INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rap-phim-ma', 'Rạp Phim Ma', 'Fear Is Coming', 'null', 'https://phimimg.com/upload/vod/20231108-1/5d6fcaa4dc91010bcf18edd6d1191314.jpg', '<p>Hồn ma Thái nổi tiếng Chiang Mai thu hút rất nhiều du khách, một nhóm du khách sau khi đến thăm rạp phim ma của hồn ma này đã phải trải qua rất nhiều hiện tươnhg siêu nhiên, và sau đó là những cái chết bí ẩn khiến chuyến du lịch Thái Lan của họ trở thành thảm họa.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Li Mengmeng","avatar":""},{"name":"Mik Thongraya","avatar":""},{"name":"Yoyo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324446);
