INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-halloween', 'Phù Thủy Halloween', 'All Hallow''s Eve', 'https://phimimg.com/upload/vod/20231108-1/b3ba5ca9fd215e63800fd1206d5570f4.jpg', 'https://phimimg.com/upload/vod/20231108-1/2a56267200dcb3b16cbaae8b2ae3afbb.jpg', '<p>Khi cô nàng Eve kỷ niệm sinh nhật 18 tuổi vào đêm Halloween, cô biết được sự thật mình là một phù thủy. Tò mò khám phá sức mạnh mới cô vô tình triệu hồi một mụ phù thủy độc ác muốn thống trị và biến cả thế giới thành nô lệ. Với bùa hộ mệnh gia truyền Eve vội vã sửa chữa đống lộn xộn cô đã gây ra trước khi đại họa xảy ra.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lexi Giovagnoli","avatar":""},{"name":"Ashley Argota","avatar":""},{"name":"John DeLuca","avatar":""},{"name":"Diane Salinger","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Dee Wallace","avatar":""},{"name":"Tracey Gold","avatar":""},{"name":"Pilot Saraceno","avatar":""},{"name":"Daniel Cooksley","avatar":""},{"name":"Kelsey Impicciche","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324446);
