INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huan-chuong-chien-thang', 'Huân Chương Chiến Thắng', 'Medal of Victory', 'https://phimimg.com/upload/vod/20231108-1/a08313d8e63bbadc5442922337b872a8.jpg', 'https://phimimg.com/upload/vod/20231108-1/5252338a6e31dc9fd575e2a5f0dd78e2.jpg', '<p>Trên đường chạy trốn sau khi vô tình vận chuyển thiết bị kích hoạt phản ứng tổng hợp hạt nhân đến Malawi, hai người lính AWOL bị nhầm là anh hùng chiến tranh và bị lôi kéo vào hoạt động chính trị của một thị trấn nhỏ.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
