INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-la-mot-gia-dinh', 'Chúng ta là một gia đình', 'We Are Family', 'https://phimimg.com/upload/vod/20231116-1/a38c8c1aec754be5c3f65029262043eb.jpg', 'https://phimimg.com/upload/vod/20231116-1/d9476a7acfab5e6010e08934ac9ae726.jpg', '<p>Chán ngán với cảnh lúc ở nhà bố, lúc ở nhà mẹ, 1 cậu bé trong gia đình kết hợp quyết định rằng bọn trẻ nên sống tại một nhà, và các ông bố bà mẹ thay phiên nhau đến thăm.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Julie Gayet","avatar":""},{"name":"Thierry Neuvic","avatar":""},{"name":"Julie Depardieu","avatar":""},{"name":"Lucien Jean-Baptiste","avatar":""},{"name":"Claudia Tagbo","avatar":""},{"name":"Philippe Katerine","avatar":""},{"name":"Chantal Ladesou","avatar":""},{"name":"Arié Elmaleh","avatar":""},{"name":"Nino Kirtadzé","avatar":""},{"name":"Caterina Murino","avatar":""},{"name":"Teïlo Azaïs","avatar":""},{"name":"Violette Guillon","avatar":""},{"name":"Lilian Dugois","avatar":""},{"name":"Luna Aglat","avatar":""},{"name":"Chann Aglat","avatar":""},{"name":"Benjamin Douba Pari","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
