INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nien-thu-giang-tran', 'Niên Thú Giáng Trần', 'Mr. Nian', 'https://phimimg.com/upload/vod/20231108-1/7646b0e55db09747f292d733371e4cc0.jpg', 'https://phimimg.com/upload/vod/20231108-1/165d3f8adb3d21b3dde053181ef8a61e.jpg', '<p>Là câu chuyện nói về xứ sở thần tiên có những con thú rất tinh nghịch trong đó chú gấu to xác là người hay thích chọc phá người khác, gần tới tết chú gấu này nhìn xuống trần gian có một cô bé đang lẻ loi và rất buồn, gì tính tình ham chơi tinh nghịch nên chú đã xuống trần gian để tìm cách làm cho cô bé này vui, đúng như người đã mong đơi sự xuất hiện của chú gấu đã khiến cho cô bé trở nên rất vui tươi khi biết người là một vị tiên trên trời, những người bạn tiên của chú gấu cũng tạo ra những tình tiết hài hước dở khóc dở cười…</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lei Jiayin","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Liu Yiwei","avatar":""},{"name":"Shen Teng","avatar":""},{"name":"Hong Tao","avatar":""},{"name":"Wang Xun","avatar":""},{"name":"Zhang Yibai","avatar":""},{"name":"Guo Tao","avatar":""},{"name":"Patrick Guo","avatar":""},{"name":"Hao Yun","avatar":""},{"name":"Xiong Naijin","avatar":""},{"name":"Xie Na","avatar":""},{"name":"Chen He","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324446);
