INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-phep-thuat', 'Những Cô Gái Phép Thuật', 'Mahoutsukai Precure! Movie: Kiseki no Henshin! Cure Mofurun!', 'https://phimimg.com/upload/vod/20231108-1/0d7fe2a934b2042b5de1c87db20468eb.jpg', 'https://phimimg.com/upload/vod/20231108-1/aaf40751ea7b2babd6c1feb60bf69e27.jpg', '<p>Phim Những Cô Gái Phép Thuật 2016: Asahina Mirai, một học sinh sắp vào học trung học, bỗng nhiên cô nhìn thấy có một vật lạ rơi từ bầu trời trong một đêm của kỳ nghỉ xuân. Hào hứng thốt lên rằng nó có thể là một phù thủy, Mirai ra đường vào sáng hôm sau với đồ chơi yêu quý của cô là gấu bông Mofurun để tìm kiếm trong công viên. Tại công viên, Mirai chứng kiến một cô gái bay vút qua đầu mình trên một cây chổi. Hồi hộp và tò mò, Mirai đặt ra cho cô gái lạ rất nhiều những câu hỏi. Cô phù thủy trẻ giới thiệu mình là Riko và giải thích rằng cô ấy đến với thế giới &quot;Không có Phép thuật&quot; để tìm kiếm một số đối tượng nhất định. Hai cô gái nhận thấy rằng họ đang đeo các mặt dây chuyền giống nhau. Trong khi đó, Batty, một thuộc hạ của Dokurokushe - Phù thuỷ của Bóng tối, xuất hiện trước mặt Mirai và Riko! Batty muốn Riko giao ra &quot;Linkle Stone Emerald&quot;, thứ mà Riko đang tìm kiếm. Để làm cho mọi thứ tồi tệ hơn, Batty sử dụng phép thuật bóng tối để tạo ra một con quái vật có tên là Yokubaru! Mirai, Riko và Mofurun cùng nắm tay. Với câu nói kỉ diệu &quot;Cure Up RaPaPa!&quot;, mặt dây chuyền của cả hai tỏa ra một ánh sáng huyền diệu trước mặt họ! Các phù thủy huyền thoại &quot;Pretty Cure&quot; được sinh ra!</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Ayaka Saito","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Mika Kikuchi","avatar":""},{"name":"Shota Yamamoto","avatar":""},{"name":"Chinami Hashimoto","avatar":""},{"name":"Makoto Ishii","avatar":""},{"name":"Aki Kanada","avatar":""},{"name":"Maya Yoshioka","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Yuuya Uchida","avatar":""},{"name":"Yoshino Ootori","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
