INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-co-gai-phep-thuat', 'Những Cô Gái Phép Thuật', 'Mahoutsukai Precure! Movie: Kiseki no Henshin! Cure Mofurun!', 'những cô gái phép thuật mahoutsukai precure! movie: kiseki no henshin! cure mofurun! rie takahashi yui horie saori hayami ayaka saito daisuke namikawa mika kikuchi shota yamamoto chinami hashimoto makoto ishii aki kanada maya yoshioka kaori nazuka yuuya uchida yoshino ootori ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-thi-tran-pineville', 'Vụ Cướp Thị Trấn Pineville', 'The Pineville Heist', 'https://phimimg.com/upload/vod/20231108-1/f27a5476d674f39d89a90c34ede6ad02.jpg', 'https://phimimg.com/upload/vod/20231108-1/92704a44ce111bbaf9af4418b1940b9e.jpg', '<p>Bộ phim Vụ Cướp Thị Trấn Pineville - Pineville Heist xoay quanh Aaron - một học sinh trung học chứng kiến một tên cướp sát hại đồng đội của mình. Trong sự hỗn loạn, Aaron bỏ trốn với túi tiền của bọn cướp. Nhưng thật không may, một trong những tên cướp đã theo dõi và truy sát cậu, buộc Aaron cùng giáo viên kịch của mình rơi vào tình thế phải chạy trốn trong chính ngôi trường của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Basil Hoffman","avatar":""},{"name":"Priscilla-Anne Forder","avatar":""},{"name":"Presley Massara","avatar":""},{"name":"Wayne V. Johnson","avatar":""},{"name":"Carl Bailey","avatar":""},{"name":"Jacob Brown","avatar":""},{"name":"Vince Groulx","avatar":""},{"name":"Darryl Dougherty","avatar":""},{"name":"Leah Rantala","avatar":""},{"name":"Dennis Dubinsky","avatar":""},{"name":"Laura Zaina","avatar":""},{"name":"Mika Polkki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324446);
