INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-hoang-da-o-trung-quoc', 'Cuộc Sống Hoang Dã Ở Trung Quốc', 'Born in China', 'https://phimimg.com/upload/vod/20231108-1/59cb07eca4d71c139732a1b236439709.jpg', 'https://phimimg.com/upload/vod/20231108-1/0d8a7b0a9beea9c1ab1d64f7ed657a59.jpg', '<p>Phim Cuộc Sống Hoang Dã Ở Trung Quốc - Born in China 2016: Bộ phim tài liệu của đạo diễn Lu Chuan nói về cuộc sống của các loài vật hoang dã được sinh ra ở Trung Quốc. Trong số những câu chuyện đó có một thiên truyện cảm động về gấu trúc mẹ giúp con mình trưởng thành; câu chuyện ly kỳ mê hoặc về một gia đình báo tuyết cố gắng chống chọi mùa đông; rồi câu chuyện trưởng thành của một chú khỉ vàng mũi hếch muốn tìm vị trí của mình trong thế giới này.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Zhou Xun","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324446);
