INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-tu-cai-nhin-dau-tien', 'Yêu em từ cái nhìn đầu tiên', 'Love O2O', 'https://phimimg.com/upload/vod/20231108-1/c2e9d0254c2370fd935343b33956c303.jpg', 'https://phimimg.com/upload/vod/20231108-1/fbaf18595fc594819275b2a182fd60e9.jpg', '<p>Được chuyển thể từ tiểu thuyết thuộc đề tài võng du của tác giả Cố Mạn. &nbsp;Nội dung xoay quanh chuyện tình từ trong game online ra ngoài đời thực của Bối Vi Vi (Angela Baby) – một hoa khôi xinh đẹp mà &quot;não không tàn&quot; cùng Tiêu Nại (Tỉnh Bách Nhiên) – chàng sinh viên khoa công nghệ thông tin tài giỏi. Mối quan hệ của họ không trắc trở, không có người thứ ba xen vào cũng không có những hiểu lầm hay xích mích...</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"AngelaBaby","avatar":""},{"name":"Jing Boran","avatar":""},{"name":"Janice Wu","avatar":""},{"name":"Tan Songyun","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Du Yuchen","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Li Xian","avatar":""},{"name":"Pang Hanchen","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Wang Zi Jie","avatar":""},{"name":"Chen Mengqin","avatar":""},{"name":"Xunzimo Liu","avatar":""},{"name":"Song Yixing","avatar":""},{"name":"Yao Kaichen","avatar":""},{"name":"Wu Yufang","avatar":""},{"name":"Cao Yi","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Li Jia Xun","avatar":""},{"name":"Zhang Zi Yu","avatar":""},{"name":"Zhang Yibai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]'