INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ma-thuat', 'Trò Ma Thuật', 'Mystic Game', 'https://phimimg.com/upload/vod/20231107-1/69120207dbbb609d61350dad7878d0a4.jpg', 'https://phimimg.com/upload/vod/20231107-1/3cebe0d83c83630cc97b080eb2a4df7b.jpg', '<p>Aleks – một anh chàng đẹp trai sát gái, tình cờ trở thành khách mời trên chương trình truyền hình chuyên về phép thuật. Tại đây chàng gặp Tanya, tình yêu của đời mình, nhưng cả hai không biết rằng hành trình để đến được bên nhau phải đối mặt với cuộc đối đầu chết chóc của hai vị pháp sư lừng danh. Từ giây phút này Aleks buộc phải tự cứu lấy mình và người yêu thoát khỏi lời nguyền lẫn trò chơi ma thuật mà hai kẻ quyền năng đã nguyền rủa anh.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Alexander Petrov","avatar":""},{"name":"Diana Pozharskaya","avatar":""},{"name":"Ekaterina Kabak","avatar":""},{"name":"Sergey Burunov","avatar":""},{"name":"Semyon Lopatin","avatar":""},{"name":"Kirill Kozakov","avatar":""},{"name":"Denis Yasik","avatar":""},{"name":"Yuliya Sules","avatar":""},{"name":"Veronika Vernadskaya","avatar":""},{"name":"Andrey Perunov","avatar":""},{"name":"Svetlana Golovina","avatar":""},{"name":"Irina Tsyvina","avatar":""},{"name":"Andrey Stoyanov","avatar":""},{"name":"Oleg Gaas","avatar":""},{"name":"Tatyana Lyalina","avatar":""},{"name":"Zhanna Og","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324446);
