INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-muoi-sac-toi', 'Năm Mươi Sắc Tối', 'Fifty Shades of Black', 'https://phimimg.com/upload/vod/20231107-1/6ead27be6cf13b4e28f0de8b327272c1.jpg', 'https://phimimg.com/upload/vod/20231107-1/2f5959f3a6f212d6c2a96a54e36d7f13.jpg', '<p>Christian Black giới thiệu sinh viên đại học nhút nhát Hannah Steale với thế giới &quot;Lãng mạn&quot; sau khi cô phỏng vấn ông cho tờ báo của mình. Mối quan hệ kinky của họ vấp ngã về phía trước mặc dù những thiếu sót của Christian với tư cách là người yêu và những trò hề của người mẹ nuôi phân biệt chủng tộc Claire, anh em eli eli và người bạn cùng thế giới của Hannah, Kateesha ..</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marlon Wayans","avatar":""},{"name":"Kali Hawk","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Florence Henderson","avatar":""},{"name":"Andrew Bachelor","avatar":""},{"name":"Jenny Zigriano","avatar":""},{"name":"Kate Miner","avatar":""},{"name":"Tina Grimm","avatar":""},{"name":"Alice Rietveld","avatar":""},{"name":"Brad Schmidt","avatar":""},{"name":"Mircea Monroe","avatar":""},{"name":"Angel Laketa Moore","avatar":""},{"name":"Elizabeth Ho","avatar":""},{"name":"Stephen Todt","avatar":""},{"name":"Cra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
