INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-song-trung', 'Kẻ Song Trùng', 'Mojave', 'https://phimimg.com/upload/vod/20231107-1/5cbb08fa4247f8fc949cc1a54a23ddd8.jpg', 'https://phimimg.com/upload/vod/20231107-1/d900d8997627087255bc51f95075682d.jpg', '<p>Phim Kẻ Song Trùng - Mojave 2015 là bộ phim tâm lý ly kỳ lấy bối cảnh sa mạc nổi tiếng ở bang California (Mỹ), với sự tham gia của hai tài tử là Garrett Hedlund và Oscar Isaac.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Garrett Hedlund","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Louise Bourgoin","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Fran Kranz","avatar":""},{"name":"Matt Jones","avatar":""},{"name":"Anna Margaret Hollyman","avatar":""},{"name":"Del Zamora","avatar":""},{"name":"Christopher Neiman","avatar":""},{"name":"Ashwin Gore","avatar":""},{"name":"Tim Soergel","avatar":""},{"name":"Kylie Rogers","avatar":""},{"name":"Frank Miranda","avatar":""},{"name":"Maria Olsen","avatar":""},{"name":"Ellen Ho","avatar":""},{"name":"Ster","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
