INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thinh-cau-quai-vat', 'Lời Thỉnh Cầu Quái Vật', 'A Monster Calls', 'https://phimimg.com/upload/vod/20231107-1/bd02da77ee23f8789e8ef1bc64300a89.jpg', 'https://phimimg.com/upload/vod/20231107-1/e7fa889e9199971b5869b3fe3e1c764c.jpg', '<p>Bộ phim là câu chuyện về Conor O’Malley (Lewis MacDougall), một cậu bé 13 tuổi phải đối mặt với nỗi sợ hãi mất đi mẹ mình (Felicity Jones), người đang bị giày vò bởi căn bệnh ung thư ác tính. Để mẹ an tâm điều trị, Conor phải chuyển tới sống cùng người bà khô khan và kĩ tính (Sigouey Weaver). Không chỉ vậy, cậu cũng thường bị bạn bè bắt nạt. Conor bắt đầu tìm cách lẩn trốn trong thế giới tưởng tượng do bản thân tạo ra.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Lewis MacDougall","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Ben Moor","avatar":""},{"name":"James Melville","avatar":""},{"name":"Oliver Steer","avatar":""},{"name":"Dominic Boyle","avatar":""},{"name":"Jennifer Lim","avatar":""},{"name":"Max Gabbay","avatar":""},{"name":"Joe Curtis","avatar":""},{"name":"Morgan Symes","avatar":""},{"name":"Max Golds","avatar":""},{"name":"Frida Palsson","avatar":""},{"name":"Wanda Opalinska","avatar":""},{"name":"Patrick Taggart","avatar":""},{"name":"Lily-Rose Aslandogdu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324446);
