INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-thinh-cau-quai-vat', 'Lời Thỉnh Cầu Quái Vật', 'A Monster Calls', 'lời thỉnh cầu quái vật a monster calls lewis macdougall sigourney weaver felicity jones toby kebbell ben moor james melville oliver steer dominic boyle jennifer lim max gabbay joe curtis morgan symes max golds frida palsson wanda opalinska patrick taggart lily-rose aslandogdu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-phai-xai-chieu', 'Yêu Là Phải Xài Chiêu', 'Crafty Love', 'https://phimimg.com/upload/vod/20231107-1/7fbebe154162270042b3330c26420286.jpg', 'https://phimimg.com/upload/vod/20231107-1/dc533e517bffa2dfb0ac67fd777f3598.jpg', '<p>Câu chuyện xoay quanh chàng Ngốc to xác nhưng tính tình như một đứa trẻ. Vì vậy, Ngốc thường xuyên bị nhóm thanh niên sống cùng khu phố chọc phá. Ngốc có một người chị gái hết mực yêu thương Ngốc. Chị sẵn sàng “ở giá” để chăm sóc cho Ngốc và luôn có mặt mỗi khi Ngốc bị ăn hiếp. Bên cạnh Ngốc còn có “anh đẹp” làm DJ - ở trọ chung nhà với chị em Ngốc. &quot;Anh đẹp” như một người anh trai luôn chịu khó nghe Ngốc tâm sự. &nbsp;Rồi đến một ngày Ngốc biết yêu. Đó là &quot;chị đẹp” - cô hàng xóm mới có vẻ ngoài mềm mại của một nữ diễn viên múa, nhưng lại rất giỏi võ. Chính cô đã giải thoát Ngốc khỏi đám thanh niên luôn gây hấn. Điều đó đã làm trái tim Ngốc xao động. &quot;Anh đẹp” đã giúp Ngốc chinh phục &quot;chị đẹp&quot; với kế hoạch “yêu là phải xài chiêu&quot;. &nbsp;Thế nhưng, cuộc gặp gỡ giữa &quot;anh đẹp&quot; và &quot;chị đẹp&quot; lại rơi vào “tình yêu sét đánh”. Phải làm sao trước tình cảnh trớ trêu này?</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"La Thành","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Khương Ngọc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
