INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-tren-hoang-dao', 'Lạc Trên Hoang Đảo', 'Robinson Crusoe', 'https://phimimg.com/upload/vod/20231114-1/b4d4811fbebd6f00445b73c0e2ce67ef.jpg', 'https://phimimg.com/upload/vod/20231114-1/7ea5858221bf11b7fa75c9b024da3f34.jpg', '<p>Trên hoang đảo nhỏ bé, một chú vẹt vui vẻ mang tên Thứ Ba chung sống hòa bình với những người bạn của mình. Dù cuộc sống tựa như thiên đường, Thứ Ba vẫn không ngừng mơ về việc khám phá thế giới bao la ngoài kia. &nbsp;Sau một trận bão, Thứ Ba tìm thấy một sinh vật lạ bị dạt vào bãi biển, đó là Robinson Crusoe. Cậu lập tức nhận ra Crusoe là tấm vé giúp mình có thể rời bỏ hòn đảo để khám phá những vùng đất mới. Ngược lại, Crusoe nhanh chóng biết rằng Thứ Ba là chìa khóa để anh có thể sinh tồn trên hoang đảo. &nbsp;Cho đến một ngày, cuộc sống của họ bị đảo lộn khi hai gã mèo hoang độc ác xuất hiện muốn thôn tính cả hòn đảo. Sát cánh bên nhau, Crusoe cùng Thứ Ba và những người bạn chống trả quyết liệt để giành lại hòn đảo yêu thương, đồng thời nhận ra sức mạnh của tình bạn đã giúp họ vượt qua mọi khó khăn như thế nào.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2016, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Ilka Bessin","avatar":""},{"name":"Dieter Hallervorden","avatar":""},{"name":"Matthias Schweighöfer","avatar":""},{"name":"Aylin Tezel","avatar":""},{"name":"Kaya Yanar","avatar":""},{"name":"Ron Allen","avatar":""},{"name":"Tommy Morgenstern","avatar":""},{"name":"Melanie Hinze","avatar":""},{"name":"Bert Franzke","avatar":""},{"name":"Tobias Lelle","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324446);
