INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cung-lop', 'Bạn Cùng Lớp', 'Dou kyu sei – Classmates', 'https://phimimg.com/upload/vod/20231114-1/dbc3e869e52703c16069b3cc9f6c9d8f.jpg', 'https://phimimg.com/upload/vod/20231114-1/58e6fdb4f9bf65ba6b902f130683359d.jpg', '<p>Rihito Sajo, người đạt điểm tuyệt đối tất cả các môn trong kỳ thi tuyển sinh trung học, và Hikaru Kusakabe, người nổi tiếng trong giới nữ sinh, hoạt động trong một ban nhạc, bắt đầu&amp;nbsp; chuyện với nhau sau khi luyện tập hợp xướng. Kusakabe tới những buổi luyện tập của Sajo, người chẳng có tí năng khiếu hát hò nào, cùng dành thời gian cho nhau, lắng nghe giọng nói của nhau, thì thầm những bài hát, dần dần hai người cứ thế yêu nhau say đắm.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kenji Nojima","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Hideo Ishikawa","avatar":""},{"name":"Yurino","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324446);
