INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nhu', 'Mồi Nhử', 'Redistributors', 'null', 'https://phimimg.com/upload/vod/20231113-1/52cd606cf1bbf580fda9eb94d1e738fd.jpg', '<p>Một cô gái PR của thành phố tiếp tục bị buộc tội làm rò rỉ thông tin từ công ty cung ứng quân sự nơi cô ấy làm việc. Bị truy đuổi bởi những người lính cũ, cô ẩn náu cùng với anh trai của mình, một thành viên của một nhóm hacker bóng tối, và phải lựa chọn giữa cuộc sống xa hoa của mình - và Những người phân phối lại.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Natan Barreto","avatar":""},{"name":"Tim Bentinck","avatar":""},{"name":"Robert Boulton","avatar":""},{"name":"Alexandra Evans","avatar":""},{"name":"Rrenford Junior Fagan","avatar":""},{"name":"Daniel Goode","avatar":""},{"name":"Isobella Hubbard","avatar":""},{"name":"Scott Joseph","avatar":""},{"name":"Andrew Kinsler","avatar":""},{"name":"Alastair Mackenzie","avatar":""},{"name":"Jeff Rawle","avatar":""},{"name":"Darrio Stangl","avatar":""},{"name":"James Allen","avatar":""},{"name":"Melody Reynolds","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
