INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-meo-duong-pho-bob', 'Chú Mèo Đường Phố Bob', 'A Street Cat Named Bob', 'https://phimimg.com/upload/vod/20231103-1/6ac6a8da45d7d3ab135972264d110366.jpg', 'https://phimimg.com/upload/vod/20231103-1/ecdd59d2ac1b132466dbcd91e4dc9bd0.jpg', '<p>Bob là chú mèo đực lông vàng đẹp đẽ, bị James Bowen bắt gặp đang rình mò ở gian trước của mái ấm mà anh tạm trú. Bob thì bị thương còn James đã trải qua cả thập kỷ sống lang thang trên phố và nhà tạm, vừa tham gia một chương trình cai nghiện để cứu vãn cuộc đời. James nát như tương, nhưng lại không thể quay lưng với Bob, sau khi anh chữa lành cho chú mèo họ trở thành một cặp đôi không thể tách rời.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Luke Treadaway","avatar":""},{"name":"Ruta Gedmintas","avatar":""},{"name":"Joanne Froggatt","avatar":""},{"name":"Anthony Stewart Head","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Beth Goddard","avatar":""},{"name":"Darren Evans","avatar":""},{"name":"Ruth Sheen","avatar":""},{"name":"Nina Wadia","avatar":""},{"name":"John Henshaw","avatar":""},{"name":"Nadine Marshall","avatar":""},{"name":"Lorraine Ashbourne","avatar":""},{"name":"Akbar Kurtha","avatar":""},{"name":"Llewella Gideon","avatar":""},{"name":"Ivana Basic","avatar":""},{"name":"Rob Jarvis","avatar":""},{"name":"Sasha D","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
