INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-ma-nhat-kieu-thai', 'Bắt Ma Nhật Kiểu Thái', 'Buppha Ratree: A Haunting in Japan', 'https://phimimg.com/upload/vod/20231103-1/02b06c8d02a7a6352a1ec8c733befa90.jpg', 'https://phimimg.com/upload/vod/20231103-1/93e903f1094a7959c5a63b0717e11a9d.jpg', '<p>Trong phim Bắt Ma Nhật Kiểu Thái 2016, một cô gái tuổi 20 vừa xinh đẹp lại giàu có, Buppha Rahtree (Rose) không thể ngờ bạn trai lại phản bội mình mà quan hệ với cô gái khác. Cô giết anh ta rồi đến Niseko – Nhật Bản và trốn trong nhà trọ Oscar Lodge. Tại đây, cô nàng gặp một ca sĩ có vẻ ngoài rất giống người yêu cũ. Tình yêu và thù hận đan xen trong trái tim Rose. Thế nhưng, cả Rose và chàng ca sĩ Nak đều không biết rằng Oscar Lodge là nơi trú ngụ của những linh hồn có trái tim tan vỡ, sự bình yên của cả hai nhanh chóng bị phá hỏng. Nak phải cầu cứu đến sự giúp đỡ của thầy trừ ma bản xứ lẫn thầy bắt ma từ Thái Lan.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Charlie Trairat","avatar":""},{"name":"Supassra Thanachat","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""},{"name":"Yok Teeranitayatarn","avatar":""},{"name":"Aphichan Chaleumchainuwong","avatar":""},{"name":"Triwarat Chutiwatkajornchai","avatar":""},{"name":"Thana Vichayasuranan","avatar":""},{"name":"Chermarn Boonyasak","avatar":""},{"name":"Apa Bhavilai","avatar":""},{"name":"Navin Yavapolkul","avatar":""},{"name":"Adirek Watleela","avatar":""},{"name":"Kiattisak Udomnak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324446);
