INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xe-den-dui', 'Chuyến Xe Đen Đủi', 'Godspeed', 'https://phimimg.com/upload/vod/20231103-1/490412923e23bbca252acec7cb50f552.jpg', 'https://phimimg.com/upload/vod/20231103-1/17d25b144537df43aa31b6837864ab6b.jpg', '<p>Phim Chuyến Xe Đen Đủi - Godspeed 2016: xoay quanh chuyến đi của một ông tài xế lái taxi nghèo và một tên buôn ma túy đến một nơi xa xôi hẻo lánh. Chỉ vì kiếm thêm chút tiền mà ông tài xế đâu ngờ đó là chuyến đi định mệnh của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Michael Hui","avatar":""},{"name":"Na-Do","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Matt Wu","avatar":""},{"name":"Tsung-Hua Tou","avatar":""},{"name":"Yi-Wen Chen","avatar":""},{"name":"Vincent Liang","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Jag Huang","avatar":""},{"name":"Lin Mei-shiu","avatar":""},{"name":"Chen Yu-hsun","avatar":""},{"name":"Cres Chuang","avatar":""},{"name":"Tao Yu Lin","avatar":""},{"name":"King Shih-Chieh","avatar":""},{"name":"Chen Heng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
