INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-duong-pho', 'Nữ thần đường phố', 'Divines', 'https://phimimg.com/upload/vod/20231103-1/eabb81bcbdeeda5ddfa1df24b176ba91.jpg', 'https://phimimg.com/upload/vod/20231103-1/ef59ca06a2f72b8f65002a499a56d16f.jpg', '<p>Dounia ranh mãnh và cô bạn thân quyết làm giàu bằng con đường mạo hiểm: theo chân một dân anh chị buôn bán ma túy.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Oulaya Amamra","avatar":""},{"name":"Déborah Lukumuena","avatar":""},{"name":"Kévin Mischel","avatar":""},{"name":"Jisca Kalvanda","avatar":""},{"name":"Yasin Houicha","avatar":""},{"name":"Majdouline Idrissi","avatar":""},{"name":"Farid Larbi","avatar":""},{"name":"Bass Dhem","avatar":""},{"name":"Maryama Soumare","avatar":""},{"name":"Wilfried Romoli","avatar":""},{"name":"Mohamed Ourdache","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
