INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hoi-thu-hai', 'Cơ Hội Thứ Hai', 'Ikinci Şans (Second Chance)', 'https://phimimg.com/upload/vod/20231103-1/9c1451e1eeb34f4907077dd5b47b15cb.jpg', 'https://phimimg.com/upload/vod/20231103-1/86161a140ed9fc7e3da51b3691b54af1.jpg', '<p>Con đường của hai con người cô đơn đối lập nhau ngang nhau. Một người là một phụ nữ rất xinh đẹp, Yasemin, là giáo viên dạy toán, và người kia là Cemal, một người sành ăn có sức lôi cuốn, chủ nhà hàng Cemal Et. Cemal là một người đàn ông hướng ngoại, vô tư, cố gắng thoát khỏi quá khứ của mình. Mặt khác, Yasemin là một người phụ nữ nhút nhát, hay bảo vệ, cố gắng chữa lành vết thương của sự lựa chọn sai lầm mà cô ấy đã thực hiện trong quá khứ, người có vỏ bọc dày, người quyết định mọi thứ cô ấy sẽ sống bằng cách sử dụng các phép tính toán học. Cuộc gặp gỡ của hai người thậm chí không thèm nhìn mặt nhau trong cuộc sống bình thường, đầu tiên sẽ bắt đầu bằng những trận đấu khẩu, sau đó chuyển thành tình yêu và rồi nhấn chìm chúng ta trong nỗi buồn. Điểm chung của cả hai là cả hai đều cần cơ hội thứ hai. Khi tìm hiểu sâu hơn về cả hai, chúng ta thấy rằng đó sẽ không phải là một tình yêu dễ dàng.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Özcan Deniz","avatar":""},{"name":"Nurgül Yeşilçay","avatar":""},{"name":"Afra Saraçoğlu","avatar":""},{"name":"Mesut Can Tomay","avatar":""},{"name":"Berrin Arısoy","avatar":""},{"name":"Fulya Şirin","avatar":""},{"name":"Anıl Altınöz","avatar":""},{"name":"Aybike Turan","avatar":""},{"name":"Duygu Çelebi","avatar":""},{"name":"Füsun Erbulak","avatar":""},{"name":"Kaan Yalçın","avatar":""},{"name":"Ömer Akgüllü","avatar":""},{"name":"Özge Kepkebir","avatar":""},{"name":"Dana Abed","avatar":""},{"name":"Murat Ayaz","avatar":""},{"name":"Nazlı Çetinel","avatar":""},{"name":"Aydin Erek","avatar":""},{"name":"Suğdem Gözalır","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324446);
