INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-nhan-vat-thu', 'Các Nhân Vật Thú', 'CHARACTERz', 'https://phimimg.com/upload/vod/20231111-1/a70c8fbd8325e9d44767eb4d9cdf3aed.jpg', 'https://phimimg.com/upload/vod/20231111-1/68f88f8778fd055a05d7f5a2fdd134a2.jpg', '<p>Tucker Ostrowski vừa có một công việc mùa hè tại Công viên giải trí thị trấn Old Old Fun Town là linh vật, Hoppy the Kangaroo. Anh ấy là một thiếu niên thông minh, đang cố gắng tiết kiệm đủ tiền để đi học đại học. Con Kangaroo Krew của anh ta bao gồm Thuyền trưởng Jack Hay-Parrot, được mặc bởi người bạn thân mới của anh ta JERRY; Bowzer the Bulldog được mặc bởi một cô gái đáng yêu SAM; và Paws chú gấu Bắc cực màu hồng được đeo bởi biệt danh là Sweatyật STU. Mọi thứ nhanh chóng trở nên phức tạp khi anh ta yêu Sam, và, khi Kangaroo Krew bị buộc tội sai trái về một vụ án tội ác tốn kém. Tương lai Tucker sườn đang gặp nguy hiểm trừ khi anh ta có thể tìm ra ai đã thiết lập CHARACTERz!</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mitchel Musso","avatar":""},{"name":"Walt Willey","avatar":""},{"name":"Miles D","avatar":""},{"name":"Marc Musso","avatar":""},{"name":"Ken Osmond","avatar":""},{"name":"Isaac C. Singleton Jr.","avatar":""},{"name":"Michael Winslow","avatar":""},{"name":"Felix Silla","avatar":""},{"name":"Ana Marina Eligio","avatar":""},{"name":"Arian Ash","avatar":""},{"name":"Denna Beena","avatar":""},{"name":"Patty Bender","avatar":""},{"name":"Justin Bowen","avatar":""},{"name":"Oriana Bustamante","avatar":""},{"name":"Mike Carr","avatar":""},{"name":"Chloe Cleghorn","avatar":""},{"name":"Amber Crews","avatar":""},{"name":"Evan Huit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324446);
