INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-chet-2', 'Vùng Đất Chết 2', 'The Stakelander - Stake Land 2', 'https://phimimg.com/upload/vod/20231102-1/86947e172069fcf1a546346c3686a448.jpg', 'https://phimimg.com/upload/vod/20231102-1/f8866b7401a828020d75c0e888c60890.jpg', '<p>Cuộc sống yên bình của Martin bổng đảo lộn khi một nhóm ma cà rồng mới tìm đến vùng đất thiên đường anh đang sống và giết chết vợ con anh. Để trả thù, anh buộc phải quay lại lãnh địa thây ma để cầu viện sự giúp đỡ của người thợ săn ma cà rồng từng hộ tống anh đến miền đất hứa nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Connor Paolo","avatar":""},{"name":"Nick Damici","avatar":""},{"name":"Laura Abramsen","avatar":""},{"name":"A.C. Peterson","avatar":""},{"name":"Steven Williams","avatar":""},{"name":"Bonnie Dennison","avatar":""},{"name":"Kristina Hughes","avatar":""},{"name":"Zane Clifford","avatar":""},{"name":"Nicole Garies","avatar":""},{"name":"Blaine Hart","avatar":""},{"name":"Kathryn Bracht","avatar":""},{"name":"Alex Arsenault","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Dylan Sthamann","avatar":""},{"name":"Tim Lynchuk","avatar":""},{"name":"Josh Strait","avatar":""},{"name":"Jaime Bird","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324446);
