INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-con-bao', 'Sau Cơn Bão', 'After the Storm', 'https://phimimg.com/upload/vod/20231102-1/12bcfc603d52108308440935b564cec9.jpg', 'https://phimimg.com/upload/vod/20231102-1/e2969eb5de18f5ddb45283432e5a1a84.jpg', '<p>Ryota là một nhà văn từng giành được giải thưởng lớn trong sự nghiệp viết sách của mình. Nhưng đó đã là câu chuyện của 15 năm trước. Hiện tại, anh đang kiếm sống bằng nghề thám tử tư, cái nghề mà có lẽ chẳng thể gọi là “hái ra tiền” khi mà cứ kiếm được bao nhiêu, anh lại ném chúng vào các trò cá cược. Vì lối sống “đến bản thân mình còn không lo nổi” này mà anh đã bị vợ ly dị và mỗi tháng chỉ được phép gặp cậu con trai Shingo một lần. Nhưng trước khi mọi chuyện trở nên quá muộn, Ryota cố gắng khắc phục và sửa chữa những lỗi lầm của mình. Cho tới một ngày nọ, khi một cơn bão ập đến.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Abe","avatar":""},{"name":"Kirin Kiki","avatar":""},{"name":"Yoko Maki","avatar":""},{"name":"Taiyo Yoshizawa","avatar":""},{"name":"Satomi Kobayashi","avatar":""},{"name":"Sosuke Ikematsu","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Isao Hashizume","avatar":""},{"name":"Kanji Furutachi","avatar":""},{"name":"Shono Hayama","avatar":""},{"name":"Aju Makita","avatar":""},{"name":"Izumi Matsuoka","avatar":""},{"name":"Mickey Curtis","avatar":""},{"name":"Rie Minemura","avatar":""},{"name":"Yuri Nakamura","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Kazuya Takahashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
