INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-het-giua-troi-xanh', 'Tiếng Hét Giữa Trời Xanh', 'Yell For The Blue Sky', 'https://phimimg.com/upload/vod/20231110-1/5567d3d2d13c13b352779f2e7e0d2db9.jpg', 'https://phimimg.com/upload/vod/20231110-1/ba0f2ccaeff0ba50b54e76d4f7c7bab8.jpg', '<p>Phim Tiếng Hét Giữa Trời Xanh - Yell For The Blue Sky 2016: Xoay quanh nữ sinh trung học Ono Tsubasa, một cô gái thầm nuôi dưỡng ước mơ trở thành tay trống của dàn nhạc cổ vũ sau một lần theo dõi tại trận bóng chày trường trung học Shirato. Để được trở thành tay trống cừ khôi ấy, Tsubasa quyết định thi vào Shirato. Tại đó, cô gặp gỡ Daisuke Yamada- cậu bạn catcher (bắt bóng) của đội bóng chày.</p>', 'Full', 1, 'single', 'completed', 26, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tao Tsuchiya","avatar":""},{"name":"Ryoma Takeuchi","avatar":""},{"name":"Shono Hayama","avatar":""},{"name":"Mirai Shida","avatar":""},{"name":"Arata Horii","avatar":""},{"name":"Fujiko Kojima","avatar":""},{"name":"Airi Matsui","avatar":""},{"name":"Yuna Taira","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Juri Ueno","avatar":""},{"name":"Eri Ikeda","avatar":""},{"name":"Honoka Matsumoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
