INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-bat-coc-di-thuong', 'Vụ Bắt Cóc Dị Thường', 'Paranormal Abduction', 'null', 'https://phimimg.com/upload/vod/20231110-1/2466634814bb62602b6f42e3631e7c17.jpg', '<p>Một phụ nữ trẻ sống sót sau một cuộc tấn công dữ dội. Cô cố gắng thu thập những chứng cứ, manh mối và những điểm tương đồng của các vụ giết người hàng loạt đang xảy ra trong thời gian gần đây để quyết tâm tìm ra thủ phạm. Trong lúc đó cô không ngờ mình chính là nạn nhân tiếp theo của cuộc bắt cóc dị thường này.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edward Furlong","avatar":""},{"name":"Heather McComb","avatar":""},{"name":"Gbenga Akinnagbe","avatar":""},{"name":"Vail Bloom","avatar":""},{"name":"Kate Nauta","avatar":""},{"name":"Sandra Algood","avatar":""},{"name":"Lyle Brocato","avatar":""},{"name":"Hazel D''Jan","avatar":""},{"name":"Olga Wilhelmine","avatar":""},{"name":"Nick Gomez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
