INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-ma', 'Cậu Bé Ma', 'The Boy', 'https://phimimg.com/upload/vod/20231102-1/44e3278a01f33019c8004338c091e83c.jpg', 'https://phimimg.com/upload/vod/20231102-1/025c635a8d28f97f67a8b34991a1d20a.jpg', '<p>Được một cặp đôi thuê để chăm sóc cho con trai họ, cô bảo mẫu choáng váng khi biết rằng đứa bé thật ra là con búp bê mà cặp đôi nọ đối xử như con người.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lauren Cohan","avatar":""},{"name":"Rupert Evans","avatar":""},{"name":"James Russell","avatar":""},{"name":"Jim Norton","avatar":""},{"name":"Diana Hardcastle","avatar":""},{"name":"Ben Robson","avatar":""},{"name":"Jett Klyne","avatar":""},{"name":"Lily Pater","avatar":""},{"name":"Stephanie Lemelin","avatar":""},{"name":"Matthew Walker","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324446);
