INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vay-ham-jadotville', 'Vây Hãm Jadotville', 'The Siege of Jadotville', 'https://phimimg.com/upload/vod/20231102-1/fda7032d026e7437837d94225af29ae1.jpg', 'https://phimimg.com/upload/vod/20231102-1/430ae5aa99f72c059d8c0afc70fbc582.jpg', '<p>Phim Vây Hãm Jadotville - The Siege Of Jadotville 2016: Quân tình nguyện Liên Hiệp Quốc bị lực lượng quân đội của Katangese-Congo tấn công vào năm 1961. Lực lượng gìn giữ hòa bình Ireland của Liên Hiệp Quốc với những trang bị vũ khí hạng nhẹ đã bị bao vây tại thị trấn Jadotville trong sáu ngày đêm kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Jamie Dornan","avatar":""},{"name":"Guillaume Canet","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Jason O''Mara","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Mikael Persbrandt","avatar":""},{"name":"Danny Sapani","avatar":""},{"name":"Fionn O''Shea","avatar":""},{"name":"Fiona Glascott","avatar":""},{"name":"Emmanuelle Seigner","avatar":""},{"name":"Conor Quinlan","avatar":""},{"name":"Sam Keeley","avatar":""},{"name":"Conor MacNeill","avatar":""},{"name":"Luc Van Gunderbeeck","avatar":""},{"name":"Jordan Mifsud","avatar":""},{"name":"Charl","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
