INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-rung-ron', 'Kế Hoạch Rùng Rợn', 'Misfortune', 'https://phimimg.com/upload/vod/20231102-1/593f75e21c2919c1f0b7b8ae18ae2ed5.jpg', 'https://phimimg.com/upload/vod/20231102-1/50edbebc7871fde802c2563503598b30.jpg', '<p>Khi một người đàn ông trẻ tuổi, bất chấp vận may của mình, biết về sự ân xá của kẻ giết cha mình, nó bắt đầu một cuộc rượt đuổi mèo và chuột qua sa mạc thù địch, tìm kiếm tài sản thừa kế bị che giấu của gia đình.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Desmond Devenish","avatar":""},{"name":"Jenna Kanell","avatar":""},{"name":"Xander Bailey","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"Steve Earle","avatar":""},{"name":"Nick Mancuso","avatar":""},{"name":"Vinicius Zorin-Machado","avatar":""},{"name":"Carl Bailey","avatar":""},{"name":"Wilson Ramirez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
