INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-cuoc-phieu-luu-anh-sao', 'Barbie: Cuộc Phiêu Lưu Ánh Sao', 'Barbie: Star Light Adventure', 'https://phimimg.com/upload/vod/20231101-1/fc1ec1f757c78a76e48ea61f8b9fd1b8.jpg', 'https://phimimg.com/upload/vod/20231101-1/673c36e53bb923d1e730dc8d8af6a309.jpg', '<p>Barbie, công chúa trượt ván của vũ trụ, phải hợp sức với một đội gồm những người bạn mới tài năng để cứu các vì sao khỏi bị vụt tắt.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Erica Lindbeck","avatar":""},{"name":"Robbie Daymond","avatar":""},{"name":"Kimberly Woods","avatar":""},{"name":"Sarah Anne Williams","avatar":""},{"name":"Michael Chandler","avatar":""},{"name":"Dwight Schultz","avatar":""},{"name":"Ben Bledsoe","avatar":""},{"name":"Jonathan Lipow","avatar":""},{"name":"Lucien Dodge","avatar":""},{"name":"Laura Post","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324446);
