INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-tinh-yeu', 'Tìm Kiếm Tình Yêu', 'Cup of Love', 'https://phimimg.com/upload/vod/20231109-1/d11f1c9cef5282493e6345dc594c9373.jpg', 'https://phimimg.com/upload/vod/20231109-1/0bb3462427219cc54f731dbd89513c8d.jpg', '<p>Zoe Walker là một nhà khoa học thực phẩm được cử đến Colombia để thiết kế một hương vị cà phê hấp dẫn thế hệ thiên niên kỷ. Tại làng Salento, Zoe gặp Diego Valdez, một chủ đồn điền địa phương lúc đầu không muốn làm việc với cô, nhưng cho phép Zoe sử dụng hạt cà phê của mình miễn là cô giúp anh thu hoạch lần cuối. Khi Zoe dành thời gian làm việc trên đất với Diego, mối tình lãng mạn bắt đầu nảy nở mặc dù nguồn gốc rất khác nhau của họ.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Hutchison","avatar":""},{"name":"Nikolás Rincón","avatar":""},{"name":"Taliana Vargas","avatar":""},{"name":"Constanza Duque","avatar":""},{"name":"Julián Arango","avatar":""},{"name":"David Ojalvo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324446);
