INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-gang-to', 'Cuộc Chiến Găng Tơ', 'Teraa Surroor', 'https://phimimg.com/upload/vod/20231109-1/ccd8f14c58d8acf3bcd9c5b0d41adda7.jpg', 'https://phimimg.com/upload/vod/20231109-1/6529dc61dd0995e62213ad37f603b980.jpg', '<p>Phim Cuộc Chiến Găng Tơ - Teraa Surroor 2016: Tara Wadia (Farah Karimaee), một cô ca sĩ và là bạn gái của tay găng tơ Raghu (Himesh Reshammiya) sống cùng người mẹ của mình (Shernaz Patel). Tara bị bắt ở Dublin vì tội tàng trữ thuốc phiện. Tara đã gọi cầu cứu Raghu và anh đang truy tìm Anirudh Brahman, một kẻ lạ mặt mà Tara vô tình quen trên Facebook và mời Tara đến Ireland.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Himesh Reshammiya","avatar":""},{"name":"Farah Karimi","avatar":""},{"name":"Monica Dogra","avatar":""},{"name":"Naseeruddin Shah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
