INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-doi', 'Hạm Đội', 'KanColle: The Movie', 'https://phimimg.com/upload/vod/20231101-1/244828084204fd9e757a6b92af7d3eb1.jpg', 'https://phimimg.com/upload/vod/20231101-1/70f50628920b2207c2a204e47b195d41.jpg', '<p>Phim Hạm Đội - KanColle: The Movie 2016: Chuyển thể từ video game. Câu chuyện tiếp tục về trận chiến giữa thế lực Abyssal bí hiểm với “Hạm đội biển sâu” đến từ lòng đại dương với những nữ hạm vốn là linh hồn của những chiến hạm đã hi sinh trong chiến tranh lại một lần nữa được bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sumire Uesaka","avatar":""},{"name":"Saki Fujita","avatar":""},{"name":"Yuka Iguchi","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Iori Nomizu","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Tanibe  Yumi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324446);
