INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-thieu-van', 'Hỏa Thiêu Vân', 'For A Few Bullets', 'https://phimimg.com/upload/vod/20231101-1/d308e962b3a7c2507146d58f42a4c76e.jpg', 'https://phimimg.com/upload/vod/20231101-1/bba10557d9b47f768a00f00f49ff0d43.jpg', '<p>Phim Hỏa Thiêu Vân - For A Few Bullets 2016: Tên lừa đảo chợ búa Tiểu Trang (Lâm Canh Tân đóng), thông minh lại hay làm trò ma lanh, nhờ đôi bàn tay nhanh nhạy mà bôn tẩu giang hồ, chẳng ngờ lúc đang làm trò mèo lại bị tay súng Lý Nhược Vân (Trương Tịnh Sơ đóng) uy hiếp, ép cùng lên đường tìm ngọc tỷ bảo vật quốc gia. Trên đường đi, 2 người âm thầm phối hợp, cùng vợ chồng lão ngoan đồng Thạch Phật (Đằng Cách Nhĩ đóng) và Kim Tam Nương (Lưu Hiểu Khánh đóng) hợp thành &quot;liên minh tìm bảo vật&quot;, đấu trí đấu dũng với kẻ ham lùng kho báu Tống Trịnh Chi (Cẩm Vinh đóng), tạo thành câu chuyện tìm bảo vật rất hài hước.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lin Gengxin","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Liu Xiaoqing","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Shi Yufei","avatar":""},{"name":"Vivian Dawson","avatar":""},{"name":"Han Qiuchi","avatar":""},{"name":"Asano Nagahide","avatar":""},{"name":"Han Pujun","avatar":""},{"name":"Wen Qi","avatar":""},{"name":"Andrey Kharybin","avatar":""},{"name":"Maria Makarenko","avatar":""},{"name":"George Christopher","avatar":""},{"name":"James Alofs","avatar":""},{"name":"Guo Dongdong","avatar":""},{"name":"Kerry Berry Brogan","avatar":""},{"name":"Anastasiya Sedikova","avatar":""},{"name":"Ten","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e91