INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-hoang', 'Vùng Đất Hoang', 'Tierra Yerma', 'https://phimimg.com/upload/vod/20231101-1/9213af5afd40fa1875dc71fc6e042a5e.jpg', 'https://phimimg.com/upload/vod/20231101-1/368ec313ba64a333ccc2aaba7cf355f0.jpg', '<p>Một bộ phim kinh dị / kinh dị dài tập lấy bối cảnh London hậu tận thế với sự tham gia của Daniel Dyer, Tamer Hassan, Simon Phillips, Ronan Vibert, Sebastian Street, Daisy Head, Rita Ramnani và John Mawson. Bộ phim kể câu chuyện về một sự kiện thảm khốc chỉ còn lại 7 người trên trái đất và cuộc đấu tranh tuyệt vọng của họ để hiểu các sự kiện khi họ bị săn lùng bởi một thế lực ma quỷ.</p>', 'Full', 1, 'single', 'completed', 21, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Julio Milostich","avatar":""},{"name":"Erto Pantoja","avatar":""},{"name":"Heidrun Breier","avatar":""},{"name":"Ignacio Varas","avatar":""},{"name":"Cristián Heinsen Pereira","avatar":""},{"name":"Ian Davidson","avatar":""},{"name":"Paul Dissington","avatar":""},{"name":"Ali Alzahid","avatar":""},{"name":"Lismer Choque Alvarez","avatar":""},{"name":"Yosmar Aguilar Jiménez","avatar":""},{"name":"Telma Vásquez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
