INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-nu-the-ky-20', 'Phụ Nữ Thế Kỷ 20', '20th Century Women', 'https://phimimg.com/upload/vod/20231101-1/d9effdfc733b80ad2f64d871f4e1d881.jpg', 'https://phimimg.com/upload/vod/20231101-1/75e74dc87835d9c12ddacc0e66f22cf9.jpg', '<p>Phim 20th Century Women 2016, phim lấy bối cảnh năm 1979 tại Santa Barbara, California, Mỹ, người phụ nữ Dorothea (Annette Benning) gặp nhiều khó khăn trong việc nuôi nấng con trai. Bà quyết định cầu viện hai cô gái trẻ là Abbie (Greta Gerwig) và Julie (Elle Fanning) giúp đỡ. Đạo diễn kiêm biên kịch Mike Mills tiết lộ ông lấy cảm hứng từ mẹ, những người chị và chính quãng thời gian tuổi dậy thì của mình để tạo ra các nhân vật và toàn bộ 20th Century Women.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Annette Bening","avatar":""},{"name":"Lucas Jade Zumann","avatar":""},{"name":"Greta Gerwig","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Alison Elliott","avatar":""},{"name":"Thea Gill","avatar":""},{"name":"Vitaly Andrew LeBeau","avatar":""},{"name":"Olivia Hone","avatar":""},{"name":"Waleed Zuaiter","avatar":""},{"name":"Curran Walters","avatar":""},{"name":"Darrell Britt-Gibson","avatar":""},{"name":"Alia Shawkat","avatar":""},{"name":"Nathalie Love","avatar":""},{"name":"Cameron Protzman","avatar":""},{"name":"Victoria Bruno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
