INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('na-tra-phieu-luu-ky', 'Na Tra Phiêu Lưu Ký', 'I Am NeZha', 'https://phimimg.com/upload/vod/20231101-1/def8dfe9dfaf9eca5068fb1e701c8332.jpg', 'https://phimimg.com/upload/vod/20231101-1/bf0e9fccdfbb9c7b2278fd351b247ea6.jpg', '<p>Là câu chuyện về Huyền Thoại tam thái tử Na Tra.Chuyện kể sau khi được sinh ra, Na Tra được xem như một &quot;thảm họa&quot; vì cậu gây rắc rối khiến ai cũng ngao ngán. Trong lúc bỏ đi, cậu tình cờ được Thái Ất Trân Nhân nhận làm đồ đệ. Lúc này ở Đông Hải, Dạ Xoa âm mưu hãm hại con gái của long vương, vu oan Na Tra, rồi gây nên một trận chiến lớn. Na Tra sẽ đối mặt với chuyện này ra sao?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tao Dian","avatar":""},{"name":"Han Jiao Jiao","avatar":""},{"name":"Liu Yao","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Liang Zou","avatar":""},{"name":"Dawei Liang","avatar":""},{"name":"Yao Yanze","avatar":""},{"name":"Xianglong Meng","avatar":""},{"name":"Wang Baichao","avatar":""},{"name":"Yi Hu","avatar":""},{"name":"Wu Yifei","avatar":""},{"name":"Zhang Huanzhao","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324446);
