INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-ve-si-ong-noi-toi-la-dac-cong', 'Lão Vệ Sĩ - Ông Nội Tôi Là Đặc Công', 'My Beloved Bodyguard', 'https://phimimg.com/upload/vod/20231101-1/8422dfc9c42baae91fb8404a7dc33450.jpg', 'https://phimimg.com/upload/vod/20231101-1/3fa322cc91b91e7866e154356619aa07.jpg', '<p>Phim xoay quanh câu chuyện báo thù của chàng trai giỏi võ (Nhạc Tùng) đang trên đường tìm kiếm vị sư huynh của mình Lý Giang (Thích Hành Vũ) vô tình trở thành vệ sĩ cho một thiên kim tiểu thư Lý Phỉ Phỉ (Lý Vũ Phỉ), làm những chuyện hết sức điên rồ.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Jacqueline Chan","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Feng Jia-Yi","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Du Yiheng","avatar":""},{"name":"Mou Xing","avatar":""},{"name":"Zhu Yuchen","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Tsui Hark","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Dean Shek","avatar":""},{"name":"William Feng","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Yuen Qiu","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Yuen Bo","avatar":""},{"name":"Tian Liang","avatar":""},{"name":"Tomer Oz","avatar":""},{"name":"Lai Xi","avatar":""},{"name":"Jonathan Kos-Read","avatar":""},{"name":"Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324446);
