INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-chet-choc', 'Trò Chết Chóc', 'The Belko Experiment', 'https://phimimg.com/upload/vod/20231101-1/ead414e28db4f0005dacfe5cdca22158.jpg', 'https://phimimg.com/upload/vod/20231101-1/4f44c18f462df6513d93e15a292cec71.jpg', '<p>Một ngày bình thường tại văn phòng trở thành một nhiệm vụ kinh hoàng để tồn tại khi 80 nhân viên (John Gallagher Jr., Tony Goldwyn, Adria Arjona) tại Belko Corp. ở Bogotá, Colombia, biết rằng họ là những con tốt trong một trò chơi chết chóc. Bị mắc kẹt bên trong tòa nhà của họ, một giọng nói qua hệ thống liên lạc nội bộ nói với các nhân viên sợ hãi rằng hai công nhân phải bị giết trong vòng 30 phút. Khi một tối hậu thư khác xuất hiện, bạn bè trở thành kẻ thù và các liên minh mới hình thành, vì cuối cùng chỉ có kẻ mạnh nhất còn sống.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Gallagher Jr.","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Melonie Diaz","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Owain Yeoman","avatar":""},{"name":"Sean Gunn","avatar":""},{"name":"Brent Sexton","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"David Del Rio","avatar":""},{"name":"Rusty Schwimmer","avatar":""},{"name":"Gail Bean","avatar":""},{"name":"James Earl","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Valentine Miele","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
