INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-dia-dao', 'Bí Mật Địa Đạo', 'Chongqing Hot Pot', 'https://phimimg.com/upload/vod/20231101-1/5a1431c5db3e18b2945e6dfb07f05de7.jpg', 'https://phimimg.com/upload/vod/20231101-1/a0b3f33b1d63c85ed62132febbeebc24.jpg', '<p>Phim Bí Mật Địa Đạo - Chongqing Hot Pot 2016: thuộc thể loại hình sự tội phạm của đạo diễn Dương Khánh với sự góp mặt của Trần Khôn, Bạch Bách Hà, Tần Hạo. Nhóm bạn thân Lưu Ba hợp tác mở quán lẩu… dưới lòng đất. Trong quá trình mở rộng quán, họ bất ngờ phát hiện một kho bạc đầy ắp tiền. Tiểu Huệ - bạn học cũ của nhóm, vô tình bị cuốn vào câu chuyện tranh đoạt tiền bạc, khi mà băng cướp đeo mặt nạ xuất hiện uy hiếp tính mạng của cô.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Kun","avatar":""},{"name":"Bai Baihe","avatar":""},{"name":"Qin Hao","avatar":""},{"name":"Yu Entai","avatar":""},{"name":"Wang Yanlin","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Zhang Yichi","avatar":""},{"name":"Chen Nuo","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Ren Min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324446);
