INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-vs-teen-titans', 'Liên Minh Công Lý vs. Teen Titans', 'Justice League vs. Teen Titans', 'https://phimimg.com/upload/vod/20231030-1/02b0654c90762781c83da8b0719b7eec.jpg', 'https://phimimg.com/upload/vod/20231030-1/ea15ae7bc3b1fec9dbd767d65d54fb35.jpg', '<p>Robin được Batman cử đến làm việc với Teen Titans sau khi hành vi bất ổn của anh làm hỏng nhiệm vụ của Justice League. Các Titan sau đó phải đứng lên đối mặt với Trigon sau khi hắn sở hữu Liên minh và đe dọa chinh phục thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stuart Allan","avatar":""},{"name":"Taissa Farmiga","avatar":""},{"name":"Jason O''Mara","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Sean Maher","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Jake T. Austin","avatar":""},{"name":"Brandon Soo Hoo","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Shemar Moore","avatar":""},{"name":"Laura Bailey","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Terrence ''T.C.'' Carson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
