INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-sat-thu', 'Liên Minh Sát Thủ', 'Allied', 'https://phimimg.com/upload/vod/20231030-1/7f850841bc072765a117abe5ba6f4824.jpg', 'https://phimimg.com/upload/vod/20231030-1/968d39bfc2e6e258fb8eb200232b9d22.jpg', '<p>Bộ phim ly kỳ hấp dẫn nhất năm đến từ đạo diễn của Forrest Gump và Cast Away. Khi sĩ quan tình báo Max Vatan nghe tin có thể vợ mình tiếp tay cho kẻ thù, anh chỉ có 72 giờ để chứng minh cô vô tội và cứu gia đình mình trước khi anh bị buộc phải làm một việc khủng khiếp.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Daniel Betts","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Camille Cottin","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Thierry Frémont","avatar":""},{"name":"Vincent Ebrahim","avatar":""},{"name":"Michael McKell","avatar":""},{"name":"Vincent Latorre","avatar":""},{"name":"Fleur Poad","avatar":""},{"name":"Miryam Hayward","avatar":""},{"name":"Iselle Rifat","avatar":""},{"name":"Aysha Kaneyo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324446);
