INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-gian-khoan-2016', 'Thảm Họa Giàn Khoan', 'Deepwater Horizon', 'https://phimimg.com/upload/vod/20231029-1/c8ce6b45223e78d705268397bd64bc83.jpg', 'https://phimimg.com/upload/vod/20231029-1/cc456e0cbbbf5997b5bdfea630c07056.jpg', '<p>Mở đầu bộ phim nhẹ nhàng với những cảnh quay xung quanh gia đình của người đàn ông, có tên là Mike (Mark Wahlberg thủ vai). Anh làm việc cho một công ty lớn có hàng triệu bộ phận chuyển động. Và công việc chủ yếu của anh cùng đồng nghiệp là nỗ lực hết mình để các bộ phận máy móc đó hoạt động thật tốt và kiếm về lợi nhuận. Nhưng thật không may, tai nạn bất chợt ập đến. Thứ dầu “quái vật” ấy đã khiến giàn khoan bốc cháy nghi ngút và kể từ đây, câu chuyện phim bắt đầu trở nên dữ dội, khốc liệt hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 23, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Dylan O''Brien","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"David Maldonado","avatar":""},{"name":"Henry Frost","avatar":""},{"name":"Jeremy Sande","avatar":""},{"name":"Brad Leland","avatar":""},{"name":"Douglas M. Griffin","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Chris Ashworth","avatar":""},{"name":"Rob Steinberg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324446);
