INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-6-truy-tim-noi-gian', 'Lính Bắn Tỉa 6: Truy Tìm Nội Gián', 'Sniper: Ghost Shooter', 'https://phimimg.com/upload/vod/20231030-1/3698aed83f3b8501b27d24e4bd5e9780.jpg', 'https://phimimg.com/upload/vod/20231030-1/9ddbb99a4d60acf6f9a5e9e5430cc36b.jpg', '<p>Các tay súng bắn tỉa ưu tú Brandon Beckett và Richard Miller đang chiến đấu với những kẻ cực đoan ở Trung Đông khi Đại tá giao cho họ một nhiệm vụ mới: bảo vệ đường ống dẫn khí đốt trải dài từ Cộng hòa Georgia đến Tây Âu khỏi những kẻ cực đoan háo hức đưa ra tuyên bố chính trị. Nhưng khi các cuộc giao tranh với kẻ thù dẫn đến việc lính bắn tỉa của Mỹ bị giết bởi một tay súng ma khóa vào vị trí chính xác của họ, người ta nghi ngờ có vi phạm an ninh. Những ngón tay nhọn và đường chiến đấu được vẽ ra, tất cả đều dẫn đến cao trào bùng nổ.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Collins","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Ravil Isyanov","avatar":""},{"name":"Stephanie Vogt","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Presciliana Esparolini","avatar":""},{"name":"Ene Frost","avatar":""},{"name":"Dominic Mafham","avatar":""},{"name":"Nigel Barber","avatar":""},{"name":"Naveed Choudhry","avatar":""},{"name":"Jade Ogugua","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Vladimir Kolev","avatar":""},{"name":"Mike Straub","avatar":""},{"name":"Asen Asenov","avatar":""},{"name":"Raymond","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae