INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pokemon-xyz-volkenion-va-magiana-sieu-may-moc', 'Pokémon XY&Z: Volkenion và Magiana Siêu Máy Móc', 'Pokémon the Movie: Volcanion and the Mechanical Marvel', 'https://phimimg.com/upload/vod/20231029-1/afb197a0ff70d1adf7a9e6f432f05f7a.jpg', 'https://phimimg.com/upload/vod/20231029-1/e445bc84ee8b5ff06aec86de8c102828.jpg', '<p>Trong cuộc phiêu lưu lần này, Ash và nhóm bạn được viếng thăm Vương Quốc Cơ Khí – nơi có một báu vật vô cùng giá trị ẩn sau sự tân tiến trong kỹ thuật. Ash vô tình bị mắc kẹt cùng Pokémon Huyền Thoại Volcanion – sinh vật mang niềm hận thù và khinh miệt dành cho loài người. Rắc rối bắt đầu xảy ra khi người quản lý Vương quốc đã đánh cắp phát minh tối thượng, đó là Pokémon Magearna Nhân Tạo được tạo ra cách đây 500 năm về trước. Hắn dự định sẽ sử dụng sức mạnh bí ẩn của Magearna để kiểm soát vương quốc cơ khí này. Liệu Ash và Volcanion có hợp tác với nhau để giải cứu Magearna được hay không? Một trong những trận chiến lớn nhất trong lịch sử Pokémon chính thức bắt đầu!</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Rica Matsumoto","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Mayuki Makiguchi","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Megumi Satou","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Inuko Inuyama","avatar":""},{"name":"Yuji Ueda","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Matsumoto Kōshirō X","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Shoko Nakagawa","avatar":""},{"name":"Yasuyuki","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324446);
