INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-ton-ngo-khong-ba-lan-danh-bach-cot-tinh', 'Tây Du Ký: Tôn Ngộ Không Ba Lần Đánh Bạch Cốt Tinh', 'The Monkey King 2', 'https://phimimg.com/upload/vod/20231030-1/7fc4df507554a40fdf1af72fb44119d1.jpg', 'https://phimimg.com/upload/vod/20231030-1/fdcc991e43b79326ca562df4e19b7ea1.jpg', '<p>Tây Du Ký 2- Ba Lần Đánh Bạch Cốt Tinh được coi là một trong những kiếp nạn đáng nhớ nhất của thầy trò Đường Tăng trên đường đi thỉnh kinh. Trong khó khăn này, thầy trò Đường Tăng không chỉ phải đối mặt với Bạch Cốt Tinh mưu mô xảo quyệt mà còn thử thách lòng tin và tình nghĩa thầy trò của nhau. Dựa vào một chương trong tác phẩm nổi tiếng của nhà văn Ngô Thừa Ân, bộ phim kể về kiếp nạn mà thầy trò Đường Tăng gặp phải trên núi Bạch Hổ. Con yêu quái này có phép biến hóa thần thông, giả làm gia đình người nông phu để bắt cóc Đường Tăng. Nhưng âm mưu của Bạch Cốt Tinh không qua được cặp mắt chiếu yêu của Tôn Ngộ Không, nên cuối cùng ả đều bị đánh chết. Đường Tăng không biết rõ sự việc đã trách Tôn Ngộ Không lạm sát người vô tội và đuổi về Hoa Quả Sơn.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Gong Li","avatar":""},{"name":"William Feng","avatar":""},{"name":"Xiao Shenyang","avatar":""},{"name":"Him Law","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Kris Phillips","avatar":""},{"name":"Wei Lu","avatar":""},{"name":"Giselle Chia","avatar":""},{"name":"Miya","avatar":""},{"name":"Miya Muqi","avatar":""},{"name":"Ngawang Rinchen","avatar":""},{"name":"John Ching Tung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d853