INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kubo-va-su-menh-samurai', 'Kubo và Sứ Mệnh Samurai', 'Kubo and the Two Strings', 'https://phimimg.com/upload/vod/20231026-1/566477ee515ef4fd50666385ace31fcf.jpg', 'https://phimimg.com/upload/vod/20231026-1/794d065953d69a1a9f6c2224ec980473.jpg', '<p>Kubo, một cậu bé, cùng với Monkey và Beetle, phải tìm và mặc bộ áo giáp huyền thoại của cha mình để đánh bại một linh hồn ác quỷ.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Art Parkinson","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Brenda Vaccaro","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Meyrick Murphy","avatar":""},{"name":"George Takei","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Minae Noji","avatar":""},{"name":"Alpha Takahashi","avatar":""},{"name":"Laura Miro","avatar":""},{"name":"Ken Takemoto","avatar":""},{"name":"Aaron Aoki","avatar":""},{"name":"Luke Donaldson","avatar":""},{"name":"Michael Sun Lee","avatar":""},{"name":"Cary Y","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324446);
