INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kubo-va-su-menh-samurai', 'Kubo và Sứ Mệnh Samurai', 'Kubo and the Two Strings', 'kubo và sứ mệnh samurai kubo and the two strings art parkinson charlize theron brenda vaccaro cary-hiroyuki tagawa meyrick murphy george takei rooney mara ralph fiennes matthew mcconaughey minae noji alpha takahashi laura miro ken takemoto aaron aoki luke donaldson michael sun lee cary y ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-13-gold', 'Đảo Hải Tặc 13: GOLD', 'One Piece Film: GOLD', 'https://phimimg.com/upload/vod/20231026-1/e3eb24b5f2b6af748928b076e2f4ba07.jpg', 'https://phimimg.com/upload/vod/20231026-1/aae845c98a184787b71a8b4744098089.jpg', '<p>Bối cảnh phim lấy mốc thời gian từ tập 80 trong loạt manga, sau khi băng hải tặc Mũ Rơm chiến thắng thất vũ hải Donquixote Doflamingo tại Dressrosa. Trong chuyến hành trình phiêu lưu trên biển cả mênh mông, họ bất ngờ bắt gặp Gran Tesoro - Một sòng bạc khổng lồ xa hoa dát vàng nằm trên một con tàu đặc biệt. &nbsp;Tại đây, Luffy và đồng đội đã rơi vào bẫy của Gild Tesoro - thuyền trưởng và là kẻ đã ăn trái ác quỷ Goru Goru, giúp hắn ta có thể biến mọi thứ thành vàng. Theo nhiều khán giả nhận định, phim có chất lượng đồ họa tuyệt vời, ánh vàng chủ đạo xuất hiện ở hầu hết các chi tiết trong phim, xen kẽ với màu tối tương phản giúp người xem cân bằng về mặt thị giác. Con tàu Gran Tesoro được hoàn thiện một cách tỉ mỉ và kỳ công, không khác gì một thành phố giữa lòng đại dương.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuya Nakai","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Nanao","avatar":""},{"name":"Gaku Hamada","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Kinya Kitaoji","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Masaya Onosak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324446);
