INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-hai-tac-13-gold', 'Đảo Hải Tặc 13: GOLD', 'One Piece Film: GOLD', 'đảo hải tặc 13: gold one piece film: gold kazuya nakai mayumi tanaka akemi okamura kappei yamaguchi hiroaki hirata yuriko yamaguchi ikue otani kazuki yao kazuhiro yamaji takahiro sakurai nanao gaku hamada hikari mitsushima kinya kitaoji fumihiko tachiki tomokazu seki masaya onosak ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-hanh-dinh-kien-va-xac-uop', 'Kiêu Hãnh, Định Kiến và Xác Ướp', 'Pride and Prejudice and Zombies', 'https://phimimg.com/upload/vod/20231026-1/2d103eee718a3523d82005a189e95867.jpg', 'https://phimimg.com/upload/vod/20231026-1/26d6f67de413ffbc195d8879fb945f47.jpg', '<p>Câu chuyện xảy ra tại nước Anh vào thế kỷ 19. Nạn dịch thây ma kinh hoàng đã biến cả miền quê trù phú và yên bình trở thành một chiến trường. Không một ai được an toàn, những người bạn thân thiết nhất cũng có thể ngay lập tức biến thành kẻ thù đáng sợ. Cảnh tượng chết chóc điêu tàn diễn ra ở khắp mọi nơi… Và nhân vật tiên phong trong phong trào tiêu diệt các thây ma chính là Elizabeth Bennet – một quý cô sinh ra trong gia đình trung lưu và được cha mình huấn luyện để trở thành một thợ săn xác sống.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lily James","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Douglas Booth","avatar":""},{"name":"Matt Smith","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Emma Greenwell","avatar":""},{"name":"Aisling Loftus","avatar":""},{"name":"Hermione Corfield","avatar":""},{"name":"Sally Phillips","avatar":""},{"name":"Dolly Wells","avatar":""},{"name":"Ellie Bamber","avatar":""},{"name":"Ryan Oliva","avatar":""},{"name":"Millie Brady","avatar":""},{"name":"Jess Radom","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a1