INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rogue-one-star-wars-ngoai-truyen', 'Rogue One: Star Wars Ngoại Truyện', 'Rogue One: A Star Wars Story', 'https://phimimg.com/upload/vod/20231026-1/41ccac3a4082ac4472fb39c6a3436899.jpg', 'https://phimimg.com/upload/vod/20231026-1/1d72c61bd4338562a3cd7cbefb195a00.jpg', '<p>Bộ phim diễn ra trong khoảng thời gian giữa tập III (Revenge of the Sith) và tập IV (The New Hope). Theo chân nữ nhân vật chính xinh đẹp Jyn Erso trong sứ mệnh đánh cắp bản thiết kế của vũ khí huỷ diệt Ngôi Sao Chết (The Death Star). Đây chính là mấu chốt để vén lên bức màn sự thật đằng sau việc quân liên minh phát hiện ra điểm yếu của Ngôi Sao chết và phá huỷ nó trong tập IV. Điều này cũng khép lại những tranh luận về vì sao siêu vũ khí của đế chế lại có thể bị phá huỷ một cách dễ dàng như vậy, vốn đã kéo dài hơn 40 năm qua.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Felicity Jones","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Jiang Wen","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Guy Henry","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Riz Ahmed","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Ben Daniels","avatar":""},{"name":"Paul Kasey","avatar":""},{"name":"Stephen Stanton","avatar":""},{"name":"Ian McElhinney","avatar":""},{"name":"Fares Fa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324446);
