INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-rung-blair', 'Phù Thủy Rừng Blair', 'Blair Witch', 'https://phimimg.com/upload/vod/20231026-1/9f3fc076416ceb23cca8dc0150e23fe3.jpg', 'https://phimimg.com/upload/vod/20231026-1/e45ff3437ebd7846ffb53675ad50c2f5.jpg', '<p>Để tìm người chị gái bị mất tích, một chàng trai trẻ cùng bạn bè mạo hiểm đi vào một khu rừng bị nguyền rủa có truyền thuyết kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"James Allen McCune","avatar":""},{"name":"Callie Hernandez","avatar":""},{"name":"Brandon Scott","avatar":""},{"name":"Corbin Reid","avatar":""},{"name":"Valorie Curry","avatar":""},{"name":"Wes Robinson","avatar":""},{"name":"Rei Hance","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324447);
