INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-tarzan', 'Huyền Thoại Tarzan', 'The Legend of Tarzan', 'https://phimimg.com/upload/vod/20231026-1/5e710fdf3c34296179f3918db6edfa40.jpg', 'https://phimimg.com/upload/vod/20231026-1/ad80564b7895ffdd72a1385d37ba33f1.jpg', '<p>Câu chuyện xảy ra nhiều năm kể từ khi người đàn ông từng được biết đến như Tarzan rời khu rừng ở châu Phi, bước vào cuộc sống của một quý tộc với tên gọi John Clayton III, Lãnh chúa Greystoke. Cùng với người vợ yêu quý Jane luôn túc trực bên anh. Nay anh được mời trở lại Congo với vai trò một sứ giả của Quốc hội. Chàng người rừng năm xưa không hề biết rằng mình chính là một con tốt trong một âm mưu chết người vì sự tham lam và trả thù, mà chủ mưu là Leon Rom (Christoph Waltz). Những gì đằng sau âm mưu chết người này không bao giờ có ý định tiết lộ.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Casper Crump","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Yule Masiteng","avatar":""},{"name":"Osy Ikhile","avatar":""},{"name":"Mens-Sana Tamakloe","avatar":""},{"name":"Sidney Ralitsoele","avatar":""},{"name":"Antony Acheampong","avatar":""},{"name":"Edward Apeagyei","avatar":""},{"name":"Ashley Byam","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324447);
