INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-su-ho-bao', 'Cộng Sự Hổ Báo', 'War Dogs', 'https://phimimg.com/upload/vod/20231026-1/a5cc545f1fe42aeeece6c82868e53ec9.jpg', 'https://phimimg.com/upload/vod/20231026-1/09b9c331b086e065799b60d288eaeec9.jpg', '<p>Câu chuyện có thật về 2 chàng trai trẻ mặt búng ra sữa rất giỏi xoay xở. Họ dấn thân vào con đường buôn bán vũ khí, từng nhận được hợp đồng trị giá 300tr $ cung cấp vũ khí cho quân đội Mỹ ở Afghanistan.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miles Teller","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"JB Blanc","avatar":""},{"name":"Gabriel Spahiu","avatar":""},{"name":"Julian Sergi","avatar":""},{"name":"Andrei Finti","avatar":""},{"name":"Jeremy Tardy","avatar":""},{"name":"Barry Livingston","avatar":""},{"name":"Jeff Pierre","avatar":""},{"name":"Said Faraj","avatar":""},{"name":"Ashley Rae Spillers","avatar":""},{"name":"Mehdi Merali","avatar":""},{"name":"Aaron L","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
