INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-sat-nhan', 'Cỗ Máy Sát Nhân', 'Kill Command', 'https://phimimg.com/upload/vod/20231026-1/9ca536524fbdd100e92891da17c67ccd.jpg', 'https://phimimg.com/upload/vod/20231026-1/ad68c5a3298deb3b7bad8b205eb8b153.jpg', '<p>Bộ phim lấy bối cảnh ở tương lai không xa, nơi mà con người sống lệ thuộc vào công nghệ và buộc phải chiến đấu với những cổ máy giết người do chính họ tạo ra.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Vanessa Kirby","avatar":""},{"name":"Thure Lindhardt","avatar":""},{"name":"David Ajala","avatar":""},{"name":"Tom McKay","avatar":""},{"name":"Deborah Rosan","avatar":""},{"name":"Bentley Kalu","avatar":""},{"name":"Mike Noble","avatar":""},{"name":"Osi Okerafor","avatar":""},{"name":"Damian Kell","avatar":""},{"name":"Tim Ahern","avatar":""},{"name":"Kelly Gough","avatar":""},{"name":"Sam Huntington","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
