INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-doc-lap-tai-chien', 'Ngày Độc Lập: Tái Chiến', 'Independence Day: Resurgence', 'https://phimimg.com/upload/vod/20231024-1/daac307e5133875e1cee269fcdda42e6.jpg', 'https://phimimg.com/upload/vod/20231024-1/7ecb1c94e2ba6a6862fa24aea2a930fc.jpg', '<p>Chúng ta đều biết điều đó sẽ trở lại. Sau bộ phim INDEPENDENCE DAY - 1 thể loại về dòng phim sự kiện, chương sử thi tiếp theo nói về một thảm họa toàn cầu với quy mô không thể tưởng tượng được. Sử dụng công nghệ thu được từ người ngoài hành tinh, các quốc gia trên trái đất đã hợp tác với một chương trình phòng thủ to lớn để bảo vệ hành tinh. Nhưng chúng ta chưa được trang bị gì để có thể chống lại lực lượng người ngoài hành tinh tân tiến và chưa từng có này. Duy chỉ có tài khéo léo của một vài người đàn ông và phụ nữ dũng cảm mới có thể vực dậy thế giới chúng ta khỏi bờ vực của sự tuyệt chủng.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Hemsworth","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Jessie T. Usher","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Maika Monroe","avatar":""},{"name":"Sela Ward","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Brent Spiner","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Charlotte Gainsbourg","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Nicolas Wright","avatar":""},{"name":"Travis Tope","avatar":""},{"name":"Chin Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324447);
