INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-choi-khong-tuoi', 'Tay Chơi Không Tuổi', 'Dirty Grandpa', 'https://phimimg.com/upload/vod/20231024-1/bf31d0d55a4166244e953f1d62ee9f0f.jpg', 'https://phimimg.com/upload/vod/20231024-1/6cc4a4c76fee2c05b8f51e085c68a1ac.jpg', '<p>Bộ phim xoay quanh câu chuyện về một người cháu trai (Zac Efron) ngay trước ngày cưới của mình đã bị ông nội tinh quái (Robert De Niro) đánh lừa, để cùng ông tham gia một chuyến hành trình đến Florida nghỉ mát. Ông nội thì cho rằng người cháu kết hôn nhầm với một cô gái không xứng đáng, còn người cháu luôn chống đối lại ông mình. Tuy nhiên, mọi mâu thuẫn và khúc mắc đã được giải quyết trong suốt chuyến đi đầy cam go này...</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"Zoey Deutch","avatar":""},{"name":"Julianne Hough","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Brandon Mychal Smith","avatar":""},{"name":"Mo Collins","avatar":""},{"name":"Henry Zebrowski","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Michael Hudson","avatar":""},{"name":"Jake Picking","avatar":""},{"name":"Deena Dill","avatar":""},{"name":"Lane Carlock","avatar":""},{"name":"Eugenia Kuzmina","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
