INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-cuoc-chien-mua-dong', 'Thợ Săn: Cuộc Chiến Mùa Đông', 'The Huntsman: Winter''s War', 'https://phimimg.com/upload/vod/20231024-1/289409f1e46228fdbfc0bdea5881b75b.jpg', 'https://phimimg.com/upload/vod/20231024-1/d5913aeb8b4c0db26fd2d559483d359a.jpg', '<p>Rất lâu trước khi bị đánh bại bởi Bạch Tuyết, nữ hoàng Ravenna luôn đau đáu dõi theo người em gái Freya (Blunt) đau khổ vì bị nhà vua phản bội. Với khả năng đóng băng mọi thứ, Freya dùng nhiều thập kỉ để tạo nên đạo quân “thợ săn chết” của mình bao gồm cả Eric (Hemsworth) và Sara (Chastain).&nbsp; Khi Freya biết chị gái bại trận, cô đã triệu hồi đạo quân để mang Gương Thần về vùng đất băng giá và khai thác sức mạnh còn lại của nó. Freya phát hiện Ravenna có thể được phục sinh từ vàng và từ đó hai chị em đã gieo ma thuật bóng tối lên vùng đất thần tiên. Eric- chàng thợ săn lạc loài lúc này phải đứng lên chống lại hai chị em.</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Rob Brydon","avatar":""},{"name":"Sheridan Smith","avatar":""},{"name":"Alexandra Roach","avatar":""},{"name":"Sope Dirisu","avatar":""},{"name":"Sophie Cookson","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Colin Morgan","avatar":""},{"name":"Conrad Khan","avatar":""},{"name":"Niamh Walter","avatar":""},{"name":"Nana Agyeman-Bediako","avatar":""},{"name":"Amelia Crouch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
