INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-trong-bong-toi', 'Sát Nhân Trong Bóng Tối', 'Don''t Breathe', 'https://phimimg.com/upload/vod/20231024-1/836dcac59f1d7cba408ccfd98628b892.jpg', 'https://phimimg.com/upload/vod/20231024-1/372cf2600329d3c7ace5147805630a00.jpg', '<p>Ba tên du côn đột nhập vào nhà của Norman, một cựu chiến binh Chiến tranh vùng Vịnh bị mù, để lấy trộm tiền của anh ta. Tuy nhiên, thật kinh hoàng, họ phát hiện ra rằng Norman không hề có khả năng tự vệ như anh ta có vẻ.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jane Levy","avatar":""},{"name":"Dylan Minnette","avatar":""},{"name":"Daniel Zovatto","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Emma Bercovici","avatar":""},{"name":"Franciska Törőcsik","avatar":""},{"name":"Christian Zagia","avatar":""},{"name":"Katia Bokor","avatar":""},{"name":"Sergej Onopko","avatar":""},{"name":"Olivia Gillies","avatar":""},{"name":"Dayna Clark","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324447);
