INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-tro-dua-chet-choc', 'Batman: Trò Đùa Chết Chóc', 'Batman: The Killing Joke', 'https://phimimg.com/upload/vod/20231023-1/b7ab65090b9e3e85f5565695a26f409a.jpg', 'https://phimimg.com/upload/vod/20231023-1/f0f3615c4530d124f226368b459a0773.jpg', '<p>Câu chuyện kể về nhân vật phản diện loạn trí – một cựu kỹ sư điên rồ hài hước chọc tức Kỵ Sĩ Bóng Đêm bằng cách bắt cóc và tra tấn Barbara Gordon (Batgirl). Hắn mang ý đồ khiến cảnh sát trưởng Gordon phát điên với những hình ảnh mình mẩy đầy thương tích, trần truồng về người con gái của ông.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Conroy","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Ray Wise","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Brian George","avatar":""},{"name":"JP Karliak","avatar":""},{"name":"Andrew Kishino","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Maury Sterling","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Bruce Timm","avatar":""},{"name":"Anna Vocino","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Rick D. Wasserman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
