INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-kho-mong-mo', 'Những Kẻ Khờ Mộng Mơ', 'La La Land', 'https://phimimg.com/upload/vod/20231023-1/bd5d8cb0b5fd7856c04a84c9c7e35378.jpg', 'https://phimimg.com/upload/vod/20231023-1/3541e59b0af9f30f74a096ddb6c35a99.jpg', '<p>La La Land là câu chuyện tình yêu tuyệt đẹp thời hiện đại giữa chàng nhạc công piano tài hoa chuyên diễn tại các quán bar Sebastian và cô diễn viên mới nổi xinh đẹp Mia Dolan. Thế nhưng, ở thiên đường điện ảnh Hollywood, tình yêu và sự thành công dường như không thể song hành. Khi thành công và sự nổi tiếng đến, họ sẽ phải đối mặt ra sao ...</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"John Legend","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Amiée Conn","avatar":""},{"name":"Terry Walters","avatar":""},{"name":"Thom Shelton","avatar":""},{"name":"Cinda Adams","avatar":""},{"name":"Callie Hernandez","avatar":""},{"name":"Jessica Rothe","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"Claudine Claudio","avatar":""},{"name":"Jason Fuchs","avatar":""},{"name":"D.A. Wallach","avatar":""},{"name":"Trevor Lissauer","avatar":""},{"name":"Olivia Hamilton","avatar":""},{"name":"Ann","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324447);
