INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tay-sung-huyen-thoai', 'Bảy Tay Súng Huyền Thoại', 'The Magnificent Seven', 'https://phimimg.com/upload/vod/20231022-1/e3f52add461fa05fc1ee534cf99d4199.jpg', 'https://phimimg.com/upload/vod/20231022-1/2e7ba7f373c8fdf9c64bc4e9b8c282b6.jpg', '<p>Bartholomew Bogue, một ông trùm tư bản độc ác, ép buộc người dân thị trấn phải bán rẻ đất đai để hắn mở rộng quy mô mỏ khai thác vàng gần đó, dẫn đến những món nợ máu. Emma Cullen, một góa phụ có chồng bị Bogue sát hại, đã thay mặt người dân thị trấn đi tìm những người có khả năng bảo vệ họ khỏi sự đàn áp, khủng bố của Bogue cùng tay chân. Sau khi thuyết phục được Sam Chisolm, cô cùng gã thợ săn tiền thưởng chính quy thuyết phục thêm sáu tay súng khác. Họ cùng nhau hợp lực bảo vệ sự tồn vong của Rose Creek khi Bogue chuẩn bị quay lại.</p>', 'Full', 1, 'single', 'completed', 23, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Martin Sensmeier","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Haley Bennett","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Luke Grimes","avatar":""},{"name":"Jonathan Joss","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"Kevin Wayne","avatar":""},{"name":"Carri","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324447);
