INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-chien-truong-thanh', 'Tử Chiến Trường Thành', 'The Great Wall', 'https://phimimg.com/upload/vod/20231022-1/bf42503b873472c271bb9a5eb0e25e60.jpg', 'https://phimimg.com/upload/vod/20231022-1/004ea6c58a66da9cee03975e78802031.jpg', '<p>Lấy bối cảnh thời kỳ Bắc Tống, chuyện phim xoay quanh câu chuyện của William Garin (Damon) – thành viên trong nhóm lính đánh thuê châu Âu được cử sang Trung Quốc để đánh cắp công thức chế tạo thuốc súng. Sau khi bị phát hiện và bị tống giam bên trong Vạn Lý Trường Thành, anh đã vô tình phát hiện ra những bí ẩn đáng sợ đằng sau công trình được coi là Đệ nhất kỳ quan của thế giới.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Jing Tian","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Han Lu","avatar":""},{"name":"Lin Gengxin","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Huang Xuan","avatar":""},{"name":"Ryan Zheng Kai","avatar":""},{"name":"Karry Wang","avatar":""},{"name":"Chen Xuedong","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Numan Acar","avatar":""},{"name":"Johnny Cicco","avatar":""},{"name":"Yu Xintian","avatar":""},{"name":"Liu Enjia","avatar":""},{"name":"Stephen Chang","avatar":""},{"name":"Li Heng","avatar":""},{"name":"Li Jingm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
