INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alice-o-xu-so-trong-guong', 'Alice Ở Xứ Sở Trong Gương', 'Alice Through the Looking Glass', 'https://phimimg.com/upload/vod/20231023-1/50355995cc88b95db0c835bc2288ce80.jpg', 'https://phimimg.com/upload/vod/20231023-1/e8a4969a798a0a5aa703bb3ad156bdd0.jpg', '<p>Phim Alice ở Xứ Sở Trong Gương trở nên sống động hơn bao giờ hết với những khung hình sử dụng kĩ xảo tuyệt đẹp và đầy màu sắc. Dàn diễn viên “bom tấn” của Alice Ở Xứ Sở Thần Tiên cũng trở lại với xứ sở trong gương: Mia Wasikowska trong vai Alice, Helena Bonham Carter trong vai Red Queen, Anne Hathaway trong vai White Queen, và tất nhiên không thể thiếu Johnny Depp trong vai Mad Hatter. Bên cạnh đó, một nhân vật phản diện hoàn toàn mới cũng đã được hé lộ trong trailer chính thức này: Time (Sacha Baron Cohen thủ vai) – một sinh vật nửa người, nửa đồng hồ với khả năng điều khiển thời gian. “Time không phải là người cô muốn đối địch đâu”, White Queen đã cảnh báo cho Alice.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Mia Wasikowska","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Andrew Scott","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Ed Speleers","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Tom Godwin","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"Amelia Crouch","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d47