INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tiec-xuc-xich', 'Đại Tiệc Xúc Xích', 'Sausage Party', 'https://phimimg.com/upload/vod/20231023-1/ce1644652d182b57a14c41a641c83627.jpg', 'https://phimimg.com/upload/vod/20231023-1/94fcc4e8ab3e555edf86b9ec0570f997.jpg', '<p>Phim kể về một anh chàng xúc xích và những người bạn của anh ta cố gắng tìm mọi cách trở lại hội chợ mua sắm sau khi bị rớt khỏi chiếc xe vận chuyển</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"James Franco","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"Scott Underwood","avatar":""},{"name":"Sugar Lyn Beard","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"Ian Jame","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
