INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-rua-dap-tan-bong-toi', 'Ninja Rùa: Đập Tan Bóng Tối', 'Teenage Mutant Ninja Turtles: Out of the Shadows', 'https://phimimg.com/upload/vod/20231023-1/0422124650d367140152ba4b3886bc24.jpg', 'https://phimimg.com/upload/vod/20231023-1/ce9e16de730f7b0df3a76da9f6ee839f.jpg', '<p>Sau khi tên tội phạm Shredder trốn thoát, hắn gia nhập lực lượng với nhà khoa học điên Baxter Stockman (Tyler Perry) và hai tên tay sai ngu ngốc Bebop (Gary Anthony Williams) và Rocksteady (WWE Superstar Stephen &quot;Sheamus&quot; Farrelly),lập ra một kế hoạch độc ác để chiếm đoạt thế giới. Khi các ninja rùa chuẩn bị bắt Shredder cùng đồng bọn thì họ nhận ra mình phải đối mặt với một ác nhân khác có ý định tương tự: Krang.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Megan Fox","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Stephen Amell","avatar":""},{"name":"Pete Ploszek","avatar":""},{"name":"Alan Ritchson","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Jeremy Howard","avatar":""},{"name":"Tyler Perry","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Alessandra Ambrosio","avatar":""},{"name":"Brittany Ishibashi","avatar":""},{"name":"Stephen Farrelly","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Peter Dona","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324447);
