INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ninja-rua-dap-tan-bong-toi', 'Ninja Rùa: Đập Tan Bóng Tối', 'Teenage Mutant Ninja Turtles: Out of the Shadows', 'ninja rùa: đập tan bóng tối teenage mutant ninja turtles: out of the shadows megan fox laura linney will arnett stephen amell pete ploszek alan ritchson noel fisher jeremy howard tyler perry brian tee gary anthony williams alessandra ambrosio brittany ishibashi stephen farrelly tony shalhoub brad garrett peter dona ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thanh-trung-nam-bau-cu', 'Ngày Thanh Trừng: Năm Bầu Cử', 'The Purge: Election Year', 'https://phimimg.com/upload/vod/20231022-1/836825a3dbc8744dacbdbdc6525c2fa9.jpg', 'https://phimimg.com/upload/vod/20231022-1/5ba66115c2101c640128fdb5913c0a22.jpg', '<p>Ngày Thanh Trừng 3 là phần kết thúc cho series kinh dị trứ danh, kịch bản vẫn xoay quanh một đêm Thanh trừng mới, khi một nữ chính trị gia mẫn cán bị săn lùng bởi bọn sát thủ mang mặt nạ cùng những kẻ thù biến chất muốn ngăn ngừa cô đắc cử tổng thống.&nbsp; Ngoài ra, yếu tố chính trị trong phần này cũng được đào sâu nhiều hơn, không còn là những cuộc chém giết và trả thù quy mô nhỏ lẻ nữa. Kết cục của phần cuối cũng sẽ quyết định được liệu “Ngày thanh trừng” có chấm dứt hoàn toàn hay không, đồng thời những kẻ giật dây tội ác trong hai phần trước cũng sẽ lộ mặt.&nbsp; Phần một của loạt phim ra mắt lần đầu năm 2013 đã khiến cộng đồng mê phim kinh dị “dậy sóng”, khi mang trong mình một kịch bản vô cùng sáng tạo. Tác phẩm đưa ra một viễn cảnh giả định, khi nước Mỹ gần như dẹp sạch hoàn toàn mầm móng tội ác trong mỗi con người. Để điều này khả thi, vào một đêm duy nhất trong mỗi năm, người dân được phép thực hiện mọi hành vi tàn ác như cướp của, cưỡng hiếp, giết người,… tất cả đều hợp pháp!</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Elizabeth Mitchell","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Betty Gabriel","avatar":""},{"name":"J. J. Soria","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"Kyle Secor","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Terry Serpico","avatar":""},{"name":"David Aaron Baker","avatar":""},{"name":"Kimberly Howe","avatar":""},{"name":"Roman Blat","avatar":""},{"name":"J. Jewels","avatar":""},{"name":"Barry Nolan","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"Adam Cantor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
