INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('london-that-thu', 'London Thất Thủ', 'London Has Fallen', 'https://phimimg.com/upload/vod/20231022-1/53e8e01e4945040abfa008a7d15a8222.jpg', 'https://phimimg.com/upload/vod/20231022-1/95aad8de4bd63fc89e51fc4e52833861.jpg', '<p>Lần này tổng thống Mỹ Benjamin Asher và đặc vụ Mike Banning sẽ đến Anh và vô tình bị cuốn vào 1 nhiệm vụ hết sức khó khăn là giải cứu các nhà lãnh đạo cấp cao các nước khi Thủ tướng Anh đột ngột qua đời và tất cả bọn họ đến Anh để dự lễ tang. Tuy nhiên đây không phải là một đám tang thông thường bởi đằng sau nó là một âm mưu bắt cóc và ám sát những yếu nhân của bọn phản động.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"Mehdi Dehbi","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Alon Abutbul","avatar":""},{"name":"Jorge Leon Martinez","avatar":""},{"name":"Waleed Zuaiter","avatar":""},{"name":"Adel Bencherif","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
