INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-tho-may-2-su-tai-xuat', 'Sát Thủ Thợ Máy 2: Sự Tái Xuất', 'Mechanic: Resurrection', 'https://phimimg.com/upload/vod/20231020-1/bf28e41ef676746b2e1601d43ca36768.jpg', 'https://phimimg.com/upload/vod/20231020-1/cebb0b3953ee22fe51bb039b026f074b.jpg', '<p>Đây thực chất là phần tiếp theo của The Mechanic (2011) - bộ phim xoay quanh gã sát thủ khôn ngoan, nhanh nhẹn, có khả năng tạo hiện trường giả hoàn hảo sau khi ra tay, khiến đối tượng sát hại trông giống như nạn nhân của một vụ tai nạn xấu số nào đó.&nbsp; Mở đầu Mechanic: Resurrection, Arthur Bishop đã “rửa tay gác kiếm” và bắt đầu cuộc sống mới. Nhưng anh vẫn bị những tổ chức tội ác lần ra tung tích. Chúng muốn gã sát thủ thực hiện ba vụ ám sát, ngụy trang tất cả thành như tai nạn.&nbsp; Bishop nhất mực từ chối và chạy thoát. Nhưng cuộc gặp gỡ định mệnh với người đẹp Gina (Jessica Alba) tại một hòn đảo xinh đẹp ở Thái Lan hoàn toàn nằm ngoài kế hoạch của anh. Sự kiện khiến Bishop buộc phải “tái xuất giang hồ”, tạm thời nhượng bộ kẻ ác.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Rhatha Phongam","avatar":""},{"name":"John Cenatiempo","avatar":""},{"name":"Bonnie Zellerbach","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Aaron Brumfield","avatar":""},{"name":"Andrew Stehlin","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Atanas Srebrev","avatar":""},{"name":"Anteo Quintavalle","avatar":""},{"name":"Femi Elufowoju Jr.","avatar":""},{"name":"Toby","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
