INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-uu-viet', 'Bộ Ba Ưu Việt', 'Hidden Figures', 'https://phimimg.com/upload/vod/20231020-1/22ff874ab567a0d39a94139742ddf4f3.jpg', 'https://phimimg.com/upload/vod/20231020-1/490276d8c25392f9b51cb8e7864a88f0.jpg', '<p>Bộ Ba Ưu Việt là một bộ phim hài hước do Mỹ sản xuất xoay quanh câu chuyện đầy thú vị về ba nữ toán học người Mỹ gốc Phi Dorothy Vaughn, Mary Jackson và Katherine Johnson. Trong phim lấy bối cảnh và thời kỳ Nga Mỹ đang chạy đua quyết liệt với nhau về việc đưa người lên không giang và NASA đã tìm ra những người phụ nữ tài năng làm bộ não đứng sau hoạt động mang tính lịch sử lần này.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taraji P. Henson","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Janelle Monáe","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Ariana Neal","avatar":""},{"name":"Saniyya Sidney","avatar":""},{"name":"Zani Jones Mbayise","avatar":""},{"name":"Donna Biscoe","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Kimberly Quinn","avatar":""},{"name":"Frank Hoyt Taylor","avatar":""},{"name":"Lidya Jewe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324447);
