INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-huyen-bi-va-noi-tim-ra-chung', 'Sinh Vật Huyền Bí và Nơi Tìm Ra Chúng', 'Fantastic Beasts and Where to Find Them', 'https://phimimg.com/upload/vod/20231020-1/6cdc6f910d27eba99a564a8a03d31c16.jpg', 'https://phimimg.com/upload/vod/20231020-1/094960c0e4d5f8411efa39cd27befefb.jpg', '<p>Lấy bối cảnh trước Harry Potter, Fantastic Beasts And Where To Find Them kể về hành trình khám phá thế giới kỳ bí của pháp sư Newt Scamander do nam diễn viên Eddie Redmayne tài năng đảm nhận. Anh lên đường tới New York vào năm 1926 và bắt đầu quá trình đúc kết những tư liệu về các loài sinh vật mà về sau trường Hogwarts dùng để giảng dạy. Đây cũng là một trong những cuốn sách giáo khoa được nhắc tới trong tập 1 của Harry Potter – Harry Potter và Hòn đá phù thủy.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Eddie Redmayne","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Alison Sudol","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Samantha Morton","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Josh Cowdery","avatar":""},{"name":"Ronan Raftery","avatar":""},{"name":"Faith Wood-Blagrove","avatar":""},{"name":"Jenn Murray","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Peter B","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324447);
