INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13-gio-linh-ngam-benghazi', '13 Giờ: Lính Ngầm Benghazi', '13 Hours: The Secret Soldiers of Benghazi', 'https://phimimg.com/upload/vod/20231020-1/e1d8bfdf19d94e3cd3e545eb5e6896ae.jpg', 'https://phimimg.com/upload/vod/20231020-1/1f2dc590e4f811c3703eb353b2d830fd.jpg', '<p>Bộ phim 13 Giờ: Lính Ngầm Benghazi của đạo diễn Michael Bay là một câu chuyện có thật và lôi cuốn về sáu cựu binh tinh nhuệ được giao trọng trách bảo vệ CIA đang cố gắng chống chọi khi quân khủng bố tấn công Lãnh sự Mỹ vào ngày 11 tháng 9 năm 2012. Khi tình hình xấu đi, họ đã có can đảm để làm những gì được cho là đúng đắn. Dựa trên cuốn sách viết về câu chuyện có thật &quot;13 Giờ: Sự thật Xảy ra bên trong Benghazi, cuốn sách bán chạy nhất của New York Times bởi tác giả Mitchell Zuckoff và thành viên của đội Annex Security.</p>', 'Full', 1, 'single', 'completed', 23, 2016, 'Vietsub', 'HD', 'Malta', 0, '[{"name":"John Krasinski","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Dominic Fumusa","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Alexia Barlier","avatar":""},{"name":"David Costabile","avatar":""},{"name":"David Denman","avatar":""},{"name":"Payman Maadi","avatar":""},{"name":"Toby Stephens","avatar":""},{"name":"Demetrius Grosse","avatar":""},{"name":"David Giuntoli","avatar":""},{"name":"Freddie Stroma","avatar":""},{"name":"Christopher Dingli","avatar":""},{"name":"David Furr","avatar":""},{"name":"Wr","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c50