INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-do-bo-bi-an', 'Cuộc Đổ Bộ Bí Ẩn', 'Arrival', 'https://phimimg.com/upload/vod/20231020-1/c95d8d9cffbbc792e00bb716f08b4e41.jpg', 'https://phimimg.com/upload/vod/20231020-1/f23cad491550b5e7c47d47574aa499e1.jpg', '<p>Khi một phi thuyền bí ẩn đáp xuống trái đất, một biệt đội tinh anh dưới sự dẫn dắt của chuyên gia ngôn ngữ học kiệt xuất Louise Banks được đưa đến để điều tra. Louise và các đồng đội phải chạy đua với thời gian để tìm câu trả lời cho nhiều bí ẩn. Để rồi, trong quá trình tìm kiếm, cô phát hiện những điều có thể đe dọa cuộc sống của cô và sự tồn tại của cả nhân loại.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Julia Scarlett Dan","avatar":""},{"name":"Abigail Pniowsky","avatar":""},{"name":"Jadyn Malone","avatar":""},{"name":"Carmela Nozza Guizzo","avatar":""},{"name":"Andrew Shaver","avatar":""},{"name":"Shawn Campbell","avatar":""},{"name":"Larry Day","avatar":""},{"name":"Pat Kiely","avatar":""},{"name":"Frank Schorpion","avatar":""},{"name":"Lucas Chartier-Dessert","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324447);
