INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-chua-ke-o-xu-so-khong-lo', 'Chuyện Chưa Kể Ở Xứ Sở Khổng Lồ', 'The BFG', 'https://phimimg.com/upload/vod/20231020-1/29304a10b35cc7af37d524b82aeb9265.jpg', 'https://phimimg.com/upload/vod/20231020-1/3a04cdfbaa3e68ffb7eae49282470f5c.jpg', '<p>Một cô gái trẻ, Sophie, kết bạn với một người khổng lồ, người bị ruồng bỏ bởi vì, không giống như những người khác cùng loại, anh ta từ chối làm tổn thương con người. Tuy nhiên, mọi thứ thay đổi sau khi những người khổng lồ khác quyết định săn lùng Sophie.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mark Rylance","avatar":""},{"name":"Ruby Barnhill","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"Marilyn Norry","avatar":""},{"name":"Chris Shields","avatar":""},{"name":"Matt Frewer","avatar":""},{"name":"Geoffrey Wade","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Haig Sutherland","avatar":""},{"name":"John Emmet Tracy","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Daniel Bacon","avatar":""},{"name":"Paul Moniz de Sa","avatar":""},{"name":"Ólafur Darri Óla","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
