INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-reacher-khong-quay-dau', 'Jack Reacher: Không Quay Đầu', 'Jack Reacher: Never Go Back', 'https://phimimg.com/upload/vod/20231019-1/48291816c8a8696d8c6b67503d9a0740.jpg', 'https://phimimg.com/upload/vod/20231019-1/73f0e4097bb65f3de87c87394261fbf3.jpg', '<p>Bản thân series phim này dựa trên bộ tiểu thuyết về nhân vật Jack Reacher của nhà văn Lee Child. Nội dung phim dựa theo cuốn tiểu thuyết cùng tên, đưa người xem theo chân thiếu tá đã giải ngũ Jack Reacher (Tom Cruise) trong cuộc điều tra trả lại sự trong sạch cho thiếu tá Turner (Cobie Smulders). Từ đó anh khám phá ra một âm mưu khủng khiếp trong quân đội, khiến không biết bao nhiêu người phải mất mạng.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Danika Yarosh","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Patrick Heusinger","avatar":""},{"name":"Madalyn Horcher","avatar":""},{"name":"Jessica Stroup","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Robert Catrini","avatar":""},{"name":"Judd Lormand","avatar":""},{"name":"Christopher Berry","avatar":""},{"name":"Hunter Burke","avatar":""},{"name":"Jason Douglas","avatar":""},{"name":"Lizeth Hutchings","avatar":""},{"name":"Marisela Zumbado","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
