INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-am-la-ky-cua-co-peregrine', 'Mái Ấm Lạ Kỳ Của Cô Peregrine', 'Miss Peregrine''s Home for Peculiar Children', 'https://phimimg.com/upload/vod/20231019-1/cff77a13fe5a5cc168047af44008ed97.jpg', 'https://phimimg.com/upload/vod/20231019-1/456d8870c81101646d55bfd9dbdfadc7.jpg', '<p>Mái Ấm Lạ Kỳ Của Cô Peregrine kể về cuộc phiêu lưu đến một vùng đất lạ kỳ của Jacob Portman. Tại đây, Jacob gặp được cô Peregrine và những đứa trẻ có khả năng dị thường cô đang che chở. Nơi ấy có cô gái tóc đỏ với đôi tay giữ lửa, cậu bé tàng hình mặc đồ lịch thiệp hay cô gái váy xanh bay lơ lửng trên trời… Tất cả đều khiến người xem choáng ngợp bởi cảm giác ma mị, kỳ bí....</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Belgium', 0, '[{"name":"Eva Green","avatar":""},{"name":"Asa Butterfield","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Ella Purnell","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Milo Parker","avatar":""},{"name":"Cameron King","avatar":""},{"name":"Finlay MacMillan","avatar":""},{"name":"Callum Wilson","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"Lauren McCrostie","avatar":""},{"name":"Pixie Davies","avatar":""},{"name":"Georgia Pem","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324447);
