INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('captain-america-noi-chien-sieu-anh-hung', 'Captain America: Nội Chiến Siêu Anh Hùng', 'Captain America: Civil War', 'https://phimimg.com/upload/vod/20231019-1/5627583170acd90f4a913dfb103a66b6.jpg', 'https://phimimg.com/upload/vod/20231019-1/8c7f1dd82969ab49e34d2adeee20a948.jpg', '<p>Captain America: Civil War (Nội Chiến Siêu Anh Hùng) xoay quanh việc Steve Rogers (Captain America) dẫn đầu một nhóm siêu anh hùng với các thành viên của Avengers với mục tiêu tiếp tục nỗ lực để bảo vệ nhân loại. Nhưng sau nhiều vụ việc xảy ra do biệt đội Avengers làm thiệt hại tài sản, chính phủ đã thiết lập cơ quan quản lý và giám sát nhóm. Điều này gây ra sự chia rẽ trong nội bộ nhóm Avengers, tạo nên hai phe đối đầu nhau. Một bên được lãnh đạo bởi Steve Rogers (Captain America) với mong muốn duy trì nhóm để thực hiện mục tiêu bảo vệ nhân loại mà không có sự can thiệp của chính phủ. Phe còn lại là của Tony Stark (Iron Man) luôn hỗ trợ giám sát và có trách nhiệm giải trình mọi việc làm với chính phủ.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Chadwick Boseman","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"William Hurt","avatar":""},{"name":"John Kani","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324447);
