INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-truy-sat', 'Băng Đảng Truy Sát', 'Green Room', 'https://phimimg.com/upload/vod/20231021-1/f107055600fd37743a75e951ee943766.jpg', 'https://phimimg.com/upload/vod/20231021-1/d746e4aa1c4ae34dbc28be6234c24fba.jpg', '<p>Một ban nhạc punk rock bị mắc kẹt ở một địa điểm hẻo lánh sau khi phát hiện ra hiện trường bạo lực. Đối với những gì họ nhìn thấy, bản thân ban nhạc trở thành mục tiêu bạo lực từ một nhóm đầu trọc quyền lực da trắng, những kẻ muốn loại bỏ mọi bằng chứng tội ác.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anton Yelchin","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Alia Shawkat","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Mark Webber","avatar":""},{"name":"Eric Edelstein","avatar":""},{"name":"Macon Blair","avatar":""},{"name":"Kai Lennox","avatar":""},{"name":"David W. Thompson","avatar":""},{"name":"Michael Draper","avatar":""},{"name":"Andy Copeland","avatar":""},{"name":"Brent Werzner","avatar":""},{"name":"Lj Klink","avatar":""},{"name":"Kasey Brown","avatar":""},{"name":"Taylor Tunes","avatar":""},{"name":"Jake Love","avatar":""},{"name":"Kyl","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
