INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-tu-luan-hoi-dai-chien-osaka', 'Sinh Tử Luân Hồi: Đại Chiến Osaka', 'GANTZ:O', 'https://phimimg.com/upload/vod/20231018-1/1219f03afc205a847b9451fe77f4e34d.jpg', 'https://phimimg.com/upload/vod/20231018-1/b1169a6d99acb0b55f8814af85f81ec8.jpg', '<p>GANTZ xoay quanh một khối cầu đen bí ẩn xuất hiện giữa gian phòng trống tại một tòa nhà nào đó không ai xác định được giữa thủ đô Tokyo. Nó có sức mạnh toàn năng làm biến mất những người tưởng chừng sẽ chết chỉ trong tích tắc.&nbsp; Gantz: O kể về phần các nhân vật Gantz tại Osaka. Trong manga gốc, đây là lúc mà các nhân vật chính nhận rằng họ không phải là những người duy nhất tham gia vào cuộc đi săn người ngoài hành tinh.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Masaya Onosaka","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Teruaki Ogawa","avatar":""},{"name":"Tomohiro Kaku","avatar":""},{"name":"Masane Tsukayama","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324447);
