INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dau-4-boyka', 'Quyết Đấu 4: Boyka', 'Boyka: Undisputed IV', 'https://phimimg.com/upload/vod/20231019-1/ff153ee9205a9648ac9586b3cbb23068.jpg', 'https://phimimg.com/upload/vod/20231019-1/2a2aafe5a8f6ed7c4854b9b6af159a73.jpg', '<p>Phim Boyka: Undisputed IV (Quyết Đấu 4: Boyka) vốn có xuất phát điểm là phản diện chính trong Undisputed II: Last Man Standing (2006), gã võ sĩ tự do Yuri Boyka do Scott Adkins thủ vai nhanh chóng chiếm được cảm tình của khán giả. Anh trở thành nhân vật chính trong phần ba ra mắt năm 2010. Được mệnh danh là “Chiến binh hoàn hảo nhất thế giới”, Yuri tuy luôn ôm trong mình hận thù, nhưng thật ra là một đấu sĩ MMA thượng võ, kiên trì. Ở phần phim này, gã phản anh hùng này tiếp tục dùng nắm đấm để theo đuổi giấc mộng vô địch thế giới của hắn.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Teodora Duhovnikova","avatar":""},{"name":"Alon Abutbul","avatar":""},{"name":"Julian Vergov","avatar":""},{"name":"Martyn Ford","avatar":""},{"name":"Brahim Achabbakhe","avatar":""},{"name":"Paul Chahidi","avatar":""},{"name":"Petio Petkov","avatar":""},{"name":"Valentin Ganev","avatar":""},{"name":"Vlado Mihailov","avatar":""},{"name":"Vladimir Kolev","avatar":""},{"name":"Hristo Petkov","avatar":""},{"name":"Boris Pankin","avatar":""},{"name":"Bashar Rahal","avatar":""},{"name":"Emilien De Falco","avatar":""},{"name":"Tim Man","avatar":""},{"name":"Andy Long Ngu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
