INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quyet-dau-4-boyka', 'Quyết Đấu 4: Boyka', 'Boyka: Undisputed IV', 'quyết đấu 4: boyka boyka: undisputed iv scott adkins teodora duhovnikova alon abutbul julian vergov martyn ford brahim achabbakhe paul chahidi petio petkov valentin ganev vlado mihailov vladimir kolev hristo petkov boris pankin bashar rahal emilien de falco tim man andy long ngu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-dai-chien-superman-anh-sang-cong-ly', 'Batman Đại Chiến Superman: Ánh Sáng Công Lý', 'Batman v Superman: Dawn of Justice', 'https://phimimg.com/upload/vod/20231019-1/40b2cd75b8405b51f42a912d53532515.jpg', 'https://phimimg.com/upload/vod/20231019-1/015a7255e2786e93e6a8df5d03e62264.jpg', '<p>Nội dung bộ phim sẽ xoay quanh cuộc đối đầu có 1-0-2 của vị hiệp sĩ mạnh mẽ, đáng gờm nhất của thành phố Gotham với biểu tượng được tôn sùng nhất của thành phố Metropolis. Nguyên nhân của “cuộc chiến” này bắt nguồn từ việc họ đang lo lắng vì không thể kiểm soát được siêu anh hùng mới có sức mạnh thần thánh. Tuy nhiên, trong lúc họ “mải miết” chiến đấu với nhau thì có một mối đe dọa khác đã nổi lên và đẩy nhân loại vào tình thế nguy hiểm hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Holly Hunter","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Tao Okamoto","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Lauren Cohan","avatar":""},{"name":"Brandon Spink","avatar":""},{"name":"Hugh Maguire","avatar":""},{"name":"Michael Cassidy","avatar":""},{"name":"Alan D. Purwi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
