INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('batman-dai-chien-superman-anh-sang-cong-ly', 'Batman Đại Chiến Superman: Ánh Sáng Công Lý', 'Batman v Superman: Dawn of Justice', 'batman đại chiến superman: ánh sáng công lý batman v superman: dawn of justice ben affleck henry cavill jesse eisenberg gal gadot amy adams diane lane jeremy irons holly hunter laurence fishburne callan mulvey scoot mcnairy tao okamoto jena malone lauren cohan brandon spink hugh maguire michael cassidy alan d. purwi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-ngay-em-den', 'Trước Ngày Em Đến', 'Me Before You', 'https://phimimg.com/upload/vod/20231018-1/04cc8e2fff8ebdc442d7a6e1d91c1ded.jpg', 'https://phimimg.com/upload/vod/20231018-1/0db4469eae005a059a90d09c151d7de4.jpg', '<p>Chuyện tình của cô gái 26 tuổi Louisa Clark sống ở một thị trấn cổ miền quê nước Anh. Lou là cô gái có phong cách ăn mặc màu mè khác biệt, không có phương hướng và ước mơ cá nhân cụ thể nào cả, dù rất vui vẻ lạc quan nhưng Lou lại phải vất vả làm việc để giúp đỡ gia đình khó khăn của mình. Công việc mới của Lou làm chăm sóc cho Will Traynor, một chủ nhà băng trẻ tuổi giàu có bị liệt nửa người và phải gắn chặt đời mình trên chiếc xe lăn. Tai nạn thảm khốc 2 năm trước đã biến Will từ một chàng trai mạnh mẽ phóng khoáng trở thành một người cố chấp, đầu hàng số phận. Cuộc gặp gỡ đã trở thành bước ngoặt làm thay đổi cuộc đời và trái tim của cả hai nhân vật.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emilia Clarke","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Brendan Coyle","avatar":""},{"name":"Jenna Coleman","avatar":""},{"name":"Matthew Lewis","avatar":""},{"name":"Samantha Spiro","avatar":""},{"name":"Stephen Peacocke","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Ben Lloyd-Hughes","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Lily Travers","avatar":""},{"name":"Alan Breck","avatar":""},{"name":"Eileen Dunwoodie","avatar":""},{"name":"Pablo Raybould","avatar":""},{"name":"Gabrielle D","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b03