INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-khong-sung', 'Người Hùng Không Súng', 'Hacksaw Ridge', 'https://phimimg.com/upload/vod/20231017-1/2df737e37b74088b161c310e937312e8.jpg', 'https://phimimg.com/upload/vod/20231017-1/f68ecaa1aebefccdde498d80a18b98e8.jpg', '<p>Phim kể lại cuộc đời của nhân vật có thật Desmond T. Doss - người lính từ chối cầm súng vì lý do tôn giáo. Nhưng ông vẫn trở thành anh hùng khi là một quân y, cứu sống 75 đồng đội trong cuộc chiến đẫm máu tại xứ sở hoa anh đào trong thời kỳ Thế chiến thứ II - Một trong những anh hùng vĩ đại nhất trong lịch sử nước Mỹ chưa bao giờ bắn một viên đạn.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Rachel Griffiths","avatar":""},{"name":"Ryan Corr","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"Goran D. Kleut","avatar":""},{"name":"Luke Pegler","avatar":""},{"name":"Firass Dirani","avatar":""},{"name":"Nathaniel Buzolic","avatar":""},{"name":"Ori Pfeffer","avatar":""},{"name":"Matt Nable","avatar":""},{"name":"Jacob Warner","avatar":""},{"name":"Richard Pyros","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324447);
