INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rogue-against-the-sky-tro-choi-cua-tram-ten-trom', 'Rogue Against the Sky: Trò chơi của trăm tên trộm', 'Rogue Against the Sky: The Game of a Hundred Thieves', 'null', 'https://phimimg.com/upload/vod/20231014-1/1cc88d5d7ef538febe1daa72d6e5262c.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Để tìm ra dấu vết của Arthur, nhóm bất hảo đã tấn công biệt thự Tề Thiên vào ban đêm, nhưng kết quả kết thúc trong thất bại. 4 thành viên của Nhóm Rogue buộc phải từ bỏ nhiệm vụ do báo động khởi hành, và ngay khi Nhóm Rogue được tổ chức lại, sự xuất hiện của Qi Gongzi đã nhen nhóm hy vọng của mọi người... Tề Công Tử thông báo cho Diệp Thiên biết, hắn đã tổ chức một bữa tiệc trộm cắp, Trò chơi trăm trộm, hy vọng sẽ chọn được thủ lĩnh của nhóm trộm thông qua cuộc thi, và người chiến thắng sẽ được thưởng hậu hĩnh. Tề Công Tử nồng nhiệt mời Diệp Thiên dẫn đầu đám lưu manh tham gia, nhưng Diệp Thiên vốn luôn kiêu ngạo, hoàn toàn khinh thường đánh nhau với nhóm trộm, Diệp Thiên không chịu đánh nhau với bọn trộm</span></p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Xiaotong","avatar":""},{"name":"Jia Zhengyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
