INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rogue-against-the-sky-tro-choi-cua-tram-ten-trom', 'Rogue Against the Sky: Trò chơi của trăm tên trộm', 'Rogue Against the Sky: The Game of a Hundred Thieves', 'rogue against the sky: trò chơi của trăm tên trộm rogue against the sky: the game of a hundred thieves yu xiaotong jia zhengyu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ngoc', 'Bố Ngốc', 'Silly Dad', 'https://phimimg.com/upload/vod/20231014-1/8abf8ecab617f612c11167aee5837c6a.jpg', 'https://phimimg.com/upload/vod/20231014-1/70456ec5caf779cc00811d0c5b540d8f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim &quot;Daddy&quot; là một bộ phim về đạo đức gia đình do Le Yingmeng sản xuất, đồng sản xuất và sản xuất bởi Fujian West Window Pictures, sản xuất bởi Đặng Tương Bình và đạo diễn bởi đạo diễn trẻ nổi tiếng Yang Musheng. Bộ phim chủ yếu kể về câu chuyện cha nuôi Lưu Lao Hi và con gái nuôi Lưu Hiểu Hoa lội ngàn dặm qua núi sông và vượt núi tìm người thân, bộ phim phản ánh bản chất con người, tình cảm gia đình, đạo đức và hiện thực xã hội thông qua những khúc quanh của hai nhân vật nhỏ để tìm người thân.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ở một thành phố ở phía nam, có một bậc thầy tên là Lưu Lao Hi, kiếm sống bằng cách đạp xe đạp ba bánh để thu hút khách hàng, năm nay ông đã ngoài năm mươi, và con gái ông Lưu Hiểu Hoa tám tuổi và vừa bước vào lớp hai. Lưu Hiểu Hoa là con gái của Lưu Lão Hi trở về từ thùng rác, từ khi vợ qua đời, anh và con gái đều dựa vào nhau, mỗi tháng đều dựa vào thu nhập thấp để trang trải cuộc sống hàng ngày và học phí của con gái.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Mỗi buổi tối, ông Lưu Lão Chi sẽ đi xe ba bánh đến &quot;nơi làm việc&quot; của mình khi con gái học xong, sau đó tiếp tục đạp xe gạ gẫm khách hàng kiếm tiền, cô con gái ngoan ngoãn cũng mỗi ngày đều cầm một chiếc bàn nhỏ để làm bài tập về nhà một cách nghiêm túc. Dù thu nhập thấp, cuộc sống eo hẹp nhưng tình cảm giữa cha và con gái lại là sự phụ thuộc nồng ấm vào nhau.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tuy nhiên, ông trời đã không đáp ứng được mong muốn của anh, và một ngày nọ, bác sĩ nói với Liu rằng anh bị bệnh nặng và gia đình không đủ khả năng chi trả chi phí điều trị cao. Lưu Thành thật nghĩ rằng mình sẽ chết sớm và rơi vào đau đớn: Sau khi anh ta ra đi, bông hoa nhỏ nhỏ nên làm gì? Cuối cùng, anh quyết định đưa đứa trẻ về với bố mẹ đẻ.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nếu máu tan thành nước, thì ân sủng nuôi dưỡng của người cha nuôi dành cho con gái mình trong những năm qua từ lâu đã mạnh mẽ hơn nhiều so với tình cảm gia đình này. Liu thực sự miễn cưỡng để con gái rời bỏ mình, nhưng so với sự miễn cưỡng này, tương lai của đứa trẻ quan trọng hơn. Vì vậy, người cha nuôi lớn tuổi đã đưa con gái đi bắt đầu hành trình tìm kiếm người thân, nhưng không ngờ, con gái cô bị bọn buôn người bắt cóc trên đường đi...</span></p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Qianghua","avatar":""},{"name":"Chen Ruohan (Baoer)","avatar":""},{"name":"Jiang Deliang","avatar":""},{"name":"Zhang Yier","avatar":""},{"name":"Feng Hui","avatar":""},{"name":"Tôn Tử Yến","avatar":""},{"name":"Đặng Tương Bình","avatar":""},{"name":"Đặng Vũ Xuân (Lele)","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324447);
