INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-nguoi-tot', 'Cảm Ơn Người Tốt', 'Good Man Thank You', 'null', 'https://phimimg.com/upload/vod/20231014-1/0abc0649d407313ade832d6ab6c3c937.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim này bắt đầu với cảnh quần chúng quét mộ con trai của Lei Tiyong vào năm 2011, dẫn đến những việc làm cá nhân của Lei Tiyong, con trai của Lei Tiyong qua đời vì bệnh bạch cầu vào năm 2007, trong quá trình điều trị, gia đình Lei Tiyong đã nhận được sự giúp đỡ từ mọi tầng lớp xã hội, và mọi người đã quyên góp gần 200 triệu nhân dân tệ, nhưng cuối cùng, con trai của Lei Tiyong vẫn bỏ đi, con trai hỏi cha mẹ trước khi chết, xã hội đã cho tôi quá nhiều tình yêu, con trai đang bước đi với tình yêu lớn của mọi người, tôi hy vọng rằng hai người lớn tuổi có thể dành nhiều tình yêu hơn cho trẻ em gặp khó khăn, Để thực hiện mong muốn cuối cùng của con trai và thực hiện lời hứa long trọng của mình, Lei Tiyong đã bắt đầu con đường đáp lại mong muốn của con trai mình. Bộ phim này bắt đầu với cảnh quần chúng quét mộ con trai của Lei Tiyong vào năm 2011, dẫn đến những việc làm cá nhân của Lei Tiyong, con trai của Lei Tiyong qua đời vì bệnh bạch cầu vào năm 2007, trong quá trình điều trị, gia đình Lei Tiyong đã nhận được sự giúp đỡ từ mọi tầng lớp xã hội, và mọi người đã quyên góp gần 200 triệu nhân dân tệ, nhưng cuối cùng, con trai của Lei Tiyong vẫn bỏ đi, con trai hỏi cha mẹ trước khi chết, xã hội đã cho tôi quá nhiều tình yêu, con trai đang bước đi với tình yêu lớn của mọi người, tôi hy vọng rằng hai người lớn tuổi có thể dành nhiều tình yêu hơn cho trẻ em gặp khó khăn, Để thực hiện mong muốn cuối cùng của con trai và thực hiện lời hứa long trọng của mình, Lei Tiyong đã bắt đầu con đường đáp lại mong muốn của con trai mình.</span></p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lei Tiyong","avatar":""},{"name":"Shen Zimeng","avatar":""},{"name":"Chen Meixi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324447);
