INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-trang-cua-sach-su-song-vinh-cuu', 'Căn Phòng Trắng Của Sách Sự Sống Vĩnh Cửu', 'White Room of the Book of Eternal Life', 'null', 'https://phimimg.com/upload/vod/20231013-1/0b51adc978ac98d6cd32ee1aae47c0a2.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bác sĩ tâm lý Kim Chi-bin là một trong số ít người trên thế giới nắm giữ bí mật của &quot;căn phòng trắng&quot;. Anh ta có thể giả mạo ký ức của người khác bằng cách nói chuyện với họ và bước vào căn phòng màu trắng của họ. Bạn thậm chí có thể đạt được sự sống vĩnh cửu bằng cách phá hủy nhân cách của người khác và do đó đi vào linh hồn của chính bạn.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Khi những vụ án kỳ lạ lần lượt xảy ra, điều tra viên tư nhân Liang Yan phát hiện ra sau khi điều tra rằng tất cả các manh mối đều chỉ về Jin Zhibin. Và mỗi khi anh ta nói chuyện với Kim Zhibin, trí nhớ của anh ta sẽ bị xóa, và cuộc điều tra sẽ kết thúc đột ngột.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Liang Yan sẽ tiết lộ bí mật của bác sĩ Jin cho chúng ta như thế nào?</span></p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Tianwen","avatar":""},{"name":"Long Shuilin","avatar":""},{"name":"Liu Ming","avatar":""},{"name":"Sun Mengchun","avatar":""},{"name":"Mou Wen","avatar":""},{"name":"Cổ Nguyệt Ninh","avatar":""},{"name":"Yamengle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324447);
