INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('can-phong-trang-cua-sach-su-song-vinh-cuu', 'Căn Phòng Trắng Của Sách Sự Sống Vĩnh Cửu', 'White Room of the Book of Eternal Life', 'căn phòng trắng của sách sự sống vĩnh cửu white room of the book of eternal life sun tianwen long shuilin liu ming sun mengchun mou wen cổ nguyệt ninh yamengle ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-nguoc-tam-ai-tinh-yeu-kin', 'Câu Chuyện Ngược Tâm Ái Tình : Yêu Kín', 'Tormenting Love Story: Hidden Love', 'null', 'https://phimimg.com/upload/vod/20231013-1/97409b9c13a0cb2b14f015bba676b23e.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong thế giới của nam chính Ngô Thiên Tường, chỉ có hai người quan trọng nhất. Một người là anh trai của mình là Wu Tianrui, và người kia là Shangguan Xue&#39;er, người phụ nữ duy nhất anh từng chạm vào. Tuy nhiên, tình yêu của Wu Tianxiang dành cho em trai đã làm hỏng em trai mình. Và tình yêu của Wu Tianxiang dành cho Shangguan Xue&#39;er cũng được đổi lấy sự phản bội hoàn toàn. Vài năm sau, Wu Tianxiang giúp em trai đuổi theo một cô gái, người biết rằng cô gái này là Thượng Quan Tuyết Nhĩ, người đã mất tích nhiều năm. Wu Tianxiang sợ rằng Thượng Quan Tuyết Nhĩ sẽ làm tổn thương em trai mình một lần nữa giống như anh ta đã làm tổn thương chính mình hồi đó, vì vậy anh ta giả vờ hòa giải với Thượng Quan Tuyết Nhĩ. Như mọi người đều biết, một cuộc khủng hoảng thậm chí còn lớn hơn đang âm thầm hình thành. Một bóng người kỳ lạ như ma luôn ẩn nấp bên cạnh Ngô Thiên Tường, giống như một linh hồn lang thang cả đời, nhìn chằm chằm Ngô Thiên Tường bằng một đôi mắt. Đối mặt với hận thù tích tụ mấy năm, tình yêu chưa bao giờ quên, Ngô Thiên Tường nên hòa hợp với Thượng Quan Tuyết Nhi như thế nào...</span></p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Qiancheng","avatar":""},{"name":"Kim Bohan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324447);
