INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-than-3-nguoi-kiem-soat', 'Cổ thần 3 : Người kiểm soát', 'Stock Master III: The Controller', 'null', 'https://phimimg.com/upload/vod/20231013-1/9ca974d078da9ed4419752619455ba38.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Đặng Khải, một cựu cao thủ trẻ tuổi giàu có, đã chứng kiến cha mình bị các đối tác của mình giết chết, và đã miệt mài nghiên cứu chứng khoán trong nhiều năm, muốn một ngày nào đó sử dụng phương pháp của riêng mình để trả thù cho cha mình. Khi anh ta đạt được một thành công nhỏ trên thị trường chứng khoán, Qiao Xiao, một nữ phóng viên đã giết anh ta giữa chừng, đã phá vỡ kế hoạch của anh ta. Dưới sự sử dụng lẫn nhau của hai người, họ đã tiến sâu vào tập đoàn Dongri, lợi dụng lòng tham của một số ông lớn, âm mưu và cạnh tranh với một số bên, và phương tiện cao nhất để xác định âm mưu là chống lại chất độc bằng thuốc độc. Cuối cùng đã đưa kẻ thù cũ của mình vào tù, đồng thời thấy rằng anh ta có một tình yêu sâu sắc dành cho nhau ...</span></p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tang Qin","avatar":""},{"name":"Zhu Ke","avatar":""},{"name":"Xiaomi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324447);
