INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-bac', 'Cờ Bạc', 'Gambler''s Redemption', 'null', 'https://phimimg.com/upload/vod/20231013-1/4ca2edbd380aae3984e6772900ee21cc.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Sự xuất hiện của nhà đầu tư Tai Long đã gây ra mâu thuẫn giữa hai anh em Yang Hai và Yang Xiao về việc liệu nhà hàng đầu bếp tư nhân mà họ điều hành có được mở rộng hay không. Dương Tiêu giới thiệu Tiêu Trần vào phòng bếp riêng theo sự xúi giục của Thái Long. Sau đó, Xiao Chen thiết kế Dương Hải đến Macau để nghiện cờ bạc, và cuối cùng nợ một khoản nợ cờ bạc khổng lồ, dẫn đến gia đình tan vỡ, và đầu bếp riêng phải bán Đài Long. Dương Hải tự sát với món nợ cờ bạc khổng lồ, chỉ có thể nhận nhiệm vụ cho vay nặng lãi nhờ anh giao hàng lên núi tuyết cao nguyên. Xiao Chen quyết định đi cùng nhau vì cảm giác tội lỗi. Trong môi trường khắc nghiệt của cao nguyên và núi tuyết, cả hai dựa vào nhau và dần nảy sinh tình cảm. Dọc theo đường đi, sự thanh lọc tâm hồn và môi trường khắc nghiệt khiến Dương Hải dần tỉnh táo lại. Mặc dù không hoàn thành nhiệm vụ, nhưng anh ta dám trở về Macau và đối mặt trực diện với mọi thứ. Tuy nhiên, điều chờ đợi anh là bàn tay đen đằng sau hậu trường, người thiết kế đủ loại bẫy...</span></p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liang Jiaren","avatar":""},{"name":"Liu Kesong","avatar":""},{"name":"Zhang Mengtian","avatar":""},{"name":"Yao Zheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324447);
