INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-bac', 'Cờ Bạc', 'Gambler''s Redemption', 'cờ bạc gambler''s redemption liang jiaren liu kesong zhang mengtian yao zheng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('angela-lala', 'Angela Lala', 'Angela Lala', 'null', 'https://phimimg.com/upload/vod/20231013-1/7a158fbbb287a477d1f9a9eeb51f7efa.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Mọi người đều có hai con đường sau khi chết, một lên thiên đàng và một đến nơi để đi. Nhưng điều đáng nói là không thể hối hận trước khi lên thiên đường, Wu Shu (do Kong Qingbing thủ vai), người đang mắc bệnh ung thư phổi, đã gặp thực tập sinh thiên thần Allala (do Từ Phi thủ vai) đến thế giới để thực hiện một nhiệm vụ khi anh ta tuyệt vọng và tự đánh bại bản thân. Allala muốn trở thành một thiên thần thực sự, vì vậy anh ta cố gắng hết sức để giúp Wu Shu bù đắp những hối tiếc đã để lại mười năm trước, và buộc anh ta phải trở lại khuôn viên thanh thiếu niên mười năm trước, chỉ để thấy rằng sự hối tiếc của Wu Shu là anh ta đã không tỏ tình với nữ thần yêu dấu của mình Zhen Mei (Qi Xiaoxue). Trong không gian này mười năm trước, bọn họ chỉ có bảy ngày để làm nhiệm vụ, liệu Ngô Thục có thể bù đắp cho sự tiếc nuối của mình và lên thiên đường hay không, liệu Allalla có thể thoát khỏi thân phận của một thiên thần thực tập sinh hay không, câu chuyện đang diễn ra trong tiếng cười.</span></p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Phi","avatar":""},{"name":"Kong Qingbing","avatar":""},{"name":"Qi Xiaoxue","avatar":""},{"name":"Liu Su","avatar":""},{"name":"Pang Yong","avatar":""},{"name":"Xu Xianren","avatar":""},{"name":"Cái Tử Kiệt","avatar":""},{"name":"Monliy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
