INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-jianger', 'Anh Hùng Jianger', 'Hero Jianger', 'null', 'https://phimimg.com/upload/vod/20231013-1/96eeb236d22bf919cc411c3179e73fee.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nó chủ yếu kể về câu chuyện của Jiang Geer, người đã bị thương bởi mũi tên Jiling của nhà thông thái trên đường đi tìm hộp kho báu Zhenguo do cha mẹ chính của mình để lại để đuổi theo 80.000 con ngựa màu lục lam và trắng của nhà thông thái ngực vàng. Con ngựa thần Anzan đã đưa Jangal bị thương đi hết con đường, nhưng bị chặn bởi những tên lính quỷ do quỷ vương phái đến, và Hunger và Scud nghe được tin tức và vội vã cứu Jangal trở lại trại Hercules. Hongel cầu xin mẹ cứu Jangal. Câu chuyện Jangal gây ấn tượng với bố chồng Rắn Trắng bằng lòng tốt và sự chân thành để có được hộp kho báu.</span></p>', 'Full', 1, 'hoathinh', 'completed', 18, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Jiayi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324447);
