INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cung-ban-cua-toi-la-tot-nhat', 'Bạn Cùng Bàn Của Tôi Là Tốt Nhất', 'My Sassy Deskmate', 'https://phimimg.com/upload/vod/20231013-1/2c45d167d96953df46d7cf56a5ae1092.webp', 'https://phimimg.com/upload/vod/20231013-1/479efa4afd5dd6476af933911f0ed4c9.webp', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Wang Yuan&#39;e&nbsp;</span><span class="" style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">(do Yuan Qiao thủ vai) luôn yêu sâu sắc một chàng trai tên là Chen Zhe, nhưng Wang Yuan&#39;e biết rằng cô ấy rất bình thường và khác xa với Chen Zhe, người tỏa sáng rực rỡ trong khuôn viên trường, vì vậy cô ấy chọn chôn vùi cảm giác này sâu trong trái tim mình. Cha của Shan Qiuxu đã gửi con trai mình vào lớp của Wang Yuan&#39;e và Chen Zhe, và mục đích của Shan Qiuxu rất đơn giản, đó là tốt nghiệp thành công, và sau đó ra nước ngoài để theo đuổi cuộc sống tự do của riêng mình.<br/>Tình cờ, một cuộc cãi vã đã nổ ra giữa Wang Yuan&#39;e và Shan Qiuxu, nhưng vì điều này, Shan Qiuxu đã có thể đi vào trái tim của Wang Yuan&#39;e, phát hiện ra khía cạnh đơn giản và tốt bụng của cô, và bị mê hoặc sâu sắc bởi nó. Tuy nhiên, toàn bộ tâm trí của Wang Yuan&#39;e đều treo trên cơ thể của Chen Zhe, điều này khiến Shan Qiuxu rất đau khổ.</span></p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Song Chen","avatar":""},{"name":"Yuan Qiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
