INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-va-ban-gai', 'Bạn Gái Và Bạn Gái', 'Happy Together', 'null', 'https://phimimg.com/upload/vod/20231013-1/3e5f557c6c55eeb5ba5ff9c79e1f2e3d.webp', '<p>Ai Ke (do Pan Ruoyao thủ vai) mơ ước trở thành người mẫu và đến New York để làm việc chăm chỉ, tuy nhiên, thực tế lạnh lùng quá tàn nhẫn so với lý tưởng bốc lửa, buộc phải kiếm sống, Ai Ke quyết định thuê hết căn nhà anh thuê để giảm áp lực tiền thuê nhà. Tuy nhiên, Ngải Kha là một người có tính cách nóng bỏng và trái tim thẳng thắn, vô số người đến xem nhà, và tất cả họ đều choáng váng trở lại bởi cái lưỡi độc của cô, Wu Yan (do Wu Xuanxuan thủ vai) là một trong số đó.</p><p>Wu trì hoãn việc lấy tiền thuê nhà một tháng làm tiền thuê nhà một năm, và kết quả là Ai Ke bị đuổi ra khỏi nhà, ai biết rằng ngày hôm sau, khi Ai Ke đi ra ngoài, anh ta nhìn thấy Wu Yan, người vô gia cư và ngủ ở cầu thang. Mặc dù Ngải Kha có cái miệng cứng rắn nhưng trái tim nhân hậu, cô không thể chịu đựng được khi thấy Ngô Diên đáng thương như vậy, vì vậy cuối cùng cô quyết định thuê ghế sofa trong phòng khách cho cô, và cứ như vậy, hai cô gái có tính cách rất khác nhau bắt đầu cuộc sống chung của họ.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pan Ruoyao","avatar":""},{"name":"Wu Xuanxuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
