INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-gai-va-ban-gai', 'Bạn Gái Và Bạn Gái', 'Happy Together', 'bạn gái và bạn gái happy together pan ruoyao wu xuanxuan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chong-nguoi-may', 'Anh Chồng Người Máy', 'Fatal Love', 'https://phimimg.com/upload/vod/20231012-1/df6ab61e76d37119cb6c126022ac211f.jpg', 'https://phimimg.com/upload/vod/20231012-1/b4acf7fe89193fa8eac2c7d16f7ad5a1.jpg', '<p>Cô cảm thấy có điều gì đó không ổn với chồng mình, nhưng cô không biết đó là điều gì. Một đêm nọ, cô chợt nhận ra anh hoàn toàn không phải là chồng cô, lẽ ra anh phải gọi là “nó” vì anh hoàn toàn không phải là con người. “Nó” là một robot thông minh, tác phẩm mới nhất của chồng tôi, một kỹ sư robot. Vì chồng cô đã mạnh dạn phá vỡ ba định luật của người máy nên toàn bộ quá trình nghiên cứu được giữ bí mật tuyệt đối nên giai đoạn cuối cùng của bài kiểm tra tương tác giữa người và máy chỉ có thể được giao cho cô, người đáng tin cậy nhất. Cô vô cùng suy sụp nhưng không thể chiến đấu nên không còn cách nào khác là phải cố gắng hòa hợp với con robot một thời gian. Trong mối quan hệ kỳ lạ này, sự phản kháng ban đầu của cô dần dần chuyển thành sự phụ thuộc và đánh giá cao, và cuối cùng cô thậm chí còn phát triển một loại cảm giác khác đối với người máy. Diễn biến sự việc quá bất ngờ, người chồng tức giận tìm đủ mọi cách để tra tấn, trừng phạt cô và con robot, đồng thời dùng những phương pháp cực kỳ lạnh lùng để chứng minh con robot không hề có cảm xúc. Ban đầu cô không tin nhưng sau nhiều thử thách, cô phải chấp nhận hiện thực tàn khốc. Robot không có cảm xúc và mọi thứ cô cảm nhận thực chất chỉ là ảo ảnh do hành vi bề mặt do chương trình tạo ra. Chán nản, cô tiêu diệt hoàn toàn con robot, chồng cô cuối cùng cũng nhận ra sự vô lý của mình và bày tỏ sự hối hận sâu sắc với cô. Cuộc sống tưởng như đã trở lại bình lặng vốn có, nhưng cô lại có vẻ bình tĩnh nhưng trên môi luôn nở một nụ cười khó nhận thấy. Một kế hoạch đã được ấp ủ từ lâu đang dần tiến triển theo tầm nhìn của cô...</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ren Xinyu","avatar":""},{"name":"Li Yanan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324447);
