INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tia-tui-la-cao-thu', 'Tía Tui Là Cao Thủ', 'Tía Tui Là Cao Thủ', 'null', 'https://phimimg.com/upload/vod/20231012-1/e65baccfeff482ef81023964f8a9dd6b.jpg', '<p>Bộ phim Tía Tui Là Cao Thủ xoay quanh câu chuyện về một gia đình làm nghề thuốc Đông y. Ông bà Nho Nhã sống yên vui, hạnh phúc bên bốn người con đều là những nam thanh nữ tú tại một vùng quê yên bình. Số tiền lớn có được từ việc đền bù đất đai của chính quyền đã khiến cuộc sống của gia đình ông bà Nho Nhã rơi vào những tranh luận, bất hòa. Bà Nhã đã quyết định bỏ lại chồng và đứa con trai út để lên thành phố. Nhưng cuộc sống nơi đất khách quê người không dễ dàng như mẹ con bà Nhã tưởng tượng. Ai sẽ là người giải cứu cho họ khỏi những cạm bẫy để trở lại cuộc sống yên bình trước đây?</p>', 'Full', 1, 'single', 'completed', 29, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hoài Linh","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Ái Phương","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Hoài Lâm","avatar":""},{"name":"Tấn Beo","avatar":""},{"name":"Cát Tường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324447);
