INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sai-gon-anh-yeu-em', 'Sài Gòn Anh Yêu Em', 'Saigon, I Love You', 'https://phimimg.com/upload/vod/20231012-1/3941691f7095db472caa74b0463b2da2.jpg', 'https://phimimg.com/upload/vod/20231012-1/0deceb4348b51d624bea0ebd35d097ad.jpg', '<p>Chuyện phim Sài Gòn Anh Yêu Em xoay quanh 5 câu chuyện, 10 nhân vật. Những câu chuyện tình lãng mạn, dễ thương và tính hài hước thể hiện tinh tế. Từng câu chuyện sẽ dẫn dắt người xem cảm nhận về mảnh đất Sài Gòn và những người yêu mến nó.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Thanh Nam","avatar":""},{"name":"Ngọc Giàu","avatar":""},{"name":"Maya","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Đoan Trang","avatar":""},{"name":"Johan Wicklund","avatar":""},{"name":"Phi Phung","avatar":""},{"name":"Huỳnh Lập","avatar":""},{"name":"Brian Trần","avatar":""},{"name":"Cường Đinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324447);
