INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-trai-tim', 'Sứ Mệnh Trái Tim', 'Sứ Mệnh Trái Tim', 'https://phimimg.com/upload/vod/20231012-1/e427335c2289a98613746116c2a19feb.jpg', 'https://phimimg.com/upload/vod/20231012-1/c28ddeec74de0b1df851e1c58654eb9e.jpg', '<p>Sứ Mệnh Trái Tim là câu chuyện về 7 người lính trẻ nhận nhiệm vụ rà phá bom mìn còn sót lại ở vùng biên giới. Giữa cuộc sống gian khổ của những chàng trai bỗng xuất hiện một bóng hồng xinh đẹp. Đó là Linh, cô giáo tiểu học vùng cao. Ngoài việc đề cao hình ảnh chịu thương chịu khó của những người lính, bộ phim còn được thổi thêm hơi thở tươi mới với câu chuyện tình lãng mạn nhưng cũng đầy sóng gió của cô giáo và anh lính Hoàng Bách. Phim có sự tham gia của nữ diễn viên nổi tiếng Angela Phương Trinh và trai đẹp vừa tấn công màn ảnh rộng Võ Cảnh.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Angela Phương Trinh","avatar":""},{"name":"Võ Cảnh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324447);
