INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('taxi-em-ten-gi', 'Taxi, Em Tên Gì?', 'Taxi, What''s Your Name?', 'https://phimimg.com/upload/vod/20231012-1/4587ee2875cbabea2e38f2eeb7910b34.jpg', 'https://phimimg.com/upload/vod/20231012-1/c0f69ce54e576ace809ee50d80820483.jpg', '<p>Taxi, Em Tên Gì? là bộ phim thuộc thể loại hài hành trình, kể lại câu chuyện đầy hài hước của anh chàng Thượng Phong – một tiến sỹ khoa học đãng trí chuyên nghiên cứu về bò sát và cô nàng tài xế taxi cá tính tên Bình Chi.&nbsp; Họ gặp nhau do Thượng Phong bị lỡ chuyến bay từ Sài Gòn về Đà Lạt, buộc phải bắt taxi lên tận xứ hoa cho kịp giờ cầu hôn bạn gái Hạ Mây. Trên đường đi, họ gặp biết bao chuyện dở khóc dở cười, thậm chí phải tấp vào…nhà nghỉ của một cặp vợ chồng kỳ quặc (diễn viên Chí Tài thủ vai).</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Thanh Thủy","avatar":""},{"name":"Angela Phương Trinh","avatar":""},{"name":"Phi Phung","avatar":""},{"name":"Trường Giang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
