INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-thu-an-danh', 'Cao Thủ Ẩn Danh', 'Cao Thủ Ẩn Danh', 'https://phimimg.com/upload/vod/20231011-1/1173e1297b4610ac6ca59fbef83f817a.jpg', 'https://phimimg.com/upload/vod/20231011-1/07d61d5f2b2f5d68b22962e25e5ddcc2.jpg', '<p>Cao Thủ Ẩn Danh một bộ phim hài hước do Việt Nam sản xuất kể về bà Năm &quot; hột gà &quot; một người phụ nữ hành nghề bán bột chiên dạo, thoạt nhìn trông bà có vẻ khắc khổ bương trải nhưng ít có ai biết đến được rằng bà Năm từng là một cao thủ võ lâm vì muốn tránh xa khỏi chốn thị phi giang hồ nên đã ẩn danh một thời gian và buôn bán bột chiên, sống hạnh phúc cùng cô con gái Bảo Yên. Lớn lên Bảo Yên trở thành một cô gái xinh đẹp và cực kì giỏi võ như mẹ mình, cô luôn muốn dùng sức mạnh của mình để bảo vệ những người nghèo và kẻ yếu. Để biết thêm xin mời các bạn theo dõi bộ phim này ngay sau đây nhé</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324447);
