INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fan-cuong', 'Fan Cuồng', 'Fan Cuồng', 'https://phimimg.com/upload/vod/20231011-1/d0cefd97f40a9c6efd4961972243733c.jpg', 'https://phimimg.com/upload/vod/20231011-1/4b26fda02a384ca5f3c7cabfa402859b.jpg', '<p>Thái (Thái Hòa) là fan ruột của chàng ca sĩ nổi tiếng Gia Nghị (Johnny Trí Nguyễn). Anh phát cuồng&nbsp; Gia Nghị đến mức quên cả đời sống cá nhân. Khi chàng ca sĩ gặp rắc rối, Thái chấp nhận quay ngược thời gian, trở về quá khứ để giúp đỡ thần tượng. Tuy nhiên, càng cố giúp, Thái càng làm mọi chuyện rối tung lên!</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Thái Hòa","avatar":""},{"name":"Johnny Nguyen","avatar":""},{"name":"Phương Trinh Jolie","avatar":""},{"name":"Huy Khánh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324447);
