INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('fan-cuong', 'Fan Cuồng', 'Fan Cuồng', 'fan cuồng fan cuồng thái hòa johnny nguyen phương trinh jolie huy khánh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-em-gan-anh-them-chut-nua', 'Cho Em Gần Anh Thêm Chút Nữa', 'Diary of Fireflies', 'https://phimimg.com/upload/vod/20231011-1/415e3cc2bdb6b1c4f0c611e7026adcba.jpg', 'https://phimimg.com/upload/vod/20231011-1/6f6542852676c71d9b254ccc6c05f55f.jpg', '<p>Bộ phim là câu chuyện nói về tình cảm giữa hai con người trẻ tuổi xuất phát từ sự thấu hiểu nhưng quyến rũ nhau nhờ sự khác biệt, và chính tình yêu cũng làm cho cả hai thay đổi, mở lòng hơn với cuộc sống và những người xung quanh. Kai (Đình Hiếu) là một anh chàng điển trai, tài giỏi nhưng đã từ bỏ việc học trong trường Y và luôn giấu mình trong thư viện bởi cái chết của mẹ mình. Chuỗi ngày lặng lẽ của anh bị phá vỡ với sự xuất hiện của Rin (Jun Vũ), một cô nàng mê chụp ảnh và tràn đầy năng lượng sống. Rin đã giúp Kai tìm lại ý nghĩa cuộc sống qua một hành trình khám phá những điều mới lạ, đầy thú vị. Nhưng chính lúc đó, cũng là lúc Kai nhận ra thân phận “kỹ nữ máu” ẩn sâu bên trong con người Rin.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jun Vũ","avatar":""},{"name":"Võ Đình Hiếu","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Lê Thiện","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Võ Quang Minh","avatar":""},{"name":"Hồng Đào","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324447);
