INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-em-gan-anh-them-chut-nua', 'Cho Em Gần Anh Thêm Chút Nữa', 'Diary of Fireflies', 'cho em gần anh thêm chút nữa diary of fireflies jun vũ võ đình hiếu kiều minh tuấn lê thiện khả như võ quang minh hồng đào ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-bao-su', 'Hải Báo Sư', 'The Posterist', 'https://phimimg.com/upload/vod/20231010-1/174c90ebfcf59d206b317aef8a579fa6.jpg', 'https://phimimg.com/upload/vod/20231010-1/96dffeac6683dd0050439495d2c6e3d3.jpg', '<p>Ông Yuen Tai-Yung (sinh năm 1941) là một nghệ sĩ Trung Quốc nổi tiếng với việc tạo ra hơn 200 áp phích phim Hồng Kông mang tính biểu tượng - bao gồm nhiều bộ phim của Lý Tiểu Long, Anh em Hui, Châu Tinh Trì, Thành Long và võ thuật của Hồng Kim Bảo. phim hài. Bộ phim tài liệu này ghi lại hành trình tìm kiếm người chủ ẩn dật của đạo diễn và những cuộc gặp gỡ sau đó với người đàn ông đó trong khoảng thời gian 12 tháng. Nó ghi lại cuộc đời và nghệ thuật của thiên tài tự học, người đã một mình khắc họa diện mạo và cảm nhận về những gì có thể được mô tả là Kỷ nguyên vàng của Điện ảnh Hồng Kông từ năm 1975 đến năm 1992. Khán giả phương Tây có thể nhận ra một số gương mặt quen thuộc từ các họa sĩ nổi tiếng này. những tác phẩm gần đây - không thể phủ nhận là ngoạn mục - chẳng hạn như chân dung của Marlon Brando, Michael Jackson, James Dean, John Lennon, Audrey Hepburn và Anne Hathaway.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Yuen Tai-Yung","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Joe Cheung Tung-cho","avatar":""},{"name":"Michael Hui","avatar":""},{"name":"John Chong","avatar":""},{"name":"Wing-Shing Ma","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324447);
INSERT OR IGNORE INTO movie_categories (movie_slug, category_slug) VALUES ('hai-bao-su', 'tai-lieu');
