INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-bao-su', 'Hải Báo Sư', 'The Posterist', 'hải báo sư the posterist yuen tai-yung kenny bee joe cheung tung-cho michael hui john chong wing-shing ma ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-suong-mu', 'Bí ẩn sương mù', 'Edge Of Suspect', 'https://phimimg.com/upload/vod/20231009-1/d0e0f53692bbd7f920092fc15c78300d.jpg', 'https://phimimg.com/upload/vod/20231009-1/58edcc8aa5a04b01d08fb1e33a42db85.jpg', '<p>Vụ án giết người rạch cổ kỳ lạ đưa nhà phân tích hình sự xinh đẹp Li Wen đến một thị trấn đầy sương mù, cô giỏi phân tích tâm lý tội phạm và có mối bất hòa nghiêm trọng với thủ lĩnh nhóm hành động Lôi Áo. Tuy nhiên, những vụ án giết người rạch cổ vẫn tiếp tục xảy ra , và người cố vấn bí ẩn cũng bất ngờ can thiệp. Lý Văn cảm giác được trong đám người có người đang nhìn trộm mình, nhưng khi quay lại lại không phát hiện được gì. Một con chim hai đầu chết tại hiện trường đã thu hút sự chú ý của cô... &quot;White Mist Mysterious Shore&quot; là bộ phim điều tra tội phạm đô thị kết hợp giữa hồi hộp và tội phạm nghệ thuật. Các yếu tố hồi hộp được thể hiện đến mức tối đa, Quá trình điều tra và những gợi ý của kẻ sát nhân đã được thêm vào, tốn rất nhiều công sức về đạo cụ, nghệ thuật và trang điểm, bố cục và màu sắc của các cảnh quay cũng được theo đuổi đến mức tối đa, trở thành &quot;phiên bản Trung Quốc của&quot; Sự im lặng của bầy cừu &quot;. &quot;Bờ biển sương trắng huyền bí&quot; lọt vào danh sách đơn vị phim truyện ăn khách nhất của Liên hoan phim thanh niên lần thứ 10 Tây Ninh</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vian Wang","avatar":""},{"name":"Zhang Zixuan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324447);
