INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-an-suong-mu', 'Bí ẩn sương mù', 'Edge Of Suspect', 'bí ẩn sương mù edge of suspect vian wang zhang zixuan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-doi-dau-2', 'Điệp Vụ Đối Đầu 2', 'Cold War 2', 'https://phimimg.com/upload/vod/20231008-1/17712d236688fff05ddb510b2d14905a.jpg', 'https://phimimg.com/upload/vod/20231008-1/4382761a6dddcd1e553fa3a3ced6110f.jpg', '<p>Bộ phim lấy bối cảnh một thời gian sau cuộc giải cứu thành công 5 nhân viên cảnh sát bị bắt cóc. Phó Cục trưởng Cục Cảnh sát Lưu Kiệt Huy (Quách Phú Thành thủ vai) được đề bạt lên vị trí người đứng đầu của Lực lượng cảnh sát Hồng Kông. Tuy nhiên, sự biến mất của chiếc xe cảnh sát được trang bị những công nghệ tối tân vẫn còn là một ẩn số. Trong lúc vụ án tưởng chừng như rơi vào trạng thái bế tắc, một mối đe doạ mới lại ập tới với Lưu Kiệt Huy khi vợ của anh đã bị bắt cóc ngay giữa thanh thiên bạch nhật. Những kẻ thủ ác đã ra tối hậu thư yêu cầu anh phải thả ngay Lý Văn Ảnh – kẻ tình nghi đang bị giam giữ để đổi lại sự tự do cho người vợ của mình. Kiệt Huy sẽ giải quyết tình huống ấy ra sao và liệu còn có rắc rối nào đang chờ anh phía trước?</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Aarif Rahman","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Chang Kuo-Chu","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Frankie Lam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324447);
