INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-sat-2016', 'Truy Sát', 'Truy Sát', 'truy sát truy sát truong ngoc anh marcus guilhem mike leeder trung ly antony nguyen hiếu nguyễn thiên nguyen cường seven maria tran lâm vissay ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-sat-nhan', 'Nhật Ký Sát Nhân', 'Killing A Diary', 'https://phimimg.com/upload/vod/20231006-1/f2c8aaab826eaaf0ef7622fd1e18c151.jpg', 'https://phimimg.com/upload/vod/20231006-1/54dbb4872feb419bd54411608a01b087.webp', '<p>Nghệ sĩ Ye Xiaoman đã trở thành thành viên của đội thần tượng dưới sự chăm sóc chu đáo của người đại diện Song Xi. Tuy nhiên, khoảng thời gian tốt đẹp đó không kéo dài được lâu, đội nữ mà cô tham gia đang đứng trước nguy cơ giải thể, Ye Xiaoman phải rời đội, chuyển sang làm thần tượng. một diễn viên, và đảm nhận vai diễn đầu tiên trong đời. Có một bộ phim tên là &quot;The Ghost in the Heart&quot;. Là một nghệ sĩ thần tượng hóa thân, mọi người đều nhìn Ye Xiaoman bằng cặp kính màu. Trong khi Ye Xiaoman đang chật vật và chán nản thì anh ấy lại cũng liên tiếp nhận được những lá thư đe dọa, điều này gây áp lực rất lớn cho anh. Quản lý Tống Hi đưa lá thư của fan cho Diệp Tiểu Mạn, khi Diệp Tiểu Mạn về nhà, cô mở thư ra thì phát hiện trong thư có ghi một trang web riêng tên là Nhật ký của Diệp Tiểu Mạn, trong nhật ký ghi lại tâm trạng mỗi ngày của Diệp Tiểu Mạn. và nhiều chi tiết khác nhau. Diệp Tiểu Mạn nhớ lại những gì viết trong nhật ký đều là sự thật, hình như chính anh đã viết và giọng nói của chính anh cũng được viết trong nhật ký, Diệp Tiểu Mạn bắt đầu hoảng sợ, dường như có một đôi mắt nào đó đang nhìn chằm chằm vào anh suốt cả ngày. thời gian trong cuộc đời anh ấy, và anh ấy dường như có thể nhìn thấy thực tế trong trạng thái xuất thần, nhìn thấy một bản thân khác trong không gian. Chậm rãi đến gần mình, lúc này Diệp Tiểu Mạn ánh mắt đột nhiên tối sầm...</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Xinzhu","avatar":""},{"name":"Wang Zige","avatar":""},{"name":"Bi Yucheng","avatar":""},{"name":"Jiang Yushunfei","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324447);
