INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gang-tay-do', 'Găng Tay Đỏ', 'Red Gloves', 'https://phimimg.com/upload/vod/20230928-1/cacb6367fc1c58e8121a981286d1b0e9.jpg', 'https://phimimg.com/upload/vod/20230928-1/4738b83233dfb1b6ee324b4d34ee67ec.jpg', '<p>Trong phim, một tổ chức sát thủ Quốc tế cử No.7 về Việt Nam để ám sát ông trùm Huỳnh Đại. Nhiệm vụ của nữ sát thủ này thất bại do sự can thiệp kịp thời của tay đàn em thận cận của Huỳnh Đại là Trần Thông. Lọt giữa vòng vây kẻ địch, cô tình cờ được Hồng Việt cứu thoát. Trong khoảng thời gian trốn truy lùng của Huỳnh Côn, con trai Huỳnh Đại, và cảnh sát Việt Nam, giữa hai người dần nảy sinh tình cảm. Tổ chức sát thủ cũng phái No.3, người bạn từ thời thơ ấu của No.7, sang hoàn thành nhiệm vụ và tiêu diệt luôn cô. Trước tình thế&nbsp;</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ninh Dương Lan Ngọc","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Lâm Vinh Hải","avatar":""},{"name":"Quang Sự","avatar":""},{"name":"Hiếu Nguyễn","avatar":""},{"name":"Trần Tuấn Lương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324447);
