INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mafia-tran-chien-sinh-tu', 'Mafia: Trận Chiến Sinh Tử', 'Mafia: Survival Game', 'https://phimimg.com/upload/vod/20230926-1/15e0d34bde41d665a2507864d0d640bd.jpg', 'https://phimimg.com/upload/vod/20230926-1/26e9fa28cf2ca65024d839cf1d74fbc3.jpg', '<p>Phim Trận Chiến Sinh Tử - Mafia: Survival Game 2016: Những ai là fan ruột của The Hunger Games, có lẽ khó mà bỏ qua siêu phẩm mới đến từ nước Nga mang tên Mafia: Survival Game (Mafia: Trận Chiến Sinh Tử). Qua bộ phim của đạo diễn trẻ tài năng Sarik Andreasyan, người xem sẽ được trải nghiệm lại cảm giác thót tim, khi nhìn những thí sinh tham gia vào trò chơi tương tác đáng sợ, trải qua những thử thách chết người trong cuộc chiến đẫm máu để giữ lấy mạng của mình.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Viktor Verzhbitskiy","avatar":""},{"name":"Venyamin Smekhov","avatar":""},{"name":"Vyacheslav Razbegaev","avatar":""},{"name":"Olga Tumaykina","avatar":""},{"name":"Andrey Chadov","avatar":""},{"name":"Yuriy Chursin","avatar":""},{"name":"Violetta Getmanskaya","avatar":""},{"name":"Artem Suchkov","avatar":""},{"name":"Natalya Rudova","avatar":""},{"name":"Stepan Yurpalov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
