INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-cuu-roi-chung-ta', 'Chúa Cứu Rỗi Chúng Ta', 'May God Save Us', 'https://phimimg.com/upload/vod/20230926-1/aaca9a117f3f1ab58b963720ee382501.jpg', 'https://phimimg.com/upload/vod/20230926-1/db380933c2af1f7d62f33f8d13f43092.jpg', '<p>Madrid, mùa hè năm 2011. Khủng hoảng kinh tế. Phong trào 15 triệu người và 1,5 triệu người hành hương đang chờ đợi sự xuất hiện của Giáo hoàng sống cạnh nhau ở Madrid đang nóng hơn và hỗn loạn hơn bao giờ hết. Trong bối cảnh này, các thám tử Velarde và Alfaro phải tìm ra kẻ có vẻ là kẻ giết người hàng loạt. Cuộc săn lùng suốt ngày đêm của họ sẽ khiến họ nhận ra một điều mà họ chưa bao giờ tưởng tượng: cả hai đều không khác lắm với kẻ giết người.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Antonio de la Torre","avatar":""},{"name":"Roberto Álamo","avatar":""},{"name":"Javier Pereira","avatar":""},{"name":"Luis Zahera","avatar":""},{"name":"Raúl Prieto","avatar":""},{"name":"María Ballesteros","avatar":""},{"name":"Teresa Lozano","avatar":""},{"name":"Rocío Muñoz-Cobo","avatar":""},{"name":"José Luis García Pérez","avatar":""},{"name":"Mónica López","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324447);
