INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-xac-pham-tuc', 'Thân Xác Phàm Tục', 'We Are the Flesh', 'https://phimimg.com/upload/vod/20230915-1/ee19accdf53aa629602dc797f3b93503.jpg', 'https://phimimg.com/upload/vod/20230915-1/f00fee06f48a64c7ee902af3a7703e80.jpg', '<p>Sau khi lang thang trong một thành phố đổ nát trong nhiều năm để tìm kiếm thức ăn và nơi trú ẩn, hai anh em tìm được đường vào một trong những tòa nhà cuối cùng còn sót lại. Bên trong, họ tìm thấy một người đàn ông sẽ đưa ra lời đề nghị nguy hiểm cho họ để sống sót ở thế giới bên ngoài.</p>', 'Full', 1, 'single', 'completed', 30, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"María Evoli","avatar":""},{"name":"Noé Hernández","avatar":""},{"name":"María Cid","avatar":""},{"name":"Diego Gamaliel","avatar":""},{"name":"Gabino Rodríguez","avatar":""},{"name":"Jonathan Miralda","avatar":""},{"name":"Andrés Villalobos","avatar":""},{"name":"Claudette Maillé","avatar":""},{"name":"Jessica Janet Martínez","avatar":""},{"name":"Jazael Olguín Zapata","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324447);
