INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chang-trai-ngoan', 'Những Chàng Trai Ngoan', 'The Nice Guys', 'https://phimimg.com/upload/vod/20230915-1/172f319175414a24b44a7b9b191d0acf.jpg', 'https://phimimg.com/upload/vod/20230915-1/c403b57fb1d1acd12996af136d625625.jpg', '<p>Một thám tử tư điều tra vụ tự tử rõ ràng của một ngôi sao khiêu dâm đang lụi tàn ở Los Angeles những năm 1970 và phát hiện ra một âm mưu.</p>', 'Full', 1, 'single', 'completed', 30, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"Angourie Rice","avatar":""},{"name":"Margaret Qualley","avatar":""},{"name":"Kim Basinger","avatar":""},{"name":"Yaya DaCosta","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Keith David","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Lois Smith","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324447);
