INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-am-nhac', 'Đấu Trường Âm Nhạc', 'Sing', 'https://phimimg.com/upload/vod/20230914-1/41368b9763d84e91d85ec3bddf125d29.jpg', 'https://phimimg.com/upload/vod/20230914-1/1afe1b4088553a96c440cb8d9cef1d8e.jpg', '<p><span style="font-family: ">Lấy bối cảnh trong thế giới của loài vật, &quot;Đấu Trường Âm Nhạc&quot; chính là hành trình khám phá bản thân của 5 nhân vật khác nhau đó là chú chuột Mike, bé voi Meena, cô heo Rosita, chú khỉ Johnny và nàng nhím Ash. Cả 5 người sẽ cùng nhau tham gia cuộc thi ca hát do chú gấu túi Buster tổ chức với giấc mơ được đổi đời. Mặc dù mục đích ban đầu của họ đều hướng tới khoản tiền thưởng giá trị nhưng cuối cùng điều quý giá nhất họ nhận được lại chính là những bài học ý nghĩa và đầy tính nhân văn.</span></p>', 'Full', 1, 'hoathinh', 'completed', 31, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Taron Egerton","avatar":""},{"name":"Tori Kelly","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Garth Jennings","avatar":""},{"name":"Peter Serafinowicz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324447);
