INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-the-mang-2015', 'Kẻ Thế Mạng', 'Self/less', 'https://phimimg.com/uploads/movies/20260710/ke-the-mang-2015-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/ke-the-mang-2015-poster.webp', '<p>Phim kể về Damian Hale, một tỷ phú rất ít khi sống cùng con gái là Claire và người thường xuyên bên cạnh Damian là ông bạn già, cánh tay phải Martin O’Neil.  Đứng trước căn bệnh ung thư không thể cứu chữa, Damian quyết định tìm đến một phương pháp y học hoàn toàn mới có tên gọi “đổi xác” để duy trì sự sống. Giáo sư Albright là người giúp Damian hoàn thành ước nguyện khi thực hiện thành công quy trình chuyển đổi ý thức của Damian sang cơ thể một chàng trai khỏe mạnh.  Với một cơ thể mới, một cuộc sống mới ở New Orleans, Damian rất thoải mái với nhân dạng mới mang tên “Edward” và kết bạn với một người địa phương tên là Anton. Tuy nhiên, Damian bắt đầu đối mặt với thử thách khi những ký ức của cơ thể mới bắt đầu hiện ra, mạnh dần và có xu hướng xóa sổ ý thức của Damian.  Liệu Damian có thể tìm hiểu được chuyện gì đang xảy ra và bảo vệ mạng sống của mình?</p>', 'Full', 1, 'single', 'completed', 42, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Natalie Martinez","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Melora Hardin","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Sam Page","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Mariana Paola Vicente","avatar":""},{"name":"Jaynee-Lynne Kinchen","avatar":""},{"name":"Brendan McCarthy","avatar":""},{"name":"Thomas Francis Murphy","avatar":""},{"name":"Sandra Ellis Lafferty","avatar":""},{"name":"Emily Tremaine","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Inmortal","Selfless","Self-Less","Self Less","Sem Retorno","Eternal","換命法則","Immortel","In/Mortal","Selfless – Der Fremde in Mir","Renaissances","セルフレス 覚醒した記憶","換命遊戲","უცხო სხეულში","თავდაუზოგავი","Self/less"]', 1784690324447);
