INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-dam-mau', 'Lâu Đài Đẫm Máu', 'Crimson Peak', 'https://phimimg.com/uploads/movies/20260710/lau-dai-dam-mau-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/lau-dai-dam-mau-poster.webp', '<p>Tuổi thơ của nữ nhà văn Edith (Mia Wasikowska) dường như không hề êm đẹp như bao cô cậu bé khác. Mỗi khi đêm đến, Edith thường được các hồn ma “không mời mà tới” ghé thăm. Đó cũng chính nguồn cảm hứng giúp cô viết nên những câu chuyện kì lạ vốn chưa có lời giải đáp. Một ngày nọ, người đàn ông bí ẩn với vẻ ngoài lịch lãm Thomas (Tom Hiddleston) xuất hiện và bày tỏ niềm yêu thích đặc biệt những trang sách của Edith.  Tuy nhiên, điều này lại khiến cho Alan - người bạn thơ ấu của Edith, ngờ vực về lý do thực sự hắn ta tiếp cận cô. Mặc cho lời cảnh báo, Edith đèm lòng yêu Thomas say đắm. Cô chấp nhận lời cầu hôn và chuyển về sống cùng Thomas và chị gái Lucille (Jessica Chastain) tại một ngôi nhà cổ cách xa thành phố. Tưởng chừng cuộc hôn nhân sẽ giải thoát Edith khỏi sự đeo bám của các hồn ma trong quá khứ, cô lại tiếp tục rơi vào trạng thái hoảng loạn bởi những hiện tượng kì lạ xảy ra bên trong ngôi nhà này…</p>', 'Full', 1, 'single', 'completed', 55, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mia Wasikowska","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Charlie Hunnam","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Leslie Hope","avatar":""},{"name":"Jonathan Hyde","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Bruce Gray","avatar":""},{"name":"Emily Coutts","avatar":""},{"name":"Alec Stockwell","avatar":""},{"name":"Brigitte Robinson","avatar":""},{"name":"Gillian Ferrier","avatar":""},{"name":"Tamara Hope","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["A Colina Escarlate","La cumbre escarlata","Crimson Peak: A Colina Vermelha","Пурпурният връх","血色庄园","腥红山庄","크림슨 피크","ปราสาทสีเลือด","Crimson Peak"]', 1784690324447);
