INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh', 'Tình', 'Love', 'https://phimimg.com/uploads/movies/20260710/tinh-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/tinh-poster.webp', '<p>Trên khía cạnh nội dung, một số nhà phê bình cho rằng Gaspar Noé đơn giản chỉ muốn miêu tả sự hủy hoại và đau đớn khi yêu một ai đó thông qua Love. Toàn bộ câu chuyện trong phim được kể lại qua hồi tưởng của nhân vật chính Murphy (Karl Glusman), sau khi anh này nhận được cuộc điện thoại cho biết bạn gái cũ Electra (Aomi Muyock) đã mất tích.  Lúc này, Murphy cảm thấy chán chường trong cuộc hôn nhân với Omi (Klara Kristin). Anh cứ thế hồi tưởng lại quãng thời gian hạnh phúc và điên rồ bên Electra, cũng như không ngừng tự hỏi điều gì sẽ xảy ra nếu như số phận không chia cắt họ.  Buổi chiếu của Love kết thúc lúc 3 giờ sáng và bộ phim nhận được nhiều tràng pháo tay từ khán phòng sau khi kết thúc. Trong năm nay, hãng Alchemy sẽ đem bộ phim tới thị trường Bắc Mỹ …</p>', 'Full', 1, 'single', 'completed', 53, 2015, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Karl Glusman","avatar":""},{"name":"Aomi Muyock","avatar":""},{"name":"Klara Kristin","avatar":""},{"name":"Ugo Fox","avatar":""},{"name":"Juan Saavedra","avatar":""},{"name":"Gaspar Noé","avatar":""},{"name":"Isabelle Nicou","avatar":""},{"name":"Benoît Debie","avatar":""},{"name":"Vincent Maraval","avatar":""},{"name":"Déborah Révy","avatar":""},{"name":"Xamira Zuloaga","avatar":""},{"name":"Stella Rocha","avatar":""},{"name":"Omaima S.","avatar":""},{"name":"Nikita Bellucci","avatar":""},{"name":"Angell Summers","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Szerelem","Ljubezen","爱恋3D","러브","Любовь","Love 3D","爱恋","Gaspar  Noé''s Love","Aşk","Love: Amor en 3D","LOVE 3D","Любов","Ljubav","Mīlestība","Meilė","Dragoste","Љубав","Láska","性本愛","Sevgi","Սեր","Ser","Love"]', 1784690324447);
