INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cat-an-thit-nguoi', 'Cát Ăn Thịt Người', 'The Sand', 'https://phimimg.com/upload/vod/20260701-1/105bff3f25fb87b2ffed4fbf9ca3a166.jpg', 'https://phimimg.com/upload/vod/20260701-1/aa66df2ed3bf5ae5570889c067cfb925.jpg', '<p>Sau một bữa tiệc tốt nghiệp thâu đêm suốt sáng bên bờ biển, một nhóm học sinh tỉnh dậy dưới ánh mặt trời thiêu đốt với cái đầu choáng váng vì say xỉn, để rồi bàng hoàng nhận ra quân số của mình đã bị hao hụt. Một sinh vật ngoài hành tinh khổng lồ đã đào sâu và ẩn nấp dưới bãi cát, và bất kỳ ai dại dột chạm chân xuống cát đều phải phó mặc mạng sống cho một biển xúc tu ăn thịt người tàn bạo. Liệu họ có thể trốn thoát khỏi móng vuốt khát máu của con quái vật này?</p>', 'Full', 1, 'single', 'completed', 60, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brooke Serene Butler","avatar":""},{"name":"Cleo Berry","avatar":""},{"name":"Cynthia Murell","avatar":""},{"name":"Dean Geyer","avatar":""},{"name":"Meagan Holder","avatar":""},{"name":"Mitchel Musso","avatar":""},{"name":"Nikki Leigh","avatar":""},{"name":"Hector David Jr.","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Bryan Boone","avatar":""},{"name":"Etalvia Cashin","avatar":""},{"name":"Jennifer Churchich","avatar":""},{"name":"Randi Krasny","avatar":""},{"name":"Adam Powell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Пясъкът","Blood Sand","Killer Beach","Песок","Th