INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau-2015', 'Thám Tử Phố Tàu', 'Detective Chinatown', 'https://phimimg.com/upload/vod/20260628-1/4514612fb30ed0a582b9def79618388b.jpg', 'https://phimimg.com/upload/vod/20260628-1/f3862656e996453e41a12318fb351b3c.jpg', '<p>Tần Phong - Thiếu niên bẩm sinh có tật nói lắp (Lưu Ngô Nhiên đóng) vì thi trượt trong kì thi vào trường cảnh sát nên được bà ngoại đưa tới Thái Lan, chỗ ở của Đường Nhân - cậu họ &quot;bủn xỉn&quot; của mình (Vương Bảo Cường đóng) còn gọi là &quot;Đệ nhất thần thám Đường Nhân Đường&quot; để giải buồn. Sau một đêm trụy lạc, Đường Nhân vô tình trở thành nghi phạm giết người, và phải cùng Tần Phong chạy trốn. Bộ phim có sự xuất hiện của các cảnh sát điều tra Hoàng Lan Đăng biệt hiệu Chó điên (Trần Xích đóng), cảnh sát may mắn biệt hiệu Thằng ngốc (Tiêu Ương đóng); &quot;Bộ ba tên cướp&quot; nham hiểm tàn ác, bí ẩn khó dò; &quot;Bố già Đường Nhân Đường&quot; sâu xa khôn lường cùng với bà chủ xinh đẹp quyến rũ. Bảy ngày! Trong 7 ngày, cặp đôi oan gia ngõ hẹp Đường Nhân - Tần Phong bắt buộc phải hợp tác, hỗ trợ lẫn nhau để đánh thắng kẻ thù.</p>', 'Full', 1, 'single', 'completed', 47, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Bảo Cường","avatar":""},{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Đồng Lệ Á","avatar":""},{"name":"Trần Hách","avatar":""},{"name":"Tiêu Ương","avatar":""},{"name":"Tiểu Thẩm Dương","avatar":""},{"name":"Phan Việt Minh","avatar":""},{"name":"Mã Dục Kha","avatar":""},{"name":"Trương Tử Phong","avatar":""},{"name":"Kim Sĩ Kiệt","avatar":""},{"name":"Đại Bằng","avatar":""},{"name":"Tang Bình","avatar":""},{"name":"Triệu Anh Tuấn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tang Ren Jie Tan An","Detective Chintang","Detective Chin Tang","唐人街·探案","僕はチャイナタウンの名探偵","唐人街探偵 THE BEGINNING","Detective Chinatown 1","唐人街探案"]', 1784690324447);
