INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hung-thu-bien-mat', 'Hung Thủ Biến Mất', 'The Vanished Murderer', 'hung thủ biến mất the vanished murderer lau ching-wan jiang yiyan gordon lam ka-tung guo xiaodong li xiaolu rhydian vaughan paulyn sun qie lutong hidy yu jonathan kos-read wang cheng lau shun li dong xiao shi de xiong shou xiao shi de zi dan 2 the murderer vanishes the bullet vanishes 2 消失的子弹2 siu sat dik hung sau siu sat dik ji daan 2 消失的兇手', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chap-va', 'Chắp vá', 'Patchwork', 'https://phimimg.com/upload/vod/20260617-1/9873be484ea3511a4d1314dad2bf0562.jpg', 'https://phimimg.com/upload/vod/20260617-1/0e203e9629517feaf171e2617c8236ba.jpg', '<p>Một bộ phim hài kinh dị đen tối đầy thú vị lấy cảm hứng từ Frankenstein, kể về một xác chết được hồi sinh từ các bộ phận cơ thể khâu lại của ba cô gái trẻ bị sát hại, quyết định dấn thân vào một cuộc hành trình đẫm máu để tìm kẻ giết họ và trả thù cho cái chết của họ!</p>', 'Full', 1, 'single', 'completed', 49, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Tory Stolper","avatar":""},{"name":"Tracey Fairaway","avatar":""},{"name":"Maria Blasucci","avatar":""},{"name":"Natalie Turpin","avatar":""},{"name":"Corey Sorenson","avatar":""},{"name":"Amanda Markowitz","avatar":""},{"name":"Luke Lanza","avatar":""},{"name":"Melissa Nearman","avatar":""},{"name":"James Phelps","avatar":""},{"name":"Amanda Lund","avatar":""},{"name":"Eric Edelstein","avatar":""},{"name":"Danny Jolles","avatar":""},{"name":"Craig Anstett","avatar":""},{"name":"Mark Hapka","avatar":""},{"name":"Jon Rudnitsky","avatar":""},{"name":"Seth Cassell","avatar":""},{"name":"Aaron Webman","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Patchwork"]', 1784690324447);
