INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-thu-44', 'Đứa Trẻ Thứ 44', 'Child 44', 'https://phimimg.com/upload/vod/20260617-1/833b8e6d007a4b84e152e62eb0867c1e.jpg', 'https://phimimg.com/upload/vod/20260617-1/7319c12f3b0c0f8a39baf65ff3dbb815.jpg', '<p>Lấy bối cảnh ở Liên Xô thời Stalin, một sĩ quan KGB thất sủng được cử đi điều tra hàng loạt vụ giết trẻ em - vụ án bắt đầu liên quan đến lãnh đạo cấp cao nhất của đảng.</p>', 'Full', 1, 'single', 'completed', 24, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Fares Fares","avatar":""},{"name":"Joel Kinnaman","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Mark Lewis Jones","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Nikolaj Lie Kaas","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Xavier Atkins","avatar":""},{"name":"Karel Dobrý","avatar":""},{"name":"Agnieszka Grochowska","avatar":""},{"name":"Petr Vaněk","avatar":""},{"name":"Jana Stryková","avatar":""},{"name":"Ursina Lardi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Crímenes ocultos","System: Child 44","Номер 44","El niño 44","El ninyo 44","チャイルド44 森に消えた子供たち","失控獵殺 ： 第 44 個孩子","Crimes Ocultos","Дете 44","Dijete 44","A 44. gyermek","Yeled 44","Child 44 - Il bambino n. 44","Berns Nr. 44","44. Çocuk","Child 44"]', 1784690324447);
