INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-len-thuc-tap-sinh', 'Cố lên Thực Tập Sinh', 'Best Get Going', 'https://phimimg.com/upload/vod/20260611-1/5e0dbd0b4f0c410b040a65f45bf46678.jpg', 'https://phimimg.com/upload/vod/20260611-1/929e774e706e90c8f5cbb8334fbffd14.jpg', '<p>Bộ phim là cuộc hành trình đi thực tập của các sinh viên vừa mới tốt nghiệp. Trong lòng mỗi người đều tràn đầy nhiệt huyết chờ mong, muốn va chạm thực tế, lăn lộn với xã hội nhưng hiện thực tàn khốc, mọi khó khăn và thử thách cùng lúc ập đến, khiến họ phải đối diện và vượt qua. Bên cạnh đó, bộ phim còn là câu chuyện tình “oan gia ngõ hẹp” của Tống Noãn và công tử nhà giàu Trương Thịnh. Ngoài ra, bộ phim còn mượn đề tài tình yêu để kể những câu chuyện về tình bạn. Có thể nói, Cố lên thực tập sinh đã thổi cho các bạn sinh viên vừa ra trường một ngọn lửa nhiệt huyết mãnh liệt, thôi thúc các bạn cố gắng và đối mặt với khó khăn...</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 28, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"riệu Lệ Dĩnh","avatar":""},{"name":"Trịnh Khải","avatar":""},{"name":"Thái Văn Tịnh","avatar":""},{"name":"Trịnh Gia Bân","avatar":""},{"name":"Xa Hiểu","avatar":""},{"name":"Vương Cơ","avatar":""},{"name":"Vu Tiểu Vĩ","avatar":""},{"name":"Canh Lạc","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Vương Chỉ Huyên","avatar":""},{"name":"Phó Tĩnh","avatar":""},{"name":"Vương Mậu Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["奔跑吧实习生","Best Get Going","加油吧实习生"]', 1784690324447);
