INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-di-the-ky', 'Bước Đi Thế Kỷ', 'The Walk', 'https://phimimg.com/upload/vod/20260608-1/85703ca3894de4e2423f019bece5f8f7.jpg', 'https://phimimg.com/upload/vod/20260608-1/6e18122668f9db801258513cbdd7d196.jpg', '<p>Bộ phim The Walk lấy cảm hứng từ ước mơ “bước trên những đám mây” của nghệ sĩ bạo gan Philippe Petit người Pháp, người đã thực hiện đi thăng bằng giữa 2 tòa tháp đôi của Trung tâm Thương mại Thế giới – biểu tượng đầy tự hào của nước Mỹ và cũng là tòa nhà cao kỷ lục vào những năm 1970. Để thực hiện được “cuộc dạo chơi” có một không hai này, Petit đã ấp ủ kế hoạch chinh phục trong suốt 6 năm và mạo hiểm cả mạng sống của mình, bất chấp mọi ngăn cấm về luật pháp.</p>', 'Full', 1, 'single', 'completed', 58, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Charlotte Le Bon","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Clément Sibony","avatar":""},{"name":"César Domboy","avatar":""},{"name":"Benedict Samuel","avatar":""},{"name":"Ben Schwartz","avatar":""},{"name":"Steve Valentine","avatar":""},{"name":"Mark Camacho","avatar":""},{"name":"Sergio Di Zio","avatar":""},{"name":"Kwasi Songui","avatar":""},{"name":"Melantha Blackthorne","avatar":""},{"name":"Jason Blicker","avatar":""},{"name":"Larry Day","avatar":""},{"name":"Karl Graboshas","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["To Walk the Clouds","To Reach the Clouds","The Walk (3D)","The Walk - 3D","El desafio (The Walk)","El desafío","The Walk"]', 1784690324447);
