INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buoc-di-the-ky', 'Bước Đi Thế Kỷ', 'The Walk', 'bước đi thế kỷ the walk joseph gordon-levitt ben kingsley charlotte le bon james badge dale clément sibony césar domboy benedict samuel ben schwartz steve valentine mark camacho sergio di zio kwasi songui melantha blackthorne jason blicker larry day karl graboshas to walk the clouds to reach the clouds the walk (3d) the walk - 3d el desafio (the walk) el desafío the walk', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-am-sat-phan-1', 'Lớp Học Ám Sát (Phần 1)', 'Assassination Classroom (Season 1)', 'https://phimimg.com/upload/vod/20260608-1/4c5dc00672f5780b5cc57fa3f62d5a44.jpg', 'https://phimimg.com/upload/vod/20260608-1/fa9f99693f33998c1e55400fc71fc568.jpg', '<p>Bạn phải làm gì nếu một ngày kia, khi đang ngồi trong lớp học, một con bạch tuộc da xanh bước vào lớp và nói Từ bây giờ tôi sẽ là thầy các em. Nhiệm vụ của các từ bây giờ đến hết năm học là giết tôi. Nếu không tôi sẽ cho nổ tung Trái Đất? Phim chỉ dành cho đối tượng trên 13 tuổi. Các học sinh lớp 3-E có 1 nhiệm vụ, đó là ám sát giáo viên của họ trước khi tốt nghiệp. Ông ta đã phá hủy mặt trăng, và hứa hẹn rằng trong vòng 1 năm nếu không ai giết được mình, ông ta sẽ hủy diệt luôn cả Trái Đất. Nhưng làm sao mà cái lớp học chỉ có toàn những học sinh không thích nghi được với ngoại cảnh này, có thể giết được một con quái vật xúc tu có khả năng đạt tới tốc độ 20 Mác, người mà rất có thể là giáo viên giỏi nhất mà họ từng có.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 24, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Mai Fuchigami","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Aya Suzaki","avatar":""},{"name":"Ayaka Suwa","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Chie Matsuura","avatar":""},{"name":"Eiji Miyashita","avatar":""},{"name":"Fuuko Saito","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Junji Majima","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Kouki Harasawa","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Megumi Ogata","avatar":""},{"name":"Miho Hino","avatar":""},{"name":"Mi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["极速老师","章鱼老师","Ansatsu Kyoushitsu","Assassination Classroom","אססיניישן קלאסרום","Classe assassina","Ansatsu Kyoutetsu","Invincible Teacher","อัสแซสซิเนชันคลาสรูม","暗殺教室"]', 1784690324447);
