INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bao-thu-3', 'Cô Gái Báo Thù 3', 'I Spit on Your Grave 3: Vengeance Is Mine', 'https://phimimg.com/upload/vod/20260602-1/9c0f04b9ea6be454b7692eabe376bbb9.jpg', 'https://phimimg.com/upload/vod/20260602-1/937e4331ebc0c57cd5fd6a847df9a1ce.jpg', '<p>Phim Người Đẹp Báo Thù 3 cốt truyện phim tiếp nối theo câu chuyện của năm 2010, sau khi báo thù thành công, Jennifer quay trở về và xin vào làm việc cho một công ty chuyên xử lý vấn đề nóng, khủng hoảng với đường dây nóng chạy 24/24. Không lâu sau, cảnh sát phát hiện một tên giết người hàng loạt đang lợi dụng đường dây nóng này để truy lùng và hạ sát những tên biến thái, hiếp dâm. Quá khứ của Jenifer cùng những hành động kì quặc khiến các thám tử và điều tra viên đặt cô vào diện nghi vấn. Nhưng liệu rằng cô là kẻ giết người hàng loạt đó hay còn ai đó đang nhởn nhơ ngoài kia?</p>', 'Full', 1, 'single', 'completed', 29, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Butler","avatar":""},{"name":"Jennifer Landon","avatar":""},{"name":"Jeff Branson","avatar":""},{"name":"Harley Jane Kozak","avatar":""},{"name":"Karen Strassman","avatar":""},{"name":"Alissa Juvan","avatar":""},{"name":"Megan Raich","avatar":""},{"name":"Doug McKeon","avatar":""},{"name":"Gabriel Hogan","avatar":""},{"name":"Michelle Hurd","avatar":""},{"name":"Russell Pitts","avatar":""},{"name":"Walter Perez","avatar":""},{"name":"Christopher Hoffman","avatar":""},{"name":"Andrew Dits","avatar":""},{"name":"Adam Dunnells","avatar":""},{"name":"Lony''e Perrine","avatar":""},{"name":"Bobby","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Escupiré sobre tu tumba 3","Bez litości 3","Cô Gái Báo Thù 3","Məzarına Tüpürəcəm 3","I Spit on Your Grave 