INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-heck-phan-7', 'Gia đình Heck (Phần 7)', 'The Middle (Season 7)', 'https://phimimg.com/upload/vod/20260516-1/291d44b1743b8e40d6b51815904f0ab6.jpg', 'https://phimimg.com/upload/vod/20260516-1/7a480ede23bff5b7f0749415cd2f556d.jpg', '<p>Mùa thứ bảy đầy thành công của Middles chứng kiến gia đình Heck vượt ra khỏi vùng an toàn và đối mặt với những tình huống mới lạ hơn so với những gì họ thường gặp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patricia Heaton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Eden Sher","avatar":""},{"name":"Atticus Shaffer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["左右不逢源","中产家庭","中之道","Anyám borogass","Családom és egyéb emberfajták","ザ・ミドル ～中流家族のフツーの幸せ～","คุณแม่สามัญประจำบ้าน","The Middle"]', 1784690324447);
