INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-ky-dai-chuong-quy', 'Truyền Kỳ Đại Chưởng Quỹ', 'The Legendary Restaurateur', 'https://phimimg.com/upload/vod/20260515-1/2e066cc230404844cb8019d0b374d404.jpg', 'https://phimimg.com/upload/vod/20260515-1/dc038631f5e995a609d2d596d4976df0.jpg', '<p>Bộ phim kể về câu chuyện của Loan Học Đường từ một gã ăn xin lang thang từ Sơn Đông đến Bắc Kinh trải qua muôn vàn khó khăn gây dựng nên cửa tiệm Phong Trạch Viên có tiếng trăm năm ở Bắc Kinh. Năm 1919 Loan Học Đường từ Sơn Đông lưu lạc đến Bắc Kinh, nhờ cứu con gái của ông chủ Tế Phong Lâu mà được làm hầu bàn trong tiệm. Tuy nhiên sau đó anh bị đuổi vì biết được bí mật của ông chủ, nhưng lại vô tình được quý nhân trợ giúp sáng lập nên cửa tiệm Phong Trạch Viên...</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 27, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Gu Zhixin","avatar":""},{"name":"He Bing","avatar":""},{"name":"Yang Lixin","avatar":""},{"name":"Liang Guanhua","avatar":""},{"name":"Li Guangfu","avatar":""},{"name":"Han Tongsheng","avatar":""},{"name":"Yu Yuan","avatar":""},{"name":"Huang Wei","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Zhang Guangbei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chuan Qi Da Zhang Gui","The Legendary Restaurateur","传奇大掌柜"]', 1784690324447);
