INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-ho-den-roi', 'Mẹ Hổ Đến Rồi', 'Tiger Mum', 'https://phimimg.com/upload/vod/20250306-1/a8b8342e6345f58ca2c80dc1f4ac66fa.jpg', 'https://phimimg.com/upload/vod/20250306-1/7df6204f53620edc0e65eb08471749e3.jpg', '<p>Câu chuyện kể về một người cha góa vợ từ sớm, một mình nuôi dạy bốn đứa con có tính cách khác nhau. Anh quyết định tái hôn, nhưng đối tượng lại là một nữ quản giáo nghiêm khắc, cứng rắn và kỷ luật thép. Gia đình ngày càng xa cách, bọn trẻ mỗi đứa đều có vấn đề riêng. Liệu &quot;mẹ hổ&quot; này có thể vượt qua thử thách từ các con và giúp gia đình này hồi sinh hay không?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 28, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Singapore', 0, '[{"name":"Huang Biren","avatar":""},{"name":"Yao Wenlong","avatar":""},{"name":"Julie Tan","avatar":""},{"name":"Ian Fang","avatar":""},{"name":"Aloysius Pang","avatar":""},{"name":"Bonnie Loo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tiger Mum","虎妈来了"]', 1784690324447);
