INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-tinh-yeu-2015', 'Nữ thần tình yêu', 'Goddess of Love', 'https://phimimg.com/upload/vod/20260318-1/608a189fcd556dce40cfa09c3f38c91b.jpg', 'https://phimimg.com/upload/vod/20260318-1/fcd717f8e9b3e5d9d28a08ceeb35e825.jpg', '<p>Bước vào vòng xoáy điên loạn đầy màu sắc khi một người phụ nữ bất ổn về mặt cảm xúc bị suy sụp sau nỗi đau khổ tột cùng. Brian là tình yêu của đời Venus, và ý nghĩ anh ta ngoại tình với người phụ nữ khác đã khởi đầu cho sự sa sút không kiểm soát của cô vào mặt tối của chứng điên loạn tâm thần tình dục.</p>', 'Full', 1, 'single', 'completed', 51, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Alexis Kendra","avatar":""},{"name":"Elizabeth Sandy","avatar":""},{"name":"Monda Scott","avatar":""},{"name":"Woody Naismith","avatar":""},{"name":"Ray Grady","avatar":""},{"name":"Richard Velton","avatar":""},{"name":"Hugh Westbourne","avatar":""},{"name":"Rachel Alig","avatar":""},{"name":"Deana Ricks","avatar":""},{"name":"Anna Logan","avatar":""},{"name":"Kendall Foote","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["The Dark Side of Venus","Goddess of Love"]', 1784690324447);
