INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mune-chien-binh-mat-trang-mune-le-gardien-de-la-lune', 'Mune: Chiến Binh Mặt Trăng (Mune, le gardien de la lune)', 'Mune: Guardian Of The Moon', 'https://phimimg.com/upload/vod/20260303-1/6b508af890259d120f618efdbb779178.jpg', 'https://phimimg.com/upload/vod/20260303-1/80f6cb4c801a1390283e733f0fc04dc2.jpg', '<p>MUNE: Chiến Binh Mặt Trăng - Khán giả sẽ đến với thế giới huyền ảo tít tên tận... mặt trăng, nơi có những sinh vật như Mune, chỉ quen với bóng tối, Glim cô bé người sáp tan chảy dưới ánh sáng ban ngày và đông lại thành hình vào ban đêm, cùng Sohone cứng rắn vì người làm từ hổ phách. &nbsp;Một sai lầm của Mune đã bị phe bóng tối Hắc Thần chớp lấy cơ hội đánh cắp mặt trời, khiến thế giới ngày đêm hòa làm một, sống trong hỗn mang. Lúc này &quot;kẻ được chọn&quot; là Mune ý thức mình có trọng trách giành lại ánh sáng cho thế giới...</p>', 'Full', 1, 'single', 'completed', 24, 2015, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Michaël Grégorio","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Izïa Higelin","avatar":""},{"name":"Féodor Atkine","avatar":""},{"name":"Éric Herson-Macarel","avatar":""},{"name":"Michel Mella","avatar":""},{"name":"Fabrice Josso","avatar":""},{"name":"Patrick Poivey","avatar":""},{"name":"Jean-Claude Donda","avatar":""},{"name":"Benoît Allemane","avatar":""},{"name":"Patrick Préjean","avatar":""},{"name":"Damien Boisseau","avatar":""},{"name":"Patrice Dozier","avatar":""},{"name":"Emmanuel Curtil","avatar":""},{"name":"Paolo Domingo","avatar":""},{"name":"Alexandre Heboy","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Milo: Månens Vokter","Muun, kuu valvur","뮨-달의 요정","Mune","ミューン 月の守護者の伝説","Mune, le gardien de la lune"]', 1784690324447);
