INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-7', 'Quá Nhanh Quá Nguy Hiểm 7', 'Furious 7', 'https://phimimg.com/upload/vod/20260225-1/fcd3765abe00b239089f2a8f82db6036.jpg', 'https://phimimg.com/upload/vod/20260225-1/e094a5a61ce3a8aa6e30526daacea01b.jpg', '<p>Trong phần này kẻ ác Ian Shaw quyết định cho những đối thủ của mình phải tắm máu, vì em trai anh ta đã bị Dominic Toretto (Vin Diesel) và nhóm của anh giết chết trong Fast and Furious 6. Một số nguồn tin còn tiết lộ rằng: sẽ có một cuộc chiến lớn giữa Ian Shaw và nhân vật của Dwayne Johnson trong phim. Phim Quá Nhanh Quá Nguy Hiểm 7 do James Wan làm đạo diễn, với sự góp mặt của Vin Diesel, Paul Walker, Jason Statham, Dwayne Johnson, Michelle Rodriguez, Jordana Brewster và Tyrese Gibson. Tài tử Paul Walker qua đời khi bộ phim đang được thực hiện và các em trai của anh quyết định tham gia đóng thế trong những cảnh quay chưa được hoàn thành.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vin Diesel","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Tony Jaa","avatar":""},{"name":"Ronda Rousey","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Iggy Azalea","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff