INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('max-dien-con-duong-tu-than', 'Max Điên: Con Đường Tử Thần', 'Mad Max: Fury Road', 'https://phimimg.com/upload/vod/20260214-1/c7eae7c8c5b22b66cf60f34924a3f3d3.jpg', 'https://phimimg.com/upload/vod/20260214-1/7a8cc2da852a2e790bc5c3a6b8718a3f.jpg', '<p>Mad Max: Fury Road đưa người xem đến với một thế giới hậu tận thế điêu tàn, chỉ còn lại sa mạc và những cuộc đụng độ giữa các phiến quân. Max đang trên đường chạy trốn quá khứ đau thương vì mất vợ và con. Tình cờ, anh gặp một cô gái trẻ Furiosa với mong muốn trở về nhà. Max quyết định giúp đỡ cô, đồng nghĩa với việc trở thành kẻ thù của một băng cướp khét tiếng. Mad Max thực chất là phần 4 của loạt phim được đánh giá cao vào những năm 80, cũng được đạo diễn bởi George Miller ...</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'FHD', 'Úc', 1, '[{"name":"Tom Hardy","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Hugh Keays-Byrne","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Rosie Huntington-Whiteley","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Abbey Lee","avatar":""},{"name":"Courtney Eaton","avatar":""},{"name":"John Howard","avatar":""},{"name":"Richard Carter","avatar":""},{"name":"Iota","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Jennifer Hagan","avatar":""},{"name":"Megan Gale","avatar":""},{"name":"Melissa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":