INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-vong-sinh-tu-3-co-lap', '12 Vòng Sinh Tử 3: Cô Lập', '12 Rounds 3: Lockdown', 'https://phimimg.com/upload/vod/20260126-1/e58178a7ec1f0f453cf29bdefbfe5e19.jpg', 'https://phimimg.com/upload/vod/20260126-1/f548cd24e9fb1e498d4f4970af071df2.jpg', '<p>Lockdown Follow - một sĩ quan cảnh sát đã trở về nhà an toàn sau khi bị bắn trong lúc tìm ra những bằng chứng để buộc tội những hoạt động bất hợp pháp của những người mà anh quen biết. Anh dần nhận ra rằng mình đang rơi vào một cái bẫy, bị truy bắt và quyết tìm cho ra sự thật. Liệu anh có tìm lại được những chứng cứ quan trọng đó để đưa ra ánh sáng?</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Good","avatar":""},{"name":"Roger Cross","avatar":""},{"name":"Daniel Cudmore","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Sarah Smyth","avatar":""},{"name":"Lee Tomaschefski","avatar":""},{"name":"Rebecca Marshall","avatar":""},{"name":"Courtney Hojenski","avatar":""},{"name":"Avery Konrad","avatar":""},{"name":"Sharon Taylor","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Toby Levins","avatar":""},{"name":"Andrew Herr","avatar":""},{"name":"Kirby Morrow","avatar":""},{"name":"Samuel Smith","avatar":""},{"name":"James Michalopolous","avatar":""},{"name":"Jaeson Lee","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["12 kol 3","12 kol 3: Lockdown","12 Balas","12 Trampas 3: Lockdown","12 Rounds 3: Lockdown","12 раундов 3: Блокировка"]', 1784690324447);
