INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-thay-hoa-vang-tren-co-xanh', 'Tôi Thấy Hoa Vàng Trên Cỏ Xanh', 'Yellow Flowers On the Green Grass', 'tôi thấy hoa vàng trên cỏ xanh yellow flowers on the green grass thịnh vinh trọng khang lam thanh my my anh mai thế hiệp cong huan duc sang mai tran le vinh truong tu lien anh tu khánh hiền le thi y. duyen hoang thuy le binh thai hoang anh dung phan tấn thi sa bao nguyen tan le thanh tung quang van yellow flowers on green grass dear brother 초록 들판의 노란 꽃들 sárga virágok a zöld mezőn 草原に黄色い花を見つける flori galbene în câmpia verde желтые цветы на зеленой траве 绿地黄花 tôi thấy hoa vàng trên cỏ xanh', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buong-tha', 'Buông Thả (Tiếng Gọi Con Tim)', 'Trainwreck', 'https://phimimg.com/upload/vod/20260122-1/07b0b82b035f0974014dedec8b967c77.jpg', 'https://phimimg.com/upload/vod/20260122-1/3b947fc932c770f796459ea3e863a334.jpg', '<p>Nữ nhà báo trẻ Amy sống buông thả và không tin vào các mối quan hệ lâu dài, nên dù đang hẹn hò với Steven vẫn qua lại với nhiều người khác. Tại tòa soạn, cô bị giao viết bài về bác sĩ Aaron Conners, dù gần như không biết gì về thể thao. Từ những buổi gặp gỡ công việc, cả hai dần nảy sinh tình cảm qua hàng loạt tình huống dở khóc dở cười. Lần đầu tiên, Amy cảm nhận được một mối quan hệ nghiêm túc và chân thành, điều trước nay luôn né tránh. Giữa lối sống tự do và khát khao được yêu thật sự, cô phải đối diện với chính mình để lựa chọn con đường hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amy Schumer","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"LeBron James","avatar":""},{"name":"Colin Quinn","avatar":""},{"name":"Mike Birbiglia","avatar":""},{"name":"Evan Brinkman","avatar":""},{"name":"John Cena","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Vanessa Bayer","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Jon Glaser","avatar":""},{"name":"Amar''e Stoudemire","avatar":""},{"name":"Dave Attell","avatar":""},{"name":"Norman Lloyd","avatar":""},{"name":"Method Man","avatar":""},{"name":"Claudia O''D","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Descompensada","เจอที่ใช่หัวใจตกราง","姐姐愛最大","나를 미치게 하는 여자","Esta Chica es un Desastre","Aşk Kazası","Trainwreck"]', 1784690324447);
