INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-kinh-di-my-phan-5-hotel', 'Truyện Kinh Dị Mỹ (Phần 5) (Hotel)', 'American Horror Story (Season 5)', 'truyện kinh dị mỹ (phần 5) (hotel) american horror story (season 5) emma roberts matt czuchry kim kardashian annabelle dexter-jones michaela jaé rodriguez denis o''hare cara delevingne julie white maaz ali história de horror americana uma história de horror americana 美恐 american horror story - die dunkle seite in dir american horror story: la casa del crimen סיפור אימה אמריקאי アメリカン・ホラー・ストーリー 아메리칸 호러 스토리 американская история ужасов американська історія жахів american horror story: freak show ahs hotel american horror story: hotel ahs american horror story: murder house american horror story: asylum american horror story: coven american horror story: roanoke american horror story: cult american horror story: apocalypse american horror story: 1984 american horror story: double feature american horror story: red tide american horror story: death valley american horror story: nyc american horror story: delicate american horror story', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-cuoi-cung-phan-1', 'Vương Triều Cuối Cùng (Phần 1)', 'The Last Kingdom (Season 1)', 'https://phimimg.com/upload/vod/20260112-1/60c10e74ba2a51bd5eec1105f38e5feb.jpg', 'https://phimimg.com/upload/vod/20260112-1/aeb73133b447abf4daab9e2117a23d33.jpg', '<p>Một bộ phim về những chiến công anh hùng và những trận chiến hoành tráng với chiều sâu chủ đề bao gồm chính trị, tôn giáo, chiến tranh, lòng dũng cảm, tình yêu, lòng trung thành và hành trình tìm kiếm bản sắc chung của chúng ta. &nbsp;Kết hợp các nhân vật và sự kiện lịch sử có thật với các nhân vật hư cấu, đó là câu chuyện về cách một dân tộc kết hợp sức mạnh của họ dưới một trong những vị vua nổi tiếng nhất lịch sử để khai hoang đất đai cho chính họ và xây dựng một nơi mà họ gọi là quê hương.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2015, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexander Dreymon","avatar":""},{"name":"Emily Cox","avatar":""},{"name":"Eliza Butterworth","avatar":""},{"name":"Mark Rowley","avatar":""},{"name":"Ruby Hartley","avatar":""},{"name":"Cavan Clerkin","avatar":""},{"name":"Arnas Fedaravičius","avatar":""},{"name":"Harry Gilby","avatar":""},{"name":"Timothy Innes","avatar":""},{"name":"Stefanie Martini","avatar":""},{"name":"Phia Saban","avatar":""},{"name":"Adrian Schiller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sonuncu Krallıq","Последното кралство","O Último Reino","孤国春秋","最后的王国","Το Τελευταίο Βασίλειο","最後的王國","Pos