INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-lan-chet-hut', 'Ba Lần Chết Hụt', 'Kill Me Three Times', 'https://phimimg.com/upload/vod/20260109-1/61eca2123311d9ab64dc73128d54d95d.jpg', 'https://phimimg.com/upload/vod/20260109-1/f84a0aa0949b73dc54a1c71946d85079.jpg', '<p>Trong một phi vụ tưởng chừng như thường lệ, một sát thủ chai lì phát hiện ra rằng anh ta không phải là mục tiêu duy nhất của mình.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Simon Pegg","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Luke Hemsworth","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Bryan Brown","avatar":""},{"name":"Steve Le Marquand","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Kill Me 3x","Tue moi 3 fois","Confusões a Triplicar","הרוג אותי 3 פעמים","Kill Me Three Times"]', 1784690324447);
