INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-lan-chet-hut', 'Ba Lần Chết Hụt', 'Kill Me Three Times', 'ba lần chết hụt kill me three times simon pegg teresa palmer sullivan stapleton alice braga luke hemsworth callan mulvey bryan brown steve le marquand kill me 3x tue moi 3 fois confusões a triplicar הרוג אותי 3 פעמים kill me three times', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thi-baahubali-khoi-nguyen', 'Sử Thi Baahubali: Khởi Nguyên', 'Bāhubali: The Beginning', 'https://phimimg.com/upload/vod/20260108-1/c2e620bdb320b7cd5b376cc226b1e323.jpg', 'https://phimimg.com/upload/vod/20260108-1/f7ffb92881265676c1135ffa47f066d1.jpg', '<p>Sử Thi Baahubali được làm dựa trên bộ sử thi nổi tiếng của Ấn Độ, bất đầu phim từ lúc thái hậu Sivagami dù đang bị thương nặng nhưng không để đứa bé sơ sinh rời khỏi vòng tay của mình. Bà trút hơi thở cuối cùng với lời cầu nguyện cho cậu bé sống sót vì vương quốc. Đứa bé được tìm thấy và nuôi dưỡng bởi bộ lạc Shiva sống cạnh một thác nước khổng lồ. Cậu tên là Shivudu và lớn lên với một sức mạnh thiên bẩm kỳ lạ. Đứa con nuôi Shiva có thể leo thoăn thoắt trên vách núi dựng đứng nơi có thác nước khổng lồ và luôn tò mò về việc liệu trên đỉnh núi có những gì. Người mẹ nuôi đã làm tất cả những gì có thể, kể cả làm phép và cầu nguyện, để cậu con trai nuôi ngừng việc chinh phục ngọn núi nhưng bất thành. Cuộc đời của Shivudu thay đổi khi anh gặp Avantika, một cô gái xinh đẹp là một thành viên của nhóm các chiến binh nổi dậy đang nỗ lực để giải phóng nữ hoàng của họ là Devasena, đang bị giam giữ suốt 25 năm qua bởi kẻ độc ác Bhallala Dev và cha của hắn. Shivudu thực ra là con trai của hoàng tử Amarendra Baahubali – người cạnh tranh với Bhallala Deva trong cuộc chiến giành ngai vàng. Sau khi đánh bại đội quân xâm lược trong một trận chiến sử thi, Amarendra được đưa lên làm vua nhưng đã bị giết hại. Trong ngục tù, mặc dù chân tay bị xiềng xích nhưng hoàng hậu Devasena vẫn cố gắng sống với niềm hy vọng một ngày nào đó sẽ gặp lại con trai của mình. Khi biết rõ mình có mối liên hệ với vương triều Mahishmati, Shivudu cũng đã tìm ra sứ mệnh của anh là giải cứu nữ hoàng và báo thù cho cha.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Rana Daggubati","avatar":""},{"name":"Tamannaah Bhatia","avatar":""},{"name":"Anushka Shetty","avatar":""},{"name":"Ramya Krishnan","avatar":""},{"name":"Nassar","avatar":""},{"name":"Sathyaraj","avatar":""},{"name":"Prabhakar","avatar":""},{"name":"Adivi Sesh","avatar":""},{"name":"Sudeepa","avatar":""},{"name":"Rohini","avatar":""},{"name":"Ramakrishna Meka","avatar":""},{"name":"Tanikella Bharani","avatar":""},{"name":"Charandeep","avatar":""},{"name":"Rakesh Varre","avatar":""},{"name":"Teja Kakumanu","avatar":""},{"name":"Bharani Shankar","avatar":""},{"name":"John Kokken","avatar":""},{"name":"Kalpalatha","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Baahubali: The Beginning","பாகுபலி","బాహుబలి","बाहुबली: द बिगनिंग","Bahubali: Početak","La leyenda de Baahubali: El inicio","巴霍巴利王：創始之初","La Leyenda de Baahubali El Inicio","Бахубали: начало","La Leyenda de Baahubali 1 - El Inicio","Bāhubali: Da biginiṅg","Baahubali: Začátek","Baahubali: O Início","బాహుబలి:ద బిగినింగ్"]', 1784690324447);
