INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xac-song-phan-6', 'Xác Sống (Phần 6)', 'The Walking Dead (Season 6)', 'xác sống (phần 6) the walking dead (season 6) lauren cohan norman reedus jeffrey dean morgan melissa mcbride christian serratos seth gilliam ross marquand josh mcdermitt khary payton cooper andrews callan mcauliffe cailey fleming lauren ridloff eleanor matsuura nadia hilker cassady mcc të vdekurit e gjallë живите мъртви les morcheurs 行尸走肉 živí mrtví elavad surnud οι ζωντανοί νεκροί 行屍 živi mrtvaci מתים מהלכים mordeye moteharrek ウォーキング・デッド 워킹 데드 워킹데드 gyvieji numirėliai gyvi numirėliai staigājušie miroņi живи мртовци żywe trupy the walking dead the walking dead: invazia zombi okružen mrtvima zivi mrtveci živí mŕtvi ล่าสยอง...กองทัพผีดิบ ฝ่าวงล้อม ซอมบี้ล้างโลก yürüyen ölüler ходячі мерці і мертві підуть twd yuradigan murdalar xac song', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-noi-loan-hoan-hao-2', 'Sự Nổi Loạn Hoàn Hảo 2', 'Pitch Perfect 2', 'https://phimimg.com/upload/vod/20260105-1/d4326b8f5c48a1eb14fe826df438940a.jpg', 'https://phimimg.com/upload/vod/20260105-1/6c9fcd651a55aa1424fde17b47bf8b13.jpg', '<p>Các cô gái nhóm Bellas của trường Đại học Barden sẽ tiếp tục thử tài tại một cuộc chơi tầm cỡ hơn: Giải A capella quốc tế. Thế nhưng lý do dẫn The Barden Bellas tới giải đấu “khó nhằn” này lại cực kỳ trớ trêu: Các cô gái nhóm Bellas vinh dự được biểu diễn trong buổi tiệc sinh nhật của Tổng thống Barack Obama này, nhưng một sự cố đã xảy ra với thành viên mập nhất nhóm - Fat Amy - khi cô đang say sưa thể hiện ca khúc “Wrecking Ball”. Kết cục còn tệ hại hơn vì tai nạn này đã kéo theo sự cố về trang phục, và cả nhóm Bellas đã bị đình chỉ biểu diễn. Vị trí của Bellas được thay thế bằng nhóm nhạc hiếu thắng Das Sound Machine. Tình thế sẽ chỉ đổi ngược lại nếu các cô gái giành giải nhất trong cuộc thi A cappella toàn thế giới – một mục tiêu xem chừng là bất khả thi. Nhưng không gì ngăn được Beca, Fat Amy, Jesse Swanson, Bumper Alle, Stacie, Lilly và những người bạn trong The Barden Bellas tiến lên phía trước, họ đã quyết tâm cho cả thế giới biết mình là ai!</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anna Kendrick","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Hailee Steinfeld","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Ester Dean","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Skylar Astin","avatar":""},{"name":"Hana Mae Lee","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Ben Platt","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Chrissie Fit","avatar":""},{"name":"Birgitte Hjort Sørensen","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"David","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Dando la nota: 2 - Aún más alto","The Hit Girls 2","La Note Parfaite 2","歌喉讚2","피치퍼펙트 2","피치 퍼펙트 2","피치 퍼펙트 2: 언프리티 걸즈","Pitch Perfect 2"]', 1784690324447);
