INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-mat-phu-nu', 'Nước Mắt Phụ Nữ', 'Make A Woman Cry', 'https://phimimg.com/upload/vod/20251230-1/e69840e09553886098362d53bc25acc5.jpg', 'https://phimimg.com/upload/vod/20251230-1/c9d4a65ddee209ef998c8bca525482f4.jpg', '<p>Một trong những khác biệt lớn nhất giữa con người và loài vật chính là cảm xúc. Vì vậy, việc lột tả tâm lý của các nhân vật khác nhau trong một bộ phim truyền hình là phần tối quan trọng của quá trình kể chuyện. Cảm giác khi một người yêu một người khác sẽ ra sao? Cảm giác khi ta tha thứ cho một ai đó sẽ thế nào? Bộ phim này được tạo ra với mong muốn truyền cảm hứng để mỗi chúng ta trở nên dịu dàng hơn và mạnh mẽ hơn.</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 13, 2015, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jung-eun","avatar":""},{"name":"Lee Tae-ran","avatar":""},{"name":"Song Chang-eui","avatar":""},{"name":"Ha Hee-ra","avatar":""},{"name":"Oh Dae-gyu","avatar":""},{"name":"Lee Soon-jae","avatar":""},{"name":"In Gyo-jin","avatar":""},{"name":"Seo Woo-rim","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Lee Da-in","avatar":""},{"name":"Park Sang-hyun","avatar":""},{"name":"Han Bo-bae","avatar":""},{"name":"Ji Il-ju","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Kim Hae-sook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["여자를 울려"]', 1784690324448);
