INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ashoka-dai-de-chakravartin-ashoka-samrat', 'Ashoka Đại Đế (Chakravartin Ashoka Samrat)', 'The Great Emperor Ashoka', 'https://phimimg.com/upload/vod/20251227-1/d307918dd6c7f2876ccfadb03378ab30.jpg', 'https://phimimg.com/upload/vod/20251227-1/f11ce127f6fa417317c5ff01f3da001a.jpg', '<p>&quot;Một vị vua được ví như một ngôi sao sáng mãi trong lịch sử cũng như trong lòng người dân Ấn Độ bởi lòng nhân đạo, sức mạnh phi thường, tinh thần quả cảm, và tài năng kiệt xuất; là người có công xây dựng một đế chế Magat hùng mạnh nhất mọi thời đại. Ông chính là đại đế Ashoka.&quot; &quot;Ashoka đại đế&quot; - một trong những xuất phẩm có tỉ xuất người xem cao nhất năm 2016 khi được phát sóng trên màn ảnh nhỏ Ấn Độ.&nbsp;</p>', 'Hoàn Tất (239/239)', 239, 'series', 'completed', 18, 2015, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Siddharth Nigam","avatar":""},{"name":"Sameer Dharmadhikari","avatar":""},{"name":"Pallavi Subhash Shirke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["चक्रवर्तीं अशोक सम्राट","The Great Emperor Ashoka","Chakravartin Ashoka Samrat"]', 1784690324448);
