INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-quai-vat-nho-em', 'Xin Chào Quái Vật (Nhớ Em)', 'I Remember You', 'https://phimimg.com/upload/vod/20251223-1/c2b6787d8a78e20e0fd297d0463c6e0b.jpg', 'https://phimimg.com/upload/vod/20251223-1/b5577a4f553245163fb3db74f8ff7a87.jpg', '<p>Lee Hyun (do Seo In Guk đóng) từ nhỏ đã có trí thông minh tuyệt đỉnh, nhưng một mặt nào đó lại giống như quái vật, do đó bị cha mình là Lee Joong Min (do Jun Kwang Ryul đóng) quản thúc rất nghiêm khắc. Sau khi trưởng thành, Lee Hyun trở thành một nhà phân tích tâm lý tội phạm. Một ngày nọ, Lee Hyun tình cờ gặp một cảnh sát hình sự non trẻ là Cha Ji An (do Jang Na Ra đóng) tại hiện trường vụ án. Duyên phận gắn kết Lee Hyun và Cha Ji An lại với nhau, viết nên một câu chuyện tình đẹp như mơ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo In-guk","avatar":""},{"name":"Jang Na-ra","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Lee Chun-hee","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Im Ji-eun","avatar":""},{"name":"Min Sung-wook","avatar":""},{"name":"Kim Jae-young","avatar":""},{"name":"Jun Kwang-ryul","avatar":""},{"name":"Son Seung-won","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Neoreul Gieokhae","Remember記號","Hello Monster","너를 기억해"]', 1784690324448);
