INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-sieu-toc', 'Cậu Bé Siêu Tốc', 'Turbo Kid', 'https://phimimg.com/upload/vod/20251215-1/bc72dd509c26526939be2d56f4f25814.jpg', 'https://phimimg.com/upload/vod/20251215-1/9fd45fc7b5ca7c115c0249d3848813fc.jpg', '<p>Bộ phim có bối cảnh về thế giới tương lai hậu tận thế, nơi ấy có The Kid - một chàng trai mồ côi tốt bụng vô tình gặp được một cô gái bí ẩn tên Apple, họ trở thành những người bạn tốt của nhau cho đến một ngày khi Zeus – Bạo chúa của vùng đất Wasteland bắt cóc cô. The Kid phải đối mặt với nỗi sợ của bản thân mình và bước vào cuộc hành trình chống lại cái ác để giải thoát Apple…</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Munro Chambers","avatar":""},{"name":"Laurence Leboeuf","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Aaron Jeffery","avatar":""},{"name":"Edwin Wright","avatar":""},{"name":"Romano Orzari","avatar":""},{"name":"Steeve Léonard","avatar":""},{"name":"Orphée Ladouceur-Nguyen","avatar":""},{"name":"Yves Corbeil","avatar":""},{"name":"Evan Manoukian","avatar":""},{"name":"Anouk Whissell","avatar":""},{"name":"François Simard","avatar":""},{"name":"Martin Paquette","avatar":""},{"name":"Pierre Sigouin","avatar":""},{"name":"Yoann-Karl Whissell","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Турбо Кід","Turbo Kid"]', 178469