INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bojack-horseman-phan-2', 'BoJack Horseman (Phần 2)', 'BoJack Horseman (Season 2)', 'bojack horseman (phần 2) bojack horseman (season 2) will arnett aaron paul alison brie amy sedaris paul f. tompkins بوجاك هورسمان ცხენი ბოჯეკი μπότζακ χόρσμαν בוג''אק הורסמן конь боджек кiнь боджек bojack horseman', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-mot-mai-nha', 'Chung Một Mái Nhà', 'Love From Today (Love On A Rooftop)', 'https://phimimg.com/upload/vod/20251124-1/e8a40e36523cafbf059ccce10568e1ab.jpg', 'https://phimimg.com/upload/vod/20251124-1/aada2bfb733c3b0b0dc0997da9bf54e2.jpg', '<p>Bộ phim là câu chuyện về đam mê, sống hết mình vì đam mê của những người trẻ, dám hy sinh tất cả để thực hiện được ước mơ của mình. Câu chuyện về tình cảm gia đình , về tình yêu cũng được miêu tả sâu sắc. Bên cạnh đó, bộ phim còn truyền tải đến khán giả về nghề trà truyền thống của Hàn Quốc.

Bộ phim với dàn diễn viên xinh đẹp và diễn xuất xuất thần cộng với sự trở lại của những diễn viên kỳ cựu được khán giả cực kỳ yêu thích như Kim Yong-rim, Ahn Nae-sang, Lee Eung-kyung.. chắc chắn là bộ phim thú vị dành cho cả gia đình.</p>', 'Hoàn Tất (80/80)', 80, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lim Se-mi","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Choo So-yeong","avatar":""},{"name":"Lee Chang-wook","avatar":""},{"name":"Jo Yoon-seo","avatar":""},{"name":"Hahm Eun-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["今天开始我爱你","Oneulbooteo Saranghae","I Love You From Today","Love on a Rooftop","오늘부터 사랑해"]', 1784690324448);
