INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-can-quy', 'Vết Cắn Quỷ', 'Bite', 'https://phimimg.com/upload/vod/20251116-1/62d6548760f865aec6b3c77869006fba.jpg', 'https://phimimg.com/upload/vod/20251116-1/938f39d65d90926ae76cc107893346dc.jpg', '<p>Trong khi đang đi nghỉ tiệc độc thân, Casey, cô dâu tương lai, bị một con côn trùng lạ cắn có vẻ vô hại. Sau khi trở về nhà với đôi chân lạnh ngắt, Casey cố gắng hủy đám cưới nhưng trước khi kịp, cô bắt đầu biểu hiện những đặc điểm giống côn trùng. Giữa sự biến đổi về thể chất và nỗi lo lắng về đám cưới, Casey khuất phục trước bản …</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Elma Begovic","avatar":""},{"name":"Jordan Gray","avatar":""},{"name":"Annette Wozniak","avatar":""},{"name":"Denise Yuen","avatar":""},{"name":"Tianna Nori","avatar":""},{"name":"Caroline Palmer","avatar":""},{"name":"MarieBeth Young","avatar":""},{"name":"Lawrene Denkers","avatar":""},{"name":"John Migliore","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["变蚊人","噬咬","刺痛","Bite"]', 1784690324448);
