INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-ma-ca-rong', 'Bác Sĩ Ma Cà Rồng', 'Blood', 'https://phimimg.com/upload/vod/20251109-1/9bc7257c32c98e914968f7853a5cbae5.jpg', 'https://phimimg.com/upload/vod/20251109-1/f9b9b29a0a097ab2b9b13ef12cb8e734.jpg', '<p>"Blood" là một bộ phim y khoa về ma cà rồng. Lấy bối cảnh tại một bệnh viện. Ma cà rồng làm việc như một bác sỹ. Diễn ra cuộc chiến giữa cái thiện và cái ác cũng như một câu chuyện về tình yêu bất tử. Park Ji Sang là Bác sỹ phẫu thuật tại Bệnh viện Ung thư Taemin. Anh luôn nghiên cứu cách để trở thành một con người bình thường. Đẹp trai, thông minh, giàu có, tốt bụng - anh là người hùng luôn dùng năng lực siêu nhiên của ma cà rồng để giúp đỡ mọi người. Tuy nhiên vì là ma cà rồng vì thế trong anh luôn thèm khát máu tươi, anh luôn phải tự đấu tranh với chính bản thân để vượt qua ham muốn cá nhân để cứu sống bệnh nhân của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ahn Jae-hyun","avatar":""},{"name":"Ji Jin-hee","avatar":""},{"name":"Koo Hye-sun","avatar":""},{"name":"Sohn Su-hyun","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Jung Hae-in","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Jung Hye-sung","avatar":""},{"name":"Baek Su-ho","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Park Joo-mi","avatar":""},{"name":"Hong Hwa-ri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id"