INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bon-nang-luat-su', 'Chuyện Bốn Nàng Luật Sư', 'Rising The Bar', 'https://phimimg.com/upload/vod/20251023-1/9dffc497fdf9e3f52101135937426495.jpg', 'https://phimimg.com/upload/vod/20251023-1/17f683e18c3c21a901efb585d530ce89.jpg', '<p>Đại luật sư Phạm Trí Nghị cùng vợ là Trương Tuệ, được mệnh danh “Thần Điêu Hiệp Lữ”. Năng lực cãi án tài tình và sự kết hợp ăn ý đã giúp Nghị - Vân trở thành cặp bài trùng trong ngành luật, thu hút rất nhiều người đến xin làm học trò. Hai vợ chồng đào tạo luật sư với những thành viên trẻ, nhiệt huyết và ưu tú như Đường Tĩnh Tư, Hoắc Tử Ngưng và Chu Tử Bác. Tử Ngưng có bạn học tên là Tăng Khả Hân, đang thực tập tại văn phòng của Tuệ Vân. Diêu Thúy Hoa, đang học việc với đại luật sư Nhậm Tuyển Diệp. Diệp có tài cãi án không thua kém Nghị và Vân. Ông nổi tiếng đào hoa và có mối quan hệ tình cảm phức tạp với đệ tử - Trịnh Chước Đồng – chị cùng cha khác mẹ của Ngưng. Mỗi đại luật sư sẽ sử dụng những phương pháp riêng của mình để đào tạo các học trò trở thành luật sư thực thụ. Tuy nhiên, mỗi người một cách sống, một quan điểm riêng về lẽ phải. Nhiều lúc, họ bị dao động bởi vinh hoa, cám dỗ hoặc chịu áp lực từ gia đình, tình bạn, tình yêu. Các luật sư tập sự trẻ tuổi sẽ chiến đấu với những khó khăn như thế nào để thực hiện được ước mơ của mình?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 11, 2015, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Trí Hiền","avatar":""},{"name":"Trương Kế Thông","avatar":""},{"name":"Trần Khải Lâm","avatar":""},{"name":"Diêu Tử Linh","avatar":""},{"name":"Trần Oánh","avatar":""},{"name":"Hà Nhạn Thi","avatar":""},{"name":"Đường Thi Vịnh","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""},{"name":"Châu Tử Dương","avatar":""},{"name":"Trịnh Tử Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rising The Bar"]', 1784690324448);
