INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-bon-nang-luat-su', 'Chuyện Bốn Nàng Luật Sư', 'Rising The Bar', 'chuyện bốn nàng luật sư rising the bar huỳnh trí hiền trương kế thông trần khải lâm diêu tử linh trần oánh hà nhạn thi đường thi vịnh lưu bội nguyệt châu tử dương trịnh tử thành rising the bar', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy', 'Phù Thủy', 'The Witch', 'https://phimimg.com/upload/vod/20251023-1/44c69d504cdfe897df8f1e001b6ea735.jpg', 'https://phimimg.com/upload/vod/20251023-1/607d3ce6952176bfe94705b0663d880f.jpg', '<p>Tin rằng một phù thủy đã nguyền rủa gia đình họ, những người hành hương sống ở bìa rừng nguyên sinh tại New England ngày càng thêm hoang tưởng.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anya Taylor-Joy","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Kate Dickie","avatar":""},{"name":"Harvey Scrimshaw","avatar":""},{"name":"Ellie Grainger","avatar":""},{"name":"Lucas Dawson","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Bathsheba Garnett","avatar":""},{"name":"Sarah Stephens","avatar":""},{"name":"Daniel Malik","avatar":""},{"name":"Axtun Henry Dube","avatar":""},{"name":"Athan Conrad Dube","avatar":""},{"name":"Vivien Moore","avatar":""},{"name":"Karen Kaeja","avatar":""},{"name":"Brandy Leary","avatar":""},{"name":"Rebecca Hope Terry","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The VVitch: A New-England Folktale","The VVitch","La bruja: Una leyenda de Nueva Inglaterra","The Witch: A New England Folk Tale","Veštica: Narodna Priča Nove Engleske","Čarodejnica - Novoanglická legenda","Čarodějky: Pověst z Nové Anglie","女巫","Ведьма: Сказка Новой-Англии","Ведьма [Eggers]","A Bruxa: A Lenda de New-England","อาถรรพ์แม่มดโบราณ","La sorcière: Une légende de la Nouvelle-Angleterre","ウィッチ","Վհուկը","La Sorcière","Вештерка","Вештица: Народна прича Нове Енглеске","Відьма","La bruja","An Chailleach","The Witch: Vuoi ascoltare una favola?","An Wragh: Drolla Ynglond Nowydh","Ragana","Čarodějnice","Czarownica: Bajka ludowa z Nowej Anglii","Vrăjitoarea","الساحرة","جادوگر","جادووگەرەکە","המכשפה","더 위치","Вещицата","不巫之地","Vještica","Nõid","ალქაჯი","Η Μάγισσα","A boszorkány","เดอะ วิทช์","Cadı","Phù Thủy","The Witch"]', 1784690324448);
