INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-thuy', 'Phù Thủy', 'The Witch', 'phù thủy the witch anya taylor-joy ralph ineson kate dickie harvey scrimshaw ellie grainger lucas dawson julian richings bathsheba garnett sarah stephens daniel malik axtun henry dube athan conrad dube vivien moore karen kaeja brandy leary rebecca hope terry the vvitch: a new-england folktale the vvitch la bruja: una leyenda de nueva inglaterra the witch: a new england folk tale veštica: narodna priča nove engleske čarodejnica - novoanglická legenda čarodějky: pověst z nové anglie 女巫 ведьма: сказка новой-англии ведьма [eggers] a bruxa: a lenda de new-england อาถรรพ์แม่มดโบราณ la sorcière: une légende de la nouvelle-angleterre ウィッチ վհուկը la sorcière вештерка вештица: народна прича нове енглеске відьма la bruja an chailleach the witch: vuoi ascoltare una favola? an wragh: drolla ynglond nowydh ragana čarodějnice czarownica: bajka ludowa z nowej anglii vrăjitoarea الساحرة جادوگر جادووگەرەکە המכשפה 더 위치 вещицата 不巫之地 vještica nõid ალქაჯი η μάγισσα a boszorkány เดอะ วิทช์ cadı phù thủy the witch', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-ngay-xua-phan-5', 'Ngày Xửa Ngày Xưa (Phần 5)', 'Once Upon A Time (Season 5)', 'https://phimimg.com/upload/vod/20251023-1/5c2f74d15579416eb4bdcfce4452375e.jpg', 'https://phimimg.com/upload/vod/20251023-1/b3fd58f20ae7c3cb17a7c04e32f98177.jpg', '<p>Loạt phim xoay quanh câu chuyện của nữ trinh thám Emma Swan cùng con trai Henry trong quá trình khám phá thị trấn Storybrooke (tiểu bang Maine, Đông Bắc Hoa Kỳ). Đây được xem là vết tích của một thế giới song song bị nguyền rủa bởi Hoàng hậu độc ác - Regina Mills - người đến từ câu chuyện cổ tích Nàng Bạch Tuyết. Trong phim, mọi nhân vật đến từ thế giới cổ tích đều không có ký ức về thân phận của mình. Nữ trinh thám Emma Swan được gửi đến thế giới này với nhiệm vụ phá vỡ lời nguyền của mụ Hoàng hậu độc ác. Trong phần 2 này, khi lời nguyền bị phá vỡ, nữ trinh thám Emma được đoàn tụ với cha mẹ, nhưng mụ Hoàng hậu độc ác Regina liệu có để mọi chuyện được yên?</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lana Parrilla","avatar":""},{"name":"Colin O''Donoghue","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Andrew J. West","avatar":""},{"name":"Alison Fernández","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Era Uma Vez","Il Était une Fois","Bylo nebylo","Gyveno kartą","Érase una vez","OUAT","Once Upon a Time"]', 1784690324448);
