INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('upin-ipin-phan-9', 'Upin & Ipin (Phần 9)', 'Upin & Ipin (Season 9)', 'upin & ipin (phần 9) upin & ipin (season 9) asyiela putri siti khairunnisa hajah ainon ariff calvin tony lokeemin tang ying sowk muhammad hafiz hassan muhammad fareez daniel rufaidah mohamed fadzil usayd uqashah kamsani siti nor adwin safie irfan fahim maheswary mohan suleiman bakti azl upin & ipin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-bay-mau', 'Cạm Bẫy Máu', 'Blood Trap', 'https://phimimg.com/upload/vod/20251020-1/51ce4752445b7ede05ea61be38da9664.jpg', 'https://phimimg.com/upload/vod/20251020-1/99c7c645cbafbb34fe210530ac4d150b.jpg', '<p>Sáu tên tội phạm được thuê để bắt cóc một cô gái trẻ nhằm đòi tiền chuộc, nhưng khi bị mắc kẹt trong dinh thự của cô, họ sớm nhận ra những gì ẩn giấu bên trong không hề như họ tưởng tượng — và cuộc săn mồi nhanh chóng biến thành cơn ác mộng kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Vinnie Jones","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Gianni Capaldi","avatar":""},{"name":"Drew Kenney","avatar":""},{"name":"Elena Mirela","avatar":""},{"name":"Grazia Leone","avatar":""},{"name":"Denny Mendez","avatar":""},{"name":"Daniel Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Bite","Blood Trap"]', 1784690324448);
