INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ve-tu-coi-chet', 'Người Về Từ Cõi Chết', 'The Revenant', 'https://phimimg.com/upload/vod/20251020-1/ffa17c97bb53a1c28869a41f5df0de4a.jpg', 'https://phimimg.com/upload/vod/20251020-1/e60b1e9a80b782dfacd0d243352b7d24.jpg', '<p>Bộ phim dựa trên câu chuyện có thật, phim kể về người thợ săn Hugh Glass. Sau một trận chiến đẫm máu với những người Mỹ bản địa, Hugh bị thương và bị đồng đội tàn nhẫn bỏ lại trong khu núi tuyết giá rét. Từ đó, Hugh Glass phải làm tất cả mọi thứ để có thể tồn tại giữa cái lạnh tàn bạo, những động vật ăn thịt và chiến tranh với những bộ lạc nơi vùng núi hoang vu. Nhờ ý chí kiên cường, người thợ săn đã sống sót một cách kỳ diệu, một mình băng qua quãng đường dài hơn 3.000 dặm (4.828 km) để trở về và trả thù được John Fitzgerald – kẻ từng là bạn của mình năm xưa …</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Forrest Goodluck","avatar":""},{"name":"Duane Howard","avatar":""},{"name":"Arthur RedCloud","avatar":""},{"name":"Melaw Nakehk''o","avatar":""},{"name":"Grace Dove","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Kristoffer Joner","avatar":""},{"name":"Joshua Burge","avatar":""},{"name":"Fabrice Adde","avatar":""},{"name":"Christopher Rosamond","avatar":""},{"name":"Robert Moloney","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Revenant - Hồn Ma Báo Thù","レヴェナント: 蘇えりし者","レヴェナント 蘇えりし者","O Regresso","El renacido","Уцілілий","Легенда Г''ю Гласса","Вяртанец з таго свету","The Revenant"]', 1784690324448);
