INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-ve-tu-coi-chet', 'Người Về Từ Cõi Chết', 'The Revenant', 'người về từ cõi chết the revenant leonardo dicaprio tom hardy domhnall gleeson will poulter forrest goodluck duane howard arthur redcloud melaw nakehk''o grace dove lukas haas paul anderson kristoffer joner joshua burge fabrice adde christopher rosamond robert moloney the revenant - hồn ma báo thù レヴェナント: 蘇えりし者 レヴェナント 蘇えりし者 o regresso el renacido уцілілий легенда г''ю гласса вяртанец з таго свету the revenant', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thoi-sao', 'Người Thổi Sáo', 'The Piper', 'https://phimimg.com/upload/vod/20251018-1/a98e9966e1d8abafae78e8f62fc3c4bd.jpg', 'https://phimimg.com/upload/vod/20251018-1/490d4e29facb0767c88be269eb7fa56d.jpg', '<p>Vào những năm thập niên 50, tại một ngôi làng trên núi không có tên trong bản đồ Hàn Quốc, một người lữ hành đi cùng cậu con trai tới mở cánh cửa làng bí ẩn. Tại đây, họ được trưởng thôn hứa sẽ thưởng cho một số tiền lớn nếu đuổi được đàn chuột đang gieo rắc nỗi ám ảnh cho họ - đó là hàng chục nghìn con chuột háu đói. &nbsp;Vốn sẵn tính thông minh và nhanh nhạy, cha con Woo-Ryong hoàn thành nhiệm vụ tưởng như bất khả thi này hết sức xuất sắc và trong thời gian chóng vánh. Mọi việc tưởng như sẽ suôn sẻ với Woo-Ryong nhưng anh không ngờ cơn ác mộng kinh hoàng thật sự bắt đầu khi các bí mật đen tối, những tội ác kinh hoàng và lời nguyền đáng sợ bủa vây ngôi làng dần được hé lộ…</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Lee Joon","avatar":""},{"name":"Goo Seung-hyun","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Kyul Hwi","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Park Yoon-seok","avatar":""},{"name":"Lee Dong-hee","avatar":""},{"name":"Kim Jin-ook","avatar":""},{"name":"Do Gi-beom","avatar":""},{"name":"Lee Ho-cheol","avatar":""},{"name":"Lee Sang-ok","avatar":""},{"name":"Shin Mi-yeong","avatar":""},{"name":"Kim Seon-kyeong","avatar":""},{"name":"Son San","avatar":""},{"name":"Ham Seon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sonnim","The guest","客人","Крысолов. Древнее проклятие","손님"]', 1784690324448);
