INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-thuong-quay-ve', 'Yêu Thương Quay Về', 'Love & Mercy', 'https://phimimg.com/upload/vod/20251011-1/0d4df1559f60abf7932519b78c75b9b3.jpg', 'https://phimimg.com/upload/vod/20251011-1/fe31de3f21c0b981bc783e60dafd0c3d.jpg', '<p>Yêu thương quay về là phim điện ảnh tiểu sử chính kịch của Mỹ năm 2014 do Bill Pohlad đạo diễn, xoay quanh thủ lĩnh kiêm nhà đồng sáng lập ban nhạc The Beach Boys Brian Wilson và sự vật lộn của ông với căn bệnh tâm thần trong các thập niên 1960 và 1980.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Dano","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"Kenny Wormald","avatar":""},{"name":"Brett Davern","avatar":""},{"name":"Graham Rogers","avatar":""},{"name":"Erin Darke","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Joanna Going","avatar":""},{"name":"Nick Gehlfuss","avatar":""},{"name":"Mark Linett","avatar":""},{"name":"Johnny Sneed","avatar":""},{"name":"Gary Griffin","avatar":""},{"name":"Teresa Cowles","avatar":""},{"name":"Vince Meghrouni","avatar":""},{"name":"Jeff Meacham","avatar":""},{"name":"Max S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["爱与宽容","Love and Mercy","Love & Mercy, la véritable histoire de Brian Wilson des Beach Boys","Love & Mercy"]', 1784690324448);
