INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-rac-roi', 'Bộ Ba Rắc Rối', 'Triple Trouble', 'https://phimimg.com/upload/vod/20240207-1/8ba12293306bd0e18178695328c06b6d.jpg', 'https://phimimg.com/upload/vod/20240207-1/8e5cbb62cee7bcbcdecba34998157cbf.jpg', '<p>Sau khi cùng tỉnh dậy trên một hòn đảo, ba phụ nữ bắt đầu chắp nối những sự việc xảy ra đêm hôm trước – với sự tham gia của một người lạ đẹp trai.</p>', 'Full', 1, 'single', 'completed', 27, 2015, 'Vietsub', 'FHD', 'Quốc Gia Khác', 1, '[{"name":"Thúy Nga","avatar":""},{"name":"Kathy Uyên","avatar":""},{"name":"Hoàng Oanh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324448);
