INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-phat-chet-luon-phan-1', 'Đấm Phát Chết Luôn (Phần 1)', 'One Punch Man (Season 1)', 'https://phimimg.com/upload/vod/20250306-1/09d0e2176c31fcd164f7f1688ce8feed.jpg', 'https://phimimg.com/upload/vod/20251012-1/4615b33d130acfdf589e204042df5e1a.jpg', '<p>Câu chuyện diễn ra tại thành phố Z của Nhật Bản tại thời điểm thế giới đầy những quái vật bí ẩn với sức mạnh ghê gớm đã xuất hiện và gây ra biết bao nhiêu thảm họa. &nbsp;Nhưng cũng chính tại đây xuất hiện 1 siêu anh hùng đấm phát chết luôn, có thể dễ dàng đánh bại và tiêu diệt những con quái vật này. Cũng chính vì tài năng hiếm có này mà có rất nhiều nghi ngại về khả năng thực sự của vị siêu anh hùng, thậm chí anh không bao giờ nhận được bất kỳ lòng tin nào từ dân chúng.

Siêu anh hùng mạnh nhất thế giới có thể giết bất cứ ai chỉ với một đòn. Nhưng không có gì có thể thách thức anh ta, nên anh ta phải vật lộn với sự buồn chán và trầm cảm.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Makoto Furukawa","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Hikaru Midorikawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ואן-פאנץ'' מאן","וואן פאנץ'' מן","वन पंच मैन","مرد یک مشتی","Wanpanman","One Punch Man","ONE PUNCH MAN ワンパンマン","OPM","Человек одного удара","ون بنش مان","Anh Hùng OnePunch","Nhất Quyền Nhân","ワンパンマン"]', 1784690324448);
