INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-tap-su', 'Thiên Sứ Tập Sự', 'Angel In-the-Making', 'https://phimimg.com/upload/vod/20251010-1/d071433470e063f2725b92caf41f1c26.jpg', 'https://phimimg.com/upload/vod/20251010-1/2d532f9b0b33e6aedc328bba2f9e5bf6.jpg', '<p>3 cô nàng Kỳ Lạc, Bạc Thúy và Du Nguyệt Ái được điều đến phòng khám khó tính và khó chịu nhất trong bệnh viên do anh chàng Dương Chí Minh .Anh là một người khá là giỏi trong công việc nhưng tính tình rất kỳ quặc lúc này lúc nọ và luôn thách thức các cấp trên và bệnh nhân của mình.Vì thế các cô gái bày ra một kế hoạch trị anh ta ,vì lý do anh đã làm không ít tập sự không hoàn thành và đậu tốt nghiệp được. Phim với sự có mặt của các diễn viên TVB quen thuộc như Sầm Lệ Hương, Lưu Bội Nguyệt, Ngô Nhược Hy, Hồng Vĩnh Thành...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 12, 2015, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tony Hung","avatar":""},{"name":"Eliza Sam","avatar":""},{"name":"Pal Sinn Lap-Man","avatar":""},{"name":"Alice Chan","avatar":""},{"name":"Elaine Yiu","avatar":""},{"name":"Joel Chan","avatar":""},{"name":"Moon Lau","avatar":""},{"name":"MoMo Wu","avatar":""},{"name":"Jinny Ng","avatar":""},{"name":"William Chak","avatar":""},{"name":"Toby Leung Ching-Kei","avatar":""},{"name":"Samantha Chuk Man-Kwan","avatar":""},{"name":"Chung King-Fai","avatar":""},{"name":"Vincent Cheung","avatar":""},{"name":"LuLu Kai","avatar":""},{"name":"Tony Chui","avatar":""},{"name":"Cecilia So Yan-Chee","avatar":""},{"name":"Stefan Wong","avatar":""},{"name":"Henr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["實習天使"]', 1784690324448);
