INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-lam-gai', 'Phận Làm Gái', 'Lazy Hazy Crazy', 'https://phimimg.com/upload/vod/20251009-1/e39748c6ef9544191bd43866ee08f398.jpg', 'https://phimimg.com/upload/vod/20251009-1/2888771f12d426cc92126d53acb6a909.jpg', '<p><span style="text-wrap-mode: wrap;">Những người bạn thời thơ ấu Tracy, Chloe và Alice ở chung một căn hộ vào mùa hè. Họ sống gần nhau, gặp gỡ các chàng trai và bán công ty của họ cũng như quan hệ tình dục. Với hình ảnh lãng mạn và chủ đề đôi khi khiêu khích, nữ đạo diễn đầu tay Luk Yee-sum mang đến cho khán giả một câu chuyện vui tươi về tình dục, ham muốn và tình bạn.</span></p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Fish Liew","avatar":""},{"name":"Ashina Kwok","avatar":""},{"name":"Koyi Mak","avatar":""},{"name":"Gregory Wong Chung-Yiu","avatar":""},{"name":"Dada Chan Ching","avatar":""},{"name":"Susan Shaw Yam-Yam","avatar":""},{"name":"Jacky Cai","avatar":""},{"name":"Kochun Tse","avatar":""},{"name":"Sora Aoi","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Derek Tsang Kwok-Cheung","avatar":""},{"name":"Kong Ka-Man","avatar":""},{"name":"Harriet Yeung Sze-Man","avatar":""},{"name":"Isabel Chan Yat-Ning","avatar":""},{"name":"Subyub Lee","avatar":""},{"name":"Tarah Chan","avatar":""},{"name":"Be","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Tung baan tung hok","레이지 헤이지 크레이지","同班同學"]', 1784690324448);
