INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-mot-chieu', 'Chuyến Đi Một Chiều', 'One Way Trip', 'https://phimimg.com/upload/vod/20251003-1/23aa5d4a09bcbab79cfd492525569a31.jpg', 'https://phimimg.com/upload/vod/20251003-1/9def13aac3503e15d18835495de96703.jpg', '<p>Bốn người bạn thân Yong-bi, Ji-gong, Sang-woo và Doo-man vừa tròn hai mươi tuổi, chính thức bước vào tuổi trưởng thành, đã cùng nhau lên đường đến Pohang, một thành phố nhỏ ven biển — vì Sang-woo sẽ nhập ngũ vào lực lượng thủy quân lục chiến vào ngày hôm sau. Trong ngày cuối cùng trước khi Sang-woo phải đi lính, một biến cố làm thay đổi cả cuộc đời bất ngờ ập đến với họ. Bốn người bạn thân giờ đây phải đối mặt với một tình huống vượt ngoài tầm kiểm soát, buộc họ phải trải qua một ngày không thể nào vãn hồi.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Ji-soo","avatar":""},{"name":"Suho","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Kim Hee-chan","avatar":""},{"name":"Kim Dong-wan","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Choi Jun-young","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Moon Hee-kyung","avatar":""},{"name":"Yoo Ha-bok","avatar":""},{"name":"Lee Ji-yeon","avatar":""},{"name":"Jeong Do-won","avatar":""},{"name":"Kang Jun-seok","avatar":""},{"name":"Han Hye-ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Geulroridei","Glory Day","冲出不归路","One Way Trip","글로리데이"]', 1784690324448);
