INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('antman-nguoi-kien', 'Ant-Man: Người Kiến', 'Ant-Man', 'https://phimimg.com/upload/vod/20250919-1/dd11033a6999f856f6a62541204e1b48.jpg', 'https://phimimg.com/upload/vod/20250919-1/e8d6232948847eba650172712d2b6d0b.jpg', '<p>Câu chuyện bắt đầu từ giáo sư Hank Pym (Michael Douglas thủ vai), Người Kiến đầu tiên với phát minh vĩ đại là bộ giáp biến đổi kích cỡ con người. Không chỉ thu nhỏ cơ thể để chiến đấu linh hoạt, bộ giáp siêu hạng còn đem lại những năng lực đặc biệt như trò chuyện với kiến, di chuyển với tốc độ nhanh. Nhưng thật không may, công nghệ tạo ra bộ giáp đã bị Darren Cross (Yellowjacket) chiếm đoạt và đưa vào sản xuất hàng loạt. Tất nhiên, “nếu trao quyền năng của Thượng đế cho tất cả mọi người thì thế giới này sẽ trở nên hỗn loạn”. Để ngăn chặn mối nguy hại đến từ Yellowjacket, giáo sư Hank Pym cùng trợ thủ Hope van Dyne (Evangeline Lilly thủ vai) đã tìm đến Scott Lang – một tên trộm vặt lừng danh từng vào tù ra tội, để nhờ anh lấy lại công nghệ đặc biệt và ngăn chặn Yellowjacket. Scott đã trở thành Người Kiến tiếp theo, bắt đầu làm quen với việc điều khiển bộ giáp và sử dụng các siêu năng lực đặc biệt.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Abby Ryder Fortson","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"T.I.","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Garrett Morris","avatar":""},{"name":"Gregg Turkington","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["איש הנמלה","Ant-Man 3D","마블 앤트맨","Человeк-Муравeй","Marvel Studios'' Ant-Man","Người Kiến","ადამიანი-ჭიანჭველა","אנט-מן","Ant Man","Marvel''s Ant-Man","Karınca Adam","الرجل النملة","Ant-Man"]', 1784690324448);
