INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-nguoi-noi-tieng', 'Góc Khuất Người Nổi Tiếng', 'A Patch Of Fog', 'https://phimimg.com/upload/vod/20250919-1/6855ad188a3478d8aa6da7088cc1e00b.jpg', 'https://phimimg.com/upload/vod/20250919-1/6ff4ee74c64f4fe48629800e66a0a8d2.jpg', '<p>Bị Robert - một bảo vệ quèn nắm thóp, nhà văn nổi tiếng Sandy Duffy buộc phải làm bạn với hắn. Sự ám ảnh ngày càng cực đoan của Robert khiến Sandy phải tìm cách thoát khỏi &quot;tình bạn&quot; này.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stephen Graham","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Lara Pulver","avatar":""},{"name":"Arsher Ali","avatar":""},{"name":"Ian McElhinney","avatar":""},{"name":"Naseen Morgan","avatar":""},{"name":"Peter Ballance","avatar":""},{"name":"Tara Cush","avatar":""},{"name":"Karen Hassan","avatar":""},{"name":"Stuart Graham","avatar":""},{"name":"Paul Kennedy","avatar":""},{"name":"Louise Mathews","avatar":""},{"name":"Nigel O''Neill","avatar":""},{"name":"Tara Lynne O''Neill","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Patch of Fog"]', 1784690324448);
