INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('goc-khuat-nguoi-noi-tieng', 'Góc Khuất Người Nổi Tiếng', 'A Patch Of Fog', 'góc khuất người nổi tiếng a patch of fog stephen graham conleth hill lara pulver arsher ali ian mcelhinney naseen morgan peter ballance tara cush karen hassan stuart graham paul kennedy louise mathews nigel o''neill tara lynne o''neill a patch of fog', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-bong-ma', 'Truy Tìm Bóng Ma', 'Phantom', 'https://phimimg.com/upload/vod/20250917-1/9a24449fc3ab8d8df4cbf2431ac31a32.jpg', 'https://phimimg.com/upload/vod/20250917-1/8a1a6e0302d3cfba11745706a1a13739.jpg', '<p>Phim Truy Tìm Bóng Ma - Phantom 2015 là một bộ phim dựa trên câu chuyện có thật, kể về cuộc điều tra về các cuộc tấn công tại Mumbai, Ấn Độ suốt nhiều ngày liền và tạo nên làn sóng khủng bố trên toàn cầu. Jude còn gọi là Daniyal Khan, là một sĩ quan trong quân đội bị can tội là đã giết một người đàn ông và bị bắt khi anh để lại cả đội mình chết thảm.</p><p>Một năm sau, tổ chức RAW quyết định bắt giữ tất cả những người liên quan đến các vụ tấn công. Họ đã tìm đến Jude để giúp họ trong việc tìm ra thủ phạm và đổi lại là lời hứa là xoá mọi tội danh cho anh và nhận được 1 vị trí tốt trong quân đội.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Mohammed Zeeshan Ayyub","avatar":""},{"name":"Rajesh Tailang","avatar":""},{"name":"Sabyasachi Chakraborty","avatar":""},{"name":"Denzil Smith","avatar":""},{"name":"Shahnawaz Pradhan","avatar":""},{"name":"Mir Sarwar","avatar":""},{"name":"J. Brandon Hill","avatar":""},{"name":"Chittaranjan Giri","avatar":""},{"name":"Chittaranjan Tripathy","avatar":""},{"name":"Sohaila Kapur","avatar":""},{"name":"Ashwath Bhatt","avatar":""},{"name":"Sumit Gulati","avatar":""},{"name":"Kaizaad Kotwal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Phantom Hindi","Phantom"]', 1784690324448);
