INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-tim-bong-ma', 'Truy Tìm Bóng Ma', 'Phantom', 'truy tìm bóng ma phantom saif ali khan katrina kaif mohammed zeeshan ayyub rajesh tailang sabyasachi chakraborty denzil smith shahnawaz pradhan mir sarwar j. brandon hill chittaranjan giri chittaranjan tripathy sohaila kapur ashwath bhatt sumit gulati kaizaad kotwal phantom hindi phantom', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-sieu-anh-hung-2-de-che-ultron', 'Biệt Đội Siêu Anh Hùng 2: Đế Chế Ultron', 'Avengers: Age Of Ultron', 'https://phimimg.com/upload/vod/20250517-1/69229eba91fea0022837a2c21585e03b.jpg', 'https://phimimg.com/upload/vod/20250517-1/b5756037d7bacff075fe28fc3197da44.jpg', '<p>Avengers: Age of Ultron tiếp nối các sự kiện xảy ra trong Captain America: The Winter Soldier ra mắt hè 2014. Kẻ thù của Biệt đội siêu anh hùng lần này là Ultron – một robot với trí tuệ nhân tạo, những năng lực siêu nhiên mạnh hơn bất kỳ ai trong The Avenger và có dã tâm chia rẽ nội bộ biệt đội nhằm thôn tính Trái Đất. Hắn được tạo ra từ phòng thí nghiệm của Tony Stark với mụ đích ban đầu là một hệ thống đặc biệt với mục đích gìn giữ hòa bình thế giới nhưng do Người Sắt sơ suất đã để mọi thứ vượt ra khỏi tầm kiểm soát, đẩy số phận của loài người lâm vào tình cảnh ngàn cân treo sợi tóc. Một lần nữa, những siêu anh hùng quả cảm - Iron Man, Captain America, Thor, The Incredible Hulk, Black Widow và Hawkeye - tiếp tục hợp tác để ngăn chặn kẻ thù. Trong hành trình bảo vệ hòa bình, nhóm kết nạp thêm hai thành viên: Wanda Maxioff và Pietro Maxioff – cặp song sinh bí hiểm và sở hữu một nguồn sức mạnh lớn lao, cũng như gặp lại một người bạn cũ trong hình dạng hoàn toàn mới có tên The Vision.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"James Spader","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Idris Elba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Avengers 2","Os Vingadores 2 - Era de Ultron","Marvel''s Avengers: Age of Ultron","Os Vingadores: A Era de Ultron","Vingadores 2","复仇者联盟2：奥创纪元","마블 어벤져스: 에이지 오브 울트론","어벤져스 2","Avengers 2: Vek Ultrona","어벤져스 에이지 오브 울트론","Avengers - L''Ère d''Ultron","Avengers - Age of Ultron","Marvel Studios'' Avengers: Age of Ultron","Avengers 2 - Age of Ultron","Os Vingadores - A Era de Ultron","Bosszúállók: Ultron kora","Avengers, L''ère d''Ultron","Vengadores 2 La era de Ultron","Avengers 2: Đế Chế Ultron","შურისმაძიებლები: ალტრონის ხანა","Avengers 2 - L''Ère d''Ultron","Avengers: Czas Ultrona","アベンジャーズ／エイジ・オブ・ウルトロン：2015","المنتقمون عهد الترون","Avengers: Age of Ultron"]', 1784690324448);
