INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-go-2', 'Điềm Gỡ 2', 'Sinister 2', 'https://phimimg.com/upload/vod/20250914-1/f5959141af1f4888dc62c616b38bf946.jpg', 'https://phimimg.com/upload/vod/20250914-1/940acc89d72354406486e58a8aac46e3.jpg', '<p>Nhân vật chính trong phim Điềm Gỡ 2 - Sinister 2 2015 là nhà văn chuyên viết về những tội ác có thật Ellison, người vừa mua một căn nhà mới để làm nơi viết sách và hy vọng có thể sáng tác một cuốn tiểu thuyết để đời tại đây. Trong phim hay này, ông không hề biết rằng, cũng chính tại ngôi nhà này, trước đây đã từng xảy ra một vụ giết người hàng loạt đầy thảm khốc. Trong một lần lên gác mái, Ellison tình cờ tìm thấy những cuốn phim và hình ảnh về vụ án đó, ông dần bị lôi cuốn và ám ảnh. Và thật kì lạ, những chi tiết viết trong bộ tài liệu đó dường như đang lặp lại với gia đình nhỏ của ông</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"James Ransone","avatar":""},{"name":"Shannyn Sossamon","avatar":""},{"name":"Robert Daniel Sloan","avatar":""},{"name":"Dartanian Sloan","avatar":""},{"name":"Lea Coco","avatar":""},{"name":"Tate Ellington","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Lucas Jade Zumann","avatar":""},{"name":"Jaden Klein","avatar":""},{"name":"Laila Haley","avatar":""},{"name":"Caden M. Fritz","avatar":""},{"name":"Olivia Rainey","avatar":""},{"name":"Nicholas King","avatar":""},{"name":"Delphine Pontvieux","avatar":""},{"name":"Michael B. Woods","avatar":""},{"name":"Tory O. Davis","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"