INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suzakinishi-the-animation', 'Suzakinishi The Animation', 'Suzakinishi The Animation', 'https://phimimg.com/upload/vod/20250913-1/30cc8ae40e6589b3ffaf363aa8774ed7.jpg', 'https://phimimg.com/upload/vod/20250913-1/4bfa8732aa311a26c83b42e2bea2360a.jpg', '<p>Một ngày nọ, có hai học sinh chuyển trường đến một ngôi trường trung học ở Tokyo: Aya Suzaki ngốc nghếch và Asuka Nishi vui tươi, lạc quan. Đối với cả hai, mỗi ngày trên giảng đường đều là một ngày hạnh phúc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Asuka Nishi","avatar":""},{"name":"Aya Suzaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["洲崎西 THE ANIMATION"]', 1784690324448);
