INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-vikings-phan-3', 'Huyền Thoại Vikings (Phần 3)', 'Vikings (Season 3)', 'https://phimimg.com/upload/vod/20250819-1/06f5c28f2e4644cc61b2baf75390734e.jpg', 'https://phimimg.com/upload/vod/20250819-1/0d0c6b7376c65021f8d1cf0b80a0a72f.jpg', '<p>Người Viking đưa chúng ta đến thế giới tàn khốc và bí ẩn của Ragnar Lothbrok, một chiến binh và nông dân Viking khao khát khám phá - và đột kích - bờ biển xa xôi trên đại dương.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Alex Høgh Andersen","avatar":""},{"name":"Jordan Patrick Smith","avatar":""},{"name":"Marco Ilsø","avatar":""},{"name":"Peter Franzén","avatar":""},{"name":"Georgia Hirst","avatar":""},{"name":"Danila Kozlovsky","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vikings"]', 1784690324448);
