INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nu-khong-kieng-cu', 'Tiên Nữ Không Kiêng Cữ', 'Bad Fairy', 'https://phimimg.com/upload/vod/20250812-1/79b2f212563c214947daaa72aef8a299.jpg', 'https://phimimg.com/upload/vod/20250812-1/495574b140e1077af645701fe1d47b11.jpg', '<p>Tiên Nữ Không Kiêng Cữ là một bộ phim hài hước do Việt Nam sản xuất xoay quanh câu chuyện về một tiên nữ vì yêu ngọc hoàng nên đã bị đày xuống hạ giới trải qua nhiều bể khổ để tu luyện thêm. Trong phim Tiên Nữ Không Kiêng Cữ thì nàng tiên của chúng ta không chỉ phải chịu những khó khăn thử thách mà cô còn có một nhiệm vụ quan trọng hơn là tìm ra năm đứa trẻ đại diện cho ngũ hành và giúp đỡ chúng vượt qua kiếp nạn thì tất cả mới có thể về trời phục chức. Liệu nàng tiên này có tìm ra được năm đứa trẻ để giúp đở chúng và trở về trời hay không, những thử thách gì đang chờ đợi cô phía trước? để biết được những điều đó mời các bạn đón xem phim Tiên Nữ Không Kiêng Cữ. Phim hứa hẹn sẻ mang lại những giây phút thư giang vô cùng thú vị đến tất cả quý vị khán giả.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Việt Hương","avatar":""},{"name":"Bảo Chung","avatar":""},{"name":"Phương Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Tiên Nữ Không Kiêng Cử"]', 1784690324448);
