INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-o-hong-kong', 'Lạc Lối Ở Hồng Kông', 'Lost In Hong Kong', 'https://phimimg.com/upload/vod/20250812-1/9f577423d579b18c678ddd321d303c2a.jpg', 'https://phimimg.com/upload/vod/20250812-1/4d942263607cd3f67426bba8f1b99843.jpg', '<p>Từ Lai (do Từ Trạch thủ vai) từng mơ ước trở thành một họa sĩ, nhưng giờ đây anh đã trở thành “pháo hôi” cho lý tưởng của chính mình, chỉ là một ông chủ nhỏ tại công ty quảng cáo của cha vợ. Anh là con rể ở rể, được cả nhà vợ coi là người thành đạt nhất, nhưng trong mắt anh, cả gia đình ấy đều quá tầm thường, và anh đổ lỗi cho họ vì đã khiến ước mơ của mình sụp đổ. Anh cũng có nhiều bất mãn với vợ (Triệu Vy thủ vai). Tại buổi họp lớp đại học, Từ Lai nghe bạn bè nhắc đến mối tình đầu Dương Y (Đỗ Tuyển thủ vai), lập tức lòng xao động. Ít lâu sau, khi cùng vợ và gia đình đến Hồng Kông du lịch, anh dự định lén gặp lại Dương Y sau nhiều năm xa cách. Không ngờ, anh lại bị cậu em vợ La La (Bào Bối Nhĩ thủ vai) bám theo. La La luôn mơ trở thành đạo diễn và đang quay một bộ phim tài liệu về gia đình. Trong lúc tìm cách hẹn gặp tình đầu, cả hai vô tình bị cuốn vào một vụ án mạng do rơi từ trên cao xuống. Chuyến gặp gỡ ngọt ngào dự tính ban đầu nhanh chóng biến thành một cuộc phiêu lưu và chạy trốn đầy kịch tính. Liệu Từ Lai và La La sẽ vượt qua được một ngày “khó quên” ở Hồng Kông này như thế nào?</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Trạch","avatar":""},{"name":"Triệu Vy","avatar":""},{"name":"Bào Bối Nhĩ","avatar":""},{"name":"Đỗ Tuyển","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85