INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-chan-dong', 'Vụ Án Chấn Động', 'The Exclusive: Beat The Devil''s Tattoo', 'https://phimimg.com/upload/vod/20250808-1/233fafb208142af77c0f7c4e2a8018c0.jpg', 'https://phimimg.com/upload/vod/20250808-1/4694a253105320e5b5e2a7954c7afe80.jpg', '<p>Sau khi tung tin sốt dẻo về một vụ án sắp xảy ra, Moo Hyuk (Jo Jung Suk) mới biết đó chỉ là tin giả. Đang đau đầu tìm cách cứu vãn sai lầm này, một vụ án mạng lại diễn ra đúng như tin tức anh đã đưa.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Jung-seok","avatar":""},{"name":"Lee Ha-na","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Bek Hyun-jin","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Choe Min","avatar":""},{"name":"Yoo Ji-hyun","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Exclusive: The Ryangchen Murders","Teukjong: Ryangchensalingi","Journalist","Scoop: Liang Chen Murder Record","특종 량첸살인기","The Exclusive  Beat the Devil''s Tattoo","造られた殺人：2015","특종: 량첸살인기"]', 1784690324448);
