INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-ky-tham-thu-phai-tra', 'Kiếm Ký: Thâm Thù Phải Trả', 'Memories Of The Sword', 'https://phimimg.com/upload/vod/20250808-1/8e35bdfcac1f77d18058e91437b03740.jpg', 'https://phimimg.com/upload/vod/20250808-1/ff721ad6a0554f255f9be107402f0fd1.jpg', '<p>Lấy bối vào cuối thời Goryeo, thời đại được trị vì bởi các thanh kiếm, Memories of the Sword là câu chuyện về ba vị kiếm khách. Yoo Baek (Lee Byung Hun), một con người ham muốn quyền lực. Wol So (Jeon Do Yeon), nữ kiếm khách mù có dung mạo của một nữ vương, luôn ra tay bảo vệ chính nghĩa và Hong Yi, cô gái ôm trong lòng mối thù phải trả. Mười tám năm trước, nhà vua đã có một giấc mơ về sự phản bội của những thanh kiếm. Không thoát khỏi định mệnh, ba vị kiếm khách tài danh với những lý tưởng riêng đã gặp nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Jeon Do-yeon","avatar":""},{"name":"Kim Go-eun","avatar":""},{"name":"Lee Jun-ho","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Kim Young-min","avatar":""},{"name":"Sung Yu-been","avatar":""},{"name":"Guzal Tursunova","avatar":""},{"name":"Bae Soo-bin","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Zhang Dong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Female Warrior: Memories of the Sword","Hyup-Nyeo: Kal-ui Gi-eok","Memories of the Sword","Hyeomnyeo: Kar-ui gi-eok","협녀, 칼의 기억"]', 1784690324448);
