INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-diet-5-thoi-dai-genisys', 'Kẻ Hủy Diệt 5: Thời Đại Genisys', 'Terminator Genisys', 'https://phimimg.com/upload/vod/20250806-1/72ceb0c2b13363155a432d9f7fa10d06.jpg', 'https://phimimg.com/upload/vod/20250806-1/fc067e41e9374187fe62a9fccf5be3d2.jpg', '<p>Terminator: Genesis là phần thứ năm của bộ phim Terminator nói về John Connor là người lãnh đạo loài người đứng lên đấu tranh như đã biết từ những phần trước mang trong mình &quot;Sứ mệnh cứu rỗi loài người John Connor&quot;. Một âm mưu mới của SkyNet đáng sợ và nguy hiểm hơn, anh phải làm gì để bảo vệ chính bản thân mình trước sự ám sát của những Kẻ hủy diệt ở quá khứ lẫn tương lai và kết cục có thể thay đổi chiến tranh mãi mãi.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emilia Clarke","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Matt Smith","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Dayo Okeniyi","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"Michael Gladis","avatar":""},{"name":"Sandrine Holt","avatar":""},{"name":"Wayne Bastrup","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"Otto Sanchez","avatar":""},{"name":"Matty Ferraro","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Ian","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Terminator 5","Термінатор 5","Terminator - Genisys - 3D","Terminátor Genisys","Terminátor: Genisys","O Exterminador do Futuro 5 - Gênesis","Terminatorius 5","Kẻ Hủy Diệt: Thời Đại Genisys","Терминатор Генезис","Terminator 5 - Genisys","终结者5","Terminator 5：Genesis","เทอร์มิเนเตอร์ 5 : มหาวิบัติจักรกลยึดโลก","Εξολοθρευτής: Γένεsys","未來戰士：創世智能","Terminator: Génesis","ターミネーター：新起動／ジェニシス：2015","Terminator Genisys"]', 1784690324448);
