INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-huy-diet-5-thoi-dai-genisys', 'Kẻ Hủy Diệt 5: Thời Đại Genisys', 'Terminator Genisys', 'kẻ hủy diệt 5: thời đại genisys terminator genisys emilia clarke jai courtney arnold schwarzenegger jason clarke matt smith j.k. simmons lee byung-hun dayo okeniyi courtney b. vance michael gladis sandrine holt wayne bastrup gregory alan williams otto sanchez matty ferraro griff furst ian terminator 5 термінатор 5 terminator - genisys - 3d terminátor genisys terminátor: genisys o exterminador do futuro 5 - gênesis terminatorius 5 kẻ hủy diệt: thời đại genisys терминатор генезис terminator 5 - genisys 终结者5 terminator 5：genesis เทอร์มิเนเตอร์ 5 : มหาวิบัติจักรกลยึดโลก εξολοθρευτής: γένεsys 未來戰士：創世智能 terminator: génesis ターミネーター：新起動／ジェニシス：2015 terminator genisys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-dau-cho-thoat', 'Chạy Đâu Cho Thoát', 'Veteran', 'https://phimimg.com/upload/vod/20250804-1/956edce00fe6ed55803d96e3f811f4f1.jpg', 'https://phimimg.com/upload/vod/20250804-1/911f5ef0a9e08e2c19c4a8e883943fa4.jpg', '<p>Veteran (Chạy Đâu Cho Thoát): Cảnh sát trưởng Seo Do-Cheol (Hwang Jung-Min đóng) rơi vào những tình huống khó khăn, nguy hiểm không chỉ với bản thân anh mà còn gia đình khi đương đầu với thiếu gia Cho Tae-Oh (Yoo Ah-In đóng) lắm tiền và nhiều chiêu để bao che những tội ác kinh khủng của gã. Đồng hành cùng anh là sự hỗ trợ hết mình từ sếp trực tiếp và đặc biệt là dàn cấp dưới hết lòng tận tụy và có phong cách “bá đạo” không-giống-ai khi lâm trận truy đuổi tội phạm.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-min","avatar":""},{"name":"Yoo Ah-in","avatar":""},{"name":"Yoo Hai-jin","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Jang Yoon-ju","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Kim Si-hoo","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Hwang Byeong-gug","avatar":""},{"name":"Park Jong-hwan","avatar":""},{"name":"Um","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92