INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-love-ru-darkness-2nd', 'To Love Ru Darkness 2Nd', 'To Love Ru Darkness 2Nd', 'https://phimimg.com/upload/vod/20250802-1/d90bf3165a607629c281abc30e01a440.jpg', 'https://phimimg.com/upload/vod/20250802-1/697027a81571a8512301edae5f9593fc.jpg', '<p>To Love-Ru Darkness 2nd (2015) là phần tiếp nối trực tiếp của To Love-Ru Darkness. Mặc dù vẫn giữ nguyên những yếu tố hài hước và ecchi đặc trưng, phần này tập trung phát triển sâu hơn cốt truyện và các mối quan hệ phức tạp giữa các nhân vật.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akeno Watanabe","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Misato Fukuen","avatar":""},{"name":"Sayuri Yahagi","avatar":""},{"name":"Kanae Itou","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Ryoka Yuzuki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["出包王女","To Love-Ru","To LOVEるーとらぶるー","To LOVEるーとらぶるーダークネス","To LOVEるーとらぶるーダークネス 2nd","もっとTo LOVEるーとらぶるー","Motto To LOVE-Ru","투 러브-루 트러블","투 러브 트러블","To LOVE 트러블","Любовь и прочие неприятности","ทูเลิฟรู","ทูเลิฟรู ดาร์กเนส","To Love-Ru Trouble Darkness","Motto To Love Ru","To LOVE Ru Darkness","To LOVEる -とらぶる-"]', 1784690324448);
