INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('to-love-ru-darkness-2nd', 'To Love Ru Darkness 2Nd', 'To Love Ru Darkness 2Nd', 'to love ru darkness 2nd to love ru darkness 2nd akeno watanabe haruka tomatsu misato fukuen sayuri yahagi kanae itou aki toyosaki kaori nazuka ayako kawasumi ryoka yuzuki 出包王女 to love-ru to loveるーとらぶるー to loveるーとらぶるーダークネス to loveるーとらぶるーダークネス 2nd もっとto loveるーとらぶるー motto to love-ru 투 러브-루 트러블 투 러브 트러블 to love 트러블 любовь и прочие неприятности ทูเลิฟรู ทูเลิฟรู ดาร์กเนส to love-ru trouble darkness motto to love ru to love ru darkness to loveる -とらぶる-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-quyet-3', 'Quỷ Quyệt 3', 'Insidious: Chapter 3', 'https://phimimg.com/upload/vod/20250731-1/70f1c602b3724fed9b3a8d39b1d4dfe7.jpg', 'https://phimimg.com/upload/vod/20250731-1/b448254047394521a7cdd07f1aaed836.jpg', '<p>Insidious: Chapter 3 (Ma Quái 3): Mở đầu với những hiện tượng kỳ quái quấy nhiễu cô bé Quinn Brenner, Insidious: Chapter 3 là phần tiền truyện (pre-quel) xảy ra trước khi Elise Rainier giúp đỡ gia đình Lambert. Trong teaser mới nhất, dấu hiệu ma quỷ đầu tiên xuất hiện khi Quinn Brenner nghịch ngợm gõ vào tường để liên lạc với cậu bạn hàng xóm. Dường như Quinn đã vô tình liên lạc với các linh hồn xấu và trở thành mục tiêu theo đuổi của chúng. Những hình ảnh ma quái liên tục xuất hiện trên nền nhạc “Tip Toe Through The Tulips”, du dương tới rợn người, khiến người xem dễ dàng bị ám ảnh. Cũng trong đoạn teaser này, khán giả có thể thấy Elise Rainier phải lần theo các dấu vết nhem nhuốc trên sàn nhà, và lạc vào thế giới ma quỷ giống như trong phần 1 và 2 của Insidious.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'FHD', 'Canada', 1, '[{"name":"Stefanie Scott","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Hayley Kiyoko","avatar":""},{"name":"Tom Gallop","avatar":""},{"name":"Tate Berney","avatar":""},{"name":"Corbett Tuck","avatar":""},{"name":"Tom Fitzpatrick","avatar":""},{"name":"Jeris Poindexter","avatar":""},{"name":"Ele Keats","avatar":""},{"name":"James Wan","avatar":""},{"name":"Joseph Bishara","avatar":""},{"name":"Michael Reid MacKay","avatar":""},{"name":"Phyllis Applegate","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["儿凶3","阴儿房第3章","Sobrenatural: Capítulo 3","인시디어스 3","Insidious Chapter 3","Insidious Capítulo 3","Παγιδευμένη Ψυχή: Κεφάλαιο 3","Insidious - Capítulo 3","Insidious 3","La noche del demonio: Capítulo 3","Коварен капан 3","Sobrenatural - A Origem","Insidious Chapitre 3","Insidious - Chapter 3","Insidieux : Chapitre 3","วิญญาณตามติด 3","อินซิเดียส 3","Quỷ Quyệt 3","Sobrenatural Capítulo 3","Insidious: Chapter 3"]', 1784690324448);
