INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thach-cam-dang', 'Thạch Cảm Đang', 'Journey To The East', 'https://phimimg.com/upload/vod/20250728-1/f40ae21e72f836f07ef3935a7cdf4eb5.jpg', 'https://phimimg.com/upload/vod/20250728-1/e5bef1e6e46c770a5b0c6ea634ee88ba.jpg', '<p>Bộ phim được lấy cảm hứng từ bộ phim Tây Du ký nổi tiếng 1986 và được chuyển thể theo tác phẩm Tây Du ký hậu truyện, Thạch Cảm Đang là bộ phim thần thoại cổ trang do Trung Quốc sản xuất. Bộ phim lấy bối cảnh đời nhà Đường, thời kỳ sau khi thầy trò Đường Tăng thỉnh kinh trở về, lúc này trời đất thông thiên, tam giới sống trong hòa bình. Tuy nhiên, thế lực yêu ma vẫn luôn ngấm ngầm thống trị tam giới.....</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 14, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Kiện","avatar":""},{"name":"Lục Tiểu Linh Đồng","avatar":""},{"name":"Lưu Đức Khải","avatar":""},{"name":"Hà Cương","avatar":""},{"name":"Tiền Yen Thu","avatar":""},{"name":"Thuần Vu San San","avatar":""},{"name":"Chung Vệ Hoa","avatar":""},{"name":"Trương Khải Y","avatar":""},{"name":"Quan Dụy","avatar":""},{"name":"Hàn Hàn","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shi Gandang Zhi Xiong Tian Tian Dong","Shi Gandang''s Heroes to Tiandong","Shi Dang''s Hero","石敢当之雄峙天东"]', 1784690324448);
