INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thach-cam-dang', 'Thạch Cảm Đang', 'Journey To The East', 'thạch cảm đang journey to the east trương tử kiện lục tiểu linh đồng lưu đức khải hà cương tiền yen thu thuần vu san san chung vệ hoa trương khải y quan dụy hàn hàn shi gandang zhi xiong tian tian dong shi gandang''s heroes to tiandong shi dang''s hero 石敢当之雄峙天东', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-than-tap-su-phan-2', 'Thổ Thần Tập Sự (Phần 2)', 'Kamisama Kiss (Season 2)', 'https://phimimg.com/upload/vod/20250728-1/94b6bd2701b520c74f8f57a8328799d0.jpg', 'https://phimimg.com/upload/vod/20250728-1/dd4ba78a12f83f846b58e7983557996b.jpg', '<p><span style="text-wrap-mode: wrap;">Câu chuyện kể rằng cha của nhân vật chính Nanami Momozono bỏ trốn vì nợ nần cờ bạc chồng chất, nhân vật chính bị bọn đòi nợ đuổi ra khỏi nhà. Trong lúc Nanami tuyệt vọng không biết đi đâu về đâu đã tình cờ giải cứu người đàn ông yếu đuối bị con chó rượt đuổi. Sau khi người đàn ông biết được hoàn cảnh của Nanami, anh ta bất ngờ nói \Tôi sẽ cho cô ngôi nhà của tôi\. Dù cảm thấy rất khó tin nhưng Nanami vẫn nửa tin nửa ngờ đi theo. Nhưng điểm đến hóa ra là một ngôi đền bỏ hoang. Danh tính của người đàn ông yếu ớt đó là một vị thổ thần bỏ nhà ra đi - Mikage. Để trở thành chủ nhân ngôi đền, Nanami chấp nhận các điều kiện do Mikage đưa ra, là thần thổ địa mới của ngôi đền, quản lý quyền lực của Mikage và lắng nghe nguyện vọng của các tín đồ. Do đó Nanami trở thành vị thổ thần mới. Đối mặt với nhiều chuyện do quái vật và các vị thần khác nhau gây ra, kinh nghiệm và tinh thần của cô ngày càng lớn, cô cũng có tình cảnh thâm sâu không thể xa cách với linh thần Tomoe. Cuộc sống đã thay đổi đáng kể kể từ đó...</span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Horie","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Daisuke Kishio","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Vanilla Yamazaki","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Shuta Morishima","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Shinnosuke Tachibana","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Natsuyo Atarashi","avatar":""},{"name":"Chika Ookubo","avatar":""},{"name":"Hiroki Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["元气少女缘结神","见习元气女神","אלוהים, נעים להכיר אותך","התחלתי להיות אלה","Kami-sama Hajimemashita","Kamisama Hajimemashita","神様はじめました◎","오늘부터 신령님","Очень приятно, Бог","Kami-sama Kiss","Divine Nanami","Kamihaji","神様はじめました"]', 1784690324448);
