INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-truong-ma-quai', 'Ngôi Trường Ma Quái', 'The Silenced', 'https://phimimg.com/upload/vod/20250727-1/e76323f6719f79e802f85dbec3f6b40d.jpg', 'https://phimimg.com/upload/vod/20250727-1/7ed55b9f05fae538025c5562679517dd.jpg', '<p>Cha Ju Ran (Park Bo Young) bị mẹ kế bắt chuyển vào sống ở trường nội trú vì bệnh tật. Tuy nhiên, đó lại là một ngôi trường ma quái khi cô dần phát hiện nhiều học sinh mất tích mà chẳng ai nhận ra.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Bo-young","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Park So-dam","avatar":""},{"name":"Kong Ye-ji","avatar":""},{"name":"Sim Hee-seop","avatar":""},{"name":"Go Won-hee","avatar":""},{"name":"Geum Sae-rok","avatar":""},{"name":"Joo Bo-bi","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Park Joo-hee","avatar":""},{"name":"Park Se-in","avatar":""},{"name":"Mok Gyu-ri","avatar":""},{"name":"Kim Dong-hyun","avatar":""},{"name":"Lee Ye-eun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gyeongseonghakyoo: Sarajin Sonyeodeul","Gyeongseong School: The Lost Girls","Gyeongseong School: Disappeared Girls","Sonyeo","Silenciadas","Vaiennetut","경성학교 - 사라진 소녀들","京城学校：消えた少女たち","京城学校:消えた少女たち","けいじょうがっこう きえたしょうじょたち","경성학교: 사라진 소녀들"]', 1784690324448);
