INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dau', 'Đối Đầu', 'Helios', 'https://phimimg.com/upload/vod/20250725-1/f82371ce4ef2bd4b6b7031ca93bbe67c.jpg', 'https://phimimg.com/upload/vod/20250725-1/667f322aee3210831f26e30f5b197ce3.jpg', '<p>Thiết bị hạt nhân di động mang tên DC8 bị đánh cắp từ Hàn Quốc bởi tên tội phạm khét tiếng &quot;Helios&quot; và trợ lý &quot;Messenger&quot; của hắn. Khi vũ khí này chuẩn bị được giao dịch tại Hong Kong, thanh tra Lý từ Đơn vị Phản ứng Chống Khủng bố đã thành lập một đội đặc nhiệm để thu hồi nó. Đội này bao gồm giáo sư vật lý Triệu Chí Nhân và các chuyên gia vũ khí Hàn Quốc như Choi và Park. Tuy nhiên, Helios luôn đi trước một bước, khiến nhiệm vụ trở nên vô cùng khó khăn, thậm chí là bất khả thi.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Hye Yoon","avatar":""},{"name":"Trương Chấn","avatar":""},{"name":"Kim Hae Sook","avatar":""},{"name":"Trương Học Hữu","avatar":""},{"name":"Dư Văn Lạc","avatar":""},{"name":"Văn Vịnh San","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["赤盜","Chek dou","ล่าคมถล่มเมือง","Helios","Đối Đầu","赤道"]', 1784690324448);
