INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-dai-thanh-tro-ve', 'Tây Du Ký: Đại Thánh Trở Về', 'Monkey King: Hero Is Back', 'https://phimimg.com/upload/vod/20250722-1/1d9167bc8050f67f891b8d71875f1681.jpg', 'https://phimimg.com/upload/vod/20250722-1/dd5bb75f52d4be10b5a12bf92ec9ac84.jpg', '<p>Bộ phim được dàn dựng dựa theo cuốn tiểu thuyết Tây Du Ký của nhà văn Ngô Thừa Ân, song có nhiều chi tiết mới. Monkey King Hero Is Back Mặc dù trong phim còn có “sạn”, bị một số nhà phê bình chỉ trích nội dung quá đơn giản, phim vẫn nhận được sự hưởng ứng nhiệt tình của công chúng, đặc biệt là từ các fan dòng phim hoạt hình. Phim lấy bối cảnh sau khi Tôn Đại Thánh trở về từ thiên đình chiến đấu với Thiên Binh Vạn Mã...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Lei","avatar":""},{"name":"Lin Zijie","avatar":""},{"name":"Tong Zirong","avatar":""},{"name":"Liu Beichen","avatar":""},{"name":"Zhou Shuai","avatar":""},{"name":"Liu Jiurong","avatar":""},{"name":"Zhao Qianjing","avatar":""},{"name":"James Hong","avatar":""},{"name":"Wu Wenlun","avatar":""},{"name":"Wu Di","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["西游记之大圣归来","Monkey King: The Hero","Monkey King : Hero Is Back","Xi you ji zhi da sheng gui lai","Le Roi Singe : Le Retour du héros","Monkey King : The Hero","西遊記之大聖歸來"]', 1784690324448);
