INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-du-ky-dai-thanh-tro-ve', 'Tây Du Ký: Đại Thánh Trở Về', 'Monkey King: Hero Is Back', 'tây du ký: đại thánh trở về monkey king: hero is back zhang lei lin zijie tong zirong liu beichen zhou shuai liu jiurong zhao qianjing james hong wu wenlun wu di 西游记之大圣归来 monkey king: the hero monkey king : hero is back xi you ji zhi da sheng gui lai le roi singe : le retour du héros monkey king : the hero 西遊記之大聖歸來', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-fargo-phan-2', 'Thị Trấn Fargo (Phần 2)', 'Fargo (Season 2)', 'https://phimimg.com/upload/vod/20250723-1/1487b0371ba62121a49ea45944233e74.jpg', 'https://phimimg.com/upload/vod/20250723-1/d611a32823729fd2ff436325da34f4a3.jpg', '<p>Fargo là một bộ phim truyền hình dài tập hài kịch tội phạm đen của Mỹ được tạo ra và chủ yếu được viết bởi Noah Hawley. Chương trình được lấy cảm hứng từ bộ phim cùng tên năm 1996 được viết và đạo diễn bởi anh em Coen, người được ghi là nhà sản xuất điều hành cho loạt phim cùng với Hawley. Sê-ri được công chiếu vào ngày 15 tháng 4 năm 2014, trên FX, và tuân theo định dạng hợp tuyển, với mỗi phần được đặt trong một thời đại khác nhau, và với một câu chuyện khác nhau và chủ yếu là các nhân vật và diễn viên mới, mặc dù có sự trùng lặp nhỏ. Mỗi mùa có rất nhiều tài liệu tham khảo cho phim của anh em Coen.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 13, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Juno Temple","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"David Rysdahl","avatar":""},{"name":"Joe Keery","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Richa Shukla Moorjani","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Sienna King","avatar":""},{"name":"Dave Foley","avatar":""},{"name":"Jon Hamm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雪花高离奇命案","冰血暴","FARGO/ファーゴ","Фарго","Fargo: Year One","Fargo: Year Two","Fargo: Year Three","Fargo: Year Four","Fargo: Year Five","Fargo"]', 1784690324448);
