INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-ma-tuy-phan-1', 'Trùm Ma Túy (Phần 1)', 'Narcos (Season 1)', 'https://phimimg.com/upload/vod/20250723-1/fdf6f49403f3a89b18688d9ddc66e711.jpg', 'https://phimimg.com/upload/vod/20250723-1/90c2929698225564655a15f2ca942fca.jpg', '<p>Bộ phim nói về cuộc đời của Pablo Escobar, ông trùm ma túy khét tiếng người Colombia, kẻ đã làm cả nước Mỹ chao đảo với hàng tấn cocain ào ạt đổ về quốc gia này. Mang phong cách hình sự cộng thêm yếu tố tài liệu với các tình tiết và hình ảnh có thật trong lịch sử đã từng đem lại thành công vang dội cho một bộ phim khác cũng nói về đề tài ma túy là City of God, Narcos hứa hẹn sẽ mang đến cái nhìn cận cảnh và chân thực nhất về tác hại và sự nguy hiểm của thứ hàng trắng đáng sợ này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pedro Pascal","avatar":""},{"name":"Matias Varela","avatar":""},{"name":"Damián Alcázar","avatar":""},{"name":"Francisco Denis","avatar":""},{"name":"Alberto Ammann","avatar":""},{"name":"Pêpê Rapazote","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Michael Stahl-David","avatar":""},{"name":"Matt Whelan","avatar":""},{"name":"Andrea Londo","avatar":""},{"name":"Manolo Cardona","avatar":""},{"name":"Natalia Jerez","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Дилъри","نارکوس","Барыги","Narcos: Colombia","Narcos"]', 1784690324448);
