INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-phu-thuy-phan-2', 'Thị Trấn Phù Thuỷ (Phần 2)', 'Salem (Season 2)', 'https://phimimg.com/upload/vod/20250717-1/251e5679e2ee19cbed7fcb350e103515.jpg', 'https://phimimg.com/upload/vod/20250717-1/cc1cc09f5f8028076ab1fbc727f92939.jpg', '<p>Lấy bối cảnh thế kỷ 17 đầy biến động ở Massachusetts, *Salem* khám phá những nguyên nhân thực sự đã thổi bùng các phiên tòa xét xử phù thủy nổi tiếng tại thị trấn này, và mạnh dạn vạch trần sự thật siêu nhiên đen tối ẩn sau tấm màn của giai đoạn tai tiếng trong lịch sử nước Mỹ. Ở Salem, phù thủy là có thật — nhưng họ không phải là những gì người ta vẫn nghĩ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Janet Montgomery","avatar":""},{"name":"Shane West","avatar":""},{"name":"Seth Gabel","avatar":""},{"name":"Tamzin Merchant","avatar":""},{"name":"Ashley Madekwe","avatar":""},{"name":"Elise Eberle","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Oliver Bell","avatar":""},{"name":"Joe Doyle","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Salem"]', 1784690324448);
