INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khung-long', 'Thế Giới Khủng Long', 'Jurassic World', 'https://phimimg.com/upload/vod/20250717-1/c3a2c4e60e6b4bf6aad37bdd6c368101.jpg', 'https://phimimg.com/upload/vod/20250717-1/ec074feb0460485073b1b8bc649cb6f1.jpg', '<p>Trong Jurassic World (Thế giới khủng long), lấy bối cảnh 22 năm sau sự kiện ở Công viên kỷ Jura phần 3. Công viên kỷ Jura ngày nào giờ đã trở thành công viên Khủng long thật sự. Tuy nhiên, khu tham quan này lại rất vắng khách, vì người dân không còn chuộng những con quái vật cổ đại nữa. Để thu hút khách trở lại, tập đoàn sở hữu Masrani quyết định lai tạo ra một loài khủng long mới, nhưng điều đó nhanh chóng dẫn đến thảm họa. Jurassic World sẽ là bộ phim bom tấn đầy hứa hẹn tiếp theo của “Star Lord” Chris Pratt, nam diễn viên đã ghi dấu ấn đậm nét trong Guardian of Galaxy vào năm ngoái.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Irrfan Khan","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Nick Robinson","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Lauren Lapkus","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Katie McGrath","avatar":""},{"name":"Andy Buckley","avatar":""},{"name":"Eric Edelstein","avatar":""},{"name":"Courtney James Clark","avatar":""},{"name":"Colby Boothman-Shep","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jurassic Park 4","Jurassic Park IV","쥬라기 공원 4","Mundo Jurásico","Jurassic Park 4 - Jurassic World","Jurassic Park IV Jurassic World","เปิดสวนโลกไดโนเสาร์","Svet iz doba jure","Park iz doba jure 4","Jūros periodo parkas","פארק היורה 4: עולם היורה","Jurassic Park 4 - Jurassic World - O Mundo dos Dinossauros","侏儸紀世界","Le monde jurassique","Jurassic Park IV: Jurassic World","ジュラシック・ワールド：2015","侏罗纪世界","侏罗纪世界1","Jurassic World"]', 1784690324448);
