INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-lam-con-do', 'Tập Làm Côn Đồ', 'Get Hard', 'https://phimimg.com/upload/vod/20250712-1/789b090253d3f89690e46923f1a3cb2b.jpg', 'https://phimimg.com/upload/vod/20250712-1/7d06f05ccd82f7fc69b964e35fae1b13.jpg', '<p>Khi người quản lý quỹ hàng rào giàu kinh hoàng James (Will Ferrell) bị kết án gian lận và bị kết án một đoạn ở San Quentin, thẩm phán sẽ cho anh ta một tháng để có được công việc của mình theo thứ tự. Biết rằng anh ta sẽ không sống sót sau một vài phút tù giam, James trở nên tuyệt vọng chuyển sang Darnell (Kevin Hart) - một doanh nhân da đen thậm chí còn không bao giờ có một vé đậu xe - để được giúp đỡ. Khi Darnell đưa James qua Wringer, cả hai đều biết rằng họ đã sai về nhiều thứ, bao gồm cả nhau.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Craig T. Nelson","avatar":""},{"name":"T.I.","avatar":""},{"name":"Greg Germann","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Mariana Paola Vicente","avatar":""},{"name":"Katia Gomez","avatar":""},{"name":"Candi Brooks","avatar":""},{"name":"Jimmy Fallon","avatar":""},{"name":"Edwina Findley","avatar":""},{"name":"Erick Chavarria","avatar":""},{"name":"Ariana Neal","avatar":""},{"name":"Paul Ben-Victor","avatar":""},{"name":"John Mayer","avatar":""},{"name":"Jon Eyez","avatar":""},{"name":"Nito Larioza","avatar":""},{"name":"Dan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Durão","30 días para ir a la cárcel","Sert Ol","Dale Duro","ゲットハード/Get Hard","ゲットハード／Get Hard","ゲットハード","Sərt Ol","Get Hard"]', 1784690324448);
