INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-gau-ted-2', 'Chú Gấu Ted 2', 'Ted 2', 'https://phimimg.com/upload/vod/20250712-1/4beacda2a7743195dc74e1e76ee0f724.jpg', 'https://phimimg.com/upload/vod/20250712-1/8cd0164a105071abb4aa7ff0d2f05203.jpg', '<p>Chú Gấu Ted 2 kể về một cậu bé tên John đã ước một điều ước vào sinh nhật 6 tuổi của mình rằng chú gấu bông Ted của mình có thể nói chuyện và đi lại như con người, và điều ước đã thành hiện thực tên tuổi của John và Ted nổi tiếng khắp Thế Giới, đến khi John trưởng thành Ted cảm thấy mình dần dần xa lạ với John vì sư xuất hiện của bạn gái anh, thế nhưng đó vẫn không thể thay thế được tình bạn lâu năm của cả hai người.
 Tiếp theo phần 2 của bộ phim này John và Ted sẽ có một cuộc phiêu lưu đầy mới mẻ sau khi thoát khỏi tai họa của một người bố vì thương con nên đã bắt cóc Ted và gây ra cho anh cái kết không mấy đẹp đẽ. John kết hôn với bạn gái của mình và họ sinh con, một gia đình tốt đẹp và Ted sẽ phải làm thế nào chứng tỏ chổ đứng của mình trong đó?</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Jessica Barth","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Sam J. Jones","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Michael Dorn","avatar":""},{"name":"Bill Smitrovich","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Cocoa Brown","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Ron Canada","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Patr","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Тед 2","テッド2：2015","テッド2","賤熊2","Ted 2"]', 1784690324448);
