INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-6-do-hoi', 'Bộ 6 Dở Hơi', 'The Ridiculous 6', 'https://phimimg.com/upload/vod/20250712-1/d2df05f85194a8c9a761800561018437.jpg', 'https://phimimg.com/upload/vod/20250712-1/484d70f3bb03ccddf48779661504bfe3.jpg', '<p>Khi người cha sống ngoài vòng pháp luật bị bắt cóc, Tommy “White Knife” Stockburn cùng 5 người anh em mà anh chưa từng biết đến đi khắp miền Tây để giải cứu cha.</p>', 'Full', 1, 'single', 'completed', 21, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Taylor Lautner","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Jon Lovitz","avatar":""},{"name":"Whitney Cummings","avatar":""},{"name":"David Spade","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Blake Shelton","avatar":""},{"name":"Vanilla Ice","avatar":""},{"name":"Julia Jones","avatar":""},{"name":"Saginaw","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Os 6 Ridículos","Los 6 Ridículos","los 6 ridiculos","Los Seis Ridiculos","The Ridiculous 6 - Die lächerlichen Sechs","หกโคบาลบ้า ซ่าระห่ำเมือง","The Ridiculous 6","荒唐六蛟龍"]', 1784690324448);
