INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-gan-ben-anh', 'Lại Gần Bên Anh', 'Be With Me', 'https://phimimg.com/upload/vod/20250711-1/9254fb445199779b9934dfe6eca99c44.jpg', 'https://phimimg.com/upload/vod/20250711-1/e34d77f76c39a1700d36597bf57aba90.jpg', '<p>Khi nhóm nhạc Rage Boys ở đỉnh cao sự nghiệp thì Khang Trấn Anh, giọng ca chính của nhóm, lại dính vào tin đồn tình ái với con gái của người quản lý là Viên An An. Anh quyết định công khai chuyện tình cảm và rời khỏi giới giải trí để được ở bên người mình yêu. Nào ngờ An An lại quyết định chia tay, khiến anh trở thành kẻ thất bại trong sự nghiệp lẫn tình yêu. Mười năm sau, Trấn Anh giờ đã là chủ một nhà hàng và có một cô con gái đáng yêu. Thế nhưng, cuộc sống yên bình của anh lại một lần nữa đảo lộn khi gặp lại An An.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2015, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Dư Thừa Ân","avatar":""},{"name":"Ngụy Như Quân","avatar":""},{"name":"Huỳnh Hà","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["舞吧舞吧在一起"]', 1784690324448);
