INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-an-thit-nguoi-phan-3', 'Bác Sĩ Ăn Thịt Người (Phần 3)', 'Hannibal (Season 3)', 'https://phimimg.com/upload/vod/20250709-1/8edc5ff16d2095fd25b37fbe044f342f.jpg', 'https://phimimg.com/upload/vod/20250709-1/acaeb8a3aeaedbc6ad298baa0b844061.jpg', '<p>Hannibal là một bộ phim truyền hình nhiều tập thuộc thể loại kinh dị viễn tưởng, điều tra hiện trường vụ án của Mỹ, sản xuất năm 2012 và được phát triển bởi Bryan Fuller cho kênh truyền hình NBC. Bộ phim dựa trên những nhân vật và các tình tiết xảy ra trong cuốn tiểu thuyết Red Dragon của Thomas Harris với một bối cảnh hiện đại và tập trung vào các mối quan hệ vừa bắt đầu giữa điều tra viên đặc biệt Graham Will của FBI và Tiến sĩ Hannibal Lecter, một bác sĩ tâm thần pháp y đã trở thành đối thủ xảo quyệt nhất của Graham Will. Phim được công chiếu 13 tập cho mùa ra mắt đầu tiên và không giống như hầu hết các chương trình công chiếu trước đây tại Hoa Kỳ, bất kỳ mùa chiếu ra mắt trong tương lai, mỗi phim truyền hình cũng sẽ có 13 tập. David Slade điều hành sản xuất và chỉ đạo thí điểm. Bộ phim công chiếu lần đầu trên kênh NBC ngày 04 Tháng Tư năm 2013.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 13, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mads Mikkelsen","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Caroline Dhavernas","avatar":""},{"name":"Gillian Anderson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ханибал","汉尼拔","هانیبال","ハンニバル","Ганнибал","هانيبال","ฮันนิบาล","Hannibal"]', 1784690324448);
