INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-cu-thich-em', 'Vẫn Cứ Thích Em', 'Destined To Love You', 'https://phimimg.com/upload/vod/20250703-1/6a2e3fdaf0c6985cdf68ef427d31b101.jpg', 'https://phimimg.com/upload/vod/20250703-1/3c80c8ddc58784a48ad074464e0c208e.jpg', '<p>Vì muốn cứu chữa mẹ mang trọng bệnh, Bảo Bảo giả mạo Tiêu Hàm, một nữ tiến sĩ du học vừa qua đời, trở thành sĩ quan huấn luyện trong học viện quân sự. Để giấu thân phận, cô phải trốn tránh cả vị hôn phu và một người đàn ông theo đuổi cô rất nhiệt tình. Trớ trêu thay, Tiêu Hàm quay trở về và cũng khi ấy, quân Nhật lăm le bờ cõi.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 13, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Kiều Ân","avatar":""},{"name":"Giả Nãi Lượng","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Pian Pian Xi Huan Ni","偏偏喜欢你"]', 1784690324448);
