INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sinh-sat-thu', 'Song Sinh Sát Thủ', 'Legend', 'https://phimimg.com/upload/vod/20250624-1/f83a4667deedc8d82c827e27c90bd4f2.jpg', 'https://phimimg.com/upload/vod/20250624-1/610b1bd555376ce196f05af7e361bec8.jpg', '<p>Dựa trên tiểu sử có thật của anh em nhà Kray, cặp gangster lừng danh ở London suốt thập niên 60. Tài tử Tom Hardy đã xuất sắc hóa thân vào hai nhân vật toàn hoàn trái ngược Ronald và Reginald Kray.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Emily Browning","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Taron Egerton","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Colin Morgan","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Tara Fitzgerald","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Nicholas Farrell","avatar":""},{"name":"Duffy","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"John Sessions","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Millie Brady","avatar":""},{"name":"Charley Palmer","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["黑道传奇","金牌黑帮","Легенда [Legend]","Lendas do Crime","Legend - Legenden der Unterwelt","Leyenda: La Profesión de la Violencia","Legend"]', 1784690324448);
