INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-la-vung-troi', 'Bao La Vùng Trời', 'Triumph In The Skies', 'https://phimimg.com/upload/vod/20250624-1/8ef983817c92fea56750cad35fdbb0cc.jpg', 'https://phimimg.com/upload/vod/20250624-1/1a3e2f5a127d4c65fd061501124c6d34.jpg', '<p>Bao La Vùng Trời xoay quanh cuộc sống và tình cảm của những cơ trưởng đẹp trai là Branson, Sam và Jayden. Branson là giám đốc điều hành một hãng hàng không nổi tiếng, tình cờ gặp lại người yêu cũ Gia Thi sau bao năm xa cách và tình cảm cũ chợt ùa về. Còn Sam bất ngờ nảy sinh chuyện tình một đêm với ngôi sao nhạc Rock TM để rồi từ đó nhận ra anh không thể thiếu cô trong đời. Chàng phi công hào hoa Jayden có tính cách cao ngạo và lãng tử cũng vướng vào nhiều mối quan hệ yêu đương phức tạp với các bóng hồng nóng bỏng qua các chuyến bay.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Trịnh Tú Văn","avatar":""},{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Trương Trí Lâm","avatar":""},{"name":"Xa Thi Mạn","avatar":""},{"name":"Mã Quốc Minh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["冲上云霄","衝上雲霄","Bao La Vùng Trời"]', 1784690324448);
