INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-nguoi-hoa', 'Phố Người Hoa', 'Coin Locker Girl', 'https://phimimg.com/upload/vod/20250618-1/15d86bb727701b2e8c7fd9f1f01cdb88.jpg', 'https://phimimg.com/upload/vod/20250618-1/c92b848393d68585a176be53c757fcc3.jpg', '<p>Một đứa trẻ bị bỏ rơi trong tủ đựng tiền xu tàu điện ngầm bị bán cho một tên cho vay nặng lãi và trùm xã hội đen tàn nhẫn và tính toán được gọi là Mẹ, người điều hành một đường dây thu hoạch nội tạng ở Phố Tàu Incheon. Được đặt tên là Il-Young, cô bé lớn lên thành cánh tay phải trung thành của Mẹ và được chuẩn bị để trở thành người kế nhiệm cuối cùng của bà. Nhưng khi lòng trung thành của Il-Young với Mẹ dao động, cuộc đụng độ giữa hai người đã giải phóng một làn sóng trả thù và xung đột đẫm máu không thương tiếc.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-soo","avatar":""},{"name":"Kim Go-eun","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Cho Hyun-chul","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Jo Bok-rae","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Oh Yu-jin","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Lee Chae-dam","avatar":""},{"name":"Oh Si-eun","avatar":""},{"name":"Yoon Yeong-gyun","avatar":""},{"name":"Gi J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b03060