INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-gio', 'Xé Gió', 'To The Fore', 'https://phimimg.com/upload/vod/20250616-1/13275a5c34f1aab55f09f3c44fb6a349.jpg', 'https://phimimg.com/upload/vod/20250616-1/946d81a284bebabb8710b6d0a5f53d1f.jpg', '<p>Lấy ba tay đua xe đạp tài năng làm trọng tâm, đạo diễn Lâm Siêu Hiền thành công khắc họa những pha đua xe kịch tính, đồng thời đào sâu về ước mơ, tình bạn, thử thách trong thể thao và cuộc sống.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Bành Vu Yến","avatar":""},{"name":"Choi Si Won","avatar":""},{"name":"Đậu Kiêu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["파풍","破风","破風","疾風スプリンター","Прийти первым"]', 1784690324448);
