INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-pixels', 'Đại Chiến Pixels', 'Pixels', 'https://phimimg.com/upload/vod/20250616-1/fe6572645a7575c63eb304252ca4615c.jpg', 'https://phimimg.com/upload/vod/20250616-1/764176e575af2baaaab44f17b04262da.jpg', '<p>Phim là câu chuyện được khởi đầu từ một phi thuyền thời gian chứa thông điệp hòa bình, gồm các ví dụ về cuộc sống và văn hóa của loài người được NASA gửi đi năm 1982 với hi vọng tìm kiếm các thực thể sống khác. Tuy nhiên, phi thuyền này lại được gửi đi không đúng cách, khiến cho những người ngoài hành tinh dịch sai thành thông điệp đe dọa, và tiến hành đổ bộ xâm chiếm trái đất. Chúng sử dụng các trò chơi điện tử cổ điển của trái đất để xây dựng mô hình cho các cuộc tấn công. Để chống lại cuộc xâm lược này, tổng thống William Cooper (Kevin James) đã kêu gọi sự giúp đỡ của nhóm bạn học cũ, đứng đầu là cựu vô địch video games năm 1980 Sam Brenner (Adam Sandler) với mục đích đánh bại người ngoài hành tinh và giải cứu trái đất.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Matt Lintz","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Denis Akiyama","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Lainie Kazan","avatar":""},{"name":"Ashley Benson","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Tim Herlihy","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"Jared Sandler","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Hành Động",