INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-cuu-hoa-chicago-2015', 'Đội Cứu Hoả Chicago (Phần 4)', 'Chicago Fire (Season 4)', 'đội cứu hoả chicago (phần 4) chicago fire (season 4) taylor kinney david eigenberg joe miñoso christian stolte miranda rae mayo daniel kyri hanako greensmith jocelyn hudon jake lockett dermot mulroney chicago fire : caserne 51 风城烈火 芝加哥烈火群英 chicago fire שיקגו fire שיקגו פייר آتش‌نشانی شیکاگو чикаго в огне one chicago chicago fire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-thoai-co-tich', 'Giai Thoại Cổ Tích', 'Tale Of Tales', 'https://phimimg.com/upload/vod/20250531-1/68a98f75055097f30b22648b0c962393.jpg', 'https://phimimg.com/upload/vod/20250531-1/57c3397cc66c0a28b3112594aea7c8b0.jpg', '<p>Bộ phim là một tác phẩm điện ảnh đầy mê hoặc, được đạo diễn bởi Matteo Garrone, lấy cảm hứng từ bộ truyện cổ tích của Giambattista Basile – một nhà văn Ý thế kỷ 17. Bộ phim là sự kết hợp độc đáo giữa các yếu tố thần thoại, kỳ ảo và hiện thực đen tối, tạo nên một câu chuyện đa tầng vừa kinh dị vừa cuốn hút. Phim kể lại ba câu chuyện cổ tích chính, mỗi câu chuyện mang một màu sắc độc đáo: một nữ hoàng khát khao có con và không ngần ngại sử dụng phép thuật để đạt được mục đích; một vị vua mù quáng chạy theo sắc dục, khiến mình trở nên hèn mọn; và một công chúa bị cuốn vào hành trình nguy hiểm khi tìm kiếm tự do và hạnh phúc. Những câu chuyện tưởng như riêng biệt nhưng lại được kết nối tinh tế bởi bối cảnh chung là những vương quốc xa hoa và huyền bí. Cuộc sống là vô thường. Khi con người muốn mình trở nên hạnh phúc, đẹp đẽ hay khao khát những điều mà mình không thể nào với tới được thì cái giá phải trả, có khi chính là bằng xương, bằng máu, bằng hạnh phúc mà mình đang có. Ở đời, không chuyện gì là hiển nhiên, không chuyện gì là tự nhiên mà có, thế nên con người càng tham lam, càng ham muốn điều gì bao nhiêu thì phải chấp nhận trả cái giá lớn bấy nhiêu. “Tale of tales” đã mang đến cho người xem bài học như vậy.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Salma Hayek Pinault","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Hayley Carmichael","avatar":""},{"name":"Bebe Cave","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Christian Lees","avatar":""},{"name":"Jonah Lees","avatar":""},{"name":"Guillaume Delaunay","avatar":""},{"name":"Alba Rohrwacher","avatar":""},{"name":"Massimo Ceccherini","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Laura Pizzirani","avatar":""},{"name":"Franco Pistoni","avatar":""},{"name":"Jessie Ca","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Le conte des contes","테일 오브 테일즈","O conto dos contos","流言蜚語","El cuento de los cuentos","Das Märchen der Märchen","Pentameron","故事中的故事","Tale of Tales","Казка казок","Το Παραμύθι των Παραμυθιών","Bir Varmış Bir Yokmuş","Nağılların Nağılı","Visu stāstu stāsts","Il racconto dei racconti"]', 1784690324448);
