INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giai-thoai-co-tich', 'Giai Thoại Cổ Tích', 'Tale Of Tales', 'giai thoại cổ tích tale of tales salma hayek pinault vincent cassel toby jones shirley henderson hayley carmichael bebe cave stacy martin christian lees jonah lees guillaume delaunay alba rohrwacher massimo ceccherini john c. reilly laura pizzirani franco pistoni jessie ca le conte des contes 테일 오브 테일즈 o conto dos contos 流言蜚語 el cuento de los cuentos das märchen der märchen pentameron 故事中的故事 tale of tales казка казок το παραμύθι των παραμυθιών bir varmış bir yokmuş nağılların nağılı visu stāstu stāsts il racconto dei racconti', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nhung-hiep-si-khong-gian', 'Doraemon: Nobita và Những Hiệp Sĩ Không Gian', 'Doraemon: Nobita and the Space Heroes', 'https://phimimg.com/upload/vod/20250521-1/c832788f0ccff91be65f6407a30977bf.jpg', 'https://phimimg.com/upload/vod/20250521-1/20fdeb6170c47e4ddc6f88e6756cb116.jpg', '<p>Một ngày Doraemon, Nobita, Shizuka, Gian và Suneo quay một bộ phim về đề tài những anh hùng vũ trụ. Khi họ đang làm thì bất ngờ gặp một sinh vật ngoài sinh vật tên là Aron đang chạy trốn kẻ thù, thấy được sức mạnh của nhóm Aron đã nhờ cứu giúp hành tinh của cậu ấy khỏi những quái vật vũ trụ. Nhóm Nobita đồng ý và chiến đấu hết mình để giúp mặc dù chiến đấu với những quái vật ấy là không dễ dàng.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2015, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Yûji Tanaka","avatar":""},{"name":"Yutaka Furukawa","avatar":""},{"name":"Arisa Mizuki","avatar":""},{"name":"Masachika Ichimura","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Nobuyuki Kobushi","avatar":""},{"name":"Nobuaki Sekine","avatar":""},{"name":"Katsumi Toriumi","avatar":""},{"name":"Kenji Kitamura","avatar":""},{"name":"Ai Fuka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["ドラえもん　のび太の宇宙英雄記（スペースヒーローズ）","Doraemon: Nobita''s Space Heroes","のび太の宇宙英雄記","Doraemon: Nobita no Space Heroe Uchū Eiyū-ki","大雄的宇宙英雄記","도라에몽: 노비타의 우주영웅기~스페이스 히어로즈~","哆啦A夢：大雄之宇宙英雄記","노비타의 우주영웅기","Doraemon - Il film: Nobita e gli eroi dello spazio","哆啦A梦：大雄的宇宙英雄记","Doraemon Nobita and the Space Heroes","映画ドラえもん のび太の宇宙英雄記","哆啦A梦 大雄的宇宙英雄记"]', 1784690324448);
