INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-chien-thang', 'Ngày Mai Chiến Thắng', 'Tomorrow Victory', 'https://phimimg.com/upload/vod/20250521-1/7c92c02fbebb61316fb0fcefe45cee2e.jpg', 'https://phimimg.com/upload/vod/20250521-1/92bbb4cf59267ff615b1081601df6bf4.jpg', '<p>Sau khi cha của Han Seung-ri chết oan uổng, gia đình sa sút, sau đó lại bị người yêu phản bội. Nhưng để tiếp tục công việc kinh doanh của gia đình cha và thực hiện ước mơ của mình, cô đã không nản chí, và lại kiên cường đứng lên như một con lật đật.</p>', 'Hoàn Tất (130/130)', 130, 'series', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon So-min","avatar":""},{"name":"Phillip Choi","avatar":""},{"name":"Song Won-geun","avatar":""},{"name":"Sun Woo-chul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["내일도 승리"]', 1784690324448);
