INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-rong-2015', 'Kiếm Rồng', 'Dragon Blade', 'https://phimimg.com/upload/vod/20231124-1/026ec5bc18b13eb1c8058e9c94b43247.jpg', 'https://phimimg.com/upload/vod/20231124-1/97554eef2f1c439391a0b130c213f4a9.jpg', '<p>Phim Kiếm Rồng lấy bối cảnh diễn ra dưới thời Tây Hán, phim xoay quanh câu chuyện của đại tướng quân Hoắc An (Thành Long) với sứ mệnh bảo vệ sự bình yên cho các nước chư hầu ở Tây Vực. Với tài năng, sự kiên trung và tình yêu hòa bình, Hoắc An đã liên kết với các huynh đệ từng vào sinh ra tử với mình lập nên liên minh “Quyết tử cho hòa bình”. &nbsp;Thế nhưng, ông lại bị gian thần hãm hại, bị đày tới biên cương và chịu cảnh nô dịch hà khắc. May mắn thay, Hoắc An đã được đại tướng quân Tiberius (John Cusack) trên đường hộ tống hoàng tử tới phương Đông giải thoát. Từ đây, hai vị tướng quân anh hùng gắn kết thành tâm giao tri kỷ cùng chung lý tưởng bảo vệ chính nghĩa, xây dựng hòa bình. Hai người sát cánh bên nhau trải qua hàng loạt những trận đấu ly kỳ và những sự kiện đầy chấn động.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Sharni Vinson","avatar":""},{"name":"Kevin Lee","avatar":""},{"name":"Raiden Integra","avatar":""},{"name":"Tomer Oz","avatar":""},{"name":"Alfred Hsing","avatar":""},{"name":"Max Huang","avatar":""},{"name":"Sammy Hung","avatar":""},{"name":"Paul Philip Clark","avatar":""},{"name":"Lorie Pester","avatar":""},{"name":"Joel Adrian","avatar":""},{"name":"Joel Adrian","avatar":""},{"name":"Harry Oram","avatar":""},{"name":"Kyle Shapiro","avatar":""},{"name":"Jonathan Paulson","avatar":""},{"name":"Vander McLeod","avatar":""},{"name":"Philippe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324448);
