INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-mang-ten-ove', 'Người Đàn Ông Mang Tên Ove', 'A Man Called Ove', 'https://phimimg.com/upload/vod/20250516-1/309d5180b20c004cdef310ad742e2d6e.jpg', 'https://phimimg.com/upload/vod/20250516-1/05a5cc2ed220930ab56767e4486fe336.jpg', '<p>Ông Ove, 59 tuổi, bỗng một hôm nhận được lời đề nghị “Ông nghỉ ngơi một chút cũng tốt mà” từ chỗ làm mà ông đã trung thành gắn bó trong hơn một phần ba thế kỷ. Vừa mất vợ cách đó 6 tháng, lại trở thành người thừa thãi trong xã hội, ông lão ít nói, cộc tính, gàn dở và cay nghiệt này bèn tìm cách tự tử theo &quot;phong cách Ove&quot;: được chuẩn bị trước, tính toán tỉ mỉ để không làm phiền đến ai. Nhưng mỗi lần Ove bắt đầu thực hiện ý định thì luôn có một sự việc gì đó bất thình lình ập đến khiến ông phải tạm gác lại “thôi để mai”...</p>', 'Full', 1, 'single', 'completed', 31, 2015, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Rolf Lassgård","avatar":""},{"name":"Bahar Pars","avatar":""},{"name":"Filip Berg","avatar":""},{"name":"Ida Engvoll","avatar":""},{"name":"Tobias Almborg","avatar":""},{"name":"Klas Wiljergård","avatar":""},{"name":"Chatarina Larsson","avatar":""},{"name":"Börje Lundberg","avatar":""},{"name":"Stefan Gödicke","avatar":""},{"name":"Johan Widerberg","avatar":""},{"name":"Anna-Lena Brundin","avatar":""},{"name":"Nelly Jamarani","avatar":""},{"name":"Zozan Akgün","avatar":""},{"name":"Viktor Baagøe","avatar":""},{"name":"Simon Edenroth","avatar":""},{"name":"Poyan Karimi","avatar":""},{"name":"Maja Rung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mees nimega Ove","Κάποιος που τον έλεγαν Όβε","En man som heter Ove","Друге життя Уве","Ove Adındaki Bir Adam","Mr. Ove"]', 1784690324448);
