INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-dan-ong-mang-ten-ove', 'Người Đàn Ông Mang Tên Ove', 'A Man Called Ove', 'người đàn ông mang tên ove a man called ove rolf lassgård bahar pars filip berg ida engvoll tobias almborg klas wiljergård chatarina larsson börje lundberg stefan gödicke johan widerberg anna-lena brundin nelly jamarani zozan akgün viktor baagøe simon edenroth poyan karimi maja rung mees nimega ove κάποιος που τον έλεγαν όβε en man som heter ove друге життя уве ove adındaki bir adam mr. ove', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minions', 'Minions', 'Minions', 'https://phimimg.com/upload/vod/20250516-1/5cfe23ba2bfed409242dd48deb8c334c.jpg', 'https://phimimg.com/upload/vod/20250516-1/63e14ac151b40ef5aed5e0c715d9a7c0.jpg', '<p>Câu chuyện kể về các Minion trước khi gặp chủ nhân Gru (xuất hiện ở 2 phần Kẻ Cắp Mặt Trăng trước), bắt đầu từ buổi bình minh của nhân loại, xuất phát điểm là những sinh vật đơn bào màu vàng, Minion dần tiến hóa qua các thời đại và luôn trung thành phụng sự những kẻ xấu xa, tàn ác nhất. Nhưng chủ nhân của chúng cứ lần lượt biến mất – từ loài khủng long bạo chúa tới Napoleon.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Katy Mixon","avatar":""},{"name":"Michael Beattie","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Dave Rosenbaum","avatar":""},{"name":"Alex Dowding","avatar":""},{"name":"Paul Thornley","avatar":""},{"name":"Kyle Balda","avatar":""},{"name":"Ava Acres","avatar":""},{"name":"Sherry","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["המיניונים","小黄人大眼萌","Mimoni","小小兵","Minions: O Filme","Despicable Me - Minions","미니언즈","Ha''Minionim","Մինիոններ","迷你兵團","Illumination''s Minions","Minions"]', 17