INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('to-quoc-phan-5', 'Tổ Quốc (Phần 5)', 'Homeland (Season 5)', 'tổ quốc (phần 5) homeland (season 5) claire danes mandy patinkin maury sterling numan acar nimrat kaur linus roache costa ronin хоумленд מולדת ホームランド homeland: v mene vlasti 國土安全 homeland', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-tro-ve', 'Hạnh Phúc Trở Về', 'Return of Happiness', 'https://phimimg.com/upload/vod/20250514-1/ad8cd87542d4bcd64115d1989592e6e3.jpg', 'https://phimimg.com/upload/vod/20250514-1/4526a927ba653b830112e3fe76e7f178.jpg', '<p>Nội dung: Ron tên Hàn Minh, 25 tuổi, người thừa kế duy nhất tập đoàn Hàn thị chuyên về thuyền buồm,là người cơ trí, nhìn xa trông rộng, tính cách có phần lạnh lùng nhưng lại vừa có tính trẻ con, thuộc chòm sao xử nữ nên có yêu cầu cao đối với mọi việc, mong muốn 1 tình yêu hoàn mỹ, cùng nữ chính là cặp thanh mai trúc mã.Lúc nhỏ, nữ chính vì 1 tai nạn biển bị mất trí nhớ, sau này cả 2 gặp lại nhưng không nhận ra nhau, trở thành 1 cặp oan gia. Tiếp xúc trong công việc dần dần nảy sinh tình cảm, sau đó phát hiện thân phận thật sự của nữ chính, ra sức giúp đỡ cô ấy lấy lại thân phận. Nhân vật của Lý Tẩm tên Đinh Ngãi Gia, con gái của chủ tịch tập đoàn Đinh thị, cha không may gặp tai nạn biển trở thành người thực vật phải sang Mỹ điều trị. Không lâu sau, bản thân cũng gặp tai nạn biển, mất trí nhớ dc 1 ngư dân cứu sống, nhận nuôi đặt tên là Ngư Ấu Vi. Mặc dù lớn lên trong 1 hoàn cảnh cơ cực, cha thì nhu nhược, mẹ lạnh nhạt, em trai đau bệnh nhưng luôn kiên cường, lạc quan, có niềm đam mê với thuyền buồm và biển cả.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 10, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Qin","avatar":""},{"name":"Guo Jiahao","avatar":""},{"name":"Ron Ng Cheuk-Hai","avatar":""},{"name":"Tong Yixuan","avatar":""},{"name":"Yang Yuting","avatar":""},{"name":"Liu Wenzhi","avatar":""},{"name":"Qin Yan","avatar":""},{"name":"Ji Qilin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["幸福归来"]', 1784690324448);
