INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-ty-do-lot', 'Công Ty Đồ Lót', 'Atelier', 'công ty đồ lót atelier mirei kiritani mao daichi mayuko kawakita ken kaito wakana sakai maiko masako chiba dori sakurada nicole ishida megumi sato 內衣白領風雲 andâwea underwear andaawea atelier ателье อเทลิเย่ アンダーウェア', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-si-ha-son', 'Đạo Sĩ Hạ Sơn', 'Monk Comes Down The Mountain', 'https://phimimg.com/upload/vod/20250506-1/cca04e231922ddf717f491b532fe7e77.jpg', 'https://phimimg.com/upload/vod/20240220-1/496805748de37e8b844f6668d274ad33.jpg', '<p>Thời kỳ dân quốc, Trung Quốc đang bị ngoại địch xâm chiếm, hỗn chiến quân phiệt xảy ra khắp nơi, từ đó đã sản sinh ra các nhân vật giang hồ thời loạn thế. Một tiểu đạo sĩ tên Hà An Hạ không rành thế sự đã rời đạo quán của mình xuống núi nhập vào hồng trần, một chân bước vào một loạt các sự kiện quỷ dị và gặp gỡ những nhân vật truyền kỳ. Sau đó một mình Hà An Hạ kinh doanh phường dược, trong một lần vô tình anh đã bị cuốn vào ân oán nơi giang hồ, Hà An Hạ bị một đạo sĩ quét rác mai danh ẩn tích võ công cao cường tên Chu Tây Ninh thuyết phục rồi tự nguyện bái sư. Cùng lúc đó, sư đệ Bành Càn Ngô cũng đằng đằng sát khí mà tìm đến cửa. Nhân vật ông chủ Tra xuất hiện càng khiến tình tiết phim được đẩy lên cao trào. Lên núi, xuống núi, chỉ trong một khoảng thời gian ngắn dường như Hà An Hạ đã ngộ ra được rất nhiều chân lý, cũng hiểu được câu nói của sư phụ: &quot;Không từ thủ đoạn nào thì chính là hào kiệt, nhưng không thay đổi ước nguyện thuở ban sơ mới là một anh hùng&quot;.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Chấn","avatar":""},{"name":"Vương Bảo Cường","avatar":""},{"name":"Quách Phú Thành","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Lâm Chí Linh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324448);
