INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-si-ha-son', 'Đạo Sĩ Hạ Sơn', 'Monk Comes Down The Mountain', 'đạo sĩ hạ sơn monk comes down the mountain trương chấn vương bảo cường quách phú thành nguyên hoa lâm chí linh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-duy-nhat-mot-nua-linh-hon-vi-em', 'Tình Yêu Duy Nhất (Một Nửa Linh Hồn Vì Em)', 'Two Spirits Love (Song Huajai Nee Puea Tur)', 'https://phimimg.com/upload/vod/20250502-1/c25b884f8f5048d649a6a526dde6864a.jpg', 'https://phimimg.com/upload/vod/20250502-1/4673e9b989e708ef31c8986d0b4b4f14.jpg', '<p>Bộ phim kể câu chuyện xoay quanh Tharatorn (Mario Maurer), chàng giám đốc một công ty nội thất có khả năng điều khiển đồ vật và mắc chứng đa nhân cách, với cô gái trẻ Kewalin (Mint) - tình nguyện viên cho một tổ chức cứu hộ. Sau cuộc gặp gỡ định mệnh xuất phát từ một tai nạn tình cờ, cả hai gặp lại nhau khi Kewalin xin vào làm cho công ty của Tharatorn. Anh thấy bối rối vì Kewalin giống hệt hình bóng cô gái mà anh vẫn hay nằm mơ thấy bao năm qua. Còn Kewalin, cô cũng ngạc nhiên khi thấy anh chàng tự xưng là Mek, ngất xỉu trước cửa nhà mình hôm trước lại không nhớ ra cô. Tharatorn để Kewalin làm trợ lý của anh. Rồi hai người lại bị cuốn vào những âm mưu trả thù, toan tính đen tối của những kẻ giấu mặt. Cũng trong thời gian này, nhân duyên kỳ lạ đã giúp họ phát hiện ra sự thật chấn động: kiếp trước, Tharatorn từng là một vị quan có tên là Warong và Kewalin mang tên Kaew. Hơn nữa, họ còn yêu nhau say đắm. Tình yêu quá khứ và tình yêu hiện tại, kiếp trước và kiếp này, hai chàng trai trong một thân xác cùng dâng trọn trái tim cho một cô gái. Liệu đến cuối cùng, Tharatorn - Kewalin có thể hoàn thành câu chuyện dở dang mà ngày xưa họ đã bỏ lỡ hay không?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 19, 2015, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mario Maurer","avatar":""},{"name":"Chalida Vijitvongtong","avatar":""},{"name":"Prama Imanothai","avatar":""},{"name":"Non Thanalop","avatar":""},{"name":"Nattapong Chatpong","avatar":""},{"name":"Nutcha Naphak Janjitranon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Song Huajai Nee Puea Tur","สองหัวใจนี้เพื่อเธอ"]', 1784690324448);
