INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-duy-nhat-mot-nua-linh-hon-vi-em', 'Tình Yêu Duy Nhất (Một Nửa Linh Hồn Vì Em)', 'Two Spirits Love (Song Huajai Nee Puea Tur)', 'tình yêu duy nhất (một nửa linh hồn vì em) two spirits love (song huajai nee puea tur) mario maurer chalida vijitvongtong prama imanothai non thanalop nattapong chatpong nutcha naphak janjitranon song huajai nee puea tur สองหัวใจนี้เพื่อเธอ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-sinh-dai-y', 'Thương Sinh Đại Y', 'Half For The People, Half For Beauties', 'https://phimimg.com/upload/vod/20250427-1/9afa5c4c480d11a6ce78f63fd5b775d9.jpg', 'https://phimimg.com/upload/vod/20250427-1/ae40d5c94aadbb1fcb9b5cfa29fc49a1.jpg', '<p>Thần y tái thế Hoa Đà là người đam mê nghiên cứu các phương thuốc mới và luôn áp dụng những kiến thức học được để cứu giúp người nghèo. Dù chỉ muốn trở thành một thầy thuốc giỏi, con đường sự nghiệp của Hoa Đà luôn gặp nhiều sóng gió khi vô tình phải tham gia vào các cuộc tranh đấu giành quyền lực chốn triều đình.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 25, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Thịnh Minh","avatar":""},{"name":"Lý Y Hiểu","avatar":""},{"name":"Chu Hiểu Ngư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["苍生大医","Empyrean Doctor","半为苍生半美人"]', 1784690324448);
