INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-tinh-giang-son', 'Đa Tình Giang Sơn', 'Royal Romance', 'https://phimimg.com/upload/vod/20250424-1/be43b62701b7c89a034b5588025b5c9b.jpg', 'https://phimimg.com/upload/vod/20250424-1/ca78c2d938ed1053b8c9fc6bfba22413.jpg', '<p>Hoàng đế Thuận Trị (do Cao Vân Tường thủ vai) trong một lần vi hành đã gặp gỡ và đem lòng yêu ca nữ Đổng Tiểu Uyển (do Hầu Mộng Dao thủ vai). Bất chấp lệnh cấm của triều đình về việc người Hán không được vào cung, ông đưa nàng vào hậu cung và phong làm phi tử. Mối tình của họ vấp phải sự phản đối mạnh mẽ từ Thái hậu Hiếu Trang (do Viên Vịnh Nghi thủ vai) và các đại thần, dẫn đến nhiều biến cố trong triều. Tuy nhiên, với tình yêu chân thành và sự thông minh, hiền hậu của mình, Đổng Tiểu Uyển dần chiếm được cảm tình của Thái hậu và các quan lại. Khi tình yêu của họ vừa được chấp nhận, một trận dịch đậu mùa bùng phát, cướp đi sinh mạng của Đổng Tiểu Uyển, để lại nỗi đau khôn nguôi cho Hoàng đế Thuận Trị.</p>', 'Hoàn Tất (77/77)', 77, 'series', 'completed', 9, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vân Tường","avatar":""},{"name":"Hầu Mộng Dao","avatar":""},{"name":"Viên Vịnh Nghi","avatar":""},{"name":"Vạn Tử Lương","avatar":""},{"name":"Từ Kỳ Văn","avatar":""},{"name":"Mễ Lộ","avatar":""},{"name":"Cao Thịnh Huy","avatar":""},{"name":"Lưu Việt","avatar":""},{"name":"Kỳ Hàng","avatar":""},{"name":"Mã Giới","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Royal Romance","Tuyệt Sắc Khuynh Thành","多情江山"]', 1784690324448);
