INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('da-tinh-giang-son', 'Đa Tình Giang Sơn', 'Royal Romance', 'đa tình giang sơn royal romance cao vân tường hầu mộng dao viên vịnh nghi vạn tử lương từ kỳ văn mễ lộ cao thịnh huy lưu việt kỳ hàng mã giới royal romance tuyệt sắc khuynh thành 多情江山', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-cua-vo-toi', 'Người Tình Của Vợ Tôi', 'My Wife''s Lover', 'https://phimimg.com/upload/vod/20250422-1/9c2f90c8c0fb7978d89b8e6728b6b4bc.jpg', 'https://phimimg.com/upload/vod/20250422-1/bb25716ed679e675480b78601c59ea14.jpg', '<p>Mi-yeon là một người phụ nữ luôn sống hết lòng vì chồng và con, gần như mù quáng hy sinh cho gia đình. Với cô, gia đình là tất cả, là điều thiêng liêng không gì có thể thay thế. Cheol-min, chồng cô, đang chịu áp lực nặng nề mỗi ngày vì một dự án sống còn – giành được quyền phát sóng trên kênh mua sắm tại nhà của công ty. Vài ngày sau, khi hay tin đối thủ đã giành được quyền phát sóng, Cheol-min tuyệt vọng tìm đến Hyun-gil, một tiền bối thời đại học hiện đang làm việc trong lĩnh vực mua sắm tại nhà. Hyun-gil nói rằng kết quả đã được định đoạt từ trước. Trong lúc đó, Mi-yeon vô tình xuất hiện ở cửa, và sau khi biết chuyện, cô quyết định đến nhà Hyun-gil với hy vọng giúp chồng vượt qua khó khăn. Tuy nhiên, tại đây, Hyun-gil đưa ra một đề nghị bí mật dành cho Mi-yeon...</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-jeong","avatar":""},{"name":"Lee Hyeon-seong","avatar":""},{"name":"Jeong Tae-min","avatar":""},{"name":"Im So-mi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["아내의 애인"]', 1784690324448);
