INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-long-tranh-ba', 'Lục Long Tranh Bá', 'Six Flying Dragons', 'https://phimimg.com/upload/vod/20250414-1/8cfa733e0682cc078f239d9fb9ec219d.jpg', 'https://phimimg.com/upload/vod/20250414-1/2770d5fed701b70c247c9a66df5ae58d.jpg', '<p>Sĩ Flying Dragons là bộ phim chuyển thể từ quyển tiểu thuyết cùng tên, được sản xuất cho lễ kỉ niệm 25 năm của đài truyền hình SBS. Phim kể về quá trình xây dựng triều đại Joseon sau khi vương triều được thiết lập bởi Hoàng đế Tae Jo và tể tướng Jung Do Yeon. Joseon vừa được thành lập thì nhiều cuộc xung đột và bạo loạn giữa 6 phiến quân đồng loạt nổ ra, trong đó nổi bật nhất là Lee Bang Won (còn gọi là Yi Bang Won) - người con thứ ba của vua Tae Jo. Hoàng tử Lee Bang Won vốn dĩ có tham vọng biến triều đại Joseon thành vương triều theo chế độ quân chủ lập hiến nhưng do vấp phải sự phản đối mạnh mẽ của Hoàng đế Tae Jo nên đã đứng lên làm loạn.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 14, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Ah-in","avatar":""},{"name":"Kim Myung-min","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Yoon Kyun-sang","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Jeong Yu-mi","avatar":""},{"name":"Park Hyuk-kwon","avatar":""},{"name":"Min Sung-wook","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Yoon Son-ha","avatar":""},{"name":"Gong Seung-yeon","avatar":""},{"name":"Lee Cho-hee","avatar":""},{"name":"Han Ye-ri","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Jeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["六龙飞天","Yookryongi Nareushya","Roots of the Throne","육룡이 나르샤"]', 1784690324448);
