INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-huyen-bi-2', 'Khách Sạn Huyền Bí 2', 'Hotel Transylvania 2', 'https://phimimg.com/upload/vod/20250412-1/8c4adba9cf090db93127e45c1658cfba.jpg', 'https://phimimg.com/upload/vod/20250412-1/7029e8a26a252669386a75e328c1d1ec.jpg', '<p>Trong Hotel Transylvania 2, chủ khách sạn ma cà rồng Dracula (Adam Sandler) giờ đã có cháu ngoại lai hai dòng máu người-ma, và đang nuôi ý định biến nó trở thành giống mình. Vấn đề nằm ở chỗ, thằng bé không hề có tố chất của ma cà rồng. Dracula đành phải tập hợp một đội ngũ “đào tạo” bao gồm Frankenstein, Người sói, Người vô hình… về làm công tác huấn luyện. Hotel Transylvania 2 hứa hẹn sẽ là một phim hoạt hình dễ thương, hài hước tuyệt vời dành cho cả gia đình trong năm nay.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2015, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Adam Sandler","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"David Spade","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Asher Blinkoff","avatar":""},{"name":"Fran Drescher","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Megan Mullally","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Dana Carvey","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Jonny Solomon","avatar":""},{"name":"Chris Kattan","avatar":""},{"name":"Sadie San","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["몬스터 