INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-manh-me-2015', 'Người Phụ Nữ Mạnh Mẽ', 'Iron Lady Cha', 'https://phimimg.com/upload/vod/20250410-1/bb998ee57af01863ada32b24381e01f1.jpg', 'https://phimimg.com/upload/vod/20250410-1/79c703e7ff451d3984e6d2c8498087a3.jpg', '<p>“Người phụ nữ mạnh mẽ” chỉ ra những vấn đề nội bật như: Người trẻ sử dụng những từ ngữ mà thế hệ già hơn không thể hiểu được, những cuộc hẹn hò thông thường đã mang một ý nghĩa mới cho giới trẻ và nhìn vào một gia đình 3 thế hệ, chúng ta có thể nhận ra các khía cạnh khác nhau của xã hội. Bộ phim cũng mô tả cuộc sống hàng ngày của Cha Mi Ran, người phụ nữ bất khuất, người quan trọng kết nối các thành viên của cả đại gia đình 3 thế hệ.</p>', 'Full', 111, 'series', 'completed', 11, 2015, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Bo-yeon","avatar":""},{"name":"Oh Kwang-rok","avatar":""},{"name":"Lee Ga-ryeong","avatar":""},{"name":"Park Yoon-jae","avatar":""},{"name":"Shin Min Soo","avatar":""},{"name":"Ha Yeon-joo","avatar":""},{"name":"Kim Yong-geon","avatar":""},{"name":"Lee Yoon-mi","avatar":""},{"name":"Min Ji-a","avatar":""},{"name":"Jung Young-sook","avatar":""},{"name":"Sun Woo-chul","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不屈的車女士","불굴의 차여사"]', 1784690324448);
