INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cua-eva', 'Tình Yêu Của Eva', 'Eve''s Love', 'https://phimimg.com/upload/vod/20250411-1/2dd7932f2a6618d7cb5332eecc0893e3.jpg', 'https://phimimg.com/upload/vod/20250411-1/355e9000eae0ad05538b71a2e7ab6d4a.jpg', '<p>Bộ phim xoay quanh những câu chuyện về sự phản bội của tình bạn, sự trả thù của nhân vật chính Song-ah, người đã vượt qua đau khổ mất mát để xây dựng lại tài sản gia đình và tìm được tình yêu đích thực sau khi phải nếm trải sự đổ vỡ, đắng cay.</p>', 'Hoàn Tất (120/120)', 120, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Se-a","avatar":""},{"name":"Lee Jae-hwang","avatar":""},{"name":"Seo Gwang-jae","avatar":""},{"name":"Yeo Hoi-hyeon","avatar":""},{"name":"Yang Geun-seok","avatar":""},{"name":"Kim Yeong-hoon","avatar":""},{"name":"Kim Mi-ryeo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Love of Eve","Eves Love","Eve''s Love","Tình Yêu Của Eva","이브의 사랑"]', 1784690324448);
