INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-phap-su-phan-3', 'Hội Pháp Sư (Phần 3)', 'Fairy Tail (Season 3)', 'https://phimimg.com/upload/vod/20250406-1/6533bef16c005cc0b3c5370b64ea7b7c.jpg', 'https://phimimg.com/upload/vod/20250406-1/7c259f8434916aab21ba0cd7c3a9d8c9.jpg', '<p>Bộ Phim Hội Pháp Sư có nội dung chính về Lucy, cô gái trẻ 17 tuổi với mong ước trở thành một pháp sư đầy quyền năng. Trên đường phiêu lưu thực hiện ước mơ, Lucy tình cờ gặp được một bộ đôi quái gở - Natsu và Happy, đang trên đường tìm kiếm Hỏa Long Igneel - tại Thị trấn Hargeon. Ước mơ của Lucy là được tham gia vào Bang hội, nơi tập trung đầy pháp sư tài giỏi.</p>', 'Hoàn Tất (51/51)', 51, 'hoathinh', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Wataru Hatano","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Mai Nakahara","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Ryoko Ono","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Shinpachi Tsuji","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c8922