INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-phap-su-phan-3', 'Hội Pháp Sư (Phần 3)', 'Fairy Tail (Season 3)', 'hội pháp sư (phần 3) fairy tail (season 3) tetsuya kakihara aya hirano rie kugimiya yuichi nakamura sayaka ohara satomi sato yui horie hiroki yasumoto wataru hatano hiroki touchi mai nakahara katsuyuki konishi ryoko ono daisuke namikawa eri kitamura shinpachi tsuji mamiko noto tak 妖精的尾巴 魔导少年 ekor peri fearī teiru フェアリーテイル ゼロ fairy tail 妖精たちの合宿 fairy tailファイナルシリーズ フェアリーテイル сказка о хвосте феи фейри тейл хвост феи 魔導少年 fairy tail zero fairy tail final series fairy tail final season fairy tail', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-mot-tinh-yeu', 'Mãi Mãi Một Tình Yêu', 'Neung Nai Suang', 'https://phimimg.com/upload/vod/20250404-1/b8dac676795f4d890aefbbd82e2fff7b.jpg', 'https://phimimg.com/upload/vod/20250404-1/5903b7fac4ffd157b5166639ce7d7e4a.jpg', '<p>Sau khi tốt nghiệp với tấm bằng thạc sĩ ngoại giao tại Pháp, Anawat Patcharapojanaj [Neung] - con trai của nhà cựu ngoại giao nổi tiếng Wit Patcharapojanaj, quyết định quay về Thái Lan làm việc. Tin tức đã thu hút rất nhiều sự quan tâm của các cô gái khắp Phrah Nakorn, ngoại trừ Hathairath Rachapitak [Poom]. Thuở nhỏ Poom cùng anh trai Pu và chị gái Pan thường xuyên được bố mẹ đưa đến chơi tại nhà Patcharapojanaj. Vì mồ côi cha mẹ và được hai bác đưa về nuôi dưỡng mà Poom luôn bị Neung trêu chọc. Trong kí ức của Poom, Neung là một cậu nhóc ích kỉ, hiếu thắng và xem thường người khác. Vì thế nên khi gặp lại anh tại một buổi tiệc, cô đã từ chối nhảy cùng anh. Neung vốn không nhận ra Poom vì cô bé ú nu ngày nào đã trưởng thành một cô gái xinh đẹp bao người theo đuổi. Ấn tượng đầu tiên không hay cộng thêm nhiều lời vo ve không đúng sự thật, Neung cho rằng Poom là một cô gái xấu xa mê hoặc đàn ông giàu có. Cả hai tuyên bố rằng sẽ không thể nào thích đối phương. Thế nhưng khi gạt bỏ định kiến sang một bên, liệu hai người sẽ có cảm nhận thế nào về nhau? Tình cảm chớm nở liệu có đơm hoa kết trái?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jirayu Tangsrisuk","avatar":""},{"name":"Urassaya Sperbund","avatar":""},{"name":"Ronnadet Wongsaroj","avatar":""},{"name":"Fair Gundon Akhazzan","avatar":""},{"name":"Kriengkrai Oonhanun","avatar":""},{"name":"Kanin Stanley","avatar":""},{"name":"Pattrakorn Tungsupakul","avatar":""},{"name":"Kalaya Lerdkasemsap","avatar":""},{"name":"Sukol Sasijulaka","avatar":""},{"name":"Kummun Klomkaew","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Namnung Suttidachanai","avatar":""},{"name":"Noon Daran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["หนึ่งในทรวง"]', 1784690324448);
