INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mai-mai-mot-tinh-yeu', 'Mãi Mãi Một Tình Yêu', 'Neung Nai Suang', 'mãi mãi một tình yêu neung nai suang jirayu tangsrisuk urassaya sperbund ronnadet wongsaroj fair gundon akhazzan kriengkrai oonhanun kanin stanley pattrakorn tungsupakul kalaya lerdkasemsap sukol sasijulaka kummun klomkaew daraneenute pasutanavin namnung suttidachanai noon daran หนึ่งในทรวง', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-bua-truyen-2', 'Tây Du Ký Bựa Truyện 2', 'The Grow 2', 'https://phimimg.com/upload/vod/20250403-1/1c386ed1b5c2ef7c030d4720ce9ee16d.jpg', 'https://phimimg.com/upload/vod/20250403-1/972b6d4aa366340a18735c76ef78b3bd.jpg', '<p>Đường Tăng bị yêu quái bắt đi, để lại Tôn Ngộ Không, Trư Bát Giới và Sa Tăng rơi vào một cuộc khủng hoảng niềm tin. Cả ba tranh cãi kịch liệt, khiến tình thế càng thêm nguy cấp. Thì ra, Sa Tăng vốn là một bán yêu từng lầm đường lạc lối, nhưng trong khoảnh khắc sinh tử, anh đã được La Hán Hàng Long Phục Hổ khai sáng, giúp quay về chính đạo. Như Lai Phật Tổ đã giao cho Sa Tăng một nhiệm vụ cực kỳ quan trọng: bí mật hỗ trợ Tôn Ngộ Không, ngôi sao phương Tây. Sau nhiều trắc trở, ba huynh đệ cuối cùng cũng hóa giải hiểu lầm, cùng nhau lần theo manh mối để tìm kiếm sư phụ. Họ bước vào một không gian dị giới, nơi đang chờ đón họ chính là Tứ Thiên Vương U Minh đầy quyền năng. Muốn phá vỡ kết giới để cứu Đường Tăng, họ phải vượt qua Tứ Sát Cung, nơi bị bốn vị thần ma trấn giữ. Thế nhưng, giữa trận chiến sinh tử, Sa Tăng và các huynh đệ không hề hay biết rằng, họ đã rơi vào một cái bẫy tinh vi do thủ lĩnh Đội Đặc Chủng Thái Tuế giăng sẵn… Liệu họ có thể vượt qua tất cả để giải cứu sư phụ hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 32, 2015, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Yu","avatar":""},{"name":"Tianhao Wu","avatar":""},{"name":"Rong Rong","avatar":""},{"name":"Yuan Zhang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["金箍棒传奇2：沙僧的逆袭"]', 1784690324449);
