INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-thu-han', 'Tình Yêu Và Thù Hận', 'Swaragini', 'https://phimimg.com/upload/vod/20250329-1/b5fc826e696c76f478d6d5f8720b860b.jpg', 'https://phimimg.com/upload/vod/20250329-1/98da8fdc699c8516aa2dd29c1bfbb382.jpg', '<p>Bộ phim&nbsp;là một câu chuyện xoay quanh tình yêu và hận thù của hai chị em cùng cha khác mẹ Swara Bose và Rigini Gadodia. Swara và Ragini vốn là đôi bạn tâm giao từ khi còn nhỏ. Mặc dù họ được nuôi dưỡng, giáo dục trong hai gia đình hoàn toàn khác biệt, nhưng niềm đam mê âm nhạc đã nối kết họ với nhau. Tình bạn đẹp đẽ giữa Swara và Ragini bị cấm cản vì hai gia đình có mối hiềm khích khó hòa giải.</p>', 'Hoàn Tất (245/245)', 245, 'series', 'completed', 14, 2015, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Helly Shah","avatar":""},{"name":"Varun Kapoor","avatar":""},{"name":"Namish Taneja","avatar":""},{"name":"Parineeta Borthakur","avatar":""},{"name":"Shalini Kapoor","avatar":""},{"name":"Sonica Handa","avatar":""},{"name":"Tejasswi Prakash","avatar":""},{"name":"Dalljiet Kaur","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Swaragini: Jodein Rishton Ke Sur","Swaragini"]', 1784690324449);
