INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-manh-ghep-cam-xuc', 'Những Mảnh Ghép Cảm Xúc', 'Inside Out', 'https://phimimg.com/upload/vod/20250327-1/e2f05f7ebd9ac578a394e05503750be5.jpg', 'https://phimimg.com/upload/vod/20250327-1/33fe8f3b9aaa555f936345d071d0f8df.jpg', '<p>Phim Inside Out là bộ phim dài thứ 15 của Disney và Pixar kể về cô bé tuổi teen bình thường Riley. Như bao bạn bè đồng trang lứa khác, bước vào tuổi dậy thì là một quá trình gian nan với Riley, và cô bé còn bị thử thách bởi một biến cố bất ngờ khi buộc phải chia tay bạn bè, và cuộc sống hiện tại để cùng bố mẹ đến sống tại một thành phố hoàn toàn xa lạ. &nbsp;Cũng như tất cả chúng ta, Riley chịu sự điều khiển của cảm xúc bên trong tâm trí mình, và với Inside Out, những cảm xúc đó đã được nhân cách hóa thành những nhân vật trên màn ảnh, đó là: Joy (Vui vẻ), Fear (Sợ sệt), Anger (Giận dữ), Sadness (Buồn bã) và Disgust (Chán ghét).</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Amy Poehler","avatar":""},{"name":"Phyllis Smith","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Lewis Black","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Kaitlyn Dias","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Paula Poundstone","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Paula Pell","avatar":""},{"name":"Dave Goelz","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Josh Cooley","avatar":""},{"name":"Flea","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Peter S","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Intensamente","Del Revés (Inside Out)","Tərs Üz","Brenda mendjes","Á röngunni","Daroon va Biroon","Ha''kol ba''rosh","Ойжұмбақ","Divertida-Mente","The Untitled Pixar Movie That Takes You Inside the Mind","Boshqotirma","ظاهر و باطن","Inside Out 3D","Вэрхал у галаве","インサイドヘッド","Del revés","Inside Out"]', 1784690324449);
