INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-co', 'Trùm Cỏ', 'Master Of Grass', 'https://phimimg.com/upload/vod/20250324-1/deff0f1c0501306eeefbc73fea3fd99c.jpg', 'https://phimimg.com/upload/vod/20250324-1/7f5706a67550af5350b0ca96de4467ae.jpg', '<p>Được thừa kế một trang trại cỏ đẹp như mơ nhưng anh chàng Mộc Lâm lại vung tay bán cả sản nghiệp, lên thành phố thực hiện ước mơ thành “trùm nhạc”. Mộc Lâm không ngờ từng bước chân mình đều có sự rình rập của một bộ ba quỷ quái với âm mưu khó hiểu. Câu chuyện càng trở nên oái oăm hơn khi Mộc Lâm rơi vào nhóm hút cỏ và đột ngột thăng hoa thành một ngôi sao âm nhạc với những sáng tác bay bổng, kỳ quái... Bộ phim gây chú ý với dàn sao ăn khách như Trấn Thành, Việt Hương, Thu Trang, Hari Won, Quang Đăng, thậm chí cả ca sĩ vườn ổi Lệ Rơi cũng góp mặt, bên cạnh sự tham gia đặc biệt của David R. Hardberger, đạo diễn hình ảnh cho loạt phim bom tấn Chúa Tể Của Những Chiếc Nhẫn. Hài hước, trẻ trung, có những cảnh quay đặc sắc về cỏ và cái kết bất ngờ là điểm nhấn của bộ phim này.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Việt Hương","avatar":""},{"name":"Trấn Thành","avatar":""},{"name":"Hari Won","avatar":""},{"name":"Quang Đăng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Trùm Cỏ"]', 1784690324449);
