INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trum-co', 'Trùm Cỏ', 'Master Of Grass', 'trùm cỏ master of grass việt hương trấn thành hari won quang đăng trùm cỏ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-bai-vo-dang', 'Triều Bái Võ Đang', 'Wudang Rules', 'https://phimimg.com/upload/vod/20250319-1/3f9bd91d5f3dc90feeb2b48fc4a8528f.jpg', 'https://phimimg.com/upload/vod/20250319-1/d83633855ec6f52a7bf36d48e5326edf.jpg', '<p>Bao Kế Xung (do Tiền Tiểu Hào đóng) là cảnh sát nằm vùng, anh ẩn mình tại núi Võ Đang bởi bị một sự đả kích lớn. Ở đó Xung gặp lại sư tỷ Mao Ỷ San (do Nguyên Thu đóng). San đang kinh doanh cho thuê nhà trọ và dạy võ thuật. San mời Xung làm đầu bếp, đồng thời cũng cho Hà Chính Đông (do Quách Chính Hồng đóng) - một anh chàng điên khùng chẳng biết lai lịch, tá túc. Núi Võ Đang vốn dĩ yên bình tự dưng xảy ra nhiều sóng gió, bởi một nhóm người đến học võ. Các học viên đó gồm: con gái San là Lạc Dương (do Dương Di đóng), Trương Gia Cảng (do Hồng Thiên Minh đóng) - một cao thủ võ đài, chàng công tử nhà giàu La Diệc Hiên (do Trương Dĩnh Khang đóng), Dương Tình Hô (do Lương Tịnh Kỳ đóng), cô người mẫu Tiêu Ngọc (do Trương Huệ Nhã đóng), em trai Cảng là Trương Gia Xuyên (do Trương Cảnh Thuần đóng)… Hóa ra, Xung và Dương đã quen biết nhau trước đó; sự xuất hiện đột ngột của Dương làm cho Xung nhớ lại chuyện đau lòng. Dương đến đây để thuyết phục mẹ nhường lại khu nhà trọ cho một tập đoàn tài chính. San cố tình bị thương và yêu cầu Xung tiếp quản công việc dạy võ. San hứa với Dương nếu trong vòng 3 tháng, Dương giành được chiến thắng cuộc thi võ, thì bà sẽ thỏa mãn nguyện vọng cho con gái. Khi khóa học võ sắp đến hồi cuối, Chính Đông tự dưng trở nên bình thường và lật tẩy thân phận thật sự của Xung. Mối nguy cơ trùng trùng bao phủ núi Võ Đang…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2015, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tavia Yeung","avatar":""},{"name":"Chin Siu-Ho","avatar":""},{"name":"Yuen Qiu","avatar":""},{"name":"Jason Chan Chi-San","avatar":""},{"name":"Toby Leung Ching-Kei","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Derek Kwok Jing-Hung","avatar":""},{"name":"Yoyo Chen Chi-Yiu","avatar":""},{"name":"Akina Hong Wah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["潮拜武當"]', 1784690324449);
