INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thich-khach-nhiep-an-nuong', 'Thích Khách Nhiếp Ẩn Nương', 'The Assassin', 'https://phimimg.com/upload/vod/20250318-1/24e236232cb7a4c0f5df8970630776a0.jpg', 'https://phimimg.com/upload/vod/20250318-1/e25832a406e6537047cf50c83dcee593.jpg', '<p>Nhiếp Ẩn Nương được huấn luyện từ bé để trờ thành một sát thủ máu lạnh, giết người không chớp mắt. Nhưng rồi định mệnh đã bắt cô đối mặt với một tình huống - phải ám sát người chồng được hứa hôn từ lúc mới chào đời - Điền Quý An (Trương Chấn thủ vai). Với trách nhiệm của một sát thủ, Nhiếp ẩn nương phải phục tùng mệnh lệnh của sư phụ, nhưng liệu trí óc có thắng được con tim?</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Nikki Hsieh","avatar":""},{"name":"Sheu Fang-Yi","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Xu Fan","avatar":""},{"name":"Zuo Xiaoqing","avatar":""},{"name":"Satoshi Tsumabuki","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Shih Chun","avatar":""},{"name":"Zhou Yun","avatar":""},{"name":"Mei Fang","avatar":""},{"name":"Jacques Picoux","avatar":""},{"name":"Yong Mei","avatar":""},{"name":"Lei Zhenyu","avatar":""},{"name":"Shao-Huai Chang","avatar":""},{"name":"Leon Dai Li-Jen","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Hsin-Yu Ling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Nie Yin Niang","המחסלת","Cìkè Niè Yǐnniáng","The Assassin","The assassin","자객 섭은낭","The Assassin Lady Nie","刺客聶