INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bich-huyet-thu-huong-mong-2015', 'Bích Huyết Thư Hương Mộng', 'A Scholar Dream Of Woman', 'https://phimimg.com/upload/vod/20250311-1/40dc404726f8daea6fefacdcd4afe1b4.jpg', 'https://phimimg.com/upload/vod/20250311-1/35fe80c6e447958c1c5b8aae0533e814.jpg', '<p>Bộ phim&nbsp;là câu chuyện về giấc mộng học giả của một tài nữ đất Giang Nam thông minh, xinh đẹp, sắc sảo. Vì muốn điều tra sự mờ ám quanh cái chết của cha mình đồng thời mở mang kho kiến thức vô tận từ những cuốn sách, Thẩm Bích Vân không ngại hiến thân làm vợ lẽ trong một gia đình danh gia vọng tộc. Và... những bi kịch đầu từ đó...</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Mông","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Hà Ngạn Nghê","avatar":""},{"name":"Ngô Sảnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Scholar Dream of Woman","碧血书香梦"]', 1784690324449);
