INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-co', 'Đoạt Cờ', 'Capture the Flag', 'https://phimimg.com/upload/vod/20250301-1/650edb925754bd7b78d52e1997b6f885.jpg', 'https://phimimg.com/upload/vod/20250301-1/a874d8c83d13c8d336b5bc83eeccbeea.jpg', '<p>Phim kể về Mike Goldwing, một cậu bé gan dạ, 12 tuổi, là cháu của cựu phi hành gia NASA - Frank. Ông Frank giờ đây đã về hưu và sống một mình sau khi ông bỏ lỡ cơ hội cùng phi hành gia Neil Armstrong và Buzz Aldrin thực hiện nhiệm vụ khám phá mặt trăng trên con tàu Apollo XI. Một tên tỷ phú lập dị đã lập ra kế hoạch lấy cắp những khoáng sản quý trên mặt trăng và phá hủy các cột cờ mà đội tàu Apollo XI đã cắm trên mặt trăng. Mike cùng ông nội của mình và những người bạn thân của mình (Amy và Marty) cùng bay lên mặt trăng ngăn chặn âm mưu của tên tỷ phú đó.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Carme Calvell","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Javier Balas","avatar":""},{"name":"Dani Rovira","avatar":""},{"name":"Camilo García","avatar":""},{"name":"Toni Mora","avatar":""},{"name":"Fernando Cabrera","avatar":""},{"name":"Xavier Casan","avatar":""},{"name":"Oriol Tarragó","avatar":""},{"name":"Marta Barbará","avatar":""},{"name":"Ramon Canals","avatar":""},{"name":"Jordi Royo","avatar":""},{"name":"Margarita Cavero","avatar":""},{"name":"Alba Sola","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Una Familia Espacial","Atrapa la bandera","Capture the Flag","Jakten till månen","太空夺旗","夺旗"]', 1784690324449);
