INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-ma-ca-rong-phan-7', 'Nhật Ký Ma Cà Rồng (Phần 7)', 'The Vampire Diaries (Season 7)', 'https://phimimg.com/upload/vod/20250215-1/d316d8557b0f54b5b28afd1ebc1bd861.jpg', 'https://phimimg.com/upload/vod/20250215-1/6dfba8d72f970e8a7fa3deda6826c47f.jpg', '<p><span style="text-wrap-mode: wrap;">Câu chuyện về hai anh em ma cà rồng bị ám ảnh bởi cùng một cô gái, người có ngoại hình rất giống với ma cà rồng xinh đẹp nhưng tàn nhẫn mà họ từng biết và yêu vào năm 1864.</span></p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Wesley","avatar":""},{"name":"Ian Somerhalder","avatar":""},{"name":"Kat Graham","avatar":""},{"name":"Candice King","avatar":""},{"name":"Zach Roerig","avatar":""},{"name":"Michael Malarkey","avatar":""},{"name":"Matthew Davis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Diários de um Vampiro","Le journal d''un vampire","Crónicas Vampíricas","Το Ημερολόγιο ενός Βρικόλακα","Diario de Vampiros","Вампирски дневници","Vampir Günlükleri","噬血Y世代","Vampire Diaries","The Vampire Diaries"]', 1784690324449);
