INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-ma-ca-rong-phan-7', 'Nhật Ký Ma Cà Rồng (Phần 7)', 'The Vampire Diaries (Season 7)', 'nhật ký ma cà rồng (phần 7) the vampire diaries (season 7) paul wesley ian somerhalder kat graham candice king zach roerig michael malarkey matthew davis diários de um vampiro le journal d''un vampire crónicas vampíricas το ημερολόγιο ενός βρικόλακα diario de vampiros вампирски дневници vampir günlükleri 噬血y世代 vampire diaries the vampire diaries', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bo-tron', 'Cô Dâu Bỏ Trốn', 'All You Need Is Love', 'https://phimimg.com/upload/vod/20231120-1/1846d2bb2c3d17b845385c28e513d26b.jpg', 'https://phimimg.com/upload/vod/20231120-1/09a5959a9d65235fbf3c9fb4270b9d95.jpg', '<p>Tiểu thư giàu có Diệp Phân Phân một lòng muốn rời xa gia đình để chạy trốn cuộc hôn nhân bị sắp đặt. Để tránh áp lực, cô quyết định nghỉ dưỡng tại một biệt thự xinh đẹp trên hòn đảo gắn liền với một bài hát cổ điển mà mẹ cô để lại. Tuy nhiên, khi đến nơi, cô phát hiện ra biệt thự thực chất chỉ là nhà nghỉ xuống cấp do một chàng trai địa phương nghèo sở hữu. Những người bạn của anh đã thổi phồng thông tin trên mạng để thu hút khách. Từ một nơi có căn phòng ngủ không cần khoá cửa, một nhà vệ sinh không cần mái, chiếc xe tải tồi tàn, câu chuyện tình yêu đầy bi hài bắt đầu!</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Thư Kỳ","avatar":""},{"name":"Địch Long","avatar":""},{"name":"Lý Quốc Nghị","avatar":""},{"name":"Tăng Bảo Nghi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
