INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-nguc-toi-phan-1', 'Hầm Ngục Tối (Phần 1)', 'Danmachi (Season 1)', 'https://phimimg.com/upload/vod/20250214-1/cee77efb4fa4c420ad71694dfb7af86c.jpg', 'https://phimimg.com/upload/vod/20250214-1/c48206e8329cf43ed45b936af264b898.jpg', '<p>Tại thành phố Orario phồn hoa mà trung tâm là mê cung dưới lòng đất &quot;Dungeon&quot;, một cậu bé tên Bell Cranell, đã chạy ra với mong ước &quot;gặp được định mệnh với người con gái đời mình&quot;. Một ngày nọ Bell bị một con quái vật tấn công và được cứu bởi Aiz Wallenstein - cô gái thám hiểm đứng đầu lớp. Trong thời khắc đó, Bell đã yêu Aiz ngay từ cái nhìn đầu tiên, và cậu ta bắt đầu hành động để một ngày nào đó có thể trở thành một nhà thám hiểm phù hợp với Aiz.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Haruka Chisuga","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Shizuka Ishigami","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Yuka Iguchi","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Wakana Kowaka","avatar":""},{"name":"Yuuki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be11