INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-co-dieu-toan-luu-ba-on', 'Thần Cơ Diệu Toán Lưu Bá Ôn', 'Foresighted Liu Bo Wen', 'https://phimimg.com/upload/vod/20250202-1/441e4ed3ab559e5c562a6416f59e967e.jpg', 'https://phimimg.com/upload/vod/20250202-1/44e5092d643e78939229d93a6dd5d30f.jpg', '<p>Triều nhà Minh, Lưu Bá Ôn được xem là khai quốc công thần, là cánh tay đắc lực của Hoàng đế Chu Nguyên Chương. Nhưng cũng chính vì sự hơn người ấy, ông đã gặp không ít khó khăn do sự tị hiềm của kẻ xấu. Không chỉ đem đến tiếng cười với những tình tiết hài hước, phim còn giúp người xem hiểu thêm về một nhân vật có thật trong lịch sử Trung Hoa.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Băng","avatar":""},{"name":"Vu Chấn","avatar":""},{"name":"Vương Cương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Foresighted Liu Bo Wen","神机妙算刘伯温"]', 1784690324449);
