INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-nha-bang', 'Lang Nha Bảng', 'Nirvana in Fire', 'https://phimimg.com/upload/vod/20250128-1/3c185a77d26575fceac8626d8c2d9a56.jpg', 'https://phimimg.com/upload/vod/20250128-1/beccd5cb723124ca7d7e2e03b61c50ff.jpg', '<p>Vì kẻ gian hãm hại mà cha và cả đội quân Xích Diễm bị kết tội mưu phản và bỏ mạng tại Mai Lĩnh, Lâm Thù sống sót nhưng trúng độc, thay đổi hoàn toàn diện mạo, sau đó trở thành Mai Trường Tô - Tông chủ của Giang Tả Minh. Nơi đây, chàng xây dựng kế hoạch báo thù, quyết tâm rửa sạch oan khuất cho cha và bảy vạn binh sĩ năm xưa.</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 9, 2015, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Xiaoming","avatar":""},{"name":"Liu Haoran","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Zhang Huiwen","avatar":""},{"name":"Sun Chun","avatar":""},{"name":"Wu Haochen","avatar":""},{"name":"Mei Ting","avatar":""},{"name":"Zhang Bo","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Liu Jun","avatar":""},{"name":"Qiao Xin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["瑯琊榜","Nirvana in Fire","琅琊榜","琅琊榜 麒麟の才子、風雲起こす","琅琊榜（ろうやぼう）～麒麟の才子、風雲起こす～","มหาบุรุษพลิกแผ่นดิน","หลางหยาป่าง","List of Langya"]', 1784690324449);
