INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-nha-bang', 'Lang Nha Bảng', 'Nirvana in Fire', 'lang nha bảng nirvana in fire huang xiaoming liu haoran tong liya zhang huiwen sun chun wu haochen mei ting zhang bo guo jingfei liu jun qiao xin 瑯琊榜 nirvana in fire 琅琊榜 琅琊榜 麒麟の才子、風雲起こす 琅琊榜（ろうやぼう）～麒麟の才子、風雲起こす～ มหาบุรุษพลิกแผ่นดิน หลางหยาป่าง list of langya', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('49-ngay', '49 Ngày', '49 Days', 'https://phimimg.com/upload/vod/20250116-1/0154a620b3fc90c63fed19df6cc44ec1.jpg', 'https://phimimg.com/upload/vod/20250116-1/1def73657d695408cd0f04ea0bf50c42.jpg', '<p>Nội dung chính của phim xoay quanh anh chàng Đông (Trường Giang) có số phận “đen như nhọ nồi” ngay từ lúc cha sinh mẹ đẻ đến giờ. Mồ côi từ nhỏ, lớn lên thì bị cô bạn gái phũ phàng bỏ rơi, tài sản bị trộm khoắng sạch đến không còn xu dính túi… tất cả khiến Đông chán chường tới nỗi quyết định tự tử. Ấy thế nhưng nguyện vọng cũng không thành, anh chàng chẳng những sống dở chết dở mà lại còn bị ba con ma Lisa (Hoàng Phi), Thành (La Thành), Như (Khả Như) bám theo &quot;mượn xác&quot; để tiêu khiển. Câu chuyện bắt đầu dở khóc dở cười từ đó, và cuộc đời của Đông rẽ sang một hướng khác… Việc bị ba con ma “bám theo” có phải là vận đen nhất của Đông chưa hay đó chỉ là những màn dạo đầu nhẹ nhàng của số phận? Liệu cuộc đời rồi có mỉm cười với Đông hay lại tiếp tục “ám” Đông bằng nhiều trò đùa ác nghiệt khác nữa…ba con ma chính là những chìa khoá để mở ra mọi bí mật trong câu chuyện trớ trêu này.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Nhã Phương","avatar":""},{"name":"Trường Giang","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Hari Won","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["49 Ngày"]', 1784690324449);
