INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhan-2015', 'Thiên Nhãn', 'Eye In The Sky', 'https://phimimg.com/upload/vod/20250111-1/07e3bfc9c1d3c973d74945ec6fce790f.jpg', 'https://phimimg.com/upload/vod/20250111-1/b914c82a74bb6211a0f2ad7d33a806e1.jpg', '<p>Cựu thám tử CID Sze Tou Shun đã buộc phải rời khỏi lực lượng cảnh sát do nghi ngờ rằng anh ta có liên quan đến một vụ án đập phá . Anh gia nhập một công ty bảo mật, nơi anh gặp Cheng Lik Hang. Là một cựu thám tử, Sze Tou Shun có một nhân vật ẩn dật, nhưng có một đôi mắt sắc bén có thể bắt được những chi tiết nhỏ từ các cảnh quay giám sát thường là chìa khóa để giải quyết các vụ án. Suy nghĩ của Cheng Lik Hang và phong cách làm việc tương tự như của Sze Tou Shun và cũng rất xuất sắc trong công việc của mình. Hai người trở thành bạn tốt và được cấp trên ưu ái. Điều này là cho đến khi điều tra viên tư nhân Ng Zan Nei xuất hiện. Xung đột nảy sinh khi cô nhầm Sze Tou Shun với một người bạn cũ. Nó khiến anh nhớ lại một sự việc đã bị lãng quên từ lâu, hóa ra có liên quan đến vụ án đốt phá.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 2015, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Ruco Chan","avatar":""},{"name":"Samantha Ko","avatar":""},{"name":"Tony Hung","avatar":""},{"name":"Rosina Lin","avatar":""},{"name":"Suet Nei","avatar":""},{"name":"Law Lok-Lam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["天眼"]', 1784690324449);
