INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-rui-cuoc-doi-va-cai-chet-cua-robert-durst-phan-1', 'Vận Rủi Cuộc Đời Và Cái Chết Của Robert Durst (Phần 1)', 'The Jinx: The Life and Deaths of Robert Durst (Season 1)', 'https://phimimg.com/upload/vod/20250111-1/dc0e8a9d27dac8aa30a34636c9a00423.jpg', 'https://phimimg.com/upload/vod/20250111-1/adcfd89b2f64623fe5326d154f2f52d1.jpg', '<p>Bộ phim do HBO sản xuất xoay quanh một vụ án có nhiều khúc mắc và nghi phạm lớn nhất trong vụ việc: Robert Durst.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Durst","avatar":""},{"name":"Andrew Jarecki","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["厄运","黑色豪门疑案","Der Ungluecksbringer - Das Leben und die Tode des Robert Durst","The Jinx","The Jinx - Part Two","The Jinx – Part Two","The Jinx- Part One","Jinx"]', 1784690324449);
