INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-rui-cuoc-doi-va-cai-chet-cua-robert-durst-phan-1', 'Vận Rủi Cuộc Đời Và Cái Chết Của Robert Durst (Phần 1)', 'The Jinx: The Life and Deaths of Robert Durst (Season 1)', 'vận rủi cuộc đời và cái chết của robert durst (phần 1) the jinx: the life and deaths of robert durst (season 1) robert durst andrew jarecki 厄运 黑色豪门疑案 der ungluecksbringer - das leben und die tode des robert durst the jinx the jinx - part two the jinx – part two the jinx- part one jinx', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hoi-dap-1988', 'Lời Hồi Đáp 1988', 'Reply 1988', 'https://phimimg.com/upload/vod/20240316-1/31c29d11416a2e4aea4e670b9b1f8eac.jpg', 'https://phimimg.com/upload/vod/20240316-1/adb8c4c3e492a81d9d8b308ecd58f652.jpg', '<p>Reply 1988 (Hangul: &nbsp;응답 하라 1988; RR: &nbsp;Eungdabhara 1988) (tạm dịch: Lời hồi đáp 1988) là một bộ phim truyền hình Hàn Quốc được sản xuất năm 2015. Với sự tham gia của Lee Hye Ri, Park Bo Gum, Ryu Jun Yeol, Go Kyung Pyo, và Lee Dong Hwi. Đây là một bộ phim tình cảm gia đình hết sức ấm lòng lấy bối cảnh năm 1988, nói về năm gia đình sống trong cùng một khu phố ở Ssangmun-dong, quận Dobong, Bắc Seoul, Hàn Quốc. Theo đạo diễn Shin Won-ho, chủ đề &quot;Người chồng bí mật&quot; vẫn luôn được thêm vào, giống như 2 phần tiền nhiệm trước của nó là Hồi đáp 1997 và Hồi đáp 1994. Ba gia đình sống dưới một mái nhà, chạy xuyên suốt từ năm 1986 đến năm 1994 trên đài tvN, lấy cảm hứng từ những bộ phim truyền hình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Hye-ri","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Ryu Hye-young","avatar":""},{"name":"Choi Seong-won","avatar":""},{"name":"Ahn Jae-hong","avatar":""},{"name":"Kim Seol","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Lee Se-young","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324449);
