INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-loan-phan-1', 'Hỗn loạn (Phần 1)', 'Fauda (Season 1)', 'https://phimimg.com/upload/vod/20241206-1/8e85cfea89653f0a1d9fa4d871f5c98f.jpg', 'https://phimimg.com/upload/vod/20241206-1/a9c681acfca920554510f6ce3dd4720e.jpg', '<p>Một đặc vụ hàng đầu đã nghỉ hưu của Israel trở lại làm việc để săn lùng một chiến binh Palestine mà anh tưởng mình đã giết được, từ đó gây ra một loạt các sự kiện.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lior Raz","avatar":""},{"name":"Hisham Suliman","avatar":""},{"name":"Shadi Mar''i","avatar":""},{"name":"Laëtitia Eïdo","avatar":""},{"name":"Itzik Cohen","avatar":""},{"name":"Rona-Lee Shim''on","avatar":""},{"name":"Boaz Konforty","avatar":""},{"name":"Doron Ben-David","avatar":""},{"name":"Neta Garty","avatar":""},{"name":"Tsahi Halevi","avatar":""},{"name":"Jonathan Avigdori","avatar":""},{"name":"Shani Atias","avatar":""},{"name":"Aylam Orian","avatar":""},{"name":"Yaakov Zada Daniel","avatar":""},{"name":"Idan Amedi","avatar":""},{"name":"Jameel Khoury","avatar":""},{"name":"Assaf Cohe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fauda","混乱 冤冤相报","Χάος","ファウダ -復讐の連鎖-","파우다: 혼돈","Фауда","פאודה"]', 1784690324449);
