INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bong-chuyen-haikyuu-phan-2', 'Vua Bóng Chuyền Haikyuu (Phần 2)', 'Haikyu!! (Season 2)', 'https://phimimg.com/upload/vod/20241125-1/7df91aef427b62143caf23c93eb291a7.jpg', 'https://phimimg.com/upload/vod/20241125-1/f608be8432714f44cb5b8232f0d0896b.jpg', '<p>Vua Bóng Chuyền Haikyu (Phần 2) - Haikyu!! (Season 2) là tiếp nối Phần 1 câu chuyện về đội bóng chuyền Karasuno - quạ đen. Nhân vật chính là Hinata, cao hơn mép dưới lưới một tí nhưng lại thích làm tay đập chủ lực. Được cái cậu ta có một đôi chân rất tuyệt vời: khả năng bứt tốc và dậm nhảy cực tốt, hâm mộ Người khổng lồ tí hon - tay đập nổi tiếng với chiều cao khiếm tốn, Hinata đã vào cao trung Karasuno, nơi mà anh ấy thể hiện chính mình với môn bóng chuyền.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Haikyuu!!","High Kyuu!!","ハイキュー!! セカンドシーズン","Haikyuu!! Karasuno Koukou VS Shiratorizawa Gakuen Koukou","ハイキュー!! 烏野高校 VS 白鳥沢学園高校","ハイキュー!! バケモノたちの行くところ","Haikyuu!! Riku vs. Kuu","하이큐!! 땅 VS 하늘","Волейбол!!","Haikyuu!! II","Haikyuu!! TO THE TOP","HAIKYU!! LAND VS. AIR","Haikyu!! Karasuno High School vs Shiratorizawa Academy","Vua Bóng Chuyền","ハイキュー!!"]', 1784690324449);
