INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-the-gioi-game-phan-1', 'Lạc Vào Thế Giới Game (Phần 1)', 'Overlord (Season 1)', 'https://phimimg.com/upload/vod/20241116-1/9a7e5a55fa665a90c3f40c424048be7c.jpg', 'https://phimimg.com/upload/vod/20241116-1/787278fc13db59c093a298a5ac7d638f.jpg', '<p>Bộ phim lấy bối cảnh năm 2138 khi con người không còn phân biệt được đâu là thực đâu là ảo được nữa. Yggdrasil, một trò chơi trực tuyến nổi tiếng đã âm thầm bị đóng cửa trong quá khứ. Tuy nhiên một top-player tên Momonga đã quyết định sống chết cùng với trò chơi này và sau đó hắn đã trở thành một tên Cốt Bạch Hắc Ma có sức mạnh lớn nhất trong trò chơi này. Thế giới dần đổi thay, cho đến khi các NPC dần dần có cảm xúc của một con người. Không gia đình, không bạn bè, không việc làm hay chỗ đứng trong xã hội, hắn quyết định chiếm lấy thế giới này cho riêng mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Yumi Hara","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Akeno Watanabe","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Masayuki Katou","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Hiromi Igarashi","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kei Shindo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong"