INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-nhau-tron-doi', 'Bên Nhau Trọn Đời', 'My Sunshine', 'https://phimimg.com/upload/vod/20241104-1/37c5540900f8c28dda103539ac52a2e7.jpg', 'https://phimimg.com/upload/vod/20241104-1/99ea04594f93b4642366f2ae9c62aa54.jpg', '<p>Chuyển thể từ tiểu thuyết ngôn tình đình đám của Cố Mạn, bộ phim đưa ta vào câu chuyện tình yêu thời thanh xuân lãng mạn của Hà Dĩ Thâm và Triệu Mặc Sênh. Vì bí mật đau buồn trong quá khứ, Mặc Sênh bỏ đi Mỹ không lời từ biệt. Bảy năm sau, cô trở về với hy vọng hóa giải khúc mắc trong lòng, định mệnh một lần nữa cho họ gặp nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Khải","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Đường Yên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["何以笙簫默","Ты мой свет","Ты - мое солнце","Silent Separation","You Are My Sunshine","何以笙箫默"]', 1784690324449);
