INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyen-thu-vo-hinh-phan-3', 'Tuyển Thủ Vô Hình (Phần 3)', 'Kuroko''s Basketball (Season 3)', 'tuyển thủ vô hình (phần 3) kuroko''s basketball (season 3) 小野賢章 小野友樹 諏訪部順一 小野大輔 木村良平 神谷浩史 鈴村健一 斎藤千和 細谷佳正 野島裕史 江口拓也 浜田賢二 保志総一朗 水谷直樹 谷山紀章 井上剛 折笠富美子 鈴木達央 福山潤 三木眞一郎 kuroko no basket kurokos basketball 幻影籃球王 kuroko no basuke 黑子的籃球 黒子のバスケ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-dau-tien', 'Khoảnh Khắc Đầu Tiên', 'My First Time', 'https://phimimg.com/upload/vod/20241021-1/dc4bfe4eeae5cd41513fdd0fb2d244e5.jpg', 'https://phimimg.com/upload/vod/20241021-1/35bd882fd07c07853b0165186f7f2b33.jpg', '<p>Yoon Tae Oh (Choi Min Ho) một sinh viên năm nhất, 20 tuổi. Chàng trai có một tính cách phóng túng. Bạn của Tae Oh, Han Song Yi (Park So Dam), người bạn quen từ khi còn nhỏ, cô gái tràn đầy nhiệt huyết. Nhưng bây giờ, bỗng dưng Tae Oh nảy sinh tình cảm với Song Yi. Trong khi đó, một người bạn của Tae Oh, Seo Ji Ahn (Kim Min Jae), chàng trai có tình cách tốt có tình cảm với Song Yi. Và giờ đây, một tam giác tình yêu giữa ba người họ xuất hiện.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조혜정","avatar":""},{"name":"박소담","avatar":""},{"name":"민호","avatar":""},{"name":"김민재","avatar":""},{"name":"이이경","avatar":""},{"name":"정유진","avatar":""},{"name":"안우연","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Cheo-eumiraseo","Because It''s The First Time","처음이라서"]', 1784690324449);
