INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-doi-gangnam', 'Bụi Đời Gangnam', 'Gangnam Blues', 'https://phimimg.com/upload/vod/20231108-1/1efdccdb147c3990628375e8a89d9d74.jpg', 'https://phimimg.com/upload/vod/20231108-1/1d0867e271470c28dd576f615ba89bb6.jpg', '<p>Bụi Đời Gangnam - Gangnam 1970 - Gangnam Blues: Lấy bối cảnh thành phố Seoul những năm 1970, bộ phim khắc họa sự đổi thay của con phố Gangnam, khi các doanh nghiệp bất động sản trải qua những biến cố lớn cùng những âm mưu của chính phủ và xã hội đen. Lee Min Ho sẽ đảm nhận vai chính mang số phận nghiệt ngã và sẽ có nhiều cảnh hành động.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Min-ho","avatar":""},{"name":"Kim Rae-won","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Kim Ji-soo","avatar":""},{"name":"Kim Seol-hyun","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Han Jae-yeong","avatar":""},{"name":"Lee Yeon-doo","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Uhm Hyo-seop","avatar":""},{"name":"Kim Yoo-yeon","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Kim Nina","avatar":""},{"name":"Kim Ji-eun","avatar":""},{"name":"Yoon Hwan","avatar":""},{"name":"Joo Yeon-seo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
