INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bui-doi-gangnam', 'Bụi Đời Gangnam', 'Gangnam Blues', 'bụi đời gangnam gangnam blues lee min-ho kim rae-won jung jin-young kim ji-soo kim seol-hyun yoo seung-mok han jae-yeong lee yeon-doo jung ho-bin uhm hyo-seop kim yoo-yeon jeon bae-soo jang so-yeon kim won-jin kim nina kim ji-eun yoon hwan joo yeon-seo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-nu-dang-yeu', 'Ma Nữ Đáng Yêu', 'Oh My Ghost', 'https://phimimg.com/upload/vod/20241017-1/22a28d10da8f5456e3a4c9785bc2edab.jpg', 'https://phimimg.com/upload/vod/20241017-1/57278b0e0cc8f4f0a12a0a67658b132d.jpg', '<p>Park Bo – Young trong vai Na Bo Sun, làm bếp phó trong một khách sạn. Na Bo Sun là một cô gái nhút nhát và có phần tự ti nên không hề có một người bạn nào bên cạnh. Vì có bà ngoại là một pháp sư, nên ngay từ khi còn nhỏ, Na Bo Sun đã có thể nhìn và nói chuyện với những linh hồn. Câu chuyện trở nên kịch tính khi thân xác Na Bo Sun và linh hồn của một con ma có tên Shin Soon – Ae hợp thành một.

Cho Jung – Seok trong vai Kang Sun – Woo, cùng làm việc với Na Bo Sun trong vai trò bếp trưởng. Một anh chàng có vẻ ngoài bảnh bảo, cộng thêm phong thái tự tin của một bếp trưởng đã khiến cho vô số cô nàng chết mê, chết mệt và Na Bo Sun cũng nằm trong số đó. Tuy nhiên, tới giờ phút này thì anh chàng đầu bếp của chúng ta vẫn chưa thể nào quên đi được hình bóng của cô bạn gái cũ. Kang Sun – Woo bắt đầu chú ý tới Na Bo Sun nhiều hơn kể từ lần hoán nhập định mệnh đó của Na Bo Sun.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박보영","avatar":""},{"name":"조정석","avatar":""},{"name":"임주환","avatar":""},{"name":"김슬기","avatar":""},{"name":"박정아","avatar":""},{"name":"강기영","avatar":""},{"name":"Choi Min-cheol","avatar":""},{"name":"곽시양","avatar":""},{"name":"오의식","avatar":""},{"name":"이대연","avatar":""},{"name":"신혜선","avatar":""},{"name":"신은경","avatar":""},{"name":"이정은","avatar":""},{"name":"이학주","avatar":""},{"name":"태항호","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["我的鬼神大人","Oh My Ghostess","רוח הרפאים שלי","O Naui Gwisinnim","Oh Naui Gwishinnim","O Naui Gwishinnim","O Naeui Gwishinnim","我的鬼神君","Oh 我的鬼神大人","Oh！我的鬼神君","О, моя примаро","Oh My Ghost","오 나의 귀신님"]', 1784690324449);
