INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('april-va-the-gioi-la-thuong', 'April Và Thế Giới Lạ Thường', 'April And The Extraordinary World', 'https://phimimg.com/upload/vod/20241004-1/d44aa85a2a9945cab7504d070452e046.jpg', 'https://phimimg.com/upload/vod/20241004-1/42a1bc57b4e76bb53c13801fd9adc6a3.jpg', '<p>April and the Extraordinary World là một câu chuyện hấp dẫn kỳ lạ về Paris với phong cách steampunk. Cuộc tìm kiếm cha mẹ - những nhà khoa học bị mất tích bởi một thế lực siêu nhiên - của cô bé April làm người xem vô cùng thích thú. Bộ phim từng được đề cử cho hạng mục phim hoạt hình hay nhất tại giải César 2016 (được xem như Oscar của nước Pháp).</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Philippe Katerine","avatar":""},{"name":"Jean Rochefort","avatar":""},{"name":"Olivier Gourmet","avatar":""},{"name":"Marc-André Grondin","avatar":""},{"name":"Bouli Lanners","avatar":""},{"name":"Anne Coesens","avatar":""},{"name":"Macha Grenon","avatar":""},{"name":"Benoît Brière","avatar":""},{"name":"Gérard Dessalles","avatar":""},{"name":"Jean-Claude Donda","avatar":""},{"name":"Damien Laquet","avatar":""},{"name":"Irina Preda","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["April and the Twisted World","A Rigged World","April and the extraordinary world","阿薇尔与虚构世界","Avril et le Monde Truque","April and the Extraordinary World","April  och den otroliga världen","아브릴과 조작된 세계","Avril y el mundo extraordinario","アヴリルと奇妙な世界","أبريل والعالم الاستثنائي","蒸汽女孩与不死猫","爱波的异想世界","Avril et le monde truqué"]', 1784690324449);
