INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('april-va-the-gioi-la-thuong', 'April Và Thế Giới Lạ Thường', 'April And The Extraordinary World', 'april và thế giới lạ thường april and the extraordinary world marion cotillard philippe katerine jean rochefort olivier gourmet marc-andré grondin bouli lanners anne coesens macha grenon benoît brière gérard dessalles jean-claude donda damien laquet irina preda april and the twisted world a rigged world april and the extraordinary world 阿薇尔与虚构世界 avril et le monde truque april and the extraordinary world april  och den otroliga världen 아브릴과 조작된 세계 avril y el mundo extraordinario アヴリルと奇妙な世界 أبريل والعالم الاستثنائي 蒸汽女孩与不死猫 爱波的异想世界 avril et le monde truqué', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-7', 'Gia Đình Hiện Đại (Phần 7)', 'Modern Family (Season 7)', 'https://phimimg.com/upload/vod/20241001-1/d6101d63843628f2de7123b0f031d734.jpg', 'https://phimimg.com/upload/vod/20241001-1/252bc05e2eaf7b5d3a09f3a9db54dc35.jpg', '<p>Thưởng thức một chương mới của tình yêu và tiếng cười với Phần thứ bảy của chương trình. Quackery lên ngôi khi Phil nhận nuôi bộ ba vịt con mồ côi và những đứa trẻ Dunphy nổi loạn dang rộng đôi cánh. Trong khi đó, Cam và Mitchell đối mặt với rào cản tài chính và những cậu bạn hoang dã, Jay và Gloria vượt qua chương trình giáo dục mầm non của Joe2 còn Manny nhảy vào trò chơi hẹn hò. Nhưng câu hỏi lớn cuối cùng sẽ được trả lời: Haley và Andy có phải là định mệnh của nhau không.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324449);
