INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-tung-phan-5', 'Tố Tụng (Phần 5)', 'Suits (Season 5)', 'https://phimimg.com/upload/vod/20240927-1/5180efd70ae7c8afd48ea7a598b39390.jpg', 'https://phimimg.com/upload/vod/20240927-1/f030a4fa00ba633c4242818878f3a722.jpg', '<p>Suits là 1 series truyền hình ăn khách của USA Network. Suits nói về hai anh chàng Mike Ross và Harvey Specter. Hai con người ở 2 địa vị khác nhau, nhưng thông minh và nhạy bén không hề thua kém nhau.Harvey Specter: một luật sự giỏi nhất tại New York. Khi được thăng cấp, anh cần phải tìm 1 cộng sự để làm việc. Anh ghét mấy tên sinh viên Harvard, học giỏi mà đầu óc chẳng có gì. Anh cần 1 cộng sự thông minh và nhạy bén. Và một ngày, anh gặp Mike Ross.Mike Ross: một anh chàng luôn ấp ủ ước mơ trở thành 1 luật sư tài giỏi. Hoàn cảnh éo le khiến anh bị đuổi học ra khỏi trường đai học Luật do cái tội giải đề thi môn Toán và bán cho con của hiệu trưởng. Một ngày nọ, vì cần tiền chữa bệnh cho nội nên anh vận chuyển cần sa. Trong khi đang chạy trốn cảnh sát, anh gặp Harvey Specter đang phỏng vấn tuyển cộng sự. Nhờ bộ óc thông minh, và trí nhớ siêu phàm, cuộc đời anh bước sang một trang mới.Hai con người có địa vị khác nhau, cùng nhau phối hợp giải quyết các vụ án, đòi lại công bằng cho thân chủ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Gina Torres","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suits: Homens de Terno","金装律师","诉讼双雄","无证律师","W garniturach","وکلا","La ley de los audaces","Briliáns elmék","Suits"]', 1784690324449);
