INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-dau-bep-soma', 'Vua đầu Bếp Soma', 'Shokugeki No Soma', 'https://phimimg.com/upload/vod/20240925-1/29ddd988baa6ab652113ad6cf3f5c12e.jpg', 'https://phimimg.com/upload/vod/20240925-1/517449c7f97c8cfd24b7ef028fbb7ca7.jpg', '<p>Soma Yukihira, con trai của một quán ăn bình dân ở khu phố buôn bán, cậu vừa giúp đỡ cha mình là Joichiro, vừa cố gắng để trở thành một đầu bếp chuyên nghiệp. Đáp ứng yêu cầu của cha, sau khi tốt nghiệp trung học cơ sở, Soma tiếp tục đến Học viện Ẩm thực Totsuki, nơi anh đã mài dũa những kỹ năng nấu nướng của mình để trở thành đầu bếp giỏi nhất.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"松岡禎丞","avatar":""},{"name":"茅野愛衣","avatar":""},{"name":"内田真礼","avatar":""},{"name":"赤﨑千夏","avatar":""},{"name":"種田梨沙","avatar":""},{"name":"髙橋ミナミ","avatar":""},{"name":"河西健吾","avatar":""},{"name":"瀬戸麻沙美","avatar":""},{"name":"大西沙織","avatar":""},{"name":"柳田淳一","avatar":""},{"name":"諏訪部順一","avatar":""},{"name":"村田太志","avatar":""},{"name":"小野友樹","avatar":""},{"name":"櫻井孝宏","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Food Wars","Shokugeki no Souma","שוקוגקי נו סומה","Shokugeki no Soma","Shokugeki No Souma","Shokugeki no Sōma","Shokugeki No Souma 2","Shokugeki no Souma: Ni no Sara","Shokugeki No Souma 3","Shokugeki No Souma 5","Shokugeki no Soma 2","Shokugeki no Soma 3","Shokugeki No Souma 4","Shokugeki no Souma: San no Sara - Tootsuki Ressha Hen","Shokugeki no Soma 5","Shokugeki no Souma: San no Sara","Shokugeki no Soma 4","Shokugeki no Souma: Gou no Sara","Shokugeki no Souma: Shin no Sara","Voedselgevecht!","В поисках божественного рецепта","Кулинарные поединки","Повар-боец Сома","حروب الطعام","حرب الطعام","Шьокуґекі но Со̄ма","Food Wars!: Shokugeki no Soma","Soma''s Cafeteria Drama","Food Wars! 4","Food Wars! 5","Food Wars! 3","Food Wars! 2","食戟のソーマ"]', 1784690324449);
