INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-hai-muoi-2015', 'Tuổi Hai Mươi', 'Twenty', 'https://phimimg.com/upload/vod/20240207-1/8e0849065b19fd9426541d029fe3a0e1.jpg', 'https://phimimg.com/upload/vod/20240207-1/dd643efca23533effe8301394a0b9ab4.jpg', '<p>Twenty – Tuổi Hai Mươi là một bộ phim hài, lãng mạn. Kể về cuộc sống, tình yêu và tình bạn của ba chàng trai: Chi Ho “nổi tiếng” (Kim Woo Bin), Dong Woo “nghèo khó” (Junho nhóm 2PM) và Kyung Jae “tài năng” (Kang Ha Neul). một bộ phim mà giới trẻ khó lòng bỏ qua. Bởi sự hội tụ của ba chàng trai biết diễn này hết sức đáng giá. Phim với nội dung cô đọng một tuổi trẻ mà ai cũng có: những người bạn thân cùng làm những điều hư hỏng một tí, có những tên bạn thân sẽ trêu mình khi mình gặp rắc rối, những lần nhát cáy trước dân anh chị và những lúc vòi vĩnh bố mẹ...</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Woo Bin","avatar":""},{"name":"Kang Ha Neul","avatar":""},{"name":"Jung So Min","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
