INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-song-gio', 'Chuyến Bay Sóng Gió', 'Romance Out Of The Blue', 'https://phimimg.com/upload/vod/20240918-1/7ffb6f2533e4f80265b00ba7533c6bf0.jpg', 'https://phimimg.com/upload/vod/20240918-1/2e4c8d10080a3dbfc1514d8ac79fcb7e.jpg', '<p>Trước ngày bay của cô tiếp viên hàng không mới vào nghề Sa Sa, vì quá hưng phấn nên đã mơ một giấc mơ vô cùng thú vị. Trong mơ vì quá hồi hộp trên chuyến bay đầu tiên cô đã gây là nhiều sự cố nghề nghiệp, đắc tội với hành khách hạng thương gia Lâm Tử Đại. Sau khi quen biết giữa họ đã nảy sinh những tình huống dở khóc dở cười và trở thành bạn tốt của nhau. Lâm Tử Đại ân cần chu đáo lại rất giàu có, Tử Đại và Sa Sa đã rơi vào lưới tình và Sa Sa cũng trải qua nhiều câu chuyện bi hài trên con đường trở thành một tiếp viên hàng không.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Vũ","avatar":""},{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Khưu Trạch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["浪漫天降"]', 1784690324449);
