INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-bay-song-gio', 'Chuyến Bay Sóng Gió', 'Romance Out Of The Blue', 'chuyến bay sóng gió romance out of the blue hạ vũ quan hiểu đồng khưu trạch 浪漫天降', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-gai-be-nho', 'Em Gái Bé Nhỏ', 'Our Little Sister', 'https://phimimg.com/upload/vod/20240917-1/87075cdf4c96f43caf79abf0ea346179.jpg', 'https://phimimg.com/upload/vod/20240917-1/9a8e9db0d98d7c3d5aec4457955493b1.jpg', '<p>Một ngày, ba chị em nhà Koda nhận được tin người bố đã bỏ đi 15 năm vừa qua đời. Trong khi chị cả Sachi vẫn còn oán giận và lấy lý do công việc để không tới thì cô hai Yoshino (Yocchan) và cô ba Chika đã cùng nhau dự đám tang. Tại đây, họ gặp Suzu – cô em gái cùng cha khác mẹ (là con vợ hai) và bà Yoko - vợ ba của bố. Sachi bất ngờ xuất hiện và nhận ra hoàn cảnh khó xử của Suzu khi hiện tại, cô bé đã không còn ai chăm sóc. Cô đề nghị Suzu về ở cùng với ba người tại Kamakura trong căn nhà gỗ cũ do ông bà để lại, căn nhà mà họ gọi là &quot;kí túc xá nữ&quot; và phong chị cả làm &quot;người quản lý. Từ đây cả ba hết lòng yêu quý và mong muốn bảo vệ đứa em gái nhỏ khỏi những tổn thương tinh thần. Có thêm một đứa em gái nhỏ, cả ba cảm thấy mình trách nhiệm thêm một bậc, mỗi người dần có thêm mục tiêu và hướng đi mới. Tuy nhiên, so với em út Suzu, 3 người chị mới đúng là những người đã trưởng thành hơn nhờ cuộc đoàn viên này.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"綾瀬はるか","avatar":""},{"name":"長澤まさみ","avatar":""},{"name":"夏帆","avatar":""},{"name":"広瀬すず","avatar":""},{"name":"加瀬亮","avatar":""},{"name":"鈴木亮平","avatar":""},{"name":"Ikeda Takafumi","avatar":""},{"name":"坂口健太郎","avatar":""},{"name":"前田旺志郎","avatar":""},{"name":"キムラ緑子","avatar":""},{"name":"中村優子","avatar":""},{"name":"Kazuaki Shimizu","avatar":""},{"name":"Kaoru Hirata","avatar":""},{"name":"野村麻純","avatar":""},{"name":"Seki Yuki","avatar":""},{"name":"Mikami Saya","avatar":""},{"name":"原扶貴子","avatar":""},{"name":"Takamitsu Nonaka","avatar":""},{"name":"Saito Kanako","avatar":""},{"name":"Yuki Kimura","avatar":""},{"name":"Yasumi Yoko","avatar":""},{"name":"小倉一郎","avatar":""},{"name":"樹木希林","avatar":""},{"name":"堤真一","avatar":""},{"name":"風吹ジュン","avatar":""},{"name":"中川雅也","avatar":""},{"name":"大竹しのぶ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Umimachi Diary","Kamakura Diary","Our Little Sister","Nasza młodsza siostra","Küçük Kız Kardeşim","Systrarna","Дневник Умимати","Naša mala sestra","Søstre","Nuestra pequeña hermana","Akhotenou ha''ktana","Η μικρή μας αδελφή","Notre petite soeur","Siskokset","Nuestra hermana pequeña","Unsere kleine Schwester","Nossa Irmã Mais Nova","Sea Town Diary","เพราะเราพี่น้องกัน","海街diary：2015","바닷마을 다이어리","Mənim Balaca Bacım","Nhật Kí Miền Biển","海街diary"]', 1784690324449);
