INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-kha-thi-quoc-gia-bi-an', 'Nhiệm Vụ: Bất Khả Thi - Quốc Gia Bí Ẩn', 'Mission: Impossible - Rogue Nation', 'https://phimimg.com/upload/vod/20231118-1/09ad64760b0baecc917e192b60d040a4.jpg', 'https://phimimg.com/upload/vod/20231118-1/c9fd0879734dcbc5c91b0700aba2a285.jpg', '<p>Ethan và đồng đội của anh phải đối mặt với nhiệm vụ bất khả thi nhất của họ, tiêu diệt đội ngũ Sydicate, một tổ chức sát thủ xuyên quốc gia gồm những thành viên thiện chiến đang tìm cách tiêu diệt tổ chức IMF.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Sean Harris","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Jens Hultén","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Mateo Rufino","avatar":""},{"name":"Fernando Abadie","avatar":""},{"name":"Alec Utgoff","avatar":""},{"name":"Hermione Corfield","avatar":""},{"name":"Nigel Barber","avatar":""},{"name":"William Roberts","avatar":""},{"name":"Patri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324449);
