INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-bat-kha-thi-quoc-gia-bi-an', 'Nhiệm Vụ: Bất Khả Thi - Quốc Gia Bí Ẩn', 'Mission: Impossible - Rogue Nation', 'nhiệm vụ: bất khả thi - quốc gia bí ẩn mission: impossible - rogue nation tom cruise jeremy renner simon pegg rebecca ferguson ving rhames sean harris simon mcburney zhang jingchu tom hollander jens hultén alec baldwin mateo rufino fernando abadie alec utgoff hermione corfield nigel barber william roberts patri ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-tam-toi', 'Con Đường Tăm Tối', 'Blackway', 'https://phimimg.com/upload/vod/20231108-1/fe7cd9906d11c02447477d31afb2134b.jpg', 'https://phimimg.com/upload/vod/20231108-1/0ae968161f19b5232418ff51fce436ee.jpg', '<p>Một phụ nữ trẻ mới trở về quê hương của mình trở thành đối tượng bị quấy rối bởi một người đàn ông tên là Blackway, một cựu cảnh sát trở thành trùm tội phạm bạo lực, người hoạt động mà không bị trừng phạt trong cộng đồng nhỏ ở rìa vùng hoang dã này. Bị người dân thị trấn địa phương bỏ rơi — và được Cảnh sát trưởng khuyên rời khỏi thị trấn — thay vào đó, Lillian quyết định đứng lên chống lại kẻ theo dõi bệnh xã hội học của mình, đồng thời nhờ sự giúp đỡ của người khai thác gỗ cũ Lester và người bạn đồng hành trẻ tuổi lém lỉnh của anh ta.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Alexander Ludwig","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Steve Bacic","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Hal Holbrook","avatar":""},{"name":"Aleks Paunovic","avatar":""},{"name":"Taylor Hickson","avatar":""},{"name":"Chris Gauthier","avatar":""},{"name":"Aaron Pearl","avatar":""},{"name":"Glenn Beck","avatar":""},{"name":"William Belleau","avatar":""},{"name":"Audrey Smallman","avatar":""},{"name":"Dale Wilson","avatar":""},{"name":"Steven Cree Molison","avatar":""},{"name":"Tara Arroya","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324449);
