INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-ho-menh', 'Thần Hộ Mệnh', 'The Guardian Brothers', 'https://phimimg.com/upload/vod/20231108-1/23776ab2938853dcf87f380d8ec6b416.jpg', 'https://phimimg.com/upload/vod/20231108-1/641d73920e970413da928896ca364c49.jpg', '<p>Từ xa xưa ở Trung Quốc luôn có tụcthờ thần hộ mệnh để mong thần linh giúp đỡ mình trong cuộc sống. Tuy nhiên thờigian dần trôi qua, càng ít người biết đến sự tồn tại của thần hộ mệnh. Hai vịthần Thần Đồ và Úc Luật đã quyết tâm lập lại mối quan hệ giữa con người và thầnlinh dù đó là việc không hề dễ dàng…</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Xiaosong Gao","avatar":""},{"name":"Xiaoxing Yi","avatar":""},{"name":"White-K","avatar":""},{"name":"Ji Guanlin","avatar":""},{"name":"Cindy Yu","avatar":""},{"name":"Bi Xiaolan","avatar":""},{"name":"Quangdu Bingba","avatar":""},{"name":"Bella Thorne","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324449);
