INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('keith-richards-anh-huong', 'Keith Richards: Ảnh hưởng', 'Keith Richards: Under the Influence', 'https://phimimg.com/upload/vod/20231108-1/99807f348f12bca974b7a2efb83a2dda.jpg', 'https://phimimg.com/upload/vod/20231108-1/8b743d99d67381480ffac9e11db3e833.jpg', '<p>Trong bộ phim tài liệu độc đáo này, hãy khám phá con người và âm thanh truyền cảm hứng cho huyền thoại nhạc rock &#39;n&#39; roll Keith Richards từ thời ấu thơ cho đến nay.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keith Richards","avatar":""},{"name":"Anthony DeCurtis","avatar":""},{"name":"Steve Jordan","avatar":""},{"name":"Tom Waits","avatar":""},{"name":"Pierre de Beauport","avatar":""},{"name":"Buddy Guy","avatar":""},{"name":"Waddy Wachtel","avatar":""},{"name":"Ivan Neville","avatar":""},{"name":"Clifton Anderson","avatar":""},{"name":"Kevin Batchelor","avatar":""},{"name":"Larry Campbell","avatar":""},{"name":"Charles Dougherty","avatar":""},{"name":"Bernard Fowler","avatar":""},{"name":"Paul Nowinski","avatar":""},{"name":"Patti Hansen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324449);
