INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cai-chet-khong-bao-truoc', 'Những Cái Chết Không Báo Trước', 'Social Suicide', 'https://phimimg.com/upload/vod/20231103-1/f64c2f4d399d06a9d81ffa072a7bb28c.jpg', 'https://phimimg.com/upload/vod/20231103-1/6a377a50f33d76a11d1280e4159f9bd9.jpg', '<p>Tự sát xã hội&#39; là một bộ phim kinh dị điều tra xem xét những gì nó thực sự cần để được chú ý trên Internet ngày nay. Dựa trên Romeo và Juliet một cách lỏng lẻo, cảnh sát điều tra những gì đã xảy ra với hai thanh thiếu niên này trước khi quá muộn bằng cách troll lịch sử mối quan hệ của họ thông qua mạng xã hội.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"India Eisley","avatar":""},{"name":"Olivia Hussey","avatar":""},{"name":"Neve McIntosh","avatar":""},{"name":"Leonard Whiting","avatar":""},{"name":"Richard Cordery","avatar":""},{"name":"Georgia Lock","avatar":""},{"name":"Jackson Bews","avatar":""},{"name":"Aymen Hamdouchi","avatar":""},{"name":"Rollo Skinner","avatar":""},{"name":"Barney White","avatar":""},{"name":"Shaquille Ali-Yebuah","avatar":""},{"name":"Tim Berrington","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324449);
