INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-thuat-cau-long', 'Võ Thuật Cầu Lông', 'Full Strike', 'https://phimimg.com/upload/vod/20231103-1/e076dffc8a2bd011be00dcb4bd16b443.jpg', 'https://phimimg.com/upload/vod/20231103-1/34187d4ce428831e26ce590be961eb20.jpg', '<p>Ng Kau Sau từng là Nữ hoàng cầu lông, cô đã từ bỏ chính mình sau khi bị trục xuất khỏi môn thể thao này. Một ngày nọ, cô gặp một nhóm những kẻ lập dị khủng khiếp: Bậc thầy say rượu đang nằm trên mặt đất, Lam Chiu một tay, Ma Kun khiếm thị và ông chủ mặt sẹo Lau Dan bị mất thính giác. Họ là những tên cướp khét tiếng nhất 10 năm trước, nhưng họ quyết định trở thành những người tốt sau khi ra tù và thành lập &quot;Câu lạc bộ cầu lông Lau Dan&quot;. Anh Sáu rất ấn tượng với họ và quyết định tham gia cùng Dan, tập luyện nghiêm túc và cùng nhau tham gia cuộc thi.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Josie Ho","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Tse Kwan-Ho","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Edmond Leung","avatar":""},{"name":"Andrew Lam","avatar":""},{"name":"Susan Shaw Yam Yam","avatar":""},{"name":"Eric Kwok Wai-Leung","avatar":""},{"name":"Grace Yip","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Julius Brian Siswojo","avatar":""},{"name":"Harriet Yeung","avatar":""},{"name":"Kabby Hui","avatar":""},{"name":"Phat Chan Fei","avatar":""},{"name":"Calvin Cho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324449);
