INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-thuat-cau-long', 'Võ Thuật Cầu Lông', 'Full Strike', 'võ thuật cầu lông full strike josie ho ronald cheng tse kwan-ho ekin cheng yee-kin wilfred lau edmond leung andrew lam susan shaw yam yam eric kwok wai-leung grace yip michael tse philip keung ho-man julius brian siswojo harriet yeung kabby hui phat chan fei calvin cho ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kiem-luu-tinh', 'Đao Kiếm Lưu Tình', 'The Executioner', 'https://phimimg.com/upload/vod/20240711-1/b72ffc39958ce9028d4b053b352e91ca.jpg', 'https://phimimg.com/upload/vod/20240711-1/6c59676a9ac3b21dff0d971493a14307.jpg', '<p><em>Diệp Thường Lục (do Huỳnh Đức Bân thủ vai) là một đao phủ pháp trường từng giết vô số người. Trên đường đến kinh thành nhận nhiệm vụ thì cơ duyên trùng hợp xui khiến Thường Lục gặp gỡ và tá túc tại nhà bà đỡ nổi tiếng của kinh thành, Hoa Nhị Hồng (do Thiệu Mỹ Kỳ đóng vai). Từ đây họ cùng chứng kiến một vụ án mạng ly kì. Tình huống nguy cấp, Nhị Hồng đã ép Thường Lục dùng cây đao Quỷ Đầu mổ bụng nạn nhân cứu một sinh mạng nhỏ. Nào ngờ cậu bé sơ sinh này đã khiến cho Thường Lục và Nhị Hồng vướng vào vòng xoáy chính trị của triều đình, đối mặt với vòng quay sinh tử cận kề. Hai người từ chỗ nghi kỵ, lạnh lùng rồi dần nảy sinh tình cảm yêu thương trong hoạn nạn... Sự xuất hiện của nhiều nhân vật bí ẩn khiến cho quan hệ giữa mọi người rất phức tạp. Và khi thân phận của cậu bé sơ sinh dần được hé lộ cũng là lúc tiếng chuông tử thần vang lên...mở màn cho những cuộc chiến thanh trừng đẫm máu tranh giành quyền lực nơi cung cấm. Liệu tình cảm sâu nặng và cơ duyên trùng hợp có giữ cho Thường Lục và Nhị Hồng được bình yên bên nhau mãi mãi? Hay chỉ như Hoa Bỉ Ngạn – loài hoa duy nhất nở rộ trên đường Hoàng Tuyền. Khi hoa nở thì không có lá, khi có lá thì hoa không nở. Hoa và lá luôn luôn không gặp nhau...</em></p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 18, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Huỳnh Đức Bân","avatar":""},{"name":"Thiệu Mỹ Kỳ","avatar":""},{"name":"Cung Gia Hân","avatar":""},{"name":"Dương Minh","avatar":""},{"name":"Trần Sơn Thông","avatar":""},{"name":"Diêu Tử Linh","avatar":""},{"name":"Khang Hoa","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324449);
