INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-trong-xe-deo-kinh-voi-khau-sung', 'Cô Gái Trong Xe Đeo Kính Với Khẩu Súng', 'The Lady in the Car with Glasses and a Gun', 'https://phimimg.com/upload/vod/20231101-1/55b3db28bcff7df9ed6b1146ae18e4c0.jpg', 'https://phimimg.com/upload/vod/20231101-1/bf3ed605f91ffb46579a068f4974d525.jpg', '<p>Cô ấy là nữ anh hùng xinh đẹp nhất, thiển cận nhất, đa cảm nhất, khó hiểu nhất, cố chấp nhất, không đáng tin cậy nhất và rắc rối nhất. Người phụ nữ trong xe chưa bao giờ nhìn thấy biển. Trên đường chạy trốn khỏi cảnh sát, cô ấy luôn tự nhủ rằng mình không điên… Chỉ có điều…</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Freya Mavor","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Benjamin Biolay","avatar":""},{"name":"Elio Germano","avatar":""},{"name":"Thierry Hancisse","avatar":""},{"name":"Sandrine Laroche","avatar":""},{"name":"Frederic Etherlinck","avatar":""},{"name":"François-Dominique Blin","avatar":""},{"name":"Alexandre von Sivers","avatar":""},{"name":"Olivier Bonjour","avatar":""},{"name":"Noémie Morales","avatar":""},{"name":"Alain Bellot","avatar":""},{"name":"Edouard Giard","avatar":""},{"name":"Lou Lambrecht","avatar":""},{"name":"Vera Van Dooren","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324449);
