INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-ten-xanh-phan-4', 'Mũi Tên Xanh (Phần 4)', 'Arrow (Season 4)', 'https://phimimg.com/upload/vod/20240624-1/d86e075e13d1719c2a8fdb985da9643c.jpg', 'https://phimimg.com/upload/vod/20240624-1/c96504e894da576df35e6faf580ca437.jpg', '<p>Bộ phim là sự sáng tạo lại từ nhân vật cùa DC Comics, Arrow không phải là một thể loại siêu anh hùng, mà chỉ đơn thuần là một anh hùng bình thường nhưng bí ẩn của công dân Starling, anh hùng Oliver Queen. Một cuộc sống bình yên và an toàn nhờ số lượng tội phạm trong thành phố đã giảm, Oliver tin rằng anh cuối cùng đã có thể có một cuộc sống riêng tư với Felicity vào một ngày. Thế nhưng, một nhân vật phản diện chết người lại xuất hiện trong Starling, buộc Oliver nhận ra rằng anh không bao giờ có thể là một Oliver Queen bình thường. Mọi diễn biến sẽ ra sao? Liệu anh có thể tiếp tục chiến tháng cái ác và tiếp tục giữ lại hoà bình cho Starling?</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Amell","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"David Ramsey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324449);
