INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-khoang-cach', 'Tình Yêu Không Khoảng Cách', 'Love Or Spend', 'https://phimimg.com/upload/vod/20240831-1/9a235d5959348dfdabde50b6d9e2ecca.jpg', 'https://phimimg.com/upload/vod/20240831-1/b8ba51cc8bfc4368ec05e36105ecc2d8.jpg', '<p>Tình Yêu Không Khoảng Cách - Love or Spend kể về câu chuyện giữa Thừa Trinh và Chính Hy đã trở thành đôi bạn thanh mai trúc mã từ nhỏ. Họ chưa từng nghĩ sẽ hoàn thành ước nguyện của hai ra đình trở thành thông gia. Nhưng trải qua bao nhiêu khó khăn trong công việc và cuộc sống, họ phát hiện bạn thân mới chính là nửa kia của mình.</p>', 'Hoàn Tất (77/77)', 77, 'series', 'completed', 9, 2015, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Vương Truyền Nhất","avatar":""},{"name":"Tăng Chi Kiều","avatar":""},{"name":"Hồng Tiểu Linh","avatar":""},{"name":"Đại Nguyên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
