INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-nghe-hanh-phuc', 'Lắng Nghe Hạnh Phúc', 'Someone Like You', 'https://phimimg.com/upload/vod/20240829-1/1e4cbc9327ecc9e3f00abb9cb90013ad.jpg', 'https://phimimg.com/upload/vod/20240829-1/8cc5369d3597aeb079fdf719b3f34e9a.jpg', '<p>Phim Lắng Nghe Hạnh Phúc - Someone like you xoay quanh người đàn ông tên là Phương Triển Thừa ông bị mất tất cả mọi thứ trong một vụ tai nạn xe hơi thảm khóc, và ông cũng mất vị hôn thê của mình do ông bị mất thị lực, nhiều nổi đau cứ đến với ông nên ông không còn tâm trí để ghép giác mạc có thể hồi phục lại thị lực. Nhưng bất ngờ đến với ông là có một người phục nữ trông giống hệt vợ của mình, được thuê để trở thành y tá ngày ngày chăm sóc ông. Câu chuyện phim Lắng Nghe Hạnh Phúc bất đầu từ đây ông Phương Triển Thừa có đến với người phục nữ mới không…</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Vương Truyền Nhất","avatar":""},{"name":"Lý Thiệu Tường","avatar":""},{"name":"Miêu Khả Lệ","avatar":""},{"name":"Nhậm Dung Huyên","avatar":""},{"name":"Trần Ngữ An","avatar":""},{"name":"Địch Uy Liêm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
