INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-thien-cot', 'Hoa Thiên Cốt', 'The Journey Of Flower', 'https://phimimg.com/upload/vod/20240829-1/2f33176bc695837e52fbe3bc2268e4f7.jpg', 'https://phimimg.com/upload/vod/20240829-1/4fc760b3ac7d083acf5e0641d1e81286.jpg', '<p>Hoa Thiên Cốt là vị thần cuối cùng của thế gian, cũng là thiên sát cô tinh trăm năm khó gặp, vì trên người có mùi vị đặc biệt dễ chiêu dụ quỷ quái, cho nên từ nhỏ bị yêu ma quấy nhiễu. Nàng đem lòng yêu chính sư phụ của mình - Bạch Tử Họa, nhưng đâu biết nàng chính là sát tinh trong số mệnh của chàng. Mối tình sư đồ luyến này đã lấy bao nước mắt của khán giả ngay từ khi còn là những trang truyện...</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 9, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Mã Khả","avatar":""},{"name":"Trương Đan Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324449);
