INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-pham-tan-nuong', 'Cực Phẩm Tân Nương', 'My Amazing Bride', 'https://phimimg.com/upload/vod/20240828-1/6ba687fc11bea39fca1246c0eff2913c.jpg', 'https://phimimg.com/upload/vod/20240828-1/8fcc6fe92a5db3850f3f0fd241c22924.jpg', '<p>Cực Phẩm Tân Nương - My Amazing Bride kể về Đường Đậu Đậu, một cô nương đã quá tuổi mà chưa chịu lấy chồng. Nàng rất có niềm tin rằng mình sẽ gặp được đức lang quân thông minh, tài trí, yêu chiều nàng. Nào ngờ, Đường gia gặp chuyện tan nhà nát cửa, phải nhờ trang chủ của Khổng Gia Trang ra tay tương cứu. Trang chủ phu nhân Giả Tương Bình gặp gỡ Đậu Đậu đề xuất hôn sự cho con trai lớn là Thẩm Bách Nam. Bách Nam từ nhỏ đã được người người phong tặng là thần đồng, tài hoa vẹn toàn. Trong đêm động phòng hoa chúc, bỗng nhiên thần đồng biến thành kẻ ngây ngốc khờ khạo, Đậu Đậu nổi giận đùng đùng, bỏ về lại Đường gia. Về nhà, nàng chứng kiến cha già bệnh nặng, mẹ già đã thu nhận hết lễ vật, không còn cách nào khác, Đậu Đậu đành quay trở lại nhà chồng, cùng Giả Tương Bình thỏa thuận hiệp ước 1 năm. Trong khi đó, Thẩm Bách Nam đối với Đậu Đậu si mê, một lòng một dạ, gây ra nhiều tình huống oái ăm, tình cảm cũng dần nảy sinh. Đậu Đậu nhận ra bệnh tình khờ khạo của Bách Nam có ẩn tình, quyết định âm thầm điều tra chân tướng sự việc.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2015, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"李沁","avatar":""},{"name":"金世佳","avatar":""},{"name":"徐垚","avatar":""},{"name":"Gao Yang","avatar":""},{"name":"Ying Haoming","avatar":""},{"name":"熊乃瑾","avatar":""},{"name":"包文婧","avatar":""},{"name":"Zhang Yijie","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":