INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-1', 'Lật Mặt 1', 'Face Off 1', 'https://phimimg.com/upload/vod/20240827-1/667f3fb8d800b97ffb55609bdfe34582.jpg', 'https://phimimg.com/upload/vod/20240827-1/51579f93f5715cc1343518fcb96e1e7b.jpg', '<p>Bộ phim Lật Mặt xoay quanh cuộc sống của Khải, một người sống trong cảnh nghèo khổ nên luôn mong muốn đổi đời. Anh cùng người bạn thân là Thắng tham gia vào một nhóm người đào kim cương trong rừng sâu. Hai người may mắn đào được ba viên kim cương thô. Tên Dũng cầm đầu nhóm giang hồ muốn giết hại họ để có được toàn bộ số kim cương. Khải may mắn thoát chết nhưng bạn anh bị giết hại. Dũng liền vu oan cho Khải mang tội giết bạn để chiếm đoạt tài sản. Vừa bị công an truy nã vừa bị nhóm của Dũng truy đuổi, Khải tìm đường chạy trốn. Khải phải thay đổi chính mình để mong sự việc lắng xuống được trở về cùng vợ con.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lý Hải","avatar":""},{"name":"Kim Xuân","avatar":""},{"name":"Trường Giang","avatar":""},{"name":"Lâm Minh Thắng","avatar":""},{"name":"Tiết Cương","avatar":""},{"name":"Võ Thành Tâm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324449);
