INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-nghiet-nga-phan-1', 'Hào Quang Nghiệt Ngã (Phần 1)', 'Hidden Truths (Season 1)', 'https://phimimg.com/upload/vod/20240116-1/668e8b952fb35985e8174d9e7e82ffe5.jpg', 'https://phimimg.com/upload/vod/20240116-1/bb6d8b60254f4192baa13becf6e1c857.jpg', '<p>Bộ phim Hào Quang Nghiệt Ngã có sự tham gia của Camila Queiroz, Marieta Severo, Agatha Moreira.Arlete là một cô gái tuổi teen ngây thơ, với ước mơ trở thành một người mẫu nổi tiếng. Sau khi cha mẹ li dị, gia đình rơi vào cảnh nghèo khó, và Arlete phải đi tìm cơ hội việc làm để giúp đỡ cho gia đình mình. Cơ hội của cô đã tới khi Fanny, một nữ doanh nhân đầy tham vọng nhìn thấy tiềm năng của Arlete và mời cô thử việc tại công ty thời trang của Fanny. Sau một thời gian được đào tạo tại một môi trường chuyên nghiệp. Arlete trở thành át chủ bài của Fanny trên sàn diễn, cô không chỉ lột xác về ngoại hình mà còn đổi tên thành Angel. Tuy nhiên đằng sau ánh hào quang rực rỡ trên sân khấu, những người mẫu của Fanny sẽ có cơ hội có tên trong quyển sách hồng, quyển sách chuyên ghi tên người mẫu để hẹn hò với những đại gia quyền lực và đem về lợi ích cho Fanny. Ban đầu Arlete từ chối tham gia, nhưng vì muốn kiếm tiền cho gia đình, cô đành chấp nhận. Cuộc hẹn đầu tiên của Arlete là với Alex, một doanh nhân quyền lực rất si mê Arlete. Tin tưởng rằng Alex sẽ đem lại cuộc sống mới tốt đẹp hơn cho mình, Arlete tham gia vào trò chơi dục vọng của anh ta và vi phạm điều cấm quan trọng nhất của quyển sách hồng: Không bao giờ có tình cảm với khách hàng.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 16, 2015, 'Thuyết Minh', 'HD', 'Brazil', 0, '[{"name":"Reynaldo Gianecchini","avatar":""},{"name":"Camila Queiroz","avatar":""},{"name":"Marieta Severo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
