INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hao-quang-nghiet-nga-phan-1', 'Hào Quang Nghiệt Ngã (Phần 1)', 'Hidden Truths (Season 1)', 'hào quang nghiệt ngã (phần 1) hidden truths (season 1) reynaldo gianecchini camila queiroz marieta severo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chu-va-chang-hau', 'Cô Chủ Và Chàng Hầu', 'Madam', 'https://phimimg.com/upload/vod/20240820-1/277cd2dc178ef3025778f23858a602e2.jpg', 'https://phimimg.com/upload/vod/20240820-1/a2b10b548094b8e2490a836adf486cc4.jpg', '<p>Ma-nim (Kim Jeong-ah-II) trở thành góa phụ sau khi chồng cô qua đời vì bệnh tật và cô đến Bukgando để tái hôn. Người chồng mới của cô là một người đàn ông đẹp trai và giàu có nhưng anh ta đã bị một người Nhật giết chết ngay cả trước khi cô qua đêm với anh ta. Ma-nim lại một mình trong ngôi nhà lớn. Mọi người bên cạnh chồng cô đều rời đi và chỉ còn lại người ông và nô lệ tên Bau. Một ngày nọ, Ma-nim nhận thấy Bau có cách nhìn chằm chằm vào cô và cô bị choáng ngợp bởi một cảm giác kỳ lạ. Cô phải kìm nén ham muốn của mình với tư cách là một người phụ nữ vì hai cuộc hôn nhân ngắn ngủi và bản sắc nghiêm ngặt của mình. Bau chưa bao giờ quan hệ tình dục với một người phụ nữ trước đây nhưng cô không bận tâm đến ánh mắt của anh ta nhìn cô. Hai người họ bắt đầu một mối tình bị cấm đoán sau lưng ông nội...</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jeong-ah","avatar":""},{"name":"Kim Ji-hoon-VI","avatar":""},{"name":"명계남","avatar":""},{"name":"Amy","avatar":""},{"name":"금광산","avatar":""},{"name":"Jeon Ji-hak","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
