INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-19-hoa-huong-duong-ruc-lua', 'Thám Tử Lừng Danh Conan 19: Hoa Hướng Dương Rực Lửa', 'Detective Conan: Sunflowers of Inferno', 'https://phimimg.com/upload/vod/20231019-1/11e0f6b860d924a2c6074c197ba98a8f.jpg', 'https://phimimg.com/upload/vod/20231019-1/75c17c74cc6048a3ff0ff0d2ccc0b3c7.jpg', '<p>Bộ phim xoay quanh việc Kaitou Kid tuyên bố trộm bức họa &quot;Hoa hướng dương&quot; nổi tiếng của Van Gogh. Rồi Conan cảm thấy hành động của tên Kid rất kì lạ, để khám phá ra sự thật sau hành động kì lạ đó, Conan cùng với nhóm cảnh sát truy bắt Kid... Từ đó Conan khám phá ra được rằng đó không phải là Kid, rất có thể là một kẻ mạo danh Kaitou Kid để hành động. Vậy bức tranh sẽ ra sao? Mục tiêu của Kid là bức tranh &quot;Hoa hướng dương&quot; nổi tiếng của Van Gohn. Tuy nhiên mọi chuyện không chỉ có vậy, Kid dường như đang chuẩn bị đẩy rất nhiều người vào nguy hiểm để đạt được mục đích của mình. Tại sao lại thế?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2015, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Akio Suyama","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Kang Ji-young","avatar":""},{"name":"Kosei Tomita","avatar":""},{"name":"Yoshiko Sakakibara","avatar":""},{"name":"Nana Eikura","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324449);
