INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-19-hoa-huong-duong-ruc-lua', 'Thám Tử Lừng Danh Conan 19: Hoa Hướng Dương Rực Lửa', 'Detective Conan: Sunflowers of Inferno', 'thám tử lừng danh conan 19: hoa hướng dương rực lửa detective conan: sunflowers of inferno minami takayama kappei yamaguchi wakana yamazaki rikiya koyama megumi hayashibara naoko matsui wataru takagi yukiko iwai ikue otani kenichi ogata chafurin akio suyama unsho ishizuka kang ji-young kosei tomita yoshiko sakakibara nana eikura ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-toan-phong', 'Thiếu Nữ Toàn Phong', 'The Whirlwind Girl', 'https://phimimg.com/upload/vod/20240814-1/a28537db13e6fa9f44cf483c4b8fcd27.jpg', 'https://phimimg.com/upload/vod/20240814-1/cfe2328937176fe801b53f48a7e0d7e2.jpg', '<p>&quot;Nguyên Võ Đạo&quot; là một môn võ thuật phổ biến toàn thế giới. Tại Ngạn Dương, nơi bắt nguồn của môn võ này, việc một đứa trẻ xin gia nhập vào một võ quán để tập luyện có khi còn quan trọng hơn việc ăn cơm. 10 năm trước, Khúc Hướng Nam của Toàn Thắng đạo quán đã giành quán quân trong cuộc thi Nguyên Võ Đạo quốc tế là sự sỉ nhục với người dân Ngạn Dương, bởi vì Khúc Hướng Nam trong cuộc thi đó đã sử dụng chất kích thích và bị truất ngôi vị. Kể từ đó, cuộc sống đen tối đã đến gia đình ông và đứa con gái nuôi đầy nghị lực Thích Bách Thảo. Nhưng không chịu khuất phục trước số phận, Bách Thảo đã từng bước trở thành một võ sĩ chân chính, đi tìm bằng chứng minh oan cho sư phụ mình. Cũng từ đó, Bách Thảo vướng vào chuyện tình cảm đầy cảm động với 3 chàng trai Đại Sư Huynh Nhược Bạch lạnh lùng, nhưng anh lại là người luôn giúp đỡ, động viên các sư đệ sư muội của mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 17, 2015, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sean Chen","avatar":""},{"name":"譚松韻","avatar":""},{"name":"An Yuexi","avatar":""},{"name":"지창욱","avatar":""},{"name":"吳磊","avatar":""},{"name":"Yu Ting''er","avatar":""},{"name":"Zhao Yuanyuan","avatar":""},{"name":"Li Chak","avatar":""},{"name":"Gavin Gao","avatar":""},{"name":"Jiang Yiyi","avatar":""},{"name":"Chai Wei","avatar":""},{"name":"Guo Junchen","avatar":""},{"name":"黃聖池","avatar":""},{"name":"Ding Chengxin","avatar":""},{"name":"Huang Tianqi","avatar":""},{"name":"Han Congcong","avatar":""},{"name":"王子璇","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324449);
