INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-than-vo-cuc-phan-3', 'Chiến Thần Vô Cực (Phần 3)', 'Infinity Nado (Season 3)', 'https://phimimg.com/upload/vod/20240811-1/7649d985b6de635671fd5ef2f4643a63.jpg', 'https://phimimg.com/upload/vod/20240811-1/362cd4ad988386cb59b477d47f86da5d.jpg', '<p><span style="text-wrap: nowrap;">Dawn và Athas tìm thấy một cậu bé đang ngủ bí ẩn, Pandora, người bị mất trí nhớ sau khi cậu ấy quay lại. Khi Pandora vừa đến Freewheel Town, anh trở thành mục tiêu truy đuổi của một tổ chức tên là Ancient Hunter Group, tổ chức yêu cầu anh thực hiện &quot;Sứ mệnh vĩ đại&quot;. Dưới sự tấn công của Jin và những người bạn của anh, Nhóm Thợ săn Cổ đại tạm thời bị đẩy lùi.</span></p><p><span style="text-wrap: nowrap;">Với sự giúp đỡ của Jin và những người bạn, Pandora dần dần quen với cuộc sống ở thế giới này và kỹ năng của anh cũng được cải thiện rất nhiều. Liệu Pandora có thể lấy lại ký ức của mình không? “Sứ mệnh vĩ đại” của ông là gì? Câu chuyện sẽ kể cho bạn nghe......</span></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Xuqiao Li","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324449);
