INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ham-cuoi-cung-phan-2', 'Chiến Hạm Cuối Cùng (Phần 2)', 'The Last Ship (Season 2)', 'https://phimimg.com/upload/vod/20240807-1/1881ffd536cd9d63c607d90c211cc2f9.jpg', 'https://phimimg.com/upload/vod/20240807-1/35373c2e57b23538038992defcaa9ca6.jpg', '<p>Sau một đại dịch toàn cầu giết chết và làm suy yếu khoảng một nửa dân số thế giới, thủy thủ đoàn (gồm 217 người có cả nam và nử) trên một tàu khu trục tên lửa dẫn đường của hải quân Mỹ không bị ảnh hưởng. Giờ đây, họ phải cố gắng để tìm cách chữa trị và ngăn chặn vi-rút để cứu nhân loại.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eric Dane","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Travis Van Winkle","avatar":""},{"name":"Christina Elmore","avatar":""},{"name":"Jocko Sims","avatar":""},{"name":"Kevin Michael Martin","avatar":""},{"name":"Michael Curran-Dorsano","avatar":""},{"name":"Jodie Turner-Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324449);
