INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-nhuc-duc', 'Vương Triều Nhục Dục', 'Empire of Lust', 'https://phimimg.com/upload/vod/20231022-1/0f08fc799bca938a56dbbe87ed9c36f1.jpg', 'https://phimimg.com/upload/vod/20231022-1/5254494cae9d745b61ce8cd9028d1963.jpg', '<p>Phim Vương Triều Nhục Dục Lấy bối cảnh năm 1398 ở Triều Tiên. Kim Min-Jae (Shin Ha-Kyun) là thống tướng dưới triều Joseon. Ông si mê mối tình đầu với một cô gái và đặt công danh sự nghiệp vào vòng nguy hiểm. Yi Bang-Won (Jang Hyuk) là một hoàng tử. Anh giúp cha mình gây dựng nên triều đại này nhưng anh lại không được chọn làm thái tử. Anh vẫn nuôi trong lòng khát vọng trở thành vua một ngày nào đó. Cuộc sống trong vương triều vốn thân bất do kỷ, khi ham muốn đi quá tầm, thành bại trở nên mong manh...</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Kang Han-na","avatar":""},{"name":"Shin Ha-kyun","avatar":""},{"name":"Kang Ha-neul","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Lee Jae-yong","avatar":""},{"name":"Choi Moo-sung","avatar":""},{"name":"Kang Kyung-hun","avatar":""},{"name":"Kim Da-ye","avatar":""},{"name":"Kim Koo-taek","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Hwang Geum-hee","avatar":""},{"name":"Kim Sa-hee","avatar":""},{"name":"Lee So-yoon","avatar":""},{"name":"Oh Yeon-Jae","avatar":""},{"name":"Jung Ji-woo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
