INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-xinh-go-cua', 'Gái Xinh Gõ Cửa', 'Knock Knock', 'https://phimimg.com/upload/vod/20231117-1/cc41ccc0e341df0bc4bc1fb773b0b8ab.jpg', 'https://phimimg.com/upload/vod/20231117-1/3f63423e308f2ecf909690b3f80ab191.jpg', '<p>Phim xoay quanh Evan Webber một kiến trúc sư tài giỏi có gia đình hạnh phúc. Rồi một ngày vợ của anh đã dắt 2 đứa con đi đến bãi biển để cắm trại và chỉ còn duy nhất Evan ở nhà. Trong đêm mưa gió đó 2 cô gái xuất hiện với thân hình ướt nhẹp vì mưa, Evan đã cho họ vào và cả 3 đã thân mật với nhau. Sau khi tỉnh dậy lúc nửa đêm Evan dần cảm nhận ra có cái gì đó kì lạ xảy ra trong căn nhà của mình. Điều gì sẽ xảy ra với anh chàng Evan này?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Lorenza Izzo","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Aaron Burns","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Ignacia Allamand","avatar":""},{"name":"Antonio Quercia","avatar":""},{"name":"Dan Baily","avatar":""},{"name":"Megan Baily","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
