INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-day-phan-5', 'Mặt Dày (Phần 5)', 'Shameless (Season 5)', 'mặt dày (phần 5) shameless (season 5) william h. macy jeremy allen white ethan cutkosky shanola hampton steve howey emma kenney christian isaiah cameron monaghan noel fisher kate miner paris newton scott michael campbell elise eberle dennis cockrum ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-vuong-quyen-phan-5', 'Trò Chơi Vương Quyền (Phần 5)', 'Game Of Thrones (Season 5)', 'https://phimimg.com/upload/vod/20240730-1/2da6911b4042ea43e6975a45256321f4.jpg', 'https://phimimg.com/upload/vod/20240730-1/ec35080ed8c5585827cb1073c2668eb4.jpg', '<p>Phần 5 tiếp tục câu truyện về 7 gia tộc chiến đấu để làm chủ vùng đất thần thoại Westeros. Những gia tộc thống trị là Stark, Lannister, và Baratheon. Vị vua của Westeros, Robert Baratheon, yêu cầu người bạn cũ của ông là Eddard – lãnh chúa Stark giữ chức vụ cao nhất (Cánh tay mặt của Nhà vua) và ngầm cảnh báo “Cánh tay” trước đây đã chết vì bị ám sát; Eddard chấp nhận mệnh lệnh để tìm ra sự thật đằng sau. Trong lúc ấy, gia tộc của Nữ hoàng, Lannisters, có lẽ đang dự tính mưu đồ để tước đoạt quyền lực. Ở phía bên kia biển khơi, những thành viên cuối cùng của dòng tộc trước đây đã bị truất phế quyền thống trị ,Targaryens, cũng đang sắp đặt kế hoạch giành lại ngai vàng. Sự xung đột giữa các gia tộc này, và với sự tồn tại của các dòng tộc lớn khác như Greyjoy, Tully, Arryn, và Tyrell đã dẫn đến cuộc chiến toàn diện. Trong khoảng thời gian này thì ở phía cực Bắc, Bóng Trắng – loài quỷ vốn chìm trong giấc ngủ rất dài, nay đã thức giấc…</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Peter Dinklage","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Emilia Clarke","avatar":""},{"name":"Maisie Williams","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Sophie Turner","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"John Bradley","avatar":""},{"name":"Alfie Allen","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Rory Mccann","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Jack Gleeson","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Isaac Hempstead","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324449);
