INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-vo', 'Đổi Vợ', 'My Friend''s Wife', 'https://phimimg.com/upload/vod/20240724-1/b4a96cdb411a3504f8e1401fdeb6df48.jpg', 'https://phimimg.com/upload/vod/20240724-1/638bd9464ae6e382ed29011362ced732.jpg', '<p>Jeong-woo là một người chồng không thể cương cứng trong khi cuộc hôn nhân của anh ấy đang đi xuống. Một người bạn và vợ của anh ấy đến từ Hoa Kỳ gợi ý một chuyến đi cặp đôi và Jeong-woo gặp Hye-sook, vợ của bạn anh ấy, một người cực kỳ quyến rũ. &#39;Gói hàng&#39; của anh cứ mỗi lần nhìn thấy cô lại bị kích thích. Anh ấy cố gắng phớt lờ nó nhưng mỗi lần nhìn thấy cô ấy, anh ấy lại nảy sinh những ảo tưởng về tình dục. Cuối cùng, anh ấy đề nghị với bạn mình rằng hãy &#39;đổi&#39; đối tác...</p>', 'Full', 1, 'single', 'completed', 30, 2015, 'Vietsub', 'FullHD', 'Hàn Quốc', 0, '[{"name":"Jeong Tae-min","avatar":""},{"name":"Hee-jeong","avatar":""},{"name":"Je Dong-hwa","avatar":""},{"name":"Lim Song-i","avatar":""},{"name":"Seo Hyeon","avatar":""},{"name":"Oh Ji-hoon","avatar":""},{"name":"Joo Ye-bin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
