INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-sieu-cap', 'Bảy Viên Ngọc Rồng Siêu Cấp', 'Dragon Ball Super', 'https://phimimg.com/upload/vod/20240718-1/2bd97759054aa140b1968d57f1bdfa37.jpg', 'https://phimimg.com/upload/vod/20240718-1/6bba5797d9c0e92a2984f07933dc151b.jpg', '<p>Sau khi kết thúc trận chiến khốc liệt với Majin Buu, trái đất trở lại hòa bình, Son Goku và người nhà sống một cuộc sống bình yên vô ưu vô lo. Nhưng lúc này, ở sâu trong vũ trụ xa xôi, Beerus - một vị thần đáng sợ đột nhiên thức tỉnh. Beerus là Thần hủy diệt, hắn yêu thích món ăn ngon và cực kì ngang ngạnh, chỉ hơi phật ý là sẽ hủy diệt một tinh cầu mới. Vì điềm báo trong một một giấc mơ thần bí, Beerus đã đến Trái Đất. Son Goku và những người bạn đối mặt với những thách thức bí ẩn, Goku biến thành Super Saiyan God để chiến đấu với Beerus.</p>', 'Full', 131, 'hoathinh', 'completed', 51, 2015, 'Vietsub', 'FullHD', 'Nhật Bản', 0, '[{"name":"野沢雅子","avatar":""},{"name":"堀川りょう","avatar":""},{"name":"鶴ひろみ","avatar":""},{"name":"山寺宏一","avatar":""},{"name":"草尾毅","avatar":""},{"name":"山田栄子","avatar":""},{"name":"皆口裕子","avatar":""},{"name":"渡辺菜生子","avatar":""},{"name":"塩屋浩三","avatar":""},{"name":"平野綾","avatar":""},{"name":"田中真弓","avatar":""},{"name":"古川登志夫","avatar":""},{"name":"中尾隆聖","avatar":""},{"name":"花江夏樹","avatar":""},{"name":"Masakazu Morita","avatar":""},{"name":"三木眞一郎","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '[]', 1784690324449);
