INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-tuyen-chan-dai', 'Cần Tuyển Chân Dài', 'Hot Girls Wanted', 'https://phimimg.com/upload/vod/20231023-1/787389796628a1a4aca9265228736dbd.jpg', 'https://phimimg.com/upload/vod/20231023-1/a676c90cb960fd70fe9c3ed0f05a73f2.jpg', '<p>Bộ phim tài liệu gây tiếng vang tại Liên hoan phim Sundance 2015 của nhà sản xuất Rashida Jones xoay quanh công nghiệp khiêu dâm &quot;nghiệp dư&quot; và những phụ nữ trong đó.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stella May","avatar":""},{"name":"Brian Omally","avatar":""},{"name":"Ava Taylor","avatar":""},{"name":"John Anthony","avatar":""},{"name":"Kelly Silguero","avatar":""},{"name":"Emeterio Silguero","avatar":""},{"name":"Ava Kelly","avatar":""},{"name":"Lucy Tyler","avatar":""},{"name":"Brooklyn Daniels","avatar":""},{"name":"Kendall Plemons","avatar":""},{"name":"Tony D.","avatar":""},{"name":"Levi Cash","avatar":""},{"name":"Alli Rae","avatar":""},{"name":"Dillion Carter","avatar":""},{"name":"Carrie Brooks","avatar":""},{"name":"Belle Knox","avatar":""},{"name":"Alaina Kristar","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324449);
