INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('can-tuyen-chan-dai', 'Cần Tuyển Chân Dài', 'Hot Girls Wanted', 'cần tuyển chân dài hot girls wanted stella may brian omally ava taylor john anthony kelly silguero emeterio silguero ava kelly lucy tyler brooklyn daniels kendall plemons tony d. levi cash alli rae dillion carter carrie brooks belle knox alaina kristar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dragon-ball-z-frieza-hoi-sinh', 'Dragon Ball Z: Frieza Hồi Sinh', 'Dragon Ball Z: Resurrection ''F''', 'https://phimimg.com/upload/vod/20231019-1/dced79d91c5ca093e2383eb08324f41b.jpg', 'https://phimimg.com/upload/vod/20231019-1/d5e083978d7f972e89060134a45bf970.jpg', '<p>Sự xuất hiện của Frieza là một nỗi lo lớn cho toàn bộ hành tinh. Khi chính hành tinh của người Saiyan đã bị chính hắn làm cho nổ tung và biến mất, nhưng may mắn người Saiyan đã đưa được đứa trẻ xuống hành tinh khác có tên gọi là Son Goku, sau khi lớn lên một lần nữa Goku phải đối mặt với kẻ đã hũy diệt hành tinh của mình, bằng sức mạnh, ý chí cùng tấm lòng trong sáng của mình Goku đã đánh bại tên Frieza tàn ác.&nbsp; Vào một ngày đẹp trời nọ, hai tên tàn dư của quân đội Freeza là Sorbet và Tagoma đã tìm kiếm những viên ngọc rồng với mục đích hồi sinh Freeza. Họ đã thành công. Freeza sau khi hồi sinh đã tìm cách trả thù những người Saiyans. Frieza trở lại cùng với một đạo quân hùng hậu ( 1000 tên ). Không những thế, nhân vật phản diện được xem là ác nhất DBZ này còn có thêm sức mạnh mới với một hình hài sáng chói lấp lánh ánh vàng báo hiệu một cuộc chiến không hề dễ dàng cho những Goku, Vegeta, Gohan….lần này.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Masakazu Morita","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Masaharu Sato","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Natsuki Hanae","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324449);
