INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fortitude-phan-1', 'Fortitude (Phần 1)', 'Fortitude (Season 1)', 'https://phimimg.com/upload/vod/20240620-1/cee2875b15b18e6db3626b4279d634ed.jpg', 'https://phimimg.com/upload/vod/20240620-1/d27fff35f764a412a0425106ab7edf11.jpg', '<p>Fortitude là một nơi không giống nơi nào khác. Mặc dù được bao quanh bởi vẻ đẹp hoang sơ của cảnh quan Bắc Cực, Fortitude là một trong những thị trấn an toàn nhất trên trái đất. Ở đây chưa bao giờ xảy ra tội phạm bạo lực. Cho đến bây giờ. Trong một cộng đồng gắn bó chặt chẽ như vậy, một vụ giết người đã chạm đến tất cả mọi người và nỗi kinh hoàng bí ẩn, đáng lo ngại của tội ác này đe dọa đến tương lai của chính thị trấn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Richard Dormer","avatar":""},{"name":"Sienna Guillory","avatar":""},{"name":"Mia Jexen","avatar":""},{"name":"Sofie Gråbøl","avatar":""},{"name":"Luke Treadaway","avatar":""},{"name":"Darren Boyd","avatar":""},{"name":"Björn Hlynur Haraldsson","avatar":""},{"name":"Alexandra Moen","avatar":""},{"name":"Dennis Quaid","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324449);
