INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-kiep-ran-phan-1', 'Tình Người Kiếp Rắn (Phần 1)', 'Tình Người Kiếp Rắn (Phần 1)', 'https://phimimg.com/upload/vod/20240618-1/0eb32dad987936295835d929481cb010.jpg', 'https://phimimg.com/upload/vod/20240618-1/3674195b27edc9a046b08b34437dce70.jpg', '<p>Câu chuyện bắt đầu khi nhà tài phiệt En-Đi-Sê-Gô mua lại khu đền thờ thần Shi-Va hơn ngàn năm tuổi để phục vụ cho mục đích kinh doanh.<br/>Biết được dự định của ông ta, nhiều thần sư đã ra sức can ngăn vì họ cho rằng đây là nơi trú ngụ của rất nhiều loài rắn được thần linh ban phước và có thể biến thành người. Tuy nhiên, Sê- Gô vẫn cho người đập phá ngôi đền thiêng để xây dựng một khách sạn sang trọng bật nhất thủ đô.</p>', 'Hoàn Tất (63/63)', 63, 'series', 'completed', 11, 2015, 'Lồng Tiếng', 'HD', 'Ấn Độ', 0, '[{"name":"Mouni Roy","avatar":""},{"name":"Arjun Bijlani","avatar":""},{"name":"Adaa Khan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324449);
