INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-muon-nguy-hiem-2015', 'Ham Muốn Nguy Hiểm', 'Careful What You Wish For', 'https://phimimg.com/upload/vod/20240619-1/66d6e5bd34459f903e58bb2486db903c.jpg', 'https://phimimg.com/upload/vod/20240619-1/b93149c421c62218abfe80f1143c6363.jpg', '<p>Một chàng trai ngoại tình với vợ của một chủ ngân hàng đầu tư. Chẳng bao lâu, một cái chết đáng ngờ và hợp đồng bảo hiểm nhân thọ đáng kể đã lôi kéo anh ta vào một vụ bê bối.</p>', 'Full', 1, 'single', 'completed', 5, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Jonas","avatar":""},{"name":"Isabel Lucas","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Kandyse McClure","avatar":""},{"name":"Graham Rogers","avatar":""},{"name":"Marc Macaulay","avatar":""},{"name":"David Sherrill","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Paul Sorvino","avatar":""},{"name":"Alex ter Avest","avatar":""},{"name":"John Driskell Hopkins","avatar":""},{"name":"Ross Gallo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
