INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-kim-nu-tac', 'Thiên Kim Nữ Tặc', 'Lady & Liar', 'https://phimimg.com/upload/vod/20240617-1/4bd553196126bafcb94a03abe654b5c4.jpg', 'https://phimimg.com/upload/vod/20240617-1/4aa29ffc00c4e8fe7d8d363c688de5c4.jpg', '<p>Thiên kim nữ tặc lấy bối cảnh ở thành phố Thượng Hải những năm 30. Câu chuyện xoay quanh hai người con gái Tưởng Tâm (Đường Yên), cô con gái bị mất tích từ lâu của một gia đình giàu có và Đỗ Tiểu Hàn (Dương Dung), một tên trộm vừa mới vượt ngục.

Sau một tai nạn trên biển, Tưởng Tâm đã bị mất đi ký ức của mình. Đỗ Tiểu Hàn đã tận dụng cơ hội này để giả mạo làm Tưởng Tâm và có cuộc sống vinh hoa phú quý.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 7, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"唐嫣","avatar":""},{"name":"Hawick Lau Hau-Wai","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"楊祐寧","avatar":""},{"name":"Maggie Chen","avatar":""},{"name":"Zhang Meng","avatar":""},{"name":"Tai Chih-yuan","avatar":""},{"name":"Guo Zi Yu","avatar":""},{"name":"Shawn Wei","avatar":""},{"name":"翟天臨","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
