INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tinh-ai-2015', 'Trò Chơi Tình Ái', 'Decadencia', 'https://phimimg.com/upload/vod/20240616-1/635eb5ffd9a89b3207cdb2c8780aabf9.jpg', 'https://phimimg.com/upload/vod/20240616-1/dfd2c6f45f47c3cbdf4fc6fa7491de68.jpg', '<p>Decadencia là một bộ phim năm 2014 đầy kịch tính và lôi cuốn, mang đến cho người xem một cái nhìn sâu sắc và thú vị về cuộc sống, tình yêu và sự mất kiểm soát. Bối cảnh của bộ phim diễn ra trong một thành phố lớn, nơi xã hội và thế giới kinh doanh đầy tham vọng và tiền tài. Câu chuyện xoay quanh hai nhân vật chính: Oliver, một doanh nhân trẻ thành đạt và Laura, một nữ diễn viên tài năng. Hai người gặp nhau trong một buổi tiệc và từ đó, mọi thứ bắt đầu thay đổi. Oliver là một người đàn ông thành công, giàu có và quyền lực. Anh ta đã quá mệt mỏi với cuộc sống của mình và muốn tìm kiếm sự thay đổi. Laura, trong khi đó, là một người phụ nữ độc lập và tự tin, nhưng cũng đang đối mặt với những khó khăn.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Alejandro Estrada","avatar":""},{"name":"Nataly Umaña","avatar":""},{"name":"Juan Pablo Castaneda","avatar":""},{"name":"Samantha Godoy","avatar":""},{"name":"Roberto Palazuelos","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
