INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-chinh-minh', 'Tìm Lại Chính Mình', 'Kill Me, Heal Me', 'https://phimimg.com/upload/vod/20240614-1/5d652df07d794fe1d5702d85d6130106.jpg', 'https://phimimg.com/upload/vod/20240614-1/5fbafaa6f43a1632c358e07adb45aba1.jpg', '<p>Cha Do Hyun là thế hệ thứ ba của một gia đình tài phiệt. Ám ảnh với nhiều ký ức đau thương ngày bé, trong anh hình thành nên bảy nhân cách khác nhau. Suốt nhiều năm, tuy được điều trị bởi bác sĩ chuyên khoa nhưng bệnh vẫn không khỏi. Cuộc sống tưởng chừng như bế tắc mãi mãi của anh chính thức bước sang trang mới từ ngày gặp bác sĩ Oh Ri Jin.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Sung","avatar":""},{"name":"Hwang Jung Eum","avatar":""},{"name":"Park Seo Joon","avatar":""},{"name":"Kim Yoo Ri","avatar":""},{"name":"Oh Min Suk","avatar":""},{"name":"Kim Yeong Ae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
