INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-3', 'Trại Giam Kiểu Mỹ (Phần 3)', 'Orange Is The New Black (Season 3)', 'https://phimimg.com/upload/vod/20240607-1/946d33444798b76582cdcf2b91e2d13c.jpg', 'https://phimimg.com/upload/vod/20240607-1/c115b7f3248d45b4974a223f833156c4.jpg', '<p>Được chuyển thể từ cuốn hồi ký Orange Is the New Black: My Year in a Womens Prison của Piper Kerman, kể về Piper Chapman, một phụ nữ đang có đầy đủ mọi thứ: nhà cửa, công việc và một người chồng sắp cưới. Bỗng một hôm, cô phải vào tù vì dính líu tới vụ buôn ma túy từ 10 năm trước, cùng người tình đồng tính trước đây. Piper sẽ phải làm sao để sống sót trong tù, cũng như giữ được tình yêu của mình?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2015, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Schilling","avatar":""},{"name":"Samira Wiley","avatar":""},{"name":"Uzo Aduba","avatar":""},{"name":"Dascha Polanco","avatar":""},{"name":"Joel Marsh Garland","avatar":""},{"name":"Danielle Brooks","avatar":""},{"name":"Michael Harney","avatar":""},{"name":"Yael Stone","avatar":""},{"name":"Lea Delaria","avatar":""},{"name":"Annie Golden","avatar":""},{"name":"Vicky Jeudy","avatar":""},{"name":"Selenis Leyva","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Nick Sandow","avatar":""},{"name":"Catherine Curtin","avatar":""},{"name":"Kate Mulgrew","avatar":""},{"name":"Emma Myles","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","