INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nina-pha-dam', 'Nina Phá Đám', 'Nina Forever', 'https://phimimg.com/upload/vod/20240606-1/a27d9604b39b733710dc3d9aafde15c1.jpg', 'https://phimimg.com/upload/vod/20240606-1/086d7943620458ca470823001c6452ca.jpg', '<p>Sau khi người yêu Nina qua đời vì tai nạn xe cộ, Rob đã tự tử nhưng bất thành. Đành bước tiếp trên đường đời, anh yêu say đắm nữ đồng nghiệp phục vụ Holly. Nhưng mối quan hệ cả hai giờ rất khó khăn, khi mà Nina không siêu thoát cứ hiện hồn về quấy rối họ khi đang… làm tình, ngay cả khi đã trốn ra nghĩa địa tòm tem cô ta cũng không tha. Rob và Holly phải chấp nhận cuộc sống và mỗi pha lên đỉnh là một lần… rụng tim.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Abigail Hardingham","avatar":""},{"name":"Cian Barry","avatar":""},{"name":"Fiona O''Shaughnessy","avatar":""},{"name":"David Troughton","avatar":""},{"name":"Elizabeth Elvin","avatar":""},{"name":"Bill Holland","avatar":""},{"name":"Lee Nicholas Harris","avatar":""},{"name":"Sean Verey","avatar":""},{"name":"Phelim Kelly","avatar":""},{"name":"Richard Sandling","avatar":""},{"name":"Javan Hirst","avatar":""},{"name":"Katharine Bennett-Fox","avatar":""},{"name":"Tamar Karabetyan","avatar":""},{"name":"Mandeep Dhillon","avatar":""},{"name":"Barry Castagn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324449);
