INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-hiep-kiem', 'Tiên Hiệp Kiếm', 'Xian Xia Sword', 'https://phimimg.com/upload/vod/20240530-1/fdfb2fa8a9359a391d68a5ecf0b248c7.jpg', 'https://phimimg.com/upload/vod/20240530-1/31d2e2d0d90cf4d0b2796dd87689c5b9.jpg', '<p>Tiên Hiệp Kiếm - Xian Xia Sword là bộ phim được chuyển thể từ cuốn tiểu thuyết nổi tiếng The Tale of Heroes của nhà văn Manchu dưới triều đại nhà Thanh. Đây được xem là một trong số truyền hình cổ trang Trung Quốc đang được chú ý nhất trong năm 2015. Nội dung bộ phim sẽ là câu chuyện xoay giữa vị anh hùng đại diện cho cái thiện và chính nghĩa với những kẻ luôn mang trong mình những dã tâm, gieo rắc tội ác và bất chấp mọi thủ đoạn để thỏa mãn tham vọng thống trị thiên hạ. Và rồi câu chuyện này sẽ đi đến? liệu rằng vị anh hùng có đủ sức để giúp cái thiện chiến thắng cái ác và đem lại sự bình yên ấm no cho bá thánh thiên hạ hay không?</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 8, 2015, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Yi","avatar":""},{"name":"Liu Tingyu","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Shendong Xu","avatar":""},{"name":"Lily Tien","avatar":""},{"name":"高雄","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324449);
