INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-goi-cho-saul-phan-1', 'Hãy Gọi Cho Saul (Phần 1)', 'Better Call Saul (Season 1)', 'https://phimimg.com/upload/vod/20240302-1/857d06daf8aec5b0d78a68300e796513.jpg', 'https://phimimg.com/upload/vod/20240302-1/0ebe78cf9d1c1c500aac872132f8f74a.jpg', '<p>Phần tiền truyện được đề cử Emmy này của Tập làm người xấu theo dấu vị luật sư bình thường Jimmy McGill khi chuyển mình thành luật sư thách thức đạo đức Saul Goodman.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Odenkirk","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Rhea Seehorn","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"Patrick Fabian","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Michael Mando","avatar":""},{"name":"Tony Dalton","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Brandon K. Hampton","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Jeremiah Bitsui","avatar":""},{"name":"Rainer Bock","avatar":""},{"name":"Robert Forster","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
