INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-goi-cho-saul-phan-1', 'Hãy Gọi Cho Saul (Phần 1)', 'Better Call Saul (Season 1)', 'hãy gọi cho saul (phần 1) better call saul (season 1) bob odenkirk jonathan banks rhea seehorn michael mckean patrick fabian giancarlo esposito michael mando tony dalton kerry condon brandon k. hampton mark margolis jeremiah bitsui rainer bock robert forster ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-poldark-phan-1', 'Anh Hùng Poldark (Phần 1)', 'Poldark (Season 1)', 'https://phimimg.com/upload/vod/20240302-1/13d9e011d6a00e1d8384a327e97c6e9a.jpg', 'https://phimimg.com/upload/vod/20240302-1/52a16ef9f2ee3bfe325292c379a4f19a.jpg', '<p>Được chuyển thể từ bộ tiểu thuyết cùng tên của nhà văn Winston Graham, Poldark lấy bối cảnh miền nam nước Anh vào thế kỷ 18. Để thoát khỏi giá treo cổ, Ross Poldark đã gia nhập quân đội Hoàng Gia Anh để chiến đấu trong Cách mạng Mỹ. Trở về quê hương Cornwall sau ba năm trời, anh hay tin cha anh đã qua đời, gia tài nhà anh kiệt quệ, còn người tình cũ là Elizabeth đã được gả cho người em họ Francis. Anh giải cứu một cô gái trẻ tên là Demelza khỏi một trận đòn và nhận cô vào làm chân phụ bếp. Cùng lúc đó, anh cũng ra tay giúp đỡ người dân trong làng và tìm cách bảo vệ những quặng mỏ đang bị đối thủ của anh, tên George Warleggan tham lam và ngạo mạn, lăm le chiếm lấy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aidan Turner","avatar":""},{"name":"Eleanor Tomlinson","avatar":""},{"name":"Heida Reed","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324449);
