INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eva-braun', 'Eva Braun', 'Eva Braun', 'https://phimimg.com/upload/vod/20240228-1/a6c8bcdf2fc5176d8191c4bb949a0edd.jpg', 'https://phimimg.com/upload/vod/20240228-1/4d767a72eea0d5ee3ea4c58cf71f1039.jpg', '<p>Eva Braun lấy cảm hứng từ những vụ bê bối tình dục có thật tại Quốc hội Ý và 120 ngày Sodoma của Marquis De Sade. Sự kết hợp này tạo nên một cuộc hành trình kỳ cục qua sức mạnh, tình dục và ý chí của những người làm mọi thứ để thành công. Pier là một ông trùm quyền lực và quan trọng, người nắm giữ quyền lực ở đất nước mình. Thanh lịch, mỉa mai và có học thức cao, anh ta có một bản năng tình dục kỳ lạ được thỏa mãn bởi tình nhân của cô, Romy, người thu thập mọi người, đàn ông và phụ nữ (nhạc sĩ, đạo diễn, nhà văn và doanh nhân) đồng ý thỏa mãn những tưởng tượng kỳ lạ của anh ta để được anh ta giúp đỡ. con đường dẫn tới thành công. Giống như Decameron, một nhóm người trong một ngôi nhà gặp phải niềm kiêu hãnh và lòng tham quyền lực và tình dục.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Andrea Riva","avatar":""},{"name":"Susanna Giaroli","avatar":""},{"name":"Federica Fracassi","avatar":""},{"name":"Adele Raes","avatar":""},{"name":"Giulia Martina Faggioni","avatar":""},{"name":"Gabriella Riva","avatar":""},{"name":"Nathan Macchioni","avatar":""},{"name":"Gabriele Falsetta","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
