INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thoi-minh-nguyet', 'Tần Thời Minh Nguyệt', 'The Legend of Qin', 'https://phimimg.com/upload/vod/20240319-1/27943d09b2b1228394dcff3010d3c05b.jpg', 'https://phimimg.com/upload/vod/20240319-1/74fbb7533dc5425c0a71d7f0e0b96ad2.jpg', '<p>Tần Thời Minh Nguyệt - The Legend of Qin kể về Kinh Thiên Minh - là con trai của thích khách Kinh Kha - từ một thiếu niên chưa hiểu chuyện đời dần trưởng thành thành một đại hiệp. Sau khi Kinh Kha hành thích Tần Thủy Hoàng thất bị, Kinh Thiên Minh cũng bị truy sát, may mắn gặp được một người bạn cũ của cha là Kiếm thánh Cái Nhiếp giúp đỡ, dạy kiếm thuật. Kinh Thiên Minh đối với Cái Nhiếp kính ngưỡng tôn trọng, coi như cha. Trên đường trốn chạy, Kinh Thiên Minh kết thân với Hạng Thiếu Vũ, Cao Nguyệt, ...Chứng kiến Mặc gia bị nạn, rồi cơ duyên xảo hợp lại thành đệ tử Mặc gia ...</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 7, 2015, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Yi","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Jiang Jinfu","avatar":""},{"name":"Hu Bingqing","avatar":""},{"name":"Qin Junjie","avatar":""},{"name":"Jin Chen","avatar":""},{"name":"Leo Wu","avatar":""},{"name":"Wang Yanlin","avatar":""},{"name":"Gong Beibi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324449);
