INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-cua-me-ke', 'Con Gái Của Mẹ Kế', 'You Are My Sisters', 'https://phimimg.com/upload/vod/20240228-1/920413a97d57427ba8e3da52da7569ab.jpg', 'https://phimimg.com/upload/vod/20240228-1/173d157ba3d0bd2973003f8d418b9e04.jpg', '<p>Con Gái Của Mẹ Kế là câu chuyện xung đột giữa mẹ kế và con chồng. Phim xoay quanh cuộc sống và tình yêu của ba chị em gái An Tịnh, An Ninh và An Lạc. Bí ẩn về tình cảm quá khứ bị tổn thương, câu chuyện năm xưa của nhà họ An là những nút thắt tạo nên kịch tính hấp dẫn. Dù từng có nhiều bất hòa nhưng cuối cùng ba chị em hiểu ra rằng tình thân không bao giờ có thể bị chia cắt và dù phải chịu tổn thương.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 15, 2015, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Khải Uy","avatar":""},{"name":"Lâu Nghệ Tiêu","avatar":""},{"name":"Bạch Băng","avatar":""},{"name":"Lưu Nhã Sắc","avatar":""},{"name":"Lý Khê Nhuế","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324449);
