INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-choi-ga-mo', 'Tay Chơi Gà Mờ', 'Dope', 'https://phimimg.com/upload/vod/20240228-1/1b6e7b5c42c888bf0f7f21005d058b2d.jpg', 'https://phimimg.com/upload/vod/20240228-1/760d7a3a0b6e5155fde61ffe0a9f13bd.jpg', '<p>Bữa tiệc ngầm mang đến cuộc phiêu lưu hoang dại cho một học sinh xuất sắc khi cậu cố gắng tồn tại ở trường cấp ba và trong cuộc sống ở khu phố Los Angeles bên bạn bè.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shameik Moore","avatar":""},{"name":"Tony Revolori","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"De''Aundre Bonds","avatar":""},{"name":"Roger Guenveur Smith","avatar":""},{"name":"Blake Anderson","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Rakim Mayers","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Quincy Brown","avatar":""},{"name":"Rick Fox","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
