INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-chet-kane', 'Giết Chết Kane', 'Kill Kane', 'null', 'https://phimimg.com/upload/vod/20240228-1/7f9a7a19c41c8ea35592960f3b083a85.jpg', '<p>Bộ phim Giết Chết Kane - Kill Kane kể về câu chuyện xảy ra ở một thành phố đầy rẫy bạo lực, một giáo viên - Ray Brookes sống trong thành phố này, vợ và con của anh đã bị một băng đảng khét tiếng giết chết. Anh không tin vào hệ thống luật pháp trong thành phố có thể giúp anh giành lại công lý cũng như chẳng còn gì để mất, nên anh đã tự mình đi tìm băng đảng khét tiếng đó và trả thù, giành lại công lý.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vinnie Jones","avatar":""},{"name":"Nicole Faraday","avatar":""},{"name":"Sebastian Street","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
