INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-duoi-den-cung', 'Truy Đuổi Đến Cùng', 'Never Let Go', 'https://phimimg.com/upload/vod/20240228-1/e493aa646382b5e52e1e18778b218fe7.jpg', 'https://phimimg.com/upload/vod/20240228-1/841ff8ec32f050c3628d65ab3774f346.jpg', '<p>Bộ phim kể về một chuyến du lịch tới Morocco, Lisa Brennan đã phải đối mặt với cơn ác mộng khủng khiếp nhất đối với bất kì bậc phụ huynh nào: đánh mất đứa con gái 5 tháng tuổi mà cô đơn độc chăm sóc. Lạc lõng nơi đất khách, cô vô vọng tìm kiếm người con mà không nhận được bất kì sự trợ giúp nào. Trong vòng 3 giờ đầu tiên, Lisa nhận thức rõ tình trạng cấp bách của người con. Với khả năng mà cô đã được huấn luyện trong chính phủ Hoa Kỳ, cô đã làm mọi thứ có thể, vượt qua mọi giới hạn của bản thân để truy tìm manh mối.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324450);
