INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-nu-sinh', 'Học Viện Nữ Sinh', 'Juuou Mujin No Fafnir', 'https://phimimg.com/upload/vod/20240220-1/0c49a7b7c335d874e6284f7018c6857b.jpg', 'https://phimimg.com/upload/vod/20240220-1/725fc2e9a62ce9c9b8b4ba6e201a9874.jpg', '<p>Chuyện kể về cậu trai Yuu Mononobe , giống đực duy nhất ở thế giới “D”. Vào một ngày đẹp trời, cậu bất ngờ “được” hốt vô học tại trường nữ sinh Midgar – ngôi trường vốn chỉ dành cho những cô gái “D”. Cuộc sống của cậu giờ đây sẽ ra sao, khi mà mới vô học ngày đầu tiên đã “giúp con gái nhà người ta khỏi lấy chồng”. Trong cái rủi may mà không kẹp thêm cái xui, khi mà cậu được đoàn tụ với cô em gái bé bỏng Mitsuki của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 18, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324450);
