INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-ma-quy-su', 'Thây Ma & Quỷ Sứ', 'Scouts Guide To The Zombie Apocalypse', 'https://phimimg.com/upload/vod/20240227-1/711804c4180fdda7d7644a77de6d1f0a.jpg', 'https://phimimg.com/upload/vod/20240227-1/30e9111dbbf6effd4a1536781efc682e.jpg', '<p>Ba người do thám và những người bạn suốt đời hợp sức với một cô phục vụ cocktail badass để trở thành đội anh hùng khó có thể xảy ra nhất thế giới. Khi thị trấn yên bình của họ bị tàn phá bởi một cuộc xâm lược của thây ma, họ sẽ chiến đấu để giành được huy hiệu của cuộc đời và thử nghiệm kỹ năng trinh sát của mình để cứu nhân loại khỏi xác sống.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Miller","avatar":""},{"name":"Joey Morgan","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Sarah Dumont","avatar":""},{"name":"David Koechner","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
