INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-ngu', 'Không Ngủ', 'Sleepless', 'https://phimimg.com/upload/vod/20240227-1/361cf91ec448265f0d91bb8caf44ed2a.jpg', 'https://phimimg.com/upload/vod/20240227-1/73dbe84c50081a5fa0c75a3171652891.jpg', '<p>Bị mất ngủ, hai nhân viên tổng đài bắt đầu đi chơi cùng nhau vào ban đêm. Họ tạo ra sự gắn kết giúp mỗi người ứng phó với những tổn thương trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Glaiza De Castro","avatar":""},{"name":"Dominic Roco","avatar":""},{"name":"TJ Trinidad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
