INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-doc-than', 'Những Người Độc Thân', 'The Lobster', 'https://phimimg.com/upload/vod/20240227-1/a4919ef0bb8c07518b091f9ccc96717e.jpg', 'https://phimimg.com/upload/vod/20240227-1/a5ebe7b47f0b41fc334029c948f36d35.jpg', '<p>Ý nghĩa của “The Lobster” có lẽ nằm ở việc miêu tả một xã hội tương lai rất kì lạ nhưng lại rất quen thuộc. Đó là một xã hội mà con người bị đánh giá dựa trên mối quan hệ tình cảm của họ, những định kiến xã hội kì lạ nhưng lại ảnh hưởng đến tất cả. Những cặp đôi thì được thổi phồng thái quá với những quyền lợi như được sống trên du thuyền, được tung hô ngoài xã hội. Còn những kẻ cô đơn thì bị săn đuổi, rẻ mạt, thậm chí bị biến thành mồi săn trong trò chơi của những kẻ khác. Nói cách khác, FA là một tội. Chính vì thế mà các nhân vật trong phim rất áp lực để tìm được nửa kia của mình, thậm chí sẵn sàng tự sát nếu không thành công. Đạo diễn Lanthimos cũng đã chia sẻ trong buổi chiếu phim tại Liên Hoan Phim New York: “Lần này tôi muốn khám phá về mối quan hệ tình cảm, và tại sao người ta lại rất áp lực để thành công trong chuyện đó.”</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Ariane Labed","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
