INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-hoan-canh-buddy-guards', 'Cặp Đôi Hoàn Cảnh', 'Buddy Guards', 'https://phimimg.com/upload/vod/20240227-1/482def83f99d221bb5a68fae20a32ef3.jpg', 'https://phimimg.com/upload/vod/20240227-1/719447e671fc0cec350e3fe84726bf4a.jpg', '<p>Cặp Đôi Hoàn Cảnh - Buddy Guards xoay quanh cặp đôi nhiều ngang trái Alfonso và Walter. Alfonso là cảnh sát viên cứng cựa của Dịch vụ Vệ Sĩ cao cấp thuộc Bộ Công An Pháp buộc phải phối hợp với Walter, một thanh niên trẻ thiếu kinh nghiệm, cuốn hút bởi thế giới showbiz. Cặp đôi này chịu trách nhiệm bảo vệ cho Jal-Y, một ngôi sao R’n’B đang bị đe dọa bởi người yêu cũ, một tội phạm đang bỏ trốn. Từ đây, bao chuyện dở khóc dở cười diễn ra.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Alice Belaïd","avatar":""},{"name":"Joey Starr","avatar":""},{"name":"Manu Payet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
