INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-trong-tu-cua-dai-thieu-gia', 'Nhật Ký Trong Tù Của Đại Thiếu Gia', 'Imprisoned: Survival Guide For Rich And Prodigal', 'null', 'https://phimimg.com/upload/vod/20240220-1/dd157ad3fb98ec4f89c3f1618a52694c.jpg', '<p>Nhật Ký Trong Tù Của Đại Thiếu Gia - Imprisoned: Survival Guide For Rich And Prodigal kể về Thần Thần công tử giàu có với toàn những người đẹp và xe hơi nổi tiếng, trong một lần lái xe say rượu cùng một cô gái mưới quen đã gây tai nạn lafmng đi đường bị thương nặng. Đối mặt với phán quyết của tòa án trong vòng 48 giờ sau khi gây ra vụ tai nạn, bị kết án 18 tháng tù giam. Bước chân vào cuộc sống trong tù, anh bàng hoàng nhận ra thế giới đằng sau song sắt là một trật tự đen tối. Chỉ cần hiểu được quy luật sinh tồn, hắn có thể an toàn sống sót sau khi thụ án. Yu Richen đã sử dụng tư duy phong phú và sự giàu có của thế hệ thứ hai của mình để nhấn mạnh vào việc tối ưu hóa chất lượng khắt khe của cuộc sống trong tù. Trước sức ép mạnh mẽ trong tình thế tuyệt vọng, bản thân sẽ giải quyết như thế nào?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cai Hanyi","avatar":""},{"name":"Liao Qizhi","avatar":""},{"name":"Wang Zongyao","avatar":""},{"name":"Zhang Jiansheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
