INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ve-gian-nan', 'Đường Về Gian Nan', 'The Long Way Home', 'null', 'https://phimimg.com/upload/vod/20240220-1/21fad3a4842185d2b5f56cf268dc8953.jpg', '<p>Đường Về Gian Nan - The Long Way Home tái hiện lại cuộc chiến đấu cam go, nguy hiểm giữa hai miền Nam và Bắc Triều Tiên những năm 1950. Một binh sỹ Nam Hàn và một một binh sỹ Bắc Hàn sau một trận chạm trán mà bị đối phương bắt giữ. Hai con người thuộc hai chiến tuyến bất đắc dĩ phải đi cùng nhau và cả hai phải trải qua nhiều tình huống dở khóc dở cười: Một bên phải thực hiện nhiệm vụ bảo vệ xe tăng và một bên phải đoạt lại tài liệu mật để có thể trở về nhà an toàn.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
