INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-ve-ben-anh', 'Quay Về Bên Anh', 'Bromance', 'https://phimimg.com/upload/vod/20240215-1/79228c1f4e07797ef1a36481269e10c2.jpg', 'https://phimimg.com/upload/vod/20240215-1/7ef948d7d86c99f26e8dad01ebc53f8a.jpg', '<p>Quay Về Bên Anh kể câu chuyện cách đây 25 năm, ông Tỳ thấp thỏm đứng đợi bên ngoài phòng sinh, mong ngóng có được một mụn con trai để nối dõi, không ngờ người tính không bằng trời tính, đứa con mà ông mong chờ là một bé gái. Mọi chuyện trở nên rắc rối khi một ông thầy bói đã phán với vợ chồng ông rằng, đứa trẻ sẽ chết sớm nếu ông bà không nuôi dạy bé gái này như một bé trai cho đến khi tròn 26 tuổi. Ngay lập tức, cô bé được khai sinh với một cái tên rất nam tính, Tỳ Á Nặc. Từ đó trở đi, để bảo vệ tính mạng, Tỳ Á Nặc bắt đầu cuộc sống của một chàng trai thực thụ, cô lớn lên với vẻ bề ngoài rất đàn ông và là một chàng trai tốt bụng. Tuy vậy, cô luôn giữ khoảng cách với những người xung quanh, thường tỏ ra bí ẩn với những người không biết đến bí mật của mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
