INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-dong-phan-1-2015', 'Biến Động (Phần 1)', 'Glitch (Season 1)', 'https://phimimg.com/upload/vod/20240309-1/edc25323c434a6e3e68e351c6b9a98bd.jpg', 'https://phimimg.com/upload/vod/20240309-1/e77f21226b2228e56fe2033f1b370693.jpg', '<p>Sĩ quan cảnh sát James Hayes gặp phải cú sốc chưa từng có trong cuộc đời khi một số cư dân địa phương sống dậy từ cái chết, trong đó có cả người thân yêu nhất của anh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2015, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Patrick Brammall","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Emma Booth","avatar":""},{"name":"Emily Barclay","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Sean Keenan","avatar":""},{"name":"Hannah Monson","avatar":""},{"name":"Aaron L. McGrath","avatar":""},{"name":"John Leary","avatar":""},{"name":"Rodger Corser","avatar":""},{"name":"Andrew McFarlane","avatar":""},{"name":"Luke Arnold","avatar":""},{"name":"Rob Collins","avatar":""},{"name":"Pernilla August","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
