INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-duong-2015', 'Học Đường 2015', 'Who Are You: School 2015', 'https://phimimg.com/upload/vod/20240209-1/f06073ef67e62987bade59255c264a5d.jpg', 'https://phimimg.com/upload/vod/20240209-1/11371cf8d86c60cf11801e335aa4a135.jpg', '<p>Được coi là siêu tân tinh của thế hệ tiếp theo, Kim So Hyun, Nam Joo Hyuk và Yook Sung Jae của BTOB được chọn tham gia phần sáu trong loạt phim Học Đường của KBS. Tất cả đều thành công kể từ năm 1999. Nội dung xoay quanh Lee Eun Bi (Kim So-hyun), một học sinh là nạn nhân bị bắt nạt trong lớp đến nỗi phải tự sát nhưng được người chị song sinh giống hệt, Eun Byul cứu sống. Bị mất trí nhớ sau lần tự tử và bị nhầm là Eun Byul, Eun Bi lấy danh tính của chị gái và quay lại trường để tìm ra sự thật.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 17, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim So Hyun","avatar":""},{"name":"Sung-Jae Yook","avatar":""},{"name":"Kim Bo Ra","avatar":""},{"name":"Nam Joo Hyuk","avatar":""},{"name":"Pill-Mo Lee","avatar":""},{"name":"Byeong-gyu Jo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324450);
