INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-co-dai', 'Chiến Binh Cổ Đại', 'Avengers Grimm', 'null', 'https://phimimg.com/upload/vod/20240220-1/1faf55d9fa1de32d4ee8abfab0fd6ea2.jpg', '<p>Chiến Binh Cổ Đại - Avengers Grimm là câu chuyện khi Rumpelstiltskin phá hủy Gương ma thuật và trốn thoát tới thế giới hiện đại, bốn công chúa của Once Upon a Time - Cinderella, Sleeping Beauty, Bạch Tuyết, và Rapunzel-được hút qua các cổng thông tin. Được đào tạo và sở hữu với sức mạnh kỳ diệu, bốn phụ nữ phải đấu tranh Rumpelstiltskin và quân đội của hắn trước khi hắn biến tất cả những người trên trái đất thành nô lệ…</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lou Ferrigno","avatar":""},{"name":"Casper Van Dien","avatar":""},{"name":"Lauren Parkinson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
