INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rise-of-the-footsoldier-part-ii', 'Rise Of The Footsoldier Part II', 'Rise Of The Footsoldier Part II', 'https://phimimg.com/upload/vod/20240220-1/807ec5e95c149dcfb99b34bafb3d0df4.jpg', 'https://phimimg.com/upload/vod/20240220-1/004dfcb3bbe838d26aacec89b65c524f.jpg', '<p>Vào ngày 6 tháng 12 năm 1995, ba thành viên Gang Essex bị sát hại dã man trong máu lạnh. Bây giờ là đầu năm 1997 và bất cứ ai giết chết ba người đàn ông vẫn chưa được mang đến công lý. Một cộng sự của những người đàn ông, vẫn tang lại sự mất mát của bạn bè, tin chắc rằng đó chỉ là vấn đề thời gian trước khi anh ta tiếp theo. Đối với anh ta, lối thoát duy nhất là quay trở lại và làm việc theo cách của mình lên thang hình sự. Anh ta càng nhận được càng càng cao, những công việc bạo lực càng trở nên, nhiệm vụ quyền lực của anh ta biến thành một nỗi ám ảnh. Với sự sống và gia đình trên dòng, anh ta có thể giữ dây thần kinh của mình với nhau lần cuối để thoát khỏi cuộc sống không?</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324450);
