INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('triet-ha', 'Triệt Hạ', 'Take Down', 'null', 'https://phimimg.com/upload/vod/20240219-1/6d1781562bd9d7955b2e2f18551041cb.jpg', '<p>Một số trẻ vị thành niên hư hỏng được gửi đến một hòn đảo ở Scotland để giáo huấn và đa số họ là con các nhà tỷ phú. Một hôm nhóm tội phạm tấn công hòn đảo bắt cóc và giam giữ họ để đòi tiền chuộc lên đến hàng tỷ đô-la...</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
