INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-chien-shiraz', 'Nội Chiến Shiraz', 'September Of Shiraz', 'https://phimimg.com/upload/vod/20240219-1/ba43ac082f0e37400469fd94cc758a1a.jpg', 'https://phimimg.com/upload/vod/20240219-1/15a34b22cbf3b373e4583b555176f83a.jpg', '<p>Trước cuộc cách mạng Iran, người dân được thể hiện niềm tin tôn giáo của mình và được đối xử bình đẳng. Nhưng kể từ khi cuộc cách mạng diễn ra tháng 9 năm 1979, tất cả đã thay đổi. Dalia Sofer, một gia đình Do Thái bị cuốn vào cơn lốc cách mạng của Iran phải chạy trốn cuộc nội chiến ra sao?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Shohreh Aghdashloo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324450);
