INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-trong-thi-tran-bayou', 'Bố Đời Trong Thị Trấn BAYOU', 'Bad Asses On The Bayou', 'https://phimimg.com/upload/vod/20240219-1/fa0c73b89a5d95ca9c9745a2b31b7a68.jpg', 'https://phimimg.com/upload/vod/20240219-1/59af3e0eb4afe2e884ba01125b46d917.jpg', '<p>Phần thứ ba trong loạt phim hành động - hài Bad Ass thành công. Bad Asses on the Bayou tái hợp bộ đôi năng động, Frank Vega (Danny Trejo) và Bernie Pope (Danny Glover), khi họ đến Louisiana để tham dự đám cưới của người bạn thân Carmen Gutierrez (Loni Love). Những gì được hình dung là một cuộc chạy trốn vào cuối tuần của đám cưới về phía nam trở nên xấu xí dữ dội như một cơn điên loạn và tình trạng lộn xộn xảy ra, thúc giục các anh hùng cao cấp của chúng ta một lần nữa phục vụ công lý.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"John Amos","avatar":""},{"name":"Loni Love","avatar":""},{"name":"Jimmy Bennett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
