INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-kinh-hoang', 'Bữa Tiệc Kinh Hoàng', 'Corpse Party', 'https://phimimg.com/upload/vod/20240219-1/0dbe6d97ef2c739b90073e7eac552b90.jpg', 'https://phimimg.com/upload/vod/20240219-1/d4237e95f1edbbb1e4652bf036f6fc07.jpg', '<p>Đối mặt với lời tạm biệt và tốt nghiệp, Naomi Nakashima, người bạn thời thơ ấu Satoshi Mochida và các bạn cùng lớp của họ, đang dọn dẹp sau lễ hội văn hóa cuối cùng của họ, khi lớp trưởng yêu thích kinh dị Ayumi Shinozaki quyết định biểu diễn Sachiko Ever After để họ sẽ mãi mãi là bạn. Thay vào đó, họ được đưa đến một buổi lễ tốt nghiệp ma ám của Trường tiểu học Heavenly Host, buộc phải đóng cửa sau một loạt vụ giết người khủng khiếp. Số phận nào đang chờ đợi Naomi và những người bạn của cô tại ngôi trường bị nguyền rủa...?</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Rina Ikoma","avatar":""},{"name":"Ryousuke Ikeoka","avatar":""},{"name":"Nozomi Maeda","avatar":""},{"name":"Yoko Kita","avatar":""},{"name":"Reina Visa","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
