INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deep-web', 'Deep Web', 'Deep Web', 'https://phimimg.com/upload/vod/20240207-1/33cae512d18e5f6d2284ee8750d7210e.jpg', 'https://phimimg.com/upload/vod/20240207-1/f43f11ec0194779fc6d8e3280264fc8f.jpg', '<p>Deep Web đưa ra câu chuyện bên trong của một trong những câu chuyện tội phạm kỹ thuật số quan trọng và hấp dẫn nhất của thế kỷ -- vụ bắt giữ Ross William Ulbricht, doanh nhân 30 tuổi bị kết tội là Cướp biển Dread Roberts, người sáng tạo và điều hành mạng chợ đen Con đường Tơ lụa. Là bộ phim duy nhất có quyền truy cập độc quyền vào gia đình Ulbricht, Deep Web khám phá cách những bộ óc thông minh nhất và những nhà lãnh đạo có tư tưởng đằng sau Deep Web và Bitcoin hiện đang bị cuốn vào cuộc chiến giành quyền kiểm soát một tương lai gắn bó chặt chẽ với công nghệ, với kỹ thuật số của chúng ta. quyền treo trong sự cân bằng.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Ross Ulbricht","avatar":""},{"name":"Cody Wilson","avatar":""},{"name":"Lyn Ulbricht","avatar":""},{"name":"Kirk Ulbricht","avatar":""},{"name":"Andy Greenberg","avatar":""},{"name":"Nicolas Christin","avatar":""},{"name":"Christopher Soghoian","avatar":""},{"name":"Cindy Cohn","avatar":""},{"name":"Christopher Tarbell","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324450);
