INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('deep-web', 'Deep Web', 'Deep Web', 'deep web deep web keanu reeves ross ulbricht cody wilson lyn ulbricht kirk ulbricht andy greenberg nicolas christin christopher soghoian cindy cohn christopher tarbell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-chin-tang-thap-quy', 'Ma Thổi Đèn: Chín Tầng Tháp Quỷ', 'Chronicles Of The Ghostly Tribe', 'https://phimimg.com/upload/vod/20240207-1/d1508112230976fbc21c58f7358b1a15.jpg', 'https://phimimg.com/upload/vod/20240207-1/ee10dd6b27c95af7c735b94a70231410.jpg', '<p>Năm 1979, trên núi Côn Luân phát hiện hài cốt sinh vật thần bí, Hồ Bát Nhất cùng đoàn thám hiểm tìm kiếm bí mật của di tích cổ trên đó đến được Cửu Tầng Yêu tháp. Nhiều người trong đoàn bỏ mạng trên đường đi hoặc mất tích, không rõ sống chết.Hồ Bát Nhất sau khi giải ngũ trở lại Bắc Kinh, gặp lại bạn thân Vương Khải Tuyền, một lần nữa bước lên hành trình tìm kiếm nền văn minh cổ. Trên đường cùng Shirley Dương tình cờ gặp gỡ, khuôn mặt quen thuộc của cô làm anh nhớ lại những ngày tháng ở cùng đoàn thám hiểm kia. Chuyến đi nguy hiểm, cả đoàn đã bị quái vật tấn công, để rồi nhận ra chuyện phát sinh nơi này lại một lần nữa liên quan đến Cửu Tầng Yêu tháp, mà lần này chờ đợi bọn họ, chính là một bí ẩn chưa có lời đáp đã phủ bụi cả ngàn năm…</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yao Chen","avatar":""},{"name":"Mark Chao","avatar":""},{"name":"Rhydian Vaughan","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Feng Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
