INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-hanh-huong', 'Những Người Hành Hương', 'Saints & Strangers', 'https://phimimg.com/upload/vod/20240118-1/18ac7c1e5bbf2cfa4c3ec42eb72ac2fb.jpg', 'https://phimimg.com/upload/vod/20240118-1/b1f77c79bdccf7b7e3e6cb8e7d69f393.jpg', '<p>Để sống sót ở Thế giới Mới, dân di cư trên con tàu Mayflower phải chịu đựng xung đột nội bộ, thời tiết khắc nghiệt và một liên minh yếu ớt với những láng giềng bản địa.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Stevenson","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Barry Sloane","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Raoul Trujillo","avatar":""},{"name":"Michael Jibson","avatar":""},{"name":"Kalani Queypo","avatar":""},{"name":"Michael Greyeyes","avatar":""},{"name":"Del Zamora","avatar":""},{"name":"Tatanka Means","avatar":""},{"name":"Rebecca Makin-Taylor","avatar":""},{"name":"Melissa H","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
