INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dam-phan', 'Người Đàm Phán', 'Bridge Of Spies', 'https://phimimg.com/upload/vod/20240207-1/729b43171532993fd59e64133126dbdd.jpg', 'https://phimimg.com/upload/vod/20240207-1/3d90ea385896f083b8538ba0ef53a34c.jpg', '<p>Phim Người Đàm Phán - Bridge Of Spies 2015 lấy bối cảnh từ những năm 60 – thời kì đỉnh điểm của chiến tranh Lạnh giữa hai cường quốc Mỹ - Liên Xô, bộ phim là câu chuyện xoay quanh luật sư James Donovan. Mặc dù xuất thân là luật sư bảo hiểm, có ít kinh nghiệm về các vụ án hình sự, nhưng CIA đã lựa chọn và “giao” cho James một nhiệm vụ an ninh tầm cỡ quốc gia vô cùng quan trọng. Đó là một trong những “thương vụ” đàm phán trao trả tù binh lớn nhất của chính phủ Mỹ sau sự kiện chiếc máy bay U-2 của quân đội Mỹ bị bắn rơi tại Xô-viết.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Mark Rylance","avatar":""},{"name":"Alan Alda","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
