INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maggie-dua-con-zombie', 'Maggie: Đứa Con Zombie', 'Maggie', 'https://phimimg.com/upload/vod/20240205-1/4e28f7feebfb07a46ac684fd28bdaa00.jpg', 'https://phimimg.com/upload/vod/20240205-1/03674e623b7ac660ddf89f3b47b6c1de.jpg', '<p>Có một đại dịch xác sống đang đe dọa loài người, nhưng Wade, một nông dân ở một thị trấn nhỏ và là người đàn ông của gia đình, không chấp nhận thất bại ngay cả khi con gái Maggie của anh ta bị nhiễm bệnh. Khi tình trạng của Maggie trở nên tồi tệ hơn và chính quyền tìm cách tiêu diệt những người nhiễm vi-rút, Wade bị đẩy đến giới hạn trong nỗ lực bảo vệ cô. Joely Richardson đóng chung trong bộ phim kinh dị hậu tận thế này.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Douglas M. Griffin","avatar":""},{"name":"J.D. Evermore","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
