INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-2015', 'Truy Sát', 'Momentum', 'https://phimimg.com/upload/vod/20240205-1/63d975ce519e20f9edb467abe1246c3c.jpg', 'https://phimimg.com/upload/vod/20240205-1/74bbe7ecb3b2c661d24d0788d13b9e81.jpg', '<p>Nội dung của bộ phim xoay quanh Alex (Olga thủ vai), một nữ siêu trộm chưa từng một lần thất bại. Trước khi giải nghệ, Alex đồng ý tham gia cùng đồng bọn trong phi vụ khổng lồ cuối cùng. Nhưng siêu trộm không ngờ cô đã vô tình bị dính vào một tổ chức vô cùng nguy hiểm vì đây không đơn thuần chỉ là một vụ cướp kim cương. Bị truy đuổi bởi những sát thủ khét tiếng, Alex phải dùng hết khả năng quân nhân được huấn luyện trước đây để vừa phải bảo vệ tính mạng, đồng thời phải tìm ra được sự thật và “truy sát” chính những kẻ đứng trong bóng tối đang săn lùng cô để kết thúc mọi chuyện.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Jenna Saras","avatar":""},{"name":"Lee-Anne Summers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
