INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoat-sac-sinh-huong', 'Hoạt Sắc Sinh Hương', 'Legend Of Fragrance', 'https://phimimg.com/upload/vod/20240118-1/c9fac6dbb5c3863289e16744a6cc949a.jpg', 'https://phimimg.com/upload/vod/20240118-1/b1e8eeffb438ac7f1c9dfae8bce6abfb.jpg', '<p>21 năm trước, vì sự ra tay tàn độc của Ninh Hạo Thiên, An Thu Thanh, một người có tài pha chế hương liệu đã mất đi vợ và con gái An Nhược Hoan. Ông quyết tâm tìm lại Ninh Hạo Thiên để rửa mối hận năm xưa.&nbsp;Gia tộc họ Ninh sinh ra hai người con Ninh Trí Viễn và Ninh Bối San bị khiếm khuyết về khướu giác, duyên phận để Trí Viễn gặp được cô gái có năng khiếu trời sinh về việc ghi nhớ mùi hương là Lạc Nhan (chính là An Nhược Hoan). Điều đặc biệt hơn nữa ở Lạc Nhan là trên người cô từ lúc sinh ra đã luôn tỏa một hương thơm ngào ngạt. Đôi oan gia ngày ngày gây gổ nhưng lại phải lòng nhau, cho đến khi họ phát hiện ra thân thế thật của mình và vén màn bí mật về sự thù hận giữa hai gia tộc. Từ đây đôi uyên ương mắc vào một tấn bi kịch đầy nước mắt...</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Dịch Phong","avatar":""},{"name":"Đường Yên","avatar":""},{"name":"Trần Vỹ Đình","avatar":""},{"name":"Thư Sướng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
