INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-mo-ky-bi', 'Cổ Mộ Kỳ Bí', 'Tomb Mystery', 'https://phimimg.com/upload/vod/20240219-1/bdeb9d41177086dc63e42f08a6039edd.jpg', 'https://phimimg.com/upload/vod/20240219-1/3bd82c6f66772c164ac032d2ac1c521d.jpg', '<p>Phim Cổ Mộ Kỳ Bí - Tomb Mystery: Nhóm sinh viên khảo cổ học, anh thợ điêu khắc cùng với một nhà đầu tư quyết định đi thám hiểm lăng mộ công chúa Cao Dương đời Đường. Dù đã chuẩn bị tâm lý “một đi không về”, nhưng khi đối mặt với những bí ẩn nơi cổ mộ và những cái bẫy chết người vẫn khiến các thành viên kinh hoàng khiếp sợ.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lữ Duật Lai","avatar":""},{"name":"Tạ Quân Hào","avatar":""},{"name":"Trương Duệ Gia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
