INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-gio-de-giet', 'Sáu Giờ Để Giết', 'Age Of Kill', 'https://phimimg.com/upload/vod/20240128-1/07b7ef3b05ba04fcda72d473737eae4d.jpg', 'https://phimimg.com/upload/vod/20240128-1/1705114c7dcd396173993510c60f25f3.jpg', '<p>Một tay súng bắn tỉa hoạt động đen bị một tên khủng bố quốc tế tâm thần tống tiền để giết 6 người không liên quan trong 6 giờ... nhưng còn nhiều điều đối với các nạn nhân hơn là những gì bạn nhìn thấy.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Kemp","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"April Pearson","avatar":""},{"name":"Nick Moran","avatar":""},{"name":"Anouska Mond","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324450);
