INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-tre-trau', 'Băng Đảng Trẻ Trâu', 'Zutaboro', 'https://phimimg.com/upload/vod/20240128-1/c4ccdb1c183c8f651fa81e7924cfb448.jpg', 'https://phimimg.com/upload/vod/20240128-1/684463108fa077d602defb6bcbd35c21.jpg', '<p>Koichi (Tasuku Nagase), Yakko (Atsushi Arai) và Kyamu tốt nghiệp cùng một trường sơ trung. Koichi giờ đang học trung học và cậu gia nhập một nhóm đầu gấu với Yakko. Trong nhóm, cậu gặp Ueki (Arata Horii) và Oni (Eiki Narita). Koichi rất giỏi đánh nhau và thường tán tỉnh các cô gái. Tuy nhiên, Yakko lại có một quãng thời gian khó khăn. Trong nhóm, cậu bị bắt nạt và trở nên lầm lỳ. Cậu tự thề sẽ trả thù cho Yakko, và Koichi đã gia nhập băng nhóm yakuza mà mẹ cậu ghét nhất.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Thuyết Minh', 'HD', 'Nhật Bản', 0, '[{"name":"Fumika Shimizu","avatar":""},{"name":"Atsushi Arai","avatar":""},{"name":"Kaho Minami","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
