INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-con-lai-chuyen-di-dai-va-ky-la-cua-bob-weir', 'Người Còn Lại: Chuyến Đi Dài Và Kỳ Lạ Của Bob Weir', 'The Other One: The Long Strange Trip Of Bob Weir', 'https://phimimg.com/upload/vod/20240128-1/b17249e71c9341f876cbf4da9f865d5e.jpg', 'https://phimimg.com/upload/vod/20240128-1/9e1add7962f9b70e7091a1ebd81bd098.jpg', '<p>Thiên ký sự về Bob Weir này nêu bật tình bạn với Jerry Garcia và thành công của anh trong vai trò thành viên của một trong những ban nhạc có tầm ảnh hưởng nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Weir","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324450);
