INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-mang-trong-biet-thu-da', 'Vụ Án Mạng Trong Biệt Thự Đá', 'The Tooth And The Nail', 'null', 'https://phimimg.com/upload/vod/20240126-1/11194a8115a3d834f489db49e7f3f162.jpg', '<p>Vụ Án Mạng Trong Biệt Thự Đá - The Tooth And The Nail xoay quanh cuộc đụng độ của hai người đàn ông tại một căn biệt thự đá cổ kính. Những việc xảy ra giữa họ vào thời điểm đó là một bí ẩn. Khi cuộc điều tra được tiến hành, cảnh sát phát hiện có 6 viên đạn được bắn ra và dựa theo các bằng chứng còn sót lại ở hiện trường thì Nam Do Jin - tài phiệt giàu có bị bắt giữ vì tội giết người tài xế Choi Seung Man. Thi thể của người tài xế không được tìm thấy tại hiện trường, nhưng mọi dấu vết đều chứng minh Nam Do Jin chính là thủ phạm. Những bí ẩn xung quanh vụ án được làm rõ khi cuộc chiến pháp lý nổ ra để cứu thoát Nam Do Jin khỏi tội danh giết người.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Sung Woo","avatar":""},{"name":"Kim Jung-Hun","avatar":""},{"name":"Ko Soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
