INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-biet-2-nhung-ke-noi-loan', 'Dị Biệt 2: Những Kẻ Nổi Loạn', 'Divergent 2: Insurgent', 'https://phimimg.com/upload/vod/20240123-1/b8fc6fa4d1adbb6a0350931d8adc4a64.jpg', 'https://phimimg.com/upload/vod/20240123-1/91817f886dd427a81fea160e7f056c4d.jpg', '<p>Những Kẻ Nổi Loạn - Dị Biệt 2 - Insurgent: là bộ phim hành động phiêu lưu, khoa học viễn tưởng và tình cảm Mỹ 2015 của đạo diễn Robert Schwentke. Ở phần này, Tris và Four bây giờ là kẻ tội phạm trên đường chạy trốn, bị truy nã bởi Jeanine, lãnh đạo của các tầng lớp uyên bác thèm khát quyền lực. Chạy đua với thời gian, họ phải tìm ra những gì gia đình Tris của hy sinh mạng sống của mình để bảo vệ, và lý do tại sao các nhà lãnh đạo uyên bác sẽ làm bất cứ điều gì để ngăn chặn chúng. Bị ám ảnh bởi quá khứ của mình, nhưng sự lựa chọn tuyệt vọng để bảo vệ những người cô yêu, Tris, phải đối mặt với một thách thức không thể tiếp nhau khi họ mở khóa các sự thật về quá khứ và cuối cùng là tương lai của thế giới của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Ansel Elgort","avatar":""},{"name":"Theo James","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324450);
