INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-z-trong-zachariah', 'Chữ Z Trong Zachariah', 'Z For Zachariah', 'https://phimimg.com/upload/vod/20240123-1/3737cc2c9ad5e2f53fa6f6c11e10c735.jpg', 'https://phimimg.com/upload/vod/20240123-1/30d22b4fe0f7fc273692dbb06b690399.jpg', '<p>Sau một cuộc chiến tranh hạt nhân, một phụ nữ trẻ tự mình sống sót, lo sợ rằng mình thực sự có thể là người phụ nữ cuối cùng trên trái đất, cho đến khi cô phát hiện ra cảnh tượng đáng kinh ngạc nhất trong cuộc đời mình: một con người khác. Là một nhà khoa học quẫn trí, anh ta gần như phát điên vì phơi nhiễm phóng xạ và tìm kiếm những người khác trong tuyệt vọng. Một sợi dây tin tưởng mong manh, bắt buộc kết nối họ. Nhưng khi một người lạ bước vào thung lũng, mối quan hệ bấp bênh của họ bắt đầu tan vỡ.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Robbie","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Chris Pine","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324450);
