INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-duong-gian-nan', 'Chặng Đường Gian Nan', 'Long Way North', 'https://phimimg.com/upload/vod/20240123-1/09da5d69114aa493d67c593bcb5afde1.jpg', 'https://phimimg.com/upload/vod/20240123-1/ef86efe15f3cefb573b076a3ee79ddca.jpg', '<p>1892, Sankt-Peterburg. Sasha, một quý tộc trẻ người Nga, luôn bị cuốn hút bởi cuộc sống phiêu lưu mạo hiểm của ông nội cô. Là một nhà thám hiểm nổi tiếng, ông đã thiết kế một con tàu bắc cực tráng lệ, nhưng ông đã không trở về từ chuyến thám hiểm cuối cùng của mình tới Bắc Cực. Để cứu lấy danh dự của gia đình, Sasha bỏ trốn. Đi về hướng Great North, cô lần theo dấu vết của ông mình để tìm kiếm con tàu nổi tiếng của ông.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Christa Théret","avatar":""},{"name":"Féodor Atkine","avatar":""},{"name":"Audrey Sablé","avatar":""},{"name":"Thomas Sagols","avatar":""},{"name":"Rémi Caillebot","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
