INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-ton-giua-dai-duong', 'Sinh Tồn Giữa Đại Dương', 'Against The Sun', 'https://phimimg.com/upload/vod/20240123-1/87defaea9704a39118c2ccf4e2fc0337.jpg', 'https://phimimg.com/upload/vod/20240123-1/e989abc0dd8f9bbd762cd13ace338352.jpg', '<p>Sinh Tồn Giữa Đại Dương - Against the Sun: Bộ phim dựa trên một câu truyện đau lòng có thật trong Thế chiến thứ II, 3 phi công thuộc Hải quân Mỹ đã đâm máy bay phóng ngư lôi của họ xuống Nam Thái Bình Dương và 3 người họ chỉ còn lại được một chiếc bè cứu sinh, xung quanh là đại dương bao la. Không thức ăn, không nước uống. Không hy vọng được giải cứu. Chống lại sự lạc lõng, bất đồng quan điểm, 3 người họ cũng phải chống lại những cơn bão, cá mập, sự đói khát. Họ chỉ còn biết dựa vào nhau mà sống...</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Felton","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Jake Abel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
