INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-doi-xa-hoi', 'Chống Đối Xã Hội', 'Anti-Social', 'https://phimimg.com/upload/vod/20240123-1/c2d19b63818013892eb8e4cd4af03458.jpg', 'https://phimimg.com/upload/vod/20240123-1/599e659d03362876dce13da0e8b4ea08.jpg', '<p>Anti-Social 2015 dựa trên những sự kiện có thật, kể về hai anh em tên Dee và Marcus sống ở trung tâm Luân Đôn. Hai anh em mưu sinh bằng nghề trộm cướp, mọi chuyện bắt đầu đảo lộn khi một trong hai anh em quen được một cô bạn gái, cùng với việc bị cảnh sát truy đuổi gắt gao. Liệu họ sẽ chấp nhận một cuộc sống mưu sinh nguy hiểm này, hay hoàn lương?</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gregg Sulkin","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Josh Myers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
