INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-doi-mang-2015', 'Mạng Đổi Mạng', 'Skin Trade', 'https://phimimg.com/upload/vod/20240122-1/dfbe742577003be8123327fe922aaacc.jpg', 'https://phimimg.com/upload/vod/20240122-1/20056489be6dd8692f04c87e9215a652.jpg', '<p>Mạng Đổi Mạng - Skin Trade: là câu chuyện về cuộc chiến giữa cảnh sát và bọn buôn bán người xuyên quốc gia. Nick Cassidy (Dolph Lundgren) – cảnh sát điều tra của bang New Jersey đã đến Bangkok, hợp tác cùng Tony Vitayakui (Tony Jaa) – cảnh sát điều tra Thái Lan để hạ gục băng nhóm tội phạm chuyên mua bán phụ nữ. Kẻ cầm đầu băng nhóm là Viktor Dragovic (Ron Perlman), một kẻ tinh ranh, mưu mô, tham tiền và tàn độc. Dragovic có mối thù lớn với cảnh sát Nick sau khi anh bắn gục con trai của Dragovic trong một lần truy quét. Chính vì vậy, Dragovic lên kế hoạch giết chết Nick và gia đình của anh. Nick may mắn chỉ bị trọng thương, nhưng vợ và con gái của anh đã tử vong sau một vụ nổ lớn. Mặc dù nguy hiểm bủa vây, Nick vẫn quyết tâm truy bắt kẻ thù để triệt phá đường mua bán người, trả thù cho vợ và con gái của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Tony Jaa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
