INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-que-ra-pho', 'Cừu Quê Ra Phố', 'Shaun The Sheep Movie', 'https://phimimg.com/upload/vod/20240121-1/63a323eb7960a9cd712fd3182419a3e8.jpg', 'https://phimimg.com/upload/vod/20240121-1/3e95dea5e0f89c0da4373ef3ceddfe27.jpg', '<p>Mệt mỏi vì làm việc tại trang trại, cừu đặc biệt, Shaun, đưa đàn chó của mình và con chó của nông dân, Bitzer, vào kế hoạch thoát hiểm tạm thời của riêng mình sau một tai nạn bất ngờ. Thật không may, trong thành phố lớn, người nông dân được chẩn đoán mắc chứng mất trí nhớ, có thể thay đổi cuộc sống trang trại bình thường của họ mãi mãi, và đội hình đặt ra một kế hoạch để lấy lại trí nhớ của nông dân và trở về trang trại. Nhưng, một nhân viên kiểm soát động vật tên là Trumper can thiệp vào kế hoạch của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
