INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-bao-kinh-hoang', 'Điềm Báo Kinh Hoàng', 'Visions', 'https://phimimg.com/upload/vod/20240121-1/1e2759d23a8806c5dcc27e8f2d1bb40a.jpg', 'https://phimimg.com/upload/vod/20240121-1/306d6bd1d1d68706fbcfe269ada38bd0.jpg', '<p>Phim Visions kể về Eveleigh, một phụ nữ mang thai vừa chuyển đến ở tại vườn nho cùng chồng. Tuy nhiên, cô bắt đầu nhìn thấy các “ảo tượng” đáng sợ không rõ nguyên do. Và có vẻ như nó liên quan đến đứa con chưa ra đời của cô.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isla Fisher","avatar":""},{"name":"Gillian Jacobs","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
