INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-luc-chet', 'Quyền Lực Chết', 'Macbeth', 'https://phimimg.com/upload/vod/20240118-1/984b7b83e51fb51899bcd7a6038d645e.jpg', 'https://phimimg.com/upload/vod/20240118-1/01574b114fe538b3ca1164ed855bd547.jpg', '<p>Phim Quyền Lực Chết - Macbeth 2015 là bản mới nhất do ba nước Anh, Mỹ, Pháp hợp tác sản xuất và do đạo diễn Justin Kurzel thực hiện với cốt truyện dựa theo giai thoại về vị vua Macbeth xứ Scotland, người không từ thủ đoạn nào để đạt được mục đích của mình. Trong số những vở kịch mà William Shakespeare từng viết, Macbeth là vở kịch u tối, chết chóc nhất. Nội dung xoay quanh việc vị dũng tướng Macbeth, người nhận được lời tiên tri từ ba phù thủy rằng một ngày nào đó, ông sẽ trở thành vua của Scotland. Dù chưa bao giờ làm điều ác nhưng lại tham vọng nên Macbeth sớm mê muội bởi lời tiên tri và lời xúi giục từ người vợ. Ông lên kế hoạch giết vua Duncan để chiếm đoạt ngai vàng. Chìm đắm trong quyền lực, Macbeth trở thành vị vua độc tài và buộc phải giết ngày càng nhiều người hơn để bảo vệ mình khỏi các thế lực mà ông nghi ngờ là thù địch. Vai chính Macbeth được thể hiện bởi nam diễn viên tài năng Michael Fassbender. Trong khi đó vai vợ Macbeth do nữ diễn viên người Pháp Marion Cotillard đảm nhận. Cả hai đều là những ngôi sao có thực lực, từng được đề cử hoặc đoạt giải Oscar trong sự nghiệp.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Jack Madigan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
