INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luan-don-khoi-lua', 'Luân Đôn Khói Lửa', 'He Who Dares: Downing Street Siege', 'https://phimimg.com/upload/vod/20240205-1/d7db0c5099915f47db0d902eedebdf57.jpg', 'https://phimimg.com/upload/vod/20240205-1/d491eb6153c2695daf8a31946e7ef92d.jpg', '<p>Phim xoay quanh một cuộc chiến khốc liệt giữa một băng nhóm tội phạm và lực lượng SAS của chính phủ. Kế hoạch bắt cóc con gái Thủ tướng Anh hoàn hảo của băng nhóm tội phạm này đã bị một nhân viên SAS phá vỡ! Không dừng lại ở đó, bọn tội phạm đã lên một kế hoạch mới táo bạo hơn để trả thù. Lần này nhắm đến một mục tiêu lớn hơn, chính là tòa nhà số 10 phố Downing, dinh Thủ Tướng Anh. SAS phải làm gì để giải cứu Thủ Tướng khỏi cuộc vây bắt đầy khói lửa này.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Simon Phillips","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
