INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-bo-quoc-te-2015', 'Khủng Bố Quốc Tế', 'Extraction', 'https://phimimg.com/upload/vod/20240111-1/c1d4c00335ecf2627a15f6edd2f5caeb.jpg', 'https://phimimg.com/upload/vod/20240111-1/ed414edac62529de2bd1cebed898a112.jpg', '<p>Một cựu đặc vụ CIA bị một nhóm khủng bố bắt cóc. Khi con trai ông biết rằng không có kế hoạch nào để cứu cha mình, ông đã phát động chiến dịch giải cứu của riêng mình.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Gina Carano","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
