INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chinh-phuc-trai-tim-em', 'Chinh Phục Trái Tim Em', 'Art Ache', 'https://phimimg.com/upload/vod/20240111-1/7af2478775383f2d2fa192a346fefb91.jpg', 'https://phimimg.com/upload/vod/20240111-1/c267590bf75c96ff015638f6833042a7.jpg', '<p>Chinh Phục Trái Tim Em - Art Ache kể về câu chuyện của anh chàng Alex coi thường Nghệ thuật Hiện đại nhưng lại phải lòng một cô nghệ sĩ Pháp đáng yêu. Anh hiểu rằng cách duy nhất để chinh phục trái tim cô là vờ như mình là một nghệ sĩ. Bây giờ anh phải chiến thắng một cuộc thi Nghệ thuật Hiện đại để có được trái tim của cô ấy.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Wayman","avatar":""},{"name":"Dee-Tails","avatar":""},{"name":"Sharlit Deyzac","avatar":""},{"name":"Adrian Bouchet","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
