INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-huyet-tam-mai', 'Đạp Huyết Tầm Mai', 'Port Of Call', 'https://phimimg.com/upload/vod/20240104-1/50066eb164c5761558f54ac22b378ea1.jpg', 'https://phimimg.com/upload/vod/20240104-1/27ca77d766cd353c3c7d9a9aa3caeeee.jpg', '<p>Phim Đạp Huyết Tầm Mai (2015): Từ Hồ Nam đến Thạch Môn Đông Quán, cuối cùng Vương Giai Mai (Xuân Hạ) và Vương Giai Lợi (Thái Kiết) đã cùng mẹ đến cảng. Nhưng Vương Giai Mai có cuộc sống không vui trong trường học, trong gia đình cũng xuất hiện mâu thuẫn. Một năm sau, Vương Giai Mai gặp nạn. A Tàng (Quách Phú Thành) cùng đồng bọn Yên Sạn (Đàm Diệu Văn) điều tra vụ án, phát hiện Mai đã trở thành thiếu nữ bán dâm, và những chứng cứ đã chỉ vào một tài xế xe tải nóng tính Đinh Tử Thông (Bạch Chỉ). Sau đó Thông tự thú và kể ra toàn bộ vụ án. Chỉ có A Tàng cảm thấy còn có điều đáng nghi, nên đã điều tra những người xung quanh Mai và Thông, dần dần phát hiện ra nội tình.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Quách Phú Thành","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Jessie Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
