INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('macadam-stories', 'Macadam Stories', 'Macadam Stories', 'https://phimimg.com/upload/vod/20240104-1/1d4c2da8f246c766e218dbe559c20eae.jpg', 'https://phimimg.com/upload/vod/20240104-1/110cbd754fa9974e7d5109b4ee4125c7.jpg', '<p>Chống lại bối cảnh của một tòa nhà chung cư đổ nát ở trung tâm của khu rừng đô thị Pháp, những câu chuyện về sự ẩn danh xã hội, sự cô đơn và tác dụng đau đớn của sự âu yếm trong suốt thời gian trở nên đan xen với những hành động của lòng tốt, đoàn kết và một cuộc gặp gỡ kỳ lạ với nghịch lý. Sau khi trải nghiệm sự trớ trêu tàn nhẫn của sự tàn nhẫn của FIRShand, người thuê nhà, Sternkowitz, hãy pha chế một kế hoạch thúc đẩy để tạo ấn tượng đầu tiên tốt về một y tá ca sống cô đơn, dựa vào máy ảnh Polaroid cũ của mình. Trong khi đó, ngôi sao điện ảnh không an toàn, Jeanne Meyer, đứng bất lực trước sự thẳng thắn của sự thẳng thắn của trẻ trung, vì cô thực sự quan tâm đến những người hàng xóm bên cạnh của cô, Charly, trở thành một ngọn hải đăng của sự tự tin, và người cố vấn không thể tha thứ của cô. Sau đó, ngoài trời, phi hành gia người Mỹ mất phương hướng, John McKenzie, lướt qua Madame Hamida phẳng và nhận ra rằng những bí ẩn của vũ trụ có thể dẫn đến một liên kết tuyệt đẹp. Có thể có sự dịu dàng trong một thế giới ảm đạm?</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
