INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-kung-fury', 'Cảnh Sát Kung Fury', 'Kung Fury', 'https://phimimg.com/upload/vod/20240104-1/e1fe1bdc320895972100c341cfecd45d.jpg', 'https://phimimg.com/upload/vod/20240104-1/2c9fa2511f1847e24fb6c254e16c70f3.jpg', '<p>Trong một chuỗi sự kiện đáng tiếc, một người bạn của Kung Fury bị ám sát bởi tên tội phạm bậc thầy kung fu nguy hiểm nhất mọi thời đại, Adolf Hitler, hay còn gọi là Kung Führer. Kung Fury quyết định du hành ngược thời gian đến Đức Quốc xã để giết Hitler và chấm dứt đế chế Đức Quốc xã một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Sandberg","avatar":""},{"name":"Jorma Taccone","avatar":""},{"name":"Leopold Nilsson","avatar":""},{"name":"Andreas Cahling","avatar":""},{"name":"Helene Ahlson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324450);
