INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-xuan-song-sat-dao', 'Vịnh Xuân Song Sát Đao', 'The Final Master', 'https://phimimg.com/upload/vod/20240104-1/4d196f83a561a265b7631ac4761a64c5.jpg', 'https://phimimg.com/upload/vod/20240104-1/252219540695aaef28195caf84330746.jpg', '<p>Bậc Thầy Võ Thuật thuộc thể loại hành động với những màn võ thuật đẹp mắt. Tương truyền rằng Thiên Tân xưa nay vẫn là thủ đô của của võ Thuật, các trường võ thuật danh tiếng vẫn đứng vững cho đến một ngày sự xuất hiện của sư phụ Trần. Bậc Thầy Võ Thuật – The Final Master bám sát hành trình của Trần sư phụ với Vịnh Xuân Quyền đến từ phương Nam, thách thức các võ sư ở năm võ quán nổi danh của Thiên Tân. Từ đó, bậc thầy quyền thế này đã chinh phục được người vợ xinh đẹp, gầy dựng được võ quán của riêng mình. Nhưng không được bao lâu, sóng gió lại kéo đến khiến hai người phải đối mặt với kẻ thù đầy nguy hiểm trong Bậc Thầy Võ Thuật – The Final Master.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liêu Phàm","avatar":""},{"name":"Tống Giai","avatar":""},{"name":"Kim Sĩ Kiệt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
