INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-si', 'Kiếm Sĩ', 'The Fencer', 'https://phimimg.com/upload/vod/20240103-1/e62b0b1465ce5c189a471e713bd01e15.jpg', 'https://phimimg.com/upload/vod/20240103-1/b82f9138116cba4f924868fb160757ef.jpg', '<p>Chạy trốn khỏi cảnh sát mật của Nga, một vận động viên đấu kiếm trẻ tuổi người Estonia buộc phải trở về quê hương, nơi anh trở thành giáo viên thể dục tại một trường học địa phương. Tuy nhiên, quá khứ bắt kịp và đặt anh ta trước một sự lựa chọn khó khăn.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Märt Avandi","avatar":""},{"name":"Ursula Ratasepp","avatar":""},{"name":"Joonas Koff","avatar":""},{"name":"Piret Kalda","avatar":""},{"name":"Kirill Käro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
