INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh', 'Nỗi Ám Ảnh', 'Obsession', 'https://phimimg.com/upload/vod/20240103-1/5bf1dcde3956064092eb9c082ee0d40c.jpg', 'https://phimimg.com/upload/vod/20240103-1/3616621fe10139100fb012cd5d987cea.jpg', '<p>Simone thừa kế một trang trại đổ nát ở Pháp và đến đó cùng chồng Eric và hai đứa con của họ. Ước mơ của cô ấy là biến ngôi nhà thành một nhà nghỉ chỉ phục vụ bữa sáng nhưng khi tốc độ xây dựng lại đang diễn ra gấp rút, cô ấy bị cuốn vào sự lãng mạn và hỗn loạn của tất cả. Đánh mất mục tiêu của mình, cô ấy phải tìm đường trở lại với những ước mơ và hoài bão đã đưa cô ấy đến đó ngay từ đầu.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Loes Haverkort","avatar":""},{"name":"Mark van Eeuwen","avatar":""},{"name":"Peter Paul Muller","avatar":""},{"name":"Evi van der Laken","avatar":""},{"name":"Bobby van Vleuten","avatar":""},{"name":"Jennifer Hoffman","avatar":""},{"name":"Pierre Boulanger","avatar":""},{"name":"Tamar Baruch","avatar":""},{"name":"Corentin Lobet","avatar":""},{"name":"Eva Duijvestein","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
