INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-dong-khoi-lua-ukraine-chien-dau-vi-tu-do', 'Mùa đông Khói Lửa: Ukraine Chiến đấu Vì Tự Do', 'Winter on Fire: Ukraine''s Fight for Freedom', 'null', 'https://phimimg.com/upload/vod/20240103-1/934604d2c1fe565abb6edf8ae31c7318.jpg', '<p>Sau hơn 93 ngày ở Ukraine, cuộc biểu tình hoà bình của sinh viên đã dần trở thành một cuộc cách mạng bạo lực và phong trào dân quyền chính thức.</p>', 'Full', 1, 'single', 'completed', 30, 2015, 'Vietsub', 'HD', 'Ukraina', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324450);
