INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cau-chuyen-dem-halloween', 'Những Câu Chuyện Đêm Halloween', 'Tales Of Halloween', 'https://phimimg.com/upload/vod/20240103-1/6ebdb41f8d18cf69ad3ad7c581874cca.jpg', 'https://phimimg.com/upload/vod/20240103-1/53130628271f4eb45a258c75e13e4fc5.jpg', '<p>Mười câu chuyện từ các đạo diễn hàng đầu của kinh dị. Hồn ma, ma cà rồng, quái vật và ác quỷ thích khủng bố những cư dân nhẹ dạ cả tin của một khu phố ngoại ô vào đêm Halloween. Tuyển tập rùng rợn này kết hợp những câu chuyện Halloween cổ điển với những cơn ác mộng.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keir Gilchrist","avatar":""},{"name":"Pollyanna McIntosh","avatar":""},{"name":"Samuel Witwer","avatar":""},{"name":"Booboo Stewart","avatar":""},{"name":"Adrienne Barbeau","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
