INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-dau-em-ai', 'Nỗi Đau Êm Ái', 'Painkillers', 'https://phimimg.com/upload/vod/20240108-1/70c4e09893c895c1c7065fde7f0e77c1.jpg', 'https://phimimg.com/upload/vod/20240108-1/5f83d7215bdfac569104a6cdaca201e5.jpg', '<p>Phim Nỗi Đau Êm Ái - Paintkillers 2015: Sau khi trở về từ một nhiệm vụ tuyệt mật ở Afghanistan, những người lính chiến bỗng giật mình tỉnh dậy trong một nơi mà không rõ nằm ở đâu trên tấm bản đồ. Điều kì lạ hơn nữa là họ chẳng nhớ gì về nhiệm vụ vừa qua cũng như nhân thân của chính họ.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Thuyết Minh', 'HD', 'Canada', 0, '[{"name":"Tahmoh Penikett","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Lesley-Ann Brandt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
