INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huy-hieu-cua-danh-du', 'Huy Hiệu Của Danh Dự', 'Badge Of Honor', 'https://phimimg.com/upload/vod/20231231-1/9438d9829ad6416e9efae2e904772135.jpg', 'https://phimimg.com/upload/vod/20231231-1/545816a2e03dd8b24f6dfbd21c697eef.jpg', '<p>Huy Hiệu Của Danh Dự - Badge of Honor kể về việc hai thanh tra ma tuý David Miles và Mike Gallo bị vướng vào một cuộc điều tra nội bộ căng thẳng khi một đứa trẻ bị bắn chết trong một vụ buôn bán ma tuý bạo lực. Thật không may, cái chết của cậu bé lại do sự nhầm lẫn của chính thanh tra Gallo. Từ đây, David Miles và Mike Gallo đứng trước giằng xé nội tâm. Họ sẽ tìm cách che đậy vụ việc hay trả giá cho hành động của mình?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lochlyn Munro","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Martin Sheen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
