INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('salut-damour', 'Salut D''Amour', 'Salut D''Amour', 'https://phimimg.com/upload/vod/20240128-1/c35054ca4387e80f9657d25e64ed2f52.jpg', 'https://phimimg.com/upload/vod/20240128-1/6e55c06b750f69187b314215ac5381ee.jpg', '<p>Sung-chil là một người đàn ông 70 tuổi gắt gỏng sống một mình và làm việc bán thời gian tại siêu thị địa phương. Jang-soo, chủ sở hữu của siêu thị và chủ tịch dự án tái phát triển của thành phố, đã cố gắng vô ích để có được chữ ký của Sung-chil (anh ấy là lần giữ cuối cùng và lý do duy nhất cho sự chậm trễ của dự án), nhưng Sung-chil bướng bỉnh từ chối bất kỳ thay đổi cho lối sống của mình. Sau đó, ông gặp người hàng xóm mới Geum-nim, một người phụ nữ lớn tuổi thân thiện nhưng thân thiện, chạy cửa hàng hoa bên cạnh. Bất chấp tuổi tác, Sung-chil thiếu kinh nghiệm và vụng về trong sự lãng mạn để toàn bộ thị trấn cổ vũ anh ta và giúp anh ta ra tòa. Nhưng con gái của Geum-Nim, Min-Jung không tán thành mối quan hệ.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324450);
