INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-hiep-si-cuoi-cung', 'Những Hiệp Sĩ Cuối Cùng', 'Last Knights', 'https://phimimg.com/upload/vod/20231231-1/33a535b2da3f40433cc20edee4dd8a1c.jpg', 'https://phimimg.com/upload/vod/20231231-1/2c8de6193c303b347d87dd5646a5c414.jpg', '<p>Những Hiệp Sĩ Cuối Cùng - Last Knights lấy bối cảnh thời kỳ trung cổ giả tưởng, người xem sẽ theo chân hành trình của một nhóm các chiến binh tìm cách trả thù cho chủ nhân của mình dưới bàn tay của một hoàng đế độc ác...</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Aksel Hennie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
