INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-diem', 'Tiêu Điểm', 'Spotlight', 'https://phimimg.com/upload/vod/20231231-1/d09dfe03d5b8889a537274333a7cc02e.jpg', 'https://phimimg.com/upload/vod/20231231-1/4e3800b658370ca72dd701dd3f6c1b24.jpg', '<p>Phim Tiêu Điểm - Spotlight 2015 do đạo diễn Tom McCarthy chấp bút cùng nhà biên kịch Josh Singer, dựa trên loạt phóng sự điều tra có thật. Trong phim, Michael Keaton và Mark Ruffalo vào vai hai nhà báo làm việc tại tờ Boston Globe – những người đã đoạt giải Pulitzer năm 2003 cho loạt bài điều tra về các linh mục phạm tội ấu dâm hơn 80 bé trai tại một nhà thờ Công giáo ở Boston, Mỹ. Người xem đồng thuận đánh giá phim là câu chuyện gai góc, khắc họa chân dung ca ngợi lòng quả cảm của các nhà báo. Tương tác giữa các diễn viên được cho là đỉnh cao.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Ruffalo","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Rachel McAdams","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
