INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-vuong-cua-ngay-tan', 'Thần Vương Của Ngày Tàn', 'Seraph Of The End: Vampire Reign', 'https://phimimg.com/upload/vod/20240109-1/38844cbbf72f3fd678fca3d29480521a.jpg', 'https://phimimg.com/upload/vod/20240109-1/6e91321556203087de11a12c8a578501.jpg', '<p>Một ngày nọ, trên trái đất xuất hiện một loại virus lạ đã giết chết những người bị nhiễm ở độ tuổi trên 13. Cùng lúc đó, Ma Cà Rồng xuất hiện trên các ngóc ngách của Địa Cầu và bắt loài người làm nô lệ. Hyakuya Yuuichirou, một chàng trai trẻ cùng với những đứa trẻ còn sót lại trong trại trẻ mồ côi bị Ma Cà Rồng bắt làm vật nuôi. Dù bị cấm đoán nhưng Yuuichirou vẫn nuôi tham vọng tiêu diệt hết lũ Ma Cà Rồng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Miyu Irino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324450);
