INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-sieu-dang', 'Điệp Viên Siêu Đẳng', 'Spooks: The Greater Good', 'https://phimimg.com/upload/vod/20231231-1/25a4e5e38d496ad3c18bf0211a2f3c34.jpg', 'https://phimimg.com/upload/vod/20231231-1/abcc8d8c1dc0615da10ecf159699ed96.jpg', '<p>Spooks: The Greater Good kể về câu chuyện của một điệp viên trẻ tên Will Holloway được MI5 bí mật cử đi truy tìm tung tích của tên tội phạm nguy hiểm Adam Kasim sau khi được đồng bọn giải thoát trong lúc được cảnh sát hộ tống đến nhà tù. Adam được biết với danh hiệu là đao phủ khét tiếng trong giới mafia và hàng loạt những phi vụ buôn ma túy lớn chưa từng có. Hắn thề rằng sau khi trốn thoát sẽ hủy diệt hoàn toàn MI5 để trả thù cho đàn em và những năm tháng trong tù. Will hiện đang bị chính phủ truy đuổi gắt gao về những thông tin quan trọng mà anh đang nắm giữ, được MI5 hỗ trợ và chống lưng Will bắt đầu vào một cuộc chiến vô cùng nguy hiểm và cam go.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kit Harington","avatar":""},{"name":"Tuppence Middleton","avatar":""},{"name":"Jennifer Ehle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
