INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jwanita', 'Jwanita', 'Jwanita', 'https://phimimg.com/upload/vod/20231227-1/0498afbdf6496c0cd22872f00d98c148.jpg', 'https://phimimg.com/upload/vod/20231227-1/b421b5b958b889ac830f71375725f637.jpg', '<p>Bí mật thực hiện ma thuật đen, một phụ nữ đầy trăn trở đoàn tụ với em gái xa cách từ lâu nhưng rốt cuộc lại để lộ ra mối ác cảm giấu kín từ lâu.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Maya Karin","avatar":""},{"name":"Bront Palarae","avatar":""},{"name":"Cristina Suzanne","avatar":""},{"name":"Marsha Milan Londoh","avatar":""},{"name":"Umie Aida","avatar":""},{"name":"Naza Manas","avatar":""},{"name":"Zarina Zainuddin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
