INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('jwanita', 'Jwanita', 'Jwanita', 'jwanita jwanita maya karin bront palarae cristina suzanne marsha milan londoh umie aida naza manas zarina zainuddin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-cua-toi', 'Người Tình Của Tôi', 'I Have A Lover', 'https://phimimg.com/upload/vod/20240109-1/3a3eeea18b92fcaa5e55ab158b7f3e2f.jpg', 'https://phimimg.com/upload/vod/20240109-1/ad0461241bbae86131f5ac02a9ae4aa0.jpg', '<p>Hae Kang và Yong Ki là anh em sinh đôi đã bị chia cắt cách đây 30 năm. Hae Kang từng là một luật sư có gia đình hạnh phúc nhưng sau khi con gái chết, cuộc hôn nhân của cô bắt đầu đổ vỡ. Chồng cô, Jin Eon, con trai của một công ty dược phẩm lớn, bị quyến rũ bởi Seol Ri xinh đẹp, trẻ đẹp và quyết định ly hôn với Hae Kang. Yong Ki mặt khác là một góa phụ mang thai, cuộc đời của côbị đe dọa trong khi cố gắng khám phá sự thật đằng sau cái chết của chồng cô. Trong khi Yong Ki bỏ chạy, cô tình cờ đổi xe với Hae Kang khiến những người theo dõi cô nhầm lẫn danh tính của Hae Kang nên họ cố gắng giết cô. Hae Kang cuối cùng bị mất trí nhớ và sống với Baek Seok, người nghĩ rằng cô ấy là mối tình đầu của Yong Ki. Sự ngây thơ và vui vẻ của Baek Seok khiến cô cảm động và cô tìm thấy hạnh phúc bên anh nhưng khi gặp lại chồng cũ, trái tim cô bắt đầu rung động.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 14, 2015, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hyun Joo","avatar":""},{"name":"Ji Jin Hee","avatar":""},{"name":"Park Han Byul","avatar":""},{"name":"Lee Kyu Han","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
