INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-earl-va-co-ban-hap-hoi', 'Tôi, Earl Và Cô Bạn Hấp Hối', 'Me And Earl And The Dying Girl', 'https://phimimg.com/upload/vod/20231227-1/378aba22d340aa5d6e7277a752458ad7.jpg', 'https://phimimg.com/upload/vod/20231227-1/18e4667da1d14ad43665f0921fe6fe47.jpg', '<p>Greg đang trải qua năm cuối trung học một cách ẩn danh nhất có thể, tránh các tương tác xã hội như bệnh dịch hạch trong khi bí mật làm những bộ phim kỳ quái, sôi nổi với Earl, người bạn duy nhất của anh ấy. Nhưng cả sự giấu tên và tình bạn của anh đều có nguy cơ tan vỡ khi mẹ anh buộc anh phải kết bạn với một người bạn cùng lớp mắc bệnh bạch cầu.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olivia Cooke","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"RJ Cyler","avatar":""},{"name":"Connie Britton","avatar":""},{"name":"Nick Offerman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
