INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cuu-ho-sinh-tu', 'Đội Cứu Hộ Sinh Tử', 'Life On The Line', 'https://phimimg.com/upload/vod/20240121-1/9d694d5947aab0ede0161bdff0715ec7.jpg', 'https://phimimg.com/upload/vod/20240121-1/13fff492e233f6f80f4cb4a1c9996115.jpg', '<p>Phim nói về một đội sữa chữa đường dây điện bị tấn công bởi một cơn bão lớn, trước đó vài ngày thì một cơn mưa nhỏ đã làm đường dây điện bị hỏng và khiến một thành viên trong đội sữa chữa chết vì tai nạn xảy ra, cái chết của ông khiến cho nhiều người thương tiếc và để lại đứa con gái không ai chăm sóc.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Bosworth","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
