INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-quoc-xac-song', 'Đế Quốc Xác Sống', 'The Empire Of Corpses', 'https://phimimg.com/upload/vod/20231230-1/53279bd338a5c2265f3129589e325207.jpg', 'https://phimimg.com/upload/vod/20231230-1/e56cf717c975e6af2ef1fcb7413a747d.jpg', '<p>Câu chuyện của Shisha no Teikoku lấy bối cảnh vào thế kỷ 19 ở Châu Âu, xoay quanh nhân vật John Watson. Anh bị chính phủ truy tìm, để trở thành một điệp viên bí mật. Tuy nhiên, Watson sống trong một thế giới nơi mà “Frankenstein”, những xác chết được gắn linh hồn giả vào, với mục đích sử dụng chúng như những người lao động, nhằm cải thiện và phát triển nền nông nghiệp.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Takayuki Sugo","avatar":""},{"name":"Taiten Kusunoki","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
