INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-night-of-horror-volume-1', 'A Night of Horror Volume 1', 'A Night of Horror Volume 1', 'https://phimimg.com/upload/vod/20231230-1/1f99d27b532b4db46c682ccf6ed67c43.jpg', 'https://phimimg.com/upload/vod/20231230-1/1116565df37cdb0045aa6afc5b036266.jpg', '<p>Cho dù bạn là người hâm mộ liên hoan phim thể loại mang tính biểu tượng của Sydney A Night of Horror hay chỉ là người hâm mộ những bộ phim kinh dị mới hay nhất và đẫm máu nhất, bạn không thể bỏ qua tuyển tập đầy rùng rợn này. Thây ma, thực thể ma quỷ, tự phẫu thuật, ăn thịt đồng loại và hơn thế nữa đang chờ đợi trong những góc tối của đề nghị đáng sợ này từ một số nhà làm phim tài năng nhất làm việc trong thể loại này hiện nay.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bianca Bradey","avatar":""},{"name":"Emily Wheaton","avatar":""},{"name":"Jessica Gower","avatar":""},{"name":"Jessica Hinkson","avatar":""},{"name":"Tegan Higginbotham","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
