INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tan-cong-cua-nguoi-khong-lo-phan-2', 'Cuộc Tấn Công Của Người Khổng Lồ (Phần 2)', 'Attack On Titan (Live Action) (Part 2)', 'https://phimimg.com/upload/vod/20231230-1/a3e3831641960b45a76e1830fe069ef6.jpg', 'https://phimimg.com/upload/vod/20231230-1/3f89fd95db264f0a2b0f7d6514b292ed.jpg', '<p>Attack On Titan (Live-Action) (Part 2) – nối tiếp ở phần 1, Eren biến thành một Titan ngay trước mặt mọi người. Bởi vậy, nhân vật bị chính loài người nghi kị và sợ hãi. Khi sắp sửa bị tử hình, Eren được một Titan mạnh mẽ khác cứu thoát. Từ đó, cậu biết được bí mật đằng sau giống người khổng lồ gieo rắc nỗi kinh hoàng cho nhân loại suốt 100 năm qua, và quyết định chấm dứt cuộc chiến đẫm máu mãi mãi.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Haruma Miura","avatar":""},{"name":"Kiko Mizuhara","avatar":""},{"name":"Kanata Hongô","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
