INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pound-of-flesh', 'Pound Of Flesh', 'Pound Of Flesh', 'https://phimimg.com/upload/vod/20231230-1/23a9525108286bc4cd5dbbecdd3510a2.jpg', 'https://phimimg.com/upload/vod/20231230-1/0f56e8bfbd3e23776f8b6b77df798090.jpg', '<p>Ở Trung Quốc để hiến thận cho cô cháu gái đang hấp hối, cựu đặc vụ xã hội đen Deacon tỉnh dậy vào một ngày trước ca phẫu thuật và phát hiện ra mình là nạn nhân mới nhất của một vụ trộm cắp nội tạng. Bị khâu lại và tức giận, Deacon rời khỏi khách sạn sang trọng của mình để tìm kiếm quả thận bị đánh cắp và tạo ra một con đường đẫm máu xuyên qua những góc tối nhất của thành phố. Đồng hồ đang tích tắc cho cháu gái của anh ấy và với mỗi bước anh ấy mất máu.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"John Ralston","avatar":""},{"name":"Aki Aleong","avatar":""},{"name":"Charlotte Peters","avatar":""},{"name":"Darren Shahlavi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324450);
