INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-cool-scoobydoo-phan-1', 'Be Cool, Scooby-Doo! (Phần 1)', 'Be Cool, Scooby-Doo! (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/3399f7c6baf0b035574d51600dce3aaa.jpg', 'https://phimimg.com/upload/vod/20231219-1/04675c7785d811bd33f13a838e88b48d.jpg', '<p>Cả nhóm quyết định đi du lịch trong Cỗ máy bí ẩn, tìm kiếm niềm vui và cuộc phiêu lưu trong thời gian có thể là kỳ nghỉ hè cuối cùng của họ cùng nhau. Tuy nhiên, những con quái vật tàn phá dường như bị thu hút bởi họ, xuất hiện gần như mọi điểm dừng trên đường đi.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Lillard","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Frank Welker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
