INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-lang-ma', 'Ngôi Làng Ma', 'The Black Death', 'https://phimimg.com/upload/vod/20231230-1/04f26051c9623c025caa6a114594addd.jpg', 'https://phimimg.com/upload/vod/20231230-1/35a11cb73778351ce0208288631909ec.jpg', '<p>Các biên niên sử và tài liệu lưu trữ đã ghi nhận rằng vào năm 1586 , vua Bayinnaung dẫn quân của mình thông qua các eo biển Malamao ở tỉnh Tak xâm lược Ayutthaya . Sau trận chiến dài liên tục, Ayutthaya đã thua trong cuộc chiến với quân đội Miến Điện từ Hongsawadi năm 1569. Sự sụp đổ của Vương quốc Ayutthaya không thể giải thích ...</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chaat Arthachinta","avatar":""},{"name":"Apa Bhavilai","avatar":""},{"name":"Narucha Chaimareung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
