INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-uoc-hien-dai', 'Tân Ước Hiện Đại', 'The Brand New Testament', 'https://phimimg.com/upload/vod/20231219-1/39fe3d061c8563b65816694d6c6cfbab.jpg', 'https://phimimg.com/upload/vod/20231219-1/f564fabb2a2903852485e906f663288a.jpg', '<p>Chúa sống ở Brussels. Tuy nhiên, trên Trái đất, Chúa là một kẻ hèn nhát, có đạo đức thảm hại và đáng ghét với gia đình của mình. Con gái của ông, Ea, cảm thấy buồn chán khi ở nhà và không thể chịu được việc bị nhốt trong một căn hộ nhỏ ở Brussels bình thường, cho đến ngày cô quyết định nổi dậy chống lại cha mình...</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Pili Groyne","avatar":""},{"name":"Benoît Poelvoorde","avatar":""},{"name":"Yolande Moreau","avatar":""},{"name":"Catherine Deneuve","avatar":""},{"name":"François Damiens","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
