INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-tinh-yeu', 'Đảo Tình Yêu', 'Palm Trees In The Snow', 'https://phimimg.com/upload/vod/20231219-1/95546a253acab503495d9a40edf8c88a.jpg', 'https://phimimg.com/upload/vod/20231219-1/b8bd18ad38dbe906f5812bacf4f5ef7d.jpg', '<p>Phim Đảo Tình Yêu - Palm Trees In The Snow 2015: Trong những kỷ vật của bố để lại, Clarence tình cờ khám phá ra một mẩu thư. Những dòng chữ viết tay trong mẩu thư tìm thấy này thôi thúc cô quyết định thực hiện chuyến hành trình đến Châu Phi, đảo Guana nơi mà người cha quá cố Jacobo và chú Kilian của cô đã dành trọn tuổi trẻ của họ ở nơi đây. Lần theo bức thư Fernando Poo - hòn đảo nhỏ hiện ra với cây cối xinh tươi và thiên nhiên xinh đẹp và quyến rũ nhưng cũng đầy thách thức. Trên con đường tìm hiểu về những câu chuyện cổ xưa của cha và chú của mình, Clarence vô tình gặp một người phụ nữ da màu, người đã dẫn cô đến câu chuyện tình yêu đẹp nhưng cũng đầy trái ngang trái trong thời kỳ thuộc địa Tây Ban Nha.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Mario Casas","avatar":""},{"name":"Adriana Ugarte","avatar":""},{"name":"Macarena García","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
