INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bao-ve-hon-nhan', 'Cuộc Chiến Bảo Vệ Hôn Nhân', 'Chaotic Wedding', 'https://phimimg.com/upload/vod/20240118-1/6071e6b28d2337c87b26aae554fa2b18.jpg', 'https://phimimg.com/upload/vod/20240118-1/845b93f610fa67f078086eee9cfe62b7.jpg', '<p>Lý Mai, Lan Tâm, Dương Đan là 3 bạn cùng đại học, hôn nhân của họ đều có nguy cơ tan vỡ. Đan ly dị và tập trung vào công ty, nên công ty phát triển rực rỡ. Hai người bạn cũng nghĩ đến ly dị nhưng 2 ông chồng của họ thì không muốn. Họ cố gắng mọi cách, kể cả đảm đương nội trợ để cứu vãn cuộc hôn nhân.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Đồng Đại Vĩ","avatar":""},{"name":"Mã Y Lợi","avatar":""},{"name":"Huỳnh Lỗi","avatar":""},{"name":"Viên Lập","avatar":""},{"name":"Lưu Kim Sơn","avatar":""},{"name":"Vu Na","avatar":""},{"name":"Mạnh Quáng Mỹ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
