INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-la', 'Số Lạ', 'Private Number', 'https://phimimg.com/upload/vod/20231227-1/4bd07a1b1ac7a520649d88e791946492.jpg', 'https://phimimg.com/upload/vod/20231227-1/47a5c59a0a30fa1c4be2ac04e4d93905.jpg', '<p>Một loạt tin nhắn điện thoại bí ẩn và ảo ảnh ám ảnh một nhà văn trong khi anh ta đấu tranh để hoàn thành một cuốn tiểu thuyết. Khi chúng tăng cường độ, anh ta mất khả năng nắm bắt thực tế, cuối cùng bị ám ảnh bởi một bí ẩn cũ sẽ dẫn đến những tiết lộ kinh hoàng về cả anh ta và người vợ trung thành của anh ta.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Judd Nelson","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Hal Ozsan","avatar":""},{"name":"Nicholle Tom","avatar":""},{"name":"Ray Stoney","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
