INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-o-paris', 'Kỳ Nghỉ Ở Paris', 'Paris Holiday', 'https://phimimg.com/upload/vod/20231213-1/fe55a89c82ba61e852dd8f30388a54db.jpg', 'https://phimimg.com/upload/vod/20231213-1/d8ade9307ba45f8621666aefcfdaa4a2.jpg', '<p>Bộ phim kể về cô gái Đinh Hiểu Mẫn (Quách Thái Khiết) – một nữ họa sĩ đến du học ở Paris ngay trước ngày kết hôn bị người yêu – một nhà điêu khắc thành danh Từ Huy (Từ Chính Hy) vứt bỏ, đột nhiên trở thành cô gái với ba “thất”: thất tình, thất hôn và thất nghiệp. Vì cú sốc đó, cô trở nên điên điên khùng khùng, không còn tin vào tình yêu, tóc tai bù xù, hành động không bình thường. Lâm Tuấn Kiệt (Cổ Thiên Lạc) là một người đàn ông ôn nhu nhưng lại bị bạn gái Triệu Vũ Tinh (Lưu Tử Nghiên) chia tay do cô là một người cuồng công việc. Anh đến Paris để giải sầu nhưng bị Hiểu Mẫn tưởng nhầm là gay nên đã cho anh sống chung nhà.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Aline Capella","avatar":""},{"name":"Cổ Thiên Nhạc","avatar":""},{"name":"Amber Kuo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
