INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-quai-da-vang', 'Tiểu Quái Da Vàng', 'Minions', 'https://phimimg.com/upload/vod/20231213-1/e20433772126d4bc7ae4ea070e1a65a9.jpg', 'https://phimimg.com/upload/vod/20231213-1/491c4e0245d305f360870b28bad1fb6d.jpg', '<p>Minions là bộ phim hoạt hình hài Mỹ 2015 của Kyle Balda, Pierre Coffin. Bộ phim đưa ta quay về thưở khai thiên lập địa, khi ấy Minion đã tồn tại. Chúng luôn phục tùng cho những kẻ tàn ác nhất nhưng họ cũng lần lượt ra đi. Vì ko còn ai để phụng sự, Minion tên Kevin đã cùng Stuart và Bob ra đi khám phá thế giới và tìm kiếm chủ nhân tàn ác cho mình. Và chúng đã tìm ra Scarlet Overkill - nữ siêu ác nhân đầu tiên nhân loại. Rồi chuyện gì sẽ xảy ra tiếp theo? Trái đất sẽ như thế nào?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Renaud","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Sandra Bullock","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324450);
