INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boruto-naruto-the-movie', 'Boruto: Naruto The Movie', 'Boruto: Naruto The Movie', 'https://phimimg.com/upload/vod/20231213-1/750bbebb9442a6819e34143deb2dc8e5.jpg', 'https://phimimg.com/upload/vod/20231213-1/b307b73fa90fb62c252b019290c6e6e8.jpg', '<p>Boruto Uzumaki là con trai của Naruto Uzumaki, hokage thứ bảy của ngôi làng lá ẩn. Đã nghe những câu chuyện về những việc làm của Naruto là một anh hùng, Boruto muốn vượt qua cha mình. Sau khi Sarada Uchiha, Boruto gặp bạn của cha mình, Sasuke Uchiha và yêu cầu được huấn luyện bởi anh ta.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
