INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-cua-ban', 'Những Người Bạn Của Bạn', 'We Are Your Friends', 'https://phimimg.com/upload/vod/20231213-1/57b5dddd64340e3b8835854239b4c0c8.jpg', 'https://phimimg.com/upload/vod/20231213-1/bc00869853283f1a3527100c903b4b92.jpg', '<p>Phim Những Người Bạn Của Bạn - We Are Your Friends 2015 lấy bối cảnh trong thế giới âm nhạc EDM và Hollywood về đêm. Phim xoay quanh Cole (Zac Efron), một DJ đầy tham vọng. Anh dành cả ngày của mình bên những bạn bè thời thơ ấu, trong khi ban đêm trở thành một DJ với những bản nhạc như có lửa. Tuy nhiên, mọi điều bắt đầu thay đổi khi anh gặp một DJ tên là James (Wes Bentley) và nhanh chóng trở thành học trò của anh. Nhưng mọi thứ bỗng trở nên phức tạp khi Cole bắt đầu nảy sinh tình cảm với cô bạn gái trẻ trung Sophie (Emily Ratajkowski) của nhà sản xuất James. Với mối quan hệ bị cấm và tình bạn thân thiết với người thầy của mình, Cole phải lựa chọn giữa tình yêu, lòng trung thành, và tương lai phát triển sự nghiệp DJ của anh.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Ratajkowski","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Jon Bernthal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
