INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('joy-nguoi-phu-nu-mang-ten-niem-vui', 'Joy – Người Phụ Nữ Mang Tên "Niềm Vui"', 'Joy', 'https://phimimg.com/upload/vod/20231213-1/2b932942216f48ed1bd6cc708f7457d5.jpg', 'https://phimimg.com/upload/vod/20231213-1/2a9574bde7ee68a422212128464f71c4.jpg', '<p>Phim Người Phụ Nữ Mang Tên Niềm Vui - Joy 2016: Có nội dung xoay quanh gia đình gồm 4 thế hệ và người mẹ đơn thân– Joy cùng ba đứa con. Đồng minh trở thành kẻ thù, kẻ thù trở thành đồng minh, một mình cô đã phải đương đầu với biết bao nỗi sợ hãi, sự phản bội và những “vết sẹo” trong tình yêu. Nhưng dường như không có gì có thể “quật ngã” được ý chí và tinh thần mãnh liệt của Joy, cô đã nhanh chóng biến công ty của mình thành “đế chế” tỷ đô dưới sự ghen ghét, đố kị của biết bao con người.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Robert De Niro","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
