INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-k-bi-mat-dao-hoang', 'Thám Tử K: Bí Mật Đảo Hoang', 'Detective K: Secret Of The Lost Island', 'null', 'https://phimimg.com/upload/vod/20231212-1/a3521866ac96ac02efd8f38d2fa5cddd.jpg', '<p>Năm 1795, năm mười chín triều vua Jeongjo, một lượng lớn bạc giả được trà trộn đưa vào lưu thông tạo ra mối đe dọa cho nền kinh tế. Thám tử Kim Min được giao nhiệm vụ điều tra thủ phạm đứng đằng sau sự việc và đã vô tình vén lên bức màn bí ẩn về hoạt động sản xuất bạc giả. Kim Min và người cộng sự Seo Pil đã theo đuổi đến cùng từ đất liền ra tới biển khơi và khám phá luôn cả bầu trời bao la để tìm ra manh mối cho vụ án.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Dal-su Oh","avatar":""},{"name":"Yeon-hee Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
