INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-cai-phan-9', 'Trạng Cãi (Phần 9)', 'Little Counselor (Season 9)', 'https://phimimg.com/upload/vod/20231219-1/4c1bac6562a5987618f045d67b89d65c.jpg', 'https://phimimg.com/upload/vod/20231219-1/530c3dbfb57ef359497d66e84d8ead3a.jpg', '<p>Người cố vấn nhỏ bé Shi Shi Ye lớn lên ở Thiệu Hưng, một thị trấn cổ ở phía nam sông Dương Tử. Dưới ảnh hưởng của văn hóa phương Đông và cha của ông, cố vấn cũ, cậu quyết định trở thành một cố vấn cho đất nước và nhân dân. Có những nghi phạm thường xuyên ở thành phố Thiệu Hưng, vì vậy Shi Ye và bạn bè của cậu đã bắt đầu một cuộc điều tra thú vị.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 8, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
