INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-ma-quai', 'Thị Trấn Ma Quái', 'Blackburn', 'https://phimimg.com/upload/vod/20231211-1/0ba097bec8dae16fa1595ff6e32445c3.jpg', 'https://phimimg.com/upload/vod/20231211-1/f95c40007d68b6ab2d1146d525b92f57.jpg', '<p>Một đám cháy rừng và lở đá bẫy năm người bạn đại học hay cãi nhau ở một thị trấn ma nhỏ ở Alaska với một lịch sử kinh hoàng. Khi họ tìm nơi ẩn náu bên trong đống đổ nát của Blackburn Asylum, họ phải chiến đấu để sống sót khi những cư dân giận dữ tàn sát từng người bạn một.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lochlyn Munro","avatar":""},{"name":"Emilie Ullerup","avatar":""},{"name":"Calum Worthy","avatar":""},{"name":"Ken Kirzinger","avatar":""},{"name":"Sarah Lind","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
