INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-song-con-2015', 'Cuộc Chiến Sống Còn', 'Battle For SkyArk', 'https://phimimg.com/upload/vod/20231211-1/b18ba5878dceb1cbcf8af591f128a77e.jpg', 'https://phimimg.com/upload/vod/20231211-1/b080dceeecb54763b3909985439b28de.jpg', '<p>Trong tương lai gần trái đất đã trở nên hoang vắng và nguy hiểm. Hiện là nơi sinh sống của một chủng tộc sinh vật bí ẩn, loài người buộc phải tìm nơi ẩn náu trong SkyArk, một thành phố nhân tạo trên bầu trời. Khi dân số tăng lên, không gian trở nên khan hiếm và chỉ những người giàu có và quyền lực mới có thể ở lại, đẩy những người nghèo và trẻ mồ côi của SkyArk đến trái đất bị bỏ hoang.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Garrett Coffey","avatar":""},{"name":"Caon Mortenson","avatar":""},{"name":"Riley Jane","avatar":""},{"name":"Taylor Coliee","avatar":""},{"name":"Luke Davis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324450);
