INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-qua-thang-nam', 'Đi Qua Tháng Năm', 'Les Aventures D''Anthony', 'https://phimimg.com/upload/vod/20231211-1/d7a4c0da5391a869c431e9d64241b4ee.jpg', 'https://phimimg.com/upload/vod/20231211-1/f94e7f3d75327ca2e7a9c9922275a472.jpg', '<p>Phim Đi Qua Năm Tháng 2015: Bộ phim kể về cuộc sống và những tình cảm nội tâm của một chàng trai trong giai đoạn từ năm cậu 20 đến 23 tuổi, từ lúc học đại học cho đến khi đi làm, từ trong nước chuyển ra nước ngoài. Anthony ( Lưu Sướng) là một chàng trai bình thường không có gì nổi trội, cũng không biết ăn nói. Năm 20 tuổi khi đang học đại học ở trường Melbourne Úc, cậu gặp được Tiểu Tuyên (Đường Nghệ Hân), Gia Minh (Bạch Cử Cương), Tiểu Hắc (Tống Vân Hoa), Pierre (Blues), bọn họ dần trở thành một nhóm bạn tốt. Năm tháng dài dằng dặc ấy đã viết nên những câu chuyện hoặc lãng mạn, ngọt ngào, hoặc hài hước hay lay động lòng người. Nhưng đồng thời, trong lòng Anthony vẫn luôn nhớ nhung về người con gái ở đất nước Nhật Bản xa xôi, Tiểu Anh (Bạch Bách Hà). Hai con người gặp lại nhau ở Tokyo sau hai năm cách biệt, rốt cuộc sẽ tạo nên một câu chuyện thế nào… Phim được chuyển thể từ tiểu thuyết bán chạy cùng tên.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Sướng","avatar":""},{"name":"Bạch Bách Hà","avatar":""},{"name":"Đường Nghệ Hân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324450);
