INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dua-xe-dap-huyen-thoai', 'Tay Đua Xe Đạp Huyền Thoại', 'The Program', 'https://phimimg.com/upload/vod/20231211-1/523710ff6225c6ca8a425404b4b9c33f.jpg', 'https://phimimg.com/upload/vod/20231211-1/036b72481e943696959019d1b39e574a.jpg', '<p>Một nhà báo thể thao người Ireland tin rằng màn trình diễn của Lance Armstrong trong các chiến thắng tại Tour de France được thúc đẩy bởi chất cấm. Với niềm tin này, anh ta bắt đầu săn lùng bằng chứng sẽ vạch trần Armstrong.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Foster","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Guillaume Canet","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Jesse Plemons","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
