INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dut-diem', 'Dứt Điểm', 'Taken 3', 'https://phimimg.com/upload/vod/20231211-1/d4a39201c5d027467006d8a35b47b943.jpg', 'https://phimimg.com/upload/vod/20231211-1/a1a6806b5ef7b15322ea4a371cb4e85d.jpg', '<p>Taken 3 là bộ phim hành động tội phạm Pháp 2015 của đạo diễn Olivier Megaton. Bộ phim được mở màn bằng sự hạnh phúc ấm cúng của gia đình nhà Bryan Mills (Liam Neeson), một đặc vụ siêu hạng. Nhưng hạnh phúc ngắn ngủi, có kẻ đã sát hại người vợ mà anh yêu quí, đe doạ tính mạng đứa con gái duy nhất và gắn tội cho anh. Anh đã bất chấp tất cả, chống lại FBI, vận dụng các kỹ năng đặc biệt của anh để bảo vệ con gái, tìm ra kẻ đứng sau tất cả mọi chuyện và đòi lại công lý cho mình.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Maggie Grace","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
