INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre', 'Tuổi Trẻ', 'Youth', 'https://phimimg.com/upload/vod/20231211-1/45c0230425fc804889a9076e73636313.jpg', 'https://phimimg.com/upload/vod/20231211-1/d84195bc909bf99e74ee5352e7026251.jpg', '<p>Fred và Mick, hai người bạn cũ, đang đi nghỉ trong một khách sạn thanh lịch dưới chân dãy Alps. Fred, một nhà soạn nhạc và dây dẫn, hiện đã nghỉ hưu. Mick, một giám đốc phim, vẫn đang làm việc. Họ nhìn với sự tò mò và sự dịu dàng đối với cuộc sống bối rối của con cái họ, các nhà văn trẻ nhiệt tình của Mick và khách sạn khác. Trong khi Mick Scrambled để hoàn thành kịch bản cho những gì anh tưởng tượng sẽ là bộ phim quan trọng cuối cùng của anh, Fred không có ý định nối lại sự nghiệp âm nhạc của mình. Nhưng ai đó muốn có tất cả các chi phí để nghe anh ta lại tiến hành.</p>', 'Full', 1, 'single', 'completed', 29, 2015, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324450);
