INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-hoan-hao', 'Chàng Trai Hoàn Hảo', 'The Perfect Guy', 'https://phimimg.com/upload/vod/20231212-1/b093a9bed2eb523418fbe98646a44c92.jpg', 'https://phimimg.com/upload/vod/20231212-1/15e36a71b036ff1dc4312677b2cf6f9a.jpg', '<p>Chàng Trai Hoàn Hảo - The Perfect Guy (2015):The Guy Perfect (2015) kể lại câu chuyện về Leah Vaughn xuất hiện để có cuộc sống lý tưởng Cô thích một thách thức, nhịp độ nhanh sự nghiệp của một vận động hành lang;.. Dave, bạn trai lâu dài cô yêu cô nhưng, tại số 36, cô đã sẵn sàng để di chuyển đến giai đoạn tiếp theo. Hôn nhân và gia đình dường như là một bước đi hợp lý và hoan nghênh. Dave là không chắc chắn như vậy. một ám ảnh sợ chút cam kết, mối nghi ngại của mình dẫn đến một break đau lên. Gặp Carter Duncan, một đẹp trai, người lạ quyến rũ mà con đường tiếp tục lai với Leah. Chăm sóc và lo lắng của Leah và gia đình và bạn bè của cô, mối quan hệ của họ tiến hành nhanh chóng. có vẻ như Leah đã gặp các chàng trai hoàn hảo. Mọi chuyện được tiếp diễn tại đây</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Ealy","avatar":""},{"name":"Sanaa Lathan","avatar":""},{"name":"Morris Chestnut","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
