INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-benh-quai-ac-2', 'Căn Bệnh Quái Ác 2', 'Contracted: Phase II', 'https://phimimg.com/upload/vod/20231212-1/2120d708ac66ea87de497b8d311b6e72.jpg', 'https://phimimg.com/upload/vod/20231212-1/2724f5e71e800337cb5a875c6e864299.jpg', '<p>Bắt đầu trực tiếp từ phần phim trước, câu chuyện kể về Riley, một trong những người cuối cùng tiếp xúc với Samantha, khi anh cố gắng truy tìm những kẻ chịu trách nhiệm cho đợt bùng phát trước khi căn bệnh rất dễ lây lan không chỉ ăn mòn cơ thể anh mà còn thế giới như chúng ta biết.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Mercer","avatar":""},{"name":"Marianna Palka","avatar":""},{"name":"Morgan Peter Brown","avatar":""},{"name":"Anna Lore","avatar":""},{"name":"Laurel Vail","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
