INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ana-maria-trong-phim', 'Ana Maria Trong Phim', 'Ana Maria In Novela Land', 'https://phimimg.com/upload/vod/20231212-1/4cb7a2144ee7aea74d517c932792a9fa.jpg', 'https://phimimg.com/upload/vod/20231212-1/c9b09598729f07b3d12a286de5ec0760.jpg', '<p>Ana Maria đang có một ngày tồi tệ cho đến khi cô đổi chỗ cho nhân vật chính của bộ phim truyền hình yêu thích của mình một cách kỳ diệu. Khi cố gắng trốn thoát khỏi Novela Land, Ana Maria cuối cùng cũng hiểu tại sao cuộc sống thực của cô lại hỗn độn như vậy.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edy Ganem","avatar":""},{"name":"Michael Steger","avatar":""},{"name":"Elizabeth Peña","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Juan Pablo Gamboa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
