INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-lac-dong-ho', 'Con Lắc Đồng Hồ', 'Furiko', 'https://phimimg.com/upload/vod/20231211-1/7e06e25d97d194a7ae019da96f77364f.jpg', 'https://phimimg.com/upload/vod/20231211-1/558cdd4920321d9fee0a4dc378022b57.jpg', '<p>Phim Con Lắc Đồng Hồ - Furiko 2015: Chuyển thể dựa trên bộ phim hoạt hình ngắn cùng tên của Tekken đạt giải thưởng nội dung tại liên hoan phim Tokyo năm 2012, bộ phim Furiko là quãng hành trình kéo dài từ lúc quen nhau đến lúc nhắm mắt xuôi tay có vui có buồn lẫn lộn xen lẫn hối hận day dứt của cặp đôi Daisuke và Saki. Đồng hồ treo tường quả lắc cũng giống như đôi vợ chồng vậy. Đồng tâm hợp lực cùng ghi lại những khoảng thời gian dài bên nhau, nếu con lắc bên phải bị hỏng, còn con lắc bên trái sẽ cố gắng lắc lư, con lắc bên phải bị kéo theo thì sẽ lắc trở lại. Chỉ cần một bên còn cố gắng thì đồng hồ sẽ không dừng lại...</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shidô Nakamura","avatar":""},{"name":"Manami Konishi","avatar":""},{"name":"Jurina Matsui","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324450);
