INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('denpa-kyoushi', 'Denpa Kyoushi', 'Denpa Kyoushi', 'https://phimimg.com/upload/vod/20231219-1/58e6b4d9751f18239680b1d10788d61d.jpg', 'https://phimimg.com/upload/vod/20231219-1/4d4039220a3be0517596111a5875c3a0.jpg', '<p>Một thiên tài vật lý với ước mơ chế tạo Cánh cửa thần kỳ của Doraemon... nay đã trở thành một NEET!? Và giờ đây anh phải trở thành giáo viên trung học theo lệnh của tiểu muội mình!? Không những thế còn vào cái trường toàn học sinh có vấn đề!? Rồi cái mạng anh liệu có được bảo toàn trước đám học sinh tinh nghịch... hay chính anh sẽ là người cải tạo bọn chúng!? Một giáo viên Otaku, liệu có thành công!?</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 16, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324450);
