INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thuy-chien-2015', 'Đại Thủy Chiến', 'Admiral', 'https://phimimg.com/upload/vod/20231211-1/c8e65fae18087a103070d278ed086980.jpg', 'https://phimimg.com/upload/vod/20231211-1/26c5069700fcfb2a027d4c9c2fbb36e1.jpg', '<p>Đây là câu chuyện về một tình yêu vĩ đại đối mặt với bi kịch vĩ đại nhất trong lịch sử nước Nga. Đô đốc Kolchak là một anh hùng chiến tranh thực thụ và là người chồng, người cha yêu dấu. Một ngày nọ, anh gặp Anna, tình yêu của đời anh và là vợ của người bạn thân nhất của anh. Cuộc cách mạng trong trái tim anh ấy phải đối mặt với cuộc cách mạng trên chính đất nước của anh ấy Định mệnh của anh ấy là trở thành Quy tắc tối cao của nước Nga.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Elizaveta Boyarskaya","avatar":""},{"name":"Sergei Bezrukov","avatar":""},{"name":"Anna Kovalchuk","avatar":""},{"name":"Egor Beroev","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
