INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-may-man-2015', 'Ngôi Sao May Mắn 2015', 'Lucky Star 2015', 'https://phimimg.com/upload/vod/20240104-1/83e0800893ff4bd4fd4a593c6c8236c6.jpg', 'https://phimimg.com/upload/vod/20240104-1/22caed812d43de478430c58d26226cfa.jpg', '<p>Tay quản lý nghệ sĩ định biến kẻ đóng giả Châu Tinh Trì thành sao, song mưu đồ của gã gặp trở ngại.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Tổ Lam","avatar":""},{"name":"Ôm Siêu","avatar":""},{"name":"Trần Gia Hoa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324450);
