INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-dale-earnhardt', 'Tôi Là Dale Earnhardt', 'I Am Dale Earnhardt', 'https://phimimg.com/upload/vod/20240104-1/a2f517e028d22a63ec7c6f930b9444c9.jpg', 'https://phimimg.com/upload/vod/20240104-1/a06a93a204bd52ab2d11fa9f1ffe83e1.jpg', '<p>I Am Dale Earnhardt đào sâu ngoài truyền thuyết để tiết lộ nhân vật phức tạp cốt lõi của The Intimidator. Anh ấy là thần tượng đối với hàng triệu người, nhưng lại là nhân vật phản diện đối với những người khác; một anh hùng của người lao động, nhưng cũng là một người con yêu của Đại lộ Madison; một người chồng, người cha và người bạn, nhưng cũng là một người đàn ông đơn độc mà ít người thực sự biết. Cái chết bi thảm của anh ở vòng đua cuối cùng của Daytona 500 năm 2001 đã gây ra làn sóng chấn động khắp cả nước và khiến anh bất tử như một trong những ngôi sao vĩ đại nhất mà NASCAR từng biết đến.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dale Earnhardt Jr.","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324450);
