INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-letter', 'Love Letter', 'Love Letter', 'https://phimimg.com/upload/vod/20240104-1/70df024f74078924f44bc5a9b8922769.jpg', 'https://phimimg.com/upload/vod/20240104-1/1ec17f3a100db07a1f3a71a817058574.jpg', '<p>Fiancé Itsuki của Hiroko Watanabe đã chết hai năm sớm hơn trong một tai nạn leo núi. Trong khi nhìn qua kỷ yếu trung học của mình, Hiroko trong một sự phù hợp của đau buồn quyết định viết thư cho anh ta bằng địa chỉ trường học cũ. Đáng ngạc nhiên là cô ấy nhận được một câu trả lời, không phải từ Itsuki chết, mà từ một người phụ nữ có cùng tên mà đã biết chồng chồng của Hiroko ở trường. Một mối quan hệ phát triển giữa hai người phụ nữ khi họ tiếp tục trao đổi thư và chia sẻ những kỷ niệm về người chết Itsuki.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
