INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-si-co-dong-gundam-thiet-huyet-co-nhi-phan-2', 'Chiến Sĩ Cơ Động Gundam: Thiết Huyết Cô Nhi (Phần 2)', 'Mobile Suit Gundam: Iron-Blooded Orphans (Season 2)', 'chiến sĩ cơ động gundam: thiết huyết cô nhi (phần 2) mobile suit gundam: iron-blooded orphans (season 2) kawanishi kengo hosoya yoshimasa hanae natsuki umehara yuichiro takumi yasuaki murata taishi amasaki kohei tamura mutsumi saito soma terasaki yuka kanemoto hisako sakurai takahiro matsukaze masaya okawa toru ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-bat-tan', 'Con Đường Bất Tận', 'The Longest Ride', 'https://phimimg.com/upload/vod/20231211-1/1bc09f2014a3122264a3537150f73144.jpg', 'https://phimimg.com/upload/vod/20231211-1/4964a74688511e48512b378980f87e5c.jpg', '<p>The Longest Ride là phim được chuyển thể từ tiểu thuyết của nhà văn Nicholas Sparks sau “Twilight”. Phim do George Tillman Jr làm đạo diễn, là câu chuyện lồng ghép hai mối tình của hai thế hệ. Đó là những tháng ngày cuồng nhiệt của đôi trẻ Luke – Sophia, đan xen với dòng hồi ức về hành trình tình yêu son sắt của người đàn ông 91 tuổi Ira với người vợ Ruth đã quá cố. Luke vốn là một chàng cao bồi trẻ hăng hái với những cuộc đua bò tót, còn Sophia là một sinh viên đại học đang bắt tay làm công việc mơ ước. Họ vô tình biết tới Ira khi ông gặp tai nạn xe hơi trên đường. Những lá thư và những hoài niệm của Ira về người vợ gắn bó qua hàng thập kỷ đã làm lay động đôi tình nhân trẻ, khiến họ hiểu thêm về tình yêu thực sự.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Eastwood","avatar":""},{"name":"Britt Robertson","avatar":""},{"name":"Lolita Davidovich","avatar":""},{"name":"Melissa Benoist","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Oona Chaplin","avatar":""},{"name":"Alan Alda","avatar":""},{"name":"Gloria Reuben","avatar":""},{"name":"Amy Parrish","avatar":""},{"name":"Elea Oberon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
