INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-hoa-si-truyen-tranh', 'Giấc Mơ Họa Sĩ Truyện Tranh', 'Bakuman Live-Action', 'https://phimimg.com/upload/vod/20231211-1/3b2c7b6c6b79109204977dfbcaad6e64.jpg', 'https://phimimg.com/upload/vod/20231211-1/006d4bf517aba1a375d3e6fcf58a8d1d.jpg', '<p>Phim Giấc Mơ Họa Sĩ Truyện Tranh - Bakuman Live-Action 2015: Moritaka Mashiro không muốn đi theo con đường của người chú là một họa sĩ manga, sau cùng chết vì kiệt sức. Cậu hình dung mình sẽ tốt nghiệp và làm việc tại văn phòng. Mọi thứ thay đổi khi cậu đem lòng yêu một cô gái trong trường. Cô gái đó, người mang hi vọng trở thành diễn viên lồng tiếng, nói với Moritaka rằng cô sẽ kết hôn với cậu, nhưng chỉ khi cả hai cùng đạt được ước mơ của mình. Moritaka sau đó kết hợp cùng người bạn cùng lớp Akito Takagi để xuất bản cuốn manga đầu của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeru Satoh","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Nana Komatsu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
