INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-da-hoi', 'Đêm Dạ Hội', 'Prom Ride', 'https://phimimg.com/upload/vod/20240102-1/fcbe79a1792840278c10aacb63544e06.jpg', 'https://phimimg.com/upload/vod/20240102-1/56cac8680f700d37da14655f249f2a50.jpg', '<p>Một nhóm học sinh trung học đang háo hức chuẩn bị cho bữa tiệc dạ hội cuối cấp . Thật không may cho họ khi gặp phải kẻ giết người tâm thần hung hăng. Đêm dạ hội hoành tráng không diễn ra như mong chờ mà mau chóng trở thành dạ hội đẫm máu… Không ai biết kẻ giết người hung hãn kia là ai. Họ bắt đầu nghi ngờ lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heather Paige Cohn","avatar":""},{"name":"Greg Gilardi","avatar":""},{"name":"Omar Gooding","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
