INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-amy-winehouse', 'Hành Trình Của Amy Winehouse', 'Amy', 'https://phimimg.com/upload/vod/20231211-1/fe955bf7c8bc572ba540c8ee2ee1fcc9.jpg', 'https://phimimg.com/upload/vod/20231211-1/ce1656511a1e627dcaabe751ac4034ab.jpg', '<p>Amy (nhan đề đầy đủ: Amy – The Girl Behind the Name) là phim tài liệu Anh mô tả về cuộc đời rực rỡ và sầu bi ca sĩ kiêm nhạc sĩ lừng danh Amy Winehouse. Tác phẩm của đạo diễn Asif Kapadia bắt đầu từ năm 1998 khi Winehouse 14 tuổi, tới khi cô bước vào âm nhạc, giành được thành công thương mại từ album đầu tay - Frank (2003), nổi danh toàn cầu khi ra mắt album bán chạy nhất thập kỷ ở Anh - Back to Black (2006).</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Amy Winehouse","avatar":""},{"name":"Mark Ronson","avatar":""},{"name":"Tony Bennett","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324450);
