INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-mat-tich-bi-an', 'Vụ Mất Tích Bí Ẩn', 'Open Heart', 'https://phimimg.com/upload/vod/20231219-1/cdbced0ece700f6756818f5093265624.jpg', 'https://phimimg.com/upload/vod/20231219-1/815c27e12c385e84c2778a81ae20b204.jpg', '<p>Vụ Mất Tích Bí Ẩn - Open Heart 2015 thuyết minh Trước sự mất tích của cha, cô bé 16 tuổi Dylan Blake gây gổ với một đám người, bị bắt giữ và bị tuyên án phải lao động công ích phục vụ cộng đồng tại Open Heart Memorial, bệnh viện nơi mẹ và chị cô làm bác sỹ, nơi ông bà cô là thành viên của hội đồng quản trị...và là nơi mà cha cô được nhìn thấy lần cuối cùng 1 người phụ nữ tóc vàng bí ẩn, trước khi ông biến mất.Gia đình Blake đang che dấu bí mật gì ?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2015, 'Thuyết Minh', 'HD', 'Canada', 0, '[{"name":"Tori Anderson","avatar":""},{"name":"Cristine Prosperi","avatar":""},{"name":"Justin Kelly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
