INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-nguy-hiem-3', 'Người Tình Nguy Hiểm 3', 'Hate Story 3', 'https://phimimg.com/upload/vod/20231231-1/e87c07f3cbd525cb939e359adddea48d.jpg', 'https://phimimg.com/upload/vod/20231231-1/5e950348614d7aadb0f8ec5e2821130f.jpg', '<p>Phim Người Tình Nguy Hiểm 3 - Hate Story 3 (2015): Câu chuyện về Aditya và Siya Singh, những người điều khiển công việc làm ăn của gia đình sau cái chết thương tâm của anh trai Aditya - Vikram. Một doanh nhân tên Saurav Singhania bỗng dưng xuất hiện trong cuộc đời họ. Saurav rất có nhã hứng với công ty của Aditya, trao cho họ lời đề nghị không thể tin được. Aditya và Siya cố gắng tìm hiểu ý định thực sự của Saurav. Cuộc trả thù tình ái đưa người xem qua mọi khung bậc của các mối quan hệ, yêu - căm ghét - báo thù.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sharman Joshi","avatar":""},{"name":"Zarine Khan","avatar":""},{"name":"Daisy Shah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324450);
