INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-cuoc-phieu-luu-den-nebulandia', 'Vua Hải Tặc: Cuộc Phiêu Lưu Đến Nebulandia', 'One Piece: Adventure Of Nebulandia', 'https://phimimg.com/upload/vod/20231231-1/844255fc9b9cf28f4af7aff00431d95c.jpg', 'https://phimimg.com/upload/vod/20231231-1/7d1df685530dad9f2a44f771a7e995e6.jpg', '<p>Vua Hải Tặc: Cuộc phiêu lưu đến Nebulandia là một chương trình truyền hình đặc biệt của anime One Piece. Phim được phát sóng vào ngày 19 tháng 12 năm 2015 do Uda Kounosuke làm đạo diễn. Trong tập phim đặc biệt lần này, nhóm Mũ Rơm sẽ phải chiến đấu với băng Hải Tặc Foxy tại Tân Thế Giới, ở một hòn đảo tên là Nebulandia - một hòn đảo có khả năng vô hiệu hóa sức mạnh của trái Ác Quỷ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
