INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-thang-tu', 'Cá Tháng Tư', 'April Fools', 'https://phimimg.com/upload/vod/20231231-1/8cedc13a90678dc4ff0bcdfa3f24e857.jpg', 'https://phimimg.com/upload/vod/20231231-1/a914c915cf5535114a1719c53a4d20ae.jpg', '<p>Phim April Fools 2015 là câu chuyện về&nbsp;Ayumi Nitta, một cô gái mắc chứng Anthropophobia (nhút nhát và sợ hãi giao tiếp với mọi người). Cô làm hộ lý vệ sinh cho tại bệnh viện. Một hôm, cô và bác sĩ phẫu thuật Wataru Makino (một người nghiện sex) tình một đêm với nhau. Sau đó Ayumi phát hiện mình có thai, chính là cái đêm hôm đó, nên đã nói với Wataru. Oái ăm thay, ngày cô nói cho Wataru biết chuyện về cái thai lại là ngày Cá tháng tư, thế là anh ấy xem đó như một lời nói dối trêu đùa.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Erika Toda","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Nanao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324450);
