INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cau-co', 'Bàn Cầu Cơ', 'Yểm Trừ', 'https://phimimg.com/upload/vod/20231231-1/285917c56507ecd0f291140e63c9ced3.jpg', 'https://phimimg.com/upload/vod/20231231-1/954bca65ce31a8b2311afba49d7588e0.jpg', '<p>Con trai một nhà trừ tà đã chơi Ouija mà không tuân theo các quy tắc, vô tình giải phóng 1 con quỷ. Để cứu con trai mình, nhà trừ quỷ đã đưa con trai mình đi khỏi nơi này cho đến khi con quỷ có thể bị tiêu diệt. Ba mươi năm sau, và sau khi ông qua đời, cháu trai ông tìm thấy trò chơi và lịch sử lặp lại...</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brittney Bertier","avatar":""},{"name":"J. Damian Anastasio","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
