INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-toi-ac', 'Âm Mưu Tội Ác', 'Siren Song', 'https://phimimg.com/upload/vod/20231231-1/27944005adcce4a9b612d120dde3c735.jpg', 'https://phimimg.com/upload/vod/20231231-1/9fe821a32be319585b489bcb7a165198.jpg', '<p>Hai anh chàng điển trai mong chờ cho một cuối tuần lãng mạn khi cô bạn gái hẹn hò trực tuyến của họ mời đến khách sạn trên một hòn đảo. Khi những vị khách khác bắt đầu biến mất, anh tin rằng cô ẩn giấu điều gì đó đáng sợ về bản thân và anh ta không thể tin vào BẤT CỨ AI trên đảo.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"C. Thomas Howell","avatar":""},{"name":"Matt Silver","avatar":""},{"name":"Rikke Leigh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324450);
