INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-vet-ky-la', 'Dấu Vết Kỳ Lạ', 'Infliction', 'https://phimimg.com/upload/vod/20231230-1/5d267950d0e6583da3b4201e1f36899a.jpg', 'https://phimimg.com/upload/vod/20231230-1/710e18189b54b73711d0e3931af87cbe.jpg', '<p>Tất cả mọi người đều nghĩ Nora bị mắc bệnh tâm thần khi luôn cho rằng mình là nạn nhân trong một vụ bắt cóc, tra tấn bởi nhóm người lạ mặt. Cô cũng tự nghĩ rằng mình điên, nhưng dấu vết lạ để lại trên người cô là thật và là bằng chứng duy nhất, nó không đủ thuyết phục cảnh sát, Nora quyết tự mình tìm kiếm ra sự thật đằng sau cuộc tấn công.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexandria Pascucci","avatar":""},{"name":"Melissa Pascucci","avatar":""},{"name":"Lou Pipon","avatar":""},{"name":"Mike Labbadia","avatar":""},{"name":"Alyson Abril","avatar":""},{"name":"Erick Moscoso","avatar":""},{"name":"Cecilia Na","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
