INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-paper', 'Thị Trấn Paper', 'Paper Towns', 'https://phimimg.com/upload/vod/20231211-1/3590819e90d03cb33a60341174eba168.jpg', 'https://phimimg.com/upload/vod/20231211-1/ea76bf67a9c6f0e30731b8aa42a00ab9.jpg', '<p>Bộ phim Thị Trấn Paper - Paper Towns, câu chuyện tình trong sáng của hai bệnh nhân ung thư đã cướp đi không ít nước mắt khán giả. Tác giả của cuốn sách - John Green - trong năm 2015 sẽ có một cuốn sách tình cảm khác được đưa lên màn ảnh là Paper Towns. Ra đời trước The Fault in Our Stars 4 năm, Paper Towns kể về chuyến đi của chàng thanh niên Quentin (Nat Wolff) cùng bốn người bạn để tìm lại cô gái hàng xóm bị mất tích... Nam chính Nat Wolff từng quen thuộc với khán giả qua vai chàng trai mù Issac trong The Fault in Our Stars, trong khi Cara Delevingne vào vai cô gái hàng xóm Margo.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cara Delevingne","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Halston Sage","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
