INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huy-ket-ban', 'Hủy Kết Bạn', 'Unfriended', 'https://phimimg.com/upload/vod/20231211-1/10eb541169848429e736d3eded8ec9c6.jpg', 'https://phimimg.com/upload/vod/20231211-1/7ac24ca6852203615bf5e2163fb309f2.jpg', '<p>Trong khi trò chuyện video vào một đêm, sáu người bạn trung học nhận được một tin nhắn Skype từ một người bạn cùng lớp, người đã tự sát một năm trước. Lúc đầu họ nghĩ rằng đó là một trò đùa, nhưng khi cô gái bắt đầu tiết lộ những bí mật đen tối nhất của bạn bè, họ nhận ra rằng họ đang phải đối mặt với một thứ gì đó ngoài thế giới này, một thứ muốn họ chết.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shelley Hennig","avatar":""},{"name":"Heather Sossaman","avatar":""},{"name":"Renee Olstead","avatar":""},{"name":"Matthew Bohrer","avatar":""},{"name":"Moses Storm","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
