INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau', 'Thám Tử Phố Tàu', 'Detective Chinatown', 'https://phimimg.com/upload/vod/20231208-1/594a338b499a5366de1887cce9145623.jpg', 'https://phimimg.com/upload/vod/20231208-1/a679276e82ae819dd7afd756604e4409.jpg', '<p>Đây là phiên bản truyền hình của bản điện ảnh Thám Tử Phố Tàu đạt kỳ tích 4,2 tỷ Nhân dân tệ! Thách thức giới hạn mới trong sản xuất phim truyền hình ~ Tại phố người Hoa kỳ lạ của đất nước Thái Lan, Lâm Mặc (từng là giáo viên dạy hóa) bắt tay với hoa khôi đáng yêu của giới cảnh sát cùng phá các vụ kì án ~ IVY - bà chủ tiệm hoa phản diện, A Ôn - ca sỹ chính tại quán bar, chiến đội ngũ đại linh đồng sẽ trình diễn những vụ án ly kì hóc búa như thế nào đây?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Khưu Trạch","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Vương Chân Nhi","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Trình Tiêu","avatar":""},{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Trương Thế","avatar":""},{"name":"Đặng Ân Hy","avatar":""},{"name":"Trần Vũ Tư","avatar":""},{"name":"Mã Bá Khiên","avatar":""},{"name":"Lý Minh Hiên","avatar":""},{"name":"崔雨鑫","avatar":""},{"name":"Gao Diệp","avatar":""},{"name":"Hoàng Khải Kiệt","avatar":""},{"name":"Đới Mặc","avatar":""},{"name":"Mã Dục Kha","avatar":""},{"name":"Trương Quốc Trụ","avatar":""},{"name":"Trương Duệ","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
