INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-pho-tau', 'Thám Tử Phố Tàu', 'Detective Chinatown', 'thám tử phố tàu detective chinatown khưu trạch trương quân ninh vương chân nhi trần triết viễn trình tiêu trương nghệ thượng trương tụng văn trương thế đặng ân hy trần vũ tư mã bá khiên lý minh hiên 崔雨鑫 gao diệp hoàng khải kiệt đới mặc mã dục kha trương quốc trụ trương duệ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-thoat', 'Tẩu Thoát', 'Tracers', 'https://phimimg.com/upload/vod/20231211-1/4497ff3648fe904dabe3fb3b41d24dc9.jpg', 'https://phimimg.com/upload/vod/20231211-1/6d03c433ca5b8722560ed65a69c595c3.jpg', '<p>Bộ phim kể về anh chàng đưa thư, Cam. Để kiếm tiền, Cam vô tình tham gia cùng một nhóm kẻ xấu đang khao khát tiền bạc và máu. Anh chàng hoảng hốt khi thấy chúng tổ chức cướp ngân hàng và bắt người làm con tin. Thậm chí khi phải đào thoát, chúng đã sẵn sàng ra tay giết người không gớm tay. Cam quyết định chạy trốn nhằm thoát khỏi băng nhóm tàn ác.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taylor Lautner","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Adam Rayner","avatar":""},{"name":"Rafi Gavron","avatar":""},{"name":"Sam Medina","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324450);
