INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('swat-unit-887', 'Swat: Unit 887', 'Swat: Unit 887', 'https://phimimg.com/upload/vod/20231211-1/e3616fad474b88ec9ca8cc06f8e967f9.jpg', 'https://phimimg.com/upload/vod/20231211-1/03c4bc61555a5005fd834eaaede58bb8.jpg', '<p>Một bộ phim kinh dị đầy hành động chạy đua với thời gian không ngừng nghỉ theo chân một Đội SWAT tinh nhuệ khi họ cố gắng ngăn chặn một tên khủng bố trong nước giết hại những con tin vô tội và phá hủy thành phố Los Angeles. Với 24 giờ còn lại trên đồng hồ, đội phải dựa vào bản năng và bộ kỹ năng độc đáo của mình để ngăn chặn cuộc tấn công và mang lại công lý.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Sizemore","avatar":""},{"name":"Mischa Barton","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Jeremy London","avatar":""},{"name":"Marlon Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324450);
