INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-cuoi-cung', 'Hiệp Sĩ Cuối Cùng', 'Last Knights', 'https://phimimg.com/upload/vod/20231211-1/a597b575f29ee28f2056e629158bf2df.jpg', 'https://phimimg.com/upload/vod/20231211-1/9e3d3f2131fe96b4e89fae66ae802bf7.jpg', '<p>Một chiến binh sa ngã mọc lên chống lại một người cai trị tham nhũng và tàn bạo để trả thù một bậc thầy bất lương của mình trong một cuộc phiêu lưu của sự sụp đổ của lòng trung thành, danh dự và báo thù.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324450);
