INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gate-luc-luong-tu-ve-ky-ao', 'GATE: Lực Lượng Tự Vệ Kỳ Ảo', 'Gate', 'gate: lực lượng tự vệ kỳ ảo gate suwabe junichi kanemoto hisako toyama nao taneda risa tomatsu haruka hikasa yoko uchida maaya yasumoto hiroki ishikawa kaito konishi katsuyuki koshimizu ami hidaka rina ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-cac-ong-trum', 'Cuộc Chiến Của Các Ông Trùm', '6 Ways To Sundown', 'null', 'https://phimimg.com/upload/vod/20231211-1/f025839321c3fd9e5ae7647604b40c1d.jpg', '<p>Cuộc Chiến Của Các Ông Trùm - 6 Ways To Sundown kể về Sundown”, tay buôn ma túy hàng đầu Bắc Mỹ chuyên phân phối cho các băng đảng Colombia. Ông đã tạo ra đường dây buôn lậu và sản xuất hiệu quả nhất kể từ thời đại của Cowboys Cocaine. John Doe là một người đàn ông bí ẩn, không rõ lai lịch. Tất cả chúng ta có thể biết về John Doe là ông muốn Sundown chết. Nhưng trước khi ông làm vậy, ông muốn làm cho Sundown cảm nhận điều mà anh đã phải trải qua, bị mọi điều mà ông phải chịu đựng và mất tất cả mọi thứ như ông đã mất. Để trả thù, John Doe thuê 6 người từ thế giới ngầm với những khả năng đặc biệt. Để thực hiện kế hoạch, John muốn tước đi 6 điều từ Sundown: tự do, tình yêu, danh tiếng, thứ quý giá nhất, tiền bạc và cuộc sống. Cuộc đời Sundown nhanh chóng chuyển từ đỉnh cao thành một địa ngục sống. Tài khoản ngân hàng bị sạch, vợ biến mất, lòng trung thành…</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Bai ling","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Dominique Swain","avatar":""},{"name":"Vivica A. Fox","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
