INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-bong-dem', 'Kẻ Săn Bóng Đêm', 'Keeper Of Darkness', 'https://phimimg.com/upload/vod/20231211-1/321a167d978e0a75a99bd0b6c0b57343.jpg', 'https://phimimg.com/upload/vod/20231211-1/14038c184baba5b1970e04aa7a9fa054.jpg', '<p>Loạt phim điện ảnh khủng bố, hãi hùng! Với con mắt âm dương của mình, từ nhỏ A Phát đã có thể nhìn thấy ma quỷ. Đang yên ổn sống cùng cô bạn gái của mình là một hồn ma thì tất cả đã hoàn toàn thay đổi kể từ khi anh gặp phải một con quỷ độc ác</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Sisley Choi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324451);
