INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-thieu-nu-cua-toi', 'Thời Đại Thiếu Nữ Của Tôi', 'Our Times', 'https://phimimg.com/upload/vod/20231211-1/ad5ab03613ff4c9471a1c4e624d833ba.jpg', 'https://phimimg.com/upload/vod/20231211-1/1eecbdcbc020297a910ea37e3c84b8f6.jpg', '<p>Phim Our Times 2015 nói về Lâm Chân Tâm, một cô nữ sinh cấp 3 bình thường, nhưng lại thích nam thần nổi tiếng nhất trường Âu Dương Phi Phàm . Một hôm, đang ở trường, cô nhận được 1 bức thư may mắn, nhưng cũng chính vì bức thư ấy mà không may quen với Từ Thái Vũ . Tuy nhiên, vì nghe được bí mật giữa người trong mộng Âu Dương Phi Phàm với hoa khôi của trường là Đào Mẫn Mẫn ; dưới sự ép buộc của tên côn đồ Từ Thái Vũ- người đã thầm thích Mẫn Mẫn từ lâu- cô phải cùng hắn tham gia “liên minh chiến tuyến thất tình”, thề sẽ làm cho 2 người kia phải chia tay, coi như giúp nhau theo đuổi người trong mộng.Một kẻ thất bại thấp kém làm sao có thể bên Bạch Mã Hoàng Tử?</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Trần Kiều Ân","avatar":""},{"name":"Ngôn Thừa Húc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
