INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-an-thit-nguoi', 'Tộc Ăn Thịt Người', 'Bone Tomahawk', 'https://phimimg.com/upload/vod/20231211-1/77acb82a082b9fa722489612dd84f9b2.jpg', 'https://phimimg.com/upload/vod/20231211-1/cf1600681b8897d05a4386dfb87bc1fd.jpg', '<p>Sau một cách ngoài vòng pháp luật vô tình dẫn dắt một nhóm troglodytes cannibalistic vào thị trấn Western Western hòa bình, những con quái vật bắt cóc một số người định cư, bao gồm cả vợ của một người chăn nuôi địa phương. Mặc dù có chân bị thương, người chăn nuôi đã tham gia một bữa tiệc cứu hộ nhỏ với Cảnh sát trưởng, Phó già của anh ta và một kẻ bắn súng mạnh mẽ. Những gì sau đây là một hành trình vào địa ngục trên trái đất khi tư thế đến nhận ra nó đang chống lại một kẻ thù có sự man rợ biết không có giới hạn. Bộ phim diễn ra vào đầu thế kỷ quanh biên giới của những gì bây giờ Texas và New Mexico.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
