INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-ngam', 'Điệp Viên Ngầm', 'Spy Time', 'https://phimimg.com/upload/vod/20231211-1/da2763aaf49520d71a92df5fa5036dfb.jpg', 'https://phimimg.com/upload/vod/20231211-1/6aaca983807e11a26b1a7ef5ba45fec9.jpg', '<p>Phim Điệp Viên Ngầm - Spy Time (2015) nói về Adolfo, một gã cảnh vệ tuổi băm, đang có khoảng thời gian bết bát. Không những cô bạn gái cả đời chấm dứt tình cảm với hắn khiến hắn chẳng còn động lực sống mà hắn còn trở thành mục tiêu của ten sát nhân hàng loạt Vázquez vừa trốn khỏi nhà tù. Đồng thời, hắn phát hiện ra cha hắn, Anacleto, vốn chả phải nông dân mà là đặc vụ, người đã nhốt Vázquez vào trại đúng 30 năm về trước. Adolfo sẽ buộc phải hợp tác với ông già mình, người mà anh chán ngán nhất, để tồn tại và sống sót trước cuộc báo thù điên cuồng cũng như đem cô bạn gái trở về.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Theo James","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
