INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-2015', 'Lính Bắn Tỉa', 'American Sniper', 'https://phimimg.com/upload/vod/20231210-1/d95458b3cfc4ac4b2198f66bc0faac33.jpg', 'https://phimimg.com/upload/vod/20231210-1/bece11c37fb8ed7250d8e95bca95b536.jpg', '<p>American Sniper là một bộ phim điện ảnh hành động tâm lý xoay quanh cuộc đời của lính bắn tỉa Chris Kyle nổi tiếng có thực được đạo diễn Clint Eastwood lấy ý tưởng để làm bộ phim về cuộc đời của người đàn ông này. Đi sâu vào bộ phim sẽ cho chúng ta thấy Chris Kyle từng phục vụ tại biệt đội Hải Cẩu và từng chinh chiến trên nhiều mặt trận tại Iraq, thế nhưng với những chiến công lớn thì thời gian cũng làm lu mờ con người của Chris Kyle, anh được giải ngủ và bắt đầu trận chiến thứ 2 trong cuộc đời mình, một trận chiến để cố gắng hòa nhập với cuộc sống không bom đạn và khói bụi.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Luke Grimes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
