INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vi-anh-hung-cua-sanjay', 'Những Vị Anh Hùng Của Sanjay', 'Sanjay''s Super Team', 'https://phimimg.com/upload/vod/20231210-1/9a45cb9f88d4bce9d20d3f4e0b5105c4.jpg', 'https://phimimg.com/upload/vod/20231210-1/88d0017aaea4f47ccae45ef99712866a.jpg', '<p>Phim Những Vị Anh Hùng Của Sanjay - Sanjays Super Team 2015 xoay quanh một cậu bé người Ấn Độ với trí tưởng tượng vô cùng phong phú tên Sanjay. Lớn lên cùng sự phát triển của xã hội, Sanjay cảm thấy xa lạ, chán nản bởi những buổi cầu nguyện hay buộc phải ngồi thiền cùng gia đình. Thế nên một ngày, Sanjay đã biến những vị thần Hindu thành dàn siêu anh hùng cực ngầu trong thế giới riêng của cậu bé.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brent Schraff","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324451);
