INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bung-chay', 'Bùng Cháy', 'Burnt', 'https://phimimg.com/upload/vod/20231210-1/a78ebef84267cdc716f40aa131cb4724.jpg', 'https://phimimg.com/upload/vod/20231210-1/dc15e32202416e4a6d7ab6a9b239bd61.jpg', '<p>‘Burnt’ xoay quanh câu chuyện cuộc sống của đầu bếp thượng hạng – Adam Jones (Bradley Cooper), người từng đoạt 2 ngôi sao Michelin – thước đo quốc tế về tài năng của các đầu bếp. Nhưng vì mải “ngủ say trên chiến thắng”, kiêu căng, trụy lạc, đẩy mình vào con đường nghiện ngập thuốc phiện khiến cuộc sống lẫn sự nghiệp của Adam Jones xuống dốc. Để khôi phục danh tiếng, Adam đã rời bỏ Paris và đến với London với quyết tâm giành 3 sao Michelin. Tại nơi đây anh cũng tìm thấy tình yêu đích thực của đời mình – Helene.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Daniel Brühl","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
