INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('flying-colors', 'Flying Colors', 'Flying Colors', 'https://phimimg.com/upload/vod/20231209-1/7d9c393596c228557072accba3c6d7a1.jpg', 'https://phimimg.com/upload/vod/20231209-1/93701a2ce9dc1b4a57e5d22d929ea853.jpg', '<p>Sayaka Kudo là một gyaru, người mặc váy ngắn và nhuộm tóc cô gái tóc vàng. Mặc dù cô ấy là một học sinh trung học cao cấp năm thứ 2, cô ấy đang ngang hàng với học sinh tiểu học lớp 4. Cô thường xuyên chuyển từ trường học vì cô không thể kết bạn, và đã từng bị đình chỉ vì bị bắt với thuốc lá. Để chuẩn bị cho cô ấy cho kỳ thi tuyển sinh đại học, mẹ cô quyết định gửi cô đến Seiho Cram School. Tuy nhiên, khi đạo diễn trường, Yoshitaka Tsubota, hãy nghe về vấn đề học tập của Sayaka, ông làm cho nó thành tích cá nhân của mình để giúp cô ấy tham gia vào trường đại học của cô ấy, Đại học Keio, một trường đại học uy tín được coi là một trong những người khó vào Nhật Bản nhất . Sau khi cha cô dán nhãn một đầu không khí, Sayaka đã quyết tâm học tập chăm chỉ để chứng minh cha mình sai. Trong suốt các kỳ nghỉ hè trong năm thứ hai của cô thông qua các kỳ thi vào cuối năm thứ ba ở trường trung học phổ thông, Sayaka nghiên cứu vô cùng khó khăn. Cô thậm chí còn loại bỏ thuốc nhuộm tóc vàng và cắt tóc của mình để thể hiện sự quyết tâm của mình. Kết quả của cô được cải thiện dần dần và giá trị độ lệch học thuật của cô tăng lên rất nhiều từ 30 đến 70 trong khoảng thời gian ngắn ngủi này.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324451);
