INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thac-loan-o-dai-bac', 'Thác Loạn Ở Đài Bắc', 'One Night In Taipei', 'https://phimimg.com/upload/vod/20231209-1/fbdc693f65b54995092b7fcfb0116b3b.jpg', 'https://phimimg.com/upload/vod/20231209-1/656d6528f38aadd03738e5c54cef1318.jpg', '<p>Một chàng trai độc thân quyết định cầu hôn bạn gái bằng chiếc nhẫn của mẹ mình chỉ để rồi chiếc nhẫn vô tình bị một cậu bé đánh rơi xuống rãnh nước. Anh trải nghiệm cuộc sống về đêm điên cuồng ở Đài Bắc và gặp gỡ nhiều cá nhân thú vị trong suốt nhiệm vụ lấy lại chiếc nhẫn.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kelvin Kwan","avatar":""},{"name":"Sophia Wang","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Riva Chang","avatar":""},{"name":"Sharon Hsu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
