INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-giam-dia-nguc', 'Nhà Giam Địa Ngục', 'Riot', 'https://phimimg.com/upload/vod/20231210-1/da4f6820f2ff26e6350da5393726a493.jpg', 'https://phimimg.com/upload/vod/20231210-1/39f3ce458c0ef1da6dca4a879e4139bd.jpg', '<p>Copper Jack Stone cố tình dàn dựng một vụ cướp ngân hàng để bị tống vào tù cùng với trùm khét tiếng người Nga Balam. Balam không chỉ là một tên tội phạm đông đảo; anh ta là một lãnh chúa rất xảo quyệt và nguy hiểm, người điều khiển lực lượng cảnh sát từ sau song sắt. Balam sống trong tù như một vỏ bọc cho quyền lực thực sự của mình, đó là Vua của thành phố. Phòng giam của anh ta là một căn phòng riêng xa hoa được xây dựng riêng cho anh ta, hầu hết không thể tiếp cận được ở độ sâu của cấu trúc nhà tù. Ngay cả quản giáo cũng sợ mạo hiểm vào khu vực của mình trong nhà tù. Tuy nhiên, ngay cả khi bị bao vây bởi những tay sai trung thành và lính canh trong pháo đài bị chia cắt của mình, Balam không biết Jack sẽ đến để trả thù cho gia đình anh ta, những người mà Balam đã sát hại trong máu lạnh. Balam cứng rắn... nhưng Jack còn cứng rắn hơn.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Reese","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Danielle C. Ryan","avatar":""},{"name":"Chuck Liddell","avatar":""},{"name":"Michael Flynn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324451);
