INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-toi-ac-2015', 'Vòng Xoáy Tội Ác', 'The Chronicles Of Evil', 'https://phimimg.com/upload/vod/20231210-1/f57d63198241d40cdb539fc5376e2ae9.jpg', 'https://phimimg.com/upload/vod/20231210-1/c7d7e630a4e6b0ccda7e97630ca4adeb.jpg', '<p>Sau buổi tiệc mừng vì được thăng chức với các đồng nghiệp, trên đường về nhà, đội trưởng đội điều tra Choi (Son Hyun Joo) vô tình gây tai nạn chết người. Anh quyết định che giấu tội lỗi của mình. Tuy nhiên, các cuộc điện thoại nặc danh liên tục đe dọa, không buông tha anh.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Park Seo-jun","avatar":""},{"name":"Daniel Choi","avatar":""},{"name":"Bae Jin-woong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324451);
