INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-toi-ben', 'Quẩy Tới Bến', 'Rock The Kasbah', 'https://phimimg.com/upload/vod/20231208-1/f3d3afb7ced92faa86077e1b0b05453c.jpg', 'https://phimimg.com/upload/vod/20231208-1/5c23d603b496c299dd85d0d3b3789e53.jpg', '<p>Quẩy Tới Bến - Rock the Kasbah kể về bầu sô Richie Vance (Bill Murray) sắp hết thời, muốn cứu vãn sự nghiệp bằng tour diễn với cô ca sĩ trẻ Ronnie (Zooey Deschanel) tại Afghanistan. Tuy nhiên, khi vừa đặt chân đến đây, Richie đã bị nữ ca sĩ cuỗm tất cả tiền bạc, hộ chiếu và trở thành kẻ tay trắng. Nhưng trong cái rủi có cái may, chính vì vậy mà Richie gặp cô gái trẻ Salima với giọng hát truyền cảm và quyến rũ. Từ đó, Richie cố gắng giúp cô gái có giọng hát phi thường chiến thắng cuộc thi Afghan Star, tương tự với American Idol.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Hudson","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Kelly Lynch","avatar":""},{"name":"Leem Lubany","avatar":""},{"name":"Zooey Deschanel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
