INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-bi-mat', 'Hôn Nhân Bí Mật', 'Shanai Marriage Honey Live Action', 'https://phimimg.com/upload/vod/20231207-1/d7b56f065e34d955f39683441a35be57.jpg', 'https://phimimg.com/upload/vod/20231207-1/8b984e263f4e0ef9d1ec1895a37f96c3.jpg', '<p>Triệu Tiểu Lượng là một người đàn ông hài hước và có một cô bạn gái cá tính tên là Phan Vân. Khi sự nghiệp của Tiểu Lượng gặp nhiều trắc trở, Phan Vân gợi ý rằng hai người kết hôn. Sau khi kết hôn,Tiểu Lượng có cơ hội làm việc tại công ty của Phan Vân. Để không ảnh hưởng tới công việc, hai người quyết định giấu mối quan hệ của mình và cùng nhau cố gắng làm việc chăm chỉ. Tuy nhiên mối quan hệ bí mật khiến cho tình yêu rơi vào khủng hoảng. Dù rất yêu nhau, họ không muốn làm lỡ cơ hội thăng tiến trong công việc. Làm thế nào để chọn giữa gia đình và công việc?</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 19, 2015, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Triệu Huy","avatar":""},{"name":"Mã Y Lợi","avatar":""},{"name":"Trương Khả Di","avatar":""},{"name":"Mikan Ryu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
