INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ba-diep-vien', 'Quý Bà Điệp Viên', 'Spy 2015', 'https://phimimg.com/upload/vod/20231208-1/1c2ef0d5e09aa78eb69045ee7be86f35.jpg', 'https://phimimg.com/upload/vod/20231208-1/749b3d14c72b9a56143ed3b577d7cce3.jpg', '<p>Điệp Viên 2015 - Spy nói về nữ nhân viên phân tích Susan Cooper của CIA. Cô không có ngoại hình đẹp, không giỏi tiếp xúc với đàn ông và suốt ngày gắn bó với công việc bàn giấy nhàm chán, hài lòng với vai trò một người hùng thầm lặng đằng sau những chiến dịch nguy hiểm. Nhưng mọi việc nhanh chóng thay đổi khi đồng đội của cô bị lộ và một điệp viên hàng đầu khác thì phản bội, Susan đã tình nguyện dấn thân vào chiến dịch bằng vỏ bọc đặc biệt rất khó bị nghi ngờ và phát hiện của cô. Nhiệm vụ của Susan là xâm nhập vào một đường dây mua bán vũ khí giết người đầy nguy hiểm và phá hủy nguy cơ của một thảm họa toàn cầu.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morena Baccarin","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Jason Statham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
