INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-dem-giang-sinh', 'Ác Mộng Đêm Giáng Sinh', 'Krampus', 'https://phimimg.com/upload/vod/20231208-1/b4a813205e73f42066afc72f28b717d5.jpg', 'https://phimimg.com/upload/vod/20231208-1/07c08f5cc3a31ef167c0d886fa7911d6.jpg', '<p>Phim Ác Mộng Đêm Giáng Sinh - Krampus 2015: Lâu nay, Giáng sinh luôn được xem là thời điểm ấm áp, hạnh phúc nhất trong năm khi các thành viên trong gia đình dù đi xa mấy cũng cố gắng trở về để quây quần, sum họp bên người thân. Tuy vậy, trái với truyền thống được ông già Noel tặng quà, ngày Giáng sinh có thể trở thành ác mộng nếu bị quỷ Krampus ghé thăm.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Scott","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Allison Tolman","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
