INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-thien-than-va-quy-du', 'Liên Minh Công Lý: Thiên Thần Và Quỷ Dữ', 'Justice League: Gods And Monsters', 'https://phimimg.com/upload/vod/20231208-1/ea6955f7535139563f9dbc1baca5d6a4.jpg', 'https://phimimg.com/upload/vod/20231208-1/853c7b5336f2e5ce94c9ff13f19a0cff.jpg', '<p>Bộ phim sẽ tập trung vào một thế giới song song nơi mà Batman, Superman và Wonder Woman trở nên xấu xa hơn so với những phiên bản trước của họ. Superman là con trai của tướng Zod, Wonder Woman là một New God còn Batman là một ma cà rồng hút máu những kẻ phạm tội. Câu truyện sẽ tập trung vào việc bộ 3 này bị vướng vào các vụ sát nhân hàng loạt, phải đối mặt với áp lực quần chúng, cũng như kẻ vô hình đứng đằng sau những vụ sát nhân kia...</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benjamin Bratt","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Tamara Taylor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
