INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-ma-nha-ho-vuong', 'Con Ma Nhà Họ Vương', 'Never Trust a Stranger', 'https://phimimg.com/upload/vod/20231210-1/669b7a7e598bf798875b669e96ad6649.jpg', 'https://phimimg.com/upload/vod/20231210-1/ce905b287e665a288a96d1b9a657571e.jpg', '<p>Nhân vật chính của phim là Nam (La Quốc Hùng). Anh ta đem lòng yêu anh bạn thân là Khánh (Tiến Vũ), nhưng Khánh lại yêu một cô gái khác (Minh Hằng). Sau một lần không kiềm chế được bản thân, Nam gây án và phải trốn lên thành phố. Bỗng nhiên anh nhận một lời đề nghị béo bở từ thiếu gia Huy (Hồ Vĩnh Khoa), theo đó Nam phải tham gia một trò chơi bệnh hoạn suốt đêm cùng Huy, đổi lại anh sẽ có 200 triệu nếu chịu đựng được đến khi trời sáng.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"La Quốc Hùng","avatar":""},{"name":"Hồ Vĩnh Khoa","avatar":""},{"name":"Diệp Lâm Anh","avatar":""},{"name":"Lương Mạnh Hải","avatar":""},{"name":"Minh Hằng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
