INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hieu-truong-va-nam-dua-be', 'Cô Hiệu Trưởng Và Năm Đứa Bé', 'Little Big Master', 'https://phimimg.com/upload/vod/20231208-1/0fc319b0f3712c8a30cba5a8e1ebc0fe.jpg', 'https://phimimg.com/upload/vod/20231208-1/0b67197d026664d32b1535c86da71a04.jpg', '<p>Phim Cô Hiệu Trưởng Và Năm Đứa Bé - Little Big Master dựa trên một câu chuyện có thật khi các trường học bị buộc đóng cửa bởi vấn đề dân số già của Hong Kong. Trước hoàn cảnh đó, một nữ hiệu trưởng nhiệt tình, luôn tuân thủ nguyên tắc và đức tin vẫn cố hết sức để điều hành một trường mẫu giáo cho những đứa trẻ kém may mắn, bất kể mức lương thấp và nhiều khó khăn. Cuối cùng, sự hy sinh của cô đã khiến nhiều người cảm động và giành được sự tôn trọng của mọi người.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Dương Thiên","avatar":""},{"name":"Ngô Diệu Hán","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
