INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grisaia-no-rakuen', 'Grisaia no Rakuen', 'Grisaia no Rakuen', 'https://phimimg.com/upload/vod/20231207-1/36f43ebb46f7875d78c0a45be64052b8.jpg', 'https://phimimg.com/upload/vod/20231207-1/1e48a2a9a7af75b18df3a55c0c1a2008.jpg', '<p>Nối tiếp phần 1 : GRISAIA NO KAJITSU, phần 2 mang sẽ mang tên là : Grisaia no RakuenCâu chuyện xảy ra sau khi các sự kiện của Grisaia no Meikyuu. Kazami Yuuji đã bị giam giữ &nbsp;khi bị nghi ngờ có tham gia vào một tổ chức khủng bố quốc tế, cầm đầu là tên Heath Oslo, đã quản lý để nhập biên giới của Nhật Bản với một vũ khí mới tàn phá hủy diệt hàng loạt trong tay. Trong khi đó, tại học viện Mihama, các sinh viên còn lại tìm thấy chính mình với thời gian chạy ra ngoài do các vấn đề tài chính, các trường được thiết lập để đóng cửa trong tháng....</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 15, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324451);
