INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1944', '1944', '1944', 'https://phimimg.com/upload/vod/20231208-1/7b0b0871cc235ab39578882486702885.jpg', 'https://phimimg.com/upload/vod/20231208-1/297574ee23300846ba5a990434ebebcd.jpg', '<p>Các sự kiện của cuộc chiến năm 1944, từ Blue Hills đến Bán đảo Sõrve. Được thể hiện qua con mắt của những người lính Estonia phải chọn phe và chiến đấu chống lại những người anh em của mình. Sự lựa chọn phải được thực hiện, không chỉ bởi những người lính, mà còn bởi những người thân yêu của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kristjan Üksküla","avatar":""},{"name":"Kaspar Velberg","avatar":""},{"name":"Märt Pius","avatar":""},{"name":"Priit Pius","avatar":""},{"name":"Priit Strandberg","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
