INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-chuong-sabo-moi-lien-ket-cua-ba-anh-em-va-y-chi-duoc-ke-thua', 'Vua Hải Tặc: Chương Sabo - Mối Liên Kết Của Ba Anh Em Và ý Chí Được Kế Thừa', 'One Piece: Episode Of Sabo - 3 Kyōdai No Kizuna Kiseki No Saikai To Uketsugareru Ishi, One Piece Sapo Special Chapter Three Brothers'' Bonds, Miracle Reunion And Inherited Will', 'https://phimimg.com/upload/vod/20231208-1/4256a7db00ebc9191b2ff0d2a954ec09.jpg', 'https://phimimg.com/upload/vod/20231208-1/8a2d77ad763363bb7b6b84080200e7fe.jpg', '<p>Vua Hải Tặc: Chương Sabo - Mối liên kết của ba anh em và ý chí được kế thừa là chương trình truyền hình đặc biệt của anime One Piece. Phim do Koga Gou làm đạo diễn và được phát sóng vào ngày 22 tháng 8 năm 2015, kể về các sự kiện trong ba phần đầu tiên của Dressrosa Arc theo quan điểm của Sabo. Bộ phim mô tả bức tranh thời thơ ấu của ba anh em Sabo, Luffy và Ace. Nói về ước mơ làm Hải tặc của bộ ba. Cuộc gặp gỡ với Luffy thông qua góc nhìn của Sabo.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324451);
