INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-long-bong', 'Tuổi Trẻ Lông Bông', 'This Is Me', 'https://phimimg.com/upload/vod/20231208-1/2ac94119d3af7b6e84c659a8b8c5b0f6.jpg', 'https://phimimg.com/upload/vod/20231208-1/e474254afab873565496d4034a1fccd2.jpg', '<p>Phim Tuổi Trẻ Lông Bông - This Is Me 2015: Một bộ phim về tuổi thanh xuân thời sinh viên đầy nghịch ngợm. Nội dung xoay quanh những ngày cuối cùng của nhóm bạn trong trường đại học và nhựng điều họ phải hoàn thành trước khi bước chân vào xã hội. Đó là câu chuyện về Anh Tử cô hoa khôi của trường phải tìm ra người thầm yêu mình trong 4 năm hay Chu Du luôn tìm cách khẳng định bản thân trước người cha đầy tài giỏi hay Tiểu Dư và người bạn đạo diễn của cậu ta. Tất cả họ đều có một khoảng thời gian đầy vui vẻ và có ý nghĩa để làm hành trang bước chân vào xã hội.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Nghiên Hy","avatar":""},{"name":"Trịnh Khải","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
