INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-dem-giang-sinh-2015', 'Ác Mộng Đêm Giáng Sinh', 'A Christmas Horror Story', 'https://phimimg.com/upload/vod/20231206-1/5288acc6a9aba568866d9339d481bc91.jpg', 'https://phimimg.com/upload/vod/20231206-1/4aded7ee9beee87272866c9edee2c849.jpg', '<p>Các học sinh trung học điều tra một vụ giết người bí ẩn xảy ra vào kỳ nghỉ lễ trước đó, một cặp vợ chồng nhận thấy cậu con trai nhỏ của họ đang hành động kỳ lạ sau chuyến đi rừng đầy tuyết để chặt cây truyền thống và một gia đình bị Krampus, ác quỷ Giáng sinh, theo dõi qua xứ sở thần tiên mùa đông. Trong khi đó ở Bắc Cực, ông già Noel đang chống lại lũ yêu tinh zombie.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Canada', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
