INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-dot-bien', 'Gấu Đột Biến', 'Unnatural', 'https://phimimg.com/upload/vod/20231205-1/901e7f8050783db0a99c322a5940a2be.jpg', 'https://phimimg.com/upload/vod/20231205-1/a8ac5b8068d798c529dbf797daa4336a.jpg', '<p>Phim Gấu Đột Biến - Unnatural 2015 kể về một nhóm các nhà khoa học cùng đến Alaska cho cuộc nghiên cứu mới nhất của họ. Nhưng họ không ngờ rằng ác mộng kinh hoàng đang chờ mình nơi tuyết trắng. Con người đang ngày một tàn phá thiên nhiên, gây ra những biến đổi khí hậu trên toàn cầu. Và cũng gián tiếp ảnh hưởng đến những loài động vật xung quanh, trong đó có những chú gấu Bắc Cực. Chúng đã dần biến thành những con gấu hung hãn, khát máu. Mắc kẹt trong tình thế tiến thoái lưỡng nan này, nhóm nhà khoa học buộc phải vào cuộc để tìm cách giải quyết trước khi sự đột biến lan rộng, nhưng đồng thời cũng phải tự bảo vệ tính mạng của bản thân trước sự hung tợn của bầy gấu hoang.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Remar","avatar":""},{"name":"Sherilyn Fenn","avatar":""},{"name":"Ron Carlson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
