INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-quy-phuc-ma-tuyet-yeu-ma-linh', 'Chung Quỳ Phục Ma: Tuyết Yêu Ma Linh', 'Zhong Kui: Snow Girl and the Dark Crystal', 'https://phimimg.com/upload/vod/20230917-1/aaf3f939aafb9f7c92be490b8cd6fae1.jpg', 'https://phimimg.com/upload/vod/20230917-1/33f119e8c6f5c4b11b97854dee02de89.jpg', '<p>Chung Quỳ Phục Ma: Tuyết Yêu Ma Linh – Zhongkui: Snow Girl And The Dark Crystal: Thành Hỗ Đô – một thành trấn biên giới phía Tây của Đường triều. Chung Quỳ – dưới sự chỉ bảo của Trương đạo tiên- đã trở thành trảm yêu sỹ, trấn thủ Hỗ Đô. Để bảo vệ bách tính khỏi sự xâm hại của yêu ma, Chung Quỳ đã thâm nhập vào ma giới, ăn trộm bảo hạp tích tụ năng lượng yêu ma, nhằm mục đích tận dụng cơ hội ngàn năm có một tiêu diệt ma giới, mang lại hòa bình vĩnh viễn cho nhân gian. Ma vương sai khiến các yêu quái đi đoạt lại bảo hạp. Chung Quỳ một thân tràn đầy chính khi, trong quá trình giao đấu với yêu ma mới phát hiện cái ranh giới giữa người và yêu ma tưởng chừng rất rõ ràng kia thực ra phức tạp hơn so với trong tưởng tượng rất nhiều, lại thêm cuộc tình không nên có với Tuyết yêu khiến Chung Quỳ càng thêm hoài nghi ý nghĩa sự tồn tại của mình. Trải qua vô số lần đụng độ với ma giới, Chung Quỳ dần phát giác bản thân mình đã rơi vào một âm mưu lớn …</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Kun","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Summer Jike","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Yang Zishan","avatar":""},{"name":"Huang Huan","avatar":""},{"name":"Luo Wenbo","avatar":""},{"name":"Hou Yidi","avatar":""},{"name":"Peter Pau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172