INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bahubali-the-beginning', 'Bahubali: The Beginning', 'Bāhubali: The Beginning', 'https://phimimg.com/upload/vod/20231204-1/b7c45f161fcb7338577466912f5c8e5d.jpg', 'https://phimimg.com/upload/vod/20231204-1/cdd5c4943d63f7c6f9e37b1112128a14.jpg', '<p>Cậu bé Shivudu bị mẹ bỏ lại như một đứa trẻ trong một ngôi làng nhỏ. Khi anh ấy lớn lên, rõ ràng là anh ấy sở hữu những món quà đặc biệt. Anh gặp công chúa chiến binh xinh đẹp Avanthika và biết rằng nữ hoàng của cô đã bị giam cầm trong 25 năm qua. Shividu lên đường giải cứu cô ấy, đồng thời khám phá ra nguồn gốc của chính mình trong quá trình này.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Rana Daggubati","avatar":""},{"name":"Tamanna Bhatia","avatar":""},{"name":"Anushka Shetty","avatar":""},{"name":"Ramya Krishnan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
