INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-nhan-cua-frankenstein', 'Quái Nhân Của Frankenstein', 'Victor Frankenstein', 'https://phimimg.com/upload/vod/20231203-1/1578e7419683b9c1e5fe6c3b8d44cad0.jpg', 'https://phimimg.com/upload/vod/20231203-1/cebd4de43d694f7fd5ed0602534225af.jpg', '<p>Nói theo quan điểm của Igor, chúng ta thấy nguồn gốc tối trợ trẻ gặp khó khăn, tình bạn cứu độ của Ngài với các sinh viên y khoa trẻ Viktor Von Frankenstein, và trở thành những người chứng kiến sự xuất hiện của cách Frankenstein đã trở thành người đàn ông - và các huyền thoại - chúng ta biết ngày nay.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Daniel Radcliffe","avatar":""},{"name":"Jessica Brown Findlay","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
