INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-phap-su-tuoi-teen', 'Hội Pháp Sư Tuổi Teen', 'Descendants', 'https://phimimg.com/upload/vod/20231203-1/e0a07f55cefb7d41726bc17831f2dbaa.jpg', 'https://phimimg.com/upload/vod/20231203-1/ec7102a7735de0c8d2c9af2c14c7f9fe.jpg', '<p>Descendants 2015 kể về một vương quốc bình dị ngày nay. Tại đây, chàng hoàng tử Ben, con trai nhân từ của vua Adam và nữ hoàng Belle, được vua cha nhường ngôi. Anh đã mang đến cơ hội chuộc lỗi cho con của một số nhân vật phản diện nổi tiếng nhất của Disney, cho phép họ vào học chung trường với con của những “người tốt”.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dove Cameron","avatar":""},{"name":"Cameron Boyce","avatar":""},{"name":"Booboo Stewart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
