INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-sau-anh-mat', 'Bí Mật Sau Ánh Mắt', 'Secret In Their Eyes', 'https://phimimg.com/upload/vod/20231203-1/b3a6a03d302c0e1355d9f2586e5354ad.jpg', 'https://phimimg.com/upload/vod/20231203-1/81b58710b0b012e5a0e78f5243a50524.jpg', '<p>Phim Bí Mật Sau Ánh Mắt - Secret in Their Eyes 2015: Julia Roberts vào vai Jess - một điều tra viên của FBI, cuộc sống của cô bị đảo lộn khi phát hiện ra xác một nạn nhân vứt trong thùng chứa rác chính là con gái mình. Đau đớn và tuyệt vọng, cô cùng người cộng sự là Ray (do nam diễn viên từng được đề cử Oscar trong 12 Years a Slave thủ vai) ráo riết điều tra với mong muốn đưa tên giết người ra ánh sáng nhưng hành trình truy tìm thủ phạm khó khăn và gian nan rất nhiều.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Julia Roberts","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
