INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-thu-dich', 'Ranh Giới Thù Địch', 'Hostile Border', 'https://phimimg.com/upload/vod/20231215-1/f35a89c131778d5dbaa0a0751af0a2bc.jpg', 'https://phimimg.com/upload/vod/20231215-1/4eb07e0a0bb9179ee6d9eb18ec592b54.jpg', '<p>Phim Ranh Giới Thù Địch - Hostile Border 2015: Lớn lên tại Mỹ, Claudia - 22 tuổi là một người nhập cư bất hợp pháp, sống với giấc mở trở thành công dân chính thức của Mỹ. Cô bị FBI bắt trong một lần dùng thẻ tín dụng giả, Claudia nhanh chóng bị trục xuất sang Mexico. Không biết nói tiếng Tây Ban Nha, mất gốc tiếng mẹ đẻ của mình, Claudia buộc lòng phải ở tạm một trang trại của người cha ghẻ lạnh. Tranh cãi gay gắt với cha của mình, Claudia tìm mọi cách quay trở về Mỹ thông qua một tên buôn lậu - Ricky. Mắc kẹt giữa vòng xoáy của những bài thuyết giáo do cha mình đặt ra, những lời hứa hẹn của Ricky và quân đội vùng biên giới. Claudia phải quyết định con đường của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Veronica Sixtos","avatar":""},{"name":"Julio Cedillo","avatar":""},{"name":"Roberto Urbina","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
