INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ravens-touch', 'Raven''s Touch', 'Raven''s Touch', 'https://phimimg.com/upload/vod/20231205-1/c2895dcb70051354d29ad6968257f5b5.jpg', 'https://phimimg.com/upload/vod/20231205-1/adb75fa4257b721123154ce33e8d7e86.jpg', '<p>Tự trách mình vì một tai nạn thảm khốc, Raven Michaels sống ẩn dật trong căn nhà gỗ hẻo lánh của gia đình. Cô lang thang trong rừng trên bờ vực suy sụp, tìm kiếm sự bình yên trong sự cô lập. Trong nỗ lực cuối cùng để cứu gia đình, Kate Royce đưa hai thiếu niên của mình đi cắm trại, tránh xa những phiền nhiễu của công nghệ và sự lãng mạn của tuổi trẻ. Khi thế giới của Raven và Kate xung đột, họ mang đến cho nhau những cơ hội bất ngờ để thân mật và hàn gắn.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dreya Weber","avatar":""},{"name":"Traci Dinwiddie","avatar":""},{"name":"David Hayward","avatar":""},{"name":"Victoria Park","avatar":""},{"name":"Christopher O''Neal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
