INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-phu-tu', 'Tình Phụ Tử', 'Son Of Saul', 'https://phimimg.com/upload/vod/20231204-1/dfb051e9bb34fa90e387ae933ad72a7b.jpg', 'https://phimimg.com/upload/vod/20231204-1/a9b113993ba135b93246887ea23d3362.jpg', '<p>Phim Tình Phụ Tử - Son Of Saul (2015): là câu chuyện diễn ra vào năm 1944 về một tù nhân năm tên Auschwitz, anh là người bị ép buộc phải thiêu những thi hài. Khi Auschwitz tìm thấy một thi hài mà anh tin đó là của con trai của mình, anh đã cố gắng trong tuyệt vọng để gìn giữ thi hài</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Géza Röhrig","avatar":""},{"name":"Levente Molnár","avatar":""},{"name":"Urs Rechn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324451);
