INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-da-den', 'Phận Da Đen', 'Hombre Negro, Piel Blanca', 'https://phimimg.com/upload/vod/20231202-1/bf6212c0ffc3f40ac1d6cb2e771f01cb.jpg', 'https://phimimg.com/upload/vod/20231202-1/25f6c98e116707c411d8f66b25a255cf.jpg', '<p>Bộ phim này ghi lại các vấn đề về sức khỏe và xã hội mà những người bạch tạng châu Phi phải đối mặt và trình bày chi tiết cuộc chiến do các nhóm vận động chính sách ở Tây Ban Nha tiến hành thay mặt họ.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324451);
