INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-voi-lung-gu', 'Cá Voi Lưng Gù', 'Humpback Whales', 'https://phimimg.com/upload/vod/20231202-1/7c9c58369f32bd863c6b8b9c7417613e.jpg', 'https://phimimg.com/upload/vod/20231202-1/63434220400d54762ff97947b45779a5.jpg', '<p>Cá voi lưng gù đưa khán giả đến Alaska, Hawaii và Vương quốc Tonga để có cái nhìn cận cảnh về cách những con cá voi này giao tiếp, ca hát, kiếm ăn, chơi đùa và chăm sóc con non của chúng. Cá voi lưng gù gần như bị tuyệt chủng cách đây 50 năm, nhưng ngày nay chúng đang phục hồi ổn định. Hãy tham gia cùng một nhóm các nhà nghiên cứu khi họ khám phá điều gì khiến cá voi lưng gù trở thành loài nhào lộn giỏi nhất trong tất cả các loài cá voi, tại sao chỉ có những con đực mới hót và tại sao những con vật thông minh cao 50 foot, nặng 48 tấn này di cư hơn 6.000 dặm khứ hồi mỗi năm.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324451);
