INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-quen-em', 'Đừng Quên Em', 'She Remembers, He Forgets', 'https://phimimg.com/upload/vod/20231201-1/5ec72876722389f495892845daa0f9e3.jpg', 'https://phimimg.com/upload/vod/20231201-1/8acc6d75df0c79ee776898d2b8ecf833.jpg', '<p>Công việc bế tắc, không hài lòng với cuộc sống hôn nhân của mình, người phụ nữ trung niên quyết định tham dự cuộc hội ngộ bạn bè cũ ở trường trung học và ký ức về những ngày thanh xuân của cô mở ra trước mắt. Cô không thể tách rời với hai chàng trai 20 năm trước nhưng cuối cùng lại cưới một trong số họ. Tất cả những ký ức cuối cùng đều dừng lại ở một sự cố quan trọng đã thay đổi cuộc đời cô và những chàng trai mãi mãi.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Miriam Yeung Chin-Wah","avatar":""},{"name":"Jan Lam Hoi-Fung","avatar":""},{"name":"Cecilia So","avatar":""},{"name":"Neo Yau","avatar":""},{"name":"Ng Siu-Hin","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Lau Hung-Fat","avatar":""},{"name":"Gill Mohindepaul Singh","avatar":""},{"name":"Ronny Yuen","avatar":""},{"name":"Bondy Chiu","avatar":""},{"name":"Helen Tam Yuk-Ying","avatar":""},{"name":"Margaret Chung","avatar":""},{"name":"Harriet Yeung","avatar":""},{"name":"Patrick Kong","avatar":""},{"name":"Isabella Chan","avatar":""},{"name":"DeeGor Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
