INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tro-ve-2015', 'Hành Trình Trở Về', 'Journey To The Shore', 'https://phimimg.com/upload/vod/20231212-1/fe165f3512cb891e9584db564735e80b.jpg', 'https://phimimg.com/upload/vod/20231212-1/ae0277d98dffd2a70f4fea5b78032b6a.jpg', '<p>Sau một tai nạn trên biển, ai cũng tưởng rằng chồng của Mizuki (Yusuke) đã chết đuối trên biển cách đây ba năm. Một ngày, anh đột nhiên trở về nhà, cô ấy không ngạc nhiên. Thay vào đó, Mizuki đang tự hỏi những gì đã khiến chồng của cô biến mất trong khoảng thời gian lâu như vậy? Yusuke đã đề nghị giải thích bằng cách đưa cô đi cùng để biết được thời gian qua anh đã ở đâu?</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Eri Fukatsu","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Yū Aoi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
