INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-thanh-ky', 'Tam Thành Ký', 'A Tale of Three Cities', 'https://phimimg.com/upload/vod/20231201-1/7b9f05fda66d3d5b9931e578d868563c.jpg', 'https://phimimg.com/upload/vod/20231201-1/98bf0cb1de64289f97e8d818536c1538.jpg', '<p>Tam Thành Ký (A Tale of Three Cities 2015) lấy bối cảnh vào những năm 30 của thế kỷ trước, nói về chuyện tình trắc trở trong thời kỳ loạn lạc, sinh ly tử biệt. người đàn ông mạnh mẽ, hiền lành Trần Chí Bình – cha Thành Long (Lưu Thanh Vân) đã có một vợ và hai con tại Trung Quốc. Sau khi đến Hồng Kông lánh nạn, ông gặp gỡ và đem lòng yêu người phụ nữ Trần Lợi Lợi (Thang Duy). Về sau, cô sinh cho Chí Bình một đứa con trai, đặt tên là Chung Cảng Sinh. Chung Cảng Sinh lớn lên gia nhập làng giải trí và lấy nghệ danh là Thành Long.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Tang Wei","avatar":""},{"name":"Qin Hailu","avatar":""},{"name":"Jing Boran","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Li Jianyi","avatar":""},{"name":"Jiao Gang","avatar":""},{"name":"Philip Chan","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Wong Ji-Dan","avatar":""},{"name":"Peng Yin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
