INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-d', 'Kế Hoạch D', 'The D Train', 'https://phimimg.com/upload/vod/20231201-1/ef56bad6f02578b2f9e5e7195c2639a8.jpg', 'https://phimimg.com/upload/vod/20231201-1/ec6ab7332304fe1cb2c19bb1c6358ad7.jpg', '<p>Đảm nhận việc lên kế hoạch cho cuộc họp lớp trung học sau 20 năm, kẻ thất bại nọ nghĩ mình đã thành công lớn khi mời được một cựu học sinh có chút tiếng tăm đến tham dự.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jack Black","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Mike White","avatar":""},{"name":"Kyle Bornheimer","avatar":""},{"name":"Henry Zebrowski","avatar":""},{"name":"Corrina Lyons","avatar":""},{"name":"Donna DuPlantier","avatar":""},{"name":"Denise Williamson","avatar":""},{"name":"Han Soto","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Mariana Paola Vicente","avatar":""},{"name":"Kendra Waldman","avatar":""},{"name":"Russell Posner","avatar":""},{"name":"Charlotte Gale","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
