INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-thien-xa-ban-tia-xinh-dep', 'Nữ Thiện Xạ Bắn Tỉa Xinh Đẹp', 'Battle for Sevastopol', 'https://phimimg.com/upload/vod/20231201-1/661412438f6f58e5f015608f80b4902c.jpg', 'https://phimimg.com/upload/vod/20231201-1/2e8d4c99b5e08c8ea6e485ec0d51f2eb.jpg', '<p>Chiến tranh đã buộc cô nữ sinh viên Lyudmila Pavlichenko đăng lính vào năm 1941. Cô gái ngây thơ trong trắng ngày nào được định mệnh đặt vào tay một khẩu súng bắn tỉa. Lòng dũng cảm cùng những kỹ năng thiên bẩm khiến cô trở thành tay bắn tỉa thiện xạ. Nhận thấy mối nguy mà cô gái mang lại, tư lệnh phát xít Đức ra lệnh tiêu diệt cô bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Yulia Peresild","avatar":""},{"name":"Yevgeni Tsyganov","avatar":""},{"name":"Natella Abeleva-Taganova","avatar":""},{"name":"Nikita Tarasov","avatar":""},{"name":"Joan Blackham","avatar":""},{"name":"Polina Pakhomova","avatar":""},{"name":"Oleg Vasilkov","avatar":""},{"name":"Vladimir Lilitskiy","avatar":""},{"name":"Anatoly Kot","avatar":""},{"name":"Valeriy Grishko","avatar":""},{"name":"Sergey Barkovsky","avatar":""},{"name":"Vitali Linetsky","avatar":""},{"name":"Sergey Puskepalis","avatar":""},{"name":"Gennadiy Chentsov","avatar":""},{"name":"Svetlana","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
