INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-ky-uc', 'Bóng Ma Ký Ức', 'Dark Places', 'https://phimimg.com/upload/vod/20231201-1/9c90d0532186741caad823ebfad8d565.jpg', 'https://phimimg.com/upload/vod/20231201-1/bfacb4a29dccbdacba281cecfcd78630.jpg', '<p>Một người phụ nữ sống sót sau vụ giết hại dã man gia đình mình khi còn nhỏ buộc phải đối mặt với những sự kiện xảy ra ngày hôm đó.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Charlize Theron","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Andrea Roth","avatar":""},{"name":"Sterling Jerins","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Drea de Matteo","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"J. LaRose","avatar":""},{"name":"Jennifer Pierce Mathus","avatar":""},{"name":"Denise Williamson","avatar":""},{"name":"Natalie Precht","avatar":""},{"name":"Madison M","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324451);
