INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bong-ma-ky-uc', 'Bóng Ma Ký Ức', 'Dark Places', 'bóng ma ký ức dark places charlize theron nicholas hoult chloë grace moretz christina hendricks tye sheridan corey stoll andrea roth sterling jerins shannon kook drea de matteo sean bridgers j. larose jennifer pierce mathus denise williamson natalie precht madison m ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-lung', 'Săn Lùng', 'Big Game', 'https://phimimg.com/upload/vod/20231201-1/d7943d9e9f1d682a807f10627bde457a.jpg', 'https://phimimg.com/upload/vod/20231201-1/744a0e3a603f7b86254b6162c1327b19.jpg', '<p>Săn Lùng - Big Game có nội dung xoay quanh một âm mưu nhằm vào Tổng thống Mỹ đã được hé lộ khi máy bay chở ông trên đường tham dự hội nghị thượng đỉnh tại Phần Lan phát hiện tín hiệu tên lửa đang tiến tới. Để bảo vệ tổng thống, mật vụ Morris quyết định đưa ông vào khoang cứu hộ khẩn cấp và đưa xuống mặt đất. Ngờ đâu, chính Morris lại là kẻ sắp đặt tất cả để biến ông thành mục tiêu săn đuổi của một nhóm khủng bố. May mắn thay, ông nhận được sự giúp đỡ từ cậu bé người địa phương Oskari đang nhận nhiệm vụ săn linh dương để chứng tỏ sự trưởng thành theo tục lệ của người dân nơi đây. Liệu chỉ với cung nỏ làm vũ khí, Tổng thống và Oskari sẽ vượt qua mọi chuyện như thế nào?</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Phần Lan', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Onni Tommila","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Felicity Huffman","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Mehmet Kurtuluş","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Jaymes Butler","avatar":""},{"name":"Jorma Tommila","avatar":""},{"name":"Risto Salmi","avatar":""},{"name":"Erik Markus Schuetz","avatar":""},{"name":"Rauno Juvonen","avatar":""},{"name":"Jean-Luc Julien","avatar":""},{"name":"Jason Steffan","avatar":""},{"name":"Philipp Rafferty","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b2390811