INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-tho-bunny', 'Cuộc Phiêu Lưu Của Thỏ Bunny', 'Looney Tunes: Rabbits Run', 'https://phimimg.com/upload/vod/20231201-1/1cccd10357f874ccf05d4c9e156aa864.jpg', 'https://phimimg.com/upload/vod/20231201-1/70792b4aa21636d1fa39b0a6504fbe1c.jpg', '<p>Lola Bunny phát minh ra một loại nước hoa có tác dụng phụ là biến mọi người thành vô hình, khiến cô và tài xế taxi Bugs Bunny chạy trốn khỏi FBI, trong khi một nhóm mờ ám khác tìm kiếm công thức.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bergman","avatar":""},{"name":"Billy West","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Rachel Ramras","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Michael Serrato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324451);
