INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lot-vao-hang-cop', 'Lọt Vào Hang Cọp', 'Tiger House', 'https://phimimg.com/upload/vod/20231201-1/864cf66ec77697daa462ff014df59ea9.jpg', 'https://phimimg.com/upload/vod/20231201-1/2269afa7a22fba1f02f2c1a96bbebbb3.jpg', '<p>Một vận động viên thể dục trẻ chiến đấu với một nhóm cướp ngân hàng tại nhà của bạn trai cô.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Kaya Scodelario","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Brandon Auret","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Julie Summers","avatar":""},{"name":"Daniel Boyd","avatar":""},{"name":"Andrew Brent","avatar":""},{"name":"Nicholas Dallas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
