INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lon-chien', 'Lợn Chiến', 'War Pigs', 'https://phimimg.com/upload/vod/20231201-1/b3035ba8588511498d367ad1b205d7c9.jpg', 'https://phimimg.com/upload/vod/20231201-1/9d95eb5c594611360cfdef1731c649b5.jpg', '<p>Phim War Pig sẽ đưa chúng ta về thời kì Thế Chiến thứ 2 cùng với một vị đại úy bị giáng chức, Jack Wosick. Anh được trao cho một cơ hội để chuộc lại lỗi lầm, đó là bí mật tiến đến phía sau hàng ngũ quân phát-xít và chiếm lấy siêu vũ khí tối tân kinh khủng V3. Tuy nhiên những người sẽ cùng anh thực hiện nhiệm vụ này lại là một nhóm chẳng ra gì và anh phải nhờ vào hai người chiến binh kì cưu khác để huấn luyện họ cho cuộc chiến sắp tới.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Goss","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Chuck Liddell","avatar":""},{"name":"Noah Segan","avatar":""},{"name":"Steven Luke","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Ryan Kelley","avatar":""},{"name":"Angie Papanikolas","avatar":""},{"name":"Jake Stormoen","avatar":""},{"name":"K.C. Clyde","avatar":""},{"name":"Paul Cram","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324451);
