INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-lay-ma-quai', 'Đầm Lầy Ma Quái', 'Muck', 'https://phimimg.com/upload/vod/20231201-1/c18b413e4f8d39857bf687c7dd86357e.jpg', 'https://phimimg.com/upload/vod/20231201-1/93ef13b072ab3706eb0d38c721e5a27f.jpg', '<p>Làm thế nào để trốn thoát khỏi mội thế lực ‘bí ẩn’, làm thế nào để sống sót và tìm ra sự thật về những khuất tất đằng sau những cuộc rượt đuổi dường như không có kết thúc ? Câu trả lời sẽ được giải đáp trong ‘Muck’. Ngay sau khi vừa rời khỏi vùng đất thiêng của tổ tiên, nhóm bạn trẻ bị kẹt lại giữa cuộc chiến của hai con quỷ, bị buộc phải chém giết nhau, phải quay trở về con bằng chính con đường đưa họ đến đây.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lachlan Buchanan","avatar":""},{"name":"Stephanie Danielson","avatar":""},{"name":"Puja Mohindra","avatar":""},{"name":"Bryce Draper","avatar":""},{"name":"Laura Jacobs","avatar":""},{"name":"Grant Alan Ouzts","avatar":""},{"name":"Lauren Francesca","avatar":""},{"name":"Jaclyn Swedberg","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Gia Skova","avatar":""},{"name":"Leila Knight","avatar":""},{"name":"Audra Van Hees","avatar":""},{"name":"Ashley Nicole Wallace","avatar":""},{"name":"Jacob Rowland Tate","avatar":""},{"name":"Peter Hart","avatar":""},{"name":"Ashley Gree","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
