INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-kute', 'Đặc Vụ Ku-te', 'Barely Lethal', 'https://phimimg.com/upload/vod/20231201-1/11a9527a42afc790d0153728385ee415.jpg', 'https://phimimg.com/upload/vod/20231201-1/763e3ad3f6de5311f7d086221486cf93.jpg', '<p>Megan Walsh đã được đào tạo để trở thành một sát thủ quốc tế cho người chăm chỉ. Tuy nhiên, trong khi cô ấy đang thực hiện một nhiệm vụ, cô ấy nhận thấy cách các thanh thiếu niên khác ở tuổi cô ấy dường như đang vui vẻ và tận hưởng cuộc sống của họ. Mong muốn một cuộc sống bình thường, cô đã bảo lãnh khỏi một nhiệm vụ và tuyển sinh vào một chương trình trao đổi sinh viên, trong khi trong quá trình được thông qua bởi một gia đình nuôi dưỡng. Cô sớm trở thành một phần của trường trung học và phải chịu áp lực và cuộc sống về môi trường của nó.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Sophie Turner","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Dove Cameron","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Emma Holzer","avatar":""},{"name":"Rob Huebel","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Jason Ian Drucker","avatar":""},{"name":"Toby Sebastian","avatar":""},{"name":"Alexandra Krosney","avatar":""},{"name":"Finesse Mitchell","avatar":""},{"name":"Bruno Gunn","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
