INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-co', 'Thất Cô', 'Lost and Love', 'https://phimimg.com/upload/vod/20231201-1/21c6d8f571c8a8998a4ad2c3efc44c77.jpg', 'https://phimimg.com/upload/vod/20231201-1/8d06d40565239911b3c00e018838143c.jpg', '<p>Sau khi cậu con trai nhỏ mất tích, Lôi (Lưu Đức Hoa) bắt đầu hành trình tìm kiếm cậu bé kéo dài 14 năm.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Jing Boran","avatar":""},{"name":"Ni Jingyang","avatar":""},{"name":"Wang Zhifei","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Sun Hai Ying","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
