INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-duoc-uoc-thay', 'Cầu Được Ước Thấy', 'Absolutely Anything', 'https://phimimg.com/upload/vod/20231130-1/b0d57847a49a3f990f2f5a9d21712d03.jpg', 'https://phimimg.com/upload/vod/20231130-1/4eeba1c4bfdc165f31af85e21c091aa9.jpg', '<p>Nội dung phim xoay quanh chàng giáo viên dạy cấp II - Neil Clarke (do Simon Pegg thủ vai) bỗng dưng nhận ra mình có khả năng làm được bất cứ thứ gì mình muốn. Nhưng mọi chuyện lại không đơn giản như vậy, bởi quyền năng đặc biệt này của anh là do một nhóm người ngoài hành tinh, có tên: Hội đồng liên Ngân Hà “ban tặng”. Và điều quan trọng là Neil không hề biết rằng cách mà anh sử dụng thứ phép màu đó sẽ quyết định tới vận mệnh của cả nhân loại.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Sanjeev Bhaskar","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Marianne Oldham","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Robert Bathurst","avatar":""},{"name":"Judy Loe","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Meera Syal","avatar":""},{"name":"Emma Pierson","avatar":""},{"name":"David Annen","avatar":""},{"name":"Mairi McHaffie","avatar":""},{"name":"Gavin Scott","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Terry Gilliam","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324451);
