INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-duoc-uoc-thay', 'Cầu Được Ước Thấy', 'Absolutely Anything', 'cầu được ước thấy absolutely anything simon pegg kate beckinsale rob riggle sanjeev bhaskar joanna lumley marianne oldham eddie izzard robert bathurst judy loe brian cox meera syal emma pierson david annen mairi mchaffie gavin scott robin williams john cleese terry gilliam e ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-quy', 'Trùng Quỷ', 'Harbinger Down', 'https://phimimg.com/upload/vod/20231211-1/02452b76dedaaf8c523bf8105e60bbd7.jpg', 'https://phimimg.com/upload/vod/20231211-1/c8059181f9a834cad0c879f4eb087da1.jpg', '<p>Một nhóm sinh viên tốt nghiệp đã đặt chuyến đi trên tàu đánh cá Harbinger để nghiên cứu tác động của sự nóng lên toàn cầu đối với một đàn Orcas ở Biển Bering. Khi phi hành đoàn của con tàu nạo vét một mảnh vỡ không gian cũ của Liên Xô gần đây, mọi thứ trở nên hết sức nguy hiểm. Có vẻ như người Nga đã thử nghiệm với gấu nước, loài động vật nhỏ bé kiên cường có thể chịu được sự khắc nghiệt của bức xạ không gian. Các sinh vật sống sót, nhưng không phải không có đột biến. Bây giờ phi hành đoàn tiếp xúc với các sinh vật đột biến mạnh mẽ. Và sau khi bị nhốt trong băng suốt 3 thập kỷ, các sinh vật này sẽ không từ bỏ hơi ấm tình bạn của con người.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Henriksen","avatar":""},{"name":"Matt Winston","avatar":""},{"name":"Camille Balsamo","avatar":""},{"name":"Giovonnie Samuels","avatar":""},{"name":"Winston James Francis","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
