INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-thau', 'Xuyên Thấu', 'Through The Air', 'https://phimimg.com/upload/vod/20231211-1/ab6bab8cda8b81a3f717d12095f35505.jpg', 'https://phimimg.com/upload/vod/20231211-1/4bfb31b038f69eaec2fff0269ffafc6a.jpg', '<p>Vincent, nhà vô địch bắn súng trường, sống một cuộc sống bình yên bên vợ và con gái, cho đến khi những vấn đề tài chính bắt buộc anh phải xem xét lại các kế hoạch của mình và đe dọa tới sự ổn định trong gia đình anh. Trên trường bắn súng, anh gặp gỡ Renaud, một người đàn ông quyến rũ nhưng đầy bí ẩn. Hắn hứa hẹn sẽ cho anh một lối thoát, nếu anh kí vào một hợp đồng đặc biệt. Kể từ giây phút ấy, Vincent bắt đầu chạm tới một rắc rối đầy nguy hiểm…</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Reda Kateb","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Johan Heldenbergh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
