INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-tim-chong-cua-do-lap-lap', 'Nhật Ký Tìm Chồng Của Đỗ Lạp Lạp', 'Go Lala Go 2', 'https://phimimg.com/upload/vod/20231211-1/c8af785c85f93ed005fcdf5e127e1d0d.jpg', 'https://phimimg.com/upload/vod/20231211-1/b18835f253a6af5a871e5c34d7f235a0.jpg', '<p>Phim Nhật Ký Tìm Chồng Của Đỗ Lạp Lạp - Go Lala Go 2 2015 tiếp tục câu chuyện của bộ phim Nhật Ký Thăng Chức Của Đỗ Lạp Lạp. Phim chủ yếu xoay quanh câu chuyện tìm kiếm người bạn đời đích thực cho mình của Đỗ Lạp Lạp – một quý cô sắp bước sang tuổi 30. Trong quá trình đó, cô đã bày ra nhiều trò “dở khóc dở cười”, để rồi tự mình vướng vào những rắc rối đó. Vương Vĩ và Trần Phong (Trần Bách Lâm) là hai anh chàng yêu cô say đắm và muốn tiến tới hôn nhân…</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Y Thần","avatar":""},{"name":"Châu Du Dân","avatar":""},{"name":"Trần Bá Lâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
