INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-giay-vang', 'Đôi Giày Vàng', 'Golden Shoes', 'https://phimimg.com/upload/vod/20231211-1/d90421ddef83941991f717a24868016e.jpg', 'https://phimimg.com/upload/vod/20231211-1/5604a0397a925faa6b570105b571578d.jpg', '<p>Một cậu bé tập trung vào bóng đá để lo liệu cho người mẹ nằm viện và người bố đang tham chiến. Rồi đôi giày đinh đặc biệt giúp cậu nâng cao kỹ năng lên tầm ngoạn mục.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Koza","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Montel Williams","avatar":""},{"name":"John Rhys-Davies","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
