INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-war', 'A War', 'A War', 'https://phimimg.com/upload/vod/20231210-1/fb144d876c71b740afec6af43ba4eaa7.jpg', 'https://phimimg.com/upload/vod/20231210-1/e12689857dc034fd94c4319b0d61d5ef.jpg', '<p>Bộ phim A War - Krigen (Chiến Cuộc) là một bộ phim có đề tài chiến tranh của Đan Mạch năm 2015 kịch bản và đạo diễn bởi Tobias Lindholm, và có sự tham gia của Pilou Asbæk và Søren Malling.
 Nội dung phim kể về Đại đội trưởng Claus M. Pedersen (Pilou Asbæk) và lính của anh ta đang đóng quân ở Helmand Province, một quận của Afghanistan, nổi tiếng khốc liệt. Trong khi đó ở Đan Mạch, Maria (Tuva Novotny) vợ Claus vẫn đang cố gắng cân bằng cuộc sống của mình khi chồng đang ở chiến trận, cùng ba đứa nhỏ một tay chăm sóc. Trong một nhiệm vụ tuần tra, Claus đã phải chiến đấu với kẻ thù, và với chính bản thân. Giữa làn đạn khốc liệt, với những con người đặt trọn niềm tin và lẽ sống nơi anh, là bao gia đình chờ con mỏi mòn, là lý tưởng sống mà anh hằng theo đuổi... Và để cứu lấy các đồng đội của mình, Claus đã phải đưa ra một quyết định gây hậu quả nghiêm trọng cho chính mình và gia đình mình ở quê nhà...</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Pilou Asbæk","avatar":""},{"name":"Tuva Novotny","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Charlotte Munck","avatar":""},{"name":"Dar Salim","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
