INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-thanh-phong-van-2', 'Đổ Thành Phong Vân 2', 'From Vegas To Macau II', 'https://phimimg.com/upload/vod/20231130-1/d01b23a7ce0ff55065c50291721f6f71.jpg', 'https://phimimg.com/upload/vod/20231130-1/5ab56becc2d69a7293b24b5823125c94.jpg', '<p>Đổ Thành Phong Vân 2 sẽ tiếp nối phần trước, Nhân vật Thạch Nhất Kiên (Châu Nhuận Phát) là một truyền kỳ trong giới cờ bạc. Ông không chỉ nhanh tay nhanh mắt, tư duy siêu việt mà còn có tuyệt triêu “sờ và tráo bài”. Tuy nhiên, ông lại là người vô cùng lương thiện, không đến đường cùng không bày trò. Phim sẽ xoay quanh những cuộc chiến bài bạc giữa những “cao thủ”, xen vào đó là những cảnh hành động đẹp mắt khiến người xem không thể rời khỏi màn hình.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Bella Law","avatar":""},{"name":"Angela Wang","avatar":""},{"name":"Yuan Quan","avatar":""},{"name":"QiaoQiao Jin","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Zaneta Wong","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Sean Tierney","avatar":""},{"name":"Connie Man","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
