INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-doi-cuoc-doi', 'Thay Đổi Cuộc Đời', 'Alex of Venice', 'https://phimimg.com/upload/vod/20231130-1/b3ea3d41464016fe62f8a6e9c0f28db0.jpg', 'https://phimimg.com/upload/vod/20231130-1/342452763d4d778dcc34c2c4c6d24071.jpg', '<p>Sau khi người chồng ở nhà nội trợ rời bỏ cô, một luật sư nghiện công việc nhận thấy rằng cô không hoàn toàn có thể hoàn thành nhiệm vụ chăm sóc con trai nhỏ, người cha ốm yếu và gia đình một mình.</p>', 'Full', 1, 'single', 'completed', 6, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Skylar Gaertner","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Matthew Del Negro","avatar":""},{"name":"Timm Sharp","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Tom Yi","avatar":""},{"name":"Zane Smith","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"Will McCormack","avatar":""},{"name":"Tai Cheadle","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"Katie Nehra","avatar":""},{"name":"Sandra Seacat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
