INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-tay-thien-duong', 'Viễn Tây Thiên Đường', 'Slow West', 'https://phimimg.com/upload/vod/20231130-1/343f17919773d64e2af17d25d3d71b7b.jpg', 'https://phimimg.com/upload/vod/20231130-1/a20332e3277df197f7b15b24fcc26da1.jpg', '<p>Viễn Tây Thiên Đường - Slow West: là bộ phim hành động Mỹ do đạo diễn John Maclean chủ nhiêm sản xuất . Phim kể về cuộc hành trình của chàng trai 16 tuổi vượt qua biên giới nước Mỹ vào thế kỉ 19 để tìm kiếm người con gái cậu yêu, với sự đồng hành của một lữ khách bí ẩn tên Silas.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Caren Pistorius","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Eddie Campbell","avatar":""},{"name":"Brooke Williams","avatar":""},{"name":"Alex MacQueen","avatar":""},{"name":"Kalani Queypo","avatar":""},{"name":"Madeleine Sami","avatar":""},{"name":"Tawanda Manyimo","avatar":""},{"name":"David T. Lim","avatar":""},{"name":"Jeffrey Thomas","avatar":""},{"name":"Hayden Frost","avatar":""},{"name":"Kieran Charnock","avatar":""},{"name":"Michael Whalle","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
