INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sleeping-with-other-people', 'Sleeping with Other People', 'Sleeping with Other People', 'https://phimimg.com/upload/vod/20231130-1/0c5cf70783588abc59b27dc3ede82412.jpg', 'https://phimimg.com/upload/vod/20231130-1/1cc857e955e67fb521c0a1aab651565d.jpg', '<p>Hai kẻ lừa dối nối tiếp có thể có cơ hội yêu thứ hai không? Sau tình một đêm ở trường đại học, Lainey và Jake người New York tình cờ gặp nhau mười hai năm sau và phát hiện ra rằng mỗi người đều có cùng một vấn đề: vì lối sống chung thủy một vợ một chồng, cả hai đều không thể duy trì mối quan hệ. Quyết tâm tiếp tục là bạn bè bất chấp sự hấp dẫn lẫn nhau, họ lập một hiệp ước để giữ mối quan hệ trong sáng, một thỏa thuận chứng tỏ nói thì dễ hơn làm.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Sudeikis","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Marc Blucas","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Andrea Savage","avatar":""},{"name":"Daniella Pineda","avatar":""},{"name":"Remy Nozik","avatar":""},{"name":"Megan Guinan","avatar":""},{"name":"Anna Margaret Hollyman","avatar":""},{"name":"Sawyer Shipman","avatar":""},{"name":"Marg","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
