INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ba-mary-shepherd', 'Quý Bà Mary Shepherd', 'The Lady in the Van', 'https://phimimg.com/upload/vod/20231130-1/5475a52c4c4724bccca10d3b36ed0032.jpg', 'https://phimimg.com/upload/vod/20231130-1/727f6b2ee5715794dd98a7caaca29a3d.jpg', '<p>Câu chuyện có thật về mối quan hệ giữa Alan Bennett và cô Shepherd độc nhất vô nhị, một người phụ nữ có nguồn gốc không rõ ràng đã &#39;tạm thời&#39; đậu chiếc xe tải của mình ở đường lái xe vào nhà của Bennett ở London và tiếp tục sống ở đó trong 15 năm.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Maggie Smith","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Gwen Taylor","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"James Corden","avatar":""},{"name":"Roger Allam","avatar":""},{"name":"Samuel Anderson","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Stephen Campbell Moore","avatar":""},{"name":"Eleanor Matsuura","avatar":""},{"name":"Sacha Dhawan","avatar":""},{"name":"Samuel Barnett","avatar":""},{"name":"Deborah Findlay","avatar":""},{"name":"David Calder","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
