INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-tien-su-troi-day', 'Cá Mập Tiền Sử Trỗi Dậy', 'Sharkansas Women''s Prison Massacre', 'https://phimimg.com/upload/vod/20231130-1/c2e0293eca49becdba9eeec2fec23136.jpg', 'https://phimimg.com/upload/vod/20231130-1/aa8026775dd41af00074a55731f287c2.jpg', '<p>Khi một tai nạn fracking vô tình xé toạc lớp vỏ trái đất, lỗ hổng tạo ra sẽ mở ra một đường dẫn nước ngầm đến một đại dương rộng lớn và bí ẩn ở đâu đó sâu bên dưới. Ngay lập tức, những con cá mập khổng lồ thời tiền sử bắt đầu tiến lên phía một vũng lầy âm u ở trung tâm Arkansas Bayou. Thật không may, đối với một nhóm nữ tù nhân đang làm công việc chi tiết ở đầm lầy, những con cá mập chết người đã tấn công mà không báo trước – ghim chặt một nhóm nạn nhân đáng tiếc trong một cabin nhỏ bỏ hoang ở trung tâm vùng đầm lầy. Cái chết có thể là lối thoát duy nhất!</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominique Swain","avatar":""},{"name":"Traci Lords","avatar":""},{"name":"Christine Nguyen","avatar":""},{"name":"Cindy Lucas","avatar":""},{"name":"Amy Holt","avatar":""},{"name":"John Callahan","avatar":""},{"name":"Corey Landis","avatar":""},{"name":"Chris De Christopher","avatar":""},{"name":"Skye McDonald","avatar":""},{"name":"Tabitha Marie","avatar":""},{"name":"Serafin Falcon","avatar":""},{"name":"Oscar DeRosa","avatar":""},{"name":"Steve Goldenberg","avatar":""},{"name":"Robert Hummel","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02