INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-go-2015', 'Điềm Gở', 'Ominous', 'https://phimimg.com/upload/vod/20231130-1/2bd45faf678ab4b2a2372f69644bd37a.jpg', 'https://phimimg.com/upload/vod/20231130-1/da4545f9d666c20774cef6535d7d0966.jpg', '<p>Phim Điềm Gở - Ominous 2015: Michael và Rachel đau khổ tột cùng trước cái chết của đứa con trai 6 tuổi trong tai nạn thảm khốc. Khi một người lạ đến đề nghị hồi sinh đứa trẻ, họ đồng ý. Tuy nhiên, đứa trẻ trở lại khi còn là đứa con mà họ từng biết nữa.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barry Watson","avatar":""},{"name":"Esmé Bianco","avatar":""},{"name":"Gavin Lewis","avatar":""},{"name":"Mark Lindsay Chapman","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Jaime Gomez","avatar":""},{"name":"Ian Hyland","avatar":""},{"name":"John Colton","avatar":""},{"name":"Connor Bellina","avatar":""},{"name":"Brandon Amano","avatar":""},{"name":"Gavin Collins","avatar":""},{"name":"Jared Breeze","avatar":""},{"name":"Hunter Payton","avatar":""},{"name":"Angela Relucio","avatar":""},{"name":"Michael C. Mahon","avatar":""},{"name":"Dona Wood","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324451);
