INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ong-dien-ro', 'Mật Ong Điên Rồ', 'Delibal', 'https://phimimg.com/upload/vod/20231130-1/2577fb67326cb8e66342cdecfaf31dde.jpg', 'https://phimimg.com/upload/vod/20231130-1/b9bdc8c315d6311b29d097ef0be82d96.jpg', '<p>Là tựa phim tình cảm chính kịch của Thổ Nhĩ Kỳ, <em>Delibal</em> kể về chuyện tình của chàng trai sinh viên kiến trúc Bariş. Vốn không tin vào tình yêu nhưng lại gặp gỡ và rung động trước Füsun, Bariş tin rằng tình yêu đích thực đang gần kề. Bằng trí thông minh và sức quyến rũ, anh chàng đã khiến cho Füsun phải lòng mình. Hai con người trẻ tuổi nhanh chóng rơi vào lưới tình và đi tới một đám cưới hạnh phúc. Thế nhưng, câu chuyện tưởng chừng đẹp như cổ tình này lại có những khúc cua bất ngờ khiến cho ai nấy đều phải cảm thấy hồi hộp, ngỡ ngàng.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Çağatay Ulusoy","avatar":""},{"name":"Leyla Lydia Tuğutlu","avatar":""},{"name":"Hüseyin Avni Danyal","avatar":""},{"name":"Nazan Kesal","avatar":""},{"name":"Mustafa Avkıran","avatar":""},{"name":"Laçin Ceylan","avatar":""},{"name":"Toprak Sağlam","avatar":""},{"name":"Barış Aytaç","avatar":""},{"name":"Zafer Akkoyun","avatar":""},{"name":"Kıvılcım Ural","avatar":""},{"name":"Ali Seyitoglu","avatar":""},{"name":"Emre Karaoglu","avatar":""},{"name":"Baturalp Yilmaz","avatar":""},{"name":"Defne Kayalar","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
