INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-chet-choc', 'Ngôi Nhà Chết Chóc', 'The Unspoken', 'https://phimimg.com/upload/vod/20231129-1/83fca4a2335aef145e3b7893028cadd9.jpg', 'https://phimimg.com/upload/vod/20231129-1/49369421cf6cc9a3dc21dcb30bf354ef.jpg', '<p>Ngôi Nhà Chết Chóc - Unspoken là bộ phim xoay quanh những sự kiện kỳ lạ diễn ra tại một ngôi nhà bí ẩn nằm sâu trong rừng. 17 năm sau một vụ mất tích không thể lý giải của gia đình Anderson, người mẹ độc thân Ruby cùng đứa con trai câm Adrian đã chuyển đến sống tại ngôi nhà này. Angela - một cô gái dù biết bí mật kinh hoàng của ngôi nhà nhưng vẫn nhận công việc trông nom cậu bé Adrian. Chính sự xuất hiện của những người chủ mới đã làm sống dậy những gì tăm tối và đáng sợ nhất tại đây. Hàng loạt vụ án mạng bí ẩn xảy ra, khiến cảnh sát cũng phải vào cuộc.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jodelle Ferland","avatar":""},{"name":"Sunny Suljic","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Matt Bellefleur","avatar":""},{"name":"Fulvio Cecere","avatar":""},{"name":"Chilton Crane","avatar":""},{"name":"Jake Croker","avatar":""},{"name":"Rukiya Bernard","avatar":""},{"name":"Pascale Hutton","avatar":""},{"name":"Anthony Konechny","avatar":""},{"name":"Jonathan Whitesell","avatar":""},{"name":"Chanelle Peloso","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Michael J Rogers","avatar":""},{"name":"Cole Vigue","avatar":""},{"name":"Jessie Fraser","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 17