INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bound', 'Bound', 'Bound', 'https://phimimg.com/upload/vod/20231129-1/2dfd2a4cc7f501a86cb632129930836d.jpg', 'https://phimimg.com/upload/vod/20231129-1/94572b4e7e1145b6408b421c759f0752.jpg', '<p>Con gái của một ông trùm bất động sản giàu có đem lòng yêu một chàng trai trẻ hơn, và cô được giới thiệu với thế giới của BDSM. Với năng lực tình dục mới được đánh thức, cô ấy cuối cùng cũng có thể kiểm soát cuộc sống của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charisma Carpenter","avatar":""},{"name":"Bryce Draper","avatar":""},{"name":"Daniel Baldwin","avatar":""},{"name":"Morgan Obenreder","avatar":""},{"name":"Michael Monks","avatar":""},{"name":"Andy T. Tran","avatar":""},{"name":"Mark McClain Wilson","avatar":""},{"name":"Hayley McLaughlin","avatar":""},{"name":"Noel Arthur","avatar":""},{"name":"Steffinnie Phrommany","avatar":""},{"name":"Terrell Owens","avatar":""},{"name":"Cedric Scott","avatar":""},{"name":"Heather Paige Cohn","avatar":""},{"name":"Lyndsay Haldorson","avatar":""},{"name":"Miss Mia Vixen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
