INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-tu-than-2015', 'Vùng Đất Tử Thần', 'The Dead Lands', 'https://phimimg.com/upload/vod/20231101-1/f414a42d0d227e3957ce6ed02cb3120c.jpg', 'https://phimimg.com/upload/vod/20231101-1/b03372954c6297f4c2e2094310257d14.jpg', '<p>Phim xoay quanh một thanh niên trẻ tuổi tên là Hongi (James Rolleston), anh là con trai của thủ lĩnh của bộ tộc người Maori, những người sống an hòa, trước giờ chưa gây thù chuốc oán với bất kỳ bộ tộc nào khác, điều mà những người dân ở đây mong muốn chính là cuộc sống hòa bình, trôi qua một cách bình yên. Tuy nhiên, một biến cố đã xảy đến khi mà bộ lạc bất ngờ bị tàn sát bởi một tên phản bội, cha của Hongi đã bị kẻ đó sát hại và chàng trai trẻ chính là niềm hi vọng duy nhất để vực lại bộ lạc đang trong cơn hoảng loạn.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"James Rolleston","avatar":""},{"name":"Lawrence Makoare","avatar":""},{"name":"Te Kohe Tuhaka","avatar":""},{"name":"Xavier Horan","avatar":""},{"name":"Raukura Turei","avatar":""},{"name":"George Henare","avatar":""},{"name":"Rena Owen","avatar":""},{"name":"Pana Hema-Taylor","avatar":""},{"name":"Calvin Tuteao","avatar":""},{"name":"Jamus Webster","avatar":""},{"name":"Bianca Hyslop","avatar":""},{"name":"Isabella Rakete","avatar":""},{"name":"Matariki Whatarau","avatar":""},{"name":"Wairangi Koopu","avatar":""},{"name":"Jeff Ruha","avatar":""},{"name":"Kani Collier","avatar":""},{"name":"Te Manaha","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324451);
