INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tinh-2015', 'Yêu Tinh', 'Poltergeist', 'https://phimimg.com/upload/vod/20231024-1/ccf15b8db0f111609259e8b047a254f6.jpg', 'https://phimimg.com/upload/vod/20231024-1/8140329de0d37cf646b9199dc0efb071.jpg', '<p>Được làm lại từ một siêu phẩm kinh dị của thập niên 80, bộ phim Yêu Tinh thu hút người xem bởi nét cổ điển và hiện đại hoà hợp một cách khéo léo. Chuyện kể về một gia đình trẻ 4 người vừa chuyển đến chỗ ở mới. Họ liên tục gặp phải những hiện tượng kỳ lạ trong ngôi nhà mình, từ những âm thanh kỳ lạ đến việc đồ vật di chuyển vô cớ. Cao trào của tất cả là khi cô con gái út bị bắt cóc. Liệu điều gì sẽ xảy ra tiếp theo?</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Saxon Sharbino","avatar":""},{"name":"Kyle Catlett","avatar":""},{"name":"Kennedi Clements","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Susan Heyward","avatar":""},{"name":"Karen Ivany","avatar":""},{"name":"Patrick Garrow","avatar":""},{"name":"Soma Bhatia","avatar":""},{"name":"L.A. Lopes","avatar":""},{"name":"Doug MacLeod","avatar":""},{"name":"Eve Crawford","avatar":""},{"name":"John Stoneham Jr.","avatar":""},{"name":"Kathryn Greenwood","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
