INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-de-chet', 'Ngày Để Chết', 'Date To Die For', 'https://phimimg.com/upload/vod/20231209-1/79a0eaecd8bc12b0b51f961338d8390a.jpg', 'https://phimimg.com/upload/vod/20231209-1/43fd536f047777808e135685c9ca530c.jpg', '<p>Ngày Để Chết - Date To Die For kể về câu chuyện Laura Armstrong là một bà mẹ hai con đang chuẩn bị ly dị chồng là Derek, một luật sư. Những người bạn của cô khuyến khích cô bắt đầu lại bằng cách hẹn hò với Michael Hill, một người cha đã ly hôn. Buổi sáng sau buổi hẹn hò với Michael, Laura thức dậy mà không nhớ gì về đêm hôm trước hay cô đã lên giường với anh ta như thế nào và kinh hoàng khi thấy anh ta nằm cạnh cô với một con dao đâm vào ngực. Cô bị buộc tội giết người và bị tống vào tù. Khi được tại ngoại, Laura bắt đầu chứng minh sự vô tội của mình, đồng thời cũng đấu tranh để giành quyền nuôi con gái.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bart Johnson","avatar":""},{"name":"Jennifer Taylor","avatar":""},{"name":"Victoria Pratt","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
