INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-la-mot-cau-chuyen', 'Tình Yêu Là Một Câu Chuyện', 'Love Is a Story', 'https://phimimg.com/upload/vod/20231129-1/b022bf1ed06f85b7f50271913cd6b5f1.jpg', 'https://phimimg.com/upload/vod/20231129-1/34b7412c36ea159701fa7d4740222291.jpg', '<p>Hai nghệ sĩ trẻ, một nghệ sĩ đàn violin và một nữ diễn viên, vừa tranh đấu để theo đuổi giấc mơ vừa duy trì ngọn lửa tình yêu trong mùa Giáng Sinh.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Romania', 0, '[{"name":"Dragos Bucur","avatar":""},{"name":"Raluca Aprodu","avatar":""},{"name":"Mimi Brănescu","avatar":""},{"name":"Mirela Oprișor","avatar":""},{"name":"Tudor Roșu","avatar":""},{"name":"Vlad Zamfirescu","avatar":""},{"name":"Darie Armin Alexandru","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
