INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-hat-tren-moi', 'Khúc Hát Trên Môi', 'Have a Song on Your Lips', 'https://phimimg.com/upload/vod/20231129-1/8018827edb95e54f2f2534e5f1bd1f58.jpg', 'https://phimimg.com/upload/vod/20231129-1/c56ecbac64512f3d6eaf6859e2193ad4.jpg', '<p>Yuri Kashiwaga từng được biết đến là một nghệ sĩ dương cầm thiên tài. Một ngày nọ, cô từ Tokyo trở về quê hương của mình ở quần đảo Goto. Ở đó, cô bắt đầu làm giáo viên tạm thời tại một trường cấp hai và cố vấn cho dàn đồng ca của trường. Dàn đồng ca nhằm mục đích tham gia một cuộc thi. Yuri giao cho các thành viên trong dàn đồng ca một nhiệm vụ. Cô hướng dẫn họ viết một bức thư với tiêu đề “Gửi bản thân tôi 15 năm sau”. Những cậu bé và cô bé 15 tuổi viết về những bí mật và lo lắng của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yui Aragaki","avatar":""},{"name":"Fumino Kimura","avatar":""},{"name":"Kenta Kiritani","avatar":""},{"name":"Yuri Tsunematsu","avatar":""},{"name":"Shota Shimoda","avatar":""},{"name":"Wakana Aoi","avatar":""},{"name":"Kyoka Shibata","avatar":""},{"name":"Mayu Yamaguchi","avatar":""},{"name":"Hayato Sano","avatar":""},{"name":"Hibiki Muroi","avatar":""},{"name":"Daichi Watanabe","avatar":""},{"name":"Hidekazu Mashima","avatar":""},{"name":"Hikari Ishida","avatar":""},{"name":"Tae Kimura","avatar":""},{"name":"Shigemitsu Ogi","avatar":""},{"name":"Kazue Tsunogae","avatar":""},{"name":"Hisashi Igawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
