INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-dung-den-voi', 'Giáng Sinh Đừng Đến Vội', 'I''m Not Ready for Christmas', 'https://phimimg.com/upload/vod/20231129-1/499df8c31d9a04cbf4dc308d6170c90f.jpg', 'https://phimimg.com/upload/vod/20231129-1/353f3d8659c62db5d02dd1500491a7a4.jpg', '<p>Giáng Sinh Đừng Đến Vội - I&#39;m Not Ready For Christmas xoay quanh cuộc sống của Holly. Cuộc sống tràn đầy năng lượng, tập trung vào sự nghiệp của Holly hoàn toàn đi chệch hướng khi cô phát hiện ra mình không còn có thể nói dối do một điều ước đặc biệt mà cháu gái Anna đã gửi cho ông già Noel. Lúc này, cô phải học cách đánh giá giữa sự thật và những gì là đúng đắn.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alicia Witt","avatar":""},{"name":"George Stults","avatar":""},{"name":"Brigid Brannagh","avatar":""},{"name":"Dan Lauria","avatar":""},{"name":"Mia Bagley","avatar":""},{"name":"Maxwell Caulfield","avatar":""},{"name":"Eli Baldwin","avatar":""},{"name":"Derrick Dean","avatar":""},{"name":"Terance Goodman","avatar":""},{"name":"Chiao-ih Hui","avatar":""},{"name":"Malinda Money","avatar":""},{"name":"Zack Phifer","avatar":""},{"name":"Walter Platz","avatar":""},{"name":"Ash Santos","avatar":""},{"name":"Palmer Scott","avatar":""},{"name":"Joseph Skousen","avatar":""},{"name":"Anne Sward","avatar":""},{"name":"Cathy Tidwell","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324451);
