INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuay-dao-hollywood', 'Khuấy Đảo Hollywood', 'Hollywood Adventures', 'https://phimimg.com/upload/vod/20231129-1/7bbef89fac166a0803f2da2b7e18a36d.jpg', 'https://phimimg.com/upload/vod/20231129-1/611dbdde3349b2001939662b74228a6f.jpg', '<p>Hollywood Adventures, Khuấy Đảo Hollywood, là một bộ phim hài do Mỹ và Trung Quốc hợp tác sản xuất với sự góp mặt của các sao hàng đầu châu Á như Triệu Vy, Huỳnh Hiểu Minh và Đồng Đại Vỹ. Chắc chắn bạn sẽ phì cười trước những tình huống không thể nào đỡ nổi của ba nhân vật chính, một cô hướng dẫn viên bá đạo, một anh chàng si tình đến Mỹ gặp người yêu và một gã nghiện phim nói nhiều.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Wei","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Abby Walker","avatar":""},{"name":"Natalija Ugrina","avatar":""},{"name":"Kat Dennings","avatar":""},{"name":"Rick Chambers","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Lyndall Grant","avatar":""},{"name":"Lauren Daisy White","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324451);
