INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-min', 'Vùng Đất Mìn', 'Land of Mine', 'https://phimimg.com/upload/vod/20231129-1/e377f2f744c0e7a32ba461d3e563abe6.jpg', 'https://phimimg.com/upload/vod/20231129-1/abb368d210c590a05b1d7a45c6661389.jpg', '<p>Đoạn đầu phim là một trường đoạn thực sự kinh dị. Sau khi được học lý thuyết, mỗi tù binh mang một quả mìn vào trong một phòng kín để tháo kíp. Từng người, từng người vào trong phòng, tay run, trán vã mồ hôi trước quả mìn. Đạo diễn phim khai thác sự hồi hộp trong im lặng. Đó là sự im lặng chết chóc. Và khán giả luôn sống trong cảm giác thấp thỏm vì không biết lúc nào mìn sẽ nổ. Bộ phim tập trung vào việc khắc họa số phận của những tù binh sau chiến tranh, khai thác mối quan hệ tâm lý đầy phức tạp giữa bên thắng cuộc (chính nghĩa) với bên thua cuộc (phi nghĩa).</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Roland Møller","avatar":""},{"name":"Louis Hofmann","avatar":""},{"name":"Mikkel Boe Følsgaard","avatar":""},{"name":"Joel Basman","avatar":""},{"name":"Laura Bro","avatar":""},{"name":"Oskar Bökelmann","avatar":""},{"name":"Emil Belton","avatar":""},{"name":"Oskar Belton","avatar":""},{"name":"Leon Seidel","avatar":""},{"name":"Karl Alexander Seidel","avatar":""},{"name":"Maximilian Beck","avatar":""},{"name":"August Carter","avatar":""},{"name":"Tim Bülow","avatar":""},{"name":"Alexander Rasch","avatar":""},{"name":"Julius Kochinke","avatar":""},{"name":"Aaron Koszuta","avatar":""},{"name":"Levin H","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324451);
