INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-lop-mat-na', 'Sau Lớp Mặt Nạ', 'Beyond The Mask', 'https://phimimg.com/upload/vod/20231128-1/657eafaab7a49d7aead0f8237ad94ad5.jpg', 'https://phimimg.com/upload/vod/20231128-1/cb1e8a2fc884127a488c675bf0dbbc9b.jpg', '<p>Sau Lớp Mặt Nạ - Beyond the Mask 2015 là câu chuyện của William, một tay lính đánh thuê bị lừa và phải chạy trốn sang thuộc địa của Mỹ. Để lấy lại danh dự của mình và tình cảm của người phụ nữ mà anh đã đánh mất sự tin tưởng của cô ấy, William giấu mình sau chiếc mặt nạ với hi vọng phá hủy âm mưu của ông chủ cũ. William phải chạy đua với thời gian cùng với sự giúp đỡ của những người bạn Charlotte và Ben Franklin.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Cheney","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Kara Killmer","avatar":""},{"name":"Adetokumboh M''Cormack","avatar":""},{"name":"Steve Blackwood","avatar":""},{"name":"Thomas D. Mahard","avatar":""},{"name":"Marc Bowers","avatar":""},{"name":"Carl Harry Carlson","avatar":""},{"name":"Samrat Chakrabarti","avatar":""},{"name":"Rebekah Cook","avatar":""},{"name":"Connie Craig","avatar":""},{"name":"Jennifer Dixon","avatar":""},{"name":"Dennis Doyle Jr.","avatar":""},{"name":"Alan Madlane","avatar":""},{"name":"Charlie Newhart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
