INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyet-tu-sat', 'Thuyết Tự Sát', 'The Suicide Theory', 'https://phimimg.com/upload/vod/20231129-1/4b7b743aa416ca2667af6ecb66e6363b.jpg', 'https://phimimg.com/upload/vod/20231129-1/22a218e4d7b658bdd85733caa358f082.jpg', '<p>Sau khi người yêu nhất của mình qua đời, Steven rơi vào tình trạng không thể kiểm soát bản thân. Vào một đêm, khi Steven âm mưu vụ giết người tiếp theo, một thi thể rơi thẳng xuống chiếc xe của anh ta. Đó là Percival, người đang muốn tự tử, nhưng bất thành. Trong hoàn cảnh này, Percival đã thuê Steven giúp mình thực hiện kế hoạch. Thế nhưng mọi nỗ lực tự tử đều thất bại một cách thần kỳ. Mỗi người mang một nỗi buồn riêng và dần dần một tình bạn đã được hình thành.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Leon Cain","avatar":""},{"name":"Steve Mazoukis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
