INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-nu-kieu-my', 'Phụ Nữ Kiểu Mỹ', 'Mistress America', 'https://phimimg.com/upload/vod/20231125-1/0140f16ea75bd47728e7ca05a29f4eef.jpg', 'https://phimimg.com/upload/vod/20231125-1/18c198e90a9a14788de3810be2ae25a7.jpg', '<p>Tracy, một sinh viên năm nhất đại học cô đơn ở New York, được giải cứu khỏi sự cô độc bởi người chị kế sắp trở thành Brooke, một cô gái thích phiêu lưu trong thị trấn, người đã lôi kéo cô vào những kế hoạch điên rồ đầy quyến rũ.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Greta Gerwig","avatar":""},{"name":"Lola Kirke","avatar":""},{"name":"Matthew Shear","avatar":""},{"name":"Jasmine Cephas Jones","avatar":""},{"name":"Heather Lind","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"Cindy Cheung","avatar":""},{"name":"Kathryn Erbe","avatar":""},{"name":"Dean Wareham","avatar":""},{"name":"Shana Dowdeswell","avatar":""},{"name":"Shelby Rebecca Wong","avatar":""},{"name":"Alfred Macadam","avatar":""},{"name":"Amy Warren","avatar":""},{"name":"Sharon Washington","avatar":""},{"name":"Morgan Lynch","avatar":""},{"name":"Andrea Chen","avatar":""},{"name":"Shoba","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
