INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-mafia', 'Phi Vụ Mafia', 'Criminal Activities', 'https://phimimg.com/upload/vod/20231125-1/bc9b3ea4f3f52060ffe1f1a4f2ce5bf8.jpg', 'https://phimimg.com/upload/vod/20231125-1/ab90aebe52a35396cab6e02f55960ad1.jpg', '<p>Phi Vụ Mafia (Criminal Activities 2015) là một bộ phim Mỹ thuộc thể loại tội phạm-thriller của đạo diễn Jackie Earle Haley, với sự tham gia của các ngôi sao điện ảnh như John Travolta, Michael Pitt, Dan Stevens, Christopher Abbott, Edi Gathegi, Rob Brown và Jackie Earle Haley. Câu chuyện trong phim xoay quanh 4 chàng trai trẻ gặp phải rắc rối trong một phi vụ đầu tư với băng đảng mafia, kéo theo cả sự tham gia điều tra của phía FBI. Dự kiến, bộ phim này sẽ được ra mắt tại thị trường Mỹ từ ngày 20 tháng 11 năm 2015 bởi hãng Image Entertainment.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Stevens","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Michael Pitt","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Travis Aaron Wade","avatar":""},{"name":"Christopher Abbott","avatar":""},{"name":"Rob Brown","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Morgan Wolk","avatar":""},{"name":"Alan B. Jones","avatar":""},{"name":"Chris Haley","avatar":""},{"name":"Christopher Jay Gresham","avatar":""},{"name":"Bobby C. King","avatar":""},{"name":"Tyrone Jenkins","avatar":""},{"name":"Rex Baker","avatar":""},{"name":"Stan Van Pelt","avatar":""},{"name":"Don Rob","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690