INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-ki-uc', 'Truy Lùng Kí Ức', 'Backtrack', 'https://phimimg.com/upload/vod/20231126-1/2aff77afd046ff8eb15ddcbf43e692e0.jpg', 'https://phimimg.com/upload/vod/20231126-1/87af84e85deec2352e81884bc9213eca.jpg', '<p>Phim Truy Lùng Kí Ức - Backtrack 2016: Peter Bower (Adrien Brody thủ vai) bị ám ảnh bởi những bóng ma trong quá khứ của mình. Là một bác sỹ tâm lý, Peter phải tiếp các bệnh nhân và tư vấn cho họ. Tuy nhiên anh ta không thể ngờ rằng, các bệnh nhân này đều không thực sự tồn tại... Họ là những bóng ma, những câu hỏi mà anh không thể giải đáp. Xuyên suốt bộ phim là những giây phút hồi hộp, gay cấn, có phần ma quái trong cuộc hành trình của Peter Bower tìm lại ký ức bị đánh cắp... “Truy lùng ký ức” hứa hẹn mang đến một câu chuyện “lạnh gáy” cho những khán giả yêu thích thể loại phim kinh dị, bí ẩn.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Malcolm Kennard","avatar":""},{"name":"Chloe Bayliss","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Robin McLeavy","avatar":""},{"name":"Jenni Baird","avatar":""},{"name":"Anna Lise Phillips","avatar":""},{"name":"Olga Miller","avatar":""},{"name":"Michael Whalley","avatar":""},{"name":"Matthew Sunderland","avatar":""},{"name":"George Shevtsov","avatar":""},{"name":"Emma O''Farrell","avatar":""},{"name":"Greg Poppleton","avatar":""},{"name":"Barbara Gouskos","avatar":""},{"name":"Jill McKay","avatar":""},{"name":"Jes","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e