INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-dem-halloween', 'Lời Nguyền Đêm Halloween', 'The Hollow', 'https://phimimg.com/upload/vod/20231125-1/b14ae0cf29ccfa54c3b306d773445e55.jpg', 'https://phimimg.com/upload/vod/20231125-1/4d5cf87d3f787f0c54fa07eccc8e5507.jpg', '<p>Đó là đêm Halloween trên Shelter Island, và thị trấn nhỏ đang chuẩn bị cho một cơn bão giết người. Nhưng những đám mây đen tụ lại trên hòn đảo đang mang theo lời nguyền trăm năm chờ đợi. Khi khu rừng sinh ra một sinh vật vô duyên và vô độ của lửa, xương và đất, ba chị em phải tranh giành để sống sót qua đêm dài tăm tối của Hollow. Vì nó không phải là thứ bạn có thể giết. Đó là thứ duy nhất bạn có thể thử và tồn tại.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephanie Hunt","avatar":""},{"name":"Sarah Dugdale","avatar":""},{"name":"Alisha Newton","avatar":""},{"name":"Hilary Jardine","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Jonathan Whitesell","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Dylan Playfair","avatar":""},{"name":"Michael Adamthwaite","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Laine MacNeil","avatar":""},{"name":"John Hainsworth","avatar":""},{"name":"Natasha Zacher","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
