INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-ca-map', 'Đảo Cá Mập', 'Shark Island', 'https://phimimg.com/upload/vod/20231206-1/1294cd5c58796accff00d9ea52221f51.jpg', 'https://phimimg.com/upload/vod/20231206-1/6a2882dc61c848832696a31053c2fdb7.jpg', '<p>Đảo Cá Mập - Shark Island kể về câu chuyện bốn người bạn cùng nhau đến một hòn đảo để nghỉ dưỡng. Nhưng thật không may, chuyến du lịch mà họ mong đợi bỗng biến thành cuộc chiến sống còn khi con cá mập thử nghiệm điên cuồng tấn công những người dân ở đây.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Becky Andrews","avatar":""},{"name":"Carter Burch","avatar":""},{"name":"Ross Britz","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
