INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-sat-nhan-3', 'Truy Tìm Sát Nhân 3', 'Garage Sale Mystery 3', 'null', 'https://phimimg.com/upload/vod/20231206-1/d55a0b11198ddb14419cbc24d2ed703d.jpg', '<p>Truy Tìm Sát Nhân 3 - Garage Sale Mystery 3 xoay quanh câu chuyện Jennifer trong khi vẫn dùng con mắt tinh tường của mình để tìm kiếm các món hời cho cửa hàng đồ cũ, cô đồng thời cũng giúp bạn của mình là Adrian bán một dinh thự từ thế kỷ 19. Có nhiều truyền thuyết nói rằng ngôi nhà này bị nguyền rủa do có nhiều người đã chết ở đó. Khi Adrian phát trực tiếp quá trình sinh hoạt của mình trong căn dinh thự để chứng minh lời nguyền không có thật, cô được phát hiện đã chết một cách bí ẩn. Mặc dù gặp phải sự ngăn cản của chồng và thanh tra cảnh sát, Jennifer vẫn quyết tâm đi tìm sự thật đằng sau cái chết của bạn mình.</p>', 'Full', 1, 'single', 'completed', 8, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lori Loughlin","avatar":""},{"name":"Sarah Strange","avatar":""},{"name":"Steve Bacic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324451);
