INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-tim-rong', 'Phi Vụ Tìm Rồng', 'Where''s The Dragon?', 'https://phimimg.com/upload/vod/20231125-1/688776926c7dfad5fc7e9c843a00f2de.jpg', 'https://phimimg.com/upload/vod/20231125-1/6148cb43d3ad4caedc0169b8aebe22c9.jpg', '<p>Phim Phi Vụ Tìm Rồng - Where&#39;s The Dragon? 2015: Con giáp Thìn (Rồng) đã mất tích một thời gian khá lâu, khiến thế giới gặp hỗn loạn. Jen - một cô bé 10 tuổi quyết định cùng với những con giáp khác đi tìm Thìn (Rồng) nhằm cứu thế giới và nhân loại. Khi Hoàng Đế nghe tin Thìn (Rồng) đã mất tích hơn trăm năm, Hoàng Đế đã ra lệnh tổ chức một cuộc thi tìm ra con vật khác thay thế Thìn (Rồng). Khắp nơi, các con vật khác đều đến để tham gia. Liệu con vật nào sẽ thắng trong cuộc thi và Jen có tìm lại được Thìn (Rồng)?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leehom Wang","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Fish Leong","avatar":""},{"name":"Michael Wong","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324451);
