INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngua-hoang', 'Ngựa Hoang', 'Wild Horses', 'https://phimimg.com/upload/vod/20231124-1/954fbd6f315483451fb4d119feb53e05.jpg', 'https://phimimg.com/upload/vod/20231124-1/83e89f7a41eb5e567a7681abd6ee2976.jpg', '<p>Kiểm lâm Texas Samantha Payne mở lại vụ án một thiếu niên 15 tuổi mất tích và phát hiện ra bằng chứng cho thấy cậu bé có khả năng bị sát hại tại một trang trại của người đàn ông giàu có trong gia đình, Scott Briggs. Khi đứa con trai bị ghẻ lạnh của Scott bất ngờ trở về nhà trong quá trình điều tra, Samantha càng tin chắc rằng gia đình Briggs có liên quan, và sẽ không dừng lại để khám phá sự thật về cái chết của cậu bé - thậm chí còn khiến tính mạng của cô gặp nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Duvall","avatar":""},{"name":"James Franco","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Luciana Pedraza","avatar":""},{"name":"Angie Cepeda","avatar":""},{"name":"Darien Willardson","avatar":""},{"name":"Joaquin Jackson","avatar":""},{"name":"Christian Jensen","avatar":""},{"name":"Devon Abner","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
