INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-quyen-2015', 'Nữ Quyền', 'Suffragette', 'https://phimimg.com/upload/vod/20231103-1/42a4b451c50294529cd4ebee12d1202c.jpg', 'https://phimimg.com/upload/vod/20231103-1/0d3bccfb833ba072fda90c6270124fdc.jpg', '<p>Phim kể về nhà hoạt động vì nữ quyền Emmeline Pankhurst, người tổ chức các cuộc biểu tình đòi quyền bầu cử cho phái đẹp vào những năm 1900s. Khi các nhà vận động vì quyền phụ nữ nhận thấy rằng cuộc tranh luận của quốc hội là vô ích trong thời kỳ đầu thế kỷ 20, cách duy nhất để tạo áp lực dẫn đến sự thay đổi chính là tìm đến những hành động ngày càng… bạo lực tại các khu nghỉ dưỡng của những người làm việc chính phủ và chống lại họ.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Anne-Marie Duff","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Romola Garai","avatar":""},{"name":"Samuel West","avatar":""},{"name":"Geoff Bell","avatar":""},{"name":"Natalie Press","avatar":""},{"name":"Adrian Schiller","avatar":""},{"name":"Amanda Lawrence","avatar":""},{"name":"Adam Michael Dodd","avatar":""},{"name":"Grace Stottor","avatar":""},{"name":"Lorraine Stanley","avatar":""},{"name":"Morgan Watkins","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324451);
