INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-tu-than', 'Sóng Tử Thần', 'The Wave', 'https://phimimg.com/upload/vod/20231124-1/817658db0a521542d332371c056b13d0.jpg', 'https://phimimg.com/upload/vod/20231124-1/5abdc9950396630fd18202044bac47f2.jpg', '<p>Bộ phim nói về thiên tai ở 1 tỉnh của nước Nauy. Ngọn núi ở tỉnh này có vết nứt và mỗi ngày một tách ra. Và phim nói về ngày định mệnh khi ngọn núi sụp xuống tạo nên sóng thần nhấn chìm 1 vùng vốn đông du khách tham quan vì cảnh quan kỳ vĩ nơi đây. Ngọn núi là có thật và vẫn luôn được quan sát nghiêm ngặt đề phòng tai hoạ có thể ập đến...</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Kristoffer Joner","avatar":""},{"name":"Ane Dahl Torp","avatar":""},{"name":"Jonas Hoff Oftebro","avatar":""},{"name":"Edith Haagenrud-Sande","avatar":""},{"name":"Fridtjov Såheim","avatar":""},{"name":"Laila Goody","avatar":""},{"name":"Arthur Berning","avatar":""},{"name":"Herman Bernhoft","avatar":""},{"name":"Eili Harboe","avatar":""},{"name":"Silje Breivik","avatar":""},{"name":"Håkon Moe","avatar":""},{"name":"Tyra Holmen","avatar":""},{"name":"Thomas Bo Larsen","avatar":""},{"name":"Mette Agnete Horn","avatar":""},{"name":"Lado Hadzic","avatar":""},{"name":"Tom Larsen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324451);
