INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhen-lua-khong-lo', 'Nhện Lửa Khổng Lồ', 'Lavalantula', 'https://phimimg.com/upload/vod/20231124-1/988fd5c274c5c9a2bdbb84758149de5d.jpg', 'https://phimimg.com/upload/vod/20231124-1/570c80ef765164953ddd1e1db37f8ac5.jpg', '<p>Tarantulas thở dung nham khổng lồ - Lavalantulas - phun ra từ những ngọn núi lửa cổ xưa ở Dãy núi Santa Monica, trút cơn mưa chết chóc và hủy diệt xuống Los Angeles. Với Thành phố của các Thiên thần đang trên bờ vực bị thiêu hủy, chỉ có một diễn viên anh hùng hành động của thập niên 90 mới có thể cản đường lũ sinh vật khát máu khổng lồ thiêu sống nạn nhân của chúng.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Guttenberg","avatar":""},{"name":"Nia Peeples","avatar":""},{"name":"Patrick Renna","avatar":""},{"name":"Carlos Bernard","avatar":""},{"name":"Michael Winslow","avatar":""},{"name":"Marion Ramsey","avatar":""},{"name":"Leslie Easterbrook","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"Danny Woodburn","avatar":""},{"name":"Noah Hunt","avatar":""},{"name":"Diana Hopper","avatar":""},{"name":"Time Winters","avatar":""},{"name":"Ian Ziering","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Zac Goodspeed","avatar":""},{"name":"Leeann Tweeden","avatar":""},{"name":"Jessica McMi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
