INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhen-lua-khong-lo', 'Nhện Lửa Khổng Lồ', 'Lavalantula', 'nhện lửa khổng lồ lavalantula steve guttenberg nia peeples patrick renna carlos bernard michael winslow marion ramsey leslie easterbrook ralph garman danny woodburn noah hunt diana hopper time winters ian ziering leigh whannell zac goodspeed leeann tweeden jessica mcmi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-cuoc', 'Chiến Cuộc', 'A War - Krigen', 'https://phimimg.com/upload/vod/20231124-1/2c06905140b93954b5d2bf0d13053eb2.jpg', 'https://phimimg.com/upload/vod/20231124-1/08fcb2d4d7d61310dc48e5172d2d976d.jpg', '<p>Bộ phim A War - Krigen (Chiến Cuộc) là một bộ phim có đề tài chiến tranh của Đan Mạch năm 2015 kịch bản và đạo diễn bởi Tobias Lindholm, và có sự tham gia của Pilou Asbæk và Søren Malling.
 Nội dung phim kể về Đại đội trưởng Claus M. Pedersen (Pilou Asbæk) và lính của anh ta đang đóng quân ở Helmand Province, một quận của Afghanistan, nổi tiếng khốc liệt. Trong khi đó ở Đan Mạch, Maria (Tuva Novotny) vợ Claus vẫn đang cố gắng cân bằng cuộc sống của mình khi chồng đang ở chiến trận, cùng ba đứa nhỏ một tay chăm sóc. Trong một nhiệm vụ tuần tra, Claus đã phải chiến đấu với kẻ thù, và với chính bản thân. Giữa làn đạn khốc liệt, với những con người đặt trọn niềm tin và lẽ sống nơi anh, là bao gia đình chờ con mỏi mòn, là lý tưởng sống mà anh hằng theo đuổi... Và để cứu lấy các đồng đội của mình, Claus đã phải đưa ra một quyết định gây hậu quả nghiêm trọng cho chính mình và gia đình mình ở quê nhà...</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Pilou Asbæk","avatar":""},{"name":"Tuva Novotny","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Charlotte Munck","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Dulfi Al-Jabouri","avatar":""},{"name":"Alex Høgh Andersen","avatar":""},{"name":"Jakob Frølund","avatar":""},{"name":"Phillip Sem Dambæk","avatar":""},{"name":"Petrine Agger","avatar":""},{"name":"Martin Tamm Andersen","avatar":""},{"name":"Christian ''Krølle'' Pedersen","avatar":""},{"name":"Andre Fog Sorensen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324451);
