INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-cuoc', 'Chiến Cuộc', 'A War - Krigen', 'chiến cuộc a war - krigen pilou asbæk tuva novotny søren malling charlotte munck dar salim dulfi al-jabouri alex høgh andersen jakob frølund phillip sem dambæk petrine agger martin tamm andersen christian ''krølle'' pedersen andre fog sorensen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-hoai', 'Kẻ Hủy Hoại', 'Demolition', 'https://phimimg.com/upload/vod/20231124-1/acf139b1dc6bfcd80afb61c1dbe99532.jpg', 'https://phimimg.com/upload/vod/20231124-1/d1d1b3c54b036ff1ccad54e248220a84.jpg', '<p>Demolition kể về một nhân viên ngân hàng đầu tư thành công Davis, người đang vượt qua nỗi đau mất vợ sau một tai nạn xe hơi thảm khốc. Mặc cho mọi nỗ lực từ cha vợ để hàn gắn vết thương lòng, Davis vẫn tiếp tục sống buông thả. Rồi một chuỗi sự kiện xảy ra bắt đầu từ một lá thư vớ vẩn khiếu nại máy bán hàng tự động của Davis, anh tạo được sự chú ý với một nhân viên phòng chăm sóc khách hàng là Karen. Những lá thư khiếu nại vô tình kéo 2 người lại gần nhau. Bằng sự giúp đỡ của Karen và cậu con trai nổi loạn Chris, Davis quyết định làm lại cuộc đời mình mà bước khởi đầu là phá huỷ cuộc sống mà anh từng có.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Judah Lewis","avatar":""},{"name":"C.J. Wilson","avatar":""},{"name":"Polly Draper","avatar":""},{"name":"Malachy Cleary","avatar":""},{"name":"Debra Monk","avatar":""},{"name":"Heather Lind","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Blaire Brooks","avatar":""},{"name":"Ben Cole","avatar":""},{"name":"Brendan Dooling","avatar":""},{"name":"Madison Arnold","avatar":""},{"name":"James Colby","avatar":""},{"name":"Alfredo Narciso","avatar":""},{"name":"Gregory Haney","avatar":""},{"name":"James Young","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
