INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-am-sat-liveaction', 'Lớp Học Ám Sát (Live-Action)', 'Assassination Classroom (Live-Action)', 'https://phimimg.com/upload/vod/20231121-1/b4a75f72494438eec87f7b40acbc013f.jpg', 'https://phimimg.com/upload/vod/20231121-1/082894a04a498b1d3b49d95ddd19cb99.jpg', '<p>Câu chuyện bắt đầu với sự kiện 70% của mặt trăng đột nhiên biến mất trong một vụ nổ. Siêu thực thể gây ra thảm họa này là một sinh vật xúc tu kì lạ có khả năng di chuyển với tốc độ siêu thanh - Mach 20. Giải thưởng treo trên đầu sinh vật này lên đến 10 tỉ yên (100 triệu USD), nhưng vì lí do nào đó, hắn lại trở thành giáo viên chủ nhiệm một lớp trung học vào đầu năm học. Toàn bộ học sinh trong lớp từ lúc đó đến cuối năm học phải ám sát được &quot;giáo viên&quot; này, nếu không hắn sẽ hủy diệt Trái đất.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazunari Ninomiya","avatar":""},{"name":"Ryosuke Yamada","avatar":""},{"name":"Masaki Suda","avatar":""},{"name":"Maika Yamamoto","avatar":""},{"name":"Haruka","avatar":""},{"name":"Mio Yuki","avatar":""},{"name":"Miku Uehara","avatar":""},{"name":"Kippei Shiina","avatar":""},{"name":"Kouki Osamura","avatar":""},{"name":"Takumi Ooka","avatar":""},{"name":"Saki Takahashi","avatar":""},{"name":"Yuuhi Kato","avatar":""},{"name":"Kang Ji-young","avatar":""},{"name":"Ami Okuma","avatar":""},{"name":"Jitsunori Uehera","avatar":""},{"name":"Kanon Miyahara","avatar":""},{"name":"Ken Sugawara","avatar":""},{"name":"Yuji Takao","avatar":""},{"name":"Ren","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324451);
