INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lop-hoc-am-sat-liveaction', 'Lớp Học Ám Sát (Live-Action)', 'Assassination Classroom (Live-Action)', 'lớp học ám sát (live-action) assassination classroom (live-action) kazunari ninomiya ryosuke yamada masaki suda maika yamamoto haruka mio yuki miku uehara kippei shiina kouki osamura takumi ooka saki takahashi yuuhi kato kang ji-young ami okuma jitsunori uehera kanon miyahara ken sugawara yuji takao ren ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sau-15-nam', 'Cuộc Chiến Sau 15 Năm', 'Dilwale', 'https://phimimg.com/upload/vod/20231121-1/6b5c9b60e0afa70325de709158bc508f.jpg', 'https://phimimg.com/upload/vod/20231121-1/aa074703ad7451aee22a60ddc036836d.jpg', '<p>Raj là một thành viên Mafia. Một ngày nọ, anh gặp một cô gái (Meera) khi đang bị băng nhóm đối thủ truy đuổi và yêu cô ấy. Sau đó, anh phát hiện ra rằng cô gái này là con gái của thủ lĩnh băng nhóm đối thủ của anh. Tuy nhiên, câu chuyện tình yêu của họ vẫn tiếp tục cho đến khi anh bị bạn gái bắn chết vì hiểu lầm sâu sắc. Sau sự cố đó, hai người yêu nhau sống ly thân cho đến khi anh chị em của họ yêu nhau. Với câu chuyện tình yêu mới này, con đường của họ lại đan xen vào nhau.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Kajol","avatar":""},{"name":"Varun Dhawan","avatar":""},{"name":"Kriti Sanon","avatar":""},{"name":"Boman Irani","avatar":""},{"name":"Johnny Lever","avatar":""},{"name":"Sanjay Mishra","avatar":""},{"name":"Kabir Bedi","avatar":""},{"name":"Mukesh Tiwari","avatar":""},{"name":"Vinod Khanna","avatar":""},{"name":"Nawab Shah","avatar":""},{"name":"Pankaj Tripathi","avatar":""},{"name":"Varun Sharma","avatar":""},{"name":"Vineet Sharma","avatar":""},{"name":"Chetna Pande","avatar":""},{"name":"Murali Sharma","avatar":""},{"name":"Stuti Dixit","avatar":""},{"name":"Naushaad Abbas","avatar":""},{"name":"Pradee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
