INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-sau-15-nam', 'Cuộc Chiến Sau 15 Năm', 'Dilwale', 'cuộc chiến sau 15 năm dilwale shah rukh khan kajol varun dhawan kriti sanon boman irani johnny lever sanjay mishra kabir bedi mukesh tiwari vinod khanna nawab shah pankaj tripathi varun sharma vineet sharma chetna pande murali sharma stuti dixit naushaad abbas pradee ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-con-vit-vang', '12 Con Vịt Vàng', '12 Golden Ducks', 'https://phimimg.com/upload/vod/20231120-1/e29d30abb5d129f3da1c3863312035b8.jpg', 'https://phimimg.com/upload/vod/20231120-1/a1cd91104b90f0da9d49c5f1f9ab69ba.jpg', '<p>Bị tàn phá bởi một mối tình, cựu gigolo Future Chang rút lui đến Thái Lan, dẫn đến cuộc sống phóng túng. Nhờ sự can thiệp của giáo viên trung học, ông Lo, Future mới có được can đảm để quay trở lại Hồng Kông. Với sự giúp đỡ của người bạn Ricky, một huấn luyện viên thể dục, anh ấy đã tập luyện chăm chỉ để lấy lại vóc dáng, quyết tâm quay trở lại với nghề buôn “vịt”. Trước sự ngạc nhiên của Future’s, Hong Kong đã trải qua một sự thay đổi đáng kể kể từ khi anh rời thành phố. Ngay cả các quy tắc buôn bán vịt cũng đã hoàn toàn thay đổi! Để tập trung vào việc buôn bán của mình, Future đã giảm bớt việc tìm kiếm khách hàng tại một nhà dưỡng lão dành cho phụ nữ. Trong khi đó, những nơi mà phụ nữ có thể mua được hạnh phúc đã trở nên dễ tiếp cận hơn nhiều, hoạt động tại các cơ sở lân cận như nhà hàng Thái…</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Pakho Chau","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Wyman Wong Wai-Man","avatar":""},{"name":"Carman Lee","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Lisa Lu","avatar":""},{"name":"Fiona Sit","avatar":""},{"name":"Joey Yung","avatar":""},{"name":"Eason Chan","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Isabella Leong","avatar":""},{"name":"Simon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
