INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tuy-tung', 'Đoàn Tùy Tùng', 'Entourage', 'https://phimimg.com/upload/vod/20231120-1/6247707210c4d13c2b1c8f970178331a.jpg', 'https://phimimg.com/upload/vod/20231120-1/7c15d9e618f3a786e384b9c3b1b59ea5.jpg', '<p>Ngôi sao điện ảnh Vincent Chase, cùng với các cậu con trai của anh ấy, Eric, Turtle và Johnny, đã trở lại… và trở lại công việc kinh doanh với Ari Gold, người đứng đầu hãng phim chuyển sang làm siêu đặc vụ. Một số tham vọng của họ đã thay đổi, nhưng mối quan hệ giữa họ vẫn bền chặt khi họ điều hướng thế giới Hollywood thất thường và thường xuyên khốc liệt.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Connolly","avatar":""},{"name":"Adrian Grenier","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Rex Lee","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Constance Zimmer","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Ronda Rousey","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Emily Ratajkowski","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324451);
