INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-vua-su-tu-2-noi-day', 'Truyền Thuyết Vua Sư Tử 2: Nổi Dậy', 'Richard the Lionheart: Rebellion', 'https://phimimg.com/upload/vod/20231203-1/25a2a4648f38e1f3ce60123bdf6df184.jpg', 'https://phimimg.com/upload/vod/20231203-1/2dd4e9417874762c06545e5c6e3140d6.jpg', '<p>Truyền Thuyết Vua Sư Tử 2: Nổi Dậy - Richard The Lionheart Rebellion kể về cuộc chiến giữa hai cường quốc Anh và Pháp. Các con trai của nhà vua Anh là Henry, Richard và Geoffrey, dẫn đầu một cuộc nổi dậy chống lại chính cha của mình. Họ được nhà vua Pháp, Louis và đặc biệt là người mẹ mang dòng máu nước Pháp của họ, Eleanor ủng hộ trong cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Valeri Alessandro","avatar":""},{"name":"Elisa Allara","avatar":""},{"name":"Lucia Allara","avatar":""},{"name":"Derek Allen","avatar":""},{"name":"Brian Ayres","avatar":""},{"name":"Christian Burruano","avatar":""},{"name":"David Callahan","avatar":""},{"name":"Andrea Lorenzo Canetto","avatar":""},{"name":"Mishaël Lopes Cardozo","avatar":""},{"name":"Davide Chiolero","avatar":""},{"name":"Neil Cole","avatar":""},{"name":"Maurizio Corigliano","avatar":""},{"name":"Emil Corradin","avatar":""},{"name":"Irene Corradin","avatar":""},{"name":"Jon Firman","avatar":""},{"name":"Greg Ma","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324451);
