INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-chon-dung-than', 'Tìm Chốn Dung Thân', 'Hidden', 'https://phimimg.com/upload/vod/20231123-1/6f23533ead290282ec7ba3a38d4ab17c.jpg', 'https://phimimg.com/upload/vod/20231123-1/96b9e72e16d851918c2e7ac0cb76a599.jpg', '<p>Một gia đình tìm chỗ ẩn nấp sau khi vùng họ ở nhiễm chất phóng xạ.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"Heather Doerksen","avatar":""},{"name":"William Ainscough","avatar":""},{"name":"David James Lewis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
