INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tim-chon-dung-than', 'Tìm Chốn Dung Thân', 'Hidden', 'tìm chốn dung thân hidden alexander skarsgård andrea riseborough emily alyn lind heather doerksen william ainscough david james lewis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-con-dam-bich', 'Lời Nguyền Con Đầm Bích', 'Queen Of Spades: The Dark Rite', 'https://phimimg.com/upload/vod/20231123-1/80d913c07975533533f0a10c338a30c3.jpg', 'https://phimimg.com/upload/vod/20231123-1/56c82bebfdcf1abd8c7cbb854dde754e.jpg', '<p>Truyền thuyết kể rằng bất kỳ một chiếc gương nào cũng có thể mở cánh cổng kết nối đến thế giới của người chết, trong đó một nghi lễ cổ xưa vẫn còn được lưu truyền đến ngày nay về cách triệu tập một linh hồn mang tên Đầm Bích. Một nhóm các bạn trẻ đã triệu tập Đầm Bích và không thể ngờ chính hành động đó đã mở ra một cánh cổng kết nối với thế giới tâm linh đầy ma quái, u uất và phẫn nộ. Họ không chỉ đẩy bản thân vào sự nguy hiểm mà còn lôi kéo thêm nhiều người bạn khác xung quanh mình, để rồi khi hối tiếc thì đã muộn.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Alina Babak","avatar":""},{"name":"Valeriya Dmitrieva","avatar":""},{"name":"Igor Khripunov","avatar":""},{"name":"Evgeniya Loza","avatar":""},{"name":"Sergey Pokhodaev","avatar":""},{"name":"Valentin Sadiki","avatar":""},{"name":"Vladimir Seleznyov","avatar":""},{"name":"Mariya Fomina","avatar":""},{"name":"Maxim Stoyanov","avatar":""},{"name":"Natalia Domeretskaya","avatar":""},{"name":"Dmitry Kulichkov","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324451);
