INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-nguyen-con-dam-bich', 'Lời Nguyền Con Đầm Bích', 'Queen Of Spades: The Dark Rite', 'lời nguyền con đầm bích queen of spades: the dark rite alina babak valeriya dmitrieva igor khripunov evgeniya loza sergey pokhodaev valentin sadiki vladimir seleznyov mariya fomina maxim stoyanov natalia domeretskaya dmitry kulichkov ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-lua', 'Thánh Lừa', 'Focus', 'https://phimimg.com/upload/vod/20231123-1/d4ceecb9ecfc73162798264a2b3b3acf.jpg', 'https://phimimg.com/upload/vod/20231123-1/e4ee4b74d168bf273605eef43b07fee8.jpg', '<p>Focus có bối cảnh ở một thành phố lớn của nước Mỹ ngày nay. Vào một buổi tối, một cô gái trẻ gợi cảm chèo kéo gã trung niên lên phòng khách sạn để lừa đảo nhằm cuỗm tiền nhưng lại phát hiện ra gã là bậc thầy trên cơ. Có chút cảm mến và thương cô gái mới vào nghề tên Jess (Margot Robbie), &quot;thánh lừa&quot; Nicky (Will Smith) quyết định thu nhận cô làm đệ tử, dạy cô mánh lới để có thể đi móc ví nhà giàu kiếm cơm.Chẳng mấy chốc, cô bé lanh lợi trở nên xuất sắc nhưng vẫn không quên ơn sư phụ, thậm chí là phải lòng anh. Thế rồi, Nicky cũng đem lòng yêu Jess. Họ qua đêm cùng nhau, đi du lịch hưởng trăng mật... Tuy nhiên, vì lo lắng rằng hai kẻ lừa đảo thì không thể tin nhau được, họ chia tay. Ba năm sau, hai người bất ngờ chạm trán ...</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Gerald McRaney","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Robert Taylor","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Brennan Brown","avatar":""},{"name":"Dominic Fumusa","avatar":""},{"name":"Dotan Bonen","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"David Stanford","avatar":""},{"name":"Steve Kim","avatar":""},{"name":"Don Yesso","avatar":""},{"name":"Juan Minujín","avatar":""},{"name":"Jano Seitun","avatar":""},{"name":"Melania Lenoir","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324451);
