INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-mcfarland-hoa-ky', 'Trường Mcfarland, Hoa Kỳ', 'McFarland, USA', 'trường mcfarland, hoa kỳ mcfarland, usa kevin costner ramiro rodriguez maria bello johnny ortiz diana maria riva elsie fisher valente rodriguez morgan saylor martha higareda carlos pratts rafael martinez hector duran sergio avelar michael aguero omar leyva danny mora ben hernand ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('va-noi-day-binh-minh-yen-tinh', 'Và Nơi Đây Bình Minh Yên Tĩnh', 'The Dawns Here Are Quiet', 'https://phimimg.com/upload/vod/20231123-1/a3d3819f016c2e5f073f3c170ae4505b.jpg', 'https://phimimg.com/upload/vod/20231123-1/11ce18df9c77ff77a2b6aa14e397a6ce.jpg', '<p>Đó là vào cuối mùa xuân năm 1942, và Chiến tranh Vệ quốc Vĩ đại đang diễn ra sôi nổi. Cách xa tiền tuyến, tại một ngã ba bị Chúa lãng quên nào đó, quân Đức thực hiện một chiến dịch đổ bộ đường không nhằm cố gắng vượt qua tuyến đường sắt Kirov và Biển Trắng - Kênh Biển Baltic. Đây không chỉ là những người lính nhảy dù thông thường. Đây là một nhóm gồm những kẻ xâm nhập dày dạn kinh nghiệm và được đào tạo bài bản, những người ưu tú của Waffen-SS, những siêu nhân. Điều duy nhất cản đường họ là một đơn vị pháo phòng không gồm hạ sĩ Vaskov và năm phụ nữ trẻ đang được huấn luyện. Nó có vẻ giống như một cuộc chiến mang ý nghĩa địa phương, nhưng huyết mạch giao thông chiến lược chính của đất nước đang bị đe dọa. Liệu hạ sĩ và &#39;người mới nhỏ nhắn&#39; của anh ta có thể ngăn chặn sự phá hoại của Đức Quốc xã hay không và với cái giá nào?</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Pyotr Fyodorov","avatar":""},{"name":"Anastasiya Mikulchina","avatar":""},{"name":"Evgenia Malakhova","avatar":""},{"name":"Kristina Asmus","avatar":""},{"name":"Sofia Lebedeva","avatar":""},{"name":"Agniya Kuznetsova","avatar":""},{"name":"Ekaterina Vilkova","avatar":""},{"name":"Anatoliy Belyy","avatar":""},{"name":"Darya Moroz","avatar":""},{"name":"Viktor Proskurin","avatar":""},{"name":"Maksim Drozd","avatar":""},{"name":"Olga Lomonosova","avatar":""},{"name":"Natalya Batrak","avatar":""},{"name":"Ilya Alekseev","avatar":""},{"name":"Valeriy Grishko","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324451);
