INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('steve-jobs-nguoi-dan-ong-cung-nhac', 'Steve Jobs: Người Đàn Ông Cứng Nhắc', 'Steve Jobs: The Man in the Machine', 'https://phimimg.com/upload/vod/20231120-1/892858078a383a7c3b114e318e19e8ac.jpg', 'https://phimimg.com/upload/vod/20231120-1/aabf7637db42b2e9697b76c7b00cd428.jpg', '<p>Khi Steve Jobs qua đời cả thế giới đã khóc. Nhưng điều gì đã gây ra nỗi đau buồn của hàng triệu người không biết anh ấy? Bộ phim giàu sức gợi này điều hướng con đường của Jobs từ một ngôi nhà nhỏ ở vùng ngoại ô, đến những ngôi chùa thiền ở Nhật Bản, đến văn phòng CEO của công ty giàu nhất thế giới, khám phá cuộc sống và công việc của Jobs đã định hình mối quan hệ của chúng ta với máy tính như thế nào. The Man in the Machine là một sự đánh giá lại đầy khiêu khích và đôi khi gây sửng sốt về di sản của một biểu tượng.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Belleville","avatar":""},{"name":"Chrisann Brennan","avatar":""},{"name":"Nolan Bushnell","avatar":""},{"name":"Jason Chen","avatar":""},{"name":"Nick Denton","avatar":""},{"name":"Jesus Diaz","avatar":""},{"name":"Peter Elkind","avatar":""},{"name":"Alex Gibney","avatar":""},{"name":"Andy Grignon","avatar":""},{"name":"Steve Jobs","avatar":""},{"name":"Yukari Iwatani Kane","avatar":""},{"name":"Daniel Kottke","avatar":""},{"name":"Brian Lam","avatar":""},{"name":"Regis McKenna","avatar":""},{"name":"Joe Nocera","avatar":""},{"name":"Ridley Scott","avatar":""},{"name":"Andrew Serwer","avatar":""},{"name":"Sherry Turkl","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324451);
