INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-chat', 'Biến Chất', 'Corrupt', 'https://phimimg.com/upload/vod/20231120-1/5d0a09c7ddd7f48b02e70b7b8a7c663d.jpg', 'https://phimimg.com/upload/vod/20231120-1/5685b648d8a0812f85c5d9e320512b50.jpg', '<p>Biến Chất - Corrupt xoay quanh trợ lý D.A. Kate MacIntyre đang thực hiện vụ án về Vargano thì hai người đàn ông chủ chốt của vụ truy tố bị giết bởi một tay súng bắn tỉa ngay trước mặt cô. Cảm thấy kinh hoàng trước những vụ giết người, Kate từ bỏ vị trí của mình để trở thành một giảng viên. Nhưng khi sếp cũ của cô, D.A. Frank Murphy, nhờ cô giúp đỡ, cô đồng ý làm cố vấn cùng với Frank và Greg Nealand, trợ lý mới của D.A. Nhưng sự trở lại của Kate khiến cuộc sống của cô rơi vào nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nicole de Boer","avatar":""},{"name":"Scott Gibson","avatar":""},{"name":"Peter Michael Dillon","avatar":""},{"name":"Steve Baran","avatar":""},{"name":"Allison Brennan","avatar":""},{"name":"Victor Cornfoot","avatar":""},{"name":"Jon McLaren","avatar":""},{"name":"Sean Tucker","avatar":""},{"name":"Alix Sideris","avatar":""},{"name":"Julia A. Long","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324451);
