INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-troi-day', 'Tội Ác Trỗi Dậy', 'The Rise of the Krays', 'https://phimimg.com/upload/vod/20231120-1/9c8716525775fa48c4210e38f579f44c.jpg', 'https://phimimg.com/upload/vod/20231120-1/b7a183c938b3b2771057df4d19d2c9f2.jpg', '<p>Theo dõi những năm đầu của hai võ sĩ nghiệp dư 18 tuổi vô danh, những người nhanh chóng chiến đấu để trở thành những kẻ ác đáng sợ và được kính trọng nhất ở London. Được kể qua con mắt của một người bạn thân đã sống sót sau họ, chúng ta thấy họ trở nên khét tiếng nhờ ma túy, tình dục và giết người.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kevin Leslie","avatar":""},{"name":"Simon Cotton","avatar":""},{"name":"Phil Dunster","avatar":""},{"name":"Danny Midwinter","avatar":""},{"name":"Dan Parr","avatar":""},{"name":"Alexa Morden","avatar":""},{"name":"Philip Prajoux","avatar":""},{"name":"Georg Nikoloff","avatar":""},{"name":"Helen Millar","avatar":""},{"name":"James Hepburn","avatar":""},{"name":"Richard Goss","avatar":""},{"name":"Mariola Jaworska","avatar":""},{"name":"Nicola Stapleton","avatar":""},{"name":"Jeana Brock","avatar":""},{"name":"Oengus MacNamara","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324451);
