INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-tinh-yeu', 'Kho báu tình yêu', 'Prem Ratan Dhan Payo', 'https://phimimg.com/upload/vod/20231120-1/e41bb5be221f4e76f4960a908242c311.jpg', 'https://phimimg.com/upload/vod/20231120-1/894588a18fd9056b08b2cec85fdb202e.jpg', '<p>Trong khi hồi phục sau vụ ám sát bốn ngày trước lễ đăng quang, một hoàng tử nghiêm nghị có thế thân là một người ngoại hình giống hệt, nhưng đầy vui vẻ và hào phóng.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Sonam Kapoor Ahuja","avatar":""},{"name":"Neil Nitin Mukesh","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Swara Bhasker","avatar":""},{"name":"Deepak Dobriyal","avatar":""},{"name":"Arman Kohli","avatar":""},{"name":"Manoj Joshi","avatar":""},{"name":"Bikramjeet Kanwarpal","avatar":""},{"name":"Deepraj Rana","avatar":""},{"name":"Samaira Rao","avatar":""},{"name":"Sanjay Mishra","avatar":""},{"name":"S M Zaheer","avatar":""},{"name":"Manoj Joshi","avatar":""},{"name":"Lata Sabharwal","avatar":""},{"name":"Karuna Pandey","avatar":""},{"name":"Suhasini Mul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
