INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-thieng', 'Máu Thiêng', 'Sacred Blood', 'https://phimimg.com/upload/vod/20231120-1/dad3c7e42dc38281a813f75dbc97c6cc.jpg', 'https://phimimg.com/upload/vod/20231120-1/30884bc980433d268eaf9a706a864690.jpg', '<p>Trong cuộc chiến đấu chống lại sự cô đơn của Natalie và các quy tắc của thế giới mới này, cô kết bạn với một nghệ sĩ trẻ khó khăn với một tâm hồn vô cùng ngây thơ. Liệu tình yêu mong manh này sẽ đưa cô thoát khỏi rắc rối hay cả hai sẽ bị kéo vào bóng tối?</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Biani","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Konstantin Kryukov","avatar":""},{"name":"Rob Nilsson","avatar":""},{"name":"Kato Kaelin","avatar":""},{"name":"Bailey Coppola","avatar":""},{"name":"Bayra Bela","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324452);
