INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-kieu-murray', 'Giáng sinh kiểu Murray', 'A Very Murray Christmas', 'https://phimimg.com/upload/vod/20231120-1/7fce0687b3f8dc332645e246a8d500c9.jpg', 'https://phimimg.com/upload/vod/20231120-1/4d26ffb02479df62f635d8a8b0fb8425.jpg', '<p>Bill Murray tập hợp dàn diễn viên toàn ngôi sao cho buổi biểu diễn âm nhạc, hài kịch và khiêu vũ thân mật, tạo nên một nét khác lạ cho chương trình tạp kỹ lễ hội này.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Paul Shaffer","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Miley Cyrus","avatar":""},{"name":"Dimitri Dimitrov","avatar":""},{"name":"David Johansen","avatar":""},{"name":"Rashida Jones","avatar":""},{"name":"Jenny Lewis","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Julie White","avatar":""},{"name":"Thomas Mars","avatar":""},{"name":"Deck D''arcy","avatar":""},{"name":"Laurent Brancowitz","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324452);
