INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-phu-thuy', 'Cây Phù Thủy', 'Curse of the Witching Tree', 'https://phimimg.com/upload/vod/20231201-1/54ad923d9990135c80033a8bba3c3c49.jpg', 'https://phimimg.com/upload/vod/20231201-1/f8c23acfc71b18ce8c12d73742de4345.jpg', '<p>Phim Cây Phù Thủy - Curse Of The Witching Tree (2015): Một người phụ nữ bị buộc tội giết hại con trai mình và bị treo cổ như một phù thủy, nguyền rủa lên cái cây và những đứa trẻ chơi xung quanh đó. Hành động trả thù này âm vang mãi suốt nhiều thế kỉ, và những linh hồn không ngừng ám ngôi nhà nơi xác những đứa trẻ bị nguyền rủa được chôn. Một gia đình chuyển đến ngôi nhà mới, và bắt đầu khám phá ra sự thật kinh khủng đằng sau cái cây &#39;phù thủy&#39; và những đứa trẻ bị sát hại trên đó đang trải qua giấc ngủ vô thức.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lucy Clarvis","avatar":""},{"name":"Sarah Rose Denton","avatar":""},{"name":"Jon Campling","avatar":""},{"name":"Lawrence Weller","avatar":""},{"name":"Caroline Boulton","avatar":""},{"name":"Danielle Bux","avatar":""},{"name":"Alex Reece","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324452);
