INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cay-phu-thuy', 'Cây Phù Thủy', 'Curse of the Witching Tree', 'cây phù thủy curse of the witching tree lucy clarvis sarah rose denton jon campling lawrence weller caroline boulton danielle bux alex reece ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-nguoi-qua-duong', 'Tôi Là Người Qua Đường', 'I Am Somebody', 'https://phimimg.com/upload/vod/20231201-1/a66c981d12d145c2182adea19ae558e6.jpg', 'https://phimimg.com/upload/vod/20231201-1/b01af15bc45579da3abb89cc13e3510f.jpg', '<p>I Am Somebody có nội dung đơn giản, không cầu kỳ nhưng vẫn đủ sức hút và ý nghĩa. Xoay quanh nhân vật Vạn Quốc Bằng, phim tập trung khai thác cuộc sống của những diễn viên chỉ chuyên đóng vai phụ, vai quần chúng. Thông qua những câu chuyện nhỏ về cuộc sống và công việc của họ, người xem dần nhận ra giá trị, mục đích sống và cống hiến của những con người vô danh, ít được công chúng quan tâm, chú ý tới. Với họ, dù vai diễn nhỏ đến đâu cũng góp phần tạo nên một bộ phim hoàn chĩnh. Cũng giống như trong cuộc sống, mỗi người đều có vai trò và giá trị nhất định trong xã hội.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wan Guopeng","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Kai Shen","avatar":""},{"name":"Bao Xiaoping","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Ting Wang","avatar":""},{"name":"Xu Xiaoqin","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Ann Hui","avatar":""},{"name":"Derek Yee Tung-Sing","avatar":""},{"name":"Wang Wanzhong","avatar":""},{"name":"Alan Mak","avatar":""},{"name":"Felix Chong Man-keung","avatar":""},{"name":"Ku Kuan-Chung","avatar":""},{"name":"Henry Fong","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Ronald Wong Ban","avatar":""},{"name":"Ko","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324452);
