INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lion-guard-return-of-the-roar', 'The Lion Guard: Return of the Roar', 'The Lion Guard: Return of the Roar', 'https://phimimg.com/upload/vod/20231201-1/eafc1c84f1aee948959d75b4ba248f8f.jpg', 'https://phimimg.com/upload/vod/20231201-1/badd90217ed2a4a8a15cf66b87305c75.jpg', '<p>Lấy bối cảnh ở thảo nguyên châu Phi, bộ phim theo chân Kion khi anh tập hợp các thành viên của &quot;Đội bảo vệ sư tử&quot;. Xuyên suốt bộ phim, nhóm động vật trẻ đa dạng sẽ học cách sử dụng từng khả năng riêng biệt của mình để giải quyết vấn đề và hoàn thành nhiệm vụ nhằm duy trì sự cân bằng trong Vòng tròn Sự sống, đồng thời giới thiệu cho người xem về vô số loài động vật sinh sống ở Châu Phi phi thường. phong cảnh.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Charles","avatar":""},{"name":"Joshua Rush","avatar":""},{"name":"Madison Pettis","avatar":""},{"name":"Andrew Kishino","avatar":""},{"name":"Vargus Mason","avatar":""},{"name":"Rob Lowe","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Eden Riegel","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Ernie Sabella","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Kevin Schon","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Diamond White","avatar":""},{"name":"Dusan Brown","avatar":""},{"name":"Atticus Shaffer","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Greg Ellis","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324452);
