INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-lion-guard-return-of-the-roar', 'The Lion Guard: Return of the Roar', 'The Lion Guard: Return of the Roar', 'the lion guard: return of the roar the lion guard: return of the roar max charles joshua rush madison pettis andrew kishino vargus mason rob lowe gabrielle union eden riegel khary payton ernie sabella james earl jones kevin schon jeff bennett diamond white dusan brown atticus shaffer sarah hyland greg ellis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sinh-thu-phan-2', 'Ký Sinh Thú Phần 2', 'Parasyte Part 2', 'https://phimimg.com/upload/vod/20231116-1/487b8116ededf4d9525b31be46b0931d.jpg', 'https://phimimg.com/upload/vod/20231116-1/03605c52e839698ff32a563f87b28ffc.jpg', '<p>Phần 2 Ký sinh thú tiếp tục câu chuyện Izumi Shinichi là một thiếu niên 17 tuổi, sống cùng bố mẹ tại một khu phố yên tĩnh ở Tokyo. Một đêm nọ, những sinh vật ngoài hành tinh, có hình thù giống loài sâu, với tên gọi Kiseijū (&quot;Ký sinh vật&quot;) đổ bộ lên Trái Đất, chiếm lấy não và điều khiển chủ thể là con người bằng cách xâm nhập qua tai hoặc mũi. Một &quot;Ký sinh vật&quot; có ý định bò vào tai của Shinichi khi cậu ngủ nhưng thất bại vì cậu đang đeo tai nghe, vậy nên đã xâm nhập cơ thể cậu bằng cách chui vào tay và điều khiển cánh tay phải, và sau đó lấy tên là Migi.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shota Sometani","avatar":""},{"name":"Ai Hashimoto","avatar":""},{"name":"Sadawo Abe","avatar":""},{"name":"Eri Fukatsu","avatar":""},{"name":"Masahiro Higashide","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Pierre Taki","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Wataru Ichinose","avatar":""},{"name":"Roy Kishima","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chín