INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-dan-mach', 'Trận Đan Mạch', 'April 9th', 'https://phimimg.com/upload/vod/20231116-1/4d82cf4a07f902657456b0fd5e84382b.jpg', 'https://phimimg.com/upload/vod/20231116-1/979fafcc84c7256bfd9f5eddd6810e36.jpg', '<p>Sáng sớm ngày 9 tháng 4 năm 1940, quân đội Đan Mạch được báo động. Người Đức đã vượt qua biên giới; Đan Mạch đang có chiến tranh chống lại quân đội mạnh nhất châu Âu. Ở Nam Jutland, các công ty xe đạp và xe máy của Đan Mạch được lệnh, bất chấp mọi khó khăn, kìm hãm lực lượng cho đến khi quân tiếp viện của Đan Mạch được huy động. Trong giờ phút định mệnh, chúng tôi theo chân thiếu úy Sand và đại đội xe đạp của anh – họ sẽ là những người lính Đan Mạch đầu tiên đụng địch trong trận chiến ngày 9/4/1940.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Pilou Asbæk","avatar":""},{"name":"Lars Mikkelsen","avatar":""},{"name":"Gustav Dyekjær Giese","avatar":""},{"name":"Martin Greis-Rosenthal","avatar":""},{"name":"Joachim Fjelstrup","avatar":""},{"name":"Elliott Crosset Hove","avatar":""},{"name":"Mathias Lundkvist","avatar":""},{"name":"Ari Alexander","avatar":""},{"name":"Jannik Lorenzen","avatar":""},{"name":"Sebastian Bull Sarning","avatar":""},{"name":"Bálint Bán","avatar":""},{"name":"Jesper Hagelskær Paasch","avatar":""},{"name":"Michael Brostrup","avatar":""},{"name":"Morten Ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324452);
