INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-di-jose', 'Mơ đi, Jose', 'No Way Jose', 'https://phimimg.com/upload/vod/20231116-1/b5a818a43caa33624ccafc662736419e.jpg', 'https://phimimg.com/upload/vod/20231116-1/4eb4892b2a0afeb48bbed56ef0bb1b96.jpg', '<p>Chênh vênh giữa ngã rẽ trong cả cuộc sống và tình yêu, chàng nhạc sĩ đang trắc trở tìm lời khuyên và sự an ủi nơi bạn bè và gia đình trong khi đi tìm chính mình.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Goldberg","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Anna Belknap","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Emily Osment","avatar":""},{"name":"Brendan Hines","avatar":""},{"name":"Eric Siegel","avatar":""},{"name":"Steve Agee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
