INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-luan-2', 'Thái Bình Luân 2', 'The Crossing 2', 'https://phimimg.com/upload/vod/20231116-1/e6ef645fb7fa648378f62beb0879d009.jpg', 'https://phimimg.com/upload/vod/20231116-1/c83a8eb5f956fc2fd7299639be171cd2.jpg', '<p>Dựa trên vụ đắm tàu Thái Bình năm 1949, Thái Bình Luân 2 nói về ba cặp đôi gặp số phận bi kịch khi bước lên chiếc tàu khách hơi nước Thái Bình, đưa những người từ Đại lục sang Đài Loan lánh nạn chiến tranh. Kết thúc bi thảm của tàu Thái Bình được so với con tàu Titanic.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ziyi","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Song Hye-kyo","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Angeles Woo","avatar":""},{"name":"Yang Kuei-Mei","avatar":""},{"name":"Wang Qian-Yuan","avatar":""},{"name":"Qin Hailu","avatar":""},{"name":"Bowie Lam","avatar":""},{"name":"Cong Shan","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Hitomi Kuroki","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Zhang Jiayi","avatar":""},{"name":"Wang Zhifei","avatar":""},{"name":"Masami Nagasawa","avatar":""},{"name":"Lin Mei-shiu","avatar":""},{"name":"Zhang Guoqin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324452);
