INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-hoan-luong', 'Sát Thủ Hoàn Lương', 'A Hitman in London', 'https://phimimg.com/upload/vod/20231120-1/f1230947c275c11427ee5b0ac52e20e7.jpg', 'https://phimimg.com/upload/vod/20231120-1/0abe447a3fd701dcc9469f7e8f81ad1a.jpg', '<p>Sau khi nhiệm vụ cuối cùng của anh ta kết thúc với cái chết của một người phụ nữ vô tội, công việc mới của một sát thủ ở London bị tổn hại khi anh ta vượt qua cảm giác tội lỗi và cuối cùng giúp đỡ một người phụ nữ tuyệt vọng bị cuốn vào một hoạt động buôn người.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mickey Rourke","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Dominique Swain","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Alan Ford","avatar":""},{"name":"Keith Mason","avatar":""},{"name":"Ara Paiaya","avatar":""},{"name":"Ron Smoorenburg","avatar":""},{"name":"Angie Simms","avatar":""},{"name":"Jess Liaudin","avatar":""},{"name":"Jerry Anderson","avatar":""},{"name":"Natalia Ryumina","avatar":""},{"name":"Sabrina Dickens","avatar":""},{"name":"Natasha Goulden","avatar":""},{"name":"Chelse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
