INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-cuop-song-bac', 'Băng Cướp Sòng Bạc', 'Heist', 'https://phimimg.com/upload/vod/20231120-1/2e9f603c6bdd38b789f872d17e622549.jpg', 'https://phimimg.com/upload/vod/20231120-1/290b70c12ce26807061684024e9a409d.jpg', '<p>Phim Băng Cướp Sòng Bạc - Heist 2015 xoay quanh câu chuyện của Luke Vaughn – một nhân viên trung thành trong sòng bài của Frank “the Pope”. Vaughn đã phải tìm đến ông chủ lâu năm của mình để hỏi vay 300.000 USD thanh toán tiền viện phí cho cô con gái nhỏ. Tuy nhiên, Pope đã từ chối một cách tàn nhẫn, đẩy Vaughn vào đường cùng và buộc anh phải hợp lực với một đồng nghiệp khác lên kế hoạch cướp sòng bạc. Tuy nhiên, phi vụ xảy ra không như mong đợi, băng cướp đã phải tẩu thoát trên một chiếc xe bus trong khi bị rượt đuổi bởi ông trùm Pope và cả cảnh sát thành phố. Liệu Vaughn có kịp tẩu thoát để cứu con gái mình?. Mời các bạn xem phim.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Gina Carano","avatar":""},{"name":"Mark-Paul Gosselaar","avatar":""},{"name":"D.B. Sweeney","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Summer Altice","avatar":""},{"name":"Rosie Fellner","avatar":""},{"name":"Alyssa Julya Smith","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Courtney Blythe Turk","avatar":""},{"name":"Han Soto","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Stephen C.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
