INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-hoi-ky-uc', 'Truy Hồi Ký Ức', 'Regression', 'https://phimimg.com/upload/vod/20231120-1/da8b9f3e2e3a5d38a1c39e6d1fce81b2.jpg', 'https://phimimg.com/upload/vod/20231120-1/d081432a122ecce1dba8dc734deef85d.jpg', '<p>Phim Truy Hồi Ký Ức - Regression 2015 là một bộ phim điện ảnh tâm lý do Mỹ sản xuất được đạo diễn Alejandro Amenabar hợp tác phụ trách cùng các diễn viên như là Emma Watson, Ethan Hawke, Dale Dickey, Lothaire Bluteau, Devon Bostick....Nội dung bộ phim xoay quanh thám tử Bruce Kenner được cô gái đau khổ Angela Gray tìm đến và tố cáo người cha tệ bạc hành hạ và lạm dụng mình nhiều năm liền. Bruce Kenner đến nhà John Gray cha ruột của Angela để điều tra thì người đàn ông này hoàn toàn không còn nhớ gì về những kí ức tội lỗi khi xưa của mình, cho rằng đây là một trò đùa nên Bruce đã nhờ đến sự giúp đỡ của một bác sĩ tâm lý học để hỗ trợ và phát hiện ra nhiều bí mật liên quan đến quốc gia và Thế Giới. Phim với nội dung đầy sức hút chắc chắn sẽ làm các bạn cảm thấy thích thú.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Lothaire Bluteau","avatar":""},{"name":"Aaron Ashmore","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Peter MacNeill","avatar":""},{"name":"Adam Butcher","avatar":""},{"name":"Jacob Neayem","avatar":""},{"name":"Aaron Abrams","avatar":""},{"name":"Catherine Disher","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Kristian Bruun","avatar":""},{"name":"Wendy Lyon","avatar":""},{"name":"Maura Grierson","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
