INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phong-bi-an', 'Văn Phòng Bí Ẩn', 'Office', 'https://phimimg.com/upload/vod/20231120-1/428716e9a4af32ac5fe90659ced3f415.jpg', 'https://phimimg.com/upload/vod/20231120-1/ddd20e040108564cfcdf859f7ba53812.jpg', '<p>Phim Văn Phòng Bí Ẩn - 2015: Kim Byeong-Gook (Bae Sung-Woo) là ông chủ một công ty. Anh ấy sống trong gia đình đàn ông và tự tin với công việc của mình, nhưng một ngày, anh ta giết toàn bộ gia đình của mình và biến mất. Thám tử Jong-Hoon (Park Sung-Woong) điều tra các vụ giết người và nói với Kim Byung-Gook, đồng nghiệp tại văn phòng của ông. Đồng nghiệp của anh ấy cho rằng thông tin không rõ ràng. Bên cạnh đó, Lee Mi-Rye (Ko Ah-Sung), người rất thân thiết với Kim Byeong-Gook, dường như che giấu gì đó. Thám tử Jong-Hoon sẽ kiểm tra hệ thống camera và quan sát Kim Byeong-Gook trở lại làm việc sau khi vụ giết người, nhưng không thể xác định vị trí anh ta khi rời văn phòng. Trong khi đó, các đồng nghiệp tại văn phòng trở nên bàng hoàng sự lo lắng về nơi ở của Kim Byung-Gook.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Go A-seong","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Ryu Hyun-kyung","avatar":""},{"name":"Lee Chae-eun","avatar":""},{"name":"Sohn Su-hyun","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Jeon Kwang-jin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
