INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-quay-ke-thu', 'Vòng Quay Kẻ Thù', 'AWOL-72', 'https://phimimg.com/upload/vod/20231120-1/db4324b3ed490aa719cc1cbb4b8dae8f.jpg', 'https://phimimg.com/upload/vod/20231120-1/bbf0ce6c22119db84fbb72a6856223f5.jpg', '<p>Nội dung của phim Vòng Quay Kẻ Thù xoay quanh một sĩ quan quân đội tên là Conrad Miller (Luke Goss), hiện đang làm việc tại AWOL và bị buộc tội bán bí mật cho KGB trong thời chiến tranh lạnh. Khi Miller nhận ra mình đã bị đối thủ của mình là Myron (Bokeem Woodbine) theo dõi, Miller cũng tìm thấy được tình yêu của anh ta, và sự thỏa hiệp của anh ta đã bị đe dọa, và anh ta làm điều duy nhất có thể có được với con người.Tẩu thoát, đó là những gì mà anh ta cần phải làm ngay lúc này khi mà những người Nga đang tìm kiếm các dịch vụ của tay thám tử nổi tiếng Adams (RZA) để giúp họ trong cuộc săn tìm và theo dõi nhất cử nhất động của Miller bằng bất cứ cách nào cần thiết. Miller có 72 giờ để đi tới điểm hẹn của mình và ra khỏi đất nước với tình yêu của mình cũng những bí mật duy nhất có thê rgiữ mạng sống cho anh ta.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Goss","avatar":""},{"name":"RZA","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Brooke Newton","avatar":""},{"name":"Marco Khan","avatar":""},{"name":"Tomoko Karina","avatar":""},{"name":"Heather Roop","avatar":""},{"name":"Mary Christina Brown","avatar":""},{"name":"Jillisa Lynn","avatar":""},{"name":"Mirtha Michelle","avatar":""},{"name":"Merry Whitney","avatar":""},{"name":"Adam Gregor","avatar":""},{"name":"Brett Wagner","avatar":""},{"name":"Jackie Guerrido","avatar":""},{"name":"Leif Gantvoort","avatar":""},{"name":"Leonard Kelly-Young","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
