INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-so-khoang-trong', 'Nỗi Sợ Khoảng Trống', 'Agoraphobia', 'https://phimimg.com/upload/vod/20231118-1/de322477fca7e9fa61b5675779d6aadb.jpg', 'https://phimimg.com/upload/vod/20231118-1/18ffbfbbaddc496045784e3e63a7a4ce.jpg', '<p>Một Agoraphobic thừa kế ngôi nhà của cha cô ở một vùng xa xôi của Florida Keys. Khi những điều kỳ lạ bắt đầu xảy ra, cô phát hiện ra rằng có một thứ gì đó đáng sợ hơn bị mắc kẹt trong nhà với cô.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cassandra Scerbo","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Maria Olsen","avatar":""},{"name":"Aniela McGuinness","avatar":""},{"name":"Roberto Escobar","avatar":""},{"name":"Julie Kendall","avatar":""},{"name":"Gema Calero","avatar":""},{"name":"Adam Brudnicki","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
