INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-canh-sat', 'Xe Cảnh Sát', 'Cop Car', 'https://phimimg.com/upload/vod/20231118-1/cf4d64d30e0081374fcc2b35780c5399.jpg', 'https://phimimg.com/upload/vod/20231118-1/9cb53fc83c7ddfed793cb295a42a75f2.jpg', '<p>Hai chàng trai trẻ tốt bụng nhưng nổi loạn đã tuyên bố bỏ nhà ra đi. Được trang bị với một số thịt bò khô, họ đi dạo qua những cánh đồng vàng nơi họ tìm thấy một chiếc xe cảnh sát bị bỏ rơi. Tò mò và thích thú, họ khám phá những chiếc xe, tìm chìa khóa và lấy xe đi một joyride. Quyết định tồi tệ của họ dẫn tới sự giận dữ của chủ sở hữu của chiếc xe, một cảnh sát trưởng quận hạt, người đã để lại một cái gì đó có giá trị lớn trong xe và đang tuyệt vọng để có được nó trở lại. Một trò chơi có nhịp độ nhanh của xảy ra sau đó mèo và chuột và các chàng trai nhanh chóng khám phá ra rằng những niềm vui đã qua và họ đang ở cách trên đầu của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"James Freedson-Jackson","avatar":""},{"name":"Hays Wellford","avatar":""},{"name":"Camryn Manheim","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Sean Hartley","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Loi Nguyen","avatar":""},{"name":"Sit Lenh","avatar":""},{"name":"Chuck Kull","avatar":""},{"name":"Thomas Coates","avatar":""},{"name":"Kathleen Bentley","avatar":""},{"name":"Justin Barr","avatar":""},{"name":"Adam Barr","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
