INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-phia-tren', 'Bầu Trời Phía Trên', 'The Sky Above Us', 'null', 'https://phimimg.com/upload/vod/20231118-1/0e58935921580da47067d89ef8dbd47b.jpg', '<p>Khi Belgrade biến đổi từ một thành phố yên bình thành mục tiêu quân sự, một đêm đánh bom NATO liên tục rơi từ trên bầu trời xuống, Ana, Bojan và Sloba cố gắng giữ bình tĩnh, tỉnh táo trong khi đối phó với nỗi sợ hãi của họ và họ tự hỏi: &quot;&quot;làm thế nào có thể tồn tại và ở lại an toàn trong thế giới điên này?</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Nada Šargin","avatar":""},{"name":"Boris Isaković","avatar":""},{"name":"Nikola Rakočević","avatar":""},{"name":"Nevena Ristić","avatar":""},{"name":"Mladen Sovilj","avatar":""},{"name":"Hristina Popović","avatar":""},{"name":"Miloš Timotijević","avatar":""},{"name":"Jovana Gavrilović","avatar":""},{"name":"Tihomir Stanić","avatar":""},{"name":"Ana Bretšnajder","avatar":""},{"name":"Slobodan ''Boda'' Ninković","avatar":""},{"name":"Mladen Andrejević","avatar":""},{"name":"Vladislava Milosavljević","avatar":""},{"name":"Bojan Ži","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
