INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-cuoi-cung', 'Cuộc Giải Cứu Cuối Cùng', 'The Last Rescue', 'https://phimimg.com/upload/vod/20231118-1/290933428b51826b746832cf36c0d2e0.jpg', 'https://phimimg.com/upload/vod/20231118-1/c2f52c43ba207d04d941c450881bff00.jpg', '<p>Thế giới Thế giới II: Ngay sau D-Day, ba người lính Mỹ và hai y tá của Quân đoàn bị mắc kẹt sau chiến tuyến của kẻ thù. Họ bắt một sĩ quan cấp cao của Đức làm tù nhân và cố gắng sắp xếp một cuộc vượt ngục.</p>', 'Full', 1, 'single', 'completed', 9, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brett Cullen","avatar":""},{"name":"Cody Kasch","avatar":""},{"name":"Gilles Marini","avatar":""},{"name":"Ryan Merriman","avatar":""},{"name":"Johann Urb","avatar":""},{"name":"Elizabeth Rice","avatar":""},{"name":"Darren Keefe Reiher","avatar":""},{"name":"Hallie Shepherd","avatar":""},{"name":"Tony Doupe","avatar":""},{"name":"Tino Struckmann","avatar":""},{"name":"Dawson Doupé","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
