INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-den', 'Liên Minh Đen', 'Black Mass', 'https://phimimg.com/upload/vod/20231117-1/5980e034737b72627d6140016589e155.jpg', 'https://phimimg.com/upload/vod/20231117-1/517b22fb05693f2bd2695abdcbfb9136.jpg', '<p>Black Mass xoay quanh về cuộc đời của Whitey Bulger một tên gangster huyền thoại ở Nam Boston. Sau nhiều năm chinh chiến ngoài đường phố Whitey Bulger muốn vươn đến tâm cao mới hơn trong vai trò một chính trị gia, nhưng kết quả là vấp phải vô số những rào cản mà các đối thủ khác đặt ra. Một cuộc chiến đầy tâm lý cũng như mưu toan bắt đầu.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Dakota Johnson","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Mark Mahoney","avatar":""},{"name":"Brad Carter","avatar":""},{"name":"Scott G. Anderson","avatar":""},{"name":"Lonnie Farmer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324452);
