INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-hoi-sinh', 'Hiệu Ứng Hồi Sinh', 'The Lazarus Effect', 'https://phimimg.com/upload/vod/20231117-1/c0d7e87a9394b88ea4921ce0b11c82d6.jpg', 'https://phimimg.com/upload/vod/20231117-1/e483b396ca6cb527f267f6ce83b50fe6.jpg', '<p>Bộ phim Hồi Sinh - The Lazarus Effect được thực hiện bởi đạo diễn David Gelb với sự tham gia của Olivia Wilde - nữ diễn viên,người mẫu nổi tiếng hàng đầu nước Mỹ. Nội dung kể về một nhóm các nhà nghiên cứu khoa học đã vô tình giết chết một đồng nghiệp trong quá trình thí nghiệm về việc lập bản đồ não. Tuy nhiên sau đó họ đã dẫn đường cho một thế lực tàn ác đến với thế giới thông qua việc hồi sinh người bạn của họ. Các thành viên trong nhóm giờ đây không những phải đấu tranh cho sự sinh tồn đồng thời còn phải tìm cách ngăn chặn người bạn trên trước khi cô ta thâm nhập vào thế giới bên ngoài.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Bolger","avatar":""},{"name":"Amy Aquino","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Ray Wise","avatar":""},{"name":"Sean T. Krishnan","avatar":""},{"name":"Bruno Gunn","avatar":""},{"name":"Mark Duplass","avatar":""},{"name":"Donald Glover","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324452);
