INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-dong-tinh', 'Hôn Nhân Đồng Tính', 'Jenny''s Wedding', 'https://phimimg.com/upload/vod/20231117-1/6203248566738b48b8f3c824f71eefb9.jpg', 'https://phimimg.com/upload/vod/20231117-1/bf9a51f7b727a365683753f2787bf448.jpg', '<p>Jenny Farrell sắp kết hôn. Nhưng gia đình căng thẳng của cô ấy sẽ phản ứng thế nào khi họ phát hiện ra rằng người phụ nữ mà họ nghĩ là bạn cùng phòng của con gái họ thực sự là vợ chưa cưới của cô ấy? Khi gia đình Farrells cổ hủ cố gắng chấp nhận viễn cảnh có một cô con dâu bất ngờ, họ phải đối mặt với một lựa chọn khó khăn: hoặc thích nghi với thời đại hoặc có nguy cơ bị bỏ lại phía sau.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katherine Heigl","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Linda Emond","avatar":""},{"name":"Grace Gummer","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Sam McMurray","avatar":""},{"name":"Diana Hardcastle","avatar":""},{"name":"Matthew Metzger","avatar":""},{"name":"Houston Rhines","avatar":""},{"name":"Cathleen O''Malley","avatar":""},{"name":"Ed Ackerman","avatar":""},{"name":"Bill Watterson","avatar":""},{"name":"Joshua Elijah Reese","avatar":""},{"name":"Hollis McCarthy","avatar":""},{"name":"Ann Hagemann","avatar":""},{"name":"Alex T. Wak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
