INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-ca-voi-quy', 'Mặc Cả Với Quỷ', 'Pay the Ghost', 'https://phimimg.com/upload/vod/20231117-1/dc80c094b615b473081c4576f8801a4a.jpg', 'https://phimimg.com/upload/vod/20231117-1/b7c34acbea5ca777b20bbfc62291606d.jpg', '<p>Một năm sau khi cậu con trai nhỏ của mình mất tích trong lễ hội hóa trang Halloween, Mike Cole bị ám ảnh bởi những hình ảnh kỳ lạ và những thông điệp đáng sợ mà anh không thể giải thích. &nbsp;Cùng với người vợ ghẻ lạnh của mình, anh ta sẽ không dừng lại ở việc làm sáng tỏ bí ẩn và tìm con trai của họ - và khi làm như vậy, anh ta khai quật một truyền thuyết không bị chôn vùi trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Veronica Ferres","avatar":""},{"name":"Lyriq Bent","avatar":""},{"name":"Lauren Beatty","avatar":""},{"name":"Kalie Hunter","avatar":""},{"name":"Jack Fulton","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Susannah Hoffmann","avatar":""},{"name":"Mark Irvingsen","avatar":""},{"name":"Liam Buckle","avatar":""},{"name":"Sofia Wells","avatar":""},{"name":"Aidan Wojtak-Hissong","avatar":""},{"name":"Caroline Gillis","avatar":""},{"name":"Janet Lo","avatar":""},{"name":"Jamillah Ross","avatar":""},{"name":"Juan C","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324452);
