INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hitler-tro-ve', 'Hitler Trở Về', 'Look Who''s Back', 'https://phimimg.com/upload/vod/20231117-1/25f398d3323a6ad7ea77b7b98fd0c832.jpg', 'https://phimimg.com/upload/vod/20231117-1/d6fe3db49ef96dc8fc3c6f4376977f07.jpg', '<p>Bộ phim &quot;Er ist wieder da&quot; dựa trên cuốn tiểu thuyết cùng tên của Timur Vermes đứng đầu doanh thu các phòng vé tại Đức tại thời điểm công chiếu. Lấy bối cảnh Berlin năm 2014, Quốc trưởng Đức quốc xã Adolf Hitler đột nhiên tỉnh dậy trên bãi cỏ và không nhớ bất kỳ điều gì từ sau năm 1945, sau đó ông bị nhầm lẫn với một diễn viên hài nổi tiếng, rồi trùm phát xít thậm chí còn có show truyền hình riêng của mình...</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Oliver Masucci","avatar":""},{"name":"Fabian Busch","avatar":""},{"name":"Katja Riemann","avatar":""},{"name":"Christoph Maria Herbst","avatar":""},{"name":"Franziska Wulf","avatar":""},{"name":"Lars Rudolph","avatar":""},{"name":"Roberto Blanco","avatar":""},{"name":"Stephan Grossmann","avatar":""},{"name":"Patrick Heinrich","avatar":""},{"name":"Michael Ostrowski","avatar":""},{"name":"Gudrun Ritter","avatar":""},{"name":"Paul Maaß","avatar":""},{"name":"Katharina Abt","avatar":""},{"name":"Marian Meder","avatar":""},{"name":"Thomas M. Köppl","avatar":""},{"name":"Marc-Marvin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
