INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-rong-loi-nguyen-cua-phu-thuy', 'Tim Rồng: Lời Nguyền Của Phù Thủy', 'Dragonheart 3: The Sorcerer''s Curse', 'https://phimimg.com/upload/vod/20231116-1/eb1cb26c6bb069da02ed38316cadd0ea.jpg', 'https://phimimg.com/upload/vod/20231116-1/c1301b2287e5edc820efc332d6fe7cc6.jpg', '<p>Khi một hiệp sĩ nhiệt huyết vô tình chạm trán một con rồng, cả hai tạo ra một liên minh lạ thường trong trận chiến cam go với một pháp sư hiểm ác.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julian Morris","avatar":""},{"name":"Tamzin Merchant","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Jassa Ahluwalia","avatar":""},{"name":"Jonjo O''Neill","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Dominic Mafham","avatar":""},{"name":"Ozama Oancea","avatar":""},{"name":"Jake Curran","avatar":""},{"name":"Roger Ashton-Griffiths","avatar":""},{"name":"Edouard Philipponnat","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324452);
