INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-max', 'Chú Chó Max', 'Max', 'https://phimimg.com/upload/vod/20231115-1/e5afa1a76ecadd5d22021e3e312c8fd8.jpg', 'https://phimimg.com/upload/vod/20231115-1/785acd5d91cf7708f4ae816818f8905a.jpg', '<p>Chú Chó Max lấy cảm hứng từ sự kiện có thật, cốt truyện kể về một chú chó quân sự bị tổn thương sau khi cái chết của người huấn luyện Kyle Wincott tại Afghanistan và được đưa về nhà, nơi nó được chấp nhận bởi gia đình người lính Kyle Wincott.Chú chó Max gắn bó với cậu em trai rắc rối 14 tuổi của Kyle Wincott. Cùng nhau, họ bắt đầu gắn kết và phát hiện ra một bí mật về cái chết của Kyle Wincott.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Haden Church","avatar":""},{"name":"Josh Wiggins","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Mia Xitlali","avatar":""},{"name":"Luke Kleintank","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"J. J. Soria","avatar":""},{"name":"Zeeko Zaki","avatar":""},{"name":"Edgar Arreola","avatar":""},{"name":"Christian Brunetti","avatar":""},{"name":"Jason Davis","avatar":""},{"name":"Miles Mussenden","avatar":""},{"name":"Nazareth Dairian","avatar":""},{"name":"Ethan Alexander McGee","avatar":""},{"name":"Carlos","avatar":""},{"name":"Dejon La","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324452);
