INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vui-lap-sai-lam', 'Vùi Lấp Sai Lầm', 'All Mistakes Buried', 'https://phimimg.com/upload/vod/20231115-1/f3e67e9a9bd645da2e3fe423b26da48c.jpg', 'https://phimimg.com/upload/vod/20231115-1/49e3da4547f3d3284a91822dc952a593.jpg', '<p>Một người nghiện ma túy cô đơn sống trong một thị trấn nhỏ chiến đấu với một tổ chức tội phạm để giành lại một món đồ trang sức bị đánh cắp, mà anh tin là chìa khóa để sửa chữa cuộc hôn nhân bị gãy của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vanessa Ferlito","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Nick Loeb","avatar":""},{"name":"Missy Yager","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
