INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-thuc-tinh', 'Ký Ức Thức Tỉnh', 'Vice', 'https://phimimg.com/upload/vod/20231113-1/f2c1f78e606ed8c7bded20b83c0d729a.jpg', 'https://phimimg.com/upload/vod/20231113-1/5515e857db664b8aedd42c3a21607b72.jpg', '<p>Ký Ức Thức Tỉnh là bộ phim kể về một tương lai xa khi mà tập đoàn Vice cho ra mắt khu nghỉ dưỡng cao cấp và hiện đại của mình, và đặc biệt khách hàng có thể làm bất cứ điều gì mình muốn với những con borot hữu cơ như người thật của mình. Kelly là một trong những co robot tình dục của tập đoàn Vice có nhiệm vụ hằng ngày phải phục vụ khách hàng kể cả bị đánh đập dã man, và rồi một ngày sau khi bị tác động mạnh vào đầu trung tâm khôi phục kí ức của Kelly gặp trục trặc và toàn bộ những kí ức của cô trong nhiều năm qua tái hiện lại trong bộ não nhân tạo của mình. Quyết định bỏ trốn khỏi Vice để tìm cách trả thù nhưng Julian người đứng đầu tập đoàn đã sớm nhận ra mối nguy hại nếu để Kelly thoát ra ngoài và tố cáo đến chính phủ.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ambyr Childers","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Bryan Greenberg","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Johnathon Schaech","avatar":""},{"name":"Charlotte Kirk","avatar":""},{"name":"Brett Granstaff","avatar":""},{"name":"Ryan O''Nan","avatar":""},{"name":"David Gordon","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"Cameron Brexler","avatar":""},{"name":"Jesse Pruett","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Nikki BreAnne Wells","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"kh