INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-co-bat-ngo', 'Sự Cố Bất Ngờ', 'An Accidental Shot Of Love', 'https://phimimg.com/upload/vod/20231113-1/0e6db417875e08c34fca0149ae4fd899.jpg', 'https://phimimg.com/upload/vod/20231113-1/d3f167470ed2f789e61a50ad15015923.jpg', '<p>Phim Sự Cố Bất Ngờ - An Accidental Shot Of Love 2015: Đang vui vẻ với bạn gái mới, Hoàng Đấu bỗng nhận được tin cô bạn gái cũ Lam Thiên mang thai đứa con của anh, Món quà bất ngờ này đã đẩy anh vào hoàng cảnh trớ trêu, dở khóc dở cười khi đứng giữa người yêu cũ và người yêu mới. Nhưng nhờ sự cố ấy, Hoàng Đấu trường thành hơn và biết đâu là hạnh phúc thật sự</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Entai","avatar":""},{"name":"Ni Hongjie","avatar":""},{"name":"Wang Jingchun","avatar":""},{"name":"Zhao Wenqi","avatar":""},{"name":"Rui Li","avatar":""},{"name":"Siqin Gaowa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
