INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-tinh-yeu-o-seoul', 'Tìm Tình Yêu Ở Seoul', 'Seoul Searching', 'https://phimimg.com/upload/vod/20231113-1/285e3dd1b0a9254e0121a709829d9648.jpg', 'https://phimimg.com/upload/vod/20231113-1/aabe4e80a5dd11874a0d79f84119819a.jpg', '<p>Vào những năm 1980, một nhóm thanh thiếu niên Hàn Quốc sinh ra ở nước ngoài gặp nhau tại một trại hè ở Seoul để tìm hiểu ý nghĩa của việc trở thành người Hàn Quốc. Sau đó, ba chàng trai đến từ Hoa Kỳ, Mexico và Đức gặp ba cô gái khuấy động thế giới của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Justin Chon","avatar":""},{"name":"Jessika Van","avatar":""},{"name":"Cha In-pyo","avatar":""},{"name":"Teo Yoo","avatar":""},{"name":"Esteban Ahn","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"Mina Fujii","avatar":""},{"name":"In-woo Kim","avatar":""},{"name":"Rosalina Lee","avatar":""},{"name":"Albert Kong","avatar":""},{"name":"Crystal Kay","avatar":""},{"name":"Nekhebet Kum Juch","avatar":""},{"name":"Uatchet Jin Juch","avatar":""},{"name":"Sue Son","avatar":""},{"name":"Han Hee Jun","avatar":""},{"name":"Kang Byul","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Choi Seong-guk","avatar":""},{"name":"Park Ji-a","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
