INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhap-cu', 'Người Nhập Cư', 'Brooklyn', 'https://phimimg.com/upload/vod/20231114-1/8e321d0086483e6c079c8fe79ec6ae84.jpg', 'https://phimimg.com/upload/vod/20231114-1/976594ec1065f3fe4bc479196ef1a671.jpg', '<p>Lấy bối cảnh những năm 50 của thế kỉ 20, bộ phim ghi lại từng sự kiện trong cuộc hành trình từ quê hương đến thành phố New York của một cô gái trẻ người Ailen. Eilis Lacey đã bỏ lại gia đình mình và cố gắng kiếm tìm hạnh phúc ở một xứ sở xa lạ. Với phần kịch bản chân thực và sắc sảo của Nick Hornby cùng diễn xuất tuyệt vời của dàn diễn viên chính đã tạo ra một bộ biên niên sử thu nhỏ về tình yêu, sự mất mát và ý niệm về hai tiếng “gia đình” đầy sức lay động.Hoa Kỳ là quốc gia được thành lập bởi những người nhập cư. Dù cho nền văn hoá của quốc gia này đã tạo ra được những bản sắc riêng thì cội rễ của mỗi thành tố cấu tạo nên nó vẫn bắt nguồn từ rất nhiều nơi và vùng lãnh thổ khác nhau.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Emory Cohen","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Jessica Paré","avatar":""},{"name":"Eve Macklin","avatar":""},{"name":"Brid Brennan","avatar":""},{"name":"Fiona Glascott","avatar":""},{"name":"Jane Brennan","avatar":""},{"name":"Nora-Jane Noone","avatar":""},{"name":"Jenn Murray","avatar":""},{"name":"Eva Birthistle","avatar":""},{"name":"Michael Zegen","avatar":""},{"name":"Matt Glynn","avatar":""},{"name":"Maeve McGrath","avatar":""},{"name":"Emma Lowe","avatar":""},{"name":"Barbara D","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
