INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tinh', 'Bẫy Tình', 'Deep Trap', 'https://phimimg.com/upload/vod/20231114-1/5585dd03f40bf241040a45bf51c52289.jpg', 'https://phimimg.com/upload/vod/20231114-1/d61beadd7942de2e2e0dd212ff113e7f.jpg', '<p>Cặp vợ chồng trong chuyến du lịch đến một hòn đảo bị cô lập. Bẫy Tình tập trung vào một người phụ nữ tên là So Yeon (do Kim Min Kyung đóng), người mà gần đây đã bị sẩy thai. Sự việc này đã khiến cô hết sức đau lòng và cô kìm nén nó theo cách riêng của mình, cũng như chồng cô Joon Sik (do Jo Han Seon đóng). Để quên bớt nỗi đau, So Yeong đề xuất ý tưởng đi nghỉ dưỡng tại một biệt thự nằm trên một hòn đảo xinh đẹp với tầm nhìn ra bãi biển.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Kim Min-kyung","avatar":""},{"name":"Jo Han-sun","avatar":""},{"name":"Im Ji-an","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
