INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-tam-thoi-gian-2', 'Bồn Tắm Thời Gian 2', 'Hot Tub Time Machine 2', 'https://phimimg.com/upload/vod/20231114-1/3a137dfd0a84c7f2677452262abd259e.jpg', 'https://phimimg.com/upload/vod/20231114-1/a6534d8aab39501495c8db360316b4e7.jpg', '<p>Bồn Tắm Thời Gian 2 - Hot Tub Time Machine 2 là một bộ phim Mỹ thuộc thể loại khoa học viễn tưởng kết hợp hài kịch được đạo diễn bởi Steve Pink và được viết kịch bản bởi Josh Heald. Nội dung phim sẽ tiếp tục câu chuyện kể từ phần 1. Sau khi cùng nhau phát hiện ra bồn tắm thời gian, những người bạn của chúng ta đều đã trở thành những người thành công và nổi tiếng. Một sự cố bất ngờ xảy đến, khi Lou - cha đẻ của internet, bị một kẻ lạ mặt tấn công bằng súng. Không còn nhiều thời gian, họ chợt nhớ đến chiếc bồn tắm như một cứu cánh. Lần này chiếc bồn tắm đưa họ đến tương lai, năm 2024</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rob Corddry","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Bianca Haase","avatar":""},{"name":"Chevy Chase","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Collette Wolfe","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Kellee Stewart","avatar":""},{"name":"Josh Heald","avatar":""},{"name":"Gretchen Koerner","avatar":""},{"name":"Lisa Loeb","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Bruce Buffer","avatar":""},{"name":"Mariana Paola Vicente","avatar":""},{"name":"Christian Slat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
