INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('addiction-a-60s-love-story', 'Addiction: A 60''s Love Story', 'Addiction: A 60''s Love Story', 'https://phimimg.com/upload/vod/20231115-1/5995f12d43c6a2dd730526df1b02c942.jpg', 'https://phimimg.com/upload/vod/20231115-1/a5e49ed4cc96da617950e542e88ebb5b.jpg', '<p>Dựa trên một câu chuyện có thật, &quot;Dynamite: A Caution Tale&quot; kể về người đàn ông của gia đình Max Bornstein, một kẻ nghiện ma túy toàn thời gian làm việc trong ngành công nghiệp khiêu dâm ngầm, rất bất hợp pháp ở Thành phố New York năm 1968. Trong khi chạy sách và phim đến các điểm giao hàng và trụ sở của đám đông xung quanh bờ biển phía đông, Max đã có Feds ở phía sau. Nhưng ngay cả sau cuộc điều tra của liên bang, nỗi lo lắng thực sự nhất của Max là vợ và hai đứa con nhỏ của anh, một gia đình luôn chìm trong bóng tối về thực tại của Max và những bức tường xung quanh anh. Khi Max chiến đấu với chứng nghiện tiêu thụ của mình, gia đình tan rã và mối nghi ngờ ngày càng tăng về việc sử dụng ma túy của anh ta giữa các cộng sự của anh ta, Max bất lực nhìn thực tế được tạo ra thành từng mảnh, khiến anh ta phải tìm kiếm khoảng trống ở giữa.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Happy Anderson","avatar":""},{"name":"Heidi Armbruster","avatar":""},{"name":"Brittany Athey","avatar":""},{"name":"Michael Badalucco","avatar":""},{"name":"Patrick Boll","avatar":""},{"name":"Theodore Bouloukos","avatar":""},{"name":"Sanford Brown","avatar":""},{"name":"Ella Dershowitz","avatar":""},{"name":"James Dewees","avatar":""},{"name":"Polly Draper","avatar":""},{"name":"Grayson Eddey","avatar":""},{"name":"Leo Fitzpatrick","avatar":""},{"name":"Daphne Gaines","avatar":""},{"name":"Cassidy Gorrell","avatar":""},{"name":"Ian Harding","avatar":""},{"name":"Frank Holley","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
