INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-bo-nhiet-tinh', 'Giả Bộ Nhiệt Tình', 'You Call It Passion', 'https://phimimg.com/upload/vod/20231115-1/452e5a23c3321c437f2b7de0be038299.jpg', 'https://phimimg.com/upload/vod/20231115-1/974b8b76d7009da01d6d16ceceafdbbc.jpg', '<p>Phim Giả Bộ Nhiệt Tình - You Call It Passion 2015 là câu chuyện về một phóng viên của mãng thông tin giải trí. Cô lả một phóng viên trẻ đầy nhiệt huyết và năng lượng. Vì tình chất nghề nghiệp nên cô lăn xả thường xuyên và va chạm với rất nhiều vấn đề, gặp nhiều người và cũng thường xuyên rơi vào những tình huống dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Bo-young","avatar":""},{"name":"Jung Jae-young","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Ryu Hyun-kyung","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Yoon Kyun-sang","avatar":""},{"name":"Ryu Deok-hwan","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Son Seong-chan","avatar":""},{"name":"Hyun Jyu-ni","avatar":""},{"name":"Lee Yeong-jin","avatar":""},{"name":"Teo Yoo","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Kim Gook-jin","avatar":""},{"name":"Seo Dong-won","avatar":""},{"name":"Shin Yeon-sook","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
