INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-sherlock-holmes', 'Ngài Sherlock Holmes', 'Mr. Holmes', 'https://phimimg.com/upload/vod/20231115-1/b31f6b33cf1f428afbbb7a4d0384406d.jpg', 'https://phimimg.com/upload/vod/20231115-1/edb5a501a7f50c0f7823054858955758.jpg', '<p>Năm 1947, đã về hưu từ lâu và gần cuối đời, Sherlock Holmes phải vật lộn với một trí nhớ không đáng tin cậy và phải nhờ đến con trai của người quản gia khi anh xem lại vụ án vẫn chưa được giải quyết dẫn đến việc nghỉ hưu của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ian McKellen","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Milo Parker","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Roger Allam","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Hattie Morahan","avatar":""},{"name":"Phil Davis","avatar":""},{"name":"Patrick Kennedy","avatar":""},{"name":"John Sessions","avatar":""},{"name":"Frances Barber","avatar":""},{"name":"Charles Maddox","avatar":""},{"name":"Takako Akashi","avatar":""},{"name":"Zak Shukor","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"David Foxxe","avatar":""},{"name":"Oliver Devoti","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
