INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-nguoi-tinh-cu-2-lop-du-phong-phan-cong', 'Cuộc chiến người tình cũ 2: Lốp dự phòng phản công', 'Ex-Files 2', 'https://phimimg.com/upload/vod/20231113-1/0a2f57d62e531a1d661610163787fa50.jpg', 'https://phimimg.com/upload/vod/20231113-1/56f0b789bbfa7bc699b3189e535bcb37.jpg', '<p>Y Trạch, biên tập viên chương trình truyền hình đã gặp lại Dư Phi, một ngôi sao mà cô từng tình cờ quen biết từ nhiều năm trước. Cuộc gặp tình cờ lần này của họ khiến Y Trạch như rơi vào giấc mộng. Đương lúc Y Trạch mơ về mộng đẹp thành sự thực, thì câu chuyện cổ tích lại tan tành, khiến cô âm thầm đưa ra một quyết định... Trong trò chơi “động tâm trước là thua cuộc” này, ai mới là người giành chiến thắng cuối cùng đây?</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ryan Zheng Kai","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Eric Wang","avatar":""},{"name":"Zhang Dianlun","avatar":""},{"name":"Zhang Yixing","avatar":""},{"name":"Qiqi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
