INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-phao-nhi', 'Lão Pháo Nhi', 'Mr. Six', 'https://phimimg.com/upload/vod/20231113-1/b28909e2559ada8e3607c110c092887c.jpg', 'https://phimimg.com/upload/vod/20231113-1/96a66e09127d02e3e8eefa942ecbfb7a.jpg', '<p>Lão Lục (Phùng Tiểu Cương), vốn là trùm thế lực ngầm cũ tại Bắc Kinh, sau nhiều năm lăn lộn, ông không thích ứng được với sự thay đổi của thời thế nên đã chọn một cuộc sống an nhàn. Nào ngờ, người con trai độc nhất của Lão Lục là Hiểu Ba (Lý Dịch Phong) lại có xích mích với người cầm đầu thế lực mới Tiểu Phi (Ngô Diệc Phàm). Một lần, Hiểu Ba và Tiểu Phi xảy ra tranh chấp, vì cứu con trai mà Lão Lục đã buộc phải ra mặt giải quyết.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Xiaogang","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Kris Wu","avatar":""},{"name":"Li Yifeng","avatar":""},{"name":"Liu Hua","avatar":""},{"name":"Liang Jing","avatar":""},{"name":"Bai Jugang","avatar":""},{"name":"Yu Hewei","avatar":""},{"name":"Lian Yiming","avatar":""},{"name":"Shang Yuxian","avatar":""},{"name":"Jiang Shan","avatar":""},{"name":"Lenox Lu","avatar":""},{"name":"Zongxiang Guan","avatar":""},{"name":"Ning Hao","avatar":""},{"name":"Tao Zeru","avatar":""},{"name":"Du Jun","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Zhang Yishan","avatar":""},{"name":"Fa Zhi Yuan","avatar":""},{"name":"Pang Guochang","avatar":""},{"name":"Tong Lei","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
