INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-thet-quy-du', 'Tiếng Thét Quỹ Dữ', 'Scream at the Devil', 'https://phimimg.com/upload/vod/20231112-1/2559ac8cc121464f06707dd7bd4381fe.jpg', 'https://phimimg.com/upload/vod/20231112-1/e871f65c804fa15894775a273e60781e.jpg', '<p>Phim Tiếng Thét Quỹ Dữ - Scream At The Devil (2016): Một phụ nữ xinh đẹp bị tâm thần phân liệt khốn khổ đến tột cùng vì chồng mình ngoại tình, và khi những ảo giác của cô dần thành sự thật thì Ác Quỷ tìm đến đòi món nợ của mình. Có phải Miriam bị điên hay Ác Quỷ thật sự đến để lấy mạng cô như đã hứa?</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shari Shattuck","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Jane Park Smith","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Kiko Ellsworth","avatar":""},{"name":"Bill Oberst Jr.","avatar":""},{"name":"Jennifer Lyons","avatar":""},{"name":"Amy Argyle","avatar":""},{"name":"Corina Boettger","avatar":""},{"name":"Teddy Vincent","avatar":""},{"name":"Brendan Norman","avatar":""},{"name":"Julia Morizawa","avatar":""},{"name":"Marti Hale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324452);
