INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieng-thet-quy-du', 'Tiếng Thét Quỹ Dữ', 'Scream at the Devil', 'tiếng thét quỹ dữ scream at the devil shari shattuck eric etebari jane park smith tony todd kiko ellsworth bill oberst jr. jennifer lyons amy argyle corina boettger teddy vincent brendan norman julia morizawa marti hale ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-spy-quest', 'Tom và Jerry: Spy Quest', 'Tom and Jerry: Spy Quest', 'https://phimimg.com/upload/vod/20231112-1/6af25c4cce31a6774e67e972f80c83c1.jpg', 'https://phimimg.com/upload/vod/20231112-1/c6852636ef24f835a98a527feba7ebae.jpg', '<p>Hai nhóm nhân vật hoạt hình cổ điển đến với nhau trong chiếc crossover đầy thú vị này với loạt phim hoạt hình phiêu lưu-phiêu lưu nổi tiếng Jonny Quest. Những người hâm mộ ở mọi lứa tuổi sẽ không muốn bỏ lỡ cuộc phiêu lưu ở trái tim này là Tussome Tom và Jerry tham gia Jonny Quest và Pal Hadji và bắt tay vào một nhiệm vụ gián điệp nguy hiểm để cứu thế giới. Chỉ là một ngày khác ở bãi biển cho Dueling Tom và Jerry ... cho đến khi họ va vào các điệp viên Junior thế giới Jonny Quest và Hadji và người bạn đồng hành của họ, tên cướp. Khi FIGHTIME FUME NEMESIS, Tiến sĩ Zin phát hiện ra rằng Cha của Jonny, Tiến sĩ Benton Quest, sở hữu một thiết bị có thể giải quyết các vấn đề về năng lượng của thế giới, Zin sẽ gửi đội quân ác quỷ độc ác của mình để đánh cắp nó và bắt Benton và vệ sĩ của anh ta, Race Bannon. Đó là khi Jonny và những người bạn lông xù mới của anh ấy vào hành động! Được thiết lập cho mưu mô, hồi hộp và hồi hộp cho cả gia đình. Tia Carrere và Tim Matheson cho vay tiếng nói của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Hartwig","avatar":""},{"name":"James Hong","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Tim Matheson","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Richard McGonagle","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"Joe Alaskey","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
