INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-trung-phat-cua-krampus', 'Sự Trừng Phạt Của Krampus', 'Krampus: The Reckoning', 'https://phimimg.com/upload/vod/20231111-1/e16bbc25ee6b92b70440287f691802ab.jpg', 'https://phimimg.com/upload/vod/20231111-1/19f0b9fff4190bf15552e508a71b9ead.jpg', '<p>Người bạn đồng hành đen tối của Thánh Nick, Krampus đã được thả ra tại một thị trấn nhỏ và con quỷ huyền thoại sẽ tìm kiếm tất cả những kẻ xấu để trừng phạt họ vào dịp Giáng sinh. Không ai an toàn khi Krampus săn lùng, tra tấn và sau đó kéo linh hồn bất lực của chúng xuống vực sâu của địa ngục.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Monica Engesser","avatar":""},{"name":"Amelia Haberman","avatar":""},{"name":"James Ray","avatar":""},{"name":"Kevin Tye","avatar":""},{"name":"Sean G.P. Anderson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324452);
