INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-di-tim-vo-cuc', 'Người Đi Tìm Vô Cực', 'The Man Who Knew Infinity', 'https://phimimg.com/upload/vod/20231113-1/f177e9ad6e34778955b608a866f0f487.jpg', 'https://phimimg.com/upload/vod/20231113-1/56e6aece792fd6b5e58f3d9619a95ff7.jpg', '<p>Lớn lên trong nghèo khó ở Madras, Ấn Độ, Srinivasa Ramanujan Iyengar được nhận vào Đại học Cambridge trong Thế chiến I, nơi ông trở thành người tiên phong trong lý thuyết toán học với sự hướng dẫn của giáo sư G.H. Hardy.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dev Patel","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Devika Bhise","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Jeremy Northam","avatar":""},{"name":"Anthony Calf","avatar":""},{"name":"Pádraic Delaney","avatar":""},{"name":"Shazad Latif","avatar":""},{"name":"Roger Narayan","avatar":""},{"name":"Arundathi Nag","avatar":""},{"name":"Dhritiman Chatterjee","avatar":""},{"name":"Richard Johnson","avatar":""},{"name":"Raghuvir Joshi","avatar":""},{"name":"Malcolm Sinclair","avatar":""},{"name":"San Shella","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
