INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-ban-tac-chien', 'Đôi Bạn Tác Chiến', 'Arthur & Merlin', 'https://phimimg.com/upload/vod/20231113-1/b0ce423829d8616e79b2cfef76b4cbd8.jpg', 'https://phimimg.com/upload/vod/20231113-1/67f07aa48aa841d0a27387e2ae4bc8b5.jpg', '<p>Trong thời kỳ đen tối của nước Anh, thời kỳ của ma thuật và huyền thoại, một tu sĩ ma túy quyền năng quyết tâm tiêu diệt người Celtic. Arthur, một chiến binh bị trục xuất và Merlin, một phù thủy ẩn dật, bắt tay vào một nhiệm vụ anh hùng để ngăn chặn ma túy và cứu người dân của họ, trước khi người Celt biến mất mãi mãi và trở thành huyền thoại.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kirk Barker","avatar":""},{"name":"Adrian Bouchet","avatar":""},{"name":"David Sterne","avatar":""},{"name":"Nigel Cooke","avatar":""},{"name":"Charlotte Brimble","avatar":""},{"name":"Nicholas Asbury","avatar":""},{"name":"Andrew Grose","avatar":""},{"name":"Garth Maunders","avatar":""},{"name":"Joseph Attenborough","avatar":""},{"name":"Jack Rigby","avatar":""},{"name":"Alison Harris","avatar":""},{"name":"Stefan Butler","avatar":""},{"name":"Harvey Walsh","avatar":""},{"name":"Jack Maw","avatar":""},{"name":"Hattie Pardy-McLaughlin","avatar":""},{"name":"Helen Phillips","avatar":""},{"name":"Garet","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324452);
