INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mat-danh-47', 'Sát Thủ: Mật Danh 47', 'Hitman: Agent 47', 'https://phimimg.com/upload/vod/20231113-1/eb753a54d7e5938952833280f3b3348b.jpg', 'https://phimimg.com/upload/vod/20231113-1/47363b154d943279ae7337fc259a085c.jpg', '<p>HITMAN: AGENT 47 tập trung vào một sát thủ ưu tú đã được biến đổi gen từ lúc thụ thai. Anh ta là cỗ máy giết người hoàn hảo và chỉ được biết đến bởi hai chữ số xăm trên lưng mình. Anh là đỉnh cao thành quả nghiên cứu và nhân bản của 46 đặc vụ trước. &nbsp;Với sức mạnh chưa từng thấy, tốc độ, sức chịu đựng và sự thông minh, mục tiêu mới nhất của anh là một công ty lớn có kế hoạch để giải mã những bí mật của Agent 47 để tạo ra một đội quân giết người khủng khiếp. Hợp tác với một người phụ nữ trẻ, những người có thể giữ bí mật để vượt qua kẻ thù lớn mạnh, Đặc vụ 47 sẽ đối mặt với nguồn gốc và kẻ thù nguy hiểm nhất của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rupert Friend","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Hannah Ware","avatar":""},{"name":"Emilio Rivera","avatar":""},{"name":"Rolf Kanies","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Dan Bakkedahl","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Mona Pirzad","avatar":""},{"name":"William E. Morris","avatar":""},{"name":"Michaela Caspar","avatar":""},{"name":"Jerry Hoffmann","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Charlene Beck","avatar":""},{"name":"Michael Bornhütter","avatar":""},{"name":"Melis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{