INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-phong-quy-du', 'Giải Phóng Quỷ Dữ', 'Exeter', 'https://phimimg.com/upload/vod/20231111-1/b4e7eb35f3e4becd19f01d8814f20747.jpg', 'https://phimimg.com/upload/vod/20231111-1/190720100dccec101cdd57c6debe6f12.jpg', '<p>Giải Phóng Quỷ Dữ - Exeter: Đây là một bộ phim kể về một nơi đươc gọi là Exeter nơi những người có vấn đề về thần kinh được đưa tới, họ sống giống như những cái xác không hồn. Bị xã hội vứt bỏ, nơi đây trở thành nỗi ám ảnh của những ai đến gần. Một nhóm thanh niên tụ tập ăn chơi ở đây và rồi họ vô tình giải phóng một con quỷ gieo rắc nỗi kinh hoàng. Họ sẽ làm gì để thoát khỏi nơi ám ảnh này và tìm cách sống sót trở...</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Lang","avatar":""},{"name":"Kelly Blatz","avatar":""},{"name":"Brittany Curran","avatar":""},{"name":"Gage Golightly","avatar":""},{"name":"Nick Nicotera","avatar":""},{"name":"Michael Ormsby","avatar":""},{"name":"Brett Dier","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Nick Nordella","avatar":""},{"name":"Laura Putnam","avatar":""},{"name":"Meredith Prunty","avatar":""},{"name":"Ashley Tramonte","avatar":""},{"name":"Shannon Hartman","avatar":""},{"name":"Lindsay MacDonald","avatar":""},{"name":"Caitlin O''Neill","avatar":""},{"name":"Hilary Pingle","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324452);
