INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-be', 'Hoàng Tử Bé', 'The Little Prince', 'https://phimimg.com/upload/vod/20231111-1/8cd6e1787ff5663ee08eadfbd488b70e.jpg', 'https://phimimg.com/upload/vod/20231111-1/22eaff2ba35daf090f2f397945494b6f.jpg', '<p>Aviator giới thiệu một cô gái đến một thế giới nơi cô ấy khám phá lại tuổi thơ của mình và biết rằng mối liên hệ giữa con người với nhau là quan trọng nhất, và chỉ bằng trái tim người ta mới có thể nhìn thấy đúng; điều gì tốt cho mắt.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Riley Osborne","avatar":""},{"name":"Mackenzie Foy","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"James Franco","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Bud Cort","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Albert Brooks","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Jacquie Barnbrook","avatar":""},{"name":"Marcel Bridges","avatar":""},{"name":"Jeffy Branion","avatar":""},{"name":"Maddie Osborne","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324452);
