INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('joker-game', 'Joker Game', 'Joker Game', 'https://phimimg.com/upload/vod/20231111-1/f0df11b1e76615807a31dec40ea54c27.jpg', 'https://phimimg.com/upload/vod/20231111-1/701f71bad78ad6de16bb18b768ce6b5f.jpg', '<p>Lấy bối cảnh của một cuộc chiến tranh thế giới thứ hai hư cấu tại một thành phố quốc tế ở châu Á. Tại Nhật Bản, Trung tá Yuki (Yusuke Iseya) đề nghị thành lập trường đào tạo gián điệp &quot;D Kikan&quot;. Trong khi đó, Kato (Kazuya Kamenashi) đang phải đối mặt với án tử hình vì không tuân lệnh cấp trên. Kato sau đó được &quot;D Kikan&quot; do thám. Anh trải qua một trung đoàn huấn luyện khắc nghiệt và đối mặt với nhiệm vụ đầu tiên với tư cách là một điệp viên. Để thu giữ các tài liệu bí mật của đại sứ Mỹ Graham &quot;Black Note.&quot; Kato thâm nhập vào một thành phố quốc tế. Một cuộc chiến giành quyền sở hữu &quot;Black Note&quot; xảy ra giữa Kato, một người phụ nữ bí ẩn tên Rin (Kyoko Fukada), Cơ quan gián điệp Anh, Cơ quan gián điệp Liên Xô và quân đội cực đoan ở Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuya Kamenashi","avatar":""},{"name":"Kyoko Fukada","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Hiroshi Yamamoto","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Kyūsaku Shimada","avatar":""},{"name":"Hiromasa Taguchi","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Keisuke Koide","avatar":""},{"name":"Richard Shelton","avatar":""},{"name":"Jasper Bagg","avatar":""},{"name":"Richard Moss","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
