INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-cong-tac-ba-dao', 'Chuyến Công Tác Bá Đạo', 'Unfinished Business', 'https://phimimg.com/upload/vod/20231111-1/d49692fdc1165f5ce8a79a307ffbcb77.jpg', 'https://phimimg.com/upload/vod/20231111-1/69ce6c0c5e326615270142073d4c009a.jpg', '<p>Chuyến Công Tác Bá Đạo - Unfinished Business kể về chuyến đi công tác làm ăn rất bá đạo của Dan Trunkman cùng hai đồng nghiệp của mình là Timothy McWinters và Mike Pancake. Họ cần phải chốt một hợp đồng cực kì quan trọng đối với họ, tuy nhiên, chuyến công tác bỗng đi chệch hướng và tràn ngập những chi tiết bất ngờ.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"James Marsden","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Ella Anderson","avatar":""},{"name":"Anastasia Sanidopoulos Mousis","avatar":""},{"name":"Melissa McMeekin","avatar":""},{"name":"David C. Bunners","avatar":""},{"name":"Frowin Wolter","avatar":""},{"name":"Britton Sear","avatar":""},{"name":"Kasia Malinowska","avatar":""},{"name":"Michael Krabbe","avatar":""},{"name":"Uwe Oc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
