INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-cong-tac-ba-dao', 'Chuyến Công Tác Bá Đạo', 'Unfinished Business', 'chuyến công tác bá đạo unfinished business vince vaughn dave franco sienna miller tom wilkinson james marsden june diane raphael nick frost ella anderson anastasia sanidopoulos mousis melissa mcmeekin david c. bunners frowin wolter britton sear kasia malinowska michael krabbe uwe oc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thu-nghiem', 'Người Thử Nghiệm', 'Experimenter', 'https://phimimg.com/upload/vod/20231111-1/73a7744c81d9923d2ff67e6265d5187c.jpg', 'https://phimimg.com/upload/vod/20231111-1/fb1e933298594fc2ccc9b6873118bee4.jpg', '<p>Đại học Yale, 1961. Stanley Milgram thiết kế một thí nghiệm tâm lý vẫn còn gây tiếng vang cho đến ngày nay, trong đó mọi người nghĩ rằng họ đang gây ra những cú sốc điện đau đớn cho một người lạ mặt dễ mến bị trói vào một chiếc ghế trong phòng khác. Bất chấp những lời cầu xin của anh ấy, phần lớn các đối tượng không dừng thí nghiệm, thực hiện những gì họ nghĩ là một cú sốc điện suýt chết, đơn giản vì họ được yêu cầu làm như vậy. Với phiên tòa xét xử Adolf Eichmann của Đức Quốc xã được phát sóng trong các phòng khách trên khắp nước Mỹ, Milgram đã gây chấn động trong nền văn hóa đại chúng và cộng đồng khoa học với khám phá của ông về xu hướng tuân thủ quyền lực của mọi người. Nổi tiếng trong một số giới, anh ta cũng bị buộc tội là một con quái vật lừa đảo, lôi kéo, nhưng vợ anh ta, Sasha, đã sát cánh bên anh ta vượt qua tất cả.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Sarsgaard","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Edoardo Ballerini","avatar":""},{"name":"John Palladino","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Danny A. Abeckaser","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Anthony Edwards","avatar":""},{"name":"Lori Singer","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Adriana Randall","avatar":""},{"name":"Donnie Keshawarz","avatar":""},{"name":"Michael Siberry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324452);
