INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-giua-doi-dong-xuan', 'Sống giữa đời: Đông Xuân', 'Little Forest: Winter-Spring', 'https://phimimg.com/upload/vod/20231111-1/fe48054ccc75502fabccc42daed4d2cd.jpg', 'https://phimimg.com/upload/vod/20231111-1/8cfe4718a20e2065030de25d908a80a9.jpg', '<p>Cốt truyện nói về Ichiko sau khi rời khỏi thành phố để sống độc lập trong cộng đồng Komori ở Tohoku (Little Forest). Câu chuyện nói về bản chất và thực phẩm thay đổi theo mùa trong khi Ichiko thì nấu ăn mỗi ngày để duy trì cuộc sống độc lập của mình. Igarashi (tác giả Children of the Sea, Hanashippanashi) đã từng sống cuộc sống độc lập như Ichiko. Kinh nghiệm từ cuộc sống trong túp lều trên núi ở tỉnh Iwate Tohoku đã truyền cảm hứng cho câu chuyện.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Hashimoto","avatar":""},{"name":"Takahiro Miura","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Yoichi Nukumizu","avatar":""},{"name":"Karen Kirishima","avatar":""},{"name":"Momone Shinokawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
