INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-hiem-dang-yeu', 'Nguy Hiểm Đáng Yêu', 'Sevimli Tehlikeli', 'https://phimimg.com/upload/vod/20231110-1/79713a646268608df6d6f9a4ea886998.jpg', 'https://phimimg.com/upload/vod/20231110-1/b13d33a292abf28606f54ba9018c597b.jpg', '<p>Nhiều năm trước, Zarok đã bắt cóc một bé gái còn nằm trong nôi ở Edirne, khiến một gia đình phải nếm trải nỗi đau lớn suốt đời. Nhiều năm trôi qua, Zarok nắm bắt cơ hội. Để giảm bớt sự hối hận, lần này anh ta sẽ bắt cóc cô gái mà anh ta đã bắt cóc trước đó và đưa cô ta trở về với gia đình thực sự của mình! Nhưng trong quá trình này, một cuộc phiêu lưu đầy tình yêu đang chờ đợi cả hai nhân vật...</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Şükrü Özyıldız","avatar":""},{"name":"Ayça Ayşin Turan","avatar":""},{"name":"Türkan Kılıç","avatar":""},{"name":"Taner Turan","avatar":""},{"name":"Cem Avnayim","avatar":""},{"name":"Ahmet Özarslan","avatar":""},{"name":"Burçin Birben","avatar":""},{"name":"Evrim Doğan","avatar":""},{"name":"Ergun Kuyucu","avatar":""},{"name":"Efe Deprem","avatar":""},{"name":"Zeynep Anıl Tatdıran","avatar":""},{"name":"Seher Terzi","avatar":""},{"name":"Gamze Topuz","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
