INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-2015', 'Không Lối Thoát', 'No Escape', 'https://phimimg.com/upload/vod/20231110-1/a6424f63f3a2b893feb208787f1b3c4d.jpg', 'https://phimimg.com/upload/vod/20231110-1/38d547ae8b2183880414c4b2c5bdfe96.jpg', '<p>Tại ngôi nhà mới ở nước ngoài, một gia đình người Mỹ sớm phát hiện ra mình đang bị cuốn vào giữa một cuộc đảo chính, và họ điên cuồng tìm kiếm một lối thoát an toàn trong một môi trường mà người nước ngoài đang bị hành quyết ngay lập tức.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Sterling Jerins","avatar":""},{"name":"Claire Geare","avatar":""},{"name":"Spencer Garrett","avatar":""},{"name":"Sahajak Boonthanakit","avatar":""},{"name":"Tanapol Chuksrida","avatar":""},{"name":"Nophand Boonyai","avatar":""},{"name":"Byron Gibson","avatar":""},{"name":"Matthew Timothy Olynyk","avatar":""},{"name":"Stacy Chbosky","avatar":""},{"name":"Suphornaphat Annie Jenselius","avatar":""},{"name":"Hiroyuki Kobayashi","avatar":""},{"name":"Thanaw","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
