INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('iliza-shlesinger-freezing-hot', 'Iliza Shlesinger: Freezing Hot', 'Iliza Shlesinger: Freezing Hot', 'https://phimimg.com/upload/vod/20231110-1/1b10592bdb9a919ef69d7320e2ebd48e.jpg', 'https://phimimg.com/upload/vod/20231110-1/b8feb91b20d15f93a43614f00f5bf5db.jpg', '<p>Diễn viên hài thông minh và trơ trẽn Iliza Shlesinger chia sẻ những quan sát trung thực không nao núng của cô ấy về sự khác biệt giữa đàn ông và phụ nữ. Với đầy những cụm từ bắt mắt có thể sử dụng thẻ bắt đầu bằng dấu thăng, đây là một tiết lộ cười phá lên phơi bày một số bí mật được giữ kín nhất - và xấu xí nhất - của phụ nữ, bao gồm sự thật về trang phục trong buổi hẹn hò đầu tiên, những cuộc chia tay tưởng tượng và sự theo đuổi không mệt mỏi để không bị lạnh lùng khi vẫn còn trông nóng bỏng.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iliza Shlesinger","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
