INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-dao-choi-trong-rung', 'Chuyến Dạo Chơi Trong Rừng', 'A Walk in the Woods', 'https://phimimg.com/upload/vod/20231110-1/64492b6d263bb6db783c64cdb7ddd2e8.jpg', 'https://phimimg.com/upload/vod/20231110-1/08198d6316819d1641992768af8f8c71.jpg', '<p>Phim Chuyến Dạo Chơi Trong Rừng - A Walk in the Woods 2015 kể về, Bill Bryson trở về Mỹ, sau hai thập kỷ tại Anh, nơi ông quyết định cách tốt nhất để kết nối với quê hương của ông là đi lang thang trên Appalachian Trail với một người bạn lâu đời nhất của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Chrystee Pharris","avatar":""},{"name":"Sandra Ellis Lafferty","avatar":""},{"name":"Hayley Lovitt","avatar":""},{"name":"Derek Krantz","avatar":""},{"name":"Andrew Vogel","avatar":""},{"name":"Linds Edwards","avatar":""},{"name":"R. Keith Harris","avatar":""},{"name":"John Kap","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Randall Newsome","avatar":""},{"name":"Susan McPhail","avatar":""},{"name":"Gaia","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
