INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-om-cua-xa-nhan', 'Cái Ôm của Xà Nhân', 'Embrace of the Serpent', 'https://phimimg.com/upload/vod/20231109-1/4d6be8b4657afb66ecfd91ab29c4cb72.jpg', 'https://phimimg.com/upload/vod/20231109-1/f971639ebb22d7ba8dfee3ed539d0c35.jpg', '<p>Embrace of the Serpent - El abrazo de la serpiente (Cái Ôm Của Xà Nhân) sản xuất năm 2015 là một bộ phim phiêu lưu hay và ý nghĩa về cuộc sống, sức mạnh của con người khi phải vượt qua những khó khăn gian khổ để sinh tồn, để đương đầu với thiên nhiên khắc nghiệt. Xoay quanh câu chuyện của hai nhà thám hiểm Theodor Koch-Grunberg (Jan Bijvoet) và Richard Evans Schultes (Brionne Davis) tìm hiểu về các bộ lạc vẫn còn đâu đó trong rừng già và những thứ chưa được khám phá. Tác phẩm đến từ Colombia là hai câu chuyện đan xen, một xảy ra ở năm 1909 và một xảy ra ở năm 1940. Karamakate (Nilbio Torres) là một pháp sư, cũng là người cuối cùng của một bộ lạc vùng Amazon. Ông đồng hành với hai nhà khoa học Mỹ và Đức trong chuyến tìm loài cây thiêng có tên Yakruna...</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Nilbio Torres","avatar":""},{"name":"Antonio Bolívar","avatar":""},{"name":"Jan Bijvoet","avatar":""},{"name":"Brionne Davis","avatar":""},{"name":"Yauenkü Miguee","avatar":""},{"name":"Luigi Sciamanna","avatar":""},{"name":"Nicolás Cancino","avatar":""},{"name":"Pediwake Daniel Martínez","avatar":""},{"name":"José Sabogal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324452);
