INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-thuy-danh-bo-4-muc-tieu-di-dong', 'Lính Thủy Đánh Bộ 4: Mục Tiêu Di Động', 'The Marine 4: Moving Target', 'https://phimimg.com/upload/vod/20231109-1/ef608f978ee03efe098a50759a9d7f47.jpg', 'https://phimimg.com/upload/vod/20231109-1/24ba454e33c2ab6b8363c366605b7006.jpg', '<p>Jake Carter được chỉ định để bảo vệ &quot;gói có giá trị cao&quot;, một người tố giác xinh đẹp đang cố gắng phơi bày một nhà thầu phòng thủ quân đội tham nhũng.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Mizanin","avatar":""},{"name":"Summer Rae","avatar":""},{"name":"Atlin Mitchell","avatar":""},{"name":"Melissa Roxburgh","avatar":""},{"name":"Josh Blacker","avatar":""},{"name":"Paul McGillion","avatar":""},{"name":"Curtis Caravaggio","avatar":""},{"name":"Matthew MacCaull","avatar":""},{"name":"Primo Allon","avatar":""},{"name":"Fraser Aitcheson","avatar":""},{"name":"Roark Critchlow","avatar":""},{"name":"David James Lewis","avatar":""},{"name":"Craig Veroni","avatar":""},{"name":"Dominic Downer","avatar":""},{"name":"Dometrius Hill","avatar":""},{"name":"Todd Jenkins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
