INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-thuy-danh-bo-4-muc-tieu-di-dong', 'Lính Thủy Đánh Bộ 4: Mục Tiêu Di Động', 'The Marine 4: Moving Target', 'lính thủy đánh bộ 4: mục tiêu di động the marine 4: moving target mike mizanin summer rae atlin mitchell melissa roxburgh josh blacker paul mcgillion curtis caravaggio matthew maccaull primo allon fraser aitcheson roark critchlow david james lewis craig veroni dominic downer dometrius hill todd jenkins ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-thanh', 'Mê Thành', 'Wild City', 'https://phimimg.com/upload/vod/20231109-1/8c1b12753c4d4fefca9cdc8cd2dc37bd.jpg', 'https://phimimg.com/upload/vod/20231109-1/1ba6cd494a68f2b0e9a0a34773bad371.jpg', '<p>Tái hiện cuộc sống mưu sinh vô cùng khó khăn của những con người lạc lối trong xã hội hiện đại. Trong đó, có một chàng trai bản chất lương thiện, tốt bụng, gia đình anh phá sản vì khủng hoảng kinh tế. Do sự cám dỗ của xã hội khi phải mưu sinh sống qua ngày, người thanh niên vô tình trở thành một tay chơi khét tiếng ai ai cũng phải khiếp sợ. Mặt trái của đồng tiền khiến con người thay đổi một cách đáng sợ và để lại nhiều suy ngẫm trong lòng người xem.</p>', 'Full', 1, 'single', 'completed', 10, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Yuen Qiu","avatar":""},{"name":"Joseph Chang","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Marc Ma","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Alex Lam Chi-Sin","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Edward Chui","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Marcus Fok","avatar":""},{"name":"Ken Law Ho-Ming","avatar":""},{"name":"Cheung Lap-Fung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324452);
