INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thoi-gian', 'Bão Thời Gian', 'Flight World War II', 'https://phimimg.com/upload/vod/20231109-1/19258bb7fd4472d9696857104caca73a.jpg', 'https://phimimg.com/upload/vod/20231109-1/a601bc25d8185dabc8e7b77c6ab78aeb.jpg', '<p>Phim Flight World War II chuyến bay 42 đang bay thì một cơn bão xuất hiện, lúc họ vừa thấy cơn bão thì máy bay của họ đã quá gần với cơn bão, họ đi vào trong cơn bão. Bất ngờ thay khi họ bay ra khỏi cơn bão, thì tiếng bom đạn nã nhau rất dữ dội, họ không ngờ rằng mình đã đi về quá khứ, vào thời điểm năm 1940, lúc mà Chiến Tranh Thế Giới Thứ 2 đang diễn ra.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Faran Tahir","avatar":""},{"name":"Robbie Kay","avatar":""},{"name":"Aqueela Zoll","avatar":""},{"name":"Matias Ponce","avatar":""},{"name":"Alberto Barros Jr.","avatar":""},{"name":"Vi Flaten","avatar":""},{"name":"David Campfield","avatar":""},{"name":"Angie Teodora Dick","avatar":""},{"name":"Erik MacRay","avatar":""},{"name":"Daniel Mentz","avatar":""},{"name":"Jason Wesley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324452);
