INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tot-thi-mang', 'Con Tốt Thí Mạng', 'Pawn Sacrifice', 'https://phimimg.com/upload/vod/20231110-1/0f331af997eedd346a1976e8e06f4d91.jpg', 'https://phimimg.com/upload/vod/20231110-1/0b9255775c28202aa37cf19fca02a321.jpg', '<p>Phim về cuộc đời của Bobby Fischer và tái hiện lại ván cờ huyền thoại giữa ông và Boris Spassky tại giải World Chess Championship năm 1972. Sau “Bobby Fischer Against The World”, một lần nữa, fan hâm mộ cờ vua sẽ được ngắm nhìn lại sự nghiệp của một đại kiện tướng có tính cách “quái dị” nhất trong lịch sử cờ vua thế giới.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Lily Rabe","avatar":""},{"name":"Sophie Nélisse","avatar":""},{"name":"Seamus Davey-Fitzpatrick","avatar":""},{"name":"Conrad Pla","avatar":""},{"name":"Aiden Lovekamp","avatar":""},{"name":"Evelyne Brochu","avatar":""},{"name":"Robin Weigert","avatar":""},{"name":"Andreas Apergis","avatar":""},{"name":"Katie Bird Nolan","avatar":""},{"name":"Ilia Volok","avatar":""},{"name":"Peter Janov","avatar":""},{"name":"Spiro Malandraki","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
