INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-no-mau', 'Đòi Nợ Máu', 'Lila & Eve', 'https://phimimg.com/upload/vod/20231110-1/6260ed5c5b464f8f139149365739c907.jpg', 'https://phimimg.com/upload/vod/20231110-1/b2e7b2ecbe3b8c7393ff74c8c78494d7.jpg', '<p>Lila, một người mẹ đau buồn quay cuồng với cái chết của con trai mình, tham gia một nhóm hỗ trợ nơi cô gặp Eve, người thúc giục cô tự mình giải quyết vấn đề để truy tìm những kẻ giết con trai mình.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Viola Davis","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Aml Ameen","avatar":""},{"name":"Andre Royo","avatar":""},{"name":"Chris Chalk","avatar":""},{"name":"Julius Tennon","avatar":""},{"name":"Yolonda Ross","avatar":""},{"name":"Rey Hernandez","avatar":""},{"name":"Whitney Goin","avatar":""},{"name":"Michole Briana White","avatar":""},{"name":"Will Brittain","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
