INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spongebob-anh-hung-len-can', 'SpongeBob: Anh Hùng Lên Cạn', 'The SpongeBob Movie: Sponge Out of Water', 'https://phimimg.com/upload/vod/20231110-1/7a77adf36c6ea4dd31bd98e29c6209ac.jpg', 'https://phimimg.com/upload/vod/20231110-1/e9d9d8f3c44fef76152aa8766ac2df1c.jpg', '<p>Burger Beard là một tên cướp biển đang tìm kiếm trang cuối cùng của một cuốn sách ma thuật có thể biến mọi kế hoạch xấu xa mà anh ta viết trong đó thành hiện thực, đó là công thức bí mật của Krabby Patty. Khi toàn bộ thành phố Bikini Bottom gặp nguy hiểm, SpongeBob, Patrick, Mr. Krabs, Squidward, Sandy và Plankton cần thực hiện một nhiệm vụ đưa họ lên mặt đất. Để lấy lại công thức và cứu thành phố của mình, cả nhóm phải lấy lại cuốn sách và biến mình thành siêu anh hùng.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2015, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Tom Kenny","avatar":""},{"name":"Bill Fagerbakke","avatar":""},{"name":"Rodger Bumpass","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Mr. Lawrence","avatar":""},{"name":"Carolyn Lawrence","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Eric Bauza","avatar":""},{"name":"Tim Conway","avatar":""},{"name":"Eddie Deezen","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"April Stewart","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"Billy West","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Nolan North","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong"