INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('90-phut-o-thien-duong', '90 Phút Ở Thiên Đường', '90 Minutes in Heaven', 'https://phimimg.com/upload/vod/20231109-1/1b5f74cf80066812e1a957bd1925b196.jpg', 'https://phimimg.com/upload/vod/20231109-1/8f6f1dc60439f92020ee5d3d79138a8d.jpg', '<p>Khoảng 90 phút sau khi nhà chức trách thông báo anh đã qua đời tại hiện trường một vụ tai nạn, một mục sư trẻ sống lại và nói rằng mình vừa lên Thiên đàng.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Bosworth","avatar":""},{"name":"Hayden Christensen","avatar":""},{"name":"Hudson Meek","avatar":""},{"name":"Bobby Batson","avatar":""},{"name":"Elizabeth Hunter","avatar":""},{"name":"David Clyde Carr","avatar":""},{"name":"Catherine Carlen","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"Michael W. Smith","avatar":""},{"name":"Gianna Simone","avatar":""},{"name":"Michael Harding","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"Mark Oliver","avatar":""},{"name":"Michael Crider","avatar":""},{"name":"Marty Stonerock","avatar":""},{"name":"Cara Mantella","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
