INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-gia-gan', 'Cớm Già Gân', 'Antigang', 'https://phimimg.com/upload/vod/20231109-1/53ed43901aa108debd92ef228f8a0075.jpg', 'https://phimimg.com/upload/vod/20231109-1/11fe082ae2496347da985891b7923bcb.jpg', '<p>Phim Biệt Đội Chống Gangster - The Squad - Antigang 2015: Trong thế giới ngầm ở Paris, Buren chưa bao giờ ngại dùng tay chân và súng ống để thực thi pháp luật. đến lúc bị săm soi bởi người sếp mới – Lenoir, Buren biết rõ là ông đã hết thời. Nhưng khi một vụ ẩu Ðả có manh mối Ðến một vụ bắt cóc xảy ra, theo cảm tính của mình Buren Ðã lùng sục ngôi nhà của Kasper – từng là một tù nhân. Tuy nhiên Kasper Ðã Ðưa ra bằng chứng ngoại phạm xác thực, Buren buộc phải thả ông ta tự do. đến lúc nhân ra vụ ẩu Ðả kia chi là một phần của một phi vụ vô cùng lớn khác, không còn gì Ðể mất, Buren quyết Ðịnh phải vào cuộc dù biết rõ Ðó là một trận chiến Ðẫm máu.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Alban Lenoir","avatar":""},{"name":"Caterina Murino","avatar":""},{"name":"Oumar Diaw","avatar":""},{"name":"Stéfi Celma","avatar":""},{"name":"Sébastien Lalanne","avatar":""},{"name":"Thierry Neuvic","avatar":""},{"name":"Jean-Toussaint Bernard","avatar":""},{"name":"Jakob Cedergren","avatar":""},{"name":"Sabrina Ouazani","avatar":""},{"name":"Féodor Atkine","avatar":""},{"name":"Stephen Scardicchio","avatar":""},{"name":"Michaël Troude","avatar":""},{"name":"Karl Amoussou","avatar":""},{"name":"Frédéric Dessains","avatar":""},{"name":"Vincent G","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
