INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ky-quai', 'Thế Giới Kỳ Quái', 'Freaks of Nature', 'https://phimimg.com/upload/vod/20231108-1/6f3c200b3bab8b54529f5e059297512b.jpg', 'https://phimimg.com/upload/vod/20231108-1/f065ba9210e45bae53a93606330781d0.jpg', '<p>Khi người ngoài hành tinh tấn công Dillford, làm đảo lộn sự cân bằng siêu nhiên ở thị trấn, ba thiếu niên – con người, ma cà rồng và thây ma – hợp sức để đánh bại kẻ thù.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicholas Braun","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Josh Fadem","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Ed Westwick","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Chris Zylka","avatar":""},{"name":"Cerina Vincent","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Aurora Perrineau","avatar":""},{"name":"Ian Roberts","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324452);
