INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-toc', 'Thợ Tóc', 'The Barber', 'https://phimimg.com/upload/vod/20231108-1/880984904743d46861502663938998d4.jpg', 'https://phimimg.com/upload/vod/20231108-1/8f7e37b121bbadbc71f99ff636238988.jpg', '<p>Eugene là một thợ cắt tóc ở thị trấn nhỏ, được cộng đồng địa phương yêu mến, nhưng lại che giấu một bí mật chết người. John đang săn lùng kẻ giết người hàng loạt không phải để vạch trần hắn mà để tìm hiểu công việc kinh doanh! Họ hình thành một mối quan hệ xoắn xuýt và khiến thị trấn đảo lộn khi Eugene dạy John cách giết người.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Glenn","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Kristen Hager","avatar":""},{"name":"Chris Coy","avatar":""},{"name":"Max Arciniega","avatar":""},{"name":"Olivia Taylor Dudley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
