INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-dam-dong-dien-loan', 'Xa Đám Đông Điên Loạn', 'Far from the Madding Crowd', 'https://phimimg.com/upload/vod/20231108-1/5ff0905c5081c1f43c5eec519f4a73c4.jpg', 'https://phimimg.com/upload/vod/20231108-1/436c9487fa8b798e259b68870bbe3370.jpg', '<p>Far from the Madding Crowd dựa theo cuốn tiểu thuyết cùng tên của của nhà văn Anh Thomas Hardy. Câu chuyện bắt đầu với cuộc gặp gỡ giữa người chăn cừu Gabriel Oak và Bathsheba Everdene - cô gái trẻ đẹp, được giáo dục tốt, nghèo nhưng phù phiếm khi đến vùng đất của Gabriel Oak trong một dịp đi thăm dì của mình. Một đêm, khi đang ngủ trong lều, Gabriel Oak gần như sắp chết vì nghẹt thở, may nhờ có Bathsheba Everdene cứu mạng. Nhờ thế mà Oak rất biết ơn Bathsheba. Nhưng rồi nó lại trở thành tình yêu mãnh liệt, thế là anh quyết định cầu hôn Bathsheba Everdene nhưng cô lại từ chối dù thích anh.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Tom Sturridge","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Jessica Barden","avatar":""},{"name":"Hilton McRae","avatar":""},{"name":"Harry Peacock","avatar":""},{"name":"Bradley Hall","avatar":""},{"name":"Sam Phillips","avatar":""},{"name":"Tilly Vosburgh","avatar":""},{"name":"Victor McGuire","avatar":""},{"name":"Jamie Lee-Hill","avatar":""},{"name":"Richard Dixon","avatar":""},{"name":"Thomas Arnold","avatar":""},{"name":"Eloise Oliver","avatar":""},{"name":"David Go","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690