INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thu-toi-cua-dua-con-hoang', 'Lời Thú Tội Của Đứa Con Hoang', 'Confessions of a Prodigal Son', 'https://phimimg.com/upload/vod/20231116-1/ec75bc9c84f3c48c9156240b97be919f.jpg', 'https://phimimg.com/upload/vod/20231116-1/3e64e5eadbbc7fc0517b386e415c2afc.jpg', '<p>Lời thú tội của một đứa con hoang đàng là một câu chuyện kể lại thời hiện đại về câu chuyện Đứa con hoang đàng mà Chúa Giê-su đã kể nổi tiếng.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Sorbo","avatar":""},{"name":"Tanya Chisholm","avatar":""},{"name":"Creagen Dow","avatar":""},{"name":"Nathan Clarkson","avatar":""},{"name":"Michael Bolten","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
