INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot-giua-trung-khoi', 'Sống Sót Giữa Trùng Khơi', 'Abandoned', 'https://phimimg.com/upload/vod/20231116-1/52913ec89f99309167acbd69e9778d1b.jpg', 'https://phimimg.com/upload/vod/20231116-1/ad4fd554d41379fd67e7f27e1577671c.jpg', '<p>Bốn người đàn ông gần như chắc chắn phải bỏ mạng khi chiếc tàu của họ bị lật và họ phải trôi dạt trên biển. Nhưng kỳ diệu thay, họ về được đến nhà sau 119 ngày lênh đênh. Tuy nhiên, khi trở về, họ phải đối mặt với sự hoài nghi và thù địch từ giới truyền thông và các nhà cầm quyền. Dựa trên câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Peter Feeney","avatar":""},{"name":"Owen Black","avatar":""},{"name":"Siobhan Marshall","avatar":""},{"name":"Serena Cotton","avatar":""},{"name":"Rachel Nash","avatar":""},{"name":"Seamus Stalker","avatar":""},{"name":"Isla Thompson","avatar":""},{"name":"Jack Walley","avatar":""},{"name":"Mark Ruka","avatar":""},{"name":"Minouk van Der Valde","avatar":""},{"name":"Daniel Watterson","avatar":""},{"name":"Daniel Cleary","avatar":""},{"name":"Greg Johnson","avatar":""},{"name":"John Davies","avatar":""},{"name":"Laurie Dee","avatar":""},{"name":"Rachel Nicholls","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324452);
