INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-nguy-hiem', 'Tình Bạn Nguy Hiểm', 'The Wrong Girl', 'https://phimimg.com/upload/vod/20231116-1/c24cddecffa06a5c65860841e40d7f07.jpg', 'https://phimimg.com/upload/vod/20231116-1/f0f5aeca2e7f47c8a55a28dad9cc0fe5.jpg', '<p>Tình Bạn Nguy Hiểm - The Wrong Girl kể về Sophia - một nữ sinh trung học thông minh, thân thiện. Cô bé làm quen với bạn mới trong lớp tên Grace. Tuy nhiên, càng ngày Grace càng có những hành động gây trở ngại đến cuộc sống của Sophia cũng như gia đình cô. Điều này khiến Sophia buộc phải tìm hiểu về bí mật của người bạn mới trước khi mọi chuyện đi quá giới hạn.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jamie Luner","avatar":""},{"name":"Kirsten Zien","avatar":""},{"name":"Sarah Grey","avatar":""},{"name":"Nels Lennarson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
