INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-tri', 'Tiên Tri', 'Prescient', 'null', 'https://phimimg.com/upload/vod/20231108-1/91ba0571c3ffa94be7798411a89f0515.jpg', '<p>Theodore Meridian là một nhà di truyền học bị ám ảnh bởi một khả năng khó hiểu khi nhìn thấy những cái chết sẽ xảy ra với đối tượng của mình trong vòng 24 giờ. Một lần, khi nhìn thấy cảnh một bệnh nhân bị giết, anh ta cảnh báo bệnh nhân để có thể tránh được một vụ nổ súng chết người. Nhưng Theodore phát hiện một sự thật kinh hoàng rằng vẫn còn một nạn nhân trong vụ nổ súng đó - người yêu của anh, Anna. Luôn sống trong mặc tội lỗi, thế giới Theodore đột nhiên thay đổi khi biết rằng Anna vẫn còn sống. Bây giờ, anh phải tìm hiểu làm thế nào minh nhận được sức mạnh trước đó và tìm hiểu xem có ai đó - hay cái gì đó đó - điều khiển mình.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Piccirilli","avatar":""},{"name":"Pamelyn Chee","avatar":""},{"name":"Anthony Bishop","avatar":""},{"name":"John Patrick Patti","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324452);
