INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-den-roi', 'Thám tử đến rồi', 'An Inspector Calls', 'https://phimimg.com/upload/vod/20231108-1/859bb72d100cde961460f8e68ea7cd79.jpg', 'https://phimimg.com/upload/vod/20231108-1/5bb0977c3021a61f441fcc2e5bc13a2f.jpg', '<p>Khi Thanh tra Karl tới biệt thự nhà họ Cầu trước lúc diễn ra tiệc đính hôn xa hoa, ông đã mang đến tin tức về vụ tự tử của người phụ nữ trẻ – và nhiều điều nghi vấn.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Zhang Han","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Karena Ng","avatar":""},{"name":"Liu Yan","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Dada Chan","avatar":""},{"name":"Annie Liu","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Emily Kwan Bo-Wai","avatar":""},{"name":"You-Nam Wong","avatar":""},{"name":"Elena Kong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
