INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-bo', 'Chối Bỏ', 'Forsaken', 'https://phimimg.com/upload/vod/20231108-1/d4da067a9f7496dbb810f73a06ce90dc.jpg', 'https://phimimg.com/upload/vod/20231108-1/a5ba73b566494166f9ed15e1c3219fc1.jpg', '<p>John Henry trở về quê hương với hy vọng hàn gắn mối quan hệ với người cha ghẻ lạnh của mình, nhưng một băng đảng địa phương đang khủng bố thị trấn. John Henry là người duy nhất có thể ngăn chặn chúng, tuy nhiên anh ta đã từ bỏ cả khẩu súng và danh tiếng là một kẻ giết người nhanh nhẹn không sợ hãi.</p>', 'Full', 1, 'single', 'completed', 21, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Demi Moore","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Siobhan Williams","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Landon Liboiron","avatar":""},{"name":"Greg Ellis","avatar":""},{"name":"Wesley Morgan","avatar":""},{"name":"Aaron Poole","avatar":""},{"name":"Dylan Smith","avatar":""},{"name":"Brock Morgan","avatar":""},{"name":"Graeme Black","avatar":""},{"name":"Tom Carey","avatar":""},{"name":"Chris Ippolito","avatar":""},{"name":"David McNally","avatar":""},{"name":"Ali Webb","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
