INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diet-vong', 'Diệt Vong', 'Extinction', 'https://phimimg.com/upload/vod/20231108-1/8cdfd4eec45832fd204a19ea1a403f80.jpg', 'https://phimimg.com/upload/vod/20231108-1/f4b1afab239b1c1f189ffc7e3721f7c1.jpg', '<p>Và đột nhiên, chỉ sau một đêm, thế giới dừng lại. Hai người đàn ông, hai người sống sót, một đứa trẻ và sự thù hận đã chia cắt họ. Một nơi bị lãng quên bởi tất cả mọi người, bao gồm cả những sinh vật sống trên Trái đất... cho đến tận bây giờ.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Fox","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Quinn McColgan","avatar":""},{"name":"Valeria Vereau","avatar":""},{"name":"Clara Lago","avatar":""},{"name":"Matt Devere","avatar":""},{"name":"Eduardo Fedriani","avatar":""},{"name":"Lili Bordán","avatar":""},{"name":"Alex Hafner","avatar":""},{"name":"Jeremy Wheeler","avatar":""},{"name":"Katharine Bubbear","avatar":""},{"name":"Julio Perillán","avatar":""},{"name":"Adam Zambryzcki","avatar":""},{"name":"Orsolya Bene","avatar":""},{"name":"Daniel Bargueño","avatar":""},{"name":"István Bán","avatar":""},{"name":"Emília Gresic","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324452);
