INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-bao-thu', 'Thiếu Nữ Báo Thù', 'Some Kind of Hate', 'https://phimimg.com/upload/vod/20231108-1/eb0190ce447da389eeb58671be6ec4e6.jpg', 'https://phimimg.com/upload/vod/20231108-1/4bf2b13e7bf2cb7602b23736a0a594cd.jpg', '<p>Phim kể về một cô gái đã chết quay về trả thù đám người xấu đã hãm hại cô. Những cái chết kinh hoàng, những màn tra tấn dã man sẽ khiến bạn phải thót tim và hồi hộp. Không dẫn dắt vòng vo, phim đánh trực diện vào chủ đề tư tưởng vì thế những cao trào dồn dập xảy ra.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ronen Rubinstein","avatar":""},{"name":"Sierra McCormick","avatar":""},{"name":"Gracie Gillam","avatar":""},{"name":"Lexi Atkins","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Noah Segan","avatar":""},{"name":"Michael Polish","avatar":""},{"name":"Maestro Harrell","avatar":""},{"name":"Andrew Bryniarski","avatar":""},{"name":"Brando Eaton","avatar":""},{"name":"Justin Prentice","avatar":""},{"name":"Jasper Polish","avatar":""},{"name":"Audrey Ellis Fox","avatar":""},{"name":"Eryn Rea","avatar":""},{"name":"Rachael Edlow","avatar":""},{"name":"Anthony Omari","avatar":""},{"name":"Britta","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324452);
