INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thieu-nu-bao-thu', 'Thiếu Nữ Báo Thù', 'Some Kind of Hate', 'thiếu nữ báo thù some kind of hate ronen rubinstein sierra mccormick gracie gillam lexi atkins spencer breslin noah segan michael polish maestro harrell andrew bryniarski brando eaton justin prentice jasper polish audrey ellis fox eryn rea rachael edlow anthony omari britta ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-thanh-xuan-khong-giu-lai-duoc', 'Nếu Thanh Xuân Không Giữ Lại Được', 'Youth Never Returns', 'https://phimimg.com/upload/vod/20231108-1/b83ab3762e5f7ffae5e73471ce1f6019.jpg', 'https://phimimg.com/upload/vod/20231108-1/9f4d7604464afcdef59f940a6fcbe340.jpg', '<p>Phim Nếu Thanh Xuân Không Giữ Lại Được (tên tiếng Anh: Youth Never Returns 2015) là bộ phim điện ảnh được chuyển thể từ tác phẩm mạng Khi Rau Chân Vịt Gặp Rau Muống của tác giả Cố Vĩ. Phim xoay quanh câu chuyện tình lãng mạn, nhẹ nhàng của “cô nàng dân quê” Châu Tuệ (Trần Kiều Ân) và “chàng ca sĩ tài năng” Vương Huy (Trương Hàn). Cả hai gặp nhau trong một buổi liên hoan lớp trên, sau khi vừa trải qua kỳ quân sự. Vương Huy đã hát ca khúc “Cô nương nơi trấn nhỏ” của Đào Triết khiến cô nhớ nhà da diết đến nỗi bật khóc. Từ lúc đó, Châu Tuệ bắt đầu có tình cảm với Vương Huy. Trong suốt hơn mười năm, kể từ thời điểm khi họ lần đầu gặp nhau tại đại học cho đến khi rời khỏi ghế nhà trường, bước vào xã hội, mối tình của họ đã trải qua vô vàn biến cố, họ cũng đã từng nghĩ đến chuyện chia tay… Liệu họ sẽ có một kết thúc viên mãn?</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Han","avatar":""},{"name":"Joe Chen","avatar":""},{"name":"Wang Xiaokun","avatar":""},{"name":"Shi Yufei","avatar":""},{"name":"Liao Juan","avatar":""},{"name":"Guo Zi Qian","avatar":""},{"name":"Hanchao Cao","avatar":""},{"name":"Shengqiang Jia","avatar":""},{"name":"Ni Jingyang","avatar":""},{"name":"Wang Xun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324452);
