INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-chim-vang', 'Chú Chim Vàng', 'Yellowbird', 'https://phimimg.com/upload/vod/20231108-1/cab4ba64c9282641444512381a5ab217.jpg', 'https://phimimg.com/upload/vod/20231108-1/92fb45350b8f42708f22fbeba79995cd.jpg', '<p>Chú Chim Vàng - Yellowbird: Câu chuyện lấy cảm hứng từ các chuyến bay di cư của hàng ngàn con chim nhạn qua Địa Trung Hải tới châu Phi để tránh mùa Đông đến sớm. Đây là một bản hùng ca về một nhân vật chẳng giống anh hùng chút nào vì trong hành trình đó, một chú chim mồ côi có tên Yellowbird buộc phải dẫn đầu đoàn di cư, vì tình cờ là con chim duy nhất biết đường.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Seth Green","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Ryan Lee","avatar":""},{"name":"Brady Corbet","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Yvette Nicole Brown","avatar":""},{"name":"Christopher Lee Parson","avatar":""},{"name":"Cristina Pucelli","avatar":""},{"name":"Jadon Sand","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Zachary Gordon","avatar":""},{"name":"Joey King","avatar":""},{"name":"Jamie Denbo","avatar":""},{"name":"Fr","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
