INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cap-con-gai', 'Kẻ Cắp Con Gái', 'Stolen Daughter', 'https://phimimg.com/upload/vod/20231108-1/2ef225ce16ae7f6e82487e53d8aaf876.jpg', 'https://phimimg.com/upload/vod/20231108-1/fd0d46701ab64500925fe56833961028.jpg', '<p>Kẻ Cắp Con Gái - Stolen Daughter kể về Stacey, một thanh tra cảnh sát phụ trách các vụ án bắt cóc trẻ em nhưng đang bị chấn thương tâm lý sau một vụ án. Sau khi Stacey trở lại làm việc, Sarah, con gái của cô bị bắt cóc. Với việc bị cản trở bởi một đồng nghiệp đang tìm kiếm vinh quang và gia đình lo lắng cho sức khỏe tâm thần của cô, liệu Stacey có thể làm được công việc của mình và giải cứu con gái mình khỏi một kẻ bắt cóc không ổn định về cảm xúc hay không?</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Andrea Roth","avatar":""},{"name":"Sarah Dugdale","avatar":""},{"name":"Rachel Hayward","avatar":""},{"name":"Steve Bacic","avatar":""},{"name":"Nicole Muñoz","avatar":""},{"name":"Matthew Kevin Anderson","avatar":""},{"name":"Sarah Deakins","avatar":""},{"name":"Keith MacKechnie","avatar":""},{"name":"Paul Anthony","avatar":""},{"name":"Crystal Balint","avatar":""},{"name":"Artine Brown","avatar":""},{"name":"Josh Byer","avatar":""},{"name":"Curtis Caravaggio","avatar":""},{"name":"Colby Chartrand","avatar":""},{"name":"Alex Draghicescu","avatar":""},{"name":"Erla Forsyth","avatar":""},{"name":"Gray","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324452);
