INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-mau-lua', 'Con Đường Máu Lửa', 'Hyena Road', 'https://phimimg.com/upload/vod/20231108-1/77aa38bdad3f23f5357d124f2429cff0.jpg', 'https://phimimg.com/upload/vod/20231108-1/609ee9ae74f2f2926255f631a10c56e5.jpg', '<p>Ba người lính, ba thế giới, ba cuộc chiến tranh khác nhau - tất cả đứng ở điểm giao nhau của cuộc chiến tranh hiện đại - thế giới tăm tối. Họ sẽ liên kết lại hay chống đối nhau để sống còn...</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Paul Gross","avatar":""},{"name":"Rossif Sutherland","avatar":""},{"name":"Clark Johnson","avatar":""},{"name":"Allan Hawco","avatar":""},{"name":"Christine Horne","avatar":""},{"name":"Jennifer Pudavick","avatar":""},{"name":"David Richmond-Peck","avatar":""},{"name":"Nikki Duval","avatar":""},{"name":"Karl Campbell","avatar":""},{"name":"Neamat Arghandabi","avatar":""},{"name":"Darren Wall","avatar":""},{"name":"Kelly Holden","avatar":""},{"name":"Sadeen Dagamseh","avatar":""},{"name":"Julia Issa Begain","avatar":""},{"name":"Hekmat Bavary","avatar":""},{"name":"Penny McDonald","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
