INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-do-dang', 'Lang Đồ Đằng', 'Wolf Totem', 'https://phimimg.com/upload/vod/20231107-1/f3d188aacd7aa2da4971df62dde11364.jpg', 'https://phimimg.com/upload/vod/20231107-1/7be192262cf5c14249c48a3d983d210f.jpg', '<p>Bộ phim khởi đầu với hình ảnh chàng sinh viên Trần Trận (Phùng Thiệu Phong đóng) tình nguyện rời Bắc Kinh đến vùng Ô Lôn Nội Mông để chăn cừu với dân du mục trong những năm đầu của cuộc cách mạng văn hóa Trung Hoa. Để rồi thay vì học chăn cừu, anh ta lại bị mê hoặc bởi những con sói hung dữ và thần bí của thảo nguyên. Trong một cảnh quay tuyệt đẹp với khung cảnh ôm trọn cả một vùng thảo nguyên rộng lớn và xanh ngắt của thảo nguyên Mông Cổ, Trần Trận và ông già du mục Tất Lợi Cách nói: “Cậu có từng nghĩ Thành Cát Tư Hãn chỉ với một binh lực nhỏ bé như vậy lại có thể đánh bại thiên binh vạn mã trên toàn thế giới được? Đó là từ bầy sói trước mặt cậu. Ông ta học được bí quyết đánh trận từ bầy sói. Sói rất thông minh, lại có khả năng tổ chức, đoàn kết nhất trí, lại biết nghe theo sự chỉ huy của con sói đầu đàn. Quan trọng nhất là sói có tính nhẫn nại rất cao. Cuộc sống phụ thuộc vào việc chớp thời cơ, sói và người Mông Cổ đều hiểu rõ đạo lý này&quot;.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"William Feng","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Ankhnyam Ragchaa","avatar":""},{"name":"Yin Zhusheng","avatar":""},{"name":"Baasanjav Mijid","avatar":""},{"name":"Tumenbayaer","avatar":""},{"name":"Han Tongsheng","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"Chanart","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
