INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-bao', 'Trai Bao', 'The Gigolo', 'https://phimimg.com/upload/vod/20231107-1/80967a2840d0eb3bb1a85d7033f93f31.jpg', 'https://phimimg.com/upload/vod/20231107-1/d8c6f06efabc0d0e80f2c902a7f1a3ec.jpg', '<p>Phim Trai Bao - The Gigolo (2015) kể về anh chàng mới lớn thật thà ngây ngô Jufeng, người có vẻ ngoài thu hút người khác phái. Cuộc đời nhiều điều thay đổi, khiến chàng trở thành một gã trai bao sành sỏi, để lọt vào mắt xanh của nữ đạo diễn phim trong phim. Đời trai bao nhìn thoáng qua thật hấp dẫn, nhưng đó là khi bạn còn sức khỏe, còn tỉnh táo, còn tràn đầy năng lượng, đặc biệt còn có thể gây hứng khởi cho người khác. Hãy cẩn thận khi những thứ đó mai một theo thời gian.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Dominic Ho","avatar":""},{"name":"Candy Yuen","avatar":""},{"name":"Jeana Ho Pui-Yu","avatar":""},{"name":"Hazel Tong","avatar":""},{"name":"Winnie Leung","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"Angelina Lo Yuen-Yan","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Ricky Yi Fan-Wai","avatar":""},{"name":"Fan Ling","avatar":""},{"name":"Ronan Pak","avatar":""},{"name":"Yu-Hong Wang","avatar":""},{"name":"DeeGor Ho","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324452);
