INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-doi-quai-vat-noi-loan', 'Người Dơi: Quái Vật Nổi Loạn', 'Batman Unlimited: Monster Mayhem', 'người dơi: quái vật nổi loạn batman unlimited: monster mayhem roger craig smith troy baker chris diamantopoulos kari wuhrer noel fisher khary payton will friedle yuri lowenthal fred tatasciore brian t. delaney dave b. mitchell richard epcar eric bauza alastair duncan amanda troop steve blum cedric ya ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cuong-duong', 'Anh Hùng Cương Dương', 'The Virgin Psychics', 'https://phimimg.com/upload/vod/20231114-1/09d27cd4834989548a47807034adc5d2.jpg', 'https://phimimg.com/upload/vod/20231114-1/bda256dc229df0b21c9aea1ee40dc197.jpg', '<p>Câu chuyện hài giả tưởng này kể về một nam sinh trung học (còn nguyên tem) bình thường tên là Yoshiro “Yocchan” Kamogawa (do Sometani thủ vai). Cuộc đời cậu đã thay đổi hoàn toàn sau một đêm, khi cậu thức dậy với khả năng đọc được suy nghĩ của người khác. Yoshiro không phải người duy nhất trong thị trấn có siêu năng lực. Teru-oichan (hẳn nhiên là vẫn chưa bị bóc mác), nhân viên của một tiệm cà phê gần trường Yoshiro, có được khả năng di chuyển đồ vật, nhưng anh chỉ toàn dùng để di chuyển sex toy. Yosuke Enomoto (chắc là vẫn còn tem), học sinh năm cuối và là cựu thành viên của đội bóng rổ, cùng trường Yoshiro, có được khả năng dịch chuyển tức thời, nhưng chỉ khi đang trong trạng thái không mảnh vải che thân.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shota Sometani","avatar":""},{"name":"Elaiza Ikeda","avatar":""},{"name":"Erina Mano","avatar":""},{"name":"Makita Sports","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Reiya Masaki","avatar":""},{"name":"Megumi Kagurazaka","avatar":""},{"name":"Ken Yasuda","avatar":""},{"name":"Maryjun Takahashi","avatar":""},{"name":"Ami Tomite","avatar":""},{"name":"Sahel Rosa","avatar":""},{"name":"Anna Konno","avatar":""},{"name":"Mizuki Hoshina","avatar":""},{"name":"Airi Shimizu","avatar":""},{"name":"Rika Hoshina","avatar":""},{"name":"Ai Shinozaki","avatar":""},{"name":"Mariko Tsutsui","avatar":""},{"name":"Ijirî Oka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324452);
