INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-co-bac', 'Tay Cờ Bạc', 'Mississippi Grind', 'https://phimimg.com/upload/vod/20231103-1/76093508c779f72f500b5e2eeaaedbe5.jpg', 'https://phimimg.com/upload/vod/20231103-1/6778276b59d03b1d7138561f24430d40.jpg', '<p>Dựa trên một phần trong cuốn sách California Spirit của Robert Altman, Mississippi Grind đã tái hiện lại một chuyến hành trình để khám phá &quot;chất Mỹ&quot; cũng như để lạc vào thế giới cờ bạc đầy tính toán. Bộ phim với sự thể hiện tuyệt vời của Ben Mendelsohn và Ryan Reynolds đầy hòa hợp đã đánh dấu một cột mốc quan trọng trong sự nghiệp của hai nam diễn viên tài năng, cũng như của cả hai đạo diễn Ryan Fleck và Anna Boden.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Mendelsohn","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"James Toback","avatar":""},{"name":"Robin Weigert","avatar":""},{"name":"Yvonne Landry","avatar":""},{"name":"Anthony Howard","avatar":""},{"name":"Jayson Warner Smith","avatar":""},{"name":"Kerry Cahill","avatar":""},{"name":"Jane McNeill","avatar":""},{"name":"Jason Shaffette","avatar":""},{"name":"P.J. Marshall","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"Teri Wyble","avatar":""},{"name":"Hunter Burk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
