INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pan-vung-dat-neverland', 'Pan & Vùng Đất Neverland', 'Pan', 'https://phimimg.com/upload/vod/20231106-1/78b62b1870779b99276e07eab6e34b82.jpg', 'https://phimimg.com/upload/vod/20231106-1/46a1ca8a4117130a13c5fe133712b638.jpg', '<p>Sống một cuộc sống ảm đạm tại một trại trẻ mồ côi ở London, cậu bé Peter 12 tuổi thấy mình bị cuốn vào thế giới kỳ ảo của Neverland. Cuộc phiêu lưu đang chờ đợi khi anh gặp người bạn mới James Hook và chiến binh Tiger Lily. Họ phải liên kết với nhau để cứu Neverland khỏi tên cướp biển tàn nhẫn Râu Đen. Trên đường đi, cậu bé nổi loạn và nghịch ngợm khám phá ra định mệnh thực sự của mình, trở thành anh hùng mãi mãi được biết đến với cái tên Peter Pan.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Levi Miller","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Kathy Burke","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"Paul Kaye","avatar":""},{"name":"Emerald Fennell","avatar":""},{"name":"Lewis MacDougall","avatar":""},{"name":"Tae-joo Na","avatar":""},{"name":"Jack Charles","avatar":""},{"name":"Bronson Webb","avatar":""},{"name":"Kurt Egyiawan","avatar":""},{"name":"Jack Lowden","avatar":""},{"name":"Jimmy Vee","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324452);
