INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-khong-the-tin-noi', 'Anh "Không thể tin nổi"', 'Mr. Unbelievable', 'https://phimimg.com/upload/vod/20231106-1/f5d319a6e3ac40bb1258983ae0a70f9e.jpg', 'https://phimimg.com/upload/vod/20231106-1/3ffc0cef7ab414f7bca20c33a09d8458.jpg', '<p>Trong phim ăn theo video âm nhạc đình đám của Trần Thiên Văn, một ca sĩ getai trung niên nỗ lực thành sao bằng cách thêm lời tiếng Anh vào bài hát tiếng Phúc Kiến.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'Singapore', 0, '[{"name":"Chen Tian Wen","avatar":""},{"name":"Genghis Chai","avatar":""},{"name":"Marcus Chin","avatar":""},{"name":"Jaime Teo","avatar":""},{"name":"Li Feihui","avatar":""},{"name":"Tosh Zhang","avatar":""},{"name":"Liu Ling Ling","avatar":""},{"name":"Zhang Wenxiang","avatar":""},{"name":"Chua Jin Sen","avatar":""},{"name":"Gadrick Chin","avatar":""},{"name":"Hayley Woo","avatar":""},{"name":"Zhang Wei","avatar":""},{"name":"Jim Lim","avatar":""},{"name":"Daren Tan","avatar":""},{"name":"Hong Huifang","avatar":""},{"name":"Ezann Lee","avatar":""},{"name":"Silver Ang","avatar":""},{"name":"Fauzie Laily","avatar":""},{"name":"Kelvin Mun","avatar":""},{"name":"Alaric Tay","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324452);
