INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-trong-sau-tham', 'Từ Trong Sâu Thẳm', 'Northern Borders', 'https://phimimg.com/upload/vod/20231106-1/bfa9911bfd6463e3465de7c19cad3ea4.jpg', 'https://phimimg.com/upload/vod/20231106-1/1ea2941cb93bd13ffa6b7b90504b617c.jpg', '<p>Bộ phim xoay quanh cuộc sống của Austin. Khi anh được gửi đến sống tại trang trại Vermont của ông bà, Austin đã khám phá ra những bí mật gia đình được giấu kín bấy lâu nay. Mắc kẹt trong các rắc rối của gia đình bên nội, Austin vô hình chung trở thành người ở giữa trong những vấn đề phiền toái.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Dern","avatar":""},{"name":"Geneviève Bujold","avatar":""},{"name":"Seamus Davey-Fitzpatrick","avatar":""},{"name":"Tom Bodett","avatar":""},{"name":"Jim Fitzpatrick","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Jacqueline Hennessy","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"John Rothman","avatar":""},{"name":"Alicia Hunt","avatar":""},{"name":"Jay O. Sanders","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324452);
