INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-goi-tu-than', 'Tiếng Gọi Tử Thần', 'Angel Whispers', 'https://phimimg.com/upload/vod/20231103-1/25ec226d33556711c2f9eee30a69298f.jpg', 'https://phimimg.com/upload/vod/20231103-1/a635c07fe9eb73ae54afc80919d81e25.jpg', '<p>Phim Tiếng Gọi Tử Thần - Angel Whispers 2015: xoay quanh sự mất tích bí ẩn của hàng loạt cô gái bán dâm trong một chung cư Hong Kong. Li phát hiện ra sự mất tích của Ping và cô bắt đầu tìm kiếm những cô gái khác. Tòa nhà bị cô lập với bên ngoài và vụ thảm sát bắt đầu. Li và các gái mại dâm khác phải tìm Ping và chiến đấu một trận chiến của trí thông minh với những kẻ giết người vô hình.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Carrie Ng","avatar":""},{"name":"Kabby Hui","avatar":""},{"name":"Sammy Hung","avatar":""},{"name":"A Lin","avatar":""},{"name":"Foo Hiu-Mei","avatar":""},{"name":"Chan Pang-Chun","avatar":""},{"name":"Roydon Chio","avatar":""},{"name":"Ricky Ko","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324452);
