INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-tam-hon', 'Vẻ Đẹp Tâm Hồn', 'The Beauty Inside', 'https://phimimg.com/upload/vod/20231103-1/d611404c664e773b02dff0b7524cc5df.jpg', 'https://phimimg.com/upload/vod/20231103-1/886fe930add6b5f9a07ca278ff12f92e.jpg', '<p>Phim Vẻ Đẹp Tâm Hồn The Beauty Inside là phiên bản remake của phim điện ảnh năm 2015 cùng tên của Hàn Quốc. Bộ phim xoay quanh Han Se Kye (Seo Hyun Jin), một nữ diễn viên nổi tiếng nhưng cũng là trung tâm của những tin đồn thất thiệt. Trên thực tế, Han Se Kye bị mắc một hội chứng kì lạ. Vào một thời điểm nào đó trong tháng, ngoại hình của cô sẽ thay đổi và biến thành người khác. Cô sẽ phải sống trong cơ thể này suốt một tuần mỗi tháng. &nbsp;Một ngày nọ, Han Se Kye gặp được Seo Do Jae (Lee Min Ki), thành viên ban quản trị của một hãng hàng không. Thông minh, đẹp trai, Seo Do Jae trong mắt nhiều người là một soái ca hoàn hảo. Thế nhưng ít ai biết anh lại mắc chứng mù mặt người. Không thể phân biệt gương mặt người khác, Seo Do Jae cố gắng che giấu khiếm khuyết của mình bằng cách cố gắng ghi nhớ mọi người thông qua thói quen và hành động của họ. Người duy nhất mà anh có thể nhận diện được gương mặt chính là Han Se Kye. Cuộc gặp với nữ diễn viên xinh đẹp đã làm thay đổi cuộc đời anh.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Hyo-joo","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Do Ji-han","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Park Shin-hye","avatar":""},{"name":"Lee Beom-su","avatar":""},{"name":"Park Seo-jun","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Juri Ueno","avatar":""},{"name":"Lee Jae-joon","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Lee Jin-wook","avatar":""},{"name":"Seo Kang-joon","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Lee Dong-wook","avatar":""},{"name":"Ko A-sung","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324452);
