INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-than-luc-thuc-tinh', 'Star Wars: Thần Lực Thức Tỉnh', 'Star Wars: The Force Awakens', 'https://phimimg.com/upload/vod/20231103-1/18bf75195abc0e7e1e2135cb89707241.jpg', 'https://phimimg.com/upload/vod/20231103-1/a217bc2da6ad14ea9d5c69e333715c5d.jpg', '<p>“Chiến tranh giữa các vì sao: Thần lực thức tỉnh” tiếp tục cho câu chuyện của 30 năm sau khi đánh bại Darth Vader và Empire. Cô nàng Rey – một người nhặt rác từ hành tinh Jakku- tìm thấy một droid BB-8, cô giữ BB-8 như thể nó là của mình. Rey vô tình phát hiện ra cỗ máy cất giữ bản đồ nơi ở của Luke Skywalker – chiến binh cuối cùng đã mất tích từ lâu. &nbsp;Finn – một stormtrooper FN-2187 may mắn sống sót sau một cuộc tấn công- đã đến gặp Rey và BB-8 với ý định giúp đỡ họ. Tuy nhiên, ba người bị tấn công bất ngờ bởi Tổ chức thứ nhất, buộc phải chạy trốn khỏi hành tinh bằng một chiếc phi đang đậu gần đó. Họ không hay biết chiếc phi thuyền mà mình đang sử dụng có ý nghĩa vô cùng đặc biệt. Đương nhiên họ cũng không hoàn toàn hay biết, có một người anh hùng đang ở trong bóng tối hỗ trợ họ.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Carrie Fisher","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Daisy Ridley","avatar":""},{"name":"John Boyega","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Lupita Nyong''o","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Peter Mayhew","avatar":""},{"name":"Gwendoline Christie","avatar":""},{"name":"Joonas Suotamo","avatar":""},{"name":"Pip Andersen","avatar":""},{"name":"Simon Pegg","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324452);
