INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-dan-vien-tinh-yeu', 'Hướng Dẫn Viên Tình Yêu', 'Love Guide for Dumpees', 'https://phimimg.com/upload/vod/20231103-1/0c655f819c4013e1b008d64b24bd3dcd.jpg', 'https://phimimg.com/upload/vod/20231103-1/c973a0ab333f890972f24fa509a9c3d5.jpg', '<p>Về một người đàn ông và một người phụ nữ làm sổ phiếu giảm giá &#39;tình một đêm&#39; sau khi cả hai đều bị bán phá giá.</p>', 'Full', 1, 'single', 'completed', 16, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoon Kye-sang","avatar":""},{"name":"Han Yeri","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Jung Su-young","avatar":""},{"name":"Jo Bok-rae","avatar":""},{"name":"Kim Chang-hwan","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Han Ji-eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
