INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-long-san-moi', 'Khủng Long Săn Mồi', 'Jurassic Prey', 'https://phimimg.com/upload/vod/20231103-1/ed16574c4beefda85bf7d5ef6f20fb57.jpg', 'https://phimimg.com/upload/vod/20231103-1/1c003ed11c0edc9079d8b342a4bea433.jpg', '<p>Một người phụ nữ ăn cắp tiền của ông trùm băng đảng với hy vọng bắt đầu một cuộc sống mới với người tình của mình. Trong khi đó, một cựu ngôi sao nhí đã rửa sạch và những người bạn của anh ta cướp một ngân hàng với một thám tử cảnh sát đang truy lùng họ. Thông qua sự xoay vần của số phận, tất cả những người này thấy mình đang ở trong một căn nhà gỗ hẻo lánh, không biết rằng công việc xây dựng gần đây đã giải phóng một sinh vật hung dữ hiện đang lang thang khắp khu vực xung quanh! Ai sẽ sống sót trong MEATEATERS!</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Donahue","avatar":""},{"name":"Jeff Kirkendall","avatar":""},{"name":"Bob Dennis","avatar":""},{"name":"James Carolus","avatar":""},{"name":"Steve Diasparra","avatar":""},{"name":"Ken Van Sant","avatar":""},{"name":"Todd Carpenter","avatar":""},{"name":"Kelsey Kaufmann","avatar":""},{"name":"Houston Baker","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324453);
