INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trach-nu-trinh-tham-que-huong', 'Trạch Nữ Trinh Thám Quế Hương', 'Detective Gui', 'https://phimimg.com/upload/vod/20231103-1/69f7f048ab6804cf97e87ff9a939b6c9.jpg', 'https://phimimg.com/upload/vod/20231103-1/059916fb56e3133b2a984182291fb4a0.jpg', '<p>Bộ phim Trạch Nữ Trinh Thám Quế Hương - Detective Gui kể về cô nàng trạch nữ có tài năng trinh thám thiên bẩm nhưng lại không giỏi giao tiếp với người khác. Một ngày nọ, cô phát hiện ra vụ án mạng của hàng xóm, sự tò mò đã thôi thúc cô đi điều tra nhưng sự thật lại khiến cô ngỡ ngàng.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Luodan","avatar":""},{"name":"Vic Chou","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Maggie Shiu","avatar":""},{"name":"Shek Sau","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
