INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-doi-tranh-quy', 'Cuộc Chiến Đòi Tranh Quý', 'Woman In Gold', 'https://phimimg.com/upload/vod/20231103-1/b6e35ceeefdb11f7529c9bc915728825.jpg', 'https://phimimg.com/upload/vod/20231103-1/dca147c52c6b2d07111a115fe24b0f44.jpg', '<p>Cuộc Chiến Đòi Tranh Quý - Woman In Gold kể lại hành trình Maria Altmann - một nạn nhân Do Thái còn sống sót sau Thế Chiến II và một chàng luật sư trẻ nhiệt huyết cùng nhau thực hiện một cuộc chiến pháp lý dai dẳng với chính quyền nước Áo để đòi lại những bức tranh quý, trong đó có bức Portrait of Adele Bloch-Bauer I, thời điểm đó đang trưng bày trong Bảo tàng Belvedere với tên gọi Woman in gold, được xem là “Mona Lisa của nước Áo” và được nước này coi là “báu vật quốc gia”.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Tatiana Maslany","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Max Irons","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Tom Schilling","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Antje Traue","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Moritz Bleibtreu","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Henry Goodman","avatar":""},{"name":"Olivia Silhavy","avatar":""},{"name":"Ben Miles","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
