INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-o-yeonpyeon', 'Cuộc Chiến Ở Yeonpyeon', 'Northern Limit Line', 'https://phimimg.com/upload/vod/20231103-1/cab16c07c29f77af2ca8069968d7ca8f.jpg', 'https://phimimg.com/upload/vod/20231103-1/56906a7f4b220b2bda63381f2c4160a7.jpg', '<p>Northern Limit Line (Cuộc Chiến Ở Yeonpyeong) dựa trên câu chuyện có thật xảy ra ở Yeonpyeong-do, đây là câu chuyện của những người lính trẻ, những người đã cho thấy sự can đảm và trách nhiệm đối với đất nước của họ...</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Moo-yul","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Lee Chung-ah","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Lee Wan","avatar":""},{"name":"Kwon Hwa-woon","avatar":""},{"name":"Kim Dong-hee","avatar":""},{"name":"Kim Ha-kyoon","avatar":""},{"name":"Jang Eui-soo","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324453);
