INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-gioi-han', 'Vượt Qua Giới Hạn', 'Beyond Paradise', 'https://phimimg.com/upload/vod/20231103-1/2bb7ce3fa136467494b522b6cd54b77b.jpg', 'https://phimimg.com/upload/vod/20231103-1/1bd404f774e04bfb1d6a0025ecd31f13.jpg', '<p>Bị ám ảnh bởi quá khứ bi thảm, Shahrzad chạy trốn quê hương và kết thúc bằng một cuộc hôn nhân xa lạ ở Los Angeles, không lâu sau mối quan hệ ngoài luồng, vụng trộm với anh chàng điển trai hàng xóm đã đẩy mọi việc vượt quá giới hạn, người chồng dần phát hiện ra sự phản bội, và người tình thì muốn phá hủy mọi thứ để có được cô.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Guzman","avatar":""},{"name":"Spencer Grammer","avatar":""},{"name":"Daphne Zuniga","avatar":""},{"name":"Francia Raísa","avatar":""},{"name":"Rome Shadanloo","avatar":""},{"name":"Christopher Maleki","avatar":""},{"name":"Max Amini","avatar":""},{"name":"Mel Fair","avatar":""},{"name":"Yareli Arizmendi","avatar":""},{"name":"Ali Olomi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
