INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-pha-lang-2-giet-khong-tha', 'Sát Phá Lang 2: Giết Không Tha', 'SPL 2: A Time for Consequences', 'https://phimimg.com/upload/vod/20231111-1/19d4f9d6d196183cbb3ff15b1eb44f3b.jpg', 'https://phimimg.com/upload/vod/20231111-1/f7e36ea88772317ef898b849e2bfc646.jpg', '<p>Sát Phá Lang 2 xoay quanh cuộc hành trình giải thoát cho cô con gái nhỏ của một nhân viên cai ngục người Thái, vì chỉ có một mình đơn độc không thể nào chống lại được thế lực bóng tối nên anh phải nhờ vào sự giúp đỡ của một người đồng nghiệp, đó là một cảnh sát chìm.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Zhang Jin","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Jun Kung","avatar":""},{"name":"Ka Wah Lam","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Ai Wai","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Candy Yuen","avatar":""},{"name":"Unda Kunteera Yhordchanng","avatar":""},{"name":"Andrew Ng","avatar":""},{"name":"Eddie Pang","avatar":""},{"name":"Law Wing-Cheong","avatar":""},{"name":"Fanny Lee Man-Fan","avatar":""},{"name":"Zhang Chi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
