INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nguyen-bong-toi-', 'Kỷ Nguyên Bóng Tối', 'Mythica: The Darkspore', 'https://phimimg.com/upload/vod/20231103-1/28ff1aeaa4b378eb1e570095e15b63f5.jpg', 'https://phimimg.com/upload/vod/20231103-1/d2b3609630d4bc604c9ac8fc956264e3.jpg', '<p>Chiến đấu qua những vùng đất đầy sinh vật và bị truy đuổi bởi những kẻ săn tiền thưởng, Marek và đồng đội của cô đang chạy đua để thu hồi tất cả những mảnh vỡ của Darkspore trước khi nó rơi vào tay một phù thủy độc ác.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melanie Stone","avatar":""},{"name":"Kevin Sorbo","avatar":""},{"name":"Adam Johnson","avatar":""},{"name":"Jake Stormoen","avatar":""},{"name":"Rocky Myers","avatar":""},{"name":"Matthew Mercer","avatar":""},{"name":"Kynan Griffin","avatar":""},{"name":"Nicola Posener","avatar":""},{"name":"Christopher Robin Miller","avatar":""},{"name":"Natalie Devine Riskas","avatar":""},{"name":"Robert Jayne","avatar":""},{"name":"Clare Niederpruem","avatar":""},{"name":"Crystal Harris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324453);
