INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-tra-thu', 'Xác Chết Trả Thù', 'The Corpse Of Anna Fritz', 'https://phimimg.com/upload/vod/20231103-1/a1a06b682eaabe74c3b2921a59fd9e37.jpg', 'https://phimimg.com/upload/vod/20231103-1/05a05ea696412695673d6834b223b843.jpg', '<p>Nữ diễn viên nổi tiếng Anna Fritz đột ngột qua đời. Khi xác cô được đưa đến nhà xác của một bệnh viện, nhân viên trực đêm Paul lúc này đã quyết định vén tấm khăn trắng mỏng manh ra để nhìn ngắm cơ thể tuyệt mỹ của người đẹp . Do chiều lòng hai người bạn là Javi và Ivan, anh đã mở cửa cho họ cùng vào xem với mình. Không cưỡng nổi ham muốn thể xác, Ivan đã đề nghị rằng cả ba hãy thay phiên nhau làm tình với xác của Anna Fritz, trước khi nó bị chuyển đi vào ngày mai. Chuỗi đau khổ không thể lường trước được đang chờ đợi họ phía trước...</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Alba Ribas","avatar":""},{"name":"Cristian Valencia","avatar":""},{"name":"Bernat Saumell","avatar":""},{"name":"Albert Carbó","avatar":""},{"name":"Henry Morales","avatar":""},{"name":"Daniel Aser","avatar":""},{"name":"Belén Fabra","avatar":""},{"name":"Montserrat Miralles","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
