INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-mat-tri-nho', 'Đánh Mất Trí Nhớ', 'Amnesiac', 'https://phimimg.com/upload/vod/20231103-1/45c27f6c3fc278f30dcd0936c37283f6.jpg', 'https://phimimg.com/upload/vod/20231103-1/14b7edd13e61a77a809fa06d1b9c0d41.jpg', '<p>Câu chuyện về một người đàn ông tỉnh dậy trên giường và bị mất trí nhớ sau một tai nạn, chỉ để bắt đầu nghi ngờ rằng vợ mình có thể không phải là vợ thực sự của mình và một mạng lưới dối trá và lừa dối ngày càng sâu trong ngôi nhà nơi anh sớm tìm thấy mình là một tù nhân.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Bosworth","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Shashawnee Hall","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Patrick Bauchau","avatar":""},{"name":"Olivia Rose Keegan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324453);
