INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-mon-qua-giang-sinh', '12 Món Quà Giáng Sinh', '12 Gifts of Christmas', 'https://phimimg.com/upload/vod/20231103-1/f7211b90be43c9fa0a164ddf7d6f0032.jpg', 'https://phimimg.com/upload/vod/20231103-1/cdd3e5e234dd27a62348ea9676562733.jpg', '<p>Món Quà Giáng Sinh - 12 Gifts of Christmas xoay quanh cuộc sống của Anna, một họa sĩ thất nghiệp, không thể trang trải cuộc sống. Một ngày, cô được thuê để trở thành người mua sắm Giáng sinh cá nhân cho Marc, một giám đốc điều hành công ty khó tính. Sau thời gian làm việc cùng nhau, hóa ra món quà giáng sinh tốt nhất chính là tình yêu mà họ dành cho nhau.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katrina Law","avatar":""},{"name":"Aaron O''Connell","avatar":""},{"name":"Donna Mills","avatar":""},{"name":"Melanie Nelson","avatar":""},{"name":"Alesandra Durham","avatar":""},{"name":"Jill Adler","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
