INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-cua-lo-lem', 'Âm mưu của Lọ Lem', 'Perfect Proposal', 'https://phimimg.com/upload/vod/20231110-1/8576cdbc3e7ca1dcafc18ac014bb5ace.jpg', 'https://phimimg.com/upload/vod/20231110-1/59dea12ffb520f662a4b92fed7f9430c.jpg', '<p>Khi đang điều hành một công ty du lịch ở Ma Cao, Ji-yeon bị đối tác kinh doanh của mình lừa gạt. Một ngày nọ, Sung-yeol hấp dẫn và nhân từ đưa ra cho cô một lời đề nghị không thể cưỡng lại: mức lương 5.000 USD hàng tháng để sống trên một chiếc du thuyền sang trọng và trở thành trợ lý chăm sóc cá nhân cho chủ sở hữu Cenado, một công ty vận chuyển và điều hành sòng bạc nổi tiếng. Không còn lựa chọn nào khác để dựa vào, cô tuân theo và chăm sóc cho người đàn ông ốm yếu, người không thể đối phó được. Ji-yeon dần dần thu hút được sự chú ý của cả Sung-yeol và ông trùm, đồng thời lưỡng lự giữa cơ hội đảm bảo cho tương lai và tình yêu của cô. Khi căng thẳng gia tăng giữa những nhân vật trên du thuyền, không ai có thể đoán trước được kết quả của nó.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lim Soo-jung","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Min Do-hee","avatar":""},{"name":"Kwak Min-ho","avatar":""},{"name":"Lee Yang-hee","avatar":""},{"name":"Jo Yoon-woo","avatar":""},{"name":"Jeon So-nee","avatar":""},{"name":"Enes Kaya","avatar":""},{"name":"Jeon Jin-oh","avatar":""},{"name":"Kim In-gwon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f585