INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-quai-vat-cua-rlstine-can-phong-linh-hon', 'Thị trấn quái vật của R.L.Stine: Căn phòng linh hồn', 'R.L. Stine''s Monsterville: The Cabinet of Souls', 'https://phimimg.com/upload/vod/20231102-1/cec70e2ecfc2dc9375766ee527028dd2.jpg', 'https://phimimg.com/upload/vod/20231102-1/413165a7502e9f625baa1302080bcbd4.jpg', '<p>Khi chương trình biểu diễn kinh dị lưu động ghé đến thị trấn, các học sinh trung học ở Danville háo hức vô cùng. Nhưng ông bầu nham hiểm lại ấp ủ một âm mưu xấu xa.</p>', 'Full', 1, 'single', 'completed', 24, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dove Cameron","avatar":""},{"name":"Braeden Lemasters","avatar":""},{"name":"Katherine McNamara","avatar":""},{"name":"Ryan McCartan","avatar":""},{"name":"Laine MacNeil","avatar":""},{"name":"Tiffany Espensen","avatar":""},{"name":"Casey Dubois","avatar":""},{"name":"Andrew Kavadas","avatar":""},{"name":"Keith MacKechnie","avatar":""},{"name":"Karin Konoval","avatar":""},{"name":"Fiona Vroom","avatar":""},{"name":"Jacob Desormeaux","avatar":""},{"name":"Carey Feehan","avatar":""},{"name":"Kelly-Ruth Mercier","avatar":""},{"name":"Sean Tyson","avatar":""},{"name":"Connor Stanhop","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324453);
