INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-dang-do', 'Bản Tình Ca Dang Dở', 'Broken: A Musical', 'null', 'https://phimimg.com/upload/vod/20231102-1/4e7e2d314683f6297681d606ef12f64c.jpg', '<p>Mona trở lại thành phố để làm mới cuộc sống của mình với người bạn thân nhất của cô là Helen sau cái chết của bà cô. Mona miễn cưỡng tham dự một bữa tiệc thịnh soạn với Helen, mặc dù người yêu cũ của cô, Jason, sẽ ở đó, nơi cô gặp Dirk quyến rũ, người đã thay đổi cuộc đời cô.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Rose","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"Ashley Argota","avatar":""},{"name":"Austin Michael","avatar":""},{"name":"Jason Tobias","avatar":""},{"name":"Jason Caceres","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324453);
