INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-chuc-bong-dem-uncle', 'Tổ Chức Bóng Đêm U.N.C.L.E.', 'The Man from U.N.C.L.E.', 'https://phimimg.com/upload/vod/20231101-1/8fe43a8fe4a4723fe644cf541aacec84.jpg', 'https://phimimg.com/upload/vod/20231101-1/5e5a424d2905ae4b037ae780951a21a7.jpg', '<p>The Man from U.N.C.L.E. là bộ phim Hành động được chuyển thể từ bộ phim truyền hình ăn khách những thập niên 60 của đạo diễn Guy Ritchie. Phim kể về Napoleon Solo, một điệp viên của CIA được bí mật giao nhiệm vụ hợp tác cùng Illya Kuryakin của KGB để điều tra về một tổ chức tội phạm với âm mưu phá hoại hòa bình trong thời gian chiến tranh lạnh của thập niên 60 này.</p>', 'Full', 1, 'single', 'completed', 21, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Henry Cavill","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Luca Calvani","avatar":""},{"name":"Sylvester Groth","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Christian Berkel","avatar":""},{"name":"Misha Kuznetsov","avatar":""},{"name":"Guy Williams","avatar":""},{"name":"Marianna Di Martino","avatar":""},{"name":"Julian Michael Deuster","avatar":""},{"name":"Andrea Cagliesi","avatar":""},{"name":"Riccardo Calvanese","avatar":""},{"name":"Pet","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324453);
