INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-trong-tuyet', 'Thiên Thần Trong Tuyết', 'Angels in the Snow', 'https://phimimg.com/upload/vod/20231109-1/ead14e5524e61bc792c82443d179e468.jpg', 'https://phimimg.com/upload/vod/20231109-1/2e01b829f5ad7a2c91087d63a4e467e8.jpg', '<p>Trong Angels in the Snow, gia đình Montgomery giàu có nhưng đầy rắc rối lên đường đón Giáng sinh đặc biệt trên núi.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristy Swanson","avatar":""},{"name":"Chris Potter","avatar":""},{"name":"Carolyn Adair","avatar":""},{"name":"Lizzie Boys","avatar":""},{"name":"Colin Lawrence","avatar":""},{"name":"Catherine Lough Haggquist","avatar":""},{"name":"Jaeda Lily Miller","avatar":""},{"name":"Nick Purcha","avatar":""},{"name":"Alexandra Siouras","avatar":""},{"name":"Kolton Stewart","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324453);
