INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-toc-san-tranh', 'Quý Tộc Săn Tranh', 'Mortdecai', 'https://phimimg.com/upload/vod/20231101-1/5736c96def7f7a8b2b3f511ce2e72124.jpg', 'https://phimimg.com/upload/vod/20231101-1/5eed6b0ffb451acc77acb96164181f56.jpg', '<p>Quý Tộc Săn Tranh - Mortdecai: là bộ phim hài hành động Mỹ 2015 của đạo diễn David Koepp. Nam diễn viên chính trong phim là Johny Deep. Bối cảnh phim là khi Mortdecai bị đẩy tới bờ vực…phá sản và không còn cách nào khác là chấp nhận dấn thân vào một phi vụ nguy hiểm: đem về một tuyệt tác hội họa bị đánh cắp từ lâu, mà khi lần theo manh mối cuối cùng của nó, Mortdecai được dẫn đến một tài khoản ngân hàng bí ẩn được đồn đoán là chứa hàng tấn vàng của Đức Quốc Xã. Mortdecai phải tiến hành một cuộc phiêu lưu sang nước Mỹ, nơi anh gặp gỡ nhiều nhân vật kì lạ dính líu đến bức tranh, một trong số đó là cô gái xinh đẹp bốc lửa (Olivia Munn) khiến cô vợ Johanna không khỏi lo lắng nhíu mày...</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Jonny Pasvolsky","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"Alec Utgoff","avatar":""},{"name":"Guy Burnet","avatar":""},{"name":"Paul Whitehouse","avatar":""},{"name":"Norma Atallah","avatar":""},{"name":"Nicholas Farrell","avatar":""},{"name":"Karl Theobald","avatar":""},{"name":"Michael Byrne","avatar":""},{"name":"James Joyce","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324453);
