INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-nhom-cua-top-cat', 'Băng Nhóm Của Top Cat', 'Top Cat Begins', 'https://phimimg.com/upload/vod/20231101-1/0ef7e22c64edc96d9359c1bed31373fe.jpg', 'https://phimimg.com/upload/vod/20231101-1/ef2aa6840fe475a5e725a4ff759118b6.jpg', '<p>Top Cat đã tìm được cách quyến rũ trái tim của các bạn! Bạn đã bao giờ tự hỏi cội nguồn của chú mèo này? Top Cat Begins sẽ tiết lộ nguồn gốc của tất cả những điều bạn biết về vị anh hùng hài hước này. Cuộc phiêu lưu tiếp theo điên rồ đến nỗi bạn phải tận mắt chứng chiến mới có thể tin.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2015, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Jason Harris","avatar":""},{"name":"David Hoffman","avatar":""},{"name":"Bill Lobley","avatar":""},{"name":"Darin De Paul","avatar":""},{"name":"Marieve Herington","avatar":""},{"name":"David Boat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324453);
