INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-muon', 'Kẻ Giết Mướn', 'Mercenary: Absolution', 'https://phimimg.com/upload/vod/20231101-1/a103f1992ff948d8698d1613b740a74b.jpg', 'https://phimimg.com/upload/vod/20231101-1/05eeb7bdb19285f5dd07d79a979a677b.jpg', '<p>Kẻ Giết Mướn - Mercenary: Absolution kể về kẻ giết người theo hợp đồng John Alexander. Một ngày, anh ta tình cờ có cơ hội cứu một cô gái vô tội khỏi tên trùm băng đảng quyền lực. Nhưng giải cứu và bảo vệ cô ấy đồng nghĩa với việc phản bội tổ chức đã trả tiền và tự đặt mạng sống của mình vào nguy hiểm. Anh ta sẽ lựa chọn như thế nào đây?</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Josh Barnett","avatar":""},{"name":"Adina Stetcu","avatar":""},{"name":"Massimo Dobrović","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Sabina Brândușe","avatar":""},{"name":"George Remes","avatar":""},{"name":"Cosmin Dominte","avatar":""},{"name":"Lesley-Anne Down","avatar":""},{"name":"Lauro Chartrand","avatar":""},{"name":"Sergiu Costache","avatar":""},{"name":"Maria Bata","avatar":""},{"name":"Lavinia Geambasu","avatar":""},{"name":"Claudiu Bleonţ","avatar":""},{"name":"Howard Dell","avatar":""},{"name":"Adina Galu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324453);
