INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-boc-ma-bo-phim-moi', 'Vỏ Bọc Ma: Bộ Phim Mới', 'Ghost in the Shell: The New Movie', 'vỏ bọc ma: bộ phim mới ghost in the shell: the new movie maaya sakamoto kenichirou matsuda kazuya nakai ikkyu juku kenji nojima mayumi asano megumi han miyuki sawashiro mugihito shunsuke sakuya takurou nakakuni tarusuke shingaki yoji ueda atsushi miyauchi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('4got10', '4Got10', '4Got10', 'https://phimimg.com/upload/vod/20231101-1/002c8a6e53e8837d0dc630b548827643.jpg', 'https://phimimg.com/upload/vod/20231101-1/657659ba92dcba43252afc59aa91815a.jpg', '<p>Brian Barnes (Johnny Messner) tỉnh dậy trong sa mạc bị thương, không còn ký ức và không biết tại sao xung quanh anh ta là tám thi thể, một chiếc xe tải với bốn triệu tiền mặt và một chiếc xe tải đầy cocaine. Brian bị truy đuổi không chỉ bởi trùm ma túy khét tiếng Danny Perez (Danny Trejo), người rất muốn lấy lại tiền của anh ta, và Đặc vụ DEA Rooker (Dolph Lundgren), mà còn bởi Cảnh sát trưởng tham nhũng Olson (Michael Pare), người sẽ không dừng lại để có được bàn tay của mình trên tài sản mới được tìm thấy. Trên đường chạy trốn, Brian phát hiện ra rằng càng nhớ nhiều thì anh càng ít muốn biết mình thực sự là ai.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Stefania Spampinato","avatar":""},{"name":"Erin O''Brien","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"John Laughlin","avatar":""},{"name":"Angell Conwell","avatar":""},{"name":"Jonathan Patrick Foo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
