INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-vuot-nguc-2', 'Hành Trình Vượt Ngục 2', 'The Condemned 2', 'https://phimimg.com/upload/vod/20231101-1/d99989fa39af8af09aaf5ea8f8e75b70.jpg', 'https://phimimg.com/upload/vod/20231101-1/0e2297d3a433cb1beebd776745b7168a.jpg', '<p>Phim The Condemned 2 (Hành Trình Vượt Ngục 2) là tiếp tục phần 1 lần này là câu chuyện kể về một tay săn tiền thưởng nhận ra đã bị ép lao vào một cuộc chơi mà ở đó các người chơi phải chiến đấu với nhau tới chết và các trận đấu được trực tiếp ra ngoài cho người xem,.....</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Randy Orton","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Steven Michael Quezada","avatar":""},{"name":"Monique Candelaria","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"Alex Knight","avatar":""},{"name":"Stafford Douglas","avatar":""},{"name":"Martin Palmer","avatar":""},{"name":"Michael Sheets","avatar":""},{"name":"Mark Sivertsen","avatar":""},{"name":"Morse Bicknell","avatar":""},{"name":"Esodie Geiger","avatar":""},{"name":"Merritt C. Glover","avatar":""},{"name":"Toni Ann Gambale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
