INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tuyet-chung', 'Cuộc Đua Tuyệt Chủng', 'Racing Extinction', 'https://phimimg.com/upload/vod/20231101-1/feb9e47e92ad36fddd10cb53898c38b0.jpg', 'https://phimimg.com/upload/vod/20231101-1/406418dafa84bbf31543b313ab1b0658.jpg', '<p>Một nhóm gồm các nhà hoạt động và đổi mới không ngờ tới ấp ủ một sứ mệnh táo bạo nhằm cứu các loài có nguy cơ tuyệt chủng.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elon Musk","avatar":""},{"name":"Jane Goodall","avatar":""},{"name":"Louie Psihoyos","avatar":""},{"name":"Leilani Munter","avatar":""},{"name":"Charles Hambleton","avatar":""},{"name":"Heather Dawn Rally","avatar":""},{"name":"Joel Sartore","avatar":""},{"name":"Paul Hilton","avatar":""},{"name":"Austin Richards","avatar":""},{"name":"Travis Threlkel","avatar":""},{"name":"Dr. Christopher W. Clark","avatar":""},{"name":"Shawn Heinrichs","avatar":""},{"name":"John Veron","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324453);
