INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-cuoc-tan-cong-cua-binh-doan-huy-diet', 'Liên Minh Công Lý: Cuộc Tấn Công Của Binh Đoàn Hủy Diệt', 'LEGO DC Comics Super Heroes: Justice League - Attack of the Legion of Doom!', 'https://phimimg.com/upload/vod/20231101-1/42804819dac4a7880cf81cf823545240.jpg', 'https://phimimg.com/upload/vod/20231101-1/851179054d1ebe5cf05dd48d387ec2e7.jpg', '<p>Tội ác đang hoành hành khi Liên minh Công lý mới thành lập giữ an toàn cho Metropolis và điều này khiến thiên tài độc ác Lex Luthor rất không hài lòng. Cùng với Black Manta, Sinestro và một nhóm tân binh tàn nhẫn, Lex xây dựng liên minh của riêng mình và tuyên bố họ là Legion of Doom. Với đội khủng bố siêu mạnh này và kế hoạch tấn công địa điểm tuyệt mật của chính phủ, Khu vực 52, cuối cùng Lex có thể đứng trước chiến thắng không? Rung chuông báo động và sẵn sàng cho những viên gạch bay lên khi Siêu nhân, Người dơi, Wonder Woman và phần còn lại của Liên minh Công lý đối đầu với những Siêu ác nhân vĩ đại nhất thế giới! Đây là bộ phim gốc hoàn toàn mới tiếp theo của LEGO® và DC Comics.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Hamill","avatar":""},{"name":"Troy Baker","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Josh Keaton","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Dee Bradley Baker","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
