INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-duc-vong', 'Vương Triều Dục Vọng', 'The Treacherous', 'https://phimimg.com/upload/vod/20231030-1/8d8b3ea89c84e2470e6798573d618bea.jpg', 'https://phimimg.com/upload/vod/20231030-1/874a9a5bd22d9a8313cdf8bab97c1807.jpg', '<p>The Treacherous là bộ phim dựa theo nhân vật có thật trong lịch sử Hàn là vị vua Yeonsangun (Yên Sơn Quân) nổi tiếng chuyên quyền. Ông lên ngôi năm 18 tuổi và không biết việc mẹ mình bị các đại thần đầu độc chết. Trong thời gian trị vì, ông có 2 cuộc thanh trừng nho sĩ dã man. Ông còn ra lệnh người dân phải tiến cống 1 vạn cô gái trẻ và ngựa để phục vụ nhu cầu giải trí của mình.The Treacherous nói về Yeonsangun, vị vua tàn bạo nhất trong lịch sử Hàn Quốc, từng tàn sát hàng loạt học giả trong 11 năm trị vì. Ông còn tuyển hàng ngàn cô gái vào cung làm tam cung lục viện để thỏa mãn dục vọng.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Kim Kang-woo","avatar":""},{"name":"Lim Ji-yeon","avatar":""},{"name":"Lee You-young","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Cha Ji-yeon","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Seo Young-joo","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Ryu Abel","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Moon Hee-kyung","avatar":""},{"name":"Kim Do-young","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Jung Da-won","avatar":""},{"name":"Amy","avatar":""},{"name":"Yoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id"