INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-chay-tron', 'Điệp Viên Chạy Trốn', 'American Ultra', 'https://phimimg.com/upload/vod/20231030-1/5df7313ddf2f79afae18703c2f03cd95.jpg', 'https://phimimg.com/upload/vod/20231030-1/b42590f8f44e7b82f3501ef37b282c17.jpg', '<p>American Ultra phim thuộc thể loại hành động do Mỹ sản xuất xoay quanh câu chuyện tình của Mike và Phoebe họ trải qua rất nhiều khó khăn, hình ảnh súng đạn, đánh bom nhựng vụ nổ xãy ra liên tiếp và đuồi bắt đó là những vấn đề của cặp đôi phải gặp nhưng trải qua nhiều sóng gió như thế mới khiến cả hai người có tình cảm mềm mại và ngọt ngào hơn.</p>', 'Full', 1, 'single', 'completed', 22, 2015, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Connie Britton","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Stuart Greer","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Monique Ganderton","avatar":""},{"name":"Nash Edgerton","avatar":""},{"name":"Paul Andrew O''Connor","avatar":""},{"name":"Freddie Poole","avatar":""},{"name":"Ilram Choi","avatar":""},{"name":"James Bendisha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
