INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-da-sac-toc', 'Đội Bóng Đa Sắc Tộc', 'Woodlawn', 'https://phimimg.com/upload/vod/20231030-1/da5c0d346de3943c61a164bb1b7f95df.jpg', 'https://phimimg.com/upload/vod/20231030-1/b5368bcbb8478b8677c8a8260795b3c3.jpg', '<p>Alabama những năm 1970, nạn phân biệt chủng tộc thách thức tài năng, niềm tin và dũng khí của ngôi sao bóng bầu dục trung học da đen Tony Nathan cả trong và ngoài sân cỏ.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"C. Thomas Howell","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Virginia Williams","avatar":""},{"name":"Brando Eaton","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"Nic Bishop","avatar":""},{"name":"Caleb Castille","avatar":""},{"name":"Kelly Greyson","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"Marcus Henderson","avatar":""},{"name":"Joy Brunson","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Kevin Sizemore","avatar":""},{"name":"DeVon Franklin","avatar":""},{"name":"Brett Rice","avatar":""},{"name":"Richard Kohn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
