INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-sat', 'Phản Sát', 'Survivor', 'https://phimimg.com/upload/vod/20231030-1/af68d19495475149f259ecdb39a50736.jpg', 'https://phimimg.com/upload/vod/20231030-1/f56f1dccba748d0ca0f590f044c65fc2.jpg', '<p>Suvivor là câu chuyện về viên an ninh hàng không Kate Abbott, được gửi tới Đại sứ quán Mỹ ở Luân Đôn để duyệt hồ sơ, hộ chiếu nhập cảnh. Tuy nhiên cô lại phát hiện ra nhiều điểm đáng ngờ trong lúc phê duyệt hộ chiếu tại đây. Trước khi có thể tự đặt ra các câu hỏi, Kate gặp rắc rối khi có một vụ đánh bom nhằm giết các nhân viên trong đại sứ quán. Kate sống sót nhưng khi vùng dậy từ trong làn khói và đống đổ nát, một người đàn ông bí ẩn được gọi là Nash hay “Người canh gác” đã cố bắn hạ cô. Tệ hơn, chính phủ lại nghi ngờ cô là người đánh bom và muốn trừ khử. Vừa chạy trốn chính phủ, bọn sát thủ, Kate còn phải theo dấu bọn khủng bố đến New York, nơi mà cô phát hiện mục tiêu của quả bom là Quảng trường Thời Đại trong đêm giao thừa.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Roger Rees","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Sonya Cassidy","avatar":""},{"name":"Antonia Thomas","avatar":""},{"name":"Sean Teale","avatar":""},{"name":"Regé-Jean Page","avatar":""},{"name":"Jing Lusi","avatar":""},{"name":"Benno Fürmann","avatar":""},{"name":"Paddy Wallace","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
