INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong', 'Căn Phòng', 'Room', 'https://phimimg.com/upload/vod/20231029-1/9cbb2aaafeed2aa70ab6a43f311493c7.jpg', 'https://phimimg.com/upload/vod/20231029-1/07b7c55cd4b3931b509d37683cd8f3b9.jpg', '<p>Dựa trên một câu chuyện hiện thực đến khốc liệt nhưng tác phẩm của đạo diễn Lenny Abrahamson vẫn tràn ngập những chân trời màu hồng qua con mắt trẻ thơ. Bộ phim mở ra bằng một ô cửa trời xoay tròn giữa khuôn hình. Ngoài ô cửa là những đám mây trôi. Trong ô cửa là cậu bé tóc vàng, nằm giữa sàn nhà, nhìn trân trối vào màu xanh đến chói mắt. Đó là Jack – cậu bé 5 tuổi - đang sống cùng mẹ là người phụ nữ từng bị cưỡng bức và bắt cóc khỏi gia đình 7 năm trước trong một căn phòng hoàn toàn cách ly với thế giới bên ngoài. Hàng tuần, một người đàn ông mang đồ ăn, thuốc uống và các vật dụng sinh hoạt đến để chu cấp. Vật duy nhất bầu bạn với Jack là chiếc tivi. Tất cả những gì Jack biết về thế giới ngoài kia là qua khung hình vuông với những con người nhỏ xíu đi qua đi lại trong đó. Đến khi Jack lên 6 tuổi, cậu bắt đầu nhận thức và suy nghĩ nghiêm túc về việc thế giới ngoài kia có tồn tại thật hay không...</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brie Larson","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"Tom McCamus","avatar":""},{"name":"Amanda Brugel","avatar":""},{"name":"Joe Pingue","avatar":""},{"name":"Cas Anvar","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Kate Drummond","avatar":""},{"name":"Randal Edwards","avatar":""},{"name":"Jack Fulton","avatar":""},{"name":"Justin Mader","avatar":""},{"name":"Zarrin Darnell-Martin","avatar":""},{"name":"Jee-Yun Lee","avatar":""},{"name":"Ola Sturik","avatar":""},{"name":"Rodrigo Fe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
