INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-san-ban-4-hanh-trinh-ngo-ngan', 'Mùa Săn Bắn 4: Hành Trình Ngớ Ngẩn', 'Open Season: Scared Silly', 'https://phimimg.com/upload/vod/20231030-1/c83b507ea7d9021fc752b4e5b4abd3f9.jpg', 'https://phimimg.com/upload/vod/20231030-1/25a2b8f28fbadd4b9051dfef6e41f752.jpg', '<p>Con người và động vật tin rằng người sói đang trốn thoát và cựu thợ săn Shaw tận dụng cơ hội để mở lại mùa giải. Boog, Elliot và ông Weenie phải đối mặt với nỗi sợ hãi và tìm ra người sói để kết thúc mùa giải vĩnh viễn.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Donny Lucas","avatar":""},{"name":"William Townsend","avatar":""},{"name":"Melissa Sturm","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Shannon Chan-Kent","avatar":""},{"name":"Michelle Murdocca","avatar":""},{"name":"Lorne Cardinal","avatar":""},{"name":"Peter Kelamis","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324453);
