INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-cua-molly', 'Nỗi Ám Ảnh Của Molly', 'The Exorcism of Molly Hartley', 'https://phimimg.com/upload/vod/20231030-1/02b2d3c038e98ea902f06a7693028767.jpg', 'https://phimimg.com/upload/vod/20231030-1/e89f874dc5ac839fef1a46c8c4d29837.jpg', '<p>Diễn ra nhiều năm sau The Haunting of Molly Hartley, người bây giờ, khi trưởng thành, đã bị một linh hồn ác quỷ ám và phải bị một linh mục sa ngã trừ tà trước khi ma quỷ hoàn toàn chiếm đoạt cô.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Lind","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Gina Holden","avatar":""},{"name":"Peter MacNeill","avatar":""},{"name":"Tom McLaren","avatar":""},{"name":"Daina Leitold","avatar":""},{"name":"Julia Arkos","avatar":""},{"name":"Bradley Sawatzky","avatar":""},{"name":"Samantha Kendrick","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324453);
