INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-mu-den', 'Trùm Mũ Đen', 'Blackhat', 'https://phimimg.com/upload/vod/20231030-1/81193e65f9ac94c7f5aca55fa050aba9.jpg', 'https://phimimg.com/upload/vod/20231030-1/7fb06a27b7544031907d38d34ea48c81.jpg', '<p>Chuyện phim kể về chàng tin tặc thiên tài Nicholas Hathaway (Chris Hemsworth thủ vai) được cơ quan chính phủ từ Mỹ và Trung Quốc thuê để truy tìm tổ chức tội phạm bí ẩn được cầm đầu bởi một tin tặc, đang gây ra hàng loạt sự kiện kinh hoàng. Chạy đua với thời gian, trước khi có thêm nhiều tội ác được gây ra, “tin tặc mũ đen” Chris Hemsworth phải dấn thân vào cuộc săn lùng nguy hiểm này với sự đồng hành của cộng sự xinh đẹp do Thang Duy thủ vai.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Tang Wei","avatar":""},{"name":"Leehom Wang","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Andy On","avatar":""},{"name":"Yorick van Wageningen","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Christian Borle","avatar":""},{"name":"Tyson Chak","avatar":""},{"name":"Brandon Molale","avatar":""},{"name":"Danny Burstein","avatar":""},{"name":"Archie Kao","avatar":""},{"name":"Abhi Sinha","avatar":""},{"name":"Jason Butler Harner","avatar":""},{"name":"Manny Montana","avatar":""},{"name":"Spenc","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
