INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trum-mu-den', 'Trùm Mũ Đen', 'Blackhat', 'trùm mũ đen blackhat chris hemsworth tang wei leehom wang viola davis holt mccallany andy on yorick van wageningen john ortiz ritchie coster christian borle tyson chak brandon molale danny burstein archie kao abhi sinha jason butler harner manny montana spenc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-trai-thue', 'Dịch Vụ Trai Thuê', 'The Wedding Ringer', 'https://phimimg.com/upload/vod/20231026-1/2b8202757cd727ec7434a6bf70e6d0e1.jpg', 'https://phimimg.com/upload/vod/20231026-1/f8c4c5309a6e5a190af65126a0c76794.jpg', '<p>Doug Harris là một chú rể đáng yêu nhưng lại vụng về trong xã hội và gặp một vấn đề: anh ấy không có phù rể. Chỉ còn chưa đầy hai tuần nữa là anh kết hôn với cô gái trong mơ của mình, Doug được giới thiệu đến Jimmy Callahan, chủ sở hữu và Giám đốc điều hành của Best Man, Inc., một công ty chuyên cung cấp những người đàn ông phù hợp nhất cho những anh chàng gặp khó khăn trong xã hội. Điều xảy ra sau đó là một trò chơi đố chữ trong đám cưới vui nhộn khi họ cố gắng thực hiện một vụ lừa đảo lớn và tình anh em nảy nở bất ngờ giữa Doug và người đàn ông giả hiệu Jimmy của anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Kaley Cuoco","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Nicky Whelan","avatar":""},{"name":"Dan Gill","avatar":""},{"name":"Corey Holcomb","avatar":""},{"name":"Ken Howard","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Mimi Rogers","avatar":""},{"name":"Aaron Takahashi","avatar":""},{"name":"Alan Ritchson","avatar":""},{"name":"Mimi Gianopulos","avatar":""},{"name":"Nikki Leigh","avatar":""},{"name":"Catherine Chen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
