INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-ve-rong', 'Truyền Thuyết Về Rồng', 'I Am Dragon', 'https://phimimg.com/upload/vod/20231026-1/3ae2db9ab0099ef62d4d5186ce7b7055.jpg', 'https://phimimg.com/upload/vod/20231026-1/1ef0a9575ce85c56e0119e4a07b78f6e.jpg', '<p>Phim Truyền Thuyết Về Rồng là bộ phim viễn tưởng nói về sự thống trị lâu đời của loài rồng lửa tại Vùng đất băng giá, nếu muốn yên ổn với cuộc sống thì loài người phải định kỳ mang những trinh nữ cống nạp cho chúng. Có một chàng dũng sĩ mạnh mẽ lập mưu giết rồng để mang lại bình yên cho người dân ở đây. Anh quyết định giăng mồi để bắt rồng và con mồi ở đây của chàng chính là cô công chúa và cũng là hôn thê của anh ta – Nhưng con rồng này quá khôn ngoan khiến dũng sĩ ôm hận. Trong vực tối của sự sợ hãi, công chúa dần khám phá về quái thú – và đó là 1 chàng trai đầy mê hoặc, hắn ta có thể biến thành người... Liệu rằng rồi số phận của cô công chúa sẽ ra sao ? Liệu con rồng có xấu xa như lời đồn về nó ?</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Mariya Poezzhaeva","avatar":""},{"name":"Matvey Lykov","avatar":""},{"name":"Stanislav Lyubshin","avatar":""},{"name":"Pyotr Romanov","avatar":""},{"name":"Andrey Lebedinskiy","avatar":""},{"name":"Aleksandr Luchinin","avatar":""},{"name":"Viktoriya Runtsova","avatar":""},{"name":"Marta Timofeeva","avatar":""},{"name":"Vladimir Kropotov","avatar":""},{"name":"Yola Sanko","avatar":""},{"name":"Egor Zubarchuk","avatar":""},{"name":"Ieva Andrejevaite","avatar":""},{"name":"Anastasiya Dubrovina","avatar":""},{"name":"Alyona Chekhova","avatar":""},{"name":"Darya","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
