INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-heidi', 'Cô Bé Heidi', 'Heidi', 'https://phimimg.com/upload/vod/20231026-1/a9d3a544cc659f35596003f58a3a89ee.jpg', 'https://phimimg.com/upload/vod/20231026-1/45583f6f15a00e266375ee87e8b59136.jpg', '<p>Heidi là cô bé mồ côi cha mẹ sống hạnh phúc cùng ông nội Almöhi trên dãy núi An-pơ tươi đẹp. Làm bạn với em là Peter, một cậu bé chăn dê nghịch ngợm nhưng tốt bụng. Một hôm, Heidi bị người dì Dete lén bắt đi đến Frank Furt và gửi đến sống tại gia đình của thương gia Sesemann để làm bạn cùng cô con gái Klara, một nàng tiểu thư tội nghiệp phải ngồi trên xe lăn. Bằng sự hoạt bát của mình, Heidi nhanh chóng chiếm được cảm tình của mọi người trong gia đình. Cô bé được học hành, vui chơi và còn được bà của Klara khơi dậy niềm đam mê với sách. Tuy cuộc sống mới rất tốt và đầy đủ nhưng nỗi nhớ về những tháng ngày tự do và vui vẻ cùng ông nội trên dãy núi An-pơ thương yêu chưa bao giờ vơi đi trong Heidi.</p>', 'Full', 1, 'single', 'completed', 23, 2015, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Anuk Steffen","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Quirin Agrippi","avatar":""},{"name":"Isabelle Ottmann","avatar":""},{"name":"Katharina Schüttler","avatar":""},{"name":"Maxim Mehmet","avatar":""},{"name":"Hannelore Hoger","avatar":""},{"name":"Jella Haase","avatar":""},{"name":"Anna Schinz","avatar":""},{"name":"Peter Lohmeyer","avatar":""},{"name":"Lilian Naef","avatar":""},{"name":"Monica Gubser","avatar":""},{"name":"Peter Jecklin","avatar":""},{"name":"Christoph Gaugler","avatar":""},{"name":"Rebecca Indermaur","avatar":""},{"name":"Marietta Jemmi","avatar":""},{"name":"Mich","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-