INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-dinh-everest', 'Thảm Họa Đỉnh Everest', 'Everest', 'https://phimimg.com/upload/vod/20231026-1/344cd995c12bddce50138800ec9440d9.jpg', 'https://phimimg.com/upload/vod/20231026-1/56d8d8ee0be16d31a5d33133c0cfa18d.jpg', '<p>Tường thuật trải nghiệm kinh hoàng của một gia đình, bộ phim đầy kịch tính này khắc họa tình trạng hỗn loạn sau cơn sóng thần khổng lồ đổ bộ vào Đông Nam Á năm 2004.</p>', 'Full', 1, 'single', 'completed', 21, 2015, 'Vietsub', 'HD', 'Iceland', 0, '[{"name":"Jason Clarke","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Martin Henderson","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Thomas M. Wright","avatar":""},{"name":"Clive Standen","avatar":""},{"name":"Naoko Mori","avatar":""},{"name":"Mia Goth","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Tom Goodman-Hill","avatar":""},{"name":"Vanessa Kir","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324453);
