INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-moi-han', 'Tám Mối Hận', 'The Hateful Eight', 'https://phimimg.com/upload/vod/20231026-1/b0a50aa164e350e102984464ae2b7c00.jpg', 'https://phimimg.com/upload/vod/20231026-1/a69d8df7313b7c4378b6f077d3dc3f61.jpg', '<p>Nhiều năm sau Nội chiến, một thợ săn tiền thưởng và con tin của anh ta bị trận bão tuyết ở Wyoming cản bước. Họ bèn ẩn náu trong một nhà ga cùng sáu người lạ khó đoán và nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 23, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"James Parks","avatar":""},{"name":"Dana Gourrier","avatar":""},{"name":"Zoë Bell","avatar":""},{"name":"Lee Horsley","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"Keith Jefferson","avatar":""},{"name":"Craig Stark","avatar":""},{"name":"Belinda Owino","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Quentin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324453);
