INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-chet', 'Ranh Giới Chết', 'Point Break', 'https://phimimg.com/upload/vod/20231026-1/0457ccaf0a67ebb534f63106c9e388d6.jpg', 'https://phimimg.com/upload/vod/20231026-1/3c8b275ca651217a06df3c83692aa1e7.jpg', '<p>Point Break phim thuộc thể loại hành động do Mỹ sản xuất xoay quanh câu chuyện nói về một anh chàng cảnh sát trong đội FBI trẻ tuổi, anh đang trong người một nhiệm vụ phải nằm vùng và trà trộn vào một nhóm vận động mạo hiểm, cả đội điều tra đang nghi ngờ nhóm người này là một bọn tội phạm tinh vi, xảo quyệt và có một thủ lĩnh rất thông minh và không tài nào tìm được chứng cứ phạm tội cả.</p>', 'Full', 1, 'single', 'completed', 11, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edgar Ramírez","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Max Thieriot","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Tobias Santelmann","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"BoJesse Christopher","avatar":""},{"name":"Clemens Schick","avatar":""},{"name":"Matias Varela","avatar":""},{"name":"Nikolai Kinski","avatar":""},{"name":"Judah Lewis","avatar":""},{"name":"Senta Dorothea Kirschner","avatar":""},{"name":"Seumas F. Sargent","avatar":""},{"name":"Daniel Bon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
