INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-may-troi-day', 'Người Máy Trỗi Dậy', 'Ex Machina', 'https://phimimg.com/upload/vod/20231026-1/9a8ecc565dd764bbc35f49a6be94b533.jpg', 'https://phimimg.com/upload/vod/20231026-1/6154722fdafdf3d65ee58321cc8bef36.jpg', '<p>Caleb, một lập trình viên 26 tuổi làm việc tại một công ty internet lớn nhất thế giới, chiến thắng một cuộc thi dành lấy một tuần tu nghiệp thuộc Nathan. Nhưng khi Caleb đến, anh thấy rằng anh sẽ phải tham gia vào một thí nghiệm kỳ lạ và hấp dẫn. Trong đó, anh phải làm việc với trí tuệ nhân tạo (A.I) thực sự đầu tiên của thế giới, nó nằm trong cơ thể của robot mang hình hài môt cô gái xinh đẹp.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Domhnall Gleeson","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Claire Selby","avatar":""},{"name":"Symara A. Templeman","avatar":""},{"name":"Gana Bayarsaikhan","avatar":""},{"name":"Tiffany Pisani","avatar":""},{"name":"Elina Alminas","avatar":""},{"name":"Chelsea Li","avatar":""},{"name":"Dan Pappaspanos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324453);
