INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tru-ta', 'Lễ Trừ Tà', 'The Vatican Tapes', 'https://phimimg.com/upload/vod/20231026-1/9ccd861395637743dbc9b49ef1abe8bb.jpg', 'https://phimimg.com/upload/vod/20231026-1/60a65ba7e7fb9bef732904a6ae9297d1.jpg', '<p>Trong một căn hầm được bảo mật cao nằm sâu trong các bức tường của Thành phố Vatican, Nhà thờ Công giáo lưu giữ hàng nghìn bộ phim và đoạn phim cũ ghi lại các lễ trừ tà</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olivia Taylor Dudley","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Kathleen Robertson","avatar":""},{"name":"Montanna Gillis","avatar":""},{"name":"Noemi Gonzalez","avatar":""},{"name":"Alison Lohman","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"John Patrick Amedori","avatar":""},{"name":"Cas Anvar","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Ashley Gibson","avatar":""},{"name":"Ann Reilly","avatar":""},{"name":"Amie Dellavalle","avatar":""},{"name":"Alex Sparrow","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324453);
