INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-ba-dao', 'Kỳ Nghỉ Bá Đạo', 'Vacation', 'https://phimimg.com/upload/vod/20231026-1/eebc108477a4d013ca06710382388b38.jpg', 'https://phimimg.com/upload/vod/20231026-1/842a311c423fea04db6289d3dad5df32.jpg', '<p>Vacation khởi đầu bằng nỗ lực hàn gắn gia đình của “ông con” Rusty nay đã lớn tuổi. Vốn là phi công của một hãng máy bay quèn, Rusty Griswold (Ed Helms) luôn tự ti vì không thể cho vợ và hai con trai tham gia những chuyến du lịch đắt tiền. &nbsp;Học theo cha mình năm xưa, anh đánh liều tổ chức một chuyến “đi phượt” cho cả nhà tới công viên giải trí Walley World cách nhà anh hàng nghìn cây số trước khi nó đóng cửa mãi mãi. Trên đường đi, nhiều tình huống bi hài xảy ra và khiến nhà Griswold không ít lần rơi vào phen khốn đốn.</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Helms","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Chevy Chase","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Miles Doleac","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Beverly D''Angelo","avatar":""},{"name":"Steele Stebbins","avatar":""},{"name":"Catherine Missal","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Elizabeth Gillies","avatar":""},{"name":"Regina Hal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
