INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-hoc-viec', 'Bố Già Học Việc', 'The Intern', 'https://phimimg.com/upload/vod/20231026-1/12cd90ff36941e743be1ea6360ac8599.jpg', 'https://phimimg.com/upload/vod/20231026-1/03f78bf0ecef2d053c06551eab0720dd.jpg', '<p>Bố Già Học Việc (The Intern): Bộ phim kể về Ben Whittaker, một ông lão góa vợ 70 tuổi (do Robert De Niro thủ vai) nhưng không hề muốn nghỉ hưu và xin vào làm nhân viên thực tập tại một cửa hàng thời trang online của cô chủ xinh đẹp và sành điệu, Jules Ostin (do Anne Hathaway thủ vai). Và câu chuyện diễn ra khi ông lão Ben Whittaker chính thức trở thành thực tập sinh thực thụ, rất trẻ trung và năng động không thua kém bất kì ai. Hơn hết, Ben đã giúp đỡ Jules khi cô nàng gặp khó khăn, truyền cảm hứng và tạo động lực để Jules tiếp tục đam mê nghê nghiệp của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Rene Russo","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"JoJo Kushner","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Zack Pearlman","avatar":""},{"name":"Jason Orley","avatar":""},{"name":"Christina Scherer","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Linda Lavin","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Steve Vinovich","avatar":""},{"name":"C.J. Wilson","avatar":""},{"name":"Mary Kay Place","avatar":""},{"name":"Erin Mackey","avatar":""},{"name":"Christina Br","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
