INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tu-sieu-dang-2015', 'Bộ Tứ Siêu Đẳng', 'Fantastic Four', 'https://phimimg.com/upload/vod/20230912-1/22e381f60682f1dd0c0c7f78361de03a.jpg', 'https://phimimg.com/upload/vod/20230912-1/d0d204b1c53e473d5ae4f8d808d1be07.jpg', '<p><span style="font-family: ">Bộ tứ siêu đẳng 2015 xoay quanh sự hình thành của Bộ tứ siêu đẳng. Tiến sỹ vật lý trẻ Reed Richards cùng phi hành gia Ben Grimm, bạn gái cũ Susan Storm và anh chàng Johnny Storm tham gia vào một cuộc thử nghiệm ngoài vũ trụ. Khi trở về, họ phát hiện ra cơ thể mình đã bị biến đổi một cách kỳ lạ: Richards có thể kéo dài người như cao su, Susan Storm có thể trở nên vô hình và tạo ra một nguồn năng lượng làm lá chắn, Johnny Storm có khả năng tự bốc cháy và bay, còn Grimm trở thành một người đá với sức mạnh khủng khiếp. Không thể trở lại bình thường, bộ tứ buộc phải học cách khai thác những siêu năng lực mới và phối hợp cùng nhau để cứu Trái Đất khỏi kẻ thù hung ác Victor Domashev (Doctor Doom) - chính là người năm xưa từng giúp đỡ họ thực hiện cuộc thử nghiệm.</span></p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miles Teller","avatar":""},{"name":"Michael B. Jordan","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Joshua Montes","avatar":""},{"name":"Dan Castellaneta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324453);
