INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-san-phu-thuy', 'Chiến Binh Săn Phù Thủy', 'The Last Witch Hunter', 'https://phimimg.com/upload/vod/20231024-1/39e42b92e9ebf774e1d5a81c87c7fafb.jpg', 'https://phimimg.com/upload/vod/20231024-1/7ab32f0e638af69d515a6d182eaf0748.jpg', '<p>Bộ phim đặt người xem vào bối cảnh thế giới bị lũng đoạn bởi sự hiện diện của tộc phù thuỷ. Cuộc chiến giữa chúng và những người thợ săn kéo dài hàng bao thế kỷ cho kết khi Kaulder (Vin Diesel) tiêu diệt được Nữ Hoàng (Julie Engelbrecht). Trước khi chết, mụ đã kịp nguyền rủa Kaulder với sự bất tử của chính mình, khiến anh mãi mãi rời xa vợ con, sống một cuộc sống cô độc kiếp này qua kiếp khác. Trở về với thế kỷ 21, Kaulder là thợ săn phù thuỷ duy nhất còn sót lại, vẫn tiếp tục tìm kiếm và tiêu diệt những sinh vật siêu nhiên chết người kia. Nhưng, anh không thể ngờ rằng, thủ lĩnh của chúng - Nữ Hoàng đã được hồi sinh và đang tìm cách trả thù loài người.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Rose Leslie","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Rena Owen","avatar":""},{"name":"Julie Engelbrecht","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Joseph Gilgun","avatar":""},{"name":"Isaach De Bankolé","avatar":""},{"name":"Sloane Coombs","avatar":""},{"name":"Dawn Olivieri","avatar":""},{"name":"Inbar Lavi","avatar":""},{"name":"Bex Taylor-Klaus","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"Armani Jackson","avatar":""},{"name":"Samara Lee","avatar":""},{"name":"Kurt Angle","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324453);
