INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-sau-day-song', 'Biển Sâu Dậy Sóng', 'In the Heart of the Sea', 'https://phimimg.com/upload/vod/20231024-1/b8fe6ff58dfddce4a798ccdfbbf754dc.jpg', 'https://phimimg.com/upload/vod/20231024-1/8bcd6c69e71e8ffcc33a85edf6a530eb.jpg', '<p>Trong khi ra khơi đánh cá, chiếc tầu Essex do viên thuyền trưởng trẻ George Pollard (Benjamin Walker) và thuyền phó giàu kinh nghiệm Owen Chase (Chris Hemsworth) chỉ huy đã bị một con cá voi khổng lồ tấn công. Chẳng ai ngờ được, loài cá voi hiền lành lại hận thù con người đến vậy. Chính sự kiện này đã truyền cảm hứng cho nhà văn Herman Melville để sáng tác ra tiểu thuyết Moby Dick. Tuy nhiên, câu chuyện đằng sau vụ tấn công của con cá voi còn kinh hoàng hơn nhiều. In The Heart Of The Sea tập trung vào khai thác quá trình giành giật sự sống của những người còn tồn tại trên tàu. Họ trải qua hành trình kéo dài 90 ngày đầy đáng sợ, ở cả trên biển lẫn đất liền. Giới hạn về nhân tính, niềm tin, giá trị đạo đức bị đẩy đến tận cùng khi họ phải đương đầu với đại dương, bão biển, đói khát, nỗi sợ hãi và sự tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 23, 2015, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Benjamin Walker","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Frank Dillane","avatar":""},{"name":"Joseph Mawle","avatar":""},{"name":"Edward Ashley","avatar":""},{"name":"Sam Keeley","avatar":""},{"name":"Osy Ikhile","avatar":""},{"name":"Gary Beadle","avatar":""},{"name":"Jamie Sives","avatar":""},{"name":"Morgan Chetcuti","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324453);
