INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-luc-nua-dem', 'Câu Chuyện Lúc Nửa Đêm', 'Goosebumps', 'https://phimimg.com/upload/vod/20231023-1/becacdacac6b1456b2e65fb5724fcef9.jpg', 'https://phimimg.com/upload/vod/20231023-1/581dd761a8e65b51346c7be3b5e0a21d.jpg', '<p>Dựa trên bộ truyện kinh dị nổi tiếng cùng tên của tác giả R.L. Stine, Goosebumps – Câu chuyện lúc nửa đêm sẽ đưa hàng loạt những quái vật đầu sỏ, quái đản và ranh ma sống dậy trên màn ảnh trong mùa Halloween 2015. Jack Black cùng những người bạn của anh sẽ có một cuộc phiêu lưu đầy vất vả để đưa bộ sậu này trở lại với thế giới của chúng.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Black","avatar":""},{"name":"Dylan Minnette","avatar":""},{"name":"Odeya Rush","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Ryan Lee","avatar":""},{"name":"Jillian Bell","avatar":""},{"name":"Halston Sage","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Amanda Lund","avatar":""},{"name":"Steven Krueger","avatar":""},{"name":"Keith Arthur Bolden","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"R.L. Stine","avatar":""},{"name":"Caleb Emery","avatar":""},{"name":"Gabriela Hernandez","avatar":""},{"name":"Nate Andrade","avatar":""},{"name":"Sheldon Brown","avatar":""},{"name":"Mel","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
