INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-hanh-qua-khu', 'Du Hành Quá Khứ', 'Project Almanac', 'https://phimimg.com/upload/vod/20231022-1/ceefe5a48eda8be2b214d5df415f2a46.jpg', 'https://phimimg.com/upload/vod/20231022-1/b7b4d987c5221d8d89add15f39e7be7d.jpg', '<p>Khai thác một đề tài quen thuộc nhưng chưa bao giờ cũ đó là du hành thời gian, bộ phim đưa khán giả làm quen với một nhóm bạn trẻ đang học trung học phổ thông với niềm đam mê tìm tòi và sáng tạo công nghệ. Trong số đó nổi bật nhất là David Raskin (Jonny Weston), thủ lĩnh của cả nhóm, và anh nuôi mộng kiếm được học bổng để vào học trường MIT danh giá. Nhưng trớ trêu là gia đình cậu lại không đủ tiền để chi trả phần còn lại của học phí khi có giấy báo được nhận vào học. Tưởng như David phải từ bỏ ước mơ của mình, thì trong lúc lục lọi căn gác xép tại nhà, một cuốn phim trong chiếc camera cũ của bố để lại đã thu hút sự chú ý của cậu, với đoạn phim cho thấy dường như cậu đã xuất hiện trong sinh nhật 7 tuổi của chính mình trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonny Weston","avatar":""},{"name":"Virginia Gardner","avatar":""},{"name":"Sofia Black-D''Elia","avatar":""},{"name":"Sam Lerner","avatar":""},{"name":"Allen Evangelista","avatar":""},{"name":"Amy Landecker","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Gary Grubbs","avatar":""},{"name":"Patrick Johnson","avatar":""},{"name":"Hillary Harley","avatar":""},{"name":"Anthony Reynolds","avatar":""},{"name":"Agnes Mayasari","avatar":""},{"name":"Katie Garfield","avatar":""},{"name":"Michelle DeFraites","avatar":""},{"name":"Fred Galle","avatar":""},{"name":"Joshua Brady","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
