INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-vu-tru', 'Người Thừa Kế Vũ Trụ', 'Jupiter Ascending', 'https://phimimg.com/upload/vod/20231022-1/27235e2ea64ea5b3f24b0706b1c37e4c.jpg', 'https://phimimg.com/upload/vod/20231022-1/75da8d779d80d25e2d57334f8ac9b3ec.jpg', '<p>Jupiter Ascending là câu chuyện xoay quanh cuộc đời của 1 cô gái- Jupiter Jones (Mila Kunis thủ vai) thay đổi hoàn toàn khi được tiên tri là người sẽ thay thế nữ hoàng vũ trụ.&nbsp; Vì không muốn bị soán ngôi, nữ hoàng đã phái nhiều sát thủ truy lùng, tiêu diệt cô. Và Cain- 1 cựu hunter của quân đội được cử đi bảo vệ cô, đã nảy sinh tình với cô. Liệu cô có sống sót qua sự truy lùng của nữ hoàng. Và tình cảm của cô và Cain sẽ như thế nào?</p>', 'Full', 1, 'single', 'completed', 13, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Eddie Redmayne","avatar":""},{"name":"Douglas Booth","avatar":""},{"name":"Edward Hogg","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Tuppence Middleton","avatar":""},{"name":"Nikki Amuka-Bird","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Christina Cole","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Kick Gurry","avatar":""},{"name":"Tim Pigott-Smith","avatar":""},{"name":"Gugu Mba","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
