INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-4', 'Người Vận Chuyển 4', 'The Transporter Refueled', 'https://phimimg.com/upload/vod/20231023-1/2e6e7a8a565c2ae572320db543cab9e7.jpg', 'https://phimimg.com/upload/vod/20231023-1/899db05fce10fffaab0b5c9cee4e5847.jpg', '<p>Người Vận Chuyển 4 - The Transporter Refueled (2015) Từ nhà sản xuất của ”Lucy” và ”Taken”, tiếp nối thành công của series phim “The Transporter”, ”The Transporter Refueled” với dàn diễn viên hoàn toàn mới cùng nam chính ”gây tranh cãi” Ed Skrein trong vai Frank Martin. Nguy hiểm lớn hơn và công nghệ cũng tối tân hơn, thế nhưng anh vẫn giữ 3 điều luật bất di bất dịch: Không thay đổi giao kèo; Không hỏi tên chủ hàng; Không bao giờ xem gói hàng nhận vận chuyển.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Ed Skrein","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Loan Chabanol","avatar":""},{"name":"Gabriella Wright","avatar":""},{"name":"Tatiana Pajković","avatar":""},{"name":"Wenxia Yu","avatar":""},{"name":"Radivoje Bukvić","avatar":""},{"name":"Noémie Lenoir","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Lenn Kudrjawizki","avatar":""},{"name":"Samir Guesmi","avatar":""},{"name":"Anatole Taubman","avatar":""},{"name":"Robbie Nock","avatar":""},{"name":"Michael Morris","avatar":""},{"name":"Nash Novcic","avatar":""},{"name":"Jochen Hägele","avatar":""},{"name":"Jérôme Zyb","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324453);
