INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-van-chuyen-4', 'Người Vận Chuyển 4', 'The Transporter Refueled', 'người vận chuyển 4 the transporter refueled ed skrein ray stevenson loan chabanol gabriella wright tatiana pajković wenxia yu radivoje bukvić noémie lenoir yuri kolokolnikov lenn kudrjawizki samir guesmi anatole taubman robbie nock michael morris nash novcic jochen hägele jérôme zyb ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-vo-si', 'Con Đường Võ Sĩ', 'Southpaw', 'https://phimimg.com/upload/vod/20231023-1/646921d4e6a4d6e8436f52a891902bec.jpg', 'https://phimimg.com/upload/vod/20231023-1/680beadde1f79196c7b01639cac2acab.jpg', '<p>Billy &quot;The Great&quot; Hope, đương kim vô địch quyền anh hạng trung cấp cơ sở, có một sự nghiệp ấn tượng, một người vợ và con gái yêu thương và lối sống xa hoa. Tuy nhiên, khi bi kịch ập đến, Billy chạm đáy vực sâu, mất đi gia đình, ngôi nhà và người quản lý của mình. Anh sớm tìm thấy một vị cứu tinh bất ngờ là Tick Willis, một cựu võ sĩ huấn luyện những võ sĩ nghiệp dư cứng rắn nhất thành phố. Với tương lai đang bị đe dọa, Hope chiến đấu để giành lại niềm tin của những người anh yêu thương nhất.</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Oona Laurence","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Skylan Brooks","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Victor Ortiz","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Miguel Gómez","avatar":""},{"name":"Dominic Colón","avatar":""},{"name":"Jose Caraballo","avatar":""},{"name":"Malcolm M. Mays","avatar":""},{"name":"Aaron Quattrocchi","avatar":""},{"name":"Lana Young","avatar":""},{"name":"Danny Henriquez","avatar":""},{"name":"Patsy Meck","avatar":""},{"name":"Vit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
