INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chappie', 'Chappie', 'Chappie', 'https://phimimg.com/upload/vod/20231021-1/5ba2bd440e4f5903f32d0f6b66c5e821.jpg', 'https://phimimg.com/upload/vod/20231021-1/2d480d6025099bd105d8b103981ce013.jpg', '<p>Bộ phim Chappie xoay quanh câu chuyện về một chú robot của lực lượng cảnh sát Johannesburg, bị hỏng sau một trận đánh, Chappie được một nhà khoa học trẻ khôi phục lại và “thổi hồn” vào biến cậu thành khác biệt. Chappie có linh hồn, có tình cảm và có suy nghĩ như một con người. Ẩn trong vẻ ngoài lạnh lùng cứng nhắc của một robot cảnh sát, linh hồn Chappie non nớt và ngây thơ như một đứa trẻ. Và hơn bao giờ hết, cậu có một niềm thiết tha mãnh liệt với cuộc sống.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sharlto Copley","avatar":""},{"name":"Dev Patel","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Ninja","avatar":""},{"name":"Yo-Landi Visser","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Chris Shields","avatar":""},{"name":"Anderson Cooper","avatar":""},{"name":"Jose Pablo Cantillo","avatar":""},{"name":"Brandon Auret","avatar":""},{"name":"Johnny Selema","avatar":""},{"name":"Maurice Carpede","avatar":""},{"name":"Jason Cope","avatar":""},{"name":"Kevin Otto","avatar":""},{"name":"Bill Marchant","avatar":""},{"name":"Robert Hobbs","avatar":""},{"name":"Eugene Khumbanyiwa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324453);
