INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-khung-long-tot-bung', 'Chú Khủng Long Tốt Bụng', 'The Good Dinosaur', 'https://phimimg.com/upload/vod/20231021-1/079ff88a4e034d5c760eb19230c950f4.jpg', 'https://phimimg.com/upload/vod/20231021-1/9563f95f994e0d33d8b003346f274557.jpg', '<p>Điều gì sẽ xảy ra nếu mảnh thiên thạch từng mãi mãi thay đổi cuộc sống trên Trái đất biến mất, và loài khủng long khổng lồ không bao giờ bị tuyệt chủng? Hãng phim hoạt hình Pixar sẽ đưa bạn vào một cuộc phiêu lưu tới thế giới của những con khủng long, nơi mà “cậu bé” khủng long Arlo trở thành người bạn của con người. Trong suốt hành trình đi qua những nơi khắc nghiệt và bí ẩn, Arlo đã học được cách đối đầu với nỗi sợ của mình và phát hiện ra khả năng tiềm ẩn bấy lâu.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frances McDormand","avatar":""},{"name":"Raymond Ochoa","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"A.J. Buckley","avatar":""},{"name":"Marcus Scribner","avatar":""},{"name":"Peter Sohn","avatar":""},{"name":"Maleah Nipay-Padilla","avatar":""},{"name":"Jack Bright","avatar":""},{"name":"Ryan Teeple","avatar":""},{"name":"Jack McGraw","avatar":""},{"name":"Mandy Freund","avatar":""},{"name":"Steven Clay Hunter","avatar":""},{"name":"David Boat","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324453);
