INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-vinh-cuu', 'Sắc Đẹp Vĩnh Cửu', 'The Age of Adaline', 'https://phimimg.com/upload/vod/20231020-1/c65ae5e969dbeddac9d3e467c8a0593f.jpg', 'https://phimimg.com/upload/vod/20231020-1/46e8d442fc1a77d466874a76a52bed3f.jpg', '<p>Sắc Đẹp Vĩnh Cửu (The Age of Adaline) là câu chuyện về Adaline, một phụ nữ trẻ sinh ra vào đầu thế kỷ 20. Một tai nạn giao thông bất ngờ khiến quá trình lão hóa của Adaline ngưng lại và đem tới cho cô nhan sắc vĩnh cửu, mãi mãi không già đi. Adaline quyết định sống cuộc đời đơn độc, không gần gũi bất kỳ ai trong suốt hơn một thế kỷ. Tuy nhiên, cuộc gặp gỡ với một chàng trai trẻ đã khơi dậy đam mê, tình yêu và sự lãng mạn ở bên trong người đàn bà hơn 100 tuổi có vẻ ngoài của cô gái hơn 20. Tình yêu này có thể làm thay đổi số phận của Adaline mãi mãi...</p>', 'Full', 1, 'single', 'completed', 15, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Blake Lively","avatar":""},{"name":"Michiel Huisman","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Amanda Crew","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"Hugh Ross","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Fulvio Cecere","avatar":""},{"name":"Anjali Jay","avatar":""},{"name":"Hiro Kanagawa","avatar":""},{"name":"Peter J. Gray","avatar":""},{"name":"Izabel Pearce","avatar":""},{"name":"Cate Richardson","avatar":""},{"name":"Jane Craven","avatar":""},{"name":"Noel Johansen","avatar":""},{"name":"Aaron Craven","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
