INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-biet-nhung-ke-noi-loan', 'Dị Biệt: Những Kẻ Nổi Loạn', 'Insurgent', 'https://phimimg.com/upload/vod/20231020-1/d9b6f94a49ec62bfb3c20f880ec1d786.jpg', 'https://phimimg.com/upload/vod/20231020-1/1839b85e7ccb35b03bdac375869cc487.jpg', '<p>Kết thúc của phần trước, nhân vật chính Beatrice Prior (Shailene Woodley), hay còn gọi là Tris, đã xông vào phòng thí nghiệm thuộc phân khu Erudite và giải cứu được Four (Theo James). Đồng thời cô cũng ngăn chặn được kế hoạch của Jeanine (Kate Winslet) sử dụng công nghệ huyết thanh để khống chế những chiến binh thuộc phân khu Dauntless thành tay sai cho kế hoạch kiểm soát tất cả các phân khu còn lại.&nbsp; Nhưng mối đe dọa ngấm ngầm trong một hệ thống xã hội đã bắt đầu xuất hiện nhiều bất ổn vẫn luôn tồn tại, và để đủ sức mạnh đương đâu với nó, Tris phải tiếp tục chinh phục được nỗi sợ hãi của bản thân trong chính những giấc mơ của mình. Tris mang những phẩm chất của cả 2 phân khu là Dauntless (Dũng cảm) và Abnegation (Vị Tha - Vô Ngã) như Tris, điều đó đồng nghĩa với việc cô phải đối diện với sự mất mát của những người thân yêu nhất.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Theo James","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Ansel Elgort","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Emjay Anthony","avatar":""},{"name":"Keiynan Lonsdale","avatar":""},{"name":"Rosa Salazar","avatar":""},{"name":"Suki Water","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
