INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sicario-ranh-gioi', 'Sicario: Ranh Giới', 'Sicario', 'https://phimimg.com/upload/vod/20231020-1/de95ac85c68dc528fac23032f80ec145.jpg', 'https://phimimg.com/upload/vod/20231020-1/2e95f7f1f2429963b9524c7de7e57575.jpg', '<p>Bộ phim lấy bối cảnh tại Mexico, nơi mà tệ nạn ma túy đang hoành hành và ngay cả cảnh sát cũng vô cùng khó khăn để truy lùng được tội phạm. Nội dung chính của phim là cuộc đối đầu giữa Kate Macer - một nữ nhân viên FBI mẫn cán và một tên trùm ma túy nguy hiểm ở vùng biên giới giữa Mỹ và Mexico.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Julio Cedillo","avatar":""},{"name":"Hank Rogerson","avatar":""},{"name":"Bernardo P. Saracino","avatar":""},{"name":"Maximiliano Hernández","avatar":""},{"name":"Kevin Wiggins","avatar":""},{"name":"Edgar Arreola","avatar":""},{"name":"Kim Larrichio","avatar":""},{"name":"Jesus Nev","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
