INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-me-cung-thu-nghiem-dat-chay', 'Giải Mã Mê Cung: Thử Nghiệm Đất Cháy', 'Maze Runner: The Scorch Trials', 'https://phimimg.com/upload/vod/20231019-1/e233f22f766d40a4444220460d1997a2.jpg', 'https://phimimg.com/upload/vod/20231019-1/f25a6d394db3adaab62df710049bfe9a.jpg', '<p>Thomas và các bạn chưa bao giờ hình dung điều gì ghê gớm hơn các thách thức đã gặp phải trong Mê cung. Nhưng họ đã lầm. Trí nhớ khiếm khuyết của họ khiến họ không biết đến những gì đã và đang diễn ra ở thế giới bên ngoài. Những thứ còn khủng khiếp hơn bầy Nhím Sầu, lắt léo hơn các ngóc ngách Mê Cung và tàn nhẫn hơn cả sự Biến Đổi. Liệu vai trò thật sự của nhóm Thomas trong toàn bộ chuyện này là gì? Sẽ thế nào nếu họ biết rằng còn có những Mê Cung khác ngoài nơi mà họ vừa thoát ra?</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Ki Hong Lee","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Dexter Darden","avatar":""},{"name":"Alexander Flores","avatar":""},{"name":"Jacob Lofland","avatar":""},{"name":"Rosa Salazar","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Terry Da","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c