INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-bi-an', 'Thế Giới Bí Ẩn', 'Tomorrowland', 'https://phimimg.com/upload/vod/20231018-1/0de522eb7b5c8cd505463439af0e8342.jpg', 'https://phimimg.com/upload/vod/20231018-1/9bcb874b52eec1b079d009a89194b27b.jpg', '<p>Một đội quân chưa rõ danh tính tuyên bố nhà sáng chế Frank Walker đang chứa chấp một phần tử bỏ trốn, trong khi bên cạnh ông chỉ là cô bé Casey Newton – người mới mang chiếc cài áo kỳ lạ tới hỏi Frank. Cuộc rượt đuổi diễn ra vô cùng kịch tính trong căn nhà đầy rẫy những vũ khí, đồ vật và cạm bẫy công nghệ cao. Chuyến phiêu lưu của Frank và Casey tiếp tục trong một cỗ máy xuyên thời gian và không gian tới thế giới bí ẩn.</p>', 'Full', 1, 'single', 'completed', 28, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Britt Robertson","avatar":""},{"name":"Raffey Cassidy","avatar":""},{"name":"Tim McGraw","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Shiloh Nelson","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Thomas Robinson","avatar":""},{"name":"Pierce Gagnon","avatar":""},{"name":"Matthew MacCaull","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Matthew Kevin Anderson","avatar":""},{"name":"Michael Giacchino","avatar":""},{"name":"D. Harlan Cuts","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324453);
