INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-bi-an', 'Thế Giới Bí Ẩn', 'Tomorrowland', 'thế giới bí ẩn tomorrowland george clooney hugh laurie britt robertson raffey cassidy tim mcgraw chris bauer shiloh nelson kathryn hahn keegan-michael key thomas robinson pierce gagnon matthew maccaull judy greer matthew kevin anderson michael giacchino d. harlan cuts ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-2015', 'Lọ Lem', 'Cinderella', 'https://phimimg.com/upload/vod/20231018-1/b4cd70e816b75bc5180a26fef401eae7.jpg', 'https://phimimg.com/upload/vod/20231018-1/4c6b1c31449d2277977e8e9cefb82aaf.jpg', '<p>Lọ Lem là một chuyện kể dân gian châu Âu ra đời từ thế kỷ 17, đến nay đã trở thành một trong những nhân vật kinh điển của thế giới cổ tích. Câu chuyện về cô bé Lọ Lem với đôi giầy thủy tinh giống như một giấc mơ đẹp đẽ được truyền từ thế hệ này sang thế hệ khác. 65 năm sau kể từ khi phiên bản hoạt hình ra mắt, Walt Disney quyết định đưa tác phẩm huyền thoại này lên màn ảnh rộng một lần nữa với phiên bản người đóng. Cinderella có kinh phí sản xuất 95 triệu USD và lần đầu ra mắt ở LHP Berlin lần thứ 65 tại Đức hồi tháng hai.Đây không phải lần đầu tiên Disney đưa Cinderella lên màn ảnh rộng, nhưng so với phiên bản hoạt hình từ những năm 1950 thì công nghệ làm phim hiện đại của thế kỷ 21 cùng sự tham gia của ...</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lily James","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Richard Madden","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Sophie McShera","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Ben Chaplin","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Richard McCabe","avatar":""},{"name":"Rob Brydon","avatar":""},{"name":"Jana Pérez","avatar":""},{"name":"Alex MacQueen","avatar":""},{"name":"Tom Edden","avatar":""},{"name":"Gareth Mason","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
