INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-muoi-sac-thai-xam', 'Năm Mươi Sắc Thái: Xám', 'Fifty Shades of Grey', 'https://phimimg.com/upload/vod/20231018-1/9013b49b02cf5170bc3c7d81ca434388.jpg', 'https://phimimg.com/upload/vod/20231018-1/2d12fb572bbd3ffd104a4639423e7eea.jpg', '<p>Câu chuyện bắt đầu khi cô sinh viên Anastasia Steele (Dakota Johnson thủ vai) tới phỏng vấn triệu phú trẻ tuổi Christian Grey (Jamie Dornan) cho tờ tạp chí của trường. Ana đơn giản, trong sáng đã lọt vào mắt xanh của kẻ luôn thích kiểm soát mọi việc là Christian. Anh bắt đầu tiếp cận Ana và cuốn cô vào vòng xoáy của tình ái và nhục cảm. Nhưng đây không phải câu chuyện tình đơn thuần giữa chàng hoàng tử giàu sang lịch lãm và cô gái ngây thơ chân chất.</p>', 'Full', 1, 'single', 'completed', 14, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Jamie Dornan","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Eloise Mumford","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Luke Grimes","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Rita Ora","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Andrew Airlie","avatar":""},{"name":"Dylan Neal","avatar":""},{"name":"Elliat Albrecht","avatar":""},{"name":"Rachel Skarsten","avatar":""},{"name":"Emily Fonda","avatar":""},{"name":"Anthony Konechny","avatar":""},{"name":"Anna Louise","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324453);
