INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-chom-sao-ve-duong-cho-yeu-chay', '12 Chòm Sao: Vẽ Đường Cho Yêu Chạy', 'Zodiac 12: Five Steps of Love', 'https://phimimg.com/upload/vod/20231011-1/806d8ce02649e3b9031cbc883784278f.jpg', 'https://phimimg.com/upload/vod/20231011-1/9f22d63e74eff3be4563661c8903567e.jpg', '<p>12 Chòm Sao: Vẽ đường Cho Yêu Chạy có nội dung xoay quanh chuyện tình lãng mạn nhưng không kém phần gần gũi với mỗi người. Phim gửi thông điệp: Không chòm sao nào chỉ lối ta đến với nhau, chỉ có trái tim yêu không sợ tổn thương mới thực sự là kim chỉ nam hạnh phúc. Phim xoay quanh mối quan hệ tình yêu, tình bạn giữa những chàng trai, cô gái trẻ đẹp với nhiều cá tính riêng biệt, đặc trưng cho người trẻ thời nay.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"B Trần","avatar":""},{"name":"Jun Vũ","avatar":""},{"name":"Quỳnh Chi","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Kim Nha Tran","avatar":""},{"name":"Canh Vu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
