INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('12-chom-sao-ve-duong-cho-yeu-chay', '12 Chòm Sao: Vẽ Đường Cho Yêu Chạy', 'Zodiac 12: Five Steps of Love', '12 chòm sao: vẽ đường cho yêu chạy zodiac 12: five steps of love b trần jun vũ quỳnh chi jun phạm kim nha tran canh vu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-ba-noi-cua-anh', 'Em Là Bà Nội Của Anh', 'Sweet 20', 'https://phimimg.com/upload/vod/20231011-1/fcb2a72a006b619381c4289e1c26db79.jpg', 'https://phimimg.com/upload/vod/20231011-1/0f165793165cfbd8368e8099695c2eb5.jpg', '<p>Chuyện phim xoay quanh bà Đại (NSƯT Minh Đức), bà già kiểu cách, khó tính, đặc biệt yêu thương cậu con trai độc nhất Quang (Đức Khuê) đang là giáo sư đại học. Nhưng tuổi xế chiều của bà không được yên ổn khi mâu thuẫn với con dâu (Hồng Ánh), với bạn bè, với quá khứ đầy sóng gió xưa kia cứ thế ập đến.&nbsp; Trong lúc quẫn bách nhất, phép màu đột ngột xảy đến, biến bà Đại trở thành cô gái trẻ trung tuổi đôi mươi. Không lãng phí cơ hội trời cho, bà quyết định tận dụng từng khoảnh khắc của “giấc mơ đẹp” để hoàn thành nhiều tâm nguyện còn dang dở. Cô gái Thanh Nga (Miu Lê) xinh đẹp xuất hiện, làm đảo lộn cuộc sống của cậu ca sĩ nhạc rock nổi loạn Ngô Trí Tùng (Ngô Kiến Huy) - vốn chính là cháu bà Đại, nhà sản xuất âm nhạc đẹp trai Mạnh Đức (Hứa Vĩ Văn) và cả ông bạn già tên Bé (NSƯT Thanh Nam) lỡ yêu sâu đậm bà Đại từ thuở trẻ.</p>', 'Full', 1, 'single', 'completed', 20, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Miu Lê","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Hari Won","avatar":""},{"name":"Minh Đức","avatar":""},{"name":"Thanh Nam","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Lều Phương Anh","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Đức Khuê","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
