INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-gan-my-nhan-va-gang-to', 'Già Gân, Mỹ Nhân Và Găng Tơ', 'Gia Gan, My Nhan va Gang To', 'https://phimimg.com/upload/vod/20231011-1/eb0fb5b20383b6855c358eda4215312b.jpg', 'https://phimimg.com/upload/vod/20231011-1/5e327c85da0e47b630e0994a0d430186.jpg', '<p>Câu chuyện mở đầu bằng đêm Giáng Sinh cách đây 30 năm, bà Hương – vợ ông Tỏi đột nhiên bỏ nhà ra đi chỉ vì Tỏi không còn là người tử tế.&nbsp; Trong suốt 30 năm, ông Tỏi luôn tìm cách gặp lại bà Hương và hy vọng được bà tha thứ cho lỗi lầm trong quá khứ. Đến một ngày, ông Tỏi quyết định lên thành phố để tìm kiếm vợ con. Nhưng vừa bắt đầu cuộc hành trình, ông “đụng độ” mỹ nhân Quỳnh Cherry – người đang chạy trốn nhóm giang hồ đáng sợ do nắm trong tay nhiều hình ảnh nhạy cảm của chúng. Tuy nhiên, như số phận sắp đặt, Quỳnh Cherry có mối liên hệ mật thiết với bà Hương, còn tên trùm băng đảng kia lại là kẻ thù không đội trời chung với “già gân”.</p>', 'Full', 1, 'single', 'completed', 17, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trường Giang","avatar":""},{"name":"Hoài Linh","avatar":""},{"name":"Toc Tien","avatar":""},{"name":"Thương Tín","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"NSƯT Đức Thịnh","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324453);
