INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dai', 'Ma Dai', 'Tenacious Ghost', 'https://phimimg.com/upload/vod/20231011-1/b59f2966be91ad144b60da368c0bb522.jpg', 'https://phimimg.com/upload/vod/20231011-1/4c07888b4f9413054167a909a66cc60b.jpg', '<p>Ma Dai kể về chuyện tình tay ba giữa một anh chàng “xấu lạ” – Thố và cô nàng xinh đẹp – Lam (Ngân Khánh), cùng Vĩnh (Hà Việt Dũng) – đẹp trai, phong độ.&nbsp; Mặc dù tên phim đề cập đến ma quỷ nhưng nhà sản xuất khẳng định đây không phải phim ma, mà là phim tình cảm – hài xoay quanh một con ma “dai dẳng”. Cũng chính sự dai dẳng này giúp người khác nhận ra những điều quý báu, những giá trị cuộc sống mà theo lời Đức Thịnh thì: “đôi khi có những việc mà có lẽ chúng ta sẽ không hiểu được khi ở cạnh con người, nhưng lại hiểu khi ở cùng một con ma”.</p>', 'Full', 1, 'single', 'completed', 19, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"NSƯT Đức Thịnh","avatar":""},{"name":"Hoài Linh","avatar":""},{"name":"Ngân Khánh","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Hari Won","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
