INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-xau-at-phai-chet', 'Kẻ Xấu Ắt Phải Chết', 'Bad Guys Always Die', 'https://phimimg.com/upload/vod/20230929-1/0648e98bb37439d04d32d2f35589ae1a.jpg', 'https://phimimg.com/upload/vod/20230929-1/61f0564617efcbd11bd3cfb4f5ea27ed.jpg', '<p><span class="key"></span>Cường Tử - một giáo viên dạy tiếng Trung 
tại Busan cùng ba người anh em đến từ quê hương Trung Quốc xa xôi hẹn 
nhau đến đảo Jeju chơi. Tên côn đồ điên cuồng, người phụ nữ Hàn Quốc 
quyến rũ, tay cảnh sát già cố chấp, kẻ theo đuôi bí ẩn và tên mục sư 
không đáng tin liên tiếp xuất hiện bên cạnh họ. Chuyến du lịch mà họ 
mong chờ đã lâu trở nên nguy hiểm và hỗn loạn do sự xuất hiện của những 
kẻ này. Đúng lúc này, một con heo đen bí ẩn xuất hiện, đẩy mọi người đến
 cửa sinh tử... Rốt cuộc thì ai mới là &quot;kẻ xấu&quot; đáng chết thực sự?</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Shin Hyun-joon","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Ding Wenbo","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Kim Yoon-hee","avatar":""},{"name":"Yang Xuwen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
