INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-yeu-thoi-dai', 'Chuyện Tình Yêu Thời Đại', 'Bang Gang (A Modern Love Story)', 'https://phimimg.com/upload/vod/20230925-1/1f8751f93eede62be4a47c4dc36f5b36.jpg', 'https://phimimg.com/upload/vod/20230925-1/e04e535f797b2093d21cc655b70b4919.jpg', '<p>Biarritz. George, mười sáu tuổi, một chàng trai hấp dẫn thời trung học, phải lòng Alex. Để thu hút sự chú ý của anh ấy, cô ấy bắt đầu một trò chơi nhóm với Alex, Nikita, Laetitia và Gabriel. Họ sẽ khám phá, kiểm tra và vượt qua giới hạn về giới tính của mình.</p>', 'Full', 1, 'single', 'completed', 18, 2015, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Marilyn Lima","avatar":""},{"name":"Daisy Broom","avatar":""},{"name":"Finnegan Oldfield","avatar":""},{"name":"Lorenzo Lefèbvre","avatar":""},{"name":"Fred Hotier","avatar":""},{"name":"Olivia Lancelot","avatar":""},{"name":"Manuel Husson","avatar":""},{"name":"Raphaël Porcheron","avatar":""},{"name":"Tatiana Werner","avatar":""},{"name":"Olivier Lefebvre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324453);
