INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-sung-suong', 'Căn Phòng Sung Sướng', 'In the Room', 'https://phimimg.com/upload/vod/20230922-1/b4c243d640a7eaccde52617eadb4d7ef.jpg', 'https://phimimg.com/upload/vod/20230922-1/56a7c804841784703ee14072c23a99e3.jpg', '<p>Bộ phim nhạy cảm và gợi cảm này tập hợp nhiều câu chuyện kéo dài nhiều thập kỷ, tất cả đều diễn ra trong cùng một căn phòng của cùng một khách sạn Singapore - và tất cả đều liên quan đến tình dục.</p>', 'Full', 1, 'single', 'completed', 21, 2015, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Josie Ho","avatar":""},{"name":"Shou Nishino","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Kim Kkob-bi","avatar":""},{"name":"Gillian Tan","avatar":""},{"name":"Boon Pin Koh","avatar":""},{"name":"Daniel Jenkins","avatar":""},{"name":"Nadia Ar","avatar":""},{"name":"George Young","avatar":""},{"name":"Lawrence Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
