INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-nay-ngay-nay', 'Ngày Nảy Ngày Nay', 'The Lost Dragon', 'https://phimimg.com/upload/vod/20230918-1/21846e16a1836b47b7a2480a42fc5fec.jpg', 'https://phimimg.com/upload/vod/20230918-1/3d7086abe3a970f28bc07e354e0fb2d3.jpg', '<p><span style="font-family: ">Bộ phim Ngày Nảy Ngày Nay xoay quanh chuyến hành trình gian nan nhưng không kém phần hài hước của hai nàng tiên khi xuống trần gian làm nhiệm vụ. Chính trong hành trình trải nghiệm làm con người dưới trần thế, hai nàng tiên đã hiểu được tình người, tình yêu và những điều ở nhân gian khác xa với nơi hai cô đang sống. Bộ phim còn có sự tham gia của diễn viên Ngô Thanh Vân, Lê Khánh, diễn viên trẻ Quốc Dũng, ảo thuật gia Petey Nguyễn,…Đặc biệt, phim có sự tham gia biên soạn kịch bản của Jun Phạm – thành viên nhóm 365.</span></p>', 'Full', 1, 'single', 'completed', 23, 2015, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Veronica Ngo","avatar":""},{"name":"Petey Nguyễn","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Diễm My","avatar":""},{"name":"Thành Lộc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
