INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-lep-ve', 'Cô Bạn Lép Vế', 'The DUFF', 'https://phimimg.com/upload/vod/20230917-1/f0d737b0c2ff3d487a7910b7443bd429.jpg', 'https://phimimg.com/upload/vod/20230917-1/037ee80edfad87a957da7298a235dd07.jpg', '<p>Cuộc Chiến Của Những Cô Nàng Cá Tính - The Duff: Một quy tắc ngầm trong các nhóm bạn đó là: Nhóm nào cũng sẽ có một cô nàng xấu xí khiến những người còn lại trông lộng lẫy hơn và được gọi là Duff - Hầu Gái Xấu Xí. Cô nàng Bianca không muốn chấp nhận sự thật này nên quyết tâm thay đổi hình ảnh của mình. Liệu cuộc chiến của cô có thành công?</p>', 'Full', 1, 'single', 'completed', 23, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mae Whitman","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Bella Thorne","avatar":""},{"name":"Skyler Samuels","avatar":""},{"name":"Bianca A. Santos","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Chris Wylde","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Seth Meriwether","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324453);
