INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('45-nam-ngay-cuoi', '45 Năm Ngày Cưới', '45 Years', 'https://phimimg.com/upload/vod/20230916-1/e47151192c42cf72d90e728589e6fe72.jpg', 'https://phimimg.com/upload/vod/20230916-1/abb320e32a330b92d3e85eca28133be6.jpg', '<p><span style="font-family: ">Cuộc sống hôn nhân bình lặng của Kate và Geoff bất ngờ bị phá vỡ trước lễ kỷ niệm 45 ngày cưới bởi một lá thư về mối tình đầu của Geoff.</span></p>', 'Full', 1, 'single', 'completed', 29, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Charlotte Rampling","avatar":""},{"name":"Tom Courtenay","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Dolly Wells","avatar":""},{"name":"David Sibley","avatar":""},{"name":"Sam Alexander","avatar":""},{"name":"Richard Cunningham","avatar":""},{"name":"Hannah Chalmers","avatar":""},{"name":"Camille Ucan","avatar":""},{"name":"Rufus Wright","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324453);
