INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ve-tu-sao-hoa', 'Người Về Từ Sao Hỏa', 'The Martian', 'https://phimimg.com/upload/vod/20230915-1/e1f374e896a08ca9ef0a41637f7a7573.jpg', 'https://phimimg.com/upload/vod/20230915-1/3f0fe46d353ab38cac33709dc6a9ede4.jpg', '<p><span style="font-family: ">The Martian xoay quanh hành trình trở về đầy phi thường của phi hành gia Mark Watney. Trong quá trình thực hiện nhiệm vụ trên sao Hỏa, Mark Watney (Matt Damon) được cho rằng đã tử nạn sau một trận bão lớn và bị mọi người bỏ lại phía sau. Tuy nhiên, Watney may mắn sống sót và bị mắc kẹt một mình trên hành tinh cằn cỗi. Anh sẽ phải sử dụng tất cả kinh nghiệm và kiến thức của mình để tiếp tục tồn tại trên một hành tinh không có sự sống và hi vọng một ngày sẽ được cứu thoát. Quan trọng hơn cả, Watney luôn giữ cho mình một nghị lực kiên cường và tinh thần thật lạc quan. Mặc dù cách xa đến hàng triệu dặm, NASA và các nhà khoa học quốc tế vẫn làm việc không mệt mỏi để có thể đưa Watney trở về an toàn.</span></p>', 'Full', 1, 'single', 'completed', 33, 2015, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Aksel Hennie","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324453);
