INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-bai', 'Trùm Bài', 'Wild Card', 'https://phimimg.com/upload/vod/20230915-1/f5ae4c22c45262612410a25afea51071.jpg', 'https://phimimg.com/upload/vod/20230915-1/2502c8c26a90ac236326b82bbc024b88.jpg', '<p><span style="font-family: &quot;Times New Roman&quot;; font-size: medium; text-wrap: wrap;">Wild Card (Trùm Bài) là một bộ phim mang phong cách hành động kể về thế giới ngầm của những tay cờ bạc. Phim được chuyển thể từ tiểu thuyết Heat của William Goldman, xuất bản năm 1985. Nhiều ý kiến cho rằng đây thực chất là phiên bản làm lại của một bộ phim chuyển thể khác được thực hiện từ năm 1986 trước đây. Trong phim, Jason Statham sẽ đóng vai Nick Wild, một tay nghiện cờ bạc hạng nặng tại Las Vegas. Để thỏa mãn thú vui cờ bạc của mình, Nick Wild đã chấp nhận làm bảo kê cho bạn của mình. Kể từ đây, những rắc rối đến từ thế giới của các tay cờ bạc sành sỏi cũng cứ thế tìm đến với Nick Wild.Lấy bối cảnh vài ngày trước lễ Giáng sinh ở thành phố Las Vegas phồn hoa - nơi những con bạc lao mình vào các cuộc đỏ</span></p>', 'Full', 1, 'single', 'completed', 31, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Dominik Garcia","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Anne Heche","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324453);
