INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu-hung-nhai-phan-2', 'Trò Chơi Sinh Tử: Húng Nhại - Phần 2', 'The Hunger Games: Mockingjay - Part 2', 'https://phimimg.com/upload/vod/20230912-1/69161f37a5d5c765b712586fdf4ab82a.jpg', 'https://phimimg.com/upload/vod/20230912-1/9dc918b723d2d2e3fd0dbb9f3e4a8f35.jpg', '<p><span style="font-family: ">Sau khi được tôn vinh như “Húng Nhại” - biểu tượng cho niềm hy vọng và khát khao tự do, Katniss cùng những người dân ở Quận 13 quyết tâm đứng lên thực hiện cuộc khởi nghĩa nhằm vào Capitol. Cách duy nhất để dành phần thắng chính là trừ khử tổng thống Snow - kẻ chủ mưu đứng đằng sau tất cả những nỗi đau thương mà Panem phải chịu đựng suốt hơn 70 năm qua. Luôn đi trước một bước, mọi thứ với Snow dường như luôn nằm trong dự định, đặc biệt là khi âm mưu của lão được vén màn: Capitol chính là Đấu Trường Sinh Tử lần thứ 76. Một lần nữa, Katniss cùng nhóm của mình bất đắc dĩ sẽ phải tham gia vào trò chơi man rợ này để chấm dứt tất cả.</span></p>', 'Full', 1, 'single', 'completed', 38, 2015, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Stanley Tucci","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324453);
