INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-giam-doc-quyen-ru', 'Nữ Giám Đốc Quyến Rũ', 'For The Emperor', 'https://phimimg.com/uploads/movies/20260713/nu-giam-doc-quyen-ru-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/nu-giam-doc-quyen-ru-poster.webp', '<p>Yi-Hwan (Lee Min-Ki) là một cựu cầu thủ bóng chày chuyên nghiệp. Anh ta dính líu đến việc sửa chữa trò chơi và mất tất cả. Ông trùm băng đảng Sang-Ha (Park Sung-Woong) điều hành một doanh nghiệp cho vay tiền và một địa điểm đánh bạc. Anh ta bắt Yi-Hwan làm việc cho mình. Trong khi đó, Yi-Hwan phải lòng chủ quán bar Yeon-Soo (Lee Tae-Im).</p>', 'Full', 1, 'single', 'completed', 49, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Min-ki","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Lee Tae-im","avatar":""},{"name":"Kim Jong-goo","avatar":""},{"name":"Jung Heung-Chae","avatar":""},{"name":"Lee Jae-won","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Han Jae-yeong","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"You Chea-myung","avatar":""},{"name":"Choi Hye-jeong","avatar":""},{"name":"Amy","avatar":""},{"name":"Yoon Sung-won","avatar":""},{"name":"Hee-jeong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hwangjereul Wihayeo","王道","为了皇帝","皇帝のために：2014","황제를 위하여"]', 1784690324453);
