INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-giam-doc-quyen-ru', 'Nữ Giám Đốc Quyến Rũ', 'For The Emperor', 'nữ giám đốc quyến rũ for the emperor lee min-ki park sung-woong lee tae-im kim jong-goo jung heung-chae lee jae-won park jin-woo han jae-yeong lee yoo-jun you chea-myung choi hye-jeong amy yoon sung-won hee-jeong hwangjereul wihayeo 王道 为了皇帝 皇帝のために：2014 황제를 위하여', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('olive-kitteridge', 'Olive Kitteridge', 'Olive Kitteridge', 'https://phimimg.com/upload/vod/20260626-1/8204c22a0238324bbb2b9914a4c9837f.jpg', 'https://phimimg.com/upload/vod/20260626-1/894207b627ba2bd438c4139901d30277.jpg', '<p>Bộ phim là góc nhìn cận cảnh về một thị trấn vùng New England có vẻ ngoài yên bình nhưng bên trong lại đầy rẫy những mối quan hệ bất chính, tội ác và bi kịch. Tất cả được kể qua lăng kính của Olive, một người phụ nữ sở hữu trí tuệ sắc sảo nhưng cay nghiệt, cùng vẻ ngoài khắc nghiệt che giấu một trái tim ấm áp đầy tổn thương và một nguyên tắc đạo đức kiên định. Câu chuyện trải dài suốt 25 năm, xoay quanh mối quan hệ giữa Olive với chồng cô, Henry, một dược sĩ tốt bụng, hiền lành của thị trấn; người con trai Christopher luôn oán hận cách nuôi dạy con của mẹ; cùng các thành viên khác trong cộng đồng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 33, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Frances McDormand","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Martha Wainwright","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"John T. Mullen","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Brady Corbet","avatar":""},{"name":"Donna Mitchell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Olive Kitteridge"]', 1784690324453);
