INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leviathan', 'Leviathan', 'Leviathan', 'https://phimimg.com/upload/vod/20260617-1/5b5a633a3c23c6f3a5765c3e1a422879.jpg', 'https://phimimg.com/upload/vod/20260617-1/32e8f7041e33b957a86e16fb85cffc93.jpg', '<p>Tại một thị trấn ven biển của Nga, Kolya buộc phải chống lại thị trưởng tham nhũng khi biết tin nhà mình sắp bị phá dỡ. Anh nhờ một người bạn luật sư giúp đỡ, nhưng sự xuất hiện của người bạn này lại mang đến thêm nhiều bất hạnh cho Kolya và gia đình anh.</p>', 'Full', 1, 'single', 'completed', 29, 2014, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Aleksey Serebryakov","avatar":""},{"name":"Elena Lyadova","avatar":""},{"name":"Vladimir Vdovichenkov","avatar":""},{"name":"Roman Madyanov","avatar":""},{"name":"Anna Ukolova","avatar":""},{"name":"Aleksey Rozin","avatar":""},{"name":"Sergey Pokhodaev","avatar":""},{"name":"Platon Kamenev","avatar":""},{"name":"Sergey Bachurskiy","avatar":""},{"name":"Valeriy Grishko","avatar":""},{"name":"Alla Emintseva","avatar":""},{"name":"Margarita Shubina","avatar":""},{"name":"Dmitriy Bykovskiy-Romashov","avatar":""},{"name":"Sergey Borisov","avatar":""},{"name":"Ig","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Leviafan","Leviatan","Левиафан"]', 1784690324453);
