INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-mat-luong-tri', 'Đánh Mất Lương Tri', 'Against The Tide', 'https://phimimg.com/upload/vod/20260611-1/721b508bb03606b09c7c1ca9ad614ec5.jpg', 'https://phimimg.com/upload/vod/20260611-1/40edcedab429ba921a7d943d3d7d880d.jpg', '<p>Bộ phim dẫn dắt người xem vào hành trình phá án đầy cuốn hút, nơi mỗi manh mối đều mở ra những bí mật khó lường. Tiểu thuyết gia Địch Thâm với những quan điểm gây tranh cãi cùng bác sĩ tâm lý Tuyết Thanh bắt tay khám phá từng vụ việc. Một người phân tích hiện trường, một người đi sâu vào tâm lý, họ dần hé lộ những góc khuất phía sau mỗi con người. Nhưng khi càng tiến gần sự thật, họ cũng phải đối diện với câu hỏi: điều gì khiến con người đánh mất lương tri?</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 35, 2014, 'Lồng Tiếng', 'FHD', 'Singapore', 0, '[{"name":"Lý Minh Thuận","avatar":""},{"name":"Trần Huýnh Giang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆潮"]', 1784690324453);
