INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-buom-den-phan-1', 'Cánh Buồm Đen (Phần 1)', 'Black Sails (Season 1)', 'https://phimimg.com/upload/vod/20260608-1/1aad81f9b0d363bf1fe32f1f1fce10a3.jpg', 'https://phimimg.com/upload/vod/20260608-1/639984ac6cb13209eae43096b668e776.jpg', '<p>Cư dân đảo New Providence có thể không chính trực lắm, nhưng đó là quê hương của thuyền trưởng cướp biển Flint, và anh sẽ chống lại bất cứ thế lực nào muốn giành lấy nó.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 37, 2014, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Toby Stephens","avatar":""},{"name":"Luke Arnold","avatar":""},{"name":"Hannah New","avatar":""},{"name":"Jessica Parker Kennedy","avatar":""},{"name":"Toby Schmitz","avatar":""},{"name":"Tom Hopper","avatar":""},{"name":"Clara Paget","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Luke Roberts","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Black Sails／ブラック・セイルズ","Black Sails ブラック・セイルズ","Black Sails"]', 1784690324453);
