INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-gioi', 'Lạc Giới', 'Paradise In Heart', 'https://phimimg.com/upload/vod/20260605-1/98cf15e95bb6f5a20134fa1f7b6ee534.jpg', 'https://phimimg.com/upload/vod/20260605-1/731643d5c7304d6ef47c634bcf4c0654.jpg', '<p>“Lạc giới” là một câu chuyện tình yêu hiện đại, lãng mạn, nhưng trĩu nặng tâm tư của những người trong cuộc, khiến người xem động lòng trắc ẩn. Thông qua câu chuyện éo le, đầy kịch tính về số phận của những người được coi là “lạc giới” trong đời sống xã hội, bộ phim nêu lên thông điệp: “Trong hành trình đi tìm hạnh phúc và hoàn thiện bản thân, con người cần được sống đúng với bản ngã của mình, miễn điều đó không làm tổn hại đến người khác và cả cộng đồng. Trong cuộc sống chúng ta hãy nên tôn trọng sự khác biệt”.</p>', 'Full', 1, 'single', 'completed', 35, 2014, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trung Dũng","avatar":""},{"name":"Mai Thu Huyền","avatar":""},{"name":"Bình An","avatar":""},{"name":"Vũ Tuấn Việt","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Mai Hồ","avatar":""},{"name":"Mai Thu Trang","avatar":""},{"name":"Tuyền Mập","avatar":""},{"name":"Trung Dân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Paradise In Heart","Lạc Giới"]', 1784690324453);
