INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lac-gioi', 'Lạc Giới', 'Paradise In Heart', 'lạc giới paradise in heart trung dũng mai thu huyền bình an vũ tuấn việt thành lộc mai hồ mai thu trang tuyền mập trung dân paradise in heart lạc giới', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-phap-va-trat-tu-nan-nhan-dac-biet-phan-16', 'Luật Pháp Và Trật Tự: Nạn Nhân Đặc Biệt (Phần 16)', 'Law & Order: Special Victims Unit (Season 16)', 'https://phimimg.com/upload/vod/20260604-1/225d6962223215676f9d46c1788c5671.jpg', 'https://phimimg.com/upload/vod/20260604-1/5d6fece59538c4fc717beed5c2039b51.jpg', '<p>Trong hệ thống tư pháp hình sự, các tội danh liên quan đến xâm hại tình dục được coi là đặc biệt ghê tởm. Tại thành phố New York, những thám tử tận tụy điều tra các vụ trọng tội tàn ác này là thành viên của một đội ngũ tinh nhuệ được biết đến với cái tên Đơn Vị Nạn Nhân Đặc Biệt. Đây là những câu chuyện của họ.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 22, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mariska Hargitay","avatar":""},{"name":"Ice-T","avatar":""},{"name":"Kelli Giddish","avatar":""},{"name":"Peter Scanavino","avatar":""},{"name":"Aimé Donna Kelly","avatar":""},{"name":"Kevin Kane","avatar":""},{"name":"Corey Cott","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Ley y el Orden: UVE","Law & Order: Unidade de Vítimas Especiais (SVU)","Law & Order: Investigação Especial","Lei & Ordem: UVE","Law and Order: New York","La  Loi & l''Ordre : USV","La  Loi & l''Ordre : Unité spéciale","New York : Unité spéciale","قانون و نظم: واحد قربانیان ویژه","LAW & ORDER： 性犯罪特捜班","성범죄수사대: SVU","로 앤 오더: 성범죄 전담반","로앤오더: 성범죄전담반","로앤오더: 성범죄 전담반","Law & Order: 성범죄전담반","Law & Order: 성범죄 전담반","Likums un Kārtība: Ņujorka",