INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-vu-ra-tro-nhung-cau-chuyen-cua-so-cuu-hoa-new-york', 'Một Vụ Ra Trò: Những Câu Chuyện Của Sở Cứu Hỏa New York', 'A Good Job: Stories of the FDNY', 'https://phimimg.com/upload/vod/20260531-1/36102ad9c08b858294721cfa015245fe.jpg', 'https://phimimg.com/upload/vod/20260531-1/793a43cc059a2b8b71df8c608abde1fb.jpg', '<p>Qua những lời kể trực tiếp từ các lính cứu hỏa kì cựu và cựu thành viên Sở cứu hỏa New York, phim tài liệu của HBO hé lộ những hiểm nguy khi ở tuyến đầu chống thần lửa.</p>', 'Full', 1, 'single', 'completed', 23, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Buscemi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["A Good Job: Stories of the FDNY"]', 1784690324453);
