INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-tamako', 'Chuyện Tình Tamako', 'Tamako Love Story', 'https://phimimg.com/upload/vod/20260530-1/757b9ed7acd8a272a6dfb2181e858058.jpg', 'https://phimimg.com/upload/vod/20260530-1/85ec83ce6b7c06b5d9bc93285384f8c3.jpg', '<p>Dành trọn cho công việc kinh doanh bánh gạo của gia đình và câu lạc bộ &quot;dùi cui&quot; ở trường trung học, Tamako hơi chậm chạp khi yêu. Cô ấy không biết gì về tình cảm của người bạn thời thơ ấu Mochizo của mình, mặc dù tất cả bạn bè của họ đều biết. Khi lễ tốt nghiệp kết thúc và Mochizo rời đến Tokyo, liệu Tamako có nhận ra tình cảm của mình và nói với anh ấy kịp thời?</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Suzaki","avatar":""},{"name":"Atsushi Tamaru","avatar":""},{"name":"Yuri Yamaoka","avatar":""},{"name":"Yuki Kaneko","avatar":""},{"name":"Juri Nagatsuma","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Takumi Yamazaki","avatar":""},{"name":"Yurie Yamashita","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Satsuki Yukino","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Koji Tsujitani","avatar":""},{"name":"Tomomichi Nishimura","avatar":""},{"name":"Kyousei Ts","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["たまこラブストーリー","Tamako Love Story","玉子市场 剧场版"]', 1784690324453);
