INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-heck-phan-6', 'Gia đình Heck (Phần 6)', 'The Middle (Season 6)', 'https://phimimg.com/upload/vod/20260516-1/335e9f1a8a6496f8d29cb996745d6eb9.jpg', 'https://phimimg.com/upload/vod/20260516-1/a8cd8bd82070630771f99b765ff31f9e.jpg', '<p>Đây là mùa thứ sáu rồi, và gia đình Heck sẽ đi về đâu đây? Khi lũ trẻ – Axl, Sue và Brick – ngày càng lớn, Frankie và Mike nghĩ rằng cuộc sống gia đình sẽ dễ dàng hơn, nhưng họ đã nhầm to! Con cái lớn hơn chỉ có nghĩa là rắc rối lớn hơn! Dù gia đình Heck làm gì đi nữa, đừng bao giờ thử làm theo ở nhà!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patricia Heaton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Eden Sher","avatar":""},{"name":"Atticus Shaffer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["左右不逢源","中产家庭","中之道","Anyám borogass","Családom és egyéb emberfajták","ザ・ミドル ～中流家族のフツーの幸せ～","คุณแม่สามัญประจำบ้าน","The Middle"]', 1784690324453);
