INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-quyet-cho-lan-da-min-mang', 'Bí Quyết Cho Làn Da Mịn Màng', 'The Secret To My Silky Skin', 'https://phimimg.com/upload/vod/20260511-1/880112bdf0ff54d4ec624ed9d930d209.jpg', 'https://phimimg.com/upload/vod/20260511-1/ce84f8d68da9bc747c0fdbc787db4dec.jpg', '<p>Một chàng trai sống cùng bố mẹ ở Kyoto đến Tokyo công tác và ở nhờ nhà người tình của mình. Họ không có kế hoạch đặc biệt nào cho năm ngày ở bên nhau. Họ sẽ đi làm vào buổi sáng, về nhà, dành buổi tối bên nhau và ngủ. Đêm đầu tiên khi đến nơi, người tình bắt đầu quan hệ tình dục với anh ta như thường lệ, nhưng anh ta lại không thể đáp lại. Thực tế, anh ta đã lo lắng về một điều gì đó từ trước khi đến Tokyo.</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Lyota Majima","avatar":""},{"name":"Issei Honna","avatar":""},{"name":"今泉浩一","avatar":""},{"name":"Hiro Kitagawa","avatar":""},{"name":"Jinta Fujimaru","avatar":""},{"name":"伊藤清美","avatar":""},{"name":"Yasumoto Akaiwa","avatar":""},{"name":"葉月螢","avatar":""},{"name":"Emi Sato","avatar":""},{"name":"Kazuko Uchida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["すべすべの秘法"]', 1784690324453);
