INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-dua-thu', 'Huyền Thoại Đưa Thư', 'Postman Pat: The Movie', 'https://phimimg.com/upload/vod/20260502-1/afab86653d928f6e1fdc2857cae86c5d.jpg', 'https://phimimg.com/upload/vod/20260502-1/d76669b523e322bc1a98376e3a3dc13d.jpg', '<p>Bác đưa thư Pat với cuộc sống giản dị bất ngờ tham gia một chương trình tìm kiếm tài năng, từ đó bị cuốn vào thế giới showbiz hào nhoáng và những thay đổi lớn trong cuộc sống, khiến ông phải đối mặt với lựa chọn giữa danh tiếng và những giá trị thân thuộc, đồng thời khám phá ý nghĩa thật sự của hạnh phúc.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2014, 'Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Stephen Mangan","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Ronan Keating","avatar":""},{"name":"Susan Duerden","avatar":""},{"name":"Sandra Teles","avatar":""},{"name":"T.J. Ramini","avatar":""},{"name":"Peter Woodward","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Brian George","avatar":""},{"name":"Parminder Nagra","avatar":""},{"name":"Jo Wyatt","avatar":""},{"name":"Enn Reitel","avatar":""},{"name":"Jane Carr","avatar":""},{"name":"Dan Hildebrand","avatar":""},{"name":"Darren Richardson","avatar":""},{"name":"Jac","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["邮递员派特叔叔","Carteiro Paulo - O Filme","Postmand Per - Filmen","Pieter Post - De Film","Postman Pat: The Movie"]', 1784690324453);
