INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('transformers-ky-nguyen-huy-diet', 'Transformers: Kỷ Nguyên Hủy Diệt', 'Transformers: Age of Extinction', 'https://phimimg.com/upload/vod/20260225-1/681e6d9b0430374841cdd5170606a465.jpg', 'https://phimimg.com/upload/vod/20260225-1/881241118d52a2b017188b47e8d2823e.jpg', '<p>Transformers 4 được bắt đầu sau 4 năm về trận chiến ở Los Angeles trong phần trước Transformers: Dark of the Moon. Câu chuyện mở màn bởi những lời đồn đại về một thợ cơ khí và con gái của ông ta đã phát hiện ra một bí mật có thể khiến cả Autobots, Decepticons, và chính phủ Hoa Kỳ bị đe dọa. Không chỉ dừng lại ở đó, ở phần này, câu chuyện sẽ dẫn người xem đến những ngã rẻ hoàn toàn mới và cũng vô vàn những bất ngờ.</p>', 'Full', 1, 'single', 'completed', 24, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Nicola Peltz Beckham","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Sophia Myles","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Titus Welliver","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Mark Ryan","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"James Bachman","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Charle","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d