INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-duc-chet-nguoi', 'Đạo Đức Chết Người', 'Deadly Virtues: Love. Honour. Obey.', 'https://phimimg.com/upload/vod/20260213-1/16ac6c55e62d153c0d68942ef57b5490.jpg', 'https://phimimg.com/upload/vod/20260213-1/df660c984ce69410946b462ecbbb6734.jpg', '<p>Một kẻ lạ mặt đột nhập vào ngôi nhà của một cặp vợ chồng, trói người chồng và dành trọn một cuối tuần để thao túng người vợ trong trò chơi tâm lý tàn nhẫn đầy đe dọa, sợ hãi và ép buộc, nơi ranh giới giữa bạo lực, sự phục tùng và mối quan hệ thân mật bị xóa nhòa, từng bước đẩy các nhân vật vào vòng xoáy nguy hiểm của quyền lực</p>', 'Full', 1, 'single', 'completed', 35, 2014, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Edward Akrout","avatar":""},{"name":"Matt Barber","avatar":""},{"name":"Megan Maczko","avatar":""},{"name":"Helen Bradbury","avatar":""},{"name":"Sadie Frost","avatar":""},{"name":"Andy Davie","avatar":""},{"name":"Nathan Gambrill","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Gefesselt - Liebe. Ehre. Gehorsam.","爱、荣誉和服从","Deadly Virtues: Love.Honour.Obey.","Deadly Virtues: Love. Honour. Obey."]', 1784690324454);
