INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-den-toi', 'Ngày Đen Tối', 'A Hard Day', 'https://phimimg.com/upload/vod/20260210-1/dfa769b498522c49fb7684d6479b04ec.jpg', 'https://phimimg.com/upload/vod/20260210-1/d764103a2a3ac94b5bc32b8cdab7ab12.jpg', '<p>Thám tử Go Geon-soo đang có một ngày khó khăn, với các sự kiện liên tục xảy ra với anh ta trong ít hơn 24 giờ: Ông nhận được một thông báo ly hôn với vợ. Mẹ ông qua đời. Ông và các đồng nghiệp của ông đang được điều tra bởi các thanh tra cảnh sát trên bị cáo buộc biển thủ. Sau đó, trên đường đến đám tang của mẹ mình, anh lái xe thiếu thận trọng và đã gây tai nạn. Anh cố gắng che đậy vụ tai nạn bằng cách ẩn xác chết của người đàn ông trong quan tài mẹ quá cố của mình. Nhưng anh bắt đầu bị đe dọa bởi một người bí ẩn …</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-kyun","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Shin Jung-keun","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Heo Jung-eun","avatar":""},{"name":"Kim Dong-young","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Kim Bo-kyung","avatar":""},{"name":"Kim Kang-hyun","avatar":""},{"name":"Kim Hae-gon","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Bae Yu-ram","avatar":""},{"name":"Jang In-sub","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Jang Jun-nyeong","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["A Hard Day","Ggeut-gga-ji Gan-da","Kkeut-kka-ji-gan-da","Ggeutggaji Ganda","Ciężki dzień","O zi grea","Тяжёлый день","Težak dan","非常警探","A Hard Day（끝까지 간다）","A Hard Day KR","Kkeutkkaji ganda","끝까지 간다"]', 1784690324454);
