INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-den-toi', 'Ngày Đen Tối', 'A Hard Day', 'ngày đen tối a hard day lee sun-kyun cho jin-woong jeong man-sik shin jung-keun shin dong-mi heo jung-eun kim dong-young ju seok-tae park bo-gum lee ji-hoon kim bo-kyung kim kang-hyun kim hae-gon ki joo-bong bae yu-ram jang in-sub seo hyun-woo jang jun-nyeong l a hard day ggeut-gga-ji gan-da kkeut-kka-ji-gan-da ggeutggaji ganda ciężki dzień o zi grea тяжёлый день težak dan 非常警探 a hard day（끝까지 간다） a hard day kr kkeutkkaji ganda 끝까지 간다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-big-hero-6', 'Biệt Đội Big Hero 6', 'Big Hero 6', 'https://phimimg.com/upload/vod/20260210-1/1f8d848e3e37acc34468aa2261b1ce92.jpg', 'https://phimimg.com/upload/vod/20260210-1/5aac86bcc42b6fc61377d529280d51d9.jpg', '<p>Câu chuyện diễn ra tại một thành phố hư cấu có tên là San Fransokyo (tên viết tắt của 2 thành phố San Francisco của Mỹ và Tokyo của Nhật Bản). Đó là nơi ở của cậu bé thần đồng Hiro Hamada cùng với một người bạn hết sức đặc biệt là Baymax. Baymax trông giống như một người tuyết màu trắng, đây là phát minh của Tadashi – anh trai Hiro. Baymax được tạo ra nhằm mục đích phục vụ cho sức khỏe của con người. Với sự thông minh của Hiro, cậu nhóc đã chế tạo ra các công cụ chiến đấu cho biệt đội siêu anh hùng với sự đồng hành của 5 thành viên còn lại là Baymax, Wasabi, Go Go, Fred và Honey Lemon. Họ cùng điều tra về kẻ giấu mặt “kabuki” đã đánh cắp phát minh “bọ siêu nhỏ” của Hiro và ngăn chặn 1 thảm họa đối với thành phố.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2014, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Scott Adsit","avatar":""},{"name":"Ryan Potter","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Damon Wayans Jr.","avatar":""},{"name":"Genesis Rodriguez","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Katie Lowes","avatar":""},{"name":"Billy Bush","avatar":""},{"name":"Daniel Gerson","avatar":""},{"name":"Paul Briggs","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Marcella Lentz-Pope","avatar":""},{"name":"Dav","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Grandes Héroes","大英雄联盟","6 Giborim","Grandes héroes","6 kangelast","Les Nouveaux Heros","빅히어로","ベイマックス","Город героев","빅 히어로","שש גיבורים","שישה גיבורים","超能陆战队","6 Super Qəhrəman","Big Hero 6"]', 1784690324454);
