INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-goi-hon', 'Trò Chơi Gọi Hồn', 'Ouija', 'https://phimimg.com/upload/vod/20260128-1/8a56f5619f587eb57e793d87aa311a95.jpg', 'https://phimimg.com/upload/vod/20260128-1/9ec2fcffb4801ac14aad8030102c415b.jpg', '<p>Ouija vốn là một trò chơi tập thể, với đạo cụ là một miếng gỗ hình trái tim; một chiếc bàn phẳng có ghi các chữ cái, các con số và các ký hiệu thông dụng. Tất cả người chơi sẽ đặt tay lên miếng gỗ này, đọc to câu hỏi và chờ miếng gỗ di chuyển tới từng ký tự. Họ sẽ ghép các ký tự này lại, sau đó cùng nhau đoán câu trả lời mà “thế lực siêu nhiên” từ thế giới bên kia vừa cho họ biết. Trò chơi Ouija gây bí ẩn ở chỗ, những người chơi đều không tác động lực vào miếng gỗ, nhưng miếng gỗ vẫn có thể tự động di chuyển và chỉ ra các thông điệp có nghĩa. &nbsp;Khai thác yếu tố siêu nhiên và huyền bí của trò chơi này, bộ phim kinh dị OUIJA xoay quanh một nhóm bạn trẻ, những người vô tình đánh thức một hồn ma quyền năng trong chiếc bàn Ouija cổ. Và rồi, họ phải tự đương đầu với nỗi sợ hãi kinh hoàng liên tục tiếp diễn.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Daren Kagasoff","avatar":""},{"name":"Matthew Settle","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Ana Coto","avatar":""},{"name":"Shelley Hennig","avatar":""},{"name":"Bianca A. Santos","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Robyn Lively","avatar":""},{"name":"Sierra Hawkins","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Claudia Katz Minnick","avatar":""},{"name":"Afra Sophia Tully","avatar":""},{"name":"Izzie  Galanti","avatar":""},{"name":"Sunny May Allison","avatar":""},{"name":"Claire Beale","avatar":""},{"name":"Vivis Colombetti","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["死亡占卜","Ouija"]', 1784690324454);
