INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-kieu-chet-mien-vien-tay', 'Triệu Kiểu Chết Miền Viễn Tây', 'A Million Ways to Die in the West', 'https://phimimg.com/upload/vod/20260128-1/52841059d312f980f99137ab4590341d.jpg', 'https://phimimg.com/upload/vod/20260128-1/335f2902d20a409e6a609f9484d251ff.jpg', '<p>Nhân vật chính của phim là Albert (Seth MacFarlane), một anh chàng chăn cừu khù khờ, nhát gan luôn tìm cách né tránh mọi phiền phức và nguy hiểm, để đến nỗi bạn gái cũng bị người khác chiếm đoạt mất. Nhưng ngay khi định rời bỏ thị trấn để đi tìm cuộc sống mới thì định mệnh xui khiến anh dính vào Anna (Charlize Theron) bạn gái của một tên sát nhân đáng sợ nhất vùng. Hai người dần nảy sinh tình cảm thông qua nhiều tình huống vui nhộn, nhưng rắc rối lớn nhất vẫn đang đợi họ phía trước.</p>', 'Full', 1, 'single', 'completed', 37, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Seth MacFarlane","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Christopher Hagen","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Matt Clark","avatar":""},{"name":"Evan Jones","avatar":""},{"name":"Aaron McPherson","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Brett Rickaby","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"John Aylwar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["夺命西","百万种硬的方式","Un golpe de talento","奪命西","מיליון דרכים למות במערב","西部的一百万种死法","A Million Ways to Die in the West"]', 1784690324454);
