INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trieu-kieu-chet-mien-vien-tay', 'Triệu Kiểu Chết Miền Viễn Tây', 'A Million Ways to Die in the West', 'triệu kiểu chết miền viễn tây a million ways to die in the west seth macfarlane charlize theron amanda seyfried liam neeson giovanni ribisi neil patrick harris sarah silverman christopher hagen wes studi matt clark evan jones aaron mcpherson rex linn brett rickaby alex borstein ralph garman john aylwar 夺命西 百万种硬的方式 un golpe de talento 奪命西 מיליון דרכים למות במערב 西部的一百万种死法 a million ways to die in the west', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-godzilla-2014', 'Chúa Tể Godzilla', 'Godzilla', 'https://phimimg.com/upload/vod/20260123-1/9495dd4dde3902a5052d929483e4e2a7.jpg', 'https://phimimg.com/upload/vod/20260123-1/109b8d6d6328501722aafa769a0298ec.jpg', '<p>Trong năm 1954, một thí nghiệm hạt nhân tại đảo Bikini đưa đến việc thức tỉnh một loạt quái vật khổng lồ từ đại dương sâu. Hơn 40 năm sau, một vụ nổ tại nhà máy hạt nhân Janjira đẩy người dân vào cuộc chiến chống lại các sinh vật khủng khiếp, bao gồm cả Godzilla và MUTO. Ford, một sĩ quan Hải quân, cùng với các nhà nghiên cứu và lính của mình, đấu tranh để bảo vệ thế giới khỏi sự hủy diệt. Cuối cùng, nhờ sự hy sinh và quyết tâm của con người, Godzilla trỗi dậy như một biểu tượng của hy vọng và chiến thắng.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Al Sapienza","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"James Pizzinato","avatar":""},{"name":"CJ Adams","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Patrick Sabongui","avatar":""},{"name":"Carson Bolde","avatar":""},{"name":"Jared Keeso","avatar":""},{"name":"Luc Roderique","avatar":""},{"name":"Eri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Nautilus","Gojira","Godzilla","哥斯拉 (2014)","Годзилла","Godzilla 3D","Chúa Tể Godzilla","哥吉拉 2014","哥斯拉","G2014"]', 1784690324454);
