INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-mai-tinh-2', 'Để Mai Tính 2', 'Let Hoi Decide', 'https://phimimg.com/upload/vod/20260123-1/a32698da95d1b604f8f74303b5b3b23d.jpg', 'https://phimimg.com/upload/vod/20260123-1/8fe265f8cbf2898c813377e4976d47c6.jpg', '<p>Phim Để Mai Tính 2 (tên cũ: Để Hội Tính) của đạo diễn Charlie Nguyễn là phần ngoại truyện hài hước chưa kể của Để Mai Tính. Xoay quanh nhân vật Phạm Hương Hội (Thái Hòa). Từ một nhân vật phụ đã rất ấn tượng trong Để Mai Tính, nay còn tỏa sáng hơn với diện mạo mới, lý lịch mới, trong vai chính của phim Để Hội Tính. Là chủ tịch của một tập đoàn lớn, giàu có, nhưng Hội lại đem lòng yêu anh chàng họa sĩ phong trần tên Nam (Quang Sự). Dưới sự chỉ dẫn của trợ lý đắc lực (Huy Khánh), Hội đã &quot;giả trai&quot; để tiếp cận Nam. Nhưng Nam đang rất ngọt ngào bên người yêu Thư Lê (Diễm My 9x). Tan vỡ trong Để Mai Tính, liệu lần này Hội có chấp nhận tiếp tục thất bại trong tình yêu? Hội sẽ làm gì để loại bỏ tình địch Thư Lê và giành lấy tình yêu của mình?</p>', 'Full', 1, 'single', 'completed', 22, 2014, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Thái Hòa","avatar":""},{"name":"Kathy Uyen","avatar":""},{"name":"Johnny Nguyen","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Diễm My 9x","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"YaYa Trương Nhi","avatar":""},{"name":"Linh Sơn","avatar":""},{"name":"Quang Su","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["De Hoi Tinh","De Mai Tinh 2","Để Hoi Tính","호이가 결정할게","Để Mai Tính 2: Để Hội Tính","De Mai Tinh 2: De Hoi Tinh","De Mai Tinh II: De Hoi Tinh","Để Hội Tính","Để Mai Tính 2"]', 1784690324454);
