INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('de-mai-tinh-2', 'Để Mai Tính 2', 'Let Hoi Decide', 'để mai tính 2 let hoi decide thái hòa kathy uyen johnny nguyen lam thanh my hoàng phúc diễm my 9x huy khánh yaya trương nhi linh sơn quang su de hoi tinh de mai tinh 2 để hoi tính 호이가 결정할게 để mai tính 2: để hội tính de mai tinh 2: de hoi tinh de mai tinh ii: de hoi tinh để hội tính để mai tính 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xui-ma-hen', 'Xui Mà Hên', 'Xui Mà Hên', 'https://phimimg.com/upload/vod/20260123-1/4e75ded0f94131a38c5f868ff1826871.jpg', 'https://phimimg.com/upload/vod/20260123-1/842c43de4d584f3e95fea9dfe9bb5dd2.jpg', '<p>Hài hước pha chút lãng mạn, bộ phim giải trí này kể câu chuyện hên xui ly kỳ của một tay “lưu manh giả danh đầu bếp”.Vừa ra khỏi tù đã bị bọn chủ nợ giang hồ truy đuổi gắt gao, cùng đường, Thành lẩn trốn vào cuộc thi vua bếp và vô tình trúng tuyển. Món tiền thưởng khổng lồ, cộng với vẻ đẹp ngọt ngào của Hà, cô gái dễ thương trong ban tổ chức cuộc thi đã khiến Thành quyết chí ở lại thi thật. Nhưng làm sao một gã lưu manh chẳng biết tí gì về nấu nướng lại đang bị xã hội đen săn lùng có thể thắng cuộc thi Vua Bếp? Phim có sự tham gia của của Hà Hiền (phim “Bụi đời Chợ Lớn”), người đẹp Lan Ngọc (phim “Cánh đồng bất tận”, &quot;Trúng Số&quot;) và một dàn sao hài miền Nam: Hiếu Hiền, Đại Nghĩa, Thu Trang…</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Nguyễn Hậu","avatar":""},{"name":"Hà Hiền","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Phi Thanh Vân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Xui Mà Hên"]', 1784690324454);
