INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-shield-phan-2', 'Đội Đặc Nhiệm SHIELD (Phần 2)', 'Marvel''s Agents Of S.H.I.E.L.D. (Season 2)', 'https://phimimg.com/upload/vod/20260119-1/55f1530e6395098ad5ad90a1c747f913.jpg', 'https://phimimg.com/upload/vod/20260119-1/78866c691cc69c3396ad5cf88e319c98.jpg', '<p>Phil Coulson (Clark Gregg, lặp lại vai trò của mình từ &quot;The Avengers&quot; và &quot;Người sắt&quot;) đứng đầu một nhóm đặc vụ tinh nhuệ với tổ chức thực thi pháp luật trên toàn thế giới được gọi là SHIELD (Phòng Hậu cần và Thi hành Can thiệp Chiến lược Quê hương) sự xuất hiện kỳ lạ trên toàn cầu. Các thành viên của nhóm - mỗi người mang một đặc sản cho nhóm - làm việc với Coulson để bảo vệ những người không thể tự bảo vệ mình khỏi các mối đe dọa phi thường và không thể tưởng tượng được, bao gồm một nhóm đáng gờm được gọi là Hydra.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 14, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Clark Gregg","avatar":""},{"name":"Chloe Bennet","avatar":""},{"name":"Elizabeth Henstridge","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Henry Simmons","avatar":""},{"name":"Natalia Cordova-Buckley","avatar":""},{"name":"Jeff Ward","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marvel''s Agentes da S.H.I.E.L.D.","Agentes da SHIELD da Marvel","神盾局特工","Marvel: Agenti S.H.I.E.L.D.","Agenti S.H.I.E.L.D.","Agentes de S.H.I.E.L.D.","Agentes de SHIELD","Marvel''s Agents of S.H.I.E.L.D","Marvel - Les Agents du SHIELD","შილდის აგენტები","A SHIELD ügynökei","סוכני שילד","ماموران شیلد","에이전트 오브 쉴드","Agenci T.A.R.C.Z.Y.","Os Agentes S.H.I.E.L.D.","S.H.I.L.E.D Ajanları","Agents of SHIELD","Agents of S.H.I.E.L.D.","Agents of S H I E L D","Marvel''s Agents of S.H.I.E.L.D."]', 1784690324454);
