INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-kinh-di-my-phan-4-freak-show', 'Truyện Kinh Dị Mỹ (Phần 4) (Freak Show)', 'American Horror Story (Season 4)', 'https://phimimg.com/upload/vod/20260118-1/b607e820c16b1f097d044428ed4aac06.jpg', 'https://phimimg.com/upload/vod/20260118-1/2391a0af195d878cec771d166683a794.jpg', '<p>Truyện kinh dị Mỹ (tựa gốc: American Horror Story) là loạt phim truyền hình nhiều tập ngắn kinh dị của Mỹ được sản xuất bởi Ryan Murphy và Brad Falchuk. Được biên kịch dưới dạng series, mỗi mùa được sản xuất dưới dạng phim truyền hình ngắn, khoảng 12 tập. Sau mỗi mùa, bối cảnh, cũng như các nhân vật được thay mới hoàn toàn, kể cả với các diễn viên từng tham gia mùa trước nên các mùa phim có cốt truyện độc lập với nhau, sở hữu cao trào và kết thúc riêng. Một số yếu tố trong phim lấy cảm hứng từ những câu chuyện và nhân vật có thật.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 12, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emma Roberts","avatar":""},{"name":"Matt Czuchry","avatar":""},{"name":"Kim Kardashian","avatar":""},{"name":"Annabelle Dexter-Jones","avatar":""},{"name":"Michaela Jaé Rodriguez","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"Julie White","avatar":""},{"name":"Maaz Ali","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["História de Horror Americana","Uma História de Horror Americana","美恐","Ameri