INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nhu-2014', 'Mồi Nhử', 'Cold in July', 'https://phimimg.com/upload/vod/20260109-1/bb73e98c23a295d607882453056df24d.jpg', 'https://phimimg.com/upload/vod/20260109-1/0910e7b1ed441dd48c53792c1bc6fd6e.jpg', '<p>Là một bộ phim tội phạm Mỹ của đạo diễn Jim Mickle. Một quyết định thứ hai có thể thay đổi cuộc sống của bạn? Trong lúc tìm hiểu tiếng động trong nhà mình vào một đêm mát mẻ ở Texas 1989, Richard Dane bắn chết một tên trộm thấp kém, Freddy Russell. Được tôn lên như một anh hùng trong thị trấn, Dane nhận ra sự an toàn của gia đình mình bị đặt trong vòng nguy hiểm khi cha của Freddy, một cựu tù binh có mặt ở thành phố. Một thời gian ngắn sau khi Dane giết chết kẻ đột nhập, anh bắt đầu phát hiện một thế giới ngầm đầy rẫy tham nhũng và bạo lực. Mạng sống của Dane ngày càng trở nên mong manh.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Michael C. Hall","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Nick Damici","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Lanny Flaherty","avatar":""},{"name":"Brianda Agramonte","avatar":""},{"name":"Tim Lajcik","avatar":""},{"name":"Brogan Hall","avatar":""},{"name":"Ken Holmes","avatar":""},{"name":"Rachel Zeiger-Haag","avatar":""},{"name":"Kristin Griffith","avatar":""},{"name":"Laurent Rejto","avatar":""},{"name":"Joe Lanza","avatar":""},{"name":"Kris Eivers","avatar":""},{"name":"Happy Anderson","avatar":""},{"name":"Josep","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Frío en julio","Frío en Julio",