INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-on-dich', 'Hàng Xóm Ôn Dịch', 'Neighbors', 'https://phimimg.com/upload/vod/20260108-1/552bfb4a822dbd570df55353b2b48c2e.jpg', 'https://phimimg.com/upload/vod/20260108-1/9d32c5e059aed3c39d1c508674df3d8a.jpg', '<p>Bộ phim là một chuỗi bi hài kịch khi một cặp vợ chồng vừa ra tù đang buộc phải phục hồi cuộc sống lại chuyển đến ở cạnh một nhà ký túc xá chung của đám sinh viên đại học quậy phá ngất trời trong lúc họ đang có đứa con mới sinh. Một “trận chiến” diễn ra giữa những người hàng xóm mà không bên nào chịu thua bên nào nổ ra vừa hài hước vừa gay cấn...</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Jerrod Carmichael","avatar":""},{"name":"Ike Barinholtz","avatar":""},{"name":"Carla Gallo","avatar":""},{"name":"Halston Sage","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Elise Vargas","avatar":""},{"name":"Zoey Vargas","avatar":""},{"name":"Brian Huskey","avatar":""},{"name":"Ali Cobrin","avatar":""},{"name":"Kira Sternbach","avatar":""},{"name":"Steven Michael Eich","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Townies","Bad Neighbours","贱邻50","Neighbors 1","Böse Nachbarn","Bad Neighbours 1","Buenos vecinos","Pis Qonşular","Nos pires voisins","Vizinhos","Да разлаем съседите","Neighbors","Les voisins","Susjedi iz pakla","Sousedi","Naapurit","Anypoforoi geitones","Ανυπόφοροι γείτονες","Rossz szomszédság","Shkhenim","Cattivi vicini","ネイバーズ