INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hang-xom-on-dich', 'Hàng Xóm Ôn Dịch', 'Neighbors', 'hàng xóm ôn dịch neighbors seth rogen zac efron rose byrne dave franco christopher mintz-plasse jerrod carmichael ike barinholtz carla gallo halston sage craig roberts lisa kudrow elise vargas zoey vargas brian huskey ali cobrin kira sternbach steven michael eich a townies bad neighbours 贱邻50 neighbors 1 böse nachbarn bad neighbours 1 buenos vecinos pis qonşular nos pires voisins vizinhos да разлаем съседите neighbors les voisins susjedi iz pakla sousedi naapurit anypoforoi geitones ανυπόφοροι γείτονες rossz szomszédság shkhenim cattivi vicini ネイバーズ sliktie kaimiņi kaimynai соседи sąsiedzi má vizinhança vecini de cosmar соседи. на тропе войны лоше комшије susedia na odstrel sosedi malditos vecinos 惡鄰纏身 kötü komşular сусіди qo''shnilar', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-song-phan-5', 'Xác Sống (Phần 5)', 'The Walking Dead (Season 5)', 'https://phimimg.com/upload/vod/20250917-1/2f5dbc996cc525e4ae19202fb7653846.jpg', 'https://phimimg.com/upload/vod/20250917-1/8435b189952499ad9dc22701c02dc3aa.jpg', '<p>Loạt phim xoay quanh nhân vật do nam diễn viên Andrew Lincoln thủ vai chính là phó cảnh sát trưởng Rick Grimes, người đã tỉnh dậy sau một khoảng thời gian hôn mê và nhận ra rằng thế giới đã bước vào thời kỳ hậu tận thế với sự xuất hiện tràn lan của thây ma ăn thịt. Anh lên đường tìm kiếm gia đình mình và gặp được nhiều người vẫn còn sống sót trên đường đi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Cohan","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Melissa McBride","avatar":""},{"name":"Christian Serratos","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Ross Marquand","avatar":""},{"name":"Josh McDermitt","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Cooper Andrews","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Cailey Fleming","avatar":""},{"name":"Lauren Ridloff","avatar":""},{"name":"Eleanor Matsuura","avatar":""},{"name":"Nadia Hilker","avatar":""},{"name":"Cassady McC","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-l