INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('archer-phan-5', 'Archer (Phần 5)', 'Archer (Season 5)', 'archer (phần 5) archer (season 5) h. jon benjamin judy greer amber nash chris parnell aisha tyler lucky yates 间谍亚契 archer: vice archer: dreamland archer: danger island archer: 1999 archer: into the cold archer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-tinh-thu', 'Ký Ức Tình Thù', 'Sanaeha Sunya Kaen', 'https://phimimg.com/upload/vod/20251220-1/afa165ea7cc3fba3b6883c196566ab55.jpg', 'https://phimimg.com/upload/vod/20251220-1/7597f93ba457f13853a6a699cc0dfc15.jpg', '<p>Kin, chủ tịch giàu có của tập đoàn KTK vừa kết hôn với người bạn gái lâu năm 7 năm của mình, Ganok. Vào đêm tân hôn của họ, cô dâu, Ganok nhận ra rằng cô đã quên mang một món quà cưới mà cô đã làm cho Kin. Cô ấy vội vàng về nhà để lấy. Trong khi đó, một cô gái trẻ tên Tawan vừa rời sân bay sau khi phát hiện ra rằng vị hôn phu lâu năm của mình đã lừa dối cô, làm một người phụ nữ khác mang thai với anh ta và phá vỡ hôn ước của họ. Tawan đã thết lòng ủng hộ vị hôn phu của mình về tài chính và tình cảm trong nhiều năm, hy sinh bản thân mình, cuối cùng phát hiện ra rằng anh ta đã lợi dụng cô trong suốt thời gian qua. Tawan, đau đớn và tan nát trái tim, đi bộ về nhà trong mưa, nhưng khi băng qua đường thì bị xe của Ganok đâm phải. Sau vụ tai nạn, Tawan phải nhập viện, nhưng Ganok được cho là đã chết. Kin thất vọng vì vừa mất đi tình yêu của đời mình, mới cưới chưa được một đêm. Kin yêu cầu được biết ai đã gây ra vụ tai nạn xe hơi của vợ mình. Khi phát hiện ra thân phận của Tawan, anh thề sẽ làm mọi thứ trong khả năng của mình để trả thù Tawan. Tawan vô tình rơi ngay vào bẫy của anh khi cô ký hợp đồng làm y tá cho em gái Kin. Liệu tình yêu của Kin dành cho Tawan có khiến anh thoát khỏi sự tức giận và lòng thù hận ấy, hay anh sẽ bị mong muốn trả thù lấn át?</p>', 'Tập 3', 15, 'series', 'ongoing', 18, 2014, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pakorn Lam","avatar":""},{"name":"Janie Tienphosuwan","avatar":""},{"name":"Kan Kantathavorn","avatar":""},{"name":"Sarunrat Visutthithada","avatar":""},{"name":"Thongpoom Siripipat","avatar":""},{"name":"Pimnipa Jittateeraroj","avatar":""},{"name":"Aom Atthaneeya Eamvasant","avatar":""},{"name":"Akwin Akkarawanit","avatar":""},{"name":"Nattarinee Jiarawanon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sanay Ha Sanya Kaen","Bittersweet Promise of Revenge","เสน่หาสัญญาแค้น"]', 1784690324454);
