INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-duoi-ong-gia-noel', 'Truy Đuổi Ông Già Noel', 'Get Santa', 'truy đuổi ông già noel get santa jim broadbent rafe spall warwick davis jodie whittaker stephen graham joanna scanlan kit connor joshua mcguire ewen bremner hera hilmar nonso anozie perry benson matt king bjarne henriksen mick walter brian bovell simon kunz graham hughes s.o.s. natale tomte i knipa à la rescousse du père noël que fim levou papai noel? uwolnić mikołaja ゲット・サンタ noël en cavale rettet weihnachten! salven a santa достать санту deda mraz iza rešetaka ujemi bozicka get santa', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-tinh-duc-phan-2', 'Bậc Thầy Tình Dục (Phần 2)', 'Masters Of Sex (Season 2)', 'https://phimimg.com/upload/vod/20251116-1/2a39850db97bbb46abcbd3ac02ad7179.jpg', 'https://phimimg.com/upload/vod/20251116-1/a3f13be4adcc8cf8c9762e1e0026c2a2.jpg', '<p>Phim tái hiện cuộc đời và sự nghiệp chông gai và đầy tranh cãi của William Masters và Virginia Johnson, hai nhà nghiên cứu tiên phong trong lĩnh vực tình dục. Năm 1956, William Masters, một nhà nghiên cứu tại Đại học Washington, đề xuất một nghiên cứu gây tranh cãi về tình dục con người nhưng bị từ chối. Mặc dù thế, ông vẫn quyết định tiếp tục tiến hành nghiên cứu và thuê Virginia Johnson làm trợ lý. Tuy chỉ là một người mẹ đơn thân không bằng cấp, Virginia lại là một trợ thủ vô cùng đắc lực cho William và cùng ông góp công &quot;khai sáng&quot; một lĩnh vực mà tưởng chừng như sẽ mãi mãi là một bí ẩn với con người.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Sheen","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Caitlin FitzGerald","avatar":""},{"name":"Annaleigh Ashford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Експерти по секс","마스터스 오브 섹스","Masters of Sex"]', 1784690324454);
