INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ma-ca-rong', 'Học Viện Ma Cà Rồng', 'Vampire Academy', 'https://phimimg.com/upload/vod/20251114-1/e8e5f0be8b6305094ce73cfcaabd3651.jpg', 'https://phimimg.com/upload/vod/20251114-1/bf3c45e3e04bb421c652fb3bd2141eb7.jpg', '<p>Rose, một người giám hộ tập sự nửa ma cà rồng / nửa người nổi loạn và người bạn thân nhất của cô, Lissa - một Công chúa ma cà rồng hoàng gia phàm trần - đã chạy trốn khi họ bị bắt và trở về Học viện St. nơi mà họ tin rằng cuộc sống của họ có thể gặp nguy hiểm nhất. Rose sẽ hy sinh tất cả để bảo vệ Lissa khỏi những kẻ có ý định lợi dụng cô từ bên trong các bức tường của Học viện và Strigoi (ma cà rồng bất tử, độc ác), những kẻ săn lùng đồng loại của cô từ bên ngoài khu bảo tồn.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zoey Deutch","avatar":""},{"name":"Lucy Fry","avatar":""},{"name":"Danila Kozlovsky","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Dominic Sherwood","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Sami Gayle","avatar":""},{"name":"Ashley Charles","avatar":""},{"name":"Claire Foy","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Dominique Tipper","avatar":""},{"name":"Edward Holcroft","avatar":""},{"name":"Bronté Norman-Terrell","avatar":""},{"name":"Chris Mason","avatar":""},{"name":"Ben","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Vampire Academy: Blood Sisters","Академия вампиров: Сёстры по