INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-ky-dam', 'Cổ Kiếm Kỳ Đàm', 'Swords Of Legends', 'https://phimimg.com/upload/vod/20250621-1/339b44bcf91b0630a1ff2f92767b5a71.jpg', 'https://phimimg.com/upload/vod/20250621-1/432533fbb1fd93e1149e5386cd12a376.jpg', '<p>Bộ phim cổ trang tiên hiệp này được chuyển thể từ game. Đệ tử của Tử Dận là Bách Lý Đồ Tô trong người có mang một luồng sát khí thần bí, phải nhờ tới Phần Tịch kiếm để áp chế. Anh quen với Âu Dương Thiếu Cung và Phương Lan Sinh. Thiếu Cung là đệ tử Thanh Ngọc đàn. Trưởng lão Lôi Nghiêm soán vị, Thiếu Cung trốn ra tìm Ngọc Hoành. Bởi Thiếu Cung đang luyện thuốc khởi tử hoàn sinh nên Đồ Tô hy vọng có thể dựa vào đó cứu sống mẹ, mới cùng đi với Thiếu Cung. Trên đường đi tìm Ngọc Hoành, Đồ Tô còn quen biết Phong Tình Tuyết và một con hồ ly hình người là Tương Linh. Hồng Ngọc được Tử Dận sai khiến bí mật bảo vệ Đồ Tô.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 15, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Lý Dịch Phong","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Chung Hân Đồng","avatar":""},{"name":"Trần Vỹ Đình","avatar":""},{"name":"Trịnh Sảng","avatar":""},{"name":"Mã Thiên Vũ","avatar":""},{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Cao Vỹ Quang","avatar":""},{"name":"Trương Trí Nghiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Gu Jian Qi Tan","고검기-담","Legend of the Ancient Sword","Ancient Sword Fantasy","Swords of Legends","古剑奇谭"]', 1784690324454);
