INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-kiem-ky-dam', 'Cổ Kiếm Kỳ Đàm', 'Swords Of Legends', 'cổ kiếm kỳ đàm swords of legends dương mịch lý dịch phong kiều chấn vũ chung hân đồng trần vỹ đình trịnh sảng mã thiên vũ địch lệ nhiệt ba cao vỹ quang trương trí nghiêu gu jian qi tan 고검기-담 legend of the ancient sword ancient sword fantasy swords of legends 古剑奇谭', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-ngoc-luong-duyen', 'Kim Ngọc Lương Duyên', 'Perfect Couple', 'https://phimimg.com/upload/vod/20251107-1/aa7f8c2106d1c96756d31dbd392448aa.jpg', 'https://phimimg.com/upload/vod/20251107-1/ccd156211776e83ed19c147a7fd2a630.jpg', '<p>Vào thời nhà Minh, Ngọc Kỳ Lân đến thủ đô một mình mang theo tín vật của mẹ nuôi và tình cờ gặp Kim Nguyên Bảo, con trai của nhà họ Kim. Hai người đã có một cuộc cãi vã và họ vô tình biết được Cố Mẫu là người duy nhất biết mẹ nuôi của cô ấy đã bị hãm hại. Giang Hiểu Tuyên, con gái lớn của gia đình họ Giang, do thái hậu bang hôn với Kim Nguyên Bảo, nhưng cô đã trốn thoát khỏi cuộc hôn nhân vì sự hỗn loạn và được Cố Trường Phong cứu. Để xác nhận danh tính của Kim Nguyên Bảo, Ngọc Kỳ Lân kết hôn thay với gia đình họ Kim và trở thành một cặp vợ chồng hạnh phúc với Kim Nguyên Bảo. Cuối cùng, danh tính của Kim Nguyên Bảo đã được xác nhận, thân phận hôn nhân thay thế của Ngọc Kỳ Lân bị vạch trần, và những việc làm xấu xa của Kim phu nhân cũng bị vạch trần. Kim Nguyên Bảo nhất thời không thể chấp nhận điều đó và rời khỏi Kim phủ. Gia đình Kim gia gặp phải khủng hoảng, Ngọc Kỳ lân không bao giờ rời bỏ Kim Nguyên Bảo, cuối cùng sự thật cũng được đưa ra ánh sáng, Kim phu nhân đã ăn năn hối cải và cả gia đình bắt đầu một cuộc sống mới.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 10, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Yên","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Hoàng Minh","avatar":""},{"name":"Cống Mễ","avatar":""},{"name":"Ổ Quân Mai","avatar":""},{"name":"Vương Dương","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Jin Yu Liang Yuan","Perfect Couple","金玉良缘"]', 1784690324454);
