INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-dinh', 'Tiền Định', 'Predestination', 'https://phimimg.com/upload/vod/20251028-1/3f02b677f80d708104342747ebfc654f.jpg', 'https://phimimg.com/upload/vod/20251028-1/059705a3eadba29c8e64e84472f10c96.jpg', '<p>Một mật vụ phải quay trở về quá khứ để ngăn chặn một tên khủng bố. Anh đóng giả làm một nhân viên quán bar nhằm thu thập thông tin về kẻ đánh bom. Một hôm, anh ta gặp một vị khách tên John. Người này cá cược với tay mật vụ rằng anh ta có thể kể một câu chuyện khó tin nhất trên đời, phần thưởng sẽ là 1 chai rượu. &nbsp;Thế rồi John bắt đầu kể câu chuyện cuộc đời mình, rằng trước kia anh ta là một cô gái tên Jane, trải qua muôn vàn chuyện lớn nhỏ và rồi trở thành người đàn ông John. Sau đó là một cuộc hành trình dài và xoắn não khi John được tay mật vụ trao cho cơ hội thay đổi quá khứ của chính mình...</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Sarah Snook","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Christopher Kirby","avatar":""},{"name":"Madeleine West","avatar":""},{"name":"Jim Knobeloch","avatar":""},{"name":"Freya Stafford","avatar":""},{"name":"Elise Jansen","avatar":""},{"name":"Tyler Coppin","avatar":""},{"name":"Christopher Stollery","avatar":""},{"name":"Christopher Sommers","avatar":""},{"name":"Kuni Hashimoto","avatar":""},{"name":"Sara El-Yafi","avatar":""},{"name":"Paul Moder","avatar":""},{"name":"Grant Piro","avatar":""},{"name":"Christopher Bunworth","avatar":""},{"name":"Jam","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宿命论","逆時空狙擊","P4trul Vremeni","Preodredište","Predestination - Entführung in die Zukunft","El Viajero del Tiempo","プリデスティネーション 2014","前目的地","Predestination"]', 1784690324454);
