INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-dinh', 'Tiền Định', 'Predestination', 'tiền định predestination ethan hawke sarah snook noah taylor christopher kirby madeleine west jim knobeloch freya stafford elise jansen tyler coppin christopher stollery christopher sommers kuni hashimoto sara el-yafi paul moder grant piro christopher bunworth jam 宿命论 逆時空狙擊 p4trul vremeni preodredište predestination - entführung in die zukunft el viajero del tiempo プリデスティネーション 2014 前目的地 predestination', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-2014', 'Bạn Thân', 'Girls', 'https://phimimg.com/upload/vod/20251028-1/ef2464d2d38af21458e5c543c04eed3e.jpg', 'https://phimimg.com/upload/vod/20251028-1/3eafb8d8d1a86fa15bae3acfd5a43a45.jpg', '<p>Ba cô gái Hy Vân, Kimmy và Tiểu Mỹ là những người bạn thân không có bí mật nào giấu nhau. Sau khi tốt nghiệp đại học, ba người quyết định sống chung.Cô gái ngoan hiền Hy Vân dành toàn bộ cuộc sống cho người bạn trai đã yêu suốt bảy năm là Lâm Kiệt, nhưng khi phát hiện anh ta ngoại tình, cuộc sống của cả ba người bạn bị đảo lộn.Cô nàng tiểu thư Kimmy mê đàn ông và cô gái cá tính Tiểu Mỹ phải ngày đêm chăm sóc Hy Vân đang suy sụp vì thất tình — nhưng nỗ lực của họ cũng không bằng sự xuất hiện của chàng trai ấm áp Kiều Lập, người luôn ở bên an ủi cô. Khi Hy Vân bắt đầu nghi ngờ về xu hướng tình dục của Kiều Lập, thì Kimmy và Tiểu Mỹ lại vướng vào một mối tình tay ba rắc rối với nam ca sĩ nhạc rock Cửu Thiên.Khi Cửu Thiên sang châu Âu lưu diễn, chuyện tình của họ trở nên căng thẳng. Hy Vân và Kimmy đều phản đối Tiểu Mỹ tiếp tục mối quan hệ này, nhưng nếu cô muốn đi theo Cửu Thiên, cô sẽ phải từ bỏ công việc trợ lý đạo diễn hiện tại.Tình bạn giữa ba cô gái đứng trước bờ vực tan vỡ — và Tiểu Mỹ phải đưa ra lựa chọn cuối cùng cho chính mình.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Ý Hàm","avatar":""},{"name":"Tiếp Khải Kỳ","avatar":""},{"name":"Dương Tử San","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Dư Văn Lạc","avatar":""},{"name":"Ngô Kiến Hào","avatar":""},{"name":"Hoàng Xán Xán","avatar":""},{"name":"An Hựu Kỳ","avatar":""},{"name":"Lý Hiền Tể","avatar":""},{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Trần Hiểu Đông","avatar":""},{"name":"Trần Đình Ni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["閨密","Gwaimat","Guimi","Girls","闺蜜"]', 1784690324454);
