INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-than-2014', 'Bạn Thân', 'Girls', 'bạn thân girls trần ý hàm tiếp khải kỳ dương tử san chung hán lương dư văn lạc ngô kiến hào hoàng xán xán an hựu kỳ lý hiền tể nhậm hiền tề trần hiểu đông trần đình ni 閨密 gwaimat guimi girls 闺蜜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mang', 'Đổi Mạng (Giải Cứu Con Tin)', 'The Target', 'https://phimimg.com/upload/vod/20251023-1/3cbbc0ae26e5cf20a50ffff7f29ee487.jpg', 'https://phimimg.com/upload/vod/20251023-1/fcac630aa2b4d74b99d27e4c77e071f3.jpg', '<p>Phim xoay quanh một lính đánh thuê chuyên nghiệp, Yeo-hoon, người đang có một cuộc sống bình thường. Trong một ngày đi làm tại văn phòng, anh đã nhìn thấy một người đàn ông bị sát hại. Những kẻ giết người cũng tấn công và đuổi Yeo-hoon, anh bị bắn và đưa đến bệnh viện. Người đàn ông bị sát hại được xác định là một nhà lãnh đạo doanh nghiệp cấp cao và Yeo-hoon sẽ trở thành nghi phạm chính. Tại đây anh đã bắt đầu hành trình minh oan cho bản thân và bắt đầu hành trình giải cứu một con tin tình cờ dính vào vụ án giết người bí ẩn này.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Lee Jin-uk","avatar":""},{"name":"Yu Jun-sang","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Cho Yeo-jeong","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Cho Eun-ji","avatar":""},{"name":"Lee Hyun-wook","avatar":""},{"name":"Kim Dae-myung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["표적","Pyo-jeok","Pyojeok","The Target"]', 1784690324454);
