INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-danh-thue-3', 'Biệt Đội Đánh Thuê 3', 'The Expendables 3', 'biệt đội đánh thuê 3 the expendables 3 sylvester stallone jason statham harrison ford arnold schwarzenegger mel gibson wesley snipes dolph lundgren randy couture terry crews kelsey grammer glen powell antonio banderas victor ortiz ronda rousey kellan lutz jet li ivan kostadinov lý liên kiệt 浴血任务3 the expendables 3 - a man''s job the expendables - a feláldozhatók 3. the expendables iii 轟天猛將3 неудержимые 3 los mercenarios: 3 cəhənnəm mələkləri 3 os mercenários 3 the expendables 3', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chim-2014', 'Người Chim', 'Birdman', 'https://phimimg.com/upload/vod/20251010-1/0c5cfacc1060023fcd91a10c3c9297d2.jpg', 'https://phimimg.com/upload/vod/20251010-1/80aa012b1991a01f29755321896feb97.jpg', '<p>Bộ phim là tác phẩm thể nghiệm châm biếm của đạo diễn Alejandro González Iñárritu, kể về một ngôi sao hết thời tìm cách lấy lại hào quang. Tác phẩm ra mắt lần đầu ở LHP Venice hồi tháng 8/2014 đến nay mang về nhiều giải thưởng đáng kể, trong đó có “Nam diễn viên chính xuất sắc trong phim hài/nhạc kịch” dành cho Michael Keaton tại Quả Cầu Vàng 2015.&quot;Người Chim&quot; là bộ phim đang được gây chú ý nởi nội dung mới lạ và dàn diễn viên tài năng. Nhân vật chính trong phim là Riggan Thomson - một diễn viên nổi đình đám với vai diễn Người chim. Thế nhưng sự nghiệp của anh giờ đã không còn ở thời kì đỉnh cao nữa nên ông luôn tìm mọi cách để lấy lại phong độ cũng như vinh quang của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Merritt Wever","avatar":""},{"name":"Jeremy Shamos","avatar":""},{"name":"Damian Young","avatar":""},{"name":"Kenny Chin","avatar":""},{"name":"Jamahl Garrison-Lowe","avatar":""},{"name":"Katherine O''Sullivan","avatar":""},{"name":"Keenan Shimizu","avatar":""},{"name":"Akira Ito","avatar":""},{"name":"Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Birdman","Birdman avagy a mellőzés meglepő ereje","Birdman - The Unexpected Virtue of Ignorance","Birdman ou (A Inesperada Virtude da Ignorância)","Birdman o la inesperada virtud de la ignorancia","버드맨","Birdman o (La inesperada virtud de la ignorancia)","Birdman - o (L''imprevedibile virtù dell''ignoranza)","בירדמן או (היתרון הבלתי צפוי של הבורות)","Birdman or (The Unexpected Virtue of Ignorance)"]', 1784690324454);
