INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-me-2014', 'Tình Mẹ', 'Mama', 'https://phimimg.com/upload/vod/20251007-1/067fec53014db10174e078c36f8b3ccc.jpg', 'https://phimimg.com/upload/vod/20251007-1/407b6a9945278d99299f62b3d902d5e2.jpg', '<p>Seung Hee là một người mẹ đơn thân chỉ lo kiếm tiền mà bỏ bê việc chăm sóc cậu con trai Geu Ru. Đến khi nhận được tin mình mắc bệnh nan y và không còn sống được bao lâu nữa, cô mới quyết tâm dành hết khoảng thời gian còn lại ở bên con mình. Không những thế, Seung Hee còn phải gạt bỏ hận thù để tìm lại bố của Geu Ru, người đàn ông từng bỏ rơi cô trước kia, và nghĩ cách thuyết phục gia đình mới của anh thu nhận con trai mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2014, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hong Jong-hyun","avatar":""},{"name":"Jung Jun-ho","avatar":""},{"name":"Choi Song-hyun","avatar":""},{"name":"Song Yun-ah","avatar":""},{"name":"Park Seo-jun","avatar":""},{"name":"Yoon Chan-young","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Hyun Jyu-ni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["妈妈·无所畏惧","Mama - Sesang Museoul Ge Eobsneun","Mama - Fearless of Anything in the World","Mama - Nothing to Fear","마마"]', 1784690324454);
