INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-nha-ben', 'Cô Bé Nhà Bên', 'A Girl At My Door', 'https://phimimg.com/upload/vod/20251003-1/518c2f9358263b6f68e389a577eaeae1.jpg', 'https://phimimg.com/upload/vod/20251003-1/98d76db52f2b9af69a9fbc5886ce91d2.jpg', '<p>Bộ phim nói về nạn bạo lực gia đình. Nội dung phim xoay quanh thiếu nữ 14 tuổi Seon Do Hee bị cha dượng bạo hành và nữ cảnh sát Lee Young Nam là ân nhân của cô bé. Young Nam đã che chở và giúp đỡ Do Hee nhưng cô không thể ngờ rằng chính mình cũng là nạn nhân của cha dượng Do Hee.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bae Doona","avatar":""},{"name":"Kim Sae-ron","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Kim Jin-goo","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Na Jong-min","avatar":""},{"name":"Gong Myoung","avatar":""},{"name":"Kim Jong-goo","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Jang Hee-jin","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Jo Yoo-jin","avatar":""},{"name":"Park Chan-guk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Dohee-ya","屋簷下的她","Dohui-ya","Otwórz mi drzwi","私の少女：2014","A Girl at My Door","道熙啊","道熙呀","Un monstruo en mi puerta","Una chica en mi puerta","도희야"]', 1784690324454);
