INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-be-nha-ben', 'Cô Bé Nhà Bên', 'A Girl At My Door', 'cô bé nhà bên a girl at my door bae doona kim sae-ron song sae-byuk kim jin-goo son jong-hak na jong-min gong myoung kim jong-goo park jin-woo moon sung-keun jang hee-jin kim min-jae lee jung-eun nam moon-chul jo yoo-jin park chan-guk dohee-ya 屋簷下的她 dohui-ya otwórz mi drzwi 私の少女：2014 a girl at my door 道熙啊 道熙呀 un monstruo en mi puerta una chica en mi puerta 도희야', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-binh-dai-ngan-ha', 'Vệ Binh Dải Ngân Hà', 'Guardians Of The Galaxy', 'https://phimimg.com/upload/vod/20250917-1/8de87cccdf95840172aef9aedf2feee2.jpg', 'https://phimimg.com/upload/vod/20250917-1/4725f099f5f9befff465063c1752a2bc.jpg', '<p>Phim nói về một phi công phản lực được bị mắc kẹt trong không gian, và anh phải đoàn kết một nhóm người ngoài hành tinh để tạo thành một đội quân đủ khả năng đánh bại các mối đe dọa từ vũ trụ. Phim có sự tham gia diễn xuất của Karen Gillan, Bradley Cooper, Zoe Saldana… và sự chỉ đạo của đạo diễn James Gunn.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Laura Haddock","avatar":""},{"name":"Sean Gunn","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Krystian Godlew","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["G.O.T.G.","Marvel''s Guardians of the Galaxy","마블 가디언즈 오