INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ve-binh-dai-ngan-ha', 'Vệ Binh Dải Ngân Hà', 'Guardians Of The Galaxy', 'vệ binh dải ngân hà guardians of the galaxy chris pratt zoe saldaña dave bautista vin diesel bradley cooper lee pace michael rooker karen gillan djimon hounsou john c. reilly glenn close benicio del toro laura haddock sean gunn peter serafinowicz christopher fairbank krystian godlew g.o.t.g. marvel''s guardians of the galaxy 마블 가디언즈 오브 갤럭시 marvel studios'' guardians of the galaxy 银河护卫队 guardians of the galaxy: vệ binh dải ngân hà guardians of the galaxy vol. 1 les gardiens de la galaxie guardiões da galáxia da marvel studios שומרי הגלאקסיה: חלק 1 การ์เดี้ยนส์ ออฟ เดอะ กาแล็กซี่ รวมพันธุ์นักสู้พิทักษ์จักรวาล գալակտիկայի պահապանները guardianes de la galaxia - volumen 1 星際異攻隊 ガーディアンズ・オブ・ギャラクシー ガーディアンズ・オブ・ギャラクシー：2014 銀河守護隊 guardians of the galaxy 1 стражи галактики. часть 1 galaksinin koruyucuları حراس المجرة guardians of the galaxy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ac-doi-dau-2014', 'Thiện Ác Đối Đầu', 'The Equalizer', 'https://phimimg.com/upload/vod/20250701-1/6273a86bd779a135f3f9e83dbf03422d.jpg', 'https://phimimg.com/upload/vod/20250701-1/bea2aa69b978afe33f73e5e0b723888b.jpg', '<p>McCall đã đặt quá khứ bí ẩn của mình sau lưng và tận tâm sống một cuộc sống mới yên ả. Nhưng khi anh gặp Teri, một cô gái trẻ chịu sự điều khiển của những tên xã hội đen Nga cực kỳ hung bạo, anh không thể khoanh tay đứng nhìn. Được trang bị những kỹ năng tiềm ẩn cho phép anh báo thù chống lại bất kỳ ai muốn tàn bạo những người yếu thế, McCall không còn rửa tay gác kiếm và tìm thấy khát vọng về công lý của mình. Nếu ai đó gặp khó khăn, bị thế giới chống lại, không còn nơi nào để nhờ cậy, McCall sẽ giúp. Anh ấy là Thiện ác đối đầu.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Haley Bennett","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"David Meunier","avatar":""},{"name":"Johnny Skourtis","avatar":""},{"name":"Alex Veadov","avatar":""},{"name":"Vladimir Kulich","avatar":""},{"name":"E. Roger Mitchell","avatar":""},{"name":"James Wilcox","avatar":""},{"name":"Mike O''Dea","avatar":""},{"name":"Anastasia Mousis Sanidopoulos","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a