INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-min-woo-den', 'Ngày Min Woo Đến', 'Awaiting', 'https://phimimg.com/upload/vod/20250913-1/68d9314fbe6554619a47eeff7225a0c1.jpg', 'https://phimimg.com/upload/vod/20250913-1/ff23c3d006ee6fadd0b6b82dcd7d75e7.jpg', '<p>Một cô gái trẻ tên Yeon-hee đang trên chuyến xe đến Bình Nhưỡng cùng nhiều cụ già. Khi lật xem lại những tấm ảnh cũ, cô nhớ về lần từng nói với chồng – Min-woo – rằng sẽ không cho phép anh “vượt qua” sang Triều Tiên trong bối cảnh chính trị lúc bấy giờ. Nhưng Min-woo vẫn ra đi và không bao giờ trở về, để rồi cuộc hôn nhân của họ tan vỡ bởi chiến tranh Triều Tiên. Giờ đây, sau sáu mươi năm chia cắt bán đảo, Yeon-hee mong mỏi được gặp lại người chồng yêu dấu của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Moon Chae-won","avatar":""},{"name":"Go Soo","avatar":""},{"name":"Kim Soo-ro","avatar":""},{"name":"Son Sook","avatar":""},{"name":"Yoo Ho-jeong","avatar":""},{"name":"Choi Gyu-hwan","avatar":""},{"name":"Park Ye-joo","avatar":""},{"name":"Lee Dong-jin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Minwussi Oneunnal","The Day Min-woo Arrives","Mr. Min-Woo''s Coming Day","Awaiting","민우씨 오는 날"]', 1784690324454);
