INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('annabelle', 'Annabelle', 'Annabelle', 'https://phimimg.com/upload/vod/20250511-1/d04548a2f9d898c4305a711dafbf5b0a.jpg', 'https://phimimg.com/upload/vod/20250511-1/565919ddccb2987a011d19c063d08853.jpg', '<p>Búp Bê Annabelle là một bộ phim điện ảnh kinh dị do Mỹ sản xuất được đạo diễn kì cựu James Wan phụ trách. Nội dung phim xoay quanh về câu chuyện đằng sau con búp bê Annabelle bị quỷ ám sau loạt truyện &quot;The Conjuring&quot; từng tạo tiếng vang trong năm 2013. Đi sâu vào bộ phim lần này Annabelle xuất hiện tại một gia đình vợ chồng trẻ, món quà được John tặng vợ mình nhân dịp sinh nhật chính là con búp bê Annabelle. Đêm đầu tiên Sarah cảm nhận được sự kì bí xảy ra xoay quanh gia đình hàng xóm, họ bị chính Annabelle điều khiển và giết hại lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Annabelle Wallis","avatar":""},{"name":"Ward Horton","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Eric Ladin","avatar":""},{"name":"Kerry O''Malley","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"Ivar Brogger","avatar":""},{"name":"Gabriel Bateman","avatar":""},{"name":"Shiloh Nelson","avatar":""},{"name":"Morganna Bridgers","avatar":""},{"name":"Michelle Romano","avatar":""},{"name":"Paige Diaz","avatar":""},{"name":"Tree O''Toole","avatar":""},{"name":"Trampas Thompson","avatar":""},{"name":"Camden Singer","avatar":""},{"name":"Kei","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slu