INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-sieu-dang-2', 'Người Nhện Siêu Đẳng 2', 'The Amazing Spider-Man 2', 'https://phimimg.com/upload/vod/20250707-1/76357d997a6d6ab4b72f5fc0b646c98f.jpg', 'https://phimimg.com/upload/vod/20250707-1/319a8a56a4f40d488edfbe1034655ea0.jpg', '<p>“Mỗi ngày tôi thức dậy và biết rằng, tôi càng cố cứu thêm nhiều người, có nghĩa tôi đang tạo ra nhiều kẻ thù hơn. Và đó chỉ là vấn đề thời gian, khi tôi phải đối mặt với những kẻ thù mạnh hơn mà tôi không thể đánh bại” – Câu nói của Người nhện báo trước cho sự xuất hiện của một loạt những kẻ thù nguy hiểm mà cậu sẽ phải đối đầu trong phần phim tiếp theo. Ngoài Electro (Jamie Foxx) đã xuất hiện trong đoạn teaser trước đây, người hùng giấu mặt Peter Parker sẽ phải chiến đấu chống lại Rhino (Paul Giamatti) và Green Goblin (Dane DeHaan).</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Dane DeHaan","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Max Charles","avatar":""},{"name":"B.J. Novak","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Jorge Vega","avatar":""},{"name":"Bill Heck","avatar":""},{"name":"Teddy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa 