INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-thuat-gia-kaito-1412', 'Ảo Thuật Gia Kaito 1412', 'Magic Kaito', 'https://phimimg.com/upload/vod/20250820-1/fc11925afa514bc0abad5d9f0bf4ae43.jpg', 'https://phimimg.com/upload/vod/20250820-1/c23e000d36add943b8d7b59b17160665.jpg', '<p>Câu chuyện xoay quanh Kuroba Kaito, một học sinh trung học 17 tuổi có tài năng ảo thuật thiên bẩm. Cuộc sống của cậu bị đảo lộn khi cậu phát hiện ra sự thật về cái chết của cha mình, Toichi Kuroba, một ảo thuật gia nổi tiếng thế giới từng là siêu trộm Kid Kid (Siêu Trộm Kid). Kaito nhận ra cha mình không chết vì tai nạn mà bị ám sát bởi một tổ chức bí ẩn.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 12, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Kappei Yamaguchi","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Minami Takayama","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Michio Hazama","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Satsuki Yukino","avatar":""},{"name":"Michie Tomizawa","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Unsho Ishizuka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["怪盗基德1412","Magic Kaito 1412","Majikku Kaito 1412","매직 카이토 1412","Siêu trộm Kid 1412","Ảo thuật gia Kaito Kid","まじっく快斗1412"]', 1784690324454);
