INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-7-ngay-cu-cua-tuong-lai', 'X-Men 7: Ngày Cũ Của Tương Lai', 'X-Men: Days Of Future Past', 'https://phimimg.com/upload/vod/20250817-1/dfcb5c95da77476758999f9e4ad18c29.jpg', 'https://phimimg.com/upload/vod/20250817-1/1356ff3bb5781090cea857aaa1392acd.jpg', '<p>Trong phần phim này, Người Sói (Hugh Jackman) được gửi về quá khứ để giúp đỡ giáo sư X (James McAvoy), Magneto (Michael Fassbender) và các dị nhân của X-Men: First Class ngăn chặn sự trỗi dậy của Sentinels, loại rô bốt khổng lồ được lập trình để tiêu diệt những người mang gen đột biến.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Elliot Page","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Daniel Cudmore","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Adan C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["X-Men: Days of Future Past 3D","X