INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-xa-thu', 'Bộ Đôi Xạ Thủ', 'The Legendary Sniper', 'https://phimimg.com/upload/vod/20250810-1/452b6419e1f833b57ca21e32f67f2464.jpg', 'https://phimimg.com/upload/vod/20250810-1/d91b9e94a9686af665f30da0a9367494.jpg', '<p>Mồ côi từ nhỏ, Trương Tam được thủ lĩnh băng cướp Tạ Lão Tạc thu nhận làm đệ tử và nuôi dạy dưới tên Tặc Cửu. Trong một cuộc bao vây và đàn áp của quân Nhật, Tạ Lão Tạc bị lính Nhật bắn chết. Căm hận sự tàn bạo của quân Nhật, Tặc Cửu quyết định gia nhập quân đội. Với tài bắn súng xuất chúng và chiến thuật linh hoạt, Tặc Cửu thành công đánh bại nhiều đợt tấn công của quân địch, hoàn thành xuất sắc nhiệm vụ và dần dà trưởng thành trong quân ngũ, trở thành một chiến sĩ thực thụ. Mối duyên của anh với tiểu thư nhà giàu mạnh mẽ Lý Nhàn Thục cũng bắt đầu từ đây.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 20, 2014, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Hồng Lôi","avatar":""},{"name":"Hải Thanh","avatar":""},{"name":"Tôn Sảnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Er Pao Shou","The Legendary Sniper","二炮手"]', 1784690324454);
