INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-luyen-2014', 'Lưu Luyến', 'Love Affair', 'https://phimimg.com/upload/vod/20250806-1/d03ff06351d733b55f1ae4daa56aeac3.jpg', 'https://phimimg.com/upload/vod/20250806-1/8f5e4c378b5649d53daeef5898984d50.jpg', '<p>Ga-hee xuất hiện trước Seong-min, người sống những ngày tẻ nhạt trông coi hiệu sách sau khi nghỉ hưu. Điều hành một trường múa ba-lê nhưng hôn nhân không hạnh phúc, Ga-hee và Seong-min nhanh chóng lao vào một mối tình cuồng nhiệt. Họ biết rằng không nên ở bên nhau, nhưng chính điều đó lại khiến mọi thứ thêm phần say đắm… cho đến khi tình yêu của họ trượt dài đến bờ vực hủy diệt.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Se-Ah","avatar":""},{"name":"Jeon Ju-ho","avatar":""},{"name":"Jung Wook","avatar":""},{"name":"Park Eun-young","avatar":""},{"name":"Ryu Sung-hyun","avatar":""},{"name":"Yoo In-na","avatar":""},{"name":"Jo Hye-in","avatar":""},{"name":"Kim Neul-me","avatar":""},{"name":"Cho Yoon-ji","avatar":""},{"name":"Jo Eun-seo","avatar":""},{"name":"Jo Yeong-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["정사 위험한 성적유희","八头身美女","Jeongsa","Love Affair","狂情慾事","情事","정사"]', 1784690324454);
