INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-trom-sieu-dang', 'Băng Trộm Siêu Đẳng', 'The Con Artists', 'https://phimimg.com/upload/vod/20250804-1/c47ad1f502202e173061118c361ff50b.jpg', 'https://phimimg.com/upload/vod/20250804-1/cbaa7ac763138a3d395e97ec0763e053.jpg', '<p>Bộ phim kể về một nhóm tội phạm nhỏ do Lee đứng đầu gồm một kỹ thuật viên, một hacker và một tay thợ mở két sắt lập kế hoạch đánh cướp các tiệm đá quý ở khu phố Tàu. Vụ trộm diễn ra suôn sẻ nhưng những tay trộm này lại không ngờ đã làm kinh động đến tên đại ca Cho bảo kê khu phố Tàu, khiến hắn quyết định ép buộc cả nhóm cùng thực hiện một vụ trộm lớn hơn: đánh cắp 150 tỷ won của Quỹ &quot;đen&quot; chính phủ. Bắt đầu từ đây, cuộc chiến cân não giữa 3 phe: nhóm Lee, băng đảng của Cho và cảnh sát diễn ra gây gắt và quyết liệt. Mỗi bên đều có toan tính riêng của mình chưa kể ẩn bên dưới vụ cướp được dàn dựng công phu còn có một một kế hoạch trả thù khác. Sự kết hợp giữa những kế hoạch đánh cướp hoàn ...</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Woo-bin","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Kim Yeong-cheol","avatar":""},{"name":"Jo Yoon-hee","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Shin Gu","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Yun Ki-chang","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Seo Ji-hee","avatar":""},{"name":"Jung Sung-il","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f585