INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-dau-si', 'Thánh Đấu Sĩ', 'Saint Seiya: Legend Of Sanctuary', 'https://phimimg.com/upload/vod/20250725-1/cea22416a2fa23d6d2e3bd25618e1320.jpg', 'https://phimimg.com/upload/vod/20250725-1/d633a9998b2d2e46691ed02e8b2e53e9.jpg', '<p>Các chiến binh được gọi là Thánh là những nhà vô địch của hy vọng luôn xuất hiện kể từ Thời đại Thần thoại bất cứ khi nào cái ác đe dọa thế giới. Trong câu chuyện ngày nay, nhiều năm kể từ cuộc chiến Thánh chiến kéo dài, chúng ta tìm thấy Saori Kido, một cô gái gặp rắc rối với sức mạnh bí ẩn của mình. Cô được một cậu bé tên là Thánh đồng Seiya cứu thoát khỏi một cuộc tấn công bất ngờ của một sát thủ, qua tai nạn đó Saori nhận ra định mệnh và sứ mệnh của mình và quyết định đến Thánh địa cùng với Seiya và nhóm các Thánh đồng của anh ta. Tại Sanctuary, họ đối đầu với Pope và tiến hành một trận chiến tuyệt vọng chống lại các vị Thánh vĩ đại nhất, Gold Saints.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Ayaka Sasaki","avatar":""},{"name":"Kenji Akabane","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Kenji Nojima","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Go Inoue","avatar":""},{"name":"Mitsuaki Madono","avatar":""},{"name":"Masumi Asano","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Shinji Kawada","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Takuya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Saint Seiya: Legend of Sanctuary","Saint Seiya Legend of Sanctuary","Los Caballeros del Zodiaco: La Leyenda del Santuario","聖鬥士星矢 LEGEND of SANCTUARY","Os Cavaleiros Do Zodíaco: A Lenda Do Santuário","Saint Seiya - La légende du sanctuaire","圣域传说","聖鬥士星矢：聖域傳說","圣斗士星矢：圣域传说","圣斗士星矢","Os Cavaleiros do Zodíaco - A Lenda do Santuário","聖闘士星矢 LEGEND of SANCTUARY"]', 1784690324454);
