INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-dau-si', 'Thánh Đấu Sĩ', 'Saint Seiya: Legend Of Sanctuary', 'thánh đấu sĩ saint seiya: legend of sanctuary kaito ishikawa ayaka sasaki kenji akabane kensho ono nobuhiko okamoto kenji nojima mitsuru miyamoto rikiya koyama koichi yamadera hiroaki hirata go inoue mitsuaki madono masumi asano toshiyuki morikawa shinji kawada daisuke namikawa takuya saint seiya: legend of sanctuary saint seiya legend of sanctuary los caballeros del zodiaco: la leyenda del santuario 聖鬥士星矢 legend of sanctuary os cavaleiros do zodíaco: a lenda do santuário saint seiya - la légende du sanctuaire 圣域传说 聖鬥士星矢：聖域傳說 圣斗士星矢：圣域传说 圣斗士星矢 os cavaleiros do zodíaco - a lenda do santuário 聖闘士星矢 legend of sanctuary', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hua-voi-cha', 'Lời Hứa Với Cha', 'Ode To My Father', 'https://phimimg.com/upload/vod/20250721-1/69bed5515aade5b7c0bcb8a0d03b9dca.jpg', 'https://phimimg.com/upload/vod/20250721-1/ad4bc8d4c340ce20d68cab487cfd365b.jpg', '<p>Một người đàn ông khao khát được đoàn tụ với cha và em gái của mình. Họ đã bị chia cắt trong một Triều Tiên bị chiến tranh tàn phá và bất ổn về chính trị.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-min","avatar":""},{"name":"Yunjin Kim","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Uhm Ji-sung","avatar":""},{"name":"Kim Seul-ki","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Choe Stella Kim","avatar":""},{"name":"Go Yoon","avatar":""},{"name":"Park Seon-woong","avatar":""},{"name":"U-KNOW","avatar":""},{"name":"Park Yeong-su","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Matthew Douma","avatar":""},{"name":"Jeon So-mi","avatar":""},{"name":"Jung Sung-ho","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Oda a mi padre","국제시장","Ode to My Father","قصيدة إلى أبي"]', 1784690324454);
