INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-fargo-phan-1', 'Thị Trấn Fargo (Phần 1)', 'Fargo (Season 1)', 'https://phimimg.com/upload/vod/20250723-1/6cf6c6b57678f93a7047cf001df6bbec.jpg', 'https://phimimg.com/upload/vod/20250723-1/080d4d7f62ab55774565760e78136ccf.jpg', '<p>Fargo là một bộ phim truyền hình dài tập hài kịch tội phạm đen của Mỹ được tạo ra và chủ yếu được viết bởi Noah Hawley. Chương trình được lấy cảm hứng từ bộ phim cùng tên năm 1996 được viết và đạo diễn bởi anh em Coen, người được ghi là nhà sản xuất điều hành cho loạt phim cùng với Hawley. Sê-ri được công chiếu vào ngày 15 tháng 4 năm 2014, trên FX, và tuân theo định dạng hợp tuyển, với mỗi phần được đặt trong một thời đại khác nhau, và với một câu chuyện khác nhau và chủ yếu là các nhân vật và diễn viên mới, mặc dù có sự trùng lặp nhỏ. Mỗi mùa có rất nhiều tài liệu tham khảo cho phim của anh em Coen.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Juno Temple","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"David Rysdahl","avatar":""},{"name":"Joe Keery","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Richa Shukla Moorjani","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Sienna King","avatar":""},{"name":"Dave Foley","avatar":""},{"name":"Jon Hamm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雪花高离奇命案","冰血暴","FARGO/ファーゴ","Фарго","Fargo: Year One","Fargo: Year Two","Fargo: Year Three","Fargo: Year Four","Fargo: Year Five","Fargo"]', 1784690324454);
