INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-la-alice', 'Vẫn Là Alice', 'Still Alice', 'https://phimimg.com/upload/vod/20250707-1/a54b75393d9853a21710753f68ed57b8.jpg', 'https://phimimg.com/upload/vod/20250707-1/730b520f990196d2c8ec039bfcfe7d91.jpg', '<p>Alice Howland, một gia đình hạnh phúc với ba đứa con đã lớn, là một giáo sư ngôn ngữ học nổi tiếng, người bắt đầu quên lời. Khi nhận được kết quả chẩn đoán đau đớn, Alice và gia đình cô thấy mối quan hệ của họ bị thử thách.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Shane McRae","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Stephen Kunken","avatar":""},{"name":"Erin Darke","avatar":""},{"name":"Daniel Gerroll","avatar":""},{"name":"Quincy Tyler Bernstine","avatar":""},{"name":"Maxine Prescott","avatar":""},{"name":"Orlagh Cassidy","avatar":""},{"name":"Rosa Arredondo","avatar":""},{"name":"Zillah Glory","avatar":""},{"name":"Caridad Montanez","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Meu Nome é Alice","Para Sempre Alice","Siempre Alice","アリスのままで","Still Alice: Κάθε Στιγμή Μετράει","Все ще Еліс","스틸 앨리스","永远的爱丽丝","Still Alice"]', 1784690324454);
