INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-tham-hiem-vung-dat-moi-peko-va-5-nha-tham-hiem', 'Doraemon: Nobita Thám Hiểm Vùng Đất Mới – Peko và 5 Nhà Thám Hiểm', 'Doraemon: New Nobita''s Great Demon - Peko and the Exploration Party of Five', 'doraemon: nobita thám hiểm vùng đất mới – peko và 5 nhà thám hiểm doraemon: new nobita''s great demon - peko and the exploration party of five wasabi mizuta megumi oohara yumi kakazu subaru kimura tomokazu seki yu kobayashi kenji tada miku natsume shun oguri yoshi yamada 新·大雄的大魔境 doraemon the movie: nobita in the new haunts of evil - peko and the five explorers eiga doraemon shin nobita no daimakyo ~peko to 5-nin no tankentai~ 電影哆啦a夢：新大雄的大魔境 doraemon y el reino perruno doraemon: nobita''s great unexplored lands—peko and the five explorers ドラえもん 新・のび太の大魔境 ～ペコと5人の探検隊～ doraemon - il film: le avventure di nobita e dei cinque esploratori 哆啦a梦：新・大雄的大魔境 doraemon: new nobita''s great demon - peko and the exploration party of five 映画ドラえもん 新・のび太の大魔境 도라에몽: 신 노비타의 대마경 ~페코와 5인의 탐험대~ 哆啦a梦 新・大雄的大魔境 多啦a夢：新大雄的大魔境 多啦a夢：新．大雄的大魔境~柏高與五人之探險隊~ 映画ドラえもん 新・のび太の大魔境 ～ペコと5人の探検隊～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-que-phuong-3', 'Lan Quế Phường 3', 'Lan Kwai Fong 3', 'https://phimimg.com/upload/vod/20250614-1/56b46eedd38a6492611d8fe8095085b7.jpg', 'https://phimimg.com/upload/vod/20250614-1/3d9f669bee1ce4957d70bcb77512c8ee.jpg', '<p>Phim Lan Kwai Fong phần 3 nói về cuộc sống về đêm ở Lan Quế Phường, những cám dỗ đầy rẫy trước mắt bạn trẻ và những quan niệm thoáng về tình yêu, tình dục của giới trẻ Hồng Kông ngày nay. Phim dự định sẽ phát hành vào đầu năm 2014.Bộ phim phần 3 kỳ này hứa hẹn sẽ thu hút một lượng lớn khán giả. Đạo diễn Tiền Quốc Vỹ đã quyết định dốc sức làm phần 3 với quy mô hoành tráng sau khi thành công vang dội của phần 1 va 2 trước đó. Nội dung bộ phim vẫn tiếp tục những màn ăn chơi tình cảm trác táng của một nhóm thanh thiếu niên đại gia với đằng sau là thế lực chống lưng đầy quyền lực.Phim Lan Quế Phường 3 Với những cảnh quay nóng bỏng cùng với dàn diễn viên chân dài sexy bộ phim chỉ dành cho người từ 16 tuổi trở ...</p>', 'Full', 1, 'single', 'completed', 23, 2014, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Whitney Hui","avatar":""},{"name":"Ava Yu Kiu","avatar":""},{"name":"Jeana Ho Pui-Yu","avatar":""},{"name":"Jason Chan Pak-Yu","avatar":""},{"name":"Alex Lam Tak-Shun","avatar":""},{"name":"Christine Ng Wing-Mei","avatar":""},{"name":"Celia Kwok Wing-Yee","avatar":""},{"name":"Charles Ying Cheong-Yau","avatar":""},{"name":"Lee Shi-Min","avatar":""},{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Justin Lo","avatar":""},{"name":"Wilson Chin Kwok-Wai","avatar":""},{"name":"Alex Fong Lik-Sun","avatar":""},{"name":"Timmy Hung Tin-Ming","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Lan kwai fong 3","喜愛夜蒲3","兰桂坊3"]', 1784690324454);
