INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-canh', 'Ma Cảnh', 'That Demon Within', 'https://phimimg.com/upload/vod/20250607-1/f1bf2b6ad5366709491957baa8fd0ca9.jpg', 'https://phimimg.com/upload/vod/20250607-1/1bcaf08a60ee026cbe25fc8da11b6c40.jpg', '<p>Vương Vĩ Nghiệp là một cảnh sát Hong Kong, vô tình cứu được một người đang bị trọng thương, sau đó mới biết người này là &quot;Quỷ Vương Đảng&quot; Hàn Giang đang bị cả giới cảnh sát Hong Kong hận thấu xương. Sau khi khỏi bệnh, Hàng Giang càng điên cuồng, giết người cướp bóc không gớm tay, còn các đồng sự của Vương Vĩ Nghiệp chỉ biết bó tay đứng nhìn, điều này khiến Vương Vĩ Nghiệp tự trách bản thân, anh chỉ còn cách bước vào ma đạo đối kháng với Quỷ vương, kết thúc đoạn ân oán này...</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Trương Gia Huy","avatar":""},{"name":"Trần Tư Tuyền","avatar":""},{"name":"An Chí Kiệt","avatar":""},{"name":"Liêu Khải Trí","avatar":""},{"name":"Lâm Gia Hoa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mo Jing","The Demon Within","クリミナル・アフェア　魔警","Этот демон внутри","魔警","Ma Cảnh","Moh Ging"]', 1784690324454);
