INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hobbit-dai-chien-nam-canh-quan', 'Người Hobbit: Đại Chiến Năm Cánh Quân', 'The Hobbit: The Battle of the Five Armies', 'https://phimimg.com/upload/vod/20250531-1/48e053e68497f675c143f8bab52f77e6.jpg', 'https://phimimg.com/upload/vod/20250531-1/6fe90c21d5bbd5e26b0e695b2d8f84bd.jpg', '<p>Tiếp nối ngay sau đoạn kết của phần hai, rồng Smaug bị thức tỉnh bởi nhóm phiêu lưu của Thorin và nổi giận bay tới tàn phá thị trấn bên hồ. Tuy nhiên, Smaug mau chóng bị cung thủ Bard tiêu diệt và Thorin nhờ đó giành lại được quê hương Erebor. Những tưởng mọi chuyện sẽ yên bình từ đây nhưng sự thất hứa của Thorin với người dân bên hồ và sự thù địch với tộc Tiên rừng mau chóng đẩy họ đến một trận chiến mới. Cùng lúc đó, liên minh Orc và sói ma Warg của tên Azog lầm lũi kéo đến ngọn Cô Sơn với toan tính chiếm lấy vị trí đắc địa và số vàng bên trong Erebor. Một trận giao tranh không khoan nhượng giữa năm đạo binh là điều không thể tránh khỏi.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ian McKellen","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Ken Stott","avatar":""},{"name":"Aidan Turner","avatar":""},{"name":"Dean O''Gorman","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"James Nesbitt","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Ryan Gage","avatar":""},{"name":"Cate Blanchet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Hobbit: Tam i z powrotem","El Hobbit III: La batalla de los cinco ejércitos","哈比人：五軍之戰","哈比人：汗血回归","指环王前传：霍比特人(下)","Ha''Hobbit: Krav Hameshet Hatsvaot","De Hobbit: De Slag van Vijf Legers","Hobbiten 3 - Femhærerslaget","Hobbit, czyli tam i z powrotem","هابیت: نبرد پنج سپاه","Lo Hobbit - La battaglia delle cinque armate","O Hobbit - A Batalha dos Cinco Exércitos","Hobbit del 3: Femhäraslaget","The Hobbit III：The Battle of the Five Armies","Lo Hobbit 3 - La battaglia delle cinque armate","호빗-다섯 군대 전투","Хоббит Битва пяти воинств","Le Hobbit 3 - La Bataille des cinq armées","Hobbit: Bitwa Pięciu Armii","سبيس جام: إرث جديد","Χόμπιτ: Η Μάχη των Πέντε Στρατών","Hobbitten - Femhaereslaget","호빗; 다섯 군대 전투","호빗 3: 다섯 군대 전투","호빗 3; 다섯 군대 전투","ホビット 決戦のゆくえ：2014","Người Hobbit 3: Đại Chiến Năm Cánh Quân","The Hobbit 3: The Battle of the Five Armies","Der Hobbit 3 - Die Schlacht der fünf Heere","哈比人：五軍之戰加長版","الهوبيت : معركة الجيوش الخمسة","Hobbit: Beş Ordunun Savaşı","Le hobbit 3 - La bataille des 5 armées","Хоббит 3","The Hobbit: The Battle of the Five Armies"]', 1784690324454);
