INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hobbit-dai-chien-nam-canh-quan', 'Người Hobbit: Đại Chiến Năm Cánh Quân', 'The Hobbit: The Battle of the Five Armies', 'người hobbit: đại chiến năm cánh quân the hobbit: the battle of the five armies ian mckellen martin freeman richard armitage orlando bloom evangeline lilly luke evans lee pace benedict cumberbatch ken stott aidan turner dean o''gorman billy connolly graham mctavish james nesbitt stephen fry ryan gage cate blanchet the hobbit: tam i z powrotem el hobbit iii: la batalla de los cinco ejércitos 哈比人：五軍之戰 哈比人：汗血回归 指环王前传：霍比特人(下) ha''hobbit: krav hameshet hatsvaot de hobbit: de slag van vijf legers hobbiten 3 - femhærerslaget hobbit, czyli tam i z powrotem هابیت: نبرد پنج سپاه lo hobbit - la battaglia delle cinque armate o hobbit - a batalha dos cinco exércitos hobbit del 3: femhäraslaget the hobbit iii：the battle of the five armies lo hobbit 3 - la battaglia delle cinque armate 호빗-다섯 군대 전투 хоббит битва пяти воинств le hobbit 3 - la bataille des cinq armées hobbit: bitwa pięciu armii سبيس جام: إرث جديد χόμπιτ: η μάχη των πέντε στρατών hobbitten - femhaereslaget 호빗; 다섯 군대 전투 호빗 3: 다섯 군대 전투 호빗 3; 다섯 군대 전투 ホビット 決戦のゆくえ：2014 người hobbit 3: đại chiến năm cánh quân the hobbit 3: the battle of the five armies der hobbit 3 - die schlacht der fünf heere 哈比人：五軍之戰加長版 الهوبيت : معركة الجيوش الخمسة hobbit: beş ordunun savaşı le hobbit 3 - la bataille des 5 armées хоббит 3 the hobbit: the battle of the five armies', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-doi-ban-than', 'Doraemon: Đôi Bạn Thân', 'Stand by Me Doraemon', 'https://phimimg.com/upload/vod/20250521-1/2d2bdd9da9c7b54406d4f91352038bde.jpg', 'https://phimimg.com/upload/vod/20250521-1/684908e6d558c679d0e90819e452d13f.jpg', '<p>Doraemon: Stand By Me sẽ là câu chuyện hoàn thiện về hành trình từ ngày đầu gặp gỡ cho đến lúc chia xa của Doraemon và Nobita. &nbsp;Ngày đầu tiên là ngày cậu bé Sewashi – con cháu 4 đời của Nobita ở thế kỷ 22 – du hành qua cỗ máy thời gian và mang theo một chú robot có chức năng giúp đỡ mọi người bằng những món bảo bối bí mật. Sewashi nói rằng cả gia đình đang phải gánh chịu khoản nợ nần mà Nobita để lại. Vậy nên Sewashi mang Doraemon tới giúp đỡ Nobita, vừa có thể thay đổi tương lai bi đát đó và vừa giúp Nobita được hạnh phúc hơn.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2014, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Satoshi Tsumabuki","avatar":""},{"name":"Vanilla Yamazaki","avatar":""},{"name":"Sachi Matsumoto","avatar":""},{"name":"Shihoko Hagino","avatar":""},{"name":"Aruno Tahara","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Miyako Takeuchi","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030