INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hong-lua', 'Hoa Hồng Lửa', 'Huahong Huahuo', 'https://phimimg.com/upload/vod/20250511-1/eeb1beda9af753bdd2f6bc0c071daedb.jpg', 'https://phimimg.com/upload/vod/20250511-1/62525199a6c9036839147fc0d4dc7441.jpg', '<p>Trần Tam Pháo là một thổ phỉ khét tiếng trong vùng và là đại đương gia của Đồng La Trại. Căm thù nhà họ Điền vì đã gây ra cái chết của cha mình, đúng vào ngày thành hôn của cô chủ phường rượu Hồng Hoa với con trưởng của Điền gia, Tam Pháo đến làm loạn hôn lễ nhằm và cướp đi tân nương. Cuộc đời của Hồng Hoa và Tam Pháo kể từ đây cũng bước sang một trang mới đầy sóng gió.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 12, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đào","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Trương Gia Dịch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花红花火"]', 1784690324454);
