INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cha-me', 'Tình Cha Mẹ', 'Romance Of Our Parents', 'https://phimimg.com/upload/vod/20250424-1/90f89561d6a3ce174b69cc846698b86b.jpg', 'https://phimimg.com/upload/vod/20250424-1/6169ada64deda41fd7c25551bb14134b.jpg', '<p>Tại khu quân sự hải quân ở Thanh Đảo, hiệu trưởng trường pháo binh hải quân và vợ của ông - Dương Đào - muốn mai mối cho sĩ quan, cả hai đều quyết tâm giải quyết vấn đề hôn nhân cá nhân cho các nhân viên lớn tuổi. Sĩ quan hải quân Giang Đức Phúc là trọng trách nặng nề đối với hiệu trưởng. Dưới sự giới thiệu của một vài linh mục, Giang Đức Phúc gặp An Kiệt trẻ và xinh đẹp tại tiệc khiêu vũ và nảy sinh tình cảm với cô ấy.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 10, 2014, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Thao","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Nhâm Soái","avatar":""},{"name":"Lưu Dật Quân","avatar":""},{"name":"Trương Diên","avatar":""},{"name":"Quách Quảng Bình","avatar":""},{"name":"Vương Tinh Hoa","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""},{"name":"Lưu Thiên Trì","avatar":""},{"name":"Trương Linh Tâm","avatar":""},{"name":"Dương Lập Tân","avatar":""},{"name":"Na Nhân Hoa","avatar":""},{"name":"Vương Vĩnh Tuyền","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["fumuaiqing","Romance of Our Parents","父母爱情"]', 1784690324454);
