INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-cha-me', 'Tình Cha Mẹ', 'Romance Of Our Parents', 'tình cha mẹ romance of our parents quách thao mai đình lưu lâm nhâm soái lưu dật quân trương diên quách quảng bình vương tinh hoa lưu mẫn đào lưu thiên trì trương linh tâm dương lập tân na nhân hoa vương vĩnh tuyền fumuaiqing romance of our parents 父母爱情', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-vet-duoi-dai-2', 'Chú Vẹt Đuôi Dài 2', 'Rio 2', 'https://phimimg.com/upload/vod/20250415-1/176122eeee70c8a044e639ecde637675.jpg', 'https://phimimg.com/upload/vod/20250415-1/918d604351661b4e0dee5e5c8654efcd.jpg', '<p>Tiếp nối phần 1 đình đám của bộ phim hoạt hình Rio, phần 2 của bộ phim sẽ đưa khán giả cùng gia đình chú vẹt đuôi dài Blu vào một chuyến phiêu lưu mới tới vùng đất hoang dã Amazon. Tại đây, gia đình Blu có cơ hội tìm lại rất nhiều đồng loại của mình cùng hàng loạt những nhân vật thú vị và cũng đầy nguy hiểm khác. Trong khi ông ngoại của lũ trẻ có vẻ khá dè chừng với Blu thì cô nàng chim Jewel – vợ của Blu gặp lại Roberto, một chú chim dũng mãnh, quyến rũ sẵn sàng đe dọa hạnh phúc đang có của gia đình Blu.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2014, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"will.i.am","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Andy García","avatar":""},{"name":"Bruno Mars","avatar":""},{"name":"Bernardo de Paula","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Jake T. Austin","avatar":""},{"name":"Amandla Stenberg","avatar":""},{"name":"Pierce Gagnon","avatar":""},{"name":"Rita Moreno","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Tracy Morgan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5e