INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-vet-duoi-dai-2', 'Chú Vẹt Đuôi Dài 2', 'Rio 2', 'chú vẹt đuôi dài 2 rio 2 jesse eisenberg anne hathaway will.i.am jamie foxx leslie mann george lopez andy garcía bruno mars bernardo de paula rodrigo santoro jemaine clement jake t. austin amandla stenberg pierce gagnon rita moreno kristin chenoweth tracy morgan рио 2 里约大冒险2 리오 2 río 2 ρίο 2 rio 2 ริโอ เจ้านกฟ้าจอมมึน 2 rio movie 2 rio 2 (2014) rio_2 (2014) 리오2 ブルー２　トロピカル・アドベンチャー chú vẹt đuôi dài 2 rio2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan', 'Họa giang hồ chi bất lương nhân', 'A Portrait of Jianghu: Bad Guys / Hua Jiang Hu Zhi Bu Liang Ren', 'https://phimimg.com/upload/vod/20250412-1/bca130600f061462db2ac751fec3ba04.jpg', 'https://phimimg.com/upload/vod/20250412-1/866653345fa3d97aa0e8144493b89955.jpg', '<p>Năm Thiên Phục thứ tư, Lương vương Chu Ôn giết vua soán quyền, chấm dứt triều đại kéo dài hơn hai trăm năm. Tổ chức Bất Lương Nhân của hoàng thất cũng bị tấn công bởi thế lực Huyền Minh Giáo của Chu Ôn, dần dần suy yếu và phân rã. Những Bất Lương Nhân còn sống sót đành phải ẩn cư để tránh bị truy sát. Bất Lương Soái Viên Thiên Cương buộc phải đơn độc xông vào hoàng cung, liều mình cứu hoàng tử cuối cùng của triều đại là Lý Tinh Vân, và bắn tên hiệu gọi Bất Lương Nhân đến tiếp ứng. Nhưng không ai xuất hiện theo hiệu lệnh, chỉ có Tinh Dương Thúc Tử lần theo dấu hiệu đến một ngôi làng hoang tàn với một cái giếng khô, và phát hiện hoàng tử sơ sinh đang khóc oe oe ở đó. Từ đây, hành trình nguy hiểm của hoàng tử bắt đầu…</p>', 'Hoàn Tất (54/54)', 54, 'hoathinh', 'completed', 11, 2014, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324454);
