INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan', 'Họa giang hồ chi bất lương nhân', 'A Portrait of Jianghu: Bad Guys / Hua Jiang Hu Zhi Bu Liang Ren', 'họa giang hồ chi bất lương nhân a portrait of jianghu: bad guys / hua jiang hu zhi bu liang ren jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-biet-yeu', 'Thiên Thần Biết Yêu', 'Hi! School - Love On', 'https://phimimg.com/upload/vod/20250409-1/223e884cc81ae5e8b21b7c6a31af052e.jpg', 'https://phimimg.com/upload/vod/20250409-1/4b01810f757976d89504fa7d3dfef82c.jpg', '<p>Với sự xuất hiện của một “thiên thần” rất đặc biệt, vô tình trở thành người phàm và vướng vào “lưới tình” cùng một hotboy học đường, phim hứa hẹn là trải nghiệm đáng nhớ dành cho các bạn tuổi ô mai trong mùa hè này.

Vốn là thiên thần dẫn dắt linh hồn người chết, song vì một lần tình cờ cứu mạng nam sinh trung học Woo Hyun mà Seul Bi phải chịu hình phạt biến thành người phàm. Không ai thân thích và cũng chẳng rõ cuộc sống trần gian, cô bé đành đến ở tạm nhà Woo Hyun, đồng thời được cho đi học cùng trường với cậu. Tại đây, Seul Bi vô cùng bất ngờ khi được gặp lại Sung Yeol – anh chàng tốt bụng từng cho cô mượn dù trong một đêm lang thang mưa gió. Qua nhiều sự cố, hiểu lầm, cả ba bắt đầu trở thành tri kỷ thân thiết. Đó cũng là lúc tình cảm dành cho cô bé thiên thần nhen nhóm trỗi dậy trong lòng Woo Hyun và Sung Yeol.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2014, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Sae-ron","avatar":""},{"name":"Nam Woo-hyun","avatar":""},{"name":"Lee Sung-yeol","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Baek Seung-Heon","avatar":""},{"name":"Han Soo-yeon","avatar":""},{"name":"Jo Yeon-woo","avatar":""},{"name":"Kim Kwang-shik","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["ハイスクール：ラブ・オン","Haiseukool - Reobeuon","Старшая школа - Любовь на полную","Старшая школа: Время любви","Старшая школа: пора любить!","Старша школа: пізнай кохання","Hi! School: Love On","하이스쿨: 러브온"]', 1784690324454);
