INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-phap-su-phan-2', 'Hội Pháp Sư (Phần 2)', 'Fairy Tail (Season 2)', 'hội pháp sư (phần 2) fairy tail (season 2) tetsuya kakihara aya hirano rie kugimiya yuichi nakamura sayaka ohara satomi sato yui horie hiroki yasumoto wataru hatano hiroki touchi mai nakahara katsuyuki konishi ryoko ono daisuke namikawa eri kitamura shinpachi tsuji mamiko noto tak 妖精的尾巴 魔导少年 ekor peri fearī teiru フェアリーテイル ゼロ fairy tail 妖精たちの合宿 fairy tailファイナルシリーズ フェアリーテイル сказка о хвосте феи фейри тейл хвост феи 魔導少年 fairy tail zero fairy tail final series fairy tail final season fairy tail', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tuoi-moi-lon', 'Trò Chơi Tuổi Mới Lớn', 'Finding The Adolescence', 'https://phimimg.com/upload/vod/20250324-1/bef89402878e6c547307addff2390266.jpg', 'https://phimimg.com/upload/vod/20250324-1/94149faf3fdaec3507dd86a95d3b5b71.jpg', '<p>Takane (Honoka Miki) là một nữ sinh trung học có niềm đam mê với hội họa, trong khi bạn thân của cô, Mika (Misato Aoyama), lại nuôi ước mơ trở thành tiểu thuyết gia. Cả hai là đôi bạn thân thiết và dần nảy sinh tình cảm dành cho nhau. Thế nhưng, mối quan hệ mong manh ấy bắt đầu lung lay khi Namie (Yukie Kawamura) xuất hiện — một cựu tiểu thuyết gia hiện đang làm việc tại thư viện.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Honoka Yahagi","avatar":""},{"name":"Misato Aoyama","avatar":""},{"name":"Yukie Kawamura","avatar":""},{"name":"Rin Aizawa","avatar":""},{"name":"Karin Ogino","avatar":""},{"name":"Sho Oyamada","avatar":""},{"name":"Yuki Takao","avatar":""},{"name":"Himeka Asami","avatar":""},{"name":"Akihiro Mayama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shishunki Gokko","青春期游戏","Finding the Adolescence","Puberty Play","思春期ごっこ"]', 1784690324454);
