INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhien-hoang-da-venice', 'Thiên Nhiên Hoang Dã Venice', 'Wild Venice', 'https://phimimg.com/upload/vod/20250324-1/93d807115fe1a893c08c05296684f042.jpg', 'https://phimimg.com/upload/vod/20250324-1/3b5af5abb89b621300b0cf257a0bd9ce.jpg', '<p>VENICE (ITALY) - THÀNH PHỐ LÃNG MẠN NHẤT CHÂU ÂU: Không chỉ có Pháp, khi nói đến những thành phố lãng mạn nhất chắc chắn phải nhắc đến Venice – một thành phố xinh đẹp nằm ở miền bắc Italy. Venice mang trong mình vẻ đẹp đặc trưng với nhiều màu sắc khác biệt. Chắc có lẽ vì vậy mà nơi đây còn được biết đến với một số tên gọi như là “thành phố nổi”, “ thành phố kênh rạch”, “thành phố của những cây cầu” ,.. hay “Thánh địa tình yêu”. … &nbsp;Mời các bạn cùng khám phá vẻ đẹp tuyệt mỹ của Venice và thiên nhiên trong lành ở nơi đây.</p>', 'Full', 1, 'single', 'completed', 32, 2014, 'Thuyết Minh', 'FHD', 'Áo', 0, '[{"name":"Andrew Solomon","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Thiên Nhiên Hoang Dã Venice","Wildes Venedig","Velence vadvilága","Wild Venice"]', 1784690324454);
