INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-nhien-hoang-da-venice', 'Thiên Nhiên Hoang Dã Venice', 'Wild Venice', 'thiên nhiên hoang dã venice wild venice andrew solomon thiên nhiên hoang dã venice wildes venedig velence vadvilága wild venice', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-trong-bao', 'Hoa Trong Bão', 'Rose In The Wind', 'https://phimimg.com/upload/vod/20250317-1/f75810d2e5e29403ffdbc337901df6d0.jpg', 'https://phimimg.com/upload/vod/20250317-1/335e69748c18e7fb9020c1c98b8a7453.jpg', '<p>Bạch Vũ Hòa là con gái Bạch gia, tính tình thẳng thắn lương thiện. Cô yêu và và kết hôn với Đổng Thiệu Hoa của Đổng phủ. Chẳng may, Thiệu Hoa mắc bệnh nặng. Để cứu chồng Vũ Hòa đến nhà kẻ thù là Đơn Phúc Toàn xin nhân sâm ngàn năm. Nhưng Đơn Phúc Toàn lại dùng bẫy hại cho Thiệu Hoa mất mạng. Nỗi đau mất chồng chưa nguôi, mẹ chồng của cô lại lấy cớ cô thất tiết nên đuổi ra khỏi Đổng Gia. Bầu trời như bỗng chốc tối sầm trước mắt, Bạch Vũ Hòa từ tiểu thư quyền quý bỗng chốc mất hết tất cả. Không nơi nương tựa, không người thân, thanh danh cũng không còn… Hiện tại và tương lai của cô lúc này được xem như một trận bão tố mù mịt và cô chính là đóa hoa duy nhất còn sót lại trong cơn bão. Quyết tâm không đầu hàng số phận, Vũ Hòa bắt đầu con đường chông gai tự phát triển sự nghiệp cho mình. Trở thành một người phụ nữ huyền thoại dũng cảm chiến đấu chống lại số phận và mạnh mẽ như một người đàn bà sắt.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 9, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Mạn","avatar":""},{"name":"Cận Đông","avatar":""},{"name":"Trần Chiêu Vinh","avatar":""},{"name":"Chu Kỳ Kỳ","avatar":""},{"name":"Lý Thiên Trụ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["铁娘子","董少爷和白小姐","Rose in the Wind","妇道"]', 1784690324454);
