INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-canh-cut-vung-madagascar', 'Biệt Đội Cánh Cụt Vùng Madagascar', 'Penguins of Madagascar', 'https://phimimg.com/upload/vod/20250316-1/d3821f112e3edd5394e3582465337818.jpg', 'https://phimimg.com/upload/vod/20250316-1/22533c6b76addd98e8c27fa5dbed81fa.jpg', '<p>Các điệp viên chim cánh cụt ưu tú Skipper, Kowalski, Rico và Private bắt tay với các đặc vụ khéo léo của Gió phương Bắc để hạ thiên tài cuồng quyền lực Trùm Xúc Tu Biển.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2014, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom McGrath","avatar":""},{"name":"Chris Miller","avatar":""},{"name":"Christopher Knights","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Annet Mahendru","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Danny Jacobs","avatar":""},{"name":"Werner Herzog","avatar":""},{"name":"Sean Charmatz","avatar":""},{"name":"Billy Eichner","avatar":""},{"name":"Stephen Kearin","avatar":""},{"name":"Ava Acres","avatar":""},{"name":"Kelly Coone","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Los Pinguinos de Madagascar La pelicula","馬達加斯加:爆走企鵝","Pinguinos de madagascar Origenes","Penguins of Madagascar: The Movie","Pinguins van Madagascar","荒失失企鵝","Die Pinguine aus Madagascar - Der Film","Os Pinguins de Madagascar","Penguins of Madagascar"]', 1784690324454);
