INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kiem-than-vuc-phan-2', 'Đao Kiếm Thần Vực (Phần 2)', 'Sword Art Online (Season 2)', 'https://phimimg.com/upload/vod/20250316-1/94fe139ab78e4b68d40c48a8c8bbbf7f.jpg', 'https://phimimg.com/upload/vod/20250316-1/837349c8d0d02b2f8bf32d447d1d2588.jpg', '<p>Một chuyên gia về trò chơi điện tử tạo ra công nghệ mới cho phép người chơi điều khiển nhân vật ảo bằng chính cơ thể của họ. Tuy nhiên, rắc rối đáng sợ lại nảy sinh.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Kanae Itou","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Ayahi Takagaki","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Sanae Kobayashi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["刀剑神域 爱丽丝篇 异界战争","SAO","刀剑神域","刀剑神域 Ⅱ","刀剑神域 爱丽丝篇","刀剑神域-Extra Edition","刀剑神域 Extra Edition","Sword Art Online","ऑनलाइन तलवार कला","स्वाद आर्ट ऑनलाइन","Sōdo Āto Onrain","ソードアート・オンライン アリシゼーション","소아온","Герой Меча Онлайн","Мастера меча онлайн","سورد آرت أونلاين","ซอร์ดอาร์ตออนไลน์","刀劍神域Ⅱ","刀劍神域