INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-quay-dam-mau-4-tan-diet', 'Góc Quay Đẫm Máu 4 : Tận Diệt', '[REC]⁴ Apocalypse', 'https://phimimg.com/upload/vod/20250314-1/d8429dc5f773c5a176970db749f807a9.jpg', 'https://phimimg.com/upload/vod/20250314-1/e01ea781bf677f067486318d1ffa20e7.jpg', '<p>Các phóng viên truyền hình Angela được cứu thoát khỏi tòa nhà và đưa tới một tàu chở dầu được kiểm tra. Tuy nhiên những người lính mà cô mang theo chứa những hạt giống virus bí ẩn của ma quỷ...</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Manuela Velasco","avatar":""},{"name":"Paco Manzanedo","avatar":""},{"name":"Héctor Colomé","avatar":""},{"name":"Ismael Fritschi","avatar":""},{"name":"Críspulo Cabezas","avatar":""},{"name":"Mariano Venancio","avatar":""},{"name":"María Alfonsa Rosso","avatar":""},{"name":"Carlos Zabala","avatar":""},{"name":"Cristian Aquino","avatar":""},{"name":"Emilio Buale","avatar":""},{"name":"Paco Obregón","avatar":""},{"name":"Javier Laorden","avatar":""},{"name":"Ramiro Blas","avatar":""},{"name":"Ferrán Terraza","avatar":""},{"name":"Carlos Lasarte","avatar":""},{"name":"Chicho Casti","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["[REC]⁴: Kıyamet Gecesi","REC レック4 ワールドエンド","死亡录像4","[REC]⁴","[REC]⁴ Apocalipsis"]', 1784690324454);
