INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-nam-yeu-em', 'Mười Năm Yêu Em', 'Ten Years Of Love', 'https://phimimg.com/upload/vod/20250314-1/834c6b1be97e0f667d2c6cf4bd38dc09.jpg', 'https://phimimg.com/upload/vod/20250314-1/cc183c59fc1c2014f8a4e976a731fc5c.jpg', '<p>Tiêu Nhiên và Lưu Nguyên là đôi bạn thân. Họ cùng đem lòng yêu Hàn Linh - cô hoa khôi của trường. Lưu Nguyên và Hàn Linh đã từng là một đôi, nhưng tiếng sét ái tình đã khiến cô nảy sinh tình cảm với Tiêu Nhiên từ lúc nào chẳng hay. Người yêu rơi vào tay bạn thân khiến mối quan hệ giữa Tiêu Nhiên và Lưu Nguyên trở nên căng thẳng.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 9, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Khiết","avatar":""},{"name":"Đặng Siêu","avatar":""},{"name":"Cao Hổ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天堂向左，深圳向右","深圳爱情故事","相爱10年","Ten Years of Love","相爱十年"]', 1784690324454);
