INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muoi-nam-yeu-em', 'Mười Năm Yêu Em', 'Ten Years Of Love', 'mười năm yêu em ten years of love đổng khiết đặng siêu cao hổ 天堂向左，深圳向右 深圳爱情故事 相爱10年 ten years of love 相爱十年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-cay-vung-grisaia', 'Trái Cây Vùng Grisaia', 'The Fruit Of Grisaia', 'https://phimimg.com/upload/vod/20250314-1/6f1bb132ff5d8d55d54f51c6a4732d95.jpg', 'https://phimimg.com/upload/vod/20250314-1/042f37af9455a892debcb7c8aee2f419.jpg', '<p>Học viện tư thục Mihama – thoạt nhìn có vẻ là một ngôi trường bình thường, nhưng thực chất nơi đây chỉ có 5 học sinh, và tất cả đều là những người mang &quot;hoàn cảnh đặc biệt&quot;. Một ngày nọ, học viện chào đón học sinh thứ sáu – Kazami Yuuji – người cũng mang trong mình một cái tôi mạnh mẽ và khác biệt chẳng kém gì những người còn lại. Trong quá trình sống và tiếp xúc với nhau, giữa họ dần nảy sinh sự thấu hiểu, những tác động qua lại nhỏ bé từng chút một bắt đầu chạm đến nội tâm của từng người. Và rồi, những câu chuyện quá khứ từng bị giam cầm trong lòng các cô gái ấy… bắt đầu chuyển động.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 18, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takahiro Sakurai","avatar":""},{"name":"Hikaru Isshiki","avatar":""},{"name":"Hiroko Taguchi","avatar":""},{"name":"Kaori Mizuhashi","avatar":""},{"name":"Tomoe Tamiyasu","avatar":""},{"name":"Ai Shimizu","avatar":""},{"name":"Mizuki Yamaguchi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["灰色三部曲","灰色的乐园","灰色的迷宫","Le Fruit de la Grisaia","The Eden of Grisaia","The Fruit of Grisaia","Grisaia no Kajitsu","Grisaia no Rakuen","Grisaia no Meikyuu","Grisaia no Meikyû","グリザイアの楽園","그리자이아의 과실","グリザイアの果実"]', 1784690324454);
