INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-gia-nghiep', 'Người Thừa Kế Gia Nghiệp', 'The Master Of The House', 'https://phimimg.com/upload/vod/20250311-1/f456ea61171afa81aff40d4ada68a575.jpeg', 'https://phimimg.com/upload/vod/20250311-1/76035f32328d98e6e62eb869cb133687.jpg', '<p>Giám đốc ngân hàng Trình Dật Phi sau một sự cố ngoài ý muốn, đã phải cầu cứu Đường Lan để thay vị trí của ông quản lý gia nghiệp. Đường Lan có tuổi thơ đầy gian khổ, được Trình Dật Phi giúp đỡ nhiều năm nay nên cô chấp nhận lời thỉnh cầu tiếp quản Trình gia của Dật Phi để trả ơn. Con thứ của Dật Phi - Trình Nguyệt Lượng - là một thanh niên đặc biệt. Anh rất thông minh và có trí nhớ phi thường nhưng hơi sống khép kín, không biết cách biểu đạt tình cảm, không tiếp xúc với ai ngoại trừ Đường Lan.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 11, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Thiên Vũ","avatar":""},{"name":"Địch Thiên Lâm","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Hách Bình","avatar":""},{"name":"Đàm Tùng Vận","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Master of the House","大当家"]', 1784690324454);
