INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-buoi-chieu', 'Chuyện Tình Buổi Chiều', 'Hirugao: Love Affairs In The Afternoon', 'https://phimimg.com/upload/vod/20250307-1/b504ad5b7acc20be059f827537a54090.jpg', 'https://phimimg.com/upload/vod/20250307-1/14333312fd0045adeeae7d72be8c789d.jpg', '<p>Cuộc sống của Sasamoto Sawa - một người vợ trẻ, vốn dĩ bình lặng và giản đơn. Thế nhưng, khi Takigawa Rikako – một người phụ nữ đầy quyến rũ và tràn ngập những cám dỗ – chuyển đến khu phố, cô cũng mang theo một thế giới mới của sự tinh tế và dục vọng. Khi Takigawa suýt bị bắt quả tang ngoại tình, Sawa vô tình ra tay giúp đỡ và bị cuốn vào vòng xoáy rắc rối. Chính từ đó, cô gặp gỡ Kitano Yuichi – một thầy giáo điển trai, và dần nhận ra những khao khát thầm kín của bản thân, những đam mê ngoài hôn nhân chưa từng nghĩ đến.</p>', 'Full', 11, 'series', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Ueto","avatar":""},{"name":"Michiko Kichise","avatar":""},{"name":"Takumi Saitoh","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Kosuke Suzuki","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Haruka Kinami","avatar":""},{"name":"Houka Kinoshita","avatar":""},{"name":"Yasushi Fuchikami","avatar":""},{"name":"Atsuko Takahata","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["昼颜","Hirugao: Amoríos en el atardecer","Hirugao - Heijitsu Gogo 3 ji no Koibito tachi","ひるがお へいじつごごさんじのこいびとたち","Hirugao","Hirugao～Love Affairs in the Afternoon～","昼顔〜平日午後3時の恋人たち〜"]', 1784690324454);
