INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-brooklyn-so-99-phan-2', 'Đồn Brooklyn Số 99 (Phần 2)', 'Brooklyn Nine-Nine (Season 2)', 'https://phimimg.com/upload/vod/20250306-1/9cd519d7fffd13069852d5146bbde12a.jpg', 'https://phimimg.com/upload/vod/20250306-1/b7d27d4c23d524c891614e79c0c8bceb.jpg', '<p><span style="text-wrap-mode: wrap;">B</span><span style="text-wrap-mode: wrap;">ộ phim xoay quanh Jake Peralta (Andy Samberg), một thám tử NYPD ở phân khu 99 của Brooklyn, người hay mâu thuẫn với sĩ quan chỉ huy mới của mình, Đại úy Raymond Holt (Andre Braugher). Dàn diễn viên phụ có Stephanie Beatriz trong vai Rosa Diaz, Terry Crews trong vai Terry Jeffords, Melissa Fumero trong vai Amy Santiago, Joe Lo Truglio trong vai Charles Boyle, Chelsea Peretti trong vai Gina Linetti, Dirk Blocker trong vai Michael Hitchcock và Joel McKinnon Miller trong vai Norm Scully.</span></p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 14, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andy Samberg","avatar":""},{"name":"Melissa Fumero","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Joe Lo Truglio","avatar":""},{"name":"Stephanie Beatriz","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Dirk Blocker","avatar":""},{"name":"Joel McKinnon Miller","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Brooklyn 99 - Lei e Desordem","ბრუკლინი 99","ברוקלין 99","بروکلین نه-نه","荒唐分局","Brooklyn 99","B99","Brooklyn Nine-Nine"]', 1784690324454);
