INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-den-tu-than', 'Hố Đen Tử Thần', 'Interstellar', 'https://phimimg.com/upload/vod/20250302-1/6012710a981edf1b6209bdb7fa82d1a6.jpg', 'https://phimimg.com/upload/vod/20250302-1/4cee31c3afd0fbfd11ed4f14b1bfd816.jpg', '<p>Interstellar nói về chuyến hành trình đi tìm một hành tinh mới cho loài người trú ngụ khi mà Trái Đất dần dần không còn là nơi an toàn và sự sống thì đang chết dần với những dịch bệnh trên các loại cây lương thực, đe dọa đến sự tồn tại của loài người một cách mạnh mẽ. Chúng ta sẽ đi theo hành trình của phi hành đoàn gồm Copper, Amelia cùng các thành viên khác trong việc giải cứu các phi hành gia khác đã lên đường khám phá các hành tinh mới để tìm ra hành tinh mới cho loài người trú ngụ</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Mackenzie Foy","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Bill Irwin","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Timothée Chalamet","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Leah Cairns","avatar":""},{"name":"Liam Dickinson","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["星际穿越","ইন্টারস্টেলার","星際啟示錄","Interestelar","Csillagok Között","インターステラー","ინტერსტელარი","Hố Đen Tử Thần","Ulduzlararası","Interstellaire","Интерстеллар","Интерстелар","بين النجوم","اولدوزلار آراسی","Інтэрстэлар","میان‌ ستاره‌ ای","इंटरस्टेलर","ਇੰਟਰਸਟੈਲਰ","Tähtedevaheline","Միջաստղային ճամփորդություն","בין כוכבים","ვარსკვლავთშორისი","Tarp žvaigždžių","ഇന്റർസ്റ്റെല്ലാർ","قائم بين النجوم","اینتر استلار","Одод хооронд","इन्टरस्टेलर","Interstellar: Călătorind Prin Univers","Medzvezdje","இன்டர்‌ஸ்டெலர்","Інтерстеллар","انٹرسٹیلر","Međuzvjezdani","Yıldızlararası","Међузвездани","ఇంటర్ స్టెల్లర్","อินเตอร์สเตลลาร์ ทะยานดาวกู้โลก","ကြယ်တာရာကြားဝယ်","인터스텔라","星際效應","Ինտերստելեր","در میان ستارگان","Interstellar"]', 1784690324455);
