INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-den-tu-than', 'Hố Đen Tử Thần', 'Interstellar', 'hố đen tử thần interstellar matthew mcconaughey anne hathaway michael caine jessica chastain casey affleck wes bentley topher grace mackenzie foy ellen burstyn john lithgow bill irwin david gyasi timothée chalamet matt damon josh stewart leah cairns liam dickinson f 星际穿越 ইন্টারস্টেলার 星際啟示錄 interestelar csillagok között インターステラー ინტერსტელარი hố đen tử thần ulduzlararası interstellaire интерстеллар интерстелар بين النجوم اولدوزلار آراسی інтэрстэлар میان‌ ستاره‌ ای इंटरस्टेलर ਇੰਟਰਸਟੈਲਰ tähtedevaheline միջաստղային ճամփորդություն בין כוכבים ვარსკვლავთშორისი tarp žvaigždžių ഇന്റർസ്റ്റെല്ലാർ قائم بين النجوم اینتر استلار одод хооронд इन्टरस्टेलर interstellar: călătorind prin univers medzvezdje இன்டர்‌ஸ்டெலர் інтерстеллар انٹرسٹیلر međuzvjezdani yıldızlararası међузвездани ఇంటర్ స్టెల్లర్ อินเตอร์สเตลลาร์ ทะยานดาวกู้โลก ကြယ်တာရာကြားဝယ် 인터스텔라 星際效應 ինտերստելեր در میان ستارگان interstellar', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-mo-ma-quai', 'Hầm Mộ Ma Quái', 'As Above, So Below', 'https://phimimg.com/upload/vod/20250228-1/663317d1074bea14ad66637da853d8c8.jpg', 'https://phimimg.com/upload/vod/20250228-1/0c372c5ae48d70af5db5b28d4dd0f365.jpg', '<p>Nhà khảo cổ học Scarlett Marlowe (Perdita Weeks) đã dành cả cuộc đời mình để tìm kiếm một trong những kho báu vĩ đại nhất của lịch sử: Hòn đá Phù thủy của Flamel. Theo truyền thuyết, cổ vật có thể ban cho cuộc sống vĩnh cửu và biến bất kỳ kim loại nào thành vàng. Khi biết rằng viên đá được cất giấu dưới lòng đất ở Hầm mộ Paris, cô đã tập hợp một đội để hướng dẫn và ghi lại sứ mệnh lịch sử của mình. Khi họ bắt đầu đi xuống, các thành viên trong nhóm không có cách nào để biết rằng họ đang bước vào địa ngục của chính họ.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Perdita Weeks","avatar":""},{"name":"Ben Feldman","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"François Civil","avatar":""},{"name":"Marion Lambert","avatar":""},{"name":"Ali Marhyar","avatar":""},{"name":"Cosme Castro","avatar":""},{"name":"Hamid Djavadan","avatar":""},{"name":"Théo Cholbi","avatar":""},{"name":"Emy Lévy","avatar":""},{"name":"Roger Van Hool","avatar":""},{"name":"Olivia Csiky Trnka","avatar":""},{"name":"Hellyette Bess","avatar":""},{"name":"Aryan Rahimian","avatar":""},{"name":"Samuel Aouizerate","avatar":""},{"name":"Kaya Blocksage","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Reflexo do Medo","Derin Kabus","Pod zemou","แดนหลอนสยองใต้โลก","地下に潜む怪人","Assim na Terra Como no Inferno","Así en la Tierra como en el Infierno","Katakombalar","Както горе, така и долу","Là-haut comme ici-bas","U mraku katakombe","Pod zemí","Catacombes","Katakomben","Όπως ψηλά, έτσι και χαμηλά","Úgy fent, mint lent","Amok le''ma''ala","Necropolis - La città dei morti","Parīze: Mirušo pilsēta","Kaip danguje, taip ir po zeme","Jako w piekle, tak i na Ziemi","Precum in iad, asa si pe pamant","Париж: Город мертвых","Kako gore, tako dole","忐忑","Париж. Місто мертвих","Hầm Mộ Ma Quái","As Above/So Below","巴黎地下坟场","巴黎地下墓穴","地下墓穴","كما في الأعلى، كذلك في الأسفل","As Above, So Below"]', 1784690324455);
