INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ham-mo-ma-quai', 'Hầm Mộ Ma Quái', 'As Above, So Below', 'hầm mộ ma quái as above, so below perdita weeks ben feldman edwin hodge françois civil marion lambert ali marhyar cosme castro hamid djavadan théo cholbi emy lévy roger van hool olivia csiky trnka hellyette bess aryan rahimian samuel aouizerate kaya blocksage o reflexo do medo derin kabus pod zemou แดนหลอนสยองใต้โลก 地下に潜む怪人 assim na terra como no inferno así en la tierra como en el infierno katakombalar както горе, така и долу là-haut comme ici-bas u mraku katakombe pod zemí catacombes katakomben όπως ψηλά, έτσι και χαμηλά úgy fent, mint lent amok le''ma''ala necropolis - la città dei morti parīze: mirušo pilsēta kaip danguje, taip ir po zeme jako w piekle, tak i na ziemi precum in iad, asa si pe pamant париж: город мертвых kako gore, tako dole 忐忑 париж. місто мертвих hầm mộ ma quái as above/so below 巴黎地下坟场 巴黎地下墓穴 地下墓穴 كما في الأعلى، كذلك في الأسفل as above, so below', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ho-2', 'Phi Hổ 2', 'Tiger Cubs 2', 'https://phimimg.com/upload/vod/20250218-1/75616134f1f4c81e5165243d72cbe210.jpg', 'https://phimimg.com/upload/vod/20250218-1/e30641ccb841bf309ee22f87a7e5d4da.jpg', '<p>Phi Hổ 2 xoay quanh đội phi hổ gồm những thành viên xuất sắc là Du Học Lễ (La Trọng Khiêm), Trang Trác Nguyên (Lương Liệt Duy), Tô Văn Cường (Huỳnh Trí Văn) dưới sự dẫn dăt của người đội trưởng Triển Hãn Thao (Mã Đức Chung). Đội phi hổ có sự liên kết chặt chẽ với nhau, vào sinh ra tử và thân nhau như anh em ruột thịt.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2014, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Him Law","avatar":""},{"name":"Oscar Leung Lit-Wai","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"Timmy Hung Tin-Ming","avatar":""},{"name":"Nancy Wu Ting-Yan","avatar":""},{"name":"Mandy Wong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
