INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-bac-kinh', 'Chuyện Tình Bắc Kinh', 'Beijing Love Story', 'https://phimimg.com/upload/vod/20250216-1/995a7e982fa8b9fde1143a9375db21ad.jpg', 'https://phimimg.com/upload/vod/20250216-1/c6a71f32c6c2a7b074826cc6638f3a14.jpg', '<p>5 câu chuyện của 5 cặp đôi ở lứa tuổi, hoàn cảnh và nghề nghiệp khác nhau vẽ nên một Chuyện Tình Bắc Kinh cực đẹp, những mâu thuẫn, những đau khổ hay hạnh phúc, lãng mạng điều được khác họa một cách đậm nét trong phim. Đặc biệt phim có sự tham gia của các diễn viên gạo cội như Lương Gia Huy, Lưu Gia Linh, Tư Cầm Cao Oa…</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Lệ Á","avatar":""},{"name":"Lương Gia Huy","avatar":""},{"name":"Lưu Gia Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Bei Jing ai qing gu shi","北京爱情故事"]', 1784690324455);
