INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-to-hai-chu', 'Một Tớ Hai Chủ', 'A Servant Of Two Masters', 'https://phimimg.com/upload/vod/20250214-1/9a232a3b21f9b5e87287d97cbe112f79.jpg', 'https://phimimg.com/upload/vod/20250214-1/3c8a98bfd48093af000fa7bb6715f6f5.jpg', '<p>Nội dung tâm lý, xã hội Ông bố đơn thân Dương Thụ nảy sinh tình cảm với bà chủ Đường Hồng giỏi giang xinh đẹp sau một thời gian làm tài xế cho bà. Đường Hồng cũng động lòng trước tấm lòng lương thiện của Dương Thụ, nhưng thân phận của hai người luôn là bức tường chắn mà họ khó có thể vượt qua. Cùng lúc đó, con gái của Dương Thụ lại làm mai cho ông với một người có phần giống với người vợ quá cố của ông. Diễn viên: Trương Gia Dịch, Diêm Ni, Giang Sơ Ảnh Đạo diễn: Lưu Tiến Thể loại: Tâm lý, Tình cảm Danh mục: Phim bộ Hoa ngữ Danh sách</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 9, 2014, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Gia Dịch","avatar":""},{"name":"Diêm Ni","avatar":""},{"name":"Giang Sơ Ảnh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["一仆二主"]', 1784690324455);
