INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-dien-nghia', 'Phong Thần Diễn Nghĩa', 'The Investiture Of The Gods', 'https://phimimg.com/upload/vod/20250204-1/7c388a6fe93f1745eeb54ac7dece80e3.jpg', 'https://phimimg.com/upload/vod/20250204-1/a0716a51386276bcc68aba47909db5eb.jpg', '<p>Phim kể về Trụ vương thời nhà Thương, một vị hôn quân tàn bạo hoang dâm vô độ, vì nghe lời Ái phi Đát Kỷ (hồ ly tinh biến thành) mà tàn hại trung lương, khiến bách tính lầm than. Khương Tử Nha là đồ đệ của Nguyên Thủy Thiên Tôn trên núi Côn Lôn, vâng lệnh thầy xuống núi cùng Na Tra giúp Cơ Phát diệt Thương lập Chu.</p>', 'Hoàn Tất (75/75)', 75, 'series', 'completed', 12, 2014, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Kiện Phong","avatar":""},{"name":"Trương Hinh Dư","avatar":""},{"name":"Khương Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Investiture of the Gods","封神英雄榜"]', 1784690324455);
