INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-den', 'Biển Đen', 'Black Sea', 'https://phimimg.com/upload/vod/20231124-1/dadc762066e4c7a0ac239087c2f32bcb.jpg', 'https://phimimg.com/upload/vod/20231124-1/5ab87d8b993ce930fcbe2c193485a444.jpg', '<p>Biển Đen - Black Sea: là tác phẩm điện ảnh của Anh, với sự tham gia của các diễn viên Jude Law, Scoot McNairy. Nội dung phim về cuộc hành trình của các thủy thủ trong chuyến tàu ngầm tìm vàng dưới đáy Biển đen. Họ sẽ gặp những khó khăn gì?.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Karl Davies","avatar":""},{"name":"Jodie Whittaker","avatar":""},{"name":"Daniel Ryan","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"David Threlfall","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Grigoriy Dobrygin","avatar":""},{"name":"Bobby Schofield","avatar":""},{"name":"Sergey Veksler","avatar":""},{"name":"Branwell Donaghey","avatar":""},{"name":"Sergey Kolesnikov","avatar":""},{"name":"Llewella","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
