INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('booba-mua-1', 'Booba (Mùa 1)', 'Booba (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/b7e811ab9d465f10957b3ba9e91cbf89.jpg', 'https://phimimg.com/upload/vod/20250116-1/471a0d5d4ec5ac169dae1e055ae4cdad.jpg', '<p>Booba nhỏ bé cảm thấy thế giới thật bí ẩn. Cậu luôn thấy vui khi tìm hiểu những điều mới lạ, và với cậu, mọi thứ xung quanh đều có thể là những chuyến phiêu lưu kỳ thú.</p>', 'Hoàn Tất (32/32)', 32, 'hoathinh', 'completed', 13, 2014, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Roman Karev","avatar":""},{"name":"Elena Kareva","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["بوبا: لغز الطعام","Buba: Aventuras na Cozinha","淘气包布巴：美食秀","S Boobou v kuchyni","Booba: Essens-Puzzle","Booba: Madprogrammet","En la cocina con Buuba","Booba: Kokkikoulu","Cuisine avec Booba !","Μπούμπα: Ας Μαγειρέψουμε","Kuhajmo s Boobom","Booba főzőműsora","תוכנית הבישול של בובי","In cucina con Booba!","ブーバのワクワク料理ショー","몬스터 요리사 부바","Booba: La cocina","Boobas matlagningsprogram","Booba gotuje","Booba: Vamos Cozinhar","Booba: Emisiune culinară","Готовим с Бубой","Boobas kockskola","บูบา: สนุกกับอาหาร","Booba: Çılgın Tarifler","好奇布巴：美味廚房","Буба: Їстівний пазл","Booba: Food Puzzle","Booba: Vui nấu ăn","Booba: The Food Show"]', 1784690324455);
