INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('booba-mua-1', 'Booba (Mùa 1)', 'Booba (Season 1)', 'booba (mùa 1) booba (season 1) roman karev elena kareva بوبا: لغز الطعام buba: aventuras na cozinha 淘气包布巴：美食秀 s boobou v kuchyni booba: essens-puzzle booba: madprogrammet en la cocina con buuba booba: kokkikoulu cuisine avec booba ! μπούμπα: ας μαγειρέψουμε kuhajmo s boobom booba főzőműsora תוכנית הבישול של בובי in cucina con booba! ブーバのワクワク料理ショー 몬스터 요리사 부바 booba: la cocina boobas matlagningsprogram booba gotuje booba: vamos cozinhar booba: emisiune culinară готовим с бубой boobas kockskola บูบา: สนุกกับอาหาร booba: çılgın tarifler 好奇布巴：美味廚房 буба: їстівний пазл booba: food puzzle booba: vui nấu ăn booba: the food show', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-cua-em', 'Người Hùng Của Em', 'Healer', 'https://phimimg.com/upload/vod/20250113-1/41d8daa2201578eca8dec8760217c459.jpg', 'https://phimimg.com/upload/vod/20250113-1/0ad1bc2e2c6d3a05cdc1a626b391a17e.jpg', '<p>Khai thác hình tượng “anh hùng giấu mặt” theo kiểu “khó đụng hàng”, đồng thời mang đến sự kết hợp hài hòa giữa hành động kịch tính và tình cảm lãng mạn, bộ phim truyền hình Hàn Quốc – Người hùng của em dễ dàng làm tan chảy trái tim khán giả.

Người hùng của em không chỉ thu hút khán giả bởi kịch bản hay, những pha hành động gay cấn mà còn tạo ấn tượng với cảnh phim lãng mạn, bối cảnh đẹp cùng dàn diễn viên trẻ, đẹp, nổi tiếng.

Người hùng của em (Healer) xoay quanh câu chuyện về một nhóm bạn trẻ cùng hoạt động trong ngành truyền thông, cụ thể là phóng viên đưa tin. Vì niềm đam mê, nhiệt huyết, không thờ ơ với những mặt tối của xã hội, họ đã cùng nhau vén màn sự thật từ bóng tối đó để cùng thay đổi thế giới mà họ đang sống.

Bộ phim là sự kết hợp hoàn hảo giữa hai chủ đề đang rất ‘hot’ hiện nay là phóng viên và siêu trộm. Với những cảnh hành động, hài hước và lãng mạn, mỗi tập phim là một trải nghiệm bất ngờ với khán giả.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Chang-wook","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Park Min-young","avatar":""},{"name":"Park Sang-won","avatar":""},{"name":"Do Ji-won","avatar":""},{"name":"Woo Hee-jin","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Oh Jong-hyuk","avatar":""},{"name":"Oh Kwang-rok","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Taemi","avatar":""},{"name":"Ji Il-ju","avatar":""},{"name":"Jang Seong-beom","avatar":""},{"name":"Jung Hye-in","avatar":""},{"name":"Park Sang-wook","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Son Seung-won","avatar":""},{"name":"Song Ji-in","avatar":""},{"name":"Choi Seung-k","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["夺命任务","Healer追击","ヒーラー 最高の恋人","Hilleo","Healer","治癒者","偽裝情人","Healer 治癒者","Цілитель","힐러"]', 1784690324455);
