INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hung-cua-em', 'Người Hùng Của Em', 'Healer', 'người hùng của em healer ji chang-wook yoo ji-tae park min-young park sang-won do ji-won woo hee-jin kim mi-kyeong oh jong-hyuk oh kwang-rok park won-sang taemi ji il-ju jang seong-beom jung hye-in park sang-wook jo han-chul son seung-won song ji-in choi seung-k 夺命任务 healer追击 ヒーラー 最高の恋人 hilleo healer 治癒者 偽裝情人 healer 治癒者 цілитель 힐러', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-song-con-phan-2', 'Cuộc Hẹn Sống Còn (Phần 2)', 'Date A Live (Season 2)', 'https://phimimg.com/upload/vod/20250106-1/e7bc073d8e50ed7f351140f171bebece.jpg', 'https://phimimg.com/upload/vod/20250106-1/eb4aaea83ccf9bfb89b3fbce7ea55ffe.jpg', '<p>Trước khi tận thế , hãy giết hoặc hôn em đi 30 năm trước, một hiện tượng kỳ lạ được gọi là &quot;không gian chấn&quot; đã tàn phá trung tâm của lục địa Á-Âu, đe dọa mạng sống của ít nhất 150 triệu người. Từ đó, những trận không chấn nhỏ hơn đã làm thế giới trở nên bất thường.Itsuka Shidou là một học sinh trung học bình thường. Thế nhưng, trong ngày đầu tiên đi học trở lại sau kỳ nghỉ xuân, một đợt không gian chấn giáng xuống thành phố. Shidou, đi tìm em gái trong thiên tai, đã gặp gỡ một cô gái cầm trọng kiếm sau một cơn không gian chấn.Em gái của Shidou, Kotori, sau đó tiết lộ với cậu cô gái đó là một sinh vật gọi là tinh linh và là nguyên nhân gây ra các đợt không gian chấn. Đồng thời Kotori cũng tiết lộ mình là một trong những lãnh đạo của tổ chức Ratatoskr có nhiệm vụ ngăn chặn những hiểm họa tinh linh. Sau đó cô mời Shidou gia nhập tổ chức với nhiệm vụ phong ấn năng lượng của các tinh linh. Với điều kiện tiên quyết là cậu phải hẹn hò với các cô gái và khiến họ yêu cậu.</p>', 'Full', 11, 'hoathinh', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Misuzu Togashi","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Iori Nomizu","avatar":""},{"name":"Asami Sanada","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Sarah Emi Bridcutt","avatar":""},{"name":"Minori Chihara","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["约会大作战","约战","デート・ア・ライブⅢ","Dēto A Raibu","デート・ア・ライブⅡ","デート・ア・ライブ IV","デート・ア・ライブⅣ","デート・ア・ライブⅤ","約會大作戰 DATE A LIVE 第四季","約會大作戰DATEALIVE第四季","Date a Live III","Date a Live II","Date a Live IV","DATE A LIVE V","デート・ア・ライブ"]', 1784690324455);
