INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-doi', 'Mùi Đời', 'Misaeng Incomplete Life', 'https://phimimg.com/upload/vod/20250101-1/0e4b86ea01897259e56322c4e1bcf075.jpg', 'https://phimimg.com/upload/vod/20250101-1/0622936592c38abd3be957d4bd10345f.jpg', '<p>Jang Geu-Rae(Siwan), một người nghiện game từ khi còn nhỏ. Với cậu, game là tất cả nhưng cậu lại không thể trở thành một game thủ chuyên nghiệp. Do vậy, cậu quay trở về với cuộc sống thực. Qua lời giới thiệu của một người quen, cậu được nhận vào làm thực tập viên tại công ty Wonin.

Vào ngày đầu tiên đi làm, cậu đụng độ với sếp của mình, Oh Sang-Sik(Lee Sung-Min). Jang Geu-Rae phải tranh đấu để giữ được công việc của mình...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yim Si-wan","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Kang So-ra","avatar":""},{"name":"Kang Ha-neul","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Shin Eun-jung","avatar":""},{"name":"Oh Min-suk","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Ryu Tae-ho","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Jung Hee-tae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ミセン 未生","ミセン","Misaeng","Misaeng: Incomplete Life","미생"]', 1784690324455);
