INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-an-quan-he-cha-con-cua-lauren-lake-phan-2', 'Tòa Án Quan Hệ Cha Con Của Lauren Lake (Phần 2)', 'Lauren Lake''s Paternity Court (Season 2)', 'https://phimimg.com/upload/vod/20241226-1/505c8309850dbe9f3b509939c115cd5f.jpg', 'https://phimimg.com/upload/vod/20241226-1/b711905ec2202fcc202b04e29bb0c40f.jpg', '<p>Paternity Court là chương trình trò chuyện kết hợp dài nửa giờ sử dụng định dạng nguyên đơn / bị đơn của chương trình tòa án. Lake trò chuyện với những người kiện tụng trong chương trình và quyết định các vụ án dựa trên kết quả xét nghiệm DNA.</p>', 'Hoàn Tất (105/105)', 105, 'tvshows', 'completed', 11, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Lake","avatar":""},{"name":"Mike Jerome Putnam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Paternity Court","Lauren Lake''s Paternity Court"]', 1784690324455);
