INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-ton', 'Trò Chơi Sinh Tồn', 'As The Gods Will', 'https://phimimg.com/upload/vod/20231030-1/b35e67ddc8469780245a2a3c9bb8b0b6.jpg', 'https://phimimg.com/upload/vod/20231030-1/339f3c6a8caa8f0d906823fc12ca88e8.jpg', '<p>Tại một trường trung học, một giáo viên đang giảng bài bất thình lình bị nổ tung sọ ngay bên bục giảng. Kế sau đó, những vụ nổ xảy ra liên tiếp. Shun Takahata và những học sinh trong lớp bị ép buộc phải cùng tham gia một trò chơi sinh tử mà họ không hề biết ai đứng đằng sau chuyện này, tại sao và mọi việc sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sota Fukushi","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Hirona Yamazaki","avatar":""},{"name":"Mio Yuki","avatar":""},{"name":"Jingi Irie","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Nijiro Murakami","avatar":""},{"name":"Dori Sakurada","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Atsuko Maeda","avatar":""},{"name":"Ryûhei Ueshima","avatar":""},{"name":"Ryosuke Yamamoto","avatar":""},{"name":"Minori Hagiwara","avatar":""},{"name":"Sasuke Otsuru","avatar":""},{"name":"Naoto Takahashi","avatar":""},{"name":"Jimon Terakado","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
