INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bong-chuyen-haikyuu-phan-1', 'Vua Bóng Chuyền Haikyuu (Phần 1)', 'Haikyu!! (Season 1)', 'https://phimimg.com/upload/vod/20241125-1/8c93d959c1f0c8886d767c6c25f61994.jpg', 'https://phimimg.com/upload/vod/20241125-1/7859420869529c6ea152bfaf1552b95e.jpg', '<p>Vua Bóng Chuyền Haikyu (Phần 1) - Haikyu (Season 1) kể về Hinata Shouyou, sau khi xem xong một trận bóng chuyền nọ, cậu đã thần tượng và mơ ước trở thành người khổng lồ tí hon và gia nhập đội bóng chuyền của trường trung học. Sau khi tìm đủ thành viên, họ đã tham gia giải đấu liên trường, tại đây họ đã chạm trán với Vua sân đấu Kageyama Tobio. Dù thua nhưng Shouyou vẫn quyết tâm lên top và trả đũa Kageyama. Tuy nhiên, lên cấp 3, oan gia ngõ hẹp thế nào, 2 cậu bé lại gặp nhau trong cùng một đội. Câu chuyện sẽ tiếp diễn ra sao?</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Haikyuu!!","High Kyuu!!","ハイキュー!! セカンドシーズン","Haikyuu!! Karasuno Koukou VS Shiratorizawa Gakuen Koukou","ハイキュー!! 烏野高校 VS 白鳥沢学園高校","ハイキュー!! バケモノたちの行くところ","Haikyuu!! Riku vs. Kuu","하이큐!! 땅 VS 하늘","Волейбол!!","Haikyuu!! II","Haikyuu!! TO THE TOP","HAIKYU!! LAND VS. AIR","Haikyu!! Karasuno High School vs Shiratorizawa Academy","Vua Bóng Chuyền","ハイキュー!!"]', 1784690324455);
