INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhien-phan-10', 'Siêu Nhiên (Phần 10)', 'Supernatural (Season 10)', 'siêu nhiên (phần 10) supernatural (season 10) jared padalecki jensen ackles misha collins 凶鬼恶灵 სუპერნატურალი supernatural スーパーナチュラル 슈퍼내츄럴 supernatural', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-yeu-co-don', 'Tôi Yêu Cô Đơn', 'I Love Loneliness', 'https://phimimg.com/upload/vod/20241116-1/f90ddf3e39a2c28f6fc2fa3199a28056.jpg', 'https://phimimg.com/upload/vod/20241116-1/58698ea0db3984259c155a897be27571.jpg', '<p>Tôi Yêu Cô Đơn kể về cuộc đời và số phận éo le của 3 người phụ nữ thông minh, xinh đẹp, thành đạt nhưng hoàn cảnh đẩy đưa họ đến với cuộc sống độc thân. Trong đó, Trang Anh (Trương Quỳnh Anh) là nữ ca sỹ đầy tham vọng, muốn lên “tột đỉnh vinh quang” nên không từ bất kỳ phương cách, thủ đoạn nào - thậm chí bỏ rơi người yêu, đến với các đại gia lắm tiền. Thu Sương (Nhật Kim Anh) là một luật sư đầy cá tính, thích chinh phục thử thách nhưng ẩn sâu bên trong là một trái tim yếu đuối, khao khát yêu thương nhưng mất niềm tin vào đàn ông. Bảo Dung (Thúy Diễm) là người phụ nữ truyền thống điển hình, nhu mì, đôn hậu, nhưng phải chịu nhiều tổn thương vì “nửa đường gãy gánh tương tư” với 2 cuộc tình dang dở. Trang Anh theo người tình đại gia bỏ rơi Duy Tân (Lương Thế Thành) để mưu cầu tiền tài, danh vọng; nhưng sau khi ảo ảnh vỡ tan, thì lại vội vàng níu kéo trong muộn màng, ngay lúc mà Duy Tân đã xao động với cô bạn thân Bảo Dung. Nhân lời yêu từ Duy Tân, trái tim Bảo Dung ngỡ sẽ được hồi sinh, nhưng ám ảnh sau hai cú sốc tình cảm trước đó khiến cô ngại ngần, không đủ tự tin đối mặt. Còn Thu Sương, trưởng thành trong một gia đình có cha và anh trai phong lưu, coi thường phụ nữ, khiến cô hoàn toàn không thể mở lòng trước bất kỳ một người đàn ông nào. Cô tự bao bọc mình bằng lá chắn đầy gai góc và trái tim giả vờ sắt đá, sẵn sàng chối bỏ cả tình yêu chân thành mà người Sĩ Lâm – người bạn “thanh mai trúc mã” dành cho mình. Sau hết bão giông, liệu Trang Anh, Bảo Dung và Thu Sương có tìm được hạnh phúc thực sự hay chấp nhận cuộc sống độc thân, đó sẽ là cái kết bất ngờ dành cho khán giả truyền hình.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 7, 2014, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lương Thế Thành","avatar":""},{"name":"Trương Quỳnh Anh","avatar":""},{"name":"Thúy Diễm","avatar":""},{"name":"Hoàng Anh","avatar":""},{"name":"NSUT Hữu Châu","avatar":""},{"name":"Ca sĩ Nhật Kim Anh","avatar":""},{"name":"NSƯT Xuân Hương","avatar":""},{"name":"Thanh Thức","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Kyokō Suiri","Kyokou Suiri","虚構推理 Season2","虚構推理 ミニアニメ","Inspectre","Invented Inference","Bảo Vệ Nhân Gian Và Yêu Giới","虚構推理"]', 1784690324455);
