INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-gian-atf', 'Nội Gián ATF', 'Ruse Of Engagement', 'https://phimimg.com/upload/vod/20241105-1/b0f1a0b15646167636d73d1bfea5f3d4.jpg', 'https://phimimg.com/upload/vod/20241105-1/1c09b227fbd9101a4620cfc128b3d263.jpg', '<p>Nội Gián ATF xoay quanh mối quan hệ giữa 2 anh em Trang Hữu Kiệt (Ngô Trác Hy) và Trang Hữu Chính (Trần Triển Bằng). Cùng yêu thích nghề cảnh sát rồi lần lượt tham gia tổ hành động và tổ tình báo chống khủng bố, những tưởng 2 anh em Hữu Kiệt và Hữu Chính sẽ tương trợ cho nhau và khiến người mẹ Đường Thục Phân (Lý Tư Kỳ) có thể yên tâm an hưởng tuổi già. Ngờ đâu, sau vụ án điều tra tổ chức bí mật, Hữu Kiệt trở mặt với Hữu Chính, mối quan hệ anh em cũng từ đó mà rạn nứt…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 10, 2014, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ngô Trác Hy","avatar":""},{"name":"Mông Gia Tuệ","avatar":""},{"name":"Trần Triển Bằng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["叛逃"]', 1784690324455);
