INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hoc-duong', 'Vua Học Đường', 'High School King of Savvy', 'https://phimimg.com/upload/vod/20241021-1/bbdc5072de8c9866d3df91ac4f8dddfe.jpg', 'https://phimimg.com/upload/vod/20241021-1/df81d6d4980aa6973a93a515d362bb4a.jpg', '<p>ộ phim xoay quanh một câu chuyện hài lãng mạn xảy ra sau khi một cậu học sinh trung học không biết trời cao đất dày là gì lại vô tình trở thành lãnh đạo của một công ty lớn. Seo In Guk vào vai một vận động viên khúc côn cầu trên băng trong trường học và là học sinh trung học nổi tiếng nhất trường. Đột nhiên anh phải thay thế người anh trai của mình, một chuyên gia CNTT làm trưởng phòng kế hoạch của một công ty. Từ đó tạo ra một loạt các tình huống lộn xộn, dở khóc dở cười và những câu chuyện thú vị tiếp nối nhau xảy ra.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 5, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"서인국","avatar":""},{"name":"이하나","avatar":""},{"name":"이수혁","avatar":""},{"name":"이태환","avatar":""},{"name":"강기영","avatar":""},{"name":"이열음","avatar":""},{"name":"오광록","avatar":""},{"name":"Kwon Seong-deok","avatar":""},{"name":"조한철","avatar":""},{"name":"김원해","avatar":""},{"name":"박수영","avatar":""},{"name":"이주승","avatar":""},{"name":"신혜선","avatar":""},{"name":"최필립","avatar":""},{"name":"송영규","avatar":""},{"name":"한진희","avatar":""},{"name":"Ji Yun-ho","avatar":""},{"name":"이정은","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["King of High School","Gogyocheosewang","High Schooler King of Life","High School King","The King of High School Manners","King of H