INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-den-phan-3', 'Danh Sách Đen (Phần 3)', 'The Blacklist (Season 3)', 'https://phimimg.com/upload/vod/20240118-1/0f990b69f02ded58014021357eebbcc3.jpg', 'https://phimimg.com/upload/vod/20240118-1/bb97be406643e8fe29bc96022a816dd8.jpg', '<p>Phim The Blacklist (Season 3) nói về cựu đặc vụ của chính phủ Raymond Red Reddington (James Spader) là mục tiêu truy nã hàng đầu của FBI trong cả thập kỷ đột ngột đến trụ sở FBI tự nguyện đầu thú, đề nghị hỗ trợ truy bắt tên khủng bố tưởng đã chết từ lâu – Ranko Zamani, với điều kiện chỉ nói chuyện với duy nhất Elizabeth “Liz” Keen – một nhân viên mới của FBI. Câu chuyện bắt đầu từ đó…</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Spader","avatar":""},{"name":"Megan Boone","avatar":""},{"name":"Diego Klattenhoff","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324455);
