INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-6', 'Gia Đình Hiện Đại (Phần 6)', 'Modern Family (Season 6)', 'https://phimimg.com/upload/vod/20241001-1/e4c4466950caacbde70739e31965f725.jpg', 'https://phimimg.com/upload/vod/20241001-1/3f9157a13c8b7cd10eb56bec4004e957.jpg', '<p>Tuần trăng mật đã qua, nhưng tiếng cười vẫn tiếp tục trong phần sáu của Modern Family. Khi Cam và Mitch mới kết hôn thích nghi với thực tế của hạnh phúc hôn nhân, Phil và Claire nhận thấy cuộc hôn nhân của họ căng thẳng bởi những người hàng xóm phiền phức, bữa tối Lễ Tạ ơn trở nên tồi tệ và việc Claire theo dõi trực tuyến. Trong khi đó, một máy bay không người lái có camera do thám tàn phá sân sau của Jay và Gloria, đồng thời áp sát trên đường cao tốc dẫn đến những thay đổi thú vị ở nhiều thành viên khác nhau trong gia tộc Pritchett-Dunphy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324455);
