INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock-phan-3', 'Thám Tử Sherlock (Phần 3)', 'Sherlock (Season 3)', 'https://phimimg.com/upload/vod/20240112-1/c76db7a229ba3c28d0cc4688510d577e.jpg', 'https://phimimg.com/upload/vod/20240112-1/e684af668e988554f8fca614ee34dc18.jpg', '<p>Trong phiên bản mới về các câu chuyện trinh thám được yêu thích của Arthur Conan Doyle, thám tử lập dị này dạo quanh các con phố của London hiện đại để tìm manh mối.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 12, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Una Stubbs","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
