INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sam-sam-den-roi', 'Sam Sam Đến Rồi', 'Boss & Me', 'https://phimimg.com/upload/vod/20240930-1/f3ac90eb680b57000048eab0b581be3f.jpg', 'https://phimimg.com/upload/vod/20240930-1/01f34c325f1b16997abea84a5d6be385.jpg', '<p>&quot;Sam Sam đến rồi&quot; được xây dựng từ tiểu thuyết &quot;Sam Sam đến đây ăn này&quot; của Cố Mạn. Câu chuyện kể về cặp đôi oan gia Phong Đằng (Trương Hàn đóng) và Sam Sam (Triệu Lệ Dĩnh đóng). Sam Sam vì có nhóm máu đặc biệt nên được Phong Đằng thu nhận về công ty làm việc. Sam Sam tiếp máu cho em gái của Phong Đằng nên đặc biệt được Phong Đằng chiếu cố gửi cho món gan lợn ăn hàng ngày. Từ ngày Sam Sam đến làm việc, Phong Đằng vô cùng vui vẻ, luôn muốn gây khó dễ cho cô, Sam Sam hết mực phản kháng nhưng lúc nào cũng thua dưới tay đại Boss. Liệu hai oan gia cuối cùng có tới được với nhau hay không...?</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 9, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"赵丽颖","avatar":""},{"name":"Zhang Han","avatar":""},{"name":"Chengyuan Li","avatar":""},{"name":"Huang Youming","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sha Shan Lai Chi","杉杉来吃","Come On Eat","삼삼래료","Пора кушать, Шань Шань!","杉杉来了","Shan Shan Comes to Eat","Shan Shan Is Here","Boss&Me","Boss & Me"]', 1784690324455);
