INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chia-se-bi-mat', 'Người Chia Sẻ Bí Mật', 'Secret Sharer', 'https://phimimg.com/upload/vod/20240927-1/ac13785adcf046177e9881d9bdd407fb.jpg', 'https://phimimg.com/upload/vod/20240927-1/77303ee6ae80002370e6ee73ffc6a984.jpg', '<p>Secret Sharer (2014) là một bộ phim thuộc thể loại lãng mạn, ly kỳ, và chính kịch. Phim được đạo diễn bởi Peter Fudakowski và dựa trên tác phẩm văn học của Joseph Conrad. Câu chuyện xoay quanh một thuyền trưởng trẻ người Ba Lan lần đầu tiên chỉ huy một con tàu chở hàng ở Biển Đông. Anh ta phải đối mặt với sự nổi loạn từ thủy thủ đoàn người Trung Quốc và phát hiện một người phụ nữ Trung Quốc đang trốn trên tàu</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jack Laskey","avatar":""},{"name":"朱珠","avatar":""},{"name":"戴立忍","avatar":""},{"name":"Si Qin Chao Ke Tu","avatar":""},{"name":"K.M. Lo","avatar":""},{"name":"Ying Wang","avatar":""},{"name":"Aroon Wanasbodeewong","avatar":""},{"name":"Guo Zhongyou","avatar":""},{"name":"Sittinont Ananvorakhun","avatar":""},{"name":"Bao Yin Ni Mu Hu","avatar":""},{"name":"Song Bin Zhu","avatar":""},{"name":"夏靖庭","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Secret Sharer"]', 1784690324455);
