INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-2014', 'Mỹ Nhân', 'Birth of a Beauty', 'https://phimimg.com/upload/vod/20240924-1/e55a286ebde7957f0e350e49aba42957.jpg', 'https://phimimg.com/upload/vod/20240924-1/40929a4123046235d1ea4cecadd05446.jpg', '<p>Biến Đổi Mỹ Nhân: Han Tae Hee, công tử của một tập đoàn vừa mang trong mình trái tim tan vỡ sau cú sốc tâm lý lớn. Để giành lại người phụ nữ mình yêu, Han Tae Hee đã biến cô nàng xấu xí thừa cân Sa Geum Ran trở thành một mỹ nhân - Sara (Han Ye Seul). Nhưng cuối cùng, anh lại phải lòng Sara xinh đẹp.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"주상욱","avatar":""},{"name":"한예슬","avatar":""},{"name":"정겨운","avatar":""},{"name":"왕지혜","avatar":""},{"name":"한상진","avatar":""},{"name":"Ha Jae-sook","avatar":""},{"name":"인교진","avatar":""},{"name":"한진희","avatar":""},{"name":"김영애","avatar":""},{"name":"강경헌","avatar":""},{"name":"Jin Ye-sol","avatar":""},{"name":"김용림","avatar":""},{"name":"심이영","avatar":""},{"name":"Kim Chung","avatar":""},{"name":"Lee Jong-nam","avatar":""},{"name":"권화운","avatar":""},{"name":"최종환","avatar":""},{"name":"Jo Yeong-hoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["La naissance d''une beauté","Minyeoui Tansaeng","รักวุ่นๆ ของคนเกิดมาสวย","Birth of Beauty","미녀의 탄생"]', 1784690324455);
