INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-nhan-2014', 'Mỹ Nhân', 'Birth of a Beauty', 'mỹ nhân birth of a beauty 주상욱 한예슬 정겨운 왕지혜 한상진 ha jae-sook 인교진 한진희 김영애 강경헌 jin ye-sol 김용림 심이영 kim chung lee jong-nam 권화운 최종환 jo yeong-hoon la naissance d''une beauté minyeoui tansaeng รักวุ่นๆ ของคนเกิดมาสวย birth of beauty 미녀의 탄생', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-su-sac-sao', 'Vi Sư Sắc Sảo', 'Incisive Great Teacher', 'https://phimimg.com/upload/vod/20240923-1/f0b85136ae4fa99abcea936fcee48e22.jpg', 'https://phimimg.com/upload/vod/20240923-1/bd892a8ce2af3d1a5c7718d0132b8022.jpg', '<p>Ông Thầy Bá Đạo - Incisive Great Teacher kể về việc khởi xướng việc nam nữ bình đẳng, Thánh thượng đã đưa ra chính sách cho phụ nữ được đi học nhưng lại gặp phải thế lực bảo thủ âm thầm phản đối. Vì muốn đảm bảo cho chính sách này được phổ biến thuận lợi, Liễu Ngạo Thiên – một mật thám hiệp khách giang hồ đã trà trộn vào học viện Hoằng Văn – trở thành lão sư. Nhờ vào sự khéo léo đưa đẩy của anh, một nhóm học sinh có cá tính và thân phận kỳ lạ đã đến học viện Hoằng Văn học tập. Từ lúc đó, cuộc sống nhà trường muôn màu muôn vẻ bắt đầu. Trên đường đến Hoằng Văn đăng ký làm lão sư, Liễu Ngạo Thiên và thặng nữ Lộ Vân Phi xảy ra hiểu lầm. Không ngờ, Lộ Vân Phi cũng vào học viện Hoằng Viên trở thành một lão sư. Từ đây, đôi oan gia này lại vừa tranh cãi ầm ĩ, vừa cùng nhau giải quyết phiền não của đám học trò, bồi dưỡng cho chúng ngày một trưởng thành. Hai người dần dần phát sinh tình cảm trong lúc hoạn nạn, nhưng không ngờ một lão sư khác tên là Nhiếp Văn Tinh lại bất ngờ xen vào tình yêu của bọn họ. Thế lực bảo thủ âm thầm liên tiếp ra tay phá rối học viện Hoằng Văn. Trong lúc nguy hiểm, Liễu Ngạo Thiên đã vận dụng sự thông minh của mình, cùng với các thầy cô giáo và học trò chống đỡ với những mối nguy hiểm liên tiếp xảy ra. Nhờ thế, họ đã bồi dưỡng nên sự dũng cảm, thông minh của các học trò. Cùng lúc đó, Liễu Ngạo Thiên bất ngờ phát hiện ra trong học viện Hoằng Văn lại ẩn náu một bàn tay đen tối của thế lực bảo thủ.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 10, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Thi Thi","avatar":""},{"name":"Ngô Kỳ Long","avatar":""},{"name":"Diệp Tổ Tân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["犀利仁师"]', 1784690324455);
