INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-tai-ho-boi', 'Bí Ẩn Tại Hồ Bơi', 'The Swimmers', 'https://phimimg.com/upload/vod/20240921-1/4c6ab4892264f07970f4d117a1cf3b8f.jpg', 'https://phimimg.com/upload/vod/20240921-1/c0bfe9b4aa3e8ec2a26c0e96bb078e50.jpg', '<p>Bộ phim xoay quanh câu chuyện của 2 người bạn thân đồng thời là đối thủ của nhau Perth và Tan. Dù là bạn thân nhưng Perth luôn ghen tỵ với tài năng của Tan. Trong khi đó Perth cũng thầm yêu Ice – bạn gái Tan. Và rồi một ngày Ice tự tử một cách bất thường và bí hiểm trong hồ bơi nơi họ thường xuyên tập luyện và rồi Tan quyết định phải tìm ra bí mật...</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chutavuth Pattarakampol","avatar":""},{"name":"Thanapob Leeratanakachorn","avatar":""},{"name":"Athapol Anunthavorasakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["ฝากไว้..ในกายเธอ"]', 1784690324455);
