INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-hercules', 'Huyền Thoại Hercules', 'The Legend Of Hercules', 'https://phimimg.com/upload/vod/20231227-1/7bdc62a61994c0ca757aaa05f72bd42c.jpg', 'https://phimimg.com/upload/vod/20231227-1/2a8cc4776a824f719485edbbd3440641.jpg', '<p>Ở Hy Lạp cổ đại năm 1200 trước Công nguyên, một nữ hoàng không khuất phục được dục vọng của thần Zeus để sinh một đứa con trai hứa sẽ lật đổ sự cai trị độc tài của nhà vua và khôi phục hòa bình cho một vùng đất đang gặp khó khăn. Nhưng vị hoàng tử này, Hercules, không biết gì về danh tính thực sự cũng như số phận của mình. Anh ta chỉ mong muốn một điều duy nhất: tình yêu của Hebe, Công chúa xứ Crete, người đã được hứa hôn với chính anh trai mình. Khi Hercules biết được mục đích lớn hơn của mình, anh ta phải lựa chọn: chạy trốn với tình yêu đích thực của mình hoặc hoàn thành định mệnh của mình và trở thành anh hùng thực sự của thời đại. Câu chuyện đằng sau một trong những huyền thoại vĩ đại nhất được tiết lộ trong sử thi đầy hành động này - một câu chuyện về tình yêu, sự hy sinh và sức mạnh của tinh thần con người.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kellan Lutz","avatar":""},{"name":"Liam McIntyre","avatar":""},{"name":"Gaia Weiss","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Roxanne McKee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324455);
