INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-yen-love', '100 Yen Love', '100 Yen Love', 'https://phimimg.com/upload/vod/20240713-1/968ad03b4c40de0cbfe8e35cd3ff7d4a.jpg', 'https://phimimg.com/upload/vod/20240713-1/f1bbf680b5183fd28d0913e8ddf1fb06.jpg', '<p>Slacker Ichiko gets into a fight with her younger sister and begins to live on her own, working the late shift at a 100 yen shop. On her way home, she passes a gym and meets middle-aged boxer Kano who trains there in silence...</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"安藤サクラ","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"根岸季衣","avatar":""},{"name":"Miyoko Inagawa","avatar":""},{"name":"早織","avatar":""},{"name":"Shohei Uno","avatar":""},{"name":"Tadashi Sakata","avatar":""},{"name":"Yuuki Okita","avatar":""},{"name":"吉村界人","avatar":""},{"name":"Shinichiro Matsuura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
