INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-quy-cua-da-vinci-phan-2', 'Những Con Quỷ Của Da Vinci (Phần 2)', 'Da Vinci''s Demons (Season 2)', 'https://phimimg.com/upload/vod/20240915-1/3544525960ee06da4c7d809ab342cb26.jpg', 'https://phimimg.com/upload/vod/20240915-1/d181e70dc510526bf2c87007519506f6.jpg', '<p><span style="text-wrap: wrap;">Da Vinci’s Demons là bộ phim truyền hình hư cấu về cuộc đời, về những bất công, khổ cực và cả những niềm vui mà Leonardo Da Vinci đã trải qua như là một nghệ sĩ, nhà phát minh, duy tâm và là một thiên tài trí tuệ. Trong cái thế giới đầy tăm tối nơi mà niềm tin còn mù quáng và kiến thức thì lại xa xỉ, tại nơi đây đã sản sinh ra một người đàn ông vĩ đại, người đã chiến đấu để gải mã những bí ẩn của thế giới và đem lại sự tự do về kiến thức, về sự hiểu biết cho mọi người. Ông là một kẻ dị giáo, là một người con trai luôn khát khao tình cảm với người cha của mình, và là người luôn chống lại những sai lầm của tôn giáo khi mà một đội quân bí mật đang dần được xây dựng để lật đổ cái xã hội hào nhoáng bề ngoài và nhơ nhuốc bên trong… Một cuộc chiến giữa tôn giáo và lý trí, sự thật và dối trá, tương lai và quá khứ đã xảy ra!</span></p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Riley","avatar":""},{"name":"Laura Haddock","avatar":""},{"name":"Elliot Cowan","avatar":""},{"name":"Hera Hilmar","avatar":""},{"name":"Gregg Chillin","avatar":""},{"name":"Eros Vlahos","avatar":""},{"name":"Blake Ritson","avatar":""},{"name":"Akin Gazi","avatar":""},{"name":"Lara Pulver","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
