INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-con-quy-cua-da-vinci-phan-2', 'Những Con Quỷ Của Da Vinci (Phần 2)', 'Da Vinci''s Demons (Season 2)', 'những con quỷ của da vinci (phần 2) da vinci''s demons (season 2) tom riley laura haddock elliot cowan hera hilmar gregg chillin eros vlahos blake ritson akin gazi lara pulver ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-x', 'Siêu Nhân X', 'X Superman', 'https://phimimg.com/upload/vod/20240911-1/213c21905a18ef1973c4b7f8611b6b4f.webp', 'https://phimimg.com/upload/vod/20240911-1/4ea872973f6d8c7d399a320d14301b74.webp', '<p>Nội dung bộ phim sẽ xoay quanh một chàng thanh niên trẻ tên Nam ngoại hình ốm yếu gầy còm là bất lợi lớn nhất của cuộc đời anh chàng, từ nhỏ đã bị các bạn trêu chọc và hiếp đáp. Đến khi trưởng thành Nam lúc nào cũng thấy mặc cảm với bản thân vì không làm được việc nặng, anh ước rằng một ngày nào đó thoát khỏi căn bệnh đang hoành hành trong người mình. Trong lúc lang thang dọc bờ sông, Nam nhìn thấy một vật phát sáng kì lạ, quyết định lội xuống để mang về nghiên cứu thì một luồng sáng mạnh phát ra và chiếm lấy cơ thể của Nam. Sáng hôm sau thức dậy Nam thấy mình cao hơn và cơ thể rắn chắc, và điều kì lạ hơn là sở hữu một luồn năng lượng cực kì mạnh mẽ. Nhằm muốn sử dụng sức mạnh của mình cho việc có ích Nam quyết định giấu mình trong một trang phục siêu nhân để hoạt động vào ban đêm.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Ngô Kiến Huy","avatar":""},{"name":"Thanh Hằng","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Phương Thanh","avatar":""},{"name":"Phạm Anh Khoa","avatar":""},{"name":"Diệp Lâm Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
