INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-den-tu-tuong-lai', 'Chàng Trai Đến Từ Tương Lai', 'Twa-Tiu-Tiann', 'https://phimimg.com/upload/vod/20231108-1/933a2511ca9fed0ac2e122f333d6daee.jpg', 'https://phimimg.com/upload/vod/20231108-1/f7d736841f7b442f99a928988cda2bd8.jpg', '<p>Thông qua bức tranh nổi tiếng &quot;Lễ hội đường phố phía Nam&quot;, một nam sinh đại học Đài Loan bất ngờ du hành ngược thời gian 100 năm, trở lại những năm 1920, khi Đài Loan nằm dưới sự cai trị của Nhật Bản. Anh ta bế tắc, anh ta hoảng loạn, anh ta muốn quay lại năm 2014 nhưng ngay sau đó anh ta đổi ý, không chỉ vì cô gái geisha xinh đẹp nhất thị trấn...</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Chris Wang","avatar":""},{"name":"Sonia Sui","avatar":""},{"name":"Jian Man-shu","avatar":""},{"name":"Chu-Ko Liang","avatar":""},{"name":"Bamboo Chen","avatar":""},{"name":"Cliff Cho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324455);
