INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-my-nuong-truyen-ky', 'Võ Mỵ Nương Truyền Kỳ', 'The Empress Of China', 'https://phimimg.com/upload/vod/20240909-1/7eb3afbd63fa0063f34c06887dcb5a69.jpg', 'https://phimimg.com/upload/vod/20240909-1/4a850f4dba0da7a55273d1a98688edad.jpg', '<p>Nhập cung năm 14 tuổi, cung nữ Võ Như Ý bắt đầu làm quen với cuộc sống đấu đá chốn thâm cung hậu đình. Chịu sự hãm hại, giày vò của quyền lực, nàng quyết định vùng lên làm chủ nó. Dần tập trung thế và lực, Võ Như Ý một bước lên ngôi Võ Hậu rồi trở thành người cai trị đất nước - nữ hoàng duy nhất trong lịch sử Trung Hoa.</p>', 'Hoàn Tất (82/82)', 82, 'series', 'completed', 10, 2014, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Băng Băng","avatar":""},{"name":"Châu Hải My","avatar":""},{"name":"Trương Phong Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324455);
