INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-ngay', '3 Ngày', '3 Days', 'https://phimimg.com/upload/vod/20240908-1/80301bc7615c5bd2a66d124230f174dd.jpg', 'https://phimimg.com/upload/vod/20240908-1/70d99d7f978451b2bc95f13faa5d9694.jpg', '<p>Ba phát súng được bắn và tổng thống Hàn Quốc đột nhiên mất tích khỏi biệt thự nghỉ dưỡng của mình. Three Days là một bộ phim kinh dị cô đọng kể về cuộc đấu tranh của vệ sĩ ưu tú của Nhà Xanh Han Tae Kyung để tìm và bảo vệ tổng thống. Với sự trợ giúp của cảnh sát địa phương Yoon Bo Won và những người đồng đội bảo vệ Nhà Xanh, liệu Han Tae Kyung có thể cứu được tổng thống trước khi quá muộn?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박유천","avatar":""},{"name":"손현주","avatar":""},{"name":"박하선","avatar":""},{"name":"소이현","avatar":""},{"name":"윤제문","avatar":""},{"name":"장현성","avatar":""},{"name":"민성욱","avatar":""},{"name":"조희봉","avatar":""},{"name":"최원영","avatar":""},{"name":"이재용","avatar":""},{"name":"남다름","avatar":""},{"name":"하준","avatar":""},{"name":"이현욱","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
