INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-vay-cuoi-dinh-menh', 'Bộ Váy Cưới Định Mệnh', 'Dress to Wed', 'https://phimimg.com/upload/vod/20231103-1/100948bd218aaa6216095047b64e5e6b.jpg', 'https://phimimg.com/upload/vod/20231103-1/ee307b676d8d45de50b07cc206c85787.jpg', '<p>Vào ngày cưới của mình, Fernando đã vô tình xé toạc chiếc váy được thiết kế riêng của một người phụ nữ có bạn trai là một kẻ nguy hiểm. Bây giờ, anh ấy không thể kết hôn cho đến khi thay chiếc váy.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Leandro Hassum","avatar":""},{"name":"Fernanda Rodrigues","avatar":""},{"name":"André Mattos","avatar":""},{"name":"Marcos Veras","avatar":""},{"name":"Renata Dominguez","avatar":""},{"name":"Tonico Pereira","avatar":""},{"name":"Catarina Abdala","avatar":""},{"name":"Érico Brás","avatar":""},{"name":"Adriana Garambone","avatar":""},{"name":"Júlia Rabello","avatar":""},{"name":"George Sauma","avatar":""},{"name":"Eliezer Motta","avatar":""},{"name":"Cláudio Tovar","avatar":""},{"name":"Ricardo Conti","avatar":""},{"name":"Álvaro Diniz","avatar":""},{"name":"Celso Taddei","avatar":""},{"name":"Paulo M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
