INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-vay-cuoi-dinh-menh', 'Bộ Váy Cưới Định Mệnh', 'Dress to Wed', 'bộ váy cưới định mệnh dress to wed leandro hassum fernanda rodrigues andré mattos marcos veras renata dominguez tonico pereira catarina abdala érico brás adriana garambone júlia rabello george sauma eliezer motta cláudio tovar ricardo conti álvaro diniz celso taddei paulo m ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-nha-bi-nguyen-rua', 'Tòa Nhà Bị Nguyền Rủa', 'Hollows Grove', 'https://phimimg.com/upload/vod/20231101-1/164c294ec3537122501a59b250beb5e4.jpg', 'https://phimimg.com/upload/vod/20231101-1/f8c0f52dad98e2e6c42337fe970d260c.jpg', '<p>Một nhà làm phim tài liệu trẻ tuổi đang theo đuổi đề tài về việc săn mồi ma quỷ. Một chương trình truyền hình thực tế với sự tham gia của nhưng người bạn của người làm phim tại một cô nhi viện bị bỏ rơi. Khi điều tra ở đây họ bị rơi vào cơn ác mộng và không thể trốn thoát được.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Henriksen","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Matthew Carey","avatar":""},{"name":"Sunkrish Bala","avatar":""},{"name":"Bresha Webb","avatar":""},{"name":"Eddie Perez","avatar":""},{"name":"Gary Sievers","avatar":""},{"name":"Tanc Sade","avatar":""},{"name":"Lindsey Smith-Sands","avatar":""},{"name":"Val Morrison","avatar":""},{"name":"Matt Doherty","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324455);
