INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-phau-tinh-yeu', 'Giải Phẫu Tình Yêu', 'Anatomy of a Love Seen', 'https://phimimg.com/upload/vod/20231101-1/7644f5aa71de89f4ca3ab00c2a0e0750.jpg', 'https://phimimg.com/upload/vod/20231101-1/66569067f09f99b4ab01f493aeea2425.jpg', '<p>Một bộ phim trong một bộ phim khám phá tình yêu trong tất cả những vinh quang đau đớn và lộn xộn của nó. Sáu tháng trước, Zoe và Mal đã yêu nhau khi đang quay một cảnh tình cảm, dẫn đến một cuộc tình dữ dội, sóng gió, sau đó là một cuộc chia tay tàn khốc. Ngay sau khi chia tay, mọi thứ trở nên phức tạp khi cả hai phải gặp nhau trên phim trường một lần nữa để quay lại cảnh định mệnh đó.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sharon Hinnendael","avatar":""},{"name":"Jill Evyn","avatar":""},{"name":"Constance Brenneman","avatar":""},{"name":"Marina Rice Bader","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
