INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi-thuc-day', 'Bóng Tối Thức Dậy', 'Dark Awakening', 'https://phimimg.com/upload/vod/20231101-1/b293392edcaf69df7af4b192b1e9bd33.jpg', 'https://phimimg.com/upload/vod/20231101-1/68f8834f3a070d2b22dda4758d3d8d23.jpg', '<p>Hai vợ chồng nhà James Thomas quyết định trở về sinh sống ở căn nhà của người mẹ vừa mới qua đời . Nhưng rồi tại đây, họ phải đối mặt với những bóng ma, những sự việc vô cùng khủng khiếp...khiến cuộc sống của họ biến thành địa ngục. Những bí mật của ngôi nhà dần dần được hé lộ nhưng cũng có nghĩa là mạng sống của các thành viên trong gia đình đang bị đe dọa...</p>', 'Full', 1, 'single', 'completed', 5, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Henriksen","avatar":""},{"name":"Jason Cook","avatar":""},{"name":"Valerie Azlynn","avatar":""},{"name":"William Pifer","avatar":""},{"name":"Lauren Sesselmann","avatar":""},{"name":"Robert Crayton","avatar":""},{"name":"Tracey Coppedge","avatar":""},{"name":"Gil Newsom","avatar":""},{"name":"Viktor Hernandez","avatar":""},{"name":"R. Keith Harris","avatar":""},{"name":"Karen Boles","avatar":""},{"name":"Vanelle","avatar":""},{"name":"Dave Geddis","avatar":""},{"name":"Cornelius Muller","avatar":""},{"name":"Marcella Rochelle","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
