INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-thinh-phong-van-3', 'Thiết Thính Phong Vân 3', 'Overheard 3', 'https://phimimg.com/upload/vod/20231101-1/c2391641342fdd8f992583171010e598.jpg', 'https://phimimg.com/upload/vod/20231101-1/6a9f2b5ff4c1f432d5ba8e8af18845e5.jpg', '<p>Nội dung bộ phim Thiết Thính Phong Vân 3 lần này sẽ lấy bối cảnh Trung Quốc những năm 80 của thế kỷ trước và đi sâu vào nội tâm của con người và tính cách của từng nhân vật qua lời thoại cũng như hành động của họ trong vai. Trải qua nhiều biến cố từ những mưu mô, kế sách và bí mật hay những màn đấu trí ngoạn mục của cảnh sát và bọn tội phạm, phần 3 tiếp theo hứa hẹn sẽ bức phá và đem lại nhiều gặt hái thành công cho ekip cũng như dàn diễn viên khủng này...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Huang Lei","avatar":""},{"name":"Ka Wah Lam","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Ying Kwan Lok","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Vincent Kok","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 178469032445