INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('poli-va-cac-ban-phan-3', 'Poli Và Các Bạn (Phần 3)', 'Robocar Poli (Season 3)', 'https://phimimg.com/upload/vod/20240630-1/178729488641c181e1a2d2e0017cea34.jpg', 'https://phimimg.com/upload/vod/20240630-1/583a19eae1d1d3e3206f2505dacd0fb6.jpg', '<p>Khi thảm họa xảy ra ở Thị trấn Brooms, xe cảnh sát Robocar Poli, xe cứu hỏa Robotruck Roy và những người bạn trong đội cứu hộ chạy đua để cứu thế giới.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 8, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324455);
