INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-6', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 6)', 'Star Wars: The Clone Wars (Season 6)', 'https://phimimg.com/upload/vod/20240624-1/781de7c0638a1c25a3c5525b6a963f0c.jpg', 'https://phimimg.com/upload/vod/20240624-1/cf1614f64cfdbc2ffbe04946443d17ea.jpg', '<p>Trong những tập phim được háo hức chờ đợi này, một số bí ẩn sâu sắc nhất về cuộc xung đột giữa mặt sáng và mặt tối của Thần lực đã được tiết lộ. Một người lính nhân bản dũng cảm phát hiện ra một bí mật gây sốc mà mỗi người lính của Cộng hòa đều mang theo. Mối quan hệ thân thiết nhất của Anakin Skywalker bị thử thách đến giới hạn khi một thượng nghị sĩ có thiện chí bị những kẻ chủ mưu của cuộc chiến thao túng. Kẻ thù độc ác trong quá khứ phát hiện ra một vũ khí cổ xưa có thể mang lại cho cô sức mạnh vô song. Và cuộc điều tra của Master Yoda về sự biến mất của Jedi đưa anh vào sâu hơn những bí ẩn của Thần lực, nơi những gì anh phát hiện ra có thể thay đổi mãi mãi cán cân quyền lực trong thiên hà.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324455);
