INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-bi-an-phan-2', 'Thị Trấn Bí Ẩn (Phần 2)', 'Gravity Falls (Season 2)', 'https://phimimg.com/upload/vod/20240831-1/36e2c1fe9a068edc409be36f2c9b5857.jpg', 'https://phimimg.com/upload/vod/20240831-1/9cd6f0ca12688871bf5e4726caf7e52e.jpg', '<p>Bộ phim kể về những cuộc phiêu lưu của hai anh em sinh đôi Dipper và Mabel Pines (12 tuổi), khi mà bố mẹ cho họ đến chơi với chú Stan ở một thị trấn của Gravity Falls, Oregon. &quot;Grunkle&quot; Stan sống và làm việc tại Lều Bí Ẩn, một cái bẫy du lịch nơi thu phí chỉ cho một cái nhìn tại bảo tàng kỳ lạ nhất thế giới này; nhưng Dipper và Mabel biết thật sự là một thứ kì lạ gì đó đang xảy ra và họ phải dựa vào nhau để sống trong thị trấn không quen thuộc ấy.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 14, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Ritter","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Alex Hirsch","avatar":""},{"name":"Linda Cardellini","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324455);
