INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-xu-la', 'Bác Sĩ Xứ Lạ', 'Doctor Stranger', 'https://phimimg.com/upload/vod/20240824-1/8c017a611202f0adf07a8e1044e19269.jpg', 'https://phimimg.com/upload/vod/20240824-1/e8127496f929e7dd4536c6646c504b8d.jpg', '<p>Bộ phim kể câu chuyện về Park Hoon (Lee Jong Suk), một cậu bé bị bắt cóc đến Triều Tiên cùng người cha bác sĩ. Ở Triều Tiên, Park Hoon được người cha của mình đào tạo thành bác sĩ. Park Hoon trở thành thiên tài phẫu thuật lồng ngực. Anh tìm cách trở về lại Hàn Quốc. Park Hoon được nhận vào làm tại bệnh viện danh tiếng nhất Hàn Quốc, bệnh viện Đại học Dong Woo nhưng anh lại cảm thấy mình như người ngoài. Để mang vể tình yêu của mình ở Bắc Hàn, anh làm bất cứ điều gì có thể để kiếm tiền...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이종석","avatar":""},{"name":"박해진","avatar":""},{"name":"진세연","avatar":""},{"name":"강소라","avatar":""},{"name":"전국환","avatar":""},{"name":"이일화","avatar":""},{"name":"최정우","avatar":""},{"name":"김지영","avatar":""},{"name":"박해준","avatar":""},{"name":"정인기","avatar":""},{"name":"윤보라","avatar":""},{"name":"천호진","avatar":""},{"name":"Goo Seung-hyun","avatar":""},{"name":"김보미","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324455);
