INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-nu-va-hoang-tu-hac-am', 'Lang Nữ và Hoàng Tử Hắc Ám', 'Wolf Girl and Black Prince', 'https://phimimg.com/upload/vod/20240819-1/bc42a17a52cfc1b453d01461fd9169da.jpg', 'https://phimimg.com/upload/vod/20240819-1/0ad719452def96e5c7618f57073fa830.jpg', '<p>Lang Nữ và Hoàng Tử Hắc Ám - Wolf Girl and Black Prince - Erika Shinohara đã nói dối về những chiến công lãng mạn của mình để nhận được sự tôn trọng của những người bạn mới. Vì vậy, khi họ yêu cầu một bức ảnh của bạn trai của cô ấy, cô ấy đã vội vàng chụp một bức ảnh của một người lạ đẹp trai, người mà bạn bè của cô ấy nhận ra là Kyouya Sata nổi tiếng và tốt bụng.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"櫻井孝宏","avatar":""},{"name":"伊藤かな恵","avatar":""},{"name":"茅野愛衣","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"松岡禎丞","avatar":""},{"name":"村瀬歩","avatar":""},{"name":"伊瀬茉莉也","avatar":""},{"name":"小松未可子","avatar":""},{"name":"島﨑信長","avatar":""},{"name":"久川綾","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
