INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-18-sat-thu-ban-tia-khong-tuong', 'Thám Tử Lừng Danh Conan 18: Sát Thủ Bắn Tỉa Không Tưởng', 'Detective Conan: Dimensional Sniper', 'https://phimimg.com/upload/vod/20231019-1/abfa01c132134c3b37b1a9ab549ead27.jpg', 'https://phimimg.com/upload/vod/20231019-1/787e75c42da9242585200ce6bf525b42.jpg', '<p>Một cựu lính bắn tỉa của &quot;Biệt đội hải cẩu&quot; hay còn gọi là SEALs (một nhánh đặc nhiệm tinh nhuệ của hải quân Hoa Kỳ, nhóm thường tham chiến tại chiến trường Trung Đông, tiêu diệt khủng bố, và Osama Binladen cũng do SEALs tiêu diệt) tên là Hunter bị tình nghi dính dáng đến 1 vụ giết người hàng loạt bằng súng bắn tỉa. Nạn nhân là những cựu thành viên của SEALs và những người có thù oán với Hunter.&nbsp; Mỗi vụ đều để lại 1 con xúc xắc với các mặt khác nhau và 1 vỏ đạn rỗng. Cả phía FBI cũng tham gia vào vụ này. Ân oán uẩn khúc bên trong là gì? Phía cảnh sát phải làm gì để bảo vệ những mục tiêu tiếp theo? Hãy cùng xem 110 phút cân não, cuộc đấu giữa những cái đầu và cả những tay snipper không tưởng. Chỉ có snipper mới hạ được ...</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2014, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Noriko Hidaka","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Miyuki Ichijou","avatar":""},{"name":"Iemasa Kayumi","avatar":""},{"name":"Kiyoyuki Yanada","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Yukik","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
