INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-trinh-tom-va-jerry-phan-2', 'Chương Trình Tom Và Jerry (Phần 2)', 'The Tom And Jerry Show (Season 2)', 'https://phimimg.com/upload/vod/20240807-1/083d76916c2da872d9c55608829bf07f.jpg', 'https://phimimg.com/upload/vod/20240807-1/3656441e25acbc101a6adc69073a32e5.jpg', '<p>Đối thủ mèo và chuột mang tính biểu tượng đã trở lại trong một diện mạo mới của loạt phim cổ điển. Giữ nguyên hình thức, nhân vật và cảm giác của nguyên tác, loạt phim này chiếu một lăng kính có độ phân giải cao, màu sắc rực rỡ vào những pha hài hước điên rồ và trận chiến không hồi kết đã khiến Tom và Jerry trở thành hai trong số những nhân vật được yêu thích nhất mọi thời đại.</p>', 'Hoàn Tất (74/74)', 74, 'series', 'completed', 6, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rick Zieff","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Stephen Stanton","avatar":""},{"name":"Joey D''Auria","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Sam Kwasman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
