INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-quyen-2014', 'Sát Quyền', 'Kung Fu Jungle', 'https://phimimg.com/upload/vod/20231103-1/b7e668f694388d101e60fe946fe6331c.jpg', 'https://phimimg.com/upload/vod/20231103-1/91bc1f2e4af70e18e90e59af2f1fd4b1.jpg', '<p>Để đổi lấy sự tự do của chính mình, một cựu võ sư bị kết tội giết người đề nghị truy bắt một tên sát nhân xảo quyệt đang hoành hành ngoài vòng pháp luật.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Bai Bing","avatar":""},{"name":"Deep Ng Ho-Hong","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Mang Hoi","avatar":""},{"name":"Bey Logan","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Billy Chan","avatar":""},{"name":"Teddy Chan","avatar":""},{"name":"Bruce Law","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Andrew Lau Wai-Keung","avatar":""},{"name":"Sharon Yeun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324455);
