INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-quyen-2014', 'Sát Quyền', 'Kung Fu Jungle', 'sát quyền kung fu jungle donnie yen charlie yeung baoqiang wang bai bing deep ng ho-hong yu kang xing yu louis fan siu-wong mang hoi bey logan alex fong david chiang da-wei yuen cheung-yan billy chan teddy chan bruce law yuen bun andrew lau wai-keung sharon yeun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-elza-yeu-dau', 'Gửi Elza Yêu Dấu', 'Dear Elza!', 'https://phimimg.com/upload/vod/20240804-1/1515a50d052a25124adfe359d141ebd4.jpg', 'https://phimimg.com/upload/vod/20240804-1/e34c953090296856a5f25f7e83b6bac2.jpg', '<p>Cuối năm 1942, Ukraine, mặt trận phía đông. Binh nhì Lombos (Gábor Makray), một người lính trung thành với quê hương, người có mong muốn duy nhất khi còn là sinh viên năm nhất là được gặp lại người vợ trẻ của mình, phục vụ tại đây. Tuy nhiên, do lỗi hành chính nên anh bị lỡ chuyến tàu về nhà. Anh ấy nghĩ mọi chuyện không thể tệ hơn được nữa, nhưng địa ngục thực sự chỉ mới bắt đầu. Người giáo viên trẻ có học thức, nói được 3 thứ tiếng, tuyệt vọng hoàn thành nghĩa vụ của mình, lại cầm vũ khí và hành quân về Mặt trận phía Đông. Anh ta bị thương trong một cuộc tấn công và sống sót qua đêm sau phòng tuyến của kẻ thù trong một cái hố. Đây là lúc anh gặp một ông già bí ẩn (Tamás Varga), và cuộc gặp gỡ này đã thay đổi mọi thứ. Lời nói của ông lão làm lung lay niềm tin không thể lay chuyển của ông vào gia đình quân nhân và quê hương. Vào lúc bình minh, binh lính Nga tìm thấy họ, Lombos bị bắt và sau đó bị mắc kẹt trong số những “kẻ giẫm đạp”. Ông già sau đó cũng xuất hiện trong hàng ngũ của kẻ thù, đi trong bóng tối và cố gắng giữ cho người lính trẻ sống sót bằng mọi giá bằng lời khuyên của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'FHD', 'Hungary', 0, '[{"name":"Géza Bodor","avatar":""},{"name":"Gábor Makray","avatar":""},{"name":"István Péntek","avatar":""},{"name":"Tamás Varga","avatar":""},{"name":"Zsuzsanna Ripli","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
