INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-day-phan-4', 'Mặt Dày (Phần 4)', 'Shameless (Season 4)', 'https://phimimg.com/upload/vod/20240731-1/553893971fe2790c069d0e9ac35cd1d4.jpg', 'https://phimimg.com/upload/vod/20240731-1/2554a10959832051ab73350a388823cc.jpg', '<p>Diễn viên từng được đề cử giải Oscar William H. Macy đóng vai Frank Gallagher, một người cha độc thân của sáu người dành phần lớn thời gian rảnh của mình để uống rượu tại các quán bar. Những đứa trẻ Gallagher - dẫn đầu bởi cô con gái lớn nhất Fiona (Emmy Rossum), người đảm nhận phần lớn trách nhiệm nuôi dạy con do vắng mặt mẹ - cố gắng tự nuôi mình mặc dù Frank không có cách nuôi dạy con cái và cách nuôi dạy khác thường khi anh làm chọn hành động như một người cha. Bộ phim là bộ phim chuyển thể từ chương trình cùng tên của người Anh từng đoạt giải BAFTA.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"William H. Macy","avatar":""},{"name":"Jeremy Allen White","avatar":""},{"name":"Ethan Cutkosky","avatar":""},{"name":"Shanola Hampton","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Emma Kenney","avatar":""},{"name":"Christian Isaiah","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Kate Miner","avatar":""},{"name":"Paris Newton","avatar":""},{"name":"Scott Michael Campbell","avatar":""},{"name":"Elise Eberle","avatar":""},{"name":"Dennis Cockrum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
