INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-anh-quoc-phan-2', 'Bóng Ma Anh Quốc (Phần 2)', 'Peaky Blinders (Season 2)', 'https://phimimg.com/upload/vod/20240730-1/5fc4d4daf6e8bb455ead8e32c81497dc.jpg', 'https://phimimg.com/upload/vod/20240730-1/ff8f503bdc2d2f847a44df770dcd214d.jpg', '<p>Một băng đảng khét tiếng xuất hiện ở Birmingham, Anh Quốc năm 1919. Cầm đầu băng là Tommy Shelby, tên trùm tội phạm khét tiếng muốn nổi lên bằng mọi giá.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2014, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Jeffrey Postlethwaite","avatar":""},{"name":"Matthew Postlethwaite","avatar":""},{"name":"Ian Pe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
