INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-noi-loan-phan-2', 'Tuổi Nổi Loạn (Phần 2)', 'Hormornes (Season 2)', 'https://phimimg.com/upload/vod/20240729-1/3b2e9cb2a74d37020fd76eb1e008618c.jpg', 'https://phimimg.com/upload/vod/20240729-1/313924473fdfe9dcde7db74b14f6d4ea.jpg', '<p>Hormones: the Series (tên đầy đủ: Hormones วัยว้าวุ่น, RTGS: ~ Wai Wa Wun; tựa đề tiếng Việt: Tuổi nổi loạn) là sê-ri truyền hình tuổi teen Thái Lan được sản xuất bởi GTH và Nadao Bangkok, chiếu trên kênh GMM One với đánh giá phân loại PG-13. Bộ phim kể về cuộc sống và các mối quan hệ của một nhóm học sinh trung học khi trải qua cuộc sống gia đình và trường học và phải đối mặt với các vấn đề khác nhau. Phá vỡ khuôn mẫu của truyền hình Thái Lan, vốn nổi bật về phim truyện truyền hình và sitcom, Hormones đã được hình thành với một phong cách thường thấy ở Hoa Kỳ với các vấn đề gây tranh cãi như quan hệ tình dục thiếu niên và mang thai, đồng tính luyến ái và bạo lực học đường.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2014, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thiti Mahayotaruk","avatar":""},{"name":"Nichaphat Chatchaipholrat","avatar":""},{"name":"Narikun Ketprapakorn","avatar":""},{"name":"ศนันธฉัตร ธนพัฒน์พิศาล","avatar":""},{"name":"ธีรดนย์ ศุภพันธุ์ภิญโญ","avatar":""},{"name":"Kanyawee Songmuang","avatar":""},{"name":"Kemisara Paladesh","avatar":""},{"name":"ต้นหน ตันติเวชกุล","avatar":""},{"name":"Sarit Trilertvichien","avatar":""},{"name":"Nutchapan Paramacharenroj","avatar":""},{"name":"วงศ์รวี นทีธร","avatar":""},{"name":"Narupornkamol Cha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
