INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-kiem-khach', 'Oan Gia Kiếm Khách', 'The Sentimental Swordsman', 'https://phimimg.com/upload/vod/20240713-1/9e4fc42861166042490a3f715a2eefd5.jpg', 'https://phimimg.com/upload/vod/20240713-1/3d658efa8005120f02f4b99551116983.jpg', '<p>Oan Gia Kiếm Khách là bộ phim xoay quanh câu chuyện của ba chị em bị phân ly từ nhỏ. Họ lớn lên trong những hoàn cảnh khác nhau nên đã hình thành lên trong họ ba tính cách hoàn toàn khác biệt.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 7, 2014, 'Thuyết Minh', 'FullHD', 'Trung Quốc', 0, '[{"name":"Lý Dịch Phong","avatar":""},{"name":"Từ Đông Đông","avatar":""},{"name":"Dĩnh Nhi","avatar":""},{"name":"Diệp Tổ Tân","avatar":""},{"name":"Chu Huệ Trân","avatar":""},{"name":"Dương Hiểu Dung","avatar":""},{"name":"Lạc Tang Niệm Trát","avatar":""},{"name":"Ngô Thiên Ngữ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
