INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oan-gia-kiem-khach', 'Oan Gia Kiếm Khách', 'The Sentimental Swordsman', 'oan gia kiếm khách the sentimental swordsman lý dịch phong từ đông đông dĩnh nhi diệp tổ tân chu huệ trân dương hiểu dung lạc tang niệm trát ngô thiên ngữ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-2', '100 Người Thử Nghiệm (Phần 2)', 'The 100 (Season 2)', 'https://phimimg.com/upload/vod/20240616-1/8c4e57a2689700cfed0239bd738319df.jpg', 'https://phimimg.com/upload/vod/20240616-1/cdf1511adebdd4b985b34354e9649c6c.jpg', '<p>Phần 2 tiếp diễn sau khi The Ark sụp đổ, những người cầm quyền cũng như đa số con người đang trú ngụ trên vệ tinh sau cuối này kế cận cái chết buộc phải phải trở lại con người vì hết oxy dự trữ. Họ không thể đợi đến khi sứ mạng thí nghiệm của 100 tù túng hoàn tất nữa. Câu chuyện sẽ diễn ra như thế nào? Liệu từ giờ ai sẽ là người chỉ huy khi 100 tù túng trước đây phải chịu sự chỉ huy của những người cầm quyền trên The Ark giờ đây lại có những kinh nghiệm sinh tồn trên con người hơn hẳn họ...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Morley","avatar":""},{"name":"Eliza Taylor","avatar":""},{"name":"Marie Avgeropoulos","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
