INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-1', '100 Người Thử Nghiệm (Phần 1)', 'The 100 (Season 1)', 'https://phimimg.com/upload/vod/20240616-1/47b4e88959c8e479ba6bd31719bc999a.jpg', 'https://phimimg.com/upload/vod/20240616-1/751e7cb9c9e4ed8a7401ab5fa66e3c71.jpg', '<p>Lấy bối cảnh tương lai, 97 năm sau khi một thảm họa hạt nhân xảy ra, một bộ phận loài người thoát nạn và đã sống bên ngoài vũ trụ được ba thế hệ. Khi nguồn tài nguyên ngày một cạn kiệt, họ quyết định đưa 100 tội phạm thiếu niên xuống Trái Đất. Chuyện trở nên rắc rối khi 100 thiếu niên này quyết định nổi loạn.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Eliza Taylor","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Bob Morley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
