INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-ong-dich-thuc-2', 'Đàn Ông Đích Thực 2', 'Think Like a Man Too', 'https://phimimg.com/upload/vod/20231101-1/d9f7deca2aa8bcc01945d53271e5ffbd.jpg', 'https://phimimg.com/upload/vod/20231101-1/8ea4b4ca8629cd4ddb155d89c99d9b82.jpg', '<p>Một đám cưới lãng mạn cuối tuần ở Las Vegas bỗng rối tung khi hai phe đàn ông và phụ nữ cố gắng hơn thua nhau trong một đêm ăn chơi trác táng.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Terrence Jenkins","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Gary Owen","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"David Walton","avatar":""},{"name":"La La Anthony","avatar":""},{"name":"Jim Piddock","avatar":""},{"name":"We","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324455);
