INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dan-ong-dich-thuc-2', 'Đàn Ông Đích Thực 2', 'Think Like a Man Too', 'đàn ông đích thực 2 think like a man too kevin hart michael ealy jerry ferrara meagan good regina hall dennis haysbert taraji p. henson terrence jenkins jenifer lewis romany malco wendi mclendon-covey gary owen gabrielle union adam brody david walton la la anthony jim piddock we ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-luan-hoi', 'Cuộc Chiến Luân Hồi', 'Edge of Tomorrow', 'https://phimimg.com/upload/vod/20231021-1/78ff73981259f02720af40ac8855609e.jpg', 'https://phimimg.com/upload/vod/20231021-1/2287784e215a7cf82500aedbb19dab05.jpg', '<p>Trung tá Bill Cage (do nam diễn viên gạo cội Tom Cruise thủ vai) vốn là một sĩ quan chưa bao giờ tham gia chiến trận thực sự. Nhưng, anh đã bị buộc thực hiện một nhiệm vụ chẳng khác nào tìm đường chết, khi chủng tộc người ngoài hành tinh xâm lược trái đất bằng những cuộc tàn sát đẫm máu với những vũ khí huỷ diệt và chẳng có một lực lược nào trên trái đất có thể chống lại chúng. Cũng từ đây, vị trung tá trẻ tuổi Bill Cage rơi vào vòng tròn không hồi kết: chiến đấu- chết- sống lại- chiến đấu…Mọi thứ dường như rơi vào bế tắc. Chính vào lúc người trung tá gần với tuyệt vọng thì anh đã phát hiện ra rằng, sau mỗi trận đánh anh có thể hiểu rõ đối thủ hơn và học được những kỹ năng chiến đấu tốt hơn. Đồng hành cùng anh là&nbsp; Rita Vrataski (do diễn viên Emily Blunt thủ vai) chiến binh siêu hạng của lực lượng đặc nhiệm. Họ đồng hành với nhau, cùng khám phá ra những bí mật và kỹ năng mới để chiến đấu với bọn người xâm lược.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Kick Gurry","avatar":""},{"name":"Dragomir Mrsic","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"Jonas Armstrong","avatar":""},{"name":"Franz Drameh","avatar":""},{"name":"Masayoshi Haneda","avatar":""},{"name":"Tony Way","avatar":""},{"name":"Terence Maynard","avatar":""},{"name":"Lara Pulver","avatar":""},{"name":"Madeleine Mantock","avatar":""},{"name":"Assly Zandry","avatar":""},{"name":"Sebastian Blunt","avatar":""},{"name":"Bet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324455);
