INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-7', 'Gã Điên (Phần 7)', 'Mad Men (Season 7)', 'https://phimimg.com/upload/vod/20240606-1/b687637230f3d48b1770f39745d59439.jpg', 'https://phimimg.com/upload/vod/20240606-1/b88d44dade77be3edcd2118ae554fa0a.jpg', '<p>Phần đầu tiên của phần 7 bắt đầu vào tháng 1 năm 1969, vài tuần sau khi Lễ tạ ơn năm 1968 kết thúc phần 6 và kết thúc vào tháng 7 năm 1969, với các nhân vật đối phó với sự năng động của cuộc sống và văn phòng được phân chia giữa New York và Los Angeles.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2014, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
