INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-quan-gia-phan-3', 'Hắc Quản Gia (Phần 3)', 'Black Butler (Season 3)', 'https://phimimg.com/upload/vod/20240302-1/1930bf9c626d0a972e29844d5ddaaa98.jpg', 'https://phimimg.com/upload/vod/20240302-1/0bbfcec001aec2414a2eb68474d987e1.jpg', '<p>Đầy kinh ngạc và phấn khích, đoàn ca kịch Noah Arc Circus đã thu phục khán giả bằng những màn trình diễn mãn nhãn của họ. Tuy nhiên, những hành động tuyệt vời này không đến mà không có giá. Trẻ em đã mất tích một cách bí ẩn xung quanh London, tương quan với phong trào của các nhóm. Không lo lắng trước những vụ bắt cóc này, Nữ hoàng Victoria đã gửi con chó bảo vệ khét tiếng của mình, Ciel Phantomhive, và người quản gia quỷ trung thành của ông, Sebastian Michaelis, thực hiện một nhiệm vụ bí mật để tìm những đứa trẻ mất tích này. Tuy nhiên, cố gắng cân bằng các tiết mục xiếc mới của họ với cuộc điều tra bí mật của họ dưới đỉnh lớn, được chứng minh là một thách thức khá lớn. Với việc những người biểu diễn khác ngày càng nghi ngờ và mối đe dọa từ ân nhân bí ẩn của rạp xiếc đang rình rập trên đầu, những gì hai người khám phá ra sẽ khiến Ciel bị lung lay về cốt lõi của mình.</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 6, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324455);
