INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-son-tiem-long', 'Hàn Sơn Tiềm Long', 'Ghost Dragon Of Cold Mountain', 'https://phimimg.com/upload/vod/20240302-1/51e580e366be9516635e0ed0eba16f64.jpg', 'https://phimimg.com/upload/vod/20240302-1/ec1a75e4e32df0527f7be033f1861894.jpg', '<p>Vào thời Bắc Tống, Thiên Ky Phủ do Phụng Nam Thiên đứng đầu lãnh đạo một nhóm các người ưu tú chuyên điều tra các vụ kỳ án trên toàn quốc. Sức mạnh và quyền lực của họ vượt trội hẳn so với các nha môn khác kể cả Lục Bộ. Chỉ huy Chu Trường Thắng dũng trí song toàn được sư phụ Nam Thiên đánh giá cao, nhưng vì một vụ án cướp của đã khiến hai sư đệ đường ai nấy đi. Trường Thắng dắt vợ là Đào Hoa ẩn dật giang hồ gần 10 năm cho đến khi vụ án đã được kết lại gần đây. Vì Nam Thiên tuổi đã cao nên Mã Xuyên Khung, Ngưu Đại Lực và Dương Mão được lệnh triệu Trường Thắng quay về, thế là bốn người lại có cơ hội đồntg tâm hợp lực phá được nhiều vụ án lớn. Thế nhưng vì tính cách khác nhau nên thường xảy ra nhiều bất đồng. Vì hiểu lầm Trường Thanh và Đào Hoa chia tay nhưng anh lại gặp được cô kỳ nữ Ân Mi Nương người có ngoại hình giống hệt Đào Hoa. Cũng trong lúc này, Trường Thanh phát hiện có tay sai của bọn Kim Quốc ẩn náo trong Thiên Ky Phủ, tặc ta khó phân …</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 22, 2014, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Mã Quốc Minh","avatar":""},{"name":"Ngạo Gia Niên","avatar":""},{"name":"Trần Quốc Bang","avatar":""},{"name":"Lý Thi Vận","avatar":""},{"name":"Lâm Hạ Vy","avatar":""},{"name":"Tào Vĩnh Liêm","avatar":""},{"name":"Lưu Giang","avatar":""},{"name":"Hàn Mã Lợi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c296