INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-bien', 'Dị Biến', 'The Anomaly', 'https://phimimg.com/upload/vod/20240228-1/c1d53f23e98fa3d438b79d62c101909f.jpg', 'https://phimimg.com/upload/vod/20240228-1/602e65467c5c617853be13b044fb3ed2.jpg', '<p>Một cựu quân nhân bị bắt và tỉnh dậy ở phía sau một chiếc xe tải, nơi anh ta biết rằng mình chỉ có chưa đầy 10 phút để tìm ra cách mình đến đó.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Alexis Knapp","avatar":""},{"name":"Victoria Broom","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Ian Somerhalder","avatar":""},{"name":"Noel Clarke","avatar":""},{"name":"Luke Hemsworth","avatar":""},{"name":"Michael Bisping","avatar":""},{"name":"Art Parkinson","avatar":""},{"name":"Ali Cook","avatar":""},{"name":"Reuben Dabrow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324455);
