INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-joseon', 'Tay Súng Joseon', 'Gunman In Joseon', 'https://phimimg.com/upload/vod/20240229-1/1eb70cd2f2cf7dc375d6cced84c18c55.jpg', 'https://phimimg.com/upload/vod/20240229-1/b66e3af8aa8e2be9729e4846caa37cdd.jpg', '<p>Phim Tay Súng Joseon lấy bối cảnh vào thế kỉ 19, là thời kì có nhiều biến động sâu sắc, bộ phim khắc họa được lòng dũng cảm cũng như nỗi đau của người thanh niên trẻ tuổi Park Yoon Kang, là con trai của đệ nhất kiếm Joseon, vì báo thù cho cha và em gái của mình, đã từ bỏ đao kiếm, trở thành tay súng cừ khôi. Nhân vật Park Yoon Kang của Lee Jun Ki là kiếm khách cuối cùng của thời đại Joseon. Đây là tuyến nhân vật anh hùng của dân tộc, là tay súng được sinh ra giữa loạn lạc chuyển giao thời đại. Nam Sang Mi trong vai Jeong Su In, là người con gái được nuôi dưỡng như bông hoa trong nhà kính, sau đó, nhờ định mệnh, cô đã thay đổi hoàn toàn, trở thành người con gái mạnh mẽ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 15, 2014, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Joon Gi","avatar":""},{"name":"Han Joo Wan","avatar":""},{"name":"Nam Sang Mi","avatar":""},{"name":"Yoo Oh Sung","avatar":""},{"name":"Jeon Hye Bin","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324455);
