INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-lanh-kinh-hoang', 'Kho Lạnh Kinh Hoàng', 'Freezer', 'https://phimimg.com/upload/vod/20240227-1/5f2c6720076f4d3c51512460bcfcabfd.jpg', 'https://phimimg.com/upload/vod/20240227-1/e65d5a1b6176ee918816bbae5047d322.jpg', '<p>Thợ máy thành phố New York Robert Saunders bị côn đồ người Nga đánh bất tỉnh trong bữa tối sinh nhật của mình và tỉnh dậy thì thấy mình bị nhốt bên trong tủ đông công nghiệp của nhà hàng. Băng đảng tàn nhẫn này yêu cầu anh ta trả lại 8 triệu đô la mà anh ta đã đánh cắp từ chúng. Vấn đề duy nhất Robert không biết họ đang nói về cái gì. Nhưng khi nhiệt độ giảm xuống và nỗi kinh hoàng ngày càng lớn, sự thật gây sốc bắt đầu lộ ra khi Robert phải vật lộn để sống sót.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan McDermott","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Yuliya Snigir","avatar":""},{"name":"Milan Malisic","avatar":""},{"name":"Rafael Petardi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
