INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-tho-giay-vui-tinh', 'Chàng Thợ Giày Vui Tính', 'The Cobbler', 'https://phimimg.com/upload/vod/20240227-1/aa3fa2f5d108b4a36901c5bf65633062.jpg', 'https://phimimg.com/upload/vod/20240227-1/ba87cc0977f541fabfe7196d5d1ff0f7.jpg', '<p>Max Simkin sửa giày trong cùng một cửa hàng ở New York đã gắn bó với gia đình ông qua nhiều thế hệ. Chán nản với guồng quay của cuộc sống hàng ngày, Max tình cờ tìm thấy một vật gia truyền kỳ diệu cho phép anh bước vào cuộc sống của những khách hàng của mình và nhìn thế giới theo một cách mới. Đôi khi bước vào vị trí của một người đàn ông khác là cách duy nhất một người có thể khám phá ra họ thực sự là ai.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Ellen Barkin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
