INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-chet-nguoi', 'Phi Vụ Chết Người', 'Stretch', 'https://phimimg.com/upload/vod/20240220-1/85c176aaad21d7e39e775195ec41199a.jpg', 'https://phimimg.com/upload/vod/20240220-1/3e6e51f5683d6c82ed5cd16ddfb1a9c8.jpg', '<p>Phi Vụ Chết Người - Stretch là bộ phim hài hước, hành động phiêu liêu, hình sự tội phạm Mỹ 2014 của đạo diễn Joe Carnahan. Bộ phim xoay quanh một anh chàng đang tuyệt vọng trong tình yêu, và không bao giờ tin vào định mệnh, Stretch (Patrick Wilson). Anh tiếp tục sống những tháng ngày còn lại là một tay lái xe limo dạn dày kinh nghiệm để lấp đầy những khoản nợ do sở thích nghiện sách của anh. Tưởng cuộc sống sẽ mãi tẻ nhạt như thế cho đến ngày vị kháchđiên của anh đến. Từ đó, anh dính dáng vào chuỗi sự kiện liên quan đến rửa tiền, FBI, tội phạm khiến anh hiểu rằng việc gì xảy ra cũng có lý do của nó và hiện thực càng phũ phàng, anh càng thể hiện mình tốt hơn. Cuối cùng, như một sự sắp đặt của định mệnh, anh đã tìm được tình yêu của đời mình.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Norman Reedus","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Jessica Alba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324455);
