INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-tung-phan-4', 'Tố Tụng (Phần 4)', 'Suits (Season 4)', 'https://phimimg.com/upload/vod/20240215-1/0fcf578f9ec4d22ff3936515ab1826bb.jpg', 'https://phimimg.com/upload/vod/20240215-1/33da1b04988f167caf08fcc35443aade.jpg', '<p>Suit - Season 4 bắt đầu sau 3 tháng kể từ khi Mike chấp nhận lời đề nghị công việc ngân hàng đầu tư Jonathan Sidwell. Liệu cuộc chiến lần này sẽ mang lại nhiều hậu quả và kết quả sao khi vẫn còn rất nhiều bí mật trong nhiều mối quan hệ khác nhau dần được hé lộ. Và liệu rằng cuộc đụng độ giữa Mike với Harvey sẽ đi đến đâu khi chính Harvey là người không tán thành chiến lược của mình...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Gina Torres","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
