INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanasaki-mai-khong-im-lang-phan-1', 'Hanasaki Mai Không Im Lặng (Phần 1)', 'Hanasaki Mai Speaks Out (Season 1)', 'https://phimimg.com/upload/vod/20240215-1/b83f64eed08ba7a362b4d33b08da7426.jpg', 'https://phimimg.com/upload/vod/20240215-1/4f6418f51ded857d658d648ab4920f52.jpg', '<p>Trên cương vị mới là thanh tra nội bộ ngân hàng, một người già lập dị phải hợp tác với một phụ nữ không bao giờ ngần ngại lên tiếng khi chứng kiến hành vi sai trái.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Anne","avatar":""},{"name":"Kamikawa Takaya","avatar":""},{"name":"Tsukaji Muga","avatar":""},{"name":"Narimiya Hiroki","avatar":""},{"name":"Enoki Takaaki","avatar":""},{"name":"Ishibashi Ryo","avatar":""},{"name":"Komoto Masahiro","avatar":""},{"name":"Osugi Ren","avatar":""},{"name":"Namase Katsuhisa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
