INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-neo-tinh-yeu', 'Muôn Nẻo Tình Yêu', 'Only Love', 'https://phimimg.com/upload/vod/20240215-1/ef1c67a4e8c724f179f032d914d6dfa8.jpg', 'https://phimimg.com/upload/vod/20240215-1/7d8a2886afa224166c14c9f392029bd7.jpg', '<p>Muôn Nẻo Tình Yêu là một câu chuyện kể mối quan hệ tình cảm giữa 6 con người trẻ tuổi xoay quanh mối quan hệ giữa con ruột và con nuôi, khoảng cách giàu và nghèo, vượt qua định kiến của tuổi trẻ, và những tình cảm gia đình ấm áp xoay quanh họ.Kim Tae Yang một bác sĩ tài giỏi với trái tim đầy lòng nhân hậu và bác ái. Từ nhỏ Tae Yang sống với Kim Sang Bae bố của mình. Tuy nhiên, sau nhiều biến cố ập đến thì sự thật về thân phận của Tae Yang được tiết lộ, Kim Sang Bae không phải bố ruột của anh mà là chú ruột. Ngay từ khi còn bé cha mẹ của Tae Yang vì quá nghèo không đủ điều kiện để nuôi cậu nên đã đưa Sang Bae cưu mang. Không chấp nhận sự thật, Tae Yang vẫn cố gắng vùi lấp quá khứ để có thể sống tiếp một cuộc sống bình thường. Yoo Ri, một cô gái làm việc tại đài truyền hình, đã gặp Tae Yang trong một chương trình trải lòng của đài, được lắng nghe và tâm sự về cuộc đời của Tae Yang đã khiến cho trái tim Yoo Ri phải day dứt, và dành tình cảm cho anh.</p>', 'Hoàn Tất (95/95)', 95, 'series', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Seo Ha Joon","avatar":""},{"name":"Im Se Mi","avatar":""},{"name":"Nam Bo Ra","avatar":""},{"name":"Lee Gyu Han","avatar":""},{"name":"Yoon Jong Hoon","avatar":""},{"name":"Kim Ye Won","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
