INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tro-lai', 'Tình Yêu Trở Lại', 'Love Is Back', 'https://phimimg.com/upload/vod/20240209-1/4c278194fe907c7a470cf8c854effad2.jpg', 'https://phimimg.com/upload/vod/20240209-1/c782f91d4ad6f388386655300e60d2d8.jpg', '<p>Trong phim Tình Yêu Trở Lại, thời đại nam nữ trẻ tuổi, đứng trước cánh cửa hôn nhân bàng hoàng do dự không ít. Minh Lượng và Cao Kiến là đối thủ một mất một còn, nhưng hai người đều chống lại hôn nhân, hi vọng chỉ nói đến tình yêu không có trách nhiệm, ai người sống chung với nhau, trở thành một đôi bí mật. Trong thời gian chung sống cả hai dần nảy sinh tình cảm, nhưng rồi lại sợ quan hệ càng lúc càng đến gần, khiến hai bên xung đột không ngừng. Tiểu thư Bao Niệm Niệm bị bác sĩ thú y Phương Tư Tề thu hút, chủ động theo đuổi lại không cẩn thận mang thai, bị cha mẹ hai bên bức hôn. Lúc nhận kết quả Niệm Niệm vô ý sinh non thì đã không còn lý do để kết hôn, quan hệ với Tư Tề càng lúc càng mỏng manh, nhưng Tư Tề lại nghĩ ra một cách quan hệ hôn nhân mới để giữ lại Niệm Niệm.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 13, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thích Vy","avatar":""},{"name":"Khương Nghiên","avatar":""},{"name":"Vương Truyền Quân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324455);
