INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-hai', 'Thiệt Hại', 'Gossip High', 'https://phimimg.com/upload/vod/20240209-1/23afacc39ac99dcf1c04a322b06caedb.jpg', 'https://phimimg.com/upload/vod/20240209-1/bc4f5894b8c94452696a017671d6acea.jpg', '<p>Phim Thiệt Hại: xoay quanh mối quan hệ phức tạp của nữ phóng viên Địch Nhất Đào và ngôi sao Kim Thành Gia Huy. Nhất Đào chịu áp lực từ tổng biên tập buộc phải có tin tức hot nhất để lên báo nên luôn rình rập tìm cơ hội săn tin tức và vô tình phát hiện được bí mật động trời của Kim Thành Gia Huy.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Chính Hy","avatar":""},{"name":"Tống Tổ Nhi","avatar":""},{"name":"Tống Hải Giáp","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
