INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thiet-hai', 'Thiệt Hại', 'Gossip High', 'thiệt hại gossip high từ chính hy tống tổ nhi tống hải giáp ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-vuong-quyen-phan-4', 'Trò Chơi Vương Quyền (Phần 4)', 'Game Of Thrones (Season 4)', 'https://phimimg.com/upload/vod/20240205-1/3a9626c89bae7f9a723b15493d3130f4.jpg', 'https://phimimg.com/upload/vod/20240205-1/4f47f80734bd9092289241b69ea1f92f.jpg', '<p>Phần 4 của series phim truyền hình nổi tiếng Game Of Thrones sẽ dựa theo nửa cuối của tiểu thuyết A Storm of Swords (Quyển thứ 3 của tiểu thuyết A Song of Ice and Fire). Cuộc tranh đấu không mệt mỏi của 7 gia tộc chiến đấu để làm chủ vùng đất thần thoại Westeros được tiếp tục trong phần 4. Một mưu đồ chính trị mới lại trỗi dậy và các phe phái còn sống sót không chỉ đấu tranh với kẻ thù bên ngoài mà còn với giặc trong. Gia tộc Lannister giành chiến thắng sau khi đã đánh bại các mối đe dọa, mặc dù vùng đất thần thoại Westeros đã nằm trong tay sự kiểm soát của gia tộc Lannister, nhưng vẫn còn hai phe phái phản đối họ: Greyjoys và Baratheons! Lần này thì các thế lực siêu nhiên đang nổi dậy như đội quân White Walkers đang dần tràn về vương quốc từ phương bắc, phù thủy Đỏ với các phép thuật hắc ám của mình đang dần trở nên mạnh hơn, 3 con rồng của công chúa Daenerys Targaryen cũng đã lớn và sẽ trở thành một thế lực lớn trong cuộc tranh đấu này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kit Harington","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Natalie Dormer","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Alfie Allen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324455);
