INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-minh-co-bien', 'Nhà Mình Có Biến', 'What Happens To My Family?', 'https://phimimg.com/upload/vod/20240205-1/7f3c9b38562ad3c3b5f802f44983e229.jpg', 'https://phimimg.com/upload/vod/20240205-1/656e9f40d805e79e38aaf7ac80940d91.jpg', '<p>Hết chịu nổi hành vi ích kỷ của con cái, ông bố nọ kiện các con đòi tất cả những gì chúng có và buộc chúng đáp ứng một danh sách điều kiện để trở thành gia đình thực sự.</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 14, 2014, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Dong Kun","avatar":""},{"name":"Kim Hyun Joo","avatar":""},{"name":"Kim Sang Kyung","avatar":""},{"name":"Kim Yong Geon","avatar":""},{"name":"Na Young Hee","avatar":""},{"name":"Yoon Bak","avatar":""},{"name":"Son Dam Bi","avatar":""},{"name":"Kyeon Mi Ri","avatar":""},{"name":"Kim Il Woo","avatar":""},{"name":"Park Hyung Sik","avatar":""},{"name":"Nam Ji Hyun","avatar":""},{"name":"Seo Kang Jun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
