INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-o-palm-springs', 'Giáng Sinh Ở Palm Springs', 'Christmas In Palm Springs', 'https://phimimg.com/upload/vod/20240220-1/f062de3bda4b7d2be2161aa59e473062.jpg', 'https://phimimg.com/upload/vod/20240220-1/35ce1eb946769a64b6770a3eef8051d6.jpg', '<p>Giáng Sinh Ở Palm Springs - Christmas in Palm Springs&nbsp;kể về hành trình hàn gắn tình cảm cho bố mẹ đã ly thân của hai đứa trẻ. Người mẹ Jessica có một buổi thuyết trình lớn ở Palm Springs. Hai đứa con của cô dự định làm bất cứ điều gì để bố và mẹ trở lại với nhau - ngay cả khi chúng phải hack điện thoại của mẹ hoặc giả làm thư ký để đảm bảo rằng bố cũng ở Palm Springs. Tuy nhiên, hai đứa trẻ gặp trở ngại là Joe, người sẽ làm bất cứ điều gì để anh ấy có thể quay trở lại cuộc sống của mẹ Jessica.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Muldoon","avatar":""},{"name":"Dina Meyer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
