INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-yeu', 'Con Yêu', 'Dearest', 'https://phimimg.com/upload/vod/20240219-1/84c6dc6d8da9f86b3d577b90c5545eb1.jpg', 'https://phimimg.com/upload/vod/20240219-1/181b05defc1243b2593d2f03c3a306fa.jpg', '<p>Dựa trên những câu chuyện có thật đáng chú ý, Peter Chan mang đến một bộ phim truyền hình cảm động về nạn bắt cóc trẻ em ở Trung Quốc. Huang Bo đóng vai một người cha có đứa con trai nhỏ biến mất trên đường phố của một thành phố lớn. Anh ta bắt đầu tìm kiếm khắp Trung Quốc, không dừng lại ở việc tìm kiếm anh ta. Trong dàn diễn viên toàn sao này, Triệu Vy vào vai một người mẹ đến từ một vùng quê nghèo.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Wei","avatar":""},{"name":"Huang Bo","avatar":""},{"name":"Hao Lei","avatar":""},{"name":"Dawei Tong","avatar":""},{"name":"Zhang Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
