INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('flowers-in-the-attic', 'Flowers In The Attic', 'Flowers In The Attic', 'https://phimimg.com/upload/vod/20240219-1/4069518ccf6269cc128778cabb99abc1.jpg', 'https://phimimg.com/upload/vod/20240219-1/8d506f0d90c38e0bf358d01cd70accf8.jpg', '<p>Dựa trên V.C. Cuốn tiểu thuyết cổ điển giống nhau gây tranh cãi của Andrew, những bông hoa trên gác mái nói về câu chuyện về những đứa trẻ Dollanganger, sau cái chết bất ngờ của cha họ, được ép buộc để ẩn giấu trong gác mái của bà ngoại tàn nhẫn của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324455);
