INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-choi', 'Rong Chơi', 'Laggies', 'https://phimimg.com/upload/vod/20240219-1/2ebb373c47ea6ac73799591802b87bc2.jpg', 'https://phimimg.com/upload/vod/20240219-1/b1595c2f292a9b9f71230d4c07063799.jpg', '<p>Học quá cao và thiếu việc làm, Megan, 28 tuổi, đang phải vật lộn với cuộc khủng hoảng một phần tư cuộc đời. Bước vào tuổi trưởng thành mà không có triển vọng nghề nghiệp, không có động lực cụ thể để nghĩ về tương lai của mình và không có ai để liên hệ, Megan cảm thấy thoải mái khi tụt lại phía sau vài bước - trong khi bạn bè của cô đánh dấu các mốc quan trọng và ăn mừng trạng thái trưởng thành mới của họ. Khi người yêu thời trung học của cô cầu hôn, Megan hoảng sợ và - có cơ hội bất ngờ để trốn thoát trong một tuần - trốn trong nhà của người bạn mới, Annika, 16 tuổi và Craig, người cha đơn thân mệt mỏi với thế giới của Annika.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Kaitlyn Dever","avatar":""},{"name":"Ellie Kemper","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
