INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-mo-tang-thuong-hon-ma-nu', 'Ngôi Mộ Tang Thương : Hồn Ma Nữ', 'Mourning Grave Aka The Girl''s Grave', 'https://phimimg.com/upload/vod/20240219-1/348441bda6bbff2fabdde9d64b3b7757.jpg', 'https://phimimg.com/upload/vod/20240219-1/9de2b7c462193fcd4fbf52e5880bcbd5.jpg', '<p>Ngôi Mộ Tang Thương : Hồn Ma Nữ - Mourning Grave Aka The Girls Grave là bộ phim hài kinh dị mang đậm chất tình cảm của Hàn Quốc năm 2014. Đạo diễn phim, In-chun Oh, sẽ đem đến cho khán giả những pha cười ngất ngưỡng đan xen những cảnh tượng rùng rợn trong phim. Nội dung phim xoay quanh về khả năng đặc biệt của một cậu bé trung học, In-Soo. Do khả năng đặc biệt có thể nhìn thấy ma của mình, In-Soo bị bạn bè cùng lứa sợ hãi, xa lánh, dần dần cậu bị cô lập hẳn. Muốn cuộc sống khá hơn, cậu và gia đình đã chuyển đến vùng ngoại ô Seoul để sống. Cậu được học lớp mới. Nhưng do luôn bị quá khứ chẳng mấy vui vẻ ấy ám ảnh, nên In-Soo vẫn luôn biệt lập và luôn có suy nghĩ rằng cậu không giống mọi người. Tại đây, cậu tình cờ thấy và dần dần kết thân với một ma nữ. Nhưng kể từ đó, những điều bí ẩn dần dần xuất hiện, các thành viên trong lớp dần dần biến mất. Liệu những sự việc quái gở, bí ẩn ấy có liên quan gì đến nàng ma nữ bạn của cậu không? Sự thật của mọi việc là gì? In-Soo quyết tìm cho ra sự thật.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hye-Lin Han","avatar":""},{"name":"Haneul Kang","avatar":""},{"name":"So-eun Kim","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324455);
