INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-hoi-mang-song', 'Thu Hồi Mạng Sống', 'Reclaim', 'https://phimimg.com/upload/vod/20240219-1/056f089400aa80af6a033c4c3fa9d17a.jpg', 'https://phimimg.com/upload/vod/20240219-1/81f83764284e4f7e2b0c3356ec27b8c7.jpg', '<p>Sau khi cô con gái mới nhận nuôi của họ bị mất tích ở một thị trấn nhỏ, Steven và Shannon sẽ làm mọi cách để khám phá sự thật đằng sau sự mất tích của cô bé và bí mật nguy hiểm đằng sau cơ quan nhận con nuôi mà họ tin tưởng. Mạo hiểm mạng sống của chính mình, họ sẽ khám phá ra ý nghĩa của việc làm cha mẹ và họ sẽ đi bao xa để giành lại đứa con của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Rachelle Lefevre","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Luis Guzmán","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
