INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-ong-maya', 'Chú Ong Maya', 'Maya The Bee Movie', 'https://phimimg.com/upload/vod/20240207-1/bb5b5a72833e23359f3aa975c02e8c15.jpg', 'https://phimimg.com/upload/vod/20240207-1/3af451e663a46254df511ff643ef6e15.jpg', '<p>Con ong mới nở Maya hơi hay quay cuồng và sẽ không tuân theo các quy tắc của tổ ong. Một trong những quy tắc này là không tin những con ong bắp cày sống ngoài đồng cỏ. Khi Sữa ong chúa bị đánh cắp, những con ong bắp cày bị nghi ngờ và Maya được cho là đồng phạm của chúng. Không ai tin rằng cô ấy là nạn nhân vô tội và sẽ không ai đứng về phía cô ấy ngoại trừ người bạn tốt bụng và tốt bụng Willy. Sau một hành trình dài và đầy biến cố đến tổ ong bắp cày, Maya và Willy sớm phát hiện ra thủ phạm thực sự và hai người bạn cuối cùng gắn bó với những cư dân khác của đồng cỏ sang trọng.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Coco Jack Gillies","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Justine Clarke","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324455);
