INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-thi-tam-bach-an', 'Đường Thi Tam Bách Án', 'The Untold Stories Of Tang Dynasty', 'https://phimimg.com/upload/vod/20240126-1/20ac630a806a74dcfd559bd3c0a054bd.jpg', 'https://phimimg.com/upload/vod/20240126-1/cddeb0a5bc3feecbb5882d864ce54dd6.jpg', '<p>Vào thời khai nguyên của Lý Đường, tin đồn Võ hậu chuyển thế nổi lên khắp nơi, tàn trang Thôi Bối Đồ tái hiện ở nhân gian ý chỉ rằng mảnh tàn trang Thôi Bối Đồ thứ 61 tiên đoán Võ hậu sắp chuyển thế, nhất định sẽ cướp đoạt giang sơn của Lý Đường. Lời đồn trực tiếp hướng về phía Ngọc quý phi đang được sủng ái nhất trong hậu cung nói cô ta chính là Võ hậu chuyển thế, đồng thời các thế lực trong triều thay đổi kịch liệt, án mạng liên tiếp xảy ra. Nghi Vân, Đậu Sinh và Lý Mặc Bạch mượn cơ hội xin đi điều tra vụ án này. Trên đường làm quen với nữ yêu Đông Nam của Vô Tương Tháp và đạo sĩ ngao du tứ phương Nguyên Đan Khâu. Từ đó Lý Mặc Bạch bước lên con đường làm 300 bài thơ, phá 300 vụ án. Đồng thời âm thầm điều tra kẻ đứng sau vụ án lời đồn Võ hậu chuyển thế.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Bách Dung","avatar":""},{"name":"Dương Hi","avatar":""},{"name":"Ngụy Thần Tịnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
