INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-ky-dieu-phan-1', 'Vũ Trụ Kỳ Diệu (Phần 1)', 'Cosmos: A SpaceTime Odyssey (Season 1)', 'https://phimimg.com/upload/vod/20240126-1/368c91813512bcd826ce9e66a3e4af7e.jpg', 'https://phimimg.com/upload/vod/20240126-1/cd9f3e860ebf9500df9e1428e1483702.jpg', '<p>COSMOS: A spacetime Odyssey tiếp nối series phim tài liệu khám phá vũ trụ nổi tiếng Cosmos: A Pesonal Voyage. Series này sẽ giới thiệu các câu chuyện chưa từng được kể về cuộc hành trình tìm kiếm tri thức, đưa khán giả đến với các thế giới mới khắp thiên hà để tìm hiểu về vũ trụ cả trên một quy mô rộng lớn nhất lẫn nhỏ nhất.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Neil deGrasse Tyson","avatar":""},{"name":"Stoney Emshwiller","avatar":""},{"name":"Michael Chochol","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324455);
