INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cun-belle-va-giang-sinh', 'Cún Belle và Giáng sinh', 'A Belle for Christmas', 'https://phimimg.com/upload/vod/20231116-1/4de3b5b9188c3d897ef804d91a3124ab.jpg', 'https://phimimg.com/upload/vod/20231116-1/6e96e3c7fd17f5c1f1e73ed5baff696d.jpg', '<p>Khi bạn gái mới của một người vừa mất vợ cố gắng tống khứ bé cún mới của gia đình họ, hai đứa con nhỏ của anh can thiệp để cứu người bạn lông xù của chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dean Cain","avatar":""},{"name":"Kristy Swanson","avatar":""},{"name":"Jet Jurgensmeyer","avatar":""},{"name":"Haylie Duff","avatar":""},{"name":"Meyrick Murphy","avatar":""},{"name":"Avary J. Anderson","avatar":""},{"name":"Connor Berry","avatar":""},{"name":"Babs Simmons","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324455);
