INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-bong-ma', 'Lời Nguyền Bóng Ma', 'Ju-on: The Beginning of the End', 'https://phimimg.com/upload/vod/20231203-1/c8cc8fc1357181d399c0be0afad8723c.jpg', 'https://phimimg.com/upload/vod/20231203-1/b207c85b6dcfd4beac7392b0dafc73f1.jpg', '<p>Lời Nguyền Bóng Ma là phần 3 của Ju On - series phim kinh dị ăn khách của Nhật Bản.Các bộ phim Ju-on kể về cuộc sống không bình yên của những người vô tình bị mắc phải lời nguyền, do hồn ma của hai mẹ con Kayako và Toshio, bị chồng sát hại trong ngôi nhà ở Nerima gây ra. Lời nguyền Ju-on xảy ra với những ai vô tình vướng phải nó. Trong phần phim này, một giáo viên trung học rất quan tâm về tình hình của học sinh, quyết định đến thăm em nam sinh nhỏ đã vắng mặt trong thời gian dài. Bước chân vào ngôi nhà hoang vắng, cô giáo bỗng chứng kiến thảm cảnh cách đây hơn 10 năm tại ngôi nhà. Nhưng đã quá muộn để có thể quay lại. Rút gọn</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shô Aoyagi","avatar":""},{"name":"Yoshihiko Hakamada","avatar":""},{"name":"Yasuhito Hida","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324455);
