INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-co-the-la-yeu', 'Chỉ Có Thể Là Yêu', 'It''s Okay, That''s Love', 'https://phimimg.com/upload/vod/20240126-1/c353a7efaa1e56e2015ab691f90d62b7.jpg', 'https://phimimg.com/upload/vod/20240126-1/db71664476de65fa589730c4c173dee5.jpg', '<p>\chỉ có thể là yêu \là câu chuyện về cuộc sống và tình yêu của những con người hiện đại mang trong mình những căn bệnh về tinh thần ,sống mà không thực sự tự nhận thức được bản thân mình. Trong phim, Jo In Sung đóng vai Jang Jae Yeol, một tiểu thuyết gia trinh thám ăn khách kiêm DJ của đài phát thanh, điển hình của mẫu đàn ông phong độ và lãng mạn với khả năng ăn nói hùng biện. Gong Hyo Jin vào vai Ji Hae Soo, một bác sĩ nhiệt huyết của khoa thần kinh, với vẻ ngoài trưng diện nhưng lại rất nhân đạo, hết sức cảm thông thương xót với bệnh nhân. Bộ phim triển khai trên mạch hai nhân vật nam nữ chính có tính cách khác thường mang chứa những vết thương giấu kín trong lòng dần dần phải lòng nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kong Hyo-Jin","avatar":""},{"name":"Jo In Sung","avatar":""},{"name":"Lee Kwang Soo","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"D.O.","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324455);
