INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-tom-and-jerry-show-phan-3', 'The Tom And Jerry Show (Phần 3)', 'The Tom And Jerry Show (Season 3)', 'https://phimimg.com/upload/vod/20240118-1/da05daf02edc9ad0c7909dd65b206d79.jpg', 'https://phimimg.com/upload/vod/20240118-1/542042c019f2ed38bb1a71cae837d50f.jpg', '<p>Hai đối thủ mèo và chuột mang tính biểu tượng đã trở lại trong loạt phim kinh điển. Giữ nguyên hình thức, nhân vật và sự nhạy cảm của nguyên tác, sê-ri này chiếu một lăng kính có độ phân giải cao, màu sắc rực rỡ vào trò hài hước điên rồ và trận chiến không hồi kết đã biến Tom và Jerry trở thành hai trong số những nhân vật được yêu thích nhất mọi thời đại.</p>', 'Hoàn Tất (78/78)', 78, 'hoathinh', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324455);
