INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-2014', 'Ranh Giới', 'Cymbeline', 'https://phimimg.com/upload/vod/20240207-1/98ccdad895f17a1c508a23122eb9a0cc.jpg', 'https://phimimg.com/upload/vod/20240207-1/d544b622747fe2ed2a1cc6a6743e9962.jpg', '<p>Ranh Giới - Cymbeline lấy cảm hứng từ vở kịch của Shakespeare nhưng được hiện vào bối cảnh hiện đại, xoay quanh cuộc chiến của những tay cớm không màng luật lệ và những tay buôn bán ma túy tại những vùng quê của nước Mỹ. Bộ phim được mô tả như một sự pha trộn giữa cái chất của series truyền hình tội phạm cực kỳ ăn khách nổi tiếng Sons of Anarchy và mang phong cách lãng mạn của Romeo \u0026 Juliet. Một tác phẩm hội tụ đầy đủ những yếu tố từ kịch tính, tình yêu, phản bội, trả thù...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Milla Jovovich","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324455);
