INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-dao-chich-lupin-de-tam', 'Siêu Đạo Chích Lupin Đệ Tam', 'Lupin The 3rd', 'https://phimimg.com/upload/vod/20240205-1/a13462ffed3df329c81c76c3c3704d90.jpg', 'https://phimimg.com/upload/vod/20240205-1/7c8dd0bdb911f47a61fefa155ef6cf6d.jpg', '<p>Thanh tra Interpol Zenigata bắt đầu cuộc săn lùng tên trộm khét tiếng Lupin Đệ Tam trên toàn thế giới. Nhưng cùng nhau, họ phải đối mặt với một kẻ thù hùng mạnh và thành lập đội Lupin để đáp trả. Sau đó, đội Lupin phải đối mặt với thử thách lấy lại Trái tim đỏ thẫm của Cleopatra bị nhốt trong một pháo đài giống như két sắt. Kho báu được cho là cho phép chủ nhân của nó kiểm soát thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Meisa Kuroki","avatar":""},{"name":"Go Ayano","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Tetsuji Tamayama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324455);
