INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-frankenstein', 'Tôi, Frankenstein', 'I, Frankenstein', 'https://phimimg.com/upload/vod/20240205-1/e3faadd06c4e7b2f1b17876958b9e0ce.jpg', 'https://phimimg.com/upload/vod/20240205-1/0f6383e30a6a6686b9d5468bbd043073.jpg', '<p>Tôi, Frankenstein - I, Frankenstein là một bộ phim hành động giả tưởng Mỷ của đạo diễn Stuart Baettie dựa trên cuốn tiểu thuyết của Kevin Grevioux. Hai thế kỷ sau khi tiến sĩ Frankenstein lắp ráp và tạo ra nguồn sức mạnh mới cho thuộc hạ của mình - Adam (Aaron Eckhart). Ông bị lôi kéo vào một cuộc chiến tranh giữa hai chủng tộc bất tử: Nhân sư, những người bảo vệ những nét tinh hoa của nhân loại và ác quỷ. Kể từ khi Adam không còn là con người hay quỷ, nữ hoàng Leonore (Miranda Otto) và hoàng tử quỷ Naberius (Bill Nighy), mỗi người muốn anh ta phục vụ cho mục đích riêng của họ. Đó cũng chính là lý do để Adam khám phá con người bên trong và đi tìm câu trả lời cho mục đích tồn tại của mình</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Miranda Otto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324455);
