INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-lan-than-cong', 'Vu Lan Thần Công', 'Hungry Ghost Ritual', 'https://phimimg.com/upload/vod/20240205-1/47b4383591237c6e1732d437c0169c02.jpg', 'https://phimimg.com/upload/vod/20240205-1/10a41e44cbae808debe7568ee1a3fc9d.jpg', '<p>Hungry Ghost là bộ phim điện ảnh đề tài kinh dị do Trương Gia Huy lần đầu làm đạo diễn. Trong Vu Lan thần công, Trương Gia Huy ngoài vai trò làm đạo diễn, anh còn tham gia vai nam chính là anh chàng thư sinh nhút nhát nhưng ham muốn tình dục cao, cũng như khả năng sành sỏi trong chuyện giường chiếu.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Annie Liu","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Cathryn Li","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Karena Teo","avatar":""},{"name":"Eric Chen","avatar":""},{"name":"Ruby Yap","avatar":""},{"name":"Chye Chee Keong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324455);
