INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-hai-mat', 'Sát Nhân Hai Mặt', 'Merciless', 'https://phimimg.com/upload/vod/20240229-1/89674ea9b9e4f59f950cfa533fdaa86b.jpg', 'https://phimimg.com/upload/vod/20240229-1/b94b9084afd90943402a39aa19f17262.jpg', '<p>Không lâu sau khi vào làm việc cho một thượng nghị sĩ, Eduardo Borges được ông tin tưởng và giao cho nhiệm vụ hỗ trợ cảnh sát điều tra các vụ án mạng liên hoàn man rợ diễn ra gần đây. Điển trai, có học thức và khéo ăn nói, Eduardo dễ dàng tạo được cảm tình với những người xung quanh mình. Nhưng họ nào có ngờ hắn lại chính là kẻ giết người hàng loạt mà cảnh sát đang truy lùng ráo riết.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 15, 2014, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Bruno Gagliasso","avatar":""},{"name":"Luana Piovani","avatar":""},{"name":"Débora Falabella","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324455);
