INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hoc-tro', 'Tình Yêu Học Trò', 'L.DK', 'https://phimimg.com/upload/vod/20240207-1/c958396e017aed02ca62481418dbfba3.jpg', 'https://phimimg.com/upload/vod/20240207-1/07ad21ed7572a1d086886d87a3151810.jpg', '<p>Cha mẹ của Aoi Nishimori chuyển đến một thành phố khác để làm việc, nhưng Aoi không muốn chuyển đến một trường trung học mới. Cô ở lại phía sau và sống trong một căn hộ một mình. Shusei Kugayama chuyển đến bên cạnh căn hộ của Aoi. Shusei là một sinh viên rất nổi tiếng tại trường trung học của họ. Do một sai lầm, Aoi làm cho vòi phun nước rơi ra trong phòng. Cho đến khi căn phòng của Shusei được cố định, anh ta ở lại với Aoi.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
