INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-2', 'Trại Giam Kiểu Mỹ (Phần 2)', 'Orange Is The New Black (Season 2)', 'https://phimimg.com/upload/vod/20240118-1/ac0a2f5922698916ff4f3d0694a4aa91.jpg', 'https://phimimg.com/upload/vod/20240118-1/778e3f2e1315d4c69b1f7323eba9fffc.jpg', '<p>Orange Is the New Black 2 tiếp tục miêu tả chân thực cuộc sống có phần thác loạn của những nữ tù nhân khi họ phải tìm mọi cách để sống sót trong tù. Sau việc làm rất tệ của cô, thì lần này Piper đã được chuyển đến một nhà tù khác có phần khắc nghiệt hơn. Liệu lần này Piper sẽ phải làm sao để sống sót trong nơi này đây?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2014, 'Vietsub', 'HD 720p', 'Âu Mỹ', 0, '[{"name":"Taylor Schilling","avatar":""},{"name":"Danielle Brooks","avatar":""},{"name":"Laura Prepon","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Emma Myles","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324455);
