INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dua-ma-vang', 'Đôi Đũa Mạ Vàng', 'Gilded Chopsticks', 'https://phimimg.com/upload/vod/20240118-1/0ec5949e7a2e2c6baf1919d8d8103c95.jpg', 'https://phimimg.com/upload/vod/20240118-1/001e6937cc5788589cc1bac791b6afbb.jpg', '<p>Nội dung phim xoay quanh cuộc đời của anh chàng Cao Thiên Bảo. Xuất thân trong một gia đình giàu có, Thiên Bảo được lớn lên trong nhung lụa, sự yêu thương và đùm bọc. Sớm bộc lộ tài năng ẩm thực, cùng điều kiện tốt, cậu biết được nhiều món ăn ngon và quý.Tuy nhiên, sóng gió vô tình ập đến với gia đình khiến Thiên Bảo phải bỏ trốn cùng người hầu thân cận, sống phiêu bạt thiên hạ, kiếm ăn qua ngày.Nhờ tài nấu nướng, cậu mới có thể vượt qua những ngày tháng khó khăn và kết giao được với nhiều người bạn mới, trong đó có hoàng thượng Dân Chân trong một lần vi hành. Hai người mới gặp như đã quen từ lâu, hoàng thượng quyết mời Thiên Bảo vào cung làm ngự trù. Chưa được bao lâu thì liên tiếp những xích mích xảy ra, Thiên Bảo bị cuốn theo cuộc chiến hoàng tộc.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 14, 2014, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Stephanie Ho  米小鱼  25 Episodes  Wong Cho-lam as 高天宝 Wong Cho-lam  高天宝  25 Episodes  Ben Wong as 胤禛","avatar":""},{"name":"四皇子 Ben Wong  胤禛","avatar":""},{"name":"四皇子  25 Episodes  Joey Meng as 纪慕雪 Joey Meng  纪慕雪  25 Episodes  Nancy Wu as 年若碧 Nancy Wu  年若碧  25 Episodes  Jack Wu as 李卫 Jack Wu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324455);
