INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-tro-ve-qua-khu', 'Liên Minh Công Lý: Trở Về Quá Khứ', 'JLA Adventures: Trapped In Time', 'https://phimimg.com/upload/vod/20240205-1/f576882e4e0dea470d8b5eef77e5dd2b.jpg', 'https://phimimg.com/upload/vod/20240205-1/7aba0654f95fcb65e9c1b632c6700623.jpg', '<p>Hãy sẵn sàng cho trận chiến muôn thuở khi Liên minh Công lý đối đầu với kẻ thù không đội trời chung, Legion of Doom, trong một bộ phim hoàn toàn mới của DC Comics. Một sinh vật bí ẩn được gọi là Kẻ đánh bẫy thời gian xuất hiện, và một kế hoạch nham hiểm do Lex Luthor lãnh đạo đã gửi Legion of Doom ngược thời gian để loại bỏ Superman, Wonder Woman và Batman trước khi họ trở thành siêu anh hùng. Đối với Aquaman, Flash và Cyborg, cùng với các siêu anh hùng tuổi teen Karate Kid và Dawnstar, số tiền đặt cược chưa bao giờ cao hơn thế, nhiệm vụ giải cứu chưa bao giờ nguy hiểm hơn thế. Vì vậy, hãy tham gia cuộc chiến vì tương lai khi Liên minh Công lý đối mặt với thử thách cuối cùng… mối đe dọa chưa từng tồn tại!</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diedrich Bader","avatar":""},{"name":"Laura Bailey","avatar":""},{"name":"Dante Basco","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Grey DeLisle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324455);
