INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-tranh', 'Kẻ Trộm Tranh', 'The Forger', 'https://phimimg.com/upload/vod/20240227-1/665e35ceb492e436463dcde12a3b99df.jpg', 'https://phimimg.com/upload/vod/20240227-1/2477797f9790a4e7e9213b5b99c5faa2.jpg', '<p>Một cựu thần đồng nghệ thuật và tên trộm vặt thế hệ thứ hai sắp xếp để mua đường ra khỏi tù để dành thời gian cho đứa con trai ốm yếu của mình, chỉ để buộc phải thay đổi kế hoạch của mình và giao thêm một công việc cho người đàn ông đã tài trợ cho việc trả tự do cho anh ta.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Marcus Thomas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324455);
