INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-vien', 'Vĩnh Viễn', 'Permanent', 'https://phimimg.com/upload/vod/20240227-1/a4b1b112ff1819afd3fb8bff8e632095.jpg', 'https://phimimg.com/upload/vod/20240227-1/9b1a2c4baa6c57902b910ac7604bc9b4.jpg', '<p>Bộ phim Vĩnh Viễn - Permanent kể về sáu người không liên quan đến nhau, họ phải vượt qua quá khứ của mình và thế giới ngầm để khám phá những gì đã kiểm soát mỗi người trong suốt những năm qua. Tình dục, ma túy, súng và Chúa đã tạo ra một loạt các sự kiện sẽ khiến mỗi người trong số họ thay đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"David Dallas","avatar":""},{"name":"Erica Derrickson","avatar":""},{"name":"Marie Blaise","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324455);
