INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elimination-game', 'Elimination Game', 'Elimination Game', 'https://phimimg.com/upload/vod/20240227-1/ca495669d54b2505b191f000488c6ad1.jpg', 'https://phimimg.com/upload/vod/20240227-1/1948f6ab6b6833886c560785b74b3ca3.jpg', '<p>Sau một vụ thảm sát dân thường gây sốc ở một vùng chiến sự nước ngoài, Navy SEAL bị thất sủng Rick Tyler bị kết án thối rữa trong một nhà tù quân sự an ninh tối đa cho đến khi anh ta có cơ hội mạo hiểm mạng sống của mình để giành lấy tự do. Là lực lượng tự nhiên một người, Tyler sẽ phải tiếp nhận và hạ gục một số kẻ giết người tàn nhẫn nhất thế giới ở một số địa điểm tàn bạo nhất thế giới để giành chiến thắng trong trò chơi, giành được tự do và tìm hiểu lý do tại sao anh ta bị gài bẫy. . Câu hỏi đặt ra là liệu anh ấy có thể hoàn thành tất cả những điều này trước khi Game On kết thúc không?</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Viva Bianca","avatar":""},{"name":"Robert Taylor","avatar":""},{"name":"Belinda McClory","avatar":""},{"name":"Nicholas Hammond","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324455);
