INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('elimination-game', 'Elimination Game', 'Elimination Game', 'elimination game elimination game dominic purcell viva bianca robert taylor belinda mcclory nicholas hammond ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bip-tay-sat-gai', 'Thần Bịp: Tay Sát Gái', 'Tazza: The Hidden Card', 'https://phimimg.com/upload/vod/20240207-1/5a19d8426d741798ef3fb3bd9932f372.jpg', 'https://phimimg.com/upload/vod/20240207-1/a28201d96f3dd47e0ad5bf63e1931267.jpg', '<p>Nhằm trả thù những kẻ từng hãm hại mình lẫn giải cứu bạn gái, chàng thanh niên có “tài năng” thiên phú trong việc gian lận cờ bạc Ham Dae Gil đã tầm sư học đạo, quyết tâm lập ra một kế hoạch phục hận hoàn hảo thông qua các ván bài đen đỏ.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Seung-hyun","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Lee Ha-nee","avatar":""},{"name":"Yoo Hae-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324455);
