INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-thai-tinh-truong', 'Sắc Thái Tình Trường', 'Some Kind Of Beautiful', 'https://phimimg.com/upload/vod/20240207-1/94fae2bbd0423ec9075cc5a55a1ed64c.jpg', 'https://phimimg.com/upload/vod/20240207-1/588e5dd956ad89a96bbc7374573bd6c2.jpg', '<p>Ban ngày, Richard Haig là một giáo sư tiếng Anh thành công và được kính trọng tại Đại học Trinity nổi tiếng ở Cambridge. Vào ban đêm, Richard thỏa mãn những tưởng tượng lãng mạn của riêng mình với một loạt sinh viên chưa tốt nghiệp xinh đẹp. Nhưng Richard đã chán trò chơi này và đang tìm kiếm thứ gì đó có ý nghĩa và lâu dài hơn. Vì vậy, khi Kate, cô bạn gái người Mỹ 25 tuổi, lực lưỡng, rám nắng của Richard nói với anh rằng cô ấy đang mang thai, Richard đã rất xúc động. Anh ấy mong muốn có một gia đình của riêng mình, trở thành một người cha mà các con anh ấy có thể tự hào, chứ không phải một con linh miêu ham muốn tình dục nào đó. Chỉ có một vấn đề. Richard không yêu Kate. Richard đang yêu em gái của Kate, Olivia. Anh đã yêu cô ngay từ lần đầu tiên nhìn thấy cô.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Ben McKenzie","avatar":""},{"name":"Fred Melamed","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324455);
