INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-truc-kinh-hoang-2014', 'Ca Trực Kinh Hoàng', 'Last Shift', 'https://phimimg.com/upload/vod/20240207-1/6f67ee1a26f7ff984753f7b2e0343cfa.jpg', 'https://phimimg.com/upload/vod/20240207-1/612511a7a61194c7a7b1caadeb8fc808.jpg', '<p>Sĩ quan cảnh sát tân binh Jessica Loren được giao ca cuối cùng tại một đồn cảnh sát đang đóng cửa và phải chờ đội hazmat thu thập bằng chứng y sinh. Được lệnh không được rời khỏi nhà ga trong bất kỳ trường hợp nào, Jessica biết được rằng đó không chỉ là một nhà ga lỗi thời, mà còn là nơi trú ngụ của hiện thân cuối cùng của cái ác và những kẻ khát máu tận tụy của hắn. Jessica bị bỏ mặc để tự lo liệu trong sân chơi của Ác quỷ.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Juliana Harkavy","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"J. LaRose","avatar":""},{"name":"Natalie Victoria","avatar":""},{"name":"Sarah Sculco","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
