INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-o-chuot', 'Khu Ổ Chuột', 'Trash', 'https://phimimg.com/upload/vod/20240207-1/0ddfd0e712c52dd79b5f38c17a6e6299.jpg', 'https://phimimg.com/upload/vod/20240207-1/e0f95f0eac2d77ec1be12aafdd8062b7.jpg', '<p>Khu Ổ Chuột - Trash: Bối cảnh phim ở Brazil, có ba đứa trẻ là bạn thân của nhau, cả ba cùng sinh sống tại 1 bãi rác lớn. Trong khi kiếm sống nhờ bãi rác, 3 người đã phát hiện một số thứ có thể khiến chúng trở nên giàu có, thế là chúng dính vào rắc rối với sự truy đuổi của cảnh sát...</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rooney Mara","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Wagner Moura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
