INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-bang-kinh-hoang-3', 'Đoạn Băng Kinh Hoàng 3', 'V/H/S: Viral', 'https://phimimg.com/upload/vod/20240207-1/b0c8524a91854ca978a3c73a8ae50f66.jpg', 'https://phimimg.com/upload/vod/20240207-1/f7d3ee729d8e516231a5c666b1af7024.jpg', '<p>V/H/S: Các phân đoạn của VIRAL bao gồm câu chuyện về một nhà ảo thuật loạn trí có được một vật thể ma thuật có sức mạnh to lớn; một cỗ máy tự chế mở ra cánh cửa đến thế giới song song; những vận động viên trượt băng tuổi teen bất đắc dĩ trở thành mục tiêu của một nghi lễ sùng bái cái chết ở Mexico; và một tổ chức đen tối, nham hiểm đang theo dõi một kẻ giết người hàng loạt. Các phân đoạn được gắn kết với nhau bằng câu chuyện về một nhóm thanh thiếu niên bị ám ảnh bởi sự nổi tiếng sau một cuộc rượt đuổi bằng ô tô bạo lực ở LA, những người vô tình trở thành ngôi sao gây xôn xao mạng tiếp theo.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Welborn","avatar":""},{"name":"Emmy Argo","avatar":""},{"name":"Gustavo Salmerón","avatar":""},{"name":"Emilia Ares","avatar":""},{"name":"Nick Blanco","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
