INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cuu-roi', 'Cuộc Chiến Cứu Rỗi', 'The Salvation', 'https://phimimg.com/upload/vod/20240207-1/549e29f30f93c4cefd15609675d86067.jpg', 'https://phimimg.com/upload/vod/20240207-1/48bd92d2ff48a782be76e1750772e901.jpg', '<p>Tây Mỹ vào những năm 1870. Một người định cư châu Âu, Jon Jensen (Mads Mikkelsen), vừa chào đón vợ và con trai đến đất nước khi họ bị bắt cóc và giết người. Anh ta trả thù kẻ giết người, chỉ để khám phá ra rằng một người là anh trai của một Nam tước đất địa phương, Henry Delarue. Delarue điều hành thị trấn địa phương với một bàn tay tàn bạo. Bây giờ anh ta muốn báo thù người đàn ông đã giết anh trai mình và người dân thị trấn địa phương đang quá sợ hãi khi anh ta đứng lên với anh ta. Jon đang chiến đấu nhiều hơn là những tên côn đồ địa phương, anh đang đối mặt với toàn bộ thị trấn.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
