INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ngay-doi-mang-2014', 'Ba Ngày Đổi Mạng', '3 Days To Kill', 'https://phimimg.com/upload/vod/20240207-1/10b163afee704b46ed6cf421647d4bd1.jpg', 'https://phimimg.com/upload/vod/20240207-1/43d22c795f645bab3b4cfd6c42740916.jpg', '<p>Bộ phim theo đuổi câu chuyện của Ethan Runner (Kevin Costner), một sát thủ cao cấp của chính phủ. Sau khi nhận được tin dữ về căn bệnh nan y trong người, Ethan quyết định từ bỏ cuộc sống nguy hiểm của mình để có thể hàn gắn tình cảm với vợ và con gái, những người mà trước đó anh buộc phải xua đuổi để tránh cho họ không bị hại. Nhưng khi tổ chức đề nghị với anh một phương thuốc cứu mạng đầy tiềm năng đang được thử nghiệm để đổi lại một nhiệm vụ cuối cùng, Ethan đành phải gánh một lúc hai công việc khó khăn nhất từ trước đến nay mà anh từng thực hiện: truy tìm tên khủng bố tàn bạo nhất thế giới và chăm sóc con gái yêu trong khi vợ đi xa.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Hailee Steinfeld","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
