INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-ky-ac-tam', 'Tự Kỷ Ác Tâm', 'No Good Deed', 'https://phimimg.com/upload/vod/20240205-1/eea33920accdcaaf67a4bfa2e01ba3fd.jpg', 'https://phimimg.com/upload/vod/20240205-1/f56a00ffe4d80b9a947dde74d7ba8796.jpg', '<p>Terri là một người vợ tận tụy và là mẹ của hai đứa con, đang sống một cuộc sống lý tưởng ở ngoại ô Atlanta khi Colin, một tên tội phạm trốn thoát quyến rũ nhưng nguy hiểm, xuất hiện trước cửa nhà cô và tuyên bố gặp sự cố xe hơi. Terri đưa điện thoại của mình để giúp anh ta nhưng nhanh chóng biết rằng không có hành động tốt nào không bị trừng phạt khi cô thấy mình phải chiến đấu để sinh tồn khi anh ta xâm chiếm nhà cô và khủng bố gia đình cô.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Henry Simmons","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
