INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-bi-an', 'Khách Sạn Bí Ẩn', 'The Secret Hotel', 'https://phimimg.com/upload/vod/20240118-1/b4b1f629b53ed6e74449d7df16bbf92a.jpg', 'https://phimimg.com/upload/vod/20240118-1/a8617ff93a14df82066f885c23450b4f.jpg', '<p>Sau 7 năm ly hôn, Sang Hyo tình cờ gặp lại chồng cũ Hae Young trong một tình huống trớ trêu khi cô là người phụ trách tổ chức lễ cưới, còn anh là chú rể. Bí ẩn hơn nữa khi trong ngày cưới, một thi thể bỗng nhiên rơi từ trên cao xuống. Vụ án đã kéo theo sự liên quan của hai người đàn ông: Sung Gyeom - sếp của Sang Hyo và anh chồng cũ oan gia.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2014, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo In Na","avatar":""},{"name":"Jin Yi Han","avatar":""},{"name":"Namgoong Min","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
