INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-oi-xin-dung-qua-song', 'Mình Ơi, Xin Đừng Qua Sông', 'My Love, Don''t Cross That River', 'https://phimimg.com/upload/vod/20240220-1/205ef979b5041ed23b818dab341c5547.jpg', 'https://phimimg.com/upload/vod/20240220-1/8b7bd783e352d2d675de014ac2f0699d.jpg', '<p>Bộ phim cảm động xoay quanh một cặp vợ chồng đã kết hôn nhiều năm: bà cụ Kang Gye Yeol 89 tuổi và ông cụ Jo Byeong Man 98 tuổi. Dù đi đến đâu, họ cũng nắm tay nhau, cùng nhau mặc trang phục truyền thống của Hàn Quốc. Vào mùa xuân, họ thích cài hoa vào tai đối phương. Vào mùa hè, họ chơi đùa trong làn nước suối. Vào mùa thu, họ nghịch lá rơi. Vào mùa đông, họ đùa vui với tuyết. Thời gian họ trải qua hàng ngày giống như vợ chồng mới cưới.Con của họ đều sống ở thành phố. Một hôm, chú chó Ggoma của họ đột nhiên qua đời, và người chồng Jo Byeong-Man cũng yếu dần đi. Vào một ngày mưa, bà Kang Gye-Yeol nghe thấy tiếng ho của chồng và bà cảm thấy bản thân sẽ nhanh chóng còn lại một mình. Vì thế bà đã chuẩn bị lời từ biệt...&nbsp;</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jo Byeong-Man","avatar":""},{"name":"Kang Gye-Yeol","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
