INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tua-thoi-gian', 'Tua Thời Gian', 'Time Lapse', 'https://phimimg.com/upload/vod/20240128-1/0d305ab857e0c1aea68c301cba9e4843.jpg', 'https://phimimg.com/upload/vod/20240128-1/17148eef7023ad987cf87ffc57e9cac5.jpg', '<p>Nội dung phim kể về ba người bạn thân khám phá ra một bí ẩn là máy chụp ảnh 24 giờ mỗi ngày trong tương lai. Họ âm mưu sử dụng nó cho mục đích cá nhân nhưng mọi việc diễn ra không suôn sẻ. Phim không dành cho khán giả dưới 18 tuổi.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Panabaker","avatar":""},{"name":"George Finn","avatar":""},{"name":"Matt O''Leary","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324456);
