INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-dam-vo-ngua', 'Muôn Dặm Vó Ngựa', 'Frontera', 'https://phimimg.com/upload/vod/20240128-1/d193ff12899409e5c1228063621a2541.jpg', 'https://phimimg.com/upload/vod/20240128-1/469f4cd90f26cbf2fbe39251331b8819.jpg', '<p>Sau khi vượt biên trái phép để làm việc, Miguel, một người cha chăm chỉ và một người chồng tận tụy, thấy mình bị vu oan tội giết vợ của một cựu cảnh sát trưởng. Sau khi biết anh bị cầm tù, người vợ đang mang thai của Miguel cố gắng giúp đỡ anh và rơi vào tay những con sói đồng cỏ tham nhũng, những kẻ giữ cô để đòi tiền chuộc. Không hài lòng với cuộc điều tra của sở cảnh sát, cựu cảnh sát trưởng cố gắng khám phá sự thật về cái chết của vợ mình và phát hiện ra bằng chứng đáng lo ngại sẽ phá hủy tương lai của một gia đình hoặc chia rẽ gia đình khác.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Harris","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Amy Madigan","avatar":""},{"name":"Kristen Rakes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
