INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-dan-lua', 'Thành Phố Đạn Lửa', 'Warsaw ''44 - City 44', 'https://phimimg.com/upload/vod/20240128-1/3e482123554bcf334b4a220c142c5df3.jpg', 'https://phimimg.com/upload/vod/20240128-1/1585603b37ac89c7519e636daf5f60b4.jpg', '<p>Thành Phố Đạn Lửa - Warsaw 44: Một câu chuyện về tình yêu, tình bạn và trận chiến đẫm máu và tàn bạo trong chiến tranh những năm 1944. Phim lấy bối cảnh chiến tranh Thế Giới thứ 2 và trong đó chúng ta sẽ theo chân Stefan Zawadzki một người lính quả cảm tham gia chiến trận và tình bạn giữa anh và Beksa. Dưới những trận chiến khốc liệt thì đối với 2 anh chàng này là một trò chơi và nhiệm vụ của họ là phải sống sót đến cuối nhiệm vụ.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Thuyết Minh', 'HD', 'Ba Lan', 0, '[{"name":"Józef Pawlowski","avatar":""},{"name":"Zofia Wichlacz","avatar":""},{"name":"Anna Próchniak","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324456);
