INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-ve', 'Quay Về', 'Coming Home', 'https://phimimg.com/upload/vod/20240126-1/078519114999089a74d67937c94f0349.jpg', 'https://phimimg.com/upload/vod/20240126-1/2bed84bedbf25bc91ca4ab9d49dcbfe1.jpg', '<p>Những năm đầu thập niên 70 thế kỷ trước, phạm nhân Lục Yên Thức nhiều năm bặt vô âm tín với người thân, trong một lần chuyển đổi nông trường đã bỏ trốn về nhà. Điều này mang đến cho con gái Đan Đan áp lực vô cùng lớn. Cô ngăn không cho mẹ là Phùng Uyển Du gặp cha mình. Sau khi cách mạng văn hóa kết thúc, Lục Yên Thức được về nhà, nhưng ông phát hiện con gái sớm đã từ bỏ giấc mơ bale và trở thành một nữ công nhân, người vợ vì mắc bệnh không còn nhận ra ông. Tình cảm sâu đậm, biến cố cuộc đời khiến Lục Yên Thức đưa ra một lựa chọn hoang đường nhưng hợp lý nhất đối với ông lúc này…</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Đạo Minh","avatar":""},{"name":"Củng Lợi","avatar":""},{"name":"Trương Tuệ Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
