INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-noi-loan', 'Cô Dâu Nổi Loạn', 'My Love, My Bride', 'https://phimimg.com/upload/vod/20240123-1/46ff0fd1806fe4ba15345e90a98278b9.jpg', 'https://phimimg.com/upload/vod/20240123-1/2845a7471394fa8e5287e5bf2b913a7c.jpg', '<p>Nội dung xoay quanh cặp vợ chồng mới cưới Young Min (Jo Jung Suk) và Mi Young (Shin Min Ah). Sau 4 năm tìm hiểu, họ quyết định tiến đến hôn nhân. Tưởng chừng cuộc sống bên cạnh nhau sẽ phủ đầy màu hồng, thế nhưng thực tế, họ phải đối diện với vô số những cảm xúc buồn vui lẫn lộn. Tuy yêu nhau sâu đậm nhưng đôi lúc họ lại có cảm giác ghét bỏ đối phương. Chính điều này đã khiến cả hai nhiều phen rơi vào tình trạng hoang mang, rối bời.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Min-a","avatar":""},{"name":"Cho Jung-seok","avatar":""},{"name":"Yoon Jung-hee","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Seo Kang-joon","avatar":""},{"name":"Yu Ha-jun","avatar":""},{"name":"Seo Shin-ae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
