INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-sat-rung-bach-tung', 'Thảm Sát Rừng Bách Tùng', 'The Redwood Massacre', 'https://phimimg.com/upload/vod/20240123-1/7cc19f1806eb628b9fad91ca9ccd96d0.jpg', 'https://phimimg.com/upload/vod/20240123-1/6078601d1a7a3b7ea9243881558cab96.jpg', '<p>THE REDWOOD MASSACRE kể về năm người bạn thích phiêu lưu, đến thăm địa điểm giết người huyền thoại Redwood. Nó có tất cả các dấu hiệu của một kỳ cắm trại thú vị và hồi hộp vào cuối tuần. Họ sớm phát hiện ra họ không phải là những người duy nhất ở địa điểm bí ẩn. Chuyến thám hiểm cắm trại vui vẻ sớm biến thành cơn ác mộng khi họ bị một kẻ giết người bí ẩn bí ẩn rình rập một cách tàn bạo.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wood","avatar":""},{"name":"Lisa Cameron","avatar":""},{"name":"Lisa Livingstone","avatar":""},{"name":"Rebecca Wilkie","avatar":""},{"name":"Adam Coutts","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
