INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-bat-dac-di', 'Cuộc Phiêu Lưu Bất Đắc Dĩ', 'Redirected', 'https://phimimg.com/upload/vod/20240123-1/cd84780ab80d2b111149ae51b27a3ede.jpg', 'https://phimimg.com/upload/vod/20240123-1/1fb39d950b654900b9e9dfcb2af263a3.jpg', '<p>Cuộc Phiêu Lưu Bất Đắc Dĩ - Redirected: Bốn người bạn - John, Ben, Tim và Michael vô tình liên quan đến một vụ cướp, và bị mắc kẹt ở Đông Âu trải qua một loạt các tai nạn bất ngờ và phải tìm đường trở về nhà. Để làm như vậy, họ sẽ phải vượt qua tên sát thủ, gái điếm, cảnh sát tham nhũng, buôn lậu và nhiều hơn nữa ..</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Vinnie Jones","avatar":""},{"name":"Scot Williams","avatar":""},{"name":"Gil Darnell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
