INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mieng-doi', 'Miệng Đời', 'The Voices', 'https://phimimg.com/upload/vod/20240123-1/6ef7bfb2bdb9857033dcf00d645c5d90.jpg', 'https://phimimg.com/upload/vod/20240123-1/092db127dd1a45a7c93452deb8e58133.jpg', '<p>Jerry, một nhân viên vận chuyển tại nhà máy đồ nội thất. Thừa hưởng căn bệnh hoang tưởng di truyền từ người mẹ, Jerry liên tục nghe thấy những giọng nói lạ xúi giục anh ta giết người và làm nhiều việc man rợ khác. Jerry luôn phải vất vả hoàn thành tốt hai vai diễn, một nhân viên hiền lành, dễ mến ban ngày và một kẻ giết người hàng loạt máu lạnh ban đêm.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Ella Smith","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
