INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-phong-hiep', 'Băng Phong Hiệp', 'Iceman 3D', 'null', 'https://phimimg.com/upload/vod/20240123-1/a914b361a7865d6e4e05c948b5837bf5.jpg', '<p>Băng Phong Hiệp - Iceman 3D kể về năm Gia Kinh cuối cùng của triều đại nhà Minh, Jin Yiwei Heying (do Chân Tử Đan đóng) được lệnh vận chuyển báu vật vô giá Quả bóng vàng từ Thiên Hầu. Ông chủ Yuanlong đưa Nie Hu và Sa Mastiff để bắt anh ta vì một vụ án oan chống lại He Ying. Khi bốn anh em đang chiến đấu, ngọn núi bất ngờ rung chuyển, và một trận tuyết lở lớn làm ngập họ. Tuy nhiên, sau khi tỉnh dậy, He Ying phát hiện ra rằng mình đã thực sự đến Hong Kong 400 năm sau. với sự giúp đỡ của Xiaomei, He Ying Sau khi học cách sử dụng các sản phẩm công nghệ cao . Đúng lúc mối quan hệ của cả hai thăng hoa thì Bộ ba Jinyiwei cũng xuyên không về thời hiện đại và tiếp tục thực hiện sứ mệnh của mình, đồng thời, cảnh sát không biết sự thật cũng đang truy bắt He Ying, một người có chức năng vượt trội. He Ying đã gặp phải nó trong 400 năm. Đây là thách thức lớn nhất.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Baoqiang","avatar":""},{"name":"Chân Tử Đan","avatar":""},{"name":"Huỳnh Thánh Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
