INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-loi-phan-1', 'Thành Phố Tội Lỗi (Phần 1)', 'Gotham (Season 1)', 'https://phimimg.com/upload/vod/20240118-1/0df6eadff4658e544cac1bc333e850ea.jpg', 'https://phimimg.com/upload/vod/20240118-1/4886ede08a380a33a6a6eb1d7a18c46f.jpg', '<p>Gotham tập trung vào thanh tra Jim Gordon và câu chuyện xuất phát từ lúc ông mới được nhận vào làm việc tại Sở cảnh sát thành phố Gotham. Vụ án đầu tiên mà Gordon phải xử lý chính là vụ việc vợ chồng tỷ phú Thomas và Martha Wayne bị sát hại trong một con hẻm nhỏ. Trong lúc điều tra, Gordon đã có dịp gặp gỡ cậu con trai nhà Wayne, Bruce Wayne, người vốn sau này sẽ trở thành Kỵ sĩ Bóng đêm và đồng hành với ông trong sự nghiệp chống tội phạm...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Mckenzie","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Zabryna Guevara","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"David Mazouz","avatar":""},{"name":"Erin Richards","avatar":""},{"name":"Andrew Stewart-Jones","avatar":""},{"name":"Victoria Cartagena","avatar":""},{"name":"Cory Michael Smith","avatar":""},{"name":"John Doman","avatar":""},{"name":"Drew Powell","avatar":""},{"name":"Camren Bicondova","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324456);
