INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-noi-loan', 'Kẻ Nổi Loạn', 'Strike One', 'null', 'https://phimimg.com/upload/vod/20240126-1/b72cef2b716e354b3a3a6fe202f4ac82.jpg', '<p>Kẻ nổi loạn là bộ phim về tội phạm gia đình hấp dẫn, cậu bé Juan Garcia sống trong khu phố dưới sự kiểm soát của băng đảng thế giới ngầm của Los Angeles, tội phạm là tương lai được định sẳn của cậu. Bị đẩy vào giữa một đống lộn xộn không liên quan và cậu cũng không biết trước, giam giữ với tội danh bị áp đặt, luật pháp cũng lộ rõ sự bất công. Cơ hội tự do của Juan càng thấp vì xuất thân và định kiến của xã hội. Nổ lực đấu tranh của người thân là hy vọng duy nhất của Juan. Bộ phim khai thác một khía cạnh hoàn toàn khác về thế giới ngầm, gây xúc động mạnh cho người xem.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Alan Corral","avatar":""},{"name":"James Russo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
