INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-ngay-mot-dem', 'Hai Ngày Một Đêm', 'Two Days, One Night', 'https://phimimg.com/upload/vod/20240126-1/acee7408e5c245ab0b8176ed17791c38.jpg', 'https://phimimg.com/upload/vod/20240126-1/fcae548ac413c8627f5d8a43614aeacd.jpg', '<p>Two Days, One Night (Hai Ngày, Một Đêm) là tác phẩm mới nhất của anh em nhà Dardenne. Bộ phim xoay quanh câu chuyện về Sandra (Marion Cotillard) và gia đình sau khi cô có nguy cơ bị đuổi việc. Sandra phát hiện ra các đồng nghiệp, thay vì bỏ phiếu để cô ở lại cơ quan làm việc, lại nhận tiền thưởng cho bản thân. Cô chỉ có hai ngày và một đêm cuối tuần để thuyết phục họ bỏ phiếu lại lần nữa...</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Fabrizio Rongione","avatar":""},{"name":"Catherine Salée","avatar":""},{"name":"Pili Groyne","avatar":""},{"name":"Baptiste Sornin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
