INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-ao-den-2-than-chet', 'Người Đàn Bà Áo Đen 2: Thần Chết', 'The Woman In Black 2: Angel Of Death', 'https://phimimg.com/upload/vod/20240124-1/08a9bbbb3417d37118630d1f3306e9f9.jpg', 'https://phimimg.com/upload/vod/20240124-1/9d1e3cf52cec84ca7877fe46630f919b.jpg', '<p>Phim kể về một nhóm người gồm 8 học sinh – một trong số đó là Edward, cậu bé đang chịu những tổn thương sâu sắc khi phải chứng kiến cảnh mẹ mình bị thiệt mạng do vụ ném bom của Đức quốc xã – cùng cô hiệu trưởng Jean Hogg và cô giáo trẻ Eve Parkins đã phải sơ tán về vùng nông thôn. Điểm đến của họ chính là tòa lâu đài Eel Marsh, nằm trên một hòn đảo tách biệt được nối với đất liền bởi con đường đất Nine Lives Causeway. Những tưởng đã tìm được một mái ấm bình yên trong tình cảnh cuộc chiến đang diễn ra khốc liệt, họ không thể ngờ rằng sự hiện diện của họ trong ngôi nhà này đã làm thức tỉnh một hồn ma đã bám trụ tại đây trong suốt nhiều thế kỷ qua. Và khi bọn trẻ đang cùng nhau chơi trên sân nhà, một hồn ma đầy thù hận bỗng bước ra từ trong bóng tối – người phụ nữ áo đen bí hiểm…</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
