INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tuyen-37', 'Chiến Tuyến 37', 'Alien Outpost', 'https://phimimg.com/upload/vod/20240123-1/e9bb5242f8ffa35dc5bb19e7736f028c.jpg', 'https://phimimg.com/upload/vod/20240123-1/f9098c96f7ab159b12af763f2f30d903.jpg', '<p>Một đoàn làm phim tài liệu theo chân một đơn vị binh lính tinh nhuệ trước cuộc xâm lược của người ngoài hành tinh.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Reegan","avatar":""},{"name":"Matthew Holmes","avatar":""},{"name":"Rick Ravanello","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Adrian Paul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
