INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tu-3-tu-dai-danh-bo-3', 'Bộ Tứ 3 - Tứ Đại Danh Bổ 3', 'The Four 3 - The Four Final Battle', 'https://phimimg.com/upload/vod/20240123-1/9b59cfb0f9a7956545e7d6fe7f9a393d.jpg', 'https://phimimg.com/upload/vod/20240123-1/805de1f7d09c574a55dd06cb090ea1b1.jpg', '<p>Sau cái chết của Liễu Tùy Phong, Cơ Dao Hoa tiếp quản Lục Phiến Môn và tiếp tục điều tra thủ phạm đứng sau, cao thủ nhất đẳng có thể hạ sát hàng loạt võ lâm cao thủ là ai. Trong khi đó, An Lão Gia với thâm thù huyết hận với Gia Cát Chánh Ngã, đã âm thầm cứu sống con trai An Thế Cảnh bằng thảo dược ngàn năm và tiếp tục bắt tay với thừa tướng Sái Kinh để một tay che trời. Về phía tứ đại danh bổ, Vô Tình (Lưu Diệc Phi) sau khi biết được chân tướng của thảm án năm xưa và đối diện với một trong 13 sát thủ - chính là đồng môn Thiết Thủ liệu cô có đủ sức chịu đựng và tình cảm với Lãnh Huyết (Đặng Siêu) sẽ ra sao khi kẻ thứ ba Cơ Dao Hoa chưa bao giờ ngừng đe dọa ?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Trung Cơ","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Chao Deng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
