INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-chui-the', 'Mạng Chửi Thề', 'Swearnet: The Movie', 'https://phimimg.com/upload/vod/20240123-1/769f1d3e94ef66355d3894e36074cc42.jpg', 'https://phimimg.com/upload/vod/20240123-1/16c5bebeacb5440f8508f48a1845e6af.jpg', '<p>Vuột mất hợp đồng truyền hình, những anh chàng ở khu nhà di động đã tự phát hành loạt phim trực tuyến, nhưng lại sớm xảy ra mâu thuẫn vì khác biệt về tư duy và cá nhân.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Mike Smith","avatar":""},{"name":"John Paul Tremblay","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"Patrick Roach","avatar":""},{"name":"Mishael Morgan","avatar":""},{"name":"Sarah Jurgens","avatar":""},{"name":"Shannon Leroux","avatar":""},{"name":"Dana Woods","avatar":""},{"name":"Howard Jerome","avatar":""},{"name":"Tom Green","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
