INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-good-lie', 'The Good Lie', 'The Good Lie', 'https://phimimg.com/upload/vod/20240123-1/d17f7a790bc8f1bda174edf07651a515.jpg', 'https://phimimg.com/upload/vod/20240123-1/d3c234cd0219f4ddc9b141a3d11842b1.jpg', '<p>Một người tị nạn trẻ tuổi trong Nội chiến Sudan trúng xổ số để chuyển đến Hoa Kỳ cùng với ba cậu bé thất lạc khác. Lần đầu tiên chạm trán với thế giới hiện đại, họ phát triển một tình bạn khó có thể xảy ra với một phụ nữ Mỹ nóng nảy được giao nhiệm vụ giúp đỡ họ, nhưng chàng trai trẻ phải vật lộn để thích nghi với cuộc sống mới này và cảm giác tội lỗi về người anh trai mà anh đã bỏ rơi.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Thad Luckinbill","avatar":""},{"name":"Sarah Baker","avatar":""},{"name":"Maria Howell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
