INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alexander-va-mot-ngay-toi-te-kinh-khung-chan-nan-buc-boi', 'Alexander Và Một Ngày Tồi Tệ, Kinh Khủng, Chán Nản, Bực Bội', 'Alexander And The Terrible, Horrible, No Good, Very Bad Day', 'https://phimimg.com/upload/vod/20240122-1/56cae486c8b497f13a58f43bcf6b526a.jpg', 'https://phimimg.com/upload/vod/20240122-1/5beee2fdb679a640827cad3aebf3eef7.jpg', '<p>Một ngày của Alexander bắt đầu với kẹo cao su dính trên tóc, sau đó là nhiều tai họa hơn. Mặc dù anh ấy ít nhận được sự đồng cảm từ gia đình và bắt đầu tự hỏi liệu có phải những điều tồi tệ chỉ xảy ra với mình hay không, nhưng mẹ, bố, anh trai và chị gái của anh ấy đều thấy mình đang sống qua một ngày tồi tệ, khủng khiếp, không tốt, rất tồi tệ của chính họ.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kerris Dorsey","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Dylan Minnette","avatar":""},{"name":"Ed Oxenbould","avatar":""},{"name":"Steve Carell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
