INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-no-ba-vuong', 'Cuồng Nộ Bá Vương', 'The Fatal Encounter', 'https://phimimg.com/upload/vod/20240121-1/e225911880941340e31d929bf03dbc9e.jpg', 'https://phimimg.com/upload/vod/20240121-1/650526f6767280a3e93497aecea0abce.jpg', '<p>Bối cảnh phim nói về một cuộc ám sát nhà vua có thật trong lịch sử. Những âm mưu, sự lừa dối, những sự thật sẽ được phơi bày. Toàn bộ cuộc ám sát diễn ra trong 24 giờ, liệu nhà vua có thể sống sót? Kẻ đứng sau toàn bộ âm mưu đó là ai? Bên cạnh nhà vua bất hạnh đó, ai mới là trung thần, ai là phản nghịch?The fatal encounter (Cuồng nộ bá vương) là bộ phim cổ trang đầu tiên trong sự nghiệp của tài tử Huyn Bin. Đây cũng là tác phẩm điện ảnh đầu tiên của đạo diễn Lea Jae-kyoo, người từng thành công với nhiều bộ phim truyền hình ăn khách. The fatal encounter là bộ phim Hàn Quốc mở màn ấn tượng nhất năm 2014 và nhận được nhiều giải thưởng cũng như đề cử tại các liên hoan phim uy tín ở khu vực châu Á.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Jung Jae Young","avatar":""},{"name":"Han Ji Min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324456);
