INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-nuoc-kajaki', 'Đập Nước Kajaki', 'Kajaki', 'https://phimimg.com/upload/vod/20240121-1/e7448e8e5c6c1745b5c0d2f643b22622.jpg', 'https://phimimg.com/upload/vod/20240121-1/799fa6dbf06f8cf8d9bacb20b366c1c0.jpg', '<p>Đập Nước Kajaki: Một tốp lính trẻ Anh quốc phải đối mặt với những kẻ thù bất ngờ và đáng sợ. Một lòng sông khô cạn. Những quả mìn rình rập dưới mỗi bước chân. Từng bước đi là một lần đánh cược với tử thần, mất chân hoặc thậm chí mất mạng...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mark Stanley","avatar":""},{"name":"Malachi Kirby","avatar":""},{"name":"David Elliot","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
