INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pride', 'Pride', 'Pride', 'https://phimimg.com/upload/vod/20240121-1/0783bcb5714fb8658c504247fa4f418a.jpg', 'https://phimimg.com/upload/vod/20240121-1/b451e0054833038870ecdd5cb229a9ca.jpg', '<p>Năm 1984, một nhóm các nhà hoạt động LGBT quyết định quyên góp tiền để hỗ trợ Liên minh công nhân mỏ quốc gia trong cuộc đình công kéo dài của họ. Chỉ có một vấn đề: Liên minh có vẻ lúng túng khi nhận được sự ủng hộ của họ.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Andrew Scott","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
