INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-chong-dan-choi', 'Vợ Chồng Dân Chơi', 'Mr. & Mrs. Player', 'https://phimimg.com/upload/vod/20240121-1/8a637bf165acb3cecbfed74dc0337e09.jpg', 'https://phimimg.com/upload/vod/20240121-1/65645945d4891efce08cba3acfe2bd69.jpg', '<p>Bộ phim Vợ chồng dân chơi (Mr. &amp; Mrs. Player) là bộ phim mới nhất của vua phim thương mại Hồng Kông Vương Tinh. Nội dung kể về cuộc gặp gỡ định mệnh của một thầy phong thủy và một cô nàng gợi cảm có chung sở thích đi đêm, đập phá ở các vũ trường...</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chrissie Chow","avatar":""},{"name":"Matt Chow","avatar":""},{"name":"Ho-Cheung Pang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
