INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-toi-la-cuong-thi', 'Ông Tôi Là Cương Thi', 'Sifu Vs. Vampire', 'https://phimimg.com/upload/vod/20240207-1/74b57f6edf8fa18a336b1c0c4ccb251f.jpg', 'https://phimimg.com/upload/vod/20240207-1/36d0c7e50e5e815aa5619f861fbeaf7c.jpg', '<p>Người ta nói rằng một xác chết nên được khai quật và di chuyển sau mỗi 30 năm để đảm bảo sự may mắn và thịnh vượng cho con cháu của nó. Khi thời hạn cho thi hài của ông nội sắp đến, ông chủ đài truyền hình Châu Tinh Trì (Kelvin Kwan, Tales from the Dark 2) tìm đến Charlie Jiang (Yuen Biao), người tổ tiên đã thực hiện nghi lễ cho gia đình Châu Tinh Trì, để hoàn thành nhiệm vụ. Khi Jiang từ chối, viện lý do tin rằng nghi lễ này là phi đạo đức, Chow đã nhờ Nicky và Boo ép buộc anh ta tham gia. Tuy nhiên, hàng loạt tai nạn xảy ra khiến xác chết được chuyển đến và bỏ lại ở đài truyền hình Châu Tinh Trì, gây ra một cuộc tắm máu.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuen Biao","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Philip Ng","avatar":""},{"name":"Kelvin Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
