INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-gio-sang-phan-2', '3 Giờ Sáng: Phần 2', '3 A.M. 3D: Part 2', 'https://phimimg.com/upload/vod/20240121-1/4e4d0963a18a49919ca148559c19a4cb.jpg', 'https://phimimg.com/upload/vod/20240121-1/5121145b498df4406d5dac16e0cd2cb4.jpg', '<p>3 Giờ Sáng Phần 2 - 3 A.M. 3D Part 2 là phần tiếp theo của bộ phim cùng tên, xoay quanh cái chết của Rang cùng những đồn đại bí ẩn về một ngôi nhà hoang. Truyền thuyết kể rằng, trong ngôi nhà nguyện bỏ hoang kế bên trường học, nếu bạn đến đó và cầu nguyện trước bức tượng nữ tu không đầu, những gì bạn ước sẽ trở thành sự thật. Sau đó, bạn phải trở lại nơi đó một mình vào lúc 3 giờ sáng. Nếu bạn không làm đúng theo những bước này, bạn sẽ chết.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Ray MacDonald","avatar":""},{"name":"Sinjai Plengpanich","avatar":""},{"name":"Supanart Jittaleela","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
