INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-thuy-hong-nhan', 'Lộ Thủy Hồng Nhan', 'For Love Or Money', 'https://phimimg.com/upload/vod/20240121-1/48d53861bf6218b75b5570942cd5cfdd.jpg', 'https://phimimg.com/upload/vod/20240121-1/38c79ddb826cfbf45727c77a3a045d80.jpg', '<p>For Love or Money dựa trên tiểu thuyết của Zhang Xiaoxian, kể về câu chuyện cảm động giữa một tiểu thư quý tộc sa ngã và người thừa kế giàu có của một công ty lớn. Cô suy sụp và mất phương hướng trong cuộc sống, trong khi anh chọn cuộc sống nghèo khó và tự do để theo đuổi đam mê họa sĩ của mình. Cùng nhau, liệu họ có thể tìm thấy chính mình trong thế giới đầy rẫy những khúc ngoặt này trước khi quá muộn?</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Liu Yifei","avatar":""},{"name":"Rain","avatar":""},{"name":"Xuebing Wang","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Tang Yan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
