INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-dong-day-hy-vong', 'Nơi Đong Đầy Hy Vọng', 'Where Hope Grows', 'https://phimimg.com/upload/vod/20240121-1/095065ed79d0dced4e537ac3c0d39065.jpg', 'https://phimimg.com/upload/vod/20240121-1/8c9f2087fd7a424f7b73405486361d61.jpg', '<p>Calvin Campbell là một cựu cầu thủ bóng chày chuyên nghiệp đã phải giải nghệ sớm do cơn hoảng loạn của anh ấy trên đĩa. Mặc dù anh ấy có tất cả tài năng cho các giải đấu lớn, nhưng anh ấy vẫn phải vật lộn với những đường cong mà cuộc đời đã ném vào anh ấy. Hôm nay, anh vô thức mộng du trong những ngày của mình và thử thách nuôi dạy cô con gái tuổi teen. Cuộc sống của anh ấy đang rơi vào vòng xoáy chậm chạp khi nó đột nhiên được đánh thức và tiếp thêm sinh lực bởi một người khó có thể xảy ra nhất - Produce, một thanh niên mắc hội chứng Down làm việc tại cửa hàng tạp hóa địa phương.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danica McKellar","avatar":""},{"name":"William Zabka","avatar":""},{"name":"Kerr Smith","avatar":""},{"name":"McKaley Miller","avatar":""},{"name":"Kristoffer Polaha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
