INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dong-nho-mua-ha-va-thu', 'Cánh Đồng Nhỏ: Mùa Hạ Và Thu', 'Little Forest: Summer/Autumn', 'https://phimimg.com/upload/vod/20240111-1/a9e4cf266988b7459a1ca78cc280a9b7.jpg', 'https://phimimg.com/upload/vod/20240111-1/a14823f81b3e19af735f9988358e1781.jpg', '<p>Ichiko (Ai Hashimoto) sống ở một thành phố lớn, nhưng quay trở lại quê hương nhỏ của cô ấy, nằm trên một ngọn núi ở vùng Tohoku. Cô ấy tự túc. Ichiko đạt được năng lượng sống giữa thiên nhiên và ăn thức ăn cô ấy tạo ra từ các thành phần theo mùa.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
