INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-loan-cung-tammy', 'Nổi Loạn Cùng Tammy', 'Tammy', 'https://phimimg.com/upload/vod/20240104-1/7a00885e2724657897284e393af1153f.jpg', 'https://phimimg.com/upload/vod/20240104-1/fa7e09ed2f3c80561eed958c0d5c836b.jpg', '<p>Đối với Tammy, một nhân viên kinh doanh bánh mì kẹp thịt, một ngày tồi tệ cứ trở nên tồi tệ hơn. Cô làm hỏng xe, mất việc và phát hiện ra rằng chồng mình không chung thủy. Đã đến lúc Tammy lên đường, nhưng không có tiền hay phương tiện đi lại, các lựa chọn của cô bị hạn chế. Lựa chọn duy nhất của cô là một chuyến du ngoạn trên đường với bà Pearl nghiện rượu nặng, người có ô tô, tiền mặt và rất thích ngắm thác Niagara. Đó không phải là lối thoát mà Tammy đã nghĩ đến, nhưng đó có thể là điều cô ấy cần.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melissa McCarthy","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Dan Aykroyd","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
