INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-tuong-nhung-van-muon-yeu-soai-ca', 'Ảo Tưởng Nhưng Vẫn Muốn Yêu: Soái Ca', 'Love, Chunibyo and Other Delusions! – Heart Throb-', 'https://phimimg.com/upload/vod/20240112-1/4d8f716fc2a1c9bcb645ef109b11055f.jpg', 'https://phimimg.com/upload/vod/20240112-1/a30b72b8ae91d8314d67ad821dc58152.jpg', '<p>Qua bao khó khăn, cuối cùng Togashi Yuuta từng mắc hội chứng cấp 2 và Takanashi Rikka hiện đang mắc hội chứng cấp 2 xác nhận quan hệ yêu đương. Bởi mẹ đi công tác và lầm lỗi của ông nội, Rikka đành phải ở nhờ nhà Yuuta và cả hai bắt đầu chung sống với nhau. Trong mùa tốt đẹp, các bạn thân sum họp lại và câu chuyện lãng mạn, thú vị lại xúc động lòng người trình diễn tiếp...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
