INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-giay-cao-got', 'Thám Tử Giày Cao Gót', 'Man On High Heels', 'null', 'https://phimimg.com/upload/vod/20240108-1/162d0703a22594f42126442a5004ecb8.jpg', '<p>Bộ phim Thám Tử Giày Cao Gót - Man On High Heels xoay quanh một thám tử điều tra sở hữu kĩ năng giác quan thứ 6 đặc biệt - Yoon Ji Wook. Với kĩ năng phán đoán tình huống cũng như biết trước mọi hành động của kẻ địch Yoon Ji Wook được sở cảnh sát xem như là một thám tử đại tài trong phá án cũng như khi chiến đấu với tội phạm. Thế nhưng ít ai biết được đằng sau vẻ ngoài lịch lãm nam tính của anh là một tâm hồn yếu đuối của một người phụ nữ, sinh ra trong hình hài của người đàn ông...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Seung Won","avatar":""},{"name":"Oh Jung Se","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
