INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dao-cua-giovanni', 'Hòn Đảo Của Giovanni', 'Giovanni''s Island', 'https://phimimg.com/upload/vod/20240108-1/aa79f4175cdb5c6f9d3ff649ab7ad735.jpg', 'https://phimimg.com/upload/vod/20240108-1/d2ae4f876bcdfdf12cdbef762bbd05ad.jpg', '<p>Sau hậu quả của cuộc xung đột tàn khốc nhất mà nhân loại từng trải qua, hòn đảo nhỏ bé Shikotan đã trở thành một phần của Tỉnh Sakhalin... và trên đường biên giới chưa được hàn gắn ở nơi xa xôi này của thế giới, tình bạn giữa những đứa trẻ từ hai quốc gia khác nhau đã chớm nở, phấn đấu vượt qua rào cản ngôn ngữ và những sóng gió của lịch sử. Được truyền cảm hứng bởi những sự kiện có thực.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masachika Ichimura","avatar":""},{"name":"Polina Ilyushenko","avatar":""},{"name":"Hiroshi Inuzuka","avatar":""},{"name":"Saburô Kitajima","avatar":""},{"name":"Tatsuya Nakadai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
