INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-eyes-diary', 'The Eyes Diary', 'The Eyes Diary', 'https://phimimg.com/upload/vod/20240104-1/77b058d7783ad8e062da0cfe6d173fcf.jpg', 'https://phimimg.com/upload/vod/20240104-1/39c499f55bee6aa315daa052d94e16d5.jpg', '<p>Đã ba tháng kể từ khi Nott (Punjan) tràn đầy nỗi buồn và đau khổ như chưa từng có. Đó là bởi vì một đêm khiến anh ta mất PLA (tập trung) bạn gái yêu dấu của mình trong vụ tai nạn xe máy. Anh ấy muốn quên đi nhưng không thể, nghe anh ấy đầy tội lỗi và đau khổ và gần như bùng nổ với sự đau buồn. Cách duy nhất để anh ấy vượt qua điều này là gặp lại PLA lần nữa trong thế giới bên kia của cô ấy, vì vậy anh ấy cố gắng tìm cách nhìn thấy Ghost. Cuối cùng, anh quyết định tham gia tình nguyện viên phi hành đoàn khẩn cấp và bí mật nhặt đồ đạc của những người chết vì chính mình. Anh ta nghĩ rằng bằng cách làm điều đó, anh ta sẽ có thể nhìn thấy những con ma, sau đó anh ta sẽ có thể nhìn thấy PLA. Tuy nhiên, mọi thứ không đơn giản. Nott chưa bao giờ gặp bất kỳ con ma nào trong khi người bạn đời của anh ta nhìn thấy chúng mọi lúc cho đến khi không ai dám ở trong nhà nữa chỉ là Motta (Maeko), bạn bè của anh ta dường như hiểu anh ta và luôn sẵn sàng đứng với anh ta. John (Jack) Bạn của anh ấy tại Quỹ Tình nguyện cố gắng bảo anh ấy đừng hỏi vấn đề, vì thấy linh hồn không phải là những thứ được chụp nhẹ. Nott không nghe Jack vì Nott muốn nói với Pla Something. Nott nâng cao những thách thức của mình để đối đầu với tất cả các linh hồn ám ảnh để họ có thể dẫn anh ta đến PLA. Anh ta có thể gặp PLA như hy vọng không? Anh ấy sẽ có thể nói với PLA những gì anh ấy muốn? Bởi vì anh ta chưa bao giờ mong đợi rằng mọi thứ đang xảy ra đã nằm dưới PLA Chăm sóc mắt.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
