INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-thoi-chien', 'Chuyện Tình Thời Chiến', 'Suite Francaise', 'https://phimimg.com/upload/vod/20240104-1/abbfdc1b7fbdcb903d5fd903ffab839a.jpg', 'https://phimimg.com/upload/vod/20240104-1/8305d026295400b8216c9778a101cc8b.jpg', '<p>Phim Chuyện Tình Thời Chiến - Suite Francaise 2015 sẽ đưa ta đến với chuyện tình lãng mạn và éo le thời Thế Chiến thứ 2 giữa Lucile Angellier, một cô gái ở một ngôi làng Pháp bị xâm lược và Bruno von Falk, một người lính Đức vừa xâm lược ngôi làng đó. Liệu tình yêu bị thử thách bởi chiến tranh và hậu quả của nó có tồn tại qua những khắc nghiệt xung quanh không?</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Williams","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Margot Robbie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324456);
