INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ca-heo-2', 'Câu Chuyện Cá Heo 2', 'Dolphin Tale 2', 'https://phimimg.com/upload/vod/20240104-1/ce4355801a8c9bf9466c695b888f3c8f.jpg', 'https://phimimg.com/upload/vod/20240104-1/f54337ad737ae4ee0f23579bc007b7a4.jpg', '<p>Sau khi được cứu sống, Winter được mang về thủy cung nuôi dưỡng. Tại đây, Winter được chế tạo một cái đuôi nhân tạo thay cho cái đuôi bị cụt trước đó. Nhưng chẳng may, bạn cùng hồ bơi của Winter là Panama lại chết bất ngờ do tuổi già. Nhận thấy tầm ảnh hưởng của lối sống bầy đàn, các nhân viên đã điều chuyển Winter đến một thủy cung khác và ra sức giúp đỡ Winter hòa nhập với đàn mới.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathan Gamble","avatar":""},{"name":"Cozi Zuehlsdorff","avatar":""},{"name":"Harry Connick","avatar":""},{"name":"Ashley Judd","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
