INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-san-nguoi', 'Đêm Săn Người', 'Kristy', 'https://phimimg.com/upload/vod/20240104-1/d9c834c77da65765f4179a9973538343.jpg', 'https://phimimg.com/upload/vod/20240104-1/f5e2062f5ea3859fd9c89eba22cd03d0.jpg', '<p>Trong dịp nghỉ Lễ Tạ Ơn, khi các bạn học quay về nhà cho một kỳ nghỉ dài thì cô sinh viên Justine quyết định ở lại trường vì không thể trang trải tấm vé máy bay đắt đỏ. Trong ngôi trường rộng mênh mông, chỉ còn cô và vài người bảo vệ. Tưởng rằng kỳ nghỉ sẽ bình yên trôi qua, cho đến khi một nhóm sát nhân hàng loạt bám theo cô và xâm nhập vào ngôi trường… Rơi vào tình thế sống còn, bản năng sinh tồn trong cô đã trỗi dậy. Cô buộc phải chinh phục nỗi sợ hãi của mình, đứng lên chiến đấu và đánh gục từng tên sát nhân trong băng nhóm.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Greene","avatar":""},{"name":"Haley Bennett","avatar":""},{"name":"Lucas Till","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
