INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thay-ac-quy-2', 'Không Thấy Ác Quỷ 2', 'See No Evil 2', 'https://phimimg.com/upload/vod/20240104-1/b62314b01de5f23a893d2fd41cd6f8d7.jpg', 'https://phimimg.com/upload/vod/20240104-1/aac4413cddc4a569ec711cf805b2d0bd.jpg', '<p>Một nhóm bạn đến nhà xác thành phố vào lúc đêm khuya để tạo bất ngờ cho Amy vào ngày sinh nhật của cô. Nhưng điều bất ngờ đang đến với họ khi xác chết một mắt của kẻ tâm thần tàn bạo Jacob Goodnight bất ngờ trỗi dậy từ một phiến đá ngầm lạnh lẽo dưới tầng hầm, biến bữa tiệc hoang dã của họ thành một lễ hội giết người kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Harris","avatar":""},{"name":"Glenn Jacobs","avatar":""},{"name":"Kaj-Erik Eriksen","avatar":""},{"name":"Katharine Isabelle","avatar":""},{"name":"Chelan Simmons","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
