INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tho', 'Ngây Thơ', 'PK', 'https://phimimg.com/upload/vod/20240104-1/2ee399e987606440ba0aea73982d9cb4.jpg', 'https://phimimg.com/upload/vod/20240104-1/94e313158cb431c5d2c618f1d51d653a.jpg', '<p>Ngây Thơ - PK: Phim kể về một anh chàng người ngoài hành tinh xuống Trái Đất và làm mất điều khiển tàu vũ trụ của mình. Anh đi khắp nơi và làm mọi cách để tìm lại điều khiển của mình. Cũng nhờ đó anh có dịp tiếp xúc với nhiều tôn giáo và tín ngưỡng khác nhau. Nhờ sự giúp đỡ của một cô gái tên Jaggu, anh đã đánh bại được sự cuồng tín tồn tại ở Ấn Độ nhờ những câu hỏi ngây ngô của mình, lấy lại điều khiển và trở về hành tinh.</p>', 'Full', 1, 'single', 'completed', 5, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Anushka Sharma","avatar":""},{"name":"Sanjay Dutt","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324456);
