INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-toi-cao', 'Quyền Tối Cao', 'Supremacy', 'https://phimimg.com/upload/vod/20231231-1/5a0fb6f1b6def0bc165a79f3449ed731.jpg', 'https://phimimg.com/upload/vod/20231231-1/f1735652c34e2cb30db2fc6b64f4748b.jpg', '<p>Câu chuyện xoay quanh một người theo chủ nghĩa tối cao da trắng được ân xá vừa giết một cảnh sát và bắt một gia đình da đen làm con tin. Trong vòng vài giờ sau khi được trả tự do sau 14 năm bị biệt giam trong Nhà tù Pelican Bay State được bảo vệ tối đa, Garrett Tully lại tiếp tục chạy trốn. Khi tìm thấy một ngôi nhà trên con đường đất và bắt một gia đình làm con tin, anh ta nghĩ rằng Hội Anh em Aryan chống lưng cho mình – và các nạn nhân trong vụ bắt cóc của anh ta là người da đen. Tộc trưởng của gia đình, ông Walker, là một cựu tội phạm chán ghét cảnh sát đến mức ông không chấp nhận con trai mình vì đã trở thành cảnh sát. Nhìn thấy sự tuyệt vọng quen thuộc ở Tully, Walker từ chối gọi chính quyền để được giúp đỡ, khiến căng thẳng gia đình leo thang và sớm mắc phải những sai lầm nghiêm trọng.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Glover","avatar":""},{"name":"Julie Benz","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Dawn Olivieri","avatar":""},{"name":"Derek Luke","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
