INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-lam-trieu-phu', 'Ngố Làm Triệu Phú', 'Are You Here', 'https://phimimg.com/upload/vod/20231231-1/78a9f9d72b2c565aa62029e5d36f91e1.jpg', 'https://phimimg.com/upload/vod/20231231-1/fd340f502282088f951faad07cc203ef.jpg', '<p>Hai nhân vật trung tâm của Are You Here là đôi bạn thân Steve Dallas và Ben Baker. Trong khi Steve là một nhân viên quen dại gái làm việc cho bản tin thời tiết địa phương, thì Ben lại là một gã trẻ tuổi mới biết tin là mình sắp sửa được nhận một khoản gia tài kếch xù từ người cha mà anh vốn xa lánh suốt bấy lâu nay. Cả hai trở về quê của Ben với mong muốn ôm trọn chỗ gia sản. Nhưng chuyến hành trình của họ luôn bị cản trở bởi người chị gái ranh ma và bà mẹ kế 25 tuổi của Ben.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Amy Poehler","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
