INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aldnoahzero', 'Aldnoah.Zero', 'Aldnoah.Zero', 'https://phimimg.com/upload/vod/20240112-1/43c1df39595c070f354d8ce797028806.jpg', 'https://phimimg.com/upload/vod/20240112-1/e2649c4dae363f5e402d25391e2cf757.jpg', '<p>Năm 1972, Apollo 17 phát hiện ra một hypergate đến sao Hỏa trên bề mặt của mặt trăng. Ngay sau đó, một cuộc chiến tranh nổ ra giữa Trái Đất và sao Hỏa, sao Hỏa và binh lính bắt đầu đi xuống từ bầu trời, cưỡi khổng lồ thép, ý định tiêu diệt nhân loại.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324456);
