INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh', 'Mật Danh', 'The Prince', 'https://phimimg.com/upload/vod/20240102-1/aeed29f442416234ebf70f34148431a6.jpg', 'https://phimimg.com/upload/vod/20240102-1/3a61c9dfaa99f6d50e7bc0ce6e6a5143.jpg', '<p>Một người đàn ông của gia đình hóa ra là một người thi hành án đám đông đã nghỉ hưu phải đi khắp đất nước để tìm con gái đã mất tích của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Jessica Lowndes","avatar":""},{"name":"Gia Mantegna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
