INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiem-dat', 'Chiếm Đất', 'The Homesman', 'https://phimimg.com/upload/vod/20240102-1/ee328fc064a651537d61ece1a239ce8a.jpg', 'https://phimimg.com/upload/vod/20240102-1/2979568c588e50fd769171ff9a366c5e.jpg', '<p>CHIẾM ĐẤT - THE HOMESMAN là một bộ phim truyền hình Viễn Tây Mỹ 2014 của đạo diễn Tommy Lee Jones dựa trên cuốn tiểu thuyết cùng tên của Glendon Swarthout. Để đổi lấy sự giúp đỡ George Briggs (Tommy Lee Jones), Mary Bee Cuddy (Hilary Swank) tuyển dụng anh ta để giúp hộ tống ba người phụ nữ mất trí từ Nebraska tới Iowa. Một hành trình với cuộc chiến tranh tâm lý và những mối nguy hiểm liên tục rình rập. Liệu họ sẽ đến Iowa an toàn?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Hilary Swank","avatar":""},{"name":"Grace Gummer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
