INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-boi-ma-quai', 'Hồ Bơi Ma Quái', 'Afterimages (The Answer)', 'https://phimimg.com/upload/vod/20240128-1/3949f1bf7deb54bf704457dcb3b491f6.jpg', 'https://phimimg.com/upload/vod/20240128-1/a8c37053a28c78b668637625fef1dd98.jpg', '<p>Một nhóm sinh viên điện ảnh đã đốt những đoạn phim băng từ của một bộ phim kinh dị. Từ đám tro tàn đó, họ nhận lại những bí mật vô cùng ám ảnh.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sheena Chan","avatar":""},{"name":"Pamelyn Chee","avatar":""},{"name":"Daniel Jenkins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
