INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rang-nanh', 'Răng Nanh', 'Tusk', 'https://phimimg.com/upload/vod/20231231-1/afdda3c30f78541d84f46c31e60cfe71.jpg', 'https://phimimg.com/upload/vod/20231231-1/68c8bb2dbb9a9b52ac3a68bd336b3d1d.jpg', '<p>Khi PODCASTER WALLACE đi đến Canada để phỏng vấn một ai đó, anh ta lướt qua một người đàn ông kỳ lạ tên là Howe có nhiều câu chuyện để kể về cuộc sống trong quá khứ của mình trong cuộc phỏng vấn của mình. Wallace thức dậy vào ngày hôm sau tìm ra Howe không phải là người mà anh ta nghĩ. Howe đã có kế hoạch phẫu thuật và tinh thần biến Wallace thành một con hải mã.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
