INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-to', 'Đôi Mắt To', 'Big Eyes', 'https://phimimg.com/upload/vod/20231231-1/a9bf9dee68c951030ed0d47dda7d24d6.jpg', 'https://phimimg.com/upload/vod/20231231-1/4ca7f967a51a7e446ef133692a51472c.jpg', '<p>Đôi Mắt To - Big Eyes lấy nguồn cảm hứng từ câu chuyện của Keanes - một nghệ sĩ nổi tiếng với những tác phẩm tranh gây tiếng vang hồi thập niên 50 thế kỉ trước - tuy nhiên những tác phẩm của ông đều do Margaret sáng tác. Margaret và Keanes kết hôn rồi dần trở nên nổi tiếng với những bức tranh vẽ trẻ em với đôi mắt lớn. Walter tuyên bố rằng ông là tác giả duy nhất của các bức tranh. Ban đầu, Margaret cũng đồng tình vì bà nghĩ rằng, người ta sẽ trả giá cao hơn cho những bức tranh có tác giả là nam giới. Sau khi hai vợ chồng ly dị, Margaret cố gắng giành lại quyền làm chủ những tác phẩm của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Christoph Waltz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
