INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-cach-mang-bit-tet', 'Cuộc Cách Mạng Bít Tết', 'Steak Revolution', 'https://phimimg.com/upload/vod/20231231-1/e5816808fe1cb8b4e1067268c14e5df5.jpg', 'https://phimimg.com/upload/vod/20231231-1/dd3e294aae462801f76449846aadd19b.jpg', '<p>Phim Cuộc Cách Mạng Bít Tết - Steak Revolution 2014: Cuộc phiêu lưu ẩm thực để tìm ra món bít tế ngon nhất trên toàn cầu. Những người nhân giống, nông dân, hàng thịt, đầu bếp, sử gia và doanh nhân vòng quanh thế giới (Pháp, Ý, Tây Ban Nha, Thụy Điển, Bỉ, Anh, Mỹ, Canada, Nhật, Argentina, Brazil) sẽ giúp chúng ta hiểu được cuộc cách mạng đang diễn ra ngay tại thời điểm này và những thách thức đang đón chờ.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Franck Ribière","avatar":""},{"name":"Yves-Marie Le Bourdonnec","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
