INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-vp7500', 'Chuyến Bay VP7500', 'Flight 7500', 'https://phimimg.com/upload/vod/20231231-1/6b3ca332b2cbe83ab652016d1a6a8454.jpg', 'https://phimimg.com/upload/vod/20231231-1/c455213c1b7d81e0a0d948e75b5771fc.jpg', '<p>Chuyến bay 7500 khởi hành từ Sân bay Quốc tế Los Angeles đến Tokyo. Khi chuyến bay qua đêm bay qua Thái Bình Dương trong suốt hành trình kéo dài 10 giờ, các hành khách chạm trán với thứ dường như là một thế lực siêu nhiên trong cabin.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Kwanten","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Scout Taylor-Compton","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
