INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-serena', 'Nàng Serena', 'Serena', 'https://phimimg.com/upload/vod/20231231-1/a2ff811535ac83e9a0e3aa795d64f6b7.jpg', 'https://phimimg.com/upload/vod/20231231-1/83565c1d90fc86da3db2d1fe7e2bd008.jpg', '<p>Vùng núi Bắc Carolina vào cuối những năm 1920 – George và Serena Pemberton, cặp vợ chồng mới cưới yêu nhau, bắt đầu xây dựng một đế chế gỗ. Serena sớm chứng tỏ mình ngang hàng với bất kỳ người đàn ông nào: giám sát những người khai thác gỗ, săn rắn đuôi chuông, thậm chí cứu mạng một người đàn ông trong vùng hoang dã. Với quyền lực và tầm ảnh hưởng hiện đang nằm trong tay, Pembertons từ chối để bất cứ ai cản đường tình yêu và tham vọng thổi phồng của họ. Tuy nhiên, khi Serena phát hiện ra quá khứ bị che giấu của George và đối mặt với số phận không thể thay đổi của chính mình, cuộc hôn nhân đầy đam mê của Pemberton bắt đầu sáng tỏ dẫn đến một cuộc tính toán đầy kịch tính.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Blake Ritson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
