INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-dung-lai', 'Không Dừng Lại', 'Non-Stop', 'https://phimimg.com/upload/vod/20231231-1/e819a60ea6efd97d2e53be0173102f72.jpg', 'https://phimimg.com/upload/vod/20231231-1/db21bda35f691c39fcf45c37a5da6a21.jpg', '<p>Không tặc 2014 - Non-stop 2014 là một phim hành động bí ẩn của đạo diễn Jaume Collet-Serra với sự tham gia của ngôi sao Liam Neeson. Nghiện rượu và chán đời, Cảnh sát Giám sát hoạt động bay Mỹ Bill Marks (Liam Neeson) đánh mất hết niềm đam mê công việc từ lâu. Mạng sống bị đe dọa trong mỗi chuyến bay nhưng với ông nó chỉ là những công việc không đáng để tâm. Tuy nhiên những công việc không đáng để tâm kia trở thành một cuộc khủng hoảng nặng nè trong một chuyến bay đến London. Ông nhận hàng loạt các tin nhắn văn bản hướng dẫn chuyển 150 triệu đô-la vào một tài khoản ở nước ngoài hoặc là cứ 20 phút sẽ có một người chết.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Scoot McNairy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
