INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-cong-ly', 'Bảo Vệ Công Lý', 'Jai Ho', 'https://phimimg.com/upload/vod/20231230-1/4b23c876d2ebbb700e86fd2aa7f926a0.jpg', 'https://phimimg.com/upload/vod/20231230-1/3fefc045d51d1ac41a7b2a910f0126bd.jpg', '<p>Là một cựu quân nhân chính trực, Jai đơn độc chiến đấu chống tham nhũng và bất công. Với một câu thần chú đơn giản để trả tiền, anh ấy bắt đầu bằng cách giúp đỡ một người và hình thành một nhóm người giúp đỡ lẫn nhau ngày càng phát triển.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Tabu","avatar":""},{"name":"Danny Denzongpa","avatar":""},{"name":"Daisy Shah","avatar":""},{"name":"Mahesh Manjrekar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
