INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-gale', 'Cuộc Đời Của Gale', 'October Gale', 'https://phimimg.com/upload/vod/20231230-1/5b48f5034d200eb5cb533a5a7928c852.jpg', 'https://phimimg.com/upload/vod/20231230-1/40517f713ed36ec5e154824869dc90c0.jpg', '<p>Một bác sĩ tiếp nhận một người đàn ông bí ẩn dạt vào bờ biển tại ngôi nhà hẻo lánh của cô với vết thương do đạn bắn. Cả hai nhanh chóng biết được kẻ giết người đã đến để hoàn thành công việc, trong khi một cơn bão đã cắt đứt họ khỏi đất liền.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patricia Clarkson","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Aidan Devine","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
