INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thang-nam-ruc-ro', 'Những Tháng Năm Rực Rỡ', 'My Brilliant Life', 'https://phimimg.com/upload/vod/20240123-1/243591462fa49c4757bb36ce3a2c7e5e.jpg', 'https://phimimg.com/upload/vod/20240123-1/e33a4fc6b61fbec2818c9081ce7f127c.jpg', '<p>My Brilliant Life được xây dựng dựa trên cuốn tiểu thuyết cùng tên của nhà văn Kim Ae Ran. Phim là câu chuyện cảm động về cặp Mira và Dae Su, khi họ bất ngờ có con ở tuổi 17. Con trai của họ, Ah Reum, được chẩn đoán bị hội chứng Progeria, một khiếm khuyết di truyền hiếm gặp, khiến bé già đi nhanh chóng ngay từ khi còn nhỏ.Bộ phim khiến khán giả sống chậm lại, nghĩ sâu hơn, chạm tới trái tim và lấy đi nước mắt của khán giả ở nhiều khoảnh khắc. My Brilliant Life chinh phục người xem bằng lối kể chuyện mạch lạc, giản dị, cùng phong cách dẫn dắt cảm xúc đậm chất Hàn Quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Dong Won","avatar":""},{"name":"Cha Eun Woo","avatar":""},{"name":"Song Hye Kyo","avatar":""},{"name":"Baek Il‑seob","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
