INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-my-nhan', 'Kung Fu Mỹ Nhân', 'Kung Fu Angels', 'https://phimimg.com/upload/vod/20240123-1/b58c9fde0b01bbfb53ee96baf0d10e28.jpg', 'https://phimimg.com/upload/vod/20240123-1/98a648a7dc2884f70d100793a6f0cae2.jpg', '<p>Kung Fu Mỹ Nhân - Kung Fu Angels kể về một tiểu thư giàu có nhưng rất nghịch ngợm. Cô liên tục bị chuyển trường vì không có trường nào có thể chấp nhận được cô. Cuộc sống của cô thay đổi khi tham gia vào một đội võ thuật của một trường tại Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Alex Lam","avatar":""},{"name":"Janelle Sing","avatar":""},{"name":"Jeremy Tsui","avatar":""},{"name":"Karena Ng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
