INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-tuoi-16', 'Trở Lại Tuổi 16', '16…Again', 'https://phimimg.com/upload/vod/20240123-1/961169fbd922f62f9d929a3d3cee3678.jpg', 'https://phimimg.com/upload/vod/20240123-1/d73cd5a8d9f9b9978e6c43b5273e5f20.jpg', '<p>Claire Karenberg không hài lòng với cuộc sống hiện tại của mình. Hai đứa con của cô đang ở tuổi nổi loạn còn ông chồng có dấu hiệu ngoại tình. Một phép màu kì lạ bất ngờ đưa cô trở lại tuổi 16. Ở đó, cô có thể gần gũi hơn với hai đứa con của mình và có cơ hội níu giữ hạnh phúc gia đình. Được trở lại tuổi 16, nhân vật Claire Karenberg không sống vì bản thân mình. Cô tận dụng cơ hội để gần gũi, tìm hiểu tâm tư tình cảm của những thành viên trong gia đình, điều cô đã xao nhãng khi trưởng thành. Nó cũng giúp cô gìn giữ được hạnh phúc mái ấm mà trong tương lai cô sẽ đánh mất.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Wiedemann","avatar":""},{"name":"Quirin Berg","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
