INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-hat-de', 'Phi Vụ Hạt Dẻ', 'The Nut Job', 'https://phimimg.com/upload/vod/20231230-1/8dc5e46ae9bfd8772642dad00f41e442.jpg', 'https://phimimg.com/upload/vod/20231230-1/a859cb94b3b3b88b63df2f838e3ca027.jpg', '<p>Phim Phi Vụ Hạt Dẻ - The Nut Job 2014: Câu chuyện về một chú sóc Surly bị đuổi khỏi đàn trong công viên thành phố vì vô tình làm cháy kho lương thực mùa đông. Lang thang trong thành phố Surly tình cờ và kết bạn với chú chuột, và niềm hy vọng của Surly với mục tiêu là trộm cửa hàng hạt dẻ vì có như thế mới cứu được đại gia đình của mình và trở về nhà.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Will Arnett","avatar":""},{"name":"Katherine Heigl","avatar":""},{"name":"Brendan Fraser","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
