INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-bi-danh-cap', 'Kho Báu Bị Đánh Cắp', 'The Monuments Men', 'https://phimimg.com/upload/vod/20231230-1/391a55461a0e5ea1146b8b259f0871b9.jpg', 'https://phimimg.com/upload/vod/20231230-1/a9ab97ad53f79ae77068c580fc0f2ac4.jpg', '<p>Trong Chiến tranh thế giới 2, quân Đế quốc xã đã đánh cắp các tác phẩm nghệ thuật ở nhiều quốc gia. Một đội ngũ bảo vệ di tích gồm 7 người được lập ra để bảo vệ những cổ vật còn sót lại và tìm kiếm những tác phẩm còn mất tích. Đây là câu chuyện cảm động, đầy tính nhân văn vể chuyến hành trình bảo vệ lịch sử nhân loại, một điều thiêng liêng mà không phải ai cũng nhìn ra giá trị của nó.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Bill Murray","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
