INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-suc-soi', 'Tuổi Trẻ Sục Sôi', 'Hot Young Bloods', 'null', 'https://phimimg.com/upload/vod/20231219-1/364ab17e2adef63de44e0be688e65824.jpg', '<p>Tại một trường cấp ba đầu thập niên 80, cảm xúc tình yêu, sự giận dữ và tình bạn nảy sinh giữa cô nàng cứng cỏi, gã mơ mộng, thủ lĩnh băng đảng và học sinh mới đáng yêu.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jong Suk","avatar":""},{"name":"Park Bo Young","avatar":""},{"name":"Lee Se Young","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
