INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-nha-am-anh', 'Căn Nhà Ám Ảnh', 'Cursed House', 'https://phimimg.com/upload/vod/20240121-1/0d98e70a94832ac3042d44b203a0122c.jpg', 'https://phimimg.com/upload/vod/20240121-1/4941ab0e15d9a794362b03c0cf935ba6.jpg', '<p>Căn Nhà Ám Ảnh - Cursed House xoay quanh ngôi nhà với nhiều bí mật kinh hoàng của gia đình In. Khi các thành viên chưa hết vui mừng vì sở hữu một căn nhà riêng thì những sự kiện kỳ lạ liên tục xảy ra như thức ăn thối rữa rất nhanh, cô con gái liên tục đi mộng du, ngay cả In cũng trở nên nóng nảy thất thường khiến anh bị sếp sa thải. Và cả mẹ vợ cũng qua đời trong một tai nạn khó hiểu. Không thể chịu nổi, vợ In tìm đến sự giúp đỡ của thầy đồng. Và cô hiểu ra rằng, ngoài gia đình cô, căn nhà còn có sự hiện diện của một hồn ma căm phẫn vị bị chồng ruồng rẫy lúc sinh thì.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Akara Amarttayakul","avatar":""},{"name":"Chinaradi Anupongphichart","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
