INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-xu-oz-dorothy-tro-lai', 'Huyền Thoại Xứ Oz: Dorothy Trở Lại', 'Legends Of Oz: Dorothy''s Return', 'https://phimimg.com/upload/vod/20231230-1/8fb96082371e2682ce1841bfad21b081.jpg', 'https://phimimg.com/upload/vod/20231230-1/1cd09fcd5795c9b2f8e826ebadf6cb62.jpg', '<p>Sau chuyến phiêu lưu đầu điên tại xứ Oz, Dorothy trở về quê nhà Kansas nhưng cô bé nhanh chóng tìm đường trở lại xứ Oz khi biết tin bạn bè của cô và toàn bộ xứ sở thần tiên này đang bị đe dọa. Cùng những người bạn cũ và mới, Dorothy phải chiến đấu chống lại Jester, kẻ muốn kiểm soát xứ Oz và biến toàn bộ cư dân thành con rối.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2014, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dan Aykroyd","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Lea Michele","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
