INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-cuoc-song', 'Câu Chuyện Cuộc Sống', 'Life Story', 'câu chuyện cuộc sống life story david attenborough ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-luan-chuyen-tau-dinh-menh', 'Thái Bình Luân - Chuyến Tàu Định Mệnh', 'The Crossing', 'https://phimimg.com/upload/vod/20231230-1/e9bfaac6c9a6e2e93b241feaa594908e.jpg', 'https://phimimg.com/upload/vod/20231230-1/9606edc7c00db5e461b1ff4b15345df0.jpg', '<p>Thái Bình Luân - Chuyến Tàu Định Mệnh - The Crossing: Bộ phim lấy bối cảnh thời gian hơn 50 năm trước dựa theo sự kiện tháng 1/1949, chiếc tàu thủy Thái Bình xuất phát từ thành phố cảng Cơ Long (Keelung) của Đài Loan đến Thượng Hải và bị chìm. Có tất cả 1000 người thiệt mạng. Được ví như phiên bản Trung Hoa của Titanic, là câu chuyện về 3 đôi tình nhân ở Trung Quốc đi trên con tàu xấu số trong một chuyến di cư tập thể, diễn ra trong bối cảnh nội chiến Trung Quốc. Những con người từ những vùng miền khác nhau cùng hội ngộ trên chuyến tàu định mệnh, họ phải vật lộn đấu tranh giữa tình yêu, nghĩa vụ, lòng tham, sự đố kị, quyết liệt dành giật lại mạng sống trên con tàu đang chìm dần vào biển sâu. Liệu ai sẽ là người may mắn sống sót để kể lại câu chuyện còn dang dở?</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shan Cong","avatar":""},{"name":"Xiaoming Huang","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
