INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-cam', 'Giam Cầm', 'The Captive', 'https://phimimg.com/upload/vod/20231219-1/502b731638f3ca89f07b9f8723dd728c.jpg', 'https://phimimg.com/upload/vod/20231219-1/929990ee29e0678380ab92b936a36630.jpg', '<p>Tám năm sau khi Cassandra mất tích, một số sự cố đáng lo ngại dường như chỉ ra rằng cô ấy vẫn còn sống. Cảnh sát, cha mẹ và bản thân Cassandra sẽ cố gắng làm sáng tỏ bí ẩn về sự mất tích của cô.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Kevin Durand","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
