INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-hu-pha-dam-cuoi', 'Gái Hư Phá Đám Cưới', 'Bad Sister', 'https://phimimg.com/upload/vod/20231219-1/8e71b55f0f21e53cd1302afe5cabe1eb.jpg', 'https://phimimg.com/upload/vod/20231219-1/7998ec70012d7e0451c1487dd3e5c7c4.jpg', '<p>Phim Gái Hư Phá Đám Cưới - Bad Sister 2014: Hoàng Nhị San là vị chiêm tinh gia chuyên nghiệp, gần như lấy chòm sao làm nguyên tắc cuộc sống, khi được biết cậu em trai ở Hàn Quốc sắp tổ chức đám cưới, mà cô dâu không phải là người thích hợp nhất để lựa chọn theo như tinh bàn nhận định, liền chạy thẳng đến Busan muốn làm hỏng hôn lễ. Trên máy bay, Hoàng Nhị San uống say, đem tâm sự và kế hoạch đều kể cho hành khách ngồi cạnh Phác Tuấn Hạo, sau khi hạ cánh lại phát hiện Phác chính là cha vợ chưa cưới của em trai, hai người vì tháo tung một đoạn hôn nhân còn hợp thành đồng minh tạm thời, nhưng trong tương xử, hai bên lại dần dần phát sinh cảm tình.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Y Hàm","avatar":""},{"name":"Ji Jin Hee","avatar":""},{"name":"Trần Học Đông","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
