INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-ca-cua-bien-ca', 'Khúc Ca Của Biển Cả', 'Song Of The Sea', 'https://phimimg.com/upload/vod/20231219-1/b9f1373b11a191a17df95b703fccdcd3.jpg', 'https://phimimg.com/upload/vod/20231219-1/6e1d783345cc94f0d4b389536e5bf450.jpg', '<p>Saoirse là một đứa trẻ là người cuối cùng của Selkies, phụ nữ ở các truyền thuyết Ailen và Scotland, những người biến đổi từ hải cẩu thành người. Cô trốn thoát khỏi ngôi nhà của bà ngoại để đi đến biển và những sinh vật cổ tích miễn phí bị mắc kẹt trong thế giới hiện đại.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324456);
