INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-dinh-ky-2014', 'Lộc Đỉnh Ký', 'The Deer And The Cauldron', 'https://phimimg.com/upload/vod/20240118-1/147f042d3982ad755dc028c80095058f.jpg', 'https://phimimg.com/upload/vod/20240118-1/f37c2ae6dae9f633e1bb5b0ea381f423.jpg', '<p>Lộc Đỉnh Ký - The Deer and The Cauldron xoay quanh chàng trai Vi Tiểu Bảo năng động và tài giỏi cùng sống với 7 người vợ xinh đẹp của mình. Các tập của bộ phim Tân Lộc Đỉnh Ký là từng câu chuyện cuộc đời của các nhân vật trong phim, cùng những tình tiết hài hước và tình cảm của Tiểu Bảo mà anh dành cho các cô vợ xinh đẹp của mình, 7 người vợ, 7 tính cách khác nhau, bộ phim sẽ mang lại cho các bạn những giây phút thư giản và thoải mái nhất.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 12, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mễ Tuyết","avatar":""},{"name":"Ngô Thiến","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Ngụy Thiên Tường","avatar":""},{"name":"Trương Mông","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324456);
