INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-phong-thinh-no', 'Cuồng Phong Thịnh Nộ', 'Into The Storm', 'https://phimimg.com/upload/vod/20231227-1/e82f412abf33771f68d42a4dda177f88.jpg', 'https://phimimg.com/upload/vod/20231227-1/e37cca79cc0dbbbdea15d31e42f61304.jpg', '<p>Cuồng Phong Thịnh Nộ - Into The Storm là bộ phim hành động hình sự Mỹ 2014 của đạo diễn Steven Quale. Dựa theo cốt truyện của phim tài l iệu kể về một thảm họa đã gieo cho những người dân nơi đây rất nhiều điều khủng khiếpTrong vòng một ngày, thị trấn Silverton là bị tàn phá bởi một sự tấn công chưa từng có lốc xoáy. Hầu hết mọi người tìm nơi trú ẩn, trong khi những người khác chạy theo hướng xoáy. Into the Storm sẽ đưa bạn trực tiếp vào trung tâm của cơn bão để trải nghiệm thiên nhiên.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Armitage","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Jeremy Sumpter","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
