INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-tu-la-loi-noi-doi-cua-em', 'Tháng Tư Là Lời Nói Dối Của Em', 'Your Lie In April', 'https://phimimg.com/upload/vod/20240111-1/d8e54e0b2323e71813a307c5891fe899.jpg', 'https://phimimg.com/upload/vod/20240111-1/32b2650389e568365f41a4198d80eb37.jpg', '<p>Cuộc sống hàng ngày của cậu bé thiên tài Kimio Arima, người cái chết của mẹ mà cậu thông thể chơi Piano được nữa, bắt đầu trở nên đầy màu sắc khi cậu gặp một nghệ sĩ vĩ cầm. Kosei, người bị mê hoặc bởi Kaori Miyazono, một kẻ kiêu ngạo, thượng đằng, nhưng đầy cá tính, bắt đầu chạy ở tuổi 14 bằng chính đôi chân của mình.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 17, 2014, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Hayami","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Risa Taneda","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Yuki Kaji","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324456);
