INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-lon-phan-8', 'Vụ Nổ Lớn (Phần 8)', 'The Big Bang Theory (Season 8)', 'https://phimimg.com/upload/vod/20231219-1/1d6946e31b655e05b59d26c60b820725.jpg', 'https://phimimg.com/upload/vod/20231219-1/f4d895fabd71037d99a9cface41cf677.jpg', '<p>Khi nhóm đối mặt với những thăng trầm trong cuộc sống cá nhân và công việc, Penny thử sức với con đường sự nghiệp mới giữa những trắc trở trong mối quan hệ với Leonard.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Galecki","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Kaley Cuoco","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Mayim Bialik","avatar":""},{"name":"Melissa Rauch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
