INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-nguy-hiem', 'Khu Nguy Hiểm', 'Brick Mansions', 'https://phimimg.com/upload/vod/20231211-1/bba4ff04187b2e2af9b2a414f67e75b2.jpg', 'https://phimimg.com/upload/vod/20231211-1/8e09d053ff88c51dd0722fd2d8b2a2a7.jpg', '<p>Khu Nguy Hiểm - Brick Mansions là một bộ phim hành động Pháp-Cananda với sự tham gia của tài tử Paul Walker. Bối cảnh của phim là năm 2018 trong một khi biệt thự bỏ hoang ở vùng đầm lầy Detroit, nơi những tên tội phạm nguy hiểm nhất đang ẩn náu. Không thể kiểm soát được bọn tội phạm này, cảnh sát đã xây dựng một bức khổng lồ xung quanh khu vực này để bảo vệ phần còn lại của thành phố. Cảnh sát chìm Damien Collier (Paul Walker) quyết tâm tìm ra kẻ giết cha mình và đòi lại công lý trong cuộc chiến chống tham nhũng. Về phần cựu tù nhân Lino (David Belle), mỗi ngày là một cuộc đấu tranh để tìm lại một con người trung thực trong chính mình. Cả 2 dường như bế tắc cho đến khi trùm mà túy Tremaine (RZA) bắt cóc bạn gái của Lino, Damien mới miễn cưỡng chấp nhận giúp đỡ Lino và họ cùng nhau đấu tranh để ngăn chặn một âm mưu vô cùng nham hiểm - phá hủy toàn thành phố bằng một quả bom.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Paul Walker","avatar":""},{"name":"David Belle","avatar":""},{"name":"RZA","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
