INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jinn', 'Jinn', 'Jinn', 'https://phimimg.com/upload/vod/20231211-1/85b74f7bf960f80404405f91610e8c30.jpg', 'https://phimimg.com/upload/vod/20231211-1/bf774b88d46dc68c1c5ace5bedb3d165.jpg', '<p>Ngay từ đầu, những câu chuyện về thiên thần và con người đã thu hút trí tưởng tượng của chúng ta và khắc sâu vào lịch sử của chúng ta vượt qua mọi ranh giới về văn hóa, tôn giáo và thời gian. Hai chủng tộc này đã thống trị bối cảnh của thần thoại hiện đại trong vô số thế kỷ, gần như xóa sạch bằng chứng cho thấy chủng tộc thứ ba từng tồn tại. Giống dân thứ ba này, sinh ra từ lửa không khói, được gọi là jinn. Tương tự như con người theo nhiều cách, jinn sống vô hình giữa chúng ta và chỉ trong những hoàn cảnh thảm khốc hoặc bất thường, con đường của chúng ta mới có ý định đi qua.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Rains","avatar":""},{"name":"Ray Park","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Faran Tahir","avatar":""},{"name":"Serinda Swan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
