INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-mr-peabody-cau-be-sherman', 'Cuộc Phiêu Lưu Của Mr. Peabody & Cậu Bé Sherman', 'Mr. Peabody & Sherman', 'https://phimimg.com/upload/vod/20231211-1/e394099658b5c219552aa8d11ceed2c7.jpg', 'https://phimimg.com/upload/vod/20231211-1/95b30be13af868667d2a3777214483ef.jpg', '<p>Ông Peabody là một doanh nghiệp Titan, nhà phát minh, nhà khoa học, người sành ăn, huy chương Olympic hai lần và thiên tài ... người cũng là một con chó. Sử dụng phát minh khéo léo nhất của mình, máy WABAC, ông Peabody và cậu bé nuôi của ông Sherman đã trở lại kịp thời để trải nghiệm các sự kiện thay đổi thế giới và tương tác với một số nhân vật tuyệt vời nhất mọi thời đại. Nhưng khi Sherman phá vỡ các quy tắc du hành thời gian, hai anh hùng của chúng ta thấy mình trong một cuộc đua để sửa chữa lịch sử và cứu lấy tương lai, trong khi ông Peabody có thể phải đối mặt với thách thức lớn nhất của mình - là cha mẹ</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
