INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-vet-rio-2', 'Chú Vẹt Rio 2', 'Rio 2', 'https://phimimg.com/upload/vod/20240108-1/b5a2274566baae4752b4a71f9ef3163f.jpg', 'https://phimimg.com/upload/vod/20240108-1/94a5be262936dd7a4e5eb0936084b1bc.jpg', '<p>Đó là một khu rừng ở ngoài kia cho BLU, Jewel và ba đứa con của họ sau khi họ bị tổn thương Rio de Janeiro đến vùng hoang dã của Amazon. Khi BLU cố gắng phù hợp với nhau, anh ta bị mỏ to-beak với Nigel báo thù và đáp ứng những kẻ thù đáng sợ nhất trong tất cả: cha vợ mình.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
