INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-nhu-la-co-cua-co-ay-gay-di', 'Nếu Như Lá Cờ Của Cô Ấy Gãy Đi', 'Flag Story, If Her Flag Breaks', 'https://phimimg.com/upload/vod/20231219-1/d43cbba3fc9cec79b97c3ac88b930ab0.jpg', 'https://phimimg.com/upload/vod/20231219-1/bc2d4866ba00ac2127d2f004213e0c35.jpg', '<p>Sau một tai nạn nọ, Hatate Souta, người có thể thấy được các lá cờ đã giữ khoảng cách với người khác vì năng lực này. Tuy nhiên, điều đó không ngăn cản được những cô gái xinh đẹp tiếp cận cậu. Khi nhận ra thì xung quanh Souta đã toàn là những người mà cậu trân trọng. Liệu lá cờ mà cậu thấy đó mang ý nghĩa gì và số phận gì đang chờ đợi họ ở KTX Hỏi Chấm? Bí mật của thế giới mà Sacrament, người trao cho cậu năng lực này nhắc đến thực ra là sao?</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 17, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324456);
