INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vi-sep-kho-tinh-2', 'Những Vị Sếp Khó Tính 2', 'Horrible Bosses 2', 'https://phimimg.com/upload/vod/20231212-1/42e8fe7de26ebd2b5d1717cf6a7783cd.jpg', 'https://phimimg.com/upload/vod/20231212-1/81484e3201c7f933aac86cb2c77ddc7c.jpg', '<p>Ở phần này, Nick Hendricks (Jason Bateman) - nhân viên quản lý tài chính mẫn cán luôn phấn đấu để được thăng chức, Kurt Buckman (Jason Sudeikis) - quản lý tài chính tại công ty dược, Dale Arbus (Charlie Day) - trợ lý của nha sĩ xinh đẹp và luôn bị cô quấy rối tình dục là 3 nam diễn viên hài chính. Bộ phim xoay quanh những tình huống hài hước, dở khóc dở cười của 3 chàng tội phạm ngố do họ đã sát hại chính ông chủ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Kevin Spacey","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
