INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-bach-phat-ma-nu', 'Tân Bạch Phát Ma Nữ', 'The White Haired Witch Of Lunar Kingdom', 'https://phimimg.com/upload/vod/20231212-1/62cf045d5335e4c66f3f00fa947f6816.jpg', 'https://phimimg.com/upload/vod/20231212-1/c2a8fabf572f4da22d8eaaff0226e92a.jpg', '<p>Tân Bạch Phát Ma Nữ - The White Haired With of Lunar Kingdom là bộ phim cổ trang tâm lý, tình cảm, hành động phiêu lưu Trung Quốc 2014 của đạo diễn Zhang Zhiliang. Bộ phim là một phiên bản mới dựa trên sự thành công của những phiên bản Bạch Phát Ma Nữ trước. Cùng với sự góp mặt của hai diễn viên có sức thu hút rất lớn của nền điện ảnh Hoa Ngữ: Huỳnh Hiểu Minh và Phạm Băng Băng. Bộ phim xoay quanh câu chuyện tình buồn giữa Luyện Nghê Thường (Phạm Băng Băng) và Trác Nhất Hàng (Huỳnh Hiểu Minh). Trên đường đến Bắc Kinh để tỏ lòng thành kính tới Hoàng đế, Nhất Hàng đã gặp và yêu một phụ nữ xinh đẹp tên Nghê Thường. Tuy nhiên, Nhất Hàng đã bị các sư phụ phản đối mối quan hệ này bởi Nghê Thường bị nghi ngờ chính là người đã ám sát ông nội Nhất Hàng. Nghê Thường phải nhận cú sốc khi biết tin Nhất Hàng đã bội ước và cưới vợ. Trước sự thật đó, mái tóc của Nghê Thường bạc trắng chỉ sau 1 đêm.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phạm Băng Băng","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Triệu Văn Trác","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0