INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-hoc-te-nhat-doi-toi', 'Năm Học Tệ Nhất Đời Tôi', 'Worst Year Of My Life Again', 'https://phimimg.com/upload/vod/20231219-1/ca8db5082e736fa80df7ea53a85741b4.jpg', 'https://phimimg.com/upload/vod/20231219-1/4a78bfc5cffa4eef99f6f8ed90d0e1a9.jpg', '<p>Năm Học Tệ Nhất Đời Tôi - Worst Year of My Life Again thuyết minh Sinh nhật lần thứ 14, với Alex King đây quả là một năm khủng khiếp: bị ghét bỏ bởi giáo viên của cậu, là mục tiêu của lũ bắt nạt trong trường và xấu hổ bởi vì những nỗ lực trong việc gây ấn tượng với cô gái nổi tiếng nhất trường. Vì vậy khi cậu thức dậy vào ngày sinh nhật 15 tuổi của mình, thì cậu phát hiện thời gian bị quay ngược lại đúng 1 năm trước đó, cậu không thể tin được rằng cậu sẽ phải sống lại 12 tháng đau khổ ấy 1 lần nữa. Cho tới khi Simon Birch và Maddy Kent, những người bạn thân của cậu thuyết phục rằng với cơ hội này, cậu có thể thay đổi mọi thứ...</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 12, 2014, 'Thuyết Minh', 'HD', 'Úc', 0, '[{"name":"Ned Napier","avatar":""},{"name":"Tiarnie Coupland","avatar":""},{"name":"Laurence Boxhall","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
