INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('main-tera-hero', 'Main Tera Hero', 'Main Tera Hero', 'https://phimimg.com/upload/vod/20240102-1/4607993aab76bef30bdaa1e5516717b8.jpg', 'https://phimimg.com/upload/vod/20240102-1/a4170fa7e9a3c25a7259ea84dfb77914.jpg', '<p>Seenu yêu Sunaina nhưng họ bị truy đuổi bởi một cảnh sát rình rập, một người đẹp mê đắm và ông bố trùm mafia của cô ấy - liệu hành động anh hùng của Seenu có thể thành công?</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Varun Dhawan","avatar":""},{"name":"Ileana D''Cruz","avatar":""},{"name":"Nargis Fakhri","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Rajpal Yadav","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
