INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-thoi-loan', 'Chiến Binh Thời Loạn', 'Born Of War', 'https://phimimg.com/upload/vod/20240102-1/9ea3d8342db70f16191ce2ba15b480e3.jpg', 'https://phimimg.com/upload/vod/20240102-1/06d35a99cf51560fa2397da78b24e084.jpg', '<p>Mina, một sinh viên đại học trẻ tuổi, cuộc sống của cô bị xé toạc sau khi gia đình cô bị giết. Khi cô phát hiện ra vụ giết người của họ là một phần của vụ bắt cóc bất thành để trả cô về với người cha thực sự của mình - một kẻ khủng bố ở Trung Đông.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Frain","avatar":""},{"name":"Sofia Black-D''Elia","avatar":""},{"name":"Lydia Leonard","avatar":""},{"name":"Michael Maloney","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324456);
