INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-bao-thu', 'Sát Thủ Báo Thù', 'Vengeance Of An Assassin', 'https://phimimg.com/upload/vod/20231211-1/9ce325b55974e33919295e1b2a95e451.jpg', 'https://phimimg.com/upload/vod/20231211-1/7fa872bb24009cedecd02129dd222310.jpg', '<p>Sát Thủ Báo Thù - Vengeance Of An Assassin: Mỗi kẻ giết người đều có một câu chuyện của riêng mình, nhưng tất cả đều liên quan đến máu và mất mát. Phim xoay quanh cuộc đời của một sát thủ, chuyên giết người tên là Natee. Do có một quá khứ bất hạnh, đen tối đã đẩy anh vào con đường tội ác, sự mất mát quá lớn của người thân cha mẹ đã biến anh thành 1 sát thủ giết người vô số. Thay vì làm sát thủ là vì tiền thì Natee lại có mục đích khác là tìm ra chân tướng cái chết của gia đình mình..</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dan Chupong","avatar":""},{"name":"Nantawooti Boonrapsap","avatar":""},{"name":"Kessarin Ektawatkul","avatar":""},{"name":"Chatchapol Kulsiriwuthichai","avatar":""},{"name":"Kowit Wattanakul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
