INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-nhan-cuong-loan-shrews-nest', 'Nữ Sát Nhân Cuồng Loạn Shrew''s Nest', 'Shrew''s Nest', 'https://phimimg.com/upload/vod/20231210-1/12a5a634295ea159aa39b53ccca16b97.jpg', 'https://phimimg.com/upload/vod/20231210-1/dbe6f72077d8693969ff56cbacaa0e80.jpg', '<p>Tây Ban Nha, những năm 1950. Chứng sợ khoảng trống của Montse khiến cô bị nhốt trong một căn hộ nham hiểm ở Madrid và mối liên hệ duy nhất của cô với thực tại là đứa em gái mà cô đã đánh mất tuổi thơ để nuôi nấng. Nhưng một ngày nọ, một người hàng xóm trẻ tuổi liều lĩnh, Carlos, ngã xuống cầu thang và lết đến cửa nhà họ. Ai đó đã vào tổ chuột chù... có lẽ anh ta sẽ không bao giờ rời đi.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Macarena Gómez","avatar":""},{"name":"Nadia de Santiago","avatar":""},{"name":"Hugo Silva","avatar":""},{"name":"Luis Tosar","avatar":""},{"name":"Gracia Olayo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
