INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-khong-ten', 'Người Không Tên', 'Genome Hazard', 'null', 'https://phimimg.com/upload/vod/20231211-1/347329cbe6ece39b6de46e36cb2939d7.jpg', '<p>Bộ phim Người Không Tên - Genome Hazard là câu chuyện kỳ bí về Taketo Ishigami, nhà hóa học thiên tài đã phát hiện ra thi thể của vợ mình trong căn hộ của anh vào ngày kỷ niệm đầu tiên của họ.Anh càng trở nên bối rối khi người vợ - đáng lý đã là thi thể trước mắt anh- gọi điện và nói rằng công việc của cô vẫn ổn.Bất lực trước những gì đang xảy ra, anh còn vô tình phát hiện mình đang bị ai đó truy sát và trực giác của Ishigami mách bảo anh phải chạy trốn. Và cuối cùng một âm mưu thâm hiểm xung quanh Ishigami dần dần được hé lộ...</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Nishijima Hidetoshi","avatar":""},{"name":"Kim Hyo-jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
