INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bears', 'Bears', 'Bears', 'https://phimimg.com/upload/vod/20231211-1/4065831acb93a29d20c24d977b07325b.jpg', 'https://phimimg.com/upload/vod/20231211-1/c917723e4b3662c04e88ff2b92209ac0.jpg', '<p>Các nhà làm phim Alastair Fothergill và Keith Scholey ghi lại một năm trong cuộc đời của một con gấu nâu Alaska tên là Sky và đàn con của nó, Scout và Amber. Câu chuyện của họ bắt đầu khi những con gấu xuất hiện sau giấc ngủ đông vào cuối mùa đông. Thời gian trôi qua, gia đình gấu phải làm việc cùng nhau để tìm thức ăn và giữ an toàn trước những kẻ săn mồi khác, đặc biệt là những con gấu khác. Mặc dù thế giới của chúng rất thú vị nhưng cũng đầy rủi ro và sự sống còn của đàn con phụ thuộc vào sự đoàn kết của gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John C. Reilly","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324456);
