INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-khao-hanh-phuc-3', 'Khát Khao Hạnh Phúc 3', 'I Need Romance 3', 'https://phimimg.com/upload/vod/20231208-1/f7d1b73c831c6847d879be0b9328052a.jpg', 'https://phimimg.com/upload/vod/20231208-1/7fddb267f4175be1ced42fa94f55d6b4.jpg', '<p>Shin Joo Yeon hiền lành và tốt bụng, làm việc cho một kênh mua sắm tại nhà, nhưng sau 9 năm trải qua nhiều chuyện đau lòng, cô đã trở thành người phụ nữ lạnh lùng. Thế nhưng sự xuất hiện của Joo Wan, chàng trai ở lứa tuổi 20, người luôn mơ về một tình yêu trong sáng, thuần khiết đã làm tan chảy con tim băng giá của cô.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 19, 2014, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim So Yeon","avatar":""},{"name":"Sung Joon","avatar":""},{"name":"Nam Goong Min","avatar":""},{"name":"Wang Ji Won","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
