INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tham-tu-veronica-mars', 'Nữ Thám Tử Veronica Mars', 'Veronica Mars', 'https://phimimg.com/upload/vod/20231210-1/4faa361ce2acb181596d7cae88ec7900.jpg', 'https://phimimg.com/upload/vod/20231210-1/4b7d4c5078383161ac09fc38b91a7208.jpg', '<p>Sau nhiều năm bỏ quên quá khứ và trở thành một nữ luật sư tài ba, Veronica Mars bị kéo trở lại thị trấn ngày xưa - vừa kịp lúc cho buổi họp lớp trung học - để giải cứu Logan, người bạn trai cũ đang dính vào một vụ án mạng đầy bí ẩn. Thế nhưng, quá trình điều tra đã khiến cô cảm thấy nghi ngờ về cách hành xử của Logan.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Bell","avatar":""},{"name":"Jason Dohring","avatar":""},{"name":"Enrico Colantoni","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
