INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy', 'Vùng Đất Quỷ', 'Forbidden Kingdom', 'https://phimimg.com/upload/vod/20231210-1/35867a8bccf1452b67ccfcb52dac1f02.jpg', 'https://phimimg.com/upload/vod/20231210-1/6b4e8237447e3e7a3469d5181f54230d.jpg', '<p>Đầu thế kỷ 18. Người vẽ bản đồ Jonathan Green thực hiện chuyến hành trình khoa học từ Châu Âu sang Phương Đông. Sau khi đi qua Transylvania và vượt qua Dãy núi Carpathian, anh thấy mình đang ở một ngôi làng nhỏ lạc trong rừng cây không thể vượt qua. Không có gì ngoài cơ hội và sương mù dày đặc có thể đưa anh đến nơi bị nguyền rủa này. Những người sống ở đây không giống bất kỳ người nào khác mà du khách đã thấy trước đó. Dân làng, sau khi đào một con hào sâu để tự bảo vệ mình khỏi phần còn lại của thế giới, có chung niềm tin ngây thơ rằng họ có thể tự cứu mình khỏi cái ác, không hiểu rằng cái ác đã làm tổ trong tâm hồn họ và đang chờ cơ hội để tràn ra thế giới.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Jason Flemyng","avatar":""},{"name":"Andrey Smolyakov","avatar":""},{"name":"Aleksey Chadov","avatar":""},{"name":"Agniya Ditkovskite","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
