INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-pho-bat-tri', 'Khu Phố Bất Trị', 'Brick Mansions', 'https://phimimg.com/upload/vod/20231209-1/d2be9b10dff023cc02ef64bf3bd32d30.jpg', 'https://phimimg.com/upload/vod/20231209-1/19528484439aea6ffca8f7a8609f5703.jpg', '<p>Khu Phố Bất Trị - Brick Mansions lấy bối cảnh thành phố Detroit khi đã bị cô lập bởi một bức tường ngăn cách và trở thành nơi trú ngụ của những tên tội phạm ma túy và cướp bóc nguy hiểm nhất. Một ngày, cảnh sát Damien (Paul Walker) quyết định trở thành cớm chìm đột nhập vào băng nhóm của tên trùm tội phạm Tremaine để trả thù cho cha bị giết và cứu bạn gái.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Yu Xia","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Philip Ng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
