INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-2014', 'Thần Bài 2014', 'The Man From Macau - From Vegas To Macau', 'https://phimimg.com/upload/vod/20231209-1/92bdef1b08cb02d071c8c563479fa31a.jpg', 'https://phimimg.com/upload/vod/20231209-1/81507ce1f12571ecc569949c554ce30c.jpg', '<p>Benz, cùng với con trai Cool và cháu trai Ngau-Ngau là một nhóm những người hùng giấu mặt chuyên cướp của xã hội đen vào ban đêm và chia cho người nghèo. Tuy nhiên, vợ Benz đang bị ung thư và không hề biết gì về hoạt động của họ. Con trai riêng của Benz - Lionel - một cảnh sát đang nằm vùng trong một công ty đa quốc gia được gọi là DOA, ngoài ánh sáng là một công ty cung cấp tội phạm lớn được điều hành bởi ông trùm Ko tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yun-Fat Chow","avatar":""},{"name":"Tạ Đình Phong","avatar":""},{"name":"Đỗ Vấn Trạch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
