INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-chung-2014', 'Tuyệt Chủng', 'Extinction', 'https://phimimg.com/upload/vod/20231209-1/47b8f0f3cce62ddca9c4d98e4398debd.jpg', 'https://phimimg.com/upload/vod/20231209-1/eb2a109527541215d758a1253f4001f1.jpg', '<p>Ở sâu trong rừng Amazon, một nhóm nghiên cứu bắt tay vào cuộc thám hiểm để bảo vệ các loài nằm trong sách đỏ. Sau nhiều sự kiện lạ lùng, các hướng dẫn mê tín của họ bỏ rơi họ và họ nhận ra họ đang ở trong tầm ngắm của một kẻ săn chưa biết tên.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Mac","avatar":""},{"name":"Ben Lloyd-Holmes","avatar":""},{"name":"Neil Newbon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324456);
