INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('he-lo-baby', 'Hé Lô Baby', 'Hello Babies', 'https://phimimg.com/upload/vod/20231208-1/804e82513c677aabbb6beebb00d70f72.jpg', 'https://phimimg.com/upload/vod/20231208-1/72d02f681d2e49ec7deb101625669ac3.jpg', '<p>Hé Lô Baby - Hello Babies là bộ phim kể về những người cao tuổi Trung Quốc muốn thế hệ trẻ có con càng sớm càng tốt. Phim cũng nói về một vấn đề khác là sự khao khát của nhiều bậc cha mẹ Đại Lục muốn sinh con tại Hồng Kông để giành quyền định cư tại đó cũng như có thể dễ dàng sinh nhiều con.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Sandra Ng","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Ronald Cheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
