INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-phut-sinh-tu', 'Giờ Phút Sinh Tử', 'The Angriest Man In Brooklyn', 'https://phimimg.com/upload/vod/20231209-1/0de9f9c6c50c56184700dc65b5c667ff.jpg', 'https://phimimg.com/upload/vod/20231209-1/b437fd7b2b1197cab1d54ef0a86a9df5.jpg', '<p>Sau khi biết rằng chứng phình động mạch não sẽ giết chết mình trong khoảng 90 phút nữa, một người đàn ông luôn bất hạnh đấu tranh để chấp nhận số phận của mình và chuộc lỗi với những người mà anh ta từng làm tổn thương.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"James Earl Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
