INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-cu-ma', 'Chung Cư Ma', 'Chung Cu Ma', 'https://phimimg.com/upload/vod/20231210-1/17c0fcd1a2c7e2ef93dc55611e7ecf90.jpg', 'https://phimimg.com/upload/vod/20231210-1/a800bd182dd43dc3df145911b6025543.jpg', '<p>Khai thác một cốt truyện kinh điển về hồn ma oan khuất ẩn trong khu chung cư cũ kỹ, bộ phim dẫn dắt người xem vào một không gian chật hẹp, nhưng chứa đựng biết bao câu chuyện buồn vui giữa lòng Sài Gòn hiện đại. Lan (Phương Mai), một phụ nữ 30 tuổi vừa ly dị chồng và đồng thời cũng là một nhà văn viết tiểu thuyết trinh thám, vừa cùng cậu con trai 5 tuổi tên Bi dọn đến khu chung cư thì đã gặp biết bao nhiêu chuyện rắc rối. Từ những người hàng xóm bí ẩn, đến những sự việc không có lời giải đáp, cùng nỗi ám ảnh về chuyện chồng ngoại tình bủa vây lấy cuộc sống của Lan. Rồi những cái chết bất ngờ, và bao cơn ác mộng đẫm máu cứ liên tiếp giáng xuống. Tất cả dường như đều gắn với chiếc hộp nhạc của cậu con trai 5 tuổi. Lẩn khuất đâu đấy hình ảnh một phụ nữ mặc chiếc váy đỏ thắm, ôm trong lòng đứa con còn đỏ hỏn. Họ sẽ thoát thân hay bị cuốn vào vòng xoáy của chuyện hận thù và báo oán?</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Hoàng Phúc","avatar":""},{"name":"Chi Pu","avatar":""},{"name":"Phương Mai","avatar":""},{"name":"Quang Sự","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
