INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-vo-danh-phan-8', 'Bác Sĩ Vô Danh (Phần 8)', 'Doctor Who (Season 8)', 'https://phimimg.com/upload/vod/20231207-1/efb30816f2778c114d84a1eaae8f98fd.jpg', 'https://phimimg.com/upload/vod/20231207-1/2f7d96aeeebd9139082dfbc34cc0be21.jpg', '<p>Bộ phim kể về cuộc phiêu lưu của Bác sĩ (nguyên văn là Doctor, có thể dịch là Tiến sĩ), một chúa tể thời gian. Bác sĩ đã đi xuyên không gian và thời gian để bảo vệ và giúp đỡ mọi sinh vật trên vũ trụ với một cỗ máy thời gian tên là TARDIS có bề ngoài không khác gì một chiếc hộp điện thoại cảnh sát những năm 1950 ở Anh quốc. Trong các chuyến phiêu lưu của mình, các Bác sĩ thường có những người bạn đồng hành rất vui tính và dễ mến...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matt Smith","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Jenna Coleman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
