INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-gian-don', 'Trái Tim Giản Đơn', 'The Normal Heart', 'https://phimimg.com/upload/vod/20231208-1/3b304ef07948f5df7c04b2160290e8a7.jpg', 'https://phimimg.com/upload/vod/20231208-1/339c1347499dabc9887e866c2aae09d8.jpg', '<p>Câu chuyện về sự khởi đầu của cuộc khủng hoảng HIV-AIDS ở thành phố New York vào đầu những năm 1980, có cái nhìn thẳng thắn về chính trị tình dục của quốc gia khi các nhà hoạt động đồng tính và các đồng minh của họ trong cộng đồng y tế đấu tranh để phơi bày sự thật về dịch bệnh đang bùng phát cho một thành phố và quốc gia phủ nhận.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Ruffalo","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Jonathan Groff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
