INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nguyen-tan-bao', 'Kỷ Nguyên Tàn Bạo', 'Kundo: Age Of The Rampant', 'https://phimimg.com/upload/vod/20231208-1/736f7f43e24fd00b21ee62d44a832aac.jpg', 'https://phimimg.com/upload/vod/20231208-1/2eeecf11fa9a36443c3e34b521eecbea.jpg', '<p>Kundo: Age of the Rampant (Kỷ nguyên tàn bạo) lấy bối cảnh Hàn quốc những năm 1895, giai đoạn khủng hoảng của xã hội Hàn Quốc. Những thảm họa thiên nhiên khiến mùa màng thất bát, dân chúng chìm trong đói rét và chết chóc.Mặc dù vậy, giới cầm quyền và quý tộc không đoái hoài gì đến chính sự cũng như cảnh lầm tham của bách tính. Chính trong thời điểm tăm tối này, Kundo đã xuất hiện và mở ra những hy vọng cho những người nghèo đói và cũng là sự đe dọa đối với tầng lớp trên trong xã hội.</p>', 'Full', 1, 'single', 'completed', 5, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gang Dong‑Won","avatar":""},{"name":"Ha Jung Woo","avatar":""},{"name":"Cho Jin Woong","avatar":""},{"name":"Ma Dong Seok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324456);
