INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-roborumble', 'Gấu Boonie: Robo-Rumble', 'Boonie Bears: Robo-Rumble', 'https://phimimg.com/upload/vod/20231208-1/0018d7a394f7cc8b7fefc5804ca1bc03.jpg', 'https://phimimg.com/upload/vod/20231208-1/633878d95f195c82cf7c777c384a06a6.jpg', '<p>Gấu Boonie: Robo-Rumble - Boonie Bears: Robo-Rumble lấy bối cảnh lễ hội mùa xuân đến gần, Logger Vick muốn đi làm thêm để có tiền đón Năm mới. Nhưng đúng lúc đó Vick bị mất việc nên anh chàng phải đi tìm công việc khác. Sau nhiều nỗ lực, cuối cùng anh cũng nhận được công việc làm kiểm lâm cho khu rừng. Ban đầu Vick bị các chú gấu hiểu nhầm là anh trà trộn vào làm kiểm lâm để thực hiện âm mưu phá rừng, tuy nhiên khi kẻ thù thực sự của khu rừng đến, tất cả bọn họ lại có cơ hội hiểu nhau hơn và cùng nhau hợp tác chống lại kẻ thù để bảo vệ ngôi nhà chung thân yêu.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
