INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('visa-for-vietnam', 'Visa For VietNam', 'Visa For VietNam', 'https://phimimg.com/upload/vod/20231208-1/88f06cf649b831ab44f4e36282c009d0.jpg', 'https://phimimg.com/upload/vod/20231208-1/b1a82bac4940494d425a217c520a65e4.jpg', '<p>Visa for VietNam là một bộ phim tài liệu của Tập đoàn Công nghiệp - Viễn thông Quân đội (Viettel). Bộ phim phần nào đưa ra một góc nhìn “tấm thị thực” mà người Việt Nam, các doanh nghiệp Việt Nam có thể tự tin và tự hào khi đi ra thế giới. Visa for VietNam được hình thành xuất phát từ câu hỏi: Điều gì khiến cho một vị nguyên thủ của đất nước Tanzania ở Đông Phi xa xôi lại mong chờ sự xuất hiện của dự án đầu tư viễn thông với Việt Nam đến vậy? Khát vọng của bạn là gì? Tựa như một con chim được sải cánh giữa bầu trời hay là mở cả bầu trời cho những con chim bay lượn. Người Viettel (Tập đoàn Công nghiệp - Viễn thông Quân đội) đã chọn cách giúp cho nhiều thế hệ con người khác nhau hiểu rằng ngoài bầu trời ấy lại còn những bầu trời khác rộng lớn hơn.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324456);
