INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-tuong-sieu-nhien-vet-can-cua-quy', 'Hiện Tượng Siêu Nhiên: Vết Cắn Của Quỷ', 'Paranormal Activity: The Marked Ones', 'https://phimimg.com/upload/vod/20231208-1/cfcd781823868e3049c8a53b228483ae.jpg', 'https://phimimg.com/upload/vod/20231208-1/9b3a819ff1c94abedc1dee5465efd04a.jpg', '<p>Jesse, 17 tuổi, đã nghe thấy những âm thanh đáng sợ phát ra từ căn hộ của người hàng xóm, nhưng khi anh bật máy ảnh lên và bắt đầu tìm ra nguồn gốc của chúng, anh gặp phải một ác quỷ cổ xưa sẽ không ngừng nghỉ cho đến khi nó cướp đi linh hồn của anh.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Cabral","avatar":""},{"name":"Gabrielle Walsh","avatar":""},{"name":"Katie Featherston","avatar":""},{"name":"Renée Victor","avatar":""},{"name":"Micah Sloat","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
