INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-arise-border-4-ma-don-doc', 'Vỏ Bọc Ma ARISE border: 4 Ma Đơn Độc', 'Ghost in the Shell Arise - Border 4: Ghost Stands Alone', 'https://phimimg.com/upload/vod/20231206-1/1b7d8668255b6a44f2f94487b6cca4fa.jpg', 'https://phimimg.com/upload/vod/20231206-1/ef2bb28f7791967e41ff48b3829405fe.jpg', '<p>Câu chuyện của phần sắp tới diễn ra giữa những dấu hiệu tái thiết sau chiến tranh vào mùa đông năm 2028. Căng thẳng đang gia tăng ở Thành phố Cảng Mới khi các cuộc biểu tình được tổ chức liên quan đến lợi ích của các tập đoàn nước ngoài. Điều này dẫn đến một vụ nổ súng liên quan đến cảnh sát chống bạo động. Tất cả bắt đầu với sự lây nhiễm cyberbrain do tên khủng bố Fire Starter tung ra. Một đơn vị tấn công độc lập do Makoto Kusanagi chỉ huy giao việc trấn áp tình hình cho những hồn ma của họ và hướng tới công lý của chính họ. Bên dưới bề nổi của sự việc là cô bé thiếc Emma và gã bù nhìn Burinda Junior. Khi Kusanagi giải quyết vụ việc, cô ấy tiến gần đến thứ mà hai hồn ma đó đang tìm kiếm.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Maaya Sakamoto","avatar":""},{"name":"Ikkyu Juku","avatar":""},{"name":"Kenichirou Matsuda","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Kazuya Nakai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324456);
