INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-tuyet-voi', 'Kỳ Nghỉ Tuyệt Vời', 'What We Did on Our Holiday', 'https://phimimg.com/upload/vod/20231206-1/2a835ae75bf44cb9f2b1bfdf001f8c7b.jpg', 'https://phimimg.com/upload/vod/20231206-1/8d551a363c7151fe823b5bd880363a12.jpg', '<p>Doug và Abi cùng ba đứa con của họ đi du lịch đến Cao nguyên Scotland để dự tiệc sinh nhật của Gordie, cha của Doug. Rõ ràng là khi phải giữ bí mật với những người còn lại trong gia đình, con cái họ là trách nhiệm lớn nhất của họ...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Tennant","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Ben Miller","avatar":""},{"name":"Amelia Bullmore","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
