INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-arise-border-3-nuoc-mat-ma', 'Vỏ Bọc Ma ARISE border: 3 Nước Mắt Ma', 'Ghost in the Shell Arise - Border 3: Ghost Tears', 'https://phimimg.com/upload/vod/20231206-1/14dbd9836a5106b1fb4c9c9f7ea47703.jpg', 'https://phimimg.com/upload/vod/20231206-1/633d4ef7836cd545b84ccff9edf346b1.jpg', '<p>Đóng vai những người yêu nhau trong kỳ nghỉ, Motoko và Batou làm việc để cố gắng ngăn chặn một tổ chức khủng bố có biểu tượng là Scrasath. Trong khi đó, Togusa điều tra vụ sát hại một người đàn ông sở hữu chiếc chân giả do Công ty Chân của Nàng tiên cá sản xuất.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Maaya Sakamoto","avatar":""},{"name":"Ikkyu Juku","avatar":""},{"name":"Kenichirou Matsuda","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Tomoyuki Dan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324456);
