INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barefoot', 'Barefoot', 'Barefoot', 'https://phimimg.com/upload/vod/20231206-1/2bdbffe977e2f8a3e49aa9b3ecba352e.jpg', 'https://phimimg.com/upload/vod/20231206-1/92989b96b7a86cb985a4def8b8fff07a.jpg', '<p>Con cừu đen của một gia đình giàu có gặp một bệnh nhân tâm thần trẻ, người đã được nuôi dưỡng trong toàn bộ cuộc sống của cô. Anh ta lấy người phụ nữ trẻ ngây thơ cho đám cưới của anh trai mình để thuyết phục gia đình rằng cuối cùng anh ta đã đứng thẳng ra khỏi cuộc sống của mình. Cô gây ấn tượng với gia đình với chính hãng, nếu sự quyến rũ không ổn định. Trên đường đi, họ rơi vào tình yêu khó chịu</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
