INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-luong', 'Hoàn Lương', 'A Good Man', 'https://phimimg.com/upload/vod/20231206-1/658a80bbd4d6c46c96c790f10f18bae6.jpg', 'https://phimimg.com/upload/vod/20231206-1/5fc9c7008cc82c2df792fa43ee39baa3.jpg', '<p>Sau khi sự nghiệp hoạt động đặc biệt lừng lẫy kết thúc trong thảm họa, Alexander rời bỏ mạng lưới và cố gắng sống một cuộc sống bình lặng với tư cách là một người siêng năng tại một khu chung cư. Nhưng khi một trong những người thuê nhà của anh ta và gia đình cô ta rơi vào tay một tên xã hội đen người Nga, Alexander bị kéo vào một cuộc chiến tổng lực giữa các băng đảng đối thủ Trung Quốc và Nga; buộc anh ta không chỉ phải bảo vệ gia đình mà còn phải đối mặt với kẻ thù cũ, và cho anh ta thêm một cơ hội để hòa giải quá khứ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Victor Webster","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Iulia Verdeș","avatar":""},{"name":"Massimo Dobrovic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324456);
