INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-rong-lua', 'Vũ Khí Rồng Lửa', 'P-51 Dragon Fighter', 'https://phimimg.com/upload/vod/20231120-1/1b1ef2e949c8121781dacf99efee3dad.jpg', 'https://phimimg.com/upload/vod/20231120-1/084a4b6e401bb08aa9071a788658c496.jpg', '<p>Khi Thế chiến thứ hai nổ ra, các đồng minh sắp đẩy phát xít ra khỏi Bắc Phi. Đó là khi Đức quốc xã tăng nhiệt, giải phóng Vũ khí bí mật của họ - những con rồng. Bây giờ quân Đồng minh phải tập hợp một nhóm phi công giỏi nhất từ các quốc gia để chiến đấu với quái thú huyền thoại.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Martin","avatar":""},{"name":"Stephanie Beran","avatar":""},{"name":"Madison Boyd","avatar":""},{"name":"Ross Brooks","avatar":""},{"name":"Pernille Trojgaard","avatar":""},{"name":"Osman Soykut","avatar":""},{"name":"Robert Pike Daniel","avatar":""},{"name":"Thom Rachford","avatar":""},{"name":"Clint Glenn Hummel","avatar":""},{"name":"Trey McCurley","avatar":""},{"name":"Seth Ginsberg","avatar":""},{"name":"Stephen Suitts","avatar":""},{"name":"Anthony Dupray","avatar":""},{"name":"Johnny Kostrey","avatar":""},{"name":"Michael Hampton","avatar":""},{"name":"Riley Litman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324456);
