INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('highway', 'HighWay', 'HighWay', 'https://phimimg.com/upload/vod/20231205-1/dcbd6101978e7237aca4247c210caa67.jpg', 'https://phimimg.com/upload/vod/20231205-1/1b89bce6be31b8b7dfa13b1dae6bac06.jpg', '<p>Ngay trước đám cưới của mình, một phụ nữ trẻ thấy mình bị bắt cóc và đòi tiền chuộc. Khi những ngày đầu tiên trôi qua, cô ấy bắt đầu phát triển một mối quan hệ kỳ lạ với kẻ bắt cóc mình.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Randeep Hooda","avatar":""},{"name":"Alia Bhatt","avatar":""},{"name":"Durgesh Kumar","avatar":""},{"name":"Pradeep Nagar","avatar":""},{"name":"Saharsh Kumar Shukla","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
