INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-anh-roi-xa', 'Nơi Anh Rời Xa', 'This Is Where I Leave You', 'https://phimimg.com/upload/vod/20231204-1/e7dc32df3db0944239d13d052c665eea.jpg', 'https://phimimg.com/upload/vod/20231204-1/b6ae8619e7cc356d8e452c758db37a05.jpg', '<p>Khi cha của họ qua đời, bốn anh chị em trưởng thành, mệt mỏi với thế giới trở về ngôi nhà thời thơ ấu của họ và được yêu cầu - với một lời nhắc nhở - ở lại đó cùng nhau trong một tuần, cùng với người mẹ nói năng tự do của họ và một nhóm vợ/chồng, người yêu cũ. và có thể-đã-được. Khi các anh chị em kiểm tra lại lịch sử đã chia sẻ của họ và tình trạng của từng mối quan hệ rách nát giữa những người biết và yêu thương họ nhất, họ kết nối lại theo những cách cực kỳ hài hước và đầy cảm xúc.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Tina Fey","avatar":""},{"name":"Jane Fonda","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Rose Byrne","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
