INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thung-lung-tam-toi', 'Thung Lũng Tăm Tối', 'The Dark Valley', 'https://phimimg.com/upload/vod/20231204-1/ef78bd2f05d3d4229d0001c7adee6918.jpg', 'https://phimimg.com/upload/vod/20231204-1/d227cfa14d8607151f484b8fe5fb6ccd.jpg', '<p>Dãy núi Alps, cuối thế kỷ 19. Greider, một kỵ sĩ đơn độc bí ẩn tự xưng là một nhiếp ảnh gia, đến một ngôi làng gỗ bị cô lập, bị cai trị bởi một gia tộc chuyên quyền, yêu cầu chỗ ở trong mùa đông.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Sam Riley","avatar":""},{"name":"Tobias Moretti","avatar":""},{"name":"Paula Beer","avatar":""},{"name":"Thomas Schubert","avatar":""},{"name":"Carmen Gratl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
