INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-thang-11', 'Sát Thủ Tháng 11', 'The November Man', 'https://phimimg.com/upload/vod/20231203-1/0e6865ebf33e836564a9d006bdf2ee22.jpg', 'https://phimimg.com/upload/vod/20231203-1/b6b876d837c790268805c848c21e1912.jpg', '<p>Trong phim Sát Thủ Tháng 11, Peter Devereaux (do nam diễn viên Pierce Brosnan thủ vai) là một cựu nhân viên CIA đặc biệt nguy hiểm và được đào tạo bài bản. Mặc dù đã giải nghệ, anh vẫn bị kéo vào một nhiệm vụ mang tính cá nhân để bảo vệ một nhân chứng có giá trị, đó là Alice Fournier (do Olga Kurylenko thủ vai) - người có thể phơi bày những sự thật đằng sau một âm mưu kéo dài hàng thập kỉ nay. Trong phim hay này, với nhiệm vụ này, anh sẽ phải đối mặt với bạn cũ đồng thời là người mình từng bảo trợ trong CIA - David Mason (do Luke Bracey đóng). Với những nghi ngờ ngày càng tăng về CIA, Peter không thể đặt niềm tin vào ai cũng như giữ được bất kỳ quy tắc hay thoả thuận nào. Xem phim Sát Thủ Tháng 11 bạn sẽ rất hài lòng với chất lượng dịch vụ phim online.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Olga Kurylenko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
