INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-quyet-dinh-lich-su', 'Những Quyết Định Lịch Sử', 'Những Quyết Định Lịch Sử', 'https://phimimg.com/upload/vod/20231203-1/f395d0e0ac86d5975fdd05bf8fc0b8f2.jpg', 'https://phimimg.com/upload/vod/20231203-1/3e644e465122cd1e25b71db750a3fc70.jpg', '<p>Những Quyết Định Lịch Sử là một bộ phim tài liệu của Tập đoàn Công nghiệp - Viễn thông Quân đội (Viettel). Có nhiều cách lý giải về mối liên hệ giữa những sự kiện quá khứ với thực tế hiện tại để diễn đạt câu chuyện của lịch sử. Ở một cách lý giải cụ thể, phim tài liệu Những Quyết Định Lịch Sử chọn cách tiếp cận vào lịch sử của những quyết định mang tính bước ngoặt. Bằng cách điểm lại những quyết định có ý nghĩa là những dấu mốc quan trọng nhất của lịch sử 25 năm của Tập đoàn Công nghiệp - Viễn thông Quân đội (Viettel), bộ phim xác định và tôn vinh những quyết định quan trọng nhất đã trực tiếp tạo dựng nên lịch sử Viettel. Qua đó, bộ phim chỉ ra lịch sử hình thành văn hóa ra quyết định theo tiêu chí “nghĩ khác, làm khác” của Viettel - một trong những nguyên nhân quan trọng nhất đã mang đến những thành công của Viettel.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Việt Nam', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324456);
