INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-pirates', 'The Pirates', 'The Pirates', 'https://phimimg.com/upload/vod/20231203-1/7d10d5bcdbc77026695f76fcfa62a001.jpg', 'https://phimimg.com/upload/vod/20231203-1/2fec3362eec052d2c99996c9ab4ddf72.jpg', '<p>Bộ phim điện ảnh bom tấn vừa được công bố và sẽ ra mắt khán giả Hàn Quốc và thế giới năm 2014 này. 15 ngày trước khi triều đại Joseon ra đời, Long Ấn quý giá được triều Minh ban tặng đã biến mất! Lời đồn rằng Long Ấn đang trôi dạt trên biển &amp; ai sở hữu nó, sẽ nắm trong tay cả thiên hạ. Hết thảy quan quân triều đình đến các tướng cướp tứ phương đều hội ngộ, sẵn sàng lật tung biển cả và “nghênh chiến” để giành vật báu. Trong số đó, có 2 “danh cướp” lừng lẫy: Nữ Hải Tặc Son Ye Jin, một mình diệt 5.000 cướp biển tại đảo Tsushima và Nam Sơn Tặc Kim Nam Gil, cái tên khiến trẻ con các bản làng khóc ré khi nghe đến tên. Cả 2 sẽ có một trận quyết đấu “một mất một còn” kịch liệt. Trận chiến còn khó khăn &amp; “éo le” hơn khi Long Ấn đã bị nuốt bởi một … con cá voi!</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Yoo Hae-jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
