INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-dac-vu-ke-thua', 'Lính Bắn Tỉa: Đặc Vụ Kế Thừa', 'Sniper: Legacy', 'https://phimimg.com/upload/vod/20231203-1/a635809b1dac3f1c6b08fdfbc7d8c3c8.jpg', 'https://phimimg.com/upload/vod/20231203-1/61d0da1bc72cc788966f7bdecb8007a0.jpg', '<p>Một chàng sát thủ cố gắng tìm một lời giải đáp cho cái chết của Cha anh. Anh cố gắng theo dõi những kẻ giết người, phát hiện ra rằng cha không chết. Vậy đâu mới là sự thật?</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Doug Allen","avatar":""},{"name":"Asen Asenov","avatar":""},{"name":"Tom Berenger","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
