INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-thoi-cong-nghe', 'Tình Yêu Thời Công Nghệ', 'Love on the Cloud', 'https://phimimg.com/upload/vod/20231205-1/e2c8eaefc0bee399d29a6223a313aa3c.jpg', 'https://phimimg.com/upload/vod/20231205-1/7ca07e9d2221c11058becbc92415ef2e.jpg', '<p>Giới thiệu: Ba kiếm khách văn học Sa Quả, Hoàng Tiểu Qua, Mã Ngai đồng cam cộng khổ trải qua cuộc sống trôi dạt ở phương Bắc, sự xuất hiện của nữ đại gia chị Mã đã mở ra buổi bình minh cho sự nghiệp của họ. Để lấy được vốn đầu tư từ chị Mã, \chàng trai 4.0\ Sa Quả đã bắt đầu quá trình sáng tác kịch bản gian khổ. Đồng thời, mầm tình yêu cũng bắt đầu xuất hiện trong thế giới của Sa Quả. Để viết được một kịch bản hay và giành được tình yêu, ba người họ đã dốc hết vốn liếng... Trong thời đại 4.0 không ngừng thay đổi này, cuộc sống luôn ngập tràn những điều bất ngờ.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"MichaelChen","avatar":""},{"name":"Noah","avatar":""},{"name":"Edward Zhang","avatar":""},{"name":"Heidi Wong","avatar":""},{"name":"Ruijia Jiang","avatar":""},{"name":"Ju Hao","avatar":""},{"name":"Wu jiang","avatar":""},{"name":"Mao A Min","avatar":""},{"name":"Donye.S","avatar":""},{"name":"Wang Bao Qiang","avatar":""},{"name":"Jiang Wen Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
