INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('5-den-7-gio', '5 Đến 7 Giờ', '5 to 7', 'https://phimimg.com/upload/vod/20231205-1/ad71040dbbd46471f4379877a7af827a.jpg', 'https://phimimg.com/upload/vod/20231205-1/d3b0359d76a7997f402cf3b021871e5a.jpg', '<p>Một nhà văn trẻ đầy đam mê đã vô tình rơi vào mối quan hệ tình cảm với một người phụ nữ. Duy chỉ một rắc rối: cô ấy đã kết hôn và cả hai người chỉ có thể gặp nhau trong khoảng 5 giờ đến 7 giờ mỗi buổi chiều.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anton Yelchin","avatar":""},{"name":"Bérénice Marlohe","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Frank Langella","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324456);
