INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('5-den-7-gio', '5 Đến 7 Giờ', '5 to 7', '5 đến 7 giờ 5 to 7 anton yelchin bérénice marlohe olivia thirlby lambert wilson frank langella ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-scooby-doo-bi-an-wrestlemania', 'Chú Chó Scooby Doo: Bí Ẩn Wrestlemania', 'Scooby-Doo! WrestleMania Mystery', 'https://phimimg.com/upload/vod/20231205-1/2bb45039d5c96fe93aa94412ee28a4d9.jpg', 'https://phimimg.com/upload/vod/20231205-1/725829b93ccda3799b9427c39d11f158.jpg', '<p>Bí ẩn bắt đầu khi Shaggy và Scooby giành vé tham dự WrestleMania và thuyết phục phi hành đoàn đi cùng họ đến WWE City. Nhưng thành phố này ẩn chứa một bí mật ma quái - một con Gấu ma đáng sợ đang nắm giữ thị trấn trong vòng kìm kẹp đáng sợ của hắn! Để bảo vệ Danh hiệu vô địch WWE đáng thèm muốn, nhóm đã nhận được sự giúp đỡ từ các Siêu sao WWE như John Cena, Triple H, Sin Cara, Brodus Clay, AJ Lee, The Miz và Kane. Xem Scooby và đồng bọn vật lộn để giải quyết vụ án này trước khi quá muộn.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Lillard","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"April Jeanette Brooks","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Mindy Cohn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324456);
