INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-than-ky', 'Cuộc Giải Cứu Thần Kỳ', 'Boonie Bears: To the Rescue', 'https://phimimg.com/upload/vod/20231205-1/adf9d9612f78ee5ab09b2c29544f985d.jpg', 'https://phimimg.com/upload/vod/20231205-1/3eed430865d3fd680f5528d5aeeaa42b.jpg', '<p>Cuộc giải cứu thần kỳ - Boonie Bears: To the Rescue bắt đầu khi hai chiếc hộp bị chuyển nhầm trong một vụ tai nạn xe hơi, giữa đêm mưa bão. Logger Vick lấy một chiếc vali từ hiện trường vụ tai nạn và bí ẩn trong đó dần được tiết lộ. Kể từ khi cậu ta mang chiếc hộp bí ẩn đó về, khu rừng trở nên không còn thanh bình nữa, và cuộc sống của các chú gấu thay đổi hoàn toàn.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
