INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-dau-sarah-kane', 'Theo Dấu Sarah Kane', '4.48', 'https://phimimg.com/upload/vod/20231205-1/b176f32b74997c912c4ff844a40e025d.jpg', 'https://phimimg.com/upload/vod/20231205-1/c9072d5e407737e2d12e8a66a05e90d2.jpg', '<p>Để chiến thắng một nhà viết kịch khó tính trong buổi thử giọng tiếp theo, một nữ diễn viên trẻ chuyển sang phương pháp diễn xuất cực đoan đến mức cô dần đánh mất chính mình trong vai diễn một cô gái hoang dã song tính lăng nhăng, tự hủy hoại bản thân và bắt đầu ngủ xung quanh, kích động đánh nhau và cắt mình. Liệu cô có thể kéo mình trở lại khỏi bờ vực thẳm trước khi quá muộn?</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Aurélie Houguenade","avatar":""},{"name":"Jean-Marie Galey","avatar":""},{"name":"David Chausse","avatar":""},{"name":"Ynda Rouya","avatar":""},{"name":"Marie Menges","avatar":""},{"name":"Matt Gras","avatar":""},{"name":"Manuel Lambinet","avatar":""},{"name":"Kait Tenison","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
