INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-kim-tu-thap', 'Bí Ẩn Kim Tự Tháp', 'The Pyramid', 'https://phimimg.com/upload/vod/20231204-1/d1a0f4c42a75cfc59dc9a3f84a01c275.jpg', 'https://phimimg.com/upload/vod/20231204-1/7e666893f2f7e23d4ef091135e0d6bd9.jpg', '<p>Bí Ẩn Kim Tự Tháp - The Pyramid là bộ phim kinh dị Mỹ 2014 của đạo diễn Grégory Levasseur. Kim tự tháp, nơi luôn xảy ra những câu chuyện quái gỡ, không có lối thoát, không có đáp án. Bộ phim xoay quanh nhóm thám hiểm khai quật 1 kim tử tháp 3 cạnh. Với họ đó là điều hết sức thú vị, nhưng mọi thứ không dừng lại ở đó. Mỗi người trong số họ lần lượt trả giá cho việc làm liều lĩnh của mình. Cái giá ấy có phải là quá đắt? Đây là 1 bộ phim hết sức kinh dị, gây cấn, hồi hộp đến ngẹt thở.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denis O''Hare","avatar":""},{"name":"Ashley Hinshaw","avatar":""},{"name":"James Buckley","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
