INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-biet', 'Dị Biệt', 'Divergent', 'null', 'https://phimimg.com/upload/vod/20231204-1/5886c986f582e8d3e514b4f8310ff6d0.jpg', '<p>Trong thế giới bị chiến tranh tàn phá và chia cắt, Tris khám phá ra năng lực đặc biệt và cùng bốn phái chống lại âm mưu hiểm độc nhắm đến những người như họ.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Ashley Judd","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324456);
