INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-bong-dem', 'Ám Ảnh Bóng Đêm', 'Out of the Dark', 'https://phimimg.com/upload/vod/20231203-1/a084496e1adc6686b3fd17a1f731750e.jpg', 'https://phimimg.com/upload/vod/20231203-1/30eb95930d1f6797e5aeb09207069711.jpg', '<p>Ám Ảnh Bóng Đêm - Out of the Dark xoay quanh cuộc sống của vợ chồng Paul \u0026 Sarah Harriman cùng cô con gái 6 tuổi Hannah. Họ đang hứng khởi bắt đầu cuộc sống mới khi Sarah sẽ tiếp quản nhà máy sản xuất giấy của cha mình, cho đến khi họ khám phá ra những bí ẩn kỳ lạ xung quanh ngôi nhà mình đang sống: câu chuyện về những nghi lễ cúng tế xưa, hình ảnh thoắt ẩn thoắt hiện của những cô bé, cậu bé. Dường như chúng có một sự quan tâm đặc biệt tới Hannah bé bỏng. Một ngày kia, Hannah đột nhiên biến mất. Chuyện gì đang xảy ra, hay đúng hơn là chuyện gì đã từng xảy ra tại nơi đây?</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Stiles","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Scott Speedman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
