INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('annie', 'Annie', 'Annie', 'https://phimimg.com/upload/vod/20231202-1/fc13d97a5eee0261d4bb76c58fd959fa.jpg', 'https://phimimg.com/upload/vod/20231202-1/f8140abd801d38a8db7f03fe6ccee18f.jpg', '<p>Trong bản chuyển thể từ vở nhạc kịch Broadway này, vị chính trị gia nọ nhận nuôi một đứa trẻ lanh lợi rồi họ thay đổi cuộc đời của nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Quvenzhané Wallis","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Amanda Troya","avatar":""},{"name":"Zoe Colletti","avatar":""},{"name":"Nicolette Pierini","avatar":""},{"name":"Eden Duncan-Smith","avatar":""},{"name":"Dorian Missick","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"Mike Birbiglia","avatar":""},{"name":"Stephanie Kurtzuba","avatar":""},{"name":"Peter Van","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
