INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-cham-tran', 'Cuộc Chạm Trán', 'Tension(s)', 'null', 'https://phimimg.com/upload/vod/20231202-1/c0c12aca357e3413234edcbd891f76b1.jpg', '<p>Phản bội và thực hiện nhiệm vụ bí mật theo yêu cầu của một nhóm lực lượng khủng bố có vũ khí, hoặc đánh cược tính mạng của gia đình để phản kháng, &quot;đặc vụ được chọn&#39; phải đưa ra quyết định trong tích tắc. Một cuộc chạm trán cực kỳ gây cấn và nảy lửa giữa siêu đặc vụ và nhóm tội phạm nguy hiểm nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Louis Mandylor","avatar":""},{"name":"David Kinsman","avatar":""},{"name":"Richard Roy Sutton","avatar":""},{"name":"François Mequer","avatar":""},{"name":"Emily Stranges","avatar":""},{"name":"Justin Bigelli","avatar":""},{"name":"Danesh Hanbury","avatar":""},{"name":"Thom Savery","avatar":""},{"name":"Joel Lacoursiere","avatar":""},{"name":"Jeanette Roxborough","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
