INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-tuyet-nhat-trong-toi', 'Điều Tuyệt Nhất Trong Tôi', 'The Best of Me', 'https://phimimg.com/upload/vod/20231202-1/96c25f84c47f7da5a56c77638ab59fa4.jpg', 'https://phimimg.com/upload/vod/20231202-1/b68d0db497f86e9df57c0667d2d3e716.jpg', '<p>Một cặp bạn học cũ thời trung học gặp lại nhau sau nhiều năm khi họ trở về thăm quê hương nhỏ bé của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Monaghan","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Liana Liberato","avatar":""},{"name":"Gerald McRaney","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Sebastian Arcelus","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"Rob Mello","avatar":""},{"name":"Hunter Burke","avatar":""},{"name":"Robby Rasmussen","avatar":""},{"name":"Caroline Hebert","avatar":""},{"name":"Ian Nelson","avatar":""},{"name":"Schuyler Fisk","avatar":""},{"name":"Douglas M.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
