INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-may-hoang-gia', 'Thợ May Hoàng Gia', 'The Royal Tailor', 'https://phimimg.com/upload/vod/20231201-1/4d79b9b9b3159a450eb40ef00ea4ada8.jpg', 'https://phimimg.com/upload/vod/20231201-1/1e9f4fbeb5990d4c66dd5a9be48ac792.jpg', '<p>Phim là những âm mưu quyền lực, lòng đố kị giữa những thợ may hoàng gia. Dol Seok là thợ may giỏi bậc nhất thời bấy giờ, luôn tuân theo những luật lệ quy tắc. Kong Jin là một thiên tài thiết kế bẩm sinh. Nhà Vua và Hoàng Hậu bỗng nhiên bị lôi kéo vào cuộc đua trang phục giữa Dol Seok và Kong Jin.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Suk-kyu","avatar":""},{"name":"Go Soo","avatar":""},{"name":"Park Shin-hye","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Lee Yu-bi","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Shin So-yul","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Yang Eun-yong","avatar":""},{"name":"Park So-dam","avatar":""},{"name":"Kim Dong-hwi","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Do-im Woo","avatar":""},{"name":"Choi Hee-jin","avatar":""},{"name":"Lee Seo-yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324456);
