INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-long-de-doa', 'Hắc Long Đe Dọa', 'Dragon Nest: Warrior''s Dawn', 'https://phimimg.com/upload/vod/20231212-1/edf5d18a195cc0adc5a6af5ef5840c0e.jpg', 'https://phimimg.com/upload/vod/20231212-1/603d9d017230d9f800a2c92afef1ab48.jpg', '<p>HẮC LONG ĐE DỌA - DRAGON NEST: WARRIORS DAWN là một bộ phim hoạt hình phiêu lưu Mỹ - Trung Quốc 2014 của đạo diễn Song Yuefeng dựa trên trò chơi Dragon Nest. 50 năm trước, Black Dragon xuất hiện một lần trên một vùng đất hòa bình ở Lagendia. Theo lệnh của nhà vua, Geraint, Argenta, Velskud và anh hùng huyền thoại khác tập hợp các lực lượng khác nhau để hình thành liên minh Slaying Dragon. Việc này đã làn truyền rộng rãi như là Cuộc xam lược đầu tiên của Rồng. Tuy nhiên, chính xác những gì đã xảy ra trong vụ việc này? Đâu là những anh hùng sau cuộc xâm lược Rồng?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Blythe Auffarth","avatar":""},{"name":"Bianca Collins","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324456);
