INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buon-nguoi', 'Buôn Người', 'Beyond Justice', 'https://phimimg.com/upload/vod/20231212-1/4588238aee1d16a5f080b09c05ad06c2.jpg', 'https://phimimg.com/upload/vod/20231212-1/02f42f6f9ffa0aa8ef5bff11ae66cf85.jpg', '<p>Buôn Người - Beyond Justice xoay quanh câu chuyện về một luật sư trẻ tuổi phải vật lộn với một vụ án mạng không hề đơn giản như mọi người thấy. Và anh nhanh chóng nhận ra rằng để giữ mạng sống cho bản thân và thân chủ, anh ta phải làm việc ngoài vòng pháp luật.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":" Mischa Barton","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Timothy Woodward Jr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
