INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-ma-quai', 'Linh Hồn Ma Quái', 'The Canal', 'https://phimimg.com/upload/vod/20231201-1/a62e553057db8876db50d86bab1dc2cf.jpg', 'https://phimimg.com/upload/vod/20231201-1/c9c03d44f3c03b08576fd54f52b2669d.jpg', '<p>Một người đàn ông nghi ngờ vợ lừa dối mình bắt đầu mơ thấy ác mộng về một sự hiện diện xấu xa mà anh ta tin rằng đang trú ngụ trong nhà mình.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rupert Evans","avatar":""},{"name":"Antonia Campbell-Hughes","avatar":""},{"name":"Hannah Hoekstra","avatar":""},{"name":"Steve Oram","avatar":""},{"name":"Kelly Byrne","avatar":""},{"name":"Serena Brabazon","avatar":""},{"name":"Anthony Murphy","avatar":""},{"name":"Calum Heath","avatar":""},{"name":"Paddy Curran","avatar":""},{"name":"Maura Foley","avatar":""},{"name":"Carl Shaaban","avatar":""},{"name":"Sinead Watters","avatar":""},{"name":"Alicja Ayres","avatar":""},{"name":"Conor Horgan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
