INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-can-phong-bi-an', 'Những Căn Phòng Bí Ẩn', 'The Rooms', 'https://phimimg.com/upload/vod/20231212-1/a9cc691051b8149f67784d14a71bb7a6.jpg', 'https://phimimg.com/upload/vod/20231212-1/792c6bf92feafb789ac5d24ae19f9b0d.jpg', '<p>Những Căn Phòng Bí Ẩn - The Rooms xoay quanh một căn phòng bí ẩn với ba sự kiện kinh dị. Câu chuyện thứ nhất, một nghệ sĩ violon cô đơn, sau khi vợ bị tai nạn nằm liệt giường, do bí bách về nhu cầu sinh lý nên anh tìm đến một cô gái mại dâm để giải tỏa. Trong khi mây mưa thì cô vợ xuất hiện. Câu chuyện thứ hai, đám mafia đi ngang qua thị trấn và kiếm một chỗ nghỉ qua đêm, do khách sạn chỉ còn một phòng duy nhất đó, nên họ chuẩn bị tinh thần cho những gì sẽ chờ đón họ trong đêm. Câu chuyện thứ 3, Ple từ Chiang Mai lên Bankok để an ủi một người bạn thất tình. Phòng cô đặt hết chỗ nên họ đưa cô lên phòng Honeymoon Suite. Tình cờ chạm mặt một anh chàng đẹp trai cũng phải lòng cô ngay cái nhìn đầu tiên. Đêm đó gặp nhau, cô phát hiện chàng trai của lòng mình thật ra đã chết, và người đợi chờ cô ở sảnh là một cái xác thối.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Markus Waldow","avatar":""},{"name":"Yoko Takano","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324456);
