INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huy-hieu-phan-boi', 'Huy Hiệu Phản Bội', 'Badge Of Betrayal', 'https://phimimg.com/upload/vod/20231211-1/f826c64c98b2e71a76818e64ccd7cd6d.jpg', 'https://phimimg.com/upload/vod/20231211-1/ae6f5196306f2f48c8c58c8ab5c6252e.jpg', '<p>Huy Hiệu Của Sự Phản Bội - Badge of Betrayal kể về Zoey - một nữ cảnh sát tội phạm mạng và Barry - một thanh tra cảnh sát. Họ cùng nhau nuôi dạy con trai mình là Timmy. Nhưng trớ trêu thay, Zoey lại phát hiện ra chồng mình ngoại tình. Đau khổ hơn nữa, vào một đêm nọ, vụ hỏa hoạn bất ngờ đã cướp đi sinh mạng của Timmy và Zoey bị buộc tội giết con trai mình. Trong cuộc chiến đấu chứng minh sự vô tội của bản thân, Zoey đã phải nhận một cú sốc lớn nhất trong cuộc đời.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Julie Benz","avatar":""},{"name":"Maxwell Kovach","avatar":""},{"name":"Rick Ravanello","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
