INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-xuan', 'Hồi Xuân', 'Revivre', 'https://phimimg.com/upload/vod/20231130-1/90706366acd9077a6b9a9535a9be3faf.jpg', 'https://phimimg.com/upload/vod/20231130-1/0b29a0a0019818c4e2099de3c5fa4d17.jpg', '<p>Là tác phẩm thứ 102 của đạo diễn kỳ cựu Hàn Quốc Im Kwon Taek, Revivre đưa khán giả khám phá những ý nghĩa mang tính biểu tượng, quan niệm về cái chết. Trong phim, nam diễn viên kỳ cựu Ahn Sung Ki vào vai Oh Sang Moo, giám đốc tiếp thị tại một công ty mỹ phẩm. Mỗi ngày, ông phải đi về giữa cơ quan và bệnh viện để chăm sóc Jin Kyung (Kim Ho Jung), người vợ được chẩn đoán bị ung thư não.Oh không bao giờ phàn nàn hay bộc lộ hết nỗi căm ghét của mình trong việc cho cô ăn, cạo đầu, thậm chí tự tay thay tã và lau rửa giúp vợ. Nhưng bất chấp việc có vẻ tận tụy chăm sóc người vợ đau ốm, ông thấy mình si dại một nhân viên tiếp thị mới hoàn toàn trẻ trung, hấp dẫn và lộng lẫy tên Choo Eun Joo (Kim Gyu Ri). Choo Eun Joo toát ra một vẻ hấp dẫn gợi dục hiển nhiên, thuyết phục khán giả tin rằng chuyện ngoại tình thể nào cũng xảy ra…</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ahn Sung-ki","avatar":""},{"name":"Kim Gyu-ri","avatar":""},{"name":"Kim Ho-jung","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Yeon Woo-jin","avatar":""},{"name":"Kim Yeong-hoon","avatar":""},{"name":"Cha Chung-hwa","avatar":""},{"name":"Ahn Suk-hwan","avatar":""},{"name":"Uh Sung-wook","avatar":""},{"name":"Han Eu-ddeum","avatar":""},{"name":"Kyul Hwi","avatar":""},{"name":"Park Hyun-ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324456);
