INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-chu-rong-bi-mat-tich', 'Tom Và Jerry: Chú Rồng Bị Mất Tích', 'Tom And Jerry: The Lost Dragon', 'https://phimimg.com/upload/vod/20231211-1/c26b7eba9cfd425a5e3676ae0910d14e.jpg', 'https://phimimg.com/upload/vod/20231211-1/8c5c6b9ff55dba4ef774cd235ff3566a.jpg', '<p>Tom Và Jerry: Chú Rồng Mất Tích là phần phim mới nhất về cặp mèo - chuột nổi tiếng do Spike Brandt và Tony Cervone đạo diễn. Bộ phim sẽ đưa người xem phiêu lưu vào thế giới của những phù thủy và những tình huống hài hước giữa chúng.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laraine Newman","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Richard McGonagle","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
