INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cuc-quang', 'Tình Yêu Cực Quang', 'Endless Nights In Aurora', 'https://phimimg.com/upload/vod/20231211-1/b741b3f4652f30665932ae283d12037d.jpg', 'https://phimimg.com/upload/vod/20231211-1/038b7b261e20111940f7c34876d80748.jpg', '<p>Phim Tình Yêu Cực Quang - Endless Nights in Aurora 2014: Một bộ phim về lời hẹn ước, sự chờ đợi, bỏ lỡ, và tha thứ. Hai người cách nhau 24 năm, hai câu chuyện về mối tình đầu, không cùng thời đại, không cùng quan niệm về tình yêu, nhưng cùng có sự cố chấp với tình yêu. Truyền thuyết về “Cực quang phía Bắc” kể về sự quyến luyến của mẹ và con gái giữa tình yêu và tình thân. Tình yêu giữa hai thế hệ bắt đầu từ đó.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Thừa Lâm","avatar":""},{"name":"Vương Hựu Thắng","avatar":""},{"name":"Lý Vận Khánh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
