INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-sat-nhan-2', 'Truy Tìm Sát Nhân 2', 'Garage Sale Mystery 2', 'null', 'https://phimimg.com/upload/vod/20231211-1/52c770ecf3ce682332f000733d9ccc5d.jpg', '<p>Truy Tìm Sát Nhân 2 - Garage Sale Mystery 2 xoay quanh câu chuyện Jennifer Shannon phát hiện chủ nhân của một kho lưu trữ tự quản - tên là Martin bị sát hại. Trước đó, Jen đã nhìn thấy một khách hàng cũ tỏ thái độ khó chịu ở đó và Martin đề cập đến việc ly hôn. Cô bị kéo vào vụ án và trở thành nhân chứng chính. Đồng thời, cửa hàng của cô bị đột nhập và vợ của Martin tìm đến với thái độ vô cùng giận dữ. Sau đó, Jennifer và Danielle - bạn của cô phát hiện ra trong đống hàng hóa mới của họ có chứa bằng chứng mà họ cần để truy tìm thủ phạm thực sự. Họ phải chạy đua để cứu lấy một mạng người và đặt mình vào tình thế nguy hiểm. Liệu họ có thành công trước khi hết thời gian?</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lori Loughlin","avatar":""},{"name":"Sarah Strange","avatar":""},{"name":"Steve Bacic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324456);
