INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-quy', 'Vợ Quỷ', 'She Devil 2014', 'https://phimimg.com/upload/vod/20231211-1/6f94bb0651a35465406c7f7ceb6bb77f.jpg', 'https://phimimg.com/upload/vod/20231211-1/332b6bd01741e694f8b16403659c086d.jpg', '<p>Vợ Quỷ - She Devil là một bộ phim kinh dị Thái Lan của đạo diễn Pisut Praesangeam. Cô ca sĩ 28 tuổi Harin Suthamjatas. Wen, một anh chàng đã tốt nghiệp giúp mẹ làm nông nghiệp. Mẹ rất muốn anh ta sớm lấy vợ để có cháu ẵm bồng. Bà tìm cho Wen một cô gái xinh đẹp tên Ploy và bắt con cưới cô ta. Wen tự hỏi tại sao một cô gái xinh đẹp như Ploy vẫn còn độc thân. Điều gì đến cũng đến, bắt đầu từ đên tân hôn, Wen phát hiện ra Ploy trở thành một con người khác - một con quỷ khi màn đêm buông xuống. Thương vợ, Wen tìm mọi cách để giúp nàng thoát khỏi những gì điều kì quái mỗi đêm. Cả 2 quyết định tìm đến vị pháp sư nổi tiếng để giúp Ploy hóa giải...</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Fandee Chanyathanakorn","avatar":""},{"name":"Harin Suthamjarus","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324456);
