INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-chinh-minh', 'Làm Lại Chính Mình', 'The Way He Looks', 'https://phimimg.com/upload/vod/20231130-1/937df14ede036792c8ad14118e673d62.jpg', 'https://phimimg.com/upload/vod/20231130-1/eb83698ed34057cd83cafe9f5ed19617.jpg', '<p>Leonardo là một thiếu niên mù phải đối mặt với một người mẹ bảo vệ quá mức trong khi cố gắng sống một cuộc sống độc lập hơn. Trước sự thất vọng của người bạn thân nhất của mình, Giovana, anh ấy dự định tham gia một chương trình trao đổi ở nước ngoài. Khi Gabriel, một học sinh mới trong thị trấn, đến lớp học của họ, những cảm xúc mới nảy nở trong Leonardo khiến anh đặt câu hỏi về kế hoạch của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Ghilherme Lobo","avatar":""},{"name":"Fábio Audi","avatar":""},{"name":"Tess Amorim","avatar":""},{"name":"Lúcia Romano","avatar":""},{"name":"Eucir de Souza","avatar":""},{"name":"Selma Egrei","avatar":""},{"name":"Isabela Guasco","avatar":""},{"name":"Victor Filgueiras","avatar":""},{"name":"Pedro Carvalho","avatar":""},{"name":"Guga Auricchio","avatar":""},{"name":"Bárbara Pereira","avatar":""},{"name":"Matheus Abreu","avatar":""},{"name":"Naruna Costa","avatar":""},{"name":"Júlio Machado","avatar":""},{"name":"Renata Novaes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324456);
