INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-den-dui', 'Ngày Đen Đủi', 'Not My Day - Nicht Mein Tag', 'https://phimimg.com/upload/vod/20231130-1/acce872a26cf92d48db90f9e721f381e.jpg', 'https://phimimg.com/upload/vod/20231130-1/d5f5b6391d587a3391abca69defa5a97.jpg', '<p>Phim Not My Day - Nicht Mein Tag - Ngày Đen Đủi 2014 nói về chàng nhân viên ngân hàng Till Reiners có vẻ như lại gặp một ngày không may mắn. Chán nản từ cuộc sống, công ăn việc làm cho đến gia đình bao gồm cả cuộc hôn nhân sắp đổ vỡ khiến anh dường như muốn từ bỏ tất cả. Vào một ngày định mệnh, Nappos xuất hiện, cuớp ngân hàng và bắt Till làm con tin, từ đấy xảy ra một chuỗi hàng loạt các sự kiện làm cho cuộc sống của Till và Nappos rối loạn. Thế nhưng trong cái rủi có cái may, nhờ sự kiện trên mà chính Til đã tìm được chính bản thân mình và có thêm những trải nghiệm quý báu cùng Nappos. Chỉ có điều Nappos không biết rằng, kẻ anh bắt làm con tin là một cựu rocker có vấn đề nặng với rượu bia, điều khiến mọi việc chỉ thêm đen đủi!!!</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Axel Stein","avatar":""},{"name":"Moritz Bleibtreu","avatar":""},{"name":"Jasmin Gerat","avatar":""},{"name":"Anna Maria Mühe","avatar":""},{"name":"Nele Kiper","avatar":""},{"name":"Ben Ruedinger","avatar":""},{"name":"Kasem Hoxha","avatar":""},{"name":"Bekim Guri","avatar":""},{"name":"Tobias Nied","avatar":""},{"name":"Emilian Markgraf","avatar":""},{"name":"Ralf Richter","avatar":""},{"name":"Maxwell Richter","avatar":""},{"name":"Milan Peschel","avatar":""},{"name":"Christian Kahrmann","avatar":""},{"name":"Frederick Lau","avatar":""},{"name":"Marvin Linke","avatar":""},{"name":"Thomas Balou Mar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
