INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-doan-thay-ma-2', 'Binh Đoàn Thây Ma 2', 'Dead Snow 2: Red vs. Dead', 'https://phimimg.com/upload/vod/20231130-1/e68f0fd480b037a742acf73a0d0a6371.jpg', 'https://phimimg.com/upload/vod/20231130-1/9e4b0dcdd6e87d4d48f30c4d28023f50.jpg', '<p>Nếu ngày tồi tệ nhất cuộc sống của bạn bao gồm cái chết vô tình của cô bạn gái bởi một cái rìu, cưa xích cánh tay của bạn ra như trong phim kinh dị, người bạn thân nhất của bạn đã bị ăn thịt bởi một tiểu đoàn của Đức Quốc xã zombified, bạn đã cho rằng không thể tồi tệ hơn được nữa. Trong trường hợp của Martin, đó chỉ là sự khởi đầu...</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vegar Hoel","avatar":""},{"name":"Ørjan Gamst","avatar":""},{"name":"Jocelyn DeBoer","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Ingrid Haas","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Kristoffer Joner","avatar":""},{"name":"Hallvard Holmen","avatar":""},{"name":"Amrita Acharia","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Christian Rubeck","avatar":""},{"name":"Bjarte Tjøstheim","avatar":""},{"name":"Charlotte Frogner","avatar":""},{"name":"Jesper Sundnes","avatar":""},{"name":"Ingar Helge Gimle","avatar":""},{"name":"Tage Guddin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
