INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-vuong-hoc-duong-3', 'Bá Vương Học Đường 3', 'Crows Explode', 'https://phimimg.com/upload/vod/20231130-1/d98a1e74ce33391efec8de2c8bc1bd67.jpg', 'https://phimimg.com/upload/vod/20231130-1/e36244c1b221a7998668707c4706eeaf.jpg', '<p>Bá Vương Học Đường 3 hay có tên khác là Thiết Quân Đoàn 3 là bộ phim hành động võ thuật dành cho lứa tuổi thanh thiếu niên được trông chờ nhất trong năm 2014 này, phần 2 của bộ phim được ra mắt từ năm 2009, và cho đến nay nó làm cho các fan hâm bộ series phim này phải trông chờ mỏi mòn. Tiêu đề tiếng Anh của bộ phim là Crows Zero 3 nhưng nó còn có 1 tên khác là Crows Explode 2014. Sau khi các đàn anh như Genji và Serizawa tốt nghiệp và gác kiếm giang hồ thì ngôi trường của những con quạ lại nổi lên các nhân vật kiệt xuất khác đánh nhau để tranh dành quyền lực.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masahiro Higashide","avatar":""},{"name":"Taichi Saotome","avatar":""},{"name":"Yuya Yagira","avatar":""},{"name":"Ryo Katsuji","avatar":""},{"name":"Takanori Iwata","avatar":""},{"name":"Kento Nagayama","avatar":""},{"name":"Kyosuke Yabe","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Ryusuke Ito","avatar":""},{"name":"Kenzō Maihara","avatar":""},{"name":"Tsutomu Takahashi","avatar":""},{"name":"Suzu Hirose","avatar":""},{"name":"Joey Iwanaga","avatar":""},{"name":"ELLY","avatar":""},{"name":"Onimaru","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c9