INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-tim-mau', 'Quả Tim Máu', 'Vengeful Heart', 'https://phimimg.com/upload/vod/20231207-1/3ebdf4c37e4998c2486a40b238652047.jpg', 'https://phimimg.com/upload/vod/20231207-1/d63071c9ed371d2ada18975b8321c4ea.jpg', '<p>Sau khi thay tim của một người bị tai nạn, Linh bắt đầu có gắn bó kỳ lạ với căn nhà cổ trên Đà Lạt. Pha trộn giữa kinh dị và hài hước, Quả Tim Máu là một trong những phim Việt ăn khách nhất mọi thời.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Nhã Phương","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Quý Bình","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
