INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-giac-quy-bermuda', 'Tam Giác Quỷ Bermuda', 'Bermuda Tentacles', 'https://phimimg.com/upload/vod/20231129-1/90d0eef3a85a43c177a22e4991c6b06f.jpg', 'https://phimimg.com/upload/vod/20231129-1/22778fa4c1a4fe6b71af2b4323bc5b9e.jpg', '<p>Sau khi Lực lượng Không quân Một bị rơi trong cơn bão ở Tam giác quỷ Bermuda, Hải quân Hoa Kỳ được cử đi tìm khoang thoát hiểm đang giữ Tổng thống. Một con quái vật khổng lồ dưới lòng đại dương thức tỉnh và tấn công hạm đội.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Savage","avatar":""},{"name":"Linda Hamilton","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Mya","avatar":""},{"name":"Justin Cuomo","avatar":""},{"name":"Jeff Rector","avatar":""},{"name":"Andy Clemence","avatar":""},{"name":"Stephanie Cantu","avatar":""},{"name":"Trevor Donovan","avatar":""},{"name":"Richard Whiten","avatar":""},{"name":"Ricco Ross","avatar":""},{"name":"Robert Blanche","avatar":""},{"name":"Angelique Cinelu","avatar":""},{"name":"Blanca Blanco","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324457);
