INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-so-phan', 'Hai Số Phận', 'The Double', 'https://phimimg.com/upload/vod/20231129-1/5e22f81cac54389d8cd862a75209cd4e.jpg', 'https://phimimg.com/upload/vod/20231129-1/87b0712ff91aa381f534a730bbc0d614.jpg', '<p>Một máy bay không người lái văn phòng vụng về ngày càng trở nên mất trí sau khi một người có vẻ ngoài lôi cuốn và tự tin nhận công việc tại nơi làm việc của anh ta và quyến rũ người phụ nữ mà anh ta mong muốn.</p>', 'Full', 1, 'single', 'completed', 6, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Mia Wasikowska","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Yasmin Paige","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"James Fox","avatar":""},{"name":"Cathy Moriarty","avatar":""},{"name":"Phyllis Somerville","avatar":""},{"name":"Gabrielle Downey","avatar":""},{"name":"Jon Korkes","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Kobna Holdbrook-Smith","avatar":""},{"name":"Susan Blommaert","avatar":""},{"name":"Bruce Byron","avatar":""},{"name":"J. Mascis","avatar":""},{"name":"Tony Rohr","avatar":""},{"name":"Karima Riachy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
