INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-2-ke-sat-nhan', 'Đột Kích 2: Kẻ Sát Nhân', 'The Raid 2: Berandal', 'https://phimimg.com/upload/vod/20231129-1/4ee659deaf4deb9f83ebe500695fa4c3.jpg', 'https://phimimg.com/upload/vod/20231129-1/530a56fdee37b3bb1613622192f293e0.jpg', '<p>The Raid 2: Berandal (Đột Kích 2: Kẻ Sát Nhân): Thêm một lần nữa Rama, một cảnh sát tài năng và đầy quả cảm phải khoác lên mình chiếc áo &quot;tội phạm&quot; để triệt phá toàn bộ đường dây Mafia và trả lại sự bình yên cho thành phố. Tiếp nối câu chuyện ở phần 1 những pha võ thuật đỉnh cao cùng cốt truyện chặt chẽ đã tạo nên hình ảnh một con người dũng cảm và can trường sẵn sàng hi sinh để bảo vệ cho gia đình và xã hội.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Iko Uwais","avatar":""},{"name":"Arifin Putra","avatar":""},{"name":"Tio Pakusadewo","avatar":""},{"name":"Oka Antara","avatar":""},{"name":"Alex Abbad","avatar":""},{"name":"Cecep Arif Rahman","avatar":""},{"name":"Julie Estelle","avatar":""},{"name":"Very Tri Yulisman","avatar":""},{"name":"Ryuhei Matsuda","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Yayan Ruhian","avatar":""},{"name":"Cok Simbara","avatar":""},{"name":"Roy Marten","avatar":""},{"name":"Epy Kusnandar","avatar":""},{"name":"Zack Lee","avatar":""},{"name":"Deddy Sutomo","avatar":""},{"name":"Marsha Timot","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
