INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-kich-ngam-2014', 'Biệt Kích Ngầm', 'Seal Team Eight: Behind Enemy Lines', 'https://phimimg.com/upload/vod/20231101-1/6a58f3e192c943372f44b7f935efac54.jpg', 'https://phimimg.com/upload/vod/20231101-1/87e2551d08a85f221b23254435d84c75.jpg', '<p>Biệt Kích Ngầm là một bộ phim chiến tranh năm 2014 của đạo diễn Roel Reine với diễn viên Tom Sizemore. Đây là phần thứ tư trong serial này, cũng như phần tiếp theo của Behind Enemy Lines, Behind Enemy Lines II Axis of Evil và Behind Enemy Lines: Colombia. Một nhóm lính tinh nhuệ của Hải quân Hoa Kỳ SEAL được gửi đến một căn cứ của bọn thổ phỉ ở Congo ,với nhiệm vụ bí mật tìm kiếm và ngăn chặn các hoạt động khai thác vũ khí uranium rơi vào tay bọn khủng bố.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Tom Sizemore","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Bonnie Lee Bouman","avatar":""},{"name":"Leroy Gopal","avatar":""},{"name":"Lex Shrapnel","avatar":""},{"name":"Tanya van Graan","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Dylan Edy","avatar":""},{"name":"Anthony Oseyemi","avatar":""},{"name":"Darron Meyer","avatar":""},{"name":"Aurélie Meriel","avatar":""},{"name":"Eugene Khumbanyiwa","avatar":""},{"name":"Colin Moss","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
