INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-chia-tay-break-up-100', 'Bậc Thầy Chia Tay', 'Break Up 100', 'https://phimimg.com/upload/vod/20231115-1/6a88071b9d07d36eb7b69d5c7b52ecf0.jpg', 'https://phimimg.com/upload/vod/20231115-1/594a8e38d4e8185884f904557fbd86ba.jpg', '<p>Sau lần chia tay thứ 99, người phụ nữ nghiện việc và anh bạn trai vô tư của cô cùng mở một quán cà phê, nơi mọi người có thể trưng bày đồ lưu niệm từ các mối tình cũ.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Ivana Wong","avatar":""},{"name":"Kenny Chan","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Jase Ho","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Jan Lam Hoi-Fung","avatar":""},{"name":"Aka Zhao","avatar":""},{"name":"Jason Sze","avatar":""},{"name":"Miriam Yeung Chin-Wah","avatar":""},{"name":"Lawrence Cheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324457);
