INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-chia-tay-the-breakup-guru', 'Bậc Thầy Chia Tay', 'The Breakup Guru', 'https://phimimg.com/upload/vod/20231012-1/37938d700d104cbee193ccf91e7f72e0.jpg', 'https://phimimg.com/upload/vod/20231012-1/777a120e77a0b12e3d63a482c6859c36.jpg', '<p>Một người là kẻ ăn bám, một người kiếm được bằng cách bán đĩa DVD tự lực: Mei Yuan Gui là một chàng trai sống sót bằng cách lừa dối bạn gái của mình; Ye Xiao Chun là một cô gái bán đĩa DVD để kiếm sống. Hai người ở tầng lớp dưới cùng của xã hội vô tình gặp nhau vào một ngày nọ khi chàng trai cứu cô gái, và từ đó bắt đầu câu chuyện tình yêu vui nhộn, ngớ ngẩn và cảm động nhất.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Guli Nazha","avatar":""},{"name":"Sun Li","avatar":""},{"name":"Han Han","avatar":""},{"name":"Xie Nan","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Ji Haixing","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
