INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguon-song-cuoi-cung', 'Nguồn Sống Cuối Cùng', 'The Last Survivors', 'https://phimimg.com/upload/vod/20231129-1/bd1c0f152bf518390323522924884e2e.jpg', 'https://phimimg.com/upload/vod/20231129-1/46e81af404cf08291ad61f69a3da1ceb.jpg', '<p>Trong tương lai gần, xã hội sụp đổ và nước trở nên khan hiếm. Khi một nam tước nước tham lam bắt đầu dọn sạch những người sống sót một cách thô bạo, Kendal, một thiếu niên 17 tuổi, chiến đấu với tay sai của nam tước để giữ cho một cái giếng mở.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Haley Lu Richardson","avatar":""},{"name":"Booboo Stewart","avatar":""},{"name":"Max Charles","avatar":""},{"name":"Nicole Fox","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Rena Owen","avatar":""},{"name":"Barbara Crampton","avatar":""},{"name":"Leo Lee","avatar":""},{"name":"Jacqueline Emerson","avatar":""},{"name":"Michael McCartney","avatar":""},{"name":"Veronica Sixtos","avatar":""},{"name":"Fivel Stewart","avatar":""},{"name":"Sheridan Crist","avatar":""},{"name":"Neal Polister","avatar":""},{"name":"Zack Duhame","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324457);
