INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-tran-chien-cuoi-cung', 'Naruto: Trận Chiến Cuối Cùng', 'The Last: Naruto the Movie', 'https://phimimg.com/upload/vod/20231128-1/1c87331f49a69a0e66c7972aa8f8d7d8.jpg', 'https://phimimg.com/upload/vod/20231128-1/c353ee9405f93be937a55d83e68d3d6c.jpg', '<p>Hai năm sau khi các sự kiện của cuộc Chiến tranh Thế giới Thứ tư Shinobi, mặt trăng bắt đầu đi xuống về phía Trái đất. Với trăng bây giờ là một ngôi sao băng đó sẽ phá hủy tất cả mọi thứ về tác động, Naruto phải đối phó với mối đe dọa này. Trong khi đó, Toneri Ōtsutsuki, một hậu duệ của Hamura Ōtsutsuki xác định thực hiện về di sản tổ tiên mình, xuất hiện và bắt cóc Hanabi Hyuga sau khi thất bại trong việc bắt lấy Hinata. Naruto, Hinata, Sakura, Sai, và Shikamaru được triển khai để đi giải cứu Hanabi.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Hideaki Tezuka","avatar":""},{"name":"Yurika Hino","avatar":""},{"name":"Tomomichi Nishimura","avatar":""},{"name":"Hisao Egawa","avatar":""},{"name":"Masako Katsuki","avatar":""},{"name":"Keiko Nemoto","avatar":""},{"name":"Masashi Ebara","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Noriaki Sugiya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1