INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-nay-khong-gap-lai', 'Sau Này Không Gặp Lại', 'The Continent', 'https://phimimg.com/upload/vod/20231127-1/04f96eccc2c2291b60c342d0de08e597.jpg', 'https://phimimg.com/upload/vod/20231127-1/089e108f70de949219301ebf4016751b.jpg', '<p>Ba người đàn ông sống ở hòn đảo cực Đông của Trung Quốc lên đường đến cực Tây của đất nước, và đối mặt với những khủng hoảng về tình yêu, tình bạn và niềm tin trên hành trình đến phương Tây.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"William Feng","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Wallace Chung","avatar":""},{"name":"Joe Chen","avatar":""},{"name":"Wang Luodan","avatar":""},{"name":"Yuan Quan","avatar":""},{"name":"Jia Zhangke","avatar":""},{"name":"White-K","avatar":""},{"name":"Kong Lian-Shun","avatar":""},{"name":"Zack Gao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
