INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-thang-he', 'Lời Nguyền Thằng Hề', 'Clown', 'https://phimimg.com/upload/vod/20231129-1/bfe000343bf12b911eb4272c64423193.jpg', 'https://phimimg.com/upload/vod/20231129-1/e8f89ecc19bca8f674dd6039d24d59d5.jpg', '<p>Trong lần sinh nhật thứ 6 của con trai mình, Kent - một ông bố yêu con - đã cố gắng để mời một anh hề đến mua vui cho Jack. Nhưng một sự cố xảy ra khiến công ty dịch vụ không thể đưa anh hề đến tiệc sinh nhật của con anh và Kent quyết định đóng giả hề để không làm con trai mình thất vọng. Trong ngày sinh nhật đó Jack đã ước: \</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Andy Powers","avatar":""},{"name":"Laura Allen","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Christian Distefano","avatar":""},{"name":"Chuck Shamata","avatar":""},{"name":"Elizabeth Whitmere","avatar":""},{"name":"Victor Cornfoot","avatar":""},{"name":"Lucas Kelly","avatar":""},{"name":"Emily Burley","avatar":""},{"name":"Matthew Stefiuk","avatar":""},{"name":"Michael Riendeau","avatar":""},{"name":"Miller Timlin","avatar":""},{"name":"Robert Reynolds","avatar":""},{"name":"Antonio Najera","avatar":""},{"name":"Alex Pacheco","avatar":""},{"name":"Walter Pacheco","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
