INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('winx-club-bi-mat-duoi-day-vuc', 'Winx Club: Bí Mật Dưới Đáy Vực', 'Winx Club: The Mystery of the Abyss', 'https://phimimg.com/upload/vod/20231129-1/6661491287599dd716407f394985ec31.jpg', 'https://phimimg.com/upload/vod/20231129-1/e57a5899df20405c72677a36cb929e7f.jpg', '<p>Kẻ thù không đội trời chung của Câu lạc bộ Winx, các phù thủy Trix, hợp tác với nữ thần độc ác Politea và phát hiện ra rằng, để đánh bại các nàng tiên một lần và mãi mãi và trở nên bất khả chiến bại, chỉ cần rất ít: một viên ngọc trai ẩn dưới đáy đại dương vô tận ! Nhỏ nhưng mạnh mẽ, Pearl of the Depth mang lại sức mạnh to lớn cho những người sở hữu nó! Đối với Winx, không có một phút nào để lãng phí: họ sẽ ngăn chặn kế hoạch của kẻ thù như thế nào trước khi quá muộn? Hãy sẵn sàng: nhiệm vụ nguy hiểm nhất của Winx sắp bắt đầu!</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2014, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Letizia Ciampa","avatar":""},{"name":"Perla Liberatori","avatar":""},{"name":"Domitilla D''Amico","avatar":""},{"name":"Ilaria Latini","avatar":""},{"name":"Gemma Donati","avatar":""},{"name":"Laura Lenghi","avatar":""},{"name":"Marco Vivio","avatar":""},{"name":"Alessandra Korompay","avatar":""},{"name":"Tatiana Dessi","avatar":""},{"name":"Federica De Bortoli","avatar":""},{"name":"Valeria Vidali","avatar":""},{"name":"Alberto Bognanni","avatar":""},{"name":"Emanuela Rossi","avatar":""},{"name":"Franca Lumachi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324457);
