INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ra-khoi-nha', 'Ra Khỏi Nhà', 'Housebound', 'https://phimimg.com/upload/vod/20231129-1/17795a161b92a7b42f9b9ce3df6a88a3.jpg', 'https://phimimg.com/upload/vod/20231129-1/2bb4737adce12e317746044c1181845e.jpg', '<p>Kylie Bucknell buộc phải sống trong một căn nhà mà luôn có tiếng thì thầm trong đêm, cô cho rằng đó là một ảo tưởng của mình nhưng đời không như mơ, những con ma trong nhà không thích sự có mặt của người mới và sự sắp xếp lại đồ đạc trong căn nhà...</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Morgana O''Reilly","avatar":""},{"name":"Rima Te Wiata","avatar":""},{"name":"Glen-Paul Waru","avatar":""},{"name":"Ross Harper","avatar":""},{"name":"Cameron Rhodes","avatar":""},{"name":"Millen Baird","avatar":""},{"name":"Bruce Hopkins","avatar":""},{"name":"Ryan Lampp","avatar":""},{"name":"Ian Mune","avatar":""},{"name":"Wallace Chapman","avatar":""},{"name":"Mick Innes","avatar":""},{"name":"David Van Horn","avatar":""},{"name":"Nikki Si''ulepa","avatar":""},{"name":"Kitty Riddell","avatar":""},{"name":"Lila Sharp","avatar":""},{"name":"Louise Mills","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
