INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-ngo-ngan', 'Cô Nàng Ngớ Ngẩn', 'She''s Funny That Way', 'https://phimimg.com/upload/vod/20231129-1/978df3cba61f2ef1cc6aa51c86dfb30d.jpg', 'https://phimimg.com/upload/vod/20231129-1/f1439d441184a92ac1614cd25f52326c.jpg', '<p>Cô Nàng Ngớ Ngẩn - She&#39;s Funny That Way xoay quanh Isabella, một nàng “gái gọi” sinh ra ở Brooklyn với khát vọng trở thành diễn viên. Sau cuộc hẹn hò với Arnold Albertson (Owen Wilson) - một biên kịch danh tiếng chuẩn bị ra mắt vở mới trên sân khấu Broadway, cô được đề nghị làm công việc kỳ lạ là vào công viên cho những chú sóc ăn hạnh nhân. Mặc dù Isabella cảm thấy bất ngờ và kỳ quặc, cô vẫn chấp nhận. Nhưng sau đó, một chuỗi sự kiện diễn ra làm thay đổi cuộc sống của tất cả những người cô gặp.</p>', 'Full', 1, 'single', 'completed', 22, 2014, 'Thuyết Minh', 'HD', 'Đức', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Illeana Douglas","avatar":""},{"name":"Richard Lewis","avatar":""},{"name":"Cybill Shepherd","avatar":""},{"name":"Austin Pendleton","avatar":""},{"name":"Tovah Feldshuh","avatar":""},{"name":"George Morfogen","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"Jake Hoffman","avatar":""},{"name":"Jake Lucas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324457);
