INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-tay-trieu-do', 'Cánh Tay Triệu Đô', 'Million Dollar Arm', 'https://phimimg.com/upload/vod/20231129-1/07421de3a01dd59fd0a24b7334e83d55.jpg', 'https://phimimg.com/upload/vod/20231129-1/f581e509d496bc2abe3432df897b1771.jpg', '<p>Trong nỗ lực cuối cùng để cứu vãn sự nghiệp của mình, đặc vụ thể thao JB Bernstein mơ ra một kế hoạch hoang dã để tìm vận động viên ném bóng cừ khôi tiếp theo của Giải bóng chày nhà nghề từ một nhóm người chơi cricket ở Ấn Độ. Anh ấy sớm phát hiện ra hai thanh niên có thể ném bóng nhanh nhưng không biết gì về trò chơi bóng chày. Hoặc Mỹ. Đó là một hành trình đáng kinh ngạc và cảm động sẽ thay đổi tất cả — đặc biệt là JB, người đã học được những bài học quý giá về tinh thần đồng đội, sự cam kết và gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Suraj Sharma","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Madhur Mittal","avatar":""},{"name":"Pitobash","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Bar Paly","avatar":""},{"name":"Al Sapienza","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Allyn Rachel","avatar":""},{"name":"Ravi Naidu","avatar":""},{"name":"Gabriela Lopez","avatar":""},{"name":"Tanner Anderson","avatar":""},{"name":"Tom Verducci","avatar":""},{"name":"Brett Zimmerman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
