INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-gia-hoan-hao', 'Cô Vợ Giả Hoàn Hảo', 'Lock Me Up, Tie Him Down', 'https://phimimg.com/upload/vod/20231125-1/57bcc6aab100deb129e3c5a1d245ab4e.jpg', 'https://phimimg.com/upload/vod/20231125-1/71a88ba3b318ac92594db764c7ce7bea.jpg', '<p>Phim Cô Vợ Giả Hoàn Hảo - Lock Me Up, Tie Him Down 2014: Cô nàng “màu hồng” của “Cơn lốc tình yêu” trở lại với điện ảnh trong vai cô nội trợ Tiffany vì để cứu chồng mà phải giả làm vợ tên bắt cóc chồng cô một tuần. Không khuất phục, cô tìm đủ mọi cách hạ gục hắn, tạo nên nhiều tình huống hài hước khi tên bắt cóc là một kẻ hậu đậu vô cùng.</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vivian Hsu","avatar":""},{"name":"He Jiong","avatar":""},{"name":"Xuebing Wang","avatar":""},{"name":"Cai Xukun","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Frankie Chan Fan-Kei","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Jiang Mengjie","avatar":""},{"name":"Harriet Yeung","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Singh Hartihan Bitto","avatar":""},{"name":"Ruan Xiaowei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
