INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-abu-ghraib', 'Nhà Tù Abu Ghraib', 'Boys of Abu Ghraib', 'https://phimimg.com/upload/vod/20231125-1/a7fc422654756bcf2a45869b0499fa74.jpg', 'https://phimimg.com/upload/vod/20231125-1/5dd5d810e9bae248d5f3279feaa883fc.jpg', '<p>Một người lính Mỹ được triển khai tại Abu Ghraib thấy mình đằng sau những bức tường của Hard Site khét tiếng, nơi anh ta phát triển tình bạn bí mật với một tù nhân người Iraq.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sara Paxton","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"John Heard","avatar":""},{"name":"Elijah Kelley","avatar":""},{"name":"John Robinson","avatar":""},{"name":"Kristen Rakes","avatar":""},{"name":"Omid Abtahi","avatar":""},{"name":"Jermaine Williams","avatar":""},{"name":"Rick Vargas","avatar":""},{"name":"Luke Moran","avatar":""},{"name":"Kurly Tlapoyawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
