INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-dung-tu-than-benh-nhan-dau-tien', 'Trạm Dừng Tử Thần: Bệnh Nhân Đầu Tiên', 'Cabin Fever 3: Patient Zero', 'https://phimimg.com/upload/vod/20231125-1/c18eed209c4f3ad7b0caf28b61f77d20.jpg', 'https://phimimg.com/upload/vod/20231125-1/4c6c91c001b440c9cbb96f890e210f05.jpg', '<p>Một nhóm bạn đến một hòn đảo hoang vắng ở Caribe để dự tiệc độc thân qua đêm đầy bất ngờ và phát hiện ra rằng hòn đảo này không hề bị bỏ hoang. Nó thực sự là nhà của một cơ sở y tế bí mật. Không chỉ vậy, có điều gì đó không ổn với vùng nước xung quanh hòn đảo...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jillian Murray","avatar":""},{"name":"Mitch Ryan","avatar":""},{"name":"Lydia Hearst","avatar":""},{"name":"Claudette Lalí","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Solly Duran","avatar":""},{"name":"Currie Graham","avatar":""},{"name":"Ryan Donowho","avatar":""},{"name":"Brando Eaton","avatar":""},{"name":"Juan ''Papo'' Bancalari","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
