INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoa-uoc-chet-nguoi', 'Thỏa Ước Chết Người', 'Emulsion', 'https://phimimg.com/upload/vod/20231125-1/5ed80fa3cce9eea8124f74fcfded8df7.jpg', 'https://phimimg.com/upload/vod/20231125-1/3b983a6769c75b92b1b448a0b900da55.jpg', '<p>EMULSION kể câu chuyện về một người bán hàng chán nản vô tình bị cuốn vào một âm mưu tống tiền nguy hiểm buộc anh ta phải đấu tranh để giành quyền kiểm soát một cuộc sống mà anh ta chưa bao giờ nghĩ là đáng sống. Vẽ nên một thế giới đen tối trong phim, nơi không có ai giống hệt như vẻ ngoài của họ, Emulsion theo chân Dane Allen khi anh tiến hóa từ một chiếc răng cưa hoàn toàn bị lãng quên thành một nhà hoạt động mạnh mẽ, người mang quyền lực đến đầu gối của họ. Đó là câu chuyện về sự khám phá, thao túng và cuộc đấu tranh không ngừng nghỉ giữa sự tự mãn và sự tự hiện thực hóa.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Claudia Bassols","avatar":""},{"name":"Sam Heughan","avatar":""},{"name":"Lex Shrapnel","avatar":""},{"name":"Mem Ferda","avatar":""},{"name":"David Ajala","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
