INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('2-tang-lop', '2 Tầng Lớp', '2 States', 'https://phimimg.com/upload/vod/20231125-1/c3589b56a55288b106efe529d1ce46f5.jpg', 'https://phimimg.com/upload/vod/20231125-1/13b49af2a0628337da160c805b7e8cf9.jpg', '<p>Một người đàn ông và một người phụ nữ đến từ hai nền văn hóa rất khác nhau và quyết định rằng họ sẽ không kết hôn cho đến khi thuyết phục được cha mẹ. Như đã sợ, sự khác biệt giữa các gia đình đặt ra một rào cản.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Alia Bhatt","avatar":""},{"name":"Arjun Kapoor","avatar":""},{"name":"Amrita Singh","avatar":""},{"name":"Revathi","avatar":""},{"name":"Ronit Roy","avatar":""},{"name":"Shivkumar Subramaniam","avatar":""},{"name":"Aru Krishansh Verma","avatar":""},{"name":"Amit Bhargav","avatar":""},{"name":"Achint Kaur","avatar":""},{"name":"Bikramjeet Kanwarpal","avatar":""},{"name":"Madhu Anand Chandhock","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
