INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-ryan-dac-vu-bong-dem', 'Jack Ryan: Đặc Vụ Bóng Đêm', 'Jack Ryan: Shadow Recruit', 'https://phimimg.com/upload/vod/20231125-1/7737e1e7c42e67e8ea6006862b49204f.jpg', 'https://phimimg.com/upload/vod/20231125-1/e99aff77167ef861bc0d808af172cf08.jpg', '<p>Trong Jack Ryan: Đặc vụ bóng đêm, sau khi chứng kiến qua màn hình cảnh toà tháp đôi New York bị tấn công khủng bố, chàng thanh niên Jack Ryan (Chris Pine) đã &quot;xếp bút nghiên&quot; và tình nguyện ra chiến trường. Trong một lần hành quân, Jack bị thương và phải giải ngũ, mọi chuyện tưởng như chấm dứt thì anh được sĩ quan tình báo CIA Thomas Harper (Kevin Costner) tuyển dụng vào một nhóm tinh nhuệ. Anh được gửi trả lại trường học và đi làm chuyên viên phân tích tài chính ở phố Wall với mục đích theo dõi các khoản tiền của bọn khủng bố. &nbsp;Sau 10 năm làm việc, tình cờ Jack phát hiện ra một âm mưu khủng khiếp nhắm vào thị trường tài chính Mỹ. Anh lên đường sang Nga để kiểm chứng lại giả thuyết của mình. Tuy nhiên, khi đến Nga, Jack Ryan lập tức bị cuốn vào một cuộc chiến đã khiến cho anh không chỉ từ một nhân viên bàn giấy trở thành đặc vụ hành động mà còn ảnh hưởng cả đến người tình xinh đẹp Cathy Muller (Keira Knightley) của mình.</p>', 'Full', 1, 'single', 'completed', 23, 2014, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Lenn Kudrjawizki","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Alec Utgoff","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Aleksandar Aleksiev","avatar":""},{"name":"Deborah Rosan","avatar":""},{"name":"Price Lindsey","avatar":""},{"name":"Celine Jedidi","avatar":""},{"name":"Ricky Rajpal","avatar":""},{"name":"Karen David","avatar":""},{"name":"David Paymer","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
