INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-am-hon-nhan', 'Quỷ Ám Hôn Nhân', 'Something Wicked', 'https://phimimg.com/upload/vod/20231125-1/86f86be3212ef528c5d6abbab08a1dcc.jpg', 'https://phimimg.com/upload/vod/20231125-1/44812bc619884cbf2b0755113130bdb1.jpg', '<p>Một cặp vợ chồng trẻ bắt đầu hưởng tuần trăng mật trước những cảnh quan lạnh giá của Tây Bắc Thái Bình Dương. Nhưng khi bi kịch ập đến, những bí mật khủng khiếp từ quá khứ của họ va chạm với những thế lực độc ác của hiện tại...</p>', 'Full', 1, 'single', 'completed', 7, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shantel VanSanten","avatar":""},{"name":"John Robinson","avatar":""},{"name":"James Patrick Stuart","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Robert Blanche","avatar":""},{"name":"Betty Moyer","avatar":""},{"name":"Broderick Boyd","avatar":""},{"name":"John Breen","avatar":""},{"name":"Jerry L. Buxbaum","avatar":""},{"name":"Joe Feeney","avatar":""},{"name":"Jeff Hunter","avatar":""},{"name":"Megan Lee Joy","avatar":""},{"name":"Patricia Malley Thacher","avatar":""},{"name":"Gilberto Martin del Campo","avatar":""},{"name":"Julian Morris","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
