INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-pompeii', 'Thảm Họa Pompeii', 'Pompeii', 'https://phimimg.com/upload/vod/20231123-1/63a03698766e4fe7c6829b5caf88a8af.jpg', 'https://phimimg.com/upload/vod/20231123-1/83f3edd0b1ccab8bea10a653ba84107e.jpg', '<p>Lấy bối cảnh năm 79 sau công nguyên, “Pompeii” là câu chuyện huyền thoại về Milo (Kit Harington thủ vai), một nô lệ bị biến thành dũng sĩ giác đấu bất khả chiến bại phải chạy đua với thời gian để cứu lấy người anh yêu, Cassia (Emily Browning), cô con gái trẻ đẹp của một lái buôn giàu có bị ép hứa hôn với một tên nghị sĩ La Mã đồi bại. Và khi đỉnh núi lửa Vesuvius phun trào dòng dung nham nóng bỏng, Milo phải tìm cách thoát ra ngoài đấu trường để cứu người anh yêu giữa thành Pompeii đang sụp đổ tan tành... Sử dụng bối cảnh của một trong những thảm họa núi lửa kinh hoàng nhất trong lịch sử, “Pompeii” lần này sẽ kể về một đấu sĩ nô lệ người Celtic, người đã đem lòng yêu một người phụ nữ quý tộc. Câu chuyện xảy ra trong chính cái đêm định mệnh khi ngọn đại hỏa sơn Vesuvius phun trào và chôn vùi toàn bộ thành phố cảng xinh đẹp trong chớp mắt. Tréo ngoe thay, vào chính thời khắc sinh tử ấy, chàng dũng sĩ giác đấu lại mặt đối mặt với kẻ thù đã giết chết gia đình mình nhiều năm trước đây.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kit Harington","avatar":""},{"name":"Emily Browning","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"Sasha Roiz","avatar":""},{"name":"Currie Graham","avatar":""},{"name":"Joe Pingue","avatar":""},{"name":"Ron Kennell","avatar":""},{"name":"Rebecca Eady","avatar":""},{"name":"Jean Frenette","avatar":""},{"name":"Dylan Schombing","avatar":""},{"name":"Maxime Savaria","avatar":""},{"name":"Tom Bishop Sr.","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
