INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-trai-dat', 'Ngoài Trái Đất', 'Extraterrestrial', 'https://phimimg.com/upload/vod/20231123-1/d367b14f722d5cb6b4ea09e1401d0bf0.jpg', 'https://phimimg.com/upload/vod/20231123-1/5f2d26d2cd475bdba1e894a0039af5d9.jpg', '<p>Năm người bạn đến một căn nhà gỗ trong rừng để tận hưởng kỳ nghỉ cuối tuần thú vị, cho đến khi những vị khách ngoài trái đất biến nó thành một cuộc chiến giành giật mạng sống của họ. Cả nhóm bị kéo ra khỏi giấc mơ khi một vật thể nhấp nháy rơi sâu trong rừng. Khi họ điều tra, những người bạn tình cờ bắt gặp một con tàu vũ trụ của người ngoài hành tinh và cư dân của nó đã không đến nơi bình yên.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brittany Allen","avatar":""},{"name":"Melanie Papalia","avatar":""},{"name":"Jesse Moss","avatar":""},{"name":"Anja Savcic","avatar":""},{"name":"Sean Rogerson","avatar":""},{"name":"Emily Perkins","avatar":""},{"name":"Mike Kovac","avatar":""},{"name":"Ian Brown","avatar":""},{"name":"Fred Keating","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Freddie Stroma","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"Reese Alexander","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324457);
