INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-xau-xa', 'Vùng Đất Xấu Xa', 'Bad Country', 'https://phimimg.com/upload/vod/20231120-1/bddd7b85a0a595278491122b53ce2946.jpg', 'https://phimimg.com/upload/vod/20231120-1/db187671122508288bcef95b3546b1f3.jpg', '<p>Khi thám tử Bud Carter của cảnh sát Baton Rouge bắt giữ kẻ giết người theo hợp đồng Jesse Weiland, anh thuyết phục Jesse trở thành người cung cấp thông tin và triệt phá đường dây tội phạm mạnh nhất miền Nam.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Dillon","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"Don Yesso","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Bill Duke","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Christopher Denham","avatar":""},{"name":"Alex Solowitz","avatar":""},{"name":"John Edward Lee","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"Frederick Weller","avatar":""},{"name":"Patrick Brinker","avatar":""},{"name":"Jeff Leaf","avatar":""},{"name":"Pat Fishe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324457);
