INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-one', 'Song One', 'Song One', 'https://phimimg.com/upload/vod/20231120-1/144b15416b348ed94c15a4051077d9f5.jpg', 'https://phimimg.com/upload/vod/20231120-1/28cb22205541bd8567f9e535d35ddb0a.jpg', '<p>Estranged từ gia đình cô, Franny trở về nhà khi một tai nạn khiến anh trai cô hôn mê. Lấy cuộc sống của mình như một nhạc sĩ đầy tham vọng, cô ấy đã theo dõi nhạc sĩ yêu thích của mình, James Forester. Chống lại bối cảnh âm nhạc của Brooklyn, Franny và James phát triển một mối quan hệ bất ngờ và đối mặt với thực tế cuộc sống của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Johnny Flynn","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Ben Rosenfield","avatar":""},{"name":"Lola Kirke","avatar":""},{"name":"Gideon Glick","avatar":""},{"name":"Al Thompson","avatar":""},{"name":"Jessamine Kelley","avatar":""},{"name":"Cass Dillon","avatar":""},{"name":"Sarah Steele","avatar":""},{"name":"Li Jun Li","avatar":""},{"name":"Kitty Crystal","avatar":""},{"name":"Grace Rex","avatar":""},{"name":"Roderick Hill","avatar":""},{"name":"Shawn Parsons","avatar":""},{"name":"Peter Francis James","avatar":""},{"name":"Katrina E. Perkins","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
