INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-co-gai-huyet-chien', 'Các Cô Gái Huyết Chiến', 'Girl''s Blood', 'https://phimimg.com/upload/vod/20231120-1/526f8b042e630ddfb5f40b7d03149a76.jpg', 'https://phimimg.com/upload/vod/20231120-1/ec36688ee1b08e58abee887e25a3107b.jpg', '<p>&quot;Girl&quot;s Blood (赤 × ピ ン ク, Aka x Pinku ) là bộ phim hành động khiêu dâm năm 2014 của Nhật do Koichi Sakamoto đạo diễn và Takehiko Minato viết kịch bản. Phim dựa trên tiểu thuyết Aka × Pink của Kazuki Sakuraba.
 Bốn cô gái tham gia vào các trận đấu ngầm bất hợp pháp &quot;Girl&quot;s Blood&quot; được tổ chức tại một tòa nhà bỏ hoang ở Roppongi mỗi đêm. Các cô gái có những câu chuyện riêng và những điều kỳ quặc từ cuộc sống riêng tư của họ. Satsuki (Yuria Haga) mắc chứng rối loạn nhận dạng giới tính, Chinatsu (Asami Tada) chạy trốn khỏi người chồng bạo hành, Miko (Ayame Misaki) là nữ hoàng S&amp;M và Mayu (Rina Koike) có khuôn mặt Lolita.”</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuria Haga","avatar":""},{"name":"Asami Tada","avatar":""},{"name":"Ayame Misaki","avatar":""},{"name":"Rina Koike","avatar":""},{"name":"Haruka Oshima","avatar":""},{"name":"Sanae Hitomi","avatar":""},{"name":"Misaki Momose","avatar":""},{"name":"Rina Sakuragi","avatar":""},{"name":"Yukiko Suo","avatar":""},{"name":"Christoph Mulai","avatar":""},{"name":"Shou Nishino","avatar":""},{"name":"Chris Mulai","avatar":""},{"name":"Christopher Mulai","avatar":""},{"name":"Christophe Mulai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324457);
