INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tay-cua-quy', 'Bàn Tay Của Quỷ', 'Where the Devil Hides', 'https://phimimg.com/upload/vod/20231120-1/d046a019ab6d161f9020f698cd199bea.jpg', 'https://phimimg.com/upload/vod/20231120-1/50c0fd5d65bb2c83614755cf1ca98003.jpg', '<p>Năm cô gái trẻ Amish bị buộc tội là con của Satan phải chiến đấu để giành lấy mạng sống của mình khi những người lớn tuổi trong cộng đồng sùng đạo của họ khăng khăng rằng họ phải được &quot;tẩy rửa&quot; trước khi bước sang tuổi 18.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rufus Sewell","avatar":""},{"name":"Alycia Debnam-Carey","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Leah Pipes","avatar":""},{"name":"Thomas McDonell","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Jim McKeny","avatar":""},{"name":"Katie Garfield","avatar":""},{"name":"Ric Reitz","avatar":""},{"name":"Ethan Alexander McGee","avatar":""},{"name":"Jon Stafford","avatar":""},{"name":"Jane McNeill","avatar":""},{"name":"Holli Saperstein","avatar":""},{"name":"Stacy Rabon","avatar":""},{"name":"Robin Dale Robertson","avatar":""},{"name":"Nicole Elliot","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
