INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('petals-on-the-wind', 'Petals on the Wind', 'Petals on the Wind', 'https://phimimg.com/upload/vod/20231201-1/7df60616a12620ce75dbb6a7aa186906.jpg', 'https://phimimg.com/upload/vod/20231201-1/7586251bee6c6bed27604aa860526f32.jpg', '<p>Một thập kỷ sau Cathy, Christopher và Carrie đã trốn thoát khỏi căn gác của ông bà của họ tại Hội trường Foxworth, những cánh hoa trên gió tiếp tục theo dõi các hoàn cảnh xoắn của gia đình khi họ cố gắng đặt quá khứ bẩn thỉu của họ, nhưng sớm khám phá những bí mật nhất định có thể &#39; t bị bỏ lại phía sau. Khi Cathy tìm thấy mình trong một mối quan hệ lạm dụng với một vũ công đồng nghiệp, Julian, Christopher và Cathy buộc phải đối mặt với những cảm xúc bị cấm mà họ đã phát triển vì một người trong thời gian bị giam cầm. Nhưng khi Bi kịch tấn công Dollangangers một lần nữa, Cathy trở lại Hội trường Foxworth để đối đầu với bà của cô và tìm cách trả thù mẹ với một kế hoạch để quyến rũ chồng bart. Khi Christopher chạy đến bên của Cathy, hai người quyết tâm bắt đầu lại - cùng nhau.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heather Graham","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"Rose McIver","avatar":""},{"name":"Wyatt Nash","avatar":""},{"name":"Bailey De Young","avatar":""},{"name":"Whitney Hoy","avatar":""},{"name":"Dylan Bruce","avatar":""},{"name":"Will Kemp","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Ravil Isyanov","avatar":""},{"name":"Stephanie Kim","avatar":""},{"name":"Molly Hagan","avatar":""},{"name":"Ross Philips","avatar":""},{"name":"Jesse Einstein","avatar":""},{"name":"Ellia English","avatar":""},{"name":"John Paul Green","avatar":""},{"name":"Megan Easton","avatar":""},{"name":"Kathryn Leigh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
