INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguon-goc', 'Nguồn Gốc', 'I Origins', 'https://phimimg.com/upload/vod/20231201-1/b67ba8ff42b85cb5477211b323f4d582.jpg', 'https://phimimg.com/upload/vod/20231201-1/29a9fa843764f570ab9259ff6d42b054.jpg', '<p>I ORIGINS : Trong phim, Ian Gray là một tiến sĩ trẻ chuyên về mắt, anh có sở thích đặc biệt với các đôi mắt bởi theo Ian thì 7 tỉ người trên thế giới không ai có đôi mắt giống ai, tất cả đều là duy nhất và có bộ sưu tập ảnh chụp chất lượng cao hàng ngàn đôi mắt của nhiều người khác nhau. Ian và 2 cộng sự là Kenny và Karen đang theo đuổi dự án hết sức táo bạo: tìm ra tế bào gốc qui định loài động vật đó có mắt hay không, từ đó thí nghiệm lai tạo loài giun đất có mắt.Trong thế giới của I Origins, người ta đang thực hiện dự án scan mống mắt của mọi người để làm dữ liệu nhận dạng cá nhân, tương tự như vân tay và Ấn Độ là một trong những quốc gia đi đầu về dự án này.Một ngày kia, Ian tình cờ gặp Sofi và bị cuốn hút bởi ...</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Pitt","avatar":""},{"name":"Brit Marling","avatar":""},{"name":"Astrid Bergès-Frisbey","avatar":""},{"name":"Steven Yeun","avatar":""},{"name":"Archie Panjabi","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Venida Evans","avatar":""},{"name":"William Mapother","avatar":""},{"name":"Kashish","avatar":""},{"name":"Dorien Makhloghi","avatar":""},{"name":"Charles W. Gray","avatar":""},{"name":"Johns Schiumo","avatar":""},{"name":"Farasha Baylock","avatar":""},{"name":"Ako","avatar":""},{"name":"Christopher Santamaria","avatar":""},{"name":"Sebastian Santamaria","avatar":""},{"name":"Rh","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
