INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-cong-ngam', 'Sát Nhân Cống Ngầm', 'Manhole', 'https://phimimg.com/upload/vod/20231201-1/ad7f32f4d23f9a2ca24ef1cf0c7b8bed.jpg', 'https://phimimg.com/upload/vod/20231201-1/6db64fe8338e1e7909b9d09961a1f1ec.jpg', '<p>Bộ phim kể về việc một cô gái trẻ (do Kim Sae Ron đóng) bị bắt cóc bởi một tên sát nhân nguy hiểm chuyên dùng lỗ cống để bắt và giết nạn nhân. Chị gái cô (do Jung Yu Mi thủ vai) cố gắng tìm ra và cứu thoát cô trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Yu-mi","avatar":""},{"name":"Kim Sae-ron","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Lee Young-yoo","avatar":""},{"name":"Yoon Chan-young","avatar":""},{"name":"Kim Bin-woo","avatar":""},{"name":"Yoon Don-sun","avatar":""},{"name":"Jun Yoon-ji","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
