INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuan-trang-mat-kinh-hoang', 'Tuần Trăng Mật Kinh Hoàng', 'Honeymoon', 'https://phimimg.com/upload/vod/20231116-1/42121f452c7994602e09fda946781eb0.jpg', 'https://phimimg.com/upload/vod/20231116-1/cd9794e9dfc5d77d65da4173ea8dcde3.jpg', '<p>Cặp vợ chồng trẻ mới cưới Paul và Bea đi du lịch đến một ngôi nhà nhỏ ven hồ xa xôi để hưởng tuần trăng mật, nơi hứa hẹn về mối tình lãng mạn riêng tư đang chờ đợi họ. Ngay sau khi đến nơi, Paul thấy Bea đang lang thang và mất phương hướng vào lúc nửa đêm.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rose Leslie","avatar":""},{"name":"Harry Treadaway","avatar":""},{"name":"Ben Huber","avatar":""},{"name":"Hanna Brown","avatar":""},{"name":"Bob Harrison","avatar":""},{"name":"John Lauterbach","avatar":""},{"name":"Peter Leo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324457);
