INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguong-cua-vao-doi', 'Ngưỡng Cửa Vào Đời', 'Premature', 'https://phimimg.com/upload/vod/20231116-1/ee6af3e482b2621043ad5551ac9ae0bf.jpg', 'https://phimimg.com/upload/vod/20231116-1/75846ef87ffbc3e89a09b86649c51ffc.jpg', '<p>Vào ngày quan trọng nhất trong cuộc đời tuổi trẻ của mình, một học sinh trung học buộc phải hồi tưởng lại lần thất bại trong việc đánh mất trinh tiết của mình hết lần này đến lần khác cho đến khi anh ta làm đúng.</p>', 'Full', 1, 'single', 'completed', 8, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Karna","avatar":""},{"name":"Katie Findlay","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Carlson Young","avatar":""},{"name":"Zoe Myers","avatar":""},{"name":"Elon Gold","avatar":""},{"name":"Cara Mantella","avatar":""},{"name":"Christen Orr","avatar":""},{"name":"Brian Huskey","avatar":""},{"name":"Kate Kneeland","avatar":""},{"name":"Katie Adkins","avatar":""},{"name":"Nickolas Wolf","avatar":""},{"name":"Caroline Traywick","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
