INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguong-cua-vao-doi', 'Ngưỡng Cửa Vào Đời', 'Premature', 'ngưỡng cửa vào đời premature john karna katie findlay craig roberts alan tudyk carlson young zoe myers elon gold cara mantella christen orr brian huskey kate kneeland katie adkins nickolas wolf caroline traywick ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-hoc-duong-2', 'Cớm Học Đường 2', '22 Jump Street', 'https://phimimg.com/upload/vod/20231116-1/b259d4d2ae59562ec77c9692ffc67141.jpg', 'https://phimimg.com/upload/vod/20231116-1/c8a4a45056bedae44744499751f76d5a.jpg', '<p>Sau khi hai anh chàng cảnh sát hậu đậu thành công trong việc phá vỡ mạng lưới buôn bán ma túy tại trường trung học, cơ hội lớn đã đến và cả hai đươc cử đi nằm vùng tại một trường đại học tư ở địa phương vì các sếp thấy rằng Jenko và Schmidt đã quá “dữ” để tiếp tục làm học sinh cấp 3. &nbsp;Tương tự lần trước, hai anh “cớm” tiếp tục thâm nhập và điều tra về một đường dây buôn ma tuý tinh vi và nguy hiểm, nhất là khi nó đã gây ra cái chết của một sinh viên. Những tưởng đã thành thục hơn sau phi vụ đầu, nhưng Jenko và Schmidt lại vấp phải nhiều thử thách khó nhằn hơn khi cuộc điều tra đi vào ngõ cụt và hai nhân vật mới xuất hiện đe doạ “mối quan hệ” của đôi bạn hoàn cảnh. Một bên là anh chàng cầu thủ bóng bầu dục Zook vô cùng hợp cạ với Jenko, một bên là cô bạn gái ngọt ngào Maya hút hồn Schmidt từ phút đầu tiên.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonah Hill","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Amber Stevens West","avatar":""},{"name":"Jillian Bell","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Keith Lucas","avatar":""},{"name":"Kenneth Lucas","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Jimmy Tatro","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Marc Evan Jackson","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Eddie J. Fernandez","avatar":""},{"name":"Rye Rye","avatar":""},{"name":"Johnn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324457);
