INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-ton-noi-hoang-dao', 'Sinh Tồn Nơi Hoang Đảo', 'Eden', 'https://phimimg.com/upload/vod/20231120-1/4b59f2f5326eefb0b923bee6f1716c99.jpg', 'https://phimimg.com/upload/vod/20231120-1/932cce18dd944ab8a471e331776fc0a6.jpg', '<p>Paul, một thiếu niên sống trong thế giới ngầm của Paris đầu những năm 1990, thành lập một nhóm DJ với bạn bè của mình và họ cùng nhau lao vào cuộc sống về đêm của tình dục, ma túy và âm nhạc bất tận.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Félix de Givry","avatar":""},{"name":"Pauline Étienne","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Hugo Conzelmann","avatar":""},{"name":"Zita Hanrot","avatar":""},{"name":"Roman Kolinka","avatar":""},{"name":"Ugo Bienvenu","avatar":""},{"name":"Vincent Lacoste","avatar":""},{"name":"Arnaud Azoulay","avatar":""},{"name":"Laurent Cazanave","avatar":""},{"name":"Paul Spera","avatar":""},{"name":"Arsinée Khanjian","avatar":""},{"name":"Juliette Lamet","avatar":""},{"name":"Greta Gerwig","avatar":""},{"name":"Léa Rougeron","avatar":""},{"name":"Laura Smet","avatar":""},{"name":"Golshift","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324457);
