INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-nhan-loai', 'Thảm Họa Nhân Loại', 'Zodiac', 'https://phimimg.com/upload/vod/20231119-1/eae2f7d5eff3771d2b585359bab76fa5.jpg', 'https://phimimg.com/upload/vod/20231119-1/a10a03204e84e11900eaf71c72fc15d6.jpg', '<p>Thảm họa toàn cầu bắt đầu xảy ra sau khi các nhà khảo cổ khai quật được một hiện vật chiêm tinh 2.000 năm tuổi. Một nhà khoa học lừa đảo là chìa khóa để giải mã cổ vật nhằm ngăn chặn ngày tận thế.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Joel Gretsch","avatar":""},{"name":"Aaron Douglas","avatar":""},{"name":"Reilly Dolman","avatar":""},{"name":"Emily Holmes","avatar":""},{"name":"Andrea Brooks","avatar":""},{"name":"Ben Cotton","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Doug Chapman","avatar":""},{"name":"Russell Roberts","avatar":""},{"name":"Raf Rogers","avatar":""},{"name":"Wolfgang Klassen","avatar":""},{"name":"Jessica Storm Smith","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324457);
