INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-dai', 'Hoang Dại', 'Wild Tales', 'https://phimimg.com/upload/vod/20231119-1/0d56f57a63f2aa13de343ec8eef11eac.jpg', 'https://phimimg.com/upload/vod/20231119-1/6293830e3d8820fbe9973852d9b66c93.jpg', '<p>Phim Wild Tales gồm 6 câu chuyện nhỏ bên trong, hoàn toàn không liên quan tới nhau: Trên một chuyến bay, Trong một quán ăn, Trên một cung đường vắng, Câu chuyện về việc đậu xe dưới lòng đường, Tai nạn giao thông và Đêm đám cưới. 6 câu chuyện được bắt đầu và kết thúc bằng một cách riêng, nó nói về những mâu thuẫn bên trong của những con người được kể tới, những tức giận, uất ức bị dồn nén giống như trái bóng cứ liên tục được bơm lên, để tới lúc nó nổ tung vì quá tải.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Ricardo Darín","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Érica Rivas","avatar":""},{"name":"Oscar Martínez","avatar":""},{"name":"Rita Cortese","avatar":""},{"name":"Julieta Zylberberg","avatar":""},{"name":"Darío Grandinetti","avatar":""},{"name":"María Marull","avatar":""},{"name":"Mónica Villa","avatar":""},{"name":"César Bordón","avatar":""},{"name":"Walter Donado","avatar":""},{"name":"Nancy Dupláa","avatar":""},{"name":"Luis Mazzeo","avatar":""},{"name":"María Onetto","avatar":""},{"name":"Osmar Núñez","avatar":""},{"name":"Germán de Silva","avatar":""},{"name":"Diego Velá","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
