INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-me-ngu-ngon-2014', 'Chúc Mẹ Ngủ Ngon', 'Goodnight Mommy', 'https://phimimg.com/upload/vod/20231113-1/8e506b8cad15ce82568ab5a2f8d7874c.jpg', 'https://phimimg.com/upload/vod/20231113-1/c5e81e2df03a81101b7137d9730decfc.jpg', '<p>Tại một vùng nông thôn nọ tách biệt khỏi thế giới bên ngoài, có một ngôi nhà nhỏ. Ngôi nhà ấy là nơi sinh sống của hai anh em sinh đôi và người mẹ của chúng. Ngày ngày hai anh em cùng nhau lang thang trong những cánh rừng, khu nghĩa địa bỏ hoang hay cánh đồng ngô rộng lớn, trong khi mẹ chúng chìm đắm trong một thế giới xa xôi nào đó giữa những lớp băng gạc quấn kín khuôn mặt khi trở về nhà sau ca phẫu thuật. Hai anh em bắt đầu cho rằng người phụ nữ kia chính là một kẻ khác đang ăn cắp hình hài của mẹ chúng. Rồi một ngày nọ, lũ trẻ bước đến hỏi bà ta: “Mẹ của bọn tôi đang ở đâu?”...</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Áo', 0, '[{"name":"Elias Schwarz","avatar":""},{"name":"Lukas Schwarz","avatar":""},{"name":"Susanne Wuest","avatar":""},{"name":"Hans Escher","avatar":""},{"name":"Elfriede Schatz","avatar":""},{"name":"Karl Purker","avatar":""},{"name":"Georg Deliovsky","avatar":""},{"name":"Christian Steindl","avatar":""},{"name":"Christian Schatz","avatar":""},{"name":"Erwin Schmalzbauer","avatar":""},{"name":"Michael Ande","avatar":""},{"name":"Ruth Leuwerik","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324457);
