INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyet-yeu-thuong', 'Thuyết Yêu Thương', 'The Theory of Everything', 'https://phimimg.com/upload/vod/20231118-1/21954f9e162f8936188ae8921d99fc09.jpg', 'https://phimimg.com/upload/vod/20231118-1/fc22a889240a2ffc6436c4f94d577528.jpg', '<p>Dựa trên cuốn hồi ký của bà Jane Hawking, bộ phim tâm lý tình cảm được 5 đề cử Oscar 2015 là một trong những tác phẩm hút nước mắt khán giả nhất năm qua.Năm 2002, A Beautiful Mind - bộ phim về cuộc đời nhà bác học John Nash của thế kỷ 20 - chiến thắng thuyết phục với 4 tượng vàng Oscar. Trong niềm ngưỡng mộ dành cho một trí tuệ siêu phàm, một tâm hồn cao đẹp cùng tâm huyết của đoàn làm phim, không ít người đã tiên đoán, sẽ có ngày Hollywood vinh danh Stephen Hawking - người khổng lồ của khoa học thế kỷ 21 như thế. The Theory of Everything, ra đời hơn một thập kỷ sau, đã biến những lời dự đoán cũng như niềm mong mỏi của khán giả yêu điện ảnh thành hiện thực.Đây không phải là bộ phim đầu tiên lấy cảm hứng về Stephen Hawking. ...</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Eddie Redmayne","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Charlie Cox","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Maxine Peake","avatar":""},{"name":"Harry Lloyd","avatar":""},{"name":"Tom Prior","avatar":""},{"name":"Sophie Perry","avatar":""},{"name":"Finlay Wright-Stephens","avatar":""},{"name":"Alice Orr-Ewing","avatar":""},{"name":"Thomas Morrison","avatar":""},{"name":"Michael Marcus","avatar":""},{"name":"Gruffudd Glyn","avatar":""},{"name":"Paul Longley","avatar":""},{"name":"Guy Oliver","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324457);
