INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-chu-lun', 'Bảy Chú Lùn', 'Der 7bte Zwerg', 'https://phimimg.com/upload/vod/20231118-1/de6e1f659c074de4054fb8aa846d00ca.jpg', 'https://phimimg.com/upload/vod/20231118-1/89b0afc2bede384a1e3a0d8b0430bfb4.jpg', '<p>Bảy chú lùn vụng về cố gắng hóa giải câu thần chú mà họ vô tình giải phóng và cứu thế giới cổ tích với sự giúp đỡ của một con rồng mệt mỏi và một con bướm. Phù thủy độc ác Dellamorta đã nguyền rủa công chúa Rose khi cô còn bé. Trước khi tròn 18 tuổi, Rose sẽ bị một vật sắc nhọn đâm vào ngón tay và cô cùng cả lâu đài sẽ chìm vào giấc ngủ dài trăm năm trừ khi tình yêu đích thực của cô hôn cô. Vào đêm trước ngày sinh nhật của mình, cô ấy gửi bạn trai Jack của mình cho 7 chú lùn, những người sống sau 7 ngọn núi để ẩn náu cho đến khi Rose tròn 18 tuổi. Thật không may, anh ấy bị lạc và bị bắt bởi con rồng Burner của Dellamorta. Vì vậy, tại bữa tiệc, Rose bị đốt vào ngón tay và mọi người chìm vào giấc ngủ sâu. Tất cả mọi người, trừ 7 chú lùn, tất nhiên là những người sẽ lên đường cứu Jack để anh có thể cứu Rose.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2014, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Otto Waalkes","avatar":""},{"name":"Mirco Nontschew","avatar":""},{"name":"Boris Aljinovic","avatar":""},{"name":"Ralf Schmitz","avatar":""},{"name":"Gustav Peter Wöhler","avatar":""},{"name":"Martin Schneider","avatar":""},{"name":"Norbert Heisterkamp","avatar":""},{"name":"Nina Hagen","avatar":""},{"name":"Christian Brückner","avatar":""},{"name":"Henning Nöhren","avatar":""},{"name":"Peter Weck","avatar":""},{"name":"Sascha Grammel","avatar":""},{"name":"Das Bo","avatar":""},{"name":"Leonhard Mahlich","avatar":""},{"name":"Mia Diekow","avatar":""},{"name":"Cosma Shiva Hagen","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324457);
