INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-thu-uy-ho-son', 'Trí Thủ Uy Hổ Sơn', 'The Taking Of Tiger Mountain', 'https://phimimg.com/upload/vod/20231117-1/f34809361333f75cef32986fdbd9049c.jpg', 'https://phimimg.com/upload/vod/20231117-1/bafd5c199d337ecf8910da60763164f5.jpg', '<p>Trí Thủ Uy Hổ Sơn - The Taking Of Tiger Mountain: Mùa đông năm 1947, phân đội 203 thuộc liên quân Dân chủ Đông Bắc dưới sự chỉ huy của thủ trưởng Thiếu Kiếm Ba (Lâm Canh Tân đóng), tiếp nhận mệnh lệnh của thượng cấp bảo vệ an toàn cho dân chúng khỏi nạn cướp bóc hoành hành trên cánh đồng tuyết Lâm Hải. Để triệt phá hoàn toàn thế lực của thổ phỉ, Dương Tử Vinh khăng khăng đề nghị cải trang trà trộn vào hang ổ của thổ phỉ: núi Uy Hổ. Trải qua rất nhiều thử thách, mạo hiểm truyền tin tình báo cho các chiến hữu ở dưới núi. Đám thổ phị bị phân đội 203 bắt sống. Dương Tử Vinh và các chiến hữu trong phân đội 203 đón nhận thời cơ tốt nhất để tiêu diệt và thu lưới, khó có thể tránh khỏi một trận chiến ác liệt...</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Hanyu","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Lin Gengxin","avatar":""},{"name":"Yu Nan","avatar":""},{"name":"Han Geng","avatar":""},{"name":"Tse Miu","avatar":""},{"name":"Chen Xiao","avatar":""},{"name":"Zha Ka","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Cheng Si-Han","avatar":""},{"name":"Xiao Yi","avatar":""},{"name":"Wang Yao","avatar":""},{"name":"Yang Yiwei","avatar":""},{"name":"Kui Zhou","avatar":""},{"name":"Lü Zhong","avatar":""},{"name":"Wu Xudong","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Hai Yitian","avatar":""},{"name":"Li Bingyuan","avatar":""},{"name":"Cao Zhanyong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324457);
