INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-con-lai', 'Những người còn lại', 'The Remaining', 'https://phimimg.com/upload/vod/20231116-1/67938dc70d89f1432faed68231e1db05.jpg', 'https://phimimg.com/upload/vod/20231116-1/411c69832d9b961c6c0fac657dd74a38.jpg', '<p>Khi những biến cố và thế lực ma quỉ báo hiệu cho sự phán xét của thần linh, nhóm khách dự đám cưới còn lại phải chạy thoát thân – và quyết định số phận của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexa PenaVega","avatar":""},{"name":"Johnny Pacar","avatar":""},{"name":"Shaun Sipos","avatar":""},{"name":"Italia Ricci","avatar":""},{"name":"Bryan Dechart","avatar":""},{"name":"Liz E. Morgan","avatar":""},{"name":"John Pyper-Ferguson","avatar":""},{"name":"Kim Pacheco","avatar":""},{"name":"Hayley Lovitt","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
