INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-kingsman-2014', 'Mật Vụ Kingsman', 'Kingsman: The Secret Service', 'https://phimimg.com/upload/vod/20231115-1/4cce5070c53191bc9ece663742da4166.jpg', 'https://phimimg.com/upload/vod/20231115-1/a99fb31e79b6f218a63ae0609133df7e.jpg', '<p>Bộ phim kể về một tổ chức điệp viên siêu đẳng sử dụng vũ khí công nghệ cao để chống lại ác nhân Richmond Valentine, một tỷ phú thiên tài với âm mưu xóa sổ phần lớn dân cư trên trái đất để thanh lọc thành một thế giới mới theo ý của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Sophie Cookson","avatar":""},{"name":"Sofia Boutella","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Samantha Womack","avatar":""},{"name":"Jonno Davies","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Adrian Quinton","avatar":""},{"name":"Alex Nikolov","avatar":""},{"name":"Velibor Topic","avatar":""},{"name":"Geoff Bell","avatar":""},{"name":"Jordan Long","avatar":""},{"name":"Theo Barklem-Biggs","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324457);
