INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-vo-sinh-tu', 'Đấu Võ Sinh Tử', 'Die Fighting', 'https://phimimg.com/upload/vod/20231117-1/1c1e8278f232efbe9672ef256111b486.jpg', 'https://phimimg.com/upload/vod/20231117-1/15575708ba574a9fb27497ea7fbe04c2.jpg', '<p>Khi một nhóm các diễn viên kung fu được đào tạo theo trường phái Thiếu Lâm chuẩn bị nghỉ ngơi ở Hollywood, một Giám đốc bí ẩn và tàn bạo buộc họ phải chạy một trận so găng qua Los Angeles. Giám đốc ghi lại mọi hành động của họ khi họ chứng minh sức mạnh của mình bằng cách khiêu khích phòng trưng bày của những tên côn đồ thế giới ngầm và võ sĩ.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fabien Garcia","avatar":""},{"name":"Laurent Buson","avatar":""},{"name":"Didier Buson","avatar":""},{"name":"Jess Allen","avatar":""},{"name":"Dave Vescio","avatar":""},{"name":"Adelyne Liu","avatar":""},{"name":"Xin Sarith Wuku","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324457);
