INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dabbe-5-loi-nguyen-quy-du', 'Dabbe 5: Lời nguyền quỷ dữ', 'Dabbe 5: Curse of the Jinn', 'https://phimimg.com/upload/vod/20231116-1/58307a0ef760f8a0cd7d7fe8fa721c67.jpg', 'https://phimimg.com/upload/vod/20231116-1/b1cee4d3a93d9e5f03a2e703dd4f2054.jpg', '<p>Khi bị ám ảnh bởi những linh hồn xấu xa và mất khả năng kiểm soát cơ thể của chính mình, Dilek nhờ đến một phụ nữ có những bí mật đen tối để chữa trị cho mình.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Nil Günal","avatar":""},{"name":"Ümit Bulent Dincer","avatar":""},{"name":"Sultan Köroğlu Kiliç","avatar":""},{"name":"Özbek Yıldız","avatar":""},{"name":"Pelin Acar","avatar":""},{"name":"Murat Seviş","avatar":""},{"name":"Kubra Bayraktar","avatar":""},{"name":"Elçin Atamgüç","avatar":""},{"name":"Ömer Duran","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
