INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-chuyen-3-ai-la-jon-galt', 'Rung Chuyển 3: Ai Là Jon Galt', 'Atlas Shrugged Part III: Who Is John Galt?', 'https://phimimg.com/upload/vod/20231116-1/50cdfa0b6086452a4e96d56633a74aef.jpg', 'https://phimimg.com/upload/vod/20231116-1/fd3d37206616fd11772b1d7dd9ec9502.jpg', '<p>Rung Chuyển 3: Ai Là Jon Galt - Atlas Shrugged Part III là bộ phim nói về câu chuyện khi nền kinh tế quốc gia đang đi đến bờ vực sụp đổ. Khi tội ác và nỗi sợ hãi bao trùm khắp nơi thì chính phủ lại sử dụng toàn bộ nguồn lực để chống lại một thế lực kì bí khác, để lại đằng sau sự tuyệt vọng của người dân. Chỉ có một người có thể chấm dứt chuyện này. Một số người sẽ tìm mọi cách để kiểm soát anh ta. Số khác sẽ cố gắng cứu sống anh ta. Bọn họ thề sẽ tìm được anh ta. Vậy, John Galt là ai?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristoffer Polaha","avatar":""},{"name":"Laura Regan","avatar":""},{"name":"Greg Germann","avatar":""},{"name":"Eric Allan Kramer","avatar":""},{"name":"Tony Denison","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Peter MacKenzie","avatar":""},{"name":"Larry Cedar","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Rob Morrow","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Jen Nikolaisen","avatar":""},{"name":"Dominic Daniel","avatar":""},{"name":"Neil Dickson","avatar":""},{"name":"Claude Kn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324457);
