INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ca-dam-me', 'Hơn Cả Đam Mê', 'Love''s Whirlpool', 'https://phimimg.com/upload/vod/20231115-1/fb0e7dca84ef60fc2aeca5427b596451.jpg', 'https://phimimg.com/upload/vod/20231115-1/ab8922bf401eb6c9cd01c682b290b826.jpg', '<p>Một căn phòng trong một căn hộ sang trọng ở trung tâm thành phố. Cuộc hoan lạc vào buổi tối bắt đầu với tám người đàn ông và phụ nữ gặp nhau lần đầu tiên, trong đó có một anh chàng thất nghiệp trả phí tiệc tùng 20.000 yên bằng tiền của cha mẹ anh ta, và một nữ sinh viên đại học có vẻ ngoài tầm thường che giấu sự phàm ăn. ham muốn tình dục.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sosuke Ikematsu","avatar":""},{"name":"Mugi Kadowaki","avatar":""},{"name":"Kenichi Takitoh","avatar":""},{"name":"Eriko Nakamura","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"Yoko Mitsuya","avatar":""},{"name":"Muck Akazawa","avatar":""},{"name":"Ryusuke Komakine","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"You Nobue","avatar":""},{"name":"Yosuke Kubozuka","avatar":""},{"name":"Tetsushi Tanaka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
