INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-cua-michael-king', 'Nỗi Ám Ảnh của Michael King', 'The Possession of Michael King', 'https://phimimg.com/upload/vod/20231114-1/cb4c7d04570994982287c4ee1e4c75dc.jpg', 'https://phimimg.com/upload/vod/20231114-1/e7f3299e4999ca0a72b21ce685422c9a.jpg', '<p>Phim kể về nhà làm phim tài liệu Michael King (Shane Johnson), người không tin vào Chúa hay Quỷ dữ. Sau cái chết đột ngột của vợ, Michael quyết định thực hiện bộ phim tiếp theo về cuộc tìm kiếm sự tồn tại của thế lực siêu nhiên, biến anh thành trung tâm của cuộc thí nghiệm – cho phép các nhà quỷ học, thầy chiêu hồn và nhiều người thực hành điều huyền bí thử sức với những điều sâu thẳm và đen tối nhất. phép thuật và nghi lễ mà họ có thể tìm thấy trên người anh ta - với hy vọng rằng khi họ thất bại, anh ta sẽ có bằng chứng một lần và mãi mãi rằng tôn giáo, thuyết tâm linh và điều huyền bí chẳng hơn gì thần thoại. Nhưng một cái gì đó xảy ra. Một thế lực xấu xa và đáng sợ đã chiếm lấy Michael King. Và nó sẽ không để cho anh ta đi.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shane Johnson","avatar":""},{"name":"Ella Anderson","avatar":""},{"name":"Cara Pifko","avatar":""},{"name":"Julie McNiven","avatar":""},{"name":"Tomas Arana","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Patricia Healy","avatar":""},{"name":"Cullen Douglas","avatar":""},{"name":"Jed Rees","avatar":""},{"name":"Freda Foh Shen","avatar":""},{"name":"Tobias Jelinek","avatar":""},{"name":"Luke Baines","avatar":""},{"name":"Anna Mountford","avatar":""},{"name":"Stewart Skelton","avatar":""},{"name":"Michael Ray Escamilla","avatar":""},{"name":"Shirley Jordan","avatar":""},{"name":"RJ Farrington","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
