INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-da-tinh-than', 'Loạn Đả Tinh Thần', 'Locke', 'https://phimimg.com/upload/vod/20231114-1/a3baee63930ca5cda330d48f5d164215.jpg', 'https://phimimg.com/upload/vod/20231114-1/5d07902889efbd7840026ea3bb27167c.jpg', '<p>Cuộc đời của một nhà quản lý xây dựng thành công, Ivan Locke, có một bước ngoặt đầy kịch tính khi anh ta biết được thông qua một cuộc điện thoại rằng một người phụ nữ mà anh ta từng tình một đêm đang lâm bồn.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Andrew Scott","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Ben Daniels","avatar":""},{"name":"Bill Milner","avatar":""},{"name":"Alice Lowe","avatar":""},{"name":"Danny Webb","avatar":""},{"name":"Lee Ross","avatar":""},{"name":"Silas Carson","avatar":""},{"name":"Kirsty Dillon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
