INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('open-windows', 'Open Windows', 'Open Windows', 'https://phimimg.com/upload/vod/20231115-1/faee22842469796bc548686c15b9a1d4.jpg', 'https://phimimg.com/upload/vod/20231115-1/22c8bb81a3992aa6d36d76718b500a82.jpg', '<p>Một nữ diễn viên tên Jill từ chối ăn tối với Nick, một người hâm mộ đã giành được một cuộc hẹn hò với cô trong một cuộc thi internet. Đổi lại, một anh chàng tên là Hợp âm, tạo dáng với tư cách là Giám đốc chiến dịch của Jill, giúp Nick theo bước chân của nữ diễn viên từ máy tính của mình. Nick bắt đầu một trò chơi mà anh ta nhận ra rằng anh ta chỉ là một con rối vào những kế hoạch maniacal do Hợp âm nghĩ ra, để săn lùng ngôi sao.</p>', 'Full', 1, 'single', 'completed', 20, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Sasha Grey","avatar":""},{"name":"Neil Maskell","avatar":""},{"name":"Iván González","avatar":""},{"name":"Jaime Olías","avatar":""},{"name":"Adam Quintero","avatar":""},{"name":"Daniel Pérez Prada","avatar":""},{"name":"Jake Klamburg","avatar":""},{"name":"Rachel Arieff","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Julián Villagrán","avatar":""},{"name":"Carlos Areces","avatar":""},{"name":"Raúl Cimas","avatar":""},{"name":"Nacho Vigalondo","avatar":""},{"name":"Miguel Noguera","avatar":""},{"name":"Nancy Yao","avatar":""},{"name":"Luis Sanchez-Cañe","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324457);
