INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chang-trai-jersey', 'Những Chàng Trai Jersey', 'Jersey Boys', 'https://phimimg.com/upload/vod/20231115-1/234b20533d95fc0946314f33d44e0997.jpg', 'https://phimimg.com/upload/vod/20231115-1/6690843184c779c005317a4f8ee4fad0.jpg', '<p>Một bộ phim tiểu sử âm nhạc về Bốn Mùa—sự trỗi dậy, thời điểm khó khăn và xung đột cá nhân, và chiến thắng cuối cùng của một nhóm bạn mà âm nhạc của họ đã trở thành biểu tượng của một thế hệ. Khác xa với một buổi hòa nhạc tưởng nhớ đơn thuần, nó đi vào trọng tâm của các mối quan hệ ở trung tâm của nhóm, đặc biệt tập trung vào thủ lĩnh Frankie Valli, đứa trẻ nhỏ với giọng giả thanh lớn.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Lloyd Young","avatar":""},{"name":"Vincent Piazza","avatar":""},{"name":"Michael Lomenda","avatar":""},{"name":"Erich Bergen","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Joseph Russo","avatar":""},{"name":"Kathrine Narducci","avatar":""},{"name":"Freya Tingley","avatar":""},{"name":"Johnny Cannizzaro","avatar":""},{"name":"James Madio","avatar":""},{"name":"Francesca Eastwood","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"Barry Livingston","avatar":""},{"name":"Alexis Krause","avatar":""},{"name":"Jeremy L","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
