INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-chang-trai-jersey', 'Những Chàng Trai Jersey', 'Jersey Boys', 'những chàng trai jersey jersey boys john lloyd young vincent piazza michael lomenda erich bergen christopher walken mike doyle joseph russo kathrine narducci freya tingley johnny cannizzaro james madio francesca eastwood steve schirripa barry livingston alexis krause jeremy l ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-mat-sat-thu', 'Nước Mắt Sát Thủ', 'No Tears For The Dead', 'https://phimimg.com/upload/vod/20231115-1/8d2eb850270c160fc719fc56743e827d.jpg', 'https://phimimg.com/upload/vod/20231115-1/cf945717343db356fb09105a2a2a371d.jpg', '<p>Bộ phim kể về cuộc đời và số phận bất hạnh của nhân vật Gon. Từ khi còn nhỏ, Gon đã bị bỏ rơi trên đất Mỹ xa lạ, được nuôi dưỡng bởi một nhóm mafia và được huấn luyện để trở thành một sát thủ chuyên nghiệp. Trong một cuộc truy sát, Gon đã vô tình giết hại một người vô tội và sai lầm khủng khiếp này đã ám ảnh và khiến anh suy nghĩ về những điều tồi tệ mình đã từng làm. Trải qua cảm giác hối tiếc sâu sắc về cuộc đời mình, anh quyết định quên đi quá khứ và quay về với cuộc sống bình thường. Cơ hội cho anh rời bỏ cuộc đời của sát thủ máu lạnh này đó là quay trở về Hàn Quốc và thực hiện nhiệm vụ cuối cùng - ám sát một người có tên Mogyeong - người phụ nữ đang tuyệt vọng vì mất đi cả chồng và con gái nhưng không hề hay biết mình đang dính líu tới một âm mưu to lớn. Liệu nhiệm vụ cuối cùng tại quê hương của người mẹ đã bỏ rơi Gon có dễ dàng thực hiện? Liệu anh có đủ can đảm để truy sát người phụ nữ này, người mà anh lỡ &quot;phải lòng&quot;? Liệu có còn con đường cho anh quay trở lại với ánh sáng?.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-gun","avatar":""},{"name":"Kim Min-hee","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Jun Kim","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Lee Young-lan","avatar":""},{"name":"Kang Ji-woo","avatar":""},{"name":"Anthony Dilio","avatar":""},{"name":"Alexander Wraith","avatar":""},{"name":"Rich Ting","avatar":""},{"name":"Dana Lee","avatar":""},{"name":"Angela Bullock","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Kang Han-na","avatar":""},{"name":"Park Ji-yeon","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
