INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-xu-ma-am', 'Đồng Xu Ma Ám', 'Ghost Coins', 'null', 'https://phimimg.com/upload/vod/20231113-1/ce71f51ff75ca9cec7e597261c10ebc8.jpg', '<p>Ở Thái Lan có một tín ngưỡng yêu cầu người thân đặt đồng xu vào miệng của người quá cố để họ có thể sang thế giới bên kia. Tuy nhiên, có một nhóm thanh thiếu niên liều lĩnh và vô trách nhiệm vẫn tiếp tục ăn trộm những đồng tiền vàng của người đã khuất. Bị tiêu diệt bởi lòng tham của chính mình, những thanh thiếu niên sau đó đã lên kế hoạch ăn cắp từ xác chết của một triệu phú, người có một đống tiền vàng và hành động của họ bằng cách nào đó đã khiến người chết tức giận. Sau đó, nhóm thanh thiếu niên gặp phải nhiều tình huống kinh hoàng khác nhau khi linh hồn của người đàn ông quay lại ám ảnh họ.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Rhatha Phongam","avatar":""},{"name":"Namo Tongkumnerd","avatar":""},{"name":"Thanayong Wongtrakul","avatar":""},{"name":"Dharmthai Plangsilp","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
