INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-cong-cua-quy', 'Cánh Cổng Của Quỷ', 'At the Devil''s Door', 'https://phimimg.com/upload/vod/20231112-1/fafb265933e79dc8b9d1da8c0f10c307.jpg', 'https://phimimg.com/upload/vod/20231112-1/5551fa560896287719799b85420256ea.jpg', '<p>Cành Cổng Của Quỷ - At The Devil&#39;s Door là bộ phim kinh dị Mỹ 2014 của đạo diễn Nicholas McCarthy. Bộ phim xoay quanh Leigh - cô nữ nhân viên nhà đất được gọi đi giám hộ 1 căn hộ sắp bán. Đến nơi, cô bị một cô gái quấy nhiễu đến mức quá đáng. Thoạt tiên cô chịu đựng vì nghỉ rằng đó chỉ là con gái người chủ căn hộ tìm cách phá hoại, cản trở cô. Dần dần, cô nhận ra sự việc không chỉ đơn giản như vậy, Leigh không ngờ rằng có một con quỷ đang ẩn bên trong và chi phối mọi hành động của cô gái. Con quỷ ấy đã đợi Leigh từ rất lâu, để thực hiện 1 mưu đồ đáng sợ. Mưu đồ đó là gì? và liệu Leigh có vượt qua được con quỷ dữ ấy hay không?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Rickards","avatar":""},{"name":"Nick Eversman","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Mark Steger","avatar":""},{"name":"Catalina Sandino Moreno","avatar":""},{"name":"Naya Rivera","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Daniel Roebuck","avatar":""},{"name":"Jan Broberg","avatar":""},{"name":"Arshad Aslam","avatar":""},{"name":"Kelsey Heller","avatar":""},{"name":"Kent Faulcon","avatar":""},{"name":"Bresha Webb","avatar":""},{"name":"Assaf Cohen","avatar":""},{"name":"Shaun O''Hagan","avatar":""},{"name":"Olivia Crocicchia","avatar":""},{"name":"Jenn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
