INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-truyen-ky-uc', 'Người Truyền Ký Ức', 'The Giver', 'https://phimimg.com/upload/vod/20231112-1/3c9dee5548a6dd22a160ab06f5ca55a3.jpg', 'https://phimimg.com/upload/vod/20231112-1/8d30ec677a923c51e1ea18dc4b60e19c.jpg', '<p>Jonas (Brenton Thwaites) sống trong một thế giới rõ ràng của sự phù hợp và mãn nguyện. Khi anh ta bắt đầu dành thời gian với Giver (Jeff Bridges), một ông già là người giữ những ký ức của cộng đồng, Jonas phát hiện ra những sự thật nguy hiểm trong quá khứ bí mật của cộng đồng. Được trang bị sức mạnh của kiến thức, Jonas nhận ra rằng anh ta phải thoát khỏi thế giới của họ để bảo vệ bản thân và những người anh ta yêu thích - một thách thức không ai từng hoàn thành thành công.</p>', 'Full', 1, 'single', 'completed', 9, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brenton Thwaites","avatar":""},{"name":"Odeya Rush","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Taylor Swift","avatar":""},{"name":"Emma Tremblay","avatar":""},{"name":"Katharina Damm","avatar":""},{"name":"Alexander Jillings","avatar":""},{"name":"James Jillings","avatar":""},{"name":"Jordan Nicholas Smal","avatar":""},{"name":"Saige Fernandes","avatar":""},{"name":"Renate Stuurman","avatar":""},{"name":"Vanessa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324457);
