INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sinh-thu-phan-1', 'Ký Sinh Thú Phần 1', 'Parasyte Part 1', 'https://phimimg.com/upload/vod/20231112-1/a6e3f3f778764d1d7d6d39f01f775035.jpg', 'https://phimimg.com/upload/vod/20231112-1/95ac64f5502bf4c2e7a39226c7eb28d3.jpg', '<p>Shinichi là một thiếu niên 17 tuổi, sống cùng bố mẹ tại một khu phố yên tĩnh ở Tokyo. Một đêm nọ, những sinh vật ngoài hành tinh, có hình thù giống loài sâu, với tên gọi Kiseijū (&quot;Ký sinh vật&quot;) đổ bộ lên Trái Đất, chiếm lấy não và điều khiển chủ thể là con người bằng cách xâm nhập qua tai hoặc mũi. Một &quot;Ký sinh vật&quot; có ý định bò vào tai của Shinichi khi cậu ngủ nhưng thất bại vì cậu đang đeo tai nghe, vậy nên đã xâm nhập cơ thể cậu bằng cách chui vào tay và điều khiển cánh tay phải, và sau đó lấy tên là Migi.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shota Sometani","avatar":""},{"name":"Eri Fukatsu","avatar":""},{"name":"Ai Hashimoto","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Masahiro Higashide","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Miko Yoki","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"Pierre Taki","avatar":""},{"name":"Sadawo Abe","avatar":""},{"name":"Mansaku Ikeuchi","avatar":""},{"name":"Seiji Hino","avatar":""},{"name":"Hideto Iwai","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Shuji Okui","avatar":""},{"name":"Yuki Sakurai","avatar":""},{"name":"Kosuke Toyohara","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997