INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-trom-cap-truc-tiep-tai-dublin', 'Bộ ba trộm cắp: Trực tiếp tại Dublin', 'Trailer Park Boys: Live in F**kin'' Dublin', 'https://phimimg.com/upload/vod/20231124-1/607e2f2c16aa39b19c3284dd85ac4c05.jpg', 'https://phimimg.com/upload/vod/20231124-1/7d0f8c34f56c8d55b82ab132d3b35d5f.jpg', '<p>Các chàng trai đi Ireland sau khi thắng một cuộc thi để gặp Rush, nhưng lại bị bắt với lý do nhập cư và phải làm một chương trình múa rối phục vụ cộng đồng.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Paul Tremblay","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"Mike Smith","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
