INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-nhan-thieu-nien', 'Tù Nhân Thiếu Niên', 'Starred Up', 'https://phimimg.com/upload/vod/20231112-1/343212ef08ad4b431dc2df0fca885c82.jpg', 'https://phimimg.com/upload/vod/20231112-1/c3a2d9dda15d92034d4e60d9d520bb9c.jpg', '<p>Eric 19 tuổi, kiêu ngạo và cực kỳ bạo lực, bị chuyển sớm đến cùng một cơ sở nhà tù dành cho người lớn với người cha ghẻ lạnh của mình. Khi tính khí nóng nảy của anh nhanh chóng khiến anh trở thành kẻ thù của cả quản lý nhà tù và bạn tù - và mối quan hệ vốn đã đầy biến động của anh với cha mình đã vượt quá giới hạn - Eric được một nhà trị liệu tâm lý tình nguyện, người điều hành một nhóm quản lý cơn giận cho tù nhân, tiếp cận. Bị giằng xé giữa chính trị băng đảng, tham nhũng trong tù và tia hy vọng về một điều gì đó tốt đẹp hơn, Eric thấy mình đang phải chiến đấu cho cuộc sống của chính mình, không chắc liệu cha mình có ở đó để bảo vệ anh ta hay tham gia trừng phạt anh ta hay không.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Jack O''Connell","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"David Ajala","avatar":""},{"name":"Peter Ferdinando","avatar":""},{"name":"Gershwyn Eustache Jnr","avatar":""},{"name":"Anthony Welsh","avatar":""},{"name":"David Avery","avatar":""},{"name":"Sian Breckin","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Gilly Gilchrist","avatar":""},{"name":"Frederick Schmidt","avatar":""},{"name":"Edna Caskey","avatar":""},{"name":"Duncan Airlie James","avatar":""},{"name":"Matt Faris","avatar":""},{"name":"Tommy McDonn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
