INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-nghin-nam', 'Ác Quỷ Nghìn Năm', 'Kundo: Age of the Rampant', 'https://phimimg.com/upload/vod/20231113-1/c6b169345ee01209212426c618dad76b.jpg', 'https://phimimg.com/upload/vod/20231113-1/621469be3eb1c99f5ff062af6452820e.jpg', '<p>Ác Quỷ Nghìn Năm - Kundo: Age of the Rampant là một bộ phim hành động võ thuật Hàn Quốc 2014 của đạo diễn Yoon Jong-bin. Năm 1859 trong những ngày cuối cùng của triều đại Joseon, nạn tham ô dẫn đến lầm than và chết chóc. Một toán cướp tên là KUNDO chuyên đi cướp của nhà giàu, những kẻ tham ô chia cho người nghèo. Toán cướp là niềm danhh dự cho người nghèo và những người bị áp bức. Thế nhưng, đối với một người đàn ông thì không chỉ phải như thế...</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Yoon Ji-hye","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Han Yeri","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Lee Da-wit","avatar":""},{"name":"Nam Da-reum","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Kim Kkob-bi","avatar":""},{"name":"Kim Jae-young","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
