INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-dai-nao-thien-cung', 'Tây Du Ký: Đại Náo Thiên Cung', 'The Monkey King', 'https://phimimg.com/upload/vod/20231113-1/aa38477bada1b93016c7ef93b10a9672.jpg', 'https://phimimg.com/upload/vod/20231113-1/ef68ea8c47035770d77b2a581b5a1233.jpg', '<p>Đại Náo Thiên Cung là câu chuyện về cuộc đời của Tôn Ngộ Không trước chuyến tháp tùng Đường Tăng đi Ấn Độ thỉnh kinh. Ngưu Ma Vương vì muốn đưa người vợ yêu là Thiết phiến công chúa và con trai là Hồng hài nhi lên thiên đàng nên đã xúi giục Tôn Ngộ Không tấn công triều đình. Do phạm tội đại náo thiên cung nên Tôn Ngộ Không bị Phật Tổ Như Lai phạt nhốt dưới Ngũ Hành Sơn 500 năm cho đến khi được Tam Tạng giải thoát và theo ông đi thỉnh kinh.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Joe Chen","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Hai Yitian","avatar":""},{"name":"Liu Hua","avatar":""},{"name":"Calvin Ka-Sing Cheng","avatar":""},{"name":"Him Law","avatar":""},{"name":"Xia Zitong","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Cathy Leung Yue-Yan","avatar":""},{"name":"Zhang Zilin","avatar":""},{"name":"Irene Wong","avatar":""},{"name":"Zhang You","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","