INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-gai-goi', 'Truy Sát Gái Gọi', 'GirlHouse', 'https://phimimg.com/upload/vod/20231111-1/d5bfdd3c39e2b6aa1b8e3510e78abfeb.jpg', 'https://phimimg.com/upload/vod/20231111-1/d762c9234273708fd05e938806af5286.jpg', '<p>Trong nỗ lực kiếm thêm tiền khi đi học đại học, Kylie chuyển đến một ngôi nhà chuyên truyền nội dung lên một trang web được xếp hạng X. Sau khi một người hâm mộ loạn trí đột nhập vào để xác định vị trí của ngôi nhà, cô thấy mình đang phải chiến đấu kinh hoàng để giành lấy mạng sống.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ali Cobrin","avatar":""},{"name":"Erin Agostino","avatar":""},{"name":"James Thomas","avatar":""},{"name":"Alice Hunter","avatar":""},{"name":"Alyson Bath","avatar":""},{"name":"Adam DiMarco","avatar":""},{"name":"Slaine","avatar":""},{"name":"Elysia Rotaru","avatar":""},{"name":"Chasty Ballesteros","avatar":""},{"name":"Nicole Fox","avatar":""},{"name":"Zuleyka Silver","avatar":""},{"name":"Wesley MacInnes","avatar":""},{"name":"Camren Bicondova","avatar":""},{"name":"Alexis Kendra","avatar":""},{"name":"Jaron Adams","avatar":""},{"name":"Julia A. Long","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
