INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-va-quai-vat-2014', 'Người Đẹp Và Quái Vật', 'Beauty and the Beast', 'https://phimimg.com/upload/vod/20231111-1/44706b61c4c4126324b2711ebce6f503.jpg', 'https://phimimg.com/upload/vod/20231111-1/a41219dce2168d89ea9d259574efcc8a.jpg', '<p>Bắt nguồn từ câu chuyện cổ tích kinh điển từng rất quen thuộc với tuổi thơ của bao người, “Beauty and the Beast” – hay tựa Việt là “Người đẹp và Quái vật” suốt nhiều thập niên đã trở thành đề tài cho vô số các tác phẩm văn học nghệ thuật. Chỉ tính riêng về phương diện điện ảnh, kể từ năm 1946 đến nay đã có tổng cộng 5 bộ phim màn ảnh rộng lấy đề tài từ câu chuyện này, chưa kể 3 loạt phim truyền hình và nhiều phiên bản khác. Tuy nhiên, mấy ai biết rằng, câu chuyện cổ tích nguyên gốc lại là một tác phẩm dân gian của Pháp (La Belle et la Bête), được xuất hiện lần đầu vào năm 1740 bởi nữ nhà văn Gabriell-Suzanne Barbot de Villeneuve.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Léa Seydoux","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Eduardo Noriega","avatar":""},{"name":"Myriam Charleins","avatar":""},{"name":"Audrey Lamy","avatar":""},{"name":"Sara Giraudeau","avatar":""},{"name":"Jonathan Demurger","avatar":""},{"name":"Nicolas Gob","avatar":""},{"name":"Louka Meliava","avatar":""},{"name":"Yvonne Catterfeld","avatar":""},{"name":"Dejan Bućin","avatar":""},{"name":"Wolfgang Menardi","avatar":""},{"name":"Mickey Hardt","avatar":""},{"name":"Arthur Doppler","avatar":""},{"name":"Elisabeth Bogdan","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324457);
