INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-phe-doi-va-yeu', 'Cà Phê, Đợi Và Yêu', 'Café. Waiting. Love', 'https://phimimg.com/upload/vod/20231111-1/121a63dd795ae266bbaea001c86fb597.jpg', 'https://phimimg.com/upload/vod/20231111-1/fe58b2135872ea91433b57f2aca33191.jpg', '<p>Sinh viên năm nhất đại học Si-ying nhận được một công việc bán thời gian tại “Cafe. Chờ. Quán cà phê Love”, nơi cô kết bạn với Abusi, một nhân viên pha cà phê tomboy có thể pha bất kỳ loại cà phê nào khách hàng yêu cầu, chủ quán cà phê xinh đẹp và bí ẩn, và Zeyu, chàng trai luôn ngồi một chỗ trong quán cà phê có vẻ rất nổi tiếng với các cô gái và người mà Si-ying nảy sinh tình cảm ngay lập tức.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Vivian Sung","avatar":""},{"name":"Bruce Ho","avatar":""},{"name":"Vivian Chow","avatar":""},{"name":"Megan Lai","avatar":""},{"name":"Marcus Chang","avatar":""},{"name":"Pauline Lan","avatar":""},{"name":"Lee Luo","avatar":""},{"name":"Cheng Chih-wei","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Ben Lam","avatar":""},{"name":"Hsi-Tien Huang","avatar":""},{"name":"Yuri Kao","avatar":""},{"name":"Hung Yan Siang","avatar":""},{"name":"Katie Chen","avatar":""},{"name":"Ethan Lo","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Chen Yen-Tso","avatar":""},{"name":"Cammy Chiang","avatar":""},{"name":"Kerr Hsu","avatar":""},{"name":"Jiu Kong","avatar":""},{"name":"Tsai C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324457);
