INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-ung-troi-day', 'Chim Ưng Trỗi Dậy', 'Falcon Rising', 'https://phimimg.com/upload/vod/20231110-1/dbde37527db58f711ec21154314ca971.jpg', 'https://phimimg.com/upload/vod/20231110-1/aa4d9a985a204124273300f299827d31.jpg', '<p>Cựu lính thủy đánh bộ John &quot;Falcon&quot; Chapman là người luôn bị dằn vặt bởi quá khứ và chấn thương tâm lý sau chiến tranh, nóng tính và có xu hướng đập phá. Cho nên anh chỉ là &quot;giải pháp cuối cùng&quot; cho những vụ khó giải quyết của cảnh sát. Khi biết tin em gái mình bị hành hung suýt chết ở Brazil, anh liền tức tốc lên đường...</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Lateef Crowder","avatar":""},{"name":"Laila Ali","avatar":""},{"name":"Hazuki Kato","avatar":""},{"name":"Masashi Odate","avatar":""},{"name":"Millie Ruperto","avatar":""},{"name":"Robert Colón","avatar":""},{"name":"Jazmin Caratini","avatar":""},{"name":"Michael J. Morris","avatar":""},{"name":"Jimmy Navarro","avatar":""},{"name":"Johnny Yang","avatar":""},{"name":"Clifford Myatt","avatar":""},{"name":"Eddie Valdes","avatar":""},{"name":"Arzoris Perez","avatar":""},{"name":"Cristian Miranda Vélez","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324457);
