INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-vo-hinh', 'Chàng Trai Vô Hình', 'The Invisible Boy', 'https://phimimg.com/upload/vod/20231110-1/598483b75f817cca7b51563a5f84634c.jpg', 'https://phimimg.com/upload/vod/20231110-1/618bbf7f81d5d0a0aaa7c4e8e5bd8f3e.jpg', '<p>Câu chuyện nói về một cậu bé 13 tuổi từ nhỏ đã có tính nhút nhát, ba mẹ của cậu bé đã làm đủ mọi cách để có thể làm cho cậu bình thường như những đứa trẻ cùng trang lứa nhưng vẫn không được, ngày hôm đó là nhầm ngày Halloween cậu bé mặt bộ trang phục và phát hiện ra bản thân mình có thể tàng hình.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ludovico Girardello","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Fabrizio Bentivoglio","avatar":""},{"name":"Noa Zatta","avatar":""},{"name":"Christo Jivkov","avatar":""},{"name":"Kseniya Rappoport","avatar":""},{"name":"Assil Kandil","avatar":""},{"name":"Falippo Valese","avatar":""},{"name":"Enea Barozzi","avatar":""},{"name":"Riccardo Gasparini","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"Vilius Tumalavicius","avatar":""},{"name":"Vincenzo Zampa","avatar":""},{"name":"Maria Sole Mansutti","avatar":""},{"name":"Zita Fusco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324457);
