INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-noi-loan-o-hong-kong', 'Những Kẻ Nổi Loạn Ở Hồng Kông', 'Hong Kong Rebels', 'null', 'https://phimimg.com/upload/vod/20231120-1/5b78c18b0724a92a9582bbe9307b24d8.jpg', '<p>Để tìm câu trả lời cho sự tự tử của mình anh trai, một nhà văn mười sáu tuổi bị lôi cuốn vào thế giới ngầm của Hồng Kông và buôn bán ma túy. Cuộc tẩu thoát khỏi thế lực xấu và thế giới ngầm thực sự là một cuộc chiến thực sự của một thanh niên mươi sáu tuổi. Và đó mùa hè năm 1997 - một mùa hè nổi loạn ở Hồng Koong.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jason Tobin","avatar":""},{"name":"Jai Day","avatar":""},{"name":"Glen Chin","avatar":""},{"name":"Oliver Williams","avatar":""},{"name":"Andrew Ng","avatar":""},{"name":"Harry Oram","avatar":""},{"name":"Zac Dawson","avatar":""},{"name":"Paul Spangfort","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
