INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nice-and-easy', 'Nice and Easy', 'Nice and Easy', 'https://phimimg.com/upload/vod/20231120-1/9591b50f27fb29c12251a5bddbc85a88.jpg', 'https://phimimg.com/upload/vod/20231120-1/fad9b98bee3241cba7d8fd4adfeace9c.jpg', '<p>Sebastian có một tham vọng trong cuộc sống: không làm gì cả. Horizon của anh ấy là chiếc ghế dài của anh ấy. Cuộc sống của anh ấy anh ấy không muốn sống nhưng chiêm ngưỡng. Nhưng hôm nay, nếu bạn không làm gì cả - bạn chẳng là gì cả. Được thúc đẩy bởi hai bạn cùng phòng của mình, thực tập chuỗi và những công việc kỳ lạ, quyết định anna và không hoàn toàn quyết định Bruno, Sebastien sẽ phải - một chút.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Baptiste Lecaplain","avatar":""},{"name":"Charlotte Le Bon","avatar":""},{"name":"Félix Moati","avatar":""},{"name":"Denis Podalydès","avatar":""},{"name":"Isabelle Candelier","avatar":""},{"name":"Jean-Yves Berteloot","avatar":""},{"name":"Suliane Brahim","avatar":""},{"name":"David Baïot","avatar":""},{"name":"Bernard Ménez","avatar":""},{"name":"Lou Chauvain","avatar":""},{"name":"Benjamin Lavernhe","avatar":""},{"name":"Richard Guedj","avatar":""},{"name":"Jean-Michel Lahmi","avatar":""},{"name":"Élisabeth Vitali","avatar":""},{"name":"Stéphanie Lagarde","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
