INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hong-den', 'Hoa Hồng Đen', 'Black Rose', 'https://phimimg.com/upload/vod/20231109-1/7a7adc441321fa965d3724411e9bc085.jpg', 'https://phimimg.com/upload/vod/20231109-1/c5fc3682064ab9b11ce6ea6e70602ca3.jpg', '<p>Những vụ giết người khủng khiếp, liên tục xảy ra đối với phụ nữ do một kẻ giết người hàng loạt gây ra ở các đường phố trung tâm của Hollywood. Một cảnh sát trưởng Nga được LAPD mời vào để giải quyết và tìm ra thủ phạm. Phim được dành riêng độc quyền cho hành khách Vietnam Airlines.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Alexander Nevsky","avatar":""},{"name":"Kristanna Loken","avatar":""},{"name":"Adrian Paul","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Matthias Hues","avatar":""},{"name":"Emmanuil Vitorgan","avatar":""},{"name":"Olga Rodionova","avatar":""},{"name":"Oksana Sidorenko","avatar":""},{"name":"Polina Butorina","avatar":""},{"name":"Robert Madrid","avatar":""},{"name":"Andrey Bazhin","avatar":""},{"name":"Arturs Pupols-Kochanevskiy","avatar":""},{"name":"Viktor Efremov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
