INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('viking-the-berserkers', 'Viking: The Berserkers', 'Viking: The Berserkers', 'https://phimimg.com/upload/vod/20231110-1/9af6bfacc84ec34405d7b4e24b764fa2.jpg', 'https://phimimg.com/upload/vod/20231110-1/99d7596cd081484a4ea30f5f7ab04cd2.jpg', '<p>The Hunger Games quay trở lại Thời kỳ Đen tối khi một nhóm năm người Saxon trẻ tuổi bị một nhóm chiến binh Viking đáng sợ bắt giữ và sử dụng làm con mồi trong một cuộc săn lùng nghi thức. Say mê một loại thuốc khiến họ trở nên &quot;điên cuồng&quot;, những thợ săn tàn bạo sẽ sớm đánh hơi thấy những đứa trẻ đang khiếp sợ trong cuộc chiến tuyệt vọng để sinh tồn khỏi cuộc săn lùng theo nghi thức. Do nhà làm phim xứ Wales Antony Smith viết kịch bản và đạo diễn.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sol Heras","avatar":""},{"name":"Anthony Baines","avatar":""},{"name":"Kezia Burrows","avatar":""},{"name":"Nick Cornwall","avatar":""},{"name":"Harry Feltham","avatar":""},{"name":"Freddie Hutchins","avatar":""},{"name":"Simon Armstrong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324457);
