INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-don-doc', 'Không Đơn Độc', 'You''re Not You', 'https://phimimg.com/upload/vod/20231110-1/67766793712bdcc11fec91c1e0debc19.jpg', 'https://phimimg.com/upload/vod/20231110-1/62b263f2a6ef756b4b54d9898f531074.jpg', '<p>Bộ phim tập trung vào cuộc sống của người phụ nữ mắc bệnh nan y. Cô gái trẻ, người giúp việc đảm nhận việc chăm sóc, bỗng trở thành tri kỷ của người phụ nữ này.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Swank","avatar":""},{"name":"Emmy Rossum","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Stephanie Beatriz","avatar":""},{"name":"Jason Ritter","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Andrea Savage","avatar":""},{"name":"Gerald Downey","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Erin Chenoweth","avatar":""},{"name":"Gareth Williams","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Ed Begley Jr.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324457);
