INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-co-tich', 'Khu Rừng Cổ Tích', 'Into the Woods', 'https://phimimg.com/upload/vod/20231110-1/d3de38ff249947211b96ae953b1b1025.jpg', 'https://phimimg.com/upload/vod/20231110-1/1c730b485c45754547f8f92998dc1891.jpg', '<p>Khu Rừng Cổ Tích - Into The Woods theo chân cặp vợ chồng người thợ làm bánh vào một khu rừng u ám đáng sợ để tìm cách hóa giải lời nguyền do mụ phù thủy xấu xí áp đặt cho họ. Họ buộc phải thu thập đủ những món đồ của chính các nhân vật cổ tích: con bò trắng của cậu bé Jack, chiếc áo choàng của cô bé quàng khăn đỏ, mái tóc của công chúa tóc mây Rapunzel, chiếc giày của nàng Lọ Lem Cinderella.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Daniel Huttlestone","avatar":""},{"name":"Tracey Ullman","avatar":""},{"name":"James Corden","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Lilla Crawford","avatar":""},{"name":"Mackenzie Mauzy","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Richard Glover","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"Simon Russell Bea","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
