INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-thu-5-cua-sinbad', 'Cuộc Phiêu Lưu Thứ 5 Của Sinbad', 'Sinbad: The Fifth Voyage', 'https://phimimg.com/upload/vod/20231109-1/fff379c15066b776ae3fcf4919d0b32f.jpg', 'https://phimimg.com/upload/vod/20231109-1/cb41a4e22c01ac9d1cc80d6f839c070a.jpg', '<p>Cuộc Phiêu Lưu Thứ 5 Của Sinbad - Sinbad The Fifth Voyage là bộ phim lấy bối cảnh khi đứa con đầu lòng của vua Sultal vừa được sinh ra đã bị một phù thủy tàn ác yểm phép. Sinbad được giao nhiệm vụ đi đến một sa mạc đầy ma thuật và các sinh vật kỳ lạ để giải cứu cô con gái bé nhỏ của nhà vua. Và rồi Sinbad có hoàn thành được nhiệm vụ đó hay không?</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shahin Sean Solimon","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Said Faraj","avatar":""},{"name":"Lorna Raver","avatar":""},{"name":"Mariam Vardani","avatar":""},{"name":"Isaac C. Singleton Jr.","avatar":""},{"name":"Sadie Alexandru","avatar":""},{"name":"Marco Khan","avatar":""},{"name":"Jon Jon Briones","avatar":""},{"name":"Mehrdad Sarlak","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324457);
