INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tho-san', 'Nữ Thợ Săn', 'The Huntresses', 'https://phimimg.com/upload/vod/20231109-1/117f1ee5120db2c724d755b4f4e31395.jpg', 'https://phimimg.com/upload/vod/20231109-1/d2c54ee4e774c8f751f451a5cca3a2f2.jpg', '<p>The Huntresses (2014) kể câu chuyện về 3 nữ kiếm khách thợ săn tài năng và xinh đẹp bậc nhất dưới thời đại Joseon. Đứng đầu bộ ba là thủ lĩnh Jin Ok (Ji Won), người thông minh nhất nhóm, đồng thời cũng là chủ nhân của những vũ khí quái chiêu hàng đầu. Trái ngược với hình ảnh điềm tĩnh và quyến rũ của đàn chị, em út Ga Bi (Son Ga In) lại thuộc mẫu con gái dễ thương, láu lỉnh. Với dung mạo lẫn cá tính hệt một đứa bé nghịch ngợm, Ga Bi luôn khiến cả nhóm đau đầu vì lối sống tự do, cá tính nóng nảy, suy nghĩ đi kèm với hành động. Trong khi đó, Hong Dan (Kang Ye Won) - cô gái duy nhất đã lập gia đình lại là cao thủ võ thuật kiêm tay lừa đảo chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji-won","avatar":""},{"name":"Ye-won Kang","avatar":""},{"name":"Son Ga-in","avatar":""},{"name":"Ju Sang-uk","avatar":""},{"name":"Chae Sang-woo","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Jin Ji-hee","avatar":""},{"name":"Ha Soo-ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
