INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-quy-2', 'Khế Ước Quỷ 2', 'The Pact II', 'https://phimimg.com/upload/vod/20231109-1/b209f828a86ed58bf08603a08b90d156.jpg', 'https://phimimg.com/upload/vod/20231109-1/a59c6cf9accdd6a13700f498d8f58224.jpg', '<p>June, một nữ họa sĩ thường xuyên có những cơn ác mộng đầy ám ảnh về một kẻ giết người hàng loạt, những giấc mơ này làm xáo trộn cuộc sống của cô và dần có những kết nối kinh hoàng với thế giới thực. Đặc vụ FBI Kevin Dickey, người tham gia vào điều tra cái chết của Judas – kể giết người hàng loạt man rợ ở The Pact I –đã xuất hiện trước cửa nhà June để thông báo một tin đầy kinh hãi rằng một bản sao của Judas đang quanh quẩn đâu đó xung quanh khu nhà. Trong quá trình điều tra, Dickey cho June xem bức hình nạn nhân của tên giết người bản sao khiến June choáng váng và kinh hoàng hơn khi nhận ra đó chính là người phụ nữ bị sát hại tàn bạo trong cơn ác mộng của cô.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Caity Lotz","avatar":""},{"name":"Camilla Luddington","avatar":""},{"name":"Haley Hudson","avatar":""},{"name":"Amy Pietz","avatar":""},{"name":"Scott Michael Foster","avatar":""},{"name":"Patrick Fischler","avatar":""},{"name":"Mark Steger","avatar":""},{"name":"Nicki Micheaux","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324457);
