INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khe-uoc-quy-2', 'Khế Ước Quỷ 2', 'The Pact II', 'khế ước quỷ 2 the pact ii caity lotz camilla luddington haley hudson amy pietz scott michael foster patrick fischler mark steger nicki micheaux ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-tac', 'Hải Tặc', 'The Pirates', 'https://phimimg.com/upload/vod/20231109-1/feda02d4f05dfec5973c635eb991ca29.jpg', 'https://phimimg.com/upload/vod/20231109-1/2aa565ecfe68c0e96ae90265e4837847.jpg', '<p>Bộ phim điện ảnh bom tấn vừa được công bố và sẽ ra mắt khán giả Hàn Quốc và thế giới năm 2014 này. 15 ngày trước khi triều đại Joseon ra đời, Long Ấn quý giá được triều Minh ban tặng đã biến mất! Lời đồn rằng Long Ấn đang trôi dạt trên biển &amp; ai sở hữu nó, sẽ nắm trong tay cả thiên hạ. Hết thảy quan quân triều đình đến các tướng cướp tứ phương đều hội ngộ, sẵn sàng lật tung biển cả và “nghênh chiến” để giành vật báu. Trong số đó, có 2 “danh cướp” lừng lẫy: Nữ Hải Tặc Son Ye Jin, một mình diệt 5.000 cướp biển tại đảo Tsushima và Nam Sơn Tặc Kim Nam Gil, cái tên khiến trẻ con các bản làng khóc ré khi nghe đến tên. Cả 2 sẽ có một trận quyết đấu “một mất một còn” kịch liệt. Trận chiến còn khó khăn &amp; “éo le” hơn khi Long Ấn đã bị nuốt bởi một … con cá voi!</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Sulli","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Shin Jung-geun","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kim Ian","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Chung Sung-hwa","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Ki