INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-sau-con-lai-ve', 'Năm Sau Con Lại Về', 'Nam Sau Con Lai Ve', 'https://phimimg.com/upload/vod/20231109-1/0c255cf6118a9fe562eb38136349acf6.jpg', 'https://phimimg.com/upload/vod/20231109-1/064ff685175ef0d6eaaee69effa8eaa0.jpg', '<p>Năm sau con lại về là một bộ phim điện ảnh Việt Nam do Trần Ngọc Giàu đạo diễn, phim dựa trên vở hài kịch Đón con về nổi tiếng một thời.</p>', 'Full', 1, 'single', 'completed', 20, 2014, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Hoài Linh","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Nhật Cường","avatar":""},{"name":"Trường Giang","avatar":""},{"name":"Long Đẹp Trai","avatar":""},{"name":"Bé Ben","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324457);
