INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-sinh-vat-ngoai-hanh-tinh', 'Giải Cứu Sinh Vật Ngoài Hành Tinh', 'Earth to Echo', 'https://phimimg.com/upload/vod/20231109-1/e122a9c574b66f7cab75d96f2324f919.jpg', 'https://phimimg.com/upload/vod/20231109-1/7e529de019c36d3350b06896d8ce3e64.jpg', '<p>Sau khi một dự án xây dựng bắt đầu đào trong khu phố của họ, những người bạn thân nhất Tuck, Munch và Alex bắt đầu nhận được những tin nhắn lạ, được mã hóa trên điện thoại di động của họ một cách khó hiểu. Tin chắc rằng có điều gì đó lớn hơn đang xảy ra, họ đến gặp cha mẹ và chính quyền. Cả ba bắt tay vào một cuộc phiêu lưu bí mật để giải mã và lần theo nguồn gốc của nó, đồng thời khám phá ra một sinh vật bí ẩn đến từ một thế giới khác đang rất cần sự giúp đỡ của họ. Cuộc hành trình sau đó sẽ thay đổi tất cả cuộc sống của họ mãi mãi.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Teo Halm","avatar":""},{"name":"Astro","avatar":""},{"name":"Reese Hartwig","avatar":""},{"name":"Ella Wahlestedt","avatar":""},{"name":"Jason Gray-Stanford","avatar":""},{"name":"Algee Smith","avatar":""},{"name":"Arthur Darbinyan","avatar":""},{"name":"Cassius M. Willis","avatar":""},{"name":"Sonya Leslie","avatar":""},{"name":"Kerry O''Malley","avatar":""},{"name":"Virginia Louise Smith","avatar":""},{"name":"Peter MacKenzie","avatar":""},{"name":"Valerie Wildman","avatar":""},{"name":"Roger Hewlett","avatar":""},{"name":"Mary Pat Gleason","avatar":""},{"name":"Marilyn Gi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễ