INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-chien-tranh', 'Liên Minh Công Lý: Chiến Tranh', 'Justice League: War', 'https://phimimg.com/upload/vod/20231109-1/27bf950a99c22698955aeead7115f1a8.jpg', 'https://phimimg.com/upload/vod/20231109-1/6a05ba5847b914ce0aef9aa760b435ca.jpg', '<p>Khi Darkseid và binh đoàn hùng mạnh, đông đảo của hắn đến xâm chiếm Trái Đất, một nhóm các siêu anh hùng - từng có xích mích, từng có hiểu nhầm, từng bị chính quyền săn đuổi - phát hiện ra rằng để chống lại thế lực ngoài hành tinh này, họ phải trở thành một thể thống nhất, và kết hợp khả năng của mỗi người trong một cuộc chiến không khoan nhượng để cứu lấy Trái Đất.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Monaghan","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Shemar Moore","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Justin Kirk","avatar":""},{"name":"Jason O''Mara","avatar":""},{"name":"George Newbern","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Bruce Thomas","avatar":""},{"name":"Rocky Carroll","avatar":""},{"name":"Georgie Kidder","avatar":""},{"name":"Hynden Walch","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Melique Berger","avatar":""},{"name":"Richar","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
