INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-de-vuong', 'Khách Sạn Đế Vương', 'The Grand Budapest Hotel', 'https://phimimg.com/upload/vod/20231109-1/5330c027d3e00eb4732365cc5b6c24df.jpg', 'https://phimimg.com/upload/vod/20231109-1/4853e5fb87863184101bd5ed47d53df6.jpg', '<p>Bộ phim này kể lại những cuộc phiêu lưu của M. Gustave (Ralph Fiennes), một hướng dẫn viên huyền thoại tại một khách sạn nổi tiếng ở châu Âu giữa các cuộc chiến, và Zero Moustafa (Tony Revolori), cậu bé sảnh trở thành người bạn đáng tin cậy nhất của mình. Câu chuyện liên quan đến hành vi trộm cắp và phục hồi một bức tranh phục hưng vô giá và trận chiến cho một gia đình khổng lồ - tất cả chống lại bối cảnh của một lục địa đột ngột và thay đổi đáng kể.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Ralph Fiennes","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Tony Revolori","avatar":""},{"name":"Mathieu Amalric","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Saoirse Ronan","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Flo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
