INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cai-chet-duoc-bao-truoc', 'Những Cái Chết Được Báo Trước', 'The Before Time', 'null', 'https://phimimg.com/upload/vod/20231109-1/c09b38b3b019a3cf70779c0b6b1f094e.jpg', '<p>Khi hai phi hành đoàn đối thủ tiến vào sa mạc để quay một chương trình thực tế dựa trên một kho báu Navajo bị chôn vùi, họ phát hiện ra rằng sự thật không chỉ xa lạ hơn viễn tưởng mà còn nguy hiểm hơn. Có điều gì đó muốn họ đào sâu hơn và thoát khỏi sa mạc sống sót.</p>', 'Full', 1, 'single', 'completed', 10, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ted Jonas","avatar":""},{"name":"Jules Hartley","avatar":""},{"name":"Phillip Andre Botello","avatar":""},{"name":"Danny Arroyo","avatar":""},{"name":"Danielle Baker","avatar":""},{"name":"Sean Patrick McGowan","avatar":""},{"name":"Aidan Marus","avatar":""},{"name":"Julianne Dowler","avatar":""},{"name":"Circus-Szalewski","avatar":""},{"name":"Megan Hui","avatar":""},{"name":"Rhoda Pell","avatar":""},{"name":"Patrick Barnitt","avatar":""},{"name":"Peter Paul Basler","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324458);
