INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-kinh-hoang', 'Nhà Kinh Hoàng', 'The Scarehouse', 'https://phimimg.com/upload/vod/20231108-1/1af857c248ffa0d46bd64299d13fd37d.jpg', 'https://phimimg.com/upload/vod/20231108-1/f23543a3e9f814712fee1cf35a80a265.jpg', '<p>Khi hai người bạn mở một ngôi nhà vui nhộn Halloween vào Đêm Quỷ, tất cả đều vui vẻ và trò chơi cho đến khi những người chị em nữ sinh trước đây của họ bắt đầu đến. Sáu chị em này phải đối mặt với quá khứ của họ khi màn đêm vượt khỏi tầm kiểm soát.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sarah Booth","avatar":""},{"name":"Kimberly-Sue Murray","avatar":""},{"name":"Katherine Barrell","avatar":""},{"name":"Dani Barker","avatar":""},{"name":"Teagan Vincze","avatar":""},{"name":"Emily Alatalo","avatar":""},{"name":"Jennifer Miller","avatar":""},{"name":"Ivana Kingston","avatar":""},{"name":"Brad Everett","avatar":""},{"name":"Jack Ettlinger","avatar":""},{"name":"Alex Harrouch","avatar":""},{"name":"Jonathan Dubsky","avatar":""},{"name":"Sean Kaufmann","avatar":""},{"name":"Julie Williams","avatar":""},{"name":"Tanya Bevan","avatar":""},{"name":"Scott Cavalheiro","avatar":""},{"name":"Sh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
