INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-di-thuong', 'Sức Mạnh Dị Thường', 'Afflicted', 'https://phimimg.com/upload/vod/20231108-1/c5247b2dee18a6a9a589127f57e12b50.jpg', 'https://phimimg.com/upload/vod/20231108-1/84207228581529270745bc2c1ddf96b5.jpg', '<p>Chuyến du lịch châu Âu của hai người bạn gặp bước ngoặt đen tối khi một trong số họ mắc phải một căn bệnh bí ẩn. Họ chạy đua để tìm ra nó là gì và làm thế nào để chữa khỏi nó trước khi căn bệnh hủy hoại hoàn toàn anh ta.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Baya Rehaz","avatar":""},{"name":"Derek Lee","avatar":""},{"name":"Clif Prowse","avatar":""},{"name":"Edo van Breemen","avatar":""},{"name":"Zachary Gray","avatar":""},{"name":"Michael Gill","avatar":""},{"name":"Jason Lee","avatar":""},{"name":"Benjamin Zeitoun","avatar":""},{"name":"Gary Redekop","avatar":""},{"name":"Lily Py Lee","avatar":""},{"name":"Tasya Teles","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
