INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tuyen-71', 'Chiến Tuyến ''71', '''71', 'https://phimimg.com/upload/vod/20231108-1/52637039d3185fc0e9e57c6c96db0dad.jpg', 'https://phimimg.com/upload/vod/20231108-1/ce2a71f673a5eb43ff29e0ab3f73d71e.jpg', '<p>Xung đột vũ trang tại Bắc Ireland luôn là “điểm nóng” trên bản đồ thế giới. Đặc biệt, giai đoạn từ năm 70 đến năm 72 được coi là đỉnh điểm của các cuộc xung đột giữa Anh, Cộng hoà Ireland và Bắc Ireland. Bạo loạn xảy ra, khủng bố liên tiếp khiến vô số người bị chết. ’71 (Chiến Tuyến &quot;71) của đạo diễn Yann Demange lấy bối cảnh chính tại thời điểm này.
 Trong khi thực hiện một nhiệm vụ tại thủ đô Belfast, do người dân chống đối quyết liệt, bạo loạn ập đến bất ngờ, người lính trẻ thuộc quân đội Anh Gary Hook (Jack O’Connell) vô tình bị đồng đội bỏ rơi lại phía sau. Đơn độc ngay giữa thành phố Belfast đầy rẫy nguy hiểm, Gary vừa bị lực lượng nổi dậy IRA lẫn lực lượng phản ứng nhanh của Anh truy đuổi gắt gao.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jack O''Connell","avatar":""},{"name":"Sean Harris","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Sam Reid","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Richard Dormer","avatar":""},{"name":"Killian Scott","avatar":""},{"name":"Babou Ceesay","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Martin McCann","avatar":""},{"name":"Jack Lowden","avatar":""},{"name":"Valene Kane","avatar":""},{"name":"Adam Nagaitis","avatar":""},{"name":"Joshua Hill","avatar":""},{"name":"Barry Barnes","avatar":""},{"name":"Aaron Mo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324458);
