INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-tuyen-71', 'Chiến Tuyến ''71', '''71', 'chiến tuyến ''71 ''71 jack o''connell sean harris paul anderson sam reid sam hazeldine barry keoghan charlie murphy richard dormer killian scott babou ceesay david wilmot martin mccann jack lowden valene kane adam nagaitis joshua hill barry barnes aaron mo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-summer-in-provence', 'My Summer in Provence', 'My Summer in Provence', 'https://phimimg.com/upload/vod/20231116-1/33a2d0ae8df8bedc753e65415cee4e00.jpg', 'https://phimimg.com/upload/vod/20231116-1/f592061843122b0291bd8c82f1578b79.jpg', '<p>Lea, Adrian và em trai của họ Theo, sinh ra điếc, đi nghỉ ở Provence với ông nội của họ, Paul &quot;Oliveron&quot; họ không bao giờ gặp nhau vì một cuộc cãi vã gia đình. Thật không may, đó không phải là những ngày lễ mà họ mơ ước, đặc biệt là sau khi cha họ tuyên bố rằng ông đã rời khỏi nhà. Trong vòng chưa đầy 24 giờ, đó là cuộc đụng độ của các thế hệ giữa thanh thiếu niên và ông của họ.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Lukas Pelissier","avatar":""},{"name":"Hugo Dessioux","avatar":""},{"name":"Chloé Jouannet","avatar":""},{"name":"Anna Galiena","avatar":""},{"name":"Aure Atika","avatar":""},{"name":"Tom Leeb","avatar":""},{"name":"Jean-Michel Noirey","avatar":""},{"name":"Hugues Aufray","avatar":""},{"name":"Charlotte de Turckheim","avatar":""},{"name":"Fabien Baïardi","avatar":""},{"name":"Laurent Fernandez","avatar":""},{"name":"Rodolphe Saulnier","avatar":""},{"name":"Oussama Abassa","avatar":""},{"name":"Joris Zapiain","avatar":""},{"name":"Michel Drucker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
