INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-summer-in-provence', 'My Summer in Provence', 'My Summer in Provence', 'my summer in provence my summer in provence jean reno lukas pelissier hugo dessioux chloé jouannet anna galiena aure atika tom leeb jean-michel noirey hugues aufray charlotte de turckheim fabien baïardi laurent fernandez rodolphe saulnier oussama abassa joris zapiain michel drucker ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-hu', 'Gái Hư', 'Call Me Bad Girl', 'https://phimimg.com/upload/vod/20231108-1/d1b6ec07b93d60eb5a609fbc59d6c54f.jpg', 'https://phimimg.com/upload/vod/20231108-1/071e90bd537355ed45738aeb77f616a6.jpg', '<p>Budsaba – cô nàng “gái hư” thành thị xinh đẹp, quyến rũ, chỉ thích dạo chơi “tình trường”, quyết tâm chiếm hết trái tim lũ “đàn ông ngốc”. Và tất nhiên “gái hư” thì chả tin vào tình yêu đích thực. Cho đến khi Budsaba gặp người đàn ông hoàn hảo, doanh nhân thành đạt Nuer Samutr. Tung hết chiêu trò để dụ chàng sa lưới đã khó, Budsaba còn phải chạm mặt 3 “gái ngoan” khác, đang theo đuổi Nuer \u0026 bảo vệ Nuer khỏi sự tấn công của Budsaba. Liệu “gái hư” dày dặn kinh nghiệm có “giăng lưới” thành công? Hay chính cô lại rơi vào bẫy tình của chàng trai hoàn hảo thật thà Nuer …</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pechaya Wattanamontree","avatar":""},{"name":"Teeradetch Metawarayut","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
