INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gai-hu', 'Gái Hư', 'Call Me Bad Girl', 'gái hư call me bad girl pechaya wattanamontree teeradetch metawarayut ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-den', 'Vận Đen', 'Good People', 'https://phimimg.com/upload/vod/20231108-1/e9db5fc9fef8619680820e32a0439b11.jpg', 'https://phimimg.com/upload/vod/20231108-1/b02021e71c7852490de366e866d41d99.jpg', '<p>Tom và Anna Wright, một cặp vợ chồng trẻ người Mỹ, lâm vào cảnh nợ nần chồng chất khi sửa sang lại ngôi nhà của gia đình Anna ở London. Khi cặp đôi đối mặt với việc đánh mất giấc mơ có một ngôi nhà và lập gia đình, họ phát hiện ra rằng người thuê nhà trong căn hộ bên dưới họ đã chết và anh ta để lại một khoản tiền mặt trị giá 400.000 đô la. Mặc dù ban đầu do dự, Tom và Anna quyết định rằng kế hoạch rất đơn giản: tất cả những gì họ phải làm là lặng lẽ lấy tiền và chỉ sử dụng những gì cần thiết để thoát khỏi nợ nần. Nhưng khi họ bắt đầu tiêu tiền và dường như không thể dừng lại, họ thấy mình trở thành mục tiêu của một kẻ thù nguy hiểm—tên trộm đã đánh cắp số tiền đó—và đó là lúc những điều rất tồi tệ bắt đầu xảy ra với những người tốt.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"James Franco","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Anna Friel","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Michael Jibson","avatar":""},{"name":"Diana Hardcastle","avatar":""},{"name":"Diarmaid Murtagh","avatar":""},{"name":"Oliver Dimsdale","avatar":""},{"name":"Nigel Genis","avatar":""},{"name":"Maarten Dannenberg","avatar":""},{"name":"Anick Wiget","avatar":""},{"name":"Michael Fox","avatar":""},{"name":"Waj Ali","avatar":""},{"name":"Nick Turner","avatar":""},{"name":"Amanda Edwards","avatar":""},{"name":"Francis Magee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
