INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-tham-phan', 'Ngài Thẩm Phán', 'The Judge', 'https://phimimg.com/upload/vod/20231108-1/e32cb688768a0860f883be75f798b01d.jpg', 'https://phimimg.com/upload/vod/20231108-1/1f13ca08da4f536996826001e67880ce.jpg', '<p>Hank Palmer là một luật sư nổi tiếng trở về quê nhà vào đám tang của mẹ. Joseph Palmer, cha anh cũng là một thẩm phán của thị trấn, người duy nhất nghi ngờ rằng cái chết của vợ mình là do bị sát hại và Hank Palmer phải chịu sự xa lánh và hắt hủi trong suốt hành trình khám phá sự thật rằng đã thực sự xảy ra chuyện gì...</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Jeremy Strong","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Leighton Meester","avatar":""},{"name":"Ken Howard","avatar":""},{"name":"Emma Tremblay","avatar":""},{"name":"Balthazar Getty","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Sarah Lancaster","avatar":""},{"name":"Lon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
