INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-no-cua-quy', 'Món Nợ Của Quỷ', 'Devil''s Due', 'https://phimimg.com/upload/vod/20231108-1/255c3aedf560f0f0bc73d8344da540fb.jpg', 'https://phimimg.com/upload/vod/20231108-1/ed77790144ef5419885b89e4d4a30eac.jpg', '<p>Việc mang thai ngoài ý muốn là bước ngoặt kinh hoàng đối với cặp vợ chồng mới cưới Zach và Samantha McCall.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zach Gilford","avatar":""},{"name":"Allison Miller","avatar":""},{"name":"Sam Anderson","avatar":""},{"name":"Catherine Kresge","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Geraldine Singer","avatar":""},{"name":"Tyler Forrest","avatar":""},{"name":"Julia Denton","avatar":""},{"name":"Robert Belushi","avatar":""},{"name":"Colin Walker","avatar":""},{"name":"Roger Payano","avatar":""},{"name":"Vanessa Ray","avatar":""},{"name":"Bill Martin Williams","avatar":""},{"name":"Jennifer Schemke","avatar":""},{"name":"Stacie Davis","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
