INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-do-chet-nguoi-2', 'Tốc Độ Chết Người 2', 'Born to Race: Fast Track', 'https://phimimg.com/upload/vod/20231108-1/0509b4cafeb5d31cb6f7fb7e07be2ebb.jpg', 'https://phimimg.com/upload/vod/20231108-1/51119e1ff983b9e6cc0d65528e84d0ab.jpg', '<p>Danny Krueger là một tay đua kéo hai mươi tuổi, người chơi theo luật của riêng mình. Sau khi giành được học bổng tại Học viện Đua xe Fast Lane danh giá, Danny thấy mình phải cạnh tranh với một số tay đua trẻ hung hãn nhất thế giới. Căng thẳng tăng vọt trong và ngoài đường đua, và một sự cố khủng khiếp khiến Danny không có bạn đua. Đối mặt với việc bị sa thải khỏi học viện, Danny buộc phải hợp tác với một đối thủ cũ. Cặp đôi phải học cách gạt bỏ những khác biệt sang một bên khi tranh giành vị trí tân binh trong một đội đua chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 11, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Beau Mirchoff","avatar":""},{"name":"Brett Davern","avatar":""},{"name":"Bill Sage","avatar":""},{"name":"Sharon Lawrence","avatar":""},{"name":"Nicole Badaan","avatar":""},{"name":"Tiffany Dupont","avatar":""},{"name":"Steve Bond","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"Grant Show","avatar":""},{"name":"Diogo Morgado","avatar":""},{"name":"Jussie Smollett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
