INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-den-cung-nhau', 'Họ Đến Cùng Nhau', 'They Came Together', 'https://phimimg.com/upload/vod/20231108-1/aa450cc9692f985d4dc4bc241e6632f6.jpg', 'https://phimimg.com/upload/vod/20231108-1/32be31014dc229028a91d4df5443e0eb.jpg', '<p>Họ Đến Cùng Nhau - They Came Together (2014) xoay quanh câu chuyện tình lãng mạn của Molly và Joel. Molly là một cô nàng dễ thương, sở hữu một cửa hàng đồ ngọt nhỏ. Trong khi đó, Joel là một anh chàng điển trai, làm việc cho một công ty kẹo khổng lồ đe dọa sẽ đóng cửa hàng kẹo của Molly. Tuy nhiên, mọi chuyện trở nên phức tạp khi từ chỗ là đối thủ, họ lại giành tình cảm cho nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Ellie Kemper","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Noureen DeWulf","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Michael Ian Black","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Teyonah Parris","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"David Wain","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
