INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phieu-luu-hoang-da', 'Chuyến Phiêu Lưu Hoang Dã', 'Wild', 'https://phimimg.com/upload/vod/20231108-1/2516f4de56c8de0e76cf31ff3a78415e.jpg', 'https://phimimg.com/upload/vod/20231108-1/54c516f61fec11a310de966568b9a9e0.jpg', '<p>Cheryl Strayed, một phụ nữ vừa ly hôn, quyết định bắt đầu cuộc sống mới bằng cách đi bộ đường dài dọc theo Đường mòn Pacific Crest dài 1.100 dặm. Cô ấy bắt đầu khám phá bản thân khi cô ấy đi trên chuyến đi của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Keene McRae","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"Michiel Huisman","avatar":""},{"name":"Kevin Rankin","avatar":""},{"name":"Cliff DeYoung","avatar":""},{"name":"Thomas Sadoski","avatar":""},{"name":"Randy Schulman","avatar":""},{"name":"W. Earl Brown","avatar":""},{"name":"Brian Van Holt","avatar":""},{"name":"Mo McRae","avatar":""},{"name":"Will Cuddy","avatar":""},{"name":"Leigh Parker","avatar":""},{"name":"Nick Eversman","avatar":""},{"name":"Ray Buckley","avatar":""},{"name":"Cathryn de Prume","avatar":""},{"name":"Kurt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
