INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-goi-tinh', 'Sát Thủ Gợi Tình', 'Gun Woman', 'https://phimimg.com/upload/vod/20231108-1/f24537271c7f2d0a4035b30b82771677.jpg', 'https://phimimg.com/upload/vod/20231108-1/76fd20a88d3708501b828d8cc48cba01.jpg', '<p>Một bác sĩ xuất sắc trong hành trình trả thù đã mua một phụ nữ trẻ và huấn luyện cô ấy trở thành sát thủ cuối cùng, cấy các bộ phận súng vào cơ thể cô ấy mà sau này cô ấy phải lắp ráp và sử dụng để giết mục tiêu trước khi cô ấy chảy máu đến chết.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Asami","avatar":""},{"name":"Kairi Narita","avatar":""},{"name":"Noriaki Kamata","avatar":""},{"name":"Matthew Floyd Miller","avatar":""},{"name":"Dean Simone","avatar":""},{"name":"Toshiya Agata","avatar":""},{"name":"Marco Ballare","avatar":""},{"name":"Marianne Bourg","avatar":""},{"name":"Stacey Chu","avatar":""},{"name":"D. Olivia Jordan","avatar":""},{"name":"Tatsuya Nakadai","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
