INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-lon', 'Chơi Lớn', 'Big Match', 'https://phimimg.com/upload/vod/20231108-1/01a67d3f24446ebe65d58223c7e53780.jpg', 'https://phimimg.com/upload/vod/20231108-1/31ff209909002aef083e69498a7e08da.jpg', '<p>Choi Ik Ho (do Lee Jung Jae đóng) là ngôi sao võ thuật tài năng, chuyên đóng các phim hài hước và hành động. Nhưng bất ngờ một ngày kia, anh vướng phải nghi án giết người. Ace (do Shin Ha Kyun thủ vai) là một người tổ chức trò chơi chuyên thiết kế những trò chơi cho giới thượng lưu. Anh ta đồng thời là tên tội phạm đã biến cả thành phố trở thành một cuộc chơi thông qua các phương tiện công nghệ cao. Ace và Choi Ik Ho sau đó đối đầu nhau khi Choi Ik Ho tham dự vào trò chơi để bảo vệ anh trai mình.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Shin Ha-kyun","avatar":""},{"name":"BoA","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Park Doo-sik","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Son Ho-jun","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Kim Yoon-sung","avatar":""},{"name":"Lee Sang-hong","avatar":""},{"name":"Nam Jeong-u","avatar":""},{"name":"Kim Geun-bae","avatar":""},{"name":"Jeong Gi-seop","avatar":""},{"name":"Kim Jae-chul","avatar":""},{"name":"Jung Hyun-jin","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Sung Ji-ru","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
