INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-khach-kenshin-2-dai-hoa-kyoto', 'Lãng Khách Kenshin 2: Đại Hỏa Kyoto', 'Rurouni Kenshin Part II: Kyoto Inferno', 'https://phimimg.com/upload/vod/20231108-1/2da24966bbf8fc14b6ac14a6cf9ab383.jpg', 'https://phimimg.com/upload/vod/20231108-1/cdb45171ae48cc034365199fba4c1a92.jpg', '<p>Lúc Kenshin bắt đầu cuộc sống mới cùng Kaoru và bạn bè thì anh nhận được yêu cầu từ chính quyền Minh Trị. Makoto Shishio là một cựu sát thủ như Kenshin, bị phản bội và bị thiêu sống, nhưng hắn đã thoát chết và hiện đang ở Kyoto, cùng đồng bọn âm mưu lật đổ chính quyền. Trái với ý nguyện của Kaoru, Kenshin bất đắc dĩ nhận nhiệm vụ, đến Kyoto để ngăn cản cuộc nội chiến sắp xảy đến với đất nước của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeru Satoh","avatar":""},{"name":"Emi Takei","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Kaito Oyagi","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Tao Tsuchiya","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Maryjun Takahashi","avatar":""},{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Kazufumi Miyazawa","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Ryosuke Miura","avatar":""},{"name":"Kenichi Takitoh","avatar":""},{"name":"Masataka Kubota","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[