INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-khach-kenshin-2-dai-hoa-kyoto', 'Lãng Khách Kenshin 2: Đại Hỏa Kyoto', 'Rurouni Kenshin Part II: Kyoto Inferno', 'lãng khách kenshin 2: đại hỏa kyoto rurouni kenshin part ii: kyoto inferno takeru satoh emi takei munetaka aoki kaito oyagi yu aoi yosuke eguchi yûsuke iseya min tanaka tao tsuchiya ryunosuke kamiki maryjun takahashi tatsuya fujiwara kazufumi miyazawa yukiyoshi ozawa ryosuke miura kenichi takitoh masataka kubota ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-hinh-bi-an', 'Bức Hình Bí Ẩn', 'Time Lapse', 'https://phimimg.com/upload/vod/20231107-1/f36e5d53aaa611c6817de10289a6a8d4.jpg', 'https://phimimg.com/upload/vod/20231107-1/704290bdbc5240ef88d2a2dfca85e552.jpg', '<p>Bộ phim kể về ba người bạn khám phá ra một cỗ máy có thể chụp ảnh 24 giờ tương lai vào mỗi ngày và họ bắt đầu có những âm mưu sử dụng cho mục đích cá nhân cho đến khi những rắc rối xung quanh chiếc máy này xảy ra.Phim Time Lapse đã nhận những lời ca ngợi từ các nhà phê bình vì bộ phim có cốt truyện khá tốt, độc đáo và đặc biệt, mang tính đột phá, bộ phim là một tiền đề cho các bộ phim &quot;hại não&quot; khác.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Panabaker","avatar":""},{"name":"Matt O''Leary","avatar":""},{"name":"George Finn","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Amin Joseph","avatar":""},{"name":"Jason Spisak","avatar":""},{"name":"Sharon Maughan","avatar":""},{"name":"David Figlioli","avatar":""},{"name":"Judith Drake","avatar":""},{"name":"Mark C. Hanson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
