INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-mat-sat-khi', 'Điềm Mật Sát Khí', 'Sweet Alibis', 'https://phimimg.com/upload/vod/20231107-1/d73e43c50fdf20bbece84fc0d7b96d8b.jpg', 'https://phimimg.com/upload/vod/20231107-1/508c73059e5d1174e147de6c845a21cc.jpg', '<p>Chi-yi là một cảnh sát kỳ cựu, người coi trọng sự an toàn của bản thân hơn bất cứ điều gì khác và do đó nổi tiếng là hèn nhát và kém hiệu quả trong công việc. Mặt khác, Yi-ping vừa tốt nghiệp học viện cảnh sát và sẵn sàng chứng tỏ bản thân bất chấp mọi rủi ro. Con gái của người đứng đầu Cơ quan Chính sách Quốc gia, Yi-ping bí mật tránh xa nguy hiểm bằng cách được chỉ định hợp tác với Chi-yi. Bắt đầu từ một vụ án tưởng chừng như vô nghĩa về cái chết vô tình của một chú cún con, cặp đôi về cơ bản là không hợp nhau bất ngờ lần ra manh mối của hàng loạt cái chết bí ẩn.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Alec Su","avatar":""},{"name":"Ariel Lin","avatar":""},{"name":"Matt Wu","avatar":""},{"name":"Lei Hung","avatar":""},{"name":"Tsu-Yun Lang","avatar":""},{"name":"Ma Nien-Hsien","avatar":""},{"name":"Kao Meng-Chieh","avatar":""},{"name":"Ken Lin","avatar":""},{"name":"Jacqueline Zhu Zhi-Ying","avatar":""},{"name":"Austin Lin","avatar":""},{"name":"Bebe Du Yan","avatar":""},{"name":"Lena Lam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
