INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-quai-hop', 'Hội Quái Hộp', 'The Boxtrolls', 'null', 'https://phimimg.com/upload/vod/20231103-1/0051cbd3eafbefa7e43b1832d4dce3db.jpg', '<p>Boxtrolls là một cộng đồng các sinh vật kỳ quặc, tinh nghịch, những người yêu thương một cậu bé mồ côi tên là trứng trong ngôi nhà hang động tuyệt vời mà họ đã xây dựng bên dưới đường phố của một thành phố được gọi là Cheesebridge. Câu chuyện kể về một cậu bé mồ côi trẻ được nuôi dưỡng bởi những người thu gom rác ở hang động dưới lòng đất, người cố gắng cứu bạn bè khỏi một kẻ hủy diệt độc ác, nhân vật phản diện của thị trấn, Archibald Snatcher. Khi Snatcher xuất hiện với một âm mưu để thoát khỏi các hộp. Trứng quyết định mạo hiểm trên mặt đất và &quot;vào ánh sáng&quot;, nơi anh gặp và hợp tác với Winnie Feisty tuyệt vời. Cùng nhau, họ đưa ra một kế hoạch táo bạo để cứu gia đình Boxtrolls. Bộ phim dựa trên tiểu thuyết của trẻ em &#39;ở đây là những con quái vật của Alan Snow.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Kingsley","avatar":""},{"name":"Isaac Hempstead-Wright","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Pat Fraley","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"James Urbaniak","avatar":""},{"name":"Brian George","avatar":""},{"name":"Lori Tri","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324458);
