INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-khi-ra-di', 'Trước Khi Ra Đi', 'Before We Go', 'https://phimimg.com/upload/vod/20231103-1/3c93c9f9bdc0c118244093ffb8b1310c.jpg', 'https://phimimg.com/upload/vod/20231103-1/3ef48c532d5e500288a28cc91a3b56db.jpg', '<p>Câu chuyện trong phim xoay quanh một người phụ nữ trẻ – Brooke Dalton (Alice thủ vai) – phải bắt chuyến tàu muộn lúc 1:30 đêm để về kịp Boston. Nhưng không may nàng bị cướp và lạc giữa thành phố New York rộng lớn cho đến khi nàng gặp chàng nghệ sĩ trẻ ở sân ga luôn sẵn lòng giúp đỡ. Và một câu chuyện tình mở ra…</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Emma Fitzpatrick","avatar":""},{"name":"Mark Kassen","avatar":""},{"name":"Daniel Spink","avatar":""},{"name":"Elijah Moreland","avatar":""},{"name":"John Cullum","avatar":""},{"name":"Scott Evans","avatar":""},{"name":"Kevin Carolan","avatar":""},{"name":"Fenton Lawless","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
