INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bien-xanh', 'Nhiệm vụ biển xanh', 'Mission Blue', 'https://phimimg.com/upload/vod/20231103-1/c295f9ee3d2e4f84584b9a2be52cb90b.jpg', 'https://phimimg.com/upload/vod/20231103-1/96f2576ae7dfdd23bec9f349cfd95cf7.jpg', '<p>Bộ phim tài liệu theo dấu nhà hải dương học Sylvia Earle trong chiến dịch cứu đại dương trên thế giới khỏi các mối đe dọa như đánh bắt quá mức và chất thải độc hại.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Cameron","avatar":""},{"name":"Michael deGruy","avatar":""},{"name":"Sylvia Earle","avatar":""},{"name":"Bryce Groark","avatar":""},{"name":"Jeremy Jackson","avatar":""},{"name":"Carl Safina","avatar":""},{"name":"Fisher Stevens","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324458);
