INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-diet', 'Tận Diệt', 'Wyrmwood: Road of the Dead', 'https://phimimg.com/upload/vod/20231106-1/c852f378aa7fd318a0e19ed1c8c97817.jpg', 'https://phimimg.com/upload/vod/20231106-1/16310b804509ededeaaa1185b0ddda81.jpg', '<p>Tận Diệt - Wyrmwood: Road Of The Dead: Barry là một thợ máy lành nghề và đảm đương việc gia đình, cuộc sống của gia đình anh bị xáo trộn khi đại dịch thây ma bùng phát. Em gái anh bị bắt bởi một đám người đeo mặt nạ và trang bị vũ khí hung tợn, điều hành bởi một tay bác sĩ quái dị. Trong lúc cô em gái lập kế hoạch bỏ trốn thì Barry cũng lên đường để cứu em mình. Dọc đường, anh gặp một người đàn ông sống sót lưu vong. Cả hai phải tự vũ trang và đồng hành cùng nhau băng qua con đường đầy thây ma, đến vùng rừng núi hoang vu hẻo lánh…</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jay Gallagher","avatar":""},{"name":"Bianca Bradey","avatar":""},{"name":"Leon Burchill","avatar":""},{"name":"Luke McKenzie","avatar":""},{"name":"Yure Covich","avatar":""},{"name":"Catherine Terracini","avatar":""},{"name":"Keith Agius","avatar":""},{"name":"Berryn Schwerdt","avatar":""},{"name":"Cain Thompson","avatar":""},{"name":"Beth Aubrey","avatar":""},{"name":"Sheridan Harbridge","avatar":""},{"name":"Damian Dyke","avatar":""},{"name":"John Michael Burdon","avatar":""},{"name":"Jesse Rowles","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
