INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-singham-tro-la', 'Cảnh Sát Singham Trở Lạ', 'Singham Returns', 'https://phimimg.com/upload/vod/20231103-1/e5de099929f35e9d5e4af24a072c0935.jpg', 'https://phimimg.com/upload/vod/20231103-1/f98b6b332f71c89ebedf8b85cce480c5.jpg', '<p>Singham Returns là một bộ phim hành động Ấn Độ của đạo diễn Rohit Shetty và được sản xuất bởi Reliance Entertainment. Phần tiếp theo của bộ phim Singham năm 2011, nam diễn viên Ajay Devgn đảm nhận vai diễn của anh ấy trong phần phim trước, đồng thời đồng sản xuất dự án, trong khi Kareena Kapoor Khan đóng vai nữ chính.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ajay Devgn","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Amole Gupte","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Vineet Sharma","avatar":""},{"name":"Dayanand Shetty","avatar":""},{"name":"Zakir Hussain","avatar":""},{"name":"Mahesh Manjrekar","avatar":""},{"name":"Sameer Dharmadhikari","avatar":""},{"name":"Pankaj Tripathi","avatar":""},{"name":"Ashwini Kalsekar","avatar":""},{"name":"Sharat Saxena","avatar":""},{"name":"Govind Namdev","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
