INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nhiem-dot-kich', 'Tiền Nhiệm Đột Kích', 'Ex-Files', 'https://phimimg.com/upload/vod/20231111-1/d09a3d83ce3079d91731f2db821f492f.jpg', 'https://phimimg.com/upload/vod/20231111-1/625da8bcebf6e23c8b8bd62190373311.jpg', '<p>Trong đám cưới bạn gái cũ, Mạnh Vân tình cơ quen biết với Hạ Lộ- “bạn gái cũ” của chú rể. Mối tình của hai người gặp phải muôn vàn thử thách do các tình cũ cực phẩm của nhau gây ra. Khi Hạ Lộ hết lần này đến lần khác hóa nguy thành an, lại không ngờ hóa ra La Xuyến – người bạn cụ của Mạnh Vân mới chính là cái bóng khiến cô không thể nào vượt qua. La Xuyến cũng đính hôn với Triệu Minh, một người đàn ông chín chắn, giàu có. Mạnh Vân cũng nhận ra tình cảm thật của mình dành cho La Xuyến. Rốt cuộc tình cảm của họ sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 25, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Geng","avatar":""},{"name":"Anna Yao","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Ryan Zheng Kai","avatar":""},{"name":"Liu Yan","avatar":""},{"name":"Wang Likun","avatar":""},{"name":"Yu Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
