INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('8-tieng-dien-cuong', '8 Tiếng Điên Cuồng', 'Walk of Shame', 'https://phimimg.com/upload/vod/20231103-1/5f4d083c81d86e51cd47e1c191bdd04b.jpg', 'https://phimimg.com/upload/vod/20231103-1/51c3842be1ca5480b24e489f6951d8d2.jpg', '<p>Sau khi trải qua tình một đêm ở L.A, Meghan phải đối mặt với vô số tình huống dở khóc dở cười. Không điện thoại, không xe, không tiền, dính vào các rắc rối và hơn thế nữa, cô chỉ còn 8 tiếng đồng hồ để chuẩn bị cho cuộc phỏng vấn quan trọng nhất trong cuộc đời của mình. Liệu Meghan sẽ làm gì ? Cô có đến kịp buổi phỏng vấn?</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Banks","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Sarah Wright","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Bill Burr","avatar":""},{"name":"Ken Davitian","avatar":""},{"name":"Lawrence Gilliard Jr.","avatar":""},{"name":"Alphonso McAuley","avatar":""},{"name":"Da''Vone McDonald","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Oliver Hudson","avatar":""},{"name":"Jacob Timothy Manown","avatar":""},{"name":"Carol Mansell","avatar":""},{"name":"Bryan Callen","avatar":""},{"name":"Tig Notaro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
