INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-dua-chet-nguoi-3', 'Trò Đùa Chết Người 3', 'Joy Ride 3', 'https://phimimg.com/upload/vod/20231103-1/3ce0f23234d3f73e5541bfd00a4046f6.jpg', 'https://phimimg.com/upload/vod/20231103-1/256cc8a67a289214a91ae7239bb7d811.jpg', '<p>Rusty Nail lại lên đường tìm cách trừng phạt sự bất công ở mọi ngã rẽ - và lần này là với một nhóm tay đua đường phố nóng nảy đang trên đường đến Road Rally 1000. Khi họ lái xe qua một con đường tắt hoang vắng trên đường đến cuộc đua, cuộc gặp gỡ với Rusty trở nên chua chát và ngay sau đó anh ta theo dõi, trêu chọc và tra tấn họ cho đến cuối con đường.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ken Kirzinger","avatar":""},{"name":"Jesse Hutch","avatar":""},{"name":"Benjamin Hollingsworth","avatar":""},{"name":"Gianpaolo Venuta","avatar":""},{"name":"Jake Manley","avatar":""},{"name":"Kirsten Zien","avatar":""},{"name":"Leela Savasta","avatar":""},{"name":"Sara Mitich","avatar":""},{"name":"J. Adam Brown","avatar":""},{"name":"James Durham","avatar":""},{"name":"Dean Armstrong","avatar":""},{"name":"Aaron Hughes","avatar":""},{"name":"David Ferry","avatar":""},{"name":"Scott Johnson","avatar":""},{"name":"Rick Skene","avatar":""},{"name":"Kyle Nobess","avatar":""},{"name":"Heather Hueging","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
