INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-lam-gi-trong-bong-toi', 'Chúng Ta Làm Gì Trong Bóng Tối', 'What We Do in the Shadows', 'null', 'https://phimimg.com/upload/vod/20231102-1/2e40a7d77261cccf2cd92db43b93204e.jpg', '<p>What Do We Do in the Shadows xoay quanh cuộc sống của 4 vampire cùng sống chung. Viago là người chín chắn, điềm tĩnh nhất nhóm, anh chàng ưa sạch sẽ, có lối sống rất quy củ thường là người đánh thức mọi người ngủ dậy, nhắc nhở giữ vệ sinh chung và phân chia công việc nhà. Trong khi đó chàng Vampire bảnh choẹ sát gái Vladislav tuy lớn tuổi thứ 2 trong nhà nhưng lại khá ngây ngô với lối sống cổ hủ rất màu mè. Deacon mới 200 tuổi, một Vampire đang trong tuổi “nổi loạn” bị Viago nhận xét là rất…trẻ trâu, dễ mất bình tĩnh, ham vui và bồng bột. Cuối cùng là một Vampire cổ đại 8000 tuổi với ngoại hình cổ quái cùng lối sống khép kín tên là Petyr, tuy có vẻ đáng sợ nhưng Petyr vẫn được 3 người bạn yêu quý hết mực. 4 người với khoảng cách tuổi tác chênh lệch từ vài trăm đến 8000 năm, với 4 cá tính riêng biệt lâm vào nhiều tình huống dở khóc, dở cười khi cố gắng chung sống hòa hợp với nhau dưới cùng 1 mái nhà và nhịp sống nơi đô thị hiện đại....</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Taika Waititi","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Jonny Brugh","avatar":""},{"name":"Cori Gonzalez-Macuer","avatar":""},{"name":"Stu Rutherford","avatar":""},{"name":"Ben Fransham","avatar":""},{"name":"Jackie van Beek","avatar":""},{"name":"Elena Stejko","avatar":""},{"name":"Jason Hoyte","avatar":""},{"name":"Karen O''Leary","avatar":""},{"name":"Mike Minogue","avatar":""},{"name":"Chelsie Preston Crayford","avatar":""},{"name":"Ian Harcourt","avatar":""},{"name":"Ethel Robinson","avatar":""},{"name":"Brad Harding","avatar":""},{"name":"Isaac Hero","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
