INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-thoat-2014', 'Giải Thoát', 'Set Me Free', 'https://phimimg.com/upload/vod/20231102-1/a761abe47243dac268e77df5085598e9.jpg', 'https://phimimg.com/upload/vod/20231102-1/a9f7ceeb506da0587b60a190b37a2ce6.jpg', '<p>Phim Giải Thoát - Set Me Free 2014 nói về Young-Jae (Choi Woo-Sik) sống tại ngôi nhà chung Isaac&#39;s House. Anh ấy được sống đến năm 17 tuổi và phải rời khỏi ngôi nhà chung. Nhưng anh ấy không muốn trở lại nhà để sống với người bố vô trách nhiệm của mình. Người bên cạnh, Young-Ja vào vai một học sinh gương mẫu và muốn trở thành linh mục. Sự thực thì anh ấy ăn cắp và nói dối bạn bè. Một ngày, bố của Young-Jae đến thăm anh ấy. Bố của anh đã cố gắng dỗ em trai của anh ấy theo anh. Young-Jae đã bùng nổ vì tức giận.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Woo-shik","avatar":""},{"name":"Kim Su-hyun","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Shin Jae-ha","avatar":""},{"name":"Park Joo-hee","avatar":""},{"name":"Lee Min-ah","avatar":""},{"name":"Jang Yoo-sang","avatar":""},{"name":"Park Keun-rok","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Yang Ik-june","avatar":""},{"name":"Seo Gil-ja","avatar":""},{"name":"Yun Seung-hun","avatar":""},{"name":"Bang Eun-jeong","avatar":""},{"name":"Lee Jae-joon","avatar":""},{"name":"Lim Ji-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
