INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-ngoc-gap-nhau-2014', 'Siêu Ngốc Gặp Nhau', 'Dumb and Dumber To', 'https://phimimg.com/upload/vod/20231102-1/6579e44ee5770564932b87998c286d1d.jpg', 'https://phimimg.com/upload/vod/20231102-1/046cb11437676a2c7689e955660365e2.jpg', '<p>Phải đến những hai mươi năm, Jim Carrey và Jeff Daniels mới có cơ hội tái ngộ cùng nhau trong phần hai mang tên</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Laurie Holden","avatar":""},{"name":"Rachel Melvin","avatar":""},{"name":"Kathleen Turner","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Tembi Locke","avatar":""},{"name":"Paul Blackthorne","avatar":""},{"name":"Brady Bluhm","avatar":""},{"name":"Patricia French","avatar":""},{"name":"Steve Tom","avatar":""},{"name":"Don Lake","avatar":""},{"name":"Eddie Shin","avatar":""},{"name":"Atkins Estimond","avatar":""},{"name":"Tommy Snider","avatar":""},{"name":"Lindsay Ayliffe","avatar":""},{"name":"Matthew Cardarople","avatar":""},{"name":"Bill Mur","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
