INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-dem-den', 'Bí Mật Đêm Đen', 'Dark Hearts', 'null', 'https://phimimg.com/upload/vod/20231102-1/163ae9504aa356d1ee6d0f8e941f0167.jpg', '<p>Nội dung phim xoay quanh mối tình lãng mạn giữa Colson, một họa sĩ đang túng quẫn bỗng tìm thấy nàng thơ của mình là cô ca sĩ nóng bỏng Fran. Nhưng sự lãng mạn táo bạo của họ càng lúc càng trở nên mất kiểm soát, rồi bỗng chốc trở thành trò chơi của sự lừa dối và phản bội đầy nguy hiểm. Phim được khen ngợi nhờ xây dựng thành công bầu không khí li kì, hồi hộp và phản ánh được những góc tối trong xã hội hiện đại. Dark Hearts từng nhận được đề cử Phim truyện dài quốc tế hay nhất tại LHP Raindance tổ chức ở London, Anh.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kyle Schmid","avatar":""},{"name":"Sonja Kinski","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Juliet Landau","avatar":""},{"name":"Richard Edson","avatar":""},{"name":"Goran Visnjic","avatar":""},{"name":"Oscar Best","avatar":""},{"name":"Jennifer Barbosa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
