INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-canh-buom-do', 'Mật Mã Cánh Bướm Đỏ', 'Red Butterfly', 'https://phimimg.com/upload/vod/20231109-1/ca862b680d0629e0a7fe4459f531af7d.jpg', 'https://phimimg.com/upload/vod/20231109-1/c038a5f04c49d2703ecd9b158e69e233.jpg', '<p>Một người đàn ông phải tìm ra con đường của mình sau khi phạm một sai lầm nghiêm trọng. Lòng trung thành của Tonio đối với người bạn lâu năm của mình đã trở thành trùm xã hội đen, TC, dẫn đến một loạt các sự kiện với hậu quả chết người. Tonio không thể cứu người yêu của mình, Cleo khỏi chính mình.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diogo Morgado","avatar":""},{"name":"Christine Evangelista","avatar":""},{"name":"Wilson Jermaine Heredia","avatar":""},{"name":"Laurence Mason","avatar":""},{"name":"James A. Stephens","avatar":""},{"name":"Jen Araki","avatar":""},{"name":"Byrdie Bell","avatar":""},{"name":"Chris Riggi","avatar":""},{"name":"Joe Rosario","avatar":""},{"name":"Matt Perfetuo","avatar":""},{"name":"Mike Perfetuo","avatar":""},{"name":"Teddy Cañez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
