INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-phia-truoc', 'Con Đường Phía Trước', 'The Road Within', 'https://phimimg.com/upload/vod/20231101-1/c26b0c10e496fc186e72ef20ac6079bd.jpg', 'https://phimimg.com/upload/vod/20231101-1/0707b77aa63e3dcf0b4e1faf0dd5d13c.jpg', '<p>Một người đàn ông trẻ mắc Hội chứng Tourette bắt đầu một chuyến đi trên đường cùng với tro cốt của người mẹ vừa qua đời của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Sheehan","avatar":""},{"name":"Dev Patel","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Ali Hillis","avatar":""},{"name":"Jim Calvert","avatar":""},{"name":"Louisa Kendrick","avatar":""},{"name":"Ross Gallo","avatar":""},{"name":"Cooper Roth","avatar":""},{"name":"Jayce Dempsey","avatar":""},{"name":"Eleanor Wells","avatar":""},{"name":"Joe Unger","avatar":""},{"name":"Eric Matheny","avatar":""},{"name":"Matt Riedy","avatar":""},{"name":"Alejandro Romero","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
