INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-nguoi-linh', 'Tôi Là Người Lính', 'I Am Soldier', 'https://phimimg.com/upload/vod/20231101-1/e625b571d71861be53926b29a9b8ddcf.jpg', 'https://phimimg.com/upload/vod/20231101-1/7359f150b0f081b514080291e841782b.jpg', '<p>Mickey Tomlinson, một đầu bếp quân đội, cố gắng thực hiện cuộc tuyển chọn quân sự nguy hiểm nhất mà con người từng biết: Cuộc tuyển chọn của Lực lượng Hàng không Đặc biệt (S.A.S.). S.A.S. Là Trung đoàn Lực lượng Đặc biệt nổi tiếng nhất của Vương quốc Anh, được giao nhiệm vụ đe dọa tính mạng ở một số nơi nguy hiểm nhất hành tinh. Mickey có nhiều kinh nghiệm quân sự hơn là chỉ đơn giản là trở thành một đầu bếp, điều mà các ứng cử viên khác không cho phép... Mickey bị phá vỡ bởi quá trình lựa chọn này - tâm trí, cơ thể và linh hồn của anh ấy kêu gào sự thương xót khi anh ấy phải chịu đựng những cuộc hành quân thần tốc đầy tra tấn. những ngọn núi dốc nhất, chạy thục mạng trong quá trình &#39;Trốn thoát và Trốn tránh&#39; và sau đó đối mặt với cuộc thẩm vấn độc ác nhất có thể, trong giai đoạn chết người được gọi là: &#39;Câu hỏi Chiến thuật&#39;. Ngay cả sau tất cả, vẫn chỉ có một cách duy nhất để bạn có thể thực sự chứng tỏ bản thân: trong chiến đấu... Nhiều người cố gắng gia nhập S.A.S. Chỉ có giới thượng lưu làm cho nó.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Noel Clarke","avatar":""},{"name":"Philip Desmeules","avatar":""},{"name":"Duncan Casey","avatar":""},{"name":"Lee Charles","avatar":""},{"name":"Jordan Long","avatar":""},{"name":"Allistair McNab","avatar":""},{"name":"Josh Myers","avatar":""},{"name":"Ian Pirie","avatar":""},{"name":"Tom Hughes","avatar":""},{"name":"Miranda Raison","avatar":""},{"name":"Alex Reid","avatar":""},{"name":"George Russo","avatar":""},{"name":"Joe Egan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324458);
