INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-khoi-lang-que', 'Thoát Khỏi Làng Quê', 'Cut Bank', 'https://phimimg.com/upload/vod/20231101-1/d3260f972327c0f65c8744e8bdec3964.jpg', 'https://phimimg.com/upload/vod/20231101-1/52772cd5538142fcac668557f4a769a1.jpg', '<p>Dwayne McLaren, 25 tuổi, một cựu vận động viên trở thành thợ sửa ô tô, mơ ước được ra khỏi thị trấn lạnh giá nhất nước Mỹ Cut Bank, Montana. Nhưng nỗ lực của anh ấy để làm như vậy đã tạo ra một loạt các sự kiện chết chóc làm thay đổi cuộc đời anh ấy và cuộc sống của thị trấn mãi mãi ...</p>', 'Full', 1, 'single', 'completed', 22, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Hemsworth","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Peyton Kennedy","avatar":""},{"name":"Marie Zydek","avatar":""},{"name":"Kristin Scott","avatar":""},{"name":"Sophia Mora","avatar":""},{"name":"Maya Molly","avatar":""},{"name":"Em Siobhan McCourt","avatar":""},{"name":"Kris Loranger","avatar":""},{"name":"Chris Krueger","avatar":""},{"name":"Mikaela Cochr","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
