INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-chieu-phai-dep', 'Tuyệt Chiêu Phái Đẹp', 'Women Who Flirt', 'https://phimimg.com/upload/vod/20231101-1/a8ab7da2c2a641fce4863b5c471a28c0.jpg', 'https://phimimg.com/upload/vod/20231101-1/42681c469e1457dc61903e0f54066209.jpg', '<p>Bộ phim là câu chuyện tình tay ba hết sức thú vị với những tình huống hài hước nhưng cũng đầy kịch tính. Nhân vật chính là cô nàng tomboy Trương Tuệ vì cảm nắng anh bạn học cùng từ đại học Tiểu Cung mà quyết định thay đổi bản thân, đặc biệt từ khi có sự xuất hiện của kiều nữ xứ Đài với vẻ đẹp đáng yêu “chết người” – Bội Bội.
 Bội Bội là một vai diễn mắt xích trong phim vì nhờ có cô mà Trương Tuệ mới quyết định thay đổi mình, từ phong cách tomboy sang nữ tính, dịu dàng và quyết tâm khổ luyện kỹ thuật “nhõng nhẽo” để cưa đổ anh chàng Tiểu Cung. Và rồi Tiểu Cung sẽ có sự lựa chọn như thế nào? Tomboy cá tính hay nữ tính dịu dàng?</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Xun","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Sonia Sui","avatar":""},{"name":"Xie Yi-lin","avatar":""},{"name":"Choenyi Tsering","avatar":""},{"name":"Michael Kai Sui","avatar":""},{"name":"Cady Yang","avatar":""},{"name":"Long De","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
