INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-du-con', 'Anh Hùng Du Côn', 'Black and White: The Dawn of Justice', 'https://phimimg.com/upload/vod/20231101-1/1332f62d5eca9c3127a6564c98fcd53c.jpg', 'https://phimimg.com/upload/vod/20231101-1/345da42e3941b1510fbaf69c93f76aff.jpg', '<p>Phim Anh Hùng Du Côn theo chân hai anh chàng cảnh sát với hai tính cách hoàn toàn trái ngược, Ngô Anh Hùng (Triệu Hựu Đình) ngay thẳng nhưng bốc đồng cùng với Trần Tăng (Lâm Canh Tân) kiêu ngạo nhưng thông minh, cùng với nhau họ khám phá ra nhiều âm mưu nguy hiểm đằng sau những vụ đánh bom nhỏ lẻ ở thành phố Cảng. Họ sẽ cùng nhau tạo ra nhiều tình huống oái ăm, hài hước và những pha hành động đẹp mắt cùng với kỹ xảo đến từ những nhà làm phim Hollywood.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Mark Chao","avatar":""},{"name":"Lin Gengxin","avatar":""},{"name":"Shiou Chieh Kai","avatar":""},{"name":"Janine Chang","avatar":""},{"name":"Huang Bo","avatar":""},{"name":"Jason Tsou","avatar":""},{"name":"Terri Kwan","avatar":""},{"name":"Tsai Yueh-Hsun","avatar":""},{"name":"Guli Nazha","avatar":""},{"name":"Mandy Lieu","avatar":""},{"name":"Christopher Lee Ming-Shun","avatar":""},{"name":"Jerry Yan Cheng-Xu","avatar":""},{"name":"Yin Chao-Te","avatar":""},{"name":"Chen Handian","avatar":""},{"name":"Moon Wang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
