INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-lui-tan', 'Ánh Sáng Lụi Tàn', 'Dying of the Light', 'https://phimimg.com/upload/vod/20231101-1/0b6b97afba122680f9ad6ce502abe2de.jpg', 'https://phimimg.com/upload/vod/20231101-1/6a43e56f90d474eab746c7a615bcbfea.jpg', '<p>Evan Lake, một điệp viên kỳ cựu của CIA, đã được lệnh nghỉ hưu. Nhưng khi người bảo trợ của anh ta phát hiện ra bằng chứng cho thấy kẻ thù của Lake, tên khủng bố Banir, đã tái xuất hiện, Lake trở nên bất hảo, bắt tay vào một nhiệm vụ xuyên lục địa đầy nguy hiểm để loại bỏ kẻ thù không đội trời chung của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Bahamas', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Alexander Karim","avatar":""},{"name":"Irène Jacob","avatar":""},{"name":"Aymen Hamdouchi","avatar":""},{"name":"Tomiwa Edun","avatar":""},{"name":"Claudius Peters","avatar":""},{"name":"Robert G. Slade","avatar":""},{"name":"Derek Ezenagu","avatar":""},{"name":"Geff Francis","avatar":""},{"name":"Tim Silano","avatar":""},{"name":"Silas Carson","avatar":""},{"name":"Șerban Celea","avatar":""},{"name":"David Lipper","avatar":""},{"name":"Ovidiu Niculescu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
