INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-nho-hathu', 'Khu Rừng Nhỏ - Hạ/Thu', 'Little Forest: Summer/Autumn', 'https://phimimg.com/upload/vod/20231101-1/18da8f747350f2574b820d968e9bfd20.jpg', 'https://phimimg.com/upload/vod/20231101-1/f3a0b14053320db96508b623d60fe5b7.jpg', '<p>Ichiko, sống ở một thành phố lớn, trở về quê nhà Komori, nằm ở miền núi thuộc vùng Tohoku. Hàng ngày sống tự cung tự cấp giữa thiên nhiên và nấu những món ăn làm từ các nguyên liệu theo mùa, Ichiko dần lấy lại được sinh lực cho cuộc sống.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Hashimoto","avatar":""},{"name":"Takahiro Miura","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Yoichi Nukumizu","avatar":""},{"name":"Karen Kirishima","avatar":""},{"name":"Momone Shinokawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
