INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hacker-sieu-dang', 'Hacker Siêu Đẳng', 'Who Am I', 'https://phimimg.com/upload/vod/20231101-1/b7c1ea1b1c9ea864c365374573bd8ecc.jpg', 'https://phimimg.com/upload/vod/20231101-1/a5a60bd8e5eac82a07c977c1d3c8cc9b.jpg', '<p>Benjamin, một tay máy tính trẻ tuổi người Đức, được mời tham gia một nhóm hacker lật đổ muốn được chú ý trên sân khấu thế giới.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Tom Schilling","avatar":""},{"name":"Elyas M''Barek","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Antoine Monot Jr.","avatar":""},{"name":"Hannah Herzsprung","avatar":""},{"name":"Trine Dyrholm","avatar":""},{"name":"Stephan Kampwirth","avatar":""},{"name":"Leopold Hornung","avatar":""},{"name":"Katharina Matz","avatar":""},{"name":"Marten Borgwardt","avatar":""},{"name":"Leonard Carow","avatar":""},{"name":"Antonia Putiloff","avatar":""},{"name":"Agnes Thi-Mai","avatar":""},{"name":"Lena Dörrie","avatar":""},{"name":"David Masterson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
