INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-kich-dong', 'Tín Hiệu Kích Động', 'The Signal', 'https://phimimg.com/upload/vod/20231101-1/48eec40ba32d161d13048f8ba2caea10.jpg', 'https://phimimg.com/upload/vod/20231101-1/3f33ca187cc4c5ead10cf43fe76866fe.jpg', '<p>Tín Hiệu Kích Động kể về Nick và Jonah là các tân sinh viên của Viện công nghệ Massachusetts với 1 lòng yêu thích được trở thành những hacker tài ba. Trong 1 lần cùng đi chơi xa có cô bạn gái của Nick, họ tình cờ lần theo dấu tích của tay hacker đối thủ và chọn ra 1 địa điểm bí mật. Sau 1 cuộc chạm trán nảy lửa giữa hoang mạc, cả ba người thức giấc dậy và phát hiện mình đang bị cầm tù, và cả chuyện này là một âm mưu to hơn cả hình dung của họ.</p>', 'Full', 1, 'single', 'completed', 22, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brenton Thwaites","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Jeffrey Grover","avatar":""},{"name":"Patrick Davidson","avatar":""},{"name":"Roy Kenny","avatar":""},{"name":"Timothy Holmes","avatar":""},{"name":"Ricardo Campos","avatar":""},{"name":"Drew Sykes","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324458);
