INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-khach-kenshin-3-ket-thuc-mot-huyen-thoai', 'Lãng Khách Kenshin 3: Kết Thúc Một Huyền Thoại', 'Rurouni Kenshin: The Legend Ends', 'https://phimimg.com/upload/vod/20231101-1/1a465580a2a0e15234aa0055979f459b.jpg', 'https://phimimg.com/upload/vod/20231101-1/ad48e9ebbc6544d6bd72994a4e5da757.jpg', '<p>Cuộc chiến của hai kiếm khách huyền thoại Rurouni Kenshin và Shishio Makoto đã đến hồi căng thẳng. Shishio đưa chiến hạm của mình về hướng Tokyo, với mục đích lật đổ chính phủ Minh Trị, đưa Nhật Bản trở về thời biến lọan. Kenshin gặp muôn vàn khó khăn và suýt bỏ mạng khi chiến đấu với hỏa kiếm hủy diệt của Shishio cũng như các phong cách chiến đấu đa dạng của lũ tay sai dưới trướng hắn. Để ngăn cản Shishio, Himura Kenshin buộc phải tìm được đến sư phụ dạy kiếm thuật của mình để học tuyệt chiêu cuối cùng của phái Phi Thiên Ngự Kiếm...</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeru Satoh","avatar":""},{"name":"Emi Takei","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Kaito Oyagi","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Tao Tsuchiya","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Kazufumi Miyazawa","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Kenichi Takitoh","avatar":""},{"name":"Ryosuke Miura","avatar":""},{"name":"Tomomi Maruyama","avatar":""},{"name":"Maryjun Takahashi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324458);
