INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-cuop-ngan-hang', 'Phi Vụ Cướp Ngân Hàng', 'Son of a Gun', 'https://phimimg.com/upload/vod/20231101-1/73d1856c7e40e36256895630a517d0c6.jpg', 'https://phimimg.com/upload/vod/20231101-1/68deac0385faa9e7f23500e09ae8c006.jpg', '<p>Phi Vụ Cướp Ngân Hàng - Son Of A Gun: Một tội phạm vị thành niên, JR 19 tuổi nhanh chóng học được những thực tế khắc nghiệt của cuộc sống tù. lọt vào mắt của một tội phạm khét tiếng nhất của Australia. Sau khi ra tù, cả nhóm lên kế hoạch cướp một ngân hàng.</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Brenton Thwaites","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Jacek Koman","avatar":""},{"name":"Matt Nable","avatar":""},{"name":"Tom Budge","avatar":""},{"name":"Nash Edgerton","avatar":""},{"name":"Damon Herriman","avatar":""},{"name":"Eddie Baroo","avatar":""},{"name":"Marko Jovanović","avatar":""},{"name":"Sam Hutchin","avatar":""},{"name":"Lucas Brown","avatar":""},{"name":"Jesse McGinn","avatar":""},{"name":"Brendan Kerkvliet","avatar":""},{"name":"Matt Flannagan","avatar":""},{"name":"Geoff Kelso","avatar":""},{"name":"Peter Neaves","avatar":""},{"name":"Kazimi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
