INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-thu-hoang-toc', 'Mối Thù Hoàng Tộc', 'Outcast', 'https://phimimg.com/upload/vod/20231029-1/847a43bd788090924fa65102592e2a7a.jpg', 'https://phimimg.com/upload/vod/20231029-1/35f994cd1d7ba54dc5dc10f8f2ca6ad4.jpg', '<p>Một chiến binh bí ẩn hợp tác với con gái và con trai của một Hoàng đế Trung Quốc bị phế truất để đánh bại người anh trai độc ác của họ, kẻ đang tìm kiếm cái chết của họ.</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Hayden Christensen","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Summer Jike","avatar":""},{"name":"Andy On","avatar":""},{"name":"Anoja Dias Bolt","avatar":""},{"name":"Byron Lawson","avatar":""},{"name":"Fernando Chien","avatar":""},{"name":"Jawed El Berni","avatar":""},{"name":"Preston Baker","avatar":""},{"name":"Ron Smoorenburg","avatar":""},{"name":"Alaa Safi","avatar":""},{"name":"Paul Philip Clark","avatar":""},{"name":"Manel Soler","avatar":""},{"name":"Daxing Zhang","avatar":""},{"name":"Max Huang","avatar":""},{"name":"Jack Tu","avatar":""},{"name":"Vander McLeod","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
