INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-lac-gioi', 'Câu Lạc Bộ Lạc Giới', 'The Torture Club', 'https://phimimg.com/upload/vod/20231029-1/2353183ca4e88b4fe472b43169ce674f.jpg', 'https://phimimg.com/upload/vod/20231029-1/6bbcabc52921674bf3fa53cd574e4b0f.jpg', '<p>Nội dung xoay quanh một câu lạc bộ đặc biệt chuyên đào tạo về tra tấn, nó phục vụ sau này cho các lĩnh vực về quân sự, các chuyên gia thẩm vấn cũng như cảnh sát và hoạt động một cách bí mật. Đặc biệt, các thành viên ở đây tất cả đều là nữ mà không có bất kỳ nam giới nào, tại đây đa phần đều là những nữ sinh trẻ xinh đẹp với khả năng chịu đựng rất tốt. Trong đó, Aoi Funaki (Haruna Yoshizumi) chính là người cầm đầu cũng như đào tạo cho nhiều nữ sinh tại đây.</p>', 'Full', 1, 'single', 'completed', 20, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Noriko Kijima","avatar":""},{"name":"Haruna Yoshizumi","avatar":""},{"name":"Yuki Mamiya","avatar":""},{"name":"Mika Yano","avatar":""},{"name":"Nami Motoyama","avatar":""},{"name":"Kanako Mochida","avatar":""},{"name":"Reiko Hayama","avatar":""},{"name":"Shungicu Uchida","avatar":""},{"name":"Rei Mizuna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
