INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-cac-quy-ong', 'Bí Mật Của Các Quý Ông', 'The Loft', 'https://phimimg.com/upload/vod/20231030-1/44edeeca0c807ffe9738a6b0ca01108d.jpg', 'https://phimimg.com/upload/vod/20231030-1/e6beb44ab4971166fdc58f247cd8ed0d.jpg', '<p>Đối với năm người đàn ông, cơ hội ở chung một căn hộ áp mái trong thành phố - nơi để thực hiện các cuộc tình ngoài hôn nhân - là một giấc mơ trở thành hiện thực, cho đến khi xác chết của một người phụ nữ vô danh xuất hiện. Nhận ra rằng kẻ giết cô phải là một người trong nhóm của họ, những người đàn ông bị hoang tưởng khi mỗi người nghi ngờ người khác. Tình bạn bị thử thách, lòng trung thành bị nghi ngờ, và hôn nhân tan vỡ trong khi nỗi sợ hãi và nghi ngờ tràn lan.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Karl Urban","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"Isabel Lucas","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Valerie Cruz","avatar":""},{"name":"Kali Rocha","avatar":""},{"name":"Elaine Cassidy","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Kristin Lehman","avatar":""},{"name":"Robert Wisdom","avatar":""},{"name":"Dora Madison","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Astr","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
