INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-mau-cuu-binh', 'Bão Mẫu Cựu Binh', 'St. Vincent', 'https://phimimg.com/upload/vod/20231030-1/bd9910f5105e86d6e2ca6605340c3ce4.jpg', 'https://phimimg.com/upload/vod/20231030-1/24a89a944db836f38bc1e224d1748cc9.jpg', '<p>Annie Erin Clark, được biết đến với nghệ danh St. Vincent, là một nhạc sĩ, ca sĩ, nhạc sĩ và nhà sản xuất người Mỹ. Cô bắt đầu sự nghiệp âm nhạc của mình với tư cách là thành viên của Polyphonic Spree. Cô cũng là thành viên của ban nhạc lưu diễn của Sufjan Stevens trước khi thành lập ban nhạc của riêng mình vào năm 2006.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Jaeden Martell","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Lenny Venito","avatar":""},{"name":"Nate Corddry","avatar":""},{"name":"Dario Barosso","avatar":""},{"name":"Kimberly Quinn","avatar":""},{"name":"Donna Mitchell","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Deirdre O''Connell","avatar":""},{"name":"Ray Iannicelli","avatar":""},{"name":"Greta","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
