INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sach-ma', 'Sách Ma', 'The Babadook', 'https://phimimg.com/upload/vod/20231030-1/f86fe3ff083fea1a4d816ca32758ad34.jpg', 'https://phimimg.com/upload/vod/20231030-1/2bdab413ecce7e45f198961708f31c17.jpg', '<p>The Babadook được truyền cảm hứng từ những bộ phim kinh dị điển hình của thập niên 30 thế kỷ 20, nữ đạo diễn Jennifer Kent đã tài tình sử dụng một ngân sách hết sức hạn chế để tạo nên một câu chuyện đầy ám ảnh trong một tông màu ảm đạm u tối. Nhân vật chính của phim Sách Ma là bà mẹ đơn thân Amelia, vài năm sau cái chết đột ngột của người chồng, cô gặp rắc rối trong việc nuôi dạy đứa con trai 6 tuổi Sam khi cậu bé liên tục kể về một sinh vật bí ẩn đeo bám cả hai mẹ con. Rồi một ngày trong nhà họ xuất hiện một cuốn sách mang tựa đề “Mr. Babadook” kể về một sinh vật kinh hoàng như thể ông kẹ. Khi Amelia đọc cho Sam nghe cuốn sách đó vào mỗi tối, thì dường như Babadook cũng đang dần dần bước ra từ những trang sách và mối đe dọa từ nó cũng trở thành sự thật mà hai mẹ con cô phải đối mặt. Và đó cũng là lúc những bí mật khủng khiếp trong quá khứ của gia đình Amelia bắt đầu được hé lộ.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Essie Davis","avatar":""},{"name":"Noah Wiseman","avatar":""},{"name":"Hayley McElhinney","avatar":""},{"name":"Daniel Henshall","avatar":""},{"name":"Barbara West","avatar":""},{"name":"Ben Winspear","avatar":""},{"name":"Cathy Adamek","avatar":""},{"name":"Craig Behenna","avatar":""},{"name":"Hachi","avatar":""},{"name":"Tim Purcell","avatar":""},{"name":"Chloe Hurn","avatar":""},{"name":"Jacquy Phillips","avatar":""},{"name":"Bridget Walters","avatar":""},{"name":"Adam Morgan","avatar":""},{"name":"Pippa Wanganeen","avatar":""},{"name":"Peta Shannon","avatar":""},{"name":"Michelle Nightingale","avatar":""},{"name":"Ton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
