INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho-5', 'Vũ Điệu Đường Phố 5', 'Step Up All In', 'https://phimimg.com/upload/vod/20231029-1/699776ff62419540bab75c4dd991d739.jpg', 'https://phimimg.com/upload/vod/20231029-1/a1352e7caf326bada9071edb012b6d3c.jpg', '<p>Lần này các nhóm nhảy cùng tụ hội về Las Vegas, nơi có sân khấu hào nhoáng và khốc liệt nhất nước Mỹ để tham gia vào cuộc tranh tài mang tên Vortex. Phần thưởng dành cho nhóm chiến thắng là hợp đồng biểu diễn chuyên nghiệp trong suốt 3 năm tại kinh đô giải trí của Mỹ. Hiển nhiên, con đường chinh phục ước mơ nào cũng là chặng đường của những khổ luyện, quyết tâm và không thể thiếu những giá trị cốt lõi của cuộc sống. Cùng với nhau, cùng với những bước nhảy của đam mê, họ chia sẻ tình bạn, tình yêu và khát khao tuổi trẻ. Bộ phim hội tụ nhiều gương mặt quen thuộc từ các phần trước của loạt phim Step Up trong một đại tiệc của âm nhạc và vũ đạo đỉnh cao.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Briana Evigan","avatar":""},{"name":"Ryan Guzman","avatar":""},{"name":"Chaton Anderson","avatar":""},{"name":"Stephen ''tWitch'' Boss","avatar":""},{"name":"Misha Gabriel","avatar":""},{"name":"Izabella Miko","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Adam Sevani","avatar":""},{"name":"Chadd Smith","avatar":""},{"name":"Christopher Scott","avatar":""},{"name":"Mari Koda","avatar":""},{"name":"Stephen Stevo Jones","avatar":""},{"name":"David Shreibman","avatar":""},{"name":"Luis Rosado","avatar":""},{"name":"Facundo Lombard","avatar":""},{"name":"Martín L","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324458);
