INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-ngu-say', 'Tội Ác Ngủ Say', 'Before I Go to Sleep', 'https://phimimg.com/upload/vod/20231029-1/dc0aa67974fab3ba3f44595c2cf8a25f.jpg', 'https://phimimg.com/upload/vod/20231029-1/f4ceacdc167e2b7c1a7c3089043cd579.jpg', '<p>Ben Lucas và bác sĩ Nash đều tìm cách giúp đỡ vợ Ben lấy lại ký ức nhưng thực chất cả hai người này đều đang giấu giếm nhiều.</p>', 'Full', 1, 'single', 'completed', 29, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Anne-Marie Duff","avatar":""},{"name":"Jing Lusi","avatar":""},{"name":"Ben Crompton","avatar":""},{"name":"Flynn MacArthur","avatar":""},{"name":"Gabriel Strong","avatar":""},{"name":"Adam Levy","avatar":""},{"name":"Dean-Charles Chapman","avatar":""},{"name":"Rosie MacPherson","avatar":""},{"name":"Steve Munroe","avatar":""},{"name":"Kevin Hudson","avatar":""},{"name":"Samantha Kelly","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324458);
