INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-dracula-huyen-thoai-chua-ke', 'Ác Quỷ Dracula: Huyền Thoại Chưa Kể', 'Dracula Untold', 'https://phimimg.com/upload/vod/20231029-1/a2326e0207441a8d0082326dc22829bc.jpg', 'https://phimimg.com/upload/vod/20231029-1/300acc24b483b5b07f1d4f6acaca0fa7.jpg', '<p>Dracula Untold là bộ phim đầu tay của đạo diễn Shore và anh đã có hướng đi táo bạo khi cố gắng kể một câu chuyện hoàn toàn mới chứ không dựa trên nguyên tác Dracula kinh điển của nhà văn Bram Stoker. Nhân vật chính của phim là hoàng tử Vlad (Luke Evans thủ vai), người cai trị xứ Transylvania vốn chịu ảnh hưởng lớn từ đế quốc Thổ Nhĩ Kỳ. Trong quá khứ, Vlad từng được cha gửi gắm vào quân đội xứ Thổ và tạo dựng danh tiếng như một chiến binh bất khả chiến bại. Trở lại quê hương trên cương vị người đứng đầu, anh quyết tâm bảo vệ gia đình gồm vợ và con trai cùng thần dân trước mọi kẻ địch.Tuy nhiên, ý chí đó lại bị thách thức bởi người đứng đầu đế chế Thổ hùng mạnh Mehmed II (Dominic Cooper). Vị Sultan (Vua) này ra ...</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Evans","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Art Parkinson","avatar":""},{"name":"Diarmaid Murtagh","avatar":""},{"name":"Ronan Vibert","avatar":""},{"name":"William Houston","avatar":""},{"name":"Ferdinand Kingsley","avatar":""},{"name":"Zach McGowan","avatar":""},{"name":"Paul Kaye","avatar":""},{"name":"Thor Kristjansson","avatar":""},{"name":"Arkie Reece","avatar":""},{"name":"Noah Huntley","avatar":""},{"name":"Joseph Long","avatar":""},{"name":"Jakub Gierszał","avatar":""},{"name":"Joe Benjamin","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324458);
