INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ac-quy-dracula-huyen-thoai-chua-ke', 'Ác Quỷ Dracula: Huyền Thoại Chưa Kể', 'Dracula Untold', 'ác quỷ dracula: huyền thoại chưa kể dracula untold luke evans dominic cooper sarah gadon charles dance art parkinson diarmaid murtagh ronan vibert william houston ferdinand kingsley zach mcgowan paul kaye thor kristjansson arkie reece noah huntley joseph long jakub gierszał joe benjamin p ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-duc-vong', 'Ám Ảnh Dục Vọng', 'Obsessed', 'https://phimimg.com/upload/vod/20231030-1/8ffcc810db637bf1700e1fbdb16c70d7.jpg', 'https://phimimg.com/upload/vod/20231030-1/5534071f03a904463fc2d0f83535f2f6.jpg', '<p>Bối cảnh của phim được lấy vào năm 1969, nội dung xoay quanh đại tá Kim Jin-Pyeong, người mới trở về Hàn Quốc sau khi đi đánh thuê cho quân đội Mỹ trong Chiến tranh Việt Nam. Anh được chỉ huy quân đội cũng là cha vợ của mình và hầu hết mọi người trong căn cứ quân sự kính trọng. Tuy nhiên, Kim Jin-Pyeong cũng gặp phải những tổn thương bên trong do hậu quả của chiến tranh. &nbsp;Một ngày nọ, Kyung Woo-Jin được chuyển sang làm việc cho Kim Jin-Pyeong. Kyung Woo-Jin là kiểu người sẽ nói hoặc làm bất cứ điều gì để làm hài lòng cấp trên của mình. Chẳng bao lâu, đại tá Kim Jin-Pyeong gặp Jong Ga-Heun, vợ của cấp dưới mới của anh. Hai vợ chồng cấp dưới cũng mới chuyển đến ngôi nhà bên kia đường của nhà đại tá Kim Jin-Pyeong và vợ. Vào một buổi tối định mệnh, đại tá Kim Jin-Pyeong chơi đùa với một con chim nhốt trên hiên nhà của hàng xóm, đó cũng là khoảnh khắc mà anh và Jong Ga-Heun trao trái tim cho nhau ngay từ cái nhìn đầu tiên, để rồi phát triển một mối quan hệ vụng trộm không đúng đắn…</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Seung-heon","avatar":""},{"name":"Lim Ji-yeon","avatar":""},{"name":"Cho Yeo-jeong","avatar":""},{"name":"On Ju-wan","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Park Hyeok-kwon","avatar":""},{"name":"Kim Hye-na","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Ye Soo-jung","avatar":""},{"name":"Han Ha-yoo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
