INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-may-bay-anh-hung-bien-lua', 'Thế Giới May Bay: Anh Hùng & Biển Lửa', 'Planes: Fire & Rescue', 'https://phimimg.com/upload/vod/20231030-1/fcb2fa70e08fd3645eeca4cfd4679234.jpg', 'https://phimimg.com/upload/vod/20231030-1/4820aeb820bed7fa8f7c0b530c1e9315.jpg', '<p>Planes 2: Anh hùng và biển lửa là một bộ phim hoạt hình 3D phiêu lưu hài hước dựng bằng máy tính của Mỹ năm 2014. Đây là phần tiếp theo của Thế giới máy bay, một bộ phim ngoại truyện năm 2013 thuộc thương hiệu Vương quốc xe hơi của Pixar.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Harris","avatar":""},{"name":"Dane Cook","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Curtis Armstrong","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Hal Holbrook","avatar":""},{"name":"Teri Hatcher","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Barry Corbin","avatar":""},{"name":"Regina King","avatar":""},{"name":"Anne Meara","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Dale Dye","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324458);
