INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thien-chua', 'Con Thiên Chúa', 'Son of God', 'https://phimimg.com/upload/vod/20231030-1/155496f5b8521a53e91963c37d429ed3.jpg', 'https://phimimg.com/upload/vod/20231030-1/edd0a373324b093ed3dd32a56969a90d.jpg', '<p>Son Of God kể về cuộc đời Chúa Jesus, từ sự giáng sinh thấp hèn, sự dạy dỗ, cho đến cái chết của Ngài trên thập tự giá.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Roma Downey","avatar":""},{"name":"Diogo Morgado","avatar":""},{"name":"Louise Delamere","avatar":""},{"name":"Darwin Shaw","avatar":""},{"name":"Amber Rose Revah","avatar":""},{"name":"Andrew Brooke","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"William Houston","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Stewart Scudamore","avatar":""},{"name":"Conan Stevens","avatar":""},{"name":"Matthew Gravelle","avatar":""},{"name":"Greg Hicks","avatar":""},{"name":"Adrian Schiller","avatar":""},{"name":"Sebastian Knapp","avatar":""},{"name":"Joe Wredden","avatar":""},{"name":"Paul Marc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
