INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-sieu-anh-hung-bi-mat-black-widow-va-punisher', 'Biệt Đội Siêu Anh Hùng Bí Mật: Black Widow và Punisher', 'Avengers Confidential: Black Widow & Punisher', 'https://phimimg.com/upload/vod/20231030-1/1e1afb7e33282dd4b5f7756f72a6e308.jpg', 'https://phimimg.com/upload/vod/20231030-1/699269dedd1b86f2ee634d2a7bfe5821.jpg', '<p>Sau khi can thiệp vào một nhiệm vụ tối mật, The Punisher bị tạm giữ bởi SHIELD AGENT và AVENGER, Black Widow. Punisher và Black Widow được gửi trên một nhiệm vụ để ngăn chặn Leviathan, một tổ chức khủng bố toàn cầu, đang định bán công nghệ bị đánh cắp cho người trả giá cao nhất. Bây giờ, cảnh vệ và điệp viên phải làm việc cùng nhau để ngăn chặn công nghệ này khỏi rơi vào tay kẻ xấu. Số phận của thế giới, và của The Avengers bị rơi vào tình trạng ngàn cân treo sợi tóc.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2014, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miyuki Sawashiro","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Hideaki Tezuka","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Ryuuzaburou Ootomo","avatar":""},{"name":"Junko Minagawa","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Masashi Sugawara","avatar":""},{"name":"Yuichi Karasuma","avatar":""},{"name":"Hisashi Izumi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"John Eric Bentley","avatar":""},{"name":"Grant George","avatar":""},{"name":"Kyle H","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1