INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-em-o-lai', 'Nếu Em Ở Lại', 'If I Stay', 'https://phimimg.com/upload/vod/20231026-1/4bc220a18a8261e9ae8e77114682ff24.jpg', 'https://phimimg.com/upload/vod/20231026-1/430c19268f9b4e2309aeba8d7c796103.jpg', '<p>Mia gặp một tai nạn khủng khiếp trên đường đến nhà ông bà. Mặc dù Mia rơi vào trạng thái hôn mê, cô ấy đã có một trải nghiệm ngoài cơ thể và nhận ra rằng cô ấy phải đưa ra một lựa chọn thay đổi cuộc sống.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Jamie Blackley","avatar":""},{"name":"Liana Liberato","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Gabrielle Rose","avatar":""},{"name":"Jakob Davies","avatar":""},{"name":"Ali Milner","avatar":""},{"name":"Aisha Hinds","avatar":""},{"name":"Gabrielle Cerys Haslett","avatar":""},{"name":"Lauren Lee Smith","avatar":""},{"name":"Adam Solomonian","avatar":""},{"name":"John Emmet Tracy","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Christine","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
