INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-paddington', 'Gấu Paddington', 'Paddington', 'https://phimimg.com/upload/vod/20231026-1/dd6a78b3a9d29556df9b5fd22742b219.jpg', 'https://phimimg.com/upload/vod/20231026-1/c03a04b6e95ddcc131bc51ba18acae65.jpg', '<p>PADDINGTON kể về một chú gấu con với một niềm đam mê to lớn về nước Anh, đã một mình chu du đến tận Luân Đôn để tìm cho mình một mái nhà. Nhưng chú nhanh chóng nhận ra mình bị lạc trong nhà ga Paddington, và may mắn được gia đình nhà Brown tốt bụng đưa về nhà họ ở tạm, và bà Brown đặt tên cho chú là Paddington.
 Những hành động và cư xử kì lạ của Paddington do chưa quen với cuộc sống mới gây cho nhà Brown và những người xung quanh nhiều phiền toái và những tình huống trớ trêu. Nhưng bọn trẻ nhà Brown yêu mến chú và chính Paddington cũng dần cảm nhận mình trở thành một thành viên của gia đình. Đúng lúc đó thì người phụ nữ bí ẩn Milicient (Nicole Kidman) dường như có liên quan đến quá khứ và chiếc nón bất li thân của Paddington xuất hiện và đe dọa thử thách tình cảm gia đình mà Paddington vừa khó khăn tìm được.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ben Whishaw","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Madeleine Harris","avatar":""},{"name":"Samuel Joslin","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Peter Capaldi","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Madeleine Worrall","avatar":""},{"name":"Tim Downie","avatar":""},{"name":"Matt King","avatar":""},{"name":"Simon Farnaby","avatar":""},{"name":"Kayvan Novak","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324458);
