INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-lego', 'Câu Chuyện Lego', 'The Lego Movie', 'https://phimimg.com/upload/vod/20231026-1/1edefbe6058039d12f8d5877dd4fe1e5.jpg', 'https://phimimg.com/upload/vod/20231026-1/31ccd58a1987819adbf473d61e1e220d.jpg', '<p>Phim sẽ theo chân Emmet – một nhân vật LEGO tí hon bình thường bất ngờ bị ngộ nhận là một trong những siêu nhân phi thường đang nắm giữ chìa khóa vận mệnh của cả thế giới. Emmet sẽ bị cuốn vào một đoàn người kỳ lạ trong một chuyến phiêu lưu huyền thoại nhằm ngăn chặn một tên độc tài xấu xa, chuyến đi dở khóc dở cười với vô vàn những tình huống bi hài ngoài dự liệu...</p>', 'Full', 1, 'hoathinh', 'completed', 25, 2014, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Shaquille O''Neal","avatar":""},{"name":"Will For","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324458);
