INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-thu-7', 'Đứa Con Thứ 7', 'Seventh Son', 'https://phimimg.com/upload/vod/20231026-1/f3adb942740cdd4aa2171e39d9df3ac0.jpg', 'https://phimimg.com/upload/vod/20231026-1/c571476ebc78e8e648e4396a9bea2228.jpg', '<p>Bộ phim xoay quanh nhân vật chính Tom Ward, đứa con trai thứ bảy của người cha cũng là con trai thứ bảy trong gia đình. Cậu được chọn để trở thành người chống lại các thế lực đen tối và cứu thoát nhân loại. Thực tế là trong suốt nhiều thế kỷ qua, loài người vẫn được âm thầm bảo vệ khỏi quỷ dữ và các thế lực siêu nhiên bởi các hiệp sỹ của hội Falcon Knights. Các chiến binh Falcon Knights đã bắt giam mụ phù thủy hung ác nhiều năm trước. Và giờ đây, mụ ta đã thoát ra khỏi phong ấn và đang triệu tập đám môn đệ ma quỷ để trả thù, sẵn sàng trút cơn thịnh nộ đã kìm nén bấy lâu lên vương quốc...</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Ben Barnes","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"John DeSantis","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Antje Traue","avatar":""},{"name":"Jason Scott Lee","avatar":""},{"name":"David Cubitt","avatar":""},{"name":"Eric Keenleyside","avatar":""},{"name":"Thai-Hoa Le","avatar":""},{"name":"Carmel Amit","avatar":""},{"name":"Gerard Plunkett","avatar":""},{"name":"Jim Shield","avatar":""},{"name":"Timothy Webber","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324458);
