INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-song-sot', 'Những Kẻ Sống Sót', 'Left Behind', 'https://phimimg.com/upload/vod/20231026-1/ba01e920fe8301866025b912b75fe892.jpg', 'https://phimimg.com/upload/vod/20231026-1/df8d6aa930037b5c9e51a3953d5927fa.jpg', '<p>Một nhóm nhỏ những người sống sót bị bỏ lại sau khi hàng triệu người đột nhiên biến mất trong thời kỳ sung sướng và thế giới rơi vào hỗn loạn và hủy diệt.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"Nicky Whelan","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Quinton Aaron","avatar":""},{"name":"Jordin Sparks","avatar":""},{"name":"Gary Grubbs","avatar":""},{"name":"William Ragsdale","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"Lolo Jones","avatar":""},{"name":"Cassi Thomson","avatar":""},{"name":"Georgina Rawlings","avatar":""},{"name":"Ashton Leigh","avatar":""},{"name":"Alec Rayme","avatar":""},{"name":"Major Dodson","avatar":""},{"name":"Han Soto","avatar":""},{"name":"Sh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324458);
