INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-loi-thuoc-ve-nhung-vi-sao', 'Khi Lỗi Thuộc Về Những Vì Sao', 'The Fault in Our Stars', 'https://phimimg.com/upload/vod/20231025-1/7320a6a8a329d093136f3ab2dfb4a83a.jpg', 'https://phimimg.com/upload/vod/20231025-1/9ce52ff308f45d71ca98a7915ad49944.jpg', '<p>Được chuyển thể từ tiểu thuyết cùng tên rất ăn khách của nhà văn John Green, The Fault in Our Stars là bộ phim tình cảm, lãng mạn được chờ đợi nhất mùa phim hè năm nay. Phim nói về tình yêu của Hazel, cô gái mắc bệnh ung thư giai đoạn cuối, và chàng trai trẻ Gus. Có đề tài là tình yêu trong cơn bạo bệnh nhưng tiểu thuyết The Fault in Our Stars từng gây sốt bởi sự nhẹ nhàng, hài hước và tính lạc quan trong câu chuyện. Thể hiện vai chính, Hazel, là kiều nữ đang lên của Hollywood - Shailene Woodley. Cô sẽ đóng cặp với nam diễn viên Ansel Elgort - người đóng vai anh trai mình trong Divergent vừa ra mắt hồi tháng ba. The Fault in Our Stars được quay tại Pittsburgh (Mỹ) và Amsterdam (Hà Lan).</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Ansel Elgort","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Lotte Verbeek","avatar":""},{"name":"Mike Birbiglia","avatar":""},{"name":"Ana Dela Cruz","avatar":""},{"name":"Randy Kovitz","avatar":""},{"name":"Emily Peachey","avatar":""},{"name":"David Whalen","avatar":""},{"name":"Milica Govich","avatar":""},{"name":"Allegra Carpenter","avatar":""},{"name":"Toni Saladna","avatar":""},{"name":"Emily Bach","avatar":""},{"name":"Tim Hartman","avatar":""},{"name":"Bethany Le","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"