INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-bot-tuoi-day-thi', 'Bồng Bột Tuổi Dậy Thì', 'Love, Rosie', 'https://phimimg.com/upload/vod/20231024-1/0a445427a094dd88793c05065da3da4e.jpg', 'https://phimimg.com/upload/vod/20231024-1/010ac45fb09968a5dde0b7801b161f14.jpg', '<p>Rosie và Alex đã là bạn từ khi còn nhỏ và không thể tưởng tượng mình là một cặp. Tuy nhiên, khi họ đi theo những hướng khác nhau, họ nhận ra rằng họ được tạo ra cho nhau.</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Lily Collins","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Christian Cooke","avatar":""},{"name":"Tamsin Egerton","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Jaime Winstone","avatar":""},{"name":"Art Parkinson","avatar":""},{"name":"Jamie Beamish","avatar":""},{"name":"Lorcan Cranitch","avatar":""},{"name":"Ger Ryan","avatar":""},{"name":"Lily Laight","avatar":""},{"name":"Rosa Molloy","avatar":""},{"name":"Sadbh Malin","avatar":""},{"name":"Nick Lee","avatar":""},{"name":"Ciaran McGlynn","avatar":""},{"name":"Jusin Holmes","avatar":""},{"name":"Max Cleary","avatar":""},{"name":"Aaron Kinsella","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
