INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('captain-america-chien-binh-mua-dong', 'Captain America: Chiến Binh Mùa Đông', 'Captain America: The Winter Soldier', 'https://phimimg.com/upload/vod/20231024-1/f929525997c4f9839b6c677a2507eb82.jpg', 'https://phimimg.com/upload/vod/20231024-1/471cf661d9e63cae2b62daa1e033aae9.jpg', '<p>Nội dung phim Captain America: Chiến Binh Mùa Đông là câu chuyện tiếp nối bộ phim The Avengers, khi Steve Rogers phải tìm cách hòa nhập vào thế giới hiện đại và kết hợp với Natasha Romanoff/Black Widow để chiến đấu chống lại một kẻ thù nguy hiểm ở Washington, D.C. Sau cuộc chiến cùng đội The Avengers tại New York, Captain America (hay còn gọi là Steve Rogers) có một cuộc sống khá thầm lặng tại Washington và anh phải vật lộn để thích nghi với cuộc sống ở thế giới hiện đại. Tuy nhiên, khi một người bạn trong SHIELD bị rơi vào vòng nguy hiểm, anh đã bị kéo vào một âm mưu đen tối có thể phá hủy cả nhân loại. Trong phim này, cùng với Black Widow, anh phải ngăn cản âm mưu này đồng thời chiến đấu chống lại nhừng sát thủ chuyên nghiệp được cử tới để thủ tiêu mình. Cặp đôi Captain, Black Widow còn tranh thủ sự giúp đỡ từ người bạn mới, Falcon. Tuy nhiên, một kẻ thù vô cùng nguy hiểm và bí ẩn lúc này lại xuất hiện.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Robert Redford","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Jenny Agutter","avatar":""},{"name":"Maximiliano Hernández","avatar":""},{"name":"Georges St-Pierre","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Alan Dale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324458);
