INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-va-tien-hai-tac', 'Tinker Bell và Tiên Hải Tặc', 'Tinker Bell and the Pirate Fairy', 'https://phimimg.com/upload/vod/20231024-1/712f94cabf5dd4ded2b639e555d4430f.jpg', 'https://phimimg.com/upload/vod/20231024-1/aaf9757db80c1a6229d97272cf5f0d06.jpg', '<p>Tinker Bell Và Hải Tặc Tiên sẽ tập trung vào nhân vật chính Zarina. Zarina sẽ khác với những nhân vật tiên nữ trước đây của Disney. Cô ấy là một nàng tiên trông giữ bụi phép màu đang cố thoát ra khỏi công việc hàng ngày để khám phá thế giới bên ngoài, nàng ta đã ăn trộm cả một ít bụi phép thuật và bay tới gia nhập hội cướp biển Skull Rock. Tinker Bell và các tiên nữ khác có nhiệm vụ lấy lại bụi tiên xanh và đưa Zarina trở về...</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mae Whitman","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Megan Hilty","avatar":""},{"name":"Pamela Adlon","avatar":""},{"name":"Angela Bartys","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Carlos Ponce","avatar":""},{"name":"Mick Wingert","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Jane Horrocks","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324458);
