INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-di-giua-rung-bia-mo', 'Lối Đi Giữa Rừng Bia Mộ', 'A Walk Among the Tombstones', 'https://phimimg.com/upload/vod/20231024-1/78b4b20ae87abdfb172756b6b84e2687.jpg', 'https://phimimg.com/upload/vod/20231024-1/b86057600ffbd3dd54e2234952685d41.jpg', '<p>Bộ phim được dựa trên bộ tiểu thuyết nhiều tập của tác giả Lawrence Block. Nổi danh với thể loại truyện tâm lý, tội phạm phức tạp và sâu sắc, Lawrence Block được Hội Nhà Văn Trinh Thám Mỹ đặt cho biệt danh “Grand Master”. Và bộ phim lần này sẽ khắc họa nhân vật được đánh giá là giàu cảm xúc nhất của ông, cựu thanh tra của Sở Cảnh Sát New York, Matthew Scudder (Liam Neeson). Từng là một cảnh sát tài ba, do chứng nghiện rượu tồi tệ mà Scudder đã phải rời khỏi ngành và trở thành thám tử tư. Nhưng một vụ án bất ngờ đã buộc Scudder phải đối mặt lại với những ký ức đau buồn trong thời gian làm cảnh sát mà ông cố quên đi.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Astro","avatar":""},{"name":"Mark Consuelos","avatar":""},{"name":"Adam David Thompson","avatar":""},{"name":"Sebastian Roché","avatar":""},{"name":"Laura Birn","avatar":""},{"name":"Maurice Compte","avatar":""},{"name":"Patrick McDade","avatar":""},{"name":"Luciano Acuna Jr.","avatar":""},{"name":"Hans Marrero","avatar":""},{"name":"Kim Rosen","avatar":""},{"name":"Eric Nelsen","avatar":""},{"name":"Jon Goracy","avatar":""},{"name":"Ra","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"