INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-ac-2-nguoi-dan-ba-bi-san-duoi', 'Thành Phố Tội Ác 2: Người Đàn Bà Bị Săn Đuổi', 'Sin City: A Dame to Kill For', 'https://phimimg.com/upload/vod/20231023-1/30e0401926f060c145e4b24d41da6f9f.jpg', 'https://phimimg.com/upload/vod/20231023-1/5754293df2c536a9020c096949bea36c.jpg', '<p>Phần trước nói về những tên tội phạm khép tiếng A. Marv, Hartigan, Dwight McCarthy và Nancy. Còn phần này nội dung xoay quanh một thành phố với đầy rẫy tội ác bắt nguồn từ những tên cảnh sát tham nhũng, vụ lợi cá nhân cùng với những tên tội phạm khét tiếng, bên cạnh đó là những kẻ kinh doanh bất chính chúng coi con người như một món hàng để kinh doanh. Số phận của thành phố này rồi sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 23, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mickey Rourke","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Powers Boothe","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
