INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-nguoi-may', 'Cảnh Sát Người Máy', 'RoboCop', 'https://phimimg.com/upload/vod/20231023-1/3effbe6d3321657229be2c165cc49277.jpg', 'https://phimimg.com/upload/vod/20231023-1/79bbc68fa28fe934274972d23499b66b.jpg', '<p>Tại thành phố Detroit, Mỹ, năm 2028, bọn tội phạm được trang bị nhiều vũ khí tối tân khiến công việc của các cảnh sát ngày một trở nên vô cùng nguy hiểm. Sĩ quan Alex Murphy trở thành cái gai trong mắt giới tội phạm nên bị chúng quyết tâm trừ khử. Vụ đánh bom đã khiến Alex nát gần hết người và đối mặt với cái chết. Lúc này, một tập đoàn công nghệ đang chế tạo siêu người máy đã đưa cho gia đình Alex một đề nghị không thể chối từ: đưa cơ thể anh vào robot để tiếp tục sống và chiến đấu - Tương Lai Nằm Trong Tầm Kiểm Soát</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Abbie Cornish","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Aimee Garcia","avatar":""},{"name":"Douglas Urbanski","avatar":""},{"name":"John Paul Ruttan","avatar":""},{"name":"Patrick Garrow","avatar":""},{"name":"K.C. Collins","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 