INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-di-san-cua-quy', 'Cuộc Đi Săn Của Quỷ', 'It Follows', 'https://phimimg.com/upload/vod/20231022-1/dd471d0a04fc66082b91ed6dbb3fbf51.jpg', 'https://phimimg.com/upload/vod/20231022-1/3ef52bc3f697afb699e1720ced50deed.jpg', '<p>Cuộc Đi Săn Của Quỷ - It Follows là câu chuyện xoay quanh nữ sinh 19 tuổi Jay Height (Maika Monroe thủ vai), bị ám ảnh bởi những người bí ẩn luôn theo dõi cô từ sau khi có những giây phút “mặn nồng” với bạn trai ở khu vực cắm trại ven sông. Jay bắt đầu rơi vào trạng thái hỗn loạn, những hình ảnh kinh dị, bí ẩn liên tục xuất hiện và đeo bám Jay. Nỗi ám ảnh này cũng khiến cho các bạn của cô cảm thấy sợ hãi và quyết định giúp đỡ cô. Cả nhóm không biết rằng, họ đang phải đối mặt với một thế lực bóng tối cực kì nguy hiểm và tàn bạo.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maika Monroe","avatar":""},{"name":"Keir Gilchrist","avatar":""},{"name":"Daniel Zovatto","avatar":""},{"name":"Jake Weary","avatar":""},{"name":"Olivia Luccardi","avatar":""},{"name":"Lili Sepe","avatar":""},{"name":"Bailey Spry","avatar":""},{"name":"Carollette Phillips","avatar":""},{"name":"Loren Bass","avatar":""},{"name":"Charles Gertner","avatar":""},{"name":"Debbie Williams","avatar":""},{"name":"Ruby Harris","avatar":""},{"name":"Leisa Pulido","avatar":""},{"name":"D.J. Oliver","avatar":""},{"name":"Linda Boston","avatar":""},{"name":"Ingrid Mortimer","avatar":""},{"name":"Kourtney Bell","avatar":""},{"name":"Ale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324458);
