INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-di-san-cua-quy', 'Cuộc Đi Săn Của Quỷ', 'It Follows', 'cuộc đi săn của quỷ it follows maika monroe keir gilchrist daniel zovatto jake weary olivia luccardi lili sepe bailey spry carollette phillips loren bass charles gertner debbie williams ruby harris leisa pulido d.j. oliver linda boston ingrid mortimer kourtney bell ale ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-rua-2014', 'Ninja Rùa', 'Teenage Mutant Ninja Turtles', 'https://phimimg.com/upload/vod/20231023-1/533c1c7fab4d7c180a7df8644a812a31.jpg', 'https://phimimg.com/upload/vod/20231023-1/7977584427c4afb4246794f108cf79bf.jpg', '<p>Từ một nghiên cứu hóa học thất bại khiến cho những chú rùa bình thường bị đột biến thành khổng lồ với khả năng đi đứng và nói chuyện như người. Được một bậc thầy võ thuật nuôi nấng và dạy dỗ, bốn chú rùa con ngày nào đã trưởng thành, là những ninja bí mật chiến đấu bảo vệ chính nghĩa và hòa bình trong thế giới ngầm của thành phố New York. Với sự hỗ trợ của cô phóng viên trẻ xinh đẹp April O&quot;Neil, năm thầy trò tìm cách chống lại thế lực đen tối của tên tội phạm Shredder cùng tổ chức Foot Clan của hắn, vốn kiểm soát cả lực lượng cảnh sát và các chính trị gia, để giải phóng cho cả thành phố.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Megan Fox","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Danny Woodburn","avatar":""},{"name":"Abby Elliott","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Jeremy Howard","avatar":""},{"name":"Pete Ploszek","avatar":""},{"name":"Alan Ritchson","avatar":""},{"name":"Johnny Knoxville","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Tohoru Masamune","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Minae Noji","avatar":""},{"name":"Madison Mason","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Malina Weissman","avatar":""},{"name":"Ta","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"