INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phong-van', 'Cuộc Phỏng Vấn', 'The Interview', 'https://phimimg.com/upload/vod/20231022-1/c95366ada9a7d491576e6d9ae809c812.jpg', 'https://phimimg.com/upload/vod/20231022-1/61d4cafe226b3ddfa6c5b4fdf18222f4.jpg', '<p>Phim hài đầy khiêu khích xoay quanh hai nhà báo được CIA chiêu mộ sau khi họ có được một cuộc phỏng vấn với Kim Jong-un. Diễn viên chính: Seth Rogen, James Franco.</p>', 'Full', 1, 'single', 'completed', 16, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Diana Bang","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Reese Alexander","avatar":""},{"name":"James Yi","avatar":""},{"name":"Paul Bae","avatar":""},{"name":"Geoff Gustafson","avatar":""},{"name":"Dominique Lalonde","avatar":""},{"name":"Anesha Bailey","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"Charles Rahi Chun","avatar":""},{"name":"Don Chow","avatar":""},{"name":"Colin Foo","avatar":""},{"name":"Larry Hoe","avatar":""},{"name":"Cleo Yeh","avatar":""},{"name":"Yuna Song","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
