INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noah-dai-hong-thuy', 'Noah: Đại Hồng Thủy', 'Noah', 'https://phimimg.com/upload/vod/20231022-1/76911f7d2b50097d57f6ca80d86a90e1.jpg', 'https://phimimg.com/upload/vod/20231022-1/fa623fb37076b982a280ecd0665658df.jpg', '<p>Dựa theo một câu chuyện có trong Kinh Thánh của nhiều tôn giáo lớn (Thiên Chúa, Hồi giáo, Do Thái...), đạo diễn Aronofsky (nổi tiếng với phim Black Swan) đã tái hiện lại một trong những sự kiện đầu tiên của loài người trên trái đất theo lời sách. Thuở đó, loài người sống hoang đàng vô lối nên Chúa quyết định trừng phạt bằng cách cho một cơn lũ lớn trên khắp cõi trái đất nhằm tiêu diệt tất cả. Tuy nhiên, xét thấy vẫn còn một vài người thiện lương nên Chúa đã chỉ cho Noah đóng một con tàu lớn để gia đình ông cùng muôn thú có chỗ ẩn náu qua cơn đại hồng thủy.</p>', 'Full', 1, 'single', 'completed', 12, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Douglas Booth","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Leo McHugh Carroll","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Finn Wittrock","avatar":""},{"name":"Madison Davenport","avatar":""},{"name":"Gavin Casalegno","avatar":""},{"name":"Nolan Gross","avatar":""},{"name":"Skylar B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324458);
