INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-va-huyen-thoai-quai-vat', 'Tinker Bell và Huyền Thoại Quái Vật', 'Tinker Bell and the Legend of the NeverBeast', 'https://phimimg.com/upload/vod/20231022-1/443cb0bb87ad62bf9496737cad98a1f0.jpg', 'https://phimimg.com/upload/vod/20231022-1/bc8e0d51185e8559235a6ea94c6a9c99.jpg', '<p>Fawn - nàng tiên vui tính và thông minh - tin rằng chúng ta không thể đánh giá một cuốn sách dựa vào cái bìa bên ngoài của nó cũng như nhìn con thú qua bộ răng nanh. Vậy nên, cô kết bạn với rất nhiều sinh vật bí hiểm và tạo ra thành phố mang tên NeverBeast. Ngày nọ, NeverBeast gặp nguy hiểm khiến nàng phải đứng trước lựa chọn: Tin vào đôi mắt hay trái tim của mình để ra quyết định sống còn cho vận mệnh của xứ thần tiên.</p>', 'Full', 1, 'hoathinh', 'completed', 26, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ginnifer Goodwin","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Megan Hilty","avatar":""},{"name":"Pamela Adlon","avatar":""},{"name":"Danai Gurira","avatar":""},{"name":"Chloe Bennet","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Jeff Corwin","avatar":""},{"name":"Olivia Holt","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Anjelica Huston","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324458);
