INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-lam-com', 'Cùng Làm Cớm', 'Let''s Be Cops', 'https://phimimg.com/upload/vod/20231022-1/2d9f1674aa7e9be8f8cec3320b5ee149.jpg', 'https://phimimg.com/upload/vod/20231022-1/4d3e4eec0c79d30bec6e2a4376a54210.jpg', '<p>Đây là một phim cảnh sát bạn thân cuối cùng ngoại trừ một điều: họ không phải là cảnh sát.&nbsp; Khi hai người bạn gặp khó khăn ăn mặc như cảnh sát trong một bữa tiệc hóa trang, họ gây chú ý cho khu phố.&nbsp; Nhưng khi những “anh hùng” mới toanh này vướng vào một mạng lưới thực tế rắc rối gồm những tên cướp và thám tử bẩn thỉu, họ buộc phải gắn huy hiệu giả của mình vào để đối đầu với&nbsp; rủi ro.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Johnson","avatar":""},{"name":"Damon Wayans Jr.","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Andy García","avatar":""},{"name":"Natasha Leggero","avatar":""},{"name":"Jon Lajoie","avatar":""},{"name":"Tom Mardirosian","avatar":""},{"name":"Rebecca Koon","avatar":""},{"name":"Joshua Ormond","avatar":""},{"name":"L. Warren Young","avatar":""},{"name":"Nelson Bonilla","avatar":""},{"name":"Brian Oerly","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Anna Colwell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324458);
