INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hercules-cuoc-chien-thanh-thrace', 'Hercules: Cuộc Chiến Thành Thrace', 'Hercules', 'https://phimimg.com/upload/vod/20231022-1/074078dab33c2b982c92d319f83c6b79.jpg', 'https://phimimg.com/upload/vod/20231022-1/cacd515862e777d5016e07728c786ff4.jpg', '<p>Dựa trên bộ truyện tranh “Hercules: The Thracian Wars”, nội dung phim sẽ mang câu chuyện thần thoại về “Vị thần sức mạnh” lồng vào bối cảnh một thế giới trần tục nơi mà các năng lực siêu nhiên thần thánh không hề tồn tại. Khác với các phiên bản Hercules trước, chuyện phim lần này không nói về sự tích ra đời của huyền thoại Hercules hay &quot;12 kỳ công của Hercules&quot; mà xảy ra rất lâu sau đó... Bị ám ảnh bởi một tội lỗi đã gây ra trong quá khứ, Hercules giờ đây trở thành một “tay lính đánh thuê” và cùng với năm bạn đồng hành trung thành, anh phiêu lưu khắp Hy Lạp, bán sức mạnh của mình để đổi lấy vàng và dùng danh tiếng lẫy lừng khiến kẻ thù khiếp sợ. Nhưng khi vị vua nhân từ của xứ Thrace và cháu gái ông nhờ đến sự giúp đỡ của Hercules để đánh bại một tên chúa tể tàn bạo khát máu, anh nhận ra rằng một khi thực thi công lý và giành lấy vinh quang, anh sẽ trở lại thành người anh hùng năm xưa, trở lại thành Hercules trong thần thoại.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Aksel Hennie","avatar":""},{"name":"Ingrid Bolsø Berdal","avatar":""},{"name":"Reece Ritchie","avatar":""},{"name":"Joseph Fiennes","avatar":""},{"name":"Tobias Santelmann","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Irina Shayk","avatar":""},{"name":"Erika Marozsán","avatar":""},{"name":"Isaac Andrews","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Stephen Peacocke","avatar":""},{"name":"Nicholas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324458);
