INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-vien-bao-tang-bi-mat-ham-mo', 'Đêm Ở Viện Bảo Tàng: Bí Mật Hầm Mộ', 'Night at the Museum: Secret of the Tomb', 'https://phimimg.com/upload/vod/20231022-1/4986ff4be126024083385823d2cb5962.jpg', 'https://phimimg.com/upload/vod/20231022-1/3a08aaf7f6a233248b92354a0e70ee34.jpg', '<p>Anh chàng gác đêm Michael một lần nữa sẽ theo viện bảo tàng đến xứ sở hoa anh đào để công tác. Không quên mang theo những người bạn tí hon của mình, và đặc biệt là tấm bài vị thần kì quý giả của vua Ai Cập. Cùng những nhân vật sống dậy từ bảo tàng, Micheal bắt đầu một chuyến phiêu lưu đầy hài hước.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"Mizuo Peck","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Dick Van Dyke","avatar":""},{"name":"Mickey Rooney","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Andrea Martin","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Matt Frewer","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324458);
