INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-o-vien-bao-tang-bi-mat-ham-mo', 'Đêm Ở Viện Bảo Tàng: Bí Mật Hầm Mộ', 'Night at the Museum: Secret of the Tomb', 'đêm ở viện bảo tàng: bí mật hầm mộ night at the museum: secret of the tomb ben stiller robin williams owen wilson steve coogan ricky gervais dan stevens rebel wilson skyler gisondo rami malek patrick gallagher mizuo peck ben kingsley dick van dyke mickey rooney bill cobbs andrea martin rachael harris matt frewer ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-biet-nhung-ke-bat-tri', 'Dị Biệt: Những Kẻ Bất Trị', 'Divergent', 'https://phimimg.com/upload/vod/20231022-1/f1f74abcbeb0c035b9837ac503a13908.jpg', 'https://phimimg.com/upload/vod/20231022-1/df1f15015dacda0c5c555bce547ad10a.jpg', '<p>Nếu như trong Harry Potter, các phù thuỷ nhỏ đến trường Hogwarts sẽ được chiếc nón phân loại và chia vào bốn nhà khác nhau thì khi xem Dị biệt, khán giả cũng chứng kiến tình huống tương tự như vậy. Ở thời tương lai 100 năm sau, toàn thế giới là một xã hội có trật tự nhất định và được phân thành 5 loại người làm các loại công việc khác nhau. Khi đến tuổi 16, mọi thanh niên đều phải trải qua một cuộc kiểm tra để biết mình thuộc nhóm nào. Tuy nhiên, vẫn có những trường hợp mà một người có thể xếp vào nhiều nhóm và người này được gọi là &quot;dị biệt&quot;, kẻ có thể gây mất cân bằng cho toàn bộ trật tự xã hội và cần phải bị loại bỏ.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Theo James","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Ansel Elgort","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Ben Lloyd-Hughes","avatar":""},{"name":"Amy Newbold","avatar":""},{"name":"Ben Lamb","avatar":""},{"name":"Janet Ulrich Brooks","avatar":""},{"name":"Clara Burger","avatar":""},{"name":"Anthony Flemin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324458);
