INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ma-am-2', 'Ngôi Nhà Ma Ám 2', 'A Haunted House 2', 'https://phimimg.com/upload/vod/20231022-1/f35e712d3247572ff14bc16a8fcd7de1.jpg', 'https://phimimg.com/upload/vod/20231022-1/58e015a45d35b2282bddaca6efe6abf4.jpg', '<p>Sau khi xua đuổi ác quỷ của người yêu cũ, Malcolm bắt đầu lại từ đầu với bạn gái mới và hai đứa con của cô ấy. Sau khi chuyển đến ngôi nhà mơ ước của họ, Malcolm một lần nữa bị cản trở bởi những sự kiện huyền bí kỳ quái.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marlon Wayans","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Essence Atkins","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Ashley Rickards","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Steele Stebbins","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Tom Virtue","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Sophie Dee","avatar":""},{"name":"Audrey Petenbrink","avatar":""},{"name":"Scott Burn","avatar":""},{"name":"Chris Gann","avatar":""},{"name":"Melissa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324458);
