INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-me-toc-do', 'Đam Mê Tốc Độ', 'Need for Speed', 'https://phimimg.com/upload/vod/20231021-1/eed9ebb2138db18cbe3cb0d922b85582.jpg', 'https://phimimg.com/upload/vod/20231021-1/d236a9a7d7a7f41c7d264bd61b91c034.jpg', '<p>Phim nói về cuộc đời anh chàng Paul (Aaron Paul), một tay đua hạng vip trong thế giới ngầm, anh sở hữu cả một gara chuyên độ những chiếc xế hộp loại xịn. Paul bị gài bẫy và tống vào tù trong khi người bạn thân nhất thì bị ám sát trong một cuộc đua, anh nóng lòng chờ ngày được thả để theo đuổi sự báo thù. Cooper sẽ đóng vai Dino, một cựu tay đua NASCAR chuyên làm ăn những vụ độ xế và mua bán siêu xe.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Aaron Paul","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Ramón Rodríguez","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Dakota Johnson","avatar":""},{"name":"Harrison Gilbertson","avatar":""},{"name":"Stevie Ray Dallimore","avatar":""},{"name":"Alan Pflueger","avatar":""},{"name":"Brian L. Keaulana","avatar":""},{"name":"Logan Holladay","avatar":""},{"name":"Carmela Zumbado","avatar":""},{"name":"Jalil Jay Lynch","avatar":""},{"name":"Nick Chinlund","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
