INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dam-me-toc-do', 'Đam Mê Tốc Độ', 'Need for Speed', 'đam mê tốc độ need for speed aaron paul dominic cooper imogen poots ramón rodríguez michael keaton rami malek kid cudi dakota johnson harrison gilbertson stevie ray dallimore alan pflueger brian l. keaulana logan holladay carmela zumbado jalil jay lynch nick chinlund ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-chet-cuoi', 'Kỳ Nghỉ Chết Cười', 'Blended', 'https://phimimg.com/upload/vod/20231020-1/916ccff80365a22f60267cac61a2d6c4.jpg', 'https://phimimg.com/upload/vod/20231020-1/41f36452f56e5a24ea4204b6f0ff2d2c.jpg', '<p>Kỳ nghỉ chết cười xoay quanh câu chuyện về hai ông bố và bà mẹ đơn thân Jim Friedman (do Adam Sandler thủ vai) và Lauren Reynolds (Drew Barrymore đóng). Định mệnh đưa họ gặp nhau bằng một buổi hẹn hò xem mặt rắc rối khiến cả hai đều quyết định không bao giờ muốn gặp lại nhau.Nhưng, cặp đôi này cứ phải chạm mặt nhau hết lần này đến lần khác, và hai gia đình tình cờ gặp nhau, thậm chí còn phải ở chung một phòng trong một khu nghỉ dưỡng kết hợp săn bắn sang trọng ở châu Phi. Hai gia đình buộc phải ở chung phòng và đi chung với nhau vì cả hai đều sử dụng vé chui. Sau một tuần gắn bó, hai gia đình dần chuyển từ xung đột sang tình cảm, Lauren và Jim cũng bắt đầu có cảm tình với nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Bella Thorne","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Abdoulaye NGom","avatar":""},{"name":"Jessica Lowe","avatar":""},{"name":"Braxton Beckham","avatar":""},{"name":"Emma Fuhrmann","avatar":""},{"name":"Alyvia Alyn Lind","avatar":""},{"name":"Kyle Red Silverstein","avatar":""},{"name":"Zak Henri","avatar":""},{"name":"Shaquille O''Neal","avatar":""},{"name":"Dan Patrick","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
