INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-john-wick', 'Sát Thủ John Wick', 'John Wick', 'https://phimimg.com/upload/vod/20231020-1/5ebb0a4e7b6c151d5e1a9c7611c420f0.jpg', 'https://phimimg.com/upload/vod/20231020-1/b6eb2ae7846baa824de265288bd4f10e.jpg', '<p>John Wick xuất sắc như một tân binh hiện đại. Về cơ bản phim có một tiền đề vô cùng đặc sắc: một tay súng đã nghỉ hưu trở về với một cuộc đời tội phạm, thoạt đầu ta tưởng đó là một tên xã hội đen đã đánh cắp chiếc xe Mustang giết chết con chó của anh ta. Nhưng nếu nhìn nhận kỹ hơn, thực chất John phải vật lộn với một cuộc khủng hoảng hiện hữu sau cái chết của vợ mình. Có thể tất cả là sự phát tiết điên cuồng của John đè nén bấy lâu. Ngay cả kẻ thù của John cũng hiểu điều đó, và họ sợ đến chết khi thấy anh nổi dậy sau ngừng ấy năm.</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Michael Nyqvist","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Alfie Allen","avatar":""},{"name":"Dean Winters","avatar":""},{"name":"Adrianne Palicki","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"David Patrick Kelly","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Munro M. Bonnell","avatar":""},{"name":"Omer Barnea","avatar":""},{"name":"Toby Leonard Moore","avatar":""},{"name":"Daniel Bernhar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
