INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-john-wick', 'Sát Thủ John Wick', 'John Wick', 'sát thủ john wick john wick keanu reeves michael nyqvist ian mcshane john leguizamo willem dafoe alfie allen dean winters adrianne palicki lance reddick bridget moynahan david patrick kelly randall duk kim munro m. bonnell omer barnea toby leonard moore daniel bernhar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('exodus-cuoc-chien-chong-pharaong', 'Exodus: Cuộc Chiến Chống Pha-ra-ông', 'Exodus: Gods and Kings', 'https://phimimg.com/upload/vod/20231020-1/18e17fd7e7ad6768cdc9f4a7bb36ecaf.jpg', 'https://phimimg.com/upload/vod/20231020-1/db4ea82da5a6531ac7fe833ae5fe5aef.jpg', '<p>Exodus: Gods and Kings lấy ý tưởng chính từ một câu chuyện khác - cuộc đại chiến giữa dân tộc Do Thái và đế chế Ai Cập hùng mạnh của các Pharaoh. Nhân vật chính của bộ phim là người anh hùng vĩ đại trong lịch sử người Do Thái - Moses. Từ một đứa trẻ sống sót sau trận đại tàn sát của Pharaoh, Moses được giao sứ mệnh dẫn dắt những nô lệ người Do Thái thoát khỏi ách thống trị của đế chế Ai Cập, tìm đến miền đất hứa tự do, nhờ sự trợ giúp từ sứ giả của Chúa.</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"María Valverde","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Isaac Andrews","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"Ghassan Massoud","avatar":""},{"name":"Tara Fitzgerald","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Andrew Tarb","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
