INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-vong-nhip-dieu', 'Khát Vọng Nhịp Điệu', 'Whiplash', 'https://phimimg.com/upload/vod/20231019-1/510da400df5f30192fd50cc087381a00.jpg', 'https://phimimg.com/upload/vod/20231019-1/bd2ab230253f0c47d59c2d8c260c110a.jpg', '<p>Trong “Whiplash”, Miles Teller vào vai Andrew Neyman, một tay trống nhạc jazz trẻ khá tham vọng và quyết tâm theo đuổi đỉnh cao trong sự nghiệp âm nhạc bên bờ biển miền Đông nước Mỹ. Ám ảnh bởi sự nghiệp viết nhạc thất bại của người cha, Andrew ngày đêm nung nấu trở thành một nhạc công vĩ đại. Nhân vật thứ hai, Terence Fletcher (Simmons) là một huấn luyện viên nổi danh nhờ tài năng giảng dạy nhưng cũng khét tiếng bởi các phương pháp khắc nghiệt của ông, chuyên dẫn dắt các tài năng nhạc jazz hàng đầu trong trường nhạc. Fletcher phát hiện ra Andrew và mang tay trống về ban nhạc riêng của mình, thay đổi mãi mãi cuộc đời của chàng trai trẻ. Đam mê vươn tới sự hoàn hảo khiến Andrew rơi vào vòng xoáy của sự ám ảnh, bởi ông thầy tàn nhẫn ...</p>', 'Full', 1, 'single', 'completed', 23, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miles Teller","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Melissa Benoist","avatar":""},{"name":"Austin Stowell","avatar":""},{"name":"Chris Mulkey","avatar":""},{"name":"Nate Lang","avatar":""},{"name":"Charlie Ian","avatar":""},{"name":"Jayson Blair","avatar":""},{"name":"Kavita Patil","avatar":""},{"name":"Damon Gupton","avatar":""},{"name":"Suanne Spoke","avatar":""},{"name":"Max Kasch","avatar":""},{"name":"Kofi Siriboe","avatar":""},{"name":"C.J. Vana","avatar":""},{"name":"Tarik Lowe","avatar":""},{"name":"Tyler Kimball","avatar":""},{"name":"Rogelio Douglas Jr.","avatar":""},{"name":"Adr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324458);
