INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thanh-trung-hon-loan', 'Ngày Thanh Trừng: Hỗn Loạn', 'The Purge: Anarchy', 'https://phimimg.com/upload/vod/20231019-1/c6d5fb818a0d84ee0cbd86f0e3fb2742.jpg', 'https://phimimg.com/upload/vod/20231019-1/6026a152cc7b9ea84d3e69dfa344150d.jpg', '<p>The Purge: Anarchy lấy bối cảnh thế giới tương lai vào năm 2023, khi nước Mỹ trở thành &quot;một quốc gia tái sinh”, với tỷ lệ tội phạm và thất nghiệp ở mức rất thấp. Để giữ mức ổn định này, chính phủ hàng năm đều tiến hành một chiến dịch có tên gọi Lễ Thanh Trừng để con người có thể tự do giải thoát mọi cảm xúc tiêu cực của họ. Trong vòng 12 tiếng, tất cả mọi hành vi phạm tội bao gồm cả giết người đều không bị truy xét trước pháp luật. Tuy nhiên, điều này đã kéo theo hàng loạt sự kiện thanh trừng vô cùng khủng khiếp gây náo loạn, càng đẩy tình trạng hỗn loạn vượt ra ngoài tầm kiểm soát...</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Frank Grillo","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Zach Gilford","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Kiele Sanchez","avatar":""},{"name":"Zoë Soul","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Jack Conley","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"Castulo Guerra","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Roberta Valderrama","avatar":""},{"name":"Niko Nicotera","avatar":""},{"name":"Bel Hernandez","avatar":""},{"name":"Lily","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
