INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-thanh-trung-hon-loan', 'Ngày Thanh Trừng: Hỗn Loạn', 'The Purge: Anarchy', 'ngày thanh trừng: hỗn loạn the purge: anarchy frank grillo carmen ejogo zach gilford michael kenneth williams kiele sanchez zoë soul edwin hodge justina machado john beasley jack conley noel gugliemi castulo guerra lakeith stanfield roberta valderrama niko nicotera bel hernandez lily ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-giai-cuu-tinh-yeu', 'Hành Trình Giải Cứu Tình Yêu', 'The Book of Life', 'https://phimimg.com/upload/vod/20231019-1/06fd4e848bd973165d8b85db7c209401.jpg', 'https://phimimg.com/upload/vod/20231019-1/ca331e425b85fe95c46d7f0624162a15.jpg', '<p>Manolo – một chàng trai trẻ tuổi, đứng giữa hai lựa chọn là sẽ theo đuổi đam mê của mình hay phải nối tiếp truyền thống gia đình. Khi đang phân vân con đường mình sẽ đi thì anh đã vô tình dấn thân vào cuộc hành trình tìm lại Maria – người bạn thanh mai trúc mã, và cũng là người mà anh đem lòng yêu thương. Bộ phim đậm chất Mexico cổ quái, với những bản đàn ghi ta mê đắm và những cuộc đấu bò tót rực lửa. Đặc biệt, phim lấy đề tài là ngày 2 tháng 11, ngày lễ của người chết bên Mexico, hứa hẹn sẽ đem đến cho bạn những cảm giác mới lạ!</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diego Luna","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Ana de la Reguera","avatar":""},{"name":"Dan Navarro","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Emil-Bastien Bouffard","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324458);
