INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lucy-sieu-pham', 'Lucy Siêu Phàm', 'Lucy', 'https://phimimg.com/upload/vod/20231021-1/7c305c91ba6e1e0f9f599b4b00687281.jpg', 'https://phimimg.com/upload/vod/20231021-1/4297899154abb69707fd8d31c817a713.jpg', '<p>Lucy là một cô gái trẻ bị bắt cóc bởi một nhóm tội phạm và bị đưa vào cơ thể một loại thuốc lạ. Thứ thuốc ấy vô tình rỉ ra và làm cho cô có siêu năng lực đặc biệt. Một người bình thường chỉ có thể sử dụng 10% trí não nhưng bây giờ cô có thể sử dụng 100% trí não của mình, cô có thể điều khiển mọi thứ bằng tâm trí hay thu nạp kiến thức một cách nhanh chóng... Lucy bắt đầu lên đường và tìm ra nguồn gốc của vấn đề.</p>', 'Full', 1, 'single', 'completed', 15, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Julian Rhind-Tutt","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"Shin Yoo-ram","avatar":""},{"name":"Seo Chong-ju","avatar":""},{"name":"Nicolas Phongpheth","avatar":""},{"name":"Paul Lefèvre","avatar":""},{"name":"Jan Oliver Schroeder","avatar":""},{"name":"Luca Angeletti","avatar":""},{"name":"Pierre Poirot","avatar":""},{"name":"Pierre Grammont","avatar":""},{"name":"Bertrand Quoniam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324458);
