INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-giai-ma', 'Trò Chơi Giải Mã', 'The Imitation Game', 'https://phimimg.com/upload/vod/20231019-1/411ae0dd38f72281f2b51cb22004313e.jpg', 'https://phimimg.com/upload/vod/20231019-1/9240fe7c293202539dc01bb3183ff5fc.jpg', '<p>Dựa trên câu chuyện đời thực của nhà phân tích mật mã huyền thoại Alan Turing(cha đẻ ngành điện toán), bộ phim khắc họa cuộc chạy đua cam go với thời gian của Turing và đội phá mã xuất sắc của anh ta tại cơ sở mật mã tối mật của nước Anh, trong những ngày đen tối nhất của thế chiến II.</p>', 'Full', 1, 'single', 'completed', 25, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Allen Leech","avatar":""},{"name":"Matthew Beard","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"James Northcote","avatar":""},{"name":"Tom Goodman-Hill","avatar":""},{"name":"Steven Waddington","avatar":""},{"name":"Ilan Goodman","avatar":""},{"name":"Jack Tarlton","avatar":""},{"name":"Alex Lawther","avatar":""},{"name":"Jack Bannon","avatar":""},{"name":"Tuppence Middleton","avatar":""},{"name":"Do","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324458);
