INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-doat-3', 'Cưỡng Đoạt 3', 'Taken 3', 'https://phimimg.com/upload/vod/20231018-1/571b948ddda503e545ac7ef077e11534.jpg', 'https://phimimg.com/upload/vod/20231018-1/8bcf7e83ed8452c8e6b7c2ca1642f9ff.jpg', '<p>Trong phần phim này, nhân vật của Liam Neeson trở thành người bị săn đuổi sau khi bị buộc tội giết người. Ông phải lên đường chạy trốn và sẽ làm hết sức để thoát thân.&nbsp; Từ một người tuân thủ luật pháp và có uy tín, Bryan Mills trở thành người chạy trốn. Bryan Mills trung thành phục vụ đất nước của mình, nhưng bây giờ họ truy bắt ông.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Dylan Bruno","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Jonny Weston","avatar":""},{"name":"Andrew Borba","avatar":""},{"name":"Judi Beecher","avatar":""},{"name":"Cedric Cirotteau","avatar":""},{"name":"Catherine Dyer","avatar":""},{"name":"Jimmy Pal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
