INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-ban-tia-my', 'Lính Bắn Tỉa Mỹ', 'American Sniper', 'lính bắn tỉa mỹ american sniper bradley cooper sienna miller kyle gallner cole konis ben reed elise robertson keir o''donnell luke sunshine kevin lacz troy vincent brandon salgado telis chance kelly marnette patterson billy miller leonard roberts reynaldo gallegos ja ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-no', 'Cuồng Nộ', 'Fury', 'https://phimimg.com/upload/vod/20231018-1/1b79643c857445200f0f67c3f82749de.jpg', 'https://phimimg.com/upload/vod/20231018-1/16640874ed36af622edd76da94019091.jpg', '<p>Fury được đặt bối cảnh vào năm 1945, khi Thế Chiến đệ nhị đang đi vào giai đoạn cuối và lực lượng Đồng Minh đang dồn tổng lực tấn công phe Phát xít Đức. Tại chiến trường Tây Đức, một tiểu đội do trung sĩ Don với biệt danh “Wardaddy” chỉ huy có nhiệm vụ điều khiển chiếc xe tăng “Fury” cùng những chiếc xe tăng khác thọc sâu vào phòng tuyến của quân Đức để hỗ trợ lực lượng bộ binh. Khi chuẩn bị thực hiện một chiến dịch mới thì họ mất đi đồng đội, người thay thế lại là một tân binh chưa hề nếm mùi chiến trường, Norman (Lorgan Lerman).Anh chàng được đào tạo để làm người truyền tin, vốn chỉ quen đánh máy và chưa bao giờ bước vào bên trong một chiếc xe tăng giờ đây được đưa vào giữa lòng địch, bên cạnh ...</p>', 'Full', 1, 'single', 'completed', 20, 2014, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Kevin Vance","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Anamaria Marinca","avatar":""},{"name":"Alicia von Rittberg","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Laurence Spellman","avatar":""},{"name":"Daniel Betts","avatar":""},{"name":"Adam Ganne","avatar":""},{"name":"Eric Kofi Abr","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324458);
