INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-me-cung', 'Giải Mã Mê Cung', 'The Maze Runner', 'https://phimimg.com/upload/vod/20231017-1/bb84af5993ebecd82bb40e92026cccbb.jpg', 'https://phimimg.com/upload/vod/20231017-1/181f2e3ab7e42eadd454d2d8999347ef.jpg', '<p>The Maze Runner là bộ phim được chuyển thể từ bộ truyện cùng tên có nội dung giả tưởng về nhóm bạn trẻ bị giam giữ trong &quot;Trảng&quot; với một trí nhớ không rõ ràng, và cuộc vật lộn tìm lối thoát. Làm thế nào họ sống sót được giữa một mê cung khổng lồ đầy những sinh vật nguy hiểm và thay đổi lời giải hằng đêm? Ai sẽ là người sống sót cuối cùng sau những bí mật chết người kia?</p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Ki Hong Lee","avatar":""},{"name":"Aml Ameen","avatar":""},{"name":"Blake Cooper","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Dexter Darden","avatar":""},{"name":"Chris Sheffield","avatar":""},{"name":"Joe Adler","avatar":""},{"name":"Alexander Flores","avatar":""},{"name":"Jacob Latimore","avatar":""},{"name":"Randall D. Cunningham","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Don McManus","avatar":""},{"name":"Michael Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
