INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-hon', 'Đoạt Hồn', 'Hollow', 'https://phimimg.com/upload/vod/20231011-1/abc2cd7e488d34e9e5a1b4b698f036a4.jpg', 'https://phimimg.com/upload/vod/20231011-1/a6ed7979de9ff7fb61e0c5045ca51105.jpg', '<p>Đoạt hồn là câu chuyện xoay quanh bi kịch của gia đình Gia Huy, một thương gia bán đá quý. Trong một lần gia đình đi làm lễ thánh, cô con gái út 8 tuổi tên Ái của gia đình bị trượt chân ngã xuống sông và chết đuối. Một tuần sau đó, người cậu Thức nhận được tin tìm thấy xác bé Ái ở Châu Đốc bên bờ sông Hậu Giang. Nhưng kỳ lạ thay, khi tới nơi nhận xác cháu, cậu Thức được chứng kiến cảnh bé Ái từ cõi chết trở về. Sau khi bé Ái được đưa về nhà, nhiều sự kiện ma quái cứ thế bắt đầu xảy ra.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kiều Chinh","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Hong An Nguyen","avatar":""},{"name":"Ngọc Hiệp","avatar":""},{"name":"Nhung Kate","avatar":""},{"name":"Suboi","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Bảo Sơn Trần","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
