INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-nam-ay', 'Chàng Trai Năm Ấy', 'Dandelion', 'https://phimimg.com/upload/vod/20231011-1/8832af980a1736d3143f7fd8b47057de.jpg', 'https://phimimg.com/upload/vod/20231011-1/23dae9b2ba34433022519f2548290675.jpg', '<p>Đình Phong là một ca sĩ trẻ nổi tiếng, ước mơ tổ chức liveshow của riêng mình. Thế nhưng, cuộc đời không mỉm cười với chàng trai ấy khi anh bị chẩn đoán mắc căn bệnh nan y. Kiên cường sống, chàng ca sĩ vẫn làm việc chăm chỉ và phấn đấu hết mình. May mắn thay, bên anh luôn có những người bạn hết lòng quan tâm, chăm sóc và yêu thương.&nbsp; Chàng Trai Năm Ấy là bộ phim gây tiếng vang lớn trong năm 2015, đưa tên tuổi Sơn Tùng M-TP trở thành ngôi sao hàng đầu Việt Nam. Ngoài ra, phim có sự xuất hiện của nhiều ngôi sao nổi tiếng như Hari Won, Phạm Quỳnh Anh, Hứa Vĩ Văn… Bộ phim được lấy cảm hứng từ câu chuyện có thật của chàng ca sĩ quá cố Wanbi Tuấn Anh.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Sơn Tùng M-TP","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Phạm Quỳnh Anh","avatar":""},{"name":"Hari Won","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Don Nguyễn","avatar":""},{"name":"Harry Lu","avatar":""},{"name":"Quang Thắng","avatar":""},{"name":"Khanh Huyen","avatar":""},{"name":"Thành Lộc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
