INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-ga', 'Hương Ga', 'Rise', 'https://phimimg.com/upload/vod/20231011-1/26dc3687d666cb2a2ee4cae4d13af782.jpg', 'https://phimimg.com/upload/vod/20231011-1/c48edbd804a7951fb89d5d7cd106a702.jpg', '<p>Từ trại giam cho đến cuộc sống quyền quý, một người bán hàng rong nhanh chóng trở thành trùm tội phạm, nhưng sự báo thù đe dọa sẽ hạ bệ cô.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kim Ly","avatar":""},{"name":"Trương Ngọc Ánh","avatar":""},{"name":"Nhu Quynh","avatar":""},{"name":"Chi Pu","avatar":""},{"name":"Chi Bảo","avatar":""},{"name":"Hiếu Nguyễn","avatar":""},{"name":"Ưng Hoàng Phúc","avatar":""},{"name":"Harry Lu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
