INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-than-nam-nu-2', 'Đơn Thân Nam Nữ 2', 'Don''t Go Breaking My Heart 2', 'https://phimimg.com/upload/vod/20231008-1/93bf8988f36d503ff7b5820556d2cc96.jpg', 'https://phimimg.com/upload/vod/20231008-1/788bbed53bf094896ae9d0b5883eb966.jpg', '<p>Thân Nhiên sắp kết hôn với Khải Hoành nhưng anh người yêu cũ ăn chơi lại chen ngang. Thiên đường tình yêu sẽ ra sao trước sự nhầm lẫn về thân phận và tình tay ba?</p>', 'Full', 1, 'single', 'completed', 13, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Gao Yuanyuan","avatar":""},{"name":"Miriam Yeung","avatar":""},{"name":"Vic Chou","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Du Yaсhun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
