INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('don-than-nam-nu-2', 'Đơn Thân Nam Nữ 2', 'Don''t Go Breaking My Heart 2', 'đơn thân nam nữ 2 don''t go breaking my heart 2 louis koo gao yuanyuan miriam yeung vic chou daniel wu lam suet lo hoi-pang du yaсhun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-bi-an-mot-huyen-thoai', 'Hoàng Phi Hồng : Bí Ẩn Một Huyền Thoại', 'Rise Of The Legend', 'https://phimimg.com/upload/vod/20231007-1/14cd0cbcc2824796f5f7973be275298a.jpg', 'https://phimimg.com/upload/vod/20231007-1/e863967b839c79db7a07f9ebc77d8a09.jpg', '<p>Tập trung khai thác thời niên thiếu và giai đoạn tuổi trẻ của nhân vật lịch sữ lỗi lạc, bậc thầy võ công và nhà y thuật Trung Hoa. Hình ảnh thứ nhất cho thấy Bành Vu Yến (vai Hoàng Phi Hồng) để đầu trần cuộn tóc dài đặc trưng của người Trung Quốc cuối thế kỷ 19 đầu thế kỷ 20, đang bước đi trong mưa. Sau lưng cao thủ là một nhóm đông cầm gươm và kiếm đang sẵn sàng xông lên. Phim lấy bối cảnh thời Thanh mạt, với không gian là bến cảng sông Chu Giang ở Quảng Châu. Tại đây, bang phái Hắc Hổ hoạt động buôn người với những chiêu trò đê hèn, ti tiện. Chứng kiến cảnh đó, Hoàng Phi Hồng vô cùng giận dữ và bất an. Anh đã cùng với những người bạn tìm cách giải thoát các nạn nhân của bọn buôn người. Từ đó, anh xây dựng lãnh hạt mới cho người nghèo và trở thành anh hùng Hoàng Phi Hồng huyền thoại.</p>', 'Full', 1, 'single', 'completed', 24, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eddie Peng","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Jing Boran","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Zhang Jin","avatar":""},{"name":"Feng Jia-Yi","avatar":""},{"name":"Wang Luodan","avatar":""},{"name":"Qin Junjie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324458);
