INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-hoc-duong', 'Án Mạng Học Đường', 'Thread of Lies', 'https://phimimg.com/upload/vod/20230930-1/393b66f00a741c4cfcc57d7422266a77.jpg', 'https://phimimg.com/upload/vod/20230930-1/98b30c732a4e323e3d18c124b052265d.jpg', '<p>Án Mạng Học Đường là một bộ phim điện ảnh Hàn Quốc ra mắt năm 2014 dựa trên một tiểu thuyết bán chạy năm 2009 mang tên Elegant Lies của tác giả Kim Ryeo-ryeong. Đạo diễn Lee Han, vai chính được đảm nhận bởi Kim Hee-ae, Go Ah-sung, Kim Hyang-gi và Kim Yoo-jung.</p>', 'Full', 1, 'single', 'completed', 18, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hee-ae","avatar":""},{"name":"Ko A-sung","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Kim Hyang-gi","avatar":""},{"name":"Yoo Ah-in","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Yoo Yeon-mi","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Lee Jae-gu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
