INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thuy-chien', 'Đại Thủy Chiến', 'The Admiral : Roaring Currents', 'https://phimimg.com/upload/vod/20230930-1/38db3486023c90e4af635a0d8bb8b55c.jpg', 'https://phimimg.com/upload/vod/20230930-1/3b283ee75ddef8c2fe60643f5a2b09d0.jpg', '<p>Phim nói về trận hải chiến Myeongnyang vào ngày 26 tháng 10 năm 
1597, được đánh giá là chiến thắng huyền thoại của đô đốc Yi Sun-sin 
(Choi Minsik) trước quân xâm lược Nhật Bản, khi ông chỉ còn lại 12 chiến
 thuyền sau thất bại thảm họa của đô đốc Won Gyun tại trận 
Chilchelollyang và phải chống lại hạm đội khoảng 330 chiến thuyền của 
Nhật Bản, do tướng Kurushima Michifusa chỉ huy.</p>', 'Full', 1, 'single', 'completed', 17, 2014, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Min-sik","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Lee Jung-hyun","avatar":""},{"name":"Kim Myung-gon","avatar":""},{"name":"Kwon Yul","avatar":""},{"name":"No Min-woo","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Ryohei Otani","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324458);
