INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-nu-tu-nhan', 'Trại Nữ Tù Nhân', 'Jailbait', 'https://phimimg.com/upload/vod/20230925-1/b085d7c78c6f1805e9d73cbe1a13bff5.jpg', 'https://phimimg.com/upload/vod/20230925-1/1bf4e96b447a23d92face488422cf7f6.jpg', '<p>Một bộ phim kinh dị dành cho lứa tuổi mới lớn kể về một cô gái trẻ bị đưa vào nhà tù vị thành niên vì tội giết người cha dượng bạo hành của mình. Bộ phim kể về cuộc hành trình của Anna Nix vào thế giới đen tối của nhà tù dành cho nữ, nơi cô phát hiện ra những mối quan hệ phức tạp, ma túy, bệnh tâm thần và hành trình tìm kiếm sự cứu chuộc cuối cùng của mình.</p>', 'Full', 1, 'single', 'completed', 19, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sara Malakul Lane","avatar":""},{"name":"Erin O''Brien","avatar":""},{"name":"Jennifer Robyn Jacobs","avatar":""},{"name":"Samantha Cardona","avatar":""},{"name":"Steve Hanks","avatar":""},{"name":"Andray Johnson","avatar":""},{"name":"Robert Sisko","avatar":""},{"name":"Cynthia Dallas","avatar":""},{"name":"Bill Devlin","avatar":""},{"name":"Marguerite Nocera","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324458);
