INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-rua-tien', 'Phi Vụ Rửa Tiền', 'The Drop', 'https://phimimg.com/upload/vod/20230919-1/24c74e34c79f5806c86aea431c4ef930.jpg', 'https://phimimg.com/upload/vod/20230919-1/b7ec3177f0791e406dc2d746ad4e2990.jpg', '<p><span style="font-family: ">Một người pha chế làm việc dưới người anh em họ của mình cho một tập đoàn tội phạm có liên quan đến một vụ cướp mang lại hầu hết những người mà anh ta biết dưới máy quét.</span></p>', 'Full', 1, 'single', 'completed', 21, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Michael Aronov","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Elizabeth Rodriguez","avatar":""},{"name":"Tobias Segal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324458);
