INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cuoc-gap-go', 'Một Cuộc Gặp Gỡ', 'Une rencontre', 'https://phimimg.com/upload/vod/20230916-1/9bb05d206caff5321d567a5c9527fd9f.jpg', 'https://phimimg.com/upload/vod/20230916-1/b614b2dcd38c52922145fff84aab9ade.jpg', '<p>Pierre đã có cuộc hôn nhân hạnh phúc được mười lăm năm và là một người cha tốt. Vẫn yêu vợ, anh vui vẻ và hài lòng với vợ, gia đình. Một buổi tối, anh gặp Elsa tại một bữa tiệc và ngay lập tức bị thu hút bởi nhau. Mười lăm ngày sau, họ tình cờ gặp lại nhau và sự hấp dẫn lẫn nhau chuyển thành sự say mê. Nhưng tình yêu của anh dành cho vợ và quy định của Elsa về việc không hẹn hò với đàn ông đã có gia đình đã ngăn cản họ thực hiện bước tiếp theo. Thay vào đó, họ tưởng tượng về nhau, và chẳng bao lâu những tưởng tượng đó hòa quyện với thực tế.</p>', 'Full', 1, 'single', 'completed', 26, 2014, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sophie Marceau","avatar":""},{"name":"François Cluzet","avatar":""},{"name":"Lisa Azuelos","avatar":""},{"name":"Alexandre Astier","avatar":""},{"name":"Arthur Benzaquen","avatar":""},{"name":"Jonathan Cohen","avatar":""},{"name":"Niels Schneider","avatar":""},{"name":"Stéphanie Murat","avatar":""},{"name":"Olivia Côte","avatar":""},{"name":"Syrus Shahidi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324458);
