INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu-hung-nhai-phan-1', 'Trò Chơi Sinh Tử: Húng Nhại - Phần 1', 'The Hunger Games: Mockingjay - Part 1', 'https://phimimg.com/upload/vod/20230912-1/df9036c25c95eb2dcf75fd2f24ad3582.jpg', 'https://phimimg.com/upload/vod/20230912-1/0c7083d297c6ffcb5a5fc82298ff6fed.jpg', '<p>Trong phần này, Katniss Everdeen trở thành biểu tượng của cuộc nổi loạn chống lại chính quyền độc tài Capitol... Đã thoát khỏi âm mưu của thế lực cầm quyền Panem vào cuối phần trước, Katniss Everdeen trở thành biểu tượng cho phong trào chống lại sự cai trị tàn bạo của Capitol và cùng lực lượng kháng chiến tập trung tại Quận 13. Trong khi đó, sang phần này nhân vật Tổng thống Snow đã thay thế Alma Coin trở thành nhân vật phản diện chính của câu chuyện. Sau khi bắt được người bạn chiến đấu Peeta Mellark của Katniss, Snow đã dùng mọi cách từ chiêu dụ đến đe dọa và tra tấn tinh thần để bắt Peeta và những người khác phải khai ra thông tin và phản bội Katniss. Đồng thời, ông ta vẫn tiếp tục xuất hiện trên các phương tiện truyền thông của Panem để khẳng định sức mạnh thống trị của Capitol lên 12 Quận trực thuộc, kết tội sự chống đối của Katniss và Quận 13 là hành động phản bội vô nghĩa.</p>', 'Full', 1, 'single', 'completed', 38, 2014, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Stanley Tucci","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324458);
