INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-than-dieu-dai-hiep', 'Tân Thần Điêu Đại Hiệp', 'The Romance of the Condor Heroes', 'null', 'https://phimimg.com/upload/vod/20230911-1/ee0d59458c3ec16ac71fa036faf2f412.jpg', '<p>Bối cảnh của Thần điêu hiệp lữ là vào cuối thời Nam Tống, khi quân Mông Cổ đã lớn mạnh, tiêu diệt hầu hết châu Á, châu Âu, đang trực tiếp uy hiếp an nguy của Nam Tống. Câu chuyện xoay quanh tình yêu của hai nhân vật chính là Dương Quá và Tiểu Long Nữ giữa những cuộc chiến tang thương đẫm máu cả trên giang hồ lẫn chiến trường.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 39, 2014, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xiao","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Mao Xiaotong","avatar":""},{"name":"Elvis Han","avatar":""},{"name":"Zong Feng Yan","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Leo Wu","avatar":""},{"name":"Zhang Xinyu","avatar":""},{"name":"Zhang Meng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324458);
