INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-kich-2013', 'Phục Kích', 'Ambushed', 'https://phimimg.com/uploads/movies/20260710/phuc-kich-2013-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/phuc-kich-2013-poster.webp', '<p>Trong thế giới ngầm hỗn loạn của Los Angeles, đặc vụ Maxwell đang tiến gần đến việc triệt phá một đường dây buôn lậu cocaine quốc tế do tên trùm tội phạm Vincent Camastra cầm đầu. Khi đặc vụ Beverly Royce thâm nhập vào băng đảng ma túy và nhận thấy mình đang dấn thân vào một vụ án phức tạp hơn nhiều, vụ án trở nên mang tính cá nhân đối với Maxwell, người phải chiến đấu chống lại những kẻ giết người tàn nhẫn và những cảnh sát biến chất trong một màn kết thúc đầy kịch tính để đưa bọn tội phạm ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 44, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Randy Couture","avatar":""},{"name":"Gianni Capaldi","avatar":""},{"name":"Carly Pope","avatar":""},{"name":"Susie Abromeit","avatar":""},{"name":"Daniel Bonjour","avatar":""},{"name":"Cinthya Carmona","avatar":""},{"name":"Michael Rivera","avatar":""},{"name":"Holly Lynch","avatar":""},{"name":"William McNamara","avatar":""},{"name":"Victoria De Mare","avatar":""},{"name":"Mindy Robinson","avatar":""},{"name":"Eline Van der Velden","avatar":""},{"name":"Frank Mercuri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Hard Rush","Ambushed AUST","Emboscada","Гонка [Ambushed]","Ambushed"]', 1784690324458);
