INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-hi-vong-va-hoc-sinh-tuyet-vong-phan-1', 'Học Viện Hi Vọng và Học Sinh Tuyệt Vọng (Phần 1)', 'Danganronpa (Season 1)', 'https://phimimg.com/upload/vod/20260622-1/dc8f5edb24af318e23c82001cecbe3dd.jpg', 'https://phimimg.com/upload/vod/20260622-1/0f56c63e78c89f3d403e7b78e7b81f1b.jpg', '<p>Vốn chỉ là một học sinh bình thường không có tài năng gì nổi bật, Makoto Naegi bất ngờ trúng xổ số để giành một suất học tại Học viện đỉnh cao Hope&#39;s Peak — nơi vốn chỉ dành cho những thiên tài kiệt xuất nhất. Thế nhưng, thay vì mở ra một cuộc sống trung học trong mơ, tấm vé này lại đẩy cậu vào chuỗi ngày tuyệt vọng tột cùng. Bởi lẽ, cách duy nhất để tốt nghiệp khỏi Học viện Hope&#39;s Peak là phải sát hại một trong những người bạn cùng lớp của mình mà không bị phát hiện, hoặc chấp nhận trở thành nạn nhân của họ.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 36, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Chiwa Saito","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Saki Fujita","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Mai Nakahara","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"TARAKO","avatar":""},{"name":"Takako Sasuga","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Akira Ishid","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["弹丸论破：希望的学园与绝望的高中生","弹丸论破 希望学园与绝望高中生","超级弹丸论破2.5 狛枝凪斗与世界的破坏者","弹丸论破3 The End of 希望之峰学园","Danganronpa – The Animation","ダンガンロンパ3 -The End of 希望ヶ峰学園- 希望編 希望の学園と絶望の高校生","Super Danganronpa 2.5: Komaeda Nagito to Sekai no Hakaisha","スーパーダンガンロンパ2.5 狛枝凪斗と世界の破壊者","Danganronpa The Animation","Danganronpa 3 Mirai Hen","Danganronpa 3 Kibou Hen","ダンガンロンパ３ The End of 希望ヶ峰学園 未来編","Danganronpa 3: The End of Kibōgamine Gakuen - Mirai-Hen","Пуля-доказательство: Академия надежды и отчаявшиеся старшеклассники","Опровергающая пуля: Академия надежды и отчаявшиеся старшеклассники","Данганронпа, Школа отчаяния","Школа надежды и безнадёжные школьники","Danganronpa","Danganronpa 3: The End of Hope''s Peak Academy - Side: Hope","Danganronpa 3: The End of Hope''s Peak High School - Future Arc","ダンガンロンパ 希望の学園と絶望の高校生 The Animation"]', 1784690324458);
