INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien-hi-vong-va-hoc-sinh-tuyet-vong-phan-1', 'Học Viện Hi Vọng và Học Sinh Tuyệt Vọng (Phần 1)', 'Danganronpa (Season 1)', 'học viện hi vọng và học sinh tuyệt vọng (phần 1) danganronpa (season 1) megumi ogata yoko hikasa kanata hongo chiwa saito junichi suwabe takuya eguchi toshiyuki morikawa saki fujita rie kugimiya mai nakahara keiji fujiwara kenta miyake hidekatsu shibata inori minase tarako takako sasuga aya hirano akira ishid 弹丸论破：希望的学园与绝望的高中生 弹丸论破 希望学园与绝望高中生 超级弹丸论破2.5 狛枝凪斗与世界的破坏者 弹丸论破3 the end of 希望之峰学园 danganronpa – the animation ダンガンロンパ3 -the end of 希望ヶ峰学園- 希望編 希望の学園と絶望の高校生 super danganronpa 2.5: komaeda nagito to sekai no hakaisha スーパーダンガンロンパ2.5 狛枝凪斗と世界の破壊者 danganronpa the animation danganronpa 3 mirai hen danganronpa 3 kibou hen ダンガンロンパ３ the end of 希望ヶ峰学園 未来編 danganronpa 3: the end of kibōgamine gakuen - mirai-hen пуля-доказательство: академия надежды и отчаявшиеся старшеклассники опровергающая пуля: академия надежды и отчаявшиеся старшеклассники данганронпа, школа отчаяния школа надежды и безнадёжные школьники danganronpa danganronpa 3: the end of hope''s peak academy - side: hope danganronpa 3: the end of hope''s peak high school - future arc ダンガンロンパ 希望の学園と絶望の高校生 the animation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-ma-thuat-phan-2', 'Vương Quốc Ma Thuật (Phần 2)', 'Magi (Season 2) (The Kingdom Of Magic)', 'https://phimimg.com/upload/vod/20260111-1/5b3698cbbc2f4d0772de95b6c8b08c50.jpg', 'https://phimimg.com/upload/vod/20260111-1/227f938f194029f46c03654af6c6aa92.jpg', '<p>Câu chuyện là một dòng chảy của số phận và cuộc chiến bảo vệ thế giới đi theo con đường lẽ phải.Aladin, nhân vật chính của bộ phim, đã đặt ra mục tiêu khám phá thế giới sau khi gần hết quãng đời mình bị mắc kẹt trong một căn phòng. Người bạn thân nhất của cậu ta là cây sáo và linh hồn của lửa mang tênUgo.Chẳng bao lâu sau, Aladin phát hiện ra mình là một Magi, một nhà ma thuật có quyền chọn vua, và cậu ấy được sinh ra để lựa chọn các vị vua, những người sẽ đi theo con đường chân chính, chiến đấu chống lại những người muốn tiêu diệt số phận. Cùng đồng hành với Aladin trên chuyến phiêu lưu ấy là những người bạn đến từ thế giới Ngàn Lẻ Một Đêm - Ali 33, Sinbad cùng chiến đấu với nhau để giữ sự cân bằng cho thế giới.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 20, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaori Ishihara","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Daisuke Ono","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["魔笛","魔奇少年","魔笛MAGI","マギ The Kingdom of Magic","マギ The Labyrinth of Magic","เมไจ อาละดินผจญภัย","MAGI 魔奇少年","Маґі: Лабіринт магії","Маґі: Королівство магії","Magi: The Labyrinth of Magic","Magi: The Kingdom of Magic","マギ"]', 1784690324458);
