INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xoay-so-phan-1', 'Xoay Sở (Phần 1)', 'Getting On (Season 1)', 'https://phimimg.com/upload/vod/20260616-1/99ce90be76f2328ed29427f2482bdb77.jpg', 'https://phimimg.com/upload/vod/20260616-1/844e63350256a21a202e92339fa263b7.jpg', '<p>Lấy bối cảnh tại khu chăm sóc đặc biệt dành cho người già của một bệnh viện đang xuống cấp, <em>Getting On</em> theo chân những cô y tá luôn bị quá tải, cùng các bác sĩ và nhà quản lý luôn trong trạng thái lo âu, khi họ phải vật lộn với thực tế dở khóc dở cười, trần trụi nhưng cũng đầy lòng trắc ẩn của công việc chăm sóc người cao tuổi.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 25, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Laurie Metcalf","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Mel Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Getting On"]', 1784690324458);
