INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-nam-tay-anh', 'Hãy Nắm Tay Anh', 'Hold My Hand', 'https://phimimg.com/upload/vod/20260611-1/7cb48cbcfed5b0b4c75fd8ae51c462c0.jpg', 'https://phimimg.com/upload/vod/20260611-1/b30c13455dd5d7867d663ebb43d64976.jpg', '<p>Han Yeon Soo – cô gái hiền lành và lương thiện – bất ngờ rơi vào bi kịch khi cha qua đời, mẹ bị sát hại, còn bản thân bị chính bạn thân vu oan và tống vào tù. Bộ phim xoay quanh hành trình Yeon Soo quyết tâm chiến đấu để minh oan cho mình trước cáo buộc giết hại mẹ ruột. Với nội dung hấp dẫn, kịch tính và giàu cảm xúc, Hãy Nắm Tay Anh gửi gắm thông điệp ý nghĩa về sự tha thứ, hóa giải hận thù để hướng tới một cuộc sống bình yên.</p>', 'Hoàn Tất (65/65)', 65, 'series', 'completed', 35, 2013, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Si-eun","avatar":""},{"name":"Zin Tae-hyun","avatar":""},{"name":"Bae Geu-rin","avatar":""},{"name":"Lee Jae-hwang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["내 손을 잡아"]', 1784690324458);
