INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('9-lan-nguoc-thoi-gian', '9 Lần Ngược Thời Gian', 'Nine: Nine Time Travels', 'https://phimimg.com/upload/vod/20260609-1/85126132ef5c74289e4650a125437bc8.jpg', 'https://phimimg.com/upload/vod/20260609-1/a75149e5c5189f5c4d391294348dd619.jpg', '<p>Park Sun Woo làm nhân viên bảo vệ tại một đài truyền hình. Anh ấy yêu phóng viên tin tức Joo Min Young, người trong sáng và trung thực. Park Sun Woo sau đó lấy được 9 món hương, cho phép anh quay ngược thời gian 20 năm. Sun Woo du hành về quá khứ với nỗ lực giữ an toàn cho gia đình để thay đổi thế giới mà anh đang sống ngày nay. Tuy nhiên, điều này không phải là không có hậu quả vì hành động của anh trong quá khứ ảnh hưởng đến cuộc sống của nhiều người ở hiện tại, trong đó có anh.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 34, 2013, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jin-uk","avatar":""},{"name":"Jo Yoon-hee","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Uhm Hyo-seop","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Park Hyung-sik","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Oh Min-suk","avatar":""},{"name":"Lee Seung-joon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Nine 9 Times Time Travel","Nine：九回时间旅行","Nine Nine Time Travels","九转迴香","나인  아홉 번의 시간여행","Nain: Ahob beonui Shiganyeohaeng","Nine: Ahop Beonui Siganyeohaeng","Nain: Ahop Beonui Siganyeohaeng","九回時空旅行","九轉時光的旅行","Nine：九回時間旅行"