INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuon-ngon-tu', 'Khu Vườn Ngôn Từ', 'The Garden Of Words', 'https://phimimg.com/upload/vod/20260603-1/97a4c8a5bc18ac4a9051caa50b68a39f.jpg', 'https://phimimg.com/upload/vod/20260603-1/a674cfe961048a18463b2befcfb08d44.jpg', '<p>Một buổi sáng mùa mưa, trên đường đến trường, cậu đã cúp tiết lang thang đến một khu vườn để phác thảo mẫu giày và bắt gặp một cô gái quyến rũ tên Yukino Yukari đang ngồi uống bia ngắm mưa rơi. Họ không nói nhau lời nào, nhưng khi trời tạnh mưa, cô gái từ biệt cậu bằng một bài tanka khiến cậu bối rối. Tiếp tục những buổi sáng trời mưa tiếp theo, họ lại gặp nhau và...?</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miyu Irino","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Fumi Hirano","avatar":""},{"name":"Takeshi Maeda","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Takanori Hoshino","avatar":""},{"name":"Suguru Inoue","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Yuki Hayashi","avatar":""},{"name":"Wataru Sekine","avatar":""},{"name":"Risa Mizuno","avatar":""},{"name":"Hiroshi Shimozaki","avatar":""},{"name":"Kuniko Ishijima","avatar":""},{"name":"Taishi Murata","avatar":""},{"name":"Azusa Tadokoro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Le Jardin des Mots","Koto no Ha no Niwa","Сад поезії","Kotonoha no Niwa","The Garden of Kotonoha","Sanojen puutarha","Цэцэрлэгийн хүрээлэн дэхь үгс","حديقة الكلمات","言叶之庭","El jardin de las palabras","언어의 정원","Сад и