INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-den-ngay-tho', 'Màu đen Ngây Thơ', 'Innocent Noir / Inocent Noir', 'https://phimimg.com/upload/vod/20260603-1/1c64a543adc4b3b5ed1d2d431d8958ba.jpg', 'https://phimimg.com/upload/vod/20260603-1/4cb0c9a2e1ba63c5b8979bffa97a9304.jpg', '<p>Một sát thủ chuyên thực hiện những vụ ám sát trông như tự sát đã có cuộc gặp gỡ định mệnh với một người pha chế rượu, và chẳng bao lâu sau, hai chàng trai trẻ cùng nhau mơ về một tương lai tốt đẹp hơn ở vùng nông thôn. Một đòn chí mạng cuối cùng đã ngăn cách họ với giấc mơ thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 23, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koh","avatar":""},{"name":"Yūdai","avatar":""},{"name":"Yasushi Takahashi","avatar":""},{"name":"Kazushi","avatar":""},{"name":"Shin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Inosento nowâru","イノセント・ノワール"]', 1784690324459);
