INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bao-thu-2', 'Cô Gái Báo Thù 2', 'I Spit on Your Grave 2', 'https://phimimg.com/upload/vod/20260602-1/d920ef3fe5f08c5eeb9d731869d1445d.jpg', 'https://phimimg.com/upload/vod/20260602-1/b6d0bf5d5a8a9733c346c5731e7d3752.jpg', '<p>Katie - người mẫu nghiệp dư rất hào hứng khi cô được nhận lời mời chụp một show ảnh mới. Tưởng đâu mọi chuyện tốt đẹp sẽ đến với cô, nhưng Katie lại lọt vào tay của một đường dây buôn người nhằm phục vụ cho thú vui bệnh hoạn của những kẻ có tiền.
 Sau khi bắt cóc, đánh đập dã man và hãm hiếp cô gái tội nghiệp, chúng đinh ninh rằng cô đã chết và vô tình để Katie trốn được. Cô gái trẻ mang trong lòng đầy hận thù lên kế hoạch cho tất cả những kẻ đã hãm hại mình phải chịu kết cục thảm khốc nhất...</p>', 'Full', 1, 'single', 'completed', 24, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jemma Dallender","avatar":""},{"name":"Joe Absolom","avatar":""},{"name":"Aleksandar Aleksiev","avatar":""},{"name":"Yavor Baharov","avatar":""},{"name":"Mary Stockley","avatar":""},{"name":"Michael Dixon","avatar":""},{"name":"Valentine Pelka","avatar":""},{"name":"Peter Silverleaf","avatar":""},{"name":"George Zlatarev","avatar":""},{"name":"Dimo Alexiev","avatar":""},{"name":"Kacey Barnfield","avatar":""},{"name":"Ivan Ivanov","avatar":""},{"name":"Krasimir Ortakchiev","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Bez litosci II","Vengeance","Dulce venganza 2","Oeil pour oeil 2","Bez litości 2","Cô Gái Báo Thù 2","Doce Vingança 2","Məzarına Tüpürəcəm 2","Escupiré sobre tu tumba 2","I Spit on Your Grave 2"]', 1784690324459);
