INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghe-nong-doc-hai', 'Ghế Nóng Độc Hại', 'Toxic Hot Seat', 'https://phimimg.com/upload/vod/20260531-1/cc613ef0ed4fd23976a14a6beab931ae.jpg', 'https://phimimg.com/upload/vod/20260531-1/42a928d86657ddf2c28f976b153accb9.jpg', '<p>Phim tài liệu này của HBO tìm hiểu về mối quan hệ giữa tiền tài, chính trị và quyền lực, và một nhóm công dân chiến đấu để lật tẩy một chiến dịch đã di hại cho nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 26, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Toxic Hot Seat: Money, Politics & Power","Toxic Hot Seat"]', 1784690324459);
