INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-korra-phan-2', 'Huyền Thoại Korra (Phần 2)', 'The Legend Of Korra (Season 2) (Book Two: Spirits)', 'https://phimimg.com/upload/vod/20260521-1/b18928f89721c2d9e32550869b2f4ef3.jpg', 'https://phimimg.com/upload/vod/20260521-1/51e4079b06d18979466976b783e4c5b4.jpg', '<p>70 năm sau chiến tranh với Hỏa Quốc, Avatar Aang đã qua đời và người lãnh nhiệm trọng trách tiếp theo của ông là Korra, một cô bé sinh ra tại một ngôi làng Thủy tộc ở Nam cực. Lúc bước vào tuổi 17, sau khi đã thuần thục ba nguyên tố lửa, nước và đất, Korra khăn gói đến thành phố Cộng Hòa để mong được sư Tenzin truyền dạy nguyên tố cuối cùng. Nhưng tất cả trở nên khó khăn hơn khi cô gái trẻ Korra không thể làm chủ bản thân để có thể tới đích đến mình mong muốn. Và trên con đường gian nan đó, Korra dần khám phá những thế lực phản động phía sau mặt tối đô thành...</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 17, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Janet Varney","avatar":""},{"name":"David Faustino","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Seychelle Gabriel","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Dee Bradley Baker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Avatar: A Lenda de Korra","Avatar: Die Legende von Korra","La Légende de Korra","ლეგ