INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-ao-42-huyen-thoai', 'Số Áo 42 Huyền Thoại', '42', 'https://phimimg.com/upload/vod/20260517-1/e1f8e38b09b644eb520116467fa31675.jpg', 'https://phimimg.com/upload/vod/20260517-1/1bbf03097eafd45ebca5ffc54284bf7f.jpg', '<p>Chuyện phim kể về Jackie Robinson, cầu thủ da đen đầu tiên chơi ở giải bóng chày chuyên nghiệp của Mỹ trong màu áo đội Brooklyn Dodgers của New York. Jackie đã phải vượt qua rất nhiều sự kỳ thị, cản trở để khẳng định tài năng của mình, đồng thời mở đường cho nhiều vận động viên da đen khác tiến vào lĩnh vực thể thao ở Mỹ.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chadwick Boseman","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Nicole Beharie","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Ryan Merriman","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"André Holland","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Hamish Linklater","avatar":""},{"name":"T.R. Knight","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Номер 42-ри","42号","42: The Jackie Robinson story","42 (2013)","42","Сорок два","42号传奇","四十二號傳奇","The 42 story"]', 1784690324459);
