INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-nhin-cuoc-song-cua-sam', 'Góc Nhìn Cuộc Sống Của Sam', 'Life According To Sam', 'https://phimimg.com/upload/vod/20260518-1/700738c317b9cd0a71e0fab0cb52e3ed.jpg', 'https://phimimg.com/upload/vod/20260518-1/52696ab031ce9d3c5ada2250e3e03ed9.jpg', '<p>Progeria là một căn bệnh di truyền hiếm gặp, gây tử vong, khiến trẻ em lão hóa nhanh; những nạn nhân nhỏ tuổi của căn bệnh này hiếm khi sống quá 13 tuổi. Bộ phim tài liệu cảm động này khám phá thế giới kỳ lạ của Sam Berns và hành trình không ngừng nghỉ tìm kiếm phương pháp điều trị và chữa khỏi bệnh của cha mẹ cậu bé (cả hai đều là bác sĩ) để cứu con trai họ khỏi căn bệnh này.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Berns","avatar":""},{"name":"Leslie Gordon","avatar":""},{"name":"Scott Berns","avatar":""},{"name":"Francis Collins","avatar":""},{"name":"Dave Matthews","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Good Life","Life According to Sam"]', 1784690324459);
