INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hau-ban-lam-duoc', 'Hoa Hậu Bạn Làm Được', 'Miss You Can Do It', 'https://phimimg.com/upload/vod/20260518-1/c1b547cada7c57999ca698ba488e079e.jpg', 'https://phimimg.com/upload/vod/20260518-1/fc5f21a52060eba9790bec152ceae537.jpg', '<p>Miss You Can Do It ghi lại cuộc thi Hoa hậu Hoàn vũ Hoa Kỳ 2008 của Abbey Curran, Hoa hậu Iowa Hoa Kỳ 2008 và là người phụ nữ khuyết tật đầu tiên tham gia cuộc thi Hoa hậu Hoàn vũ Hoa Kỳ, cùng tám cô gái khuyết tật khác nhau về thể chất và trí tuệ khi họ tham gia cuộc thi Hoa hậu Hoàn vũ. Abbey đã sáng lập cuộc thi Hoa hậu Hoàn vũ thường niên vào năm 2004, và các cô gái cùng gia đình đã đến từ khắp nơi trên đất nước để tham gia đêm duy nhất này, nơi vẻ đẹp nội tâm và khả năng của họ được tỏa sáng.</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Abbey Curran","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Garota Você Pode","Miss You Can Do It"]', 1784690324459);
