INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-vong-nhot-nhat-trong-dong-suoi-roc-rach', 'Cầu Vồng Nhợt Nhạt Trong Dòng Suối Róc Rách', 'A Pale Rainbow Over The Brook', 'https://phimimg.com/upload/vod/20260518-1/48028ecdd26c92394026093a7486f641.jpg', 'https://phimimg.com/upload/vod/20260518-1/3dcab2a02b45077bba6190b243fccd5f.jpg', '<p>Kou là một đầu bếp đầy mơ ước, sống một mình ở Tokyo. Khi nghe tin cha mất, anh vội vã trở về quê nhà. Đối mặt với áp lực phải kết hôn từ gia đình, anh trốn đến nơi tụ tập bí mật thời thơ ấu, và vô tình gặp lại Eiji, giáo viên trung học mà anh đã thầm thương trộm nhớ. Sự xuất hiện của Eiji khơi dậy những cảm xúc trong lòng Kou; liệu tình yêu bị ngăn cấm của họ có thể thành hiện thực?</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Seseragi no awai niji","せせらぎの淡い虹"]', 1784690324459);
