INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-heck-phan-5', 'Gia đình Heck (Phần 5)', 'The Middle (Season 5)', 'https://phimimg.com/upload/vod/20260516-1/4d61b9a6362bb97d7cd82c48fea00735.jpg', 'https://phimimg.com/upload/vod/20260516-1/82bcf3f2f2ef83a09c06d1ccb0b18b8a.jpg', '<p>Những rắc rối thường nhật của một người phụ nữ đã kết hôn và gia đình không mấy hòa thuận của cô, cùng những nỗ lực để tồn tại trong cuộc sống nói chung tại thành phố Orson, Indiana.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patricia Heaton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Eden Sher","avatar":""},{"name":"Atticus Shaffer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["左右不逢源","中产家庭","中之道","Anyám borogass","Családom és egyéb emberfajták","ザ・ミドル ～中流家族のフツーの幸せ～","คุณแม่สามัญประจำบ้าน","The Middle"]', 1784690324459);
