INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sat-su-noi-gian-cua-technovore-nguoi-sat-su-troi-day-cua-technovore', 'Người Sắt: Sự Nổi Giận Của Technovore (Người Sắt: Sự Trỗi Dậy Của Technovore)', 'Iron Man: Rise Of Technovore', 'https://phimimg.com/upload/vod/20260515-1/36430f0db6e4fbd232870b8db39c44b0.jpg', 'https://phimimg.com/upload/vod/20260515-1/9ee02be2725851f9d7187dc74a4fa76b.jpg', '<p>Iron Man: Rise of Technovore(Người Sắt: Sự Nổi Giận Của Technovore) là một trong nhưng bộ phim hoạt hình về người sắt được chuyển thể từ comic. Lần này, thiên tài công nghệ trẻ và điên Ezekiel Stane đã phát triển một bộ áo giáp kỹ thuật hữu cơ mới mà dường như vượt trội hơn hẳn Iron Man. Khi Stane giải phóng một cuộc tấn công khủng bố trong thời gian ra mắt của Tony. Lần này Iron Man sẽ phải chống lại Ezekiel Stane, kẻ có bộ giáp công nghệ sinh học vượt trội so với công nghệ của Iron Man. Kẻ đã gài bẫy làm cho Iron Man phải chịu trách nhiệm về một vụ khủng bố và bị S.H.I.E.L.D. truy đuổi.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tessyo Genda","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Hiroe Oka","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Junko Minagawa","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Shuhei Sakaguchi","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Houko Kuwashima","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Hideaki Tezuka","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Iron Man - Rise of Technovore","Homem de Ferro: A Batalha Contra Ezekiel Stane","Iron Man: La rebelión de Technívoro","Iron Man: Surge el Tecnívoro","Aian Man: Raizu Obu Tekunovoa","Iron Man: Rise of Technovore","Iron Man Rise of Technovore","アイアンマン：ライズ・オブ・テクノヴォア","Gvozdeni čovek: Uspon Tehnovora","Железный Человек: Восстание Техновора","Vasember: Technovore ébredése","钢铁侠：噬甲危机","Iron Man : L''essor de Technovore","鋼鐵人：噬甲危機"]', 1784690324459);
