INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-tinh-nghi-phan-3', 'Kẻ Tình Nghi (Phần 3)', 'Person of Interest (Season 3)', 'kẻ tình nghi (phần 3) person of interest (season 3) jim caviezel michael emerson kevin chapman amy acker sarah shahi personne d''intérêt 嫌疑人 kohde ინტერესის ობიექტი مظنون فرد تحت نظر مظنون تحت نظر suspectul подозреваемый บุคคลต้องสงสัย особливо небезпечно у полі зору p.o.i person of interest', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-xu-oz-vi-dai-va-quyen-nang', 'Lạc Vào Xứ Oz Vĩ Đại và Quyền Năng', 'Oz The Great And Powerful', 'https://phimimg.com/upload/vod/20260511-1/9e50396f4cc354e4704692e3484441d2.jpg', 'https://phimimg.com/upload/vod/20260511-1/5ce1619ac3143e2483640b061f5f0f8f.jpg', '<p>Bộ phim được dựa trên bộ tiểu thuyết Oz của nhà văn L. Frank Baum, và cũng để tưởng nhớ tới bộ phim Phù thủy xứ Oz sản xuất năm 1939 bởi hãng MGM. Lấy bối cảnh từ 20 năm trước so với các sự kiện xảy ra trong bộ sách, Lạc vào xứ Oz vĩ đại và quyền năng tập trung vào nhân vật &quot;phù thủy xứ Oz&quot; Oscar Diggs, người đã lạc vào xứ Oz diệu kỳ và gặp gỡ ba phù thủy: &quot;phù thủy độc ác của miền Tây&quot; Theodora, &quot;phù thủy độc ác của miền Đông&quot; Evanora và Glinda &quot;phù thủy tốt bụng&quot;. Oscar sau đó gia nhập vào công cuộc tìm lại trật tự và hòa bình ở xứ Oz, cùng lúc đó anh cũng chiến đấu để hòa giải những bất đồng với những phù thủy kia và với cả chính bản thân mình.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Zach Braff","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Joey King","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Stephen R. Hart","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Tim Holmes","avatar":""},{"name":"Toni Wynne","avatar":""},{"name":"Rob Crites","avatar":""},{"name":"William Dick","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"John Lord Booth III","avatar":""},{"name":"Suzanne","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Le Monde Fantastique d''Oz","Oz, Mágico e Poderoso","Oz: The Great and Powerful","Oz le magnifique","The Wizard of Oz 0.5 - Oz the Great and Powerful","오즈 그레이트 앤드 파워풀","Oz - The Great and Powerful (2013)","Όζ: Μέγας Και Παντοδύναμος","Оз: Великият и могъщият","Oz: O Grande e Poderoso","Muhteşem ve Kudretli Oz","Die fantastische Welt von Oz","اوز بزرگ و قدرتمند","Oz: Wielki i Potężny","Oz: Möhtəşəm və Qüdrətli","Oz: El Poderoso","Oz: un mundo fantástico","Оз, велики и моћни","Оз: Великий та Могутній","Suur ja kõikvõimas Oz","Il grande e potente Oz","Varenais no Oza zemes","Óz, a hatalmas","Mocný vládce Oz","Grozavul și puternicul Oz","Mahtava Oz","Օզ։ ՄԵծ և սարսափելի","ოზი: დიადი და ძლევამოსილი","أوز: العظيم والقوي","اوز العظيم و القوى","ארץ אוז","オズ はじまりの戦い","Агуу хүчит Оз","Lạc vào xứ Oz vĩ đại và quyền năng","ออซ มหัศจรรย์พ่อมดผู้ยิ่งใหญ่","魔境仙踪","魔境仙蹤","奧茲大帝","Carstvo Velikog Oza","Ozas: didingas ir galingas","Cesta do krajiny Oz","Mogočni Oz","Волшебник страны Оз","Oz the Great and Powerful"]', 1784690324459);
