INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lac-vao-xu-oz-vi-dai-va-quyen-nang', 'Lạc Vào Xứ Oz Vĩ Đại và Quyền Năng', 'Oz The Great And Powerful', 'lạc vào xứ oz vĩ đại và quyền năng oz the great and powerful james franco mila kunis rachel weisz michelle williams zach braff bill cobbs joey king tony cox stephen r. hart abigail spencer bruce campbell ted raimi tim holmes toni wynne rob crites william dick gene jones john lord booth iii suzanne le monde fantastique d''oz oz, mágico e poderoso oz: the great and powerful oz le magnifique the wizard of oz 0.5 - oz the great and powerful 오즈 그레이트 앤드 파워풀 oz - the great and powerful (2013) όζ: μέγας και παντοδύναμος оз: великият и могъщият oz: o grande e poderoso muhteşem ve kudretli oz die fantastische welt von oz اوز بزرگ و قدرتمند oz: wielki i potężny oz: möhtəşəm və qüdrətli oz: el poderoso oz: un mundo fantástico оз, велики и моћни оз: великий та могутній suur ja kõikvõimas oz il grande e potente oz varenais no oza zemes óz, a hatalmas mocný vládce oz grozavul și puternicul oz mahtava oz օզ։ մեծ և սարսափելի ოზი: დიადი და ძლევამოსილი أوز: العظيم والقوي اوز العظيم و القوى ארץ אוז オズ はじまりの戦い агуу хүчит оз lạc vào xứ oz vĩ đại và quyền năng ออซ มหัศจรรย์พ่อมดผู้ยิ่งใหญ่ 魔境仙踪 魔境仙蹤 奧茲大帝 carstvo velikog oza ozas: didingas ir galingas cesta do krajiny oz mogočni oz волшебник страны оз oz the great and powerful', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('extraction', 'Extraction', 'Extraction', 'https://phimimg.com/upload/vod/20260511-1/894fdd92e80d83fbca574cbc70352cdf.jpg', 'https://phimimg.com/upload/vod/20260511-1/79345fd2a74ce6287371229f61825ea6.jpg', '<p>EXTRACTION, một tính năng độc quyền dành cho phiên bản kỹ thuật số, kể về một thành viên đội đặc nhiệm Mỹ, người sống sót duy nhất sau một nhiệm vụ giải cứu tù nhân thất bại. Bị buộc phải chiến đấu để thoát khỏi nhà tù an ninh tối cao của Chechnya, anh ta phải giữ cho mục tiêu của mình sống sót để bắt được một tên buôn vũ khí khủng bố đang đe dọa đến sinh mạng của hàng ngàn người.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Patrick Foo","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Joanne Kelly","avatar":""},{"name":"Falk Hentschel","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Chris Jai Alex","avatar":""},{"name":"Adam Croasdell","avatar":""},{"name":"Paul Duke","avatar":""},{"name":"Spencer Garrett","avatar":""},{"name":"Brandy Grace","avatar":""},{"name":"Jef Groff","avatar":""},{"name":"Chad Guerrero","avatar":""},{"name":"Ben Jenkin","avatar":""},{"name":"Jeff Leaf","avatar":""},{"name":"Roman Mitichyan","avatar":""},{"name":"Branden Morgan","avatar":""},{"name":"Richard","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Misión secreta","Extraction","Extraccion"]', 1784690324459);
