INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-trai-cam', 'Hương Vị Trái Cấm', 'Hardcore Comedy', 'https://phimimg.com/upload/vod/20260508-1/90e0862719d666b77fb1ccc84e0c5696.jpg', 'https://phimimg.com/upload/vod/20260508-1/cc10090b64f4dfab891315bb9f154dce.jpg', '<p>Hardcore Comedy là tuyển tập gồm ba câu chuyện độc lập mang màu sắc hài hước táo bạo, pha trộn giữa tình yêu kỳ lạ, những tình huống trớ trêu, các trò đùa điên rồ và không khí gợi cảm. Phim đưa người xem đi qua nhiều cung bậc từ lãng mạn, hài nhảm đến hành động với những màn rượt đuổi xe, đụng độ giang hồ và các mối quan hệ đầy bất ngờ, …</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"關楚耀","avatar":""},{"name":"小肥","avatar":""},{"name":"衛詩雅","avatar":""},{"name":"陳偉霆","avatar":""},{"name":"陳靜","avatar":""},{"name":"梁競徽","avatar":""},{"name":"苟藝慧","avatar":""},{"name":"孫佳君","avatar":""},{"name":"蔡穎恩","avatar":""},{"name":"林盛斌","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zhong Kou Wei","Hardcore Comedy","重口味"]', 1784690324459);
