INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-vi-phan-1', 'Hoán Vị (Phần 1)', 'Orphan Black (Season 1)', 'https://phimimg.com/upload/vod/20260506-1/a54e14638472230a54fab95859a943cc.jpg', 'https://phimimg.com/upload/vod/20260506-1/edfb9e701fccf60a22e518997cd3e775.jpg', '<p>Khi Sarah chứng kiến vụ tự tử của một phụ nữ trông giống mình, cô lấy danh tính của người đã chết... và khám phá một thế giới đầy bí mật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2013, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Tatiana Maslany","avatar":""},{"name":"Jordan Gavaris","avatar":""},{"name":"Josh Vokey","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Ari Millen","avatar":""},{"name":"Kevin Hanchard","avatar":""},{"name":"Kristian Bruun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Тъмното дете","Клонинги","오펀 블랙","Orphan Black"]', 1784690324459);
