INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bep-samurai-mot-tinh-yeu-that-su', 'Chuyện Bếp Samurai: Một Tình Yêu Thật Sự', 'A Tale Of Samurai Cooking: A True Love Story', 'https://phimimg.com/upload/vod/20260505-1/14e2cb456e1215b96a90015a0641f2f2.jpg', 'https://phimimg.com/upload/vod/20260505-1/250f9697730e565c161190de76795da9.jpg', '<p>Đầu bếp Haru đã kết hôn với gia đình huyền thoại &quot;Kitchen Samurai&quot;. Nhưng chồng cô, người kế vị của gia đình Funaki, lại không biết nấu ăn. Haru thề sẽ biến anh thành một đầu bếp samurai siêu đẳng và bắt đầu dạy chồng mới cách nấu ăn.</p>', 'Full', 1, 'single', 'completed', 36, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Ueto","avatar":""},{"name":"Kengo Kora","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Yui Natsukawa","avatar":""},{"name":"Riko Narumi","avatar":""},{"name":"Kenta Hamano","avatar":""},{"name":"Hana Ebise","avatar":""},{"name":"Naoto Ogata","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Takeshi Kaga","avatar":""},{"name":"Eri Fuse","avatar":""},{"name":"Ichirôta Miyakawa","avatar":""},{"name":"Takashi Sasano","avatar":""},{"name":"Katsuyuki Tai","avatar":""},{"name":"Masatoshi Nakamura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["BUSHI NO KONDATE","武士的菜單","Szamuráj menü","武士の献立"]', 1784690324459);
