INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-bep-samurai-mot-tinh-yeu-that-su', 'Chuyện Bếp Samurai: Một Tình Yêu Thật Sự', 'A Tale Of Samurai Cooking: A True Love Story', 'chuyện bếp samurai: một tình yêu thật sự a tale of samurai cooking: a true love story aya ueto kengo kora kimiko yo toshiyuki nishida yui natsukawa riko narumi kenta hamano hana ebise naoto ogata tasuku emoto takeshi kaga eri fuse ichirôta miyakawa takashi sasano katsuyuki tai masatoshi nakamura bushi no kondate 武士的菜單 szamuráj menü 武士の献立', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-sen', 'Bà Sen', 'Mrs Sen', 'https://phimimg.com/upload/vod/20260505-1/ada8103e4d876e10d204c4c6a6c326b6.jpg', 'https://phimimg.com/upload/vod/20260505-1/35eba3cb6fb3bdf19502c51f5664e937.jpg', '<p>Vào những giờ đầu của một buổi sáng tháng 12, tiếng chuông điện thoại phá tan sự yên tĩnh của gia đình Sen. Anuradha, người nhấc máy, sững sờ khi nghe giọng người gọi ở đầu dây bên kia. Chồng cô đã gặp tai nạn chết người ở Thái Lan và rơi vào hôn mê, và cô cần phải bắt chuyến bay sớm nhất có thể để đến bệnh viện. Thế giới của cả Anuradha và Sohini đều sụp đổ. Cả hai bà Sen đều không biết phải đối mặt với khủng hoảng mà họ chưa từng tưởng tượng đến như thế nào. Thi thể của Somnath được hỏa táng và Anuradha muốn mang tro cốt về Ấn Độ, cho cha của Somnath để làm lễ tang. Sohini không phản đối, nhưng khi chuẩn bị ra sân bay, Sohini ngất xỉu. Bác sĩ được gọi đến và ông yêu cầu Anuradha đưa Sohini nhập viện một lần nữa. Tại bệnh viện, Sohini được chẩn đoán là bị tổn thương nội tạng và xuất huyết nội. Tuy nhiên, các bác sĩ nói rõ rằng chỉ còn vài ngày nữa là Sohini sẽ chết.</p>', 'Trailer', 1, 'single', 'ongoing', 20, 2013, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Rituparna Sengupta","avatar":""},{"name":"Hrishitaa Bhatt","avatar":""},{"name":"Rohit Roy","avatar":""},{"name":"Biplab Chatterjee","avatar":""},{"name":"Subhasish Mukherjee","avatar":""},{"name":"Shankar Chakraborty","avatar":""},{"name":"Priyangshu Chowdhury","avatar":""},{"name":"Rupsha Guha","avatar":""},{"name":"Ushasie Chakraborty","avatar":""},{"name":"Anashua Majumdar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mrs Sen"]', 1784690324459);
