INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-cha-me-phan-5', 'Làm Cha Mẹ (Phần 5)', 'Parenthood (Season 5)', 'làm cha mẹ (phần 5) parenthood (season 5) peter krause lauren graham dax shepard erika christensen monica potter sam jaeger joy bryant mae whitman miles heizer max burkholder savannah paige rae tyree brown xolo maridueña bonnie bedelia craig t. nelson parenthood', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-khoai-tay', 'Ngôi Sao Khoai Tây', 'Potato Star', 'https://phimimg.com/upload/vod/20231207-1/f11b617c1d56d4b4a848d6f1aa96a2af.jpg', 'https://phimimg.com/upload/vod/20231207-1/f8ea610956dcf8b2e2457899259dd329.jpg', '<p>Phim Ngôi Sao Khoai Tây tái hiện những tình huống lạ kỳ, những rắc rối oái oăm liên tục xảy đến với gia tộc họ Noh trong tình huống khẩn cấp, khi một thiên thạch mang hình thù na ná củ khoai tây bất ngờ xuất hiện, được tiên đoán là có khả năng va chạm với trái đất. Một thiên thạch hình dáng khoai tây lạ kỳ “bỗng dưng ghé thăm” trái đất, sau đó liên tục thay đổi quỹ đạo, đe dọa sự sống còn và khiến tất cả mọi người rơi vào hỗn loạn, sợ hãi. Trong tình thế căng thẳng, gia đình họ Noh càng chứng minh thêm cách ứng phó kỳ lạ của con người trước sự hữu hạn của thời gian, thay vì đoàn kết chống thảm họa thì các thành viên trong gia đình lại bắt đầu bộc lộ “bản chất thật”, gây ra vô số rắc rối, cùng với đó là hàng loạt tình huống và mâu thuẫn khó đỡ. Nội dung chính xoay quanh đời sống của gia đình nhiều thế hệ với vô số rắc rối, nhưng Ngôi sao khoai tây không hề cho thấy sự lặp lại những tình huống “sóng gió” , thay vào đó, cách xử lý tình huống lẫn “đường đi” từng tuyến nhân vật trong phim được xây dựng đầy khác biệt. Lỡ Trái đất bị một hành tinh lớn bằng nửa mặt trăng đâm vào thì sao? Những công việc thường ngày, những chuyện rắc rối và tình cảm yêu đương của ban sẽ thay đổi thế nào? Bộ phim sitcom này sẽ khắc họa cuộc sống hài hước của một gia đình qua những tình huống nguy hiểm, li kì và không kém phần hấp dẫn được tạo nên bởi một cuộc đụng độ giữa hai hành tinh</p>', 'Hoàn Tất (92/92)', 92, 'series', 'completed', 28, 2013, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Soon Jae","avatar":""},{"name":"Yeo Jin Goo","avatar":""},{"name":"Ha Yeon Soo","avatar":""},{"name":"Go Kyung Pyo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324459);
