INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-canh-dong-o-anh', 'Một cánh đồng ở Anh', 'A Field in England', 'https://phimimg.com/upload/vod/20260409-1/75745b2f210da30e460e89f425d46d69.jpg', 'https://phimimg.com/upload/vod/20260409-1/d1feded00e815ac69007932fbd939ba6.jpg', '<p>Trong cuộc Nội chiến Anh thế kỷ 17, một nhóm nhỏ lính đào ngũ chạy trốn khỏi một trận chiến khốc liệt qua một cánh đồng hoang. Họ bị một nhà giả kim bắt giữ, người buộc nhóm phải giúp ông ta tìm kiếm một kho báu ẩn giấu mà ông ta tin rằng đang được chôn giấu trong cánh đồng. Vượt qua một vòng tròn nấm khổng lồ, nơi cung cấp bữa ăn đầu tiên của họ, nhóm nhanh chóng rơi vào hỗn loạn với những cuộc tranh cãi, đánh nhau và hoang tưởng, và khi rõ ràng rằng kho báu có thể không phải là vàng, họ dần trở thành nạn nhân của những năng lượng đáng sợ bị giam giữ bên trong cánh đồng.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Reece Shearsmith","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Richard Glover","avatar":""},{"name":"Peter Ferdinando","avatar":""},{"name":"Ryan Pope","avatar":""},{"name":"Julian Barratt","avatar":""},{"name":"Laura Obiols","avatar":""},{"name":"Sara Dee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Поле в Англии","腐国恶土","A Field in England"]', 1784690324459);
