INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-gia-pho-wall', 'Sói Già Phố Wall', 'The Wolf of Wall Street', 'https://phimimg.com/upload/vod/20260326-1/09e1ea513e6530d6f5fe2a00eece8511.jpg', 'https://phimimg.com/upload/vod/20260326-1/4d8aa88f610951ffc563bc52a7dd6dba.jpg', '<p>Tác phẩm về ông trùm chứng khoán Jordan Belfort vẽ nên một xã hội Mỹ tràn ngập tình dục, ma túy và đạo đức suy đồi vào cuối thập niên 1980, đầu thập niên 1990. &nbsp;Phim được phóng tác dựa trên kịch bản chuyển thể từ cuốn hồi ký nổi tiếng ăn khách của Jordan Belfort, một tay môi giới cổ phiếu giá trị thấp từ Long Island đã trở nên cực kỳ nổi tiếng khi xuất bản cuốn hồi ký sau thời gian thụ án 20 tháng tù do từ chối hợp tác với cảnh sát điều tra trong vụ bê bối chứng khoán giả mạo đã suýt nữa làm sụp đổ cả phố Wall vào thập niên 90, dính líu đến giới ngân hàng và cả các băng đảng mafia. The Wolf Of Wall Street đã phản ánh sự thăng trầm của thế giới tài chính Wall Street cùng với những cuộc tiệc tùng chơi bời ngập trong ma túy và rượu chè, cuối cùng đã làm đảo lộn cuộc sống của những con người đắm chìm trong nó...</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Rob Reiner","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Jean Dujardin","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Cristin Milioti","avatar":""},{"name":"Christine Ebersole","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Katarina Čas","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Kenneth Choi","avatar":""},{"name":"Brian Sacca","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["华尔街狼人","华尔街之狼","Wilk z Wall Street","더 울프 오브 월 스트리트","คนจะรวย ช่วยไม่ได้","Wall Streeti hunt","華爾街之狼","Ուոլթ Սթրիթի Գայլը","Le Loup de Wall Street","דער וואלף פון וואל סטריט","Воўк з Уол-стрыт","Вълкът от Уолстрийт","Волкот од Волстрит","Волк с Уолл-стрит","Вук са Вол стрита","Вовк з Уолл-стріт","Уолл-стрит кашкăрĕ","Уолл-стрит қасқыры","Ο λύκος της Wall Street","O lobo de Wall Street","El lobo de Wall Street","El llobu de Wall Streeet","Uoll-strit canavarı","Vuk s Wall Streeta","Volstrītas vilks","A Wall Street farkasa","Lupul de pe Wall Street","Vlk z Wall Street","Volk z Wall Streeta","უოლ-სტრიტიშ გერი","უოლ-სტრიტის მგელი","Para Avcısı","ذئب وول ستريت","گرگ وال استریت","ولف آف وال استریت","ديب وول ستريت","הזאב מוול סטריט","ദി വുൾഫ്‌ ഓഫ്‌ വാൾസ്ട്രീറ്റ്‌","ウルフ・オブ・ウォールストリート","Уолл-стрит карышкыры","Sói Già Phố Wall","द वुल्फ ऑफ वॉल स्ट्रीट","দ্য উল্‌ফ অব ওয়াল স্ট্রিট","The Wolf of Wall Street"]', 1784690324459);
