INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('soi-gia-pho-wall', 'Sói Già Phố Wall', 'The Wolf of Wall Street', 'sói già phố wall the wolf of wall street leonardo dicaprio jonah hill margot robbie matthew mcconaughey kyle chandler rob reiner jon bernthal jon favreau jean dujardin joanna lumley cristin milioti christine ebersole shea whigham katarina čas p.j. byrne kenneth choi brian sacca 华尔街狼人 华尔街之狼 wilk z wall street 더 울프 오브 월 스트리트 คนจะรวย ช่วยไม่ได้ wall streeti hunt 華爾街之狼 ուոլթ սթրիթի գայլը le loup de wall street דער וואלף פון וואל סטריט воўк з уол-стрыт вълкът от уолстрийт волкот од волстрит волк с уолл-стрит вук са вол стрита вовк з уолл-стріт уолл-стрит кашкăрĕ уолл-стрит қасқыры ο λύκος της wall street o lobo de wall street el lobo de wall street el llobu de wall streeet uoll-strit canavarı vuk s wall streeta volstrītas vilks a wall street farkasa lupul de pe wall street vlk z wall street volk z wall streeta უოლ-სტრიტიშ გერი უოლ-სტრიტის მგელი para avcısı ذئب وول ستريت گرگ وال استریت ولف آف وال استریت ديب وول ستريت הזאב מוול סטריט ദി വുൾഫ്‌ ഓഫ്‌ വാൾസ്ട്രീറ്റ്‌ ウルフ・オブ・ウォールストリート уолл-стрит карышкыры sói già phố wall द वुल्फ ऑफ वॉल स्ट्रीट দ্য উল্‌ফ অব ওয়াল স্ট্রিট the wolf of wall street', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguon-von-nhan-luc', 'Nguồn Vốn Nhân Lực', 'Human Capital', 'https://phimimg.com/upload/vod/20260311-1/e26c58d1c793fbbc77af10654a0681d6.jpg', 'https://phimimg.com/upload/vod/20260311-1/f1a7cf3a5e223285e87eac568b81828b.jpg', '<p>Vào đêm trước Giáng sinh tại Lake Como, một người đi xe đạp bất ngờ bị xe jeep tông trong màn đêm lạnh giá. Vụ tai nạn tưởng chừng đơn lẻ ấy nhanh chóng kéo theo hàng loạt bí mật bị phơi bày. Sự việc trở thành bước ngoặt định mệnh, làm rung chuyển gia đình Bernaschi giàu có và gia đình Rovelli đang trên bờ vực phá sản. Khi sự thật dần được hé lộ, mỗi lựa chọn, mỗi tham vọng đều phải trả giá. Đây là câu chuyện căng thẳng về tiền bạc, đạo đức và những hệ lụy không thể lường trước.</p>', 'Full', 1, 'single', 'completed', 23, 2013, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Valeria Bruni Tedeschi","avatar":""},{"name":"Fabrizio Bentivoglio","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Fabrizio Gifuni","avatar":""},{"name":"Luigi Lo Cascio","avatar":""},{"name":"Giovanni Anzaldo","avatar":""},{"name":"Matilde Gioli","avatar":""},{"name":"Guglielmo Pinelli","avatar":""},{"name":"Gigio Alberti","avatar":""},{"name":"Bebo Storti","avatar":""},{"name":"Paolo Pierobon","avatar":""},{"name":"Silvia Cohen","avatar":""},{"name":"Gianluca Di Lauro","avatar":""},{"name":"Stefano Fiorentino","avatar":""},{"name":"Fulvio Mil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El capital humano","휴먼 캐피탈","Les opportunistes","Il capitale umano"]', 1784690324459);
