INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguon-von-nhan-luc', 'Nguồn Vốn Nhân Lực', 'Human Capital', 'nguồn vốn nhân lực human capital valeria bruni tedeschi fabrizio bentivoglio valeria golino fabrizio gifuni luigi lo cascio giovanni anzaldo matilde gioli guglielmo pinelli gigio alberti bebo storti paolo pierobon silvia cohen gianluca di lauro stefano fiorentino fulvio mil el capital humano 휴먼 캐피탈 les opportunistes il capitale umano', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wajma-chuyen-tinh-afghanistan', 'Wajma, Chuyện Tình Afghanistan', 'Wajma, an Afghan Love Story', 'https://phimimg.com/upload/vod/20260311-1/a2470fbb45dd730ac5c593c6657126b6.jpg', 'https://phimimg.com/upload/vod/20260311-1/e5712348c843988dd6698fb12323d636.jpg', '<p>Lấy bối cảnh Kabul bảo thủ, Wajma - một cô gái trẻ - bàng hoàng khi phát hiện mình mang thai ngoài giá thú. Bạn trai chối bỏ trách nhiệm, còn cha cô vì danh dự gia đình mà giam giữ con gái trong nhà. Bị dồn vào góc tường bởi định kiến và áp lực xã hội, Wajma rơi vào tuyệt vọng. Trong nỗ lực buộc mọi người phải đối diện với sự bất công và lựa chọn của mình, cô tìm đến một hành động cực đoan, đặt ra câu hỏi nhức nhối về tình yêu, danh dự và quyền được tự quyết của phụ nữ.</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Wazhma Bahar","avatar":""},{"name":"Mustafa Abdulsatar","avatar":""},{"name":"Haji Gul Aser","avatar":""},{"name":"Brehna Bahar","avatar":""},{"name":"Aquella Akram","avatar":""},{"name":"Mohamad Ehrar","avatar":""},{"name":"Sher Shah Eshan","avatar":""},{"name":"Shohab Hakimi","avatar":""},{"name":"Tahera Hashemi","avatar":""},{"name":"Assib Ibrahim","avatar":""},{"name":"Saleha Ibrahim","avatar":""},{"name":"Ramin Nassiri","avatar":""},{"name":"Zaid Podal","avatar":""},{"name":"Faida Raonaq","avatar":""},{"name":"Mujtaba Sabbar","avatar":""},{"name":"Farida Saleh","avatar":""},{"name":"Wali Shah","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Wajma, une fiancée afghane","Wajma, an Afghan Love Story","Wajma"]', 1784690324459);
