INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-6', 'Quá Nhanh Quá Nguy Hiểm 6', 'Fast & Furious 6', 'https://phimimg.com/upload/vod/20260219-1/0539db43e27bd4a55eb27a1a5a6cee33.jpg', 'https://phimimg.com/upload/vod/20260219-1/545bde5d673a9a47692eb426817eb81b.jpg', '<p>Sau khi Dom và Rio thực hiện trót lọt phi vụ cuỗm 100 triệu đô la ở phần trước, cả nhóm đã giải tán và đường ai nấy đi. Tuy nhiên, họ không thể trở về nhà và sẽ mãi mãi phải sống cảnh vất vưởng nay đây mai đó. &nbsp;Trong khi đó, đặc vụ Hobbs lại đang truy đuổi một băng đảng lính đánh thuê lộng hành xuyên 12 quốc gia do Owen Shaw cầm đầu. Cảnh sát bó tay, cách duy nhất để bắt được chúng là lấy độc trị độc. &nbsp;Đặc vụ Hobbs đưa ra lời đề nghị với Doms để tập hợp nhóm của anh lại ở London và giúp cảnh sát vây bắt băng đảng của Owen. Nếu thành công, Doms và các bạn của anh sẽ có được một bản lí lịch &quot;trong sáng&quot; để đàng hoàng trở về nhà.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Gina Carano","avatar":""},{"name":"Clara Paget","avatar":""},{"name":"Kim Kold","avatar":""},{"name":"Joe Taslim","avatar":""},{"name":"Samuel M. Stewart","avatar":""},{"name":"Benjamin Davies","avatar":""},{"name":"Matthew Stirling","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29