INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('90-phut-kinh-hoang', '90 Phút Kinh Hoàng', 'The Terror Live', 'https://phimimg.com/upload/vod/20260126-1/d37ea12630f392cff730a1bb6dbb751f.jpg', 'https://phimimg.com/upload/vod/20260126-1/660ec59e5b6a184c56e068ac3bf4e327.jpg', '<p>Yoon Young-Hwa vốn một bình luận viên truyền hình nhưng vì nhiều ly do, anh đang phải làm một công việc khác. Một buổi sáng, khi anh đang dẫn chương trình phát thanh quen thuộc thì một người nặc danh gọi vào chương trình và tuyên bố sẽ đánh sập cây cầu Mapo. Ban đầu, ai cũng nghĩ đó chỉ là trò đùa nhưng Yoon Young-Hwa nhanh chóng nhận ra đó là mối nguy thực sự. &nbsp;Từ nơi anh đang làm việc, có thể nhìn thấy cây cầu và ngay sau đó, thảm họa khủng khiếp đã xảy ra. Ngay khi đó, Yoon Young-Hwa đã nhận ra cơ hội để anh nổi tiếng đã tới và anh quyết định thực hiện bài bình luận nóng lên sóng trực tiếp .</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"David Lee","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Kim Hae-in","avatar":""},{"name":"Han Soo-hyun","avatar":""},{"name":"Kang Jin-ah","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Choi Jeong-hyun","avatar":""},{"name":"Lee Choon-yun","avatar":""},{"name":"Kim Ho-yeon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Terror, LIVE"