INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('47-lang-nhan', '47 Lãng Nhân', '47 Ronin', 'https://phimimg.com/upload/vod/20260126-1/1986034eaec1be87e6b95c1779089407.jpg', 'https://phimimg.com/upload/vod/20260126-1/b88cad29c1a94ad77b36bdbe971970f6.jpg', '<p>47 Lãng Nhân kể về cuộc phiêu lưu đầy sóng gió của 47 võ sĩ samurai không được thừa nhận (ronin). Sau khi vị chủ tướng, sư phụ của họ bị hại chết, nhóm võ sĩ này lên kế hoạch trả thù cho ông. Họ rời bỏ quê hương, lên đường báo thù cùng sự giúp đỡ của Kai (Keanu Reeves), một võ sĩ mang hai dòng máu Nhật - Anh. Những ronin này phải đối mặt với thế lực hắc ám, ma quỷ và phù thủy đầy quyền năng luôn tìm cách hãm hại và tiêu diệt họ.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Jin Akanishi","avatar":""},{"name":"Masayoshi Haneda","avatar":""},{"name":"Hiroshi Sogabe","avatar":""},{"name":"Takato Yonemoto","avatar":""},{"name":"Shû Nakajima","avatar":""},{"name":"Hiroshi Yamada","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Tanroh Ishida","avatar":""},{"name":"Yorick van Wageningen","avatar":""},{"name":"Ron Bottitta","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["浪魂47","47 Ronin - A Grande Batalha Samurai","47 로닌","47 Róninů","47 Ronin 3D","La Leyenda del Samurái: 47 Ronin","47 סמוראים","47 Ronin"]', 1784690324459);
