INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-tap-sinh', 'Thực Tập Sinh', 'The Internship', 'https://phimimg.com/upload/vod/20260116-1/eed8a2156773723ac631cb28afc5aef5.jpg', 'https://phimimg.com/upload/vod/20260116-1/33aa15d8ba42eaddebb1a6f411a8791e.jpg', '<p>Billy và Nick là nhân viên bán hàng có sự nghiệp và cuộc sống đang bị cản trở bởi thế giới kĩ thuật số hiện nay. Cố gắng để chứng minh họ không phải là những con người lỗi thời, bất chấp sự kém hiểu biết về thời đại bằng cách tham gia một khóa thực tập đáng mơ ước ở Google , cùng với một nhóm các sinh viên đại học xuất sắc. Thế nhưng, tìm được lối vào đến với điều không tưởng này mới chỉ là một nửa quãng đường. Bây giờ họ phải cạnh tranh với một nhóm những thiên tài ưu tú nhất, am hiểu công nghệ nhất trên thế giới để chứng minh rằng: chỉ có cái khó mới ló cái khôn.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vince Vaughn","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Dylan O''Brien","avatar":""},{"name":"Tiya Sircar","avatar":""},{"name":"Tobit Raphael","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Jessica Szohr","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Eric André","avatar":""},{"name":"Harvey Guillén","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Bruno Amato","avatar":""},{"name":"JoAnna Garcia Swisher","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["翻生求职党","挨踢实习生","Aprendices fuera de línea","Generation Praktikum","Aprendices fuera de linea","實習大叔","Praktikantai","Aprendices Fuera de Linea","Prakti.com - Die klicken nicht richtig","Prakticom","Le Stage","Os Estagiários","인턴십","The Internship"]', 1784690324459);
