INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-trai-dat-diet-vong', 'Bí Mật Trái Đất Diệt Vong', 'Oblivion', 'https://phimimg.com/upload/vod/20260108-1/dd67a6a1dc8cfca1292a3b0e6b427ea6.jpg', 'https://phimimg.com/upload/vod/20260108-1/e23277f47792cf1d36e825741507645a.jpg', '<p>Phim Oblivion 2013 lấy bối cảnh vào năm 2077, sau khi thế giới bị người ngoài hành tinh xâm lược thì tất cả loài người được đưa đến đám mây sống, chỉ còn chàng chiến binh Jack Harper là được giữ lại. Anh và người yêu mình được lệnh hợp tác với nhau để chiến đấu chống lại bọn quái vật hung tợn, sau này Jack tình cờ cứu mạng một cô gái xinh đẹp tên Julia trong chiếc phi thuyền bị hỏng, cô ta đã cho anh nhớ lại những ký ức bí ẩn của anh và cùng anh đi khám phá nó...</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Cruise","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Zoë Bell","avatar":""},{"name":"Abigail Lowe","avatar":""},{"name":"Isabelle Lowe","avatar":""},{"name":"Booch O''Connell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["遗忘星球","攻‧元2077","遗忘","Horizons","L''oubli","オブリビオン","オブリビオン：2013","Nơi Bị Quên Lãng","遗落战境","Oblivion: el tiempo del olvido","攻·元2077","ობლივიონი","Oblivion