INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-bang-gia', 'Nữ Hoàng Băng Giá', 'Frozen', 'https://phimimg.com/upload/vod/20260107-1/c23c5e7fd66cea62f04e50620750a654.jpg', 'https://phimimg.com/upload/vod/20260107-1/30161af90dc9057474b4c1f3974393ee.jpg', '<p>Có thể nhiều người sẽ ao ước sở hữu phép thuật, song đó chắc chắn không phải nàng công chúa Elsa. Ngay từ nhỏ, cô đã có khả năng kỳ diệu là tạo ra băng tuyết cũng như điều khiển những con gió. Nhưng chính khả năng ấy đã vô tình gây thương tích cho em gái Anna. Anna được các quỷ lùn chữa trị và cái giá phải trả là cô bé hoàn toàn quên mất việc chị mình có năng lực đặc biệt. Không những thế, đức vua và hoàng hậu còn phải cách ly Elsa trong căn phòng kín để phép thuật của cô không phát tác, khiến tuổi thơ hai chị em Elsa và Anna bị tách rời.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Idina Menzel","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Livvy Stubenrauch","avatar":""},{"name":"Santino Fontana","avatar":""},{"name":"Eva Bella","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Maia Wilson","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Annie Lopez","avatar":""},{"name":"Annaleigh Ashford","avatar":""},{"name":"Paul Briggs","avatar":""},{"name":"Stephen J. Anderson","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Jennifer Lee","avatar":""},{"name":"Chris Williams","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f008