INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-chim-vao-bong-toi', 'Star Trek: Chìm Vào Bóng Tối', 'Star Trek Into Darkness', 'https://phimimg.com/upload/vod/20251226-1/77819e97ebb92555ee356b80edc540ef.jpg', 'https://phimimg.com/upload/vod/20251226-1/0a01de860cc6f1e9a813340bd49b9522.jpg', '<p>Bộ phim là phần tiếp theo của phim Star Trek. Trong phần này, sau khi được gọi về trái đất, những phi hành gia phát hiện ra tổ chức của mình đã bị phá hoại bởi một thế lực không đơn giản nào đó. Và người cựu thuyền trưởng của con tàu vũ trụ Enterprise bị sát hại bởi một kẻ lạ mặt. Đau đớn trước cái chết của ông, Kirk cùng con tàu vũ trụ Enterprise và các phi hành đoàn lại bắt đầu một cuộc hành trình mới, truy tìm kẻ đã giết vị cựu thuyền trưởng vĩ đại của họ. Nhưng lúc này họ lại khám phá ra một bí mật khủng khiếp và họ nhận ra những gì họ nhìn thấy chưa phải là sự thật họ từng biêt. Bí mật khủng khiếp đó là gì? Liệu họ có sống sót trở về?</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Chris Pine","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Peter Weller","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"John Cho","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"Noel Clarke","avatar":""},{"name":"Nazneen Contractor","avatar":""},{"name":"Amanda Foreman","avatar":""},{"name":"Jay Scully","avatar":""},{"name":"Jonathan Dixon","avatar":""},{"name":"Aisha Hin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Star Trek XII：Into Darkness","스타 트렉 다크니스","Star Trek: En la oscuridad","Viaje a las estrellas 12 En la oscuridad","Star Trek XII: En la oscuridad","Star Trek - Into Darkness","星际迷航12：暗黑无界","星际迷航2：暗黑无界","Star Trek XII - Into Darkness","Star Trek: Além da Escuridão","Sötétségben - Star Trek","Star Trek 12: Into Darkness","Звёздный путь: Возмездие","Du Hành Giữa Các Vì Sao 2: Chìm Vào Bóng Tối","Зоряний шлях: Відплата","Star Trek II","Star Trek：Into Darkness","מסע בין כוכבים: האויב בתוכנו","Star Trek 12","Star Trek 12 - Into Darkness","Star Trek 3.2","Star Trek 3.2 - Into Darkness","Star Trek Into Darkness"]', 1784690324459);
