INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('star-trek-chim-vao-bong-toi', 'Star Trek: Chìm Vào Bóng Tối', 'Star Trek Into Darkness', 'star trek: chìm vào bóng tối star trek into darkness chris pine zachary quinto zoe saldaña benedict cumberbatch karl urban simon pegg bruce greenwood peter weller alice eve anton yelchin john cho leonard nimoy noel clarke nazneen contractor amanda foreman jay scully jonathan dixon aisha hin star trek xii：into darkness 스타 트렉 다크니스 star trek: en la oscuridad viaje a las estrellas 12 en la oscuridad star trek xii: en la oscuridad star trek - into darkness 星际迷航12：暗黑无界 星际迷航2：暗黑无界 star trek xii - into darkness star trek: além da escuridão sötétségben - star trek star trek 12: into darkness звёздный путь: возмездие du hành giữa các vì sao 2: chìm vào bóng tối зоряний шлях: відплата star trek ii star trek：into darkness מסע בין כוכבים: האויב בתוכנו star trek 12 star trek 12 - into darkness star trek 3.2 star trek 3.2 - into darkness star trek into darkness', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-thoa-ky-duyen', 'Tử Thoa Kỳ Duyên', 'Legend Of The Purple Hairpin', 'https://phimimg.com/upload/vod/20251224-1/15dceb1b071bea55e2f408ce3d7fbb33.jpg', 'https://phimimg.com/upload/vod/20251224-1/2486c1a00ec3009f3cb76e47fb2dc198.jpg', '<p>Bộ phim khắc họa câu chuyện tình, chuyện đời bi thương của ca kỹ xinh đẹp, tài hoa nhất đời Đường, Hoắc Tiểu Ngọc. Dù được nhiều kẻ quyền cao chức trọng để mắt, nhưng Tiểu Ngọc vẫn chỉ một mực chờ đợi “nhân duyên” với tài tử Lý Quân Ngu - vốn nổi danh tứ phương bởi tài hoa xuất chúng. Trời không phụ lòng người, vì vô tình đánh rơi chiếc tử thoa quý giá, Tiểu Ngọc có dịp gặp người trong mộng Quân Ngu và ngay phút đầu tiên, quân tử - mỹ nhân đã trúng tiếng sét ái tình. Đôi trai tài gái sắc trao nhau lời ước hẹn trọn đời và dùng chiếc tử thoa làm vật đính ước.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 11, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Hiên","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Trần Di Dung","avatar":""},{"name":"Trình Thành","avatar":""},{"name":"Uyển Cầm Đan","avatar":""},{"name":"Viện Khương Đan","avatar":""},{"name":"Kim Yến Linh","avatar":""},{"name":"Trương Thiên Kỳ","avatar":""},{"name":"Lý Diệu Kính","avatar":""},{"name":"Trịnh Dịch Đồng","avatar":""},{"name":"Bao Văn Tịnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Love In The Purple","The Purple Hairpin","紫釵奇緣"]', 1784690324459);
