INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-benh-the-ky-cau-lac-bo-mua-thuoc-dallas', 'Căn Bệnh Thế Kỷ (Câu Lạc Bộ Mua Thuốc Dallas)', 'Dallas Buyers Club', 'https://phimimg.com/upload/vod/20251214-1/c7f68f83256437eb618c99e61c62ce96.jpg', 'https://phimimg.com/upload/vod/20251214-1/20258c616aed07228e751ae6a8f5a1ab.jpg', '<p>Vì lối sống buông thả, hoang dại, Ron Woodroof đã phải đối mặt với căn bệnh thế kỷ. Nhưng anh không muốn chấp nhận cái chết, nên bất chấp tất cả để điều trị và giúp đỡ những ai mắc bệnh giống mình.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Michael O''Neill","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Griffin Dunne","avatar":""},{"name":"Kevin Rankin","avatar":""},{"name":"Donna DuPlantier","avatar":""},{"name":"Deneen Tyler","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Ian Casselberry","avatar":""},{"name":"Noelle Wilcox","avatar":""},{"name":"Bradford Cox","avatar":""},{"name":"Rick Espaillat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo''adon ha''lakokhot shel Dallas","Poslovni klub Dalas","Sınırsızlar Kulübü","Գնորդների դալասյան ակումբը","Dallas Buyers Club"]', 1784690324459);
