INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-trinh-pha', 'Đại Trinh Phá', 'Shanghai Forest', 'https://phimimg.com/upload/vod/20251210-1/f9e6ad3c855c65852769a8a3e1a114c1.jpg', 'https://phimimg.com/upload/vod/20251210-1/69c304967a142d6931721ed6fa72575f.jpg', '<p>Năm 1930 tại bến Thượng Hải, bốn người thanh niên trẻ là đạo tặc hiệp nghĩa Tiêu Ân, nữ ca sĩ Tuyết Diễm, nữ nhà báo Viên Băng Băng, cảnh sát trưởng Cốc Hùng Phi vì một vụ hung án mà xảy ra những xung đột, mâu thuẫn. Ngay sau đó họ đã phát hiện ra một bí mật kinh thiên động địa, có một thế lực ngầm đen tối, đang phối hợp với tổ chức tình báo nước ngoài, với mưu đồ cướp quốc bảo cố cung.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghê Đại Hồng","avatar":""},{"name":"Ngưu Thanh Phong","avatar":""},{"name":"Vương Học Binh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Shang Hai Sen Lin","Shanghai Forest","上海森林"]', 1784690324459);
