INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-the-ky', 'Phi Vụ Thế Kỷ', 'Now You See Me', 'https://phimimg.com/upload/vod/20251130-1/74147344a9e18207c23027c50e0cea6c.jpg', 'https://phimimg.com/upload/vod/20251130-1/ac099f5652e6e0da64316fdfb85e7dd6.jpg', '<p>Phim nói về một nhóm các nhà ảo thuật đường phố tài ba được tập hợp lại bởi một người bí ẩn nhằm thực hiện một phi vụ không tưởng trước hàng ngàn người là di chuyển từ New York đến 1 ngân hàng ở Paris trong vài giây và trộm sạch tiền. Vụ việc nghiêm trọng này làm cho FBI phải vào cuộc điều tra và cũng từ đó mở ra những điều bí ẩn về người lạ mặt đã dẫn dắt họ. Now You See Me với những diễn biến nhanh, những màn ảo thuật đẹp, thật giả lẫn lộn làm cho bộ phim hấp dẫn hơn và người xem phải tập trung vào phim Phi Vụ Thế Kỷ trong suốt bộ phim sẽ không làm bạn thất vọng. Ngay từ khi có trailer đầu tiên về phim, Phi Vụ Thế Kỷ đã đem lại cảm giác chắc chắn đây sẽ là 1 trong những bộ phim hay năm 2013.</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Common","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"José Garcia","avatar":""},{"name":"Jessica Lindsey","avatar":""},{"name":"Caitríona Balfe","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"Stanley Wong","avatar":""},{"name":"Laura Cayouet","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Nada es lo que parece","Die Unfassbaren - Now You See Me","나우 유씨미 : 마술사기단","グランド・イリュージョン","惊天魔盗团","Phi Vụ Thế Kỷ","非常盜","Now You See Me","Ahora me ves: 1","Now You See Me 1","Insaisissables","Иллюзия обмана 1"]', 1784690324459);
