INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van', 'Diệp Vấn', 'Ip Man', 'https://phimimg.com/upload/vod/20251201-1/19273fddb7402dcfea093f0e0ef8ba81.jpg', 'https://phimimg.com/upload/vod/20251201-1/7559ddf77de1f487623f4aed300373c6.jpg', '<p>Phim kể về cuộc đời của Diệp Vấn từ nhỏ đến lớn, sinh ra giữa thời chiến, trải qua bao nhiêu lần tắm máu, vào sinh ra tử để thành danh với &quot;Vịnh Xuân Quyền&quot;.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Hàn Tuyết","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Lương Tiểu Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["叶问"]', 1784690324459);
