INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-cua-no-le-phan-4', 'Cuộc Chiến Của Nô Lệ (Phần 4)', 'Spartacus (Season 4)', 'cuộc chiến của nô lệ (phần 4) spartacus (season 4) liam mcintyre manu bennett dustin clare cynthia addai-robinson jaime murray ellen hollman luna rioumina marisa ramirez ditch davey barry duffield pana hema-taylor stephen lovatt blessing mokgohloa jenna lind hanna mangan lawrence gwendoline спартак: кръв и пясък спартак: отмъщение spartacus: viva a origem spartacus origens: deuses da arena 斯巴达克斯：血与沙 斯巴达克斯：复仇 spartacus: gods of the arena spartacus: sangre y arena spartacus: dioses de la arena spartacus: venganza spartacus: la guerra de los condenados spartacus: les dieux de l''arène spartacus - az aréna istenei spartacus: sangue e areia spartacus: blood and sand spartacus: vengeance spartacus: war of the damned spartacus', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-boi-uyen-uong', 'Ngọc Bội Uyên Ương', 'Bygone Love', 'https://phimimg.com/upload/vod/20251118-1/40b01fe152020aa4356630d4ba1d46ec.jpg', 'https://phimimg.com/upload/vod/20251118-1/899cf4de1b62ce16e8ab54b5102d9a45.jpg', '<p>Bộ phim là câu chuyện tình éo le, ngang trái và đầy đau khổ đan xen với những mưu đồ đen tối, ẩn sau vẻ hào nhoáng là sự đố kỵ và ganh đua. “Ngọc bội uyên ương” đưa người xem quay lại Trung Quốc giai đoạn những năm loạn lạc, rối ren, trong đó nổi bật lên thế lực quân sự của gia đình Thẩm Kỳ Tuấn và thế lực kinh tế của gia đình Đường Đình Hiên. Cả hai lại cùng dành tình cảm đặc biệt cho Kim Vĩnh Ân, tất cả tạo nên một bức tranh đầy màu sắc và kịch tính từ đầu đến cuối phim. Tình yêu đặt trong bối cảnh xã hội phức tạp đã khiến những người trẻ tuổi gặp không ít khó khăn và đau khổ khi phải vượt qua những định kiến xã hội và rào cản từ gia đình. Sự tranh giành quyền lợi đã biến tình yêu và hôn nhân thành cuộc trao đổi để đảm bảo địa vị và lợi ích cá nhân. Tiểu thư Kim Vĩnh Ân, hiền dịu đã bị cuốn vào vòng xoáy tranh quyền đoạt lợi đó, cuộc tình tay ba với Kỳ Tuấn và Đình Hiên đã khiến cô vô cùng đau khổ và giằng xé.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Thiếu Kỳ","avatar":""},{"name":"Mã Tuấn Vĩ","avatar":""},{"name":"Trương Mông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鸳鸯佩"]', 1784690324459);
