INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-tinh-duc-phan-1', 'Bậc Thầy Tình Dục (Phần 1)', 'Masters Of Sex (Season 1)', 'https://phimimg.com/upload/vod/20251116-1/094207c18f21b38ff5c60ad7bcef5201.jpg', 'https://phimimg.com/upload/vod/20251116-1/de6e5e1d63d2c8d146c5c8c163b97bab.jpg', '<p>Phim tái hiện cuộc đời và sự nghiệp chông gai và đầy tranh cãi của William Masters và Virginia Johnson, hai nhà nghiên cứu tiên phong trong lĩnh vực tình dục. Năm 1956, William Masters, một nhà nghiên cứu tại Đại học Washington, đề xuất một nghiên cứu gây tranh cãi về tình dục con người nhưng bị từ chối. Mặc dù thế, ông vẫn quyết định tiếp tục tiến hành nghiên cứu và thuê Virginia Johnson làm trợ lý. Tuy chỉ là một người mẹ đơn thân không bằng cấp, Virginia lại là một trợ thủ vô cùng đắc lực cho William và cùng ông góp công &quot;khai sáng&quot; một lĩnh vực mà tưởng chừng như sẽ mãi mãi là một bí ẩn với con người.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Sheen","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Caitlin FitzGerald","avatar":""},{"name":"Annaleigh Ashford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Експерти по секс","마스터스 오브 섹스","Masters of Sex"]', 1784690324459);
