INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-nguyen-thuy-phan-1', 'Ma Cà Rồng Nguyên Thủy (Phần 1)', 'The Originals (Season 1)', 'https://phimimg.com/upload/vod/20251102-1/1297b833c990b03fec3ea52d3400d890.jpg', 'https://phimimg.com/upload/vod/20251102-1/b1fd59fb4c6384ff924d2012ff250e75.jpg', '<p>Klaus Mikaelson nhận được tin có thế lực siêu nhiên đang vùng dậy chống lại hắn ở New Orleans. Những nghi vấn của Klaus đưa hắn về gặp lại tên đệ tử xảo quyệt của hắn, Marcel, một trùm ma cà rồng điều khiển tất cả ma cà rồng lẫn người dân nơi đây. Vì muốn giúp em trai mình hối cải, Elijah theo Klaus quay về New Orleans và nhanh chóng phát hiện ra cô người sói Hayley cũng đến đây để tìm manh mối về dòng tộc mình, và bị rơi vào tay của một phù thủy quyền năng tên Sophie. Căng thẳng xảy ra trên thị trấn này khi những luật lệ mà Marcel đưa ra buộc dân chúng phải tuân theo đang có nguy cơ bị phá vỡ. Vì Klaus, tìm cho ra câu trả lời vì sao đệ tử hắn lại có được mọi thứ đáng lý ra phải là của hắn. Trong khi chờ đợi liệu em gái họ, Rebekah, có rời Mystic Falls để gặp lại gia đình không, Klaus và Elijah ép buộc phù thủy nơi đây lập liên minh để đảm bảo New Orleans một lần nữa sẽ dưới quyền cai trị của Những Ma Cà Rồng Nguyên Thủy.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joseph Morgan","avatar":""},{"name":"Daniel Gillies","avatar":""},{"name":"Charles Michael Davis","avatar":""},{"name":"Riley Voelkel","avatar":""},{"name":"Yusuf Gatewood","avatar":""},{"name":"Danielle Rose Russell","avatar":""},{"name":"Steven Krueger","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Първородните","Os Originais","初代吸血鬼","始祖家族","ორიგინალები","პირველები","Первородные","Прадавні","The Originals"]', 1784690324459);
