INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ti-hon-movie-nhiem-vu-cuoi-cung', 'Thợ Săn Tí Hon Movie: Nhiệm Vụ Cuối Cùng', 'Hunter x Hunter: The Last Mission', 'https://phimimg.com/upload/vod/20251030-1/f5a8815bfa7c1cb5e35ced0125a407f4.jpg', 'https://phimimg.com/upload/vod/20251030-1/b10d984bc4c669206745d1e72fe2b19b.jpg', '<p>Isaac Netero – chủ tịch của Hiệp hội Thợ săn – từng phong ấn một thợ săn tên là Jed, người đã làm chủ “On”, bóng tối của Nen. Nhiều năm sau, những kẻ sử dụng On xuất hiện trở lại trong giải đấu Battle Olympia tại Tháp Thiên Đường. Đây là nhiệm vụ cuối cùng của Netero: bảo vệ Hiệp hội và thế giới khỏi mối đe dọa mang đầy thù hận và khát vọng báo thù – và ông sẽ cần tất cả sự giúp đỡ có thể để hoàn thành nó.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Han","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Ichitaro Ai","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Ryuuzaburou Ootomo","avatar":""},{"name":"Hiroki Takahashi","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Kimiko Saito","avatar":""},{"name":"Chisa Yokoyama","avatar":""},{"name":"Shinya Hamazoe","avatar":""},{"name":"Kan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529