INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-cuoi-cung', 'Âm Mưu Cuối Cùng (Tham Chiến)', 'Welcome to the Punch', 'https://phimimg.com/upload/vod/20251023-1/3b0273af7622ee1a04826062042a149a.jpg', 'https://phimimg.com/upload/vod/20251023-1/4284dc20d24b3687df79d548ba987c0e.jpg', '<p>Tham Chiến - Welcome To The Punch là bộ phim hành động ly kỳ xoay quanh cuộc truy đuổi giữa một tội thạm và một tham tử điều tra. Jacob Sternwood là một gã từng phạm tội, bị buộc phải quay về London khi con trai anh ta bị dính líu vào một vụ trộm cắp. Điều này đã giúp cho thám tử Max Lewinsky có cơ hội bắt hắn sau nhiều năm truy đuổi bất thành. Khi họ phải đối mặt nhau, cũng là lúc họ bắt đầu phát hiện ra một âm mưu sâu xa hơn, họ hợp tác với nhau để vạch trần âm mưu của giới thượng cấp...</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"James McAvoy","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Ruth Sheen","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Elyes Gabel","avatar":""},{"name":"Jason Maza","avatar":""},{"name":"Johnny Harris","avatar":""},{"name":"Steve Oram","avatar":""},{"name":"Natasha Little","avatar":""},{"name":"Cathy Murphy","avatar":""},{"name":"Seun Shote","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["欢迎来到庞奇","Inimigos de Sangue","Le Traître","Enemigos de Sangre","Ласкаво просимо в капкан"