INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-muu-cuoi-cung', 'Âm Mưu Cuối Cùng (Tham Chiến)', 'Welcome to the Punch', 'âm mưu cuối cùng (tham chiến) welcome to the punch james mcavoy mark strong david morrissey peter mullan daniel mays andrea riseborough daniel kaluuya ruth sheen jason flemyng elyes gabel jason maza johnny harris steve oram natasha little cathy murphy seun shote 欢迎来到庞奇 inimigos de sangue le traître enemigos de sangre ласкаво просимо в капкан feinde - welcome to the punch 테이크다운 双雄 ビトレイヤー：2013 enemigos de sangre welcome to the punch', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-nu-bong-dem', 'Y Nữ Bóng Đêm', 'American Mary', 'https://phimimg.com/upload/vod/20251023-1/4e4e5546f3266ebb07f7d689a0fd35a4.jpg', 'https://phimimg.com/upload/vod/20251023-1/4491fc98935374fd9ed3bb5fb64ed660.jpg', '<p>Mary là một sinh viên y khoa tài năng nhưng gặp khó khăn tài chính. Trong lúc tuyệt vọng, cô nhận lời thực hiện một ca phẫu thuật bất hợp pháp tại một hộp đêm, mở đầu cho hành trình sa vào thế giới ngầm của phẫu thuật biến dạng cơ thể. Sau khi bị cưỡng hiếp bởi một giáo sư tại trường, Mary từ bỏ con đường học thuật và bắt đầu thực hiện các ca phẫu thuật cực đoan cho những khách hàng kỳ quái — từ biến mình thành búp bê sống đến thay đổi giới tính một cách cực đoan. Dần dần, Mary trở thành một biểu tượng trong cộng đồng “biến hình”, nhưng cũng đánh mất chính mình trong quá trình trả thù và kiểm soát.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Katharine Isabelle","avatar":""},{"name":"Julia Maxwell","avatar":""},{"name":"Antonio Cupo","avatar":""},{"name":"Tristan Risk","avatar":""},{"name":"Paula Lindberg","avatar":""},{"name":"Paul Anthony","avatar":""},{"name":"Clay St. Thomas","avatar":""},{"name":"John Emmet Tracy","avatar":""},{"name":"Twan Holliday","avatar":""},{"name":"Nelson Wong","avatar":""},{"name":"Travis Watters","avatar":""},{"name":"Marius Soska","avatar":""},{"name":"Sylvia Soska","avatar":""},{"name":"Jen Soska","avatar":""},{"name":"David Lovgren","avatar":""},{"name":"Sean Amsing","avatar":""},{"name":"Natasha Forry","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["美国玛丽","American Mary - Aussehen ist alles","Amerikanka Meri","血腥玛丽","美國瑪麗","American Mary"]', 1784690324459);
