INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-moi', 'Thế Giới Mới', 'New World', 'https://phimimg.com/upload/vod/20251023-1/90c683c91967dcbdc0f87877fba788c5.jpg', 'https://phimimg.com/upload/vod/20251023-1/6d829257ca1114182e4ceb278ac809d2.jpg', '<p>Phim kể về một cảnh vụ nằm vùng trong tổ chức xã hội đen lớn nhất Hàn Quốc. Sau cái chết của ông trùm, băng đảng rơi vào cuộc đấu tranh giành quyền lực. Người cảnh vụ đứng giữa hai lựa chọn, trở thành ông trùm trong tổ chức xã hội đen, hay tiếp tục nằm vùng, bị cấp trên quên lãng như con tốt thí trên bàn cờ...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Hwang Jung-min","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Kim Yoon-sung","avatar":""},{"name":"Na Kwang-hoon","avatar":""},{"name":"Park Seo-yeon","avatar":""},{"name":"Choi Il-hwa","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Jang Kwang","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Don Lee","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Woo Jung-kook","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shin-sae-gye","Sinsegye","New World (2013)","The New World","Sin-se-gye","New World","신세계"]', 1784690324459);
