INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-hoan-thien', 'Trái Tim Hoàn Thiện', 'A Change of Heart', 'https://phimimg.com/upload/vod/20251011-1/145e070aa5fe54fa4284a66f1ff3a2a7.jpg', 'https://phimimg.com/upload/vod/20251011-1/38da50d6b0c8e80676590eedf2ad0d53.jpg', '<p>Phương Tự Lực, một doanh nhân tài ba nổi tiếng với đầu óc nhạy bén và phong cách làm việc thẳng tay, nhưng không may anh bị bệnh tim và bệnh tình ngày càng nguy kịch mà cách duy nhất để giái cứu là thay tim. Nào ngờ bác sĩ phụ trách Diêu Nhật Sơn đột nhiên qua đời trong một tai nạn, và quả tim của anh lại thích hợp để thay cho Tự Lực. Sau cuộc phẫu thuật thay tim, tính tình Tự Lực thay đổi hoàn toàn, anh trở nên hiền hoà và sống rất tình cảm, đâu đó trong anh là hình bóng của Nhật Sơn là Nguyễn Tiểu Cát và vợ anh là Đường Thiện Hành.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2013, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Michael Miu Kiu-Wai","avatar":""},{"name":"Bosco Wong Chung-Chak","avatar":""},{"name":"Joey Man Yee-Man","avatar":""},{"name":"Niki Chow Lai-Kei","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Vincent Wong Ho-Shun","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"JJ Jia","avatar":""},{"name":"Elaine Yiu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chuan Ai Shi Wu Suo","好心作怪"]', 1784690324459);
