INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dot-lo-ke-sat-nhan', 'Kẻ Đốt Lò (Kẻ Sát Nhân)', 'Stoker', 'https://phimimg.com/upload/vod/20250926-1/aaf8389b5a8b5d9306d18898bcce9287.jpg', 'https://phimimg.com/upload/vod/20250926-1/868daf22a12a91f1cc16a02f9f70bf25.jpg', '<p>Truyện phim kể về cô gái trẻ lập dị India Stoker (Mia Wasikowska đóng). Sau cái chết của cha cô, thì người cậu bí ẩn Charlie (Matthew Goode) bổng trở về. Tuy nhiên, sau đó trong thị trấn liên tiếp xảy ra những vụ mất tích kỳ lạ và India sớm khám phá ra rằng người cậu của mình chính là nguyên nhân gây ra việc đó. Mẹ của cô Evelyn (Nicole Kidman) bị phát hiện có tình ý với Charlie, và mâu thuẫn bắt đầu nảy sinh khiến cho cả ba rơi vào vòng xoáy của những mưu toan và kế hoạch chết người.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mia Wasikowska","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Alden Ehrenreich","avatar":""},{"name":"Phyllis Somerville","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"Judith Godrèche","avatar":""},{"name":"David Alford","avatar":""},{"name":"Peg Allen","avatar":""},{"name":"Lauren E. Roman","avatar":""},{"name":"Harmony Korine","avatar":""},{"name":"Dominick ''Dino'' Howard","avatar":""},{"name":"Tyler","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["慾謀","私房吓","欲谋","Stoker","스토커","Tajemství rodiny Stokerů","イノセント・ガーデン"]', 1784690324459);
