INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-den-chan-menh-de-vuong', 'Kỵ Sĩ Đen: Chân Mệnh Đế Vương', 'Berserk: The Golden Age Arc III - The Advent', 'https://phimimg.com/upload/vod/20250923-1/ec813279f5e2c6d350d940fe6a90d550.jpg', 'https://phimimg.com/upload/vod/20250923-1/206488358a09fbb7e0eebad1b128cdb9.jpg', '<p>Một năm đã trôi qua kể từ khi Guts rời khỏi Đội quân Chim ưng và Griffith bị vương quốc Midland bắt giam vì tội phản quốc. Trong đêm tối, tại một khu cắm trại bí mật, Đội quân Chim ưng bị tấn công bởi nhóm sát thủ Bakiraka do Silat cầm đầu. Khi mọi hy vọng dường như đã tan biến, Guts quay trở lại sau chuyến đi của mình. &quot;Anh đã phá hủy tất cả.&quot; Khóc rằng Griffith sẽ không là gì nếu thiếu Guts, Casca và Guts hòa quyện làm một cả về thể xác lẫn tâm hồn. Griffith bị giam giữ trong tòa nhà cổ nhất tại Lâu đài Wyndham, Tháp Tái Sinh.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroaki Iwanaga","avatar":""},{"name":"Toa Yukinari","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Takahiro Fujiwara","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Yoshiaki Matsumoto","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ayako Takeuchi","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Shinji Ogawa","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Hiroki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"c