INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-si-den-chan-menh-de-vuong', 'Kỵ Sĩ Đen: Chân Mệnh Đế Vương', 'Berserk: The Golden Age Arc III - The Advent', 'kỵ sĩ đen: chân mệnh đế vương berserk: the golden age arc iii - the advent hiroaki iwanaga toa yukinari takahiro sakurai takahiro fujiwara minako kotobuki rikiya koyama yoshiaki matsumoto kenta miyake kazuki yao yuki kaji ayako takeuchi miyuki sawashiro shinji ogawa aki toyosaki ayana taketatsu akio otsuka hiroki berserk, l''âge d''or 3 berserk - das goldene zeitalter iii: niedergang beruseruku: ohgon jidaihen 3 - kôrin ベルセルク 黄金時代篇iii 降臨 berserk. la edad de oro iii: el advenimiento 극장판 베르세르크 : 황금 시대편 iii - 강림 beruseruku ogon jidai-hen iii korin berserk ōgon jidai-hen iii kōrin berserk the golden age arc iii: descent berserk: ougon jidai-hen iii - kourin berserk: the golden age arc 3 - the advent ベルセルク 黄金時代篇ⅲ 降臨', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-sam-ii-the-gioi-bong-toi', 'Thần Sấm II: Thế Giới Bóng Tối', 'Thor: The Dark World', 'https://phimimg.com/upload/vod/20250923-1/e4ba7b6bbd53ecef3e7740405648310b.jpg', 'https://phimimg.com/upload/vod/20250923-1/59eb1a450d1c31635548241d4ff3031b.jpg', '<p>Thor: Thần Sấm phải chiến đấu để cứu trái đất và tất cả Cửu Giới từ một kẻ thù trong bóng tối. Trong khi Thor chiến đấu để lập lại trật tự trên vũ trụ thì một chủng tộc cổ xưa Malekith vì lợi nhuận đã làm mọi cách để kéo vũ trụ trở lại vào bóng tối. Phải đối mặt với một kẻ thù mà ngay cả Odin và Asgard không thể chịu được, Thor phải bắt tay vào hành trình nguy hiểm nhất. Đặc biệt, Thor lại cơ hội tái hợp lại với Jane Foster nhưng anh buộc phải hy sinh mọi thứ để cứu tất cả chúng ta. Liệu Thor sẽ chọn Jane Foster hay chấp nhận đánh đổi vì sứ mạng của mình? Là rồi Thần Sấm có giải cứu được trái đất?</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Jaimie Alexander","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Rene Russo","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Kat Dennings","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Clive","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thor 2","Marvel''s Thor: The Dark World","Thor - The Dark World","Thor 2: Σκοτεινός Κόσμος","마블 토르: 다크 월드","Thor: Un mundo oscuro","Thor: Mroczny świat","Thor Mroczny Świat - Thor The Dark World","Thor - The Dark Kingdom","Marvel Studios'' Thor: The Dark World","Thor 2: Thế Giới Bóng Tối","Թոր՝ մութ աշխարհ","토르 2","토르 다크 월드","Thor II","ธอร์: เทพเจ้าสายฟ้าโลกาทมิฬ","Thor II: The Dark World","マイティ・ソー／ダーク・ワールド：2013","Thor 2: The Dark World","雷神2：黑暗世界","Thor: Karanlık Dünya","ثور العالم المظلم","Thor: The Dark World"]', 1784690324459);
