INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-sam-ii-the-gioi-bong-toi', 'Thần Sấm II: Thế Giới Bóng Tối', 'Thor: The Dark World', 'thần sấm ii: thế giới bóng tối thor: the dark world chris hemsworth natalie portman tom hiddleston christopher eccleston anthony hopkins jaimie alexander zachary levi ray stevenson tadanobu asano idris elba rene russo adewale akinnuoye-agbaje kat dennings stellan skarsgård alice krige clive thor 2 marvel''s thor: the dark world thor - the dark world thor 2: σκοτεινός κόσμος 마블 토르: 다크 월드 thor: un mundo oscuro thor: mroczny świat thor mroczny świat - thor the dark world thor - the dark kingdom marvel studios'' thor: the dark world thor 2: thế giới bóng tối թոր՝ մութ աշխարհ 토르 2 토르 다크 월드 thor ii ธอร์: เทพเจ้าสายฟ้าโลกาทมิฬ thor ii: the dark world マイティ・ソー／ダーク・ワールド：2013 thor 2: the dark world 雷神2：黑暗世界 thor: karanlık dünya ثور العالم المظلم thor: the dark world', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-ngoan', 'Gái Ngoan', 'Very Good Girls', 'https://phimimg.com/upload/vod/20250919-1/a80d69d9ec3f71c84334859eb569b94a.jpg', 'https://phimimg.com/upload/vod/20250919-1/de2c025185952fa3dc5b8c5983bd6b09.jpg', '<p>Hai cô gái New York hẹn nhau &quot;thành người lớn&quot; sau khi tốt nghiệp trung học. Nhưng khi cả hai cùng phải lòng một chàng nghệ sĩ đường phố, tình bạn của họ lần đầu đứng trước thử thách thực sự.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dakota Fanning","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Ellen Barkin","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Clare Foley","avatar":""},{"name":"Owen Campbell","avatar":""},{"name":"Roslyn Curry","avatar":""},{"name":"Lenny Platt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ילדות טובות מאד","Muy buenas chicas","Very Good Girls - Die Liebe eines Sommers","Very Good Girls"]', 1784690324459);
