INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-kinh-hoang-2013', 'Ám Ảnh Kinh Hoàng', 'The Conjuring', 'https://phimimg.com/upload/vod/20250907-1/c50b081bafdc12d0f50e65a5d5e65a73.jpg', 'https://phimimg.com/upload/vod/20250907-1/f1a9d7559997afbc90e8df098dd4f806.jpg', '<p>Ed và Lorraine Warren, là những nhà điều tra các hiện tượng siêu nhiên xảy ra trên nước Mỹ. Những báo cáo của họ còn truyền cảm hứng cho cuốn tiểu thuyết Amityville Horror. Trong phim hai vợ chồng Warren là những người điều tra các hiện tượng siêu nhiên, họ đến để hỗ trợ gia đình Perron đang trải qua các sự kiện ngày càng đáng lo ngại trong trang trại của họ ở Harrisville, Rhode Island vào năm 1971.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Patrick Wilson","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Mackenzie Foy","avatar":""},{"name":"Joey King","avatar":""},{"name":"Hayley McFarland","avatar":""},{"name":"Shanley Caswell","avatar":""},{"name":"Kyla Deaver","avatar":""},{"name":"Sterling Jerins","avatar":""},{"name":"John Brotherton","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Joseph Bishara","avatar":""},{"name":"Marion Guyot","avatar":""},{"name":"Morganna Bridgers","avatar":""},{"name":"Amy Tipton","avatar":""},{"name":"Zach Pappas","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Warren Files","Prizivanje Zla","คนเรียกผี","死霊館","La Conjuration","Ám Ảnh Kinh Hoàng","Անեծքը","Закляття","Korku Seansı","Заклятие","Хараал","Заклинанието","Το Κάλεσμα","V Zajetí Démonů","Kirottu","V Zajatí Démonov","Dosjet Uorren","Trăind Printre Demoni","Obecność","Démonok Között","Išvarymas","Ļaunuma Izsaukšana","Prizivanje","L''evocazione - The Conjuring","Conjuring – Die Heimsuchung","Nattens Dæmoner","לזמן את הרוע","الشعوذة","احضار","الشعوذه","컨저링","詭屋驚凶實錄","招魂","ദ കോൺജൂറിങ്ങ്","தி கான்ஜுரிங்","বাংলা","L''expedient Warren","古宅惊魂","El Conjuro","The Untitled Warren Files Project","Conjuring - Les Dossiers Warren","Conjuring Les Dossiers Warren","Conjuring, Les Dossiers Warren","The Conjuring"]', 1784690324459);
