INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-anh-kinh-hoang-2013', 'Ám Ảnh Kinh Hoàng', 'The Conjuring', 'ám ảnh kinh hoàng the conjuring patrick wilson vera farmiga lili taylor ron livingston mackenzie foy joey king hayley mcfarland shanley caswell kyla deaver sterling jerins john brotherton shannon kook joseph bishara marion guyot morganna bridgers amy tipton zach pappas the warren files prizivanje zla คนเรียกผี 死霊館 la conjuration ám ảnh kinh hoàng անեծքը закляття korku seansı заклятие хараал заклинанието το κάλεσμα v zajetí démonů kirottu v zajatí démonov dosjet uorren trăind printre demoni obecność démonok között išvarymas ļaunuma izsaukšana prizivanje l''evocazione - the conjuring conjuring – die heimsuchung nattens dæmoner לזמן את הרוע الشعوذة احضار الشعوذه 컨저링 詭屋驚凶實錄 招魂 ദ കോൺജൂറിങ്ങ് தி கான்ஜுரிங் বাংলা l''expedient warren 古宅惊魂 el conjuro the untitled warren files project conjuring - les dossiers warren conjuring les dossiers warren conjuring, les dossiers warren the conjuring', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-kinh-hoang-2013', 'Bí Mật Kinh Hoàng', 'Secret Love', 'https://phimimg.com/upload/vod/20250905-1/8ba0dc00d4adce7dcdf82495cb7b0b7e.jpg', 'https://phimimg.com/upload/vod/20250905-1/7d974267da19db8239d626f351816ef9.jpg', '<p>Phim là câu chuyện kể về bốn người với bốn thân phận khác nhau cùng những bí mật của riêng mình, đang khao khát tìm kiếm tình yêu và sự báo thù. Mọi người điều có những bí mất riêng và bí mất có thể giúp mọi người thành công và giúp họ yêu.

Những bí mật cũng có thể phá hủy mọi người, nó có thể làm cho chúng ta hạnh phúc, lo lắng, hoặc thậm chí chúng ta mù quáng. Bộ phim này nói về những bí mật… và những thử thách và đau khổ của những người sống với bí mật, những bí mật xoay quanh bốn nhân vật mong muốn tìm thấy tình yêu và trả thù.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-eum","avatar":""},{"name":"Ji Sung","avatar":""},{"name":"Bae Soo-bin","avatar":""},{"name":"Lee Da-hee","avatar":""},{"name":"Lee Duck-hwa","avatar":""},{"name":"Yang Jin-sung","avatar":""},{"name":"Kang Nam-gil","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Yang Hee-kyung","avatar":""},{"name":"Moon Ji-in","avatar":""},{"name":"Ahn Ji-hyun","avatar":""},{"name":"Jo Mi-ryung","avatar":""},{"name":"Song Min-gyeong","avatar":""},{"name":"Choi Woong","avatar":""},{"name":"Jeong Soo-young","avatar":""},{"name":"Hwang Seok-jeong","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Kim Hyun-kyoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["秘密","Bimil","Тайна","Secret Love","Secret","비밀"]', 1784690324459);
