INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-thit-vien-2', 'Cơn Mưa Thịt Viên 2', 'Cloudy with a Chance of Meatballs 2', 'https://phimimg.com/upload/vod/20250905-1/dad9c3650b64e9b7235af0408de16b9d.jpg', 'https://phimimg.com/upload/vod/20250905-1/50ce337f870b1d5c19fb5a368486c152.jpg', '<p>Trong phim Cơn Mưa Thịt Viên 2, sau tai nạn hi hữu trong phần phim trước khiến hòn đảo Swallow Falls tràn ngập những món thức ăn khổng lồ, dân xứ đảo phải ra đi. Khi trở lại, họ không tin vào mắt mình khi thấy hòn đảo tràn ngập những sinh vật bằng thức ăn. Vẻ ngoài hết sức dễ thương của chúng khiến ai cũng có cảm tình. Nhưng khi đụng độ với con khủng long bánh xếp, dân đảo và nhà phát minh Flint Lockwood mới nhận ra họ đang đối diện với thảm họa mới.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Hader","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"James Caan","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Melissa Sturm","avatar":""},{"name":"Kris Pearn","avatar":""},{"name":"Craig Kellman","avatar":""},{"name":"Khamani Griffin","avatar":""},{"name":"Bridget Hoffman","avatar":""},{"name":"Al Roker","avatar":""},{"name":"Steve Alterman","avatar":""},{"name":"June Christ","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35