INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-cay-2013', 'Ma Cây', 'Evil Dead', 'https://phimimg.com/upload/vod/20250830-1/73b3de00180e6e1d5977ad574a9e8c6f.jpg', 'https://phimimg.com/upload/vod/20250830-1/bb857d0ecbe46436913a88faf663900a.jpg', '<p>Phim Ma Cây 2013 là phiên bản hiện đại của bộ phim kinh dị đẫm máu Ma Cây, làm lại từ tác phẩm cùng tên năm 1981. Phim là cuộc chiến đấu của một nhóm bạn trẻ với ma quỷ tại một ngôi nhà trong rừng sâu, khi họ đang cắm trại và phát hiện ra một cuốn sách bí ẩn dẫn họ vô tình triệu tập lên quỷ sống trong rừng gần đó. Và cũng từ đây một cuộc chiến đấu cho sự sống còn bắt đầu. Xem phim Ma Cây và với các khán giả có thần kinh thép, chắc chắn các bạn sẽ thích phim này.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jane Levy","avatar":""},{"name":"Shiloh Fernandez","avatar":""},{"name":"Lou Taylor Pucci","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"Elizabeth Blackmore","avatar":""},{"name":"Phoenix Connolly","avatar":""},{"name":"Jim McLarty","avatar":""},{"name":"Sian Davis","avatar":""},{"name":"Stephen Butterworth","avatar":""},{"name":"Karl Willetts","avatar":""},{"name":"Randal Wilson","avatar":""},{"name":"Rupert Degas","avatar":""},{"name":"Bob Dorian","avatar":""},{"name":"Ellen Sandweiss","avatar":""},{"name":"Jack Walley","avatar":""},{"name":"Bruce Campbell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["尸变","Piktieji numireliai","Cartea mortilor","Zlobni mrtveci","鬼玩人4","A Noite dos Mortos-Vivos","L’opéra de la Terreur (Evil Dead)","A Morte do Demônio","Posesión Infernal","이블데드2013","이블 데드 2013","Evil Dead"]', 1784690324459);
