INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-tinh-nghich-tinh-yeu-o-tokyo', 'Nụ hôn tinh nghịch: Tình yêu ở Tokyo', 'Mischievous Kiss: Love in Tokyo', 'https://phimimg.com/upload/vod/20250824-1/f1fef40c14beef343fac0ced3e2c56c1.jpg', 'https://phimimg.com/upload/vod/20250824-1/342e0470949e68229f65dbe98ecc04a9.jpg', '<p>Tại lễ khai giảng trung học, nữ sinh Kotoko Aihara (do Honoka Miki thủ vai), là một cô nàng khá ngốc, đã ngay lập tức trúng tiếng sét ái tình khi vừa trông thấy Naoki Irie ( Yuki Furukawa thủ vai). Ban đầu, Kotoko không có cơ hội để tỏ tình và âm thầm ôm mối tình đơn phương rất lâu cho tới khi cô ấy có cơ hội trao tận tay cậu lá thư tình. Thật không may, Naoki chẳng thèm quan tâm tới Kotoko, hơn nữa còn buông ra những lời cay nghiệt như Tôi không thích loại con gái ngu ngốc!, biến Kotoko thành trò cười của cả trường trung học. Rồi một ngày nhà của Aihara Kotoko bị hư hại bởi một trận động đất. Kotoko Aihara và cha cô quyết định tới sống nhờ nhà bạn của cha cho tới khi nhà được sửa chữa lại. Giống như là định mệnh an bài, ngôi nhà mà Kotoko chuyển tới ở nhờ chính là gia đình của Naoki. Kotoko làm thế nào để có thể cưa đổ anh chàng máu lạnh, miệng đầy nanh nhọn, lời toàn nọc độc như Naoki đây? Hãy cùng chờ đợi những chiêu trò khùng điên của cô nàng ngây thơ, trong sáng và đầy ý chí này nhé!</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Honoka Yahagi","avatar":""},{"name":"Yuki Furukawa","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Nanami Fujimoto","avatar":""},{"name":"Sogen Tanaka","avatar":""},{"name":"Yuga Aizawa","avatar":""},{"name":"Yoji Tanaka","avatar":""},{"name":"Kazumasa Koura","avatar":""},{"name":"Tomomi Nishimura","avatar":""},{"name":"Kasumi Yamaya","avatar":""},{"name":"Kanna Mori","avatar":""},{"name":"Masaki Kaji","avatar":""},{"name":"Yoshiaki Miyagi","avatar":""},{"name":"Noémie Nakai","avatar":""},{"name":"Toshi Takeuchi","avatar":""},{"name":"Arata Horii","avatar":""},{"name":"Mirai Suzuki","avatar":""},{"name":"Risako","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Beijo Malicioso","一吻定情","Itazura na Kiss ~ Love in TOKYO","Itazura na Kiss","Itazura na Kiss ~ Love in TOKYO 2","イタズラなKiss〜Love in TOKYO 2","イタキス","イタKiss","イタズラなKiss Love in TOKYO","イタズラなKiss〜Love in TOKYO","장난스런 키스 Love in TOKYO","It Started with a Kiss","Mischievous Kiss in Tokyo","Love in Tokyo","イタズラなKiss～Love in TOKYO"]', 1784690324459);
