INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-6-nguoi-soi-wolverine', 'X-Men 6: Người Sói Wolverine', 'The Wolverine', 'https://phimimg.com/upload/vod/20250817-1/abae7b6648b9bd2ab78d3906c72e2f91.jpg', 'https://phimimg.com/upload/vod/20250817-1/6d644b549e62946d771b12bd8bb6bed4.jpg', '<p>Marvel một lần nữa đưa đến cho khán giả câu chuyện mới đầy hấp dẫn về chàng Người Sói Logan - siêu anh hùng vốn được đông đảo khán giả yêu mến. Được đặt sau mốc sự kiện của X-Men: The Last Stand, bộ phim dõi theo hành trình của Logan lưu lạc tới đất nước Nhật Bản xa xôi, nơi anh bị lạc lõng hoàn toàn. &nbsp;Gặp lại một cố nhân tại xứ mặt trời mọc, Logan nhận được một đề nghị có thể khiến anh thay đổi hoàn toàn cuộc sống cô độc: loại bỏ tất cả các năng lực để anh trở thành người thường. Giữa muôn trùng nguy hiểm đến từ những kẻ thù xung quanh, liệu anh chàng Người Sói có từ bỏ sự bất tử của mình?</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Tao Okamoto","avatar":""},{"name":"Rila Fukushima","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Svetlana Khodchenkova","avatar":""},{"name":"Hal Yamanouchi","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Ken Yamamura","avatar":""},{"name":"Nobutaka Aoyagi","avatar":""},{"name":"Seiji Funamoto","avatar":""},{"name":"Shinji Ikefuji","avatar":""},{"name":"Qyoko Kudo","avatar":""},{"name":"Nobuaki Kakuda","avatar":""},{"name":"Chiharu Mizuno","avatar":""},{"name":"Takao Kin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wolverine 2","Žderavac","Wolverine: Samurai","Rosomaha bessmertnij","The Wolverine 3D","金钢狼2","Wolverine - Imortal","엑스맨, 더 울버린","The Wolverine: Unleashed Extended Edition","הוולברין","The Wolverine"]', 1784690324459);
