INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xmen-6-nguoi-soi-wolverine', 'X-Men 6: Người Sói Wolverine', 'The Wolverine', 'x-men 6: người sói wolverine the wolverine hugh jackman hiroyuki sanada tao okamoto rila fukushima famke janssen will yun lee svetlana khodchenkova hal yamanouchi brian tee ken yamamura nobutaka aoyagi seiji funamoto shinji ikefuji qyoko kudo nobuaki kakuda chiharu mizuno takao kin wolverine 2 žderavac wolverine: samurai rosomaha bessmertnij the wolverine 3d 金钢狼2 wolverine - imortal 엑스맨, 더 울버린 the wolverine: unleashed extended edition הוולברין the wolverine', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-ngang-trai', 'Tình Yêu Ngang Trái', 'NiseKoi', 'https://phimimg.com/upload/vod/20231219-1/7fb0cf2aaf00e10b61af35a78c5cb515.jpg', 'https://phimimg.com/upload/vod/20231219-1/4e3ffa9941efecde658cac91a87e5d46.jpg', '<p>Em sẽ giữ chìa, còn anh sẽ giữ ổ khóa. Sau này nếu mình được gặp lại nhau thì đây sẽ là thứ chúng ta dùng để nhận ra nhau, và khi đó, chúng ta sẽ... cưới nhau.Tuổi thơ con người thật hồn nhiên và trong sáng, nhìn cảnh hai đứa trẻ mới tí tuổi đầu đã nói mấy lời đỡ không nổi như thế thật đáng yêu biết bao...Con người là thế... Ai cũng mong rằng mọi thứ sẽ có được một kết quả như những câu chuyện cổ tích...Ấy thế màCó những lúc sự thật lại không như con người mong muốn &lt;&lt;Rồi cái ngày định mệnh, ngày hai đứa gặp lại, mọi chuyện sẽ ra sao? Hồi sau sẽ rõ</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324459);
