INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-quyet-2', 'Quỷ Quyệt 2', 'Insidious: Chapter 2', 'https://phimimg.com/upload/vod/20250731-1/47b9637fd9b7bdbb97f02de28ab36a16.jpg', 'https://phimimg.com/upload/vod/20250731-1/e8d11a952d8ae6dadf10a4273e3d3cd6.jpg', '<p>Năm 1986, Lorraine Lambert mời nhà tâm linh Elise đến nhà mình để giúp tìm con ma đang đeo bám cậu con trai Josh của bà. Elise nhận định Josh có khả năng đặc biệt mà người thường không có, đó là kết nối linh hồn mình với thế giới của người chết. Hai người quyết định xóa ký ức của Josh để anh thôi không &quot;du hành&quot; vào thế giới đen tối này nữa. &nbsp;Hai mươi lăm năm trôi qua, Josh khi này đã có vợ là Renai cùng hai con. Đây là lúc truyện phim tiếp nối phần 1. Những tưởng đã thoát khỏi ma quỷ từ lần trước nhưng những hiện tượng lạ vẫn diễn ra trong nhà Lambert.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Patrick Wilson","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Barbara Hershey","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Andrew Astor","avatar":""},{"name":"Hank Harris","avatar":""},{"name":"Jocelin Donahue","avatar":""},{"name":"Lindsay Seim","avatar":""},{"name":"Danielle Bisutti","avatar":""},{"name":"Tyler Griffin","avatar":""},{"name":"Garrett Ryan","avatar":""},{"name":"Tom Fitzpatrick","avatar":""},{"name":"Priscilla Garita","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["儿凶2","阴儿房第2章","阴儿房第2章：阴魂守舍","Sobrenatural: Capítulo 2","วิญญาณยังตามติด","Naznaczony 2","Insidious: Chapter 2","Insidieux : Chapitre 2","La Noche del Demonio Capitulo 2","Insidious 2 - Oltre i confini del male","Insidious 2","インシディアス 第2章","Sobrenatural - Capítulo 2","La noche del demonio: Capítulo 2","Insidious - Chapter 2","Insidious : Chapitre 2","غدار: الفصل الثاني","인시디어스 2: 두번째 집","인시디어스 2: 두 번째 집","인시디어스: 두 번째 집","הרוע שבפנים: פרק 2","อินซิเดียส 2","Quỷ Quyệt 2","Sobrenatural Capítulo 2"]', 1784690324459);
