INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-bang-gia', 'Chuyến Tàu Băng Giá', 'Snowpiercer', 'https://phimimg.com/upload/vod/20250727-1/9727b3d02c257a872b18644f7b2f3e06.jpg', 'https://phimimg.com/upload/vod/20250727-1/af06f1f7de9abb15cea33bce1401e4dc.jpg', '<p>Lấy bối cảnh năm 2031, sau thất bại của nỗ lực khắc phục sự nóng lên của toàn cầu, Trái Đất trở về với Kỷ Băng Hà khi hoàn toàn bị bao phủ bởi băng tuyết và thế giới loài người đứng trước nguy cơ bị xóa sổ. Tất cả những người may mắn sống sót đều ở trên con tàu mang tên Snowpiercer. Con tàu đi tới khắp nơi trên Trái Đất và giống như một xã hội thu nhỏ, chứa đựng những mâu thuẫn và phân biệt giàu nghèo, giai cấp giữa những người đang phải cùng nhau đương đầu với cái chết. Quá mệt mỏi trước sự áp bức, bất công, dưới sự lãnh đạo của Curtis (Chris Evans thủ vai), những người nghèo sống ở những toa sau của con tàu đã nổi dậy tiến hành cuộc cách mạng lật đổ tầng lớp thượng lưu ở những toa trước. Tuy nhiên, cuộc nổi dậy của họ đối mặt với rất nhiều nhiều khó khăn, thử thách...</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Song Kang-ho","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Ko A-sung","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Luke Pasqualino","avatar":""},{"name":"Vlad Ivanov","avatar":""},{"name":"Adnan Hasković","avatar":""},{"name":"Emma Levie","avatar":""},{"name":"Steve Park","avatar":""},{"name":"Clark Middleton","avatar":""},{"name":"Marcanthonee Reis","avatar":""},{"name":"Paul Lazar","avatar":""},{"name":"Tómas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Seolgug Yeolcha","Крізь сніг","Hólyukasztó","Snowpiercer (Rompenieves)","Snowpiercer","قطار یخ شکن","قطار برف‌شکن","یخ‌شکن","Snowpiercer - Le Transperce-neige","スノーピアサー：2013","Seolgungnyeolcha","Сквозь снег","설국열차"]', 1784690324459);
