INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hy-vong-2013', 'Hy Vọng', 'Hope (Wish)', 'https://phimimg.com/upload/vod/20250721-1/e7fcd5b952a0902442986a7bae846c2e.jpg', 'https://phimimg.com/upload/vod/20250721-1/dca387cfd09ca348205c642b659366a6.jpg', '<p>Dựa trên câu chuyện có thật. Phim Hy Vọng - Hope, còn được gọi là Wish, là câu chuyện về bi kịch xảy đến với cô con gái bé nhỏ So-won trong một lần đi học từ trường về nhà. Cha cô bé – Dong-hoon – nhận được điện thoại từ bệnh viện thông báo So-won đang bị chấn thương cả về thể xác lẫn tinh thần. Liệu gia đình của họ có vượt qua được quá khứ và trở về là một mái ấm như ngày xưa... Là một bộ phim Hàn Quốc năm 2013 của đạo diễn Lee Joon-ik, với sự tham gia của Sol Kyung-gu, Uhm Ji-won và Lee Re. Phim đã giành giải Phim hay nhất tại Giải thưởng Phim Rồng Xanh lần thứ 34.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sul Kyung-gu","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Lee Re","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Cha Mi-kyeong","avatar":""},{"name":"Jeong Min-sung","avatar":""},{"name":"Ahn Se-ha","avatar":""},{"name":"Jo Bok-rae","avatar":""},{"name":"Jo Moon-ee","avatar":""},{"name":"Kim Ooh-jin","avatar":""},{"name":"Yang Jin-sung","avatar":""},{"name":"Kim Do-yeob","avatar":""},{"name":"Kim Jin-hyeok","avatar":""},{"name":"Jin Sun-mi","avatar":""},{"name":"Jang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["So-won","ソウォン/願い","Hope: Esperança","Nadzieja","Желание","希望:為愛重生","Hy Vọng","Hope So-won","希望：为爱重生","أمل","소원"]', 1784690324459);
