INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-than', 'Ẩn Thân', 'Secretly, Greatly', 'https://phimimg.com/upload/vod/20250626-1/1d54cd17ad857374f48472c0f85b200c.jpg', 'https://phimimg.com/upload/vod/20250626-1/b90545174b0781906e5daaeb3164dfda.jpg', '<p>Ẩn Thân - Secretly Greatly phim xoay quanh ba điệp viên Triều Tiên trở thành những người di cư bí mật đến hội phủ ở một ngôi làng nhỏ ở Hàn Quốc để thực hiện nhiệm vụ. Ba điệp viên có hai lần tên là Won Ryu-hwan, Ri Hae-rang và Lee Hae-jin. Họ giả dạng thành những người di dân bình thường và sống trong đó như một gia đình. Tuy nhiên, cuộc sống an lành của họ bị đảo lộn khi những khía cạnh đen tối của công việc điệp viên bắt đầu xuất hiện. Không chỉ đơn thuần là một bộ phim hành động, Secretly Greatly cũng mang đậm yếu tố tình cảm và hài hước. Ba điệp viên phải đối mặt với các thử thách và nguy hiểm không ngừng từ công việc của họ, trong khi cố gắng hòa nhập vào cuộc sống hàng ngày và tạo dựng một mối quan hệ thân thiết với những người dân trong ngôi làng.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Soo-hyun","avatar":""},{"name":"Park Ki-woong","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Son Hyun-joo","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Shin Jung-keun","avatar":""},{"name":"Hong Kyung-in","avatar":""},{"name":"Lee Chae-young","avatar":""},{"name":"Park Eun-bin","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Goo Seung-hyun","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Kim Pub-lae","avatar":""},{"name":"Park Hye suk","avatar":""},{"name":"Jo Yong jin","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Lee Yeon-k","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Secretly Greatly","偉大的隱藏者","은밀하게 위대하게","Тайная миссия","Eunmilhagae euidaehagae","Covertness"]', 1784690324460);
