INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-ma-ca-rong', 'Chuyện Tình Ma Cà Rồng', 'Only Lovers Left Alive', 'https://phimimg.com/upload/vod/20250624-1/d6461c0c7d3dbe224ab6c35cd0b6be8e.jpg', 'https://phimimg.com/upload/vod/20250624-1/49edb193ceacc295468da2f576da7347.jpg', '<p>Bất tử sẽ mang đến hạnh phúc hay bất hạnh cho ta? Hòa vào cuộc sống loài người, ma cà rồng Adam và Eve muốn an ổn cả đời. Nhưng với cuộc đời gần như bất tử, sóng gió là điều như đã được định sẵn.</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tilda Swinton","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Mia Wasikowska","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Slimane Dazi","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Carter Logan","avatar":""},{"name":"Aurélie Thépaut","avatar":""},{"name":"Ali Amine","avatar":""},{"name":"Dave W.","avatar":""},{"name":"Ego Sensation","avatar":""},{"name":"Nick Name","avatar":""},{"name":"Fouad El Achaari","avatar":""},{"name":"Hawchi Mustapha","avatar":""},{"name":"Abdelkader Dourkan","avatar":""},{"name":"Mohamed Chairi Felah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Isgyvena tik mylintys","Les derniers amants","Mono oi erastes menoun zontanoi","永生情人","Rak ha''ohavim sordim","Sólo los amantes sobreviven","Amantes Eternos","Само любовниците остават живи","唯爱永生","Samo ljubavnici preživljavaju","Prezijí jen milenci","Armastajate igav