INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-ma-ca-rong', 'Chuyện Tình Ma Cà Rồng', 'Only Lovers Left Alive', 'chuyện tình ma cà rồng only lovers left alive tilda swinton tom hiddleston anton yelchin mia wasikowska jeffrey wright slimane dazi john hurt carter logan aurélie thépaut ali amine dave w. ego sensation nick name fouad el achaari hawchi mustapha abdelkader dourkan mohamed chairi felah isgyvena tik mylintys les derniers amants mono oi erastes menoun zontanoi 永生情人 rak ha''ohavim sordim sólo los amantes sobreviven amantes eternos само любовниците остават живи 唯爱永生 samo ljubavnici preživljavaju prezijí jen milenci armastajate igavene elu halhatatlan szeretők solo gli amanti sopravvivono オンリー・ラヴァーズ・レフト・アライヴ izdzīvo tikai mīlētāji tylko kochankowie przeżyją só os amantes sobrevivem îndrăgostiţii mor ultimii выживут только любовники samo ljubavnici opstaju prežijú len milenci večna ljubimca 噬血戀人 sadece aşıklar hayatta kalır виживуть лише коханці only lovers left alive', '');
