INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cam-ket', 'Bản Cam Kết', 'Commitment', 'https://phimimg.com/upload/vod/20250618-1/d1e1dfbcb9fc714eecefbaba980827c8.jpg', 'https://phimimg.com/upload/vod/20250618-1/843347c07db9dc78481771701e389f3a.jpg', '<p>Mười chín tuổi, Myung-hoon không bao giờ tưởng tượng rằng mình trở thành một kẻ giết người. Ước mơ trở một nghệ sĩ dương cầm nhanh chóng tan biến khi cha mình - một điệp viên Bắc Triều Tiên - chết do không hoàn thành nhiệm vụ khiến anh và cô em gái Hye-in bị bắt đến một trại tù lao động khổ sai. Cấp trên của cha Myung-hoon, Đại tá Moon đề xuất với anh một đề nghị: Nếu anh qua Hàn Quốc hoàn thành những gì người cha đang làm dở dang như một điệp viên thì anh và em gái sẽ được tha. Myung-hoon trải qua hai năm tập luyện căng thẳng à những nguy hiểm luôn rình rập trong quá trình ở Hàn Quốc. Anh phải hoàn thành nhiệm vụ trước khi Cơ quan tình báo Hàn Quốc phát hiện ra và trừ khử anh.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Seung-hyun","avatar":""},{"name":"Han Ye-ri","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Kim Sun-kyung","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Kang Hanna","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Lee Shin-seong","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Park Gil-su","avatar":""},{"name":"Hwang Yeon-hui","avatar":""},{"name":"Park Kyung-man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be1