INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thien-long-bat-bo-2013', 'Tân Thiên Long Bát Bộ', 'The Demi-Gods And Semi-Devils', 'https://phimimg.com/upload/vod/20250610-1/058be0c82885b1c7a354b5978e1f4f27.jpg', 'https://phimimg.com/upload/vod/20250610-1/886e12c76d100d8b065ead0cce1e4bb4.jpg', '<p>Kiều Phong bị trục xuất khỏi Cái Bang và lên đường hành tẩu giang hồ nhằm điều tra chân tướng sự thật của những âm mưu nhắm vào mình. Trong hành trình này, Kiều Phong đã gặp gỡ và kết nghĩa huynh đệ với hai kỳ tài võ học là Đoàn Dự và Hư Trúc. Ba vị anh hùng tuy tầng lớp, xuất thân khác biệt nhưng đã đồng sinh cộng tử cùng đối đầu với trùng trùng ân oán trong loạn thế giang hồ.</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 11, 2013, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Chung Hán Lương","avatar":""},{"name":"Kim Khởi Phạm","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Trương Mông","avatar":""},{"name":"Giả Thanh","avatar":""},{"name":"Tôn Phong Nham","avatar":""},{"name":"Triệu Viên Duệ","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Trương Hinh Dư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["天龙八部 2013","天龙八部钟汉良","천룡팔부","天龙八部"]', 1784690324460);
