INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do', 'Sự Cám Dỗ', 'Nasha', 'https://phimimg.com/upload/vod/20250609-1/067bc0e8062feef00b08b27770d5a185.jpg', 'https://phimimg.com/upload/vod/20250609-1/60fb9e94c55240ba1e4eeec78d93b03d.jpg', '<p>Nasha là bộ phim khiêu dâm tuổi teen Ấn Độ năm 2013 của đạo diễn Amit Saxena. Bộ phim là sự ra mắt Bollywood của Shivam Patil và Poonam Pandey. Sau khi phát hành, Nasha đã nhận được phản ứng chỉ trích trái chiều.</p>', 'Full', 1, 'single', 'completed', 26, 2013, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Poonam Pandey","avatar":""},{"name":"Shivam Patil","avatar":""},{"name":"Ranbir Chakma","avatar":""},{"name":"Mohit Chauhan","avatar":""},{"name":"Vishal Bhonsle","avatar":""},{"name":"Sheetal Singh","avatar":""},{"name":"Rohan Khurana","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Дурман","नशा"]', 1784690324460);
