INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hobbit-dai-chien-voi-rong-lua', 'Người Hobbit: Đại Chiến Với Rồng Lửa', 'The Hobbit: The Desolation of Smaug', 'https://phimimg.com/upload/vod/20250531-1/13544113937967705074b76de7bb22a8.jpg', 'https://phimimg.com/upload/vod/20250531-1/17c9567604f918b82399bf076c51b5ee.jpg', '<p>Phim &quot;Người Hobbit: Đại Chiến Với Rồng Lửa&quot; tiếp tục kể về cuộc phiêu lưu của nhân vật chính Bilbo Baggins và cuộc hành trình với phù thuỷ Gandalf cùng mười ba người lùn dẫn đầu bởi Thorin Oakenshield, họ mang trên mình một nhiệm vụ sử thi để đòi lại Lonely Mountain và Vương quốc người lùn đã mất của Erebor. &nbsp;Sống sót trong cuộc hành trình bất ngờ, cả đoàn đã đi về phía Đông, dọc đường họ đã gặp phải tộc người hoá gấu Beorn và một đàn nhện khổng lồ trong khu rừng nguy hiểm ở Mirkwood. Sau khi thoát khỏi móng vuốt của các Wood-Elf, các người lùn tìm đến thị trấn Lake và cuối cùng đến được Lonely Mountain - nơi họ phải đối mặt với nguy hiểm lớn nhất đó là một sinh vật đáng sợ hơn bất kỳ ai, thứ mà sẽ kiểm chứng không chỉ lòng dũng cảm mà thử thách cả giới hạn tình bạn của họ – Rồng Smaug.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ian McKellen","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Ken Stott","avatar":""},{"name":"James Nesbitt","avatar":""},{"name":"Mikael Persbrandt","avatar":""},{"name":"Sylvester McCoy","avatar":""},{"name":"Aidan Turner","avatar":""},{"name":"Dean O''Gorman","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Adam","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Kääbik: Smaugi laastatud maa","Hobiti: Smaugis aokhrebuli","HaHobit: Mapal''to Shel Smaug","Hobitas: Smogo dykyne","El Hobbit 2: La desolación de Smaug","De Hobbit: de Woestenij van Smaug","Hobbit 2: Pustkowie Smauga","Hobit: Šmaugovo pustošenje","The Hobbit 2: The Desolation of Smaug","The Hobbit II: The Desolation of Smaug","The Hobbit: The Desolation of Smaug 3D","Hobbiten 2 - Smaugs ødemark","El Hobbit II: La desolación de Smaug","Le Hobbit 2 - La Désolation de Smaug","哈比人：荒谷魔龙","哈比人：荒谷惡龍","The Hobbit - The Desolation of Smaug","A hobbit - Smaug pusztasága","Хоббіт: Пустка Смоґа","Lo Hobbit 2 - La desolazione di Smaug","호빗-스마우그의 폐허","Hobbitten - Dragen Smaugs Oedemark","호빗 2; 스마우그의 폐허","호빗 2: 스마우그의 폐허","호빗; 스마우그의 폐허","ホビット 竜に奪われた王国：2013","Người Hobbit 2: Đại Chiến Với Rồng Lửa","Der Hobbit 2 - Smaugs Einöde","الهوبيت : خراب التنين سموج","Хоббит 2","Хоббит Пустошь Смауга","Hobbit: Smaug''un Çorak Toprakları","The Hobbit: The Desolation of Smaug"]', 1784690324460);
