INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-vien-bao-tang-bao-boi', 'Doraemon: Nobita và Viện Bảo Tàng Bảo Bối', 'Doraemon: Nobita''s Secret Gadget Museum', 'https://phimimg.com/upload/vod/20250521-1/96d7084a6ed4b2a61c227db820d09883.jpg', 'https://phimimg.com/upload/vod/20250521-1/960de14ce495fc490fd32e801d111158.jpg', '<p>Một kẻ tự xưng là siêu trộm Kaito Deluxe (DX) đã đột nhập vào nhà Nobita lúc nửa đêm và lấy đi quả chuông của Doraemon. Điều này đưa Nobita và nhóm bạn vào cuộc phiêu lưu tại một nơi mang tên &quot;Viện Bảo Tàng Bảo Bối Tương Lai&quot;, đây là nơi lưu giữ tất cả các bảo bối tại thế kỷ 22. Cuộc điều tra trở nên phức tạp và kỳ lạ hơn khi có sự xuất hiện của những nhân vật mới.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Sachi Matsumoto","avatar":""},{"name":"Osamu Mukai","avatar":""},{"name":"Yuko Sanpei","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Rikako Aikawa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Nobita''s Secret Gadget Museum","Doraemon Nobita no Himitsu Dougu Museum","Doraemon and Nobita Holmes in the Mysterious Museum of the Future","도라에몽 : 노비타의 비밀도구 박물관","道具博物館","Doraemon: Nobita''s Secret Gadget Museum","哆啦A梦 大雄的秘密道具博物馆","Muzium Peralatan Rahsia Nobita","多啦A梦大电影：大雄的秘密道具博物馆","映画ドラえもん のび太のひみつ道具博物館"]', 1784690324460);
