INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-song-mot-minh', 'Tôi Sống Một Mình', 'I Live Alone', 'https://phimimg.com/upload/vod/20250304-1/17c3607b473c62b0fe62bca2fc8a6e7d.jpg', 'https://phimimg.com/upload/vod/20250304-1/b823ce2b8a2904adbec6f195213be73e.jpg', '<p>I Live Alone là một chương trình thực tế Hàn Quốc theo phong cách tài liệu, ghi lại cuộc sống hàng ngày của các thành viên trong câu lạc bộ tự thành lập mang tên **Rainbow** – nhóm gồm những người nổi tiếng độc thân và sống một mình. Với thông điệp rằng việc sống độc thân có thể là một &quot;huy hiệu danh dự&quot;, chương trình mang đến cái nhìn chân thực, hài hước và đầy cảm xúc về cuộc sống cá nhân của những người nổi tiếng khi không có máy quay sân khấu hay kịch bản.</p>', 'Tập 596', 1000, 'tvshows', 'ongoing', 12, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Na-rae","avatar":""},{"name":"Jeon Hyun-moo","avatar":""},{"name":"Key","avatar":""},{"name":"Hwasa","avatar":""},{"name":"Code Kunst","avatar":""},{"name":"Kian84","avatar":""},{"name":"Lee Jang-woo","avatar":""},{"name":"Lee Ju-seung","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Cha Seo-won","avatar":""},{"name":"Honey J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["I Live Alone","我独自生活 2023","나혼자 산다","나혼자산다 2023","Nahonja Sanda","Home Alone","나 혼자 산다"]', 1784690324460);
