INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-mat-trang-2', 'Kẻ Trộm Mặt Trăng 2', 'Despicable Me 2', 'https://phimimg.com/upload/vod/20250516-1/af854e7ccc3f931e50c44d11e311eab3.jpg', 'https://phimimg.com/upload/vod/20250516-1/bda2e80f1ef61467ad0ede1e384c6fb2.jpg', '<p>Trong Despicable Me 2, nhân vật Gru rũ bỏ quá khứ là một tên trộm tinh quái để toàn tâm nuôi dạy 3 cô con gái là Margo, Edith và Agnes. Thế nhưng ngay khi Gru quyết định lui về với gia đình và trở thành một người cha mẫu mực thì một tổ chức bí mật với quy mô toàn cầu đến gõ cửa. Gru cùng với cộng sự mới của anh - Lucy cùng bắt tay tham gia vào cuộc truy tìm xem ai là kẻ đứng sau chuỗi những phi vụ âm mưu đình đám đang diễn ra. Và thế là, quái kiệt Gru một thời lại trở lại với thế giới để khẳng định vị trí bất khả chiến bại của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2013, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Steve Carell","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Miranda Cosgrove","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Elsie Fisher","avatar":""},{"name":"Dana Gaier","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Nasim Pedrad","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Chris Renaud","avatar":""},{"name":"Nickolai Stoilov","avatar":""},{"name":"Vanessa Bayer","avatar":""},{"name":"Ava Acres","avatar":""},{"name":"Lori Alan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Mina, supervaras 2","Ganouv al ha''Minionim","Grozan ja 2","Çilgin Hirsiz 2","Нiкчемний я 2","גנוב על הירח 2","Dumma mig 2","من شرور 2","Verschrikkelijke Ikke 2","Despicable Me 2 3D","Détestable-moi 2","卑鄙的我2","坏蛋奖门人2","Despicable Me 2: Back 2 Work!","Kẻ Trộm Mặt Trăng 2","怪盗グルーのミニオン危機一発：2013","Jaz, baraba 2","Gru 2. Mi villano favorito","壞蛋獎門人2","Gru na super tajnom zadatku","怪盗グルーのミニオン危機一発","Ich - Einfach unverbesserlich 2","Gru, el meu dolent preferit 2","Illumination''s Despicable Me 2","Despicable Me 2"]', 1784690324460);
