INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-quoc-phan-3', 'Tổ Quốc (Phần 3)', 'Homeland (Season 3)', 'https://phimimg.com/upload/vod/20250515-1/f3de2cf2fe03ea381764113ca7897688.jpg', 'https://phimimg.com/upload/vod/20250515-1/84fca875abf95a8549eaf72307d3678a.jpg', '<p>Ở loạt phim chính trị gay cấn này, chuyên viên phân tích CIA Carrie Mathison phải đối mặt các vấn đề sức khỏe tâm thần và gia đình khi lãnh đạo cuộc chiến chống khủng bố.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 19, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Claire Danes","avatar":""},{"name":"Mandy Patinkin","avatar":""},{"name":"Maury Sterling","avatar":""},{"name":"Numan Acar","avatar":""},{"name":"Nimrat Kaur","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Costa Ronin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Хоумленд","מולדת","ホームランド","Homeland: V mene vlasti","國土安全","Homeland"]', 1784690324460);
