INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-tran-chien-cuoi-cung', 'Diệp Vấn: Trận Chiến Cuối Cùng', 'Ip Man: The Final Fight', 'https://phimimg.com/upload/vod/20231115-1/2d9cc6bef5740a3133ec16c962bbf80f.jpg', 'https://phimimg.com/upload/vod/20231115-1/82619b329313da8f62c3311faf5e9db3.jpg', '<p>Hồng Kông thời hậu chiến, đại võ sư Diệp Vấn bắt buộc phải tham gia một cuộc đấu. Thoạt đầu, đó dường như chỉ là những thử thách đơn giản của môn phái đối đầu. Những thử thách dần dần dẫn dắt ông đi vào một thế giới ngầm của Hội Tam Hoàng đầy rẫy hiểm nguy. Để bảo toàn cuộc sống và danh dự, ông buộc phải chiến đấu hết mình.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Chung Hân Đồng","avatar":""},{"name":"Tăng Chí Vỹ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324460);
