INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cham-vao-toi-ac', 'Chạm Vào Tội Ác', 'A Touch Of Sin', 'https://phimimg.com/upload/vod/20231111-1/43dabf62a3e66e973dd422a365783076.jpg', 'https://phimimg.com/upload/vod/20231111-1/2c8c7cc312f3521076baea369090d4a3.jpg', '<p>Bộ phim với cấu trúc bốn phần, kể bốn câu chuyện dựa trên những sự kiện có thật: ba vụ án hình sự gây chấn động cả nước: Hồ Văn Hải, Chu Khắc Hoa, Đặng Ngọc Kiều, và sự kiện nhảy lầu ở Foxconn. Kể về Đại Hải ở núi Ô Kim vì thôn trưởng và Tiêu Thắng Lợi lợi dụng mỏ than để tư lợi mà phẫn nộ, nhiều lần cầu xin công lý không thành, lửa giận bốc lên; Tam Nhi về quê ăn Tết mừng thọ mẹ, chán ghét cuộc sống bình thường, nhớ nhung những ngày tháng giang hồ xưa kia; Tiểu Ngọc làm việc ở tiệm massage, khát khao xác lập quan hệ với người tình, nhưng lại rơi vào vòng xoáy tình cảm, cuối cùng vì không thể chịu đựng được sự ức hiếp mà đứng lên phản kháng; còn Tiểu Huy đi làm thuê ở Đông Quản, để trốn tránh tranh chấp tiền sinh hoạt với bạn làm cùng, chuyển sang kiếm sống ở hộp đêm, bất ngờ gặp gỡ người đồng hương xinh đẹp. Bốn người ở bốn vùng khác nhau của Trung Quốc, họ vô tình gặp gỡ, mỗi người đối diện với những nỗi buồn, tình yêu và hy vọng trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Võ","avatar":""},{"name":"Vương Bảo Cường","avatar":""},{"name":"Triệu Đào","avatar":""},{"name":"La Lam Sơn","avatar":""},{"name":"Trương Gia Dịch","avatar":""},{"name":"Lý Mộng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324460);
