INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-den-phan-2', 'Gương Đen (Phần 2)', 'Black Mirror (Season 2)', 'https://phimimg.com/upload/vod/20231002-1/786f0d07aba8dd49bfa3e174ab1346ce.jpg', 'https://phimimg.com/upload/vod/20231002-1/a591b45c50f46afad0f61d4a24011282.jpg', '<p>Black Mirror: Season 2 (Gương Đen: Phần 2): là tên chung của loạt phim truyền hình Anh (2011), dựng theo những kịch bản lạ lùng của tác giả Charlie Brooker. Black Mirror mô tả những thực tại trong đó con người kết nối liên tục với nhau và với quá khứ bằng thiết bị số. Hình ảnh của mỗi người, hầu như mọi hoạt động của mỗi người trong ngày, đều soi bóng trong vô vàn &quot;gương đen&quot; bủa vây âm thầm. &quot;Gương đen&quot; là thiết bị ghi nhận sự hiện diện của mỗi người, có ở khắp nơi: trên tường, trên bàn, trong tay mọi người. Trong loạt phim Black Mirror, phim The Entire History of You mô tả tác động của thiết bị đặc biệt, được cấy ghép vào người để ghi nhận, lưu giữ mọi hình ảnh thu nhận qua mắt. Người mang thiết bị có thể xem lại những gì đã thấy ở bất kỳ thời điểm nào trong đời và cho người khác cùng xem, nếu muốn. Đó là loại ký ức được ghi thành phim, không phải trí nhớ dễ méo mó, dễ hao hụt của con người, được chia sẻ với người khác chỉ bằng lời kể. Phim xoay quanh những xung đột trong một gia đình khi người chồng thấy được hình ảnh ngoại tình rành rành trong ký ức của người vợ. Một khi có thiết bị cho phép thấy lại rõ ràng mọi hình ảnh ở bất kỳ thời điểm nào trong quá khứ, con người không thể che giấu bất cứ sự thật nào và không thể lãng quên những nỗi đau.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 11, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bryony Neylan-Francis","avatar":""},{"name":"Shawn Aldin-Burnett","avatar":""},{"name":"Daniel Kaluuya","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
