INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ket-noi', 'Mất Kết Nối', 'Disconnect', 'https://phimimg.com/upload/vod/20250411-1/2117dbae4b165acafc6e2754d8963444.jpg', 'https://phimimg.com/upload/vod/20250411-1/0447a43bd6e6ab9035c38e56c1b85600.jpg', '<p>Bộ phim nói về những hậu quả khôn lường do việc con người lạm dụng internet và mạng xã hội để phơi bày cuộc sống cá nhân.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Paula Patton","avatar":""},{"name":"Max Thieriot","avatar":""},{"name":"Michael Nyqvist","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Jonah Bobo","avatar":""},{"name":"Colin Ford","avatar":""},{"name":"Haley Ramm","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Kasi Lemmons","avatar":""},{"name":"John Sharian","avatar":""},{"name":"Aviad Bernstein","avatar":""},{"name":"Teresa Calentano","avatar":""},{"name":"Marc Jacobs","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["疏離世界","Lahti ühendatud","Desligados","Nepovezano","Sanal Hayatlar","Disconnect. Reconnect.","Desconexión","Os Desconectados","Disconnect","디스커넥트"]', 1784690324460);
