INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-pudhiphat', 'Bác Sĩ Pudhiphat', 'Khun Chai Pudhiphat', 'https://phimimg.com/upload/vod/20250406-1/80badcdd5c8aaf75b63a45eabcb3389a.jpg', 'https://phimimg.com/upload/vod/20250406-1/284c1e35ed2d0737ead6dee068932749.jpg', '<p>Nối tiếp câu chuyện về cậu con trai thứ 2 nhà Juthathep trong Series Những Quý Ông Nhà Juthathep phần 3 kể về cậu Khun Chai Bác Sĩ, Khun Chai Pudhiphat, một người vừa có tài vừa khiến bao nhiêu cô gái đập loạn nhịp vì vẻ ngoài ưu nhìn đầy trẻ con của mình. Dù sinh ra trong một gia tộc nổi tiếng nhưng cậu ưu thích công việc của mình và sẵn sàng cống hiến bản thân vì y học chứ không hề có hứng thú gì đến giới thượng lưu. Do duyên phận, cậu gặp và trúng tiếng sét ái tình với Krong Keaw, Tân Hoa Hậu Sri Siam, người cũng đang gặp rắc rối vì bị lừa trở thành người tình của tướng Pinit, người đáng tuổi cha cô. Cậu đã giúp đỡ cô và từ đó trong mỗi người nhen nhóm lên 1 thứ tình cảm với đối phương. Nhưng thứ tình cảm ấy lại bị cả hai che giấu trong lòng do sự khác biệt về giai cấp xã hội.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jame Jirayu Tangsrisuk","avatar":""},{"name":"Bella Vanita","avatar":""},{"name":"Noey Chotika Wongwilas","avatar":""},{"name":"Got Jirayu Thantrakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["สุภาพบุรุษจุฑาเทพ","Suparburoot Jutathep Series","Suparburoot Jutathep","Surparabaroot","Khun Chai Tharathorn","Khun Chai Phutthiphat","สุภาพบุรุษจุฑาเทพ: คุณชายรณพีร์","สุภาพบุรุษจุฑาเทพ: คุณชายพุฒิภัทร","สุภาพบุรุษจุฑาเทพ ตอน คุณชายรัชชานนท์","Khun Chai Ratchanon","คุณชายรณพีร์","Khun Chai Pawornruj","คุณชายปวรรุจ","สุภาพบุรุษจุฑาเทพ: คุณชายปวรรุจ","คุณชายพุฒิภัทร","คุณชายธราธร","สุภาพบุรุษจุฑาเทพ: คุณชายรัชชานนท์","Khun Chai Ronaphee","สุภาพบุรุษจุฑาเทพ: คุณชาย"]', 1784690324460);
