INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-pudhiphat', 'Bác Sĩ Pudhiphat', 'Khun Chai Pudhiphat', 'bác sĩ pudhiphat khun chai pudhiphat jame jirayu tangsrisuk bella vanita noey chotika wongwilas got jirayu thantrakul สุภาพบุรุษจุฑาเทพ suparburoot jutathep series suparburoot jutathep surparabaroot khun chai tharathorn khun chai phutthiphat สุภาพบุรุษจุฑาเทพ: คุณชายรณพีร์ สุภาพบุรุษจุฑาเทพ: คุณชายพุฒิภัทร สุภาพบุรุษจุฑาเทพ ตอน คุณชายรัชชานนท์ khun chai ratchanon คุณชายรณพีร์ khun chai pawornruj คุณชายปวรรุจ สุภาพบุรุษจุฑาเทพ: คุณชายปวรรุจ คุณชายพุฒิภัทร คุณชายธราธร สุภาพบุรุษจุฑาเทพ: คุณชายรัชชานนท์ khun chai ronaphee สุภาพบุรุษจุฑาเทพ: คุณชาย', '');
