INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-so-ba-linh', 'Hồ Sơ Bá Linh', 'The Berlin File', 'hồ sơ bá linh the berlin file ha jung-woo han suk-kyu ryoo seung-bum jun ji-hyun lee kyung-young kwak do-won yoon jong-bin kim seo-hyung choi moo-seong dong bang-woo john keogh numan acar pasquale aleardi thomas thieme tayfun bademsoy werner daehn sinja dieks toni var bereulin l''agent ベルリンファイル akta berlińskie 柏林 the berlin file (2013) 柏林档案 柏林谍变 berlin dosyası 柏林諜戰 berlinski dosije берлинское дело dosarul berlin agentura a berlini ügynök a berlin-akta berlínská mise o arquivo de berlim the berlin file 베를린', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-trung-nhac-phi', 'Tinh Trung Nhạc Phi', 'The Loyalty of Yue Fei', 'https://phimimg.com/upload/vod/20250324-1/a0d26bb30fd16630db0ade5788477f59.jpg', 'https://phimimg.com/upload/vod/20250324-1/9c04998e99c34e6e95f4450cd109535f.jpg', '<p>Phim mô tả cuộc đời truyền kỳ của danh tướng Nhạc Phi, từ lúc là một binh sĩ bình thường cho đến khi trở thành thống soái chống quân Kim. Nhạc Phi thiếu thời có cơ duyên từng được thọ giáo các vị danh thần Lưu Cáp, Hàn Tiêu Trụ, Lý Cương, Trương Sở về quân sự; trải qua hai mươi năm phấn dũng kháng Kim, thân trải trăm trận, cuối cùng bị gian thần bức hại, chết oan ở Phong Ba đình</p>', 'Hoàn Tất (69/69)', 69, 'series', 'completed', 20, 2013, 'Lồng Tiếng + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Xiaoming","avatar":""},{"name":"Ruby Lin","avatar":""},{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Wu Xiubo","avatar":""},{"name":"Liu Shishi","avatar":""},{"name":"Zhang Zhixi","avatar":""},{"name":"Wang Ou","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Wang Zhi","avatar":""},{"name":"Huang Xiaoge","avatar":""},{"name":"Wang Teng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Jing Zhong Yue Fei","The Patriot Yue Fei","精忠岳飞"]', 1784690324460);
