INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-ten-xanh-phan-2', 'Mũi Tên Xanh (Phần 2)', 'Arrow (Season 2)', 'https://phimimg.com/upload/vod/20240624-1/242d24823637e49f12ef3cbb3852d944.jpg', 'https://phimimg.com/upload/vod/20240624-1/09ee5b95904f4981060b9edaf38b5c28.jpg', '<p>Vào cuối Phần 1, thành phố Starling chịu tổn thất nặng nề và Oliver Queen cũng vậy. Rút kinh nghiệm từ những sai lầm của mình, Oliver quyết định thay đổi phương pháp của mình ngay cả khi vẫn tôn trọng lời hứa với bạn mình. Trong khi đó, kẻ thù mới từ quá khứ của anh lại xuất hiện và gây khó khăn cho cuộc sống của Oliver.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Amell","avatar":""},{"name":"David Ramsey","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"Rick Gonzalez","avatar":""},{"name":"Katherine McNamara","avatar":""},{"name":"Juliana Harkavy","avatar":""},{"name":"Joseph David-Jones","avatar":""},{"name":"Ben Lewis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
