INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-lang-vuong', 'Lan Lăng Vương', 'Prince of Lan Ling', 'https://phimimg.com/upload/vod/20250319-1/1ea59e70a587e50b8f195e3cd9669457.jpg', 'https://phimimg.com/upload/vod/20250319-1/e83ad12602d47e97910d158cecdae0d7.jpg', '<p>Được mệnh danh là Chiến thần, bách chiến bách thắng, Lan Lăng Vương luôn đeo một chiếc mặt nạ đáng sợ để che giấu khuôn mặt mình trong khi chỉ huy quân đội. Lan Lăng Vương Cao Trường Cung là một đại tướng quân lừng lẫy của Bắc Tề. Truyền thuyết kể rằng, Lan Lăng Vương là một người rất mưu trí, trung quân ái quốc và đối xử với tướng lĩnh rất khoan hồng.

Có một lời tiên tri rằng: Ai có được thiên nữ sẽ có được thiên hạ. Dương Tuyết Vũ, hậu nhân cuối cùng của Vu tộc, vô tình bị cuốn vào cuộc chiến tranh giữa Bắc Tề và Bắc Chu. Mặc dù đã biết trước vận mệnh bi thảm của Lan Lăng Vương nhưng Tuyết Vũ vẫn đem lòng yêu Lan Lăng Vương và giúp anh chiến thắng trong cuộc chiến tranh với Chu Vũ Đế, Vũ Văn Ung. Nhưng sự cố gắng của Tuyết Vũ chỉ đầy Lan Lăng Vương gần đến vận mệnh của mình. Vì Lan Lăng Vương được người người yêu quý, ngưỡng mộ nên Thái tử Cao Vỹ sinh lòng ghen ghét, đố kỵ. Liệu Tuyết Vũ có thể bảo vệ được Lan Lăng Vương không khi Cao Vỹ muốn giết chết anh?</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 18, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"William Feng","avatar":""},{"name":"Ariel Lin","avatar":""},{"name":"Daniel Chan Hiu-Tung","avatar":""},{"name":"Zhai Tianlin","avatar":""},{"name":"Mao Linlin","avatar":""},{"name":"Han Dong","avatar":""},{"name":"George Hu","avatar":""},{"name":"Tiara Huang","avatar":""},{"name":"Zhang Zimu","avatar":""},{"name":"Wang Di","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"Zheng Xiaoning","avatar":""},{"name":"Wang Zheng","avatar":""},{"name":"Lü Zhong","avatar":""},{"name":"Lu Yong","avatar":""},{"name":"Zhang Guoqing","avatar":""},{"name":"Wang Tian Ye","avatar":""},{"name":"Dai Chunrong","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"Zhu Haijun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Lan Ling Wang","兰陵王","King of Lan Ling","蘭陵王"]', 1784690324460);
