INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-noi-tinh-yeu-bat-dau', 'Trở Về Nơi Tình Yêu Bắt Đầu', 'A Moment Of Love', 'https://phimimg.com/upload/vod/20250219-1/c6a388dfa3aef93de5ba7d44a476a19f.jpg', 'https://phimimg.com/upload/vod/20250219-1/c57b1e8e82f4ef386d89bb7687c3af82.jpg', '<p>Kỷ Nhã Thanh là phóng viên ở Bắc Kinh, tuy sắp đến ngày kết hôn nhưng vì giúp bạn thân Vivian nên cô đồng ý đến Vân Nam viết bài. Tại đây, cô gặp Hứa Niệm Tổ – một chàng trai Đài Loan đang thực hiện di nguyện của người ông nuôi là trao lại di vật cho người yêu của ông (một người cũng tên là Kỷ Nhã Thanh). Sự gặp gỡ tình cờ đưa hai người vào một cuộc hành trình lãng mạn</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Shishi","avatar":""},{"name":"Vic Chou","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hui Dao Ai Kai Shi De Di Fang","Trở Về Nơi Tình Yêu Bắt Đầu","回到愛開始的地方"]', 1784690324460);
