INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-dau-hien-dai', 'Nàng Dâu Hiện Đại', 'Hot Mom!', 'https://phimimg.com/upload/vod/20250218-1/9bed67375e476a3cb8d8e36af74e45e3.jpg', 'https://phimimg.com/upload/vod/20250218-1/85d41358975bd838265bf7e93408483d.jpg', '<p>Bộ phim Bà Mẹ Nóng Bỏng thuộc thể loại phim Tình Cảm của Trung Quốc. Bà Mẹ Nóng Bỏng (Nàng Dâu Hiện Đại) xoay quanh nhân vật Hạ Băng – một nhân viên văn phòng trẻ trung, xinh đẹp và có cá tính hơi nổi loạn một chút. Vì hoàn cảnh đẩy đưa, Hạ Băng đã bất ngờ mang thai ngoài ý muốn và phải sớm bước vào cuộc sống hôn nhân trong sự ghét bỏ của mẹ chồng.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 8, 2013, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Li","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Zhu Yin","avatar":""},{"name":"Xi Meijuan","avatar":""},{"name":"Yang Kun","avatar":""},{"name":"Wang Maolei","avatar":""},{"name":"Donald Tong Kim-Hong","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Pan Hong","avatar":""},{"name":"Cui Shaohan","avatar":""},{"name":"Long Yi Yi","avatar":""},{"name":"Li Yilin","avatar":""},{"name":"Zhu Rui","avatar":""},{"name":"Wu Jin Xi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hot Mom","辣妈正传"]', 1784690324460);
