INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-trinh-mua-he', 'Phương Trình Mùa Hè', 'Midsummer''s Equation', 'https://phimimg.com/upload/vod/20250210-1/f34ee6ad1393b1dc03d94ff8478ac2a3.jpg', 'https://phimimg.com/upload/vod/20250210-1/c1cce3824b2056ab72d73397ce769d1b.jpg', '<p>Masaharu Fukuyama tái diễn vai diễn của anh từ bộ phim &quot;Suspect X&quot; năm 2008, vào vai nhà vật lý kiêm thám tử Manabu Yukawa. Vị thám tử khoa học này đến một thị trấn ven biển để tham gia một buổi nói chuyện. Nhưng khi một người đàn ông được phát hiện chết bên ngoài nhà trọ nơi anh ta đang ở, Yukawa bắt đầu gỡ rối các mối liên hệ giữa nạn nhân và cô con gái hoạt động của chủ nhà trọ, cùng một cậu bé thông minh xuất hiện trên tàu và liên tục xuất hiện. Đây là một câu chuyện trinh thám kiểu Sherlock Holmes với yếu tố môi trường, chắc chắn sẽ làm hài lòng những người hâm mộ thể loại trinh thám cổ điển.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaharu Fukuyama","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Anne Watanabe","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Hakuryu","avatar":""},{"name":"Gin Maeda","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Sansei Shiomi","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Hikaru Yamazaki","avatar":""},{"name":"Tôru Kizu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Manatsu no hôteishiki","Manatsu no houteishiki","한여름의 방정식","Midsummer Formula","ガリレオ 真夏の方程式","神探伽俐略2:真夏方程式","真夏の方程式：2013","真夏の方程式","神探伽利略 盛夏的方程式"]', 1784690324460);
