INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuong-trinh-mua-he', 'Phương Trình Mùa Hè', 'Midsummer''s Equation', 'phương trình mùa hè midsummer''s equation masaharu fukuyama yuriko yoshitaka kazuki kitamura anne watanabe jun fubuki hakuryu gin maeda naomi nishida sansei shiomi tetsushi tanaka hikaru yamazaki tôru kizu manatsu no hôteishiki manatsu no houteishiki 한여름의 방정식 midsummer formula ガリレオ 真夏の方程式 神探伽俐略2:真夏方程式 真夏の方程式：2013 真夏の方程式 神探伽利略 盛夏的方程式', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ataru-moi-tinh-dau-va-lan-giet-cuoi-cung', 'Ataru: Mối Tình Đầu Và Lần Giết Cuối Cùng', 'Ataru: The First Love & The Last Kill', 'https://phimimg.com/upload/vod/20250210-1/659ff90c5640c72afca59ade69bea0a1.jpg', 'https://phimimg.com/upload/vod/20250210-1/6789cc69a355fc4597320e65ff1d78f3.jpg', '<p>Ataru, một người mắc hội chứng &quot;savant&quot;, có khả năng khám phá, quan sát, nhìn thấu và suy luận ra các bằng chứng vi mô của những vụ án chưa được giải quyết. Tại sao anh ta luôn đến hiện trường tội ác? Điều gì giải thích cho hành vi kỳ lạ của anh ta? Trong khi đó, một bí ẩn dần hé lộ với Ataru và một người phụ nữ tên là Madoka, một kẻ giết người. Người phụ nữ này có trí nhớ phi thường và khả năng suy luận giống như Ataru. Cô ta là ai?</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masahiro Nakai","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Chiaki Kuriyama","avatar":""},{"name":"Yuta Tamamori","avatar":""},{"name":"Maki Horikita","avatar":""},{"name":"Yasuko Matsuyuki","avatar":""},{"name":"Hiroaki Murakami","avatar":""},{"name":"Masaki Okada","avatar":""},{"name":"Masachika Ichimura","avatar":""},{"name":"Kyūsaku Shimada","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Seiji Chihara","avatar":""},{"name":"Yasuhi Nakamura","avatar":""},{"name":"Haruka Shimazaki","avatar":""},{"name":"Kaoru Okunuki","avatar":""},{"name":"Ken Sh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["げきじょうばん アタル ザ・ファースト・ラブ・アンド・ザ・ラスト・キル","超智神探ATARU：挑战最强宿敌","劇場版 ATARU THE FIRST LOVE＆THE LAST KILL"]', 1784690324460);
