INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-duong-anh-hung-phan-2', 'Tùy Đường Anh Hùng (Phần 2)', 'Heroes Of Sui And Tang Dynasties (Season 2)', 'https://phimimg.com/upload/vod/20250204-1/6d4e33cd2110a71342447b9b443fce36.jpg', 'https://phimimg.com/upload/vod/20250204-1/4ecff66b625518f35c20880f473a8669.jpg', '<p>Dựa trên những truyền thuyết dân gian và tư liệu lịch sử có thật. Tùy đường là thời kỳ đươc biết đến như thời của giang hồ phân tranh, anh hùng bồi xuất. Bối cảnh phim trải dài từ khi nhà Tùy thành lập, rồi diệt vong, cho đến khi Lý Thế Dân đăng cơ, tạo ra thời kỳ “Trinh Quan Chi Trị”. Bên cạnh đó là những trận chiến của các anh hùng trại Ngõa Cương bảo vệ nông dân vô tội cũng được thể hiện. Trong đó Trình Giảo Kim là một vị quân tử dám làm dám nhận, giang hồ hiệp nghĩa xưng là Hỗ thế Ma Vương tại Ngõa cương đã đã cùng với các anh hùng hào kiệt khắp nơi đứng lên đấu tranh và đòi lại công lý cho bách tính.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 8, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Vệ Kiện","avatar":""},{"name":"Trương Duệ","avatar":""},{"name":"Lưu Hiểu Khánh","avatar":""},{"name":"Diệp Tổ Tân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sui Tang Ying Xiong","Heroes of Sui and Tang","隋唐英雄"]', 1784690324460);
