INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-ki', 'Hoàng Hậu Ki', 'The Empress Kia', 'https://phimimg.com/upload/vod/20231204-1/85d2e2cc50dc807b7530504bdfb8a51f.jpg', 'https://phimimg.com/upload/vod/20231204-1/2fd0f5c950f8bc4b38678ba2fb5d4523.jpg', '<p>Câu chuyện về tình yêu và sự đấu tranh để sinh tồn của một cung nữ dâng trà tầm thường sống giữa chốn cung đình nhiều thị phi, để cuối cùng trở thành Hoàng hậu Ki của triều Nguyên. Bà cũng là người phụ nữ đầu tiên trong lịch sử Hàn Quốc đề cao tình yêu trong lý tưởng chính trị của mình và trở thành niềm tự hào của những người phụ nữ trong chốn hậu cung xưa.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 9, 2013, 'Vietsub + Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji Won","avatar":""},{"name":"Joo Jin Mo","avatar":""},{"name":"Ji Chang Wook","avatar":""},{"name":"Baek Jin Hee","avatar":""},{"name":"Kim Seo Hyung","avatar":""},{"name":"Jeon Kook Hwan","avatar":""},{"name":"Lee Won Jong","avatar":""},{"name":"Lee Moon Sik","avatar":""},{"name":"Kwon Oh Jung","avatar":""},{"name":"Choi Mu Sung","avatar":""},{"name":"Kim Young Ho","avatar":""},{"name":"Jin Yi Han","avatar":""},{"name":"Yoo In Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
