INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-cong-chua-aurora', 'Nàng Công Chúa Aurora', 'Princess Aurora', 'https://phimimg.com/upload/vod/20250111-1/a740b0dd72ebc9261f14f1198dc9baf6.jpg', 'https://phimimg.com/upload/vod/20250111-1/ba2c3055c2bf4bf72e193c2a07b09c72.jpg', '<p>Phim kể về cuộc sống và tình yêu của cô con gái út một gia đình giàu có. Nhìn bề ngoài ai cũng nghĩ cô là một tiểu thư kênh kiệu được nuông chiều, nhưng thực ra cô lại là một cô gái khôn ngoan, luôn tự tin bảo vệ chính kiến trước ba ông anh trai lúc nào cũng xem thường cô. Cô có mối tình lãng mạn với một chàng tiểu thuyết gia điển trai, nhưng quan hệ của họ lại vấp phải ba trở ngại lớn: ba người chị gái của anh chàng.</p>', 'Hoàn Tất (150/150)', 150, 'series', 'completed', 11, 2013, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon So-min","avatar":""},{"name":"Oh Chang-seok","avatar":""},{"name":"Seo Ha-jun","avatar":""},{"name":"Kim Bo-yeon","avatar":""},{"name":"Son Chang-min","avatar":""},{"name":"Park Hae-mi","avatar":""},{"name":"Seo Woo-rim","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Im Ye-jin","avatar":""},{"name":"Lee Hyun-kyoung","avatar":""},{"name":"Kim Hye-eun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aurora, the Princess","오로라 공주"]', 1784690324460);
