INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hoi-dap-1994', 'Lời Hồi Đáp 1994', 'Reply 1994', 'https://phimimg.com/upload/vod/20240316-1/0fc8f7d28a76cc8e6b23038c0d6b0553.jpg', 'https://phimimg.com/upload/vod/20240316-1/d23ccac5044ef773039f679abc6da21d.jpg', '<p>Câu chuyện nói về những người bạn thân đang tham gia bữa tiệc tân gia của một cặp đôi trong số họ, vừa xem lại cuốn băng ghi lại đám cưới của chủ nhà, vừa bàn tán và nhớ về cuộc sống của họ khi còn ở tuổi 20: Năm 1994, sáu chàng trai, cô gái đến từ các tỉnh thành khác nhau của Hàn Quốc lần đầu tới Seoul để bắt đầu cuộc sống sinh viên.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Go Ara","avatar":""},{"name":"Jung Woo","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Son Ho-jun","avatar":""},{"name":"Cha Sun-woo","avatar":""},{"name":"Min Do-hee","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Yook Sung-jae","avatar":""},{"name":"Yeon Jun-seok","avatar":""},{"name":"Yoon Jong-hoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324460);
