INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang', 'Nàng', 'Her', 'https://phimimg.com/upload/vod/20241218-1/73e211938d22ef363ece15a845a7394f.jpg', 'https://phimimg.com/upload/vod/20241218-1/0b1408ee2841e0967af302b50cc21c9a.jpg', '<p>Theodore là một nhà văn cô đơn, hướng nội, làm nghề viết thư tình cho những người gặp khó khăn trong việc biểu lộ cảm xúc. Trầm cảm và chán nản sau khi ly dị vợ - tình yêu từ thuở ấu thơ, Theodore đã rơi vào mối quan hệ với Samantha, một hệ điều hành máy tính có trí thông minh nhân tạo và khả năng học hỏi, giao tiếp như con người bình thường...</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Lynn Adrianna","avatar":""},{"name":"Lisa Renee Pitts","avatar":""},{"name":"Gabe Gomez","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Artt Butler","avatar":""},{"name":"May Lindstrom","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Brian D. Johnson","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Spike Jonze","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"David Azar","avatar":""},{"name":"Guy Lewis","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["云端情人","触不到的她","그녀","Her：2013","Nàng","Ella","Նե","O.","Ela","Тя","Ona","Hende","Temake","Dikos tis","Δικός της","觸不到的她","A nő","Ou","Hee","Lei","her/世界でひとつの彼女","Ол","Viņa","Ji","Uma História de Amor","Geu-nyeo","雲端情人","Rak Dang Fang Chat","Aşk","Вона","U","Her"]', 1784690324460);
