INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang', 'Nàng', 'Her', 'nàng her joaquin phoenix scarlett johansson lynn adrianna lisa renee pitts gabe gomez chris pratt artt butler may lindstrom rooney mara bill hader kristen wiig brian d. johnson amy adams matt letscher spike jonze olivia wilde david azar guy lewis 云端情人 触不到的她 그녀 her：2013 nàng ella նե o. ela тя ona hende temake dikos tis δικός της 觸不到的她 a nő ou hee lei her/世界でひとつの彼女 ол viņa ji uma história de amor geu-nyeo 雲端情人 rak dang fang chat aşk вона u her', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-phan-dac-biet', 'Thân Phận Đặc Biệt', 'Special ID', 'https://phimimg.com/upload/vod/20241206-1/d047312436ad472daa0fb3a1d04d44d0.jpg', 'https://phimimg.com/upload/vod/20241206-1/b47bf58511d0f133e84e60a4d5ab0359.jpg', '<p>Phim kể về cảnh sát Trần Tử Long và nhóm của anh được giao nhiệm vụ xâm nhập vào thế giới ngầm khắc nghiệt và tàn nhẫn nhất của Trung Quốc để ngăn chặn âm mưu độc ác của tên trùm tội phạm xã hội đen Trương Mao Hùng. &nbsp;Cách duy nhất để anh báo cáo về trụ sở là cố tình bị bắt giam. Sau nhiều lần như vậy, tên trùm Trương Mao Hùng bắt đầu nghi ngờ thân phận của anh. Hắn suy nghĩ loại bỏ mọi cách xâm nhập vào băng đảng xã hội đen của Trần Tử Long. Khi đến Trung Quốc, Trần Tử Long đối mặt với cánh tay phải của Trương Mao Hùng là Suny, được giao nhiệm vụ xử tử những cảnh sát nằm vùng. &nbsp;Ở Trung Quốc, Trần Tử Long được nữ cảnh sát xinh đẹp, dũng cảm Phương Tĩnh hỗ trợ nhưng hai người lại có quan điểm, cách xử lý không giống nhau. Khi thân phận cảnh sát chìm bị bại lộ, tính mạng của anh cũng như người thân trong gia đình bị đe dọa. &nbsp;Trong cuộc chiến quyết liệt với cái ác, Trần Tử Long bị giằng xé giữa bảo vệ gia đình và che giấu thân phận thật của chính mình…</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Donnie Yen Chi-Tan","avatar":""},{"name":"Jing Tian","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Ronald Cheng Chung-Kei","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Yang Zhigang","avatar":""},{"name":"Terence Yin Chi-Wai","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Andrew Yan Hua","avatar":""},{"name":"Tony Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Special ID","Особая личность","Identidade Especial","Te Shu Shen Fen","特殊身份"]', 1784690324460);
