INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-tinh-yeu', 'Bài Học Tình Yêu', 'Love Lesson', 'https://phimimg.com/upload/vod/20241116-1/fdff9d5b80aaf56c97723884605d22d3.jpg', 'https://phimimg.com/upload/vod/20241116-1/9591075a6ee88e708490f03c5eb58458.jpg', '<p>Tác giả bài hát nổi tiếng nhất Hàn Quốc Hee-soo tình cờ gặp một cậu bé 19 tuổi trong thang máy. Hee-soo lấy cảm hứng từ một bài hát mới khi nhìn anh rung chuyển trước hình dáng của cô. Cô bắt đầu kể cho anh nghe về phụ nữ với lý do cô đang dạy nhạc cho anh. Họ yêu nhau nhưng mọi chuyện trở nên phức tạp khi người thầy cuộc sống của cô, Joon-ho, người đã dạy cô về cuộc sống và âm nhạc quay lại.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Sun-young","avatar":""},{"name":"Byun Jun-suk","avatar":""},{"name":"Oh Cho-hee","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Heo Jung-min","avatar":""},{"name":"Min Ji-Hyuk","avatar":""},{"name":"Kim Da-bin","avatar":""},{"name":"Nam Tae-boo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Fancy Walk","화려한 외출","hwa-ryeo-han oi-chool","Love Lesson","愛的教慾","華麗的外出","情欲奏鳴曲"]', 1784690324460);
