INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-hai-tac-akf', 'Vịnh Hải Tặc AKF', 'TPB AFK The Pirate Bay Away From Keyboard', 'https://phimimg.com/upload/vod/20241116-1/852fa13905abcacc7957fc75eefd1aae.jpg', 'https://phimimg.com/upload/vod/20241116-1/098126090ec75346e811ae3882f07c6e.jpg', '<p>TPB AFK: The Pirate Bay Away From Keyboard là một bộ phim tài liệu Thụy Điển năm 2013 do Simon Klose đạo diễn và sản xuất. Nó tập trung vào cuộc sống của ba người sáng lập The Pirate Bay - Peter Sunde, Fredrik Neij, và Gottfrid Svartholm - và phiên tòa xét xử Pirate Bay.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Gottfrid Svartholm","avatar":""},{"name":"Fredrik Neij","avatar":""},{"name":"Peter Sunde","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["TPB-AFK","TPB AFK","The Pirate Bay - Away from Keyboard","海盜灣：分享中","TPB AFK: The Pirate Bay Away from Keyboard","TBP AFK","The Pirate Bay: Away from Keyboard","The Pirate Bay AFK","TPB AFK: The Pirate Bay - Away from Keyboard"]', 1784690324460);
