INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dua-nghet-tho', 'Đường Đua Nghẹt Thở', 'Rush', 'https://phimimg.com/upload/vod/20241114-1/e239d43e6400f09c7891cb77bcb89e64.jpg', 'https://phimimg.com/upload/vod/20241114-1/a868b49a5aeb34b6b4e8081d915e1175.jpg', '<p>Đường Đua Nghẹt Thở là câu chuyện có thật về hai tay đua huyền thoại: Niki Lauda và James Hunt. Thế nhưng còn hơn thế nữa, đây là sự đối đầu của hai tính cách, một cuộc đối đầu vĩ đại nhưng bên trong nó là một tình bạn cao thượng (friendemy).Niki Lauda là huyền thoại của làng đua xe. Bộ dạng như một con chuột, Niki là con người thực dụng, sử dụng kinh nghiệm và sự tính toán đầu óc trên đường đua (bản thân anh cũng là một thiên tài cơ khí và tự hào với một bộ mông trời phú &quot;chỉ cần ngồi lên là biết xe thế nào&quot;). Anh tới với F1 chỉ vì, theo tính toán logic của anh, đó là công việc mà anh làm giỏi nhất và sẽ thành công nhất (&quot;nếu có việc khác có thể thành công hơn, tôi sẽ bỏ đua xe ngay). Phương châm của Niki là chấp nhận rủi ro đến 20%, nhưng ...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Alexandra Maria Lara","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"David Calder","avatar":""},{"name":"Natalie Dormer","avatar":""},{"name":"Stephen Mangan","avatar":""},{"name":"Christian McKay","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Colin Stinton","avatar":""},{"name":"Julian Rhind-Tutt","avatar":""},{"name":"Jamie de Courcey","avatar":""},{"name":"Augusto Dall''Ara","avatar":""},{"name":"Ilario Calv","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Гонка","Rush"]', 1784690324460);
