INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-thu-vo-hinh-phan-2', 'Tuyển Thủ Vô Hình (Phần 2)', 'Kuroko''s Basketball (Season 2)', 'https://phimimg.com/upload/vod/20241103-1/fccf441b4b2567c5c64d5af4f6d1ede7.jpg', 'https://phimimg.com/upload/vod/20241103-1/9b22736870e2161e93949a6b0e2fa820.jpg', '<p>Đội bóng rổ trường sơ trung Teikō đã tạo nên tiếng tăm lừng lẫy bằng cách càn quét hết tất cả các cuộc thi. Những thành viên thường trực của đội bóng này được biết đến với cái tên &quot;Thế Hệ Những Cầu Thủ Phi Thường&quot;. Sau khi tốt nghiệp sơ trung, năm ngôi sao của đội đến học ở những trường trung học khác nhau với những đội bóng danh tiếng. Tuy nhiên, có một tin đồn rằng: còn một thành viên nữa thuộc &quot;Thế Hệ Những Cầu Thủ Phi Thường&quot;, bóng ma thứ sáu. Cầu thủ bí ẩn này hiện đang là học sinh năm nhất của trường cao trung Seirin, một ngôi trường mới được thành lập với một đội bóng đầy tiềm năng nhưng ít được biết đến. Giờ đây, Kuroko Tetsuya, thành viên thứ sáu của &quot;Thế Hệ Những Cầu Thủ Phi Thường&quot;, và Kagami Taiga, một cầu thủ có năng lực tiềm ẩn từng học sơ trung ở Mỹ đang hướng Seirin trở thành nhà vô địch của Nhật Bản, hạ gục từng thành viên của &quot;Thế Hệ Những Cầu Thủ Phi Thường &quot;. Câu chuyện của ánh sáng và bóng tối sẽ đi về đâu?</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 10, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小野賢章","avatar":""},{"name":"小野友樹","avatar":""},{"name":"諏訪部順一","avatar":""},{"name":"小野大輔","avatar":""},{"name":"木村良平","avatar":""},{"name":"神谷浩史","avatar":""},{"name":"鈴村健一","avatar":""},{"name":"斎藤千和","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"野島裕史","avatar":""},{"name":"江口拓也","avatar":""},{"name":"浜田賢二","avatar":""},{"name":"保志総一朗","avatar":""},{"name":"水谷直樹","avatar":""},{"name":"谷山紀章","avatar":""},{"name":"井上剛","avatar":""},{"name":"折笠富美子","avatar":""},{"name":"鈴木達央","avatar":""},{"name":"福山潤","avatar":""},{"name":"三木眞一郎","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Kuroko no Basket","Kurokos Basketball","幻影籃球王","Kuroko no Basuke","黑子的籃球","黒子のバスケ"]', 1784690324460);
