INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyen-thu-vo-hinh-phan-2', 'Tuyển Thủ Vô Hình (Phần 2)', 'Kuroko''s Basketball (Season 2)', 'tuyển thủ vô hình (phần 2) kuroko''s basketball (season 2) 小野賢章 小野友樹 諏訪部順一 小野大輔 木村良平 神谷浩史 鈴村健一 斎藤千和 細谷佳正 野島裕史 江口拓也 浜田賢二 保志総一朗 水谷直樹 谷山紀章 井上剛 折笠富美子 鈴木達央 福山潤 三木眞一郎 kuroko no basket kurokos basketball 幻影籃球王 kuroko no basuke 黑子的籃球 黒子のバスケ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-duyen-ma', 'Tình Người Duyên Ma', 'Pee Mak', 'https://phimimg.com/upload/vod/20241101-1/f887c5259b957e37174fffdd819711c9.jpg', 'https://phimimg.com/upload/vod/20241101-1/9f233755f2ae17281d39667101da0a9a.jpg', '<p>Tưởng kinh dị nhưng lại hài không tưởng, Tình Người Duyên Ma đã tạo ra cú nổ lớn tại khu vực Châu Á nói chung và Việt Nam nói riêng. Dù mang yếu tố hài pha lẫn liêu trai, nhưng bộ phim vẫn đọng lại trong lòng khán giả sau khi xem xong bởi những chi tiết nhân văn của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mario Maurer","avatar":""},{"name":"Davika Hoorne","avatar":""},{"name":"Nattapong Chartpong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Pee Mak Phra Kanong","พี่มาก..พระโขนง","피막","淒厲人妻"]', 1784690324460);
