INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-toan-tu-tuong-kinh', 'Thần Toán Tử Tưởng Kính', 'Inn On Fire', 'https://phimimg.com/upload/vod/20241031-1/5b4ec6b5ca9ff6ac09b18390588b67f5.jpg', 'https://phimimg.com/upload/vod/20241031-1/4f2cd4bac1e0f6b9799858529183e73e.jpg', '<p>Hảo hán Lương Sơn tử thương ly tán, Tưởng Kính mang thân trọng thương được bà chủ quán rượu giúp đỡ và che giấu thân phận. Nhưng nhìn bá tánh rơi vào cảnh nước sôi lửa bỏng, tấm lòng muốn hành hiệp trượng nghĩa của anh từ đó khơi dậy lần nữa.</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Siêu","avatar":""},{"name":"Ngôn Kiệt","avatar":""},{"name":"Trương Dịch Mộc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["割爱"]', 1784690324460);
