INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-toan-tu-tuong-kinh', 'Thần Toán Tử Tưởng Kính', 'Inn On Fire', 'thần toán tử tưởng kính inn on fire vương siêu ngôn kiệt trương dịch mộc 割爱', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-trinh-truyen-ky', 'Lục Trinh Truyền Kỳ', 'Legend of Lu Zhen', 'https://phimimg.com/upload/vod/20241021-1/7c7ece1f81f4b13676bb5f2b7bc4d02f.jpg', 'https://phimimg.com/upload/vod/20241021-1/fb1688ceae4bf3bcf10b55f69d52e796.jpg', '<p>Lục Trinh thời Bắc Tề xuất thân gia đình thương nhân, mồ côi mẹ. Từ nhỏ, nàng lương thiện thông minh, nhưng vì giúp đỡ công việc làm ăn của cha nên bị mẹ kế ganh ghét, tìm cách hãm hại, thành ra cha mất nhà tan. Để trốn khỏi sự truy sát của mẹ kế, nàng dự tuyển tú nữ và nhập cung. Giữa chốn thâm cung, Lục Trinh rất cực khổ, cố gắng, nhờ thông tuệ mà làm đến chức nữ quan. Và sự kiên nhẫn, lương thiện của nàng cũng đã khiến thái tử Cao Trạm động lòng, nhưng mối tình gặp nhiều trắc trở bởi thân phận địa vị, sự đố kị, kẻ giết mẹ thái tử là Lâu thái hậu cùng những âm mưu quỷ kế, ái hận tình thù đều trút lên đầu Lục Trinh. Cuối cùng, nhờ sự dũng cảm và trí tuệ, Lục Trinh đã giúp thái tử vượt qua hàng loạt âm mưu, hành động tranh quyền đoạt vị của gia tộc Lâu thái hậu. Giúp thái tử lên ngôi, song vận mệnh khiến Cao Trạm không thể cho nàng danh phận. Nàng “gả” cho chính trị, phò tá ấu đế, trở thành nữ tướng duy nhất trong lịch sử Trung Hoa.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 7, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"赵丽颖","avatar":""},{"name":"陳曉","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Qiao Renliang","avatar":""},{"name":"Tang Yixin","avatar":""},{"name":"Leanne Liu","avatar":""},{"name":"Maggie Cheung Hoh-Yee","avatar":""},{"name":"Emma Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Lùzhēn Chuánqí","陸貞傳奇","女相","女相·陆贞传奇","Female Prime Minister","陆贞传奇"]', 1784690324460);
