INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oanh-thien-loi-lang-chan', 'Oanh Thiên Lôi Lăng Chấn', 'Cannon Maker', 'https://phimimg.com/upload/vod/20241020-1/1470b2925482dd535241ebcdc11463f4.jpg', 'https://phimimg.com/upload/vod/20241020-1/46fe5aec10c90e97af501a674937d1fb.jpg', '<p>Với những chiến công của mình, Lăng Chấn trở thành trọng thần, được hoàng thượng đặc biệt chú ý. Nhưng rồi chính bởi vòng xoáy quyền lực trong triều đã giáng bao tai họa xuống cuộc đời Lăng Chấn.</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Minh Kiện","avatar":""},{"name":"Triệu Tiểu Duệ","avatar":""},{"name":"Cao Du","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Revanche - Ti ucciderò","把哀伤留给复仇","维也纳复仇","La revancha","Revanche"]', 1784690324460);
