INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-chi-hoa-va-thiet-ty-bac', 'Nhất Chi Hoa Và Thiết Tý Bác', 'The Deathsmen', 'https://phimimg.com/upload/vod/20241020-1/dad7550f94043e71be3db056186b2200.jpg', 'https://phimimg.com/upload/vod/20241020-1/53c401f12a50f569f020de17e7dd75eb.jpg', '<p>Thái Khánh cứ nghĩ sẽ sống an ổn hết đời với chức vụ cai quản lao thành. Cho đến một ngày, sự xuất hiện của &quot;kẻ tạo phản&quot; Lư Tuấn Nghĩa đã làm cuộc đời của Thái Khánh thay đổi sang con đường khác.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hác Bách Kiệt","avatar":""},{"name":"Điền Vũ Tình","avatar":""},{"name":"Dương Phong Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Služio sam engleskog kralja","Tarjoilin Englannin kuninkaalle","英国王給仕人に乾杯！","Jeg har betjent kongen av England","Eu Servi o Rei de Inglaterra","În slujba regelui Angliei","Stregel sem angleškemu kralju","Obsluhoval jsem anglického krále"]', 1784690324460);
