INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-the-ma-vuong-phan-thuy', 'Hỗn Thế Ma Vương Phàn Thụy', 'The Devil Incarnate', 'https://phimimg.com/upload/vod/20241016-1/3352960770b80f1dfe5b2191ede9188a.jpg', 'https://phimimg.com/upload/vod/20241016-1/9020a380d8fa6a2ef8788ab6053123c3.jpg', '<p>Phàn Thụy cướp bản đồ kho báu của triều đình để làm lễ vật đầu quân Lương Sơn. Trong lúc đó, Lương Sơn Công Tôn Thắng cũng đến giải cứu nghĩa sĩ Nguyên Hựu Đảng nhưng đã bị Phàn Thụy đi trước một bước. Gặp được hảo hán Lương Sơn, Phàn Thụy vui mừng trao tặng bản đồ. Nhưng sự thật bất ngờ khiến cả hai đều không lường trước được.</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lữ Hải Hoa","avatar":""},{"name":"Trương Kiến Hải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Devil Incarnate","混世魔王樊瑞"]', 1784690324460);
