INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hon-tren-song-chaophraya', 'Hoàng Hôn Trên Sông Chaophraya', 'Sunset At Chaophraya', 'https://phimimg.com/upload/vod/20241016-1/58154f411519d00afefed9bfeec68d8d.jpg', 'https://phimimg.com/upload/vod/20241016-1/7ba488c988f79a2997f26bd167ecd337.jpg', '<p>Lấy bối cảnh Thế chiến 2 tại Thái Lan, chàng lính Nhật Kobori đem lòng yêu cô gái Thái Ang Angumumalin. Anh mang trong mình tinh thần phụng sự đất nước nhưng con tim anh lại dần hướng theo tiếng gọi của thứ tình cảm oan nghiệt này.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sukrit Wisetkaew","avatar":""},{"name":"Noona Nuengthida Sophon","avatar":""},{"name":"Puri Hiranprueck","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Koo Kum","Khu Kam","Sunset Over the Killing Fields","Sunset at Chaophraya","คู่กรรม"]', 1784690324460);
