INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dao-quan-thang', 'Đại Đao Quan Thắng', 'Loyal Swordman', 'https://phimimg.com/upload/vod/20241016-1/187dec473637232459f834fb398565f4.jpg', 'https://phimimg.com/upload/vod/20241016-1/7eed29ccb20b4f1a4507c3db95e8f96a.jpg', '<p>Vì cái chết của con trai, Thái Kinh trút mọi sự tức giận lên Quan Thắng, hạ lệnh cho Quan Thắng công đánh Lương Sơn, thực ra là muốn dồn anh vào chỗ chết. Binh mã và lương khô mang theo không đủ để tác chiến, đánh Lương Sơn rõ ràng là một con đường chết. Quan Thắng rốt cuộc phải làm thế nào? Cố thủ hay hồi kinh?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Na Gia Uy","avatar":""},{"name":"Thái Điệp","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["笑傲江湖"]', 1784690324460);
