INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thi-cong-ky-an', 'Tân Thi Công Kỳ Án', 'Chinese Sherlock Shi', 'https://phimimg.com/upload/vod/20241007-1/2fc2ca9a57884b62801f1704703001f8.jpg', 'https://phimimg.com/upload/vod/20241007-1/6f181d665f3d4bfd8fd851c336d2c35b.jpg', '<p>Tân Thi Công Kỳ Án kề về nhân vật chính là Thi Sĩ Luân là một vị quan thanh liêm chính trực, ông nổi danh là người anh minh, chính trực, không sợ bất cứ quyền lực lớn. Ông là con trai vị tướng lớn trong triều của thời Khang Hy. Nhờ tài năng, như một vị bao thanh thiên thứ 2 của dân, ông làm quan 5 năm sau đó được bổ nhiệm chức Tri phủ Dương Châu, ông chăm lo cho người dân nên được dân dan gọi là Thi Công.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Minh","avatar":""},{"name":"Quách Chân Nghê","avatar":""},{"name":"Triệu Cẩm Đạo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["施公案","新施公案"]', 1784690324460);
