INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-5', 'Gia Đình Hiện Đại (Phần 5)', 'Modern Family (Season 5)', 'https://phimimg.com/upload/vod/20241001-1/6a05d6643f0fe0b05bd126995bbf73d0.jpg', 'https://phimimg.com/upload/vod/20241001-1/54b61898da244f9e5edbeb9b5207d766.jpg', '<p>Tiếng chuông đám cưới đang vang lên trong mùa thứ năm của Gia đình hiện đại. Khi Cam và Mitchell tranh cãi về kế hoạch cho ngày trọng đại của họ, những người còn lại trong gia đình phải toàn lực thích nghi với công việc mới, trường học mới và một bảo mẫu nam mới. Có những thảm họa trông trẻ, một ngày kỷ niệm để ăn mừng, sự ràng buộc sai lầm giữa nam giới và mọi thứ, từ ván bài ăn tiền cao cho đến bố mẹ chồng quá mực bảo trọng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324460);
