INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-hien-dai-phan-5', 'Gia Đình Hiện Đại (Phần 5)', 'Modern Family (Season 5)', 'gia đình hiện đại (phần 5) modern family (season 5) ed o''neill sofía vergara julie bowen ty burrell jesse tyler ferguson eric stonestreet sarah hyland ariel winter nolan gould rico rodriguez familja moderne съвременно семейство modern family famille moderne famille moderne egy rém modern család משפחה מודרנית modernā amerikāņu ģimene família moderna американская семейка عائلة عصرية сучасна сім’я a modern farewell', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-vong-thuong-luu-2013', 'Khát Vọng Thượng Lưu', 'I Summon You Gold', 'https://phimimg.com/upload/vod/20240927-1/3db373459d8369c03a2aa1e43fa62e7c.jpg', 'https://phimimg.com/upload/vod/20240927-1/9ec1ec994d5e57544905670168ed2520.jpg', '<p>Jung Mong-hee và Son Yoo-na là hai chị em sinh đôi nhưng được hai gia đình khác nhau nhận nuôi. Mong-hee là một cô gái bán trang sức dạo vui vẻ và chăm chỉ, có mơ ước được trở thành nhà thiết kế trang sức. Trong khi đó, Yoo-na lại là cô tiểu thư lạnh lùng, con dâu cả của một nhà tài phiệt giàu có ở phố Cheongdam-dong và có bố mẹ là tỷ phú đang định cư bên Hoa Kỳ. Sau một thời gian chung sống không hòa hợp, Yoo-na quyết định ly hôn với chồng là Park Hyun-soo. Gia đình của Hyun-soo hiện là chủ của một công ty trang sức lớn ở Hàn Quốc. Do là con trai trưởng, anh được gia đình kỳ vọng sẽ trở thành người thừa kế của công ty. Tuy nhiên, em trai của Hyun-soo là Hyun-joon lại muốn được ngồi vào chiếc ghế CEO đó. Do vậy, Hyun-joon đã cùng với vợ của mình là Min Seung-eun, một nhà thiết kế trang sức nổi tiếng, lập ra nhiều kế hoạch nhằm tranh giành quyền thừa kế công ty. Khi vô tình gặp được Mong-hee, Hyun-soo đã nhờ cô giả làm người vợ đã ly hôn của mình. Cũng từ đó, vô số các tình huống hài hước, dở khóc dở cười nảy sinh, gắn kết cả hai người lại với nhau. Cho đến một ngày, Hyun-soo nhận ra rằng tình yêu và hạnh phúc đã lại một lần nữa mỉm cười với anh.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"연정훈","avatar":""},{"name":"한지혜","avatar":""},{"name":"백진희","avatar":""},{"name":"박서준","avatar":""},{"name":"김형준","avatar":""},{"name":"반효정","avatar":""},{"name":"김지영","avatar":""},{"name":"금보라","avatar":""},{"name":"최명길","avatar":""},{"name":"김다현","avatar":""},{"name":"이태성","avatar":""},{"name":"이수경","avatar":""},{"name":"한보름","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Geum Nawara, Ddookddak!","I Summon You, Gold","Gold, Appear!","금 나와라, 뚝딱!"]', 1784690324460);
