INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khat-vong-thuong-luu-2013', 'Khát Vọng Thượng Lưu', 'I Summon You Gold', 'khát vọng thượng lưu i summon you gold 연정훈 한지혜 백진희 박서준 김형준 반효정 김지영 금보라 최명길 김다현 이태성 이수경 한보름 geum nawara, ddookddak! i summon you, gold gold, appear! 금 나와라, 뚝딱!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-me-that-tuyet', 'Con Gái Mẹ Thật Tuyệt', 'You Are The Best!', 'https://phimimg.com/upload/vod/20240924-1/4e86bf9fd725f6b2914bc920d156abec.jpg', 'https://phimimg.com/upload/vod/20240924-1/1f6252260a8f887722ce7b4a8792d9f6.jpg', '<p>Chật vật với công việc bán thời gian sau khi tốt nghiệp, cô gái trẻ Soon Shin (nữ ca sĩ IU đóng) không may rơi vào bẫy của tay lừa đảo mạo danh công ty giải trí. Không những mất số tiền lớn vì nhẹ dạ, Soon Shin còn phải đối mặt nỗi đau khôn cùng khi cha cô đột ngột qua đời bởi tai nạn giao thông. Sau biến cố ấy, mẹ Soon Shin phải nhận làm lao công để cáng đáng gia đình và phụ cô trả nợ. Trong lúc rối bời, Soon Shin bất ngờ nhận được lời đề nghị đào tạo trở thành diễn viên từ chàng giám đốc Joon Ho (Jo Jung Suk đóng). Do muốn chứng tỏ trước bạn gái cũ, Joon Ho quyết định mạo hiểm lên kế hoạch “biến vịt hóa thiên nga” khi chọn Soon Shin - một người không tài năng, không nhan sắc để “nhào nặn” thành ngôi sao màn ảnh. Còn Soon Shin vì không muốn mẹ tiếp tục khổ sở vì mình nên đã nhắm mắt gật đầu bước vào hành trình “lột xác” chưa rõ tương lai.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 6, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"아이유","avatar":""},{"name":"조정석","avatar":""},{"name":"고두심","avatar":""},{"name":"이미숙","avatar":""},{"name":"유인나","avatar":""},{"name":"정우","avatar":""},{"name":"이지훈","avatar":""},{"name":"김갑수","avatar":""},{"name":"이응경","avatar":""},{"name":"고주원","avatar":""},{"name":"Bae Geu-rin","avatar":""},{"name":"손태영","avatar":""},{"name":"이지훈","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Choegoda Lee Soon-shin","ลีซุนชิน ครอบครัวนี้มีรัก","Lee Soon Shin is the Best","The Best Lee Soon-shin","You''re the Best, Lee Soon Shin","최고다 이순신"]', 1784690324460);
