INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-gai-me-that-tuyet', 'Con Gái Mẹ Thật Tuyệt', 'You Are The Best!', 'con gái mẹ thật tuyệt you are the best! 아이유 조정석 고두심 이미숙 유인나 정우 이지훈 김갑수 이응경 고주원 bae geu-rin 손태영 이지훈 choegoda lee soon-shin ลีซุนชิน ครอบครัวนี้มีรัก lee soon shin is the best the best lee soon-shin you''re the best, lee soon shin 최고다 이순신', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-thua-ke', 'Những Người Thừa Kế', 'The Heirs', 'https://phimimg.com/upload/vod/20240920-1/e0b50619ce00cbab16ff503e9f70ef75.jpg', 'https://phimimg.com/upload/vod/20240920-1/5560351829007f6352ac8f1377bdbf8a.jpg', '<p>The Heirs được biên kịch bởi Kim Eun Sook, nhà biên kịch nổi tiếng nhất Hàn Quốc, bộ phim bị giới làm phim trước đó phàn nàn vì đã thu hút quá nhiều ngôi sao nổi tiếng của họ. Nội dung của The Heirs nói về tình yêu, cuộc sống cùng với những câu chuyện xoay quanh những người trẻ còn đang trên ghế nhà trường.

Kim Tan là người thừa kế của tập đoàn Empire hùng mạnh. Với tính chất luôn kiêu ngạo và chỉ biết đến bản thân mình, tuy nhiên anh lại luôn bị xem là cái bóng của người anh cùng cha khác mẹ Kim Won. Lấy mô típ quen thuộc là câu chuyện về hoàng tử - Lọ Lem, nhiều khán giả kỳ vọng Kim Eun Sook sẽ mang tới nét mới cho The Heirs lần này.</p>', 'Full', 1, 'series', 'completed', 10, 2013, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"박신혜","avatar":""},{"name":"이민호","avatar":""},{"name":"김우빈","avatar":""},{"name":"김지원","avatar":""},{"name":"강민혁","avatar":""},{"name":"최진혁","avatar":""},{"name":"정수정","avatar":""},{"name":"강하늘","avatar":""},{"name":"박형식","avatar":""},{"name":"Choi Tae-hwan","avatar":""},{"name":"Jeon Soo-jin","avatar":""},{"name":"Hwang Bo-Mi","avatar":""},{"name":"Jo Yoon-woo","avatar":""},{"name":"Yang Seung-Pil","avatar":""},{"name":"정동환","avatar":""},{"name":"김미경","avatar":""},{"name":"최진호","avatar":""},{"name":"최원영","avatar":""},{"name":"임주은","avatar":""},{"name":"김성령","avatar":""},{"name":"박준금","avatar":""},{"name":"서이숙","avatar":""},{"name":"이연경","avatar":""},{"name":"정원중","avatar":""},{"name":"라미란","avatar":""},{"name":"최은경","avatar":""},{"name":"Baek Seung-hyeon","avatar":""},{"name":"김승욱","avatar":""},{"name":"Yoon Son-ha","avatar":""},{"name":"Moon Ah-ram","avatar":""},{"name":"정가람","avatar":""},{"name":"Chanwoo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["继承者们","وارثان","相続者たち","Souzokushatachi","왕관을 쓰려는자, 그무게를 견뎌라 - 상속자들","Wangkwaneul Sseuryeoneunja, Geumoogereul Gyeondyeora - Sangsokjadeul","Sangsokjadeul","Sangsogjadeul","繼承者們","The Inheritors","The One Trying to Wear the Crown, Withstands the Weight - The Heirs","Inheritors","The Heirs","상속자들"]', 1784690324460);
