INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-nguoi-thua-ke', 'Những Người Thừa Kế', 'The Heirs', 'những người thừa kế the heirs 박신혜 이민호 김우빈 김지원 강민혁 최진혁 정수정 강하늘 박형식 choi tae-hwan jeon soo-jin hwang bo-mi jo yoon-woo yang seung-pil 정동환 김미경 최진호 최원영 임주은 김성령 박준금 서이숙 이연경 정원중 라미란 최은경 baek seung-hyeon 김승욱 yoon son-ha moon ah-ram 정가람 chanwoo 继承者们 وارثان 相続者たち souzokushatachi 왕관을 쓰려는자, 그무게를 견뎌라 - 상속자들 wangkwaneul sseuryeoneunja, geumoogereul gyeondyeora - sangsokjadeul sangsokjadeul sangsogjadeul 繼承者們 the inheritors the one trying to wear the crown, withstands the weight - the heirs inheritors the heirs 상속자들', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-iris-ii', 'Mật Danh IRIS II', 'Iris II', 'https://phimimg.com/upload/vod/20240920-1/76002694986560c6bd5606869766f138.jpg', 'https://phimimg.com/upload/vod/20240920-1/7222a3cb912eec7cd71f0e3a283dc66b.jpg', '<p>Câu chuyện diễn ra vào thời điểm ba năm sau cái chết của Hyun Joon (nhân vật do Lee Byung Hun thủ vai) ở phần 1. Bộ phim sẽ tiết lộ những bí ẩn xung quanh cái chết của Hyun Joo cùng với Baek San – người đã bị bắt vì đã hoạt động bí mật trong tổ chứ IRIS và phác thảo chân dung của Ms.Black – người điều khiển mọi hoạt động thông qua Baek San. Bộ phim cũng sẽ là cuộc chiến của những đặc vụ NSS chống lại IRIS – tổ chức ngày càng lớn mạnh và càng khó để phá hủy với đặc vụ Yoo Gun (Jang Hyuk) – lãnh đạo của đội NSS TF – A. Trong khi đang chiến đấu chống lại Baek San (Kim Young Chul), Yoo Gun lại bị cuốn vào một vụ án làm thay đổi số phận của anh mãi mãi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장혁","avatar":""},{"name":"이범수","avatar":""},{"name":"이정길","avatar":""},{"name":"이다해","avatar":""},{"name":"김영철","avatar":""},{"name":"윤두준","avatar":""},{"name":"김승우","avatar":""},{"name":"이준","avatar":""},{"name":"백성현","avatar":""},{"name":"윤소이","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"윤주상","avatar":""},{"name":"김소연","avatar":""},{"name":"임수향","avatar":""},{"name":"이보희","avatar":""},{"name":"Kang Shin-hyo","avatar":""},{"name":"오연수","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["아이리스 2","아이리스 2: 뉴제너레이션","Iris II: New Generation","Iris 2","Mật Danh IRIS II","아이리스2"]', 1784690324460);
