INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-danh-iris-ii', 'Mật Danh IRIS II', 'Iris II', 'mật danh iris ii iris ii 장혁 이범수 이정길 이다해 김영철 윤두준 김승우 이준 백성현 윤소이 david lee mcinnis 윤주상 김소연 임수향 이보희 kang shin-hyo 오연수 아이리스 2 아이리스 2: 뉴제너레이션 iris ii: new generation iris 2 mật danh iris ii 아이리스2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-dai-chien', 'Siêu Đại Chiến', 'Pacific Rim', 'https://phimimg.com/upload/vod/20240920-1/c2e5d3840a336d6fff9953acd7b23268.jpg', 'https://phimimg.com/upload/vod/20240920-1/11d7c08ec38fbeffec272f6b41d232b4.jpg', '<p>Một bộ phim hấp dẫn không thể bỏ qua khi con người phải chiến đấu chống lại những quái vật đến từ kẽ nứt của Thái Bình Dương mang tên gọi Kaiju. Chúng đang đe dọa hủy diệt thế giới loài người khi con người gần như thất bại hoàn toàn trước sức mạnh của lũ quái khổng lồ. &nbsp;Để tiêu diệt những sinh vật này, một loại vũ khí đặc biệt đã được chế tạo: Những robot khổng lồ, được gọi là Jeager. Được điều khiển đồng thời bởi hai phi công, tâm trí của họ được khóa lại trong một cầu nối thần kinh. Nhưng những robot này thậm chí vẫn không thể nào đối chọi lại được lũ quái vật kia. &nbsp;Lực lượng phòng vệ của loài người không còn lựa chọn nào khác buộc phải ủy thác tất cả vào hai người hùng mà chẳng ai ngờ tới: Một cựu phi công hay gây rắc rối và một phi công thực tập, còn chưa được sát hạch. Họ cùng phối hợp điều khiển một Jeager từng là huyền thoại nhưng nay đã lỗi thời. Họ trở thành hy vọng cuối cùng của nhân loại trước bờ vực diệt vong...</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Charlie Hunnam","avatar":""},{"name":"菊地凛子","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Robert Kazinsky","avatar":""},{"name":"Robert Maillet","avatar":""},{"name":"Heather Doerksen","avatar":""},{"name":"Larry Joe Campbell","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Diego Klattenhoff","avatar":""},{"name":"Santiago Segura","avatar":""},{"name":"Jane Watson","avatar":""},{"name":"Jung-Yul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Titanes del pacifico","Pacific Rim 1","퍼시픽림","环太平洋","Το Δαχτυλίδι της Φωτιάς","悍戰太平洋","Vaikse ookeani võitlus","Siêu Đại Chiến Thái Bình Dương","Pacific.Rim","Pacific Rim"]', 1784690324460);
