INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-dai-chien', 'Siêu Đại Chiến', 'Pacific Rim', 'siêu đại chiến pacific rim charlie hunnam 菊地凛子 idris elba max martini clifton collins jr. ron perlman charlie day burn gorman robert kazinsky robert maillet heather doerksen larry joe campbell brad william henke diego klattenhoff santiago segura jane watson jung-yul titanes del pacifico pacific rim 1 퍼시픽림 环太平洋 το δαχτυλίδι της φωτιάς 悍戰太平洋 vaikse ookeani võitlus siêu đại chiến thái bình dương pacific.rim pacific rim', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-lua-2013', 'Bão Lửa', 'Firestorm', 'https://phimimg.com/upload/vod/20240918-1/cbebdaebb3eb772c0ec34f342cd81f6a.jpg', 'https://phimimg.com/upload/vod/20240918-1/66c83cc23c3217865ce5c40a74fcbd16.jpg', '<p>Bão lửa kể về cuộc săn lùng băng nhóm tội phạm có tổ chức, cầm đầu bởi tên trùm khét tiếng: Cho Nam (Hồ Quân). Chúng đã thực hiện trót lọt phi vụ cướp xe bọc thép ngay giữa ban ngày, trước sự chứng kiến của người dân. Điều này gây ra sức ép và bị xem là sự sỉ nhục đối với lực lượng cảnh sát. Lui Ming Chit (Lưu Đức Hoa), thanh tra nổi tiếng sắt đá, rất hận tên trùm Nam và đồng bọn. Anh quyết tiêu diệt triệt để bọn tội phạm làm nguy hại đến cuộc sống của người dân. Nhưng anh sớm hiểu ra sự thật phũ phàng rằng, tất cả các chiến thuật thông thường của cảnh sát đều bị vô hiệu hóa. Để bắt lũ tội phạm đặc biệt này đòi hỏi một cách thực thi công lý đặc biệt, thậm chí phải vứt bỏ tôn chỉ đạo đức của bản thân.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"劉德華","avatar":""},{"name":"林家棟","avatar":""},{"name":"姚晨","avatar":""},{"name":"胡军","avatar":""},{"name":"呂良偉","avatar":""},{"name":"Jacqueline Chan","avatar":""},{"name":"姜皓文","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Oscar Leung","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Sammy Hung","avatar":""},{"name":"陳肥","avatar":""},{"name":"黃智賢","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"張兆輝","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Edward Chui Wai-Tung","avatar":""},{"name":"Hiro Hayama","avatar":""},{"name":"Vincent Sze","avatar":""},{"name":"Bob Lam","avatar":""},{"name":"Bonnie Xian","avatar":""},{"name":"Wong Ch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Fēngbào","Fengbao","Firestorm","ปิดเมืองล่าโจร","风暴","風暴"]', 1784690324460);
