INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-ke-doan-ket', 'Mẹ Kế: Đoạn Kết', 'Jan Dara: The Finale', 'https://phimimg.com/upload/vod/20231117-1/a1da3f151b34277117356198b798cd43.jpg', 'https://phimimg.com/upload/vod/20231117-1/f51e7a9a590fe207677d78b61cf2d279.jpg', '<p>Jan Dara trở lại Bangkok để trả thù Wisnan, người đàn ông đã biến cuộc đời anh thành địa ngục trần gian. Ngọn lửa báo thù thiêu rụi anh ta đến mức anh ta trở thành người đàn ông mà anh ta ghét suốt đời. Jan tiếp tục đi vào mặt tối. Anh ấy muốn nhìn thấy những người đã đối xử tệ với anh ấy phải chịu đựng.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mario Maurer","avatar":""},{"name":"Chaiyapol Pupart","avatar":""},{"name":"Sakrat Ruekthamrong","avatar":""},{"name":"Bongkoj Khongmalai","avatar":""},{"name":"Rhatha Phongam","avatar":""},{"name":"Shou Nishino","avatar":""},{"name":"Savika Chaiyadej","avatar":""},{"name":"Nut Devahastin Na Ayutthaya","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"Chudapha Chantakett","avatar":""},{"name":"Thaweesak Alexander Thananan","avatar":""},{"name":"Ruangsak Loychusak","avatar":""},{"name":"Phongsiree Bunl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324460);
