INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('legendary-tomb-of-the-dragon', 'Legendary: Tomb of the Dragon', 'Legendary: Tomb of the Dragon', 'https://phimimg.com/upload/vod/20231109-1/5b337132f79d982e10563f6f6bd1b147.jpg', 'https://phimimg.com/upload/vod/20231109-1/ea0f2b68a17a61082b0e71c6955f01f3.jpg', '<p>Travis và nhóm của anh ấy đến Trung Quốc để tìm kiếm thứ không tồn tại... nhiệm vụ của họ là bắt một Cryptid đang tàn phá một ngôi làng hẻo lánh và họ cần phải làm điều này trước khi nó bị giết bởi Harker, kẻ treo thưởng huyền thoại thợ săn.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"James Lance","avatar":""},{"name":"Lydia Leonard","avatar":""},{"name":"Chengxuan Li","avatar":""},{"name":"Geng Le","avatar":""},{"name":"Murray Clive Walker","avatar":""},{"name":"Viktor Sobtchak","avatar":""},{"name":"Tom Austen","avatar":""},{"name":"David Thomas Jenkins","avatar":""},{"name":"Li Shengye","avatar":""},{"name":"Yang Caiyu","avatar":""},{"name":"Paul Philip Clark","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324460);
