INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('legendary-tomb-of-the-dragon', 'Legendary: Tomb of the Dragon', 'Legendary: Tomb of the Dragon', 'legendary: tomb of the dragon legendary: tomb of the dragon scott adkins dolph lundgren huang yi james lance lydia leonard chengxuan li geng le murray clive walker viktor sobtchak tom austen david thomas jenkins li shengye yang caiyu paul philip clark ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-phat', 'Lửa Phật', 'Once Upon a Time in Vietnam', 'https://phimimg.com/upload/vod/20231108-1/33a2df75de1ab7ffb1f5b805ac2b4142.jpg', 'https://phimimg.com/upload/vod/20231108-1/22b67c302179f2672bbee97ee96aea55.jpg', '<p>Chuyện phim bắt đầu từ một ngôi làng nhỏ, nơi những người dân vô tội đang bị gã giang hồ khét tiếng và đồng bọn của hắn ra sức quấy rối và ức hiếp. Cái gai trong mắt của chúng chính là Hiền – một người thợ làm bánh trong làng. Trước sự hống hách của bọn giang hồ, Hiền cùng với người vợ xinh đẹp của mình đã kêu gọi người dân trong làng đứng lên phản kháng. Cùng thời điểm đó, Đạo - một cao nhân bí ẩn đã đến và chứng kiến cuộc chiến không cân sức này. Đạo đã đứng về phía dân làng. Một cuộc quyết chiến nổ ra và quá khứ bí ẩn của Đạo cũng dần dần được hé lộ...</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Dustin Nguyen","avatar":""},{"name":"Roger Yuan","avatar":""},{"name":"Veronica Ngo","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Ngọc Diệp","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Phi Thanh Vân","avatar":""},{"name":"Bùi Văn Hải","avatar":""},{"name":"Nguyễn Hậu","avatar":""},{"name":"Quang Minh Do","avatar":""},{"name":"Jason Ninh Cao","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Diễm My 9x","avatar":""},{"name":"Thanh Thủy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324460);
