INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-nam-ay', 'Mùa Hè Năm Ấy', 'Last Summer', 'https://phimimg.com/upload/vod/20231103-1/6941eb2336e33f7e5e854423d78109b2.jpg', 'https://phimimg.com/upload/vod/20231103-1/fa96a4e8acc207114c8d55857588ec15.jpg', '<p>Bộ phim lấy bối cảnh Thế chiến 2 ở Thái Lan, một người lính Nhật Bản tên là Kobori đem lòng yêu cô gái Thái Lan Ang Angumumalin. Kobori sẵn sàng làm mọi việc để phụng sự tổ quốc nhưng anh sẽ phải đánh đổi tất cả để cứu lấy tình yêu của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel Pettit","avatar":""},{"name":"Sean Rose","avatar":""},{"name":"Roben R. Sullivant","avatar":""},{"name":"Byron Taylor","avatar":""},{"name":"Deb Lewis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324460);
