INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-cua-nguoi-chet', 'Hiệp Sĩ Của Người Chết', 'Knight of the Dead', 'https://phimimg.com/upload/vod/20240910-1/eaa4100b294fbdfe2ac97c3ece7ff662.jpg', 'https://phimimg.com/upload/vod/20231103-1/c2c052b4fd2126f6ac0ab68d2849354d.jpg', '<p>Hiệp Sĩ Của Người Chết - Knight Of The Dead xoay quanh hành trình bảo vệ chén thánh của một nhóm hiệp sĩ thập tự chinh. Sau khi bị săn đuổi bởi những kẻ cướp, nhóm hiệp sĩ đã hộ tống chén thánh qua một thung lũng của cái chết, nơi họ phải chiến đấu để có được tự do.</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Feth Greenwood","avatar":""},{"name":"Vivien Vilela","avatar":""},{"name":"Lee Bennett","avatar":""},{"name":"Dylan Jones","avatar":""},{"name":"Alan Calton","avatar":""},{"name":"Jason Beeston","avatar":""},{"name":"George McCluskey","avatar":""},{"name":"Alf Thompson","avatar":""},{"name":"Dennis Carr","avatar":""},{"name":"Eva Morgan","avatar":""},{"name":"Nia Ann","avatar":""},{"name":"Kevin Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324460);
