INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hiep-si-cua-nguoi-chet', 'Hiệp Sĩ Của Người Chết', 'Knight of the Dead', 'hiệp sĩ của người chết knight of the dead feth greenwood vivien vilela lee bennett dylan jones alan calton jason beeston george mccluskey alf thompson dennis carr eva morgan nia ann kevin smith ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tao-thao', 'Tào Tháo', 'Cao Cao', 'https://phimimg.com/upload/vod/20240908-1/2459235a3d17b1615861cb2007d06ece.jpg', 'https://phimimg.com/upload/vod/20240908-1/9f35b229d9236f4402453ae44435e8aa.jpg', '<p>Bộ phim là câu chuyện phim được khai thác dựa trên những tài liệu lịch sử có thật trong lịch sử Trung Hoa về nhân vật Tào Tháo được tái hiện chân thực và một góc nhìn khách quan, toàn diện hơn về nhân vật lịch sử có nhiều chiến tích này. Bộ phim “Tào Tháo”như một biện chứng hùng hồn về tính lịch sử của nhân vật được cho là nhất đại gian hùng trong thời Tam Quốc. Theo lịch sử Tào Tháo là người thủ đoạn, vô tình, máu lạnh. Nhưng ở phim này đạo diễn đã biến Tào Tháo thành người có tình, có nghĩa. Được nhắc đến nhiều nhất là chuyện tình giữa Tào Tháo và Thái Văn Cơ</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 10, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lập Tân","avatar":""},{"name":"Nhạc Hồng","avatar":""},{"name":"Hân Tuyết","avatar":""},{"name":"Lâm Diệu Khả","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324460);
