INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tao-thao', 'Tào Tháo', 'Cao Cao', 'tào tháo cao cao triệu lập tân nhạc hồng hân tuyết lâm diệu khả ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-than-toc', 'Điệp Vụ Thần Tốc', 'Dhoom 3', 'https://phimimg.com/upload/vod/20240905-1/e550dd51f3b995c3e3b312c0b7285118.jpg', 'https://phimimg.com/upload/vod/20240905-1/0ae04078efcb6f98cc16ebe88076707c.jpg', '<p>Dhoom 3 là một bộ phim hành động Ấn Độ của đạo diễn Vijay Krishna Acharya. Cái tên Aamir Khan quá nổi tiếng với Ba Chàng Ngốc sẽ là một sự đảm bảo cho sự hấp dẫn của phim. Năm 1991, Iqbal Khan Haroon (Jackie Shroff) mở một rạp xiếc - The Great Indian Circus ở Chicago nhưng đang trong giai đoạn khó khăn. Ngân hàng của Anderson (Andrew Bicknell) - Western Bank of Chicago - đã cho Iqbal Khan vay tiền, quyết định đóng cửa các rạp xiếc khi ông ta không có khả năng chi trả. Sahir (Siddharth Nigam), con trai của Iqbal Khan, cầu xin Anderson không đóng cửa rạp xiếc nhưng chỉ nhận được cái lắc đầu và cha anh phải tự sát. Và bây giờ là năm 2013, Sahir (Aamir Khan) vẫn chưa quên tên Anderson và có ý định trả thù. Anh ta cướp các chi nhánh của Western Bank of Chicago và để lại tin nhắn tiếng Hin-đu và một mặt nạ chú hề.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Abhishek Bachchan","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Uday Chopra","avatar":""},{"name":"Jackie Shroff","avatar":""},{"name":"Tabrett Bethell","avatar":""},{"name":"Andrew Bicknell","avatar":""},{"name":"Riya Ray","avatar":""},{"name":"Elizabeth Reiners","avatar":""},{"name":"Jacqueline Scislowski","avatar":""},{"name":"Kim DeJesus","avatar":""},{"name":"Parth Suri","avatar":""},{"name":"Michael L. Howard","avatar":""},{"name":"Michael David Hammond","avatar":""},{"name":"Madison Moran","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324460);
