INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-danh-stalingrad', 'Trận Đánh Stalingrad', 'Stalingrad', 'https://phimimg.com/upload/vod/20231103-1/3ee1f1b5c9ce31309b2020430f0dd883.jpg', 'https://phimimg.com/upload/vod/20231103-1/459001e9a1e0238d5d0d26e7c3bec850.jpg', '<p>Stalingrad là trận chiến quan trọng, tạo nên bước ngoặt trong Chiến tranh thế giới thứ 2, hứa hẹn đưa người xem “thâm nhập” sâu vào từng khoảnh khắc lịch sử. Đạo diễn người Nga, Fyodor Bondarchuk, con trai của đạo diễn nổi tiểng đã thực hiện bộ phim Chiến tranh và Hòa bình, sẽ chỉ đạo thực hiện bộ phim về Stalingrad mới này.</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Thomas Kretschmann","avatar":""},{"name":"Yanina Studilina","avatar":""},{"name":"Philippe Reinhardt","avatar":""},{"name":"Heiner Lauterbach","avatar":""},{"name":"Mariya Smolnikova","avatar":""},{"name":"Andrey Smolyakov","avatar":""},{"name":"Oleg Volku","avatar":""},{"name":"Pyotr Fyodorov","avatar":""},{"name":"Sergey Bondarchuk","avatar":""},{"name":"Dmitry Lysenkov","avatar":""},{"name":"Anna von Haebler","avatar":""},{"name":"Mariya Sittel","avatar":""},{"name":"Petar Zekavica","avatar":""},{"name":"Georges Devdariani","avatar":""},{"name":"Oksana B","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
