INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-thanh', 'Ngoại Thành', 'Suburbanite', 'null', 'https://phimimg.com/upload/vod/20231103-1/36f738f829a24c6aaf15cc6be79c1811.jpg', '<p>Một đêm khuya trên đường đi làm về, John ngủ gục trên bánh xe và đánh một người đàn ông. Anh ta mang xác về nhà, hoàn toàn có ý định che đậy nó thì bất ngờ xảy ra chuyện không tưởng, người đàn ông tỉnh dậy. Bây giờ John phải quyết định anh sẽ sẵn sàng đi bao xa để bảo vệ gia đình và bí mật của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Dietrich","avatar":""},{"name":"Susana Gibb","avatar":""},{"name":"Max Hartman","avatar":""},{"name":"Nicole Leigh","avatar":""},{"name":"Teanna McKay","avatar":""},{"name":"Jodie Moore","avatar":""},{"name":"Frank Mosley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324460);
