INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-luther-phan-3', 'Thanh Tra Luther (Phần 3)', 'Luther (Season 3)', 'https://phimimg.com/upload/vod/20240726-1/0feeffdd414901f81bf163432f7435aa.jpg', 'https://phimimg.com/upload/vod/20240726-1/67634ee481b1c478d7a24e2fed92a388.jpg', '<p>Phim Thanh Tra Luther - Luther 2010: Sau 7 tháng tạm đình chỉ để phục vụ công tác điều tra do trong 1 lần đuổi bắt anh đã gây ra cái chết cho 1 tên tội phạm, John Luther trở lại nhiệm vụ. Với sự hỗ trợ của Justin Ripley, anh điều tra một vụ giết người tại nhà, Douglas và Laura Morgan được tìm thấy bởi cô con gái Alice. Sau khi lấy khẩu cung, Luther tin rằng cô đã giết cha mẹ mình. Anh ta không có bằng chứng nào và cảnh sát đã không thể tìm thấy khẩu súng. Alice là một cô gái cực kì thông minh và chuẩn bị sẵn mọi thức để chơi trò chơi tâm lý với anh. Trong khi đó, Luther đang cố gắng sửa chữa mối quan hệ của mình với vợ người vợ đã ly thân của mình. Cô ấy đã gặp người khác và đang bắt đầu 1 mối quan hệ mới.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Michael Smiley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324460);
