INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-tra-luther-phan-3', 'Thanh Tra Luther (Phần 3)', 'Luther (Season 3)', 'thanh tra luther (phần 3) luther (season 3) idris elba dermot crowley michael smiley ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-xa-la', 'Thiên Đường Xa Lạ', 'A Stranger in Paradise', 'https://phimimg.com/upload/vod/20240901-1/6520cd2cae3bd1d5c90e4947d78fd4ff.jpg', 'https://phimimg.com/upload/vod/20231101-1/6a779307f2605c7330823adea2845edf.jpg', '<p>Trên bờ vực trở thành đối tác, cuộc sống của Josh Pratt (Colin Egglesfield) bị đảo lộn khi SEC điều tra người đứng đầu quỹ phòng hộ trị giá hàng tỷ đô la của anh ta về giao dịch nội gián. Bị buộc phải có một “kỳ nghỉ” đúng lúc mà anh ta không bao giờ yêu cầu Josh thấy mình ở Bangkok với cái giá phải trả trên đầu, một người anh em không rõ ràng về mặt đạo đức, người đã thâm nhập sâu vào giới mafia Thái Lan và có xu hướng bị bắn. Thật không may cho Josh, lối thoát duy nhất là từ bỏ thông tin mà anh ấy không biết mình có.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Egglesfield","avatar":""},{"name":"Catalina Sandino Moreno","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Stuart Townsend","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Sonia Couling","avatar":""},{"name":"James With","avatar":""},{"name":"Elina Loukas","avatar":""},{"name":"Jay Acovone","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324460);
