INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-cac-quy-co-phan-1', 'Xin Chào Các Quý Cô (Phần 1)', 'Hello Ladies (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/a390f73a426091a517f6e846601cc2e2.jpg', 'https://phimimg.com/upload/vod/20240808-1/50deb38089d8d0d1c78868e9654c1534.jpg', '<p>Stuart Pritchard là một chàng trai Anh vụng về, quá tự tin đang cố gắng hẹn hò ở Los Angeles – nơi anh ta liên tục cố gắng xâm nhập vào thế giới của những người đẹp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stephen Merchant","avatar":""},{"name":"Christine Woods","avatar":""},{"name":"Nate Torrence","avatar":""},{"name":"Kevin Weisman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324460);
