INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-duong-lat-van-phan-4', 'Đế Chế Đường Lát Ván (Phần 4)', 'Boardwalk Empire (Season 4)', 'https://phimimg.com/upload/vod/20240808-1/f3371ef68668217df7b045b91c48e1b5.jpg', 'https://phimimg.com/upload/vod/20240808-1/1ed12dcce24dd1e00cd78c9ec39e31df.jpg', '<p>Lấy bối cảnh vào năm 1920, tại thành phố Atlantic, ngày bắt đầu quy định việc cấm bán rượu. Và hệ lụy là sự xuất hiện của hàng loạt các băng nhóm tội phạm, chính trị trở thành gangster. Nơi bắt nguồn cảm hứng cho chế độ mafia Mỹ, mà sau này hình thành các huyền thoại mafia nổi tiếng như: Bugsy Siegel, Lucky Luciano, Al Capone Scarface.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Buscemi","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Vincent Piazza","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Paul Sparks","avatar":""},{"name":"Gretchen Mol","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Ben Rosenfield","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
