INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('de-che-duong-lat-van-phan-4', 'Đế Chế Đường Lát Ván (Phần 4)', 'Boardwalk Empire (Season 4)', 'đế chế đường lát ván (phần 4) boardwalk empire (season 4) steve buscemi kelly macdonald michael shannon shea whigham stephen graham vincent piazza michael kenneth williams paul sparks gretchen mol jeffrey wright ben rosenfield ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-su-dai-nao-cong-duong', 'Trạng Sư Đại Náo Công Đường', 'Return Of The Silver Tongue', 'https://phimimg.com/upload/vod/20240802-1/b639ec5f2b889b1139451eeb5974948f.jpg', 'https://phimimg.com/upload/vod/20240802-1/6b8ce627fe9ca6498d4444eebe3b32e3.jpg', '<p>Hương Tứ Duy (Quách Tấn An) mở học đường đề bồi dưỡng các anh tài, trong đó có môn sinh Châu Cúc (Huỳnh Thuý Như) với Tứ Duy vừa là thầy trò vừa là bạn hữu, Châu Cúc tư chất thông minh nhưng đọc sách luôn hiểu một nữa, từ đó thường xuyên dùng sai các thành ngữ. Tứ Duy là một người chính nghĩa, nhận thấy chuyện đời hoang đường và có sự dạy dỗ sâu sắc nên khó ai có thể thay đổi tâm tính của anh, nhưng một dịp tình cờ gặp một người tên Trần Chân Chân (Điền Nhuỵ Ni) lai lịch bất minh nhưng lanh lẹ cơ trí, giỏi tài biện minh, sau đó hai người trở thành hai người trạng sư biện hộ. Phan Kính Toàn (Trương Quốc Cường) nổi tiếng ác bá và con trai hắn-Phan Nhĩ Danh (Lâm Hiểu Phong) luôn coi Tứ Duy và Chân Chân là kẻ thù. Sự thay đổi của Tứ Duy khiến cho người bạn thân của anh là Hạ Hầu Võ (Mạch Trường Thanh) đau lòng thất vọng, bởi vì năm xưa phụ thân của Hầu Võ bị trạng sư Trần Mộng Cát (Lý Thành Xương) vu oan nên chết đi nên anh luôn có thành kiến với những ai là trạng sư, tuy Hầu Võ hiểu dụng ý của Tứ Duy nhưng lại nghi ngờ thân phận bất minh của Chân Chân nên anh ta quyết tâm điều tra. Từ đó vạch ra vụ án an chôn giấu 20 năm trước tái diễn, một tên sát thủ trạng sư máu lạnh xuất hiện, từ đó tin đồn khắp nơi, khiến cho mọi người lo lắng từng ngày...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2013, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Quach Tấn An","avatar":""},{"name":"Điền Nhụy Ni","avatar":""},{"name":"Huỳnh Thúy Như","avatar":""},{"name":"Mạch Trường Thanh","avatar":""},{"name":"Lý Thành Xương","avatar":""},{"name":"Vương Quân Thanh","avatar":""},{"name":"Trương Quốc Cường","avatar":""},{"name":"Lâm Hiểu Phong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324460);
