INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ngao-giang-ho-2013', 'Tiếu Ngạo Giang Hồ', 'Swordsman', 'https://phimimg.com/upload/vod/20240731-1/92db82b92d01530760d55b92a7e57611.jpg', 'https://phimimg.com/upload/vod/20240731-1/41a14435ab09f597c01007420332b588.jpg', '<p>Tiếu Ngạo Giang Hồ là câu chuyện xoay quanh cuộc chiến giữa các phe phái trong võ lâm Trung nguyên để giành được bí kíp võ công . &quot;Tịch tà kiếm phổ&quot; huyền diệu của nhà họ Lâm. Nhân vật chính của &quot;Tiếu ngạo giang hồ&quot; là chàng trai lãng tử Lệnh Hồ Xung - đại đệ tử phái Hoa Sơn, một chàng trai nghĩa hiệp có tính cách lanh lợi, tư chất thông minh khác thường.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2013, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"霍建華","avatar":""},{"name":"袁姍姍","avatar":""},{"name":"陈乔恩","avatar":""},{"name":"陳曉","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Huang Wenhao","avatar":""},{"name":"楊朙娜","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"June Wu","avatar":""},{"name":"張雪迎","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Han Dong","avatar":""},{"name":"Xie Ning","avatar":""},{"name":"張衛健","avatar":""},{"name":"張春仲","avatar":""},{"name":"Zhang Lei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324460);
