INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lang-tu', 'Anh Hùng Lãng Tử', 'Romantic Heroes of the Tang Dynasty', 'https://phimimg.com/upload/vod/20240713-1/35f975d179c3d46ec9be8195be9b5a2b.jpg', 'https://phimimg.com/upload/vod/20240713-1/267a6f4f6daef13479b613757d8533a2.jpg', '<p>Anh Hùng Lãng Tử - Romantic Heroes Of The Tang Dynasty kể về một đội hộ vệ trung thành thời nhà Đường chuyên trừ gian diệt ác, tạo phước cho dân, giúp bá tánh thiên hạ được an cư lạc nghiệp, giữ cho quốc thái dân an, từ đó ngày càng trưởng thành và giúp triều đình dẹp những mối họa hại dân hại nước.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2013, 'Lồng Tiếng', 'FullHD', 'Trung Quốc', 0, '[{"name":"Alex Fong Lik-Sun","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Meng Li","avatar":""},{"name":"Andy Chen","avatar":""},{"name":"Kris Shen","avatar":""},{"name":"Wu Chien-Lien","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324460);
