INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-duc-phat', 'Cuộc đời Đức Phật', 'The Buddha', 'https://phimimg.com/upload/vod/20240609-1/7df85f431c3a46b4b1ca8b5d0aa87153.jpg', 'https://phimimg.com/upload/vod/20240609-1/85dd62e022cacf0ac30ff870d212650c.jpg', '<p>Bộ phim chuyển thể từ sách Đường xưa mây trắng của thầy Thích Nhất Hạnh với kinh phí đầu tư lên đến $120.000.000. Đạo diễn người Ấn Độ đã sang Việt Nam xin ý kiến thầy Thích Nhất Hạnh và có ngõ ý chia sẻ một phần doanh thu của bộ phim cho thầy Thích Nhất Hạnh, tuy nhiên thầy đã từ chối và mong muốn đạo diễn sử dụng nó vào việc giúp đỡ trẻ em ở Ấn Độ.

Bộ phim dài 55 tập miêu tả đầy đủ về cuộc đời Đức Phật từ khi ra đời đến khi đạt tới Giác Ngộ.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 9, 2013, 'Lồng Tiếng', 'HD', 'Ấn Độ', 0, '[{"name":"Himanshu Soni","avatar":""},{"name":"Gungun Uprari","avatar":""},{"name":"Jagat Singh","avatar":""},{"name":"Meghan Jadhav","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324460);
