INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-iris-2-ban-dien-anh', 'Mật Danh Iris 2: Bản Điện Ảnh', 'Iris 2', 'https://phimimg.com/upload/vod/20231023-1/22973746537da3837ee7e694b3591b8e.jpg', 'https://phimimg.com/upload/vod/20231023-1/df8a84754507d4e6fa09632f031ef562.jpg', '<p>Một đội đặc nhiệm an ninh bí mật phải ngăn chặn các sát thủ khủng bố phá hoại một hội nghị hòa bình giữa Triều Tiên và Hàn Quốc.</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Lee Beom-su","avatar":""},{"name":"Im Soo-hyang","avatar":""},{"name":"Lee Da-hae","avatar":""},{"name":"Kim Yeong-cheol","avatar":""},{"name":"Oh Soo-yeon","avatar":""},{"name":"Oh Yeon-soo","avatar":""},{"name":"Kim So-yeon","avatar":""},{"name":"Cha Soon-hyeong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324460);
