INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-sao-dua-anh-toi', 'Vì Sao Đưa Anh Tới', 'My Love From The Star', 'https://phimimg.com/upload/vod/20240118-1/ca6b29b4326b5b347a081d83317e3a10.jpg', 'https://phimimg.com/upload/vod/20240118-1/b5a11f84b1974d47dbd52b77d604cb66.jpg', '<p>Một anh chàng ngoài hành tinh đến Trái Đất từ 400 năm gần như đã có thể trở lại quê nhà. Nhưng khi gặp một nữ diễn viên nổi tiếng, anh đã không còn mong muốn trở về nữa.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Soo Hyun","avatar":""},{"name":"Gianna Jun","avatar":""},{"name":"Park Hae Jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
