INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-canh-sat-ma', 'Đồn Cảnh Sát Ma', 'R.I.P.D.', 'https://phimimg.com/upload/vod/20231026-1/91021773081132f00dce17d0070018f0.jpg', 'https://phimimg.com/upload/vod/20231026-1/44d3d99c297c55e2c3cf34f1280bec37.jpg', '<p>R.I.P.D. kể về Đồn Cảnh Sát Ma chuyên săn lùng những linh hồn tội phạm muốn gây hại cho thế giới con người. Bộ phim xoay quanh bộ đôi cảnh sát, một đã chết 100 năm, một thì vừa mới chết cùng hợp lực chiến đấu. Sau khi bị sát hại, Nick gia nhập R.I.P.D. Anh hợp tác cùng đội quân với những nhiệm vụ cam go phía trước cũng như tìm hiểu thủ phạm đã mưu sát mình.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Stephanie Szostak","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"James Hong","avatar":""},{"name":"Marisa Miller","avatar":""},{"name":"Mike O''Malley","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Larry Joe Campbell","avatar":""},{"name":"Michael Coons","avatar":""},{"name":"Chris Everett","avatar":""},{"name":"Michael Tow","avatar":""},{"name":"Lonnie Farmer","avatar":""},{"name":"Piper Mackenzie Har","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324460);
