INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-1', 'Trại Giam Kiểu Mỹ (Phần 1)', 'Orange Is The New Black (Season 1)', 'https://phimimg.com/upload/vod/20240607-1/b6a87cfc52e0b0143089baa8499e0c79.jpg', 'https://phimimg.com/upload/vod/20240607-1/8b5d93ac35f4084619c45903d14b5322.jpg', '<p>Piper Chapman là một phụ nữ đang có đầy đủ mọi thứ: nhà cửa, công việc và một người chồng chưa cưới. Bỗng một hôm, cô phải vào tù vì dính líu tới vụ buôn ma túy từ mười năm trước, cùng người tình đồng tính trước đây. Piper sẽ phải làm sao để sống sót trong tù, cũng như duy trì được quan hệ với anh.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2013, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pablo Schreiber","avatar":""},{"name":"Asia Kate Dillon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324460);
