INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-than-2013', 'Phân Thân', 'Bilocation', 'https://phimimg.com/upload/vod/20240524-1/11147b20b7f8b09c518f695b636660bb.jpg', 'https://phimimg.com/upload/vod/20240524-1/91d0202911f98a8e91b93205f46fec32.jpg', '<p>Dựa trên cuốn tiểu thuyết kinh dị từng đạt giải thưởng của nhà văn Haruka Hojo, phim do nữ diễn viên Asami Mizukawa đảm nhận vai chính. Mizukawa vào vai Shinobu Takamura 1 phụ nữ bị kết tội làm giả hoá đơn ở siêu thị. Cô biết mình vô tội nhưng vô cùng sốc khi thấy hình ảnh chính mình phạm tội trong đoạn phim quay 10 phút trước đó. Trong quá trình bị giam giữ, Shinobu dần phát hiện 1 bóng ma được sinh ra từ cơ thể cô thông qua hiện tượng “bilocation”.</p><p>Nam ca sĩ Kento Senga từ nhóm nhạc thần tượng Kis-My-Ft2 sẽ thủ vai 1 sinh viên tên Takumi Mitarai, thành viên của biệt đội “Bilocation Club” chuyên bảo vệ mọi người khỏi hiện tượng này. Bên cạnh đó, 1 thực tập sinh khác của nhà Johnny là Sho Takada sẽ vào vai 1 chàng trai trẻ bí ẩn, người luôn che giấu gương mặt thật của mình…</p>', 'Full', 1, 'single', 'completed', 6, 2013, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Asami Mizukawa","avatar":""},{"name":"Kento Senga","avatar":""},{"name":"Sho Takada","avatar":""},{"name":"Kenichi Takitoh","avatar":""},{"name":"Yosuke Asari","avatar":""},{"name":"Wakana Sakai","avatar":""},{"name":"Kosuke Toyohara","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324460);
