INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-quy-cua-da-vinci-phan-1', 'Những Con Quỷ Của Da Vinci (Phần 1)', 'Da Vinci''s Demons (Season 1)', 'https://phimimg.com/upload/vod/20240302-1/fd6fc58aca76f0c941a92ae86e2d753c.jpg', 'https://phimimg.com/upload/vod/20240302-1/05d60314d6fe9add535e5d1d6af71835.jpg', '<p>Trong cái thế giới đầy tăm tối nơi mà niềm tin thì mù quáng còn kiến thức thì lại xa xỉ, đã sản sinh một người đàn ông vĩ đại, người đã chiến đấu để đem lại sự tự do về kiến thức, về hiểu biết cho mọi người. Seri này sẽ kể về cuộc đời và sự nghiệp của Leonardo da Vinci, về những bất công, khổ cực và cả những niềm vui mà một người thiên tài như ông đã trải qua. Ông là một kẻ dị giáo, người chống lại những sai lầm của tôn giáo. Một đội quân bí mật đang cố gắng lật đổ cái xã hội đầy hào nhoáng mà nhơ nhuốc ấy. Một người con trai khao khát tình cảm với người cha của mình. Ông thấy con người mình đang trong một cơn bão được ấp ủ từ nhiều thế kỉ qua. Một cuộc chiến giữa sự thật và dối trá, tôn giáo và lý trí, quá khứ và tương lai...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Riley","avatar":""},{"name":"Elliot Cowan","avatar":""},{"name":"Laura Haddock","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324460);
