INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-viking-saga-the-darkest-day', 'A Viking Saga: The Darkest Day', 'A Viking Saga: The Darkest Day', 'https://phimimg.com/upload/vod/20240228-1/8825b8aa174de71412c38466f8ae2aa8.jpg', 'https://phimimg.com/upload/vod/20240228-1/d36dde64cfa9a453c872c6eded4a6c50.jpg', '<p>Bị cuốn vào một thế giới giết người bạo lực và đẫm máu, Hereward, một tu sĩ mới vào nghề, phải đưa Phúc âm của Lindisfarne - một cuốn sách có vẻ đẹp và sức mạnh to lớn - đến sự an toàn của tu viện Iona, trong khi bị truy đuổi bởi một đội tử thần Viking- quyết tâm bắt giữ nó. Trên đường đến tu viện, anh gặp một kiếm sĩ dũng mãnh và điêu luyện, người đã đáp lại lời cầu nguyện của anh và cống hiến cả cuộc đời để bảo vệ Hereward trong khi anh giao cuốn sách. Giữa cuộc hành trình, họ phải đối mặt với những người Viking sẵn sàng giết người để đạt được thứ họ muốn, khiến Hereward và người bảo vệ của anh phải chịu sự thương xót của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Elen Rhys","avatar":""},{"name":"Mark Lewis Jones","avatar":""},{"name":"Gary Mavers","avatar":""},{"name":"Marc Pickering","avatar":""},{"name":"Michael Jibson","avatar":""},{"name":"Ioan Hefin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324460);
