INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuat-xem-tuong', 'Thuật Xem Tướng', 'The Face Reader', 'https://phimimg.com/upload/vod/20240228-1/d1e9d2bd237b32ff4c0eb61f3701e679.jpg', 'https://phimimg.com/upload/vod/20240228-1/4803b7a720927b78a88104551872cbf6.jpg', '<p>Na Kyung là một người có khả năng thiên tài bẩm sinh về nhận biết con người qua khuôn mặt trong triều đại Joseon. Chính vì vậy, Yeon Hong đã kết hợp với Nae Kyung để nhờ anh xác định ra những kẻ sát nhân. . Với kỹ năng “trời phú” của mình, Nae Kyung nhanh chóng được vua Moonjong chọn làm người thân tín để xác định những kẻ phản bội trong triều đình, những kẻ đang “nhăm nhe” đe doa đến sự an nguy của triều đại Joseon.Tuy nhiên, vua MoonJoong “đột tử” rất bí ẩn. Nae Kyung bị một kẻ đang khao khát chiếm ngôi vua lôi kéo. Mục tiêu của hắn là giết chết người thừa kế sáng giá là Danjong. Để giữ lòng trung thành với vua MoonJoong và bảo vệ vị vua trẻ tương lai, Nae Kyung đã phải bước vào một cuộc đấu tranh quyền lực lớn nhất ...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Song Kang-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
