INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nganh-han-2013', 'Ngạnh Hán', 'The Underdog Knight', 'https://phimimg.com/upload/vod/20240227-1/4fc136853fbcb5fc67c4ef36b80191f4.jpg', 'https://phimimg.com/upload/vod/20240227-1/84a372f4b4db2c05528a357caa60be9c.jpg', '<p>Ngạnh Hán xoay quanh Lão Tam là một lính đặc công lão luyện. Do một lần cứu đồng đội chết đuối, anh bị chứng thiếu oxy trong máu. Chứng bệnh ảnh hưởng tới tâm thần của Lão Tam, khiến anh bị giải ngũ và không còn trí óc lành lặn. Bị ám ảnh bởi những kỹ năng đã được tôi luyện, và chỉ có chú bé điếc làm bạn thân, Lão Tam lang thang trong thành phố, trở thành người bảo vệ công lý kỳ quặc với tài năng võ thuật hơn người...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ye Liu","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Yong You","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324460);
