INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-lai-vang', 'Linh Hồn Lai Vãng', 'Haunter', 'https://phimimg.com/upload/vod/20240227-1/74753a5a61fab44503c4acc21dcfc3d2.jpg', 'https://phimimg.com/upload/vod/20240227-1/017fea4ddc1c82853a580c0247bcb522.jpg', '<p>Một thiếu niên bị mắc kẹt trong một vòng lặp thời gian không hoàn toàn giống nhau mỗi lần. Cô ấy phải khám phá sự thật nhưng hành động của cô ấy có hậu quả đối với bản thân và những người khác.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324460);
