INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-tram-tuoi-treo-qua-cua-so-va-bien-mat', 'Ông Trăm Tuổi Trèo Qua Cửa Sổ Và Biến Mất', 'The 100 Year-Old Man Who Climbed Out The Window And Disappeared', 'https://phimimg.com/upload/vod/20240227-1/1c46c1325181be67941f30f2af84981c.jpg', 'https://phimimg.com/upload/vod/20240227-1/fbc8ec7ba3a7a2c29da58b963aa5fc3a.jpg', '<p>Bộ phim “Ông Trăm Tuổi Trèo Qua Cửa Sổ Và Biến Mất” được chuyển thể từ tiểu thuyết cùng tên của nhà văn Thụy Điển Jonas Jonasson, tác giả của nhiều cuốn tiểu thuyết bán chạy như: “Cô Gái Mù Chữ Phá Bom Nguyên Tử”, “Anders Sát Thủ Cùng Bè Lũ”, “Những Cuộc Phiêu Lưu Tình Cờ Của Ông Trăm Tuổi”. Vào ngày sinh nhật lần thứ 100 của mình, cụ ông Allan Karlsson đột nhiên trèo qua của sổ ngôi nhà dưỡng lão – Nhà Già – và biến mất. Ở cái tuổi 100 hiếm ai đạt tới thì cụ có thể đi đâu được? Một cuộc truy tìm trên khắp nước Thụy Điển diễn ra từ phía những người có trách nhiệm chăm nom cụ cũng như chính quyền sở tại. Song song với cuộc truy tìm nhân đạo ấy, một cuộc truy tìm đuổi bắt khác gay cấn hơn, xảy đến từ một tên tội phạm, kẻ đã ngớ ngẩn hoặc đúng hơn, bất cẩn trao vali 50 triệu crown vào tay cụ già này. Nhưng một người đã sống qua một thế kỷ thì không dễ gì tóm cụ ta được.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Robert Gustafsson","avatar":""},{"name":"Iwar Wiklander","avatar":""},{"name":"David Wiberg","avatar":""},{"name":"Mia Skäringer","avatar":""},{"name":"Jens Hultén","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324460);
