INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-chim-trong-bong-toi', 'Star Trek: Chìm Trong Bóng Tối', 'Star Trek Into Darkness', 'https://phimimg.com/upload/vod/20240220-1/d63d74e18fd91b530b883cb35e97376c.jpg', 'https://phimimg.com/upload/vod/20240220-1/86dd315f92a999d33e4dd5b485d66f37.jpg', '<p>Sau khi phi hành đoàn của doanh nghiệp tìm thấy một lực lượng khủng bố không thể ngăn cản từ trong tổ chức của họ, Thuyền trưởng Kirk dẫn đầu một cuộc săn lùng với một thế giới hoang dã để nắm bắt vũ khí hủy diệt hàng loạt một người đàn ông.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324460);
