INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('little-busters', 'Little Busters', 'LB!', 'https://phimimg.com/upload/vod/20240215-1/0867ad41dd38285fbd3dd38796126c19.jpg', 'https://phimimg.com/upload/vod/20240215-1/0a6723e99673b553153381bf601b9ae7.jpg', '<p>Naoe Riki là một cậu bé mồ côi cha mẹ từ nhỏ. Những ngày tháng u ám cứ bám lấy cuộc đời Riki cho tới một hôm, cậu gặp một đám trẻ tự xưng là Little Busters - 1 nhóm chuyên chống lại cái ác và bảo vệ công lí.&nbsp;Câu chuyện lấy bối cảnh tại trường trung học, nơi mà nhóm Little Busters gặp và kết nạp thêm nhiều thành viên và cùng nhau tận hưởng 1 school-life đầy màu sắc và không kém phần cảm động...</p>', 'Hoàn Tất (27/27)', 27, 'hoathinh', 'completed', 19, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324460);
