INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-nikita-phan-4', 'Sát Thủ Nikita (Phần 4)', 'Nikita (Season 4)', 'https://phimimg.com/upload/vod/20240215-1/c91a289b16f519bc05283a2e6b959707.jpg', 'https://phimimg.com/upload/vod/20240215-1/6868a60b942663ffc9c4238057afd7c8.jpg', '<p>Ba tháng sau khi bị buộc tội giết người, Nikita tiếp tục lẩn trốn tại Canada. Trong khi đó, Alex và Sonya đến Mumbai, cố gắng tìm ra vị trí của kẻ thù giấu mặt The Shop và cuộc khủng bố tiếp theo của họ. Sẵn sàng làm tất cả mọi thứ để xóa tên mình ra khỏi tổ chức ám sát, Nikita đến gặp Dale Gordon - người mà cô nghĩ rằng có thể giúp đỡ cô. Nhưng liệu mọi thứ có đúng như kế hoạch?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maggie Q","avatar":""},{"name":"Lyndsy Fonseca","avatar":""},{"name":"Shane West","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324460);
