INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-tuan', 'Hai Tuần', 'Two Weeks', 'https://phimimg.com/upload/vod/20240205-1/4883a816fc65b5d29652d01c92d6f0b4.jpg', 'https://phimimg.com/upload/vod/20240205-1/d60b5f73af682834eeefde5a1f0ff156.jpg', '<p>Phim xoay quanh câu chuyện một anh chàng bị đổ tội giết người bỗng nhiên phát hiện ra mình có một cô con gái mắc bệnh máu trắng. Anh chàng chỉ có vỏn vẹn 2 tuần để cố gắng cứu cô con gái.Trong Phim Hai Tuần, Kim So Yeon hóa thân thành công tố viên thông minh, công bằng Park Jae Kyung. Cô nàng chính là người chịu trách nhiệm đuổi bắt Tae San.Tác phẩm Two Weeks đánh dấu sự tái hợp của Kim So Yeon với biên kịch So Hyun Kyung sau bộ phim Prosecutor Princess. Đây cũng là lần thứ 2 cô nàng hóa thân thành một công tố viên.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2013, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Joon Gi","avatar":""},{"name":"Kim So Yeon","avatar":""},{"name":"Ryu Soo Young","avatar":""},{"name":"Park Ha Sun","avatar":""},{"name":"Lee Chae Mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324460);
