INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-thanh-tri-doanh-luy-cua-anh', 'Em Là Thành Trì Doanh Lũy Của Anh', 'You Are My Hero', 'https://phimimg.com/upload/vod/20240205-1/a523a0b96f5039fe251eea6eaac39254.jpg', 'https://phimimg.com/upload/vod/20240205-1/8001de21b530ec7f401da8f01aa3c9c7.jpg', '<p>Em Là Thành Trì Doanh Lũy Của Anh cải biên từ tiểu thuyết Thành Trì Doanh Lũy (tên khác: Mười Dặm Gió Xuân Chẳng Bằng Anh) của Mộc Thanh Vũ lấy đề tài quân nhân. Phim xoay quanh câu chuyện về Mễ Kha (Mã Tư Thuần thủ vai ) - một bác sĩ mới tại bệnh viện và đặc vụ Hình Khắc Lũy (Bạch Kính Đình thủ vai). Họ gặp nhau trong một khoá huấn luyện cứu hộ khẩn cấp do đội SWAT tổ chức. Ban đầu, Mễ Kha và Hình Khắc Lũy vì hiểu lầm nhau nên đã nảy sinh thù địch. Sau nhiều lần tiếp xúc, sát cánh bên nhau trong những tình thế nguy hiểm, cả hai đều rung cảm trước những việc làm tốt đẹp của đối phương nên quan hệ thù địch giữa họ dần dần trở thành tình yêu. Trong lực lượng cảnh sát, Hình Khắc Lũy luôn giữ hình tượng là một đội trưởng ôn hoà, uy phong, mạnh mẽ nhưng khi ở bên Mễ Kha, anh lại là một quân nhân rất chiều chuộng người yêu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mã Tư Thuần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324460);
