INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-tuoi-teen', 'Siêu Trộm Tuổi Teen', 'The Bling Ring', 'https://phimimg.com/upload/vod/20240220-1/aa6fb6159c2f6ff3035bd7774197509a.jpg', 'https://phimimg.com/upload/vod/20240220-1/ecb685a94d80580020f67dea285f5b03.jpg', '<p>Bộ phim kể về một nhóm trộm tuổi teen. Những tên trộm trẻ tuổi này thường xuyên đột nhập vào nhà những người giàu có, nổi tiếng của Hollywood để trộm đồ và phá tanh bành.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Chang","avatar":""},{"name":"Israel Broussard","avatar":""},{"name":"Emma Watson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324460);
