INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-hen-the', 'Vụ Hẹn Thề', 'The Sacrament', 'https://phimimg.com/upload/vod/20240220-1/b78db8a6ef997ed91bc28fb81e727421.jpg', 'https://phimimg.com/upload/vod/20240220-1/1ee78e2cea12410a289f39d0233a821d.jpg', '<p>The Sacrament–Vụ Hẹn Thề (2013/2014): Phim đươc xếp loại kinh dị / căng thẳng được khích lệ từ một biến cố có thật xảy ra năm 1978 do nhà thuyết giáo Jim Jones và nhóm tín đồ lập một khu riêng tại Guyana (Nam Mỹ) mang tên Kế Hoạch Đền Nông Nghiệp Nhân Dân (Peoples Temple Agricultural Project) để sống cô lập hầu có thể giữ đạo theo ý của giáo chủ.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Swanberg","avatar":""},{"name":"AJ Bowen","avatar":""},{"name":"Kentucker Audley","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"Amy Seimetz","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324460);
