INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-walter-mitty', 'Bí Mật Của Walter Mitty', 'The Secret Life Of Walter Mitty', 'https://phimimg.com/upload/vod/20240219-1/53b801d70fc37b2bad9b4307064d7300.jpg', 'https://phimimg.com/upload/vod/20240219-1/d8826bafb7359c02255f472bc510df3c.jpg', '<p>Người quản lý của ngành tài sản tiêu cực của Tạp chí Life, Walter Mitty, đã làm việc mười sáu năm cho tạp chí và có một cuộc sống tẻ nhạt, không đi đâu cả ngoài từ nhà của mình đến công việc và ngược lại. Anh ấy là một kẻ trốn thoát, mơ mộng vào một thế giới tưởng tượng nhiều lần một ngày. Walter phải lòng Cheryl Melhoff gần đây đã thuê nhưng anh ta quá ngại ngùng để mời cô vào một cuộc hẹn hò và anh ta đang cố gắng liên hệ với cô ấy qua hẹn hò trực tuyến. Tạp chí đang chuẩn bị phát hành phiên bản in cuối cùng và người quản lý sự không thể chuyển đổi Ted Hendricks đang chuẩn bị một khoản thu nhỏ không thể tránh khỏi trong vài ngày tới. Walter đã là người liên lạc giữa tạp chí và nhiếp ảnh gia độc lập bí ẩn Sean OConnell, người đã gửi cho anh ta một gói tiêu cực và một ví như một món quà cho công việc của mình. Sean cũng đề nghị quản lý cấp cao Việc sử dụng 25 âm tính cho trang bìa của phiên bản cuối cùng. Tuy nhiên, Walter không thể tìm thấy những tiêu cực bị thiếu. Walter không có cách nào để liên hệ với Sean và tìm ra một manh mối rằng anh ta có thể ở Greenland. Ông quyết định đi du lịch đến Greenland để theo dõi Sean Down vào đầu một cuộc phiêu lưu không thể tin được.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324460);
