INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-bi-an', 'Con Đường Bí Ẩn', 'Mystery Road', 'https://phimimg.com/upload/vod/20240219-1/46f46f9ef5adf80051fff49af73f4e9a.jpg', 'https://phimimg.com/upload/vod/20240219-1/6d65c98ff61faac66ce419f1a1741106.jpg', '<p>Trong một thị trấn hẻo lánh, Jay Swan, một thám tử cao bồi bản địa, trở về nhà để điều tra vụ án mạng của một cô gái vị thành niên - xác cô ấy được tìm thấy giữa tuyến đường cao tốc vận tải ra khỏi thị trấn. Jay rất xa lạ với lực lượng cảnh sát da trắng đang thống trị và cả cộng đồng bản địa, trong đó có cô con gái tuổi teen của mình, người đang có quan hệ mật thiết với nạn nhân bị sát hại.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Aaron Pedersen","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Ryan Kwanten","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324460);
