INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blue-is-the-warmest-colour', 'Blue Is The Warmest Colour', 'Blue Is The Warmest Colour', 'https://phimimg.com/upload/vod/20240219-1/b59b8a1405998a3be226ce8520d88988.jpg', 'https://phimimg.com/upload/vod/20240219-1/82892913f5e840050a20f6b952babe65.jpg', '<p>Adèle là một học sinh trung học đang bắt đầu khám phá mình như một người phụ nữ. Cô ấy hẹn hò với đàn ông nhưng không tìm thấy sự hài lòng với họ tình dục, và bị một người bạn nữ bị từ chối, cô ấy muốn. Cô mơ thấy một cái gì đó nhiều hơn. Cô ấy gặp Emma, một cô gái có tinh thần tự do mà bạn bè của Adèle từ chối do tình dục của cô ấy, và bởi hiệp hội bắt đầu từ chối Adèle. Mối quan hệ của cô với Emma phát triển thành nhiều hơn là những người bạn như cô là người duy nhất mà cô có thể thể hiện mình một cách cởi mở. Cùng nhau, Adèle và Emma khám phá sự chấp nhận xã hội, tình dục và phổ tình cảm của mối quan hệ trưởng thành của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324460);
