INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-benh-quai-ac', 'Căn Bệnh Quái Ác', 'Contracted', 'https://phimimg.com/upload/vod/20240219-1/39a1b22ffa859a4811bb0b1a03b79c2b.jpg', 'https://phimimg.com/upload/vod/20240219-1/d15b3e58bf898ec082818ddcabf47445.jpg', '<p>Trong một khoảng thời gian khó khăn trong cuộc đời cô, Samantha xinh đẹp miễn cưỡng tuân theo đảng của người bạn thân nhất của mình, và mặc dù cô vẫn vật lộn với một cơn nghiện trước đó, cô không chính xác chấp nhận một thức uống từ một người xa lạ hoàn toàn. Kết quả là, sau đó, Samantha Hapless bị say mê đáng kể, cô ấy sẽ bị hãm hiếp trong ghế sau của chiếc xe của kẻ săn mồi độc hại, tuy nhiên, từ thời điểm đó, sự cố khủng khiếp sẽ là vấn đề ít nhất trong số các vấn đề của cô. Ngay lập tức và khá không thể giải thích được, Samantha tội nghiệp sẽ bắt đầu nhận thấy những thay đổi hữu cơ nhanh chóng và mạnh mẽ trong cơ thể của cô ấy, và không thể xác định được nguồn gốc của sự biến đổi đáng kể, trong vòng 72 giờ tới, cô ấy sẽ nắm lấy số phận khủng khiếp và đáng buồn của mình cũng như chắc chắn rằng cô ấy đang sụp đổ. Theo đúng nghĩa đen</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324460);
