INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-arise-border-1-noi-dau-ma', 'Vỏ Bọc Ma ARISE Border: 1 Nỗi Đau Ma', 'Ghost In The Shell Arise - Border 1: Ghost Pain', 'https://phimimg.com/upload/vod/20240219-1/513cda5540ed03a853cb2c94cf99ada3.jpg', 'https://phimimg.com/upload/vod/20240219-1/3000af594a827f9b6f0c530ae7fa2a6a.jpg', '<p>Câu chuyện lấy bối cảnh vào năm 2027, một năm sau khi kết thúc cuộc chiến tranh phi hạt nhân lần thứ tư. Thành phố Tân Cảng vẫn đang quay cuồng với hậu quả của chiến tranh khi nó hứng chịu một trận bom do mìn tự hành gây ra. Sau đó, một thành viên quân đội liên quan đến hối lộ buôn bán vũ khí bị bắn hạ. Trong quá trình điều tra, Daisuke Aramaki của Bộ phận An ninh Công cộng chạm trán với Motoko Kusanagi, hacker cấp độ người máy, phù thủy được giao cho Đơn vị Bí mật 501 của quân đội. Batou, một người đàn ông có con mắt không ngủ, nghi ngờ rằng Kusanagi là kẻ đứng sau vụ đánh bom. Thanh tra cảnh sát tỉnh Niihama Togusa đang theo đuổi hai vụ án của riêng mình về vụ bắn chết và giết gái mại dâm. Bản thân Motoko đang bị theo dõi bởi Kurutsu, người đứng đầu Đơn vị bí mật thứ 501 và các đặc vụ người máy.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Maaya Sakamoto","avatar":""},{"name":"Ikkyu Juku","avatar":""},{"name":"Kenichirou Matsuda","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Shunsuke Sakuya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324460);
