INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-noi-dam-lay', 'Giáng Sinh Nơi Đầm Lầy', 'Christmas on the Bayou', 'https://phimimg.com/upload/vod/20231108-1/517ac01b8ad7ca2e98baf99effd7618d.jpg', 'https://phimimg.com/upload/vod/20231108-1/2f1c28d3a90773321ec227b70e12ca94.jpg', '<p>Giáng Sinh Nơi Đầm Lầy - Christmas on The Bayou kể về Katherine - một giám đốc Marketing thành công ở New York. Khi phát hiện ra thói tham công tiếc việc đang ảnh hưởng đến cậu con trai 8 tuổi của mình, Zac, cô quyết định dành Giáng sinh bên Caleb và người thân ở quê nhà trên vịnh. Khi Caleb cố gắng khơi lạimối tình thời thơ ấu và thuyết phục cô chuyển về nhà, Katherine bị giằng xé giữa ánh đèn rực rỡ nơi thành phố lớn và sự yên tĩnh nơi quê hương. Lúc này, chỉ có một phép màu Giáng sinh do Papa Noel dàn dựng mới có thể hướng trái tim Katherine về ngôi nhà thực sự của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilarie Burton","avatar":""},{"name":"Tyler Hilton","avatar":""},{"name":"Randy Travis","avatar":""},{"name":"Markie Post","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Brody Rose","avatar":""},{"name":"Ariana Neal","avatar":""},{"name":"Cannon Bosarge","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Colin Bates","avatar":""},{"name":"Samantha Beaulieu","avatar":""},{"name":"Jacob Etter","avatar":""},{"name":"Odessa Feaster","avatar":""},{"name":"Dana Gourrier","avatar":""},{"name":"Leticia Jimenez","avatar":""},{"name":"Mary Katherine Oglesby","avatar":""},{"name":"Lisa Raziano","avatar":""},{"name":"Ang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324461);
