INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('atm-2-ket-hon', 'ATM 2: Kết Hôn', 'ATM 2 The Series', 'https://phimimg.com/upload/vod/20240126-1/b57d83f5721597890d508f0fb2103de7.jpg', 'https://phimimg.com/upload/vod/20240126-1/e190fa675f1b63531fdd1da3e62e3872.jpg', '<p>Tiếp nối câu chuyện tình của Sua và Jib trong phim điện ảnh ATM: Lỗi Tình Yêu. Giờ đây cả hai đã kết hôn và Jib chấp nhận ở nhà làm hậu phương để Sua yên tâm xây dựng sự nghiệp. Suốt ngày quần quật với công việc giặt giũ, đưa đón chồng đi làm, khiến cho cuộc sống của Jib trở nên tẻ nhạt. Không thể chịu đựng điều đó, Jib quyết định quay trở lại ngân hàng làm việc. Những cạnh tranh, mẫu thuẫn và cuộc chiến giành vị trí cũng nảy sinh từ đây. Liệu cả hai có thể giữ được hạnh phúc hiện có của mình hay không?</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ter Chantavit Dhanasevi","avatar":""},{"name":"Ice Preechaya Pongthananikorn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
