INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-anh-that-lac', 'Bức Ảnh Thất Lạc', 'The Missing Picture (L''image Manquante)', 'https://phimimg.com/upload/vod/20240207-1/52310f53c5192cfd561cba369a91b79d.jpg', 'https://phimimg.com/upload/vod/20240207-1/d1a82d0d2e800ab439f189b574f91eb2.jpg', '<p>Năm 1975, quân đội Khmer Đỏ nắm quyền trên vương quốc Campuchia, bắt đầu một thời kỳ đẫm máu trong lịch sử đất nước này. Suốt 4 năm nằm dưới chính quyền Kampuchea Dân Chủ với lãnh đạo Pol Pot, Campuchia đã trải qua nạn diệt chủng tàn khốc dưới chế độ cải cách, cướp đi sinh mạng của gần 2 triệu người. Không chỉ chia rẽ gia đình thành từng nhóm lao động khổ sai ở nhiều thành phố xa nhau, bắt họ bỏ đi danh tính để gọi nhau bằng con số, Khmer Đỏ còn tuyên chiến với những nhóm dân ngoài nông nghiệp như lớp trí thức. Những cuốn sách bị đốt cháy, trường học biến thành nơi tra tấn tù nhân, sự đàn áp đó đã cướp từ tay cả thế hệ trẻ một ngòi bút hay trí nhớ để viết về trang lịch sử cay nghiệt. Những đứa trẻ giờ nằm dưới sự tàn ác của chính quyền, ngày ngày lao động khổ sai...</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Randal Douc","avatar":""},{"name":"Jean-Baptiste Phou","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324461);
