INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-ngon-luan', 'Cuộc Chiến Ngôn Luận', 'Library Wars', 'https://phimimg.com/upload/vod/20240228-1/4dbe660befed0b6a32774ae8416437e0.jpg', 'https://phimimg.com/upload/vod/20240228-1/1f516a880e620f204d95ad7aa1cbe0cf.jpg', '<p>Library Wars là bộ phim năm 2013 dựa trên tiểu thuyết cùng tên của Hiro Arikawa. Quá trình quay phim bắt đầu vào tháng 10 năm 2012 và bộ phim được phát hành vào ngày 27 tháng 4 năm 2013. Đây là một thành công về mặt phê bình và phòng vé ở Nhật Bản, tiếp theo là phần tiếp theo, Library Wars: The Last Mission.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nana Eikura","avatar":""},{"name":"Okada Junichi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
