INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-nguoi-yeu-dau', 'Giết Người Yêu Dấu', 'Kill Your Darlings', 'https://phimimg.com/upload/vod/20240205-1/af3f3f9bfce91904c427c24a69d84468.jpg', 'https://phimimg.com/upload/vod/20240205-1/1f79a6c930d4c563888348b301611004.jpg', '<p>Kill Your Darlings là một phim tiểu sử Mỹ năm 2013 được viết bởi Austin Bunn và đạo diễn bởi John Krokidas trong bộ phim đầu tay của mình. Bộ phim đã được công chiếu trên toàn thế giới tại Liên hoan phim Sundance 2013, thu được những phản ứng đầu tiên tích cực.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Dane DeHaan","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"David Cross","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"David Rasche","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
