INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-rong-thien-loi-nguyen-cua-bong-dem', 'Truyền Thuyết Rồng Thiên: Lời Nguyền Của Bóng Đêm', 'Dragon Lore: Curse Of The Shadow', 'https://phimimg.com/upload/vod/20240205-1/321433c4859e9528e379bb52f7491bd3.jpg', 'https://phimimg.com/upload/vod/20240205-1/f6f92f4b8ac5fc256c29c93172898028.jpg', '<p>Nữ thợ săn Nemyt trong một lần đi săn vô tình bắn hạ con rồng của tên quái vật Fangtor Bloodmoon và nhân cơ hội đó hắn tìm cách trả thù cô, buộc Nemyt phải đứng lên đương đầu với thế lực hắc ám...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Chuchran","avatar":""},{"name":"Richard McWilliams","avatar":""},{"name":"Paul D. Hunt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324461);
