INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-duong-cung-life-of-a-king', 'Bước Đường Cùng', 'Life Of A King', 'https://phimimg.com/upload/vod/20240207-1/9f49ae4f99f29bfd11319a52a9ccc101.jpg', 'https://phimimg.com/upload/vod/20240207-1/78ee6661a05e03d0691525e599593755.jpg', '<p>Câu chuyện có thật về sứ mệnh của một người đàn ông là mang đến cho những đứa trẻ nội thành Washington DC thứ mà anh chưa từng có - một tương lai. Sau khi bị giam 18 năm, Eugene Brown đã thành lập Câu lạc bộ Cờ vua Ghế Lớn để giúp những đứa trẻ thoát khỏi đường phố và hướng tới những cuộc sống mà chúng chưa bao giờ tin rằng mình có khả năng. Đây là câu chuyện đầy cảm hứng của anh ấy.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"LisaGay Hamilton","avatar":""},{"name":"Paula Jai Parker","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Carlton Byrd","avatar":""},{"name":"Thurston Hill","avatar":""},{"name":"Chidi Ajufo","avatar":""},{"name":"Jaida - Iman Benjamin","avatar":""},{"name":"Rickey Brown","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
