INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-thuong-vo', 'Mỹ Nhân Thượng Võ', 'Kick Ass Girls', 'https://phimimg.com/upload/vod/20240207-1/59ae9f02047915cc9f28128d2d3acb1a.jpg', 'https://phimimg.com/upload/vod/20240207-1/384dd1b3aaff01c806254a1915434ecb.jpg', '<p>Bảo Bảo trong 1 lần sắp xếp đấu boxing với cô bạn thân tên TT, họ đã đường ai nấy đi sau khi đánh bại 1 anh chàng.Sau đó Bảo thuê 1 người vô gia cư tên Miu, người bị bồ đá ra khỏi nhà, để làm nữ tiếp viên boxing xinh đẹp, với mục đích thu hút sự chú ý của các nam khán giả. Nhưng không may là TT lại đến để gây rối ở trận đấu boxing. Và một người phụ nữ bí ẩn tên Zhu Ge cũng xuất hiện để thuê 1 vệ sĩ bảo vệ trên đường đi Malaysia, mọi rắc rối bắt đầu...</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chrissie Chow","avatar":""},{"name":"Dada Lo","avatar":""},{"name":"Hidy Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
