INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dua-mau-2', 'Đường Đua Máu 2', 'Race 2', 'https://phimimg.com/upload/vod/20240207-1/c13eb8928ea9eced11686336be62ec11.jpg', 'https://phimimg.com/upload/vod/20240207-1/5b1950568d81aa9ad66dfe4857f36abd.jpg', '<p>Trả thù cho cái chết của người tình cũ, Ranveer buộc phải đối mặt với Armaan Mallik, ông trùm khét tiếng của băng đảng mafia người Ấn tại châu Âu. Để tiếp cận với kẻ thù, Ranveer đã tán tỉnh Aleena, em gái nuôi của Mallik lẫn cả cô nàng Omisha - hôn thê của kẻ thù. Khi kế hoạch trả thù đang diễn ra trôi chảy, Ranveer phát hiện ra mình đã mắc phải một sai lầm chết người: anh đã đem lòng yêu Omisha. Liệu cạm bẫy nào đó đang chờ đón Ranveer trong cuộc chơi đầy oan nghiệt này?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Anil Kapoor","avatar":""},{"name":"John Abraham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
