INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-mat-troi-xu-leith', 'Ánh Mặt Trời Xứ Leith', 'Sunshine On Leith', 'https://phimimg.com/upload/vod/20240207-1/6c3dd76e63f87897ef16d5224aa41bf2.jpg', 'https://phimimg.com/upload/vod/20240207-1/fe91056274dc42d34bb683d6e6606022.jpg', '<p>Davy và Ally phải học lại cách sống ở Edinburgh sau khi phục vụ ở Afghanistan về nhà. Cả hai đấu tranh để học cách sống một cuộc sống bên ngoài quân đội và đối phó với những khó khăn hàng ngày của gia đình, công việc và các mối quan hệ. Sunshine on Leith dựa trên bản hit sân khấu giật gân cùng tên, có phần âm nhạc của ban nhạc pop-folk The Proclaimers.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George MacKay","avatar":""},{"name":"Kevin Guthrie","avatar":""},{"name":"Freya Mavor","avatar":""},{"name":"Antonia Thomas","avatar":""},{"name":"Jane Horrocks","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
