INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-ve-nha', 'Hành Trình Về Nhà', 'Boonie Bears: Homeward Journey', 'https://phimimg.com/upload/vod/20240207-1/daf1faf0a3ea65ae4009c64cf1925181.jpg', 'https://phimimg.com/upload/vod/20240207-1/5947d36eec662c760f4e6a57a35e0c74.jpg', '<p>Hành trình về nhà - Boonie Bears: Homeward Journey kể câu chuyện về anh chàng tiều phu Vick và những người bạn là những loài vật sống trong rừng. Tiều phu Vick bắt đầu chiến dịch đốn rừng để có tiền về quê ăn Tết. Anh em nhà gấu tập hợp bạn bè, sử dụng mọi mánh khóe để cứu ngôi nhà thiên nhiên yêu dấu. Nhưng thật bất ngờ, nhóm bạn lại sớm cảm động trước tình cảnh của Vick nên đã ấp ủ kế hoạch đưa anh chàng tiều phu kịp trở về nhà, quây quần bên gia đình dịp Tết.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
