INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-sieu-oai-oam', 'Phi Vụ Siêu Oái Oăm', 'Suck Me Shakespeer', 'https://phimimg.com/upload/vod/20240205-1/c9da14c2aeed8db3916d6a3bb051c6fb.jpg', 'https://phimimg.com/upload/vod/20240205-1/3e593ca6d538fb571e6c386be3ace61d.jpg', '<p>Phi Vụ Siêu Oái Oăm là câu chuyện kể về những giáo viên bị quá tải và những cô cậu học sinh lắm chiêu nhiều trò, đem lại tiếng cười sảng khoái và chống lại sự gò bó trong trường học. Sau khi ra tù vì tội cướp nhà băng, Zeki Miller đi tìm lại khoản tiền mình đã trộm được để trả nợ, nhưng oái oăm là ở chỗ đồng phạm với anh ta lại chôn tiền ở một công trình đang xây dựng. Ai mà ngờ, khi Zeki ra tù thì chỗ đó đã trở thành phòng thể thao của trường trung học Goethe. Vì muốn lấy lại số tiền, anh ta xin vào làm giáo viên tạm thời trong trường. Như một số giáo viên khác, anh chàng giáo viên thay thế bất đắc dĩ này đã bị đám trẻ hành cho lên bờ xuống ruộng. Để đáp trả, anh ta nhanh chóng dạy cho bọn chúng nhiều bài học đích đáng. Vô tình, những “bài học” đó có tác dụng tích cực cho bọn trẻ.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Elyas M''Barek","avatar":""},{"name":"Karoline Herfurth","avatar":""},{"name":"Katja Riemann","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
