INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhien-tuyet-my-dat-nuoc-dai-loan', 'Thiên Nhiên Tuyệt Mỹ: Đất Nước Đài Loan', 'Beyond Beauty: Taiwan From Above', 'https://phimimg.com/upload/vod/20240220-1/7aca661d7ac06b47a585ca82f3b7a5fd.jpg', 'https://phimimg.com/upload/vod/20240220-1/d7c40beb3c44c45e34204831f62389df.jpg', '<p>Phim Thiên Nhiên Tuyệt Mỹ: Đất Nước Đài Loan - Beyond Beauty: Taiwan From Above 2013 là bộ phim tài liệu đầu tiên ghi lại những hình ảnh tuyệt đẹp của thiên nhiên Đài Loan từ trên không. Bộ phim đoạt giải phim tài liệu xuất sắc nhất tại Giải thưởng Kim Mã lần thứ 50, đồng thời trở thành bộ phim tài liệu đạt doanh thu cao nhất tại thị trường Đài Loan.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Nien-Jen Wu","avatar":""},{"name":"Xiang Hong","avatar":""},{"name":"Cing-Soong Lai","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324461);
