INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('saving-mr-banks', 'Saving Mr. Banks', 'Saving Mr. Banks', 'https://phimimg.com/upload/vod/20240128-1/e04633e129cd3478cce57a308be01b2f.jpg', 'https://phimimg.com/upload/vod/20240128-1/796bbfce766e9478f9e821bf24c8a3c1.jpg', '<p>Bộ phim có nội dung tái hiện câu chuyện chưa từng được kể về cuộc hội ngộ giữa P.L. Travers, tác giả của tác phẩm nổi tiếng Mary Poppins, và nhà sản xuất phim huyền thoại Walt Disney. Năm 1961, Disney đã mời bà Trevers tới Hollywood để thương lượng sở hữu bản quyền cuốn sách và chuyển thể thành phim. Bà Travers đồng ý và lưu lại Los Angeles trong 2 tuần để theo sát quá trình lên kế hoạch sản xuất một trong những bộ phim được yêu mến nhất trong lịch sử.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Annie Rose Buckley","avatar":""},{"name":"B.J. Novak","avatar":""},{"name":"Kathy Baker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
