INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-chinh-minh', 'Là Chính Mình', 'We Are What We Are', 'https://phimimg.com/upload/vod/20240128-1/3872a59d72f898eb3283ded9a7f56868.jpg', 'https://phimimg.com/upload/vod/20240128-1/1c21a681e9446181a04079da764bbbd8.jpg', '<p>Gia đình Parkers, những người ẩn dật bám vào các phong tục cổ xưa, thấy cuộc sống bí mật của họ bị đe dọa khi một trận mưa như trút nước và cái chết của người mẫu hệ buộc hai cô con gái Iris và Rose phải đảm nhận những trách nhiệm đặc biệt.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Sage","avatar":""},{"name":"Ambyr Childers","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"Michael Parks","avatar":""},{"name":"Wyatt Russell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
