INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-khu', 'Quá Khứ', 'The Past', 'https://phimimg.com/upload/vod/20240128-1/2e2b6f88e25228d902da997af623d947.jpg', 'https://phimimg.com/upload/vod/20240128-1/b2bb5a8a16a2314e39afc57766063043.jpg', '<p>Sau 4 năm, một người đàn ông Iran quay trở lại Pháp để thăm vợ cũ và hai đứa con. Lúc này Ahmad nhận ra rằng vợ cũ của mình đang có mối quan hệ với một người Ả Rập tên Samir. Samir cũng có một con trai và một người vợ đang hôn mê. Mối quan hệ của cô con gái lớn và mẹ cô đang xấu đi vì cô con gái cho rằng mẹ cô là nguyên nhân dẫn đến tình trạng hôn mê của vợ Samir.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Berenice Bejo","avatar":""},{"name":"Ali Mosaffa","avatar":""},{"name":"Tahar Rahim","avatar":""},{"name":"Pauline Burlet","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
