INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-thit-dong-loai', 'Ăn Thịt Đồng Loại', 'Butcher Boys', 'https://phimimg.com/upload/vod/20240126-1/a369654595d969c154a79e3719358720.jpg', 'https://phimimg.com/upload/vod/20240126-1/0d04cc13e5232354a32f41d91aa540bb.jpg', '<p>Một chuyến đi tàu lượn siêu tốc liên tục, đau thắt ruột xuyên qua vùng đất địa ngục của thành phố nội địa Mỹ. Một lễ kỷ niệm sinh nhật tại một nhà hàng cao cấp diễn ra trong các sự kiện chuyển động đưa Sissy, anh trai cô, Mikey, và những người bạn, Kenny và Barbie, đối mặt với thế giới rùng rợn của Boneboys. Lấy cảm hứng từ câu chuyện ăn thịt đồng loại A Modest Proposal của Jonathan Swift, Boneboys là những kẻ săn mồi quốc tế chuyên kinh doanh thịt người - dù còn sống hay đã chết. Nơi săn bắn của họ là các thành phố trên thế giới.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ali Faulkner","avatar":""},{"name":"Edwin Neal","avatar":""},{"name":"Marilyn Burns","avatar":""},{"name":"Derek Lee Nixon","avatar":""},{"name":"Johnny Walter","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
