INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-sieu-bua', 'Bộ Ba Siêu Bựa', 'Grand Masti', 'https://phimimg.com/upload/vod/20240126-1/56a0f3ed53f6da4786a8fe0f2377c558.jpg', 'https://phimimg.com/upload/vod/20240126-1/fb2d538166b9c0d89f59375c0721c4e3.jpg', '<p>Phim Bộ Ba Siêu Bựa - Grand Masti 2013: Amar, Prem và Meet là những người bạn lâu năm đã trải qua mọi giai đoạn cuộc đời cùng nhau, họ cùng lớn lên bên nhau và bây giờ họ đang cùng chán cuộc sống hôn nhân mập mờ của họ. Để thêm một chút gia vị cho cuộc sống của mình, họ bắt đầu lên một kế hoạch cho cuộc phiêu lưu hoang dã tại trường trung học để tìm kiếm những kỉ niệm ngày xưa! Khi niềm vui trở thành cái gì đó gian dối và gian dối hơn, họ thấy mình bị lạc lối trong chính kế hoạch của mình và đi vào một mạng lưới nguy hiểm không có lối thoát.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ritesh Deshmukh","avatar":""},{"name":"Vivek Oberoi","avatar":""},{"name":"Aftab Shivdasani","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
