INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-westerplatte', 'Trận Chiến Westerplatte', 'Battle Of Westerplatte', 'https://phimimg.com/upload/vod/20240126-1/53eaea72d0acb413ccf62a28b59dcb42.jpg', 'https://phimimg.com/upload/vod/20240126-1/ab3f9e4f1810eb20f00b2e1ad4b9edb9.jpg', '<p>Bộ phim chiến tranh đau thương này là một vở kịch sử thi về trận chiến đầu tiên của Thế chiến thứ hai. Trận chiến Westerplatte bắt đầu vào ngày 1 tháng 9 năm 1939 sẽ mãi mãi được ghi nhớ là trận chiến tuyên bố bắt đầu Thế chiến thứ hai ở châu Âu. Trong hơn một tuần, chưa đầy 200 binh sĩ Ba Lan đã chiến đấu chống lại đợt oanh tạc dữ dội của quân Đức và trong quá trình này, họ trở thành biểu tượng cho sức mạnh của sự kháng cự. Khi bạo lực bùng phát, một trận chiến phức tạp mang tính chất cá nhân hơn diễn ra giữa hai chỉ huy Ba Lan về cách lãnh đạo người của họ một cách tốt nhất. Giữa cảnh đổ máu, họ phải tự hỏi bản thân – họ nên chiến đấu cho đến khi người cuối cùng đứng vững hay đầu hàng khi đối mặt với tỷ lệ áp đảo? Những gì mở ra là một cuộc khám phá gây xúc động về cuộc chiến chống lại các thế lực chuyên chế.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Michal Zebrowski","avatar":""},{"name":"Mirosław Baka","avatar":""},{"name":"Jan Englert","avatar":""},{"name":"Borys Szyc","avatar":""},{"name":"Piotr Adamczyk","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
