INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-trai-dat', 'Trở Về Trái Đất', 'After Earth', 'https://phimimg.com/upload/vod/20240124-1/47ddfe221b98b43703a7f08f980b0354.jpg', 'https://phimimg.com/upload/vod/20240124-1/ab9601f81683ccf28213751b6f04f6bf.jpg', '<p>Một vụ va chạm rời khỏi Kitai Raige và cha Cypher bị mắc kẹt trên trái đất, một thiên niên kỷ sau những sự kiện bị ép buộc sự trốn thoát của nhân loại. Với Cypher bị thương, Kitai phải bắt tay vào một hành trình nguy hiểm để báo hiệu để được giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324461);
