INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-ma-phap-su', 'Kim Ma Pháp Sư', 'Kamen Rider Wizard In Magic Land', 'https://phimimg.com/upload/vod/20240124-1/182d014e41c45a1feafbea568b744b10.jpg', 'https://phimimg.com/upload/vod/20240124-1/ba5d60d670bba0632498dbffd68c4271.jpg', '<p>Haruto sẽ du hành đến vùng đất Land of Magic, và gặp được Golden Magician, hay giờ đã chính thức được biết đến là Kamen Rider Sorcerer. Ở nơi này cũng có thể henshin thành Kamen Rider Mage (bằng một chiếc thặt lưng giống với White Wizard). Như trong bức hình dưới có thể thấy Rinko, Shunpei và Wajima đang chuẩn bị henshin.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shun''ya Shiraishi","avatar":""},{"name":"Makoto Okunaga","avatar":""},{"name":"Junki Tozuka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
