INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-con-do', 'Pháp Sư Côn Đồ', 'Man On The Edge', 'https://phimimg.com/upload/vod/20240123-1/ff119117849f814b654c4a477763b19f.jpg', 'https://phimimg.com/upload/vod/20240123-1/a81cca68b9573c45ac837e768a926f17.jpg', '<p>Một tay xã hội đen được chọn để trở thành thầy cúng. Làm sao anh có thể cân bằng cuộc sống hoàn toàn đối lập của mình, giữa đánh người và giúp người. Sau đó, ông chủ của anh ta vô tình ghét thầy cúng.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Shin-yang","avatar":""},{"name":"Kim Jung-tae","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Jung Hye-young","avatar":""},{"name":"Kim Sung-kyun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324461);
