INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-xac-song', 'Vua Xác Sống', 'Zombie King', 'https://phimimg.com/upload/vod/20240123-1/809dc64f4a1ff1b64e7c9dc9deddf58e.jpg', 'https://phimimg.com/upload/vod/20240123-1/61a7019aba85577b0f984b42c80a8b0d.jpg', '<p>Vua Xác Sống - Zombie King kể về những con người xa lạ tập hợp lại và tìm cách để sống sót khi mà thảm họa xác sống lan rộng khắp đất nước. Nhưng họ có thể đối chọi lại với thế lực siêu nhiên? Nguồn cơn của thảm họa bắt đầu từ một người đàn ông bất hạnh mất đi người vợ thương yêu. Anh ta sẵn sàng giao kèo với ác quỷ để đưa vợ mình trở về. Có điều... ác quỷ không dễ đối phó.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Corey Feldman","avatar":""},{"name":"EDWARD FURLONG","avatar":""},{"name":"George McCluskey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
