INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-gia-dinh-o-osage', 'Đại Gia Đình Ở Osage', 'August', 'https://phimimg.com/upload/vod/20240123-1/c2f1323ce271d7b135e4f9d9006c834c.jpg', 'https://phimimg.com/upload/vod/20240123-1/e7812ab595dc0267cba7643494c70a83.jpg', '<p>Đại Gia Đình Ở Osage - August - August: Osage County kể về gia đình Weston tại vùng Oklahoma nổi tiếng với việc có những người phụ nữ độc lập, mạnh mẽ và không cùng nhìn về một hướng. Những con người trong gia đình chẳng ai muốn gặp ai nhưng rồi cuối cùng cũng phải quay trở về gặp nhau vì cái chết đột ngột của một thành viên trong gia đình. Họ quay về để làm nghĩa vụ với người cha đã mất và người mẹ nghiện thuốc đang mang trong mình bệnh ung thư.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Chris Cooper","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
