INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-xac-2013', 'Thoát Xác', 'John Dies At The End', 'https://phimimg.com/upload/vod/20240122-1/b1cc5c97f8dc07ec338f4cf64fc422c1.jpg', 'https://phimimg.com/upload/vod/20240122-1/635d9df4b81ba5b927ffa15c3c8cd984.jpg', '<p>Bộ phim John Dies at the End xoay quanh một loại thuốc hứa hẹn cho những trải nghiệm kỳ lạ mà người ta gọi nó là Nước Sốt Đậu Nành, và người sử dụng qua sẽ có cảm giác trôi theo thời gian và không gian. Tuy nhiên, một số người trở về không còn là con người. Đột nhiên, một cuộc xâm lược đang được tiến hành, và nhân loại cần một anh hùng. Khi đó John và David, hai học sinh bỏ học đại học để giữ được việc đang làm. Liệu hai người bạn này có thể ngăn chặn được thời khắc kinh hoàng đang tới để cứu nhân loại?</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chase Williamson","avatar":""},{"name":"Rob Mayes","avatar":""},{"name":"Paul Giamatti","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
