INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-nguoi-cua-ban', 'Mẫu Người Của Bạn', 'A Case Of You', 'https://phimimg.com/upload/vod/20240121-1/cf4973b3cfa18925397f24cc50eecd4d.jpg', 'https://phimimg.com/upload/vod/20240121-1/f6b0546cac6bfd8f9c6734cef02f0d19.jpg', '<p>A Case of You xoay quanh câu chuyện về nhân vật nhà văn trẻ cố gắng gây ấn tượng với một phụ nữ mà mình thích bằng cách tạo một tài khoản ảo trên Facebook với một hồ sơ lý lịch với những tiêu chuẩn mà cô gái này thích. Tuy nhiên, mọi chuyện trở nên rắc rối khi người phụ nữ ấy đã đem lòng yêu anh thật. Anh cảm thấy khó xử khi tự hỏi nếu như biết được sự thật về con người anh thì cô có còn yêu anh nữa hay không, cuộc sống của anh giống như một mớ hỗn độn mà anh không tìm được lối ra...</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Long","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Evan Rachel Wood","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324461);
