INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-long-bao-chua', 'Khủng Long Bạo Chúa', 'The Dinosaur Experiment', 'https://phimimg.com/upload/vod/20240207-1/a5af0101b80b3e487ff36e66acad65a8.jpg', 'https://phimimg.com/upload/vod/20240207-1/53cb82b42c9079edab031351106c1c1f.jpg', '<p>Những vụ án mạng xảy ra, đội thám tử và cảnh sát đều đi vào ngõ cụt khi bằng chứng để lại hiện trường chỉ là một mảnh móng vuốt. Nhóm bạn trẻ 3 người phát hiện ra hung thủ chính là khủng long hồi sinh và phải cố sức giành sự sống với sinh vật mạnh nhất hành tinh.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jana Mashonee","avatar":""},{"name":"Lorenzo Lamas","avatar":""},{"name":"Cole Brown","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
