INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-sadako-2', 'Lời Nguyền Sadako 2', 'Sadako 3D 2', 'https://phimimg.com/upload/vod/20240207-1/c83c257823f1ce2eb9ec1371a397c40f.jpg', 'https://phimimg.com/upload/vod/20240207-1/02fb7db42640a21fe13e897cb6f64e84.jpg', '<p>Trong phim Lời Nguyền Sadako 2, tại một trường trung học nơi Akana Aikawa đang giảng dạy lan truyền tin đồn về một cuốn băng. Cuốn băng khiến cho những người xem nó có ý định tự sát. Xem phim này bạn sẽ thấy ngay sau đó, một học sinh của Akane là Noriko đã tự tử. Và rồi hàng loạt những những cái chết đáng ngờ được phát hiện.Phía cảnh sát kết luận rằng nguyên nhân của những cái chết này đều là tự sát mà bỏ lỡ mất một đầu mối quan trọng trong hàng loạt cái chết của những học sinh này. Đó là họ đều đã xem một cuốn băng trước khi chết. Bộ phim Lời Nguyền Sadako 2 được xây dựng dựa trên một tác phẩm của Koji Suzuki, chúc các bạn xem phim online thật vui vẻ!</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miori Takimoto","avatar":""},{"name":"Satomi Ishihara","avatar":""},{"name":"Yusuke Yamamoto","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
