INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thung-lung-soi-2013', 'Thung Lũng Sói', 'Wolf Creek 2', 'https://phimimg.com/upload/vod/20240207-1/f56a61f434155617c9bd52960bb9b213.jpg', 'https://phimimg.com/upload/vod/20240207-1/b06afeb4ef0a51c286c09dd0208c9e9b.jpg', '<p>Bị thu hút bởi lời hứa về một kỳ nghỉ ở Úc, những du khách ba lô Rutger, Katarina và Paul đến thăm Miệng núi lửa Wolf Creek khét tiếng. Cuộc phiêu lưu vùng hẻo lánh trong mơ của họ sớm trở thành hiện thực kinh hoàng khi họ chạm trán với người địa phương khét tiếng nhất của địa điểm, người đàn ông cuối cùng mà bất kỳ du khách nào đến vùng này đều muốn gặp—Mick Taylor. Khi những du khách ba lô chạy trốn, Mick truy đuổi họ trong một cơn thịnh nộ hoành tráng bằng những ngón tay trắng xuyên qua vùng đất hoang đầy thù địch.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Jarratt","avatar":""},{"name":"Ryan Corr","avatar":""},{"name":"Ben Gerrard","avatar":""},{"name":"Shane Connor","avatar":""},{"name":"Shannon Ashlyn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
