INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vinh-trinh', 'Mã Vĩnh Trinh', 'Ma Yong Zhen', 'https://phimimg.com/upload/vod/20240116-1/82a9137e73ba4a09172b6131fc98bb80.jpg', 'https://phimimg.com/upload/vod/20240116-1/af1a66411f9945b0ac9033ad71f0c7ff.jpg', '<p>Mã Vĩnh Trinh - Ma Yong Zhen xoay quanh cuộc đời nhiều biến cố của chàng trai trẻ Mã Vĩnh Trinh rời quê nghèo Sơn Đông lên Thượng Hải tìm kiếm giấc mơ đổi đời. Khi mới đến đây, anh đã trải qua rất nhiều gian nan, nhưng sau cùng đã gây dựng được một địa bàn riêng tại nơi phồn hoa này. Tuy nhiên, các thế lực xấu xa không dung nạp được Mã Vĩnh Trinh chính nghĩa, vì vậy ở bến Thượng Hải đã diễn ra một cuộc chiến giữa cái thiện và cái ác làm rung động lòng người.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 16, 2013, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Thiếu Cường","avatar":""},{"name":"Châu Mục Ân","avatar":""},{"name":"Hà Trung Hoa","avatar":""},{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Trần Quốc Khôn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324461);
