INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('79-dem', '79 Đêm', 'Seventy-Nine', 'https://phimimg.com/upload/vod/20240121-1/160a7752de297fe78761141a64240f93.jpg', 'https://phimimg.com/upload/vod/20240121-1/970e824cfbdd166cd0be9b4b043e2d50.jpg', '<p>Trong một trại tâm thần bị bỏ hoang, các bác sĩ thực hiện các thí nghiệm bí mật trên những bệnh nhân không nghi ngờ. Các thí nghiệm, có tên mã là Limes, được thiết kế để chữa các cơn bạo lực trong tù nhân thông qua các phương pháp tẩy não và thao túng tâm trí mới. Gia đình các bệnh nhân sớm phát hiện đây không phải là bệnh viện bình thường.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Rosenthal","avatar":""},{"name":"Adrian Voo","avatar":""},{"name":"Patrick Edward Wynne","avatar":""},{"name":"Kathinka van Putten","avatar":""},{"name":"Bo Linton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
