INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chet-cung', 'Chết Cứng', 'Rigor Mortis', 'https://phimimg.com/upload/vod/20240121-1/e774b953c8f0d81427533ab4827f1970.jpg', 'https://phimimg.com/upload/vod/20240121-1/c856ac118540e91a2fefaca5bd4aad52.jpg', '<p>Chuyện kể về Tiền Tiểu Hào, một diễn viên hết thời dọn đến một khu chung cư cũ nát để tìm một nơi tự kết liễu cuộc đời vô vọng của mình. Nhưng những lần tự sát của anh luôn bị cản trở bởi những con người quái dị và cả những hồn ma đang trú ngụ trong khu chung cư này.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anthony Chan","avatar":""},{"name":"Siu-Ho Chin","avatar":""},{"name":"Kara Hui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
