INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-va-doi-giay-than-ky', 'Barbie Và Đôi Giày Thần Kỳ', 'Barbie In The Pink Shoes', 'https://phimimg.com/upload/vod/20240111-1/d937e3957542e4c9a6593278c66dc161.jpg', 'https://phimimg.com/upload/vod/20240111-1/9abdd6c9698f5e1d6bd54c9fedf4e25b.jpg', '<p>Nhảy theo cách của bạn trong một cuộc phiêu lưu kỳ diệu với Barbie trong vai Kristyn, một nữ diễn viên ba lê với những giấc mơ lớn! Khi thử một đôi giày màu hồng lấp lánh, cô và người bạn thân nhất của mình, Hailey, bị cuốn vào một thế giới múa ba lê kỳ ảo. Ở đó, Kristyn phát hiện ra rằng cô phải nhảy trong vở ba lê yêu thích của mình để đánh bại Nữ hoàng Tuyết độc ác. Với màn trình diễn vở ballet huyền thoại Giselle và Swan Lake, đó là một hành trình tuyệt vời, nơi nếu bạn khiêu vũ bằng cả trái tim, giấc mơ sẽ thành hiện thực!</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Trevor Devall","avatar":""},{"name":"Brett Dier","avatar":""},{"name":"Katie Crown","avatar":""},{"name":"Ali Liebert","avatar":""},{"name":"Bill Mondy","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
