INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-lam-nguoi-lon', 'Học Làm Người Lớn', 'The To Do List', 'https://phimimg.com/upload/vod/20240104-1/9779575d1bbc104f10a70eabc4a5368e.jpg', 'https://phimimg.com/upload/vod/20240104-1/73deb23eb27aa746045ae111eb31bd10.jpg', '<p>Brandy dù đã hoàn thành chương trình phổ thông, là người được vinh dự đọc diễn văn tốt nghiệp, nhưng kinh nghiệm trong chuyện tình yêu và cả chuyện tình dục của cô chỉ là con số 0 tròn trĩnh. Áp lực để trở thành người dày dạn kinh nhiệm trong chuyện ấy, cùng với sự giúp đỡ của chuyên gia là người chị dễ thương, nóng bỏng, cô lập ra danh sách những việc cần làm từ nụ hôn pháp, đến những chuyện kinh khủng....</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aubrey Plaza","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Bill Hader","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
