INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-ac-ma', 'Lời Nguyền Ác Ma', 'The Wicked', 'https://phimimg.com/upload/vod/20240104-1/380142821c36ed1977d2411c5c94271d.jpg', 'https://phimimg.com/upload/vod/20240104-1/59d7d0765e9246756fa69b12de88f52e.jpg', '<p>Một nhóm thanh thiếu niên thử thách truyền thuyết về một phù thủy bất tử và nhận được nhiều hơn những gì họ mong đợi. Gần đến Halloween và sáu người trẻ tuổi, sợ hãi nhưng không hề nản lòng trước câu chuyện dân gian xung quanh một ngôi nhà ma ám cũ, tìm đường đến nơi ở của Kẻ ác huyền thoại, có lẽ với hy vọng khiêu khích mụ phù thủy độc ác, nhưng rõ ràng là chưa chuẩn bị cho những gì họ chắc chắn đã gây ra.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Devon Werkheiser","avatar":""},{"name":"Nicole Forester","avatar":""},{"name":"Justin Deeley","avatar":""},{"name":"Caitlin Carmichael","avatar":""},{"name":"Cassie Keller","avatar":""},{"name":"Jamie Kaler","avatar":""},{"name":"Jess Adams","avatar":""},{"name":"Chase Maser","avatar":""},{"name":"Diana Hopper","avatar":""},{"name":"Jackelyn Gauci","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
