INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-bong-dem-thanh-pho-xuong', 'Vũ Khí Bóng Đêm: Thành Phố Xương', 'The Mortal Instruments: City Of Bones', 'https://phimimg.com/upload/vod/20240104-1/66a8cc165bf0581b55be8747753d1563.jpg', 'https://phimimg.com/upload/vod/20240104-1/8a9630822c618c10955743562b5c75f5.jpg', '<p>Clary Fray là một cô bé bình thường cho đến khi cô phát hiện ra bí mật thân thế của mình, trong người cô có phân nữa dòng máu là thiên thần. Và rồi cuộc sống của cô hoàn toàn bị đảo lộn khi mẹ cô bị một con quỷ bắt đi. Phim The Mortal Instruments: City of Bones chính là hành trình của của bé Clary đi cứu mẹ. Cô có thể nhìn thấu những bộ mặt quỷ đội lớp người ở thành phố New York nơi mà cô đang sinh sống. Bên cạnh đó, cô còn phải rèn luyện để trở thành một Shadow Hunter nới có đủ sức mạnh cứu mẹ vì bây giờ bọn quỷ càng ngày càng lớn mạnh.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lily Collins","avatar":""},{"name":"Jamie Campbell Bower","avatar":""},{"name":"Robert Sheehan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
