INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-a-phien', 'Trận Chiến Á Phiện', 'The White Storm', 'null', 'https://phimimg.com/upload/vod/20240104-1/73868bd5d75c3ca37738c0d7fa41a266.jpg', '<p>Phim kể về một cảnh sát chìm (Cổ Thiên lạc) gia nhập vào xã hội đen để triệt phá đường dây ma túy do Hắc Sài đừng đầu. Anh phải kết hợp chặt chẽ với điều tra viên của Cục Ma Túy Hong Kong (Lưu Thanh Vân) và cấp dưới của anh ta (Trương Gia Huy). Cả ba phải hợp sức trong những tình huống hiểm nghèo nhất để tìm ra tên trùm tội phạm của đường dây buôn bán ma túy xuyên quốc gia.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Ching Wan Lau","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Lik-Sun Fong","avatar":""},{"name":"Yolanda","avatar":""},{"name":"Hoi-Pang Lo","avatar":""},{"name":"Kenneth Lo Wai-Kwong","avatar":""},{"name":"Ben Lam","avatar":""},{"name":"Berg Ng","avatar":""},{"name":"Mã Dục Kha","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Elanne kwong","avatar":""},{"name":"Xingyu Shi","avatar":""},{"name":"Siu-Kei Lee","avatar":""},{"name":"维他亚·潘斯林加姆","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
