INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-den-mang', 'Mạng Đền Mạng', 'Dragonwolf', 'https://phimimg.com/upload/vod/20240104-1/121b91523e56c64d5243c6c28c15bd6a.jpg', 'https://phimimg.com/upload/vod/20240104-1/db3e25813027e1c26756d674a5277772.jpg', '<p>The Devils Cauldron, một thành phố nơi sự sa đọa và bạo lực đã tạo nên một xã hội trong đó chỉ có những kẻ nguy hiểm và nhẫn tâm mới có thể tồn tại, hai chàng trai trẻ sở hữu trí tuệ và sự hung dữ để phát triển, tự khắc tên mình là những sát thủ hiệu quả nhất và không thể ngăn cản. Sát cánh bên nhau, hai anh em này là những sát thủ nguy hiểm nhất, khiến ngay cả những tên tội phạm độc ác nhất cũng phải khiếp sợ. Nhưng khi một người phụ nữ có vẻ đẹp hiếm có bí ẩn bước vào cuộc sống của hai anh em, cô ấy đã làm họ mù quáng bằng những lời hứa ngọt ngào của mình và khiến họ chống lại nhau, dẫn đến một trận chiến hoành tráng có nguy cơ đưa Devils Cauldron đến bờ vực diệt vong.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Kazu Patrick Tang","avatar":""},{"name":"Johan Kirsten","avatar":""},{"name":"Macha Polivka","avatar":""},{"name":"Guk Srisawat","avatar":""},{"name":"Stephen Thomas","avatar":""},{"name":"Bonnie Zellerbach","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
