INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('her', 'Her', 'Her', 'https://phimimg.com/upload/vod/20240104-1/0e9366d9804c3912f03dda484dc39a8e.jpg', 'https://phimimg.com/upload/vod/20240104-1/1dcf34a7864aa3e284ab10a81b2349a4.jpg', '<p>Theodore là một nhà văn cô đơn, hướng nội, làm nghề viết thư tình cho những người gặp khó khăn trong việc biểu lộ cảm xúc. Trầm cảm và chán nản sau khi ly dị vợ - tình yêu từ thuở ấu thơ, Theodore đã rơi vào mối quan hệ với Samantha, một hệ điều hành máy tính có trí thông minh nhân tạo và khả năng học hỏi, giao tiếp như con người bình thường...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Portia Doubleday","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Kristen Wiig","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
