INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sparks', 'Sparks', 'Sparks', 'https://phimimg.com/upload/vod/20240104-1/52bfe122045a32b24e021a11d2e8bab6.jpg', 'https://phimimg.com/upload/vod/20240104-1/fc516ca5a266ed77599c070663820217.jpg', '<p>Một người canh gác đeo mặt nạ phát hiện ra mặt tối của chủ nghĩa anh hùng. Việc truy lùng siêu tội phạm khét tiếng nhất quốc gia khiến cuộc sống và danh tiếng của Spark bị hủy hoại.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chase Williamson","avatar":""},{"name":"Ashley Bell","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"William Katt","avatar":""},{"name":"Marina Squerciati","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Scott Rinker","avatar":""},{"name":"David Sobolov","avatar":""},{"name":"Larry Cedar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
