INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('germ', 'Germ', 'Germ', 'https://phimimg.com/upload/vod/20231231-1/1502923a765c322e5daad5f973e6bebb.jpg', 'https://phimimg.com/upload/vod/20231231-1/2f43f89941c7a5667cd1c93626eac47f.jpg', '<p>Nỗ lực bắn hạ một vệ tinh quay quanh quỹ đạo của quân đội đã gây ra một dịch bệnh lây truyền qua không gian tại một thị trấn nhỏ, xa xôi. Phó Max Brody và bạn gái Brooke của anh ta phải chiến đấu chống lại đội quân gồm những người dân và binh lính bị nhiễm bệnh khi họ đấu tranh để cứu bản thân và những người thân yêu của họ khỏi cái chết sớm khủng khiếp. Khi việc ăn thịt người lây lan, liệu kẻ mạnh có sống sót?</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marguerite Sundberg","avatar":""},{"name":"Michael Flores","avatar":""},{"name":"Mark Chiappone","avatar":""},{"name":"Beth Pratt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
