INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-sat-thu', 'Cỗ Máy Sát Thủ', 'The Machine', 'null', 'https://phimimg.com/upload/vod/20240102-1/ee44c6d6b3d4322925ebc7e6be279f58.jpg', '<p>Cỗ Máy Sát Thủ - The Machine là bộ phim đặt bối cảnh trong một thế giới kiệt quệ do dấn sâu vào cuộc chiến tranh lạnh với một kẻ thù mới, Bộ quốc phòng Anh đang ở trên bờ vực của một kế hoạch táo bạo nhằm phát triển một thứ vũ khí siêu hạng có thể thay đổi cục diện chiến tranh.&nbsp;&nbsp;Nhà khoa học hàng đầu Vincent McCarthy đã cung cấp giải pháp bằng phát minh của mình, “The Machine” – một người máy sinh học hình dáng con người với cơ thể có sức mạnh vô song và kỹ năng tư duy siêu đẳng. Nhưng khi chương trình thử nghiệm trục trặc trong quá trình hoạt động khiến cho một mẫu thử sơ đẳng nổi loạn và phá hủy phòng thí nghiệm, McCarthy buộc phải tuyển mộ một nữ chuyên gia trí thông minh nhân tạo nhằm giúp anh ngăn ngừa nguy cơ rủi ro từ chính cỗ máy chiến đấu có tư duy con người mà anh đã tạo ra.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Caity Lotz","avatar":""},{"name":"Denis Lawson","avatar":""},{"name":"Sam Hazeldine","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
