INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-cong-ly-2013', 'Đi Tìm Công Lý', 'Out Of The Furnace', 'https://phimimg.com/upload/vod/20240124-1/c4a69ab910be7e7a0466a13c98ce5eca.jpg', 'https://phimimg.com/upload/vod/20240124-1/418e8654e8aaa1646200f464ba2fb1d4.jpg', '<p>Phim nói về Russell Baze (Christian Bale), một công nhân có cuộc sống khó khăn, làm việc tại một nhà máy thép địa phương vào ban ngày, và phải chăm sóc người cha bị bệnh nan y hàng đêm. Rodney Russell (Casey Affleck), em trai Russell sau trở về sau nghĩa vụ quân sự ở Iraq, bị thu hút bởi những hoạt động phi pháp của các băng đảng địa phương, và rồi đột nhiên mất tích một cách bí ẩn. Khi mà cảnh sát không thể giải quyết được thì chính Russell phải tự mình dấm thân tìm lại công bằng cho em trai.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Zoe Saldana","avatar":""},{"name":"Forest Whitaker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
