INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-co-doc', 'Kỵ Sĩ Cô Độc', 'The Lone Ranger', 'https://phimimg.com/upload/vod/20240102-1/425b4761e766e25adff764b81567ed17.jpg', 'https://phimimg.com/upload/vod/20240102-1/01707d3294183e9688bf83ffe5f986eb.jpg', '<p>Dựng lại từ một câu chuyện được kể lại từ một chiến binh của người mĩ bản địa mang tên Tonto (Johnny Depp) về sự thay đổi của John Reid (Armie Hammer) - một người luôn luôn làm theo pháp luật nhưng sau khi gặp được Tonto anh đã thay đổi và trở thành một người anh hùng huyền thoại của công lí. Hầu hết các tình huống hài hước từ bộ phim đến từ hai người anh hùng với cách xử lí sự việc khác nhau nay buộc phải học cách làm việc chung để chống lại sự tham quyền đoạt lợi.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"William Fichtner","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
