INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-co-doi', 'Giáng Sinh Có Đôi', 'All I Want For Christmas', 'https://phimimg.com/upload/vod/20240128-1/5ca75737416b4b467090f063e66f68e1.jpg', 'https://phimimg.com/upload/vod/20240128-1/0b9c6f2e53dce9e0c0de9959cfbfef71.jpg', '<p>Giáng Sinh Có Đôi - All I Want For Christmas xoay quanh nhân vật Elizabeth, một giám đốc quảng cáo trẻ có sự nghiệp thăng tiến nhưng lại là người có vấn đề trong việc kết nối với mọi người. Tuy nhiên, khi gặp Calvin tại một cửa hàng trò chơi điện tử, cô nhận được một chiếc ghim chứa đựng phép thuật của Giáng sinh. Bất cứ khi nào mặc nó vào, Elizabeth có thể đọc thấu suy nghĩ của người khác. Câu hỏi đặt ra là, mặc dù có thể biết những gì mọi người muốn, nhưng cô có thực sự lắng nghe không?</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Arnold","avatar":""},{"name":"Brad Rowe","avatar":""},{"name":"Melissa Sagemiller","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
