INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-ca-dai-chien', 'Danh Ca Đại Chiến', 'Running Man', 'https://phimimg.com/upload/vod/20240102-1/a75066beabb385e1f9d51f0048d340ab.jpg', 'https://phimimg.com/upload/vod/20240102-1/db3e69111fac7192b8826fbe0b3c7fc2.jpg', '<p>Bộ phim nói về một người đàn ông tên là Jong-woo, anh ta là một ông bố trẻ nên phải làm lụng rất vất vả kể cả ngày lẫn đêm, ban ngày Jong-woo làm việc cho một Gara xe và ban đêm anh hóa thân thành một tài xế Taxi. Jong-woo làm việc vất vả với ước mơ bé nhỏ là có thể mua được một căn hộ nho nhỏ cho cuộc sống của anh và đứa con trai của mình. Cuộc sống của anh diễn ra thật bình thường thì bỗng dưng chỉ trong một đêm anh đã trở thành mục tiêu truy đuổi của cảnh sát khi họ nhận định anh là một tên giết người hàng loạt. Chứng cứ của vụ việc là họ tìm thấy một xác chết trong chiếc taxi của Jong-woo. Trước tình hình như thế, Jong-woo đành phải trốn chạy hòng tìm cách minh oan cho mình...</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sin Ha-Gyoon","avatar":""},{"name":"Eun-ji Jo","avatar":""},{"name":"Sang-ho Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
