INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-thanh-trung-phan-7', 'Lệnh Thanh Trừng (Phần 7)', 'Burn Notice (Season 7)', 'https://phimimg.com/upload/vod/20240109-1/909bb5a75a3cabe623e1cd8c42e7d53a.jpg', 'https://phimimg.com/upload/vod/20240109-1/9f6f3ebaaf1eeaf2435a6bfc028c85d3.jpg', '<p>Một điệp viên trước đây từng nằm trong danh sách đen sử dụng những kỹ năng và quá trình đào tạo độc đáo của mình để giúp đỡ mọi người trong những tình huống tuyệt vọng.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Donovan","avatar":""},{"name":"Sharon Gless","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Coby Bell","avatar":""},{"name":"Gabrielle Anwar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
