INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alpha-va-omega-2-cuoc-phieu-luu-dip-le', 'Alpha Và Omega 2: Cuộc Phiêu Lưu Dịp Lễ', 'Alpha And Omega 2: A Howl-iday Adventure', 'https://phimimg.com/upload/vod/20231231-1/4071b416a650c207eb000713bc91382a.jpg', 'https://phimimg.com/upload/vod/20231231-1/e1e03340c0dd19491201efa3713a51e4.jpg', '<p>Kate &amp; Humphrey cùng ba chú sói con (Smokey, Claudette và Runt) đang vui vẻ chuẩn bị kỷ niệm kỳ nghỉ đông đầu tiên cùng nhau thì chú sói con nhỏ nhất của họ, Runt, biến mất một cách bí ẩn. Bây giờ họ phải thực hiện một cuộc hành trình mới xuyên qua vùng hoang dã để tìm Runt trước khi lễ hội mùa đông bắt đầu ở quê nhà.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Diskin","avatar":""},{"name":"Marieve Herington","avatar":""},{"name":"Liza West","avatar":""},{"name":"Tracy Pfau","avatar":""},{"name":"Meryl Leigh","avatar":""},{"name":"Shaun Gerardo","avatar":""},{"name":"Blackie Rose","avatar":""},{"name":"G.K. Bowes","avatar":""},{"name":"Harper Fogelson","avatar":""},{"name":"Willa Fogelson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
