INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-dac-nhiem-2013', 'Lực Lượng Đặc Nhiệm', 'Force Of Execution', 'https://phimimg.com/upload/vod/20231231-1/230990b144d8a4f4dcb25dcb8514179f.jpg', 'https://phimimg.com/upload/vod/20231231-1/baab6022eb6ba2aa3363dcdd41802a2e.jpg', '<p>Seagal đóng vai ông trùm tội phạm Alexander, một ông trùm trường học cũ, người cai trị đế chế tội phạm của mình bằng cả sự cao thượng và tàn bạo. Để thực hiện một cuộc tấn công nhà tù đơn giản, anh ta cử người thi hành án tốt nhất và người bảo vệ Roman Hurst (Foster). Khi cú đánh không thành công, Hurst buộc phải trả giá cho sự thất bại của mình: bị trục xuất đến thành phố mà anh gần như từng cai trị. Nhưng một cuộc chiến tranh giành lấy linh hồn của thành phố đang nổ ra giữa Alexander, một tay xã hội đen máu lạnh được biết đến với cái tên The Iceman (Rhames) và một băng đảng Mexico tàn nhẫn. Hurst, với sự giúp đỡ của một chủ nhà hàng từng bị lừa đảo (Trejo), người có một vài động thái ẩn giấu của riêng mình, sẽ tìm lại ý chí của chính mình để sống sót trong cuộc xung đột sắp tới và trả thù những người đã đối xử tệ với anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"David House","avatar":""},{"name":"Jenny Gabrielle","avatar":""},{"name":"Bren Foster","avatar":""},{"name":"Sarah Minnich","avatar":""},{"name":"Jesus Jr.","avatar":""},{"name":"J. Anthony Pena","avatar":""},{"name":"Tait Fletcher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324461);
