INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-chi-em-va-mot-dam-cuoi', 'Bốn Chị Em Và Một Đám Cưới', 'Four Sisters And A Wedding', 'https://phimimg.com/upload/vod/20231219-1/9277403630016e8c1fc95207e15d4bbb.jpg', 'https://phimimg.com/upload/vod/20231219-1/104be4864fc8e0c37bbdce25a5ef017f.jpg', '<p>Sau nhiều năm không gặp, bốn chị em gái nhà Salazar quyết định quay trở về quê nhà khi nghe tin cậu em trai út của họ sắp kết hôn. Sum họp cùng với gia đình, những kỷ niệm ngày xưa ùa về khiến họ có cảm giác chưa chuẩn bị tinh thần việc em trai sẽ có một gia đình riêng. Liệu các cô chị sẽ làm thế nào, ngăn cản đám cưới hay phải chấp nhận sự thật?</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Bea Alonzo","avatar":""},{"name":"Angel Locsin","avatar":""},{"name":"Shaina Magdayao","avatar":""},{"name":"Toni Gonzaga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
