INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-paula-peril', 'Cuộc Phiêu Lưu Của Paula Peril', 'Paula Peril', 'null', 'https://phimimg.com/upload/vod/20240121-1/b32f4b237e986f685378ffa613b1c7d2.jpg', '<p>Bộ phim Cuộc Phiêu Lưu Của Paula Peril - Paula Peril kể về phóng viên dũng cảm Paula Peril Perillo theo chân người dẫn đường đến một nhà kho bỏ hoang, nơi cô bị tấn công bởi năm tên côn đồ tàn bạo làm việc cho tên cướp đồi bại Vince Vincelli. Sau khi chiến đấu dũng cảm, cô bị chúng khuất phục, trói buộc và đe dọa để cung cấp thông tin. Paula sắp hết lựa chọn. Liệu cô có trốn thoát kịp thời để vạch trần chiến dịch Vincelli một lần và mãi mãi?</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Marla Malcolm","avatar":""},{"name":"Stephen Hanthorn","avatar":""},{"name":"Valerie Perez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
