INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-goi-tuoi-teen', 'Gái Gọi Tuổi Teen', 'Young & Beautiful', 'https://phimimg.com/upload/vod/20231230-1/409c8d1a0ace52b5ab57e938c433651e.jpg', 'https://phimimg.com/upload/vod/20231230-1/4c501c6916d7ba63f564f951e16cfd6c.jpg', '<p>Marine Vacth vào vai cô gái mại dâm tuổi vị thành niên Isabelle đã được đề cử cho giải Cành cọ vàng tại Liên hoan phim Cannes 2013, và nhận được lời khen ngợi từ các nhà phê bình phim.Bức chân dung của một cô gái 17 tuổi sống một cuộc đời hai mặt và bí mật bẩn thỉu của cô được giấu kín.Trong một trường trung học ở Paris, khi các học sinh khác tụ tập và ngân nga bài thơ No One’s Serious at Seventeen (Chẳng ai nghiêm túc ở tuổi 17) của thi hào Arthur Rimbaud, thì nữ sinh Isabelle Bontale (Marine Vacth) dành cả buổi tối để làm bài tập và mơ mộng về các chàng trai.Sau một kỳ nghỉ Hè bên bờ biển, khi Isabelle lần đầu có trải nghiệm tình dục với một chàng trai người Đức, cô quyết định biến ham muốn ...</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Marine Vacth","avatar":""},{"name":"Géraldine Pailhas","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Frédéric Pierrot","avatar":""},{"name":"Nathalie Richard","avatar":""},{"name":"Johan Leysen","avatar":""},{"name":"Fantin Ravat","avatar":""},{"name":"Laurent Delbecque","avatar":""},{"name":"Djédjé Apali","avatar":""},{"name":"Lucas Prisor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
