INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-duc', 'Sắc Dục', 'Adore', 'https://phimimg.com/upload/vod/20231230-1/2633dff61480bca2c2b8d6f83b1bde63.jpg', 'https://phimimg.com/upload/vod/20231230-1/00ffa4743b6892a375a474019f553d48.jpg', '<p>Lil và Roz là hai người bạn suốt đời, lớn lên cùng nhau với tư cách là hàng xóm ở một thị trấn ven biển bình dị. Khi trưởng thành, các con trai của họ đã phát triển một tình bạn bền chặt như tình bạn gắn bó với mẹ của chúng. Vào một mùa hè, cả bốn người đều phải đối mặt với những cảm xúc sôi sục ngày càng lớn dần giữa họ và mỗi người đều tìm thấy niềm hạnh phúc bất ngờ trong mối quan hệ vượt qua giới hạn của quy ước.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Ben Mendelsohn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
