INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-sa-mac', 'Nắng Sa Mạc', 'Heatstroke', 'https://phimimg.com/upload/vod/20231230-1/839f4b775ab404a4fb00f522202b849c.jpg', 'https://phimimg.com/upload/vod/20231230-1/a78206765174d06036b93ba7ed16af96.jpg', '<p>Trên một chuyến đi gia đình trong các sa mạc châu Phi, họ bất ngờ bị sa vào một cuộc săn chết người của một đám người không rõ lại lịch, số phận của họ đặt trên vai thành viên nhỏ tuổi nhất...</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Calvin Hayward","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
