INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-sa-mac', 'Nắng Sa Mạc', 'Heatstroke', 'nắng sa mạc heatstroke stephen dorff warrick grier calvin hayward ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-rong-bien-troi-day', 'Địch Nhân Kiệt: Rồng Biển Trỗi Dậy', 'Young Detective Dee: Rise Of The Sea Dragon', 'https://phimimg.com/upload/vod/20231219-1/0fa8e7ca0c3e0e455ea459e528a52298.jpg', 'https://phimimg.com/upload/vod/20231219-1/91a144ea67d18e65db2d6d1e568f6005.jpg', '<p>Bộ phim là câu chuyện xoay quanh thần thám Địch Nhân Kiệt lúc còn trẻ cùng những vụ án thủy quái cướp bóc trước khi anh đi nhậm chức ở Đại Lý Tự. Nữ hoàng Võ Tắc Thiên đã hạ lệnh điều một số tàu chiến sang kinh đô của Triều Tiên để hỗ trợ nước đồng minh thân cận trong cuộc chiến chống lại quân Buyeo hung hãn. Tuy nhiên trước khi các chiến tàu này rời cảng thì chiếc tàu chỉ huy đã bị nhấn chìm bởi một thế lực vô cùng bí ẩn từ dưới đáy biển nổi lên. Nữ hoàng Võ Tắc Thiên vốn không phải là người mê tín. Bà đã hạ lệnh gọi đích danh Uý Trì Chân Kim từ hình bộ tới để điều tra vụ việc này, và hạn trong vòng 10 ngày phải tìm ra câu trả lời nếu không muốn đầu rời khỏi cổ. Tình cờ ngày hôm đó Địch Nhân Kiệt cũng đặt chân đến Lạc Dương. Cả Địch Nhân Kiệt và Uý Trì đều được chứng kiến toàn cảnh lễ rước Duệ Cơ vào đền Long Vương, và cả 2 đều bị vẻ đẹp mê hồn của nàng cuốn hút.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"Mark Chao","avatar":""},{"name":"Kun Chen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
