INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-quan-anh-hung', 'Đội Quân Anh Hùng', 'Company Of Heroes', 'https://phimimg.com/upload/vod/20231219-1/41be41a996a30541c8be503c37e6576e.jpg', 'https://phimimg.com/upload/vod/20231219-1/85abff8d2f491af366891227de09b9a1.jpg', '<p>Câu chuyện của phim kể về một biệt đội lính Mỹ bị lạc vào trong tiền tuyến quân thù sau trận Battle of the Bulge. Tình cờ họ phát hiện ra âm mưu chế tạo một quả siêu Bomb của Đức Quốc Xã. Và những chàng trai của biệt đội đã quyết định phải ngăn chặn âm mưu này.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Sizemore","avatar":""},{"name":"Alastair Mackenzie","avatar":""},{"name":"Chad Michael Collins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
