INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-la-ban-than', 'Mãi Là Bạn Thân', 'Best Friends Forever', 'https://phimimg.com/upload/vod/20231219-1/d241d59ae2caefd3562535f65f64a82c.jpg', 'https://phimimg.com/upload/vod/20231219-1/af3e2d176a8e5c59bc889ea9ab559aa9.jpg', '<p>Để đánh dấu một cột mốc quan trọng trong đời, Harriet và cô bạn thân nhất, Reba, đã quyết định thực hiện một chuyến du lịch đường bộ dài đến một vùng đất mới. Đó sẽ là một chặng đường đầy ắp những điều bất ngờ của hai cô gái.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Berg","avatar":""},{"name":"Jon Michael Davis","avatar":""},{"name":"Leslie Chappell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
