INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-chong-khung-bo', 'Lực Lượng Chống Khủng Bố', 'Closed Circuit', 'https://phimimg.com/upload/vod/20231219-1/b4ee1634c5a3fffc987facaf2aca9497.jpg', 'https://phimimg.com/upload/vod/20231219-1/bf887f5e38594b4b181d741fe20a17c7.jpg', '<p>Martin và Claudia là người yêu cũ của nhau, họ cùng tham gia một nhóm bảo vệ cho một thử nghiệm của chủ nghĩa khủng bố.khán giả sẽ được chứng kiến những màn tấn công vô cùng đặc sắc của lực lượng chống khủng bố đồng thời với những pha đấu trí thông minh nhưng cũng không kém phần hài hước của hai nhân vật chính.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Bana","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Kenneth Cranham","avatar":""},{"name":"Isaac Hempstead-Wright","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Anne-Marie Duff","avatar":""},{"name":"Riz Ahmed","avatar":""},{"name":"Denis Moschitto","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
