INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-loai-orc', 'Cuộc Chiến Loài Orc', 'Dragonfyre', 'https://phimimg.com/upload/vod/20231219-1/a6a55ed0135e9223ace1e43e3b69b1a1.jpg', 'https://phimimg.com/upload/vod/20231219-1/056bc93671b4dee163ad97af5648652b.jpg', '<p>Một cựu đặc nhiệm mệt mỏi vì chiến đấu mua một trang trại ở miền Tây nước Mỹ xa xôi để chạy trốn khỏi thế giới và gặp phải hàng loạt kẻ xâm phạm kỳ lạ, bao gồm một công chúa yêu tinh xinh đẹp, một nhà thần bí người Mỹ bản địa và lũ Orc. Khi lũ Orc xâm chiếm tài sản của anh, John phải từ bỏ sự cô lập của mình để trở thành một anh hùng, trước khi lũ Orc giải phóng thần rồng của chúng đến thế giới của chúng ta.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Masiela Lusha","avatar":""},{"name":"Clare Niederpruem","avatar":""},{"name":"Rusty Joiner","avatar":""},{"name":"Wesley John","avatar":""},{"name":"Isaac C. Singleton Jr.","avatar":""},{"name":"Maclain Nelson","avatar":""},{"name":"Jake Van Wagoner","avatar":""},{"name":"Rocky Myers","avatar":""},{"name":"Mark Brocksmith","avatar":""},{"name":"Adam Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
