INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-lao-xi-tin', 'Bô Lão Xì Tin', 'Last Vegas', 'https://phimimg.com/upload/vod/20231219-1/4aa31b2124116905b5f4b8f000e82351.jpg', 'https://phimimg.com/upload/vod/20231219-1/87342adc2f088eb9e27993e6a57cb6fe.jpg', '<p>Bô Lão Xì Tin là một bộ phim điện ảnh mang đậm chất hài hước được sản xuất tại Mỹ. Nội dung phim nói về tình bạn của 4 người đàn ông đang ở lứa tuổi về hưu, nhưng một trong số họ nổi trội nhất là Billy, tuy đã già nhưng rất phong độ và giàu có, ông mời ba người bạn thân thiết của mình đến Last Vegas để dự đám cưới của mình với cô dâu trẻ hơn mình chả chục tuổi.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Morgan Freeman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
