INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-lao-xi-tin', 'Bô Lão Xì Tin', 'Last Vegas', 'bô lão xì tin last vegas robert de niro michael douglas morgan freeman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tha-huong', 'Kẻ Tha Hương', 'The Immigrant', 'https://phimimg.com/upload/vod/20231219-1/9d19b52065051c1af0619b09e4f69b76.jpg', 'https://phimimg.com/upload/vod/20231219-1/083ab37eddad0c9be9ee173c1888b754.jpg', '<p>Kẻ Tha Hương - The Immigrant là bộ phim tâm lý tình cảm Mỹ 2013 của đạo diễn James Gray. Nội dung phim kể về con đường theo đuôi giấc mơ nước mỹ của Ewa Cybulska và chị gái Madga, họ đã rời quê hương Ba Lan thân thương đến xứ sở xa lạ New York năm 1921. Madga đột ngột bị phát hiện mình đang mắc bệnh tại đảo Ellis, từ đó cả 2 chị em bị chia rẽ. Cô em gái Ewa bị đẩy xuống ơờng phố Manhattan, còn cô chị gái Madga thì bị cách ly do bệnh tật. Sự xui xẻo chưa dừng lại ở đó với Ewa, cô đã gặp một kẻ đàn ông quyến rũ nhưng lại rất xảo quyệt, hắn đẩy cô vào con đường bán thân. May thay, sau đó không lâu, cô gặp được người em họ của Bruno, ảo thuật gia Orlando. Anh là người khiến cô rung động và là người duy nhất giúp cô thoát khỏi cuộc sống kinh tởm ấy. Liệu chị gái Madga đang sống ra sao? Hai chị em cô có còn cơ hội gặp nhau hay chăng? Và cái giá cho sự tham vọng đó của hai cô gái trẻ có phải là quá lớn?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"Jeremy Renner","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
