INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-ruoi', 'Chim Ruồi', 'Hummingbird', 'https://phimimg.com/upload/vod/20231219-1/a219906bfff85697ec7e1548bb97797d.jpg', 'https://phimimg.com/upload/vod/20231219-1/acff23164fbad15ad2a906b5bb374dfb.jpg', '<p>Hummingbird là bộ phim hành động nói về Joey, người cựu chiến binh cố gắng tạo dựng cuộc sống mới để đền bù những ám ảnh trong quá khứ. Nhưng những nỗ lực của Joey trở nên vô nghĩa khi thù hận kéo anh trượt dài vào thế giới ngầm. Số phận người cựu chiến binh sẽ đi về đâu? Tù nhân trong tay cảnh sát Luân Đôn, tay anh chị của thế giới tội phạm hay lại là kẻ không tên sống bên lề xã hội?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Agata Buzek","avatar":""},{"name":"Vicky McClure","avatar":""},{"name":"Benedict Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
