INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chim-ruoi', 'Chim Ruồi', 'Hummingbird', 'chim ruồi hummingbird jason statham agata buzek vicky mcclure benedict wong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-duong', 'Học Đường', 'Palo Alto', 'https://phimimg.com/upload/vod/20231219-1/b8725fdffca223ea623a6771990f93b5.jpg', 'https://phimimg.com/upload/vod/20231219-1/d49b0494bb62bdd173a9ac273c81ef9a.jpg', '<p>April nhút nhát, nhạy cảm trong lớp, bị giằng xé giữa cuộc tán tỉnh trái phép với huấn luyện viên bóng đá Mr. B của cô và tình yêu đơn phương với chàng trai ngọt ngào Teddy. Trong khi đó, Emily lại đưa ra những ân huệ tình dục cho mọi chàng trai bước qua con đường của cô - bao gồm cả Teddy và người bạn thân nhất của anh ta là Fred, một sợi dây trực tiếp không có bộ lọc hay ranh giới. Khi bữa tiệc trung học kéo dài đến bữa tiệc tiếp theo — April và Teddy đấu tranh để thừa nhận tình cảm chung của họ — sự liều lĩnh ngày càng leo thang của Fred bắt đầu rơi vào hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Roberts","avatar":""},{"name":"Jack Kilmer","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"James Franco","avatar":""},{"name":"Zoe Levin","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Keegan Allen","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Margaret Qualley","avatar":""},{"name":"Colleen Camp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
