INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-duoc-mot-nam', 'Chỉ Được Một Năm', 'I Give It A Year', 'https://phimimg.com/upload/vod/20231230-1/fa47db3984492a682ac82a9c763575ca.jpg', 'https://phimimg.com/upload/vod/20231230-1/eea2e43bfbc9111e7ce8dc971fd79f9b.jpg', '<p>Sau một thời gian tán tỉnh nhanh chóng, hai người yêu nhau vội vàng quyết định kết hôn. Khi năm đầu tiên của cuộc hôn nhân diễn ra, sự cám dỗ và sự không tương thích khiến mối quan hệ của họ gặp nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rafe Spall","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Jane Asher","avatar":""},{"name":"Tim Key","avatar":""},{"name":"Nigel Planer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
