INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chien-z', 'Thế Chiến Z', 'World War Z', 'null', 'https://phimimg.com/upload/vod/20230910-1/c22f13113f394fdf5d1900acdfc9766a.jpg', '<p>Cuộc sống của cựu điều tra viên Liên Hợp Quốc Gerry Lane và gia đình anh có vẻ hài lòng. Đột nhiên, thế giới bị cản trở bởi một bệnh nhiễm trùng bí ẩn biến toàn bộ quần thể loài người thành những thây ma vô tâm hung hãn. Sau khi thoát khỏi sự hỗn loạn, Lane được thuyết phục thực hiện nhiệm vụ điều tra căn bệnh này. Tiếp theo là một chuyến đi đầy nguy hiểm vòng quanh thế giới, nơi Lane phải bất chấp những nguy hiểm khủng khiếp và những khó khăn dài để tìm ra câu trả lời trước khi nền văn minh của loài người sụp đổ.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Daniella Kertesz","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Ludi Boeken","avatar":""},{"name":"Matthew Fox","avatar":""},{"name":"Fana Mokoena","avatar":""},{"name":"David Morse","avatar":""},{"name":"Elyes Gabel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
