INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-danh-du', 'Tình Yêu Và Danh Dự', 'Love And Honor', 'https://phimimg.com/upload/vod/20231227-1/30dd88771d54eee19976f79aa3614f2d.jpg', 'https://phimimg.com/upload/vod/20231227-1/f0535106a3e73f27ae35ce161cc2bb94.jpg', '<p>Khi một người lính trẻ ở Việt Nam bị cô gái quê hương của mình ruồng bỏ, anh và người bạn thân nhất của mình quyết định đi AWOL và quay trở lại Hoa Kỳ để giành lại cô ấy.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Hemsworth","avatar":""},{"name":"Austin Stowell","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Aimee Teegarden","avatar":""},{"name":"Chris Lowell","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
