INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-dai-danh-bo-2', 'Tứ Đại Danh Bổ 2', 'The Four 2', 'https://phimimg.com/upload/vod/20231219-1/326a992147decfb350708b11f5cba8d3.jpg', 'https://phimimg.com/upload/vod/20231219-1/a604c5827fd13d437888209a36e3df58.jpg', '<p>Tiếp nối chuyện yêu đương với Lãnh Huyết trong phần đầu, Vô Tình sẽ phải đối mặt với các đối thủ “nặng ký” là Như Yên và Cơ Dao Hoa. Trong phần này, thảm án diệt môn của nhà Vô Tình cũng dần hé lộ. Vô Tình vừa chịu nỗi đau mất người yêu, vừa ôm trong lòng mối hận tìm ra kẻ đã sát hại cả nhà mình. Tuy có nhiều lúc bị đặt trong hoàn cảnh trớ trêu nhưng với lòng can đảm, Vô Tình đã từng bước vạch trần sự thật, tìm ra kẻ thủ ác núp sau vỏ bọc hiền lành.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Jiang Yiyan","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Wu Xiubo","avatar":""},{"name":"Liu Yan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
