INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-nay-lua', 'Cuộc Chiến Nảy Lửa', 'The Heat', 'https://phimimg.com/upload/vod/20231219-1/b4c7f40c1e5d7f07137225566ca425ac.jpg', 'https://phimimg.com/upload/vod/20231219-1/96aaf26d6aedac832cffef3e5d89dd38.jpg', '<p>Đặc vụ đặc biệt của FBI Sarah Ashburn, người luôn trong trạng thái căng thẳng được ghép nhóm với nữ cảnh sát Boston hay giận dỗi Shannon Mullins trong vụ săn tìm gã trùm ma túy tàn nhẫn. Điều gì sẽ xảy ra khi ghép đôi 2 người phụ nữ mà không ai đã từng có cộng sự hay một người bạn nào theo đúng nghĩa của nó?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Michael McDonald","avatar":""},{"name":"Melissa McCarthy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
