INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ngoc-vuot-thoi-gian', 'Bảo Ngọc Vượt Thời Gian', 'Rubinrot', 'https://phimimg.com/upload/vod/20231219-1/ec999425232932ac1e0ec94b4e72a9c0.jpg', 'https://phimimg.com/upload/vod/20231219-1/c93a4f914e4fed4380598d8810ab4446.jpg', '<p>Gwendolyn Shepherd là một cô gái 16 tuổi bình thường nhưng gia đình cô nắm giữ một bí mật: Gen du hành thời gian được biểu hiện trong tộc được thừa hưởng, nhưng không phải thành viên nào trong gia đình cũng được ban phước. Mọi người đều chắc chắn rằng Charlotte, em họ của Gwen có gen này. Tuy nhiên, một ngày nào đó Gwendolyn đột nhiên thấy mình ở London vào cuối thế kỷ 19 và nhận ra rằng chính cô, người sinh ra là một nhà du hành thời gian. Tuy không hào hứng lắm nhưng cô ấy sẽ làm mọi cách có thể để giải quyết những bí ẩn cổ xưa về viên hồng ngọc.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Maria Ehrich","avatar":""},{"name":"Jannis Niewöhner","avatar":""},{"name":"Laura Berlin","avatar":""},{"name":"Uwe Kockisch","avatar":""},{"name":"Josefine Preuss","avatar":""},{"name":"Florian Bartholomäi","avatar":""},{"name":"Katharina Thalbach","avatar":""},{"name":"Veronica Ferres","avatar":""},{"name":"Anna Böttcher","avatar":""},{"name":"Sibylle Canonica","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
