INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trong-giang-ho-trat-tu-moi', 'Người Trong Giang Hồ: Trật Tự Mới', 'Young And Dangerous: Reloaded', 'https://phimimg.com/upload/vod/20231219-1/b566d80eac19313c50dfa5c7475be89b.jpg', 'https://phimimg.com/upload/vod/20231219-1/bd4f38476b71ba0ac33efc8a092c7ae8.jpg', '<p>Phim kể về những tay gian hồ xứ Hồng Kong mới nhất nỗi loạn chém giết lẫn nhau, những vụ thanh toán của các tay chân đàn anh, đàn em và các thế lực của Đoàn Gia. Trong đó nổi lên là cuộc tranh giành quyền lực của băng hội Hồng Hưng, một bang đang nắm giữ khu vực cầu cảng, và đang bị các bang nhóm khác ở đây gây sóng gió.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Him Law","avatar":""},{"name":"Oscar Leung","avatar":""},{"name":"Alex Lam Chi Sin","avatar":""},{"name":"Sammy Sum Chun-Hin","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Jacquelin Ch''ng","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Denise Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324461);
