INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-vo-toan-thuan', 'Tình Yêu Vô Toàn Thuận', 'Campus Confidential', 'https://phimimg.com/upload/vod/20231215-1/6de01b7b3dbbee1528ad4fa344fc753f.jpg', 'https://phimimg.com/upload/vod/20231215-1/773850368c528c569faf50aa3e4e838f.jpg', '<p>Chàng trai đam mê học đường đã giải cứu cô gái hấp dẫn nhất trong khuôn viên trường khỏi một hồ nước khô sau khi cô rơi xuống. Truyền thuyết kể rằng nếu hai người gặp nhau ở hồ khi nước cạn, họ sẽ yêu nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Bo-lin Chen","avatar":""},{"name":"Ivy Yi-Han Chen","avatar":""},{"name":"Shu-yao Kuo","avatar":""},{"name":"Paul Chiang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
