INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chot-chan-cuoi-cung', 'Chốt Chặn Cuối Cùng', 'The Last Stand', 'https://phimimg.com/upload/vod/20231214-1/e22c5459a9fa0449b1780265d68f82e2.jpg', 'https://phimimg.com/upload/vod/20231214-1/c08e4c6af80f512e7311607c7483c830.jpg', '<p>Cảnh sát trưởng Ray Owens đã rời khỏi Los Angeles và chuyển tới công tác tại một thị trấn vùng biên Sommerton Junction yên tĩnh. Tuy nhiên, cuộc sống yên bình của người dân nơi đây đã bị xáo trộn hoàn toàn khi Gabriel Cortez tên trùm buôn lậu khét tiếng nhất Tây bán cầu đã thực hiện thành công một cuộc đào tẩu mạo hiểm nhưng vô cùng ngoạn mục khỏi tay của FBI. Với sự trợ giúp của một nhóm những kẻ sống ngoài vòng pháp luật Cortez đã bắt theo một con tin và bắt đầu hành trình chạy trốn của mình hướng về biên giới Mỹ - Mexico.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Johnny Knoxville","avatar":""},{"name":"Jaimie Alexander","avatar":""},{"name":"Forest Whitaker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
