INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-ac-goi-cam', 'Thần Ác Gợi Cảm', 'Sexy Evil Genius', 'https://phimimg.com/upload/vod/20231214-1/050fd7d1fd881d2e07abf1b82764710b.jpg', 'https://phimimg.com/upload/vod/20231214-1/e0c021dffc74a70efdd4c3a75f867a19.jpg', '<p>Một bộ phim hài đen tối kể về một nhóm người lạ theo phong cách chiết trung được người yêu cũ của cả hai, Nikki Franklyn, mời đến một quán bar ở trung tâm thành phố, một phụ nữ trẻ cực kỳ gợi cảm, khó đoán và có thể mất trí, người vừa mới ra tù vì tội giết người bạn trai cũ cuối cùng của mình. Bữa tiệc thực sự bắt đầu khi chính Nikki đến, kéo theo người yêu và vị hôn thê mới nhất của cô, luật sư bị thách thức về mặt đạo đức, người đã xử lý vụ án của cô. Cô ấy bí ẩn về ý định của mình và những người yêu hiện tại và trước đây của cô ấy sớm nhận ra rằng tất cả họ đều bị cuốn vào một trong những trò chơi trí tuệ tinh quái, xuất sắc của cô ấy với những hậu quả chết người có thể xảy ra. Vào cuối đêm, sự trả thù sẽ được thực hiện, mối tình lãng mạn mới sẽ nảy nở và Nikki sẽ mang lại danh tiếng là Thiên tài Ác ma Gợi cảm.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Seth Green","avatar":""},{"name":"Michelle Trachtenberg","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"William Baldwin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
