INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-equestria', 'Những Cô Gái Equestria', 'My Little Pony: Equestria Girls', 'https://phimimg.com/upload/vod/20231213-1/7ee43bc7534fc0715b1c8bf087bbd2e7.jpg', 'https://phimimg.com/upload/vod/20231213-1/0b06d2126d382b5fca9e38d9b09456f3.jpg', '<p>Thông qua một chiếc gương ma thuật, Twilight Sparkle du hành vào một vũ trụ thay thế để lấy lại chiếc vương miện đã bị đánh cắp từ Đế chế Pha lê. Khi đến nơi, cô kinh hoàng khi biết rằng mình đã biến thành người.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tara Strong","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Cathy Weseluck","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
