INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cho-2-su-noi-gian-cua-dan-con', 'Người Chó 2: Sự Nổi Giận Của Đàn Con', 'Dogman 2', 'null', 'https://phimimg.com/upload/vod/20231213-1/20fae3c18ac6d68daf06497e41bea1f4.jpg', '<p>Bộ phim Người Chó 2: Sự Nổi Giận Của Đàn Con - Dogman 2 lấy bối cảnh một năm kể từ khi Người Chó khủng bố cộng đồng vùng Trung Tây này, và sự kiện kinh hoàng dường như đã trở thành lịch sử. Tuy nhiên, ẩn nấp trong khu rừng là một lứa chó con Người Chó đã trưởng thành hoàn toàn mà ngay cả mẹ của chúng cũng biết chúng là một mối đe doạ khủng khiếp có thể làm xáo trộn cuộc sống nơi đây một lần nữa.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
