INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-luc-nua-dem', 'Trước Lúc Nửa Đêm', 'Before Midnight', 'https://phimimg.com/upload/vod/20231213-1/0fa695e7c9272423fb23d672cb7a08cb.jpg', 'https://phimimg.com/upload/vod/20231213-1/3d5870432746746e8c6eb7fbcbc3027f.jpg', '<p>Đã chín năm kể từ lần cuối chúng tôi gặp Jesse và Celine, cặp vợ chồng người Pháp người Mỹ đã từng gặp một chuyến tàu ở Vienna. Bây giờ họ sống ở Paris với hai con gái sinh đôi, nhưng đã dành một mùa hè ở Hy Lạp về lời mời của một người đồng nghiệp tác giả của Jesse. Khi kỳ nghỉ kết thúc và Jesse phải gửi con trai tuổi teen của mình đến Hoa Kỳ, anh ta bắt đầu đặt câu hỏi về các quyết định đời sống của mình, và mối quan hệ của anh ta với Celine có nguy cơ.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324461);
