INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-may-bay', 'Thế Giới Máy Bay', 'Planes', 'https://phimimg.com/upload/vod/20231212-1/1dfc97d4699b3984ea8de6c036c30016.jpg', 'https://phimimg.com/upload/vod/20231212-1/35f564560d9efde6f4b4395552e402e6.jpg', '<p>Chuyện phim kể về Dusty - một chiếc máy bay cánh quạt cũ, rỉ sét nhưng luôn mơ mộng được tham gia vào một cuộc đua máy bay vòng quanh thế giới khủng nhất từ trước đến nay. Nhưng oái oăm ở chỗ, Dusty lại mắc bệnh sợ độ cao. Và với sự giúp đỡ, ủng hộ của một phi đội với những nhân vật mới toe và hài hước, Dusty đã dang rộng đôi cánh đến với thử thách lớn nhất trong cuộc đời.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carlos Alazraqui","avatar":""},{"name":"Dane Cook","avatar":""},{"name":"Stacy Keach","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
