INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dai-ton-su', 'Nhất Đại Tôn Sư', 'The Grandmaster', 'https://phimimg.com/upload/vod/20231211-1/a72fcbb88de5d074d8d5be43b910e0af.jpg', 'https://phimimg.com/upload/vod/20231211-1/5e50c411bac4d65f82927f4cf746f0c8.jpg', '<p>Bộ phim kể về Diệp Vấn, một trong những bậc thầy về võ thuật Trung Hoa. Đây cũng là vai diễn nổi tiếng trong phim bộ cùng tên có diễn xuất của ngôi sao võ thuật Chân Tử Đan. Diệp Vấn là người sáng lập ra môn phái Vịnh Xuân Quyền và có rất nhiều học trò xuất sắc, trong đó có Lý Tiểu Long (Bruce Lee). Nhất đại tông sư (The Grand Masters) có tông đen chủ đạo, nhân vật “Nhất đại tông sư” Diệp Vấn của Lương Triều Vỹ (Tony Leung) đội mũ trắng, đi giày sắt, một mình đối đầu với đám đông kẻ thù. Đạo diễn Vương Gia Vệ sử dụng hiệu ứng nước trong suốt và sáng màu trên nền trang phục và khung cảnh đen tối, đồng thời quay chậm để làm cảnh phim trông ấn tượng hết sức có thể. Có thể thấy rõ từng bọt nước tung lên sau cú đá của Lương Triều Vỹ....</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Chiu Wai Leung","avatar":""},{"name":"Ziyi Zhang","avatar":""},{"name":"Jin Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
