INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-doi-khi-toi-gap-em', 'Thay Đổi Khi Tôi Gặp Em', 'The Necessary Death Of Charlie Countryman', 'https://phimimg.com/upload/vod/20240108-1/c9802aa8d8057b9bcb78c7525cf36e8e.jpg', 'https://phimimg.com/upload/vod/20240108-1/3716e61cbd31a6c08afb86394aacf752.jpg', '<p>Phim kể về Charlie Countryman (LaBeouf) chỉ là một chàng trai bình thường cho đến khi anh gặp và đem lòng yêu Gabi, một cô gái Rumani sau khi ông ngồi bên cạnh cha mình trên một chiếc máy bay dẫn đến cái chết của ông. Nhưng Gabi kết hôn với Nigel (Mikkelsen), một trùm tội phạm bạo lực và tinh thần không ổn định với một nhóm côn đồ theo ý của mình. Được trang bị với ít hơn trí thông minh của mình và quyến rũ ngây thơ, Charlie chịu đựng một nhịp bầm tím xuống sau khi khác để thu hút Gabi và giữ cô ta ra khỏi con đường nguy hiểm. Xem Phim Charlie Countryman Cuối cùng khai thác của mình về lòng dũng cảm mù tạo ra một mớ hỗn độn như vậy mà ông còn lại chỉ có một lối thoát, để cứu cô gái trong mộng của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Mads Mikkelsen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
