INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-can-phong-bi-an', 'Giải Mã Căn Phòng Bí Ẩn', 'Banshee Chapter', 'https://phimimg.com/upload/vod/20231211-1/892304c4c99fbeaeebedee135e858331.jpg', 'https://phimimg.com/upload/vod/20231211-1/b028599f07f5ce4a0bfb51751f9737f9.jpg', '<p>Lần theo dấu vết của một người bạn mất tích, người đã thử nghiệm thuốc thay đổi tâm trí, một nhà báo trẻ - được hỗ trợ bởi một nhà văn phản văn hóa lưu manh, The Silence of The Lambs - thấy mình bị lôi kéo vào thế giới nguy hiểm của chính phủ tối mật. nghiên cứu và bí ẩn của một tín hiệu vô tuyến nhiễu không rõ nguồn gốc. Là một bộ phim kinh dị có nhịp độ nhanh pha trộn giữa thực tế và viễn tưởng, Banshee Chapter dựa trên các tài liệu có thật, lời khai của đối tượng thử nghiệm thực tế và những bí mật được khám phá về các chương trình bí mật do CIA điều hành.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ted Levine","avatar":""},{"name":"Katia Winter","avatar":""},{"name":"Michael McMillian","avatar":""},{"name":"Monique Candelaria","avatar":""},{"name":"Jenny Gabrielle","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
