INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-3', 'Sát Nhân 3', 'Murder 3', 'https://phimimg.com/upload/vod/20231211-1/3856c9fd771c1445749d59356c2440c1.jpg', 'https://phimimg.com/upload/vod/20231211-1/e4f4afbab53c2ebc92d092022677221b.jpg', '<p>Một nhiếp ảnh gia thời trang và động vật hoang dã nóng bỏng Vikram có mối quan hệ với Nisha. Cô chuyển đến sống cùng anh trong ngôi nhà nguy nga của anh ở ngoại ô thành phố. Ngôi nhà thế giới cũ, được xây dựng từ nhiều thập kỷ trước vừa đẹp vừa đáng sợ. Nó chứa đựng nhiều bí mật mà Nisha sẽ sớm khám phá ra; về cuộc đời của người đàn ông đã tạo ra nó và của Vikram, người đang đối phó với sự mất tích bí ẩn của bạn gái cũ Roshni</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Randeep Hooda","avatar":""},{"name":"Aditi Rao Hydari","avatar":""},{"name":"Sara Loren","avatar":""},{"name":"Rajesh Shringapure","avatar":""},{"name":"Bugs Bhargava","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
