INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('steinsgate-the-movie-load-region-of-deja-vu', 'Steins;Gate: The Movie - Load Region Of Déjà Vu', 'Steins;Gate: The Movie - Load Region Of Déjà Vu', 'https://phimimg.com/upload/vod/20231211-1/f36f8311a7f8afa800ea26d06e6b5c04.jpg', 'https://phimimg.com/upload/vod/20231211-1/fc817e4dc74bfcfddc315910af347d14.jpg', '<p>Sau các sự kiện của anime, Rintarou bắt đầu cảm thấy hậu quả của thời gian du lịch rộng rãi, và cuối cùng hoàn toàn mờ dần khỏi thực tế. Kurisu, là người bạn đồng hành duy nhất nhớ đến anh ta, bây giờ phải tìm cách đưa anh ta trở lại.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
