INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-maisie-da-biet', 'Thứ Maisie Đã Biết', 'What Maisie Knew', 'https://phimimg.com/upload/vod/20231211-1/fda26b25ff0fae2395eb52a3b6d679b9.jpg', 'https://phimimg.com/upload/vod/20231211-1/f8940d07e52df75a93a560a0422f4c12.jpg', '<p>Chuyển thể từ cuốn tiểu thuyết cùng tên, phim Thứ Maisie Đã Biết là một bộ phim tình cảm xã hội được nhiều khán giả yêu thích bởi đó là câu chuyện tình cảm của cha mẹ và con cái giữa thực tại của xã hội hiện đại, náo nhiệt. Xem phim online này bạn sẽ thấy một cặp vợ chồng vừa mới ly dị, vì cuốn theo nhịp sống đô thị xô bồ ấy nên cũng chẳng thể tự tay chăm sóc đứa con của mình một cách tử tế được. Ngay những phút đầu tiên của bộ phim ta thấy họ xuất hiện trong tinh thần hoảng loạn sau cuộc hôn nhân đổ vỡ. Như những đứa trẻ, cả hai dùng mọi biện pháp để tranh giành quyền được nuôi Maisie. Họ không ngần ngại làm mọi điều để thể hiện tình cảm của mình dành cho con gái là nhiều hơn, ngay cả việc tiến thêm bước nữa. Mời các bạn cùng chú ý đón theo dõi phim Thứ Maisie Đã Biết.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Steve Coogan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
