INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-ba-dao', 'Mùa Hè Bá Đạo', 'The Kings Of Summer', 'https://phimimg.com/upload/vod/20231211-1/c5ea14b1c30428d2dd662292c7229c10.jpg', 'https://phimimg.com/upload/vod/20231211-1/49f425d7f204e9f5caeab06e27d54cd3.jpg', '<p>Ba người bạn Joe, Patrick và Biaggio, quyết định rời khỏi các gia đình rối loạn chức năng của họ và sống một cuộc sống bị cô lập trong rừng. Cuối cùng họ biết rằng người ta không thể chạy trốn khỏi gia đình của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Robinson","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Erin Moriarty","avatar":""},{"name":"Craig Cackowski","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Megan Mullally","avatar":""},{"name":"Marc Evan Jackson","avatar":""},{"name":"William Sonnie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
