INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-bang-kinh-hoang-2', 'Đoạn Băng Kinh Hoàng 2', 'V/H/S/2', 'https://phimimg.com/upload/vod/20231211-1/c2d48f0ca74171f6d9313fea81a5487c.jpg', 'https://phimimg.com/upload/vod/20231211-1/e54b9045d41267fe20e3f5a03d8c8ee2.jpg', '<p>Hai thám tử tư trong khi quá trình tìm kiếm một sinh viên mất tích một cách bí ẩn, khi họ đột nhập vào một căn nhà thì phát hiện ra một cuộn băng bí ẩn. Sau khi xem nội dung cuốn băng họ phát hiện ra một sự thật kinh hoàng, những chuyện khủng khiếp gì đang chờ đợi họ...</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lawrence Michael Levine","avatar":""},{"name":"Kelsy Abbott","avatar":""},{"name":"Adam Wingard","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
