INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-van-cau-chuyen-cuoi-nhat-phan-1', 'Mười Vạn Câu Chuyện Cười Nhạt (Phần 1)', 'One Hundred Thousand Bad Jokes (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/5a38e31a0e6d929e859cdb6c5dc865a8.jpg', 'https://phimimg.com/upload/vod/20231219-1/54473f67119db934bf8c9f95d9398214.jpg', '<p>Mười Vạn Câu Chuyện Cười Nhạt (Phần 1) vietsub | One Hundred Thousand Bad Jokes (Season 1) vietsub là một bộ phim hoạt hình chuyển thể từ tác phẩm truyện tranh hài hước cùng tên của tác giả Hàn Vũ. Phim được đánh giá là tác phẩm thổi luồng gió mới vào phong cách sáng tác của ngành truyện tranh, hoạt hình Trung Quốc. Các nhân vật quen thuộc như Lý Tịnh, Na Tra, Công chúa Bạch Tuyết, Pinocchio, Hồ Lô hay siêu nhân... được kể theo phong cách hoàn toàn mới lạ.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 15, 2013, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324461);
