INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dai-tranh-dau', 'Võ Đài Tranh Đấu', 'Unbeatable', 'https://phimimg.com/upload/vod/20231211-1/f342c59e5d0f410aa9a967fec6a27163.jpg', 'https://phimimg.com/upload/vod/20231211-1/12219b21729f4cc3e267ba88be6aac87.jpg', '<p>Bộ phim Võ Đài Tranh Đấu thể hiện tinh thần chiến đấu và sự khắc nghiệt của bộ môn quyền anh. Bô phim kể về hai thầy trò Trình Huy và Tư Tề đều lâm vào cảnh nợ nần, vì có năng khiếu trong môn thể thao này nên hai người quyết định tập luyện khổ cực để có thể chiến thắng trong các giải đấu mặc dù đối thủ của họ đều là những người to lớn và hung hãn. Bộ phim thể hiện chân thật bộ môn quyền anh,...</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Singh Hartihan Bitto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
