INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ragnarok', 'Huyền Thoại Ragnarok', 'Ragnarok', 'https://phimimg.com/upload/vod/20231211-1/1b622926881226636f92a03b07993552.jpg', 'https://phimimg.com/upload/vod/20231211-1/41ee9e062112c98528a80ba83c2620f1.jpg', '<p>Nhà khảo cổ học Sigurd Svendsen phát hiện ra rằng con tàu Oseberg ẩn giấu một bí mật từ Thời đại Viking. Cùng với hai đứa con của mình, Sigurd bắt đầu hành trình tìm kiếm sự thật. Bí ẩn dẫn họ đến No Mans Land giữa Na Uy và Nga, nơi không có người đàn ông nào du hành trong thời hiện đại. Những chữ rune cũ mang ý nghĩa mới khi bí mật mà chúng khám phá ra đáng sợ hơn bất cứ ai có thể tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Pål Sverre Hagen","avatar":""},{"name":"Nicolai Cleve Broch","avatar":""},{"name":"Sofia Helin","avatar":""},{"name":"Bjørn Sundquist","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
