INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-ao-trang', 'Thiên Thần Áo Trắng', 'Good Doctor', 'https://phimimg.com/upload/vod/20231219-1/aaf2e8bc96252128ac2f31ebbdf071c9.jpg', 'https://phimimg.com/upload/vod/20231219-1/484517a12beb3038779904ffa504fc5b.jpg', '<p>Bộ phim Good Doctor nói về một người đàn ông trẻ tuổi tên Park Shi On mắc chứng bệnh Savant và chậm phát triển. Tuổi trí tuệ của anh là 10 nhưng anh đã trở thành một bác sĩ phẫu thuật cho trẻ em. Trong khi đó, Kim Do Han bác sĩ phẫu thuật cho trẻ em tốt nhất luôn tìm thấy mình trong cuộc đối đầu với Park Shi On.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Joo Won","avatar":""},{"name":"Choi Ro Woon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
