INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ra-khoi-inferno', 'Ra Khỏi Inferno', 'Out Of Inferno', 'null', 'https://phimimg.com/upload/vod/20231211-1/6f2f1282345442b1dc2d2e099a5a9d83.jpg', '<p>Một sự cố hỏa hoạn nghiêm trọng xảy ra với một tòa tháp thương mại sầm uất. Bên trong tòa nhà, Keung, người làm công việc cứu hỏa, nhanh chóng tổ chức một cuộc sơ tán. Nhưng ngọn lửa lan nhanh ra tất cả các ngóc ngách của tòa nhà. Trong khi đó, Tai-kwan, người đã làm việc với Keung trước đây, là đội trưởng Đội cứu hỏa. Và vợ anh ta đang gặp một bác sĩ phụ khoa trong tòa nhà. Tai-kwan cử đơn vị của mình đến chữa cháy ngay sau khi nhận được cảnh báo. Thảm họa chưa từng có đã kết nối lại Tai-kwan và Keung, hai người đã trở nên xa lạ với nhau trong nhiều năm.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Angelica Lee","avatar":""},{"name":"Sinje Lee","avatar":""},{"name":"Ching Wan Lau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
