INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paranoia', 'Paranoia', 'Paranoia', 'https://phimimg.com/upload/vod/20231211-1/7c54c273a5b908806dd1c68b3ab4350a.jpg', 'https://phimimg.com/upload/vod/20231211-1/23fe0005371f205ea9c953e2a140f7d8.jpg', '<p>Một nhân viên cấp thấp tại một tập đoàn hùng mạnh thấy mình đang chiếm giữ một văn phòng ở góc phố, nhưng với một cái giá nguy hiểm - anh ta phải theo dõi người cố vấn cũ của sếp mình để đảm bảo cho ông ta lợi thế trị giá hàng tỷ đô la.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Hemsworth","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Josh Holloway","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Angela Sarafyan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
