INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lap-di-2013', 'Kẻ Lập Dị', 'The Best Offer', 'https://phimimg.com/upload/vod/20231211-1/dfd555d6c51685e3255b692a63a2114a.jpg', 'https://phimimg.com/upload/vod/20231211-1/be303cc4ca0444a551573d52dca83da4.jpg', '<p>Virgil Oldman là một nhà sưu tập tranh, ông sở hữu những tác phẩm của các danh họa tài ba trên thế giới mà các viện bảo tàng ước muốn. Ông dành hết thời gian cho nghệ thuật cho đến khi gặp được Claire, một cô gái bí ẩn. Một hôm trên đường trở về nhà, Oldman bị đánh cướp. Ông được cô chăm sóc chu đáo, men tình thêm nồng ấm, trái tim biết yêu ở tuổi xế chiều càng thêm rộn ràng. Thế nhưng đến một buổi sáng khi Oldman mở cửa phòng trưng bày thì tất cả các bộ sưu tập cá nhân của mình và Claire đều biến mất.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Geoffrey Rush","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Sylvia Hoeks","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Maximilian Dirr","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
