INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-ong-gia-noel', 'Giải Cứu Ông Già Noel', 'Saving Santa', 'https://phimimg.com/upload/vod/20231211-1/1cbfb4f4bf12d153833b2737419bc22a.jpg', 'https://phimimg.com/upload/vod/20231211-1/2d49b7975ef8c08754011aa336a871e3.jpg', '<p>Một yêu tinh có mức độ ổn định thấp phát hiện ra rằng anh ta là người duy nhất có thể ngăn chặn cuộc xâm lược Bắc Cực bằng cách sử dụng bí mật của Santas Sleigh, TimeGlobe, để du hành ngược thời gian để cứu ông già Noel - hai lần.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Freeman","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Tim Conway","avatar":""},{"name":"Pam Ferris","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Joan Collins","avatar":""},{"name":"David Cowgill","avatar":""},{"name":"Noel Clarke","avatar":""},{"name":"Newell Alexander","avatar":""},{"name":"Moosie Drier","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
