INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-ket-bat-ngo', 'Đoạn Kết Bất Ngờ', 'Not Another Happy Ending', 'https://phimimg.com/upload/vod/20231211-1/af0f7ff1ac253d352c79b6911d3c2b77.jpg', 'https://phimimg.com/upload/vod/20231211-1/f32c0c95bf8062c13fc945b65458398c.jpg', '<p>Khi một nhà xuất bản đang gặp khó khăn phát hiện ra tác giả thành công duy nhất của mình bị chặn, anh ấy biết rằng mình phải bỏ chặn cô ấy hoặc anh ấy sẽ kết thúc. Với thành công mới đạt được, cô ấy trở nên quá hạnh phúc và không thể viết khi cô ấy hạnh phúc. Rắc rối duy nhất là, anh ấy càng khiến cô ấy cảm thấy tồi tệ bao nhiêu thì anh ấy càng nhận ra rằng mình yêu cô ấy bấy nhiêu.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Karen Gillan","avatar":""},{"name":"Stanley Weber","avatar":""},{"name":"Iain De Caestecker","avatar":""},{"name":"Henry Ian Cusick","avatar":""},{"name":"Kate Dickie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
