INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('matru-va-dan-lang-mandola', 'MaTru Và Dân Làng Mandola', 'Matru Ki Bijlee Ka Mandola', 'https://phimimg.com/upload/vod/20231211-1/9b68b536032c5d2f083c02781d26f28f.jpg', 'https://phimimg.com/upload/vod/20231211-1/ca8312c4459f15c3fa3c793eedca60f1.jpg', '<p>Harry là một nhà công nghiệp yêu con gái Bijlee của mình và mối quan hệ họ chia sẻ với người đàn ông thứ sáu của Harry, Matru. Tuy nhiên, kế hoạch kết hôn với con trai của một chính trị gia của Bijlee đã mang đến những khúc ngoặt trong cuộc đời của Matru, Bijlee và Mandola.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Anushka Sharma","avatar":""},{"name":"Imran Khan","avatar":""},{"name":"Pankaj Kapur","avatar":""},{"name":"Shabana Azmi","avatar":""},{"name":"Arya Babbar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
