INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('door-to-the-night', 'Door To The Night', 'Door To The Night', 'https://phimimg.com/upload/vod/20231231-1/e4d4b73a38dee86d76a759ec478249e3.jpg', 'https://phimimg.com/upload/vod/20231231-1/1f9614193d8b9c0cd012cc2a9cc0540d.jpg', '<p>Jong-sup, người đã tự mình nuôi con trai mình sau khi vợ chết, cũng mất con trai mình đến một tai nạn đáng tiếc. Sau đó, anh ta phát hiện ra anh ta bị ung thư và chỉ có 6 tháng để sống. Jong-sup không muốn mất phẩm phẩm cho đến lúc anh ta chết để anh ta thuê một người chăm sóc là Yeon-hwa. Nhìn thấy cô ấy thực hiện tất cả các yêu cầu kén chọn của anh ấy, Jong-sup cảm thấy bị thu hút bởi cô ấy và nó phát triển đủ lớn để đánh thức mong muốn trong anh ấy. Tuy nhiên, mặc dù Jong-sup, Yeon-Hwa làm anh suy yếu hơn nữa bằng cách ngày càng quyến rũ với mọi khoảnh khắc. Ngay khi Jong-sup quyết định anh ta không thể lấy nó nữa, anh ta phải đối mặt với một sự thật không thể tin được.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
