INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cuoi-cung', 'Ngày Cuối Cùng', 'The Last Days', 'https://phimimg.com/upload/vod/20231211-1/8dcbb35252fae3e2be0d31a4ab030f02.jpg', 'https://phimimg.com/upload/vod/20231211-1/b8174fd8e240fbd398b822d9cc4a9069.jpg', '<p>2013; Một dịch bệnh bí ẩn lây lan khắp hành tinh. Nhân loại phát triển nỗi sợ hãi phi lý trước những không gian rộng mở, có thể gây ra cái chết ngay lập tức. Chẳng mấy chốc, dân số thế giới bị mắc kẹt bên trong các tòa nhà. Khi Barcelona rơi vào tình trạng hỗn loạn, Marc bắt đầu hành trình tìm kiếm Julia, bạn gái mất tích của anh mà không hề ra ngoài.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Quim Gutiérrez","avatar":""},{"name":"Jose Coronado","avatar":""},{"name":"Marta Etura","avatar":""},{"name":"Leticia Dolera","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
