INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-canh-sat', 'Viên Cảnh Sát', 'Officer Down 2013', 'https://phimimg.com/upload/vod/20231211-1/169ab1427bc6079f50daa5a8747971b2.jpg', 'https://phimimg.com/upload/vod/20231211-1/bf4f5ce20a1b299ad4a2cb3eeea5164b.jpg', '<p>Nội dung phim xoay quanh quá khứ của một người cảnh sát. Quá khứ đó với rất nhiều những bi kịch và nỗi buồn. Anh ta phải đối mặt và mọi thứ luôn luẩn quẩn làm anh ta rất khó khăn để vượt qua... Trong khi đó công việc và cuộc sống là một sự khó khăn với anh. Tội phạm ngày càng gia tăng khiến anh lâm vào bế tắc khi làm việc.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"David Boreanaz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324461);
