INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu', 'Phi Vụ', 'On The Job', 'https://phimimg.com/upload/vod/20231211-1/04f4e932cc07b668bcdf2cc952da9733.jpg', 'https://phimimg.com/upload/vod/20231211-1/25199dd8db2f2441da929c0e3511bc5c.jpg', '<p>Một câu chuyện ly kỳ về 4 người đàn ông đang đấu tranh để tồn tại và nuôi sống bản thân và những người thân. Hai trong số đó là cựu tù; 1 là sát thủ giết thuê, 2 là nhân viên tư pháp bị bắt vì tội tham nhũng. Mario quyết định làm việc đàng hoàng khi ông được tạm tha. Daniel là tù nhân trẻ hơn và đệ tử của Mario, được chọn để thay thế ông đi làm nhiệm vụ. Joaquin và Francis là 2 sĩ quan cảnh sát đang rắc rối với vấn đề đạo đức. Và 2 bên không tránh khỏi nhưng xung đột, va chạm …</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Joel Torre","avatar":""},{"name":"Gerald Anderson","avatar":""},{"name":"Piolo Pascual","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
