INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-hoac-chet', 'Đua Hoặc Chết', 'The Human Race', 'https://phimimg.com/upload/vod/20231208-1/ee824b1b5bea2a4b0d345b168449a32c.jpg', 'https://phimimg.com/upload/vod/20231208-1/71b12083c67f7e06d50b39c7b5c89e86.jpg', '<p>Trong một khoảnh khắc, khoảng 80 người đang đi bộ trên một con phố lớn của thành phố. Đột nhiên, một ánh sáng chói lòa xuất hiện đưa họ đến một đường đua rất đặc biệt. Một giọng nói vang lên trong đầu mọi người: “Trường học, ngôi nhà và nhà tù đều an toàn. Thực hiện theo các mũi tên hoặc bạn sẽ chết. Ở trên con đường hoặc bạn sẽ chết. Nếu bạn nhân đôi hai lần, bạn sẽ chết. Đừng chạm vào cỏ nếu không bạn sẽ chết. Đua hoặc chết.” Dù bạn giàu hay nghèo, già hay trẻ, đui mù, khỏe mạnh, tật nguyền, dũng cảm hay hèn nhát; các quy tắc không phân biệt. Chỉ có thể có một người chiến thắng!</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul McCarthy-Boyington","avatar":""},{"name":"Eddie McGee","avatar":""},{"name":"Brianna Lauren Jackson","avatar":""},{"name":"B. Anthony Cohen","avatar":""},{"name":"Trista Robinson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
