INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tru-ta-cuoi-cung-phan-2', 'Lễ Trừ Tà Cuối Cùng: Phần 2', 'The Last Exorcism Part II', 'https://phimimg.com/upload/vod/20231210-1/4d347ebf09c00f96986a694134803799.jpg', 'https://phimimg.com/upload/vod/20231210-1/9964bbc06a982f09dd6731917af35038.jpg', '<p>Khi Nell Sweetzer cố gắng xây dựng một cuộc sống mới sau các sự kiện của phần phim đầu tiên, thế lực tà ác đã từng chiếm hữu cô quay trở lại với một kế hoạch thậm chí còn khủng khiếp hơn.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Bell","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"Andrew Sensenig","avatar":""},{"name":"Spencer Treat Clark","avatar":""},{"name":"Judd Lormand","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
