INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tren-mai-nha', 'Tình Yêu Trên Mái Nhà', 'The Rooftop', 'https://phimimg.com/upload/vod/20231210-1/430e44871101bd30d19e7765bd3b11e3.jpg', 'https://phimimg.com/upload/vod/20231210-1/60136b35f2edc1a19b171d6e533b37da.jpg', '<p>Phim Tình Yêu Trên Nóc Nhà lấy bối cảnh xã hội Trung Quốc vào những năm 1970, Châu Kiệt Luân rất chăm chút cho đứa con tinh thần mới của mình bằng những cảnh quay đậm chất khiêu vũ chính thống, âm nhạc và thêm một chút gia vị của võ thuật và đua xe.Vốn dĩ là ca sỹ nên Châu Kiệt Luân rất chú trọng vào yếu tố âm nhạc của bộ phim và anh muốn nó thật hoàn hảo.Trong phim Châu Kiệt Luân sẽ giữ vai trò đạo diễn kiêm diễn viên chính.Sau khi bộ phim Tình Yêu Trên Nóc Nhà hoàn thành thì đây cũng là bộ phim điện ảnh thứ 2 mà Châu Kiệt Luân giữ vai trò đạo diễn, tuy nhiên anh cho biết mình vẫn không thể nào thoát khỏi sự căng cứng về mặt tâm lý cũng như những lo lắng về bộ phim.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jay Chou","avatar":""},{"name":"Tăng Chí Vĩ","avatar":""},{"name":"Xueqi Wang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
