INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-bong-dem-tro-lai-phan-2', 'Kỵ Sĩ Bóng Đêm Trở Lại (Phần 2)', 'Batman: The Dark Knight Returns, Part 2', 'https://phimimg.com/upload/vod/20231208-1/e512ceebe82fd16a48cf60d74843abd1.jpg', 'https://phimimg.com/upload/vod/20231208-1/c441ab0f0a6dc2e62a2722f236b5c899.jpg', '<p>Người dơi đã trở lại sau khi vắng mặt 10 năm. Chính quyền Gotham muốn bắt giữ anh ta. Một kẻ thù già muốn một cuộc hội ngộ. Các liên đoàn muốn người đàn ông của ngày mai để ngăn chặn anh ta.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
