INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-buoc-cung-khung-long', 'Dạo Bước Cùng Khủng Long', 'Walking With Dinosaurs 3D', 'https://phimimg.com/upload/vod/20231209-1/f077bd35b06c099041d40a147837618d.jpg', 'https://phimimg.com/upload/vod/20231209-1/5ec7a251e1c23b6c022f451f13520aca.jpg', '<p>Walking with Dinosaurs 3D là một bộ phim mô tả các nhân vật khủng long 3D giống như thật lấy bối cảnh là những bức ảnh chân thực đưa khán giả đến thế giới tiền sử khi nó tồn tại 70 triệu năm trước. Bộ phim dựa trên miniseries truyền hình tài liệu năm 1999 Walking with Dinosaurs, do BBC sản xuất. Walking with Dinosaurs 3D được sản xuất bởi Evergreen Studios, công ty sản xuất Happy Feet, và được phát hành vào ngày 11 tháng 10 năm 2013.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Rowe","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Angourie Rice","avatar":""},{"name":"John Leguizamo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
