INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tri-cua-tinh-yeu', 'Giá Trị Của Tình Yêu', 'The Look Of Love', 'https://phimimg.com/upload/vod/20231209-1/b437a891350c42a9a1c57dc82dd2899b.jpg', 'https://phimimg.com/upload/vod/20231209-1/971aee40924901a114f022691d07c7cb.jpg', '<p>Paul Raymond xây dựng đế chế khiêu dâm, giải trí và bất động sản giúp ông trở thành người đàn ông giàu có nhất nước Anh, nhưng ma túy đã hủy diệt cô con gái yêu quý của ông, Debbie.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Steve Coogan","avatar":""},{"name":"Anna Friel","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Tamsin Egerton","avatar":""},{"name":"Chris Addison","avatar":""},{"name":"James Lance","avatar":""},{"name":"Simon Bird","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Kieran O''Brien","avatar":""},{"name":"David Walliams","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
