INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tan-cong-la-mat', 'Kẻ Tấn Công Lạ Mặt', 'Absolute Deception', 'https://phimimg.com/upload/vod/20231208-1/3b557b2c159e2fd7664f56d188067ef0.jpg', 'https://phimimg.com/upload/vod/20231208-1/cd1fabc98fa794a0cc042c06f97b6673.jpg', '<p>Khi một nữ phóng viên góa chồng hợp tác với Đặc vụ Liên bang để giải quyết bí ẩn về cuộc sống hai mặt của người chồng đã qua đời của Miles, một kẻ gian lớn đã được thả ra khỏi tù và tìm kiếm số tiền mà Miles đã đánh cắp từ anh ta. Người phóng viên và đặc vụ FBI bị mắc kẹt trong làn đạn, trong khi mối tình lãng mạn nở rộ trong câu chuyện ly kỳ về sự lừa dối, sợ hãi và dối trá này.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
