INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-dai-chien-2', 'Mỹ Nhân Đại Chiến 2', 'My Lucky Star', 'https://phimimg.com/upload/vod/20231208-1/07993a33ee359277ab8cb9ec47e96dca.jpg', 'https://phimimg.com/upload/vod/20231208-1/a251b745288c9e1096f8283c1eb85f5d.jpg', '<p>Bộ phim xoay quanh nhân vật nữ chính Tô Phi (Chương Tử Di đóng) một cô gái ngây thơ, hồn nhiên có sở thích vẽ tryện tranh.Hiện đang là một nhân viên bán vé may bay.Tô Phi vẫn luôn mơ mộng một ngày nào đó chàng hoàng tử trong truyện tranh sẽ xuất hiện và đưa cô thoát khỏi cuộc sống tẻ nhạt của mình.Tô Phi tình cờ trúng thưởng một chuyến du lịch Singapore và bị 2 người bạn thân là Lí Lệ (Diêu Thần đóng), Lục Tiểu Tịch (Lâm Tâm Như đóng) cho leo cây vì vậy cô đã phải đến Singapore du lịch một mình.Ở đây cô đã gặp được Đại Vệ (Vương Lực Hoành đóng) một điệp viên đang thực hiện nhiệm vụ.Tô Phi hết sức kinh ngạc khi Đại Vệ giống hệt chàng Hoàng Tử trong truyện tranh của cô...</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ziyi Zhang","avatar":""},{"name":"Leehom Wang","avatar":""},{"name":"Ruby Lin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
