INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-huyen-bi', 'Gia Tộc Huyền Bí', 'Beautiful Creatures 2013', 'https://phimimg.com/upload/vod/20231208-1/70d12a8a44ed56e0b4c837f272ff9a7b.jpg', 'https://phimimg.com/upload/vod/20231208-1/177bd7194e62808bdddf2a2acdb28a2c.jpg', '<p>Phim xoay quanh việc chàng trai trẻ Ethan luôn muốn rời khỏi thị trấn nhỏ ở miền Nam mà anh luôn cho là tẻ nhạt của mình cho đến khi anh gặp Lena – cô gái bí ẩn mới chuyển đến thị trấn. Tình yêu của họ vừa chớm nở đã gặp phải những hiểm nguy, cấm cản đến từ lời nguyền cổ xưa của gia tộc Dark. Và khi những bí ẩn vừa được hé mở thì cũng là lúc cuộc chiến giữa Ánh sáng và Bóng Tối, giữa cái Thiện và cái Ác bắt đầu..</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alice Englert","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Emma Thompson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
