INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-nghiet-nga', 'Sự Thật Nghiệt Ngã', 'Raanjhanaa', 'https://phimimg.com/upload/vod/20231208-1/c2d288b5a8fc91f0c7991017c48f5a87.jpg', 'https://phimimg.com/upload/vod/20231208-1/05c483798a8491ea52d9f364c672f35b.jpg', '<p>Kundan Shankar là con trai duy nhất của một gia đình người Tamil theo đạo Hindu sống ở Varanasi. Ngay từ thuở thơ ấu Kundan đã nảy sinh tình cảm đơn phương mãnh liệt với một cô gái đạo Hồi tên Zoya ở khu phố bên. Kundan luôn cố gắng tiếp cận Zoya nhưng luôn bị ăn tát. Zoya vì cảm động về tình cảm của Kundan đã đổi ý, nhưng khi bố mẹ cô phát hiện nên nhất quyết gửi cô đi học xa nhà. Tám năm sau Zoya trở về, Kundan tiếp tục tỏ tình nhưng Zoya miễn cưỡng, nói rằng hai đạo khác nhau. Kundan dù biết Zoya đã yêu người khác, vốn là một lãnh đạo sinh viên, ở trường đại học nhưng vì yêu cô nên vẫn giúp cô và chàng trai đó được chấp thuận làm đám cưới. Vào ngày cưới Kundan biết được sự thật rằng anh ta là người đạo Sikh. Sự thật này đã làm lễ cưới hôm đó bị phá hủy, Zoya đã cắt tay tự vẫn còn Jasjeet, chàng trai đó bị người trong làng đánh đập dã man. Bản thân Kundan quên mất lễ cưới của mình ngày hôm đó nên đã bị bố mẹ đuổi khỏi nhà. Để chuộc lại lỗi lầm, Kundan đưa Zoya đến Punjab tìm Jasjeet, biết được rằng Jasjeet đã không qua khỏi. Zoya trở về trường đại học thay Jasjeet tiếp tục lãnh đạo Đảng vì nhân dân Ấn Độ của Jasjeet, chuẩn bị cho cuộc tranh cử sắp tới. Kundan đã xin gia nhập Đảng này và với mưu mẹo của mình, anh đã giúp Đảng giành được nhiều phiếu bầu và trở thành lãnh đạo của Đảng. Điều đó khiến Zoya không phục. Trong những ngày cuối cùng của cuộc tranh cử, Zoya do vẫn căm ghét Kundan nên đã nghe theo lời của một chính trị gia, lừa Kundan vào một cuộc biểu tình và bị bắn...</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Dhanush","avatar":""},{"name":"Sonam Kapoor","avatar":""},{"name":"Abhay Deol","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
