INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho-2', 'Vũ Điệu Đường Phố 2', 'StreetDance: All Stars', 'https://phimimg.com/upload/vod/20231208-1/879cc73412b24f1c882110abdd28b547.jpg', 'https://phimimg.com/upload/vod/20231208-1/95e43e7d2926524a4914e5204c0289ca.jpg', '<p>Sau khi thất bại thảm hại trước nhóm nhảy Invincible,&nbsp;vũ công đường phố Ash (Hentschel) đã tìm kiếm những người giỏi nhất đến từ khắp nơi trên thế giới, tập hợp lại để tiếp tục cho 1 trận tái đấu. Liệu với đam mê và khát khao chiến thằng, Ash có thể dành chiến thắng?</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Akai Osei-Mansfield","avatar":""},{"name":"Ashley Jensen","avatar":""},{"name":"Theo Stevenson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
