INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('inside-llewyn-davis', 'Inside Llewyn Davis', 'Inside Llewyn Davis', 'https://phimimg.com/upload/vod/20231208-1/ac24a73e24b2d743cdf01184f0bff5d1.jpg', 'https://phimimg.com/upload/vod/20231208-1/51ec7696d1a2393964c0c02c35c05fa0.jpg', '<p>Bộ phim kể lại quãng thời gian đúng một tuần của anh chàng ca sĩ kiêm sáng tác nhạc Folk Llewyn Davis. Cũng giống như các nghệ sỹ tự do khác, Llewyn Davis đang phải vật lộn với cuộc sống vừa để nuôi thân vừa tìm cách phát triển sự nghiệp. Trong một tuần đó, anh chạy đôn chạy đáo để kiếm từng đồng, trình diễn ở phòng trà, thậm chí chẳng có nhà cửa mà phải nhờ vào bạn bè.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Jerry Grayson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
