INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-lop-hoc', 'Nữ Hoàng Lớp Học', 'The Queens Classroom', 'https://phimimg.com/upload/vod/20231207-1/3c3af762814426b0afb699a57ac38148.jpg', 'https://phimimg.com/upload/vod/20231207-1/7137ad45d62c8b276672074ed1131efc.jpg', '<p>Cô giáo chính trong phim Lớp Học Của Nữ Vương là Ma Yeo Jin là người lạnh lùng, có cách dạy đặc biệt, cô có nhiệm vụ là phải cảm hóa được những học sinh cứng đầu của lớp 6/3 này. Liệu Ma Yeo Jin sẽ làm gì với những học trò rắc rối này? Bọn chúng sẽ được cảm hóa với phương thức dạy học kia hay cô phải chịu bó tay trước những trò tinh ranh của đám học trò?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2013, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hyang Gi","avatar":""},{"name":"Kim Sae Ron","avatar":""},{"name":"Ko Hyun Jung","avatar":""},{"name":"Yoon Yeo Jung","avatar":""},{"name":"Lee Ki Young","avatar":""},{"name":"Jung Suk Yong","avatar":""},{"name":"Chun Bo Geun","avatar":""},{"name":"Seo Shin Ae","avatar":""},{"name":"Lee Young Yoo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
