INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-so-vo', 'Điệp Viên Sợ Vợ', 'The Spy: Undercover Operation', 'https://phimimg.com/upload/vod/20231208-1/da2620542263cd45a24995bd694c606f.jpg', 'https://phimimg.com/upload/vod/20231208-1/0c4e919331fbb4958c886c063c4e0c94.jpg', '<p>Phim Điệp Viên Sợ Vợ - The Spy: Undercover Operation kể về Chul-Soo, một đặc vụ ngầm tài ba với một điểm yếu duy nhất, cô vơ tiếp viên hàng không tò mò và không hề biết gì về công việc của chồng. Trong điệp vụ mới nhất, Chul-Soo dối vợ sang Busan, nhưng thực chất là sang Bangkok điều tra kẻ tình nghi. Tại đây , bất ngờ anh gặp vợ mình đang đi cùng kẻ tình nghi điển trai. Những tình huống dở khóc dở cười liên tục xảy ra khi Chul-Soo vừa phải hoàn thành nhiệm vụ vừa phải bảo vệ cô vợ yêu dấu của mình… Đến với Điệp Viên Sợ Vợ, khán giả sẽ có dịp trải qua những giây phút vừa gây cấn vừa hài hước cùng những nhân vật tiếng tăm của điện ảnh xứ kim chi như Sol Kyung-gu, Moon So-ri và đặc biệt là mỹ nam người Mỹ gốc Hàn Daniel Henney.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kyung-gu Sol","avatar":""},{"name":"So-ri Moon","avatar":""},{"name":"Daniel Henney","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
