INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2013', 'Báo Thù', 'Oldboy', 'https://phimimg.com/upload/vod/20231206-1/a6ecca57b0f4a35bce28de9a3d39d0b9.jpg', 'https://phimimg.com/upload/vod/20231206-1/625643d6bed2b56274bbb21adaea7b38.jpg', '<p>Phiên bản điện ảnh Hollywood của bộ phim Hàn Quốc cùng tên từng tạo được ấn tượng mạnh mẽ với khán giả toàn cầu. Joe Doucett là một nhân viên quảng cáo bị bắt cóc và giam cầm trong suốt 20 năm. Sau chừng ấy năm, ông bất ngờ được thả ra và suy nghĩ đầu tiên của Joe là tìm ra những kẻ đã nhốt mình để trả thù và cả đứa con gái suốt 20 năm ông luôn ao ước được gặp.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Brolin","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Lance Reddick","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
