INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-triet-hoc', 'Nhà Triết Học', 'After the Dark', 'https://phimimg.com/upload/vod/20231205-1/beab8418c46912003fa9c7ef9f1f8540.jpg', 'https://phimimg.com/upload/vod/20231205-1/c972ebfd9f13ba9f8b6f6c0aa86c39c1.jpg', '<p>Tại một trường quốc tế ở Jakarta, một giáo viên triết học thách thức lớp 20 học sinh cuối cấp sắp tốt nghiệp của mình chọn ra mười người trong số họ sẽ trú ẩn dưới lòng đất và khởi động lại loài người trong trường hợp xảy ra ngày tận thế hạt nhân.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James D''Arcy","avatar":""},{"name":"Sophie Lowe","avatar":""},{"name":"Rhys Wakefield","avatar":""},{"name":"Bonnie Wright","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Abhi Sinha","avatar":""},{"name":"Freddie Stroma","avatar":""},{"name":"Katie Findlay","avatar":""},{"name":"George Blagden","avatar":""},{"name":"Jacob Artist","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324461);
