INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tron-tim', 'Trò Chơi Trốn Tìm', 'Hide and Seek', 'https://phimimg.com/upload/vod/20231205-1/2ba615c9a3ff6b42c0c2572cacc1c1b0.jpg', 'https://phimimg.com/upload/vod/20231205-1/c85e2af2b58cd6103e590b6f90703097.jpg', '<p>Sung-soo có mọi thứ mà một người đàn ông có thể mong muốn: một người vợ xinh đẹp và những đứa con xinh xắn, một ngôi nhà tiện nghi và một chiếc xe hơi sang trọng, và rất nhiều tiền trong ngân hàng. Khi biết rằng người anh xa lạ của mình, Sung-chul, đã mất tích, những ký ức ám ảnh về quá khứ rắc rối của họ thôi thúc anh đến thăm căn hộ của anh trai mình để tìm kiếm câu trả lời.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Jeong Joon-won","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
