INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-an-thit-nguoi', 'Kẻ Ăn Thịt Người', 'Cannibal', 'https://phimimg.com/upload/vod/20231203-1/09dec5a09adea91d396c7f943748797c.jpg', 'https://phimimg.com/upload/vod/20231203-1/823622d3b0674a158f3029186a1ebc1a.jpg', '<p>Carlos là thợ may uy tín nhất ở Granada, nhưng anh ta cũng là một kẻ sát nhân trong bóng tối. Anh không cảm thấy hối hận, không có lỗi, cho đến khi Nina xuất hiện trong cuộc sống của anh và tình yêu thức tỉnh.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Antonio de la Torre","avatar":""},{"name":"María Alfonsa Rosso","avatar":""},{"name":"Olimpia Melinte","avatar":""},{"name":"Joaquín Núñez","avatar":""},{"name":"Delphine Tempels","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324461);
