INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cua-bac-si', 'Ngày Của Bác Sĩ', 'The Day of the Doctor', 'https://phimimg.com/upload/vod/20231204-1/5fa26d995e91b4121f90b93cf8dffa81.jpg', 'https://phimimg.com/upload/vod/20231204-1/587427e312f16eb8b7f4eed8a163f228.jpg', '<p>Năm 2013, có một điều gì đó kinh khủng đã xảy ra tại Triển lãm Quốc Gia tại London. Năm 1562 có một vụ giết người đã xảy ra vào thời nữ hoàng Elizabeth, và trong mớ không-thời gian đó, mộ cuộc chiến vẫn âm thầm diễn ra và đang đi đến kết thúc....</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matt Smith","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Christopher Eccleston","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
