INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('darkroom', 'Darkroom', 'Darkroom', 'https://phimimg.com/upload/vod/20231204-1/a0b92d4c9518253bc654991c854c746e.jpg', 'https://phimimg.com/upload/vod/20231204-1/f0e541f7ddf36b739c7c789df6463c13.jpg', '<p>Michelle giết chết ba người bạn của mình trong một vụ tai nạn xe hơi kinh hoàng khi đang lái xe trong tình trạng say xỉn. Sau khi cai nghiện, Michelle nhận một công việc do cố vấn của cô giới thiệu, khiến cô bị mắc kẹt trong một biệt thự với ba anh chị em tâm thần và phải tra tấn thể xác để thanh tẩy tội lỗi của Michelle.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kaylee DeFer","avatar":""},{"name":"Elisabeth Röhm","avatar":""},{"name":"Christian Campbell","avatar":""},{"name":"Tobias Segal","avatar":""},{"name":"Natalie Knepp","avatar":""},{"name":"Geneva Carr","avatar":""},{"name":"Heléne Yorke","avatar":""},{"name":"Britne Oldford","avatar":""},{"name":"Bess Rous","avatar":""},{"name":"Michael Sirow","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
