INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhen-mong-to', 'Nhện Mông To', 'Big Ass Spider!', 'https://phimimg.com/upload/vod/20231204-1/0e5312412da19de442eb0e7af7956db3.jpg', 'https://phimimg.com/upload/vod/20231204-1/3560c9b145c07e4b91950b600b6a1911.jpg', '<p>Khi một con nhện khổng lồ ngoài hành tinh trốn thoát khỏi phòng thí nghiệm quân sự và hoành hành khắp thành phố Los Angeles, một kẻ tiêu diệt thông minh và người bạn đồng hành bảo vệ của anh ta phải tiêu diệt sinh vật này trước khi toàn bộ thành phố bị phá hủy.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Greg Grunberg","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Clare Kramer","avatar":""},{"name":"Ray Wise","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Patrick Bauchau","avatar":""},{"name":"Ruben Pla","avatar":""},{"name":"Alexis Kendra","avatar":""},{"name":"Bob Bledsoe","avatar":""},{"name":"Bobby C. King","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324461);
