INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-noi-loan-phan-1', 'Tuổi Nổi Loạn (Phần 1)', 'Hormornes (Season 1)', 'https://phimimg.com/upload/vod/20231203-1/4afaf63860cb6789532bd69a53d88740.jpg', 'https://phimimg.com/upload/vod/20231203-1/3fc1764d255b52ab6da6647507d68d17.jpg', '<p>Bộ phim kể về cuộc sống và các mối quan hệ của một nhóm học sinh trung học trong cuộc sống gia đình và phải đối mặt với các vấn đề khác nhau. Học sinh trung học ở Bangkok vật lộn với các vấn đề như tình dục, mang thai tuổi vị thành niên, đồng tính luyến ái, ma túy,...</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 15, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Peach Pachara","avatar":""},{"name":"Pattie Ungsumalynn Sirapatsakmetha","avatar":""},{"name":"Kao Supassara Thanachart","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
