INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-tung-phan-3', 'Tố Tụng (Phần 3)', 'Suits (Season 3)', 'https://phimimg.com/upload/vod/20231203-1/58181894a547d8c7c2bd57c1e82c3b5f.jpg', 'https://phimimg.com/upload/vod/20231203-1/90fe221b3214d5d9597724656813a7f4.jpg', '<p>Suit – Season 3 (Tố Tụng 3) tiếp nối thành công của 2 phần trước. Sự xuất hiện một nữ hoàng sắc đẹp, là giám đốc điều hành của một công ty xăng dầu Rossington đang phải đối mặt với vụ kiện đã đem đến cho Harvey một vụ kiện tụng mới và có phần khó khăn khi cô đặt hết niềm tin vụ kiện vào Harvey. Thêm vào đó, sự xuất hiện của Stephen Huntley, cánh tay phải của Edward Darby đã làm cho tình hình tại công ty ngày càng phức tạp.</p>', 'Hoàn tất (16/16)', 16, 'series', 'completed', 15, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Gina Torres","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
