INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-cua-belle-va-sebastian', 'Tình Bạn Của Belle Và Sebastian', 'Belle and Sebastian', 'https://phimimg.com/upload/vod/20231201-1/eb21b1e4162bcf4792282913f5b0dc8e.jpg', 'https://phimimg.com/upload/vod/20231201-1/a2dda1c165cf937994f0303a2897dbb7.jpg', '<p>Belle And Sebastien là bộ phim cảm động và nhiều cảm xúc về tình yêu thương giữa một cậu bé mồ côi và một con chó hoang ở vùng núi Alpes. Một cậu bé dũng cảm đứng ra bảo vệ con chó bị xem là thú dữ đối với mọi người thợ săn trong làng và bị lùng bắt dữ dội. Một con thú dữ chỉ tấn công người khác vì tự vệ, vì nỗi sợ khi bị đe dọa. Một con chó xả thân nhảy vào nguy hiểm để cứu bạn và những người bạn của bạn. Cậu bé mồ côi, sống lang thang một mình, được một ông già César cưu mang và chăm lo như con đẻ. Một cậu bé không có bạn, kết thân với một con chó hoang không chủ và trở nên thân thiết, khắng khít, bền chặt. Chúng yêu thương nhau và bảo vệ nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Félix Bossuet","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Dimitri Storoge","avatar":""},{"name":"Mehdi El Glaoui","avatar":""},{"name":"Andreas Pietschmann","avatar":""},{"name":"Urbain Cancelier","avatar":""},{"name":"Margaux Chatelier","avatar":""},{"name":"Paloma Palma","avatar":""},{"name":"Karine Adrover","avatar":""},{"name":"Loïc Varraut","avatar":""},{"name":"Jan Oliver Schroeder","avatar":""},{"name":"Tom Sommerlatte","avatar":""},{"name":"Andrée Damant","avatar":""},{"name":"Pasquale D''Inca","avatar":""},{"name":"Eric Soubelet","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
