INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-ban-cua-belle-va-sebastian', 'Tình Bạn Của Belle Và Sebastian', 'Belle and Sebastian', 'tình bạn của belle và sebastian belle and sebastian félix bossuet tchéky karyo dimitri storoge mehdi el glaoui andreas pietschmann urbain cancelier margaux chatelier paloma palma karine adrover loïc varraut jan oliver schroeder tom sommerlatte andrée damant pasquale d''inca eric soubelet ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('make-me-shudder', 'Make Me Shudder', 'Make Me Shudder', 'https://phimimg.com/upload/vod/20231201-1/e4c9515b78235466e42a1cc08045f1c7.jpg', 'https://phimimg.com/upload/vod/20231201-1/6baf578e739e6c74db0a50a571fe5200.jpg', '<p>Trong thời gian nghỉ học, có một quy tắc là học sinh phải rời khỏi ký túc xá của trường để trở về nhà. Tuy nhiên, một nhóm sinh viên thích đến những nơi bị ma ám để thách thức những con ma, đã tập hợp băng nhóm của họ cho một thử thách khác. Địa điểm họ chọn là Tòa nhà Daeng, nơi có lịch sử là địa điểm tự sát bi thảm của một học sinh. Sau vụ tự sát, tòa nhà bị bỏ hoang và trở nên hạn chế đối với tất cả sinh viên. Không đắn đo suy nghĩ, cả nhóm quyết định khám phá nơi này và thách thức những sinh vật siêu nhiên ở đó để &quot;làm chúng rùng mình&quot;, dẫn đến một chuỗi sự kiện kinh hoàng và khó quên.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Kunatip Pinpradub","avatar":""},{"name":"Kittipat Samantrakulchai","avatar":""},{"name":"Bhuripat Vejvongsatechavat","avatar":""},{"name":"Withawat Thaokhamlue","avatar":""},{"name":"Ritthichai Tasarika","avatar":""},{"name":"Worrachai Sirikongsuwan","avatar":""},{"name":"Supakit Amornthitipong","avatar":""},{"name":"Brian Richard Garton","avatar":""},{"name":"Siraphop Manithikhun","avatar":""},{"name":"Patharawarin Timkul","avatar":""},{"name":"Chutcha Rujinanon","avatar":""},{"name":"Pitipo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
