INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-hublot', 'Ngài Hublot', 'Mr Hublot', 'https://phimimg.com/upload/vod/20231130-1/e46f82a60ec8e489fd893185d3b8f15f.jpg', 'https://phimimg.com/upload/vod/20231130-1/754693efa33aeabd4baaa157b3cf60d8.jpg', '<p>Phim Ngài Hublot- Mr Hublot 2013: Ông Hublot là một nhân vật bị thu hồi, đặc sắc với OCD, sợ thay đổi và thế giới bên ngoài. Sự xuất hiện của Robot Pet khiến cuộc đời của anh ta bị lộn ngược: anh ta phải chia sẻ nhà của mình với người bạn đồng hành xâm lấn này.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324461);
