INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-nay-van-yeu-em', 'Mai Này Vẫn Yêu Em', 'Will You Still Love Me Tomorrow?', 'https://phimimg.com/upload/vod/20231130-1/7813c5ab1df04e142db787578c395597.jpg', 'https://phimimg.com/upload/vod/20231130-1/b9087b2afcc9b0f08bd6535a35b841b7.jpg', '<p>Weichung hướng nội đã kết hôn với Feng được chín năm. Họ có với nhau một con trai và Feng muốn có thêm một đứa con nữa. Một ngày nọ, Stephen, một người bạn cũ hiện đang tổ chức đám cưới, xuất hiện và khuyến khích Weichung quay lại cuộc sống đồng tính trước đây. Lo lắng vì sợ mất vợ, Weichung ngập ngừng bắt đầu hẹn hò với một tiếp viên hàng không sau lưng Feng.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Richie Jen","avatar":""},{"name":"Mavis Fan","avatar":""},{"name":"Shih Chin-Hang","avatar":""},{"name":"Hsia Yu-chiao","avatar":""},{"name":"Lawrence Ko","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Wei-Ning Chang","avatar":""},{"name":"Gabriel Lan","avatar":""},{"name":"Kao Yu-Shan","avatar":""},{"name":"Ching-Pu Tan","avatar":""},{"name":"Jane Lee","avatar":""},{"name":"Wen-Wen Yang","avatar":""},{"name":"Hsing-Chen Yeh","avatar":""},{"name":"Shao-Huai Chang","avatar":""},{"name":"Alan Chen","avatar":""},{"name":"Yi-Che Chien","avatar":""},{"name":"Vivi Lee","avatar":""},{"name":"Tzu-Chien Tseng","avatar":""},{"name":"KaKa","avatar":""},{"name":"Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324461);
