INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('5-nam-danh-mat', '5 Năm Đánh Mất', 'The Stolen Years', 'https://phimimg.com/upload/vod/20231130-1/0e1f1e05d79098d97a13512e3296851c.jpg', 'https://phimimg.com/upload/vod/20231130-1/94d5588d24845a1ef04ef7bf68db8df4.jpg', '<p>Hà Mạn tỉnh dậy sau cơn hôn mê và nghĩ rằng cô vẫn đang hưởng tuần trăng mật với chồng Xie Yu, nhưng cô nhận được một cú sốc nặng nề: ký ức của cô có khoảng cách 5 năm và trong thời gian đó cặp đôi đã ly hôn. Bối rối và tuyệt vọng khi không biết cuộc hôn nhân của họ tan vỡ như thế nào, Hà Mẫn tìm kiếm câu trả lời từ chồng cũ và bạn thân cũ của cô.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bai Baihe","avatar":""},{"name":"Joseph Chang","avatar":""},{"name":"Christine Fan","avatar":""},{"name":"Ken Lin","avatar":""},{"name":"Amber An","avatar":""},{"name":"Tse Kwan-Ho","avatar":""},{"name":"Queenie Tai","avatar":""},{"name":"Deng Zi-Yi","avatar":""},{"name":"Sky Wu","avatar":""},{"name":"Kuang-Yao Fan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324461);
