INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-secret-scandal', 'The Secret Scandal', 'The Secret Scandal', 'https://phimimg.com/upload/vod/20231211-1/a3ba4540a757d7843fc358644ee8200d.jpg', 'https://phimimg.com/upload/vod/20231211-1/db1387745fd58342167d2b4ee469dd9e.jpg', '<p>Một nữ diễn viên chết. Một phóng viên sau đó điều tra vụ việc và một công tố nữ tìm kiếm công lý. Để tiết lộ sự thật đằng sau cái chết của nữ diễn viên, phóng viên và nữ công tố viên bắt đầu chiến đấu chống lại một nhóm năng lượng.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324461);
