INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-tay-khoi-sung', 'Miền Tây Khói Súng', 'Vengeance Without Mercy', 'https://phimimg.com/upload/vod/20231211-1/487cb094ef3ecf13c8c944202803ce0c.jpg', 'https://phimimg.com/upload/vod/20231211-1/e41d3458549c251b959bba970f583588.jpg', '<p>Charles Holley đã dành mười năm theo dõi Animus Smite, người đã giết chết gia đình ông trong cuộc nội chiến. Cuối cùng anh ta đã tìm thấy kẻ thù. Anh ta sẽ làm gì nếu gặp lại kẻ thù của mình?</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Adams","avatar":""},{"name":"Jezibell Anat","avatar":""},{"name":"Saul Brooks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324461);
