INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-sua-chua', 'Thợ Sửa Chữa', 'The Repairman', 'https://phimimg.com/upload/vod/20231211-1/919803be91ef587f2d59c2fa46609d44.jpg', 'https://phimimg.com/upload/vod/20231211-1/7c93dcee12819a849fbf87ffe062ee0e.jpg', '<p>Scanio Libertetti, là một kỹ sư thất bại nhưng lại là nhà phát minh thiên tài kiếm sống bằng nghề sửa chữa máy pha cà phê. IS yêu cầu giải thích các tình huống dẫn đến việc anh ta bị phạt quá tốc độ, những anh ta lại hồi tưởng quá xa ...thành một câu chuyện dài như một bộ phim về cuộc sống của mình trong suốt những năm qua. Bắt đầu từ những người bạn thời thơ ấu luôn sẵn sàng chỉ trích anh ta, người chú luôn khuyến khích anh ta chấn chỉnh cuộc sống mình và sự hiện diện của Helena, một cô gái trẻ người Anh mới chuyển đến Ý và dường như là người duy nhất hiểu được anh ta. Ít nhất là đã từng...trong một khoảng thời gian.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniele Savoca","avatar":""},{"name":"Hannah Croft","avatar":""},{"name":"Paolo Giangrasso","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324461);
