INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-vang-khuc-ca', 'Hòa Vang Khúc Ca', 'Grace Unplugged', 'https://phimimg.com/upload/vod/20231130-1/5ade7980f44b2c6d5236028dc7d1a856.jpg', 'https://phimimg.com/upload/vod/20231130-1/ccbea07d036d837eb6b50c20558a9aa4.jpg', '<p>Hòa Vang Khúc Ca - Grace Unplugged kề về Grace Trey vừa tròn 18 tuổi và khao khát làm nhiều hơn là hát trong ban nhạc thờ được dẫn dắt bởi cha cô, Johnny Trey, ngôi sao nhạc pop một thời. Grace khao khát thoát khỏi cái bóng của bố và tạo dựng tên tuổi khi hát những bài hát về một điều gì đó không phải Chúa, nhưng Johnny cảnh báo cô rằng danh tiếng không hào nhoáng như vẻ ngoài.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"AJ Michalka","avatar":""},{"name":"James Denton","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Jamie Grace","avatar":""},{"name":"Emma Catherwood","avatar":""},{"name":"Zane Holtz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324461);
