INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pororo-duong-dua-mao-hiem', 'Pororo: Đường Đua Mạo Hiểm', 'Pororo: The Racing Adventure', 'https://phimimg.com/upload/vod/20231130-1/282eebd5becfb837a0665af0fd25546b.jpg', 'https://phimimg.com/upload/vod/20231130-1/1698918ad84aabef065eeb9912b3100f.jpg', '<p>PORORO: ĐƯỜNG ĐUA MẠO HIỂM là câu chuyện về chú chim cánh cụt Pororo mơ ước được vô địch trong cuộc thi lái xe trượt tuyết. Ấp ủ ước mơ này , Pororo cùng các bạn của mình quyết định bay đến Northpia – xứ sở tuyết để tham gia cuộc thi. Cả nhóm đã cùng nhau chinh phục vô số khó khăn, vượt mặt các đối thủ cao to đáng gờm để giành lấy chiến thắng cuối cùng.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sun","avatar":""},{"name":"Ham Su-jung","avatar":""},{"name":"Kim Hwan-jin","avatar":""},{"name":"Lee Mi-ja","avatar":""},{"name":"Hong So-young","avatar":""},{"name":"Cho Hyun-jung","avatar":""},{"name":"Jung Mi-sook","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324461);
