INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thay-thuoc', 'Người Thầy Thuốc', 'The Physician', 'https://phimimg.com/upload/vod/20231129-1/3a490ab203ced9993928b109b24a2ca0.jpg', 'https://phimimg.com/upload/vod/20231129-1/771ba9d12db13024e42d0128eaf2f0c1.jpg', '<p>Nước Anh năm 1021. Rob Cole một chàng trai nghèo khổ, thề sẽ trở thành thầy thuốc và chiến thắng bệnh tật và cái chết. Anh phải trải qua con đường gian khó để tìm kiếm kiến thức bị bao vây bởi vô số thử thách và hy sinh, dẫn anh đến Isfahan xa xôi ở Ba Tư, nơi anh gặp Ibn Sina người chữa bệnh vĩ đại nhất trong thời đại của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Tom Payne","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Emma Catherine Rigby","avatar":""},{"name":"Elyas M''Barek","avatar":""},{"name":"Fahri Yardım","avatar":""},{"name":"Makram J. Khoury","avatar":""},{"name":"Michael Marcus","avatar":""},{"name":"Stanley Townsend","avatar":""},{"name":"Emil Marwa","avatar":""},{"name":"Martin Hancock","avatar":""},{"name":"Adam Thomas Wright","avatar":""},{"name":"Jodie McNee","avatar":""},{"name":"Dominique Moore","avatar":""},{"name":"Aidan K","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324461);
