INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-noi-thanh-loi', 'Không Nói Thành Lời', 'Enough Said', 'https://phimimg.com/upload/vod/20231129-1/a35447e89ef85baaddfe7268408a5b12.jpg', 'https://phimimg.com/upload/vod/20231129-1/632c0a3ba1fd864ea6d7f4e543dfcaf3.jpg', '<p>Đã ly dị từ lâu, Eva sống những ngày êm đềm với công việc mát-xa và cùng cô con gái. Nhưng con của Eva sắp phải xa mẹ để đi học Đại học. Trong lúc ấy, Eva gặp Albert, một anh chàng tuy nặng cân nhưng lại vui tính, ngọt ngào, hoàn toàn vừa ý Eva. Tình cảm cả hai đang mùi mẫn thì Eva làm quen được cô bạn tên Marianne. Cô bạn mới này hầu như hoàn hảo về mọi mặt chỉ có điều: cô ta từng ăn hiếp ông chồng cũ một cách quá đáng. Giật mình, Eva cảm thấy có gì đó không ổn về mối quan hệ giữa cô với Albert và Marianne, cả ông chồng cũ của cô ta.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Julia Louis-Dreyfus","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Tavi Gevinson","avatar":""},{"name":"Ben Falcone","avatar":""},{"name":"Tracey Fairaway","avatar":""},{"name":"Eve Hewson","avatar":""},{"name":"Lennie Loftin","avatar":""},{"name":"Jessica St. Clair","avatar":""},{"name":"Christopher Nicholas Smith","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Phillip Brock","avatar":""},{"name":"Nick Williams","avatar":""},{"name":"Ivy Strohmaier","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324461);
