INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-phep-thuat', 'Ngôi Nhà Phép Thuật', 'The House of Magic', 'https://phimimg.com/upload/vod/20231129-1/f51302d339c503e678936664bc16ecb3.jpg', 'https://phimimg.com/upload/vod/20231129-1/98f17ae5903a28e944d8f10cf32fa681.jpg', '<p>&quot;Ngôi Nhà Phép Thuật - The House of Magic&quot; là một bộ phim hoạt hình 2013 của 2 đạo diễn Jeremy Degruson và Ben Stassen. Thunder, một con mèo bị bỏ rơi tìm kiếm nơi trú ẩn trong một cơn bão, tình cờ vào một ngôi nhà lạ lùng không thể tưởng tượng được, thuộc sở hữu của một nhà ảo thuật già. Không ai cũng hoan nghênh việc có mặt của chú mèo, đặc biệt là Jack Rabbit và Maggie Mouse luôn âm mưu đuổi Thunder đi. Tình hình trở nên tồi tệ khi ngôi nhà sắp bị quy hoạch...</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2013, 'Thuyết Minh', 'HD', 'Bỉ', 0, '[{"name":"Brianne Siddall","avatar":""},{"name":"Shanelle Gray","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Doug Stone","avatar":""},{"name":"Grant George","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Elisa Gabrielli","avatar":""},{"name":"Cinda Adams","avatar":""},{"name":"Sage Sommer","avatar":""},{"name":"Kyle Hebert","avatar":""},{"name":"Bill Parks","avatar":""},{"name":"Ella Rouhier","avatar":""},{"name":"Noah Ray Strauss","avatar":""},{"name":"Isabella Tatone","avatar":""},{"name":"Keegan Thomas","avatar":""},{"name":"Jim Ward","avatar":""},{"name":"Susanne Blakeslee","avatar":""},{"name":"Roxa","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":