INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-batman-the-movie-dc-super-heroes-unite', 'Lego Batman: The Movie - DC Super Heroes Unite', 'Lego Batman: The Movie - DC Super Heroes Unite', 'https://phimimg.com/upload/vod/20231129-1/4ab404af98a3bc999b57db2f6d876032.jpg', 'https://phimimg.com/upload/vod/20231129-1/7d08317292e3081b0dfe5ed15b8300f6.jpg', '<p>Joker hợp tác với Lex Luthor để phá hủy thế giới từng viên gạch một. Tùy thuộc vào Batman, Superman và phần còn lại của Justice League để ngăn chặn chúng.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Troy Baker","avatar":""},{"name":"Charlie Schlatter","avatar":""},{"name":"Travis Willingham","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Christopher Corey Smith","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Townsend Coleman","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Laura Bailey","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Katherine Von Till","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Cam Clarke","avatar":""},{"name":"Erin Shanagher","avatar":""},{"name":"Sandra Bullock","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324461);
