INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lego-batman-the-movie-dc-super-heroes-unite', 'Lego Batman: The Movie - DC Super Heroes Unite', 'Lego Batman: The Movie - DC Super Heroes Unite', 'lego batman: the movie - dc super heroes unite lego batman: the movie - dc super heroes unite troy baker charlie schlatter travis willingham clancy brown christopher corey smith rob paulsen townsend coleman brian bloom laura bailey kari wahlgren katherine von till steve blum cam clarke erin shanagher sandra bullock ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-duong-cung-2013', 'Bước Đường Cùng', 'Homefront', 'https://phimimg.com/upload/vod/20231129-1/5da4460924afe0cb856457aaefe77f22.jpg', 'https://phimimg.com/upload/vod/20231129-1/9aa846e3c35c05b4bf9aae5c1c1f59ea.jpg', '<p>Homefront được xây dựng trên hình mẫu những bộ phim về miền viễn tây kinh điển, với cốt truyện xoay quanh một cựu sĩ quan cảnh sát sống cuộc sống bình lặng tại một thị trấn nhỏ, trước khi nhận ra mình không thể chạy trốn khỏi quá khứ. Phil Broker, nhân vật của Jason Statham, đã quyết định chuyển về vùng nông thôn Louisiana sau một chiến dịch thất bại. Tất cả những gì anh còn là cô con gái… sau khi người vợ qua đời. Đau đớn, cô độc, anh chọn sống tách biệt cho tới khi con gái anh vô tình gây mâu thuẫn với một gia đình địa phương cùng sống trong thị trấn nhỏ ở nhánh sông phía nam này. Mâu thuẫn nhỏ đó cứ leo thang, leo thang và ngày càng trầm trọng hơn, cho tới khi vỏ bọc của anh đột ngột bị lật tẩy.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"James Franco","avatar":""},{"name":"Izabela Vidovic","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Rachelle Lefevre","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Christa Campbell","avatar":""},{"name":"Omar Benson Miller","avatar":""},{"name":"Nicole Andrews","avatar":""},{"name":"Joshua Brady","avatar":""},{"name":"Marcus Hester","avatar":""},{"name":"Chuck Zito","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Linds Edwards","avatar":""},{"name":"Aus","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
