INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cang-tot-dep-hon', 'Ngày Càng Tốt Đẹp Hơn', 'Better And Better', 'https://phimimg.com/upload/vod/20231209-1/2e3c8640e62f8d80909eb70007ea9c32.jpg', 'https://phimimg.com/upload/vod/20231209-1/7dc84b104c1b0f0b050e6f3fe3f79b93.jpg', '<p>Sun Xiangcheng, một người tổ chức người hâm mộ chuyên nghiệp tự phong, được mẹ Yuanfang gọi đến từ quê hương của anh ấy ở Thung lũng West Well. Nghĩ rằng anh ấy có mối quan hệ thân thiết với những người nổi tiếng, cô ấy nhờ anh ấy giúp tổ chức lễ đón năm mới của làng</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Jue","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Xu Jinglei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
