INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-tro-ve-2013', 'Đường Trở Về', 'The Way Way Back', 'https://phimimg.com/upload/vod/20231120-1/5ba0906b2cd4de6e7f858d6f6acdbb7d.jpg', 'https://phimimg.com/upload/vod/20231120-1/5593bdff167943c0b99315108ddc4825.jpg', '<p>Phim kể về kì nghỉ hè của cậu bé 14 tuổi Duncan, trong suốt kì nghỉ hè của mình cậu phải đến sống và làm việc ở một công viên nước. Cuộc sống của Duncan ở đây không hề dễ dàng khi cậu bé phải đối mặt với muôn vàn khó khăn, rắc rối và cậu phải tự tìm cách giải quyết chúng, nhất là với người quản lí công viên đáng ghét luôn tìm cách gây khó dễ cho Duncan.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam James","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Nat Faxon","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Zoe Levin","avatar":""},{"name":"River Alexander","avatar":""},{"name":"Adam Riegler","avatar":""},{"name":"Jeremy Weaver","avatar":""},{"name":"Robert Capron","avatar":""},{"name":"Rodney Lodge","avatar":""},{"name":"Devon Werden","avatar":""},{"name":"Ava De","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
