INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ma-am-2013', 'Ngôi Nhà Ma Ám', 'A Haunted House', 'https://phimimg.com/upload/vod/20231023-1/c65cd82b5dc64f51eed09da228b01f2b.jpg', 'https://phimimg.com/upload/vod/20231023-1/e2caeb2423b5ea7c2cf2a69a2da550c6.jpg', '<p>Malcolm và Kisha chuyển đến ngôi nhà mơ ước của họ nhưng sớm biết được có một con quỷ cũng cư trú ở đó. Khi Kisha bị chiếm hữu, Malcolm - quyết tâm giữ cho đời sống tình dục của mình đi đúng hướng - tìm đến một linh mục, một nhà ngoại cảm và một nhóm chuyên săn ma để được giúp đỡ trong việc giả mạo tất cả &quot;cảnh quay được tìm thấy&quot; này.</p>', 'Full', 1, 'single', 'completed', 7, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marlon Wayans","avatar":""},{"name":"Essence Atkins","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Liana Mendoza","avatar":""},{"name":"Jamie Noel","avatar":""},{"name":"Marlene Forte","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Robin Thede","avatar":""},{"name":"Bobbie Lee","avatar":""},{"name":"Damien Bray","avatar":""},{"name":"Joel Kelley Dauten","avatar":""},{"name":"Jordenn Thompson","avatar":""},{"name":"Andrew Daly","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
