INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-nguy-hiem-2013', 'Mối Quan Hệ Nguy Hiểm', 'A Dark Matter', 'null', 'https://phimimg.com/upload/vod/20231101-1/c42bb7cae5ef005c9c001ff81e4d826b.jpg', '<p>Bất ngờ trước sự ra đi đột ngột của bạn gái, nghệ sĩ Angus bắt đầu lạc vào một lớp thực tế đen tối được cai trị bởi một con quỷ quyền năng. Tin rằng chìa khóa để tìm thấy cô ấy nằm bên trong, Angus lao sâu hơn vào thế giới địa ngục netherworld.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Daniel Briere","avatar":""},{"name":"Shauna Bradley","avatar":""},{"name":"Ashiko Westguard","avatar":""},{"name":"Troy Blundell","avatar":""},{"name":"Marty Moreau","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
