INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-ngon-tay-2013', 'Chủ Ngón Tay', 'A Wedding Invitation', 'https://phimimg.com/upload/vod/20231012-1/c1931fe7bd7969b514706ba7c1c9d86a.jpg', 'https://phimimg.com/upload/vod/20231012-1/563e504901d34a533572d0a18afda526.jpg', '<p>Đôi tình nhân thời trung học QiaoQiao và Li Xing sắp tốt nghiệp đại học và Li Xing khiến QiaoQiao bất ngờ cầu hôn. Tuy nhiên, QiaoQiao từ chối lời đề nghị, đưa ra những lý lẽ hấp tấp về lý do tại sao anh ấy chưa sẵn sàng. Anh ta không hề biết rằng QiaoQiao có một bí mật kinh hoàng. Tuy nhiên, họ viết một hợp đồng chia tay; nếu cả hai đều độc thân trong 5 năm nữa thì họ sẽ kết hôn. Hai người chia tay và năm năm trôi qua. Tin rằng Li Xing vẫn đang đợi cô, QiaoQiao kiên nhẫn chờ cuộc gọi của anh. Nhưng cuối cùng khi Li Xing liên lạc với cô thì đó là để mời cô đến dự đám cưới của anh. QiaoQiao vô cùng sửng sốt và quyết tâm giành lại ngọn lửa trước đây của mình bằng bất cứ giá nào - mặc dù bí mật khiến họ phải xa nhau vẫn còn đọng lại. Liệu tình yêu của họ có thực sự được nối lại?</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Bai Baihe","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Pace Wu","avatar":""},{"name":"Jiang Jinfu","avatar":""},{"name":"Lin Mei-shiu","avatar":""},{"name":"Li Hongtao","avatar":""},{"name":"Chen Mengqi","avatar":""},{"name":"Yu Yankai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
