INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-nhu-2013', 'Nếu Như', 'What If', 'https://phimimg.com/upload/vod/20231109-1/ad69a60e48a52adff1d1cf9198e89b3c.jpg', 'https://phimimg.com/upload/vod/20231109-1/e31ecaf7cb07132b9bd04f40f3280125.jpg', '<p>Wallace bỏ học trường y đã nhiều lần bị đốt cháy bởi những mối quan hệ tồi tệ. Vì vậy, trong khi mọi người xung quanh, bao gồm cả người bạn cùng phòng Allan, dường như đang tìm được đối tác hoàn hảo, thì Wallace quyết định tạm dừng cuộc sống tình cảm của mình. Sau đó, anh gặp Chantry, một họa sĩ hoạt hình sống với bạn trai lâu năm của cô là Ben. Wallace và Chantry hình thành một kết nối ngay lập tức, tạo nên một tình bạn thân thiết. Tuy nhiên, không thể phủ nhận phản ứng hóa học giữa họ, khiến cặp đôi tự hỏi, điều gì sẽ xảy ra nếu tình yêu của đời bạn thực sự là bạn thân của bạn?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Megan Park","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Lucius Hoyos","avatar":""},{"name":"Jemima Rooper","avatar":""},{"name":"Tommie-Amber Pirie","avatar":""},{"name":"Meghan Heffern","avatar":""},{"name":"Jonathan Cherry","avatar":""},{"name":"Rebecca Northan","avatar":""},{"name":"Jordan Hayes","avatar":""},{"name":"Oona Chaplin","avatar":""},{"name":"Adam Fergus","avatar":""},{"name":"Sam Moses","avatar":""},{"name":"Ennis Esmer","avatar":""},{"name":"Mike Wil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2