INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-o-thai-lan', 'Mất Tích ở Thái Lan', 'Lost In Thailand', 'https://phimimg.com/upload/vod/20231209-1/702873b8df7b466fdd1024d19934bbf6.jpg', 'https://phimimg.com/upload/vod/20231209-1/7ea1cc9db234fb42f2ed406da11cedb6.jpg', '<p>Nhà doanh nghiệp thành công Từ Lãng đã mất 4 năm để phát minh ra sản phẩm truyền kỳ Supergas. Mỗi lần bơm xăng chỉ cần bơm đầy 2/3 bình, sau đó thêm vào hai giọt Supergas, xăng trong bình sẽ tự khắc đầy. Bạn học của Từ Lãng, đồng thời cũng là đối thủ cạnh tranh hạng mục này với anh, Cao Bác muốn bán phát minh này lại cho người Pháp. Tuy nhiên, Từ Lãng kiên quyết phản đối, với hy vọng bán lại cho các công ty đầu tư để họ tiếp tục phát triển và nghiên cứu chuyên sâu hơn, giúp phát minh này mang tính đột phá, thu về nhiều lợi nhuận hơn. Mỗi người một ý kiến, không ai nhường ai, và do giữ số cổ phần bằng nhau, Từ Lãng và Cao Bác đành nhờ cậy tới cổ đông lớn nhất, Châu Dương. Vừa biết tin Châu Dương hiện đang ở Thái Lan, Từ Lãng lập tức lên đường tìm kiếm, Cao Bác bám sát gót. Trên máy bay, Từ Lãng gặp Vương Bảo, định lợi dụng Vương Bảo để cắt đuôi Cao Bác, nhưng cuối cùng lại trở thành “vú em” bên cạnh Vương Bảo. Cuối cùng ai trong Từ Lãng và Cao Bác sẽ nhận được sự ủng hộ của Châu Dương? Với mục đích hoàn toàn khác biệt, liệu 3 người đàn ông này sẽ đem đến cho chúng ta cuộc hành trình thần kỳ ở Thái Lan như thế nào?</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zheng Xu","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Bo Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324462);
