INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-vong-sinh-tu-2-tai-chien', '12 Vòng Sinh Tử 2: Tái Chiến', '12 Rounds 2: Reloaded', 'https://phimimg.com/upload/vod/20231129-1/7be2e7f14426ce1491bbe2f8135bf1bb.jpg', 'https://phimimg.com/upload/vod/20231129-1/05416288968ef4668c307314c6af480d.jpg', '<p>12 Rounds: Reloaded là phần thứ hai của bộ phim 12 Rounds đã rất thành công năm 2009. Trong phần này, Nick Malloy, một kỹ thuật viên y tế khẩn cấp chứng kiến một vụ tai nạn giao thông khủng khiếp. Chiếc xe nổ tung và anh đã lao đến cứu giúp các nạn nhân đang còn kẹt trong xe đang gào thét trong biển lửa. Điều oái ăm thay mà Nick không thể ngờ tới: chính anh là nhân vật mà bọn găng tơ nhắm đến trong tai nạn xe đó. Nick bị cuốn vào trò mèo vờn chuột với những tay xã hội đen đó. Chúng bắt cóc vợ anh. Tại sao Nick lại được chọn trong trò chơi của bọn chúng khủng bố xã hội đen đó? Nick có giải cứu được vợ anh hat không?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Randy Orton","avatar":""},{"name":"Brian Markinson","avatar":""},{"name":"Cindy Busby","avatar":""},{"name":"Sean Rogerson","avatar":""},{"name":"Tom Stevens","avatar":""},{"name":"Colin Lawrence","avatar":""},{"name":"Chelsey Reist","avatar":""},{"name":"Sebastian Spence","avatar":""},{"name":"Janene Carleton","avatar":""},{"name":"Rachel Hayward","avatar":""},{"name":"John Wardlow","avatar":""},{"name":"Venus Terzo","avatar":""},{"name":"Sean Owen Roberts","avatar":""},{"name":"Charlie Kerr","avatar":""},{"name":"Jason Diablo","avatar":""},{"name":"Jesse Hutch","avatar":""},{"name":"Kyle Cassie","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324462);
