INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-den', 'Bầu Trời Đen', 'Dark Skies', 'https://phimimg.com/upload/vod/20231129-1/2d1d27c2f9449256820248292342d9e7.jpg', 'https://phimimg.com/upload/vod/20231129-1/b1abf72457ed2688b72b7ff8d593f952.jpg', '<p>Bầu Trời Đen - Dark Skies là bộ phim tâm lý, kinh dị kể về một gia đình trẻ sống ở vùng ngoại ô. Cặp vợ chồng Daniel và Lacy Barrett vô cùng lo lắng khi chứng kiến hàng loạt sự kiện đáng sợ xảy ra, ảnh hưởng tới sự an toàn và bình yên của gia đình mình. Khi mọi chuyện dần sáng tỏ rằng họ đang bị những thế lực chết chóc và đáng sợ khủng khiếp theo đuổi, Daniel và Lacy quyết định phải tự mình bảo vệ gia đình và tìm lời giải cho những bí ẩn đang theo sau họ.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Keri Russell","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Dakota Goyo","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Trevor St. John","avatar":""},{"name":"Annie Thurman","avatar":""},{"name":"Myndy Crist","avatar":""},{"name":"Josh Wingate","avatar":""},{"name":"Ron Ostrow","avatar":""},{"name":"Alyvia Alyn Lind","avatar":""},{"name":"Kadan Rockett","avatar":""},{"name":"L.J. Benet","avatar":""},{"name":"Rich Hutchman","avatar":""},{"name":"Jake Brennan","avatar":""},{"name":"Marion Kerr","avatar":""},{"name":"Josh Stamberg","avatar":""},{"name":"Tiffany Jeneen","avatar":""},{"name":"Brian Step","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 17