INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-dao-chich', 'Nghệ Thuật Đạo Chích', 'The Art of the Steal', 'https://phimimg.com/upload/vod/20231129-1/7e1662cace6c5c703e82f6692aa1565a.jpg', 'https://phimimg.com/upload/vod/20231129-1/92ff59d33a6566b32620d52a2d8509a2.jpg', '<p>Nghệ Thuật Đạo Chích là câu chuyện kể về một nhóm người sở hữu nhiều kĩ năng nổi bật về thông tin và máy móc do WheelMan đứng đầu, ông từng là một tay đua biểu diễn xe đua nghệ thuật nhưng đã hết thời sau vụ tai nạn. Tất cả thành viên trong nhóm đều muốn thay đổi cách sống và công việc hiện tại của mình nhằm hướng đến tương lai sáng hơn bằng cách đánh cắp cuốn sách cổ chứa đựng bí mật về những sự việc trên toàn thế giới, giá trị của nó có thể lên đến hàng chục triệu Dolas. Kế hoạch đánh cắp cuốn sách quý bắt đầu, dưới sự giám sát của cảnh sát phòng chống tội phạm quốc gia, liệu nhóm của WheelMan có thực hiện được phi vụ lớn nhất từ trước đến nay?</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Kenneth Welsh","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Katheryn Winnick","avatar":""},{"name":"Jason Jones","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Karyn Dwyer","avatar":""},{"name":"Joe Pingue","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Eugene Lipinski","avatar":""},{"name":"Elle Downs","avatar":""},{"name":"Dax Ravina","avatar":""},{"name":"Rob deLeeuw","avatar":""},{"name":"Christopher Dyson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b