INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hot-girl-sieu-quay', 'Hot Girl Siêu Quậy', 'Miss Change', 'https://phimimg.com/upload/vod/20231129-1/30a7d4790284204f0fb6d73f239305ee.jpg', 'https://phimimg.com/upload/vod/20231129-1/c4c6b8c28a1b1817f462db7dea95812b.jpg', '<p>Je-Chil (Song Sam-Đồng) là một luật sư rất thành công trong thị trường chứng khoán, nhưng anh chưa bao giờ hẹn hò với một người phụ nữ nào trong cuộc sống của mình. Rồi Soo Hyun (Shin Yoo Joo) cô gái yêu kiều, nóng bỏng xuất hiện hớp hồn anh ta. Ngất ngay trước sự quyến rũ của cô nàng, Je-Chil bắt đầu tán tỉnh chinh phục người đẹp.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Sam-dong","avatar":""},{"name":"Lee Su-jung","avatar":""},{"name":"Jeong Eun-woo","avatar":""},{"name":"Shin Yu-ju","avatar":""},{"name":"You Il-han","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Jin Yong-uk","avatar":""},{"name":"Seo Ha-yoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
