INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-that-quai', 'Giang Hồ Thất Quái', 'Princess and Seven Kung Fu Masters', 'null', 'https://phimimg.com/upload/vod/20231128-1/d9728f3e36eed130a92c41046f18a220.jpg', '<p>Phim lấy bối cảnh ở trấn Phúc Tinh yên bình, nơi 7 vị cao thủ võ lâm ở ẩn và làm những công việc bình thường như hai chi em quán tính tình có chút khùng khùng, bà chủ lầu xanh, anh thợ may, pháp sư, người trông giữ trẻ, người bán son phấn... nhưng cuộc sống của họ lại nổi sóng gió khi xuất hiện một nhóm người lạ vào thôn.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Xie Na","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Natalie Meng Yao","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Jiang Luxia","avatar":""},{"name":"Meilin Mo","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Rose Chan Ka-Wun","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Tiger Xu","avatar":""},{"name":"Wan Chiu","avatar":""},{"name":"Wong Cho-lam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
