INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tuyen-dung', 'Người Tuyển Dụng', 'The Employer', 'https://phimimg.com/upload/vod/20231127-1/8817470e7c00a4fc267de88bd8e72c5a.jpg', 'https://phimimg.com/upload/vod/20231127-1/30aeff681ecb790cf9ba326fea2173df.jpg', '<p>Năm ứng cử viên đang cạnh tranh quyết liệt cho một công việc tại một tập đoàn quyền lực nhưng rất bí ẩn. Vào đêm trước ngày diễn ra vòng phỏng vấn cuối, cả năm người đều nhận được cuộc gọi từ người tuyển dụng thông báo rằng họ sẽ được kiểm tra một lần nữa. Cả năm người bị đánh thuốc mê, nhốt vào phòng kín và buộc phải chiến đấu với nhau để sống sót, chỉ có một người có thể nhận được công việc này.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Malcolm McDowell","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Paige Howard","avatar":""},{"name":"Michael DeLorenzo","avatar":""},{"name":"Matthew Willig","avatar":""},{"name":"Katerina Mikailenko","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Nicki Aycox","avatar":""},{"name":"Daniel Aldema","avatar":""},{"name":"Erin Soto","avatar":""},{"name":"Tony Casale","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
