INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bep-dien-vien-va-ten-vo-lai', 'Đầu Bếp, Diễn Viên, Và Tên Vô Lại', 'The Chef, The Actor, The Scoundrel', 'https://phimimg.com/upload/vod/20231129-1/9a28523428f65cda7ea11d5b5c18c9d0.jpg', 'https://phimimg.com/upload/vod/20231129-1/64461d76628f95ee9bf022f0d9474598.jpg', '<p>Chiến tranh thế giới thứ hai: một trận dịch tả tàn phá đường phố Bắc Kinh. Một nhóm đặc vụ tình báo Trung Quốc xuất sắc bắt cóc một tướng quân và nhà hóa sinh người Nhật, người có thể nắm giữ thuốc giải độc.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Ye","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Huang Bo","avatar":""},{"name":"Liang Jing","avatar":""},{"name":"Wang Xun","avatar":""},{"name":"Chie Tanaka","avatar":""},{"name":"Ryu Kohata","avatar":""},{"name":"Minowa Yasufumi","avatar":""},{"name":"Shinichi Takashima","avatar":""},{"name":"Masanobu Otsuka","avatar":""},{"name":"Fei Zhenxiang","avatar":""},{"name":"Zhao Su-Chen","avatar":""},{"name":"Akira Hibino","avatar":""},{"name":"Zhang Luyi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
