INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ho', 'Tình Hờ', 'Third Person', 'https://phimimg.com/upload/vod/20231125-1/07f9a7cc803250356e024902133bc5be.jpg', 'https://phimimg.com/upload/vod/20231125-1/6cf58ed87f65350a7e7a92e438060250.jpg', '<p>Một tiểu thuyết gia nổi tiếng nỗ lực viết một bài phân tích về tình yêu ở một trong ba câu chuyện, mỗi câu chuyện lấy bối cảnh ở một thành phố khác nhau, trình bày chi tiết về sự bắt đầu, diễn biến và kết thúc của một mối quan hệ.</p>', 'Full', 1, 'single', 'completed', 8, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"James Franco","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Kim Basinger","avatar":""},{"name":"Moran Atias","avatar":""},{"name":"Michele Melega","avatar":""},{"name":"Katy Louise Saunders","avatar":""},{"name":"Loan Chabanol","avatar":""},{"name":"Riccardo Scamarcio","avatar":""},{"name":"Daniela Virgilio","avatar":""},{"name":"Vinicio Marchioni","avatar":""},{"name":"Vincent Riotta","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Bob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
