INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zone-pro-site-the-moveable-feast', 'Zone Pro Site: The Moveable Feast', 'Zone Pro Site: The Moveable Feast', 'https://phimimg.com/upload/vod/20231125-1/5a14733f46ea9b3da034bf2bd2fa0f9d.jpg', 'https://phimimg.com/upload/vod/20231125-1/6d6924f3a10eb1ea0a5f6f9a703b11cd.jpg', '<p>Hơn 20 năm trước, có ba đầu bếp bậc thầy &quot;Ban Dou&quot; thống trị ngành kinh doanh ăn uống ở Đài Loan. Tuy nhiên, hoạt động kinh doanh tiệc đường phố đã sa sút kể từ khi nền kinh tế Đài Loan bùng nổ. Master Fly Spirit muốn truyền lại công thức nấu ăn và kỹ năng nấu nướng của gia đình cho đứa con duy nhất của mình, Wan, nhưng cô lại muốn chạy trốn khỏi công việc kinh doanh của gia đình và trở thành một ngôi sao điện ảnh.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Tony Yang","avatar":""},{"name":"Lin Mei-shiu","avatar":""},{"name":"Hsia Yu-chiao","avatar":""},{"name":"Bamboo Chen","avatar":""},{"name":"Wu Nien-Jen","avatar":""},{"name":"Ko I-Chen","avatar":""},{"name":"Jieh-Wen King","avatar":""},{"name":"Tuo Hsien","avatar":""},{"name":"Wu Pong-Fong","avatar":""},{"name":"Hsi-Sheng Chen","avatar":""},{"name":"Chen Yen-Tso","avatar":""},{"name":"Love Fang","avatar":""},{"name":"Lee Lieh","avatar":""},{"name":"Ma Nien-Hsien","avatar":""},{"name":"Yang Li-Yin","avatar":""},{"name":"Tzu-Chiang Wang","avatar":""},{"name":"Ren-Chien Ko","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
