INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lupin-de-tam-va-tham-tu-lung-danh-conan', 'Lupin Đệ Tam và Thám Tử Lừng Danh Conan', 'Lupin III vs. Detective Conan: The Movie', 'https://phimimg.com/upload/vod/20231124-1/3909b8ee6553ca44e1c8509f01f52983.jpg', 'https://phimimg.com/upload/vod/20231124-1/47e86eb54a4bef826a68e71d699940ed.jpg', '<p>Đó là một chéo giữa loạt Lupin III và trường hợp đóng cửa và diễn ra sau khi truyền hình Lupin đặc biệt thứ 3 so với thám tử VS Conan, cũng kết hợp các yếu tố khác nhau từ người tiền nhiệm trong cốt truyện của nó. Cốt truyện theo Conan Edogawa, người bắt đầu bắt giữ Arsene Lupine III, nghi phạm ăn cắp một viên ngọc gọi là Cherry Sapphire.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kanichi Kurita","avatar":""},{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Kiyoshi Kobayashi","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Iemasa Kayumi","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
