INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-dan-vao-dau', 'Viên Đạn Vào Đầu', 'Bullet to the Head', 'https://phimimg.com/upload/vod/20231124-1/4e5d4c89f9459d5bd7e6bcef3bf0fb9b.jpg', 'https://phimimg.com/upload/vod/20231124-1/4d8655855b9337708cde81aeae025fe8.jpg', '<p>Với nội dung kể về Jimmy Bobo - người được mệnh danh là Hit Man của New Orleans cùng bắt tay hợp tác với &quot;siêu cớm&quot; Taylor Kwon trong nhiệm vụ truy sát những kẻ giết người trong khắp tiểu bang. Với dàn diễn viên được mệnh danh là &quot;nghe đã muốn coi&quot; (Lão làng Sylvester Stallone, tay lái lụa Sung Kang, Jason Momoa, Christian Slater, Sarah Shahi, Adewale Akinnuoye-Agbaje, và Jon Seda)</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Sarah Shahi","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Jason Momoa","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Jon Seda","avatar":""},{"name":"Weronika Rosati","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Brian Van Holt","avatar":""},{"name":"Dane Rhodes","avatar":""},{"name":"Marcus Lyle Brown","avatar":""},{"name":"Andrew Austin-Peterson","avatar":""},{"name":"Robert Cavan Carruth","avatar":""},{"name":"Paul Etheredge","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
