INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-bi-am-2-bi-an-o-georgia', 'Ngôi Nhà Bị Ám 2: Bí Ẩn Ở Georgia', 'The Haunting in Connecticut 2: Ghosts of Georgia', 'https://phimimg.com/upload/vod/20231124-1/015dd26d7925813fba39ea353d8c5d5e.jpg', 'https://phimimg.com/upload/vod/20231124-1/de457a9f7461bd9b61a8701fead077ea.jpg', '<p>Dựa trên sườn cốt truyện giống na ná với phần đầu The Haunting in Connecticut (2009). Sau khi người chồng Andy Wyrick cùng người vợ trẻ Lisa và đứa con gái Heidi của mình chuyển đến sinh sống tại một căn nhà cũ kĩ ở một nơi hoang vắng tại Georgia, gia đình bé nhỏ này đã nhanh chóng khám phá ra họ không phải là ba thanh viên duy nhất trong nhà. Gia đình ba thành viên này đã phải mặt đối mặt với những bí ẩn &quot;ớn lạnh đến thấu xương&quot; ... một bí mật ám ảnh từ bên dưới căn nhà mà họ đang sinh sống và sẽ đe dọa bất cứ thành viên nào nếu họ gặp phải.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Murray","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Cicely Tyson","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"Andrea Frankle","avatar":""},{"name":"Lauren Pennington","avatar":""},{"name":"Morgana Shaw","avatar":""},{"name":"Grant James","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Jaren Mitchell","avatar":""},{"name":"Brad James","avatar":""},{"name":"Hunter Burke","avatar":""},{"name":"Wayne Pére","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
