INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-bi-am-2-bi-an-o-georgia', 'Ngôi Nhà Bị Ám 2: Bí Ẩn Ở Georgia', 'The Haunting in Connecticut 2: Ghosts of Georgia', 'ngôi nhà bị ám 2: bí ẩn ở georgia the haunting in connecticut 2: ghosts of georgia chad michael murray katee sackhoff abigail spencer cicely tyson emily alyn lind andrea frankle lauren pennington morgana shaw grant james lance e. nichols jaren mitchell brad james hunter burke wayne pére ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-lon-nguoc', 'Cô Gái Lộn Ngược', 'Patema Inverted', 'https://phimimg.com/upload/vod/20231124-1/4a2bd9ee23ddd7b639c42f7d0d574d58.jpg', 'https://phimimg.com/upload/vod/20231124-1/46e80def9f320ec05765040dcc61eccf.jpg', '<p>Trong một ngôi làng nhỏ dưới lòng đất, nơi mà các thông đạo và đường hầm ở khắp mọi nơi. Ngay cả với không gian sống chật hẹp và tối tăm như vậy, người dân ở đây vẫn sống rất vui vẻ. Patema, cô công chúa nhỏ của ngôi làng dưới lòng đất có sở thích khám phá các đường hầm. Nơi ưa thích của cô là &quot;vùng nguy hiểm&quot; nơi đã có lệnh cấm vào (dù chẳng ai biết tại sao). Dù đã bị mắng nhiều lần nhưng tính hiếu kì của Patema vẫn không thay đổi và trong một lần tới đó như thường lệ, một biến cố bất ngờ đã xảy ra...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yukiyo Fujii","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Shintarou Oohata","avatar":""},{"name":"Shinya Fukumatsu","avatar":""},{"name":"Masayuki Katou","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Hideyuki Umezu","avatar":""},{"name":"Gou Shinomiya","avatar":""},{"name":"Yu Shimamura","avatar":""},{"name":"Tomoyuki Shimura","avatar":""},{"name":"Shunsuke Itou","avatar":""},{"name":"Yuka Keicho","avatar":""},{"name":"Genki Muro","avatar":""},{"name":"Toru Sakurai","avatar":""},{"name":"Kiyohito","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gi