INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-26', 'Phi Vụ 26', 'Special 26', 'https://phimimg.com/upload/vod/20231121-1/cd65f009b02538dbc050dbd5e1e32b2b.jpg', 'https://phimimg.com/upload/vod/20231121-1/638da1c1c8123e348f30e59671595522.jpg', '<p>Vào đầu những năm 1980 ở Ấn Độ, một nhóm chuyên gia lừa đảo đã cướp tiền của các doanh nhân và chính trị gia nổi tiếng bằng cách giả làm nhân viên của Cục Tình báo Trung ương hoặc quan chức thuế thu nhập. Băng nhóm thực hiện các cuộc đột kích giả, trong đó chúng đánh cắp số tiền lớn từ các mục tiêu của chúng.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Manoj Bajpayee","avatar":""},{"name":"Jimmy Shergill","avatar":""},{"name":"Rajesh Sharma","avatar":""},{"name":"Kishore Kadam","avatar":""},{"name":"Kajal Agarwal","avatar":""},{"name":"Divya Dutta","avatar":""},{"name":"Ujjwal Chopra","avatar":""},{"name":"Mukesh Bhhatt","avatar":""},{"name":"Tiku Talsania","avatar":""},{"name":"Neeru Bajwa","avatar":""},{"name":"Bhagwan Tiwari","avatar":""},{"name":"Gurpal Singh","avatar":""},{"name":"Vikas Shrivastav","avatar":""},{"name":"Deepraj Rana","avatar":""},{"name":"Vipin Sharma","avatar":""},{"name":"Sukh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
