INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-quan-ma', 'Đội Quân Ma', 'Frankenstein''s Army', 'https://phimimg.com/upload/vod/20231120-1/6a086773764c504d3cf640cbcbd1ec2c.jpg', 'https://phimimg.com/upload/vod/20231120-1/f3bd7098cafafcf3c1537da78af55a4a.jpg', '<p>Vào cuối Thế chiến II, những người lính Nga tiến vào miền đông nước Đức tình cờ gặp một phòng thí nghiệm bí mật của Đức Quốc xã, một phòng thí nghiệm đã khai quật và bắt đầu thử nghiệm nhật ký của Tiến sĩ Victor Frankenstein. Các nhà khoa học đã sử dụng công trình huyền thoại của Frankenstein để tập hợp một đội quân siêu chiến binh được ghép lại với nhau từ các bộ phận cơ thể của những người đồng đội đã ngã xuống của họ - một âm mưu khủng khiếp cuối cùng của Hitler để thoát khỏi thất bại</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Karel Roden","avatar":""},{"name":"Joshua Sasse","avatar":""},{"name":"Robert Gwilym","avatar":""},{"name":"Alexander Mercury","avatar":""},{"name":"Luke Newberry","avatar":""},{"name":"Hon Ping Tang","avatar":""},{"name":"Andrei Zayats","avatar":""},{"name":"Mark Stevenson","avatar":""},{"name":"Cristina Catalina","avatar":""},{"name":"Jan de Lukowicz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
