INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tham-tu', 'Đội Thám Tử', 'Vishwaroopam', 'https://phimimg.com/upload/vod/20231203-1/dbaa9d9cb0b743a2e13d5f3d92b76246.jpg', 'https://phimimg.com/upload/vod/20231203-1/cd5deae170cff0d06b8b175e8d5f6120.jpg', '<p>Vishwanathan là một giáo viên dạy nhảy Kathak ở New York, trong một cuộc hôn nhân khá hài lòng với Nirupama một bác sĩ chuyên khoa hạt nhân. Mâu thuẫn nảy sinh, cô thuê một thám tử để theo dõi chồng mình, và rồi mọi chuyện xảy ra….</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Kamal Haasan","avatar":""},{"name":"Rahul Bose","avatar":""},{"name":"Andrea Jeremiah","avatar":""},{"name":"Pooja Kumar","avatar":""},{"name":"Shekhar Kapur","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324462);
