INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-trieu-phu', 'Giấc Mơ Triệu Phú', 'Nebraska', 'https://phimimg.com/upload/vod/20231121-1/e14b302c73db3188a6c8db0fc980e915.jpg', 'https://phimimg.com/upload/vod/20231121-1/feb3b00dfed32f5170d8ff9ce15ddc5d.jpg', '<p>Nebraska là một bộ phim hài hước đen trắng, kể về một ông già tên là Woody Grant cương quyết bằng mọi cách đến được bang Nebbraska để nhận 1 triệu đô la ông vừa thắng. Dù bị bệnh và không lái được xe nhưng ông già Wooddy Grant vẫn sẵn sàng vượt quãng đường xa từ bang Montana để đến tận Nebraska. Vợ con ông cố gắng giải thích rằng lá thư thông báo ông trúng số độc đắc chỉ là một trò lừa bịp để quảng cáo. Nhưng nỗ lực của họ cũng bằng thừa, đi nhận 1 triệu đô la đã trở thành nỗi ám ảnh cho đến khi David đồng ý đưa ông bố già tới Nebraska. Chặng đường đầu tiên của hai bố con là Hawthorn, nơi Woody sinh ra và lớn lên. Tin ông già đi không vững này thành triệu phú được đồn thổi. Anh thợ sửa xe hơi ngày nào bỗng dưng trở thành nhân vật nổi tiếng trong ngôi làng mà đa số là những người cũng đã gần đất xa trời.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Dern","avatar":""},{"name":"Will Forte","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Mary Louise Wilson","avatar":""},{"name":"Rance Howard","avatar":""},{"name":"Tim Driscoll","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Angela McEwan","avatar":""},{"name":"Glendora Stitt","avatar":""},{"name":"Elizabeth Moore","avatar":""},{"name":"Kevin Kunkel","avatar":""},{"name":"Dennis McCoig","avatar":""},{"name":"Ronald Vosta","avatar":""},{"name":"Missy Doty","avatar":""},{"name":"John Reynolds","avatar":""},{"name":"Jeffrey Yos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324462);
