INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung', 'Người Hùng', 'Machete Kills', 'https://phimimg.com/upload/vod/20231121-1/bbfc891e8cb141da0d2e14d12fbf50b2.jpg', 'https://phimimg.com/upload/vod/20231121-1/32d19ce8db47c33a8a9d999051b22517.jpg', '<p>Phim Machete Kills 2013 xoay quanh nhân vật chính Machete (Danny Trejo), người sẽ nhận lệnh từ Tổng thống truy lùng một tên trùm buôn lậu ma túy đang đe dọa nước Mỹ bằng một âm mưu tấn công hạt nhân cực kỳ nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Charlie Sheen","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Lady Gaga","avatar":""},{"name":"Alexa PenaVega","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Marko Zaror","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
