INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hung', 'Người Hùng', 'Machete Kills', 'người hùng machete kills danny trejo mel gibson demián bichir amber heard michelle rodriguez sofía vergara charlie sheen jessica alba lady gaga alexa penavega vanessa hudgens tom savini cuba gooding jr. antonio banderas walton goggins william sadler marko zaror j ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-chu-nhat-dang-nho', 'Ngày Chủ Nhật Đáng Nhớ', 'Remember Sunday', 'https://phimimg.com/upload/vod/20231123-1/a87c7af83f07f2fac63b5cfba1fef848.jpg', 'https://phimimg.com/upload/vod/20231123-1/bff0dd103cd9fa4b7bc2419de0967d6c.jpg', '<p>Một cô hầu bàn cô đơn, kém may mắn gặp một nhân viên cửa hàng trang sức đẹp trai, kỳ quặc và nghĩ rằng có lẽ cuối cùng cô đã gặp được Mr. Càng biết nhiều về Gus, Molly càng bị anh ta hấp dẫn. Nhưng cô ấy cũng bối rối. Gus lơ đãng, bận tâm. Có phải anh ấy đang che giấu điều gì đó? Câu trả lời ngắn gọn là có. Anh bất đắc dĩ phải chia sẻ với cô rằng kể từ khi bị chứng phình động mạch não, anh đã mất hoàn toàn trí nhớ ngắn hạn. Mỗi ngày đều là một ngày hoàn toàn mới, cuộc sống của anh lại bắt đầu lại. Mỗi ngày nhìn thấy Molly, anh đều cố gắng nhớ cô ấy là ai và cô ấy đại diện cho điều gì. Mỗi ngày anh đều phải yêu cô một lần nữa.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexis Bledel","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Merritt Wever","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Valerie Azlynn","avatar":""},{"name":"David Hoffman","avatar":""},{"name":"Jerry Adler","avatar":""},{"name":"Ann McKenzie","avatar":""},{"name":"Dana Gourrier","avatar":""},{"name":"Larisa Oleynik","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Richard Topol","avatar":""},{"name":"Chris Conner","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Sam Malone","avatar":""},{"name":"Michael Arata","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
