INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tu-ida', 'Nữ Tu Ida', 'Ida', 'https://phimimg.com/upload/vod/20231123-1/ba02082afcda3b3d16f7042c71de9716.jpg', 'https://phimimg.com/upload/vod/20231123-1/9e9b945f5b02bf25cee4888c1206d06e.jpg', '<p>Ida là một bộ phim đơn giản đến kỳ lạ với tiết tấu chậm rãi, những cảnh quay đầy chất thơ nhưng rất ám ảnh về sức nặng truyền tải cho người xem. Qua từng khung hình, bộ phim lật giở dần bí mật của sự tìm kiếm - tìm kiếm câu chuyện, tìm kiếm sự thật và tìm kiếm bản thể. Đạo diễn gốc Ba Lan - Pawel Pawlikowski, đã mang đến một trải nghiệm độc đáo tưởng như không còn xa lạ với chủ đề hậu Thế chiến II tại Ba Lan.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Agata Kulesza","avatar":""},{"name":"Agata Trzebuchowska","avatar":""},{"name":"Dawid Ogrodnik","avatar":""},{"name":"Jerzy Trela","avatar":""},{"name":"Adam Szyszkowski","avatar":""},{"name":"Halina Skoczyńska","avatar":""},{"name":"Joanna Kulig","avatar":""},{"name":"Dorota Kuduk","avatar":""},{"name":"Natalia Łągiewczyk","avatar":""},{"name":"Afrodyta Weselak","avatar":""},{"name":"Mariusz Jakus","avatar":""},{"name":"Izabela Dąbrowska","avatar":""},{"name":"Artur Janusiak","avatar":""},{"name":"Anna Grzeszczak","avatar":""},{"name":"Jan Wojciech Poradow","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
