INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-tu-ida', 'Nữ Tu Ida', 'Ida', 'nữ tu ida ida agata kulesza agata trzebuchowska dawid ogrodnik jerzy trela adam szyszkowski halina skoczyńska joanna kulig dorota kuduk natalia łągiewczyk afrodyta weselak mariusz jakus izabela dąbrowska artur janusiak anna grzeszczak jan wojciech poradow ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-ky-uc', 'Mê Cung Ký Ức', 'Trance', 'https://phimimg.com/upload/vod/20231123-1/dd56bebd1971d6bf0a24590b22cfc31e.jpg', 'https://phimimg.com/upload/vod/20231123-1/8f60745aba94da0e5a510197b182fea1.jpg', '<p>Một nhân viên làm việc ở trung tâm bán đấu giá lên kế hoạch chôm một bức tranh quý với sự hợp tác với một băng đảng chuyên ăn cắp tranh. Tuy nhiên sau khi bị đánh vào đầu, anh chàng này đã mất trí nhớ và điều oái ăm là anh ta là người duy nhất biết chỗ giấu bức tranh. Nhiều lần cố gắng nhớ lại không thành của anh chàng khiến bọn cướp nghi ngờ sự trung thực của anh này và rồi chúng quyết định thuê một phụ nữ biết thôi miên để xâm nhập vào não của anh ta. Và nhiều câu chuyện bí ẩn được vỡ ra từ đó.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Danny Sapani","avatar":""},{"name":"Matt Cross","avatar":""},{"name":"Wahab Sheikh","avatar":""},{"name":"Mark Poltimore","avatar":""},{"name":"Tuppence Middleton","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"Michael Shaeffer","avatar":""},{"name":"Tony Jayawardena","avatar":""},{"name":"Vincent Montuel","avatar":""},{"name":"Jai Rajani","avatar":""},{"name":"Spencer Wilding","avatar":""},{"name":"Gursharan Chaggar","avatar":""},{"name":"Edward Rising","avatar":""},{"name":"Lee N","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '