INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chua-mot-ai', 'Không Chừa Một Ai', 'No One Lives', 'https://phimimg.com/upload/vod/20231120-1/40e3ea2f228987402fc0ace1f0a54a50.jpg', 'https://phimimg.com/upload/vod/20231120-1/57469246de4e389ea0bef774404d2bbf.jpg', '<p>Một băng nhóm giết người tàn nhẫn trên đường cao tốc bắt cóc một cặp vợ chồng giàu có đi du lịch xuyên quốc gia chỉ để phát hiện ra rằng mọi thứ không như vẻ ngoài của chúng.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Evans","avatar":""},{"name":"Adelaide Clemens","avatar":""},{"name":"Laura Ramsey","avatar":""},{"name":"Lee Tergesen","avatar":""},{"name":"Derek Magyar","avatar":""},{"name":"America Olivo","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Lindsey Shaw","avatar":""},{"name":"Lenore Banks","avatar":""},{"name":"George Murdoch","avatar":""},{"name":"Gary Grubbs","avatar":""},{"name":"Andrea Frankle","avatar":""},{"name":"Rob Steinberg","avatar":""},{"name":"Michael Harrity","avatar":""},{"name":"Chris Carnel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
