INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-viet-huyen-thoai', 'Những Người Viết Huyền Thoại', 'The Legend Makers', 'https://phimimg.com/upload/vod/20231120-1/4d9d9053e95b058b752290039de0db15.jpg', 'https://phimimg.com/upload/vod/20231120-1/c1f37154fff55cc31be0825d94be5806.jpg', '<p>Những người viết huyền thoại lấy bối cảnh cuộc chiến tranh chống Mỹ cứu nước thời kỳ những năm 1960 khi tình thế cần chi viện xăng dầu cho chiến trường miền Nam ngày càng trở nên cấp bách và cần thiết. Thông qua việc xây dựng đường ống dẫn dầu 5000 km dọc Trường Sơn để chuẩn bị cho những trận đánh lớn thay vì những trận đánh du kích nhỏ lẻ, bộ phim đã dựng lên những câu chuyện tựa như khúc tráng ca hào hùng cảm động về sự cống hiến của một thế hệ thanh niên Việt Nam.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Tăng Bảo Quyên","avatar":""},{"name":"Trương Minh Quốc Thái","avatar":""},{"name":"Bảo Thanh","avatar":""},{"name":"Hoàng Hải","avatar":""},{"name":"Đinh Tuấn Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324462);
