INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-ngua-khumba', 'Chú Ngựa Khumba', 'Khumba', 'https://phimimg.com/upload/vod/20231120-1/7ef68aad116305abff1f2a561658d848.jpg', 'https://phimimg.com/upload/vod/20231120-1/cae66ca6d2c2f066f300ee711a9a0df2.jpg', '<p>Một con ngựa vằn nửa sọc bị đổ lỗi là nguyên nhân gây ra hạn hán và rời đàn để tìm kiếm những sọc còn thiếu của mình. Anh ta được tham gia vào nhiệm vụ của mình bởi một con linh dương đầu bò bảo vệ quá mức và một con đà điểu lòe loẹt; họ đánh bại con báo hung bạo và cứu đàn của nó.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2013, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Jake T. Austin","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Anika Noni Rose","avatar":""},{"name":"Catherine Tate","avatar":""},{"name":"Jennifer Cody","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Roger L. Jackson","avatar":""},{"name":"Julianna Rose","avatar":""},{"name":"Sam Riegel","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324462);
