INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-breakdance', 'Đấu Trường Breakdance', 'Battle of the Year', 'https://phimimg.com/upload/vod/20231201-1/c8ed1aa578410686ec1befe94f3fdab4.jpg', 'https://phimimg.com/upload/vod/20231201-1/9eb70c27527aeab096ce2db350967554.jpg', '<p>Phim kể về 1 nhóm nhảy người Mỹ với sự giúp đỡ của vị huấn luyện viên tài ba (Josh Holloway) đã cùng đấu tranh để đạt được ước mơ của mình cho dù bị sự hiểm lầm của xã hội và chính gia đình mình. Cuộc sống của họ gặp trở ngại ở Pháp khi cả đội phải áp dụng kỹ năng của mình cho bài kiểm tra cuối cùng: đấu với các đội từ 18 quốc gia đang cạnh tranh cho danh hiệu vô địch thế giới tại trận chung kết Battle of the Year.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Holloway","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Chris Brown","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Caity Lotz","avatar":""},{"name":"Terrence Jenkins","avatar":""},{"name":"Weronika Rosati","avatar":""},{"name":"Ivan ''Flipz'' Velez","avatar":""},{"name":"Jesse Erwin","avatar":""},{"name":"Steve Terada","avatar":""},{"name":"Joshua Lee Ayers","avatar":""},{"name":"Luis Rosado","avatar":""},{"name":"Richard Maguire","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
