INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tinh-yeu', 'Hành Trình Tình Yêu', 'Chennai Express', 'https://phimimg.com/upload/vod/20231116-1/6e56397484e564df9a927ee2148aa8ee.jpg', 'https://phimimg.com/upload/vod/20231116-1/2a42c90cd974615eb7d837ecc553465b.jpg', '<p>Rahul bắt đầu cuộc hành trình đến một thị trấn nhỏ ở Tamil Nadu để thực hiện ước nguyện cuối cùng của ông nội: ngâm tro cốt của ông trong Nước thánh Rameshwaram. Trên đường đi, anh gặp một người phụ nữ đến từ một gia đình độc nhất ở miền Nam. Khi họ tìm thấy tình yêu thông qua hành trình này ở vùng đất hoa lệ của Nam Ấn Độ, một chuyến đi bất ngờ đang chờ đợi họ.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"Nikitin Dheer","avatar":""},{"name":"Manorama","avatar":""},{"name":"Sathyaraj","avatar":""},{"name":"Mukesh Tiwari","avatar":""},{"name":"Kamini Kaushal","avatar":""},{"name":"Lekh Tandon","avatar":""},{"name":"Rakesh Kukreti","avatar":""},{"name":"Priyamani","avatar":""},{"name":"Delhi Ganesh","avatar":""},{"name":"Mohan Raman","avatar":""},{"name":"Yogi Babu","avatar":""},{"name":"Jasper","avatar":""},{"name":"Besant Ravi","avatar":""},{"name":"King Kong","avatar":""},{"name":"Jimmy Moses","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
