INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phuc-tap', 'Chuyện phức tạp', 'A Complicated Story', 'https://phimimg.com/upload/vod/20231116-1/a5f2be0abfc8fc1d5dbfcbe3d65c27c9.jpg', 'https://phimimg.com/upload/vod/20231116-1/eacc12a0b3dc29ceae8b0f8618c06c8f.jpg', '<p>Một sinh viên Trung Quốc đại lục túng tiền kí hợp đồng đẻ thuê cho một cặp vợ chồng người Hong Kong, nhưng hợp đồng bất ngờ bị chấm dứt khiến cuộc sống của cô bị đảo lộn.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jacqueline Zhu Zhi-Ying","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"John Shum Kin-Fun","avatar":""},{"name":"Stephanie Che","avatar":""},{"name":"Wang Ziyi","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Cherrie Ying Choi-Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
