INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-phuc-tap', 'Chuyện phức tạp', 'A Complicated Story', 'chuyện phức tạp a complicated story jacqueline zhu zhi-ying jacky cheung john shum kin-fun stephanie che wang ziyi deanie ip lo hoi-pang cherrie ying choi-yi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-so-khanh-tot-so', 'Chàng Sở Khanh Tốt Số', 'Don Jon', 'https://phimimg.com/upload/vod/20231116-1/38b9c71ca65e9c77376ded2a95de3d8d.jpg', 'https://phimimg.com/upload/vod/20231116-1/8548e833c2193b4f1437517d353b5cff.jpg', '<p>Bartender Jon Martello (Joseph Gordon-Levitt) ở New Jersey biết điều gì là quan trọng: bạn bè, gia đình, xe hơi, nhà thờ của anh ấy, những cuộc chinh phục tình dục của anh ấy - và khiêu dâm. Trên thực tế, Jon là một người nghiện phim khiêu dâm và chưa bao giờ có một mối quan hệ chân chính với phụ nữ. Tuy nhiên, khi gặp Barbara (Scarlett Johansson), anh ta phải thay đổi phương thức hoạt động của mình, vì Barbara sẽ không dễ dàng lên giường. Lần đầu tiên trong đời, Jon bắt đầu một cuộc tán tỉnh thực sự, nhưng nỗi ám ảnh của anh về tình dục có nguy cơ phá hỏng mọi thứ.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Tony Danza","avatar":""},{"name":"Glenne Headly","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Lindsey Broad","avatar":""},{"name":"Rob Brown","avatar":""},{"name":"Jeremy Luke","avatar":""},{"name":"Paul Ben-Victor","avatar":""},{"name":"Italia Ricci","avatar":""},{"name":"Amanda Perez","avatar":""},{"name":"Sarah Dumont","avatar":""},{"name":"Sloane Avery","avatar":""},{"name":"Loanne Bishop","avatar":""},{"name":"Arin Babaian","avatar":""},{"name":"Arielle Reitsma","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3