INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-oggy-va-nhung-chu-gian-tinh-nghich', 'Mèo Oggy Và Những Chú Gián Tinh Nghịch', 'Oggy and the Cockroaches: The Movie', 'https://phimimg.com/upload/vod/20231116-1/94ba337b341de1b44736003cb6eda199.jpg', 'https://phimimg.com/upload/vod/20231116-1/2059190367b12877a084aa9ac5f9764f.jpg', '<p>Nhân vật chính trong phim là Oggy - chú mèo da xanh tốt bụng và thật thà - sống trong cùng một ngôi nhà với mèo Jack. Oggy sẽ là chú mèo hạnh phúc nhất nếu ba chú gián: Dee Dee, Joey và Marky không xuất hiện và quyết định cư trú tại ngôi nhà thoải mái của mình. Ba chú gián ngốc nghếch, tinh nghịch luôn nghĩ ra đủ trò tinh quái để chọc phá hai chú mèo, đặc biệt là Oggy. Cuộc chiến giữa chúng dường như không bao giờ có hồi kết.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324462);
