INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thinh-no-cua-carrie', 'Cơn Thịnh Nộ Của Carrie', 'Carrie', 'https://phimimg.com/upload/vod/20231116-1/f78f023339e0969790531e1795088d33.jpg', 'https://phimimg.com/upload/vod/20231116-1/1e781a4a2590f7401c8e25faab956011.jpg', '<p>Cơn thịnh nộ của Carrie - Carrie: Dựa trên cuốn tiểu thuyết cùng tên của nhà văn Stephen King, bộ phim xoay quay cô gái nhỏ (do Chloe Grace Moretz thủ vai) có khả năng di chuyển các đồ vật nhưng lại bị chính bà mẹ cuồng tính (do Jullianne More đóng) ngược đãi. Ở trường, chính cô cũng bị các bạn mình xa lánh và hành hạ. Đoạn trailer dài hơn 2 phút đã cung cấp cho người xem một cái nhìn gần như là đầy đủ về ý tưởng mà Peirce muốn truyền tải và gần như Carrie được hứa hẹn sẽ là một bộ phim tâm lý rùng rợn hết sức nặng nề.</p>', 'Full', 1, 'single', 'completed', 9, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Gabriella Wilde","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Portia Doubleday","avatar":""},{"name":"Ansel Elgort","avatar":""},{"name":"Alex Russell","avatar":""},{"name":"Zoë Belkin","avatar":""},{"name":"Samantha Weinstein","avatar":""},{"name":"Karissa Strain","avatar":""},{"name":"Katie Strain","avatar":""},{"name":"Demetrius Joyette","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Arlene Mazerolle","avatar":""},{"name":"Evan Gilchrist","avatar":""},{"name":"Eddie M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
