INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-he-vang-92', 'Thế Hệ Vàng 92', 'The Class of ‘92', 'https://phimimg.com/upload/vod/20231120-1/05a3a4f3b09c9adb55bbd219df81fd39.jpg', 'https://phimimg.com/upload/vod/20231120-1/4375fe76942f3bfbdaddc263d299b35e.jpg', '<p>Một chi tiết về sự nổi lên và trở thành siêu sao thể thao toàn cầu của sáu cầu thủ bóng đá trẻ cực kỳ tài năng của Manchester United (David Beckham, Nicky Butt, Ryan Giggs, Paul Scholes, Phil và Gary Neville). Bộ phim kể về giai đoạn 1992-1999, với đỉnh cao là chức vô địch cúp châu Âu của Manchester United.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Beckham","avatar":""},{"name":"Paul Scholes","avatar":""},{"name":"Phil Neville","avatar":""},{"name":"Gary Neville","avatar":""},{"name":"Nicky Butt","avatar":""},{"name":"Éric Cantona","avatar":""},{"name":"Danny Boyle","avatar":""},{"name":"Zinedine Zidane","avatar":""},{"name":"Robbie Savage","avatar":""},{"name":"Tony Blair","avatar":""},{"name":"Ryan Giggs","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324462);
