INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-tai-uong', 'Kỳ Nghỉ Tai Ương', 'Long Weekend (Thongsook)', 'https://phimimg.com/upload/vod/20231119-1/5e913597f99671d2bf84f19d20522c08.jpg', 'https://phimimg.com/upload/vod/20231119-1/006d962e453b5a4a6ac050e689df1b40.jpg', '<p>Thongsook có cảm tình với cô nàng Nam xinh đẹp. Tuy vậy, cậu lại thường hay bị đám bạn cùng nhóm của Nam trêu chọc và bắt nạt. Khi nhóm bạn trẻ tới một hòn đảo bị bỏ hoang để nghỉ ngơi cuối tuần, những người bạn của Nam đã nhốt Thongsook lại trong một ngôi miếu thờ cổ. Và đó chính là khởi điểm cho những tai ương kinh hoàng sắp sửa giáng xuống cả hội…</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Akkaranat Ariyaritwikul","avatar":""},{"name":"Chinawut Indracusin","avatar":""},{"name":"Sean Jindachot","avatar":""},{"name":"Kitlapat Korasudraiwon","avatar":""},{"name":"Natpassara Adulyamethasiri","avatar":""},{"name":"Sheranut Yusananda","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
