INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-thuc-cua-the-gioi', 'Kết Thúc Của Thế Giới', 'The World''s End', 'https://phimimg.com/upload/vod/20231119-1/3baaf9a94c55d690b4b6621c17ea7a39.jpg', 'https://phimimg.com/upload/vod/20231119-1/ae8d60f61f15e754953df4e8558aee06.jpg', '<p>5 người bạn thời thơ ấu, trở về lại quê nhà của họ cho một buổi tiệc nhậu linh đình. Khi họ viếng thăm trở lại quán rượu mà họ đã tới 20 năm trước, họ nhận thức được là đang bắt đầu trên một cuộc hành trình cứu thoát nhân loại từ một cuộc xâm chiếm của người máy. Pegg nổi bật là một người đàn ông chưa trưởng thành trong lứa tuổi 40, cố gắng tuyệt vọng níu kéo tuổi trẻ của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Darren Boyd","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Steve Oram","avatar":""},{"name":"Reece Shearsmith","avatar":""},{"name":"Nicholas Burns","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Thomas Law","avatar":""},{"name":"Zachary Bailess","avatar":""},{"name":"Jasper Levine","avatar":""},{"name":"James T","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324462);
