INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tia-chop-mat-na-den', 'Tia Chớp Mặt Nạ Đen', 'Sparks', 'https://phimimg.com/upload/vod/20231119-1/aab1ac312c555bb5a0f489a6843cf338.jpg', 'https://phimimg.com/upload/vod/20231119-1/232181571d8ddad2df1ee334a0588c2e.jpg', '<p>Một mảnh thiên thạch đã rơi xuống khu Rochester, New York làm hơn 230 người chết. 13 người may mắn sống sót đều nhiễm phóng xạ và trở thành người đột biến. Trong số đó có Kevin - kẻ gây ra các vụ giết người hàng loạt trong nhiều năm qua. Giờ đây, hắn lại muốn thống trị thế giới bằng sức mạnh đột biến của mình. Ian Sparks và Lady Heavenly phải làm gì để chống lại gã Kevin độc ác?</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chase Williamson","avatar":""},{"name":"Ashley Bell","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"William Katt","avatar":""},{"name":"Marina Squerciati","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Scott Rinker","avatar":""},{"name":"David Sobolov","avatar":""},{"name":"Larry Cedar","avatar":""},{"name":"Esteban Cueto","avatar":""},{"name":"Dave Hanson","avatar":""},{"name":"Stephen Kearin","avatar":""},{"name":"Jeremy Rowley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
