INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-dam-me', 'Hành Trình Của Đam Mê', 'Inside Llewyn Davis', 'https://phimimg.com/upload/vod/20231118-1/690735411aab12f32bc885927f618e79.jpg', 'https://phimimg.com/upload/vod/20231118-1/4d551daffa28d8035c1e5d95f43cfe76.jpg', '<p>Bộ phim kể lại quãng thời gian đúng một tuần của anh chàng ca sĩ kiêm sáng tác nhạc Folk Llewyn Davis. Cũng giống như các nghệ sỹ tự do khác, Llewyn Davis đang phải vật lộn với cuộc sống vừa để nuôi thân vừa tìm cách phát triển sự nghiệp. Trong một tuần đó, anh chạy đôn chạy đáo để kiếm từng đồng, trình diễn ở phòng trà, thậm chí chẳng có nhà cửa mà phải nhờ vào bạn bè.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Jerry Grayson","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Jeanine Serralles","avatar":""},{"name":"Stark Sands","avatar":""},{"name":"Alex Karpovsky","avatar":""},{"name":"Benjamin Pike","avatar":""},{"name":"Jake Ryan","avatar":""},{"name":"Helen Hong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324462);
