INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-trinh-cua-dam-me', 'Hành Trình Của Đam Mê', 'Inside Llewyn Davis', 'hành trình của đam mê inside llewyn davis oscar isaac carey mulligan john goodman garrett hedlund justin timberlake adam driver f. murray abraham robin bartlett max casella jerry grayson ethan phillips jeanine serralles stark sands alex karpovsky benjamin pike jake ryan helen hong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-2', 'Người Bảo Vệ 2', 'The Protector 2', 'https://phimimg.com/upload/vod/20231117-1/37281b930389330aa90f6b8b0c5d9ad1.jpg', 'https://phimimg.com/upload/vod/20231117-1/53765498426c36447d4edc7cba95263c.jpg', '<p>Câu chuyện bắt đầu sau cái chết của Boss Suchart, một chủ trang trại voi quyền lực. Các sát thủ đã cố tình ngụy tạo bằng chứng giả để đổ tội cho Kham (Tony Jaa) khi anh vô tình xuất hiện tại hiện trường vụ án. Kham buộc phải bỏ trốn trước khi cảnh sát truy nã. Trong khi đó, hai cô cháu gái sinh đôi của Boss Suchart là Ping Ping (Jeeja Yanin) và Xu Xinh (Teerada Kittisiriprasert) cũng tìm cách trả thù cho người chú của mình. May mắn cho Kham, anh gặp Sergeant Mark (Mum Jokmok), một đặc vụ Interpol được cử đến Thái Lan trong một nhiệm vụ bí mật. Trước sự truy đuổi của nhiều phe phái khác nhau, Kham cũng được giao nhiệm vụ tìm kiếm chú voi yêu quý của mình là Khon đã biến mất cùng với cái chết của Boss Suchart. Trong cuộc hành trình gian nan đó, Kham còn tham gia vào một cuộc thi đấu võ đài trong thế giới ngầm do ông chủ LC (RZA) tổ chức. Các võ sĩ thuộc LC chỉ được gọi tên, bao gồm nữ sát thủ gợi cảm Twenty (Yaya Ying Rhatha Phongam) và võ sĩ xảo quyệt số 2 (Marrese Crump).</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Marrese Crump","avatar":""},{"name":"JeeJa Yanin","avatar":""},{"name":"RZA","avatar":""},{"name":"Rhatha Phongam","avatar":""},{"name":"Jawed El Berni","avatar":""},{"name":"Raiden Integra","avatar":""},{"name":"Kazu Patrick Tang","avatar":""},{"name":"Eddie Ruiz","avatar":""},{"name":"Eakasit Thairaat","avatar":""},{"name":"Pornchai Hongrattanaporn","avatar":""},{"name":"David Ismalone","avatar":""},{"name":"Theerada Kittisiriprasert","avatar":""},{"name":"Sophon Phoonsawat","avatar":""},{"name":"Boonso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
