INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-cuoc-doi-2013', 'Làm Lại Cuộc Đời', 'Dreams', 'https://phimimg.com/upload/vod/20231129-1/dc010686d0e6ab71d91a035ad2bbadd6.jpg', 'https://phimimg.com/upload/vod/20231129-1/66bf1338d1d7200fe203f53d9a276c64.jpg', '<p>Mia ước mơ thành ca sĩ, Quentin mơ ước nhảy múa, Paalo muốn sửa đổi mối quan hệ với con gái và Alonzo hy vọng sẽ kết nối lại với gia đình mình, nhưng thực tế như một tên tội phạm khét tiếng đẩy ước mơ của họ vào một trận chiến khó khăn. Bốn câu chuyện này được đan lại với nhau để tạo ra một câu chuyện đầy cảm hứng.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Syesha Mercado","avatar":""},{"name":"Angie Stone","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324462);
