INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tarzan', 'Tarzan', 'Tarzan', 'https://phimimg.com/upload/vod/20231116-1/4ff8bb9d2cd8360849a56d80f823f32a.jpg', 'https://phimimg.com/upload/vod/20231116-1/58d062941c47b2441df2a5ad7b9c6bdd.jpg', '<p>Một trong những câu chuyện kinh điển và được kính trọng nhất mọi thời đại, Edgar Rice Burroughs&quot; Tarzan trở lại màn ảnh rộng với thế hệ mới. Tarzan và Jane phải đối mặt với đội quân đánh thuê được phái đi bởi CEO độc ác của Greystoke Energies, người đã tiếp quản công ty từ tay cha mẹ của Tarzan, sau khi họ chết trong một vụ tai nạn máy bay ở khu rừng châu Phi.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Kellan Lutz","avatar":""},{"name":"Spencer Locke","avatar":""},{"name":"Les Bubb","avatar":""},{"name":"Joe Cappelletti","avatar":""},{"name":"Brian Huskey","avatar":""},{"name":"Mark Deklin","avatar":""},{"name":"Jaime Ray Newman","avatar":""},{"name":"Robert Capron","avatar":""},{"name":"Jonathan Morgan Heit","avatar":""},{"name":"Anton Zetterholm","avatar":""},{"name":"Jason Hildebrandt","avatar":""},{"name":"Jonathan Tweedie","avatar":""},{"name":"Rebecca Reaney","avatar":""},{"name":"Trevor St. John","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Maximilian Allgei","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324462);
