INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-nguoi-may', 'Sát Thủ Người Máy', 'The Machine', 'https://phimimg.com/upload/vod/20231116-1/7807058fae1a0f416b3207a2e0cd6927.jpg', 'https://phimimg.com/upload/vod/20231116-1/7094e951ff26da5d9e867b17e5da1499.jpg', '<p>Đã chìm sâu vào Chiến tranh Lạnh lần thứ hai, Bộ Quốc phòng Anh đang tìm kiếm một loại vũ khí có thể thay đổi cuộc chơi. Lập trình viên Vincent McCarthy vô tình đưa ra câu trả lời trong The Machine, một người máy siêu mạnh. Khi một lỗi lập trình khiến nguyên mẫu phá hủy phòng thí nghiệm của anh, McCarthy đã thực hiện những nỗ lực đầy ám ảnh của mình dưới lòng đất, tránh xa những con mắt tò mò.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Caity Lotz","avatar":""},{"name":"Toby Stephens","avatar":""},{"name":"Denis Lawson","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Pooneh Hajimohammadi","avatar":""},{"name":"Jonathan Byrne","avatar":""},{"name":"Jade Croot","avatar":""},{"name":"John-Paul Macleod","avatar":""},{"name":"Helen Griffin","avatar":""},{"name":"Siwan Morris","avatar":""},{"name":"Nicola Reynolds","avatar":""},{"name":"Alan Low","avatar":""},{"name":"Sule Rimi","avatar":""},{"name":"Joshua Higgott","avatar":""},{"name":"Giles Thomas","avatar":""},{"name":"Cornelius Garrett","avatar":""},{"name":"Sam Ellis","avatar":""},{"name":"Ric","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
