INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-vet-ma-ca-rong', 'Dấu Vết Ma Cà Rồng​', 'Byzantium', 'https://phimimg.com/upload/vod/20231116-1/00fd62dfadb33cbfb4b01f5542f62242.jpg', 'https://phimimg.com/upload/vod/20231116-1/669467f073e5b821f05397102b9e811d.jpg', '<p>Hai chị em Eleanor và Clara dọn đến ở một thị trấn cổ của nước Anh. Cô chị Clara thì không ngần ngại thuyết phục mọi người về nguồn gốc ma cà rồng của họ nhưng dường như chẳng ai chịu tin. Cho tới khi một loạt các vụ mất tích bí ẩn trong thị trấn xảy ra, mọi người mới đặt dấu hỏi về hành tung của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gemma Arterton","avatar":""},{"name":"Saoirse Ronan","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"Kate Ashfield","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Uri Gavriel","avatar":""},{"name":"Thure Lindhardt","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Barry Cassin","avatar":""},{"name":"David Heap","avatar":""},{"name":"Warren Brown","avatar":""},{"name":"Ruby Snape","avatar":""},{"name":"Jenny Kavanagh","avatar":""},{"name":"Glenn Doherty","avatar":""},{"name":"Edyta Budnik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
