INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vat-chu-2013', 'Vật Chủ', 'The Host', 'https://phimimg.com/upload/vod/20230917-1/e319eb716049847c1a488f23608cda60.jpg', 'https://phimimg.com/upload/vod/20230917-1/5d1ffab69b671eabfbd91daabd6e2479.jpg', '<p><span style="font-family: ">Phim được chuyển thể từ tiểu thuyết cùng tên của nhà văn Stephenie Meyer – tác giả loạt truyện kinh dị lãng mạn nổi tiếngTwilight. Bộ phim kể về câu chuyện tình yêu của đôi bạn trẻ Melanie Stryder và Jared trong bối cảnh Trái Đất bị xâm chiếm bởi những người ngoài hành tinh có khả năng chiếm giữ cơ thể con người, biến họ thành những vật chủ. Melanie, một trong những người sống sót cuối cùng, bị một trong những linh hồn ký sinh đó xâm chiếm cơ thể của Melanie Stryder. Nhưng thay vì thực hiện nhiệm vụ của giống loài là chiếm giữ Trái Đất, &quot;Lữ Hành&quot; trở nên gắn kết với vật chủ của mình và bắt đầu giải cứu những con người còn tự do...</span></p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Max Irons","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Chandler Canterbury","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Stephen Rider","avatar":""},{"name":"Alex Russell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324462);
