INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-trinh-dien-ngoan-muc', 'Màn Trình Diễn Ngoạn Mục', 'Blinder', 'null', 'https://phimimg.com/upload/vod/20231117-1/54527c24d5bd578af10bc53acb13b781.jpg', '<p>Một ngôi sao bóng đá bị thất sủng trở về nhà để đối mặt với quá khứ của mình. Ông thấy sức mạnh để đoàn tụ câu lạc bộ bóng đá của mình, nhen nhóm lại một tình yêu đã mất, và một lần nữa khám phá ra niềm đam mê của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Oliver Ackland","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Zoe Carides","avatar":""},{"name":"Anna Hutchison","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Rose McIver","avatar":""},{"name":"Bob Morley","avatar":""},{"name":"Aaron Jakubenko","avatar":""},{"name":"Finn Ireland","avatar":""},{"name":"Damien Di Paola","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
