INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-starving-games', 'The Starving Games', 'The Starving Games', 'https://phimimg.com/upload/vod/20231117-1/ad38ea90d7d52bca38c15bded45e4147.jpg', 'https://phimimg.com/upload/vod/20231117-1/64933f7985f85bdae8b11e8adc1eedc6.jpg', '<p>Đặt trong góc đáng buồn nhất của một tương lai hậu tận thế, nữ anh hùng Kantmiss Evershot (Maiara Walsh) tình nguyện viên để đưa vị trí của em gái mình thao túng của cô ấy trong bảy mươi lăm trò chơi đói khát hàng năm. Khi làm như vậy, cô phải để lại phía sau Dale-a-bạn bè của mình (Brant Daugherty) và hợp tác với con trai của Bakey Baker Peter Malarkey (Cody Allen Christian) trong một cuộc chiến cho cuộc sống của cô. Nhưng xin chờ chút nữa! Cô ấy cũng có thể giành được một ham già, một phiếu giảm giá cho một phụ dài bằng chân với giá sáu inch, và một người dưa chua ăn một phần! Trong các trò chơi đói khát, Friedberg và Seltzer&#39;s Sixth&#39;s Cinematic Cinematic of Office Hit, The Preific Parody Duo có các điểm tham quan được đào tạo về bom tấn phiêu lưu The Hunger Games! Đó là tất cả những lời cười và một nửa lượng calo khi chúng kéo hàng chục mũi tên bị rắn, gai tại các bộ phim khoa học, hành động và tưởng tượng từ những nhân vật và những người nổi tiếng vĩ đại và mạnh mẽ đến Pop như Harry Potter và Taylor Swift.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maiara Walsh","avatar":""},{"name":"Cody Christian","avatar":""},{"name":"Brant Daugherty","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Ross Wyngaarden","avatar":""},{"name":"Lauren Bowles","avatar":""},{"name":"Dean J. West","avatar":""},{"name":"Michael Hartson","avatar":""},{"name":"Theodus Crane","avatar":""},{"name":"Chris Marroy","avatar":""},{"name":"Eryn L. Davis","avatar":""},{"name":"Kennedy Hermansen","avatar":""},{"name":"Juhahn Jones","avatar":""},{"name":"Taylor Ashley Murphy","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Rob Steinberg","avatar":""},{"name":"Bri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
