INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-sat-nhan-1', 'Truy Tìm Sát Nhân 1', 'Garage Sale Mystery 1', 'https://phimimg.com/upload/vod/20231115-1/4d2e8f6799d3a1fd0900d5428424246f.jpg', 'https://phimimg.com/upload/vod/20231115-1/bcb2d7937d204dca7b535e7f95bb9174.jpg', '<p>Truy Tìm Sát Nhân 1 - Garage Sale Mystery 1 kể về Jennifer Shannon, người luôn có thể tìm được những thứ đồ quý giá khi đến hội chợ đồ cũ. Cô đã tạo dựng được sự nghiệp từ khả năng săn kho báu ấy. Khi một chuỗi các vụ trộm xảy ra tại thị trấn, Jennifer đã dùng đôi mắt tinh tường cùng khả năng giải quyết vấn đề để tìm ra mối liên hệ giữa các vụ trộm cắp và hội chợ bán đồ.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Lori Loughlin","avatar":""},{"name":"Rick Ravanello","avatar":""},{"name":"Sara Canning","avatar":""},{"name":"Brendan Meyer","avatar":""},{"name":"Sarah Strange","avatar":""},{"name":"Andrew Dunbar","avatar":""},{"name":"Cameron Bancroft","avatar":""},{"name":"Britt Irvin","avatar":""},{"name":"Anne Marie DeLuise","avatar":""},{"name":"Matty Finochio","avatar":""},{"name":"Sebastian Stewart","avatar":""},{"name":"Jim Thorburn","avatar":""},{"name":"Doug Abrahams","avatar":""},{"name":"Mark Acheson","avatar":""},{"name":"Mary Black","avatar":""},{"name":"Robert Lawrenson","avatar":""},{"name":"Dolore","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324462);
