INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-mac-dinh-menh', 'Sa Mạc Định Mệnh', 'Collision', 'https://phimimg.com/upload/vod/20231115-1/e26044e94b4c834e5992f82815de1fd0.jpg', 'https://phimimg.com/upload/vod/20231115-1/8e8cbad8cccfa441c9f50b90ca2fdd71.jpg', '<p>Lấy bối cảnh hai vợ chồng đi nghỉ ở Ma-rốc, người vợ âm mưu giết chồng với sự giúp đỡ của người tình. Kế hoạch trở nên tồi tệ khi người yêu và chồng của cô gặp tai nạn xe hơi khủng khiếp trên một con đường sa mạc xa xôi. Họ thoát khỏi đống ô tô chồng chất tại một ngã tư sa mạc và chạm trán với nhóm người sống sót, bao gồm một kẻ buôn lậu bị truy nã, một cảnh sát chìm, một kẻ bắt cóc, một em bé và một người Úc bất tỉnh. Họ dấn thân vào hành trình lừa dối và khám phá mà đỉnh điểm là buổi souk Tangiers.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Roschdy Zem","avatar":""},{"name":"Jaimie Alexander","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Moussa Maaskri","avatar":""},{"name":"Charlie Bewley","avatar":""},{"name":"Affif Ben Badra","avatar":""},{"name":"Carlos Leal","avatar":""},{"name":"Gabriella Wright","avatar":""},{"name":"Hamza Kadri","avatar":""},{"name":"Dominique Fouassier","avatar":""},{"name":"Mansour Badri","avatar":""},{"name":"Joseph Beddelem","avatar":""},{"name":"Abdelilah Nadif","avatar":""},{"name":"Noureddine Hajoujou","avatar":""},{"name":"Mustaph","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
