INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hon-tren-song-chao-phraya', 'Hoàng Hôn Trên Sông Chao Phraya', 'Sunset at Chaophraya', 'https://phimimg.com/upload/vod/20231115-1/f122b8b406cd596a003573cb7f3ea4a2.jpg', 'https://phimimg.com/upload/vod/20231115-1/04e0846f20b624a9969b349b876d7bae.jpg', '<p>Bộ phim lấy bối cảnh Thế chiến 2 ở Thái Lan, một người lính Nhật Bản tên là Kobori đem lòng yêu cô gái Thái Lan Ang Angumumalin. Kobori sẵn sàng làm mọi việc để phụng sự tổ quốc nhưng anh sẽ phải đánh đổi tất cả để cứu lấy tình yêu của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Oranate D. Caballes","avatar":""},{"name":"Nitit Warayanon","avatar":""},{"name":"Kulpong Boonnak","avatar":""},{"name":"Surachai Chantimatorn","avatar":""},{"name":"Mongkol Utok","avatar":""},{"name":"Peron Yasu","avatar":""},{"name":"Mayreeya Mungsiri","avatar":""},{"name":"Chamnian Charoensap","avatar":""},{"name":"Tatsunobu Tanikawa","avatar":""},{"name":"Toshiyuki Goto","avatar":""},{"name":"Darren Fox","avatar":""},{"name":"Norio Suzuki","avatar":""},{"name":"Kiradej Ketakinta","avatar":""},{"name":"Ulrich Heinz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324462);
