INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-5-nang-tien', 'Nhà Có 5 Nàng Tiên', 'Five Fairies In The House', 'https://phimimg.com/upload/vod/20231113-1/38675282b8c901ad02ea38ddbff91e5b.jpg', 'https://phimimg.com/upload/vod/20231113-1/27c2ef8c83a7f64968a870ac98413b54.jpg', '<p>Phim kể về một đôi vợ chồng nghèo là ông Tiên Cảnh (Hoài Linh) và bà Mai Nhỏ Nhẹ (Việt Hương) làm nghề lượm rác mơ ước có một mụn con. Một ngày nọ, họ nhặt được và cưu mang không chỉ một mà đến năm bé gái mồ côi. Cả hai người yêu quý năm em bé ấy như con ruột và cho ăn học đàng hoàng. Thời gian trôi đi, chúng trở thành những thiếu nữ giỏi giang, xinh đẹp. Mỗi người đều sở hữu một nhan sắc tuyệt trần tới mức nhiều người gọi họ bằng cái tên &quot;5 nàng tiên&quot; (Ngân Khánh, Miu Lê, Bảo Anh, Trương Nhi và Minh Thảo).</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Hoài Linh","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Ngân Khánh","avatar":""},{"name":"Miu Lê","avatar":""},{"name":"Chí Tài","avatar":""},{"name":"Tấn Beo","avatar":""},{"name":"Phương Thanh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
