INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('iron-man-hulk-heroes-united', 'Iron Man & Hulk: Heroes United', 'Iron Man & Hulk: Heroes United', 'https://phimimg.com/upload/vod/20231113-1/1f534463e172a3515d5b02df3eb7034a.jpg', 'https://phimimg.com/upload/vod/20231113-1/66ab29b0e77ea7424b13ffda3ce84ecb.jpg', '<p>Người Sắt bất khả chiến bại và Hulk đáng kinh ngạc phải hợp lực để cứu Trái đất khỏi mối đe dọa lớn nhất! Khi hai nhà khoa học Hydra cố gắng tăng cường năng lượng cho Lò phản ứng Hồ quang Stark bằng Năng lượng Gamma của Hulk, họ giải phóng một sinh vật hoàn toàn bằng điện có tên là Zzzax - và hắn khao khát được hủy diệt. Cùng với nhau, Iron Man và Hulk là lực lượng duy nhất cản trở sự mất điện của hành tinh Zzzax. Nhưng trước tiên, bộ đôi siêu anh hùng sẽ phải vượt qua Wendigos gầm gừ, những người máy chết chóc và cường quốc có vảy, Abomination. Liệu hai trong số những anh hùng hùng mạnh nhất của Marvel có thể tìm cách hợp tác với nhau mà không đụng độ nhau trước khi hết giờ?</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adrian Pasdar","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"David Kaye","avatar":""},{"name":"Liam O''Brien","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324462);
