INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('percy-jackson-bien-quai-vat', 'Percy Jackson: Biển Quái Vật', 'Percy Jackson: Sea of Monsters', 'https://phimimg.com/upload/vod/20231113-1/9640d959dd3646981147fbee57abebf6.jpg', 'https://phimimg.com/upload/vod/20231113-1/fecb6b70a3bf97783506cd460d6df8c3.jpg', '<p>Dựa trên cuốn sách thứ hai trong loạt Riordan, Sea of Monsters là một câu chuyện trong đó Percy phải giải cứu &quot;Trại Á thần,&quot; nơi trú ẩn an toàn duy nhất của những trẻ em á thần, chúng sẽ được bảo vệ khỏi sự nguy hiểm cập kè của Kronos - một lực lượng tà ác do bị đầu độc của những vị thần chính là những đứa con trai của mình, Kronos đã sống dậy và quyết định trút mọi tức giận lên đỉnh Olympus. Để cứu đồng loại Percy và bạn anh ấy phải dấn thân vào &quot;Biển quái vật&quot; để tìm &quot;Bộ lông cừu vàng&quot; ở vùng &quot; Tam giác quỷ &quot; vì đây là thứ duy nhất có thể bảo vệ trại biên giới của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Leven Rambin","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"Katelyn Mager","avatar":""},{"name":"Grey Damon","avatar":""},{"name":"Paloma Kwiatkowski","avatar":""},{"name":"Anthony Stewart Head","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Robert Maillet","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Connor Dunn","avatar":""},{"name":"Alisha Newton","avatar":""},{"name":"Bjor","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324462);
