INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-san-chim-quy', 'Cuộc Săn Chim Quý', 'A Birder''s Guide to Everything', 'https://phimimg.com/upload/vod/20231114-1/844aa76f3663c6f7b0f3d05c62730004.jpg', 'https://phimimg.com/upload/vod/20231114-1/7293d9f263e2f79aac7def9f195d7fc3.jpg', '<p>Cậu bé David Portnoy, 15 tuổi, yêu thích chim, nghĩ rằng mình đã có một cuộc khám phá để đời. Vì vậy, vào đêm trước buổi tái hôn của cha mình, cậu đã trốn cùng với những người bạn tốt nhất của mình để tiến hành một cuộc du lịch kì thú để củng cố vị trí của họ trong sự nghiệp nghiên cứu chim.</p>', 'Full', 1, 'single', 'completed', 10, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kodi Smit-McPhee","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Katie Chang","avatar":""},{"name":"Briana Marin","avatar":""},{"name":"Lucas Near-Verbrugghe","avatar":""},{"name":"Ethan Cohn","avatar":""},{"name":"Stephen Kunken","avatar":""},{"name":"Daniela Lavender","avatar":""},{"name":"Andy Prosky","avatar":""},{"name":"Adam Barrie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
