INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-noi-doi-cua-armstrong', 'Lời nói dối của Armstrong', 'The Armstrong Lie', 'https://phimimg.com/upload/vod/20231115-1/c633eca8b9880ae40bdad8c1d41b524a.jpg', 'https://phimimg.com/upload/vod/20231115-1/b63dc12c2091dd060e41d5660c94a07d.jpg', '<p>Bộ phim tài liệu này xoay quanh cua rơ Lance Armstrong, từ nỗ lực trở lại vào năm 2009 cho đến lời thú nhận động trời vào năm 2012 về việc sử dụng chất kích thích.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Armstrong","avatar":""},{"name":"Betsy Andreu","avatar":""},{"name":"Frankie Andreu","avatar":""},{"name":"Reed Albergotti","avatar":""},{"name":"Johan Bruyneel","avatar":""},{"name":"Daniel Coyle","avatar":""},{"name":"Michele Ferrari","avatar":""},{"name":"Michael Bloomberg","avatar":""},{"name":"Anderson Cooper","avatar":""},{"name":"Bill Clinton","avatar":""},{"name":"Oprah Winfrey","avatar":""},{"name":"Alex Gibney","avatar":""},{"name":"Larry King","avatar":""},{"name":"Barbara Walters","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324462);
