INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-noi-doi-cua-armstrong', 'Lời nói dối của Armstrong', 'The Armstrong Lie', 'lời nói dối của armstrong the armstrong lie lance armstrong betsy andreu frankie andreu reed albergotti johan bruyneel daniel coyle michele ferrari michael bloomberg anderson cooper bill clinton oprah winfrey alex gibney larry king barbara walters ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tay-ngoai-cam', 'Bàn Tay Ngoại Cảm', 'The Gifted Hands', 'https://phimimg.com/upload/vod/20231115-1/a9fbf361407e4bf9c885f29c399a9cae.jpg', 'https://phimimg.com/upload/vod/20231115-1/bacbb4f2a74845e241f53361f78f813e.jpg', '<p>The Gifted Hand đưa khán giả tới một câu chuyện đặc biệt kỳ lạ, có khả năng gây tò mò mạnh mẽ. Chuyện phim kể về vụ việc một bé gái bị bắt cóc rồi bị giết hại trong địa bàn quản lý của điều tra viên Yang Chun-dong. Tại hiện trường vụ án, Yang đột nhiên nhớ lại rằng mình đã nhìn thấy quang cảnh này trước đó vài ngày, được miêu tả dưới dạng những bức vẽ graffiti. Hành trình tìm kiếm người họa sĩ đóng vai trò then chốt trong vụ án dẫn anh đến với Jun. Anh nhận ra rằng Jun sở hữu khả năng ngoại cảm đặc biệt, cho phép cậu nhìn thấy ký ức ẩn sâu bên trong một đồ vật hay một con người chỉ bằng cách chạm tay vào. Khả năng này khiến cậu bị xa lánh, phải chọn sống cuộc sống ẩn dật, dùng graffiti để miêu tả những gì mình thấy. Yang quyết định sẽ nhờ tới năng lực của Jun để truy tìm hung thủ...</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Kang-woo","avatar":""},{"name":"Kim Bum","avatar":""},{"name":"Esom","avatar":""},{"name":"Kim Yoo-bin","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Seo Hyun-chul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324462);
