INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dabbe-nhap-hon', 'Dabbe: Nhập hồn', 'Dabbe: The Possession', 'https://phimimg.com/upload/vod/20231125-1/db17c0a028e66815e260ad1ccf4256b7.jpg', 'https://phimimg.com/upload/vod/20231125-1/f73eba479d77c814fb151cc0c8f4e3e3.jpg', '<p>Ngay trước đám cưới, Kübra bị quỷ ám. Khi cuộc kiểm tra hé lộ những phát hiện ghê rợn hơn, bạn của cô – một nhà tâm thần học – tìm cách làm lễ trừ tà.</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Irmak Örnek","avatar":""},{"name":"A. Murat Özgen","avatar":""},{"name":"Cansu Kurgun","avatar":""},{"name":"Elçin Atamgüç","avatar":""},{"name":"Sabriye Günüç","avatar":""},{"name":"Sultan Köroğlu Kiliç","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
