INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-toa-tram-huong', 'Cung Tỏa Trầm Hương', 'The Palace', 'https://phimimg.com/upload/vod/20231112-1/59c8613b19bd8b6c0c39cb1ed7f93575.jpg', 'https://phimimg.com/upload/vod/20231112-1/8704810aef5e4ec77bed2a988da1e217.jpg', '<p>Được làm lại từ phim truyền hình ăn khách một thời Cung tỏa tâm ngọc, Cung tỏa Trầm Hương xoay quanh mạch truyện chính là sự kiện chín vị a ca giành vợ nổi tiếng thời vua Khang Hy, từ đó tái hiện cuộc chiến tranh quyền đoạt vị khốc liệt trong thế giới hoàng cung. Hai nhân vật chính của phim là Trầm Hương và Lưu Ly do Châu Đông Vũ và Triệu Lệ Dĩnh đảm nhận. Họ từ hai người bạn tri kỷ đồng cam cộng khổ bỗng chốc trở mặt thành thù chỉ vì quyền lợi cá nhân. Với nhiều tình tiết hấp dẫn như vậy, Cung tỏa Trầm Hương được kỳ vọng sẽ mang đến cho khán giả một bữa tiệc phim cổ trang thú vị và hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Dongyu","avatar":""},{"name":"Chen Xiao","avatar":""},{"name":"Zhao Liying","avatar":""},{"name":"Lu Yi","avatar":""},{"name":"Zhu Zixiao","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Cheng Haofeng","avatar":""},{"name":"Du Yuchen","avatar":""},{"name":"Dicky Cheung Wai-Kin","avatar":""},{"name":"Kingdom Yuen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
