INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kinh-cuu-uoc', 'Thánh Kinh Cựu Ước', 'The Book of Daniel', 'https://phimimg.com/upload/vod/20231111-1/f4352a82dfc2674b39bfd5744227ebf4.jpg', 'https://phimimg.com/upload/vod/20231111-1/75af3e6a1034d92a517b0b746dfe641c.jpg', '<p>Câu chuyện về Daniel và 3 người bạn, những người vẫn một mực kính phục và vâng giữ điều răn luật lệ Thượng Đế mình, Ngài nâng đỡ, giữ gìn họ, dù họ có bước vào lò lửa hừng hay trong hang sư tử cũng không tổn hại gì - Vì Ngài ở bên họ.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Miano","avatar":""},{"name":"Andrew Bongiorno","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Kevin McCorkle","avatar":""},{"name":"Rolf Saxon","avatar":""},{"name":"Peter Kluge","avatar":""},{"name":"Liam Matthews","avatar":""},{"name":"Ben Maccabee","avatar":""},{"name":"Alice Amter","avatar":""},{"name":"Philip Anthony-Rodriguez","avatar":""},{"name":"Kevin Blake","avatar":""},{"name":"Drew Cardillo","avatar":""},{"name":"Francesco Curá","avatar":""},{"name":"Alton Denmore","avatar":""},{"name":"Anthony L. Fernandez","avatar":""},{"name":"Gallagher","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
