INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-ngot-tinh-yeu-2', 'Vị Ngọt Tình Yêu 2', 'Aashiqui 2', 'https://phimimg.com/upload/vod/20231111-1/ba03f071c262726d21f482dfcfcb8a0f.jpg', 'https://phimimg.com/upload/vod/20231111-1/4eee36445829ee192c7563e52fc72ade.jpg', '<p>Một phụ nữ trẻ gặp một nhạc sĩ thất bại, người bắt đầu sự nghiệp ca hát của mình, nhưng mối quan hệ của họ đã sụp đổ khi mọi người cho rằng anh ta đến với cô vì danh tiếng và tài sản.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aditya Roy Kapur","avatar":""},{"name":"Shraddha Kapoor","avatar":""},{"name":"Shaad Randhawa","avatar":""},{"name":"Mahesh Thakur","avatar":""},{"name":"Salil Acharya","avatar":""},{"name":"Mahesh Bhatt","avatar":""},{"name":"Soumyajit Majumdar","avatar":""},{"name":"Milind Pathak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
