INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-ghen', 'Cuồng Ghen', 'Scorned', 'https://phimimg.com/upload/vod/20231111-1/97161bcd513422cc6b1468ee767c2837.jpg', 'https://phimimg.com/upload/vod/20231111-1/492ad4664b531a460e496b89e1552cbe.jpg', '<p>Sadie và Kevin đã quyết định dành một ngày cuối tuần lãng mạn cùng nhau tại ngôi nhà bên hồ của anh ấy. Nhưng khi một tin nhắn bất ngờ - và đáng tiếc - từ người bạn thân nhất của cô, Jennifer, gửi cho Kevin, tiết lộ mối tình vụng trộm giữa hai người, Sadie lao vào khao khát trả thù.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"AnnaLynne McCord","avatar":""},{"name":"Viva Bianca","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Doug Drucker","avatar":""},{"name":"Juan Pablo Veizaga","avatar":""},{"name":"Scott Knisley","avatar":""},{"name":"Sadie Katz","avatar":""},{"name":"Joe Kurak","avatar":""},{"name":"Denise Glass","avatar":""},{"name":"Rich Grosso","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324462);
