INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-hen-dau-tien', 'Lần Hẹn Đầu Tiên', 'First Period', 'https://phimimg.com/upload/vod/20231113-1/e56e7cccf8992f85ad0cb554730d6349.jpg', 'https://phimimg.com/upload/vod/20231113-1/10c6044b7281ecff13707e97454fb9e1.jpg', '<p>Cô gái mới lớn Cassie và Maggie bị ruồng bỏ là những cô gái khó xử nhất ở trường trung học. Cùng nhau, họ quyết định cách để giành được trái tim của những chàng trai dễ thương và cô gái nổi tiếng là về nhất trong cuộc thi tài năng của trường. Nhưng các đối thủ Heather, Other Heather, và những người bạn trai nổi tiếng của họ là Brett và Dirk sẽ không dừng lại ở đó để giữ những người hùng của chúng ta trở thành trò cười của trường. Nó sẽ cần sự lột xác, can đảm và thậm chí có thể đọc rap một chút để đánh bại họ theo đúng phong cách của thập niên 80.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brandon Alexander III","avatar":""},{"name":"Dudley Beene","avatar":""},{"name":"Lauren Rose Lewis","avatar":""},{"name":"Michael Turchin","avatar":""},{"name":"Leigh Wakeford","avatar":""},{"name":"Karli Kaiser","avatar":""},{"name":"Adrian Burks","avatar":""},{"name":"Cassandra Peterson","avatar":""},{"name":"Jack Plotnick","avatar":""},{"name":"Diane Salinger","avatar":""},{"name":"Judy Tenuta","avatar":""},{"name":"Tara Karsian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
