INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-3096-ngay', 'Ác Mộng 3096 Ngày', '3096 Days', 'https://phimimg.com/upload/vod/20231113-1/5f2deb094b24127921404ba0c43235a3.jpg', 'https://phimimg.com/upload/vod/20231113-1/5f7cdd5964075fe15762f34fa2bdaf36.jpg', '<p>Dựa trên các sự kiện thực tế. Cô gái Áo 10 tuổi, Natascha Kampusch bị bắt cóc vào ngày 03 tháng 3 năm 1998, trên đường đến trường. Cô đã dành 8 năm rưỡi dưới sự giam cầm nghiêm ngặt của kẻ bắt cóc, và đã tìm cách sống sót sau một trong những trải nghiệm độc ác nhất mà một đứa trẻ không bao giờ nên có</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Antonia Campbell-Hughes","avatar":""},{"name":"Thure Lindhardt","avatar":""},{"name":"Trine Dyrholm","avatar":""},{"name":"Amelia Pidgeon","avatar":""},{"name":"Dearbhla Molloy","avatar":""},{"name":"Roeland Wiesnekker","avatar":""},{"name":"Ellen Schwiers","avatar":""},{"name":"Erni Mangold","avatar":""},{"name":"Sebastian Weber","avatar":""},{"name":"Angelina Noa","avatar":""},{"name":"Michael Grimm","avatar":""},{"name":"Heike Koslowski","avatar":""},{"name":"Ulla Geiger","avatar":""},{"name":"Arthur Streiling","avatar":""},{"name":"Thomas Loibl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
