INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-theo-dau-vet', 'Lần Theo Dấu Vết', 'Prisoners', 'https://phimimg.com/upload/vod/20231113-1/fe32efdecd9d929e89930b01898c0847.jpg', 'https://phimimg.com/upload/vod/20231113-1/daf88c3716da4d5db54c528cf3602055.jpg', '<p>Trong Prisoners, Hugh Jackman vào vai Keller Dover, một người cha có con gái mất tích bí ẩn. Anh quyết định tự mình điều tra khi phía cảnh sát không tìm ra manh mối. Nhưng liệu người cha tuyệt vọng này có thể làm được gì để bảo vệ gia đình của mình?</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Dylan Minnette","avatar":""},{"name":"Zoë Soul","avatar":""},{"name":"Wayne Duvall","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Len Cariou","avatar":""},{"name":"Sandra Ellis Lafferty","avatar":""},{"name":"Erin Gerasimovich","avatar":""},{"name":"Kyla-Drew","avatar":""},{"name":"Brad James","avatar":""},{"name":"Anthony Reynolds","avatar":""},{"name":"Ro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324462);
