INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-phai-thanh-nhan', 'Há Phải Thánh Nhân', 'Ain''t Them Bodies Saints', 'https://phimimg.com/upload/vod/20231111-1/cad5b88f7cb08e0bd88470d2714fb394.jpg', 'https://phimimg.com/upload/vod/20231111-1/919dd078af3e72efc70421b3df5791f0.jpg', '<p>Bộ phim là cậu chuyện về cô gái Ruth do Rooney Mara thủ vai, sau khi cùng bạn trai đấu súng với cảnh sát và đã vô tình giết hại một cảnh sát. &nbsp;Bạn trai cô đã nhận tội thay cô và phải vào tù, với niềm khao khát tự do và mong muốn gặp lại vợ con của mình, anh đã trốn thoát khỏi nhà tù và trốn chạy trong sự truy đuổi của cảnh sát ...</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rooney Mara","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Keith Carradine","avatar":""},{"name":"Kennadie Smith","avatar":""},{"name":"Jacklynn Smith","avatar":""},{"name":"Nate Parker","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Charles Baker","avatar":""},{"name":"Augustine Frizzell","avatar":""},{"name":"Kentucker Audley","avatar":""},{"name":"David Zellner","avatar":""},{"name":"Turner Ross","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Will Beinbrink","avatar":""},{"name":"Frank Mosley","avatar":""},{"name":"Steve Corne","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
