INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-thu-hai', 'Người Mẹ Thứ Hai', 'Ilo Ilo', 'https://phimimg.com/upload/vod/20231111-1/05dbf3d257756c5628ff84eb8f37fc0b.jpg', 'https://phimimg.com/upload/vod/20231111-1/5414e66a8fc5e1e9a81f69539bae7c19.jpg', '<p>Tại Singapore, gia đình Lim chào đón người giúp việc mới đến của họ, Teresa. Giống như nhiều phụ nữ Philippines khác, cô đến thành phố này để tìm kiếm một cuộc sống tốt đẹp hơn. Sự hiện diện của cô ấy trong gia đình làm xấu đi mối quan hệ vốn đã căng thẳng của họ. Nhưng Jiale, cậu con trai nhỏ, sớm bắt đầu hình thành một mối quan hệ đặc biệt với Teresa, và cô ấy sớm trở thành một phần không thể nói ra của gia đình.</p>', 'Full', 1, 'single', 'completed', 24, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yann Yann Yeo","avatar":""},{"name":"Chen Tian Wen","avatar":""},{"name":"Angeli Bayani","avatar":""},{"name":"Koh Jia Ler","avatar":""},{"name":"Jo Kukathas","avatar":""},{"name":"Peter Wee","avatar":""},{"name":"Naomi Toh","avatar":""},{"name":"Stephanie Kiong","avatar":""},{"name":"Jia Min Chantel Teo","avatar":""},{"name":"Zhi Fang Xu","avatar":""},{"name":"Sea Moi Lee","avatar":""},{"name":"James Ng","avatar":""},{"name":"Sook Fen Wong","avatar":""},{"name":"Siow Phing Tan","avatar":""},{"name":"Aizuddiin Nasser","avatar":""},{"name":"Kamal Bin Abdul Rahim","avatar":""},{"name":"Delwin Neo","avatar":""},{"name":"Bai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
