INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-croods', 'Gia Đình Croods', 'The Croods', 'https://phimimg.com/upload/vod/20231111-1/0c26efb74d11c8aeeab3073dbe89be70.jpg', 'https://phimimg.com/upload/vod/20231111-1/89354f80668531b2a3d6e5e6bda33ef5.jpg', '<p>Khi trận động đất xóa sổ hang động mình nương náu, gia đình gà mờ thời tiền sử buộc phải bôn ba qua những vùng đất lạ lẫm, mong muốn kiếm tìm mái nhà mới.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Chris Sanders","avatar":""},{"name":"Randy Thom","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
