INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuon-quyt', 'Khu Vườn Quýt', 'Tangerines', 'https://phimimg.com/upload/vod/20231111-1/cb5c3c7cfdc519ddb0f87486a869518f.jpg', 'https://phimimg.com/upload/vod/20231111-1/4e712dc0acd741e819da279c7713ba01.jpg', '<p>Bối cảnh của phim đặt trong cuộc chiến tranh ở Georgia, vùng Apkhazeti vào năm 1990. Tại một ngôi làng của người Estonia, tất cả mọi người đều đã bỏ về nước hết, chỉ còn lại Ivo và Margus, hai ông lão ở lại để thu hoạch vườn quýt của mình. Họ không đứng về phía nào trong cuộc chiến, vì vậy tuy ở trong vùng chiến tranh nhưng cuộc sống thường ngày của hai ông lão khá bình yên (tuy thỉnh thoảng cũng có lính lác đến xinh đểu thức ăn). Thế rồi một ngày nọ, một cuộc đấu súng giữa hai phe diễn ra ngay trước nhà Ivo, và họ buộc phải đưa những người lính thuộc hai phe đối lập vào nhà.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lembit Ulfsak","avatar":""},{"name":"Giorgi Nakashidze","avatar":""},{"name":"Elmo Nüganen","avatar":""},{"name":"Misha Meskhi","avatar":""},{"name":"Raivo Trass","avatar":""},{"name":"Zura Begalishvili","avatar":""},{"name":"Jano Izoria","avatar":""},{"name":"Gia Gogishvili","avatar":""},{"name":"Vamekh Jangidze","avatar":""},{"name":"Aleko Begalishvili","avatar":""},{"name":"Temo Khutsishvili","avatar":""},{"name":"Giorgi Tsaava","avatar":""},{"name":"Denis Khlibov","avatar":""},{"name":"Viktor Gegeshidze","avatar":""},{"name":"Genadi Levchenko","avatar":""},{"name":"Kakha Are","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324462);
