INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vendetta', 'Vendetta', 'Vendetta', 'https://phimimg.com/upload/vod/20231111-1/229415d79307c510a4a50c98a0d5258e.jpg', 'https://phimimg.com/upload/vod/20231111-1/593481d969e7c842da408805889c1982.jpg', '<p>Sĩ quan thẩm vấn hoạt động đặc biệt Jimmy Vickers truy tìm một băng đảng đã tàn sát cha mẹ anh, đồng thời tránh bị đơn vị cũ và cảnh sát truy lùng. Với việc cảnh sát đang áp sát và đơn vị cũ của anh đang lần theo dấu vết, anh phải trốn tránh bị bắt đủ lâu để hoàn thành cuộc thập tự chinh khủng khiếp của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Danny Dyer","avatar":""},{"name":"Roxanne McKee","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Josef Altin","avatar":""},{"name":"Bruce Payne","avatar":""},{"name":"Simona Brhlikova","avatar":""},{"name":"Emma Samms","avatar":""},{"name":"Nick Nevern","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Ricci Harnett","avatar":""},{"name":"Lucy Drive","avatar":""},{"name":"Joshua Osei","avatar":""},{"name":"Tracy Kirby","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
