INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-banh-ban', 'Vua Banh Bàn', 'Foosball', 'https://phimimg.com/upload/vod/20231109-1/c9a4419bb436f4021493e5db11a3dde3.jpg', 'https://phimimg.com/upload/vod/20231109-1/0e7ed9ba28551608a88b154077c65621.jpg', '<p>Vua Banh Bàn - Foosball là câu chuyện của Amadeo, một anh chàng nhút nhát nhưng rất tài năng. Cuộc sống của Amadeo trở nên rắc rối khi Grosso - một thanh niên cùng làng - đạt danh hiệu cầu thủ bóng đá xuất sắc nhất thế giới - trở về để trả thù cho trận thua bi lắc duy nhất trước Amadeo từ thời thơ ấu. Trong hoàn cảnh khó khăn đó, một điều kỳ diệu đã xảy ra: các “cầu thủ” trong bàn bi lắc bóng đá hỏng bỗng dưng sống lại! Họ có linh hồn, có thể di chuyển và có thể chơi đá bóng. Họ quyết tâm giúp đỡ Amadeo tìm lại thế giới đã đánh mất. Cùng với sự hỗ trợ của đội quân đó, Amadeo sẽ bước vào một cuộc phiêu lưu mới để giải cứu cô bạn gái tên Laura mà cậu thầm thương trộm nhớ.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2013, 'Vietsub', 'HD', 'Argentina', 0, '[{"name":"David Masajnik","avatar":""},{"name":"Juan José Campanella","avatar":""},{"name":"Diego Ramos","avatar":""},{"name":"Pablo Rago","avatar":""},{"name":"Gabriel Almirón","avatar":""},{"name":"Axel Kuschevatzky","avatar":""},{"name":"Mariana Otero","avatar":""},{"name":"Diego Mesaglío","avatar":""},{"name":"Lucía Maciel","avatar":""},{"name":"Marcos Mundstock","avatar":""},{"name":"Ernesto Claudio","avatar":""},{"name":"Miguel Ángel Rodríguez","avatar":""},{"name":"Fernando Gustavo Sily","avatar":""},{"name":"Fabián Gianola","avatar":""},{"name":"Sebastián Mog","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":