INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-tuong-gia', 'Giải Cứu Tướng Gia', 'Saving General Yang', 'https://phimimg.com/upload/vod/20231110-1/b0a742a4a6ae8a7c9dc3c9548b19d1d8.jpg', 'https://phimimg.com/upload/vod/20231110-1/d9a88bfb0faeddfb1308d7267e83d987.jpg', '<p>Giải Cứu Tướng Gia - Saving General Yang kể về Trung Hoa dưới thời nhà Tống đứng trước họa xâm lăng của đội quân Khiết Đan. Gian thần Phan Nhân Mỹ kích động Hoàng Đế, đưa đệ nhất danh tộc họ Dương ra chiến trường để trả thù riêng. Dưới sự dẫn dắt của Dương Nghiệp, đại tướng quân của Dương gia và phu nhân của ông Xa Thái Quân, 7 người con trai Dương gia lần lượt ra trận chống lại quân xâm lược của Thái tử Khiết Đan - Gia Luật Nguyên.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Adam Cheng","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Wu Zun","avatar":""},{"name":"Vic Chou","avatar":""},{"name":"Xu Fan","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Raymond Lam","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Fu Xinbo","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Ady An","avatar":""},{"name":"Vivi Lee","avatar":""},{"name":"Chen Zhihui","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Liu Jun","avatar":""},{"name":"王希之","avatar":""},{"name":"Zhang Xiao-Yan","avatar":""},{"name":"Cici Chen","avatar":""},{"name":"Wang Chunyuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324462);
