INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('christmas-rose', 'Christmas Rose', 'Christmas Rose', 'https://phimimg.com/upload/vod/20231110-1/bb7f90593ab39b76c7abc8f956e4139c.jpg', 'https://phimimg.com/upload/vod/20231110-1/9e9f0bdd9c635c459a4407e634e02c87.jpg', '<p>Bị liệt từ nhỏ, Jing là một giáo viên dạy piano tốt bụng và có một cuộc sống bình lặng. Một ngày nọ, cô cáo buộc bác sĩ Chu đã quấy rối cô trong một cuộc khám bệnh điển hình. Chu nhanh chóng bị bắt, buộc tội và đưa ra xét xử. Công tố viên của vụ án là Tim, một luật sư lý tưởng, người đã gia nhập thế giới luật pháp để trừng phạt kẻ có tội. Tuy nhiên, khi điều tra viên Nam của Tim giúp anh bóc tách các mảnh vỡ thì vụ án càng trở nên phức tạp. Chẳng bao lâu, Tim bắt đầu đặt câu hỏi về sự thật xung quanh câu chuyện của Jing.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Xia Yu","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Qin Hailu","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Kam Kwok-Leung","avatar":""},{"name":"Pat Ha","avatar":""},{"name":"Theresa Lee Yee-Hung","avatar":""},{"name":"Joe Cheung Tung-cho","avatar":""},{"name":"Kwan Ling","avatar":""},{"name":"Wong Siu-Foon","avatar":""},{"name":"Kate Yeung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
