INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-lap-den-toi', 'Vòng Lặp Đen Tối', 'Dark Circles', 'https://phimimg.com/upload/vod/20231109-1/d5be83f7a50f358f4ced185a4129728e.jpg', 'https://phimimg.com/upload/vod/20231109-1/d37f7f0ba1d976462af34b6536898f19.jpg', '<p>Khi cha mẹ mới Alex và Penny rút lui khỏi thành phố và chuyển đến một nơi bên ngoài thị trấn, sự căng thẳng và tình trạng thiếu ngủ trầm trọng do đứa con sơ sinh của họ gây ra khiến cả hai đều nhìn thấy những thứ trong nhà có thể tồn tại hoặc không tồn tại. Việc liên tục nhìn thấy một người phụ nữ lạ khiến mỗi người trong số họ tự hỏi liệu họ có đang bị ảo giác hay không, hay ngôi nhà mới của họ có sự hiện diện đen tối, siêu nhiên. Khi khả năng nắm bắt mong manh về thực tế của họ ngày càng trở nên mê sảng, Alex và Penny thấy mình gần như bất lực trước sự thật khủng khiếp về những gì đang thực sự diễn ra trong ngôi nhà này.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnathon Schaech","avatar":""},{"name":"Pell James","avatar":""},{"name":"Andrea Frankle","avatar":""},{"name":"Philippe Brenninkmeyer","avatar":""},{"name":"Jenn Foreman","avatar":""},{"name":"Ever Eloise Landrum","avatar":""},{"name":"Glen Warner","avatar":""},{"name":"Suzanne Severio","avatar":""},{"name":"Brett Beoubay","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
