INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kiem-than-vuc-extra-edition', 'Đao Kiếm Thần Vực: Extra Edition', 'Sword Art Online: Extra Edition', 'https://phimimg.com/upload/vod/20231109-1/aabc8647436d411e267fe6bab53bd54f.jpg', 'https://phimimg.com/upload/vod/20231109-1/73d4eed1f17e91db443f9ed4e4aacb5c.jpg', '<p>Rihito Sajo, người đạt điểm tuyệt đối tất cả các môn trong kỳ thi tuyển sinh trung học, và Hikaru Kusakabe, người nổi tiếng trong giới nữ sinh, hoạt động trong một ban nhạc, bắt đầu&nbsp; chuyện với nhau sau khi luyện tập hợp xướng. Kusakabe tới những buổi luyện tập của Sajo, người chẳng có tí năng khiếu hát hò nào, cùng dành thời gian cho nhau, lắng nghe giọng nói của nhau, thì thầm những bài hát, dần dần hai người cứ thế yêu nhau say đắm.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Kanae Ito","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Ayahi Takagaki","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324462);
