INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-ruc-lua-cua-mister-va-pete', 'Mùa Hè Rực Lửa Của Mister Và Pete', 'The Inevitable Defeat of Mister & Pete', 'https://phimimg.com/upload/vod/20231109-1/0545b46c2922c298aabd11ac87fe2aa8.jpg', 'https://phimimg.com/upload/vod/20231109-1/e339451b135a4ecad990f06709731217.jpg', '<p>Câu chuyện về tuổi mới lớn về hai thanh niên nội thành, những người phải tự lo cho bản thân trong suốt mùa hè sau khi mẹ của họ bị chính quyền bắt đi.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Skylan Brooks","avatar":""},{"name":"Ethan Dizon","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"Jordin Sparks","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
