INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-ruc-lua-cua-mister-va-pete', 'Mùa Hè Rực Lửa Của Mister Và Pete', 'The Inevitable Defeat of Mister & Pete', 'mùa hè rực lửa của mister và pete the inevitable defeat of mister & pete skylan brooks ethan dizon jennifer hudson jordin sparks anthony mackie jeffrey wright adewale akinnuoye-agbaje ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-gian-toi-la-mafia', 'Đơn Giản Tôi Là Mafia', 'The Family', 'https://phimimg.com/upload/vod/20231109-1/3ef068f174995ca206f8abd4022c1cb1.jpg', 'https://phimimg.com/upload/vod/20231109-1/13b175c53945280a6613138267947230.jpg', '<p>Một ông chủ mafia và gia đình anh ta được chuyển đến một thị trấn buồn ngủ ở Pháp dưới chương trình bảo vệ nhân chứng sau khi snitching trên đám đông. Bất chấp những nỗ lực tốt nhất của FBI Agent Stansfield (Tommy Lee Jones) để giữ chúng xếp hàng, Fred Manzoni (Robert de Niro), vợ Maggie (Michelle Pfeiffer) và con cái của họ Belle (Dianna Agron) và Warren (John D&#39;Leo) Không thể giúp đỡ nhưng trở lại thói quen cũ và thổi bay bìa của họ bằng cách xử lý các vấn đề của họ theo cách của họ, cho phép những người thân Mafia cũ của họ theo dõi chúng. Chaos xảy ra khi điểm cũ được giải quyết trong các cài đặt không hợp nhất.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Dianna Agron","avatar":""},{"name":"John D''Leo","avatar":""},{"name":"Jon Freda","avatar":""},{"name":"David Belle","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Jimmy Palumbo","avatar":""},{"name":"Ted Arcidi","avatar":""},{"name":"Vincent Pastore","avatar":""},{"name":"Paul Borghese","avatar":""},{"name":"Stan Carp","avatar":""},{"name":"Anthony Desio","avatar":""},{"name":"Michael J. Panichelli Jr.","avatar":""},{"name":"Oisín Stack","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
