INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-nha-vung-que', 'Căn Nhà Vùng Quê', 'Cottage Country', 'https://phimimg.com/upload/vod/20231109-1/13431e3b7e842b31aae8d2c2b675f7b5.jpg', 'https://phimimg.com/upload/vod/20231109-1/5bb23f250d614f3170b2f7e6edd8863c.jpg', '<p>Khi Todd đưa bạn gái Cammie đến ngôi nhà nhỏ của gia đình để cầu hôn ẩn dật, điều cuối cùng mà anh ấy mong muốn làm là đối phó với người anh trai lười biếng và cô bạn gái hippie của anh ấy. Nhưng trong bộ phim hài đầy sai sót này, Todd và Cammie phải đối phó với người anh trai vô tình bị sát hại để có thể sống hạnh phúc mãi mãi.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Malin Åkerman","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Dan Petronijevic","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"Benjamin Ayres","avatar":""},{"name":"Kenneth Welsh","avatar":""},{"name":"Nancy Beatty","avatar":""},{"name":"Sabrina Grdevich","avatar":""},{"name":"Jim Annan","avatar":""},{"name":"Jonathan Crombie","avatar":""},{"name":"Earl Pastko","avatar":""},{"name":"Bill Turnbull","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
