INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ga-fruitvale', 'Nhà Ga Fruitvale', 'Fruitvale Station', 'https://phimimg.com/upload/vod/20231109-1/5632a9a24ad4a0208e4ffc3664eae428.jpg', 'https://phimimg.com/upload/vod/20231109-1/3f441375326afe9f66a56a64c9a16a71.jpg', '<p>Oakland, California. Chàng trai trẻ người Mỹ gốc Phi Oscar Grant gặp gỡ các thành viên trong gia đình, bạn bè, kẻ thù và người lạ trước khi đối mặt với số phận của mình trên sân ga ở ga Fruitvale, vào sáng sớm của Ngày đầu năm mới 2009.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael B. Jordan","avatar":""},{"name":"Melonie Diaz","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"Ariana Neal","avatar":""},{"name":"Keenan Coogler","avatar":""},{"name":"Trestin George","avatar":""},{"name":"Joey Oglesby","avatar":""},{"name":"Michael James","avatar":""},{"name":"Marjorie Crump-Shears","avatar":""},{"name":"Destiny Ekwueme","avatar":""},{"name":"Bianca Rodriguez III","avatar":""},{"name":"Julian Keyes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
