INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ke-ke-thu', 'Cận Kề Kẻ Thù', 'Enemies Closer', 'https://phimimg.com/upload/vod/20231108-1/e435b7ee6c559bc3792b2e1402e14f48.jpg', 'https://phimimg.com/upload/vod/20231108-1/aece8f40a220250f92d4050982e5a10a.jpg', '<p>Sau khi một lô hàng ma túy lớn bị mất tích ở biên giới Mỹ-Canada, kiểm lâm và cựu Hải quân SEAL Henry rơi vào trạng thái sinh tồn khi băng đảng ma túy buộc anh phải giúp lấy lại gói hàng bị rơi. Bị mắc kẹt trong vùng hoang dã không có liên lạc với thế giới bên ngoài, Henry thấy mình phải đối mặt với Clay, một người đàn ông có mối thù cá nhân chống lại Henry, người đã quay trở lại để trả thù. Giờ đây, hai kẻ thù không đội trời chung phải đưa ra lựa chọn: gác lại quá khứ và hợp tác cùng nhau, hoặc chết một mình dưới tay những kẻ buôn ma túy, một băng nhóm tàn nhẫn sẽ không dừng lại để lấy lại hàng hóa đã mất.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Tom Everett Scott","avatar":""},{"name":"Orlando Jones","avatar":""},{"name":"Linzey Cocker","avatar":""},{"name":"Kris Van Damme","avatar":""},{"name":"Zahari Baharov","avatar":""},{"name":"Dimo Alexiev","avatar":""},{"name":"Vlado Mihailov","avatar":""},{"name":"Teodor Tsolov","avatar":""},{"name":"Hristo Mitzkov","avatar":""},{"name":"Jonas Talkington","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
