INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-gangster', 'Băng Đảng Gangster', 'Gangster Squad', 'https://phimimg.com/upload/vod/20231108-1/1735864cc3462b755ca4ecfef0e000e5.jpg', 'https://phimimg.com/upload/vod/20231108-1/1492671c9b252cd58cabde6aed8c8b14.jpg', '<p>Với bối cảnh Los Angeles những năm 1949, đạo diễn Ruben Fleischer đã dựng lại một sự kiện có thật. Mickey Cohen là ông trùm của một đường dây chuyên kiếm tiền từ gái mại dâm và ma túy. Với thế lực rộng lớn lan tới tân tới Chicago, ông thâu tóm toàn bộ cảnh sát và những băng đảng trong địa bàn ông đi qua. Nhưng nơi đâu có cái ác, chính nghĩa sẽ đứng lên. Một biệt đội lấy tên là LAPD với sự dẫn đầu của Sgt. John O’Mara (Josh Brolin thủ vai) và Jerry Wooters (Ryan Goslingthủ vai) lãnh đạo đã âm thầm đi kiếm lại công lí cho chính nơi mình đang sống.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Brolin","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Troy Garity","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"James Carpinello","avatar":""},{"name":"James Landry Hébert","avatar":""},{"name":"Evan Jones","avatar":""},{"name":"Josh Pence","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc