INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giu-bang-chung', 'Người Giữ Bằng Chứng', 'The Keeper of Lost Causes', 'https://phimimg.com/upload/vod/20231108-1/64d10492744662aaf58ad8ade19e3770.jpg', 'https://phimimg.com/upload/vod/20231108-1/bfd0541a59bc0c52053b17d94473ee0a.jpg', '<p>Đan Mạch, 2013. Cảnh sát Carl Mørck và Hafez el-Assad, thành viên duy nhất của Cục Q, nơi tập trung vào việc giải quyết các vụ án chưa được xử lý, điều tra vụ mất tích của chính trị gia Merete Lynggaard, đã biến mất khi cô và anh trai đi du lịch trên một chiếc phà 5 năm trước .</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Nikolaj Lie Kaas","avatar":""},{"name":"Fares Fares","avatar":""},{"name":"Sonja Richter","avatar":""},{"name":"Mikkel Boe Følsgaard","avatar":""},{"name":"Søren Pilmark","avatar":""},{"name":"Peter Plaugborg","avatar":""},{"name":"Per Scheel Krüger","avatar":""},{"name":"Troels Lyby","avatar":""},{"name":"Øyvind Fabricius Holm","avatar":""},{"name":"Divya Das","avatar":""},{"name":"Rasmus Botoft","avatar":""},{"name":"Patricia Schumann","avatar":""},{"name":"Marie Mondrup","avatar":""},{"name":"Kenneth Carmohn","avatar":""},{"name":"Michael Brostrup","avatar":""},{"name":"Jeff","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324462);
