INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-ngoai-ba-dao', 'Ông Ngoại Bá Đạo', 'Jackass Presents: Bad Grandpa', 'https://phimimg.com/upload/vod/20231108-1/1d5229325f63d78524cbeb265cbd48f7.jpg', 'https://phimimg.com/upload/vod/20231108-1/c0268d90c575fdcfac4a8f9e1528a456.jpg', '<p>&quot;Bad Grandpa&quot; là phần thứ 4 trong loạt phim &quot;Jackass&quot; được khởi chiếu từ năm 2002. Bộ phim xoay quanh câu chuyện về ông già Irving Zisman. Ở tuổi 86, ông quyết định thực hiện một chuyến &quot;phượt&quot; xuyên nước Mỹ. Bạn đồng hành với ông chính là cậu cháu trai Billy chỉ mới 8 tuổi - người mà bất đặc dĩ ông phải cho đi cùng.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Knoxville","avatar":""},{"name":"Jackson Nicoll","avatar":""},{"name":"Georgina Cates","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Spike Jonze","avatar":""},{"name":"Kamber Hejlik","avatar":""},{"name":"Grasie Mercedes","avatar":""},{"name":"Jack Polick","avatar":""},{"name":"Gregorio","avatar":""},{"name":"Jill Killington","avatar":""},{"name":"Madison Davis","avatar":""},{"name":"George Faughnan","avatar":""},{"name":"Marilynn Allain","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
