INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-osin', 'Cô Bé Ôsin', 'Oshin', 'https://phimimg.com/upload/vod/20231108-1/6d67375dd0864897ef89835ecd72c63f.jpg', 'https://phimimg.com/upload/vod/20231108-1/a8e9fa343d8cba622446c627de11bee3.jpg', '<p>Oshin là bộ phim phiên bản điện ảnh do đạo diễn Togashi Shin sản xuất năm 2013, dựa trên bộ phim truyền hình nhiều tập cùng tên được yêu thích nhất trong lịch sử của đài NHK, vốn rất quen thuộc với khán giả Việt Nam vào thập niên 1990. Năm 1907, cô bé Oshin chỉ mới lên 7 nhưng đã bị bắt đi làm người ở do gia cảnh quá khốn cùng. Lúc đầu, cô bé chống cự vì không muốn xa gia đình, nhưng sau, vì mẹ, vì gia đình, bé Oshin lại quyết chí đi làm bằng tất cả nghị lực của mình.Ở nhà chủ là một nhà buôn gỗ, bé Oshin bị bắt làm việc cực nhọc từ sáng tới tối khuya, kể cả trong thời tiết băng tuyết giá lạnh. Chịu sự quản thúc khắc nghiệt, phải làm bao việc cực nhọc nhưng cô bé không khóc, không nản chí cũng không chùn bước và luôn ...</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kokone Hamada","avatar":""},{"name":"Aya Ueto","avatar":""},{"name":"Goro Inagaki","avatar":""},{"name":"Pinko Izumi","avatar":""},{"name":"Kayoko Kishimoto","avatar":""},{"name":"Manami Igashira","avatar":""},{"name":"Ayako Kobayashi","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Ryosuke Nogi","avatar":""},{"name":"Jitsuko Yoshimura","avatar":""},{"name":"Guts Ishimatsu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
