INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-vu-phai', 'Cuồng Vũ Phái', 'The Way We Dance', 'https://phimimg.com/upload/vod/20231108-1/d086e2e93f1dd66b11f2fefe1e59ffd5.jpg', 'https://phimimg.com/upload/vod/20231108-1/9c3f997174c8fa451eb2060bc6e66aef.jpg', '<p>Sau khi rời nhóm khiêu vũ của trường đại học, một sinh viên thuộc tầng lớp lao động tìm thấy nguồn cảm hứng từ thái cực quyền cho phong cách khiêu vũ đường phố độc đáo của riêng mình.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cherry Ngan","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Lokman Yeung","avatar":""},{"name":"Janice Fan","avatar":""},{"name":"Tommy \"Guns\" Ly","avatar":""},{"name":"Paul Wong","avatar":""},{"name":"Gloria Yip Wan-Yee","avatar":""},{"name":"Chan Wing-Chiu","avatar":""},{"name":"Bob Lam","avatar":""},{"name":"Lo Ka Fai","avatar":""},{"name":"Tom Poon Chun-Wai","avatar":""},{"name":"Law Siu Pong","avatar":""},{"name":"Julian Gaertner","avatar":""},{"name":"Lydia Lau","avatar":""},{"name":"Tasha Wong","avatar":""},{"name":"Koo Chi Kin","avatar":""},{"name":"Lam Yuet Wing","avatar":""},{"name":"Chu Ti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324462);
