INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-vu-phai', 'Cuồng Vũ Phái', 'The Way We Dance', 'cuồng vũ phái the way we dance cherry ngan babyjohn choi lokman yeung janice fan tommy "guns" ly paul wong gloria yip wan-yee chan wing-chiu bob lam lo ka fai tom poon chun-wai law siu pong julian gaertner lydia lau tasha wong koo chi kin lam yuet wing chu ti ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oculus', 'Oculus', 'Oculus', 'https://phimimg.com/upload/vod/20231108-1/e8fb5ef807bb84765e47d9e4acbb8a7f.jpg', 'https://phimimg.com/upload/vod/20231108-1/6246ae7896ff13ce0640fc3ceb78d59c.jpg', '<p>Mieke đang bị quấy rối bởi một hiện tượng không thể giải thích được. Cô ấy đang gặp ác mộng và những đứa con của cô ấy đang hành động kỳ lạ. Mẹ cô xuất hiện không rõ lý do, sau một thời gian dài không liên lạc. Cô cố gắng cảnh báo Mieke về ngày diệt vong sắp xảy ra. Nó có liên quan gì đến con búp bê mà một trong những đứa con trai của cô ấy tặng nhân dịp sinh nhật không? Mieke có một khám phá rất đen tối. Điều gì đó sẽ đảo lộn cuộc sống của cô ấy.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Mike Flanagan","avatar":""},{"name":"Karen Gillan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
