INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oculus', 'Oculus', 'Oculus', 'oculus oculus mike flanagan karen gillan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-cuong-dam-phan-1', 'Người Đàn Bà Cuồng Dâm: Phần 1', 'Nymphomaniac: Vol. I', 'https://phimimg.com/upload/vod/20231108-1/3ec4ecc287f858ab512ea8bc95964a19.jpg', 'https://phimimg.com/upload/vod/20231108-1/5ce06456b0951ccfb8d423d8b9a1750e.jpg', '<p>Bộ phim kể về hành trình dục vọng của cô gái từ khi còn trẻ đến lúc trở thành một người đàn bà cuồng dâm ở độ tuổi 50. Bộ phim bắt đầu từ cảnh một lần Joe bị tấn công trong một con hẻm nhỏ và được một người đàn ông xa lạ cứu giúp. Người này đưa Joe về nhà chăm sóc, và tại đây cô kể lại câu chuyện đời mình từ lúc sinh ra cho tới khi trở thành một người phụ nữ 50 tuổi với khát khao tình dục luôn cháy bỏng. Đó là cuộc đời chìm đắm trong sắc dục với hàng trăm người đàn ông và những mối tình khác nhau…</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Charlotte Gainsbourg","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Sophie Kennedy Clark","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Ananya Berg","avatar":""},{"name":"Jens Albinus","avatar":""},{"name":"Anders Hove","avatar":""},{"name":"Simon Böer","avatar":""},{"name":"Felicity Gilbert","avatar":""},{"name":"Clayton Nemrow","avatar":""},{"name":"James Northcote","avatar":""},{"name":"Saskia Reeves","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
