INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-quan-ly-dai-tai', 'Người quản lý đại tài', 'The Midas Touch', 'https://phimimg.com/upload/vod/20231103-1/2693f50c6d41fe878ee0b75681f1150d.jpg', 'https://phimimg.com/upload/vod/20231103-1/645669dbbb5935132e5dc12466c9c954.jpg', '<p>Một người thu nợ tiếp quản một nhóm diễn viên đang lên sau khi công ty đại diện của họ vỡ nợ, nhưng anh nhanh chóng nhận ra mình rơi vào rắc rối.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chapman To","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Jenny Lau Wai-Suen","avatar":""},{"name":"Gao Yun Xiang","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"He Jiong","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Vincy Chan","avatar":""},{"name":"Mani Fok Man-Hei","avatar":""},{"name":"Hins Cheung","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Deep Ng Ho-Hong","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Billy Luk","avatar":""},{"name":"Stephanie Che","avatar":""},{"name":"Steven Cheung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
