INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-quan-ly-dai-tai', 'Người quản lý đại tài', 'The Midas Touch', 'người quản lý đại tài the midas touch chapman to charlene choi wong cho-lam jenny lau wai-suen gao yun xiang gillian chung he jiong nicholas tse vincy chan mani fok man-hei hins cheung louis cheung deep ng ho-hong lo hoi-pang yumiko cheng billy luk stephanie che steven cheung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-nao-con-nay', 'Cha Nào Con Nấy', 'Like Father, Like Son', 'https://phimimg.com/upload/vod/20231107-1/7461fabc2236aa6556722200e072724f.jpg', 'https://phimimg.com/upload/vod/20231107-1/4a8df0ccb70d9109eccba2d098431184.jpg', '<p>Like Father, Like Son - Soshite chichi ni naru (Cha Nào Con Nấy) ra mắt năm 2013 và vẫn giữ được phong cách đặc trưng của Hirokazu Koreeda như các tác phẩm trước đó của ông: Nobody Knows, Still Walking hay I Wish... Sự xuất sắc của Like Father, Like Son bằng các chi tiết và cách dẫn truyện khéo léo đã giúp bộ phim thắng giải Giám khảo cao quý của Liên hoan phim Cannes năm 2013. Giới phê bình quốc tế đặc biệt dành những lời khen có cánh cho bản tình ca về tình phụ tử này. Dù đóng khung theo lối kể chuyện truyền thống và khuôn thước, đây vẫn là một phim ngọt ngào và quyến rũ bởi cái nhìn ấm áp và tinh nhạy đặc trưng, là một trong những tác phẩm đình đám tôn vinh giá trị gia đình của điện ảnh Nhật Bản. Phim có một cách tiếp cận hoàn toàn mới mẻ thông qua những bài học trên hành trình tìm lại chính mình của người cha sau một biến cố tưởng như dễ dàng vượt qua mà lại không phải vậy.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masaharu Fukuyama","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Yoko Maki","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Keita Ninomiya","avatar":""},{"name":"Shôgen Hwang","avatar":""},{"name":"Yuri Nakamura","avatar":""},{"name":"Kazuya Takahashi","avatar":""},{"name":"Yoh Yoshida","avatar":""},{"name":"Pierre Taki","avatar":""},{"name":"Ichirō Ogura","avatar":""},{"name":"Hiroshi Okochi","avatar":""},{"name":"Hana Kino","avatar":""},{"name":"Kazuaki Shimizu","avatar":""},{"name":"Tsuyoshi Hayashi","avatar":""},{"name":"Tomoya Nakamura","avatar":""},{"name":"Megumi Morisaki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
