INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-ma', 'Cá Mập Ma', 'Ghost Shark', 'https://phimimg.com/upload/vod/20231103-1/3d20e0349e86a65c280af8ead947619c.jpg', 'https://phimimg.com/upload/vod/20231103-1/1406561857ff00927e734f4b7178963b.jpg', '<p>Một thị trấn ven biển bị cản trở bởi một con cá mập ăn thịt người siêu nhiên. Một thợ săn ma hợp lực với một thuyền trưởng biển để khám phá bí mật về quá khứ đen tối của khu vực và tìm cách xua đuổi kẻ săn mồi bóng ma.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mackenzie Rosman","avatar":""},{"name":"Shawn C. Phillips","avatar":""},{"name":"Richard Moll","avatar":""},{"name":"Jayme Bohn","avatar":""},{"name":"Eliot Brasseaux","avatar":""},{"name":"Amy Brassette","avatar":""},{"name":"Sloane Coe","avatar":""},{"name":"Robert Aberdeen","avatar":""},{"name":"Chelsea Bruland","avatar":""},{"name":"Kim Collins","avatar":""},{"name":"Dave Davis","avatar":""},{"name":"Brooke Hurring","avatar":""},{"name":"Lucky Johnson","avatar":""},{"name":"Ben Lemoine","avatar":""},{"name":"Angela Meredith Furst","avatar":""},{"name":"Jaren Mitchell","avatar":""},{"name":"Thomas","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324462);
