INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-luc-vo-hinh', 'Thế Lực Vô Hình', 'Compound Fracture', 'https://phimimg.com/upload/vod/20231103-1/9c6914a088ea62ba04617961ba4be0ca.jpg', 'https://phimimg.com/upload/vod/20231103-1/25188e8937cf3cf7c7853bcb17c8b167.jpg', '<p>Michael Wolffsen (Tyler Mane) nhận được một cuộc điện thoại khẩn cấp và đưa cháu trai và vị hôn thê của mình lên đường về nhà với người thân duy nhất còn sống khác của anh: người cha ghẻ lạnh, lập dị (và cực kỳ hoang tưởng), Gary (Muse Watson), người bị ám ảnh bởi xây dựng một hợp chất không thể có được. Khi họ đến ngôi nhà khiêm tốn của Gary, được bao quanh bởi hàng mẫu Anh và hàng mẫu đất đầy camera và các cảm biến an ninh khác, Michael ngạc nhiên và lo lắng khi biết rằng cha mình đang ở giai đoạn đầu của chứng mất trí nhớ. Ngôi nhà bây giờ cũng được bao phủ bởi các biểu tượng siêu nhiên và huyền bí. Chào mừng đến với hợp chất, COMPOUND FRACTURE. Thành trì được thiết kế để cứu họ sẽ là ngôi mộ vĩnh cửu của họ?</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler Mane","avatar":""},{"name":"Muse Watson","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Leslie Easterbrook","avatar":""},{"name":"Renae Geerlings","avatar":""},{"name":"Alex Saxon","avatar":""},{"name":"Susan Angelo","avatar":""},{"name":"Jelly Howie","avatar":""},{"name":"Todd Farmer","avatar":""},{"name":"Daniel Roebuck","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324462);
