INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-luc-sieu-nhien', 'Năng Lực Siêu Nhiên', 'SPEC: Zero', 'https://phimimg.com/upload/vod/20231111-1/eb1454b3026abf9c5d9ee6fe9d5ee8f0.jpg', 'https://phimimg.com/upload/vod/20231111-1/2aae15fb36ddb2e2297493fc27c59abb.jpg', '<p>Học sinh trung học Saya Toma mất cha mẹ và em trai trong một tai nạn máy bay. Thám tử Akio Kondo đến và nói với cô rằng &quot;gia đình cô có khả năng cao đã bị giết bởi những kẻ có đặc điểm kỹ thuật.&quot; Đó là lần đầu tiên cô nghe đến &quot;spec&quot;. 6 năm sau, Saya Toma, người không bao giờ quên những gì Thám tử đã nói, quyết định trở thành thám tử. Cô trở về Nhật Bản sau khi được FBI đào tạo tại Hoa Kỳ. Saya Toma được phân công giải quyết những vụ án chưa được giải quyết tại Cục Công an. Trong khi đó, vì âm mưu của Satoshi Chii, Juichi Ninomae coi Saya Toma là cha mẹ của mình&amp;quot; kẻ thù và cố gắng đẩy cô ấy đến bờ vực. Âm mưu của Satoshi Chii cũng khiến Saya Toma và Juichi Ninomae quên mất họ là anh em. Hai anh em đang hướng tới một cuộc chiến sinh tử. Một cô gái tên Maho Ueno tham gia vào cuộc chiến của họ. Để bảo vệ Maho Ueno, Saya Toma sử dụng &quot;spec&quot;.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Erika Toda","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Saki Fukuda","avatar":""},{"name":"Yuu Tokui","avatar":""},{"name":"Ken Yasuda","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Yu Shirota","avatar":""},{"name":"Kohki Okada","avatar":""},{"name":"Kazuyuki Matsuzawa","avatar":""},{"name":"Ryuji Sainei","avatar":""},{"name":"Kasumi Arimura","avatar":""},{"name":"Takeshi Ito","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Kippei Shiina","avatar":""},{"name":"Raita Ryu","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Mitsuki Tanimura","avatar":""},{"name":"Denden","avatar":""},{"name":"Takay","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324462);
