INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-day-toi-day', 'Tôi Đây, Tôi Đây', 'It''s Me, It''s Me', 'https://phimimg.com/upload/vod/20231111-1/d20f1914bcc6b83e4d741784a85addda.jpg', 'https://phimimg.com/upload/vod/20231111-1/01fa8a6dddab066aa81e54adce6745c4.jpg', '<p>Hitoshi rơi vào một cuộc khủng hoảng danh tính kỳ quặc khi trò đùa đơn giản khiến nhiều phiên bản của anh bắt đầu xuất hiện khắp nơi!</p>', 'Full', 1, 'single', 'completed', 27, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuya Kamenashi","avatar":""},{"name":"Yuki Uchida","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Midoriko Kimura","avatar":""},{"name":"Ryo Iwamatsu","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Keiko Takahashi","avatar":""},{"name":"Eri Fuse","avatar":""},{"name":"Ryu Nakatani","avatar":""},{"name":"Yoshiyuki Morishita","avatar":""},{"name":"Aimi Satsukawa","avatar":""},{"name":"Maya Okano","avatar":""},{"name":"Marie Machida","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Suzuki Matsuo","avatar":""},{"name":"Ai Aita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324462);
