INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-day-toi-day', 'Tôi Đây, Tôi Đây', 'It''s Me, It''s Me', 'tôi đây, tôi đây it''s me, it''s me kazuya kamenashi yuki uchida ryo kase midoriko kimura ryo iwamatsu kiyohiko shibukawa keiko takahashi eri fuse ryu nakatani yoshiyuki morishita aimi satsukawa maya okano marie machida yutaka matsushige suzuki matsuo ai aita ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-song-thuong-luu', 'Đời Sống Thượng Lưu', 'The Great Beauty', 'https://phimimg.com/upload/vod/20231103-1/d562d4b8b5068303b045e2cf6c341a07.jpg', 'https://phimimg.com/upload/vod/20231103-1/db7c10571440b721ec3622d2f9a87c1a.jpg', '<p>Le Grande Bellezza (The Great Beauty) sản xuất vào năm 2013 dưới bàn tay tài ba của đạo diễn người Ý Paolo Sorrentino. Bộ phim vinh dự là phim khai mạc tại Liên hoan phim Cannes 2013 và đoạt giải Phim nói tiếng nước ngoài hay nhất tại Oscar lần thứ 86. Lấy bối cảnh ở Rome, phim xoay quanh Jep Gambardella – một nhà văn thuộc tầng lớp thượng lưu Ý. Sau 40 năm kể từ ngày xuất bản ấn phẩm nổi tiếng của mình: The Human Apparatus, Jep mất dần cảm hứng sáng tác và bắt đầu lang thang mỗi tối để tìm kiếm Le Grande Bellezza (Vẻ đẹp vĩ đại) của riêng ông. Câu chuyện về cuộc hành trình tìm kiếm vẻ đẹp vĩ đại của Jep Gambardella – về những con người đau đáu cả đời để đi tìm lại sự vĩ đại thực sự.</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Toni Servillo","avatar":""},{"name":"Carlo Verdone","avatar":""},{"name":"Sabrina Ferilli","avatar":""},{"name":"Carlo Buccirosso","avatar":""},{"name":"Iaia Forte","avatar":""},{"name":"Pamela Villoresi","avatar":""},{"name":"Galatea Ranzi","avatar":""},{"name":"Franco Graziosi","avatar":""},{"name":"Sonia Gessner","avatar":""},{"name":"Giorgio Pasotti","avatar":""},{"name":"Massimo Popolizio","avatar":""},{"name":"Luca Marinelli","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"Anita Kravos","avatar":""},{"name":"Roberta Cartocci","avatar":""},{"name":"Lorenzo Gio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
