INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-be-2-di-san-vi-dai', 'Bạn Bè 2: Di Sản Vĩ Đại', 'Friend : The Great Legacy', 'https://phimimg.com/upload/vod/20231103-1/be76f08ff977fa475d15bfa104515716.jpg', 'https://phimimg.com/upload/vod/20231103-1/ca244d4b636e2c3d9cc009fa5ee469c0.jpg', '<p>Người đứng đầu băng đảng là Lee Jeong-suk (Yoo Oh Sung thủ vai) sau mười bảy năm ngồi tù đã được thả ra ngoài, tuy nhiên vị thế của anh đã bị thay đổi. Yeog Eun Ki (Jung Ho-bin thủ vai), đàn em năm xưa chính là kẻ chủ mưu cướp đi tất cả quyền lợi cũng như người thân tín với Joeng-suk. Nhằm khôi phục vị thế, Lee Jeong-suk đã đi tìm lại những đàn em thân tín năm xưa, lên kế hoạch lật đổ Yeong Eun Ki. Ông cũng đề nghị hợp tác Choi Sung Hoon (Kim Woo Bin thủ vai), bạn tù nhiều năm trước cũng là người ông coi như con ruột. Cuộc chiến giành ngôi vị của Lee Jeong-suk và Yeong Eun Ki đã náo loạn cả một băng đảng, khiến ai nấy cũng khiếp sợ. Tình tiết Bạn Bè 2 càng được đẩy lên cao khi Choi Sung Hoon phát hiện ra bí ẩn đằng sau cái chết của bố mình, anh quyết định trừng phạt thủ phạm dù phải ngồi tù thêm lần nữa.</p>', 'Full', 1, 'single', 'completed', 21, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yu Oh-seong","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Kim Woo-bin","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Lee Cheol-min","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Hwang Sung-joon","avatar":""},{"name":"Kang Han-na","avatar":""},{"name":"Jo Min-jun","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Choi Jeong-hyun","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Song Ji-ho","avatar":""},{"name":"Park Sung-hyun","avatar":""},{"name":"Jeong Soo-kyo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324462);
