INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cui-bap-2', 'Anh Hùng Cùi Bắp 2', 'Kick-Ass 2', 'https://phimimg.com/upload/vod/20231102-1/7c2cf8d3c11b5a71e8a7f4103196884d.jpg', 'https://phimimg.com/upload/vod/20231102-1/b7668da6f17a5ae7ae456e13e3173b0a.jpg', '<p>Mindy Macready vẫn tiếp tục làm công việc trừ gian diệt bạo với danh tính Hit-girl cho dù không được sự đồng ý của người cha nuôi Marcus. Đồng thời cùng lúc đó anh chàng Dave Lizewski cảm thấy chán chường với cuộc sống vô vị hiện tại mà chỉ muốn được mạnh mẽ và tài giỏi như Mindy. &nbsp;Cùng lúc đó Chris D&quot;Amico sau khi thủ tiêu mẹ ruột đã mở một kế hoạch báo thù với tiềm lực tài chính hùng mạnh trong tay. Hắn dùng tiền để mua chuộc lũ tội phạm khắp nơi để xây dựng một tổ chức tội ác hòng đối đầu với Kick-ass, kẻ thù giết cha của Chris. &nbsp;Mọi chuyện trở nên rắc rối khi Mindy nghe lời cha nuôi, cố gắng tìm cách hòa nhập trở lại với cuộc sống của một nữ sinh trung học. Dave buộc phải đi tìm những đồng minh khác phục vụ cho công cuộc &quot;trừ gian diệt bạo&quot;...</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Lyndsy Fonseca","avatar":""},{"name":"Jim Carrey","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Lindy Booth","avatar":""},{"name":"Garrett M. Brown","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Donald Faison","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Augustus Prew","avatar":""},{"name":"Robert Emms","avatar":""},{"name":"Monica Dolan","avatar":""},{"name":"Steven Mackinto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324462);
