INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-tram-sao', 'Khách Sạn Trăm Sao', 'Hotel Deluxe', 'https://phimimg.com/upload/vod/20231102-1/8a67b5a7a6844f73d1d2b6726a159fe4.jpg', 'https://phimimg.com/upload/vod/20231102-1/e1a5a8b1b010925ae52c1cfca0532093.jpg', '<p>Hotel Deluxe về cơ bản là &quot;All&#39;s Well Ends Well 2013&quot;, với dàn diễn viên và đoàn làm phim gần như giữ nguyên, và một số gương mặt mới được thêm vào. Phim kể câu chuyện về một nhóm quản lý khách sạn cố gắng hết sức để đạt xếp hạng 5 sao cho khách sạn của họ , với một số nhân vật phụ và câu chuyện được thêm vào trong quá trình thực hiện.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ronald Cheng","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Fiona Sit","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Lynn Hung","avatar":""},{"name":"Karena Ng","avatar":""},{"name":"Susan Shaw Yam Yam","avatar":""},{"name":"Ha Chun-Chau","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Janelle Sing","avatar":""},{"name":"Wong Ji-Dan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324462);
