INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-nhai-xanh', 'Hoa Nhài Xanh', 'Blue Jasmine', 'https://phimimg.com/upload/vod/20231102-1/6c69ffba95e23f263c25cb4fdde83491.jpg', 'https://phimimg.com/upload/vod/20231102-1/25d023e602a0017cea4dc3013c341b33.jpg', '<p>Sau khi cuộc hôn nhân của cô với một doanh nhân giàu có đổ vỡ, Jasmine ở New York bỏ trốn đến San Francisco và căn hộ khiêm tốn của em gái cô, Ginger. Mặc dù cô ấy đang ở trong một trạng thái cảm xúc mong manh và thiếu kỹ năng làm việc, Jasmine vẫn cố gắng lên tiếng phản đối bạn trai của Ginger, Chili. Jasmine miễn cưỡng nhận một công việc trong văn phòng nha sĩ, trong khi Ginger bắt đầu hẹn hò với một người đàn ông, người hơn Chili một bước.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alec Baldwin","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Louis C.K.","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Andrew Dice Clay","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Alden Ehrenreich","avatar":""},{"name":"Joy Carlin","avatar":""},{"name":"Richard Conti","avatar":""},{"name":"Glen Caspillo","avatar":""},{"name":"Charlie Tahan","avatar":""},{"name":"Annie McNamara","avatar":""},{"name":"Daniel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
