INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-nga', 'Sa Ngã', 'Freier Fall', 'https://phimimg.com/upload/vod/20231102-1/27dd58cb889e2091f67a90322d220b76.jpg', 'https://phimimg.com/upload/vod/20231102-1/9d1adca0702bdce7ccab5161fd5de0c4.jpg', '<p>Một sự nghiệp đầy hứa hẹn với cảnh sát, một em bé sắp chào đời... Cuộc đời của Marc dường như đang đi đúng hướng. Sau đó, anh gặp đồng nghiệp là cảnh sát Kay và trong những buổi chạy bộ thường xuyên của họ, Marc trải nghiệm cảm giác thoải mái và dễ dàng chưa từng có trước đây -- và ý nghĩa của việc yêu một người đàn ông khác.</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Hanno Koffler","avatar":""},{"name":"Max Riemelt","avatar":""},{"name":"Katharina Schüttler","avatar":""},{"name":"Maren Kroymann","avatar":""},{"name":"Luis Lamprecht","avatar":""},{"name":"Attila Borlan","avatar":""},{"name":"Oliver Bröcker","avatar":""},{"name":"Horst Krebs","avatar":""},{"name":"Shenja Lacher","avatar":""},{"name":"Hassan Lazouane","avatar":""},{"name":"Stephanie Schönfeld","avatar":""},{"name":"Britta Hammelstein","avatar":""},{"name":"Barbara Bernt","avatar":""},{"name":"Samuel Schnepf","avatar":""},{"name":"Vilmar Bieri","avatar":""},{"name":"Jonathan Mül","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324462);
