INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-huyet-kieu-oa', 'Thiết Huyết Kiều Oa', 'Angel Warriors', 'https://phimimg.com/upload/vod/20231102-1/2d50b5144c5c9a5e17022a2caff4006f.jpg', 'https://phimimg.com/upload/vod/20231102-1/5f9734d1593dae86c3bf2a42f5795811.jpg', '<p>Phim kể về cuộc đời của cô bé mồ côi do Phan Sương Sương thủ vai, cha mất và cô bị bắt cóc lúc còn bé và được bọn bắt cóc đem cho một gia đình làm chài lưới nuôi dưỡng, Yoo Jin lúc còn bé rất dễ thương nhưng lại bị mẹ nuôi ghét bỏ và ghẻ lạnh, thế nhưng nụ cười tươi tắn lúc nào cũng hiễn rõ trên gương mặt cô bé đáng yêu này, vì lúc nào cô cũng được cha nuôi mình che chở và thương yêu...</p>', 'Full', 1, 'single', 'completed', 29, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Collin Chou","avatar":""},{"name":"Andy On","avatar":""},{"name":"Mavis Pan","avatar":""},{"name":"Fu Huayang","avatar":""},{"name":"Yu Nan","avatar":""},{"name":"Renata Tan","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Ryu Kohata","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"Wang Qiuzi","avatar":""},{"name":"Wu Jingyi","avatar":""},{"name":"Wang Danyi Li","avatar":""},{"name":"Shi Fanxi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
