INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan', 'Sát Nhân', 'Murder Eleven', 'https://phimimg.com/upload/vod/20231101-1/199390118dda675aeebe2b523d7d6554.jpg', 'https://phimimg.com/upload/vod/20231101-1/c7922c79c2bced65009fb29f31d78d6e.jpg', '<p>Mười gái mại dâm là nạn nhân của một tên giết người hàng loạt trên các đường phố của thành phố Atlantic. Nguyên nhân của vụ giết người hàng loạt vẫn là một ẩn số. . Hai thám tử Mayfield và Jessee nỗ lực để tìm ra kẻ giết người man rợ này. Thời gian ngày càng gấp rút. Hai thám tử chỉ còn ít thời gian để ngăn chặn nạn nhân thứ 11. Đêm nay rất dài bởi họ đang bị mất dấu nạn nhân thứ 11.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julienne Irons","avatar":""},{"name":"Jim Klock","avatar":""},{"name":"Michael Mack","avatar":""},{"name":"Richard Alan Reid","avatar":""},{"name":"Autumn Federici","avatar":""},{"name":"Chad Ridgely","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324462);
