INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hom-nay-nhat-dinh-thang', 'Hôm nay nhất định thắng', 'Go Eight', 'https://phimimg.com/upload/vod/20231109-1/6ea51ef2535dbbb2d7bc0cb237818e30.jpg', 'https://phimimg.com/upload/vod/20231109-1/fa58a02f0a372be6031e4fb328241f29.jpg', '<p>Khi một nhà báo tìm hiểu về câu chuyện thối nát trong một giải bóng đá, cuộc điều tra của cô dẫn đến một cầu thủ ngôi sao có khả năng dính líu đến vụ việc.</p>', 'Full', 1, 'single', 'completed', 23, 2013, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Zendhy Zaen","avatar":""},{"name":"Mathias Muchus","avatar":""},{"name":"Ray Sahetapy","avatar":""},{"name":"Tika Putri","avatar":""},{"name":"Ibnu Jamil","avatar":""},{"name":"Verdi Solaiman","avatar":""},{"name":"Pierre Gruno","avatar":""},{"name":"Ramon Y. Tungka","avatar":""},{"name":"Deddy Mahendra Desta","avatar":""},{"name":"Henky Solaiman","avatar":""},{"name":"Cok Simbara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324462);
