INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-sat-thu', 'Bảy Sát Thủ', '7 Assassins - Glory Days', 'https://phimimg.com/upload/vod/20231109-1/20afa16ec09fa8aaf4c18e55ba4e89ba.jpg', 'https://phimimg.com/upload/vod/20231109-1/6458dc868a4ead2a6d4b307b5c9b5356.jpg', '<p>Những năm cuối Thanh triều, nội bộ triều đình rối ren, bất ổn. Nội có nông dân khởi nghĩa, quân phiệt dòm ngó lăm lăm. Ngoại có Tây phương âm mưu xâm lược. Để dẹp loạn và chống giặc ngoại xâm, chính phủ nhà Thanh gom góp vạn lạng vàng từ khắp các nơi nhằm tăng quân ngạch, bổ sung quân nhu. Nhưng không ai ngờ rằng trên đường đi chiếc xe chở tiền vàng bị cướp, nhóm cướp tiến vào vùng đại mạc phía Tây. Triều đình lập tức phái binh mã điều tra, từ đó thế lực các phương bắt đầu đối đầu nhau gay gắt, chém giết lẫn nhau khắp các chiến trường...</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Felix Wong","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Power Chan Kwok-Pong","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Guo Tao","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Ni Hongjie","avatar":""},{"name":"Rose Chan Ka-Wun","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Song Xiaobao","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Dick","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075