INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-em-se-song-ra-sao', 'Giờ Em Sẽ Sống Ra Sao', 'How I Live Now', 'https://phimimg.com/upload/vod/20231101-1/ed04754f0c4b976e34be1a2b2b5b8261.jpg', 'https://phimimg.com/upload/vod/20231101-1/6e3d7810b3afb5c6104d12f465e75f8c.jpg', '<p>Phim How do I live now 2013 kể về Daisy (Saoirse Ronan) – một cô bé tuổi thiếu niên người Mỹ được gửi đến sống với họ hàng tại một vùng đồng quê thanh bình. Vốn lãnh đạm và lạc lõng, cô bé bắt đầu hòa nhập với những cảnh trí thiên nhiên và con người dễ thương xung quanh mình, đồng thời thắp lên một chuyện tình lãng mạn với anh chàng đẹp trai Edmund (George MacKay). Nhưng ở ven bìa rừng ngay trong những ngày hè chốn đồng quê thôn dã, tin tức về những xung đột quân sự ngày càng leo thang tại châu Âu. Và khi nước Anh rơi vào thời chiến với tình trạng bạo lực hỗn loạn, Daisy phải học cách trốn chạy và chiến đấu để sinh tồn.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"George MacKay","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Harley Bird","avatar":""},{"name":"Danny McEvoy","avatar":""},{"name":"Anna Chancellor","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Darren Morfitt","avatar":""},{"name":"Sabrina Dickens","avatar":""},{"name":"Stella Gonet","avatar":""},{"name":"Des McAleer","avatar":""},{"name":"Natasha Jones","avatar":""},{"name":"Sophie Stanton","avatar":""},{"name":"Nav Sidhu","avatar":""},{"name":"Amy Dawson","avatar":""},{"name":"Mark Stanley","avatar":""},{"name":"Paul Ronan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"