INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hanh-trinh-don-doc-tren-bien', 'Cuộc Hành Trình Đơn Độc Trên Biển', 'All Is Lost', 'https://phimimg.com/upload/vod/20231101-1/7014d7cf96b4d159cc11e84c0be13889.jpg', 'https://phimimg.com/upload/vod/20231101-1/f0fc18bdd882307a61173961d58365b0.jpg', '<p>Trong khi lênh đênh giữa vùng biển Ấn Độ Dương, tự mình thực hiện cuộc hành trình khám phá, con tàu của người đàn ông (Robert Redford) vô tình va chạm với một tàu chở container. Cú va chạm khiến thân tàu bị thủng, nước dần tràn vào khoang. Không những vậy, ông còn phải đối mặt với cơn bão lớn sắp ập đến. Khi đứng trước biển cả bao la, mất phương hướng, mất luôn con tàu, chứng kiến sự nổi giận của người mẹ thiên nhiên, ông làm cách nào để vượt qua?Một thử thách thực sự không chỉ đối với nhân vật chính mà còn với các nhà làm phim. Một câu chuyện tưởng như đơn giản, không có gì đó, đạo diễn J.C. Chandor làm sao để All Is Lost trở nên hấp dẫn, cuốn hút người xem.Bối cảnh chỉ diễn ra trên biển (tất nhiên không quay ...</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324463);
