INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-do-chinh-thong-bat-dac-di', 'Tín Đồ Chính Thống Bất Đắc Dĩ', 'The Reluctant Fundamentalist', 'https://phimimg.com/upload/vod/20231031-1/65e4ba3a4bbae9bdb6c39bf331194abe.jpg', 'https://phimimg.com/upload/vod/20231031-1/388acb281c114ee25f4b83136cc462d9.jpg', '<p>Tại New York, một người gốc Pakistan nhận ra rằng Giấc mơ Mỹ của anh đã sụp đổ sau vụ tấn công khủng bố 11/9.</p>', 'Full', 1, 'single', 'completed', 25, 2013, 'Vietsub', 'HD', 'Qatar', 0, '[{"name":"Riz Ahmed","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Shabana Azmi","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Nelsan Ellis","avatar":""},{"name":"Haluk Bilginer","avatar":""},{"name":"Meesha Shafi","avatar":""},{"name":"Imaad Shah","avatar":""},{"name":"Christopher Nicholas Smith","avatar":""},{"name":"Ashwath Bhatt","avatar":""},{"name":"Sarah Quinn","avatar":""},{"name":"Chandrachur Singh","avatar":""},{"name":"Adil Hussain","avatar":""},{"name":"Ali Sethi","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
