INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tin-do-chinh-thong-bat-dac-di', 'Tín Đồ Chính Thống Bất Đắc Dĩ', 'The Reluctant Fundamentalist', 'tín đồ chính thống bất đắc dĩ the reluctant fundamentalist riz ahmed kate hudson liev schreiber kiefer sutherland om puri shabana azmi martin donovan nelsan ellis haluk bilginer meesha shafi imaad shah christopher nicholas smith ashwath bhatt sarah quinn chandrachur singh adil hussain ali sethi d ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trom-chuyen-nghiep', 'Tay Trộm Chuyên Nghiệp', 'Parker', 'https://phimimg.com/upload/vod/20231029-1/fa0cb13f6e89fdb13c4a85c7a4993685.jpg', 'https://phimimg.com/upload/vod/20231029-1/698a930df3a92346306af3fae7eb27bf.jpg', '<p>Tay trộm chuyên nghiệp Parker chuyển thể từ tiểu thuyết cùng tên của tác giả lừng danh Donald E. Westlake. Nội dung phim xoay quanh tên trộm liều lĩnh, kỹ tính và nhẫn tâm nhất - Parker . Tất cả những gì anh yêu cầu ở đội của mình là sự trung thành tuyệt đối - và phải bám sát lấy kế hoạch đặt ra.
 Nhưng vụ trộm lại trở nên vô cùng nguy hiểm cho tất cả bởi sự cẩu thả của một thành viên. Parker quyết định không tham gia với ông trùm xã hội đen Melander và băng nhóm của gã trong kế hoạch lớn tiếp theo. Không quen với việc bị từ chối, những tên trộm trở mặt với Parker, bắn và quẳng anh lại bên rìa một con đường vắng. Liệu Parker có sống sống? Anh sẽ làm gì để trả thù những kẻ muốn giết mình?.</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Michael Chiklis","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Sala Baker","avatar":""},{"name":"Carlos Carrasco","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Emma Booth","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Patti LuPone","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Earl Maddox","avatar":""},{"name":"Micah A. Hauptman","avatar":""},{"name":"Jon Eyez","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Carl J. W","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324463);
