INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cia-tai-xuat-2', 'CIA Tái Xuất 2', 'RED 2', 'https://phimimg.com/upload/vod/20231029-1/3bea5ab95a9cd8b79324ce8021cc240d.jpg', 'https://phimimg.com/upload/vod/20231029-1/af6980a59286df170877f262f22c6270.jpg', '<p>Một ngày nọ, trên trang WikiLeaks bỗng xuất hiện thông tin về Nightshade - món vũ khí hạt nhân có sức công phá không tưởng và ghi rằng Frank cùng Marvin có liên quan tới nó. Ngay lập tức hai cựu điệp viên này cùng Sarah trở thành nhiều mục tiêu săn đuổi, từ chính phủ Mỹ, Anh cho tới cả Nga.
 Phía Mỹ chọn sát thủ Han từ Hàn Quốc được mệnh danh là kẻ giết thuê tài ba nhất thế giới trong khi nước Anh cậy nhờ Victoria, thiện xạ quen thuộc từ phần 1. Hai cái tên nguy hiểm trên cùng sự xuất hiện của nữ tướng tình báo Nga Katja khiến Frank, Marvin và Sarah buộc phải lên đường chạy trốn...</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Garrick Hagon","avatar":""},{"name":"Tim Pigott-Smith","avatar":""},{"name":"Jong Kun Lee","avatar":""},{"name":"Philip Arditti","avatar":""},{"name":"Mitchell Mullen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
