INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-not-ngay-cuoi', 'Sống Nốt Ngày Cuối', 'This Is the End', 'https://phimimg.com/upload/vod/20231030-1/98b362e5e84167bb04cb8602a610a9c7.jpg', 'https://phimimg.com/upload/vod/20231030-1/f23346f34e98810808606bce7299f02d.jpg', '<p>Một nhóm người nổi tiếng của Hollywood tụ tập tại một bữa tiệc, vật lộn với mối nguy hiểm thảm khốc – và với nhau – khi tận thế bắt đầu.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Rihanna","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Aziz Ansari","avatar":""},{"name":"Samantha Ress","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
