INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-zombie', 'Tình Yêu Zombie', 'Warm Bodies', 'https://phimimg.com/upload/vod/20231029-1/c4a65d5400b52ffd765d0e057a27fc4c.jpg', 'https://phimimg.com/upload/vod/20231029-1/edf25975f8ae4113e9e59fe246ffeab5.jpg', '<p>Warm Bodies là bộ phim tình cảm lãng mạn kể về một một câu chuyện tình éo le giữa một thay ma và một con người. Khi con người bị tấn công bởi các thây ma thì một thây ma R đã yêu một cô gái tên là Julie ngay cái nhìn đầu tiên. Vì tình yêu nên R dạy cho Julie bắt chước cách sống của thây ma để cô không bị tấn công. Nhưng ngang trái thây cha của Julie là người đứng đầu của tổ chức chống thây ma. Liệu chuyện tình của họ sẽ kết thúc ra sau? Mặc dù Warm Bodies lấy chủ đề xác sống nhưng bộ phim mang lại nhiều cảm xúc cho người xem, từ lo sợ, lãng mạn, đau đớn, vui sướng chứ không ghê rợn giống như những bộ phim kinh dị cùng chủ đề khác</p>', 'Full', 1, 'single', 'completed', 24, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicholas Hoult","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Cory Hardrict","avatar":""},{"name":"Vincent Leclerc","avatar":""},{"name":"Daniel Rindress-Kay","avatar":""},{"name":"Chris Cavener","avatar":""},{"name":"Aaron Janke","avatar":""},{"name":"Serge Alain Cambronne","avatar":""},{"name":"Robert Reynolds","avatar":""},{"name":"John Topor","avatar":""},{"name":"Ayisha Issa","avatar":""},{"name":"Debbie Wong","avatar":""},{"name":"Christian P","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":