INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-ma', 'Mẹ Ma', 'Mama', 'https://phimimg.com/upload/vod/20231030-1/31719dc2ba6beff1a341bf13cca9157b.jpg', 'https://phimimg.com/upload/vod/20231030-1/a4cd4a75e4bf7bd85d43da56921dd7d7.jpg', '<p>Sau cái chết của cha mẹ, hai cô gái trẻ buộc phải cư trú trong một ngôi nhà có sự hiện diện đầy u ám và đáng sợ. Ngay cả sau khi được giải cứu, các thế lực tà ác vẫn theo họ đến ngôi nhà mới của họ.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Megan Charpentier","avatar":""},{"name":"Isabelle Nélisse","avatar":""},{"name":"Daniel Kash","avatar":""},{"name":"Melina Matthews","avatar":""},{"name":"Morgan McGarry","avatar":""},{"name":"Javier Botet","avatar":""},{"name":"Jane Moffat","avatar":""},{"name":"David Fox","avatar":""},{"name":"Dominic Cuzzocrea","avatar":""},{"name":"Julia Chantrey","avatar":""},{"name":"Ray Kahnert","avatar":""},{"name":"Christopher Marren","avatar":""},{"name":"Matthew Edison","avatar":""},{"name":"Diane Gor","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324463);
