INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-hung-chien-xu-so-la-cay', 'Trận Hùng Chiến Xứ Sở Lá Cây', 'Epic', 'https://phimimg.com/upload/vod/20231026-1/10d738a7ea1250d4be32ead1186b0983.jpg', 'https://phimimg.com/upload/vod/20231026-1/c2cfb6deb1cfae49328473681a03686b.jpg', '<p>Mary Katherine cùng các chiến hữu tí hon và khổng lồ bất đắc dĩ chống lại những thế lực đen tối để bảo vệ thế giới tươi đẹp bấy lâu của họ. Khi teaser có độ dài vài giây của bộ phim được phát hành vào mùa hè năm ngoái, nhiều suy đoán cho rằng Epic có chút gì đó hao hao các bộ phim khác như Ferngully: The Last Rainforest hay thậm chí là Avatar của James Cameron. Đạo diễn Chris Wedge chia sẻ: “Tôi ghét việc liên hệ Epic với những bộ phim khác. Nhưng có thể nói bộ phim giống như một chuyến phiêu lưu trong thế giới rộng lớn mênh mông của Star Wars và khiến cho khán giả hoàn toàn chìm đắm trong một thế giới diệu kỳ, mơ mộng và nên thơ như Avatar.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Aziz Ansari","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Beyoncé","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Steven Tyler","avatar":""},{"name":"Pitbull","avatar":""},{"name":"Blake Anderson","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Allison Bills","avatar":""},{"name":"Todd Cummings","avatar":""},{"name":"Troy Evans","avatar":""},{"name":"Emma Kenney","avatar":""},{"name":"Jaso","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324463);
