INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nguyen-elysium', 'Kỷ Nguyên Elysium', 'Elysium', 'https://phimimg.com/upload/vod/20231026-1/283168e477a12df66b4b8055408ee111.jpg', 'https://phimimg.com/upload/vod/20231026-1/731b8c913d1da90e6d4988eef70cf82c.jpg', '<p>Elysium là bộ phim về thảm họa Trái Đất. Bối cảnh phim vào năm 2159 có hai tầng lớp người tồn tại trên xã hội: những người rất giàu có sống trên trạm không gian nhân tạo Elysium, và số còn lại là những người sống trên một Trái Đất hoang tàn, ô nhiễm. Thư ký Rhodes, một viên chức chính phủ cương trực không ngừng nghỉ trong việc thực thi những đạo luật chống nhập cư và làm quấy rối cuộc sống xa xỉ của công dân Elysium. Nhưng điều đó vẫn không ngăn được người dân sống trên Trái Đất vượt biên bằng mọi cách. Max một gã dân Trái Đất bình thường khi tìm cách vào Elysium không may bị dồn vào đường cùng, đã đồng ý nhận một sứ mạng khiến ai cũng nản lòng mà nếu thành công sẽ cứu rỗi cuộc đời gã, thậm chí mang lại bình đẳng cho thế giới vốn đang bị phân cực...</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Jodie Foster","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Wagner Moura","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Jose Pablo Cantillo","avatar":""},{"name":"Faran Tahir","avatar":""},{"name":"Maxwell Perry Cotton","avatar":""},{"name":"Brandon Auret","avatar":""},{"name":"Josh Blacker","avatar":""},{"name":"Emma Tremblay","avatar":""},{"name":"Adrian Holmes","avatar":""},{"name":"Jared Keeso","avatar":""},{"name":"Michael Shanks","avatar":""},{"name":"Carly Pope","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":