INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dich-cum', 'Đại Dịch Cúm', 'The Flu', 'https://phimimg.com/upload/vod/20231026-1/261f0c49c8dcea8753767741f4fa1af6.jpg', 'https://phimimg.com/upload/vod/20231026-1/4e2bbb4c099f557934b24def772cf8e0.jpg', '<p>Chuyến tàu chở những người vượt biên trái phép sang Hàn quốc không ngờ đang mang trong mình mầm mống hiểm họa khôn lường khi trong số người vượt biên có một người đang mang mầm bệnh dịch. Và điều gì đến đã đến! Những người trốn trong chiếc container trên tàu đều bị nhiễm bệnh mà chết, chỉ còn lại một người... &nbsp;Kang Ji-Koo là nhân viên cứu hỏa cùng bác sĩ Kim In-Hae phải nhanh chóng cấp cứu và tìm ra chủng loại virus có khả năng gây chết người chỉ sau 36 giờ nhiễm bệnh cùng với cách điều trị. &nbsp;Và thời gian trở thành vấn đề cực đại khi Kim In Hae phát hiện ra chính con gái mình cũng đang mắc phải loại virus này.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Soo Ae","avatar":""},{"name":"Park Min-ha","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Lee Sang-yeob","avatar":""},{"name":"Cha In-pyo","avatar":""},{"name":"Kim Ki-hyeon","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Choi Byung-mo","avatar":""},{"name":"Kim Moon-Soo","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Jang Kyoung-up","avatar":""},{"name":"Na Ki-soo","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Seon Uk-hyeon","avatar":""},{"name":"Seol Chang-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b2390