INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('riddick-thong-linh-bong-toi', 'Riddick: Thống Lĩnh Bóng Tối', 'Riddick', 'https://phimimg.com/upload/vod/20231026-1/8b2e2261468d57474ab3e71af289750b.jpg', 'https://phimimg.com/upload/vod/20231026-1/1bcadbb5e87dbac8b0dda7c22e67e6b7.jpg', '<p>Ở cuối phần trước, Riddick đã trở thành Thống Soái của quân đoàn tinh nhuệ Necromonger. Nắm giữ cả thế giới trong lòng bàn tay nhưng anh luôn thấy lạc lõng và buồn chán ở thế giới xa lạ này. Một ngày, gã chỉ huy hai mặt Vaako (Karl Urban) tự nhận hắn biết được vị trí của Furya, hành tinh quê hương của Riddick. Nỗi khao khát được trở lại quê nhà lấn át mối hoài nghi đối với Vaako. Chọn một vài người lính tin cẩn nhất, Riddick lên tàu và rời khỏi tổ ấm của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Matt Nable","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Nolan Gerard Funk","avatar":""},{"name":"Andreas Apergis","avatar":""},{"name":"Noah Dalton Danby","avatar":""},{"name":"Neil Napier","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Conrad Pla","avatar":""},{"name":"Danny Blanco Hall","avatar":""},{"name":"Keri Hilson","avatar":""},{"name":"Charlie Marie Dupont","avatar":""},{"name":"Jan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
