INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-nam-no-le', '12 Năm Nô Lệ', '12 Years a Slave', 'https://phimimg.com/upload/vod/20231026-1/a8e953837eaa42f6b3d141baf1de0249.jpg', 'https://phimimg.com/upload/vod/20231026-1/b36c5b0a69b052af7a5117fdae05e016.jpg', '<p>12 Năm Nô Lệ là một bộ phim truyền hình lịch sử Mỹ-Anh của đạo diễn Steve McQueen. Trong những năm trước khi cuộc nội chiến, Solomon Northup (Chiwetel Ejiofor), một người da đen tự do ở New York bị bắt cóc và bán làm nô lệ ở miền Nam. Chịu sự tàn ác của một nô lệ (Michael Fassbender) nhưng anh cũng tìm thấy lòng tốt bất ngờ từ những người khác trong khi cuộc đấu tranh liên tục để tồn tại và bảo vệ nhân phẩm của mình. Sau đó, trong năm thứ 12 của những thử thách đau lòng, một cơ hội gặp gỡ với một chế độ nô lệ từ Canada đã thay đổi cuộc sống của Solomon mãi mãi.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Lupita Nyong''o","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Adepero Oduye","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Chris Chalk","avatar":""},{"name":"Taran Killam","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Kelsey Scott","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324463);
