INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('12-nam-no-le', '12 Năm Nô Lệ', '12 Years a Slave', '12 năm nô lệ 12 years a slave chiwetel ejiofor michael fassbender lupita nyong''o benedict cumberbatch paul dano sarah paulson adepero oduye scoot mcnairy paul giamatti brad pitt michael kenneth williams alfre woodard chris chalk taran killam bill camp kelsey scott ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-hai-mang', 'Điệp Vụ Hai Mang', '2 Guns', 'https://phimimg.com/upload/vod/20231026-1/10d7af1fb5b66ddf6e09685750f97401.jpg', 'https://phimimg.com/upload/vod/20231026-1/e8fb2f135ea655feb21ab9d5ad7a2fed.jpg', '<p>Hai người đàn ông là điệp viên, họ là Bobby và Marcus. Họ là điệp viên của hai cục điều tra khác nhau nhưng lại nhận chung một nhiệm vụ trà trộn vào một tổ chức ma túy lớn. Hai người cùng thi hành nhiệm vụ của mình nhưng không ai biết được thân phận thực sự của người kia. Và từ ngày chạm mặt họ đã không ưa gì người đối diện mình, cả hai như nước với lửa. Tuy nhiên hành động của bọn họ không thể qua mắt nổi tên trùm, hắn ta đã dùng mưu kế cho hai người tham gia một vụ cướp ngân hàng và tại đây họ bị nhận diện là cớm và bị truy đuổi bởi những đồng nghiệp của mình. Nhiệm vụ của hai người đã thất bại, và giờ đây họ phải cùng nhau chiến đấu.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Paula Patton","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Robert John Burke","avatar":""},{"name":"Greg Sproles","avatar":""},{"name":"Patrick Fischler","avatar":""},{"name":"Derek Solorsano","avatar":""},{"name":"Edgar Arreola","avatar":""},{"name":"Kyle Clements","avatar":""},{"name":"Christopher Matthew Cook","avatar":""},{"name":"Tim Bell","avatar":""},{"name":"Tait Fletcher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324463);
