INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyen-truong-phillips', 'Thuyền Trưởng Phillips', 'Captain Phillips', 'https://phimimg.com/upload/vod/20231026-1/f9098245de012898bd8f7291306bcdb0.jpg', 'https://phimimg.com/upload/vod/20231026-1/d8790246a34678fa86e93526811a5a57.jpg', '<p>Captain Phillips kể lại câu chuyện có thật về 18 tiếng kinh hoàng của thuyền trưởng Phillips. Ông đang điều khiển con tàu Maersk Alabama trên biển Ấn Độ Dương thì bị cướp biển Somali đánh cướp. Đây cũng là vụ cướp tàu chở hàng của Mỹ đầu tiên trong suốt 200 năm qua. Không chỉ cướp hàng, chúng còn bắt cóc Phillips làm con tin nhằm đòi tiền chuộc dẫn đến một cuộc giải cứu đầy kịch tính.</p>', 'Full', 1, 'single', 'completed', 21, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Barkhad Abdi","avatar":""},{"name":"Barkhad Abdirahman","avatar":""},{"name":"Faysal  Ahmed","avatar":""},{"name":"Mahat M. Ali","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Chris Mulkey","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Omar Berdouni","avatar":""},{"name":"Mohamed Ali","avatar":""},{"name":"Issak Farah Samatar","avatar":""},{"name":"Thomas Grube","avatar":""},{"name":"Mark Holde","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
