INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuyen-truong-phillips', 'Thuyền Trưởng Phillips', 'Captain Phillips', 'thuyền trưởng phillips captain phillips tom hanks barkhad abdi barkhad abdirahman faysal  ahmed mahat m. ali michael chernus david warshofsky corey johnson chris mulkey yul vazquez max martini catherine keener omar berdouni mohamed ali issak farah samatar thomas grube mark holde ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-xanh-nong-am', 'Màu Xanh Nồng Ấm', 'Blue Is the Warmest Color', 'https://phimimg.com/upload/vod/20231026-1/a7b891220fc733b1408d5c4dad330356.jpg', 'https://phimimg.com/upload/vod/20231026-1/b559e8ec8f24a57f7124256cb911db7d.jpg', '<p>Màu Xanh Nồng Ấm xoay quanh chuyện tình cảm của Adele,một cô nữ sinh 17 tuổi cô gái xinh xắn và học giỏi nhất trường nhưng đang loay hoay với chính cảm xúc, giới tính thật của mình. Trong một lần cô gái đã chấp nhận tự thỏa hiệp với bản thân khi lên giường với một chàng trai có tình cảm với cô, chỉ để thấy sự hờ hững của mình trong mối quan hệ này và chia tay ngay sau đó. Cuộc sống và con người Adele dần trở nên mất phương hướng khi vô tình gặp cô gái học mỹ thuật Emma, người có mái tóc xanh nổi loạn ở giữa ngã tư đường. Vật lộn giữa bản năng giới tính và các mối quan hệ xã hội, Adele vẫn quyết định dấn thân vào, khám phá và nếm trải mối tình đồng tính này từng bước một, giống như mọi chuyện tình yêu trên thế gian. Cùng nhau, Adele và Emma khám phá mọi thứ từ sự chấp nhận của xã hội cho tới tình dục , và cảm xúc họ dành cho nhau khi cả 2 đều đến tuổi trưởng thành,liệu rằng họ có đến được với nhau mãi mãi</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Adèle Exarchopoulos","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Salim Kechiouche","avatar":""},{"name":"Aurélien Recoing","avatar":""},{"name":"Catherine Salée","avatar":""},{"name":"Benjamin Siksou","avatar":""},{"name":"Mona Walravens","avatar":""},{"name":"Jérémie Laheurte","avatar":""},{"name":"Alma Jodorowsky","avatar":""},{"name":"Anne Loiret","avatar":""},{"name":"Benoît Pilot","avatar":""},{"name":"Sandor Funtek","avatar":""},{"name":"Fanny Maurin","avatar":""},{"name":"Maelys Cabezon","avatar":""},{"name":"Samir Bella","avatar":""},{"name":"Tom Hurier","avatar":""},{"name":"Man","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324463);
