INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-nha-trang', 'Giải Cứu Nhà Trắng', 'White House Down', 'https://phimimg.com/upload/vod/20231026-1/ca3a7033c995409d160ac9a0e9e7e1c3.jpg', 'https://phimimg.com/upload/vod/20231026-1/659adf3d373af422cb5b4dbc60a4239f.jpg', '<p>Khi một tổ chức bán quân sự vạch ra kế hoạch đẫm máu hòng chiếm đóng Nhà Trắng, tổng thống phải tìm cách trốn chạy kẻ tấn công cho đến khi được giải cứu.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Joey King","avatar":""},{"name":"Maggie Gyllenhaal","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"James Woods","avatar":""},{"name":"Nicolas Wright","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Michael Murphy","avatar":""},{"name":"Rachelle Lefevre","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Kevin Rankin","avatar":""},{"name":"Garcelle Beauvais","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
