INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-ba-dao', 'Gia Đình Bá Đạo', 'We''re the Millers', 'https://phimimg.com/upload/vod/20231026-1/52abc470583bdba3affe8bb3a2411174.jpg', 'https://phimimg.com/upload/vod/20231026-1/9e7f9ac8591502662e9bb05f4c134dda.jpg', '<p>Chuyện phim xoay quanh kẻ buôn thuốc phiện (Jason Sudeikis thủ vai) phải tìm cách vượt biên giới Mỹ - Mexico với 1.500 kg ma túy. Để hợp thức hóa mọi chuyện ở cửa khẩu, không bị nghi ngờ hắn liền lên kế hoạch lập một gia đình giả để vờ đi du lịch trong chiếc ô tô cùng số hàng cấm. Một cô vũ nữ (Jennifer Aniston thủ vai) được hắn tuyển làm vợ, một đứa trẻ vô gia cư (Emma Roberts đóng) và một thằng bé hàng xóm người Anh (Will Poulter) được tuyển làm con gái và con trai. Bộ tứ gia đình hỗn tạp bắt đầu chuyến hành trình dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 14, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Aniston","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Emma Roberts","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Molly C. Quinn","avatar":""},{"name":"Tomer Sisley","avatar":""},{"name":"Matthew Willig","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Mark L. Young","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Laura-Leigh","avatar":""},{"name":"Crystal Nichol","avatar":""},{"name":"Dickson Obahor","avatar":""},{"name":"Brett Ge","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324463);
