INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tu-than-3-dia-nguc', 'Cuộc Đua Tử Thần 3: Địa Ngục', 'Death Race: Inferno', 'https://phimimg.com/upload/vod/20231026-1/ea2f573fc423d67bf49716da9fc080bc.jpg', 'https://phimimg.com/upload/vod/20231026-1/c01850692b7ee773a8ddfbbe10dc3679.jpg', '<p>Nếu bạn là 1 fan của bộ phim Death Race, hẳn bạn sẽ rất vui mừng vì đạo diễn Roel Reine vừa trở lại cùng phần 3 của bộ phim Death Race 3 : Inferno. Phần 1 của Death Race ra mắt vào năm 2008 với nam tài tử Jason Statham trong vai một tù nhân phải tham gia cuộc đua sinh tử với những người bạn tù và người chiến thắng sẽ có được tự do, sang phần 2 bộ phim giới thiệu một nhân vật mới: Frankenstein được diễn bởi diễn viên Luke Goss, đến phần 3 Goss quay trở lại vai Frankenstein với cuộc đua tại một địa điểm mới: sa mạc Kalahari Nam Phi. Giống như những phần trước của bộ phim, Death Race 3 mang tới những cuộc đua xe tốc độ đầy tàn khốc với những chiếc xe tự chế theo phong cách Mad-Max, đầy súng ống.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Goss","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Tanit Phoenix","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Robin Shou","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Frederick Koehler","avatar":""},{"name":"Tanya van Graan","avatar":""},{"name":"Sean Cameron Michael","avatar":""},{"name":"Hlubi Mboya","avatar":""},{"name":"Charlbi Dean","avatar":""},{"name":"Mark Elderkin","avatar":""},{"name":"Eugene Khumbanyiwa","avatar":""},{"name":"Jeremy Crutchley","avatar":""},{"name":"Yrsa Daley-Ward","avatar":""},{"name":"Ebb","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
