INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-dua-tu-than-3-dia-nguc', 'Cuộc Đua Tử Thần 3: Địa Ngục', 'Death Race: Inferno', 'cuộc đua tử thần 3: địa ngục death race: inferno luke goss ving rhames danny trejo tanit phoenix dougray scott robin shou langley kirkwood frederick koehler tanya van graan sean cameron michael hlubi mboya charlbi dean mark elderkin eugene khumbanyiwa jeremy crutchley yrsa daley-ward ebb ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khong-trong-luc', 'Cuộc Chiến Không Trọng Lực', 'Gravity', 'https://phimimg.com/upload/vod/20231026-1/2a2d6aefdb03ef39ba87082f522e4809.jpg', 'https://phimimg.com/upload/vod/20231026-1/2a1a3d35803fc55b20a590c3aac776df.jpg', '<p>Tiến sĩ Ryan Stone, một kỹ sư y tế xuất sắc trong nhiệm vụ Tàu con thoi đầu tiên của cô, cùng với phi hành gia kỳ cựu Matt Kowalsky chỉ huy chuyến bay cuối cùng trước khi nghỉ hưu. &nbsp;Nhưng trên một chuyến đi bộ ngoài không gian dường như thường lệ, thảm họa đã ập đến. &nbsp;Tàu con thoi bị phá hủy, khiến Stone và Kowalsky hoàn toàn bị trói buộc vào nhau và rơi vào bóng tối của không gian. &nbsp;Sự im lặng chói tai cho họ biết họ đã mất bất kỳ liên kết nào với Trái đất và bất kỳ cơ hội giải cứu nào. &nbsp;Khi nỗi sợ hãi chuyển sang hoảng sợ, mỗi luồng không khí sẽ ăn hết lượng oxy ít ỏi còn lại. &nbsp;Nhưng cách duy nhất về nhà có thể là đi xa hơn vào khoảng không gian rộng lớn đáng sợ.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Orto Ignatiussen","avatar":""},{"name":"Phaldut Sharma","avatar":""},{"name":"Amy Warren","avatar":""},{"name":"Basher Savage","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324463);
