INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-choi-co-nhan', 'Có Chơi, Có Nhận', 'Pain & Gain', 'https://phimimg.com/upload/vod/20231026-1/2641e32f4aea2e88f865379eaae0f250.jpg', 'https://phimimg.com/upload/vod/20231026-1/bddb410233076a746ef38701ca56e422.jpg', '<p>Pain And Gain (Có Chơi &amp; Có Nhận) là bộ phim dựa trên một câu chuyện có thật từng được đăng tải trên tờ Miami New Times. Bối cảnh của phim là thành phố Miami những năm 1990. Trong phim, ba chàng huấn luyện viên thể hình bắt cóc một doanh nhân giàu có nhằm hiện thực hóa nhanh chóng giấc mơ Mỹ của mình. Tuy nhiên, kế hoạch đó không diễn ra như mong muốn. Ba nhân vật chính nhanh chóng nhận ra rằng phi vụ của họ chỉ đem lại những vụ đấu súng, cảnh sát và sự thù oán với các băng nhóm tội phạm địa phương.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Bar Paly","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Michael Rispoli","avatar":""},{"name":"Keili Lefkovitz","avatar":""},{"name":"Vivi Pineda","avatar":""},{"name":"Christopher Jestin Langstaff","avatar":""},{"name":"Gustavo Escobar","avatar":""},{"name":"Corinne Ferrer","avatar":""},{"name":"Zack Moore","avatar":""},{"name":"Kory Getman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
