INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum-huyen-thoai-rung-smurfy', 'Xì Trum: Huyền Thoại Rừng Smurfy', 'The Smurfs: The Legend of Smurfy Hollow', 'https://phimimg.com/upload/vod/20231024-1/bd17d7a58a819879b449982e7aca5c27.jpg', 'https://phimimg.com/upload/vod/20231024-1/e44493f23230d4a039fee64e1a5d06c9.jpg', '<p>Khi Brainy Smurf được ưu ái giành chiến thắng trong Cuộc săn Smurfberry hàng năm năm thứ chín liên tiếp, Gutsy Smurf bắt đầu khám phá cách Brainy giành chiến thắng hàng năm. Cuộc điều tra của Gutsy đưa anh vào Thung lũng Smurfy ma quái – và rơi thẳng vào cái bẫy của Gargamel! Liệu Brainy và Gutsy, với sự giúp đỡ của Smurfette, có thể gạt bỏ sự cạnh tranh của họ trước khi Gargamel bắt giữ họ hay tệ hơn là họ đối mặt với hồn ma huyền thoại, Kỵ sĩ không đầu?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hank Azaria","avatar":""},{"name":"Melissa Sturm","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Tom Kane","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Adam Wylie","avatar":""},{"name":"John Oliver","avatar":""},{"name":"Gary Basaraba","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324463);
