INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-dao-tau', 'Kế Hoạch Đào Tẩu', 'Escape Plan', 'https://phimimg.com/upload/vod/20231024-1/b9da4f1f9f9d43caf1f29db1cdc0839c.jpg', 'https://phimimg.com/upload/vod/20231024-1/deda6f13eeeca9ad1dc9ef2f3c77a837.jpg', '<p>Một chuyên gia phân tích thiết kế hệ thống an ninh cho các tòa nhà bị gài bẫy và bị bắt giam vào nhà tù có hệ thống an ninh do chính anh “có công” thiết lập. Anh buộc phải liên kết với người bạn tù của mình và lập ra một kế hoạch đào thoát khỏi “lăng mộ” kiên cố, được bảo vệ an toàn nhất trên thế giới.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Faran Tahir","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Graham Beckel","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Caitríona Balfe","avatar":""},{"name":"David Joseph Martinez","avatar":""},{"name":"Alec Rayme","avatar":""},{"name":"Christian Stokes","avatar":""},{"name":"Rodney Feaster","avatar":""},{"name":"Dav","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
