INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-gia-gatsby', 'Đại Gia Gatsby', 'The Great Gatsby', 'https://phimimg.com/upload/vod/20231024-1/2063bf45acef15a457233f1e5f7c86a5.jpg', 'https://phimimg.com/upload/vod/20231024-1/d3e42865d9983f0328cb1c32eab97383.jpg', '<p>Giữa thành phố Long Island năm 1922, Nick Carraway bị cuốn hút bởi lối sống bí ẩn và xa hoa của người hàng xóm Jay Gatsby. Nick bị hút vào vòng xoáy của cuộc sống thượng lưu quanh Gatsby, nhưng chẳng bao lâu sau, qua các vết nứt của sự giàu có, xa hoa của Gatsby, Nick Carraway cảm nhận được nỗi ám ảnh, điên rồ, và cả những bi kịch đang chờ đợi.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Amitabh Bachchan","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Adelaide Clemens","avatar":""},{"name":"Steve Bisley","avatar":""},{"name":"Richard Carter","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Vince Colosimo","avatar":""},{"name":"Max Cullen","avatar":""},{"name":"Mal Day","avatar":""},{"name":"Charlize","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324463);
