INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-ky-si-bong-dem-tro-lai-phan-2', 'Nguời Dơi: Kỵ Sĩ Bóng Đêm Trở Lại, Phần 2', 'Batman: The Dark Knight Returns, Part 2', 'https://phimimg.com/upload/vod/20231023-1/867756a712e0d86696f708c6c6ee99ff.jpg', 'https://phimimg.com/upload/vod/20231023-1/d5ff1f10912a981c8f7a57fae1ccfd69.jpg', '<p>Phần 2 tiếp tục cuộc hành trình đầy gian khó của Bruce Wayne để bảo vệ người dân và thành phố trước thế lực đen tối. Batman không những đối mặt với kẻ thù không đội trời chung là Joker, mà còn phải đối đầu với người bạn thân lâu năm, Superman...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Weller","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"David Selby","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Mark Valley","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"James Patrick Stuart","avatar":""},{"name":"Maria Canals-Barrera","avatar":""},{"name":"Gwendoline Yeo","avatar":""},{"name":"Danny Jacobs","avatar":""},{"name":"Townsend Coleman","avatar":""},{"name":"Michael Jackson","avatar":""},{"name":"Bruce Timm","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324463);
