INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-doi-ky-si-bong-dem-tro-lai-phan-2', 'Nguời Dơi: Kỵ Sĩ Bóng Đêm Trở Lại, Phần 2', 'Batman: The Dark Knight Returns, Part 2', 'nguời dơi: kỵ sĩ bóng đêm trở lại, phần 2 batman: the dark knight returns, part 2 peter weller ariel winter david selby michael emerson mark valley grey delisle frank welker dee bradley baker michael mckean james patrick stuart maria canals-barrera gwendoline yeo danny jacobs townsend coleman michael jackson bruce timm ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hansel-gretel-tho-san-phu-thuy', 'Hansel & Gretel: Thợ Săn Phù Thủy', 'Hansel & Gretel: Witch Hunters', 'https://phimimg.com/upload/vod/20231023-1/67599db462bf583a2a009a8a4bb713a8.jpg', 'https://phimimg.com/upload/vod/20231023-1/43a7d12a8e161ca2dfadcd0d996de1ac.jpg', '<p>Chuyện phim bắt đầu 15 năm sau khi hai anh em Hansel (Jeremy Renner) và Gretel (Gemma Arterton) thoát khỏi mụ phù thủy ăn thịt trẻ em, kẻ đã thay đổi cuộc sống của họ mãi mãi và cho họ cơ hội nếm trải mùi thù hận. Sau nhiều năm, hai anh em trở thành những thợ săn tiền thưởng với kỹ năng vượt bậc, toàn tâm toàn ý cho sự nghiệp truy đuổi và tiêu diệt những mụ phù thuỷ ác trốn trong rừng sâu. Hai nhân vật chính, Hansel và Gretel, trong phim. Ảnh: Paramount. Nhưng rồi thị trấn nhỏ với những căn nhà gỗ quen thuộc lại phải đối mặt với cơn ác mộng khi những đứa trẻ vô tội bắt đầu mất tích. Hansel và Gretel đứng trước một thứ ác hiểm hơn bất cứ phù thủy nào mà mình từng săn đuổi - kẻ có thể hé lộ vài bí mật về quá khứ ...</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeremy Renner","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Pihla Viitala","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Ingrid Bolsø Berdal","avatar":""},{"name":"Joanna Kulig","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Bjørn Sundquist","avatar":""},{"name":"Rainer Bock","avatar":""},{"name":"Thomas Scharff","avatar":""},{"name":"Kathrin Kühnel","avatar":""},{"name":"Zoë Bell","avatar":""},{"name":"Monique Ganderton","avatar":""},{"name":"Christ","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324463);
