INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot-2013', 'Sống Sót', 'Lone Survivor', 'https://phimimg.com/upload/vod/20231022-1/c6de83e325393dc9fa96c49b69f2789c.jpg', 'https://phimimg.com/upload/vod/20231022-1/d736c44c9bb5b9b79bdeaa86c1f030d4.jpg', '<p>Phim kể câu chuyện về bốn lính đặc nhiệm Navy SEAL của Mỹ khi đội đặc nhiệm thực hiện nhiệm vụ bí mật nhằm tiêu diệt thủ lĩnh cấp cao của tổ chức al-Qaeda đang lẩn trốn ở vùng núi Afghanistan. Trong khi triển khai nhiệm vụ, họ bị kẻ địch phát hiện sau khi thả những thường dân mà họ vô tình bắt gặp trên đường tiến quân. Cả đội đặc nhiệm bị phục kích bởi phiến quân Taliban có vũ khí và lực lượng áp đảo. Trong khi chờ chi viện, họ đã chiến đấu anh dũng để tìm đường thoát khỏi vùng đất của Taliban.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Ali Soliman","avatar":""},{"name":"Alexander Ludwig","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Scott Elrod","avatar":""},{"name":"Josh Berry","avatar":""},{"name":"Yousuf Azami","avatar":""},{"name":"Sammy Sheik","avatar":""},{"name":"Rich Ting","avatar":""},{"name":"Dan Bilzerian","avatar":""},{"name":"Rick Vargas","avatar":""},{"name":"Gregory Rockwood","avatar":""},{"name":"Ryan Kay","avatar":""},{"name":"Patrick Griffin","avatar":""},{"name":"Eric S","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324463);
