INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thanh-trung', 'Ngày Thanh Trừng', 'The Purge', 'https://phimimg.com/upload/vod/20231022-1/3dfcbd4084e92cb68ec3aa6285050e54.jpg', 'https://phimimg.com/upload/vod/20231022-1/10fcc3b5708794c5f2b056d6b712d72d.jpg', '<p>The Purge lấy bối cảnh thế giới tương lai vào năm 2022, khi Mỹ trở thành “quốc gia mới tái sinh”, với tội phạm và tỷ lệ thất nghiệp ở mức rất thấp. Để giữ mức ổn định này, chính phủ hàng năm đều có một chiến dịch có tên gọi “12 giờ thanh trừng” để con người có thể tự do giải thoát mọi cảm xúc tiêu cực của họ. Trong 12 tiếng này, các hành vi phạm tội (bao gồm cả giết người) đều không bị truy xét trước pháp luật. Bi kịch xảy đến khi một gia đình bị bắt làm con tin và một câu chuyện rùng rợn bắt đầu...</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Max Burkholder","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"Rhys Wakefield","avatar":""},{"name":"Tony Oller","avatar":""},{"name":"Arija Bareikis","avatar":""},{"name":"Tom Yi","avatar":""},{"name":"Chris Mulkey","avatar":""},{"name":"Tisha French","avatar":""},{"name":"Dana Bunch","avatar":""},{"name":"Peter Gvozdas","avatar":""},{"name":"John Weselcouch","avatar":""},{"name":"Alicia Vela-Bailey","avatar":""},{"name":"David Basila","avatar":""},{"name":"Boima Blake","avatar":""},{"name":"Nathan Clarkso","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
