INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-thanh-trung', 'Ngày Thanh Trừng', 'The Purge', 'ngày thanh trừng the purge ethan hawke lena headey max burkholder adelaide kane edwin hodge rhys wakefield tony oller arija bareikis tom yi chris mulkey tisha french dana bunch peter gvozdas john weselcouch alicia vela-bailey david basila boima blake nathan clarkso ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-trang-that-thu', 'Nhà Trắng Thất Thủ', 'Olympus Has Fallen', 'https://phimimg.com/upload/vod/20231023-1/54633352d34c1257b09813287b1b1db5.jpg', 'https://phimimg.com/upload/vod/20231023-1/1d386f5ee8bea5078de55693d6ec46df.jpg', '<p>Chuyện phim nói về một nhóm phần tử cực đoan được trang bị vũ khí hạng nặng và huấn luyện kỹ càng cùng thực hiện một vụ đột kích táo bạo vào Nhà Trắng ở thủ đô Washington giữa ban ngày. Chúng nhanh chóng nắm quyền kiểm soát, bắt giữ Tổng thống Benjamin Asher và bộ tham mưu của nước Mỹ trong một căn hầm bất khả xâm phạm ở ngay dưới dinh tổng thống. Khi cuộc chiến ác liệt nổ ra trước bãi cỏ Nhà Trắng, cựu nhân viên an ninh Mike Banning tìm đường đột nhập vào bên trong để làm nhiệm vụ được anh cho là lý tưởng của cuộc đời – bảo vệ Tổng thống, bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Finley Jacobsen","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"Rick Yune","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Phil Austin","avatar":""},{"name":"James Ingersoll","avatar":""},{"name":"Freddy Bosche","avatar":""},{"name":"Lance Broadway","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Keong Sim","avatar":""},{"name":"Kevin Moon","avatar":""},{"name":"Mal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
