INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-den-luc', 'Đã Đến Lúc', 'About Time', 'https://phimimg.com/upload/vod/20231023-1/ab3b334683ab5f92a11c38d95ead964d.jpg', 'https://phimimg.com/upload/vod/20231023-1/a996e8cd2b97ea3db2c2bc2727d6e658.jpg', '<p>Vào bữa tiệc trước thềm năm mới, Tim (Domhnall Gleeson) được chính cha mình “giới thiệu” về khả năng “truyền thống” của gia đình: có thể đi xuyên qua thời gian trở về quá khứ. Ngỡ ngàng và thích thú, Tim quyết định phải thay đổi cuộc đời mình khiến nó tốt đẹp hơn bằng việc đi tìm cho bản thân một cô bạn gái… Kết quả là, cậu đã thấy mục tiêu nhưng liệu rằng, những khả năng thiên phú của Tim có thể giúp cậu dễ dàng chinh phục được nàng hay không?</p>', 'Full', 1, 'single', 'completed', 20, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Domhnall Gleeson","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Lydia Wilson","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Richard Cordery","avatar":""},{"name":"Joshua McGuire","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Will Merrick","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Tom Hughes","avatar":""},{"name":"Clemmie Dugdale","avatar":""},{"name":"Harry Hadden-Paton","avatar":""},{"name":"Mitchell Mullen","avatar":""},{"name":"Lisa Eichhorn","avatar":""},{"name":"Jenny","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324463);
