INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-nhan-tiep-theo', 'Nạn Nhân Tiếp Theo', 'You''re Next', 'https://phimimg.com/upload/vod/20231020-1/565fe5d3aa64645cb4ce11223b789c70.jpg', 'https://phimimg.com/upload/vod/20231020-1/c599bda03b495c28764925adcf1ca7a7.jpg', '<p>Một cuộc đoàn tụ gia đình bỗng biến thành một cuộc thảm sát đầy chết chóc khi họ trở thành mục tiêu của một tên sát nhân đeo mặt nạ. Hy vọng duy nhất của họ là Erin, cô bạn gái của một thành viên trong gia đình.</p>', 'Full', 1, 'single', 'completed', 15, 2013, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sharni Vinson","avatar":""},{"name":"Nicholas Tucci","avatar":""},{"name":"Wendy Glenn","avatar":""},{"name":"AJ Bowen","avatar":""},{"name":"Joe Swanberg","avatar":""},{"name":"Margaret Laney","avatar":""},{"name":"Amy Seimetz","avatar":""},{"name":"Ti West","avatar":""},{"name":"Rob Moran","avatar":""},{"name":"Barbara Crampton","avatar":""},{"name":"L.C. Holt","avatar":""},{"name":"Simon Barrett","avatar":""},{"name":"Lane Hughes","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Kate Lyn Sheil","avatar":""},{"name":"Calvin Lee Reeder","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324463);
