INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nan-nhan-tiep-theo', 'Nạn Nhân Tiếp Theo', 'You''re Next', 'nạn nhân tiếp theo you''re next sharni vinson nicholas tucci wendy glenn aj bowen joe swanberg margaret laney amy seimetz ti west rob moran barbara crampton l.c. holt simon barrett lane hughes larry fessenden kate lyn sheil calvin lee reeder ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-gi-joe-bao-thu', 'Biệt Đội G.I. Joe: Báo Thù', 'G.I. Joe: Retaliation', 'https://phimimg.com/upload/vod/20231020-1/bb7582978d0d35ed5614b566d55b6f10.jpg', 'https://phimimg.com/upload/vod/20231020-1/18e86266109a8fbe7028296d82697cb8.jpg', '<p>Đây là phần tiếp theo của bom tấn vô cùng ăn khách – “G.I. Joe: The Rise of Cobra”. Nội dung phần 2 của &quot;G.I. Joe&quot; bắt đầu khi những người lãnh đạo nước Mỹ bị tổ chức Cobra (kẻ thù không đội trời chung của đội đặc nhiệm G.I.Joe) kiểm soát và ra lệnh loại bỏ G.I.Joe. Toàn bộ nhóm đặc vụ bị gài bẫy và gần như bị xóa sổ. Những người còn sống của đội đặc nhiệm tìm đến sự giúp đỡ của người lãnh đạo G.I. Joe năm xưa - tướng Joe Colton để cùng nhau tìm nguyên nhân thực sự của mọi chuyện và tìm cách giải cứu nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 17, 2013, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Adrianne Palicki","avatar":""},{"name":"Ray Park","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Élodie Yung","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"D.J. Cotrona","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Joseph Mazzello","avatar":""},{"name":"RZA","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"DeRay Davis","avatar":""},{"name":"Ravi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
