INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-gi-joe-bao-thu', 'Biệt Đội G.I. Joe: Báo Thù', 'G.I. Joe: Retaliation', 'biệt đội g.i. joe: báo thù g.i. joe: retaliation dwayne johnson bruce willis jonathan pryce adrianne palicki ray park ray stevenson élodie yung lee byung-hun d.j. cotrona luke bracey channing tatum joseph mazzello rza arnold vosloo walton goggins matt gerald joe chrest deray davis ravi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dragon-ball-z-tran-chien-cua-cac-vi-than', 'Dragon Ball Z: Trận Chiến Của Các Vị Thần', 'Dragon Ball Z: Battle of Gods', 'https://phimimg.com/upload/vod/20231020-1/dadec98fe3c052168804875bf20e7cb6.jpg', 'https://phimimg.com/upload/vod/20231020-1/65152e5cb2c07ac3b660d2e4a322d369.jpg', '<p>Trong phần Dragon Ball Z Battle Of God, Goku và nhóm bạn của mình phải đối mặt với một đối thủ ở cấp độ khác hoàn toàn là thần phá hoại. Sau mấy chục năm ngủ, thần phá hoại tỉnh giấc vì cảm nhận được sẽ gặp được đối thủ xứng tầm với mình nên lên đường đi tìm đối thủ này. Nhưng lại không may mắn nguồn năng lượng của đối thủ này lại nằm ở Trái Đất, nơi nhóm bạn của Goku. Goku bỏ qua lời khuyên của Thần Vũ Trụ (King Kai) và thách thức Bills trong 1 trận chiến. Tuy nhiên Goku không đủ mạnh trước sức mạnh áp đảo của Bills và đã bị đánh bại. Bills bỏ đi sau khi thốt lên “Có kẻ nào đó trên Trái Đất xứng đáng để tiêu diệt?”. Trách nhiệm bảo vệ Trái Đất lại một lần nữa phụ thuộc vào họ, nhóm bạn của Goku phải làm như thế nào để có thể làm hài lòng thần phá hoại để Trái Đất không bị hủy diệt?</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Masakazu Morita","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Joji Yanami","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Shoko Nakagawa","avatar":""},{"name":"Kenji Utsumi","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Kozo Shioya","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Unsho Ishizuk","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324463);
