INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dragon-ball-z-tran-chien-cua-cac-vi-than', 'Dragon Ball Z: Trận Chiến Của Các Vị Thần', 'Dragon Ball Z: Battle of Gods', 'dragon ball z: trận chiến của các vị thần dragon ball z: battle of gods masako nozawa koichi yamadera masakazu morita ryou horikawa hiromi tsuru joji yanami toshio furukawa shoko nakagawa kenji utsumi mayumi tanaka toru furuya hikaru midorikawa kozo shioya shigeru chiba tessyo genda takeshi kusao unsho ishizuk ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-sieu-trom', 'Truy Lùng Siêu Trộm', 'Cold Eyes', 'https://phimimg.com/upload/vod/20231019-1/a992f78062d29437c05834dfd995c958.jpg', 'https://phimimg.com/upload/vod/20231019-1/6c8078ffe53c9aa42d1c8a2b5eca65c2.jpg', '<p>Ha Yoon Ju (Han Hyo Joo) là một cô gái sở hữu bộ nhớ siêu phàm, khả năng quan sát &amp; tập trung tối đa. Cô là thành viên mới nhất của Ủy ban chống tội phạm đặc biệt (SCU), chuyên điều tra, giám sát các hồ sơ tội phạm nguy hiểm và xảo quyệt. Đồng hành cùng Yoon Ju là đội trưởng kỳ cựu Hwang Sang Jun (Seol Kyung Gu). Mục tiêu của cả đội là James (Jung Woo Sung), thủ lĩnh lạnh lùng của một tổ chức tội phạm có vũ trang. Với trí thông minh tột đỉnh, James luôn giúp băng nhóm thoát khỏi mọi sự theo dõi, truy lùng từ phía cảnh sát. Bây giờ, Sang Jun và Yoon Ju phải tìm mọi cách, thậm chí đặt cược cả tính mạng để có thể truy tìm và ngăn chặn James.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Sol Kyung-gu","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Lee Jun-ho","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Son Min-seok","avatar":""},{"name":"Jang Won-hyung","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Lee Hyun-kyun","avatar":""},{"name":"Lee Hwa-Jung","avatar":""},{"name":"Lee Tae-hyeong","avatar":""},{"name":"Yoon Don-sun","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Enes Kaya","avatar":""},{"name":"Park Chung-hwan","avatar":""},{"name":"Kang Jun-seok","avatar":""},{"name":"Sim","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
