INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-ngu-lam-3-sieu-quay-las-vegas', 'Ba Chàng Ngự Lâm 3: Siêu Quậy Las Vegas', 'The Hangover Part III', 'https://phimimg.com/upload/vod/20231019-1/9c8742394486b7959c0b430ec4673610.jpg', 'https://phimimg.com/upload/vod/20231019-1/6fe1ea55910827e142a6bb736fdd2220.jpg', '<p>Cuộc hành trình đầy tiếng cười nhưng cũng gay cấn không kém của bộ ba thân thiết bao gồm nha sĩ Stu (Ed Helms), chàng giáo viên điển trai (Bradley Cooper) Phil và chàng béo ngốc nghếch hay gây chuyện Alan (Zach Galifianakis) sẽ được tiếp tục. Bối cảnh câu chuyện diễn ra ở Las Vegas – thành phố được mệnh danh dành cho những trò vui bất tận và Tijuana (Mexico). Khác với mọi khi, lần này sẽ không có đám cưới, cũng chẳng có tiệc độc thân, nhưng những chuyện rắc rối vẫn có thể xảy đến chứ? Và khi “đàn sói” lên đường thì chắc chắn là có chuyện chẳng lành.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Sasha Barrese","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Sondra Currie","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"Oliver Cooper","avatar":""},{"name":"Mike Vallely","avatar":""},{"name":"Grant Holmquist","avatar":""},{"name":"Osca","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
