INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sat-3', 'Người Sắt 3', 'Iron Man 3', 'https://phimimg.com/upload/vod/20231019-1/7e1f85a6b0c9f5c07afd7ad18d41a424.jpg', 'https://phimimg.com/upload/vod/20231019-1/6a2500b20b990f7c896c924a93c4e804.jpg', '<p>Từ sau những sự kiện và những trận chiến đầy ám ảnh trong The Avengers, Tony Stark quay về ở ẩn trong căn biệt thự sang trọng của mình, tạm thời chờ đợi trong tư cách một tỷ phú giàu có được yêu mến và gác danh phận siêu anh hùng sang một bên.&nbsp; Tuy nhiên, những hiểm họa mới lại tiếp tục xuất hiện dưới bóng ma bao trùm của một quái nhân, đồng thời cũng là một thiên tài về công nghệ - The Mandarin. Người bạn thân trong lực lượng quân đội Hoa Kỳ của Tony - James Rhodes cần tới sự giúp đỡ của anh và những bộ giáp siêu việt.&nbsp; Mọi chuyện không hề dễ dàng như Tony và James tưởng tượng: dưới sức mạnh thần bí của mười chiếc nhẫn vũ trụ, The Mandarin đã đánh bại &quot;Người Sắt&quot;, đồng thời khiến siêu anh hùng - tỷ phú trở thành kẻ mất trí nhớ...</p>', 'Full', 1, 'single', 'completed', 12, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Stephanie Szostak","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Miguel Ferrer","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Wang Xueqi","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Matthew Sterling Nye","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822