INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-tien-kieu-my', 'Săn Tiền Kiểu Mỹ', 'American Hustle', 'https://phimimg.com/upload/vod/20231021-1/e6f273ca7fca469f90e1efb66a6ce8ae.jpg', 'https://phimimg.com/upload/vod/20231021-1/85c7c16dfc35d3a7f809d039a185fb79.jpg', '<p>Rosenfeld, là một tay lừa đảo thiên tài chuyên thực hiện các phi vụ có liên quan đến những tác phẩm nghệ thuật bị đánh cắp. Chính &quot;tài năng&quot; của hắn đã làm cho Richie DiMaso - một đặc vụ FBI phải chú ý. Irving và cô nhân tình Sydney của hắn buộc lòng phải cấu kết với tay FBI lộng quyền đó, bước vào thế giới của những tay trùm chứng khoán và xã hội đen khác nhằm ra tay triệt tiêu những thế lực xấu. Bên cạnh câu chuyện của những kẻ âm thầm đó là một câu chuyện khác gắn kết và đan xen về ngài thị trưởng Carmine Polito, người luôn cố gắng hỗ trợ cộng đồng của mình chống chọi với cuộc khủng hoảng kinh tế và những biến động của thời đại.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Louis C.K.","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Elisabeth Röhm","avatar":""},{"name":"Paul Herman","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Matthew Russell","avatar":""},{"name":"Thomas Matthews","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Anthony Ze","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f69