INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-to-xac-2', 'Những Đứa Trẻ To Xác 2', 'Grown Ups 2', 'https://phimimg.com/upload/vod/20231018-1/5e6f602ce1286693b5b692efd93f42cb.jpg', 'https://phimimg.com/upload/vod/20231018-1/ed7f5039c9dab6d548b05d50c6536a4b.jpg', '<p>Lenny đã chuyển gia đình trở lại thị trấn nhỏ nơi anh và bạn bè lớn lên. Khoảng thời gian này, những người trưởng thành là những người học các bài học từ những đứa trẻ của họ trong một ngày nổi tiếng là đầy bất ngờ — ngày cuối cùng của năm học.</p>', 'Full', 1, 'single', 'completed', 11, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"David Spade","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Colin Quinn","avatar":""},{"name":"Tim Meadows","avatar":""},{"name":"Shaquille O''Neal","avatar":""},{"name":"Jon Lovitz","avatar":""},{"name":"Georgia Engel","avatar":""},{"name":"Alexander Ludwig","avatar":""},{"name":"Peter Dante","avatar":""},{"name":"Oliver Hudson","avatar":""},{"name":"All","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
