INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-cuong-dam-phan-2', 'Người Đàn Bà Cuồng Dâm: Phần 2', 'Nymphomaniac: Vol. II', 'https://phimimg.com/upload/vod/20231018-1/6a0e62c3b4f4ff72557d3736a599c2b2.jpg', 'https://phimimg.com/upload/vod/20231018-1/f56f95e89ff862c463ed06a96d8ba221.jpg', '<p>Người Đàn Bà Cuồng Dâm 2 tiếp tục kể về cuộc đời của Joe. Joe sống với Jerôme và Marcel (con trai của họ) trong bình yên, cô mất cảm hứng với tình dục. Joe đi tìm sự điên loạn, trụy lạc và bạo dâm mong cảm hứng tình dục quay trở lại với mình. Jerôme dắt Marcel bỏ đi và đưa con trai mình đến làm con nuối của 1 gia đình khác. Sau này, Joe được gửi đến bác sĩ phụ khoa của cô để điều trị, nhưng cô không thừa nhận rằng cô đang nghiện tình dục. Trong khi đó Seligman nói với Joe rằng ông vẫn còn “zin” và giúp cô hiểu hành động của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2013, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Charlotte Gainsbourg","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Jean-Marc Barr","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Mia Goth","avatar":""},{"name":"Michaël Pas","avatar":""},{"name":"Shanti Roney","avatar":""},{"name":"Kate Ashfield","avatar":""},{"name":"Sophie Kennedy Clark","avatar":""},{"name":"Lien Van De Kelder","avatar":""},{"name":"Laura Christensen","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Chr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324463);
