INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phim-kinh-di-hai-my-5', 'Phim Kinh Dị Hài Mỹ 5', 'Scary Movie 5', 'https://phimimg.com/upload/vod/20231018-1/f787692c97e1a0fdde00fc4592b1aae0.jpg', 'https://phimimg.com/upload/vod/20231018-1/ae4eff9ec25564bd493dab3575f57d8e.jpg', '<p>Phim Phim Kinh Dị 5: Đây là phần mới nhất của loạt phim kinh dị, hài cùng tên. Trong phần 5, khán giả tiếp tục được xem những tình huống vui nhộn và hồi hộp được làm nhái từ nhiều bộ phim quen thuộc khác.</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Tisdale","avatar":""},{"name":"Simon Rex","avatar":""},{"name":"Gracie Whitton","avatar":""},{"name":"Ava Kolker","avatar":""},{"name":"Heather Locklear","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Josh Robert Thompson","avatar":""},{"name":"Darrell Hammond","avatar":""},{"name":"Marisa Saks","avatar":""},{"name":"Dylan Morris","avatar":""},{"name":"Ryan Morris","avatar":""},{"name":"Lidia Porto","avatar":""},{"name":"Snoop Dogg","avatar":""},{"name":"Mac Miller","avatar":""},{"name":"Erica Ash","avatar":""},{"name":"J.P. Manoux","avatar":""},{"name":"Marianne Hammock","avatar":""},{"name":"Terry Cre","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
