INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-thu-thach-5', 'Đương Đầu Thử Thách 5', 'A Good Day to Die Hard', 'https://phimimg.com/upload/vod/20231018-1/81d676ae219ffa971919a8b3037e6834.jpg', 'https://phimimg.com/upload/vod/20231018-1/aad9d4d82d35776c798e93cab08f8439.jpg', '<p>Tiếp nối thành công từ những phần trước, Die Hard quay trở lại với bối cảnh ở Moscow - Nga. Cha con thám tử McClane được hội ngộ sau nhiều năm xa cách nhưng lại trong một hoàn cảnh hết sức éo le. Hai cha con họ phải gác bỏ những bất đồng, sát cánh chiến đấu cùng nhau để tồn tại.</p>', 'Full', 1, 'single', 'completed', 13, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Sebastian Koch","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Yuliya Snigir","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Radivoje Bukvić","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Sergey Kolesnikov","avatar":""},{"name":"Roman Luknár","avatar":""},{"name":"Zolee Ganxsta","avatar":""},{"name":"Péter Takátsy","avatar":""},{"name":"Pasha D. Lychnikoff","avatar":""},{"name":"Megalyn Echikunwoke","avatar":""},{"name":"Melissa Tang","avatar":""},{"name":"Attila","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
