INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('teo-em', 'Tèo Em', 'Little Teo', 'https://phimimg.com/upload/vod/20231012-1/91c7dd1bb1c2b3d5f231749a6bb6c4d9.jpg', 'https://phimimg.com/upload/vod/20231012-1/ab109fe7ac8d52644f2970cc54f2939e.jpg', '<p>Bộ phim hài đường phố không khuyến khích khán giả dưới 16 tuổi kể về Ti Anh (Johnny Trí Nguyễn thủ vai) và Tèo Em (Thái Hoà thủ vai) – hai anh em cùng cha khác mẹ với tính cách trái ngược nhau. Phim kể về chuyến phiêu lưu của họ khi đến thị trấn Sa Đéc để cứu vãn mối tình của Ti Anh.</p>', 'Full', 1, 'single', 'completed', 28, 2013, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Johnny Nguyen","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Ngọc Diệp","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"YaYa Trương Nhi","avatar":""},{"name":"Ninh Dương Lan Ngọc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
