INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-giay-got-nhon', 'Âm Mưu Giày Gót Nhọn', 'How to Fight in Six Inch Heels', 'https://phimimg.com/upload/vod/20231011-1/8380d0f6cd27e6e3dcabc84dbb34a54b.jpg', 'https://phimimg.com/upload/vod/20231011-1/507ee5b98275b94dae15b1ee3960f3cf.jpg', '<p>Anne là cô gái có tài năng thiết kế thời trang, đang có cuộc sống hạnh phúc tại New York, cô có sự nghiệp ổn định và được chồng sắp cưới yêu thương hết mực. Sau này Kiệt - chồng sắp cưới của Anne phải đi công tác ở Việt Nam. Trong lúc chat bằng Skype với Kiệt, Anne phát hiện ra trong nhà Kiệt có đôi giày phụ nữ. Anne nghi ngờ Kiệt ngoại tình và bí mật về Việt Nam điều tra việc này.</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kathy Uyen","avatar":""},{"name":"Petey Majik Nguyễn","avatar":""},{"name":"Don Nguyễn","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"YaYa Trương Nhi","avatar":""},{"name":"Trương Tri Trúc Diễm","avatar":""},{"name":"Phương Mai","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Sigmund Watkins","avatar":""},{"name":"Gigi Velicitat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324463);
