INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-trinh-tham', 'Cặp Đôi Trinh Thám', 'Conspirators', 'https://phimimg.com/upload/vod/20231006-1/707b74f2a56e58171cb5d9772526a957.jpg', 'https://phimimg.com/upload/vod/20231006-1/749d1ee4ee3ba7f28048eaff58c24f3a.jpg', '<p>&quot;Chan Tan (của Aaron Kwok), một thám tử tư ở Thái Lan, đã tới Malaysia lần theo manh mối trong một bức ảnh. Ở đó, anh ta tìm kiếm một người đàn ông tên Chai (của Chan Koon Tai), người có thể giúp tiết lộ sự thật đằng sau vụ sát hại cha mẹ anh 30 năm trước. Con gái nuôi Zi-wei của Chai (của Jiang Yi Yan) là một đứa trẻ mồ côi gốc Trung Quốc. Dưới sự hướng dẫn của Zi-wei, Chan cuối cùng đã tìm thấy Chai. Nhưng Chai cho biết người đàn ông trong ảnh, Pang, một kẻ buôn ma túy Chan đã chết cách đây khá lâu. Trong lúc đó, Chan được tin nhà mình bị đột nhập, Chan vội vã trở về Thái Lan. Trở về nhà, Chan tìm thấy một ngăn bí mật dưới gầm giường nhưng đã bị lục soát. Anh nghi ngờ thứ từng được cất giấu ở đó. có thể liên quan đến cái chết của cha mẹ anh. Anh không thể làm gì khác ngoài việc tìm kiếm sự giúp đỡ từ một thám tử tư Malaysia. Chan đã tìm thấy Zheng Fong-hei (của Nick Cheung), một thám tử người Malaysia sinh ra ở Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 26, 2013, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Jiang Yiyan","avatar":""},{"name":"Leon Lee","avatar":""},{"name":"Chen Kuan-tai","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Terence Tsui","avatar":""},{"name":"Wong Chun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"