INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-tro-xa-hoi-den', 'Học Trò Xã Hội Đen', 'My Paparotti', 'https://phimimg.com/upload/vod/20230929-1/ef38eef1c7d25474170ebfbc307937a5.jpg', 'https://phimimg.com/upload/vod/20230929-1/21652d62319dc6254a739cb0789da550.jpg', '<p>Truyện phim kể về Jang-ho – chàng nam sinh trung học thiên tài, cũng là “hoàng tử” của băng nhóm du côn luôn mơ trở thành một danh ca nổi tiếng. Sang-jin, thầy giáo thanh nhạc địa phương cũng là một ca sĩ hết thời đã tìm cách giúp đỡ cậu chàng đạt được ước mơ dù cho nhiều rắc rối đã xảy ra khi anh phải chỉ dẫn cậu học trò “nguy hiểm” này.</p>', 'Full', 1, 'single', 'completed', 19, 2013, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Han Suk-kyu","avatar":""},{"name":"Kang So-ra","avatar":""},{"name":"Lee Jae-yong","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Kim Ji-seok","avatar":""},{"name":"Lee Sang-hun","avatar":""},{"name":"Yoon Yeong-gyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324463);
