INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-quay-duc-vong', 'Vòng Quay Dục Vọng', 'Deseo', 'https://phimimg.com/upload/vod/20230925-1/9ea2c3ae409ba45e92bdcb0e4276e275.jpg', 'https://phimimg.com/upload/vod/20230925-1/21a44ab0732dcf33e6249295dd2b47c9.jpg', '<p>Tám truyện ngắn về sự quyến rũ và những cuộc gặp gỡ bất chính giữa những người yêu nhau, đầy hài hước và khêu gợi, sử dụng cấu trúc hình tròn nằm trong bầu không khí quốc tế của một thành phố thuộc địa của Mexico.</p>', 'Full', 1, 'single', 'completed', 24, 2013, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Edith González","avatar":""},{"name":"Christian Bach","avatar":""},{"name":"Paola Nuñez","avatar":""},{"name":"Paulina Gaitán","avatar":""},{"name":"Leonor Varela","avatar":""},{"name":"Lila Downs","avatar":""},{"name":"Pedro Damián","avatar":""},{"name":"Gerardo Taracena","avatar":""},{"name":"Ari Borovoy","avatar":""},{"name":"Geraldine Zinat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324463);
