INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-doi-cho-lon', 'Bụi Đời Chợ Lớn', 'Chinatown', 'https://phimimg.com/upload/vod/20230923-1/a734853ebf2caf5da9d0753afb8a06d3.jpg', 'https://phimimg.com/upload/vod/20230923-1/5934bbd5630a98db49867efc10af4c2d.jpg', '<p>Trong thế giới ngầm tại Sài Gòn thì Chợ Lớn luôn có một vị trí cực kỳ quan trọng – có thể ví như trái tim của cả thành phố. Có được Chợ Lớn là sẽ có được cả Sài Gòn! Chính vì thế, không có gì lạ khi Chợ Lớn là nơi đáng để khao khát nhất. Máu và nước mắt đã không ngừng đổ xuống cho những cuộc tranh quyền đoạt vị đầy khốc liệt của thế giói ngầm …&nbsp; Phim xoay quanh mối quan hệ phức tạp giữa 4 nhân vật chính là Hùng Chợ Lớn (Long Điền), Tài Nhớt (Hoàng Phúc), Phong Bụi (Johnny Trí Nguyễn) và Lâm (Hà Hiền). Lâm là em trai Hùng, vì quá si mê Hương (Huỳnh Bích Phương) – người tình của Tài Nhớt nên đã đắc tội với gã đối thủ máu lạnh. Vốn đã có âm mưu chiếm lấy Chợ Lớn nên nhân cơ hội này Tài Nhớt buộc Hùng phải đối đầu với mình. Để tăng thêm phần thắng, hắn đã tìm mọi cách khiến cho Phong Bụi – một cao thủ ẩn mình mà y luôn xem như anh em phải quay trở lại giúp y đánh bại Hùng. Và cuộc chiến đã nổ ra giữa 2 nhóm Tài Nhớt – Hùng Chợ Lớn với những trận đấu sinh tử một mất một còn…</p>', 'Full', 1, 'single', 'completed', 18, 2013, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hoàng Phúc","avatar":""},{"name":"Long Điền","avatar":""},{"name":"Hà Hiền","avatar":""},{"name":"Huỳnh Bích Phương","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Johnny Nguyen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324463);
