INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-gia-dinh', 'Giải Cứu Gia Đình', 'The Contractor', 'https://phimimg.com/upload/vod/20230923-1/088cfd036fd8aa31e82835cd14710e08.jpg', 'https://phimimg.com/upload/vod/20230923-1/3adb1af6a8d903fd64fb260668036681.jpg', '<p>Elizabeth Chase đang bận sửa sang lại ngôi nhà mới của mình cùng với chồng luật sư, Paul và con gái, McKenzie. Để đảm bảo mọi việc hoàn thành trước sự kiện từ thiện mà họ tổ chức, cặp đôi đã thuê một nhà thầu, Javier, để giúp đỡ. Tuy nhiên, Elizabeth bắt đầu nghi ngờ Javier và biết rằng anh ta đã nhắm mục tiêu vào gia đình từ lâu. Giờ đây, để cứu gia đình mình, Elizabeth sẽ phải tự mình giải quyết vấn đề.</p>', 'Full', 1, 'single', 'completed', 22, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Christina Cox","avatar":""},{"name":"Brad Rowe","avatar":""},{"name":"Taylor Spreitler","avatar":""},{"name":"Arianne Zucker","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Drew Osborne","avatar":""},{"name":"Roy Lee Jones","avatar":""},{"name":"Skoti Collins","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324463);
