INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-tinh-duc', 'Nô Lệ Tình Dục', 'Sweet Whip', 'https://phimimg.com/upload/vod/20230922-1/ed66b2cd9eaeb61e5cb2e8ae505d86ec.jpg', 'https://phimimg.com/upload/vod/20230922-1/f459e0146628eb7d57af2dbe56d23256.jpg', '<p>Khi Naoko còn là học sinh năm nhất trung học, cô đã bị một người đàn ông sống cạnh nhà bắt cóc và giam cầm. Trong một tháng, cô đã phải trải qua địa ngục. Cuối cùng, cô giết chết người đàn ông và trốn thoát. Bây giờ khi đã trưởng thành, Naoko là bác sĩ chuyên điều trị vô sinh nhưng cô còn có một mặt khác. Naoko là một bậc thầy nổi tiếng trong câu lạc bộ S&amp;M.</p>', 'Full', 1, 'single', 'completed', 23, 2013, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mitsu Dan","avatar":""},{"name":"Yuki Mamiya","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Hiroko Nakajima","avatar":""},{"name":"Tsuyoshi Nakano","avatar":""},{"name":"Ito Yozaburo","avatar":""},{"name":"Hiroko Yashiki","avatar":""},{"name":"Shun Nakayama","avatar":""},{"name":"Taro Suwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324463);
