INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than', 'Thiên Thần', 'Angélique', 'https://phimimg.com/upload/vod/20230915-1/b8adc75b116be56bdb5f7c81b34b5171.jpg', 'https://phimimg.com/upload/vod/20230915-1/872590c1e4ce0724bc6efe2914d8d905.jpg', '<p>Số phận đáng kinh ngạc của Angélique: một cô gái xinh đẹp tìm thấy trong tình yêu của mình với Joffrey Peyrac sức mạnh để chống lại sự bất công và sự khuất phục trong một thế kỷ bị cản trở bởi những cuộc tranh giành quyền lực, bất bình đẳng và áp bức.</p>', 'Full', 1, 'single', 'completed', 26, 2013, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nora Arnezeder","avatar":""},{"name":"Gérard Lanvin","avatar":""},{"name":"Tomer Sisley","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Florence Coste","avatar":""},{"name":"David Kross","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Jiří Pomeje","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324463);
