INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu-bat-lua', 'Trò Chơi Sinh Tử: Bắt Lửa', 'The Hunger Games: Catching Fire', 'https://phimimg.com/upload/vod/20230912-1/29cbb2ee3c6ecd47d4f2a8853bc29d93.jpg', 'https://phimimg.com/upload/vod/20230912-1/b7de56b1971467c5a9fd38856285cdf2.jpg', '<p>The Hunger Games: Catching Fire là tập phim thứ hai trong loạt phim The Hunger Games với những sự kiện nối tiếp các diễn biến trong phần một. Chiến thắng Katniss Everdeen và Peeta Mellark tại Đấu trường sinh tử lần 74 thổi bùng lên cuộc nổi loạn tại các quận của Panem. Điều đó khiến họ trở thành mục tiêu săn đuổi của Capitol.The Hunger Games lấy bối cảnh tương lai không xa khi Bắc Mỹ bị đe dọa bởi hạn hán, hỏa hoạn, đói kém và đặt ra giả thuyết khi đó chiến tranh được thay thế bằng một trò chơi săn người. Mỗi năm, các quận cử ra đại diện tham dự cuộc đấu một mất một còn để làm trò giải khuây cho các thế lực giàu có. Trò chơi khát máu này được xây dựng như một show truyền hình thực tế truyền đi khắp nơi. ...</p>', 'Full', 1, 'single', 'completed', 36, 2013, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Lenny Kravitz","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Jeffrey Wright","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324463);
