INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cau-be-nhut-nhat-nhung-ngay-he-oi-buc', 'Nhật Ký Cậu Bé Nhút Nhát: Những Ngày Hè Oi Bức', 'Diary Of A Wimpy Kid: Dog Days', 'https://phimimg.com/uploads/movies/20260710/nhat-ky-cau-be-nhut-nhat-nhung-ngay-he-oi-buc-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/nhat-ky-cau-be-nhut-nhat-nhung-ngay-he-oi-buc-poster.webp', '<p>Bộ phim bắt đầu với chuyến đi chơi của gia đình Heffley tới hồ bơi công cộng để bắt đầu kì nghỉ hè trong khi năm học vẫn chưa kết thúc. Trong khi đó, Greg cảm thấy không thoải mái với sự náo nhiệt, đông đúc và mất vệ sinh của hồ bơi. Khi ở hồ, gia đình Heffley đã gặp lại người bạn của Rodrick, một cậu bé của rắc rối nhưng giờ đã trở thành học sinh gương mẫu sau khi tham gia Spag Union - một chương trình học khá khắt khe cho học sinh lớp 8. Vậy là, cha của Greg, Frank muốn gửi Greg vào lớp học đặc biệt này.Vào ngày cuối cùng ở trường, Greg đã cố gắng xin Holy Hills điền số điện thoại của cô ấy vào cuốn nhật kí trường học của mình. Tuy nhiên, Holly đã từ chối đưa hai số cuối. Trong khi đó, anh trai của Greg, Rodrick, ...</p>', 'Full', 1, 'single', 'completed', 68, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Gordon","avatar":""},{"name":"Robert Capron","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Peyton List","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Grayson Russell","avatar":""},{"name":"Karan Brar","avatar":""},{"name":"Melissa Roxburgh","avatar":""},{"name":"Laine MacNeil","avatar":""},{"name":"Connor Fielding","avatar":""},{"name":"Owen Fielding","avatar":""},{"name":"Philip Maurice Hayes","avatar":""},{"name":"Terence Kelly","avatar":""},{"name":"Bronwen Smith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Diary of a Wimpy Kid 3: Dog Days","Diario di una schiappa 3 - Vida da cani","Diário de um Banana 3 - Dias de Cão","El diario de Greg 3: Días de perros","Дневникът на един дръндьо: Кучешки дни","グレッグのダメ日記 3","יומנו של חנון 3: קיץ קטלני","葛瑞的囧日記3","윔피 키드 3: 도그 데이즈","Diary of a Wimpy Kid: Dog Days"]', 1784690324463);
