INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-den', 'Đỏ Đen', 'Luck', 'https://phimimg.com/upload/vod/20260630-1/f4d880dceafe937b3a4ea33328641ad5.jpg', 'https://phimimg.com/upload/vod/20260630-1/dff5360193664ae8e5f3c8940cb9a545.jpg', '<p>Một bộ phim chính kịch lấy bối cảnh trong thế giới đua ngựa đầy kịch tính, tập trung khai thác cuộc đời của những chủ sở hữu, nài ngựa, huấn luyện viên và những tay cá cược — những con người mà số phận đều gắn chặt vào cùng một đường đua.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 35, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dustin Hoffman","avatar":""},{"name":"Dennis Farina","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Jill Hennessy","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Jason Gedrick","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Gary L. Stevens","avatar":""},{"name":"Tom Payne","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Weronika Rosati","avatar":""},{"name":"Alan Rosenberg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["לאק","Luck"]', 1784690324463);
