INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-tau-khong-gian-cuoc-xam-lang-chien-doi-thien-ha-xam-luoc', 'Chiến Binh Tàu Không Gian: Cuộc Xâm Lăng (Chiến Đội Thiên Hà: Xâm Lược)', 'Starship Troopers: Invasion', 'https://phimimg.com/upload/vod/20260629-1/8ae745c6c90eb1be568958d5175f23ae.jpg', 'https://phimimg.com/upload/vod/20260629-1/e35d2923d78110d37571070643feeebf.jpg', '<p>Binh lính từ hai tàu vũ trụ đã hợp lực để tiêu diệt một cuộc tấn công quy mô lớn của loài bọ khổng lồ tại một tiền đồn của Liên bang. Tuy nhiên, trước khi sứ mệnh hoàn thành và những người sống sót kịp sơ tán, một con tàu bất ngờ rời đi và mất liên lạc một cách bí ẩn. Những binh lính dày dạn kinh nghiệm còn lại phải chạy đua với thời gian để giải cứu, để rồi bàng hoàng phát hiện ra rằng mối đe dọa từ loài bọ hung tợn này đang chuẩn bị ập xuống ngay chính quê hương của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 30, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Luci Christian","avatar":""},{"name":"David Anthony Matranga","avatar":""},{"name":"Justin Doran","avatar":""},{"name":"David Wald","avatar":""},{"name":"Andrew Love","avatar":""},{"name":"Leraldo Anzaldua","avatar":""},{"name":"Sam Roman","avatar":""},{"name":"Emily Neves","avatar":""},{"name":"Melissa Davis","avatar":""},{"name":"Kalob Martinez","avatar":""},{"name":"Chris Patton","avatar":""},{"name":"Adam Gibbs","avatar":""},{"name":"Jovan Jackson","avatar":""},{"name":"Corey Hartzog","avatar":""},{"name":"Jessie James Grelle","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Shelley Cale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Звездный десант Вторжение","Tropas Estelares - Invasão","Starship Troopers: Invasión","星河战队：入侵","Starship Troopers 4 - Invasion","Starship Troopers - Invasion","Starship Troopers : Invasion","スターシップ・トゥルーパーズ インベイジョン","스타쉽 트루퍼스: 인베이전","Csillagközi invázió: Invázió","Invasión","Starship Troopers - L''invasione","Brigadas del Espacio 4","Starship Troopers 4: Invasion","星河戰隊4","Starship Troopers: Invasion"]', 1784690324463);
