INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-binh-tau-khong-gian-cuoc-xam-lang-chien-doi-thien-ha-xam-luoc', 'Chiến Binh Tàu Không Gian: Cuộc Xâm Lăng (Chiến Đội Thiên Hà: Xâm Lược)', 'Starship Troopers: Invasion', 'chiến binh tàu không gian: cuộc xâm lăng (chiến đội thiên hà: xâm lược) starship troopers: invasion luci christian david anthony matranga justin doran david wald andrew love leraldo anzaldua sam roman emily neves melissa davis kalob martinez chris patton adam gibbs jovan jackson corey hartzog jessie james grelle karl glusman shelley cale звездный десант вторжение tropas estelares - invasão starship troopers: invasión 星河战队：入侵 starship troopers 4 - invasion starship troopers - invasion starship troopers : invasion スターシップ・トゥルーパーズ インベイジョン 스타쉽 트루퍼스: 인베이전 csillagközi invázió: invázió invasión starship troopers - l''invasione brigadas del espacio 4 starship troopers 4: invasion 星河戰隊4 starship troopers: invasion', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-ma-thuat-phan-1', 'Vương Quốc Ma Thuật (Phần 1)', 'Magi (Season 1) (The Labyrinth Of Magic)', 'https://phimimg.com/upload/vod/20260111-1/a71642f227da46c19ff1d4fd77f25a5a.jpg', 'https://phimimg.com/upload/vod/20260111-1/d526855ddade086247a0f26fb2fc9557.jpg', '<p>Câu chuyện là một dòng chảy của số phận và cuộc chiến bảo vệ thế giới đi theo con đường lẽ phải.Aladin, nhân vật chính của bộ phim, đã đặt ra mục tiêu khám phá thế giới sau khi gần hết quãng đời mình bị mắc kẹt trong một căn phòng. Người bạn thân nhất của cậu ta là cây sáo và linh hồn của lửa mang tênUgo.Chẳng bao lâu sau, Aladin phát hiện ra mình là một Magi, một nhà ma thuật có quyền chọn vua, và cậu ấy được sinh ra để lựa chọn các vị vua, những người sẽ đi theo con đường chân chính, chiến đấu chống lại những người muốn tiêu diệt số phận. Cùng đồng hành với Aladin trên chuyến phiêu lưu ấy là những người bạn đến từ thế giới Ngàn Lẻ Một Đêm - Ali 33, Sinbad cùng chiến đấu với nhau để giữ sự cân bằng cho thế giới.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 21, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaori Ishihara","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Daisuke Ono","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35