INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gio-phieu-luu-phan-4', 'Giờ Phiêu Lưu (Phần 4)', 'Adventure Time (Season 4)', 'giờ phiêu lưu (phần 4) adventure time (season 4) jeremy shada john dimaggio tom kenny hynden walch olivia olson niki yang pendleton ward polly lou livingston hora de aventura com finn e jake hora de aventura 探险活宝 abenteuerzeit mit finn und jake eventyrtid hora de aventuras время приключений с финном и джейком час пригод разом із фіном та джейком adventure time with finn & jake adventure time: stakes adventure time with finn jake adventure time', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-giau-nang-ngheo', 'Chàng Giàu, Nàng Nghèo', 'Rich Man, Poor Woman', 'https://phimimg.com/upload/vod/20260611-1/62b11f710eaaa00a4df2a73882c16673.jpg', 'https://phimimg.com/upload/vod/20260611-1/d2928cbd9d8e6d311a3dba432d0eef03.jpg', '<p>Hyuga bắt đầu sự nghiệp từ một trang web do anh tự mày mò xây dựng vì đam mê. Về sau, anh phát triển nó thành một công ty công nghệ thông tin lớn mạnh và trở thành một tỷ phú trẻ tuổi. Ngược lại, Makoto lại gặp phải vô vàn khó khăn và lận đận trên con đường tìm kiếm việc làm. Bản tính của hai người hoàn toàn trái ngược nhau. Dù liên tục xảy ra xung đột ngay từ lần đầu gặp gỡ, họ lại dần bị thu hút bởi đối phương và cùng nhau vượt qua rất nhiều sóng gió trong sự nghiệp lẫn cuộc sống.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 24, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Arata Iura","avatar":""},{"name":"Satomi Ishihara","avatar":""},{"name":"Saki Aibu","avatar":""},{"name":"Yōsuke Asari","avatar":""},{"name":"Yasuhi Nakamura","avatar":""},{"name":"Aiku Maikawa","avatar":""},{"name":"Kiyohiko Ueki","avatar":""},{"name":"Daishi Shikanai","avatar":""},{"name":"Shiro Sano","avatar":""},{"name":"Masumi Nomura","avatar":""},{"name":"Yuki Furukawa","avatar":""},{"name":"Tomomi Maruyama","avatar":""},{"name":"Kiyohiko Ueki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["有钱男与贫穷女","多金社长小资女","Ricchi Pua","Ricchi Man, Pua Uuman","Ricchiman Puauman"