INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-9', 'Chuyện Văn Phòng (Phần 9)', 'The Office (Season 9)', 'https://phimimg.com/upload/vod/20260604-1/d4c751e0c4a3a045e7eb5485702855c4.jpg', 'https://phimimg.com/upload/vod/20260604-1/a3d4005d704c66ceaf3102c7f7ce52e6.jpg', '<p>Trong Phần 9, Andy tìm thấy tiếng gọi thực sự của mình trong làng giải trí, Jim đạt được công việc mơ ước, Erin đấu tranh với tình yêu và cuộc hôn nhân của Angela không như mong đợi.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 26, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324463);
