INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-toi-southland-phan-4', 'Góc Tối Southland (Phần 4)', 'Southland (Season 4)', 'https://phimimg.com/upload/vod/20250701-1/dc622b0b3136ee62d434bdc2909570b0.jpg', 'https://phimimg.com/upload/vod/20250701-1/4527875d4def7a91b05aaf936ed2d950.jpg', '<p>Một cái nhìn chân thực và thô mộc về thế giới tội phạm ở Los Angeles, bộ phim đi sâu vào cuộc sống của cảnh sát, tội phạm, nạn nhân và gia đình của họ. Câu chuyện xoay quanh bốn nhân vật chính: Cảnh sát John Cooper, một cựu binh dày dạn kinh nghiệm, người phải chứng minh năng lực một lần nữa sau ca phẫu thuật hồi phục; Cảnh sát Ben Sherman, người vẫn còn nhiều điều phải học hỏi sau khi vừa hoàn thành chương trình đào tạo; Thám tử Lydia Adams, người có khối lượng công việc không ngừng nghỉ, và các vụ án ngày càng gần gũi với cuộc sống cá nhân; Sammy Bryant, một cựu thám tử đã quyết định quay lại làm cảnh sát thường phục sau cái chết bi thảm của đồng nghiệp thân thiết.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben McKenzie","avatar":""},{"name":"Michael Cudlitz","avatar":""},{"name":"Regina King","avatar":""},{"name":"Shawn Hatosy","avatar":""},{"name":"C. Thomas Howell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Southland: Cidade do crime","SouthLand","Саутленд","Южная Территория","Southland"]', 1784690324463);
