INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-hawaii-phan-3', 'Đội Đặc Nhiệm Hawaii (Phần 3)', 'Hawaii Five-0 (Season 3)', 'https://phimimg.com/upload/vod/20260604-1/83f58942e59081ab258f037c1da4afdb.jpg', 'https://phimimg.com/upload/vod/20260604-1/55451758f81fa0dcc097863805ef3168.jpg', '<p>Steve McGarrett trở về quê nhà ở Oahu nhằm truy tìm kẻ đã sát hại cha mình. Tại đây, Thống đốc đã trao cho anh cơ hội đứng đầu một đội đặc nhiệm của riêng mình (Đội Five-0). Sát cánh cùng Steve trong biệt đội này là các thành viên Chin Ho Kelly, Danny &quot;Danno&quot; Williams và Kono Kalakaua.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 25, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alex O''Loughlin","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"Ian Anthony Dale","avatar":""},{"name":"Meaghan Rath","avatar":""},{"name":"Beulah Koale","avatar":""},{"name":"Dennis Chun","avatar":""},{"name":"Kimee Balmilero","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"Taylor Wily","avatar":""},{"name":"Katrina Law","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Havaí 5.0","Havaí Cinco-Zero","夏威夷特勤组","天堂执法者","Hawái 5.0","Χαβάη 5-0","Χαβάη Πέντε-0","הוואי חמש-אפס","הוואי חמש-0","הוואי 5-אפס","ハワイファイブオー","Hawái Cinco-0","Гавайи 5-0","Hawaii Five-O","Hawaii 5-0","Hawaii 5.0","Hawaii Five-0"]', 1784690324463);
