INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-hai-o-racine', 'Thứ Hai Ở Racine', 'Mondays at Racine', 'https://phimimg.com/upload/vod/20260531-1/c6b717e96201a963cb77b8c5227afbe0.jpg', 'https://phimimg.com/upload/vod/20260531-1/4ba352c56eb0c2ca6f4c14d17e6716dd.jpg', '<p>Được truyền cảm hứng từ mẹ mình, một bệnh nhân ung thư, hai chị em là chủ của một tiệm làm đẹp tại New York đã phục vụ miễn phí cho các bệnh nhân ung thư một lần mỗi tháng vào thứ Hai.</p>', 'Full', 1, 'single', 'completed', 23, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rachel Delmolfetto","avatar":""},{"name":"Linda Hart","avatar":""},{"name":"Cambria Russell","avatar":""},{"name":"Cynthia Sansone","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Mondays at Racine"]', 1784690324463);
