INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-du-phan-9', 'Danh Dự (Phần 9)', 'One Tree Hill (Season 9)', 'https://phimimg.com/upload/vod/20260527-1/038500001b1bd1309d7a08855ac4a342.jpg', 'https://phimimg.com/upload/vod/20260527-1/3ea746dc41e50447349a7e04a57a6882.jpg', '<p>Tại thị trấn Tree Hill thuộc bang Bắc Carolina, hai người anh em cùng cha khác mẹ chẳng có điểm gì chung ngoài một họ Scott. Lucas – một chàng trai sống nội tâm, thuộc tầng lớp lao động nghèo – là một thiên tài bóng rổ đường phố, nhưng tài năng của cậu chỉ được công nhận bởi nhóm bạn thân tại sân bóng bên bờ sông. Ngược lại, Nathan – chàng công tử nhà giàu, nổi tiếng và ngậm thìa vàng từ nhỏ – lại say sưa trong sự sùng bái của cả thị trấn với tư cách là ngôi sao sáng giá của đội bóng rổ trung học. Cả hai chàng trai đều là con của cựu cầu thủ bóng rổ đại học Dan Scott. Sự lựa chọn ruồng bỏ Lucas cùng người mẹ Karen từ nhiều năm trước của ông ta sẽ trở thành nỗi ám ảnh dai dẳng suốt cuộc đời, ngay cả trong cuộc sống hiện tại bên người vợ Deb và cậu con trai Nathan.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 22, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Lafferty","avatar":""},{"name":"Bethany Joy Lenz","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Robert Buckley","avatar":""},{"name":"Shantel VanSanten","avatar":""},{"name":"Jackson Brundage","avatar":""},{"name":"Lee Norris","avatar":""},{"name":"Lisa Goldstein Kirsch","avatar":""},{"name":"Stephen Colletti","avatar":""},{"name":"Tyler Hilton","avatar":""},{"name":"Paul Johansson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Самотно дърво на хълма","One Tree Hill: Lances da Vida","青山镇","独木岭","Filoi gia panta","Tree Hill","Pogoda na milosc","Ruleta destinului","Tri Hil","Пагорб одного дерева","Ravens","One Tree Hill"]', 1784690324463);
