INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-ngoc', 'Ba Chàng Ngốc', 'The Three Stooges', 'https://phimimg.com/upload/vod/20260522-1/5d5b8f7ba865cb3246f18b2816e426c0.jpg', 'https://phimimg.com/upload/vod/20260522-1/47ed2788124067ed3bc911f27e261b0e.jpg', '<p>Bị bỏ lại trên bậc cửa của một trại trẻ mồ côi do các nữ tu quản lý, ba đứa trẻ sơ sinh ngốc nghếch lớn lên thành những người lao công thích chọc tay và hay kêu &quot;nyuk-nyuk&quot; tên là Larry, Curly và Moe. Khi biết rằng những khó khăn tài chính sắp buộc nơi duy nhất họ từng gọi là nhà phải đóng cửa, bộ ba quyết tâm gây quỹ 830.000 đô la trong một tháng. Lần đầu tiên bước ra thế giới, ba người ngây thơ vụng về bị cuốn vào một âm mưu giết người và trở nên nổi tiếng trên một chương trình thực tế truyền hình.</p>', 'Full', 1, 'single', 'completed', 21, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sean Hayes","avatar":""},{"name":"Will Sasso","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"Craig Bierko","avatar":""},{"name":"Stephen Collins","avatar":""},{"name":"Larry David","avatar":""},{"name":"Kirby Heyborne","avatar":""},{"name":"Carly Craig","avatar":""},{"name":"Kate Upton","avatar":""},{"name":"Marianne Leone Cooper","avatar":""},{"name":"Brian Doyle-Murray","avatar":""},{"name":"Mike Sorrentino","avatar":""},{"name":"Snooki","avatar":""},{"name":"JWoww","avatar":""},{"name":"Ronni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["שלושת הליצנים","The Three Stooges: The Movie","바보 삼총사","바보삼총사","The Three Stooges"]', 1784690324463);
