INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-heck-phan-4', 'Gia đình Heck (Phần 4)', 'The Middle (Season 4)', 'https://phimimg.com/upload/vod/20260516-1/3ba1e6c1a15ba624e3ba54df00a5b99b.jpg', 'https://phimimg.com/upload/vod/20260516-1/4ece3a5f3fb8a52106889dcbdea8f9a2.jpg', '<p>Trong khi một diễn biến bất ngờ có thể buộc Frankie phải xem xét lại sự nghiệp của mình tại đại lý ô tô, Mike đã đặt mục tiêu đảm bảo rằng Axl bằng cách nào đó sẽ giành được học bổng thể thao vào đại học năm sau. Trong khi đó, Sue không chỉ đang xoay xở ở trường trung học mà còn muốn tự mình lái xe trên những con đường ở Indiana bằng cách lấy bằng lái. Chẳng có gì lạ khi cậu con trai út Brick lúc nào cũng cắm đầu vào sách vở!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patricia Heaton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Eden Sher","avatar":""},{"name":"Atticus Shaffer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["左右不逢源","中产家庭","中之道","Anyám borogass","Családom és egyéb emberfajták","ザ・ミドル ～中流家族のフツーの幸せ～","คุณแม่สามัญประจำบ้าน","The Middle"]', 1784690324463);
