INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-cho-thue-meo', 'Dịch vụ cho thuê mèo', 'Rent-a-Cat', 'https://phimimg.com/upload/vod/20260502-1/01219b3d25d3bfdc73ac691d8259f3e2.jpg', 'https://phimimg.com/upload/vod/20260502-1/ab56388a4d1dc088ff90ccf4095b90c7.jpg', '<p>Rent-a-Cat kể về cuộc sống thường ngày của một cô gái độc thân Sayoko và gia đình duy nhất của cô là những chú mèo. Cô mở dịch vụ thuê mèo cho những người cô đơn và có vấn đề trong cuộc sống vì cô tin rằng loài mèo sẽ có thể lấp đầy khoảng trống trong tâm hồn họ. Dù vậy, ta dần nhận ra rằng Sayoko cũng đối mặt với sự cô đơn của chính mình khi cô cũng khao khát những mối quan hệ với con người bên cạnh loài mèo.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mikako Ichikawa","avatar":""},{"name":"Reiko Kusamura","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Maho Yamada","avatar":""},{"name":"Kei Tanaka","avatar":""},{"name":"Katsuya Kobayashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rentaneko","고양이를 빌려드립니다","吉猫出租","Rent-a-Cat","レンタネコ"]', 1784690324463);
