INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-co-chay', 'Mùi cỏ cháy', 'The Scent of Burning Grass', 'https://phimimg.com/upload/vod/20250401-1/4f45ae9188b5d8528b2f531a6434eec6.jpg', 'https://phimimg.com/upload/vod/20250401-1/9572a5005594738f465fe9ec1da18722.jpg', '<p>&quot;Mùi cỏ cháy&quot; lấy bối cảnh chính là sự kiện Mùa hè đỏ lửa 1972 với trận chiến tại Thành cổ Quảng Trị. Nhân vật chính trong phim là bốn sinh viên Trường Đại học Tổng hợp Hà Nội là: Hoàng, Thành, Thăng và Long theo lệnh tổng động viên lên đường nhập ngũ năm 1971, được huấn luyện tốc hành và sau cùng đã tham gia chiến đấu tại Thành cổ Quảng Trị năm 1972. Tại đây, Thành, Thăng và Long đã hi sinh còn Hoàng thì may mắn sống sót trở về. Bộ phim được kể lại từ ký ức của Hoàng, khi ông thăm lại chiến trường xưa.</p>', 'Full', 1, 'single', 'completed', 24, 2012, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Nguyễn Năng Tùng","avatar":""},{"name":"Nguyễn Hữu Mười","avatar":""},{"name":"Lê Văn Thơm","avatar":""},{"name":"To Tuan Dang","avatar":""},{"name":"Thanh Sơn","avatar":""},{"name":"Lê Chí Kiên","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Scent of Burning Grass","Mùi cỏ cháy"]', 1784690324463);
