INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-khach-hang-phan-1', 'Danh Sách Khách Hàng (Phần 1)', 'The Client List (Season 1)', 'https://phimimg.com/upload/vod/20260429-1/4b71b30c58cde759b79008ec08585b69.jpg', 'https://phimimg.com/upload/vod/20260429-1/073f9261aa3a9c7074fe59998394fae6.jpg', '<p>Riley Parks phải khéo léo duy trì sự cân bằng giữa hai cuộc đời hoàn toàn trái ngược — một bên là người mẹ đơn thân tại một thị trấn bảo thủ, luôn chật vật để lo cho gia đình; bên kia là một nữ doanh nhân nhạy bén và đầy tham vọng, làm việc cùng một nhóm phụ nữ nóng bỏng, nổi loạn và khó lường. Giữa những áp lực từ định kiến xã hội và nhu cầu mưu sinh, cô phải đối mặt với những tình huống dở khóc dở cười và cả những nguy cơ có thể làm đổ vỡ vỏ bọc hoàn hảo mà cô dày công xây dựng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"Rebecca Field","avatar":""},{"name":"Alicia Lagano","avatar":""},{"name":"Brian Hallisay","avatar":""},{"name":"Laura-Leigh","avatar":""},{"name":"Cybill Shepherd","avatar":""},{"name":"Tyler Champagne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Специални клиенти","Клиентски списък","La liste","The Client List"]', 1784690324463);
