INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-tranh-thieu-nu', 'Bức Tranh Thiếu Nữ', 'Renoir', 'https://phimimg.com/upload/vod/20260428-1/90e9f4eec92236b8ddb4555055d8b0bf.jpg', 'https://phimimg.com/upload/vod/20260428-1/04e6c93d7d297b96496f76ea3ff8b9bf.jpg', '<p>Bộ phim kể về câu chuyện bị lãng quên của Andrée Heuschling, còn được gọi là Catherine Hessling , người mẫu cuối cùng của họa sĩ trường phái ấn tượng Pierre-Auguste Renoir và là nữ diễn viên đầu tiên trong các bộ phim của con trai ông, đạo diễn phim Jean Renoir . Andrée là liên kết giữa hai nghệ sĩ nổi tiếng và được hoan nghênh rộng rãi, một người cha và con trai. Trong khi người cha đang ở giai đoạn cuối của sự nghiệp rực rỡ thì cậu con trai vẫn đang tìm kiếm chính mình, sự nghiệp vĩ đại của anh với tư cách là một trong những đạo diễn điện ảnh nổi tiếng nhất vẫn chưa bắt đầu. Đạo diễn Gilles Bourdos đã sử dụng các dịch vụ của một thợ rèn nghệ thuật bị kết án, Guy Ribes, để tạo ra và tái tạo các bức tranh Renoir trong hành động trực tiếp trên màn ảnh Lấy bối cảnh ở Riviera của Pháp vào mùa hè năm 1915, Jean Renoir - con trai của họa sĩ trường phái Ấn tượng, Pierre-Auguste - trở về nhà để dưỡng bệnh sau khi bị thương trong Thế chiến thứ nhất. Bên cạnh anh là Andrée, một phụ nữ trẻ mang đến sự trẻ trung, mê hoặc, và truyền cảm hứng cho cả hai cha con.</p>', 'Full', 1, 'single', 'completed', 20, 2012, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Michel Bouquet","avatar":""},{"name":"Christa Théret","avatar":""},{"name":"Vincent Rottiers","avatar":""},{"name":"Thomas Doret","avatar":""},{"name":"Romane Bohringer","avatar":""},{"name":"Carlo Brandt","avatar":""},{"name":"Solène Rigot","avatar":""},{"name":"Anne-Lise Heimburger","avatar":""},{"name":"Hélène Babu","avatar":""},{"name":"Stuart Seide","avatar":""},{"name":"Sylviane Goudal","avatar":""},{"name":"Michèle Gleizer","avatar":""},{"name":"Cécile Rittweger","avatar":""},{"name":"Laurent Poitrenaux","avatar":""},{"name":"Paul Spera","avatar":""},{"name":"Thierry Hanc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["印象雷諾瓦","Реноар","Ренуар","Renoir","Ρενουάρ"]', 1784690324463);
