INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buc-tranh-thieu-nu', 'Bức Tranh Thiếu Nữ', 'Renoir', 'bức tranh thiếu nữ renoir michel bouquet christa théret vincent rottiers thomas doret romane bohringer carlo brandt solène rigot anne-lise heimburger hélène babu stuart seide sylviane goudal michèle gleizer cécile rittweger laurent poitrenaux paul spera thierry hanc 印象雷諾瓦 реноар ренуар renoir ρενουάρ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-than-thien-menh-hoang-de', 'Võ Thần (Thiên Mệnh Hoàng Đế)', 'God Of War (Warrior K)', 'https://phimimg.com/upload/vod/20260415-1/b13b756f1604fe28e291097671756f4a.jpg', 'https://phimimg.com/upload/vod/20260415-1/0f5758ec10494e1596dd57209b08048f.jpg', '<p>Từ thân phận nô lệ bị chà đạp đến võ tướng làm thay đổi vận mệnh quốc gia, Kim Joon - nhân vật có thật trong lịch sử Hàn Quốc - hiện lên như một huyền thoại. Võ Thần đưa người xem trở lại triều đại Goryeo khắc nghiệt, nơi quyền lực và sinh mạng chỉ cách nhau một lằn ranh mong manh. Giữa chiến trận tàn khốc và âm mưu triều đình, một con người nhỏ bé vẫn kiên cường vươn lên, mang theo lời hứa, tình yêu và niềm tin vào chính nghĩa. Không chỉ là bản anh hùng ca đầy máu, nước mắt và khát vọng sống, bộ phim còn chạm đến cảm xúc với những mối tình sâu lắng giữa thời loạn.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 26, 2012, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Joo-hyuk","avatar":""},{"name":"Kim Ha-eun","avatar":""},{"name":"Park Sang-wook","avatar":""},{"name":"Lee Seung-hyo","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Ahn Jae-mo","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Kim Gyu-ri","avatar":""},{"name":"Park Sang-min","avatar":""},{"name":"Hong Ah-reum","avatar":""},{"name":"Cho Eun-sook","avatar":""},{"name":"Koh Soo-hee","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Jin Won","avatar":""},{"name":"Oh Young-soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Mooshin","Musin","Soldier","Military Official","무신"]', 1784690324463);
