INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-than-thien-menh-hoang-de', 'Võ Thần (Thiên Mệnh Hoàng Đế)', 'God Of War (Warrior K)', 'võ thần (thiên mệnh hoàng đế) god of war (warrior k) kim joo-hyuk kim ha-eun park sang-wook lee seung-hyo cheon ho-jin ahn jae-mo park hae-soo kim gyu-ri park sang-min hong ah-reum cho eun-sook koh soo-hee kang shin-il jin won oh young-soo mooshin musin soldier military official 무신', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-thang-nam', 'Nữ Hoàng Tháng Năm', 'May Queen', 'https://phimimg.com/upload/vod/20260403-1/0b32b21763d951b5d49dc9c28ca4ced1.jpg', 'https://phimimg.com/upload/vod/20260403-1/c01e2ca325139fd740133f86e208132c.jpg', '<p>Nữ Hoàng Tháng 5 là bộ phim kể về câu chuyện của cô gái giàu nghị lực Hae Joo. Cha của Chun Hae Joo đã bị chính bạn thân của mình là Do-Hyun sát hại. Do- Hyun quyết định giết cha cô vì ông yêu mẹ của Chun Hae Joo. Ông ta thậm chí còn ra lệnh cho quản gia Park Gi Chul giết Chun Hae Joo nhỏ bé khi đó mới 2 tuổi nhưng người quản gia không làm được và đã đưa cô đến một gia đình quen biết của ông ấy. Chun Hae Joo may mắn sống sót và lớn lên trong gia đình bố mẹ nuôi. Không biết con gái mình vẫn còn sống, mẹ của Chun Hae Joo kết hôn với Do Hyun. Hae Joo lớn lên trong cơ cực, bị mẹ nuôi ghẻ lạnh. Đến khi lớn chuyện tình cảm của Hae Joo cũng vấp phải nhiều trở ngại.</p>', 'Hoàn Tất (76/76)', 76, 'series', 'completed', 24, 2012, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Ji-hye","avatar":""},{"name":"Kim Jae-won","avatar":""},{"name":"Jae Hee","avatar":""},{"name":"Son Eun-seo","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Geum Bo-ra","avatar":""},{"name":"Lee Duck-hwa","avatar":""},{"name":"Yang Mi-kyung","avatar":""},{"name":"Kim Kyu-chul","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Sunwoo Jae-duk","avatar":""},{"name":"Kim Yoo-jung","avatar":""},{"name":"Park Ji-bin","avatar":""},{"name":"Park Gun-tae","avatar":""},{"name":"Kang Ji-woo","avatar":""},{"name":"Jung Zi-so","avatar":""},{"name":"Seo Young-joo","avatar":""},{"name":"Baek Seoung-hee","avatar":""},{"name":"Yoon Jong-h","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["五月皇后","五月女王","五月的情海","메이퀸"]', 1784690324463);
