INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-hoang-thang-nam', 'Nữ Hoàng Tháng Năm', 'May Queen', 'nữ hoàng tháng năm may queen han ji-hye kim jae-won jae hee son eun-seo ahn nae-sang geum bo-ra lee duck-hwa yang mi-kyung kim kyu-chul kim ji-young sunwoo jae-duk kim yoo-jung park ji-bin park gun-tae kang ji-woo jung zi-so seo young-joo baek seoung-hee yoon jong-h 五月皇后 五月女王 五月的情海 메이퀸', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kem-da', 'Kem Đá', 'Hyouka', 'https://phimimg.com/upload/vod/20260403-1/5cfa2aa08ecd9d17c72db43cad38cc76.jpg', 'https://phimimg.com/upload/vod/20260403-1/7f667fd1ebe1b0a413669d9e477b0d8e.jpg', '<p>Oreki Houtarou là một nam sinh trung học theo chủ nghĩa sống tối giản &quot;tiết kiệm năng lượng&quot;. Một ngày nọ, theo lời yêu cầu của chị gái, cậu tham gia vào Câu lạc bộ Văn học Cổ điển. Tại đây, cậu đã gặp gỡ Chitanda Eru, Fukube Satoshi và Ibara Mayaka. Chitanda là một thiếu nữ xinh đẹp, điềm tĩnh, nhưng cô sẽ trở thành hiện thân của sự tò mò mãnh liệt mỗi khi thốt lên câu nói: &quot;Tôi rất tò mò!&quot;. Fukube là một chàng trai luôn tươi cười với trí nhớ siêu phàm, người tự gọi mình là một &quot;cơ sở dữ liệu&quot;. Còn Ibara là một cô gái thấp bé nhưng lại cực kỳ nghiêm khắc với bản thân và người khác. Họ bắt đầu cùng nhau điều tra một vụ án bí ẩn đã xảy ra từ 45 năm trước. Những manh mối của bí mật này được chôn giấu trong một tập kỷ yếu cũ của các thành viên câu lạc bộ đời trước, mang tựa đề: &quot;Hyouka&quot;.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 15, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuichi Nakamura","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Daisuke Sakaguchi","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["冰菓","氷菓","冰果","Hyouka","Hyōka","Postre helado","ปริศนาความทรงจำ","古籍研究社","Хьока"]', 1784690324463);
