INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhai-minh-nguyet-dao', 'Thiên Nhai Minh Nguyệt Đao', 'The Magic Blade', 'https://phimimg.com/upload/vod/20250613-1/403a47ce9e18f008b92f12cb80804593.jpg', 'https://phimimg.com/upload/vod/20250613-1/e5a74fdd3aec1bc2d0355ae959d2e29d.jpg', '<p>24 năm trước, minh chủ võ lâm Dương Thường Phong bị giết một cách thần bí, trở thành một đại huyền án trong võ lâm. 24 năm sau, Phó Hồng Tuyết - hiệu xưng con trai duy nhất của Dương Thường Phong đột nhiên xuất hiện, triển khai báo thù. Diệp Khai, con thứ của Dương Thường Phong, người từ nhỏ đã hoán đổi thân phận với Phó Hồng Tuyết, dùng kế để Châu Đình chiếm được tình cảm của Phó Hồng Tuyết. Nào ngờ Châu Đình lại yêu Phó Hồng Tuyết. Để giúp người yêu Yến Nam Phi đoạt lấy ngôi minh chủ võ lâm, Minh Nguyệt Tâm tìm cách diệt trừ Phó Hồng Tuyết, nhưng dần dà lại nảy sinh tình cảm. Trên con đường báo thù, Phó Hồng Tuyết phải trải qua rất nhiều nguy cơ và trở ngại. Chàng phải chịu đựng sự khảo nghiệm của thiện và ác, ái và hận, trung thành và bội phản. Dưới sự giúp đỡ của Diệp Khai cùng Châu Đình và Minh Nguyệt Tâm, Phó Hồng Tuyết đã phá tan được trùng trùng âm mưu của Yến Nam Phi, Hướng Ứng Thiên, Công tử Vũ, Dương Phu Nhân... đồng thời tìm ra bí mật đằng sau cái chết của Dương Thường Phong và thân thế của mình, tìm lại được tình yêu...</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 23, 2012, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Mông","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Trần Sở Hà","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天涯明月刀"]', 1784690324463);
