INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-cot-phan-8', 'Hài Cốt (Phần 8)', 'Bones (Season 8)', 'hài cốt (phần 8) bones (season 8) emily deschanel david boreanaz john boyd michaela conlin tamara taylor t.j. thyne huesos bones: sempre em medicina 寻骨线索 עצמות استخوان‌ها bones', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-phai-tan', 'Sắc Đẹp Phai Tàn', 'Helter Skelter', 'https://phimimg.com/upload/vod/20260204-1/cd6c0e7ce628b8143339516f94009dd4.jpg', 'https://phimimg.com/upload/vod/20260204-1/07837aee77534642e5ca3d4e39d1e708.jpg', '<p>Ririko, một ngôi sao giải trí hàng đầu, luôn che giấu sự thật rằng cô đã phải thực hiện rất nhiều cuộc phẫu thuật thẩm mỹ trên toàn bộ cơ thể để trở nên xinh đẹp như ngày hôm nay. Trong khi cô đang muốn vươn cao hơn trong sự nghiệp thì các biến chứng của các ca phẫu thuật bắt đầu nảy sinh và Ririko bắt đầu phải đối mặt với những vấn đề trong công việc và cá nhân. Mọi việc trở nên rối bời khi người quản lý của cô tuyển thêm một gương mặt mới, Kozue, để làm “gà nhà” với mục đích đá bay Ririko ra khỏi làng giải trí… Dựa vào bộ truyện cùng tên gây tranh cãi tại Nhật của tác giả Kyoko Okazaki, bộ phim Helter Skelter đang làm nóng không khí trên các diễn đàn điện ảnh. Ngoài nội dung gây sốc, Helter Skelter còn gây bất ngờ khi công bố diễn viên Erika Sawajiri sẽ thủ vai chính đầy sexy trong bộ phim này, trái ngược với hình ảnh ngoan hiền vốn gắn với cô trong các tác phẩm như One litre of Tears, The Letters…</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Erika Sawajiri","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Shinobu Terajima","avatar":""},{"name":"Go Ayano","avatar":""},{"name":"Kiko Mizuhara","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"Anne Suzuki","avatar":""},{"name":"Susumu Terajima","avatar":""},{"name":"Show Aikawa","avatar":""},{"name":"Kaori Momoi","avatar":""},{"name":"Mariko Sumiyoshi","avatar":""},{"name":"Narumi Konno","avatar":""},{"name":"Yosuke Kubozuka","avatar":""},{"name":"Mieko Harada","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"MEGUMI","avatar":""},{"name":"Yukari Shiomi","avatar":""},{"name":"Airi Taira","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["惡女羅曼死","Herutâ sukerutâ","Хелтер-скелтер","Helter Skelter","헬터 스켈터","整容天后","ヘルタースケルター"]', 1784690324463);
