INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-loi-nguyen', 'Vùng Đất Quỷ Dữ: Lời Nguyền', 'Resident Evil: Damnation', 'https://phimimg.com/upload/vod/20250716-1/268f1f2649fa2bdc0b96baf6990e7c61.jpg', 'https://phimimg.com/upload/vod/20250716-1/9f35ee02bc3e0faa03f92ecfeebf3577.jpg', '<p>Capcom Nhật Bạn đã thông báo chính thức về việc hãng sẽ thực hiện phần tiếp theo của loạt phim hoạt hình 3D GC phát hành vào năm 2008. Resident Evil: Damnation vẫn do Sony Pictures Entertainment phát hành. Phim dự định ra mắt vào năm 2012. Phim có sự trở lại của Leon S.Kennedy trong một nhiệm vụ hoàn toàn mới. Kỹ xảo 3D được thực hiện trong Resident Evil: Damnation sẽ hoàn toàn khác hẳn với kỷ xảo 3D trong phim RE: Afterlife.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Matthew Mercer","avatar":""},{"name":"Courtenay Taylor","avatar":""},{"name":"Robin Sachs","avatar":""},{"name":"Dave Wittenberg","avatar":""},{"name":"Wendee Lee","avatar":""},{"name":"Val Tasso","avatar":""},{"name":"Salli Saffioti","avatar":""},{"name":"Patrick Seitz","avatar":""},{"name":"Michael McConnohie","avatar":""},{"name":"Jolene Andersen","avatar":""},{"name":"David Vincent","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Resident Evil La Maldición","Resident Evil: Infierno","Resident Evil Damnation - CG","Resident Evil 2 - Damnation","Biohazard Damnation","레지던트 이블 2: 댐네