INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-4-di-san-cua-bourne', 'Siêu Điệp Viên 4: Di Sản Của Bourne', 'The Bourne Legacy', 'https://phimimg.com/upload/vod/20260116-1/50a95019a0c4dc8a01869697a68a7c29.jpg', 'https://phimimg.com/upload/vod/20260116-1/2fcedaf3263c052bc29da9b6a8363e77.jpg', '<p>Aaron Cross – một người từng tham gia chương trình tuyệt mật của chính phủ. Chương trình đột ngột bị dừng lại tất cả những người tham gia thử nghiệm đều bị giết hại. Aaro Cross may mắn trốn thoát và quyết tâm thoát khỏi sự truy đuổi của CIA… Trong phần này, nội dung không tập trung vào J. Bourne nữa mà đào sâu vào bí mật đằng sau những chương trình mà các phần trước thường xuyên nói tới như Treadstone, Blackbriar.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jeremy Renner","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Dennis Boutsikaris","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Donna Murphy","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Shane Jacobson","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"John Douglas T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jason Bourne 4 - L''Héritage","谍影重重4：伯恩的遗产","Jason Bourne 4 - The Bourne Legacy","O Legado Bourne","Jason Bourne: L''héritage","본 레거시","Bourne 4 - The Bourne Legacy","Jason Bourne 4 - Bourneův odkaz","Bourne 4 El legado de Bourne","Jason Bourne L''Héritage","Jason Bourne, L''Héritage","Bourne IV: The Bourne Legacy","叛諜追擊4 機密逃殺","Jason Bourne 4 - Das Bourne Vermächtnis","Jason Bourne 4","谍影重重4","إرث بورن","The Bourne Legacy"]', 1784690324463);
