INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-diep-vien-4-di-san-cua-bourne', 'Siêu Điệp Viên 4: Di Sản Của Bourne', 'The Bourne Legacy', 'siêu điệp viên 4: di sản của bourne the bourne legacy jeremy renner rachel weisz edward norton stacy keach dennis boutsikaris oscar isaac joan allen albert finney david strathairn scott glenn donna murphy michael chernus corey stoll zeljko ivanek shane jacobson elizabeth marvel john douglas t jason bourne 4 - l''héritage 谍影重重4：伯恩的遗产 jason bourne 4 - the bourne legacy o legado bourne jason bourne: l''héritage 본 레거시 bourne 4 - the bourne legacy jason bourne 4 - bourneův odkaz bourne 4 el legado de bourne jason bourne l''héritage jason bourne, l''héritage bourne iv: the bourne legacy 叛諜追擊4 機密逃殺 jason bourne 4 - das bourne vermächtnis jason bourne 4 谍影重重4 إرث بورن the bourne legacy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-noi-em-yeu-anh', 'Hãy Nói Em Yêu Anh', 'Say "I Love You."', 'https://phimimg.com/upload/vod/20260114-1/f1385645adbdb3b7dd3bb56ce81e3bb7.jpg', 'https://phimimg.com/upload/vod/20260114-1/5e065703d023fd9c0db70bf941ac1ac3.jpg', '<p>Tin tưởng chính là tự đẩy mình vào thất bại. Đó là bài học xương máu mà Mei Tachibana đã rút ra khi trái tim cô tan vỡ. Cô tìm thấy một giải pháp: không bao giờ kết bạn với bất kỳ ai nữa. Nói thì dễ hơn làm, nhưng với Mei, điều đó thực sự hiệu quả. Ít nhất là cho đến khi Yamato Kurosawa — chàng trai điển trai và đầy quyến rũ — xuất hiện và làm đảo lộn mọi thứ. Mei không hề tìm kiếm một &#39;bạch mã hoàng tử&#39; cứu rỗi đời mình. Vậy tại sao anh ta lại hôn cô và phá hỏng mọi kế hoạch cơ chứ? Giữa những nhịp tim thổn thức và đôi môi run rẩy, bóng ma của những phản bội trong quá khứ, hiện tại và tương lai đang đeo bám cả hai người.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 14, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ai Kayano","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Risa Taneda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["只要你说你爱我","Say, I Love You","Sukitte Iinayo","Suki-tte Ii na yo","Sukitte Ii na yo.","Say \"I love you.\"","好きっていいなよ。"]', 1784690324463);
