INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-noi-em-yeu-anh', 'Hãy Nói Em Yêu Anh', 'Say "I Love You."', 'hãy nói em yêu anh say "i love you." ai kayano takahiro sakurai nobunaga shimazaki minako kotobuki yumi uchiyama tomoaki maeno risa taneda 只要你说你爱我 say, i love you sukitte iinayo suki-tte ii na yo sukitte ii na yo. say "i love you." 好きっていいなよ。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-linh-cuoi-cung-dai-thuong-hai', 'Thủ Lĩnh Cuối Cùng (Đại Thượng Hải)', 'The Last Tycoon', 'https://phimimg.com/upload/vod/20260112-1/55d88767fb862e3faeac7fc5f805170c.jpg', 'https://phimimg.com/upload/vod/20260112-1/de3c193429026035c828a2d73039121a.jpg', '<p>Câu chuyện bắt đầu tại Phố Đông, Thượng Hải vào đầu thế kỷ XX. Chàng học việc tiệm trái cây Thành Đại Khí và cô hàng xóm diễn viên kinh kịch Diệp Tri Thu là đôi thanh mai trúc mã. Sau khi bị hãm hại vào tù, Thành Đại Khí lạc mất người thương khi cô buộc phải lên phía Bắc cầu học. Tại ngục tối, anh được đặc vụ Mao Tái giải cứu, từ đó quỹ đạo cuộc đời hoàn toàn thay đổi.Đầu quân dưới trướng ông trùm Thượng Hải Hồng Thọ Đình, Thành Đại Khí nhờ bản lĩnh và sự khôn ngoan đã nhanh chóng thăng tiến, trở thành cánh tay phải đắc lực của Hồng gia. Bên cạnh anh có A Bảo – đệ nhất mỹ nhân Thượng Hải hết lòng tình nghĩa, nhưng sâu trong tim anh vẫn luôn dành một vị trí cho mối tình đầu. Sau phi vụ đơn thương độc mã cứu Hồng Thọ Đình, Thành Đại Khí chính thức vang danh khắp bến Thượng Hải, trở thành một thế hệ kiêu hùng.Khi bước sang tuổi trung niên, sự nghiệp đạt đỉnh cao cũng là lúc anh phải đối mặt với hiểm họa xâm lược của phát xít Nhật và sự ép buộc của Mao Tái – giờ đã là một đầu mục đặc vụ đầy dã tâm. Cuộc hội ngộ với Diệp Tri Thu (nay đã có gia đình) càng khiến lòng anh dậy sóng. Khi Thượng Hải thất thủ, Mao Tái lấy Hồng Thọ Đình làm con tin, ép Thành Đại Khí trở về làm việc cho chính quyền bù nhìn. Để cứu anh em và giữ trọn đại nghĩa dân tộc, Thành Đại Khí ngoài mặt thuận tùng nhưng âm thầm bày binh bố trận, thực hiện một ván bài sinh tử giữa lòng Thượng Hải đầy biến động.</p>', 'Full', 1, 'single', 'completed', 45, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Hồng Kim Bảo","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Viên Tuyền","avatar":""},{"name":"Mạc Văn Úy","avatar":""},{"name":"Cao Hổ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Shang Hai","The Last Tycoon","大上海"]', 1784690324463);
