INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-gia-mao', 'Hoàng Đế Giả Mạo', 'Masquerade', 'https://phimimg.com/upload/vod/20260109-1/79b94b01c04b763d572735ce91c416e7.jpg', 'https://phimimg.com/upload/vod/20260109-1/fe5a9dd2997b50b5e1ce03463175d53c.jpg', '<p>Hoàng Đế Giả Mạo dựa vào câu chuyện có thật về một vị vua bạo chúa khét tiếng nhưng lại là một chính trị gia rất tốt mang tê Gwanghae, vị vua thứ 15 của đế chế Chosun huyền thoại. Gwanghae thật bị một nhóm gian thần bày mưu ám sát nên phải tạm “quy ẩn” một thời gian. Vì đất nước một ngày không thể không có vua nên Gwanghae đã sai cận thần tìm một kẻ thế mạng ngồi tạm vào ngôi báu để đánh lạc hướng.</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Jang Kwang","avatar":""},{"name":"Shim Eun-kyung","avatar":""},{"name":"Park Ji-a","avatar":""},{"name":"Shin Jung-keun","avatar":""},{"name":"Jeon Guk-hyang","avatar":""},{"name":"Lee El","avatar":""},{"name":"Kim Myung-gon","avatar":""},{"name":"Kyul Hwi","avatar":""},{"name":"Lee Yang-hee","avatar":""},{"name":"Lee Bong-ryeon","avatar":""},{"name":"Lee Ran-hee","avatar":""},{"name":"Shin Un-seop","avatar":""},{"name":"Joo Young-ho","avatar":""},{"name":"Yang Joon-mo","avatar":""},{"name":"Moon Cha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Gwanghae, Wangyidoen namja","광해: 왕이 된 남자","Masquerade","A férfi aki királyt játszott","光海，成为王的男人","Gwang-hae, wang-i doin nam-ja","광해, 왕이 된 남자","Gwanghae: wang-i doen namja"]', 1784690324463);
