INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xac-song-phan-3', 'Xác Sống (Phần 3)', 'The Walking Dead (Season 3)', 'xác sống (phần 3) the walking dead (season 3) lauren cohan norman reedus jeffrey dean morgan melissa mcbride christian serratos seth gilliam ross marquand josh mcdermitt khary payton cooper andrews callan mcauliffe cailey fleming lauren ridloff eleanor matsuura nadia hilker cassady mcc të vdekurit e gjallë живите мъртви les morcheurs 行尸走肉 živí mrtví elavad surnud οι ζωντανοί νεκροί 行屍 živi mrtvaci מתים מהלכים mordeye moteharrek ウォーキング・デッド 워킹 데드 워킹데드 gyvieji numirėliai gyvi numirėliai staigājušie miroņi живи мртовци żywe trupy the walking dead the walking dead: invazia zombi okružen mrtvima zivi mrtveci živí mŕtvi ล่าสยอง...กองทัพผีดิบ ฝ่าวงล้อม ซอมบี้ล้างโลก yürüyen ölüler ходячі мерці і мертві підуть twd yuradigan murdalar xac song', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-khon-kho', 'Những Người Khốn Khổ', 'Les Misérables', 'https://phimimg.com/upload/vod/20260108-1/cb71577c8bec20d630d6518b63f33260.jpg', 'https://phimimg.com/upload/vod/20260108-1/a0120a170ff08393e1f67f79105a5395.jpg', '<p>Tác phẩm chuyển thể từ tiểu thuyết cùng tên của đại văn hào Victor Hugo. Trong tác phẩm phim âm nhạc chuyển thể này Hugh Jackman vào vai nhân vật chính Jean Valjean – người tù khốn khổ trong cuộc chiến đấu giành lại tự do và cứu rỗi những người dân nghèo khốn cùng. Poster mới nhất chính là hình ảnh về Jean Valjean, và như những poster trước đó, trọng tâm lại dồn vào đôi mắt với cái nhìn đầy biểu cảm. Cùng với Hugh Jackman trong phim còn có sự tham gia của Russell Crowe, Anne Hathaway, Sacha Baron Cohen, và Eddie Redmayne.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Anh', 1, '[{"name":"Hugh Jackman","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Eddie Redmayne","avatar":""},{"name":"Aaron Tveit","avatar":""},{"name":"Samantha Barks","avatar":""},{"name":"Daniel Huttlestone","avatar":""},{"name":"Fra Fee","avatar":""},{"name":"Hugh Skinner","avatar":""},{"name":"Alistair Brammer","avatar":""},{"name":"Killian Donnelly","avatar":""},{"name":"Adam Pearce","avatar":""},{"name":"Ian Pirie","avatar":""},{"name":"Tim D","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Les misérables: Nędznicy","Bi Navayan","Le Mis","레 미제라블","レ・ミゼラブル　デジタルリマスター／リミックス","Les Misérables"]', 1784690324463);
