INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-noi-loan-hoan-hao', 'Sự Nổi Loạn Hoàn Hảo', 'Pitch Perfect', 'https://phimimg.com/upload/vod/20260105-1/7bb3c4dbb7247f66ca8212466c0cb2ef.jpg', 'https://phimimg.com/upload/vod/20260105-1/835a5a0d37f56e673ffc245be5354740.jpg', '<p>Bộ phim lấy bối cảnh tại trường đại học Barden. Nhân vật chính của phim là Beca (Anna Kendrick đóng), một cô gái trẻ đam mê ca hát. Bố cô là một giảng viên đại học, ông đã bắt cô phải hoàn tất chương trình đại học ở Barden. Là một cô gái có tính cách độc lập, không có bạn bè, chỉ say mê với âm nhạc, việc hòa nhập vào trường đại học của cô sinh viên năm nhất Beca có vẻ không mấy khả quan. Nhưng rồi cuối cùng cô cũng tìm ra được một lí do để yêu thích việc ở lại trường, đó chính là nhóm nhạc A cappella nữ độc nhất vô nhị tại Barden – The Barden Bellas.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anna Kendrick","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Skylar Astin","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Ester Dean","avatar":""},{"name":"Hana Mae Lee","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Ben Platt","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Kelley Jakle","avatar":""},{"name":"Shelley Regner","avatar":""},{"name":"Caroline Fourmy","avatar":""},{"name":"Wanetah Walmsley","avatar":""},{"name":"Nicole Lovince","avatar":""},{"name":"Michae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["歌喉赞","Pitch Perfect - Die Bühne gehört uns!","Pitch Perfect (The Hit Girls)","Pitch Perfect 1","Pitch Perfect","Dando la nota: 1","피치퍼펙트"]', 1784690324463);
