INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-django', 'Hành Trình Django', 'Django Unchained', 'https://phimimg.com/upload/vod/20251230-1/db7ef0e683c460fc1bffd93e5afeecc9.jpg', 'https://phimimg.com/upload/vod/20251230-1/e3388dc8c43e976972dc1314f66aacfb.jpg', '<p>Tài tử &quot;Titanic&quot; đóng vai một chủ nô quyến rũ nhưng tàn bạo trong tác phẩm cao bồi miền Tây, &quot;Django Unchained&quot; - bộ phim đánh dấu sự trở lại của đạo diễn lừng danh Quentin Tarantino.Tuy lấy bối cảnh là miền Nam nước Mỹ nhưng phong cách của Django Unchained lại là cao bồi miền Tây. Phim nói về hành trình của một người nô lệ da màu (Jamie Foxx đóng) giải cứu người vợ khỏi tay tên chủ điền Calvin Candie nổi tiếng bệnh hoạn và độc ác.</p>', 'Full', 1, 'single', 'completed', 41, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jamie Foxx","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Dennis Christopher","avatar":""},{"name":"James Remar","avatar":""},{"name":"David Steen","avatar":""},{"name":"Dana Gourrier","avatar":""},{"name":"Nichole Galicia","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Sammi Rotibi","avatar":""},{"name":"Clay Donahue Fontenot","avatar":""},{"name":"Escalant","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Zencirsiz Canqo","Đangova osveta","Джанго освобождённый","ג''נגו ללא מעצורים","جانكو المتحرر","Ђангова освета","Django Livre","장고: 분노의 추적자","被解放的姜戈","Django desencadenado","จังโก้ โคตรคนแดนเถื่อน","Ջանգո Ազատագրվածը","Django déchaîné","Джанга вызвалены","Джанго без окови","Джанґо вільний","Джанго кісен ашқан","Django, ο τιμωρός","Django desencadenáu","Django desencadenat","Django sin cadenas","Odbjegli Django","Atsvabinātais Džango","Ištrūkęs Džango","Django elszabadul","Django","Django Libertado","Django dezlănțuit","Django brez okovov","Zincirsiz","Ջանգոն ազատված","ჯანგო გათავისუფლებული","Nespoutaný Django","جانغو الحر","زینجیرسیز","جنگوی زنجیرگسسته","جانجو الحر","جانگۆی ئازادکراو","ジャンゴ 繋がれざる者","Кишенден бошотулган Джанго","Жанго эрх чөлөөгөө олсон нь","Hành trình Django","জ্যাঙ্গো আনচেইন্ড","ਜੈਂਗੋ ਅਨਚੇਨਡ","சாங்கோ அன்செயின்டு","జాంగో అన్‌చెయిన్డ్","黑殺令","決殺令","被解救个姜戈","खतरों का खिलाडी","Џанго разузданиот","Ozod Django","Django Unchained"]', 1784690324463);
