INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-trinh-django', 'Hành Trình Django', 'Django Unchained', 'hành trình django django unchained jamie foxx christoph waltz leonardo dicaprio kerry washington samuel l. jackson walton goggins dennis christopher james remar david steen dana gourrier nichole galicia laura cayouette ato essandoh sammi rotibi clay donahue fontenot escalant zencirsiz canqo đangova osveta джанго освобождённый ג''נגו ללא מעצורים جانكو المتحرر ђангова освета django livre 장고: 분노의 추적자 被解放的姜戈 django desencadenado จังโก้ โคตรคนแดนเถื่อน ջանգո ազատագրվածը django déchaîné джанга вызвалены джанго без окови джанґо вільний джанго кісен ашқан django, ο τιμωρός django desencadenáu django desencadenat django sin cadenas odbjegli django atsvabinātais džango ištrūkęs džango django elszabadul django django libertado django dezlănțuit django brez okovov zincirsiz ջանգոն ազատված ჯანგო გათავისუფლებული nespoutaný django جانغو الحر زینجیرسیز جنگوی زنجیرگسسته جانجو الحر جانگۆی ئازادکراو ジャンゴ 繋がれざる者 кишенден бошотулган джанго жанго эрх чөлөөгөө олсон нь hành trình django জ্যাঙ্গো আনচেইন্ড ਜੈਂਗੋ ਅਨਚੇਨਡ சாங்கோ அன்செயின்டு జాంగో అన్‌చెయిన్డ్ 黑殺令 決殺令 被解救个姜戈 खतरों का खिलाडी џанго разузданиот ozod django django unchained', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nhac-my-nam', 'Ban Nhạc Mỹ Nam', 'Shut Up Flower Boy Band', 'https://phimimg.com/upload/vod/20251226-1/7d6a3aebd481bc5c013e5384a272fa32.jpg', 'https://phimimg.com/upload/vod/20251226-1/88e6c1f234ff7ab9f17304c9395d5ab9.jpg', '<p>Đây là bộ phim mới xoay quanh đề tài về một band nhạc rock, vậy nên đã chọn ra những gương mặt hoàn toàn mới để tham gia diễn xuất. Tên của bộ phim là &quot;Ban Nhạc Mỹ Nam&quot; kể câu chuyện về tình bạn, niềm đam mê âm nhạc, và tình yêu xoay quanh ban nhạc gồm những anh chàng học sinh trung học đẹp trai, có tâm hồn tự do, phóng khoáng : Ji Hyuk, Hyun Soo, Ha Jin, Do Il, Kyung Jong. Dù chỉ là những nam sinh còn ngồi trên ghế nhà trường, nhưng cả năm chàng trai luôn có cùng một đam mê cháy bỏng với âm nhạc, họ thành lập ban nhạc rock underground Eye Candy và mong muốn sẽ trở nên nổi tiếng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sung Joon","avatar":""},{"name":"L","avatar":""},{"name":"Lee Hyun-jae","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Yoo Min-kyu","avatar":""},{"name":"Cho Bo-ah","avatar":""},{"name":"Jung Eui-chul","avatar":""},{"name":"Kim Jung-min","avatar":""},{"name":"Lim Kim","avatar":""},{"name":"Kim In-seo","avatar":""},{"name":"Kwak Jung-wook","avatar":""},{"name":"Kim Hyun-joon","avatar":""},{"name":"Jung Jin-an","avatar":""},{"name":"Dong Hyun-bae","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Kim C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["闭嘴，花美男乐团","Dakchigo Kkotminam Baendeu","Dakchigo Kkotminam Band","꽃미남밴드: 안구정화","搖滾吧！花樣男團","Flower Boy Band","Eye Candy","Shut Up: Flower Boy Band","Flower Boy Band: Eye Candy","Shut Up And Let''s Go","Shut Up: Pretty Boys Band","닥치고 꽃미남밴드"]', 1784690324463);
