INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-sushi', 'Cô Gái Sushi', 'Sushi Girl', 'cô gái sushi sushi girl danny trejo mark hamill noah hathaway jeff fahey sonny chiba tony todd cortney palm james duval andy mackenzie david dastmalchian michael biehn neal fischer suren m. seron rachel federoff mike m. quick david reynolds destin pfaff stryker суши гёл la fille sushi sushi girl', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-no-le-phan-3', 'Cuộc Chiến Của Nô Lệ (Phần 3)', 'Spartacus (Season 3)', 'https://phimimg.com/upload/vod/20251125-1/5d82b161e430c3323030262e8ad5b276.jpg', 'https://phimimg.com/upload/vod/20251125-1/9a0aaecf7540762b87d269a0b765c1b9.jpg', '<p>Spartacus là bộ phim khắc họa hình ảnh người anh hùng nô lệ Spartacus vì muốn chống lại quân thổ phỉ Spartacus đã liên minh cùng quân La Mã nhưng ngay sau đó La Mã đã phản bội lại anh. Spartacus bị bắt và được huấn luyện để trở thành võ sĩ chuyên thi đấu mua vui tại đấu trường La Mã nổi tiếng. Cuộc sống khắc nghiệt mà hàng ngày cùng với tình yêu gia đình nhỏ bé của mình Spartacus đã lãnh đạo những người nô lệ cùng khổ tiến hành cuộc khởi nghĩa long trời lở đất làm rung chuyển cả đế chế La Mã.

Nhan đề bộ phim cũng đã phản ảnh rất nhiều về đề tài và nội dung của phim. Người anh hùng Spartacus dũng cảm chấp nhận đổ máu và nước mắt để chống lại thế lực đen tối bảo vệ gia đình và những người đang gặp khốn khổ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam McIntyre","avatar":""},{"name":"Manu Bennett","avatar":""},{"name":"Dustin Clare","avatar":""},{"name":"Cynthia Addai-Robinson","avatar":""},{"name":"Jaime Murray","avatar":""},{"name":"Ellen Hollman","avatar":""},{"name":"Luna Rioumina","avatar":""},{"name":"Marisa Ramirez","avatar":""},{"name":"Ditch Davey","avatar":""},{"name":"Barry Duffield","avatar":""},{"name":"Pana Hema-Taylor","avatar":""},{"name":"Stephen Lovatt","avatar":""},{"name":"Blessing Mokgohloa","avatar":""},{"name":"Jenna Lind","avatar":""},{"name":"Hanna Mangan Lawrence","avatar":""},{"name":"Gwendoline","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Спартак: Кръв и пясък","Спартак: Отмъщение","Spartacus: Viva a Origem","Spartacus Origens: Deuses da Arena","斯巴达克斯：血与沙","斯巴达克斯：复仇","Spartacus: Gods of the Arena","Spartacus: Sangre y arena","Spartacus: Dioses de la Arena","Spartacus: Venganza","Spartacus: La guerra de los condenados","Spartacus: les Dieux de l''Arène","Spartacus - Az aréna istenei","Spartacus: Sangue e Areia","Spartacus: Blood and Sand","Spartacus: Vengeance","Spartacus: War of the Damned","Spartacus"]', 1784690324463);
