INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-saga', 'Ultraman Saga', 'Ultraman Saga', 'https://phimimg.com/upload/vod/20251122-1/efe8efd2c3ccbd6d6d1acb4d9f42c276.jpg', 'https://phimimg.com/upload/vod/20251122-1/7dd8c1f43c10975b358bda57a3aa1fd3.jpg', '<p>Ultraman Saga lấy bối cảnh 15 năm sau khi Shin Asuka (Ultraman Dyna) biến mất trong một hố đen. Trái Đất đã xây dựng trạm vũ trụ trên sao Hỏa để tưởng niệm anh, nhưng nơi này nhanh chóng bị tấn công bởi sinh vật ngoài hành tinh Granspheres. Phi công trẻ Taiga liều lĩnh truy đuổi và bị cuốn vào một pháo đài không gian bí ẩn. Trước mối đe dọa hủy diệt, Ultraman Zero, Cosmos và Dyna hợp thể thành Ultraman Saga - chiến binh tối thượng. Một cuộc chiến mới bắt đầu, khi hy vọng về sự trở lại của Dyna ngày càng sáng rõ.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeshi Tsuruno","avatar":""},{"name":"DAIGO","avatar":""},{"name":"Sayaka Akimoto","avatar":""},{"name":"Ayaka Umeda","avatar":""},{"name":"Taiyo Sugiura","avatar":""},{"name":"Yuka Masuda","avatar":""},{"name":"Sae Miyazawa","avatar":""},{"name":"Sumire Sato","avatar":""},{"name":"Kana Kobayashi","avatar":""},{"name":"Haruka Shimada","avatar":""},{"name":"Sayaka Ikeda","avatar":""},{"name":"Kurea Mori","avatar":""},{"name":"Kanau Tanaka","avatar":""},{"name":"Sion Nakamaru","avatar":""},{"name":"Toshikazu Fukawa","avatar":""},{"name":"Risa Saito","avatar":""},{"name":"Nobuyuki Kase","avatar":""},{"name":"Joe Onodera","avatar":""},{"name":"Ry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]'