INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-ly-thuan-phong', 'Thần Thám Lý Thuần Phong', 'Intelligent Detective', 'https://phimimg.com/upload/vod/20251028-1/024df8af02b3e26236ec0e1f79ccf75e.jpg', 'https://phimimg.com/upload/vod/20251028-1/af5ccfd5870734ba799800823b0406e0.jpg', '<p>Kinh thành Trường An thường xuyên xảy ra nhiều vụ án, ban đầu là những vụ giết người xảy ra bên ngoài cổng Khai Nguyên, sau đó là sự xuất hiện trở lại của con cháu thời đại. Nhà Hán lưu lạc và trở thành những kẻ sát nhân, lợi dụng người dân lương thiện để thao túng quyền lực trong triều đình, huynh đệ tương tàn. Cuối cùng ở Nam Sơn xuất hiện hàng loạt hiện tượng kỳ lạ, cũng như hàng loạt câu chuyện kỳ lạ diễn ra trong triều đình và những chuyện thầm kín chốn hậu cung thường xuyên xuất hiện.Nếu bạn là người yêu thích những bộ phim hấp dẫn, đừng bỏ lỡ phim hay trung quốc. Đặc biệt, các tác phẩm đến từ đất nước này thường mang đậm giá trị văn hóa và truyền thống. Hãy khám phá ngay kho tàng phim ảnh đa dạng, từ kỳ bí đến tâm lý, chắc chắn sẽ khiến bạn say mê và khó mà rời mắt.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 11, 2012, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Thiên Dã","avatar":""},{"name":"Trần Hạo Dân","avatar":""},{"name":"Triệu Kha","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bu An","Intelligent Detective","卜案"]', 1784690324464);
