INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-quay-hanh-phuc', 'Vòng Quay Hạnh Phúc', 'Missing You', 'https://phimimg.com/upload/vod/20251023-1/0c4e28692dc2c875096994c09a1e1f47.jpg', 'https://phimimg.com/upload/vod/20251023-1/4dd33d37858219895999a3a15fc7c770.jpg', '<p>Khang Như Phong (do Chung Gia Hân đóng) vừa được nhận vào làm việc cho một công ty chuyên tìm kiếm người bị thất lạc do chiến tranh, thiên tai hoặc thay đổi chỗ ở. Lãnh đạo Lỗ Văn Địch (do Tưởng Chí Quang đóng) là người rất điềm tĩnh và tư duy logic. Dưới trướng của ông còn có 3 nhân viên cá tính, là anh chàng năng nổ Thi Diệc Khiêm (do Trần Trí Sâm đóng), cô nàng khéo ăn nói Tiển Khiết Trinh (do Lạc Đồng đóng), và chuyên gia máy tính Dương Tử Cơ (do Trần Vỹ Hồng đóng).</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2012, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Jason Chan Chi-San","avatar":""},{"name":"Rosina Lin","avatar":""},{"name":"Cilla Kung","avatar":""},{"name":"Ram Chiang Chi-Kwong","avatar":""},{"name":"Mat Yeung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["幸福摩天輪"]', 1784690324464);
