INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-trinh-kontiki', 'Hải Trình Kon-Tiki', 'Kon-Tiki', 'https://phimimg.com/upload/vod/20251023-1/4c31366ec275e601d203a698d23310e3.jpg', 'https://phimimg.com/upload/vod/20251023-1/745563c6e5e598f482a70ddd11f11ceb.jpg', '<p>Kon-Tiki (Hải Trình Kon-Tiki) là một bộ phim lịch sử năm 2012 được đạo diễn bởi Joachim Rønning và Espen Sandberg. Phim được dựng từ cuốn &quot;Hải trình Kon-Tiki&quot; nói về Thor Heyerdahl (1914 - 2002), một nhà nhân chủng học và thám hiểm gia người Na Uy cùng một nhóm các cộng sự vào năm 1947 nhằm chứng minh cho giả thuyết 1500 năm trước người da đỏ đã vượt biển đến định cư trên những đảo nam Thái Bình Dương chứ không phải từ Châu Á như các thuyết từ trước đến nay. Hải Trình Kon-Tiki là nơi Thor Heyerdahl ghi lại chuyến đi của ông cùng các bạn với một bút pháp say mê, mang tới nguồn kiến thức tưởng chừng vô tận về biển cả, sinh vật biển, lịch sử, phong tục. Cuốn sách đã thổi bùng lên ngọn lửa cảm hứng về lòng quả cảm của con người trước tự nhiên bao la.</p>', 'Full', 1, 'single', 'completed', 20, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pål Sverre Hagen","avatar":""},{"name":"Anders Baasmo Christiansen","avatar":""},{"name":"Tobias Santelmann","avatar":""},{"name":"Gustaf Skarsgård","avatar":""},{"name":"Odd-Magnus Williamson","avatar":""},{"name":"Jakob Oftebro","avatar":""},{"name":"Agnes Kittelsen","avatar":""},{"name":"Manuel Cauchi","avatar":""},{"name":"Richard Trinder","avatar":""},{"name":"Søren Pilmark","avatar":""},{"name":"Peter Wight","avatar":""},{"name":"Jo Adrian Haavind","avatar":""},{"name":"Ian Bonar","avatar":""},{"name":"Eilif Hellum Noraker","avatar":""},{"name":"Elisa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["康提基號：偉大航程","孤筏重洋","A Aventura de Kon Tiki","Un viaje fantástico","Expedição Kon Tiki","A Aventura de Kon-Tiki","Kon-Tiki"]', 1784690324464);
