INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mau-lanh', 'Sát Thủ Máu Lạnh', 'A Company Man', 'https://phimimg.com/upload/vod/20251023-1/9a8997ae510ec0b5e5cbf2aef12f02e2.jpg', 'https://phimimg.com/upload/vod/20251023-1/e44c161b1b7cce515a8adc2adbb450fe.jpg', '<p>Hyeong Do là một sát thủ trong tổ chức giết người theo hợp đồng dưới mặt nạ là một công ty buôn bán kim loại. Đối với Hyeong giết người đã trở thành công việc thường nhật nhưng trong một lần nhận nhiệm vụ thủ tiêu Hyun Yi khi anh này hết giá trị sử dụng. Hyeong đã để tình cảm chi phối và không hoàn thành nhiệm vụ. Hyeong đã bị biến thành mục tiêu của nhóm các sát thủ khác.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"So Ji-sub","avatar":""},{"name":"Lee Mi-yeon","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Kim Dong-jun","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Han Bo-bae","avatar":""},{"name":"Yoo Ha-bok","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Kim Seo-won","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Hong Kyeong-yeon","avatar":""},{"name":"Lee Jae-yoon","avatar":""},{"name":"Jung Young-ki","avatar":""},{"name":"Lee Chae-eun","avatar":""},{"name":"Yu Na-mi","avatar":""},{"name":"Hwang Seok-jeong","avatar":""},{"name":"Jeong Gi-seop","avatar":""},{"name":"Ha Soo-ho","avatar":""},{"name":"Seo Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Company Man","회사원","Служащий","Hoi-sa-won","公司职员"]',