INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-do', 'Vân Đồ', 'Cloud Atlas', 'https://phimimg.com/upload/vod/20251023-1/09bb4237eb707a9b38c5f92aa9622927.jpg', 'https://phimimg.com/upload/vod/20251023-1/4ee0d3e39e8034c94f3bf745a3841fb7.jpg', '<p>Cloud Atlas là một thiên sử thi về loài người mà trong đó, mỗi hành động của mỗi cá nhân lại có tác động, ảnh hưởng tới những con người khác tại quá khứ, hiện tại và tương lai. Sáu nhân vật chính cùng sáu câu truyện kéo dài hơn 5 thế kỉ bắt đầu tại ba lục địa, bắt đầu từ Nam Thái Bình Dương thế kỷ 19 kéo dài tới thời kì tận hậu thế tại Hawaii. Mỗi câu truyện được “dẫn dắt” bởi chính nhân vật của câu truyện kế tiếp. Sáu câu truyện nhỏ được kết hợp thành một cốt truyện thống nhất.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Hanks","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Keith David","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Robert Fyfe","avatar":""},{"name":"Martin Wuttke","avatar":""},{"name":"Robin Morrissey","avatar":""},{"name":"Brody Nicholas Lee","avatar":""},{"name":"Ian van Temperle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Atlas Chmur","Atlas mraků","Cloud Atlas - Der Wolkenatlas","클라우드 아틀라스","クラウド アトラス","Облакът Aтлас","Cloud Atlas: La Red Invisible","Cloud Atlas (2012)","A Viagem 2012","Cartographie des nuages","Cloud Atlas - Alles ist verbunden","Mây Atlas","El atlas de las nubes","Cloud Atlas"]', 1784690324464);
