INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-do', 'Vân Đồ', 'Cloud Atlas', 'vân đồ cloud atlas tom hanks halle berry jim broadbent hugo weaving jim sturgess bae doona ben whishaw james d''arcy zhou xun keith david susan sarandon hugh grant david gyasi robert fyfe martin wuttke robin morrissey brody nicholas lee ian van temperle atlas chmur atlas mraků cloud atlas - der wolkenatlas 클라우드 아틀라스 クラウド アトラス облакът aтлас cloud atlas: la red invisible cloud atlas (2012) a viagem 2012 cartographie des nuages cloud atlas - alles ist verbunden mây atlas el atlas de las nubes cloud atlas', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-ngay-xua-phan-2', 'Ngày Xửa Ngày Xưa (Phần 2)', 'Once Upon A Time (Season 2)', 'https://phimimg.com/upload/vod/20251023-1/2444048eeac3009577b55d7d485b163e.jpg', 'https://phimimg.com/upload/vod/20251023-1/6b16e6ee7dce895be5adc4366a1e033f.jpg', '<p>Loạt phim xoay quanh câu chuyện của nữ trinh thám Emma Swan cùng con trai Henry trong quá trình khám phá thị trấn Storybrooke (tiểu bang Maine, Đông Bắc Hoa Kỳ). Đây được xem là vết tích của một thế giới song song bị nguyền rủa bởi Hoàng hậu độc ác - Regina Mills - người đến từ câu chuyện cổ tích Nàng Bạch Tuyết. Trong phim, mọi nhân vật đến từ thế giới cổ tích đều không có ký ức về thân phận của mình. Nữ trinh thám Emma Swan được gửi đến thế giới này với nhiệm vụ phá vỡ lời nguyền của mụ Hoàng hậu độc ác. Trong phần 2 này, khi lời nguyền bị phá vỡ, nữ trinh thám Emma được đoàn tụ với cha mẹ, nhưng mụ Hoàng hậu độc ác Regina liệu có để mọi chuyện được yên?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lana Parrilla","avatar":""},{"name":"Colin O''Donoghue","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Andrew J. West","avatar":""},{"name":"Alison Fernández","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Era Uma Vez","Il Était une Fois","Bylo nebylo","Gyveno kartą","Érase una vez","OUAT","Once Upon a Time"]', 1784690324464);
