INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-bi-2-thuat-hoi-sinh', 'Họa Bì 2: Thuật Hồi Sinh', 'Painted Skin: The Resurrection', 'https://phimimg.com/upload/vod/20251014-1/d75baefb4be41c495fb29b5ef518e114.jpg', 'https://phimimg.com/upload/vod/20251014-1/53dc9ff22cd441d239ba239d35b6e476.jpg', '<p>Tiểu Duy là một yêu tinh tu luyện ngàn năm, bị giam giữ dưới mặt hồ băng đã 500 năm và phải hứng chịu những cơn rét lạnh quét vào da thịt vì vi phạm nguyên tắc yêu giới. Tước Nhi cảm mến gương mặt xinh đẹp của Tiểu Duy nên mổ hàn băng giải thoát cho cô. Tiểu Duy tiếp tục cuộc tìm kiếm và cô đã lấy trái tim của hoàng tử Thiên Lang quốc. Nhưng dù vậy, cô vẫn là một yêu quái. Trên hành trình, Tiểu Duy được một chiến binh uy dũng giải cứu khỏi bọn cướp và nhận ra người đó có trái tim nóng ấm, có thể cứu cô khỏi cơn hàn băng. Nhưng chiến binh đó chính là Tĩnh công chúa đang trên đường đến biên giới Bạch Thành tìm Hoắc Tâm. Tĩnh Nhi công chúa có hôn ước với vương tử của Thiên Lang quốc nhưng trên đường cô đã bỏ trốn, đi tìm Hoắc Tâm, trước đây là thị vệ của cô và bây giờ đang giữ biên giới. Hoắc Tâm từ chối tình yêu của công chúa vì mặc cảm thân phận và vì lỗi lầm của quá khứ. Tĩnh Nhi chấp nhận đổi lấy nhan sắc của Tiểu Duy để có được Hoắc Tâm và trao trái tim của mình cho yêu tinh.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Xun","avatar":""},{"name":"Chen Kun","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"William Feng","avatar":""},{"name":"Chen Tingjia","avatar":""},{"name":"Lenox Lu","avatar":""},{"name":"Kris Phillips","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""},{"name":"Li Bingyuan","avatar":""},{"name":"You Benchang","avatar":""},{"name":"Zhang Yilong","avatar":""},{"name":"Qin Junjie","avatar":""},{"name":"Sun Jiankui","avatar":""},{"name":"Morgan Benoit","avatar":""},{"name":"Guan Xiaotong","avatar":""},{"name":"Temur Gang","avatar":""},{"name":"Zhang Dong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["畫皮2 轉生術","Démon vadász: A feltámadás","Pele Pintada: A Ressurreição","妖魔伝　レザレクション","轉生術","妖魔伝 －レザレクション－","畫皮2 之轉生術","画皮2"]', 1784690324464);
