INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-bi-2-thuat-hoi-sinh', 'Họa Bì 2: Thuật Hồi Sinh', 'Painted Skin: The Resurrection', 'họa bì 2: thuật hồi sinh painted skin: the resurrection zhou xun chen kun zhao wei yang mi william feng chen tingjia lenox lu kris phillips gordon liu chia-hui li bingyuan you benchang zhang yilong qin junjie sun jiankui morgan benoit guan xiaotong temur gang zhang dong 畫皮2 轉生術 démon vadász: a feltámadás pele pintada: a ressurreição 妖魔伝　レザレクション 轉生術 妖魔伝 －レザレクション－ 畫皮2 之轉生術 画皮2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-tam-linh', 'Thế Giới Tâm Linh', 'Red Lights', 'https://phimimg.com/upload/vod/20251012-1/15fcd20814453a9003a9c20334233492.jpg', 'https://phimimg.com/upload/vod/20251012-1/7c7c952dcb9c42f61cb7d87c58d077b0.jpg', '<p>Hai nhà điều tra những trò lừa bịp huyền bí, Tiến sĩ Margaret Matheson kỳ cựu và trợ lý trẻ của cô, Tom Buckley, nghiên cứu các hiện tượng siêu hình đa dạng nhất với mục đích chứng minh nguồn gốc lừa đảo của chúng. Simon Silver, một nhà ngoại cảm mù huyền thoại, xuất hiện trở lại sau 30 năm vắng bóng bí ẩn để trở thành thách thức quốc tế lớn nhất đối với cả khoa học chính thống và những người theo chủ nghĩa hoài nghi chuyên nghiệp. Tom bắt đầu phát triển một nỗi ám ảnh mãnh liệt với Silver, người có từ tính trở nên mạnh mẽ hơn với mỗi biểu hiện mới của các sự kiện không thể giải thích được. Khi Tom đến gần Silver hơn, căng thẳng tăng lên và thế giới quan của anh ấy bị đe dọa đến tận cùng.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Garrick Hagon","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Mitchell Mullen","avatar":""},{"name":"Nathan Osgood","avatar":""},{"name":"Madeleine Potter","avatar":""},{"name":"Eloise Webb","avatar":""},{"name":"Jeany Spark","avatar":""},{"name":"Jan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Luces rojas","レッド・ライト","Poderes Ocultos","Les voyants rouges","异能感应","红灯","Red Lights"]', 1784690324464);
