INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-cat-tu-han', 'Thành Cát Tư Hãn', 'Genghis: The Legend of the Ten', 'https://phimimg.com/upload/vod/20251012-1/c3eb614345be9277d30325337982803f.jpg', 'https://phimimg.com/upload/vod/20251012-1/be2e88838d7696a2b2b5c88cb6f93d53.jpg', '<p>Ít ai biết rằng, vị hoàng đế khét tiếng tàn bạo Thành Cát Tư Hãn, thường cưu mang những đứa trẻ mồ côi do chiến tranh, mang chúng về để mẹ ông nuôi dưỡng. Lũ trẻ khi lớn lên, được dạy dỗ để trở thành những chiến binh dũng cảm nhất, trung thành nhất với hoàng đế Mông Cổ, góp phần tạo nên sự vĩ đại của 1 đế chế.</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Baasanjav Mijid","avatar":""},{"name":"Bekh-Ochir Jambal","avatar":""},{"name":"Amarsaikhan Baljinnyam","avatar":""},{"name":"Tserenbold Tsegmid","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Les Dix guerriers de Gengis Khan","Аравт – 10 солдат Чингисхана","Ten Soldiers of Genghis Khan","Aravt"]', 1784690324464);
