INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tuoc-dai', 'Đồng Tước Đài', 'The Assassins', 'https://phimimg.com/upload/vod/20251011-1/021d9b2788868a4f4b23d4d1d2ff2f3f.jpg', 'https://phimimg.com/upload/vod/20251011-1/a136b90bcdb469995fd3735c6d94c765.jpg', '<p>Linh Thư và Mục Thuận là 2 cô nhi bị Triều đình bắt về huấn luyện trở thành những sát thủ với mục đích cuối cùng là sát hại Tào Tháo. Linh Thư và Mục Thuận có tình cảm gắn bó với nhau. Trải qua tuổi thơ trong hầm ngục, ước mơ của Linh Thư là một ngày nào đó thoát khỏi mối ràng buộc với &quot;vận mệnh thiên hạ&quot; để được sống những ngày an nhàn, tự do bên Mục Thuận.</p>', 'Full', 1, 'single', 'completed', 24, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chow Yun-Fat","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Hiroshi Tamaki","avatar":""},{"name":"Alec Su","avatar":""},{"name":"Annie Shizuka Inoh","avatar":""},{"name":"Yau Sam-Chi","avatar":""},{"name":"Yao Lu","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Bao Jianfeng","avatar":""},{"name":"Chi Cheng","avatar":""},{"name":"Eric Qu Quan-Cheng","avatar":""},{"name":"Samuel Pang King-Chi","avatar":""},{"name":"Temur Gang","avatar":""},{"name":"Wang Shengli","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Michael Tong Chun-Chung","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Wang Zezo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["铜雀台","The Assasins","조조-황제의 반란","Tong que tai"]', 1784690324464);
