INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ky-vong-lon-lao', 'Những Kỳ Vọng Lớn Lao', 'Great Expectations', 'https://phimimg.com/upload/vod/20251011-1/44038e95dd5e0a37af168f37fa4889d4.jpg', 'https://phimimg.com/upload/vod/20251011-1/f34d577aa524fd48232831d54f655146.jpg', '<p>Great Expectations là bộ phim chuyển thể năm 2012 từ tiểu thuyết cùng tên của Charles Dickens xuất bản năm 1861. Phim do Mike Newell đạo diễn, ...</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Irvine","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"David Walliams","avatar":""},{"name":"Tamzin Outhwaite","avatar":""},{"name":"Daniel Weyman","avatar":""},{"name":"Jessie Cave","avatar":""},{"name":"Edward Fleming","avatar":""},{"name":"Olly Alexander","avatar":""},{"name":"Kate Lock","avatar":""},{"name":"Pooky Quesnel","avatar":""},{"name":"Ben","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Grandes Esperanzas","Grandi Speranze","Grandes Esperanças","Великі сподівання","Great Expectations"]', 1784690324464);
