INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-lenh-cuoi-cung-thinh-phong-gia', 'Mật Lệnh Cuối Cùng - Thính Phong Giả', 'The Silent War', 'https://phimimg.com/upload/vod/20251009-1/d7bbba8634e5347a2d0f876f985eb1e6.jpg', 'https://phimimg.com/upload/vod/20251009-1/d6dc1cda18002fdc771d47ddc99ab914.jpg', '<p>Một bộ phim gián điệp ly kỳ lấy bối cảnh những năm 1950 và được chuyển thể từ tiểu thuyết &quot;Year Suan/Plot Against&quot; của May Jia. Tony Leung Chiu Wai vào vai một người đàn ông mù làm việc cho một thợ chỉnh đàn piano. Anh được tuyển dụng vào một nhiệm vụ gián điệp vì thính giác đặc biệt của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Zhou Xun","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Wang Xuebing","avatar":""},{"name":"Mavis Fan","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Jacob Cheung","avatar":""},{"name":"Pal Sinn Lap-Man","avatar":""},{"name":"Carrie Ng Ka-Lai","avatar":""},{"name":"Henry Fong Ping","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Silent War","701 รหัสลับคนคม","聽風者","The Chinas Silent War","听风者"]', 1784690324464);
