INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-lenh-cuoi-cung-thinh-phong-gia', 'Mật Lệnh Cuối Cùng - Thính Phong Giả', 'The Silent War', 'mật lệnh cuối cùng - thính phong giả the silent war zhou xun tony leung chiu-wai wang xuebing mavis fan dong yong david lam wai jacob cheung pal sinn lap-man carrie ng ka-lai henry fong ping the silent war 701 รหัสลับคนคม 聽風者 the chinas silent war 听风者', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-vu-truong-an', 'Diệu Vũ Trường An', 'House of Harmony and Vengeance', 'https://phimimg.com/upload/vod/20251008-1/65dbbecc73f9223a3ef96c3b2a9ee69d.jpg', 'https://phimimg.com/upload/vod/20251008-1/1b066ebc95729ebb5f38d81008933756.jpg', '<p>Trong lúc lẩn tránh sự truy bắt của quan binh, nhạc sư đường phố Đới Danh Bạt (do Âu Dương Chấn Hoa đóng) đã mạo danh thân phận quan Đô Tri của Kiều Bộ Long (do Mạch Trường Thanh đóng). Khi Bạt đang hưởng vinh hoa phú quý ở vườn Sưởng Lê của giáo phường, Long chật vật làm đầu bếp cho một trà lầu, với cái tên mới là Cao Nhân. Bạt cố gắng tiếp cận Nhân để học lỏm các thành tựu âm nhạc của anh. Bạt còn thoái hôn với vị hôn thê thuở nhỏ - Biện Ngọc Yên (do Chung Gia Hân đóng). Biết chuyện, Yên không cam tâm, nên quyết định xin làm vũ nương trong giáo phường để tiếp cận Bạt. Yên kết bạn với cô gái bán than hiếu thảo Lợi Tại Sơn (do Hồ Hạnh Nhi đóng), cùng phấn đấu để trở thành những vũ nương giỏi nhất, gọi là vũ ưu. Triều đình tổ chức cuộc thi tuyển chọn hoa khôi từ các vũ ưu. Người đoạt danh hiệu cao quý này có thể được phong làm quận chúa hoặc vương phi. Cũng vì vậy mà Yên và Sơn từ bạn trở thành đối thủ. Tình cảm của họ càng rạn nứt khi cùng vướng vào mối tình tay ba với Bạt.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 18, 2012, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bobby Au-Yeung Tsan-Wah","avatar":""},{"name":"Evergreen Mak Cheung-Ching","avatar":""},{"name":"Myolie Wu Hang-Yee","avatar":""},{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Angela Tong Ying-Ying","avatar":""},{"name":"Yoyo Chen Chi-Yiu","avatar":""},{"name":"JJ Jia","avatar":""},{"name":"Oscar Leung Lit-Wai","avatar":""},{"name":"Sire Ma","avatar":""},{"name":"Grace Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["耀舞长安","耀舞長安"]', 1784690324464);
