INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ngoai-dao-va-ten-trom', 'Kẻ Ngoại Đạo Và Tên Trộm', 'Heathens and Thieves', 'https://phimimg.com/upload/vod/20250930-1/079166c04e19adb110f3ac16098e7c85.jpg', 'https://phimimg.com/upload/vod/20250930-1/70defef56b9180526f936716116f082c.jpg', '<p>Kẻ Ngoại Đạo Và Tên Trộm - Heathens and Thieves Phim kể về Lawmen, một kẻ lang thang với khẩu súng và chuyên đi đánh thuê cho các trại khai thác vàng ở bắc Cali. Khi nghe tin đồn rằng một công nhân đường sắt TQ đã trốn thoát cùng với số vàng của trại và hiện đang ở một trang trại hẻo lánh, Lawmen cùng đồng bọn lập kế hoạch để đánh cắp số vàng cho bản thân.</p>', 'Full', 1, 'single', 'completed', 21, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andrew Simpson","avatar":""},{"name":"Gwendoline Yeo","avatar":""},{"name":"Don Swayze","avatar":""},{"name":"Michael Robert Brandon","avatar":""},{"name":"Boyuen","avatar":""},{"name":"Tom Proctor","avatar":""},{"name":"Joel Patrick Berry","avatar":""},{"name":"Jesse James Youngblood","avatar":""},{"name":"John A. Lorenz","avatar":""},{"name":"Richard Doyle","avatar":""},{"name":"Roy Hall Jr.","avatar":""},{"name":"Bernard Dowling","avatar":""},{"name":"Roy Hall Sr.","avatar":""},{"name":"John Hammond","avatar":""},{"name":"Howard Leonard","avatar":""},{"name":"Ned Nichols","avatar":""},{"name":"Cod","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Heathens and Thieves - Das Glück ist mit dem Bösen","Heathens and Thieves"]', 1784690324464);
