INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-vien-kiem-thien-chi-ngan', 'Hiên Viên Kiếm: Thiên Chi Ngân', 'Xuan-Yuan Sword: Scar Of Sky', 'https://phimimg.com/upload/vod/20250927-1/623aff588d6cba65e1a24fd25a25f250.jpg', 'https://phimimg.com/upload/vod/20250927-1/4ef67443d53aecb416caebb4b0905639.jpg', '<p>Truyền thuyết từ ngàn xưa để lại. Khi chòm sao yêu tinh Xích Quán đi đến nhân gian, hồng trần tất xảy ra tai họa long trời lở đất. Khi chòm sao yêu Xích Quán lại đến lần nữa. Ngũ đại thần khí thời thượng cổ cũng sẽ xuất hiện theo nó: Kính Côn Luân, Đỉnh Thần Nông, Đàn Phục Hy, Ấn Không Đồng và Đá Nữ Oa. Tương truyền ai có thể đoạt được ngũ đại thần khí sẽ trở thành Đại địa hoàng giả, thống lĩnh thiên hạ.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 12, 2012, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Đồng","avatar":""},{"name":"Hồ Ca","avatar":""},{"name":"Trịnh Phối Phối","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Xuan Yuan Jian Zhi Tian Zhi Hen","Xuan Yuan Sword Scar of Sky","Xuan Yuan Sword - Rift of the Sky","轩辕剑之天之痕"]', 1784690324464);
