INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-den-cuoc-vay-ham-thanh-doldrey', 'Kỵ Sĩ Đen: Cuộc Vây Hãm Thành Doldrey', 'Berserk: The Golden Age Arc II - The Battle For Doldrey', 'https://phimimg.com/upload/vod/20250923-1/4dd20b75347a62c1c4e2eecfd20adeae.jpg', 'https://phimimg.com/upload/vod/20250923-1/07166bc9fd44ef6574a61db63632fd1f.jpg', '<p>Đội quân Chim ưng và thủ lĩnh bí ẩn của họ, Griffith, tiếp tục giành chiến thắng trong hết trận chiến này đến trận chiến khác, danh tiếng của họ ngày càng vang dội khắp vương quốc Midland. Nhưng nhiệm vụ gần đây nhất của họ là một thử thách mà bất kỳ ai từng cố gắng đều đã thất bại: chinh phục pháo đài Doldrey tưởng chừng bất khả xâm phạm.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroaki Iwanaga","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Toa Yukinari","avatar":""},{"name":"Takahiro Fujiwara","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Yoshiaki Matsumoto","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Keisuke Sogo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Berserk - L''epoca d''oro - Capitolo II - La conquista di Doldrey","베르세르크 황금시대편Ⅱ  돌드레이 공략 (2012)","Berserk Ōgon Jidai-hen II Dorudorei kōryaku","Berserk: Ougon Jidai-hen II - Doldrey Kouryaku","Berserk: The Golden Age Arc 2 - The Battle for Doldrey","ベルセルク 黄金時代篇Ⅱ ドルドレイ攻略"]', 1784690324464);
