INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-si-den-cuoc-vay-ham-thanh-doldrey', 'Kỵ Sĩ Đen: Cuộc Vây Hãm Thành Doldrey', 'Berserk: The Golden Age Arc II - The Battle For Doldrey', 'kỵ sĩ đen: cuộc vây hãm thành doldrey berserk: the golden age arc ii - the battle for doldrey hiroaki iwanaga takahiro sakurai toa yukinari takahiro fujiwara yuki kaji minako kotobuki rikiya koyama yoshiaki matsumoto kenta miyake kazuki yao keisuke sogo berserk - l''epoca d''oro - capitolo ii - la conquista di doldrey 베르세르크 황금시대편ⅱ  돌드레이 공략 (2012) berserk ōgon jidai-hen ii dorudorei kōryaku berserk: ougon jidai-hen ii - doldrey kouryaku berserk: the golden age arc 2 - the battle for doldrey ベルセルク 黄金時代篇ⅱ ドルドレイ攻略', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-den-qua-trung-cua-nha-vua', 'Kỵ Sĩ Đen: Quả Trứng Của Nhà Vua', 'Berserk: The Golden Age Arc I - The Egg Of The King', 'https://phimimg.com/upload/vod/20250923-1/670bfac24226d4f78a12a1c76a4b1409.jpg', 'https://phimimg.com/upload/vod/20250923-1/069e645029a47147a3562b0a2a1a4374.jpg', '<p>Guts, một lính đánh thuê với sức mạnh kinh người, có một cuộc sống vô định, chỉ đơn thuần là hết trận chiến này đến trận chiến khác. Tuy nhiên, mọi thứ đột ngột thay đổi khi anh gặp và bị đánh bại bởi Griffith, một chàng trai trẻ đẹp và lôi cuốn, thủ lĩnh của đội quân lính đánh thuê có tên Đội quân Chim ưng (Band of the Hawk). Sau khi Guts gia nhập đội quân, mối quan hệ giữa hai người bắt đầu phát triển, trong khi đó, Casca, nữ kiếm sĩ mạnh mẽ và duy nhất trong Đội quân Chim ưng, lại chật vật để chấp nhận Guts và tầm ảnh hưởng mà anh mang lại. Khi hai người đàn ông bắt đầu cùng nhau chiến đấu, Griffith tiếp tục vươn lên nắm quyền lực, tất cả dường như là để đạt được những mục tiêu bí ẩn đã được tiên đoán trước của anh. Guts và Griffith sẽ phải đi đến đâu để đạt được những mục tiêu này, và số phận sẽ đưa hai người họ về đâu?</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroaki Iwanaga","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Takahiro Fujiwara","avatar":""},{"name":"Toa Yukinari","avatar":""},{"name":"Yoshiaki Matsumoto","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Nobuyuki Katsube","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Hiroshi Arikawa","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Kendo Kobayashi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Berserk - L''Age d''Or - L''œuf du Roi Conquérant","Berserk - La Edad de Oro I - El huevo del rey conquistador","Berserk - L''epoca d''oro - Capitolo I - L''uovo del re dominatore","베르세르크 황금 시대편 I : 패왕의 알","ベルセルク 黄金時代篇I 覇王の卵","Berserk - Das goldene Zeitalter I","Berserk: The Golden Age Arc - The Egg of the King","Berserk Film 1: The High King''s Egg","베르세르크 황금시대편Ⅰ  패왕의 알","Berserk Ôgon Jidai-Hen I: Haô no Tamago","Beruseruku Ōgon Jidai-hen Wan Haō no Tamago","베르세르크 황금시대편 I  패왕의 알","베르세르크 황금시대편 I - 패왕의 알","Berserk: Ougon Jidai-hen I - Haou no Tamago","Berserk: Golden Age Arc I - Egg of the Supreme Ruler","Berserk: The Golden Age Arc 1 - The Egg of the King","Berserk - The Golden Age Arc I: The High King''s Egg"]', 1784690324464);
