INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-si-den-qua-trung-cua-nha-vua', 'Kỵ Sĩ Đen: Quả Trứng Của Nhà Vua', 'Berserk: The Golden Age Arc I - The Egg Of The King', 'kỵ sĩ đen: quả trứng của nhà vua berserk: the golden age arc i - the egg of the king hiroaki iwanaga takahiro sakurai yuki kaji takahiro fujiwara toa yukinari yoshiaki matsumoto minako kotobuki kazuki yao aki toyosaki kenta miyake nobuyuki katsube rikiya koyama hiroshi arikawa hochu otsuka kendo kobayashi berserk - l''age d''or - l''œuf du roi conquérant berserk - la edad de oro i - el huevo del rey conquistador berserk - l''epoca d''oro - capitolo i - l''uovo del re dominatore 베르세르크 황금 시대편 i : 패왕의 알 ベルセルク 黄金時代篇i 覇王の卵 berserk - das goldene zeitalter i berserk: the golden age arc - the egg of the king berserk film 1: the high king''s egg 베르세르크 황금시대편ⅰ  패왕의 알 berserk ôgon jidai-hen i: haô no tamago beruseruku ōgon jidai-hen wan haō no tamago 베르세르크 황금시대편 i  패왕의 알 베르세르크 황금시대편 i - 패왕의 알 berserk: ougon jidai-hen i - haou no tamago berserk: golden age arc i - egg of the supreme ruler berserk: the golden age arc 1 - the egg of the king berserk - the golden age arc i: the high king''s egg', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fairy-tail-nu-te-cua-phuong-hoang', 'Fairy Tail: Nữ Tế Của Phượng Hoàng', 'Fairy Tail: Phoenix Priestess', 'https://phimimg.com/upload/vod/20250919-1/557bf571f043c14f66a458ee9793ada2.jpg', 'https://phimimg.com/upload/vod/20250919-1/2f59d7a36295d0f4b3576497ca6c9ac9.jpg', '<p>Ở vùng núi phía bắc Fiore là Ngôi làng Lửa, nơi lưu giữ một di tích màu xanh lam tươi tốt được gọi là Đá Phượng hoàng. Được giao cho một người phụ nữ bí ẩn tên là Éclair, nó được cho là chứa sức mạnh của một con phượng hoàng cổ đại. Cô ấy lang thang khắp vùng đất một mình và bảo vệ viên đá khỏi bị tổn hại, mặc dù không nhớ tại sao nó lại được cô chăm sóc và chỉ có một hồi ức mờ nhạt nhất về nơi cô phải lấy nó. &nbsp;Sau khi chạm trán với hội phù thủy Fairy Tail, Éclair nhận được lời đề nghị từ Natsu Dragneel và những người bạn của anh để giúp cô khám phá những bí ẩn xung quanh viên đá. Tuy nhiên, giữa cuộc hành trình của cả nhóm, Éclair bất ngờ bị tấn công và viên đá bị lấy đi từ cô. Với điều này, những ý định bất chính nhằm hồi sinh phượng hoàng rực lửa vì sức mạnh vô song của nó được đưa ra ánh sáng, và các pháp sư của Fairy Tail thấy mình trong một tình huống có thể gieo rắc tai họa. Bây giờ họ phải cùng nhau ngăn chặn sự hồi sinh của phượng hoàng và cứu thế giới khỏi đống đổ nát.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Mika Kanai","avatar":""},{"name":"Shinpachi Tsuji","avatar":""},{"name":"Ryoko Ono","avatar":""},{"name":"Wataru Hatano","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Mai Nakahara","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Harumi Sakurai","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Kat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fairy Tail - La prêtresse du Phoenix","Fairy Tail: The Phoenix Priestess","Fairy Tail the Movie: Phoenix Priestess","Fairy Tail - le film : la prêtresse du Phoenix","Fairy Tail Movie 1 Houou no Miko","劇場版 FAIRY TAIL -鳳凰の巫女-","Сказка о Хвосте феи: Жрица Феникса","Хвост Феи: Жрица Феникса","Сказка о хвосте феи: Жрица Жар-птицы","Fairy Tail: Houou no Miko","魔导少年剧场版：凤凰巫女","劇場版 FAIRY TAIL 鳳凰の巫女"]', 1784690324464);
