INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('fairy-tail-nu-te-cua-phuong-hoang', 'Fairy Tail: Nữ Tế Của Phượng Hoàng', 'Fairy Tail: Phoenix Priestess', 'fairy tail: nữ tế của phượng hoàng fairy tail: phoenix priestess tetsuya kakihara aya hirano rie kugimiya yuichi nakamura sayaka ohara satomi sato yui horie aya endo mika kanai shinpachi tsuji ryoko ono wataru hatano hiroki touchi mai nakahara eri kitamura hiroki yasumoto harumi sakurai mariya ise kat fairy tail - la prêtresse du phoenix fairy tail: the phoenix priestess fairy tail the movie: phoenix priestess fairy tail - le film : la prêtresse du phoenix fairy tail movie 1 houou no miko 劇場版 fairy tail -鳳凰の巫女- сказка о хвосте феи: жрица феникса хвост феи: жрица феникса сказка о хвосте феи: жрица жар-птицы fairy tail: houou no miko 魔导少年剧场版：凤凰巫女 劇場版 fairy tail 鳳凰の巫女', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-sieu-anh-hung', 'Biệt Đội Siêu Anh Hùng', 'The Avengers', 'https://phimimg.com/upload/vod/20250517-1/63af625c8e64e37cefb78667309cf9e1.jpg', 'https://phimimg.com/upload/vod/20250517-1/2f379fa692f6cdbd440d34bf367cccfb.jpg', '<p>The Avengers là bộ phim giả tưởng kể về một nhóm siêu anh hùng với những khả năng đặc biệt, họ bao gồm: Người Sắt, Thor, Đội trưởng Mỹ, và Người Khổng Lồ Xanh Hulk cùng tham gia với tổ chức bảo vệ thế giới SHIELD. Mục đích của SHIELD là nhằm bảo vệ Trái Đất khỏi âm mưu hủy hoại của những thế lực xấu từ ngoài địa cầu mà kẻ cầm đầu là Loki.</p>', 'Full', 1, 'single', 'completed', 22, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Alexis Denisof","avatar":""},{"name":"Tina Benko","avatar":""},{"name":"Jerzy Skolimows","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b61