INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-sieu-anh-hung', 'Biệt Đội Siêu Anh Hùng', 'The Avengers', 'biệt đội siêu anh hùng the avengers robert downey jr. chris evans mark ruffalo chris hemsworth scarlett johansson jeremy renner tom hiddleston clark gregg cobie smulders stellan skarsgård samuel l. jackson gwyneth paltrow paul bettany alexis denisof tina benko jerzy skolimows avengers assemble avengers 3d the avengers 3d the avengers: an imax 3d experience marvel''s avengers assemble ดิ อเวนเจอร์ส 1 marvel''s the avengers vengadores os vingadores marvel: los vengadores 어벤져스 마블 어벤져스 мститeли 复仇者联盟 biệt đội siêu anh hùng avengers gfh the avengers: os vingadores アベンジャーズ վրիժառուները अवेंजर्स अंगारे बने शोले the avengers: los vengadores de marvel المنتقمون the avengers', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-go', 'Điềm Gở', 'Sinister', 'https://phimimg.com/upload/vod/20250914-1/d7292e311eb597bfaba3fb499d791f62.jpg', 'https://phimimg.com/upload/vod/20250914-1/cef9440d663b21b51cf510a319fdc5a9.jpg', '<p>Nhà văn chuyên viết tội phạm có thật Ellison Oswald (Ethan Hawke) đang sa sút; anh ấy đã không có một cuốn sách bán chạy nhất trong hơn 10 năm và ngày càng trở nên tuyệt vọng với một bản hit. Vì vậy, khi anh phát hiện ra sự tồn tại của một bộ phim lén cho thấy cái chết của một gia đình, anh thề sẽ giải quyết bí ẩn. Anh ta chuyển gia đình của mình đến nhà của các nạn nhân và bắt đầu làm việc. Tuy nhiên, khi những thước phim cũ và những manh mối khác gợi ý về sự hiện diện của một thế lực siêu nhiên, Ellison biết rằng sống trong ngôi nhà có thể gây tử vong.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Juliet Rylance","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"Clare Foley","avatar":""},{"name":"Michael Hall D''Addario","avatar":""},{"name":"Victoria Leigh","avatar":""},{"name":"Blake Mizrahi","avatar":""},{"name":"Cameron Ocasio","avatar":""},{"name":"Danielle Kotch","avatar":""},{"name":"Ethan Haberfield","avatar":""},{"name":"Nicholas King","avatar":""},{"name":"Tavis Smiley","avatar":""},{"name":"Rachel Konstantin","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Found Footage","Untitled Scott Derrickson Project","フッテージ","Siniestro","Sinister"]', 1784690324464);
