INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diem-go', 'Điềm Gở', 'Sinister', 'điềm gở sinister ethan hawke juliet rylance vincent d''onofrio james ransone fred thompson clare foley michael hall d''addario victoria leigh blake mizrahi cameron ocasio danielle kotch ethan haberfield nicholas king tavis smiley rachel konstantin c found footage untitled scott derrickson project フッテージ siniestro sinister', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-sieu-dang', 'Người Nhện Siêu Đẳng', 'The Amazing Spider-Man', 'https://phimimg.com/upload/vod/20250707-1/e85e85d591b947b1e639983d09d2de5d.jpg', 'https://phimimg.com/upload/vod/20250707-1/5fe0d95859f9ab7b752352028971ed34.jpg', '<p>Amazing Spider-Man hay Siêu Nhện Tái Xuất có khá nhiều khác biệt so với các phần trước tập trung ở sự khác biệt ở tính cách của các nhân vật, Peter không còn là cậu bé nhút nhát mà khá nghịch ngợm, bên cạnh đó đạo diễn Marc Webb cũng mạnh dạn đưa ra thêm nhiều thay đổi về cốt truyện để Amazing Spider-Man thực sự mới lạ so với các phiên bản cũ. Cha mẹ Peter biến mất bí ấn và để cậu cho cô chú nuôi nấng. Sự tò mò về thân phận của bản thân lẫn những điều chưa biết về cha mẹ luôn thôi thúc cậu. Peter tìm thấy tập tài liệu mà cha để lại. Từ đây, những manh mối dẫn cậu tới tập đoàn Oscorp và người cộng sự của ông. Một tai nạn tại Oscorp khiến Peter có những siêu năng lực của loài nhện, Người nhện xuất hiện bí ẩn trong lòng New York.</p>', 'Full', 1, 'single', 'completed', 24, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Irrfan Khan","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Chris Zylka","avatar":""},{"name":"Max Charles","avatar":""},{"name":"C. Thomas Howell","avatar":""},{"name":"Jake Keiffer","avatar":""},{"name":"Kari Coleman","avatar":""},{"name":"Michael Barra","avatar":""},{"name":"Leif Gantvoort","avatar":""},{"name":"Andy Pessoa","avatar":""},{"name":"Hannah Marks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yangi O''rgimchak odam","Amazing Spider-Man","გასაოცარი ობობა-კაცი","საოცარი ადამიანი-ობობა","საოცარი ობობა-კაცი","საოცარი სპაიდერმენი","გასაოცარი სპაიდერმენი","Amazing Spider-Man 1","The Amazing Spider-Man I","アメイジング・スパイダーマン：2012","Người Nhện Siêu Đẳng","El Sorprendente Hombre Araña","超凡蜘蛛侠1 (安德鲁·加菲尔德)","წარმოუდგენელი ადამიანი-ობობა","الرجل العنكبوت المذهل","The Amazing Spider-Man"]', 1784690324464);
