INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-nhen-sieu-dang', 'Người Nhện Siêu Đẳng', 'The Amazing Spider-Man', 'người nhện siêu đẳng the amazing spider-man andrew garfield emma stone rhys ifans denis leary martin sheen sally field irrfan khan campbell scott embeth davidtz chris zylka max charles c. thomas howell jake keiffer kari coleman michael barra leif gantvoort andy pessoa hannah marks yangi o''rgimchak odam amazing spider-man გასაოცარი ობობა-კაცი საოცარი ადამიანი-ობობა საოცარი ობობა-კაცი საოცარი სპაიდერმენი გასაოცარი სპაიდერმენი amazing spider-man 1 the amazing spider-man i アメイジング・スパイダーマン：2012 người nhện siêu đẳng el sorprendente hombre araña 超凡蜘蛛侠1 (安德鲁·加菲尔德) წარმოუდგენელი ადამიანი-ობობა الرجل العنكبوت المذهل the amazing spider-man', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-cung', 'Hậu Cung', 'The Concubine', 'https://phimimg.com/upload/vod/20250808-1/8e2d369c259704b9949f01af1f1467b7.jpg', 'https://phimimg.com/upload/vod/20250808-1/6c55fab9cd58bb2e872b4419fc6e8cc4.jpg', '<p>Là những năm đầu của triều đại Chosun, bộ phim xoay quanh ba nhân vật: Hwa Yeon, con gái của một tướng quân đương triều, người đã chấp nhận tiến cung để bảo vệ người yêu. Kwon Yoo, người đàn ông luôn bị dằng xé giữa tình yêu và thù hận. Vua Seong Won với tình yêu đầy đam mê nhục dục với Hwa Yeon dù có biết bao cung tần vây quanh.
 Trong cái thế giới bị chi phối bởi quyền lực, ba nhân vật chính lặn lội trong cuộc chiến tình, quyền và thù. Cho đến cuối cùng điều gì sẽ thắng? Nhấn mạnh vào tấn bi kịch của triều đại và hoàng cung, The Concubine mang đến khán giả một cái nhìn toàn diện về cuộc chiến chốn thâm cung, nơi mà dục vọng, lòng ham muốn và sự tham lam của con người luôn ngự trị, đồng thời, những âm mưu đáng sợ đối với ngai vàng cũng được thể hiện một cách sinh động và đầy lôi cuốn</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Yeo-jeong","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Kim Min-jun","avatar":""},{"name":"Park Ji-young","avatar":""},{"name":"Cho Eun-ji","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Ahn Suk-hwan","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Oh Ji-hye","avatar":""},{"name":"Hong Kyeong-yeon","avatar":""},{"name":"Hong Yeo-jin","avatar":""},{"name":"Oh Hyeon-kyeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["후궁 : 제왕의 첩","The Concubine","Hugoong: Jewangui Chub","Royal Concubine: Concubine of King","King''s Concubine","The Queen","滿宮春","後宮：色慾天下","Hugoong Jewangui Chub","معشوقه پادشاه","صیغه","صیغه پادشاه","後宮の秘密：2012","후궁: 제왕의 첩"]', 1784690324464);
