INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hau-cung', 'Hậu Cung', 'The Concubine', 'hậu cung the concubine cho yeo-jeong kim dong-wook kim min-jun park ji-young cho eun-ji lee kyung-young ahn suk-hwan park cheol-min oh ji-hye hong kyeong-yeon hong yeo-jin oh hyeon-kyeong 후궁 : 제왕의 첩 the concubine hugoong: jewangui chub royal concubine: concubine of king king''s concubine the queen 滿宮春 後宮：色慾天下 hugoong jewangui chub معشوقه پادشاه صیغه صیغه پادشاه 後宮の秘密：2012 후궁: 제왕의 첩', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-nang-anna-karenina', 'Chuyện Tình Nàng Anna Karenina', 'Anna Karenina', 'https://phimimg.com/upload/vod/20250814-1/fe9fdb6894b56b2c55de9fcb053722de.jpg', 'https://phimimg.com/upload/vod/20250814-1/e784738ce3500ce7794dae841ecb7bb6.jpg', '<p>Dù ở đâu vào thời kỳ nữ quyền chưa lên ngôi, rất ít phụ nữ có được hạnh phúc trong hôn nhân. Trong bối cảnh châu Âu thế kỷ XIX, Anna cũng chịu số phận chua xót như vậy. Đang trong độ tuổi thanh xuân phơi phới, nàng phải kết hôn với người đàn ông hơn mình rất nhiều tuổi, một người mình không hề yêu, một người cứng nhắc và chẳng hề lãng mạn. Cuộc hôn nhân ấy được sắp xếp bởi người cô ham tiền và địa vị, không màng đến sự chấp thuận của Anna. Sánh đôi bên chồng, bá tước Karenin, người cống hiến cả đời mình cho lý tưởng nước Nga, Anna trở thành hình mẫu phu nhân được ao ước trong giới thượng lưu. Dù luôn xuất hiện xinh đẹp và rạng rỡ, trở thành trung tâm của mọi sự chú ý nhưng bên ngoài càng đẹp đẽ, lấp lánh bao nhiêu, tâm hồn nàng lại càng u uất và buồn khổ bấy nhiêu. Còn gì đau đớn hơn việc chung sống với người mình không yêu? Cho đến khi Anna gặp Vronsky và khiêu vũ với chàng, ngọn lửa nhiệt thành trong trái tim nàng mới thực sự bùng cháy. Lần đầu tiên sau 8 năm trời đằng đẵng giam cầm tuổi trẻ bên chồng, trái tim nàng xao động, không thể khước từ tiếng gọi của tình yêu.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Eric MacLennan","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Raphaël Personnaz","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Emerald Fennell","avatar":""},{"name":"Tannish","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["안나 카레니나","Chuyện Tình Anna","安娜．卡列尼娜","อันนา คาเรนิน่า รักร้อนซ่อนชู้","อันนา คาเรนินา","Anna Karenina"]', 1784690324464);
