INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('to-loveru-darkness', 'To Love-Ru Darkness', 'To LOVE-Ru Darkness', 'to love-ru darkness to love-ru darkness akeno watanabe haruka tomatsu misato fukuen sayuri yahagi kanae itou aki toyosaki kaori nazuka ayako kawasumi ryoka yuzuki 出包王女 to love-ru to loveるーとらぶるー to loveるーとらぶるーダークネス to loveるーとらぶるーダークネス 2nd もっとto loveるーとらぶるー motto to love-ru 투 러브-루 트러블 투 러브 트러블 to love 트러블 любовь и прочие неприятности ทูเลิฟรู ทูเลิฟรู ดาร์กเนส to love-ru trouble darkness motto to love ru to love ru darkness to loveる -とらぶる-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-than-tap-su-phan-1', 'Thổ Thần Tập Sự (Phần 1)', 'Kamisama Kiss (Season 1)', 'https://phimimg.com/upload/vod/20250728-1/be86c74bef74498a0da58cc813e9e4dc.jpg', 'https://phimimg.com/upload/vod/20250728-1/46383ddd39461927fb2cb746ba0a5672.jpg', '<p>Vì người cha đam mê cờ bạc, mắc phải một món nợ lớn mà rời nhà, Nanami phiêu bạt nơi đầu đường xó chợ. Lúc đó nàng ấy trợ giúp một đàn ông thần bí bị con chó đuổi. Sau được biết cảnh ngộ của Nanami, đàn ông thần bí đó nói: “Thế thì ta cho nàng căn nhà của mình thôi!” Dù chưa tin hẳn, nhưng Nanami vẫn đến với “căn nhà” kia vì nàng ấy không có nơi ở nữa. Hóa ra căn nhà kia lại là một đền thờ đã bị bỏ hoang. Còn Tomoe, một người tự xưng là yêu quái cáo hầu hạ Thổ thần, xuất hiện và người đàn ông thần bí đó lại là Thổ thần. Ông ấy không chỉ cho Nanami căn nhà, mà còn nhượng chức Thổ thần cho nàng ấy. Vậy nên, cuộc sống Thổ thần của Nanami được bắt đầu...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Horie","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Daisuke Kishio","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Vanilla Yamazaki","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Shuta Morishima","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Shinnosuke Tachibana","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Natsuyo Atarashi","avatar":""},{"name":"Chika Ookubo","avatar":""},{"name":"Hiroki Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae