INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nha-mot-minh-5-phi-vu-ngay-le', 'Ở Nhà Một Mình 5 (Phi Vụ Ngày Lễ)', 'Home Alone 5 : The Holiday Heist', 'https://phimimg.com/upload/vod/20250722-1/11d98d93ab3a9658eb92096e257d288e.jpg', 'https://phimimg.com/upload/vod/20250722-1/cfed235bd64491c9ebf052b3dd1521a3.jpg', '<p>Kevin McCallister hiện đang sống với mẹ sau khi bố mẹ cậu ly hôn. Cậu quyết định dành Giáng Sinh cùng bố tại dinh thự của Natalie – bạn gái giàu có của ông. Trong khi đó, tên trộm Marv Merchants, một trong những kẻ xấu từ hai phần phim trước, bắt tay với tội phạm mới tên Vera để đột nhập vào dinh thự của Natalie.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Christian Martyn","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Eddie Steeples","avatar":""},{"name":"Doug Murray","avatar":""},{"name":"Ellie Harvie","avatar":""},{"name":"Peter DaCunha","avatar":""},{"name":"Bill Turnbull","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Adriana O''Neil","avatar":""},{"name":"Gordon Tanner","avatar":""},{"name":"Bryan Terrell Clark","avatar":""},{"name":"Chris Sigurdson","avatar":""},{"name":"Pamela Iveta","avatar":""},{"name":"Sandy Taronno","avatar":""},{"name":"Kari","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Home Alone 5: Alone in the Dark","나