INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-gau-ted', 'Chú Gấu Ted', 'Ted', 'https://phimimg.com/upload/vod/20250712-1/8d22b57a30616a1c578a5a7046f5a4a0.jpg', 'https://phimimg.com/upload/vod/20250712-1/465f6b0a9566b150ee525642805a4d2d.jpg', '<p>Trong đêm Giáng sinh chú bé John đã ước Ted có thể cử động và nói chuyện được, thật bất ngờ điều ước trở thành hiện thực. Cuộc sống của John đã hoàn toàn thay đổi từ đó những rắc rối xuất hiện khi John ở tuổi “Băm” lăm. Ted không đơn giản chỉ là câu chuyện của cậu bé và con gấu bông mà chứa đựng trong những điều giản đơn đó là những thông điệp ý nghĩa từ cuộc sống mà tác giả muốn nhắn nhủ, qua bộ phim người xem sẽ rút ra cho chính mình. Ted thực sự là bộ phim hài hước kiểu người lớn rất đáng xem.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Jessica Barth","avatar":""},{"name":"Aedin Mincks","avatar":""},{"name":"Bill Smitrovich","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Norah Jones","avatar":""},{"name":"Sam J. Jones","avatar":""},{"name":"Tom Skerritt","avatar":""},{"name":"Bretton Manley","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356