INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-que-phuong-2', 'Lan Quế Phường 2', 'Lan Kwai Fong 2', 'https://phimimg.com/upload/vod/20250614-1/6a81d069270a4f63bb95b9aaa705d48e.jpg', 'https://phimimg.com/upload/vod/20250614-1/54c996f14c8ff1f7a3923d48d6b0f5a6.jpg', '<p>Chiều 24/7, trailer đầu tiên của bộ phim điện ảnh Hỷ ái dạ bồ 2 đã chính thức được công bố trên các phương tiện thông tin đại chúng. Ngay sau đó, nó đã được lan truyền với tốc độ nhanh tới &quot;chóng mặt&quot; và trở thành chủ đề thảo luận sôi nổi của giới trẻ Trung Quốc.Điểm gây chú ý đầu tiên là sự xuất hiện của &quot;thiên thần sexy&quot; Trần Tĩnh Nghĩa với trang phục khá &quot;mát mẻ&quot;: hầu hết là bikini và áo 2 dây, váy siêu ngắn. Gương mặt trong sáng từng được mệnh danh là Tiểu long nữ của Hồng Kông nay đã &quot;lột xác&quot; hoàn toàn với hình ảnh quyến rũ tột cùngBên cạnh đó, tần xuất và số lượng cảnh quay tình ái cuồng nhiệt được đạo diễn Tiền Quốc Vỹ mạnh tay khai thác, khiến người xem đi từ mừng rỡ đến...ngại ngùng. Và ...</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Shiga Lin Si-Nga","avatar":""},{"name":"Kelvin Kwan","avatar":""},{"name":"Sammy Sum Chun-Hin","avatar":""},{"name":"Liu Yuqi","avatar":""},{"name":"Avis Chan","avatar":""},{"name":"Mia Chan Ching-Yi","avatar":""},{"name":"Cheuk Wan-Chi","avatar":""},{"name":"Linah Matsuoka","avatar":""},{"name":"Dominic Ho Hou-Man","avatar":""},{"name":"Angelina Zhang","avatar":""},{"name":"Adason Lo","avatar":""},{"name":"Daniel Chau","avatar":""},{"name":"Sita Chan","avatar":""},{"name":"Liddy Li","avatar":""},{"name":"Jaime Fong","avatar":""},{"name":"Chiang Man Kit","avatar":""},{"name":"Vanko Wong","avatar":""},{"name":"Calinda Chan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Lan kwai fong 2","喜愛夜蒲2","兰桂坊2"]', 1784690324464);
