INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-sinh-ai-tinh', 'Thiên Sinh Ái Tình', 'Natural Born Lovers', 'https://phimimg.com/upload/vod/20250609-1/4b3fc00a637e71d160f24f8d5a8da29a.jpg', 'https://phimimg.com/upload/vod/20250609-1/2a9f09b2e4efedc17bdc4c8a7ac067f4.jpg', '<p>Được thực hiện dưới sự chỉ đạo của đạo diễn Diệp Niệm Sâm và có sự góp mặt của hai diễn viên tài năng Trương Trí Lâm và Lưu Tâm Du, bộ phim điện ảnh Thiên sinh ái tình cuồng (Natural Born Lovers) đã ra mắt khán giả Hong Kong từ ngày 25/10 vừa rồi. Với cốt truyện hài hước, lôi cuốn, bộ phim nhanh chóng trở thành hit và tính đến đầu tháng 11 đã thu hút được hơn 4 triệu khán giả.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Julian Cheung Chi-Lam","avatar":""},{"name":"Annie Liu Xin-You","avatar":""},{"name":"Anna Kay","avatar":""},{"name":"Ciwi Lam Sze-Man","avatar":""},{"name":"Kathy Tong Yee","avatar":""},{"name":"Jinny Ng","avatar":""},{"name":"Ava Yu Kiu","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Mandy Lieu","avatar":""},{"name":"Johnson Yuen Tak-Cheung","avatar":""},{"name":"Oscar Leung Lit-Wai","avatar":""},{"name":"Jason Chan Pak-Yu","avatar":""},{"name":"Linah Matsuoka","avatar":""},{"name":"Christine Kuo Yun-Hui","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["天生愛情狂"]', 1784690324464);
