INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-chien', 'Nghịch Chiến', 'The Viral Factor', 'https://phimimg.com/upload/vod/20250607-1/94086016a02da2190b4fb71171e25659.jpg', 'https://phimimg.com/upload/vod/20250607-1/5edcaf17fa2b62944a90ec9ccafb7313.jpg', '<p>Mang nguy cơ bị liệt hoàn toàn, cảnh sát Vạn Phi về nhà thăm mẹ và bỗng biết được mình có một người anh thất lạc. Khi đến tìm anh trai, Vạn Phi không ngờ cuộc gặp đó lại mở ra sự thật đầy ngang trái.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Kiệt Luân","avatar":""},{"name":"Tạ Đình Phong","avatar":""},{"name":"An Chí Kiệt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["逆戰","Jik zin","The Viral Factor","Tehlike Faktörü","逆战","ویروس"]', 1784690324464);
