INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cuu-hoa-chicago-2012', 'Đội Cứu Hoả Chicago (Phần 1)', 'Chicago Fire (Season 1)', 'https://phimimg.com/upload/vod/20250517-1/102c83e607c0ad28fcc763c7effb0fde.jpg', 'https://phimimg.com/upload/vod/20250517-1/e78b9fe386608f277511c0270a9f176b.jpg', '<p>Góc nhìn trực tiếp về cuộc sống hàng ngày của những anh hùng với một trong những nghề cao quý nhất của nước Mỹ. &nbsp;Đối với các nhân viên cứu hỏa, đội cứu hộ và nhân viên y tế của Chicago Firehouse 51, không có nghề nghiệp nào căng thẳng hoặc nguy hiểm hơn, nhưng lại đáng làm và phấn khích như vậy. &nbsp;Những người đàn ông và phụ nữ can đảm này là một trong số những người ưu tú đâm đầu vào nguy hiểm khi những người khác đang chạy theo hướng khác và hành động của họ tạo ra sự khác biệt giữa sự sống và cái chết.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Kinney","avatar":""},{"name":"David Eigenberg","avatar":""},{"name":"Joe Miñoso","avatar":""},{"name":"Christian Stolte","avatar":""},{"name":"Miranda Rae Mayo","avatar":""},{"name":"Daniel Kyri","avatar":""},{"name":"Hanako Greensmith","avatar":""},{"name":"Jocelyn Hudon","avatar":""},{"name":"Jake Lockett","avatar":""},{"name":"Dermot Mulroney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chicago Fire : Caserne 51","风城烈火","芝加哥烈火群英","Chicago fire","שיקגו Fire","שיקגו פייר","آتش‌نشانی شیکاگو","Чикаго в огне","One Chicago","Chicago Fire"]', 1784690324464);
