INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hobbit-hanh-trinh-vo-dinh', 'Người Hobbit: Hành Trình Vô Định', 'The Hobbit: An Unexpected Journey', 'https://phimimg.com/upload/vod/20250531-1/e9301d1c4a7d4f0b315f0c0974f71b70.jpg', 'https://phimimg.com/upload/vod/20250531-1/1af4d14c37fc5b1b69cdf7ed5923df3e.jpg', '<p>The Hobbit: Hành Trình Vô Định đưa người xem trở về với thế giới Trung Địa huyền ảo và tham gia vào cuộc hành trình vô định của Bilbo Baggins - chú của nhân vật Frodo. Lấy mốc thời gian trước những sự kiện xảy ra trong ba phần Chúa Nhẫn, phim xoay quanh nhân vật Bilbo Baggins, người bị cuốn vào một chuyến phiêu lưu phi thường để đoạt lại xứ sở Người Lùn đang bị chiếm giữ bởi con rồng khổng lồ Smaug. Cùng đi của Bilbo là Pháp sư Gandalf Áo Xám và 13 thành viên tộc Người Lùn mà dẫn đầu là hoàng tử Thorin Oakensheild. Cuộc hành trình đưa họ tới những vùng đất kỳ lạ của Trung Địa - nơi có những vị tiên lộng lẫy, những con yêu tinh khổng lồ, những phù thủy bí hiểm và cả những linh hồn giấu mặt đang theo dõi nhất cử nhất động của họ.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Martin Freeman","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"James Nesbitt","avatar":""},{"name":"Ken Stott","avatar":""},{"name":"Sylvester McCoy","avatar":""},{"name":"Barry Humphries","avatar":""},{"name":"Dean O''Gorman","avatar":""},{"name":"Aidan Turner","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Adam Brown","avatar":""},{"name":"Peter Hambleton","avatar":""},{"name":"John Callen","avatar":""},{"name":"Mark Hadlow","avatar":""},{"name":"Jed Brophy","avatar":""},{"name":"William Kircher","avatar":""},{"name":"Stephen Hunt","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Hobbiten: En uventet reise","The Hobbit - An Unexpected Journey - 3D","A Hobbit: Egy váratlan utazás","O Hobbit - Uma Jornada Inesperada","Hobbit - An Unexpected Journey","Le Hobbit : Un voyage inattendu","El Hobbit I: Un viaje inesperado","指环王前传：霍比特人(上)","Hobitas: nelaukta kelionė","De Hobbit: Een Onverwachte Reis","Χόμπιτ: Ένα Αναπάντεχο Ταξίδι","Hobbit - en oväntad resa","Hobbit","Hobbit 3D","호빗: 뜻밖의 여정","호빗-뜻밖의 여정","Hobbit: Beklenmedik Yolculuk","El hobbit: Un viaje inesperado","哈比人：不思議之旅","호빗 1; 뜻밖의 여정","호빗 1: 뜻밖의 여정","호빗; 뜻밖의 여정","Хобит: Неочекуваното патување","Người Hobbit: Hành Trình Vô Định","الهوبيت : رحلة غير متوقعة","Хоббит 1","Хоббит Нежданное путешествие","The Hobbit: An Unexpected Journey"]', 1784690324464);
