INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hobbit-hanh-trinh-vo-dinh', 'Người Hobbit: Hành Trình Vô Định', 'The Hobbit: An Unexpected Journey', 'người hobbit: hành trình vô định the hobbit: an unexpected journey martin freeman ian mckellen richard armitage james nesbitt ken stott sylvester mccoy barry humphries dean o''gorman aidan turner graham mctavish adam brown peter hambleton john callen mark hadlow jed brophy william kircher stephen hunt hobbiten: en uventet reise the hobbit - an unexpected journey - 3d a hobbit: egy váratlan utazás o hobbit - uma jornada inesperada hobbit - an unexpected journey le hobbit : un voyage inattendu el hobbit i: un viaje inesperado 指环王前传：霍比特人(上) hobitas: nelaukta kelionė de hobbit: een onverwachte reis χόμπιτ: ένα αναπάντεχο ταξίδι hobbit - en oväntad resa hobbit hobbit 3d 호빗: 뜻밖의 여정 호빗-뜻밖의 여정 hobbit: beklenmedik yolculuk el hobbit: un viaje inesperado 哈比人：不思議之旅 호빗 1; 뜻밖의 여정 호빗 1: 뜻밖의 여정 호빗; 뜻밖의 여정 хобит: неочекуваното патување người hobbit: hành trình vô định الهوبيت : رحلة غير متوقعة хоббит 1 хоббит нежданное путешествие the hobbit: an unexpected journey', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-hon-dao-dieu-ki-cuoc-phieu-luu-cua-loai-thu', 'Doraemon: Nobita và Hòn Đảo Diệu Kì – Cuộc Phiêu Lưu Của Loài Thú', 'Doraemon: Nobita and the Island of Miracles – Animal Adventure', 'https://phimimg.com/upload/vod/20250521-1/bbd241dab75fd43d6da28f11199c8fb5.jpg', 'https://phimimg.com/upload/vod/20250521-1/36971d32bf271fd37497c7ad2e7f2671.jpg', '<p>Nobita được mua cho một con bọ cánh cứng, Nobita đem nó đi đấu với Jaian nhưng lại bị thua nên Nobita nhờ Doraemon bắt cho mình một con khác để phục thù,trong lúc dò tìm bọ cánh cứng cho Nobita không may lại bắt dính loài khổng điểu cổ đại. Lo sợ khi đưa nó về thế giới cổ đại cũng sẽ diệt vong nên nhóm Doraemon đưa nó đến một nơi có tên là đảo Beregamondo. Ở đây nhóm bạn đã gặp người quản lý đảo, cô tiến sĩ Kelly. Do sơ suất nên Doraemon bị con khổng điểu lấy mất gậy lãng quên. Con khổng điểu ấy đã đánh rơi cậy gầu đó vào đầu Nobisuke/Dakke (ba Nobita lúc chạc tuổi Nobita).</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2012, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Atsuko Tanaka","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Shihoko Hagino","avatar":""},{"name":"Yuzuru Fujimoto","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Rikako Aikawa","avatar":""},{"name":"Shun","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cb