INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-doi-do', 'Phi Đội Đỏ', 'Red Tails', 'https://phimimg.com/upload/vod/20250517-1/0c2256c99f11a7ec548967c19b82c928.jpg', 'https://phimimg.com/upload/vod/20250517-1/5db2c17fa8e5b5e58698f67dceab585b.jpg', '<p>Năm 1944, trong cuộc chiến tranh thế giới thứ 2 khi quân đội Đồng Minh và Phát Xít Đức vẫn còn đang ở thế cân bằng. Dù đang chiến tranh nhưng trong lực lương quân đội Mỹ vẫn còn tồn tại rõ rệt sự phân biệt chủng tộc. Bất ngờ lầu năm góc quyết định bổ sung một biệt đội phi công da màu vào lực lượng không quân. Tuskegee là tên chung của những phi công da màu đầu tiên trong US Air Force. Vừa phải bảo vệ nền hòa bình của thế giới, đồng thời bảo vệ cho quyền tự do và bình đẳng, những phi công trẻ Tuskegee chẳng có gì để mất, chỉ có lòng dùng cảm để chứng tỏ với bầu trời…</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bryan Cranston","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Daniela Ruah","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Andre Royo","avatar":""},{"name":"Robert Kazinsky","avatar":""},{"name":"Lee Tergesen","avatar":""},{"name":"Matthew Leitch","avatar":""},{"name":"Michael B. Jordan","avatar":""},{"name":"Method Man","avatar":""},{"name":"Gerald McRaney","avatar":""},{"name":"Matthew Marsh","avatar":""},{"name":"Barnaby Kay","avatar":""},{"name":"Chris Riedell","avatar":""},{"name":"Leslie Odom Jr.","avatar":""},{"name":"Nate Park","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b