INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-quoc-phan-2', 'Tổ Quốc (Phần 2)', 'Homeland (Season 2)', 'https://phimimg.com/upload/vod/20250515-1/fa324c0c1a746052a838e6d6c2ea8a61.jpg', 'https://phimimg.com/upload/vod/20250515-1/4c84248299729f8394539f19bf630289.jpg', '<p>Ở loạt phim chính trị gay cấn này, chuyên viên phân tích CIA Carrie Mathison phải đối mặt các vấn đề sức khỏe tâm thần và gia đình khi lãnh đạo cuộc chiến chống khủng bố.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Claire Danes","avatar":""},{"name":"Mandy Patinkin","avatar":""},{"name":"Maury Sterling","avatar":""},{"name":"Numan Acar","avatar":""},{"name":"Nimrat Kaur","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Costa Ronin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Хоумленд","מולדת","ホームランド","Homeland: V mene vlasti","國土安全","Homeland"]', 1784690324464);
