INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duc-vong', 'Dục Vọng', 'The Paperboy', 'https://phimimg.com/upload/vod/20250514-1/8c17d4eee303a119a9c9c34fc26961e4.jpg', 'https://phimimg.com/upload/vod/20250514-1/c577bec915dd91c971880f550e17dd0d.jpg', '<p>The Paperboy là một bộ phim tâm lý - tội phạm, lấy bối cảnh tại Florida, xoay quanh một phóng viên điều tra vụ án của một tử tù bị kết án giết cảnh sát. Trong quá trình tìm kiếm sự thật, anh và những người xung quanh bị cuốn vào một vòng xoáy đầy bí ẩn, bạo lực và những cảm xúc khó lường.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Macy Gray","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"Nealla Gordon","avatar":""},{"name":"Edrick Browne","avatar":""},{"name":"Kevin Waterman","avatar":""},{"name":"Danny Hanemann","avatar":""},{"name":"Peter Murnik","avatar":""},{"name":"John P. Fertitta","avatar":""},{"name":"Jay Oliver","avatar":""},{"name":"Gary Clarke","avatar":""},{"name":"Ava Bogle","avatar":""},{"name":"Adam Sibley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["报童","Amores peligrosos","El chico del periodico","Obsessão","Laiškanešys","The Paperboy"]', 1784690324464);
