INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-bi-an-2012', 'Xác Chết Bí Ẩn', 'El cuerpo / The Body', 'https://phimimg.com/upload/vod/20250514-1/85dd4db449ebcc3e3dab050a8e536fea.jpg', 'https://phimimg.com/upload/vod/20250514-1/dbcf0fc73f1f03727a2de6d9ac2ffb75.jpg', '<p>Một tác phẩm kiệt xuất đến từ nền công nghiệp điện ảnh Tây Ban Nha, có lẽ là chỉ đứng sau Hollywood. The Body sở hữu một cốt truyện phức tạp, mạch phim dồn dập ngay từ những phút đầu, bạn sẽ bị dẫn từ bất ngờ này đến bất ngờ khác và kết thúc bằng một cú knock-out ở cuối phim. &nbsp;Xác chết của một phụ nữ biến mất khỏi nhà xác một cách bí ẩn. Một thanh tra quyết tâm tìm ra bí ẩn đằng sau xác chết này!</p>', 'Full', 1, 'single', 'completed', 22, 2012, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Jose Coronado","avatar":""},{"name":"Hugo Silva","avatar":""},{"name":"Belén Rueda","avatar":""},{"name":"Aura Garrido","avatar":""},{"name":"Cristina Plazas","avatar":""},{"name":"Montse Guallar","avatar":""},{"name":"Nausicaa Bonnín","avatar":""},{"name":"Miquel Gelabert","avatar":""},{"name":"Oriol Vila","avatar":""},{"name":"Carlota Olcina","avatar":""},{"name":"Patrícia Bargalló","avatar":""},{"name":"Ahmed Adel","avatar":""},{"name":"Mia Esteve","avatar":""},{"name":"Sílvia Aranda","avatar":""},{"name":"Manel Dueso","avatar":""},{"name":"Pere Brasó","avatar":""},{"name":"Albert López-Murtra","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Telo","El cuerpo"]', 1784690324464);
