INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-doi-1942', 'Nạn Đói 1942', 'Back to 1942', 'https://phimimg.com/upload/vod/20250511-1/05d10f6622dd7ab1f1558efcea60ff01.jpg', 'https://phimimg.com/upload/vod/20250511-1/50c4afdc7f6137bcdaa35eac215de658.jpg', '<p>Một trong những đạo diễn thành công nhất của nền điện ảnh Trung Quốc đương đại Phùng Tiểu Cương vừa cho ra tác phẩm mới khắc họa lại nạn đói năm 1942 ở Trung Quốc. Bộ phim có tên “Back to 1942” (Quay về năm 1942) được đánh giá như một thiên sử thi hùng tráng.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Guoli","avatar":""},{"name":"Xu Fan","avatar":""},{"name":"Zhang Mo","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Chen Daoming","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Wang Ziwen","avatar":""},{"name":"Fan Wei","avatar":""},{"name":"Feng Yuanzheng","avatar":""},{"name":"Alec Su","avatar":""},{"name":"Li Xuejian","avatar":""},{"name":"Lü Zhong","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Ke Lan","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Alfred Hsing","avatar":""},{"name":"Shaohua Zhang","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Zhang Guoqiang","avatar":""},{"name":"Du Ch","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Back to 1942","1942","Empire of War - Der letzte Widerstand","温故1942","Yi jiu si er","温故一九四二","一九四二"]', 1784690324464);
