INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nan-doi-1942', 'Nạn Đói 1942', 'Back to 1942', 'nạn đói 1942 back to 1942 zhang guoli xu fan zhang mo zhang hanyu chen daoming adrien brody tim robbins wang ziwen fan wei feng yuanzheng alec su li xuejian lü zhong qiao zhenyu ke lan li qian zhao yi alfred hsing shaohua zhang duan yihong zhang guoqiang du ch back to 1942 1942 empire of war - der letzte widerstand 温故1942 yi jiu si er 温故一九四二 一九四二', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trang-om-mat-troi', 'Mặt Trăng Ôm Mặt Trời', 'The Moon Embracing The Sun', 'https://phimimg.com/upload/vod/20241222-1/00e278de60ccc89ba638b7baae44b4c9.jpg', 'https://phimimg.com/upload/vod/20241222-1/af4a4224311c26914500d25dc4a463f9.jpg', '<p>Mặt Trăng Ôm Mặt Trời dựa trên tiểu thuyết cùng tên của nhà văn Jeong Eun Gwol. Nội dung phim kể về kể về mối tình giữa Lee Hwon – vị vua của triều đại Joseon với Han Ga-In – con gái của Đại Đề Học Hoằng Văn Quán. Han Ga-In là một cô gái vô cùng thông minh xinh đẹp, và nàng còn là một cô gái rất nhân hậu, giàu lòng thương người.

Nàng được hứa hôn với Lee Hwon vào năm 13 tuổi nhưng sau đó bị hãm hại, nàng bị mang trọng bệnh. May thay, nàng được pháp sư đứng đầu Tinh Túc Sảnh cứu mạng, nhưng nàng lại mất đi trí nhớ và phải phiêu bạt đó đây. Định mệnh sắp đặt nàng gặp lại Lee Hwon với thân phận phù thủy, và được Lee Hwon đặt tên thành Wol.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Soo-hyun","avatar":""},{"name":"Yeo Jin-goo","avatar":""},{"name":"Han Ga-in","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Jung Il-woo","avatar":""},{"name":"Lee Tae-ri","avatar":""},{"name":"Kim Min-seo","avatar":""},{"name":"Kim So-hyun","avatar":""},{"name":"Sunwoo Jae-duk","avatar":""},{"name":"Song Jae-hee","avatar":""},{"name":"Yim Si-wan","avatar":""},{"name":"Yoon Seung-ah","avatar":""},{"name":"Seo Ji-hee","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kim Yeong-ae","avatar":""},{"name":"Nam Bo-ra","avatar":""},{"name":"Jin Ji-hee","avatar":""},{"name":"Song Jae-rim","avatar":""},{"name":"Lee Won-keun","avatar":""},{"name":"Kim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["拥抱太阳的月亮","해품달","La Luna Abraza al Sol","ลิขิตรักตะวันและจันทรา","The Moon That Embraces the Sun","The Moon Embracing the Sun","해를 품은 달"]', 1784690324464);
