INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dem-kinh-hoang-2012', 'Bóng Đêm Kinh Hoàng', 'Another', 'https://phimimg.com/upload/vod/20250418-1/c63bb7d21269c566af3169482d41442e.jpg', 'https://phimimg.com/upload/vod/20250418-1/7b9a63f55778a32c06c8d33f64d8daf4.jpg', '<p>Khi Kouichi chuyển đến ngôi trường mới, cô ấy lập tức cảm nhận được một điều gì đó đáng sợ đang bao trùm lên không khí của lớp học. Điều này khiến các bạn học sinh trong lớp ai cũng im lặng, né tránh không dám nhắc đến. Tất cả dường như đều liên quan đến một cô gái bí ẩn, trầm lặng mà chẳng ai dám lại gần hay nói chuyện cùng.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsushi Abe","avatar":""},{"name":"Natsumi Takamori","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Madoka Yonezawa","avatar":""},{"name":"Kazutomi Yamamoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["替身","Another アナザー-","アナザー","Another"]', 1784690324464);
