INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-tren-non-cao', 'Chuyện Tình Trên Non Cao', 'Romancing In Thin Air', 'https://phimimg.com/upload/vod/20231110-1/adb12b427023010145f56cced1cd5f73.jpg', 'https://phimimg.com/upload/vod/20231110-1/f33645c37addd96ec825a4cf108a4999.jpg', '<p>Sau khi đăng quang ngôi vị Ảnh đế lần thứ ba, ngôi sao điện ảnh Lưu Bách Khiêm cầu hôn bạn gái và nhận được cái gật đầu đồng ý của người đẹp. Thế nhưng, đúng ngày cưới, cô nàng lại bỏ chạy theo người khác, khiến nam diễn viên đau khổ, phải lên cao nguyên Vân Nam để giải sầu và tình cờ gặp Tú - người phụ nữ mang nhiều tổn thương trong quá khứ. Giữa khung cảnh núi non hùng vĩ và khí hậu khắc nghiệt, họ dần xích lại gần nhau, chữa lành những vết thương lòng, viết nên câu chuyện tình nhẹ nhàng nhưng đầy xúc động.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Trịnh Tú Văn","avatar":""},{"name":"Vương Bảo Cường","avatar":""},{"name":"Lý Quang Khiết","avatar":""},{"name":"Điềm Nữu","avatar":""},{"name":"Cao Viên Viên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324464);
