INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-4-luc-dia-troi-dat', 'Kỷ Băng Hà 4: Lục Địa Trôi Dạt', 'Ice Age: Continental Drift', 'https://phimimg.com/upload/vod/20250412-1/1eacbb7a8048e7bf64b86c4360448182.jpg', 'https://phimimg.com/upload/vod/20250412-1/74f3e3213270c4d4debe15e8c6161c07.jpg', '<p>Đây là phần 4 của loạt phim đuộc đánh giá là một trong loạt phim hoạt hình được yêu thích và thành công nhất mọi thời đại. Trong phần này nhóm bạn Manny (voi ma-mút), Diego (hổ răng kiếm) và Sid (lười tiền sử) sẽ đối mặt với những thử thách mới do các lục địa bị trôi dạt sau trận Đại hồng thủy. Bên cạnh đó phim có sự xuất hiện của nhiều nhân vật mới như: Squint, Captain Gutt, Flynn… Có thể nói với các tình tiết hài hước, vui nhộn, Kỷ băng hà 4 mang tới cho người xem những tiếng cười sảng khoái. Các nhân vật trong phim trở nên sống động với: vui, buồn, yêu, ghét như con người, qua đó phim cũng chuyển tải những bài học nhẹ nhàng về tình cảm cha con, bạn bè, tình yêu. Đây được đánh giá là 1 bộ phim hay với đề cử giải thưởng Kids&quot; Choice Awards 2013</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2012, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Keke Palmer","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Aziz Ansari","avatar":""},{"name":"Alain Chabat","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Drake","avatar":""},{"name":"Nicki Minaj","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Alan Tudyk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["A Era do Gelo 4: Deriva Continental","Ice Age 4: Continental Drift","Ice Age 4 - Mannerten mullistus","Epoka Lodowcowa 4: Wędrówka Kontynentów","Epoka Lodowcowa: Wędrówka Kontynentów","Ice Age 4 La formacion de los continentes","L''Âge de glace 4 : La Dérive des continents","アイス・エイジ４　パイレーツ大冒険","Ice Age 4: På gyngende grund","العصر الجليدي: الانجراف القاري","Istid 4: Kontinenter på avveie","გამყინვარების ხანა: კონტინენტალური დრეიფი","Kỷ Băng Hà 4: Lục Địa Trôi Dạt","Buz Dövrü 4: Qitələr Ayrılır","冰河世纪4：大陆漂移","冰河世纪4","冰原历险记4：板块漂移","아이스 에이지 4","Ledeno doba 4 - Zemlja se trese","Ísöld 4: Heimsálfuhopp","冰河世纪4：玩转新大陆","Ice Age: Continental Drift"]', 1784690324464);
