INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tho-lac-chon-than-tien', 'Nàng Thơ Lạc Chốn Thần Tiên', 'Adventures Into the Woods: A Sexy Musical', 'https://phimimg.com/upload/vod/20250411-1/59ac217c96ba8882f3db0b6fd2aee9a7.jpg', 'https://phimimg.com/upload/vod/20250411-1/ec6187d565585cacc2c6da689ccd886d.jpg', '<p>EMMANUELLE IN WONDERLAND là một bức thư tình gửi đến các vở nhạc kịch Hollywood và Broadway trong quá khứ. Khi đang tham gia vào một thí nghiệm khoa học, một cô gái trẻ rơi qua hố sâu và lạc vào xứ sở thần tiên! Đây không phải là Xứ sở thần tiên mà bạn nhớ, mà là một thế giới hoàn toàn mới, nơi tất cả các câu chuyện cổ tích đều tồn tại và cuối cùng tất cả họ đều trưởng thành! Trên hành trình tìm đường trở về nhà, Emmanuelle gặp The Mad Hatter, Goldilocks, The Big Bad Wolf, Dorothy, The Scarecrow, Humpty Dumpty, Jack và Jill, Snow White, The Frog Prince, The Evil Queen và nhiều nhân vật khác! Sau đây là bộ phim hài ca nhạc gợi cảm, kỳ quặc nhất trong năm với 12 bài hát gốc! Glee khỏa thân gặp Disney trên axit! Dành cho trẻ em ở mọi lứa tuổi… Trên 18 tuổi!</p>', 'Full', 1, 'single', 'completed', 26, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Allie Haze","avatar":""},{"name":"Ariauna Albright","avatar":""},{"name":"Jess Allen","avatar":""},{"name":"Chriss Anglin","avatar":""},{"name":"Cameron Bass-Jackson","avatar":""},{"name":"Victoria De Mare","avatar":""},{"name":"Robert Donavan","avatar":""},{"name":"Harper Issacs","avatar":""},{"name":"Russia Hardy","avatar":""},{"name":"Ron Jeremy","avatar":""},{"name":"Monica Mayhem","avatar":""},{"name":"Jeremy L. Morrison","avatar":""},{"name":"Nataliya Joy Prieto","avatar":""},{"name":"Kristian Steel","avatar":""},{"name":"Marta Zolynska","avatar":""},{"name":"Elissa Dowlin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Emmanuelle in Wonderland","Emmanuelle Through Time: Emmanuelle''s Sex Tales","Adventures Into the Woods: A Sexy Musical"]', 1784690324464);
