INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-tho-lac-chon-than-tien', 'Nàng Thơ Lạc Chốn Thần Tiên', 'Adventures Into the Woods: A Sexy Musical', 'nàng thơ lạc chốn thần tiên adventures into the woods: a sexy musical allie haze ariauna albright jess allen chriss anglin cameron bass-jackson victoria de mare robert donavan harper issacs russia hardy ron jeremy monica mayhem jeremy l. morrison nataliya joy prieto kristian steel marta zolynska elissa dowlin emmanuelle in wonderland emmanuelle through time: emmanuelle''s sex tales adventures into the woods: a sexy musical', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-bua-truyen', 'Tây Du Ký Bựa Truyện', 'The Grow', 'https://phimimg.com/upload/vod/20250403-1/00f042016a138e91a0e05becac13ba25.jpg', 'https://phimimg.com/upload/vod/20250403-1/0f3ede7997840ee5417c3d0690ee8f42.jpg', '<p>Vào một đêm tối trời gió lớn, đường tăng và các đồ đệ dừng chân nghỉ ngơi tại một ngôi miếu hoang giữa vùng sa mạc hoang vu. Sa Tăng, người luôn chăm chỉ và tận tụy, lại một lần nữa bốc phải lá thăm xui xẻo để canh đêm. Sau nhiều ngày vất vả, cuối cùng Sa Tăng kiệt sức và ngất xỉu, suýt bị Diêm Vương kéo đi. Nhiệm vụ đi tìm thuốc hồi sinh đương nhiên được giao cho Tôn Ngộ Không – &quot;Nam tiếp viên số một Thiên đình&quot;. Nhưng chưa kịp lấy thuốc về, Đường Tăng, với tài y thuật của mình, đã không kiềm chế nổi mà lao vào cứu chữa. Bằng một màn hô hấp nhân tạo, ông vô tình kéo linh hồn Sa Tăng quay về từ cõi chết. Trong lúc đó, tiên dược của Tôn Ngộ Không lại vô tình rơi trúng cây Kim Cô Bổng…</p>', 'Full', 1, 'hoathinh', 'completed', 42, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Han Xue","avatar":""},{"name":"汪译男","avatar":""},{"name":"童自荣","avatar":""},{"name":"于立","avatar":""},{"name":"榕榕","avatar":""},{"name":"Huang Ying","avatar":""},{"name":"刘彬","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '["夺宝幸运星大电影之金箍棒传奇","金箍棒传奇"]', 1784690324464);
