INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-di-san', 'Kẻ Đi Săn', 'The Chaser', 'https://phimimg.com/upload/vod/20250327-1/20c09d1052b82c6a75c20c9905909b14.jpg', 'https://phimimg.com/upload/vod/20250327-1/2e8f4dd6ceb1a8b6c54cfad4812c9201.jpg', '<p>Jung Ho, từng là cảnh sát nhưng nay đã trở thành một tay ma cô dẫn gái, nổi điên vì hàng loạt gái gọi dưới tay gã biến mất. Gã tin rằng các cô gái đã lừa tiền hắn mà bỏ đi. Nhưng sự thật là một tên sát nhân hàng loạt nhắm vào các cô gái gọi, trong đó có Min Ji, người Jung Ho quan tâm nhất...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2012, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Kim Sang-joong","avatar":""},{"name":"Go Joon-hee","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Ryu Seung-su","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Lee Yong Woo","avatar":""},{"name":"Jang Shin-young","avatar":""},{"name":"Lee Re","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Park Keun-hyong","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Lee Hye-in","avatar":""},{"name":"Nam Da-reum","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Ryohei Otani","avatar":""},{"name":"Kang Ji","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["追击者","Chujeokja","追擊者","Father''s War","Tracer","추적자"]', 1784690324464);
