INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-toc-xu', 'Công Chúa Tóc Xù', 'Brave', 'https://phimimg.com/upload/vod/20250327-1/8205f8768f0773897ebd3cf285950a4c.jpg', 'https://phimimg.com/upload/vod/20250327-1/73bdddbb4224bb8599450bdfa2c98213.jpg', '<p>Công Chúa Tóc Xù xoay quanh nhân vật chính công chúa Merida. Từ nhỏ cô đã tỏ ra là người ngang bướng không thích những nề nếp chốn cung đình. Một ngày, hoàng hậu tổ chức kén phò mã cho Merida. Không chấp nhận sự sắp đặt Merida đã bỏ vương quốc ra đi. Trên đường đi cuộc gặp gỡ định mệnh với mụ phù thủy già đã đưa cô vào những cuộc phiêu lưu đầy hiểm nguy. Trong phim, Brave được đánh giá cao ở khía cạnh nhân văn, đề cao tình cảm gia đình, lòng quả cảm. Thông qua hình ảnh cô công chúa Merida bướng bỉnh người xem liên tưởng tới những cô bé, cậu bé tuổi teen bướng bỉnh mà mình đã gặp đâu đó, với tạo hình nhân vật khá đặc sắc ngộ nghĩnh Brave đã làm thỏa mãn sự háo hức của các Fan nhí. Bên cạnh đó những nhạc khúc Scotlen đã tạo ra điểm nhấn đặc biệt cho phim.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2012, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kelly Macdonald","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"Peigi Barker","avatar":""},{"name":"Steve Purcell","avatar":""},{"name":"Patrick Doyle","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Sally Kinghorn","avatar":""},{"name":"Eilidh Fraser","avatar":""},{"name":"Steven Cree","avatar":""},{"name":"Callum O''Neill","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Brave - 3D","Hrabra Merida","Rebelle (Brave)","Ausarta","شجاع","Modig","Cəsur","Brave (Indomable)","勇敢传说","Merida - Legende der Highlands","Valiente","Brave - Coraggiosa e ribelle","Brave"]', 1784690324464);
