INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-an-luong-tam-phan-2', 'Toà Án Lương Tâm (Phần 2)', 'Ghetto Justice (Season 2)', 'https://phimimg.com/upload/vod/20250324-1/a4b315f0be5a27be60455a8cb9aa9ef8.jpg', 'https://phimimg.com/upload/vod/20250324-1/40aa1e5786d51c7469648cc91748d9c8.jpg', '<p>Sau khi mãn hạn tù, Law Lik-ah muốn bắt đầu lại, vì vậy anh hợp tác với đồng đội Kris Wong Sze-fu để chống lại sự bất công. Lik-ah và Kris sớm trở thành anh hùng của Sham Shui Po nhưng tính cách của họ xung đột và họ liên tục bất đồng với nhau. Trong khi đó, họ đã xúc phạm nhà phát triển bất động sản giàu có khi xử lý một vụ sập tòa nhà và tính mạng của Lik-ah đang gặp nguy hiểm. Liệu họ có thể tìm lại công bằng cho những công dân thiệt thòi ở Sham Shui Po?</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 19, 2012, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Myolie Wu Hang-Yee","avatar":""},{"name":"Raymond Cho","avatar":""},{"name":"JJ Jia","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Christine Kuo Yun-Hui","avatar":""},{"name":"Jazz Lam","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Ting Chu-Wai","avatar":""},{"name":"Eddie Kwan Lai-Kit","avatar":""},{"name":"Andy Shiu Cheuk-Yiu","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Chan Min-L","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["怒火街头II","怒火街头2","欢喜情缘","Ghetto Justice II","怒火街頭II"]', 1784690324464);
