INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('atm-loi-tinh-yeu', 'ATM Lỗi Tình Yêu', 'ATM', 'https://phimimg.com/upload/vod/20250324-1/48b3d47e5de7fc4a2bbafc8bddc44e93.jpg', 'https://phimimg.com/upload/vod/20250324-1/7d4d524c2808495533b367f8fcf6dc9d.jpg', '<p>Ngân hàng JNBC có quy định cấm nhân viên yêu nhau. Nhưng trớ trêu thay cô sếp nữ lại phải lòng nhân viên nam của mình. Hai người đi đến quyết định kết hôn, thế nhưng không ai chịu nghỉ việc. Đúng lúc đó, máy ATM của ngân hàng bị lỗi và những tình huống dở khóc dở cười đến không ngờ diễn ra.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Preechaya Pongthananikorn","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""},{"name":"Thawat Pornrattanaprasert","avatar":""},{"name":"Sananthachat Thanapatpisal","avatar":""},{"name":"Pongkool Suebsung","avatar":""},{"name":"Puttachat Pongsuchat","avatar":""},{"name":"Gornpop Janjaroen","avatar":""},{"name":"Pongsatorn Jongwilas","avatar":""},{"name":"Yanee Tramoth","avatar":""},{"name":"Anake Inthajun","avatar":""},{"name":"Korn Kit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ATM Error","ATM: Er Rak Error","ATM เออรัก..เออเร่อ"]', 1784690324464);
