INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madagascar-3-than-tuong-chau-au', 'Madagascar 3: Thần Tượng Châu Âu', 'Madagascar 3: Europe''s Most Wanted', 'https://phimimg.com/upload/vod/20250316-1/60af61b6c789c0cf82816d47b84bb6ad.jpg', 'https://phimimg.com/upload/vod/20250316-1/810a78255ac9bbc689d0a5c995f36086.jpg', '<p>Madagsaca 3 đã mang tới cho người xem những khoảnh khắc tuyệt vời. Mặc dù thuộc dòng phim giải trí tuy nhiên Madagasca 3 cũng mang đến bài học về tình bạn, sự hi sinh, nghị lực… Được gửi gắm nhẹ nhàng thông qua lời nói, hành đông của các nhân vật. Phim được công chiếu lần đầu ra công chúng tại LHP CAN 2012 và nhận được nhiều phản hồi rất tích cực.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2012, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ben Stiller","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"David Schwimmer","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Tom McGrath","avatar":""},{"name":"Chris Miller","avatar":""},{"name":"Christopher Knight","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Madagascar 3","Madagascar 3 - Europe''s Most Wanted","Madagascar 3 - Bons Baisers d’Europe","马达加斯加3","Madagascar 3 - Europe''s Most Wanted - 3D","마다가스카3 : 이번엔 서커스다","Madagaskar 3 Euroopa tagaotsitumad","Madagascar 3 - Os Procurados","Madagascar 3: De marcha por Europa","Madagaskar 3: Full rulle i Europa","荒失失奇兵3：歐洲逐隻捉","Madagascar 3: Thần Tượng Châu Âu","马达加斯加3：欧洲大围捕","Madagaskar 3: Najtraženiji u Europi","Madagaskar 3: Najtraženiji u Evropi","荒失失奇兵3：欧洲逐只捉","Madagascar 3: Europe''s Most Wanted"]', 1784690324464);
