INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tam-thang-tam', 'Ngày Tám Tháng Tám', 'August 8', 'https://phimimg.com/upload/vod/20250314-1/90522fd059b34ca0669c8253a086798d.jpg', 'https://phimimg.com/upload/vod/20250314-1/d3d377615050b51b2d669632fda335a1.jpg', '<p>Bốn năm sau cuộc xung đột ngắn ngày giữa Gruzia và Nga tại khu vực Nam Ossetia, một bộ phim chiến tranh bom tấn của điện ảnh Nga mang tên “August 8” (Mùng 8 tháng Tám) đã được ra mắt, và đây được coi như cái nhìn của nước Nga về cuộc chiến kể trên. Được cấp vốn thực hiện tới 90 phần trăm bởi điện Kremlin (xấp xỉ 10 triệu USD), “August 8” được nhiều người cho là câu trả lời cho “5 days of War,” một tác phẩm Hollywood cũng kể về cuộc chiến Nga-Gruzia, được chính quyền Gruzia ủng hộ và có nam diễn viên Andy Garcia vào vai tổng thống Mikheil Saakashvili. Theo tờ Izvestia, “August 8” là bộ phim kể về một người phụ nữ Mátxcơva đi tìm lại con trai bị thất lạc tại thị trấn Tskhinvali, NamOssetia, sau khi họ bị lạc nhau trong vùng chiến tranh. Bộ phim sử dụng nhiều kĩ xảo hoành tráng, và đôi lúc cuộc chiến được tái hiện lại dưới mắt đứa con trai như trận đánh giữa những người máy tươi cười chống lại những con quái vật đáng sợ và những chiến binh đeo mặt nạ.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Svetlana Ivanova","avatar":""},{"name":"Maksim Matveev","avatar":""},{"name":"Artyom Fadeev","avatar":""},{"name":"Aleksey Guskov","avatar":""},{"name":"Aleksandr Oleshko","avatar":""},{"name":"Vladimir Vdovichenkov","avatar":""},{"name":"Sergey Gazarov","avatar":""},{"name":"Gosha Kutsenko","avatar":""},{"name":"Khasan Baroev","avatar":""},{"name":"Anna Legchilova","avatar":""},{"name":"Ekaterina Avdeeva","avatar":""},{"name":"Egor Beroev","avatar":""},{"name":"Estelle Raskin","avatar":""},{"name":"Anatoliy Belyy","avatar":""},{"name":"Alexander Petrov","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["August 8th","Avgust. Vosmogo","オーガストウォーズ","Август. Восьмого"]', 1784690324464);
