INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-tam-thang-tam', 'Ngày Tám Tháng Tám', 'August 8', 'ngày tám tháng tám august 8 svetlana ivanova maksim matveev artyom fadeev aleksey guskov aleksandr oleshko vladimir vdovichenkov sergey gazarov gosha kutsenko khasan baroev anna legchilova ekaterina avdeeva egor beroev estelle raskin anatoliy belyy alexander petrov an august 8th avgust. vosmogo オーガストウォーズ август. восьмого', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-thien-ac', 'Ranh Giới Thiện Ác', 'Highs And Lows', 'https://phimimg.com/upload/vod/20250314-1/256cfd38bd43f709398af6de8f41ab49.jpg', 'https://phimimg.com/upload/vod/20250314-1/38854212600a0aada0c32ed597a51b68.jpg', '<p>Nội dung của phim Ranh Giới Thiện Ác xoay quanh cảnh sát Hướng Vinh (Miêu Kiều Vỹ), đang làm việc chung với người cộng sự trẻ tuổi Vỹ Thế Lạc (Lâm Phong) trong cục điều tra tội phạm ma tuý, tuy nhiên Hướng Vinh lại liên tục vi phạm pháp luật khi anh ta tham gia vào những đường dây buôn bán ma tuý ngầm. Vỹ Thế Lạc sau một thời gian điều tra đã bắt đầu tìm thấy những dấu vết cho thấy Hướng Vinh là một cảnh sát biến chất, ngày ngày bí mật câu kết với bọn con buôn ma tuý. Lúc này Thế Lạc tập trung nhiều hơn trong việc tìm ra những bằng chứng buộc tộc Vinh, trong khi thanh tra Phan Học Lễ (Huỳnh Trí Hiền) và anh thì liên tục xảy ra những mâu thuẫn. Mặc khác, nhờ điều tra Vỹ Thế Lạc mà Hướng Vinh có quen biết với một cô gái chuyên cung cấp thông tin cho cảnh sát tên là Trần Gia Bích (Từ Tử San), anh nhanh chóng bị cuốn vào chuyện tình cảm sau khi tiếp xúc với cô, trớ trêu đó lại là một cuộc tình tay ba và người thứ 3 trong cuộc tình này là Quỳ Hỷ Tuyền (Quan Ân Na). Tuy nhiên, cuối cùng Gia Bích lại rơi vào con đường gần như sẽ không có lối thoát, cô dần dần biến chất và trở thành một tay buôn bán ma tuý thứ thiệt, thách thức cả cảnh sát. Lúc này, Vỹ Thế Lạc, Hướng Vinh và Trần Gia Bích chính thức bước vào một cuộc chiến không khoan nhượng để vượt qua ranh rới giữa thiện và ác…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2012, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Trí Hiền","avatar":""},{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Ngô Ỷ Lợi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["雷霆扫毒 2012","雷霆扫毒","Thunderous Drug Raid","Highs and Lows","雷霆掃毒"]', 1784690324464);
