INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-troi-day', 'Thế Giới Ngầm: Trỗi Dậy', 'Underworld: Awakening', 'https://phimimg.com/upload/vod/20250303-1/ad99a7b76cd4ac8d9e8a4ea61bc1b0ae.jpg', 'https://phimimg.com/upload/vod/20250303-1/a3825ad4a0937c6d99b0c72dc4ae1b1e.jpg', '<p>Sau một giấc ngủ dài, Selene tỉnh dậy, và khi phát hiện ra rằng con người đã biết đến sự tồn tại về giống loài của mình - Ma cà rồng và Người sói. Họ đang tiến hành một cuộc chiến tranh toàn diện để tiêu diệt cả hai loài bất tử này. Selene quyết tâm tìm cách chiến đấu để bảo vệ giống loài…</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Theo James","avatar":""},{"name":"India Eisley","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Sandrine Holt","avatar":""},{"name":"Sanny van Heteren","avatar":""},{"name":"Jacob Blair","avatar":""},{"name":"Robert Lawrenson","avatar":""},{"name":"Kurt Max Runte","avatar":""},{"name":"Marvin Duerkholz","avatar":""},{"name":"Ron Wear","avatar":""},{"name":"Richard Cetrone","avatar":""},{"name":"Dan Payne","avatar":""},{"name":"Mark Gibbon","avatar":""},{"name":"Benita Ha","avatar":""},{"name":"Tyler McC","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Underworld: New Dawn","Underworld 4: Awakening","黑夜传说4：觉醒","Underworld IV: Awakening (2012)","Underworld - 4 - Awakening","Thế Giới Ngầm 4: Trỗi Dậy","สงครามโค่นพันธุ์อสูร 4: กำเนิดใหม่ราชินีแวมไพร์","Underworld 4","A