INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-bac-kinh-2012', 'Chuyện Tình Bắc Kinh', 'Beijing Love Story', 'https://phimimg.com/upload/vod/20250222-1/51c97462ca03821d980b856a2005c7b0.jpg', 'https://phimimg.com/upload/vod/20250222-1/01e7e48383196a3c227d9c2b95045f00.jpg', '<p>5 câu chuyện của 5 cặp đôi ở lứa tuổi, hoàn cảnh và nghề nghiệp khác nhau vẽ nên một Chuyện Tình Bắc Kinh cực đẹp, những mâu thuẫn, những đau khổ hay hạnh phúc, lãng mạng điều được khác họa một cách đậm nét trong phim. Đặc biệt phim có sự tham gia của các diễn viên gạo cội như Lương Gia Huy, Lưu Gia Linh, Tư Cầm Cao Oa…</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2012, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Sicheng","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Monica Mok Siu-Kei","avatar":""},{"name":"Tan Kai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beijing Love Story","北京爱情故事"]', 1784690324464);
