INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-bac-kinh-2012', 'Chuyện Tình Bắc Kinh', 'Beijing Love Story', 'chuyện tình bắc kinh beijing love story chen sicheng tong liya zhang yi jerry lee yang mi zhang xinyi monica mok siu-kei tan kai beijing love story 北京爱情故事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ho-2012', 'Phi Hổ', 'Tiger Cubs', 'https://phimimg.com/upload/vod/20250218-1/442d2bb7c98d31fa8677cdc4234cbd93.jpg', 'https://phimimg.com/upload/vod/20250218-1/625bbe3a68aa5fd6fc7c25944551d78c.jpg', '<p>Triển Hàn Thao với biệt danh Ma Quỷ là một sỹ quan huấn luyện lâu năm trong đội Phi Hổ. Trong thâm tâm Hàn Thao là một vị anh cả trọng tình nghĩa, anh ta luôn coi người đồng hành Trang Trác Nguyên là anh em tốt. Bạn gái của Thao, Đinh Tuệ Tuệ bất ngờ chuyển hướng tình cảm sang Trác Nguyên. Để giữ tình anh em, Nguyên giả vờ nói rằng Tô Văn Cường cũng là một đồng sự, là bạn gái của mình. Từ đó đã gây nên những quan hệ rắc rối. Đúng lúc ấy bên cảnh sát nhận được tình báo rằng tên tướng cướp Đỗ Thiên Vũ đang lập kế hoạch lớn đánh cướp kho bạc. Hàn Thao và nữ giám đốc cục điều tra tội phạm, Trang Trác Hoa cùng triển khai hành động bắt cướp. Trác Hoa là chị gái của Trác Nguyên, một cô gái kiêu ngạo và không hòa đồng, ngày đêm tập trung công việc nhằm quên đi sự đau đớn về bạn trai bị kẻ điên cuồng giết hại năm xưa. Trong lúc làm việc chung, Thao dần phát hiện Hoa rất giống mình, và cảm giác tế nhị trong hai người dần nảy sinh</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"Oscar Leung Lit-Wai","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Nancy Wu Ting-Yan","avatar":""},{"name":"Him Law","avatar":""},{"name":"Christine Kuo Yun-Hui","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Woo Fung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["飛虎"]', 1784690324464);
