INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-dau-tay', 'Đêm Dâu Tây', 'Strawberry Night', 'https://phimimg.com/upload/vod/20250210-1/3fa316fe8521ea6bbd1fedc278b4f403.jpg', 'https://phimimg.com/upload/vod/20250210-1/117d0d57b1f8f13e92154fe4de5523fa.jpg', '<p>Reiko Himekawa là một nữ thám tử tại Cục Cảnh sát Metropolitan. Reiko không xuất thân từ một gia đình danh giá, nhưng cô đã nhanh chóng thăng tiến nhờ làm việc chăm chỉ và giành được sự tôn trọng của các cảnh sát viên.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuko Takeuchi","avatar":""},{"name":"Takao Osawa","avatar":""},{"name":"Hidetoshi Nishijima","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Les années sandwiches"]', 1784690324464);
