INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-duong-anh-hung-phan-1', 'Tùy Đường Anh Hùng (Phần 1)', 'Heroes Of Sui And Tang Dynasties (Season 1)', 'https://phimimg.com/upload/vod/20240116-1/b4f9f09cefed56c9b7f95c2fef220778.jpg', 'https://phimimg.com/upload/vod/20240116-1/07ee038a2a9828ad4589d8f7db6b797d.jpg', '<p>Phim xoay quanh thời kỳ giang hồ phân tranh, anh hùng bồi xuất - với bối cảnh phim trải dài từ khi nhà Tùy thành lập rồi diệt vong, cho tới khi Lý Thế Dân đăng cơ. Bên cạnh đó là những trận chiến của các anh hùng trại Ngõa Cương như Tần Quỳnh, La Thành, Trình Giảo Kim…Đặc biệt là Trình Giảo Kim - một vị quân tử dám làm dám nhận, giang hồ nghĩa hiệp.</p>', 'Hoàn Tất (72/72)', 72, 'series', 'completed', 8, 2012, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Vệ Kiện","avatar":""},{"name":"Trương Duệ","avatar":""},{"name":"Lưu Hiểu Khánh","avatar":""},{"name":"Diệp Tổ Tân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324464);
