INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-vong-truy-kich', 'Pháp Võng Truy Kích', 'Friendly Fire', 'https://phimimg.com/upload/vod/20250121-1/ce8ff3f5e56e409e12f45379045b2295.jpg', 'https://phimimg.com/upload/vod/20250121-1/ce480bc445b229e89a60d30d93f9f79b.jpg', '<p>Luật sư Cam Tổ Tán (Tạ Thiên Hoa) và bạn gái là Huống Thiên Lam (Dương Di) sống chung với nhau, nhưng sau đó cả hai nảy sinh xung đột có khả năng dẫn đến chia tay. Trùng hợp, Tổ Tán được đề bạt khen ngợi, cũng trở thành 1 công tố viên và chung nơi làm việc với Thiên Lam, nhưng cả hai lúc này có khoảng cách cộng với cô thư ký riêng của Tố Tán (Vương Quân Thanh) chen vào giữa hai người, Tổ Tán phải xem xét lại vấn đề hôn nhân của mình… Mặt khác cha của Tổ Tán (Hứa Thiệu Hùng) có nhận nuôi 1 trẻ mồ côi và đứa bé lớn lên chính là em trai Tổ Tán – Cam Ba Địa (Sâm Mỹ). Ba Địa làm cảnh sát, anh và 1 nữ cảnh là Ngãi Mỹ Thần (Trần Mẫn Chi) như nước và lửa, tuy nhiên sau cùng Ba Địa nhận ra Mỹ Thần là”nữ thần” của mình và quyết định theo đuổi cô bất chấp cô đã có vị hôn phu…Trong khi 2 cặp tình nhân còn mắc nhiều do dự, 1 doanh nhân là Bàng Thiết Tâm (Trần Vỹ) liên quan đến nhiều vụ giết người và có tình cảm với Cam Tổ Tán…</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2012, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Sammy Leung","avatar":""},{"name":"Sharon Chan Man-Chi","avatar":""},{"name":"Louis Yuen Siu-Cheung","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Alice Chan Wai","avatar":""},{"name":"Benz Hui Shiu-Hung","avatar":""},{"name":"Samantha Ko","avatar":""},{"name":"Oscar Leung Lit-Wai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["燃情阻击","The Law Friendly Fire","Friendly Fire","法網狙擊"]', 1784690324464);
