INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-tinh-yeu', 'Cơn Mưa Tình Yêu', 'Love Rain', 'https://phimimg.com/upload/vod/20250110-1/e2f1ccfe5ff14a6a0000c8e9aa7803fb.jpg', 'https://phimimg.com/upload/vod/20250110-1/9fc84298472c8948621be47026e832b0.jpg', '<p>Love Rain là tác phẩm melodrama lấy đề tài về tình yêu kéo qua nhiều thế hệ. Seo In Ha (Jang Geun Suk đóng) là một sinh viên khoa Nghệ thuật và Kim Yoon Hee (Yoona) cô gái xinh đẹp đã nảy sinh tình cảm trong những năm tháng đại học. Mối tình đầu không có kết thúc trọn vẹn khiến cả hai day dứt, dù mỗi người đều có gia đình, con cái riêng. Nhiều năm sau, trong khi In Ha tưởng rằng Yoon Hee đã chết trong dịch bệnh năm xưa, anh tình cờ gặp lại cô. Lúc này, con trai của anh và con gái của cô cũng hữu duyên gặp nhau tại Nhật Bản và nảy sinh nhiều cảm xúc kỳ lạ khi quay về Hàn Quốc.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Keun-suk","avatar":""},{"name":"Yoona","avatar":""},{"name":"Son Eun-seo","avatar":""},{"name":"Seo In-guk","avatar":""},{"name":"Hwang Bo-ra","avatar":""},{"name":"Kim Si-hoo","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Kim Young-kwang","avatar":""},{"name":"Park Se-young","avatar":""},{"name":"Shin Ji Ho","avatar":""},{"name":"Jung Jin-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱情雨","ラブレイン","Sarangbi","愛情雨","Love Rides the Rain","Love in the Rain","Singin'' in the Rain","Cơn Mưa Tình Yêu","Mưa tình yêu","사랑비"]', 1784690324464);
