INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hoi-dap-1997', 'Lời Hồi Đáp 1997', 'Reply 1997', 'https://phimimg.com/upload/vod/20250110-1/d6f60eba16445c191e432170e3523d46.jpg', 'https://phimimg.com/upload/vod/20250110-1/7f4a71ff899108899ec63251b239c750.jpg', '<p>Thời đi học, Shi Won từng thần tượng một nhóm nhạc nam. Giờ đây, khi đã 33 tuổi, những hồi ức lại sống dậy với Shi Won và những bạn học cũ nay khi ngày họp mặt đến gần.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Eun-ji","avatar":""},{"name":"Seo In-guk","avatar":""},{"name":"Eun Ji-won","avatar":""},{"name":"Lee Ho-won","avatar":""},{"name":"Shin So-yul","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Song Jong-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Reply 1997","Answer me 1997","Eungdabhara 1997","응답하라 1997","응답하라1997","ย้อนรอยรัก 1997","Answer Me 1997","Answer To 1997","Respond 1997","Reply"]', 1784690324464);
