INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boboiboy-phan-2', 'BoBoiBoy (Phần 2)', 'BoBoiBoy (Season 2)', 'https://phimimg.com/upload/vod/20240126-1/ca5708e9582da9ac7a8a95512025a970.jpg', 'https://phimimg.com/upload/vod/20240126-1/25bd40d86ab5a83433d52484eb4e2789.jpg', '<p>BoBoiBoy, cộng sự robot Ochobot và hội bạn có siêu năng lực ứng phó với một mối đe dọa mới trên hành tinh – và cả rắc rối ở trường học.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Nurfathiah Diaz","avatar":""},{"name":"Nur Sarah Alisya","avatar":""},{"name":"Diệp Di Trân","avatar":""},{"name":"Dzubir Mohamed Zakaria","avatar":""},{"name":"Anas Abdul Aziz","avatar":""},{"name":"Muhammad Fathi Diaz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324464);
