INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huu-nhan-so-phan-4', 'Hữu Nhân Sổ (Phần 4)', 'Natsume''s Book Of Friends (Season 4)', 'hữu nhân sổ (phần 4) natsume''s book of friends (season 4) hiroshi kamiya kazuhiko inoue eiji itoh miki ito hisayoshi suganuma akira ishida sanae kobayashi ryohei kimura miyuki sawashiro kazuma horie junichi suwabe rina sato 夏目友人帐 陆 夏目友人帐 伍 夏目友人帐 肆 夏目友人帐 参 续 夏目友人帐 夏目友人帐 柒 夏目友人帐 pakt der yokai le pacte des yōkai knjiga prijatelja natsume yûjinchô کتابِ دوستان ناتسومه natsume yuujinchou natsume yūjin-chō natsume yūjinchō natsume yuujinchou go natsume yuujinchou roku natsume yuujinchou shi natsume yuujinchou san zoku natsume yuujinchou 夏目友人帳 陸 続 夏目友人帳 夏目友人帳 参 夏目友人帳 肆 夏目友人帳 伍 natsume yuujinchou shichi 夏目友人帳 漆 나츠메 우인장 나츠메우인장 тетрадь дружбы нацумэ นัตสึเมะกับบันทึกสหาย книга друзів нацуме natsume''s book of friends natsume''s friend book natsume yujin-cho quyển sổ người bạn hữu nhân sổ 夏目友人帳', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-moc-lan-truyen-ky', 'Hoa Mộc Lan Truyền Kỳ', 'The Story Of Mulan', 'https://phimimg.com/upload/vod/20241214-1/3e42cbfa8a719d74f57008e715756069.jpg', 'https://phimimg.com/upload/vod/20241214-1/df9f642f401c286cb540be8f1e7d1355.jpg', '<p>Thời Bắc Ngụy, Bắc Địa Vương công cao lấn chủ, bị hoàng đế ban chết. Hai vương tử Thác Bạt Thiên Nhiên và Thác Bạt Á Thuật đào thoát thành công. Cha của Mộc Lan vâng mệnh bảo vệ huyết mạch cho tông thất, nuôi dưỡng hai vương tử. Mộc Lan cùng hai vương tử cùng nhau lớn lên. Ba năm sau, Thác Bạt gia được xá miễn, hai vương tử được triệu về kinh nhập ngũ. Sáu năm sau, lân bang sang xâm phạm, triều đình tiến hành tuyển quân rộng rãi. Dù già yếu thương tật, nhưng cha Mộc Lan cũng bị gọi nhập ngũ. Mộc Lan quyết định thay cha cải nam trang tòng quân. Trong quân doanh, Mộc Lan gặp lại Thác Bạt Thiên Nhiên và Thác Bạt Á Thuật. Thiên Nhiên biết được thân phận của Mộc Lan, nhưng yêu cầu Mộc Lan giữ bí mật với Á Thuật. Trong quá trình thao luyện binh sĩ, Mộc Lan và Á Thuật thường xuyên xung đột. Ban đầu Mộc Lan không muốn giết người, nhưng Á Thuật đã phân tích cho nàng hiểu ý nghĩa của chiến tranh và chức trách của quân nhân. Mộc Lan trở thành tướng tài, nhiều lần lập công. Chiến tranh kết thúc, Mộc Lan khôi phục thân phận nữ nhi. Hoàng đế tha cho nàng tội khi quân, và ban cho họ Hoa. Mộc Lan không ham vinh hoa phú quý, quyết định hồi hương quy ẩn...</p>', 'Hoàn Tất (57/57)', 57, 'series', 'completed', 17, 2012, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hầu Mộng Dao","avatar":""},{"name":"Quách Phẩm Siêu","avatar":""},{"name":"Lưu Đức Khải","avatar":""},{"name":"Trịnh Phối Phối","avatar":""},{"name":"Lữ Lương Vỹ","avatar":""},{"name":"Vương Âu","avatar":""},{"name":"Dương Lệ Thanh","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324464);
