INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-moc-lan-truyen-ky', 'Hoa Mộc Lan Truyền Kỳ', 'The Story Of Mulan', 'hoa mộc lan truyền kỳ the story of mulan hầu mộng dao quách phẩm siêu lưu đức khải trịnh phối phối lữ lương vỹ vương âu dương lệ thanh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-so-truyen-ky', 'Hán Sở Truyền Kỳ', 'Legend Of Chu And Han', 'https://phimimg.com/upload/vod/20241125-1/ed262748b8fae2af3979f0d80cabc949.jpg', 'https://phimimg.com/upload/vod/20241125-1/ecbdba98e767b4a5d41614967967a68e.jpg', '<p>Hạng Vũ xuất thân từ đình quý tộc, tư chất hơn người, hào khí ngút trời, trên đời khó anh hùng nào sánh kịp. Lưu Bang ngoài 40 tuổi, cả ngày nhàn rỗi, không thích lao động nhưng tính khí vô cùng phóng khoáng, có tài năng ngoại giao, hay khoác lác, thường tự xưng là “Long chủng” Tần Thủy Hoàng bất ngờ qua đời, gian thần lộng quyền, nhị thế tử kế vị, tàn bạo bất nhân, lạm dụng chinh chiến để bốc lột người dân

Hán Sở Tranh Hùng Không nghề mưu sinh, thảo khấu nổi lên tứ phía. Đúng lúc này cácanh hùng hào kiệt từ các nơi tụ họp về Trung nguyên. Những âm mưu rợn người, những cuộc chiến tranh giành quyền lực đan xen những mâu thuẩn trong tình cảm, Ngu Cơ, Lưu Bang, Lữ Trĩ. Cuối cùng Lưu Bang đại thắng, dựa trên chế độ chính trị hiện có của nhà Tần, thành lập Đại Hán và lưu vào sách sử với tên gọi Hán Cao Tổ.</p>', 'Hoàn Tất (80/80)', 80, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Đạo Minh","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Đoạn Dịch Hoành","avatar":""},{"name":"Tần Lam","avatar":""},{"name":"Lý Y Hiểu","avatar":""},{"name":"Dương Lập Tân","avatar":""},{"name":"Vưu Dũng","avatar":""},{"name":"Vu Hòa Vỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Legend of Chu and Han","楚汉传奇","초한지","King''s War"]', 1784690324464);
