INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('han-so-truyen-ky', 'Hán Sở Truyền Kỳ', 'Legend Of Chu And Han', 'hán sở truyền kỳ legend of chu and han trần đạo minh hà nhuận đông đoạn dịch hoành tần lam lý y hiểu dương lập tân vưu dũng vu hòa vỹ legend of chu and han 楚汉传奇 초한지 king''s war', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tan-de-quoc-chi-thien-ha', 'Đại Tần Đế Quốc: Chí Thiên Hạ', 'Qin Empire Alliance', 'https://phimimg.com/upload/vod/20241125-1/c8ea52dbe66344f297e81b68222a768d.jpg', 'https://phimimg.com/upload/vod/20241125-1/dab64f412d348bf5e6035f6edaef9446.jpg', '<p>Cuối thời kỳ Chiến quốc, lãnh địa Hoa Hạ vốn đã hỗn loạn năm trăm năm vẫn chiến tranh liên miên, dân chúng lầm than. Khi đó, sáu nước suy yếu, chỉ có nước Tần hùng mạnh, thế cục thống nhất thiên hạ đã dần lộ rõ. Thương nhân Lã Bất Vi đưa Doanh Dị Nhân, đang làm con tin ở nước Triệu trốn về nước Tần, còn Tần Thủy Hoàng Doanh Chính lúc nhỏ bị bỏ lại Hàm Đan, nhiều lần trải qua tai họa sinh tử nên đã tận mắt chứng kiến nỗi khổ và sự tuyệt vọng mà chiến tranh đã gây ra cho dân chúng, trong lòng đã nảy ra hoài bão thống nhất thiên hạ từ đây. Sau này, Doanh Chính trở lại nước Tần, trải qua vòng xoáy chính trị ở Hàm Dương đã trở thành một vị vua thực sự. Để nắm bắt thời cơ và sức mạnh thống nhất thiên hạ, thực hiện tham vọng thống nhất thiên hạ, Doanh Chính đã mưu tính kỹ lưỡng, hành động bí mật, cuối cùng bình định được loạn Lao Ái, tự mình chấp chính, bãi chức Thừa tướng, giành lại binh quyền. Sau đó lại dẹp bỏ tông thất, khôi phục thế lực, xóa bỏ chướng ngại để Đông xuất tiêu diệt các nước. Dưới sự phò tá của các quan văn võ như Lý Tư, Vương Tiễn, Mông Điềm… đã tiêu diệt sáu nước, xây dựng nhà nước trung ương tập quyền đầu tiên trong lịch sử Trung Quốc.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lỗ Nhất","avatar":""},{"name":"Đoạn Dịch Hoành","avatar":""},{"name":"Lí Nại Văn","avatar":""},{"name":"Chu Châu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324464);
