INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-han-tinh-thu', 'Lửa Hận Tình Thù', 'Yellow Boots', 'https://phimimg.com/upload/vod/20241104-1/af2ed372462e7811e392ad1363e23c2f.jpg', 'https://phimimg.com/upload/vod/20241104-1/964461e19a046053fdbb028f8389c3d1.jpg', '<p>Từng làm mưa gió trên màn ảnh nhỏ năm 2012, phim theo chân mối quan hệ từ bạn thành thù của chị kế - em kế Yun Hwa và Yu Ra. Vì yêu, Yu Ra đã không từ thủ đoạn để khiến Yun Hwa mất cả tương lai. Phim không chỉ mang đến những tình tiết drama điển hình mà còn mang đến vô số bài học cuộc sống đáng suy ngẫm.</p>', 'Hoàn Tất (108/108)', 108, 'series', 'completed', 8, 2012, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Woo Sung","avatar":""},{"name":"Yun Ah Jeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ice Adonis","Lửa Hận Tình Thù","노란 복수초"]', 1784690324464);
