INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-ma-quai', 'Trò Chơi Ma Quái', 'Don''t Click', 'https://phimimg.com/upload/vod/20241016-1/ac5c71c4637b6042be24887d8a82dada.jpg', 'https://phimimg.com/upload/vod/20241016-1/35d0266c202a645d53b9d6fab4d22c31.jpg', '<p>Một đoạn phim đã từng gây nhiều sự chú ý trên mạng, sau đó bị cấm và biến mất không dấu vết. Jung Mi đã nhờ bạn trai của chị gái mình là Joon Hyuk, làm việc cho đội điều tra đặc biệt chống tội phạm mạng để tải đoạn phim đó về. Sau khi xem đoạn phim đó hàng loạt những việc kì lạ xảy đến với Jung Mi. Chị gái của Jung Mi là See Hee cùng với Joon Hyuk cố gắng cứu cô nhưng &quot;Tất cả những ai xem đoạn phim này đều phải chết&quot;</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박보영","avatar":""},{"name":"주원","avatar":""},{"name":"강별","avatar":""},{"name":"Kim Min-hyuk","avatar":""},{"name":"Lee Marg-Eum","avatar":""},{"name":"Kang Hae-In","avatar":""},{"name":"Kwon Nam-hee","avatar":""},{"name":"Jeong Dong-gyoo","avatar":""},{"name":"Choi Ji-Hun","avatar":""},{"name":"남경읍","avatar":""},{"name":"Min Young","avatar":""},{"name":"Han Ye-Na","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ویدئوی تایید نشده: هرگز کلیک نکن","不明影像：绝对点击禁止","不明影像","미확인 동영상: 절대클릭금지"]', 1784690324465);
