INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock-phan-2', 'Thám Tử Sherlock (Phần 2)', 'Sherlock (Season 2)', 'https://phimimg.com/upload/vod/20241002-1/d8b90c88d3f1d1df793591924ce50853.jpg', 'https://phimimg.com/upload/vod/20241002-1/2eaef07548eaa65ac6681c17836d658b.jpg', '<p>Mùa đầu tiên là sự khởi đầu của mối quan hệ giữa họ. Mùa hai là giai đoạn hình thành quan hệ, thông qua niềm yêu thương, sự sợ hãi và nỗi mất mát. Mùa ba là giai đoạn hoàng kim của hai người. Còn mùa bốn có thể được gọi là những hậu quả, những bóng ma trong quá khứ quay trở lại ám ảnh họ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Martin Freeman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["神探夏洛克","Σέρλοκ","新福尔摩斯","神探福爾摩斯","شرلوک هلمز","셜록","Šerlokas","Шерлок","新世紀福爾摩斯","Sherlok Xolms","Sherlock"]', 1784690324465);
