INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh', 'Thám Tử Lừng Danh', 'Alex Cross', 'https://phimimg.com/upload/vod/20240928-1/7d699515750d2464f2a2f0fee115e00a.jpg', 'https://phimimg.com/upload/vod/20240928-1/d27285ba679e2901c53d0e1ce9418f29.jpg', '<p>Alex Cross, một nhà tâm lý học đồng thời là một thám tử tài ba từng phục vụ trong ngành cảnh sát, buộc phải vào cuộc truy tìm tên giết người hàng loạt Picasso sau cuộc gọi nhờ giúp đỡ của người bạn thân từ thuở nhỏ Tommy Kane, đồng thời là đồng nghiệp cũ trong sở cảnh sát Detroit. Hai người còn có sự đồng hành của nữ thám tử Monica Ashe. Trong quá trình điều tra và truy tìm dấu vết của tên sát nhân, Cross nhận được lời đe dọa tính mạng người thân trong gia đình. Với sự tức giận tột độ, Cross thề sẽ hạ gục kẻ sát nhân bằng bất cứ giá nào. Hai đối thủ lao vào trò chơi “mèo vờn chuột” với một bên truy lùng và bên kia trốn chạy.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tyler Perry","avatar":""},{"name":"Edward Burns","avatar":""},{"name":"Matthew Fox","avatar":""},{"name":"Rachel Nichols","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Cicely Tyson","avatar":""},{"name":"Chad Lindberg","avatar":""},{"name":"Stephanie Jacobsen","avatar":""},{"name":"Sonny Surowiec","avatar":""},{"name":"Yara Shahidi","avatar":""},{"name":"Gary A. Jones","avatar":""},{"name":"Simon Rhee","avatar":""},{"name":"Alexandra Ruddy","avatar":""},{"name":"Christian �","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["James Patterson - Alex Cross","侦探亚历克斯","Alex Cross"]', 1784690324465);
