INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-tung-phan-2', 'Tố Tụng (Phần 2)', 'Suits (Season 2)', 'https://phimimg.com/upload/vod/20240927-1/c0c219d9062b3cbe61456960bce47a93.jpg', 'https://phimimg.com/upload/vod/20240927-1/3017a858dbe7ec819237106d514e646d.jpg', '<p>Suit – Season 2 (Tố Tụng 2) tiếp tục xoay quanh các vụ kiện tụng do hai anh chàng luật sư tài giỏi Harvey và Mike cùng nhau phối hợp giải quyết một cách xuất sắc. Trong khi Mike buộc phải đối mặt với những bí mật về quá khứ của mình khi bị Jessica phát hiện cũng như trong chuyện tình cảm với Rachel, thì Harvey đang xoáy vào cuộc chiến tranh giành quyền lực với Jesscia khi người đứng đầu công ty Daniel Hardman đã quay trở về…Liệu cuộc đời của Mike có thật sự bước sang một trang mới hay không? Và số phận của Harvey trong cuộc tranh cử sẽ đi đến đâu?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Gina Torres","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suits: Homens de Terno","金装律师","诉讼双雄","无证律师","W garniturach","وکلا","La ley de los audaces","Briliáns elmék","Suits"]', 1784690324465);
