INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-co-anh-hung-xuat-thieu-nien', 'Tự Cổ Anh Hùng Xuất Thiếu Niên', 'Little Heroes', 'https://phimimg.com/upload/vod/20240923-1/52c7b9b5955e5c709ef9f361bfead39b.jpg', 'https://phimimg.com/upload/vod/20240923-1/725735b98782c25b27c05c0e405ebeba.jpg', '<p>Tự Cổ Anh Hùng Xuất Thiếu Niên - Little Heroes kể về Thiết Bưu, một đứa trẻ mồ côi được hoà thượng Thích Trí nhận nuôi và cho học võ nên anh có võ công cao cường. Chàng là một người hiền lành, siêng năng và kiên cường. Thiết Bưu chính là người đứng ra kêu gọi và cùng mọi người dẹp băng đảng của A Nhĩ Thái khi ông ta lấy cớ tiêu diệt Thiên Địa hội (hội phản Thanh phục Minh) để củng cố thế lực cho ý định cướp ngôi của mình.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Ngô Lỗi","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Bạch Tĩnh","avatar":""}]', '[]', '["Zi Gu Ying Xiong Chu Shao Nian","自古英雄出少年"]', 1784690324465);
