INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-co-anh-hung-xuat-thieu-nien', 'Tự Cổ Anh Hùng Xuất Thiếu Niên', 'Little Heroes', 'tự cổ anh hùng xuất thiếu niên little heroes thích tiểu long ngô lỗi nguyên hoa bạch tĩnh zi gu ying xiong chu shao nian 自古英雄出少年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-reacher-phat-sung-cuoi-cung', 'Jack Reacher: Phát Súng Cuối Cùng', 'Jack Reacher', 'https://phimimg.com/upload/vod/20231019-1/cc5da74e37a2ff24263fbf578595409d.jpg', 'https://phimimg.com/upload/vod/20231019-1/1fa105b32b29e5acbdc78b7fea833d3f.jpg', '<p>Bộ phim là câu chuyện về Jack Reacher, một cựu quân nhân được cảnh sát tìm tới để nhờ giúp họ điều tra một vụ thảm sát. Một tay súng đã lấy đi 5 mạng sống sau 6 phát đạn, tất cả mọi bằng chứng đều đổ dồn vào nghi phạm bị bắt. Nhưng hắn vẫn khẳng định mình vô tội. Jack Reacher bí ẩn luôn lẩn tránh đám đông và những mối quan hệ, nhưng anh biết về tay súng này. Tin tức về những vụ giết người đã buộc anh phải bước ra khỏi bóng tối và chia sẻ với các điều tra viên những gì anh biết về gã tù nhân kia.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Werner Herzog","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Vladimir Sizov","avatar":""},{"name":"Joseph Sikora","avatar":""},{"name":"Nicole Forester","avatar":""},{"name":"Michael Raymond-James","avatar":""},{"name":"Alexia Fast","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"James Martin Kelly","avatar":""},{"name":"Dylan Kussman","avatar":""},{"name":"Denver Milord","avatar":""},{"name":"Susan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324465);
