INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-ngay-keo-lo', 'Cưới Ngay Kẻo Lỡ', 'Love Puzzle', 'https://phimimg.com/upload/vod/20231108-1/c1df6c98fd5b100b16c021eb63533ac2.jpg', 'https://phimimg.com/upload/vod/20231108-1/5434d491efe12cd266292502a940e224.jpg', '<p>Nữ biên tập viên vốn đã quay cuồng trước những áp lực từ hôn ước, vậy mà anh chàng nhiếp ảnh gia tạp chí mới thuê lại cản trở không chỉ kế hoạch sự nghiệp của cô.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Johnny Nguyen","avatar":""},{"name":"Ngọc Diệp","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Tấn Beo","avatar":""},{"name":"Thanh Thủy","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Diễm My","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324465);
