INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-dong-tien', 'Hương Vị Đồng Tiền', 'The Taste of Money', 'https://phimimg.com/upload/vod/20231106-1/028edc36444585fb77e343d136b16ad5.jpg', 'https://phimimg.com/upload/vod/20231106-1/a39c2a9a6186ce0a5944ff687b98c617.jpg', '<p>Ju Young-Jak là thư ký cho Baek Geum-Ok, một nữ chủ tịch giàu có. Nhận thấy Baek có ham muốn với mình, Ju chấp nhận trở thành người tình của Baek. Tuy nhiên, mọi chuyện đảo lộn khi Ju gặp con gái của Baek, Nami, một cô gái có tính cách hoàn toàn khác so với bà mẹ ham tiền của mình. Ju bị cuốn hút bởi tính cách đặc biệt của Nami, từ đó nảy sinh hàng loạt những mâu thuẫn gay gắt.Nhiều tuyến nhân vật phức tạp, tình yêu cùng thù hận, thể xác và tâm hồn, tiền bạc và nhân phẩm con người, tất cả &nbsp;đan xen, vạch ra cái sự thật ẩn trong vẻ hào nhoáng của tầng lớp thượng lưu. Bộ phim thứ 7 này của đạo diễn Lim Sang Soo được đánh giá là có diễn biến mạnh mẽ và gây bất ngờ hơn bộ phim The housemaid trước đó của ông.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Kang-woo","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Youn Yuh-jung","avatar":""},{"name":"Maui Taylor","avatar":""},{"name":"Kim Hyo-jin","avatar":""},{"name":"Jung Won-joong","avatar":""},{"name":"On Ju-wan","avatar":""},{"name":"Kwon Byung-gil","avatar":""},{"name":"Hwang Jeong-min","avatar":""},{"name":"Kal So-won","avatar":""},{"name":"Darcy Paquet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
