INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-dung-cam', 'Trái Tim Dũng Cảm', 'Brave Hearts: Umizaru', 'https://phimimg.com/upload/vod/20231103-1/105246ffbe8b454c9d7516cb017c0c7c.jpg', 'https://phimimg.com/upload/vod/20231103-1/ace82ed263a64ca8f2f04ffc2c9009dd.jpg', '<p>Mika (Naka Riisa ) là tiếp viên trên chiếc máy bay sắp sửa hạ cánh xuống sân bay Haneda theo đúng lịch trình. Đột nhiên, động cơ máy bay bốc cháy. Để cứu 346 người trên máy bay, Senzaki Daisuke (Ito Hideaki ) và đội cứu hộ được gọi đến thực thi nhiệm vụ...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hideaki Ito","avatar":""},{"name":"Ai Kato","avatar":""},{"name":"Ryuta Sato","avatar":""},{"name":"Riisa Naka","avatar":""},{"name":"Shohei Miura","avatar":""},{"name":"Hiroyuki Hirayama","avatar":""},{"name":"Tsuyoshi Ihara","avatar":""},{"name":"Saburo Tokito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
