INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-ca-hoi-o-yemen', 'Câu Cá Hồi Ở Yemen', 'Salmon Fishing in the Yemen', 'https://phimimg.com/upload/vod/20231103-1/d7018d471666ed9779e7774b0cc0f91d.jpg', 'https://phimimg.com/upload/vod/20231103-1/e19e6f3fcbed5487395394637ee6430f.jpg', '<p>Được chuyển thể từ cuốn tiểu thuyết cùng tên của nhà văn Paul Torday, Salmon Fishing in The Yemen là phim tình cảm được đánh giá cao khi ra mắt tại Mỹ hồi tháng 3. Phim nói về một chuyên gia về cá được một nhà tư vấn tiếp cận để giúp biến giấc mơ của một vị tù trưởng Trung Đông thành sự thực - đưa môn thể thao câu cá tới vùng sa mạc nóng bỏng.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Rachael Stirling","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Catherine Steadman","avatar":""},{"name":"Tom Mison","avatar":""},{"name":"Tom Beard","avatar":""},{"name":"Jill Baker","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Alex Taylor-McDowall","avatar":""},{"name":"Peter Wight","avatar":""},{"name":"Hugh Simon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324465);
