INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-ca-hoi-o-yemen', 'Câu Cá Hồi Ở Yemen', 'Salmon Fishing in the Yemen', 'câu cá hồi ở yemen salmon fishing in the yemen ewan mcgregor emily blunt kristin scott thomas rachael stirling amr waked catherine steadman tom mison tom beard jill baker conleth hill alex taylor-mcdowall peter wight hugh simon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('au-trung-tinh-nghich-phan-2', 'Ấu Trùng Tinh Nghịch (Phần 2)', 'Larva (Season 2)', 'https://phimimg.com/upload/vod/20240908-1/5043e597a1f1700dba8f3ced8518ac7f.jpg', 'https://phimimg.com/upload/vod/20240908-1/795c640e69b90d834ed676c6b24dfb1f.jpg', '<p>Ấu trùng tinh nghịch là một phim truyền hình hài hoạt hình trên máy tính được tạo bởi Tuba Entertainment ở Seoul, Hàn Quốc. Phim hoạt hình này cho thấy hai ấu trùng là nhân vật chính của nó. Vàng - Ấu trùng vàng đi chậm và tham ăn. Anh ta luôn lắng nghe Đỏ nhưng thường mất kiểm soát bản thân khi nhìn thấy thức ăn. Đỏ - Ấu trùng đỏ có tính cách khó gần và thiếu kiên nhẫn. Anh ta hét lên như Bruce Lee (Lý Tiểu Long) và đá chân lên không trung mặc dù anh ta không có chân như con người. Đỏ là một nhân vật luôn trải qua đau khổ. Hầu hết bắt đầu với lòng tham cho một cái gì đó.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 10, 2012, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"홍범기","avatar":""},{"name":"안효민","avatar":""},{"name":"강시현","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
