INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-nguoi-dan-ong-ngot-ngao', 'Đi tìm người đàn ông ngọt ngào', 'Searching for Sugar Man', 'https://phimimg.com/upload/vod/20231101-1/cecc15612b4f4faf35ea1782f6e876ca.jpg', 'https://phimimg.com/upload/vod/20231101-1/6c1fe055a4cf32a480201e2f073e459e.jpg', '<p>Hai người Nam Phi bắt đầu khám phá điều gì đã xảy ra với người hùng âm nhạc khó có thể xảy ra của họ, nghệ sĩ rock &#39;n&#39; patin bí ẩn những năm 1970, Rodriguez. Phim đoạt giải Phim tài liệu hay nhất tại Lễ trao giải Oscar lần thứ 85.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Stephen Segerman","avatar":""},{"name":"Rodriguez","avatar":""},{"name":"Regan Rodriguez","avatar":""},{"name":"Eva Rodriguez","avatar":""},{"name":"Mike Theodore","avatar":""},{"name":"Dennis Coffey","avatar":""},{"name":"Sandra Rodriguez-Kennedy","avatar":""},{"name":"Clarence Avant","avatar":""},{"name":"Steve Rowland","avatar":""},{"name":"Malik Bendjelloul","avatar":""},{"name":"Dan DiMaggio","avatar":""},{"name":"Jerome Ferretti","avatar":""},{"name":"Willem Möller","avatar":""},{"name":"Craig Bartholomew Strydom","avatar":""},{"name":"Ilse Assmann","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324465);
