INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('di-tim-nguoi-dan-ong-ngot-ngao', 'Đi tìm người đàn ông ngọt ngào', 'Searching for Sugar Man', 'đi tìm người đàn ông ngọt ngào searching for sugar man stephen segerman rodriguez regan rodriguez eva rodriguez mike theodore dennis coffey sandra rodriguez-kennedy clarence avant steve rowland malik bendjelloul dan dimaggio jerome ferretti willem möller craig bartholomew strydom ilse assmann s ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-5', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 5)', 'Star Wars: The Clone Wars (Season 5)', 'https://phimimg.com/upload/vod/20240624-1/c454aa5e7db49f50a8b084fce7016d68.jpg', 'https://phimimg.com/upload/vod/20240624-1/dcaae6478025cb05b83eb1b569a5fb99.jpg', '<p>Bóng tối của mặt tối đổ xuống trên Star Wars: The Clone Wars Season Five khi loạt phim tiến gần hơn đến các sự kiện nghiệt ngã của Star Wars: Episode III Revenge of the Sith. Những pha hành động trên màn ảnh rộng, những nhân vật khó quên và cuộc phiêu lưu thú vị của Star Wars Saga vẫn tiếp tục khi các anh hùng Jedi đối mặt với vô số kẻ thù. Với hình ảnh, âm thanh, hành động và phiêu lưu tuyệt vời, Star Wars: The Clone Wars tiếp tục câu chuyện điện ảnh tương đương với một bộ phim hoạt hình ngắn Star Wars mỗi tuần. Phần Năm tràn ngập những pha hành động bùng nổ, thế giới kỳ lạ, những nhân vật hấp dẫn và những bước ngoặt gây sốc khi một số người chơi chính phải đối mặt với số phận của mình khi thiên hà chìm vào bóng tối.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324465);
