INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-16-tien-dao-thu-11', 'Thám Tử Lừng Danh Conan 16: Tiền Đạo Thứ 11', 'Detective Conan: The Eleventh Striker', 'https://phimimg.com/upload/vod/20231019-1/8f707299648e4d9fc8f1aa852f009061.jpg', 'https://phimimg.com/upload/vod/20231019-1/14ff3746443511d1d7139cf05d45aed3.jpg', '<p>Một lá thư nặc danh được gửi tới văn phòng thám tử Mori với nội dung khá bí ẩn, dưới dạng mật mã &quot;Cậu bé mặc áo Xanh và Xanh sọc ... mưa từ trời cao đổ xuống ...&quot; và đe dọa sẽ đánh bom. Nếu Conan giải được mật mã thì bom sẽ không nổ. Một nhiệm vụ khó khăn mới dành cho Conan và nhóm thám tử nhí ngay trong trận cầu khốc liệt giữa 2 đội bóng Tokyo Spirit (có Hide) và Big Osaka (của Higo).</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2012, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Mirei Kiritani","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Kazuyoshi Miura","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Koji Tsujitani","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Atsuko Yuy","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324465);
