INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-tin-tuc-phan-1', 'Phòng Tin Tức (Phần 1)', 'The Newsroom (Season 1)', 'https://phimimg.com/upload/vod/20240809-1/71aeac5e6c814acd62e76833096caf81.jpg', 'https://phimimg.com/upload/vod/20240809-1/4243c9f53d50f235e7868e70963b4fde.jpg', '<p>Một người dẫn chương trình tin tức nổi tiếng vì tính cách khó chịu phải tham gia vào chuyên mục mới để cứu vãn tình hình bết bát về tỉ suất xem, và hợp tác với tình cũ của anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeff Daniels","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Thomas Sadoski","avatar":""},{"name":"Dev Patel","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Sam Waterston","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
