INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-the-phan-3', 'Thất Thế (Phần 3)', 'Eastbound & Down (Season 3)', 'https://phimimg.com/upload/vod/20240808-1/68096377544663b467f846df2fe7cbe4.jpg', 'https://phimimg.com/upload/vod/20240808-1/296003f5c357493ab3752370a21a3354.jpg', '<p>Nhiều năm sau khi quay lưng lại với quê hương, một cầu thủ bóng chày chuyên nghiệp đã kiệt sức và quay trở lại dạy thể dục tại trường trung học cơ sở cũ của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny McBride","avatar":""},{"name":"Steve Little","avatar":""},{"name":"Katy Mixon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
