INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scoobydoo-doi-giai-ma-bi-an-phan-2', 'Scooby-Doo! Đội Giải Mã Bí Ẩn (Phần 2)', 'Scooby-Doo! Mystery Incorporated (Season 2)', 'https://phimimg.com/upload/vod/20240808-1/9e82e21eb5748ff37bf23527b9fbddc3.jpg', 'https://phimimg.com/upload/vod/20240808-1/4599b2c712c08076ba26ec870fe21456.jpg', '<p>Phiên bản này của loạt phim hoạt hình nổi tiếng kể về Scooby và nhóm bạn sống ở Crystal Cove, một thị trấn nhỏ có lịch sử lâu đời về việc nhìn thấy ma, những câu chuyện về quái vật và những bí ẩn khác mà các thám tử phải giải quyết một lần và mãi mãi. Nhưng những cư dân lâu đời của Crystal Cove, những người dựa vào danh tiếng của thị trấn để thu hút khách du lịch, đã chuẩn bị sẵn sàng để làm mọi cách để bảo vệ lãnh thổ của họ.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 10, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Frank Welker","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Mindy Cohn","avatar":""},{"name":"Matthew Lillard","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324465);
