INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-vuong-quyen-phan-2', 'Trò Chơi Vương Quyền (Phần 2)', 'Game Of Thrones (Season 2)', 'https://phimimg.com/upload/vod/20240730-1/bc8c1ee26261c9fa192d253088f23ed2.jpg', 'https://phimimg.com/upload/vod/20240730-1/d31b8be8fcc5409cce4ec2d016806ba5.jpg', '<p>Tiếp nối phần 1 , với phần 2 lần này phim nói về Vùng đất huyền thoại Westeros đang tiếp tục bị 7 gia đình quý tộc đấu đá nhau để giành quyền kiểm soát, nhằm đạt được mục đích 7 gia tộc này đã không từ bất kì thủ đoạn nào dù có bỉ ổi đến mấy. Theo thống kê Game of Thrones 2 là 1 trong những bộ phim được mong chờ nhất năm 2012. Giống như phần 1, phần 2 của loạt phim này làm khán giả mãn nhãn với những cảnh quay hoành tráng những tình huống căng thẳng tới ngẹt thở đẩy người xem vào trạng thái không biết nhân vật của mình sẽ chết lúc nào.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Iain Glen","avatar":""},{"name":"Emilia Clarke","avatar":""},{"name":"Lena Headey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
