INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sui-gia-nan-giai', 'Sui Gia Nan Giải', 'Divas in Distress', 'https://phimimg.com/upload/vod/20240729-1/39be380f0f0d418e9305a8d1a517d7e7.jpg', 'https://phimimg.com/upload/vod/20240729-1/d646efb0df63cb8f208d9f3589b005cd.jpg', '<p>Nói về cuộc chiến của hai người trước kia là đồng nghiệp của nhau trong cùng một công ty nhưng do mâu thuẫn họ đã trở thành oan gia với nhau trong vòng 30 năm và hầu như cắt dứt mối liên hệ với nhau. Nhưng một ngày kia, con cái của họ lại lẩn quẩn trong vòng vây tình cảm làm cho cả hai thế hệ điều khốn đốn. Con của họ luôn bị rơi vào tình thế khó xử khi người lớn hai bên luôn không nể mặt nhau. Liệu cuộc chiến 30 năm của họ còn kéo dài bao lâu? Họ có vì con cái mà giải hòa hay con cái của họ phải hy sinh tình cảm vì đấng sinh thành?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 10, 2012, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Liza Wang","avatar":""},{"name":"Gigi Wong","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Him Law","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Eliza Sam","avatar":""},{"name":"李成昌","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"鍾景輝","avatar":""},{"name":"古明華","avatar":""},{"name":"Janice Shum","avatar":""},{"name":"蘇恩磁","avatar":""},{"name":"魏惠文","avatar":""},{"name":"張慧雯","avatar":""},{"name":"Eddy Law Tin-Chi","avatar":""},{"name":"Esther Wan","avatar":""},{"name":"Mark Ma","avatar":""},{"name":"Kirby Lam","avatar":""},{"name":"Dickson Lee","avatar":""},{"name":"夏竹欣","avatar":""},{"name":"于洋","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324465);
