INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-giac-la', 'Cảm Giác Lạ', '2 + 2', 'https://phimimg.com/upload/vod/20240728-1/2a38d25aa4895662fc709e952eed8775.jpg', 'https://phimimg.com/upload/vod/20240728-1/bbfcf7c66d2952255533900ffc0f75d8.jpg', '<p>Khi những niềm vui của những cuộc hẹn hò bắt đầu già đi, Richard và Bettina chia sẻ một bí mật với bạn bè của họ Diego và Emilia: Họ bắt đầu một cuộc sống với những cảm giác lạ từ những buổi hẹn hò nhanh chóng.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Adrián Suar","avatar":""},{"name":"Carla Peterson","avatar":""},{"name":"Juan Minujín","avatar":""},{"name":"Julieta Díaz","avatar":""},{"name":"Alfredo Casero","avatar":""},{"name":"Tomás Wicz","avatar":""},{"name":"Micaela Cuccaresi","avatar":""},{"name":"Juana Wein","avatar":""},{"name":"Nicolas Torcanowsky","avatar":""},{"name":"Kevin Melnisky","avatar":""},{"name":"Judith Kusnir","avatar":""},{"name":"Paula Baldini","avatar":""},{"name":"Pierre Fremond","avatar":""},{"name":"Gabriel Harrison","avatar":""},{"name":"Ana Inés Hermida","avatar":""},{"name":"Federico Taramasco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324465);
