INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thu-toi-cua-ke-sat-nhan', 'Lời Thú Tội Của Kẻ Sát Nhân', 'Confession Of Murder', 'https://phimimg.com/upload/vod/20231219-1/4b82b0d54f18f311c7278d758ba129ec.jpg', 'https://phimimg.com/upload/vod/20231219-1/6b8ee3856b98e93babd86320a497537f.jpg', '<p>Confession of Murder là một phim hành động kinh dị, xoay quanh Lee Doo Suk, một kẻ giết người hàng loạt. Sau khi thời hạn điều tra vụ án của mình hết hạn, anh ta đã xuất bản cuốn tự truyện và từ đó trở thành người nổi tiếng. Tuy nhiên, thám tử Choi Hyung Goo (Jung Jae Young thủ vai), người từng phụ trách vụ án của Lee Doo Suk 15 năm trước, luôn nghi ngờ con người của Lee Doo Suk. Choi Hyung Goo cố gắng đưa anh ta vào tù bằng cách tìm kiếm những bằng chứng về một số trường hợp mất tích chưa tìm ra nguyên nhân dường như có liên quan tới anh ta.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Won-Young Choi","avatar":""},{"name":"Gwang Jang","avatar":""},{"name":"Jae-yeong Jeong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
