INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-ong-dich-thuc', 'Đàn Ông Đích Thực', 'Think Like a Man', 'https://phimimg.com/upload/vod/20231108-1/548e4311abac4945901260eae8d1c985.jpg', 'https://phimimg.com/upload/vod/20231108-1/0e1b3c043622e2323b28593132085d66.jpg', '<p>Bốn phụ nữ bắt đầu giải quyết các vấn đề trong mối quan hệ của họ theo lời khuyên từ một cuốn sách bán chạy. Nhưng bạn đời của họ lại chẳng mấy hợp tác.</p>', 'Full', 1, 'single', 'completed', 5, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Ealy","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Terrence Jenkins","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Gary Owen","avatar":""},{"name":"La La Anthony","avatar":""},{"name":"Chris Brown","avatar":""},{"name":"Wendy Williams","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"Caleel Harris","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Ste","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324465);
