INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-5', 'Gã Điên (Phần 5)', 'Mad Men (Season 5)', 'https://phimimg.com/upload/vod/20240606-1/e795cac4980d242ea00ce769ac2febba.jpg', 'https://phimimg.com/upload/vod/20240606-1/13e887cd07f0afe0a5dc282b56ab5c9e.jpg', '<p>Phần 5 diễn ra từ Ngày tưởng niệm năm 1966 đến mùa xuân năm 1967. Phần này khám phá cuộc hôn nhân mới của Don Draper với Megan, khiến anh ta bỏ qua công việc của mình tại công ty quảng cáo Sterling Cooper Draper Pryce. Trong khi đó, Lane, Pete, Roger, Joan và Peggy biết được rằng “mỗi người đàn ông đều vì chính mình” trong cuộc sống cá nhân và nghề nghiệp của họ khi mỗi người phải đối mặt với những khởi đầu mới đầy đau đớn.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2012, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
