INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-grimm-phan-2', 'Anh Em Nhà Grimm (Phần 2)', 'Grimm (Season 2)', 'https://phimimg.com/upload/vod/20240317-1/8ad9c6f46461bf11d9f6e3cdac6e7cdf.jpg', 'https://phimimg.com/upload/vod/20240317-1/36fc80d8d9b7faa5cdfd93292587fa0a.jpg', '<p>Grimm là một show truyền hình của đài NBC, ra mắt lần đầu tiên vào 28.10.2011. Phim theo thể loại điều tra, phá án, rừng rợn và được lấy cảm hứng từ những câu chuyện cổ tích kinh điển của anh hem nhà Grimm nhưng series được biến tấu dưới một cách nhìn khác táo bạo, li kỳ, và thực tế hơn với cuộc sống.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Giuntoli","avatar":""},{"name":"Silas Weir Mitchell","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"Sasha Roiz","avatar":""},{"name":"Reggie Lee","avatar":""},{"name":"Bree Turner","avatar":""},{"name":"Claire Coffee","avatar":""},{"name":"Elizabeth Tulloch","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324465);
