INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-trang-len', 'Vương Quốc Trăng Lên', 'Moonrise Kingdom', 'https://phimimg.com/upload/vod/20240228-1/a8be76edd4dc010ac3a1e1a05897b404.jpg', 'https://phimimg.com/upload/vod/20240228-1/0274752ca9db0dfcca4f7e8487510ca5.jpg', '<p>Phim lấy bối cảnh New England những năm 1960, một cặp đôi yêu nhau đã bỏ trốn khỏi thị trấn New England, khiến cho một đội tìm kiếm địa phương phải tỏa ra để tìm kiếm hai người họ và cuộc sống của người dân thị trấn bị đảo lộn, và điều đó có khi lại là điều tốt cho thị trấn...</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jared Gilman","avatar":""},{"name":"Kara Hayward","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Bob Balaban","avatar":""},{"name":"Lucas Hedges","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
