INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-vo-dang', 'Đại Võ Đang', 'Wu Dang', 'https://phimimg.com/upload/vod/20240228-1/e830feeaa1ae6f50c019338117685844.jpg', 'https://phimimg.com/upload/vod/20240228-1/9889c79d2a2ca597b2d408a1d2d35148.jpg', '<p>Câu chuyện trong Đại Võ Đang - Thiên địa mật mã diễn ra vào thời Dân Quốc, tương truyền trên núi Võ Đang cất giấu ba bảo vật hiếm thấy, cô gái Thiên Tâm - hậu nhân của một gia tộc võ học đến từ dị vực cùng với nhà thám hiểm người Mỹ Đường Vân Long và con gái nuôi của anh là Đường Ninh mượn danh nghĩa đến tham gia tỷ thí võ thuật để mưu đồ cướp đoạt bảo vật. Đệ tử tục gia của Võ Đang là Thủy Hợp Nhất vô tình được chọn làm đại diện cho môn phái tham gia tranh giành ngôi vị quán quân võ thuật. Cuộc chiến đoạt bảo vạn phần hiểm nguy cũng theo đó mà chính thức lên đài.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Xu Jiao","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Henry Fong","avatar":""},{"name":"Shaun Tam Chun-Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324465);
