INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ngang-trai', 'Tình Ngang Trái', 'Love Actually... Sucks!', 'https://phimimg.com/upload/vod/20240228-1/0eb52e1f6a5d1e1bac0d45e37bb5d0cf.jpg', 'https://phimimg.com/upload/vod/20240228-1/7d92c2a926a44f8e9178a0182bb7af3a.jpg', '<p>Tình Ngang Trái – Love Actually… Sucks! (2012) được lấy cảm hứng từ những câu chuyện có thật trong cuộc sống và mở đầu bằng một bữa tiệc cưới đầy kịch tính với màn trả thù không thể bất ngờ hơn. Sau đó, phim đưa người xem theo dõi lần lượt sáu câu chuyện về tình yêu, tình dục và sự suy đồi đã trở nên sai trái: một anh trai và em gái trong mối quan hệ loạn luân.Một nam họa sĩ đã kết hôn phải lòng người mẫu nam trẻ tuổi của mình, một giáo viên trường múa người bị vây hãm với Queen, một trong những học sinh của anh ta và là một phụ nữ giàu có, mối tình tay ba giữa Moon – một phụ nữ trung niên trong mối tình tay ba phức tạp với hai người đàn ông trẻ tuổi, một trong hai người là rắc rối và cô ấy muốn thoát khỏi anh ta và một một cặp đôi đồng tính nữ, một trong số họ mắc chứng hoang tưởng đóng vai.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Osman Hung","avatar":""},{"name":"Linda So","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
