INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-ngang-trai', 'Tình Ngang Trái', 'Love Actually... Sucks!', 'tình ngang trái love actually... sucks! osman hung linda so ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tot-thi', 'Con Tốt Thí', 'Gambit', 'https://phimimg.com/upload/vod/20240228-1/2fc7c1ed1b041b4b76919fd623f370a0.jpg', 'https://phimimg.com/upload/vod/20240228-1/d4f4d1b4f8b5f8a3676eb542fe0b14ef.jpg', '<p>Lấy bối cảnh London và New Mexico, bộ phim hài có sự tham gia của tài tử Colin Firth và minh tinh Cameron Diaz xoay quanh nhân vật chính là Harry Deane - một tay giám tuyển nghệ thuật ở London. Anh này nhờ tới sự trợ giúp từ một cô nàng cao bồi Texas chính hiệu trong kế hoạch bán bức tranh giả cho người đàn ông giàu nhất nước Anh. Những tình huống dở khóc dở cười xảy ra khiến câu chuyện “tranh giả” đi theo một hướng khác.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Alan Rickman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324465);
