INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-quan-dia-nguc', 'Đội Quân Địa Ngục', 'Outpost: Black Sun', 'https://phimimg.com/upload/vod/20240227-1/92e9080b6bdb8fbd207d929bebb1c996.jpg', 'https://phimimg.com/upload/vod/20240227-1/357efc85ca445598c655027bcdda0a2c.jpg', '<p>Một cặp điều tra viên hợp tác với một Đơn vị Lực lượng Đặc biệt để dấn thân vào sâu bên trong cuộc chiến đang diễn ra ác liệt giữa quân đội và đội quân Zombie Stormtroopers đông đảo của Đức Quốc xã. Nhiệm vụ của họ là chiến đấu phía sau chiến tuyến của kẻ thù, xác định vị trí công nghệ tại nguồn gốc của mối đe dọa ngày càng tăng này và ngăn chặn sự trỗi dậy dường như không thể tránh khỏi của Đế chế thứ 4.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Catherine Steadman","avatar":""},{"name":"Richard Coyle","avatar":""},{"name":"Ali Craig","avatar":""},{"name":"Daniel Caltagirone","avatar":""},{"name":"Nick Nevern","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324465);
