INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than', 'Tình Thân', 'The Descendants', 'https://phimimg.com/upload/vod/20240227-1/527be4e0fac310448787f93ccdfc1dff.jpg', 'https://phimimg.com/upload/vod/20240227-1/2d1899fe8b14e620b9646d9bae4b3b88.jpg', '<p>Bộ phim tâm lí hài dựa trên cuốn tiểu thuyết của Kaui Hart Hemmings. Matt King là người đại diện cho vùng đất của gia đình ông tại Hawaii, đang cố gắng kết nối lại với 2 cô con gái của mình sau tai nạn chèo thuyền nghiêm trọng khiến Elizabeth - vợ ông rơi vào trạng thái hôn mê. Trước áp lực của các phe phái về việc bán đất, Matt King đưa 2 cô con gái theo trên 1 chuyến đi từ Oahu tới Kauai để đối mặt với 1 nhà môi giới bất động sản trẻ tuổi - người có mối quan hệ với Elizabeth trước khi cô gặp tai nạn bất hạnh, và muộn màng biết được 1 bí mật về vợ mình.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Shailene Woodley","avatar":""},{"name":"Amara Miller","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324465);
