INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-choi-voi-virus', 'Chống Chọi Với Virus', 'Antiviral', 'https://phimimg.com/upload/vod/20240227-1/7c30133b9346036c55bed995fdbcffde.jpg', 'https://phimimg.com/upload/vod/20240227-1/f36f454d7ca8422948ddaf4ba5a33c07.jpg', '<p>Syd March là một nhân viên tại một phòng khám chuyên bán thuốc tiêm vi rút sống thu được từ những người nổi tiếng bị bệnh cho những người hâm mộ bị ám ảnh. Khi bị nhiễm căn bệnh giết chết siêu cảm giác Hannah Geist, Syd trở thành mục tiêu của những nhà sưu tập và những người hâm mộ cuồng nhiệt. Anh phải làm sáng tỏ bí ẩn xung quanh cái chết của cô trước khi chịu chung số phận.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Caleb Landry Jones","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Joe Pingue","avatar":""},{"name":"Sheila McCarthy","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324465);
