INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-kho', 'Gã Khờ', 'The Innocent Man', 'https://phimimg.com/upload/vod/20240209-1/1f5604705e59af3f708f0bb92d28103e.jpg', 'https://phimimg.com/upload/vod/20240209-1/43051b11e3d1a713e4a1751487e77582.jpg', '<p>Gã khờ - The Innocent Man là bộ phim tâm lý xã hội mang phong cách cổ điển về sự phản bội, sự trả thù và tình yêu. Mỹ nam Song Joong-ki trong phim thủ vai Kang Ma-ru, một chàng trai thư sinh trong sáng có một tình yêu đẹp. Nhưng mọi chuyện thay đổi hoàn toàn, khi Ma-ru bị phản bội bởi chính người bạn gái chạy theo tiền tài và danh vọng. Nhiều năm sau, Ma-ru trở lại mang trong mình mối hận và một kế hoạch trả thù những kẻ phản bội. Anh lên kế hoạch quyến rũ Seo Eun-gi, con gái của một tài phiệt và biến cô thành con tốt trong kế hoạch của mình. Mọi chuyện sẽ ra sao, khi thiện lương trong Ma-ru được đánh thức bởi chính tình cảm chân thành của Eun-gi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon Chae-Won","avatar":""},{"name":"Song Joong Ki","avatar":""},{"name":"Park Shi Yeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324465);
