INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-ma-ca-rong', 'Cô Bạn Ma Cà Rồng', 'The Moth Diaries', 'https://phimimg.com/upload/vod/20240220-1/f8c8226a46ebbc76357215df3eecfc2d.jpg', 'https://phimimg.com/upload/vod/20240220-1/31a11d6e2ecdf3581b562917cd9335a6.jpg', '<p>Hai cô gái trẻ Rebecca và Lucy sống vui vẻ hạnh phúc bên nhau cho đến khi có sự xuất hiện của cô gái bí ẩn Ernessa với khuôn mặt lạnh lùng, nước da nhợt nhạt xanh xao, không ăn bất cứ thứ gì và thường lãng vãng trước cửa sổ phòng của các nữ sinh vào ban đêm. Lucy nhanh chóng đã bị vẻ đẹp của Ernessa quyến rũ hút hồn. Rebecca dần nhận ra điều đó và cố tìm hiểu mọi chuyện để tìm lại Lucy trước đây mà cô từng biết. Và bi kịch bắt đầu từ những cái chết bí ẩn của những người xung quanh...</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sarah Bolger","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Lily Cole","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324465);
