INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhanh-hay-chet', 'Nhanh Hay Chết', 'Quick', 'https://phimimg.com/upload/vod/20240220-1/95892bb58747089405a2efc6c5dc7cb0.jpg', 'https://phimimg.com/upload/vod/20240220-1/2e43bb11d11cd72a83101933eb7703d0.jpg', '<p>Vào một ngày định mệnh, Ki-su, một nhân viên giao hàng chuyên nghiệp cùng cô bạn gái cũ Ah-rom bị lừa tham gia vào một loạt các vụ đánh bom trong thành phố. Vấn đề là ở chỗ, trên mũ bảo hiểm của Ah-rom có gắn một quả bom có thể được kích hoạt từ xa hoặc sẽ phát nổ nếu như hai người đứng cách nhau quá 10 mét. Cả hai phải làm thế nào để có thể vượt qua tình thế này?</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Min-ki Lee","avatar":""},{"name":"Ye-won Kang","avatar":""},{"name":"In-kwon Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
