INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vat-the-la', 'Vật Thể Lạ', 'Alien Uprising', 'null', 'https://phimimg.com/upload/vod/20240219-1/c05904cc258d623a7b0c2bfd4cd9ea70.jpg', '<p>Vật Thể Lạ - Alien Uprising xoay quanh một nhóm bạn bè vui chơi trong một đêm tại quán bar. một đôi tình nhân chia sẻ với mọi người ở đó về một cuộc sống thật đẹp đang có. Và rồi không may thay, những điều kỳ lạ bắt đầu xảy ra. Trong phim, mất điện toàn thành phố. Không điện thoại, không có đèn, trong bóng tối họ đã cố gắng để đối phó. Sau đó, là một cuộc xâm lược từ UFO, những người khổng lồ! Bầu trời tối sầm lại bởi các tàu của những kẻ xâm lược ngoài hành tinh. chúng bắt đầu tiếp quản Trái đất năm người bạn đấu tranh để tồn tại trong cơn hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Simon Phillips","avatar":""},{"name":"Joey Ansah","avatar":""},{"name":"Julian Glover","avatar":""},{"name":"Sean Brosnan","avatar":""},{"name":"Sean Pertwee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
