INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-kia-ngu-o-tren-tuong', 'Gương Kia Ngự Ở Trên Tường', 'Mirror Mirror', 'https://phimimg.com/upload/vod/20240219-1/01e9f3adc9c11f9c161f853499824a08.jpg', 'https://phimimg.com/upload/vod/20240219-1/23747ba69514957cd68c1b5f01a11d95.jpg', '<p>Mirror Mirror là một câu chuyện cổ tích cổ điển với sự tham gia của diễn viên đoạt giải Oscar Julia Roberts trong vai Nữ hoàng, Lily Collins (The Blind Side) trong vai Nàng Bạch Tuyết, Armie Hammer (The Social Network) trong vai Hoàng Tử Alcott, Sean Bean (“The Game of Thrones”, The Lord of the Rings: The Return of the King) trong vai Nhà Vua và Nathan Lane (The Lion King, The Birdcage) trong vai người đầy tớ Brington của Nữ Hoàng. Bộ phim Mirror Mirror là câu chuyện xoay quanh mụ nữ hoàng độc ác giành quyền kiểm soát một vương quốc và một công chúa lưu vong tuyển mộ sự giúp đỡ của bảy phiến quân tháo vát để giành lại quyền thừa kế của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lily Collins","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Armie Hammer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324465);
