INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-dam-thep', 'Bà Đầm Thép', 'The Iron Lady', 'https://phimimg.com/upload/vod/20240219-1/ebfb9fad70dda6cd736b1e1724aaba7a.jpg', 'https://phimimg.com/upload/vod/20240219-1/45573572905f6864177b0e691ece8d1b.jpg', '<p>Bộ phim kể câu chuyện về Margaret Thatcher - cựu thủ tướng Anh, người đã vượt qua mọi rào cản về giới tính và tầng lớp xã hội để có được vị trí chính trị trong một xã hội nam quyền. Chuyện phim còn đề cập đến những vấn đề về quyền lực và những cái giá phải trả cho quyền lực trong khi mô tả bức chân dung chân thực nhất về người phụ nữ phi thường này...</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Richard E. Grant","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324465);
