INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-ba-con-gai', 'Nhà Có Ba Con Gái', 'Darling Mother Darling Daughters', 'https://phimimg.com/upload/vod/20240126-1/cdcb0c4894acb6504f5eea61d95ddc7d.jpg', 'https://phimimg.com/upload/vod/20240126-1/e6061f530e8c37da98217db394e327fb.jpg', '<p>Nhà Có Ba Con Gái là bộ phim đài loan kể về gia đình có 2 cô con gái khắc khẩu do cùng cha khác mẹ, cuộc sống của bốn bố con ông Chí Minh trải qua nhiều sóng gió. Cuộc đời mỗi người được lột tả sống động trong các mối quan hệ phức tạp, chất chứa không chỉ tình yêu, ước mơ, sự tin tưởng mà còn cả lòng thù hận và những mưu toan ích kỷ…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2012, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lộ Thần","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Mã Thiên Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324465);
