INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-vo-danh', 'Điệp Viên Vô Danh', 'The Expatriate', 'https://phimimg.com/upload/vod/20240207-1/eddb46785cfd1e0c7fab3dbfc5462855.jpg', 'https://phimimg.com/upload/vod/20240207-1/8dde2c03c247c8f59d8123deb0f7cacc.jpg', '<p>Một người đàn ông đã từng làm việc cho CIA. Trong thời gian nghỉ ông ta và cô con gái đã bị lôi cuốn vào một phi vụ dẫn tới nguy hiểm tới tính mạng. Hai cha con đã phải vượt qua rất nhiều khó khăn, chạy chốn, tự điều tra để tìm cho mình cơ hội sống.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Nick Alachiotis","avatar":""},{"name":"Liana Liberato","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
