INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('inescapable', 'Inescapable', 'Inescapable', 'https://phimimg.com/upload/vod/20240207-1/f0f0ccbd31e8a37662aeb6491872f854.jpg', 'https://phimimg.com/upload/vod/20240207-1/ee1570b1f62b0e4ba29501b5a03d85b9.jpg', '<p>Hai mươi lăm năm trước Adib, một sĩ quan trẻ đầy triển vọng trong quân cảnh Syria, đột ngột rời khỏi Damascus trong hoàn cảnh đáng ngờ. Từ bỏ tình yêu của đời mình là Fatima, anh lên đường đến Canada và quét sạch phiến đá. Khi con gái Muna của ông đột nhiên biến mất ở Damascus, quá khứ của ông có nguy cơ bắt kịp ông một cách thô bạo. Hợp tác với một sứ giả người Canada, giờ đây Adib phải đối mặt với tình trạng hỗn loạn mà anh cho rằng mình đã bỏ lại phía sau để tìm Muna.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Siddig","avatar":""},{"name":"Joshua Jackson","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Saad Siddiqui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324465);
