INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-angels-share', 'The Angels'' Share', 'The Angels'' Share', 'https://phimimg.com/upload/vod/20240207-1/732a9246d4e106daad087f819b9394bb.jpg', 'https://phimimg.com/upload/vod/20240207-1/17d8883fe38fcdcb0471ccd62812868d.jpg', '<p>Suýt thoát án tù, ông bố mới Robbie thề sẽ lật ngược tình thế. Chuyến thăm nhà máy chưng cất rượu whisky đã truyền cảm hứng cho anh và những người bạn của mình tìm cách thoát khỏi cuộc sống vô vọng.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Brannigan","avatar":""},{"name":"Siobhan Reilly","avatar":""},{"name":"John Henshaw","avatar":""},{"name":"Gary Maitland","avatar":""},{"name":"William Ruane","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
