INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-cua-quy-du', 'Bài Học Của Quỷ Dữ', 'Lesson Of The Evil', 'https://phimimg.com/upload/vod/20240207-1/9db58c91e9d70157311a0aa73291935a.jpg', 'https://phimimg.com/upload/vod/20240207-1/d4c15c4cca4d08360749589efe61b763.jpg', '<p>Lesson of the Evil bắt đầu khi giáo viên trẻ Seiji Hasumi tới dạy tại trường trung học Shinko Academy. Tại đây, Seiji được cả học sinh lẫn đồng nghiệp yêu mến và tôn trọng. Thế nhưng, sau một vài vụ việc kỳ lạ xảy ra, một nữ sinh 17 tuổi tên Reika Katagiri luôn có cảm giác nghi ngờ vị giáo viên mới đáng kính này. Dần dà, cô phát hiện ra rằng hắn bị mắc bệnh tâm thần và nhiều người hắn quen trước đây đã bị chết. Để giải quyết một số vấn đề trong trường học như bạo lực, lạm dụng, Seiji đã quyết định lần lượt giết từng học trò của mình...</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Takayuki Yamada","avatar":""},{"name":"Ruth Sundell","avatar":""},{"name":"Fumi Nikaidô","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324465);
