INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-la-xac-song-a-phan-2', 'Đây Là Xác Sống à? (Phần 2)', 'Is This A Zombie? (Season 2)', 'https://phimimg.com/upload/vod/20240118-1/d0ebf2ec1a3fc3bb8b4033ddc7e887f4.jpg', 'https://phimimg.com/upload/vod/20240118-1/6a31ac9f49f75172ea63fbbda3a2d2ba.jpg', '<p>Ayumu và Eucliwood đối mặt với những rắc rối ở trường trung học trong khi phải vật lộn với danh tiếng mới và kẻ thù cũ của Ayumu ở địa ngục.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Majima Junji","avatar":""},{"name":"Nomizu Iori","avatar":""},{"name":"Hikasa Yoko","avatar":""},{"name":"Kanemoto Hisako","avatar":""},{"name":"Yoshino Hiroyuki","avatar":""},{"name":"Shimizu Ai","avatar":""},{"name":"Shitaya Noriko","avatar":""},{"name":"Yamaguchi Rie","avatar":""},{"name":"Mina","avatar":""},{"name":"Kitaoka Chiharu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324465);
