INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('2-ngay-o-new-york', '2 Ngày Ở New York', '2 Days In New York', 'https://phimimg.com/upload/vod/20240205-1/722506edd9189684a961c4f7f158e99e.jpg', 'https://phimimg.com/upload/vod/20240205-1/3a0b7d83bf6b196cb2b5b847f32fc565.jpg', '<p>Marion và Mingus đều xuất thân từ những mối tình không thành, nhưng bằng cách tập hợp các con lại với nhau, họ đã tạo dựng được một gia đình nhỏ nhưng hạnh phúc. Căng thẳng trong gia đình họ sớm bắt đầu tăng cao khi người cha vui tính của Marion xuất hiện trước cửa nhà họ cùng với cô con gái ngổ ngáo và người bạn trai kỳ dị của cô ấy đi cùng. Khi những vị khách lắm mồm phá vỡ mọi điều cấm kỵ có thể tưởng tượng được, cặp đôi hạnh phúc bắt đầu đặt câu hỏi về cam kết của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julie Delpy","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Albert Delpy","avatar":""},{"name":"Kate Burton","avatar":""},{"name":"Dylan Baker","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
