INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-chong-co-bac', 'Vợ Chồng Cờ Bạc', 'Mr. & Mrs. Gambler', 'https://phimimg.com/upload/vod/20240205-1/86aa2f04915faa4555f585c825c514e4.jpg', 'https://phimimg.com/upload/vod/20240205-1/39ef769b29c1b8333f41fc837e1a559a.jpg', '<p>Phim là phiên bản kết hợp của hai bộ phim Gia đình siêu nhân (The Incredibles) và Ông bà Smith (Mr. and Mrs. Smith). Với dàn diễn viên nổi tiếng cùng với sự kết hợp của những pha võ thuật hành động hài chắc chắn sẽ làm khán giả hài lòng.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Đỗ Vấn Trạch","avatar":""},{"name":"Tiết Khải Kì","avatar":""},{"name":"Kar-Ying Law","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324465);
