INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-khi-chien-binh', 'Hào Khí Chiến Binh', 'Warriors Of The Rainbow: Seediq Bale (Part 1)', 'https://phimimg.com/upload/vod/20240227-1/f8acd37437a0ed40236dc79d1cb84d55.jpg', 'https://phimimg.com/upload/vod/20240227-1/0f76ad7b466e6b4e5494ff58f9ff367a.jpg', '<p>Bộ phim dài 4 giờ 30 phút này được xây dựng dựa trên câu chuyện có thật về bộ tộc Seediq - những người đã thực hiện một cuộc nổi dậy đẫm máu năm 1930 chống lại quân đội Nhật Bản để bảo vệ cuộc sống của mình. Những diễn viên không chuyên đảm nhiệm những vai chính và sử dụng chính ngôn ngữ của bộ tộc Seediq cũng đem lại dấu ấn riêng cho phim.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Masanobu Andô","avatar":""},{"name":"Jun''ichi Haruta","avatar":""},{"name":"Sabu Kawahara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
