INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-khi-duoc-song', 'Hạnh Phúc Khi Được Sống', 'Excuse Me For Living', 'https://phimimg.com/upload/vod/20240207-1/d2a671fd2ed63c193b1c45db5f170645.jpg', 'https://phimimg.com/upload/vod/20240207-1/cb4abad436b4947845adcec5a3a208c6.jpg', '<p>Excuse Me for Living là một bộ phim hài lãng mạn của Mỹ năm 2012 được viết, sản xuất và đạo diễn bởi Ric Klass và có sự tham gia của Tom Pelphrey, Christopher Lloyd... Bộ phim xoay quanh câu chuyện về cuộc đời của một thanh niên phóng đãng quyến rũ không kém phần hư hỏng. Anh phải tuân theo yêu cầu của phòng khám phục hồi mà mình đang điều trị rằng anh có hai lựa chọn: anh phải dẫn dắt một nhóm những người đàn ông lớn tuổi tìm lại tình yêu cuộc sống hoặc phải đối mặt với việc giam giữ và mất đi tình yêu của người mình yêu. Từ đó, những tình huống dở khóc dở cười bắt đầu xảy ra với chàng trai. Liệu anh có thể chinh phục được tình yêu đồng thời chữa khỏi căn bệnh tâm lý của mình?</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Pelphrey","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Robert Vaughn","avatar":""},{"name":"Jacob","avatar":""},{"name":"Lars","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324465);
