INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-nhan', 'Phạm Nhân', 'Offender', 'https://phimimg.com/upload/vod/20240205-1/1507f2f6c97bb96ba11968ceff5d66d7.jpg', 'https://phimimg.com/upload/vod/20240205-1/fbc5e9e1ceef1c3a8fcbbcba4e25ab46.jpg', '<p>Bộ phim Phạm Nhân - Offender xoay quanh nhân vật Tommy Nix (Joe Cole) - một thanh niên chăm chỉ, cầu tiến thuộc tầng lớp lao động. Anh chàng luôn cố gắng tránh xa các rắc rối cho đến khi bạn gái anh trở thành nạn nhân của một vụ tấn công tàn bạo. Từ đó, Tommy Nix buộc phải thay đổi bản thân để bảo vệ mình và người yêu.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"English Frank","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Kimberley Nixon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324465);
