INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-lan-gap-mat', 'Hai Lần Gặp Mặt', 'Double Xposure', 'https://phimimg.com/upload/vod/20240220-1/bbd47849d121d2a3fde60b3d12638f9d.jpg', 'https://phimimg.com/upload/vod/20240220-1/b721026759ced7abc19600c0c38dc7fe.jpg', '<p>Tống Kì (Phạm Băng Băng) là chuyên gia tư vấn hình ảnh của một công ty mỹ phẩm, trong một lần tình cờ, cô phát hiện ra bạn trai mình, bác sĩ Lưu Đông (Phùng Thiệu Phong) và Tiểu Tây (Hoắc Tư Yến) đang lén lút quan hệ sau lưng cô. Sau đó cô bị dính vào một vụ án mạng khó có thể giải thích, nhưng trong quá trình điều tra vụ án mạng đó, một bí mật càng to lớn hơn nữa đã xuất hiện. Trong bí mật này, tình yêu của cô ấy, khát vọng của cô ấy, tình cảm gia đình của cô ấy cùng những cơn đau không thể lí giải của cô, tất cả sẽ dần dần được bật mí trong suốt cuộc hành trình kì bí của cô. Cái cô ấy phải đối mặt và tìm kiếm cái mà toàn bộ cuộc sống của cô đã đánh đổi.....</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Joan Chen","avatar":""},{"name":"Bingbing Fan","avatar":""},{"name":"Shaofeng Feng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324465);
