INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-tiger', 'Điệp Viên Tiger', 'Ek Tha Tiger', 'https://phimimg.com/upload/vod/20240219-1/6e0a50e49456fbe139b083999f9fe7f4.jpg', 'https://phimimg.com/upload/vod/20240219-1/8e57be321bd7fc00e4729025ef2681a0.jpg', '<p>Một nhà khoa học trường Cao đẳng Trinity bị nghi ngờ bán bí mật công nghệ tên lửa cho Pakistan. Chính phủ Ấn Độ gửi một điệp viên có tên là Tiger, để tìm hiểu về hoạt động của giáo sư. Nhưng thật trớ trêu,Tiger đã yêu Zoya – người phụ giúp của giáo sư ngay từ cái nhìn đầu tiên và họ đã bị cuốn vào một hành trình đuổi bắt dài, từ Dublin đến Istanbul sau đó Kazakhstan và Chile...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Ranvir Shorey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
