INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-hoan-hao-2012', 'Kế Hoạch Hoàn Hảo', 'A Perfect Plan', 'https://phimimg.com/upload/vod/20240128-1/33ffa9ec557f33e0d64df90647241179.jpg', 'https://phimimg.com/upload/vod/20240128-1/ce92fb8c2b517f51d90bf59783470988.jpg', '<p>Để tránh đi theo “vết xe đổ” bao năm nay của gia đình mình Isabelle đã có một chiến lược tìm một chàng trai bất kì làm mồi nhử, quyến rũ anh ta, làm đám cưới đầu tiên và ly hôn ngay sau đó. Quả là một kế hoạch hoàn hảo nếu mồi nhử của cô nàng không phải Jean-Yves Berthier - người mà cô nàng sẽ kề vai sát cánh từ đỉnh Kilimandjaro tới tận thủ đô Moscow. Đây sẽ là một chuyến du lịch tiền đám cưới đầy ắp những kỉ niệm đẹp.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Diane Kruger","avatar":""},{"name":"Dany Boon","avatar":""},{"name":"Alice Pol","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324465);
