INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-cua-quy', 'Trái Tim Của Quỷ', 'The Devil Inside', 'https://phimimg.com/upload/vod/20240128-1/6c33e622100a84e6460a6d9627f4956d.jpg', 'https://phimimg.com/upload/vod/20240128-1/4109879c3216ed6bd7b004bc58b3ea19.jpg', '<p>Ở Italia, một người phụ nữ dính líu vào hàng loạt lễ trừ tà trái phép nhằm mục đích tìm hiểu nguyên nhân và những gì đã xảy ra với mẹ của mình - bà này đã bị cáo buộc giết chết ba người trong lễ trừ tà của chính bà...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fernanda Andrade","avatar":""},{"name":"Simon Quarterman","avatar":""},{"name":"Evan Helmuth","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324465);
