INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tron-gay-nat', 'Vòng Tròn Gãy Nát', 'The Broken Circle Breakdown', 'https://phimimg.com/upload/vod/20240128-1/a8bb85e059eeb9bf8a67f91bbc1cad5f.jpg', 'https://phimimg.com/upload/vod/20240128-1/b8b09e2f855a6aef8275645b0ca3cebc.jpg', '<p>Tác phẩm của điện ảnh Bỉ, được đề cử “Phim nói tiếng nước ngoài hay nhất” tại Oscar 2014, là một câu chuyện gia đình có lối kể độc đáo và mang đậm màu sắc tâm linh.Hai nhân vật chính gặp nhau thật tình cờ. Anh là nhạc sĩ chơi bluegrass, còn cô là nghệ sĩ xăm hình. Anh nói nhiều về cuộc sống đam mê, còn cô thích lắng nghe hơn. Anh lãng mạn, theo thuyết vô thần, còn cô sống thực tế với một đức tin của riêng mình. Cuộc tình của họ xoay quanh những bản nhạc đồng quê và những buổi diễn cùng dàn nhạc ăn ý mà cá tính với giọng ca trong vắt của cô trên nền banjo anh gảy. Cô bé Maybelle dễ thương là thành quả của mối tình đầy khác biệt nhưng đẹp đẽ này. Nhưng quá ác nghiệt cho Didier và Elise, Maybelle mắc căn bệnh ung thư khi ...</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Veerle Baetens","avatar":""},{"name":"Johan Heldenbergh","avatar":""},{"name":"Nell Cattrysse","avatar":""},{"name":"Geert Van Rampelberg","avatar":""},{"name":"Nils De Caster","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324465);
