INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-cua-quy', 'Cậu Bé Của Quỷ', 'Asura', 'https://phimimg.com/upload/vod/20240128-1/8b86154f7b12bf9a6abae3731a12b84d.jpg', 'https://phimimg.com/upload/vod/20240128-1/f94632055babf269c9c1a37c454baf45.jpg', '<p>Còn lại một mình trên đời, cậu bé mồ côi Asura phải học cách đấu tranh với quỷ dữ bên trong mình để tồn tại. Bộ phim ẩn chứa bài học về nghị lực sống của con người khi phải đối mặt với khó khăn...</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Tesshô Genda","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Hiroaki Hirata","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324465);
