INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-cua-quy', 'Nụ Hôn Của Quỷ', 'Kiss Of The Damned', 'https://phimimg.com/upload/vod/20240128-1/d9ced2294c8c9ac8fa182b4f73b72307.jpg', 'https://phimimg.com/upload/vod/20240128-1/ac2f1f1e69e1046d8ac70452e083a427.jpg', '<p>Ma cà rồng xinh đẹp Djuna cố gắng chống lại sự tiến bộ của nhà biên kịch đẹp trai, con người Paolo, nhưng cuối cùng cũng chịu khuất phục trước niềm đam mê của họ. Khi người chị Mimi quyến rũ và hay thay đổi của cô bất ngờ đến thăm, cô đe dọa mối quan hệ mới của Djuna, và toàn bộ cộng đồng ma cà rồng trở nên nguy cấp.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joséphine de la Baume","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Roxane Mesquida","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Riley Keough","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324465);
