INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-tra-thu', 'Cảnh Sát Trả Thù', 'Freelancers', 'https://phimimg.com/upload/vod/20240126-1/00d3400da7304c8a08a7bd9684b9dcb1.jpg', 'https://phimimg.com/upload/vod/20240126-1/a7aac137c7637e2f4da9567bba51d8e8.jpg', '<p>Con trai của một sĩ quan NYPD bị giết gia nhập lực lượng, tại đây anh đụng độ với cộng sự cũ của cha mình và một nhóm cảnh sát bất hảo. Sếp mới của anh ta, Sarcone, sẽ xem liệu anh ta có những gì cần thiết để trở nên bất hảo thông qua nhiều thử thách và khó khăn về lòng trung thành, sự tin tưởng và tôn trọng hay không. Khi sự thật về cái chết của cha anh được tiết lộ, sự trả thù đã chiếm lấy anh và anh sẽ không dừng lại cho đến khi công lý thực sự được thực thi.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"50 Cent","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Ryan O''Nan","avatar":""},{"name":"Matt Gerald","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324465);
