INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dan-phong-tinh-nhue', 'Đội Dân Phòng Tinh Nhuệ', 'The Watch', 'https://phimimg.com/upload/vod/20240126-1/6c7ae7dc9d85b6cdde837ec4b29523b0.jpg', 'https://phimimg.com/upload/vod/20240126-1/f069d1044a5f91ed1b199a26799b1a71.jpg', '<p>Bốn anh chàng ngoại ô hàng ngày đến với nhau như một cái cớ để thoát khỏi cuộc sống buồn tẻ của họ vào một đêm một tuần. Nhưng khi họ vô tình phát hiện ra rằng thị trấn của họ đã tràn ngập những người ngoài hành tinh đóng giả những người dân ngoại ô bình thường, họ không còn lựa chọn nào khác ngoài việc cứu khu phố của mình - và thế giới - khỏi sự hủy diệt hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Rosemarie DeWitt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
