INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-trong-rung-sau', 'Lạc Trong Rừng Sâu', 'The Outback', 'https://phimimg.com/upload/vod/20240126-1/f053b6f8fd9f3c4c28333685fbf3d961.jpg', 'https://phimimg.com/upload/vod/20240126-1/e3d794c3947986224bdda2c45e87020d.jpg', '<p>Bị trêu chọc vì màu da của mình, chú gấu túi trắng Johnny tham gia một lễ hội hóa trang du lịch với Hamish, quỷ Tasmania và Higgens, một chú khỉ nhiếp ảnh gia với tư cách là đặc vụ tài năng. Trên đường đi qua sa mạc hẻo lánh của Úc, chiếc xe kéo mà họ đang đi bị lỏng và gặp sự cố. Johnny phải sống xứng đáng với địa vị anh hùng mà Hamish thể hiện khi những người dân địa phương vùng hẻo lánh cố gắng giải cứu một chú gấu túi bị bắt cóc khỏi Bog, một con cá sấu khổng lồ và lũ tay sai dingo của hắn.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jenni Pulos","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Nolan North","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
