INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-sassy-hubby', 'My Sassy Hubby', 'My Sassy Hubby', 'null', 'https://phimimg.com/upload/vod/20240123-1/866d9df4f0fa71380fc83906257ae6b1.jpg', '<p>YOYO và Zhang Shisan đã đính hôn với nhau trước khi chào đời. Mười năm trước, nữ sinh trung học YOYO được cha mẹ yêu cầu kết hôn với Zhang Shisan ở Vương quốc Anh. Họ đồng ý giả vờ kết hôn. Sau đó, họ yêu nhau và sống với nhau trong mười năm Vì chênh lệch tuổi tác, Shisan ngày càng háo hức với cuộc sống ổn định. Xung đột của họ đã được nâng cấp. YOYO luôn đe dọa sẽ ly hôn mỗi khi họ cãi nhau. Sau một lần cãi vã, họ bắt đầu sống ly thân. Shisan gặp nữ sinh Dong Yi và YOYO gặp lại người yêu thuở nhỏ của mình, chàng trai nhà giàu Lin Shuhao, liệu tình yêu của họ cuối cùng có tiếp tục?</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Charlene Choi","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Zhang Xin Yi","avatar":""},{"name":"Jeremy Jones","avatar":""},{"name":"Vương Tổ Lam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
