INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-cuop-goi-cam', 'Những Kẻ Cướp Gợi Cảm', 'Spring Breakers', 'https://phimimg.com/upload/vod/20240123-1/911674ac346dab0fc146f1e3a7a1120e.jpg', 'https://phimimg.com/upload/vod/20240123-1/344f4b50b61894876f4ad7570861f3b5.jpg', '<p>Phim Những Kẻ Cướp Gợi Cảm nói về bốn cô bạn thân Faith, Candy, Brit và Cotty, họ là những sinh viên đại học nhưng lại có những ý tưởng táo bạo, họ muốn có những cuộc phiêu lưu thỏa thích nhưng lại không đủ tiền nên họ đã lên kế hoạch đi cướp. Hình ảnh một băng cướp chơi bời ở các vũ trường với những bộ bikini ngay lập tức bị chú ý và họ bị bắt. Phim Những Kẻ Cướp Gợi Cảm bắt đầu những chuyến làm ăn lớn hơn khi họ được một người đàn ông giải cứu, hắn là một tên du côn nổi tiếng và hắn bắt đầu lợi dụng 4 cô gái trẻ này cho những chuyện mà hắn muốn làm. Phim online này có thể coi là một bộ phim lột xác của công chúc Disney Selena Gomez khi trước đó cô chuyên đóng những vai hiền lành và ngoan ngoãn. Mời các bạn chú ý đón theo dõi!</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vanessa Hudgens","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Ashley Benson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
