INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-than-2012', 'Thế Thân', 'Tumbleweed', 'https://phimimg.com/upload/vod/20240126-1/0d7756e137ab74dcd2d9378aa08a531c.jpg', 'https://phimimg.com/upload/vod/20240126-1/dbecea0bca1a880dfbfbc72dd189f628.jpg', '<p>Phim đề cập tới một người đàn ông sống một cuộc sống khó khăn. Ông vào tù vì những tội ác của người khác chỉ vì muốn kiếm tiền. Sau đó ông nhìn thấy một phụ nữ xinh đẹp và rơi vào tình yêu với cô ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Sung Hwa","avatar":""},{"name":"Son Eun Seo","avatar":""},{"name":"Lim Chang Jung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
