INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nhuc-qua-gioi-han', 'Ô Nhục: Quá Giới Hạn', 'Outrage Beyond', 'https://phimimg.com/upload/vod/20240124-1/9bb1352298d3d83d51092463f8eb3a2b.jpg', 'https://phimimg.com/upload/vod/20240124-1/a8cfb88efc12503e902848df85b90f50.jpg', '<p>Như cảnh sát khởi động một cuộc đàn áp toàn diện về tội phạm có tổ chức, nó đốt cháy một cuộc đấu tranh yakuza quốc gia giữa Sanno của phương Đông và Hanabishi của phương Tây. Những gì bắt đầu như là một xung đột nội bộ trong Outrage đã trở thành một cuộc chiến tranh trên toàn quốc trong Outrage Beyond.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryo Kase","avatar":""},{"name":"Takeshi Kitano","avatar":""},{"name":"Toshiyuki Nishida","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
