INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-giang-sinh', 'Đêm Giáng Sinh', 'All About Christmas Eve', 'https://phimimg.com/upload/vod/20240123-1/1e30b9b33f559b834685f7f2799731e4.jpg', 'https://phimimg.com/upload/vod/20240123-1/4b571560528577227f0021deb7c47a54.jpg', '<p>Đêm Giáng Sinh - All About Christmas Eve xoay quanh cô nàng Eve, một người lên kế hoạch cho bữa tiệc. Một ngày, cô phải quyết định tham gia sự kiện của một trong những khách hàng hàng đầu của cơ quan cô hay đến kỳ nghỉ lãng mạn với bạn trai Darren. Lựa chọn cuối cùng của Eve sẽ ảnh hưởng tới toàn bộ tương lai cô sau này.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Haylie Duff","avatar":""},{"name":"Chris Carmack","avatar":""},{"name":"Connie Sellecca","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
