INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-ma-dai-chien', 'Kim Ma Đại Chiến', 'Kamen Rider X Super Sentai Super Hero Taisen', 'https://phimimg.com/upload/vod/20240121-1/98ffaf76a16c366bb309e1d3544da536.jpg', 'https://phimimg.com/upload/vod/20240121-1/8bcc3edfee94a25c2de05a86af429a3f.jpg', '<p>Suốt 40 năm qua, Kamen Rider và Super sentai đã cùng nhau bảo vệ Trái Đất khỏi sự xâm lược của những tên ma. Nhưng giờ đây, Captain Marverlous/Gokai Red của Sentai giờ đã làm lãnh đạo của DaiZangyack lại quyết định tiêu diệt Rider và Kadoya Tsukasa/Kamen Rider Decade của Rider đã trở lại làm lãnh đạo của DaiShocker lại quyết định tiêu diệt Sentai. Cuộc chiến giữa Rider và Sentai đã diễn ra.Tại sao Rider và Sentai lại không đội trời chung? Kế hoạch Big Machine là gì?...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masahiro Inoue","avatar":""},{"name":"Kimito Totani","avatar":""},{"name":"Tatsuhito Okuda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
