INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-gian-la-tinh-yeu', 'Đơn Giản Là Tình Yêu', 'Amour', 'https://phimimg.com/upload/vod/20240121-1/ba3bc678ed2bf0e988a60d9731672f9b.jpg', 'https://phimimg.com/upload/vod/20240121-1/de444d6e7921715da84a1be4137309ba.jpg', '<p>Phim là câu chuyện về một cặp vợ chồng lớn tuổi, Georges và Anne, từng là giáo viên dạy nhạc. Cả hai sống hạnh phúc trong một ngôi nhà ấm cúng ở Paris, Pháp. Họ có một cô con gái cũng theo nghề cha mẹ nhưng sống ở nước ngoài. Đến một ngày, cơn đột quỵ khiến Anne bị liệt nửa người bên phải. Mọi hoạt động sinh hoạt thường ngày của bà giờ bị chi phối bởi Georges. Đã chung sống với nhau hàng chục năm, tình yêu của họ một lần nữa bị thử thách bởi trách nhiệm, bệnh tật, sự hy sinh và thời gian…</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Louis Trintignant","avatar":""},{"name":"Emmanuelle Riva","avatar":""},{"name":"Isabelle Huppert","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
