INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('don-gian-la-tinh-yeu', 'Đơn Giản Là Tình Yêu', 'Amour', 'đơn giản là tình yêu amour jean-louis trintignant emmanuelle riva isabelle huppert ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-goi-cam-2012', 'Đối Tác Gợi Cảm', 'My Ps Partner', 'https://phimimg.com/upload/vod/20240121-1/e54afc6af86c41e53bfdd3a72306addc.jpg', 'https://phimimg.com/upload/vod/20240121-1/a775d61aae6acbe8841438e7d7f414c2.jpg', '<p>My P.s Partner là một bộ phim hài lãng mạn kể về chuyện tình của Hyun Seung (Ji Sung) và Yoon Jung (Kim Ah Joong). Do một cuộc điện thoại gọi nhầm thú vị, cả hai đã đến được với nhau khi đều đang trong quá trình đổ vỡ tình yêu trước đó. Không chỉ lãng mạng, hài hước, My P.s Partner còn mang đến cho khán giả những cảnh nóng “bỏng mắt”.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seong Ji","avatar":""},{"name":"Ah-jung Kim","avatar":""},{"name":"So-Yul Shin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324466);
