INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-tac-goi-cam-2012', 'Đối Tác Gợi Cảm', 'My Ps Partner', 'đối tác gợi cảm my ps partner seong ji ah-jung kim so-yul shin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-tu-do', 'Nghệ Thuật Tự Do', 'Liberal Arts', 'https://phimimg.com/upload/vod/20240121-1/d3c9af0112f57cc3b5a2900b37c872cd.jpg', 'https://phimimg.com/upload/vod/20240121-1/fa3b91df0a47db3e392f956a1b0790f7.jpg', '<p>Mới độc thân, 35 tuổi và không có hứng thú với công việc, Jesse Fisher lo lắng rằng những ngày tươi đẹp nhất của anh đã qua đi. Nhưng dù có vùi đầu vào sách bao nhiêu đi chăng nữa, cuộc sống vẫn cứ kéo Jesse lại. Khi giáo sư đại học yêu thích của anh ấy mời anh ấy đến trường để nói chuyện trong bữa tối nghỉ hưu của mình, Jesse đã chớp lấy cơ hội. Anh ấy đã chuẩn bị cho nỗi nhớ nhà ăn và phòng ký túc xá, các bữa tiệc và hội thảo thơ ca; những gì anh ấy không thấy sắp tới là Zibby - một sinh viên năm hai xinh đẹp, sớm phát triển, yêu thích âm nhạc cổ điển. Zibby đánh thức những cảm giác đáng sợ, thú vị, đã ngủ quên từ lâu về khả năng và mối liên hệ mà Jesse nghĩ rằng anh đã chôn vùi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Elizabeth Reaser","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
