INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-duoc-bao-truoc-2012', 'Cái Chết Được Báo Trước', 'Dead Before Dawn', 'https://phimimg.com/upload/vod/20240111-1/00365969f4b65f63521619503a2f12c2.jpg', 'https://phimimg.com/upload/vod/20240111-1/e09642bceb28e0a3d13fccfd4f96c7c4.jpg', '<p>Một nhóm sinh viên đại học vô tình giải phóng một lời nguyền độc ác khiến mọi người tự sát và biến thành Zombie Demons, hay còn gọi là ZEMONS!</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christopher Lloyd","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Martha MacIsaac","avatar":""},{"name":"April Mullen","avatar":""},{"name":"Brandon Jay McLaren","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
