INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eastern-bandits', 'Eastern Bandits', 'Eastern Bandits', 'https://phimimg.com/upload/vod/20240205-1/0a312a364033db5464850e54dc8f79a1.jpg', 'https://phimimg.com/upload/vod/20240205-1/45c62d3baab6a548d1972864679484ea.jpg', '<p>Phim lấy bối cảnh thời Nhật Bản xâm lược Trung Quốc. Câu chuyện được kể dưới góc nhìn của Gao, một người lính đang tìm cách trả thù người Nhật khi cố gắng ám sát tổng chỉ huy người Nhật đang đến thăm. Trong quá trình vạch ra âm mưu như vậy, anh ta đã có cơ hội chạm trán với một Mafia địa phương, do thủ lĩnh Fang lôi cuốn của nó cầm đầu. Fang có một nhóm theo dõi, trong đó có một người là em gái của Fang. Fang trong quá khứ đã giải cứu nhiều tín đồ này bằng chính máu của mình và kết quả là tất cả các thành viên trong băng cướp đã hình thành một tình bạn và mối quan hệ gắn bó lâu dài. Khi Gao nhận ra rằng anh ta có thể sử dụng súng và sức mạnh con người của tên cướp của Fang, anh ta đã lập một kế hoạch để cố tình bị Fang bắt giữ. Khi Fang phát hiện ra - anh ta vô cùng tức giận và buồn bã và suýt giết Gao, nhưng Gao được chị gái của Fang cứu vì cô ấy rõ ràng nảy sinh tình cảm với Gao sau khi chứng kiến anh ta đã trải qua như thế nào trong các giai đoạn thẩm vấn khi anh ta bị Fang bắt giữ.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiaoming Huang","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Tino Bao","avatar":""},{"name":"倪景阳","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
