INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-long-tuyet-trang', 'Trong Lòng Tuyết Trắng', 'Into The White', 'https://phimimg.com/upload/vod/20240104-1/bc59b31df53c521dead406840b624a75.jpg', 'https://phimimg.com/upload/vod/20240104-1/91903579ba85a15a6bb10b091a10cdc9.jpg', '<p>Into the White là câu chuyện có thật về một nhóm các phi công Anh và Đức trong Thế chiến II. Sau trận bắn khốc liệt giữa hai phía, họ cùng bị rơi xuống một vùng đất hoang dã của Na Uy. Mặc dù ban đầu căng thẳng giữa hai nhóm tưởng chừng không thể giải quyết, nhưng rồi những người đàn ông này buộc phải đoàn kết với nhau để sống sót qua mùa đông dài khắc nghiệt. Chính trong cuộc chiến đặc biệt này, tình bạn giữa những kẻ tưởng là tử thù đã nảy nở...</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Florian Lukas","avatar":""},{"name":"David Kross","avatar":""},{"name":"Lachlan Nieboer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
