INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-hoang-cung', 'Siêu Trộm Hoàng Cung', 'The Grand Heist', 'null', 'https://phimimg.com/upload/vod/20240104-1/e7199a01d84b1a545b1732c86d451f55.jpg', '<p>Vào cuối thế kỷ 18, băng là một mặt hàng có giá trị hơn vàng. Khi các quan chức tham nhũng âm mưu hình thành độc quyền và ấn định giá của nó, một nhóm gồm 11 người chuyên nghiệp được thành lập để đánh cắp tất cả các khối băng hoàng gia trong năm nhà kho trong một đêm.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Tae Hyun","avatar":""},{"name":"Oh Ji Ho","avatar":""},{"name":"Min Hyo Rin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
