INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-nhan-chung', 'Bảo Vệ Nhân Chứng', 'Witness Insecurity', 'https://phimimg.com/upload/vod/20240116-1/3972d39ff27a81be64d6755dde48b6b8.jpg', 'https://phimimg.com/upload/vod/20240116-1/2be8996717c022b4ec82cb613f33bf1e.jpg', '<p>Phim Bảo Vệ Nhân Chứng - Hộ Hoa Nguy Tình xoay quanh mối tình của anh chàng cảnh sát và cô gái chơi đàn cello. Vì cô đã gây ra tai nạn làm cho anh trai mình chết lúc còn bé nên cô đã mắc chứng bệnh trần cảm chỉ cười khi chơi đàn cello, ngoài ra cô không quan tâm thế giới bên ...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2012, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Chu Tuệ Mẫn","avatar":""},{"name":"Chung Gia Hân","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"La Lạc Lâm","avatar":""},{"name":"Lạc Đồng","avatar":""},{"name":"Lý Thành Xương","avatar":""},{"name":"Tần Bái","avatar":""},{"name":"Tăng Vĩ Quyền","avatar":""},{"name":"Tưởng Chí Quang","avatar":""},{"name":"Tưởng Gia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
