INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-ve-nhan-chung', 'Bảo Vệ Nhân Chứng', 'Witness Insecurity', 'bảo vệ nhân chứng witness insecurity chu tuệ mẫn chung gia hân huỳnh tông trạch la lạc lâm lạc đồng lý thành xương tần bái tăng vĩ quyền tưởng chí quang tưởng gia ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien', 'Siêu Điệp Viên', 'Spy', 'https://phimimg.com/upload/vod/20240203-1/023098e67d4569316325b5c05f5075b0.jpg', 'https://phimimg.com/upload/vod/20240203-1/6ecc177e9169be7255e3687c3df6f71b.jpg', '<p>Kim, Kang, Woo, Yoon là bốn tay gián điệp của Bắc Hàn được cài vào Nam Hàn. Tuy nhiên, đó là chuyện 22 năm trước đây, còn hiện giờ mỗi người đều có cuộc sống riêng với những lo toan khác nhau. Kim trở thành một người đàn ông bận rộn tìm kế sinh nhai để nuôi sống gia đình với việc buôn bán thuốc Viagra nhập lậu từ Trung quốc. Kang là bà mẹ đơn thân làm nghề môi giới bất động sản, Woo là chủ trang trại nuôi bò và Yoon chỉ là một công dân lớn tuổi đã về hưu. Nhưng cuộc sống vốn chẳng yên ả gì của họ lại bị đảo lộn hoàn toàn khi một ngày kia, họ đột nhiên nhận được nhiệm vụ mới từ tư lệnh Choi. Và mặc dù họ hoàn toàn chẳng muốn tiếp tục cuộc sống của những ngày tháng trước đây nhưng không còn cách nào khác đành phải miễn cưỡng tham gia. Mọi chuyện sẽ ra sao khi nhiệm vụ quan trọng lại được giao cho những tay gián điệp đang muốn trốn tránh quá khứ của chính mình?</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hie-bong Byeon","avatar":""},{"name":"Gyu-Woon Jung","avatar":""},{"name":"Myung-min Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
