INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-song', 'Mật Mã Sống', 'Safe', 'https://phimimg.com/upload/vod/20240104-1/250e4863d938509c948e8de9bd07ea24.jpg', 'https://phimimg.com/upload/vod/20240104-1/ab5e0027a51c7c29658571c45ea7597c.jpg', '<p>Một cựu đặc vụ ưu tú nhận thực hiện một nhiệm vụ kép: giải cứu một cô bé người Trung Quốc bị Hội Tam Hoàng bắt cóc và tìm một giải pháp an toàn để đánh lừa Mafia Nga, Hội Tam Hoàng và cả những quan chức tham nhũng của New York. Liệu anh có hoàn thành được nhiệm vụ khó khăn này?</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Catherine Chan","avatar":""},{"name":"Chris Sarandon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
