INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-thoat', 'Đào Thoát', 'Escape', 'https://phimimg.com/upload/vod/20240103-1/aa6d666e3bcc293844d6faf0a7e4f7f9.jpg', 'https://phimimg.com/upload/vod/20240103-1/0fc4892a9eaba29d28eea5611ef62412.jpg', '<p>Mười năm sau khi cái chết đen tàn phá đất nước, một gia đình nghèo bắt đầu hành trình tìm kiếm điều kiện sống tốt hơn. Trong một con đường núi hoang vắng, họ bị tấn công bởi một nhóm kẻ trộm giết người tàn nhẫn. Người duy nhất tha thứ là Signe 19 tuổi. Cô bị bắt làm tù binh, và băng đảng đưa cô trở lại trại của họ. Tại đây, cô sớm biết rằng họ có số phận tồi tệ hơn cái chết trong cửa hàng đối với cô, và nhận ra rằng hy vọng duy nhất của cô là trốn thoát.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Isabel Christine Andreasen","avatar":""},{"name":"Ingrid Bolsø Berdal","avatar":""},{"name":"Milla Olin","avatar":""},{"name":"Tobias Santelmann","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324466);
