INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dien', 'Kẻ Điên', 'Maniac', 'https://phimimg.com/upload/vod/20240108-1/7bc4d2b2a9fa660809096dd677c37c2b.jpg', 'https://phimimg.com/upload/vod/20240108-1/34ff00f0229252d65a14eebd9170b7c9.jpg', '<p>Bộ phim kể về câu truyện một chàng trai chủ cửa hàng đồ chơi người lớn mắc một chứng bệnh hoang tưởng sau khi tận mắt chứng kiến cảnh mẹ mình bị cưỡng hiếp cho đến chết. Từ đó, những khách hàng đến cửa hàng đều bị anh cho là kẻ gây nên vụ án khi xưa, anh lên kế hoạch bắt cóc và hành hạ đề thỏa mãn chứng hoang tưởng của mình...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"America Olivo","avatar":""},{"name":"Nora Arnezeder","avatar":""},{"name":"Zoe Aggeliki","avatar":""},{"name":"Jan Broberg","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
