INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-khach-rurouni-kenshin', 'Lãng Khách Rurouni Kenshin', 'Rurouni Kenshin', 'https://phimimg.com/upload/vod/20231231-1/9513cbaf44cbb7f1ad51d96405311fb1.jpg', 'https://phimimg.com/upload/vod/20231231-1/d1e4151856251b4b1fa1f6867c625a0a.jpg', '<p>Bộ phim được chuyển thể từ bộ manga nổi tiếng Rurouni Kenshin của tác giả Watsuki Nobuhiro, được đăng trên Weekly Shonen Jump từ 02/09/1994 đến 04/11/1999. Cựu sát thủ huyền thoại Kenshin Himura (Takeru Sato) nay đã trở thành một samurai lang thang. Anh ta giúp đỡ và bảo vệ cho những người cần đến mình như một hành động chuộc lại những lỗi lầm trong quá khứ. Rồi anh gặp và cứu giúp Kaoru Kamiya (Emi Takei). Cha của Kaoru mở một ngôi trường dạy kendo tại Tokyo, Kamiya Kasshin. Kaoru mời Kenshin đến ở lại võ đường của mình. Tại đây, tình cảm của 2 người dần tiến triển, tuy nhiên Kenshin vẫn luôn bị ám ảnh bởi quá khứ của mình...</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Yû Aoi","avatar":""},{"name":"Takeru Satô","avatar":""},{"name":"Teruyuki Kagawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
