INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-bau-troi', 'Biệt Đội Bầu Trời', 'Sky Force 3D', 'https://phimimg.com/upload/vod/20240128-1/49f34b5f9e90d3639d30b5c0daf97bc6.jpg', 'https://phimimg.com/upload/vod/20240128-1/26e600c586586b3c5215cb3dedf2bb56.jpg', '<p>Chiếc máy bay nhỏ Tinny mơ ước trở thành anh hùng, nhưng trong một đội thân thiện gồm những chiếc máy bay kỳ cựu, anh không được công nhận. Một ngày nọ, bất chấp lệnh cấm của đội trưởng Ben, anh ấy lên đường cứu mọi người khỏi đám cháy, nhưng tính mạng của anh ấy gặp nguy hiểm, và đội trưởng đã cứu anh ấy bằng chính mạng sống của mình. Vì đau khổ, tội lỗi và sợ hãi, Tinny rời đội và bắt đầu làm việc tại công ty của tôi. Nhưng đột nhiên ngọn lửa dữ dội khiến anh nhớ lại quá khứ và anh lao đến giúp đỡ bạn bè mà không sợ hãi.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John S. Flynn","avatar":""},{"name":"Randy Charach","avatar":""},{"name":"Heather Gordon","avatar":""},{"name":"Aaron Krebs","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
