INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-bi-an', 'Vụ Án Bí Ẩn', 'Howling', 'https://phimimg.com/upload/vod/20240102-1/340f71373d0bbf3c51bb3bc2203bec71.jpg', 'https://phimimg.com/upload/vod/20240102-1/d149b7290018207be39f3a816b86e4c6.jpg', '<p>Phim dựa trên cuốn tiểu thuyết The Hunter của tác giả người Nhật Bản Asa Nonami. Howling có sự tham gia của tài tử Song Kang-ho và người đẹp Lee Na-young.Các vụ tự thiêu bí ẩn liên tiếp xảy trong thành phố. Thám tử Sang-gil cùng nữ thanh tra Eun-Young được giao nhiệm vụ điều tra. Sang-gil tập trung vào các dấu vết của vụ cháy trong khi Eun-Young lại chú ý tới những vết răng lưu lại trên cơ thể nạn nhân. Qua điều tra, hai người xác định những vụ án mạng từ trước đến giờ đều liên quan đến một con chó săn. Thêm vào đó, các nạn nhân đều có chung một mối liên hệ bí ẩn. Manh mối đã có nhưng việc điều tra không hề dễ dàng.</p>', 'Full', 1, 'single', 'completed', 5, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Na‑young","avatar":""},{"name":"Song Kang Ho","avatar":""},{"name":"Lee Tae‑ri","avatar":""},{"name":"Nam Bo Ra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324466);
