INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-cuoi-pho', 'Ác Mộng Cuối Phố', 'House At The End Of The Street', 'https://phimimg.com/upload/vod/20240102-1/ef9bfe3d55314513096eff303ed36bd0.jpg', 'https://phimimg.com/upload/vod/20240102-1/ddacac51186bf71e9e0fa1b758e2984c.jpg', '<p>Hai mẹ con chuyển đến một thị trấn mới và thấy mình sống cạnh ngôi nhà nơi một cô gái trẻ đã sát hại cha mẹ mình. Khi cô con gái kết bạn với cậu con trai còn sống, cô biết được câu chuyện còn lâu mới kết thúc.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Thieriot","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"Nolan Gerard Funk","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
