INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-thue-mot-nguoi-tinh', 'Tôi Thuê Một Người Tình', 'Love Me Or Leave Me', 'https://phimimg.com/upload/vod/20240109-1/5eb94d49a11ac6d69a2d26406aaec3d7.jpg', 'https://phimimg.com/upload/vod/20240109-1/5ea98319bc5b0d5022813579a64c313e.jpg', '<p>Tám năm yêu nhau, mặc cho những lời cầu hôn chân thành từ Hạo Minh nhưng Kỷ Tình vẫn né tránh và hoài nghi về tình yêu của anh. Bởi vì cha của cô lúc còn trẻ đã có vợ lẽ bên ngoài, khiến mẹ của cô tức giận chạy ra ngoài và xảy ra tai nại mà qua đời. Lại thêm sau khi trưởng thành, các bạn bè xung quanh sau khi kết hôn cũng bị chồng bội bạc, càng khiến cô theo chủ nghĩa không hôn nhân. Vì vô cùng yêu thương Kỷ Tình nên Hạo Minh đề nghị cả hai trải qua cuộc sống “hôn nhân thử”. Qua một tháng, Kỷ Tình dần bị Hạo Minh cảm hóa. Trước khi chấp nhận đeo nhẫn cưới, nghe theo kiến nghị của các chị em, Kỷ Tình quyết định thử mức độ chân thành của Hạo Minh bằng cách thuê một phụ nữ theo đuổi anh, nhưng không ngờ rằng người phụ nữ Triệu San San đó tiếp cận Hạo Minh là có mục đích khác. San San rất sùng bái những gì mà Kỷ Tình đang có, nên muốn cướp đi cuộc sống hoàn mỹ của cô...</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 13, 2012, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Hựu Thắng","avatar":""},{"name":"Hứa Vĩ Ninh","avatar":""},{"name":"Tiểu Huân","avatar":""},{"name":"Lý Khang Nghi","avatar":""},{"name":"Kha Hữu Luân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
