INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nang-lola', 'Chuyện Nàng Lola', 'Lola Versus', 'https://phimimg.com/upload/vod/20231231-1/fd1cbd84cc3926c2cea2614759d96184.jpg', 'https://phimimg.com/upload/vod/20231231-1/a7a7c21af28feae77ea22d42b9d5c791.jpg', '<p>Bị bạn trai bỏ rơi ngay trước ngày cưới 3 tuần, Lola (Greta Gerwig) liệt kê một loạt danh sách bạn bè thân thiết của cô để bắt đầu một cuộc hành trình mà cô hy vọng là nó sẽ giúp cô trở thành người phụ nữ chưa chồng đến năm 30 tuổi.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Greta Gerwig","avatar":""},{"name":"Zoe Lister Jones","avatar":""},{"name":"Hamish Linklater","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
