INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tham-99-ngay', 'Yêu Thầm 99 Ngày', 'Love In Time', 'https://phimimg.com/upload/vod/20231231-1/6b728002065d3de6ddde2d879134ab6d.jpg', 'https://phimimg.com/upload/vod/20231231-1/41e1d9b5bc3b6c6f9ad2f52d9db9fee4.jpg', '<p>Cuộc sống của hai người bạn cùng phòng ở Hồng Kông với một chiếc xe bán kem thay đổi khi một người anh em họ hấp dẫn từ Đài Loan chuyển đến. Cho là một kẻ lười biếng, dành cả ngày để bán kem với người bạn thân nhất / bạn cùng phòng Beer. Mặc dù công việc kinh doanh xe bán kem của anh ấy đang thất bại, anh ấy vẫn có một mái nhà trên đầu vì căn hộ của anh ấy thuộc về người chú của anh ấy. Khi em họ Tina quyết định trở về Hồng Kông, Cho và Beer buộc phải ở chung nhà với cô ấy, tạo ra mối quan hệ đối nghịch giữa ba người. Tuy nhiên, Cho và Tina bắt đầu gắn bó theo thời gian, mặc dù họ không thừa nhận có tình cảm với nhau. Khi ông chủ Machi lôi cuốn của Tina xuất hiện, Cho nhận ra rằng mình có thể đã quá muộn.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bosco Wong","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Sammy Leung","avatar":""},{"name":"Sita Chan","avatar":""},{"name":"Danny So","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
