INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-dao-song-hung', 'Bảo Đảo Song Hùng', 'Double Trouble', 'https://phimimg.com/upload/vod/20240126-1/8d5a64f4ec4b76415632d8ad5348a9bb.jpg', 'https://phimimg.com/upload/vod/20240126-1/a26590c53c6505d4e56e4f55ee03607b.jpg', '<p>Hai nhân viên bảo vệ — một đến từ Bắc Kinh, một đến từ Đài Bắc — buộc phải làm việc cùng nhau để truy tìm một bức tranh huyền thoại của Trung Quốc đã bị đánh cắp bởi những tên trộm nghệ thuật quốc tế</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jaycee Chan","avatar":""},{"name":"Xia Yu","avatar":""},{"name":"Deng Jiajia","avatar":""},{"name":"Chen Handian","avatar":""},{"name":"Chang Fei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
