INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-sat', 'Bầu Trời Sắt', 'Iron Sky', 'https://phimimg.com/upload/vod/20231231-1/6793bf0989ddfc700b5d07b2c1d82eb6.jpg', 'https://phimimg.com/upload/vod/20231231-1/11e51b0c0f2114924d55bb07a9d6bacf.jpg', '<p>Trong khoảnh khắc cuối cùng của chiến tranh thế giới thứ II, chương trình không gian bí mật của Đức Quốc xã đã trốn tránh việc bị phá hủy bằng cách chạy trốn tới phía tối của Mặt Trăng.Trong suốt 70 năm ẩn dấu bí mật, Đức quốc xã đã cho xây dựng một pháo đài không gian khổng lồ với một hạm đội các phi thuyền tối tân. Năm 2018,với sức mạnh của công nghệ và lực lượng đông đảo.Chúng trở lại Trái Đất để lấy lại những gì thuộc về chúng.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Julia Dietze","avatar":""},{"name":"Christopher Kirby","avatar":""},{"name":"Götz Otto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324466);
