INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-choi-kieu-uc', 'Dân Chơi Kiểu Úc', 'A Few Best Men', 'https://phimimg.com/upload/vod/20231231-1/0eed8192f452b23ef65febf013ddf73b.jpg', 'https://phimimg.com/upload/vod/20231231-1/188c26fd54e90dcb5f5f4cbfc0014548.jpg', '<p>“A Few Best Men” là câu chuyện vui nhộn về các chàng trai trẻ trước ngưỡng cửa hôn nhân. Họ đã cùng nhau quậy một trận tơi bời trước khi cưới vợ, và thậm chí mang luôn những trò phá bĩnh “tưng tửng” của mình vào thẳng ngày đám cưới...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Thuyết Minh', 'HD', 'Anh', 0, '[{"name":"Laura Brent","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Kris Marshall","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324466);
