INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dan-choi-kieu-uc', 'Dân Chơi Kiểu Úc', 'A Few Best Men', 'dân chơi kiểu úc a few best men laura brent xavier samuel kris marshall ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('two-rabbits', 'Two Rabbits', 'Two Rabbits', 'https://phimimg.com/upload/vod/20231231-1/ac4ccb068597f7fbaea3365e7d5a70ac.jpg', 'https://phimimg.com/upload/vod/20231231-1/77c9797aecbd044f691f93fdefc5d6e2.jpg', '<p>Edgar là một thanh niên thuộc tầng lớp trung lưu, gần 30 tuổi. Anh ấy sống trong một cuộc sống đầy khủng hoảng và ở một vị trí phổ biến đối với đại đa số người Brazil. Một mặt, quyền lực, được đại diện bởi một nhà nước tham nhũng, lạm dụng và vắng mặt trong các khoản thuế trước nghĩa vụ của họ. Mặt khác, bạo lực có tổ chức ngày càng gia tăng đã trở thành một điều thường xuyên trong cuộc sống của người dân ở các thành phố lớn. Edgar phản ứng với tất cả những điều này với tư cách là một người cảnh giác hiện đại. Với sự trợ giúp của các thành phần như công nghệ, thông tin phản tác dụng và thao túng, Edgar vạch ra một kế hoạch tuyệt vời, sử dụng lòng tham của đối thủ làm lý do cho sự hủy diệt của nó. Khi cốt truyện mở ra, chúng ta biết nhiều hơn về quá khứ đen tối của mỗi nhân vật khi Edgar ghép các mảnh lại với nhau trong một câu đố hấp dẫn tạo nên cốt truyện của bộ phim.</p>', 'Full', 1, 'single', 'completed', 37, 2012, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Fernando Alves Pinto","avatar":""},{"name":"Alessandra Negrini","avatar":""},{"name":"Caco Ciocler","avatar":""},{"name":"Marat Descartes","avatar":""},{"name":"Djair Guilherme","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
