INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-dong-song', 'Câu Chuyện Dòng Sông', 'Câu Chuyện Dòng Sông', 'https://phimimg.com/upload/vod/20231231-1/a0323134e08a39886cc24fff38701671.jpg', 'https://phimimg.com/upload/vod/20231231-1/481b5f3e83a46a5812023840bdc33b38.jpg', '<p>Câu Chuyện Dòng Sông xoay quanh những người Việt bỏ lại gia đình phía sau để sang đất Lào xa xôi cống hiến, về công cuộc xây dựng và vun đắp văn hóa sống, văn hóa kinh doanh của Unitel. Thông qua Unitel Unitel (thương hiệu của Tập đoàn Công nghiệp - Viễn thông Quân đội trên đất nước Lào), những cây cầu nối liền 2 nước không chỉ được xây bằng công nghệ viễn thông mà còn bằng tình đoàn kết, đồng cam cộng khổ để mang lại cho những dòng sông vẫn âm thầm chảy qua 2 đất nước những câu chuyện và những biểu tượng mới về tình người.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324466);
