INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu', 'Mật Vụ', 'Gabbar Singh', 'https://phimimg.com/upload/vod/20231231-1/66f66c51ab77e039522215da2df7c4de.jpg', 'https://phimimg.com/upload/vod/20231231-1/52371ff5587a8c9275042de676520735.jpg', '<p>Một cậu bé chạy trốn khỏi nhà, tức giận với cha dượng và anh trai cùng cha khác mẹ của mình. Nhiều năm sau, anh trở thành thanh tra cảnh sát và chiến đấu với một tên tội phạm khét tiếng.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Pawan Kalyan","avatar":""},{"name":"Shruti Haasan","avatar":""},{"name":"Ali Basha","avatar":""},{"name":"Kota Srinivasa Rao","avatar":""},{"name":"Abhimanyu Singh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
