INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-con-tho', 'Hai Con Thỏ', '2 Coelhos', 'https://phimimg.com/upload/vod/20240123-1/0170a302a01cf64c889eb5b66a8da7c9.jpg', 'https://phimimg.com/upload/vod/20240123-1/c24cdf559ba62d1903d81cf956dd5f1e.jpg', '<p>Edgar là một người đàn ông chững chạc, gần 30 tuổi, anh sống trong một xã hội chỉ có quyền lực, tham nhũng tại Brazil và trừng trị những kẻ trốn thuế của nhà nước. Tội phạm, bạo lực ngày càng gia tăng và có tổ chức, ảnh hưởng tới cuộc sống của người dân nơi đó. Với sự hỗ trợ công nghệ và trí óc của mình, Edgar đã vạch ra một kế hoạch tuyệt vời, dùng chính lòng tham vô đáy của kẻ xấu để tiêu diệt chúng...</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Fernando Alves Pinto","avatar":""},{"name":"Alessandra Negrini","avatar":""},{"name":"Caco Ciocler","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
