INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-haley', 'Đi Tìm Haley', 'Taken Back: Finding Haley', 'https://phimimg.com/upload/vod/20240123-1/29ac61d8b963521c9361ce5b96914f48.jpg', 'https://phimimg.com/upload/vod/20240123-1/939c96c075d991e224a05b70c8c6e36b.jpg', '<p>Đi Tìm Haley - Taken Back: Finding Haley xoay quanh hành trình tìm con của nhiếp ảnh gia Karen. Trong một lần đưa con gái đi chơi lễ hội, Karen vô tình làm lạc mất con. Cô tự nhủ rằng đến một ngày mình cũng sẽ tìm được con. Nhiều năm sau, Karen đinh ninh mình đã tìm được con gái thất lạc nhưng cô phải tìm ra bằng chứng cho thấy hai người là ruột thịt.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Tapping","avatar":""},{"name":"Kacey Rohl","avatar":""},{"name":"Moira Kelly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
