INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-sinh-tu', 'Chiến Dịch Sinh Tử', 'Argo', 'https://phimimg.com/upload/vod/20231230-1/42137d4e5ed5be5ef8c5f734c4235c88.jpg', 'https://phimimg.com/upload/vod/20231230-1/f6a985b139e12e3597822590ba2c60ed.jpg', '<p>Argo dựa trên một sự kiện có thật, Argo ghi chép lại một chiến dịch sinh tử bí mật có nhiệm vụ giải cứu 6 người Mỹ, điều đã vén lên bức màn của cuộc khủng hoảng con tin Iran – sự thật đã được che giấu cả thập kỉ. Vào ngày 4/11/1979, lúc mà cuộc Cách mạng Iran đang lên đến đỉnh điểm, các dân quân đã tấn công vào đại sứ quán Mỹ ở Tehran, bắt 52 người Mĩ làm con tin.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"John Goodman","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
