INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-cu-ky-quai', 'Chung Cư Kỳ Quái', 'Small Apartments', 'https://phimimg.com/upload/vod/20231230-1/1d17a3a1c8093d226e7c020669055e1d.jpg', 'https://phimimg.com/upload/vod/20231230-1/255c414b438717357663a46fb0ca76ca.jpg', '<p>Khi một kẻ bất tài vụng về vô tình giết chết chủ nhà của mình, anh ta phải làm mọi thứ trong khả năng của mình để giấu xác, chỉ để thấy rằng sự phân tâm của ham muốn, cái chết của người anh yêu quý và một nhóm nhân vật lạc lối buộc anh ta phải vào một cuộc hành trình mà một may mắn đang chờ đợi anh ta.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Lucas","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"James Caan","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Billy Crystal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
