INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-o-toa-nha-31', 'Tội Ác Ở Tòa Nhà 31', 'Tower Block', 'https://phimimg.com/upload/vod/20231230-1/df938b75115c1a28f1b743fbcb8033a5.jpg', 'https://phimimg.com/upload/vod/20231230-1/d931ea79bda0fae6fae53a5bc23ee982.jpg', '<p>Một năm sau khi chứng kiến một vụ giết người, cư dân của Tower Block 31 thấy mình bị một tay súng bắn tỉa hạ gục, đẩy những người may mắn còn sống vào cuộc chiến sinh tồn.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sheridan Smith","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"Russell Tovey","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Jill Baker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
