INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-cuc-quyen-2-anh-hung-ba-dao', 'Thái Cực Quyền 2: Anh Hùng Bá Đạo', 'Tai Chi Hero', 'https://phimimg.com/upload/vod/20231225-1/24f8509d9cb1144a55e9410a5ec6ebe4.jpg', 'https://phimimg.com/upload/vod/20231225-1/a8bd1f7abf33c811a2497c9329447aad.jpg', '<p>Bộ phim bom tấn võ thuật steampunk của Trung Quốc kể về những năm đầu của bậc thầy Thái cực quyền Yang Luchan, người đã sáng lập vào thế kỷ 19, thứ mà ngày nay đã trở thành phong cách Thái cực quyền phổ biến nhất trên thế giới. Phần thứ hai của bộ ba Tai Chi tiếp tục cuộc hành trình của Yang Luchan, một đứa trẻ tài năng với cục thịt mọc trên trán, người đã giúp cứu một ngôi làng khỏi đội quân lính steampunk đáng sợ mang những cỗ máy kỳ lạ với kiến thức về Tai Chi mà chúng giao phó cho anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jayden Yuan","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"William Fung Kwun-Man","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
