INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-tham-quan', 'Khách Tham Quan', 'Sightseers', 'https://phimimg.com/upload/vod/20231225-1/4af7c3316d0727e775933bfff5622cfb.jpg', 'https://phimimg.com/upload/vod/20231225-1/405782497f7fc3c61c0e8799c33e5c49.jpg', '<p>Bắt đầu bằng một chuyến đi ngọt ngào để tìm hiểu về cuộc sống của nhau, Chris và Tina tưởng rằng mình sẽ đắm chìm trong hạnh phúc. Nào ngờ họ gặp phải những kẻ phá đám không ngờ đến và cuộc hành trình trở nên rắc rối hơn bao giờ hết!</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Alice Lowe","avatar":""},{"name":"Kenneth Hadley","avatar":""},{"name":"Steve Oram","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
