INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le', 'Nô Lệ', 'Be My Slave', 'https://phimimg.com/upload/vod/20231230-1/d28caee233fb413c5092edd5a5bf5608.jpg', 'https://phimimg.com/upload/vod/20231230-1/3cd44a2b2e1c628a0c28eca85c92d479.jpg', '<p>Dan Mitsu đóng vai Kana, một nữ nhân viên tại một công ty xuất bản có quan hệ tình ái với một đồng nghiệp trẻ hơn. Anh sớm phát hiện ra rằng sự tôn sùng của Kana kéo dài đến xu hướng bạo dâm, liên quan đến một người đàn ông bí ẩn chỉ được biết đến với cái tên Sensei. Khám phá này sẽ đẩy mối quan hệ của anh ấy với Kana lên một mức độ nguy hiểm mới mà anh ấy có thể chưa sẵn sàng.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mitsu Dan","avatar":""},{"name":"Itsuji Itao","avatar":""},{"name":"Hiroaki Mayama","avatar":""},{"name":"Kanji Furutachi","avatar":""},{"name":"Asuka Ishii","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
