INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-nang-xau-tinh', 'Những Cô Nàng Xấu Tính', 'Bad Girls', 'https://phimimg.com/upload/vod/20231230-1/06efc3b389854b3a08bec3dc9f22f652.jpg', 'https://phimimg.com/upload/vod/20231230-1/8961b3c323941f05079e7211db0ce1e8.jpg', '<p>Ella Chen của S.H.E (New Perfect Two) bắt tay với mỹ nam màn ảnh Mike He (Love Keeps Going) trong Bad Girls! Ella vào vai nữ sinh trung học lanh lợi A-Đan, người cùng với những người bạn thân nhất của mình là Pei Pei (nữ thần của otaku Da Yuan) và Xiao Mi (Beatrice Fang), tạo thành bộ ba khét tiếng dễ bị bạo lực được gọi là Bad Các cô gái. Cô ấy tự mình giải quyết công lý, bảo vệ những cô gái khác khỏi những kẻ bắt nạt và quan trọng nhất là trừng phạt những cậu bé không thể chịu đựng được. Mùa hè này, thần tượng trẻ tuổi nổi tiếng Justin (Mike He) đến trường của A-Dan để quay bộ phim lãng mạn mới nhất của anh ấy, và điều đó khiến các cô gái trong thị trấn phát cuồng. Nhưng chính A-Dan lãnh đạm, hoàn toàn do duyên số, vô tình đụng phải phim trường, và được giao vai nữ chính đối diện với Justin kiêu ngạo! Có một vấn đề - cô ấy chưa từng có kinh nghiệm lãng mạn nào trước đó..</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ella Chen","avatar":""},{"name":"Mike He","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Chris Wang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
