INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nu-tinker-bell', 'Tiên Nữ Tinker Bell', 'Tinker Bell: Secret Of The Wings', 'https://phimimg.com/upload/vod/20231230-1/ffa257109e90decd65c4fa6f6ef5b99b.jpg', 'https://phimimg.com/upload/vod/20231230-1/6f042ef8fb8d8cd1c1bd015b66467e56.jpg', '<p>Tinker Bell được sinh ra từ nụ cười đầu tiên của đứa trẻ sơ sinh và được ngọn gió mang tới Pixie Hollow (một hòn đảo ở Never Land). Tại đây cô gặp những nàng tiên nhỏ khác và biết rằng năng lực của mình là để phục vụ việc hàn gắn mọi thứ - một thiên thần sửa chữa mọi thứ. Các tiên thợ khác đã giúp nhân viên mới học việc và Tinker Bell đã học được nghề, cô có thể sửa được máy nhạc bằng việc sử dụng nước biển. Thế rồi khi cô được kể rằng, chỉ có các nàng tiên thường mới có thể vào lục địa thì cô thấy hơi chạnh lòng cho các nàng tiên như mình. Rồi cô cố gắng nâng cao năng lực của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mae Whitman","avatar":""},{"name":"Lucy Hale","avatar":""},{"name":"Timothy Dalton","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
