INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-ho-an-thit-nguoi-2', 'Cá Hổ Ăn Thịt Người 2', 'Piranha 3DD', 'https://phimimg.com/upload/vod/20231230-1/ca1d998b0bd7bbc956462e25d347a748.jpg', 'https://phimimg.com/upload/vod/20231230-1/ec96cfb17a55720667b3a359b9ca41b7.jpg', '<p>Cá Hổ Ăn Thịt Người 2 - Piranha 3DD tiếp nối phần 1 đem đến cho khán giả những trải nghiệm kinh hoàng nhất. Trong phần 2 này, câu chuyện bắt đầu ở khu công viên nước mới khai trương. Để tiết kiệm kinh phí, những người phụ trách đã dẫn nước từ hồ vào mà không biết rằng đã tự mở con đường xuống địa ngục. Từng con cá ăn thịt hung dữ theo dòng nước chui vào ống dẫn, thỏa sức tàn sát con mồi là các du khách đang vui chơi hết mình ở đây.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Panabaker","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"David Hasselhoff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
