INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-ha-dai-chien', 'Ngân Hà Đại Chiến', 'Battlestar Galactica: Blood & Chrome', 'https://phimimg.com/upload/vod/20231215-1/f90e774f93a31a03df5b199e466b6367.jpg', 'https://phimimg.com/upload/vod/20231215-1/8c9420aebfe359252978a81f40c1a48b.jpg', '<p>Cuộc chiến Cylon đầu tiên đã diễn ra ác liệt trong 10 năm và Thiếu úy William Adama trẻ tuổi gia nhập hạm đội. Thất vọng vì không được giao cho một máy bay chiến đấu mà là một chuyên cơ vận tải, phi công phụ của anh ấy cũng không quá quan tâm đến việc để một tân binh lái máy bay của mình vì anh ấy chỉ còn một thời gian ngắn trước khi trở lại làm dân thường. Hàng hóa của họ là một nhà khoa học dân sự, nhưng họ vừa rời đi thì cô ấy có đơn đặt hàng mới cho họ và một điểm đến mới. Mặc dù cô ấy ít nói về các chi tiết, nhưng Adama rất quan tâm - đặc biệt là khi nó liên quan đến việc đi vào không gian do Cylon kiểm soát. Tuy nhiên, không có gì là như nó có vẻ.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Pasqualino","avatar":""},{"name":"Ben Cotton","avatar":""},{"name":"Brian Markinson","avatar":""},{"name":"Lili Bordán","avatar":""},{"name":"Jill Teed","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324466);
