INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tu-than-3', 'Cuộc Đua Tử Thần 3', 'Death Race 3: Inferno', 'https://phimimg.com/upload/vod/20231215-1/9db3b80b2199dbf03ff9325f3397c1a7.jpg', 'https://phimimg.com/upload/vod/20231215-1/72fe5ded4d2a93060643e9e4e2c669b4.jpg', '<p>Nếu bạn là 1 fan của bộ phim Death Race, hẳn bạn sẽ rất vui mừng vì đạo diễn Roel Reine vừa trở lại cùng phần 3 của bộ phim Death Race 3 : Inferno. Phần 1 của Death Race ra mắt vào năm 2008 với nam tài tử Jason Statham trong vai một tù nhân phải tham gia cuộc đua sinh tử với những người bạn tù và người chiến thắng sẽ có được tự do, sang phần 2 bộ phim giới thiệu một nhân vật mới: Frankenstein được diễn bởi diễn viên Luke Goss, đến phần 3 Goss quay trở lại vai Frankenstein với cuộc đua tại một địa điểm mới: sa mạc Kalahari Nam Phi. Giống như những phần trước của bộ phim, Death Race 3 mang tới những cuộc đua xe tốc độ đầy tàn khốc với những chiếc xe tự chế theo phong cách Mad-Max, đầy súng ống. Bộ phim được dự kiến sẽ ra mắt vào đầu năm sau.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Goss","avatar":""},{"name":"Tanit Phoenix","avatar":""},{"name":"Danny Trejo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324466);
