INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nghin-tu-cuoi-cung', 'Một Nghìn Từ Cuối Cùng', 'A Thousand Words', 'https://phimimg.com/upload/vod/20231219-1/8462e4d6bc9503ec3887856a5df3d8ce.jpg', 'https://phimimg.com/upload/vod/20231219-1/428d14c3235675cf6606af8b900805e6.jpg', '<p>Eddie Murphy trong vai Jack McCall, phát hiện ra một cây lạ mọc lên trong vườn. Cuộc sống anh bắt đầu đảo lộn sau khi được biết mình chỉ còn được nói một nghìn từ nữa, nếu anh nói ra một từ thì sẽ có một chiếc lá rụng xuống và khi chiếc lá cuối cùng lìa cành là lúc cuộc sống của anh sẽ chấm dứt. Gia đình, bạn bè và công việc tất cả sẽ bị ảnh hưởng bởi quyết định của anh, Jack phải tìm cho mình một cách để tiếp tục tồn tại hoặc đơn giản chỉ cần im lặng để sống hết quãng đời còn lại...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Emanuel Ragsdale","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
