INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-hoang', 'Nhật Hoàng', 'Emperor', 'https://phimimg.com/upload/vod/20231215-1/d79fe855fe5bc8cd11521f3c2a7918af.jpg', 'https://phimimg.com/upload/vod/20231215-1/f9d09bf5b6d5a6828dca055f28dd19dc.jpg', '<p>Khi Nhật Bản đầu hàng vào cuối thế chiến thứ hai, tướng Fellers được giao nhiệm vụ quyết định treo cổ Nhật hoàng Hirohito. Tuy nhiên ông đã gặp lại Aya, một sinh viên ông gặp trước đó tại Mỹ, và không ngờ rằng cuộc gặp gỡ này đã ảnh hưởng đến quyết định của ông.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Fox","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Eriko Hatsune","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
