INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-tong-thong-lincoln', 'Cuộc Đời Tổng Thống Lincoln', 'Lincoln', 'https://phimimg.com/upload/vod/20231214-1/38f9c0789a42ec3d46102c6ade4c35b6.jpg', 'https://phimimg.com/upload/vod/20231214-1/612f598aed472cb8c4a938b8a5df3eef.jpg', '<p>Khi cuộc nội chiến tiếp tục diễn ra dữ dội, Tổng thống Mỹ đấu tranh không những với sự tàn sát vẫn đang tiếp diễn trên mặt trận, mà còn với nhiều thế lực khác với quyết định giải phóng nô lệ của mình...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Sally Field","avatar":""},{"name":"David Strathairn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
