INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gi-va-suong', 'Gỉ Và Sương', 'Rust And Bone', 'https://phimimg.com/upload/vod/20231213-1/b2e8a860d50cb77472d88af3dd78870b.jpg', 'https://phimimg.com/upload/vod/20231213-1/99cf1128bd61065d106c359994b0fa5b.jpg', '<p>Rust and Bone kể về câu chuyện tình yêu giữa một chàng trai thất nghiệp 25 tuổi với một người phụ nữ làm nghề huấn luyện cá voi, với sự tham gia của ngôi sao người Pháp từng đoạt giải Oscar Marion Cotillard.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"Armand Verdure","avatar":""},{"name":"Céline Sallette","avatar":""},{"name":"Corinne Masiero","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
