INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-6-cuoc-san-duoi-osama-bin-laden', 'Biệt Đội 6: Cuộc Săn Đuổi Osama Bin Laden', 'Seal Team Six: The Raid On Osama Bin Laden', 'https://phimimg.com/upload/vod/20231213-1/02317bfe9b27d0aa231843966cb3f05b.jpg', 'https://phimimg.com/upload/vod/20231213-1/c741c56a37c00e4cb15b4e7ce5cf5dc7.jpg', '<p>Khi tin đồn về nơi ở của Osama bin Laden được tiết lộ, CIA đã chuẩn bị sẵn một đội SEAL dày dạn kinh nghiệm của Hải quân Hoa Kỳ cho nhiệm vụ để đời. Bất chấp bằng chứng thuyết phục rằng bin Laden đang ở trong khu nhà, và bỏ qua những phân nhánh có thể xảy ra của một cuộc tấn công không báo trước trên đất Pakistan, Lầu Năm Góc ra lệnh tấn công. Đội SEAL kết hợp với nhau để hoàn thành sứ mệnh công lý trong trận quyết đấu cuối cùng hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cam Gigandet","avatar":""},{"name":"Kathleen Robertson","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Anson Mount","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
