INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ham', 'Chiến Hạm', 'Battleship', 'https://phimimg.com/upload/vod/20231213-1/5d8932e5c75de776b7b905915249c5e8.jpg', 'https://phimimg.com/upload/vod/20231213-1/399e72ed4daf020bfc9ab53264a13278.jpg', '<p>Battleship là một bộ phim chiến tranh khoa học viễn tưởng dựa theo game cùng tên do hãng Milton Bradley phát triển. Battleship nói về cuộc giao chiến ác liệt giữa một nhóm người ngoài hành tinh mang tên “The Regents” – những người tới Trái Đất với sứ mệnh xây dựng một nguồn năng lượng trên đại dương và một hạm đội hải quân Mỹ đóng trên vùng biển gần quần đảo Hawaii. Với kinh phí 200 triệu USD, Battleship có sự xuất hiện của ngôi sao ca nhạc Rihanna trong vai một chuyên gia vũ khí trên tàu USS John Paul Jones.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Liam Neeson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324466);
