INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-tu-than', 'Vịnh Tử Thần', 'The Bay', 'https://phimimg.com/upload/vod/20231212-1/263bb26dc232ee130bcdee7dd78e7299.jpg', 'https://phimimg.com/upload/vod/20231212-1/9e635f33f015df52036059dc3de31879.jpg', '<p>Hai triệu con cá dạt vào bờ. Một nghìn con chim đen từ trên trời rơi xuống. Vào ngày 4 tháng 7 năm 2009, một mối đe dọa chết người quét qua thị trấn ven biển cổ kính Claridge, Maryland, nhưng câu chuyện đau lòng về những gì đã xảy ra vào Ngày Độc lập đó chưa bao giờ được kể—cho đến tận bây giờ. Chính quyền tin rằng họ đã chôn vùi sự thật về thảm kịch cướp đi sinh mạng của hơn 700 người. Giờ đây, ba năm sau, một phóng viên đã xuất hiện với đoạn phim tiết lộ sự che đậy và một kẻ giết người ngoài sức tưởng tượng: một đợt bùng phát ký sinh trùng bí ẩn. Được kể từ góc nhìn của những người đã ở đó và chứng kiến những gì đã xảy ra, The Bay diễn ra trong hơn 24 giờ qua iPhone, Android, cuộc gọi 911, webcam và bất kỳ thứ gì khác có thể được sử dụng để ghi lại cơn ác mộng ở Claridge của mọi người. Những gì tiếp theo là một câu chuyện kinh hoàng về một thị trấn nhỏ chìm trong nỗi kinh hoàng tuyệt đối.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Connolly","avatar":""},{"name":"Will Rogers","avatar":""},{"name":"Michael Beasley","avatar":""},{"name":"Christopher Denham","avatar":""},{"name":"Kenny Alfonso","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
