INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ham-my', 'Chiến Hạm Mỹ', 'American Warships', 'https://phimimg.com/upload/vod/20231211-1/3e56ef0ee957c479e7a8f54d2faca6f9.jpg', 'https://phimimg.com/upload/vod/20231211-1/aa0d45937ad702468f5fed1adeade406.jpg', '<p>Khi một thế lực ngoài hành tinh gây chiến trên Trái đất, chỉ có thủy thủ đoàn của USS Iowa - chiến hạm cuối cùng của Mỹ, cản đường họ.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mario Van Peebles","avatar":""},{"name":"Carl Weathers","avatar":""},{"name":"Johanna Watts","avatar":""},{"name":"Nikki McCauley","avatar":""},{"name":"Devin McGee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
