INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-mat-toi-lu-quy', 'Để Mắt Tới Lũ Quỷ', 'Jeff Dunham: Minding The Monsters', 'https://phimimg.com/upload/vod/20231211-1/e49b2e92b5c3468cb0a18e60eea0592b.jpg', 'https://phimimg.com/upload/vod/20231211-1/e7a213a7006580ed4fd674556cc99411.jpg', '<p>Jeff Dunham là một chàng trai có sức thu hút đặc biệt không chỉ ở ngoại hình ưa nhìn mà còn ở một biệt tài hiếm có - khả năng điều khiển những con rối và nói nhiều giọng (bằng giọng bụng). Với biệt tài này, anh đã mang lại vô vàn tiếng cười cho khán giả qua những màn kịch rối cực kỳ đặc sắc. Và lần này, anh đã cùng với những người bạn của mình đã biến ngôi nhà bí ẩn thành 1 sân khấu hài hước.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Dunham","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
