INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('de-mat-toi-lu-quy', 'Để Mắt Tới Lũ Quỷ', 'Jeff Dunham: Minding The Monsters', 'để mắt tới lũ quỷ jeff dunham: minding the monsters jeff dunham ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-chua-bon-mua', 'Nhà Chứa Bốn Mùa', 'The Seasoning House', 'https://phimimg.com/upload/vod/20231211-1/6b13c1ae7b805d708b36cc073ebc1ab6.jpg', 'https://phimimg.com/upload/vod/20231211-1/466a78526557949b109438e5c0ee8d91.jpg', '<p>The Seasoning House - nơi các cô gái trẻ bị bán dâm cho quân đội. Một đứa trẻ câm điếc mồ côi bị bắt làm nô lệ để chúng chăm sóc. Cô ấy di chuyển giữa các bức tường và không gian thu thập thông tin, lên kế hoạch trốn thoát. Kế hoạch trả thù tài tình và tàn bạo của cô.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rosie Day","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Kevin Howarth","avatar":""},{"name":"Anna Walton","avatar":""},{"name":"Jemma Powell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
