INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-goi-cam', 'Sát Thủ Gợi Cảm', 'Naked Soldier', 'https://phimimg.com/upload/vod/20231211-1/c652ecbb2388ded5e1b27c90ddf63216.jpg', 'https://phimimg.com/upload/vod/20231211-1/f342798c47456df2bf344bc37759b5a6.jpg', '<p>15 năm trước, đặc vụ hình cảnh quốc tế CK Long cùng các đồng đội Interpol phá án thành công áp phe ma túy trị giá hàng triệu đô la của tập đoàn Cartel. Điên cuồng trả thù, chúng đã mượn tay tổ chức Madame Rose sát hại ông và cả gia đình. CK Long bị thương nặng và may mắn sống sót sau thảm họa “diệt môn”, nhưng cô con gái 5 tuổi Phoenix thì lại bị bắt cóc. Phoenix bị xóa trí nhớ và được huấn luyện cùng với bảy đứa trẻ khác trở thành những sát thủ chuyên nghiệp phục vụ cho những phi vụ đen tối của tổ chức. CK Long không hề biết rằng sau 15 năm, con gái mình cùng những đứa trẻ khác đã trở thành những sát thủ đẳng cấp nhất thế giới dưới tên gọi “Những sát thủ gợi cảm” (Naked Soldiers). Để che giấu tung tích, mỗi sát thủ đã ngụy trang thành những công dân bình thường để hoạt động bí mật ở những thành phố lớn như Los Angeles, Hồng Kông, Đài Loan, Tokyo. Trong đó, Phoenix sống dưới vỏ bọc một sinh viên Đại học ở Đài Loan. Khi Phoenix tiến hành ám sát Iron Wolf ở Đài Loan, cô đã không ra tay với người thân của Iron Wolf và sơ suất để lại vết máu của mình tại hiện trường. Đó cũng chính là dấu vết để CK Long phát hiện Phoenix là cô con gái ngày nào. Trước tình thế đó, Madam Rose đã lên một kế hoạch độc ác để Phoenix sẽ tự kết liễu chính cha ruột mình sau khi vô tình phát hiện ra bí mật này...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Jennifer Tse","avatar":""},{"name":"Sammo Hung Kam-Bo","avatar":""},{"name":"Ankie Beilke","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
