INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bep-truong', 'Bếp Trưởng', 'Le Chef', 'https://phimimg.com/upload/vod/20231212-1/d7521a22571cc7948e52f56013d1700e.jpg', 'https://phimimg.com/upload/vod/20231212-1/e85623ef17ef7e56be0cd14e508ee015.jpg', '<p>Một đầu bếp kỳ cựu đối đầu với Giám đốc điều hành mới của tập đoàn nhà hàng của mình, người muốn cơ sở mất một sao trong bảng xếp hạng để thu hút một đầu bếp trẻ chuyên về ẩm thực phân tử.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Michaël Youn","avatar":""},{"name":"Raphaëlle Agogué","avatar":""},{"name":"Julien Boisselier","avatar":""},{"name":"Salomé Stévenin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
