INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-bong-dem-troi-day', 'Kỵ Sĩ Bóng Đêm Trỗi Dậy', 'The Dark Knight Rises', 'https://phimimg.com/upload/vod/20231212-1/68a89cc3ceb09c5280393df200682b4d.jpg', 'https://phimimg.com/upload/vod/20231212-1/0944b2a5a2d6c69489f5d686691c5d4b.jpg', '<p>Mặc dù nổi tiếng của anh ta sau những sự kiện của The Dark Knight (2008), trong đó anh ta tham gia rap cho tội ác của vết lõm, người Batman cảm thấy bị buộc phải can thiệp để hỗ trợ thành phố và lực lượng cảnh sát của nó, đang vật lộn để đối phó với kế hoạch của Bane để phá hủy thành phố.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
