INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-giang-sinh-kinh-hoang', 'Đêm Giáng Sinh Kinh Hoàng', 'Silent Night', 'https://phimimg.com/upload/vod/20231211-1/f9d2c7c060e8d32557051143d30ab955.jpg', 'https://phimimg.com/upload/vod/20231211-1/70ac61b1039cb14c9af70138b598be3b.jpg', '<p>Lực lượng cảnh sát của một thị trấn xa xôi ở miền Trung Tây đang tìm kiếm một ông già Noel sát thủ đang đón người dân vào đêm Giáng sinh.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jaime King","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Brendan Fehr","avatar":""},{"name":"Lisa Marie","avatar":""},{"name":"Ellen Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
