INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-toa-chau-liem', 'Cung Tỏa Châu Liêm', 'Locked Beaded Curtain', 'https://phimimg.com/upload/vod/20231219-1/aab6b06d35741475ccf5426965c30e8b.jpg', 'https://phimimg.com/upload/vod/20231219-1/53cdff1bd6ca42f401ecd507e9863c16.jpg', '<p>Vào năm Ung Chính triều Thanh, con gái của dự khuyết tứ phẩm Điển Nghi Lăng Trụ là Liên Nhi, nghe lời cha mà kết giao với Thập thất vương gia Dận Lễ. Hai bên giao tình đậm sâu, vốn muốn kết bái phu thê. Không ngờ Dận Lễ vì muốn cứu lão sư A Linh A, bất đắc dĩ phải lấy con gái của A Linh A là Gia Gia làm vợ. Liên Nhi đau lòng quyết định nhập cung, ngày ngày hầu hạ trong thâm cung, khát vọng một ngày có thể rời xa chốn cung đình sống cuộc sống bình yên, không ngờ lại bị các phe phái lợi dụng. Lý Vệ muốn liên minh với nàng, tổng quản thái giám Tô Bồi Thịnh muốn báo ân với nàng, Ngọc Thấu - người chị em tốt lúc mới nhập cung - lại bán đứng và hãm hại nàng. Chốn thâm cung bề ngoài tĩnh lặng nhưng bên trong lại ẩn giấu nhiều bí mật khôn lường. Vào lúc Liên Nhi mệt mỏi, chán nản, tình cờ nàng lọt vào mắt xanh của Ung Chính, trở thành Hi phi được sủng ái muôn phần. Vào lúc này nàng bỗng phát hiện ra tất cả mọi chuyện đều trở nên rất phức tạp. Dừng lại thì sẽ bị bức hại, tiếp tục thì có thể đánh mất cả bản thân mình. Ở ngã ba đường, nàng chọn cách tin vào ánh dương, tin rằng giông bão rồi cũng sẽ trôi qua. Thế là nàng kiên nhẫn tiếp tục chịu đựng. Cuối cùng cũng tự mình tạo nên khoảng trời riêng</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 19, 2012, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Thịnh Minh","avatar":""},{"name":"Viên San San","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Tôn Phi Phi","avatar":""},{"name":"Thư Sướng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324466);
