INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-sat-nhan', 'Đối Mặt Sát Nhân', 'Gone', 'https://phimimg.com/upload/vod/20231211-1/8db1ef5c5c18270b220f73fdbedfdc93.jpg', 'https://phimimg.com/upload/vod/20231211-1/e826a3870eea2aa0b29c4a4ecadfa560.jpg', '<p>Jill Parish, một thiếu nữ đã phát hiện chị gái mình bị bắt cóc sau khi đi làm về và Jill Parish cho rằng kẻ bắt cóc chính là tên giết người hàng loạt đã bắt cóc cô vào hai năm về trước đã trở lại với ý định trả thù. Nhưng cô không có bất kì chứng cứ hay dấu vết gì của tên sát nhân ấy và cảnh sát cũng không tin vào câu chuyện của Jill Parish, họ nghĩ rằng cô đã tự tưởng tượng ra tất cả mọi chuyện. Chẳng có ai giúp đỡ, cô quyết tìm ra tên sát nhân trước khi tính mạng của chị gái bị đe dọa.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Wes Bentley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
