INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-an-do-1', 'Giang Hồ Ấn Độ 1', 'Gangs Of Wasseypur-part1', 'https://phimimg.com/upload/vod/20231211-1/cca171f2b1e9d1eff4718ceb1b034e5a.jpg', 'https://phimimg.com/upload/vod/20231211-1/305b36afb1f4dbec260ab54c2c0c11cc.jpg', '<p>Phim kể về Shahid Khan, một thanh niên muốn lấy lại danh tiếng của cha mình sau khi cha anh bị một ông chủ mỏ than sát hại. Shahid lập một băng nhóm và hứa sẽ đưa nhóm giang hồ này trở thành một băng nhóm đáng sợ và quyền lực nhất ở Wasseypur.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Manoj Bajpayee","avatar":""},{"name":"Richa Chadha","avatar":""},{"name":"Tigmanshu Dhulia","avatar":""},{"name":"Nawazuddin Siddiqui","avatar":""},{"name":"Reema Sen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
