INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-sung-suong-hay-goi', 'Muốn Sung Sướng, Hãy Gọi...', 'For A Good Time, Call...', 'https://phimimg.com/upload/vod/20231211-1/2d11819a7cb41d3d40c4acbabd3460a2.jpg', 'https://phimimg.com/upload/vod/20231211-1/ad1fb01919daa5575f361bc90907dea3.jpg', '<p>Để trang trải thêm cho cuộc sống, hai cô nàng Lauren và Katie làm thêm bằng nghề nói chuyện sex qua điện thoại. Xen giữa những cuộc trò chuyện gợi tình là một vài cảnh nóng của hai cô gái trẻ.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ari Graynor","avatar":""},{"name":"Lauren Miller","avatar":""},{"name":"Justin Long","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
