INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-beo-cuu-tinh', 'Chàng Béo Cứu Tinh', 'Here Comes The Boom', 'https://phimimg.com/upload/vod/20231211-1/0b6816e9fdebcb1cf020b371d1431c76.jpg', 'https://phimimg.com/upload/vod/20231211-1/c72b83ca904d31ef2a3d31fd3fc9f39f.jpg', '<p>Scott chàng giáo viên sinh học quá cỡ đang cố gắng trở thành một võ sĩ chuyên nghiệp nhằm kiếm tiền duy trì các hoạt động ngoại khóa đang bị cắt giảm không thương tiếc tại ngôi trường vô cùng túng thiếu này. Hiện tượng âm nhạc trẻ tuổi người Philippines, Charice, một lần nữa lại góp mặt trong bộ phim bằng chính giọng ca trời phú của cô. Và chắc chắn cô sẽ lại chinh phục được tất cả những khán giả khó tính nhất</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin James","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Henry Winkler","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
