INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chang-beo-cuu-tinh', 'Chàng Béo Cứu Tinh', 'Here Comes The Boom', 'chàng béo cứu tinh here comes the boom kevin james salma hayek henry winkler ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-ngoi-sao-giang-sinh', 'Truy Tìm Ngôi Sao Giáng Sinh', 'Journey To The Christmas Star', 'https://phimimg.com/upload/vod/20231211-1/9961935b4339be53c4407c8526bb6384.jpg', 'https://phimimg.com/upload/vod/20231211-1/81e4a257dafefbd573cd9f190f91745a.jpg', '<p>Sonja 13 tuổi tốt bụng đến một ngôi làng nhỏ cùng với một nhóm cướp. Nhưng có một lời nguyền trên ngôi làng. Cách đây rất lâu, cô con gái duy nhất của Nhà vua Goldhair đã biến mất khi đang tìm kiếm Ngôi sao Giáng sinh. Nữ hoàng chết vì một trái tim tan vỡ, để lại vị vua tan nát một mình. Kể từ ngày đó, Nhà vua đã nguyền rủa Ngôi sao Giáng sinh, do đó khiến bóng tối và đau buồn giáng xuống vùng đất này. Tuy nhiên, một nhà hiền triết già đã tiết lộ rằng Goldhair vẫn còn sống và sẽ chỉ trở lại nếu Nhà vua tìm được đường trở lại Ngôi sao Giáng sinh. Kể từ đó, Nhà vua luôn tìm kiếm Ngôi sao Giáng sinh vào mỗi dịp Giáng sinh, nhưng đều vô ích.</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Vilde Zeiner","avatar":""},{"name":"Anders Baasmo Christiansen","avatar":""},{"name":"Agnes Kittelsen","avatar":""},{"name":"Stig Werner Moe","avatar":""},{"name":"Eilif Hellum Noraker","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
