INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-mo-tu-than', 'Khu Mộ Tử Thần', 'Dead Mine', 'https://phimimg.com/upload/vod/20231211-1/708e576a8d386940937ab81ab3333f69.jpg', 'https://phimimg.com/upload/vod/20231211-1/354e1d92485ff3f54fa0646f5b934f77.jpg', '<p>Truyền thuyết về Vàng của Yamashita thu hút một thợ săn kho báu và nhóm của anh ta vào sâu trong rừng rậm Indonesia. Khi họ bị mắc kẹt trong một boong-ke bị bỏ hoang trong Thế chiến II của Nhật Bản, họ phải đối mặt với thực tế đáng sợ rằng lối thoát duy nhất là tiến sâu hơn vào bên trong.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Ario Bayu","avatar":""},{"name":"Miki Mizuno","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Les Loveday","avatar":""},{"name":"Carmen Soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
