INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-con-mai', 'Điều Còn Mãi', 'Still Mine', 'https://phimimg.com/upload/vod/20231211-1/0603be483d689f9eee97bd40dbac15b7.jpg', 'https://phimimg.com/upload/vod/20231211-1/796a247d1dfd49e5acfa6f6929c1a833.jpg', '<p>Craig, một nông dân New Brunswick quyết tâm cao, bắt đầu xây dựng một ngôi nhà phù hợp hơn cho người vợ ốm yếu của mình, Irene, bất chấp những lo lắng về con cái của họ. Khi bắt đầu xây dựng, anh ta bị che mắt bởi các quy tắc và quan chức quan liêu. Khi Irene ngày càng ốm yếu, Craig chống trả. Dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Cromwell","avatar":""},{"name":"Geneviève Bujold","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"Julie Stewart","avatar":""},{"name":"Rick Roberts","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
