INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-man-dong-tien-2', 'Vị Mặn Đồng Tiền 2', 'Easy Money II', 'https://phimimg.com/upload/vod/20231211-1/17911b7247d087722c432dee8db79c0c.jpg', 'https://phimimg.com/upload/vod/20231211-1/be99f28206cb20eaae9836abc708a3eb.jpg', '<p>Johan ‘JW’ Westlund một sinh viên mới ra trường đã thất bại trong lần phỏng vấn xin việc đầu tiên, vì muốn có tiền anh đã vận chuyển ma tuý và phải trả giá bằng 3 năm tù. Sau khi ra tù anh hy vọng sẽ trở lại cuộc sống bình thường nhưng đã thất bại khi anh dính vào một vụ thanh toán của một thành viên Mafia Nam Tư trong kế hoạch đòi lại số tiền bị mất của người bạn tù mà anh quen biết.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Matias Varela","avatar":""},{"name":"Dragomir Mrsic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
