INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-anh-dinh-menh', 'Bức Ảnh Định Mệnh', 'The Lucky One', 'https://phimimg.com/upload/vod/20231211-1/49740cc2d69618e4047b283a68f0bc22.jpg', 'https://phimimg.com/upload/vod/20231211-1/94f26f9b17f855cf2652f5c3046158ae.jpg', '<p>Logan là một hàng hải phục vụ ở Iraq. Trong khi ở đó, anh ta tìm thấy một bức ảnh của một cô gái với Giữ an toàn được viết trên lưng. Anh ta đang chiêm ngưỡng nó khi đơn vị của anh ta bị tấn công. Anh ta sống sót và tin tưởng bức ảnh để cứu anh ta. Anh ta cố gắng tìm chủ sở hữu nhưng không thể, giả sử anh ta đã bị giết. Khi anh quay trở lại các bang, anh thấy khó điều chỉnh và vẫn bị ám ảnh bởi những gì đã xảy ra. Phân tích bức ảnh, anh ta tìm thấy trong nền một cột mốc nói với anh ta rằng cô ấy đang ở Louisiana. Sau đó anh ấy đến đó và tìm thấy cô ấy. Anh ấy học tên của cô ấy là Beth. Anh cố gắng nói với cô những gì đã xảy ra nhưng không thể hiểu được những lời. Cô ấy giả định rằng anh ta ở đó để xin việc mà họ quảng cáo đang tìm kiếm ai đó để giúp đỡ trong việc kinh doanh của gia đình cô ấy, một con chó cái chó. Anh ta nói có nhưng lúc đầu, cô cảm thấy khó chịu từ anh ta nhưng bà của cô quyết định cho anh ta một cơ hội. Không lâu nên anh ta kết nối với con trai mình. Sau đó, anh ta phát hiện ra rằng đó là anh trai cô chỉ có bức ảnh, anh ta không nhớ anh ta. Anh ta thấy rằng cái chết của anh trai cô có ảnh hưởng sâu sắc đến cô. Cuối cùng, họ trở nên gần gũi mà làm cho bà của cô hạnh phúc nhưng không phải là người yêu cũ của cô là một phó cảnh sát trưởng luôn đe dọa sẽ đưa con trai của họ ra khỏi cô.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
