INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-ao-den', 'Người Đàn Bà Áo Đen', 'The Woman In Black', 'https://phimimg.com/upload/vod/20240102-1/b8e7308c274ad9ac184078a6a10072f5.jpg', 'https://phimimg.com/upload/vod/20240102-1/7a3013f016275c8da016959e8f5392df.jpg', '<p>The Woman in Black được thực hiện dựa trên cuốn tiếu thuyết của tác giả Susan Hill. Phim kể về luật sư trẻ Arthur Kipps, người phải đến ngôi làng xa xôi để phân loại những giấy tờ tài liệu của một vị khách hàng vừa mới qua đời. Tại đây, anh tình cờ khám phá ra những bí mật khủng khiếp của căn nhà. Bí mật này hình như có liên quan đến một người phụ nữ bí ẩn thường xuyên mặc đồ màu đen. Dân địa phương không ai dám hé môi về tung tích của bà ta. Khi người thân của anh bị đe dọa bởi nhân vật bí ẩn và đầy hận thù, Arthur Kipps phải tìm cách phá vỡ guồng xoay của sự khiếp đảm này.</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Ciarán Hinds","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
