INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than-5', 'Ngã Rẽ Tử Thần 5', 'Wrong Turn 5: Bloodlines', 'https://phimimg.com/upload/vod/20231210-1/116d1d7f44fe4a9cc995e201614a88ee.jpg', 'https://phimimg.com/upload/vod/20231210-1/520c31673844b31d450da2dd2de36464.jpg', '<p>Dân vùng núi đã quay lại thị trấn! Những kẻ man di, máu lạnh ăn thịt người được biết tới với cái tên Ba Ngón, Một Mắt và Răng Cưa (trong phần 4) cũng quay lại. Lần này thị trấn nhỏ Fairlake, Tây Virginia trở thành khu vui chơi của chúng trong đêm Halloween...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Doug Bradley","avatar":""},{"name":"Camilla Arfwedson","avatar":""},{"name":"Simon Ginty","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
