INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-vo-toi-di', 'Yêu Vợ Tôi Đi', 'All About My Wife', 'https://phimimg.com/upload/vod/20231210-1/64ccd1747615ae1fdd98a13820b12c16.jpg', 'https://phimimg.com/upload/vod/20231210-1/f1706cee7e121455ece2d9848f73c0c5.jpg', '<p>Jung-in là một người phụ nữ thông minh, tươi tắn, quyến rũ, hoàn hảo trong mắt mọi đàn ông. Nhưng khi cô lên tiếng, với vô vàn lời phàn nàn và rắc rối, địa ngục dường như đang ập xuống với chồng cô. Chính vì vậy, Doo-hyun, chồng cô luôn ấp ủ mong muốn được ra đi, để thoát khỏi những đau khổ dày vò. Nhưng liệu một người chồng nhút nhát, rụt rè có dám bỏ người vợ khó chiều? Chỉ còn một cách, đó là người vợ phải biến mất khỏi cuộc đời anh. Và anh chồng quyết định thuê một anh chàng chuyên ... cưa gái để chinh phục vợ ... Một câu chuyện ngược luyến tàn tâm mới lạ, hấp dẫn, hài hước xen lẫn dàn diễn viên đẹp, diễn xuất tốt Tất cả về Vợ người ta hội đủ những yếu tố trở thành một trong những bộ phim ăn khách nhất năm 2012 tại Hàn Quốc.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Im Soo-jung","avatar":""},{"name":"Lee Sun-kyun","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Kim Jung-tae","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
