INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tho', 'Nàng Thơ', 'A Muse', 'https://phimimg.com/upload/vod/20231211-1/fff1d02de6ca266fa89fb7c9f2691f7c.jpg', 'https://phimimg.com/upload/vod/20231211-1/658d85512d2dde85b74f0a025d340095.jpg', '<p>Lee Jeok-yo là một ông già 70ish, một nhà thơ được kính trọng. Anh ta quan tâm đến sự đệ tử 30ish tuổi 30ish Seo Ji-Woo. Thế giới của hai người đàn ông này bị lung lay khi học sinh trung học 17 tuổi Han Eun-Gyo bước vào bức tranh, khi tâm trí và những ham muốn tình dục của họ được đánh thức.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324466);
