INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dai-dam-mau', 'Võ Đài Đẫm Máu', 'Cage Fight', 'https://phimimg.com/upload/vod/20231231-1/e0504d67a9c0fd3617a13765f6bc28e4.jpg', 'https://phimimg.com/upload/vod/20231231-1/873d36065e9640a4c723676c263b42ef.jpg', '<p>Guerero một người cư trú bất hợp pháp đến từ Mexico, Xuyên qua biên giới để đến Mỹ tìm gia đình. Sau khi đến Sandiego, anh gặp tổ chức tội phạm Gino Santoro - người đã cho anh công việc, chỗ ở và đề nghị giúp anh tìm gia đình. Chỉ có 1 điều kiện Guerero phải chiến đấu cho cuộc sống của mình trong phạm vi và chỉ bằng cách phải thật mạnh mẽ mới có cơ hội sống sót. Phim được dành riêng độc quyền cho hành khách Vietnam Airlines.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Aguilar","avatar":""},{"name":"Alberto Alvarado","avatar":""},{"name":"Lorena Bernal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324466);
