INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-linh-hon-chet', 'Những Linh Hồn Chết', 'Dead Souls', 'https://phimimg.com/upload/vod/20231231-1/93f2a91aa917ee300098bfaa2eacf0db.jpg', 'https://phimimg.com/upload/vod/20231231-1/51135c767a1be22cf5a9f4c7780a6152.jpg', '<p>Johnny Petrie biết được vào sinh nhật thứ 18 của mình rằng anh được nhận nuôi sau khi thừa kế một trang trại ở Maine. Háo hức muốn bắt đầu một cuộc sống mới, Johnny chuyển đến sống ở trang trại này. Tuy nhiên, Johnny sớm phát hiện ra rằng, trang trại đã bị bỏ hoang trong 18 năm kể từ khi gia đình thật sự của anh qua đời, và nó cũng chứa đựng ký ức kinh hoàng về cái chết của gia đình anh.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Magda Apanowicz","avatar":""},{"name":"Bill Moseley","avatar":""},{"name":"Emma","avatar":""},{"name":"Jesse James","avatar":""},{"name":"Johnny Petrie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
