INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-hat-karaoke', 'Chàng Trai Hát Karaoke', 'Karaoke Man', 'https://phimimg.com/upload/vod/20231230-1/041268841730bdd5205616eddbc7cd8d.jpg', 'https://phimimg.com/upload/vod/20231230-1/b36103dbcbee9e799728ce8312ce518e.jpg', '<p>Để chinh phục Glennis, một nhạc sĩ và đồng thời cũng là một nữ nhân viên xinh đẹp làm việc trong quán karaoke, anh chàng Louis buộc phải biến mình thành một thiên tài ca hát để thu hút sự chú ý của cô. Từ một anh chàng nhút nhát, liệu Louis có thành công?</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Dietzen","avatar":""},{"name":"Caitlin Crosby","avatar":""},{"name":"James Denton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
