INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-abby', 'Siêu Nhân Abby', 'Siêu Nhân Abby', 'https://phimimg.com/upload/vod/20231230-1/7c63c84819f1bc3be548f2104c220020.jpg', 'https://phimimg.com/upload/vod/20231230-1/e40479e5dcfaffa2f45640119804afa8.jpg', '<p>Gia đình Careful là một gia đình rất tốt bụng, nhưng lại rất lơ đãng. Đặc điểm chính của gia đình này là khả năng liên tục bị rối loạn. Abby Careful là một cô gái mơ mộng thích đọc truyện tranh siêu anh hùng nhưng rất có trách nhiệm. Khi gia đình gặp nguy hiểm, Abby đã để cho trí tưởng tượng của mình bay xa và trở thành Super Abby, một nữ siêu anh hùng giống như trong truyện tranh yêu thích của cô bé, để thoát khỏi \</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2012, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
