INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-duoi-voi-sen', 'Xác Chết Dưới Vòi Sen', 'Hitchcock', 'https://phimimg.com/upload/vod/20231229-1/1f74c4f49a784d0a55b6d4dcdf91d525.jpg', 'https://phimimg.com/upload/vod/20231229-1/01ccf91f2e080354eb350a721d6e4d10.jpg', '<p>Sau thành công vang dội với North by Northwest, đạo diễn Alfred Hitchcock đưa ra một lựa chọn táo bạo cho dự án tiếp theo của mình: chuyển thể từ tiểu thuyết Psycho của Robert Bloch. Khi hãng phim từ chối trả lại bức ảnh, Hitchcock quyết định tự mình trả tiền để đổi lấy phần trăm lợi nhuận. Vợ anh, Alma Reville, rất dè dặt về bộ phim nhưng vẫn ủng hộ anh. Tuy nhiên, quá trình sản xuất khiến cuộc hôn nhân của cặp đôi trở nên căng thẳng.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Jessica Biel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
