INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-doc-tai', 'Kẻ Độc Tài', 'The Dictator', 'https://phimimg.com/upload/vod/20231210-1/16943ea637713fb5273ca82aea6aa9a9.jpg', 'https://phimimg.com/upload/vod/20231210-1/05f80b57c2c650cf4947d2df723d50bd.jpg', '<p>Cộng hòa Wadiya được cai trị bởi một nhà lãnh đạo lập dị và áp bức tên là Hafez Aladeen. Aladeen được triệu tập đến New York để lắp ráp Liên Hợp Quốc để giải quyết các mối quan tâm về chương trình vũ khí hạt nhân của đất nước mình, nhưng chuyến đi trở nên tồi tệ.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
