INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('stuck-in-love', 'Stuck In Love.', 'Stuck In Love.', 'https://phimimg.com/upload/vod/20231209-1/551eb5edd757b6931be4f7d1cb1a8263.jpg', 'https://phimimg.com/upload/vod/20231209-1/a8ed033898eda9d0594b24d9a0d43702.jpg', '<p>Gặp gỡ các nhà kho. William Borgens là một tác giả được hoan nghênh, người đã không viết một từ kể từ khi vợ cũ Erica rời bỏ anh 3 năm trước cho một người đàn ông khác. Ở giữa gián điệp erica và romps thông thường với người hàng xóm kết hôn với Tricia, Bill đang đối phó với sự phức tạp của việc nuôi dạy những đứa trẻ thiếu niên Samantha và Rusty. Samantha đang xuất bản cuốn tiểu thuyết đầu tiên của mình và quyết tâm tránh tình yêu bằng mọi giá - sau tất cả những gì cô ấy đã thấy những gì nó đã làm cho cha mẹ cô ấy. Ở giữa Hook Ups, cô gặp chàng trai tốt Lou, người sẽ không dừng lại để giành chiến thắng. Rusty, là một nhà văn giả tưởng đầy tham vọng và Stephen King Aficionado, người đang tìm kiếm một nhiệm vụ để đạt được trải nghiệm cuộc sống. Anh ta rơi vào Kate xinh đẹp, nhưng bối rối và có được hương vị đầu tiên của tình yêu và một trái tim tan vỡ. Một câu chuyện về gia đình, tình yêu (bị mất và tìm thấy), và cách kết thúc có thể tạo ra những khởi đầu mới. Không có viết lại trong cuộc sống, chỉ có cơ hội thứ hai.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324466);
