INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-ruc-lua', 'Con Đường Rực Lửa', 'Agneepath', 'https://phimimg.com/upload/vod/20231209-1/7a5425b1d4b6594f61ed4e26275647b6.jpg', 'https://phimimg.com/upload/vod/20231209-1/63a9b2f24f5f125d4f830b9ec85e0650.jpg', '<p>Tại một làng nhỏ Mandwa của Ấn độ, Vijay Dinanath Chauhan được cha dạy cách sử dụng lửa trong lò rèn. Cuộc đời của anh đi vào ngõ cụt khi tên ác bá trong vùng treo cổ cha anh. Vijay bỏ quê lên Bombay với người mẹ đang mang trong mình đứa em của mình với ước muốn một ngày nào đó sẽ trở lại Mandwa and gây dựng lại vinh quang của cha và trả thù tên ác bá Kancha Cheena...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Hrithik Roshan","avatar":""},{"name":"Priyanka Chopra","avatar":""},{"name":"Sanjay Dutt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
