INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-doi-sa-nga', 'Đường Đời Sa Ngã', 'On The Road', 'https://phimimg.com/upload/vod/20231208-1/4c9a4619d3cef91b34022fe97c725380.jpg', 'https://phimimg.com/upload/vod/20231208-1/0d9f2e1538c84a6bee6f416c854b02a9.jpg', '<p>Phim lấy bối cảnh ở New York cuối những năm 1940 với lối sống trụy lạc bất cần. Bộ phim kể về chuyến hành trình đi xuyên nước Mỹ của bộ ba Dean - Sal - Marylou. Trên đường đi, họ bị cuốn vào dòng xoáy của tình dục, rượu và ma túy.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Garrett Hedlund","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Tom Sturridge","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
