INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-huyet-ngai', 'Lời Nguyền Huyết Ngải', 'Loi Nguyen Huyet Ngai', 'https://phimimg.com/upload/vod/20231210-1/e47413ec50d7a8e4a4b2723b141bdac0.jpg', 'https://phimimg.com/upload/vod/20231210-1/411edd12b1374b9ca10e49be7bc0da84.jpg', '<p>Chuyện phim xoay quanh việc ba cậu sinh viên - Bình, Tùy và Khải - tìm thấy chiếc hộp gỗ, trong có chứa mẩu cây khô héo và câu bùa chú trong ngăn kéo của thầy giáo Hoàn Sinh. Khi biết đây là loài ngải hút máu người của dân tộc Sắng La và có thể chữa bệnh, cả ba lao vào nghiên cứu. Trong công cuộc tìm hiểu về loại cây kỳ lạ này, ba cậu sinh viên tìm tới một ngôi nhà u ám - nơi có một cô bé được mệnh danh là Thánh cô, vẫn mở cửa vào những đêm trăng rằm để chữa bệnh cho người dân. Thánh cô tên thật là Chiêu Dương, 16 tuổi, có vẻ đẹp ngây thơ nhưng đầy chất ma mị, và rất thích lang thang đi chơi vào đêm khuya.</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Thành Lộc","avatar":""},{"name":"Đỗ Văn Hoàng","avatar":""},{"name":"Trịnh Minh Huy","avatar":""},{"name":"Phan Anh","avatar":""},{"name":"Yu Dương","avatar":""},{"name":"Nhu Quynh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
