INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-doan', 'Thủ Đoạn', 'Passion', 'https://phimimg.com/upload/vod/20231208-1/8f420eef5fa0a729d191cd020a9ce60b.jpg', 'https://phimimg.com/upload/vod/20231208-1/3dab48ce1a3b13139a5c77f59a93628a.jpg', '<p>Sự cạnh tranh giữa ông chủ lôi kéo của một công ty quảng cáo và người được bảo trợ tài năng của cô leo thang từ ăn cắp tín dụng đến sỉ nhục công khai rồi giết người.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
