INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-ban-on-nuoc-my', 'Chúa Ban Ơn Nước Mỹ', 'God Bless America', 'https://phimimg.com/upload/vod/20231208-1/c40b831d3702997241d84bcd506c5bbd.jpg', 'https://phimimg.com/upload/vod/20231208-1/106eacab189bb914fab3a39a8eb784af.jpg', '<p>Sau khi nhận được thông báo có khối u não, Frank cảm thấy chán nản cuộc sống và định tự tử nhưng khi xem một chương trình truyền hình thực tế, một cô bé hư hỏng nổi khùng lên chỉ vì nhận được chiếc ô tô không đúng ý trong ngày sinh nhật làm anh ta đổi ý và thay vào đó quyết định sẽ gây ra hàng loạt vụ giết người nhằm vào những kẻ theo anh là đáng chết để thế giới tốt đẹp hơn. Trên đường hành hiệp, Frank gặp được cô bé 16 tuổi Roxy và không ngờ cô bé cũng ủng hộ Frank. Cả hai bắt đầu hành trình bắn phá khắp nơi của mình...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joel Murray","avatar":""},{"name":"Tara Lynne Barr","avatar":""},{"name":"Mackenzie Brooke Smith","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
