INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-gio-sang', '3 Giờ Sáng', '3 A.M. 3D', 'https://phimimg.com/upload/vod/20231208-1/0bd84a8d32d5a775beba3576222717b4.jpg', 'https://phimimg.com/upload/vod/20231208-1/49045f340e5ac769b7c5064dbde68273.jpg', '<p>Omnibus kinh dị mới nhất của Thái Lan được tạo thành từ ba câu chuyện lạnh lùng. Hai chị em sở hữu một cửa hàng tóc giả. Một nhân viên nhà tang lễ rơi vào tình yêu. Hai giám đốc công ty yêu thích chơi khăm đáng sợ. Ba câu chuyện được đặt lúc 3 giờ sáng, giờ khốn lắm nhất trong đêm, nơi tất cả các linh hồn đều tự do đi lang thang.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
