INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-chong-ma-tuy', 'Lực Lượng Chống Ma Túy', 'Grupo 7', 'https://phimimg.com/upload/vod/20231219-1/478f1e4189c94fbededff643fc5b0e75.jpg', 'https://phimimg.com/upload/vod/20231219-1/0c57848a2bd146569aa7f5312de20f54.jpg', '<p>Grupo 7 có một nhiệm vụ khó khăn là làm sạch các mạng lưới buôn bán ma túy nguy hiểm nhất của thành phố và kết thúc sức mạnh ảnh hưởng của các tổ chức băng nhóm đường phố. Grupo 7 được dẫn dắt bởi Angel, một sĩ quan trẻ đầy khao khát, và Rafael, một cảnh sát ngạo mạn, và hành động với tính cách bạo lực...</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Inmaculada Alcántara","avatar":""},{"name":"Andrés Blanco","avatar":""},{"name":"Javier Berger","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
