INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-diep-vien-bat-diet', 'Nữ Điệp Viên Bất Diệt', 'Bond Girls Are Forever (2012)', 'null', 'https://phimimg.com/upload/vod/20231219-1/bcb4ab78d2b96b0da0c985f975a92eed.jpg', '<p>Nữ Điệp Viên Bất Diệt - Bond Girls Are Forever (2012) - bộ phim thông qua các đoạn phim cổ điển sử thi Bond trong quá khứ, và với sự tham gia của một số cựu Bond Girl, bộ phim tài liệu lần ra quá trình phát triển của nữ anh hùng James Bond điển hình từ cô gái xinh đẹp gặp nạn cho đến người tham gia dũng cảm.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Halle Berry","avatar":""},{"name":"Maryam d&#x27;Abo","avatar":""},{"name":"Ursula Andress","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
