INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-ten-xanh-phan-1', 'Mũi Tên Xanh (Phần 1)', 'Arrow (Season 1)', 'https://phimimg.com/upload/vod/20231207-1/878bd31c07705993492dbcf1a4f5080a.jpg', 'https://phimimg.com/upload/vod/20231207-1/442878ab7f3917ecd25618d2be84e5ea.jpg', '<p>Sau một vụ đắm tàu nghiêm trọng, chàng tỉ phú ăn chơi có tiếng của thành phố Starling - Oliver Queen mất tích và không có hy vọng sống sót. Năm năm sau, anh bất ngờ xuất hiện trên một hòn đảo xa xôi ở Thái Bình Dương. Trở về nhà, tất cả người thân không nhận ra được bên trong Oliver đã có một sự đổi thay mạnh mẽ, trừ một người là mẹ của anh - Moira.Ban ngày, Oliver đóng vai chính bản thân khi xưa - một tay ăn chơi tán gái giàu có, vô tâm, luôn theo sát bên là tài xế kiêm vệ sĩ tận tụy - John Diggle và cô bạn gái Laurel Lance. Khi màn đêm xuống, thành phố Starling lại xuất hiện thêm một sứ giả công lý ngoài vòng pháp luật - The Green Arrow...</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Donnell","avatar":""},{"name":"Stephen Amell","avatar":""},{"name":"Willa Holland","avatar":""},{"name":"Katie Cassidy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324466);
