INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sofia-the-first-once-upon-a-princess', 'Sofia The First: Once Upon A Princess', 'Sofia The First: Once Upon A Princess', 'https://phimimg.com/upload/vod/20231208-1/5d0b70de76ed50e1ffce5263151ed36f.jpg', 'https://phimimg.com/upload/vod/20231208-1/4ec57c778d0a921e95f2cf0beec0914a.jpg', '<p>Sofia, là một cô bé với nền tảng của người bình thường cho đến khi mẹ cô kết hôn với nhà vua và đột nhiên cô là hoàng tộc. Với sự giúp đỡ của ba nàng tiên phụ trách Học viện Đào tạo Hoàng gia, Sofia biết rằng trông giống như một công chúa không khó khăn nhưng cư xử như người ta phải đến từ trái tim.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
