INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-dong-lan-dan', 'Long Đong Lận Đận', 'Floating City', 'https://phimimg.com/upload/vod/20231208-1/a59024703dd269ef8aecf864c6c0c8f9.jpg', 'https://phimimg.com/upload/vod/20231208-1/8c592ec7a616ae91886412743133b9eb.jpg', '<p>Floating City tái hiện câu chuyện có thật về cuộc đời thăng trầm và gian nan của một chàng ngư dân tại vùng sông nước nghèo khổ. Anh đã phải làm đủ mọi nghề để lập nghiệp và sau nhiều nỗ lực cuối cùng cũng trở thành một doanh nhân thành đạt...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Quách Phú Thành","avatar":""},{"name":"Hà Siêu Nghi","avatar":""},{"name":"Annie Liu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
