INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gang-to-vo-danh', 'Găng Tơ Vô Danh', 'Nameless Gangster', 'https://phimimg.com/upload/vod/20231208-1/95a0719e6cf740c6803f4b60c172504e.jpg', 'https://phimimg.com/upload/vod/20231208-1/33702496e6c295f7118bd0d4834f95cf.jpg', '<p>Năm 1982, tại thành phố cảng Busan, nhân viên hải quan Choi Ik-hyeon đứng trước nguy cơ mất việc do bị quy tội tham nhũng. Lo gia đình không còn người nương tựa, Ik-hyeon đánh liều bán số ma tuý anh tình cờ phát hiện trong một nhà kho. Để móc nối làm ăn, Ik-hyeon tìm gặp Choi Hyeong-bae, một trùm giang hồ đầy thế lực có quan hệ với Yakuza (xã hội đen Nhật Bản). Run rủi thế nào mà Hyeong-bae lại chính là em họ xa của Ik-hyeon. Nhờ quan hệ họ hàng mà anh em nhà Choi nhanh chóng kết thành cặp bài trùng. Sự kết hợp giữa trí tuệ của Ik-hyeon và sức mạnh cơ bắp của Hyeong-bae tạo thành thứ vũ khí tối thượng, giúp hai người phất lên nhanh chóng trong thế giới tham nhũng và tội ác. Tuy nhiên, khi chính phủ quyết định tuyên chiến với tội phạm vào năm 1990, quan hệ giữa hai anh em dần xấu đi, lòng tin bắt đầu lung lay. Hai người chẳng từ thủ đoạn nào với nhau để tìm cách sinh tồn...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Min-sik Choi","avatar":""},{"name":"Jung-woo Ha","avatar":""},{"name":"Peter Cavnoudias","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
