INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('5-ngay-chien-tran', '5 Ngày Chiến Trận', '5 Days Of War', 'https://phimimg.com/upload/vod/20231208-1/7928c1291bf0a5b16163f61b665d5dba.jpg', 'https://phimimg.com/upload/vod/20231208-1/6fad9d486039a1296057f7562e773406.jpg', '<p>Bộ phim này mô tả 5 ngày về cuộc chiến giả tưởng 5 ngày của đất nước Nga và nam Ossetia. Cuộc chiến đơn thuần là cuộc tranh chấp về lãnh thổ cũng như tài nguyên. Khi đó có 1 nhóm phóng viên Mỹ đã quay được các cảnh này diễn ra giữa quân của 2 bên...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rupert Friend","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Richard Coyle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
