INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ky-dieu-2012', 'Điều Kỳ Diệu', 'To the Wonder', 'https://phimimg.com/upload/vod/20231206-1/aac65bbeef718d6fbe786b17c9ca91a7.jpg', 'https://phimimg.com/upload/vod/20231206-1/17fb6ad32579b0904565ca2d77ffcf25.jpg', '<p>Sau khi yêu nhau ở Paris, Marina và Neil đến Oklahoma, nơi nảy sinh nhiều vấn đề. Mục sư gốc Tây Ban Nha trong nhà thờ của họ đấu tranh với đức tin của mình, trong khi Neil gặp một người phụ nữ từ thời thơ ấu của anh.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Tatiana Chiline","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
