INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nguyen-cua-cha', 'Tâm Nguyện Của Cha', 'People Like Us', 'https://phimimg.com/upload/vod/20231206-1/b304315f2f43b5ae51a4a8c705ed725a.jpg', 'https://phimimg.com/upload/vod/20231206-1/765aa084303dc84ab725c8a7e7d9a94d.jpg', '<p>Bộ phim kể về câu truyện người con của nhà buôn bán bất động sản lớn, sau khi nghe tin bố mất, anh vội vã chạy về nhà và đọc bản di chúc do cha mình để lại. Trong đó, anh được thừa hưởng hết tài sản do ông để lại nhưng với điều kiện là anh phải tìm đến một gia đình mà ông gọi là căn nhà thứ hai của anh. Từ đó, những bí mật về cuộc đời người cha dần dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Mark Duplass","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
