INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-reo-goi', 'Tử Thần Réo Gọi', 'Hit and Run', 'https://phimimg.com/upload/vod/20231206-1/f386b3c71036a070925ce672024689f5.jpg', 'https://phimimg.com/upload/vod/20231206-1/f019fc6f8df67608c455666358628aa3.jpg', '<p>Một tài xế đào tẩu trước đây trốn thoát khỏi Chương Trình Bảo Vệ Nhân Chứng để đưa cô bạn gái đến Los Angeles để cô nàng có thể nhận được công việc mơ ước. Chuyến đi của họ bỗng trở nên đầy rắc rối khi bị FBI truy đuổi, và nguy hiểm khôn lường khi đồng đảng tội phạm cũ của Charlie bất thần xuất hiện...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dax Shepard","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Bradley Cooper","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
