INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-san-duoi', 'Cuộc Săn Đuổi', 'The Hunt', 'https://phimimg.com/upload/vod/20231206-1/5333b8f5213eacccf5d9f88ce8a71e73.jpg', 'https://phimimg.com/upload/vod/20231206-1/4ed1743808b6eac947165c289258c8c1.jpg', '<p>Lucas (Mads Mikkelsen) sống trong một cộng đồng nhỏ nơi mà ai cũng biết nhau. Anh có cuộc sống cá nhân gặp nhiều rắc rối, ly dị vợ, không được chăm sóc con trai. Anh làm việc tại một nhà trẻ của thị trấn, được mọi người quý mến vì tính tình hòa đồng. Một lần, người bạn thân nhất của anh nhờ đón con gái Klara (Annika Wedderkopp) từ nhà trẻ về nhà. Sau đó, Klara giống như phải lòng Lucas. Nhận biết được tình cảm khác lạ của cô bé, anh đã khuyên bảo và không đồng tình với cách làm của Klara. Giận dữ cô bé đã kể một câu chuyện bịa cho giám đốc của nhà trẻ rằng Lucas đã “khoe của quý” trước mặt mình. Đây là một lời cáo buộc vô cùng nghiêm trọng khi Klara chỉ là một đứa trẻ, sự việc này buộc Lucas vào tội lạm dụng tình dục trẻ em. Lucas dần bị mọi người căm ghét, ruồng bỏ, bản thân anh không hiểu tình huống mà mình gặp phải, đến khi biết thì không có cách nào có thể chứng minh được sự vô tội của mình.....</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Mads Mikkelsen","avatar":""},{"name":"Thomas Bo Larsen","avatar":""},{"name":"Annika Wedderkopp","avatar":""},{"name":"Lasse Fogelstrøm","avatar":""},{"name":"Susse Wold","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
