INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('skyfall', 'Skyfall', 'Skyfall', 'https://phimimg.com/upload/vod/20231204-1/bc797d73aa51c633d698e044b3602aca.jpg', 'https://phimimg.com/upload/vod/20231204-1/e6e59db2a0177e80d9132ea04b4e0a94.jpg', '<p>Khi nhiệm vụ mới nhất của James Bond (Daniel Craig) diễn ra nghiêm trọng và các đại lý trên khắp thế giới được tiếp xúc, Mi6 bị tấn công, buộc (M Dame Judi Dench) để di dời cơ quan. Những sự kiện này khiến quyền lực và vị trí của cô bị thách thức bởi Gareth Mallory (Ralph Fiennes), Chủ tịch mới của Ủy ban Tình báo và An ninh. Với Mi6 bây giờ bị xâm phạm từ cả trong và ngoài, M còn lại với một đồng minh, cô ấy có thể tin tưởng: trái phiếu. 007 Đưa đến bóng tối, chỉ được hỗ trợ bởi đại lý thực địa, Miss Eve Moneypenny (Naomie Harris), sau một con đường mòn đến Tiago Rodriguez bí ẩn, A.K.A. Raoul Silva (Javier Bardem), người có động cơ gây chết người và ẩn giấu vẫn chưa tiết lộ chính mình</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324466);
