INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-de-song', 'Học Để Sống', 'Get the Gringo', 'https://phimimg.com/upload/vod/20231204-1/72c612ce75173a5b4cb89da0c84d8777.jpg', 'https://phimimg.com/upload/vod/20231204-1/b03175dcf8386d8c0364a3218e58b3dd.jpg', '<p>Một công dân Mỹ bị bắt vì tội cướp tiền và sau đó ông được đưa vào nhà tù Mexico nơi cai trị của tên trùm khùng bố Javi và các tên cảnh sát tham nhũng,. Tại đây ông phải học cách tồn tại và trốn thoát ra khỏi nhà tù với sự giúp đõ của cậu bé 9 tuổi.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Kevin Hernandez","avatar":""},{"name":"Daniel Giménez Cacho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
