INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-lang-thap-tam-thoa', 'Kim Lăng Thập Tam Thoa', 'The Flowers of War', 'https://phimimg.com/upload/vod/20231204-1/df7ad44db4d3de9245e0ea03fd41dddb.jpg', 'https://phimimg.com/upload/vod/20231204-1/ab8f907744f55997194f9d808ba725cb.jpg', '<p>The Flowers Of War dựa trên sự kiện cuộc Đại thảm sát ở Nam Kinh năm 1937 khi quân Nhật chiếm đóng Trung Quốc. Câu chuyện về 13 cô kỹ nữ ở bên sông Tần Hoài, 6 chàng binh sỹ thoát ra khỏi đống tử thi, những khuê nữ con nhà quyền quý và một vài vị linh mục, những người còn sót lại sau cuộc chiến thảm khốc, cùng trú ngụ trong một giáo đường, và họ tiếp tục phải đối mặt với cuộc đại thảm sát lịch sử...</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Ni Ni","avatar":""},{"name":"Xinyi Zhang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324466);
