INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-hoan-hao', 'Vỏ Bọc Hoàn Hảo', 'Cleanskin', 'https://phimimg.com/upload/vod/20231204-1/12c1b935d4fa5fb452ba96a30ac21493.jpg', 'https://phimimg.com/upload/vod/20231204-1/362ffd97fe0529c6df96fca8744925c7.jpg', '<p>Ewan là một nhân viên mật vụ, anh phải đối mặt với một nhiệm vụ vô cùng khó khăn và nguy hiểm. Đó là theo dõi và tiêu diệt kẻ đánh bom cảm tử Ash cùng với tổ chức khủng bố của hắn. Trong khi đó, Ash đang phải vật lộn với lương tâm. Điều này thể hiện rõ nét trên những hoạt động khủng bố của anh ta. Ewan sẽ vượt qua nhiệm vụ này như thế nào? Bạn sẽ có câu trả lời ngay sau khi xem hết bộ phim này.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Abhin Galeya","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
