INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-the-princess-the-popstar', 'Barbie: The Princess & the Popstar', 'Barbie: The Princess & the Popstar', 'https://phimimg.com/upload/vod/20231203-1/a0ed5beb3a310671b9a2b80d938727c1.jpg', 'https://phimimg.com/upload/vod/20231203-1/032e0e4569d381055c3ee813145c4ad1.jpg', '<p>Barbie vào vai nàng công chúa thích hát và nhảy hơn là làm một nhân vật hoàng gia. Khi một ngôi sao nhạc pop nổi tiếng đến vương quốc, họ quyết định hoán đổi thân phận.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kelly Sheridan","avatar":""},{"name":"Jennifer Waris","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Tiffany Kathryn","avatar":""},{"name":"Ellie King","avatar":""},{"name":"Peter Kelamis","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"Allison Warnyca","avatar":""},{"name":"Christopher Gaze","avatar":""},{"name":"Lauren Lavoie","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324466);
