INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-kim-dai-kiep-an', 'Hoàng Kim Đại Kiếp Án', 'Guns N'' Roses', 'https://phimimg.com/upload/vod/20231214-1/ca7c95d8ffda24422c1c918a46fb5129.jpg', 'https://phimimg.com/upload/vod/20231214-1/37a501b202a6bc64a05b2c10faee2209.jpg', '<p>Phim kể về vùng đông bắc Trung Quốc thời kỳ bị Nhật đô hộ, đã lập nên nước Mãn Châu, trong vùng có 1 anh chàng du thủ du thực tên Tiểu Đông Bắc, hàng ngày hành nghề trộm cắp kiếm ăn, những tưởng sẽ sống thế cả đời, nhưng không ngờ anh chàng lại dính vào cuộc đấu tranh của hội cứu quốc và quân Nhật, hội cứu quốc muốn cướp 8 tấn vàng của quân Nhật dùng để mua vũ khí và Tiểu Đông Bắc vô tình biết được bí mật này, liệu rồi vàng sẽ về tay ai...</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuanyuan Cheng","avatar":""},{"name":"Wei Fan","avatar":""},{"name":"Tao Guo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
