INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-song', 'Mồi Sống', 'Bait', 'https://phimimg.com/upload/vod/20231205-1/a9ebd698eb25f0b0c1879efbdad02264.jpg', 'https://phimimg.com/upload/vod/20231205-1/f4de82fbfcbaf943392c896031239734.jpg', '<p>Một cơn sóng thần đã tấn công vào thành phố biển xinh đẹp, và tràn vào khu mua sắm ven biển bên trong tòa nhà Australia. Mọi người bị mắc kẹt bên trong khu mua sắm khi bên dưới luôn bị rình rập bởi loài cá mập trắng hung tợn...</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Richard Brancatisano","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Chris Betts","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
