INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('moi-song', 'Mồi Sống', 'Bait', 'mồi sống bait richard brancatisano xavier samuel chris betts ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robot-va-frank', 'Robot và Frank', 'Robot & Frank', 'https://phimimg.com/upload/vod/20231205-1/33863d97e0b64333ee5aeffd0d47ee32.jpg', 'https://phimimg.com/upload/vod/20231205-1/ad986d9d41c10c8fe946f352f685eebc.jpg', '<p>Frank già khó tính sống một mình. Thói quen của anh ấy bao gồm các chuyến thăm hàng ngày đến thư viện địa phương của anh ấy, nơi anh ấy có một ánh mắt lấp lánh dành cho thủ thư. Những đứa con lớn của ông quan tâm đến sức khỏe của cha chúng và mua cho ông một người máy chăm sóc. Ban đầu phản đối ý tưởng này, Frank nhanh chóng đánh giá cao những lợi ích của sự hỗ trợ của rô bốt - như những bữa ăn bổ dưỡng và một ngôi nhà sạch sẽ - và cuối cùng bắt đầu coi rô bốt của mình như một người bạn đồng hành thực sự. Với sự trợ giúp của người máy, niềm đam mê của Frank đối với nghề nghiệp cũ, bất hợp pháp của mình được khơi dậy, dù tốt hay xấu.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Langella","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Peter Sarsgaard","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
