INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-rong', 'Mắt Rồng', 'Dragon Eyes', 'https://phimimg.com/upload/vod/20231204-1/9c34463140ea5a3629ac0dc492d79fac.jpg', 'https://phimimg.com/upload/vod/20231204-1/c390b0b3f04b6d7e4ec109e939d5d822.jpg', '<p>Một khu phố có tên St Jude Square những người dân ở đó phải sống trong lo âu sợ hãi bởi các băng nhóm xã hội đen trấn áp và không lấy được 1 ngày bình yên. Đúng lúc đó có 1 nhân vật bí ẩn xuất hiện và giúp người dân chống lại bọn chúng với võ thuật tuyệt đỉnh của mình...</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cung Le","avatar":""},{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Johnny Holmes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
