INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ty-phu-gap-nan', 'Tỷ Phú Gặp Nạn', 'Cosmopolis', 'https://phimimg.com/upload/vod/20231204-1/e4fb4c31df256030b3976a5092b87e83.jpg', 'https://phimimg.com/upload/vod/20231204-1/a39513adedf9ef3b0ff839af6d1cafac.jpg', '<p>Được chuyển thể từ tiểu thuyết cùng tên của nhà văn Don DeLillo, Cosmopolis là câu chuyện về một tỷ phú trẻ và cũng là phù thủy tài chính của nước Mỹ. Khi đi ngang qua khu Manhattan, anh định tới cắt tóc ở một cửa hàng quen nhưng chiếc xe sang trọng của anh bị mắc kẹt lại trên đường khi tổng thống tới thăm nơi đây. Cuộc tấn công của những kẻ vô chính phủ và đám tang của một rapper đã đưa đẩy câu chuyện theo một hướng khác…</p>', 'Full', 1, 'single', 'completed', 33, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Sarah Gadon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
