INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-trong-ngoi-nha', 'Bóng Ma Trong Ngôi Nhà', 'The Apparition', 'https://phimimg.com/upload/vod/20231204-1/f6650548059a7ac7c3033a17667b7bf6.jpg', 'https://phimimg.com/upload/vod/20231204-1/25068bccb86643a748b66d8ba257c814.jpg', '<p>Bị ám ảnh bởi những sự việc đáng sợ xảy ra trong nhà của họ, Kelly và Ben biết rằng thí nghiệm cận tâm lý học của một trường đại học đã tạo ra một thực thể hiện đang ám ảnh họ. Linh hồn độc ác nuôi dưỡng nỗi sợ hãi và hành hạ cặp đôi bất kể họ chạy đi đâu. Tuyệt vọng, Kelly và Ben tìm đến một nhà nghiên cứu hiện tượng huyền bí, nhưng ngay cả với sự trợ giúp của anh ta, có lẽ đã quá muộn để tự cứu mình khỏi sự hiện diện đáng sợ.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sebastian Stan","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Julianna Guill","avatar":""},{"name":"Luke Pasqualino","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
