INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham-ma-tuy', 'Tội Phạm Ma Túy', 'Pusher', 'https://phimimg.com/upload/vod/20231204-1/6daab580ddc289ae18406a7f74c93916.jpg', 'https://phimimg.com/upload/vod/20231204-1/cbf66fc403627c9d25f973d86ffb785f.jpg', '<p>Pusher là câu chuyện về Frank, một tên trùm buôn bán ma túy tại London. Khi công việc kinh doanh của anh đang thuận lợi thì cũng là lúc anh nhận ra được các khách hàng và đối tác của anh đang dần lừa gạt anh để chiếm đoạt số hàng và địa bàn kinh doanh của mình. Vậy Frank sẽ phải làm gì trước tình thế này?</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Richard Coyle","avatar":""},{"name":"Bronson Webb","avatar":""},{"name":"Agyness Deyn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324466);
