INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giac-ma-quai', 'Ảo Giác Ma Quái', 'A Fantastic Fear of Everything', 'https://phimimg.com/upload/vod/20231203-1/0ef2ba85dbab3f8db619af70b9498350.jpg', 'https://phimimg.com/upload/vod/20231203-1/c7c006abd2f0fb4ea9a4eee19792a955.jpg', '<p>Trong phim, Jack (Simon Pegg), sau một thời gian viết truyện cho trẻ em, cảm thấy chán nản và quyết định chuyển sang thể loại kinh dị u ám về những kẻ giết người hàng loạt. Tuy nhiên có vẻ như bản tính nhút nhát của anh không hợp lắm cho việc viết tiểu thuyết loại này, và thế là hàng loạt những ảo giác (hay thực) ma quái bắt đầu xảy đến với anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Paul Freeman","avatar":""},{"name":"Amara Karan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
