INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bel-ami', 'Bel Ami', 'Bel Ami', 'https://phimimg.com/upload/vod/20231203-1/3b2483b8ab1711a43366dd322961511a.jpg', 'https://phimimg.com/upload/vod/20231203-1/7103f86a40fa2fba91cbe9f6d9ba1e96.jpg', '<p>Georges Duroy du hành qua Paris những năm 1890, từ những chiếc gác xép đầy gián đến những thẩm mỹ viện sang trọng, sử dụng trí thông minh và khả năng quyến rũ của mình để vươn lên từ nghèo khó trở nên giàu có, từ vòng tay của gái điếm đến những cuộc hẹn hò say đắm với những người đẹp giàu có, trong một thế giới mà chính trị và truyền thông tranh giành ảnh hưởng , nơi tình dục là quyền lực và sự nổi tiếng là nỗi ám ảnh.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Philip Glenister","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Natalia Tena","avatar":""},{"name":"Anthony Higgins","avatar":""},{"name":"James Lance","avatar":""},{"name":"Thomas Arnold","avatar":""},{"name":"Timothy Walker","avatar":""},{"name":"Pip Torrens","avatar":""},{"name":"Christopher Fulford","avatar":""},{"name":"Amy Marston","avatar":""},{"name":"Eloise Webb","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
