INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-hoa-cuc-vang-nhiet-doi', 'Khách Sạn Hoa Cúc Vàng Nhiệt Đới', 'The Best Exotic Marigold Hotel', 'https://phimimg.com/upload/vod/20231202-1/f5dd96f6d427ccec70caa3c3e84d4a84.jpg', 'https://phimimg.com/upload/vod/20231202-1/b31aa435fd947dea7f73280c41f2ca28.jpg', '<p>The Best Exotic Marigold Hotel theo chân một nhóm ông bà lão người Anh ở tuổi nghỉ hưu quyết định &quot;cho thuê trọn gói&quot; thời nghỉ hưu của mình tại đất nước Ấn Độ ít tốn kém và kỳ thú. Bùi tai trước những màn quảng cáo về một khu khách sạn Hoa Vạn Thọ mới được tân trang và đắc ý trước viễn cảnh về một cuộc sống thoải mái, họ đã đến tận nơi và phát hiện ra tòa cung điện chỉ còn là một cái vỏ cũ kỹ. Mặc dù môi trường mới không được sang trọng như họ tưởng, cuối cùng họ đã trở thành những con người khác với những trải nghiệm kỳ thú và phát hiện ra rằng cuộc sống và tình yêu đều có thể bắt đầu lại khi bạn bỏ lại quá khứ đằng sau lưng...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Dev Patel","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Ronald Pickup","avatar":""},{"name":"Ramona Marquez","avatar":""},{"name":"Hugh Dickson","avatar":""},{"name":"Patrick Pearson","avatar":""},{"name":"Liza Tarbuck","avatar":""},{"name":"Tina Desai","avatar":""},{"name":"Lillete Dubey","avatar":""},{"name":"Lucy Robinson","avatar":""},{"name":"Sara Stewart","avatar":""},{"name":"Louise Brealey","avatar":""},{"name":"Richard Cubis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709