INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-kinh-di', 'Câu Chuyện Kinh Dị', 'Horror Stories', 'https://phimimg.com/upload/vod/20231202-1/ca702554f40b79ddf276988fce2d0052.jpg', 'https://phimimg.com/upload/vod/20231202-1/777fa53c73b354e76d41e7afbb8b564e.jpg', '<p>Một thiếu niên bị bắt cóc và buộc phải kể những câu chuyện đáng sợ nhất mà cô ấy biết, dẫn đến tuyển tập bốn câu chuyện này: anh chị em bị bao vây khi ở nhà một mình; một kẻ giết người thoát khỏi sự giam giữ của cảnh sát giữa chuyến bay; chị em kế phẫu thuật thẩm mỹ đến mức rùng rợn như ác mộng; một nhân viên y tế và người mẹ bế tắc vì cô con gái nhỏ bị nhiễm bệnh.</p>', 'Full', 1, 'single', 'completed', 5, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ji-won","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Kim Hyun-soo","avatar":""},{"name":"No Kang-min","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"No Hyeon-Hee","avatar":""},{"name":"Jin Tae-hyeon","avatar":""},{"name":"Choi Yoon-young","avatar":""},{"name":"Cha Jung-Won","avatar":""},{"name":"Kim Ki-chun","avatar":""},{"name":"Nam Bo-ra","avatar":""},{"name":"Jung Eun-chae","avatar":""},{"name":"Bae Soo-bin","avatar":""},{"name":"Na Young-hee","avatar":""},{"name":"Lim Sung-Min","avatar":""},{"name":"Lee Yoon-jeong","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Kim Ye-w","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
