INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-ky-si-bong-dem-tro-lai-phan-1', 'Người Dơi: Kỵ Sĩ Bóng Đêm Trở Lại, Phần 1', 'Batman: The Dark Knight Returns, Part 1', 'https://phimimg.com/upload/vod/20231202-1/2f54aa765727d6e091b99eec3c467e8d.jpg', 'https://phimimg.com/upload/vod/20231202-1/5f93453a81b0581c475cda0321f53d57.jpg', '<p>Đã một thập kỉ trôi qua kể từ lần cuối Bruce Wayne mặc trên mình bộ giáp batman, không chỉ mình anh mà nhiều siêu anh hùng khác đã bị ép buộc phải lui vào bóng tối. Chìm trong cơn hỗn loạn của &quot;Middle Age&quot;, Bruce Wayne không còn cách nào khách ngoài việc đắm mình trong rượu và những chiếc xe thể thao đắt tiền. Tuy vậy, anh vẫn luôn đau đớn khi nhìn cảnh thành phố Gotham thân yêu đang dần rơi vào tay của những băng đảng tội phạm giết người mang tên The Mutants. &nbsp;Tình hình còn nghiêm trọng hơn khi Harvey Dent (aka Two-Face) trở lại, buộc Wayne phải trở lại làm kị sĩ bóng đêm nhằm mang lại niềm hi vọng mới cho thành phố. Song hành cùng anh là một cô nàng tuổi teen Carrie - với biệt danh Robin. Cô bé này đã một lần cứu Batman khỏi một cuộc tấn công tàn độc của tên trùm băng Mutant. Với người đồng hành mới, mục đích đấu tranh mới, kẻ thù mới, Kị sĩ bóng đêm trở lại để bảo vệ Gotham khỏi những kẻ thù cả mới... và cũ.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Weller","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"David Selby","avatar":""},{"name":"Wade Williams","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Gary Anthony Sturgis","avatar":""},{"name":"Paget Brewster","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Maria Canals-Barrera","avatar":""},{"name":"Cathy Cavadini","avatar":""},{"name":"Townsend Coleman","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Gr","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
