INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-song-than', 'Thảm Họa Sóng Thần', 'The Impossible', 'https://phimimg.com/upload/vod/20231202-1/669d8ed8557ed52fb9ac32877b08a92a.jpg', 'https://phimimg.com/upload/vod/20231202-1/3b942dc1657643a487cf46cbe8391097.jpg', '<p>Maria và Henry cùng ba cậu con trai bắt đầu kỳ nghỉ ở Thái Lan, tìm kiếm vài ngày yên bình tại nơi thiên đường miền nhiệt đới này. Nhưng vào buổi sáng ngày 26/12, khi cả gia đình họ đang vui chơi quanh một bể bơi sau lễ Giáng Sinh vào đêm hôm trước, một tiếng gầm khủng khiếp rền vang từ trung tâm của trái đất.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Samuel Joslin","avatar":""},{"name":"Oaklee Pendergast","avatar":""},{"name":"Marta Etura","avatar":""},{"name":"Sönke Möhring","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Ploy Jindachote","avatar":""},{"name":"Jomjaoi Sae-Limh","avatar":""},{"name":"Johan Sundberg","avatar":""},{"name":"Jan Roland Sundberg","avatar":""},{"name":"La-Orng Thongruang","avatar":""},{"name":"Tor Klathaley","avatar":""},{"name":"Douglas Johansson","avatar":""},{"name":"Emilio","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
