INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay', 'Bậc Thầy', 'The Master', 'https://phimimg.com/upload/vod/20231201-1/6ee78ff2476ce87a519536a01fd45413.jpg', 'https://phimimg.com/upload/vod/20231201-1/15d148b0b4a0eee833f274fa95beb8ee.jpg', '<p>Năm 1952, sau Thế chiến thứ 2, Lancaster Dodd (Philip Seymour Hoffman) lập nên giáo pháo The Cause. Chỉ trong một thời gian ngắn, giáo phái này trở nên hùng mạnh, dương uy rộng khắp. Thế nhưng, đó cũng là lúc Freddie Quell (Joaquin Phoenix) - trợ thủ đắc lực của Lancaster Dodd bắt đầu tỏ ra nghi ngờ về mục đích của The Cause.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Ambyr Childers","avatar":""},{"name":"Madisen Beaty","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Patty McCormack","avatar":""},{"name":"Lena Endre","avatar":""},{"name":"Barbara Brownell","avatar":""},{"name":"Amy Ferguson","avatar":""},{"name":"Jennifer Neala Page","avatar":""},{"name":"Christopher Evan Welch","avatar":""},{"name":"Mik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
