INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-doi-nam-1942', 'Nạn Đói Năm 1942', 'Back to 1942', 'https://phimimg.com/upload/vod/20231201-1/17cfbc8e98ccf3ed5765c0796aaa8f0a.jpg', 'https://phimimg.com/upload/vod/20231201-1/f51b42c9903343fd4846c8ee7f7380c2.jpg', '<p>Năm 1942, tỉnh Hà Nam bị tàn phá bởi nạn đói bi thảm nhất trong lịch sử Trung Quốc hiện đại, khiến ít nhất ba triệu đàn ông, phụ nữ và trẻ em thiệt mạng. Mặc dù nguyên nhân chính của nạn đói là do hạn hán nghiêm trọng, nhưng nó càng trở nên trầm trọng hơn do châu chấu, bão gió, động đất, dịch bệnh và sự tham nhũng của chính quyền Quốc dân đảng cầm quyền.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Guoli","avatar":""},{"name":"Xu Fan","avatar":""},{"name":"Zhang Mo","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Chen Daoming","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Wang Ziwen","avatar":""},{"name":"Fan Wei","avatar":""},{"name":"Feng Yuanzheng","avatar":""},{"name":"Alec Su","avatar":""},{"name":"Li Xuejian","avatar":""},{"name":"Lü Zhong","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Ke Lan","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Alfred Hsing","avatar":""},{"name":"Zhang Shaohua","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Zhang Guoqiang","avatar":""},{"name":"Du Ch","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
