INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-hung', 'Truy Hùng', 'Fairy Tale Killer', 'https://phimimg.com/upload/vod/20231201-1/ed353fd69b2d4fc371a8f349e35cb545.jpg', 'https://phimimg.com/upload/vod/20231201-1/b60d08a9d84da5747e95099eb8230fbb.jpg', '<p>Truy Hùng - Fairy Tale Killer (2012) là phim Phim kể về 1 vụ giết người hàng loạt được thực hiện theo kiểu truyện cổ tích bởi 1 tên sát nhân biến thái do Vương Bảo Cường thủ vai. Lưu Thanh Vân vào vai 1 thanh tra truy lùng tên sát nhân biến thái đồng thời tìm hiểu bí mật về sự liên quan đến truyện cổ tích.</p>', 'Full', 1, 'single', 'completed', 6, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Elanne Kwong","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"James Ho Chung-Hung","avatar":""},{"name":"Gary Chiu Cheun-Sing","avatar":""},{"name":"Kelly Fu","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Ciwi Lam","avatar":""},{"name":"Joey Man Yee-Man","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
