INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tinh-nghi', 'Kẻ Tình Nghi', 'Bernie', 'https://phimimg.com/upload/vod/20231201-1/c6a9d10a62519a32646c4ed5573a7df3.jpg', 'https://phimimg.com/upload/vod/20231201-1/e5a7ef42b66ed72e193516611c8c2f44.jpg', '<p>Trong một thị trấn nhỏ, hẻo lánh ở Carthage, Texas, Bernie Tiede là một trong những cư dân đáng kính nhất của thị trấn. Anh ta dạy ở trường học Chủ Nhật, hát trong dàn đồng ca, và cũng không có gì ngạc nhiên khi anh làm bạn với Marjorie Nugent, một người góa phụ giàu có. Bernie thường xuyên đi lại với Marjorie và thậm chí là người đứng ra quản lý tài khoản ngân hàng cho bà ta... Thế nhưng người dân của Carthage đã thực sự sốc khi một ngày nọ người ta phát hiện ra Marjorie Nugent đã chết, và Bernir Tiede bị buộc tội giết người...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Black","avatar":""},{"name":"Shirley MacLaine","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Brady Coleman","avatar":""},{"name":"Richard Robichaux","avatar":""},{"name":"Rick Dial","avatar":""},{"name":"Brandon Smith","avatar":""},{"name":"Larry Jack Dotson","avatar":""},{"name":"Merrilee McCommas","avatar":""},{"name":"Mathew Greer","avatar":""},{"name":"Marjorie Dome","avatar":""},{"name":"Tim Cariker","avatar":""},{"name":"Fern Luker","avatar":""},{"name":"Jack Payne","avatar":""},{"name":"Sonny Carl Davis","avatar":""},{"name":"Chris Humphrey","avatar":""},{"name":"Jesse","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
