INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shadow-dancer', 'Shadow Dancer', 'Shadow Dancer', 'https://phimimg.com/upload/vod/20231201-1/95dee68213f71f7c91920ac5307fd553.jpg', 'https://phimimg.com/upload/vod/20231201-1/5ed3c3191605ec8d86f1de6e8c1c1426.jpg', '<p>Lấy bối cảnh ở Belfast những năm 1990, một người phụ nữ buộc phải phản bội tất cả những gì mình tin tưởng vì con trai mình.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Andrea Riseborough","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Brid Brennan","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Stuart Graham","avatar":""},{"name":"Martin McCann","avatar":""},{"name":"Maria Laird","avatar":""},{"name":"Barry Barnes","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Gary Lydon","avatar":""},{"name":"Daniel Tatarsky","avatar":""},{"name":"Tom Bennett","avatar":""},{"name":"Nicholas Asbury","avatar":""},{"name":"Morgan Wa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
