INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-bien-phong', 'Lính Biên Phòng', 'The Gatekeepers', 'https://phimimg.com/upload/vod/20231130-1/674a657fcd5131c23077a21c658e2190.jpg', 'https://phimimg.com/upload/vod/20231130-1/cdea7c62e5278ea342a5ff01eb787c72.jpg', '<p>Trong một loạt các cuộc phỏng vấn thẳng thắn và chưa từng có, sáu cựu lãnh đạo của Shin Bet - cơ quan tình báo và an ninh của Israel - nói về vai trò của họ trong chiến dịch chống khủng bố kéo dài hàng thập kỷ của Israel, thảo luận về các phương pháp gây tranh cãi của họ và liệu mục đích cuối cùng có biện minh cho phương tiện hay không. (TIFF)</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ami Ayalon","avatar":""},{"name":"Avraham Shalom","avatar":""},{"name":"Yaakov Peri","avatar":""},{"name":"Carmi Gillon","avatar":""},{"name":"Avi Dichter","avatar":""},{"name":"Yuval Diskin","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324466);
