INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-bien-phong', 'Lính Biên Phòng', 'The Gatekeepers', 'lính biên phòng the gatekeepers ami ayalon avraham shalom yaakov peri carmi gillon avi dichter yuval diskin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-truy-bo', 'Đại Truy Bổ', 'Nightfall', 'https://phimimg.com/upload/vod/20231130-1/627793f114dfbf6b877df197c28ea824.jpg', 'https://phimimg.com/upload/vod/20231130-1/70081c4c0fbb2a68e886a39b60d78e62.jpg', '<p>Bộ phim xoay quanh một vụ án tình, án trong án liên quan đến nhân vật Vương Viễn Dương (do Trương Gia Huy đóng). Hai mươi năm trước, Vương Viễn Dương lúc ấy 19 tuổi, bị buộc tội sát hại cô gái 18 tuổi tên là Y Vân và sau đó lãnh án chung thân. Thế nhưng anh được mãn hạn sớm và giờ đây đã trở về với cuộc sống bình thường. &nbsp;Vương Viễn Dương vô tình nhìn thấy một người giống với cô gái Y Vân ngày xưa, đó là một nghệ sĩ dương cầm tên là Từ Tuyết. Anh thường xuyên theo dõi cuộc sống của cô một cách lặng lẽ , phát hiện ra cô có một người cha đầy bạo lực, thường xuyên đánh đập và ép buộc cô làm theo ý mình. Ở phía bên kia, cảnh sát Lâm Chính Chung (do Nhậm Đạt Hoa đóng), người đang dành rất nhiều thời gian cho công việc để vơi bớt cú sốc sau khi vợ anh tự tử, cũng vì vậy anh hay bỏ bê cô con gái của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Kay Tse","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Candice Yu","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Jun Kung","avatar":""},{"name":"Tian Zhuangzhuang","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Ken Hung","avatar":""},{"name":"Cherry Ngan","avatar":""},{"name":"Cyrus Chow","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Hinson Chou","avatar":""},{"name":"Phat Cha","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324466);
