INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dont-worry-im-a-ghost', 'Don''t Worry, I''m a Ghost', 'Don''t Worry, I''m a Ghost', 'https://phimimg.com/upload/vod/20231130-1/64716b54febfdfc0e9f9e0ea63dbccc4.jpg', 'https://phimimg.com/upload/vod/20231130-1/3b81211cf62aa3669b31a838db96319a.jpg', '<p>Một chàng trai trẻ đã gặp tai nạn xe hơi và bây giờ bị mất trí nhớ đang bị một phụ nữ trẻ bị ám ảnh để cố gắng dẫn dắt anh ta để giải quyết vụ giết người của mình. Từ từ và một chút bởi một chút bộ nhớ của anh ta trở lại và với nó bi kịch xảy ra.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Shin-hye","avatar":""},{"name":"Bong Tae-gyu","avatar":""},{"name":"Lee Ha-yul","avatar":""},{"name":"Park Seo-yeon","avatar":""},{"name":"Kim Seung-wook","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324466);
