INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-than', 'Phân Thân', 'Holy Motors', 'https://phimimg.com/upload/vod/20231130-1/5d69bfa2ca12c9a5e7fdc783c5a71185.jpg', 'https://phimimg.com/upload/vod/20231130-1/519849e5d4316f412bf0b7687cc63509.jpg', '<p>Phân Thân xoay quanh một người đàn ông dị nhân tên Oscar. Từ sáng đến tối, một vài giờ trong cuộc sống của Monsieur Oscar, một người trong bóng tối cuộc hành trình từ đời này sang đời khác. Lần lượt ông ta đều trải qua, đội trưởng của ngành công nghiệp, sát thủ, người giàu có , người ăn xin, một tên quái vật , kẻ lập dị , người rừng , người của gia đình.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Denis Lavant","avatar":""},{"name":"Edith Scob","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Kylie Minogue","avatar":""},{"name":"Élise Lhomeau","avatar":""},{"name":"Jeanne Disson","avatar":""},{"name":"Michel Piccoli","avatar":""},{"name":"Leos Carax","avatar":""},{"name":"Nastya Golubeva Carax","avatar":""},{"name":"Reda Oumouzoune","avatar":""},{"name":"Zlata","avatar":""},{"name":"Geoffrey Carey","avatar":""},{"name":"Annabelle Dexter-Jones","avatar":""},{"name":"Élise Caron","avatar":""},{"name":"Corinne Yam","avatar":""},{"name":"Julien Prévost","avatar":""},{"name":"Ahcène Nini","avatar":""},{"name":"La","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324466);
