INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('caught-in-the-web', 'Caught in the Web', 'Caught in the Web', 'https://phimimg.com/upload/vod/20231130-1/cb6161d03df6767abe151a5ef1a89874.jpg', 'https://phimimg.com/upload/vod/20231130-1/9212e5cdaaac24d71514910545669aae.jpg', '<p>Câu chuyện về ba người phụ nữ có thế giới xung đột - một bài bình luận xã hội về xã hội &#39;âm thanh&#39; mà chúng ta đang trở thành, nơi nhận thức trở thành hiện thực và phán đoán dựa trên sự thật hạn chế nhanh chóng lan truyền, bất kể sự thật hay thiệt hại mà họ có thể gây ra.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Yuanyuan","avatar":""},{"name":"Mark Chao","avatar":""},{"name":"Chen Hong","avatar":""},{"name":"Wang Xueqi","avatar":""},{"name":"Yao Chen","avatar":""},{"name":"Loudan Wang","avatar":""},{"name":"Chen Ran","avatar":""},{"name":"Bao-hua Chang","avatar":""},{"name":"Yu Ailei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324466);
