INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-truong', 'Chiến Trường', 'Battleground', 'https://phimimg.com/upload/vod/20231129-1/4c340f0161b9b8980ec1461e49f01a9d.jpg', 'https://phimimg.com/upload/vod/20231129-1/73fe548fcfed502970773ace0ac256ff.jpg', '<p>Sáu tên cướp ngân hàng đang trên đường trốn chạy và bị mắc kẹt trong 1 khu rừng. Để tìm cách thoát khỏi khu rừng, họ đã bắt và giết tất cả mọi người khi đi vào rừng nhằm đe dọa không cho cảnh sát vào. Thật không may cho họ, Hugh Lambe là một cựu chiến binh sống ẩn mình trong rừng. Và mọi chuyện bắt đầu khi sáu tên cướp này muốn giết Hugh Lambe, và ông phải đối phó với 6 tên cướp này ra sao? Với kinh nghiệm của một lính thủy đánh bộ đã về hưu…</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Hugh Lambe","avatar":""},{"name":"Bryan Larkin","avatar":""},{"name":"Bob Cymbalski","avatar":""},{"name":"Robert Nolan","avatar":""},{"name":"Damon E. White","avatar":""},{"name":"Mark Munro","avatar":""},{"name":"Frank Ieraci","avatar":""},{"name":"Lee Sandford","avatar":""},{"name":"Bass Stewart","avatar":""},{"name":"Raman Zarafshan","avatar":""},{"name":"Ryan Borg","avatar":""},{"name":"Merella Fernandez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
