INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-me-2012', 'Tình Mê', 'The Second Woman', 'https://phimimg.com/upload/vod/20231116-1/8041ae7914b8aaf717c26c592b63b190.jpg', 'https://phimimg.com/upload/vod/20231116-1/b482ec1eab7e949e88d3c8c8457b141d.jpg', '<p>Tình Mê (The Second Woman) xoay quanh cặp chị em song sinh Tuệ Hương, Tuệ Bảo do Thư Kỳ thể hiện, cả hai đều có tình cảm với chàng diễn viên sân khấu Phương Dịch Nam (Dư Văn Lạc). Chính vì tranh nhau một người đàn ông, hai chị em đã trở mặt thành thù và quyết chiếm được người mình yêu. Vào một đêm sấm chớp, người chị đột nhiên mất tích và hàng loạt những hành động quái dị của người em gái càng khiến mọi chuyện càng trở nên rối rắm, dị thường...</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Chen Shu","avatar":""},{"name":"Niu Mengmeng","avatar":""},{"name":"Xi Meijuan","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
