INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-tho-2012', 'Khó Thở', 'Breathless', 'https://phimimg.com/upload/vod/20231115-1/b726eb51de7302cdc7936a32c3df765d.jpg', 'https://phimimg.com/upload/vod/20231115-1/fcde31ff511ab6bb3e25303dc92414fe.jpg', '<p>Buồn chán chồng của mình, Lorna và cô bạn quyết định tự chữa &quot;bệnh&quot; cho mình bằng rượu Tennessee whiskey. Nhưng quyết định đó lại dẫn họ đến một vấn đề rắc rối hơn. Khi cảnh sát trưởng Cooley hỏi một số câu hỏi rắc rối khiến mọi việc phát triển thành một câu chuyện trả thù và sống sót theo đúng kiểu Texas: táo bạo và tàn nhẫn...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gina Gershon","avatar":""},{"name":"Kelli Giddish","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Wayne Duvall","avatar":""},{"name":"Paul Cuneo","avatar":""},{"name":"Richard Riehle","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324466);
