INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-giao-2012', 'Chuyển Giao', 'The Tall Man', 'https://phimimg.com/upload/vod/20231103-1/2f5f7b0ae42da15657280ae9cee5f632.jpg', 'https://phimimg.com/upload/vod/20231103-1/a92bd217de288224f95501680dde6a3d.jpg', '<p>Thị trấn Cold Rock đang tàn lụi dần bởi việc khai thác mỏ, những đứa trẻ được sinh ra ngoài ý muốn và không được đến trường, biến cố xảy đến khi hàng loạt trẻ em mất tích mà không có dấu vết, người dân hoang mang cùng với những lời đồn đại rằng những đứa trẻ bị bắt cóc bởi một thực thể bí ẩn mà họ gọi là The Tall Man. Nữ y tá Julia Denning (Jessica Biel) không tin cho đến khi con trai cô David biến mất lúc nửa đêm. Lo lắng đi giải cứu đứa con, Julia một lần nữa sống lại trong cơn ác mộng đen tối nhất của những người làm cha mẹ.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jessica Biel","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Jakob Davies","avatar":""},{"name":"William B. Davis","avatar":""},{"name":"Samantha Ferris","avatar":""},{"name":"Colleen Wheeler","avatar":""},{"name":"Eve Harlow","avatar":""},{"name":"Janet Wright","avatar":""},{"name":"Ferne Downey","avatar":""},{"name":"John Mann","avatar":""},{"name":"Teach Grant","avatar":""},{"name":"Garwin Sanford","avatar":""},{"name":"Lucas Myers","avatar":""},{"name":"Pat Henman","avatar":""},{"name":"Katherine Ramdeen","avatar":""},{"name":"Jodi Sadowsky","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324466);
