INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-lai-tu-dau', 'Yêu Lại Từ Đầu', 'The Vow', 'https://phimimg.com/upload/vod/20230917-1/3d4cbd15c7cc6c746cafd458da47a47e.jpg', 'https://phimimg.com/upload/vod/20230917-1/5e05f17de7f076fa2e53d916c2905687.jpg', '<p><span style="font-family: ">The Vow nói về tình yêu của hai nhân vật Paige và Leo. Cả hai quyết định tổ chức đám cưới &quot;chui&quot; trong một viện bảo tàng để tiết kiệm chi phí. Tuy nhiên, khi họ đang tận hưởng những ngày hạnh phúc đầu tiên của cuộc sống hôn nhân thì một biến cố xảy ra. Tai nạn xe hơi thảm khốc đã cướp đi trí nhớ của Paige. Khi thức dậy trong bệnh viện, cô không còn nhớ Leo là ai mà chỉ nhớ được quãng thời gian trước khi gặp và yêu anh. Mọi chuyện trở nên phức tạp khi Paige quay về với người yêu cũ trước đây. Leo tự nhủ phải làm mọi cách để giành lại trái tim của vợ mình...</span></p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel McAdams","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Jessica Lange","avatar":""},{"name":"Tatiana Maslany","avatar":""},{"name":"Lucas Bryant","avatar":""},{"name":"Kristina Pesic","avatar":""},{"name":"Dillon Casey","avatar":""},{"name":"Wendy Crewson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324466);
