INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-kich-ngam-2012', 'Biệt Kích Ngầm', 'Act of Valor', 'https://phimimg.com/upload/vod/20231101-1/473dd6c07cdc9da1cf06f3fdb235d7f1.jpg', 'https://phimimg.com/upload/vod/20231101-1/3395d6e9c692ef4f478754d59c03402a.jpg', '<p>Khi đi giải cứu một nhân viên CIA bị bắt cóc, một biệt đội SEAL tình cờ khám phá ra một âm mưu khủng bố nhằm vào nước Mỹ. Kẻ chủ mưu lên kế hoạch tấn công hòng biến những tòa nhà chọc trời trở thành đống đổ nát. Để bảo vệ cuộc sống cho hàng trăm nghìn người dân vô tội, họ phải dấn thân vào nguy hiểm, thậm chí chấp nhận rời xa gia đình của mình mãi mãi để giữ trọn lời thề với quê hương.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Roselyn Sánchez","avatar":""},{"name":"Emilio Rivera","avatar":""},{"name":"Gonzalo Menendez","avatar":""},{"name":"Marissa Labog","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Alex Veadov","avatar":""},{"name":"Drea Castro","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Jason Cottle","avatar":""},{"name":"Alexander Asefa","avatar":""},{"name":"Jeffrey Barnachea","avatar":""},{"name":"Kenny Calderon","avatar":""},{"name":"Raul Canizales II","avatar":""},{"name":"Sam Cespedes","avatar":""},{"name":"Jimmy Chhiu","avatar":""},{"name":"Charles Chiyangwa","avatar":""},{"name":"Anton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324466);
