INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-song-con', 'Luật Sống Còn', 'The Gangster', 'https://phimimg.com/upload/vod/20231129-1/59e59897e34768c9e486e51eee5e2e84.jpg', 'https://phimimg.com/upload/vod/20231129-1/f8735a5c09839d71745fe9dfed861711.jpg', '<p>Ở Bangkok vào những năm 1950, Jod và Daeng là những gangster không hề biết sợ hãi, họ là thủ lãnh của những băng đảng đường phố được kính phục. Những năm trôi qua sống trong bạo lực, Jod dần rút khỏi giang hồ để nhường lại cho các đàn em quản lý... Tuy nhiên, sau khi anh em của anh ta bị sát hại trong các cuộc chiến giữa các băng đảng, anh đã trở lại và quyết trả thù...</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Krissada Sukosol Clapp","avatar":""},{"name":"Somchai Kemglad","avatar":""},{"name":"Sakarin Suthamsamai","avatar":""},{"name":"Krisada Supapprom","avatar":""},{"name":"Boonsong Nakphoo","avatar":""},{"name":"Pornchai Hongrattanaporn","avatar":""},{"name":"Wasu Sangsingkaew","avatar":""},{"name":"Pakchanok Wo-Onsri","avatar":""},{"name":"Nantharat Chaowarat","avatar":""},{"name":"Atthiwat Theeranithitnanth","avatar":""},{"name":"Danoo Chutinavee","avatar":""},{"name":"Suttasit Pottasak","avatar":""},{"name":"Preec","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324467);
