INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-thpt-dien-tu', 'Trường THPT Điện Tử', 'Video Game High School', 'https://phimimg.com/upload/vod/20231129-1/ca3aaac296eec0807a9692133dbe64d3.jpg', 'https://phimimg.com/upload/vod/20231129-1/6773e4b4d36373d51cb8686aea21ba88.jpg', '<p>Phim lấy bối cảnh ở một tương lai không xa, khi trò chơi điện tử trực tuyến trở thành môn thể thao cực kỳ phổ biến và cuốn hút khán giả bậc nhất trên thế giới. Brian D - chàng trai trẻ đam mê game sau cú xuất thần trong một trận đấu public đã được tuyển thẳng vào Video Game High School - trường Trung học Phổ thông Điện tử. Hãy cùng trải nghiệm những biến cố thăng trầm BrianD phải vượt qua cùng với những người bạn thân mới, tình yêu mới để trở thành một gamer chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Blaylock","avatar":""},{"name":"Johanna Braddy","avatar":""},{"name":"Jimmy Wong","avatar":""},{"name":"Ellary Porterfield","avatar":""},{"name":"Brian Firenzi","avatar":""},{"name":"Harley Morenstein","avatar":""},{"name":"Rocky Collins","avatar":""},{"name":"Benji Dolly","avatar":""},{"name":"Joel Kelley Dauten","avatar":""},{"name":"Freddie Wong","avatar":""},{"name":"Justine Ezarik","avatar":""},{"name":"Shira Lazar","avatar":""},{"name":"Leeanna Vamp","avatar":""},{"name":"Zachary Levi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324467);
