INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-ma-nhiem-xa', 'Thây Ma Nhiễm Xạ', 'Zombie 108', 'https://phimimg.com/upload/vod/20231129-1/3281c98c5d7d8b81e7b0064592d2618b.jpg', 'https://phimimg.com/upload/vod/20231129-1/ced91a52a9ba92773c4361c83edbe774.jpg', '<p>Một loại virus xâm nhập vào Quân đội Đài Bắc và các đội SWAT giám sát việc sơ tán nhưng ở Tây Môn Đình, các băng đảng không muốn cảnh sát. Họ tấn công quân đội nhưng khi cả hai thấy mình bị tấn công bởi thây ma thì có một liên minh khi họ cố gắng trốn thoát.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Yvonne Yao Cai-Ying","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Chu Mu-Yen","avatar":""},{"name":"Lena Lam","avatar":""},{"name":"Chie Jen-hao","avatar":""},{"name":"Liu Geng-Hong","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Morris Rong Xiang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324467);
