INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-dan-thich-khach', 'Viên Đạn Thích Khách', 'Assassin''s Bullet', 'https://phimimg.com/upload/vod/20231129-1/49cf24de1bb212fb3a234749c526d769.jpg', 'https://phimimg.com/upload/vod/20231129-1/f9dca57b7bb38e0800b1bbf1b3042bcd.jpg', '<p>Trong Assassin&#39;s Bullet, Slater đóng vai Robert Diggs, một đặc vụ đen đến làm việc cho Đại sứ Ashdown (ngôi sao của Hunger Games, Donald Sutherland), theo dõi một sát thủ cảnh giác ở Đông Âu. Sát thủ maverick (phụ nữ) đã hạ gục các mục tiêu nổi tiếng trong danh sách sát thủ của Hoa Kỳ, và Diggs phải tìm ra danh tính của kẻ giết người trước khi xảy ra một sự cố quốc tế. Trò chơi mèo vờn chuột thông thường diễn ra sau đó.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Slater","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Elika Portnoy","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Ivaylo Geraskov","avatar":""},{"name":"Ivan Kotsev","avatar":""},{"name":"Tanya Mickov","avatar":""},{"name":"Vassil Mihajlov","avatar":""},{"name":"Bashar Rahal","avatar":""},{"name":"Antoaneta Yordanova","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
