INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-bao', 'Quả Báo', 'Bad Karma', 'https://phimimg.com/upload/vod/20231208-1/4a8bd2f3fdcfded69b01d1d8c08b9338.jpg', 'https://phimimg.com/upload/vod/20231208-1/9dee96de6544486c4f38d1a0ac54ca75.jpg', '<p>Sau khi cận kề cái chết, người đàn ông muồn từ bỏ tất cả để trở lại cuộc sống bình thường, nhưng anh phải trả giá cho những gì mình đã làm trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":" Ray Liotta","avatar":""},{"name":"Aaron Pedersen","avatar":""},{"name":"Dominic Purcell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324467);
