INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-sadako', 'Lời Nguyền Sadako', 'Sadako 3D', 'https://phimimg.com/upload/vod/20231208-1/5ec4298dda7777103eea2186b29eefd8.jpg', 'https://phimimg.com/upload/vod/20231208-1/dbdde82ba0b303e2b99881a9d6aaee56.jpg', '<p>Trong phim Lời Nguyền Sadako, tại một trường trung học nơi Akana Aikawa đang giảng dạy lan truyền tin đồn về một cuốn băng kì quái. Cuốn băng trong phim hd này khiến cho những người xem nó có ý định tự sát.Ngay sau đó, một học sinh của Akane là Noriko đã tự tử. Và rồi hàng loạt những những cái chết đáng ngờ được phát hiện. Trong phim online này, phía cảnh sát kết luận rằng nguyên nhân của những cái chết này đều là tự sát mà bỏ lỡ mất một đầu mối quan trọng trong hàng loạt cái chết của những học sinh này. Đó là họ đều đã xem một cuốn băng trước khi chết. Cốt truyện của phim Lời Nguyền Sadako có phần giống với Ringu, ai đã từng rợn tóc gáy khi xem Ringu khó có thể bỏ qua Sadako. Kính mời các bạn cùng xem phim online này!</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Hashimoto","avatar":""},{"name":"Satomi Ishihara","avatar":""},{"name":"Kôji Seto","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
