INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-nhu-da-yeu', 'Dường Như Đã Yêu', 'Like Someone in Love', 'https://phimimg.com/upload/vod/20231129-1/bf2778b59fe6b8d97dc3b932bf11252f.jpg', 'https://phimimg.com/upload/vod/20231129-1/9dc50c09b0430256a0c2968a659f6bd5.jpg', '<p>Phim kể về mối quan hệ tuy ngắn ngủi nhưng hàm chứa quá nhiều điều cần suy nghĩ. Akiko - Nữ sinh viên xinh đẹp ngoài giờ học thì kiêm thêm nghề gái gọi. Takashi - Lão Giáo sư đã hưu và cô đơn. 1 lần Takashi gọi Akiko đến (lão già lắm rồi, chỉ muốn tâm sự thôi), và tình cảm bộc phát giữa 2 người. Những mở đầu bất an thường báo hiệu rằng cái kết là một bờ vực chông chênh.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Rin Takanashi","avatar":""},{"name":"Tadashi Okuno","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Denden","avatar":""},{"name":"Tomoaki Tatsumi","avatar":""},{"name":"Mihoko Suzuki","avatar":""},{"name":"Kaneko Kubota","avatar":""},{"name":"Reiko Mori","avatar":""},{"name":"Seina Kasugai","avatar":""},{"name":"Koichi Ohori","avatar":""},{"name":"Tomoaki Tatsumi","avatar":""},{"name":"Ryota Nakanishi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
