INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-chan-de', 'Gã Chăn Dê', 'Goats', 'https://phimimg.com/upload/vod/20231129-1/7b79c3c14e114bbf4e2849ff8a8e7195.jpg', 'https://phimimg.com/upload/vod/20231129-1/1bd8d3aa776ec1a32114bf98d74f2b7e.jpg', '<p>Có một người mẹ Thời đại mới chỉ quan tâm đến bản thân và một người cha ghẻ lạnh có nghĩa là cậu bé 15 tuổi Ellis Whitman đã lớn lên dựa vào một người giám hộ khác thường: một nhà hiền triết chuyên chăn dê, trồng cần sa tên là &#39;Người đàn ông dê&#39;. Khi Ellis quyết định rời bỏ những cách thay thế của ngôi nhà sa mạc của mình để đến một trường dự bị ngột ngạt ở Bờ Đông, những thay đổi lớn sắp xảy ra.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Duchovny","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Graham Phillips","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Justin Kirk","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Dakota Johnson","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Olga Segura","avatar":""},{"name":"Nicholas Lobue","avatar":""},{"name":"Ronnie Rubalcaba","avatar":""},{"name":"Tommee May","avatar":""},{"name":"Musashi Alexander","avatar":""},{"name":"Ana Auther","avatar":""},{"name":"Geoff Ellsworth","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
