INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ranh-pham-toi', 'Lằn Ranh Phạm Tội', 'The Aggression Scale', 'https://phimimg.com/upload/vod/20231128-1/b4f8e46b9fd19560e2e600d210216b74.jpg', 'https://phimimg.com/upload/vod/20231128-1/bc69e73cb451432f1da56ba41fd0b859.jpg', '<p>Phim Lằn Ranh Phạm Tội, khi ra bảo lãnh Bellavance, ông chủ phát hiện ra rằng $ 500,000 tiền của mình bị mất, ông sẽ gửi bốn người đàn ông tấn công Hardcore để gửi một tin nhắn áp lực cho các gia đình những tên trộm bị nghi ngờ... Nhưng khi những kẻ giết người trong phim này xâm nhập vào nhà Rutledge, thật không may cho họ khi gặp phải Owen. Owen có một tiền sự của hành vi bạo lực, biết làm thế nào để làm bẫy chết người và để dạy cho những tên côn đồ này, một số bài học chết người cực kỳ trong báo thù.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Wise","avatar":""},{"name":"Dana Ashbrook","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Jacob Reynolds","avatar":""},{"name":"Lisa Rotondi","avatar":""},{"name":"Fabianne Therese","avatar":""},{"name":"Boyd Kestner","avatar":""},{"name":"Joseph McKelheer","avatar":""},{"name":"Ryan Hartwig","avatar":""},{"name":"Jill Burress","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
