INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-sat-thu', 'Truy Lùng Sát Thủ', 'One in the Chamber', 'https://phimimg.com/upload/vod/20231128-1/4439bc393b2558565aa37fbdda6df727.jpg', 'https://phimimg.com/upload/vod/20231128-1/1fc2da87337d0ea8db52b243424010e3.jpg', '<p>Bối cảnh phim &quot;One in the chamber&quot; là cuộc chiến mafia ở châu Âu. Sau sự sụp đổ của chủ nghĩa Cộng sản, bọn tội phạm từ Mỹ đã nhận thấy châu Âu là một mảnh đất màu mỡ nên đã nhanh chóng tràn qua. Những kẻ buôn bán vũ khí và ma túy đã biến Prague thành hang ổ của chúng. Ray Carver là một sát thủ chuyên nghiệp làm việc cho cả hai băng đảng đối thủ trong một cuộc chiến mafia ở Nga. Carver đã bị truy đuổi khi cố ám sát tên trùm thuốc phiện Chechen. Cùng lúc đó, mafia Suverov thuê Alexey Andreev &quot;The Wolf&quot; -một sát thủ được cho là không có thật của Nga - thủ tiêu Carver. Cuộc chiến tranh băng đảng thực sự bắt đầu… &quot;One in the chamber&quot; là bộ phim có chủ đề tội phạm của đạo diễn William Kaufman, do Cuba Gooding Jr và Dolph Lundgren thủ vai chính. Với những màn truy đuổi và giao đấu quyết liệt trong thế giới ngầm của xã hội đen, One in the chamber sẽ không khiến người xem thất vọng về một bộ phim hành động hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Leo Gregory","avatar":""},{"name":"Billy Murray","avatar":""},{"name":"Claudia Bassols","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Slavi Slavov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
