INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('helpless', 'Helpless', 'Helpless', 'https://phimimg.com/upload/vod/20231128-1/25d00990bf49754565158c43f3b31ea6.jpg', 'https://phimimg.com/upload/vod/20231128-1/f4c7e82f5569346d586299b459b5681f.jpg', '<p>Một người đàn ông tìm kiếm vị hôn thê của mình, người đã biến mất mà không có dấu vết ngay trước lễ cưới của họ, chỉ để khám phá danh tính gây sốc của cô.</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Min-hee","avatar":""},{"name":"Lee Sun-kyun","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Song Ha-yoon","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Choi Il-hwa","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Yang Eun-yong","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Cha Soo-yeon","avatar":""},{"name":"Im Ji-gyu","avatar":""},{"name":"Min Sung-wook","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Kim Do-young","avatar":""},{"name":"Shin Yeon-sook","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
