INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-yen', 'Huyết Yến', 'The Last Supper', 'https://phimimg.com/upload/vod/20231127-1/da756613b54b63d9c4e0e55f2a426033.jpg', 'https://phimimg.com/upload/vod/20231127-1/f98996984a079d2dbf3341593367a4e7.jpg', '<p>The Last Supper lấy đề tài cuộc đối đầu hai nước Hán – Sở của Trung Hoa cổ đại, phim tái hiện lại buổi dạ yến lịch sử vào năm 206 trước Công Nguyên. Trong buổi dạ yến, Tây Sở Bá Vương – Hạng Vũ – tìm mọi cách để giết chết kình địch Lưu Bang.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Ye","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Qin Lan","avatar":""},{"name":"Sha Yi","avatar":""},{"name":"Nie Yuan","avatar":""},{"name":"Huo Si-Yan","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Tao Zeru","avatar":""},{"name":"Li Qi","avatar":""},{"name":"Qi Dao","avatar":""},{"name":"Hao Bojie","avatar":""},{"name":"Zhao Xiang","avatar":""},{"name":"Lü Yulai","avatar":""},{"name":"Liu Wei","avatar":""},{"name":"Han Zhang","avatar":""},{"name":"Liang Zhao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324467);
