INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-mong', 'Huyền Mộng', 'Imaginaerum', 'https://phimimg.com/upload/vod/20231129-1/eef72dd120dd9c2607b5b8b4b3fd8fa1.jpg', 'https://phimimg.com/upload/vod/20231129-1/ed61bfb9a4cddf9fc725ae497768ceb2.jpg', '<p>Imaginaerum kể câu chuyện về một nhà soạn nhạc lớn tuổi, Tom, người mắc chứng mất trí nhớ nghiêm trọng. Vì mắc bệnh trong nhiều năm và đã thoái lui về thời thơ ấu, anh ấy hầu như không nhớ gì về cuộc sống trưởng thành của mình. Âm nhạc, bạn bè, tất cả quá khứ của anh ấy bao gồm cả ký ức về con gái anh ấy đều mờ ảo trong tâm trí mong manh của anh ấy. Tất cả những gì anh ấy còn lại là trí tưởng tượng của một cậu bé mười tuổi. Khi anh chìm vào hôn mê, dường như không thể lấy lại những gì anh đã mất. Hoặc là nó?</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Phần Lan', 0, '[{"name":"Marianne Farley","avatar":""},{"name":"Quinn Lord","avatar":""},{"name":"Francis X. McCarthy","avatar":""},{"name":"Tuomas Holopainen","avatar":""},{"name":"Ilkka Villi","avatar":""},{"name":"Marco Hietala","avatar":""},{"name":"Anette Olzon","avatar":""},{"name":"Emppu Vuorinen","avatar":""},{"name":"Jukka Nevalainen","avatar":""},{"name":"Ron Lea","avatar":""},{"name":"Stéphane Demers","avatar":""},{"name":"Madison McAleer","avatar":""},{"name":"Joanna Noyes","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
