INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-chu-rua-sammy-2-thoat-khoi-thien-duong', 'Cuộc Phiêu Lưu Của Chú Rùa Sammy 2: Thoát Khỏi Thiên Đường', 'A Turtle''s Tale 2: Sammy''s Escape from Paradise', 'https://phimimg.com/upload/vod/20231129-1/4d59391ed2cd2dddabe16011c51fd58f.jpg', 'https://phimimg.com/upload/vod/20231129-1/67827e27cf15500f052ba0e8acb65fc2.jpg', '<p>Sammy và Ray, rùa da và những người bạn mãi mãi, đang tận hưởng nước và cát của đảo san hô, chăn dắt những chú rùa con mới nở Ricky và Ella ra biển. Đột nhiên, một kẻ săn trộm đột nhập và đưa chúng đi để tham gia một buổi trình diễn thủy cung ngoạn mục dành cho khách du lịch ở Dubai. Ông trùm của nơi này, chú cá ngựa Big D, lôi kéo họ vào kế hoạch trốn thoát tuyệt vời của mình. Nhưng cùng với những người bạn mới Jimbo, chú cá đốm mắt bọ và chú tôm hùm nhanh nhẹn Lulu, chú bạch tuộc ngọt ngào Annabel và cả một gia đình chim cánh cụt, Sammy và Ray đã ấp ủ những kế hoạch đột phá của riêng mình. Đó là lúc cô bé Ricky và Ella đến, quyết tâm đột nhập để giải cứu họ. Sau một loạt các cuộc phiêu lưu ly kỳ và những cuộc trốn thoát trong gang tấc, các anh hùng của chúng ta tiến về phía nam để gặp Shelly, tình yêu đầu tiên và duy nhất của Sammy.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Kaitlyn Maher","avatar":""},{"name":"Carter Hastings","avatar":""},{"name":"Alan Shearman","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Joe J. Thomas","avatar":""},{"name":"Jeff Dunham","avatar":""},{"name":"Dino Andrade","avatar":""},{"name":"April Stewart","avatar":""},{"name":"Chris Andrew Ciulla","avatar":""},{"name":"Terri Douglas","avatar":""},{"name":"John Kassir","avatar":""},{"name":"Joey D''Auria","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Cinda Adams","avatar":""},{"name":"Lex Lang","avatar":""},{"name":"Cam Clar","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324467);
