INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phieu-luu-cua-chu-rua-sammy-2-thoat-khoi-thien-duong', 'Cuộc Phiêu Lưu Của Chú Rùa Sammy 2: Thoát Khỏi Thiên Đường', 'A Turtle''s Tale 2: Sammy''s Escape from Paradise', 'cuộc phiêu lưu của chú rùa sammy 2: thoát khỏi thiên đường a turtle''s tale 2: sammy''s escape from paradise kaitlyn maher carter hastings alan shearman khary payton carlos alazraqui joe j. thomas jeff dunham dino andrade april stewart chris andrew ciulla terri douglas john kassir joey d''auria robin atkin downes cinda adams lex lang cam clar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-catwalk', 'Đặc Vụ Catwalk', 'Runway Cop', 'https://phimimg.com/upload/vod/20231129-1/5ad416d278b76a36bdf740b16e8540c5.jpg', 'https://phimimg.com/upload/vod/20231129-1/a1c7f0250a20cc7aea92a6aeae236f3a.jpg', '<p>Runway Cop là một bộ phim hài hành động của Hàn Quốc năm 2012, với sự tham gia của Kang Ji-hwan và Sung Yu-ri và do Shin Tae-ra đạo diễn. Nó kể câu chuyện về một thám tử quá khích và thừa cân Cha Cheol-soo, người được bí mật làm người mẫu thời trang để giải quyết một vụ án.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Ji-hwan","avatar":""},{"name":"Sung Yu-ri","avatar":""},{"name":"Lee Soo-hyuk","avatar":""},{"name":"Kim Young-kwang","avatar":""},{"name":"Shin Min-chul","avatar":""},{"name":"Shin Jung-geun","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Park Jeong-hak","avatar":""},{"name":"Lee Dae-jin","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Kim Jung-pal","avatar":""},{"name":"Choe Yoon-seul","avatar":""},{"name":"Heo Myeong-haeng","avatar":""},{"name":"Kim Woo-bin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
