INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-catwalk', 'Đặc Vụ Catwalk', 'Runway Cop', 'đặc vụ catwalk runway cop kang ji-hwan sung yu-ri lee soo-hyuk kim young-kwang shin min-chul shin jung-geun lee hee-jun kim ji-young park bo-gum ra mi-ran park jeong-hak lee dae-jin choi gwi-hwa kim jung-pal choe yoon-seul heo myeong-haeng kim woo-bin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-an-choi', 'Mật Vụ Ăn Chơi', 'Agent Vinod', 'https://phimimg.com/upload/vod/20231129-1/41e8e6ac115cd82ba700cec6d9606319.jpg', 'https://phimimg.com/upload/vod/20231129-1/2108997edfc965f24c42b108fa35ef79.jpg', '<p>Tại Khyber Pakhtunkhua của Pakistan, Đặc vụ RAW Vinod (Saif Ali Khan) được đồng nghiệp Rajan (Ravi Kishan) giải cứu khỏi tay một sĩ quan quân đội Pakistan bất hảo (Shahbaz Khan). Ở Nga/Uzbekistan, một cựu sĩ quan KGB bị tra tấn và sát hại. Tại Cape Town, một nhóm các ông trùm kinh doanh quốc tế thảo luận về tin đồn rằng sĩ quan KGB đã chết sở hữu một quả bom vali hạt nhân. Tại Moscow, Rajan bị lộ và bị bắn chết khi đang cố gắng gửi một thông điệp Code Red tới Ấn Độ. Ở Ấn Độ, người đứng đầu RAW nhìn thấy tin nhắn chưa hoàn chỉnh chỉ chứa số 242. Đặc vụ Vinod thực hiện một nhiệm vụ bí mật xuyên quốc gia để khám phá lý do tại sao đồng nghiệp của anh ta, Rajan, bị sát hại. Một loạt khúc ngoặt đưa Vinod đi khắp thế giới đến Ma-rốc và Latvia, Karachi đến Delhi và cuối cùng là London, nơi anh phát hiện ra âm mưu thực sự.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Adil Hussain","avatar":""},{"name":"Ravi Kishan","avatar":""},{"name":"Prem Chopra","avatar":""},{"name":"Ram Kapoor","avatar":""},{"name":"Zakir Hussain","avatar":""},{"name":"B. P. Singh","avatar":""},{"name":"Shahbaz Khan","avatar":""},{"name":"Gulshan Grover","avatar":""},{"name":"Dhritiman Chatterjee","avatar":""},{"name":"Rajat Kapoor","avatar":""},{"name":"Anshuman Ajai Singh","avatar":""},{"name":"Arif Zakaria","avatar":""},{"name":"Vasilisa Petina","avatar":""},{"name":"Mohommed Ali Shah","avatar":""},{"name":"Ri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
