INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-doc-than', 'Hội Độc Thân', 'Bachelorette', 'https://phimimg.com/upload/vod/20231125-1/05a6717db97d6141daf5246990bcd6dc.jpg', 'https://phimimg.com/upload/vod/20231125-1/e375c03eb29ddd3e7baedaec30c6b031.jpg', '<p>Phim Bachelorette - Hội Độc Thân có nội dung hài hước kể về những cô bạn thân từ thời còn học cấp 3 gặp lại nhau để giúp một cô bạn trong nhóm trước ngày cưới, thế nhưng giúp đỡ thì chưa thấy, một người trong nhóm đề nghị tổ chức một buổi tiệc độc thân thâu đêm trước ngày cưới để chúc mừng người bạn của mình. Và rồi từ đó, những rắc rối đầy hài hước bắt đầu xảy ra.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kirsten Dunst","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Kyle Bornheimer","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Hayes MacArthur","avatar":""},{"name":"Ella Rae Peck","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Shauna Miles","avatar":""},{"name":"Arden Myrin","avatar":""},{"name":"Candy Buckley","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Melissa Stephens","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
