INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-thang-bien-sau', 'Chiến Thắng Biển Sâu', 'The Deep', 'https://phimimg.com/upload/vod/20231125-1/5e54c5f66dff9b6e5eebcaba272f4306.jpg', 'https://phimimg.com/upload/vod/20231125-1/9d04d6c0de83e4b44bcd9a203208dde9.jpg', '<p>Một ngư dân tên Gulli đã sống sót sau một vụ chìm tàu và phải tìm cách quay lại đất liền. Trong khi hầu hết mọi người không thể cầm cự được lâu, Gulli đã tìm cách xoay xở trên biển Bắc Đại Tây Dương trong sáu tiếng và đi bộ trên những hòn đá nhọn thêm hai tiếng nữa. Ông nói chuyện với lũ mòng biển và bắt đầu nhớ lại về cuộc đời mình, cũng như những nghĩ về những gì ông sẽ làm khi ông sống sót. Đây là một bộ phim về sự bền bỉ và dũng cảm, được thể hiện qua cuộc đấu tranh sinh tồn của Gulli trên biển và cuộc sống của ông sau khi trở về đất liền.</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Iceland', 0, '[{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Joi Johannsson","avatar":""},{"name":"Þorbjörg Helga Þorgilsdóttir","avatar":""},{"name":"Theodór Júlíusson","avatar":""},{"name":"María Sigurðardóttir","avatar":""},{"name":"Björn Thors","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
