INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-dam-bao-an-toan', 'Không Đảm Bảo An Toàn', 'Safety Not Guaranteed', 'https://phimimg.com/upload/vod/20231126-1/e776b9969183ce69f26b7bc9458fc900.jpg', 'https://phimimg.com/upload/vod/20231126-1/81186a6b8b6a756615b0564b49795580.jpg', '<p>Đây là bộ phim tuyệt vời nhất ở thể loại phim hài. Người xem chắc chắn sẽ được cười thỏa thuê, nhưng đồng thời sẽ rất xúc động với câu chuyện trong phim. Nhân vật Aubrey Plaza sẽ khiến khán giả yêu mến ngay lập tức vì tính cách khá hay ho của cô nàng. Bạn diễn của cô – Mark Duplass cũng hấp dẫn không kém. Cặp đôi này đã dẫn dắt người xem tới một cuộc hành trình khám phá bản thân để mở rộng trái tim và trí tưởng tượng ngọt ngào, theo cùng một cách...</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aubrey Plaza","avatar":""},{"name":"Mark Duplass","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Jenica Bergere","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"William Hall Jr.","avatar":""},{"name":"Tony Doupe","avatar":""},{"name":"Xola Malik","avatar":""},{"name":"Kimberly Durham","avatar":""},{"name":"Grace Arends","avatar":""},{"name":"Scott Swan","avatar":""},{"name":"Basil Harris","avatar":""},{"name":"Tom Ricciardelli","avatar":""},{"name":"Lynn Shelton","avatar":""},{"name":"Eli Boro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c