INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-den-bac-cuc', 'Hành Trình Đến Bắc Cực', 'To the Arctic 3D', 'https://phimimg.com/upload/vod/20231125-1/2fbbe19faa88773dab67d18b4c99e85b.jpg', 'https://phimimg.com/upload/vod/20231125-1/a89dc4b0ce3cac69b6f50791e683ea99.jpg', '<p>Phim tài liệu phiêu lưu Hành Trình Đến Bắc Cực kể về một câu chuyện đầy ngoạn mục về sự sinh tồn trong tự nhiên. Được dẫn dắt bởi giọng đọc truyền cảm của chủ nhân giải Oscar, Meryl Streep. Bộ phim dẫn dắt khán giả đến với một chuyến hành trình chưa từng được trải nghiệm trước đây vào cuộc sống của một cô gấu Bắc Cực cùng hai chú gấu con sinh đôi mới bảy tháng tuổi của mình khi chúng tìm đường trở về nhà ở vùng Bắc Cực hoang dã.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324467);
