INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-gui-momo', 'Thư Gửi Momo', 'A Letter to Momo', 'https://phimimg.com/upload/vod/20231125-1/3ecadd15b0981118c32c489390138c53.jpg', 'https://phimimg.com/upload/vod/20231125-1/90fadc864817bda1bf8471ab0aafeb45.jpg', '<p>Cuộc sống của một cô bé 11 tuổi nhút nhát bước sang một bước ngoặt kỳ lạ khi cô phát hiện ra ba con yêu tinh đói sống trên gác mái của ngôi nhà mới của mình. Cô nhớ cuộc sống cũ của mình. Cô ấy nhớ cha mình rất nhiều. Cho đến khi cô ấy kết bạn với ma cà rồng mới.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Karen Miyama","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Yuka","avatar":""},{"name":"Takeo Ogawa","avatar":""},{"name":"Yoshisada Sakaguchi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Cho","avatar":""},{"name":"Ikuko Tani","avatar":""},{"name":"Daizaburō Arakawa","avatar":""},{"name":"Kota Fuji","avatar":""},{"name":"Katsuki Hashimoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324467);
