INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-buoi-hoang-hon-3', 'Mãi Mãi Buổi Hoàng Hôn 3', 'Always Sunset on Third Street ''64', 'https://phimimg.com/upload/vod/20231206-1/dca1e9c11d3644187f31a7bb3b031f27.jpg', 'https://phimimg.com/upload/vod/20231206-1/5522b330573267ce753958764ffa6537.jpg', '<p>Always Sanchome no Yuhi 64 là phần cuối cùng của phim điện ảnh 3 phần Always Sanchome no Yuhi.
 Tokyo năm 1964. Thế vận hội Olympic sẽ được tổ chức ở Tokyo và Nhật Bản đã trải qua một giai đoạn tăng trưởng kinh tế nhanh chóng. Chứng kiến quá trình chuyển mình của đất nước, cư dân Third Street vẫn sống một cuộc sống bình dị với thái độ lạc quan. Tiểu thuyết gia Ryunosuke đã kết hôn với Hiromi, Junnosuke hiện nay đã lên trung học vẫn sống cùng với họ. Suzuki cùng với vợ Tomoe, đứa con trai Ippei, và cô nhân viên Mutsuko tiếp tục làm việc ở xưởng xe. Cửa hàng của họ đã phát triển và mở rộng sau chừng ấy năm, hiện đã có mặt trên khắp các nẻo đường. Tuy nhiên, sau đó một sự kiện đã xảy ra cho các cư dân ở Third Street...</p>', 'Full', 1, 'single', 'completed', 7, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hidetaka Yoshioka","avatar":""},{"name":"Koyuki","avatar":""},{"name":"Shinichi Tsutsumi","avatar":""},{"name":"Maki Horikita","avatar":""},{"name":"Shota Sometani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
