INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-de-tau-than-chau', 'Cha Đẻ Tàu Thần Châu', 'Qian Xuesen', 'https://phimimg.com/upload/vod/20231205-1/01dca280e562fee5bf397cc6d4fbe556.jpg', 'https://phimimg.com/upload/vod/20231205-1/d22a9edf373a3a3ed6369679a6ec78a4.jpg', '<p>Giáo sư Caltech Qian Xuesen chịu đựng 5 năm điều tra từ thời McCarthy trước khi trở về Trung Quốc để trở thành cha đẻ của chương trình không gian của đất nước.</p>', 'Full', 1, 'single', 'completed', 8, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chen Kun","avatar":""},{"name":"Kitty Zhang","avatar":""},{"name":"George Anton","avatar":""},{"name":"Steve Boergadine","avatar":""},{"name":"Ted Durant","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
