INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oi-thanh-than-oi', 'Ôi Thánh Thần Ơi', 'OMG: Oh My God!', 'https://phimimg.com/upload/vod/20231125-1/07f94d62c5a921a5f52d7fc506b7a35a.jpg', 'https://phimimg.com/upload/vod/20231125-1/bee36e20116322fdaf299b945708c4b8.jpg', '<p>OMG: Oh My God! (Ôi Thánh Thần Ơi!) là một bộ phim hài châm biếm của Ấn Độ năm 2012, là phiên bản làm lại của bộ phim The Man Who Sued God của Úc năm 2001. Cốt truyện dựa trên một vở kịch sân khấu Gujarati (thể loại kịch nói bằng ngôn ngữ bản địa của bang Gujarat, Ấn Độ) mang tên Kanji Virudh Kanji. Phim được Umesh Shukla đạo diễn và đồng biên kịch với Bhavesh Mandalia. OMG: Oh My God! tuy không gây tiếng vang lớn về giải thưởng nhưng có nội dung khá thú vị, hài hước về đề tài tôn giáo.</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Paresh Rawal","avatar":""},{"name":"Akshay Kumar","avatar":""},{"name":"Mithun Chakraborty","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Mahesh Manjrekar","avatar":""},{"name":"Puja Gupta","avatar":""},{"name":"Apoorva Arora","avatar":""},{"name":"Poonam Jhawer","avatar":""},{"name":"Krunal Pandit","avatar":""},{"name":"Harsh Chhaya","avatar":""},{"name":"Lubna Salim","avatar":""},{"name":"Nikhil Ratnaparkhi","avatar":""},{"name":"Murali Sharma","avatar":""},{"name":"Yusuf Hussain","avatar":""},{"name":"Jaineeraj Rajpurohit","avatar":""},{"name":"Nidhi Subbaiah","avatar":""},{"name":"Azaan Sh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324467);
