INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oi-thanh-than-oi', 'Ôi Thánh Thần Ơi', 'OMG: Oh My God!', 'ôi thánh thần ơi omg: oh my god! paresh rawal akshay kumar mithun chakraborty om puri mahesh manjrekar puja gupta apoorva arora poonam jhawer krunal pandit harsh chhaya lubna salim nikhil ratnaparkhi murali sharma yusuf hussain jaineeraj rajpurohit nidhi subbaiah azaan sh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('as-one', 'As One', 'As One', 'https://phimimg.com/upload/vod/20231125-1/f877da7bce613ea55b440866df6df787.jpg', 'https://phimimg.com/upload/vod/20231125-1/e768394cfb7f0b3ed7375bcd9aeeb04d.jpg', '<p>&quot;Là một&quot; là nhà nghỉ điện ảnh của đội thể thao Hàn Quốc thống nhất sau chiến tranh đầu tiên, vội vàng thành lập để tham gia vào Giải vô địch bóng bàn thế giới thứ 41 vào năm 1991. Sau vụ đánh bom trung bình của Bắc Triều Tàu của Triều Tiên 858 năm 1987, Một hội nghị thượng đỉnh đã được tổ chức giữa Bắc và Hàn Quốc để xoa dịu căng thẳng cực đoan trên bán đảo. Hội nghị thượng đỉnh đã kết thúc với thỏa thuận thành lập một đội thể thao Hàn Quốc thống nhất; và bóng bàn, có thể nhìn thấy rất cao và đẳng cấp thế giới ở cả hai quốc gia, được chọn là sự hợp nhất tượng trưng. Tóm lại, đội bóng Bắc-Nam thống nhất đầu tiên dưới sự Aegis &quot;Hàn Quốc&quot; đơn giản được thành lập để cạnh tranh trong Giải vô địch bóng bàn thế giới năm 1991 tại Chiba, Nhật Bản. &quot;Như một&quot; kể lại những sự kiện đầy kịch tính này, nơi đặc biệt là hai cầu thủ đẳng cấp thế giới chỉ gặp nhau trên bàn là những đối thủ khó chết phải đột nhiên trở thành một đối tác và đồng đội thực sự trong giai đoạn lớn nhất của Giải vô địch thế giới. Đưa sang một bên các tham vọng cá nhân của họ, những phụ nữ này phải triệu tập mọi ounce Grit và Grace để đánh bại một đội ngũ thống trị của Trung Quốc đã gây ra danh hiệu Giải vô địch thế giới thứ 9 liên tiếp.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji-won","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Han Yeri","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Lee Jong-suk","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Park Young-seo","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Choi Yoon-young","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Jo Min-jae","avatar":""},{"name":"Jang Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
