INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-nhung-dieu-chua-ke', 'Điệp Viên 007: Những Điều Chưa Kể', 'Everything or Nothing: Untold Story 007', 'null', 'https://phimimg.com/upload/vod/20231205-1/9989e8e439caabec59d0dac7358f412b.jpg', '<p>Điệp Viên 007: Những Điều Chưa Kể - Everything or Nothing: Untold Story 007- Kể về câu chuyện của Maddy (Amandla Stenberg), một thanh niên 18 tuổi thông minh và giàu trí tưởng tượng, người bị bệnh không thể rời khỏi sự bảo vệ của môi trường kín mít của cô ấy, và Olly (Nick Robinson), cậu bé hàng xóm. ai sẽ không để điều đó ngăn cản họ. Nhìn qua cửa sổ và chỉ nói chuyện bằng tin nhắn, cô và Olly hình thành một mối liên kết sâu sắc khiến họ phải mạo hiểm mọi thứ để được ở bên nhau ... ngay cả khi điều đó có nghĩa là mất tất cả.</p>', 'Full', 1, 'single', 'completed', 9, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Barry","avatar":""},{"name":"Ken Adam","avatar":""},{"name":"Maud Adams","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324467);
