INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-and-jerry-robin-hood-and-his-merry-mouse', 'Tom and Jerry: Robin Hood and His Merry Mouse', 'Tom and Jerry: Robin Hood and His Merry Mouse', 'https://phimimg.com/upload/vod/20231204-1/e6accd297e18fa4add07ccb64670c6c4.jpg', 'https://phimimg.com/upload/vod/20231204-1/3405c43d8748e822db605d0715e35f49.jpg', '<p>Robin Hood, một người đàn ông vui vẻ ăn cắp từ người giàu để dành cho người nghèo, có một Sidekick mới có khả năng, Jerry. Vua độc ác suy luận, theo cách riêng của mình rực rỡ, rằng cách tốt nhất để đối phó với mối đe dọa mới này là một con mèo, vì vậy anh ta thuê Tom.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324467);
