INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-nguy-hiem-2012', 'Mối Quan Hệ Nguy Hiểm', 'Dangerous Liaisons', 'https://phimimg.com/upload/vod/20231121-1/9295270d37c5ae3e54e94c0116b3158e.jpg', 'https://phimimg.com/upload/vod/20231121-1/288939c7024c8339cee7cdf676ab26d6.jpg', '<p>Lấy cảm hứng từ cuốn tiểu thuyết Les liaisons dangereuses của nhà văn người Pháp Choderlos de Laclos, ra đời năm 1782. Dangerous liaisons đưa người xem về Thượng Hải những năm 30 của thế ký trước. Tạ Dịch Phàm là chàng công tử ăn chơi khét tiếng nhất thành phố phải lòng Đỗ Phấn Ngọc – người phụ nữ trong sáng, thuần khiết. Trong khi đó, Mạc Tiệp Dư, người đàn bà phóng đãng mà Tạ Dịch Phàm chưa bao giờ chinh phục được, lại muốn anh cướp đi trinh tiết của một nữ sinh trong trắng vì cô này được hứa hôn cho gã tài phiệt mà Tiệp Dư hẹn hò. Những mối quan hệ nguy hiểm diễn ra trong một Thượng Hải phù hoa và đầy toan tính. ..Đời loạn, tình cũng loạn</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jang Dong-gun","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Cecilia Cheung Pak-Chi","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Candy Wang","avatar":""},{"name":"Lisa Lu","avatar":""},{"name":"Xiao Shu-Li","avatar":""},{"name":"Wu Fang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
