INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-ngam', 'Phi Vụ Ngầm', 'Contraband', 'https://phimimg.com/upload/vod/20231123-1/c2d87f6d13e403955bae70e82486a3a4.jpg', 'https://phimimg.com/upload/vod/20231123-1/4ab7744a963f7ab6c8de1d027b5a47c3.jpg', '<p>Từ rất lâu kể từ khi cha anh bị tống tù. Khi cậu em vợ là Andy (Caleb Landry Jones) dính líu tới một vụ buôn ma túy với tay trùm Tim Brigg (Giovanni Ribisi), Chris buộc phải ra mặt giải quyết để tránh liên lụy tới vợ và các con. Để có thể trả nợ cho Andy trong thời hạn hai tuần, Chris dự tính thực hiện một phi vụ buôn tiền giả tại Panama. Với sự giúp đỡ của người bạn thân lâu năm Sebastian (Ben Foster), Chris gia nhập đoàn thủy thủ của tàu Southbound của thuyền trưởng Camp và vạch ra một kế hoạch hoàn hảo trong thời gian tương đối chặt chẽ. Tuy nhiên, cũng như bất kỳ “nhiệm vụ cuối cùng” nào, mọi sự chuẩn bị từ trước của Chris không diễn ra suôn sẻ như anh đã định, khiến anh và các đồng sự phải đối mặt với những biến cố không lường trước được.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"David O''Hara","avatar":""},{"name":"William Lucking","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Robert Wahlberg","avatar":""},{"name":"Jason Mitchell","avatar":""},{"name":"Paul LeBlanc","avatar":""},{"name":"Michael J. Taylor","avatar":""},{"name":"John Russ B","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324467);
