INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-sau-nua-dem', '30'' Sau Nửa Đêm', 'Zero Dark Thirty', 'https://phimimg.com/upload/vod/20231123-1/01c9501624798704947915dbf16aac49.jpg', 'https://phimimg.com/upload/vod/20231123-1/b0354eec39176c24eeb55aeac9722ee6.jpg', '<p>Zero Dark Thirty’ của nữ đạo diễn Kathryn Bigelow nhận 5 đề cử tại giải thưởng của Viện Hàn lâm.Phim hay nhất, Nữ diễn viên chính xuất sắc (cho Jessica Chastain), Dựng phim xuất sắc, Dựng âm thanh xuất sắc và Kịch bản gốc hay nhất.Với kinh phí 40 triệu USD và lời giới thiệu “câu chuyện về cuộc truy tìm người đàn ông nguy hiểm nhất trong lịch sử thế giới”, phim xoay quanh nhân vật chính là Maya (Jessica Chastain), một nữ chuyên gia phân tích của Cơ quan Tình báo Trung ương (CIA). Cô đóng vai trò quan trọng trong chiến dịch truy kích trùm Al-Qaeda. Maya truy tìm dấu vết của Bin Laden trong một thập kỷ từ sau vụ khủng bố 11/9/2001 khiến cả nước Mỹ chìm trong đau thương.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Mark Duplass","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Jeremy Strong","avatar":""},{"name":"Reda Kateb","avatar":""},{"name":"Ricky Sekhon","avatar":""},{"name":"J.J. Kandel","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Stephen Dillane","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324467);
