INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-sinh-mot-cap', 'Trời Sinh Một Cặp', 'Perfect Two', 'https://phimimg.com/upload/vod/20231123-1/ce4a342eadd9d875d654eb3ca54fbcdd.jpg', 'https://phimimg.com/upload/vod/20231123-1/47c708724ac662348b95367101da0a46.jpg', '<p>Lẳng lặng nuôi con suốt 6 năm trời, đến khi cậu bé lớn đôi chút, cô nàng quyết định ra nước ngoài sinh sống. Không nỡ để con mình cả đời không biết mặt cha, Gia Úy mang Bân Bân đến chỗ A Tân để 2 người nhận mặt nhau. Vậy là chuỗi ngày chung sống giữa người cha “bất đắc dĩ” và cậu con “từ trên trời rơi xuống” đã bắt đầu từ đây...</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Vic Chou","avatar":""},{"name":"Ella Chen Jia Hua","avatar":""},{"name":"Vivian Hsu","avatar":""},{"name":"Yang Mi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324467);
