INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-cuoi-con-duong', 'Ánh Sáng Cuối Con Đường', 'The Cold Light of Day', 'https://phimimg.com/upload/vod/20231123-1/7153f41982929f2efe20a71408cc0ca0.jpg', 'https://phimimg.com/upload/vod/20231123-1/191f1247ef20889eb352ceb20cac5987.jpg', '<p>Khi Will Shaw tới Tây Ban Nha trong một kỳ nghỉ trên du thuyền cùng cả gia đình, chàng doanh nhân trẻ chẳng có tâm trạng nào để nghỉ ngơi. Công ty non trẻ của anh đang gặp trục trặc và mối quan hệ căng thẳng của anh với người cha nghiêm khắc Martin chỉ càng làm cho mọi chuyện tệ hơn. Nhưng khi gia đình của anh bị bắt cóc bởi những đặc vụ trong quá trình thu hồi lại một chiếc cặp bí ẩn, Will ngay lập tức trở thành đối tượng bị truy đuổi...</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Henry Cavill","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Verónica Echegui","avatar":""},{"name":"Joseph Mawle","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Rafi Gavron","avatar":""},{"name":"Emma Hamilton","avatar":""},{"name":"Michael Budd","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Jim Piddock","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Andrea Ros","avatar":""},{"name":"Joe Dixon","avatar":""},{"name":"Paloma Bloyd","avatar":""},{"name":"Fermí Reixach","avatar":""},{"name":"Mark Ullod","avatar":""},{"name":"Colm Meaney","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324467);
