INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-trieu-do', 'Ông Trùm Triệu Đô', 'A Millionaire on the Run', 'https://phimimg.com/upload/vod/20231123-1/6ea5e7cfb4e7727c07fb6146bca12cf3.jpg', 'https://phimimg.com/upload/vod/20231123-1/e887c27856a2f80c88fc49e1abb11c3c.jpg', '<p>Câu chuyện về anh chàng nhân viên văn phòng kiêm quản lý Choi Yeong In (Jin-young Park) được giao nhiệm vụ mang 5 triệu đô đi hối lộ. Vốn ôm mộng làm ca sĩ, thế nhưng số tiền 5 triệu đô đã thay đổi hoàn toàn cuộc đời anh. Choi Yeong In vô tình bị cuốn vào một âm mưu chiếm đoạt số tiền và thậm chí bị truy sát, liệu anh phải làm sao để bảo toàn tính mạng?</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Jin-young","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Min Hyo-rin","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Lee Kyung-young","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
