INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-trong-mo', 'Cô Gái Trong Mơ', 'Ruby Sparks', 'https://phimimg.com/upload/vod/20231123-1/3173647df1334e915138128af2f1f16f.jpg', 'https://phimimg.com/upload/vod/20231123-1/f58d0290ad075c4984a613fb6787910c.jpg', '<p>Calvin là một tiểu thuyết gia thiên tài, anh bắt đầu viết một tiểu thuyết mới bằng chiếc máy đánh chữ về Ruby, một cô gái trong mơ đối với anh. Anh ấy không ngờ rằng, ngày hôm sau, Ruby biến thành 1 cô gái thực sự, và họ bắt đầu có một mối quan hệ tốt đẹp với nhau. Nếu mối quan hệ có gì đó không ổn, tất cả việc Calvin cần làm là gõ vài chữ vào tiểu thuyết và Ruby sẽ thực hiện y hệt như những thứ anh cần.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Dano","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Alia Shawkat","avatar":""},{"name":"Deborah Ann Woll","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Toni Trucks","avatar":""},{"name":"Eleanor Seigler","avatar":""},{"name":"John F. Beach","avatar":""},{"name":"Jane Anne Thomas","avatar":""},{"name":"Wallace Langham","avatar":""},{"name":"Mary Jo Deschanel","avatar":""},{"name":"Emma Jacob","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
