INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-sleepless', 'The Sleepless', 'The Sleepless', 'https://phimimg.com/upload/vod/20231123-1/c75ececc6502892f6994ffd4bb0a0716.jpg', 'https://phimimg.com/upload/vod/20231123-1/0dcc7d5c191e06a2b07f2f0584247386.jpg', '<p>&quot;Hai mặt trăng&quot; mô tả hai phụ nữ và một người đàn ông thấy mình ở một khu vực bị cô lập mà không có lối thoát. So-hee (Park Han-Byul) là một nhà văn câu chuyện kinh dị, người giữ bí mật. Seok-ho (Kim Ji-seok) là một sinh viên đại học bị chấn thương không xác định. Anh ta cố gắng khám phá những gì chấn thương đó là.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Han-byul","avatar":""},{"name":"Kim Ji-seok","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Park Won-sang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
