INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cloned-the-recreator-chronicles', 'CLONED: The Recreator Chronicles', 'CLONED: The Recreator Chronicles', 'https://phimimg.com/upload/vod/20231031-1/f9eaf088c26c6a6c25397b61fe60c0bd.jpg', 'https://phimimg.com/upload/vod/20231031-1/1553a1b86f00aa947aa686f21e401e3d.jpg', '<p>Khi một nhóm thanh thiếu niên tình cờ tìm thấy một phòng thí nghiệm bí mật, họ trở thành một phần của thí nghiệm chết người - The Recreator - những bản sao độc ác của con người. Craig, Tracy và Derek đối mặt với những bản sao chính xác của chính họ chỉ có một mục đích; để tìm và giết bản gốc của họ. Khi thời gian không còn nhiều, nhóm ban đầu phải phá hủy phòng thí nghiệm và tự cứu mình trước khi chúng bị thay thế. Bộ phim kinh dị thú vị của Gregory Orr mang khoa học viễn tưởng vào cuộc sống với một khía cạnh gợi cảm.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stella Maeve","avatar":""},{"name":"J. Mallory McCree","avatar":""},{"name":"John de Lancie","avatar":""},{"name":"Laura Moss","avatar":""},{"name":"Alexander Nifong","avatar":""},{"name":"Curzon Dobell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
