INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-phu-hop-voi-tre-em', 'Không Phù Hợp Với Trẻ Em', 'Not Suitable For Children', 'https://phimimg.com/upload/vod/20231116-1/2b8314c085bf24554a96653d02f1987b.jpg', 'https://phimimg.com/upload/vod/20231116-1/976599a03938a098728ebc2d8354bd06.jpg', '<p>Anh chàng playboy chính hiệu Jonah với cuộc sống là những chuỗi ngày vô tư “chinh chiến” với các cô gái và tiệc tùng. Bỗng một hôm, thế giới của Jonah như bị đảo lộn khi anh nhận được tin mình bị ung thư tinh hoàn, và khả năng sẽ không thể có con trong vòng một tháng nữa. Với mọi nỗ lực cùng sự giúp đỡ của bạn bè, Jonah quyết định tận dụng khoảng thời gian quý báu còn lại để thực hiện một kế hoạch điên rồ “gieo giống” càng nhiều càng tốt!</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Ryan Kwanten","avatar":""},{"name":"Sarah Snook","avatar":""},{"name":"Ryan Corr","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Laura Brent","avatar":""},{"name":"Alice Parkinson","avatar":""},{"name":"Susan Prior","avatar":""},{"name":"Lewis Fitz-Gerald","avatar":""},{"name":"Kathryn Beck","avatar":""},{"name":"Belinda Bromilow","avatar":""},{"name":"Zoe Carides","avatar":""},{"name":"Lulu McClatchy","avatar":""},{"name":"Daniel Henshall","avatar":""},{"name":"Dilshan Rain","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
