INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-vay', 'Giải Vây', 'Maximum Conviction', 'https://phimimg.com/upload/vod/20231120-1/5a7acfd9d11c8fcc2448f3f089bb4382.jpg', 'https://phimimg.com/upload/vod/20231120-1/16037ab3b83ce5becb885a1020c3b61b.jpg', '<p>Một cựu nhân viên đặc nhiệm Tom Steele (Seagal) và đồng nghiệp của ông Manning (Austin) được giao cho ngừng hoạt động một nhà tù cũ, họ phải giám sát sự xuất hiện của hai nữ tù nhân bí ẩn. Chẳng bao lâu, một lực lượng tinh nhuệ của lính đánh thuê tấn công nhà tù trong việc tìm kiếm những người mới đến. Khi được tiết lộ danh tính thực sự của những người phụ nữ, Steele nhận ra anh đang ở giữa một bí mật lớn mà ông không tưởng tượng được.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Steve Austin","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Bren Foster","avatar":""},{"name":"Aliyah O''Brien","avatar":""},{"name":"Steph Song","avatar":""},{"name":"Toby Levins","avatar":""},{"name":"J.J. Makaro","avatar":""},{"name":"Terrance Leigh","avatar":""},{"name":"Teach Grant","avatar":""},{"name":"Ian Robison","avatar":""},{"name":"Brian Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
