INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tu-rome', 'Tình Yêu Từ Rome', 'To Rome with Love', 'https://phimimg.com/upload/vod/20231119-1/fb789536d77012507d54a0609a4b6a1a.jpg', 'https://phimimg.com/upload/vod/20231119-1/f7dd3e796962e444a4ce27e89c0e8ed2.jpg', '<p>To Rome With Love được lồng ghép bởi 4 câu chuyện riêng biệt về những người dừng chân tại thành Rome. Họ là người Mỹ, người Italy, dân địa phương hay khách du lịch. Tất cả đều bị cuốn vào những cuộc phiêu lưu lãng mạn tại thành phố huyền thoại của châu Âu...</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Woody Allen","avatar":""},{"name":"Roberto Benigni","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Judy Davis","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Greta Gerwig","avatar":""},{"name":"Elliot Page","avatar":""},{"name":"Alessandro Tiberi","avatar":""},{"name":"David Pasquesi","avatar":""},{"name":"Lynn Swanson","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Augusto Fornari","avatar":""},{"name":"Mariano Rigillo","avatar":""},{"name":"Gianmarco Tognazzi","avatar":""},{"name":"Riccardo Scamarcio","avatar":""},{"name":"Ales","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
