INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-dau-marsupilami', 'Theo dấu Marsupilami', 'HOUBA! On the Trail of the Marsupilami', 'https://phimimg.com/upload/vod/20231119-1/a799246dc0a60f828caece8446095c1b.jpg', 'https://phimimg.com/upload/vod/20231119-1/0ca516b8c08d3f061f5e3b69b02aee39.jpg', '<p>Khi phóng viên Dan Geraldo (Alain Chabat) đến Palombia để săn lùng một muỗng, anh ta không bao giờ nghi ngờ rằng anh ta sắp thực hiện một khám phá đáng kinh ngạc ... với hướng dẫn địa phương tài nguyên của mình Pablito (Jamel Debouze), Dan có một bất ngờ sau một Một cuộc phiêu lưu ly kỳ cho phép anh ta mang thế giới một số tin tức ngoạn mục: Marsupilami, một con vật thần thoại và tinh nghịch, thực sự tồn tại! Bạn cũng sẽ trở thành những cái đuôi lông!</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Alain Chabat","avatar":""},{"name":"Jamel Debbouze","avatar":""},{"name":"Fred Testot","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Patrick Timsit","avatar":""},{"name":"Géraldine Nakache","avatar":""},{"name":"Liya Kebede","avatar":""},{"name":"Aïssa Maïga","avatar":""},{"name":"Dalip Singh","avatar":""},{"name":"Jacques Weber","avatar":""},{"name":"Jade Nuckcheddy","avatar":""},{"name":"Erika Carlsson","avatar":""},{"name":"Carlos Macias Marquez","avatar":""},{"name":"Salah Benlemqawanssa","avatar":""},{"name":"Maria McClurg","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
