INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-doi-dau', 'Điệp Vụ Đối Đầu', 'Cold War', 'https://phimimg.com/upload/vod/20231117-1/2878724ade94c0e8564d460f305bc8d2.jpg', 'https://phimimg.com/upload/vod/20231117-1/873d02583414d1e58bcfcdfd79007997.jpg', '<p>Trung tâm báo án của Lực lượng Cảnh sát Hồng Kông đã nhận được những cuộc gọi điện thoại nặc danh, báo cáo một vụ bắt cóc tấn công 1 chiếc xe cảnh sát. Trong xe gồm 5 nhân viên cảnh sát cùng các vũ khí trang thiết bị đã trở thành con tin để bọn bắt cóc đòi tiền chuộc. Nhằm lúc Tổng trưởng cảnh sát đi công tác nước ngoài, vì vậy 2 phó tổng trưởng cảnh sát là Lý Văn Bân (Lương Gia Huy đóng) – thuộc phái diều hâu và Lưu Kiệt Huy (Quách Phú Thành đóng) được giao nhiệm vụ giải cứu con tin.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Aarif Rahman","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Andy On","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Grace Huang","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Ma Yili","avatar":""},{"name":"Gary Chan Ga-Fai","avatar":""},{"name":"Angel Ho","avatar":""},{"name":"Foo Hiu-Mei","avatar":""},{"name":"Rachel Kan","avatar":""},{"name":"Elva Ni Chen-Xi","avatar":""},{"name":"Alex Mok S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
