INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-dinh-menh-407', 'Chuyến Bay Định Mệnh 407', '407 Dark Flight 3D', 'https://phimimg.com/upload/vod/20231117-1/8ada8bb6d1d90fbbc3dcfdf36025866b.jpg', 'https://phimimg.com/upload/vod/20231117-1/253e89c7e238ad0aea8094bd1cb37ab2.jpg', '<p>Mười năm trước, một nữ tiếp viên hàng không trẻ tuổi, New, đã sống sót một cách kỳ diệu trong một vụ tai nạn máy bay. New khẳng định rằng một linh hồn báo thù đã gây ra tai nạn đó, nhưng niềm tin của cô ấy khiến những người xung quanh lo lắng và cô ấy phải trải qua một liệu pháp tâm lý.</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Marsha Vadhanapanich","avatar":""},{"name":"Peter Knight","avatar":""},{"name":"Paramej Noiam","avatar":""},{"name":"Unchalee Hassadeevichit","avatar":""},{"name":"Patcharee Tubthong","avatar":""},{"name":"Namo Tongkumnerd","avatar":""},{"name":"Sisangian Sihalath","avatar":""},{"name":"Anchalee Hassadeevichit","avatar":""},{"name":"Thiti Vechabul","avatar":""},{"name":"Jonathan Samson","avatar":""},{"name":"Kristen Evelyn Rossi","avatar":""},{"name":"Atthaphan Phunsawat","avatar":""},{"name":"Nuntita Khampiranon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
