INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tad-truy-tim-kho-bau', 'Tad Truy Tìm Kho Báu', 'Tad, the Lost Explorer', 'https://phimimg.com/upload/vod/20231117-1/f2e7182e5885b267320878d8f8601b41.jpg', 'https://phimimg.com/upload/vod/20231117-1/9a69c3e6aac237a949ef796cdb57d290.jpg', '<p>Từ thuở thơ ấu, Tad đã mơ ước có những chuyến phiêu lưu đầy nguy hiểm và những khám phá lớn lao, thần tượng của anh là nhà thám hiểm Indiana Jones. Nhưng sự thật thì Tad chỉ là một công nhân xây dựng bình thường. Nhưng một lần, định mệnh đã đưa đẩy điều đó xảy ra, đưa đẩy Tad đến khu khảo cổ học ở Peru để tìm kiếm kho báu Inca cổ. Nhưng câu chuyện không xảy ra trôi chảy, Tad bắt đầu đối mặt với nhiều hiểm nguy…</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Óscar Barberán","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"José Mota","avatar":""},{"name":"Pep Anton Muñoz","avatar":""},{"name":"Miguel Ángel Jenner","avatar":""},{"name":"Luis Posada","avatar":""},{"name":"Meritxell Ané","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324467);
