INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chet-truoc-luc-binh-minh', 'Chết Trước Lúc Bình Minh', 'Dead Before Dawn', 'null', 'https://phimimg.com/upload/vod/20231116-1/b5414556c33a5934754b9132b9d11e45.jpg', '<p>Bắt đầu với sự hồi tưởng về thời thơ ấu của Casper Galloway, nơi anh chứng kiến cái chết của cha mình. Sau 16 năm, anh là sinh viên của một trường trung học. Cho đến một ngày, ông nội nhờ anh trông chừng cửa hàng đồ cổ của mình trong một giờ. Casper hoài nghi, như trong anh có một nỗi sợ hãi về nơi này kể từ lúc cha anh qua đời khi anh được bốn tuổi. Trong lúc trông chừng cửa hàng, vì tò mò anh đã làm vỡ một chiếc bình an táng cũ, mà ông nội của anh đã cảnh báo anh không được chạm vào. Lời nguyền từ chiếc bình trở thành hiện thực. Bất cứ ai nhìn vào mắt anh sẽ trở thành Zombie Demons hay còn gọi là Zemons...</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Devon Bostick","avatar":""},{"name":"Martha MacIsaac","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Brandon Jay McLaren","avatar":""},{"name":"Brittany Allen","avatar":""},{"name":"Kyle Schmid","avatar":""},{"name":"Tim Doiron","avatar":""},{"name":"April Mullen","avatar":""},{"name":"Kevin McDonald","avatar":""},{"name":"Ellen Dubin","avatar":""},{"name":"Rossif Sutherland","avatar":""},{"name":"Dru Viergever","avatar":""},{"name":"Benjamin Ayres","avatar":""},{"name":"Max Topplin","avatar":""},{"name":"Marty Adams","avatar":""},{"name":"Jacob Ewaniuk","avatar":""},{"name":"Boyd Ban","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
