INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-la-can', 'Hẹn Hò Là Cắn', 'Vamps', 'https://phimimg.com/upload/vod/20231116-1/72d6799ccbbf313a0056673a414cfb80.jpg', 'https://phimimg.com/upload/vod/20231116-1/4a6278a056c4b856b4da7eefb2d00b17.jpg', '<p>Hẹn hò là cắn! Alicia Silverstone tái hợp với đạo diễn Clueless Amy Heckerling trong bộ phim hài Vamps, kể về hai cô ả hút máu thời hiện đại bị nghiện mua sắm và hay mơ mộng chuyện hẹn hò. Anchor Bay cũng cho ra mắt trailer đầu tiên cùng poster mới trong câu chuyện hoang đường máu me về giới ma cà rồng nữ này.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alicia Silverstone","avatar":""},{"name":"Krysten Ritter","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Richard Lewis","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Zak Orth","avatar":""},{"name":"Marilu Henner","avatar":""},{"name":"Kristen Johnston","avatar":""},{"name":"Meredith Scott Lynn","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Larry Wilmore","avatar":""},{"name":"Bettina Bresnan","avatar":""},{"name":"Todd Barry","avatar":""},{"name":"Taylor Negro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
