INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-ca-heo', 'Giải Cứu Cá Heo', 'Big Miracle', 'https://phimimg.com/upload/vod/20230917-1/749c3f3794dd2167505cdb7ce5c26c19.jpg', 'https://phimimg.com/upload/vod/20230917-1/f8bb32d7aec55acef3cf5a9543ae8775.jpg', '<p>Một phóng viên tin tức ở một thị trấn nhỏ và một tình nguyện viên của Greenpeace tranh thủ sự giúp đỡ của các siêu cường đối thủ để cứu ba con cá voi xám hùng vĩ bị mắc kẹt dưới lớp băng ở Vòng Bắc Cực.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Ted Danson","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"John Michael Higgins","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
