INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-bau-cu', 'Chiến Dịch Bầu Cử', 'The Campaign', 'https://phimimg.com/upload/vod/20231117-1/c912c4047491f1b53971c835ed44bbdd.jpg', 'https://phimimg.com/upload/vod/20231117-1/d17b03b0cd5b50e3b7eb87d4463bb784.jpg', '<p>Chuyện phim kể về Cam Brady và Marty Huggins - hai người hoàn toàn khác nhau từ cách sống, suy nghĩ. Nhưng mọi chuyện bỗng khác đi khi họ buộc phải đối đầu trong cuộc tranh cử ngang tài ngang sức. Bề ngoài luôn tỏ ra thân thiết, nhưng bên trong là cuộc đấu tranh, gây khó khăn cho nhau liên tục nhằm thu được số phiếu bầu nhiều hơn. Từ đây, những tình huống dở khóc dở cười liên tục xảy ra...</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Katherine LaNasa","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"Sarah Baker","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Karen Maruyama","avatar":""},{"name":"Grant Goodman","avatar":""},{"name":"Kya Haywood","avatar":""},{"name":"Randall D. Cunningham","avatar":""},{"name":"Madison Wolfe","avatar":""},{"name":"Thomas Middleditch","avatar":""},{"name":"Josh Lawson","avatar":""},{"name":"Heath","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
