INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-lenh-khan-cap', 'Mật Lệnh Khẩn Cấp', 'Brake', 'https://phimimg.com/upload/vod/20231117-1/bd4a86e43a43c658cf0946fe292dbc2f.jpg', 'https://phimimg.com/upload/vod/20231117-1/ca08061bdfa291a7829db0ccbac75d98.jpg', '<p>Một Đặc vụ Mật vụ bị giam giữ trong thùng xe ô tô và chịu đựng sự tra tấn về tinh thần và thể xác với tốc độ cao khi những kẻ khủng bố cố gắng moi thông tin cần thiết cho âm mưu thâm độc của chúng.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Chyler Leigh","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Kali Rocha","avatar":""},{"name":"Kent Shocknek","avatar":""},{"name":"Jaylen Moore","avatar":""},{"name":"Stephen J. Bridgewater","avatar":""},{"name":"Matthew Pollino","avatar":""},{"name":"Jason Raphael","avatar":""},{"name":"Sammy Sheik","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"King Orba","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
