INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-khung-long', 'Dự Án Khủng Long', 'The Dinosaur Project', 'https://phimimg.com/upload/vod/20231115-1/ecabc152618cac8480dc7ca368e97686.jpg', 'https://phimimg.com/upload/vod/20231115-1/b6382882cca33b2dda25b9c5bcfccd91.jpg', '<p>Khủng long, loài bò sát khổng lồ từng thống trị trái đất hàng triệu năm trước đây luôn là đề tài mở được các nhà làm phim nhắm đến cho các bộ phim phiêu lưu hành động đầy kịch tính. Và lần này trong The Dinosaur Project, loài khủng long lại trở lại nhưng với thể loại kinh dị, được đặc tả với khía cạnh hoàn toàn đáng sợ và nguy hiểm. Bộ phim kể về câu chuyện của 2 bố con cùng đoàn làm phim tài liệu cho một chương trình TV dấn thân vào 1 cuộc thám hiểm tại đất nước Congo hoang dã để đi tìm tàn tích của những chú khủng long tại đây, và họ đã tìm thấy được nhiều hơn thế...</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Natasha Loring","avatar":""},{"name":"Matt Kane","avatar":""},{"name":"Richard Dillane","avatar":""},{"name":"Peter Brooke","avatar":""},{"name":"Stephen Jennings","avatar":""},{"name":"Andre Weideman","avatar":""},{"name":"Abena Ayivor","avatar":""},{"name":"Sivu Nobongoza","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
