INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-khieu-vu', 'Nữ Hoàng Khiêu Vũ', 'Dancing Queen', 'https://phimimg.com/upload/vod/20231113-1/44c8f877cff316ceb75a472d88921c00.jpg', 'https://phimimg.com/upload/vod/20231113-1/cfacd350b024c0c157ad3ad838456e8e.jpg', '<p>Vợ của ứng cử viên cho chức thị trưởng kế tiếp của Seoul trở thành một ca sĩ múa trong phim này. Hwang Jeong-min sẽ vào vai một luật sư nghèo trở thành một nhà hoạt động chính trị và Uhm Jung-hwa vào vai người vợ có nguyện vọng trở thành ca sĩ nhưng ban đầu không muốn chồng mình biết.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Uhm Jung-hwa","avatar":""},{"name":"Hwang Jung-min","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Chung Sung-hwa","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Jeong Gyu-su","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Seo Dong-won","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Choi Woo-ri","avatar":""},{"name":"Han Soo-a","avatar":""},{"name":"Lee A-rin","avatar":""},{"name":"Park Sa-rang","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Lee Hyo-ri","avatar":""},{"name":"Gil","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Jeong A-mi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
