INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mai-mot-tinh-yeu', 'Còn Mãi Một Tình Yêu', 'Celeste & Jesse Forever', 'https://phimimg.com/upload/vod/20231114-1/c8788ee3032e25880887fa1a6e4dcf10.jpg', 'https://phimimg.com/upload/vod/20231114-1/3b769a0cec665d5cdd37eea8cb42c3d2.jpg', '<p>Celeste và Jesse gặp nhau ở trường trung học và kết hôn khi còn trẻ. Họ cười cùng một câu chuyện cười và kết thúc câu nói của nhau. Họ mãi mãi được liên kết trong tâm trí bạn bè như một cặp đôi hoàn hảo - cô ấy, một nữ doanh nhân quyền lực và một tiểu thuyết gia mới chớm nở; anh ấy, một tâm hồn tự do luôn khiến mọi thứ không trở nên nhàm chán. Vấn đề duy nhất của họ là họ đã quyết định ly hôn. Mối quan hệ hoàn hảo của họ có thể chịu được trở ngại nhỏ này không?</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rashida Jones","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Emma Roberts","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Rebecca Dayan","avatar":""},{"name":"Janel Parrish","avatar":""},{"name":"Sarah Haskins","avatar":""},{"name":"Matthew Del Negro","avatar":""},{"name":"Shira Lazar","avatar":""},{"name":"Will McCormack","avatar":""},{"name":"Kate Krieger","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Zoë Hall","avatar":""},{"name":"Lenny Jacobson","avatar":""},{"name":"Chri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
