INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-hoi-gi-ben-khong', 'Ai Hỏi Gì Ben Không?', 'Any Questions for Ben?', 'https://phimimg.com/upload/vod/20231115-1/62d439455813faa1f3f753197d75dbc5.jpg', 'https://phimimg.com/upload/vod/20231115-1/05b6a26045a9965c52f5e32f3269f445.jpg', '<p>Sau lần quay về phát biểu tại trường cũ, Ben - một anh chàng 27 tuổi thành đạt - bắt đầu tự hỏi về ý nghĩa và hướng đi của cuộc đời mình. Một năm sau đó, nhờ cô bạn Alex và câu chuyện của những người xung quanh, Ben dần nhận ra rằng: số phận của mình phải do chính mình quyết định.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Josh Lawson","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Daniel Henshall","avatar":""},{"name":"Christian Clark","avatar":""},{"name":"Teressa Liane","avatar":""},{"name":"Felicity Ward","avatar":""},{"name":"Jodi Gordon","avatar":""},{"name":"Ed Kavalee","avatar":""},{"name":"Alan Brough","avatar":""},{"name":"Rob Carlton","avatar":""},{"name":"Tracy Mann","avatar":""},{"name":"Lachy Hulme","avatar":""},{"name":"Liliya May","avatar":""},{"name":"David James","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
