INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-hoi-gi-ben-khong', 'Ai Hỏi Gì Ben Không?', 'Any Questions for Ben?', 'ai hỏi gì ben không? any questions for ben? josh lawson rachael taylor daniel henshall christian clark teressa liane felicity ward jodi gordon ed kavalee alan brough rob carlton tracy mann lachy hulme liliya may david james ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-tinh-yeu', 'Cuộc Chiến Tình Yêu', 'This Means War', 'https://phimimg.com/upload/vod/20231115-1/297ef568f5d6b49aaabe8711d33a0a1c.jpg', 'https://phimimg.com/upload/vod/20231115-1/5e89595021495a3a26d7f7d87f1e0780.jpg', '<p>Hai chàng đặc vụ CIA, FDR (Chris Pine) và Tuck (Tom Hardy) là một đôi bạn thân. FDR đẹp trai, ngọt ngào, tự tin và là một tay &quot;sát gái&quot; có hạng, trong khi đó bạn thân của anh là Tuck lại hơi cục mịch và khá vụng về trong các vấn đề thuộc phạm trù lãng mạn. Cả hai đều không ngờ lại có một ngày phải đối đầu nhau vì cùng phải lòng cô nàng Lauren Scott (Reese Witherspoon) - một cô gái xinh đẹp làm chuyên viên kiểm định chất lượng sản phẩm cấp cao, tình bạn khăng khít giữa FDR và Tuck liệu có bị đe dọa?</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Laura Vandervoort","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Kasey Ryne Mazak","avatar":""},{"name":"Warren Christie","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Chelsea Handler","avatar":""},{"name":"John Paul Ruttan","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Rosemary Harris","avatar":""},{"name":"George Touliatos","avatar":""},{"name":"Clint Carleton","avatar":""},{"name":"Jenny Sl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
