INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-anh-la-chuyen-nho-2012', 'Tiếng Anh Là Chuyện Nhỏ', 'English Vinglish', 'https://phimimg.com/upload/vod/20231111-1/9481ad350c84c6a55f2fae3f5abe80ed.jpg', 'https://phimimg.com/upload/vod/20231111-1/c51b847f660574cb70227f604f56e4cb.jpg', '<p>Tiền bạc, danh vọng và tiếng Anh. Tại Ấn Độ, ba nhân tố này đóng một vai trò vô cùng quan trọng trong việc đánh giá và nhìn nhận một người nào đó. Câu chuyện trong English Vinglish xoay quanh Shashi, một phụ nữ không biết tiếng Anh và luôn cảm thấy bất an vì bị mọi người xung quanh và cả người thân trong gia đình chế giễu. Cho đến khi được em gái mời dự đám cưới ở New York, Sashi quyết định đăng ký vào một lớp học tiếng Anh để có thể giao tiếp nơi xứ người và hơn hết, tìm kiếm một sự chấp nhận. Qua những tình huống hài hước mà cô phải đối mặt, Sashi dần vượt qua được mặc cảm bản thân, trở thành một người phụ nữ tự tin và can đảm.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sridevi","avatar":""},{"name":"Adil Hussain","avatar":""},{"name":"Mehdi Nebbou","avatar":""},{"name":"Priya Anand","avatar":""},{"name":"Navika Kotia","avatar":""},{"name":"Shivansh Kotia","avatar":""},{"name":"Sujata Kumar","avatar":""},{"name":"Rajeev Ravindranathan","avatar":""},{"name":"Sumeet Vyas","avatar":""},{"name":"Ruth Aguilar","avatar":""},{"name":"Maria Romano","avatar":""},{"name":"Cory Hibbs","avatar":""},{"name":"Damian Thompson","avatar":""},{"name":"Sulabha Deshpande","avatar":""},{"name":"Ashwin Mathew","avatar":""},{"name":"Amitabh Bachchan","avatar":""},{"name":"Rajeev Pahuja","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324467);
