INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-chien', 'Tuyên Chiến', 'I Declare War', 'https://phimimg.com/upload/vod/20231111-1/e5703c5725979a4d6eaaadf9940fef2e.jpg', 'https://phimimg.com/upload/vod/20231111-1/0ee8c3ef4d01bd0748c6bc7e793159ab.jpg', '<p>Trò chơi chiến tranh mùa hè giữa những đứa trẻ hàng xóm trở nên nghiêm trọng chết người khi sự ghen tị và phản bội hòa vào nhau, trong bộ phim hài đen vui nhộn và kinh hoàng xen kẽ này kết hợp các phần ngang nhau của Lord of the Flies và Roald Dahl.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Siam Yu","avatar":""},{"name":"Gage Munroe","avatar":""},{"name":"Michael Friend","avatar":""},{"name":"Aidan Gouveia","avatar":""},{"name":"Mackenzie Munro","avatar":""},{"name":"Alex Cardillo","avatar":""},{"name":"Dyson Fyke","avatar":""},{"name":"Spencer Howes","avatar":""},{"name":"Andy Reid","avatar":""},{"name":"Kolton Stewart","avatar":""},{"name":"Richard Nguyen","avatar":""},{"name":"Alex Wall","avatar":""},{"name":"Eric Hanson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
