INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-cua-banh-my', 'Linh Hồn Của Bánh Mỳ', 'The Soul of Bread', 'https://phimimg.com/upload/vod/20231111-1/180a2d72a04f4af0d4ae32586f96785f.jpg', 'https://phimimg.com/upload/vod/20231111-1/bc3932db0e62d6ab10ff17e478fb0b0d.jpg', '<p>Cao Bính là một thợ làm bánh mỳ của &#39;Tiệm bánh mỳ Nguyên Thần&#39; ở Cao Hùng, anh là thanh mai trúc mã cùng lớn lên từ nhỏ với cô con gái Hiểu Bình của ông chủ Khưu. Anh chàng Cao Bính không chịu lấy ai ngoài Hiểu Bình đã lên kế hoạch chuẩn bị một màn cầu hôn bất ngờ vào một buổi tối, nhưng trong lòng Hiểu Bình luôn có một ước mơ khao khát được thực hiện, chính vì vậy cô chẳng có phản ứng gì với màn cầu hôn của Cao Bính...</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Michelle Chen","avatar":""},{"name":"Chen Handian","avatar":""},{"name":"Anthony Neely","avatar":""},{"name":"Janel Tsai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
