INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-cao-toc', 'Đường Cao Tốc', 'Motorway', 'https://phimimg.com/upload/vod/20231113-1/318350a6a849a5ef402bd21f8b61713c.jpg', 'https://phimimg.com/upload/vod/20231113-1/9694ccf91f95312cb084bf3790c930e2.jpg', '<p>Trần Tường là cảnh sát mới trong “đội xe tàng hình” của bộ giao thông. Một người có tâm huyết, ghét cái xấu như anh lái xe cảnh sát cải trang, ẩn núp trên đường để truy bắt mục tiêu. Tưởng Tân là “tay đua” của băng cướp chuyên nghiệp, hắn dựa vào kỹ thuật lướt xe “8000 vòng, 2km/h” ở góc vuông nên chưa từng thất bại. Trong khi cảnh sát Lư Phong sắp về hưu tính cách bảo thủ nhát gan, làm cộng sự với Trần Tường, cả hai khi làm nhiệm vụ thường trái ngược nhau. Trong một lần chạm mặt Tưởng Tân nhiều năm trước, Lư Phong dã có sự ám ảnh tâm lý rất lớn.Lần này Tưởng Tân tái xuất giang hồ gây án, Trần Tường truy đuổi vào hẻm nhỏ suýt mất mạng. Vì cứu Trần Tường, Lư Phong quay lại lái xe tàng hình chiến vớii bọn cướp liều lĩnh. Một trận chiến vô cùng căng thẳng, trậnn chiến bão táp sống chết trong gang tấc bùng nổ giữa cảnh sát và bọn cướp.</p>', 'Full', 1, 'single', 'completed', 10, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anthony Wong","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Barbie Hsu","avatar":""},{"name":"Li Guangjie","avatar":""},{"name":"Josie Ho","avatar":""},{"name":"Li Haitao","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Iva Law Wing-Han","avatar":""},{"name":"Au Hin-Wai","avatar":""},{"name":"Auston Lam","avatar":""},{"name":"Peter Lau Wai-Hung","avatar":""},{"name":"Frank Liu Zong-Ji","avatar":""},{"name":"Tracy Leung","avatar":""},{"name":"Julius Brian Si","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324467);
