INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dao-chet', 'Hòn Đảo Chết', 'Black Rock', 'https://phimimg.com/upload/vod/20231111-1/d01749cd547ca7189e19f37dd81b2835.jpg', 'https://phimimg.com/upload/vod/20231111-1/812acfb92d04a78c3d0c33c2c32332d6.jpg', '<p>Ba người bạn thời thơ ấu gạt bỏ những vấn đề cá nhân của họ sang một bên và đoàn tụ vào cuối tuần của một cô gái trên một hòn đảo xa xôi ngoài khơi bờ biển Maine. Một bước đi sai lầm đã biến kỳ nghỉ cuối tuần của họ thành một cuộc chiến sinh tồn chết chóc.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Aselton","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Will Bouvier","avatar":""},{"name":"Jay Paulson","avatar":""},{"name":"Anslem Richardson","avatar":""},{"name":"Carl K. Aselton III","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324467);
