INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gone', 'Gone', 'Gone', 'https://phimimg.com/upload/vod/20231111-1/15fc5c34346c99690d2df0dd94409bec.jpg', 'https://phimimg.com/upload/vod/20231111-1/7bfb8803c4952a7984bdb8b37f3e003f.jpg', '<p>Jill Conway đang cố gắng làm lại cuộc đời sau khi sống sót sau một vụ bắt cóc kinh hoàng. Mặc dù cô ấy đang gặp khó khăn, nhưng cô ấy đã từng bước nhỏ hướng tới cuộc sống bình thường bằng cách bắt đầu một công việc mới và mời chị gái của cô ấy, Molly, chuyển đến sống cùng cô ấy. Một buổi sáng đi làm về, Jill phát hiện ra rằng Molly đã biến mất, và cô chắc chắn rằng chính người đàn ông đã bắt cóc cô trước đó đã quay lại để trả thù.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Emily Wickersham","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Socratis Otto","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Katherine Moennig","avatar":""},{"name":"Sam Upton","avatar":""},{"name":"Ted Rooney","avatar":""},{"name":"Erin Carufel","avatar":""},{"name":"Amy Argyle","avatar":""},{"name":"Susan Hess","avatar":""},{"name":"Jeanine Jackson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
