INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mau-lanh-the-iceman', 'Sát Thủ Máu Lạnh', 'The Iceman', 'https://phimimg.com/upload/vod/20231111-1/6c7280e63dbf853446cfe01a1cf62f7b.jpg', 'https://phimimg.com/upload/vod/20231111-1/0a6d58a50648ba419f3153458a2b5d52.jpg', '<p>Sát Thủ Máu Lạnh | The Iceman (2013) Câu chuyện có thật của Richard Kuklinski, kẻ giết người khét tiếng và là mẫu người đàn ông gia đình. Khi đã bị bắt vào cuối năm 1986, không vợ, không con cái, không có bất kỳ mối quan hệ nào, tính sát thủ càng lúc trở nên đáng sợ trong con người của ông ta.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Shannon","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"David Schwimmer","avatar":""},{"name":"James Franco","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"John Ventimiglia","avatar":""},{"name":"Danny A. Abeckaser","avatar":""},{"name":"Ryan O''Nan","avatar":""},{"name":"McKaley Miller","avatar":""},{"name":"Hector Hugo","avatar":""},{"name":"Zoran Radanovich","avatar":""},{"name":"Shira Vilensky","avatar":""},{"name":"Kelly Lind","avatar":""},{"name":"John P. Fe","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324467);
