INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crawlspace', 'Crawlspace', 'Crawlspace', 'https://phimimg.com/upload/vod/20231111-1/2e73ac870b9df19bca561fad63f884a2.jpg', 'https://phimimg.com/upload/vod/20231111-1/e1a7bf244fce28f32ce59435ceaa719a.jpg', '<p>Một nhóm binh sĩ tinh nhuệ được cử đến để xâm nhập và giải cứu nhóm khoa học hàng đầu khỏi Pine Gap, khu liên hợp quân sự bí mật hàng đầu dưới lòng đất của Úc, sau khi nó bị tấn công bởi các lực lượng không xác định. Nhiệm vụ bị tổn hại khi họ gặp phải một phụ nữ trẻ không nhớ cô ấy là ai hoặc làm thế nào cô ấy đến được đó. Khi họ cố gắng trốn thoát, cả nhóm nhanh chóng phát hiện ra tất cả không phải như vẻ ngoài của nó và cơ sở đã trở thành nơi thử nghiệm cho một thứ gì đó độc ác hơn nhiều.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Amber Clayton","avatar":""},{"name":"Eddie Baroo","avatar":""},{"name":"Justin Batchelor","avatar":""},{"name":"Nicholas Bell","avatar":""},{"name":"John Brumpton","avatar":""},{"name":"Ditch Davey","avatar":""},{"name":"Leslie Simpson","avatar":""},{"name":"Fletcher Humphrys","avatar":""},{"name":"Peta Sergeant","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324467);
