INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thich-la-dat', 'Thích Là Đặt', 'Lay the Favorite', 'https://phimimg.com/upload/vod/20231109-1/7a9a06df36180c595d8c2358917bcc01.jpg', 'https://phimimg.com/upload/vod/20231109-1/cd528b9ae12db1de8b69c8a166cead1a.jpg', '<p>Tài năng của một cựu vũ công thoát y với những con số đã mang đến cho cô một công việc với một tay cờ bạc chuyên nghiệp, người điều hành một cuốn sách thể thao ở Las Vegas.</p>', 'Full', 1, 'single', 'completed', 22, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rebecca Hall","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Joshua Jackson","avatar":""},{"name":"Laura Prepon","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Joel Murray","avatar":""},{"name":"Hugo Armstrong","avatar":""},{"name":"Earl Maddox","avatar":""},{"name":"Rio Hackford","avatar":""},{"name":"Jo Newman","avatar":""},{"name":"Adam Kozlowski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324467);
