INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tiem-kich', 'Biệt Đội Tiêm Kích', 'Soar Into the Sun', 'https://phimimg.com/upload/vod/20231109-1/292730e38157d52e05ed883769cbc5e3.jpg', 'https://phimimg.com/upload/vod/20231109-1/d30257345f3718a5ad6d1c1db3c0cfa6.jpg', '<p>Trong Soar Into The Sun, Bi Rain vào vai phi công Tae-Hun. Sau màn trổ tài gây náo loạn triển lãm hàng không thường niên, TaeHun bị điều về đội bay chiến đấu mang tên Phi đội chiến đấu 21. Tại đây, anh dần thích nghi với môi trường mới nhưng vẫn không thể nào tránh khỏi sự đối đầu với thủ lĩnh của biệt đội, người được coi là tay súng đỉnh cao của Phi đội chiến đấu 21. Một ngày nọ, một chiếc tiêm kích không xác định được tung tích bất ngờ xuất hiện trên bầu trời Seoul, báo hiệu cuộc chiến tranh hạt nhân diện rộng.Tae-hun cùng những đồng đội của mình chiến đấu để bảo vệ sự an bình cho những người dân vô tội, đồng thời hoàn thành sứ mệnh tối thượng, mạo hiểm khi quyết định lao thẳng vào lãnh thổ của đối phương…</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Rain","avatar":""},{"name":"Yu Jun-sang","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Kim Sung-su","avatar":""},{"name":"Lee Ha-na","avatar":""},{"name":"Lee Jong-suk","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Jung Suk-won","avatar":""},{"name":"Baek Bong-ki","avatar":""},{"name":"Park Hyo-joon","avatar":""},{"name":"Choi Beom-ho","avatar":""},{"name":"Ryoo Je-seung","avatar":""},{"name":"Jung Yoon-suk","avatar":""},{"name":"Ha Soo-ho","avatar":""},{"name":"Jung Han-yong","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Yang Joon-mo","avatar":""},{"name":"Jon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324467);
