INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-mien-nam-hoang-da', 'Quái Vật Miền Nam Hoang Dã', 'Beasts of the Southern Wild', 'https://phimimg.com/upload/vod/20231110-1/751fac341b9d456958db6034b345c289.jpg', 'https://phimimg.com/upload/vod/20231110-1/b19b6aa7ab327799be976866c5ffdfb0.jpg', '<p>Hushpuppy, một cô bé sáu tuổi gan dạ, sống với cha mình, Wink ở &#39;the Bathtub&#39;, một cộng đồng phía nam Delta ở rìa thế giới. Tình yêu mãnh liệt của Wink chuẩn bị cho cô ấy bước vào sự sáng tỏ của vũ trụ—trong khoảng thời gian mà anh ấy không còn ở đó để bảo vệ cô ấy nữa. Khi Wink mắc phải một căn bệnh bí ẩn, thiên nhiên trở nên bất ổn—nhiệt độ tăng cao và các tảng băng tan chảy, giải phóng một đội quân sinh vật thời tiền sử được gọi là bò rừng châu Âu. Khi nước dâng cao, bò rừng châu âu kéo đến và sức khỏe của Wink yếu dần, Hushpuppy lên đường tìm kiếm người mẹ đã mất của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Quvenzhané Wallis","avatar":""},{"name":"Dwight Henry","avatar":""},{"name":"Levy Easterly","avatar":""},{"name":"Gina Montana","avatar":""},{"name":"Lowell Landes","avatar":""},{"name":"Pamela Harper","avatar":""},{"name":"Amber Henry","avatar":""},{"name":"Jonshel Alexander","avatar":""},{"name":"Nicholas Clark","avatar":""},{"name":"Joseph Brown","avatar":""},{"name":"Henry D. Coleman","avatar":""},{"name":"Kaliana Brower","avatar":""},{"name":"Phillip Lawrence","avatar":""},{"name":"Hannah Holby","avatar":""},{"name":"Jimmy Lee Moore","avatar":""},{"name":"Jovan Hathaway","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324467);
