INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('6-vien-dan', '6 Viên Đạn', '6 Bullets', 'https://phimimg.com/upload/vod/20231109-1/2871e3b4a4c84c1be72bac1edc41bd29.jpg', 'https://phimimg.com/upload/vod/20231109-1/0a4b286443fcb86b3bb00f1928757af6.jpg', '<p>Một lính đánh thuê giải nghệ với biệt tài tìm trẻ em mất tích được 1 võ sĩ thuê tìm cô con gái đã bị bắt cóc của mình. Và người lính đánh thuê kia lại bắt đầu công việc của mình. Nhưng lần này, việc tìm kiếm không chút đơn giản...</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Kris Van Damme","avatar":""},{"name":"Bianca Bree","avatar":""},{"name":"Joe Flanigan","avatar":""},{"name":"Anna-Louise Plowman","avatar":""},{"name":"Charlotte Beaumont","avatar":""},{"name":"Uriel Emil Pollack","avatar":""},{"name":"Louis Dempsey","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324467);
