INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-long-dai-chien', 'Khủng Long Đại Chiến', 'Speckles: The Tarbosaurus', 'https://phimimg.com/upload/vod/20231109-1/5f48b18b3c90adfc82fc41d3e2cb8753.jpg', 'https://phimimg.com/upload/vod/20231109-1/a102fd9562c2c8dc2d642ff27fe196a7.jpg', '<p>Câu chuyện trong Tarbosaurus diễn ra ở thời điểm 80 triệu năm về trước. Lúc ấy, loài khủng long thống trị lãnh thổ Hàn Quốc cũng hệt như cách chúng tung hoành bên dưới mọi vùng trời còn lại của thế giới. Một phần lãnh địa khủng long mà bây giờ được biết đến dưới cái tên Jeonnam Yeosu là rừng “nhà” của giống loài đặc chủng: Tarbosaurus.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Hyeong-seok","avatar":""},{"name":"Shin Yong-woo","avatar":""},{"name":"Koo Ja-hyoung","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324467);
