INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-40', 'Tuổi 40', 'This Is 40', 'https://phimimg.com/upload/vod/20231109-1/5fc04e79ea6addcbd9ae5ba0c146eb90.jpg', 'https://phimimg.com/upload/vod/20231109-1/b9f5817f600fa4d9bccba17463c0b8a0.jpg', '<p>Trong phần hậu truyện này của &quot;Dính bầu&quot;, vợ chồng Pete và Debbie sẽ phải vật lộn với cuộc sống thực tế khi họ bước vào tuổi trung niên.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Maude Apatow","avatar":""},{"name":"Iris Apatow","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Graham Parker","avatar":""},{"name":"Albert Brooks","avatar":""},{"name":"Lena Dunham","avatar":""},{"name":"Annie Mumolo","avatar":""},{"name":"Robert Smigel","avatar":""},{"name":"Charlyne Yi","avatar":""},{"name":"Lisa Darr","avatar":""},{"name":"Billie Joe Armstrong","avatar":""},{"name":"Michael Ian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
