INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tau-bi-an', 'Con Tàu Bí Ẩn', 'The Philadelphia Experiment', 'https://phimimg.com/upload/vod/20231108-1/630b4870ba015c1c4f562b0833db0bd8.jpg', 'https://phimimg.com/upload/vod/20231108-1/54cee8842ef98493e847eebdee8ca660.jpg', '<p>Chính phủ Hoa Kì thực hiện một dự án nghiên cứu bí mật, khởi động lại Thí nghiệm Philadelphia Experiment huyền thoại hồi Thế Chiến II, nhằm tạo ra thiết bị tàng hình có thể làm tàu chiến trở nên tàng hình. Thí nghiệm đem lại kết quả thành công và khiến con tàu đầu tiên (tàu khu trục Eldride) vốn đã biến mất trong cuộc thí nghiệm đầu năm 1943 tái xuất hiện. Thế giới của thế kỉ 21 đứng trước đại họa. Giờ người sống sót duy nhất từ thí nghiệm năm 1943 ấy và cháu gái ông phải ngăn chặn đại họa.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ryan Robbins","avatar":""},{"name":"Nicholas Lea","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Emilie Ullerup","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Lauro Chartrand","avatar":""},{"name":"Gina Holden","avatar":""},{"name":"John Reardon","avatar":""},{"name":"Allison Hossack","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324468);
