INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tu-ha-dong-2', 'Sư Tử Hà Đông 2', 'The Lion Roars 2', 'null', 'https://phimimg.com/upload/vod/20231108-1/440e94dbbd86d575a4e49333530cbcbd.jpg', '<p>Nữ hiệp Vương Nguyệt Anh hận đàn ông không chung tình, cả ngày ra tay can thiệp vào chuyện gia đình người khác, còn nghiêm cấm tất cả đàn ông lấy vợ, khiến dân tình phẫn nộ bất bình. Cha của Nguyệt Anh là Vương Thừa Nhan biết Nguyệt Anh sẽ không yêu phàm phu tục tử, vì hạnh phúc cả đời của con gái, ông cố ý sắp đặt một cuộc đọ sức giữa người có mưu lược nhất trấn là Đông Phương Minh Lượng, và Nguyệt Anh để biện luận về tình yêu. Sau một hồi đọ sức, cuối cùng hai người đã lập một điều cá cược, giao ước nếu trong vòng một năm Minh Lương không thay lòng đổi dạ với Nguyệt Anh thì hai người sẽ kết làm vợ chồng...</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cecilia Cheung Pak-Chi","avatar":""},{"name":"Xiao Shenyang","avatar":""},{"name":"Victor Huang","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"He Jiong","avatar":""},{"name":"Zhao Benshan","avatar":""},{"name":"Liu Yuqi","avatar":""},{"name":"Jerry Wu","avatar":""},{"name":"Zhang Xinyu","avatar":""},{"name":"Qi Ji","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Du Kang","avatar":""},{"name":"Shen Fang-Xi","avatar":""},{"name":"Zhang Zhihong","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324468);
