INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dinh-toi-cao', 'Quyết Định Tối Cao', 'Maximum Conviction', 'https://phimimg.com/upload/vod/20231108-1/196615079ef9b35f9515c538880dfefe.jpg', 'https://phimimg.com/upload/vod/20231108-1/bb6e34b98ea3ac8413ce7866d1ee428a.jpg', '<p>Khi cựu đặc nhiệm xã hội đen Cross và đối tác của anh ta là Manning được giao nhiệm vụ phá dỡ một nhà tù cũ, họ phải giám sát sự xuất hiện của hai nữ tù nhân bí ẩn. Chẳng bao lâu sau, một lực lượng lính đánh thuê tinh nhuệ đã tấn công nhà tù để tìm kiếm những người mới đến. Khi danh tính thực sự của những người phụ nữ được tiết lộ, Cross nhận ra rằng anh ta đang mắc kẹt giữa một thứ gì đó lớn hơn nhiều so với những gì anh ta tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Steve Austin","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Bren Foster","avatar":""},{"name":"Aliyah O''Brien","avatar":""},{"name":"Steph Song","avatar":""},{"name":"Toby Levins","avatar":""},{"name":"J.J. Makaro","avatar":""},{"name":"Terrance Leigh","avatar":""},{"name":"Teach Grant","avatar":""},{"name":"Ian Robison","avatar":""},{"name":"Brian Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
