INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('magic-mike', 'Magic Mike', 'Magic Mike', 'https://phimimg.com/upload/vod/20231108-1/52b3ab4f63aba286c41fc37da5a00e66.jpg', 'https://phimimg.com/upload/vod/20231108-1/3092a54442f4985fb67794db40e4f115.jpg', '<p>Mike Lane là một người đàn ông ba mươi tuổi sống ở Tampa, Florida. Ban ngày anh ta làm việc như một mái nhà trong khi vào ban đêm, như Magic Mike, anh ta là điểm thu hút ngôi sao của các vị vua của Tampa, một nhóm vũ nữ thoát y nam. Bí mật, anh ta muốn ra ngoài để tiếp tục kinh doanh sản xuất đồ nội thất dự kiến nhưng xếp hạng tín dụng của anh ta ngăn chặn khoản vay ngân hàng cho việc này mặc dù tiết kiệm đáng kể của mình. Một đêm Adam, một người bạn làm việc tuổi teen của Mike, theo anh ta đến câu lạc bộ và, khi một trong những hành động không thể tiếp tục, anh ta bị chiếm ưu thế để thoát y - trở thành một cú đánh lớn. Tuy nhiên, thành công đi vào đầu anh ta và những hành động dại dột của mình không chỉ đe dọa sẽ gây nguy hiểm cho mối quan hệ của chị gái của mình với Mike mà còn là tham vọng của Mike.</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Alex Pettyfer","avatar":""},{"name":"Cody H. Carolin","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"James Martin Kelly","avatar":""},{"name":"Reid Carolin","avatar":""},{"name":"Adam Rodríguez","avatar":""},{"name":"Kevin Nash","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Michael Roark","avatar":""},{"name":"Betsy Brandt","avatar":""},{"name":"Mircea Monroe","avatar":""},{"name":"Avery","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
