INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('atm-cam-bay-luc-nua-dem', 'ATM: Cạm Bẫy Lúc Nửa Đêm', 'ATM', 'https://phimimg.com/upload/vod/20231108-1/b07ca3e4f9dfb38d13ea1837febb4d84.jpg', 'https://phimimg.com/upload/vod/20231108-1/7acbf5ffb9308c61a3ef9bbb2f001432.jpg', '<p>Sau bữa tiệc Giáng sinh ấm cúng, ba người đồng nghiệp Emily, Corey và David vui vẻ ra về. Trên đường đi, họ tạt qua một trạm ATM để rút tiền, lúc này đã quá nửa đêm. Khi vào bên trong trạm và nhìn ra ngoài, cả ba trông thấy một người đàn ông giấu mặt đứng nhìn họ trong đêm tối. Chỉ vài phút sau, người đàn ông giấu mặt lộ nguyên hình là một tên sát nhân bệnh hoạn. Bị kẹt lại trong trạm ATM, Emily, Corey và David chứng kiến những trò chơi man rợ của hắn. Chiếc máy ATM giờ trở thành một chiếc lồng mỏng manh, còn ba thanh niên biến thành những con mồi của kẻ giết người...</p>', 'Full', 1, 'single', 'completed', 11, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alice Eve","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"Aaron Hughes","avatar":""},{"name":"Will Woytowich","avatar":""},{"name":"Steve Nagribianko","avatar":""},{"name":"Glen Thompson","avatar":""},{"name":"Robert Huculak","avatar":""},{"name":"Ernesto Griffith","avatar":""},{"name":"Bryan Terrell Clark","avatar":""},{"name":"Dan De Jaeger","avatar":""},{"name":"Omar Alex Khan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
