INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zambezia-thanh-pho-cac-loai-chim', 'Zambezia: Thành Phố Các Loài Chim', 'Zambezia', 'https://phimimg.com/upload/vod/20231108-1/7cb54767e0bc3cabfda60cf5a51350a1.jpg', 'https://phimimg.com/upload/vod/20231108-1/8e540744fded571718e0e014e401eeba.jpg', '<p>Một thành phố chim nhộn nhịp trên các cạnh của hùng vĩ Victoria Falls, &quot;Zambezia&quot; là câu chuyện của Kai, nhưng chim ưng trẻ cao tinh thần người đi đến thành phố chim &quot;Zambezia&quot;, nơi ông phát hiện ra sự thật về nguồn gốc của mình và, trong việc bảo vệ thành phố, học làm thế nào để là một phần của một cộng đồng.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2012, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"Jeremy Suarez","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Noureen DeWulf","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Jamal Mixon","avatar":""},{"name":"David Shaughnessy","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Lee Duru","avatar":""},{"name":"Phil LaMarr","avatar":""},{"name":"Zolani Mahola","avatar":""},{"name":"Deep Roy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324468);
