INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ganh-xiec-mat-troi', 'Gánh Xiếc Mặt Trời', 'Cirque du Soleil: Worlds Away', 'https://phimimg.com/upload/vod/20231108-1/e5916eef955426f481e7339cf584cac2.jpg', 'https://phimimg.com/upload/vod/20231108-1/85465701aff0b501c7aaa5e15f3dde96.jpg', '<p>Một câu chuyện gốc có các màn trình diễn của Cirque du Soleil. Một phụ nữ trẻ bị mê hoặc bởi một Aerialist. Khi họ rơi vào thế giới mộng mơ của Cirque du Soleil và bị tách ra, họ du hành qua các thế giới lều khác nhau để cố gắng tìm thấy nhau.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Erica Linz","avatar":""},{"name":"Igor Zaripov","avatar":""},{"name":"Matt Gillanders","avatar":""},{"name":"Jason Berrent","avatar":""},{"name":"Dallas Barnett","avatar":""},{"name":"Sophia Elisabeth","avatar":""},{"name":"Lutz Halbhubner","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
