INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hiep-si-diet-rong', 'Nữ Hiệp Sĩ Diệt Rồng', 'Dragon Age: Dawn of the Seeker', 'https://phimimg.com/upload/vod/20231108-1/56a7246a97923d89167b2313c11c55fc.jpg', 'https://phimimg.com/upload/vod/20231108-1/35ed546b4c0ce0924e5880191b6629b9.jpg', '<p>Mang tên gọi Dragon Age: Dawn of the Seeker, bộ phim hoạt hình kể về câu chuyện của một cô gái có tuổi thơ bất hạnh khi phải tận mắt chứng kiến cái chết của những người thân ngay trước mắt mình. Mang trong mình sự căm hận và đau thương, những uất hận từ ngày còn thơ bé trở thành động lực để cô trở nên mạnh mẽ hơn trong cuộc chiến đòi lại công lý cho mình.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"John Swasey","avatar":""},{"name":"Mike McFarland","avatar":""},{"name":"Pam Dougherty","avatar":""},{"name":"R. Bruce Elliott","avatar":""},{"name":"Luci Christian","avatar":""},{"name":"Colleen Clinkenbeard","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324468);
