INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-sung-diet-quy', 'Những Tay Súng Diệt Quỷ', 'Gallowwalkers', 'https://phimimg.com/upload/vod/20231108-1/b00a1ff8a85b8e1b3a7bf25238348ea6.jpg', 'https://phimimg.com/upload/vod/20231108-1/5de5a0c2208c2f5889586bf18ff7a7a8.jpg', '<p>Bộ phim kể về một tay súng bí ẩn, Aman, là con trai của một nữ tu, người đã phá vỡ giao ước với Thiên Chúa để đảm bảo sự sống còn của mình. Hành động này mang lại một lời nguyền trên Aman - tất cả những người chết bởi khẩu súng của anh sẽ trở lại. Từ đó, anh bị săn đuổi bởi một băng đảng của anh là nạn nhân trước đây, dẫn đầu bởi zombie Kansa. Aman tuyển mộ Fabulos, một chiến binh trẻ tuổi mới, để chiến đấu bên cạnh anh....</p>', 'Full', 1, 'single', 'completed', 20, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Riley Smith","avatar":""},{"name":"Tanit Phoenix","avatar":""},{"name":"Simona Brhlikova","avatar":""},{"name":"Steven Elder","avatar":""},{"name":"Jenny Gago","avatar":""},{"name":"Kevin Howarth","avatar":""},{"name":"Alyssa Pridham","avatar":""},{"name":"Alex Avant","avatar":""},{"name":"Hector Hugo","avatar":""},{"name":"Jack Bowyer","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"Page Falkinburg Jr.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324468);
