INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-vu-cuop-tau', 'Một Vụ Cướp Tàu', 'A Hijacking', 'https://phimimg.com/upload/vod/20231108-1/7330e3b2e638bd1eebfa5c1c47731e4f.jpg', 'https://phimimg.com/upload/vod/20231108-1/20cfa223e104160c3a7a09f5a2f85696.jpg', '<p>A Hijacking - Kapringen (Một Vụ Cướp Tàu) là một bộ phim tâm lý ly kỳ năm 2012 của Đan Mạch, kịch bản và đạo diễn bởi Tobias Lindholm. Phim được công chiếu tại Liên hoan phim quốc tế Venice lần thứ 69.
 Con tàu chở hàng mang tên MV Rozen mang cờ Đan Mạch đang trong hành trình cập cảng thì bị một toán cướp biển Somali chiếm giữ ở Ấn Độ Dương. Trên tàu có đầu bếp Mikkel (Pilou Asbæk) và kỹ sư Jan (Roland Møller), cùng những thành viên khác trong thủy thủ đoàn bị bắt làm con tin. Với yêu cầu tiền chuộc lên đến hàng triệu đô la, cuộc chơi sinh tử giữa các CEO của công ty vận tải biển và hải tặc Somali bắt đầu. Mọi chuyện trở nên nghiêm trọng hơn khi băng hải tặc rơi vào các cuộc đàm phán cân não leo thang và các vấn đề chính trị với chính quyền ở thủ đô Copenhagen...</p>', 'Full', 1, 'single', 'completed', 21, 2012, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Pilou Asbæk","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"Gary Skjoldmose Porter","avatar":""},{"name":"Abdihakin Asgar","avatar":""},{"name":"Amalie Ihle Alstrup","avatar":""},{"name":"Amalie Vulff Andersen","avatar":""},{"name":"Linda Laursen","avatar":""},{"name":"Keith Pearson","avatar":""},{"name":"Allan Arnby","avatar":""},{"name":"Bettina Schjerlund","avatar":""},{"name":"Derrick Dharmakan","avatar":""},{"name":"Juma Mvita","avatar":""},{"name":"Min Kyan \"Thura&a","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
