INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-gia-dinh-cua-anh', 'Em Là Gia Đình Của Anh', 'Evim Sensin', 'https://phimimg.com/upload/vod/20231113-1/9904f62a7fef240202fde200340aa922.jpg', 'https://phimimg.com/upload/vod/20231113-1/12e8d19994927d5b88264f08181b4761.jpg', '<p>&quot;Evim Sensin&quot; là một bộ phim lãng mạn của Thổ Nhĩ Kỳ. Nội dung phim kể về câu chuyện tình yêu giữa Ali và Leyla. Ali là một chàng trai đẹp trai, giàu có và thành đạt, trong khi đó Leyla là một cô gái trẻ, xinh đẹp và có tình yêu với nghệ thuật.Trong một lần đi du lịch, Ali và Leyla tình cờ gặp nhau và đem lòng yêu nhau. Tuy nhiên, chính sự khác biệt về địa vị xã hội và nền văn hóa của hai người khiến cho tình yêu của họ gặp nhiều trắc trở và thử thách.Phim &quot;Evim Sensin&quot; là một bộ phim lãng mạn, đầy cảm xúc về tình yêu và sự hy sinh. Câu chuyện của Ali và Leyla được tái hiện một cách đầy cảm hứng và sâu lắng, tạo nên sức hút đặc biệt đối với khán giả yêu thích phim lãng mạn.</p>', 'Full', 1, 'single', 'completed', 21, 2012, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Özcan Deniz","avatar":""},{"name":"Fahriye Evcen","avatar":""},{"name":"Sait Genay","avatar":""},{"name":"Özay Fecht","avatar":""},{"name":"Levent Öktem","avatar":""},{"name":"Güneş Hayat","avatar":""},{"name":"Teoman Kumbaracıbaşı","avatar":""},{"name":"Gizem Denizci","avatar":""},{"name":"Barış Yalçın","avatar":""},{"name":"Volga Sorgu","avatar":""},{"name":"Ayşe Melike Çerçi","avatar":""},{"name":"Zeynep Ender İge","avatar":""},{"name":"Efe Deprem","avatar":""},{"name":"Pelin Dinçer","avatar":""},{"name":"Kayhan Yıldızoğlu","avatar":""},{"name":"Ergin Torun","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","i