INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-luot-song', 'Huyền Thoại Lướt Sóng', 'Chasing Mavericks', 'https://phimimg.com/upload/vod/20231103-1/f32c4f37f3a1ffbd25b75eec16380130.jpg', 'https://phimimg.com/upload/vod/20231103-1/127b515722aa617051d489077c417ff3.jpg', '<p>Chasing Mavericks (tên ban đầu là Of Men and Mavericks),&nbsp;phim&nbsp;được chỉ đạo bởi&nbsp;Curtis Hanson,&nbsp;Gerard Butler&nbsp;sẽ đóng vai người thầy của Moriarty (do diễn viên mới nổi&nbsp;Jonny Weston&nbsp;thủ vai), 1 tay lướt ván đã làm nên tên tuổi tại Mavericks ở Phía bắc California.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Jonny Weston","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Leven Rambin","avatar":""},{"name":"Peter Mel","avatar":""},{"name":"Zach Wormhoudt","avatar":""},{"name":"Devin Crittenden","avatar":""},{"name":"Taylor Handley","avatar":""},{"name":"Cooper Timberline","avatar":""},{"name":"Maya Raines","avatar":""},{"name":"Harley Graham","avatar":""},{"name":"Jenica Bergere","avatar":""},{"name":"James Anthony Cotton","avatar":""},{"name":"Channon Roe","avatar":""},{"name":"Thomas Freil","avatar":""},{"name":"L. Pet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
