INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-luot-song', 'Huyền Thoại Lướt Sóng', 'Chasing Mavericks', 'huyền thoại lướt sóng chasing mavericks gerard butler jonny weston elisabeth shue abigail spencer leven rambin peter mel zach wormhoudt devin crittenden taylor handley cooper timberline maya raines harley graham jenica bergere james anthony cotton channon roe thomas freil l. pet ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-trong-thu-khong', 'Hồi Trống Thu Không', 'Curfew', 'https://phimimg.com/upload/vod/20231103-1/2472fa943fd8fba9fc9dbd1b5291a21a.jpg', 'https://phimimg.com/upload/vod/20231103-1/b5c51b06ebb1fe38d4541fbc8c38dca6.jpg', '<p>Curfew kể về một người đàn ông có tên Richie, trong giây phút đen tối nhất của cuộc đời đã quyết định tự sát. Bộ phim mở đầu vô cùng ấn tượng với cảnh Richie nằm trong bồn tắm đầy máu, dao lam ở tay đang cố gắng hoàn thành nốt việc kết liễu đời mình thì bỗng điện thoại reo vang. Người em gái từ lâu cắt đứt liên lạc với anh khẩn khoản nhờ anh trông giúp con gái (Sophie) trong khi cô vắng nhà. Và thế là Richie quyết định hoãn lại cái chết một vài tiếng để đưa cô cháu gái đi chơi... Shawn Christensen đã tự viết kịch bản, tự đạo diễn, tự mình đóng vai chính rồi cũng tự biên tập. Thậm chí bài hát mà Sophie yêu thích trong đoạn nhảy múa ở khu chơi bowling cũng là do chính anh sáng tác và thể hiện. Một phần nguyên do là mấy năm trước, anh viết kịch bản phim Abduction, do Taylor Lautner thủ vai chính, bị chê dở tệ. Anh đổ lỗi cho các nhà làm phim làm hỏng kịch bản và quyết định trong bộ phim ngắn này sẽ tự tay làm từ đầu tới cuối. Và anh đã thành công. Anh thể hiện khá đạt sự trống rỗng, vô hồn của Richie cùng sự suy nhược thần kinh của kẻ luôn rắp ranh ý định tự tử. &quot;Curfew&quot; tôn vinh giá trị gia đình và tầm quan trọng của cảm giác được cần đến, được có ích cho đời.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fatima Ptacek","avatar":""},{"name":"Shawn Christensen","avatar":""},{"name":"Dana Segal","avatar":""},{"name":"Kirsten Holly Smith","avatar":""},{"name":"Kim Allen","avatar":""},{"name":"Helga Athineos","avatar":""},{"name":"gino patti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
