INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nhuc-2-qua-gioi-han', 'Ô Nhục 2: Quá Giới Hạn', 'Beyond Outrage', 'https://phimimg.com/upload/vod/20231103-1/cfbee962f7a37fe6e6557812cec5f122.jpg', 'https://phimimg.com/upload/vod/20231103-1/c8f0a9b1bb753fcd99c1a6a74d1641cf.jpg', '<p>Bộ phim nối dài câu chuyện Outrage được ra mắt khán giả vào năm 2010, kể về xung đột giữa các thế hệ khi một gia đình Yakuza lớn mạnh quá tầm kiểm soát. Cũng trong giai đoạn chuyển giao nhạy cảm, gia đình này bị phá hoại ngầm bởi một tay cảnh sát tham nhũng ác độc.</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeshi Kitano","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Shun Sugata","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Shigeru Kōyama","avatar":""},{"name":"Hirofumi Arai","avatar":""},{"name":"Kenta Kiritani","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Hakuryu","avatar":""},{"name":"Sansei Shiomi","avatar":""},{"name":"Akira Nakao","avatar":""},{"name":"Hideo Nakano","avatar":""},{"name":"Katsunori Takahashi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324468);
