INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-nguoc', 'Thế Giới Ngược', 'Upside Down', 'https://phimimg.com/upload/vod/20231103-1/3f86cd83ec9ecbc568925cd582a98714.jpg', 'https://phimimg.com/upload/vod/20231103-1/79eb6c9143ea65d4e8a442dd9f1febf1.jpg', '<p>Với sự giúp đỡ của một công thức, một chàng trai bình thường, Adam, đã bất chấp thế giới, quy luật khoa học và lực hấp dẫn để lấy lại tình yêu thời thơ ấu của mình, Eden, người sống ở một thế giới khác.</p>', 'Full', 1, 'single', 'completed', 23, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kirsten Dunst","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"James Kidnie","avatar":""},{"name":"Holly Uloth","avatar":""},{"name":"Blu Mankuma","avatar":""},{"name":"Nicholas Rose","avatar":""},{"name":"Vlasta Vrana","avatar":""},{"name":"Kate Trotter","avatar":""},{"name":"Janine Theriault","avatar":""},{"name":"Vincent Messina","avatar":""},{"name":"Cole K. Mickenzie","avatar":""},{"name":"Paul Ahmarani","avatar":""},{"name":"Carolyn Guillet","avatar":""},{"name":"Jesse Sherman","avatar":""},{"name":"Francis B. Goldberg","avatar":""},{"name":"Franco","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324468);
