INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-nguoc', 'Thế Giới Ngược', 'Upside Down', 'thế giới ngược upside down kirsten dunst jim sturgess timothy spall james kidnie holly uloth blu mankuma nicholas rose vlasta vrana kate trotter janine theriault vincent messina cole k. mickenzie paul ahmarani carolyn guillet jesse sherman francis b. goldberg franco ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-alpha', 'Biệt Đội Alpha', 'Tom Clancy''s Ghost Recon Alpha', 'https://phimimg.com/upload/vod/20231103-1/0668ffa6ae680d473876431673cb5f7c.jpg', 'https://phimimg.com/upload/vod/20231103-1/1635ba260aa5913339f2ad45eac3f4d7.jpg', '<p>Bộ phim xoay quanh câu chuyện về bốn nhân vật chính, đây đồng thời cũng là hình ảnh đại diện cho bốn lớp nhân vật có thể chơi được trong game. Cốt truyện của bộ phim dựa theo các sự kiện diễn ra ngay trước bối cảnh chính trong game, đây cũng là bước ngoặt có tính đột phá của toàn bộ nội dung câu chuyện. Cụ thể, đó sẽ là cuộc tấn công tiến vào một thành phố lớn tại châu Âu. Các cảnh trong phim được quay tại một khu vực mà trong trò chơi, đó sẽ là một bản đồ dành cho chế độ mutilplayer đầy hấp dẫn. Đặc biệt, trong bộ phim, đạo diễn đã cố ý ẩn dấu một mã số bí mật, cho phép người chơi khám phá và sử dụng nó thông qua hệ thống Ghost Recon Network để kích hoạt và nhận được một vũ khí bí mật, độc quyền trong game.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlotte Rampling","avatar":""},{"name":"Radek Brůna","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Keith Gilmore","avatar":""},{"name":"Pavel Ledinsky","avatar":""},{"name":"Erich Redman","avatar":""},{"name":"Joplin Sibtain","avatar":""},{"name":"Daniel Svoboda","avatar":""},{"name":"Charles Venn","avatar":""},{"name":"Nick Von Schlippe","avatar":""},{"name":"Karel Dobrý","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324468);
