INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-alpha', 'Biệt Đội Alpha', 'Tom Clancy''s Ghost Recon Alpha', 'biệt đội alpha tom clancy''s ghost recon alpha charlotte rampling radek brůna mark ivanir keith gilmore pavel ledinsky erich redman joplin sibtain daniel svoboda charles venn nick von schlippe karel dobrý ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-dac-vu-xinh-dep', 'Nữ Đặc Vụ Xinh Đẹp', 'So Undercover', 'https://phimimg.com/upload/vod/20231103-1/93196725051ae616a6de168c71071820.jpg', 'https://phimimg.com/upload/vod/20231103-1/966ffba149f9500b1ea540a1c7a1659e.jpg', '<p>Nhờ tài thao lược như điệp viên chuyên nghiệp mà Molly đã được FBI thuê để bảo vệ cho con gái của một ông trùm. Rất ngạc nhiên và không kém phần tự kiêu, Molly hỏi: “Cục an ninh không còn ai khác làm việc này à?”. Sau khi đã trở thành đặc vụ của FBI, Molly từ một cô nàng tomboy bắt đầu biến thành một nữ sinh đại học thật nhẹ nhàng, tinh tế. Và quá trình khổ luyện của cô nàng cũng bắt đầu, từ đi giày cao gót đến ăn mặc thật gợi cảm. Bước vào trường đại học, nhiều chuyện dở khóc dở cười bắt đầu diễn ra với cô nàng thám tử tư vừa được &quot;nâng level&quot;. Qua đó, Molly bất ngờ phát hiện ra rằng không phải tất cả mọi người trong trường đều như họ vẫn thể hiện, trong đó có cả chính cô.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miley Cyrus","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Mike O''Malley","avatar":""},{"name":"Joshua Bowman","avatar":""},{"name":"Lauren McKnight","avatar":""},{"name":"Kelly Osbourne","avatar":""},{"name":"Eloise Mumford","avatar":""},{"name":"Megan Park","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Matthew Settle","avatar":""},{"name":"Autumn Reeser","avatar":""},{"name":"Jimmy Lee Jr.","avatar":""},{"name":"Morgan Calhoun","avatar":""},{"name":"Ric Reitz","avatar":""},{"name":"Leticia Jimenez","avatar":""},{"name":"Ashley Treadaway","avatar":""},{"name":"Darcel Whi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
