INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-dac-vu-xinh-dep', 'Nữ Đặc Vụ Xinh Đẹp', 'So Undercover', 'nữ đặc vụ xinh đẹp so undercover miley cyrus jeremy piven mike o''malley joshua bowman lauren mcknight kelly osbourne eloise mumford megan park alexis knapp matthew settle autumn reeser jimmy lee jr. morgan calhoun ric reitz leticia jimenez ashley treadaway darcel whi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scooby-doo-mat-na-chim-ung-xanh', 'Scooby Doo! Mặt nạ chim ưng xanh', 'Scooby-Doo! Mask of the Blue Falcon', 'https://phimimg.com/upload/vod/20231103-1/ed87b825131a01272246a39a44131310.jpg', 'https://phimimg.com/upload/vod/20231103-1/a622a8888a5e52897eda43b171c0d72e.jpg', '<p>Mega Mondo Pop Cartoon-a-Con ở California đầy nắng đánh dấu vị trí bí ẩn trong cuộc phiêu lưu Scooby-Doo nguyên bản hoàn toàn mới này! Herculoids Frankenstein Jr. và Space Ghost chỉ là một vài trong số các nhân vật truyện tranh nổi tiếng tiêu biểu tại hội nghị độc đáo cộng với việc có một buổi ra mắt bộ phim trị giá siêu đô la với sự tham gia của Scooby-Doo và các siêu anh hùng được yêu thích nhất mọi thời đại của Shaggy Blue Falcon và Dynomutt! Vì vậy, khi nhân vật phản diện khủng khiếp Mr. Hyde giải phóng những con dơi quái vật, những con chó săn hú và chất nhờn nham hiểm vào các lễ hội, đó là lúc Mystery Incorporated lần theo manh mối và đặt bẫy quái vật của chúng. Nhưng đó là nhóm gắn thẻ siêu năng lực chuyên ăn bánh pizza gồm Shaggy và Scooby-Doo, những người đã khai thác được siêu anh hùng bên trong của họ để ngăn chặn toàn bộ sự kiện bị bao trùm bởi chất nhờn màu xanh lá cây ma quái! Thích ngay trên Dog Wonder!</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Welker","avatar":""},{"name":"Mindy Cohn","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Gregg Berger","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Billy West","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324468);
