INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-sat', 'Tay Đấm Sắt', 'The Man with the Iron Fists', 'https://phimimg.com/upload/vod/20231103-1/08704e8f612a558138621ef0cdf30182.jpg', 'https://phimimg.com/upload/vod/20231103-1/f4c01b50c6f5631abc788993a654a34e.jpg', '<p>Phim lấy bối cảnh triều nhà Thanh. Dù vậy, nó lại không phụ thuộc nhiều vào văn hóa và võ thuật Trung Hoa mà có những biến tấu riêng đậm chất phương Tây. Vào thời nhà Thanh vốn vẫn phụ thuộc nhiều vào chế độ phong kiến, một người thợ rèn thấp hèn (RZA) có khả năng chế tạo những món vũ khí đặc biệt cho các bộ tộc khác nhau. &nbsp;Anh dành dụm số tiền thu được để chuộc lại sự tự do cho người con gái anh yêu là nàng Lụa (Jamie Chung). Một ngày nọ có tin đồn về chuyến hàng chở vàng của hoàng đế sẽ ghé ngang vùng đất này, lãnh đạo của các bộ tộc mưu đồ sẽ giết nhau để giành giật số vàng này. Trong số đó, bộ tộc sư tử là tàn bạo nhất. Chúng được lãnh đạo bởi Sư Tử Bạc (Bryon Mann) và Sư tử Đồng (Cung Le).</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"RZA","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Cung Le","avatar":""},{"name":"Rick Yune","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Mary Christina Brown","avatar":""},{"name":"Jin Au-Yeung","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Andrew Ng","avatar":""},{"name":"Chen Kuan-tai","avatar":""},{"name":"Yoyao Hsueh","avatar":""},{"name":"Telly Liu","avatar":""},{"name":"Grace Huang","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"Te","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324468);
