INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-dam-sat', 'Tay Đấm Sắt', 'The Man with the Iron Fists', 'tay đấm sắt the man with the iron fists rza russell crowe lucy liu jamie chung zhu zhu dave bautista cung le rick yune gordon liu chia-hui mary christina brown jin au-yeung byron mann daniel wu andrew ng chen kuan-tai yoyao hsueh telly liu grace huang andrew lin pam grier te ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-phan-no-cua-cac-vi-than', 'Sự Phẫn Nộ Của Các Vị Thần', 'Wrath of the Titans', 'https://phimimg.com/upload/vod/20231103-1/36ce54eb61785676982be64f1548b8a7.jpg', 'https://phimimg.com/upload/vod/20231103-1/96dc40c4f5a7e85e9c886b02af0e45c2.jpg', '<p>Wrath of Titans (Sự Phẫn Nộ của Các Vị Thần) nói về Perseus - con trai thần Zeus đang trải qua cuộc sống êm đềm bên làng chai cùng cậu con trai 10 tuổi tên là Helius, nhưng cuộc tranh chấp giữa các vị thần đã phá vỡ khung cảnh yên ả ấy sự trỗi dậy của các Titan và Zeus bị giam cầm đã buộc Perseus phải tham gia vào nhiệm vụ đầy hiểm nguy mới… Bối cảnh của phim được thực hiện rất chân thực, từ cảnh chiến trường, cảnh vật núi rừng cho đến những khung hình nhanh của những trận giao chiến nảy lửa. Diễn xuất của các nhân vật khá tốt nên mặc dù là 1 phim sử dụng nhiều kĩ xảo nhưng các nhân vật vẫn hiện lên chân thực và sống động.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Sinéad Cusack","avatar":""},{"name":"John Bell","avatar":""},{"name":"Lily James","avatar":""},{"name":"Alejandro Naranjo","avatar":""},{"name":"Freddy Drabble","avatar":""},{"name":"Kathryn Carpenter","avatar":""},{"name":"Matt Milne","avatar":""},{"name":"Birkett Turton","avatar":""},{"name":"Spencer Wilding","avatar":""},{"name":"Jua","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324468);
