INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-hamilton-vi-loi-ich-quoc-gia', 'Điệp Viên Hamilton: Vì Lợi Ích Quốc Gia', 'Hamilton - I nationens intresse', 'https://phimimg.com/upload/vod/20231103-1/e5c0ea7c60a41176f402b710058a1413.jpg', 'https://phimimg.com/upload/vod/20231103-1/df5a828ab4d9365b5addc1354e640d04.jpg', '<p>Đại úy Hamilton bí mật gia nhập một tổ chức mafia Nga chuyển lậu vũ khí tới Thụy Điển cho một đám khủng bố. Đột nhiên họ bị tấn công bởi một nhóm không rõ từ đâu. Tất cả mọi người đều bị giết ngoại trừ Hamilton. Bọn chúng lấy hết số vũ khí này. Bọn chúng là ai? Và đang làm việc cho kẻ nào? Hamilton bắt đầu đuổi theo chúng trên toàn thế giới...</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Mikael Persbrandt","avatar":""},{"name":"Saba Mubarak","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Pernilla August","avatar":""},{"name":"Gustaf Hammarsten","avatar":""},{"name":"Ray Fearon","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Liv Mjönes","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"Fanny Risberg","avatar":""},{"name":"Lennart Hjulström","avatar":""},{"name":"Leo Gregory","avatar":""},{"name":"Ashraf Farah","avatar":""},{"name":"Sandra Andreis","avatar":""},{"name":"Aleksandr Nosik","avatar":""},{"name":"Dan Ekborg","avatar":""},{"name":"Michael An","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
