INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-usb', 'Ổ USB', 'Flashdrive', 'null', 'https://phimimg.com/upload/vod/20231109-1/074e5ff80d087070d72f78e84ff7f410.jpg', '<p>Bộ phim Ổ USB - Flashdrive kể về câu chuyện khi Ashley Romano - người sắp trở thành phóng viên tin tức tình cờ gặp một huyền thoại đô thị có tên là EL JARVE&#39; DE ESCOBAR, cuộc sống của cô ấy đã bị đặt vào vòng nguy hiểm. Phát hiện ra việc cô ấy bị sát hại, Johnny Franco, bạn trai và cũng là người dạy võ cho cô ấy sẽ không dừng lại để khám phá sự thật và tìm cách trả thù cho cái chết của cô ấy thông qua một nhóm sát thủ do Antonio dẫn đầu.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emilio Pantero","avatar":""},{"name":"Franklin Correa","avatar":""},{"name":"Janet Miranda","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
