INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-cuc-quyen-level-zero', 'Thái Cực Quyền: Level Zero', 'Tai Chi Zero', 'https://phimimg.com/upload/vod/20231101-1/d2dd6e1113cc915630216c6f5119edbe.jpg', 'https://phimimg.com/upload/vod/20231101-1/a06bd436b8c1edf72b512643db0cd107.jpg', '<p>Là câu chuyện từ vô danh đến anh hùng của một chàng trai mồ côi. Sau hàng loạt biến cố, anh chàng trôi dạt đến Chen Clan, ngôi làng vẫn được gọi là &quot;thiên đường của trái đất&quot;. Nơi đây, mỗi người dân đều là những cao thủ về&nbsp;Thái Cực Quyền. Cậu bé mồ côi cũng muốn được học kungfu và tạo nên tên tuổi của riêng mình nhưng bị từ chối với lý do&nbsp;Thái Cực Quyền&nbsp;không được truyền cho người ngoài.</p>', 'Full', 1, 'single', 'completed', 21, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiaochao Yuan","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"William Feng","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Ying Da","avatar":""},{"name":"Bruce Siu-Lung Leung","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Chen Sicheng","avatar":""},{"name":"Xiong Naijin","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Jade Xu","avatar":""},{"name":"Pierre Bourdaud","avatar":""},{"name":"Paul Philip Clark","avatar":""},{"name":"Marc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
