INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-anh-den-vut-tat', 'Khi Ánh Đèn Vụt Tắt', 'When the Lights Went Out', 'https://phimimg.com/upload/vod/20231101-1/63f400f1244d027c9a1f7027d790554e.jpg', 'https://phimimg.com/upload/vod/20231101-1/7ca5f4300f35a98d3e720bc3dbd1a633.jpg', '<p>Yorkshire, 1974, gia đình Maynard chuyển đến ngôi nhà mơ ước của họ. Đó là một giấc mơ nhanh chóng biến thành cơn ác mộng kinh hoàng khi cả gia đình phát hiện ra một sự thật kinh hoàng, một sự thật sẽ đi vào sử sách. Ngôi nhà đã bị chiếm giữ bởi yêu tinh bạo lực nhất từng được ghi nhận, một yêu tinh sẽ xé bạn khỏi giường khi bạn ngủ và kéo bạn bất lực vào bóng tối.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Steven Waddington","avatar":""},{"name":"Kate Ashfield","avatar":""},{"name":"Jo Hartley","avatar":""},{"name":"Tasha Connor","avatar":""},{"name":"Molly Windsor","avatar":""},{"name":"Craig Parkinson","avatar":""},{"name":"Andrea Lowe","avatar":""},{"name":"Martin Compston","avatar":""},{"name":"Gary Lewis","avatar":""},{"name":"Hannah Clifford","avatar":""},{"name":"Tony Pitts","avatar":""},{"name":"Ross Mullan","avatar":""},{"name":"Matt Connor","avatar":""},{"name":"Martina McClements","avatar":""},{"name":"Peter Egan","avatar":""},{"name":"Hester Evans","avatar":""},{"name":"Graham Hornsby","avatar":""},{"name":"Kels","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324468);
