INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-tren-thao-nguyen', 'Cuộc Chiến Trên Thảo Nguyên', 'Zhauzhürek myng bala', 'https://phimimg.com/upload/vod/20231031-1/5dad393122af3d29cdf78f5746f00f8b.jpg', 'https://phimimg.com/upload/vod/20231031-1/0291281b102e9cd6a85b5d1f9c6d5e78.jpg', '<p>Một câu chuyện phổ quát về sự tự do của tinh thần con người và cuộc đấu tranh chống lại chế độ nô lệ và chế độ chuyên quyền, về tình yêu, sự mất mát và sự phản bội. Nó được nhìn qua con mắt của những đứa trẻ và thanh thiếu niên Kazakhstan giản dị.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Kazakhstan', 0, '[{"name":"Asylkhan Tolepov","avatar":""},{"name":"Kuralay Anarbekova","avatar":""},{"name":"Aliya Anuarbek","avatar":""},{"name":"Aliya Telebarisova","avatar":""},{"name":"Ayan Utepbergenov","avatar":""},{"name":"Tlektes Meyramov","avatar":""},{"name":"Tulyubek Aralbayev","avatar":""},{"name":"Eduard Ondar","avatar":""},{"name":"Nurlan Alimzhanov","avatar":""},{"name":"Dauren Sergazin","avatar":""},{"name":"Doskhan Joljakcynov","avatar":""},{"name":"Tungyshbay Gamankulov","avatar":""},{"name":"Berik Aytzhanov","avatar":""},{"name":"Tserenbold Ts","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
