INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-hat-nhan-2012', 'Thảm Họa Hạt Nhân', 'Chernobyl Diaries', 'https://phimimg.com/upload/vod/20231031-1/7c2137582227e8ae55f4153028708014.jpg', 'https://phimimg.com/upload/vod/20231031-1/006b351070362917cea08c10721f4915.jpg', '<p>Một nhóm sáu du khách muốn đi khỏi con đường mòn, thuê một &quot;hướng dẫn viên du lịch cực đoan&quot;; người, phớt lờ những lời cảnh báo, đưa họ vào thành phố Pripyat, nơi ở trước đây của các công nhân lò phản ứng hạt nhân Chernobyl, nhưng giờ là một thị trấn hoang vắng kể từ thảm họa hơn 25 năm trước. Sau một chuyến khám phá ngắn gọn về thành phố bị bỏ hoang, các thành viên trong nhóm thấy mình bị mắc kẹt và phát hiện ra rằng họ không đơn độc.</p>', 'Full', 1, 'single', 'completed', 22, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jesse McCartney","avatar":""},{"name":"Devin Kelley","avatar":""},{"name":"Jonathan Sadowski","avatar":""},{"name":"Olivia Taylor Dudley","avatar":""},{"name":"Ingrid Bolsø Berdal","avatar":""},{"name":"Nathan Phillips","avatar":""},{"name":"Alex Feldman","avatar":""},{"name":"Milutin Milošević","avatar":""},{"name":"Kristof Konrad","avatar":""},{"name":"Pasha D. Lychnikoff","avatar":""},{"name":"Miloš Timotijević","avatar":""},{"name":"Dimitri Diatchenko","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
