INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-con-cua-soi-ame-va-yuki', 'Những Đứa Con Của Sói Ame và Yuki', 'Wolf Children', 'https://phimimg.com/upload/vod/20231029-1/90704924a866d6077a36c10bb00c2354.jpg', 'https://phimimg.com/upload/vod/20231029-1/2e7ac046c17e2f2ebc73e0d8596dac1d.jpg', '<p>Hai chị em Yuki và Ame có một bí mật. Hai cô cậu nhóc là ‘người sói’, chính xác hơn là ‘nửa người nửa sói’. Mẹ chúng – Hana đã gặp và yêu một anh chàng người sói. Cả gia đình họ có một cuộc sống bình dị lặng thầm nơi nơi đô thành, giữ kín những bí mật của mình. Bỗng một ngày, cha họ qua đời. Mẹ Hana quyết định mang Yuki và Ame về một làng quê, sống vui vầy cùng thiên nhiên.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Haru Kuroki","avatar":""},{"name":"Yukito Nishii","avatar":""},{"name":"Aoi Miyazaki","avatar":""},{"name":"Takao Osawa","avatar":""},{"name":"Momoka Ohno","avatar":""},{"name":"Amon Kabe","avatar":""},{"name":"Takuma Hiraoka","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Tadashi Nakamura","avatar":""},{"name":"Tamio Ohki","avatar":""},{"name":"Tomie Kataoka","avatar":""},{"name":"Hajime Inoue","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Taichi Masu","avatar":""},{"name":"Kumiko Aso","avatar":""},{"name":"Bunta Sugawara","avatar":""},{"name":"Takashi Kobayashi","avatar":""},{"name":"Mitsu","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu"