INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-do-choi-bua-tiec-trong-phong-tam', 'Câu Chuyện Đồ Chơi: Bữa Tiệc Trong Phòng Tắm', 'Partysaurus Rex', 'https://phimimg.com/upload/vod/20231029-1/6ee847035c76fdf9a628821fc21c5d3c.jpg', 'https://phimimg.com/upload/vod/20231029-1/8533cc95c27429fa8f2138d2fdd684e9.jpg', '<p>Toy Story Toons Partysaurus Rex là một bộ phim hoạt hình ngắn năm 2012 do Mark Walsh đạo diễn. Nó được chiếu tại các rạp chiếu phim trước khi chiếu phim chính là Finding Nemo. Chú khủng long Rex với đôi tay ngắn vụng về trở thành tâm điểm của một bữa tiệc đầy đồ chơi với những nhân vật nổi tiếng trong bộ phim hoạt hình kinh điển Toy Story. Partysaurus Rex không chỉ là cơ hội cho khán giả thăm thú đám đồ chơi đã đi vào tâm trí từ năm 1995 mà còn mang đến bữa tiệc đầy đồ chơi chưa bao giờ được khám phá trong một bối cảnh câu chuyện mà độc đáo, màu sắc và đầy hài hước, đó là bồn tắm.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wallace Shawn","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Tim Allen","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Donald Fullilove","avatar":""},{"name":"Emily Hahn","avatar":""},{"name":"Don Rickles","avatar":""},{"name":"Lori Alan","avatar":""},{"name":"Estelle Harris","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Mark A. Walsh","avatar":""},{"name":"Timothy Dalton","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Sherry Lynn","avatar":""},{"name":"Lori Richardson","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"John Cygan","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
