INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-do-choi-bua-tiec-trong-phong-tam', 'Câu Chuyện Đồ Chơi: Bữa Tiệc Trong Phòng Tắm', 'Partysaurus Rex', 'câu chuyện đồ chơi: bữa tiệc trong phòng tắm partysaurus rex wallace shawn tom hanks tim allen corey burton tony cox donald fullilove emily hahn don rickles lori alan estelle harris john ratzenberger mark a. walsh timothy dalton joan cusack sherry lynn lori richardson carlos alazraqui john cygan a ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-vuot-thoi-gian', 'Sát Thủ Vượt Thời Gian', 'Looper', 'https://phimimg.com/upload/vod/20231029-1/63216b76dc65fb318d435db2e27aad9e.jpg', 'https://phimimg.com/upload/vod/20231029-1/7f96fbbbea2dbd950787a712117e84fc.jpg', '<p>Trong tương lai, con người tìm ra phương pháp đi xuyên thời gian. Do luật pháp tương lai nghiêm cấm giết người nên cách di chuyển này thường được các tổ chức tội phạm sử dụng để lách luật nhằm giết hại kẻ thủ. Nạn nhân sau khi bị bắt được đưa về quá khứ để các sát thủ xuyên thời gian (Looper) hạ sát. Bộ phim lấy bối cảnh ở hai thời điểm, năm 2044 và năm 2074. Vào năm 2044, Joseph Simmons (Joseph Gordon-Levitt) là một sát thủ hàng đầu làm việc cho tổ chức tội phạm lớn nhất tại thành phố Kansas. Một ngày Joshep nhận được hợp đồng giết chết Joe (Bruce Willis), một sát thủ đã nghỉ hưu vào năm 2074. Khi thời khắc quyết định ập đến, bất ngờ Joshep phát hiện ra Joe chính là anh của 30 năm nữa....</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Noah Segan","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"James Landry Hébert","avatar":""},{"name":"Pierce Gagnon","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Frank Brennan","avatar":""},{"name":"Marcus Hester","avatar":""},{"name":"Jon Eyez","avatar":""},{"name":"Kevin Stillwell","avatar":""},{"name":"Thirl Has","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b