INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-vo-hinh', 'Sức Mạnh Vô Hình', 'Chronicle', 'https://phimimg.com/upload/vod/20231030-1/2ecfd78c807b60dda762acfe58660f00.jpg', 'https://phimimg.com/upload/vod/20231030-1/ef833bb972c9efaad1c5c74964b9e886.jpg', '<p>Nội dung phim xoay quanh câu chuyện của một nhóm bạn trẻ trên đường đi du lịch bất ngờ gặp một sự vật lạ. Cuộc gặp gỡ đó mang lại cho họ một sức mạnh siêu nhiên biến họ trở thành X-men. 3 người bạn khám phá ra thiên thạch lạHọ lấy năng lực của mình để trêu đùa người khácĐiều khiển cả một chiếc xeLại còn trêu chọc các bạn gái nữaKhi nghi ngờ có người theo dõi hành tung của mình…… họ làm hỏng chiếc xe luôn!Dùng ý nghĩ để phá hủy cả một chiếc xe!Bay lượn trên trời!Lại còn đẩy lùi cả xe cảnh sát nữa!</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dane DeHaan","avatar":""},{"name":"Alex Russell","avatar":""},{"name":"Michael B. Jordan","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Anna Wood","avatar":""},{"name":"Ashley Grace","avatar":""},{"name":"Joe Vaz","avatar":""},{"name":"Crystal-Donna Roberts","avatar":""},{"name":"Luke Tyler","avatar":""},{"name":"Grant Powell","avatar":""},{"name":"Daisy Tormé","avatar":""},{"name":"Matt Nolan","avatar":""},{"name":"Popeye Vogelsang","avatar":""},{"name":"Steve Kramer","avatar":""},{"name":"Ashley Peldon","avatar":""},{"name":"Paul Pape","avatar":""},{"name":"Jeff Fischer","avatar":""},{"name":"Byron Thames","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id