INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-sieu-hang', 'Cướp Siêu Hạng', 'Stolen', 'https://phimimg.com/upload/vod/20231030-1/1f28b75e5008885d3c29059dcf17c616.jpg', 'https://phimimg.com/upload/vod/20231030-1/e1d0a279ffa768cc0785d38ffe55246c.jpg', '<p>Tên trộm bậc thầy Will Montgomery vừa được thả ra khỏi nhà tù Tiểu bang sau khi thụ án 10 năm, được liên lạc với Vincent, đồng đội cũ của hắn, người đang giữ con gái tuổi teen của Will để đòi tiền chuộc trong một chiếc taxi bị cướp. Vincent sẽ chỉ đầu hàng cô khi Will tiết lộ tung tích của 20 triệu đô la mà anh ta đã che giấu từ vụ cướp cuối cùng của họ.</p>', 'Full', 1, 'single', 'completed', 14, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Sami Gayle","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Shanna Forrestall","avatar":""},{"name":"Kevin Foster","avatar":""},{"name":"Mark Valley","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Edrick Browne","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Garrett Hines","avatar":""},{"name":"Tanc Sade","avatar":""},{"name":"Dan Braverman","avatar":""},{"name":"Jon Eyez","avatar":""},{"name":"Marcus Lyle Brown","avatar":""},{"name":"Matt No","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
