INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuop-sieu-hang', 'Cướp Siêu Hạng', 'Stolen', 'cướp siêu hạng stolen nicolas cage sami gayle josh lucas malin åkerman danny huston shanna forrestall kevin foster mark valley barry shabaka henley edrick browne m.c. gainey j.d. evermore garrett hines tanc sade dan braverman jon eyez marcus lyle brown matt no ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho-4', 'Vũ Điệu Đường Phố 4', 'Step Up Revolution', 'https://phimimg.com/upload/vod/20231029-1/a912875ec69962aa30dbff7cf3bd857d.jpg', 'https://phimimg.com/upload/vod/20231029-1/e2bae741be8a767a9c3d3a5ee7598a27.jpg', '<p>Emily là cô tiểu thư giàu có nhưng đam mê vũ đạo. Cô rời gia đình tới Miami để theo đuổi ước mơ của mình. Tại đây, Emily gặp gỡ và đem lòng yêu Sean, chàng trai trẻ thủ lĩnh nhóm nhảy Flash Mob đường phố. &nbsp;Tuy nhiên, khu phố gắn liền với lịch sử của Flash Mob ở Miami có nguy cơ bị di dời và phá hủy. Emily, Sean cùng những vũ công khác quyết tâm đấu tranh để bảo vệ ngôi nhà chung và ước mơ của họ.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kathryn McCormick","avatar":""},{"name":"Ryan Guzman","avatar":""},{"name":"Misha Gabriel","avatar":""},{"name":"Stephen ''tWitch'' Boss","avatar":""},{"name":"Cleopatra Coleman","avatar":""},{"name":"Michael ''Xeno'' Langebeck","avatar":""},{"name":"Peter Gallagher","avatar":""},{"name":"Tommy Dewey","avatar":""},{"name":"Emiliano Díez","avatar":""},{"name":"Steve Zurk","avatar":""},{"name":"Mia Michaels","avatar":""},{"name":"Claudio Pinto","avatar":""},{"name":"Adam Sevani","avatar":""},{"name":"Mario Ernesto Sánchez","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324468);
