INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-dieu-duong-pho-4', 'Vũ Điệu Đường Phố 4', 'Step Up Revolution', 'vũ điệu đường phố 4 step up revolution kathryn mccormick ryan guzman misha gabriel stephen ''twitch'' boss cleopatra coleman michael ''xeno'' langebeck peter gallagher tommy dewey emiliano díez steve zurk mia michaels claudio pinto adam sevani mario ernesto sánchez ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-cau-chuyen-nguoi-ca-2', 'Barbie: Câu Chuyện Người Cá 2', 'Barbie in A Mermaid Tale 2', 'https://phimimg.com/upload/vod/20231029-1/366fb25ec8d714d8506a0113a84a9e13.jpg', 'https://phimimg.com/upload/vod/20231029-1/19b9b2861bc1473683ac1f3739da2486.jpg', '<p>Hãy ủng hộ Barbie khi cô ấy trở lại với tư cách là Merliah, nhà vô địch lướt sóng vui tính và thời trang, đồng thời cũng là một công chúa tiên cá kỳ diệu! Trong câu chuyện về biển thú vị này, Merliah gây chú ý khi đến Úc để tham gia cuộc thi lướt sóng đỉnh cao. Khi nàng tiên cá độc ác Eris trốn thoát khỏi vòng xoáy với kế hoạch chiếm lấy ngai vàng của Oceana, Merliah và những người bạn biển của cô đã lao vào để ngăn chặn cô. Đó là một cuộc phiêu lưu mới mẻ, nơi Merliah biết rằng mọi thứ đều có thể xảy ra và cô ấy thực sự có thể tận hưởng những điều tốt đẹp nhất của cả hai thế giới!</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kelly Sheridan","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Nakia Burrise","avatar":""},{"name":"Maryke Hendrikse","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Alistair Abell","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"Kelly Metzger","avatar":""},{"name":"Andrew Francis","avatar":""},{"name":"Barbara Tyson","avatar":""},{"name":"Kira Tozer","avatar":""},{"name":"Bethany Brown","avatar":""},{"name":"Britt Irvin","avatar":""},{"name":"Peter Me","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324468);
