INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-minh-tinh-va-chang-lang-tu-3-bua-tiec-lon', 'Nữ Minh Tinh và Chàng Lãng Tử 3: Bữa Tiệc Lớn!', 'Beverly Hills Chihuahua 3: Viva la Fiesta!', 'https://phimimg.com/upload/vod/20231030-1/35924bcb49c93de5ace709ebd92b3571.jpg', 'https://phimimg.com/upload/vod/20231030-1/245ca4bb4b708ed81100edfc560e2863.jpg', '<p>Khi Papi, Chloe, những chú chó con, chú Pedro và chủ của chúng chuyển đến một khách sạn, chú chó con nhỏ nhất Rosa cảm thấy mình không phù hợp và Papi muốn khiến cô bé cảm thấy dễ chịu hơn bằng cách cho cô ấy thấy cô ấy đặc biệt như thế nào.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Lopez","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"Emily Osment","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Madison Pettis","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Miguel Ferrer","avatar":""},{"name":"Sebastian Roché","avatar":""},{"name":"Kay Panabaker","avatar":""},{"name":"Ashley Boettcher","avatar":""},{"name":"Jeff Witzke","avatar":""},{"name":"Cara Santana","avatar":""},{"name":"Logan Grove","avatar":""},{"name":"Kerry Wieder","avatar":""},{"name":"Sam Pancake","avatar":""},{"name":"Erin C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324468);
