INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-minh-tinh-va-chang-lang-tu-3-bua-tiec-lon', 'Nữ Minh Tinh và Chàng Lãng Tử 3: Bữa Tiệc Lớn!', 'Beverly Hills Chihuahua 3: Viva la Fiesta!', 'nữ minh tinh và chàng lãng tử 3: bữa tiệc lớn! beverly hills chihuahua 3: viva la fiesta! george lopez frances fisher jake busey emily osment odette annable madison pettis lacey chabert ernie hudson miguel ferrer sebastian roché kay panabaker ashley boettcher jeff witzke cara santana logan grove kerry wieder sam pancake erin c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-khong-gian-khong-the-lam-lai', 'Đặc Vụ Không Gian: Không Thể Làm Lại', 'Evangelion: 3.0 You Can (Not) Redo', 'https://phimimg.com/upload/vod/20231030-1/9b76e8df610e4ea20763012b4d5212c5.jpg', 'https://phimimg.com/upload/vod/20231030-1/6dd8b7e6e0f5cf2b00a39fc88b99179d.jpg', '<p>Được cứu thoát khỏi thân thể Unit-01, cuối cùng Ikari Shinji đã tỉnh dậy nhưng không hề hay biết chuyện gì đã xảy ra đối với mình và với cả thế giới sau Chấn Động Thứ Ba. Mọi thứ trở nên xa lạ với cậu và những người cậu từng thân quen đã đổi khác và xem cậu như tội phạm chiến tranh. Shinji quyết định đi tìm câu giải đáp cho những gì đang diễn ra và bảo đảm rằng Ayanami Rei cũng đã được cứu khỏi Unit-01. Tuy nhiên tất cả lại tiếp tục trở nên khó hiểu hơn nữa khi Shinji bị cấm lái Eva và nơi cậu đang ở không còn là Trụ sở NERV...</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Anri Katsu","avatar":""},{"name":"Hiro Yuuki","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Miki Na","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong