INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-khong-gian-khong-the-lam-lai', 'Đặc Vụ Không Gian: Không Thể Làm Lại', 'Evangelion: 3.0 You Can (Not) Redo', 'đặc vụ không gian: không thể làm lại evangelion: 3.0 you can (not) redo megumi ogata yuko miyamura akira ishida megumi hayashibara maaya sakamoto kotono mitsuishi yuriko yamaguchi fumihiko tachiki motomu kiyokawa mariya ise miyuki sawashiro takehito koyasu akio otsuka anri katsu hiro yuuki sayaka ohara miki na ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-ca-map', 'Bẫy Cá Mập', 'Bait', 'https://phimimg.com/upload/vod/20231030-1/a52d7b18dfd2c1a07edd1ca679462001.jpg', 'https://phimimg.com/upload/vod/20231030-1/250903fae51fb85d6b2d81d8f06b5125.jpg', '<p>Bait xoay quanh câu chuyện về một hung thần trắng dưới đại dương, đã tấn công và tàn sát mọi khách du lịch tại bờ biển Coolangatta ở Australia. Khi mọi người vẫn đang vui vẻ nghĩ dưỡng và tận hưởng kỳ nghỉ thì, tai họa ập đến, dần dần mọi người đều bị bỏ mạng dưới hàm răng kinh hoàng của cá mập. Một số người may mắn sống sót hiện đáng trốn trong những tòa nhà, thế nhưng mực nước ngày càng dân cao hơn khiến cá thành phố dần ngập trong biển nước và cá mập có thể di chuyển vào trong những căn nhà và tiếp tục tàn sát từng người. Vì thế những người còn sống tìm cách chiến đấu và sinh tồn để giữ gìn tính mạng và chờ người tới giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 22, 2012, 'Vietsub', 'HD', 'Singapore', 0, '[{"name":"Sharni Vinson","avatar":""},{"name":"Phoebe Tonkin","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Alex Russell","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Cariba Heine","avatar":""},{"name":"Lincoln Lewis","avatar":""},{"name":"Alice Parkinson","avatar":""},{"name":"Dan Wyllie","avatar":""},{"name":"Qi Yuwu","avatar":""},{"name":"Richard Brancatisano","avatar":""},{"name":"Chris Betts","avatar":""},{"name":"Damien Garvey","avatar":""},{"name":"Adrian Pang","avatar":""},{"name":"Martin Sacks","avatar":""},{"name":"Simon Edds","avatar":""},{"name":"Nicholas McCallum","avatar":""},{"name":"Yasus","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324468);
