INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-ca-map', 'Bẫy Cá Mập', 'Bait', 'bẫy cá mập bait sharni vinson phoebe tonkin julian mcmahon alex russell xavier samuel cariba heine lincoln lewis alice parkinson dan wyllie qi yuwu richard brancatisano chris betts damien garvey adrian pang martin sacks simon edds nicholas mccallum yasus ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-su-ba-bau', 'Tâm Sự Bà Bầu', 'What to Expect When You''re Expecting', 'https://phimimg.com/upload/vod/20231030-1/77c0aab1a4e7a23c100b7d5239254387.jpg', 'https://phimimg.com/upload/vod/20231030-1/9ba022023885c46d503f764f5814b3d7.jpg', '<p>Những thử thách sắp xảy ra khi làm cha mẹ khiến cuộc sống của năm cặp vợ chồng bị đảo lộn. Hai người nổi tiếng chưa chuẩn bị trước cho nhu cầu bất ngờ của việc mang thai; nội tiết tố tàn phá một tác giả cuồng trẻ con, trong khi chồng cô cố gắng không thua kém cha mình, người đang mong đợi một cặp song sinh với người vợ trẻ chiến lợi phẩm của mình; chồng của một nhiếp ảnh gia không chắc chắn về kế hoạch nhận con nuôi của vợ mình; mối tình một lần đã dẫn đến việc chủ xe chở đồ ăn đối thủ có thai bất ngờ.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Chace Crawford","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Matthew Morrison","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Ben Falcone","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Rob Huebel","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Amir Talai","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Wendi McLendon-C","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
