INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-su-ba-bau', 'Tâm Sự Bà Bầu', 'What to Expect When You''re Expecting', 'tâm sự bà bầu what to expect when you''re expecting jennifer lopez chace crawford anna kendrick cameron diaz elizabeth banks brooklyn decker matthew morrison rodrigo santoro ben falcone dennis quaid chris rock rob huebel thomas lennon amir talai rebel wilson joe manganiello wendi mclendon-c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-tham-phan', 'Hội Thẩm Phán', 'Dredd', 'https://phimimg.com/upload/vod/20231030-1/87e1d19b0baf31672568503c202db0fc.jpg', 'https://phimimg.com/upload/vod/20231030-1/3ba5283f59f72eabbb1b466b56b21071.jpg', '<p>Tương lai nước Mỹ bị nhấn chìm trong bạo lực, băng đảng làm chủ đường phố và các Mega City. Chỉ có một thế lực duy nhất dám đứng lên chống lại thế giới tội phạm này, đó chính là &quot;Hội Thẩm Phán&quot;. Họ là những cảnh sát kỳ cựu được trao quyền tự quyết định và tự hành xử. Trong đó, Dredd (Karl Urban thủ vai) là thẩm phán tối cao, và là cái tên mà băng đảng phải khiếp sợ mỗi khi nhắc đến.Trong thế giới tội phạm, tú bà Ma-Ma (Lena Headey đóng) vừa là trùm xã hội đen vừa là đầu nậu cung cấp ma túy mới, gây ảo giác &quot;chậm&quot; mà giới trẻ đang nghiện. Dredd cùng với lính mới Caassandra Anderson (Olivia Thrilby thủ vai), sẽ dấn thân vào những khu ổ chuột, đương đầu với các băng đảng xã hội đen và tham gia cuộc chiến bất tận ...</p>', 'Full', 1, 'single', 'completed', 19, 2012, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Karl Urban","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Tamer Burjaq","avatar":""},{"name":"Joe Vaz","avatar":""},{"name":"Rakie Ayola","avatar":""},{"name":"Junior Singo","avatar":""},{"name":"Luke Tyler","avatar":""},{"name":"Jason Cope","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Rachel Wood","avatar":""},{"name":"Andile Mngadi","avatar":""},{"name":"Porteus Xandau","avatar":""},{"name":"Emma Breschi","avatar":""},{"name":"Shoki Mokgapa","avatar":""},{"name":"Yoh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324468);
