INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bo-cap-3-cuoc-chien-chuoc-toi', 'Vua Bọ Cạp 3: Cuộc Chiến Chuộc Tội', 'The Scorpion King 3: Battle for Redemption', 'https://phimimg.com/upload/vod/20231030-1/636a0779bc840becfdb0fc1628d858b7.jpg', 'https://phimimg.com/upload/vod/20231030-1/ef12edc090cf995b46e5529966385e4a.jpg', '<p>Mathayus đã bị mất hoàng hậu yêu quý của mình và phải đối mặt bởi một bệnh dịch nguy hiểm. Một sát thủ được thuê để bảo vệ đồng minh của ông vua Ramusan từ cuộc tấn công sắp xảy ra. Nhiệm vụ của ông là giải cứu công chúa đang bị giam giữ. Đổi lại cho các quyền lợi của mình, ông được hứa sẽ cùng kết hôn với Silda, con gái Ramusan...</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Victor Webster","avatar":""},{"name":"Bostin Christopher","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Krystal Vee","avatar":""},{"name":"Selina Lo","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Kimbo Slice","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Johann Helf","avatar":""},{"name":"Geoffrey Giuliano","avatar":""},{"name":"Tanapol Chuksrida","avatar":""},{"name":"J.D. Hall","avatar":""},{"name":"Stephane Lambert","avatar":""},{"name":"Damian Mavis","avatar":""},{"name":"Jason Pace","avatar":""},{"name":"Dean Alexandrou","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
