INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tim-lai', 'Tình Yêu Tìm Lại', 'Silver Linings Playbook', 'https://phimimg.com/upload/vod/20231026-1/4c95ccbd570ec7528d28491b563d3e22.jpg', 'https://phimimg.com/upload/vod/20231026-1/b91a50af5432a4a231283b8dcf1fe255.jpg', '<p>Được chuyển thể từ cuốn tiểu thuyết của nhà văn Matthew Quick, &quot;Silver Linings Playbook&quot; kể về quá trình bình phục và đoàn tụ với gia đình của một giáo viên thất nghiệp sau 8 tháng điều trị tại bệnh viện tâm thần. Tham gia diễn xuất chính trong bộ phim này là nam diễn viên Bradley Cooper và minh tinh màn bạc Jennifer Lawrence.</p>', 'Full', 1, 'single', 'completed', 23, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Chris Tucker","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Paul Herman","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Matthew Russell","avatar":""},{"name":"Cheryl Williams","avatar":""},{"name":"Patrick McDade","avatar":""},{"name":"Brea Bee","avatar":""},{"name":"Mary Regency Boies","avatar":""},{"name":"Phillip Chorba","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324468);
