INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cap-linh-hon', 'Đánh Cắp Linh Hồn', 'The Possession', 'https://phimimg.com/upload/vod/20231026-1/8dd8ac2791617fa4c4df41626c9d9e06.jpg', 'https://phimimg.com/upload/vod/20231026-1/986505449a725a61a908445bc847fca2.jpg', '<p>Phim dựa trên một câu chuyện có thật về một cô bé vô tình mua được một chiếc hộp gỗ tưởng chừng rất bình thường nhưng không ai biết rằng nó đang ẩn chứa một linh hồn đầy thù hận bên trong. Sau khi nhiều lần suy nghĩ thì cô bé đã quyết định mở chiếc hộp và trở thành một con người hoàn toàn khác.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Natasha Calis","avatar":""},{"name":"Madison Davenport","avatar":""},{"name":"Rob LaBelle","avatar":""},{"name":"Matisyahu","avatar":""},{"name":"Quinn Lord","avatar":""},{"name":"Jay Brazeau","avatar":""},{"name":"Jim Thorburn","avatar":""},{"name":"Erin Simms","avatar":""},{"name":"John Cassini","avatar":""},{"name":"Grant Show","avatar":""},{"name":"Tim Perez","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"Scott J. Ateah","avatar":""},{"name":"Paul Wu","avatar":""},{"name":"Antoine Safi","avatar":""},{"name":"Cameron Sprague","avatar":""},{"name":"Shar","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
