INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-bong-dem', 'Lời Nguyền Bóng Đêm', 'Dark Shadows', 'https://phimimg.com/upload/vod/20231026-1/50a27d56780c54a664b1be9ea4d7fd4f.jpg', 'https://phimimg.com/upload/vod/20231026-1/0d0081c591642ca7c2d9ddc900227fe5.jpg', '<p>Ma cà rồng Barnabas Collins vô tình được giải thoát khỏi ngôi mộ của mình và bước vào một thế giới đầy thay đổi của năm 1972. Anh quay trở lại Trang viên Collinwood và phát hiện ra rằng gia sản và gia đình vĩ đại một thời của mình đã rơi vào cảnh hoang tàn.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Gulliver McGrath","avatar":""},{"name":"Ray Shirley","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Alice Cooper","avatar":""},{"name":"Ivan Kaye","avatar":""},{"name":"Susanna Cappellaro","avatar":""},{"name":"Raffey Cassidy","avatar":""},{"name":"Alexia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324468);
