INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tuoi-teen', 'Câu Chuyện Tuổi Teen', 'The Perks of Being a Wallflower', 'https://phimimg.com/upload/vod/20231026-1/e8090204672403a80152969ca954715c.jpg', 'https://phimimg.com/upload/vod/20231026-1/7ed517a064ad78345fc9f649b2fb19d9.jpg', '<p>Câu Chuyện Tuổi Teen là câu chuyện về tuổi mới lớn. Charlie - cậu học sinh đang gặp khó khăn thực sự về việc tiếp thu các từ vựng mới, cố gắng khắc phục chứng bệnh kỳ lạ của mình bằng cách gửi đi những bức thư - không người nhận. Sam, cô bạn cùng trường của cậu đã đưa cậu đến thế giới của tình dục, ma túy… The Perks Of Being A Wallflower đã chạm đến những vấn đề gần gũi trong cuộc sống của các cô cậu nhóc tuổi teen. Đặc biệt, sự ngọt ngào, thi vị của tình yêu và tình bạn được dàn diễn viên của The perks of being a wallflower lột tả một cách khéo léo, tự nhiên, mang lại cho khán giả những giây phút nhẹ nhàng, ý nghĩa.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Kate Walsh","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Reece Thompson","avatar":""},{"name":"Patrick de Ledebur","avatar":""},{"name":"Brian Balzerini","avatar":""},{"name":"Tom Kruszewski","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"Tom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
