INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-12-z-ky-phung-dich-thu', 'Đảo Hải Tặc 12: Z - Kỳ Phùng Địch Thủ', 'One Piece Film: Z', 'https://phimimg.com/upload/vod/20231026-1/6ae4010c6a52dacb539afd8370803143.jpg', 'https://phimimg.com/upload/vod/20231026-1/1412579ced243aef8308a926fbb0853e.jpg', '<p>Đảo Hải Tặc: Z - Kỳ Phùng Địch Thủ có nội dung là được so sánh với Vũ khí cổ đại, con át chủ bài của hải quân, viên đá Dyan đột nhiên bị đánh cắp bởi một người đàn ông vô cùng mạnh mẽ, cựu đô đốc hải quân Z sẽ là đối thủ của băng hải tặc Mũ Rơm. &nbsp;Tổng bộ Hải Quân tiến tới việc đối phó với âm mưu đe dọa làm lung lay các trụ cột của Tân Thế Giới. Ở nơi khác, Kuzan trợ giúp cho băng Mũ Rơm. Cuối cùng, Luffy và đồng đội của mình tiến lên chống lại Z cùng sức mạnh kinh hoàng của ông ta.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Masami Suzuki","avatar":""},{"name":"Ryoko Shinohara","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Masashi Hirose","avatar":""},{"name":"Mika","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324468);
