INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ao-den-3', 'Đặc Vụ Áo Đen 3', 'Men in Black 3', 'https://phimimg.com/upload/vod/20231024-1/94f905476aef5defafbff9325d79b17c.jpg', 'https://phimimg.com/upload/vod/20231024-1/44b21f748539f14b0b69150fddcc1fe7.jpg', '<p>Trước tình hình mạng sống của mật vụ K và vận mệnh của Trái Đất bị đe dọa, mật vụ J phải quay về quá khứ để tìm cách ngăn không cho điều này xảy ra. J đã khám phá ra những bí mật động trời mà K chưa bao giờ kể với anh, những bí mật sẽ dần được vén màn khi J song hành cùng Mật vụ K khi còn trẻ trong cuộc phiêu lưu giải cứu cộng sự, Tổ chức Áo Đen, và tương lai của cả nhân loại.</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Ả rập Thống nhất', 0, '[{"name":"Will Smith","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Nicole Scherzinger","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"David Rasche","avatar":""},{"name":"Keone Young","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Cayen Martin","avatar":""},{"name":"Clarke Thorell","avatar":""},{"name":"Adam Mucci","avatar":""},{"name":"Tom McComas","avatar":""},{"name":"Douglas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324468);
