INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-hoc-duong', 'Cớm Học Đường', '21 Jump Street', 'https://phimimg.com/upload/vod/20231023-1/da3ec959e57b046a607d48ace40aca1b.jpg', 'https://phimimg.com/upload/vod/20231023-1/48691902857b2f398cb608f80f1fd058.jpg', '<p>Bộ phim nói về Schmidt và Jenko, hai người bạn từ thời trung học, được chỉ định tham gia đơn vị đặc biệt mang tên 21 Jump Street, một nhóm cảnh sát đặc biệt trà trộn vào trường trung học để phá đường dây tiêu thụ thuốc kích thích cực lớn.&nbsp; Thế là dẹp bỏ súng ống và huy hiệu để đổi lấy balô và cặp táp, hai chàng trai bước vào lại ngôi trường cấp 3 quen thuộc. Công cuộc làm quen lại với cuộc sống mới mẻ này đã khó, Schmidt và Jenko còn phải truy tìm những tên trùm buôn thuốc kích thích cho học sinh ranh ma và hung tợn hơn họ tưởng tượng nhiều.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonah Hill","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"DeRay Davis","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Dax Flame","avatar":""},{"name":"Chris Parnell","avatar":""},{"name":"Ellie Kemper","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Holly Robinson Peete","avatar":""},{"name":"Johnny Pemberton","avatar":""},{"name":"Stanley Wong","avatar":""},{"name":"Justin Hires","avatar":""},{"name":"Brett Lapeyrouse","avatar":""},{"name":"Lindsey Bro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f69792608