INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-duong-toi-ninja', 'Naruto: Đường Tới Ninja', 'ROAD TO NINJA -NARUTO THE MOVIE-', 'https://phimimg.com/upload/vod/20231023-1/3ecbbc8a6b39957fdc6627ac7814173b.jpg', 'https://phimimg.com/upload/vod/20231023-1/2d82f3e23d85116eb4b4fcdc7f7f04da.jpg', '<p>Naruto và Sakura đang chơi trong công viên thì gặp Madara-thành viên tổ chức Akatsuki bắt vào trong một thế giới khác song song với thế giới Naruto đang sống. Ở thế giới này tất cả mọi người đều thay đổi và Naruto không có tên như cũ mà bị gọi là Memma. Tính cách mọi người thay đổi và cái bất ngờ nhất là bố mẹ Naruto vẫn còn sống và không làm Hokage mà thay vào đó là bố của Sakura làm Hokage và đã hi sinh. Cái bất ngờ hơn nữa là Akatsuki lại là tổ chức đánh thuê. Trong thế giới này Naruto phải đánh lại với chính mình là Memma và hợp sức với Cửu Vĩ...</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2012, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Emi Shinohara","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Naoya Uchida","avatar":""},{"name":"Noriaki Sugiyama","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Hideo Ishikawa","avatar":""},{"name":"Shinji Kawada","avatar":""},{"name":"Katsuhiko Kawamoto","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Kohsuke Toriumi","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Showtaro Moriku","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c