INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-pi', 'Cuộc Đời Của Pi', 'Life of Pi', 'https://phimimg.com/upload/vod/20231023-1/0d931233a1bf7c7259ff848e61913f79.jpg', 'https://phimimg.com/upload/vod/20231023-1/97760d0209f95609b76a90e9cd05ac44.jpg', '<p>Nói sơ qua về nội dung, Life of Pi kể về cuộc đời của một chàng trai xức Cà ri lên Pi Patel (thực ra tên đầy đủ dài lắm, tên của một hồ bơi) trong một chuyến hải trình đến Canada cùng gia đình không may bị tàu chìm và chỉ mình anh sống sót. Lênh đênh trên biển vượt Thái Bình Dương để sống sót, Pi phải tìm cách cùng làm bạn với một con hổ Bengal có tên Richard Parker (bố của Peter Parker – Người Nhện).&nbsp; Pi và con hổ là mối quan hệ kỳ lạ, sự đấu tranh sinh tồn lênh đênh giữa biển trong 227 ngày - làm sao để sống, làm sao để có thức ăn và nước uống, làm sao không bị con hổ ăn thịt, và làm sao để không chết bởi sự cô đơn. Cuộc đời của Pi còn là câu chuyện về tôn giáo, bởi Pi - cậu bé 16 tuổi này - có một tinh thần mộ ...</p>', 'Full', 1, 'single', 'completed', 17, 2012, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Suraj Sharma","avatar":""},{"name":"Irrfan Khan","avatar":""},{"name":"Ayush Tandon","avatar":""},{"name":"Gautam Belur","avatar":""},{"name":"Adil Hussain","avatar":""},{"name":"Tabu","avatar":""},{"name":"Ayaan Khan","avatar":""},{"name":"Mohd Abbas Khaleeli","avatar":""},{"name":"Vibish Sivakumar","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"James Saito","avatar":""},{"name":"Jun Naito","avatar":""},{"name":"Andrea Di Stefano","avatar":""},{"name":"Shravanthi Sainath","avatar":""},{"name":"Elie Alouf","avatar":""},{"name":"T.M. Karthik","avatar":""},{"name":"Amarendran","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
