INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-doi-cua-pi', 'Cuộc Đời Của Pi', 'Life of Pi', 'cuộc đời của pi life of pi suraj sharma irrfan khan ayush tandon gautam belur adil hussain tabu ayaan khan mohd abbas khaleeli vibish sivakumar rafe spall gérard depardieu james saito jun naito andrea di stefano shravanthi sainath elie alouf t.m. karthik amarendran ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-doat-2', 'Cưỡng Đoạt 2', 'Taken 2', 'https://phimimg.com/upload/vod/20231022-1/a40dc684866a3525834cdd4253ecf6a9.jpg', 'https://phimimg.com/upload/vod/20231022-1/2111addeccc4a34f1ed390e578efb805.jpg', '<p>Bryan Mills làm vệ sĩ cho những người nổi tiếng. Trong 1 chuyến đi tới Itstanbul, Bryan có mời vợ cũ Lenore và cô con gái Kim cùng tới du lịch cùng mình, đúng lúc này những kẻ thù năm xưa xuất hiện cầm đầu là tên trùm nguy hiểm Murad chúng đã bắt cóc Leonare. Một lần nữa Bryan đã đương đầu với bọn tội phạm nguy hiểm… Với bối cảnh đẹp của Itstanbul cùng những pha hành động gay cấn Taken 2 đã thu hút khán giả ở mọi lứa tuổi. Nội dung phim cũng ca ngợi tình nghĩa vợ chồng, tình phụ tử.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"D.B. Sweeney","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Luke Grimes","avatar":""},{"name":"Kevork Malikyan","avatar":""},{"name":"Alain Figlarz","avatar":""},{"name":"Frank Alvarez","avatar":""},{"name":"Murat Tuncelli","avatar":""},{"name":"Ali Yildirim","avatar":""},{"name":"Ergun Kuyucu","avatar":""},{"name":"Cengiz Bozkurt","avatar":""},{"name":"Hakan Karahan","avatar":""},{"name":"Saruhan Sari","avatar":""},{"name":"Naci Adi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
