INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ma-ca-rong', 'Thợ Săn Ma Cà Rồng', 'Abraham Lincoln: Vampire Hunter', 'https://phimimg.com/upload/vod/20231022-1/b459c95446612180691adf50f9ac0961.jpg', 'https://phimimg.com/upload/vod/20231022-1/7c60abb1dc7ab10f92bca7874b58b5bb.jpg', '<p>Phim khởi đầu bằng việc Lincoln bị ám ảnh bởi ma cà rồng sau những câu chuyện thời thơ ấu. Sau đó, cái chết của mẹ Lincoln làm dấy lên nỗi sợ hãi tột cùng. Và từ đó, ông bắt đầu tham gia cuộc chiến tiêu diệt đoàn quân thây ma trên khắp thế giới…</p>', 'Full', 1, 'single', 'completed', 23, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benjamin Walker","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"John Rothman","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Alex Lombard","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Teri Wyble","avatar":""},{"name":"Cameron M. Brown","avatar":""},{"name":"Frank Brennan","avatar":""},{"name":"John Neisler","avatar":""},{"name":"Meade Patton","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Robin McLeavy","avatar":""},{"name":"Erin Wass","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324468);
