INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('journey-2-hon-dao-huyen-bi', 'Journey 2: Hòn Đảo Huyền Bí', 'Journey 2: The Mysterious Island', 'https://phimimg.com/upload/vod/20231023-1/bbd0206d597f5431bea85d7d41eb6112.jpg', 'https://phimimg.com/upload/vod/20231023-1/59fb4d858d6a491a4aaf3fa8f7c81e85.jpg', '<p>Cuộc phiêu lưu bắt đầu khi Sean nhận được tín hiệu cầu cứu được mã hóa từ một hòn đảo huyền bí ở nơi mà thực tế không có hòn đảo nào tồn tại cả - một nơi của các hình thái sống kỳ lạ, những ngọn núi vàng, những núi lửa chết người và bí mật kinh hoàng. Không thể ngăn Sean thực hiện chuyến đi, cha dượng mới của Sean phải cùng tham gia hành trình. Cùng với một phi công và cô con gái xinh đẹp đầy cá tính của ông, họ bắt đầu tìm kiếm hòn đảo, giải cứu những cư dân cô độc ở đó và giải thoát họ trước khi những xung động địa chấn kéo hòn đảo xuống dưới đáy biển và chôn vùi kho báu của nó mãi mãi...</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Anna Colwell","avatar":""},{"name":"Stephen Caudill","avatar":""},{"name":"Branscombe Richmond","avatar":""},{"name":"Walter Bankson","avatar":""},{"name":"Cody Easterbrook","avatar":""},{"name":"Paul Leo Klink","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324468);
