INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('journey-2-hon-dao-huyen-bi', 'Journey 2: Hòn Đảo Huyền Bí', 'Journey 2: The Mysterious Island', 'journey 2: hòn đảo huyền bí journey 2: the mysterious island dwayne johnson josh hutcherson michael caine vanessa hudgens luis guzmán kristin davis anna colwell stephen caudill branscombe richmond walter bankson cody easterbrook paul leo klink ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sum-hop-kieu-my', 'Sum Họp Kiểu Mỹ', 'American Reunion', 'https://phimimg.com/upload/vod/20231023-1/104e001debf672409d216645d795f965.jpg', 'https://phimimg.com/upload/vod/20231023-1/26943b0e322f19b4e9a84f7598a61fa1.jpg', '<p>Bánh Mỹ thật sự đã trở lại với dàn diễn viên chủ lực từng làm nên thành công cho loạt film này từ phần 1-2-3. Lần này nhóm cựu học sinh Jim, Michelle, Stifler cùng các người bạn của họ lại tề tựu về trường trung học East Great Falls, Michigan để dự buổi họp mặt cựu học sinh và quậy 1 trận ra trò theo đúng phong cách Bánh Mỹ.Mặc dù vẫn sẽ giữ nguyên chất hài đặc trưng như các phần phim trước, nhưng bài học giới tính trong American Reunion không còn được đưa đến trực tiếp theo góc nhìn từ tuổi mới lớn, mà được lồng ghép vào trong những ký ức, hoài niệm thời thơ ấu, cộng thêm những câu chuyện &quot;dở khóc dở cười&quot; của đám bạn bè lâu năm mới có dịp tái ngộ này.</p>', 'Full', 1, 'single', 'completed', 12, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Biggs","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Chris Klein","avatar":""},{"name":"Thomas Ian Nicholas","avatar":""},{"name":"Tara Reid","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Eddie Kaye Thomas","avatar":""},{"name":"John Cho","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"Ali Cobrin","avatar":""},{"name":"Shannon Elizabeth","avatar":""},{"name":"Chris O","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
