INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-ma', 'Chú Chó Ma', 'Frankenweenie', 'https://phimimg.com/upload/vod/20231023-1/26501b3cdefc3ff7fc5ca5a63f3285ae.jpg', 'https://phimimg.com/upload/vod/20231023-1/a9b3794d0872f5cf26ce556624d7f61c.jpg', '<p>Khi một chiếc ô tô tông vào con chó cưng Sparky của Victor, Victor quyết định làm cho nó sống lại theo cách duy nhất mà anh ấy biết. Nhưng khi &quot;quái vật&quot; cổ tia chớp tàn phá và kinh hoàng trái tim những người hàng xóm của Victor, anh phải thuyết phục họ rằng Sparky vẫn là người bạn tốt, trung thành như anh.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Tahan","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Martin Landau","avatar":""},{"name":"Atticus Shaffer","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Robert Capron","avatar":""},{"name":"James Hiroyuki Liao","avatar":""},{"name":"Conchata Ferrell","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Christopher Lee","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324468);
