INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-cho-ma', 'Chú Chó Ma', 'Frankenweenie', 'chú chó ma frankenweenie charlie tahan catherine o''hara martin short martin landau atticus shaffer winona ryder robert capron james hiroyuki liao conchata ferrell tom kenny frank welker dee bradley baker jeff bennett christopher lee ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-bi-mat-doi-canh', 'Tinker Bell: Bí Mật Đôi Cánh', 'Secret of the Wings', 'https://phimimg.com/upload/vod/20231022-1/eed3a63ffa4295ef6ef3fa133502e6a8.jpg', 'https://phimimg.com/upload/vod/20231022-1/c3a7bfb873bf8f2a01885c186abc4bf9.jpg', '<p>Tinker Bell được sinh ra từ nụ cười đầu tiên của đứa trẻ sơ sinh và được ngọn gió mang tới Pixie Hollow (một hòn đảo ở Never Land). Tại đây cô gặp những nàng tiên nhỏ khác và biết rằng năng lực của mình là để phục vụ việc hàn gắn mọi thứ - một thiên thần sửa chữa mọi thứ. Các tiên thợ khác đã giúp nhân viên mới học việc và Tinker Bell đã học được nghề, cô có thể sửa được máy nhạc bằng việc sử dụng nước biển. Thế rồi khi cô được kể rằng, chỉ có các nàng tiên thường mới có thể vào lục địa thì cô thấy hơi chạnh lòng cho các nàng tiên như mình. Rồi cô cố gắng nâng cao năng lực của mình. Hãy theo dõi xem chuyện gì tiếp theo sẽ xảy đến nhé!</p>', 'Full', 1, 'hoathinh', 'completed', 30, 2012, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mae Whitman","avatar":""},{"name":"Lucy Hale","avatar":""},{"name":"Timothy Dalton","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Megan Hilty","avatar":""},{"name":"Pamela Adlon","avatar":""},{"name":"Angela Bartys","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"Debby Ryan","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Jodi Benson","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Ben Disk","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324468);
