INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('norman-giac-quan-thu-sau', 'Norman & Giác Quan Thứ Sáu', 'ParaNorman', 'https://phimimg.com/upload/vod/20231022-1/2c4940c4b2a1ad536dcab96ae279bede.jpg', 'https://phimimg.com/upload/vod/20231022-1/18cc84b328f7f69b4bc8997c19b83049.jpg', '<p>Lấy bối cảnh tại thị trấn Blithe Hollow (một địa danh hư cấu), ParaNorman kể về cậu bé 11 tuổi Norman Babcock. Khác với những đứa trẻ khác, Norman dành phần lớn thời gian cho phim kinh dị và nghiên cứu về các truyền thuyết ma quỷ. Trên thực tế, cậu bé còn là người có khả năng trò chuyện với người chết. Một ngày nọ, người chú kỳ quặc Prenderghast tìm đến Norman và cho cậu biết lời nguyền phù thủy yểm vào thị trấn cách đây 300 năm sắp linh nghiệm. Chỉ có Norman là người duy nhất ngăn chặn được hiểm họa từ lời nguyền này. Sử dụng giác quan thứ sáu, cậu bé 11 tuổi chạm tới những giới hạn của tận cùng thế giới bên kia.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Tucker Albrizzi","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Elaine Stritch","avatar":""},{"name":"Bernard Hill","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Tempestt Bledsoe","avatar":""},{"name":"Jeremy Shada","avatar":""},{"name":"Scott Menville","avatar":""},{"name":"Hannah Noyes","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
