INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-hoanh-trang', 'Bữa Tiệc Hoành Tráng', 'Project X', 'https://phimimg.com/upload/vod/20231019-1/9ebe874220f4714b82c3f650fe2cb879.jpg', 'https://phimimg.com/upload/vod/20231019-1/18146795abfb16378357997e550dbc10.jpg', '<p>3 học sinh trung học tổ chức tiệc sinh nhật để tạo dựng tên tuổi. Tuy nhiên mọi thứ lại vượt ngoài tầm kiểm soát khi những lời đồn về bữa tiệc lan truyền...(phim coi rất vui ^^)</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Mann","avatar":""},{"name":"Oliver Cooper","avatar":""},{"name":"Jonathan Daniel Brown","avatar":""},{"name":"Dax Flame","avatar":""},{"name":"Kirby Bliss Blanton","avatar":""},{"name":"Brady Hender","avatar":""},{"name":"Nick Nervies","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Peter MacKenzie","avatar":""},{"name":"Caitlin Dulany","avatar":""},{"name":"Rob Evors","avatar":""},{"name":"Rick Shapiro","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Pete Gardner","avatar":""},{"name":"Nichole Sakura","avatar":""},{"name":"Sam Lant","avatar":""},{"name":"Hen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
