INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ralph-dap-pha', 'Ralph Đập Phá', 'Wreck-It Ralph', 'https://phimimg.com/upload/vod/20231019-1/013fb59db5eeca34627b18f8531ef128.jpg', 'https://phimimg.com/upload/vod/20231019-1/b9c0337ae6780e19017ae7e9e322166e.jpg', '<p>Ralph – anh chàng chuyên đóng vai kẻ ác trong trò chơi Fix - It Felix nổi tiếng, sau hàng thập kỷ lặp lại những công việc nhàm chán và phải làm nền cho Felix, Ralph quyết định rời bỏ trò chơi đã gắn bó 30 năm vào dấn thân vào cuộc phiêu lưu trong thế giới game, đi tìm chiếc huy chương vàng để chứng tỏ mình có những tố chất của một người hùng…&nbsp; Thông qua câu chuyện của Ralph, phim đã mang đến một chân lý giản đơn dành cho tất cả mọi người: “Quan trọng không phải bạn tốt hay xấu, không phải bạn là ai, mà bạn sẽ làm gì cho cuộc sống”. Đặc biệt, với những ai từng say mê trò chơi điện tử , Wreck-It-Ralph sẽ giúp khán giả sống lại thời kỳ hoàng kim của những trò chơi điện tử bốn nút, máy chơi game bằng xèng có đồ họa đơn sơ năm xưa.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John C. Reilly","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Rich Moore","avatar":""},{"name":"Raymond S. Persi","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Jamie Elman","avatar":""},{"name":"Adam Carolla","avatar":""},{"name":"Horatio Sanz","avatar":""},{"name":"Katie Lowes","avatar":""},{"name":"Kevin Deters","avatar":""},{"name":"Ed O''Neill","avatar":""},{"name":"Phil Johnston","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Edi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324468);
