INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-su-tinh-duc-cua-mot-gia-dinh-phap', 'Ký Sự Tình Dục Của Một Gia Đình Pháp', 'Sexual Chronicles of a French Family', 'https://phimimg.com/upload/vod/20231019-1/fe3852d01e570f6e0ef3bbe58ae5a665.jpg', 'https://phimimg.com/upload/vod/20231019-1/7339849a507b2f0bd20b152e3d416ffa.jpg', '<p>Những bữa ăn trong gia đình nhà Romain thường không mấy vui vẻ vì chuyện học hành cứ bị lôi ra trong khi đề tài tình dục là điều cấm kỵ. Rồi ông bố nhận ngay cú sét khi cậu út Romain &quot;thẩm du&quot; trong lớp học bị bắt gặp và quay cả phim nữa. Đối diện với nguy cơ bị đuổi học, bố mẹ cậu mới chuyển hướng. Chuyện tình dục hết là điều cấm kỵ giờ là chủ đề đáng quan tâm của gia đình. Bố mẹ cậu quyết định làm 1 đề tài về &quot;chuyện ấy&quot; của mình để huấn luyện mấy đứa con</p>', 'Full', 1, 'single', 'completed', 20, 2012, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Mathias Melloul","avatar":""},{"name":"Valérie Maës","avatar":""},{"name":"Stephan Hersoen","avatar":""},{"name":"Pierre Perrier","avatar":""},{"name":"Yan Brian","avatar":""},{"name":"Adeline Rebeillard","avatar":""},{"name":"Leïla Denio","avatar":""},{"name":"Gregory Annoni","avatar":""},{"name":"Nathan Duval","avatar":""},{"name":"Laetitia Favart","avatar":""},{"name":"Benjamin Houoti","avatar":""},{"name":"Maïlys Amrous","avatar":""},{"name":"Philippe Duquesne","avatar":""},{"name":"Astrid Vermeulin","avatar":""},{"name":"Faustine Dubois","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
