INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than-huyet-thong', 'Ngã Rẽ Tử Thần: Huyết Thống', 'Wrong Turn 5: Bloodlines', 'https://phimimg.com/upload/vod/20231018-1/5522985fe154a65e71a4ab0a3de649b8.jpg', 'https://phimimg.com/upload/vod/20231018-1/cf279bff3bbee45054aae2cb53462646.jpg', '<p>Ông Maynard Odets là một tên sát nhân độc ác đã bị chính phủ truy nã suốt 30 năm, không ai biết hắn đã trốn đi đâu nhưng thực ra hắn đang sống ở rừng Virginia cùng ba anh em đột biến của Three Finger. Hằng ngày Maynard cùng bọn chúng đi săn người ăn thịt, đến một lần nọ khi cuộc săn người bị thất bại thì Maynard bị cảnh sát bắt đưa về nhà tù của một thị trấn nhỏ gần đó. Thế là tối hôm đó Three Finger, One Eye và Saw Tooth phải đi vào thị trấn để cứu ông ấy, những cảnh sát và người dân trong thị trấn có biết chuyện này không và họ phải làm gì để đối phó với những tên &quot;khách không mời mà đến&quot; này.</p>', 'Full', 1, 'single', 'completed', 15, 2012, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Borisa Tyutyundzhieva","avatar":""},{"name":"Doug Bradley","avatar":""},{"name":"Roxanne McKee","avatar":""},{"name":"Camilla Arfwedson","avatar":""},{"name":"Paul Luebke","avatar":""},{"name":"Rosie Holden","avatar":""},{"name":"Simon Ginty","avatar":""},{"name":"Amy Lennox","avatar":""},{"name":"Peter Brooke","avatar":""},{"name":"Finn Jones","avatar":""},{"name":"Oliver Hoare","avatar":""},{"name":"Velizar Peev","avatar":""},{"name":"Svilen Cholakov","avatar":""},{"name":"Borislav Iliev","avatar":""},{"name":"Duncan Wisbey","avatar":""},{"name":"Radoslav Parvanov","avatar":""},{"name":"Kyle Redmon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324468);
