INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-den-hanh-tinh-chet', 'Hành Trình Đến Hành Tinh Chết', 'Prometheus', 'https://phimimg.com/upload/vod/20231018-1/5c32d85c5c966816b9a392db68221ac5.jpg', 'https://phimimg.com/upload/vod/20231018-1/803b3784cef2bcd9bfb6d8d609239a58.jpg', '<p>Nội dung phim nói về các nhà khảo cổ phát hiện ra những manh mối về nguồn gốc của loài người. Những manh mối này dẫn họ tìm tới những góc tối tăm nhất, tận cùng của vũ trụ. Tại đó, họ phải đối mặt với một cuộc chiến đầy khiếp sợ để cứu tương lai của nhân loại. Prometheus 3D có sự tham gia của dàn diễn viên tài năng: Michael Fassbender, Charlize Theron, Idris Elba, Logan Marshall-Green và Guy Pearce. Cùng chờ đợi đến ngày 8.6.2012 để trải nghiệm và tự cảm&nbsp; nhận bộ phim thú vị này như thế nào.</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Noomi Rapace","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"Sean Harris","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Emun Elliott","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Kate Dickie","avatar":""},{"name":"Branwell Donaghey","avatar":""},{"name":"Vladimir \"Furdo\" Furdik","avatar":""},{"name":"C.C. Smiff","avatar":""},{"name":"Shane Steyn","avatar":""},{"name":"Ian Whyte","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324468);
