INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dien-hy-su-2012', 'Hoa Điền Hỷ Sự', 'All''s Well End''s Well', 'https://phimimg.com/upload/vod/20231012-1/5828eb323b4469baea4d75bdc7c345db.jpg', 'https://phimimg.com/upload/vod/20231012-1/846ff2bcc0793cc69d301dab82193220.jpg', '<p>Bốn người đàn ông thực hiện một sứ mệnh anh hùng để giúp đỡ bốn người phụ nữ và trải qua một loạt các rủi ro.</p>', 'Full', 1, 'single', 'completed', 16, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Hiro Hayama","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Lam Suet","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324468);
