INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-kieu-va-chi-minh', 'Xuân Kiều Và Chí Minh', 'Love In The Buff', 'https://phimimg.com/upload/vod/20231012-1/6cc42de93bf4edce0262d0ba8e1d25ed.jpg', 'https://phimimg.com/upload/vod/20231012-1/65b05077948fae910d6cd5cf56ae4c82.jpg', '<p>Khi ngọn lửa cũ đoàn tụ, đó sẽ là lần thứ hai có duyên hay là trường hợp một lần cắn hai lần ngượng ngùng? Jimmy và Cherie, hai người yêu cũ đến từ Hồng Kông, gặp nhau ở Bắc Kinh và dường như không thể quên nhau dù đã có quan hệ với người khác. Bị giằng xé giữa việc chung thủy với người bạn đời mới hay nghe theo trái tim mình, họ khám phá những khó khăn, nghi ngờ và sợ hãi tồn tại giữa các cặp vợ chồng trẻ hiện đại.</p>', 'Full', 1, 'single', 'completed', 13, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Miriam Yeung","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Xu Zheng","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Roy Szeto","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Isabel Chan Yat-Ning","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Mia Yam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324468);
