INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-toi-khong-dang-tin', 'Chồng Tôi Không Đáng Tin', 'My Sassy Hubby', 'https://phimimg.com/upload/vod/20231010-1/345e642077a81222f0449670f2f0eb9c.jpg', 'https://phimimg.com/upload/vod/20231010-1/8d9dd1754ed53fc54bd959ef355f8b45.jpg', '<p>Người chồng ngổ ngáo của tôi theo chân Yoyo Ma và Thập Tam Trương 10 năm sau cho đến ngày nay khi họ đang gặp phải những vấn đề trong hôn nhân. Sau khi nhận ra rằng lễ cưới tổ chức ở London không được coi là chính thức ở Hồng Kông, họ quyết định chia tay để tìm kiếm tình yêu thực sự của mình. Trong khi Yoyo và Thirteen đều bắt đầu hẹn hò với những khách hàng tiềm năng mới, liệu họ có quay lại với nhau không?</p>', 'Full', 1, 'single', 'completed', 18, 2012, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Xu Zhengxi","avatar":""},{"name":"Joyce Cheng","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Susan Shaw Yam Yam","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"JJ Jia","avatar":""},{"name":"Sandy Lam San-San","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
