INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-lam-nguoi-xau-phan-5', 'Tập làm người xấu (Phần 5)', 'Breaking Bad (Season 5)', 'https://phimimg.com/upload/vod/20231006-1/6ca020a81ec7d679958802d5821636e3.jpg', 'https://phimimg.com/upload/vod/20231006-1/f299815b16844779bcea138fc5203869.jpg', '<p>Trong mùa cuối, cái xấu không còn chỉ là một hành động khi vòng xoáy biến chất đưa Walt trở thành ông trùm của một đế chế ma túy, đe dọa mọi thứ và mọi người.</p>', 'Hoàn tất (16/16)', 16, 'series', 'completed', 22, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bryan Cranston","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Anna Gunn","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Betsy Brandt","avatar":""},{"name":"RJ Mitte","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Steven Michael Quezada","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Giancarlo Esposito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
