INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-bo-gap-me-phan-8', 'Khi Bố Gặp Mẹ (Phần 8)', 'How I Met Your Mother (Season 8)', 'https://phimimg.com/upload/vod/20231001-1/a0aaebddf1d6995577ffa332b32a100c.jpg', 'https://phimimg.com/upload/vod/20231001-1/6829cc93abe622a74686477368964faa.jpg', '<p>“Khi Bố Gặp Mẹ” đã quay lại với mùa 8 đầy tiếng cười. Tiếp tục với câu chuyện Ted đã yêu như thế nào. Mọi chuyện bắt đầu khi người bạn thân nhất của Ted, luật sư môi trường đầy tham vọng Marshall, cầu hôn người yêu thời đại học của anh, Lily, một giáo viên mẫu giáo. Giờ cả hai đã có con, Ted nhận ra rằng tốt hơn hết anh nên bắt tay vào việc này nếu anh quá hy vọng tìm được tình yêu đích thực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Cristin Milioti","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324468);
