INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dang', 'Hoa Dạng', 'Ripples of Desire', 'https://phimimg.com/upload/vod/20230915-1/7971e87aaaf644b7f240c00a3c6406e5.jpg', 'https://phimimg.com/upload/vod/20230915-1/292c50be0c8b16df9d6b2bab4cb8df26.jpg', '<p><span style="font-family: ">Hoa Dạng: Một hòn đảo cho những kẻ lưu lạc Một con phố hoa rực rỡ Câu chuyện giữa 2 ca kỹ tuổi 17 và tên hải tặc hiệp nghĩa. Trong thời thế hỗn loạn giữa công đạo và chính nghĩa - con người phải đối mặt với những thử thách về tình yêu và tính người</span></p>', 'Full', 1, 'single', 'completed', 27, 2012, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Jerry Yan Cheng-Xu","avatar":""},{"name":"Cheng Yuan-Chang","avatar":""},{"name":"Michelle Chen","avatar":""},{"name":"Ivy Chen","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Li Xiaoran","avatar":""},{"name":"Mao Zijun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324468);
