INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu', 'Trò Chơi Sinh Tử', 'The Hunger Games', 'https://phimimg.com/upload/vod/20230912-1/f5720340649845b17c75525ed5cda668.jpg', 'https://phimimg.com/upload/vod/20230912-1/0590288e46812cbe9fed7bdfa8c5e860.jpg', '<p>The Hunger Game đặt trong bối cảnh khu vực bắc mỹ bị hủy hoại do thiên tai và chiến tranh, cả khu vực trở thành một Panem với Capitol và 13 huyện. Mỗi năm sẽ có 24 thanh niên của 12 huyện được lựa chọn để tham gia một Trò chơi sinh tử được tường thuật cho cả đất nước xem trong đó chỉ có một người gan dạ và mưu trí nhất mới có thể sống và chiến thắng. Đây là tác phẩm hấp dẫn mang đậm triết lý “ai mạnh thì sống”, bên cạnh đó phim ca ngợi khát vọng sống, tình yêu của những người trẻ tuổi. Được giới phê bình phim đánh giá khá cao, The Hunger Game đã tạo ra một cơn sốt các phòng chiếu Bắc mỹ.</p>', 'Full', 1, 'single', 'completed', 36, 2012, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Lenny Kravitz","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Wes Bentley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324468);
