INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-do-phan-3', 'Phong Độ (Phần 3)', 'Hung (Season 3)', 'https://phimimg.com/upload/vod/20260630-1/0bf9270b586438799d2822fc8678005d.jpg', 'https://phimimg.com/upload/vod/20260630-1/0d2f9cfe31c0983d60f26d690d0355aa.jpg', '<p>Những thời khắc tuyệt vọng đòi hỏi những biện pháp cực đoan, và hoàn cảnh của Ray Drecker lúc này quả thực không thể bi đát hơn. Từ một huyền thoại thể thao thời trung học, giờ đây ở tuổi trung niên, anh phải chật vật với đồng lương huấn luyện viên bóng rổ, vừa ly dị vợ, vừa phải gồng gánh nuôi con thì căn nhà vốn đã xập xệ lại bất ngờ bị hỏa hoạn. Để tìm kiếm một công việc tay trái nhằm trang trải cuộc sống, Ray quyết định khai thác &quot;vốn tự có&quot; trời ban của mình như một nỗ lực cuối cùng để thay đổi số phận.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 34, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Charlie Saxton","avatar":""},{"name":"Sianoa Smit-McPhee","avatar":""},{"name":"Rebecca Creskoff","avatar":""},{"name":"Gregg Henry","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Lennie James","avatar":""},{"name":"Stephen Amell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Na velikosti záleží","Hung (Superdotado)","Hung"]', 1784690324468);
