INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-la-so-1-phan-3', 'Gia Đình Là Số 1 (Phần 3)', 'High Kick (Season 3)', 'https://phimimg.com/upload/vod/20240829-1/05ea25e9f2011df44e92839c5973be05.jpg', 'https://phimimg.com/upload/vod/20240829-1/a0cd73eac83d6f6c967485b05a0f84b8.jpg', '<p>Trong phim Gia Đình Là Số 1 Phần 3, Ahn Nae Sang và Yoon Yoo Sun là đôi vợ chồng trung niên. Khi người chồng phá sản, gia đình họ phải chuyển về nhà của em vợ để sống cùng. Từ đây, mâu thuẫn cũng bắt đầu nảy sinh.Sẽ không còn tình tiết gây mỏi mệt như phần 2 mà sẽ toàn tiếng cười, bởi đó là thứ ta còn thiếu trong cuộc sống này. Bộ phim Gia Đình Là Số 1 Phần 3 đã lăng xê thành công nhiều tên tuổi từ những phần trước đó và thu hút khán giả bởi những tình tiết hài hước, vui nhộn nhưng cũng đầy ý nghĩa về gia đình</p>', 'Hoàn Tất (123/123)', 123, 'series', 'completed', 65, 2011, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"안내상","avatar":""},{"name":"윤유선","avatar":""},{"name":"윤계상","avatar":""},{"name":"박하선","avatar":""},{"name":"서지석","avatar":""},{"name":"이종석","avatar":""},{"name":"정수정","avatar":""},{"name":"Go Young-wook","avatar":""},{"name":"박지선","avatar":""},{"name":"Yoon Gun","avatar":""},{"name":"김지원","avatar":""},{"name":"줄리엔 강","avatar":""},{"name":"백진희","avatar":""},{"name":"이적","avatar":""},{"name":"강승윤","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324468);
