INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-sang-phan-1', 'Khai Sáng (Phần 1)', 'Enlightened (Season 1)', 'https://phimimg.com/upload/vod/20260616-1/e573b60620b7bd2972c789ca59cf05c6.jpg', 'https://phimimg.com/upload/vod/20260616-1/8439e123cfa0fc47abfb9e56a178409f.jpg', '<p>Sau một lần suy sụp tinh thần nghiêm trọng ngay trước mắt công chúng và trải qua một cuộc thức tỉnh triết lý sâu sắc trong thời gian ở trại cai nghiện/phục hồi chức năng, Amy quyết tâm quay trở lại để sắp xếp và vực dậy cuộc đời mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mike White","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Timm Sharp","avatar":""},{"name":"Diane Ladd","avatar":""},{"name":"Sarah Burns","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Iluminada","Enlightened : illuminée","Enlightened"]', 1784690324468);
