INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gio-phieu-luu-phan-3', 'Giờ Phiêu Lưu (Phần 3)', 'Adventure Time (Season 3)', 'giờ phiêu lưu (phần 3) adventure time (season 3) jeremy shada john dimaggio tom kenny hynden walch olivia olson niki yang pendleton ward polly lou livingston hora de aventura com finn e jake hora de aventura 探险活宝 abenteuerzeit mit finn und jake eventyrtid hora de aventuras время приключений с финном и джейком час пригод разом із фіном та джейком adventure time with finn & jake adventure time: stakes adventure time with finn jake adventure time', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-de-yeu-ngay-nao-do', 'Một Ngày Để Yêu (Ngày Nào Đó)', 'One Day', 'https://phimimg.com/upload/vod/20260608-1/79775fcc01c25016fb356195d9ccef47.jpg', 'https://phimimg.com/upload/vod/20260608-1/091bd4a4b5ca012c8e21676a24f6aa6a.jpg', '<p>Được chuyển thể từ tiểu thuyết cùng tên của tác giả David Nicholls, phim là hành trình tình yêu kéo dài gần 20 năm của hai nhân vật Dexter và Emma. Sau đêm thân mật tại lễ tốt nghiệp đại học trong này, hàng năm cả hai lại hẹn gặp nhau một ngày để biết cuộc sống hiện tại của người kia. Họ cũng có cảm tình với nhau, nhưng chỉ quyết định gặp nhau một năm một lần.</p>', 'Full', 1, 'single', 'completed', 25, 2011, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Tom Mison","avatar":""},{"name":"Jodie Whittaker","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Ken Stott","avatar":""},{"name":"Romola Garai","avatar":""},{"name":"Matt Berry","avatar":""},{"name":"Toby Regbo","avatar":""},{"name":"Matthew Beard","avatar":""},{"name":"Georgia King","avatar":""},{"name":"Heida Reed","avatar":""},{"name":"Joséphine de la Baume","avatar":""},{"name":"Amanda Fairbank-Hynes","avatar":""},{"name":"Diana Kent","avatar":""},{"name":"James Laurenson","avatar":""},{"name":"Sé","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["En dag","Um Dia","Den samme dag næste år","Egy nap","Jeden den","Samme dag næste år","Un jour","One Day (Siempre el Mismo Día)","f-oneday","One Day with Anne Hathaway","Siempre el Mismo Día","Винаги в същия ден","Bir Gün","원 데이","원데이","Siempre el mismo día","真愛挑日子","One Day","一天"]', 1784690324468);
