INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-ngay-de-yeu-ngay-nao-do', 'Một Ngày Để Yêu (Ngày Nào Đó)', 'One Day', 'một ngày để yêu (ngày nào đó) one day anne hathaway jim sturgess tom mison jodie whittaker rafe spall patricia clarkson ken stott romola garai matt berry toby regbo matthew beard georgia king heida reed joséphine de la baume amanda fairbank-hynes diana kent james laurenson sé en dag um dia den samme dag næste år egy nap jeden den samme dag næste år un jour one day (siempre el mismo día) f-oneday one day with anne hathaway siempre el mismo día винаги в същия ден bir gün 원 데이 원데이 siempre el mismo día 真愛挑日子 one day 一天', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-8', 'Chuyện Văn Phòng (Phần 8)', 'The Office (Season 8)', 'https://phimimg.com/upload/vod/20260604-1/0c8ceab4953883b55be24e9a5cc85a44.jpg', 'https://phimimg.com/upload/vod/20260604-1/d7622bf1a086c33e343121a9ffdcdc4d.jpg', '<p>Phần thứ tám chủ yếu xoay quanh việc Andy Bernard lên làm giám đốc khu vực, cũng như những trò hề của Robert California, Giám đốc điều hành mới của Sabre, một công ty máy in hư cấu sở hữu Dunder Mifflin. Nửa mùa giải, Dwight Schrute —cùng với Jim Halpert, Stanley Hudson, Ryan Howard, Erin Hannon và Cathy —đi đến Florida để giúp thành lập Cửa hàng Sabre, nơi Nellie Bertram được giới thiệu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 26, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324468);
