INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-heck-phan-3', 'Gia đình Heck (Phần 3)', 'The Middle (Season 3)', 'gia đình heck (phần 3) the middle (season 3) patricia heaton neil flynn charlie mcdermott eden sher atticus shaffer 左右不逢源 中产家庭 中之道 anyám borogass családom és egyéb emberfajták ザ・ミドル ～中流家族のフツーの幸せ～ คุณแม่สามัญประจำบ้าน the middle', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-sup-do-phan-1', 'Bầu Trời Sụp Đổ (Phần 1)', 'Falling Skies (Season 1)', 'https://phimimg.com/upload/vod/20260515-1/277761a10a22eecfd831cf9477b49e86.jpg', 'https://phimimg.com/upload/vod/20260515-1/e6c7c7b7579aa5dd343a35d5e3954781.jpg', '<p>Falling Skies mở ra trong bối cảnh hỗn loạn sau cuộc tấn công của người ngoài hành tinh khiến phần lớn thế giới mất khả năng hoàn toàn. &nbsp;Trong sáu tháng kể từ cuộc xâm lược đầu tiên, một số ít người sống sót đã tập hợp lại bên ngoài các thành phố lớn để bắt đầu nhiệm vụ khó khăn chiến đấu trở lại. &nbsp;Mỗi ngày là một bài kiểm tra khả năng sống sót khi những người lính công dân làm việc để bảo vệ những người dân được họ chăm sóc trong khi cũng tham gia vào một chiến dịch nổi dậy chống lại lực lượng người ngoài hành tinh đang chiếm đóng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 29, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Noah Wyle","avatar":""},{"name":"Moon Bloodgood","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Drew Roy","avatar":""},{"name":"Connor Jessup","avatar":""},{"name":"Maxim Knight","avatar":""},{"name":"Colin Cunningham","avatar":""},{"name":"Sarah Carter","avatar":""},{"name":"Mpho Koaho","avatar":""},{"name":"Doug Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qu