INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('michael-jackson-cuoc-doi-cua-mot-bieu-tuong', 'Michael Jackson: Cuộc đời Của Một Biểu Tượng', 'Michael Jackson: The Life Of An Icon', 'https://phimimg.com/upload/vod/20260514-1/a569251d1ee11bf1ae7055513094d5ce.jpg', 'https://phimimg.com/upload/vod/20260514-1/e2a25c2910d79ccdd58b76da4560ded0.jpg', '<p>Hãy cùng chiêm ngưỡng Michael Jackson, một trong những nghệ sĩ giải trí nổi tiếng và được yêu mến nhất mọi thời đại, theo một cách chưa từng có trong bộ phim dài tưởng nhớ Michael Jackson: Cuộc đời của một biểu tượng. Được hàng triệu người hâm mộ trên toàn thế giới biết đến với những album phá kỷ lục, các video âm nhạc đột phá, những bước nhảy mê hoặc và những nỗ lực nhân đạo, câu chuyện thật sự của ông chưa bao giờ được kể... cho đến bây giờ. Cái nhìn chưa từng có này về cuộc đời hấp dẫn của Vua nhạc Pop bao gồm các cuộc phỏng vấn hoàn toàn mới với mẹ ông, Katherine Jackson, cũng như các anh chị em Tito và Rebbie Jackson, cháu trai Jaafar Jackson và cháu gái Tahkyah, cùng nhiều khoảnh khắc đáng nhớ của Jackson và bạn bè, và các huyền thoại âm nhạc như Smokey Robinson, Dionne Warwick và 3 người con của ông, cùng nhiều người khác nữa.</p>', 'Trailer', 1, 'single', 'ongoing', 24, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Jackson","avatar":""},{"name":"Tito Jackson","avatar":""},{"name":"Rebbie Jackson","avatar":""},{"name":"Katherine Jackson","avatar":""},{"name":"Frank DiLeo","avatar":""},{"name":"Whitney Houston","avatar":""},{"name":"Freda Payne","avatar":""},{"name":"Thomas Mesereau","avatar":""},{"name":"Percy Sledge","avatar":""},{"name":"Petula Clark","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Michael Jackson: La vida de un ídolo","Michael Jackson - The Life Of An Icon","Michael Jackson: The Life of an Icon"]', 1784690324468);
