INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('michael-jackson-cuoc-doi-cua-mot-bieu-tuong', 'Michael Jackson: Cuộc đời Của Một Biểu Tượng', 'Michael Jackson: The Life Of An Icon', 'michael jackson: cuộc đời của một biểu tượng michael jackson: the life of an icon michael jackson tito jackson rebbie jackson katherine jackson frank dileo whitney houston freda payne thomas mesereau percy sledge petula clark michael jackson: la vida de un ídolo michael jackson - the life of an icon michael jackson: the life of an icon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tinh-nghi-phan-1', 'Kẻ Tình Nghi (Phần 1)', 'Person of Interest (Season 1)', 'https://phimimg.com/upload/vod/20260512-1/437b0907f75a93401ea7c751cfde649b.jpg', 'https://phimimg.com/upload/vod/20260512-1/f0843b81542f0feca1f5fbd0bd898578.jpg', '<p>John Reese, cựu nhân viên bán quân sự của CIA, được cho là đã chết và hợp tác với tỷ phú ẩn dật Finch để ngăn chặn tội phạm bạo lực ở thành phố New York bằng cách khởi xướng kiểu công lý của riêng họ. Với sự đào tạo đặc biệt mà Reese đã có trong Hoạt động bí mật và bộ óc phát minh phần mềm thiên tài của Finch, cả hai là sự kết hợp hoàn hảo cho công việc mà họ phải hoàn thành. Với sự trợ giúp của thiết bị giám sát, họ làm việc &quot;ngoài vòng pháp luật&quot; và bắt đúng tội phạm sau song sắt.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 19, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jim Caviezel","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Amy Acker","avatar":""},{"name":"Sarah Shahi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Personne d''intérêt","嫌疑人","Kohde","ინტერესის ობიექტი","مظنون","فرد تحت نظر","مظنون تحت نظر","Suspectul","Подозреваемый","บุคคลต้องสงสัย","Особливо небезпечно","У полі зору","P.O.I","Person of Interest"]', 1784690324468);
