INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-nao-cua-phat-3', 'Đại Náo Cửa Phật 3', 'The Monk And The Mafia', 'https://phimimg.com/upload/vod/20260513-1/96283e1c138bfb95a7c11afeaa39f1c4.jpg', 'https://phimimg.com/upload/vod/20260513-1/320ccbc9e6b35ebdd1f8b450de15b51f.jpg', '<p>Một doanh nhân thuê một chuyến bay riêng đến Tây Tạng để đón một vị sư. Trên đường trở về, chiếc máy bay bị không tặc khống chế, khiến vị sư lạc vào một vùng chiến sự hiểm nguy. Tại đây, ông phải đối mặt với những tên cướp tàn bạo và tìm cách thuyết phục chúng từ bỏ con đường tội lỗi để hướng thiện. Giữa khói lửa chiến tranh, lòng từ bi và sự kiên định của vị sư trở thành tia hy vọng duy nhất để thay đổi những tâm hồn đã bị tha hóa.</p>', 'Full', 1, 'single', 'completed', 21, 2011, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Choosak Iamsuk","avatar":""},{"name":"Amena Pinit","avatar":""},{"name":"Somlek Sakdikul","avatar":""},{"name":"Somchai Kemklad","avatar":""},{"name":"Nattawut Palapinyo","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Boriboon Junreurng","avatar":""},{"name":"Bunyawan Pongsuwan","avatar":""},{"name":"Siwadon Chantanasewi","avatar":""},{"name":"Panuphan Khrutto","avatar":""},{"name":"Chookiat Iamsook","avatar":""},{"name":"Thomas James Lavelle","avatar":""},{"name":"Kietkajorn Tuamde","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เท่ง โหน่ง จีวรบิน","Teng Nong Jiworn Bin","เท่งโหน่งจีวรบิน","เท่งโหน่ง จีวรบิน"]', 1784690