INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bao-thu-tron-bo-dam-mau', 'Cô Dâu Báo Thù: Trọn Bộ Đẫm Máu', 'Kill Bill: The Whole Bloody Affair', 'https://phimimg.com/upload/vod/20260508-1/ff5631b5b7e1899f4233745b803a72e7.jpg', 'https://phimimg.com/upload/vod/20260508-1/51db6f6b0b61cfe017930938caba1aee.jpg', '<p>Tác phẩm hoàn chỉnh của Quentin Tarantino, kết hợp Kill Bill: Vol. 1 và Vol. 2, theo chân The Bride — một sát thủ đã rời bỏ giới giang hồ — tỉnh dậy sau bốn năm hôn mê vì bị chính người thầy và người tình của mình, Bill, bắn hạ. Cô bắt đầu hành trình báo thù tàn khốc, quyết tâm tiêu diệt Bill và nhóm sát thủ Deadly Viper Assassination Squad đã phản bội cô.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"David Carradine","avatar":""},{"name":"千葉真一","avatar":""},{"name":"Julie Dreyfus","avatar":""},{"name":"栗山千明","avatar":""},{"name":"劉家輝","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["킬 빌: 더 홀 블러디 어페어","追殺比爾：整齣滿江紅","追殺比爾：整個血腥事件","標殺令：整個血腥事件","Kill Bill: Kompletní krvavá aféra","Убить Билла: Кровавое дело целиком","Kill Bill: The Whole Bloody Affair"]', 1784690324469);
