INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-5-phi-vu-rio', 'Quá Nhanh Quá Nguy Hiểm 5: Phi vụ Rio', 'Fast Five', 'https://phimimg.com/upload/vod/20260225-1/205435e2bc9a19b20a3f9cf6512599a7.jpg', 'https://phimimg.com/upload/vod/20260225-1/0295b1008f36cfd1c71f309bb8f9bfa3.jpg', '<p>Kể từ khi Brian O’Conner và Mia Toretto cứu thoát Dominic Toretto khỏi trại giam, họ đã phải chạy qua nhiều biên giới để trốn tránh sự truy đuổi của nhà cầm quyền. Tới Rio de Janeiro, họ phải tham gia vào một công việc cuối cùng để có được sự tự do cho mình. Khi họ tập hợp đội ngũ những tay đua hàng đầu, mọi người đều không biết rằng công việc cuối cùng này đưa họ đối đầu với một doanh nhân tham lam, người đang muốn họ phải chết. Nhưng ông ta không phải là người duy nhất đuổi theo họ...</p>', 'Full', 1, 'single', 'completed', 25, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vin Diesel","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Matt Schulze","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Tego Calderon","avatar":""},{"name":"Don Omar","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Michael Irby","avatar":""},{"name":"Fernando Chien","avatar":""},{"name":"Alimi Ballard","avatar":""},{"name":"Yorgo Constantine","avatar":""},{"name":"Geoff Meed","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5