INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('transformers-vung-toi-cua-mat-trang', 'Transformers: Vùng Tối Của Mặt Trăng', 'Transformers: Dark of the Moon', 'https://phimimg.com/upload/vod/20260225-1/c46a0e0467ad12e066cef1348a25c6a3.jpg', 'https://phimimg.com/upload/vod/20260225-1/534468be277cbd94276f2189be7c537c.jpg', '<p>Bối cảnh phim diễn ra ở Trái đất với nội dung ngoài yếu tố hấp dẫn, hài hước thì phần 3 được bật mí sẽ cực kì bí ẩn. Phe Autobots gồm Bumblebee, Ratchet, Ironhide và Sideswipe do Optimus Prime lãnh đạo sẽ trở lại và đối đầu với phe Decepticons xấu xa, những kẻ quyết tâm trả thù cho thất bại của chúng. Trong phần mới này, phe Autobots và phe Decepticons sẽ tham gia vào một cuộc chạy đua vào vũ trụ nguy hiểm giữa Mỹ và Nga, và một lần nữa anh chàng Sam Witwicky đã đến với sự trợ giúp của những người bạn robot của mình. Phần phim này sẽ có những nhân vật mới, trong đó có một nhân vật phản diện mới trong tạo hình Shockwave, kẻ độc tài lên ngôi đứng đầu hành tinh Cybertron khi 2 phe Decepticons và Autobots rời nơi này để chiến đấu trên Trái Đất.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Rosie Huntington-Whiteley","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Patrick Dempsey","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Julie White","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Lester Spe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Transformers 3: O Lado Oculto da Lua","Transformers 3","Transformers III: Dark of the Moon (2011)","Transformers 3: El lado oscuro de la Luna","變形金剛3：黑月降臨","Transformers: Dark of the Moon","Transformers 3 - resta solo la terra","Transformers 3 - Die dunkle Seite des Mondes","Transformers :The Dark Side of the Moon","Transformeriai 3","Transformers 3: Dark of the Moon","Transformers 3: A Hold sötétsége","Transformers - Dark of the Moon","Transformerlar 3","Transformerlar 3: Oyning qorongʻi tomoni","Transformers 3 - Dark of the Moon","变形金刚3：月黑之时","Transformers: Temná strana Měsíce","Robot Đại Chiến 3: Bóng Tối Mặt Trăng","トランスフォーマー／ダークサイド・ムーン：2011","变形金刚3：黑月降临","Transformers: Vùng Tối Của Mặt Trăng","Transformers 3: Ay''ın Karanlık Yüzü","Transformers 3: Ay''ın Qaranlıq Üzü","트랜스포머 3","Transformers: Partea întunecată a Lunii","變形金剛：黑月降臨","变形金刚：黑月降临","트랜스포머: 달의 어둠","트랜스포머 3: 달의 어둠","Трансформеры 3: Тёмная сторона Луны"]', 1784690324469);
