INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tay-du-ky-2011', 'Tân Tây Du Ký', 'Journey To The West', 'https://phimimg.com/upload/vod/20260222-1/3740491170b602d4fe704347eeae128c.jpg', 'https://phimimg.com/upload/vod/20260222-1/ae7d4c818f797cadc8d9ec899cbabd4b.jpg', '<p>Bộ phim kể về hành trình thỉnh kinh đầy gian nan của Đường Tăng cùng ba đồ đệ là Tôn Ngộ Không, Trư Bát Giới và Sa Tăng trên đường sang Tây Trúc lấy chân kinh. Trải qua 81 kiếp nạn, thầy trò phải đối mặt với vô số yêu ma quỷ quái cùng những cám dỗ về danh lợi, tình cảm và quyền lực. Trong suốt chặng đường, mỗi người dần vượt qua điểm yếu của bản thân, học cách tin tưởng, hy sinh và bảo vệ lẫn nhau. Sau bao thử thách sinh tử, thầy trò Đường Tăng cuối cùng cũng hoàn thành sứ mệnh, tu thành chính quả và mang chân kinh trở về, góp phần phổ độ chúng sinh.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 24, 2011, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trình Lực Đống","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Từ Cẩm Giang","avatar":""},{"name":"Tàng Kim Sinh","avatar":""},{"name":"Lưu Đào","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Trần Tư Hàn","avatar":""},{"name":"Triệu Nghị","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["09西游记","张版西游记","西游记"]', 1784690324469);
