INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-la-so-may', 'Anh Là Số Mấy?', 'What''s Your Number?', 'https://phimimg.com/upload/vod/20260206-1/10770b62ddf759602bc221a17daf189a.jpg', 'https://phimimg.com/upload/vod/20260206-1/a10c498ace6d6f4265189e1fd7c3c683.jpg', '<p>Nghĩ rằng tri kỷ đích thực của cô có thể nằm trong số nhiều tình cũ, Ally bắt đầu sứ mệnh tìm kiếm tình cũ để xem ai có thể là nửa kia hoàn hảo cho mình.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anna Faris","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Blythe Danner","avatar":""},{"name":"Ed Begley Jr.","avatar":""},{"name":"Oliver Jackson-Cohen","avatar":""},{"name":"Heather Burns","avatar":""},{"name":"Eliza Coupe","avatar":""},{"name":"Kate Simses","avatar":""},{"name":"Tika Sumpter","avatar":""},{"name":"Dave Annable","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Denise Vasi","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Thomas Le","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Sex list","先生，你哪位","你上过几个","Sexlist","Prima di te","Сколько у тебя.","What''s Your Number?"]', 1784690324469);
