INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tan-cong-lassaut', 'Cuộc Tấn Công (L''Assaut)', 'The Assault', 'https://phimimg.com/upload/vod/20260127-1/5bbab90a4124d4a812b24db52cd03e53.jpg', 'https://phimimg.com/upload/vod/20260127-1/6a5182f39bf4f2a5081788115d1dfae7.jpg', '<p>Tháng 12 năm 1994. Vào thứ Bảy ngày 24, bốn tên khủng bố thuộc nhóm GIA đã chiếm quyền kiểm soát chiếc máy bay Airbus A300 của hãng hàng không Air France tại sân bay Algiers. Chiếc máy bay đang chuẩn bị khởi hành đi Paris với 227 hành khách trên khoang.</p>', 'Full', 1, 'single', 'completed', 19, 2011, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Vincent Elbaz","avatar":""},{"name":"Grégori Derangère","avatar":""},{"name":"Mélanie Bernier","avatar":""},{"name":"Aymen Saïdi","avatar":""},{"name":"Chems Dahmani","avatar":""},{"name":"Mohid Abid","avatar":""},{"name":"Djanis Bouzyani","avatar":""},{"name":"Marie Guillard","avatar":""},{"name":"Naturel Le Ruyet","avatar":""},{"name":"Philippe Bas","avatar":""},{"name":"Philippe Cura","avatar":""},{"name":"Grégoire Taulère","avatar":""},{"name":"Charlie Costillas","avatar":""},{"name":"Ludovic Meacci","avatar":""},{"name":"Laurent Paillot","avatar":""},{"name":"Antoine Basler","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The assault: il volo del terrore","フランス特殊部隊 GIGN（ジェイジェン） 〜エールフランス8969便ハイジャック事件〜","L''Assaut"]', 1784690324469);
