INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-ngay-de-song', '10 Ngày Để Sống', 'Countdown', 'https://phimimg.com/upload/vod/20260126-1/348310139c74f4a5104ca1e2052622b5.jpg', 'https://phimimg.com/upload/vod/20260126-1/6e9963721c0026a7edc5b57a04b46d6b.jpg', '<p>Phim 10 Ngày Để Sống kể về Tae Geon Ho, một người đàn ông máu lạnh làm nghề đòi nợ, anh ta luôn thực hiện xuất sắc công việc này với tỉ lệ thành công 100% và một phụ nữ xinh đẹp giỏi nói dối mang trong mình tiền án lừa đảo, Cha Ha Yeon (Jeon Do Yeon đóng). Mục tiêu mới nhất của tay siết nợ Tae Geon Ho là người phụ nữ bí ẩn vừa mãn hạn tù Cha Ha Yeon. Để trả thù những kẻ từng đưa mình vào tù, Cha Ha Yeon đã lợi dụng chính Geon Ho để lên một kế hoạch kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Jae-young","avatar":""},{"name":"Jeon Do-yeon","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Lee Min-young","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Song Hye-kyo","avatar":""},{"name":"Shin Sun-hee","avatar":""},{"name":"Woo Mi-hwa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["카운트다운","Countdown","Ka-woon-teu-da-woon","Kawoonteudawoon","カウントダウン：2011"]', 1784690324469);
