INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-mon-phi-giap', 'Long Môn Phi Giáp', 'Flying Swords of Dragon Gate', 'https://phimimg.com/upload/vod/20260109-1/ddebd64456072e7acd4752e5c4642d71.jpg', 'https://phimimg.com/upload/vod/20260109-1/6d6a168c2cd0f7b243793a4a1bc89fff.jpg', '<p>Long Môn Phi Giáp xuất hiện sau ba năm kể từ khi Lông Môn Khách Sạn khét tiếng bị thiêu rụi trong sa mạc khi người chủ quán trọ Jade của nó biến mất. Một băng nhóm marauder mới đã tiếp quản - những người chủ quán trọ vào ban ngày và những kẻ săn kho báu vào ban đêm. Nhà trọ là địa điểm được đồn đại của một thành phố đã mất bị chôn vùi dưới sa mạc, và kho báu ẩn giấu của nó sẽ chỉ được tiết lộ bởi một cơn bão khổng lồ cứ sau 60 năm. Băng nhóm này đã sử dụng nhà trọ làm bình phong để xác định vị trí kho báu bị mất.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Chen Kun","avatar":""},{"name":"Gwei Lun-Mei","avatar":""},{"name":"Chris Lee Yuchun","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Mavis Fan","avatar":""},{"name":"Du Yiheng","avatar":""},{"name":"Viann Zhang Xinyu","avatar":""},{"name":"Sheng Chien","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""},{"name":"Wang Shuangbao","avatar":""},{"name":"Sun Jiankui","avatar":""},{"name":"Han Feixing","avatar":""},{"name":"Temur Gang","avatar":""},{"name":"Li Junru","avatar":""},{"name":"Dillon Wu Di","avatar":""},{"name":"Zhang Dong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c4301