INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-lo-lem', 'Tiểu Thư Lọ Lem', 'Monte Carlo', 'https://phimimg.com/upload/vod/20251228-1/b1c14281723c0c23385f4f52d0cac7b8.jpg', 'https://phimimg.com/upload/vod/20251228-1/1b3699bf428fdc9f7053f4a3c0083c11.jpg', '<p>Trên hành trình đến Paris, Grace, Meg và Emma lại bỗng gặp bao chuyện dở khóc dở cười. Grace bị nhận nhầm là tiểu thư thừa kế hư hỏng khiến cả ba cuốn vào chuyến phiêu lưu mơ ước tới Monte Carlo.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Selena Gomez","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"Leighton Meester","avatar":""},{"name":"Cory Monteith","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Pierre Boulanger","avatar":""},{"name":"Amanda Fairbank-Hynes","avatar":""},{"name":"Valérie Lemercier","avatar":""},{"name":"Joe Camp III","avatar":""},{"name":"Franck de la Personne","avatar":""},{"name":"Máté Haumann","avatar":""},{"name":"István Göz","avatar":""},{"name":"Attila Árpa","avatar":""},{"name":"Joël Lefranço","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Monte Carlo","Монте - Карло","Des vacances de princesse","몬테카를로","恋するモンテカルロ"]', 1784690324469);
