INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi-tuoi-teen-phan-1', 'Người Sói Tuổi Teen (Phần 1)', 'Teen Wolf (Season 1)', 'https://phimimg.com/upload/vod/20251214-1/559d237a3e7887a869f18b1e95698e3f.jpg', 'https://phimimg.com/upload/vod/20251214-1/cf13adac952a4db38a0d7a0300d44289.jpg', '<p>Vết thú cắn biến một học sinh cấp ba thành người sói. Khả năng siêu nhiên mới giúp cậu thành ngôi sao thể thao – và cũng khiến cuộc sống của cậu vô cùng phức tạp.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tyler Posey","avatar":""},{"name":"Holland Roden","avatar":""},{"name":"Shelley Hennig","avatar":""},{"name":"Dylan Sprayberry","avatar":""},{"name":"Linden Ashby","avatar":""},{"name":"Melissa Ponzio","avatar":""},{"name":"JR Bourne","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Младият върколак","Тийн вълк","Teen Wolf","گرگ نوجوان","Lobo Adolescente","Оборотень","Genç Kurt","Молодий вовк"]', 1784690324469);
