INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-ky-an', 'Giang Hồ Kỳ Án', 'Jianghu Mystery', 'https://phimimg.com/upload/vod/20251110-1/b9042bc589df2ba7562df652bda71163.jpg', 'https://phimimg.com/upload/vod/20251110-1/333a11956d6c60e07f2048ecd42cb1f4.jpg', '<p>Bọ phim&nbsp;xoay quanh những vụ án kỳ bí xảy ra trong giang hồ. Nhân vật chính là các vị quan thông minh, nghĩa hiệp và những hiệp khách võ công cao cường, cùng nhau phá giải những vụ án ly kỳ liên quan đến âm mưu, quyền lực và tình cảm. Phim kết hợp yếu tố võ hiệp với điều tra phá án, vừa gay cấn, hồi hộp vừa thấm đẫm chất nhân văn, phản ánh sự phức tạp của lòng người và công lý nơi chốn giang hồ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2011, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Kỳ Long","avatar":""},{"name":"Vương Khả","avatar":""},{"name":"Vương Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324469);
