INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giang-ho-ky-an', 'Giang Hồ Kỳ Án', 'Jianghu Mystery', 'giang hồ kỳ án jianghu mystery ngô kỳ long vương khả vương lôi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nichijou-cuoc-song-thuong-ngay-cua-toi', 'Nichijou: Cuộc Sống Thường Ngày Của Tôi', 'Nichijou: My Ordinary Life', 'https://phimimg.com/upload/vod/20251109-1/a4b3c2086475a3222a5769735b250838.jpg', 'https://phimimg.com/upload/vod/20251109-1/18b3a2c05c170e6a4be55c4d3adb06da.jpg', '<p>Theo chân ba cô gái bình thường trong hành trình biến những khoảnh khắc vụng về của cuộc sống trở nên… tồi tệ gấp nghìn lần.Cùng với những người bạn cùng lớp đầy màu sắc, họ học được những bài học quan trọng nhất theo cách khó khăn nhất.Trong khi đó, ở con phố bên cạnh, một giáo sư tí hon lại khiến cuộc sống trở nên rối ren cho một robot chỉ muốn trở nên bình thường.Nhưng “bình thường” chính là điều không bao giờ có thể xảy ra ở thị trấn nơi cá hồi rơi từ trên trời xuống!Thực ra, điều duy nhất bạn có thể tin tưởng là bạn bè,— dù ngay cả họ cũng… vô cùng kỳ lạ.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mariko Honda","avatar":""},{"name":"Mai Aizawa","avatar":""},{"name":"Misuzu Togashi","avatar":""},{"name":"Shizuka Furuya","avatar":""},{"name":"Hiromi Konno","avatar":""},{"name":"Minoru Shiraishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324469);
