INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anohana-doa-hoa-ngay-ay-ta-cung-ngam', 'AnoHana: Đóa Hoa Ngày Ấy Ta Cùng Ngắm', 'AnoHana: The Flower We Saw That Day', 'https://phimimg.com/upload/vod/20251105-1/f5c113169148b21ea8da759c39df66c2.jpg', 'https://phimimg.com/upload/vod/20251105-1/41111911941f2d4eeedbf57b256d7b15.jpg', '<p>Phim là một câu chuyện cảm động về tình bạn. Xoay quanh những con người từng là bạn thân thời thơ ấu, nhưng một biến cố xảy ra đã khiến họ phải xa rời nhau, để rồi dần thay đổi theo năm tháng. Và mùa hè ấy lại đến, với sự xuất hiện của một người bạn năm xưa cùng điều ước cao thượng của mình đã kết nối những con người ấy lại với nhau. Liệu tình bạn năm nào có được khôi phục? Họ có thể trở lại như trước kia hay không? Mời các bạn xem phim sẽ rõ!</p>', 'Full', 11, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miyu Irino","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Takayuki Kondo","avatar":""},{"name":"Mitsuru Ogata","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Aún no sabemos el nombre de la flor que vimos aquel día","我们仍未知道那天所见到的花的名字","那朵花","未闻花名","ANOHANA: Bunga yang Kita Lihat Waktu Itu","אנו עדיין לא יודעים את שם הפרח שראינו ביום ההוא","Ano Hi Mita Hana no Namae o Bokutachi wa Mada Shiranai.","AnoHana","Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.","Ano hi mita hana no namae wo bokutachi menma e no tegami","あの日見た花の名前を僕達はまだ知らない。めんまへの手紙","Ano Hana","아노하나","Todavía no conocemos el nombre de la flor que vimos ese día.","Нам всё невдомёк, как же звался тот цветок","Мы так и не знаем названия цветка, что видели в тот день","อะโนะฮะนะ","未聞花名","AnoHana, We Still Don''t Know the Name of the Flower We Saw That Day.","Anohana: We Still Don''t Know The Flowers We Saw That Day - Letter to Menma","Anohana: The Flowers We Saw That Day - a Letter to Menma","あの日見た花の名前を僕達はまだ知らない。"]', 1784690324469);
