INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anohana-doa-hoa-ngay-ay-ta-cung-ngam', 'AnoHana: Đóa Hoa Ngày Ấy Ta Cùng Ngắm', 'AnoHana: The Flower We Saw That Day', 'anohana: đóa hoa ngày ấy ta cùng ngắm anohana: the flower we saw that day miyu irino ai kayano haruka tomatsu takahiro sakurai saori hayami takayuki kondo mitsuru ogata aún no sabemos el nombre de la flor que vimos aquel día 我们仍未知道那天所见到的花的名字 那朵花 未闻花名 anohana: bunga yang kita lihat waktu itu אנו עדיין לא יודעים את שם הפרח שראינו ביום ההוא ano hi mita hana no namae o bokutachi wa mada shiranai. anohana ano hi mita hana no namae wo bokutachi wa mada shiranai. ano hi mita hana no namae wo bokutachi menma e no tegami あの日見た花の名前を僕達はまだ知らない。めんまへの手紙 ano hana 아노하나 todavía no conocemos el nombre de la flor que vimos ese día. нам всё невдомёк, как же звался тот цветок мы так и не знаем названия цветка, что видели в тот день อะโนะฮะนะ 未聞花名 anohana, we still don''t know the name of the flower we saw that day. anohana: we still don''t know the flowers we saw that day - letter to menma anohana: the flowers we saw that day - a letter to menma あの日見た花の名前を僕達はまだ知らない。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-phau-thuat-cua-grey-phan-8', 'Ca Phẫu Thuật Của Grey (Phần 8)', 'Grey''s Anatomy (Season 8)', 'https://phimimg.com/upload/vod/20251104-1/fe47d6ece55ad6601518095ebdb621e7.jpg', 'https://phimimg.com/upload/vod/20251104-1/ffbd42d1fa6773aa72e809263d478f34.jpg', '<p>Bác sĩ thực tập (và sau này là bác sĩ nội trú) Meredith Grey bị cuốn vào những mối quan hệ cá nhân, cũng như quan hệ công việc với các đồng nghiệp ở bệnh viện Seattle.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ellen Pompeo","avatar":""},{"name":"Chandra Wilson","avatar":""},{"name":"James Pickens Jr.","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Caterina Scorsone","avatar":""},{"name":"Camilla Luddington","avatar":""},{"name":"Kim Raver","avatar":""},{"name":"Jason George","avatar":""},{"name":"Chris Carmack","avatar":""},{"name":"Anthony Hill","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Alexis Floyd","avatar":""},{"name":"Niko Terho","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Trevor Jackson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Anatomia e Greit","A Anatomia de Grey","L''anatomie de Grey","实习医生","Grey''s Anatomy Die jungen Ärzte","Grey''s Anatomy Die jungen Aerzte","Grey''s Anatomy - Die jungen Ärzte","A coeur ouvert","그레이 아나토미","Анатомія пристрасті","Greys Anatomy","Grey''s Anatomy"]', 1784690324469);
