INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('clash-of-empires-the-battle-for-asia', 'Clash of Empires: The Battle for Asia', 'Hikayat Merong Mahawangsa', 'https://phimimg.com/upload/vod/20251015-1/3437d54cd31b9dc9fd711e076d9cbd8a.jpg', 'https://phimimg.com/upload/vod/20251015-1/f1e61e26f99d82e7ef2570ea00601978.jpg', '<p>Dựa trên tài liệu lịch sử thế kỷ 16 mang tên &quot;Biên niên sử Mã Lai&quot;, &quot;Biên niên sử Merong Mahawangsa&quot; là một bộ phim sử thi hành động đầy kịch tính, với các nhân vật thần thoại, những khoảnh khắc kỳ diệu và những cảnh quay hiệu ứng hình ảnh mãn nhãn. Merong Mahawangsa là hậu duệ của Alexander Đại đế, một thuyền trưởng hải quân và nhà thám hiểm nổi tiếng đã đến châu Á vài trăm năm trước.</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Stephen Rahman Hughes","avatar":""},{"name":"Gavin Stenhouse","avatar":""},{"name":"Khir Rahman","avatar":""},{"name":"Ummi Nazeera","avatar":""},{"name":"Jing Lusi","avatar":""},{"name":"Craig Fong","avatar":""},{"name":"Henrik Norman","avatar":""},{"name":"Umie Aida","avatar":""},{"name":"Jehan Miskin","avatar":""},{"name":"Rahim Razali","avatar":""},{"name":"Wan Hanafi Su","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Clash of Empires","Clash of Empires - Die Schlacht um Asien","Clash of Empires: The Battle for Asia","The Malay Chronicles: Bloodlines","Hikayat Merong Mahawangsa","帝国时代：亚洲王朝"]', 1784690324469);
