INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-thien-ha', 'Mỹ nhân thiên hạ', 'Beauty World', 'https://phimimg.com/upload/vod/20251012-1/16ce42f5285d704dee50d178782991df.jpg', 'https://phimimg.com/upload/vod/20251012-1/47f9e3ac4d148ac5b2fecdb4c0b2f074.jpg', '<p>Dưới thời trị vì của Hoàng đế Cao Tông nhà Đường, Lạc Dương là thủ đô của các vị thần. Vợ lẽ Tiêu Thục, người được Hoàng đế Cao Tông sủng ái, đã cố tình gài bẫy hại Vương hoàng hậu, khiến bà phải làm trò hề trước mặt Hoàng đế Cao Tông và đánh mất phẩm giá của hoàng hậu, để trả thù và giành được sự ưu ái từ nhà họ Tiêu, Vương hoàng hậu đã nghe theo lời đề nghị của Công chúa Cao Dương và cử người tình cũ của Cao Tông đến.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 16, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Ting","avatar":""},{"name":"Li Xiaolu","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Zheng Guolin","avatar":""},{"name":"He Shengming","avatar":""},{"name":"Lv Jiarong","avatar":""},{"name":"Zhoumuyin","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Tong Liya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["美人天下","Đường Cung Mỹ Nhân Thiên Hạ","唐宫美人天下"]', 1784690324469);
