INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dao-nu-bo-khoai', 'Đới Đao Nữ Bộ Khoái', 'Female Constables', 'https://phimimg.com/upload/vod/20251012-1/0393a77606b9848180f9944871b4a7ad.jpg', 'https://phimimg.com/upload/vod/20251012-1/8b6ab1a98e3cab47dd426e15cb1e3060.jpg', '<p>Liễu Minh Nguyệt là một cô gái thông minh, hiền lành mắc chứng bệnh sợ đao kiếm. Vì thế mà trong cuộc sống thường ngày, cô làm bất cứ việc gì cũng không dám đụng tới dao. Ấy vậy mà khi vào cung, cô lại bén duyên với đao kiếm, rồi trở thành đới đao nữ bổ khoái bên cạnh hoàng thượng. Trong quá trình này, Minh Nguyệt tình cờ gặp trạng sư Âu Dương Đông. Hai con người tài giỏi với hai tính cách trái ngược bắt đầu cùng nhau hợp tác điều tra các vụ án hóc búa và tạo nên vô số những câu chuyện hài hước.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 11, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Xa Thi Mạn","avatar":""},{"name":"Khương Hồng","avatar":""},{"name":"Vương Giá Lâm","avatar":""},{"name":"Đoạn Thiện Như","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Knife Female Detective","带刀女捕快"]', 1784690324469);
