INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-trao-nang-dau', 'Đánh tráo nàng dâu', 'Mere Brother Ki Dulhan', 'https://phimimg.com/upload/vod/20251010-1/0374e60f33ed9a87213f72919b552bbf.jpg', 'https://phimimg.com/upload/vod/20251010-1/769616639e594e8020c6b9c2ffa952a1.jpg', '<p>Một chàng trai trẻ cố gắng sắp xếp một cuộc hôn nhân cho anh trai mình, nhưng lại phát hiện ra mình phải lòng vị hôn thê được chọn.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ali Zafar","avatar":""},{"name":"Imran Khan","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Tara D''Souza","avatar":""},{"name":"Kyra Dutt","avatar":""},{"name":"Parikshat Sahni","avatar":""},{"name":"Mohammed Zeeshan Ayyub","avatar":""},{"name":"Kanwaljit Singh","avatar":""},{"name":"Sufi Malhotra","avatar":""},{"name":"Suparna Marwah","avatar":""},{"name":"Karamveer Choudhary","avatar":""},{"name":"Marhu Sheikh","avatar":""},{"name":"Arfeen Khan","avatar":""},{"name":"Tariq Vasudeva","avatar":""},{"name":"Brijendra Kala","avatar":""},{"name":"John Abraham","avatar":""},{"name":"Iain","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我兄弟的新娘","MBKD","My Brother''s Bride","คนอลวนรักอลเวง","मेरे ब्रदर की दुल्हन"]', 1784690324469);
