INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-trao-nang-dau', 'Đánh tráo nàng dâu', 'Mere Brother Ki Dulhan', 'đánh tráo nàng dâu mere brother ki dulhan ali zafar imran khan katrina kaif tara d''souza kyra dutt parikshat sahni mohammed zeeshan ayyub kanwaljit singh sufi malhotra suparna marwah karamveer choudhary marhu sheikh arfeen khan tariq vasudeva brijendra kala john abraham iain 我兄弟的新娘 mbkd my brother''s bride คนอลวนรักอลเวง मेरे ब्रदर की दुल्हन', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-tu-than', 'Cuộc Hẹn Tử Thần', 'Men with No Shadows', 'https://phimimg.com/upload/vod/20251008-1/ecf92d48981ce942c9f80eb7799fbc4e.jpg', 'https://phimimg.com/upload/vod/20251008-1/2f9d13d3551cf6c6b4bd7989ab30eedc.jpg', '<p>Cử nhân y khoa Giang Đông Kiện chuyên tâm nghiên cứu dược lý, thuốc do anh nghiên cứu ra vô tình khiến cho bệnh nhân tử vong, vấp phải cú sốc lớn, Đông Kiện quyết định rời khỏi công ty dược phẩm, chuyển sang làm bác sĩ phòng mạch. Một lần nọ, Đông Kiện gặp tai nạn giao thông trí mạng, anh và Thai Phong cùng bị thương nghiêm trọng, Thai Phong tự xưng là ác ma và buộc anh phải giao ra tên một người đáng chết. Đông Kiện thà chết cũng không chịu khuất phục, khiến Thai Phong sinh lòng hiếu kỳ với nhân tính, hắn thâm nhập vào cuộc sống của Đông Kiện, theo đuổi nữ bệnh nhân Phương Tiểu Phương mà Đông Kiện yêu thầm từ lâu. Từ khi đồng hành cùng ác ma, Đông Kiện có cả danh và lợi, nhưng dần dần mất đi bản tính lương thiện...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2011, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bobby Au-Yeung Tsan-Wah","avatar":""},{"name":"Raymond Lam Fung","avatar":""},{"name":"Tavia Yeung Yi","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Gigi Wong","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"Felton Law Gwan-Joh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["不速之約"]', 1784690324469);
