INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-hen-tu-than', 'Cuộc Hẹn Tử Thần', 'Men with No Shadows', 'cuộc hẹn tử thần men with no shadows bobby au-yeung tsan-wah raymond lam fung tavia yeung yi david chiang da-wei gigi wong catherine chau felton law gwan-joh 不速之約', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-ben-song', 'Thám Tử Bên Sông', 'The River Murders', 'https://phimimg.com/upload/vod/20250930-1/61f30b70e6e347708fdbd40075010036.jpg', 'https://phimimg.com/upload/vod/20250930-1/fdf90980b3ca87e5725d792aa535b771.jpg', '<p>Những tội lỗi trong quá khứ không hề bị lãng quên trong bộ phim kinh dị hồi hộp rùng rợn này. Khi thi thể đầu tiên được phát hiện, mọi thứ dường như chỉ là sự trùng hợp ngẫu nhiên. Nhưng giờ đây, thám tử điều tra án mạng Jack Verdon có lý do để lo lắng: nạn nhân của một loạt vụ giết người tình dục tàn bạo đều là bạn gái cũ của anh. Bị nghi ngờ bởi một đặc vụ FBI, người đã tiếp quản vụ án và bị đội trưởng đình chỉ công tác, Jack phải làm việc ngoài vòng pháp luật nếu muốn tìm ra kẻ giết người, cứu vãn tương lai và bảo vệ những gì còn sót lại của quá khứ.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ray Liotta","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Gisele Fraga","avatar":""},{"name":"Sarah Ann Schultz","avatar":""},{"name":"Michael Rodrick","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Chris LeBlanc","avatar":""},{"name":"Michelle Krusiec","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"C.R. Clatworthy","avatar":""},{"name":"Cindy Dolenc","avatar":""},{"name":"Aaron Farb","avatar":""},{"name":"Sali Sayler","avatar":""},{"name":"Vanessa Toll","avatar":""},{"name":"Patrick Treadway","avatar":""},{"name":"Alex Do","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Río de asesinatos","The River Murders"]', 1784690324469);
