INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-chuck-phan-5', 'Điệp Viên Chuck (Phần 5)', 'Chuck (Season 5)', 'https://phimimg.com/upload/vod/20250907-1/de54d34110e0ee3f93ded691baf5c69f.jpg', 'https://phimimg.com/upload/vod/20250907-1/1e2094fc6532c5cf6c6a46bacfa733d2.jpg', '<p>Chuck là bộ phim nói về một anh chàng tẻ nhạt bình thường không có gì nổi bật tên Chuck nhưng sau đó anh vô tình trở thành một điệp viên khi nhận được một mail kì lạ từ người bạn học cũ của anh tên Bryce. Bryce hiện đang làm việc cho CIA nên mail mà anh gửi cho Chuck có chứa nhiều bí mật trong đó nên vô tình khiến Chuck dính vào những vụ việc vô cùng rắc rối. Vì biết được 1 số bí mật nên CIA buộc phải bảo vệ anh đồng thời cho anh tham gia vào 1 số phi vụ vô cùng nguy hiểm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 15, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Levi","avatar":""},{"name":"Yvonne Strahovski","avatar":""},{"name":"Joshua Gomez","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"Scott Krinsky","avatar":""},{"name":"Sarah Lancaster","avatar":""},{"name":"Mark Christopher Lawrence","avatar":""},{"name":"Ryan McPartlin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Чък","Praktoras... Sto Tsak","Πράκτορας... Στο Τσακ","チャック","CHUCK / チャック","Чак","宅男特務","Chuck"]', 1784690324469);
