INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-chien-tranh', 'Nữ Thần Chiến Tranh', 'Athena: Goddess Of War', 'https://phimimg.com/upload/vod/20250823-1/e061e00145c562e3c85324cb5d286d13.jpg', 'https://phimimg.com/upload/vod/20250823-1/a3d75174734424ba8f52759e2dc56643.jpg', '<p>Một tổ chức khủng bố được biết đến với cái tên &quot;Athena&quot;, do một trí tuệ bậc thầy tàn ác Son Hyuk lãnh đaọ, đang đe dọa Hàn Quốc và thế giới. Đã đến lúc điệp viên đặc biệt Lee Jung Woo của Cơ quan An ninh Quốc gia ngăn chặn âm mưu khủng khiếp của họ. Jo Soo Young, con gái của tổng thống Hàn Quốc, bị bắt cóc và đem giấu ở Ý. Jung Woo và đội của anh được giao nhiệm vụ tìm cô ấy và mang cô trở về.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Cha Seung-won","avatar":""},{"name":"Soo Ae","avatar":""},{"name":"Kim Min-jong","avatar":""},{"name":"Ricky Kim","avatar":""},{"name":"Lee Ji-ah","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Kim Seung-woo","avatar":""},{"name":"Kim So-yeon","avatar":""},{"name":"Lee El","avatar":""},{"name":"Lee Ji-hyun","avatar":""},{"name":"Sean Dulake","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Athena: The Movie","아테나 : 전쟁의 여신","Die Athena-Verschwörung","Athena, a titkos ügynökség","Athena：Goddess Of War","아테나: 전쟁의 여신"]', 1784690324469);
