INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-5-the-he-thu-nhat', 'X-Men 5: Thế Hệ Thứ Nhất', 'X-Men: First Class', 'https://phimimg.com/upload/vod/20250817-1/8f84a298f28649d20812b16605860320.jpg', 'https://phimimg.com/upload/vod/20250817-1/8af518496b858826c7ed65edcbd37351.jpg', '<p>Bộ phim kể về nhóm dị nhân thế hệ đầu và nguyên nhân sự chia rẽ người đột biến thành hai nhóm đối địch. Một nhóm bảo vệ loài người, nhóm còn lại tẩy chay và coi dị nhân mới là giống nòi ưu việt. &nbsp;Charles Xavier và Erik Lehnsherr là hai người đột biến. Trong khi Charles luôn muốn tìm kiếm và phát huy năng lực của dị nhân để bảo vệ loài người, thì Erik nuôi mối thù với những kẻ đã hãm hại mẹ anh và biến anh thành một vật thí nghiệm. Khi nhóm Lửa địa ngục xuất hiện và sử dụng siêu năng hòng thôn tính Trái đất, cả hai hợp lực với nhóm dị nhân trẻ chặn đứng âm mưu này.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"January Jones","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Álex González","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Glenn Morshowe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":