INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-vang-hung-dong-phan-1', 'Chạng Vạng: Hừng Đông (Phần 1)', 'The Twilight Saga: Breaking Dawn (Part 1)', 'https://phimimg.com/upload/vod/20250812-1/94f5ff364addbbedf23331e3b4d277cc.jpg', 'https://phimimg.com/upload/vod/20250812-1/a872d137b9041e314f7b133082c0d7c3.jpg', '<p>Hừng Đông Phần 1 mở đầu khi sau nhiều khó khăn cách trở cuối cùng Bella và Edward cũng đến được với nhau bằng một đám cưới hạnh phúc nhưng &quot;ngày vui ngắn chẳng tày gang&quot; khi Bella có thai, sinh mạng mang nửa dòng máu người và nửa dòng máu Ma cà rồng. Đặc biệt cái thai này còn gây nguy hiểm tới tính mạng của Bella và cả gia tộc Ma cà rồng.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Taylor Lautner","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Nikki Reed","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Sarah Clarke","avatar":""},{"name":"Christian Camargo","avatar":""},{"name":"Gil Birmingham","avatar":""},{"name":"Julia Jones","avatar":""},{"name":"Booboo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35638