INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-quyet', 'Quỷ Quyệt', 'Insidious', 'https://phimimg.com/upload/vod/20250731-1/e753d27a7578d8e7cc0d7da1c3af9846.jpg', 'https://phimimg.com/upload/vod/20250731-1/7805a656c8b6bdeee32ab9c2eccf77fb.jpg', '<p>Đây là phần phim đầu tiên (theo thứ tự thời gian, lần thứ ba) trong loạt phim Insidious. Câu chuyện xoay quanh cặp vợ chồng có con trai không hiểu sao đi vào tình trạng hôn mê và trở thành một vật chứa cho hồn ma trong một không gian tâm linh muốn cư ngụ cơ thể của mình, để sống một lần nữa. Bộ phim đã được phát hành tại rạp vào ngày 1 tháng 4 năm 2011 và FilmDistrict phát hành đầu tiên. Bộ phim được nối tiếp theo một phần sau, Quỷ quyệt 2 (2013) và hai phần sau, Quỷ quyệt 3 (2015) và Quỷ quyệt: Chìa khóa quỷ dữ (2018).</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Canada', 1, '[{"name":"Patrick Wilson","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Barbara Hershey","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Andrew Astor","avatar":""},{"name":"Corbett Tuck","avatar":""},{"name":"Heather Tocquigny","avatar":""},{"name":"Ruben Pla","avatar":""},{"name":"John Henry Binder","avatar":""},{"name":"Joseph Bishara","avatar":""},{"name":"Philip Friedman","avatar":""},{"name":"J. LaRose","avatar":""},{"name":"Kelly Devoto","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sobrenatural - Insidious","Insidieux","Insidious: La noche del demonio","Коварен","วิญญาณตามติด","Sobrenatural - A Origem","潜伏阴儿房","غدار","Ruhlar Bölgesi","อินซิเดียส","Quỷ Quyệt","Insidious Chapter 1","白日梦游记","Insidious"]', 1784690324469);
