INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quy-quyet', 'Quỷ Quyệt', 'Insidious', 'quỷ quyệt insidious patrick wilson rose byrne lin shaye ty simpkins barbara hershey leigh whannell angus sampson andrew astor corbett tuck heather tocquigny ruben pla john henry binder joseph bishara philip friedman j. larose kelly devoto sobrenatural - insidious insidieux insidious: la noche del demonio коварен วิญญาณตามติด sobrenatural - a origem 潜伏阴儿房 غدار ruhlar bölgesi อินซิเดียส quỷ quyệt insidious chapter 1 白日梦游记 insidious', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-hiep-nhat-chi-mai', 'Quái Hiệp Nhất Chi Mai', 'The Vigilantes In Masks', 'https://phimimg.com/upload/vod/20250728-1/297bdbfe28422e9f79629fd678bd1910.jpg', 'https://phimimg.com/upload/vod/20250728-1/a80d1415b4d211cf21d3ebac499d2738.jpg', '<p>Mất hết tất cả vì bị kẻ gian hãm hại, Ly Ca Tiếu từ chỉ huy Cẩm y vệ trở thành một kẻ nát rượu. Mãi đến khi gặp được bậc thầy dịch dung Hạ Tiểu Mai, đệ nhất khinh công Yến Tam Nương và cao thủ giang hồ Sài Hồ, anh mới bắt đầu tìm lại được ý chí sống và quyết tâm trả thù. Bốn người cùng thành lập nhóm hiệp khách &quot;Nhất Chi Mai&quot; chuyên đi phá án, trừ gian diệt bạo, bảo vệ dân thường trước sự đàn áp của cường quyền.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Chính Nam","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Lưu Thi Thi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["怪侠一枝梅","Strange Hero Yi Zhi Mei"]', 1784690324469);
