INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-chen-thanh-phan-1', 'Cuộc Chiến Chén Thánh (Phần 1)', 'Fate/Zero (Season 1)', 'https://phimimg.com/upload/vod/20250719-1/e34aa3f223fd0e855eb359dc41729daf.jpg', 'https://phimimg.com/upload/vod/20250719-1/a274465a6cc0e5e827fd5aa56a0e47e7.jpg', '<p>&quot;Để theo đuổi sức mạnh của Chén Thánh - thứ có thể ban phép màu, bảy pháp sư (master) triệu hồi bảy linh (Servant), chiến đấu trong trận chiến Chén thánh cho đến khi chỉ còn lại duy nhất người cuối cùng. Sự thật về &quot;Cuộc chiến Chén Thánh lần thứ tư&quot; xảy ra 10 năm trước cuối cùng cũng được hé lộ! &quot;</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rikiya Koyama","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Ayumi Tsunematsu","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Jouji Nakata","avatar":""},{"name":"Megumi Toyoguchi","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Satoshi Tsuruoka","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Takumi Yamazaki","avatar":""},{"name":"Tarusuke Shingaki","avatar":""},{"name":"Tomokazu Seki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["命运守护之夜前传","Fate 2 - Zero","命运零话","Feito/Zero","Fate Zero","フェイト/ゼロ","페이트 제로","Доля: Початок","Fate/Zero‌","Cuộc chiến Ché