INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-chen-thanh-phan-1', 'Cuộc Chiến Chén Thánh (Phần 1)', 'Fate/Zero (Season 1)', 'cuộc chiến chén thánh (phần 1) fate/zero (season 1) rikiya koyama ayako kawasumi akio otsuka akira ishida ayumi tsunematsu daisuke namikawa hikaru midorikawa jouji nakata megumi toyoguchi ryotaro okiayu satoshi tsuruoka sayaka ohara show hayami takumi yamazaki tarusuke shingaki tomokazu seki 命运守护之夜前传 fate 2 - zero 命运零话 feito/zero fate zero フェイト/ゼロ 페이트 제로 доля: початок fate/zero‌ cuộc chiến chén thánh fate/zero', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-12-con-giap', 'Truyền Thuyết 12 Con Giáp', 'The Legend Of The Twelve Chinese Zodiacs', 'https://phimimg.com/upload/vod/20250719-1/a7f23f8f3d4d380577ed406097da0cf5.jpg', 'https://phimimg.com/upload/vod/20250719-1/d0a28e814ed4b2d36b1a698b98a6c494.jpg', '<p>Bộ phim lấy cổ trang thần thoại, lấy đề tài truyền thuyết dân gian về cầm tinh 12 con giáp. Chuyện xưa nói rằng thời thượng cổ hồng hoang, Hoàng Đế cùng Xi Vưu đại chiến, bị ma quỷ ám ảnh – Xi Vưu chịu yêu ma, quỷ quái mê hoặc , bán đứng linh hồn của chính mình, cầu lấy ở trong chiến tranh đả bại hoàng đế, đem nhân gian biến thành luyện ngục. Tận thế buông xuống, Dược Vương Thần Nông, làm phép cho cầm tinh hổ ( Quách Phẩm Siêu ) , cùng cầm tinh thỏ ( Lí Mạn ) phục mệnh nhập thế tìm kiếm phân tán khắp nhân gian các loại cầm tinh, đem 12 cầm tinh nguyên thần trở về vị trí cũ, giúp hoàng đế đả bại tà ma, cứu vớt thiên hạ thương sinh…</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 12, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Trần Hạo Dân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Legend of the Zodiac","十二生肖传奇"]', 1784690324469);
