INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-doi-hoa-hong-anh', 'Ngọn Đồi Hoa Hồng Anh', 'From Up On Poppy Hill', 'https://phimimg.com/upload/vod/20250716-1/ebe434c66a2fbb14e8857f020e86ee67.jpg', 'https://phimimg.com/upload/vod/20250716-1/2f292080fbc97a9746f61bf2d72e9005.jpg', '<p>Bộ phim lấy bối cảnh Nhật Bản những năm 1960, nói về một cô gái tên Matsuzaki Umi sống cùng với gia đình trên đỉnh một ngọn đồi ở sát biển, cây Ngu Mỹ Nhân mọc rất nhiều trên ngọn đồi này và hằng ngày cô thường kéo cờ hiệu trong sân nhà vốn là đỉnh của ngọn đồi đó, cha của cô đã mất tích trong chiến tranh và những lá cờ hiệu cô kéo lên hằng ngày là dấu hiệu để nếu cha cô trở về từ biển có thể nhận ra nhà của mình. Cô đã gặp một nam sinh cùng học trong ngôi trường trung học với mình người muốn giữ và sửa chữa lại ngôi trường cũ thay vì phá bỏ và xây ngôi trường mới. Cô cũng có tình cảm với anh ta nhưng sau đó họ đã phát hiện ra 2 người có chung huyết thống..</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2011, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Masami Nagasawa","avatar":""},{"name":"Junichi Okada","avatar":""},{"name":"Keiko Takeshita","avatar":""},{"name":"Yuriko Ishida","avatar":""},{"name":"Rumi Hiiragi","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Takashi Naito","avatar":""},{"name":"Shunsuke Kazama","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Tsubasa Kobayashi","avatar":""},{"name":"Aoi Teshima","avatar":""},{"name":"Goro Miyazaki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Kokuriko-zaka kara","Desde la colina de las Amapolas","From Kokuriko Hill","来自虞美人之坡","З макових схилів","Coquelicot-zaka kara","Oppe paa Valmuebakken","紅花坂上的海","La colina de las amapolas","虞美人盛开的山坡","来自红花坂","红花坂上的海","Da Colina Kokuriko","コクリコ坂から"]', 1784690324469);
