INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngon-doi-hoa-hong-anh', 'Ngọn Đồi Hoa Hồng Anh', 'From Up On Poppy Hill', 'ngọn đồi hoa hồng anh from up on poppy hill masami nagasawa junichi okada keiko takeshita yuriko ishida rumi hiiragi jun fubuki takashi naito shunsuke kazama nao omori teruyuki kagawa haruka shiraishi tsubasa kobayashi aoi teshima goro miyazaki kokuriko-zaka kara desde la colina de las amapolas from kokuriko hill 来自虞美人之坡 з макових схилів coquelicot-zaka kara oppe paa valmuebakken 紅花坂上的海 la colina de las amapolas 虞美人盛开的山坡 来自红花坂 红花坂上的海 da colina kokuriko コクリコ坂から', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanna-bi-an-2011', 'Hanna Bí Ẩn', 'Hanna', 'https://phimimg.com/upload/vod/20250704-1/c44a15373028d9b317bb93d5664f66a9.jpg', 'https://phimimg.com/upload/vod/20250704-1/e4efb52588959d15a473cfe857cfb9f4.jpg', '<p>Hanna là một cô bé 16 tuổi phải sống cách biệt với thế giới bên ngoài, bị đào tạo huấn luyện trở thành một sát thủ chuyên nghiệp bởi chính cha của mình – cựu điệp viên CIA . Hanna bị bắt khi đang thực hiện một phi vụ, cô phải nhanh chóng học cách hòa nhập với thế giới bên ngoài để bảo vệ bản thân và tìm ra sự thật che dấu về sự tồn tại, cũng như câu trả lời cho những câu hỏi bất ngờ về thân thế của chính mình.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Jessica Barden","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Aldo Maland","avatar":""},{"name":"Tim Beckmann","avatar":""},{"name":"John Macmillan","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Martin Wuttke","avatar":""},{"name":"Paris Arrowsmith","avatar":""},{"name":"Paul Birchard","avatar":""},{"name":"Christian Malcolm","avatar":""},{"name":"Jamie Beamish","avatar":""},{"name":"Tom Hodgkin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["少女杀手的奇幻旅程","杀神少女：汉娜","殺神少女:漢娜","Hanna"]', 1784690324469);
