INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanna-bi-an-2011', 'Hanna Bí Ẩn', 'Hanna', 'hanna bí ẩn hanna saoirse ronan eric bana cate blanchett tom hollander jessica barden olivia williams jason flemyng aldo maland tim beckmann john macmillan vicky krieps martin wuttke paris arrowsmith paul birchard christian malcolm jamie beamish tom hodgkin 少女杀手的奇幻旅程 杀神少女：汉娜 殺神少女:漢娜 hanna', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('not-nhac-tinh-yeu-2011', 'Nốt Nhạc Tình Yêu', 'Heartstrings (You''ve Fallen For Me)', 'https://phimimg.com/upload/vod/20250702-1/75ec950c3e91383bcd9f03b2c9dc0002.jpg', 'https://phimimg.com/upload/vod/20250702-1/9f2c3f3f6aa91d4b9e8d2a8b9d849ab8.jpg', '<p>Bộ phim kể về câu chuyện tình yêu, tình bạn và ước mơ của những sinh viên trẻ tại một trường đại học nghệ thuật. Bộ phim tập trung vào Lee Shin, một sinh viên lạnh lùng và tài năng chơi guitar, và Kyu Won, một sinh viên nhạc truyền thống nhiệt huyết và năng động, cùng với những người bạn của họ.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 14, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Shin-hye","avatar":""},{"name":"Jung Yong-hwa","avatar":""},{"name":"Song Chang-eui","avatar":""},{"name":"So I-hyeon","avatar":""},{"name":"Kang Min-hyuk","avatar":""},{"name":"Kim Yoon-hye","avatar":""},{"name":"Lee Hyun-jin","avatar":""},{"name":"Lim Se-mi","avatar":""},{"name":"Shin Gu","avatar":""},{"name":"Mun Ka-young","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Sunwoo Jae-duk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Te enamoraste de mí","Neon Naege Banhaesseo","You''ve Fallen for Me","Festival","You Were Taken By Me","넌 내게 반했어"]', 1784690324469);
