INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('not-nhac-tinh-yeu-2011', 'Nốt Nhạc Tình Yêu', 'Heartstrings (You''ve Fallen For Me)', 'nốt nhạc tình yêu heartstrings (you''ve fallen for me) park shin-hye jung yong-hwa song chang-eui so i-hyeon kang min-hyuk kim yoon-hye lee hyun-jin lim se-mi shin gu mun ka-young lee il-hwa sunwoo jae-duk te enamoraste de mí neon naege banhaesseo you''ve fallen for me festival you were taken by me 넌 내게 반했어', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-nam-ay-chung-ta-cung-theo-duoi', 'Cô Gái Năm Ấy Chúng Ta Cùng Theo Đuổi', 'You Are The Apple Of My Eye', 'https://phimimg.com/upload/vod/20250626-1/1c81a0d4ca62879b1fc863252b2f52bd.jpg', 'https://phimimg.com/upload/vod/20250626-1/a7b44a2cfb016023d7901be96c5f6a2f.jpg', '<p>Kha Cảnh Đằng khi học cấp hai là một nam sinh học lực kém lại nghịch ngợm, hay gây rối. Giáo viên đã “giao phó” cậu cho nữ sinh giỏi nhất lớp – Thẩm Giai Di. Mỗi khi Kha Cảnh Đằng không nghiêm túc học hành, Thẩm Giai Di sẽ dùng bút bi chọc vào áo cậu để nhắc nhở. Dưới sự giám sát và khích lệ của cô, thành tích học tập của Kha Cảnh Đằng dần tiến bộ rõ rệt, và cậu cũng bắt đầu thích cô gái thanh lịch ấy. Thế nhưng, Kha Cảnh Đằng lại không dám thổ lộ tình cảm, bởi Thẩm Giai Di – người được hầu hết nam sinh yêu mến – lại luôn có ác cảm với những ai theo đuổi mình. Cô chỉ muốn tập trung học hành, không mong ai xen vào cuộc sống của mình. Nhưng, vì sao Thẩm Giai Di lại sẵn sàng chia sẻ tâm sự với riêng Kha Cảnh Đằng? Liệu cô có cảm giác đặc biệt nào với cậu hay không? Và liệu mối tình đơn phương kéo dài suốt tám năm của Kha Cảnh Đằng có thể có được cái kết viên mãn?</p>', 'Full', 1, 'single', 'completed', 36, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Kha Chấn Đông","avatar":""},{"name":"Trần Diệc Phi","avatar":""},{"name":"Hồ Hán Đình","avatar":""},{"name":"Tào Thụy Long","avatar":""},{"name":"Ngô Tư Lân","avatar":""},{"name":"Giản Cơ Nghi","avatar":""},{"name":"Trần Thư Dung","avatar":""},{"name":"Hác Thiệu Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Na xie nian, wo men yi qi zhui de nu hai","Ты — самое дорогое, что у меня есть","그 시절, 우리가 좋아했던 소녀","You Are the Apple of My Eye","あの頃、君を追いかけた","那些年，我們一起追的女孩"]', 1784690324469);
