INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-nam-ay-chung-ta-cung-theo-duoi', 'Cô Gái Năm Ấy Chúng Ta Cùng Theo Đuổi', 'You Are The Apple Of My Eye', 'cô gái năm ấy chúng ta cùng theo đuổi you are the apple of my eye kha chấn đông trần diệc phi hồ hán đình tào thụy long ngô tư lân giản cơ nghi trần thư dung hác thiệu văn na xie nian, wo men yi qi zhui de nu hai ты — самое дорогое, что у меня есть 그 시절, 우리가 좋아했던 소녀 you are the apple of my eye あの頃、君を追いかけた 那些年，我們一起追的女孩', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ung', 'Báo Ứng', 'Punished', 'https://phimimg.com/upload/vod/20250624-1/76d80037a63ff6777003318407c35b7a.jpg', 'https://phimimg.com/upload/vod/20250624-1/8381268c446c1127c8f4159e93e58ca4.jpg', '<p>Phim xoay quanh một doanh nhân giàu có, đang rơi vào tuyệt vọng sau khi con gái mình bị bắt cóc rồi ngay sau đó nhận tin: cô đã bị sát hại. Trong cơn phẫn nộ tột cùng, ông thuê tài xế riêng kiêm cựu xã hội đen để truy tìm và trừng phạt những kẻ gây ra bi kịch. Phim khai thác sâu sắc nỗi đau mất mát, sự giằng xé giữa công lý - thù hận, cũng như cái giá phải trả cho hành động bất chấp tất cả để trả thù.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Văn Vịnh San","avatar":""},{"name":"Trương Khả Di","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Bao ying","Retribution","迷途追凶","Bou ying","报应","Punished","報應(2011)","報應"]', 1784690324469);
