INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giao-lam-chieu', 'Cô Giáo Lắm Chiêu', 'Bad Teacher', 'https://phimimg.com/upload/vod/20250620-1/6df92bc3bfe5a314530e4ce34642dccf.jpg', 'https://phimimg.com/upload/vod/20250620-1/f5a52f6050c9cae1b52d50608c1f2167.jpg', '<p>Hụt hẫng khi chia tay người yêu lắm tiền nhiều của, Elizabeth đành quay về với công việc giáo viên trung học. Tuy nhiên, cô nàng vẫn không từ bỏ ước mơ chài một &quot;đại gia &quot; nào khác để làm nơi nương tựa. Đối tượng&quot; hoàn hảo đã xuất hiện – Scott trẻ tuổi, cực kỳ đẹp trai và hết sức giàu có. Elizabeth quyết định tung tất cả vũ khí lợi hại nhất của mình ra để chiếm cho bằng được trái tim của Scott. Tuy nhiên, nữ đồng nghiệp tài năng Amy lại tỏ ra là đối thủ đáng gờm của Elizabeth, trong khi thầy giáo thể dục si tình Russel vẫn kiên trì theo đuổi cô. Một trận chiến nảy lửa ngấm ngầm diễn ra tại mái trường trung học.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Phyllis Smith","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Kaitlyn Dever","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Dave Allen","avatar":""},{"name":"Matthew J. Evans","avatar":""},{"name":"Jillian Armenante","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Igal Ben Yair","avatar":""},{"name":"Aja Bair","avatar":""},{"name":"Andra N","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zkazená úca","Bad Teacher: Una cattiva maestra","Profă rea, poamă bună","Bad Teacher"]', 1784690324469);
