INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-boi-nguoi-ngoai-hanh-tinh', 'Cao Bồi & Người Ngoài Hành Tinh', 'Cowboys & Aliens', 'https://phimimg.com/upload/vod/20250614-1/805b5a5765c14ddb57c43af1295bcf99.jpg', 'https://phimimg.com/upload/vod/20250614-1/2dd7e1cf22613276722be02c85d03e30.jpg', '<p>Năm 1873 ở lãnh thổ New Mexico, Jake Lonergan tỉnh lại trong hoang mạc với một cái vòng tay kỳ lạ trên tay và không còn nhớ gì. Anh đến thị trấn Absolution, được mục sư Meacham chữa trị vết thương. Cảnh sát trưởng John Taggart nhận ra Jake là tội phạm đang bị truy nã và cố gắng bắt anh. Jake sắp bỏ chạy thì bị người phụ nữ tên Ella Swenson đánh gục. Taggart chuẩn bị chuyển Jake và Percy Dolarhyde đến Santa Fe cho tòa án xét xử.</p>', 'Full', 1, 'single', 'completed', 20, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Daniel Craig","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Adam Beach","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Noah Ringer","avatar":""},{"name":"Keith Carradine","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Ana de la Reguera","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"David O''Hara","avatar":""},{"name":"Buck Taylor","avatar":""},{"name":"Matthew Taylor","avatar":""},{"name":"Cooper Tayl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Cowboys and Aliens","Cowboys & Aliens  - EC","Cowboys vs aliens","Cowboys et envahisseurs","Vaqueros contra aliens","Cao Bồi & Người Ngoài Hành Tinh","Cowboys und Aliens","Cowboys & Aliens"]', 1784690324469);
