INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thieu-lam-tu', 'Tân Thiếu Lâm Tự', 'Shaolin', 'https://phimimg.com/upload/vod/20250610-1/ffe4ca5fdf3851e919513479159e388c.jpg', 'https://phimimg.com/upload/vod/20250610-1/980350267be42899561db66b09c46099.jpg', '<p>Vào những năm 1920, nhà Thanh sụp đổ, xã hội hỗn loạn, nội chiến đẫm máu. Hầu Kiệt, một vị tướng tài bị chính thuộc hạ phản bội, đành ôm con gái vào chùa Thiếu Lâm xin tá túc.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Tạ Đình Phong","avatar":""},{"name":"Phạm Băng Băng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["新少林寺","shaolin","Шаолинь","新少林寺／Shaolin","Shaolin. La leyenda de los monjes guerreros","Xin shao lin si","Shaolin","新少林寺／Shaolin：2011"]', 1784690324469);
