INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ma-thuat-su', 'Đại Ma Thuật Sư', 'The Great Magician', 'https://phimimg.com/upload/vod/20250610-1/c224aeb5798e456bb26dec5e7f331bb5.jpg', 'https://phimimg.com/upload/vod/20250610-1/47062306ee047f5fcd7acc5dd36e616e.jpg', '<p>Thu hút khán giả bởi sự tham gia của đại hoa đán Châu Tấn và Thiên vương Lương Triều Vỹ. Bộ phim dõi theo cuộc đời đầy thăng trầm và nhiều ân oán của ảo thuật gia lừng lẫy Trương Hiền.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lương Triều Vĩ","avatar":""},{"name":"Châu Tấn","avatar":""},{"name":"Lưu Thanh Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大魔術師"]', 1784690324469);
