INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-bao-boi-tu-than-phan-2', 'Harry Potter và Bảo Bối Tử Thần: Phần 2', 'Harry Potter and the Deathly Hallows: Part 2', 'https://phimimg.com/upload/vod/20250602-1/4d1f429b653c19ff8f8e4fb17babb7b5.jpg', 'https://phimimg.com/upload/vod/20250602-1/5ce2cb828266d80e466f0fcfafd123c8.jpg', '<p>Kết thúc phần 1 là khi nhóm bạn Harry Potter, Ron và Hermione quay trở lại trường Hogwarts để tìm và tiêu diệt Trường Sinh Linh Giá cuối cùng của Voldemort. Nhưng Voldemort đã phát hiện ra nhiệm vụ của họ, và trận chiến pháp thuật lớn nhất trong lịch sử đã diễn ra ở đây, nơi mà biết bao người ngã xuống, nơi mà tất cả các pháp sư dũng cảm sẵn sàng đánh đổi cuộc sống của mình để tiêu diệt tận cùng thế lực hắc ám. Giáo sư Dumbledore mặc dù đã mất từ tập 6, nhưng ở phần cuối ông vẫn đóng vai trò quan trọng trong việc dẫn đường chỉ lối cho Harry chiến đấu với phù thủy hắc ám mạnh nhất mọi thời đại...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Warwick Davis","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Matthew Lewis","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Evanna Lynch","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Jason Isaacs","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Harry Potter en de relieken des doods - Deel 2","해리 포터와 죽음의 성물 - 파트2","Harry Potter a Dary smrti - 2. časť","Гарри Поттер и Дары Смерти: Часть II","Harry Potter och dödsrelikerna – Del 2","Harry Potter e as Relíquias da Morte - Parte 2","Harry Potter et les Reliques de la Mort : 2ème partie","해리 포터와 죽음의 성물 - 2부","해리 포터와 죽음의 성물 2","해리포터와 죽음의 성물 2","해리포터와 죽음의성물 2","ჰარი პოტერი და სიკვდილის საჩუქრები: ნაწილი მეორე","ハリー・ポッターと死の秘宝 Part2","ハリーポッターと死の秘宝 Part2","Harry Potter and the Deathly Hallows։ Part 2 3D","הארי פוטר ואוצרות המוות: חלק ב''","Harry Potter ja surma vägised: Osa 2","哈利·波特与死亡圣器（下）","هاري بوتر ومقدسات الموت الجزء الثاني","Harry Potter VIII: Harry Potter and the Deathly Hallows: Part II","Harry Potter i Insygnia Śmierci: Część II","Harry Potter i Insygnia Śmierci, cz.2","Harry Potter i Insygnia śmierci, część 2","Harry Potter i Insygnia Śmierci: Część 2","Հարրի Փոթերը և Մահվան պարգևները։ Մաս 2","해리 포터 8","Harry Potter 8","Harry Potter 8 - The Deathly Hallows - Part 2","Harry Potter 8 - Deathly Hallows - Part 2","Harry Potter and the Deathly Hallows: Part 2"]', 1784690324469);
