INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sat-thu-2011', 'Trò Chơi Sát Thủ', 'Assassination Games', 'https://phimimg.com/upload/vod/20250530-1/b0b95104e5043643601d8cd00d0a9ae4.jpg', 'https://phimimg.com/upload/vod/20250530-1/0a5c59cb7c0cb85e131b2410b2073c6a.jpg', '<p>Trò Chơi Sát Thủ xoay quanh Brazil (Jean-Claude Van Damme) là một sát thủ thực hiện theo hợp đồng, sẵn sàng chấp nhận bất cứ công việc nào nếu nhận được một mức giá phù hợp. Flint (Scott Adkins) rời bỏ trò chơi sát thủ khi một vụ tấn công tàn bạo của một kẻ bán thuốc phiện độc ác làm người vợ của anh rơi vào tình trạng hôn mê. Khi một hợp đồng được đưa ra để thủ tiêu một tên bán thuốc phiện máu lạnh này, cả Brazil và Flint đều muốn hắn chết - một người làm là vì tiền, còn người kia vì muốn trả thù. Khi các trinh sát của Interpol và các thành viên xấu xa của thế giới tội phạm ngầm săn đuổi, hai sát thủ miễn cưỡng liên minh với nhau để nhanh chóng thực hiện mục tiêu của mình trước khi họ họ bị thủ tiêu...</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Ivan Kaye","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Marija Karan","avatar":""},{"name":"Bianca Bree","avatar":""},{"name":"Michael Higgs","avatar":""},{"name":"Valentin Teodosiu","avatar":""},{"name":"Kris Van Damme","avatar":""},{"name":"Alin Panc","avatar":""},{"name":"Șerban Celea","avatar":""},{"name":"George Remes","avatar":""},{"name":"Mărioara Sterian","avatar":""},{"name":"Andrew French","avatar":""},{"name":"Attila Árpa","avatar":""},{"name":"Niko El Santo Zavero","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Weapon","بازی مرگ آسا","Assassination Games"]', 1784690324469);
