INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-ki-dieu-cua-gumball-phan-1', 'Thế Giới Kì Diệu Của Gumball (Phần 1)', 'The Amazing World Of Gumball (Season 1)', 'thế giới kì diệu của gumball (phần 1) the amazing world of gumball (season 1) nicolas cantu christian j. simon dan russell teresa gallagher kyla rae kowalewski sandra dickinson kerry shale jessica mcdonald stefan ashton frank гъмбол великолепният чуден свят на гъмбол 口香糖的奇妙世界 дивовижний світ ґамбола the wonderfully weird world of gumball the amazing world of gumball', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-muon', 'Thu Muộn', 'Late Autumn', 'https://phimimg.com/upload/vod/20250521-1/235d17af92d23b9b980044d1878a9130.jpg', 'https://phimimg.com/upload/vod/20250521-1/612e4096b9fe40a08dd6e86bf0cbdd8c.jpg', '<p>Một người vợ ngoại tình, đang trong tù vì giết chồng, nhận được tin mẹ mình đã qua đời ở Seattle. Các quan chức cho cô một kỳ nghỉ phép 3 ngày để tham dự đám tang của mẹ, khi trên xe buýt cô gặp một người đàn ông không có đủ tiền để trả vé. Trong tù và trên con đường đi tới sự tha thứ, họ sẽ học được rằng cuộc sống không bao giờ diễn ra theo kế hoạch.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Tang Wei","avatar":""},{"name":"Jun Kim","avatar":""},{"name":"John Wu","avatar":""},{"name":"Danni Lang","avatar":""},{"name":"Katarina Choi","avatar":""},{"name":"Kim Seo-ra","avatar":""},{"name":"Park Mi-hyeon","avatar":""},{"name":"James C. Burns","avatar":""},{"name":"Nikita Breznikov","avatar":""},{"name":"Alycia Delmore","avatar":""},{"name":"J.P. Giuliotti","avatar":""},{"name":"Ben Wang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["만추","Manchu","晚秋","Поздняя осень","Manchoo","Late Autumn"]', 1784690324469);
