INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-muon', 'Thu Muộn', 'Late Autumn', 'thu muộn late autumn hyun bin tang wei jun kim john wu danni lang katarina choi kim seo-ra park mi-hyeon james c. burns nikita breznikov alycia delmore j.p. giuliotti ben wang 만추 manchu 晚秋 поздняя осень manchoo late autumn', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-binh-doan-nguoi-sat', 'Doraemon: Nobita và Binh Đoàn Người Sắt', 'Doraemon: Nobita and the New Steel Troops: Winged Angels', 'https://phimimg.com/upload/vod/20250521-1/f4332a93f6fa5265a61c395c6022267c.jpg', 'https://phimimg.com/upload/vod/20250521-1/6f44d511f18614d6aa39a1031b18aa41.jpg', '<p>Nhân vật chính, Nobita, rất buồn vì không thể có được một món đồ chơi RC lớn để khoe với Suneo. Sự trẻ con đua đồi của nobita khiến Doraemon tức giận, và với mùa hè nóng nực của Nhật Bản, anh ta quyết định đi &quot;giải nhiệt&quot; ở Bắc Cực bằng Cánh cửa thần kỳ. Nobita đi theo sau tìm doraemon nhưng vô tình phát hiện ra một quả cầu kỳ lạ giống quả bóng bowling bắt đầu nhấp nháy với ánh sáng &nbsp;chớp tắt nó triệu hồi một khối kim loại trông giống như bàn chân của một người máy khổng lồ. nobita mang nó về phòng và quả cầu đi theo gọi đến nhà cậu hàng tấn bộ phận khác.t</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Masaharu Fukuyama","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["のび太と新・鉄人兵団","Doraemon: Nobita and the New Steel Troops—Winged Angels","Eiga Doraemon Shin Nobita to tetsujin heidan: Habatake tenshitachi","新大雄與鐵人兵團","新·大雄與鐵人兵團","도라에몽: 신 노비타와 철인병단 ~날아오르는 천사들~","哆啦A夢：新·大雄與鐵人兵團","哆啦A梦：新大雄与铁人兵团","โดราเอมอน เดอะ มูฟวี่ โนบิตะผจญกองทัพมนุษย์เหล็ก ~ปีกแห่งนางฟ้า~","映画ドラえもん 新・のび太と鉄人兵団 はばたけ！天使たち","映画ドラえもん 新 のび太と鉄人兵団 はばたけ 天使たち","Doraemon In Nobita and the Steel Troops: The New Age","電影哆啦A夢：新大雄與鐵人兵團","Doraemon.Nobita.and.the.New.Steel.Troops.Angel.Wings","哆啦A梦：新大雄与铁人兵团～振翅吧天使们～","多啦A梦大电影：新‧大雄与铁人兵团","映画ドラえもん 新・のび太と鉄人兵団 ～はばたけ 天使たち～"]', 1784690324469);
