INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-5', 'Lưỡi Hái Tử Thần 5', 'Final Destination 5', 'https://phimimg.com/upload/vod/20250519-1/d0a2460a3794b17475e8010931b91679.jpg', 'https://phimimg.com/upload/vod/20250519-1/e4460ab21110eb20257bc5017cf41290.jpg', '<p>Anh chàng Sam Lawton (Nicholas D’Agosto đóng) trong một lần trên đường trở về nhà vào buổi tối phải đi qua một cây cầu treo. Vào đúng lúc đó, trên cầu xảy ra một vụ tắc đường. Sam đã có linh cảm cây cầu sẽ bị sập và mọi người đang đi trên cây cầu đều bỏ mạng. Và đúng như linh cảm, thảm họa đã xảy ra khi cây cầu bị sập. Một nhóm người đã may mắn thoát chết nhưng rồi họ vẫn phải ra đi dưới tay của thần chết. Với nội dung như vậy series “Final Destination” từ phần một đến phần năm đều có chung một phong cách. Nếu Thần Chết đã nhắm đến ai thì người đó hãy coi chừng. Đừng nên vui mừng vì thoát chết trong một vụ tai nạn nào đó, chắc chắn người đó sẽ bị chết thảm hơn.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicholas D''Agosto","avatar":""},{"name":"Emma Bell","avatar":""},{"name":"Miles Fisher","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Arlen Escarpeta","avatar":""},{"name":"Jacqueline MacInnes Wood","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Ellen Wroe","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Brent Stait","avatar":""},{"name":"Roman Podhora","avatar":""},{"name":"Jasmin Dring","avatar":""},{"name":"Barclay Hope","avatar":""},{"name":"Chasty Ballesteros","avatar":""},{"name":"Mike Dopud","avatar":""},{"name":"Tanya","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Galutinis tikslas 5","Final Destination 5 3D","Destinació final 5","Destination finale 5","Destino final 5","Put bez povratka 5","Premonição 5","โกงตายสุดขีด","Destination ultime 5","Lưỡi Hái Tử Thần 5","死神5來了","死神来了5","絕命終結站5","Final Destination 5"]', 1784690324469);
