INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-trong-mo', 'Hoàng Tử Trong Mơ', 'Your Highness', 'https://phimimg.com/upload/vod/20250517-1/62fdf242867465a02e5e8b7d936bdf5c.jpg', 'https://phimimg.com/upload/vod/20250517-1/4da577b9426e6073a2b7a9b4564d46e5.jpg', '<p>Lấy bối cảnh thời kỳ trung cổ, “Your Highness” là bộ phim hành động hài kể về hai anh em hoàng tử, một người dũng cảm, hào hoa, đẹp trai luôn giải cứu các thiếu nữ yếu ớt, tiêu diệt loài rồng và chế ngự ác quỷ, một người thì tốt bụng nhưng vô dụng lúc nào cũng muốn trốn tránh lũ rồng, ác quỷ và những rắc rối thường ngày.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny McBride","avatar":""},{"name":"James Franco","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Damian Lewis","avatar":""},{"name":"Rasmus Hardiker","avatar":""},{"name":"Simon Farnaby","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"B.J. Hogg","avatar":""},{"name":"Matyelok Gibbs","avatar":""},{"name":"Angela Pleasence","avatar":""},{"name":"Anna Barry","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Amber An","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["¿Su alteza?","Ваша Високість","Your Highness - Schwerter, Joints und scharfe Bräute","廢柴殿下","Your Highness"]', 1784690324469);
