INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-hoa-diet-quy-phan-1', 'Lam Hỏa Diệt Quỷ (Phần 1)', 'Blue Exorcist (Season 1)', 'lam hỏa diệt quỷ (phần 1) blue exorcist (season 1) hiroshi kamiya 青之驱魔师 岛根启明结社篇 青之驱魔师 雪之尽头篇 青之驱魔师 终夜篇 青之驱魔师 京都不净王篇 青之驅魔師 京都不淨王篇 青之驅魔師 島根啟明結社篇 青之驅魔師 雪之盡頭篇 青之驅魔師 終夜篇 blue exorcist ao no exorcist ao no ekusoshisuto エクソシスト ao no exorcist: kyoto fujouou-hen ao no exorcist: kyoto fujō ō-hen ao no futsumashi 青の祓魔師 京都不浄王篇 青の祓魔師 島根啓明結社篇 青の祓魔師 雪ノ果篇 青の祓魔師 終夜篇 청의 엑소시스트 시마네 일루미너티편 청의 엑소시스트 시마네 일루미너티 편 청의 엑소시스트 교토 부정왕편 청의 엑소시스트 눈의 최후편 청의 엑소시스트 종야편 blue exorcist: kyoto saga blue exꚛrcis♰ blue exꚛrcis♰: kyoto saga blue exorcist -shimane illuminati saga- blue exorcist -beyond the snow saga- blue exorcist -the blue night saga- lam hỏa diệt quỷ 青の祓魔師', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-vet-duoi-dai', 'Chú Vẹt Đuôi Dài', 'Rio', 'https://phimimg.com/upload/vod/20250415-1/0a5838dfaeabdcbd9e32411611b59204.jpg', 'https://phimimg.com/upload/vod/20250415-1/995b02d6c6c4a9d19e87d01ca348f4ef.jpg', '<p>Blu là chú chim Macaw thuần hóa và chưa bao giờ tập bay, sống một cuộc sống thoải mái với người bạn thân Linda cùng cậu chủ. Blu và Linda đều tưởng Blu là cá thể duy nhất còn sót lại của loài Macaw, nhưng rồi họ phát hiện ra còn một “cô” Macaw cái tại Rio de Janeiro, cả hai quyết định thực hiện của hành trình mạo hiểm để tìm Jewel, cô Macaw của Blu. Không may khi tới Rio, Blu và Jewel bị bắt cóc bởi một nhóm buôn lậu thú, với sự khôn ngoan của Jewel và sự giúp sức của các chú chim thành phố. Blu đã trốn thoát, cùng sự trợ giúp của những người bạn mới, chú chim Macaw sẽ tìm cách học bay, giải cứu người bạn Linda và dạy cho bọn buôn lậu một bài học.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2011, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"will.i.am","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Jake T. Austin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Carlos Ponce","avatar":""},{"name":"Karen Disher","avatar":""},{"name":"Jason Fricchione","avatar":""},{"name":"Sofia Scarpa Saldanha","avatar":""},{"name":"Kelly Keaton","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Rio the Movie","奇鹦嘉年华","Rio - O Filme","Rio 3D","Rio","Rio 1 3D","Рио 1","Rio - Der Film","Rio 1","Rio: Chú Vẹt Đuôi Dài"]', 1784690324469);
