INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-than-nam-nu', 'Đơn Thân Nam Nữ', 'Don''t Go Breaking My Heart', 'https://phimimg.com/upload/vod/20231009-1/161ec8c6bd79cc253688374eeef5778c.jpg', 'https://phimimg.com/upload/vod/20231009-1/f184b69cd9db545b8bf407b32f030301.jpg', '<p>Đến Hong Kong tìm kiếm tình yêu, chuyên viên phân tích tài chính Trình Tử Hân đau lòng phát hiện bị người yêu lừa dối. Giữa lúc cô đơn sau chia tay, hai người đàn ông xuất hiện: một CEO giàu có theo đuổi bằng sự hào nhoáng và một kiến trúc sư mang đến sự ấm áp chân thành. Trái tim Tử Hân bắt đầu rung động giữa hai thái cực, tạo nên một câu chuyện tình tay ba đầy bất ngờ và lãng mạn. Liệu cô sẽ chọn sự ổn định vật chất hay rung cảm từ trái tim? Hành trình tìm kiếm tình yêu đích thực giữa những lựa chọn khó khăn chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Cao Viên Viên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324469);
