INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-an-luong-tam-phan-1', 'Toà Án Lương Tâm (Phần 1)', 'Ghetto Justice (Season 1)', 'https://phimimg.com/upload/vod/20250324-1/fbc8f638d384352bdde63aeb3c301638.jpg', 'https://phimimg.com/upload/vod/20250324-1/1bd1b41351edad5289e8e6281141df13.jpg', '<p>LUẬT LIK-AH từng chiến đấu vì danh tiếng cá nhân và đạt được lợi ích trong lĩnh vực luật. Sau khi thành lập Trung tâm Tư vấn Pháp lý với người anh họ GEORGE MIKE JR. (Lâm Chí Sin) và người bạn tốt của mình TING KA-FU ở Sham Shui Po, LIK-AH thay đổi ý định và nhận ra rằng luật pháp không phải là đặc quyền của người giàu. Bằng cách giúp đỡ cơ sở đấu tranh chống lại sự bất công bằng những chiến thuật độc đáo, LIK-AH trở thành Anh hùng của nhân dân Sham Shui Po. Cũng làm luật sư, WONG SZ-FU (Hồ Hạnh Nhi) từng ngưỡng mộ LIK-AH vì màn trình diễn bất khả chiến bại của anh ấy trong lĩnh vực này nhưng cô ấy bắt đầu coi thường anh ấy vì anh ấy đã bị biến thành luật sư khu ổ chuột. Tuy nhiên, sau một vài phiên tòa với anh ta, cả hai bắt đầu cảm kích và yêu nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2011, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Myolie Wu Hang-Yee","avatar":""},{"name":"Jazz Lam","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Raymond Cho","avatar":""},{"name":"JJ Jia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["怒火街头","Ghetto Justice","斗智情缘","怒火街頭"]', 1784690324469);
