INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-than', 'Xả Thân', 'Sacrifice', 'https://phimimg.com/upload/vod/20250318-1/02011775eb9935b79e25ef5a8c6a0473.jpg', 'https://phimimg.com/upload/vod/20250318-1/9d6f6ae98f0d8e898fa2e8a3983f4a98.jpg', '<p>Bộ phim kể về cuộc thanh toán lẫn nhau giữa các tay buôn bán ma túy. Với các pha hành động, bắn giết hết sức dã man làm cho người xem cảm thấy mát mắt. Ngoài ra phim còn có các tình tiết hết sức khăng khít giữa các nhân vật trong phim như Mike: là tên trùm buôn bán ma túy, là anh trai của Angel 1 con tin của các tên trùm ma túy kia muốn Mike làm việc cho hắn và 1 người cảnh sát hết lòng về công việc: John Hebron.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Lara Daans","avatar":""},{"name":"Arcadia Kendal","avatar":""},{"name":"Zion Forrest Lee","avatar":""},{"name":"Jake Simons","avatar":""},{"name":"Layton Morrison","avatar":""},{"name":"Athena Karkanis","avatar":""},{"name":"Matthew Stefiuk","avatar":""},{"name":"Hannah Chantée","avatar":""},{"name":"Adrian Langley","avatar":""},{"name":"Stacey Martino","avatar":""},{"name":"Peter Michael Dillon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Krwawy odwet","Sacrifice (Uncut)","Sacrifice"]', 1784690324469);
