INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-luc-sieu-pham-2011', 'Trí Lực Siêu Phàm', 'Limitless', 'https://phimimg.com/upload/vod/20250308-1/2168aad8ffc059ea9ac31cd14489148d.jpg', 'https://phimimg.com/upload/vod/20250308-1/969ac960193d48420df0a18965c68921.jpg', '<p>Phim xoay quanh câu chuyện về Eddie Morra (do Bradley Cooper thủ vai), một nhà văn đang bế tắc trong cuộc sống bỗng dưng tìm được lối thoát qua một viên thuốc thần kỳ. Loại thuốc lạ lùng này giúp anh khai thác được 100% trí tuệ, suy nghĩ, sự sáng tạo... để biến thành một phiên bản hoàn hảo của chính bản thân mình. Tuy nhiên, Eddie không ngờ rằng sự thông minh đột biến của anh đã thu hút hàng loạt thế lực đen tối. Anh chàng nhà văn bỗng dưng trở thành kẻ bị săn đuổi và những kẻ giấu mặt nguy hiểm sẵn sàng biến cuộc đời anh trở thành một tấn bi kịch thảm khốc.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Bradley Cooper","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Abbie Cornish","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Anna Friel","avatar":""},{"name":"Johnny Whitworth","avatar":""},{"name":"Tomas Arana","avatar":""},{"name":"Robert John Burke","avatar":""},{"name":"Darren Goldstein","avatar":""},{"name":"Ned Eisenberg","avatar":""},{"name":"T.V. Carpio","avatar":""},{"name":"Richard Bekins","avatar":""},{"name":"Patricia Kalember","avatar":""},{"name":"Cindy Katz","avatar":""},{"name":"Brian Anthony Wilson","avatar":""},{"name":"Rebecca Dayan","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c892