INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-ma-ca-rong-phan-3', 'Nhật Ký Ma Cà Rồng (Phần 3)', 'The Vampire Diaries (Season 3)', 'https://phimimg.com/upload/vod/20240229-1/71d30cd819a48412f1b815b1137c66b7.jpg', 'https://phimimg.com/upload/vod/20240229-1/862228d79ae58e9edee6cc4a52fa6022.jpg', '<p>Phần 3 mở ra cánh cửa bí mật về nguồn gốc của Klaus khi động cơ của việc anh ta muốn Stefan đứng về phía mình cuối cùng đã được tiết lộ. Stefen ngày càng lấn sâu vào thế lực xấu, Damon và Elena phải đấu tranh với cảm giác tội lỗi để mang Stefan trở lại như con người ban đầu.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nina Dobrev","avatar":""},{"name":"Paul Wesley","avatar":""},{"name":"Ian Somerhalder","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324469);
