INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('2-nang-ba-dao-phan-1', '2 Nàng Bá Đạo (Phần 1)', '2 Broke Girls (Season 1)', 'https://phimimg.com/upload/vod/20250212-1/d9c2c4d744d587048890534ae055ece7.jpg', 'https://phimimg.com/upload/vod/20250212-1/1cf8c62d8156ad415e435012f9254c28.jpg', '<p>Bộ phim hài về tình bạn không ngờ giữa hai cô gái trẻ rất khác biệt, họ gặp nhau khi làm bồi bàn tại một quán ăn ở khu Williamsburg thời thượng, Brooklyn. Họ kết nối với nhau qua giấc mơ cùng nhau sở hữu một cửa hàng bánh cupcake thành công. Chỉ có một điều cản trở họ – họ không có tiền.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kat Dennings","avatar":""},{"name":"Beth Behrs","avatar":""},{"name":"Garrett Morris","avatar":""},{"name":"Jonathan Kite","avatar":""},{"name":"Matthew Moy","avatar":""},{"name":"Jennifer Coolidge","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Duas Garotas em Apuros","打工姐妹花","追梦女孩","破产姐妹","2 Socky","2 $ocky","두 파산녀","Dvi bankrutavusios merginos","2 Bankrutavusios Merginos","2 Miúdas nas Lonas","Two Broke Girls","Hai Nàng Bá Đạo","2 Broke Girls"]', 1784690324469);
