INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giau-mat-2011', 'Người Giấu Mặt', 'The Hidden Face', 'https://phimimg.com/upload/vod/20250117-1/98608078e732893959b299e484ebfa4b.jpg', 'https://phimimg.com/upload/vod/20250117-1/d8628419c9024e78eb578bb906544d36.jpg', '<p>Nhạc trưởng Adrián và bạn gái Belen từ Tây Ban Nha chuyển đến Đức, để anh có thể theo đuổi sự nghiệp của mình. Belen là một nhà thiết kế thời trang. Cô nghi ngờ Adrián có thể có mối quan hệ với một trong các nhạc sĩ trong dàn nhạc. Và sau đó cô lên kế hoạch. Cô gửi đến anh 1 thông điệp rằng cô đã bỏ đi và bí mật đi đến một căn hầm được xây dựng bởi người chủ nhà, để xem phản ứng của Adrián...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'FHD', 'Colombia', 0, '[{"name":"Quim Gutiérrez","avatar":""},{"name":"Martina García","avatar":""},{"name":"Clara Lago","avatar":""},{"name":"Alexandra Stewart","avatar":""},{"name":"María Soledad Rodríguez","avatar":""},{"name":"Marcela Mar","avatar":""},{"name":"Humberto Dorado","avatar":""},{"name":"Julio Pachón","avatar":""},{"name":"Marcela Benjumea","avatar":""},{"name":"Mozad","avatar":""},{"name":"Juan A. Baptista","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Bunker","La verità nascosta","镜中人","The Hidden Face","Прихована правда","Inside","Бункер","La cara oculta"]', 1784690324469);
