INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boboiboy-phan-1', 'BoBoiBoy (Phần 1)', 'BoBoiBoy (Season 1)', 'https://phimimg.com/upload/vod/20250106-1/080b50a9b1e72464340b6862b01165d5.jpg', 'https://phimimg.com/upload/vod/20250106-1/5f92a3b7ad14ac4e3645983a0a60711a.jpg', '<p><span style="color: rgb(32, 33, 34); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">Bộ phim bắt đầu với việc BoBoiBoy, nhân vật chính của series có chuyến thăm tới nhà của ông cậu - ông Aba - ở đảo Rintis nhân dịp nghỉ hè. Cùng lúc, Adu Du, một người ngoài hành tinh đến từ Ata Ta Tiga đến Trái Đất để tìm kiếm nguồn năng lượng. Adu Du phát hiện ở Trái Đất có ca-cao, một nguồn năng lượng quý &quot;đã bị tuyệt chủng ở Ata Ta Tiga khoảng 30 ngàn năm về trước&quot;. Adu Du muốn gom hết số ca-cao từ Trái Đất về Ata Ta Tiga để trở thành &quot;một vị hùng&quot; của hành tinh này. Để chắc chắn kế hoạch được thực hiện thành công, Adu Du đã tìm kiếm sức mạnh từ Quả cầu Năng lượng Ochobot. Dù vậy, sự không may mắn đã xảy đến khi Ochobot nhận BoBoiBoy làm chủ nhân. Ochobot trao sức mạnh cho BoBoiBoy và những người bạn mới của cậu gồm: Ying, Yaya và Gopal.</span></p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 20, 2011, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Muhammad Fathi Diaz","avatar":""},{"name":"Noriman Saffian","avatar":""},{"name":"Mohammad Muiz Rahimi","avatar":""},{"name":"Harris Alif","avatar":""},{"name":"Mohamad Shamir Supaat","avatar":""},{"name":"Nur Fathiah Diaz","avatar":""},{"name":"Nur Sarah Alisya","avatar":""},{"name":"Yap Ee Jean","avatar":""},{"name":"Dzubir Mohamed Zakaria","avatar":""},{"name":"Wong Wai Kay","avatar":""},{"name":"Nizam Razak","avatar":""},{"name":"Anas Abdul Aziz","avatar":""},{"name":"Anas Abdul Aziz","avatar":""},{"name":"Nizam Razak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["波波仔","BoBoiBoy"]', 1784690324469);
