INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('boboiboy-phan-1', 'BoBoiBoy (Phần 1)', 'BoBoiBoy (Season 1)', 'boboiboy (phần 1) boboiboy (season 1) muhammad fathi diaz noriman saffian mohammad muiz rahimi harris alif mohamad shamir supaat nur fathiah diaz nur sarah alisya yap ee jean dzubir mohamed zakaria wong wai kay nizam razak anas abdul aziz anas abdul aziz nizam razak 波波仔 boboiboy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-8', 'Bác Sĩ House (Phần 8)', 'House (Season 8)', 'https://phimimg.com/upload/vod/20250103-1/bca5472f49f7319ec297ccdb11e9892d.jpg', 'https://phimimg.com/upload/vod/20250103-1/76833ef739980788ba1adca24b8323c5.jpg', '<p>Mùa trước, House và Cuddy cuối cùng đã quyết định đưa mối quan hệ của họ lên một tầm cao mới, nhưng phải vật lộn để tìm sự cân bằng giữa cuộc sống nghề nghiệp và cá nhân, và cuối cùng, Cuddy đã đưa ra quyết định rất xúc động là chấm dứt mối quan hệ của họ. Khi mỗi người trong số họ giải quyết hậu quả của cuộc chia tay, House kết hôn với một người nhập cư cần Thẻ xanh. Trong tập thứ 150 quan trọng của loạt phim, Mười Ba đã được ra tù sau khi an tử cho anh trai cô, người đang mắc bệnh Huntingtons giai đoạn cuối, căn bệnh tương tự mà cô đang mắc phải. Khi mùa giải kết thúc, khi những nỗ lực hàn gắn mối quan hệ của anh với Cuddy của House không thành công, anh buộc phải thực hiện các biện pháp quyết liệt và có thể không thể thay đổi để có thể thay đổi mối quan hệ của họ mãi mãi.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 15, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324469);
