INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-cung-chan-hoan-truyen', 'Hậu Cung Chân Hoàn Truyện', 'Empresses In The Palace', 'https://phimimg.com/upload/vod/20241117-1/429427872cb94a010d842304022cfe7a.jpg', 'https://phimimg.com/upload/vod/20241117-1/7ca2671c6ba20c87b7e23f25d4f19497.jpg', '<p>Nội dung phim xoay quanh những cuộc tranh đấu quyền lực và tình yêu của những nữ nhân trong chốn thâm cung vào triều đại Hoàng đế Ung Chính Nhà Thanh. Các phi tần lập mưu, tranh đấu nhau để có được quyền lực cũng như sự sủng ái của Hoàng đế.

Chân Hoàn là một thiếu nữ hiền lành, không màng danh lợi, thế sự, thế nhưng luôn bị hãm hại bởi những thế lực trong hậu cung. Hoàn cảnh buộc cô phải cứu lấy bản thân mình để rồi sau này cô trở thành phi tần quyền lực bậc nhất trong chốn hậu cung, nhưng điều gì cũng có cái giá của nó, để bước lên bảo tọa Hoàng thái hậu, Chân Hoàn vì mất dần những người thân yêu bên cạnh mình nên trở thành người phụ nữ tự cường, quyền lực, ra tay phòng thủ trước những âm mưu của người khác.</p>', 'Hoàn Tất (76/76)', 76, 'series', 'completed', 15, 2011, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Trần Kiến Bân","avatar":""},{"name":"Thái Thiếu Phân","avatar":""},{"name":"Tưởng Hân","avatar":""},{"name":"Lý Đông Học","avatar":""},{"name":"Lan Hi","avatar":""},{"name":"Trương Hiểu Long","avatar":""},{"name":"Đào Hân Nhiên","avatar":""},{"name":"Nhiệt Y Trát","avatar":""},{"name":"Đường Nghệ Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["后宫·甄嬛传","宮廷の諍い女","후궁견환전","후궁견환전 : 옹정황제의 여인","The Legend of Zhen Huan","Zhen Huan Zhuan","Hou Gong Zhen Huan Zhuan","Empresses in The Palace","甄嬛传"]', 1784690324469);
