INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-kaiji-2-con-bac-cuoi-cung', 'Thần Bài Kaiji 2: Con Bạc Cuối Cùng', 'Kaiji 2: The Ultimate Gambler', 'https://phimimg.com/upload/vod/20241114-1/acfcfd91feeeef37d0e8606d42e7b20d.jpg', 'https://phimimg.com/upload/vod/20241114-1/3b803edb4fb8d9f78b7ffb4140fe5160.jpg', '<p>Phần 2 của phim được tiếp tục khi Kaiji lại rơi vào con đường túng quẫn và bị bắt xuống cống làm việc. Tại đây anh đã thỏa thuận với công ty quản lý của mình về việc cho anh lên mặt đất và kiếm được số tiền 200 triệu Yên từ 1 triệu Yên ban đầu trong vòng 14 ngày. Kaiji sẽ làm gì để có thể “làm giàu” trong thời gian quá ngắn như thế?</p>', 'Full', 1, 'single', 'completed', 26, 2011, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Namase Katsuhisa","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Yoshizumi Ito","avatar":""},{"name":"Hayato Kakizawa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Kaiji 2: Jinsei dakkai gêmu","Kaiji 2: The Ultimate Gambler","カイジ2:人生奪回ゲーム","Kaiji 2 Jinsei dakkai gemu","Kaiji 2: En Büyük Kumarbaz","赌博默示录2","赌博默示录2：人生夺回游戏","开司2：人生夺回游戏","カイジ2 人生奪回ゲーム"]', 1784690324469);
