INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ruou-ruc-tinh', 'Quán Rượu Rực Tình', 'Cabaret Desire', 'https://phimimg.com/upload/vod/20241101-1/1511a0958ed6ec252c7513d44b5e68a7.jpg', 'https://phimimg.com/upload/vod/20241101-1/c0550a4a86dc6538087a489d3a268f19.jpg', '<p>Có một nơi huyền diệu, phóng túng, nơi mọi người đến vào ban đêm để nghe những câu chuyện khiêu dâm. Một Madame giới thiệu mỗi khách hàng với một quý cô hoặc quý ông, người sẽ đưa họ đi sâu vào thế giới của những câu chuyện đầy sức gợi. Lời nói nhẹ nhàng trôi đi khi ham muốn nhẹ nhàng xâm chiếm từng centimet, từng kẽ hở. Những người kể chuyện sẽ đưa bạn vào cuộc hành trình qua bốn câu chuyện sẽ dẫn bạn khám phá những cảm giác mới và những địa điểm đầy ham muốn. Danh sách truyện: Hai Alexes, Mẹ tôi, Ở xứ sở thần tiên, Khăn trải giường ướt.</p>', 'Full', 1, 'single', 'completed', 19, 2011, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Toni Fontana","avatar":""},{"name":"Sofia Prada","avatar":""},{"name":"Saskia Condal","avatar":""},{"name":"Mario Mentrup","avatar":""},{"name":"Silvia Diamond","avatar":""},{"name":"Matisse","avatar":""},{"name":"Didac Duran","avatar":""},{"name":"Samia Duarte","avatar":""},{"name":"Tennessee Pink","avatar":""},{"name":"Simone","avatar":""},{"name":"Eva León","avatar":""},{"name":"Javi Ninguno","avatar":""},{"name":"Mistress Basia","avatar":""},{"name":"Luizo Vega","avatar":""},{"name":"Cava Cabret","avatar":""},{"name":"Lola Page","avatar":""},{"name":"Renée","avatar":""},{"name":"Lucita Flores","avatar":""},{"name":"Soledad Rubin","avatar":""},{"name":"Matias de","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱欲夜知味","Cabaret Desire","카바레 디자이어","欲望爱之夜"]', 1784690324469);
