INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-3', 'Bằng Chứng Thép (Phần 3)', 'Forensic Heroes (Season 3)', 'https://phimimg.com/upload/vod/20241029-1/e9567e908bc6beece01b395ae30e95bc.jpg', 'https://phimimg.com/upload/vod/20241029-1/1af31081c0ffa75d168d02e8fd28b907.jpg', '<p>Bằng Chứng Thép Phần 3 là bộ tiếp tiếp nối sau 2 phần đầu thành công vang dội. Mặc dù dàn diễn viên hoàn toàn mới nhưng Bằng Chứng Thép Phần 3 hứa hẹn cũng sẽ thành công không kém 2 phần đầu. Vẫn xoay quanh những vụ án kỳ bí được tổ trọng án điều tra với những nghiệp vụ chuyên nghiệp. Phim còn đan xen những tình cảm hài hước hay là những mối tình tay ba làm cho bộ phim thêm thú vị.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2011, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ngô Trác Hy","avatar":""},{"name":"Từ Tử San","avatar":""},{"name":"Lê Diệu Tường","avatar":""},{"name":"Trương Khả Di","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["法证先锋III","FH3","Forensic Heroes 3","法證先鋒III"]', 1784690324469);
