INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chuyen-an-dac-biet-1', 'Đội Chuyên Án Đặc Biệt 1', 'Justice Heroes 1', 'https://phimimg.com/upload/vod/20241007-1/b08435d793e1d9ce6ae9ee14c96a1d7e.jpg', 'https://phimimg.com/upload/vod/20241007-1/3590215448b178d3a72a3c9265a1d09f.jpg', '<p>Đội Chuyên Án Đặc Biệt 1 - Những kế hoạch âm thầm của Tố Lan muốn lấy lại những gì cô đã đánh đổi tuổi thanh xuân của cô trong suốt 20 năm qua, đã lọt vào tầm mắt nghi ngờ của chủ tịch Long. Họ đã có những mâu thuẫn nội bộ trong công việc làm ăn phi pháp, tuy Tố Lan tỏ ra rất trung thành với công việc cô được giao phó. Đội cảnh sát đặc nhiệm cũng có kế hoạch triệt phá những đường dây phi pháp của tập đoàn này, họ đã bổ nhiệm 3 nữ cảnh sát xinh đẹp hóa thân thành những cô gái dân chơi luôn có mặt ở những quán bar và có những biệt danh riêng của họ, để hòa nhập vào vài điều tra ngầm phá án. Những phi vụ phá án gây cấn và ly kỳ của ba nữ diễn viên xinh đẹp vào vai gái dân chơi.</p>', 'Hoàn Tất (80/80)', 80, 'series', 'completed', 13, 2011, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Giang Tổ Bình","avatar":""},{"name":"Lý Chính Dĩ","avatar":""},{"name":"Đinh Cường","avatar":""},{"name":"Vương Lập Uy","avatar":""},{"name":"Dư Bích Ngạn","avatar":""},{"name":"Đường Định Quân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lian Zheng Ying Xiong","Independent Heroes","廉政英雄"]', 1784690324469);
