INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-chuyen-an-dac-biet-1', 'Đội Chuyên Án Đặc Biệt 1', 'Justice Heroes 1', 'đội chuyên án đặc biệt 1 justice heroes 1 giang tổ bình lý chính dĩ đinh cường vương lập uy dư bích ngạn đường định quân lian zheng ying xiong independent heroes 廉政英雄', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-phuong-the-ngoc', 'Tân Phương Thế Ngọc', 'Unmatched Hero Fang Shiyu', 'https://phimimg.com/upload/vod/20241007-1/09184d5ec243284e13ea82b144d88d96.jpg', 'https://phimimg.com/upload/vod/20241007-1/899d5b9e2414d0c617533fe41e86d898.jpg', '<p>Tân Phương Thế Ngọc có nội dung xoay quanh chàng trai Phương Thế Ngọc. Được mẹ luyện võ từ nhỏ nên khi trưởng thành, Thế Ngọc rất hay đánh nhau và gây lộn với những thanh niên khác trong thành. Với đức tính hiếu thắng và lòng yêu con người nên anh luôn giúp đỡ những người gặp nạn và yếu thế. Sau khi tỉ thí trong một trận lôi đài, Thế Ngọc vô tình đánh chết cha con Liêu Lão Hổ và càng tăng lên nỗi căm phẫn với Lý Tiểu Hoàn, với sự truy sát gắt gao, Thế Ngọc đành phải trốn lên Thiếu Lâm Tự để lẩn tránh một thời gian.&nbsp; Tính cách anh một lần nữa lại có sự thay đổi, trong thời gian đó, Thế Ngọc còn nảy sinh tình cảm với nghĩa nữ của Liêu Lão Hổ là Liêu Vô Song. Trải qua rất nhiều phong ba cuộc đời, từ một thiếu niên manh động, dần dần Thế Ngọc đã trưởng thành và trở thành một tiểu anh hùng cái thế lừng lẫy tiếng tăm.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Dương Tử","avatar":""},{"name":"Hoàng Thánh Y","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["方世玉","盖世英雄方世玉"]', 1784690324469);
