INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-tung-phan-1', 'Tố Tụng (Phần 1)', 'Suits (Season 1)', 'https://phimimg.com/upload/vod/20240927-1/13960848a9b86e849bc65b13ad30152d.jpg', 'https://phimimg.com/upload/vod/20240927-1/7849606764fd399e320c091b58fab4fa.jpg', '<p>Suits là 1 series truyền hình ăn khách của Mỹ. Bộ phim xoay quanh Mike Ross và Harvey Specter. Hai con người ở 2 địa vị khác nhau, nhưng thông minh và nhạy bén không hề thua kém nhau. Harvey Specter: luật sự giỏi nhất tại New York. Khi được thăng cấp, anh cần phải tìm 1 cộng sự để làm việc. Anh ghét mấy tên sinh viên Harvard, học giỏi mà đầu óc chẳng có gì. Anh cần 1 cộng sự thông minh và nhạy bén. Và một ngày, anh gặp Mike Ross. Mike Ross: một anh chàng luôn ấp ủ ước mơ trở thành 1 luật sư tài giỏi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 26, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Gina Torres","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suits: Homens de Terno","金装律师","诉讼双雄","无证律师","W garniturach","وکلا","La ley de los audaces","Briliáns elmék","Suits"]', 1784690324469);
