INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-co-hinh-xam-rong-2011', 'Cô Gái Có Hình Xăm Rồng', 'The Girl with the Dragon Tattoo', 'https://phimimg.com/upload/vod/20240922-1/39353d5b93aa242ace8504d3c6136fae.jpg', 'https://phimimg.com/upload/vod/20240922-1/957a03855f2f1f0c62c28513d9c70ec4.jpg', '<p>Cô Gái Có Hình Xăm Rồng được chuyển thể từ tiểu thuyết nổi tiếng cùng tên từ bộ ba tiểu thuyết trinh thám Thiên Niên Kỷ (Millennium) của nhà văn Thụy Điển Stieg Larsson. Câu chuyện xảy ra tại tòa soạn Millennium - tờ báo viết bài với tiêu chí chống tham nhũng, bất công và chiến đấu bảo vệ cho công bằng xã hội.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'FHD', 'Thụy Điển', 1, '[{"name":"Daniel Craig","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Yorick van Wageningen","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Goran Visnjic","avatar":""},{"name":"Donald Sumpter","avatar":""},{"name":"Ulf Friberg","avatar":""},{"name":"Bengt C.W. Carlsson","avatar":""},{"name":"Tony Way","avatar":""},{"name":"Per Myrberg","avatar":""},{"name":"Josefin Aspl","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Devushka s tatu drakona","Дівчина з татуюванням дракона","Millenium 4 - Les hommes qui n''aimaient pas les femmes","Millennium: A Garota Com Tatuagem de Dragão","Verblendung - The Girl with the Dragon Tattoo","Millennium: Los hombres que no amaban a las mujeres","Ejderha Dövmeli Kız","Əjdaha Döyməli Qız","Վիշապի դաջվածքով աղջիկը","The Girl with the Dragon Tattoo"]', 1784690324469);
