INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cau-chuyen-kinh-di-hong-kong', 'Những Câu Chuyện Kinh Dị Hồng Kong', 'Hong Kong Ghost Stories', 'https://phimimg.com/upload/vod/20231108-1/347d536afd5ac0cc5619a2f67b1597d9.jpg', 'https://phimimg.com/upload/vod/20231108-1/35f2bcd137d5f3eb3e6bd6748f0e0bdf.jpg', '<p>Wong Jing&#39;s Classroom theo chân Ling, giáo viên thay thế mới tại một trường trung học ngoại ô. Cô ấy cảm thấy có điều gì đó không ổn về lớp học của mình. Các học sinh trong lớp 4E của cô ấy là một lũ ngỗ ngược, ngoại trừ Don Don, người luôn ngồi lặng lẽ trong góc. Nghi ngờ rằng các học sinh của mình là Gi Gi, Co Co và Fong tham gia mại dâm, Ling báo cáo các vấn đề của lớp mình với hiệu trưởng, nhưng được biết rằng chưa bao giờ có Lớp 4E trong trường... Trong Patrick Kong&#39;s Travel, một nhóm bạn đi nghỉ ở Đại lục, trong đó Bo bị tai nạn giao thông qua đời. Tại đám tang của Bo, những người bạn đồng hành của cô gặp Ka Ming, người tình đã bị ghẻ lạnh của Bo, người mà Bo đã có một cuộc cãi vã gay gắt qua điện thoại ngay trước cái chết bi thảm của cô. Tại bữa tối lẩu sau đám tang, Ka Ming với khuôn mặt nhợt nhạt tiết lộ cho những người sống sót bí mật về mối quan hệ của anh ta với Bo trước khi ra tay sát hại...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jennifer Tse","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Pakho Chau","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Juno Leung","avatar":""},{"name":"Carol Yeung","avatar":""},{"name":"Betrys Kong Yi","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Him Law","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Jacquline Chong","avatar":""},{"name":"Harriet Yeung","avatar":""},{"name":"Rose Chan Ka-Wun","avatar":""},{"name":"Charmaine","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324469);
