INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bo-kinh-tam', 'Bộ Bộ Kinh Tâm', 'Scarlet Heart', 'https://phimimg.com/upload/vod/20240908-1/5ee2762c417b6ebd7d27bd44b39345eb.jpg', 'https://phimimg.com/upload/vod/20240908-1/eae65bc6b6b38ede42f36d5624972a15.jpg', '<p>Trương Hiểu vốn là một cô nhân viên văn phòng bình thường ở một thành phố phồn hoa. Vì tình cờ rơi vào đường hầm thời không mà vượt thời gian trở về triều Thanh.

Ở đó, cô hóa thân thành một thiếu nữ mười sáu tuổi Nhược Hi, bị cuốn vào chốn cung đình với những tranh đấu đầy phong vân biến ảo. Không hề có được cử chỉ, ngôn từ ôn nhu dịu dàng như những thiếu nữ khác.

Ngược lại cô rất ngang tàng, thường cùng các a ca &quot;đấu võ mồm&quot;, &quot;đánh nhau&quot; với các cung nữ, đến cả Khang Hi cũng gọi cô là &quot;Thập tam muội liều mạng&quot;.

Thời gian thấm thoắt, cô nương bướng bỉnh Nhược Hi năm nào đã dần trưởng thành. Cô bị cuốn vào cuộc đấu tranh giành ngôi vị của chín hoàng tử mà không thể rút ra, tình cảm cá nhân cũng bị giằng xé trong cuộc chiến thảm liệt chốn cung đình ....</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 12, 2011, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉詩詩","avatar":""},{"name":"吳奇隆","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"韓棟","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"林更新","avatar":""},{"name":"劉松仁","avatar":""},{"name":"Annie Liu","avatar":""},{"name":"Ye Qing","avatar":""},{"name":"Guo Xiaoting","avatar":""},{"name":"Xing Hanqing","avatar":""},{"name":"Yang Xiaobo","avatar":""},{"name":"Chai Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
