INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-ho-2011', 'Cô Vợ Hờ', 'Just Go With It', 'https://phimimg.com/upload/vod/20240905-1/ee4cace531bb0e38b56ea8587c206f3c.jpg', 'https://phimimg.com/upload/vod/20240905-1/95b6f4bf6185941c21f97ac7f699c6c9.jpg', '<p>20 năm trước, chàng bác sĩ phẫu thuật thẩm mỹ Danny (Adam Sandler) từng rất hạnh phúc vì chuẩn bị lấy vợ, nhưng không may cuộc hôn nhân lại bất thành, và anh ta buồn bã ra ngoài lang thang với chiếc nhẫn cưới. Không ngờ các cô gái nhìn thấy thế, lại nghĩ anh ta đã kết hôn, sẽ khác với những gã sở khanh mà họ đã từng hẹn hò, vậy nên họ dễ dàng “đổ” vì anh.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"Griffin Gluck","avatar":""},{"name":"Dave Matthews","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Rachel Dratch","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Dan Patrick","avatar":""},{"name":"Minka Kelly","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"Rakefet Abergel","avatar":""},{"name":"Dana Goodman","avatar":""},{"name":"Julia Lea Wolo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
