INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('au-trung-tinh-nghich-phan-1', 'Ấu Trùng Tinh Nghịch (Phần 1)', 'Larva (Season 1)', 'https://phimimg.com/upload/vod/20240908-1/ee8cdeacb49cb9854e3f2bfd4af70c54.jpg', 'https://phimimg.com/upload/vod/20240908-1/e1bbe8a8318a7b0c00f36b421a489ad2.jpg', '<p>Ấu trùng tinh nghịch là một phim truyền hình hài hoạt hình trên máy tính được tạo bởi Tuba Entertainment ở Seoul, Hàn Quốc. Phim hoạt hình này cho thấy hai ấu trùng là nhân vật chính của nó. Vàng - Ấu trùng vàng đi chậm và tham ăn. Anh ta luôn lắng nghe Đỏ nhưng thường mất kiểm soát bản thân khi nhìn thấy thức ăn. Đỏ - Ấu trùng đỏ có tính cách khó gần và thiếu kiên nhẫn. Anh ta hét lên như Bruce Lee (Lý Tiểu Long) và đá chân lên không trung mặc dù anh ta không có chân như con người. Đỏ là một nhân vật luôn trải qua đau khổ. Hầu hết bắt đầu với lòng tham cho một cái gì đó.</p>', 'Hoàn Tất (104/104)', 104, 'hoathinh', 'completed', 11, 2011, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"홍범기","avatar":""},{"name":"안효민","avatar":""},{"name":"강시현","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
