INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-nang-muon', 'Điều Nàng Muốn', 'What Women Want', 'https://phimimg.com/upload/vod/20231101-1/169c5594ad1ae9e69fce68ee495dcc29.jpg', 'https://phimimg.com/upload/vod/20231101-1/cf6d1b2490c81f703eb88bd0c343630a.jpg', '<p>Phim nói về Fred Wang bất ngờ bị điện giật sau một tai nạn trong nhà tắm, anh tỉnh dậy trong bệnh viện và nhận ra mình vừa có được một khả năng bất ngờ: đọc được suy nghĩ của phụ nữ! Bằng khả năng mới mẻ này, Wang nhanh chóng chiếm được cảm tình và niềm tin của người khác phái. Lợi dụng điều này, Wang còn nghe trộm cả ý tưởng của cô đồng nghiệp Ellen và phát biểu một cách trôi chảy như là của mình. Nhưng liệu khả năng này kéo dài đến bao lâu?</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Hu Jing","avatar":""},{"name":"Banny Chen","avatar":""},{"name":"Yuan Li","avatar":""},{"name":"Russell Wong","avatar":""},{"name":"Mavis Pan","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Du Juan","avatar":""},{"name":"Li Chengru","avatar":""},{"name":"Anya Wu","avatar":""},{"name":"Tao Jia","avatar":""},{"name":"Osric Chau","avatar":""},{"name":"Deshun Wang","avatar":""},{"name":"Zhang Ying","avatar":""},{"name":"Shen Chang","avatar":""},{"name":"Yang Jie","avatar":""},{"name":"Tami Zhao Mi","avatar":""},{"name":"Yang Luxi","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Zhang Xiang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
