INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-4', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 4)', 'Star Wars: The Clone Wars (Season 4)', 'https://phimimg.com/upload/vod/20240624-1/6e0eee975129a5d4f99f5f0c2918be5f.jpg', 'https://phimimg.com/upload/vod/20240624-1/2c1972a4d08129baf9c1b5f85c704bb5.jpg', '<p>Leo thang và mở rộng đến các góc chưa được khám phá của thiên hà, phạm vi và quy mô của Star Wars: The Clone Wars tiếp tục phát triển. Những kẻ thù đáng sợ trong quá khứ quay trở lại để giải quyết những điểm cũ và những liên minh bất ngờ được thành lập ở cả hai phía của trận chiến. Được giới phê bình đánh giá cao và không giống bất kỳ chương trình hoạt hình nào khác trên truyền hình, Star Wars: The Clone Wars đưa người xem đến ngay tuyến đầu của cuộc xung đột thiên hà lớn.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 15, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
