INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-hiep-tinh-duyen', 'Kiếm Hiệp Tình Duyên', 'Sword Heroes Fate', 'https://phimimg.com/upload/vod/20240829-1/354644520fb89d0902d27551c9e6d273.jpg', 'https://phimimg.com/upload/vod/20240829-1/ff2dc593e675f4fb26c751590a404417.jpg', '<p>Năm 2030, tại buổi họp báo ra mắt trò chơi trực tuyến quy mô lớn của JS có tên mã là JX003, nhà thiết kế chính đã thông báo rằng hệ thống JX003 sẽ cho phép phần lớn những người đam mê Internet bước vào thế giới ảo của kiếm sĩ thông qua các cảm biến ở dạng mô phỏng, và cảm nhận một cách thực tế. Vui, giận, buồn, yêu, ghét và ghét, đồng thời, nó bao gồm tất cả các cảm giác của xúc giác, thị giác và khứu giác. Trong thế giới ảo, hacker Triệu Tiểu Triệu đã chặn bộ nhớ và các kênh thoát của tất cả người chơi đóng vai nhân vật trong trò chơi bằng vi-rút và ẩn mình trong không gian ảo. Sau khi trải qua đủ loại khúc ngoặt trong thế giới ảo của triều đại nhà Đường, Diệp Phàm, Triệu Tiểu Triệu, Ninh Hinh và Diệp Khu, bốn bậc thầy Internet chính trực trong thực tế, đã đến với nhau. Họ phát hiện ra rằng có một thế lực hùng mạnh đang cạnh tranh với họ để giành lấy &quot;Cửu Thiên Huyền Ngọc&quot;. Sau một trận đấu trí và dũng khí, &quot;Cửu Thiên Huyền Ngọc&quot; cuối cùng đã được bảo vệ an toàn trong tay của Diệp Phàm, Triệu Tiểu Triệu và Đỗ Vũ.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 8, 2011, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Đình Phong","avatar":""},{"name":"Thái Trác Nghiên","avatar":""},{"name":"Ngô Á Kiều","avatar":""},{"name":"Tôn Tổ Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
