INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-tinh', 'Gạ Tình', 'Madrid, 1987', 'https://phimimg.com/upload/vod/20240825-1/a582f2f7de4a3e53ad90e3e678581fd1.jpg', 'https://phimimg.com/upload/vod/20240825-1/6fea0df87d5a5f1adca0d48df5548643.jpg', '<p>Vào năm 1987 tại Madrid, cuộc gặp gỡ bất ngờ giữa một nhà báo kỳ cựu và một sinh viên trẻ đã dẫn đến cuộc khám phá sâu sắc về tình yêu, ham muốn, chính trị, quyền lực và sự khám phá lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"José Sacristán","avatar":""},{"name":"María Valverde","avatar":""},{"name":"Ramon Fontserè","avatar":""},{"name":"Alberto Ferreiro","avatar":""},{"name":"Bárbara de Lemus","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
