INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-15-15-phut-tinh-lang', 'Thám Tử Lừng Danh Conan 15: 15 Phút Tĩnh Lặng', 'Detective Conan: Quarter of Silence', 'https://phimimg.com/upload/vod/20231019-1/77f1474fb74f187f6476ce4579d9cb2a.jpg', 'https://phimimg.com/upload/vod/20231019-1/552ca207f81a03a99b2f1e4f7dea6475.jpg', '<p>Câu chuyện bắt đầu với một tên được coi là mối đe dọa của chính phủ Nhật Bản, nhưng óc siêu phàm Conan sẽ ngăn chặn mọi tai họa có thể ập đến khi đường hầm xe điện ngầm bị nổ tung. Conan đã tìm ra được rằng có sự liên hệ giữa một ngôi làng đã bị dời đi vì một dự án làm con đập, và cậu ấy phải chạy đua để ngăn tên tội phạm trước khi có một vụ án mạng nào xảy ra.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2011, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Mayumi Izuka","avatar":""},{"name":"Keiichi Nanba","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
