INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-su-tu-cuoi-cung', 'Bầy Sư Tử Cuối Cùng', 'The Last Lions', 'https://phimimg.com/upload/vod/20240818-1/edf1110f0032457499d75cc032e8b45e.jpg', 'https://phimimg.com/upload/vod/20240818-1/bba39345ee7c5c8b62384ed1b6af506f.jpg', '<p>Ở Đồng bằng Okavango của Botswana, một con sư tử cái bị ruồng bỏ và hai con sư tử con của nó phải chiến đấu một mình để sinh tồn - vượt qua mọi nguy hiểm. Cách phòng thủ duy nhất của chúng là trốn thoát đến Đảo Duba -- và với điều đó, một tương lai không xác định. Bối cảnh cho câu chuyện sử thi này là một trong những vùng cuối cùng mà sư tử có thể sống trong tự nhiên. Đối mặt với tình trạng đất đai ngày càng cạn kiệt và áp lực ngày càng tăng từ việc săn bắn, sư tử - giống như con sư tử cái đơn độc của chúng ta và đàn con của nó - đang tiến đến bờ vực tuyệt chủng.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'FHD', 'Botswana', 0, '[{"name":"Jeremy Irons","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324470);
