INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-danh-o-my-phan-2', 'Thành Danh Ở Mỹ (Phần 2)', 'How To Make It In America (Season 2)', 'https://phimimg.com/upload/vod/20240809-1/921891d97d7079ea62f5f7feb8190ad2.jpg', 'https://phimimg.com/upload/vod/20240809-1/5145e50829eade8d81d6394666fe02fa.jpg', '<p>Ben và Cam trở về New York đầy phấn khích với kế hoạch ra mắt dòng sản phẩm CRISP của họ. Rene tâng bốc bạn gái bằng sản phẩm Rasta Monsta của mình. Rachel nhận ra mình vẫn còn tình cảm với Ben, nhưng anh đã hẹn hò người khác.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bryan Greenberg","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Eddie Kaye Thomas","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Edgar Garcia","avatar":""},{"name":"Nick Chinlund","avatar":""},{"name":"Andrea Navedo","avatar":""},{"name":"Tuffy Questell","avatar":""},{"name":"Nicole LaLiberte","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
