INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-moi-2011', 'Con Mồi', 'The Prey', 'https://phimimg.com/upload/vod/20240802-1/d88e2b7b34e55e9a960a3f3f75364f32.jpg', 'https://phimimg.com/upload/vod/20240802-1/24fa68269d774aeabf2079fe3e267cfb.jpg', '<p>The Prey (Tiếng Pháp: La Proie) là một bộ phim kinh dị Pháp 2011 của đạo diễn phim hành động Éric Valette. Franck bị đi tù và vô tình kết bạn với Jean-Louis. Jean-Louis hứa sẽ chăm sóc gia đình của Franck sau khi hắn ta được thả ra. Thế nhưng, Franck biết rằng Jean-Louis là một kẻ giết người hàng loạt. Vì vậy ông phải thoát ra để bảo vệ gia đình mình. Liệu cả gia đình Franck sẽ bình an vô sự?</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Albert Dupontel","avatar":""},{"name":"Alice Taglioni","avatar":""},{"name":"Stéphane Debac","avatar":""},{"name":"Natacha Régnier","avatar":""},{"name":"Sergi López","avatar":""},{"name":"Caterina Murino","avatar":""},{"name":"Olivier Schneider","avatar":""},{"name":"Zinedine Soualem","avatar":""},{"name":"Serge Hazanavicius","avatar":""},{"name":"Jean-Marie Winling","avatar":""},{"name":"Stephane Girondeaud","avatar":""},{"name":"François Hatt","avatar":""},{"name":"Lucien Jean-Baptiste","avatar":""},{"name":"Yves Verhoeven","avatar":""},{"name":"Claire B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
