INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-moi-2011', 'Con Mồi', 'The Prey', 'con mồi the prey albert dupontel alice taglioni stéphane debac natacha régnier sergi lópez caterina murino olivier schneider zinedine soualem serge hazanavicius jean-marie winling stephane girondeaud françois hatt lucien jean-baptiste yves verhoeven claire b ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-dam-mau-phan-4', 'Giang Hồ Đẫm Máu (Phần 4)', 'Sons Of Anarchy (Season 4)', 'https://phimimg.com/upload/vod/20240731-1/883fcb5083e0063c9b63d00ef5e901b4.jpg', 'https://phimimg.com/upload/vod/20240731-1/ace88877c1d121468bcf1570a9d27e27.jpg', '<p>Sons of Anarchy là một bộ phim truyền hình tội phạm của Mỹ bởi đạo diễn Kurt Sutter được phát sóng vào năm 2008 và kết thúc vào năm 2014. Kể cuộc đời của một câu lạc bộ xe gắn máy sống ngoài vòng pháp luật hoạt động tại Charming , một thị trấn hư cấu ở Thung lũng Trung tâm California . Charlie Hunnam trong vai Charlie Jackson là &quot;Jax&quot; Teller.

Mỗi Season sẽ liên quan đến âm mưu song song đan xen và chồng lên nhau, tập trung vào cả đời sống cá nhân và gia đình của Jackson &quot;Jax&quot; Teller ( Charlie Hunnam ) và trên SAMCRO ( viết tắt bởi Sons of Anarchy Motorcycle Club, Redwood Original). SAMCRO có liên quan đến việc buôn súng ở miền tây Hoa Kỳ, và đối phó với các băng nhóm đối thủ, chính trị gia và chính quyền. Chính thức lúc đầu là phó chủ tịch và sau đó lên giữ chủ tịch sau này của SAMCRO, sau khi phát hiện những tội ác mà chủ tịch cũ đã giấu diếm anh. Jax đấu tranh để quản lý câu lạc bộ và giữ lại tâm huyết của người sáng lập chính là người cha quá cố John.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 10, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Katey Sagal","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Dayton Callie","avatar":""},{"name":"David Labrava","avatar":""},{"name":"Drea de Matteo","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Niko Nicotera","avatar":""},{"name":"Theo Rossi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
