INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-trai-dao-chin', 'Khi Trái Đào Chín', 'The 33D Invader', 'https://phimimg.com/upload/vod/20231117-1/ab19594457f037c11f0f8d788609b2c0.jpg', 'https://phimimg.com/upload/vod/20231117-1/8f9b542a4b4b7bc6c2cb5b6f82810959.jpg', '<p>Năm 2046, hành tinh Sucker đã làm trái đất thay đổi khi biến 99% đàn ông mất khả năng duy trì giống nòi. Liên hợp quốc đã chọn ra một phụ nữ khỏe mạnh, đặt tên là “Tương lai” để gửi đến trái đất vào thời điểm năm 2011 vơi mục đích gặp một nam nhi khỏe mạnh để tạo ra những giống nòi cường tráng cho trái đất. Tuy niên hành tinh Sucker đã cử 2 tinh binh của chúng là Sucker số 1 và Sucker số 2 xuống ngăn chặn kế hoạch này</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Akiho Yoshizawa","avatar":""},{"name":"Monna Lam","avatar":""},{"name":"Wu Qing-Qing","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Samuel Leung Cheuk-Moon","avatar":""},{"name":"Chen Jun-Yan","avatar":""},{"name":"Zhi Zhi","avatar":""},{"name":"Taka Katou","avatar":""},{"name":"Justin Cheung","avatar":""},{"name":"Chen Chih-Ying","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324470);
