INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-rieng-minh-em', 'Chỉ Riêng Mình Em', 'Always', 'https://phimimg.com/upload/vod/20230913-1/6af2bdc95e58d8c6d5b457abb6332f9b.jpg', 'https://phimimg.com/upload/vod/20230913-1/0af13a58d61c4ef047afdd5088a51f3e.jpg', '<p><span style="font-family: ">Cheol Min (So Ji Sub) trước đây từng là một võ sỹ quyền anh, công việc hiện tại của anh là người đưa nước và trông coi bãi đỗ xe. Cuộc sống của anh có lẽ vẫn cứ bình lặng trôi đi nếu không có một ngày, một cô gái mù tên là Jeong Hwa (Han Hyo Joo) đột ngột xuất hiện, tặng cho anh những trái cam đường, kẹo ngọt, và cả cơm rong biển do nhầm anh với bác bảo vệ trước… Sự nhầm lẫn của Jeong Hwa đã giúp cho hai người quen biết nhau và dần trở nên gần gũi, tự nhiên hơn. Trong buổi hẹn hò đầu tiên, khi Jeong Hwa hỏi về những chuyện trước đây của Cheol Min, anh vô cớ nổi nóng và nói ra những lời xúc phạm đến cô, khiến cho mối quan hệ giữa cả hai trở nên căng thẳng và họ không gặp nhau nữa. Một ngày nọ, người sếp nơi Jeong Hwa làm việc uống say và định giở trò bỉ ổi với Jeong Hwa ngay tại nhà cô</span></p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"So Ji-sub","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Oh Gwang-rok","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Goo Seung-hyun","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Jung Jae-jin","avatar":""},{"name":"Park Seong-geun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
