INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-thu', 'Trả Thù', 'Recoil', 'https://phimimg.com/upload/vod/20240617-1/0bb0d985e641b5291fcf3462455fb2de.jpg', 'https://phimimg.com/upload/vod/20240617-1/6a26cf7e0b51a830aac7e813b633bc07.jpg', '<p>Có vẻ gu hành động võ thuật đang được hướng đến Đông Nam Á sau nhiều thập kỉ bị thống trị bởi Đông Á thì phải. Mới mấy tháng trước thì chúng ta đã được mãn nhãn với những màn võ thuật không chê vào đâu được từ bộ phim The Raid Redemption thì hôm nay, trailer mới của bộ phim Bangkok Revenge cũng vừa được cho ra mắt, cũng máu lửa và tràn ngập những đòn thế ghê rợn. Bangkok Revenge có một cốt truyện cổ điển, một cậu bé chứng kiến cảnh gia đình bị giết năm 10 tuổi. Thế là bao nhiêu quyết tâm căm hờn của cậu đều dành hết vào việc trả thù. 20 năm, cậu bé trở lại, quyết tâm tìm được những kẻ đã sát hại gia đình mình.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Austin","avatar":""},{"name":"Serinda Swan","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"Adam Greydon Reid","avatar":""},{"name":"Camille Solari","avatar":""},{"name":"Tygh Runyan","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Patrick Sabongui","avatar":""},{"name":"Tom McBeath","avatar":""},{"name":"Patrick Gilmore","avatar":""},{"name":"Rebecca Reichert","avatar":""},{"name":"Connor Stanhope","avatar":""},{"name":"Roman Podhora","avatar":""},{"name":"Daniel Boileau","avatar":""},{"name":"Jase An","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
