INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kham-pha-tinh-duc', 'Khám Phá Tình Dục', 'Autoerotic', 'https://phimimg.com/upload/vod/20240603-1/5e378f77c39541a97472b46d74f37ca3.jpg', 'https://phimimg.com/upload/vod/20240603-1/7f5567a7d7f22425b2823f44061f8536.jpg', '<p>Theo chân bốn cặp đôi người Chicago có mối liên hệ với nhau khi họ khám phá ranh giới của niềm vui bản thân và khám phá tình dục.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amy Seimetz","avatar":""},{"name":"Lane Hughes","avatar":""},{"name":"Megan Mercier","avatar":""},{"name":"Kate Lyn Sheil","avatar":""},{"name":"Joe Swanberg","avatar":""},{"name":"Chris Hilleke","avatar":""},{"name":"Kris Rey","avatar":""},{"name":"Frank V. Ross","avatar":""},{"name":"Josephine Decker","avatar":""},{"name":"Rosemary Plain","avatar":""},{"name":"Adam Wingard","avatar":""},{"name":"Ti West","avatar":""},{"name":"Brendan Kelly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
