INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-tranh-cu', 'Chiến Dịch Tranh Cử', 'The Ides Of March', 'https://phimimg.com/upload/vod/20240228-1/1eecd9873f8ab47aeabbacb0c33d9412.jpg', 'https://phimimg.com/upload/vod/20240228-1/d1c750d2cf5d0af403812001fdf5062c.jpg', '<p>Bộ phim xoay quanh cuộc vận động tranh cử tổng thống Mỹ giữa hai ứng viên Mike Morris (George Clooney) và Ted Pullman (Michael Mantell). Trong khi ông Mike Morris là thống đốc bang Pennsylvania và cũng là ứng cử viên cho chức tổng thống thuộc đảng Dân chủ. Đối thủ của ông Ted Pullman đại diện cho đảng Cộng hòa. Cả hai đang tranh chấp tại bang Ohio – nơi sẽ quyết định số phiếu cho cuộc đua vào Nhà Trắng. Trợ lý của Mike Morris - Stephen Myers (Ryan Gosling) là người đứng sau hỗ trợ cho ông trong cuộc vận động tranh cử. Stephen có tuổi trẻ, đam mê và hoài bão. Sau lần gặp gỡ, trao đổi bí mật với Tom Duffy (Paul Giamatti), người quản lý chiến dịch cho thượng nghị sĩ Ted Pullman, sự nghiệp của Stephen bị đe dọa nghiêm trọng. Từ đây, anh dần phát hiện ra hàng loạt vụ bê bối kinh người cùng mặt trái của chính trị.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Gregory Itzin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
