INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh', 'Chiến Binh', 'Warrior', 'null', 'https://phimimg.com/upload/vod/20240227-1/5fba3cd43b992dabaaeed1b81e848775.jpg', '<p>Sau 14 năm xa cách, Tommy, một cựu chiến binh của Mỹ ở chiến trường Iraq, quyết định trở về nhà. Để kiếm tiền cho gia đình của một đồng đội đã hy sinh ở chiến trường, Tommy quyết định tham gia tranh giải MMA Sparta với phần thưởng cho người chiến thắng là 5 triệu USD. Anh quyết định nhờ bố mình là Paddy, cựu võ sĩ quyền Anh nổi tiếng, huấn luyện.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Nolte","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Joel Edgerton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
