INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-giang-sinh-cua-harold-va-kumar', 'Câu Chuyện Giáng Sinh Của Harold Và Kumar', 'A Very Harold & Kumar 3D Christmas', 'https://phimimg.com/upload/vod/20240227-1/a15463dbf9b860341a327147f8cee0ec.jpg', 'https://phimimg.com/upload/vod/20240227-1/6ef8ecf269afd313937f1b3a517a63d1.jpg', '<p>Hai người bạn cùng phòng, một là nhà đầu tư ngân hàng Harold hơi bị nhát gái và một anh chàng sinh viên trường Y Kumar hay bày trò phá phách nghịch ngợm, đều mang trong mình dòng máu lai, Hàn Quốc – Mỹ và Ấn Độ – Mỹ. Ban đầu, hai anh chàng Harold và Kumar chỉ vạch kế hoạch được ăn bánh hambuger ở White Castle cho đêm thứ sáu cuối tuần. Tuy nhiên, đường đến White Castle không phải là dễ dàng, cả hai đã đẩy mình vào một cuộc phiêu lưu đầy kỳ thú dọc đường đi, chỉ trong một đêm họ đã gặp biết bao chuyện dở khóc dở cười, nhiều lúc cười không chịu nổi . Nhưng cuối cùng, vượt qua tất cả, sau đêm nhớ đời đó họ đã đạt được mục đích của mình, bộ phim với nhiều tình tiết hài hước, sử dụng ngôn ngữ rất đời thường ko giả tạo mang lại cảm giác gần gũi cuộc sống thực với khán giả</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kal Penn","avatar":""},{"name":"John Cho","avatar":""},{"name":"Neil Patrick Harris","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
