INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chet-don-doc', 'Chết Đơn Độc', 'A Lonely Place To Die', 'null', 'https://phimimg.com/upload/vod/20240227-1/e58f5d1bd08c5ff3d0818297be55a085.jpg', '<p>Chết Đơn Độc - A Lonely Place To Die bắt đầu khi một nhóm gồm 5 người leo núi đi bộ đường dài và leo núi ở vùng cao nguyên ở Scotland và phát hiện ra một cô gái trẻ người Serbia bị chôn vùi trong một khoang nhỏ ở một nơi hoang dã. Họ bị lôi vào một trò chơi đáng sợ của mèo vờn chuột của những kẻ bắt cóc khi họ cố gắng để đưa cô gái đến nơi an toàn.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melissa George","avatar":""},{"name":"Alec Newman","avatar":""},{"name":"Ed Speleers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
