INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-mau-bat-dac-di', 'Bảo Mẫu Bất Đắc Dĩ', 'The Sitter', 'https://phimimg.com/upload/vod/20240227-1/fdc145257aff0d96388707ad32eb6e65.jpg', 'https://phimimg.com/upload/vod/20240227-1/3ca02bb019883966111c2547fa1f594f.jpg', '<p>Noah, không phải là kiểu người trông trẻ giải trí cho bọn trẻ bất kể nó nhàm chán thế nào. Anh ấy miễn cưỡng tham gia một buổi biểu diễn ngồi; đúng hơn là anh ấy nên làm bất cứ điều gì khác, đặc biệt nếu nó liên quan đến việc lười biếng. Khi Noah đang quan sát đứa trẻ hàng xóm, anh nhận được một cuộc gọi chiến lợi phẩm từ bạn gái trong thành phố. Để hẹn hò với cô ấy, Noah ra đường, nhưng cuộc phiêu lưu đô thị của anh vượt quá tầm kiểm soát khi anh thấy mình đang chạy trốn khỏi một trùm ma túy điên cuồng.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonah Hill","avatar":""},{"name":"Landry Bender","avatar":""},{"name":"Max Records","avatar":""},{"name":"Kevin Hernandez","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Kylie Bunbury","avatar":""},{"name":"Erin Daniels","avatar":""},{"name":"D.W. Moffett","avatar":""},{"name":"J.B. Smoove","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
