INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-tot-dep', 'Cuộc Sống Tốt Đẹp', 'A Better Life', 'https://phimimg.com/upload/vod/20240220-1/edb2b6cc20c5cfb227313cd2df28258f.jpg', 'https://phimimg.com/upload/vod/20240220-1/230d43926a6cb68eebb758cd2c326206.jpg', '<p>Một người làm vườn ở Đông L.A. đấu tranh để giữ con trai mình tránh xa các băng nhóm và các cơ quan nhập cư khi đi khắp thị trấn để thực hiện công việc tạo cảnh quan cho những chủ đất giàu có của thành phố.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Demián Bichir","avatar":""},{"name":"José Julián","avatar":""},{"name":"Chelsea Rendon","avatar":""},{"name":"Dolores Heredia","avatar":""},{"name":"Joaquín Cosío","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
