INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('butter', 'Butter', 'Butter', 'https://phimimg.com/upload/vod/20240220-1/45b4b4a5aba9b4f63d8cb5ec878aa8e0.jpg', 'https://phimimg.com/upload/vod/20240220-1/06561ea601450783fbdacf6e8a3c6e77.jpg', '<p>Món Bơ Hảo Hạng kể về Laura Pickler (Jennifer Garner), một người phụ nữ tham vọng có chồng là nhà điêu khắc tượng bơ nổi tiếng nhất thị trấn. Vì bực mình trước ý định từ bỏ vị trí số một của chồng, Laura đã quyết định tự mình sáng tạo ra phong cách riêng, ngày đêm khổ luyện để quay lại cuộc thi với quyết tâm giữ gìn vị trí độc tôn. Để giành chiến thắng, cô cũng không tiếc sử dụng mọi mánh khóe để lấn lướt đối thủ. Nhưng sau cùng, liệu Laura có đạt được mục đích của mình?</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Garner","avatar":""},{"name":"Yara Shahidi","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Kristen Schaal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
