INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-bai-cua-sam-axe', 'Thất Bại Của Sam Axe', 'Burn Notice: The Fall Of Sam Axe', 'https://phimimg.com/upload/vod/20240220-1/5d929d6440800c7c828d8590b1f265d0.jpg', 'https://phimimg.com/upload/vod/20240220-1/9a890dd75bb84fe762adaa594af1b2b0.jpg', '<p>Trước khi Sam Axe hợp tác với Michael và Fiona, anh ấy là Chỉ huy Axe, US Navy SEAL. Sự sụp đổ của Sam Axe kể câu chuyện về cách Sam đi từ Tư lệnh Hải quân đáng kính trở thành người đàn ông bí ẩn mà chúng ta biết trên Thông báo Burn. Trong nhiệm vụ quân sự cuối cùng của Sam, anh được cử đến khu rừng rậm Colombia để điều tra các tuyên bố về một tổ chức khủng bố độc ác chỉ được biết đến với cái tên Espada Ardiente (Thanh kiếm rực lửa). Nhiệm vụ của anh ta: xác định xem liệu viện trợ quân sự của Hoa Kỳ có cần thiết để đối phó với mối đe dọa hay không. Nhưng khi anh đến, mọi thứ phức tạp hơn anh tưởng tượng. Anh ta nhận được tin rằng quân nổi dậy đã nhắm mục tiêu vào một phòng khám dân sự nhỏ nằm sâu trong rừng. Bây giờ Sam phải cứu các bác sĩ và bệnh nhân của phòng khám khỏi cái chết nhất định. Tuy nhiên, dường như không có gì xảy ra và Espada Ardiente có thể không phải là mối đe dọa lớn nhất mà Sam Axe phải đối mặt.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Campbell","avatar":""},{"name":"Kiele Sanchez","avatar":""},{"name":"Chandra West","avatar":""},{"name":"John Diehl","avatar":""},{"name":"RonReaco Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
