INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-van-truong', 'Quan Vân Trường', 'The Lost Bladesman', 'https://phimimg.com/upload/vod/20240220-1/684653ca928ff8a6ee2de7f886ebcceb.jpg', 'https://phimimg.com/upload/vod/20240220-1/2e991199e483022a14d18a99a584316f.jpg', '<p>Quan Vân Trường là câu chuyện kể về những ngày tháng “thân tại doanh Tào lòng ở Hán” của Quan Vũ, về cuộc hành trình hộ tống Qi Lan (Tôn Lệ) – vợ của Lưu Bị (Phương Trung Tín) ra khỏi vòng kiềm tỏa của Tào Tháo (Khương Văn), giữ trọn đạo làm tôi và đạo làm tiểu đệ. Trong cuộc hành trình ấy, Quan Vũ đã phải vượt qua biết bao hiểm nguy, cạm bẫy. Khi thì là những lời ngon ngọt dụ dỗ, vàng bạc châu báu... Mà Tào Tháo dùng để mua chuộc Quan Vũ, khi thì là những cuộc giao đấu quyết liệt để phá vòng vây quân Ngụy... Nhưng thử thách càng nhiều thì tấm lòng trung thành dũng cảm của Quan Vân Trường lại càng sáng ngời và đáng quý.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Wen Jiang","avatar":""},{"name":"Betty Sun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
