INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gosick', 'Gosick', 'Gosick', 'https://phimimg.com/upload/vod/20240220-1/d597c9dfd6fa6f0bf5c5a4f4a6e56c2b.jpg', 'https://phimimg.com/upload/vod/20240220-1/18817a08874480a5cd59a81e9907d20a.jpg', '<p>Câu chuyện xảy ra vào năm 1924 tại Vương quốc Saubure ở Châu Âu. Kujo Kazuya là em thứ 3 của một Quân nhân người Nhật, chuyển đến học ở Học viện Thánh Maguerite, nơi những chuyện kì bí xảy ra như cơm bữa. Tại đây cậu gặp Victorique (ngậm tẩu nhìn chẳng khác Sherlock Holmes), thông minh xinh đẹp. Và Kazuya cùng Victorique bắt đầu khám phá ra những bí ẩn mà các thám tử phải chịu thua.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 15, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
