INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-quy', 'Vua Quỷ', 'Beelzebub', 'https://phimimg.com/upload/vod/20240215-1/0da95a3ef2b8e26df0e3254398adfd6a.jpg', 'https://phimimg.com/upload/vod/20240215-1/3c272fa63f61817c5b172246745d8fd3.jpg', '<p>Nội dung sơ sơ thì chắc ai cũng biết rồi, thì là câu chuyện xoay quanh Oga Tatsumi, người được coi là gã côn đồ mạnh nhất vùng và học ở ngôi trường cũng toàn côn đồ. Vào một ngày đẹp trời, đang cúp tiết ngủ bên bờ sông, Oga thấy một người đàn ông tự nhiên bị chia nửa ra và bên trong là một em bé sơ sinh. Sau đó Oga biết được, đứa bé đó là con của quỷ vương, và Oga được chọn là người nuôi dưỡng đứa bé đó cùng với người hầu gái tên Hilda. Phim xoay quanh cuộc sống bị đảo lộn của cậu với Baby Beel và Hilda</p>', 'Hoàn Tất (60/60)', 60, 'hoathinh', 'completed', 18, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324470);
