INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-an-dem-loat-phim-phan-2', 'Quán Ăn Đêm – Loạt Phim (Phần 2)', 'Midnight Diner (Season 2)', 'https://phimimg.com/upload/vod/20240209-1/8cbb4ab33e9d3fcd3d1e62a95e41cc2c.jpg', 'https://phimimg.com/upload/vod/20240209-1/724ce475de4693b29eb02aa4f0c3b1a4.jpg', '<p>Chủ quán ăn đêm phục vụ đồ ăn và đồng cảm với nhiều khách hàng khác nhau, từ yakuza, nhân viên cửa hàng trò chơi cho đến vũ công thoát y.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kobayashi Kaoru","avatar":""},{"name":"Ayata Toshiki","avatar":""},{"name":"Fuwa Mansaku","avatar":""},{"name":"Matsushige Yutaka","avatar":""},{"name":"Mitsuishi Ken","avatar":""},{"name":"Uno Shohei","avatar":""},{"name":"Yamanaka Takashi","avatar":""},{"name":"Kaneko Kiyofumi","avatar":""},{"name":"Sudou Risa","avatar":""},{"name":"Kobayashi Asako","avatar":""},{"name":"Yoshimoto Nahoko","avatar":""},{"name":"Joe Odagiri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
