INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-ngam-phan-2', 'Đế Chế Ngầm (Phần 2)', 'Boardwalk Empire (Season 2)', 'https://phimimg.com/upload/vod/20240205-1/f2a3d5c5c9b07671a83c3493bb12f65f.jpg', 'https://phimimg.com/upload/vod/20240205-1/7a2d8834b3a03203eda8eb9234a3edeb.jpg', '<p>Boardwalk Empire là bộ phim truyền hình nói về vấn đề tội phạm trong thời kì những năm 1920 đến 1930 khi lệnh cấm bán rượu được ban hành. Và hệ lụy là sự xuất hiện của hàng loạt các băng nhóm tội phạm, chính trị trở thành Gangster. Nơi bắt nguồn cảm hứng cho chế độ Mafia Mỹ, mà sau này hình thành các huyền thoại mafia nổi tiếng như: Bugsy Siegel, Lucky Luciano, Al Capone Scarface. Nhân vật chính là Enoch “Nucky” Thompson, một chính trị gia nổi bật lên trong thời kì này và đã trở thành người lãnh đạo thành phố Atlantic City, New Jersey. Boardwalk Empire có những bối cảnh được trau chuốt tỉ mỉ và vô cùng chân thực, cùng cốt truyện đặc sắc và gay cấn được thể hiện một cách hoàn hảo bởi những diễn viên tài năng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Buscemi","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Vincent Piazza","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324470);
