INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-truot-van', 'Cô Nàng Trượt Ván', 'Chalet Girl', 'https://phimimg.com/upload/vod/20240207-1/e0a078c68374018f688c221e1c3bb8b6.jpg', 'https://phimimg.com/upload/vod/20240207-1/19fca0dff3d410b920f884fa318f0ffd.jpg', '<p>Trong khi làm việc tại một khu nghỉ dưỡng trượt tuyết độc quyền để hỗ trợ bố, Kim học trượt tuyết và giỏi môn này đến mức cô tham gia một cuộc thi với giải thưởng tiền mặt khổng lồ. Cô ấy phải đào sâu để vượt qua nỗi sợ hãi của mình, nhưng cuộc sống của cô ấy trở nên phức tạp hơn thông qua ông chủ được chỉ định của cô ấy, Jonny.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Felicity Jones","avatar":""},{"name":"Ed Westwick","avatar":""},{"name":"Brooke Shields","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Tamsin Egerton","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
