INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-an-thit-nguoi', 'Thành Phố Ăn Thịt Người', 'Remains', 'https://phimimg.com/upload/vod/20240207-1/cfaf0e9c989b442ed61d4151cdacd8a9.jpg', 'https://phimimg.com/upload/vod/20240207-1/a785ae4ed41d225e678e334c4f9f0fe4.jpg', '<p>Một vụ nổ hạt nhân đã lây lan một loại virus khắp thành phố và biến mọi người thành Zombie tấn công những người còn sống. Tori và Tom cùng những người còn lại phải trốn trong Casino và tìm cách chống trả lại đám Zombie đang khát máu.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Grant Bowler","avatar":""},{"name":"Tawny Cypress","avatar":""},{"name":"Evalena Marie","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
