INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cuoc-doi-tuoi-dep', 'Một Cuộc Đời Tươi Đẹp', 'A Beautiful Life', 'https://phimimg.com/upload/vod/20240207-1/6bd88332b4a0f37c0f75f2e43028a8cc.jpg', 'https://phimimg.com/upload/vod/20240207-1/f00b947739a4e10cd21ad4f240b89673.jpg', '<p>Sau khi gặp nhau trong một tình huống khó xử, một nữ doanh nhân quyến rũ và một viên cảnh sát cổ hủ đã bắt đầu một mối quan hệ làm thay đổi cuộc sống của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thư Kỳ","avatar":""},{"name":"Lưu Diệp","avatar":""},{"name":"Huỳnh Thu Sinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
