INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-lai-so-thu', 'Mở Lại Sở Thú', 'We Bought A Zoo', 'https://phimimg.com/upload/vod/20240207-1/3042e0b519acaf48b7054c73d4e29fb8.jpg', 'https://phimimg.com/upload/vod/20240207-1/63cb35fb2d8f4ce01105831c641302ea.jpg', '<p>Sau khi vợ qua đời, Benjamin mua một ngôi nhà với một sở thú gắn liền với nó. Sau đó, ông nhận trách nhiệm cải tạo vườn thú để nó có thể được mở cửa trở lại cho công chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Colin Ford","avatar":""},{"name":"Maggie Elizabeth Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
