INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-tieu-lon', 'Mục Tiêu Lớn', 'Submarine', 'https://phimimg.com/upload/vod/20240207-1/a62fa1db57b60abfa9f5c268a89dfbfe.jpg', 'https://phimimg.com/upload/vod/20240207-1/745ea48e5875aaa0ee4e10bfe019eb31.jpg', '<p>Một bộ phim hài kể về 1 cậu nhóc 15 tuổi, Oliver Tate, có 2 mục tiêu: đánh mất trinh tiết của mình trước ngày sinh nhật tiếp theo, và dập tắt ngọn lửa tình giữa mẹ với người yêu cũ đang quay trở lại trong cuộc sống của bà. Oliver thích một cô bé tinh nghịch và thẳng tính học cùng trường là Jordana. Cậu đồng ý giúp cô tìm cách làm cho bạn trai của cô ghen, bằng cách chụp ảnh nụ hôn của 2 người, đưa vào nhật kí và phát tán nó ở trường. Mặc dù kế hoạch không thành công và Oliver bị bắt nạt, nhưng quan hệ giữa cậu và Jordana tiến triển hơn trước. Ở nhà, Oliver phát hiện ra sự lạnh nhạt giữa bố và mẹ mình, đồng thời tìm hiểu mối quan hệ giữa mẹ với 1 người đàn ông là Graham - bạn trai cũ của bà, người mới chuyển đến sống cạnh nhà họ. Oliver tìm mọi cách để khiến Graham tránh xa khỏi mẹ mình, cậu đã vi phạm những qui định đối với trẻ vị thành niên như đột nhập vào nhà Graham và uống rượu say. Cha mẹ cậu sau khi hiểu được cuộc nổi loạn của con mình thì đã dần làm lành với nhau...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Craig Roberts","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Paddy Considine","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
