INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('raone', 'Ra.One', 'Ra.One', 'https://phimimg.com/upload/vod/20240207-1/c0567216155a4b7f94731b3fc752c7c5.jpg', 'https://phimimg.com/upload/vod/20240207-1/aaff4c92d8f0ad4eecddb80f04f3d083.jpg', '<p>Muốn được con trai yêu quý, Shekhar - một lập trình viên trò chơi video đã tạo ra trò chơi đối kháng với nhân vật Ra One có trí thông minh nhân tạo và sức mạnh phi thường, tuy nhiên đã có lỗi xãy ra với phần mềm khiến cho nhân vật Ra One từ trò chơi bước ra thế giới thực.Shekhar phải trở thành một siêu anh hùng Ra One với sức mạnh công nghệ đánh bại nhân vật do mình tạo ra để cứu lấy những người anh yêu quý.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Arjun Rampal","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Sanjay Dutt","avatar":""},{"name":"Priyanka Chopra Jonas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
