INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('raone', 'Ra.One', 'Ra.One', 'ra.one ra.one shah rukh khan arjun rampal kareena kapoor khan sanjay dutt priyanka chopra jonas ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tro-than-tai', 'Quán Trọ Thần Tài', 'Treasure Inn', 'https://phimimg.com/upload/vod/20240207-1/e6fa318254299285a1b2f739750b7a74.jpg', 'https://phimimg.com/upload/vod/20240207-1/cae789cc35b8f460b7b5471c9349078f.jpg', '<p>Cung Thiếu Gia (Tạ Đình Phong) và Lão Ba (Trương Gia Huy) là hai tân bộ đầu của huyện Bạch Mã. Mặc dù có chút võ công nhưng cả hai lại không có cơ hội vụt sáng mà suốt ngày chỉ loay hoay với việc giặt giũ và nấu nướng trong nha huyện. Cho đến một ngày nọ, huyện Bạch Mã xảy ra một vụ án long trời lở đất. Chỉ trong một đêm, gia đình Trương lão gia bị rơi vào thảm họa diệt môn. Bức tượng quý giá “Ngọc Quan âm” của Trương gia cũng bị đánh cướp. Quyết tâm khám phá vụ án, Cung thiếu gia và lão Ba đã lên đường đến Quán Trọ Thần Tài – một quán trọ thần bí nằm trong sa mạc mà chủ nhân của nó là Ngọc Linh Lung (Lưu Dương) – một cô gái cực kỳ quyến rũ...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Tạ Đình Phong","avatar":""},{"name":"Trương Gia Huy","avatar":""},{"name":"Dawei Tong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
