INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ca-heo', 'Câu Chuyện Cá Heo', 'Dolphin Tale', 'https://phimimg.com/upload/vod/20240207-1/142593336724ea7bb3ba09880a931f85.jpg', 'https://phimimg.com/upload/vod/20240207-1/e2c0f87b3d3b48aad23b88c24a202166.jpg', '<p>Xoay quanh hành trình giải cứu và đem lại cuộc sống mới cho chú cá heo bị mất đuôi Winter của cậu bé cô độc Sawyer Nelson. Tin rằng chỉ cần có một cái đuôi giả thì Winter có thể bơi lại như trước, Sawyer đã làm mọi điều có thể để Winter có được đuôi mới. Phim là câu chuyện cảm động về tình bạn dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathan Gamble","avatar":""},{"name":"Harry Connick","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Cozi Zuehlsdorff","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
