INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-ca-heo', 'Câu Chuyện Cá Heo', 'Dolphin Tale', 'câu chuyện cá heo dolphin tale nathan gamble harry connick morgan freeman cozi zuehlsdorff ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-apollo-18', 'Bí Mật Apollo 18', 'Apollo 18', 'https://phimimg.com/upload/vod/20240205-1/2ec652dd34518e3f12b14cf3641dff09.jpg', 'https://phimimg.com/upload/vod/20240205-1/82334b2ab5b846de508e005d7b257e2d.jpg', '<p>Con tàu Apollo 17 - ra mắt ngày 17/4/1972 là nơi thực thi nhiệm vụ cuối cùng bay lên mặt trăng của Cơ quan hàng không vũ trụ Mỹ NASA. Thế nhưng 1 năm sau, 2 phi hành gia Mỹ đã được gửi vào một nhiệm vụ bí mật để bay đến mặt trăng được tài trợ bởi Bộ Quốc phòng Mỹ. Trong khi đó, NASA đã phủ nhận tính xác thực của nhiệm vụ này, nhưng những thước phim mà người Nga đã quay được đã chứng minh nhiệm vụ đó là có thật, dấy lên mối nghi ngờ: “Có một lý do mà chúng ta sẽ không bao giờ quay lại mặt trăng”. Apollo 18 sẽ hé lộ lý do này đồng thời cho thấy bằng chứng đáng lo ngại mới về các dạng sinh vật sống khác...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Warren Christie","avatar":""},{"name":"Lloyd Owen","avatar":""},{"name":"Ryan Robbins","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
