INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-thuat-sai-lam', 'Chiến Thuật Sai Lầm', 'Tactical Force', 'https://phimimg.com/upload/vod/20240205-1/8ac23cb4d01a3e43bacf94fa08f80931.jpg', 'https://phimimg.com/upload/vod/20240205-1/b9f0dd8b1b0f179edc17c741b65a1e7f.jpg', '<p>Một bài tập huấn luyện cho Đội LAPD SWAT đã gặp sai lầm nghiêm trọng khi họ thấy mình đọ sức với hai băng đảng đối thủ khi bị mắc kẹt trong Nhà chứa máy bay bỏ hoang, không được trang bị gì ngoài khoảng trống.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Austin","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"Michael Shanks","avatar":""},{"name":"Lexa Doig","avatar":""},{"name":"Darren Shahlavi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
