INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('patiala-house', 'Patiala House', 'Patiala House', 'https://phimimg.com/upload/vod/20240205-1/7b2914287b86d5b58fc65656f7e40b69.jpg', 'https://phimimg.com/upload/vod/20240205-1/8495a07f317d0d93bf2d20b6ac2979ad.jpg', '<p>Parghat Singh Gattu Kahlon là một chủ cửa hàng trung niên, người bí mật tập chơi bowling vào ban đêm để nuôi ước mơ được chơi cho đội tuyển Anh. Mặc dù các thành viên trong gia đình coi thường anh vì đã từ bỏ ước mơ của mình chỉ vì mong muốn của cha anh, nhưng họ vẫn tìm thấy tia hy vọng và thuyết phục anh chơi cho đội tuyển Anh trong khi họ lên kế hoạch che giấu sự thật với cha anh.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Anushka Sharma","avatar":""},{"name":"Rishi Kapoor","avatar":""},{"name":"Dimple Kapadia","avatar":""},{"name":"Masha Pour","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
