INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-dieu-uoc-giang-sinh', '12 Điều Ước Giáng Sinh', '12 Wishes For Christmas', 'https://phimimg.com/upload/vod/20240220-1/51e5fb2d18dc5cd1bf63c79831bfdcf2.jpg', 'https://phimimg.com/upload/vod/20240220-1/2ccdac609525a3984ac50f7ef8da6a37.jpg', '<p>12 Điều Ước Giáng Sinh - 12 Wishes For Christmas xoay quanh cô nàng Laura. Một ngày, cô được một phụ nữ bí ẩn ban cho 12 điều ước Giáng sinh. Nhưng không lâu sau, Laura nhận ra rằng mong muốn của cô đang dẫn đến những tình huống không lường trước được, và cô phải nhanh chóng hành động để giành lấy mạng sống của mình - và con chó - trở về như trước Giáng sinh</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elisa Donovan","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Gabrielle Carteris","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
