INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-uat', 'Phẫn Uất', 'Tyrannosaur', 'https://phimimg.com/upload/vod/20240128-1/12ad5ac836708a654949fd269fa9518e.jpg', 'https://phimimg.com/upload/vod/20240128-1/63679ae5a570869febe3426c006d96a3.jpg', '<p>Câu chuyện về Joseph, một người đàn ông bị ám ảnh bởi bạo lực và cơn thịnh nộ đang khiến anh ta tự hủy hoại bản thân. Khi cuộc sống của Joseph rơi vào vòng xoáy hỗn loạn, một cơ hội cứu chuộc xuất hiện dưới hình dạng của Hannah, một nhân viên cửa hàng từ thiện Cơ đốc giáo. Mối quan hệ của họ phát triển để tiết lộ rằng Hannah đang che giấu một bí mật của riêng mình với những hậu quả tàn khốc đối với cuộc sống của cả hai.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Mullan","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Paul Popplewell","avatar":""},{"name":"Samuel Bottomley","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
