INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuon-mat-ke-sat-nhan', 'Khuôn Mặt Kẻ Sát Nhân', 'Faces In The Crowd', 'https://phimimg.com/upload/vod/20240128-1/2861df3b997a351410d0273ea5d130b7.jpg', 'https://phimimg.com/upload/vod/20240128-1/66e312e7e67db1b226277237fe58ebd7.jpg', '<p>Bộ phim kinh dị này xoay quanh một người phụ nữ bị một chứng bệnh không nhìn rõ được mặt người sau khi sống sót từ một vụ giết người hàng loạt. Với tình trạng đó, mỗi khi một gương mặt hiện ra và biến mất trước mắt cô, nó lại thay hình đổi dạng, và kẻ giết người thì cứ ngày một tới gần...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"David Atrakchi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
