INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-loai-vat-mo-coi', 'Những Loài Vật Mồ Côi', 'Born To Be Wild', 'https://phimimg.com/upload/vod/20240128-1/350004fb112679db1f94f367b6a32997.jpg', 'https://phimimg.com/upload/vod/20240128-1/2d1941a6e1b821bcb7a890cca4178f98.jpg', '<p>Born to be Wild là một bộ phim được gợi hướng từ Ngày Thế Giới Bảo Vệ Trái Đất. Được quay theo kỹ thuật 3 chiều và sử dụng màn ảnh rộng IMAX, bộ phim kể lại hoạt động lạ lùng của hai phụ nữ dấn thân cứu những con thú mồ côi có nguy cơ bị diệt chủng: đười ươi ở Borneo và voi ở Kenya. Hai bà đã nuôi dưỡng những con thú mồ côi này và sau đó trả chúng về với hoang dã...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Birute Galdikas","avatar":""},{"name":"Daphne Sheldrick","avatar":""},{"name":"Morgan Freeman","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324470);
