INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-loai-vat-mo-coi', 'Những Loài Vật Mồ Côi', 'Born To Be Wild', 'những loài vật mồ côi born to be wild birute galdikas daphne sheldrick morgan freeman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tru-an', 'Nơi Trú Ẩn', 'Take Shelter', 'https://phimimg.com/upload/vod/20240128-1/e269a39e36edfb9e22a864f795cddc4b.jpg', 'https://phimimg.com/upload/vod/20240128-1/9d1158aec292efc21fa80967a9c2c990.jpg', '<p>Curtis LaForche sống trong một thị trấn nhỏ tại Ohio với vợ Samantha và cô con gái Hannah 6 tuổi bị điếc. Cuộc sống của họ khá vất vả vì chỉ có ông chồng đi làm chính, vợ ở nhà vừa trông con, vừa làm thợ may kiếm thêm thu nhập. Cuối tuần, họ còn ra chợ bán thêm hàng thủ công mỹ nghệ để có tiền lo cho sức khỏe cũng như nhu cầu đặc biệt của Hannah. Mặc dù vậy, gia đình Curtis và Samantha luôn tràn ngập tình yêu và hạnh phúc. Mọi chuyện bắt đầu xáo trộn, khi Curtis có những giấc mơ đáng sợ về cơn bão kì lạ đang đến. Anh lo lắng và ám ảnh đến ngày tận thế nên quyết định xây một nơi trú ẩn tại sân sau nhà họ. Hành vi của Curtis đã đưa cuộc hôn nhân của anh và cả mối quan hệ với đồng nghiệp tại nơi làm việc vào chỗ bế tắc...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Shannon","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Shea Whigham","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
