INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('top-cat-the-movie', 'Top Cat: The Movie', 'Top Cat: The Movie', 'https://phimimg.com/upload/vod/20240127-1/5f3980e1bc05a7202784f2d79e207fbf.jpg', 'https://phimimg.com/upload/vod/20240127-1/d8e5b3ad7573add795117a7deafffd62.jpg', '<p>Có một cảnh sát trưởng mới trong khu phố thất vọng với hiệu suất của Sĩ quan Dibble. Thủ lĩnh và đội quân người máy của ông ta tuyên chiến với Top Cat và băng nhóm mèo hung hãn của ông ta.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2011, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Rául Anaya","avatar":""},{"name":"Jorge Arvizu","avatar":""},{"name":"Mario Castañeda","avatar":""},{"name":"Eduardo Garza","avatar":""},{"name":"Danny Trejo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
