INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-voi-nhung-dua-tre', 'Bạn Thân Với Những Đứa Trẻ', 'Friends With Kids', 'https://phimimg.com/upload/vod/20240126-1/8d3aa2eb9911f4b5f2b41b9a1ee5deef.jpg', 'https://phimimg.com/upload/vod/20240126-1/11269727a45ccfa4b831a687254eaa13.jpg', '<p>Một cặp bạn thân sau khi tham khảo tác động của việc sinh con đối với các cặp vợ chồng cảm thấy hầu hết đều là những tác động xấu. Do đó họ quyết định sẽ có con trước, rồi sau đó sẽ cặp kè với người bạn đời tương lai sau...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Westfeldt","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Maya Rudolph","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
