INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-thang-muoi', 'Đứa Trẻ Tháng Mười', 'October Baby', 'https://phimimg.com/upload/vod/20240123-1/95e1613bd34b627ae804d8b70fb4e782.jpg', 'https://phimimg.com/upload/vod/20240123-1/34b1a4f35d25e1196e49bf5f6fdbff9e.jpg', '<p>BÉ THÁNG 10 là câu chuyện về tuổi mới lớn của một sinh viên năm nhất đại học xinh đẹp và ngây thơ, người phát hiện ra rằng cả cuộc đời mình là dối trá và bắt đầu chuyến hành trình với một loạt những kẻ lạc lối để khám phá bản thân và câu trả lời mà cô ấy khao khát.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel Hendrix","avatar":""},{"name":"Jason Burkey","avatar":""},{"name":"John Schneider","avatar":""},{"name":"Jennifer Price","avatar":""},{"name":"Colleen Trusler","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
