INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nganh-han-2', 'Ngạnh Hán 2', 'The Underdog Knight 2', 'https://phimimg.com/upload/vod/20240123-1/fe6434c2d832e33bf0881c9e5ea2c143.jpg', 'https://phimimg.com/upload/vod/20240123-1/ea429d86fdade7ae4dbdc853d1513a44.jpg', '<p>Bộ phim The Underdog Knight 2 là phần tiếp theo của phim The Underdog Knight được Trung Quốc sản xuất năm 2008. Lưu Diệp vào vai Lão Tam - người bị tổn thương về trí não sau một vụ tai nạn... Lão Tam đảm nhiệm vai trò của một cận vệ chuyên dụng cũng như một cựu thủy thủ hải quân, với trí não bị tổn thương sau khi anh gặp một vụ tai nạn. Rời bỏ quân ngũ, cùng với tài võ nghệ siêu phàm, anh tiếp tục lên đường phiêu lưu tìm và tiêu diệt tội phạm. Trong phần này, Lão Tam sẽ chạm trán một tổ chức tội phạm quốc tế để bảo vệ tài sản quốc gia. Vai diễn người bạn gái xinh đẹp của anh, do Trương Tử Lâm đảm nhiệm, sẽ bị bắt cóc và được người yêu mình giải thoát</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"En-chun Chiao","avatar":""},{"name":"Ye Liu","avatar":""},{"name":"Zilin Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
