INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-co-buong-tay', 'Liệu Có Buông Tay', 'Let Go', 'https://phimimg.com/upload/vod/20240123-1/80a3812b54bfb6a39ee87e48a9804b2b.jpg', 'https://phimimg.com/upload/vod/20240123-1/eb07b8b68d3faa06a66d87abb88904e0.jpg', '<p>Liệu Có Buông Tay - Let Go: Bộ phim xoay quanh cuộc sống đan xen của Disman - một sĩ quan quản chế đang buồn chán với cuộc hôn nhân của mình và hai cựu tù nhân lập dị và 1 cô gái bốc lửa đang bị quản giáo tại địa phương mà anh chịu trách giám sát. Mỗi người đều có vấn đề và quá khứ đeo đẳng, vậy họ có thể buông bỏ quá khứ để sống theo đúng nghĩa hay không?</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"EDWARD ASNER","avatar":""},{"name":"David Denman","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
