INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lieu-co-buong-tay', 'Liệu Có Buông Tay', 'Let Go', 'liệu có buông tay let go kevin hart gillian jacobs edward asner david denman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-phu-thuy', 'Thời Đại Phù Thủy', 'Season Of The Witch', 'https://phimimg.com/upload/vod/20240123-1/0df02a1d86ee69d7549e9348bade6ec2.jpg', 'https://phimimg.com/upload/vod/20240123-1/91ed514c1c35c4a0319403817c1dba3a.jpg', '<p>Thế kỷ 14 là thời gian mà nhân loại bị ám ảnh bởi những lực lượng siêu tự nhiên và sẵn sàng làm bất cứ điều gì để loại bỏ mọi hiểm nguy cho bản thân. Behmen là một chàng trai quả cảm, nhưng niềm tin của anh hoàn toàn vỡ nát sau nhiều năm chinh chiến với tư cách là hiệp sĩ Thập tự chinh. Anh trở lại quê hương của mình trong lòng trung tâm Châu Âu, để rồi đau đớn nhận ra nó đang bị ảnh hưởng bởi cơn dịch bệnh Đen chết người. Liệu tài năng của Behmen có đủ để cứu quê hương mình thoát khỏi cơn bĩ cực?</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Claire Foy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
