INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-thu-tinh-yeu-2011', 'Vườn Thú Tình Yêu', 'Zookeeper', 'https://phimimg.com/upload/vod/20240123-1/afba3745295d99b5b811bc71730f63da.jpg', 'https://phimimg.com/upload/vod/20240123-1/612a66b8d394a9419afe17ae1a926ea2.jpg', '<p>Các loài vật ở sở thú rất yêu quý người quản thú Griffin Kayes, một anh chàng độc thân đáng yêu. Một ngày nọ , anh ta quyết định rời sở thú và để tìm một cuộc sống mới. Khi các loài vật biết được dự định này của Griffin , chúng đã quyết định phá vỡ quy ước của mình để tiết lộ cho anh một bí mật rất lớn. Đó là chúng có thể nói chuyện được. Bên cạnh đó, các con động vật còn chỉ cho anh chàng khờ này cách tiếp cận phái nữ theo bản năng tự nhiên của từng loài, nhằm mục đích giúp Griffin chinh phục được cô gái trong mơ của mình để họ có thể xây dựng một gia đình hạnh phúc...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin James","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Leslie Bibb","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
