INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-xung-tran', 'Anh Hùng Xung Trận', 'Battlefield Heroes', 'https://phimimg.com/upload/vod/20240207-1/149ffd35c66ace018fa754980ba878dc.jpg', 'https://phimimg.com/upload/vod/20240207-1/6d3f67f157fa4ff80057b23c87bbcbe4.jpg', '<p>Bộ phim kể lại những mốc thời gian, khi mà Silla đánh thắng Goguryeo vào năm 668. Trong lịch sử, sau sự tan rã của Cổ Triều Tiên, Hàn Quốc bước vào thời kỳ phân tranh quyền lực mà đỉnh điểm là thời Tam Quốc với 3 nước Silla, Baekje và Goguryeo. Silla, Baekje và Goguryeo là ba Đại Quốc cường mạnh của Hàn Quốc, từ năm 57 trước Công nguyên đến năm 668 sau Công nguyên.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jin-yeong Jeong","avatar":""},{"name":"Mun-shik Lee","avatar":""},{"name":"Ryu Seung-Ryong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
