INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-kich', 'Truy Kích', 'Abduction', 'https://phimimg.com/upload/vod/20240118-1/e2bb46b5cf7b11bbca5e5984c9706185.jpg', 'https://phimimg.com/upload/vod/20240118-1/1eb8c72e92559e96a6fec35b872c839a.jpg', '<p>Truy Kích - Abduction (2011) kể về chàng thiếu niên Nathan Harper. Cậu đang có cuộc sống yên bình cùng cha mẹ cùng mối tình chưa thổ lộ với cô bạn hàng xóm Karen (Lily Collins). Cho đến một ngày, Nathan tình cờ thấy hình ảnh hồi bé của mình trên một trang web tìm người mất tích rồi phát hiện ra những người mình chung sống bao lâu nay không phải cha mẹ đẻ. Một màn truy lùng ráo riết giữa 2 phe CIA và Mafia Nga mà cậu chính là con mồi bùng nổ. Trên đường trốn chạy khỏi việc bị bắt làm con tin, chính bản thân cậu bị cuốn vào cuộc tranh giành dãy số mã hóa bí ẩn.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taylor Lautner","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Alfred Molina","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
