INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-so-4', 'Tôi Là Số 4', 'I Am Number Four', 'https://phimimg.com/upload/vod/20240118-1/9f4ea45c9d2686f9fc2d4416478cfcf0.jpg', 'https://phimimg.com/upload/vod/20240118-1/1a41788a529139e36a2413047334b786.jpg', '<p>John Smith - một chàng trai với năng lực đặc biệt đang trên đường chạy trốn khỏi những kẻ thù độc ác có âm mưu sát hại mình. Liên tục thay đổi thân thế, không ngừng di chuyển từ thành phố này sang thành phố khác cùng người giám hộ Henri, John tưởng như đã không còn mối liên hệ nào với quá khứ. Nhưng tại thị trấn nhỏ Ohio mà giờ đã được gọi là nhà, John bắt đầu vướng phải những sự kiện nằm ngoài dự kiến, có khả năng làm thay đổi số phận của cậu - tiếng sét ái tình đầu đời, những quyền lực mới mẻ và mối liên hệ với những người chia sẻ số phận như mình...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Pettyfer","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Dianna Agron","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
