INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-tinh', 'Săn Tình', 'Sarangi Museoweo', 'https://phimimg.com/upload/vod/20240104-1/d333d10b478fa9cc754ec035a7632763.jpg', 'https://phimimg.com/upload/vod/20240104-1/5e60e9e0d50aa7dc512da3b0a5f48053.jpg', '<p>Tình Dục Là Chuyện nhỏ&nbsp;được biết đến là tựa phim&nbsp;tâm lý hài hước rất hấp dẫn ra mắt lần đầu tiên vào năm 2002, qua nhiều phần khác nhau giờ đây câu chuyện về anh chàng&nbsp;Eun-shik (Im Chang-jung) lại được tiếp tục trong Tình Dục Là Chuyện Nhỏ 4 được ra mắt vào năm 2011 hứa hẹn rất nhiều những tình tiết hài hước mới cũng như nhiều điều mới mẻ, hấp dẫn trong những cuộc tình mà anh này trải qua.&nbsp;&nbsp;Thực tế thì chuyện phim về&nbsp;Eun-shik đã được kết thúc từ phần 2 và Săn Tình là một phần phim hoàn toàn tách biệt nhưng cách dẫn dắt cũng như nam chính là được giữ nguyên.Phim Tình Dục Là Chuyện Nhỏ 4: Săn Tình&nbsp; là câu chuyện hài giữa Sang-yeol và So-yeon</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chang Jung Lim","avatar":""},{"name":"Gyu-ri Kim","avatar":""},{"name":"Tae-hoon Kim","avatar":""},{"name":"Min-Hwan Park","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
