INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('poulet-aux-prunes', 'Poulet Aux Prunes', 'Poulet Aux Prunes', 'https://phimimg.com/upload/vod/20240104-1/8f70e5ef91fcc370ed4fa6ec322ebdae.jpg', 'https://phimimg.com/upload/vod/20240104-1/6bca95d2928997bb51e72adcb5c97666.jpg', '<p>Kể từ khi violin yêu dấu của anh ta bị phá vỡ, Nasser Ali Khan, một trong những nhạc sĩ nổi tiếng nhất trong ngày của mình, đã mất tất cả hương vị cho cuộc sống. Tìm kiếm không có nhạc cụ nào xứng đáng thay thế nó, anh quyết định giam mình vào giường để chờ đợi cái chết.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
