INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-dong-tu-than', 'Hang Động Tử Thần', 'Sanctum', 'https://phimimg.com/upload/vod/20240109-1/26ae82c79a4499e1ad27125cbe2abd41.jpg', 'https://phimimg.com/upload/vod/20240109-1/ae263886858ab13caffb49db5e2c8bd3.jpg', '<p>Phim xoay quanh một đoàn thám hiểm lặn xuống nước khám phá những hang động kỳ vĩ và đẹp nhất của Trái Đất mà chưa nhiều người tìm ra. Khi một cơn bão nhiệt đới đẩy họ xuống sâu dưới các hang động, đoàn thám hiểm phải chống chọi với nước lạnh, địa hình hiểm trở và nỗi sợ hãi bị mắc kẹt lại nơi đây mãi mãi. Trưởng đoàn thám hiểm - thợ lặn Frank McGuire - đã thăm dò hang động Esa-ala ở Nam Thái Bình Dương trong nhiều tháng trời. Tuy nhiên, khi lối thoát bị những dòng nước dữ dội chặn lại, Frank cùng với cậu con trai Josh 17 tuổi và chuyên gia tài chính Carl Hurley buộc phải tính những phương án mới để tìm cách thoát ra ngoài...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rhys Wakefield","avatar":""},{"name":"Allison Cratchley","avatar":""},{"name":"Christopher Baker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
