INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-bua-quyen-nang', 'Chiếc Búa Quyền Năng', 'Almighty Thor', 'https://phimimg.com/upload/vod/20240108-1/4a668e92f6613566669e5866d13c912f.jpg', 'https://phimimg.com/upload/vod/20240108-1/dae69f8f119d750e38d6d31a20efd2fc.jpg', '<p>Loki phá hủy pháo đài Valhalla và đánh cắp Hammer of Invincibility, chỉ có anh hùng trẻ tuổi Thor mới có thể bảo vệ Trái đất khỏi Armageddon.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cody Deal","avatar":""},{"name":"Patricia Velásquez","avatar":""},{"name":"Richard Grieco","avatar":""},{"name":"Kevin Nash","avatar":""},{"name":"Jess Allen","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
