INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-trong-bong-toi', 'Trốn Trong Bóng Tối', 'In Darkness', 'https://phimimg.com/upload/vod/20240108-1/0ced684d9eb7e57067e6cb1e7f1084e5.jpg', 'https://phimimg.com/upload/vod/20240108-1/ee36d14b63e44691d27d5aed11fd4fc7.jpg', '<p>Nội dung phim kể về một tay lừa gạt người Ba Lan sau đó trở thành anh hùng khi bảo vệ người Do Thái khỏi thảm họa diệt chủng, với dàn diễn viên chính là Robert Wieckiewicz, Agnieszka Grochowska và Kinga Preis cùng các diễn viên người Đức khác là Benno Furmann và Maria Schrader. Dựa trên câu chuyện có thực của Leopold Soha (Robert Wieckiewicz), một thanh tra hệ thống thoát nước trong thành phố Lvov của Ba Lan khi Đức quốc xã chiếm đóng. Tình cờ gặp một nhóm người Do Thái đang bị Phát xít Đức truy lùng, thấy đây là một cơ hội ngon ăn nên anh ta đã đồng ý giúp mọi người ẩn nấp với một mức giá béo bở. Ban đầu chỉ là vì những lợi ích của bản thân, sau đó Leopold đã cùng với người bạn của mình và là đồng nghiệp Szczepek Wroblewski mạo hiểm mạng sống của chính mình để giấu và chăm sóc cho những người tị nạn Do Thái suốt 14 tháng trong đường cống ngầm của thành phố dưới sự kiểm soát của quân phát xít...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Robert Więckiewicz","avatar":""},{"name":"Benno Fürmann","avatar":""},{"name":"Agnieszka Grochowska","avatar":""},{"name":"Maria Schrader","avatar":""},{"name":"Herbert Knaup","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
