INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tron-trong-bong-toi', 'Trốn Trong Bóng Tối', 'In Darkness', 'trốn trong bóng tối in darkness robert więckiewicz benno fürmann agnieszka grochowska maria schrader herbert knaup ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-an-do', 'Bố Già Ấn Độ', 'Bbuddah Hoga Terra Baap', 'https://phimimg.com/upload/vod/20240104-1/d661d90a07c7e8dda8ea79a6ef9b58f2.jpg', 'https://phimimg.com/upload/vod/20240104-1/3647b90ecaa08f75d3434ab04c133785.jpg', '<p>Sau một loạt vụ đánh bom ở Mumbai, ACP Karan Malhotra thông báo rằng anh ta sẽ bắt những thủ phạm chịu trách nhiệm trong một khoảng thời gian rất ngắn cũng như cố gắng thuyết phục người yêu thời đại học của anh ta, Tanya P. Nath, kết hôn với anh ta. Sau đó, anh ta bắt đầu thẩm vấn một số nghi phạm đến mức một tên xã hội đen của thế giới ngầm, Kabir, buộc phải thuê một sát thủ để tiêu diệt anh ta. Kẻ giết người tiềm năng, Viju, là một cựu tù nhân lớn tuổi cứng rắn cũng như một cựu xã hội đen, hiện đang điều hành một quán rượu ở Paris, và sẵn sàng giết Karan. Khi bắt đầu thực hiện nhiệm vụ khủng khiếp này, anh tình cờ gặp lại tình cũ, Kamini, cũng như người vợ đã ly thân của mình, Sita - và chính những cuộc gặp gỡ này có thể là bước ngoặt trong cuộc đời này có thể thuyết phục anh rời bỏ bom và Bandooks phía sau và dành phần đời còn lại của mình để cầu nguyện và xem Kênh Bhakti.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Amitabh Bachchan","avatar":""},{"name":"Hema Malini","avatar":""},{"name":"Sonu Sood","avatar":""},{"name":"Sonal Chauhan","avatar":""},{"name":"Prakash Raj","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
