INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vo-dich-luot-van', 'Nhà Vô Địch Lướt Ván', 'Soul Surfer', 'https://phimimg.com/upload/vod/20240102-1/c62e811d95fb726f6feb3fa9dba07157.jpg', 'https://phimimg.com/upload/vod/20240102-1/84f758685e2955449a5756c7825b6f29.jpg', '<p>Câu chuyện có thật về vận động viên lướt sóng tuổi teen Bethany Hamilton, người đã bị mất cánh tay trong một cuộc tấn công của cá mập và đã dũng cảm vượt qua mọi khó khăn để trở thành nhà vô địch một lần nữa, nhờ quyết tâm tuyệt đối và niềm tin vững chắc của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"AnnaSophia Robb","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Carrie Underwood","avatar":""},{"name":"Kevin Sorbo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
