INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-tinh-thu-ba', 'Giới Tính Thứ Ba', 'Tomboy', 'https://phimimg.com/upload/vod/20240102-1/24b48dbf5fb7ed5f5179ef722c02106d.jpg', 'https://phimimg.com/upload/vod/20240102-1/7e8b26357e4e3d5ab0f186f5696e3b4d.jpg', '<p>Một gia đình người Pháp chuyển đến một khu phố mới trong kỳ nghỉ hè. Câu chuyện kể về một đứa trẻ 10 tuổi không phù hợp với giới tính, Laure, người đang thử nghiệm cách thể hiện giới tính của mình, lấy tên là Mikael.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Zoé Héran","avatar":""},{"name":"Malonn Lévana","avatar":""},{"name":"Jeanne Disson","avatar":""},{"name":"Sophie Cattani","avatar":""},{"name":"Mathieu Demy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
