INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-chien-tuyen', 'Đầu Chiến Tuyến', 'The Front Line', 'https://phimimg.com/upload/vod/20240128-1/fa0576ead7e3b2099764c2777164e7cf.jpg', 'https://phimimg.com/upload/vod/20240128-1/2b67e645ceff6ce280843209db1da3ff.jpg', '<p>Phim lấy bối cảnh tại một ngọn đồi mang tính chiến lược có tên Aerok vào năm 1953, ngay trước thềm hiệp định đình chiến, đồng thời cũng là lúc những cuộc đọ súng ở vùng giáp ranh xảy ra ác liệt nhất. The Front Line xoay quanh tình bạn giữa hai người lính Hàn Quốc và Triều Tiên tại một trận địa ác liệt...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha-kyun Shin","avatar":""},{"name":"Soo Go","avatar":""},{"name":"Seung-su Ryu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324470);
