INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-duong-toi-di', 'Chặng Đường Tôi Đi', 'My Way', 'https://phimimg.com/upload/vod/20240102-1/c500f746bed8df1c35f3b10aa3849b57.jpg', 'https://phimimg.com/upload/vod/20240102-1/6f9cb7d3640d2fde0535d4f0abc12909.jpg', '<p>My way xoay quanh câu chuyện về Joon Sik, một người làm công tại trang trại do ông của Tatsuo làm chủ nhưng lại có mơ ước tham gia Thế vận hội Tokyo với tư cách vận động viên marathon. Tatsuo cũng có mục tiêu giống như Joon Sik nên 2 người trở thành đối thủ cạnh tranh của nhau. Chiến tranh nổ ra, cả 2 đều phải gia nhập quân đội. Tatsuo trở thành đội trưởng đơn vị vệ binh của Joon Sik và đã nghĩ ra một kế hoạch tuy nhiên nó đã thất bại. Joon Sik và Tatsuo đều bị quân Xô Viết bắt giam. Họ bỏ trốn nhưng bị quân Đức Quốc Xã bắt và buộc phải chia ly. Đến năm 1944, họ gặp lại nhau tại cuộc chiến Normandy...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Dong-gun Jang","avatar":""},{"name":"Jô Odagiri","avatar":""},{"name":"Bingbing Fan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
