INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-ai-khac-ngoai-anh', 'Không Ai Khác Ngoài Anh', 'Nobody Else But You', 'https://phimimg.com/upload/vod/20240102-1/5818553078164a0baf39fdefeb170316.jpg', 'https://phimimg.com/upload/vod/20240102-1/858634a0b24bb5a474811d64d026fda1.jpg', '<p>Vụ tự sát mơ hồ của một người đẹp địa phương, cô gái dự báo thời tiết, người mẫu phô mai và người trông giống Marilyn Monroe tìm thấy một thám tử háo hức ở David Rousseau, tiểu thuyết gia tội phạm bán chạy nhất. Khi Rousseau đến thăm một ngôi làng hẻo lánh trên dãy Alps để đọc di chúc của bạn mình, ông đã vô tình, nhưng không thể cưỡng lại được, bị cuốn vào mạng lưới giết người rối rắm và chính trị của thị trấn nhỏ trong bí ẩn lạc nhịp này.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Paul Rouve","avatar":""},{"name":"Sophie Quinton","avatar":""},{"name":"Guillaume Gouix","avatar":""},{"name":"Olivier Rabourdin","avatar":""},{"name":"Arsinée Khanjian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
