INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-rong', 'Mộ Rồng', 'Legendary: Tomb Of The Dragon', 'https://phimimg.com/upload/vod/20240126-1/bf401be625d5ae6d2a6aa72b6aa276fa.jpg', 'https://phimimg.com/upload/vod/20240126-1/13f7adc587fc7dfe28840e3b1076ee60.jpg', '<p>Câu chuyện&nbsp;kể về một nhóm người gồm Travis Preston và bạn bè cùng nhau đi đến Trung Quốc để chứng thực sự tồn tại của một loài động vật bí ẩn. Trong Hành trình đó, Travis và đồng đội đã phải trải qua nhiều nguy hiểm để bảo vệ sinh vật bí hiểm này trước tham vọng săn giết của một nhóm kẻ thù khác. Chuyện gì sẽ xảy ra với Travis và đồng đội? Sinh vật kia thật sự là gì?</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Scott Adkins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
