INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-ganh-xiec', 'Chuyện Tình Gánh Xiếc', 'Water For Elephants', 'https://phimimg.com/upload/vod/20231231-1/525039365c9c73e2680e069954102de0.jpg', 'https://phimimg.com/upload/vod/20231231-1/223c474253ef333cee268021558595f9.jpg', '<p>Phim “Water for Elephants” dựa theo cuốn sách cùng tên rất ăn khách của tác giả Sara Gruen, xoay quanh câu chuyện tình lãng mạn bất ngờ một cặp đôi vượt qua những khó khăn, rào cản để đến với nhau. Thế giới họ đang sống tràn ngập những điều khó khăn và thậm chí tình yêu cũng trở thành một thứ xa xỉ mà rất ít người có được. Richard LaGravenese biến cuốn tiểu thuyết thành kịch bản, trong khi Francis Lawrence đóng vai trò đạo diễn của phim.Trong phim, Robert Pattinson vào vai Jacob Jankowski, một sinh viên chuyên ngành thú y. Sau khi cha mẹ anh qua đời trong một tai nạn kinh hoàng, Jacob quyết định bỏ học và trở thành người chăm sóc động vật tại rạp xiếc Benzini Brothers đang “gồng mình” để tồn tại trong cơn đại suy thoái kinh tế.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Paul Schneider","avatar":""},{"name":"Jim Norton","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
