INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-rom-2011', 'Chó Rơm', 'Straw Dogs', 'https://phimimg.com/upload/vod/20231231-1/8599b331a202de87150d58a2f54da260.jpg', 'https://phimimg.com/upload/vod/20231231-1/288a706cd6980a2da90b8ff16e0ce892.jpg', '<p>Nhà biên kịch L.A. David Sumner cùng vợ, Amy, chuyển đến quê hương của cô ở miền Nam sâu thẳm. Ở đó, trong khi căng thẳng gia tăng giữa họ, một cuộc xung đột nảy lửa với người dân địa phương trở thành mối đe dọa cho cả hai.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Marsden","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Dominic Purcell","avatar":""},{"name":"Laz Alonso","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
