INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giay-phut-sinh-tu', 'Giây Phút Sinh Tử', 'Ticking Clock', 'https://phimimg.com/upload/vod/20231230-1/0d60bcd11de133844aee6765e4bf7780.jpg', 'https://phimimg.com/upload/vod/20231230-1/50a410eacfb442db4ceb3acab94ac046.jpg', '<p>Một phóng viên tình cờ đọc được nhật ký của một kẻ sát nhân với kế hoạch giết thịt những cô gái cụ thể, và anh ta bắt đầu tự mình điều tra và phát hiện ra rằng mọi dấu vết đều dẫn đến một đứa trẻ mồ côi 9 tuổi sống trong nhà tập thể.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Austin Abrams","avatar":""},{"name":"Yancey Arias","avatar":""},{"name":"Danielle Nicolet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
