INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-vet-rio', 'Chú Vẹt Rio', 'Rio', 'https://phimimg.com/upload/vod/20231230-1/88283a5ab65341c96d4c7e54be502dde.jpg', 'https://phimimg.com/upload/vod/20231230-1/77e04dc24918d3324a215de87216dfd9.jpg', '<p>Ở Rio de Janeiro, Baby Macaw, Blu, được các đại lý bắt và buôn lậu đến Hoa Kỳ. Trong khi lái xe qua hồ Moose, Minnesota, chiếc xe tải đang vận chuyển blu vô tình rơi vào hộp của blu trên đường. Một cô gái, Linda, tìm con chim và giơ anh ta bằng tình yêu. Mười lăm năm sau, blu là một loài chim thuần hóa và thông minh không bay và sống một cuộc sống thoải mái với chủ sở hữu nhà sách Linda. Ra khỏi Brazil Brazil, Tulio, Tulio, thăm Linda và giải thích rằng Blu là con đực cuối cùng của loài của anh ta, và anh ta có một phụ nữ tên là Jewel ở Rio de Janeiro. Anh mời Linda mang Blu đến Rio để anh và viên ngọc có thể cứu loài của họ. Linda đi với Blu và Tulio đến Rio de Janeiro và họ rời BLU và viên ngọc trong một chiếc lồng lớn trong Viện nơi Tulio hoạt động. Trong khi họ đang ăn tối, những kẻ buôn lậu đột nhập vào Viện và đánh cắp Blu và Jewel để bán chúng. Linda và Tulio nhìn khắp nơi cho BLU, người bị xích vào viên ngọc và ẩn trong một khu ổ chuột. Trong khi đó, viên ngọc và blu thoát khỏi những kẻ bắt giữ và kết bạn với một nhóm những con chim giúp họ thoát khỏi chuỗi. Đó là lễ hội và những kẻ buôn lậu và có nghĩa là cockatoo, Nigel, không có ý định từ bỏ blu và viên ngọc, và đuổi những con chim qua những con đường đông đúc</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
