INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-chuyen-nghiep-2011', 'Sát Thủ Chuyên Nghiệp', 'Killer Elite', 'https://phimimg.com/upload/vod/20231230-1/c6eb28274d464ccc06d274a5d17738d7.jpg', 'https://phimimg.com/upload/vod/20240117-1/a505ae096ced66c0fd36318cc13943c9.jpg', '<p>“Killer Elite” bắt đầu với cuộc ám sát một người đàn ông bí ẩn của một nhóm bao gồm năm sát thủ nguy hiểm: Danny Bryce, Hunter, Davies, và Meier. Một năm sau đó, Danny nghe tin người cố vấn và cũng là người đỡ đầu tinh thần của mình là Hunter đã bị bắt. Danny bắt đầu cuộc hành trình giải cứu Hunter nhưng Danny cũng trở thành con mồi bị săn đuổi. Liệu Danny có giải thoát được Hunter, bảo vệ được mạng sống của chính mình và tìm ra nguyên nhân bí ẩn phía sau vụ truy sát.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Robert De Niro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
