INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-trai-dat-khac', 'Một Trái Đất Khác', 'Another Earth', 'https://phimimg.com/upload/vod/20231219-1/39cc35e1c003892333074bce4fb44f81.jpg', 'https://phimimg.com/upload/vod/20231219-1/12b6690bacf47afc93ab463e91125a04.jpg', '<p>Một Trái Đất Khác xoay quanh việc con người phát hiện phiên bản của Trái Đất. Trong phim Another Earth, Rhoda Williams (Brit Marling), một người phụ nữ trẻ thông minh đã chấp nhận tham gia chương trình vật lý vũ trụ của MIT để thỏa mãn niềm đam mê khao khát được khám phá vũ trụ. Một nhà soạn nhạc xuất sắc, John Burroughs (William Mapother), vừa đạt đến đỉnh cao của nghề nghiệp của mình và sắp có một đứa con thứ hai. Vào đêm khám phá ra một bản sao của trái đất, cuộc sống của những người xa lạ này trở nên gắn bó với nhau không thể thay đổi...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brit Marling","avatar":""},{"name":"William Mapother","avatar":""},{"name":"Matthew-Lee Erlbach","avatar":""},{"name":"Meggan Lennon","avatar":""},{"name":"AJ Diana","avatar":""},{"name":"Kumar Pallana","avatar":""},{"name":"Bruce Colbert","avatar":""},{"name":"Ana Valle","avatar":""},{"name":"Joseph A. Bove","avatar":""},{"name":"Jordan Baker","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
