INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-nang-jane-eyre', 'Chuyện Tình Nàng Jane Eyre', 'Jane Eyre', 'null', 'https://phimimg.com/upload/vod/20230909-1/b637a2b77ae08194123c8075198ec394.jpg', '<p>Câu chuyện về cuộc đời cô gái nhỏ sống ở thế kỷ 19, lớn lên trong bất hạnh, cay nghiệt và luôn nung nấu ý muốn thay đổi số phận. Jane Eyre là mẫu phụ nữ can đảm, khiêm tốn, lương thiện, nhưng đầy kiên định. Vì vậy, đã có quá nhiều vở kịch, bộ phim về Jane Eyre được dàn dựng trong hơn 100 năm qua. Tuy nhiên, bản phim mới nhất Jane Eyre do diễn viên Mia Wasikowska thể hiện vẫn có sự khác biệt lớn, mang đến nhiều cảm xúc gần như những gì mà tiểu thuyết mô tả.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mia Wasikowska","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Valentina Cervi","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Su Elliot","avatar":""},{"name":"Holliday Grainger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
