INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-nang-jane-eyre', 'Chuyện Tình Nàng Jane Eyre', 'Jane Eyre', 'chuyện tình nàng jane eyre jane eyre mia wasikowska michael fassbender jamie bell sally hawkins simon mcburney valentina cervi judi dench su elliot holliday grainger ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vu-an-ky-la', 'Những Vụ Án Kỳ Lạ', 'Twilight Investigation', 'https://phimimg.com/upload/vod/20231219-1/0330fb22b2d59860b049c824a4e5dee9.jpg', 'https://phimimg.com/upload/vod/20231219-1/516cf681f1b76f2de72dfdd9a06e3630.jpg', '<p>Những Vụ Án Kỳ Lạ TVB do điện ảnh Hong Kong sản xuất và được phát sóng trên đài TVB vào năm 2011. Phim có tựa đề tiếng anh là Twilight Investigation và thuộc thể loại tâm lý hình sự. Từ ngày bắt đầu lên sóng, phim đã chiếm được sự tin tưởng và yêu mến từ phía khán giả, đồng thời trở thành một trong những bộ phim truyền hình hay nhất Hong Kong năm 2011.Những Vụ Án Kỳ Lạ do đạo diễn lừng danh La Vĩnh Hiền chỉ đạo nội dung, cùng sự tham gia của dàn diễn viên đình đám gồm nhiều ngôi sao đầu quân cho đài TVB như: Vương Hỷ, Chung Gia Hân, Huỳnh Hạo Nhiên, Lê Nặc Ý, Lương Gia Kỳ, Lý Tư Tiệp,…Nội dung phim Những Vụ Án Kỳ Lạ xoay quanh một cựu cảnh sát điều tra Diệp Quốc Xương. Sau khi nghỉ việc, ông mở một văn phòng thám tử với đam mê điều tra những vụ án hóc búa. Ngay lập tức, có rất nhiều thám tử trẻ tuổi đầu quân cho văn phòng dưới sự chỉ đạo của ông. Tuy mỗi người một kiểu, một tính cách nhưng họ đều rất non kinh nghiệm với những cái tên như ậu nhóc lề mề Chu Gia Thăng, anh chàng Vương Tiểu Hổ tinh ranh và “lão đại” Kỷ An Cư.Trong số họ, mỗi người đều có một tài lẻ riêng cho nên khi hợp nhất lại thành một đội thì văn phòng thám tử này rất đáng gờm. An Cư là cái tên nổi bật nhất với trí tuệ nhạy bén, tính cách cẩn trọng và làm việc một cách khoa học. Dưới sự chỉ đạo của Diệp Quốc Xương, văn phòng thám tử đã phá được rất nhiều vụ án khó và hóc búa. Cảm ơn các bạn đã ủng hộ vuviphim, chúc các bạn xem phim vui vẻ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2011, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Vương Hỷ","avatar":""},{"name":"Chung Gia Hân","avatar":""},{"name":"Huỳnh Hạo Nhiên","avatar":""},{"name":"Lý Tư Tiệp","avatar":""},{"name":"Trần Quốc Bang","avatar":""},{"name":"Chu Tuệ Mẫn","avatar":""},{"name":"Uyển Quỳnh Đan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
