INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phineas-va-ferb-bang-qua-chieu-khong-gian-thu-2', 'Phineas Và Ferb: Băng Qua Chiều Không Gian Thứ 2', 'Phineas And Ferb The Movie: Across The 2nd Dimension', 'https://phimimg.com/upload/vod/20231215-1/9cbcba3a6b6164df1620cb809e6d34b8.jpg', 'https://phimimg.com/upload/vod/20231215-1/c2e0d3760698cea22eed60605ffd93e9.jpg', '<p>Phineas và Ferb bị mắc kẹt trong một chiều không gian khác, nơi Doofenshmirtz siêu xấu xa cai trị Vùng Ba Bang. Họ phải tìm đường trở về nhà với sự giúp đỡ của thú mỏ vịt tên là Perry, người mà họ phát hiện ra là một đặc vụ bí mật.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vincent Martella","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Dan Povenmire","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
