INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-dua-phan-2', 'Trả Đũa (Phần 2)', 'Strike Back (Season 2)', 'https://phimimg.com/upload/vod/20231219-1/b73d06355466962a916cd76e00c228e7.jpg', 'https://phimimg.com/upload/vod/20231219-1/c6a3a718eb48140f6eaadc83a1bf0155.jpg', '<p>Gã trùm khủng bố người Pakistan – Latif lên kế hoạch cho một cuộc tấn công vào các quốc gia Phương Tây với mật hiệu “Project Dawn”. Một lần nữa tổ chức Section 20 được giao nhiệm vụ chặn đứng âm mưu này.Người được lựa chọn không ai khác chính là John Porter, một chiến binh từng trải giàu kinh nghiệm. Tuy nhiên John bị lọt ổ phục kích và các đồng đội phải vào cuộc giúp đỡ anh…</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Amanda Mealing","avatar":""},{"name":"Jimi Mistry","avatar":""},{"name":"Michelle Lukes","avatar":""},{"name":"Philip Winchester","avatar":""},{"name":"Rhashan Stone","avatar":""},{"name":"Sullivan Stapleton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
