INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dem-kinh-hoang', 'Bóng Đêm Kinh Hoàng', 'Fright Night', 'https://phimimg.com/upload/vod/20231213-1/a296fb7f388af7187ef04d90c31b830d.jpg', 'https://phimimg.com/upload/vod/20231213-1/faf1c77e8ebeab264949ecc64c3b69cb.jpg', '<p>Charlie Brewster là fan cuồng của phim kinh dị. Và chẳng hiểu trời “thương” hay “phạt” mà cậu có dịp đối mặt với nỗi kinh hoàng thực sự. Thị trấn nhỏ nơi cậu sinh sống như bị bóng đêm bao trùm bởi những cái chết hàng loạt không rõ nguyên nhân. Tên sát nhân đầy toan tính mãi vẫn chưa lộ diện. Giữa lúc ấy, Charlie phát hiện ra những dấu hiệu lạ từ Jerry - gã hàng xóm điển trai được lòng tất cả mọi người, kể cả mẹ cậu. Mọi bằng chứng đều dẫn đến kết luận duy nhất: Hắn là quái vật ma cà rồng. Nhưng vì không có cách nào chứng minh được điều ấy, Charlie buộc phải lao vào cuộc chiến đơn thương độc mã tiêu diệt con ma cà rồng này...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anton Yelchin","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"David Tennant","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
