INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cau-be-nhut-nhat-luat-cua-rodrick', 'Nhật Ký Cậu Bé Nhút Nhát: Luật Của Rodrick', 'Diary Of A Wimpy Kid: Rodrick Rules', 'https://phimimg.com/upload/vod/20231213-1/e31277a9189f59deabb774c9f956b388.jpg', 'https://phimimg.com/upload/vod/20231213-1/40964f85e7be98161dc34457aef0cb3d.jpg', '<p>Greg Heffley đã trở lại, cùng với những câu chuyện đã xảy ra trong kì nghỉ hè đầu tiên của cậu đã tạo nên cơn sốt Diary of a Wimpy Kid (2007). Lại một lần nữa, thiên ký sự của Greg lần lượt kể ra những rắc rối vui nhộn của một cậu nhóc, với bối cảnh là trường học của Greg, và tập trung vào những trò đùa quái ác của người anh láu cá Rodrick.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zachary Gordon","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Robert Capron","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
