INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-phap-thieu-nu-nanoha-movie-1', 'Ma Pháp Thiếu Nữ Nanoha - Movie 1', 'Magical Girl Lyrical Nanoha: The Movie 1st', 'https://phimimg.com/upload/vod/20231212-1/ab44da11d51d46fc9a4e0cfe677e961c.jpg', 'https://phimimg.com/upload/vod/20231212-1/49f6259ae995fbecefbf4ec08f685e80.jpg', '<p>Ở phần này là sự kiện Jewel Seed và là lần đầu tiên Nanoha có phép. Phim xoay quanh việc Nanoha thu thập và tranh giành Jewel Seed với Fate, đồng thời cũng kể về hoàn cảnh quá khứ của Fate - người mà ai cũng biết là sau này sẽ cùng Nanoha làm cái việc mà ai cũng biết là việc gì rồi...</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
