INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-lech', 'Cặp Đôi Lệch', 'Odd Perfect Match', 'https://phimimg.com/upload/vod/20231219-1/2f18d2e64926d36d0961c806af6a8027.jpg', 'https://phimimg.com/upload/vod/20231219-1/d7c749011587a1c04ca5dbc02713dd5b.jpg', '<p>Hoài Chân - cô gái có sở thích khác người: nhặt lại đồ của người khác bỏ đi. Khai Thái, một người lạnh lùng, thích viết tiểu thuyết. Cả hai ngẫu nhiên là thành viên của “Hội Thất Thư”. Giữa họ sẽ xảy ra chuyện gì? Câu chuyện sẽ diễn biến thế nào khi có người thứ ba xuất hiện?</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 16, 2011, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Cao Dĩ Tường","avatar":""},{"name":"Dương Danh Uy","avatar":""},{"name":"Ngô Á Hinh","avatar":""},{"name":"Tăng Khải Huyền","avatar":""},{"name":"Tiểu Man","avatar":""},{"name":"Trần Chí Khải","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
