INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-danh-cong-ly-2011', 'Nhân Danh Công Lý', 'The Lincoln Lawyer', 'https://phimimg.com/upload/vod/20231211-1/18dc9d25e0a90bf280100ce9e5bb9108.jpg', 'https://phimimg.com/upload/vod/20231211-1/92b5b1964f95a2ea0a81446e35f0aa52.jpg', '<p>Nhân Danh Công Lý kể về một luật sư bào chữa hình sự Mickey Haller hoạt động xung quanh Los Angeles County ra khỏi đen Lincoln Town Car . Haller đã dành phần lớn sự nghiệp của mình bảo vệ bọn tội phạm khu vườn đa dạng, bao gồm cả một địa phương biker băng đảng do Eddie Vogel, nhưng một ngày một vụ cao cấp đi theo cách của mình. Haller được thuê để đại diện cho Louis Roulet giàu, một Beverly Hills ăn chơi và con trai của ông trùm bất động sản Mary Windsor, người bị cáo buộc đánh đập tàn bạo của cô gái điếm Regina Campo.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Josh Lucas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
