INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-xa-em-dem-nay', 'Đừng Xa Em Đêm Nay', 'Take Me Home Tonight', 'https://phimimg.com/upload/vod/20231211-1/cdcb7d63ba933adb327811c1b66103b2.jpg', 'https://phimimg.com/upload/vod/20231211-1/e97b8641813eeb5c5f418476fb8fdb77.jpg', '<p>Matt Franklin, sinh viên tốt nghiệp MIT gần đây, lẽ ra đang trên đường đến với sự nghiệp thành công tại một công ty nằm trong danh sách Fortune 500, nhưng thay vào đó, anh lại nổi loạn chống lại sự trưởng thành bằng cách nhận một công việc tại một cửa hàng video. Matt cân nhắc lại quan điểm của mình khi mối tình đơn phương thời trung học của anh, Tori, bước vào và mời anh dự tiệc cuối hè. Với sự giúp đỡ của người chị song sinh và người bạn thân nhất, Matt ấp ủ một kế hoạch thay đổi cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Topher Grace","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Michelle Trachtenberg","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
