INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-tim-chim-quy', 'Săn Tìm Chim Quý', 'The Big Year', 'https://phimimg.com/upload/vod/20231211-1/b8985cbc4965851124855a59efec8d5e.jpg', 'https://phimimg.com/upload/vod/20231211-1/ed56cd5c2f83095a966822ce4010607d.jpg', '<p>The Big Year xoay quanh 3 người đàn ông đã dành hẳn 1 năm nghỉ ngơi để theo đuổi giấc mơ của mình, sau khi quá mệt mỏi với những nghĩa vụ và trách nhiệm. Cả 3 bước vào cuộc thử thách săn tìm những loài chim quí hiếm nhất tại Bắc Mỹ. Cuộc tranh đua cũng mang ý nghĩa biểu tượng cho những thách thức mà mỗi người phải đối mặt trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Steve Martin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
