INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-song-trong-toi', 'Tôi Sống Trong Tôi', 'The Skin I Live In', 'https://phimimg.com/upload/vod/20231211-1/7895c05a61c90ed372f84e0b7921f4a0.jpg', 'https://phimimg.com/upload/vod/20231211-1/144d817bc991d3d8e9d4db480d5b97a2.jpg', '<p>Để vinh danh người vợ quá cố, người đã chết trong một tai nạn xe hơi rực lửa, nhà khoa học, Tiến sĩ Robert Ledgard, đang cố gắng tổng hợp làn da hoàn hảo có thể chịu được vết bỏng, cắt giảm hoặc bất kỳ loại thiệt hại nào khác. Khi anh ta đến gần hơn để hoàn thiện làn da này trên bệnh nhân hoàn hảo của mình, cộng đồng khoa học bắt đầu phát triển hoài nghi và quá khứ của anh ta được tiết lộ cho thấy bệnh nhân của anh ta được liên kết chặt chẽ với các sự kiện bi thảm mà anh ta muốn quên đi như thế nào.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
