INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thach-thuc-dang-may-rau', 'Thách Thức Đấng Mày Râu', 'Hall Pass', 'https://phimimg.com/upload/vod/20231212-1/c4b4799e27dd963a41940facc344d20c.jpg', 'https://phimimg.com/upload/vod/20231212-1/8ff6a5807db74f244528b024525612b6.jpg', '<p>Rick và Fred là đôi bạn thân. Giữa họ có rất nhiều điểm chung, bao gồm cả việc họ đã kết hôn nhiều năm. Nhưng khi cả hai bắt đầu có biểu hiện chán nản khi ở nhà thì hai bà vợ của cả hai quyết định cho hai ông chồng 1 tuần tự do làm những gì mình muốn. Họ sẽ không theo dõi, không vặn hỏi để hai ông chồng thoải mái hơn. Nghe như giấc mơ bấy lâu nay của cả hai chàng đã thành sự thật. Nhưng giấc mơ đó thật ngắn ngủi bởi vì họ nhanh chóng nhận ra đâu mới là hạnh phúc đích thực của cuộc đời mình...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Christina Applegate","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324470);
