INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-thu-sieu-pham', 'Cung Thủ Siêu Phàm', 'War Of The Arrows', 'https://phimimg.com/upload/vod/20231211-1/a51487c359dfbc95cf19cef0763f45d6.jpg', 'https://phimimg.com/upload/vod/20231211-1/aadb17eb61724c75bc52295cd6d1a447.jpg', '<p>Nam-Yi là một thiện xạ khó ai sánh bằng. Anh sống để bảo vệ cô em gái Ja-In, như lời hứa danh dự với cha. Khi em gái mình quyết định kết hôn, anh tin rằng Ja-In đã tìm được hạnh phúc thực sự. Tuy nhiên vào ngày cưới, ngôi làng của họ bị đội quân Mãn Châu tấn công. Cô dâu, chú rể và cả những người dân trong làng đều bị bắt đi.Với cây cung cha để lại, Nam-Yi quyết tâm truy đuổi đến cùng để giải cứu em gái.Nam-Yi lần lượt tiêu diệt từng tên lính tinh nhuệ của kẻ thù. Thủ lĩnh quân Mãn Châu Jyusinta ngay lập tức nhận ra tài năng của Nam-Yi và truy đuổi anh, nhằm bảo vệ hoàng tử và người của mình. Nam-Yi với tài bắn cung lượn sóng và Jyusinta với những mũi tên có sức sát thương kinh hồn sẽ đối mặt với nhau như thế nào để bảo vệ những điều quý giá nhất?</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon Chae Won","avatar":""},{"name":"Park Hae Il","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Kim Moo Yul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324470);
