INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-menh-kim', 'Đoạt Mệnh Kim', 'Life Without Principle', 'https://phimimg.com/upload/vod/20231211-1/4e654461bb7624ceb8e3fa1000f1e1df.jpg', 'https://phimimg.com/upload/vod/20231211-1/80bc1788af705fb1d2078e7adfe62991.jpg', '<p>Đoạt mệnh kim là câu chuyện về những số phận khác nhau của 3 con người hoàn toàn khác nhau, điểm chung duy nhất của họ là đều cần tiền. Một người là vị thanh tra cảnh sát đáng kính phải trả nợ cho hợp đồng mua nhà mà vợ mình đã ký. Một người là nhân viên ngân hàng phải chịu trách nhiệm cho một khoản đầu tư rủi ro. Và một người là tay lưu manh hạng xoàng, sống bằng nghề lừa gạt và cướp bóc muốn thử vận may của bản thân bằng cờ bạc. Cả 3 con người đó đều sống trong một xã hội bị ám ảnh bởi đồng tiền. Họ gắn kết với nhau bởi một món tiền trị giá 5 triệu đô. Một món tiền không quá lớn nhưng cũng không hề nhỏ đối với những con người đang cần tiền. Cả 3 sẽ làm gì khi đứng trước sự cám dỗ của đồng tiền? Họ sẽ phải trả giá gì để có được khoản tiền đó? Và cuối cùng ai sẽ là người chiến thắng? Tất cả đều nằm trong bộ phim đầy kịch tính này của đạo diễn Đỗ Kỳ Phong.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Richie Jen","avatar":""},{"name":"Lau Ching-wan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
