INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tu-than', 'Trò Chơi Tử Thần', 'Game Of Death', 'https://phimimg.com/upload/vod/20231211-1/43bb9093d7d622f9c2cef1ecd2744a8f.jpg', 'https://phimimg.com/upload/vod/20231211-1/5a5745f53d08fe703814f983feba1abf.jpg', '<p>Vệ sĩ của một nhà ngoại giao và một số người khác bị thương trong một vụ ám sát bất thành. Tất cả họ đều được đưa đến cùng một bệnh viện, nơi vệ sĩ hợp tác với một y tá để bảo vệ nhà ngoại giao khỏi một đội sát thủ máu lạnh. Nhưng nữ y tá biết rằng có nhiều âm mưu đang diễn ra hơn nhiều hơn những gì đang diễn ra trước mắt.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Gary Daniels","avatar":""},{"name":"Wesley Snipes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
