INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-nhat-ky-ki-la', 'Cuốn Nhật Ký Kì Lạ', 'The Rum Diary', 'https://phimimg.com/upload/vod/20231211-1/002f3780c98febe43dddc9da442e161c.jpg', 'https://phimimg.com/upload/vod/20231211-1/fe418457f50ced66983d541be8b99c0f.jpg', '<p>Câu chuyện bắt đầu trong bối cảnh những năm 1960, tại San Juan, Puerto Rico, nơi Paul Kemp (tên khác của Hunter S. Thompson) bắt đầu làm việc với một tạp chí nghèo nàn phục vụ cho khách du lịch Mỹ. Cuộc đời của anh chàng từ đây bắt đầu phải đối mặt với sự phản bội và đố kị, những cuộc tình đan xen lẫn nhau - những mặt trái của những người chủ bút trong tòa báo được phơi bày qua bộ phim một cách hài hước và kịch tính.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Aaron Eckhart","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324470);
