INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ben-kia', 'Thế Giới Bên Kia', 'Hereafter', 'https://phimimg.com/upload/vod/20231211-1/451fdd8a056c02cbd6f6c332d8747ba5.jpg', 'https://phimimg.com/upload/vod/20231211-1/67857c797b1dba9400c3b02b1d58d187.jpg', '<p>Hereafter kể về câu chuyện của ba người luôn bị ám ảnh bởi những cái chết bằng nhiều cách khác nhau. George-Matt Damon , một công nhân Mỹ có khả năng kết nối đến thế giới bên kia. Còn ở Pháp, Marie-Cécile de France, một người dẫn chương trình truyền hình Pháp, từng sống sót trong vụ sóng thần ở Châu Á. Còn Marcus, một cậu học sinh London thì đi tìm kiếm câu trả lời về cái chết của người anh trai song sinh. Mỗi người có một con đường tìm kiếm câu trả lời nhưng cuộc sống của họ mãi mãi thay đổi vì họ tin rằng có sự tồn tại trong thế giới bên kia...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Cécile De France","avatar":""},{"name":"Bryce Dallas Howard","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
