INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-nha-di-thoi', 'Về Nhà Đi Thôi', 'Way Back Home', 'https://phimimg.com/upload/vod/20231211-1/1d0e00f830a363bca6c5910efc81a873.jpg', 'https://phimimg.com/upload/vod/20231211-1/fa39c4cd58cfa31a5f21c2edcb990331.jpg', '<p>Trong suốt 12 năm qua, Jessica Santiagio luôn phải đối mặt với nỗi đau và cảm giác tội lỗi khi để lạc mất em gái Joanna. Jessica nỗ lực để làm hài lòng mẹ, nhưng bà chỉ luôn mong nhớ về Joanna. Sau nhiều năm lưu lạc và được một người ngư dân tốt bụng nuôi nấng, Joanna trở về nhà và như một sợi dây kết nối nhà Santiagio lại với nhau. Thế nhưng sự ganh tị giữa hai chị em gái đã khiến gia đình họ có nguy cơ chia rẽ một lần nữa.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Thuyết Minh', 'HD', 'Philippines', 0, '[{"name":"Kathryn Bernardo","avatar":""},{"name":"Julia Montes","avatar":""},{"name":"Enrique Gi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
