INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('127-gio-sinh-tu', '127 Giờ Sinh Tử', '127 Hours', 'https://phimimg.com/upload/vod/20231211-1/b3c70888ad69ef72806c94552ee43cac.jpg', 'https://phimimg.com/upload/vod/20231211-1/3e39a9662bcc8953be1c8046a56edd36.jpg', '<p>Bộ phim kể về Aron Ralston, một nhà leo núi chuyên nghiệp. Anh bắt đầu một ngày mới bằng một tinh thần đầy phấn chấn và thực hiện cuộc hành trình của mình đến một hẻm núi cô lập tại Utah. Tuy nhiên, ngày mới của anh đã bất ngờ xoay chuyển 180 độ sau khi Aron bị một tai nạn: một tảng đá rơi và kẹp chặt cánh tay của anh vào vách núi, buộc anh treo lơ lửng trong một hẻm núi bị cô lập tại Utah. Tiếp theo sau đó, là những khoảnh khắc đầy cảm động, vui tươi, phấn khích và cả lãng mạn trong cuộc sống của Aron qua những hồi tưởng của anh khi bị treo trên vách núi. Anh tự hỏi, liệu có phải chính các cô là những người cuối cùng anh gặp trong cuộc sống của mình...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Amber Tamblyn","avatar":""},{"name":"Kate Mara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
