INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nac-danh', 'Nặc Danh', 'Anonymous', 'https://phimimg.com/upload/vod/20231211-1/3f6e255166e3d420e1c900a12372e0a9.jpg', 'https://phimimg.com/upload/vod/20231211-1/bf5c982272224b3c17665900c7790875.jpg', '<p>Anonymous là bộ phim dựng lên với một giả thuyết khiến mọi người phải thay đổi hẳn cách nhìn về Shakespeare: chính Edward De Vere, bá tước vùng Oxford là người đã viết lên những vở kịch dưới bút danh Shakespeare còn William Shakespeare chỉ là kẻ lợi dụng cơ hội và một người đứng ra làm bia cho bá tước Edward trong những vở kịch đầy tính chính trị của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Campbell Bower","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Vanessa Redgrave","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
