INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nac-danh', 'Nặc Danh', 'Anonymous', 'nặc danh anonymous jamie campbell bower rhys ifans david thewlis joely richardson vanessa redgrave ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-ve-nhung-co-gai-diem-cua-toi', 'Hồi Ức Về Những Cô Gái Điếm Của Tôi', 'Memoria De Mis Putas Tristes', 'https://phimimg.com/upload/vod/20231211-1/c55946cc330e22c946a7a97384f68411.jpg', 'https://phimimg.com/upload/vod/20231211-1/a48040b451d49a8c0a47b77772f1ebc5.jpg', '<p>Để kỷ niệm sinh nhật lần thứ 90 của mình, một nhà báo già độc thân, Sabio, quyết định tự thưởng cho mình một đêm ân ái mãnh liệt với một thiếu nữ còn trinh. Rosa Cabarcas, người bạn cũ của anh ta với tư cách là một bà chủ nhà chứa, đã sắp xếp cho anh ta một phụ nữ trẻ lý tưởng, Delgadina, một công nhân nhà máy, người đã bán trinh tiết của mình để nuôi gia đình, nhưng khi nhìn thấy cô ấy đang ngủ như một thiên thần, anh ta mất hứng thú với thú vui trong sáng và đem lòng yêu với cô ấy. Tình yêu đó không có nghĩa là có thật, nhưng số phận thay đổi, và hy vọng đó được sinh ra từ một cơ hội cho tình yêu không kiềm chế.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Emilio Echevarría","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Ángela Molina","avatar":""},{"name":"Olivia Molina","avatar":""},{"name":"Dominika Paleta","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
