INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-mon-nu-tuong', 'Dương Môn Nữ Tướng', 'Legendary Amazons', 'https://phimimg.com/upload/vod/20231210-1/8eca1df30ee0d0e02aa0128842848ccc.jpg', 'https://phimimg.com/upload/vod/20231210-1/3a671cd3ce250ab7090c17b660878be0.jpg', '<p>Phim lấy bối cảnh Trung Quốc đầu thế kỷ 11 dưới thời trị vì của Hoàng đế Renzong nhà Tống. Hoàng đế bỏ bê quốc sự và chìm đắm trong những thú vui cá nhân, trong khi chính phủ chìm trong tham nhũng và chiến tranh tiếp tục hoành hành ở biên giới của nhà Tống. Triều đại nhà Tống đang bị xâm lược bởi quân đội của quốc gia đối địch Tây Hạ. Yang Zongbao là người đàn ông cuối cùng còn trụ lại trong gia tộc Yang, một gia đình gồm các tướng lĩnh đã cống hiến cả cuộc đời để bảo vệ nhà Tống khỏi quân xâm lược nước ngoài. Anh ta dường như đã chết trong trận chiến một cách bi thảm khi Gia sư Hoàng gia phản bội Pang từ chối gửi quân tiếp viện để hỗ trợ anh ta. Người vợ góa bụa của Yang Zongbao, Mu Guiying, dẫn đầu các góa phụ khác của gia tộc Yang vào trận chiến để tiếp tục di sản của chồng họ.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cecilia Cheung","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Cheng Pei-Pei","avatar":""},{"name":"Ge Chun-Yan","avatar":""},{"name":"Yukari Ôshima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324470);
