INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cho-dem', 'Anh Hùng Chợ Đêm', 'Night Market Hero', 'https://phimimg.com/upload/vod/20231231-1/5d6338b09f1e7aeaa62a6c2c6b5274df.jpg', 'https://phimimg.com/upload/vod/20231231-1/1a832a411d272488b416232979fdd838.jpg', '<p>Night Market Hero xoay quanh một nhóm người bán hàng tại khu chợ đêm hư cấu Bát Bát Bát, cuộc sống của họ tấp nập với những ganh đua về ẩm thực và tranh chấp về những vấn đề có vẻ như chẳng có gì to tát. Nhưng những cuộc tranh chấp nội bộ của họ giảm bớt khi họ phát hiện ra các chính khách địa phương và các chuyên viên bất động sản muốn đá họ ra khỏi mảnh đất mà nhiều người trong số đó đã sinh sống hơn một thập kỷ. Cuối cùng những người bán hàng này tập hợp lại với nhau để cứu ngôi chợ...</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Cheng Pin Chao","avatar":""},{"name":"Chu-Sheng Chen","avatar":""},{"name":"Guang Yao Fan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
