INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chac-la-noi-nay', 'Chắc Là Nơi Này', 'This Must Be The Place', 'https://phimimg.com/upload/vod/20231231-1/f41274f69b0f7660cc45d0e35f844046.jpg', 'https://phimimg.com/upload/vod/20231231-1/b0dd1469973a218aedd7815db47a1103.jpg', '<p>Một ngôi sao nhạc rock đã nghỉ hưu buồn chán bắt đầu tìm kiếm kẻ hành hạ cha mình, một cựu tội phạm chiến tranh của Đức Quốc xã đang tị nạn ở Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Johnny Ward","avatar":""},{"name":"Eve Hewson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
