INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-tinh-33-ngay', 'Thất Tình 33 Ngày', 'Love Is Not Blind', 'https://phimimg.com/upload/vod/20231231-1/e634df313e10248f6d87d6a8a86d0283.jpg', 'https://phimimg.com/upload/vod/20231231-1/b63891ac9dfb1db10f006ea9d3e4cfda.jpg', '<p>Phim kể về Hoàng Tiểu Tiên, 27 tuổi, làm việc trong một công ty chuyên tổ chức đám cưới. Bề ngoài bình thường, hoàn cảnh gia đình bình thường, thứ duy nhất nắm chắc trong tay là một cái miệng cay nghiệt. Cô rất lạc quan với cuộc sống của mình. Có một tình yêu đã kéo dài 7 năm nhưng vẫn chưa “ tu thành chính quả”, đã thế vô tình nhìn thấy bạn trai tay trong tay thân mật với bạn thân nhất của mình. Từ đây, những ngày thất tình đã đến với cô, và khi tâm hồn của người mới thất tình đem đi làm thì đã xảy ra nhiều chuyện khiến cho cảnh ngộ của cô càng gió thảm mưa sầu. Đồng nghiệp của cô là Vương Tiểu Tiện, là một người vừa cay nghiệt vừa độc mồm độc miệng mà cô nhận xét anh ta là một Gay chính hiệu. Liệu những ngày thất tình của Hoàng Tiểu Tiên có kết thúc suôn sẻ...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Wen","avatar":""},{"name":"Baihe Bai","avatar":""},{"name":"Jia-yi Zhang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
