INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-thien-duong', 'Nụ Hôn Thiên Đường', 'Paradise Kiss', 'https://phimimg.com/upload/vod/20231211-1/eb550ff42c5a5ca94eda7f83d3a189f5.jpg', 'https://phimimg.com/upload/vod/20231211-1/56d33fbb5fd0f289997442b81b9d3519.jpg', '<p>Hyasaka Yukari chỉ muốn một điều: vào trường đại học mà mẹ cô muốn. Một ngày nọ, cô gặp một nhóm ngông cuồng yêu thích thời trang. Họ đang tìm kiếm một hình mẫu và Yukari phù hợp với hình mẫu lý tưởng của họ. Từ bây giờ Yukari sẽ biết thế giới thời trang và người mẫu cũng như những gì cô ấy thực sự muốn.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Keiko Kitagawa","avatar":""},{"name":"Osamu Mukai","avatar":""},{"name":"Aya Omasa","avatar":""},{"name":"Shunji Igarashi","avatar":""},{"name":"Kento Kaku","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
