INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-canh-sat', 'Lực Lượng Cảnh Sát', 'The Guard', 'https://phimimg.com/upload/vod/20231211-1/dc1e19aaa77847e6831d08adb8cb2d37.jpg', 'https://phimimg.com/upload/vod/20231211-1/48e0d784f90d8d9c8c888c5d6092cd35.jpg', '<p>Trung sĩ Gerry Boyle là một cảnh sát thị trấn nhỏ ở Ailen với một tính cách đối đầu, hợp tác với một nhân viên FBI căng thẳng để điều tra một đường dây buôn lậu ma túy quốc tế.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Gleeson","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Katarina Čas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
