INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-giang-sinh-cua-ma-mut', 'Kỷ Băng Hà: Giáng Sinh Của Ma Mút', 'Ice Age: A Mammoth Christmas', 'https://phimimg.com/upload/vod/20231211-1/109a062f134cb0f8f50a6be82e73e62e.jpg', 'https://phimimg.com/upload/vod/20231211-1/d638bc53d2d0597686ccb5a30e45e1ab.jpg', '<p>Khi Sid vô tình phá hủy Rock Christmom của Manny và kết thúc danh sách nghịch ngợm của ông già Noel, anh ta dẫn đầu một nhiệm vụ vui nhộn đến Bắc Cực để làm cho mọi thứ đúng và kết thúc làm mọi thứ tồi tệ hơn nhiều. Bây giờ nó tùy thuộc vào Manny và Posse thời tiền sử của anh ấy để cùng nhau cứu nhau và cứu Giáng sinh cho cả thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
