INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-trieu-den', 'Thủy Triều Đen', 'Dark Tide', 'https://phimimg.com/upload/vod/20231209-1/42858852fb74c1df9ed41d02060ffa0b.jpg', 'https://phimimg.com/upload/vod/20231209-1/75d0d7320c6cd3c6c8e6efe3709eb388.jpg', '<p>Trong phim Dark Tide, Halle Berry thủ vai một huấn luyện viên lặn tên Sara, người đã sống sót sau một tai nạn kinh hoàng khi bị tấn công bởi cá mập. Sara phải đối mặt với một quyết định vô cùng khó khăn, đó là quay trở lại mặt nước và chiến đấu với những “hung thần biển cả” này. Người đẹp 44 tuổi sẽ xuất hiện với một bộ bikini và chiến đấu với một con cá mập trắng khổng lồ trong những cảnh quay vô cùng hồi hộp và gay cấn được thực hiện tại False Bay (Nam Phi).</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Halle Berry","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Ralph Brown","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
