INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sector-7', 'Sector 7', 'Sector 7', 'https://phimimg.com/upload/vod/20231209-1/c073286dba55274aaf43f88a1027ba12.jpg', 'https://phimimg.com/upload/vod/20231209-1/2397155ae495bbde62e024ec4c0c0da7.jpg', '<p>Ở Sector 7, một mỏ dầu dưới nước nằm ở phía nam đảo Jeju, Hae-jun đang làm quản lý thiết bị hàng hải trên một con tàu thăm dò dầu tên là Eclipse. Gia nhập thủy thủ đoàn sau đó là Jeong-man, một đồng nghiệp cũ của cha Hae-jun, được bổ nhiệm làm thuyền trưởng cho Eclipse. Mặc dù công việc của anh ấy là giám sát việc rút tàu, nhưng anh ấy đề nghị tiến hành khoan lần cuối.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji-won","avatar":""},{"name":"Oh Ji-ho","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Song Sae-byuk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
