INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dao-bat-khuat', 'Hòn Đảo Bất Khuất', 'Rebellion', 'https://phimimg.com/upload/vod/20231210-1/05f6aa6031f7d4207d4f2306aa055dbf.jpg', 'https://phimimg.com/upload/vod/20231210-1/0a4e9118869264d743c7a37315cbf37a.jpg', '<p>Tháng 4 năm 1988, Đảo Ouvéa, New Caledonia. 30 hiến binh bị một nhóm chiến binh tự do Kanak bắt làm con tin. 300 binh sĩ được gửi từ Pháp để thiết lập lại trật tự. 2 người đàn ông đối đầu nhau: Philippe Legorjus, trưởng nhóm khủng bố, và Alphonse Dianoou, trưởng nhóm bắt cóc. Thông qua các giá trị được chia sẻ của họ, họ sẽ cố gắng làm cho cuộc thảo luận thành công. Tuy nhiên, giữa cuộc bầu cử tổng thống, khi các vấn đề thuộc về chính trị, trật tự không phải lúc nào cũng do đạo đức quyết định. Một sử thi đầy bạo lực và rắc rối đánh dấu sự trở lại của Mathieu Kassovitz trước và sau máy quay.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Mathieu Kassovitz","avatar":""},{"name":"Iabe Lapacas","avatar":""},{"name":"Malik Zidi","avatar":""},{"name":"Alexandre Steiger","avatar":""},{"name":"Daniel Martin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
