INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-mon-yen', 'Hồng Môn Yến', 'White Vengeance', 'https://phimimg.com/upload/vod/20231210-1/bdd2fd175c4c6db1e03e1ecebb91e97f.jpg', 'https://phimimg.com/upload/vod/20231210-1/7057d9ba7c12b062847aedbac3509417.jpg', '<p>Dựa vào những sự kiện xảy ra năm 206 trước Công Nguyên, bộ phim miêu tả cận cảnh 2 sự kiện nổi tiếng nhất của thời Hán - Sở tranh hùng: Buổi tiệc Hồng Môn và Bá Vương biệt cơ. Một bên là màn đấu trí, đấu dũng nghẹt thở giữa các đấng nam nhi. Một bên là khúc nhạc biệt ly đầy đau thương, xót xa. Tất cả cùng hòa quyện, tạo nên một thời kỳ lịch sử - một thiên anh hùng ca đầy bi tráng.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shaofeng Feng","avatar":""},{"name":"Lê Minh","avatar":""},{"name":"Hanyu Zhang","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
