INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('conan-nguoi-hung-man-di', 'Conan - Người Hùng Man Di', 'Conan The Barbarian', 'https://phimimg.com/upload/vod/20231210-1/0dc870fa62069dc6d8e756f5de10248d.jpg', 'https://phimimg.com/upload/vod/20231210-1/82376c9dd3dd1309a5d631574997bace.jpg', '<p>Conan - chiến binh dũng cảm người man di - trỗi dậy để bảo vệ con dân Hyboria sau khi các thế lực tà ác tàn sát gia đình và người làng của anh.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Momoa","avatar":""},{"name":"Rachel Nichols","avatar":""},{"name":"Stephen Lang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
