INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-dac-nhiem', 'Lực Lượng Đặc Nhiệm', 'Special Forces', 'https://phimimg.com/upload/vod/20231210-1/897b37ddb746b22ee1b13b31c77a5d93.jpg', 'https://phimimg.com/upload/vod/20231210-1/5d84fd850d032d21c7ee6f277f64eb43.jpg', '<p>Nội dung kể về Một nhà báo trẻ Pháp bị bắt cóc tại Afghanistan do Taliban thực hiện. Chính phủ Pháp từ chối tuân theo các điều kiện của những kẻ bắt cóc. Sau đó, Taliban đăng trên Internet video đếm ngược đến cái chết của cô. Để giải cứu các cô gái gửi đến một đội hình tinh nhuệ của lực lượng đặc biệt Pháp...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Diane Kruger","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Benoît Magimel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
