INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-nhi-4-ke-cap-thoi-gian', 'Điệp Viên Nhí 4: Kẻ Cắp Thời Gian', 'Spy Kids: All The Time In The World In 4D', 'https://phimimg.com/upload/vod/20231210-1/669c9f150649315fe2355596d69096f5.jpg', 'https://phimimg.com/upload/vod/20231210-1/adea29a1ec1a73594dc275f70319b36f.jpg', '<p>Nhìn bề ngoài, Marissa Cortez Wilson có tất cả mọi thứ... vừa cưới được một phóng viên truyền hình chuyên săn tin điệp viên rất nổi tiếng, vừa có một đứa con mới sinh và một cặp sinh đôi thông minh con của chồng. Nhưng thực ra, mặc cho mọi cố gắng để làm mẹ của cô, Rebecca và Cecil không muốn cô ở bên cạnh và chúng luôn là thử thách khó khăn nhất đối với Marissa. Ngoài ra, chồng của cô, Wilbur không biết rằng Marissa là một điệp viên bí mật đã nghỉ hưu...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Alba","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Joel McHale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
