INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-em-fbi-3-cha-nao-con-nay', 'Vú Em FBI 3: Cha Nào Con Nấy', 'Big Momma''s 3: Like Father, Like Son', 'https://phimimg.com/upload/vod/20231210-1/ba375e68f748504e696d0fc1667b78cf.jpg', 'https://phimimg.com/upload/vod/20231210-1/f0df38891c76f5adaba402f677006571.jpg', '<p>Một phi vụ giết người đã xảy ra trong trường đào tạo nghệ thuật dành cho nữ sinh và Trent tình cờ là nhân chứng sống. Để tìm ra thủ phạm và bảo vệ con trai, chàng điệp viên chìm FBI Malcome bắt Trent cải trang thành một Cô nàng Bé bự cùng Big Momma xâm nhập vào ngôi trường toàn nữ sinh ấy... Liệu bộ đôi “cha nào con nấy” có giành thắng lợi không?</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Lawrence","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Jessica Lucas","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
