INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-sung-cong-ly', 'Họng Súng Công Lý', 'Machine Gun Preacher', 'https://phimimg.com/upload/vod/20231208-1/65b5631b518ea8669832a8c8e651ae9a.jpg', 'https://phimimg.com/upload/vod/20231208-1/855ee246306a667a7be81545e3274acc.jpg', '<p>Rũ bỏ quá khứ phạm tội, Sam Childers tìm đến Đông Phi để góp sức tái thiết lại cuộc sống nơi đây sau cuộc nội chiến. Tại Sudan, Sam tìm thấy niềm tin từ chính trẻ em bản xứ. Đồng thời, anh đã phát hiện hàng loạt cuộc bắt cóc trẻ em nhằm mục đích quân sự, do tổ chức khủng bố LRA cầm đầu. Sam phải đứng trước hai chọn lựa: nghe theo dân chúng phớt lờ hành vi bắt cóc, hay đứng lên kêu gọi sự đấu tranh giải thóat trẻ em vô tội...</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Michael Shannon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
