INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-giac', 'Tỉnh Giấc', 'The Awakening', 'https://phimimg.com/upload/vod/20231209-1/1a545d2098c67a9da3847fbe7ab442a4.jpg', 'https://phimimg.com/upload/vod/20231209-1/052d4e2c29bdc22cf70e650cbe05acca.jpg', '<p>Ở nước Anh thời hậu Chiến tranh, một nhà văn và đôi khi là thợ săn ma điều tra một vụ ám ảnh được báo cáo tại một trường nội trú nam sinh.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rebecca Hall","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Isaac Hempstead-Wright","avatar":""},{"name":"Lucy Cohu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
