INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-noi-thi-ve', 'Đại Nội Thị Vệ', 'The Life And Times Of A Sentinel', 'https://phimimg.com/upload/vod/20231207-1/d42d37bae475973bd664c775b1a5f0ce.jpg', 'https://phimimg.com/upload/vod/20231207-1/b171bbd18d346b91d9ab22039ca3d447.jpg', '<p>Đại Nội Thị Vệ nói về một thị vệ cận thân thị vệ của vua Khang Hy tên là Đa bảo. Đa bảo là một chàng thanh niên luôn có ước mơ được vào làm thị vệ trong tử cấm thành. Chàng thanh niên này có võ nghệ cao cường, luôn muốn phục vụ người dân. Cuối cùng Đa Bao cũng đạt được ước mơ của mình, Đa Bảo được xung làm cận vệ cho Du Thân Vương Phứơc Toàn, được sự tín nhiệm và kết thân với vị vương gia này, Đa Bảo được đề cử bảo vệ vua Khang Hy. Nhưng trong chốn cấm cung luôn đầy rẩy những âm mưu toan tính, tranh giành quyền lực. Đa Bảo Phát hiện ra âm mưu soán vị ngôi vua của người huynh đệ Phước Toàn. Người bạn thanh mai trúc mã Trác Tử Ngưng của Đa Bảo lại bị cuốn vào cuộc chiến quyền lực chốn hậu cung. Đa Bảo phải làm thế nào để biết ai là thù, ai là bạn?</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 17, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Mã Tuấn Vỹ","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Lý Thi Vận","avatar":""},{"name":"Đường Thi Vịnh","avatar":""},{"name":"Cung Gia Hân","avatar":""},{"name":"Trần Quốc Bang","avatar":""},{"name":"Trần Cẩm Hồng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324470);
