INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-noi-thi-ve', 'Đại Nội Thị Vệ', 'The Life And Times Of A Sentinel', 'đại nội thị vệ the life and times of a sentinel mã tuấn vỹ mã quốc minh lý thi vận đường thi vịnh cung gia hân trần quốc bang trần cẩm hồng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-kim-thuat-su-ngoi-sao-thanh-cua-milos', 'Giả Kim Thuật Sư: Ngôi Sao Thánh Của Milos', 'Hagane No Renkinjutsushi: Milos No Seinaru Hoshi', 'https://phimimg.com/upload/vod/20231208-1/a8c529c7c67ad4b4cb373fdd9aafd57b.jpg', 'https://phimimg.com/upload/vod/20231208-1/8662236368b765f424f3b759a016c20a.jpg', '<p>Nguyên tác mô tả cuộc qui mô vĩ đại về dấu vết của quỷ và cuộc hành trình đầy khắc nghiệt của 2 anh em nhà Elric - những người đã dấn thân vào những điều cấm kị gây được tiếng vang lớn. Người em Edward Elric và người anh trai Alphonse dù bị số phận trêu ngươi vẫn đồng hành trong cuộc hành trình của chính mình. Câu chuyện kể về những mối ràng buộc bị cấm kị chính thức bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
