INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-ba-dao', 'Cô Nàng Bá Đạo', 'This Girl Is Bad Ass', 'https://phimimg.com/upload/vod/20231208-1/914c038fa59063a81539e1c8c0782a66.jpg', 'https://phimimg.com/upload/vod/20231208-1/16d0d420ae157e83bc30821b65d70e73.jpg', '<p>Nội dung của phim Cô Nàng Bá Đạo xoay quanh cuộc sống đầy xáo trộn của cô nàng trẻ tuổi xinh đẹp Jija Yanin và người chú Mum Jokmok của cô sau khi bị những tay giang hồ truy sát. Công việc của họ là vận chuyển hàng lậu cho các băng cướp khét tiếng bằng cách sử dụng xe đạp vốn tránh được sự nghi ngờ của cảnh sát một cách cao nhất.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"JeeJa Yanin","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Boriboon Junreurng","avatar":""},{"name":"Chalerm Yamchamang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
