INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-bien-vung-caribbe-phan-4-suoi-nguon-tuoi-tre', 'Cướp Biển Vùng Caribbe (Phần 4): Suối Nguồn Tươi Trẻ', 'Pirates Of The Caribbean: On Stranger Tides', 'https://phimimg.com/upload/vod/20231208-1/bded01f3d3d453344b2ce2b50be7be89.jpg', 'https://phimimg.com/upload/vod/20231208-1/be8589516f1a047f9650d25db0f7d4c4.jpg', '<p>Câu chuyện phim bắt đầu khi Jack Sparrow, đang tâp hợp thủy thủ đoàn để lên đường tìm tới Suối nguồn tươi trẻ, dòng suối đem lại sự sống cho người nào may mắn uống được. Chính tại nơi đây, Jack đã gặp lại Angelica, một nữ cướp biển vô cùng xinh đẹp mà anh đã từng gặp trong quá khứ. Jack bị Angelica ép đưa lên con tàu Revenge Queen Anne dưới sự điều khiển của cha cô - tên cướp biển dữ dằn Blackbeard. Sự thành công của cướp biển vùng Caribe đã mang tới thành công ngoài mong đợi cho Johnny Dept, anh đã từng được đề cử giải Oscar cho vai diễn của mình và trong phần 4 này Jack lại 1 lần nữa tái xuất tiếp tục mê hoặc khan giả bằng những hành động mạo hiểm nhưng đầy ngộ nghĩnh. Ngoài ra việc lựa chọn cảnh quay đẹp gần như nguyên sinh của Hawai khiến người xem không khỏi thán phục trước vẻ đẹp thơ mộng nơi đây.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Ian Mcshane","avatar":""},{"name":"Kevin Mcnally","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Astrid Bergès-Frisbey","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Keith Richards","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Greg Ellis","avatar":""},{"name":"Damian O''hare","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Anton Lesser","avatar":""},{"name":"Roger Allam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324470);
