INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-doi-pho', 'Nghệ Thuật Đối Phó', 'The Art Of Getting By', 'https://phimimg.com/upload/vod/20231208-1/0391e1a3edb8f283ad4aab4f791ab06f.jpg', 'https://phimimg.com/upload/vod/20231208-1/40b206eec49dc1bb5f3eb0c3c9d49ad8.jpg', '<p>George, một thiếu niên cô đơn và hay chết chóc, đã học hết năm cuối cấp mà chưa bao giờ làm một ngày làm việc thực sự, được kết bạn với Sally, một cô gái nổi tiếng nhưng phức tạp, người nhận ra ở anh một tinh thần nhân hậu.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Emma Roberts","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Alicia Silverstone","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
