INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-chet', 'Vùng Đất Chết', 'Stake Land', 'https://phimimg.com/upload/vod/20231208-1/e713f271520eeaf73688e81503c2d915.jpg', 'https://phimimg.com/upload/vod/20231208-1/c2a4b139cc6a1eda993ffce1da92dcfa.jpg', '<p>Nước Mỹ là bị tan rã sau khi đại nạn ma cà rồng diễn ra trên diện rộng. Các thành phố trở thành những nấm mồ khổng lồ, những người sống sót thì phải sống dựa vào nhau trong những khu ngoại ô đổ nát, với nỗi sợ hãi bóng đêm. Sau cái chết của cha mẹ, chàng trai trẻ Martin được một tay thợ săn mà cà rồng chuyên nghiệp hộ tống để tới bắc Canada, nơi được cho là nơi cuối cùng sạch bóng những kẻ hút máu người...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Connor Paolo","avatar":""},{"name":"Nick Damici","avatar":""},{"name":"Kelly McGillis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
