INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-quoc', 'Chiến Quốc', 'The Warring States', 'https://phimimg.com/upload/vod/20231206-1/2cad3033dea4f86c0b77358520fe2b98.jpg', 'https://phimimg.com/upload/vod/20231206-1/a4490c739f05d0fd00385529dc7833ec.jpg', '<p>Phim tái hiện thời kỳ Chiến Quốc với sự đối đầu giữa kỳ tài quân sự Tôn Tẫn và Bàng Quyên, chủ đề âm mưu, chiến tranh xen lẫn với tình yêu. Với sự đầu tư rất lớn, các cảnh quay được thực hiện ngoại cảnh trải dài từ Nội Mông, Hà Nam, Hà Bắc, các cảnh chiến đấu hoành tráng mang lại cảm giác choáng ngợp cho người xem...</p>', 'Full', 1, 'single', 'completed', 22, 2011, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Honglei Sun","avatar":""},{"name":"Tian Jing","avatar":""},{"name":"Hee-seon Kim","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324470);
