INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mo-coi-2', 'Sát Thủ Mồ Côi 2', 'The Burma Conspiracy: Largo Winch II', 'https://phimimg.com/upload/vod/20231204-1/80c9d60fd08135196035382565c26bc7.jpg', 'https://phimimg.com/upload/vod/20231204-1/c6d90feafdc27e5d50d823433ee389ab.jpg', '<p>Phim The Burma Conspiracy 2011 nói về bước đầu sóng ngọn gió, đặc biệt là bị áp lực nặng nề từ cái gọi là uỷ ban Adriatic, một hội kín gồm các doanh nhân chính trị gia bị nghi ngờ có liên quan đến cái chết của Nerio Winch, người từng sử dụng các phương cách kinh doanh lương thiện lẫn mờ ám để tẩy rửa tiền làm giàu. Liệu phim online này sẽ diễn biến thế nào mời các bạn cùng theo dõi bộ phim Sát Thủ Mồ Côi 2 và trải nghiệm những công nghệ phim hd tuyệt vời!</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tomer Sisley","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Ulrich Tukur","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324470);
