INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-xui', 'Hên Xui', '50/50', 'https://phimimg.com/upload/vod/20231204-1/c0dee38038c828d01af3c155878ddb5f.jpg', 'https://phimimg.com/upload/vod/20231204-1/f12f1991c6e4077c5fb19f3de19b5149.jpg', '<p>Adam Lerner là một anh chàng bình thường như bao chàng trai khác. Tính cách, sự nghiệp và chuyện tình yêu của Adam chẳng có gì nổi bật. Cuộc sống cứ bình lặng trôi qua cho đến khi anh phát hiện ra mình bị ung thư cột sống, vốn rất hiếm gặp, ở cái tuổi 27. Không những vậy, Adam còn bị cô bạn gái đỏng đảnh lừa dối. Mọi dự định tương lai tan biến, hạnh phúc ngày càng xa vời, thay vào đó là những giờ trị liệu hóa học, trị liệu tâm lý mệt nhọc. Mọi chuyện xảy đến với Adam quá đột ngột nhưng anh bình thản đón nhận dù gia đình và người bạn thân Kyle hết sức lo lắng. Trong quãng thời gian khó khăn nhất của cuộc đời, Adam cảm nhận được tình bạn, tình yêu đích thực, điều mà xưa nay anh chưa bao giờ tìm thấy...</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Anna Kendrick","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324470);
