INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lemonade-mouth', 'Lemonade Mouth', 'Lemonade Mouth', 'https://phimimg.com/upload/vod/20231203-1/169ce79c4a189826cb5c2fee7537026c.jpg', 'https://phimimg.com/upload/vod/20231203-1/c5238a721601945a718f99ceb640c1b0.jpg', '<p>Lemonade Miệng nói với trẻ em và thanh thiếu niên xây dựng những tảng đá tự tin của bạn và tìm ra các quy tắc định kỳ của bạn. Câu chuyện diễn ra sau năm học sinh trung học khác nhau - Olivia (Bridgit Mendler), Mo (Naomi Scott), Charlie (Blake Michael), Stella (Hayley Kiyoko) và Wen (Adam Hicks) gặp nhau đang bị giam giữ. Họ nhận ra rằng họ được định sẵn để đá, và cuối cùng thành lập một ban nhạc trở thành một nhà vô địch cho học sinh ngồi ngoài Elite trường trung học.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
