INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-mau-lanh', 'Sát Nhân Máu Lạnh', 'Cold Fish', 'https://phimimg.com/upload/vod/20231205-1/f4e5588e1c02ce859335be198fef7d10.jpg', 'https://phimimg.com/upload/vod/20231205-1/c4ad7315c4db54608ff9c47873174155.jpg', '<p>Cold Fish là một bộ phim kinh dị nổi tiếng của Nhật Bản. Câu chuyện xảy ra khi con gái tuổi teen của Syamoto bị bắt vì tội trộm cắp, một người đàn ông trung niên hào phóng giúp anh giải quyết tình hình. Người đàn ông và người vợ của mình còn cho Syamoto làm việc tại các cửa hàng bán cá kiểng của họ. Và ở đây, Syamoto sớm phát hiện ra sự thật khủng khiếp của cặp vợ chồng dường như hoàn hảo này...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Mitsuru Fukikoshi","avatar":""},{"name":"Denden","avatar":""},{"name":"Asuka Kurosawa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
