INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-doi', 'Cây Đời', 'The Tree of Life', 'https://phimimg.com/upload/vod/20231204-1/494cff7ce4c35bed9f2e97f47bb2a740.jpg', 'https://phimimg.com/upload/vod/20231204-1/47a11a94d62b144ef194545489a8c528.jpg', '<p>The Tree of Life là bộ phim tâm linh kể về cuộc sống của một gia đình vào những năm 1950. Bộ phim xoay quanh hành trình cuộc đời của người con cả trong gia đình, Jack, qua những năm tháng ngây thơ của tuổi nhỏ cho đến những năm trưởng thành đau khổ và vỡ mộng khi phải cố gắng hoà thuận với người cha kỹ tính và trầm cảm (Brad Pitt). Cuối cùng, Jack nhận ra bản thân mình là tâm hồn lạc lõng giữa thế giới hiện đại, Jack phải đi tìm câu trả lời về nguồn gốc và ý nghĩa của cuộc sống trong khi vẫn luôn thắc mắc về sự tồn tại của niềm tin.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Jessica Chastain","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324470);
