INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-nha-choc-troi', 'Siêu Trộm Nhà Chọc Trời', 'Tower Heist', 'https://phimimg.com/upload/vod/20231202-1/c296651590c8c35befd021f980accb4f.jpg', 'https://phimimg.com/upload/vod/20231202-1/fb168c9d48368e2b3a20926bb882c944.jpg', '<p>Siêu Trộm Nhà Chọc Trời, Tower Heist kể về Josh Kovaks là quản lý của một chung cư cao tầng ở New York. Ông là gần tất cả những người thuê nhà, đặc biệt là tài chính Arthur Shaw. Một ngày Shaw bị bắt giữ bởi FBI cho gian lận. Josh nghĩ đó là một sự hiểu lầm có thể được giải quyết, nhưng sau đó ông biết rằng quỹ lương hưu của người lao động - mà ông hỏi Shaw để xử lý - đã biến mất. Khi một trong những nhân viên cố gắng để giết mình, quan điểm của Josh Shaw thay đổi.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Alan Alda","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Gabourey Sidibe","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Nina Arianda","avatar":""},{"name":"Marcia Jean Kurtz","avatar":""},{"name":"Juan Carlos Hernández","avatar":""},{"name":"Harry O''Reilly","avatar":""},{"name":"James Colby","avatar":""},{"name":"Peter Van","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
