INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-canh-cut-nha-popper', 'Bầy Cánh Cụt Nhà Popper', 'Mr. Popper''s Penguins', 'https://phimimg.com/upload/vod/20231201-1/e67aca1aeaffb0c7b550589001a62c53.jpg', 'https://phimimg.com/upload/vod/20231201-1/4910bda2026e96a521edb1cacbb10ee5.jpg', '<p>Popper là một doanh nhân thành đạt. Anh tốt bụng và hài hước. Một ngày kia, anh nhận được một bưu kiện. Anh hết sức bất ngờ khi mở bưu kiện ấy, đó là 6 chú chim cánh cụt Nam cực. Cuộc sống của anh bắt đầu có những thay đổi lớn lao. Và khi anh biến đổi căn hộ sang trọng của mình thành miền đất thần tiên mùa đông cho những chú chim cánh cụt nhỏ thì một điều kỳ diệu đã xảy ra...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Ophelia Lovibond","avatar":""},{"name":"Madeline Carroll","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Maxwell Perry Cotton","avatar":""},{"name":"James Tupper","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"William Charles Mitchell","avatar":""},{"name":"Henry Kelemen","avatar":""},{"name":"Kelli Barrett","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324470);
