INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-sinh-tu', 'Thời Khắc Sinh Tử', 'In Time', 'https://phimimg.com/upload/vod/20231201-1/8122e1fae68e5eb33460f41e651500c3.jpg', 'https://phimimg.com/upload/vod/20231201-1/6526818afba2a0c82f7b6d71e6c7029a.jpg', '<p>Bị buộc tội giết người oan, chàng trai trẻ nọ chiến đấu để tồn tại trong một tương lai nơi người ta chỉ sống đến 25 tuổi – trừ những ai mua được thêm thời gian mới sống lâu hơn.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Timberlake","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Alex Pettyfer","avatar":""},{"name":"Johnny Galecki","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"Yaya DaCosta","avatar":""},{"name":"Toby Hemingway","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Shyloh Oostwald","avatar":""},{"name":"Emma Fitzpatrick","avatar":""},{"name":"Will Harris","avatar":""},{"name":"Michael William Freeman","avatar":""},{"name":"Jesse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324470);
