INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-bi-an', 'Điều Bí Ẩn', 'Mysteria', 'https://phimimg.com/upload/vod/20231212-1/f3dc305189b6f3f49cdd36c69318bf81.jpg', 'https://phimimg.com/upload/vod/20231212-1/199e5db43a64eba04b928bc9c5625db5.jpg', '<p>Một nhà biên kịch thấy mình là trung tâm của cuộc điều tra giết người liên quan đến một vợ chính trị nổi tiếng. Các sự kiện xung quanh nguồn cảm hứng cho ông cho kịch bản của mình … Nhưng đó chỉ là Điều Bí Ẩn mà ông chưa biết cho đến một ngày….</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Miano","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Martin Landau","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324470);
