INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-moi-lon-2011', 'Tuổi Mới Lớn', 'Young Adult', 'https://phimimg.com/upload/vod/20231201-1/a102d6a83c275f6d6a83979b614ba326.jpg', 'https://phimimg.com/upload/vod/20231201-1/db32b68afcd47da9052b8129798f475d.jpg', '<p>Bộ phim Young Adult xoay quanh một nhà văn đã ly dị sống ở miền Trung Tây trở về quê nhà của cô để kết nối lại với một mối tình cũ, người đã kết hôn và có một gia đình.Trong Young Adult, Charlize vào vai một nhà văn chuyên viết thay cho người khác những tiểu thuyết dành cho lứa tuổi thanh thiếu niên. Vừa ly hôn, Charlize trở về nhà của cô ở thị trấn nhỏ bé Minnesota , cô phát hiện ra người bạn trai thời trung học đã kết hôn nhưng cuộc sống không hạnh phúc.Cảm thấy vẫn còn tình cảm với người yêu cũ, cô tìm cách quyến rũ mặc kệ người ấy đã có một gia đình và những đứa trẻ. Cô gợi lại một mối tình lãng mạn và vạch kế hoạch để thu phục lại chàng trai vốn thuộc về mình…Thông tin thêm: Là một trong những gương mặt ...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlize Theron","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Collette Wolfe","avatar":""},{"name":"Jill Eikenberry","avatar":""},{"name":"Richard Bekins","avatar":""},{"name":"Mary Beth Hurt","avatar":""},{"name":"Kate Nowlin","avatar":""},{"name":"Jenny Dare Paulin","avatar":""},{"name":"Rebecca Hart","avatar":""},{"name":"Louisa Krause","avatar":""},{"name":"Elizabeth Ward Land","avatar":""},{"name":"Brian McElhaney","avatar":""},{"name":"Hettienne Park","avatar":""},{"name":"John Fore","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
