INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-tinh-yeu', 'Lời Nguyền Tình Yêu', 'Chilling Romance', 'https://phimimg.com/upload/vod/20231130-1/365e1706fee36eb639de9c6af88299a8.jpg', 'https://phimimg.com/upload/vod/20231130-1/76690f4f3057c353f9f37b273c5455ae.jpg', '<p>Bộ phim kể về câu chuyện giữa Yu-ri (một cô gái không thể hẹn hò với ai vì một &quot;giác quan&quot; rất đặc biệt) với Jo-gu (một chàng trai lận đận trong tình trường vì bản tính nhút nhát) và cuộc chiến đấu một mất một còn để giành lấy tình yêu của họ...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Hwang Seung-eon","avatar":""},{"name":"Kim Hyun-sook","avatar":""},{"name":"Yoon Ji-min","avatar":""},{"name":"Kim Soo-min","avatar":""},{"name":"Um Tae-goo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324470);
