INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-cong-chua-va-chang-phi-cong', 'Nàng Công Chúa Và Chàng Phi Công', 'Toaru Hikuushi e no Tsuioku', 'https://phimimg.com/upload/vod/20231130-1/037eaee8940e74f139dddc89f231314b.jpg', 'https://phimimg.com/upload/vod/20231130-1/603e322116675df4898f137910b5aadd.jpg', '<p>Cuộc chiến giữa Đế quốc Levamme và Đế quốc Amatsukami đã diễn ra ác liệt trong nhiều năm. Giữa cuộc đấu tranh này, hoàng tử của Đế chế Levamme tuyên bố tình yêu của mình với Juana del Moral và thề sẽ kết thúc chiến tranh sau một năm, như một phần trong lời cầu hôn của anh ấy. Khi Amatsukami biết được điều này, họ tấn công dinh thự của del Moral, nhằm vào mạng sống của Juana. Trong nỗ lực cuối cùng nhằm mang lại cô dâu cho hoàng tử, Lực lượng Không quân San Maltilia thuê một lính đánh thuê mang hai dòng máu lai—một bestado—để bí mật đưa Juana đến gặp hoàng tử.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Haruka","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Takeshi Tomizawa","avatar":""},{"name":"Takuto Yoshinaga","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Yutaka Nakano","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Seiko Niizuma","avatar":""},{"name":"Katsumi Cho","avatar":""},{"name":"Mitsuaki Hoshino","avatar":""},{"name":"Risa Shimizu","avatar":""},{"name":"Hideaki Nonaka","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id"