INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-cong-chua-va-chang-phi-cong', 'Nàng Công Chúa Và Chàng Phi Công', 'Toaru Hikuushi e no Tsuioku', 'nàng công chúa và chàng phi công toaru hikuushi e no tsuioku haruka ryunosuke kamiki daisuke ono takeshi tomizawa takuto yoshinaga masaki terasoma yutaka nakano sumire morohoshi daisuke namikawa seiko niizuma katsumi cho mitsuaki hoshino risa shimizu hideaki nonaka ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ga-mai-thich-phieu-luu', 'Cô Gà Mái Thích Phiêu Lưu', 'Leafie, a Hen Into the Wild', 'https://phimimg.com/upload/vod/20231130-1/5dc30aa1a81ecb1252e7dc781d29a164.jpg', 'https://phimimg.com/upload/vod/20231130-1/158b8b4b3d126703788dacd7f0c40b2c.jpg', '<p>Cô gà mái Leafie sống trong một trang trại nhưng vẫn mơ ước được bay ra khoảng sân bên ngoài nông trại để có thể tự do đẻ trứng. Leafie cố tính nhịn đói, vờ như không thể đẻ trứng được nữa. Cô bị ném ra vũng bùn và suýt bị tên chồn một mắt ăn thịt nhưng may sao thoát nạn nhờ sự giúp đỡ của một chú vịt.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon So-ri","avatar":""},{"name":"Yoo Seung-ho","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Kim Sang-hyun","avatar":""},{"name":"Jeon Sook-kyung","avatar":""},{"name":"Um Sang-hyun","avatar":""},{"name":"Sa Seong-ung","avatar":""},{"name":"Kim Ji-hye","avatar":""},{"name":"Seo Seung-won","avatar":""},{"name":"Han Shin-jeong","avatar":""},{"name":"Hong Beom-gi","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324470);
