INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-ga-mai-thich-phieu-luu', 'Cô Gà Mái Thích Phiêu Lưu', 'Leafie, a Hen Into the Wild', 'cô gà mái thích phiêu lưu leafie, a hen into the wild moon so-ri yoo seung-ho choi min-sik park chul-min kim sang-hyun jeon sook-kyung um sang-hyun sa seong-ung kim ji-hye seo seung-won han shin-jeong hong beom-gi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ham', 'Đường Hầm', 'The Tunnel', 'https://phimimg.com/upload/vod/20231130-1/71d00306fde4c01d6bee14d349a430e0.jpg', 'https://phimimg.com/upload/vod/20231130-1/6c1abc1597f42ab1588d61db815f6f7a.jpg', '<p>Vào năm 2007, giữa tình trạng hạn hán và thiếu nước, chính quyền Bang NSW đã tiết lộ kế hoạch khai thác và tái chế hàng triệu lít nước bị mắc kẹt trong mạng lưới đường hầm xe lửa bỏ hoang ngay bên dưới trung tâm Sydney. Tuy nhiên, chính phủ đột nhiên lạnh nhạt với kế hoạch và lý do tại sao không được công khai. Người ta nói về những người vô gia cư sử dụng đường hầm làm nơi trú ẩn sẽ mất tích, mặc dù chính phủ tuyên bố rằng không có người vô gia cư nào ở đó. Điều này cùng với sự im lặng của các quan chức và bộ trưởng đã khiến một nhà báo, Natasha bắt đầu cuộc điều tra về sự che đậy của chính phủ. Cô và nhóm của mình Pete (Nhà sản xuất), Steve (Người quay phim) và Tangles (Kỹ thuật viên âm thanh) quyết định điều tra câu chuyện trong đường hầm.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Bel Deliá","avatar":""},{"name":"Luke Arnold","avatar":""},{"name":"Andy Rodoreda","avatar":""},{"name":"James Caitlin","avatar":""},{"name":"Goran D. Kleut","avatar":""},{"name":"Arianna Gusi","avatar":""},{"name":"Peter McAllum","avatar":""},{"name":"Shannon Jones","avatar":""},{"name":"Ben Maclaine","avatar":""},{"name":"Steve Davis","avatar":""},{"name":"Renee Lim","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324471);
