INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-le-tru-ta', 'Nghi Lễ Trừ Tà', 'The Rite', 'https://phimimg.com/upload/vod/20231130-1/963779c44ac913fb37a21c2dbc25fd18.jpg', 'https://phimimg.com/upload/vod/20231130-1/d1c5bb3b0c9f888990c91a39329b89ae.jpg', '<p>Sinh viên chủng viện Michael Kovak miễn cưỡng theo học trường trừ tà ở Vatican. Khi đang ở Rome, Michael gặp một linh mục không chính thống, người đã giới thiệu cho anh ta về mặt tối của đức tin, khám phá ra tầm với của ma quỷ thậm chí đến một trong những nơi linh thiêng nhất trên Trái đất.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Colin O''Donoghue","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Maria Grazia Cucinotta","avatar":""},{"name":"Marta Gastini","avatar":""},{"name":"Arianna Veronesi","avatar":""},{"name":"Andrea Calligari","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"Torrey DeVitto","avatar":""},{"name":"Ben Cheetham","avatar":""},{"name":"Marija Karan","avatar":""},{"name":"Rosa Pianeta","avatar":""},{"name":"Giampi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324471);
