INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scabbard-samurai', 'Scabbard Samurai', 'Scabbard Samurai', 'https://phimimg.com/upload/vod/20231130-1/41e630d5db5fc847d8bc396ce52afbee.jpg', 'https://phimimg.com/upload/vod/20231130-1/cebf262b7d6cf41a5837af731b6bd6ca.jpg', '<p>Kanjuro Nomi là một samurai già chỉ có một bao kiếm. Bỏ mặc lãnh chúa của mình để đi lang thang khắp vùng đất cùng con gái Tae, Kanjuro bị bắt và bị kết án với một hình phạt bất thường: anh có 30 ngày để mang lại nụ cười cho vị hoàng tử đau buồn đã mất mẹ — nếu không anh sẽ phải chết.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takaaki Nomi","avatar":""},{"name":"Sea Kumada","avatar":""},{"name":"Itsuji Itao","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Pistol Takehara","avatar":""},{"name":"Ryo","avatar":""},{"name":"Masatō Ibu","avatar":""},{"name":"Zennosuke Fukkin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
