INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-toc-do', 'Thiên Thần Tốc Độ', 'Speed Angels', 'https://phimimg.com/upload/vod/20231130-1/3f3b3126fb091523441be6c6fb40604c.jpg', 'https://phimimg.com/upload/vod/20231130-1/8c25e4edaf1659213fe8a6ccdfdd5b80.jpg', '<p>Thiên Thần Tốc Độ là bộ phim lấy cảm hứng từ đua xe. Nội dung kể về 2 cô gái là hai tay đua của đội Lưu Quang, là linh hồn của đội. Hai người thay nhau giành chức quán quân trong các cuộc đua. Tuy nhiên, tại một cuộc thi quan trọng, hai người tự nhiên mất tích dẫn tới sự giải tán đội đua trong thất bại. Một năm sau, giáo viên huấn luyện của đội Lưu Quang quyết định vực dậy đội đua. Anh tìm được một nhân vật tiềm năng là một tài xế taxi, quyết tâm đào tạo cô thành một tay đua hạng nhất để cùng Lưu Nhược Anh và đội xe đua Nhật Bản Điền Trung Thiên hội tiến hành một cuộc đua sinh tử...</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tang Wei","avatar":""},{"name":"René Liu","avatar":""},{"name":"Han Jae-suk","avatar":""},{"name":"Jimmy Lin Chih-Ying","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Chie Tanaka","avatar":""},{"name":"Cheng Pei-pei","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Cecilia Cheung Pak-Chi","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"He Jiong","avatar":""},{"name":"Zhu Yongteng","avatar":""},{"name":"Li Xin-Lu","avatar":""},{"name":"Max Chow Hung-Choi","avatar":""},{"name":"Min Chunxiao","avatar":""},{"name":"Minowa Yasufumi","avatar":""},{"name":"Zhong Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324471);
