INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-killer-who-never-kills', 'The Killer Who Never Kills', 'The Killer Who Never Kills', 'null', 'https://phimimg.com/upload/vod/20231130-1/737afaf02f4f372c1c547ff166a099c6.jpg', '<p>Trevor Ou là Sát Thủ Không Bao Giờ Giết Người, một sát thủ chiếm được lòng tin của các mục tiêu trước khi tước đoạt mạng sống của họ – và anh ta làm điều đó mà không giết họ! Trevor làm giả cái chết của mục tiêu và cho họ danh tính mới, nhưng khi mục tiêu đầu tiên của anh là Grace trở lại – và bộc lộ tình yêu của cô dành cho anh – Trevor có thể cần tìm một giải pháp lâu dài hơn.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Jam Hsiao","avatar":""},{"name":"Zaizai Lin","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Huang Licheng","avatar":""},{"name":"Chang Kuo-Chu","avatar":""},{"name":"Ma Nien-Hsien","avatar":""},{"name":"Chao Cheng-Ping","avatar":""},{"name":"Na-Do","avatar":""},{"name":"Danny Deng","avatar":""},{"name":"Janel Tsai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
