INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kungfu-tho-ngo', 'Kungfu Thỏ Ngố', 'Legend of Kung Fu Rabbit', 'https://phimimg.com/upload/vod/20231130-1/942051d7658324c09b4ad78ee89699a6.jpg', 'https://phimimg.com/upload/vod/20231130-1/c0dffea88f7975fb06e74348bce11ed3.jpg', '<p>Bỗng một ngày kia từ đằng chân trời xuất hiện một cuộc can qua: minh chủ võ lâm Lão Quán Chủ bị đồ đệ là tên gấu trúc Hùng Thiên Bá phản bội và hãm hại. Ông chạy về nơi Thố Nhị đang sinh sống. Cơ duyên đưa đẩy Lão Quán Chủ truyền thụ toàn bộ võ công cho Thố Nhị rồi căn dặn cậu về nhiệm vụ tiêu diệt Hùng Thiên Bá và cứu lấy hòa bình cho toàn bộ dân chúng. Nhưng trước đó, Thố Nhị cần phải tìm được con gái của Lão Quán Chủ tên là Mẫu Đơn. Và từ đây, Thố Nhị đã chính thức bước vào một cuộc hành trình đầy gian nan, hiểm nguy rình rập.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Rebecca Black","avatar":""},{"name":"Tom Arnold","avatar":""},{"name":"Claire Geare","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Jon Heder","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
