INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-ngoai-truyen', 'Võ Lâm Ngoại Truyện', 'My Own Swordsman', 'https://phimimg.com/upload/vod/20231129-1/d31d8dba4c2d47db84ed66f633a1a19b.jpg', 'https://phimimg.com/upload/vod/20231129-1/fbf9bdf4e9d1f852ffb546ecfa0959c7.jpg', '<p>Sau tám mươi tập phát sóng trên truyền hình Trung Quốc đại lục, bộ phim hài kung fu nổi tiếng Thượng Kinh đã nhảy lên màn ảnh rộng với phiên bản đặc sắc này.</p>', 'Full', 1, 'single', 'completed', 6, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sha Yi","avatar":""},{"name":"Yu Entai","avatar":""},{"name":"Ni Hongjie","avatar":""},{"name":"Jiang Chao","avatar":""},{"name":"Yao Chen","avatar":""},{"name":"Yan Ni","avatar":""},{"name":"Wu Ma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
