INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-tu-luan-hoi-dap-an-hoan-hao', 'Sinh Tử Luân Hồi: Đáp Án Hoàn Hảo', 'Gantz: Perfect Answer', 'https://phimimg.com/upload/vod/20231129-1/76e6df0e2868d32b6a52a80bd5eb70e1.jpg', 'https://phimimg.com/upload/vod/20231129-1/78e2de36989cdf6ce54a399190e0edd5.jpg', '<p>Kei Kurono và Masaru Kato được triệu tập tới Gantz. Họ tiếp tục chiến đấu để chống lại những mối hiểm họa đến từ những hành tinh ngoài trái đất. Càng chiến đấu thì họ lại càng trở nên mạnh mẽ hơn. Họ sẽ không thể từ bỏ trừ khi hạ được kẻ thù cuối cùng, Saint. Kei Kurono tiếp tục chiến đấu để sống sót, nhưng Masaru Kato thì lại căm ghét cái thế giới bị kiểm soát bởi bạo lực này và muốn từ bỏ.Từ 2 người bạn thân, Kei Kurono và Masaru Kato trở thành 2 kẻ đối đầu trong trò chơi bạo lực đó. Sự lựa chọn cuối cùng sẽ là gì...?</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazunari Ninomiya","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Kensuke Chisaka","avatar":""},{"name":"Go Ayano","avatar":""},{"name":"Shigeru Okuse","avatar":""},{"name":"Yasuyuki Hirano","avatar":""},{"name":"Masafumi Oishi","avatar":""},{"name":"Kyoji Kamui","avatar":""},{"name":"Masanobu Sakata","avatar":""},{"name":"Naho Toda","avatar":""},{"name":"Ryuya Wakaba","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Tomokazu Koshimura","avatar":""},{"name":"Tomorow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae