INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ca-phe-de-flore', 'Quán Cà Phê De Flore', 'Café de Flore', 'https://phimimg.com/upload/vod/20231129-1/f11b463cf107ed735cd8c11981b2e3bc.jpg', 'https://phimimg.com/upload/vod/20231129-1/ba8c56d510a04289bbbb70d37cce9047.jpg', '<p>Jacqueline là một bà mẹ trẻ sống ở Paris những năm 1960 cùng với cậu con trai tàn tật Laurent. Bị chồng ruồng bỏ, Jacqueline hi sinh tất cả để chăm sóc con trai và thề sẽ cho Laurent một cuộc sống “bình thường” đầy hạnh phúc. Antoine, là một DJ thành công ở Montreal ngày nay, người dường như có tất cả: một sự nghiệp phát đạt, hai cô con gái xinh đẹp, bạn đời Rose, người mà anh yêu say đắm. Tuy nhiên, không có gì là hoàn hảo và Carole, vợ cũ của Antoine vẫn bị tàn phá bởi cuộc chia ly gần đây của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Vanessa Paradis","avatar":""},{"name":"Kevin Parent","avatar":""},{"name":"Hélène Florent","avatar":""},{"name":"Evelyne Brochu","avatar":""},{"name":"Marin Gerrier","avatar":""},{"name":"Alice Dubois","avatar":""},{"name":"Evelyne de la Chenelière","avatar":""},{"name":"Michel Dumont","avatar":""},{"name":"Joanny Corbeil-Picher","avatar":""},{"name":"Rosalie Fortier","avatar":""},{"name":"Michel Laperrière","avatar":""},{"name":"Caroline Bal","avatar":""},{"name":"Nicolas Marié","avatar":""},{"name":"Pascal Elso","avatar":""},{"name":"Jérôme Kircher","avatar":""},{"name":"Clair","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
