INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-linh-ngu-lam-2011', 'Ba Chàng Lính Ngự Lâm', 'The Three Musketeers', 'https://phimimg.com/upload/vod/20231029-1/f225201502003c6b291658878ea54066.jpg', 'https://phimimg.com/upload/vod/20231029-1/c4df8dd52809be71c508959e7f59346b.jpg', '<p>Anh chàng quý tộc trẻ và nghèo D’Artagnan khá nóng tính giờ đây phải đồng hành cùng với 3 chàng lính ngự lâm để đánh bại M&quot;lady De Winter, người phụ nữ trẻ đẹp quyến rũ và là tay sai của Hồng y giáo chủ Richelieu, nhằm dập tắt âm mưu chiếm ngôi vua nước Pháp và nhấn chìm toàn bộ châu Âu vào chiến tranh...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Gabriella Wilde","avatar":""},{"name":"James Corden","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Freddie Fox","avatar":""},{"name":"Dexter Fletcher","avatar":""},{"name":"Helen George","avatar":""},{"name":"Christian Oliver","avatar":""},{"name":"Markus Bra","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
