INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-bao-thu-2011', 'Người Đẹp Báo Thù', 'Haywire', 'https://phimimg.com/upload/vod/20231103-1/19f744b86de8de21b684217564a30853.jpg', 'https://phimimg.com/upload/vod/20231103-1/22e344fd47a4d6ffe5949e29ca53811b.jpg', '<p>Trong Haywire, một câu chuyện thót tim về hoạt động gián điệp và sự phản bội, một nữ tình báo (Carano), người làm việc trong môi trường gián điệp quốc tế đầy nguy hiểm, phản kháng lại sau khi phát hiện mình bị phản bội bởi một kẻ vô cùng thân cận trong cục. Bộ phim được sản xuất bởi Gregory Jacobs (loạt phim về Ocean) và chắp bút bởi Lem Dobbs (The Limey).Haywire sẽ ra rạp vào ngày 20/01/2012 với dàn diễn viên ngôi sao Channing Tatum, Ewan McGregor, Michael Fassbender, Michael Douglas, Antonio Banderas, Bill Paxton, Michael Angarano, Mathieu Kassovitz. Phim do Steven Soderbergh đạo diễn.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Gina Carano","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Eddie J. Fernandez","avatar":""},{"name":"Anthony Brandon Wong","avatar":""},{"name":"Tim Connolly","avatar":""},{"name":"Max Arciniega","avatar":""},{"name":"Aaron Cohen","avatar":""},{"name":"Debbie Lynn Ross","avatar":""},{"name":"Juli","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef