INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-dien-dai-2011', 'Yêu Điên Dại', 'Crazy, Stupid, Love.', 'https://phimimg.com/upload/vod/20231022-1/9ff5b385753c3c98e4509ac9fa324749.jpg', 'https://phimimg.com/upload/vod/20231022-1/8370687f6380f47946f3c5367c79cae4.jpg', '<p>Cal Weaver quá chán nản với những vấn đề không thể tháo gỡ trong cuộc hôn nhân 25 năm của mình. Sau khi được một anh chàng đẹp trai sát gái tư vấn, Cal đã biến mình thành một tay chơi phong độ khác hẳn với mình lúc trước.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"Jonah Bobo","avatar":""},{"name":"Joey King","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Beth Littleford","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Liza Lapira","avatar":""},{"name":"Josh Groban","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Julianna Guill","avatar":""},{"name":"Crystal Reed","avatar":""},{"name":"Zayne Emory","avatar":""},{"name":"Joanne Brooks","avatar":""},{"name":"Caitl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
