INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-si-bat-dac-di', 'Dũng Sĩ Bất Đắc Dĩ', 'Ronal Barbaren', 'https://phimimg.com/upload/vod/20231129-1/dbd518a179aeb14a8d085da2898328f0.jpg', 'https://phimimg.com/upload/vod/20231129-1/1942ae416198dec19426edbbfe38448d.jpg', '<p>Ron - man rợ và khác thường nhất trên thế giới. Không quan tâm đến bất kỳ trận chiến hay chinh phục nào. Điều mà anh muốn chỉ là được ở một mình. Nhưng số phận đưa đẩy, một ngày kia hoàng tử ác Volkazar, lãnh đạo bộ tộc thù địch, đã bắt tất cả cúng tế cho các vị thần cổ đại để đem lại cho họ quyền lực trên thế giới. Ron cùng với một nữ chiến binh cơ bắp, phải vượt qua nhiều gian nan để giải phóng người dân của mình, tìm lại niềm vui.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2011, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Anders Juul","avatar":""},{"name":"Hadi Ka-Koush","avatar":""},{"name":"Lærke Winther","avatar":""},{"name":"Brian Lykke","avatar":""},{"name":"Lars Mikkelsen","avatar":""},{"name":"Peter Aude","avatar":""},{"name":"Lars Bom","avatar":""},{"name":"Ole Thestrup","avatar":""},{"name":"Preben Kristensen","avatar":""},{"name":"Brigitte Nielsen","avatar":""},{"name":"Sven-Ole Thorsen","avatar":""},{"name":"Ole Ernst","avatar":""},{"name":"Jesper Binzer","avatar":""},{"name":"Allan Olsen","avatar":""},{"name":"Jens Jacob Tychsen","avatar":""},{"name":"Bodil Jørgensen","avatar":""},{"name":"Szhirley","avatar":""},{"name":"Niels","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324471);
