INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-2011', 'Thợ Săn', 'The Hunter', 'https://phimimg.com/upload/vod/20231129-1/33312ee90e5faf73a99b3e64611506b4.jpg', 'https://phimimg.com/upload/vod/20231129-1/113f74165c58cd67c9021d6fee1ce076.jpg', '<p>Martin, một lính đánh thuê, được một công ty công nghệ sinh học bí ẩn ở Châu Âu phái đến vùng hoang dã Tasmania để săn lùng con hổ Tasmania cuối cùng.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Willem Dafoe","avatar":""},{"name":"Frances O''Connor","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Jacek Koman","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Dan Wyllie","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"Morgan Davies","avatar":""},{"name":"Finn Woodlock","avatar":""},{"name":"Jamie Timony","avatar":""},{"name":"Maia Thomas","avatar":""},{"name":"Dan Spielman","avatar":""},{"name":"John Brumpton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324471);
