INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tho-san-2011', 'Thợ Săn', 'The Hunter', 'thợ săn the hunter willem dafoe frances o''connor sam neill jacek koman callan mulvey dan wyllie sullivan stapleton morgan davies finn woodlock jamie timony maia thomas dan spielman john brumpton ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-den-toi', 'Giờ Đen Tối', 'The Darkest Hour', 'https://phimimg.com/upload/vod/20231128-1/c5ff7b7ee28df7d4747a059fbe1a7b83.jpg', 'https://phimimg.com/upload/vod/20231128-1/c27125e72cb5e4caccb18a1599816d8a.jpg', '<p>Nội dung của phim Giờ Đen Tối xoay quanh hai nhà thiết kế phần mềm người Mỹ tên Sean ( Emile Hirsch) và Ben (Max Minghella), những người tới Moscow để bán phần mềm của họ cho các nhà đầu tư. Tuy nhiên, Sean và Ben đã bị chơi xấu bởi đối tác người Thụy Điển của họ – Skyler, công việc làm ăn của 2 người từ đó cũng kết thúc. Sau đó cả 2 đến một hộp đêm, nơi họ gặp 2 cô nàng xinh đẹp người Mỹ và Úc là Natalie và Anne, họ tán tỉnh các cô gái và gặp Skyler trong câu lạc bộ.
 Bất ngờ, tất cả mọi người đã hết sức ngạc nhiên bởi nguồn ánh sáng chiếu tới, thứ mà họ nhầm lẫn với các hiện tượng tự nhiên. Nhưng chẳng bao lâu, họ biết rằng ánh sáng là dấu hiệu của việc những người ngoài hành tinh xâm chiếm Trái đất và sử dụng nguồn cung cấp năng lượng để tiêu diệt loài người. Sean, Ben, Natalie, Anne và Skyler trốn trong bếp và khi rời khỏi nơi này, họ tìm kiếm những người sống sót trên đường phố. Liệu rằng họ có phải là người cuối cùng trên Trái đất?</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Joel Kinnaman","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Veronika Ozerova","avatar":""},{"name":"Dato Bakhtadze","avatar":""},{"name":"Gosha Kutsenko","avatar":""},{"name":"Nikolay Efremov","avatar":""},{"name":"Georgiy Gromov","avatar":""},{"name":"Artur Smolyaninov","avatar":""},{"name":"Anna Roudakova","avatar":""},{"name":"Pyotr Fyodorov","avatar":""},{"name":"Ivan Gromov","avatar":""},{"name":"Aleksandr Chernykh","avatar":""},{"name":"Oleg Poddubn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324471);
