INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-vo-thuat', 'Gia Đình Võ Thuật', 'The Kick', 'https://phimimg.com/upload/vod/20231128-1/6596d10cfc410af818c0006965f40934.jpg', 'https://phimimg.com/upload/vod/20231128-1/9b9eb883dd756ed52dc64eb0335b90d8.jpg', '<p>Phim kể về 1 gia đình Hàn Quốc nhập cư sang Thái Lan và mở 1 lớp dạy Taewondo. Có 1 băng nhóm XHĐ Thái Lan đã đánh cướp &#39;&#39;Thanh kiếm thần của vị vua cuối cùng của Thái La &#39;&#39;được triển lãm ở Bảo tàng Quốc gia. Bằng võ nghệ cao cường, gia đình Moon dành lại báu vật trên tay bọn chúng và trở thành những người hùng của Thái Lan. Nhưng điều đó làm bọn tội phạm càng giận dữ. Chúng bắt cóc cậu con trai út và đòi lấy Thanh kiếm của Đức vua để trao đổi.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cho Jae-hyun","avatar":""},{"name":"Ye Ji Won","avatar":""},{"name":"Tae-joo Na","avatar":""},{"name":"Taemi","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"JeeJa Yanin","avatar":""},{"name":"Do Shi-gang","avatar":""},{"name":"Lee Kwan-hun","avatar":""},{"name":"Kim Yiroo","avatar":""},{"name":"Brahim Achabbakhe","avatar":""},{"name":"Thanathep Sucharitchan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324471);
