INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-charlie-brown', 'Cậu Bé Charlie Brown', 'Happiness Is a Warm Blanket, Charlie Brown', 'https://phimimg.com/upload/vod/20231128-1/f307d91c55bdee6d0bfd6afb489e39a9.jpg', 'https://phimimg.com/upload/vod/20231128-1/8fb5e8da745fd399597c65858e5497d7.jpg', '<p>Linus bị đẩy đến giới hạn của mình khi biết rằng bà ngoại sẽ đến thăm và lên kế hoạch cởi bỏ chiếc chăn an toàn trẻ con của anh.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Grace Rolek","avatar":""},{"name":"Ciara Bravo","avatar":""},{"name":"Amanda Pace","avatar":""},{"name":"Blesst Bowden","avatar":""},{"name":"Andrew Beall","avatar":""},{"name":"Andy Pessoa","avatar":""},{"name":"Trenton Rogers","avatar":""},{"name":"Austin Lux","avatar":""},{"name":"Shane Baumel","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
