INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-dem-o-paris', 'Nửa Đêm Ở Paris', 'Midnight in Paris', 'https://phimimg.com/upload/vod/20231128-1/c7d503256a6cb61bb14e19a8ec46d18f.jpg', 'https://phimimg.com/upload/vod/20231128-1/e24f19abe4c8992f40ed40a2e74f1b3a.jpg', '<p>Nhân vật chính của Midnight in Paris là Gil, một chàng nhà văn người Mỹ, cùng vị hôn thê xinh đẹp Inez đến Paris trong một kỳ nghỉ. Vẻ đẹp lãng mạn của thủ đô nước Pháp với kiến trúc cổ kính, quá khứ tươi đẹp, lộng lẫy, những cơn mưa bất chợt đã khiến tâm hồn của một thi sĩ lãng mạn như Gil bị xao xuyến. Trong khi đó, hôn thê của anh lại chìm đắm trong sự hiện đại của Paris. Một hôm, khi đi dạo trên đường phố lúc nửa đêm, Gil bất ngờ leo lên một chiếc xe Peugeot cổ. Chuyến xe này đưa anh trở lại Paris vào những năm 1920. Tại đây, Gil đã gặp gỡ những nhân vật mà anh không bao giờ có thể ngờ tới - nhà văn Mỹ Earnest Hemingway, nữ nhà văn Gertrude Stein, danh họa Pablo Picasso, nhà soạn nhạc Cole Porter, vợ chồng Scott và Zelda Fitzgerald... Những ngày sau đó, cứ tới nửa đêm, Gil lại leo lên chiếc xe cổ và du hành thời gian trở về thời kỳ hoàng kim của Paris và tận hưởng cái không khí hoài cổ mà bản thân anh vẫn hằng ao ước...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Kurt Fuller","avatar":""},{"name":"Mimi Kennedy","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Nina Arianda","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Carla Bruni","avatar":""},{"name":"Maurice Sonnenberg","avatar":""},{"name":"Thierry Hancisse","avatar":""},{"name":"Guillaume Gouix","avatar":""},{"name":"Audrey Fleurot","avatar":""},{"name":"Marie-Sohna Condé","avatar":""},{"name":"Yves Heck","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Tom Hiddlest","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
