INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-duoc-bao-truoc-2011', 'Cái Chết Được Báo Trước', 'Scream of the Banshee', 'https://phimimg.com/upload/vod/20231101-1/2ba25cd1a9c4c0224b81f20622ecc0c0.jpg', 'https://phimimg.com/upload/vod/20231101-1/5d8d8e135d77bc71e2b924d9bbc18bf7.jpg', '<p>Một giáo sư khảo cổ học đã khai quật một cổ vật nguy hiểm, vô tình giải phóng một sinh vật có thể giết người bằng sức mạnh của tiếng thét xé xương của nó.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Henriksen","avatar":""},{"name":"Lauren Holly","avatar":""},{"name":"Edrick Browne","avatar":""},{"name":"Leanne Cochran","avatar":""},{"name":"Kasey Emas","avatar":""},{"name":"Misty Ormiston","avatar":""},{"name":"Kim Ormiston","avatar":""},{"name":"Eric F. Adams","avatar":""},{"name":"Marcelle Baer","avatar":""},{"name":"Thomas C. Daniel","avatar":""},{"name":"Garrett Hines","avatar":""},{"name":"Don Lincoln","avatar":""},{"name":"Monica Acosta","avatar":""},{"name":"Kayden Kessler","avatar":""},{"name":"John T. Wilson Jr.","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324471);
