INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-nguc', 'Địa Ngục', 'Hell', 'https://phimimg.com/upload/vod/20231129-1/ef8f840fdcaf07bebf097977e8e26913.jpg', 'https://phimimg.com/upload/vod/20231129-1/50d574e35cfe9e2dcfa1d197fb9e228a.jpg', '<p>Bối cảnh vào năm 2016 khi mà lượng bức xạ từ mặt trời trở lên quá mạnh mọi thứ trên trái đất dần bị thiêu trụi. Dần dần còn rất ít người sống sót được sau thảm họa, họ phải sống chiến đấu với bầu không khí khô cằn để tìm nguồn sống...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Hannah Herzsprung","avatar":""},{"name":"Lars Eidinger","avatar":""},{"name":"Stipe Erceg","avatar":""},{"name":"Lisa Vicari","avatar":""},{"name":"Angela Winkler","avatar":""},{"name":"Yoann Blanc","avatar":""},{"name":"Christoph Gaugler","avatar":""},{"name":"Ellen Schweiger","avatar":""},{"name":"Luca Winkler","avatar":""},{"name":"Tammo Winkler","avatar":""},{"name":"Anne Hartung","avatar":""},{"name":"Stanislav Bogdanov","avatar":""},{"name":"Christine Sehr","avatar":""},{"name":"Christine Kollmann","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324471);
