INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-ky-quac', 'Ngã Rẽ Kỳ Quặc', 'Bellflower', 'https://phimimg.com/upload/vod/20231129-1/8e8190054bf1f361e5f24a97b999a1ac.jpg', 'https://phimimg.com/upload/vod/20231129-1/3927f32759b1f85853381d237f919dc0.jpg', '<p>Hai người bạn dành tất cả thời gian rảnh của họ để xây dựng niềm đam mê súng phun và các loại vũ khí hủy diệt hàng loạt với hy vọng rằng một ngày tận thế toàn cầu sẽ xảy ra. Cả 2 người rất chăm chút chiếc xe mang tên medusa và nhờ nó nên cả 2 vượt qua mọi thử thách. Phim gay cấn và nhiều tình tiết rất hồi hộp.</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan Glodell","avatar":""},{"name":"Jessie Wiseman","avatar":""},{"name":"Tyler Dawson","avatar":""},{"name":"Rebekah Brandes","avatar":""},{"name":"Vincent Grashaw","avatar":""},{"name":"Zack Kraus","avatar":""},{"name":"Keghan Hurst","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
