INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-cua-tom-sawyer', 'Những Cuộc Phiêu Lưu Của Tom Sawyer', 'Tom Sawyer', 'https://phimimg.com/upload/vod/20231129-1/8bf0c6d09a766ba978c26c5e7392be9a.jpg', 'https://phimimg.com/upload/vod/20231129-1/8708f280e0dd4aacc74d201699484553.jpg', '<p>Tom Sawyer có một cái đầu đầy những trò đùa và lái xe khi anh ta phát minh ra không chỉ là một cuộc phiêu lưu mới, tốt nhất là xung quanh với người bạn thân nhất của anh ta Huck Finn - khiến dì Polly của anh ta cùng với Tom và anh trai cùng cha khác mẹ của anh ta Sid ở thị trấn St. .Petersburg trên sông Mississippi.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Louis Hofmann","avatar":""},{"name":"Heike Makatsch","avatar":""},{"name":"Benno Fürmann","avatar":""},{"name":"Joachim Król","avatar":""},{"name":"Peter Lohmeyer","avatar":""},{"name":"Hinnerk Schönemann","avatar":""},{"name":"Sylvester Groth","avatar":""},{"name":"Leon Seidel","avatar":""},{"name":"Holger Handtke","avatar":""},{"name":"Andreas Warmbrunn","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
