INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-sam-truyen-thuyet-ve-asgard', 'Thần Sấm: Truyền Thuyết Về Asgard', 'Thor: Tales of Asgard', 'https://phimimg.com/upload/vod/20231129-1/7488f46024b79962a333e2bdae69a281.jpg', 'https://phimimg.com/upload/vod/20231129-1/c1c6723d3c7e28017eb9137e9dcac11a.jpg', '<p>Khao khát phiêu lưu, Thor bí mật dấn thân vào cuộc hành trình để đời, cùng với người anh trai trung thành Loki, người có ma thuật mới chớm nở trang bị cho anh ta đủ phép thuật để gây ra rắc rối, cùng với Warriors Three - một nhóm du khách khoe khoang không muốn ra khơi trong bất kỳ cuộc phiêu lưu nào có thể thực sự nguy hiểm. Nhưng khởi đầu là một cuộc truy tìm kho báu vô hại nhanh chóng trở nên chết chóc, và giờ đây Thor phải chứng tỏ mình xứng đáng với số phận mà anh khao khát bằng cách cứu lấy chính Asgard.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Wolf","avatar":""},{"name":"Rick Gomez","avatar":""},{"name":"Alistair Abell","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Paul Dobson","avatar":""},{"name":"Chris Britton","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jay Brazeau","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Ron Halder","avatar":""},{"name":"Cathy Weseluck","avatar":""},{"name":"Michael Dobson","avatar":""},{"name":"John Novak","avatar":""},{"name":"Mark Acheson","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Mark Gibbon","avatar":""},{"name":"Jillian Michaels","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Ve","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-