INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xong-hoi', 'Xông Hơi', '247 Degrees Fahrenheit', 'https://phimimg.com/upload/vod/20231129-1/5dcacad1532936f92e81555270699025.jpg', 'https://phimimg.com/upload/vod/20231129-1/412c82378c0fcaf19a7b2835dd85471a.jpg', '<p>Bốn người bạn đi đến một căn nhà gỗ ven hồ để nghỉ cuối tuần vô tư, nhưng niềm vui biến thành cơn ác mộng khi 3 người họ bị nhốt trong phòng tắm hơi nóng. Mỗi phút đều có giá trị và mọi mức độ đều quan trọng khi họ chiến đấu để giành lấy mạng sống của mình trong cái nóng lên tới 247°F.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scout Taylor-Compton","avatar":""},{"name":"Travis Van Winkle","avatar":""},{"name":"Michael Copon","avatar":""},{"name":"Christina Ulloa","avatar":""},{"name":"Tyler Mane","avatar":""},{"name":"Michael Andrew","avatar":""},{"name":"George Dugashvili","avatar":""},{"name":"Rene Etore","avatar":""},{"name":"Tornike Gogrichiani","avatar":""},{"name":"Ibrahim Idowu","avatar":""},{"name":"Misha Arobelidze","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
