INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-hu-gio', 'Đồi Hú Gió', 'Wuthering Heights', 'https://phimimg.com/upload/vod/20231125-1/55055d8d470650274e6ec806a0056775.jpg', 'https://phimimg.com/upload/vod/20231125-1/995a59d17ea2c6ca2f3824e6786472b7.jpg', '<p>Đồng hoang Yorkshire, miền bắc nước Anh, vào cuối thế kỷ 18. Heathcliff trẻ tuổi, được giải cứu khỏi đường phố Liverpool bởi ông Earnshaw, chủ sở hữu của Wuthering Heights, một trang trại biệt lập, qua nhiều năm phát triển một niềm đam mê điên cuồng với Cathy, em gái nuôi của anh ta, một nỗi ám ảnh bệnh hoạn định mệnh kết thúc một cách bi thảm.</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kaya Scodelario","avatar":""},{"name":"James Howson","avatar":""},{"name":"Solomon Glave","avatar":""},{"name":"Shannon Beer","avatar":""},{"name":"Steve Evets","avatar":""},{"name":"Oliver Milburn","avatar":""},{"name":"Paul Hilton","avatar":""},{"name":"Simone Jackson","avatar":""},{"name":"Lee Shaw","avatar":""},{"name":"James Northcote","avatar":""},{"name":"Amy Wren","avatar":""},{"name":"Nichola Burley","avatar":""},{"name":"Adam Lock","avatar":""},{"name":"Eve Coverley","avatar":""},{"name":"Jonny Powell","avatar":""},{"name":"Emma Ropner","avatar":""},{"name":"Richard Guy","avatar":""},{"name":"Michael Hughes","avatar":""},{"name":"Pau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
