INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-dao', 'Dì Đào', 'A Simple Life', 'https://phimimg.com/upload/vod/20231125-1/a4a57ff4aa4359f23ee2a3c26e91ea78.jpg', 'https://phimimg.com/upload/vod/20231125-1/bc0a80a122b2172e9e5546e9bb5d267d.jpg', '<p>Bộ phim kể về câu chuyện tình người cảm động giữa một thiếu gia danh gia Roger và dì Đào, người nô bộc đã nuôi nấng anh từ tấm bé. Dì Đào làm việc cho gia đình Roger đã 60 năm trời, phục vụ, chăm sóc cho năm thế hệ trong gia đình. Tới nay, tuổi cao sức yếu chẳng may bị trúng gió. Tình cảnh khiến Roger bỗng cảm thấy hoang mang. Công việc bận rộn bản thân còn chẳng lo nổi, anh đành phải đưa dì Đào vào viện dưỡng lão. Và câu chuyện cảm động được bắt đầu từ đây…</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Qin Hailu","avatar":""},{"name":"Wang Fuli","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Leung Tin","avatar":""},{"name":"Hui Siu-ying","avatar":""},{"name":"Hui Pik-Kei","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""},{"name":"Yu Man-Si","avatar":""},{"name":"Jason Chan Chi-San","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Eman Lam Yi-Man","avatar":""},{"name":"Lam Yee-Lok","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Ning Hao","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Tsui Ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
