INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-ngoc-rong', 'Truy Tìm Ngọc Rồng', 'The Dragon Pearl', 'https://phimimg.com/upload/vod/20231125-1/73b845b532a1ea451274674bbe792499.jpg', 'https://phimimg.com/upload/vod/20231125-1/1e12bc4cacdfa97f1ee3e13d036d7130.jpg', '<p>Josh và Ling đang mong đợi một kỳ nghỉ nhàm chán khi đến thăm cha mẹ của họ tại một cuộc khai quật khảo cổ ở Trung Quốc. Nhưng những người bạn mới sớm phát hiện ra rằng họ đang ở giữa một cuộc phiêu lưu khi họ tìm thấy một con Rồng Vàng Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Sam Neill","avatar":""},{"name":"Louis Corbett","avatar":""},{"name":"Li Lin Jin","avatar":""},{"name":"Ji Wang","avatar":""},{"name":"Robert Mammone","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Chen Bao Yuan","avatar":""},{"name":"Junkang Wang","avatar":""},{"name":"Peter Powell","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324471);
