INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-thinh-phong-van-2', 'Thiết Thính Phong Vân 2', 'Overheard 2', 'https://phimimg.com/upload/vod/20231125-1/306a1c84e22060d2a68e95d24389b468.jpg', 'https://phimimg.com/upload/vod/20231125-1/74aab0977e9230c77c68b977ca8f8399.jpg', '<p>Phần 2 của bộ phim điện ảnh đình đám hè 2009 - Overheard 2 (tên tiếng Trung là Thiết thính phong vân) đã công bố trailer và poster chính thức vào ngày hôm qua – 30/6. Cùng với đó, khán giả cũng đã nhận được lời hứa “chắc nịch” từ phía nhà sản xuất về ngày công chiếu 18/8 của phim. Nhịp độ dồn dập cùng với những dòng chữ xuất hiện liên tiếp: ”Năm 1965, chỉ số Hang Seng (chỉ số chứng khoán của Hồng Kông) giảm 24.71%”, “Năm 1993, chỉ số Hang Seng giảm 10000 điểm”, “Năm 2008, thị trường tài chính lâm vào khủng hoảng”… đã phần nào hé lộ không khí “căng như dây đàn” của bộ phim.Trong đoạn trailer, ngoài những hình ảnh, con số về chứng khoán – tài chính thì những hình ảnh về ba đàn anh ...</p>', 'Full', 1, 'single', 'completed', 7, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Daniel Wu","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Chiao Chiao","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Ai Kong","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Jane Wong","avatar":""},{"name":"Ben Yuen Foo-Wa","avatar":""},{"name":"Patricia Tang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c