INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-hong', 'Giáng Sinh Hồng', 'A very Pink Christmas', 'https://phimimg.com/upload/vod/20231125-1/f2ac5b574adb9eb17a26f5f9baf699d3.jpg', 'https://phimimg.com/upload/vod/20231125-1/2ed3b73b64fbef7d57272a9f1c21a1a2.jpg', '<p>Giáng Sinh Hồng - A very Pink Christmas là câu chuyện kể về Pink Panther và Big Nose đối mặt với nhau để xem ai có thể kiếm đủ tiền để mua chiếc xe thể thao xa hoa nhất thế giới. Nhưng khi Pink bắt gặp một cậu bé chỉ muốn mua một cái cây nhỏ cho gia đình mình, Pink gạt lòng tham sang một bên để khám phá ý nghĩa của việc thực sự kỷ niệm \</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeannie Elias","avatar":""},{"name":"Alex Nussbaum","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324471);
