INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-goi-cam', 'Chiến Binh Gợi Cảm', 'Sucker Punch', 'https://phimimg.com/upload/vod/20231125-1/a8e58e133834dc791e69fba713ba6adf.jpg', 'https://phimimg.com/upload/vod/20231125-1/a8af54f45826083cdc90c17413da4dba.jpg', '<p>Phim Chiến Binh Gợi Cảm của đạo diễn lừng danh Zack Snyder là một bộ phim hành động đầy táo bạo. Phim hd này với nội dung xoay quanh 5 nữ anh hùng gợi cảm và mạnh mẽ. Câu chuyện xoay quanh hành trình của nhân vật Baby Doll, một cô gái phải sống với người cha dượng độc ác đang âm mưu tẩy não mình. Để thoát khỏi những ám ảnh do bị điều khiển bởi máy móc trị liệu tâm thần, cô đã cùng 4 người bạn của mình lập kế hoạch trốn khỏi nơi họ bị giam dữ.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Browning","avatar":""},{"name":"Abbie Cornish","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Richard Cetrone","avatar":""},{"name":"Gerard Plunkett","avatar":""},{"name":"Malcolm Scott","avatar":""},{"name":"Ron Selmour","avatar":""},{"name":"A.C. Peterson","avatar":""},{"name":"Revard Dufresne","avatar":""},{"name":"Kelora Clingwall","avatar":""},{"name":"Frederique De Rauco","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
