INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-thu-2011', 'Trả Thù', 'Bangkok Revenge', 'https://phimimg.com/upload/vod/20231206-1/f924e368891a3b9501c5e5ff5220d891.jpg', 'https://phimimg.com/upload/vod/20231206-1/a18407038cf6d23c75119f0411be3694.jpg', '<p>Có vẻ gu hành động võ thuật đang được hướng đến Đông Nam Á sau nhiều thập kỉ bị thống trị bởi Đông Á thì phải. Mới mấy tháng trước thì chúng ta đã được mãn nhãn với những màn võ thuật không chê vào đâu được từ bộ phim The Raid Redemption thì hôm nay, trailer mới của bộ phim Bangkok Revenge cũng vừa được cho ra mắt, cũng máu lửa và tràn ngập những đòn thế ghê rợn. Bangkok Revenge có một cốt truyện cổ điển, một cậu bé chứng kiến cảnh gia đình bị giết năm 10 tuổi. Thế là bao nhiêu quyết tâm căm hờn của cậu đều dành hết vào việc trả thù. 20 năm, cậu bé trở lại, quyết tâm tìm được những kẻ đã sát hại gia đình mình.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Jon Foo","avatar":""},{"name":"Caroline Ducey","avatar":""},{"name":"Michaël Cohen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324471);
