INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-vai', 'Đổi Vai', 'The Change-Up', 'https://phimimg.com/upload/vod/20231125-1/bdeb30c3e099e1bcefd9b37a1c3b7060.jpg', 'https://phimimg.com/upload/vod/20231125-1/fcf194559ea60d12f74b9210ed81508c.jpg', '<p>Hai người đàn ông, tuy khác biệt là vậy, nhưng lại là hai người bạn thân thiết. Nhưng số phận đưa đẩy họ tới một định mệnh không ngờ: hoán đổi thân xác! Liệu một tay chơi vô lo vô nghĩ sẽ làm bố ra sao? Liệu một người đàn ông chính trực sẽ sống cuộc sống hoang đàng thế nào? Và quan trọng nhất, họ sẽ phải làm gì để trở về với cuộc sống đích thực của mình?</p>', 'Full', 1, 'single', 'completed', 8, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Gregory Itzin","avatar":""},{"name":"Mircea Monroe","avatar":""},{"name":"Sydney Rouviere","avatar":""},{"name":"Matthew Cornwell","avatar":""},{"name":"Craig Bierko","avatar":""},{"name":"TJ Hassan","avatar":""},{"name":"Ned Schmidtke","avatar":""},{"name":"Ming Lo","avatar":""},{"name":"Dax Griffin","avatar":""},{"name":"Andrea Moore","avatar":""},{"name":"Taaffe O''Connell","avatar":""},{"name":"Bailey Anne Borders","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
