INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-do-cua-tu-duy', 'Tốc Độ Của Tư Duy', 'The Speed of Thought', 'https://phimimg.com/upload/vod/20231124-1/93b1cf95613ed3ec872713d2d244e5ed.jpg', 'https://phimimg.com/upload/vod/20231124-1/fe91de2162401d0dffaf7eb1c5e54d6f.jpg', '<p>Joshua Lazarus (Nick Stahl) là một nhà ngoại cảm được nuôi dưỡng trong nhà nuôi dưỡng của NSA. Lazarus giúp chính phủ bằng cách sử dụng khả năng của mình. Anh ta được cơ quan cho biết rằng thần giao cách cảm là một tác dụng phụ của Bệnh Widmann, và anh ta sẽ trở nên mất trí theo thời gian và cuối cùng chết vì căn bệnh này. Tuy nhiên, Lazarus gặp một người phụ nữ có sức mạnh tương tự (Mía Maestro), người không có bất kỳ dấu hiệu nào của căn bệnh này, khiến Lazarus phải đối mặt với những lời dối trá mà anh ta đã nói.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Stahl","avatar":""},{"name":"Mía Maestro","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Blair Brown","avatar":""},{"name":"Evan Oppenheimer","avatar":""},{"name":"Alan Cox","avatar":""},{"name":"Erik Palladino","avatar":""},{"name":"Stefania Tortorella","avatar":""},{"name":"Jorge Sabaté","avatar":""},{"name":"Julio DePietro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324471);
