INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-x', 'Cô Nàng X', 'Julia X', 'https://phimimg.com/upload/vod/20231124-1/4b5a17246dfd5abab137a6d45628ca83.jpg', 'https://phimimg.com/upload/vod/20231124-1/836761883211b8e219dff7ee8fc636b2.jpg', '<p>Phim kể về một gã bệnh hoạn chuyên bắt những người phụ nữ trẻ hành hạ để lấy niềm vui. Một ngày hắn bắt được một cô gái trẻ, hắn ung dung dùng nhiều trò để uy hiếp, tra tấn cô. Nhưng rồi, vỏ quýt dày có móng tay nhọn, hắn gặp phải đối thủ, giờ đây hắn lại trở thành nạn nhân tiêu khiển cho những trò vui của cô gái và chị cô ấy...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Valerie Azlynn","avatar":""},{"name":"Kevin Sorbo","avatar":""},{"name":"Alicia Leigh Willis","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Saxon Sharbino","avatar":""},{"name":"Gregg Brazzel","avatar":""},{"name":"Meg Rains","avatar":""},{"name":"Kasi Scarbrough Corley","avatar":""},{"name":"Sarah Duncan","avatar":""},{"name":"Ted Ferguson","avatar":""},{"name":"Michael Kober","avatar":""},{"name":"James B. McDaniel","avatar":""},{"name":"Courtney Rawls","avatar":""},{"name":"Michael Showers","avatar":""},{"name":"Lindsay Small","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324471);
