INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-khong-the-thay-doi-the-gioi-chung-toi-muon-xay-mot-truong-hoc-o-campuchia', 'Tuy không thể thay đổi thế giới, chúng tôi muốn xây một trường học ở Campuchia', 'We Can''t Change the World. But, We Wanna Build a School in Cambodia.', 'https://phimimg.com/upload/vod/20231123-1/24bc435429f12bff994f5e3f88d8cbda.jpg', 'https://phimimg.com/upload/vod/20231123-1/ce0136b585203119baf342669949a070.jpg', '<p>Một sinh viên y khoa buồn chán và bạn bè của anh thề sẽ xây dựng một trường học cho trẻ em Campuchia, nhưng kế hoạch của họ bị đe dọa khi thực tế khắc nghiệt ập đến.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Osamu Mukai","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Masataka Kubota","avatar":""},{"name":"Eri Murakawa","avatar":""},{"name":"Mei Kurokawa","avatar":""},{"name":"Noriko Eguchi","avatar":""},{"name":"Masaya Kikawada","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Hiroshi Abe","avatar":""},{"name":"Hayato Matsunaga","avatar":""},{"name":"Mina Asakura","avatar":""},{"name":"Kokoro Asami","avatar":""},{"name":"Miyuki Matsushita","avatar":""},{"name":"Masaaki Nagakura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
