INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuy-khong-the-thay-doi-the-gioi-chung-toi-muon-xay-mot-truong-hoc-o-campuchia', 'Tuy không thể thay đổi thế giới, chúng tôi muốn xây một trường học ở Campuchia', 'We Can''t Change the World. But, We Wanna Build a School in Cambodia.', 'tuy không thể thay đổi thế giới, chúng tôi muốn xây một trường học ở campuchia we can''t change the world. but, we wanna build a school in cambodia. osamu mukai tori matsuzaka tasuku emoto masataka kubota eri murakawa mei kurokawa noriko eguchi masaya kikawada lily franky hiroshi abe hayato matsunaga mina asakura kokoro asami miyuki matsushita masaaki nagakura ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dup', 'Cú Đúp', 'The Double', 'https://phimimg.com/upload/vod/20231121-1/795b2de136bc3b33b0f99e9dde242d21.jpg', 'https://phimimg.com/upload/vod/20231121-1/8a56c78f837389048097e2b0c4a56188.jpg', '<p>Vụ ám sát bí ẩn một thượng nghị sĩ Hoa Kỳ mang nhãn hiệu đặc biệt của sát thủ huyền thoại Liên Xô &#39;Cassius&#39;, buộc nhân viên CIA đã nghỉ hưu, Paul Shepherson phải hợp tác với đặc vụ FBI tân binh, Ben Geary để phá án. Dành cả sự nghiệp của mình để theo đuổi Cassius, Shepherdson tin rằng kẻ thù của mình đã chết từ lâu, nhưng bị người giám sát cũ của anh, Tom Highland, thúc đẩy nhận vụ án. Geary, người đã viết luận văn Thạc sĩ về việc Shepherdson truy đuổi kẻ sát nhân Liên Xô, chắc chắn rằng Cassius đã xuất hiện trở lại.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Tamer Hassan","avatar":""},{"name":"Stephen Moyer","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Stana Katic","avatar":""},{"name":"Yuriy Sardarov","avatar":""},{"name":"Jeffrey Pierce","avatar":""},{"name":"Lawrence Gilliard Jr.","avatar":""},{"name":"Sonja Crosby","avatar":""},{"name":"Ed Kelly","avatar":""},{"name":"Dan Lemieux","avatar":""},{"name":"Ivan Fedorov","avatar":""},{"name":"Mike Kraft","avatar":""},{"name":"Randy Flagler","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324471);
