INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cu-dup', 'Cú Đúp', 'The Double', 'cú đúp the double richard gere topher grace martin sheen tamer hassan stephen moyer christopher marquette odette annable stana katic yuriy sardarov jeffrey pierce lawrence gilliard jr. sonja crosby ed kelly dan lemieux ivan fedorov mike kraft randy flagler ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1911', '1911', '1911', 'https://phimimg.com/upload/vod/20231121-1/8f3f916a76fc7d57f42ff01bf63415a2.jpg', 'https://phimimg.com/upload/vod/20231121-1/ac4c1b6e4279e74f27a6e04c3f146bb5.jpg', '<p>Vào đầu thế kỷ 20, Trung Quốc rơi vào tình trạng khủng hoảng. Đất nước bị chia cắt thành các phe phái chiến tranh, người dân đang chết đói và những cải cách chính trị gần đây đã khiến vấn đề trở nên tồi tệ hơn chứ không phải tốt hơn. Triều đại nhà Thanh đang cầm quyền, được lãnh đạo bởi một vị hoàng đế mới 7 tuổi, và người mẹ tàn nhẫn của ông, Thái hậu Longyu, đã hoàn toàn mất liên lạc sau 250 năm nắm quyền không cần bàn cãi. Huang Xing gần đây đã trở về từ Nhật Bản, nơi anh ấy đã nghiên cứu nghệ thuật chiến tranh hiện đại. Khi thấy đất nước của mình tan rã, anh ấy cảm thấy mình không còn lựa chọn nào khác ngoài việc cầm kiếm lên.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Jaycee Chan","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Hu Ge","avatar":""},{"name":"Ning Jing","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Yu Shaoqun","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Huang Zhizhong","avatar":""},{"name":"Mei Ting","avatar":""},{"name":"Simon Dutton","avatar":""},{"name":"James Lee Guy","avatar":""},{"name":"Li Dongxue","avatar":""},{"name":"Wang Ziwen","avatar":""},{"name":"Wei Zongwan","avatar":""},{"name":"Xie Gang","avatar":""},{"name":"Tao Zeru","avatar":""},{"name":"Xing Jiadong","avatar":""},{"name":"Wang Luyao","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324471);
