INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-bo-hao-hang', 'Món Bơ Hảo Hạng', 'Butter', 'https://phimimg.com/upload/vod/20231120-1/66e2f2ba5c79116f77a1d8b486be60b6.jpg', 'https://phimimg.com/upload/vod/20231120-1/5b31a09f8f2aa77d016186713f1a00c5.jpg', '<p>Món Bơ Hảo Hạng kể về Laura Pickler (Jennifer Garner), một người phụ nữ tham vọng có chồng là nhà điêu khắc tượng bơ nổi tiếng nhất thị trấn. Vì bực mình trước ý định từ bỏ vị trí số một của chồng, Laura đã quyết định tự mình sáng tạo ra phong cách riêng, ngày đêm khổ luyện để quay lại cuộc thi với quyết tâm giữ gìn vị trí độc tôn. Để giành chiến thắng, cô cũng không tiếc sử dụng mọi mánh khóe để lấn lướt đối thủ. Nhưng sau cùng, liệu Laura có đạt được mục đích của mình?</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Garner","avatar":""},{"name":"Yara Shahidi","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Phyllis Smith","avatar":""},{"name":"Garrett Schenck","avatar":""},{"name":"Judy Leavell","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Deana Ricks","avatar":""},{"name":"Kelly Tippens","avatar":""},{"name":"Dodie Brown","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
