INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-duc-chon-cong-so', 'Tình Dục Chốn Công Sở', 'MicroSex Office', 'https://phimimg.com/upload/vod/20231123-1/a2518dac55c13436eb4ada2f1e7a7f85.jpg', 'https://phimimg.com/upload/vod/20231123-1/07ba61c5972954051287b2d95190d5ed.jpg', '<p>Ngày xửa ngày xưa ở Hồng Kông, có một công ty dầu y học cổ truyền gần như phá sản. Tuy nhiên, đội ngũ nhân viên cứng nhắc và buồn chán của nó - người quản lý xấu tính Ben Chow, Tyson nhếch nhác, Hatou thiếu tình yêu và cô gái mới không biết gì Rachel - không có gì tốt hơn để làm ngoài việc tưởng tượng về tất cả các kiểu trốn thoát tình dục trong những căn phòng nhỏ buồn tẻ lạnh lẽo của họ. Rất may, công ty của họ được tiếp quản bởi một doanh nghiệp đồ chơi người lớn đến từ Trung Quốc, và giấc mơ ướt át của họ trở thành sự thật khi bốn đồng nghiệp mới ngon lành đến khuấy động cuộc sống văn phòng của họ!</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Koni Lui","avatar":""},{"name":"Chak Hoi-Tai","avatar":""},{"name":"Harriet Yeung","avatar":""},{"name":"Jacquline Chong","avatar":""},{"name":"Dada Chan","avatar":""},{"name":"Chen Zhi-Ming","avatar":""},{"name":"Yedda Chao Tong","avatar":""},{"name":"Bonnie Wong","avatar":""},{"name":"Terence Tsui Chi-Hung","avatar":""},{"name":"Gill Mohindepaul Singh","avatar":""},{"name":"Dino Acconci","avatar":""},{"name":"Julio Acconci","avatar":""},{"name":"Hugo Leung","avatar":""},{"name":"Cheema Daljit Singh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
