INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-thang', 'Chiến Thắng', 'Win Win', 'https://phimimg.com/upload/vod/20231123-1/5cc299f99149ffe51fcd68119e2fbb56.jpg', 'https://phimimg.com/upload/vod/20231123-1/f43ecbf3a1dc099fd4ddbc69f761b911.jpg', '<p>Khi huấn luyện viên đấu vật bán thời gian ở trường trung học kém may mắn Mike đồng ý trở thành người giám hộ hợp pháp cho một người đàn ông lớn tuổi, đứa cháu trai rắc rối của người được giám hộ của ông hóa ra lại trở thành một vận động viên vật lộn ngôi sao, khơi dậy ước mơ giành chiến thắng lớn -- cho đến khi mẹ của cậu bé lấy anh ta.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Giamatti","avatar":""},{"name":"Alex Shaffer","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Burt Young","avatar":""},{"name":"Nina Arianda","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Clare Foley","avatar":""},{"name":"David W. Thompson","avatar":""},{"name":"Marcia Haufrecht","avatar":""},{"name":"Sharon Wilkins","avatar":""},{"name":"Penelope Kindred","avatar":""},{"name":"Sophie Kindred","avatar":""},{"name":"Tim Ransom","avatar":""},{"name":"Marceline","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
