INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han-hoang-hon', 'Giới Hạn Hoàng Hôn', 'The Sunset Limited', 'https://phimimg.com/upload/vod/20231123-1/413f54995dfddb8b9aa4e7bc9eb2162e.jpg', 'https://phimimg.com/upload/vod/20231123-1/d51e3402b430080e3868f0c5463c13a8.jpg', '<p>Một cựu tù nhân da đen có tôn giáo sâu sắc đã ngăn cản nỗ lực tự tử của một giáo sư đại học da trắng phi xã hội, người đang cố ném mình trước một chuyến tàu điện ngầm đang chạy tới, &#39;The Sunset Limited.&#39; Khi một người cố gắng kết nối ở mức độ lý trí, tinh thần và cảm xúc, thì người kia vẫn kiên định trong nỗi tuyệt vọng khó kiếm được của mình. Bị mắc kẹt trong một cuộc tranh luận triết học, cả hai đều nhiệt tình bảo vệ quan điểm cá nhân của mình và cố gắng chuyển đổi đối phương.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Samuel L. Jackson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
