INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-11-truy-tim-mu-rom', 'Đảo Hải Tặc 11: Truy Tìm Mũ Rơm', 'One Piece 3D: Straw Hat Chase', 'https://phimimg.com/upload/vod/20231123-1/cfbc1c2c3b13620b3b367574fdadec38.jpg', 'https://phimimg.com/upload/vod/20231123-1/39a0c2f4c49f4c07a578ae130b28d30d.jpg', '<p>Vua Hải Tặc 3D: Truy tìm mũ rơm – Câu chuyện nói về một ngày của nhóm Mũ Rơm. Khi thức dậy, vị thuyền trưởng phát hiện chiếc mũ yêu quý của mình đã đi đâu mất và cuống cuồng đi tìm khắp nơi. Và thế là tất cả thuyền viên trên Sunny Going bắt đầu lao vào tìm kiếm. Trong quá trình tìm kiếm, nhóm phải chống lại từ hải quân đến quái vật biển và cuối cùng là đến ngay một căn cứ hải quân. Cuộc chiến hải tặc – hải quân lại bắt đầu và một câu chuyện cảm động giữa 2 thuyền viên “không bình thường” trên một con tàu hải tặc vừa giải tán.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Cho","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Tomomitsu Yamaguchi","avatar":""},{"name":"Takeshi Kusao","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324471);
