INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-tan-cong', 'Tổng Tấn Công', 'Attack the Block', 'https://phimimg.com/upload/vod/20231123-1/8994247c98dff0a3898185e1fd7023ad.jpg', 'https://phimimg.com/upload/vod/20231123-1/cddbb5d72ac136bdf40597f1acfaf813.jpg', '<p>Nội dung phim xoay quanh Moses (John Boyega) và nhóm bạn quậy phá của cậu giết chết một sinh vật kỳ lạ trong công viên ở Nam London. Xác của con vật, chiến lợi phẩm, được lôi về khu chung cư cả lũ đang sống. Từ đây, các sinh vật ngoài hành tinh bắt đầu xuất hiện. Moses và lũ bạn từ thợ săn, đã trở thành con mồi. Điều bất ngờ là sau khi Trái Đất bị những sinh vật ngoài hành tinh tấn công, một nhóm trẻ ngỗ ngược đã đã trở thành những người duy nhất chống lại sự xâm lăng của chúng trước sự ngỡ ngàng của nhiều người...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"John Boyega","avatar":""},{"name":"Jodie Whittaker","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Alex Esmail","avatar":""},{"name":"Luke Treadaway","avatar":""},{"name":"Selom Awadzi","avatar":""},{"name":"Franz Drameh","avatar":""},{"name":"Simon Howard","avatar":""},{"name":"Jumayn Hunter","avatar":""},{"name":"Leeon Jones","avatar":""},{"name":"Sammy Williams","avatar":""},{"name":"Michael Ajao","avatar":""},{"name":"Paige Meade","avatar":""},{"name":"Danielle Vitalis","avatar":""},{"name":"Gina Antwi","avatar":""},{"name":"Natasha Jones","avatar":""},{"name":"Terry Notary","avatar":""},{"name":"Chris Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng",