INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-giua', 'Kẹt Giữa', 'The Inbetweeners Movie', 'https://phimimg.com/upload/vod/20231123-1/35b3d6b3d77b046d746381f9f43ee307.jpg', 'https://phimimg.com/upload/vod/20231123-1/6bc8a57ccd23f32f8aea4de3a374799a.jpg', '<p>Will, Simon, Jay và Neil là bốn cậu bé gặp phải vấn đề trong gia đình: Simon mới bị người yêu bỏ, ông nội của Jay mất và cha của Will dự định sẽ cưới tình nhân của ông. Neil dẫn cả nhóm tới Malia, Crete để nghỉ mát. Ở đây họ gặp bốn cô gái và cả bốn bắt đầu tìm cách tán tỉnh một trong số các cô gái này.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Simon Bird","avatar":""},{"name":"James Buckley","avatar":""},{"name":"Blake Harrison","avatar":""},{"name":"Joe Thomas","avatar":""},{"name":"Emily Head","avatar":""},{"name":"Lydia Rose Bewley","avatar":""},{"name":"Laura Haddock","avatar":""},{"name":"Tamla Kari","avatar":""},{"name":"Jessica Knappett","avatar":""},{"name":"Theo Barklem-Biggs","avatar":""},{"name":"Theo James","avatar":""},{"name":"Anthony Stewart Head","avatar":""},{"name":"Victoria Willing","avatar":""},{"name":"Greg Davies","avatar":""},{"name":"Henry Lloyd-Hughes","avatar":""},{"name":"Belinda Stewart-Wil","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
