INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-nong', 'Điểm Nóng', 'Red State', 'https://phimimg.com/upload/vod/20231120-1/ecc6ad61a277a2f77b1ae34e641a350d.jpg', 'https://phimimg.com/upload/vod/20231120-1/735dadc5e430d9e8ef83c57b9e4d92ba.jpg', '<p>Ba thanh thiếu niên chấp nhận một lời mời trên mạng đến tham dự một buổi sex tập thể. Thế nhưng họ đã gặp mục sư Abin Cooper bệnh hoạn cùng với những phần tử đang lên một kế hoạch khủng khiếp. Một màn cuồng sát ghê rợn diễn ra. Liệu số phận của những thanh thiếu niên kia sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Parks","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Kerry Bishé","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Matt Jones","avatar":""},{"name":"Kevin Alejandro","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"Anna Gunn","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Betty Aberlin","avatar":""},{"name":"Jennifer Schwalbach Smith","avatar":""},{"name":"Patrick Fischler","avatar":""},{"name":"Damian You","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
