INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-chim-canh-cut-2', 'Vũ Điệu Chim Cánh Cụt 2', 'Happy Feet Two', 'https://phimimg.com/upload/vod/20231201-1/0c3fc0f19d15d2384dff20202d84cec1.jpg', 'https://phimimg.com/upload/vod/20231201-1/076f4189a240eab4c9eb232b083655b8.jpg', '<p>Chú chim cánh cụt Mumble có một vấn đề: con trai Erik, người không muốn khiêu vũ, chạm trán với The Mighty Sven, một chú chim cánh cụt có thể bay! Mọi thứ trở nên tồi tệ hơn với Mumble khi thế giới bị rung chuyển bởi những thế lực mạnh mẽ, khiến anh phải tập hợp các quốc gia chim cánh cụt và đồng minh của họ để giải quyết mọi việc.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2011, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Pink","avatar":""},{"name":"Elizabeth Daily","avatar":""},{"name":"Johnny A. Sanchez","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Common","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Jeffrey Garcia","avatar":""},{"name":"Ava Acres","avatar":""},{"name":"Benjamin Flores Jr.","avatar":""},{"name":"Meibh Campbell","avatar":""},{"name":"Magda Szubanski","avatar":""},{"name":"Hank Azar","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
