INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-ky-hiep-lu', 'Thần kỳ hiệp lữ', 'Mr. & Mrs. Incredible', 'https://phimimg.com/upload/vod/20231116-1/fbf4d39ea81709fdbd3f357db0419711.jpg', 'https://phimimg.com/upload/vod/20231116-1/d87b25d69fe7ac3e1f1568c124a0f85a.jpg', '<p>Hai siêu anh hùng nghỉ việc để vui với đời sống hôn nhân tại một ngôi làng nhỏ, nhưng nhận ra gây dựng hạnh phúc gia đình còn khó hơn chiến đấu với kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Wang Bo-chieh","avatar":""},{"name":"Wowkie Zhang","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Liang Long","avatar":""},{"name":"Wang Dongfang","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Zhang Aiqin","avatar":""},{"name":"Zhou Bo","avatar":""},{"name":"Wen Zhang","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Steven Fung Min-Hang","avatar":""},{"name":"Vincent Kok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
