INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-cua-tintin', 'Những Cuộc Phiêu Lưu Của Tintin', 'The Adventures of Tintin', 'https://phimimg.com/upload/vod/20231120-1/64eab830468b5e957883533771da7877.jpg', 'https://phimimg.com/upload/vod/20231120-1/4ac543f5635d38b743ff77ce4a44d9ff.jpg', '<p>Trong bộ phim hoạt hình 3D đầu tiên nói về nhân vật Tintin này, Daniel Craig vào vai tên tội phạm Ivanovich Sakharine, Jamie Bell trong vai thám tử Tintin, Andy Serkis vai thuyền trưởng Haddock, Simon Pegg và Nick Frost trong vai cặp thám tử song sinh Thomson và Thompson. Nội dung bộ phim xoay quanh cuộc gặp gỡ giữa Tintin với thuyền trưởng Haddock. Cả hai tình cờ phát hiện ra sự thật về con tàu chở kho báu mang tên Unicorn bị đánh chìm hàng trăm năm về trước. Cả hai cùng lên đường đi tìm sự thật về kho báu này. Bộ phim sử dụng công nghệ bắt hình động chính xác đến từng chi tiết nhưng vẫn đảm bảo sự phóng đại, cường điệu không thể thiếu của một bộ phim hoạt hình và tràn ngập những pha hành động lẫn các tình huống hài hước.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2011, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Jamie Bell","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"Gad Elmaleh","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Enn Reitel","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Sonje Fortag","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Phillip Rhys","avatar":""},{"name":"Ron Bottitta","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Sebastian Roché","avatar":""},{"name":"Kim Stengel","avatar":""},{"name":"Abraham Justice","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324471);
