INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-chu-muu', 'Kẻ Chủ Mưu', 'The Conspirator', 'https://phimimg.com/upload/vod/20231119-1/2638c595d4470ee48dc66413f8ea6aa8.jpg', 'https://phimimg.com/upload/vod/20231119-1/7ab5f87b157edd800a8b8273fe4de391.jpg', '<p>Mary Surratt là người phụ nữ duy nhất bị buộc tội tham gia vào âm mưu ám sát tổng thống Abraham Lincoln trong tổng số 8 người bị bắt. Khi cả đất nước quay lưng lại với cô, cô chỉ còn có thể dựa vào người luật sư miễn cưỡng của mình để bào chữa và minh oan cho bản thân Mary. Chàng luật sư trẻ Frederick Aiken ban đầu không muốn tham gia vào vụ kiện này, nhưng dần dần anh đã thấy những dấu hiệu chứng tỏ rằng có vẻ như Mary thực sự vô tội.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Gerald","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324471);
