INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('seconds-apart', 'Seconds Apart', 'Seconds Apart', 'https://phimimg.com/upload/vod/20231119-1/b6e4a3d738409595f2e2464d4e254659.jpg', 'https://phimimg.com/upload/vod/20231119-1/675d318b7675062b590f2571a906fbf1.jpg', '<p>Seth và Jonah là cặp song sinh với khả năng nguy hiểm: Thần giao cách cảm. Mọi thứ bắt đầu xoay quanh sự kiểm soát của họ khi các bạn cùng lớp của họ kết thúc theo những cách xoắn và kỳ quái. Cảnh sát nghi ngờ họ. Nhưng, sự ghen tuông bắt đầu phân chia chúng và chẳng mấy chốc họ không còn tin tưởng lẫn nhau. Dẫn đến một trận chiến khủng khiếp chống lại chính họ.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Orlando Jones","avatar":""},{"name":"Edmund Entin","avatar":""},{"name":"Gary Entin","avatar":""},{"name":"Samantha Droke","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Morgana Shaw","avatar":""},{"name":"Stephanie Richards","avatar":""},{"name":"Abby Chapman","avatar":""},{"name":"Tate Chapman","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
