INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-kich-luc-nua-dem', 'Truy Kích Lúc Nửa Đêm', 'Sleepless Night', 'https://phimimg.com/upload/vod/20231116-1/e06940468b84a8ef6fa16161e5e45619.jpg', 'https://phimimg.com/upload/vod/20231116-1/4704449b1c0d3fc010daa8f4123253e0.jpg', '<p>Phim nói về một phi vụ cứu con trai của cảnh sát Vincent cùng với đồng nghiệp. Họ cùng nhau phá vụ án buôn ma túy của ông chủ hộp đêm là Jose. Nhưng bọn chúng đã bắt cóc con trai của Vincent để đòi lại số tài sản thất thoát. Phim Truy Kích Lúc Nữa Đêm nói về nhiệm vụ khó khăn của hai cảnh sát làm sao cứu đươc con trai đồng thời bắt được tội phạm?</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Tomer Sisley","avatar":""},{"name":"Serge Riaboukine","avatar":""},{"name":"Julien Boisselier","avatar":""},{"name":"JoeyStarr","avatar":""},{"name":"Laurent Stocker","avatar":""},{"name":"Birol Ünel","avatar":""},{"name":"Lizzie Brocheré","avatar":""},{"name":"Samy Seghir","avatar":""},{"name":"Dominique Bettenfeld","avatar":""},{"name":"Adel Bencherif","avatar":""},{"name":"Pom Klementieff","avatar":""},{"name":"Catalina Denis","avatar":""},{"name":"Vincent Bersoulle","avatar":""},{"name":"Olivier Massart","avatar":""},{"name":"Cécile Boland","avatar":""},{"name":"Hervé Sogne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
