INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-quoc-basara-bua-tiec-cuoi-cung', 'Chiến Quốc Basara: Bữa Tiệc Cuối Cùng', 'Gekijouban Sengoku Basara: The Last Party', 'https://phimimg.com/upload/vod/20231129-1/69425437789f243e7a08c57fae90f0c8.jpg', 'https://phimimg.com/upload/vod/20231129-1/fe790fdf5747fd5ab053aa5922e3da43.jpg', '<p>Sengoku Basara The Last Party lấy bối cảnh dựa theo nguyên tác game Sengoku Basara Samurai Heroes trên hệ máy PS3 với cốt truyện chính xoay quanh cuộc giao tranh giành quyền thống nhất Nhật Bản giữa hai thế lực Miền Đông Nhật Bản (Đông Quân) và Miền Tây Nhật Bản (Tây Quân) tại Sekigahara (Quan Ngã Nguyên) vào năm 1600. Do anime có cốt truyện riêng khác hẳn với game nên sẽ có nhiều tình tiết bị thay đổi.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuya Nakai","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Soichiro Hoshi","avatar":""},{"name":"Toru Okawa","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Masakazu Morita","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Tessyo Genda","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324471);
