INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-nhan', 'Nạn Nhân', 'The Victim', 'null', 'https://phimimg.com/upload/vod/20231129-1/cc58bb4ec7cba1ff4bad37a2b5d46c21.jpg', '<p>Cuộc sống của Annie gặp nguy hiểm sau khi cô chứng kiến vụ cưỡng hiếp và sát hại người bạn thân nhất của mình. Chạy trốn khỏi hai kẻ tấn công, cô tình cờ gặp Kyle, một người ẩn dật sống giữa rừng. Kyle thấy sự tĩnh lặng của khu rừng thật thoải mái. Kẻ cô độc đẹp trai thô kệch ở cách xa nền văn minh - nghĩa là - cho đến khi một tiếng gõ cửa khiến cuộc sống đơn độc của anh ta rơi vào hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Biehn","avatar":""},{"name":"Jennifer Blanc","avatar":""},{"name":"Ryan Honey","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Denny Kirkwood","avatar":""},{"name":"Tanya Newbould","avatar":""},{"name":"Dana Daurey","avatar":""},{"name":"Alyssa Lobit","avatar":""},{"name":"Samuel N. Benavides","avatar":""},{"name":"Nicole Bilderback","avatar":""},{"name":"Phoebe Price","avatar":""},{"name":"Kym Jackson","avatar":""},{"name":"Amy Honey","avatar":""},{"name":"Brianne Davis","avatar":""},{"name":"Jamielyn Lippman","avatar":""},{"name":"J.C. Brandy","avatar":""},{"name":"Caitlin Keat","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324471);
