INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oslo-ngay-31-thang-8', 'Oslo, Ngày 31 Tháng 8', 'Oslo, 31. august', 'https://phimimg.com/upload/vod/20231128-1/9058eeca8212c0bba698c64fdfaf423d.jpg', 'https://phimimg.com/upload/vod/20231128-1/276d12e86df9499b9f544f0a2811d494.jpg', '<p>Một ngày nọ trong cuộc đời của Anders, một thanh niên nghiện ma túy đang hồi phục, anh xin phép rời trung tâm điều trị một thời gian ngắn để phỏng vấn xin việc và gặp lại những người bạn cũ ở Oslo.</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anders Danielsen Lie","avatar":""},{"name":"Malin Crépin","avatar":""},{"name":"Hans Olav Brenner","avatar":""},{"name":"Ingrid Olava","avatar":""},{"name":"Tone Beate Mostraum","avatar":""},{"name":"Øystein Røger","avatar":""},{"name":"Aksel Thanke","avatar":""},{"name":"Kjærsti Odden Skjeldal","avatar":""},{"name":"Renate Reinsve","avatar":""},{"name":"Anders Borchgrevink","avatar":""},{"name":"Petter Width Kristiansen","avatar":""},{"name":"Johanne Kjellevik Ledang","avatar":""},{"name":"Iselin Steiro","avatar":""},{"name":"Elin Gun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
