INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-truyen-nhiem', 'Sự Truyền Nhiễm', 'Contagion', 'https://phimimg.com/upload/vod/20231117-1/5f0789bc2ce0b9f3531d071dbdad1d28.jpg', 'https://phimimg.com/upload/vod/20231117-1/0f3bec666e38c5a73f7e3db98da07615.jpg', '<p>Một nữ doanh nhân Beth Emhoff bỗngđột ngột qua đời vì một căn bệnh không rõ nguồn gốc sau chuyến công tác ở Hồng Kông. Vài ngày sau, số lượng người chết có triệu chứng như Beth Emhoff ngày một tăng trên toàn thế giới. Để cứu nguy cho nhân loại, Trung tâm Kiểm soát dịch bệnh Hoa Kỳ đã bắt tay vào nghiên cứu một loại vắc-xin phòng bệnh. Nhiều sinh mạng đã phải đánh đổi và câu trả lời về nguồn gốc dịch bệnh chỉ được hé mở ở những phút cuối cùng… &nbsp;Là một phim khoa học giả tưởng dựa trên những tình tiết có thật, “Contagion” đã xuất sắc mang về doanh thu 135 triệu USD cho hãng Warner Bros Picture và khẳng định phong độ của đạo diễn Steve Soderbreg. Ngoài ra sự góp mặt của dàn sao đã từng nhận các giải thưởng lớn như Matt Damon, Jude Law, Marion Cotillard, Gwyneth Paltrow, Bryan Cranston, Kate Winslet cũng góp phần mang lại thành công của phim.</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Chin Han","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Anna Jacoby-Heron","avatar":""},{"name":"Sanaa Lathan","avatar":""},{"name":"Demetri Martin","avatar":""},{"name":"Armin Rohde","avatar":""},{"name":"Enrico Colantoni","avatar":""},{"name":"Larry Clarke","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324471);
