INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-lon-de-sup-do', 'Quá Lớn Để Sụp Đổ', 'Too Big to Fail', 'https://phimimg.com/upload/vod/20231117-1/c86482d613f266ca045e5dfff9f48e66.jpg', 'https://phimimg.com/upload/vod/20231117-1/4824c793950d2df8dbf31df3b79e5fa3.jpg', '<p>Một cái nhìn sâu sắc về cuộc khủng hoảng tài chính nghiêm trọng năm 2008 và những người đàn ông và phụ nữ quyền lực đã quyết định số phận của nền kinh tế thế giới chỉ trong vài tuần.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Hurt","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"James Woods","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Fiona Choi","avatar":""},{"name":"Evan Handler","avatar":""},{"name":"Joey Slotnick","avatar":""},{"name":"Peter Hermann","avatar":""},{"name":"Michael O''Keefe","avatar":""},{"name":"Maria Bartiromo","avatar":""},{"name":"Chance Kelly","avatar":""},{"name":"Ben Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
