INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gnomeo-va-juliet', 'Gnomeo và Juliet', 'Gnomeo & Juliet', 'https://phimimg.com/upload/vod/20231117-1/a5dd306a33175bead851d914cdce3d5a.jpg', 'https://phimimg.com/upload/vod/20231117-1/2be6c3fd6d0f99d10803b01c888c14aa.jpg', '<p>Bộ phim được thực hiện tác phẩm kinh điển Romeo &amp; Juliet của đại văn hào Shakespeare. Câu chuyện tình yêu vĩ đại nhất mọi thời đại đã được đạo diễn Kelly Asbury biến hóa thành một bộ phim hoạt hình hài với các nhân vật chính là những chú lùn thường được làm tượng trang trí trong vườn. Gnomeo và Juliet phải vượt qua nhiều trở ngại để đến với nhau sau khi họ cũng bị cuốn vào một mối hận thù giữa hai dòng tộc láng giềng. Liệu đôi trẻ sẽ có một kết thúc có hậu hay không, tất cả còn chờ khán giả ở phía trước...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Ashley Jensen","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Ozzy Osbourne","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Dolly Parton","avatar":""},{"name":"Hulk Hogan","avatar":""},{"name":"Richard Wilson","avatar":""},{"name":"Julio Bonet","avatar":""},{"name":"Julia Braams","avatar":""},{"name":"James Dan","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
