INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-lap', 'Thiết Lập', 'Setup', 'https://phimimg.com/upload/vod/20231115-1/609bcd5d2a4c1342efc9504239c430e5.jpg', 'https://phimimg.com/upload/vod/20231115-1/248cad734f61e1becf237e283aa26039.jpg', '<p>Một nhóm bạn thiết lập kế hoạch chi tiết một vụ cướp, nhưng kế hoạch đã bị thay đổi khi có một kẻ phản bội và cao chạy xa bay với các hàng hóa cướp được. Sonny đã lập 1 đội đi trả thù kẻ phản bội và lấy lại những gì thuộc về mình. Cuối cùng, khi đối mặt với kẻ phản bội cũng chính là người bạn thân thiết nhiều năm, Sonny buộc phải đưa ra một quyết định sống còn...</p>', 'Full', 1, 'single', 'completed', 10, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"50 Cent","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"James Remar","avatar":""},{"name":"Randy Couture","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Susie Abromeit","avatar":""},{"name":"Jay Karnes","avatar":""},{"name":"Jordan Trovillion","avatar":""},{"name":"Ambyr Childers","avatar":""},{"name":"Jenna Dewan","avatar":""},{"name":"Omar J. Dorsey","avatar":""},{"name":"Theo Kypri","avatar":""},{"name":"Richard Goteri","avatar":""},{"name":"Rory Markham","avatar":""},{"name":"Brett Granstaff","avatar":""},{"name":"Ralph Liste","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
