INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ten-an-hai', 'Ba Tên Ăn Hại', 'Delhi Belly', 'https://phimimg.com/upload/vod/20231115-1/17641e3fb32fb7ae0d8af6f6c7d1f5bb.jpg', 'https://phimimg.com/upload/vod/20231115-1/53e92feea0dc0d4058a5f9513c27e322.jpg', '<p>Ba người đàn ông bình thường, không nghi ngờ gì thấy mình nằm trong danh sách tấn công của một trong những tập đoàn tội phạm quyền lực nhất Ấn Độ.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Imran Khan","avatar":""},{"name":"Kunaal Roy Kapur","avatar":""},{"name":"Vir Das","avatar":""},{"name":"Shenaz Treasury","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Raju Kher","avatar":""},{"name":"Vijay Raaz","avatar":""},{"name":"Lushin Dubey","avatar":""},{"name":"Paresh Ganatra","avatar":""},{"name":"Rahul Singh","avatar":""},{"name":"Rajendra Sethi","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Anusha Dhandekar","avatar":""},{"name":"Aamir Khan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
