INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tuan-voi-kieu-nu', 'Một Tuần Với Kiều Nữ', 'My Week with Marilyn', 'https://phimimg.com/upload/vod/20231114-1/2304409dd8c03227b354ac53c8017398.jpg', 'https://phimimg.com/upload/vod/20231114-1/8c87306fcfd4745a212502d4a3a0b4f4.jpg', '<p>Một Tuần Với Kiều Nữ - My Week With Marilyn là câu chuyện về mối tình đầu ngắn ngủi, vô vọng mà chàng trai trẻ Colin Clark (Eddie Redmayne) dành cho nữ minh tinh số 1 thế giới Marilyn Monroe (Michelle Williams). Chuyện xảy ra trên phim trường The Prince and the Showgirl (1957). Khi đó, Colin là một chàng trợ lý đạo diễn chân ướt chân ráo bước vào nghề. Họ cùng nhau trải qua một tuần ngọt ngào với một mối quan hệ có thể xem là “chuyện tình trong sáng” dù đằng sau đó là biết bao nghi vấn, giống như nhiều bí ẩn trong cuộc đời huyền thoại màn bạc thế kỷ 20.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Michelle Williams","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Eddie Redmayne","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Philip Jackson","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Michael Kitchen","avatar":""},{"name":"Julia Ormond","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Zoë Wanamaker","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Richard Clifford","avatar":""},{"name":"Robert P","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
