INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-tuan-voi-kieu-nu', 'Một Tuần Với Kiều Nữ', 'My Week with Marilyn', 'một tuần với kiều nữ my week with marilyn michelle williams kenneth branagh eddie redmayne dominic cooper philip jackson derek jacobi toby jones michael kitchen julia ormond simon russell beale dougray scott zoë wanamaker emma watson judi dench jim carter richard clifford robert p ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-quang-khan-do', 'Cô Gái Quàng Khăn Đỏ', 'Red Riding Hood', 'https://phimimg.com/upload/vod/20231113-1/d0ae4264aba78e504bd749df7e877851.jpg', 'https://phimimg.com/upload/vod/20231113-1/656e3d16a74ca143af28e399b030d639.jpg', '<p>Valerie đang yêu một người ngoài cuộc đang ấp ủ, Peter, nhưng cha mẹ cô đã sắp xếp cho cô kết hôn với một người đàn ông khác. Không muốn mất nhau, Valerie và Peter dự định cùng nhau bỏ trốn khi chị gái của Valerie bị giết bởi một người sói lảng vảng trong khu rừng tối bao quanh ngôi làng của họ. Sự hoảng loạn bao trùm thị trấn khi Valerie phát hiện ra rằng cô có một mối liên hệ độc nhất vô nhị với con quái vật - thứ đã lôi kéo họ lại với nhau một cách không thể lay chuyển, khiến cô vừa bị nghi ngờ... vừa là con mồi</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Shiloh Fernandez","avatar":""},{"name":"Max Irons","avatar":""},{"name":"Julie Christie","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Shauna Kain","avatar":""},{"name":"Michael Hogan","avatar":""},{"name":"Adrian Holmes","avatar":""},{"name":"Cole Heppell","avatar":""},{"name":"Christine Willes","avatar":""},{"name":"Michael Shanks","avatar":""},{"name":"Kacey Rohl","avatar":""},{"name":"Megan Charpentier","avatar":""},{"name":"D.J. Greenburg","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gi