INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sleep-tight', 'Sleep Tight', 'Sleep Tight', 'https://phimimg.com/upload/vod/20231113-1/c982cc27ee939941c3458b88701d852f.jpg', 'https://phimimg.com/upload/vod/20231113-1/a3338079fd9af9e8c08a2a0ac4362f6d.jpg', '<p>Căn hộ hướng dẫn viên Cesar (Luis Tosar) là một người khốn khổ, người tin rằng anh ta được sinh ra mà không có khả năng hạnh phúc. Kết quả là, ông quyết định sứ mệnh của mình là biến cuộc sống của mình đối với mọi người xung quanh. Phần lớn người thuê rất dễ dàng để kích động, nhưng Clara (Marta Etura) chứng tỏ khó khăn hơn nhiều so với nhiều nhất. Vì vậy, Cesar đi đến cực kỳ đáng sợ để khiến người phụ nữ trẻ này bị phá vỡ về mặt tinh thần. Mọi thứ trở nên phức tạp hơn nữa trong mối quan hệ xoắn này khi bạn trai của cô, Marcos (Alberto San Juan), xuất hiện.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Luis Tosar","avatar":""},{"name":"Marta Etura","avatar":""},{"name":"Alberto San Juan","avatar":""},{"name":"Petra Martínez","avatar":""},{"name":"Iris Almeida","avatar":""},{"name":"Carlos Lasarte","avatar":""},{"name":"Amparo Fernández","avatar":""},{"name":"Roger Morilla","avatar":""},{"name":"Pep Tosar","avatar":""},{"name":"Margarita Roset","avatar":""},{"name":"Manel Dueso","avatar":""},{"name":"Tony Corvillo","avatar":""},{"name":"Ricard Sadurní","avatar":""},{"name":"Xavier Pujolràs","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324471);
