INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-ngoat-2', 'Bước Ngoặt 2', 'Turning Point 2', 'https://phimimg.com/upload/vod/20231114-1/5ce7ba48bef467ca80324edae76f4614.jpg', 'https://phimimg.com/upload/vod/20231114-1/77c141a84e975bba7caab3774cb4768f.jpg', '<p>Sau khi giết chết tay trùm Co Què Tô Tinh Bá (Huỳnh Tông Trạch), Laughing (Tạ Thiên Hoa) phải chịu án tù và vô tình gặp được người bạn tù là Hoắc Thiên Nhậm (Ngô Trấn Vũ) - một giáo sư tâm lí học bị kết tội tàng trữ ma túy. Mặc dù bề ngoài lịch thiệp nhưng ông là một kẻ máu lạnh. Hơn nữa ông dùng khả năng của mình đã có thể kiểm soát âm thầm những người khác. Nghi ngờ rằng một vụ việc liên quan đến lực lượng cảnh sát tham nhũng, Phó Bí thư Cảnh sát An ninh đã giao nhiệm vụ cho Laughing điều tra chân tướng trong khi anh đang là tù nhân.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Tse","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Bosco Wong","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Kate Tsui","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Jin Au-Yeung","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"Jacqueline Chan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324471);
