INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giap-sat', 'Giáp Sắt', 'Ironclad', 'https://phimimg.com/upload/vod/20231114-1/17a3164ae2abb35e76f4db9d69c4a809.jpg', 'https://phimimg.com/upload/vod/20231114-1/74b0ce4f051b3beb0168a45330907a7d.jpg', '<p>Năm 1215, vua John của Anh bị buộc phải ký bộ luật Magna Carta, đảm bảo quyền tự do của công dân. Giận dữ vì bị tước đoạt quyền lợi, ông ta cùng đội lính đánh thuê bắt đầu cướp bóc đất nước. Nhưng một trong những trở ngại cuối cùng đến thành London chính là lâu đài Rochester. Trong đó có những hiệp sĩ dũng cảm sẵn sàng tử thủ trong một trận chiến đẩm máu cuối cùng.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"James Purefoy","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Aneurin Barnard","avatar":""},{"name":"Jamie Foreman","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Rhys Parry Jones","avatar":""},{"name":"Vladimir Kulich","avatar":""},{"name":"David Melville","avatar":""},{"name":"Annabelle Apsion","avatar":""},{"name":"Steffan Rhodri","avatar":""},{"name":"Daniel O''Meara","avatar":""},{"name":"Bree","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324471);
