INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-it-cua-thien-duong', 'Một Ít Của Thiên Đường', 'A Little Bit of Heaven', 'https://phimimg.com/upload/vod/20231114-1/16d4b0b5dd7db7e1fe2959ff107907ef.jpg', 'https://phimimg.com/upload/vod/20231114-1/ff49d622c49d05f217e5557ff1b7d5ba.jpg', '<p>Phim xoay quanh một người đàn ông đã kết hôn dính vào một chuyện tình với một người phụ nữ trẻ tuổi, mặc dù anh sớm bắt đầu nghi ngờ cô có thể là bóng ma của một người phụ nữ đã chết từ lâu...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Hudson","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Steven Weber","avatar":""},{"name":"Johann Urb","avatar":""},{"name":"Bailey Bass","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
