INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-ca-map', 'Đầm Cá Mập', 'Shark Night 3D', 'https://phimimg.com/upload/vod/20231115-1/d63281bab3f5aec067ed49511850a959.jpg', 'https://phimimg.com/upload/vod/20231115-1/9d25c392aa8b33c89b452e4a11ca9a31.jpg', '<p>Một nhóm bạn trẻ tổ chức kỳ nghỉ cuối tuần ở ngôi nhà bên hồ tại vịnh Louisiana. Mọi thứ trong kỳ nghỉ đều hoàn hảo như là trong mơ đối với các câu trai cô gái mới lớn đang hừng hực sức trẻ tuổi dậy thì. Nhưng giấc mơ hoàn hảo đột nhiên trở thành cơn ác mộng khi họ là mục tiêu tấn công của con cá mập nước ngọt khổng lồ.</p>', 'Full', 1, 'single', 'completed', 9, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sara Paxton","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Chris Carmack","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Chris Zylka","avatar":""},{"name":"Katharine McPhee","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Damon Lipari","avatar":""},{"name":"Sinqua Walls","avatar":""},{"name":"Christine Bently","avatar":""},{"name":"Alyssa Diaz","avatar":""},{"name":"Jimmy Lee Jr.","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Kelly Sry","avatar":""},{"name":"Tyler Bryan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324471);
