INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sharpay-phieu-luu-ky', 'Sharpay Phiêu Lưu Ký', 'Sharpay''s Fabulous Adventure', 'https://phimimg.com/upload/vod/20231115-1/f70b69f22d8230766b594d170507fa71.jpg', 'https://phimimg.com/upload/vod/20231115-1/7b300f24f939496db569edae7dfb4387.jpg', '<p>Phim kể về việc sau khi được phát hiện trong một cuộc thi tài năng, Sharpay cùng chú cún cưng Boi quyết định rời khỏi Southwest và tới Broadway, để thi thố tài năng nhằm thực hiện ước mơ được có mặt trong vở kịch The Great White Way...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ashley Tisdale","avatar":""},{"name":"Austin Butler","avatar":""},{"name":"Cameron Goodman","avatar":""},{"name":"Bradley Steven Perry","avatar":""},{"name":"Lucas Grabeel","avatar":""},{"name":"Alec Mapa","avatar":""},{"name":"Jack Plotnick","avatar":""},{"name":"Robert Curtis Brown","avatar":""},{"name":"Jessica Tuck","avatar":""},{"name":"Pat Mastroianni","avatar":""},{"name":"Mike ''Nug'' Nahrgang","avatar":""},{"name":"Alessandra Cannito","avatar":""},{"name":"Lauren Collins","avatar":""},{"name":"Shadia Ali","avatar":""},{"name":"Sarah Joy Ben","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324471);
