INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('swat-doi-dac-nhiem', 'S.W.A.T.: Đội Đặc Nhiệm', 'S.W.A.T.: Firefight', 'https://phimimg.com/upload/vod/20231115-1/d69518684daa9822ed78e3149ce5ef8c.jpg', 'https://phimimg.com/upload/vod/20231115-1/ca490c45f1cdff9c944e687871c40277.jpg', '<p>S.W.A.T là tên đội đặc nhiệm cảnh sát Los Angeles. Câu chuyện xoay quanh đội của Hondo. Vì một lỗi lầm trong lúc giải thoát con tin mà Jim Street và đồng nghiệp của anh bị tách ra. Anh chàng kia bị đuổi việc còn Jim thì bị giáng chức xuống làm người giữ đồ. Nhờ sự bảo lãnh của Hondo mà Jim trở lại làm cảnh sát đặc nhiệm và được gửi đi huấn luyện. Trong đội còn có Sanchez - cô gái xinh đẹp nhưng bản lãnh không thua đàn ông và TJ - kẻ luôn cạnh tranh với Jim. Họ đã có những ngày tháng bên nhau thật vui vẻ, đoàn kết...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Carly Pope","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Kristanna Loken","avatar":""},{"name":"Matt Bushell","avatar":""},{"name":"Nicholas Gonzalez","avatar":""},{"name":"Shannon Kane","avatar":""},{"name":"Gino Anthony Pesi","avatar":""},{"name":"Kevin Phillips","avatar":""},{"name":"Dennis North","avatar":""},{"name":"Brad Bukauskas","avatar":""},{"name":"Yuriy Sardarov","avatar":""},{"name":"Darcy Leutzinger","avatar":""},{"name":"Iris Frank","avatar":""},{"name":"Tim Holmes","avatar":""},{"name":"Tru H","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
