INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-so-bong-dem', 'Đừng Sợ Bóng Đêm', 'Don''t Be Afraid of the Dark', 'https://phimimg.com/upload/vod/20231115-1/101fdb97b4f33d68266cee5c5f438e96.jpg', 'https://phimimg.com/upload/vod/20231115-1/3b9ee3141c0d61540872bec13e27e287.jpg', '<p>Được làm lại từ bộ phim truyền hình cùng tên vào năm 1973, Don&#39;t Be Afraid of The Dark kể về một gia đình sống trong tòa lâu đài cổ được xây dựng từ thế kỷ 19 đang được tu sửa lại.Trong khi khám phá lâu đài rực rỡ, Sally phát hiện ra một tầng hầm cổ xưa . Vô tình, cô bé vô tình giải thoát cho loài quái vật cổ đại, chúng tìm mọi cách để kéo gia đình Sally rơi xuống&quot; độ sâu không đáy&quot; của ngôi nhà huyền bí . Sally phải thuyết phục cha mình là Alex và cô bạn gái của ông - Kim - tin vào sự tồn tại của những bóng đen dưới thềm nhà trước khi mọi việc trở nên muộn màng.</p>', 'Full', 1, 'single', 'completed', 20, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Holmes","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Emelia Burns","avatar":""},{"name":"Nicholas Bell","avatar":""},{"name":"James Mackay","avatar":""},{"name":"Eddie Ritchard","avatar":""},{"name":"Bruce Gleeson","avatar":""},{"name":"Gary McDonald","avatar":""},{"name":"Carolyn Shakespeare-Allen","avatar":""},{"name":"Julia Blake","avatar":""},{"name":"Trudy Hellier","avatar":""},{"name":"Terry Kenwrick","avatar":""},{"name":"Grant Piro","avatar":""},{"name":"Todd MacDonald","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
