INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-thuat-bong-tien', 'Chiến Thuật Bóng - Tiền', 'Moneyball', 'https://phimimg.com/upload/vod/20231113-1/9f4d8ca680fbc7fcfe16d4baf52b03d9.jpg', 'https://phimimg.com/upload/vod/20231113-1/b915c318b25e55d29e5aec87b952c0f6.jpg', '<p>Nản lòng vì đội bóng chày của mình không đủ tiền mua cầu thủ đắt giá, giám đốc Billy Beane của Oakland A đặt cược vào chiến lược mới đầy táo bạo để thay đổi cuộc chơi.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Stephen Bishop","avatar":""},{"name":"Reed Diamond","avatar":""},{"name":"Brent Jennings","avatar":""},{"name":"Ken Medlock","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Vyto Ruginis","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Casey Bond","avatar":""},{"name":"Nick Porrazzo","avatar":""},{"name":"Kerris Dorsey","avatar":""},{"name":"Arliss","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
