INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-thuat-bong-tien', 'Chiến Thuật Bóng - Tiền', 'Moneyball', 'chiến thuật bóng - tiền moneyball brad pitt jonah hill philip seymour hoffman robin wright chris pratt stephen bishop reed diamond brent jennings ken medlock tammy blanchard jack mcgee vyto ruginis nick searcy glenn morshower casey bond nick porrazzo kerris dorsey arliss ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hobo-with-a-shotgun', 'Hobo with a Shotgun', 'Hobo with a Shotgun', 'https://phimimg.com/upload/vod/20231113-1/4591de7aa58aec227d44cc1cefb61541.jpg', 'https://phimimg.com/upload/vod/20231113-1/e665c9ef38a126c9462b70663529e5c4.jpg', '<p>Một người đàn ông vô gia cư cảnh giác kéo vào một thành phố mới và thấy mình bị mắc kẹt trong sự hỗn loạn đô thị, một thành phố nơi các quy tắc tội phạm và nơi ông trùm tội phạm của thành phố ngự trị. Nhìn thấy một cảnh quan đô thị đầy những tên cướp có vũ trang, cảnh sát tham nhũng, gái mại dâm bị lạm dụng và thậm chí là một ông già Noel ấu dâm, Hobo bắt đầu mang lại công lý cho thành phố theo cách tốt nhất mà anh ta biết - với một khẩu súng ngắn cỡ 20. Tình trạng lộn xộn xảy ra khi anh ấy cố gắng làm mọi thứ tốt hơn cho thế hệ tương lai. Công lý đường phố sẽ thực sự chiếm ưu thế.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Rutger Hauer","avatar":""},{"name":"Molly Dunsworth","avatar":""},{"name":"Gregory Smith","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"Brian Downey","avatar":""},{"name":"Nick Bateman","avatar":""},{"name":"Peter Simas","avatar":""},{"name":"Pasha Ebrahimi","avatar":""},{"name":"Jeremy Akerman","avatar":""},{"name":"David Brunt","avatar":""},{"name":"Brain Jamieson","avatar":""},{"name":"Duane Patterson","avatar":""},{"name":"Agnes Laan","avatar":""},{"name":"Andre Haines","avatar":""},{"name":"Tim Dunn","avatar":""},{"name":"Drew O''Hara","avatar":""},{"name":"Glen Matthews","avatar":""},{"name":"Zack Tove","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
