INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hobo-with-a-shotgun', 'Hobo with a Shotgun', 'Hobo with a Shotgun', 'hobo with a shotgun hobo with a shotgun rutger hauer molly dunsworth gregory smith robb wells brian downey nick bateman peter simas pasha ebrahimi jeremy akerman david brunt brain jamieson duane patterson agnes laan andre haines tim dunn drew o''hara glen matthews zack tove ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum', 'Xì Trum', 'The Smurfs', 'https://phimimg.com/upload/vod/20231112-1/01b158ca33b0d9c2ea212e1b4bfa2542.jpg', 'https://phimimg.com/upload/vod/20231112-1/fab589c6b53dfb72d2721757a2f79d5a.jpg', '<p>Lão phù thủy độc ác Gargamel rượt đưổi các chú xì - trum ra khỏi ngôi làng của mình. Tình cờ họ đã vô tình lạc vào hang động cấm mà không biết đó chính là Blue moon , một cánh cửa thần kỳ giúp đưa các xì trum đến thời hiện tại ở công viên Trung tâm New York. Họ đã phải nương náu tại nhà của một cặp đôi mới cưới và tìm cách quay trở lại ngôi làng của họ trước khi lão Gargamel tóm gọn.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hank Azaria","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jayma Mays","avatar":""},{"name":"Jonathan Winters","avatar":""},{"name":"Katy Perry","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Tim Gunn","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Madison McKinley","avatar":""},{"name":"Meg Phillips","avatar":""},{"name":"Mahadeo Shivraj","avatar":""},{"name":"Julie Chang","avatar":""},{"name":"Mark Doherty","avatar":""},{"name":"Minglie Chen","avatar":""},{"name":"Sean Kenin","avatar":""},{"name":"Victor Pagan","avatar":""},{"name":"Adria Bar","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324471);
