INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xi-trum', 'Xì Trum', 'The Smurfs', 'xì trum the smurfs hank azaria neil patrick harris jayma mays jonathan winters katy perry anton yelchin sofía vergara tim gunn frank welker madison mckinley meg phillips mahadeo shivraj julie chang mark doherty minglie chen sean kenin victor pagan adria bar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-chia-khoa-bi-an', 'Chiếc Chìa Khóa Bí Ẩn', 'Extremely Loud & Incredibly Close', 'https://phimimg.com/upload/vod/20231112-1/7f5c31328506d11c341c70f01cdcf653.jpg', 'https://phimimg.com/upload/vod/20231112-1/e27fb3ce975dab07275a635589192789.jpg', '<p>Extremely Loud and Incredibly Close (Chiếc Chìa Khóa Bí Ẩn) xoay quanh nhân vật cậu bé Oskar Schell, một đứa trẻ 9 tuổi khác thường, rất thích phiêu lưu và luôn tự cho mình là một nhà phát minh nghiệp dư, nhà thiết kế đồ trang sức, nhà thiên văn, một nhà khoa học ăn chay và một người theo chủ nghĩa hòa bình. Sau cái chết của bố mình hôm 11/09 tại Trung Tâm Thương Mại Thế Giới, cậu tìm được một chiếc chìa khóa bí mật của ông, cậu liền lao vào một cuộc phiêu lưu kì lạ - một cuộc tìm kiếm bí mật, cấp bách trong 5 khu vực dân cư tại thành phố New York. Khi Oskar đi khắp thành phố, cậu bé gặp phải đủ loại người đang tìm mọi cách để sống sót và tồn tại. Cuối cùng, chuyến phiêu lưu của Oska cũng kết thúc tại nơi mà cậu bé khởi hành, nhưng cậu đã tìm được một thứ trải nghiệm có ý nghĩa nhất đối với mỗi con người , đó là sự yêu thương.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Thomas Horn","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Zoe Caldwell","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Dennis Hearn","avatar":""},{"name":"Paul Klementowicz","avatar":""},{"name":"Julian Tepper","avatar":""},{"name":"Caleb Reynolds","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Lorna Guity Pruce","avatar":""},{"name":"Hazelle Goodman","avatar":""},{"name":"Bernadette Dray","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
