INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-hoan-luong', 'Con Đường Hoàn Lương', 'Inside Out', 'https://phimimg.com/upload/vod/20231111-1/cf6b392c57d92e57b0f7ff6754be15b9.jpg', 'https://phimimg.com/upload/vod/20231111-1/832eacbc451d72b1d1285cf59e0ea5c3.jpg', '<p>Con Đường Hoàn Lương - Inside Out xoay quanh AJ -người chịu án tù 13 năm vì tội ngộ sát kẻ có ý định giết chết người bạn tốt nhất của mình là Jack. Sau khi được phóng thích, AJ không muốn gì hơn là bắt đầu làm một công việc kinh doanh nhỏ và sống cuộc sống tự do không tội ác. Thật không may, trong vòng vài giờ rời khỏi nhà tù, Jack lại dính líu đến AJ trong một vụ tai nạn bắn chết một người đàn ông.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Michael Lévesque","avatar":""},{"name":"Juliette Goglia","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Julie White","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Michael Cudlitz","avatar":""},{"name":"Jency Griffin","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Juli Erickson","avatar":""},{"name":"Danny Epper","avatar":""},{"name":"Mike Agresta","avatar":""},{"name":"John Chambers","avatar":""},{"name":"Allen Boudreaux","avatar":""},{"name":"Edward Cummings","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324471);
