INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-toan-trum-mafia', 'Thanh Toán Trùm Mafia', 'Kill the Irishman', 'https://phimimg.com/upload/vod/20231111-1/b6d29489d5110c66dde1f76b6850c3be.jpg', 'https://phimimg.com/upload/vod/20231111-1/a3d5bd999ad4186bc8525204218bef8b.jpg', '<p>Kill the Irishman là bộ phim tâm lý - hình sự dựa trên một câu chuyện có thật về một tay xã hội đen khó chơi người Ailen làm việc cho các tổ chức ngầm ở Cleveland trong những năm 70. Trong phim lấy bối cảnh năm 1976, Cleveland - Ohio, một cuộc chiến băng đảng lớn đã nổ ra giữa băng của trùm xã hội đen Ailen Danny Grenne và mafia Ý khi Greene mở một chiến dịch nhằm mục đích mở rộng lãnh thổ của mình tại Cleveland...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Stevenson","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Tony Darrow","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Jason Butler Harner","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Tony Lo Bianco","avatar":""},{"name":"Laura Ramsey","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"Paul Sorvino","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324471);
