INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-lam-chong-ban', 'Yêu Lầm Chồng Bạn', 'Something Borrowed', 'https://phimimg.com/upload/vod/20231111-1/1ef00ce919f02ed174c98bcccb811a75.jpg', 'https://phimimg.com/upload/vod/20231111-1/52fe021b67d4d1bd6e471d3c2b05281e.jpg', '<p>Mặc dù Rachel là một luật sư thành đạt và một người bạn trung thành, hào phóng nhưng cô vẫn độc thân. Sau một lần uống quá nhiều trong lễ kỷ niệm sinh nhật lần thứ 30 của mình, Rachel bất ngờ lên giường với người cô yêu lâu năm, Dex – người tình cờ đính hôn với người bạn thân nhất của cô, Darcy. Sự phân nhánh của mối liên lạc có nguy cơ phá hủy tình bạn trọn đời của những người phụ nữ, trong khi Ethan, bạn tâm giao của Rachel, lại che giấu một bí mật có khả năng bùng nổ của riêng anh ta.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ginnifer Goodwin","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Ashley Williams","avatar":""},{"name":"Geoff Pierson","avatar":""},{"name":"Jill Eikenberry","avatar":""},{"name":"Jonathan Epstein","avatar":""},{"name":"Leia Thompson","avatar":""},{"name":"Sarah Baldwin","avatar":""},{"name":"Mark LaMura","avatar":""},{"name":"Lindsay Ryan","avatar":""},{"name":"Kirsten Day","avatar":""},{"name":"Christopher Peuler","avatar":""},{"name":"Herb Lieberz","avatar":""},{"name":"Jimmy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
