INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ve-thien-nien-ky-rong', 'Huyền Thoại Về Thiên Niên Kỷ Rồng', 'Legend of the Millennium Dragon', 'https://phimimg.com/upload/vod/20231113-1/266f9d7dffffc08c6974dfe879bc0c3e.jpg', 'https://phimimg.com/upload/vod/20231113-1/3acc394b0a75055a6cd3594d3b645afd.jpg', '<p>Một cuộc hành trình ngoạn mục của một anh hùng trẻ tuổi bất đắc dĩ bị đẩy vào một quá khứ bí ẩn đầy quái vật, rồng và những sức mạnh tiềm ẩn kỳ lạ. Thông qua một loạt các trận chiến và cuộc phiêu lưu ngoài thế giới này, Jun, một cậu học sinh cấp hai nhút nhát, được biến thành một anh hùng có sứ mệnh chiến đấu với cái ác và đảm bảo sự hài hòa và yên bình trên thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satomi Ishihara","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Sôsuke Komori","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Takashi Kondo","avatar":""},{"name":"Masaaki Tsukada","avatar":""},{"name":"Shunsuke Sakuya","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Akio Nojima","avatar":""},{"name":"Anri Katsu","avatar":""},{"name":"Chikara Ousaka","avatar":""},{"name":"Hidenori Takahashi","avatar":""},{"name":"Ikuo Nishikawa","avatar":""},{"name":"Kanako Toujou","avatar":""},{"name":"Katsuhi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"685