INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-ngu-lam-2', 'Ba Chàng Ngự Lâm 2', 'The Hangover Part II', 'https://phimimg.com/upload/vod/20231113-1/9f09667ca6657ae57ae4e39ea2c858d0.jpg', 'https://phimimg.com/upload/vod/20231113-1/8f136834bf59133c60fa576b5f01ecde.jpg', '<p>Bốn chàng trai Stu, Phil, Alan và Doug tới Bangkok để tổ chức tiệc chia tay độc thân cho Stu trước khi anh kết hôn. Tuy nhiên, mọi việc một lần nữa lại không tuân theo kế hoạch. Sau một đêm &quot;thác loạn&quot;, Teddy - em rể tương lai của Stu - biến mất. Stu, Phil và Alan tỉnh dậy trong một nhà nghỉ rẻ tiền ở Bangkok. Trên mặt Stu xuất hiện một hình xăm to, Alan thì bị cạo trọc đầu, một con khỉ mặc quần áo xuất hiện. Ba chàng &quot;ngự lâm&quot; phải nhanh chóng tìm ra Teddy trước khi diễn ra đám cưới của Stu. Nhiều sự kiện trớ trêu xảy đến khiến nhóm bạn gặp phải bao rắc rối tại xứ Chùa Vàng, Thái Lan....</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Mason Lee","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Sasha Barrese","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"Aroon Seeboonruang","avatar":""},{"name":"Nirut Sirijanya","avatar":""},{"name":"Yasmin Lee","avatar":""},{"name":"Nick Cassavetes","avatar":""},{"name":"Sondra Currie","avatar":""},{"name":"Bryan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324471);
