INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-do-dinh-menh', 'Bản Đồ Định Mệnh', 'The Adjustment Bureau', 'https://phimimg.com/upload/vod/20231113-1/73ff8328f383476a96285613f23f1831.jpg', 'https://phimimg.com/upload/vod/20231113-1/9b3ceefa44b5d5f941257ba13f687ce5.jpg', '<p>Một người đàn ông nhìn thấy tương lai mà Định mệnh đã lên kế hoạch cho anh ta - và chọn chiến đấu cho số phận của chính mình. Chiến đấu với Cục điều chỉnh quyền lực trên khắp, dưới và qua các đường phố của New York, anh ta mạo hiểm sự vĩ đại của định mệnh để được ở bên người phụ nữ duy nhất anh ta từng yêu.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Shane McRae","avatar":""},{"name":"Lisa Thoreson","avatar":""},{"name":"Florence Kastriner","avatar":""},{"name":"Natalie Carter","avatar":""},{"name":"Phyllis MacBryde","avatar":""},{"name":"Chuck Scarborough","avatar":""},{"name":"Jon Stewart","avatar":""},{"name":"Kar Fearon","avatar":""},{"name":"RJ Konner","avatar":""},{"name":"Susan D. Michaels","avatar":""},{"name":"Gregory P. Hi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324471);
