INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('below-zero', 'Below Zero', 'Below Zero', 'https://phimimg.com/upload/vod/20231113-1/c260f82d013286c4ffce6eccea8e7c97.jpg', 'https://phimimg.com/upload/vod/20231113-1/1f2e859ee83aad12f3ea149bfc7c6ed1.jpg', '<p>Dựa trên các sự kiện thực sự, dưới Zero là một phim kinh dị với cảm giác &#39;Fargo&#39;. Đó là câu chuyện về &#39;Jack the hack&#39;, ít hơn mức trung bình, nhưng một khi kịch bản biên kịch thành công, bây giờ phải đối mặt với khối nhà văn. Mong muốn đáp ứng thời hạn tiết kiệm nghề nghiệp và khóa những kẻ gây phiền nhiễu về cuộc sống bối rối của mình, Jack sắp xếp để bị bỏ lại một mình và bị khóa bên trong một tiệm làm mát thịt, chỉ với những bữa ăn chay và trí tưởng tượng của anh ta để truyền cảm hứng cho anh ta. Khi nhiệt độ giảm, các đường giữa thực tế và mờ ảo, và kịch bản của Jack đến nguy hiểm cho cuộc sống. Anh ta sẽ thực hiện thời hạn quan trọng nhất trong sự nghiệp của mình? Hoặc là jack &#39;chỉ là một hack&#39;? Trong khi viết kịch bản, nhà biên kịch thực tế và nhà sản xuất dưới 0, Signe Olynyk, được sắp xếp để tự khóa vật lý trong tủ đông thịt của một lò mổ từ xa bị bỏ hoang. Đó là một phần câu chuyện này phát triển. Nó được quay tại cùng một vị trí.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Edward Furlong","avatar":""},{"name":"Michael Berryman","avatar":""},{"name":"Kristin Booth","avatar":""},{"name":"Michael Eisner","avatar":""},{"name":"Dee Hanna","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324471);
