INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-chi', 'Ý Chí', 'Will', 'https://phimimg.com/upload/vod/20231111-1/65cb1bbdb4a872494ee466215f6fdc80.jpg', 'https://phimimg.com/upload/vod/20231111-1/7427f1f4017d758193694cd4180e582e.jpg', '<p>Brennan là cổ động viên số một của Liverpool, có thể kể lại vô số sự thật về câu lạc bộ và tại một trường công lập ở miền nam nước Anh kể từ khi cha anh, Gareth, vô cảm, không thể chăm sóc cho anh sau cái chết của mẹ Will. Một ngày nọ, Gareth xuất hiện bất ngờ với tấm vé tham dự trận Chung kết Champions League 2005 của Liverpool tại Istanbul.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Damian Lewis","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Rebekah Staton","avatar":""},{"name":"Perry Eggleton","avatar":""},{"name":"Kieran Wallbanks","avatar":""},{"name":"Malcolm Storry","avatar":""},{"name":"Harvey Walsh","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Brandon Robinson","avatar":""},{"name":"Jane March","avatar":""},{"name":"Karen Crean","avatar":""},{"name":"Kristian Kiehling","avatar":""},{"name":"Kenny Dalglish","avatar":""},{"name":"Neil Maskell","avatar":""},{"name":"Branko Tomović","avatar":""},{"name":"Steven Gerrard","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324471);
