INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhay-mua-tu-do', 'Nhảy múa tự do', 'Footloose', 'https://phimimg.com/upload/vod/20231111-1/ef1f8f36de89cad38963397c8c4c3954.jpg', 'https://phimimg.com/upload/vod/20231111-1/4586b570360e74083c008d8ffcb1a907.jpg', '<p>Mắc kẹt ở một thị trấn nhỏ nơi khiêu vũ là phạm pháp, cậu thiếu niên ở thành phố lớn thách thức pháp luật khi phải lòng cô con gái nổi loạn của một mục sư địa phương.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Kenny Wormald","avatar":""},{"name":"Julianne Hough","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"Patrick John Flueger","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"Ziah Colon","avatar":""},{"name":"Ser''Darius Blain","avatar":""},{"name":"L. Warren Young","avatar":""},{"name":"Brett Rice","avatar":""},{"name":"Maggie Elizabeth Jones","avatar":""},{"name":"Mary-Charles Jones","avatar":""},{"name":"Enisha Brewster","avatar":""},{"name":"Josh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
