INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-los-angeles', 'Đại Chiến Los Angeles', 'Battle: Los Angeles', 'https://phimimg.com/upload/vod/20231111-1/8467d519bb2c2f4b04d40393547ca5a8.jpg', 'https://phimimg.com/upload/vod/20231111-1/a48e1228e6b5f78a8fcee722968ca841.jpg', '<p>Một buổi sáng đẹp trời, bờ biển Los Angeles đột ngột bị tấn công bởi những UFO đến từ vũ trụ, manh nha chiếm đoạt nguồn nước trên Trái Đất. Thành phố phút chốc biến thành đống đổ nát, xác người la liệt trên những con đường. Một trung sĩ lính thủy đánh bộ đã nghỉ hưu cùng những người đồng đội mới tham gia trận chiến tại thành phố Los Angele chống lại những kẻ xâm lược ngoài hành tinh.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Ramón Rodríguez","avatar":""},{"name":"Will Rothhaar","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Joey King","avatar":""},{"name":"Beth Keener","avatar":""},{"name":"Jessica Heap","avatar":""},{"name":"Cory Hardrict","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Gino Anthony Pesi","avatar":""},{"name":"Ne-Yo","avatar":""},{"name":"James Hiroyuki Liao","avatar":""},{"name":"Adetokumboh M''Cormack","avatar":""},{"name":"Bryce Cass","avatar":""},{"name":"Michelle R","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324472);
