INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-bi-an', 'Chiến Binh Bí Ẩn', 'The Green Hornet', 'https://phimimg.com/upload/vod/20231111-1/97e9457e9eb6cdcf5ee83cd4e1c32904.jpg', 'https://phimimg.com/upload/vod/20231111-1/14f81f3eae8c3596447f78849324a34e.jpg', '<p>Britt Reid, người thừa kế gia tài báo chí lớn nhất ở Los Angeles, là một tay ăn chơi hư hỏng, cho đến nay vẫn hạnh phúc khi sống một cuộc sống không mục đích. Sau khi cha qua đời, Britt gặp Kato, một nhân viên tháo vát của công ty. Nhận ra rằng họ có tài năng và nguồn lực để làm nên điều gì đó của cuộc đời mình, Britt và Kato hợp lực với tư cách là những chiến binh tội phạm hàng đầu để hạ gục tên tội phạm mạnh nhất thành phố, Chudnofsky.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"Jay Chou","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Chad L. Coleman","avatar":""},{"name":"Jamie Harris","avatar":""},{"name":"Edward Furlong","avatar":""},{"name":"Jill Remez","avatar":""},{"name":"Joe O''Connor","avatar":""},{"name":"Morgan Rusler","avatar":""},{"name":"Joshua Erenberg","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"Taylor Cole","avatar":""},{"name":"Robert Clotworthy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324472);
