INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-tro-lai', 'Siêu Nhân Trở Lại', 'All Star Superman', 'https://phimimg.com/upload/vod/20231111-1/89dee405a7fc8ea45d5c90073702b93c.jpg', 'https://phimimg.com/upload/vod/20231111-1/9326367403908c6f8a9d96e18adc7f3d.jpg', '<p>Nội dung trong Phim All Star Superman là câu chuyện kể lại những hành động của tên ác nhân Lex Luthor, hắn là một người rất ranh ma và sảo quyệt, biết được điểm yếu của Superman, hắn đã lợi dụng 1 khả năng của Superman làm cho các tế bào của Superman hấp thụ 1 lượng rất lớn bức xạ mặt trời, để thực hiện những mục đích cá nhân của mình.
 Trước khi nhận ra được những mục đích xấu xa của Lex, thì cũng chính là lúc mà người anh hùng Superman đang chết dần, thời gian để anh sống chỉ còn 1 năm nữa thôi. Đứng trước cái chết anh đã quyết định giấu mọi người tất cả mọi chuyện, để anh có thể cố gắng làm những điều mình cần làm trước khi chết. Liệu rằng Superman có thể phá vỡ được kế hoạch của tên đại ác nhân kia không?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Denton","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Anthony LaPaglia","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Alexis Denisof","avatar":""},{"name":"Chris Cox","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Obba Babatundé","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Finola Hughes","avatar":""},{"name":"Ke","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
