INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-sat', 'Ẩn Sát', 'Hindsight', 'https://phimimg.com/upload/vod/20231110-1/63d3c1b840344e7936dc7e0c8eb57556.jpg', 'https://phimimg.com/upload/vod/20231110-1/f264554a2247c2f652d485cb0591db91.jpg', '<p>Tay trùm băng đảng, Du Heon, nghỉ hưu non và đăng ký vào học một lớp nấu ăn với hy vọng mở nhà hàng để tạo dựng một khởi đầu mới. Trong lớp học nấu ăn, anh gặp một cô gái kỳ quặc, Se Bin, và nhận thấy bản thân mình bị cuốn hút bởi nét quyến rũ bí ẩn của cô. Mặc dù quyết tâm phủi sạch quá khứ nhưng Du Heon được các đồng nghiệp cũ triệu tập về gấp để ngăn chặn người kế nhiệm mở rộng hoạt động phi pháp sang mại dâm và mua bán thuốc phiện...</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Chun Jung-myung","avatar":""},{"name":"Lee Jong-hyuk","avatar":""},{"name":"Kim Min-jun","avatar":""},{"name":"Youn Yuh-jung","avatar":""},{"name":"Esom","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Lee Jong-pil","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Jo Deok-jae","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Song Jae-ryong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
