INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cuoi-tuan', 'Ngày Cuối Tuần', 'Weekend', 'https://phimimg.com/upload/vod/20231110-1/0dbe95713f99a7bf2cc7d938a7ef98bc.jpg', 'https://phimimg.com/upload/vod/20231110-1/4ea4b4de4cc3020ff29957175d05e130.jpg', '<p>Sau bữa tiệc say xỉn tại nhà với những người bạn thẳng thắn của mình, Russell đến một câu lạc bộ đồng tính nam. Ngay trước giờ đóng cửa, anh đến đón Glen nhưng điều tưởng chừng chỉ là tình một đêm lại trở thành một thứ khác, một thứ đặc biệt.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Tom Cullen","avatar":""},{"name":"Chris New","avatar":""},{"name":"Jonathan Race","avatar":""},{"name":"Laura Freeman","avatar":""},{"name":"Loreto Murray","avatar":""},{"name":"Kieran Hardcastle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
