INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sai-gon-yo', 'Sài Gòn Yo!', 'Saigon Electric', 'https://phimimg.com/upload/vod/20231110-1/c33761fe997b69166228c699bf8ec8e6.jpg', 'https://phimimg.com/upload/vod/20231110-1/666c370ff984ffbb3be5f97f0b485d49.jpg', '<p>Tình bạn chớm nở giữa hai vũ công đầy đam mê chợt rạn nứt khi một chàng trai khiến cuộc thi hip-hop sắp tới của họ trở nên phức tạp.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Khương Ngọc","avatar":""},{"name":"Quỳnh Hoa","avatar":""},{"name":"Elly Nguyen","avatar":""},{"name":"Phan Tấn Thi","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Hà Hiền","avatar":""},{"name":"Kim Xuân","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324472);
