INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-hugo', 'Cuộc Phiêu Lưu Của Hugo', 'Hugo', 'https://phimimg.com/upload/vod/20231109-1/c160ce86980d5440e7e3afacc99c236e.jpg', 'https://phimimg.com/upload/vod/20231109-1/20d5765d8bdf43ec1676db6d7a5e4ff5.jpg', '<p>Hugo được chuyển thể từ cuốn tiểu thuyết The Invention of Hugo Cabret của văn hào người Anh Brian Selznick, Hugo lấy bối cảnh thành phố Paris những năm 1930, tập trung vào cuộc sống bí ẩn của một cậu bé mồ côi bên trong các bức tường của một nhà ga xe lửa. Khi Hugo gặp một chú robot bị hỏng, một cô gái lập dị, và một người đàn ông lạnh lùng - người điều hành cửa hàng đồ chơi, cậu đã rơi vào một cuộc phiêu lưu kì lạ mà có thể đặt tất cả những bí mật của cậu vào vòng nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Asa Butterfield","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Kevin Eldon","avatar":""},{"name":"Gulliver McGrath","avatar":""},{"name":"Shaun Aylward","avatar":""},{"name":"Emil Lage","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324472);
