INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-gai-goi', 'Nhật Ký Gái Gọi', 'Bruna Surfistinha', 'https://phimimg.com/upload/vod/20231110-1/0151d63563cb7d2ee5566f08d5230fd0.jpg', 'https://phimimg.com/upload/vod/20231110-1/d1cb6046b7e80346862c1b12b6b92d7b.jpg', '<p>Raquel là một cô gái được nhận nuôi bởi một gia đình tầng lớp thượng lưu, ở tuổi 17 cô bỏ nhà ra đi đến học tại một trường đại học truyền thống ở San Paulo để trở thành một cô gái gọi. Ngay sau khi bắt đầu công việc, cô quyết định viết một blog về những kinh nghiệm của mình. Blog này đã gây được sự chú ý mạnh mẽ, và nhanh chóng trở thành một trong những blog phổ biến nhất ở Brazil...</p>', 'Full', 1, 'single', 'completed', 22, 2011, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Deborah Secco","avatar":""},{"name":"Cássio Gabus Mendes","avatar":""},{"name":"Drica Moraes","avatar":""},{"name":"Fabiula Nascimento","avatar":""},{"name":"Cristina Lago","avatar":""},{"name":"Guta Ruiz","avatar":""},{"name":"Clarisse Abujamra","avatar":""},{"name":"Luciano Chirolli","avatar":""},{"name":"Sérgio Guizé","avatar":""},{"name":"Simone Iliescu","avatar":""},{"name":"Érika Puga","avatar":""},{"name":"Brenda Lígia","avatar":""},{"name":"Gustavo Machado","avatar":""},{"name":"Juliano Cazarré","avatar":""},{"name":"Rodrigo Dorado","avatar":""},{"name":"Roberto Audio","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
