INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-hoan-hao', 'Kế Hoạch Hoàn Hảo', 'The Entitled', 'https://phimimg.com/upload/vod/20231109-1/7fde91c07121b134358d6cce30a88347.jpg', 'https://phimimg.com/upload/vod/20231109-1/d2ecc4aca2155e98accdededaa3fb856.jpg', '<p>Cuộc đời của Paul Dynan hoàn toàn đảo lộn khi anh quyết định bắt cóc ba đứa trẻ và đòi tiền chuộc từ cha mẹ chúng. Nhưng mọi thứ dần mất kiểm soát khi kẻ đồng phạm cùng anh trở nên phấn khích và các nạn nhân cũng gây không ít bất ngờ cho anh. Khi có máu đổ xuống và kế hoạch hoàn hảo của anh bị biến tướng thì Paul cũng bắt đầu phải đối mặt với trò chơi của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ray Liotta","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Laura Vandervoort","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Tatiana Maslany","avatar":""},{"name":"John Bregar","avatar":""},{"name":"Anthony Ulc","avatar":""},{"name":"Nola Augustson","avatar":""},{"name":"Jim Codrington","avatar":""},{"name":"Martin Doyle","avatar":""},{"name":"Rosalba Martinni","avatar":""},{"name":"Eric Fink","avatar":""},{"name":"Claire Calarco","avatar":""},{"name":"Jim Calarco","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
