INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanna-bi-an', 'Hanna Bí Ẩn', 'Hanna', 'https://phimimg.com/upload/vod/20231108-1/7ff348bc64fca04d4f46541927ae42a5.jpg', 'https://phimimg.com/upload/vod/20231108-1/53c89a5b4e0301a6d24fdea1a44a1393.jpg', '<p>Hanna là một cô bé 16 tuổi phải sống cách biệt với thế giới bên ngoài, bị đào tạo huấn luyện trở thành một sát thủ chuyên nghiệp bởi chính cha của mình – cựu điệp viên CIA . Hanna bị bắt khi đang thực hiện một phi vụ, cô phải nhanh chóng học cách hòa nhập với thế giới bên ngoài để bảo vệ bản thân và tìm ra sự thật che dấu về sự tồn tại, cũng như câu trả lời cho những câu hỏi bất ngờ về thân thế của chính mình.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Tim Beckmann","avatar":""},{"name":"John Macmillan","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Paul Birchard","avatar":""},{"name":"Christian Malcolm","avatar":""},{"name":"Jamie Beamish","avatar":""},{"name":"Jessica Barden","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Sebastian Hülk","avatar":""},{"name":"Joel Basman","avatar":""},{"name":"Martin Wut","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
