INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-la-mat', 'Kẻ Lạ Mặt', 'Unknown', 'https://phimimg.com/upload/vod/20231108-1/4bafaa8b03446464995f550d55b0f0cb.jpg', 'https://phimimg.com/upload/vod/20231108-1/bc4866b85ad893a21d7cb7763ebb6c0e.jpg', '<p>Unknown (Kẻ Lạ Mặt) là bộ phim hành động, bí ẩn xoay quanh cuộc sống của giáo sư Martin cùng vợ tới Berlin dự hội thảo, vì quên chiếc cặp tài liệu, ông quay lại sân bay. Trên đường đi, chiếc taxi gặp tai nạn. Bốn ngày sau, Martin tỉnh dậy sau cơn mê. Ông quay lại tìm vợ nhưng bên cạnh cô lại là một giáo sư Martin khác. Ai đã lấy mất danh tính của ông, và để làm gì?</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"January Jones","avatar":""},{"name":"Aidan Quinn","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"Sebastian Koch","avatar":""},{"name":"Olivier Schneider","avatar":""},{"name":"Stipe Erceg","avatar":""},{"name":"Rainer Bock","avatar":""},{"name":"Mido Hamada","avatar":""},{"name":"Clint Dyer","avatar":""},{"name":"Karl Markovics","avatar":""},{"name":"Eva Löbau","avatar":""},{"name":"Helen Wiebensohn","avatar":""},{"name":"Adnan Maral","avatar":""},{"name":"Merle Wiebensohn","avatar":""},{"name":"Torsten Mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
