INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock-holmes-tro-choi-cua-bong-dem', 'Thám Tử Sherlock Holmes: Trò Chơi Của Bóng Đêm', 'Sherlock Holmes: A Game of Shadows', 'https://phimimg.com/upload/vod/20231108-1/22c161628bdf127b5c35476525b1fa72.jpg', 'https://phimimg.com/upload/vod/20231108-1/4997c26b347f732705f52f371680dfe9.jpg', '<p>Chúng ta đều biết Holmes luôn là người thông minh nhất trong phần 1 với những suy luận sắc bén cùng những hành động tưởng chừng như ngờ nghệch nhưng đều là ý đồ của chàng thám tử tài ba này. Tuy nhiên trong phần này, anh ta sẽ đụng độ một tên tội phạm ở đẳng cấp cao hơn hẳn những tên mà Holmes từng được biết - Giáo sư Moriarty. Hắn ta có trí thông minh ngang ngửa với Holmes nhưng lại dùng nó để phục vụ cho cái ác, cùng với những suy tính xảo trá và bất chấp mọi thủ đọan là yếu tố đem lại cho hắn lợi thế trong cuộc đấu trí căng thẳng với chàng thám tử nổi tiếng...</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"William Houston","avatar":""},{"name":"Wolf Kahler","avatar":""},{"name":"Iain Mitchell","avatar":""},{"name":"Jack Laskey","avatar":""},{"name":"Patricia Slater","avatar":""},{"name":"Karima McAdams","avatar":""},{"name":"Richard Cunningham","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c7