INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-sherlock-holmes-tro-choi-cua-bong-dem', 'Thám Tử Sherlock Holmes: Trò Chơi Của Bóng Đêm', 'Sherlock Holmes: A Game of Shadows', 'thám tử sherlock holmes: trò chơi của bóng đêm sherlock holmes: a game of shadows robert downey jr. jude law noomi rapace jared harris rachel mcadams eddie marsan kelly reilly stephen fry paul anderson geraldine james william houston wolf kahler iain mitchell jack laskey patricia slater karima mcadams richard cunningham ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-noi-gian', 'Trò Chơi Nội Gián', 'Tinker Tailor Soldier Spy', 'https://phimimg.com/upload/vod/20231108-1/55b826fcea76c5ee4ff08bd075ad258b.jpg', 'https://phimimg.com/upload/vod/20231108-1/fb169ae96636df3a91cb9401a111873c.jpg', '<p>Tailor Tinker Soldier Spy giống như trò chơi giải đố, với những lời gợi ý vô cùng ít ỏi, đòi hỏi khả năng quan sát, tỉ mẩn, và kiên nhẫn. George Smiley là một điệp viên đã hết thời chỉ chờ ngày nhận quyết định về hưu. Một ngày, chính phủ Anh nghe được tin có một điệp viên hai mang của Liên Xô đang nằm vùng tại The Circus (thuộc MI6), bộ não của cơ quan tình báo tối cao của Anh Quốc. George Smiley được giao nhiệm vụ điều tra kẻ phản bội trong bốn nhân vật đầu não, được đặt bí danh là Tinker (Toby Jones), Tailor (Colin Firth), Soldier (Ciarán Hinds) và Poorman (David Dencik). Nhiệm vụ của ông là cực kì khó khăn khi mà mọi hoạt động của The Circut là tối mật, ông không được phép tiếp cận hồ sơ, kế hoạch hay lịch trình của những nhân vật trong đó.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gary Oldman","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Kathy Burke","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Svetlana Khodchenkova","avatar":""},{"name":"Roger Lloyd Pack","avatar":""},{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Christian McKay","avatar":""},{"name":"Zoltán","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324472);
