INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-san-toi-pham', 'Đội Săn Tội Phạm', 'Trigun: Badlands Rumble', 'https://phimimg.com/upload/vod/20231108-1/fbc657abd97beedc5ee8b7d8e4d30689.jpg', 'https://phimimg.com/upload/vod/20231108-1/96ec225372737bf6cc0ce1b977c793bc.jpg', '<p>Câu truyện xảy ra ở 1 thị trấn hoang vắng tên Macca. Thị trưởng thị trấn này tên Kapler đang tập hợp những người chuyên săn tội phạm để chống lại tên cướp nổi tiếng Gasbag. Meryl và Milly đến thị trấn này và ngạc nhiên khi thấy Vash ở đây. Sau đó tay chân của Gasbag tấn công Macca, Vash nhận ra Wolfwood trong số chúng.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masaya Onosaka","avatar":""},{"name":"Satsuki Yukino","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Tsutomu Isobe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
