INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-tan-sat', 'Đêm Tàn Sát', 'Dylan Dog: Dead of Night', 'https://phimimg.com/upload/vod/20231108-1/36bf135321de19b2e04a4418c0c43a25.jpg', 'https://phimimg.com/upload/vod/20231108-1/84a531aafb0d1e227b168a28fcd47cbf.jpg', '<p>Dylan Dog là 1 điều tra viên chuyên điều tra thế giới ngầm huyền bí. Anh khó khăn lắm mới dời khỏi được New Orleans để tránh xa cuộc sống đầy ác mộng nơi đó. Nhưng cơn ác mộng đó không bỏ qua cho anh. 1 cô gái nhân tạo, 1 nữ thừa kế và là 1 tên sát thủ tàn bạo đã âm mưu kéo anh ta trở lại với thế giới ma quỷ đen tối.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brandon Routh","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Sam Huntington","avatar":""},{"name":"Taye Diggs","avatar":""},{"name":"Anita Briem","avatar":""},{"name":"Kurt Angle","avatar":""},{"name":"Andrew Sensenig","avatar":""},{"name":"Randal Reeder","avatar":""},{"name":"Courtney J. Clark","avatar":""},{"name":"Gabrielle Chapin","avatar":""},{"name":"Kimberly Whalen","avatar":""},{"name":"Courtney Shay Young","avatar":""},{"name":"James Hébert","avatar":""},{"name":"Marco St. John","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
