INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-tan-sat', 'Đêm Tàn Sát', 'Dylan Dog: Dead of Night', 'đêm tàn sát dylan dog: dead of night brandon routh peter stormare sam huntington taye diggs anita briem kurt angle andrew sensenig randal reeder courtney j. clark gabrielle chapin kimberly whalen courtney shay young james hébert marco st. john ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-o-paris', 'Quái Vật Ở Paris', 'A Monster in Paris', 'https://phimimg.com/upload/vod/20231108-1/5d2f1d5d6208933baf17ffcca36aba7d.jpg', 'https://phimimg.com/upload/vod/20231108-1/e4e41505fa4b6f206c9d5af7b66efa8c.jpg', '<p>Một bộ phim hoạt hình lấy bối cảnh tại Paris vào năm 1910 và nói về một con quái vật đang sống trong một khu vườn và tình yêu của nó dành cho một ca sĩ trẻ xinh đẹp.
 Tại Paris vào năm 1910, Emile là một cô bé điều khiển máy chiếu nhút nhát ở một ráp chiếu phim, và Raoul là một nhà phát minh màu sắc, cùng nhau săn lùng một con quái vật đang khiến người dân kinh sợ. Họ tham gia lực lượng với Lucille, một ngôi sao lớn của quán rượu Bird of Paradise, một nhà khoa học lập dị và chú khỉ cáu kỉnh để cứu con quái vật vốn chỉ là người hóa ra là một con vật quá cỡ nhưng vô hại thoát khỏi cảnh sát trưởng tàn nhẫn đầy tham vọng của thành phố.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Vanessa Paradis","avatar":""},{"name":"Matthieu Chedid","avatar":""},{"name":"Gad Elmaleh","avatar":""},{"name":"François Cluzet","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Julie Ferrier","avatar":""},{"name":"Bruno Salomone","avatar":""},{"name":"Sébastien Desjours","avatar":""},{"name":"Philippe Peythieu","avatar":""},{"name":"Mirabelle Kirkland","avatar":""},{"name":"Allan Wenger","avatar":""},{"name":"Jodi Forrest","avatar":""},{"name":"Bob Balaban","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"David Gasman","avatar":""},{"name":"Matthew Géczy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324472);
