INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-long-den-xanh-hiep-si-ngoc-bich', 'Chiến Binh Lồng Đèn Xanh: Hiệp Sĩ Ngọc Bích', 'Green Lantern: Emerald Knights', 'https://phimimg.com/upload/vod/20231108-1/378fdf3bcfc33fb95b8b4190062d27fb.jpg', 'https://phimimg.com/upload/vod/20231108-1/b30a333ad8cb1b5dc19168b221eb912b.jpg', '<p>Green Lantern: Emerald Knights trong vũ trụ mênh mông mang theo những điều huyền bí to lớn có một lực lượng tuy nhỏ nhưng rất hùng mạnh đã tồn tại qua hàng thế kỉ. Là những người bảo vệ hòa bình và công lý, họ được gọi là quân đoàn Green Lantern. Những chiến binh Green Lantern đã thề rằng phải giữ được trật tự và bình yên trong dải ngân hà này, nên mỗi người đeo một chiếc nhẫn chứa đựng siêu quyền năng. Nhưng khi Parallax, kẻ thù mới của họ, đe dọa sẽ phá hủy sự cân bằng quyền năng trong vũ trụ, định mệnh của họ và số phận của Trái đất nằm trong tay thành viên mới nhất của quân đoàn, con người đầu tiên được lựa chọn: Hal Jordan. Hal mặc dù là một viên phi công tự phụ nhưng anh thực sự có tài năng, nhưng quân đoàn Green Lantern có rất ít sự tôn trọng đối với loài người, những người chưa bao giờ được chiếc nhẫn quyền năng ban cho sức mạnh vô biên.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathan Fillion","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Roddy Piper","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Michael Jackson","avatar":""},{"name":"Peter Jessop","avatar":""},{"name":"David Kaufman","avatar":""},{"name":"Sunil Malhotra","avatar":""},{"name":"Andrea Romano","avatar":""},{"name":"Jane Singer","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Bruce Thomas","avatar":""},{"name":"Mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
