INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-la-ma', 'Chiến Binh La Mã', 'The Eagle', 'https://phimimg.com/upload/vod/20231103-1/9877d19aa858c9eb925ec93d7f7c6d64.jpg', 'https://phimimg.com/upload/vod/20231103-1/f2c0bb5e295e25f35bec280f138df6f5.jpg', '<p>Sau sự mất tích bí ẩn của binh đoàn số 9 tại vùng núi Scotland, người lính La Mã trẻ Marcus Aquila lên đường đi tìm lại biểu tượng vinh quang của cha mình, là chỉ huy một thời của binh đoàn La Mã số 9 lừng danh. Bạn đồng hành duy nhất của Marcus là một nô lệ gốc Anh tên Esca, hai người vượt qua dải tường thành Hadrian để tiến vào vùng đất chưa được người La Mã khai phá tại cao nguyên Caledonia. Ở đây cả hai sẽ phải đối phó với những bộ tộc người man ở bản địa để khám phá những ký ức của binh đoàn số Chín và đoạt lại biểu tượng huy hoàng của binh đoàn...</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Tahar Rahim","avatar":""},{"name":"Dakin Matthews","avatar":""},{"name":"Douglas Henshall","avatar":""},{"name":"Paul Ritter","avatar":""},{"name":"Pip Carter","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"István Göz","avatar":""},{"name":"Bence Gerö","avatar":""},{"name":"Zsolt László","avatar":""},{"name":"Julian Lewis Jones","avatar":""},{"name":"Brian Gleeson","avatar":""},{"name":"Jon Campling","avatar":""},{"name":"Alad","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
