INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-kevin', 'Cậu Bé Kevin', 'We Need to Talk About Kevin', 'https://phimimg.com/upload/vod/20231103-1/cff62a222908f4e895a43042c40b3cbe.jpg', 'https://phimimg.com/upload/vod/20231103-1/6eed6ed1eb6ff910bdb180b20a08a7cb.jpg', '<p>Một người mẹ của Eva cố gắng ghép lại cuộc đời của mình sau một sự cố gây ra bởi đứa con kỳ lạ của cô, Kevin. Khi một nhà văn thành công, cô buộc phải lấy bất cứ thứ gì xuất hiện theo cách của mình, bất chấp những điều ngày càng kỳ quái và nguy hiểm Kevin nói, hoặc làm.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tilda Swinton","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Jasper Newell","avatar":""},{"name":"Rock Duer","avatar":""},{"name":"Ashley Gerasimovich","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Alex Manette","avatar":""},{"name":"Kenneth Franklin","avatar":""},{"name":"Leslie Lyles","avatar":""},{"name":"Paul Diomede","avatar":""},{"name":"Michael Campbell","avatar":""},{"name":"J. Mallory McCree","avatar":""},{"name":"Mark Elliot Wilson","avatar":""},{"name":"James Chen","avatar":""},{"name":"Lauren Fox","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
