INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-thac-loan', 'Cuộc Thác Loạn', 'Hollywood Sex Wars', 'https://phimimg.com/upload/vod/20231103-1/1c730b8d1421ba66dc1f5e477fd1ed32.jpg', 'https://phimimg.com/upload/vod/20231103-1/f7f8cd841d87c215f6f48d4148cf02b8.jpg', '<p>Max, Aaron và Glen có một thành tích đầy rẫy những pha ăn vạ và những pha móc nối không phù hợp. Các chàng trai bắt tay vào một nhiệm vụ để nâng cao mức trung bình đánh bóng của cô gái nóng bỏng của họ. Họ gặp Hollywood Casanova Johnny Eyelash, người đã dạy những cậu bé này trò chơi ghi điểm bằng cánh tay hạng A. Nhưng có một vấn đề, các cô gái có tổ chức, xảo quyệt và có một chương trình nghị sự của riêng họ. Không lâu sau đó, các cô gái, dẫn đầu là Wendy Lớn và Wendy Nhỏ, bắt kịp chiến thuật của Johnny và Hollywood trở thành một cái bẫy lớn.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mario Diaz","avatar":""},{"name":"Jenae Altschwager","avatar":""},{"name":"Eli Jane","avatar":""},{"name":"Dominique Purdy","avatar":""},{"name":"Jacqui Holland","avatar":""},{"name":"Christine Nguyen","avatar":""},{"name":"Aneliese Roettger","avatar":""},{"name":"Carmen Palumbo","avatar":""},{"name":"Richard Blair","avatar":""},{"name":"Suzy Kaye","avatar":""},{"name":"Fabio","avatar":""},{"name":"Robin Bain","avatar":""},{"name":"Elena Diaz","avatar":""},{"name":"Maz Siam","avatar":""},{"name":"April Garcia","avatar":""},{"name":"Nat Dixon","avatar":""},{"name":"Marta Zolynska","avatar":""},{"name":"Erica Curtis","avatar":""},{"name":"Olivia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324472);
