INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-ky-quai', 'Vụ Cướp Kỳ Quái', 'Flypaper', 'https://phimimg.com/upload/vod/20231103-1/87adda6ccd7de11c7084bdfed0c400a7.jpg', 'https://phimimg.com/upload/vod/20231103-1/6b65312bdd39569365de12bb0225d0cb.jpg', '<p>Flypaper ( Vụ Cướp Kỳ Quái) là bộ phim hành động xoay quanh một vụ cướp. Câu chuyện bắt đầu khi Tripp bước vào một ngân hàng để đổi tiền trong khi 2 toán cướp đụng mặt nhau tại ngân hàng mà Tripp đang đúng. Một cách bí hiểm như đệ tử Sherlock Holmes phải hóa giải bí quyết của Agatha Christie để có được trái tim cố gái. Nhưng mọi chuyện không đơn giản như thế, và có rất nhiều tình huống dở khóc, dở cười xảy ra làm mọi chuyện đảo lộn hết lên...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Matt Ryan","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"John Ventimiglia","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Curtis Armstrong","avatar":""},{"name":"Rob Huebel","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Natalia Safran","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Eddie Matthews","avatar":""},{"name":"Rob Boltin","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Josep","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
