INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-nha-hat', 'Bóng ma Nhà hát', 'The Phantom of the Opera at the Royal Albert Hall', 'https://phimimg.com/upload/vod/20231103-1/e2f7e1ac56cd1500e302e3f834b83c50.jpg', 'https://phimimg.com/upload/vod/20231103-1/7807bde32d76280b37c2f5aa7206516a.jpg', '<p>Một thiên tài âm nhạc bị biến dạng, ẩn mình trong Nhà hát Opera Paris, khủng bố công ty opera vì lợi ích vô tình của một người bảo trợ trẻ tuổi mà anh ta đào tạo và yêu mến. Lễ kỷ niệm 25 năm buổi biểu diễn đầu tiên của Phantom of the Opera được tổ chức với một buổi biểu diễn hoành tráng tại Royal Albert Hall ở London.</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ramin Karimloo","avatar":""},{"name":"Sierra Boggess","avatar":""},{"name":"Hadley Fraser","avatar":""},{"name":"Liz Robertson","avatar":""},{"name":"Nick Holder","avatar":""},{"name":"Wendy Ferguson","avatar":""},{"name":"Daisy Maywood","avatar":""},{"name":"Barry James","avatar":""},{"name":"Gareth Snook","avatar":""},{"name":"Wynne Evans","avatar":""},{"name":"Earl Carpenter","avatar":""},{"name":"Kiera Duffy","avatar":""},{"name":"Sergei Polunin","avatar":""},{"name":"Philip Griffiths","avatar":""},{"name":"Simon Green","avatar":""},{"name":"Stephen John Davis","avatar":""},{"name":"Gardar Thor C","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
