INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-duoi-theo-tinh-tu', 'Những Đứa Trẻ Đuổi Theo Tinh Tú', 'Children Who Chase Lost Voices', 'https://phimimg.com/upload/vod/20231103-1/ddd5977cdb5ad92e88d5d787c03364dc.jpg', 'https://phimimg.com/upload/vod/20231103-1/985fb7fa570424ec6c0ab518b5ad836a.jpg', '<p>Asuna mất cha từ nhỏ và sống một cuộc đời thật cô đơn. Cô dành thời gian nghe một bài hát kỳ lạ thông qua một thiết bị cũng kỳ lạ không kém, chiếc radio tinh thể của cha mình. Và cũng từ đó, cô bắt đầu chuyến hành trinh vào một thế giới hoàn toàn xa lạ để tìm ra ý nghĩa thật sự của &quot;chia ly&quot;- thứ nghiệt ngã nhưng cũng là vẻ đẹp của cuộc đời.
 &quot;Con người sống luôn phải chịu mất mát chia ly. Đó là lời nguyền của con người, nhưng chắc hẳn cũng là một phúc lành.&quot;</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hisako Kanemoto","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Sumi Shimamoto","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Kanae Ito","avatar":""},{"name":"Tamio Ohki","avatar":""},{"name":"Aki Kanada","avatar":""},{"name":"Ai Horanai","avatar":""},{"name":"Saya Horigome","avatar":""},{"name":"Mayumi Tsuchiya","avatar":""},{"name":"Tomomi Saito","avatar":""},{"name":"Takeshi Maeda","avatar":""},{"name":"Risa Mizuno","avatar":""},{"name":"Yuuna Inamura","avatar":""},{"name":"Yuka Terasaki","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
