INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-phieu-luu-ky', 'Giáng Sinh Phiêu Lưu Ký', 'Arthur Christmas', 'https://phimimg.com/upload/vod/20231106-1/745e6501a473ce96b34bb1d5b52ca06e.jpg', 'https://phimimg.com/upload/vod/20231106-1/c6e3ccf371b6f7057cddf41dcce1aed6.jpg', '<p>Tiết lộ câu trả lời đáng kinh ngạc, chưa bao giờ được nhắc tới cho câu hỏi của mọi đứa trẻ khi Giáng Sinh về &quot;làm thế nào ông già Noel phân phát hết tất cả những món quà trong một đêm?&quot; Đó là nhờ trung tâm phân phát quà của ông già noel, một trung tâm siêu công nghệ cao hoạt động ẩn bên dưới Bắc Cực. Nhưng trung tâm của bộ phim là một câu chuyện về gia đình Arthur, và cậu bé Arthur phải thực hiện một nhiệm vụ cấp bách hoàn thành trước hoàng hôn ngày lễ Giáng sinh.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Ashley Jensen","avatar":""},{"name":"Marc Wootton","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Ramona Marquez","avatar":""},{"name":"Michael Palin","avatar":""},{"name":"Sanjeev Bhaskar","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Iain McKee","avatar":""},{"name":"Andy Serki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","