INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giang-sinh-phieu-luu-ky', 'Giáng Sinh Phiêu Lưu Ký', 'Arthur Christmas', 'giáng sinh phiêu lưu ký arthur christmas james mcavoy hugh laurie bill nighy jim broadbent imelda staunton ashley jensen marc wootton laura linney eva longoria ramona marquez michael palin sanjeev bhaskar robbie coltrane joan cusack rhys darby jane horrocks iain mckee andy serki ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('steve-jobs-khoanh-khac-con-lai', 'Steve Jobs: Khoảnh Khắc Còn Lại', 'Steve Jobs: One Last Thing', 'https://phimimg.com/upload/vod/20231106-1/da230e1f2d7cd17fca75089f3bc3a335.jpg', 'https://phimimg.com/upload/vod/20231106-1/f3bfd07b9a89c208d049c2f918f232af.jpg', '<p>Steve Jobs - Nhà sáng lập, cựu giám đốc điều hành thương hiệu nổi tiếng Apple. Dưới sức ảnh hưởng rộng lớn của ông sau khi mất vào ngày 5/10/2011 do ung thư tuyến tiền liệt, cộng đồng mạng như Twitter đã lên tiếng rộng rãi cùng với hàng đoàn người tổ chức kỉ niệm trước các cửa hàng Apple Store. Thông qua bộ Film này chúng ta không chỉ xem xét về tài năng, phong cách và trí tưởng tượng tuyệt vời của Jobs mà còn nhìn cách ông đã định hình và ảnh hưởng rộng rãi đến đời sống của chúng ta như thế nào. Ta sẽ phỏng vấn những người đã một thời và hiện vẫn từng hợp tác với Jobs, như Ronald Wayne - đồng sáng lập Apple Computer; Robert Palladino - nhà thư pháp với các lớp học mà Jobs thừa nhận tạo nên cảm hứng cho ông thiết kế kiểu chữ cho máy tính Mac; Dean Hovey - người thiết kế con chuột cho Aplle cùng nhiều người khác....</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Jobs","avatar":""},{"name":"Steve Wozniak","avatar":""},{"name":"Bob Cringely","avatar":""},{"name":"Will.i.am","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324472);
