INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('steve-jobs-khoanh-khac-con-lai', 'Steve Jobs: Khoảnh Khắc Còn Lại', 'Steve Jobs: One Last Thing', 'steve jobs: khoảnh khắc còn lại steve jobs: one last thing steve jobs steve wozniak bob cringely will.i.am ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-day-sao', 'Đêm đầy sao', 'Starry Starry Night (Xing kong)', 'https://phimimg.com/upload/vod/20231103-1/c49344c59a6d66bdf45b206dcf0d6ffa.jpg', 'https://phimimg.com/upload/vod/20231103-1/3913bdcdd05cdb7f886a038bffcc83ad.jpg', '<p>Từng có một cô gái trẻ tên là May cảm thấy xa lạ với mọi người xung quanh. May lo lắng cho cha mẹ cô, những người có cuộc hôn nhân đang rạn nứt, và cô khao khát được trở về khu rừng nơi ông cô sống. Một ngày nọ, May kết bạn với một cậu bé cũng cô đơn như cô. Khi thực tế bắt kịp, họ chạy trốn đến một thế giới tươi đẹp chỉ thuộc về họ. Vừa giàu trí tưởng tượng vừa thực tế đến đau lòng, cuộc hành trình của họ nói lên nỗi đau của sự cô đơn, nỗi buồn mất mát và hơi ấm của hy vọng cho cả trẻ em và người lớn.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Xu Jiao","avatar":""},{"name":"Hui-Min Lin","avatar":""},{"name":"René Liu","avatar":""},{"name":"Harlem Yu","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Janel Tsai","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Shih Chin-Hang","avatar":""},{"name":"Lee Lieh","avatar":""},{"name":"Chen Yu-hsun","avatar":""},{"name":"Huang Shih-Han","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
