INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nu-u-hon-4', 'Thiện Nữ U Hồn 4', 'A Chinese Fairy Tale', 'https://phimimg.com/upload/vod/20231103-1/5318519b6a07ffe98495d83c9a74cb60.jpg', 'https://phimimg.com/upload/vod/20231103-1/f324804980ac4d202087e68e315a2449.jpg', '<p>Hồ ly Tiểu Thiện vì mong ước được đầu thai thành người mà trở thành nỗi khiếp sợ của ngàn người. Còn chàng thư sinh Ninh Thái Thần với tình yêu đầu đời dành cho người con gái tuyệt thế giai nhân mà sẵn sàng hy sinh mạng sống. Một chuyện tình tay ba đẫm nước mắt nhưng cũng tràn ngập hạnh phúc. Tận đáy lòng của mỗi nhân vật chỉ có một mong ước đơn giản là được sống trọn ...</p>', 'Full', 1, 'single', 'completed', 22, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Yu Shaoqun","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Wang Danyi Li","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Gong Xinliang","avatar":""},{"name":"Lin Peng","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Alan Chui Chung-San","avatar":""},{"name":"Sise Ma","avatar":""},{"name":"Fei  Wang","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324472);
