INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khong-co-dan-ong', 'Thế Giới Không Có Đàn Ông', 'Without Men', 'https://phimimg.com/upload/vod/20231103-1/34ae39c6df1bb93ed323c2dc5794ca1f.jpg', 'https://phimimg.com/upload/vod/20231103-1/d5f0092c78345c0cb63b89287e4dd666.jpg', '<p>Thế Giới Không Có Đàn Ông - Without Men xoay quanh cuộc sống của những người phụ nữ sống ở 1 thị trấn xa xôi tại Châu Mỹ. Họ đang đứng trước một nguy cơ lớn, khi mà tất cả những người đàn ông trong thị trấn phải đi chiến đấu. Những người phụ nữ này phải xây dựng lại cuộc sống của mình và đối mặt với khó khăn như thế nào?</p>', 'Full', 1, 'single', 'completed', 23, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eva Longoria","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Oscar Nunez","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Mónica Huarte","avatar":""},{"name":"Yvette Yates Redick","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Luis Chávez","avatar":""},{"name":"Guillermo Díaz","avatar":""},{"name":"Paul Rodríguez","avatar":""},{"name":"Camryn Manheim","avatar":""},{"name":"Judy Reyes","avatar":""},{"name":"Fernanda Romero","avatar":""},{"name":"Hope Dworaczyk Smith","avatar":""},{"name":"Jesse Garcia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
