INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khong-co-dan-ong', 'Thế Giới Không Có Đàn Ông', 'Without Men', 'thế giới không có đàn ông without men eva longoria christian slater oscar nunez kate del castillo mónica huarte yvette yates redick maría conchita alonso luis chávez guillermo díaz paul rodríguez camryn manheim judy reyes fernanda romero hope dworaczyk smith jesse garcia ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-kinh-di', 'Quái Vật Kinh Dị', 'The Thing', 'https://phimimg.com/upload/vod/20231103-1/72c8ce391eb22e2bedae8d85cdd9bdbf.jpg', 'https://phimimg.com/upload/vod/20231103-1/4e7bea7312d5d35efcb7389762a05d23.jpg', '<p>Tại một vùng nghiên cứu tại Nam Cực, sự phát hiện về một sinh vật ngoài hành tinh đã dẫn đến sự đối đầu giữa cô sinh viên Kate Lloyd (Mary Elizabeth Winstead) và nhà khoa học Sander Halvorson (Ulrich Thomsen). Trong khi Dr. Halvorson vẫn tiếp tục nghiên cứu thì Kate cùng với Sam Carter (Joel Edgerton), một phi công lái trực thăng hợp lại thành một nhóm để chiến đấu với loài sinh vật ngoài hành tinh kỳ quái có khả năng mượn cơ thể của người khác...Tiếng gió rít ù ù trên vùng lạnh giá Nam Cực, tiếng khoan vào băng rít lộng óc, tiếng bước chân, tiếng hét, tiếng súng phun lửa... tất cả như đưa khán giả vào một cơn ác mộng kinh hoàng nhất mà họ từng trải qua.</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Paul Braunstein","avatar":""},{"name":"Trond Espen Seim","avatar":""},{"name":"Kim Bubbs","avatar":""},{"name":"Jørgen Langhelle","avatar":""},{"name":"Jan Gunnar Røise","avatar":""},{"name":"Stig Henrik Hoff","avatar":""},{"name":"Kristofer Hivju","avatar":""},{"name":"Carsten Bjørnlund","avatar":""},{"name":"Jo Adrian Haavi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
