INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-thai', 'Võ Sĩ Thái', 'Thai Fighter', 'null', 'https://phimimg.com/upload/vod/20231103-1/44cad29286f4ad338c929f68809379c2.jpg', '<p>Võ Sĩ Thái - Thai Fighter xoay quanh Jack, một nhân viên pha chế ở sòng bạc. Anh đã có một ngày tồi tệ khi tình cờ phạm tội nghiêm trọng, là mục tiêu của một băng đảng mafia Thái Lan và tuyệt vọng thoát khỏi một kẻ sát nhân là một chuyên gia võ thuật. Tất cả chỉ vì một vi mạch đã đến tay anh ta một cách bất ngờ. Được bạn bè giúp đỡ, Jack cố gắng sống sót trong khi tìm cách đưa vi mạch cho cơ quan chức năng. Nhưng mọi thứ sẽ trở nên tuyệt vọng khi họ phát hiện ra rằng kẻ sát nhân không ngừng săn đuổi họ cũng là cảnh sát.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Akarin Akaranitimaytharatt","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Anake Inthajun","avatar":""},{"name":"Andrew Scott Dixon","avatar":""},{"name":"Simon Kook","avatar":""},{"name":"Yaow Lookyee","avatar":""},{"name":"Padung Songsang","avatar":""},{"name":"Anuwat Tharapan","avatar":""},{"name":"Pornwipa Watcharakaroon","avatar":""},{"name":"Saisin Wongkhamlao","avatar":""},{"name":"Sakchai Yukhachen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324472);
