INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-hoa-hong', 'Sát Thủ Hoa Hồng', 'Requiem for a Killer', 'https://phimimg.com/upload/vod/20231111-1/9f66640806c530ed595ab0d32887cc3a.jpg', 'https://phimimg.com/upload/vod/20231111-1/07da12a97fe44eb208100f0331d30894.jpg', '<p>Lucretia là một kẻ giết thuê. Chuyên đầu độc và đam mê opera, cô sẽ phải thực hiện một bản hợp đồng khó khăn ở trung tâm dãy núi Alps của Thụy Sĩ. Trong vai một ca sĩ, Lucretia sẽ phải xuất hiện trong bối cảnh của Festival d&#39;Ermeux độc quyền và cố gắng giết một trong những cộng sự của cô: giọng nam trung người Anh Alexander Child. Gần đây đã mua lại một nhà máy chưng cất của Scotland, anh ta vẫn là trở ngại duy nhất đối với một dự án đường ống chiến lược có lợi ích kinh tế đáng kể; gần đây đã giành chiến thắng trong một cuộc chiến pháp lý khó khăn chống lại British Oil, biện pháp cuối cùng của họ là loại bỏ anh ta. Mọi thứ trở nên phức tạp hơn là Rico, được gửi bởi tổ chức chống gián điệp của Pháp, người cố gắng thâm nhập vào dàn nhạc và ngăn chặn âm mưu chống lại Alexander Child.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Clovis Cornillac","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Xavier Gallais","avatar":""},{"name":"Christopher Stills","avatar":""},{"name":"Corrado Invernizzi","avatar":""},{"name":"Michel Fau","avatar":""},{"name":"Frédérique Tirmont","avatar":""},{"name":"Johan Leysen","avatar":""},{"name":"Jean-Claude Dreyfus","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
