INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hoi-ngo', 'Cuộc Hội Ngộ', 'The Reunion', 'https://phimimg.com/upload/vod/20231110-1/06d4582aabc57ab84532441acd38ea3e.jpg', 'https://phimimg.com/upload/vod/20231110-1/3f358906aa30ea884b69ff14925d08e4.jpg', '<p>Cuộc Hội Ngộ - The Reunion xoay quanh một gia đình rối loạn: Sam, Leo không ưa gì cậu em trai Douglas quậy phá, một bà mẹ nghiện rượu và ông bố giàu có nhưng đã qua đời. Một khối lượng tài sản đáng giá được để lại và ba anh em phải bắt đầu thực hiện di chúc của người cha quá cố. Rất nhiều sự việc đã phát sinh ra sau đó. Họ sẽ phải đối mặt với ông trùm buôn ma túy người Mexico đội lốt doanh nhân cao quý rồi âm mưu bắt cóc các thành viên trong gia đình... Liệu Sam sẽ phải làm gì để đối mặt với nguy hiểm cũng như hàn gắn lại mối thâm tình của 3 anh em?</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cena","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Michael Rispoli","avatar":""},{"name":"Gregg Henry","avatar":""},{"name":"Lela Loren","avatar":""},{"name":"Jack Conley","avatar":""},{"name":"J.D. Garfield","avatar":""},{"name":"Josh Berry","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"River Shields","avatar":""},{"name":"Marya Beauvais","avatar":""},{"name":"Rio Alexander","avatar":""},{"name":"Tait Fletcher","avatar":""},{"name":"Morse Bicknell","avatar":""},{"name":"Jeremiah Bitsui","avatar":""},{"name":"Kevin Christophe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324472);
