INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sui-gia-dai-chien', 'Sui Gia Đại Chiến', 'Meet the In-Laws', 'https://phimimg.com/upload/vod/20231102-1/e80cb27843087400d605f97aa37b9362.jpg', 'https://phimimg.com/upload/vod/20231102-1/de0684599be228d92bf00fc554750d69.jpg', '<p>Khi họa sĩ truyện tranh Hyun-joon phải lòng Da-hong, một trong những người hâm mộ của anh ấy, nó đã tạo nên cuộc chiến nguyên mẫu giữa hai gia đình của họ, những người đến từ các vùng đối địch. Hyun-joon đến từ vùng Honam tự do chính trị (Bắc và Nam Jeolla) trong khi Da-hong đến từ vùng Yeongnam bảo thủ (Bắc và Nam Gyeongsang). Khi cả hai tuyên bố ý định kết hôn, họ phải đối mặt với vô số rào cản đe dọa hạnh phúc của họ.</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Sae-byuk","avatar":""},{"name":"Lee Si-young","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Kim Soo-mi","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"Yang Han-yeol","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
