INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-tan-ac', 'Bóng Ma Tàn Ác', 'Intruders', 'https://phimimg.com/upload/vod/20231102-1/7cafcf817cb406ea050392d0dce08b90.jpg', 'https://phimimg.com/upload/vod/20231102-1/6fa134a9c71bc046e566ff511f35276b.jpg', '<p>Mặc dù không ai có thể nhìn thấy anh ta, Hollow Face ẩn nấp trong các góc, khao khát tình yêu một cách tuyệt vọng nhưng chỉ biết gieo rắc nỗi sợ hãi và ghét bỏ. Anh len lỏi vào cuộc sống của John Farrow sau khi cô con gái 13 tuổi yêu quý của Farrow, Mia, bị hành hung tại nhà của họ. Ranh giới giữa thực và ảo mờ đi khi các vết nứt bắt đầu mở ra trong đơn vị gia đình. Có vẻ như không có biện pháp an ninh nào có thể ngăn cản được Mặt Rỗng.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Carice van Houten","avatar":""},{"name":"Ella Purnell","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Ella Hunt","avatar":""},{"name":"Kerry Fox","avatar":""},{"name":"Pilar López de Ayala","avatar":""},{"name":"Izán Corchero","avatar":""},{"name":"Imogen Gray","avatar":""},{"name":"Michael Nardone","avatar":""},{"name":"Mark Wingett","avatar":""},{"name":"Natasha Dosanjh","avatar":""},{"name":"Héctor Alterio","avatar":""},{"name":"Ralph Ineson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324472);
