INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-den', 'Danh Sách Đen', 'The Hit List', 'https://phimimg.com/upload/vod/20231102-1/673f4ed73c8e317a3888d4cca5ee2567.jpg', 'https://phimimg.com/upload/vod/20231102-1/f89c4e4e734bf781a97b91bcf0f296d8.jpg', '<p>Một người đàn ông bất mãn tạo ra một danh sách sát thủ với một người lạ trong một đêm say xỉn và sau đó phải chạy đua để cố gắng cứu những người mà anh ta đánh dấu để tiêu diệt khi các thi thể bắt đầu chất đống và mọi ngón tay đều chỉ về phía anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Jonathan LaPaglia","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Drew Waters","avatar":""},{"name":"Sarah Ann Schultz","avatar":""},{"name":"Holt Boggs","avatar":""},{"name":"David E. Ornston","avatar":""},{"name":"Ginny Weirick","avatar":""},{"name":"Sean Cook","avatar":""},{"name":"Brandon O''Neill","avatar":""},{"name":"J.P. O''Shaughnessy","avatar":""},{"name":"David Andriole","avatar":""},{"name":"Daniel Brockley","avatar":""},{"name":"Rich Cowan","avatar":""},{"name":"Katarzy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
