INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-sach-den', 'Danh Sách Đen', 'The Hit List', 'danh sách đen the hit list cuba gooding jr. cole hauser jonathan lapaglia michael papajohn drew waters sarah ann schultz holt boggs david e. ornston ginny weirick sean cook brandon o''neill j.p. o''shaughnessy david andriole daniel brockley rich cowan katarzy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-thoai-luong-nan', 'Tiến Thoái Lưỡng Nan', 'The Dilemma', 'https://phimimg.com/upload/vod/20231101-1/ad45fd05affe13c5fef8c7afb0a5ffff.jpg', 'https://phimimg.com/upload/vod/20231101-1/035ed0e4a7878097953dcd2258367ace.jpg', '<p>Ngay từ khi còn học đại học, Ronny và Nick đã là đôi bạn thân thiết với nhau. Hiện tại cả hai đang làm tại một cơ sở thiết kế ô tô, và cả hai đang mơ ước có thể thành lập công ty riêng. Bạn gái của Ronny - Beth - và vợ của Nick - Geneva - cũng luôn sát cánh bên hai người. Tuy nhiên, thế giới như đảo lộn đối với Ronny khi anh vô tình phát hiện ra có vẻ như Geneva đang ngoại tình, và quyết định phải làm sáng tỏ vụ việc. Công cuộc điều tra bắt đầu và Ronny phát hiện ra nhiều điều bí mật bất ngờ. Trong khi thời gian cho buổi thuyết trình lớn quyết định sự nghiệp của cả hai đang đến gần, Ronny phải quyết định xem có nên nói với người bạn thân nhất của mình những gì anh biết hay không...</p>', 'Full', 1, 'single', 'completed', 22, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Rance Howard","avatar":""},{"name":"Laura Whyte","avatar":""},{"name":"Amy Morton","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Heidi Johanningmeier","avatar":""},{"name":"Rebecca Spence","avatar":""},{"name":"Grace Rex","avatar":""},{"name":"Mimi Sagadin","avatar":""},{"name":"Eduardo N. Martine","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
