INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thoat', 'Lối Thoát', 'The Ledge', 'https://phimimg.com/upload/vod/20231101-1/14fc61ceba2a7076cb439985a173b871.jpg', 'https://phimimg.com/upload/vod/20231101-1/2ff2a517dcb68f9d89c462c0cf8ca7a2.jpg', '<p>Bộ phim tập trung vào một người đàn ông (Hunnam) dọa sẽ tự vẫn bằng cách nhảy từ một ngôi nhà cao chọc trời. Còn nam diễn viên Gorham sẽ đóng vai người bạn cùng phòng của người đàn ông này. Một trận chiến của tâm lý giữa một Kitô chính thống và một người vô thần. Cuối cùng, ai sẽ là người chiến thắng?</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Jaqueline Fleming","avatar":""},{"name":"Mike Pniewski","avatar":""},{"name":"Jillian Batherson","avatar":""},{"name":"Dean J. West","avatar":""},{"name":"Amber Gaiennie","avatar":""},{"name":"Katia Gomez","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Maxine Greco","avatar":""},{"name":"Geraldine Singer","avatar":""},{"name":"Tyler Humphrey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
