INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-hanh-phuc-', 'Thời Khắc Hạnh Phúc', 'A Happy Event', 'https://phimimg.com/upload/vod/20231101-1/e80b2d98f9dd42f3db36e349568bef00.jpg', 'https://phimimg.com/upload/vod/20231101-1/427523af2369bb205cf01f887561fd0b.jpg', '<p>Cô ấy dồn tôi vào một góc, rồi ép tôi đi quá giới hạn của mình. Cô ấy khiến tôi phải đối mặt với sự tuyệt đối: tình yêu, sự hy sinh, sự dịu dàng, sự từ bỏ. Cô ấy làm tôi trật khớp, biến đổi tôi. Tại sao không ai cảnh báo tôi? Tại sao không ai từng nói về điều này?&quot; Un heureux événement, hay một cái nhìn sâu sắc về tình mẫu tử, chân thành và không kiêng kỵ.</p>', 'Full', 1, 'single', 'completed', 27, 2011, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Louise Bourgoin","avatar":""},{"name":"Pio Marmaï","avatar":""},{"name":"Josiane Balasko","avatar":""},{"name":"Thierry Frémont","avatar":""},{"name":"Gabrielle Lazure","avatar":""},{"name":"Firmine Richard","avatar":""},{"name":"Anaïs Croze","avatar":""},{"name":"Daphné Bürki","avatar":""},{"name":"Lannick Gautry","avatar":""},{"name":"Nicole Valberg","avatar":""},{"name":"Louis-Do de Lencquesaing","avatar":""},{"name":"Ophélie Koering","avatar":""},{"name":"Amélie Glenn","avatar":""},{"name":"Patrick Spadrille","avatar":""},{"name":"Bruno Georis","avatar":""},{"name":"Dominiqu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324472);
