INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-so-8', 'Trang Số 8', 'Page Eight', 'https://phimimg.com/upload/vod/20231101-1/78fb446c2dc40021266dc531128d1da1.jpg', 'https://phimimg.com/upload/vod/20231101-1/26510b00fab27365eb8db88028463eab.jpg', '<p>Johnny Worricker là một nhân viên lâu năm của MI5. Ông chủ và cũng là người bạn tốt nhất của ông, Benedict Baron bất ngờ qua đời, bỏ lại đằng sau một tập hồ sơ không thể giải thích được, đe dọa sự ổn định của tổ chức. Trong khi đó, cơ hội ập đến khi Jonhny gặp người hàng xóm của mình và nhà hoạt động chính trị Nancy Pierpan. Jonhny buộc phải rời bỏ công việc của mình cùng với thân phận hiện tại để tìm ra sự thật...</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Tom Hughes","avatar":""},{"name":"Judy Davis","avatar":""},{"name":"Rakhee Thakrar","avatar":""},{"name":"Saskia Reeves","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Marthe Keller","avatar":""},{"name":"Richard Lintern","avatar":""},{"name":"Holly Aird","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Kate Burdette","avatar":""},{"name":"Aisling Loftus","avatar":""},{"name":"Andrew Cleaver","avatar":""},{"name":"Rory Morr","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
