INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-quan-san-nhay-', 'Quán Quân Sàn Nhảy', 'Beat the World', 'https://phimimg.com/upload/vod/20231101-1/9360bc8ae3e1cfae374b8fa21d82c095.jpg', 'https://phimimg.com/upload/vod/20231101-1/adc13ce9e6f55b1bc46f490a393b9fdc.jpg', '<p>Ba nhóm nhảy - một người Mỹ Latinh, một người châu Âu và một người Canada - chuẩn bị chiến đấu tại cuộc thi International Beat the World ở Detroit. Trên đường đi, họ phải vật lộn với nợ nần cờ bạc, những cuộc chia tay tồi tệ và cái tôi của chính họ. Trong trận đấu cuối cùng để trở thành nhà vô địch thế giới, họ thấy rằng những hy vọng, ước mơ và thậm chí cả mạng sống của họ đang bị đe dọa.</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Tyrone Marshall Brown","avatar":""},{"name":"Mishael Morgan","avatar":""},{"name":"Nikki Grant","avatar":""},{"name":"Chase Armitage","avatar":""},{"name":"Ray Johnson","avatar":""},{"name":"Kristy Flores","avatar":""},{"name":"Shane Pollard","avatar":""},{"name":"Luís Lobianco","avatar":""},{"name":"Teresa Espinosa","avatar":""},{"name":"SebiJaeger","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
