INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-do-chet-nguoi', 'Cám Dỗ Chết Người', 'A Dangerous Method', 'https://phimimg.com/upload/vod/20231101-1/532c715f0ad7da509da276e02868c26a.jpg', 'https://phimimg.com/upload/vod/20231101-1/37e0a583d4a9f0fd0356b9a09620da41.jpg', '<p>Bị cám dỗ bởi thử thách từ một ca bệnh lạ lùng, bác sĩ Jung (Michael Fassbender) nhận lời chữa trị cho Sabina Spielrein (Keira Knightley) – một phụ nữ bị rối loạn tâm thần nhưng rất xinh đẹp. Vũ khí của Jung chính là phương pháp của thầy ông – nhà tâm lý học Sigmund Freud nổi tiếng. Nhưng rồi cả hai cùng trúng phải bùa mê của Sabina.</p>', 'Full', 1, 'single', 'completed', 23, 2011, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"André Hennicke","avatar":""},{"name":"Arndt Schwering-Sohnrey","avatar":""},{"name":"Mignon Remé","avatar":""},{"name":"Mareike Carrière","avatar":""},{"name":"Franziska Arndt","avatar":""},{"name":"Wladimir Matuchin","avatar":""},{"name":"André Dietz","avatar":""},{"name":"Anna Thalbach","avatar":""},{"name":"Sarah Marecek","avatar":""},{"name":"Björn Geske","avatar":""},{"name":"Markus H","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
