INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-cuong-dam', 'Sát Nhân Cuồng Dâm', 'Cassadaga', 'https://phimimg.com/upload/vod/20231101-1/a971512e256c1d3035ec88a0b8dacb88.jpg', 'https://phimimg.com/upload/vod/20231101-1/053b8956875036adc115bdce56bd77ea.jpg', '<p>Nội dung của Phim Sát Nhân Cuồng Dâm là câu chuyện giả tưởng được xây dựng trên những tình tiết giật gân với nhiều hình ảnh máu me kinh dị 18+.Một cô gái khiếm thính cố gắng liên hệ với em gái của mình trong sự chiêu hồn, chỉ để kết nối với các bóng ma của một phụ nữ bị sát hại.Bị ám ảnh bởi cái chết của em gái mình, Lily Morel tìm kiếm niềm an ủi tại cộng đồng duy linh của Cassadaga. Tại đây thay vì sống khép kín, cô liên lạc một cái gì đó rất khác, đó là hồn ma trả thù của một phụ nữ trẻ bị sát hại và Lily cố gắng làm mọi cách điều tra để làm sáng tỏ những bí ẩn xung quanh cái chết bí ẩn của 1 người phụ nữ này, nó khiến cô phải đối mặt với một kẻ giết người hàng loạt được biết đến với cái tên “Geppetto”.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kelen Coleman","avatar":""},{"name":"Kevin Alejandro","avatar":""},{"name":"Louise Fletcher","avatar":""},{"name":"Rus Blackwell","avatar":""},{"name":"Lucas Beck","avatar":""},{"name":"Lucius Baston","avatar":""},{"name":"Amy LoCicero","avatar":""},{"name":"Sarah Sculco","avatar":""},{"name":"Rachel Durose","avatar":""},{"name":"Avis-Marie Barnes","avatar":""},{"name":"Hank Stone","avatar":""},{"name":"Christina Bach","avatar":""},{"name":"Carlos Navarro","avatar":""},{"name":"Amy Dionne Bevly","avatar":""},{"name":"Janine Klein","avatar":""},{"name":"Garrett Boyle","avatar":""},{"name":"Beth Marsha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"