INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vi-sep-kho-tinh', 'Những Vị Sếp Khó Tính', 'Horrible Bosses', 'https://phimimg.com/upload/vod/20231030-1/d1a037e94a82e1b10ae20fd0cc9c8143.jpg', 'https://phimimg.com/upload/vod/20231030-1/4200bfb88a5a5c9d32325d03759c2a23.jpg', '<p>Horrible Bosses (Những Vị Sếp Khó Tính) là bộ phim hài hước thiên về mô tả sự dối trá, các mánh khóe, quấy rối tình dục nơi công sở và định kiến. Nội dung phim xoay quanh Kurt, Dale và Nick là 3 anh mệt mỏi với những rắc rối đến từ cấp trên khó tính và lập dị của mình. Vì thế, 3 người lập kế hoạch tiêu diệt những vị sếp khó ưa nhưng mọi việc không dễ dàng như họ nghĩ. Và đồng hành cùng họ là một tên xã hội đen, người tư vấn cho kế hoạch mưu sát của ba anh chàng trên...</p>', 'Full', 1, 'single', 'completed', 13, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Lindsay Sloane","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Ron White","avatar":""},{"name":"John Francis Daley","avatar":""},{"name":"Meghan Markle","avatar":""},{"name":"Steve Wiebe","avatar":""},{"name":"Michael Albala","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
