INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-bat-tu', 'Chiến Binh Bất Tử', 'Immortals', 'https://phimimg.com/upload/vod/20231029-1/5cbcb9d3c96aacf53923de11dc007507.jpg', 'https://phimimg.com/upload/vod/20231029-1/8a15cd670c66f20429ece7c8259800e2.jpg', '<p>Immortals là câu chuyện cuộc chiến giữa các vị thần trên đỉnh Olympia và những thần dân Hy Lạp chống lại cuộc xâm lược của đế chế Hyperion (Mickey Rourke). Một đội quân khát máu đã tiến vào Hy Lạp tàn sát không thương tiếc dân lành chỉ với một mục đích là tìm một loại vũ khí chết người để tiêu diệt và chiếm lĩnh toàn thế giới. Khi số phận của nhân loại thực sự bị đe dọa Zeus vị thần tối cao trên đỉnh Olympia đã chọn Theseus (Cavill) phải lãnh đạo nhân dân chống lại Hyperion.</p>', 'Full', 1, 'single', 'completed', 14, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Henry Cavill","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Freida Pinto","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Joseph Morgan","avatar":""},{"name":"Isabel Lucas","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Daniel Sharman","avatar":""},{"name":"Peter Stebbings","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Alan van Sprang","avatar":""},{"name":"Anne Day-Jones","avatar":""},{"name":"Steve Byers","avatar":""},{"name":"Matthew G. Taylor","avatar":""},{"name":"Roman","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
