INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-dai-hoi-o-pixie', 'Tinker Bell: Đại Hội Ở Pixie', 'Pixie Hollow Games', 'https://phimimg.com/upload/vod/20231030-1/ea455e6296697821d97fdae3400b9224.jpg', 'https://phimimg.com/upload/vod/20231030-1/9e77636d20b66cb258106a5c61a51e32.jpg', '<p>Tinker Bell được sinh ra từ nụ cười đầu tiên của đứa trẻ sơ sinh và được ngọn gió mang tới Pixie Hollow (một hòn đảo ở Never Land). Tại đây cô gặp những nàng tiên nhỏ khác và biết rằng năng lực của mình là để phục vụ việc hàn gắn mọi thứ - một thiên thần sửa chữa mọi thứ. Các tiên thợ khác đã giúp nhân viên mới học việc và Tinker Bell đã học được nghề, cô có thể sửa được máy nhạc bằng việc sử dụng nước biển. Thế rồi khi cô được kể rằng, chỉ có các nàng tiên thường mới có thể vào lục địa thì cô thấy hơi chạnh lòng cho các nàng tiên như mình. Rồi cô cố gắng nâng cao năng lực của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 26, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Megan Hilty","avatar":""},{"name":"Brenda Song","avatar":""},{"name":"Jason Dolley","avatar":""},{"name":"Tiffany Thornton","avatar":""},{"name":"Zendaya","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Angela Bartys","avatar":""},{"name":"Pamela Adlon","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Jessica DiCicco","avatar":""},{"name":"Jesse McCartney","avatar":""},{"name":"Daniel Curtis","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324472);
