INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-chuoc-toi', 'Đột Kích: Chuộc Tội', 'The Raid', 'https://phimimg.com/upload/vod/20231026-1/7e013d1db943c943e38c308688608d60.jpg', 'https://phimimg.com/upload/vod/20231026-1/e083de5e9c0d2be3d532d271878a2d1c.jpg', '<p>Phim nói về 1 khu chung cư bị bỏ hoang ở Jarkata đã lâu. Khu nhà này trở thành 1 nơi mà đến lực lượng cảnh sát chưa bao giờ muốn đến thăm! Lợi dụng ngôi nhà bỏ hoang không ai thèm đến, các băng đảng và các nhóm buôn ma túy đã chọn nơi này làm cứ điểm của chúng. Trong đó đặc biệt nhất là trùm buôn ma túy khét tiếng Tama. Một đội SWAT được trang bị vũ khí tối tân để săn lùng và tiêu diệt tên trùm buôn ma túy khét tiếng Tama này. Liệu họ có thành công?</p>', 'Full', 1, 'single', 'completed', 21, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Iko Uwais","avatar":""},{"name":"Joe Taslim","avatar":""},{"name":"Donny Alamsyah","avatar":""},{"name":"Yayan Ruhian","avatar":""},{"name":"Pierre Gruno","avatar":""},{"name":"Ray Sahetapy","avatar":""},{"name":"Tegar Satrya","avatar":""},{"name":"Iang Darmawan","avatar":""},{"name":"Eka ''Piranha'' Rahmadia","avatar":""},{"name":"Verdi Solaiman","avatar":""},{"name":"Alfridus Godfred","avatar":""},{"name":"Rully Santoso","avatar":""},{"name":"Melkias Ronald Torobi","avatar":""},{"name":"Johanes Tuname","avatar":""},{"name":"Sofyan Alop","avatar":""},{"name":"R. Iman Aj","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
