INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dot-kich-chuoc-toi', 'Đột Kích: Chuộc Tội', 'The Raid', 'đột kích: chuộc tội the raid iko uwais joe taslim donny alamsyah yayan ruhian pierre gruno ray sahetapy tegar satrya iang darmawan eka ''piranha'' rahmadia verdi solaiman alfridus godfred rully santoso melkias ronald torobi johanes tuname sofyan alop r. iman aj ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-dung-cam', 'Lòng Dũng Cảm', 'Courageous', 'https://phimimg.com/upload/vod/20231026-1/0147bbae823bb0e4bb04d93f343eb4b3.jpg', 'https://phimimg.com/upload/vod/20231026-1/3ace0a8b3bccddf84f2a8be28bdbb94e.jpg', '<p>Các nhân viên thực thi pháp luật Adam Mitchell, Nathan Hayes và các đối tác của họ đương đầu với những điều tồi tệ nhất mà đường phố gặp phải với sự tự tin và tập trung. Tuy nhiên, vào cuối ngày, họ phải đối mặt với một thử thách mà không ai trong số họ thực sự sẵn sàng giải quyết: làm cha. Họ biết rằng Thiên Chúa mong muốn làm thay đổi tấm lòng của những người cha đối với con cái họ, nhưng con cái của họ đang bắt đầu ngày càng rời xa họ. Khi bi kịch ập đến nhà, những người đàn ông này phải vật lộn với hy vọng, nỗi sợ hãi, niềm tin và tình cha con của họ. Liệu một nhu cầu cấp thiết mới có thể giúp những người cha này đến gần Chúa hơn... và với con cái của họ không?</p>', 'Full', 1, 'single', 'completed', 11, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ken Bevel","avatar":""},{"name":"Alex Kendrick","avatar":""},{"name":"Kevin Downes","avatar":""},{"name":"Renee Jewell","avatar":""},{"name":"Rusty Martin","avatar":""},{"name":"Lauren Etchells","avatar":""},{"name":"Ben Davies","avatar":""},{"name":"Robert Amaya","avatar":""},{"name":"Angelita Nelson","avatar":""},{"name":"Taylor Hutcherson","avatar":""},{"name":"Eleanor Brown","avatar":""},{"name":"T.C. Stallings","avatar":""},{"name":"Matt Hardwick","avatar":""},{"name":"Kaleb Bevel","avatar":""},{"name":"Ashley Mclearn","avatar":""},{"name":"Amberly Marquard","avatar":""},{"name":"Bryan Barnes","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
