INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('long-dung-cam', 'Lòng Dũng Cảm', 'Courageous', 'lòng dũng cảm courageous ken bevel alex kendrick kevin downes renee jewell rusty martin lauren etchells ben davies robert amaya angelita nelson taylor hutcherson eleanor brown t.c. stallings matt hardwick kaleb bevel ashley mclearn amberly marquard bryan barnes k ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-so-bon', 'Tôi Là Số Bốn', 'I Am Number Four', 'https://phimimg.com/upload/vod/20231026-1/36bb034075d9f03faa2d8f41811f3a95.jpg', 'https://phimimg.com/upload/vod/20231026-1/44477ff33eba72f2683a7ab182aa2aef.jpg', '<p>John Smith, một chàng trai với năng lực đặc biệt, trên đường chạy trốn khỏi những kẻ thù độc ác có âm mưu sát hại mình. Liên tục thay đổi thân thế, không ngừng di chuyển từ thành phố này sang thành phố khác cùng người giám hộ là Henri, John tưởng như đã không còn mối liên hệ nào với quá khứ. Tại thị trấn nhỏ Ohio mà giờ đã được gọi là nhà, John bắt đầu vướng phải những sự kiện nằm ngoài dự kiến, có khả năng làm thay đổi số phận của cậu – tiếng sét ái tình đầu đời, những quyền lực mới mẻ và mối liên hệ với những người chia sẻ số phận như mình… Phim được chuyển thể từ cuốn sách cùng tên của hai nhà văn James Frey và Job Hughes.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Alex Pettyfer","avatar":""},{"name":"Dianna Agron","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"Garrett M. Brown","avatar":""},{"name":"Patrick Sebes","avatar":""},{"name":"Emily Wickersham","avatar":""},{"name":"Jeff Hochendoner","avatar":""},{"name":"Greg Townley","avatar":""},{"name":"Reuben Langdon","avatar":""},{"name":"Molly McGinnis","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"Andy Owen","avatar":""},{"name":"Sophia Anne","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
