INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-dau', 'Phù Dâu', 'Bridesmaids', 'https://phimimg.com/upload/vod/20231026-1/616e3e5ab31653a249b5bc99de1e08fd.jpg', 'https://phimimg.com/upload/vod/20231026-1/c750093483e948de8858f212ef3a3491.jpg', '<p>Khi một thợ bánh thiếu việc làm trở thành phù dâu danh dự của người bạn thân, cô suýt phá hỏng ngày trọng đại của bạn mình khi ganh đua với các phù dâu khác.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Wiig","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Ellie Kemper","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Jill Clayburgh","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Michael Hitchcock","avatar":""},{"name":"Tim Heidecker","avatar":""},{"name":"Franklyn Ajaye","avatar":""},{"name":"Lynne Marie Stewart","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Jessic","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
