INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-toc-do-2-linh-hon-bao-thu', 'Ma Tốc Độ 2: Linh Hồn Báo Thù', 'Ghost Rider: Spirit of Vengeance', 'https://phimimg.com/upload/vod/20231026-1/792e47b0123bc58f390db82178f61ab1.jpg', 'https://phimimg.com/upload/vod/20231026-1/1bd511fd5be5e43ebea6e9bff4b0554e.jpg', '<p>Trong phần này, Johnny Blaze đến vùng Đông Âu ở ẩn và đấu tranh để trấn áp lời nguyền anh phải chịu trong phần 1 - là thợ săn tiền thưởng của quỷ dữ. Tại đây, Johnny được một giáo phái bí mật của nhà thờ tuyển dụng để cứu một cậu bé thoát khỏi ma quỷ. Anh miễn cưỡng trở lại với sức mạnh của Ghost Rider…</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Violante Placido","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Johnny Whitworth","avatar":""},{"name":"Fergus Riordan","avatar":""},{"name":"Spencer Wilding","avatar":""},{"name":"Sorin Tofan","avatar":""},{"name":"Jacek Koman","avatar":""},{"name":"Anthony Stewart Head","avatar":""},{"name":"Cristian Iacob","avatar":""},{"name":"Christophe Lambert","avatar":""},{"name":"Jai Stefan","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Ionut Cristian Lefter","avatar":""},{"name":"Will Ashcrof","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
