INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-den-long-xanh', 'Chiến Binh Đèn Lồng Xanh', 'Green Lantern', 'https://phimimg.com/upload/vod/20231026-1/8c3b0b0199ea956064ba957e40976174.jpg', 'https://phimimg.com/upload/vod/20231026-1/287258dd5df1fef9ab33ff8c82f55c71.jpg', '<p>Chiến Binh Đèn Lồng Xanh kể về Abin Sur, một Green Lantern có lớp da màu tím đang phải chống lại kẻ thù bí ẩn và bị thất thế. Ngay lập tức ông đã quyết định dùng con tàu cứu nạn bay tới Trái Đất. &nbsp;Ở đây, chiếc nhẫn quyền năng của ông đã lựa chọn chàng phi công trẻ Hal Jordan làm Green Lantern kế nhiệm.Sau khi đọc xong lời thề của một Green Lantern trong phim hay này, Hal đã được chiếc nhẫn trao cho quyền năng vô biên và đưa thẳng tới hành tinh Oa - cơ quan đầu não của các Green Lantern trong khắp thiên hà. Tại đây, một cuộc họp lớn giữa các Green Lantern từ tứ phương đổ về đang diễn ra.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Gattlin Griffith","avatar":""},{"name":"Jenna Craig","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Nick Jandl","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug