INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngua-chien', 'Ngựa Chiến', 'War Horse', 'https://phimimg.com/upload/vod/20231024-1/89e9fad6f4c312dd9d5dc7da99c145c8.jpg', 'https://phimimg.com/upload/vod/20231024-1/dd27b9b64279890912c01becc409f369.jpg', '<p>Sau bao tháng “găm hàng”, những hình ảnh mới nhất trong bộ phim War Horse của đạo diễn Steven Spielberg cuối cùng cũng đã được hé lộ. Đây là một trong những bộ phim được mong đợi nhất trong năm 2011 của đạo diễn từng 3 lần đoạt giải Oscar này. War Horse dựa trên tiểu thuyết best seller cùng tên của tác giả Michael Morpurgo. Lấy bối cảnh miền Tây nước Anh trong giai đoạn Thế chiến thứ nhất, War Horse là câu chuyện về chàng trai Albert cùng với chú ngựa Joey của mình. Cả hai là những người bạn thân thiết với nhau, nhưng rồi một ngày, Joey lại bị bán cho quân đội để phục vụ binh lính trên chiến trường. Không thể bỏ mặc bạn mình nên Albert cũng quyết định tham gia nhập ngũ dù với quyết tâm tìm lại Joey.Hành trình trong cuộc chiến của ...</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Jeremy Irvine","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Niels Arestrup","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Celine Buckens","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Patrick Kennedy","avatar":""},{"name":"Leonard Carow","avatar":""},{"name":"David Kross","avatar":""},{"name":"Matt Milne","avatar":""},{"name":"Robert Emms","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Nicolas Bro","avatar":""},{"name":"Rainer Bock","avatar":""},{"name":"Hin","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
