INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-nam-dau-tien', 'Người Dơi: Năm Đầu Tiên', 'Batman: Year One', 'https://phimimg.com/upload/vod/20231023-1/2937d7ea8a4d9f7a70a4b8e58855149c.jpg', 'https://phimimg.com/upload/vod/20231023-1/777053a18fa039e07cf0feae42edc36a.jpg', '<p>Người Dơi: Năm Đầu Tiên nói về thời kỳ đầu sau khi Bruce Wayne trở lại Gotham sau 12 năm luyện tập võ thuật và nhiều kỹ năng khác ở nước ngoài, và sĩ quan cảnh sát Jim Gordon từ Chicago bị chuyển công tác sang Gotham phải mang cả gia đình theo. Cả 2 người chứng kiến sự thối nát của cảnh sát và bọn tội phạm ở Gotham...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben McKenzie","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Eliza Dushku","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Alex Rocco","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"Sara Ballantine","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Roark Critchlow","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Danny Jacobs","avatar":""},{"name":"Nick Jameson","avatar":""},{"name":"Liliana Mumy","avatar":""},{"name":"Pat Musick","avatar":""},{"name":"Andrea","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
