INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu-colombia', 'Nữ Sát Thủ Colombia', 'Colombiana', 'https://phimimg.com/upload/vod/20231023-1/a80bdd53abbfbb74a4cfda777c5f316b.jpg', 'https://phimimg.com/upload/vod/20231023-1/11b17d74e2e12a0292cbbe46561bb046.jpg', '<p>Colombiana là câu chuyện trả thù xoay quanh một vụ án đã xảy ra hơn chục năm trước, một đứa trẻ đã là tận mắt chứng kiến vụ cha mẹ mình bị tàn sát một cách dã man bởi một một sát thủ máu lạnh khi cô là đứa trẻ ở Bogota. Cô con gái may mắn thoát chết nhưng không một tên sát nhân nào bị bắt. Số phận đã đưa cô gái bé nhỏ đến với người bác của mình. Chính từ đây, lòng thù hận, ham muốn báo thù bắt đầu được nuôi dưỡng trong tâm trí cô bé. Lớn lên, cô trở thành 1 nữ sát thủ, âm thầm hành động đơn độc với mục tiêu là trả thù cho cái chết của cha mẹ mình. Cuộc phiêu lưu của cô rồi sẽ đi tới đâu? Công lý liệu có tồn tại theo đúng nghĩa của nó?</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Zoe Saldaña","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Callum Blue","avatar":""},{"name":"Michael Vartan","avatar":""},{"name":"Lennie James","avatar":""},{"name":"Amandla Stenberg","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Jesse Borrego","avatar":""},{"name":"Cynthia Addai-Robinson","avatar":""},{"name":"Ofelia Medina","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Affif Ben Badra","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Charles Maquignon","avatar":""},{"name":"Beto Benitez","avatar":""},{"name":"Sam Douglas","avatar":""},{"name":"Angel G","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529