INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-lai-sieu-hang', 'Tay Lái Siêu Hạng', 'Drive', 'https://phimimg.com/upload/vod/20231023-1/1b09b362ecd9b7068481e17bfb0a081e.jpg', 'https://phimimg.com/upload/vod/20231023-1/822483652783a520e1811bac01d7f4fd.jpg', '<p>Drive là câu chuyện ở Hollywood về một diễn viên đóng thế (Gosling) các cảnh đua xe trong phim hành động. Cuộc sống của anh cũng bình lặng như những diễn viên hạng thường ở Hollywood, một căn hộ nhỏ và mối tình với cô gái hàng xóm. Nhưng thật ra nghề tay phải của anh là lái thuê cho bọn tội phạm trong các phi vụ đánh cướp. Cho đến khi thực hiện một hợp đồng lái thuê, anh nhận ra mình bị dính vào một vụ án nguy hiểm có thể hại cả anh và người yêu. Điều duy nhất có thể cứu cả hai là anh phải ngồi sau vô lăng và đạp ga tăng hết tốc lực.</p>', 'Full', 1, 'single', 'completed', 23, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Albert Brooks","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Kaden Leos","avatar":""},{"name":"Jeff Wolfe","avatar":""},{"name":"James Biberi","avatar":""},{"name":"Russ Tamblyn","avatar":""},{"name":"Joe Bucaro III","avatar":""},{"name":"Tiara Parker","avatar":""},{"name":"Tim Trella","avatar":""},{"name":"Jimmy Hart","avatar":""},{"name":"Tina Huang","avatar":""},{"name":"Andy San Dimas","avatar":""},{"name":"John Pyper-Fe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]',