INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('captain-america-ke-bao-thu-dau-tien', 'Captain America: Kẻ Báo Thù Đầu Tiên', 'Captain America: The First Avenger', 'https://phimimg.com/upload/vod/20231023-1/52b540fe25106beae3fdf132bfe6fb01.jpg', 'https://phimimg.com/upload/vod/20231023-1/c57522ab9758306b8318fc880db5d43d.jpg', '<p>lấy bổi cách từ đầu năm 1942, khi Mỹ đang tham gia Thế chiến thứ II và cần tới những chiến binh can trường. Chàng trai Steve Rogers (Chris Evans) là một người như vậy, nhưng thể hình quá thấp bé khiến anh không thể đạt được ước mơ tòng quân. Cơ may đến với Rogers khi anh được chọn tham gia một thí nghiệm của chính phủ, giúp biến người thường trở thành siêu chiến binh.&nbsp; Mọi việc diễn ra suôn sẻ, biến Rogers thành một người cao to vạm vỡ, đầu óc tiếp thu mọi kỹ năng chiến đấu nhanh và vẫn giữ được trái tim nhân hậu.Anh trở thành Captain America, biểu tượng của nước Mỹ kể từ đó. Đối thủ của anh là phe Phát-xít, với quái nhân Red Skull, kẻ không chỉ quyền năng mà còn rất tàn ác.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Bruno Ricci","avatar":""},{"name":"JJ Feild","avatar":""},{"name":"Kenneth Choi","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Lex Shrapnel","avatar":""},{"name":"Michael Brandon","avatar":""},{"name":"Mart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324472);
