INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rango-tac-ke-nhat-gan', 'Rango: Tắc Kè Nhát Gan', 'Rango', 'https://phimimg.com/upload/vod/20231020-1/b965a04e0794cd6b1ed38ca8230c510d.jpg', 'https://phimimg.com/upload/vod/20231020-1/8cbe74e731e426b6b13c74bcaab850c5.jpg', '<p>Khi Rango, thú cưng bị thất lạc của gia đình, vô tình đến thị trấn Dirt khắc nghiệt, đầy súng đạn, con thằn lằn kém can đảm đột nhiên thấy mình nổi bật. Được chào đón như niềm hy vọng cuối cùng mà thị trấn đang chờ đợi, cảnh sát trưởng mới Rango buộc phải đảm nhận vai trò mới của mình một cách triệt để.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Ned Beatty","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Harry Dean Stanton","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Ian Abercrombie","avatar":""},{"name":"Gil Birmingham","avatar":""},{"name":"James Ward Byrkit","avatar":""},{"name":"Claudia Black","avatar":""},{"name":"Blake Clark","avatar":""},{"name":"John Cothran","avatar":""},{"name":"Patrika Darbo","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
