INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than-cuoc-dam-mau-bat-dau', 'Ngã Rẽ Tử Thần: Cuộc Đẫm Máu Bắt Đầu', 'Wrong Turn 4: Bloody Beginnings', 'https://phimimg.com/upload/vod/20231020-1/e91508d20f74bc870b7963b996ae2ad8.jpg', 'https://phimimg.com/upload/vod/20231020-1/ea02c3f47834aa782f5166a8537610c4.jpg', '<p>Vào những ngày mùa đông lạnh giá, một nhóm bạn trẻ đang đi trượt tuyết trong khu rừng Virginia thì gặp bão tuyết, mà trời cũng gần tối. Họ không biết nên tránh bão nơi nào, nhưng khi nhìn từ xa xa, họ thấy có một ngôi nhà to lớn y như một lâu đài. Cả bọn liền đến đó nghĩ một đêm, họ không hề biết trước kia, nói đúng hơn là 16 năm trước nơi đây là bệnh viện tâm thần, từng nhốt những bệnh nhân tâm thần nguy hiểm trong đó có 3 đứa trẻ bị đột biến gen điên dại, ác độc và khát máu. Giờ đây bọn chúng đã trở thành những gã to con, sự nguy hiểm của bọn chúng chắc hẳn đã tăng lên gấp bội. Nhóm bạn này có chạy thoát khỏi bọn quái vật này không, hay tất cả bọn họ đều thành bữa ăn của chúng.</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jennifer Pudavick","avatar":""},{"name":"Tenika Davis","avatar":""},{"name":"Terra Vnesa","avatar":""},{"name":"Kristen Harris","avatar":""},{"name":"Kaitlyn Leeb","avatar":""},{"name":"Dean Armstrong","avatar":""},{"name":"Ali Tataryn","avatar":""},{"name":"Victor Zinck Jr.","avatar":""},{"name":"Samantha Kendrick","avatar":""},{"name":"Sean Skene","avatar":""},{"name":"Dan Skene","avatar":""},{"name":"Arne MacPherson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
