INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nga-re-tu-than-cuoc-dam-mau-bat-dau', 'Ngã Rẽ Tử Thần: Cuộc Đẫm Máu Bắt Đầu', 'Wrong Turn 4: Bloody Beginnings', 'ngã rẽ tử thần: cuộc đẫm máu bắt đầu wrong turn 4: bloody beginnings jennifer pudavick tenika davis terra vnesa kristen harris kaitlyn leeb dean armstrong ali tataryn victor zinck jr. samantha kendrick sean skene dan skene arne macpherson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-ben-le', 'Những Kẻ Bên Lề', 'Intouchables', 'https://phimimg.com/upload/vod/20231020-1/14a41c8c94aad6c155362e2e76d54bde.jpg', 'https://phimimg.com/upload/vod/20231020-1/481d5a9a3240f19e288ef103296c6d34.jpg', '<p>Chỉ sau 7 ngày đầu được công chiếu, bộ phim Intouchables (Những kẻ bên lề) đã thu hút gần 2 triệu rưỡi lượt khán giả tại Pháp. Một thành tích khá bất ngờ vì phim này được cho ra mắt hầu như cùng một thời điểm với hai đối thủ nặng ký đến từ Hoa Kỳ là Bí mật của Kỳ lân (Steven Spielberg) và phiên bản mới của Ba chàng ngự lâm pháo thủ (Paul W.S Anderson). Để thành công, bộ phim Những kẻ bên lề chỉ dựa vào cốt truyện kịch bản, chứ không cần đến công nghệ ba chiều hay kỹ xảo điện toán. Tác phẩm này khai thác mạch phim tình cảm xã hội, nó lôi cuốn đông đảo khán giả vào phòng chiếu phim phần lớn vì bộ phim nắm bắt kịp thời thị hiếu của người xem. Vào lúc mà chính phủ Pháp lần lượt ban hành các ...</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"François Cluzet","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Dominique Henry","avatar":""},{"name":"Anne Le Ny","avatar":""},{"name":"Clotilde Mollet","avatar":""},{"name":"Alba Gaïa Bellugi","avatar":""},{"name":"Audrey Fleurot","avatar":""},{"name":"Cyril Mendy","avatar":""},{"name":"Christian Ameri","avatar":""},{"name":"Marie-Laure Descoureaux","avatar":""},{"name":"Salimata Kamate","avatar":""},{"name":"Absa Diatou Toure","avatar":""},{"name":"Dominique Daguier","avatar":""},{"name":"François Caron","avatar":""},{"name":"Thomas Solivérès","avatar":""},{"name":"Grég","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324472);
