INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-si', 'Giáo Sĩ', 'Priest', 'https://phimimg.com/upload/vod/20231020-1/9ab691e5d1ad844ee68030a0e518ea72.jpg', 'https://phimimg.com/upload/vod/20231020-1/7588a1754ac6fcee668981c97fbceff7.jpg', '<p>Câu chuyện xoay quanh chiến binh huyền thoại Priest, sống sót từ sau Cuộc Chiến Ma Cà Rồng gần đây nhất đang phải sống náu mình trong số những con người bị áp bức đang trú ẩn trong thành phố khép kín. Khi cô cháu gái của anh bị một bọn ma cà rồng tàn ác bắt cóc, Priest đã phá bỏ lời thề thiêng liêng của mình để liều mình tìm kiếm cô cháu gái trước khi chúng biến nó thành ma cà rồng. Anh đã thành lập đội thập tự chinh của mình và bao gồm bạn trai của cô cháu gái, cậu cảnh sát trường trẻ tuổi và nữ chiến binh Priestess cũng đã từng tham gia cuộc chiến lần trước, người có được những kĩ năng chiến đấu rất tốt.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Bettany","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Stephen Moyer","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Mädchen Amick","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Marilyn Brett","avatar":""},{"name":"Jacob Hopkins","avatar":""},{"name":"Arnold Chon","avatar":""},{"name":"Dave Florek","avatar":""},{"name":"Joel Polinsky","avatar":""},{"name":"Josh Wingate","avatar":""},{"name":"Jon Braver","avatar":""},{"name":"Casey Pieretti","avatar":""},{"name":"The","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
