INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-muon-chay-bong', 'Ham Muốn Cháy Bỏng', 'Desire', 'https://phimimg.com/upload/vod/20231020-1/9103363256eade70e93beb2db7f63e08.jpg', 'https://phimimg.com/upload/vod/20231020-1/53e7eb6dbfc818bcd017999019d9379c.jpg', '<p>Q là một bộ phim chính kịch khiêu dâm của Pháp năm 2011 của đạo diễn Laurent Bouhnik. Nó đã được phát hành tại Hoa Kỳ với tên gọi Desire.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Déborah Révy","avatar":""},{"name":"Hélène Zimmer","avatar":""},{"name":"Gowan Didi","avatar":""},{"name":"Johnny Amaro","avatar":""},{"name":"Johan Libéreau","avatar":""},{"name":"Jean-François Gallotte","avatar":""},{"name":"Brice Fournier","avatar":""},{"name":"Christelle Benoit","avatar":""},{"name":"Patrick Hauthier","avatar":""},{"name":"Léticia Belliccini","avatar":""},{"name":"Fabien Ara","avatar":""},{"name":"Margot Heurtematte","avatar":""},{"name":"Aurélia Arto","avatar":""},{"name":"Noémie Leroux-Cazaubon","avatar":""},{"name":"Yassine Azzouz","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
