INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-goc', 'Mật Mã Gốc', 'Source Code', 'https://phimimg.com/upload/vod/20231021-1/e7161d683c88812fa9fde65309258946.jpg', 'https://phimimg.com/upload/vod/20231021-1/97124b1d4eb944fdf2f4d3d418d9e579.jpg', '<p>Đặt ra giả thuyết về một tương lai gần khi sự sống của nhân loại bị đe dọa bởi loài virus chết người, phim &quot;Mật mã sống còn&quot; thu hút khán giả bằng những pha hành động nghẹt thở.Hành trình dài 6.000 dặm của tay lính đánh thuê Toorop, hộ tống cô gái trẻ cùng người bảo hộ từ Đông Âu đến nước Mỹ được dự báo rất gian nan và nguy hiểm. Đó không chỉ là trở ngại về mặt địa lý với đại dương bao la hay vùng tuyết phủ, trong một thế giới mà mọi hành động của con người đều bị các vệ tinh theo dõi, giám sát, trên các vùng đất hoang bị ngắt quãng bởi những khu vực nhiễm phóng xạ. Trên hết, khó khăn nhất của đoàn hộ tống là trách nhiệm bảo vệ hy vọng duy nhất, cứu sống tương lai loài người. Vấn đề đặt ra là những ...</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Michael Arden","avatar":""},{"name":"Cas Anvar","avatar":""},{"name":"Russell Peters","avatar":""},{"name":"Brent Skagford","avatar":""},{"name":"Craig Thomas","avatar":""},{"name":"Gordon Masten","avatar":""},{"name":"Susan Bain","avatar":""},{"name":"Paula Jean Hixson","avatar":""},{"name":"Lincoln Ward","avatar":""},{"name":"Kyle Gatehouse","avatar":""},{"name":"Albert Kwan","avatar":""},{"name":"Anne Day-Jones","avatar":""},{"name":"Clarice Byrn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324472);
