INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-manh-me', 'Người Phụ Nữ Mạnh Mẽ', 'Martha Marcy May Marlene', 'https://phimimg.com/upload/vod/20231021-1/8e55abbb524cacdf216f10e0f9000442.jpg', 'https://phimimg.com/upload/vod/20231021-1/fd1df4100f05ecb9813d586fc8f70336.jpg', '<p>Bị ám ảnh bởi những ký ức đau đớn và bệnh hoang tưởng ngày càng nặng, một người phụ nữ này tìm cách đấu tranh để hòa nhập lại với gia đình của mình sau khi chạy trốn một giáo phái. Câu chuyện xoay quanh một phụ nữ trẻ (Elizabeth Olsen), đang sống với chị gái (Sarah Paulson) sau khi thoát khỏi một giáo phái. Hugh Dancy sẽ vào vai chồng của Sarah Paulson.</p>', 'Full', 1, 'single', 'completed', 15, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Olsen","avatar":""},{"name":"Christopher Abbott","avatar":""},{"name":"Brady Corbet","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Maria Dizzia","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Louisa Krause","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Adam David Thompson","avatar":""},{"name":"Allen McCullough","avatar":""},{"name":"Lauren Molina","avatar":""},{"name":"Louisa Braden Johnson","avatar":""},{"name":"Tobias Segal","avatar":""},{"name":"Gregg Burton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
