INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giup-viec', 'Người Giúp Việc', 'The Help', 'https://phimimg.com/upload/vod/20231021-1/bd757a0ffdf6de6f2eab112e98923f0e.jpg', 'https://phimimg.com/upload/vod/20231021-1/70bb6171e7a90e211eb0f1becd2f1867.jpg', '<p>Người Giúp Việc được chuyển thể từ tác phẩm cùng tên của nhà văn Mỹ Kathryn Stockett. Bộ phim nói về câu chuyện của những người giúp việc gốc Phi làm việc trong các gia đình người da trắng ở Jackson, Mississippi vào thời điểm những năm đầu của thập niên 1960. Skeeter là một nhà báo và cô đã quyết định viết một cuốn sách kể về câu chuyện của những người giúp việc da đen qua đó giúp phơi bày sự phân biệt chủng tộc rất rõ rệt của các gia đình da trắng với họ.</p>', 'Full', 1, 'single', 'completed', 31, 2011, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Emma Stone","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"Sissy Spacek","avatar":""},{"name":"​Christopher Lowell","avatar":""},{"name":"Cicely Tyson","avatar":""},{"name":"Aunjanue Ellis-Taylor","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Dana Ivey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
