INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-thep', 'Tay Đấm Thép', 'Real Steel', 'https://phimimg.com/upload/vod/20231018-1/8f2e051929cee2df4b66abfa646185a7.jpg', 'https://phimimg.com/upload/vod/20231018-1/78ae656b1a2260123d6e32e61afe20b0.jpg', '<p>Phim đặt trong tương lai không xa, loài người tạo nên những robot siêu đẳng, khi mà quyền Anh robot trở thành môn thể thao phổ biến và có thể thay thế con người trổ tài trên sàn đấm bốc. Nhưng đó cũng là nơi Charlie - một võ sĩ quyền anh nổi tiếng với những cú đấm “thần sầu” - cảm thấy không thể hòa hợp. Đúng lúc ấy, anh tình cờ tìm được 1 chú robot ở bãi phế thải và tin rằng nó sẽ giúp anh vô địch. Trong khi Charlie theo đuổi hy vọng leo lên vị trí dẫn đầu thì một điều bất ngờ khác cũng đến với anh. Đứa con trai lưu lạc bấy lâu đột nhiên xuất hiện và muốn biết nhiều hơn về bố mình…</p>', 'Full', 1, 'single', 'completed', 23, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Dakota Goyo","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Karl Yune","avatar":""},{"name":"Sophie Levy","avatar":""},{"name":"Tess Levy","avatar":""},{"name":"Olga Fonda","avatar":""},{"name":"John Gatins","avatar":""},{"name":"Gregory Sims","avatar":""},{"name":"Torey Adkins","avatar":""},{"name":"Phil LaMarr","avatar":""},{"name":"John Hawkinson","avatar":""},{"name":"David Alan Basche","avatar":""},{"name":"Julian Gant","avatar":""},{"name":"Ken","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324472);
