INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ruoi', 'Long Ruồi', 'Long Ruoi', 'https://phimimg.com/upload/vod/20231011-1/b171d766f9606e6b7815597dc4cabb7d.jpg', 'https://phimimg.com/upload/vod/20231011-1/6d1eaef75f46d2f4dbc720f4afb51ec1.jpg', '<p>Phim là câu chuyện về Tèo (Thái Hòa), anh chàng đầu bếp quê mùa, quyết tâm lên thành phố đổi đời sau khi cô bạn gái bỏ anh đi theo tay Việt kiều giàu sụ. Nhờ ngoại hình giống đại ca xã hội đenLong Ruồi như hai giọt nước, Tèo ngay lập tức chễm chệ ngồi vào ghế đàn anh, sống cuộc sống xa hoa đúng như mong ước. Nhưng sự thật, Tèo chỉ là một con cờ trong cái bẫy đã được dàn xếp và anh sẽ bị cuốn vào hàng loạt tình huống dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 19, 2011, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Bùi Văn Hải","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Mi Minh","avatar":""},{"name":"Khương Ngọc","avatar":""},{"name":"Phi Thanh Vân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324472);
