INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-du', 'Mộng Du', 'Sleepwalker', 'null', 'https://phimimg.com/upload/vod/20231010-1/28d60347a821c469197e4c9a6adf9c7b.jpg', '<p>Ziyi đã bị ám ảnh bởi giấc mơ tương tự trong nhiều năm: Trong giấc mơ, cô đứng một mình trên vùng đất hoang và biết rằng có thứ gì đó được chôn giấu bên dưới. Người duy nhất có thể an ủi cô là người bạn thiết kế Eric của cô, người mà cô sẽ tiết lộ những giấc mơ kỳ lạ của mình. Cô được trung sĩ cảnh sát Madam Ou tiếp cận để hỗ trợ điều tra người chồng cũ mất tích. Trong khi đó, cảnh sát cũng đang truy tìm đứa cháu trai bị bắt cóc của cô, người vẫn chưa rõ tung tích mặc dù mẹ cậu là Becky đã trả tiền chuộc. Một ngày nọ, Ziyi tỉnh dậy và phát hiện vết bùn ở đầu giường, làm dấy lên nghi ngờ rằng cô có thể đã giết chồng cũ trong giấc ngủ! Tử Di dẫn Âu phu nhân đến hiện trường trong giấc mơ của cô, nơi sự thật kinh hoàng đang chờ đợi họ...</p>', 'Full', 1, 'single', 'completed', 18, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Angelica Lee","avatar":""},{"name":"Huo Si-Yan","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Li Zonghan","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Marc Ma","avatar":""},{"name":"Elva Ni Chen-Xi","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324472);
