INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-tham-b', 'Trinh Thám B+', 'The Detective 2', 'https://phimimg.com/upload/vod/20231010-1/87b81d86786557fd7f68d0de9505c926.jpg', 'https://phimimg.com/upload/vod/20231010-1/04fc2125bcbba48bd4e229a3382c656d.jpg', '<p>Thám tử tư vụng về Chan Tam được bạn cảnh sát Fung Chak tuyển dụng để giúp điều tra một vụ án giết người hàng loạt. Các nạn nhân, một người đàn ông trung niên bị giết tại nhà, một phụ nữ chết được tìm thấy trong bãi rác và một cô gái tuổi teen bị giết trong công viên, đều bị giết một cách man rợ, nhưng họ dường như không có quan hệ họ hàng với nhau. Không còn manh mối nào để theo dõi, Tâm quyết định đi vào ngõ cụt.</p>', 'Full', 1, 'single', 'completed', 17, 2011, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Gong Beibi","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Xu Zhengxi","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Ciwi Lam","avatar":""},{"name":"Renee Lee Wan","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"You-Nam Wong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324472);
