INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-tam-ma-phap', 'Khai Tâm Ma Pháp', 'Magic To Win', 'https://phimimg.com/upload/vod/20231010-1/4651e9361dc1a8cfd5f75aaec2d2d108.jpg', 'https://phimimg.com/upload/vod/20231010-1/dbcd66ede46749015b4ef685ece9cf60.jpg', '<p>Không ai biết rằng Giáo sư Hong Sum Kwai thực chất là Thủy pháp sư, một trong năm pháp sư nguyên tố. Một ngày nọ, Hong vô tình đánh mất sức mạnh phép thuật của mình và sức mạnh này được chuyển giao cho học trò của anh là Cheng Meisi. Cô gái vui vẻ sử dụng những khả năng siêu phàm mà cô có được nhờ may mắn trong cuộc sống, ở trường và trên sân bóng chuyền, nhưng những sức mạnh đó cũng khiến cô gặp rắc rối khi một cuộc chiến ma thuật nổ ra xung quanh cô... Pháp sư lửa Bi Yewu đang tuyệt vọng để biến quay ngược thời gian để thay đổi một bi kịch trong quá khứ, nhưng để làm được điều đó anh cần phải tập hợp sức mạnh của cả năm pháp sư nguyên tố. Pháp sư gỗ Gu Xinyue thấy trước thảm họa nếu thời gian bị biến dạng, vì vậy ông cảnh báo các pháp sư khác - bao gồm Pháp sư Trái đất Ling Feng và Pháp sư kim loại Charlie - hợp lực và ngăn chặn điều đó xảy ra...</p>', 'Full', 1, 'single', 'completed', 16, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Karena Ng","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Wu Zun","avatar":""},{"name":"Yan Ni","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Renata Tan","avatar":""},{"name":"Yip Sai-Wing","avatar":""},{"name":"Loletta Lee","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324472);
