INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-benh-aids', 'Mối Tình Bệnh AIDS', 'Love For Life', 'https://phimimg.com/upload/vod/20231010-1/7cef1735d0ad6588476d21761ed8ac3a.jpg', 'https://phimimg.com/upload/vod/20231010-1/730523472768fc72be33bfe1bc0eb6a5.jpg', '<p>Lấy bối cảnh tại một ngôi làng nhỏ của Trung Quốc, nơi virus HIV đang lây lan nhanh chóng do buôn bán máu trái phép, Mo shu wai zhuan xoay quanh De Yi và Qinqin đều bị gia đình ghẻ lạnh vì căn bệnh của họ và bất ngờ tìm thấy tình yêu với nhau. những bất hạnh.</p>', 'Full', 1, 'single', 'completed', 12, 2011, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ziyi","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Jiang Wenli","avatar":""},{"name":"Cunxin Pu","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Tao Zeru","avatar":""},{"name":"Sun Hai Ying","avatar":""},{"name":"Li Danyang","avatar":""},{"name":"Cai Guoqing","avatar":""},{"name":"Li Jianhua","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
