INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-99', 'Thiên Sứ 99', '99th Angel', 'https://phimimg.com/upload/vod/20231007-1/a8f88d63570d1c77f983e8d9b192465f.jpg', 'https://phimimg.com/upload/vod/20231007-1/d791df8422a6c3ec2cf3c7b466fc038c.jpg', '<p>Thiên Sứ 99 là câu chuyện về chàng thiên sứ Thiên Minh tình cờ bắn trúng
 mũi tên vào một cô gái tên Pha Lê dưới hạ giới nên buộc phải xuống trần
 để gỡ mũi tên ra. Tiếp xúc với cô gái, Thiên Minh lại nảy sinh tình cảm
 với cô. Không ngờ Pha Lê cũng đang bị con trai Diêm vương để ý nhằm hút
 hồn. Một khi rút mũi tên ra thì hồn cô gái sẽ thuộc về con trai Diêm 
vương. Thiên sứ sẽ phải tìm cách để bảo vệ nàng Pha Lê… Hoàng là con 
Diêm vương bị đẩy lên trần gian để thu hồi 99 hồn ma, và hồn ma của bà 
nội Pha Lê là hồn ma thứ 99. Để chinh phục được bà nội, Hoàng phải giả 
vờ yêu Pha Lê nhưng thực ra sau này anh và Thương lại âm thầm yêu nhau.</p>', 'Full', 1, 'single', 'completed', 34, 2011, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Huỳnh Anh","avatar":""},{"name":"Diễm My","avatar":""},{"name":"Ngô Kiến Huy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324472);
