INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thoa-hiep', 'Không Thỏa Hiệp', 'Blitz', 'https://phimimg.com/upload/vod/20230926-1/c5d639f202d6562611f853be30a10e45.jpg', 'https://phimimg.com/upload/vod/20230926-1/bf83b372ccc1be36dd6c7165f383c0c2.jpg', '<p>Điều gì xảy ra khi cảnh sát, những người bảo vệ an toàn xã hội lại trở thành mục tiêu của một tên giết người hàng loạt? Để chống lại một kẻ thù xảo quyệt ngoan cố như thế, một thanh tra cảnh sát với tiền sử bạo lực đã vào cuộc. Một cuộc chiến với cái ác vượt khỏi biên giới của công lý. Statham sẽ vào vai một viên cảnh sát cứng rắn, không chịu thỏa hiệp được phân công truy tìm tên sát nhân.</p>', 'Full', 1, 'single', 'completed', 19, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Zawe Ashton","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Ron Donachie","avatar":""},{"name":"Joe Dempsie","avatar":""},{"name":"Elly Fairman","avatar":""},{"name":"Ned Dennehy","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324472);
