INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-dam-me', 'Khách Sạn Đam Mê', 'Hotel Desire', 'https://phimimg.com/upload/vod/20230925-1/c6695c3628f09d536acc8ed530bfdb9f.jpg', 'https://phimimg.com/upload/vod/20230925-1/626a18840468750bac0d60bebdd4f02d.jpg', '<p>Phim là câu chuyện về một cô hầu phòng sống ở Berlin, người phải chịu đựng những cơn trầm uất tình dục. Cuộc sống của cô thay đổi khi một lần vô tình, cô đi lạc vào phòng khách sạn nơi một họa sỹ mù đang ngụ lại.</p>', 'Full', 1, 'single', 'completed', 22, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Saralisa Volm","avatar":""},{"name":"Clemens Schick","avatar":""},{"name":"Jan-Gregor Kremp","avatar":""},{"name":"Herbert Knaup","avatar":""},{"name":"Frederick Lau","avatar":""},{"name":"Palina Rojinski","avatar":""},{"name":"Trystan Pütter","avatar":""},{"name":"Hans-Uwe Bauer","avatar":""},{"name":"Liroy Gehrke","avatar":""},{"name":"Petar Knezevic","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
