INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-quan-hoan-hao', 'Giác Quan Hoàn Hảo', 'Perfect Sense', 'https://phimimg.com/upload/vod/20230918-1/8b85632bd97286f8d207808331bde4fa.jpg', 'https://phimimg.com/upload/vod/20230918-1/e57e20b0c9cf0287e6fb57bbd691a42b.jpg', '<p>Tại Glasgow, Scotland, trong khi một đại dịch bí ẩn bắt đầu lan rộng khắp thế giới, Susan, một nhà dịch tễ học tài giỏi, phải lòng Michael, một đầu bếp khéo léo.</p>', 'Full', 1, 'single', 'completed', 25, 2011, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Stephen Dillane","avatar":""},{"name":"Denis Lawson","avatar":""},{"name":"Anamaria Marinca","avatar":""},{"name":"Alastair Mackenzie","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Lauren Tempany","avatar":""},{"name":"Shabana Akhtar Bakhsh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324472);
