INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-tho-may', 'Sát Thủ Thợ Máy', 'The Mechanic', 'null', 'https://phimimg.com/upload/vod/20230909-1/6d44bd18d7001645cab31a699274c8dd.jpg', '<p>Statham vào vai Arthur Bishop, một sát thủ chuyên nghiệp. Anh được giao nhiệm vụ giết chết Harry (Donald Sutherland) - người bị gán tội phản bội tổ chức. Harry cũng chính là bạn của Arhur. Vì nhiệm vụ, Arthur đã giết chết Harry. Sau khi Harry chết, Arthur tình cờ gặp Steve McKenna (Ben Foster) - con trai của Harry. Arthur đã đào tạo Steve trở thành một sát thủ chuyên nghiệp và là đồng sự của mình. Trong một hợp đồng giết người, Arthur tình cờ phát hiện mình đã bị Dean (Tony Goldwyn) - người đứng đầu tổ chức lừa giết Harry. Với sự trợ giúp của Steve, cả hai đã giết chết tên Dean. Tuy nhiên, đó cũng là lúc Steve nhận ra Arthur chính là thủ phạm đã giết chết cha mình năm xưa.</p>', 'Full', 1, 'single', 'completed', 20, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Foster","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Donald Sutherland","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324472);
