INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-tho-may', 'Sát Thủ Thợ Máy', 'The Mechanic', 'sát thủ thợ máy the mechanic ben foster jason statham donald sutherland ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-noi-day-cua-hanh-tinh-khi', 'Sự Nổi Dậy Của Hành Tinh Khỉ', 'Rise of the Planet of the Apes', 'https://phimimg.com/upload/vod/20230912-1/52d9993949488c4b6edefa70facb48a3.jpg', 'https://phimimg.com/upload/vod/20230912-1/9f9c05acb5ff2576fc44b7ef04599265.jpg', '<p><span style="font-family: ">Will Rodman (James Franco) là một nhà khoa học tại công ty sinh học Gen-Sys, công ty này đang cố gắng phát triển một phương thuốc cho bệnh Alzheimer và đang thử nghiệm một loại thuốc theo liệu pháp gen lên những con tinh tinh. Loại thuốc này, là một loại virus được sửa đổi, giúp biến đổi những con tinh tinh, khiến chúng có khả năng thông minh của loài người. Một con tinh tinh cái đã cho rằng con của nó (mà phòng thí nghiệm vẫn chưa biết đến) bị đe dọa nên đã nổi giận và bị bắn chết bởi các nhân viên an ninh. Ông chủ của Will là Steven Jacobs (David Oyelowo) sau đó đã ra lệnh cho người giữ con tinh tinh này là Robert Franklin (Tyler Labine) phải kết liễu bằng thuốc những con tinh tinh còn lại. Franklin không thể khiến mình giết chết con tinh tinh con khi phát hiện ra sự tồn tại của nó và thay vào đó đã trao nó cho Will đem về nhà nuôi.</span></p>', 'Full', 1, 'single', 'completed', 34, 2011, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Freida Pinto","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Jamie Harris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43