INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-trong-mong-2012', 'Người Tình Trong Mộng', 'Men in Hope', 'người tình trong mộng men in hope bolek polívka jiří macháček petra hřebíčková simona stašová vica kerekes lukáš langmajer hynek čermák filip antonio michal novotný ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-than-tuong', 'Thử Thách Thần Tượng', 'Running Man', 'https://phimimg.com/upload/vod/20241017-1/65a22ab2e96e79bfedf8ae96d955f72a.jpg', 'https://phimimg.com/upload/vod/20241017-1/8ce53643bb316f8fb8dc3dddd955f2ce.jpg', '<p>Thử Thách Thần Tượng - RUNNING MAN là một show truyền hình hài hước thực tế của Hàn Quốc, ra mắt từ năm 2010 nhưng cho đến nay vẫn là một trong những chương trình giải trí được yêu thích nhất tại xứ sở kim chi. Với RUNNING MAN, đảm bảo các bạn sẽ phải &quot;cười lăn cười bò&quot; vì sự hài hước của các thành viên cũng như những nhiệm vụ oái ăm mà họ phải chịu đựng trong suốt chương trình. Ngoài 8 thành viên chính của RUNNING MAN gồm: Yoo Jae Suk, Ji Suk Jin, Kim Jong Kook, Lee Kwang Soo, Haha, Song Ji Hyo, Yang Se Chan và Jeon So Min, khán giả sẽ có dịp gặp gỡ những ngôi sao giải trí hàng đầu khác của Hàn Quốc, thậm chí là những ngôi sao Quốc tế tham gia RUNNING MAN trong vai trò khách mời đặc biệt.</p>', 'Tập 811', 790, 'tvshows', 'ongoing', 125, 2010, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae Suk","avatar":""},{"name":"Jeon So Min","avatar":""},{"name":"Kim Jong Kook","avatar":""},{"name":"HaHa","avatar":""},{"name":"Song Ji Hyo","avatar":""},{"name":"Yang Se Chan","avatar":""},{"name":"Ji Suk Jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["런닝맨"]', 1784690324472);
