INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-cao-tinh-yeu', 'Thông Cáo Tình Yêu', 'Love In Disguise', 'https://phimimg.com/uploads/movies/20260713/thong-cao-tinh-yeu-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/thong-cao-tinh-yeu-poster.webp', '<p>“Love in Disguise” xoay quanh chủ đề tình yêu, tình bạn và niềm đam mê âm nhạc của các bạn trẻ. Một lần tình cờ, xe của Đỗ Minh Hàn va phải Tống Hiểu Thanh (Lưu Diệc Phi đóng) và phải lòng cô. Chính vì vậy, anh đã giả dạng thành một sinh viên âm nhạc để có cơ hội tiếp cận với Hiểu Thanh. Từ đây, nhiều câu chuyện hấp dẫn diễn ra.</p>', 'Full', 1, 'single', 'completed', 47, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Leehom Wang","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Hank Chen Han-Dian","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Zhang You","avatar":""},{"name":"Zhang Zhihong","avatar":""},{"name":"Gary Mak Wing-Lun","avatar":""},{"name":"Khalil Fong","avatar":""},{"name":"Yike Zeng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Lian ai tong gao","Love In Disguise","戀愛通告"]', 1784690324472);
