INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuong-trang-mua-dong', 'Xương Trắng Mùa Đông', 'Winter''s Bone', 'https://phimimg.com/uploads/movies/20260710/xuong-trang-mua-dong-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/xuong-trang-mua-dong-poster.webp', '<p>Vắng mặt cha và cùng với người mẹ ốm yếu và đau khổ, cô bé Ree Dolly 17 tuổi sống chung với gia đình mình tại một vùng ngoại ô nghèo nàn và dơ bẩn. Bị mắc kẹt lại nơi này tuy nhiên khi được nghe cảnh sát trưởng địa phương nói rằng cha cô đã ký quỹ ngôi nhà của họ thành tiền bảo lãnh và nếu ông ta không trả hết nợ trong vòng 1 tuần, họ sẽ mất tất cả. Cô bé biết rằng cha mình có liên quan đến việc buôn bán thuốc trong khu vực và sản xuất những thành phẩm hóa học nhưng bất cứ nơi nào mà cô tìm đến, cô đều nhận được một thông điệp: tránh xa chuyện này và đừng nhúng mũi vào chuyện người khác. Cô bé không chịu nghe, thậm chí sau khi người chú, Teardrop, bảo rằng cha cô có thể đã bị giết. Ree vẫn tiếp tục, đặt sự ...</p>', 'Full', 1, 'single', 'completed', 59, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Kevin Breznahan","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Sheryl Lee","avatar":""},{"name":"Shelley Waggener","avatar":""},{"name":"Isaiah Stone","avatar":""},{"name":"Lauren Sweetser","avatar":""},{"name":"Ashlee Thompson","avatar":""},{"name":"Valerie Richards","avatar":""},{"name":"Cinnamon Schultz","avatar":""},{"name":"Casey MacLaren","avatar":""},{"name":"Tate Taylor","avatar":""},{"name":"Ronnie Hall","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Winters Knochen","Lazos de sangre","Winter''s Bone"]', 1784690324472);
