INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-bich-huyet-tam-dan', 'Bao Thanh Thiên: Bích Huyết Tâm Đan', 'Justice Bao: Arbiter Of Loyalty Unto Death', 'https://phimimg.com/upload/vod/20260612-1/0ca5678b6c8f50cb44b32f3f3cd34592.jpg', 'https://phimimg.com/upload/vod/20260612-1/6385ca6cf86d31424d71f6a3bfeeac07.jpg', '<p>Bao Công vì trừ gian diệt ác mà bị người ám hại, bị lôi kéo sâu cuộc đấu tranh trong triều đình. Triển Chiêu và Công Tôn Sách tính mạng khó giữ. Bích Huyết Đan Tâm sẽ tiếp nối phiên bản năm 1993, là bộ đầu tiên sau đó có kịch bản hoàn toàn mới, mang theo phong cách vốn có của phim Bao Thanh Thiên, gia tăng thêm hiệu ứng 3D, để khán giả thấy được rõ hơn hình ảnh một giang sơn Đại Tống 1000 năm trước.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 35, 2010, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Kim Siêu Quần","avatar":""},{"name":"Phạm Hồng Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["包青天之碧血丹心","Justice Bao Arbiter of Loyalty unto Death"]', 1784690324472);
