INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-7', 'Chuyện Văn Phòng (Phần 7)', 'The Office (Season 7)', 'https://phimimg.com/upload/vod/20260604-1/1d50f0ff80628a7a57e034e5c0cf5182.jpg', 'https://phimimg.com/upload/vod/20260604-1/02ed5909126bd28c4039439317209449.jpg', '<p>Trong Phần 7, Dwight hiện là chủ sở hữu của tòa nhà, Andy đang tán tỉnh Erin, Jim và Pam đấu tranh với việc trở thành cha mẹ mới và những người bạn gái trong quá khứ ám ảnh Michael.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 25, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324472);
