INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ten-cuop-nguoi-my-frank-va-jesse-james', 'Những Tên Cướp Người Mỹ: Frank Và Jesse James', 'American Bandits: Frank And Jesse James', 'https://phimimg.com/upload/vod/20260606-1/a17a97a5b6b47b00b682f757e576bb7a.jpg', 'https://phimimg.com/upload/vod/20260606-1/748bf61c96b139cc54646bc27747d1b4.jpg', '<p>Sau khi Jesse James bị trúng đạn vào ngực, Frank James quyết định giải tán băng đảng và lên kế hoạch hội quân sau bốn ngày. Trong bối cảnh bị Cảnh sát trưởng Hoa Kỳ Kane ráo riết truy đuổi, cùng với sự phản bội âm thầm diễn ra ngay trong nội bộ toán cướp, tất cả đã dẫn tới một cuộc đấu súng rực lửa và đầy nghẹt thở tại thị trấn hoang tàn mang tên &#39;Gila Wells&#39;.</p>', 'Full', 1, 'single', 'completed', 46, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Stults","avatar":""},{"name":"Peter Fonda","avatar":""},{"name":"Tim Abell","avatar":""},{"name":"Jeffrey Combs","avatar":""},{"name":"Michael Gaglio","avatar":""},{"name":"Anthony Tyler Quinn","avatar":""},{"name":"Siri Baruc","avatar":""},{"name":"Ian Patrick Williams","avatar":""},{"name":"Ted Monte","avatar":""},{"name":"Franc Ross","avatar":""},{"name":"Patrick Gorman","avatar":""},{"name":"Lauren Eckstrom","avatar":""},{"name":"Christopher Weir","avatar":""},{"name":"Peter Sherayko","avatar":""},{"name":"Jake Thornton","avatar":""},{"name":"Ron Harper","avatar":""},{"name":"Randy Mulkey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Американские бандиты: 