INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bao-thu', 'Cô Gái Báo Thù', 'I Spit on Your Grave', 'https://phimimg.com/upload/vod/20260602-1/eb4cbb51fbf99db14aa9e61ca9c62b5e.jpg', 'https://phimimg.com/upload/vod/20260602-1/06227be883c0490cd02b8c7ef499269b.jpg', '<p>Jennifer là một nhà văn trẻ tài năng. Cô quyết định dành 1 kỳ nghỉ ngắn tại một căn nhà trong rừng gỗ để chuẩn bị cho cuốn sách tiếp theo của mình. Nhưng cô không biết rằng, nguy hiểm đang rình rập cô. Ngay đêm đầu tiên tại căn nhà gỗ, cô đã bị một nhóm côn đồ tấn công. May mắn tưởng chừng như đã mỉm cười với cô khi cô vùng thoát được bàn tay bọn đốn mạt và gặp cảnh sát trưởng của thị trấn. Nhưng trớ trêu thay, cảnh sát trưởng lại là kẻ cầm đầu lũ du côn. Và điều gì đến cũng đến, cô lại bị bắt trở lại. Bằng sự mạnh mẽ từ nội lực, Jennifer nhảy xuống sông và trốn thoát. Và cuộc báo thù bắt đầu...</p>', 'Full', 1, 'single', 'completed', 25, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Butler","avatar":""},{"name":"Jeff Branson","avatar":""},{"name":"Tracey Walter","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Chad Lindberg","avatar":""},{"name":"Rodney Eastman","avatar":""},{"name":"Daniel Franzese","avatar":""},{"name":"Mollie Milligan","avatar":""},{"name":"Saxon Sharbino","avatar":""},{"name":"Amber Dawn Landrum","avatar":""},{"name":"Michelle Tonjes","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Dulce Venganza","Night of the Woman","Day of the Woman","Oeil pour Oeil","Escupiré sobre tu tumba","Bez litości","Doce Vingança","Məzarına Tüpürəcəm","Mezarına Tüküreceği