INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-ca-chien-thang-phan-1', 'Bài Ca Chiến Thắng (Phần 1)', 'Victorious (Season 1)', 'https://phimimg.com/upload/vod/20250207-1/7c472db6ccc3849ed3d45a332041449e.jpg', 'https://phimimg.com/upload/vod/20260518-1/cb32cc2642211542c751248250f4fdb0.jpg', '<p>Sam Puckett thì ồn ào, độc lập, và cứng cỏi như thép, trong khi Cat Valentine lại ngọt ngào như kẹo và cực kỳ mơ màng. Nhưng điều đó không ngăn cặp đôi không tưởng này trở thành bạn thân và bạn cùng phòng! Cùng nhau, họ là một đôi bạn mạnh mẽ với niềm đam mê dành cho niềm vui và phiêu lưu – chỉ tiếc là nó không hề rẻ. Bởi vì burger tại nhà hàng robot yêu thích của họ, Bots, không mọc trên cây. Một dịch vụ trông trẻ tại nhà nhanh chóng trở thành giải pháp cho vấn đề túi rỗng của họ, nhưng cũng là lý do cho vô số cuộc phiêu lưu hài hước khác!</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 41, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Victoria Justice","avatar":""},{"name":"Leon G. Thomas III","avatar":""},{"name":"Matt Bennett","avatar":""},{"name":"Elizabeth Gillies","avatar":""},{"name":"Ariana Grande","avatar":""},{"name":"Avan Jogia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["胜利之歌","빅토리어스","VICTORiOUS","Victorious"]', 1784690324473);
