INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dong-bat-tan', 'Cánh Đồng Bất Tận', 'Floating Lives', 'https://phimimg.com/upload/vod/20260513-1/5a65a8263244e77888355d58d3ad4ee7.jpg', 'https://phimimg.com/upload/vod/20260513-1/a676c06b9d30cacc6788f6cba8e1f71e.jpg', '<p>Lấy bối cảnh ở đồng bằng sông Cửu Long của Việt Nam, bộ phim kể về câu chuyện của ông Võ và những người con của ông. Vô cùng tức giận vì sự không chung thủy của vợ, anh đã đốt nhà và tất cả những kỷ niệm của anh trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 22, 2010, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Dustin Nguyễn","avatar":""},{"name":"Do Thi Hai Yen","avatar":""},{"name":"Tăng Thanh Hà","avatar":""},{"name":"Ninh Dương Lan Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Floating Lives","Au fil de l''eau","Cánh Đồng Bất Tận"]', 1784690324473);
