INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roi-vao-bay', 'Rơi Vào Bẫy', 'Clueless', 'https://phimimg.com/upload/vod/20260513-1/09faac4bd2503d384bef8ece92347301.jpg', 'https://phimimg.com/upload/vod/20260513-1/bedbac24d68686885549e97819f6b514.jpg', '<p>Một đạo diễn lừng danh quyết định tập hợp một nhóm các diễn viên hài để thực hiện dự án mới nhất của mình. Tuy nhiên, sự kết hợp đầy ngẫu hứng và hỗn loạn giữa những cá tính mạnh này đã dẫn đến vô vàn tình huống dở khóc dở cười. Phim phơi bày những sự thật trớ trêu và những trò lố bịch diễn ra phía sau ống kính, cho thấy việc tạo ra một tác phẩm nghệ thuật đôi khi còn hài hước hơn cả kịch bản trên phim.</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Suthep Pongam","avatar":""},{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Choosak Iamsuk","avatar":""},{"name":"Thanya Phowichit","avatar":""},{"name":"Bamrer Phongintakun","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Sornsutha Klunmalee","avatar":""},{"name":"Chitisan Chaisena","avatar":""},{"name":"Sudarat Butrprom","avatar":""},{"name":"Apaporn Nakornsawan","avatar":""},{"name":"Saisin Wongkhamlao","avatar":""},{"name":"Anuwat Tarapun","avatar":""},{"name":"Anake Inthajun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Phao Taek","โป๊ะแตก"]', 1784690324473);
