INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-rock-phan-5', '30 Rock (Phần 5)', '30 Rock (Season 5)', 'https://phimimg.com/upload/vod/20260501-1/69e64d9ca8b8234f53108cba084ef104.jpg', 'https://phimimg.com/upload/vod/20260501-1/66bcc8b65121c09d0abf933f978f6d01.jpg', '<p>Liz bắt đầu trưởng thành hơn, suy nghĩ nghiêm túc về tương lai thay vì chỉ sống theo công việc. Jack đối diện khủng hoảng quyền lực và vị trí trong tập đoàn, lần đầu cảm thấy không kiểm soát được mọi thứ. Series lúc này châm biếm mạnh mẽ hơn về doanh nghiệp và tham vọng.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Maulik Pancholy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 ROCK サーティー･ロック","サーティー･ロック","30 락","30락","30록","30 Rock"]', 1784690324473);
