INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhi-karate', 'Siêu Nhí Karate', 'The Karate Kid', 'https://phimimg.com/upload/vod/20250619-1/ac92034240ce0dec5df8f030d74ba620.jpg', 'https://phimimg.com/upload/vod/20250619-1/500b4450accaa8d0d870d76083cb64ff.jpg', '<p>Câu bé Dre Parker, 12 tuổi theo mẹ di chuyển từ thành phố Detroit, Mỹ sang Bắc Kinh, Trung Quốc. Tại đây, ngỡ ngàng với cuộc sống mới, khác biệt về ngôn ngữ, Dre vô tình gây sự đánh nhau với những học sinh giỏi kungfu Trung Quốc cùng trường. Để lấy lại danh dự và cũng để chinh phục cô bạn gái Mỹ Anh xinh đẹp, Dre quyết tâm &quot;đi học võ&quot;. Và vị sư phụ chính là ông thợ điện bí ẩn sống cùng khu phố.</p>', 'Full', 1, 'single', 'completed', 24, 2010, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jaden Smith","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Wenwen Han","avatar":""},{"name":"Zac Wang","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Wu Zhensu","avatar":""},{"name":"Zhiheng Wang","avatar":""},{"name":"Wang Ji","avatar":""},{"name":"Tess Liu","avatar":""},{"name":"Xu Ming","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Shijia Lü","avatar":""},{"name":"Luke Carberry","avatar":""},{"name":"Jared Minns","avatar":""},{"name":"Cameron Hillman","avatar":""},{"name":"Ghye Samuel Brown","avatar":""},{"name":"Liang Geliang","avatar":""},{"name":"Zhang Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","