INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhi-karate', 'Siêu Nhí Karate', 'The Karate Kid', 'siêu nhí karate the karate kid jaden smith jackie chan taraji p. henson wenwen han zac wang yu rongguang wu zhensu zhiheng wang wang ji tess liu xu ming zhao yi shijia lü luke carberry jared minns cameron hillman ghye samuel brown liang geliang zhang bo thành long gongfu meng best kid cau be karate карате кид карате пацан new karate kid малий каратист karate kid v - la leggenda continua kung fu kid เดอะ คาราเต้ คิด بچه کاراته‌باز karaté kid karatê kid 功夫梦 ベスト・キッド 베스트 키드 the kung fu dream the karate kid', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oc-dao-cua-oscar-oscars-oasis-2', 'Ốc Đảo Của Oscar (Oscar''s Oasis 2)', 'Oscar''s Oasis', 'https://phimimg.com/upload/vod/20260319-1/f49c52cce75ee815f4617461d874a5c8.jpg', 'https://phimimg.com/upload/vod/20260319-1/c6eb40418d59b87edd50af8200383e43.jpg', '<p>Giữa sa mạc nóng bỏng khô cằn, để tìm được nước và thức ăn, chú thằn lằn Oscar phải vượt qua những bụi xương rồng đầy gai, địa hình khắc nghiệt, đặc biệt phải đối phó với bộ ba láu cá Popy, Buck và Harchi. Bộ phim vô cùng hài hước và ngộ nghĩnh là món quà giải trí thú vị không chỉ dành riêng cho các khán giả nhí.</p>', 'Hoàn Tất (78/78)', 78, 'hoathinh', 'completed', 32, 2010, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Marie Facundo","avatar":""},{"name":"Sly Johnson","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Oscar''s Oasis 2"]', 1784690324473);
