INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-cot-phan-6', 'Hài Cốt (Phần 6)', 'Bones (Season 6)', 'https://phimimg.com/upload/vod/20260222-1/ae8ad7122a74333835a0e59de792f696.jpg', 'https://phimimg.com/upload/vod/20260222-1/287b833cf434e8a8368b082c17fe9cb7.jpg', '<p>Tiến sĩ Temperance Brennan và các đồng nghiệp tại Phòng thí nghiệm Pháp y Medico-Legal thuộc Viện Jeffersonian hỗ trợ Đặc vụ Seeley Booth điều tra các vụ án giết người, đặc biệt là khi các thi thể đã bị phân hủy, thiêu rụi hoặc hủy hoại nghiêm trọng đến mức các phương pháp nhận dạng thông thường không còn tác dụng.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 17, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emily Deschanel","avatar":""},{"name":"David Boreanaz","avatar":""},{"name":"John Boyd","avatar":""},{"name":"Michaela Conlin","avatar":""},{"name":"Tamara Taylor","avatar":""},{"name":"T.J. Thyne","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huesos","Bones: Sempre em Medicina","寻骨线索","עצמות","استخوان‌ها","Bones"]', 1784690324473);
