INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tay-du-ky-2010', 'Tân Tây Du Ký', 'Journey To The West', 'https://phimimg.com/upload/vod/20260221-1/a56a160667e98edf781fc72630a11539.jpg', 'https://phimimg.com/upload/vod/20260221-1/4c93382594d34d74e9eb43cf43ca52b6.jpg', '<p>&quot;Tân Tây Du Ký&quot; (Journey to the West) chuyển thể từ tác phẩm văn học kinh điển của Ngô Thừa Ân, kể về hành trình gian khổ của bốn thầy trò Đường Tăng (Trần Tư Hàn) từ Đại Đường xa xôi đến Tây Trúc để thỉnh kinh. Trên con đường đầy chông gai đó, họ phải đối mặt với vô số tai ương và quỉ yêu muốn hại Đường Tăng vì tin rằng thịt của sư phụ có thể mang lại sự trường sinh bất tử. Đồng hành cùng ông là Tôn Ngộ Không (Phí Chấn Tường), Trư Bát Giới (Tạ Ninh) và Sa Tăng (Mưu Phụng Bân). Tuy nhiên, thông điệp cao đẹp về lòng từ bi bác ái của đạo Phật luôn được thể hiện xuyên suốt tác phẩm, tạo nên những bài học ý nghĩa.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 27, 2010, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tư Hàn","avatar":""},{"name":"Tạ Ninh","avatar":""},{"name":"Mưu Phượng Bân","avatar":""},{"name":"Phí Chấn Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新西遊記","浙版西遊記","신 서유기","서유기 2010","서유기","西游记"]', 1784690324473);
