INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zebraman-2-cuoc-tan-cong-vao-thanh-pho-zebra', 'Zebraman 2: Cuộc Tấn Công Vào Thành Phố Zebra', 'Zebraman 2: Attack On Zebra City', 'https://phimimg.com/upload/vod/20260218-1/63eb0f9d7241163bbb501a04041e5051.jpg', 'https://phimimg.com/upload/vod/20260218-1/951778ba858ae4b93b2734c402fb36de.jpg', '<p>Lấy bối cảnh thế giới hậu tận thế vào năm 2025, nhân loại tìm thấy niềm hy vọng nơi người hùng Zebraman. Tuy nhiên, Zebra Queen (Nữ hoàng Ngựa vằn) đã đánh cắp sức mạnh của ông, khiến ông mất đi khả năng sống sót qua Zebra Time (Giờ Ngựa vằn). Nhưng ông quyết tâm phải giành lại sức mạnh của mình bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 21, 2010, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Show Aikawa","avatar":""},{"name":"Riisa Naka","avatar":""},{"name":"Guadalcanal Taka","avatar":""},{"name":"Tsuyoshi Abe","avatar":""},{"name":"Masahiro Inoue","avatar":""},{"name":"Mei Nagano","avatar":""},{"name":"Hideo Nakano","avatar":""},{"name":"Mame Yamada","avatar":""},{"name":"Naoki Tanaka","avatar":""},{"name":"Suzanne","avatar":""},{"name":"Nana Mizuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["斑马人2","斑马人2：斑马城的逆袭","Zeburāman - Zebura Shiti no Gyakushū","ゼブラーマン ゼブラシティの逆襲"]', 1784690324473);
