INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('zebraman-2-cuoc-tan-cong-vao-thanh-pho-zebra', 'Zebraman 2: Cuộc Tấn Công Vào Thành Phố Zebra', 'Zebraman 2: Attack On Zebra City', 'zebraman 2: cuộc tấn công vào thành phố zebra zebraman 2: attack on zebra city show aikawa riisa naka guadalcanal taka tsuyoshi abe masahiro inoue mei nagano hideo nakano mame yamada naoki tanaka suzanne nana mizuki 斑马人2 斑马人2：斑马城的逆袭 zeburāman - zebura shiti no gyakushū ゼブラーマン ゼブラシティの逆襲', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-tren-pho-elm', 'Ác Mộng Trên Phố Elm', 'A Nightmare on Elm Street', 'https://phimimg.com/upload/vod/20260206-1/a7fb731f2eeb35e9dffc970bb9a00546.jpg', 'https://phimimg.com/upload/vod/20260206-1/032a443629c8e35d0a8d74a4822e0cec.jpg', '<p>Ác mộng trên phố Elm là phim tâm lý, ly kỳ kinh dị Mỹ năm 2010 của đạo diễn Samuel Bayer.Bộ phim được làm lại từ bộ phim phiên bản gốc cùng tên sản xuất vào năm 1984. Một nhóm bạn trẻ tại thị trấn Springwood, tiểu bang Ohio bị một người đàn ông lạ đội nón phớt màu nâu, khuôn mặt đầy vết bỏng tên Freddy Krueger ám ảnh và giết họ trong những giấc mơ với chiếc găng tay có ngón sắc bén, điều ghê gớm là ai bị giết trong giấc mơ cũng sẽ chết thật ngoài đời. Cô nàng Nancy Holbrook và anh chàng Quentin Smith quyết định hợp tác với nhau tìm hiểu về người đàn ông độc ác ấy và tìm cách tiêu diệt ông ta...</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rooney Mara","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"Thomas Dekker","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Connie Britton","avatar":""},{"name":"Lia D. Mortensen","avatar":""},{"name":"Julianna Damm","avatar":""},{"name":"Christian Stolte","avatar":""},{"name":"Katie Schooping Knight","avatar":""},{"name":"Hailey Schooping Knight","avatar":""},{"name":"Leah Uteg","avatar":""},{"name":"Don Robert Cass","avatar":""},{"name":"Kurt Na","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b9