INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-song-phan-1', 'Xác Sống (Phần 1)', 'The Walking Dead (Season 1)', 'https://phimimg.com/upload/vod/20250917-1/10b70cf796fd5e79fe77b48ef9185c71.jpg', 'https://phimimg.com/upload/vod/20250917-1/a90c89d6357fa3f4f9dcac5a1bcf803b.jpg', '<p>Loạt phim xoay quanh nhân vật do nam diễn viên Andrew Lincoln thủ vai chính là phó cảnh sát trưởng Rick Grimes, người đã tỉnh dậy sau một khoảng thời gian hôn mê và nhận ra rằng thế giới đã bước vào thời kỳ hậu tận thế với sự xuất hiện tràn lan của thây ma ăn thịt. Anh lên đường tìm kiếm gia đình mình và gặp được nhiều người vẫn còn sống sót trên đường đi.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 22, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Cohan","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Melissa McBride","avatar":""},{"name":"Christian Serratos","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Ross Marquand","avatar":""},{"name":"Josh McDermitt","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Cooper Andrews","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Cailey Fleming","avatar":""},{"name":"Lauren Ridloff","avatar":""},{"name":"Eleanor Matsuura","avatar":""},{"name":"Nadia Hilker","avatar":""},{"name":"Cassady McC","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly"