INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xac-song-phan-1', 'Xác Sống (Phần 1)', 'The Walking Dead (Season 1)', 'xác sống (phần 1) the walking dead (season 1) lauren cohan norman reedus jeffrey dean morgan melissa mcbride christian serratos seth gilliam ross marquand josh mcdermitt khary payton cooper andrews callan mcauliffe cailey fleming lauren ridloff eleanor matsuura nadia hilker cassady mcc të vdekurit e gjallë живите мъртви les morcheurs 行尸走肉 živí mrtví elavad surnud οι ζωντανοί νεκροί 行屍 živi mrtvaci מתים מהלכים mordeye moteharrek ウォーキング・デッド 워킹 데드 워킹데드 gyvieji numirėliai gyvi numirėliai staigājušie miroņi живи мртовци żywe trupy the walking dead the walking dead: invazia zombi okružen mrtvima zivi mrtveci živí mŕtvi ล่าสยอง...กองทัพผีดิบ ฝ่าวงล้อม ซอมบี้ล้างโลก yürüyen ölüler ходячі мерці і мертві підуть twd yuradigan murdalar xac song', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-tinh-duoc', 'Tình Yêu Và Tình Dược', 'Love & Other Drugs', 'https://phimimg.com/upload/vod/20260108-1/e340fd0cbd92cf46cc9834c50a81d543.jpg', 'https://phimimg.com/upload/vod/20260108-1/847eab95b2012e4b19f88c8f1db440d9.jpg', '<p>Maggie là một linh hồn tự do đầy quyến rũ, người sẽ không để bất kỳ ai - hay bất cứ thứ gì - trói buộc cô ấy. Nhưng cô lại gặp gỡ mối quan hệ của mình ở Jamie, người có sức quyến rũ không ngừng và gần như không thể sai lầm phục vụ anh ta rất tốt với các phụ nữ và trong thế giới buôn bán dược phẩm khô khan. Mối quan hệ đang tiến triển của Maggie và Jamie khiến cả hai không khỏi ngạc nhiên, khi họ nhận ra mình đang bị ảnh hưởng bởi thứ ma túy tối thượng: tình yêu.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Gabriel Macht","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Jill Clayburgh","avatar":""},{"name":"George Segal","avatar":""},{"name":"Kate Jennings Grant","avatar":""},{"name":"Katheryn Winnick","avatar":""},{"name":"Kimberly Scott","avatar":""},{"name":"Peter Friedman","avatar":""},{"name":"Nikki DeLoach","avatar":""},{"name":"Natalie Gold","avatar":""},{"name":"Megan Ferguson","avatar":""},{"name":"Michael Benja","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love, et autres drogues","Love & autres drogues","O Amor é o Melhor Remédio","De Amor y Otras Adicciones","L''Amour et les autres drogues","Amor & Outras Drogas","Amor y Otras Drogas","러브 앤 드럭스","Amore & Altri Rimedi","Sevgi və Digər Narkotiklər","Aşk & Diğer Sarhoşluklar","Love & Other Drugs"]', 1784690324473);
