INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-va-tinh-yeu-phan-1', 'Âm Mưu Và Tình Yêu (Phần 1)', 'Stay Together, My Love (Season 1)', 'https://phimimg.com/upload/vod/20250301-1/d8112ac2ea2be614d83fba2a94e8a739.jpg', 'https://phimimg.com/upload/vod/20250301-1/94748a29cf59c5aa60874bd129dd8ef9.jpg', '<p>Hai chị em họ Gopi và Rashi cùng gả vào một gia đình danh giá và giàu có. Với tính cách hoàn toàn trái ngược cả hai tạo ra vô số rắc rối cho ngôi nhà mới của mình.</p>', 'Hoàn Tất (1103/1103)', 1103, 'series', 'completed', 18, 2010, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Sneha Jain","avatar":""},{"name":"Harsh Nagar","avatar":""},{"name":"Jay Pathak","avatar":""},{"name":"Aliraza Namdar","avatar":""},{"name":"Nadia Himani","avatar":""},{"name":"Prakash Waghela","avatar":""},{"name":"Anuradha Aalia Namdar","avatar":""},{"name":"Rupal Patel","avatar":""},{"name":"Akanksha Juneja","avatar":""},{"name":"Devoleena Bhattacharjee","avatar":""},{"name":"Mohammad Nazim Khilji","avatar":""},{"name":"Vandana Vithlani","avatar":""},{"name":"Manish Arora","avatar":""},{"name":"Swati Shah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gopi","Saath Nibhana Saathiya","Stay Together, My Love","Âm mưu và tình yêu","साथ निभाना साथिया"]', 1784690324473);
