INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-muu-va-tinh-yeu-phan-1', 'Âm Mưu Và Tình Yêu (Phần 1)', 'Stay Together, My Love (Season 1)', 'âm mưu và tình yêu (phần 1) stay together, my love (season 1) sneha jain harsh nagar jay pathak aliraza namdar nadia himani prakash waghela anuradha aalia namdar rupal patel akanksha juneja devoleena bhattacharjee mohammad nazim khilji vandana vithlani manish arora swati shah gopi saath nibhana saathiya stay together, my love âm mưu và tình yêu साथ निभाना साथिया', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-sat-thu', 'Chuyện Tình Sát Thủ', 'Knight And Day', 'https://phimimg.com/upload/vod/20251228-1/3f66a504cf1e5039c1a5a9860600ab59.jpg', 'https://phimimg.com/upload/vod/20251228-1/3a8583a64ca85c9d2da9c581fbaf2f69.jpg', '<p>Phim xoay quanh cuộc phiêu lưu mạo hiểm của người đẹp June Havens (Cameron Diaz) và siêu điệp viên Milner (Tom Cruise). Trong một lần hẹn hò với Milner – người bạn trai chưa hề biết mặt, June vô tình bị kéo vào chuyến hành trình nguy hiểm để bảo vệ một nguồn năng lượng quý. Đó là một cuộc đuổi bắt đầy căng thẳng đến mức nghẹt thở khi mà mọi thứ, kể cả con người không hề đơn giản như ta vẫn tưởng, thậm chí cả hai người họ. Họ buộc phải đối mặt với việc đi tìm những đồng minh khác lẫn việc bị phản bội bởi những người không thể ngờ được. Với những suy nghĩ ấy cứ lẩn vẫn trong tâm trí, họ lên đường, dấn thân vào trò vờn đuổi mà cơ hội sóng sót cực kì mong manh, tính mạng con người như ngàn cân treo sợi tóc xuyên suốt trận chiến giữa sự thật và niềm tin.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Marc Blucas","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Falk Hentschel","avatar":""},{"name":"Lennie Loftin","avatar":""},{"name":"Rich Manley","avatar":""},{"name":"Dale Dye","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Trevor Loomis","avatar":""},{"name":"Nilaja Sun","avatar":""},{"name":"Taylor Treadwell","avatar":""},{"name":"Chr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Innocenti bugie - Knight and Day","戀戰特務王","나잇 & 데이","Night & Day","Noche y dia Knight and Day","騎士出任務","Encontro Explosivo","Knight and Day"]', 1784690324473);
