INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-sat-thu', 'Chuyện Tình Sát Thủ', 'Knight And Day', 'chuyện tình sát thủ knight and day tom cruise cameron diaz peter sarsgaard viola davis jordi mollà paul dano maggie grace marc blucas celia weston falk hentschel lennie loftin rich manley dale dye gal gadot jack o''connell trevor loomis nilaja sun taylor treadwell chr innocenti bugie - knight and day 戀戰特務王 나잇 & 데이 night & day noche y dia knight and day 騎士出任務 encontro explosivo knight and day', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-im-lang-das-letzte-schweigen', 'Sự Im Lặng (Das letzte Schweigen)', 'The Silence', 'https://phimimg.com/upload/vod/20251220-1/5ee5f3131522191f2de25867c5be64ad.jpg', 'https://phimimg.com/upload/vod/20251220-1/7e312d7af9d42e8d04563f33d837daa6.jpg', '<p>Cô bé Sinikka 13 tuổi mất tích trong một đêm hè nóng nực. Chiếc xe đạp của cô được tìm thấy tại đúng địa điểm mà một bé gái khác từng bị sát hại 23 năm về trước. Thực tại đầy kịch tính này đã buộc những người từng liên quan đến vụ án năm xưa phải đối mặt với quá khứ của chính mình.</p>', 'Full', 1, 'single', 'completed', 20, 2010, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Ulrich Thomsen","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Katrin Sass","avatar":""},{"name":"Sebastian Blomberg","avatar":""},{"name":"Burghart Klaußner","avatar":""},{"name":"Oliver Stokowski","avatar":""},{"name":"Karoline Eichhorn","avatar":""},{"name":"Jule Böwe","avatar":""},{"name":"Roeland Wiesnekker","avatar":""},{"name":"Claudia Michelsen","avatar":""},{"name":"Lena Klenke","avatar":""},{"name":"Helene Luise Doppler","avatar":""},{"name":"Michael Dorn","avatar":""},{"name":"Hilmar Eichhorn","avatar":""},{"name":"Amon Robert W","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Das Schweigen","Silencio de hielo","Il était une fois un meurtre","Néma csönd","Cisza","O Silêncio","The Silence","Das letzte Schweigen"]', 1784690324473);
