INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-cuong-thi', 'Chiến Binh Cương Thi', 'Vampire Warriors', 'https://phimimg.com/upload/vod/20251214-1/f9af589b7f13901fde46081ed436b958.jpg', 'https://phimimg.com/upload/vod/20251214-1/f4baff4a0ec3d604cf18068a3a96d456.jpg', '<p>Trong thế giới loài người, tồn tại một nhóm Cương Thi lương thiện. Cô gái săn Cương Thi trẻ tuổi A Nha sống gần gũi với gia đình Cương Thi gồm A Tư, A Long và A Lực.&nbsp; Bỗng nhiên, Cương Thi hung hãn A Minh xuất hiện, tàn sát đồng loại. Sau khi A Minh giết hại người thân và bạn bè của A Nha và A Tư, cả hai bị dồn vào đường cùng.&nbsp; Để trả thù và tiêu diệt A Minh, A Nha quyết định hy sinh, chấp nhận bị A Tư cắn để biến thành Cương Thi mạnh mẽ. Cô tham gia vào trận chiến sinh tử cuối cùng với A Minh.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Trần Gia Hoàn","avatar":""},{"name":"Tưởng Lộ Hà","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Die Vampirjaeger","殭屍新戰士","僵尸新战士","Lesbian Vampire Warriors"]', 1784690324473);
