INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-thai-2010', 'Ác Thai', 'Womb Ghosts', 'https://phimimg.com/upload/vod/20251202-1/ca6623a5590479211196c0f9eadc99dd.jpg', 'https://phimimg.com/upload/vod/20251202-1/c765cc9691505604414b6f7ee78107cc.jpg', '<p>Sự sống sau khi chết của một thai nhi bên trong cơ thể phụ nữ tồn tại dưới dạng Quỷ Thai. Việc chấm dứt sự sống đó một cách phi tự nhiên sẽ biến đứa bé thành một loại linh hồn độc ác và hung dữ nhất.&nbsp; Một bệnh viện tâm thần bị ám bởi các linh hồn. Vụ sẩy thai bí ẩn của một nữ bệnh nhân trẻ và xinh đẹp khiến giới chức phải tiến hành điều tra. Chỉ có một câu trả lời duy nhất cho sự tồn tại của sinh vật phi thánh thiện này... đó chính là Quỷ Thai.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tú Na","avatar":""},{"name":"Lê Thụy Nghi","avatar":""},{"name":"Lâm Tuyết","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ngok toi","恶胎","惡胎"]', 1784690324473);
