INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-thanh-gioi-bi', 'Toàn Thành Giới Bị', 'City Under Siege', 'https://phimimg.com/upload/vod/20251129-1/709c67d77a1397096028f2b1a2d5bb16.jpg', 'https://phimimg.com/upload/vod/20251129-1/2874d4ad3ef220dd17d81b2fc1f6157b.jpg', '<p>Sunny là một nghệ sĩ xiếc ngây thơ, mơ ước được thừa hưởng tài năng ném dao của cha mình. Tuy nhiên, những đồng nghiệp thù địch liên tục bắt nạt anh, đẩy anh xuống vị trí một chú hề hèn mọn. Trong một chuyến lưu diễn đến Malaysia, Cheung và những nghệ sĩ xiếc khác phát hiện ra một hang động bị quân đội Nhật Bản chiếm đóng trong Thế chiến II. Thay vì tìm thấy kho báu, các nghệ sĩ - bao gồm cả Sunny - bị phun một loại hóa chất bí ẩn, biến họ thành những dị nhân siêu phàm...</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Quách Phú Thành","avatar":""},{"name":"Thư Kỳ","avatar":""},{"name":"Châu Dương Kiệt","avatar":""},{"name":"Trương Tĩnh Sơ","avatar":""},{"name":"Ngô Kinh","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chun sing gai bei","全城戒备","Assassin: City Under Siege","全城戒備"]', 1784690324473);
