INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-cuoi-hoan-hao', 'Đám Cưới Hoàn Hảo', 'Perfect Wedding', 'https://phimimg.com/upload/vod/20251129-1/917a6813e8eec2b63674c23868b182e0.jpg', 'https://phimimg.com/upload/vod/20251129-1/256c60b25a9e914577b14d92b3b5e783.jpg', '<p>Lạc Hân (Dương Thiên Hoa đóng), một nhà thiết kế đám cưới quyến rũ và xinh đẹp, có tiếng tăm trong ngành. Dưới bàn tay tài hoa của cô, vô số đám cưới độc đáo và lãng mạn đã ra đời.Cô chứng kiến không biết bao nhiêu cảnh tượng ấm áp, lãng mạn, nhưng đường tình duyên của chính cô lại đầy trắc trở, thậm chí từng gặp phải bi kịch chú rể bỏ trốn ngay trong ngày cưới. Những cú sốc liên tiếp khiến Lạc Hân không còn tin vào cái gọi là tình yêu đích thực.Tình cờ, cô gặp lại Phong (Lâm Phong đóng), người đàn ông cô từng có tình một đêm. Vì các vấn đề nợ nần, Phong buộc phải vào công ty của Lạc Hân để &quot;bán thân trả nợ&quot;.Hai người họ dần trở nên ăn ý, hợp tác vui vẻ và cống hiến những màn tổ chức đám cưới tuyệt vời, tình cảm dành cho nhau cũng ngày càng sâu đậm.Tuy nhiên, ngay khi họ chuẩn bị vượt qua rào cản tâm lý của nhau, đủ loại thử thách bắt đầu xuất hiện: Bạn trai cũ của Lạc Hân là Joe (Cát Dân Huy đóng) bất ngờ quay đầu lại, còn Phong cũng gặp một cô gái đáng yêu. Mối quan hệ của họ rồi sẽ đi đến đâu...</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Dương Thiên Hoa","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Cát Tử Thần","avatar":""},{"name":"Hứa Bích Nghi","avatar":""},{"name":"Hồ Tử San","avatar":""},{"name":"Bernice Liu","avatar":""},{"name":"Châu Hối Na","avatar":""},{"name":"Eric Kot","avatar":""},{"name":"Ô Tử Niên","avatar":""},{"name":"Mạch Linh Linh","avatar":""},{"name":"Ngô Gia Nam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["抱抱俏佳人"]', 1784690324473);
