INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-giac-toi-loi-2010', 'Cảm Giác Tội Lỗi', 'Marriage With A Liar', 'https://phimimg.com/upload/vod/20251126-1/9714bac18ec99b2e4cd2d359beec145f.jpg', 'https://phimimg.com/upload/vod/20251126-1/22a25f1ee09ff0bf7b0195a733ab3392.jpg', '<p>Kiki (Châu Tú Na), một cô gái văn phòng xinh đẹp rạng ngời, và bạn trai cô là Tse (La Trọng Khiêm), một cảnh sát, chỉ còn chưa đầy một tuần nữa là kết hôn.Một đêm nọ, Kiki tham dự buổi tiệc chia tay đời độc thân do hai người bạn thân là Shirley (Trang Tư Mẫn) và Meng (Phương Hạo Mân) dày công chuẩn bị. Trong cơn say mèm, Kiki tình cờ gặp Jack (Thẩm Chí Minh), một nhiếp ảnh gia đẹp trai, phong độ vừa trở về từ nước ngoài.Không biết do ảnh hưởng của rượu hay áp lực trước hôn nhân, Kiki và Jack đã phải lòng nhau từ cái nhìn đầu tiên và trong lúc hoang mang, họ đã qua đêm với nhau.Ngày hôm sau, tình cờ Kiki lại nhìn thấy Tse cùng hai người bạn thân là Keung (Hồng Thiên Minh) và Tak (Kim Cương) bước ra từ một hộp đêm. Không thể ngờ được người bạn trai vốn trung thực lại phản bội mình, Kiki đã lớn tiếng chất vấn Tse. Cặp đôi chỉ còn ba ngày nữa là cưới này cuối cùng đã tan rã trong sự không vui vẻ....</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tú Na","avatar":""},{"name":"La Trọng Khiêm","avatar":""},{"name":"Dương Yên","avatar":""},{"name":"Thẩm Chí Minh","avatar":""},{"name":"Trương Tư Mẫn","avatar":""},{"name":"Phương Hào Vận","avatar":""},{"name":"Hồng Thiên Minh","avatar":""},{"name":"Mạch Trường Thanh","avatar":""},{"name":"Trần Gia Bảo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fun chin see oi","Marriage Wa A Liar","婚前試愛"]', 1784690324473);
