INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh-3', 'Quái Thú Vô Hình 3', 'Predators', 'https://phimimg.com/upload/vod/20251116-1/971fff3e457917f4b3d817f8539ec833.jpg', 'https://phimimg.com/upload/vod/20251116-1/da3acbbb119f7c34798c7e6227139e81.jpg', '<p>Một trong những phim khoa học viễn tưởng rùng rợn được mong chờ nhất năm 2010. Nội dung phim xoay quanh việc một nhóm những sát thủ nguy hiểm nhất trên thế giới bị đưa tới một hành tinh xa lạ. Royce - một cựu lính đánh thuê, đang rơi giữa không trung và chỉ kịp bung dù khi gần chạm đất. Dần dần, Royce nhận ra mình không phải là người duy nhất “đổ bộ” xuống khu rừng bí ẩn này. Và tại đây, anh sớm nhận ra mình là con mồi của những sinh vật tiến hoá cấp cao.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Adrien Brody","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Oleg Taktarov","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Louis Ozawa","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Carey Jones","avatar":""},{"name":"Brian Steele","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Aaron Richardson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Predators","Depredadores","Predadores","プレデターズ","มหากาฬพรีเดเตอร์","Grobuonys 3","Les Prédateurs","Predator 3 - Predators","O Predador 3 - Predadores","הט