INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-gia-binh-doan', 'Cư Gia Binh Đoàn', 'Home Troopers', 'https://phimimg.com/upload/vod/20251023-1/022008b3e7a939ea5f56ca51f0a7fc6d.jpg', 'https://phimimg.com/upload/vod/20251023-1/25765d07a2916b7ac36913f63ea2c274.jpg', '<p>Từ khi làm dâu nhà họ Gia, Lê Gia Gia (do Uông Minh Thuyên đóng) luôn tận tâm chăm lo cho gia đình, để chồng mình là Gia Cát Hà (do Hạ Vũ đóng), tập trung sự nghiệp. Gia Gia nắm trong tay kho tàng kiến thức về các bí quyết săn sóc chồng con. Chính vì thế, bà được xem là trụ cột tinh thần của cả nhà, ai cũng nể trọng. Thời gian trôi, Gia Gia tưởng rằng mình sắp được an hưởng tuổi già khi chồng về hưu, các con đã trưởng thành. Nào ngờ, một biến cố lớn khiến mọi hy vọng của bà gần như sụp đổ. Con trai cả - Gia Cát Tịnh (do Trịnh Gia Dĩnh đóng) vốn hiếu thảo nhất, thành đạt nhất, là niềm tự hào của gia đình. Nay, anh lại không hỏi qua ý kiến của mẹ, lẳng lặng bỏ việc, hùn vốn với bạn là Kỳ Vĩnh Phát (do Tào Vĩnh Liêm đóng), mở công ty dịch vụ vệ sinh.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2010, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Liza Wong Ming-Chuen","avatar":""},{"name":"Ha Yue","avatar":""},{"name":"Bernice Liu","avatar":""},{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Christine Kuo Yun-Hui","avatar":""},{"name":"Raymond Cho Wing-Lim","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Angela Tong Ying-Ying","avatar":""},{"name":"Daniel Chau","avatar":""},{"name":"Vincent Wong Ho-Shun","avatar":""},{"name":"Claire Yiu","avatar":""},{"name":"Adrian Chau Chi-Man","avatar":""},{"name":"Vivian Tsang","avatar":""},{"name":"So Lai Ming","avatar":""},{"name":"Chan On-ying","avatar":""},{"name":"Ce","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["居家兵團"]', 1784690324473);
