INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-son-dai-dia-chan', 'Đường Sơn Đại Địa Chấn', 'Aftershock', 'https://phimimg.com/upload/vod/20251024-1/de35696dcb936e844d26c125a738d118.jpg', 'https://phimimg.com/upload/vod/20251024-1/29636624e9b2be7d1d5433a99dbb8a04.jpg', '<p>Bộ phim dựa trên cuốn tiểu thuyết Aftershock của một hoa kiều Canada. Bộ phim kể về cuộc đời của một cô bé sau trận động đất đã san phẳng thành phố Đường Sơn miền Bắc Trung Quốc vào ngày 28 tháng 7 năm 1976...</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Fan","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Wang Ziwen","avatar":""},{"name":"Chen Daoming","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Chen Jin","avatar":""},{"name":"Zhang Guoqiang","avatar":""},{"name":"Zhang Zifeng","avatar":""},{"name":"Zhang Jia-Jun","avatar":""},{"name":"Lü Zhong","avatar":""},{"name":"Yong Mei","avatar":""},{"name":"Lu Yi","avatar":""},{"name":"Yang Lixin","avatar":""},{"name":"Liu Lili","avatar":""},{"name":"Ma Qiuzi","avatar":""},{"name":"Yang Le","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Separados pelo Destino","Tremblement de terre à Tangshan","Tangshan dadizhen","Tang shan da di zhen","Μετά το σοκ","Aftershock","Aftershock 2010","とうざんだいじしん","Tangshan da dizhen","唐山大地震"]', 1784690324473);
