INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-da-cam', 'Màu Da Cam', 'Orange', 'https://phimimg.com/upload/vod/20251020-1/f0277984cb3c54bc5ffd3f0a6ec8cb03.jpg', 'https://phimimg.com/upload/vod/20251020-1/bc2f7c8aa7036c7af6e61c4b1fe5a3ed.jpg', '<p>Một chàng trai trẻ đem lòng yêu một cô gái, nhưng anh phải liên tục nói dối để khiến cô vui. Khi không thể tiếp tục che giấu nữa, anh nói với cô rằng mọi chuyện không thể kéo dài thêm và quyết định chia tay.</p>', 'Full', 1, 'single', 'completed', 20, 2010, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ram Charan","avatar":""},{"name":"Genelia D''Souza","avatar":""},{"name":"Prabhu","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Brahmanandam","avatar":""},{"name":"Manjula Ghattamaneni","avatar":""},{"name":"Sanjay Swaroop","avatar":""},{"name":"Pavitra Lokesh","avatar":""},{"name":"Srinivas Avasarala","avatar":""},{"name":"Vennela Kishore","avatar":""},{"name":"Praneeth","avatar":""},{"name":"Sanchita Shetty","avatar":""},{"name":"Kalpika Ganesh","avatar":""},{"name":"Sameer Hasan","avatar":""},{"name":"Siddhu Jonnalagadda","avatar":""},{"name":"Phanikanth Rampal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hai Ramcharan","Narıncı","Orange"]', 1784690324473);
