INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('36-cau-chuyen', '36 Câu Chuyện', 'Taipei Exchanges', 'https://phimimg.com/upload/vod/20251014-1/89e3c44d7f4edad1e4ef367cce7fd0dc.jpg', 'https://phimimg.com/upload/vod/20251014-1/136a0cdc379533fb7d7b554c0e7fdaec.jpg', '<p>Hai hàng cây xanh rậm rạp ôm lấy con phố yên tĩnh, bên đường, quán “Cà phê Đóa Nhi” bật sáng ánh đèn ấm áp. Chủ quán là hai chị em trẻ tuổi – Đóa Nhi và Tường Nhi. Vì đam mê cà phê và bánh ngọt, Đóa Nhi đã dùng tiền tiết kiệm từ công việc cùng với sự giúp đỡ của gia đình, để cùng em gái xây dựng nên một quán cà phê mang phong cách riêng. Trong tưởng tượng của cô, bản thân sẽ là linh hồn của quán – bạn bè thân thiết sẽ đến ủng hộ, rồi lại kéo thêm bạn bè khác đến. Tình cảm và nhân duyên của cô sẽ trở thành nguồn năng lượng cho quán phát triển. Quả thật, ngày khai trương, rất nhiều bạn bè đã đến chúc mừng, mang theo những món quà thú vị. Đóa Nhi vui mừng khôn xiết, thề rằng sẽ duy trì quán thật lâu dài. Thế nhưng, thực tế không như mơ — sau lễ khai trương, khách đến ngày càng thưa thớt, quán trở nên vắng lặng, còn kho hàng lại đầy ắp quà mừng. Sự “được lòng người” của Đóa Nhi bỗng chốc trở thành gánh nặng lưu kho. Trong một lần trò chuyện tình cờ, hai chị em nảy ra ý tưởng mở chương trình “trao đổi vật phẩm”. Trong quán, thứ duy nhất có thể mua bằng tiền là cà phê; còn nếu khách muốn những món đồ khác, họ phải dùng một vật có giá trị tương đương để đổi. Nhờ vậy, khách có thể đổi mô hình robot siêu nhân lấy một tấm ảnh cũ, hoặc đổi một chiếc bình nước suối lấy cuốn sách dạy nấu món Thái. Không còn bàn chuyện tiền bạc — chỉ còn sự đồng cảm về giá trị giữa người với người. Từ đó, “Cà phê Đóa Nhi” không còn là quán cà phê thông thường, mà trở thành nơi kết nối cảm xúc của thành phố, nơi những câu chuyện được trao đổi, sẻ chia và lắng nghe. Trong số những vị khách ghé thăm, có một phi công phụ mang đến 35 câu chuyện từ các thành phố khác nhau. Mỗi cuộc trao đổi khiến Đóa Nhi và Tường Nhi xem xét lại tiêu chuẩn giá trị của bản thân, và cuối cùng, họ quyết định ra đi tìm kiếm “câu chuyện thứ 36” — hành trình thực sự thuộc về chính mình.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Quế Luân Mỹ","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Mã Chấn Á","avatar":""},{"name":"Lâm Dung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["타이페이 카페 스토리","第36個故事"]', 1784690324473);
