INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('36-cau-chuyen', '36 Câu Chuyện', 'Taipei Exchanges', '36 câu chuyện taipei exchanges quế luân mỹ trương quân ninh mã chấn á lâm dung 타이페이 카페 스토리 第36個故事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-danh-thue', 'Biệt Đội Đánh Thuê', 'The Expendables', 'https://phimimg.com/upload/vod/20251012-1/9ae5b986bc8776d50d3571d9d86853d9.jpg', 'https://phimimg.com/upload/vod/20251012-1/b3bd76a1e0fb1449eaaefa6222076e7f.jpg', '<p>The Expendables (Biệt Đội Đánh Thuê) là bộ phim hành động có nội dung xoay quanh biệt đội đặc nhiệm The Expendables được thuê để xâm nhập vào một quốc gia Nam Mũ và lật đổ nhà độc tài tàn nhẫn đang trị vì... Khi nhiệm vụ bắt đầu, biệt đội đặc nhiệm chợt nhận ra rằng mọi việc không giống như khi họ xuất hiện. Sau đó, họ nhận ra rằng mình cũng bị gài bẫy và chính họ bị rơi vào một mớ những nguy hiểm của sự lừa dối và phản bội. Sau đó biệt đội đặc nhiệm bắt đầu hiểu ra rằng kẻ thù thực sự của họ là một tên cựu điệp viên CIA rất láu cá James Monroe và tay sai của ông ta là Paine. Biệt Đội Đánh Thuê (The Expendables) là bộ phim hành động hoành tráng nhất trong năm 2010 từ Hollywood. Bộ phim khơi gợi lại thời kỳ huy hoàng của những bộ phim hành động thập niên 80-90 thế kỷ trước và tôn vinh những màn đấu võ đỉnh cao, những cảnh chiến đấu thực thụ của những người hùng cơ bắp</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Jet Li","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Randy Couture","avatar":""},{"name":"Steve Austin","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Giselle Itié","avatar":""},{"name":"Charisma Carpenter","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Hank Amos","avatar":""},{"name":"Amin Joseph","avatar":""},{"name":"Grifon Aldren","avatar":""},{"name":"Antonio Rodrigo Nogueira","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Expendables - Stahlharte Söldner","Los mercenarios","The Expendables - A feláldozhatók","轰天猛将","I mercenari","The Expendables","轟天猛將","Неудержимые","The Expendables 1","Cəhənnəm Mələkləri","Los Mercenarios: 1","Os Mercenários"]', 1784690324473);
