INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-bat-dung-srpski-film', 'Tội Ác Bất Dung (Srpski film)', 'A Serbian Film', 'https://phimimg.com/upload/vod/20251010-1/c83442326ceb3218a7bc640870b7ed1c.jpg', 'https://phimimg.com/upload/vod/20251010-1/6140f44f6e04fcace57ff7a123401132.jpg', '<p>Ngôi sao phim khiêu dâm đã giải nghệ Milos đang sống cuộc đời gia đình bình thường, cố gắng kiếm sống qua ngày. Khi được trao cơ hội ngàn vàng để có thể đảm bảo tài chính cho gia đình suốt phần đời còn lại, Milos phải tham gia vào một bộ phim bí ẩn cuối cùng. Từ đó, anh bị cuốn vào cơn lốc của sự tàn bạo và hỗn loạn khôn tưởng.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Serbia', 0, '[{"name":"Srđan ''Žika'' Todorović","avatar":""},{"name":"Sergej Trifunović","avatar":""},{"name":"Jelena Gavrilović","avatar":""},{"name":"Slobodan Beštić","avatar":""},{"name":"Katarina Žutić","avatar":""},{"name":"Anđela Nenadović","avatar":""},{"name":"Ana Sakić","avatar":""},{"name":"Lidija Pletl","avatar":""},{"name":"Lena Bogdanović","avatar":""},{"name":"Luka Mijatović","avatar":""},{"name":"Nenad Heraković","avatar":""},{"name":"Čarni Đerić","avatar":""},{"name":"Miodrag Krčmarik","avatar":""},{"name":"Tanja Divnić","avatar":""},{"name":"Marina Savić","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Serbian Film","Сербский фильм","세르비안 필름","A Serbian Film - UC","Srpski film","Bir Sırp Filmi","Сръбски филм","A Serbian Film - Terror sem Limites","セルビアン・フィルム","Сербський філь