INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-khach-bi-an', 'Du Khách Bí Ẩn', 'The Tourist', 'https://phimimg.com/upload/vod/20251010-1/ddcb859ecf2dffd085cf76393b90cf86.jpg', 'https://phimimg.com/upload/vod/20251010-1/d501740bcbb8707d1ca3266fc86fc9e2.jpg', '<p>Một du khách người Mỹ tìm kiếm sự an ủi cho trái tim tan vỡ của mình, nhưng lại bị đốn tim sau khi tình cờ gặp một đặc vụ Interpol xinh đẹp.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Timothy Dalton","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Christian De Sica","avatar":""},{"name":"Alessio Boni","avatar":""},{"name":"Daniele Pecci","avatar":""},{"name":"Giovanni Guidelli","avatar":""},{"name":"Raoul Bova","avatar":""},{"name":"Bruno Wolkowitch","avatar":""},{"name":"Julien Baumgartner","avatar":""},{"name":"François Vincentelli","avatar":""},{"name":"Clément Sibony","avatar":""},{"name":"Jean-Claude","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ツーリスト：2010","السائح","The Tourist"]', 1784690324473);
