INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuat-thuy-phu-dung', 'Xuất Thủy Phù Dung', 'The Fantastic Water Babes', 'https://phimimg.com/upload/vod/20251009-1/ecae74bee74dd740091e01daeb61f99e.jpg', 'https://phimimg.com/upload/vod/20251009-1/52c690da1d9e54183e077d26f877b4be.jpg', '<p><span style="text-wrap-mode: wrap;">Gil (Gillian Chung) là một cô gái cố gắng tự kết liễu đời mình sau khi bị bạn trai bỏ rơi để theo một cô gái khác, Brenda (Chrissie Chow). Gil được thần nước cứu và tin rằng mình đã nhận được sức mạnh đặc biệt. Mặc dù cô ấy thậm chí không biết bơi nhưng cô ấy vẫn tham gia cuộc thi bơi lội Fantastic Water Babes, trong một nỗ lực báo thù để cạnh tranh với đối thủ lãng mạn và bạn bè của cô ấy, cũng như để giành lại bạn trai của mình. Để thành thạo bơi lội, cô bắt cóc nhà vô địch bơi lội Kwok Chi Yuan (Alex Fong Lik Sun) đến đảo Cheung Chau, để bắt anh dạy cô và bạn bè cô bơi.</span></p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Gillian Chung","avatar":""},{"name":"Alex Fong Lik-Sun","avatar":""},{"name":"Huang Shengyi","avatar":""},{"name":"Hyper BB","avatar":""},{"name":"Chu Fun","avatar":""},{"name":"Simon Lui Yu-Yeung","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Tian Liang","avatar":""},{"name":"Natalie Tong","avatar":""},{"name":"Janet Ma","avatar":""},{"name":"Chrissie Chau Sau-Na","avatar":""},{"name":"Calvin Sun","avatar":""},{"name":"Jacqueline Law Wai-Guen","avatar":""},{"name":"Liu Chui-Chun","avatar":""},{"name":"Sam Ho Choi-Chow","avatar":""},{"name":"Jeffrey Lau","avatar":""},{"name":"Au Wai-Lun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Fantastic Water Babes","Chut Sui Fu Yung","出水芙蓉"]', 1784690324473);
