INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-gai-goi-sinh-vien', 'Dịch Vụ Gái Gọi Sinh Viên', 'Student Services', 'https://phimimg.com/upload/vod/20251009-1/b1efe53d26312e8a13417d94cbb09bf6.jpg', 'https://phimimg.com/upload/vod/20251009-1/1a59c76fd7ca9787007deb099fb536b6.jpg', '<p><span style="text-wrap-mode: wrap;">Laura 19 tuổi bị căng thẳng trong năm đầu tiên ở trường đại học khi những lo lắng về tiền bạc khiến cô mất tập trung vào việc học và vì vậy, tuyệt vọng vì tiền, cô trả lời một quảng cáo trực tuyến về tình bạn thân thiết đã dẫn cô đến một con đường nguy hiểm.</span></p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Déborah François","avatar":""},{"name":"Mathieu Demy","avatar":""},{"name":"Alain Cauchi","avatar":""},{"name":"Benjamin Siksou","avatar":""},{"name":"Anna Sigalevitch","avatar":""},{"name":"Joseph Braconnier","avatar":""},{"name":"Marc Chapiteau","avatar":""},{"name":"Pascal Bongard","avatar":""},{"name":"Lou Bohringer","avatar":""},{"name":"Édith Le Merdy","avatar":""},{"name":"Fred Epaud","avatar":""},{"name":"Marthe Caufman","avatar":""},{"name":"Javier Cruz","avatar":""},{"name":"Jicey Carina","avatar":""},{"name":"Martine Fontaine","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Meus Caros Estudos","Student Services","Studentki","Studentin, 19, sucht...","我親愛的課程","Mes chères études"]', 1784690324473);
