INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-nguoi-la', 'Xin Chào Người Lạ', 'Hello Stranger', 'https://phimimg.com/upload/vod/20250420-1/08e4c572c26ecbe843bfb9e04ef4ed40.jpg', 'https://phimimg.com/upload/vod/20250420-1/43289d576611a4f32f2a940d92c57b42.jpg', '<p>Xin Chào Người Lạ Hello Stranger (2011) Bộ phim kể về cuộc hành trình của hai bạn trẻ tại đất nước xinh đẹp Hàn Quốc. Dù mỗi người đến Hàn Quốc với mục đích khác nhau nhưng khi ở đây, họ đã trở thành những người bạn thân thiết, cùng nhau trải nghiệm những điều thú vị và mới mẻ tại xứ sở Kim Chi. Họ cùng nhau tham quan những địa danh, thắng cảnh gắn liền với những bộ phim truyền hình nổi tiếng của Hàn Quốc. Và rồi, tình yêu bất ngờ đến với họ lúc nào không hay. Đó có thực sự là tình yêu? Hay đó chỉ là sự hiểu lầm của chính chàng trai trẻ trước nỗi cô đơn nơi đất khách quê người?</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Nuengthida Sophon","avatar":""},{"name":"Warattaya Nilkuha","avatar":""},{"name":"Nattapong Chatpong","avatar":""},{"name":"Pongsatorn Jongwilas","avatar":""},{"name":"Attharut Kongrasri","avatar":""},{"name":"Natkrita Rummanu","avatar":""},{"name":"Necha Khoovatanapaisal","avatar":""},{"name":"Binn Kitchachonpong","avatar":""},{"name":"Rossukon Kongket","avatar":""},{"name":"Pornsawan Sriboonwong","avatar":""},{"name":"Oraphan Arjsamat","avatar":""},{"name":"Aummaraporn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["헬로 스트레인저","你好，陌生人","กวนมึนโฮ","你好陌生人","กวน มึน โฮ"]', 1784690324473);
