INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-tinh-yeu', 'Bí Mật Của Tình Yêu', 'The Mysteries of Love', 'https://phimimg.com/upload/vod/20251008-1/6bcb583fb368c5a6c19e39d4b9d302b3.jpg', 'https://phimimg.com/upload/vod/20251008-1/a131665751d08c0fbe7f5d02ebb39b03.jpg', '<p>Cảnh Bác đã giúp Thiên Hằng phá giải hàng loạt vụ án kỳ bí, cũng nhờ vậy mà Cảnh Bác quen biết nữ cảnh sát Từ Tiểu Lệ (Dương Di). Lý tính phân tích rõ cho Cảnh Bác biết sở dĩ anh nảy sinh tình cảm với Tiểu Lệ, là do hormone tình yêu mang tên phenylalanine gây ra, tuy nhiên hoàn cảnh trưởng thành và quan niệm cuộc sống của 2 người hoàn toàn khác nhau, dù vận dụng bất kỳ công thức nào cũng không thể cứu được một cuộc tình có rất nhiều biến số.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 14, 2010, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Lam Fung","avatar":""},{"name":"Kenneth Ma Kwok-Ming","avatar":""},{"name":"Tavia Yeung Yi","avatar":""},{"name":"Bernice Liu","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Evergreen Mak Cheung-Ching","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Ram Chiang Chi-Kwong","avatar":""},{"name":"Ruco Chan Chin-Pang","avatar":""},{"name":"Joseph Lee Kwok-Lun","avatar":""},{"name":"Yu Chi-Ming","avatar":""},{"name":"Candy Chiu Ching-Yee","avatar":""},{"name":"Lee Ji-Kei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Mysteries Of Love","談情說案"]', 1784690324473);
