INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-phong-liet', 'Tây Phong Liệt', 'Wind Blast', 'https://phimimg.com/upload/vod/20251008-1/66fae4a4201b03de2f593eb3b0f27449.jpg', 'https://phimimg.com/upload/vod/20251008-1/8c62c028b1b896dc72a9632148ce409d.jpg', '<p>Sau khi thực hiện thành công phi vụ ám sát một người đàn ông để kiếm tiền, tên võ sĩ bí hiểm đào tẩu trên sa mạc Gobi với cô bạn gái đang mang thai của hắn.</p>', 'Full', 1, 'single', 'completed', 23, 2010, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Duan Yihong","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Xia Yu","avatar":""},{"name":"Charlie Yeung Choi-Nei","avatar":""},{"name":"Yu Nan","avatar":""},{"name":"Tse Kwan-Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["西风烈","Wind Blast","西風烈"]', 1784690324473);
