INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-than', 'Ác Thần', 'Legion', 'https://phimimg.com/upload/vod/20251008-1/6aef30231ea84b42857134312ed48207.jpg', 'https://phimimg.com/upload/vod/20251008-1/005c95f1f0ada36b826ee8192931242f.jpg', '<p>Phim Ác Thần kể lại cuộc đấu tranh sinh tồn khắc nghiệt và tàn bạo, một bên là đạo quân ác thần hùng mạnh do Đức Chúa trời phái xuống nhằm tiêu diệt tận gốc loài người như từng làm trước đây, khi dùng cơn đại hồng thủy. Tuy nhiên, Tổng lãnh Thiên thần Michael đã quyết định bất tuân lệnh Chúa, bí mật giáng trần và giúp đỡ những con người đang bị kẹt trong một nhà hàng hẻo lánh vùng sa mạc New Mexico. Đây chính là nơi có cô gái trẻ Charlie đang mang trong mình niềm hy vọng duy nhất của nhân loại, một đứa bé sau này sẽ trở thành Đấng Cứu Thế.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Paul Bettany","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Kate Walsh","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Adrianne Palicki","avatar":""},{"name":"Willa Holland","avatar":""},{"name":"Charles S. Dutton","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Jeanette Miller","avatar":""},{"name":"Cameron Harlow","avatar":""},{"name":"Josh Stamberg","avatar":""},{"name":"Yancey Arias","avatar":""},{"name":"Stephen Oyoung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Légion, L''Armée des anges","Legião 2010","리전","리젼","Legion"]', 1784690324473);
