INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-dao-chich-kaito-kid', 'Siêu Đạo Chích Kaito Kid', 'Magic Kaito: Kid the Phantom Thief', 'https://phimimg.com/upload/vod/20250820-1/558afe9b008a7e625c60504b78293d4a.jpg', 'https://phimimg.com/upload/vod/20250820-1/76fec321d58cd1b13093f57f5c232676.jpg', '<p>Kuroba Kaito, một học sinh trung học bình thường, phát hiện cha mình – một ảo thuật gia nổi tiếng – thực chất là siêu trộm Kaito Kid và đã bị sát hại bí ẩn. Kaito quyết định khoác lên mình danh tính của Kaito Kid để điều tra sự thật. Anh sử dụng tài ảo thuật và sự thông minh để đánh lừa cảnh sát, đồng thời truy tìm những người đứng sau cái chết của cha mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kappei Yamaguchi","avatar":""},{"name":"Ayumi Fujimura","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["怪盗基德","まじっく快斗Kid thePhantom Thief","Magic Kaito","괴도 키드","매직 카이토","괴도키드 스페셜","まじっく快斗"]', 1784690324473);
