INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-vang-nhat-thuc', 'Chạng Vạng: Nhật Thực', 'The Twilight Saga: Eclipse', 'https://phimimg.com/upload/vod/20250812-1/69fc6b365ad77a862ed5853192192a0b.jpg', 'https://phimimg.com/upload/vod/20250812-1/01b3ff99c0f5b847be72720e97297714.jpg', '<p>Đưa tính hành động, tình yêu, tình bạn, sự ghen tuông, niềm đam mê - những gì đã đưa Twilight và The Twilight Saga: New Moon trở thành bom tấn trên toàn thế giới - lên một tầm cao mới, The Twilight Saga: Eclipse được đốt cháy bởi những âm mưu báo thù và câu chuyện tình yêu ngang trái.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Taylor Lautner","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Nikki Reed","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Justin Chon","avatar":""},{"name":"Christian Serratos","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Twilight Saga: Eclipse","The Twilight Saga 3 - Eclipse","Twilight - Chapitre 3 - Hésitatio