INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-va-ran-3', 'Hoa Và Rắn 3', 'Flower & Snake 3', 'https://phimimg.com/upload/vod/20250729-1/4f2e5ab0fe173d1aaa8b479645a0aa96.jpg', 'https://phimimg.com/upload/vod/20250729-1/719718732edce3d4ec7b116f54ed1cd3.jpg', '<p>Một doanh nhân tàn nhẫn với các đối thủ cạnh tranh của mình, và để đáp lại các đối thủ của mình sau khi bị đuổi khỏi công việc kinh doanh, đã bắt cóc vợ của một doanh nhân nói trên và bắt đầu đào tạo cô ấy trở thành một ngôi sao khiêu dâm, đặc biệt là thể loại S&amp;M/bondage.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minako Komukai","avatar":""},{"name":"Yasukaze Motomiya","avatar":""},{"name":"Shōhei Hino","avatar":""},{"name":"Mari Komatsuzaki","avatar":""},{"name":"Kei Mizutani","avatar":""},{"name":"Kotono","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["花与蛇3","Flower And Snake III","꽃과 뱀 3","花と蛇 3"]', 1784690324473);
