INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-zero-belial-bao-thu', 'Ultraman Zero: Belial Báo Thù', 'Ultraman Zero: The Revenge of Belial', 'https://phimimg.com/upload/vod/20250727-1/238dd3cc466ff19962b8e745dbd87b61.jpg', 'https://phimimg.com/upload/vod/20250727-1/1c0a0211eddd7fdb916c199c6de4274f.jpg', '<p>Ultraman Zero: Belial Báo Thù là phần phim tiếp nối vũ trụ Ultra, nơi cái ác trở lại dưới hình hài quen thuộc nhưng nguy hiểm hơn bao giờ hết. Belial - Ultraman sa ngã không chỉ sống sót sau thất bại, mà còn tiến hóa và tập hợp một đội quân hắc ám với âm mưu chiếm lấy toàn bộ thiên hà. Trước hiểm họa lan rộng, Ultraman Zero, chiến binh trẻ quả cảm, bắt đầu tập hợp lực lượng gồm cả con người và các chiến binh ngoài hành tinh để một lần nữa ngăn chặn Belial. Đây là hành trình rực lửa giữa ánh sáng và bóng tối, nơi lòng dũng cảm, tình đồng đội và tinh thần chiến đấu được đẩy đến giới hạn cuối cùng.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mamoru Miyano","avatar":""},{"name":"Tatsuomi Hamada","avatar":""},{"name":"Yū Koyanagi","avatar":""},{"name":"Tao Tsuchiya","avatar":""},{"name":"Tamotsu Ishibashi","avatar":""},{"name":"Yasue Sato","avatar":""},{"name":"Kaito Nitta","avatar":""},{"name":"Kaito Kobayashi","avatar":""},{"name":"Minako Ide","avatar":""},{"name":"Kenrô Nanbara","avatar":""},{"name":"Yuka Hanabusa","avatar":""},{"name":"Maaya Takada","avatar":""},{"name":"Sei Hiraizumi","avatar":""},{"name":"Kitaro","avatar":""},{"name":"Bengal","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Hiroshi Kamiya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Urutoraman Zero THE MOVIE: Chōkessen! Beriaru Ginga Teikoku","赛罗奥特曼超决战：贝利亚银河帝国","Ultraman Zero Super Deciding Fight The Belial Galactic Empire","ウルトラマンゼロ THE MOVIE 超決戦!ベリアル銀河帝国","ウルトラマンゼロ THE MOVIE 超決戦！ベリアル銀河帝国"]', 1784690324473);
