INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ultraman-zero-belial-bao-thu', 'Ultraman Zero: Belial Báo Thù', 'Ultraman Zero: The Revenge of Belial', 'ultraman zero: belial báo thù ultraman zero: the revenge of belial mamoru miyano tatsuomi hamada yū koyanagi tao tsuchiya tamotsu ishibashi yasue sato kaito nitta kaito kobayashi minako ide kenrô nanbara yuka hanabusa maaya takada sei hiraizumi kitaro bengal hikaru midorikawa tomokazu seki hiroshi kamiya urutoraman zero the movie: chōkessen! beriaru ginga teikoku 赛罗奥特曼超决战：贝利亚银河帝国 ultraman zero super deciding fight the belial galactic empire ウルトラマンゼロ the movie 超決戦!ベリアル銀河帝国 ウルトラマンゼロ the movie 超決戦！ベリアル銀河帝国', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-toc', 'Thần Tốc', 'Faster', 'https://phimimg.com/upload/vod/20250725-1/90f0446541f8849d024ff2e72b36061a.jpg', 'https://phimimg.com/upload/vod/20250725-1/134fee270c94361827516f43df59d1bd.jpg', '<p>Sau khi ở tù mười năm, người đàn ông biệt danh Driver được trả tự do, vừa ra tù thì anh ta liền lấy xe chạy đến một công ty rồi dùng súng bắn chết ông nhân viên trong công ty này. Trước đây, hai anh em Driver từng bị một băng cướp xông vào nhà sát hại, anh trai Driver là Gary bị cắt cổ, còn Driver bị tên trùm bắn. May mắn là Driver còn sống, nhưng anh ta phải ở tù vì trước đó anh và Gary có đi cướp ngân hàng, Driver luôn nuôi ý chí trả thù cho anh mình khi anh ta ở trong tù.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Oliver Jackson-Cohen","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Jeff Daniel Phillips","avatar":""},{"name":"Aaron Behr","avatar":""},{"name":"Jan Hoag","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Michael Irby","avatar":""},{"name":"Josh Clark","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Michael Blain-Rozgay","avatar":""},{"name":"Sidney S. Liufau","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Faster: Iute ca glontul","Faster - Tödliche Rache","Nhanh Hơn","패스터","Venganza letal","极速复仇","ტყვიაზე სწრაფი","უფრო სწრაფი","Faster"]', 1784690324473);
