INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghia-hai-hao-tinh', 'Nghĩa Hải Hào Tình', 'No Regrets', 'https://phimimg.com/upload/vod/20250723-1/095f58bed1e7ebafc63e3f83605b23a7.jpg', 'https://phimimg.com/upload/vod/20250723-1/63199a4b0fc3a4943c7f10644fe7939e.jpg', '<p>Thập niên 30, tình hình chính trị Quảng Châu gặp nhiều biến động, tệ nạn xã hội mặc sức hoành hành. Do thị trường kinh doanh á phiện thu lợi béo bở, chính phủ đương thời quyết định thành lập cục cấm thuốc phiện, mang danh nghĩa cấm nhưng thực chất là công khai tiếp tay cho việc kinh doanh ngầm mặt hàng này. Trịnh Cửu Muội (do Đặng Tuỵ Văn đóng) là con gái của một trùm bán á phiện và trở về để tiếp quản việc kinh doanh của gia đình. Cảnh sát trưởng Lưu Tỉnh (do Lê Diệu Tường đóng) và Cửu Muội là hai nhân vật chính, đối đầu với nhau nhưng sau đó phát triển mối quan hệ tình cảm. Khi Quảng Châu bị chiếm đóng bởi quân Nhật, Cửu Muội bị hãm hại và Lưu Tỉnh cùng cô vượt qua những khó khăn đen tối nhất của cuộc đời.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 14, 2010, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đặng Tụy Văn","avatar":""},{"name":"Lê Diệu Tường","avatar":""},{"name":"Huỳnh Hạo Nhiên","avatar":""},{"name":"Trần Pháp Lai","avatar":""},{"name":"Nhạc Hoa","avatar":""},{"name":"Tạ Tuyết Tâm","avatar":""},{"name":"Huệ Anh Hồng","avatar":""},{"name":"Ngao Gia Niên","avatar":""},{"name":"Mạch Trường Thanh","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Huỳnh Trí Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["義海豪情","巾帼枭雄之义海豪情","Rosy Business: No Regrets","巾幗梟雄之義海豪情"]', 1784690324473);
