INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nghia-hai-hao-tinh', 'Nghĩa Hải Hào Tình', 'No Regrets', 'nghĩa hải hào tình no regrets đặng tụy văn lê diệu tường huỳnh hạo nhiên trần pháp lai nhạc hoa tạ tuyết tâm huệ anh hồng ngao gia niên mạch trường thanh hồ định hân huỳnh trí hiền 義海豪情 巾帼枭雄之义海豪情 rosy business: no regrets 巾幗梟雄之義海豪情', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-mat-trang', 'Kẻ Trộm Mặt Trăng', 'Despicable Me', 'https://phimimg.com/upload/vod/20250516-1/9479bf96d2ace3e87261975f31b219fb.jpg', 'https://phimimg.com/upload/vod/20250516-1/e51402a887bb3dab4db99a396fd03a53.jpg', '<p>Nhân vật tâm điểm của bộ phim là Gru, một tên tội phạm khét tiếng. Gru và đám tay chân robot tí hon chuyên đi đánh cắp những biểu tượng nổi tiếng của thế giới. Thế nhưng tiếng xấu của Gru bị suy giảm khi tên tội phạm trẻ tuổi Vector đã ăn cắp kim tự tháp của Ai Cập. Gru quyết định làm phi vụ có một không hai cho thế giới phải bái phục: ăn cắp mặt trăng. Trước tiên, Gru phải đánh cắp khẩu súng có khả năng thu nhỏ mọi vật từ quân đội. Nhưng Vector đã nẫng tay trên khẩu súng thần kỳ từ Gru. Mọi kế hoạch giành lại cây súng của Gru đều bị Vector đánh bại. Cuối cùng, Gru nghĩ ra cách dùng ba đứa trẻ của viện mồ côi xâm nhập sào huyệt của Vector. Thế nhưng ba đứa trẻ Margo, Edith, Agnes đã cảm hóa Gru bằng sự ngây thơ, hướng thiện của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2010, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Steve Carell","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Miranda Cosgrove","avatar":""},{"name":"Elsie Fisher","avatar":""},{"name":"Dana Gaier","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Chris Renaud","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Rob Huebel","avatar":""},{"name":"Ken Daurio","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Verschrikkelijke ikke en de rest kan stikke","Cilgin Hirsiz","Aulinn ég","Dumma mig","슈퍼 배드","Despicable Me 3D","卑鄙的我","坏蛋奖门人","Kẻ Trộm Mặt Trăng","壞蛋獎門人","Moi, moche et méchant","Moi moche et méchant","怪盗グルーの月泥棒","Ich - Einfach unverbesserlich","Gru. Mi villano favorito","Illumination''s Despicable Me","Despicable Me"]', 1784690324473);
