INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-kiep-sau', 'Vùng Đất Quỷ Dữ: Kiếp Sau', 'Resident Evil: Afterlife', 'https://phimimg.com/upload/vod/20250716-1/e42aa66d4fa840e7f7c4211568d03e71.jpg', 'https://phimimg.com/upload/vod/20250716-1/a21880867698bee09c0f9232d78060f8.jpg', '<p>Alice tiếp tục hành trình tìm kiếm những con người sống sót và dẫn dắt họ tới nơi an toàn. Cuộc đối đầu với tổ chức Umbrella tiếp tục diễn ra cam go, nhưng Alice lần này nhận được sự giúp đỡ không ngờ tới từ một người bạn cũ.</p>', 'Full', 1, 'single', 'completed', 20, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Kacey Clarke","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Sergio Peris-Mencheta","avatar":""},{"name":"Boris Kodjoe","avatar":""},{"name":"Spencer Locke","avatar":""},{"name":"Sienna Guillory","avatar":""},{"name":"Norman Yeung","avatar":""},{"name":"Ray Olubowale","avatar":""},{"name":"Christopher Kano","avatar":""},{"name":"Tatsuya Goke","avatar":""},{"name":"Fulvio Cecere","avatar":""},{"name":"Nobuya Shimamoto","avatar":""},{"name":"Denis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Resident Evil 4","Resident Evil 4: Afterlife","Biohazard IV","Resident Evil - Afterlife","Resident Evil 4 3D","Resident Evil 4 - Afterlife","Resident evil 4: La resurreccion","Resident Evil 4 : Afterlife","Resident Evil : Afterlife","Resident evil: L''au-delà","Resident Evil 4 La Resurrección","Resident Evil 4 Ultratumba","Оселя зла 4","Resident Evil 4 - Recomeço","Обитель зла 4: Жизнь после смерти 3D","레지던트 이블 4","Обитель зла: Жизнь после смерти","Оселя зла: Потойбічне життя","Resident Evil. Afterlife","Resident Evil: Afterlife 3D","레지던트 이블 4-끝나지 않은 전쟁","Resident Evil 4: La Resurreccion","Resident Evil：Afterlife","Resident Evil։ Afterlife 3D","生化危机4：战神再生","Resident Evil Afterlife","バイオハザード4","الشر المقيم : ما بعد الحياة","Resident Evil: Afterlife"]', 1784690324473);
