INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-quy-du-kiep-sau', 'Vùng Đất Quỷ Dữ: Kiếp Sau', 'Resident Evil: Afterlife', 'vùng đất quỷ dữ: kiếp sau resident evil: afterlife milla jovovich wentworth miller ali larter kim coates kacey clarke shawn roberts sergio peris-mencheta boris kodjoe spencer locke sienna guillory norman yeung ray olubowale christopher kano tatsuya goke fulvio cecere nobuya shimamoto denis resident evil 4 resident evil 4: afterlife biohazard iv resident evil - afterlife resident evil 4 3d resident evil 4 - afterlife resident evil 4: la resurreccion resident evil 4 : afterlife resident evil : afterlife resident evil: l''au-delà resident evil 4 la resurrección resident evil 4 ultratumba оселя зла 4 resident evil 4 - recomeço обитель зла 4: жизнь после смерти 3d 레지던트 이블 4 обитель зла: жизнь после смерти оселя зла: потойбічне життя resident evil. afterlife resident evil: afterlife 3d 레지던트 이블 4-끝나지 않은 전쟁 resident evil 4: la resurreccion resident evil：afterlife resident evil։ afterlife 3d 生化危机4：战神再生 resident evil afterlife バイオハザード4 الشر المقيم : ما بعد الحياة resident evil: afterlife', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-bong-than-tinh-yeu', 'Hình Bóng Thần Tình Yêu', 'Cupid''s Shadows', 'https://phimimg.com/upload/vod/20250421-1/a32917db485b683f15595e20a3e756f5.jpg', 'https://phimimg.com/upload/vod/20250421-1/130b904e9f37a41b00d61e0c1805cef6.jpg', '<p>Rome (Weir) là một doanh nhân trẻ, là bạn thân của Pat. Pat đã đính hôn với Pipu nhưng Monthat, anh trai của Pat đã cưỡng bức Pipu và Pipu đã có thai. Pipu muốn tự tử nhưng Pat đã ngăn cản và hứa là sẽ xem đứa bé như con ruột. Vì ba của Pat và Monthat yêu cầu phải có cháu trai nên khi Pipu sinh ra một bé gái, Monthat đã mang đứa bé đi đổi với con trai của một người làm công với tín vật là sợi dây chuyền có lồng 1 chiếc nhẫn đeo ở cổ. Sau đó Monthat đã cố giết chết Pat để chiếm đoạt gia tài kể cả Pipu. Thời gian trôi qua, Tien (Mai), đứa bé gái được tráo đổi năm xưa được ba mẹ nuôi, nuôi dưỡng như một đứa con trai để che dấu mọi chuyện. Tuy nhiên&nbsp; ba mẹ nuôi của Tien cũng bị giết chết sau một tai nạn xe hơi và Tien phải lưu lạc ở ngoài bờ biển Hua Hin. Tại đây Tien đã gặp Rome. Trải qua nhiều chuyện, Rome đã đưa Tien về nhà mình ở Huahin, nơi mà Pat đang được chăm sóc sau khi thoát khỏi sự mưu sát năm xưa. Pat nhận ra Tien có chiếc nhẫn của ba mình và nói cho Rome biết mọi sự thật.Sau đó vì sức khỏe suy yếu nên Pat qua đời và Rome quyết định trả thù Monthat. Lồng ghép mọi việc lại, Rome với sự giúp đỡ của em gái Pa và em rể đã đoán ra được Tien là bé gái năm xưa bị tráo đổi và cũng là con ruột của Monthat. Rome quyết định đưa Tien về Bangkok để cải tạo, giáo dục Tien từ một cô bé giả trai mồ côi trở thành một cô gái thượng lưu, để chống lại Monthat. Tien rất tin tưởng, tôn trọng và yêu Rome. Trong khi phải đấu tranh tư tưởng giữa trả thù và tình cảm với Tien thì Rome còn phải đối mặt với sự trở lại của Mon, vị hôn thê cũ, đang tìm mọi cách để đẩy Tien ra khỏi vòng tay của Rome….</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sukollawat Kanarot","avatar":""},{"name":"Davika Hoorne","avatar":""},{"name":"Patson Sarindu","avatar":""},{"name":"Kratip Chawallakorn Wanthanapisitkul","avatar":""},{"name":"Voravudh Niyomsap","avatar":""},{"name":"Kade Tharakade Petchsuksai","avatar":""},{"name":"Tunsinee Promsut","avatar":""},{"name":"Tawatson Plengsiriwat","avatar":""},{"name":"Sam Chotibun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ngao Kammathep","เงากามเทพ"]', 1784690324473);
