INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-lan-lam-gangster', 'Một Lần Làm Gangster', 'Once a Gangster', 'https://phimimg.com/upload/vod/20250523-1/d45ab6c717001ba1b8d520cce856b102.jpg', 'https://phimimg.com/upload/vod/20250523-1/a1bfd4aecc7825c795a9888daf1410fd.jpg', '<p>Hai cựu đại ca xã hội đen được tiến cử làm thủ lĩnh cho bang hội, nhưng cả hai đều muốn có cuộc sống bình dị. Mỗi bên phải đánh lừa nhau để được thua cuộc bầu chọn.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Trịnh Y Kiện","avatar":""},{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Phương Trung Tín","avatar":""},{"name":"Diệp Tuyền","avatar":""},{"name":"Dư An An","avatar":""},{"name":"Lưu Hạo Long","avatar":""},{"name":"Trần Tử Thông","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Once a Gangster","飛沙風中轉","飛砂風中轉"]', 1784690324473);
