INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-phung-diem', 'Long Phụng Điếm', 'The Adventure Of The King', 'https://phimimg.com/upload/vod/20250626-1/11740d32960f8caaeb3879e047111571.jpg', 'https://phimimg.com/upload/vod/20250626-1/2ecea76d951d99a9359598d493e13e5f.jpg', '<p>Vua Chính Đức (Nhậm Hiền Tề) giả dân thường để vi hành rồi không may bị mất trí nhớ. Xui khiến thế nào, ngài đã gặp và phải lòng yêu bà chủ quán Lý Phụng Tỷ (Đại S - Từ Hy Viên) chua ngoa, sát phạt.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Từ Hy Viên","avatar":""},{"name":"Hoắc Tư Yến","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dragon and Phoenix Inn","Long Feng Dian","Lung Fung Dim","Adventure.of.the.King","龍鳳店"]', 1784690324473);
