INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-bao-boi-tu-than-phan-1', 'Harry Potter và Bảo Bối Tử Thần: Phần 1', 'Harry Potter and the Deathly Hallows: Part 1', 'https://phimimg.com/upload/vod/20250602-1/c847d25d6018d0665aa03fb75c981c1a.jpg', 'https://phimimg.com/upload/vod/20250602-1/be0884caecf9eb4741932860ae5d5ae4.jpg', '<p>Chúa tể Voldemort cùng đám tay chân của hắn đang âm mưu tấn công Harry Potter khi cậu rời khỏi ngôi nhà của gia đình Dursley lần cuối cùng. Ngay trước khi phép bảo vệ cho Harry tại gia đình Dursley hết hiệu lực vào thời điểm Harry bước qua tuổi 17, người của Hội Phượng hoàng đến để hộ tống cậu tới một nơi ở mới an toàn. Mặc dù đã dùng sáu người nguỵ trang thành Harry, Harry thật vẫn bị Voldemort cùng các Tử thần Thực tử phát hiện ra trên đường đi và bị tấn công...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Evanna Lynch","avatar":""},{"name":"Andy Linden","avatar":""},{"name":"Guy Henry","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"David Thew","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Harry Potter en de relieken des doods - Deel 1","해리 포터와 죽음의 성물 - 파트1","Harry Potter y las Reliquias de la Muerte: Parte 1","Harry Potter a Dary smrti - 1. časť","Harry Potter och dödsrelikerna – Del 1","Harry Potter et les Reliques de la mort : 1re partie","Harry Potter e as Relíquias da Morte - Parte 1","해리포터와 죽음의성물 1","해리포터와 죽음의 성물 1","해리 포터와 죽음의 성물 1","해리 포터와 죽음의 성물 - 1부","Гарри Поттер и Дары Смерти: Часть I","ハリー・ポッターと死の秘宝 Part1","ハリーポッターと死の秘宝 Part1","Harry Potter and the Deathly Hallows։ Part 1 3D","Harry Potter ja surma vägised: Osa 1","哈利·波特与死亡圣器（上）","هاري بوتر ومقدسات الموت الجزء الأول","הארי פוטר ואוצרות המוות: חלק א''","הארי פוטר 7","Հարրի Փոթերը և Մահվան պարգևները։ Մաս 1","해리 포터 7","Harry Potter 7 - The Deathly Hallows - Part 1","Harry Potter 7 - Deathly Hallows - Part 1","Harry Potter 7","Harry Potter y las reliquias de la muerte - Parte 1","Harry Potter and the Deathly Hallows: Part 1"]', 1784690324473);
