INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-bao-boi-tu-than-phan-1', 'Harry Potter và Bảo Bối Tử Thần: Phần 1', 'Harry Potter and the Deathly Hallows: Part 1', 'harry potter và bảo bối tử thần: phần 1 harry potter and the deathly hallows: part 1 daniel radcliffe emma watson rupert grint toby jones helena bonham carter alan rickman ralph fiennes bill nighy simon mcburney rhys ifans evanna lynch andy linden guy henry jason isaacs brendan gleeson john hurt robbie coltrane david thew harry potter en de relieken des doods - deel 1 해리 포터와 죽음의 성물 - 파트1 harry potter y las reliquias de la muerte: parte 1 harry potter a dary smrti - 1. časť harry potter och dödsrelikerna – del 1 harry potter et les reliques de la mort : 1re partie harry potter e as relíquias da morte - parte 1 해리포터와 죽음의성물 1 해리포터와 죽음의 성물 1 해리 포터와 죽음의 성물 1 해리 포터와 죽음의 성물 - 1부 гарри поттер и дары смерти: часть i ハリー・ポッターと死の秘宝 part1 ハリーポッターと死の秘宝 part1 harry potter and the deathly hallows։ part 1 3d harry potter ja surma vägised: osa 1 哈利·波特与死亡圣器（上） هاري بوتر ومقدسات الموت الجزء الأول הארי פוטר ואוצרות המוות: חלק א'' הארי פוטר 7 հարրի փոթերը և մահվան պարգևները։ մաս 1 해리 포터 7 harry potter 7 - the deathly hallows - part 1 harry potter 7 - deathly hallows - part 1 harry potter 7 harry potter y las reliquias de la muerte - parte 1 harry potter and the deathly hallows: part 1', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-cuoc-dai-thuy-chien-o-xu-so-nguoi-ca', 'Doraemon: Nobita và Cuộc Đại Thủy Chiến Ở Xứ Sở Người Cá', 'Doraemon: Nobita''s Great Battle of the Mermaid King', 'https://phimimg.com/upload/vod/20250521-1/483979a4b955721950608cafd7f585b6.jpg', 'https://phimimg.com/upload/vod/20250521-1/f5e28d866bed2bf95e70e6d3779d8e51.jpg', '<p>Nobita muốn bơi lặn ngay trong thành phố Tokyo. Vì vậy, Doraemon đã sử dụng Máy bơm mô phỏng nguồn nước biển nhân tạo để bơm nước ngập đầy thành phố. Đêm đó Doraemon và Nobita sử dụng kính tạo cảm giác và chân vịt bơi lặn để dạo quanh thành phố toàn nước. Bỗng xuất hiện cá mập đe doạ mọi người và Doraemon buộc phải tắt máy bơm. Nhóm bạn phát hiện một cô bé người cá nằm ngất trong lùm cây tên là Sophia. Họ đưa cô về nhà và biết được thân thế công chúa Vương quốc người cá của cô. Nhóm bạn có một chuyến tham quan tại Vương quốc đó.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2010, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Shihoko Hagino","avatar":""},{"name":"Mayumi Izuka","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Doraemon 2010, Nobita and the Great Mermaid Battle","Doraemon the Legend 2010","人魚大海戰","のび太の人魚大海戦","Doraemon: Nobita''s Great Battle of the Mermaid King","Doraemon the Movie: Nobita''s Mermaid Legend","Doraemon Nobita no Ningyo Daikaisen","Nobita and the Great Battle of the Mermaid King","도라에몽: 노비타의 인어대해전","哆啦A夢：大雄的人魚大海戰","Eiga Doraemon: Nobita no Ningyo Daikaisen","โดราเอมอน เดอะ มูฟวี่: สงครามเงือกใต้สมุทร","Pertempuran Hebat Nobita dengan Raja Duyung","映画ドラえもん のび太の人魚大海戦"]', 1784690324473);
