INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-salt', 'Điệp Viên Salt', 'Salt', 'https://phimimg.com/upload/vod/20230917-1/8ab3c0e0d69931ea79b46d0b3f4da4f4.jpg', 'https://phimimg.com/upload/vod/20230917-1/f1e37412f6965a1a21193b4e5e8b244c.jpg', '<p><span style="font-family: ">Evelyn Salt, một đặc vụ CIA đã thề rằng sẽ phục vụ hết mình cho tổ quốc. Tuy nhiên, lòng trung thành của cô bị nghi ngờ khi một tên phản bội buộc tội cô là đặc vụ ngầm của Nga. Salt không còn cách nào khác ngoài việc phải bỏ trốn, dùng tất cả kĩ năng và kinh nghiệm tích lũy bấy lâu của một điệp viên để tránh bị bắt lại. Thế nhưng, nỗ lực của cô nhằm chứng minh sự vô tội của bản thân chỉ khiến cho mọi người thêm nghi ngờ về hành động của cô. Và, cuộc săn đuổi nhằm đưa sự thật về thân phận cô ra ngoài ánh sáng vẫn cứ tiếp diễn với một câu hỏi chưa thể trả lời được: &quot;Salt là ai?&quot;</span></p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Daniel Olbrychski","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Daniel Pearce","avatar":""},{"name":"Hunt Block","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Cassidy Hinkle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324473);
