INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-dien-loan', 'Những Kẻ Điên Loạn', 'The Crazies', 'https://phimimg.com/upload/vod/20250517-1/d38e4e93870af30eb14f04ddf2402d8d.jpg', 'https://phimimg.com/upload/vod/20250517-1/87c326c960684c1d1600a0ac24d5f821.jpg', '<p>Khi độc tố bắt đầu để quay các cư dân của Ogden Marsh, Iowa vào tâm thần bạo lực, cảnh sát trưởng David Dutton cố gắng để làm cho ý nghĩa của tình hình trong khi ông, vợ ông, và hai ban nhạc dân thị trấn bị ảnh hưởng với nhau trong một cuộc chiến cho sự sống còn.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Timothy Olyphant","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Joe Reegan","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Gregory Sporleder","avatar":""},{"name":"Lynn Lowry","avatar":""},{"name":"Christie Lynn Smith","avatar":""},{"name":"Brett Rickaby","avatar":""},{"name":"Preston Bailey","avatar":""},{"name":"John Aylward","avatar":""},{"name":"Larry Cedar","avatar":""},{"name":"Pierce Gagnon","avatar":""},{"name":"Mike Hickman","avatar":""},{"name":"Lisa K. Wyatt","avatar":""},{"name":"Just","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["La città verrà distrutta all''alba","A Epidemia","疯杀禁区","A tébolyultak","Sed de Muerte","El Día Del Apocalipsis","The Crazies Fuerchte deinen Naechsten","The Crazies"]', 1784690324473);
