INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-quyen-anh', 'Huyền Thoại Quyền Anh', 'The Fighter', 'https://phimimg.com/upload/vod/20250514-1/61a7e9841055bc52fbc46c968bea07c2.jpg', 'https://phimimg.com/upload/vod/20250514-1/1ce43883298041946b1fc7faa302f31e.jpg', '<p>“The Fighter” kể về cuộc đời của tay đấm huyền thoại “Irish” Mickey Ward cùng người anh trai Dick Eklund. Đây là một cuốn nhật kí bằng phim xoay từ những ngày đầu của hai anh em trên những con đường gồ ghề của Lowell, Massachusetts thông qua các sự đầu tranh của Eklund với ma túy và giải vô địch thế giới cuối cùng của Ward ở London. Hai chàng diễn viên tài tử sẽ &nbsp;mang khán giả đến với những diễn biến tâm lý phức tạp và quá trình tập luyện gian khổ của tay đấm huyền thoại “Irish” cũng như những rắc rối khiến Dick Eklund vào tù.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Mickey O''Keefe","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Melissa McMeekin","avatar":""},{"name":"Bianca Hunter","avatar":""},{"name":"Erica McDermott","avatar":""},{"name":"Jill Quigg","avatar":""},{"name":"Dendrie Taylor","avatar":""},{"name":"Kate B. O''Brien","avatar":""},{"name":"Jenna Lamia","avatar":""},{"name":"Frank Renzulli","avatar":""},{"name":"Paul Campbell","avatar":""},{"name":"Caitlin Dwyer","avatar":""},{"name":"Chanty S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fighter","燃烧斗魂","燃燒鬥魂","파이터","Boxer","O Vencedor 2010","Taistelija","The Fighter - A harcos","Võ Sĩ","The Fighter"]', 1784690324473);
