INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-long-doi-quyet', 'Hoả Long Đối Quyết', 'Fire Of Conscience', 'https://phimimg.com/upload/vod/20231125-1/c346f58747f9f4d4739b5ed0be07d353.jpg', 'https://phimimg.com/upload/vod/20231125-1/478f2eba4229476c1c6dc4de5db70692.jpg', '<p>Trong màn đêm, cảnh sát Văn Phương mang nặng vết thương lòng, dấn thân vào cuộc truy lùng kẻ sát nhân gieo rắc nỗi kinh hoàng lên những nhân chứng yếu ớt. Bên cạnh anh là Kỷ Thiếu Quần, đồng nghiệp bí ẩn với ánh mắt dò xét, họ cùng nhau lần theo dấu vết tội ác ẩn sau bức màn tham nhũng. Những bí mật chôn vùi và mối thù hận âm ỉ từ quá khứ dần được hé lộ. Giữa lằn ranh thiện ác mong manh, sự thật hiện ra như lưỡi dao sắc lạnh, đe dọa xé toạc những mối quan hệ tưởng chừng bền vững. Cuộc đối đầu cuối cùng không chỉ là cuộc chiến giữa cảnh sát và tội phạm, mà còn là sự giằng xé trong lương tâm mỗi người.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lê Minh","avatar":""},{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Vương Bảo Cường","avatar":""},{"name":"Từ Nhược Tuyên","avatar":""},{"name":"Liêu Khải Trí","avatar":""},{"name":"Diệp Tuyền","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324473);
