INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-thanh-cam-gia-ca', 'Long Thành Cầm Giả Ca', 'The Lute Player Of Long Thanh', 'https://phimimg.com/upload/vod/20250406-1/569d93a3e0f5b432533d54fc8e8e6002.jpg', 'https://phimimg.com/upload/vod/20250406-1/9148b9e34e816756259b33ca4254373c.jpg', '<p>Long thành cầm giả ca là một trong những bộ phim nhựa được xây dựng nhân sự kiện kỷ niệm đại lễ 1000 năm Thăng Long - Hà Nội. Bộ phim dựa theo ý tưởng của bài thơ Long thành cầm giả ca của thi hào Nguyễn Du. Long thành cầm giả ca là câu chuyện hư cấu được xây dựng dựa trên lịch sử triều đại cuối Lê đầu Nguyễn. Mang đậm chất lịch sử và những nét văn hóa truyền thống của người Hà Nội xưa, &#39;Long thành cầm giả ca&#39; là câu chuyện bi tráng và đầy chất thơ về mối tình giữa đại thi hào Nguyễn Du với người đàn bà gảy đàn thành Thăng Long.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 13, 2010, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quách Ngọc Ngoan","avatar":""},{"name":"Nhật Kim Anh","avatar":""},{"name":"NSND Trần Lực","avatar":""},{"name":"NSND Bùi Bài Bình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Крайон Шин-чан","蜡笔小新","Crayon Shin-Chan","Shin Chan","Shin Chan (1992)","Shin-chan","Shin-Chan","Kureyon Shin Chan","짱구는 못말려","เครยอนชินจัง","ชินจัง","蠟筆小新","クレヨンしんちゃん"]', 1784690324473);
