INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kinh-hoang', 'Đảo Kinh Hoàng', 'Shutter Island', 'https://phimimg.com/upload/vod/20250331-1/844c21fcd8486b0c773390b5ec8565f4.jpg', 'https://phimimg.com/upload/vod/20250331-1/cd3c3124f03cd88359919f0c461de8ff.jpg', '<p>Vào năm 1954, hai cảnh sát tư pháp Teddy Daniels và Chuck Aule được cử đến viện tâm thần Ashecliffe, trên Đảo Kinh Hoàng, cảng Boston, để điều tra vụ mất tích của Rachel Solando, một nữ bệnh nhân từng dìm chết 3 đứa con của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Christopher Denham","avatar":""},{"name":"Nellie Sciutto","avatar":""},{"name":"Joseph Sikora","avatar":""},{"name":"Curtis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ilha do Medo","Zindan Adası","Đảo Kinh Hoàng","Suletud saar","不赦島","禁闭岛","Անիծյալների Կղզին","Востраў праклятых","A ilha do Medo","Злокобен остров","Островот Шатер","Остров проклятых","О́стрів про́клятих","Το νησί των καταραμένων","Otok Shutter","Slēgtā sala","Kuždesių sala","Viharsziget","Insula Shutter","La isla siniestra","Suljettu saari","ჩაკეტილი კუნძული","Prokletý ostrov","شٹر آئی لینڈ","جزيرة شاتر","جزیره شاتر","שאטר איילנד","ഷട്ടർ ഐലൻഡ്","シャッター アイランド","셔터 아일랜드","Каргыш аралы","Laʼnatlanganlar oroli","शटर आइलैंड","শাটার আইল্যান্ড","ಷಟರ್ ಐಲೇಂಡ್","隔離島","Prekliaty ostrov","Zlovešči otok","เกาะนรกซ่อนทมิฬ","Ashecliffe","Shutter Island"]', 1784690324473);
