INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-kinh-hoang', 'Đảo Kinh Hoàng', 'Shutter Island', 'đảo kinh hoàng shutter island leonardo dicaprio mark ruffalo ben kingsley max von sydow michelle williams emily mortimer patricia clarkson jackie earle haley ted levine john carroll lynch elias koteas robin bartlett christopher denham nellie sciutto joseph sikora curtis ilha do medo zindan adası đảo kinh hoàng suletud saar 不赦島 禁闭岛 անիծյալների կղզին востраў праклятых a ilha do medo злокобен остров островот шатер остров проклятых о́стрів про́клятих το νησί των καταραμένων otok shutter slēgtā sala kuždesių sala viharsziget insula shutter la isla siniestra suljettu saari ჩაკეტილი კუნძული prokletý ostrov شٹر آئی لینڈ جزيرة شاتر جزیره شاتر שאטר איילנד ഷട്ടർ ഐലൻഡ് シャッター アイランド 셔터 아일랜드 каргыш аралы laʼnatlanganlar oroli शटर आइलैंड শাটার আইল্যান্ড ಷಟರ್ ಐಲೇಂಡ್ 隔離島 prekliaty ostrov zlovešči otok เกาะนรกซ่อนทมิฬ ashecliffe shutter island', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-do-choi-3', 'Câu Chuyện Đồ Chơi 3', 'Toy Story 3', 'https://phimimg.com/upload/vod/20250327-1/d178ebc5de887a673a0098d43114ee5d.jpg', 'https://phimimg.com/upload/vod/20250327-1/f339b673c0467e6a62695bc2b544afbe.jpg', '<p>Cậu bé Andy ngày nào nay đã trở thành người lớn sắp sửa phải bước vào ngưỡng cửa đại học. Đống đồ chơi của cậu, bao gồm cả Woody và Buzz Lightyear, bị đưa vào nhà kho. Và trước khi chúng bị tống lên gác mái, bố mẹ cậu vô tình ném chúng đi. Kết quả là một người dọn rác đã đem những món đồ chơi đó đến Sunnyside, một trung tâm vui chơi dành cho trẻ em, và khi tiếng hô “Đồ chơi mới!” được cất lên là lũ trẻ xông vào tranh giành nhau Ken, Barbie, ông Đầu khoai tây và Buzz Lightyear… Vừa cố gắng tồn tại ở trường tiểu học đáng sợ đó, những nhân vật đồ chơi của chúng ta vừa tìm cách quay trở lại ngôi nhà thân thương nơi có cậu chủ Andy vẫn đang chờ đợi chúng. Trải qua rất nhiều chuyến phiêu lưu, cuối cùng họ cũng được trở về nhà, một đoạn kết thực sự cảm động khiến mọi người không cầm được nước mắt trước tình cảm gắn bó của Andy và những món đồ chơi…</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Tim Allen","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Don Rickles","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Estelle Harris","avatar":""},{"name":"Blake Clark","avatar":""},{"name":"Jeff Pidgeon","avatar":""},{"name":"Ned Beatty","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Jodi Benson","avatar":""},{"name":"John Morris","avatar":""},{"name":"Emily Hahn","avatar":""},{"name":"Timothy Dalton","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Whoopi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["反斗奇兵3","Toy Story III","Toy Story - Játékháború 3.","Příběh hraček 3","토이 스토리 3","ทอย สตอรี่ 3","Toy Story 3","Câu Chuyện Đồ Chơi 3","Oyuncaq Hekayəsi 4","Leikfangasaga 3","История игрушек 3"]', 1784690324473);
