INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-trong-toi', 'Kẻ Sát Nhân Trong Tôi', 'The Killer Inside Me', 'https://phimimg.com/upload/vod/20250325-1/1465eb50778255447080d7e10cba7240.jpg', 'https://phimimg.com/upload/vod/20250325-1/186554205cee83a1c3c96d95487c3a4e.jpg', '<p><span style="text-wrap-mode: wrap;">Phó cảnh sát trưởng Lou Ford là trụ cột của cộng đồng ở thị trấn nhỏ phía tây Texas của ông, kiên nhẫn và có vẻ chu đáo. Một số người cho rằng anh ấy hơi chậm chạp và có thể nhàm chán, nhưng đó là điều tồi tệ nhất họ nói về anh ấy. Nhưng sau đó không ai biết Lou gọi cái gì</span></p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Casey Affleck","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Ned Beatty","avatar":""},{"name":"Tom Bower","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Liam Aiken","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Jay R. Ferguson","avatar":""},{"name":"Blake Lindsley","avatar":""},{"name":"Noah Crawford","avatar":""},{"name":"Caitlin Turner","avatar":""},{"name":"Ali Nazary","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Assassino em Mim","El demonio bajo la piel","キラー・インサイド・ミー","İçimdəki Qatil","The Killer Inside Me"]', 1784690324473);
