INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-tinh-ho-diep-kiem', 'Lưu Tinh Hồ Điệp Kiếm', 'Meteor, Butterfly, Sword', 'https://phimimg.com/upload/vod/20250317-1/b2d47990ee05847515821cc25ef96fd6.jpg', 'https://phimimg.com/upload/vod/20250317-1/266621755ead3edaeb09c679dda394b6.jpg', '<p>Lưu Tinh Hồ Điệp Kiếm được chuyển thể từ tiểu thuyết của nhà văn kiếm hiệp nổi tiếng Cổ Long, Lưu Tinh Hồ Điệp Kiếm xứng đáng là một trong những bộ phim kiếm hiệp hay nhất mọi thời đại. Phim kể về bộ tứ Mạnh Tinh Hồn, Diệp Tường, Thạch Quân, Tiểu Hà – những đệ tử đắc lực của Cao Lão Đại. Sau khi nhận nhiệm vụ ám sát cao thủ võ lâm Tôn Ngọc Bá, Mạnh Tinh Hồn đã trà trộn vào môn phái của y và vô tình rơi vào một âm mưu vô cùng to lớn. Sự thật về thân thế của Mạnh Tinh Hồn cũng dần được vén màn, tình sư đồ giữa anh và sư phụ Cao Lão Đại cũng bị xen ngang bởi những nghi ngờ nối tiếp. Những màn so tài đỉnh cao, những ân oán tình thù trong giới giang hồ chính là điều thu hút khán giả khi xem Lưu Tinh Hồ Điệp Kiếm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2010, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Ý Hàm","avatar":""},{"name":"Trần Sở Hà","avatar":""},{"name":"Vương Diễm","avatar":""},{"name":"Lưu Đức Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Liu Xing, Hu Die, Jian","Meteor, Butterfly, Sword","流星蝴蝶剑"]', 1784690324473);
