INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-danh-tinh', 'Người Vô Danh Tính', 'The Man From Nowhere', 'https://phimimg.com/upload/vod/20231210-1/b3c8f6ad03a1468b7cf78ae7eaaca28a.jpg', 'https://phimimg.com/upload/vod/20231210-1/4050e468d26427b51a935a851eb89a64.jpg', '<p>Vì một biến cố đau buồn trong quá khứ, cựu đặc vụ Cha Tae Shik (Won Bin) từ bỏ tất cả để sống ẩn dật, tách biệt với thế giới bên ngoài. Không bạn, không người thân, hàng ngày anh chỉ trò chuyện với cô bé hàng xóm So-Mi (Kim Sae Ron). Với mong muốn thoát khỏi cuộc sống nghèo túng, mẹ của So-Mi đánh cắp 2 gói hàng của một tổ chức ma túy nguy hiểm. Điều này khiến gia đình cô phải trả giá rất đắt, bản thân So-Mi bị bắt cóc vì mục đích bí ẩn. Bắt đầu từ đây là cuộc hành trình giải cứu và trả thù của Cha Tae Shik</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Won Bin","avatar":""},{"name":"Kim Sae Ron","avatar":""},{"name":"Kim Sung Oh","avatar":""},{"name":"Kim Hee Won","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324473);
