INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-cuong-si', 'Đêm Cuồng Si', 'A Night in Nude Salvation', 'đêm cuồng si a night in nude salvation naoto takenaka hiroko satoh machiko kochi harumi inoue shinobu ôtake jō shishido ヌードの夜　愛は惜しみなく奪う a night in nude: salvation 裸體救贖 çıplak bir gece: kurtuluş ヌードの夜／愛は惜しみなく奪う', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-7', 'Bác Sĩ House (Phần 7)', 'House (Season 7)', 'https://phimimg.com/upload/vod/20250103-1/31e63c658e64ba4451e0242c437ee5ce.jpg', 'https://phimimg.com/upload/vod/20250103-1/1e6f2267e8056fd4caea3d3632efcc0b.jpg', '<p>Trong phần cuối của Phần 6, House, bị thúc đẩy bởi sự mất mát của một bệnh nhân mà anh ấy điều trị tại một địa điểm tai nạn và phải đối mặt với tin tức bất ngờ rằng Cuddy hiện đã đính hôn, rơi vào vòng xoáy tuyệt vọng và cân nhắc việc điều trị nỗi đau tinh thần và cảm xúc của mình bằng Vicodin, có khả năng thúc đẩy chu kỳ lệ thuộc và nghiện ngập của anh ta lại lặp lại. Nhưng trong một bước ngoặt đáng ngạc nhiên, Cuddy tiết lộ rằng cô đã hủy bỏ lễ đính hôn và thừa nhận với House rằng cô yêu anh ấy, mặc dù ước gì cô không làm vậy. Ngoài ra, Thirteen đã nộp đơn xin nghỉ phép ở bệnh viện, khiến người ta đặt ra câu hỏi về tình trạng sức khỏe của cô. Khi Phần 7 bắt đầu, House và Cuddy cố gắng xây dựng một mối quan hệ thực sự và đối mặt với câu hỏi liệu mối quan hệ mới của họ có ảnh hưởng đến khả năng chẩn đoán bệnh nhân hay không.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 13, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324473);
