INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-nhu-nang', 'Da Như Nắng', 'Skin Like Sun', 'https://phimimg.com/upload/vod/20241231-1/51dec69363ec8cf5e444afa8c45c8aaf.jpg', 'https://phimimg.com/upload/vod/20241231-1/b85118c3e5a09b78396cacefed786c3f.jpg', '<p>Cặp vợ chồng trẻ Wim và Floor ngoài đời thực dành một buổi chiều trong những căn phòng ngập nắng của một ngôi nhà đổ nát ở Bỉ. Theo một cách độc đáo, bộ phim tài liệu khiêu dâm mang tính nghệ thuật này được biên tập gần như theo thời gian thực. Trong sự chậm rãi, chúng ta có được sự rắn chắc, ngọt ngào và gợi cảm. Hãy quên đi việc chỉnh sửa nhanh bằng ngón tay. Chậm là ở chỗ đó.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Wim van Damme","avatar":""},{"name":"Floor Wyns","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Skin. Like. Sun.","肌肤如阳光","스킨 라이크 썬","Des jours plus belles que la nuit"]', 1784690324473);
