INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-cung-day-song', 'Hoàng Cung Dậy Sóng', 'Dong Yi', 'https://phimimg.com/upload/vod/20241011-1/2451c69591478c7c2ec166d7d0c46c22.jpg', 'https://phimimg.com/upload/vod/20241011-1/e14bc48bb8d8dba8769b3be42dae1c16.jpg', '<p>Lấy bối cảnh dưới thời trị vì của Vua Sukjong thuộc triều đại Joseon, câu chuyện tập trung vào Dong Yi, một cung nữ nhận được sự tin tưởng của Hoàng hậu Inhyeon và sau đó được nhà vua sủng ái khi ông cảm động trước những lời cầu nguyện của cô cho sức khỏe của Hoàng hậu trong thời gian trị vì. những tranh chấp tại tòa án do Jang Hee Bin gây ra. Dong Yi trở thành vợ lẽ với cấp bậc sook-bin và sinh ra một người con trai sau này trở thành vị vua thứ 21 của Joseon, Yeongjo.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 11, 2010, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"한효주","avatar":""},{"name":"박하선","avatar":""},{"name":"정동환","avatar":""},{"name":"지진희","avatar":""},{"name":"이소연","avatar":""},{"name":"배수빈","avatar":""},{"name":"정진영","avatar":""},{"name":"김유정","avatar":""},{"name":"이광수","avatar":""},{"name":"Kim Dong-yoon","avatar":""},{"name":"여현수","avatar":""},{"name":"오연서","avatar":""},{"name":"최철호","avatar":""},{"name":"남다름","avatar":""},{"name":"정유미","avatar":""},{"name":"Kwon Hae-sung","avatar":""},{"name":"Kim Woo-seok","avatar":""},{"name":"박정수","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["دونگ یی","Dong Lee","Dong Yi","同伊","동이","Jewel in the Crown"]', 1784690324473);
