INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-danh-cap-giac-mo', 'Kẻ Đánh Cắp Giấc Mơ', 'Inception', 'https://phimimg.com/upload/vod/20231018-1/ea2205d6cdedccf1251422eb4fa85f6d.jpg', 'https://phimimg.com/upload/vod/20231018-1/d0ccc81540ff2c85cecbf73dda05728f.jpg', '<p>Cobb đánh cắp thông tin từ các mục tiêu của mình bằng cách đi vào giấc mơ của họ. Saito đề nghị xóa sạch tiền án của Cobb như một khoản thanh toán cho việc thực hiện hành vi đầu tiên đối với con trai của đối thủ cạnh tranh ốm yếu của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Elliot Page","avatar":""},{"name":"Dileep Rao","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Tohoru Masamune","avatar":""},{"name":"Taylor Geare","avatar":""},{"name":"Claire Geare","avatar":""},{"name":"Johnathan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324473);
