INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-tien-rang', 'Chàng Tiên Răng', 'Tooth Fairy', 'https://phimimg.com/upload/vod/20231107-1/36cc04285789271d2d0840a9a945bee3.jpg', 'https://phimimg.com/upload/vod/20231107-1/b50c35e089b93a3842a48ad6bee8b722.jpg', '<p>Khi vận động viên khúc côn cầu hạng nhỏ Derek Thompson - người có sở thích đánh gãy răng đối thủ mỗi khi thi đấu - khiến một người hâm mộ vỡ mộng, anh ta bị kết án cấm thi đấu một tuần với tư cách là một người chân chính, ăn mặc chỉnh tề, chân chính. -life tiên răng. Chẳng mấy chốc, Derek được truyền cảm hứng để thắp lại những giấc mơ thời trẻ của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Ryan Sheckler","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Destiny Whitlock","avatar":""},{"name":"Chase Ellison","avatar":""},{"name":"Darien Provost","avatar":""},{"name":"Alex Ferris","avatar":""},{"name":"Nicole Muñoz","avatar":""},{"name":"Brendan Meyer","avatar":""},{"name":"Josh Emerson","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Dan Joffre","avatar":""},{"name":"Ellie Harvie","avatar":""},{"name":"Barclay Ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324473);
