INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-quoc', 'Tam Quốc', 'Three Kingdoms', 'https://phimimg.com/upload/vod/20240830-1/8a15cf1f042ac8a876870c7f49d0d3b4.jpg', 'https://phimimg.com/upload/vod/20240830-1/fed61e8483edccce93a0a1b9110c6c56.jpg', '<p>Phim xoay quanh quá trình hình thành và phát triển theo thế chân vạc giữa ba nước với các nhân vật chủ đạo như Gia Cát Lượng, Tào Tháo, Lưu Bị, Tôn Quyền, Chu Du, Tư Mã Ý… đan xen về những mâu thuẫn trong việc tranh giành ngôi thứ trong gia đình họ Tào; những rắc rối tính ái giữa Tào Phi, Tào Thực và nàng Chân Phi với những bất đồng chiến lược, những cuộc chiến tài trí giữa Gia Cát Lượng và Lưu Bị, giữa Chu Du và Tôn Quyền...</p>', 'Hoàn Tất (95/95)', 95, 'series', 'completed', 41, 2010, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"陳建斌","avatar":""},{"name":"于和偉","avatar":""},{"name":"陆毅","avatar":""},{"name":"于荣光","avatar":""},{"name":"Kang Kai","avatar":""},{"name":"聶遠","avatar":""},{"name":"倪大红","avatar":""},{"name":"Yu Bin","avatar":""},{"name":"Victor Huang","avatar":""},{"name":"Zhang Bo","avatar":""},{"name":"许文广","avatar":""},{"name":"Huo Qing","avatar":""},{"name":"Du Xudong","avatar":""},{"name":"Li Jianxin","avatar":""},{"name":"Kang Qunzhi","avatar":""},{"name":"邵峰","avatar":""},{"name":"Li Yixiao","avatar":""},{"name":"Yang Guang","avatar":""},{"name":"Wang Xinjun","avatar":""},{"name":"Liu Ya Jin","avatar":""},{"name":"Wang Di","avatar":""},{"name":"Liu Kui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827