INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-linh-soi-xam', 'Thủ Lĩnh Sói Xám', 'Alpha and Omega', 'https://phimimg.com/upload/vod/20231103-1/15a551e0a1ad48a18d404472014e0960.jpg', 'https://phimimg.com/upload/vod/20231103-1/84572c8c850bfbc7608f0fca8c581935.jpg', '<p>Thủ Lĩnh Sói Xám - Alpha and Omega lấy bối cảnh công viên quốc gia Jasper (Canada) với các dãy núi là nơi sinh sống của một bầy sói kỳ lạ. Khi Kate - thủ lĩnh mới của nhóm sói Alpha và Humphrey - thủ lĩnh nhóm sói Omega bị các nhân viên kiểm lâm công viên tóm gọn và đưa đi, cả hai phải bắt đầu trên một hành trình đáng kinh ngạc để về nhà. Dù là đối thủ \</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Long","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Larry Miller","avatar":""},{"name":"Eric Price","avatar":""},{"name":"Vicki Lewis","avatar":""},{"name":"Chris Carmack","avatar":""},{"name":"Kevin Sussman","avatar":""},{"name":"Brian Donovan","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Elizabeth Tulloch","avatar":""},{"name":"Christine Lakin","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Mela Lee","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324473);
