INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-luther-phan-5', 'Thanh Tra Luther (Phần 5)', 'Luther (Season 5)', 'https://phimimg.com/upload/vod/20240726-1/58c9d8971da9b6fc855c5902ca7ca331.jpg', 'https://phimimg.com/upload/vod/20240726-1/9dcaa40cb1da6c76e2641097ad72b7f4.jpg', '<p>Một thanh tra tận tụy cố gắng kiểm soát đời tư của mình trong khi phải đối phó với các yếu tố tâm lý ẩn giấu trong những vụ án ông đảm nhận.</p>', 'Hoàn Tất (4/4)', 6, 'series', 'completed', 22, 2010, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Hermione Norris","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Patrick Malahide","avatar":""},{"name":"Wunmi Mosaku","avatar":""},{"name":"Enzo Cilenti","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324473);
