INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-mong-bay-cao', 'Ước Mộng Bay Cao', 'Udaan', 'https://phimimg.com/upload/vod/20231101-1/67df83449d3f2f9c07e8ad4c39f6d948.jpg', 'https://phimimg.com/upload/vod/20231101-1/d0be8341a396d31b2bee4047cbd5d2fe.jpg', '<p>Phim Ước Mộng Bay Cao - Udaan 2010: Sau khi trải qua tám năm trong trường nội trú, Rohan trở về thị trấn công nghiệp Jamshedpur bé nhỏ và tìm về căn phòng nhỏ của mình. Nơi có một người cha độc đoán và cậu em trai còn không biết sự tồn tại của anh. Bị buộc phải làm việc trong nhà máy thép của cha mình. Nhưng Rohan vẫn ước mơ trở thành nhà văn và thoát ra khỏi cuộc sống hiện tại.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ronit Roy","avatar":""},{"name":"Rajat Barmecha","avatar":""},{"name":"Aayan Boradia","avatar":""},{"name":"Ram Kapoor","avatar":""},{"name":"Manjot Singh","avatar":""},{"name":"Anand Tiwari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
