INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-3', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 3)', 'Star Wars: The Clone Wars (Season 3)', 'https://phimimg.com/upload/vod/20240624-1/cc787e5813eeefb77ff5cc7f489e310c.jpg', 'https://phimimg.com/upload/vod/20240624-1/82accc100a5fa87bfdc513c344ddd174.jpg', '<p>Bí ẩn, âm mưu và cuộc phiêu lưu đang chờ đợi các anh hùng của chúng ta với những tập phim hành động hoàn toàn mới. Mặt tối càng phát triển mạnh mẽ hơn và các Hiệp sĩ Jedi bị đẩy đến giới hạn. Ranh giới giữa thiện và ác trở nên mờ nhạt khi những bí mật được khám phá, sự thật bị nghi ngờ và các liên minh bị phản bội. Trong phần đầy biến đổi này của Star Wars: The Clone Wars, số phận của thiên hà đang ở thế cân bằng và số phận của Người được chọn cuối cùng sẽ được tiết lộ.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
