INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-tam-ke', 'Mỹ Nhân Tâm Kế', 'Beauty''s Rival In Palace', 'https://phimimg.com/upload/vod/20240829-1/e9a23864d484e9ea5858fd3c107dc3ce.jpg', 'https://phimimg.com/upload/vod/20240829-1/ec5c0270aff83794d1de9c3df2a5a84d.jpg', '<p>Sau khi rời khỏi cung, mẹ con Hương Liên - Vân Tịch bị truy sát đến chết. Vân Tịch may mắn thoát chết do chạy đến được chỗ cậu ngoại mình. Đến khi lớn lên, Vân Tịch được đưa vào cung làm cung nữ. Lữ Hậu, lúc này đã lên ngôi Thái Hậu nhận ra được sự thông minh của nàng nên ra lệnh nàng mang con trai mới sinh của Vương Mỹ Nhân đổi cho Hoàng hậu Trương Yên - cháu ngoại của Lữ Hậu và phong làm Thái Tử.

Sau này, Đại Quốc binh biến, Lữ Hậu lại lo sợ hai mẹ con Bạc Cơ, Lưu Hằng làm phản nên lệnh cho Vân Tịch đổi tên thành Đậu Y Phòng và đưa đến Đại Quốc làm nội gián bằng cách ban hôn với Lưu Hằng. Vì thương sinh thiên hạ và cũng để Lữ Hậu tin tưởng, nàng đã đề nghị với Lưu Hằng tu sửa lăng tẩm bí mật luyện binh. Phu thê cùng trải qua rất nhiều biến cố, tạo thành thiên thu đại nghiệp.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2010, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Trần Kiện Phong","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Lâm Tâm Như","avatar":""},{"name":"Hà Thịnh Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324474);
