INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-14-con-tau-bien-mat-giua-troi-xanh', 'Thám Tử Lừng Danh Conan 14: Con Tàu Biến Mất Giữa Trời Xanh', 'Detective Conan: The Lost Ship in the Sky', 'https://phimimg.com/upload/vod/20231019-1/022510f92c4b2669ac3f85eda70de56b.jpg', 'https://phimimg.com/upload/vod/20231019-1/55af1a6d1152de5bf7d8e506ed7fbb99.jpg', '<p>Sở cảnh sát nhận được thông tin về một vụ nổ ở Viện vi sinh học Tokyo thuộc thành phố Tokyo Nishitama do một nhóm khủng bố mang tên Red Shamu-Neko (Mèo Xiêm Đỏ),và có thể chúng đã lấy đi một loại virus vô cùng nguy hiểm. Trong khi đó, để truy bắt Kid, bác của Sonoko, Suzuki Jirokichi, đã sắp đặt một khí cầu lớn mang tên Bell 3, trên đó có chứa viên đá quý &quot;Thiếu nữ bầu trời&quot;. Nhóm Mori Kogoro và Đội Thám tử nhí cũng được mời tham gia chuyến bay đến Osaka này. Không may,toàn bộ con tàu đã bị bọn khủng bố nói trên áp chế, và đe dọa sẽ cho nổ cả con tàu nếu có ai manh động. Đồng thời, trên tàu đã có người bị trúng độc. Ran cũng có triệu chứng...!? Shinichi xuất hiện...!?Conan cũng được tin Heiji: Cả Osaka đã biết về vụ việc, và ...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2010, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Sawa Ishige","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324474);
