INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-toi-la-ho-ly', 'Bạn Gái Tôi Là Hồ Ly', 'My Girlfriend Is A Gumiho', 'https://phimimg.com/upload/vod/20240814-1/c39c6d808d35208ff20799e6b5366d59.jpg', 'https://phimimg.com/upload/vod/20240814-1/6bc9b9965ebe2f0888cbafabd29573f2.jpg', '<p>Sau khi gặp gỡ một cô gái bí ẩn xinh đẹp, anh chàng đang ôm mộng trở thành ngôi sao phim hành động phát hiện ra cô chính là gumiho – cáo chín đuôi trong truyền thuyết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2010, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이승기","avatar":""},{"name":"신민아","avatar":""},{"name":"노민우","avatar":""},{"name":"박수진","avatar":""},{"name":"변희봉","avatar":""},{"name":"윤유선","avatar":""},{"name":"성동일","avatar":""},{"name":"효민","avatar":""},{"name":"김호창","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
