INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-danh-o-my-phan-1', 'Thành Danh Ở Mỹ (Phần 1)', 'How To Make It In America (Season 1)', 'https://phimimg.com/upload/vod/20240809-1/6a5d72e2497dd3f2310cad43d6e540ce.jpg', 'https://phimimg.com/upload/vod/20240809-1/c19e8d8f0948ee3c66f84d6547979f5c.jpg', '<p>Khi việc kinh doanh ván trượt đi vào bế tắc, nhà thiết kế Ben quyết định đầu tư vào một vụ buôn áo da có vẻ ăn chắc do bạn thân của anh là Cam đề xuất. Tuy nhiên họ mau chóng gặp rắc rối khi anh họ Cam là Rene ra tù và đòi Cam một khoản vay cũ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bryan Greenberg","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Eddie Kaye Thomas","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Edgar Garcia","avatar":""},{"name":"Nick Chinlund","avatar":""},{"name":"Andrea Navedo","avatar":""},{"name":"Tuffy Questell","avatar":""},{"name":"Nicole LaLiberte","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
