INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('de-che-duong-lat-van-phan-1', 'Đế Chế Đường Lát Ván (Phần 1)', 'Boardwalk Empire (Season 1)', 'đế chế đường lát ván (phần 1) boardwalk empire (season 1) steve buscemi kelly macdonald michael shannon shea whigham stephen graham vincent piazza michael kenneth williams paul sparks gretchen mol jeffrey wright ben rosenfield ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quoc-sac-thien-huong', 'Quốc Sắc Thiên Hương', 'Spell of the Fragrance', 'https://phimimg.com/upload/vod/20240802-1/dfe809278aad2a1dad8e70868067691e.jpg', 'https://phimimg.com/upload/vod/20240802-1/026a664b7a66c3b030e78d7914a1f7ae.jpg', '<p>Hương gia và Cung gia là hai gia tộc luyện hương nổi tiếng, luôn đối đầu với nhau để giành vị trí Thiên hạ đệ nhất hương. Thật trùng hợp Hương Hạo Vũ - đại thiếu gia họ Hương, cùng với thiếu gia họ Cung Cung Thiếu Hoa đều đem lòng yêu Tô Vũ Ninh - người con gái điều chế nước hoa bậc nhất Bách Hoa Lĩnh. Điều này khiến cho mâu thuẫn giữa Hương gia và Cung gia càng không thể hóa giải.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Michelle Ye","avatar":""},{"name":"劉愷威","avatar":""},{"name":"He Shengming","avatar":""},{"name":"Qiwen Xu","avatar":""},{"name":"陳曉","avatar":""},{"name":"何賽飛","avatar":""},{"name":"Pan Hong","avatar":""},{"name":"Lv Jiarong","avatar":""},{"name":"Xi Xue","avatar":""},{"name":"Ma Yashu","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
