INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-dam-mau-phan-3', 'Giang Hồ Đẫm Máu (Phần 3)', 'Sons Of Anarchy (Season 3)', 'https://phimimg.com/upload/vod/20231219-1/f1ccab2590d3672cfd397326e36a75f1.jpg', 'https://phimimg.com/upload/vod/20231219-1/c9e6751e1abcba5dd01b7662ca1bb7db.jpg', '<p>Mùa giải này bắt đầu với việc SAMCRO cảm thấy bất lực trước vụ bắt cóc Abel, đặc biệt là Jax, người mà nỗi đau khiến anh rơi vào tình trạng hỗn loạn sâu sắc hơn về tương lai của mình với câu lạc bộ. Cuộc tìm kiếm Abel đưa các chàng trai của chúng ta đến Ireland, nơi Jax không chỉ đối mặt với Quân đội Cộng hòa Ireland mà còn cả một lịch sử cá nhân chưa kể. Trong khi đó, vẫn đang trên xe lam, Gemma phải đối mặt với một tin tức bất ngờ và mạo hiểm tự do của mình để đối phó với nó.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Katey Sagal","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Dayton Callie","avatar":""},{"name":"David Labrava","avatar":""},{"name":"Drea de Matteo","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Niko Nicotera","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
