INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-cuu-muoi', 'Trư Cửu Muội', 'Chun Guang Can Lan Zhu Jiu Mei', 'https://phimimg.com/upload/vod/20240729-1/5b46366e199888ab5e6cbdd224e5f338.jpg', 'https://phimimg.com/upload/vod/20240729-1/d1c9fd817b990e944f2b11afbc9e6e2b.jpg', '<p>Trư Cửu Muội, Tiền Đa Văn, Tôn Chí Quốc, Lý Tăng vốn là Khiếu Thiên chiến sĩ nơi Thượng giới, vì nhiều nguyên nhân mà bị đày xuống trần gian đầu thai làm người. Cự Linh Thần phát hiện Ma giới xâm phạm Trung thổ, để chế ngự chúng, ông tìm 4 vị Khiếu Thiên chiến sĩ nay đã thành phàm nhân, tập hợp thành một nhóm 4 người, tiếp nhận sứ mệnh tìm cách đối phó Ma giới. Trên đường đi họ trải qua nhiều kiếp nạn, cuối cùng luyện thành pháp thuật Cấm giới, thành công bảo vệ hòa bình trị an cho trần gian.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 8, 2010, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Kiều Ân (Trư Cửu Muội)","avatar":""},{"name":"Kiều Nhậm Lương (Tiền Đa Văn)","avatar":""},{"name":"Từ Hải Kiều (Tôn Chí Quốc – Tây Hồ Kiếm Lang)","avatar":""},{"name":"Từ Chấn (Lý Tăng)","avatar":""},{"name":"Ông Hồng (Phi Thiên)","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
