INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tru-cuu-muoi', 'Trư Cửu Muội', 'Chun Guang Can Lan Zhu Jiu Mei', 'trư cửu muội chun guang can lan zhu jiu mei trần kiều ân (trư cửu muội) kiều nhậm lương (tiền đa văn) từ hải kiều (tôn chí quốc – tây hồ kiếm lang) từ chấn (lý tăng) ông hồng (phi thiên) ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-o-sungkyunkwan', 'Chuyện Tình Ở Sungkyunkwan', 'Sungkyunkwan Scandal', 'https://phimimg.com/upload/vod/20240729-1/a4345e9c9afad08a7790ce1ac9d12c8c.jpg', 'https://phimimg.com/upload/vod/20240729-1/ab9b020d611b3845c27cc45bfffa5ce8.jpg', '<p>Sungkyunkwan Scandal (tạm dịch: &quot;Chuyện Tình Ở Sungkyunkwan&quot;) là một bộ phim cổ trang, hài, lãng mạn và tình cảm của Hàn Quốc được trình chiếu trên kênh KBS2 từ ngày 30 tháng 08 đến ngày 2 tháng 11 năm 2010. Kịch bản của phim được phỏng theo cuốn tiểu thuyết ăn khách &quot;Cuộc đời của các nho sinh Sungkyunkwan&quot; (성균관 유생들의 나날: Seongkyunkwan Yusaengdeurui Nanal; The Lives of SungKyunKwan Confucian Scholars) xuất bản năm 2009 của nhà văn Jung Eun Gweol. Phim được quay từ ngày 27 tháng 5 năm 2010 tại phim trường ở tỉnh Gyeonggi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2010, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박민영","avatar":""},{"name":"박유천","avatar":""},{"name":"유아인","avatar":""},{"name":"송중기","avatar":""},{"name":"김갑수","avatar":""},{"name":"이재용","avatar":""},{"name":"안내상","avatar":""},{"name":"김하균","avatar":""},{"name":"김미경","avatar":""},{"name":"김광규","avatar":""},{"name":"서효림","avatar":""},{"name":"Jun Tae-Soo","avatar":""},{"name":"김민서","avatar":""},{"name":"Ryu Dam","avatar":""},{"name":"Joo Ah-sung","avatar":""},{"name":"Lee In","avatar":""},{"name":"이태리","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"