INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-o-sungkyunkwan', 'Chuyện Tình Ở Sungkyunkwan', 'Sungkyunkwan Scandal', 'chuyện tình ở sungkyunkwan sungkyunkwan scandal 박민영 박유천 유아인 송중기 김갑수 이재용 안내상 김하균 김미경 김광규 서효림 jun tae-soo 김민서 ryu dam joo ah-sung lee in 이태리 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-huong-va-duong-ba-ho', 'Thu Hương và Đường Bá Hổ', 'In The Eye Of The Beholder', 'https://phimimg.com/upload/vod/20240719-1/b04a4424b8ee2a1f22f2e776b35f8c7d.jpg', 'https://phimimg.com/upload/vod/20240719-1/e45386f503f72300c18d1457f7a03a53.jpg', '<p>Bức tranh &quot;Cửu Mỹ Đồ&quot; của Đường Bá Hổ (do Trần Hào đóng) còn thiếu một mỹ nhân đặc biệt. Vì thế, tài tử Bá Hổ du sơn ngoạn thủy tìm kiếm mỹ nhân. Tình cờ anh gặp được Thu Hương (do Hồ Hạnh Nhi đóng) – nha hoàn của Hoa phủ. Bá Hổ không chỉ say mê phong thái thu hút mà còn ngưỡng mộ võ công lợi hại của cô. Bá Hổ quyết định vào Hoa phủ làm gia đinh. Anh muốn chinh phục Thu Hương bằng trái tim chân thành chứ không phải dựa vào danh tiếng của bản thân nên đã đổi tên thành Hoa An. Nào ngờ vì nhiều hiểu lầm, Bá Hổ chẳng những không thể lấy lòng người đẹp, ngược lại càng khiến Thu Hương thêm căm ghét. Duy chỉ có lão gia Hoa Hồng Sơn (do Hạ Vũ đóng) là nhìn Bá Hổ bằng cặp mắt khác. Từ lâu, ông đã biết anh không phải người tầm thường. Đường Bá Hổ vô tình vướng vào âm mưu lật đổ hoàng đế của Ninh Vương (do Tăng Vĩ Quyền đóng) và tình yêu đơn phương của quận chúa Chu Đình Ngọc (do Trần Pháp Lai đóng).</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2010, 'Lồng Tiếng', 'FullHD', 'Hồng Kông', 0, '[{"name":"Elaine Yiu","avatar":""},{"name":"黎諾懿","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"胡杏兒","avatar":""},{"name":"陈法拉","avatar":""},{"name":"羅君左","avatar":""},{"name":"夏雨","avatar":""},{"name":"黎耀祥","avatar":""},{"name":"李國麟","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"李成昌","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"姚瑩瑩","avatar":""},{"name":"韓馬利","avatar":""},{"name":"麥長青","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324474);
