INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-cau-chuyen-thoi-trang', 'Barbie: Câu Chuyện Thời Trang', 'Barbie: A Fashion Fairytale', 'https://phimimg.com/upload/vod/20231024-1/71ec5a74286aaab6f1cf0f9db5564d67.jpg', 'https://phimimg.com/upload/vod/20231024-1/6dc60c6cad023bb348624cdd06bb676c.jpg', '<p>Hãy cùng Barbie tham gia vào một câu chuyện cổ tích hiện đại, đầy màu sắc, tràn ngập thời trang, bạn bè và niềm vui! Barbie và chú chó Sequin của cô bay đến thăm ngôi nhà thời trang tuyệt vời của dì cô ở Paris, và cô rất ngạc nhiên khi nó sắp đóng cửa vĩnh viễn. Sau khi phát hiện ra ba Flairies đầy mê hoặc với sức mạnh ma thuật lấp lánh, Barbie nảy ra một ý tưởng tuyệt vời để cứu doanh nghiệp. Cô thậm chí còn truyền cảm hứng cho Alice, một nhà thiết kế thời trang nhút nhát, và họ cùng nhau tạo nên một buổi trình diễn thời trang rực rỡ trên sàn diễn. Barbie cho thấy điều kỳ diệu sẽ xảy ra khi bạn tin vào chính mình.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diana Kaarina","avatar":""},{"name":"Adrian Petriw","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Patricia Drake","avatar":""},{"name":"Alexa Devine","avatar":""},{"name":"Shannon Chan-Kent","avatar":""},{"name":"Maryke Hendrikse","avatar":""},{"name":"Kandyse McClure","avatar":""},{"name":"Britt Irvin","avatar":""},{"name":"Chiara Zanni","avatar":""},{"name":"Kelly Metzger","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Brandy Kopp","avatar":""},{"name":"Charles Fathy","avatar":""},{"name":"Annick Obonsawin","avatar":""},{"name":"Nicole Bouma","avatar":""},{"name":"Nic","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d