INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jonah-hex-ke-song-hai-the-gioi', 'Jonah Hex: Kẻ Sống Hai Thế Giới', 'Jonah Hex', 'https://phimimg.com/upload/vod/20231023-1/edfe42d5ba1ffc46805889d6655a5c77.jpg', 'https://phimimg.com/upload/vod/20231023-1/6b45186146a5e705d383450e1205abc7.jpg', '<p>Tay súng Jonah Hex được Tổng thống Ulysses Grant bổ nhiệm để truy lùng tên khủng bố Quentin Turnbull, một cựu sĩ quan Liên minh miền Nam quyết tâm giải phóng địa ngục trên trái đất. Jonah không chỉ giành được tự do khi nhận nhiệm vụ này mà còn trả thù kẻ đã sát hại vợ con mình.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Brolin","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Aidan Quinn","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Tom Wopat","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Julia Jones","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Rio Hackford","avatar":""},{"name":"Luke James Fleischmann","avatar":""},{"name":"David Jensen","avatar":""},{"name":"Billy B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
