INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-7', 'Lưỡi Cưa 7', 'Saw 3D', 'https://phimimg.com/upload/vod/20231017-1/d83357b59437b1186784e83bccb66a19.jpg', 'https://phimimg.com/upload/vod/20231017-1/a530fd2f557cba9c5733cb04d25d1508.jpg', '<p>Thực hiện bằng công nghệ 3D, Saw VII xoay quanh một nhóm người sống sót khỏi tên sát nhân hàng loạt Jigsaw, đã tập hợp lại để tìm kiếm sự giúp đỡ từ Bobby Dagen - một người ẩn chứa nhiều bí mật đen tối. Nam diễn viên Tobin Bell sẽ trở lại đảm nhận vai kẻ giết người hàng loạt John Kramer/Jigsaw.&nbsp; Đây là tập phim cuối cùng của loạt phim kinh dị hấp dẫn này. Dù nhiều fan hâm mộ dường như vẫn tỏ ra tiếc nuối khi Saw dừng lại ở tập VII nhưng theo các nhà làm phim thì họ thấy “nhiệm vụ của chúng tôi đến đây là hoàn tất. Chúng tôi không muốn thành loại đấu sĩ cứ mãi bám võ đài”. Họ cũng hứa rằng, Saw VII sẽ trả lời những câu hỏi còn bỏ ngỏ từ những tập phim trước - Trò chơi vẫn tiếp diễn.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobin Bell","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Betsy Russell","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Sean Patrick Flanery","avatar":""},{"name":"Chad Donella","avatar":""},{"name":"Chester Bennington","avatar":""},{"name":"Gina Holden","avatar":""},{"name":"Dean Armstrong","avatar":""},{"name":"Naomi Snieckus","avatar":""},{"name":"Oluniké Adeliyi","avatar":""},{"name":"Rebecca Marshall","avatar":""},{"name":"Anne Lee Greene","avatar":""},{"name":"Sebastian Pigott","avatar":""},{"name":"Jon Cor","avatar":""},{"name":"Kevin McGarry","avatar":""},{"name":"Dru","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324474);
