INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luoi-cua-7', 'Lưỡi Cưa 7', 'Saw 3D', 'lưỡi cưa 7 saw 3d tobin bell costas mandylor betsy russell cary elwes sean patrick flanery chad donella chester bennington gina holden dean armstrong naomi snieckus oluniké adeliyi rebecca marshall anne lee greene sebastian pigott jon cor kevin mcgarry dru ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ba-noi-tro-kieu-my-phan-7', 'Những Bà Nội Trợ Kiểu Mỹ (Phần 7)', 'Desperate Housewives (Season 7)', 'https://phimimg.com/upload/vod/20240618-1/fda34777747e4e07413a292146b7e299.jpg', 'https://phimimg.com/upload/vod/20240618-1/76a312d58c8937a51fa20c50d7ce897e.jpg', '<p>Sau khi mất cả chồng và công việc kinh doanh, Bree dần bắt đầu quá trình xây dựng lại cuộc đời mình, đầu tiên bằng cách kể cho bạn cô là Gabrielle một bí mật có thể kết thúc tình bạn của họ, sau đó bắt đầu mối tình lãng mạn với nhà thầu trẻ hơn nhiều tuổi Keith Watson. Trong khi đó, Solises phát hiện ra rằng con gái Juanita của họ đã bị tráo đổi khi mới sinh, và Lynette được bạn cùng phòng thời đại học cũ của cô là Renee Perry (Vanessa Williams), người sau này chuyển đến con đường này vĩnh viễn đến thăm. Bob và Lee tìm đường quay lại với nhau, còn tình hình tài chính của Susan và Mike khiến họ phải chuyển đến một căn hộ trong thành phố và đảm nhận những công việc mà họ không muốn chịu đựng, trong khi Paul Young, người góa vợ của Mary Alice, chuyển đi. quay lại Wisteria Lane để tàn phá.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Teri Hatcher","avatar":""},{"name":"Felicity Huffman","avatar":""},{"name":"Marcia Cross","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Ricardo Chavira","avatar":""},{"name":"Doug Savant","avatar":""},{"name":"James Denton","avatar":""},{"name":"Brenda Strong","avatar":""},{"name":"Vanessa Williams","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
