INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-no-le', 'Săn Nô Lệ', 'The Slave Hunters', 'https://phimimg.com/upload/vod/20240608-1/59f6d7ad987c07ad5f8bc7dcbd50dfee.jpg', 'https://phimimg.com/upload/vod/20240608-1/e9599b038765cbf9034e2e62e59b6612.jpg', '<p>Bộ phim “Săn nô lệ” do KBS sản xuất xoay quanh mối thù không đội trời chung của hai người đàn ông là Lee Dae Gil- kẻ săn nô lệ khét tiếng và Tae Ha. Cả hai người họ đều là những con người tài giỏi, sống có ước mơ và lý tưởng nhưng bị số phận trêu đùa dồn vào ngõ cụt. Hai chàng tuấn kiệt ngang tài, ngang sức này cùng có một ước mơ xây dựng một xã hội tốt đẹp không có áp bức bất công, nhưng họ không nhận ra điều đó cho đến khi Hye Won xuất hiện giữa hai người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2010, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장혁","avatar":""},{"name":"오지호","avatar":""},{"name":"이다해","avatar":""},{"name":"공형진","avatar":""},{"name":"이종혁","avatar":""},{"name":"한정수","avatar":""},{"name":"김지석","avatar":""},{"name":"성동일","avatar":""},{"name":"김하은","avatar":""},{"name":"이한위","avatar":""},{"name":"김응수","avatar":""},{"name":"데니 안","avatar":""},{"name":"안석환","avatar":""},{"name":"윤주희","avatar":""},{"name":"김갑수","avatar":""},{"name":"조희봉","avatar":""},{"name":"조진웅","avatar":""},{"name":"안길강","avatar":""},{"name":"Lee In","avatar":""},{"name":"윤지민","avatar":""},{"name":"윤문식","avatar":""},{"name":"김영옥","avatar":""},{"name":"Ha Si-eun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
