INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-4', 'Gã Điên (Phần 4)', 'Mad Men (Season 4)', 'https://phimimg.com/upload/vod/20240606-1/ea1a943331adb5f2b74e380fb64a7c90.jpg', 'https://phimimg.com/upload/vod/20240606-1/c381dcea2386c4ab85438e0718416947.jpg', '<p>Phần bốn diễn ra từ tháng 11 năm 1964 đến tháng 10 năm 1965. Phim lấy bối cảnh tại công ty quảng cáo mới và hiện đại hơn đáng kể, Sterling Cooper Draper Pryce. Câu chuyện chính của mùa thứ tư được thúc đẩy bởi cuộc khủng hoảng danh tính của Don Draper. Khi Don rơi sâu hơn vào nỗi tuyệt vọng hiện sinh, anh bắt đầu thường xuyên gặp gỡ những người phụ nữ có tư cách đạo đức lỏng lẻo và phải đối mặt với chứng nghiện rượu đến suy nhược.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2010, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
