INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-9-tu-than', 'Số 9 Tử Thần', 'Nine Dead', 'https://phimimg.com/upload/vod/20240228-1/f3e3332a097201dc934597b2fe924d34.jpg', 'https://phimimg.com/upload/vod/20240228-1/b1ed72cfad275932691613bde6b8d60e.jpg', '<p>Giao tiếp là chìa khóa để sống sót cho chín người lạ bị bắt cóc bởi một tay súng đeo mặt nạ và nói rằng một trong số họ sẽ chết cứ sau mười phút cho đến khi họ khám phá ra tất cả họ được kết nối với nhau như thế nào. Ai trong số chín người sống và ai chết?</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melissa Joan Hart","avatar":""},{"name":"John Terry","avatar":""},{"name":"Chip Bent","avatar":""},{"name":"Lawrence Turner","avatar":""},{"name":"Edrick Browne","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
