INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-lay', 'Sa Lầy', 'Hesher', 'https://phimimg.com/upload/vod/20240228-1/696152745a5bd63e0e39425ff32fa6df.jpg', 'https://phimimg.com/upload/vod/20240228-1/79e1ee2f05f59429a3ea772843b08d4b.jpg', '<p>Một cậu bé mồ côi mẹ và mất liên lạc với cha cũng như thế giới xung quanh. Sau đó, anh gặp Hesher, người đã khiến cuộc sống của anh trở nên hỗn loạn hơn.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Audrey Wasilewski","avatar":""},{"name":"Monica Staggs","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
