INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sa-lay', 'Sa Lầy', 'Hesher', 'sa lầy hesher joseph gordon-levitt natalie portman rainn wilson audrey wasilewski monica staggs ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-he-nong-bong', 'Ngày Hè Nóng Bỏng', 'Hot Summer Days', 'https://phimimg.com/upload/vod/20240227-1/5a4d8d01c18d2c5616f4c1c9082b75e3.jpg', 'https://phimimg.com/upload/vod/20240227-1/77618bd762d2d1e6217ffceb1211de59.jpg', '<p>Bộ phim là câu chuyện tình yêu của 3 cặp đôi : Tình Yêu Đuổi Bắt = Ngô Ngạn Tổ + Từ Nhược Tuyên : Trong một nhà hàng sushi, đầu bếp và thực khách cùng nhìn vào một món ăn, giữa cả hai có rất nhiều lời không thể nói. Họ không biết cách để thể hiện tâm sự của mình cho người kia. Họ đã từng yêu nhau từ rất lâu thế nhưng khi đó anh chỉ bàn tay trắng. Anh đã xa cô để tới Nhật Bản học tập, khi trở về anh đã có thể mở một nhà hàng của riêng mình. Thế nhưng khi gặp lại cô, anh lại một lần nữa từ chối tình yêu của cô. Tình Yêu Trong Sáng = Tỉnh Bách Nhiên + Dương Dĩnh : Trong một nhà máy, chàng công nhân trẻ cá với ông chủ rằng mình sẽ “cưa đổ” cô nàng hoa khôi của nhà máy. Và cô nàng cũng quyết định “chơi” lại với một lời thách thức rằng nếu chàng trai mà đứng ngoài nhà máy 100 ngày thì cô sẽ đồng ý hẹn hò cùng anh. Và rồi khi mọi việc sắp kết thúc, “người đẹp” sẽ chọn gì ? Tiền bạc hay tình yêu. Tình yêu “lừa gạt” = Trương Học Hữu + Lưu Nhược Anh : Sau một tai nạn, cả hai cùng nằm trong bệnh viện. Và bởi một tin nhắn nhầm, họ có mối liên hệ với nhau. Anh nói anh là một tay đua xe mặc dù chỉ là một chàng lái xe tải thuê còn cô thì nói cô là một nghệ sĩ piano dù cho cô là nhân viên tiệm mát xa. Tình yêu đến với họ, chỉ cho đến khi những điều giả dối cả hai dựng nên sụp đổ, lột trần bộ mặt thật của họ. Tuy nhiên tình yêu đó không hề mất đi mà điều này lại khiến cả hai gần nhau hơn...</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tạ Đình Phong","avatar":""},{"name":"Trương Học Hữu","avatar":""},{"name":"Rene Liu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
