INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('natalie', 'Natalie', 'Natalie', 'https://phimimg.com/upload/vod/20240227-1/53d270d4d554ea07ce9f3ca4d679202f.jpg', 'https://phimimg.com/upload/vod/20240227-1/c6a175e3c5e297aa678da0abe8f9578d.jpg', '<p>Những người đã xây dựng một bức tường xung quanh mình. Nhà điêu khắc Jun-hyeok, nhà phê bình nghệ thuật Min-woo và sinh viên múa hiện đại Mi-ran. Một bộ phim tình cảm bí ẩn về tình yêu và những bí mật của ba người.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-jae","avatar":""},{"name":"Kim Ji-hun","avatar":""},{"name":"Hyeon-jin","avatar":""},{"name":"Kim Gi-yeon","avatar":""},{"name":"Kang Jin-joo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
