INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-vu-tru-3', 'Chiến Binh Vũ Trụ 3', 'Universal Soldier: Regeneration', 'https://phimimg.com/upload/vod/20240220-1/8df0bf72f5268656de3b981917d0076c.jpg', 'https://phimimg.com/upload/vod/20240220-1/05586d6b0104943388659d739769b8fd.jpg', '<p>Khi bị các thế lực khủng bố đe dọa sẽ gây ra thảm họa hạt nhân, hy vọng duy nhất của thế giới phụ thuộc vào việc thiết lập lại hoạt động của Chiến binh Vũ Trụ đã bị vứt xó từ lâu Luc Deveraux. Được trang bị vũ khí tối tân và lập trình mới hoàn toàn, Deveraux đã sẵn sàng đối mặt với kẻ thù không đội trời chung của mình từ phần trước trong Universal Soldier, cùng một thế hệ người máy thứ hai mang tên UniSol...</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Andrei Arlovski","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
