INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ramona-va-beezus', 'Ramona Và Beezus', 'Ramona And Beezus', 'https://phimimg.com/upload/vod/20240219-1/9bb551bdc3f7f862be21d1acb8bb5ee5.jpg', 'https://phimimg.com/upload/vod/20240219-1/5f2994ffb373f924aefa1d67c454160c.jpg', '<p>Ramona là một đứa trẻ dễ thương, đang học lớp ba. Cô bé có một trí tưởng tượng cực kì phong phú, một nguồn năng lượng không bao giờ cạn kiệt và những trò “phá phách” thọat nhìn thì có vẻ giống như những tai nạn vậy. Ramona rất thích chọc khoáy mọi người, kể cả người chị lớn của mình Beezus. Beezus thì đang cố tìm mọi cách để kéo được anh chàng dễ thương Henry đi chơi với mình. Tuy nhiên, Ramona sẽ phải sử dụng những trò tinh nghịch, láu cá của mình để giữ lại mái ấm của gia đình cô bé trước khi mọi việc quá trễ. Đây là một bộ phim nhẹ nhàng, hài hước rất thích hợp cho mọi lứa tuổi và xem cùng gia đình.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey King","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Bridget Moynahan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
