INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-khung-hoang-kinh-te', 'Cuộc Khủng Hoảng Kinh Tế', 'Inside Job', 'https://phimimg.com/upload/vod/20240207-1/27e6c36bd628c8790e1bcf2d6117f54b.jpg', 'https://phimimg.com/upload/vod/20240207-1/2313d938ff069872d97c139bf7ac7c99.jpg', '<p>Cuộc khủng hoảng tài chính toàn cầu diễn ra vào mùa Thu năm 2008 đã gây ra hàng triệu người mất việc làm và nhà cửa và đẩy Hoa Kỳ vào một cuộc suy thoái kinh tế sâu sắc. Matt Damon thuật lại một bộ phim tài liệu cung cấp một cuộc kiểm tra chi tiết về các yếu tố dẫn đến sự sụp đổ và xác định những người chơi chính về tài chính và chính trị. Giám đốc Charles Ferguson thực hiện một loạt các cuộc phỏng vấn và theo dõi câu chuyện từ Hoa Kỳ, Trung Quốc đến Iceland đến một số điểm nóng tài chính toàn cầu khác.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"William Ackman","avatar":""},{"name":"Barack Obama","avatar":""},{"name":"George W. Bush","avatar":""},{"name":"Jonathan Alpert","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324474);
