INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-toc-may', 'Công Chúa Tóc Mây', 'Tangled', 'https://phimimg.com/upload/vod/20240207-1/324221f6c3c1ff99dae0bafcfecc9c5e.jpg', 'https://phimimg.com/upload/vod/20240207-1/1732c7ab82d0f01710bd852e92a82f77.jpg', '<p>Rapunzel tóc dài kỳ diệu đã dành toàn bộ cuộc sống của mình vào một tòa tháp, nhưng bây giờ một tên trộm runaway đã vấp ngã trên cô, cô sẽ phát hiện ra thế giới lần đầu tiên, và cô thực sự là ai.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
