INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-hu-vo', 'Lạc Vào Hư Vô', 'Enter The Void', 'https://phimimg.com/upload/vod/20240205-1/3f925e3e0480a04e627c1d0bb88bf708.jpg', 'https://phimimg.com/upload/vod/20240205-1/988e4d12f256f4477bc9e4b1a678fd74.jpg', '<p>Oscar và Linda là 2 anh em ruột sống ở Tokyo, Oscar làm trung gian bán ma túy, còn Linda múa thoát y ở một night club. Trong một lần bị cảnh sát mai phục và truy bắt, Oscar bị bắn chết. Và sau đó cậu như tan vào hư vô, biến thành một hồn ma, nhưng vẫn vật vờ ở Tokyo theo dõi em gái mình cùng những chuyện xảy ra sau cái chết của mình...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nathaniel Brown","avatar":""},{"name":"Paz de la Huerta","avatar":""},{"name":"Cyril Roy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
