INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-so-tinh-yeu', 'Ẩn Số Tình Yêu', 'Valentine''s Day', 'https://phimimg.com/upload/vod/20240205-1/dd9118672ef7991412f330f999e8e4ad.jpg', 'https://phimimg.com/upload/vod/20240205-1/6704fbe90adb950ed2d3daf0adacf941.jpg', '<p>Quy tụ nhiều diễn viên đình đám của Hollywood, phim là những câu chuyện tình lãng mạn ở thành phố Los Angeles phồn hoa, vào đúng dịp Lễ tình nhân. Mỗi câu chuyện, mỗi cặp đôi, mỗi tình tiết, đều như những mảng màu tô điểm cho bức tranh tình yêu nhiều màu sắc trong ngày Valentine.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Alba","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Jessica Biel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
