INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hunt-to-kill', 'Hunt To Kill', 'Hunt To Kill', 'https://phimimg.com/upload/vod/20240207-1/efa3156ddca4f030c369719a5ca1515f.jpg', 'https://phimimg.com/upload/vod/20240207-1/9623a8ff4a4e87d790272c6755c74c71.jpg', '<p>Jim Rhodes, một đặc vụ Tuần tra Biên giới Hoa Kỳ, một người đã ly hôn khó khăn để thương tiếc cho sự ra đi của người bạn đời bị sát hại trong khi vất vả nuôi dạy đứa con gái nổi loạn của mình ở vùng núi Montana. Nhưng khi một nhóm những kẻ đào tẩu vui vẻ bắt Rhodes và con gái của anh ta làm con tin, một vùng hoang dã hiểm trở sẽ bùng nổ trong sự báo thù trên mọi địa hình. Có con vật nào bị thương nguy hiểm hơn một người làm luật để chết không? Daniels thể hiện một trong những nhân vật phản diện.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Austin","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Marie Avgeropoulos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
