INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-unjust', 'The Unjust', 'The Unjust', 'https://phimimg.com/upload/vod/20240228-1/06458a95e62113f96f80cf75344ac9eb.jpg', 'https://phimimg.com/upload/vod/20240228-1/88ba6676500e32b6d815385ad5be3029.jpg', '<p>Một tên giết người hàng loạt nhằm vào những nữ sinh vẫn đang nhởn nhơ ngoài vòng pháp luật – đã có 5 nạn nhân được xác định, khiến cho cả Tổng thống cũng phải vào cuộc. Khi kẻ tình nghi lớn nhất của vụ án chết trong khi bị bắt và vụ án tưởng như đã bế tắc, những cảnh sát cấp cao quyết định tạo ra tên giết người. Dù Đại úy Choi Cheol Gi lấy làm kiêu hãnh vì bắt được rất nhiều tội phạm trong sự nghiệp cảnh sát của mình, tuy nhiên cấp bậc của anh ấy lại không thể hiện điều đó. Vì thế Đại úy Choi đã bị sắp đặt và giáng chức bởi một tội khác, anh đã quyết định đây là cơ hội cuối cùng của mình để lấy lại những gì đáng lẽ ra thuộc về mình. Anh đã thỏa thuận với ông trùm của một băng nhóm - Jang Seok ...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryoo Seung-bum","avatar":""},{"name":"Hwang Jung-min","avatar":""},{"name":"Yu Hae-jin","avatar":""},{"name":"Ma Dong-seok","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324474);
