INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-hanh-huong', 'Chuyến Hành Hương', 'The Way', 'https://phimimg.com/upload/vod/20240228-1/1032e8a97e2d8d3f4c201289315e62cb.jpg', 'https://phimimg.com/upload/vod/20240228-1/622a54702b71f6357981d9cd12322e36.jpg', '<p>Khi con trai ông qua đời khi đang đi bộ trên tuyến đường hành hương Camino de Santiago nổi tiếng ở Pyrenees, Tom bay đến Pháp để nhận hài cốt. Để tìm hiểu sâu hơn về cuộc sống của đứa con bị ghẻ lạnh của mình, anh quyết định hoàn thành chuyến đi leo núi dài 500 dặm tới Tây Ban Nha. Tom sớm tham gia cùng những du khách khác và nhận ra rằng tất cả họ đang tìm kiếm thứ gì đó.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Sheen","avatar":""},{"name":"Emilio Estevez","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Yorick van Wageningen","avatar":""},{"name":"James Nesbitt","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Ángela Molina","avatar":""},{"name":"Carlos Leal","avatar":""},{"name":"Simón Andreu","avatar":""},{"name":"Eusebio Lázaro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
