INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-choi-cua-quy', 'Sân Chơi Của Quỷ', 'Devil''s Playground', 'https://phimimg.com/upload/vod/20240227-1/6e4ed24b4c703b58515c99e11a595d77.jpg', 'https://phimimg.com/upload/vod/20240227-1/910511799fa32981cdd121d3009bfb79.jpg', '<p>Khi thế giới không chống chọi được với ngày tận thế thây ma, Cole - một lính đánh thuê cừ khôi - đang truy đuổi một người có thể đưa ra phương pháp chữa trị. Không chỉ đối với bệnh dịch mà còn đối với số phận đương nhiệm của Cole.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"MyAnna Buring","avatar":""},{"name":"Danny Dyer","avatar":""},{"name":"Craig Fairbrass","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Colin Salmon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
