INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-chien-sat-ma-tran', 'Quyết Chiến Sát Mã Trấn', 'Welcome To Shamatown', 'https://phimimg.com/upload/vod/20240207-1/7103fe73b2a806553c1981edd0d7e2cc.jpg', 'https://phimimg.com/upload/vod/20240207-1/1063ea03d8282d0574e8d2ca931e7bdf.jpg', '<p>Truyền thuyết kể rằng, rất nhiều bảo vật được giấu tại Sát Mã Trấn - một ngôi làng phía tây nam Trung Quốc. Để cải thiện cuộc sống của dân làng, Đường Cao Bằng, thủ lĩnh ở đây, quyết định biến Sát Mã thành khu du lịch cho những người mê đồ cổ. Ông đã thu lượm những đồ vật cũ của dân làng, và giới thiệu trên một chương trình truyền hình về đồ cổ. Tuy nhiên, hành động của ông không thu hút được những vị khách du lịch mà lại khiến cho những kẻ buôn bán bất hợp pháp để mắt tới ngôi làng này...</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bei-Er Bao","avatar":""},{"name":"Bingkun Cao","avatar":""},{"name":"Yuen Che","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
