INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-vo-yeu', 'Giả Vờ Yêu', 'Club Friday The Series 11: Ruk Nok Kot', 'https://phimimg.com/upload/vod/20240118-1/f60b048f70d51598d79d158d3326708a.jpg', 'https://phimimg.com/upload/vod/20240118-1/b0fabae279c432e5010eeab0a6139097.jpg', '<p>kể về Sin, vốn được sinh ra trong một gia đình thuộc tầng lớp bình dân. Ba cô là một người nghiêm khắc, nuôi dạy con cái một cách bảo thủ. Vì vậy cô luôn có khao khát mãnh liệt là nhanh chóng làm chủ cuộc đời của mình. Bất chấp sự phản đối của cha mẹ, cô đã lựa chọn và kết hôn với một gã chồng tồi bởi vì ban đầu cô nghĩ tình yêu đó sẽ mau chóng giải phóng cô khỏi gia đình. Tuy nhiên cuộc hôn nhân sớm đổ vỡ, và nhiều biến cố lần lượt đến với cuộc đời của Sin.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 19, 2010, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Pat Napapa Thantrakul","avatar":""},{"name":"Aun Witaya Wasukraipaisarn","avatar":""},{"name":"Not Vorarit Fuangarome","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
