INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chap-but', 'Người Chấp Bút', 'The Ghost Writer', 'https://phimimg.com/upload/vod/20240207-1/2b26ef3804e63392ea0c681777252268.jpg', 'https://phimimg.com/upload/vod/20240207-1/80d9f353ce551616109de2b5ead28002.jpg', '<p>“The Ghost Writer” là câu chuyện về một người chấp bút (Ewan McGregor) cho hồi ký của cựu thủ tướng Anh Adam Lang (Pierce Brosnan). Dự án có vẻ như là một việc để đời cho người chấp bút đã nhuốm màu sắc bi kịch khi một người trợ lý lâu năm của thủ tướng bị chết trong một tai nạn khó hiểu.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Tom Wilkinson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
