INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-co-doc-cua-abby', 'Sự Cô Độc Của Abby', 'Let Me In', 'https://phimimg.com/upload/vod/20240207-1/a24d444c5d28a29f731a232dc5c9d540.jpg', 'https://phimimg.com/upload/vod/20240207-1/8e6263c7455dc36841ff4b43190b8e25.jpg', '<p>Câu chuyện phim xảy ra tại New Mexico, một thị trấn yên tĩnh và đang bị ám ảnh bởi một điều xấu xa. Người dân nơi đây được nhà chức trách yêu cầu phải báo cáo cho họ bất kỳ hoạt động đáng ngờ nào. Trong thị trấn có cậu bé Owen thường xuyên bị các bạn cùng lớp bắt nạt và bị bỏ rơi vì cha mẹ đã ly dị. Owen sống bên cạnh một cô bạn hàng xóm mới tên là Abby, một cô bé rất bí ẩn, có vẻ yếu đuối và đầy rắc rối, cùng độ tuổi với Owen...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Richard Jenkins","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
