INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy', 'Ác Quỷ', 'Devil', 'https://phimimg.com/upload/vod/20240207-1/bac8e32a17bc32e4e41ba2e7b5e363d7.jpg', 'https://phimimg.com/upload/vod/20240207-1/0263a29c5627a10f207c242c1b3661fc.jpg', '<p>Câu chuyện xoay quanh một nhóm người bị mắc kẹt tại một thang máy trong một tòa nhà. Ban đầu, họ đều cho rằng đó là một tai nạn. Nhưng sau đó họ hoảng sợ phát hiện ra rằng việc này được gây ra bởi một linh hồn ma quỷ đang ngụy trang thành một trong năm người ở thang máy. Hoảng loạn, nhóm người bắt đầu nghi ngờ lẫn nhau và cố tìm cách thoát khỏi nơi đáng sợ trên.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Messina","avatar":""},{"name":"Caroline Dhavernas","avatar":""},{"name":"Bokeem Woodbine","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
