INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-khoi-tinh', 'Hương Khói Tình', 'Love In A Puff', 'https://phimimg.com/upload/vod/20240205-1/c74e9cce00a24d4fc022cc3d94b83237.jpg', 'https://phimimg.com/upload/vod/20240205-1/c2013284fff19a1606d1f8f95c71f1ed.jpg', '<p>Một phim hài lãng mạn có đề tài vô cùng mới mẻ. Bộ phim bắt đầu khi nhà nước Hồng Kông chính thức ban hành luật lệ cấm hút thuốc ở những nơi công cộng. Việc này dẫn đến hiện tượng là các nhân viên văn phòng thường hay tụ tập lại ở một chỗ nào đó để hút thuốc. Chính ở đó, các nhân viên trở nên gần gũi và thân quen hơn, cùng nói chuyện về cuộc sống cũng như công việc. Tình yêu của hai nhân viên văn phòng Chí Minh và Xuân Kiều cũng dần dần phát sinh ở nơi đó.\r\n</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Thiên Hoa","avatar":""},{"name":"Dư Văn Lạc","avatar":""},{"name":"Trương Minh Đạt","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
