INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-thanh-huyen-thoai', 'Trở Thành Huyền Thoại', 'Legendary', 'https://phimimg.com/upload/vod/20240205-1/409c0fe0557f86e3bab5aab3c14f2aec.jpg', 'https://phimimg.com/upload/vod/20240205-1/ea8513f3bd291cd654710f61efedb029.jpg', '<p>Trở Thành Huyền Thoại - Legendary xoay quanh hành trình ly kỳ tìm kiếm người thân của một thiếu niên thông minh, ham đọc sách. Anh chàng đã tham gia đội đấu vật của trường mình với mục đích tìm lại người thân trong gia đình bị thất lạc sau cái chết của cha anh - một huyền thoại đô vật ở trường đại học 10 năm trước đây.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Glover","avatar":""},{"name":"John Cena","avatar":""},{"name":"Patricia Clarkson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
