INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-thanh-huyen-thoai', 'Trở Thành Huyền Thoại', 'Legendary', 'trở thành huyền thoại legendary danny glover john cena patricia clarkson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-wall-2-dong-tien-khong-ngu', 'Phố Wall 2: Đồng Tiền Không Ngủ', 'Wall Street: Money Never Sleeps', 'https://phimimg.com/upload/vod/20240205-1/76b294f09c579fa8f197887676c53a1e.jpg', 'https://phimimg.com/upload/vod/20240205-1/d655cbb139cbdd38977725468c4a3b8f.jpg', '<p>Gordon Gekko (Michael Douglas) từng là một huyền thoại trên thị trường chứng khoán phố Wall nhưng sau những gian lận về tài chính cùng mánh khóe rửa tiền tinh vi, ông bị tòa án xử 8 năm tù giam. Trong cái ngày được thả tự do, không một ai, dù là cô con gái Winnie (Carey Mulligan), đồng nghiệp, bạn bè năm xưa đến đón Gordon. Suốt một thời gian dài sau đó, ông tập trung tâm trí viết sách và cho ra đời cuốn Liệu lòng tham có tốt?. Kinh nghiệm, sự ảnh hưởng trên thị trường, cùng các mối quan hệ cũ và đặc biệt là bài diễn văn của Gordon tại trường đại học đã tác động mạnh mẽ tới Jake Moore (Shia LaBeouf), một thương nhân trẻ tuổi đang gặp khó khăn về tài chính. Ngân hàng mà Jake đang làm việc bắt đầu lâm vào khủng hoảng nghiêm trọng. Để cứu lấy sự nghiệp của người thầy Louis Zabel khỏi món nợ khổng lồ lên đến hàng tỷ đô la, không còn cách nào khác, anh phải tìm tới sự giúp đỡ của Gordon. Bù lại, Jake hứa sẽ hàn gắn lại mối quan hệ giữa Gordon và Winnie, người vợ chưa cưới của anh cũng là con gái ông. Nhưng liệu Gordon có thực sự thay đổi, liệu còn có âm mưu nào đứng đằng sau mọi sự việc? Mặc dù đã có nhiều thay đổi trong phong cách nhưng cũng giống như các tác phẩm khác của Oliver Stone, Wall Street: Money Never Sleeps không dành cho đại đa số khán giả. Có lẽ, Wall Street: Money Never Sleeps hấp dẫn nhất đối với những ai làm về lĩnh vực tài chính, chứng khoán. Bộ phim đi sâu khai thác từng ngóc ngách trong thị trường phố Wall, cách nó vận hành, cách chính phủ cùng các ngân hàng tìm cách thoát khỏi cuộc khủng hoàng tài chính toàn cầu hồi cuối năm 2008. Oliver Stone sử dụng rất nhiều hình ảnh lẫn câu thoại ẩn dụ suốt từ đầu tới cuối phim để mô tả điều này như hiệu ứng domino, những quả bong bóng xà phòng dễ vỡ bay trên không trung, ánh đèn trên những tòa nhạc cao ốc trọc trời..</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Carey Mulligan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
