INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-noi-loan', 'Thiếu Nữ Nổi Loạn', 'The Runaways', 'https://phimimg.com/upload/vod/20240128-1/850128f7879d525e07e791fa877fb946.jpg', 'https://phimimg.com/upload/vod/20240128-1/706681525f598d87751d0437bbea9dea.jpg', '<p>“The Runaways” là một bộ phim về 1 nhóm nhạc rock của các cô gái trẻ thập niên 1970. Joan Jett và Cherie Currie, những cô gái nổi loạn và bất trị ở miền nam California, trở thành những ngôi sao nhạc rock của một nhóm nhạc huyền thoại - những người đã lát những viên gạch đầu tiên cho những thế hệ nối tiếp của các nhóm nhạc nữ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Michael Shannon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
