INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-sat-thu', 'Yêu Nhầm Sát Thủ', 'Killers', 'https://phimimg.com/upload/vod/20240128-1/bd0d0a7971710b4b70ef196059d99c84.jpg', 'https://phimimg.com/upload/vod/20240128-1/ab068474d55db7af7a9cbc9ae216b073.jpg', '<p>Sốc vì bị người yêu đá, Jennifer dọa bố mẹ sẽ uống thuốc tự tử. Không nỡ nhìn thấy con gái đau khổ, cha của Jennifer, ông Kornfeldt, một nhân viên mật vụ ở Washington đã cho vợ và con gái đi cùng mình trong một chuyến công tác đến Pháp. Tại một bờ biển tuyệt đẹp ở Pháp, Jennifer đã tình cờ gặp Spencer - một anh chàng cực kỳ hấp dẫn và ga lăng. Ngay phút đầu tiên gặp Spencer, Jennifer đã nhận ra Spencer chính là người đàn ông hoàn hảo mà cô hằng mong ước. Vì vậy, bằng mọi cách Jennifer quyết tâm hạ gục “mục tiêu” điển trai này. Thế nhưng, điều mà Jennifer không ngờ tới là Spencer - “người đàn ông vạn người mê” của cô lại là một điệp viên, một tay sát thủ ngầm của chính phủ...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katherine Heigl","avatar":""},{"name":"Ashton Kutcher","avatar":""},{"name":"Tom Selleck","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
