INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-man-hien-ni-thi', 'Nguyệt Mãn Hiên Ni Thi', 'Crossing Hennessy', 'https://phimimg.com/upload/vod/20240128-1/26dc4e6f62fa3fb38f735396690bb41b.jpg', 'https://phimimg.com/upload/vod/20240128-1/7bb42a071868be14fa11d1db9f3e63b0.jpg', '<p>Hennessy không phải là một con sông hay một cây cầu, mà là một con phố chính ở quận Loan Tư của Hồng Kông. Đó là nơi Loy giúp bà Chiang – bà mẹ hà khắc góa chồng của anh, mở một cửa hàng đồ điện. Phía cuối con phố, Oi Lin làm việc cho cửa hàng kinh doanh thiết bị vệ sinh của chú mình. Cả hai có liên hệ với nhau theo một cách nào đó, bởi anh chàng người yêu Xu đỏm dáng hay trăng hoa của Oi Lin đang ở trong tù, trong khi Loy thỉnh thoảng quan hệ với người vợ vừa ly dị của mình. Bất đắc dĩ gặp nhau trong một cuộc xem mặt do những người họ hàng nhiều chuyện sắp đặt, họ tiếp tục cuộc chơi để làm vừa lòng người thân. Và khi bắt đầu hiểu nhau hơn, họ nhận ra rằng dù khoảng cách địa lý rất gần, nhưng để tiến thêm một bước về phía tình yêu thì phải có dũng khí của cả một đời người.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Trương Học Hữu","avatar":""},{"name":"Wei Tang","avatar":""},{"name":"Trịnh Y Kiện","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
