INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-tien-truyen', 'Diệp Vấn Tiền Truyện', 'The Legend Is Born: Ip Man', 'https://phimimg.com/upload/vod/20240128-1/aab3ef8dcbdecd8f49723efd63672419.jpg', 'https://phimimg.com/upload/vod/20240128-1/30cfed50c59beac797f01b88044bb3fc.jpg', '<p>Câu chuyện bắt đầu tại Quảng Đông,miền Nam Trung Quốc vào năm 1905. Diệp Vấn và người anh em không cùng huyết thống Tien-Chi trở thành đệ tử của sư phụ Chan Wah-sun (do Hồng Kim Bảo thủ vai), trưởng môn phái Vịnh Xuân. Sau khi sư phụ qua đời được một năm, võ quán được chuyển giao cho người bạn lâu năm của ông là Chun-Sui (Yuen Biao đóng). Năm 1915, Diệp Vấn chiếm được trái tim của cô gái Cheung Wing-sin sau một lần bảo vệ cô trong một trận chiến, nhưng lại dấy lên sự ghen tuông từ người bạn ấu thơ cũng là đồng môn của anh Lee Mei Wai, người đã yêu thầm anh từ lâu. Sau đó, Diệp Vấn đến Hong Kong để tiếp tục nghiệp học ở trường Đại học. Tại đây, anh đã gặp Leung Bik - một cao thủ Vịnh Xuân Quyền, người đã dạy anh những đòn thế đầy sáng tạo và uy lực mà trước đây anh chưa từng biết đến ở môn võ Vịnh Xuân. Tuy nhiên, Diệp Vấn lại bị các môn phái khác trừng phạt chính vì những thế võ Vịnh Xuân này bị coi là dị giáo...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Yu-Hang To","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"Biao Yuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
