INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-nhan-quyen', 'Cuộc Chiến Nhân Quyền', 'Made In Dagenham', 'https://phimimg.com/upload/vod/20240128-1/9d05d1aeb77a393c679680e4c1635eee.jpg', 'https://phimimg.com/upload/vod/20240128-1/3dba383deb79426b5b77eb0df9eb9cd9.jpg', '<p>Kịch bản về cuộc đình công năm 1968 tại nhà máy ô tô Ford Dagenham, nơi các nữ công nhân xuống đường phản đối sự phân biệt giới tính.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sally Hawkins","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Simon Nehan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
