INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-so-kinh-hoang', 'Tần Số Kinh Hoàng', 'Midnight FM', 'https://phimimg.com/upload/vod/20240128-1/ff4fde7d720ec0ec9a9685d5be3c4c8f.jpg', 'https://phimimg.com/upload/vod/20240128-1/bc49cf1bf22a429c584110f58f8f48a3.jpg', '<p>Sun-young là một DJ phát thanh nổi tiếng với nhiều người hâm mộ, cô dẫn chương trình nhạc phim phát sóng đêm khuya. Cô là một người hoàn hảo, đã xây dựng được một sự nghiệp thành công trong 5 năm qua, nhưng khi con gái cô cần phải tiến hành phẫu thuật ở nước ngoài, người mẹ đơn thân này quyết định từ bỏ sự nghiệp. Cô chuẩn bị cho buổi phát sóng cuối cùng của mình từ việc lựa chọn bài hát cho đến những chi tiết nhỏ nhặt nhất.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Soo Ae","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Choi Song-hyun","avatar":""},{"name":"Shin Da-eun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
