INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-chien-binh', 'Con Đường Chiến Binh', 'The Warrior''s Way', 'https://phimimg.com/upload/vod/20240127-1/c49684108fb0a3547756f4657f841c52.jpg', 'https://phimimg.com/upload/vod/20240127-1/ae5b6e852ab96d3f1ee2108031eb73e2.jpg', '<p>Yang là một người đàn ông được gọi là “anh chàng có đôi mắt trống rỗng” đã quyết tâm luyện trí lực của mình trong một thời gian dài để đánh bại tất cả kẻ thù và trở thành tay kiếm hàng đầu thế giới. Nhưng rồi anh cảm thấy nghi ngờ về đám sát thủ mà mình vẫn giao du và quyết định đến ẩn mình ở một nơi xa xôi – một ngôi làng nằm trên bờ biển phía Tây – và sống với một em bé có cha mẹ đã bị giết bởi chính lưỡi gươm của anh. Tại đây, Yang đã sống một cuộc sống yên tĩnh bằng cách mở tiệm giặt ủi, và dần dần trái tim băng giá của anh đã mở ra đón nhận tấm lòng của một cô gái mạnh mẽ tên là Lynne, người cố gắng tiếp cận và trở nên gần gũi với anh. Nhưng hạnh phúc của họ không kéo dài. Một tên chỉ huy độc ác, người đã sát hại cả gia đình của Lynne, đang đe dọa cả làng, còn những đồng bọn trước đây của Yang đã phát hiện ra sự phản bội của anh và truy đuổi để khử anh. Tình cảnh này đã bắt buộc Yang phải rút kiếm của mình ra khỏi vỏ và sử dụng nó một lần nữa...</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dong-gun Jang","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Geoffrey Rush","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
