INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ghet-chuyen-tinh-yeu', 'Tôi Ghét Chuyện Tình Yêu', 'I Hate Luv Storys', 'https://phimimg.com/upload/vod/20240127-1/7168219bdd252bd2f7d5f5e97ec0336f.jpg', 'https://phimimg.com/upload/vod/20240127-1/b9bf56ee5a926b07fd64d222a030f485.jpg', '<p>Simran thích những câu chuyện tình yêu, với công việc lý tưởng và người bạn trai hoàn hảo, cô sống một cuộc sống hạnh phúc và mơ mộng. Tuy nhiên, mọi thứ bị gián đoạn một cách thô bạo bởi sự hoài nghi về tình cảm của Jay.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Imran Khan","avatar":""},{"name":"Sonam Kapoor","avatar":""},{"name":"Sammir Dattani","avatar":""},{"name":"Samir Soni","avatar":""},{"name":"Bruna Abdullah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
