INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-lan-lua-dan', 'Giữa Làn Lửa Đạn', '71: Into The Fire', 'https://phimimg.com/upload/vod/20240126-1/69407680d48381cf78ed369be3459ba6.jpg', 'https://phimimg.com/upload/vod/20240126-1/62afb469ffbd33c2e501e0dd8b4306a5.jpg', '<p>71: Into the Fire – Giữa Làn Lửa Đạn – là câu chuyện về cuộc chiến tranh tại Hàn Quốc của 71 học sinh, sinh viên Hàn Quốc trong cuộc chiến chống lại đợt tấn công của hàng trăm binh lính Triều Tiên dày dạn trong cuộc chiến tranh Triều Tiên nổ ra vào năm 1950.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Choi Seung-hyun","avatar":""},{"name":"Kim Seung-woo","avatar":""},{"name":"Cha Seung-won","avatar":""},{"name":"Kim Hye-seong","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324474);
