INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-nguy-hiem', 'Kẻ Nguy Hiểm', 'A Dangerous Man', 'https://phimimg.com/upload/vod/20240126-1/6ef44b0490a4922114540ea5e9fbe2ca.jpg', 'https://phimimg.com/upload/vod/20240126-1/1a96ee2c6431c09b768a3d8405295233.jpg', '<p>Shane Daniels, một cựu đặc nhiệm bị kết án oan 6 năm cho tội giết người. 6 năm sau, trên đường rời khỏi nước Mỹ, anh vô tình cứu sống 1 cô gái và vô tình dính vào 1 đường dây buôn bán ma túy có sự tham gia của cảnh sát liên bang. Đã dính vào rồi thì tất nhiên phải thoát ra, và cuộc đấu tranh giành sự sống bắt đầu...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Marlaina Mah","avatar":""},{"name":"Vitaly Kravchenko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
