INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-hai-duong', 'Thiên Đường Hải Dương', 'Ocean Heaven', 'https://phimimg.com/upload/vod/20240123-1/f73494189f2b9c68cda5a1d31002e80e.jpg', 'https://phimimg.com/upload/vod/20240123-1/9ef1b8b1d0397101f269c78c9d89d4f9.jpg', '<p>Câu chuyện về tình yêu không mệt mỏi của người cha dành cho cậu con trai mắc chứng tự kỷ. Người cha mắc bệnh nan y cố gắng dạy cậu con trai mắc chứng tự kỷ những kỹ năng sống cần thiết để tự mình sinh tồn trước khi qua đời. Đó cũng là sự tri ân sâu sắc đối với tình yêu thương vô bờ bến mà cha mẹ dành cho con cái và mong muốn không ngừng chăm sóc, chăm sóc con bằng hết khả năng của mình, bất chấp khó khăn, bất kể nỗ lực.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Wen Zhang","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Zhu Yuanyuan","avatar":""},{"name":"Gao Yuanyuan","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"Chen Ran","avatar":""},{"name":"Yong Mei","avatar":""},{"name":"Chen Rui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
