INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-sat-o-my-lai', 'Thảm Sát Ở Mỹ Lai', 'My Lai Four: Soldati Senza Onore', 'https://phimimg.com/upload/vod/20240123-1/3de3abade7c8a37f27908c5bb527e66c.jpg', 'https://phimimg.com/upload/vod/20240123-1/a89f545f249a8cdcb1d393e36472a62b.jpg', '<p>My Lai Four là một bộ phim nói về câu chuyện của một trung đội lính Mỹ gây ra vụ thảm sát kinh hoàng tại Mỹ Lai – Việt Nam (Mỹ Lai là một ngôi làng nhỏ thuộc huyện Sơn Tịnh, tỉnh Quảng Ngãi). Bộ phim này được chuyển thể từ tác phẩm đoạt giải Pulitzer của Seymour Hersh.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Lồng Tiếng', 'HD', 'Ý', 0, '[{"name":"Alvin Anson","avatar":""},{"name":"Gianluca Baldari","avatar":""},{"name":"Beau Ballinger","avatar":""},{"name":"Ronny Boos","avatar":""},{"name":"Michael Bruggink","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
