INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paris-toc-hanh', 'Paris Tốc Hành', 'Coursier', 'https://phimimg.com/upload/vod/20240125-1/d0c058a875bfd1ce882175043543aa5b.jpg', 'https://phimimg.com/upload/vod/20240125-1/7cb0ab1c3787b2f8e299f05a188fe92f.jpg', '<p>Sam (Michaël Youn) là một nhân viên chuyển phát nhanh. Để đúng giờ với khách, anh luôn phá vỡ mọi luật lệ trên đường để có thể làm tốt công việc. Nhưng dù cố gắng bao nhiêu, anh cũng chưa bao giờ nhận được tiền thưởng từ ông chủ, chưa bao giờ thắng được các đồng nghiệp, và luôn bị cảnh sát giao thông phạt. Bạn gái của anh là Nadia (Géraldine Nakache), em gái Nadia tổ chức đám cưới, cô yêu cầu anh bằng mọi giá phải tham dự. Nhưng ngay ngày đám cưới, anh lại vô tình giao hàng cho một băng nhóm tội phạm, và mọi rắc rối cứ đổ lên đầu anh...</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Michaël Youn","avatar":""},{"name":"Géraldine Nakache","avatar":""},{"name":"Jimmy Jean-Louis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
