INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-gioi-han', 'Vượt Giới Hạn', 'Extraordinary Measures', 'https://phimimg.com/upload/vod/20240122-1/baab77d0d4780a104df189ba8e4744e3.jpg', 'https://phimimg.com/upload/vod/20240122-1/f03c38afde2323ad1167f25937192057.jpg', '<p>Người cha thuộc tầng lớp lao động John Crowley cuối cùng cũng đang trên đà thành công nhanh chóng khi hai đứa con nhỏ của ông được chẩn đoán mắc bệnh Pompe—một tình trạng khiến cơ thể không thể phân hủy đường. Với sự hỗ trợ của vợ, John từ bỏ sự nghiệp của mình và hợp tác với chuyên gia độc đáo, Tiến sĩ Robert Stonehill để thành lập một công ty công nghệ sinh học và phát triển một phương pháp chữa trị kịp thời để cứu sống các con của mình. Khi Tiến sĩ Stonehill làm việc không mệt mỏi để chứng minh những lý thuyết khiến ông trở thành con cừu đen của cộng đồng y tế, một mối liên kết mạnh mẽ đã được hình thành giữa hai đồng minh khó tin.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"Meredith Droeger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
