INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-vo', 'Tan Vỡ', 'Heartbreaker', 'https://phimimg.com/upload/vod/20240122-1/979fa4dc5813653a2f408d0a9344c8d1.jpg', 'https://phimimg.com/upload/vod/20240122-1/4259fa1b062d3f9835e9edeba209e497.jpg', '<p>Alex và em gái của anh ấy điều hành một doanh nghiệp được thiết kế để phá vỡ các mối quan hệ. Họ được một người đàn ông giàu có thuê để phá đám cưới của con gái ông ta. Vấn đề duy nhất là họ chỉ có một tuần để làm như vậy.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Romain Duris","avatar":""},{"name":"Vanessa Paradis","avatar":""},{"name":"Julie Ferrier","avatar":""},{"name":"François Damiens","avatar":""},{"name":"Andrew Lincoln","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
