INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cah', 'Ca$h', 'Ca$h', 'https://phimimg.com/upload/vod/20240122-1/25fecced8f759ba9516ec14aeb496ed9.jpg', 'https://phimimg.com/upload/vod/20240122-1/07373b36f3dd8408674e823c1ddb5f1f.jpg', '<p>Một sự may mắn bỗng trở nên nguy hiểm đối với Sam Phelan và vợ Leslie khi họ phải đối mặt với một quyết định thay đổi cuộc đời, đưa Pyke Kubic kỳ lạ và nham hiểm đến trước cửa nhà họ. Khi Pyke dẫn Sam và Leslie vào một cuộc phiêu lưu hỗn loạn qua các đường phố Chicago, mỗi người ngày càng bị kéo sâu hơn vào vòng xoáy tuyệt vọng của lừa dối và bạo lực – tất cả đều nhân danh tiền bạc.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Victoria Profeta","avatar":""},{"name":"Thampy Antony","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Michael Mantell","avatar":""},{"name":"Paul Sanchez","avatar":""},{"name":"Peggy Roeder","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Larry Neumann Jr.","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
