INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-soi', 'Quái Vật Sói', 'Monsterwolf', 'https://phimimg.com/upload/vod/20240122-1/7e15187e2d55a32106727c4c5192a6bd.jpg', 'https://phimimg.com/upload/vod/20240122-1/7c7ba2d4365008421cd2d710fe46e694.jpg', '<p>Quái Vật Sói - Monsterwolf kể về một nhóm người đại diện cho một công ty dầu khí tìm thấy một mảnh đất mới để khoan dầu. Nhưng sau đó, họ vô tình bắt gặp một sinh vật rất giống sói. Sinh vật này tàn phá thị trấn và chỉ có thể bị ngăn chặn bởi người Mỹ bản địa cuối cùng còn sống sót.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leonor Varela","avatar":""},{"name":"Marc Macaulay","avatar":""},{"name":"Robert Picardo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
