INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-trung-phat', 'Biệt Đội Trừng Phạt', 'Sinners And Saints', 'https://phimimg.com/upload/vod/20240121-1/62cf72e570a8d23209e4e6de07fafb8c.jpg', 'https://phimimg.com/upload/vod/20240121-1/9a2fea2e545c2468968cece9af3f9b15.jpg', '<p>Trong cơn bão tội phạm đang bao trùm thành phố New Orleans, hai cảnh sát Sean Riley và Will Ganz được hợp thành tổ giải quyết hàng loạt vụ giết người thô bạo đang dần lôi kéo thành phố vào một cuộc chiến giữa hai băng nhóm tôi phạm lớn. Càng điều tra họ càng phát hiện sự thật chưa bao giờ mà họ tưởng tượng đến...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Strong","avatar":""},{"name":"Kevin Phillips","avatar":""},{"name":"Costas Mandylor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
