INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-khong-nhu-la-mo', 'Đời Không Như Là Mơ', 'Life As We Know It', 'https://phimimg.com/upload/vod/20240121-1/16aada594b176ff25def3983cd353f05.jpg', 'https://phimimg.com/upload/vod/20240121-1/7a6ad4b06ed992c32d460e9ee2bd5121.jpg', '<p>Phim được mở đầu bằng một cuộc hẹn hò nhớ đời của Holly, cô chủ một hiệu bánh nhỏ và Eric Messer, một kỹ thuật viên sát gái của kênh truyền hình thể thao. Họ gặp nhau theo sự sắp đặt của hai người bạn thân nhất - Alison và Peter. Cuộc gặp gỡ tưởng như lãng mạn nhanh chóng trở thành đêm hẹn hò tồi tệ nhất mà cả Holly và Messer đều muốn quên đi vì họ giống như hai cực trái dấu, không thể hòa hợp. Trớ trêu thay, vì có chung hai người bạn thân nhất nên họ liên tiếp phải đối đầu nhau trong những dịp đặc biệt, nhất là khi Sophie - con của Alison và Peter chào đời. Holly và Messer trở thành cha mẹ đỡ đầu của cô bé.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katherine Heigl","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Josh Lucas","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
