INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-hen-nho-doi', 'Đêm Hẹn Nhớ Đời', 'Date Night', 'https://phimimg.com/upload/vod/20240121-1/45846bd8e32c8ad302eae0bfeb71a199.jpg', 'https://phimimg.com/upload/vod/20240121-1/e60c48583b6a7fa20fb9a063e1718aec.jpg', '<p>Phil và Claire Foster lo sợ rằng mối quan hệ nhẹ nhàng của họ có thể rơi vào một lối mòn cũ. Trong đêm hẹn hò hàng tuần của họ, việc đặt chỗ ăn tối dẫn đến việc họ bị nhầm với một vài tên trộm — và giờ đây, một số nhân vật không ưa muốn giết Phil và Claire.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Jimmi Simpson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
