INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('super', 'Super', 'Super', 'https://phimimg.com/upload/vod/20240121-1/c444f3aff44a904c909364d646cf7eda.jpg', 'https://phimimg.com/upload/vod/20240121-1/c8b8b2f62b473649de6e62024ce852fa.jpg', '<p>Sau khi vợ rơi vào tầm ảnh hưởng của một tên buôn ma túy, một anh chàng hàng ngày biến mình thành Crimson Bolt, một siêu anh hùng với những ý định tốt nhất, mặc dù anh ta thiếu các kỹ năng anh hùng.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"Elliot Page","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Gregg Henry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
