INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-tam', 'Dã Tâm', 'Burning Bright', 'https://phimimg.com/upload/vod/20240121-1/14fc6f1750841678b7df0eb83938a20d.jpg', 'https://phimimg.com/upload/vod/20240121-1/3dad01493a039bcc35aa71054047b17a.jpg', '<p>Sau khi người cha dượng ăn cắp tiền tiết kiệm của cô để mua một con hổ dữ, Kelly mất hết hy vọng vào đại học. Nhưng tình hình của Kelly trở nên tồi tệ hơn khi một cơn bão khiến cô và anh trai mắc chứng tự kỷ của mình phải sống trong ngôi nhà của họ với con quái vật ăn thịt người. Bộ phim kinh dị không thể bỏ qua này kể về nữ anh hùng gan dạ và em gái của cô ấy khi họ đấu tranh để đánh lừa kẻ săn mồi hung hãn và tìm cách sống sót.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Briana Evigan","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Charlie Tahan","avatar":""},{"name":"Peggy Sheffield","avatar":""},{"name":"Mary Rachel Dudley","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
