INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-thoi-o-tay-tang', 'Một Thời Ở Tây Tạng', 'Once Upon A Time In Tibet', 'https://phimimg.com/upload/vod/20240111-1/f2c882ef6f6294258f904c685d3b6c9b.jpg', 'https://phimimg.com/upload/vod/20240111-1/1519e82b75ad082868177c5185887af8.jpg', '<p>Lấy bối cảnh trong Chiến tranh Trung-Nhật lần thứ hai (1937-1945), quân đội Hoa Kỳ mang hàng tiếp tế đến Trung Quốc bằng cách bay qua dãy Himalaya. Sau đó, một câu chuyện tình yêu nảy sinh giữa một phi công người Mỹ và một cô gái Tây Tạng, người đã cứu mạng anh ta khi máy bay của anh ta bị rơi.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Song Jia","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"Joshua Hannum","avatar":""},{"name":"Zhu Ziyan","avatar":""},{"name":"San Mu-Ke","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
