INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-soi', 'Ma Sói', 'The Wolfman', 'https://phimimg.com/upload/vod/20240111-1/dcf18894fa0d9c1532cd803a27e21e69.jpg', 'https://phimimg.com/upload/vod/20240111-1/6cb866b5a4ec19750c74d2650f6701f8.jpg', '<p>Lawrence Talbot, một quý tộc bị ám ảnh bởi quá khứ của bản thân, khám phá ra số phận nghiệt ngã của mình. Tuổi thơ của Talbot kết thúc vào đêm mẹ ông qua đời. Ông rời ngôi làng Victorian của vùng Blackmoor, cố gắng vượt qua cú sốc và quên đi mọi thứ. Nhưng khi Gwen Conliffe, hôn thê của anh trai ông, cầu cứu ông để tìm kiếm người chồng đang mất tích của cô, Talbot buộc phải trở về làng. Đó cũng là lúc ông phát hiện ra có một sức mạnh khát máu kinh khủng đang giết dần giết mòn dân làng.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benicio Del Toro","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Emily Blunt","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
