INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-loi-dai', 'Đả Lôi Đài', 'Tiger And Dragon Reloaded', 'https://phimimg.com/upload/vod/20240205-1/fbd3aa1b0e283a04d2d3948d6c731b0b.jpg', 'https://phimimg.com/upload/vod/20240205-1/b3d74a456a17ceea3f39e2dc0d12efc7.jpg', '<p>Cheung là một thanh niên yếu ớt và hay bị bắt nạt nhưng lại rất ham thích tập võ và luyện kungfu. Ông chủ xem Cheung là một kẻ vô dụng và gửi anh ta về làm cho một công ty trà ở vùng quê xa xôi. Nhưng không ngờ nơi đây lại là nơi xuất hiện của rất nhiều những cao thủ kungfu và Cheung phải đối mặt với nhiều nguy hiểm khi luôn đứng giữa những cuộc giao tranh của hai bang phái Rồng và Hổ. Chẳng bao lâu sau, Cheung nhận ra rằng, mối liên kết chỉ có thể được giải quyết nếu như anh ra tay...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Siu-Lung Leung","avatar":""},{"name":"Kuan Tai Chen","avatar":""},{"name":"Teddy Robin Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
