INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be', 'Cậu Bé', 'Boy', 'https://phimimg.com/upload/vod/20240111-1/29bbe029511529dc670d7158f16ce664.jpg', 'https://phimimg.com/upload/vod/20240111-1/54a31328870e984cc9c95d1a961d515f.jpg', '<p>Cậu bé, một đứa trẻ 11 tuổi và là một người hâm mộ cuồng nhiệt của Michael Jackson, sống ở bờ biển phía đông New Zealand vào năm 1984, có cơ hội biết người cha tội phạm vắng mặt của mình, người đã quay trở lại để tìm một túi tiền mà anh ta đã chôn nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"James Rolleston","avatar":""},{"name":"Te Aho Aho Eketone-Whitu","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Moerangi Tihore","avatar":""},{"name":"Cherilee Martin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
