INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-diet-vong-2008', 'Thảm Họa Diệt Vong', 'Black Death', 'https://phimimg.com/upload/vod/20240111-1/8f6bd6688e6f9e09a6fcf034595ee75d.jpg', 'https://phimimg.com/upload/vod/20240111-1/6bb4195df4a8c86cbd70af1666011ab8.jpg', '<p>Khi bệnh dịch hạch tàn phá khắp Anh quốc, những tin đồn về một ngôi làng đã hoàn toàn thoát khỏi bệnh dịch, bởi vì người dân ở đó đã thực hành các nghi lễ satan, và Chúa tể bóng tối giúp họ tránh khỏi bệnh tật và đưa người chết sống lại. Ulric (Sean Bean), một hiệp sĩ cuồng tín thuộc dòng tu Thánh chiến cùng một toán hiệp sĩ đánh thuê nhận nhiệm vụ tìm kiếm ngôi làng xa xôi, bắt giữ thủ lĩnh của người dân làng dị giáo, và đưa những kẻ tà đạo đó ra trước công lý nhân danh nhà thờ. Còn tu sĩ trẻ tuổi Osmund (Eddie Redmayne), người tình nguyện làm người hướng dẫn cho nhóm hiệp sĩ thì coi đây là một nhiệm vụ cứu rỗi những linh hồn lầm lạc. Cuộc hành trình của họ chứa đầy nguy hiểm, đã có người ngã xuống, nhưng khi vào làng thì nỗi kinh hoàng thực sự của họ mới bắt đầu...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Eddie Redmayne","avatar":""},{"name":"Carice van Houten","avatar":""},{"name":"Kimberley Nixon","avatar":""},{"name":"John Lynch","avatar":""},{"name":"Tim McInnerny","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Daniel Steiner","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
