INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-canh-sat', 'Siêu Cảnh Sát', 'Dabangg', 'https://phimimg.com/upload/vod/20240104-1/a5c8095cd3d7de7c62dfb7ba0845a4c3.jpg', 'https://phimimg.com/upload/vod/20240104-1/2efcafe5cce2d1ec69e273807a47fbef.jpg', '<p>Bộ phim về nạn tham nhũng trong giới cảnh sát của đạo diễn Abhinav Kashyap đã giành tới 6 giải thưởng, gồm giải phim hay nhất, giải Nam/Nữ ca sĩ xuất sắc nhất, Chỉ đạo âm nhạc và Kịch bản xuất sắc nhất tại lễ trao giải Điện ảnh Quốc tế Ấn Độ lần thứ 12 - được xem là giải “Oscar của Bollywood” - được tổ chức lần đầu tiên ở Bắc Mỹ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Sonakshi Sinha","avatar":""},{"name":"Vinod Khanna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
