INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-canh-sat', 'Siêu Cảnh Sát', 'Dabangg', 'siêu cảnh sát dabangg salman khan sonakshi sinha vinod khanna ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-tam-than-tham', 'Độc Tâm Thần Thám', 'Độc Tâm Thần Thám', 'https://phimimg.com/upload/vod/20240116-1/e3d82e512df2c58b6a98520fb707c557.jpg', 'https://phimimg.com/upload/vod/20240116-1/08b7fdd851abee060fd397872783d6ec.jpg', '<p>Thanh tra đơn vị chống tội phạm cấp cao, Yiu HOK-SUM (Bowie Lam) đã học được kỹ năng đọc tâm trí của người khác ở nước ngoài. Cho đến nay anh là cảnh sát làm việc hiệu quả và quyền lực nhất trong đơn vị. Anh có thể phân tích và đọc được ý nghĩ của người khác chỉ bằng cách quan sát ngôn ngữ cơ thể của họ, nét mặt và từ những giai điệu của giọng nói. Ngoài ra, anh cũng có kỹ năng cao khi chỉ ra khác biệt trong lời khai và bằng chứng.&nbsp;Tuy nhiên, đồng đội của anh xem anh như chướng ngại trong mắt. Nhân viên mới, YIP CHIN-TING (Kristal Tin) và HO LAI-YIN (Bosco Wong) làm việc đặc biệt phiền toái. Kết quả là, hai người thường có đối chất và sự hiểu lầm với thanh tra. Những điều trên trở nên tồi tệ hơn SUM khi biết rằng em gái của anh, CHING PUI-YEE (Aimee Chan) đang bí mật hẹn hò với LAI, và TING, người gần đây đã được ly dị, đã phải lòng anh ta.&nbsp;</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 2010, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lê Nặc Ý","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Lâm Bảo Di","avatar":""},{"name":"Điền Nhụy Ni","avatar":""},{"name":"Trần Nhân Mỹ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
