INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-brighton', 'Băng Đảng Brighton', 'Brighton Rock', 'https://phimimg.com/upload/vod/20240104-1/9e413110b0bef5119af9444bd03ca953.jpg', 'https://phimimg.com/upload/vod/20240104-1/3a347026be0b21ef866d2c772c103bea.jpg', '<p>BRIGHTON ROCK : Bộ phim dựa trên cuốn tiểu thuyết của Graham Greene trong đó kể về một tên tội phạm đã giết chết một kẻ thù và từ đó cuộc sống của hắn trở nên hỗn loạn khi phải đối mặt với mối đe dọa tống tiền từ một cô hầu bàn (Riseborough) người biết rõ về kẻ sát nhân.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy Serkis","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Andrea Riseborough","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
