INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-tien-thuong-2010', 'Kẻ Săn Tiền Thưởng', 'The Bounty Hunter', 'https://phimimg.com/upload/vod/20240104-1/407c9e9ccd35aa1707b95bd78352daf6.jpg', 'https://phimimg.com/upload/vod/20240104-1/904f0c3fa4bce1d50868c22f414ff78d.jpg', '<p>Buổi biểu diễn mới nhất của một thợ săn tiền thưởng đáng kính khá thỏa mãn, vì người bảo lãnh của anh ta là vợ cũ của anh ta, người không có ý định bị bắt nếu không chiến đấu.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Gio Perez","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Joel Garland","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
