INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jackass-3d', 'Jackass 3D', 'Jackass 3D', 'https://phimimg.com/upload/vod/20240103-1/a4f7ada6e134cb89cfa9b44fb5626b03.jpg', 'https://phimimg.com/upload/vod/20240103-1/bc8d2c0d82b0d669da37cb2dd90dad98.jpg', '<p>Johnny Knoxville, Bam Margera, Steve-O, Wee Man và những người bạn gan dạ và liều lĩnh còn lại của họ tham gia vào một vòng chơi khăm và pha nguy hiểm kỳ quặc khác. Ngoài việc đứng trên đường đi của một con bò tót đang lao tới, phóng mình lên không trung và đâm xuyên qua nhiều đồ vật khác nhau, các chàng trai còn biểu diễn trong các phân đoạn như Cocktail áo len, Bóng tổ ong và Kéo răng Lamborghini.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Knoxville","avatar":""},{"name":"Bam Margera","avatar":""},{"name":"Ryan Dunn","avatar":""},{"name":"Steve-O","avatar":""},{"name":"Chris Pontius","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324474);
