INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-khu-tu-than', 'Đặc Khu Tử Thần', 'The Ward', 'https://phimimg.com/upload/vod/20240102-1/70e62e7aad68feba276a775383ff06df.jpg', 'https://phimimg.com/upload/vod/20240102-1/007de4f4a6e991f780b3beb6876b9c3a.jpg', '<p>Kristen, một phụ nữ trẻ gặp rắc rối, bị cảnh sát bắt sau khi đốt cháy một trang trại và bị nhốt trong Bệnh viện tâm thần North Bend. Chẳng mấy chốc, cô bắt đầu nghi ngờ rằng nơi này có một bí mật đen tối cốt lõi và cô quyết tâm tìm ra nó là gì.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amber Heard","avatar":""},{"name":"Mamie Gummer","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Laura-Leigh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
