INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-chuoc-den', 'Tiền Chuộc Đen', 'Black Ransom', 'https://phimimg.com/upload/vod/20240102-1/51a94a988e978a1538d443acdc8c63c1.jpg', 'https://phimimg.com/upload/vod/20240102-1/ec3788fcbe9e2ed571db39b7bf4126be.jpg', '<p>Zhang Bo Wen là một sĩ quan cảnh sát trung niên, là một hình mẫu cho các cảnh sát trẻ. Ông là một thiện xạ và sở hữu một tính cách rất bình tĩnh. Những ngày vinh quang của ông đã kết thúc khi ông chỉ là cựu thành viên ưu tú trong một đơn vị cảnh sát. Mọi thứ thay đổi khi vợ ông là bị sát hại bởi các một băng nhóm tội phạm và sau đó, ông bị chìm vào tuyệt vọng, và mối quan hệ với con gái của ông cũng bị ảnh hưởng. Vào một ngày ông ta được yêu cầu bởi Madam Gu Guo Qiang, người mới được bổ nhiệm làm Tổng thanh ta, đi điều tra các lãnh đạo cấp cao của các băng nhóm.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Kiu Wai Miu","avatar":""},{"name":"Fala Chen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
