INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-nguyen-cuoi-doi', 'Ước Nguyện Cuối Đời', 'Ways To Live Forever', 'https://phimimg.com/upload/vod/20240102-1/4335621b9f5e68a391547d85e356367a.jpg', 'https://phimimg.com/upload/vod/20240102-1/779c5bfd0e16aace75037bfd54dfab30.jpg', '<p>Sam thích sự thật. Anh ấy muốn biết về UFO, phim kinh dị, khí cầu, ma và các nhà khoa học, và cảm giác hôn một cô gái như thế nào. Và bởi vì anh ấy mắc bệnh bạch cầu nên anh ấy muốn biết sự thật về cái chết. Sam cần câu trả lời cho những câu hỏi sẽ không ai trả lời.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Chaplin","avatar":""},{"name":"Emilia Fox","avatar":""},{"name":"Greta Scacchi","avatar":""},{"name":"Robbie Kay","avatar":""},{"name":"Alexander Nathan Etel","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
