INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-va-nguoi-doi-khai-huyen', 'Siêu Nhân Và Người Dơi: Khải Huyền', 'Superman Batman: Apocalypse', 'https://phimimg.com/upload/vod/20240102-1/710a8217e2213920461ab8ccedd70939.jpg', 'https://phimimg.com/upload/vod/20240102-1/7fd2268ed3b18251462797b9e972cd64.jpg', '<p>Bộ phim Superman Batman Apocalypse kể về Batman phát hiện ra một cô gái bí ẩn có năng lực siêu phàm và có mối liên hệ với Supper Man. Khi cô gái rơi vào tầm ngắm của Darkseid, chúa tể của Apocolips thì vô vàn nguy hiểm cũng đến với cô... Bằng lòng quả cảm của mình, liệu Batman có thể cứu cô gái thoát khỏi nguy hiểm hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Daly","avatar":""},{"name":"Kevin Conroy","avatar":""},{"name":"Summer Glau","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Andre Braugher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
