INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-tuyet-mat', 'Sứ Mệnh Tuyệt Mật', 'Point Blank', 'https://phimimg.com/upload/vod/20231231-1/f684b340c47fe24d61951c2e77d7b000.jpg', 'https://phimimg.com/upload/vod/20231231-1/610e14e835dd8c0559e6daae9d5a24b4.jpg', '<p>Samuel Pierret là một y tá đã cứu nhầm người - một tên trộm có tay sai bắt người vợ đang mang thai của Samuel làm con tin để buộc anh ta đưa ông chủ của họ ra khỏi bệnh viện. Một cuộc đua qua các tàu điện ngầm và đường phố ở Paris diễn ra sau đó, và số lượng người chết tăng lên. Samuel có thể trốn tránh cảnh sát và tội phạm ngầm và đưa người mình yêu đến nơi an toàn không?</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gilles Lellouche","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Gérard Lanvin","avatar":""},{"name":"Elena Anaya","avatar":""},{"name":"Mireille Perrier","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
