INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-bang', 'Đóng Băng', 'Frozen', 'https://phimimg.com/upload/vod/20231227-1/879bcc2409c390d559df28d6babe96b7.jpg', 'https://phimimg.com/upload/vod/20231227-1/6f1f45d3c7ad8860bbfd7578af6e0def.jpg', '<p>Khi ba người trượt tuyết thấy mình bị mắc kẹt trên ghế nâng tại một khu nghỉ mát trượt tuyết ở New England đã đóng cửa vào tuần tới, họ buộc phải đưa ra những lựa chọn sống hay chết được chứng minh là nguy hiểm hơn là ở lại và chết cóng.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Bell","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Ed Ackerman","avatar":""},{"name":"Rileah Vanderbilt","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Adam Johnson","avatar":""},{"name":"Chris York","avatar":""},{"name":"Peder Melhuse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324474);
