INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-to-xac-1', 'Những Đứa Trẻ To Xác 1', 'Grown Ups', 'https://phimimg.com/upload/vod/20231227-1/f63b0cc387c0b6361ca6301d1743588a.jpg', 'https://phimimg.com/upload/vod/20231227-1/3ee10c54df77bae6e64e90e227adc7f6.jpg', '<p>Sau nhiều năm xa cách, nhóm 5 người bạn thân từ khi tham gia đội bóng hồi trung học đã gặp lại nhau. Gần 3 thập kỷ đã trôi qua, cả 5 người đều đã lập gia đình và có con. Khi biết tin huấn luyện viên năm xưa qua đời, họ quay trở về New England để tham dự lễ tang. Mặc dù giờ đây mọi thứ đã thay đổi rất nhiều nhưng có một điều mà cả 5 anh bạn chí thân không bao giờ thay đổi. Chẳng ai trong số họ thực sự trưởng thành.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Kevin James","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
