INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-uy-thac', 'Người Ủy Thác', 'Repo Men', 'https://phimimg.com/upload/vod/20231227-1/f2527e259a883aa095ad97392b117437.jpg', 'https://phimimg.com/upload/vod/20231227-1/6521b9cac499d20c379e9b5242824215.jpg', '<p>Remy và Jake, hai người đồng đội luôn kề vai sát cánh làm việc cho một tổ chức tên là “The Union”, chuyên cung cấp cho con người những bộ phận nội tạng nhân tạo như mắt, tim, thận để có thể khỏe mạnh sinh sống. Nhiệm vụ hàng ngày của họ là tìm kiếm những khách hàng đã mua sản phẩm nhưng không trả nổi tiền để “đòi lại” bằng cách thô bạo nhất. Tình thế hoàn toàn thay đổi khi Remy sau một tai nạn trong lúc làm việc đã khiến bản thân anh phải thay một trái tim nhân tạo để sống xót. Không tiền trả, giờ đây Remy lại trở thành con mồi để những tay thợ chuyên nghiệp khác của “The Union” đuổi bắt...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Alice Braga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
