INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-eve', 'Thời Đại Eve', 'Time Of EVE: The Movie', 'https://phimimg.com/upload/vod/20231225-1/99b67f0f39585b8b101f2092e32e3685.jpg', 'https://phimimg.com/upload/vod/20231225-1/260f514d560f413ba302365028307ec5.jpg', '<p>Trong tương lai không xa, android sẽ được sử dụng phổ biến. Tuy nhiên, việc đối xử với người máy ngang hàng với con người không được tán thành và luôn có sự hoang tưởng xung quanh khả năng người máy bất chấp con người, chủ nhân của chúng. Những người tỏ ra quá tin tưởng vào android của họ sẽ bị khiển trách và bị gán cho là những người nghiện android. Rikuo Sakisaka, người đã coi robot là điều hiển nhiên trong suốt cuộc đời của mình, một ngày nọ phát hiện ra rằng Sammy, người máy tại nhà của anh, đã hành động độc lập và tự đến và đi một mình. Anh ấy tìm thấy một cụm từ kỳ lạ được ghi trong nhật ký hoạt động của cô ấy, Bạn có đang tận hưởng khoảng thời gian của EVE không?. Anh cùng với người bạn Masakazu Masaki lần theo dấu vết của Sammy và tìm thấy một quán cà phê khác thường. Nagi, nhân viên pha chế, thông báo với họ rằng quy tắc chính của quán cà phê là không phân biệt đối xử giữa người và người máy. Trong khi Rikuo cố gắng tiết lộ ý định của Sammy, anh bắt đầu đặt câu hỏi về tính hợp pháp của nỗi sợ hãi khiến con người coi người máy không hơn gì những công cụ đơn thuần.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Rie Tanaka","avatar":""},{"name":"Kenji Nojima","avatar":""},{"name":"Yukana","avatar":""},{"name":"Michio Nakao","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
