INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-khong-nga-re', 'Ngài Không Ngã Rẽ', 'Mr. Nobody', 'https://phimimg.com/upload/vod/20231230-1/aa70a4a7e53b8843fd79a6dcd77ce7e5.jpg', 'https://phimimg.com/upload/vod/20231230-1/6e05f82c8643f7d0f6461510ace429a3.jpg', '<p>Thuộc thể loại tâm lý, viễn tưởng do đạo diễn tài ba người Bỉ Jaco Van Dormael viết kịch bản và đạo diễn, Mr. Nobody là bộ phim nghệ thuật đích thực để lại cho khán giả nhiều cảm xúc và chút bâng khuâng trước câu hỏi: Liệu con đường ta đã chọn là con đường đúng đắn nhất?</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jared Leto","avatar":""},{"name":"Sarah Polley","avatar":""},{"name":"Diane Kruger","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
