INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-cuoi-cung', 'Bản Tình Ca Cuối Cùng', 'The Last Song', 'https://phimimg.com/upload/vod/20231230-1/9ec121d95586b77053a25ebd551cb169.jpg', 'https://phimimg.com/upload/vod/20231230-1/32080de8a99ad40f4afb233026ce9a31.jpg', '<p>Bộ phim xoay quanh một cô gái nổi loạn được gửi đến một thị trấn ven biển phía Nam vào mùa hè để ở với cha mình. Thông qua tình yêu âm nhạc chung, bộ đôi xa lạ học cách kết nối lại.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miley Cyrus","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Bobby Coleman","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Hallock Beals","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Nick Lashaway","avatar":""},{"name":"Carly Chaikin","avatar":""},{"name":"Kate Vernon","avatar":""},{"name":"Melissa Ordway","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
