INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-quy-quai', 'Ma Cà Rồng Quỷ Quái', 'Vampires Suck', 'https://phimimg.com/upload/vod/20231219-1/9b262be2d96cd643f88ec39ab25618f2.jpg', 'https://phimimg.com/upload/vod/20231219-1/d3ea21a0d63e8bbad62ecb76c0d4834e.jpg', '<p>Cuối cùng thì những đầu óc thích giễu cợt đã kịp “hút máu” Twilight Saga. Bởi vì đạo diễn Aaron Seltzer (được biết đến với các phim như Date Movie, Epic Movie v.v.) đã cho ra tác phẩm mới nhất của mình: Vampires Suck. Bộ phim hứa hẹn sẽ khiến cho các fan của Twilight “nổi sung” khi thấy các nhân vật yêu thích của mình bị đem ra làm trò đùa. Vì vậy, khuyến cáo những ai đã trót mê đắm chàng Edward ma cà rồng quyến rũ, nàng Bella đẹp một cách giản dị hoặc chàng Jacob không bao giờ mặc áo thì hãy cân nhắc trước khi xem Vampires Suck. Bạn cũng đừng mong đợi một thông điệp sâu sắc hay ý nghĩa từ bộ phim. Vampires Suck đơn giản chỉ là một phim hài nhái lại tình tiết của những bộ phim nổi tiếng khác. Đạo diễn (đồng thời cũng là người viết kịch bản) Aaron Seltzer biến những nhân vật nghiêm túc trong Twilight và các phim khác trở nên ngớ ngẩn, vụng về và ngu ngốc. Mỗi chi tiết trong phim đều chứa đựng yếu tố bất ngờ. Nó có thể khiến bạn bật cười thoải mái. Nhưng đồng thời cũng có thể làm bạn thấy khó chịu vì kiểu hài khiếm nhã đặc trưng của loại phim này.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jenn Proske","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"Diedrich Bader","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
