INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-tot-dep', 'Những Điều Tốt Đẹp', 'All Good Things', 'https://phimimg.com/upload/vod/20231219-1/d0c24cba6bbc5abcb91169d4bdadd063.jpg', 'https://phimimg.com/upload/vod/20231219-1/e624773c4895e67af32e4dcbce1eea50.jpg', '<p>Bộ phim lấy bối cảnh những năm 1980 tại thành phố New York. David Marks (Ryan Gosling), con trai của một ông trùm bất động sản cực hùng mạnh, đã kết hôn với một học sinh cùng lớp xinh đẹp có tên Katie (Kirsten Dunst). Họ cùng nhau chạy trốn ra khỏi thành phố để tới Vermont, mới mục đích chỉ là được thu hút sự chú ý của cha David. Khi trở lại, Katie tiếp tục học trường y và bắt đầu một cuộc sống cho mình. Tuy nhiên, khi Katie trở nên ngày càng độc lập, thì David thì lại trở nên bạo lực nhiều hơn. Bí mật gia đình thì từ từ tiết lộ, cũng như việc Katie biến mất mà không để lại một dấu vết. Nhiều năm sau, khi người bạn thân nhất của David bị chết, vụ án 20 năm này lại mở ra với David là nghi phạm chính, và các bí mật đen tối của gia đình đã mở đường cho một sự thật đáng sợ.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Frank Langella","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
