INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-ban-quy-gia-noel', 'Dị Bản: Quỷ Già Noel', 'Rare Exports', 'https://phimimg.com/upload/vod/20231219-1/6773c267040c6085b85a1b9462e92ea8.jpg', 'https://phimimg.com/upload/vod/20231219-1/7fdf3b7f75c85b127bf842ca6053bd93.jpg', '<p>Ở một vùng núi tuyết Bắc Phần Lan, những đứa trẻ nơi đây lần lượt biến mất một cách bí ẩn. Những thợ săn tuần lộc bắt đầu công cuộc tìm kiếm cho tới khi tìm ra một di tích cổ. Họ phát hiện ra nhân vật huyền thoại đang sống tại nơi này - một ông già Tuyết có thật. Nhưng tất cả khác xa những gì người ta tưởng tượng trước kia... Bộ Phim Dị Bản: Quỷ Già Noel khám phá một truyền thuyết khác hẳn về ông già Noel: thay vì là một vị thánh đi thưởng cho những đứa trẻ ngoan thì ông là một con quỷ đi trừng phạt những đứa trẻ hư. Khi ông già Noel thoát ra khỏi hầm mộ nơi đã phong ấn, giam cầm ông suốt nhiều năm trời, những chú lùn trong truyền thuyết bắt đầu đi bắt cóc những đứa trẻ trong thị trấn...</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Phần Lan', 0, '[{"name":"Per Christian Ellefsen","avatar":""},{"name":"Jorma Tommila","avatar":""},{"name":"Tommi Korpela","avatar":""},{"name":"Onni Tommila","avatar":""},{"name":"Jonathan Hutchings","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
