INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-phong-vu', 'Đông Phong Vũ', 'East Wind Rain', 'https://phimimg.com/upload/vod/20231219-1/9434323ee244915f2f67d763e80c27a5.jpg', 'https://phimimg.com/upload/vod/20231219-1/b5d9072c926a1cc0806718e4d5c348e3.jpg', '<p>Năm 1941, một cuộn phim được chuyển đến Thượng Hải và một điệp viên Trung Quốc tên là Gong An Ming (Liu Yun Long) phải quyết định xem anh ta nên làm gì với cuộn phim, hóa ra lại chứa đựng một bí mật lớn có thể gây chấn động cả thế giới. Anh phát hiện ra mã kế hoạch có tên Mưa gió đông và chuyển thông tin cho người Mỹ rằng lãnh thổ của họ sẽ sớm bị quân Nhật xâm chiếm. Mật mã được phát sóng trong bản tin thời tiết của Đài phát thanh Tokyo vào ngày 4 tháng 12 năm 1941. Khi ở Thượng Hải, An Ming gặp ca sĩ kiêm nghệ sĩ dương cầm, Hoàn Nhan (Phạm Băng Băng) và đem lòng yêu cô ấy mà không nhận ra rằng cô ấy cũng là một người. của các điệp viên. Ngay sau đó, An Ming nhận ra rằng nỗ lực của mình không thành công và đã bị bỏ qua vì một số lý do. Và bây giờ bằng cách mạo hiểm mạng sống của mình, anh ấy cũng phải quyết định xem Huân Yan là người yêu hay kẻ thù của mình? Cuối cùng Nhật Bản sẽ tấn công Trân Châu Cảng? Huan Yan đang làm gián điệp cho quốc gia nào? An Ming sẽ bị bắt bởi kẻ thù của mình?</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yunlong","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Takayuki Takemoto","avatar":""},{"name":"Li Xiaoran","avatar":""},{"name":"Yu Rongguang","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
