INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-bi-mat-cua-tieu-thu-anne-lister', 'Nhật Ký Bí Mật Của Tiểu Thư Anne Lister', 'The Secret Diaries Of Miss Anne Lister', 'https://phimimg.com/upload/vod/20231219-1/4ac6825af08e9faa716848b7071eadf5.jpg', 'https://phimimg.com/upload/vod/20231219-1/a2f6dc87f5488dd62a0627d291c57d9d.jpg', '<p>Một người đồng tính nữ vào những năm 1800 luôn ghi chép chi tiết về cuộc đời mình trong nhật ký được mã hóa, cố gắng sống độc lập trong khi tung hứng ngoại tình với một phụ nữ đã có gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maxine Peake","avatar":""},{"name":"Anna Madeley","avatar":""},{"name":"Susan Lynch","avatar":""},{"name":"Christine Bottomley","avatar":""},{"name":"Gemma Jones","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
