INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-anh-hung', 'Siêu Anh Hùng', 'Kick-Ass', 'https://phimimg.com/upload/vod/20231219-1/7486f212129ad19e921e34ffcaea0385.jpg', 'https://phimimg.com/upload/vod/20231219-1/9b2816afd569486f6b84c4fba03e6a82.jpg', '<p>Nội dung của Kick-Ass xoay quanh Dave Lizewski, một học sinh trung học vì quá mê mệt truyện tranh nên đã quyết định trở thành một... siêu anh hùng, dù cậu chẳng có khả năng siêu nhiên nào. Trên con đường “trừ gian diệt ác”, Dave vô tình chạm trán Big Daddy, một kẻ vì mục đích “thực thi công lý” đã huấn luyện cô con gái mới 11 tuổi của mình - Hit Girl - trở thành một “cô gái hành động...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Chloë Grace Moretz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
