INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-do-chua-te-nhac-rock', 'Dẫn Độ Chúa Tể Nhạc Rock', 'Get Him To The Greek', 'https://phimimg.com/upload/vod/20231219-1/1e5f992670d31c18bd68753799bb502a.jpg', 'https://phimimg.com/upload/vod/20231219-1/059ef7ef427a93c4a006d4e297c43db5.jpg', '<p>Phim đánh dấu sự hợp tác trở lại của hai danh hài Jonah Hill, Russell Brand cùng đạo diễn Nicholas Stoller kể từ sau bộ phim hài tình cảm Forgetting Sarah Marshall vào năm 2008. Trong tác phẩm mới này, Russell vào vai một ca sĩ nhạc rock, còn Jonah trở thành tay nhạc công quèn Aaron Green. Tay nhạc công được giao nhiệm vụ bay tới London để lôi kéo nam ca sĩ nhạc rock Aldous Snow tới biểu diễn tại một nhà hát của người Hy Lạp tại Los Angeles. Chuyến đi của Aaron đã xảy ra bao tình huống dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 6, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonah Hill","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Elisabeth Moss","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324474);
