INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-dien-ca-phe', 'Đồn Điền Cà Phê', 'White Material', 'https://phimimg.com/upload/vod/20231219-1/57b34f0339baaa5b5748e176f1878cd3.jpg', 'https://phimimg.com/upload/vod/20231219-1/a5705439f0001dacc844b4464e7a41df.jpg', '<p>Đồn Điền Cà Phê - White Material (2009):Đồn Điền Cà Phê (White Material) việc Denis thăm lại châu Phi, lần này khám phá một nơi đầy rẫy những xung đột dân sự và chủng tộc. Một gia đình người Pháp da trắng sống ngoài vòng pháp luật trong nhà và cố gắng cứu đồn điền cà phê của mình kết nối với một anh hùng da đen cũng bị lôi kéo vào cuộc hỗn chiến. Tất cả cố gắng sống sót khi thế giới của họ nhanh chóng sụp đổ xung quanh họ...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Isabelle Huppert","avatar":""},{"name":"Christopher Lambert","avatar":""},{"name":"Nicolas Duvauchelle","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
