INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('borgen-phan-1', 'Borgen (Phần 1)', 'Borgen (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/6780fb2beed494e9c7650ef2e89a54a8.jpg', 'https://phimimg.com/upload/vod/20231219-1/bca9e22a0fc7a5c91270f34934fec0a1.jpg', '<p>Trong phim chính kịch về sự kiện lịch sử này, loạt biến cố bất ngờ đưa Birgitte Nyborg vào ghế thủ tướng Đan Mạch với tư cách là lãnh đạo nữ đầu tiên của đất nước này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2010, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Sidse Babett Knudsen","avatar":""},{"name":"Birgitte Hjort Sørensen","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Freja Riemann","avatar":""},{"name":"Emil Poulsen","avatar":""},{"name":"Thomas Levin","avatar":""},{"name":"Benedikte Hansen","avatar":""},{"name":"Mikael Birkkjær","avatar":""},{"name":"Anders Juul","avatar":""},{"name":"Lisbeth Wulff","avatar":""},{"name":"Kasper Lange","avatar":""},{"name":"Lars Knutzon","avatar":""},{"name":"Søren Spanning","avatar":""},{"name":"Iben Dorner","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
