INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-oi-chao-mi', 'Ma Ơi Chào Mi', 'Hello Ghost', 'https://phimimg.com/upload/vod/20231219-1/5b68ecabdb3ce54f8673777ee8194a81.jpg', 'https://phimimg.com/upload/vod/20231219-1/5f8c888754dfddb20ca856540239b80a.jpg', '<p>Ma Ơi Chào Mi - Hello Ghost: Một câu chuyện xoay quanh Sang Man, một anh chàng cô đơn, tuyệt vọng chỉ muốn tìm cái chết. Một ngày nọ, sau một cố gắng tự tử không thành, Sang Man bỗng dưng thấy được các hồn ma. Đó là: Một con ma già biến thái có thú vui bệnh hoạn, cả đời chỉ thích nhìn mông phụ nữ. Một con ma nghiện thuốc ưa tọc mạch, thành ma mà vẫn sợ hồ ly tinh. Một ma nữ khóc nhè cứ sướt mướt cả ngày mà chẳng cần lý do. Thêm một thằng ma nhóc vô địch về ăn uống. Để thoát khỏi những oan hồn rắc rối này, Sang Man chỉ có cách hoàn thành tâm nguyện của họ trước khi chết. Sau khi hoàn thàn tâm nguyện, anh bỗng nhận ra...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Tae-hyun Cha","avatar":""},{"name":"Ye-won Kang","avatar":""},{"name":"Moon-su Lee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
