INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-da', 'Sỏi Đá', 'Stone', 'https://phimimg.com/upload/vod/20231219-1/ed42a80720aaafa4b1802b4ddfb4db92.jpg', 'https://phimimg.com/upload/vod/20231219-1/0e5ac554d15bc0e7fd0ebc8c580a27ef.jpg', '<p>Gerald Stone Creeson, phục vụ cho Arson, đang đến phiên điều trần về việc tạm tha. Để gia tăng cơ hội được phóng thích sớm, Stone đã cố gắng thu phục nhân viên văn phòng Jack Mabry bằng những trò chơi tâm lý và dùng chính vợ của mình để quyến rũ Jack.Trong lúc đó, Stone phát hiện ra một tôn giáo tên là Zukangor mà Norton trước đây đã từng nói rằng nó dựa trên một tôn giáo thực sự, có thể là Eckankar...</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Enver Gjokaj","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
