INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-bat-coc-alice-creed', 'Vụ Bắt Cóc Alice Creed', 'The Disappearance Of Alice Creed', 'https://phimimg.com/upload/vod/20231219-1/912bd7011460a58714518bad910aab3a.jpg', 'https://phimimg.com/upload/vod/20231219-1/33f04079571bb7c9056ba6356eaaec44.jpg', '<p>Hai tên tội phạm Vic và Danny lên kế hoạch bắt cóc cô gái Alice Creed. Chúng thiết kế biến một căn hộ chung cư thành một nhà tù, giữ chặt cô gái trên giường trong phòng kính cách âm hoàn toàn. Nhưng thời gian trôi qua trước khi nhận được tiền chuộc, những sự kiện xảy ra không như chúng mong muốn... Danny vốn yêu Alice nhưng khoản tiền hai triệu đô khiến anh mờ mắt. Con đường dẫn đến tội phạm thật không xa cũng không gần. Kết cục của ba con người, ba số phận rồi sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Gemma Arterton","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Martin Compston","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324474);
