INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('siren', 'Siren', 'Siren', 'https://phimimg.com/upload/vod/20231219-1/3b335b606692c773b01963e7d68fd12c.jpg', 'https://phimimg.com/upload/vod/20231219-1/823dad402a2a03c42206b54f8d5e629e.jpg', '<p>Một nhóm bạn trốn khỏi thành phố để đi nghỉ cuối tuần có một kế hoạch đơn giản là đi tham quan bờ biển để thư giãn cuối tuần. Mọi thứ trở nên khó khăn khi một trong những người bạn phát hiện ra một phụ nữ trẻ quyến rũ, nóng nảy đang vẫy tay cầu cứu ngoài khơi của một trong nhiều hòn đảo hẻo lánh dọc theo bờ biển. Tiếp cận để giải cứu cô ấy trở nên nguy hiểm và họ mạo hiểm mọi thứ để sống sót rời khỏi hòn đảo.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eoin Macken","avatar":""},{"name":"Anna Skellern","avatar":""},{"name":"Tereza Srbová","avatar":""},{"name":"Anthony Jabre","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
