INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-toi-ac', 'Thị Trấn Tội Ác', 'The Town', 'https://phimimg.com/upload/vod/20231215-1/c85fc259861b2cb724e1355b35a87a90.jpg', 'https://phimimg.com/upload/vod/20231215-1/e01361dd887cade17bbf05370d3d3ccf.jpg', '<p>Vùng lân cận Charlestown của Boston nổi tiếng vì đã tạo ra một số lượng lớn những tên cướp có vũ trang, thế hệ sau thế hệ. Những tên cướp này không bao giờ rời khỏi cuộc sống Charlestown của họ trên giá trị của chính họ, khu phố nơi có một mã viết thư để bảo vệ lối sống đó. Những tên cướp như vậy bao gồm bạn bè Doug Macray, James Coughlin, Albert Gleansy Magloan và Desmond Elden. Doug và James đặc biệt đối xử với nhau như gia đình, vì những cơn co cố thực sự như vậy để doug kể từ khi mẹ của Doug chạy ra ngoài và cha của Doug, Stephen Macray, đã bị tống vào tù. Chị gái độc thân của James, Krista Coughlin bị ma túy, và Doug có một mối quan hệ tình dục bình thường. Foursome thực hiện một vụ cướp ngân hàng chủ yếu thành công, nhưng do hoàn cảnh, hãy tham gia quản lý ngân hàng, Claire Keesey, con tin trong một thời gian ngắn trước khi phát hành không hề hấn gì về thể chất. Họ phát hiện ra rằng Claire sống ở Charlestown, vì vậy họ muốn đảm bảo rằng cô ấy không thấy bất cứ điều gì có thể buộc tội họ nếu họ từng gặp cô ấy. Như vậy, Doug bắt đầu một mối quan hệ cá nhân với cô ấy để tìm hiểu những gì cô ấy biết và những gì cô ấy đã nói với cảnh sát và FBI, người đã chịu trách nhiệm điều tra. Anh ta biết rằng cô ấy đã giữ một số thông tin từ chính quyền để bảo vệ mình nhưng thông tin có thể xác định quy định cụ thể của James. Nhưng Doug từ từ rơi cho cô, như cô làm cho anh. Cuối cùng, Doug mơ ước rời khỏi cuộc sống Charlestown của mình để được với Claire bất cứ nơi nào nhưng ở đó. Nhưng Doug phải cố gắng và giữ nhận dạng thực sự của mình từ cô ấy, và giữ cho thực tế rằng anh ấy đang nhìn thấy cô ấy từ các đồng nghiệp của mình. Nhưng rời đi không dễ như anh ta muốn như anh ta và băng đảng được một công việc lớn của một tay xã hội đen địa phương có tên là Fergie dù Doug thích hay không. Và Adam Frawley, điều tra viên chính của FBI, đi vào bằng chứng liên kết với bốn người cướp ngân hàng và một chiếc xe bọc thép bọc thép tiếp theo, vì vậy là trên đuôi của họ để có bằng chứng sẽ khiến họ bị mất hoặc sống.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
