INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-ransom', 'Black Ransom', 'Black Ransom', 'https://phimimg.com/upload/vod/20231215-1/f2f766784757b69c3c55139169ad6015.jpg', 'https://phimimg.com/upload/vod/20231215-1/ad056707e75b52b116bb75e1576a099c.jpg', '<p>Một ông chủ mạnh mẽ của hội tam hoàng đã bị bắt cóc, và giám đốc cảnh sát mới Koo quyết định tuyển dụng sự giúp đỡ của Mann, một cựu siêu cảnh sát đã bị giáng xuống làm nhiệm vụ hỗ trợ. Mann bị cắt giảm công việc khi nhận ra đối thủ của mình là Sam, một cựu cảnh sát có nhiều mối hận. Khi Sam chiến đấu với gia đình Mann, Mann càng quyết tâm hạ gục kẻ bắt cóc nguy hiểm và băng nhóm của hắn.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fala Chen","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Andy On","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Tak-bun Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
