INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-nghiep', 'Thất Nghiệp', 'The Company Men', 'https://phimimg.com/upload/vod/20231219-1/344dbb1e5537b0c6a5f26613f6b76a20.jpg', 'https://phimimg.com/upload/vod/20231219-1/8f47b80c4afccf4b3d727b8083e8e603.jpg', '<p>Bobby Walker sống trong giấc mơ Mỹ: công việc tuyệt vời, gia đình hạnh phúc, chiếc Porsche bóng loáng trong gara. Khi công ty thu hẹp quy mô khiến anh và hai đồng nghiệp thất nghiệp, ba người đàn ông buộc phải xác định lại cuộc sống của họ với tư cách là những người đàn ông, người chồng và người cha.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Maria Bello","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
