INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-kim-jong-wook', 'Đi Tìm Kim Jong Wook', 'Finding Mr. Destiny', 'https://phimimg.com/upload/vod/20231215-1/311b56258674a73f161dc98d3f51dc15.jpg', 'https://phimimg.com/upload/vod/20231215-1/39d1573af9c3d7ceeab2b9d0dc21ea08.jpg', '<p>Seo Ji Woo (Im Soo Jung) là một đạo diễn sân khấu, cô luôn sống độc thân vì chưa quên được mối tình đầu. Để giúp con gái, bố cô nhờ tới văn phòng “Tìm kiếm mối tình đầu” của Han Ki Joon (Gong Yoo). Họ cùng nhau tìm kiếm một người tên là Kim Jong Wook - mối tình đầu của Seo Ji Woo. Seo Ji Woo vốn không phối hợp nhưng bất lực trước cố chấp của Han Ki Joon và bị bố cằn nhằn, nên cô đồng ý. Kim Jong Wook lại xuất hiện khi tình cảm giữa Han Ki và Ji Woo có biến đổi. Liệu 3 người họ sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Gong","avatar":""},{"name":"Im Soo-jung","avatar":""},{"name":"Qian Hu Zhen","avatar":""},{"name":"Qian Hu Zhen","avatar":""},{"name":"Seung-soo Ryu","avatar":""},{"name":"Cheong-a Lee","avatar":""},{"name":"Young-nam Jang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
