INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scoobydoo-hoc-vien-ao-thuat', 'Scooby-Doo! Học Viện Ảo Thuật', 'Scooby-Doo! Abracadabra-Doo', 'https://phimimg.com/upload/vod/20231215-1/170bcda4157b74050ee97baa527345b9.jpg', 'https://phimimg.com/upload/vod/20231215-1/8b7b6ecdcf94b9d8740feff889c80fab.jpg', '<p>Lần này, nhóm bạn cùng nhau đến thăm cô em họ Madelyn của Velma. Madelyn đang học ảo thuật tại Học viện ảo thuật Whirlen Merlin, nơi đang có sự xuất hiện của con quái vật sư tử đầu chim khổng lồ. Như mọi lần, họ quyết định điều tra cho ra sự việc.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mindy Cohn","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Frank Welker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
