INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-trong-dam-tang', 'Cái Chết Trong Đám Tang', 'Death At A Funeral', 'https://phimimg.com/upload/vod/20231214-1/5677d3dcf6bb4d4a2059fdc32d314521.jpg', 'https://phimimg.com/upload/vod/20231214-1/cb34ad1574649c0cf6b57330c10834c5.jpg', '<p>Khi người đàn ông đứng đầu của một gia đình ở Los Angeles qua đời, anh con cả lên kế hoạch cho tang lễ. Lễ tang đó đã trở thành thảm họa nhờ dàn khách viếng phong phú.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Rock","avatar":""},{"name":"Martin Lawrence","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Columbus Short","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Regine Nehy","avatar":""},{"name":"Keith David","avatar":""},{"name":"Ron Glass","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
