INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cai-chet-trong-dam-tang', 'Cái Chết Trong Đám Tang', 'Death At A Funeral', 'cái chết trong đám tang death at a funeral chris rock martin lawrence tracy morgan danny glover james marsden luke wilson zoe saldaña regina hall columbus short peter dinklage kevin hart loretta devine regine nehy keith david ron glass ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-gui-juliet', 'Thư Gửi Juliet', 'Letters To Juliet', 'https://phimimg.com/upload/vod/20231214-1/ffaeb75f39a5668fd09db91088c65ffc.jpg', 'https://phimimg.com/upload/vod/20231214-1/41669317b566399dc11b76b973a6fc9e.jpg', '<p>Shopie đang cùng chồng chưa cưới đi nghỉ mát trong chuyến “tiền trăng mật” của mình. Thế nhưng, chuyến đi đến Verona đã làm thay đổi cả cuộc đời Shopie khi cô tìm được một bức tường chứa đầy những lá thư của một người lạ mặt gửi đến Juliet – một nhân vật của Shakespeare. Bức thư của một cô gái trẻ kể về mối tình của cô vào năm 1957, và cô mất liên lạc với “Romeo” của mình từ đó. Cảm động vì mối tình bền bỉ của người con gái đó, Shopie đã viết trả lại, như một lời tri ân tình cảm. Không thể ngờ rằng, Claire, cô gái viết bức thư xin lời khuyên từ Juliet đó vẫn còn sống. Nhận được thư trả lời, cô gái trẻ, nay đã thành một thiếu phụ như sống lại những khoảnh khắc tình yêu quý giá trong cuộc đời mình. Cô quyết định cùng cháu trai của mình đi từ Mỹ tới Ý để gặp Shopie. Được động viên, cả ba người cùng bắt đầu chuyến hành trình tìm lại người yêu cũ của Claire. Để rồi từ đó, chuyến hành trình đã giúp ba con người xích lại gần nhau hơn, và tìm được tình yêu đích thực của chính cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Vanessa Redgrave","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
