INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-set-danh', 'Tình Yêu Sét Đánh', 'A Little Thing Called Love', 'https://phimimg.com/upload/vod/20231213-1/736ce656181515735daa37fb8b140465.jpg', 'https://phimimg.com/upload/vod/20231213-1/9c3e29045718e57eeb9bab6bc6608075.jpg', '<p>Cuộc sống của một cô gái 14 tuổi Nam, người yêu cao cấp lớp mười của cô và cố gắng hết sức để giành được sự chú ý của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
