INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-o-luan-don', 'Sứ Mệnh Ở Luân Đôn', 'Mission London', 'https://phimimg.com/upload/vod/20231213-1/9eb3acdc6ac03453c88e4851c6bc5c60.jpg', 'https://phimimg.com/upload/vod/20231213-1/18a7c7f42f0e1e00ac428e3ae3326893.jpg', '<p>Một buổi hòa nhạc kỷ niệm việc Bulgari gia nhập EU đang được lên kế hoạch tại Đại sứ quán ở London và nhiệm vụ của VARADIN, đại sứ mới, là đảm bảo Nữ hoàng tham dự. Nhưng với những nhân viên tham nhũng, các băng đảng tội phạm hoạt động ngoài bếp, yêu một vũ nữ thoát y và một chút hiểu lầm với một công ty PR cung cấp tiền bản quyền trông giống nhau - nhiệm vụ đơn giản của anh ấy biến thành một cơn ác mộng hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Alan Ford","avatar":""},{"name":"Tomas Arana","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"Georgi Staykov","avatar":""},{"name":"Julian Vergov","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
