INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-hoat-dong-nhu-the-nao-phan-1', 'Vũ Trụ Hoạt động Như Thế Nào (Phần 1)', 'How The Universe Works (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/b5300b0551a9219c67cb1ada1ab37120.jpg', 'https://phimimg.com/upload/vod/20231219-1/76fc2879ef8882a97686593f49a4b98d.jpg', '<p>Hướng dẫn dành cho người dùng về vũ trụ, từ Vụ nổ lớn đến các thiên hà, ngôi sao, hành tinh và mặt trăng: tất cả đến từ đâu và làm thế nào để tất cả khớp với nhau? Một cuốn sách sơ lược dành cho những ai đã từng nhìn lên bầu trời đêm và tự hỏi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324474);
