INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-cua-co-temple-grandin', 'Chuyện Của Cô Temple Grandin', 'Temple Grandin', 'https://phimimg.com/upload/vod/20231211-1/140281a9b3c40f6ce55277018fd3a6a6.jpg', 'https://phimimg.com/upload/vod/20231211-1/1af92fcadb16a478e2b33752bb980a6a.jpg', '<p>Temple Grandin là bộ phim của đạo diễn Mick Jackson thuộc thể loại tâm lý tình cảm. Phim kể về Temple Grandin, một phụ nữ trẻ mắc chứng tự kỷ, trải qua điều trị kịp thời và với ý chí vô cùng mạnh mẽ, đã trở thành một trong những câu chuyện thành công nhất nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 6, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Claire Danes","avatar":""},{"name":"Julia Ormond","avatar":""},{"name":"David Strathairn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
