INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-ca', 'Thi Ca', 'Poetry', 'https://phimimg.com/upload/vod/20231211-1/014640999a829f8017faed661ca6ef57.jpg', 'https://phimimg.com/upload/vod/20231211-1/64a3c1b885cb316c2ee173f65e1180bc.jpg', '<p>Mija, người phụ nữ đã lớn tuổi phát hiện ra mình đang trong giai đoạn đầu của căn bệnh Alzheimer. Hàng ngày, bà phải đi chăm sóc cho một người đàn ông già để lấy tiền nuôi bản thân và đứa cháu trai khó bảo. Thú vui duy nhất của Mija là lớp học làm thơ tại trung tâm văn hóa địa phương. Cho đến một ngày, bà hay tin, người cháu trai dính líu đến một băng đảng đã cưỡng hiếp một học sinh nữ khiến cô bé này phải tự tử.. Vai trò của thơ ca và của nghệ thuật, và căn bệnh của nữ nhân vật chính - liệu những khi quên lãng có phải là do căn bệnh, hay đó chỉ là cách tự giải thoát?</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoon Jeong-hee","avatar":""},{"name":"Lee Da-wit","avatar":""},{"name":"Kim Hee-ra","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kim Yong-taek","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
