INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-tang-hinh', 'Chàng Trai Tàng Hình', 'Oh! Invisible Man', 'https://phimimg.com/upload/vod/20231211-1/58aa0b44f7ab22c3bceecc3d0fbee577.jpg', 'https://phimimg.com/upload/vod/20231211-1/a9abe88c6fcb91066f1c9099f86ea0a8.jpg', '<p>Live action chuyển thể từ phim hoạt hình và truyện tranh. Câu chuyện tập trung vào một nam sinh trung học sống trong một gia đình toàn nữ. Khi anh ấy phát hiện ra rằng mình có thể tàng hình, điều đó đương nhiên dẫn đến những tình huống mạo hiểm, đặc biệt là liên quan đến những cô gái mà anh ấy sống cùng.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Emi Yanagimoto","avatar":""},{"name":"Yuri Murakami","avatar":""},{"name":"Enoku Shimegi","avatar":""},{"name":"Yû Kawana","avatar":""},{"name":"Maika Suzuki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
