INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-lam-me', 'Âm Mưu Làm Mẹ', 'Locked Away', 'https://phimimg.com/upload/vod/20231211-1/c48b3c16944f9b6400a8b0f5c988d307.jpg', 'https://phimimg.com/upload/vod/20231211-1/22c7dcc690db10c401dd47ef3f555cab.jpg', '<p>Âm Mưu Làm Mẹ - Locked Away bắt đầu khi cô bé Taylin - một học sinh năm cuối cấp ba - nói với Sasha, mẹ của mình rằng cô đang mang thai với bạn trai Kevin. Sasha muốn Taylin cho đứa bé làm con nuôi, tuy nhiên cô bé quyết định tìm đến lời khuyên của cố vấn thai nghén Chloe. Điều mà Taylin không biết là Chloe đã muốn có con từ khá lâu và không thể có một đứa con của riêng mình. Cô ta sẵn sàng làm điều không tưởng để lấy đứa con mà Taylin đang mang.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean Louisa Kelly","avatar":""},{"name":"Kirsten Zien","avatar":""},{"name":"Paula Trickey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
