INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-muu-lam-me', 'Âm Mưu Làm Mẹ', 'Locked Away', 'âm mưu làm mẹ locked away jean louisa kelly kirsten zien paula trickey ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-niem-hanh-phuc', 'Cảm Ơn Niềm Hạnh Phúc', 'Happythankyoumoreplease', 'https://phimimg.com/upload/vod/20231211-1/7ca76f3a28450d4068e84fb536583a6b.jpg', 'https://phimimg.com/upload/vod/20231211-1/9a2b00b57e2931d114510b5c6e3c94bb.jpg', '<p>Ghi lại khoảnh khắc mang tính thế hệ - những người trẻ tuổi đang trên đà trưởng thành thực sự, mệt mỏi với tính hoài nghi theo phản xạ của họ, mỗi người theo cách riêng của mình đấu tranh để kết nối và xác định ý nghĩa của việc yêu và được yêu. Sáu người New York tung hứng tình yêu, tình bạn và bóng ma thách thức sâu sắc của tuổi trưởng thành. Sam Wexler là một nhà văn đang gặp khó khăn và đang có một ngày đặc biệt tồi tệ. Khi một cậu bé bị tách khỏi gia đình trên tàu điện ngầm, Sam đã đưa ra một quyết định đáng ngờ là đưa cậu bé trở về căn hộ của mình và từ đó bắt đầu một tình bạn bổ ích nhưng phức tạp. Cuộc sống của Sam xoay quanh những người bạn của anh ấy - Annie, người có hình ảnh bản thân khiến cô ấy không cam kết; Charlie và Mary Catherine, một cặp đôi có thể chuyển đến Los Angeles để kiểm tra mối quan hệ của họ; và Mississippi, một ca sĩ quán rượu lọt vào mắt xanh của Sam.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Pablo Schreiber","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
