INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-an-vui-nhon-working', 'Quán Ăn Vui Nhộn - Working!!', 'Messy Restaurant, Wagnaria!!', 'https://phimimg.com/upload/vod/20231219-1/7cd832345f12689ad3565684f5b75714.jpg', 'https://phimimg.com/upload/vod/20231219-1/467e4f8d47fd9207e82d950c40cd9b83.jpg', '<p>Tại một quán ăn gia đình tại Hokkaido, Takanashi Souta, một học sinh 16 tuổi đang làm thêm cùng với những người bạn lạ lùng của mình: Taneshima Popura, một senpai lớn hơn cậu 1 tuổi nhưng thường bị tưởng lầm là học sinh tiểu học. Shirafuji Kyouko, 26 tuổi, một bà chị quản lý nóng tính và những nhân viên có lòng nhiệt huyết tràn trề khác cùng những bí ẩn xoay quanh họ.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
