INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-giac', 'Tố Giác', 'The Whistleblower', 'https://phimimg.com/upload/vod/20231212-1/cf9db189810b889d6c6ca32ae494c9f5.jpg', 'https://phimimg.com/upload/vod/20231212-1/1f1c456e646af38f7616bdcd96dc1f0c.jpg', '<p>The Whistleblower được dựng trên một cốt truyện có thật, xoay quanh nhân vật Kathryn Bolkovac, một cảnh sát Mỹ có nhiệm vụ đến Bosnia thực hiện quá trình kiến tạo hòa bình ở nước này sau chiến tranh. Với vai trò huấn luyện cảnh sát Bosnia, Kathryn đã phát hiện ra bí mật khủng khiếp về một ngành công nghiệp buôn người ngầm có liên quan đến các nhà thầu quân sự Mỹ và thậm chí cả Liên hợp quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
