INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tu', 'Khổng Tử', 'Confucius', 'https://phimimg.com/upload/vod/20231212-1/d21f1f3228396049e51e08c6a6f905cd.jpg', 'https://phimimg.com/upload/vod/20231212-1/0629a522a6ddd1652d8852ca52be8da5.jpg', '<p>Phim Khổng Tử chính là cuộc đời của triết gia nổi tiếng Trung Hoa Khổng Tử sống cách nay hơn 2 thiên niên kỷ (551–479 TCN). Ở tuổi 55, Khổng Tử là thượng thư bộ hình của nước Lỗ nhưng do thất vọng nên rời bỏ nước này. Trong phim hd này, ông tới nhiều nước, truyền bá tư tưởng triết học của chính mình nhưng ít được vị vương hầu nào thực sự để ý. Khổng Tử có rất nhiều đệ tử, cũng giống như Phật Thích ca, Chúa Jesus hay Thánh Muhammad. Nhưng ông không phải là người sáng lập một thứ tôn giáo mà trở thành thầy giáo. Tư tưởng triết học của ông, gọi là Khổng giáo, được hậu thế truyền bá, phát triển, để 6 thế kỷ sau khi ông mất, nhà Hán lấy đó làm triết lý duy nhất để trị nước. Xem phim Khổng Tử và trải nghiệm những công nghệ phim online tuyệt vời!</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Châu Tấn","avatar":""},{"name":"Lục Nghị","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
