INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jonah-hex-trum-san-tien-thuong', 'Jonah Hex: Trùm Săn Tiền Thưởng', 'Jonah Hex', 'https://phimimg.com/upload/vod/20231211-1/b69247d9bd3836c3f70d507aa46e6948.jpg', 'https://phimimg.com/upload/vod/20231211-1/fbac4efb5217059408b0421a52a320b5.jpg', '<p>Trong nhiệm kỳ tổng thống của Grant, Jonah Hex là một thợ săn tiền thưởng hiếm hoi. Trong cuộc nội chiến, anh ta là một kẻ nổi loạn có vinh danh đã đặt anh ta afoul của một tướng quân, Quentin Turnbull, người đã giết gia đình Jonah trong khi Jonah nhìn theo dõi. Kết quả của thử thách, khuôn mặt của Jonah bị biến dạng và anh ta có thể nói chuyện với người chết. Sau khi dàn dựng cái chết của chính mình, Turnbull, với một nhóm rebel stalwarts, nở một kế hoạch để đưa sự kết hợp đến đầu gối của nó. Grant muốn hex để ngăn chặn nó. Trong khi quốc gia sẵn sàng kỷ niệm Ngày quốc khánh, Hex và một đồng minh không có khả năng có ít thời gian để ngăn chặn Turnbull và vũ khí hủy diệt hàng loạt của anh ta.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
