INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('jonah-hex-trum-san-tien-thuong', 'Jonah Hex: Trùm Săn Tiền Thưởng', 'Jonah Hex', 'jonah hex: trùm săn tiền thưởng jonah hex  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-van-cua-nha-vua', 'Diễn Văn Của Nhà Vua', 'The King''s Speech', 'https://phimimg.com/upload/vod/20231211-1/7611b92a121a0207e73ec8be748a666e.jpg', 'https://phimimg.com/upload/vod/20231211-1/415d453713890da9db7d3f1eac2d4024.jpg', '<p>Câu chuyện kể về vua George VI, cha của nữ hoàng Elizabeth II. George (Bertie) vốn không hề nghĩ đến chuyện mình sẽ kế vị ngai vàng cho tới khi anh trai ông là Edward VIII quyết định từ bỏ ngôi vua để làm đám cưới với người phụ nữ mong muốn. Tuy nhiên, khả năng diễn thuyết của George quá tệ đến mức ông phải nhờ tới một người tư vấn với những phương pháp rèn luyện không giống ai, dẫn tới một tình bạn khăng khít giữa hai người và George VI đã dũng cảm lãnh đạo nhân dân Anh quốc đi qua thời kỳ chiến tranh.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Helena Bonham Carter","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
