INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-khoi-dau', 'Những Người Khởi Đầu', 'Beginners', 'https://phimimg.com/upload/vod/20231211-1/07c6d6f50817ef52fe6a6dd6a764c6da.jpg', 'https://phimimg.com/upload/vod/20231211-1/b3d9c3f4e785de1952d38a0fb080fe46.jpg', '<p>Những Người Khởi Đầu là một bộ phim hài kịch tình cảm của Mỹ được sản xuất vào năm 2010, được biên kịch và đạo diễn bởi Mike Mills. Nội dung phim được dựa trên câu chuyện có thật của chính cha của đạo diễn Mills, 5 năm trước khi mất ông đã thừa nhận mình là người đồng tính ở tuổi 75. Bộ phim mang đến thông điệp đầy ý nghĩa là câu trả lời cho câu hỏi của nhân vật Hal: Sống là phải liên tục sẵn sàng đối mặt với những điều bất ngờ mà cuộc đời thảy vào bạn mỗi buổi sớm mai. Ai cũng mong có được những món quà đẹp đẽ, nhưng biết làm gì khi chúng ta chẳng thể nào tự quyết định những gì mình sẽ nhận?</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Cosmo","avatar":""},{"name":"Goran Visnjic","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
