INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-hai-nam-gap-trieu-chau', 'Khi Hải Nam Gặp Triều Châu', 'When Hainan Meets Teochew', 'https://phimimg.com/upload/vod/20231211-1/f83c7fa00fc051f634497ae0a7d666d9.jpg', 'https://phimimg.com/upload/vod/20231211-1/8f595875fa20287d434b6801501409be.jpg', '<p>Trong phim hài giới tính uốn cong này, hảo cảm bất ngờ nảy sinh khi Triều Châu tình cờ nhặt được chiếc áo lót của Hải Nam.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lý Chiêu Mẫn","avatar":""},{"name":"Tan Hong Chye","avatar":""},{"name":"Dương Nhạn Nhạn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
