INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gulliver-du-ky', 'Gulliver Du Ký', 'Gulliver''s Travels', 'https://phimimg.com/upload/vod/20240104-1/52c86a1b9d9b1efdeae1e099d6b77c06.jpg', 'https://phimimg.com/upload/vod/20240104-1/a0aa8f2ba86182a807b0a96e82ac2da5.jpg', '<p>Lemuel Gulliver (Jack Black) đã làm việc trong phòng thư của một tờ báo hàng ngày New York trong mười năm qua. Sợ để đưa mình ra khỏi đó, anh coi mình là một kẻ thua cuộc, cũng như tất cả các đồng nghiệp của mình. Một ngày nọ, sau khi cuối cùng đã có đủ, anh ta quyết định tuyên bố tình yêu của mình với Darcy Silverman xinh đẹp (Amanda Peet), biên tập viên du lịch của tờ báo và một trong những người bạn duy nhất của Gulliver, chỉ để gà ra vào phút cuối và thay vào đó hãy nói với cô ấy rằng anh ta D thích thử tay viết một cột. Darcy chấp nhận và gửi cho anh ta một nhiệm vụ cho Tam giác Bermuda. Ở đó, Gulliver trở nên đắm tàu và kết thúc trên đảo Liliput, nơi anh cao gấp mười hai lần so với người đàn ông cao nhất. Lần đầu tiên, Gulliver có những người nhìn lên anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
