INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-trinh-lat-tay', 'Chương Trình Lật Tẩy', 'Operation: Endgame', 'https://phimimg.com/upload/vod/20231211-1/f3789d21485b5edf79c6a69d560b5da2.jpg', 'https://phimimg.com/upload/vod/20231211-1/3fff31d37ef06662a4db69f0e4ae1370.jpg', '<p>Một trận chiến xảy ra giữa hai đội gián điệp của chính phủ trong một cơ sở ngầm sau khi ông chủ của họ bị ám sát.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Anderson","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Maggie Q","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
