INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-tam-mai-moi', 'Trung Tâm Mai Mối', 'Cyrano Agency', 'https://phimimg.com/upload/vod/20240102-1/dc808512cc5c9dc3e7c5e8148d64827a.jpg', 'https://phimimg.com/upload/vod/20240102-1/2c4d2790b868977659c1419263b2d456.jpg', '<p>Cyrano Agency là một Trung tâm mai mối cho những người xa lạ với mục tiêu đạt tỷ lệ thành công đến 100%. Đôi khi nó hoạt động như các trường quay, đôi khi lại là những kịch bản được xây dựng hoàn hảo như một kế hoạch tác chiến bí mật để giúp các thân chủ tìm được tình yêu. Phương châm của trung tâm chính là “Làm việc ở cõi âm chứ không hướng đến cõi dương”, giúp cho các khách hàng tìm được tình yêu bằng phương thức thầm kín nhất. Trung tâm mai mối Cyrano được thành lập bởi 4 thành viên của một sân khấu kịch với khách hàng là những anh chàng đang yêu đơn phương trong vô vọng. Bằng kỹ năng sân khấu, trí tưởng tượng bay bổng và các phương tiện kỹ thuật hiện đại, các “chuyên gia” của Cyrano luôn thành công trong việc tạo ra những tình huống lãng mạn, những lời thoại trau chuốt khiến cho bất cứ cô nàng nào cũng cảm thấy trái tim mình đang rung động.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Tae-woong Eom","avatar":""},{"name":"Min-jung Lee","avatar":""},{"name":"Daniel Choi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
