INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-tu-si', 'Linh Hồn Tử Sĩ', 'Valhalla Rising', 'https://phimimg.com/upload/vod/20231211-1/d7f2c9e325c0d32b80e63304f0971921.jpg', 'https://phimimg.com/upload/vod/20231211-1/94f8c3ac57f6678d8fc44c170f9ba04a.jpg', '<p>Phim xoay quanh nhân vật One-Eye câm lặng, một thủ lĩnh Viking, lòng quả cảm của anh chỉ có thể so sánh với sức mạnh siêu nhiên anh có. Trốn khỏi kiếp nô lệ, anh dong thuyền cùng với những binh lính theo đạo Thiên chúa đi tìm Đất thánh. Nhưng thay vì vậy, anh thấy mình bị lạc trong một lãnh địa lạ lẫm và nguy hiểm trùng trùng...</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mads Mikkelsen","avatar":""},{"name":"Maarten Stevenson","avatar":""},{"name":"Alexander Morton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324474);
