INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lu-tre-deu-on', 'Lũ Trẻ Đều Ổn', 'The Kids Are All Right', 'https://phimimg.com/upload/vod/20231211-1/2ced1a876bcca98be36c3b1a9baa9264.jpg', 'https://phimimg.com/upload/vod/20231211-1/8b0f34a6d2f6cd9f50303aefa88c8222.jpg', '<p>Mối quan hệ giữa Nic và Jules kéo dài đã lâu, gắn bó và thương yêu nhưng không hẳn là hoàn hảo. Nic, một nhà vật lý học, cần phải nắm bắt những gì mà cô ấy tin rằng đó là sự điểu khiển, trong khi Jules, cũng dưới sự điều khiển đó, lại ít quả quyết hơn. Trong mối quan hệ của họ, Jules loạng choạng trong cuộc sống nửa vời của mình, đôi khi cố gắng bắt đầu một việc kinh doanh - để rồi luôn luôn thất bại – hay việc ở nhà làm một người mẹ. Cô ấy đang bắt đầu công việc thiết kế quang cảnh. Họ có 2 con đang ở độ tuổi thiếu niên, Joni và Laser, Nic là mẹ đẻ của Joni và Jules là mẹ ruột của Laser. Dù không giống nhau hoàn toàn, mỗi đứa đều mang nét tương đồng với mẹ ruột về tính cách. Joni và Laser là anh em cùng mẹ khác cha, cha họ là những người cho tinh trùng vô danh. Không lâu sau sinh nhật lần thứ 18 của Joni và trước khi cô bé định chuyển nhà để học đại học, Laser, chỉ mới 15 và không đủ tuổi để làm điều đó...</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Annette Bening","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Mark Ruffalo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
