INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-ba-tinh', 'Ngã Ba Tình', 'Love, In Between', 'https://phimimg.com/upload/vod/20231230-1/7ca67f95ccc80c9a9b453de85f7a60cd.jpg', 'https://phimimg.com/upload/vod/20231230-1/8326d948dc494ca53dfdcb80c1bf7d13.jpg', '<p>Trước đây được gọi là Hai người phụ nữ hoặc Mưa đóng băng. Một người đàn ông muốn tất cả tình yêu, một người vợ tiếp cận người phụ nữ khác của chồng và một người phụ nữ muốn giữ tình yêu của mình. Một bộ phim tình cảm sang trọng về ba người này và cuộc gặp gỡ đầy rủi ro của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Eun-kyung","avatar":""},{"name":"Jung Joon-ho","avatar":""},{"name":"Shim Yi-young","avatar":""},{"name":"Choi Jae-won","avatar":""},{"name":"Kwon Seong-min","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
