INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tu-bao-thu', 'Nữ Tu Báo Thù', 'Nude Nuns With Big Guns', 'https://phimimg.com/upload/vod/20231211-1/36cc59f39cb80404e081f5996a4440e9.jpg', 'https://phimimg.com/upload/vod/20231211-1/ea4d9767cab1b0c3381811330fa8d5c8.jpg', '<p>Khi thực hiện lời thề trở thành một nữ tu, Sơ Sarah bị lạm dụng, tẩy não và cũng bị đánh thuốc mê bởi các giáo sĩ đồi bại. Trước cái chết của chính mình vì một liều thuốc gây chết người, Chị Sarah nhận được một thông điệp từ Chúa bảo chị hãy trả thù tất cả những kẻ đã làm điều sai trái với chị. Được trang bị ý chí của Chúa và một kho vũ khí lớn, cô đưa ra Ngày phán xét cho những kẻ hành hạ mình trước đây. Khi nhà thờ thuê băng nhóm mô tô tàn nhẫn Los Muertos để truy tìm và giết cô ấy, họ sớm nhận ra rằng chị gái này là một người mẹ tồi.</p>', 'Full', 1, 'single', 'completed', 6, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Asun Ortega","avatar":""},{"name":"Bill Oberst Jr.","avatar":""},{"name":"Ivet Corvea","avatar":""},{"name":"Devanny Pinn","avatar":""},{"name":"Tawny Amber Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
