INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-nha-ben', 'Án Mạng Nhà Bên', 'Good Neighbours', 'https://phimimg.com/upload/vod/20231209-1/f17b66eadb7fb0e82bc52ef41f19424b.jpg', 'https://phimimg.com/upload/vod/20231209-1/3969565cd0409755ee2e7b0eb9f5b834.jpg', '<p>Một chàng trai tên Victor, người mới đến Montreal và cố gắng kết bạn với Spencer ngồi xe lăn và Louise yêu mèo, nhưng mọi người đều đang phải đối mặt với một kẻ giết người hàng loạt đang khủng bố khu phố. Kẻ giết người kinh dị bí ẩn đấy vẫn chưa lộ diện và reo rắc sự kinh hoàng vào tâm trí mọi người, liệu số phận của mọi người sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jay Baruchel","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Emily Hampshire","avatar":""},{"name":"Gary Farmer","avatar":""},{"name":"Xavier Dolan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
