INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-bac-kiem-quy-benizakura', 'Linh Hồn Bạc: Kiếm Quỷ Benizakura', 'Gintama: The Movie', 'https://phimimg.com/upload/vod/20231209-1/e49d74d0b86e2ded30bfc119e28506aa.jpg', 'https://phimimg.com/upload/vod/20231209-1/69e7523e4a41546e0f31ef2b03d436f1.jpg', '<p>Thời kỳ Edo Nhật Bản, một người đàn ông bí ẩn xuất hiện trước samurai Katsura Kotarou và cầm thanh kiếm “Benizakura” hỏi Katsura so tài với mình. Sau đêm này, Katsura mất tích mà thú cưng của anh là Elizabeth ủy thác Kagura và Shinpachi tìm tăm tích của chủ nhân. Bên cạnh đó, Gintoki cũng được người khác ủy thác đi tìm tăm tích của Benizakura đang làm loạn khắp nơi. Manh mối cả ba người tìm được đều chỉ về một phi thuyền trên không và thế lực độc ác trong phi thuyền hống hách lộng hành bởi không thuộc phạm vi cảnh sát quản lý. Ở nơi đó, Gintoki còn gặp lại đồng đội cũ và đối thủ hiện nay Takasugi Shinsuke. Takasugi đang dẫn đội quân quỷ hòng phá hủy Edo. Đối mặt với phần tử khủng bố hung hãn tàn bạo và thanh kiếm Benizakura kỳ lạ, Gintoki bị thương nặng có khả năng thoát hiểm và cứu Edo hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sugita Tomokazu","avatar":""},{"name":"Ban Kou Da Zhu","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Shi Tian Zhang","avatar":""},{"name":"Koyasu Takehito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324474);
