INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('22-vien-dan', '22 Viên Đạn', '22 Bullets', 'null', 'https://phimimg.com/upload/vod/20231210-1/f239ec21a39870dca71056a21c2c630d.jpg', '<p>Charly Mattei, một tên trùm mafia hoàn lương, đang có một cuộc sống hạnh phúc cùng vợ và con. Cho đến một ngày, cái quá khứ của một kẻ ngoài vòng pháp luật lại đeo bám anh, một nhóm 8 người đã bắn lén và bỏ lại anh cho đến chết tại một bãi đậu xe của Old Port tại Marseille với 22 viên đạn trong cơ thể. May mắn thoát chết, anh quyết định đi trả thù kẻ đã hãm hại mình. Anh tìm đến nhóm người đã tấn công anh với lời cảnh cáo sẽ giết chết từng người một vào bất cứ lúc nào và bất cứ nơi đâu, đồng thời anh cũng phát hiện ra một trong những người phục kích anh trong vụ này chính là người bạn thân thời thơ ấu của mình, Tony Zacchia, Marie Goldman, một nữ cảnh sát có chồng cũng là một nhân viên cảnh sát và đã hi sinh trong khi thi hành nhiệm vụ nhưng hung thủ thì vẫn ung dung ngoài vòng pháp luật, chính là người điều tra vụ nổ súng ở hầm xe của Charlie. Và cô luôn muốn điều tra rõ cái chết của chồng mình, và cô nghi ngờ là do người của Tony Zacchia làm. Để bắt được Tony, Charlie đề ra yêu cầu hợp tác với Marie. Cảnh sát đang nắm giữ một USB chứa chứng cứ phạm tội các hoạt động rửa tiền của Tony. Cuối cùng họ cũng tóm được Tony, nhưng lúc này thì Marie tiết lộ cho Charlie biết một thông tin về vụ bắn súng ở hầm xe. Một người trong nhóm phục kích Charlie ở bãi xe đã cố tình không bắn trúng anh, và người đó cũng chính là bạn anh, Tony Zacchia, nên anh đã quyết định tha thứ cho Tony.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Thuyết Minh', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Jean-Pierre Darroussin","avatar":""},{"name":"Kad Merad","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
