INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-dung-cam', 'Chiến Binh Dũng Cảm', 'Veer', 'https://phimimg.com/upload/vod/20231210-1/dcdf49b08ad946a5014ee3698f593ba1.jpg', 'https://phimimg.com/upload/vod/20231210-1/bc2da09f2243e141c7d5aea851df8d81.jpg', '<p>Một Hoàng tử Pindari đến Anh để học các chiến thuật quân sự để có thể trả thù cho người dân của mình, nhưng khi ở đó, anh ta đã yêu.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Mithun Chakraborty","avatar":""},{"name":"Jackie Shroff","avatar":""},{"name":"Sohail Khan","avatar":""},{"name":"Raj Khatri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
