INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ho-to-khat-nhi', 'Mãnh Hổ Tô Khất Nhi', 'True Legend', 'https://phimimg.com/upload/vod/20231209-1/25ae2bde68f9c5fc0ddec4734e9564d3.jpg', 'https://phimimg.com/upload/vod/20231209-1/36d5c24c673882149a1b22f7cd767cb3.jpg', '<p>Bối cảnh câu chuyện xảy ra vào thời nhà Thanh, khi các nước bắt đầu ồ ạt nhảy vào hòng chia năm xẻ bảy Trung Quốc. Tô Khất Nhi sinh sống tại vùng Hắc Long Giang cũng phải chịu không ít áp bức của người Nga. Con trai của Tô Khất Nhi bị người Nga ức hiếp tới mức gần như sắp phải bỏ mạng nơi biên giới. Chứng kiến cảnh người thân yêu duy nhất của mình gặp nguy hiểm đã đốt cháy ngọn lửa trong tâm can Tô Khất Nhi, nguồn năng lượng bấy lâu bị kìm nén bên trong giờ đã bộc phát, đưa Tô Khất Nhi đến với cảnh giới cao nhất trong võ học mà bao lâu nay vẫn đang tìm kiếm...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wenzhuo Zhao","avatar":""},{"name":"Xun Zhou","avatar":""},{"name":"Andy On","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
