INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-toi-cua-tu', 'Đường Tới Cửa Tử', 'The Sylvian Experiments', 'https://phimimg.com/upload/vod/20231209-1/251f6b1a0a4ed5b8caf2a90a9c14c482.jpg', 'https://phimimg.com/upload/vod/20231209-1/1bbae7825fd4d4d15f329df713cf0cfb.jpg', '<p>Đường Tới Cửa Tử - The Sylvian Experiments kể về các thí nghiệm ác mộng về não người. Một ngày, Tiến sĩ Hattori và chồng phát hiện dưới lòng đất một bộ phim ghi lại các nghiên cứu phẫu thuật não. Bị ám ảnh bởi khái niệm siêu thực của nó, Hattori cố gắng tái tạo lại thí nghiệm, bắt đầu với các con gái của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mina Fujii","avatar":""},{"name":"Momoko Hatano","avatar":""},{"name":"Yôko Chôsokabe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
