INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-willy-thoat-khoi-vinh-hai-tac', 'Giải Cứu Willy: Thoát Khỏi Vịnh Hải Tặc', 'Free Willy: Escape From Pirate''s Cove', 'https://phimimg.com/upload/vod/20231208-1/a3d7ae2b269bf564c92bb67f0ffd5f4c.jpg', 'https://phimimg.com/upload/vod/20231208-1/38bcf4c26121e0206f3e15700b653bf3.jpg', '<p>Sau khi cô bé Kirra rời ngôi nhà ở Úc của mình để đi nghỉ hè với ông nội ở Nam Phi, cô nhanh chóng phát hiện ra một con cá voi sát thủ bị mắc cạn trong đầm phá gần công viên giải trí bên bờ biển xuống cấp của ông cô. Cô đặt tên cho chú cá voi cô đơn là Willy—và bắt tay vào một nhiệm vụ vĩ đại là dẫn anh chàng nhỏ bé trở lại chiếc kén đầy lo lắng của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Beau Bridges","avatar":""},{"name":"Bindi Irwin","avatar":""},{"name":"Matthew Dylan Roberts","avatar":""},{"name":"Kevin Otto","avatar":""},{"name":"Darron Meyer","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
