INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giai-cuu-willy-thoat-khoi-vinh-hai-tac', 'Giải Cứu Willy: Thoát Khỏi Vịnh Hải Tặc', 'Free Willy: Escape From Pirate''s Cove', 'giải cứu willy: thoát khỏi vịnh hải tặc free willy: escape from pirate''s cove beau bridges bindi irwin matthew dylan roberts kevin otto darron meyer ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-dinh-menh', 'Hoán Đổi Định Mệnh', 'The Switch', 'https://phimimg.com/upload/vod/20231208-1/8d13d57aaa24d771b0e7cf474d4f4051.jpg', 'https://phimimg.com/upload/vod/20231208-1/d2b9ecf0a998d3b53f530ba31e907a54.jpg', '<p>Kassie là một phụ nữ độc thân thông minh, vui tính, bất chấp sự phản đối của người bạn thân mắc bệnh thần kinh Wally, quyết định đã đến lúc phải sinh con - ngay cả khi điều đó có nghĩa là tự mình làm... với sự giúp đỡ nhỏ từ một người hiến tặng tinh trùng quyến rũ. Nhưng, cô ấy không hề hay biết, kế hoạch của Kassie trở nên tồi tệ vì một công tắc vào phút cuối mà mãi đến bảy năm sau mới được phát hiện ra… khi Wally làm quen với cậu con trai dễ thương - mặc dù hơi loạn thần kinh - của Kassie.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Todd Louiso","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
