INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13-thich-khach', '13 Thích Khách', '13 Assassins', 'https://phimimg.com/upload/vod/20231208-1/bdc1057d23077d3771a2969d96ac8e95.jpg', 'https://phimimg.com/upload/vod/20231208-1/d8f79bcabca83b8d3900ff3057d5226b.jpg', '<p>Bộ phim lấy bối cảnh vào những năm cuối triều đại Edo (1603-1868), khi Shogun giữ được nền hòa bình cho đất nước trong nhiều năm trời. Điều này khiến Samurai ngày càng trở nên yếu thế và mất dần khả năng chiến đấu đỉnh cao khi xưa. Sự tàn ác, dã man của lãnh chúa Naritsugu đã làm người dân khốn khổ, căm hận. Được sự ủng hộ của một quan chức lâu năm trong triều, 13 võ sĩ Samurai lên kế hoạch ám sát Naritsugu.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kôji Yakusho","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Yûsuke Iseya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
