INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('13-thich-khach', '13 Thích Khách', '13 Assassins', '13 thích khách 13 assassins kôji yakusho takayuki yamada yûsuke iseya ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-det-hoang-cung', 'Viện Dệt Hoàng Cung', 'A Weaver On The Horizon', 'https://phimimg.com/upload/vod/20231219-1/1a335c3bf0d874df16962d5c81fffd89.jpg', 'https://phimimg.com/upload/vod/20231219-1/add030f4420c037763570474e0314373.jpg', '<p>Viện Dệt Hoàng Cung là bộ phim nói về cuộc đời truyền kỳ của Hoàng Xảo Nhi (Hoàng Đạo Bà), được xem là người đã khai sáng ra thời kỳ mới cho nghề dệt Trung Hoa. Đây là người đã cải tiến kỹ thuật dệt vải của Trung Quốc, nâng nó lên tầm cao mới.Trong phim, Lưu Thi Thi vào vai công chúa bướng bỉnh Gia Nghi. Cô yêu tướng quân Lâm Mộ Phi, nhưng anh lại động lòng với người bạn thân thiết của cô trong cung cấm. Sau nhiều biến cố trong cuộc sống, người con gái Mộ Phi yêu cũng lấy chồng để thành toàn cho Gia Nghi và anh, nhưng cuộc sống hôn nhân của cô không hạnh phúc. Vì vậy, anh chỉ còn biết cách dồn tâm sức vào đại nghiệp khuông phò Nam Tống, còn Gia Nghi lại cam tâm tình nguyện cùng anh đi khắp chân trời góc biển, làm mọi cách để anh phải động lòng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 15, 2010, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Quân Ninh","avatar":""},{"name":"Viên Hoằng","avatar":""},{"name":"Lưu Thi Thi","avatar":""},{"name":"Quách Hiểu Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
