INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luon-co-anh-ben-doi', 'Luôn Có Anh Bên Đời', 'The Road Less Traveled', 'https://phimimg.com/upload/vod/20231208-1/8ffb5c0f8b61614d5c83bbdca726a093.jpg', 'https://phimimg.com/upload/vod/20231208-1/a843ac98fd3a7a164dcea4cdd019da49.jpg', '<p>Phim kể về câu chuyện bi thảm của một tài xế bán tải (Cổ Thiên Lạc) vô tình chạy qua và giết chết một chủ nhà hàng (Yin Xiaotian) trong một vụ tai nạn xe hơi. Khi biết vợ của Yin (Huỳnh Nghị) đang mang thai và phải làm việc chăm chỉ để điều hành công việc kinh doanh của chồng, anh quyết định giúp đỡ cô ấy dù điều đó có thể khiến bạn gái anh (Karen Mok) tức giận. Bộ phim đi qua các giai đoạn của cuộc đời và tình yêu của con người.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Karen Mok","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"Yin Xiaotian","avatar":""},{"name":"Liang Dawei","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
