INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-na-uy', 'Rừng Na Uy', 'Norwegian Wood', 'https://phimimg.com/upload/vod/20231208-1/74d916e31317ee65ba9dc159b5f5bddc.jpg', 'https://phimimg.com/upload/vod/20231208-1/7769878414d1dc7885040a528825f1d7.jpg', '<p>Khi nghe bài hát Na Uy Wood, Toru (Matsuyama) nhớ lại cuộc sống của mình vào những năm 1960, khi người bạn Kizuki tự sát và anh ta đã gần gũi với Naoko, bạn gái của Kizuki. Khi hai người thử, theo những cách rất khác nhau, để tranh luận với nỗi đau của họ, Toru tạo thành một mối liên kết với một người phụ nữ khác, Midori.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324474);
