INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-chim', 'Cớm Chìm', 'Cop Out', 'https://phimimg.com/upload/vod/20231208-1/0d38ba83fbd21547fc90fd1059b6082d.jpg', 'https://phimimg.com/upload/vod/20231208-1/b95a2056c189cd09ccaa92ec37e01000.jpg', '<p>Thám tử Jimmy và Paul, mặc dù là đối tác của nhau trong chín năm, nhưng đôi khi vẫn có vẻ như hai thái cực đối lập—đặc biệt là khi những trò hề khó đoán của Paul khiến họ bị đình chỉ công tác không lương. Sẵn có tiền mặt và đang cố gắng trả tiền cho đám cưới của con gái mình, Jimmy quyết định bán một thẻ bóng chày hiếm có trị giá hàng chục nghìn đô la. Thật không may, khi cửa hàng của người sưu tập bị cướp và chiếc thẻ biến mất cùng với kẻ gian, Paul và Jimmy cuối cùng trở thành kẻ lừa đảo, lần theo chiếc thẻ và đường dây ma túy đằng sau hành vi trộm cắp của nó, tất cả đều vào thời gian của riêng họ và không có bất kỳ sự hỗ trợ nào — ngoại trừ lẫn nhau .</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Michelle Trachtenberg","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Adam Brody","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324474);
