INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-no', 'Món Nợ', 'The Debt', 'https://phimimg.com/upload/vod/20231206-1/2d3636dc8c731326106e831ef9e7a4e2.jpg', 'https://phimimg.com/upload/vod/20231206-1/34d93d9f4ae2a45810b8c9977985b98e.jpg', '<p>Helen Mirren và ngôi sao Sam Worthington trong phim The Debt, câu chuyện kể về Rachel Singer, một cựu chiến binh ở Mossad đã cố gắng để bắt giữ và đưa ra xét xử một tôi phạm chiến tranh nổi tiếng thời Đức Quốc xã (được mệnh danh là Bác sĩ giải phẫu của Birkenau) trong một sứ mệnh bí mật của Israel đã kết thúc với cái chết của hắn trên đường phố Đông Berlin. Bây giờ, 30 năm sau, một người đàn ông lại tự xưng là bác sĩ xuất hiện, và Rachel phải quay trở lại Đông Âu để tìm ra sự thật.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Romi Aboulafia","avatar":""},{"name":"Adar Beck","avatar":""},{"name":"Morris Perry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
