INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-luu-ngoai-khong-gian', 'Phiêu Lưu Ngoài Không Gian', 'Welcome to the Space Show', 'https://phimimg.com/upload/vod/20231205-1/b7706474ee3d81e95b5a6e11f209cf8d.jpg', 'https://phimimg.com/upload/vod/20231205-1/e67b94525ffd562cd6055576c3115517.jpg', '<p>Năm đứa trẻ cứu mạng một người ngoài hành tinh giống chó khi tham gia trại hè tự quản. Anh ta cố gắng thưởng cho họ bằng cách đưa họ đến một thuộc địa của người ngoài hành tinh trên Mặt trăng. Các sự kiện trở nên tồi tệ hơn khi báo cáo của anh ấy về cuộc tấn công khiến anh ấy bị thương khiến việc đi từ Mặt trăng đến Trái đất bị cấm và trẻ em bị mắc kẹt trong không gian. Những đứa trẻ cần tìm đường trở về nhà trước khi trại kết thúc và cha mẹ chúng phát hiện ra rằng chúng mất tích. Họ cũng phải tránh những kẻ săn trộm đã làm bị thương người bạn ngoài hành tinh của họ, và giờ dường như đang rình rập tất cả bọn họ.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takuto Yoshinaga","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Tamaki Matsumoto","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Honoka Ikezuki","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324474);
