INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-than-2', 'Súng Thần 2', 'The Boondock Saints II: All Saints Day', 'https://phimimg.com/upload/vod/20231205-1/ad46cb082a48b9d936a7fa944398be15.jpg', 'https://phimimg.com/upload/vod/20231205-1/79b16b4b729864f7a9ab0e63f2e167a3.jpg', '<p>Suốt 8 năm qua, anh em nhà MacManus sống một cách yên bình cùng cha mình ở một nông trại nuôi cừu sâu trong một hòn đảo nhỏ, biệt lập tại Ireland. Một ngày nọ, chú họ báo tin rằng người cha xứ kính yêu của họ bị giết chết, nhưng điều tệ hơn là cả hai bị tình nghi là hung thủ gây ra vụ án này.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Patrick Flanery","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Billy Connolly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324474);
