INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-com-tranh-tai', 'Siêu Cớm Tranh Tài', 'The Other Guys', 'https://phimimg.com/upload/vod/20231205-1/14826eb99c0412c471faf61605122e13.jpg', 'https://phimimg.com/upload/vod/20231205-1/a639931c9326d6acf3add6380c918c15.jpg', '<p>Terry và Allen, hai cảnh sát bàn giấy ở New York nắm bắt cơ hội xông pha trận mạc để chứng tỏ bản thân. Tuy nhiên, mọi thứ không dễ dàng như hai chàng tưởng tượng. Không chỉ mãn nhãn với các cảnh hành động hài hước, phim làm thỏa lòng người hâm mộ với dàn nam sao hùng hậu.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Michael Keaton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324474);
