INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shanghai', 'Shanghai', 'Shanghai', 'https://phimimg.com/upload/vod/20231203-1/a27dc538b92b541eb2b28a88ee25367a.jpg', 'https://phimimg.com/upload/vod/20231203-1/0b3c86f77e76562a28da8694118be02e.jpg', '<p>Một người đàn ông Mỹ trở lại Thượng Hải tham nhũng, bị Nhật Bản chiếm đóng bốn tháng trước trận Trân Châu Cảng và phát hiện ra bạn mình đã bị giết. Trong khi làm sáng tỏ những bí ẩn về cái chết, anh ta yêu và phát hiện ra một bí mật lớn hơn nhiều mà chính phủ của anh ta đang che giấu.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Chow Yun-Fat","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Ken Watanabe","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
