INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-don-tot-cung', 'Đau Đớn Tột Cùng', 'Bereavement', 'https://phimimg.com/upload/vod/20231202-1/dce597784f238dbc29e0f0c1243648ca.jpg', 'https://phimimg.com/upload/vod/20231202-1/b588fc45888f5cf53e0497b89013ecf1.jpg', '<p>Bộ phim xoay quanh Martin Bristoll đã bị bắt cóc năm lên 6 tuổi ở miền Minersville,Pennsylvania vào năm 1989. Graham Sutter, một gã tâm thần sống ẩn dật, giam giữ Martin trong trại heo của hắn, và bắt phải chứng kiến và tham gia vào những việc khủng khiếp không thể tả. Trong vòng năm năm, nơi ở của Martin vẫn là một bí ẩn, cho đến năm 17 tuổi Allison Miller đến sống với chú của cô là Jonathan. Trong khi khám phá môi trường xung quanh, Allison phát hiện ra những điều nhiều việc bất ổn tại các trang trại phía cuối đường...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Biehn","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Brett Rickaby","avatar":""},{"name":"Nolan Gerard Funk","avatar":""},{"name":"Spencer List","avatar":""},{"name":"John Savage","avatar":""},{"name":"Peyton List","avatar":""},{"name":"Kathryn Meisle","avatar":""},{"name":"Valentina de Angelis","avatar":""},{"name":"Greg Wood","avatar":""},{"name":"Ashley Wolfe","avatar":""},{"name":"Matthew Mindler","avatar":""},{"name":"Jamie Farrell","avatar":""},{"name":"Andrea Havens","avatar":""},{"name":"Jonathan Walker","avatar":""},{"name":"Chase Pechacek","avatar":""},{"name":"Sha","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324474);
