INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-don-tot-cung', 'Đau Đớn Tột Cùng', 'Bereavement', 'đau đớn tột cùng bereavement michael biehn alexandra daddario brett rickaby nolan gerard funk spencer list john savage peyton list kathryn meisle valentina de angelis greg wood ashley wolfe matthew mindler jamie farrell andrea havens jonathan walker chase pechacek sha ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-nhiem-tho-rung', 'Đặc Nhiệm Thỏ Rừng', 'Cat Shit One', 'https://phimimg.com/upload/vod/20231201-1/a630c9afddd53d58f4f6708e27cfceb6.jpg', 'https://phimimg.com/upload/vod/20231201-1/76d5cf615dc716cd4ad272213affc0b3.jpg', '<p>Cuộc chiến chống khủng bố đã trở nên riêng tư. Chiến tranh luôn là một hoạt động kinh doanh có lợi nhuận, vì vậy việc các tập đoàn tư nhân điều quân đội của riêng họ để chiến đấu chống khủng bố chỉ là một hoạt động kinh doanh tốt. Ai khác có thể bảo vệ những chú thỏ vô tội đó khỏi những kẻ cuồng lạc đà cuồng nhiệt. Nó rơi vào tay một nhóm nhỏ gồm những người lính thỏ lông xù dày dạn chiến đấu trên sân nhà của lạc đà. Bắt nguồn từ một bộ truyện tranh nổi tiếng dựa trên xung đột ở Việt Nam có tên là Apocalypse Meow, loạt phần tiếp theo này sử dụng các nhân vật động vật để kể câu chuyện về cuộc chiến chống khủng bố chiến đấu ở các nước xa xôi. Mặc dù dàn nhân vật không phải là con người, nhưng tác phẩm hấp dẫn và được nghiên cứu tỉ mỉ này nhấn mạnh vào chủ nghĩa thực tế để khắc họa chính xác vũ khí và chiến thuật mà binh lính sử dụng.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Hiroshi Tsuchida","avatar":""},{"name":"Masashi Nitta","avatar":""},{"name":"Sawaki Akimoto","avatar":""},{"name":"Kenta Sakai","avatar":""},{"name":"Yuki Hirako","avatar":""},{"name":"Matthew Watkins","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324474);
