INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-buoc-len-thien-dang', 'Ba Bước Lên Thiên Đàng', 'Three Steps Above Heaven', 'https://phimimg.com/upload/vod/20231201-1/f274272362cf01ee3b02b8c4f3a7890e.jpg', 'https://phimimg.com/upload/vod/20231201-1/15476359734ffc54a643fe9ebf9d0673.jpg', '<p>Câu chuyện về hai người trẻ tuổi thuộc hai thế giới khác nhau. Đó là biên niên sử của một tình yêu ngẫu nhiên, gần như không thể nhưng không thể tránh khỏi kéo theo một cuộc hành trình điên cuồng mà họ khám phá ra tình yêu tuyệt vời đầu tiên. Babi là một cô gái thuộc tầng lớp thượng lưu, được giáo dục về tính tốt và sự ngây thơ. Hache là một cậu bé nổi loạn, bốc đồng, thiếu ý thức, ham thích mạo hiểm và nguy hiểm, thể hiện trong những trận đánh nhau bất tận và những cuộc đua xe mô tô bất hợp pháp, giới hạn của lẽ thường</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"María Valverde","avatar":""},{"name":"Mario Casas","avatar":""},{"name":"Álvaro Cervantes","avatar":""},{"name":"Marina Salas","avatar":""},{"name":"Nerea Camacho","avatar":""},{"name":"Cristina Plazas","avatar":""},{"name":"Jordi Bosch","avatar":""},{"name":"Joan Crosas","avatar":""},{"name":"Diego Martín","avatar":""},{"name":"Andrea Duro","avatar":""},{"name":"Pablo Rivero","avatar":""},{"name":"Cristina Dilla","avatar":""},{"name":"Víctor Sevilla","avatar":""},{"name":"Marcel Borràs","avatar":""},{"name":"Pere Ventura","avatar":""},{"name":"Àlex Maruny","avatar":""},{"name":"Clara Segura","avatar":""},{"name":"Henar J","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324474);
