INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ancient-aliens-phan-1', 'Ancient Aliens (Phần 1)', 'Ancient Aliens (Season 1)', 'https://phimimg.com/upload/vod/20231203-1/8b2412b97c4408be6e8783ec3ef548f0.jpg', 'https://phimimg.com/upload/vod/20231203-1/850308e50f90e63d19e21cb41dbb8ff2.jpg', '<p>Có phải những sinh vật thông minh từ ngoài vũ trụ đã đến thăm Trái đất hàng ngàn năm trước? Từ thời khủng long đến Ai Cập cổ đại, từ những hình vẽ ban đầu trong hang động cho đến những vụ chứng kiến hàng loạt liên tục ở Mỹ, mỗi tập phim mang đến chiều sâu lịch sử cho các câu hỏi, suy đoán, tranh cãi khiêu khích, tài khoản trực tiếp và lý thuyết có căn cứ xung quanh cuộc tranh luận lâu đời này.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 14, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Giorgio A. Tsoukalos","avatar":""},{"name":"Ariel Bar Tzadok","avatar":""},{"name":"Jonathan Young","avatar":""},{"name":"Robert Clotworthy","avatar":""},{"name":"David Childress","avatar":""},{"name":"Erich von Däniken","avatar":""},{"name":"David Wilcock","avatar":""},{"name":"George Noory","avatar":""},{"name":"Philip Coppens","avatar":""},{"name":"Nick Pope","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324474);
