INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-tuong-lai', 'Cảnh Sát Tương Lai', 'Future X-Cops', 'https://phimimg.com/upload/vod/20231201-1/d350658e4868569e501028484eb0e1b7.jpg', 'https://phimimg.com/upload/vod/20231201-1/6419f15678978264dea3a8fccccd0316.jpg', '<p>Kidd là một cảnh sát đến từ năm 2080 trong tương lai. Anh cùng vợ mình được giao nhiệm vụ bảo vệ Tiến sĩ Masterson, người được mệnh danh là &quot;Cha đẻ của ngành năng lượng mặt trời&quot; nhờ công phát hiện ra phương pháp thay thế xăng dầu, khí đốt bằng năng lượng mặt trời. Và cũng vì công lao đó mà những ...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Barbie Hsu","avatar":""},{"name":"Xu Jiao","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Mike He","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Shi Yunpeng","avatar":""},{"name":"Chan Kin-Chow","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Tang Yifei","avatar":""},{"name":"Ma Jingwu","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Xiao Jian","avatar":""},{"name":"Li Youwei","avatar":""},{"name":"Chan Hiu-Fung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324474);
