INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chloe', 'Chloe', 'Chloe', 'https://phimimg.com/upload/vod/20231201-1/d542228cb580fdbee0ed3ffbd04ed832.jpg', 'https://phimimg.com/upload/vod/20231201-1/1f782be9a7884b19f30be9fcfbe4a575.jpg', '<p>Catherine và David, cô là một bác sĩ, ông là một giáo sư, ban đầu nhìn thoáng qua cặp đôi hoàn hảo. Hạnh phúc kết hôn với một đứa con trai tuổi teen tài năng, họ dường như có cuộc sống hoàn hảo. Nhưng khi David bỏ lỡ một chuyến bay và bữa tiệc sinh nhật bất ngờ của anh, những nghi ngờ sôi nổi dài của Catherine đã vươn lên bề mặt. Nghi ngờ sự không chung thủy, cô quyết định thuê một người hộ tống để quyến rũ chồng và kiểm tra lòng trung thành của mình. Catherine tìm thấy mình &#39;chỉ đạo&#39; những cuộc gặp gỡ của Chloe của Chloe với David và sự cuối cùng của Chloe là báo cáo lại, các mô tả ngày càng trở nên đồ họa như các cuộc họp nhân lên.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Max Thieriot","avatar":""},{"name":"R. H. Thomson","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"Mishu Vellani","avatar":""},{"name":"Julie Khaner","avatar":""},{"name":"Laura de Carteret","avatar":""},{"name":"Tiffany Lyndall-Knight","avatar":""},{"name":"Meghan Heffern","avatar":""},{"name":"Arlene Duncan","avatar":""},{"name":"Tamsen McDonough","avatar":""},{"name":"Kathryn Kriitmaa","avatar":""},{"name":"Adam Waxman","avatar":""},{"name":"Natalie Lisinsk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb530