INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khung-bo-khong-tuong', 'Vụ Khủng Bố Không Tưởng', 'Unthinkable', 'https://phimimg.com/upload/vod/20231201-1/08aa5cd4cc2d48c3173e69d6e94bcd9f.jpg', 'https://phimimg.com/upload/vod/20231201-1/2c17d91d8c0df88fa03f2610efb47b6e.jpg', '<p>Unthinkable lấy bối cảnh nước Mỹ bị đe dọa bởi 3 quả bom nguyên tử được giấu ở 3 thành phố lớn. 3 quả bom được hẹn giờ cho nổ vào thứ Sáu. Thủ phạm đã bị bắt vào thứ Tư. Và việc tiếp theo, là buộc thủ phạm nói ra nơi giấu 3 quả bom. Nội dung phim xoay quanh việc tra hỏi thủ phạm để tìm ra vị trí 3 quả bom. Trong phim, khi đối diện với kẻ thù, nước Mỹ đã từng bước từng bước phải từ bỏ các giá trị về nhân quyền của mình, những giá trị Mỹ, điều làm nên nền tảng của Giấc Mơ Mỹ. Những giá trị về nhân quyền, về thượng tôn pháp luật, những điều mà Mỹ tự hào dường như bị chính nước Mỹ chối bỏ khi phải đối mặt với nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 7, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Lora Kojovic","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"Vincent Laresca","avatar":""},{"name":"Brandon Routh","avatar":""},{"name":"Joshua Harto","avatar":""},{"name":"Holmes Osborne","avatar":""},{"name":"Michael Rose","avatar":""},{"name":"Randy Oglesby","avatar":""},{"name":"Benito Martinez","avatar":""},{"name":"Sasha Roiz","avatar":""},{"name":"Dayo Ade","avatar":""},{"name":"Yara Shahidi","avatar":""},{"name":"Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387e