INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('outside-the-law', 'Outside the Law', 'Outside the Law', 'https://phimimg.com/upload/vod/20231201-1/adc5728ee17620624c9ad1b4932dcc36.jpg', 'https://phimimg.com/upload/vod/20231201-1/4d4706f1646dd5d30a594d5b0288015e.jpg', '<p>Sau khi mất đi ngôi nhà của gia đình ở Algeria vào những năm 1920, ba anh em trai và mẹ của họ sống rải rác trên khắp thế giới. Messaoud gia nhập quân đội Pháp chiến đấu ở Đông Dương; Abdelkader trở thành một nhà lãnh đạo của phong trào độc lập của người Algeria ở Pháp và Saïd chuyển đến Paris để kiếm tiền trong các câu lạc bộ mờ ám và phòng quyền anh ở Pigalle.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Jamel Debbouze","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Sami Bouajila","avatar":""},{"name":"Chafia Boudraa","avatar":""},{"name":"Bernard Blancan","avatar":""},{"name":"Sabrina Seyvecou","avatar":""},{"name":"Assaad Bouab","avatar":""},{"name":"Thibault de Montalembert","avatar":""},{"name":"Samir Guesmi","avatar":""},{"name":"Jean-Pierre Lorit","avatar":""},{"name":"Ahmed Benaissa","avatar":""},{"name":"Larbi Zekkal","avatar":""},{"name":"Louisa Nehar","avatar":""},{"name":"Mourad Khen","avatar":""},{"name":"Mohamed Djouhari","avatar":""},{"name":"Mostefa Djad","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324474);
