INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kenh-tin-tuc', 'Kênh Tin Tức', 'Rann', 'https://phimimg.com/upload/vod/20231130-1/83d00426afa9b872af9915f2126130be.jpg', 'https://phimimg.com/upload/vod/20231130-1/881a2f288896b2b3f8f40fcf3b4338b0.jpg', '<p>Vị giám đốc đáng kính của một hãng thông tấn cố gắng duy trì tính toàn vẹn của báo chí khi văn phòng của ông và một hãng đối thủ tranh giành người xem sau một vụ tấn công khủng bố.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Amitabh Bachchan","avatar":""},{"name":"Ritesh Deshmukh","avatar":""},{"name":"Paresh Rawal","avatar":""},{"name":"Sudeep","avatar":""},{"name":"Mohnish Behl","avatar":""},{"name":"Rajat Kapoor","avatar":""},{"name":"Rajpal Yadav","avatar":""},{"name":"Gul Panag","avatar":""},{"name":"Suchitra Krishnamoorthi","avatar":""},{"name":"Neetu Chandra","avatar":""},{"name":"Simone Singh","avatar":""},{"name":"Rajkummar Rao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
