INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-bong-toi', 'Bí Ẩn Bóng Tối', 'Vanishing on 7th Street', 'https://phimimg.com/upload/vod/20231130-1/7f9b0fac2cee670e0d42885f254c4b96.jpg', 'https://phimimg.com/upload/vod/20231130-1/48258cf619a5c8ea5bf105111f7f61af.jpg', '<p>Một sự cố mất điện toàn cầu bí ẩn khiến vô số dân số biến mất một cách đơn giản, chỉ để lại quần áo và tài sản của họ. Một nhóm nhỏ những người sống sót tập hợp lại với nhau trong một quán rượu thiếu sáng trên Phố 7, đấu tranh để chống lại nỗi kinh hoàng về ngày tận thế. Nhận ra rằng trên thực tế, họ có thể là những người cuối cùng trên trái đất, một bóng đen đã tấn công họ một mình.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Neal Huff","avatar":""},{"name":"Jacob Latimore","avatar":""},{"name":"Taylor Groothuis","avatar":""},{"name":"Jordan Trovillion","avatar":""},{"name":"Hugh Maguire","avatar":""},{"name":"Erin Nicole","avatar":""},{"name":"Carolyn Clifford","avatar":""},{"name":"Stephen Clark","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Arthur Cartwright","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324474);
