INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-nguc-khung', 'Rồng Ngực Khủng', 'Big Tits Zombie', 'https://phimimg.com/upload/vod/20231211-1/4de60128f531c19fa17d437b13a04333.jpg', 'https://phimimg.com/upload/vod/20231211-1/d4fe19180b1ab95aeacc2b812d66910c.jpg', '<p>Một cuốn sách về người chết thời trung cổ được phát hiện trong hầm mộ nằm dưới câu lạc bộ thoát y của một thị trấn nhỏ. Khi một trong những vũ nữ thoát y tuyệt vọng tập hợp một đội quân xác sống, những vũ nữ thoát y còn lại phải đá vào mông một số thây ma để cứu thế giới.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sora Aoi","avatar":""},{"name":"Io Aikawa","avatar":""},{"name":"Risa Kasumi","avatar":""},{"name":"Mari Sakurai","avatar":""},{"name":"Tamayo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
