INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tac-dong-chet-choc', 'Tác Động Chết Chóc', 'Deadly Impact', 'null', 'https://phimimg.com/upload/vod/20231210-1/ee698ca66b9eaebd00ec05bcb6fdd9a9.jpg', '<p>Tác Động Chết Chóc - Deadly Impact xoay quanh sĩ quan cảnh sát với quá nhiều nỗi đau và mất mát Sean Patrick Flanery. Sau khi phát hiện kẻ giết người tàn bạo quay trở lại, Sean mang theo quá khứ đau buồn tham gia lực lượng với FBI truy tìm kẻ sát thủ chủ mưu, đưa kẻ tâm thần đến công lý.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joel Bryant","avatar":""},{"name":"Dave Colon","avatar":""},{"name":"Christopher Dempsey","avatar":""},{"name":"Brother Douglas","avatar":""},{"name":"Sean Patrick Flanery","avatar":""},{"name":"Julianne Flores","avatar":""},{"name":"Michelle Greathouse","avatar":""},{"name":"Chaz Grundy","avatar":""},{"name":"Antony Hall","avatar":""},{"name":"David House","avatar":""},{"name":"John Koyama","avatar":""},{"name":"Fredrick Lopez","avatar":""},{"name":"Mike Miller","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Luce Rains","avatar":""},{"name":"Chris Ra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
