INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tac-dong-chet-choc', 'Tác Động Chết Chóc', 'Deadly Impact', 'tác động chết chóc deadly impact joel bryant dave colon christopher dempsey brother douglas sean patrick flanery julianne flores michelle greathouse chaz grundy antony hall david house john koyama fredrick lopez mike miller joe pantoliano luce rains chris ra ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-tam-thoi-gian', 'Bồn Tắm Thời Gian', 'Hot Tub Time Machine', 'https://phimimg.com/upload/vod/20231130-1/b8d59c8f7c57810e814d4378f7cecde6.jpg', 'https://phimimg.com/upload/vod/20231130-1/54e818d727c0da7772ab039f451ec58a.jpg', '<p>4 người bạn thân chán ngán với cuộc sống: Adam - lại một lần nữa - bị bạn gái &quot;đá&quot;, Lou không còn tìm thấy niềm vui chốn tiệc tùng, Nick bị cô vợ không chung thủy kiểm soát nhất cử nhất động, và Jacob đóng đô dưới tầng hầm để thỏa mãn thói ghiền trò chơi điện tử. Lou đã gần như tuyệt vọng, anh tự tử. Những người bạn của anh đã cứu và dẫn anh đi trượt tuyết cuối tuần. Sau một đêm chè chén bí tỷ trong bồn tắm nước nóng tại resort, bốn anh &quot;bạn già&quot; tỉnh dậy với đầu còn chuếnh choáng men và nhận ra mình đang ở... năm 1986. Tại sao chiếc máy thời gian bồn tắm lại không đưa bốn nhân vật chính của chúng ta đến với thế giới cổ đại, hay một thời kỳ chiến tranh hào hùng nào đó? Tại sao lại là thập kỷ 80? Bởi đây là cơ hội để họ sửa chữa quá khứ và thay đổi tương lai của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Lyndsy Fonseca","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Collette Wolfe","avatar":""},{"name":"William Zabka","avatar":""},{"name":"Chevy Chase","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Aliu Oyofo","avatar":""},{"name":"Jake Rose","avatar":""},{"name":"Brook Bennett","avatar":""},{"name":"Yan-Kay Crystal Lowe","avatar":""},{"name":"Jessica Paré","avatar":""},{"name":"Ke","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
