INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-thuy-minh-chau', 'Phỉ Thúy Minh Châu', 'The Jade and the Pearl', 'https://phimimg.com/upload/vod/20231130-1/e6a275c883c66df90975e53acf955bc0.jpg', 'https://phimimg.com/upload/vod/20231130-1/ff870e2dc9d27bb35791188b2eb25b09.jpg', '<p>Trong hành trình dài đến một vùng đất xa lạ cho cuộc hôn nhân trong mơ của mình, Công chúa Yan (Thái Trác Nghiên) phát hiện ra mình phải lòng Tướng quân Cheng (Lâm Phong), người đang dẫn đầu đoàn quân hộ tống. Bất chấp tình yêu bị ngăn cấm, họ trao đổi những biểu tượng tình yêu. Tuy nhiên, một cuộc tấn công bất ngờ của một băng đảng cướp đã thay đổi vận mệnh của họ. Tướng quân Cheng bị bắt làm con tin bởi nữ thủ lĩnh của băng cướp, Zhu (Joey Yung) và anh dần yêu cô. Bi kịch tiếp tục diễn ra khi Cheng phải đối mặt với những quyết định khó khăn.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Raymond Lam","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Joey Yung","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Steven Cheung","avatar":""},{"name":"Macy Chan","avatar":""},{"name":"Shuang Chen","avatar":""},{"name":"Kenny Kwan","avatar":""},{"name":"You-Nam Wong","avatar":""},{"name":"Ralph Chau Chi-Ho","avatar":""},{"name":"Shiu-Hung Hui","avatar":""},{"name":"Tien Niu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
