INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-doan-sat-thu', 'Tập Đoàn Sát Thủ', 'Machete', 'https://phimimg.com/upload/vod/20231130-1/763d890bebd69c33f9f73e240da26e2b.jpg', 'https://phimimg.com/upload/vod/20231130-1/061c487885a297dbffc024030a180868.jpg', '<p>Bộ phim Machete xoay quanh câu chuyện về một cựu điệp viên liên bang bí mật sống dưới vỏ bọc là một người dân lao động bình thường. Sau khi bị chính đồng nghiệp trong tổ chức của mình phản bội, anh phải trốn tránh và lên kế hoạch trả thù...</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Steven Seagal","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Lindsay Lohan","avatar":""},{"name":"Electra Avellan","avatar":""},{"name":"Elise Avellan","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Billy Blair","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Tito Larriva","avatar":""},{"name":"Gilbert Trejo","avatar":""},{"name":"Felix Sab","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
