INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-dung-so', 'Bi, Đừng Sợ!', 'Bi, Don''t Be Afraid', 'https://phimimg.com/upload/vod/20231208-1/d1540eb14805af186f54f3548662bfe3.jpg', 'https://phimimg.com/upload/vod/20231208-1/4d16ed2b818c952fb68e7c936dcd468f.jpg', '<p>Hình ảnh những viên đá lạnh gắn liền với hành trình khám phá những bí mật, khao khát, dục vọng ẩn sâu trong mỗi người. Phim như một bài thơ đầy cảm xúc về thế giới vừa tươi đẹp, vừa đớn đau.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"NSƯT Trần Tiến","avatar":""},{"name":"Nguyễn Hà Phong","avatar":""},{"name":"Nguyễn Thị Kiều Trinh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
