INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-tac', 'Đạo Tặc', 'Takers', 'https://phimimg.com/upload/vod/20231129-1/7b4358e160f18849f081d71242896af1.jpg', 'https://phimimg.com/upload/vod/20231129-1/555f569c7d01917160dad05cfe483359.jpg', '<p>Nhóm cướp nhà băng tinh nhuệ sắp đặt vụ cướp táo bạo sau khi gã cộng sự cũ thuyết phục họ nhắm vào một chiếc xe được vũ trang. Đó có thể là phi vụ &quot;đậm&quot; nhất của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Brown","avatar":""},{"name":"Hayden Christensen","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"T.I.","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Johnathon Schaech","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Gaius Charles","avatar":""},{"name":"Gideon Emery","avatar":""},{"name":"Zulay Henao","avatar":""},{"name":"Glynn Turman","avatar":""},{"name":"Nicholas Turturro","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Isa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
