INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-toi-pham', 'Vương Quốc Tội Phạm', 'Animal Kingdom', 'https://phimimg.com/upload/vod/20231129-1/9e7cdc8b2163e0206e6c3b3ae40c436b.jpg', 'https://phimimg.com/upload/vod/20231129-1/a539714b071f683950864154cd88d048.jpg', '<p>Joshua “J” được đại gia đình nhận nuôi sau khi mẹ anh qua đời vì dùng thuốc quá liều. Gia tộc, được cai trị bởi bà nội đầy mưu mô của J, tham gia rất nhiều vào các hoạt động tội phạm, và J sớm bị truyền bá lối sống của họ. Nhưng J có cơ hội đi theo một con đường khác khi một cảnh sát tìm cách giúp đỡ anh ta.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Ben Mendelsohn","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Luke Ford","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Dan Wyllie","avatar":""},{"name":"Anthony Hayes","avatar":""},{"name":"Laura Wheelwright","avatar":""},{"name":"Mirrah Foulkes","avatar":""},{"name":"Justin Rosniak","avatar":""},{"name":"Susan Prior","avatar":""},{"name":"Clayton Jacobson","avatar":""},{"name":"Anna Lise Phillips","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Tim Ph","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
