INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-an-minh', 'Quỷ Dữ Ẩn Mình', 'Devil', 'https://phimimg.com/upload/vod/20231129-1/1ff68b9451ef7b6ece1e26ae28324dec.jpg', 'https://phimimg.com/upload/vod/20231129-1/ad36f50a2a2d90451fa187ce75f90199.jpg', '<p>Thanh tra Bowden phải cứu năm người bị mắc kẹt trong thang máy, và phải làm điều này thật nhanh, vì một trong số họ là quỷ dữ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Messina","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Jenny O''Hara","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Caroline Dhavernas","avatar":""},{"name":"Joshua Peace","avatar":""},{"name":"Zoie Palmer","avatar":""},{"name":"Joe Cobden","avatar":""},{"name":"Vincent Laresca","avatar":""},{"name":"Craig Eldridge","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Rudy Webb","avatar":""},{"name":"Robert Lee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
