INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-dung-xa-toi', 'Mãi Đừng Xa Tôi', 'Never Let Me Go', 'https://phimimg.com/upload/vod/20231129-1/ef92448fdd2df241dac0c6657204a3c8.jpg', 'https://phimimg.com/upload/vod/20231129-1/4ff88bff06d27b641eb22b5c6c06f930.jpg', '<p>Never Let Me Go là một phim điện ảnh chính kịch lãng mạn dystopia của Anh Quốc năm 2010, dựa trên cuốn tiểu thuyết Mãi đừng xa tôi của Kazuo Ishiguro xuất bản năm 2005. Phim do Mark Romanek đạo diễn từ kịch bản của Alex Garland.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Andrew Garfield","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Nathalie Richard","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Izzy Meikle-Small","avatar":""},{"name":"Ella Purnell","avatar":""},{"name":"Charlie Rowe","avatar":""},{"name":"Kate Bowes Renna","avatar":""},{"name":"Hannah Sharp","avatar":""},{"name":"Christina Carrafiell","avatar":""},{"name":"Oliver Parson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324475);
