INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('senna', 'Senna', 'Senna', 'https://phimimg.com/upload/vod/20231129-1/f2ef35d754ef2df66ed1ca8fc11c0fe7.jpg', 'https://phimimg.com/upload/vod/20231129-1/7638e0f2ed22226eded936ed73eb30e2.jpg', '<p>Bộ phim tài liệu tiết tấu nhanh kể về Ayrton Senna, một trong những tay đua cừ khôi nhất trong lịch sử giải Công thức Một và cũng là một người hùng tại quê hương Brazil.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ayrton Senna","avatar":""},{"name":"Alain Prost","avatar":""},{"name":"Frank Williams","avatar":""},{"name":"Ron Dennis","avatar":""},{"name":"Viviane Senna","avatar":""},{"name":"Milton da Silva","avatar":""},{"name":"Neide Senna","avatar":""},{"name":"Jackie Stewart","avatar":""},{"name":"Sid Watkins","avatar":""},{"name":"Galvão Bueno","avatar":""},{"name":"Reginaldo Leme","avatar":""},{"name":"Gerhard Berger","avatar":""},{"name":"Nelson Piquet","avatar":""},{"name":"Nigel Mansell","avatar":""},{"name":"Jean-Marie Balestre","avatar":""},{"name":"Bernie Ecclestone","avatar":""},{"name":"John Bisig","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324475);
