INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-kinh-hoang-2010', 'Kỳ Nghỉ Kinh Hoàng', 'Tucker and Dale vs. Evil', 'https://phimimg.com/upload/vod/20231129-1/ef5136a808e9ee281049bd49c916fde9.jpg', 'https://phimimg.com/upload/vod/20231129-1/13821e11caaba8ff6ea5c7b2644babf9.jpg', '<p>Tucker và Dale quyết định đi nghỉ tại căn nhà gỗ của họ trên núi. Kỳ nghỉ của họ thay đổi một cách khó chịu khi họ bị một nhóm sinh viên đại học nhầm là kẻ giết người bằng cưa máy.
 Ban đầu</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Alan Tudyk","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"Philip Granger","avatar":""},{"name":"Jesse Moss","avatar":""},{"name":"Bill Baksa","avatar":""},{"name":"Christie Laing","avatar":""},{"name":"Chelan Simmons","avatar":""},{"name":"Brandon Jay McLaren","avatar":""},{"name":"Travis Nelson","avatar":""},{"name":"Alex Arsenault","avatar":""},{"name":"Adam Beauchesne","avatar":""},{"name":"Joseph Allan Sutherland","avatar":""},{"name":"Karen Reigh","avatar":""},{"name":"Tye Evans","avatar":""},{"name":"Mitchell Verigin","avatar":""},{"name":"Angel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
