INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alice-o-xu-so-than-tien-2010', 'Alice Ở Xứ Sở Thần Tiên', 'Alice in Wonderland', 'https://phimimg.com/upload/vod/20231018-1/f43bc8c661ec5d12329025b817e46a85.jpg', 'https://phimimg.com/upload/vod/20231018-1/6a71156b498151dbaec73cd8fc0884d8.jpg', '<p>Đã 10 năm kể từ ngày rơi xuống chiếc hố thỏ và lạc vào Xứ Sở Thần Tiên, nay Alice Kingsley trong phim Alice Ở Xứ Sở Thần Tiên đã 19 tuổi và trở thành một thiếu nữ xinh đẹp. Khi bất ngờ bị cầu hôn tại bữa tiệc lớn, cô gái đã bỏ chạy và một lần nữa lạc xuống Xứ Sở Thần Tiên. Xứ Sở Thần Tiên giờ chẳng còn đẹp đẽ như xưa mà đã trở nên điêu tàn dưới bàn tay ngự trị của mụ Nữ Hoàng Đỏ. Dẫu Alice không còn nhớ chút gì về chốn ma mị này, nhưng tất cả những người bạn nơi đây đều vẫn còn nhớ cô gái. Và chính Alice sẽ là người giải cứu tất cả, trả lại sự yên bình cho mảnh đất màu nhiệm này.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mia Wasikowska","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Tim Pigott-Smith","avatar":""},{"name":"Leo Bill","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Christop","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
