INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-riu-2', 'Lưỡi Rìu 2', 'Hatchet II', 'https://phimimg.com/upload/vod/20231129-1/11215f8c58d423023b6b0b818a5b62fb.jpg', 'https://phimimg.com/upload/vod/20231129-1/c176d27fb69dfa32e5dadfcccf185b78.jpg', '<p>Hatchet II (Lưỡi Rìu 2) tiếp theo câu chuyện phần một. Nhưng trong phần này, các thành viên trong nhóm bạn đã chết, chỉ có Marybeth thoát khỏi nanh vuốt của gã sát nhân cơ thể biến dạng ở đầm lầy - Victor Crowley. Sau khi biết được sự thật về mối quan hệ giữa gia đình cô và gã điên cầm rìu đó, Marybeth quay trở về đầm lầy Louisiana cùng với một đội quân thợ săn để cướp lại thi thể các thành viên trong gia đình cô và tiến hành sự trả thù tàn bạo nhất đối với gã...</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danielle Harris","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Parry Shen","avatar":""},{"name":"R.A. Mihailoff","avatar":""},{"name":"AJ Bowen","avatar":""},{"name":"Ed Ackerman","avatar":""},{"name":"Alexis Kendra","avatar":""},{"name":"David Foy","avatar":""},{"name":"Colton Dunn","avatar":""},{"name":"Rick McCallum","avatar":""},{"name":"John Carl Buechler","avatar":""},{"name":"Kathryn Fiore","avatar":""},{"name":"Erika Hamilton","avatar":""},{"name":"Mercedes McNab","avatar":""},{"name":"Joleigh Fioravanti","avatar":""},{"name":"Rileah Vanderbilt","avatar":""},{"name":"Cha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
