INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luoi-riu-2', 'Lưỡi Rìu 2', 'Hatchet II', 'lưỡi rìu 2 hatchet ii danielle harris kane hodder tony todd parry shen r.a. mihailoff aj bowen ed ackerman alexis kendra david foy colton dunn rick mccallum john carl buechler kathryn fiore erika hamilton mercedes mcnab joleigh fioravanti rileah vanderbilt cha ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-bi-an-ngon-lua-ma', 'Địch Nhân Kiệt: Bí Ẩn Ngọn Lửa Ma', 'Detective Dee and the Mystery Of the Phantom Flame', 'https://phimimg.com/upload/vod/20231129-1/08cd260b85c7f30ff40005423454f2d4.jpg', 'https://phimimg.com/upload/vod/20231129-1/c20581f0ba3a40a96e02aab17dfebbf9.jpg', '<p>Cả kinh thành Lạc Dương tràn ngập trong các lễ hội về đêm. Và dường như mọi chuyện đã suôn sẻ nếu không xảy ra những cái chết đầy bí ẩn và gây ra nỗi kinh hoàng cho người dân. Mọi chuyện càng tồi tệ hơn khi hầu hết nạn nhân đều là những người thân cận của Võ Tắc Thiên. Sợ rằng ngày lễ đăng quang sẽ bị phá hủy, Võ vương nóng lòng muốn biết ai là người đứng đằng sau vụ việc này, bà đã phải nhờ đến bổ đầu Địch (Địch Nhân Kiệt) - hiện đang bị đày ải. Anh là người chuyên xử lý các vụ việc này, đồng thời cũng là người đã từng chống lại bà khi bà bắt đầu nắm quyền lực tám năm về trước. Cuối cùng Địch đã chấp nhận quay lại giúp bà. Anh đã làm việc cùng Bei - một người hăng hái và một người chuyên sử dụng ma thuật và cũng là một thiên tài về cải trang. Họ dần dần khám phá ra được các bí mật của hung thủ nhưng họ không ngờ tới một sự nguy hiểm đang chờ họ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Deng Chao","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Teddy Robin","avatar":""},{"name":"Liu Jinshan","avatar":""},{"name":"Yao Lu","avatar":""},{"name":"Jean-Michel Casanova","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d4