INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-o-rome', 'Chuyện Tình Ở Rome', 'When in Rome', 'https://phimimg.com/upload/vod/20231129-1/b44f1eba8087a40dc4f8dee7768bf1e4.jpg', 'https://phimimg.com/upload/vod/20231129-1/bb47f0956632a21c3a3a9a5d6af013f3.jpg', '<p>Sau khi câu được những đồng xu từ một đài phun nước ở Ý, Beth Harper, một người New York hoài nghi thấy mình được một số người theo đuổi nồng nhiệt theo đuổi. Trong khi đối mặt với sự chú ý, Beth cố tìm hiểu xem liệu cô phóng viên quyến rũ có thực sự yêu mình hay không.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Kristen Bell","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Jon Heder","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Alexis Dziena","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Peggy Lipton","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Luca Calvani","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Judith Malina","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Natalie Joy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
