INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoa-giai', 'Kẻ Hoà Giải', 'Troubleshooter', 'https://phimimg.com/upload/vod/20231129-1/1b3dce72d1c85b3905c6f42743fa394b.jpg', 'https://phimimg.com/upload/vod/20231129-1/0920d216bd3ed23eb407195bd7d7043e.jpg', '<p>Phim nói về một cuộc phiêu lưu, hành động trong vòng 24 giờ của Kang Tae Shik – một người đi đòi nợ thuê nhưng rơi vào bẫy của bọn xã hội đen và bị vu khống giết người. Để minh oan cho mình, Tae Shik phải thực hiện một cuộc bắt cóc theo yêu cầu, anh sẽ làm gì để tự cứu lấy cuộc đời mình?</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sol Kyung-gu","avatar":""},{"name":"Lee Jung-jin","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Lee Young-hoon","avatar":""},{"name":"Park Young-seo","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Kim Hyang-gi","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Kim Jung-pal","avatar":""},{"name":"Min Young","avatar":""},{"name":"Ha Soo-ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
