INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-do-la-la', 'Nhật Ký Đỗ La La', 'Go Lala Go!', 'https://phimimg.com/upload/vod/20231130-1/18998920853989cb4d7bdbf5df9f5c11.jpg', 'https://phimimg.com/upload/vod/20231130-1/153e435baa90c8ae85ecfe079be976b5.jpg', '<p>Go Lala Go là câu chuyện kể về một phụ nữ cần mẫn, luôn chọn cho mình cách tích cực nhất để thăng tiến, được ca ngợi như là tài liệu hướng dẫn phải đọc với tất cả những nhân viên văn phòng. Đó là trường hợp của Đỗ La La, cô bắt đầu sự nghiệp của mình tại một công ty đứng trong hàng ngũ 500 công ty hàng đầu trên thế giới với công việc là một nhân viên tiếp tân khiêm tốn. La La luôn vượt qua sức ép và sự thất vọng với một thái độ tích cực, nhận thức rằng trở ngại chỉ là những thử thách gay go mà cô phải vượt qua.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Jinglei","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Stanley Huang","avatar":""},{"name":"Pace Wu","avatar":""},{"name":"Li Ai","avatar":""},{"name":"Song Ningfeng","avatar":""},{"name":"Alice Wang","avatar":""},{"name":"Peter Loehr","avatar":""},{"name":"Erik Siao","avatar":""},{"name":"Wu Jian-Xin","avatar":""},{"name":"Sun Zhuo","avatar":""},{"name":"Jiang Jin-Chao","avatar":""},{"name":"Zheng Yan-Qi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
