INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-do-la-la', 'Nhật Ký Đỗ La La', 'Go Lala Go!', 'nhật ký đỗ la la go lala go! xu jinglei karen mok man-wai stanley huang pace wu li ai song ningfeng alice wang peter loehr erik siao wu jian-xin sun zhuo jiang jin-chao zheng yan-qi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-search-for-santa-paws', 'The Search for Santa Paws', 'The Search for Santa Paws', 'https://phimimg.com/upload/vod/20231129-1/a4931ba4145f86483275c20e9790890f.jpg', 'https://phimimg.com/upload/vod/20231129-1/8863020ff8cf2c25077a6b37747433af.jpg', '<p>Theo truyền thống của những câu chuyện cổ điển về ngày lễ của Disney, một bộ phim cảm động về sức mạnh của sự cho đi và ý nghĩa thực sự của lễ Giáng sinh đã xuất hiện. Khám phá tình bạn huyền thoại của ông già Noel và bàn chân ông già Noel bắt đầu như thế nào trong bộ phim gốc đầy cảm hứng, The Search For Santa Paws. Khi ông già Noel và người bạn thân mới của ông, Paws, phát hiện ra rằng các chàng trai và cô gái trên thế giới đã đánh mất tinh thần của mùa lễ hội, họ thực hiện một chuyến đi đến Thành phố New York. Nhưng sau khi ông già Noel mất trí nhớ, Paws, một đứa trẻ mồ côi trung thành tên Quinn, người bạn mới Will và một nhóm chó biết nói có phép thuật tuyệt vời sẽ phụ thuộc vào việc cứu St. Nick và cho thế giới thấy Giáng sinh thực sự là gì.</p>', 'Full', 1, 'single', 'completed', 9, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kaitlyn Maher","avatar":""},{"name":"Madison Pettis","avatar":""},{"name":"Zachary Gordon","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"John Ducey","avatar":""},{"name":"Bonnie Somerville","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Danny Woodburn","avatar":""},{"name":"Chris Coppola","avatar":""},{"name":"Jason Connery","avatar":""},{"name":"Christopher Massey","avatar":""},{"name":"Josh Flitter","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Genevieve Hannelius","avatar":""},{"name":"Nicole Leduc","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
