INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-search-for-santa-paws', 'The Search for Santa Paws', 'The Search for Santa Paws', 'the search for santa paws the search for santa paws kaitlyn maher madison pettis zachary gordon wendi mclendon-covey richard riehle john ducey bonnie somerville richard kind danny woodburn chris coppola jason connery christopher massey josh flitter bill cobbs genevieve hannelius nicole leduc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-tran-chan', 'Huyền Thoại Trần Chân', 'Legend of The Fist : The Return of Chen Zhen', 'https://phimimg.com/upload/vod/20231129-1/f373ec099dbd32944c818f5c00510dcd.jpg', 'https://phimimg.com/upload/vod/20231129-1/ec5bc4c93cfabd9fc5789fc928275297.jpg', '<p>Âm mưu thâm độc của quân đội Nhật trong giai đoạn xâm lược Trung Quốc là chia rẽ phe phái thông qua lực lượng chỉ điểm, sát thủ để mở rộng xâm lược Trung Quốc. Tuy nhiên, nhiều kẻ trong số đó đã bị thủ tiêu không dấu tích bởi một sát thủ siêu hạng mặc đồ đen không ai khác đó chính là Trần Chân, 7 năm sau cái chết của sư phụ Hoắc Nguyên Giáp, Trần Chân đã trở về Thượng Hải trong diện mạo hoàn toàn mới. Trần Chân đã nhiều lần được đưa lên phim ảnh nhưng Huyên Thoại Trần Chân thực sự tạo ra điểm nhấn đặc biệt. Chung Tử Đơn vẫn là linh hồn của những phim mà anh tham gia. Võ thuật đỉnh cao trong phim là điều miễn bàn cãi, bên cạnh võ thuật trung hoa truyền thống Huyền Thoại Trần Chân có sự xuất hiện của Aikido, Karate.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Huang Bo","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Ryu Kohata","avatar":""},{"name":"Huo Si-Yan","avatar":""},{"name":"Zhou Yang","avatar":""},{"name":"Akira","avatar":""},{"name":"Ma Yue","avatar":""},{"name":"Karl Dominick","avatar":""},{"name":"Jiajia Chen","avatar":""},{"name":"Alex Ahlstrom","avatar":""},{"name":"Yale Varty","avatar":""},{"name":"Shi Feng","avatar":""},{"name":"Minowa Yasufumi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
