INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-chan-tran', 'Giấc Mơ Chân Trần', 'A Barefoot Dream', 'https://phimimg.com/upload/vod/20231129-1/c0da7dc1de35b8d1cdfaa8429567bad2.jpg', 'https://phimimg.com/upload/vod/20231129-1/66a5be9c83dff60c246f03b20719351c.jpg', '<p>Kim Won-kang là một cựu cầu thủ bóng đá có cuộc sống không như mong đợi. Anh ta đi đến Đông Timor, nơi anh ta nghĩ rằng sẽ có nhiều cơ hội cho anh ta. Một ngày nọ, anh thấy một nhóm những đứa trẻ đường phố chơi bóng đá với đôi chân trần. Nghĩ rằng anh ta có thể ghi bàn bằng cách bán giày bóng đá, anh ta mở một cửa hàng dụng cụ thể thao, nhưng nhận ra không ai trong số những đứa trẻ có thể mua những đôi giày hay áo lạ mắt đó. Một lần nữa, tuyệt vọng, anh lại sắp đóng cửa hàng. Nhưng anh quyết định dạy bọn trẻ cách chơi bóng đá. Vẫn không có giày, nhưng họ quyết định thi đấu tại Giải vô địch bóng đá trẻ quốc tế tại Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hee-soon","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Im Won-hee","avatar":""},{"name":"Kim Seo-hyung","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Shin Cheol-jin","avatar":""},{"name":"Xanana Gusmão","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
