INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cay-tao-gai', 'Chuyện Tình Cây Táo Gai', 'Under the Hawthorn Tree', 'https://phimimg.com/upload/vod/20231127-1/fe177a275770deb7ef60a3e2ce86a1d5.jpg', 'https://phimimg.com/upload/vod/20231127-1/6ce75e321cc2ca3c9d03431340dbfc22.jpg', '<p>Một câu chuyện tình yêu nhẹ nhàng như làn gió mát mùa hè nhưng lại khiến người xem cảm thấy day dứt khôn nguôi giữa thời kỳ những cảm xúc cá nhân của con người bị kìm nén để rồi cuối cùng, mỗi người trong số họ đều phải hối tiếc về những gì đã trôi qua không thể quay lại được nữa.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Dongyu","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Xi Meijuan","avatar":""},{"name":"Li Xuejian","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Sa Ren-Na","avatar":""},{"name":"Lü Liping","avatar":""},{"name":"Jiang Ruijia","avatar":""},{"name":"Yu Xinbo","avatar":""},{"name":"Sun Hai Ying","avatar":""},{"name":"Huang Xiaoge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
