INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-kiet-that-the', 'Quái Kiệt Thất Thế', 'The Losers', 'https://phimimg.com/upload/vod/20231129-1/6f1d7d441c80fe4e8c1ba931c91d05c0.jpg', 'https://phimimg.com/upload/vod/20231129-1/2e815757d9e25631743882e9775b18c5.jpg', '<p>Phim Quái Kiệt Thất Thế - The Losers là một đội ngũ đen-ops ưu tú của Hoa Kỳ Lực lượng đặc biệt hợp tác xã, do Clay và hình thành bởi Roque, Pooch, Jensen, và Cougar, được cử sang Bolivia trong một tìm kiếm và phá hủy nhiệm vụ trên một hợp chất được điều hành bởi một trùm ma túy. Phim Quái Kiệt Thất Thế: Trong khi vẽ một mục tiêu cho một cuộc không kích sắp tới, các mã giảm phát hiện trẻ em nô lệ trong hợp chất này và cố gắng gọi tắt cuộc tấn công, nhưng cấp trên, có tên mã là Max, bỏ qua những lời cầu xin của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Columbus Short","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Peter Macdissi","avatar":""},{"name":"Peter Francis James","avatar":""},{"name":"Tanee McCall","avatar":""},{"name":"Mark Ginther","avatar":""},{"name":"Daniel Kalal","avatar":""},{"name":"Colin Follenweider","avatar":""},{"name":"Garrett Warren","avatar":""},{"name":"Rey Hernandez","avatar":""},{"name":"Ernes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb