INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-ngay-mai-que-huong-tran-khoi-lua', 'Nếu Ngày Mai Quê Hương Tràn Khói Lửa', 'Tomorrow, When the War Began', 'https://phimimg.com/upload/vod/20231125-1/854d4d6aae43977cb26fc229249a1aa9.jpg', 'https://phimimg.com/upload/vod/20231125-1/4b4e42af8b945a77a3c2dd3b5dda1457.jpg', '<p>Bộ phim kể về một nhóm tám nam nữ sinh trung học ở miền quê cùng đi dã ngoại tại một vùng núi hoang vu hẻo lánh ở Úc. Khi họ quay trở về nhà thì bàng hoàng khi thấy toàn bộ gia đình, người thân… đều biến mất. Họ sẽ phải làm gì để lấy lại cuộc sống của mình? Mời các bạn theo dõi bộ phim.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Caitlin Stasey","avatar":""},{"name":"Rachel Hurd-Wood","avatar":""},{"name":"Phoebe Tonkin","avatar":""},{"name":"Deniz Akdeniz","avatar":""},{"name":"Lincoln Lewis","avatar":""},{"name":"Chris Pang","avatar":""},{"name":"Ashleigh Cummings","avatar":""},{"name":"Andrew Ryan","avatar":""},{"name":"Colin Friels","avatar":""},{"name":"Don Halbert","avatar":""},{"name":"Olivia Pigeot","avatar":""},{"name":"Kelly Butler","avatar":""},{"name":"Julia Yon","avatar":""},{"name":"Dane Carson","avatar":""},{"name":"Matthew Dale","avatar":""},{"name":"Gary Quay","avatar":""},{"name":"Michael Camilleri","avatar":""},{"name":"Stephen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
