INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-thuoc-tinh-yeu', 'Khói Thuốc Tình Yêu', 'Love In A  Puff', 'https://phimimg.com/upload/vod/20231125-1/aec0a2d90c69fb2d0f611d057ea2b976.jpg', 'https://phimimg.com/upload/vod/20231125-1/383d29abe9696f3861df1dcf6387e250.jpg', '<p>Tác phẩm về tình yêu được đánh giá cao trong các bộ phim Hồng Kông, có thể khiến bạn ôm bụng cười và cảm thấy ấm áp!</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shawn Yue","avatar":""},{"name":"Miriam Yeung Chin-Wah","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Chui Tien-You","avatar":""},{"name":"Miu Fei-Lam","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Charmaine Fong","avatar":""},{"name":"Sharon Luk","avatar":""},{"name":"Roy Szeto","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Isabel Chan Yat-Ning","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Singh Hartihan Bitto","avatar":""},{"name":"Eric Chan Hoi-Yan","avatar":""},{"name":"Feli","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
