INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoi-thuoc-tinh-yeu', 'Khói Thuốc Tình Yêu', 'Love In A  Puff', 'khói thuốc tình yêu love in a  puff shawn yue miriam yeung chin-wah cheung tat-ming chui tien-you miu fei-lam jo kuk cho-lam vincent kok charmaine fong sharon luk roy szeto matt chow hoi-kwong isabel chan yat-ning kenny wong tak-ban singh hartihan bitto eric chan hoi-yan feli ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-hoa-thu-tu', 'Bức Họa Thứ Tư', 'The Fourth Portrait', 'https://phimimg.com/upload/vod/20231125-1/39d4645689b767dbff6d0b09666c71ad.jpg', 'https://phimimg.com/upload/vod/20231125-1/010afe314b593497fd0e075f029b1fbb.jpg', '<p>Cậu bé Xiang 10 tuổi phải đối mặt với tương lai cô đơn sau khi cha cậu qua đời. Ngay khi anh ấy nghĩ rằng mình sẽ sống cả đời trong trại trẻ mồ côi, thì người mẹ ghẻ lạnh của anh ấy xuất hiện. Và cuộc đời anh thay đổi mãi mãi... Một người mẹ vô tình, một người cha dượng đáng ghét, một ngôi nhà lạnh lẽo. Xiang đang hướng tới đâu? Anh ấy tìm thấy sự thoải mái khi vẽ và tác phẩm của anh ấy bộc lộ niềm khao khát được quan tâm và yêu mến. Cuộc sống lại tràn đầy hy vọng khi anh gặp lại người gác cổng trường học cũ, người không dễ dàng thể hiện lòng tốt của mình và một người đàn ông đẫy đà có những ý tưởng điên rồ và bị ám ảnh bởi những cơn ác mộng về anh trai mình. Một sự thật đáng sợ sắp được phơi bày. Liệu Xiang có thể khắc họa hình ảnh của chính mình trong bức chân dung thứ tư?</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Shiao Hai Pi","avatar":""},{"name":"King Shih-Chieh","avatar":""},{"name":"Hao Lei","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Na-Do","avatar":""},{"name":"Terri Kwan","avatar":""},{"name":"Luo Bei An","avatar":""},{"name":"Vincent Liang","avatar":""},{"name":"Hsi-Sheng Chen","avatar":""},{"name":"Chia-Kuei Chen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
