INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2010', 'Báo Thù', 'True Grit', 'https://phimimg.com/upload/vod/20231102-1/ae8c06919b7630330d5cc5bf24e96b09.jpg', 'https://phimimg.com/upload/vod/20231102-1/b378a19d0a019dc598eeb3b4ac35f6dd.jpg', '<p>True Grit cũng đánh dấu sự trở lại của dòng phim miền viễn Tây - vốn nổi bật trong nhiều thập kỷ của thế kỷ trước - nhưng theo một phong cách mới độc đáo hơn, táo bạo hơn qua bàn tay &quot;nhào nặn&quot; của hai anh em đa tài nhà Coen. Phim miền Tây trong những năm gần đây không còn được ưa chuộng như thời kỳ hoàng kim ngày trước nữa. Nhưng có thể nói với True Grit, Ethan và Joel Coen đã làm hồi sinh thể loại này.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Bruce Green","avatar":""},{"name":"Roy Lee Jones","avatar":""},{"name":"Paul Rae","avatar":""},{"name":"Nicholas Sadler","avatar":""},{"name":"Dakin Matthews","avatar":""},{"name":"Ed Corbin","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"Ruth Morris","avatar":""},{"name":"Leon Russom","avatar":""},{"name":"Jake Walker","avatar":""},{"name":"Don Pirl","avatar":""},{"name":"James Brolin","avatar":""},{"name":"Jar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324475);
