INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tru-ta-cuoi-cung', 'Lễ Trừ Tà Cuối Cùng', 'The Last Exorcism', 'https://phimimg.com/upload/vod/20231125-1/1c91079887914b79893d39acf828a21c.jpg', 'https://phimimg.com/upload/vod/20231125-1/f17292153ec81b70b7781da7a9de8f25.jpg', '<p>Sau nhiều năm thực hiện &quot;các lễ trừ tà&quot; và lấy tiền của các tín đồ, Reverend Marcus đến vùng nông thôn Louisiana cùng với một đoàn làm phim để ông có thể xua tan những gì ông tin là huyền thoại về sự chiếm hữu của ma quỷ. Vị tôn kính năng động chắc chắn rằng đây sẽ là một cuộc “trừ tà” thường lệ khác đối với một kẻ cuồng tín tôn giáo bị xáo trộn nhưng thay vào đó, trang trại đẫm máu của gia đình Sweetzer lại xuất hiện và một ác quỷ thực sự mà anh ta không bao giờ có thể tưởng tượng được.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Fabian","avatar":""},{"name":"Ashley Bell","avatar":""},{"name":"Iris Bahr","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Tony Bentley","avatar":""},{"name":"Shanna Forrestall","avatar":""},{"name":"Justin Shafer","avatar":""},{"name":"Carol Sutton","avatar":""},{"name":"Victoria Patenaude","avatar":""},{"name":"John Wilmot","avatar":""},{"name":"Becky Fly","avatar":""},{"name":"Denise Lee","avatar":""},{"name":"Logan Craig Reid","avatar":""},{"name":"Sofia Hujabre","avatar":""},{"name":"Adam Grimes","avatar":""},{"name":"Allen Boudreaux","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324475);
