INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tinh-nhue-2-ke-thu-ben-trong', 'Biệt Đội Tinh Nhuệ 2: Kẻ Thù Bên Trong', 'Elite Squad: The Enemy Within', 'https://phimimg.com/upload/vod/20231125-1/fb8cba41cda8587a9d5602cad737604f.jpg', 'https://phimimg.com/upload/vod/20231125-1/f68e825cb45b66b418b5320d267b4777.jpg', '<p>Tropa De Elite là xã hội thu nhỏ của thành phố Rio de Janeiro với những mặt tối tiêu cực, đầy rẫy tham nhũng, bạo lực, tội ác và nhấn mạnh, khai thác sâu bức tranh thối nát ngay chính lực lượng đại diện cho công lý - đội đặc nhiệm của cảnh sát chống tệ nạn buôn bán ma túy. Một số nhà bình luận cho rằng, bộ phim đã lột tả được một thực tế của ngành cảnh sát là những nhân viên trong lực lượng an ninh cũng phải thỏa hiệp để tồn tại...</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Wagner Moura","avatar":""},{"name":"Irandhir Santos","avatar":""},{"name":"André Ramiro","avatar":""},{"name":"Pedro Van-Held","avatar":""},{"name":"Maria Ribeiro","avatar":""},{"name":"Sandro Rocha","avatar":""},{"name":"Milhem Cortaz","avatar":""},{"name":"Tainá Müller","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"André Mattos","avatar":""},{"name":"Adriano Garib","avatar":""},{"name":"Julio Adrião","avatar":""},{"name":"Emílio Orciollo Netto","avatar":""},{"name":"Charles Fricks","avatar":""},{"name":"Fabrício Boliveira","avatar":""},{"name":"Pierre Santos","avatar":""},{"name":"Cadu Fáv","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324475);
