INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-no-tinh-yeu', 'Món Nợ Tình Yêu', 'Romantic Debtors', 'https://phimimg.com/upload/vod/20231124-1/d5c13e47c0e0f63c7dca1e825edfed55.jpg', 'https://phimimg.com/upload/vod/20231124-1/235d664141abe9ec94a58338f41c361e.jpg', '<p>Một cảnh sát mắc nợ liên tục bị một người phụ nữ làm việc gọi điện đòi nợ. Khi tình cờ gặp nhau, họ bị thu hút bởi nhau và không nhận ra rằng họ đã có một mối quan hệ thù địch qua điện thoại.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Im Chang-jung","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Lee Jae-gu","avatar":""},{"name":"Jo Deok-hyeon","avatar":""},{"name":"Kim Jung-pal","avatar":""},{"name":"Jeong Eun-u","avatar":""},{"name":"Kim Sa-hui","avatar":""},{"name":"Kang Jae-seop","avatar":""},{"name":"Bang Su-hyeong","avatar":""},{"name":"Kim Won-jin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
