INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chang-may-man', 'Anh Chàng May Mắn', 'Cyrus', 'https://phimimg.com/upload/vod/20231124-1/8061bc69099b5dca662131276ddbbef7.jpg', 'https://phimimg.com/upload/vod/20231124-1/694fefbb8038af166b7247d9f10422f9.jpg', '<p>John Kilpatrick (John C. Reilly) đã li dị vợ được bảy năm, và anh đang gặp khó khăn trong việc cân bằng cuộc sống mới của mình. John bị trầm cảm, nhất là khi nghe tin vợ cũ đi lấy chồng. Sau lần tình cờ gặp Molly Fawcett (Marisa Tomei) ở một bữa tiệc, anh nghĩ rằng mình đã tìm được một nửa hoàn hảo một lần nữa. Chỉ có một vấn đề, đó là Cyrus (Jonah Hill), cậu con trai 21 tuổi của Molly. Cyrus yêu mẹ của mình khá đặc biệt, sẽ làm mọi cách để bảo vệ Molly theo những gì cậu ta cảm thấy tốt nhất và chắc chắn sẽ không sẵn sàng chia sẻ cô với bất kỳ ai, đặc biệt là John. John phải tìm mọi cách để đến được với mối tình lãng mạn của mình, bất chấp mọi sự can thiệp cố ý hay vô ý của Cyrus...</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"John C. Reilly","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Kathy Wittes","avatar":""},{"name":"Diane Mizota","avatar":""},{"name":"Katie Aselton","avatar":""},{"name":"Jamie Donnelly","avatar":""},{"name":"Tim Guinee","avatar":""},{"name":"Steve Zissis","avatar":""},{"name":"Bill ''Bunky'' Miller","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
