INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-ho-piranha', 'Cá Hổ Piranha', 'Piranha 3D', 'https://phimimg.com/upload/vod/20231124-1/ba67f4c7344e224caadfad959d916dff.jpg', 'https://phimimg.com/upload/vod/20231124-1/3ffc70efce206511a2cf6a39cc7412d4.jpg', '<p>Làm lại từ bộ phim cùng tên năm 1978, &quot;Piranha 3D&quot; xoay quanh việc một vụ động đất đã làm nứt đáy hồ Victoria và giải phóng hàng nghìn con cá Piranha - loài cá ăn thịt hung dữ người thời tiền sử. Với hàm răng sắc nhọn, những con cá Piranha dữ tợn trở thành nỗi kinh hoàng đối với cư dân thị trấn. &nbsp;Vào ngày 4/7, bên bờ hồ Victoria xinh đẹp ở Arizona đã tổ chức một lễ hội lớn. Nhưng một cơn địa chấn dưới mặt hồ đã giải phóng hàng triệu con cá hổ Piranha. Và cảnh sát trưởng Julie Forester (Elisabeth Shue) phải bất chấp mọi nguy hiểm để bảo vệ gia đình mìmh và cùng người dân trong thị trấn tiêu diệt loài cá ăn thịt người này.</p>', 'Full', 1, 'single', 'completed', 8, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elisabeth Shue","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Steven R. McQueen","avatar":""},{"name":"Jessica Szohr","avatar":""},{"name":"Kelly Brook","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Riley Steele","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Devra Korwin","avatar":""},{"name":"Brooklynn Proulx","avatar":""},{"name":"Sage Ryan","avatar":""},{"name":"Cody Longo","avatar":""},{"name":"Ricardo Chavira","avatar":""},{"name":"Paul Schee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
