INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('72-khach-tro', '72 Khách Trọ', '72 Tenants of Prosperity', 'https://phimimg.com/upload/vod/20231124-1/9dcd2f7912756d7559674b6d801474ff.jpg', 'https://phimimg.com/upload/vod/20231124-1/deaf4b614a6dfd7131c9252059cdfa49.jpg', '<p>Cáp Công và Thạch Kiên là hai anh em kết nghĩa, cả hai cùng phải lòng cô bạn Tiểu Đào Hồng vốn là con &quot;ghẻ&quot; của bà chủ phòng trọ keo kiệt bủn xỉn ở Sư Tử Sơn. Trong một lần giúp cô khỏi cảnh gả ép, đồng thời 70 vị khách trọ nghèo khổ cũng khỏi phải đóng tiền thuê nhà nên cô rất cảm kích, cả hai đều muốn cưới Tiểu Đào Hồng nhưng Cáp Công ma lanh hơn đã dùng mẹo thắng được, Thạch Kiên không chịu, thế là từ đó Thạch Kiên và Cáp Công sinh ra thù ghét nhau. Vài chục năm sau Cáp Công và Thạch Kiên mở cửa hàng điện thoại cạnh tranh nhau quyết liệt ở một khu phố sầm uất tại Hồng Kông, trớ trêu thay những người con của họ lại bắt đầu cảm nhau gây nên nhiều tình huống khó xử cho hai ông bố vốn không ưa nhau...</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jacky Cheung","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Bosco Wong","avatar":""},{"name":"Linda Chung","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Liang Tian","avatar":""},{"name":"Kate Tsui","avatar":""},{"name":"Natalis Chan","avatar":""},{"name":"Bernice Liu","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Chin Siu-ho","avatar":""},{"name":"Prudence Liew Mei-","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
