INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('72-khach-tro', '72 Khách Trọ', '72 Tenants of Prosperity', '72 khách trọ 72 tenants of prosperity jacky cheung eric tsang anita yuen bosco wong linda chung wong cho-lam stephy tang michael tse liang tian kate tsui natalis chan bernice liu yiu-cheung lai tenky tin kai-man wu fung mak cheung-ching sam lee chin siu-ho prudence liew mei- ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-thuo-tinh-tho', 'Một Thuở Tình Thơ', 'Flipped', 'https://phimimg.com/upload/vod/20231121-1/b6105626ae8a4c62df3efde7c7ca4da9.jpg', 'https://phimimg.com/upload/vod/20231121-1/7cab2618dd036ac8cd22651131367929.jpg', '<p>Năm 1957, khi học sinh lớp hai Bryce Loski và Julianna &quot;Juli&quot; Baker lần đầu tiên gặp nhau, Juli biết tình yêu của nó, nhưng Bryce không chắc chắn và cố gắng tránh Juli. Đến lớp sáu, năm 1961, Bryce cố gắng thoát khỏi Juli bằng cách hẹn hò với những quầy hàng Sherry, người mà Juli coi thường. Tuy nhiên, người bạn tốt nhất của Bryce, Garrett, quan tâm đến Sherry và cuối cùng nói với cô sự thật về Bryce yêu cầu cô ra ngoài; Cô ấy không lấy nó tốt. Từ quan điểm của Juli, Bryce trả lại cảm xúc của mình, nhưng nhút nhát. Sau khi tìm ra Bryce và Sherry đã chia tay, cô nghĩ rằng cô có thể có Bryce trở lại. Nhưng sau đó họ xem xét lại các quyết định của họ khi thời gian trôi qua. Năm 1962, ông nội của Bryce Chet Duncan chuyển đến với gia đình. Chet có quan điểm khác nhau về Juli. Có một cây sycamore lớn, cũ mà Juli yêu mà không ai hiểu được. Một ngày nọ, nó bị cắt giảm bởi một nhóm cảnh quan để một ngôi nhà có thể được xây dựng ở đó, bất chấp sự phản đối của Juli. Cô trở nên rất chán nản sau đó, như cây cho phép cô nhìn thế giới một cách giác ngộ hơn. Cha cô cho cô một bức tranh của cây.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Madeline Carroll","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Anthony Edwards","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"Penelope Ann Miller","avatar":""},{"name":"Aidan Quinn","avatar":""},{"name":"Kevin Weisman","avatar":""},{"name":"Morgan Lily","avatar":""},{"name":"Ryan Ketzner","avatar":""},{"name":"Ashley Taylor","avatar":""},{"name":"Israel Broussard","avatar":""},{"name":"Cody H. Carolin","avatar":""},{"name":"Inga R. Wilson","avatar":""},{"name":"Michael Bolten","avatar":""},{"name":"Shane Harpe","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
