INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-ke-phuc-thu', 'Cái chết kẻ phục thù', 'Revenge: A Love Story', 'https://phimimg.com/upload/vod/20231121-1/918ad9341eb0937384d41969e5250ad6.jpg', 'https://phimimg.com/upload/vod/20231121-1/4df77685b783941f2fe79f5d13171f68.jpg', '<p>Một kẻ giết người hàng loạt đã giết hại dã man một số cảnh sát và những người vợ đang mang thai của họ. Sau một cuộc điều tra nhanh chóng, kẻ sát nhân được tiết lộ là Kit, người mà thám tử phụ trách vụ án biết từ một vụ án trước đó. Ngày xửa ngày xưa, Kit là một cậu bé ngây thơ ở một ngôi làng nông thôn, người cũng phải lòng cậu học sinh trung học ngây thơ Wing. Sau cái chết của bà nội Wing, Kit đã giải cứu Wing khỏi một cơ sở chăm sóc nuôi dưỡng và cả hai nhanh chóng yêu nhau. Tuy nhiên, mối tình lãng mạn của họ kết thúc sớm khi một cảnh sát địa phương bắt giữ họ. Những sự kiện tiếp theo đã đặt mầm mống cho con đường báo thù đáng sợ của Kit.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Juno Mak","avatar":""},{"name":"Chin Siu-ho","avatar":""},{"name":"Sora Aoi","avatar":""},{"name":"Tony Liu","avatar":""},{"name":"Wong Shu-Tong","avatar":""},{"name":"Lam Ling Yuen","avatar":""},{"name":"Candy Cheung Shuet-Kan","avatar":""},{"name":"Tony Ho","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324475);
