INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dien-cuong', 'Kẻ Điên Cuồng', 'Crazy on the Outside', 'https://phimimg.com/upload/vod/20231123-1/7c7afbd06af861ced80c5400e9614f7f.jpg', 'https://phimimg.com/upload/vod/20231123-1/1644bce2ab34c5003ee1c257c5b9d1b8.jpg', '<p>Một cựu tội phạm mới được ân xá gặp khó khăn trong việc thích nghi với cuộc sống bình thường kỳ quặc bên ngoài nhà tù. Anh ta đã trải qua ba năm sau song sắt sau khi bị bắt quả tang phạm tội và chịu trách nhiệm cho người bạn nguy hiểm hơn nhiều của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Jeanne Tripplehorn","avatar":""},{"name":"Helen Slayton-Hughes","avatar":""},{"name":"Kenton Duty","avatar":""},{"name":"Daniel Booko","avatar":""},{"name":"Karle Warren","avatar":""},{"name":"Robert Baker","avatar":""},{"name":"Casey Sander","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Malcolm Goodwin","avatar":""},{"name":"John Hayden","avatar":""},{"name":"Meeghan Holaway","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
