INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai', 'Huyền Thoại', 'Legendary', 'https://phimimg.com/upload/vod/20231120-1/fc937b18b184d9921a1d68daa9066ed1.jpg', 'https://phimimg.com/upload/vod/20231120-1/41fb99534e2f7833fdcc1956868ac2d0.jpg', '<p>Một thiếu niên thông minh trong sách tham gia đội đấu vật của trường như một cách để đoàn tụ những thành viên còn sống sót trong gia đình, những người đã chia tay nhau sau cái chết của cha anh, một huyền thoại đấu vật ở trường đại học, 10 năm trước.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patricia Clarkson","avatar":""},{"name":"Devon Graye","avatar":""},{"name":"John Cena","avatar":""},{"name":"Madeleine Martin","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"John Posey","avatar":""},{"name":"Tyler Posey","avatar":""},{"name":"Teo Olivares","avatar":""},{"name":"Kareem J. Grimes","avatar":""},{"name":"Angelena Swords","avatar":""},{"name":"Lara Grice","avatar":""},{"name":"Patrick Cox","avatar":""},{"name":"Deneen Tyler","avatar":""},{"name":"Andrew Sensenig","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Courtney J. Cla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
