INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-nguoi-me', 'Bí Mật Người Mẹ', 'Incendies', 'https://phimimg.com/upload/vod/20231120-1/979aa72a90fa948d6bcbe1b26fd690cf.jpg', 'https://phimimg.com/upload/vod/20231120-1/4e22077c41729e52a24604630f6d84d6.jpg', '<p>Tờ di chúc của mẹ đã khiến hai anh em song sinh Jeanne và Simon tới vùng Trung Đông để chuyển hai lá thư - một cho người cha bị mất tích và một cho một người anh em mà họ chưa quen biết. Cuộc hành trình đã đưa họ đến với những bí mật mà họ chưa từng biết về mẹ mình.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Lubna Azabal","avatar":""},{"name":"Mélissa Désormeaux-Poulin","avatar":""},{"name":"Maxim Gaudette","avatar":""},{"name":"Rémy Girard","avatar":""},{"name":"Allen Altman","avatar":""},{"name":"Abdelghafour Elaaziz","avatar":""},{"name":"Dominique Briand","avatar":""},{"name":"Frédéric Paquet","avatar":""},{"name":"Ahmad Massad","avatar":""},{"name":"John Dunn-Hill","avatar":""},{"name":"Jackie Sawiris","avatar":""},{"name":"Lara Atalla","avatar":""},{"name":"Baya Belal","avatar":""},{"name":"Yousef Shweihat","avatar":""},{"name":"Karim Babin","avatar":""},{"name":"Mohamed Majd","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324475);
