INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-shippden-toa-thap-bi-mat', 'Naruto Shippūden: Tòa Tháp Bị Mất', 'Naruto Shippūden: The Lost Tower', 'https://phimimg.com/upload/vod/20231120-1/35e669074a12a933885836fcc896619d.jpg', 'https://phimimg.com/upload/vod/20231120-1/ac6f036b58d2f560306454531cfd569c.jpg', '<p>Được giao nhiệm vụ một để đi bắt Mukade, một missing-nin ( ninja bỏ trốn ). Uzumaki Naruto đc sắp đặt vào di tích lịch sử vẻ vang đã bị tàn phá: Ouran, nơi Naruto truy đuổi các ninja đang làm việc cho Mukade và Mukade. Mục tiêu của Mukade đã được tiết lộ là để có một leyline hoạt động bên trong những sự tàn phá và hắn sẽ giải phóng sức mạnh của leyline, gây ra một ánh sáng để bao bọc Naruto và gửi Nar vào quá khứ, 20 năm trước khi mọi chuyện bắt đầu. Khi Naruto thức dậy trong quá khứ, Nar đã đc tiếp xúc, nói chuyện và chiến đấu cùng Người Cha Vĩ Đại, Hokage Đệ Tứ, Namikaze</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Nobuaki Fukuda","avatar":""},{"name":"Kenji Hamada","avatar":""},{"name":"Keiko Nemoto","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Yumi Touma","avatar":""},{"name":"Yuko Kobayashi","avatar":""},{"name":"Fujiko Takimoto","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Mayuki Makiguchi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f76788