INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-mot-the-gioi-tot-dep-hon', 'Trong một thế giới tốt đẹp hơn', 'In a Better World', 'https://phimimg.com/upload/vod/20231116-1/98114dfd0bc9feb4721795dbff397a51.jpg', 'https://phimimg.com/upload/vod/20231116-1/6784475db9e02541849e460850ebab51.jpg', '<p>Cuộc sống của hai gia đình Đan Mạch đan xen nhau, và một tình bạn phi thường nhưng đầy rủi ro đã chớm nở. Nhưng sự cô đơn, yếu đuối và sầu muộn nằm trong sự chờ đợi.</p>', 'Full', 1, 'single', 'completed', 22, 2010, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Mikael Persbrandt","avatar":""},{"name":"Trine Dyrholm","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"William Jøhnk Nielsen","avatar":""},{"name":"Markus Rygaard","avatar":""},{"name":"Martin Buch","avatar":""},{"name":"Anette Støvelbæk","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Tina Gylling Mortensen","avatar":""},{"name":"Stig Hoffmeyer","avatar":""},{"name":"Camilla Bendix","avatar":""},{"name":"Birthe Neumann","avatar":""},{"name":"Susanne Juhász","avatar":""},{"name":"Elsebeth Steentoft","avatar":""},{"name":"Bodil Jørgensen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
