INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-chu-rua-sammy', 'Cuộc Phiêu Lưu Của Chú Rùa Sammy', 'A Turtle''s Tale: Sammy''s Adventures', 'https://phimimg.com/upload/vod/20231116-1/d6a0edd5a55bda8b8e092c0f97b122cd.jpg', 'https://phimimg.com/upload/vod/20231116-1/63069e83f99ae96cb788e2550082efac.jpg', '<p>Sammy, một con rùa biển, sinh ra trên một bãi biển hoang vắng và cố gắng trèo ra khỏi ổ trứng. Bị bắt bởi 1 con chim mòng biển, cậu đấu tranh cho cuộc sống của mình và cố thoát ra, vô tình chim mòng biển đụng đầu với một chim mòng biển khác, cũng mang theo con mồi của nó, chú rùa biển cái mang tên Shelly. Câu chuyện bắt đầu từ đây...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2010, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Yuri Lowenthal","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Isabelle Fuhrman","avatar":""},{"name":"Melanie Griffith","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Robert Sheehan","avatar":""},{"name":"Kathy Griffin","avatar":""},{"name":"Jenny McCarthy-Wahlberg","avatar":""},{"name":"Gigi Perreau","avatar":""},{"name":"Eric Unger","avatar":""},{"name":"Kierstin Koppel","avatar":""},{"name":"Pat Carroll","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Cam Clarke","avatar":""},{"name":"Alan Shearman","avatar":""},{"name":"Scott Menvi","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324475);
