INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('coi-chet', 'Cõi Chết', 'The Dead', 'https://phimimg.com/upload/vod/20231116-1/cf23d9f9a661a9fe7cfebae098f7760f.jpg', 'https://phimimg.com/upload/vod/20231116-1/bb9b688dbfc1f8b3530d292ada93c3d8.jpg', '<p>Khi chuyến bay sơ tán cuối cùng ra khỏi châu Phi bị chiến tranh tàn phá bị rơi ngoài khơi, Trung úy Kỹ sư Không quân Hoa Kỳ Brian Murphy nổi lên như người sống sót duy nhất ở vùng đất nơi người chết đang sống lại và tấn công người sống.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Julia Scott-Russell","avatar":""},{"name":"Rob Freeman","avatar":""},{"name":"Ben Crowe","avatar":""},{"name":"Dan Morgan","avatar":""},{"name":"Prince David Oseia","avatar":""},{"name":"David Dontoh","avatar":""},{"name":"Glenn Salvage","avatar":""},{"name":"Howard J. Ford","avatar":""},{"name":"Jonathan Ford","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324475);
