INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shrek-cuoc-phieu-luu-cuoi-cung', 'Shrek: Cuộc Phiêu Lưu Cuối Cùng', 'Shrek Forever After', 'https://phimimg.com/upload/vod/20231120-1/b8f31dd838f8ccbaf63728580e7a41b0.jpg', 'https://phimimg.com/upload/vod/20231120-1/ada781e52bea1dfb54122bd64eec94ff.jpg', '<p>Cuộc sống Shrek giờ hoàn toàn thay đổi sau cuộc gặp gỡ định mệnh với công chúa Fiona. Thay vì khiến mọi người sợ hãi như trước đây, anh giờ đây đã trở thành một người chuyên giải quyết rắc rối cho người khác. Chính vì thế cuộc sống của Shrek bị đảo lộn, anh không còn cảm thấy tự do như trước. Bữa tiệc sinh nhật các con của Shrek thành giọt nước làm tràn ly khi mọi người bắt chàng ta mua vui cho trẻ nhỏ. Shrek bỏ đi và vướng vào bẫy do tên lừa đảo Rumpelstiltskin giăng ra: anh chàng ước có một ngày làm chằn tình như xưa để mọi người phải sợ hãi mình. Cái giá phải trả là Rumpelstiltskin tước đi ngày Shrek ra đời, nghĩa là gã chằn tinh tên Shrek không hề tồn tại.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Walt Dohrn","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Kathy Griffin","avatar":""},{"name":"Mary Kay Place","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Meredith Vieira","avatar":""},{"name":"Ryan Seacrest","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Larry King","avatar":""},{"name":"Reg","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324475);
