INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-cua-henry', 'Tội ác của Henry', 'Henry''s Crime', 'https://phimimg.com/upload/vod/20231120-1/23400a385d689de6548786e361c058d8.jpg', 'https://phimimg.com/upload/vod/20231120-1/acba38d13b4bace7e046aa00408cdc5c.jpg', '<p>Một người đàn ông vô mục đích bị tống vào tù vì một tội ác mà anh ta không phạm phải, một kẻ lừa đảo cũ nhắm vào chính ngân hàng mà anh ta bị tống đi vì tội cướp.</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"James Caan","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Fisher Stevens","avatar":""},{"name":"Danny Hoch","avatar":""},{"name":"Bill Duke","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Currie Graham","avatar":""},{"name":"David Costabile","avatar":""},{"name":"Jordan Gelber","avatar":""},{"name":"Audrey Lynn Weston","avatar":""},{"name":"Julie Ordon","avatar":""},{"name":"Guy Boyd","avatar":""},{"name":"Peter Appel","avatar":""},{"name":"David Bishins","avatar":""},{"name":"Drew McVety","avatar":""},{"name":"Tim Snay","avatar":""},{"name":"Carlos","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
