INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-ac-cua-henry', 'Tội ác của Henry', 'Henry''s Crime', 'tội ác của henry henry''s crime keanu reeves vera farmiga james caan judy greer fisher stevens danny hoch bill duke peter stormare currie graham david costabile jordan gelber audrey lynn weston julie ordon guy boyd peter appel david bishins drew mcvety tim snay carlos ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-tuong-sieu-nhien-2', 'Hiện Tượng Siêu Nhiên 2', 'Paranormal Activity 2', 'https://phimimg.com/upload/vod/20231119-1/39f7613df66d740004d8cc45958116d7.jpg', 'https://phimimg.com/upload/vod/20231119-1/ac0666e2820da349e12c72746a729d50.jpg', '<p>Câu chuyện bắt đầu khi một gia đình ba người đón chào sự ra đời của bé Hunter. Cha, mẹ và cô chị gái đang tuổi thiếu niên đều vô cùng hào hứng. Cả chú chó Abby nữa. Sau một sự kiện, gia đình quyết định dựng hệ thống camera an ninh bao quát toàn bộ khu nhà. Một thành viên trong gia đình còn yêu thích việc quay phim đến mức luôn kè kè bên mình chiếc máy quay cầm tay.Bóng đêm trùm xuống và người mẹ bắt đầu nghe thấy nhiều tiếng động lạ, cũng như chứng kiến xoong chảo tự rơi khỏi giá bếp hay những cánh cửa tự đóng sập sau lưng mình. Rồi cô con gái cũng bắt đầu nghe được các âm thanh và vô tình bắt được trong camera của mình cảnh thứ gì đấy đang chuyển động. Chú chó nổi giận hằng đêm, nhưng không ai có phản ứng gì. Người cha quyết định đích thân chứng tỏ cho các thành viên còn lại trong gia đình rằng nhất định phải có một cách giải thích hợp lý cho mọi chuyện. Gần như ông đã thành công. Cuối cùng, cả gia đình quyết định ngồi xem lại những thước phim được camera an ninh ghi lại. Và họ bắt đầu nhận ra có điều gì đó không bình thường ở những cánh cửa tự đóng sầm lại, hay ai đó bị kéo lê quanh ngôi nhà. Họ nhận thức được rằng những thực thể kia dường như hành động ngày càng hung bạo hơn khi đêm xuống. Chỉ cho đến cuối cùng họ mới biết được rằng những thực thể giận giữ đang muốn gì và ai hay cái gì đang thực hiện hành động hằn thù...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sprague Grayden","avatar":""},{"name":"Brian Boland","avatar":""},{"name":"Molly Ephraim","avatar":""},{"name":"Katie Featherston","avatar":""},{"name":"Micah Sloat","avatar":""},{"name":"Seth Ginsberg","avatar":""},{"name":"Vivis Cortez","avatar":""},{"name":"William Juan Prieto","avatar":""},{"name":"Jackson Xenia Prieto","avatar":""},{"name":"David Bierend","avatar":""},{"name":"Emily Brobst","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324475);
