INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vo-dich', 'Nhà Vô Địch', 'Secretariat', 'https://phimimg.com/upload/vod/20231119-1/702667c290e5987a2cac61d49621a680.jpg', 'https://phimimg.com/upload/vod/20231119-1/934d312b72cb2d99c611fa1be0a31221.jpg', '<p>Người nội trợ và người mẹ Penny Chenery đồng ý tiếp quản Chuồng ngựa Meadow có trụ sở tại Virginia của người cha ốm yếu của cô, mặc dù cô không có kiến thức về đua ngựa. Chống lại mọi khó khăn, Chenery - với sự giúp đỡ của huấn luyện viên kỳ cựu Lucien Laurin - xoay sở để điều hướng công việc kinh doanh do nam giới thống trị, cuối cùng nuôi dưỡng người chiến thắng Triple Crown đầu tiên sau 25 năm.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diane Lane","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Dylan Walsh","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Nelsan Ellis","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Otto Thorwarth","avatar":""},{"name":"Michael Harding","avatar":""},{"name":"Richard Fullerton","avatar":""},{"name":"Tim Ware","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Keith Austin","avatar":""},{"name":"Kevin Connolly","avatar":""},{"name":"Eric Lange","avatar":""},{"name":"Drew Roy","avatar":""},{"name":"Carissa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
