INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-tuong-sieu-nhien-o-tokyo', 'Hiện Tượng Siêu Nhiên: Ở Tokyo', 'Paranormal Activity: Tokyo Night', 'https://phimimg.com/upload/vod/20231117-1/0a3436cea5ff2a10df1c06b48ffe035a.jpg', 'https://phimimg.com/upload/vod/20231117-1/80419285d3e2f9c548ff8bb48d239adf.jpg', '<p>Koichi chăm sóc em gái của mình, người vừa trở về sau chuyến du lịch nước ngoài ở Hoa Kỳ vì cô ấy không được khỏe. Trong khi chăm sóc cho cô ấy, anh ấy ghi lại bằng chứng về những bóng ma trong nhà của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Aoi Nakamura","avatar":""},{"name":"Noriko Aoyama","avatar":""},{"name":"Kosuke Kujirai","avatar":""},{"name":"Ayako Yoshitani","avatar":""},{"name":"Kazuyoshi Tsumura","avatar":""},{"name":"Maaya Morinaga","avatar":""},{"name":"Tōze Yamada","avatar":""},{"name":"Shinji Matsubayashi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
