INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-lo-luan-don', 'Đại Lộ Luân Đôn', 'London Boulevard', 'https://phimimg.com/upload/vod/20231117-1/a717e00e477c946ba65dc77658fa757d.jpg', 'https://phimimg.com/upload/vod/20231117-1/aac05cc3fe7cf496114de4ac6840375e.jpg', '<p>Dựa trên cuốn tiểu thuyết của nhà văn Ken Bruen, London Boulevard kể về tên tội phạm vừa mãn hạn từ vì tội hành hung ở ở South London. Cố gắng bỏ đi quá khứ để có thể sống một cuộc sống bình thường như bao người khác, nhân vật trung tâm của câu chuyện bắt đầu đi kiếm việc làm và sau đó trở thành một tên sai vặt bên cạnh cô diễn viên trẻ tuổi (Knightley).Công việc trong thế giới hào nhoáng đã chấm dứt những chuỗi ngày sống trong thế giới ngầm và bắt đầu cho một guồng quay mới với tiền bạc, xe cộ, tình yêu... Theo tờ Variety, bộ phim sẽ hoàn toàn lấy bối cảnh ở London với những cảnh quay rất chân thực và sống động.Sau khi giành Quả cầu vàng với bộ phim hài In Bruges, London Boulevard là dự án điện ảnh lớn đầu tiên của ...</p>', 'Full', 1, 'single', 'completed', 10, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Anna Friel","avatar":""},{"name":"Ben Chaplin","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Sanjeev Bhaskar","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Ophelia Lovibond","avatar":""},{"name":"Jamie Campbell Bower","avatar":""},{"name":"Matt King","avatar":""},{"name":"Donald Sumpter","avatar":""},{"name":"Velibor Topic","avatar":""},{"name":"Lee Boardman","avatar":""},{"name":"Jonny Coyne","avatar":""},{"name":"Alan Williams","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324475);
