INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-tuong-phat-3', 'Truy Tìm Tượng Phật 3', 'Ong-Bak 3', 'https://phimimg.com/upload/vod/20231116-1/33fb364fa153ce138c27172c8ce25ab4.jpg', 'https://phimimg.com/upload/vod/20231116-1/17d6bd3efb7ca7575522423725404658.jpg', '<p>Ông Bak 3 nhặt lên nơi Ong Bak 2 đã rời đi. Tiến bị bắt và gần như bị đánh đến chết trước khi anh ta được cứu và mang về dân làng Kana Khone. Ở đó, ông được dạy thiền và cách đối phó với nghiệp chướng của mình, nhưng rất sớm, đối thủ vòm của anh ta trở về thách thức Tiến cho một cuộc đấu tay đôi cuối cùng.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Dan Chupong","avatar":""},{"name":"Sarunyu Wongkrachang","avatar":""},{"name":"Sorapong Chatree","avatar":""},{"name":"Nirut Sirijanya","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Choomporn Theppitak","avatar":""},{"name":"Patthama Panthong","avatar":""},{"name":"Primorata Dejudom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324475);
