INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-illusionist', 'The Illusionist', 'The Illusionist', 'https://phimimg.com/upload/vod/20231116-1/98bd3b2164728b4f4f2961feed03946d.jpg', 'https://phimimg.com/upload/vod/20231116-1/7a1bf582684f6af396f5d46938efb24e.jpg', '<p>Một nhà ảo thuật người Pháp tới Scotland để làm việc. Anh gặp một cô gái trẻ ở một ngôi làng nhỏ. Cuộc phiêu lưu tiếp theo của họ ở Edinburgh đã thay đổi cuộc đời cả hai mãi mãi.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Claude Donda","avatar":""},{"name":"Eilidh Rankin","avatar":""},{"name":"Didier Gustin","avatar":""},{"name":"Jil Aigrot","avatar":""},{"name":"Jacques Tati","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
