INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13', '13', '13', 'https://phimimg.com/upload/vod/20231129-1/978d347a94056123380d77a0ab7ed379.jpg', 'https://phimimg.com/upload/vod/20231129-1/ea8b64b0d42e7bc9754ad56418420160.jpg', '<p>Một chàng trai trẻ ngây thơ giả định danh tính của một người đàn ông đã chết và thấy mình bị lôi kéo vào một thế giới ngầm của quyền lực, bạo lực và cơ hội, nơi những người đàn ông đánh bạc sau những cánh cửa đóng kín bằng mạng sống của những người đàn ông khác.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Riley","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Alice Barrett","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Michael Berry Jr.","avatar":""},{"name":"Starla Benford","avatar":""},{"name":"Daisy Tahan","avatar":""},{"name":"Carlos Reig-Plaza","avatar":""},{"name":"Doug Kruse","avatar":""},{"name":"Chuck Zito","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
