INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-ke-hoach-tuyet-diet-super-saiyan', 'Bảy Viên Ngọc Rồng: Kế Hoạch Tuyệt Diệt Super Saiyan', 'Dragon Ball: Plan to Eradicate the Super Saiyans', 'https://phimimg.com/upload/vod/20231117-1/7d1074ded54474141aac092b16c3679b.jpg', 'https://phimimg.com/upload/vod/20231117-1/67e9884de97095b54fa9955b7981b91f.jpg', '<p>Tiến sĩ Raichi là một trong những người sống sót duy nhất của Tuffles, một chủng tộc đã từng sống trên hành tinh Planet trước của Saiyans. Saiyans không chỉ tàn sát toàn bộ dân Tuffle, nhưng cũng đã đánh cắp công nghệ của họ và chinh phục các hành tinh, thay đổi tên hành tinh Vegeta trong danh dự của nhà vua của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Ryou Horikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
