INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-vu-thoi-dai-sat-thu', 'Kiếm Vũ: Thời Đại Sát Thủ', 'Reign of Assassins', 'https://phimimg.com/upload/vod/20231117-1/868785fb4fee727fb8839df0a6333645.jpg', 'https://phimimg.com/upload/vod/20231117-1/db0e840d853b8f957ef803750bb036cf.jpg', '<p>Phim kể về câu chuyện rượt đuổi truy sát của nữ sát thủ Lôi Bút có mối thù không đội trời chung với Tằng Tịnh. Tuy nhiên, nhân vật hiệp khách này đã rút khỏi giang hồ và kết hôn với 1 chàng thư sinh chân yếu tay mềm A Thịnh. Để chống trả lại âm mưu của sát thủ và bảo vệ người chồng vô can, Tằng Tịnh không quản hiểm nguy khó khăn, nhất quyết không chịu khuất phục kẻ địch...</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Michelle Yeoh","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Wang Xueqi","avatar":""},{"name":"Barbie Hsu","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Jiang Yiyan","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Nina Pau Hei-Ching","avatar":""},{"name":"King Shih-Chieh","avatar":""},{"name":"Li Zonghan","avatar":""},{"name":"You Benchang","avatar":""},{"name":"Matt Wu","avatar":""},{"name":"Angeles Woo","avatar":""},{"name":"Hu Xiaoguang","avatar":""},{"name":"Han Zhi","avatar":""},{"name":"Qin Pengfei","avatar":""},{"name":"Tong Lei","avatar":""},{"name":"Zhang Aiqin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
