INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chon-song', 'Chôn Sống', 'Buried', 'https://phimimg.com/upload/vod/20231117-1/9c5f1ce72dfe7781115ab035e53f679d.jpg', 'https://phimimg.com/upload/vod/20231117-1/915a48a3fac8f52dadf8ad673cfc0751.jpg', '<p>Câu chuyện về Conroy, một tài xế xe tải. Một ngày kia, anh tỉnh dậy thì thấy mình nằm sâu dưới lòng đất mà không hề biết ai đẩy anh vào tình trạng này và tại sao lại bị như vậy. Bị chôn sống dưới đất với một chiếc điện thoại di động và một cái bật lửa, anh ra sức đấu tranh cho sự sống của mình từ dưới địa ngục. &nbsp;Đấu tranh với nỗi hoảng sợ, tuyệt vọng và mê sảng, khi bật lửa dần cạn kiệt, ôxy để thở hầu như sắp hết, Conroy chỉ có 90 phút để thoát khỏi cái bẫy chết người này trước khi cơn ác mộng tồi tệ nhất của anh trở thành sự thật.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"José Luis García Pérez","avatar":""},{"name":"Robert Paterson","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Samantha Mathis","avatar":""},{"name":"Ivana Miño","avatar":""},{"name":"Warner Loughlin","avatar":""},{"name":"Erik Palladino","avatar":""},{"name":"Kali Rocha","avatar":""},{"name":"Chris William Martin","avatar":""},{"name":"Cade Dundish","avatar":""},{"name":"Mary Birdsong","avatar":""},{"name":"Kirk Baily","avatar":""},{"name":"Anne Lockhart","avatar":""},{"name":"Robert Clotworthy","avatar":""},{"name":"Michalla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324475);
