INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-tan-bao', 'Đế Chế Tàn Bạo', 'The Round Up', 'https://phimimg.com/upload/vod/20231117-1/fc7389c96da616439c071b0262080ba1.jpg', 'https://phimimg.com/upload/vod/20231117-1/a08494d0a92c16e6c1423f177a513e46.jpg', '<p>Bộ phim tái hiện lại cuộc bố ráp kinh hoàng tại sân vận động Vel d’Hiv năm 1942, khi 13 ngàn dân Do Thái bị thu gom tại Paris. Phim kể lại những câu chuyện bi thảm trong cuộc bố ráp bởi Đức quốc xã qua cái nhìn của một nhóm trẻ em, được xem là một bước tiến quan trọng trong việc Pháp thừa nhận sự đồng lõa của mình trong các tội ác thời Đức chiếm đóng. Xoay quanh nhân vât chính Josep Weismann, hiện đã 80 tuổi, và là một trong 4.051 trẻ em bị bắt trong cuộc bố ráp ngày đó. Không giống như hầu hết các bạn bè cùng cảnh ngộ, cậu bé Josep 11 tuổi đã tìm cách trốn thoát...</p>', 'Full', 1, 'single', 'completed', 22, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Gad Elmaleh","avatar":""},{"name":"Raphaëlle Agogué","avatar":""},{"name":"Sylvie Testud","avatar":""},{"name":"Hugo Leverdez","avatar":""},{"name":"Oliver Cywie","avatar":""},{"name":"Mathieu Di Concetto","avatar":""},{"name":"Romain Di Concetto","avatar":""},{"name":"Rebecca Marder","avatar":""},{"name":"Anne Brochet","avatar":""},{"name":"Isabelle Gélinas","avatar":""},{"name":"Thierry Frémont","avatar":""},{"name":"Catherine Allégret","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Adèle Exar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 