INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-dao-thai', 'Võ Sĩ Đạo Thái', 'The Samurai of Ayothaya', 'https://phimimg.com/upload/vod/20231115-1/fc55628aa607b2a02361c85a58751f68.jpg', 'https://phimimg.com/upload/vod/20231115-1/d4c06e829b320821d0118b174d59d503.jpg', '<p>Dựa trên một nhân vật có thật, bộ phim kể về câu chuyện của Yamada Nagamasa, một chiến binh người Nhật định cư ở Ayutthaya vào thế kỷ 16 và trở thành một người lính trong quân đội của vua Naresuan. Sau trận chiến với Miến Điện, Ayutthaya vẫn phải tiếp tục chiến đấu khi một nhóm người bí ẩn tổ chức khủng bố và cướp bóc. Yamada điều tra và thấy rằng nhóm người này thực sự là những samurai Nhật Bản. Anh làm thế nào để ngăn chặn những người đồng hương của mình...</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Seigi Ozeki","avatar":""},{"name":"Sorapong Chatree","avatar":""},{"name":"Winai Kraibutr","avatar":""},{"name":"Buakaw Banchamek","avatar":""},{"name":"Thammaros Jaichuen","avatar":""},{"name":"Thanawut Ketsaro","avatar":""},{"name":"Mukuda Hann","avatar":""},{"name":"Yonthida Nakong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
