INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-robin-hood', 'Huyền Thoại Robin Hood', 'Robin Hood', 'https://phimimg.com/upload/vod/20231115-1/3403b96575ea0c804e2d6300cc1e204b.jpg', 'https://phimimg.com/upload/vod/20231115-1/ed3e84e29c6ba0e316763172ed4c0dd9.jpg', '<p>Bộ phim kể lại cuộc đời của anh chàng Robin Longstride (Russell Crowe) trước khi trở thành huyền thoại Robin Hood. Xuất thân là một xạ thủ bắn cung cừ khôi, Robin cùng những người bạn của mình đã có khoảng thời gian chiến đấu chống lại người Pháp trong quân đội của nhà vua Richard I. Khi nhà vua hy sinh trên chiến trận, Robin trở về và mạo danh là tướng Loxley để tránh tội chết. Lúc này thái tử John - một kẻ ham chơi, bất tài và độc ác đã lên ngôi vua và đưa ra hàng loạt những chính sách khắc nghiệt. Robin tới Nottingham để thực hiện nốt lời hứa với tướng Loxley đã khuất và tại đây, anh đã gặp gỡ với góa phụ xinh đẹp Marion (Cate Blanchett).</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Eileen Atkins","avatar":""},{"name":"Mark Addy","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Scott Grimes","avatar":""},{"name":"Alan Doyle","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Jonathan Zaccaï","avatar":""},{"name":"Robert Pugh","avatar":""},{"name":"Gerard McSor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
