INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scott-pilgrim-chong-lai-ca-the-gioi', 'Scott Pilgrim Chống Lại Cả Thế Giới', 'Scott Pilgrim vs. the World', 'https://phimimg.com/upload/vod/20231113-1/dc2e0c58008da21c17cfcc41b08403f8.jpg', 'https://phimimg.com/upload/vod/20231113-1/2c9f0a07b73b95ab2beaaaa4923cd289.jpg', '<p>Bộ phim là câu chuyện về tay guitar bass 23 tuổi tên là Scott Pilmgrim của ban nhạc Sex Bob-omb. Scott vừa gặp được người con gái trong mộng của mình - Ramona Flowers. Quyết tâm có được trái tim của Ramona, Scott phát hiện ra anh phải chiến đấu với 7 “đối thủ” – vốn là người yêu cũ của cô bạn lạ lùng này. Những kẻ đó cũng đang nung nấu ý định giết Scott. Scott Pilgrim vs. the World được chuyển thể từ tập truyện tranh Scott Pilgrim của tác giả Bryan Lee O’ Malley. Với sự góp mặt của hai diễn viên tuổi teen Michael Cera và Mary Elizabeth Winstead chắc chắn sẽ không khỏi bất ngờ với cuộc chiến vì người đẹp của Scott.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Cera","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Ellen Wong","avatar":""},{"name":"Kieran Culkin","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Mark Webber","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"Satya Bhabha","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Brandon Routh","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Keita Saito","avatar":""},{"name":"Shota Saito","avatar":""},{"name":"Will","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
