INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-ve-xu-gahoole', 'Hộ Vệ Xứ Ga''Hoole', 'Legend of the Guardians: The Owls of Ga''Hoole', 'https://phimimg.com/upload/vod/20231113-1/58fe6c6c606e42717e19265674d586a5.jpg', 'https://phimimg.com/upload/vod/20231113-1/4077dcd92af6ba6a6b9c4eab31fcd57e.jpg', '<p>Legend of the Guardians bao gồm ba tập đầu trong seri truyện Guardians of Ga&quot;Hoole. Chúng ta sẽ được theo chân Soren, một chú cú đầy mơ mộng và lúc nào cũng bị những câu chuyện cổ của bố mình về Chiến Binh Hộ Vệ Ga’Hoole ám ảnh đến tơi tả. Trái ngược với sự hân hoan của Soren là lòng ghen ghét, ham muốn độc chiếm tình cảm từ gia đình của Kludd, anh trai Soren. Trong một lần ra tay hãm hại em mình, Kludd đã vô tình khiến cả hai rơi vào hang ổ của một bọn cú hung dữ đang âm mưu thống trị thế giới. Bằng trái tim dũng cảm và niềm tin với chính nghĩa, Soren đã liều mình dẫn theo bạn bè, băng qua nhiều vùng đất nguy hiểm, để tìm đến Cây Thần. Theo truyền thuyết hàng trăm năm qua, đó là thành lũy của Chiến Binh Hộ Vệ Ga’Hoole và chỉ có họ mới có thể giải cứu quê hương của Soren.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2010, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jim Sturgess","avatar":""},{"name":"Ryan Kwanten","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Emily Barclay","avatar":""},{"name":"Abbie Cornish","avatar":""},{"name":"Anthony LaPaglia","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Deborra-Lee Furness","avatar":""},{"name":"Adrienne DeFaria","avatar":""},{"name":"Sacha Ho","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324475);
