INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-joneses', 'The Joneses', 'The Joneses', 'https://phimimg.com/upload/vod/20231114-1/7ed923eb29c4cb4e8713573cb9239acb.jpg', 'https://phimimg.com/upload/vod/20231114-1/2e7420ea8757aafff1716c33bf72a1c9.jpg', '<p>Một gia đình dường như hoàn hảo chuyển đến sống ở một khu ngoại ô, nhưng khi biết được lý do tại sao họ lại sống ở đó, họ không hoàn toàn trong sạch với những người hàng xóm của mình.</p>', 'Full', 1, 'single', 'completed', 22, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Duchovny","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Benjamin Hollingsworth","avatar":""},{"name":"Lauren Hutton","avatar":""},{"name":"Catherine Dyer","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Glenne Headly","avatar":""},{"name":"Ashley LeConte Campbell","avatar":""},{"name":"Christine Evangelista","avatar":""},{"name":"Chris Williams","avatar":""},{"name":"Tiffany Morgan","avatar":""},{"name":"Robert Pralgo","avatar":""},{"name":"Joe Narciso","avatar":""},{"name":"Ric Reitz","avatar":""},{"name":"L. Warren Youn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
