INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-hai', 'Thượng Hải', 'Shanghai', 'https://phimimg.com/upload/vod/20231115-1/efc4383826f33b3351cc89fbe186a6df.jpg', 'https://phimimg.com/upload/vod/20231115-1/13460f109c0164ed276b0b955dfaa99e.jpg', '<p>Sau khi trở lại Thượng Hải, một người đàn ông Mỹ đã bị dính líu đến vụ tham nhũng và phát hiện ra rằng bạn thân của mình đã bị giết sau khi Nhật Bản tấn công Thượng Hải trước trận Trân Châu Cảng và chiếm đóng thành phố trong bốn tháng. Trong quá trình điều tra, anh ta đã phát hiện ra một bí mật vĩ đại hơn nhiều so với đối với chính phủ của Mỹ đang được che giấu, đồng thời, anh ta đã phát đi một tình yêu mới nảy nở.</p>', 'Full', 1, 'single', 'completed', 23, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"John Cusack","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"David Morse","avatar":""},{"name":"Franka Potente","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Andy On","avatar":""},{"name":"Race Wong","avatar":""},{"name":"Rosanne Wong","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"Hon Ping Tang","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Christopher Buchholz","avatar":""},{"name":"Ronan Vibert","avatar":""},{"name":"Nicholas Rowe","avatar":""},{"name":"Gemma C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324475);
