INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-hai', 'Thượng Hải', 'Shanghai', 'thượng hải shanghai john cusack gong li chow yun-fat jeffrey dean morgan ken watanabe david morse franka potente hugh bonneville andy on race wong rosanne wong michael culkin hon ping tang benedict wong christopher buchholz ronan vibert nicholas rowe gemma c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-dep', 'Cuộc Đời Đẹp', 'Biutiful', 'https://phimimg.com/upload/vod/20231115-1/8a0c8e8179745140101feedb3492c768.jpg', 'https://phimimg.com/upload/vod/20231115-1/1711291cdd8fa7ed3fdfe8dce222e75d.jpg', '<p>Bộ phim nói về những ngày tháng cuối cùng trong cuộc đời của Uxbal (Javier Bardem), một người đàn ông bình thường như bao người đàn ông khác tại thành phố Barcelona. Cuộc sống của Uxbal không hề “tươi đẹp”, như tựa phim Biutiful. Công việc dĩ nhiên không dễ dàng, đời sống cá nhân của Uxbal cũng đầy khó khăn. Người vợ Marambra (Maricel Álvarez) mắc chứng rối loạn lưỡng cực, đòi trở lại sau khi li thân. Hai đứa con nhỏ thiếu vắng sự quan tâm, không người chăm sóc. Một người bạn thân của Uxbal bị cảnh sát bắt, gã buộc phải lo lắng cho vợ con mình nên đã phản bội... Uxbal sống trong một mớ quan hệ hỗn loạn. Như thể chưa đủ, số phận còn giáng cho Uxbal một cú chí mạng: anh bị ung thư, chỉ còn sống được vài tháng... Mặc dù phải làm việc phạm pháp để mưu sinh nhưng Uxbal không phải là người xấu. Anh luôn tìm mọi cách để làm điều tốt, luôn giúp đỡ bạn bè, người thân, nhưng cuộc sống vốn khắc nghiệt, khó khăn đến tàn nhẫn...</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Javier Bardem","avatar":""},{"name":"Maricel Álvarez","avatar":""},{"name":"Hanaa Bouchaib","avatar":""},{"name":"Guillermo Estrella","avatar":""},{"name":"Eduard Fernández","avatar":""},{"name":"Cheikh Ndiaye","avatar":""},{"name":"Diaryatou Daff","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Luo Jin","avatar":""},{"name":"George Chibuikwem Chukwuma","avatar":""},{"name":"Lang Sofia Lin","avatar":""},{"name":"Yodian Yang","avatar":""},{"name":"Tuo Lin","avatar":""},{"name":"Xueheng Chen","avatar":""},{"name":"Xiaoyan Zhang","avatar":""},{"name":"Ailie Ye","avatar":""},{"name":"Xianlin B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
