INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uncle-boonmee-who-can-recall-his-past-lives', 'Uncle Boonmee Who Can Recall His Past Lives', 'Uncle Boonmee Who Can Recall His Past Lives', 'https://phimimg.com/upload/vod/20231115-1/ecd444401ba9c0c47b01b32a9271d3e8.jpg', 'https://phimimg.com/upload/vod/20231115-1/e12a62788aed5e11764ea2644e6a6cb3.jpg', '<p>Bị suy thận cấp tính, Boonmee đã chọn trải qua những ngày cuối đời bên những người thân yêu của mình ở vùng quê. Ngạc nhiên thay, hồn ma của người vợ đã khuất xuất hiện để chăm sóc cho anh ta, và đứa con trai thất lạc từ lâu của anh ta trở về nhà trong hình dạng không phải con người. Suy ngẫm về lý do căn bệnh của mình, Boonmee cùng gia đình đi xuyên rừng rậm đến một hang động bí ẩn trên đỉnh đồi—nơi sinh ra kiếp sống đầu tiên của anh.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Thanapat Saisaymar","avatar":""},{"name":"Jenjira Pongpas","avatar":""},{"name":"Sakda Kaewbuadee","avatar":""},{"name":"Natthakarn Aphaiwonk","avatar":""},{"name":"Geerasak Kulhong","avatar":""},{"name":"Wallapa Mongkolprasert","avatar":""},{"name":"Kanokporn Tongaram","avatar":""},{"name":"Samud Kugasang","avatar":""},{"name":"Sumit Suebsee","avatar":""},{"name":"Mathieu Ly","avatar":""},{"name":"Vien Pimdee","avatar":""},{"name":"Akachai Aodvieng","avatar":""},{"name":"Prakasit Padsena","avatar":""},{"name":"Nikom Kammach","avatar":""},{"name":"Chophaka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324475);
