INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-tu-luan-hoi-liveaction', 'Sinh Tử Luân Hồi (Live-Action)', 'Gantz', 'https://phimimg.com/upload/vod/20231115-1/0bffc3a831e4d0fc0cb0a34449d90061.jpg', 'https://phimimg.com/upload/vod/20231115-1/8fbde2419946b12276f9859d275a900b.jpg', '<p>Gantz xoay quanh 2 chàng trai trẻ do Kei Kurono và Masaru Kato. Hai người đã chết trong một tai nạn nhưng lại được một vật thể bí ẩn được gọi là Gantz cứu sống. Sinh mạng của 2 người đã kết thúc và thuộc về Gantz, cùng một số người cùng hoàn cảnh họ được trang bị sức mạnh siêu nhiên, vũ khí hiện đại để tiêu diệt những người ngoài hành tinh trong những lốt bọc khác nhau. Rất nhiều người hy sinh trong các nhiệm vụ. Nếu sống sót họ được quay về cuộc sống bình thường cho đến khi Gantz triệu tập. Cách duy nhất để thoát ra khỏi trò chơi sinh tử này là tích đủ 100 điểm mà vẫn còn sống.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazunari Ninomiya","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Natsuna Watanabe","avatar":""},{"name":"Ainosuke Shibata","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Chieko Ichikawa","avatar":""},{"name":"Donpei Tsuchihira","avatar":""},{"name":"Hidekazu Nagae","avatar":""},{"name":"Kazuhide Kobayashi","avatar":""},{"name":"Kazuyuki Asano","avatar":""},{"name":"Kensuke Chisaka","avatar":""},{"name":"Matsuri Hashimoto","avatar":""},{"name":"Merii","avatar":""},{"name":"Motoki","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678