INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('casino-jack-and-the-united-states-of-money', 'Casino Jack and the United States of Money', 'Casino Jack and the United States of Money', 'null', 'https://phimimg.com/upload/vod/20231115-1/2c479b69e3dc78e0e4a8477ff665a0d5.jpg', '<p>Một cuộc điều tra thăm dò về những lời dối trá, tham lam và tham nhũng xung quanh siêu vận động hành lang Jack Abramoff của D.C. và những người bạn thân của ông ta.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Abramoff","avatar":""},{"name":"Tom DeLay","avatar":""},{"name":"Bob Ney","avatar":""},{"name":"Ralph Reed","avatar":""},{"name":"Neil Volz","avatar":""},{"name":"William Branner","avatar":""},{"name":"Donn Dunlop","avatar":""},{"name":"Hal Kreitman","avatar":""},{"name":"Kelly Brian Kuhn","avatar":""},{"name":"Paolo Mugnaini","avatar":""},{"name":"Kevin Henderson","avatar":""},{"name":"Melanie Sloan","avatar":""},{"name":"Nina Easton","avatar":""},{"name":"Dana Rohrabacher","avatar":""},{"name":"Thomas Frank","avatar":""},{"name":"J. Michael Waller","avatar":""},{"name":"Grover Norquist","avatar":""},{"name":"Jonas","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324475);
