INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dien-hy-su-2010', 'Hoa Điền Hỷ Sự', 'All''s Well End''s Well', 'https://phimimg.com/upload/vod/20231012-1/7be0268041417912cf081cb1541f792d.jpg', 'https://phimimg.com/upload/vod/20231012-1/ecf71e3a0eb7f10564598f890286e409.jpg', '<p>Công chúa Trân trên đường trở về đất nước của mình, cứu vớt được một cô gái tên Ying, cô gái đã tự vẫn để phản đối cuộc hôn nhân do gia đình sắp xếp.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Pan Yueming","avatar":""},{"name":"Lynn Hung","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""},{"name":"Lam Suet","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
