INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gian-diep-vu-em', 'Gián Điệp Vú Em', 'The Spy Next Door', 'https://phimimg.com/upload/vod/20231113-1/c559677efccf5801bbd50381a95dfa75.jpg', 'https://phimimg.com/upload/vod/20231113-1/4bfe5af182c9c6b1d3b94a1754004464.jpg', '<p>Bob Ho là một siêu gián điệp của CIA. Một ngày, anh quyết định nghỉ việc “về vườn” và mong muốn lập gia đình với cô hàng xóm xinh đẹp Gillian. Tuy nhiên, để kết hôn với Gillian, Bob phải vượt qua thử thách do chính cô đặt ra là phải chiếm được cảm tình của ba đứa con riêng của cô là: Farren, Ian, Nora...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Amber Valletta","avatar":""},{"name":"Madeline Carroll","avatar":""},{"name":"Alina Foley","avatar":""},{"name":"Magnús Scheving","avatar":""},{"name":"Billy Ray Cyrus","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Katherine Boecher","avatar":""},{"name":"Will Shadley","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Mia Stallard","avatar":""},{"name":"Maverick McWilliams","avatar":""},{"name":"Quinn Mason","avatar":""},{"name":"Margaret Murphy","avatar":""},{"name":"Esodie Geiger","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Arron Shiv","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324475);
