INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-binh-tieu-tuong', 'Đại Binh Tiểu Tướng', 'Little Big Soldier', 'https://phimimg.com/upload/vod/20231113-1/240e7fb2966128a169805d2c43c9738d.jpg', 'https://phimimg.com/upload/vod/20231113-1/4da3fb00d1b1f18b2f8801ba54e5fa38.jpg', '<p>Đó là thời kỳ đen tối nhất trong lịch sử Trung Quốc, khi những con người đứng đầu đất nước phát động chiến tranh chỉ để thỏa mãn lòng tham không đáy của bọn họ. Máu chảy thành sông, thây chất thành núi, hàng triệu người chết bởi những trận chiến vô nghĩa đó. Và những người còn sống chỉ có hai lựa chọn duy nhất - giết hoặc bị giết...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Leehom Wang","avatar":""},{"name":"Steve Yoo","avatar":""},{"name":"Lin Peng","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Jin Song","avatar":""},{"name":"Xu Dongmei","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Ben Niu","avatar":""},{"name":"Zhao Yao-Dong","avatar":""},{"name":"Ji Tao","avatar":""},{"name":"Wang Xu","avatar":""},{"name":"Jack Tu","avatar":""},{"name":"Zha Ka","avatar":""},{"name":"Jerry Liau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324475);
