INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ly-tieu-long', 'Huyền Thoại Lý Tiểu Long', 'Bruce Lee, My Brother', 'https://phimimg.com/upload/vod/20231112-1/2597094b9c239b00a27ae6b94007ecdb.jpg', 'https://phimimg.com/upload/vod/20231112-1/9239e125e69919aefc740d576fe8d7bd.jpg', '<p>Bruce Lee, My Brother là một bộ phim tiểu sử hành động kịch tính về huyền thoại võ thuật cùng tên được kể bởi em trai của ông, Robert Lee. Phim xoay quanh cuộc đời của Lý Tiểu Long khi còn là một thanh niên nổi loạn ở Hồng Kông trước khi anh lên đường sang Mỹ và chinh phục thế giới ở tuổi 18 chỉ với 100 đô la Mỹ trong túi.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aarif Rahman","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Jennifer Tse","avatar":""},{"name":"Zhang Yishan","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Gong Mi","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Ou-Yang Ching","avatar":""},{"name":"Tan Han-Jin","avatar":""},{"name":"Angela Gong Mi","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Lee Heung-Kam","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Johnson Yuen Tak-Cheung","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
