INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-ly-tieu-long', 'Huyền Thoại Lý Tiểu Long', 'Bruce Lee, My Brother', 'huyền thoại lý tiểu long bruce lee, my brother aarif rahman tony leung ka-fai christy chung lai-tai jennifer tse zhang yishan michelle ye gong mi alex man song jia ou-yang ching tan han-jin angela gong mi wilfred lau lee heung-kam cheung tat-ming eddie cheung johnson yuen tak-cheung a ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dau-3-chuoc-toi', 'Quyết Đấu 3: Chuộc Tội', 'Undisputed III: Redemption', 'https://phimimg.com/upload/vod/20231111-1/18beb521631cd4b2eeabca7a60004648.jpg', 'https://phimimg.com/upload/vod/20231111-1/1236b9be95f8f7dada6f99c2573c568a.jpg', '<p>Boyka, 1 tù nhân người Nga, đang chịu đựng chấn thương đầu gối nghiêm trọng sau khi kết thúc phần 2 của Undisputed. Sau giải đấu đó, bây giờ anh chỉ quan tâm và giỏi nhất ở việc lau rửa toalet. Nhưng một cơ hội đã đến với anh khi một giải đấu quốc tế giữa các tù nhân trên thế giới diễn ra, đó chính là giải đấu Quyền Vương. Giải đấu bao gồm những võ sĩ tù nhân giỏi nhất thế giới quy tụ với giải thưởng chính là sự tự do cho người chiến thắng. Chính vì thế, Boyka đã đánh thức lòng kiêu hãnh của chính bản thân để đổi lấy sự tự do. Nhưng cuộc đấu khônghề dễ dàng đối với Boyka...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Mykel Shannon Jenkins","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Hristo Shopov","avatar":""},{"name":"Marko Zaror","avatar":""},{"name":"Michael Baral","avatar":""},{"name":"Ilram Choi","avatar":""},{"name":"Robert Costanzo","avatar":""},{"name":"Lateef Crowder","avatar":""},{"name":"Esteban Cueto","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"Valentin Ganev","avatar":""},{"name":"Velislav Pavlov","avatar":""},{"name":"Kiril Efremov","avatar":""},{"name":"Trayan Milenov-Troy","avatar":""},{"name":"Dimiter Doichin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
