INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quyet-dau-3-chuoc-toi', 'Quyết Đấu 3: Chuộc Tội', 'Undisputed III: Redemption', 'quyết đấu 3: chuộc tội undisputed iii: redemption scott adkins mykel shannon jenkins mark ivanir hristo shopov marko zaror michael baral ilram choi robert costanzo lateef crowder esteban cueto vernon dobtcheff valentin ganev velislav pavlov kiril efremov trayan milenov-troy dimiter doichin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-y-ve', 'Cẩm Y Vệ', '14 Blades', 'https://phimimg.com/upload/vod/20231113-1/84de6e6b7eadfed898abd80098eeb668.jpg', 'https://phimimg.com/upload/vod/20231113-1/6e3eabe631d71c51dcb9da875ec68870.jpg', '<p>Trong thời đại nhà Minh, hoàng đế Trung Hoa sở hữu một vũ khí vĩ đại và nguy hiểm hơn bất cứ thứ gì khác - đó là đội Cẩm Y Vệ - một đội thị vệ có thanh thế. Đội Cẩm Y Vệ này thu gom và bí mật huấn luyện những đứa trẻ mồ côi không nơi nương tựa ngoài đường. Chúng được dạy dỗ từ nhỏ và trở thành những tay sát thủ sử dụng thông thạo 14 lưỡi dao - 8 lưỡi dùng cho việc tra tấn kẻ thù, 5 lưỡi dùng để giết và lưỡi dao cuối cùng dùng để tự sát khi nhiệm vụ không thành. Đội Cẩm Y Vệ không phải tuân theo pháp luật, có quyền giết người mà không cần hỏi trước, và hiến dâng cả cuộc đời của mình để phục vụ hoàng đế.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Wu Zun","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Kate Tsui","avatar":""},{"name":"Qi Yuwu","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Chen Kuan-tai","avatar":""},{"name":"Chen Zhihui","avatar":""},{"name":"Xu Xiangdong","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Jin Laiqun","avatar":""},{"name":"Liu Zhuoling","avatar":""},{"name":"Zhang Yujiao","avatar":""},{"name":"Ding Wen-Bin","avatar":""},{"name":"Qiu Bo","avatar":""},{"name":"Bian Yang","avatar":""},{"name":"Han Lei","avatar":""},{"name":"Huang Jinlong","avatar":""},{"name":"Wang Min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
