INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-cua-mot-thieu-nien-mat-tri-nho', 'Hồi ức của một thiếu niên mất trí nhớ', 'Memoirs of a Teenage Amnesiac', 'https://phimimg.com/upload/vod/20231123-1/7e1e4e997696aa0bd885a3fd4a13c7ca.jpg', 'https://phimimg.com/upload/vod/20231123-1/c714839230a3f19baaeafddf4ef0afeb.jpg', '<p>Một nữ sinh trung học xoay sở với cuộc sống bị lãng quên và tình yêu mới sau khi cú ngã nghiêm trọng khiến cô quên mất bốn năm qua.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Maki Horikita","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Yuya Tegoshi","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Emma Roberts","avatar":""},{"name":"Misa Shimizu","avatar":""},{"name":"Atsuro Watabe","avatar":""},{"name":"Reika Kirishima","avatar":""},{"name":"Mirei Kiritani","avatar":""},{"name":"Kate Gorney","avatar":""},{"name":"Kylee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
