INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-uc-cua-mot-thieu-nien-mat-tri-nho', 'Hồi ức của một thiếu niên mất trí nhớ', 'Memoirs of a Teenage Amnesiac', 'hồi ức của một thiếu niên mất trí nhớ memoirs of a teenage amnesiac maki horikita kenichi matsuyama yuya tegoshi anton yelchin emma roberts misa shimizu atsuro watabe reika kirishima mirei kiritani kate gorney kylee ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-am-son', 'Quan Âm Sơn', 'Buddha Mountain', 'https://phimimg.com/upload/vod/20231111-1/558b8500581dff926e165c350b23ceff.jpg', 'https://phimimg.com/upload/vod/20231111-1/7f1ee511a71beee3ee53d1c35401a20b.jpg', '<p>Quan Âm Sơn thông qua cuộc sống phản nghịch của một đôi nam nữ thanh niên lãng du, tường thuật lại một câu chuyện về tình yêu, tuổi trẻ và sự trưởng thành. Trong Quan Âm Sơn Phạm Băng Băng và Trần Bách Lâm là một đôi nam nữ thanh niên có cá tính nổi bật, cả hai vì chán ghét cuộc sống trong gia đình và kỳ thi tuyển sinh đại học mà phiêu bạt đến thành phố để mưu sinh. Trương Ngải Gia đảm nhiệm vai diễn bà chủ nhà tuyệt vọng, mất chồng, mất con và mất cả mục tiêu cuộc sống. Đôi nam nữ thanh niên và “bà chủ tuyệt vọng” cùng sinh hoạt trong một ngôi nhà, ba người không ngừng xung đột và dần dần lộ ra bí mật cuộc sống của mình...</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sylvia Chang","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Fei Long","avatar":""},{"name":"Jin Jing","avatar":""},{"name":"Fang Li","avatar":""},{"name":"Liu Jie","avatar":""},{"name":"Bao Zhenjiang","avatar":""},{"name":"Shen Wen","avatar":""},{"name":"Tang Maru","avatar":""},{"name":"Yuan Ze","avatar":""},{"name":"Chen Yu","avatar":""},{"name":"Wang Guo-Yu","avatar":""},{"name":"Shi Min-Fang","avatar":""},{"name":"Dany Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
