INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-can-cong-ly', 'Cán Cân Công Lý', 'Brooklyn''s Finest', 'https://phimimg.com/upload/vod/20231111-1/46ad40d5036fe72ae7e423b42a05516e.jpg', 'https://phimimg.com/upload/vod/20231111-1/73b609cfbbf6ee73d75a8e0664338335.jpg', '<p>Bộ phim Brooklyn Finest đưa ra bài học sâu sắc này cho ta, với 3 nhân vật, 3 cảnh đời riêng biệt chìm trong bi kịch, và mỗi nhân vật biểu tượng cho 1 cái cân, để cân bằng giữa điều thiện vá điều ác, điều đúng và điều sai, chính khán giả là thẩm phán, còn rạp chiếu phim là tòa án. Kịch bản phim thành công ở chỗ suốt bộ phim là những chứng cứ trước tòa, khán giả đóng vai trò quan tòa cho đến gần cuối phim, đạo diễn thi hành bản án, và kì diệu là bản án thi hành hoàn toàn thỏa mãn sự mong đợi của hơn 200 quan tòa ngồi trong rạp.Cán cân thứ nhất là Edie, Richard Gere thủ vai, một cảnh sát tuần tra già chỉ còn 7 ngày nữa về hưu, sống cầu an đến mức vô trách nhiệm, tội lỗi của ông ta là vô cảm bàng quang trước cái ác tại thành ...</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Wesley Snipes","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Ellen Barkin","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Shannon Kane","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Armando Riesco","avatar":""},{"name":"Wade Allain-Marcus","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
