INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-cho-nhung-sieu-anh-hung', 'Trông Chờ Những Siêu Anh Hùng', 'Waiting for "Superman"', 'https://phimimg.com/upload/vod/20231111-1/8eb613bb5de1c0765a1dfa0fbf9206b9.jpg', 'https://phimimg.com/upload/vod/20231111-1/07550064605c954df3eac5007e36fb5e.jpg', '<p>Waiting for &quot;Superman&quot;là một bộ phim tài liệu năm 2010 của đạo diễn Davis Guggenheim và nhà sản xuất phim Lesley Chilcott. Bộ phim phân tích sự thất bại của giáo dục công lập Mỹ bằng cách bắt trước một số học sinh thông qua hệ thống giáo dục. Bộ phim nhận được giải thưởng khán giả bình chọn dành cho phim tài liệu hay nhất 2010 tại Sundance Film Festival.</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charles Adams","avatar":""},{"name":"Jonathan Alter","avatar":""},{"name":"Jonathan Alter","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324475);
