INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-khan', 'Tôi Là Khan', 'My Name Is Khan', 'https://phimimg.com/upload/vod/20231111-1/2b00cddad4ba5c7488528009a29c56dd.jpg', 'https://phimimg.com/upload/vod/20231111-1/6d96a931352cc8fb25955b4ffa4feabd.jpg', '<p>Phim xoay quanh ảnh hưởng của vụ tấn công ngày 11/9 lên một người đàn ông người Hồi giáo Ấn Độ sống tại San Francisco đã làm một chuyến hành trình xuyên nước Mỹ để đến gặp Tổng thống Barack Obama chỉ để nói với ông &quot;Tôi tên Khan và tôi không phải khủng bố&quot;.</p>', 'Full', 1, 'single', 'completed', 23, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Kajol","avatar":""},{"name":"Jimmy Shergill","avatar":""},{"name":"Sonya Jehan","avatar":""},{"name":"Arjan Aujla","avatar":""},{"name":"Zarina Wahab","avatar":""},{"name":"Adarsh Gourav","avatar":""},{"name":"Tanay Chheda","avatar":""},{"name":"Yuvan Makar","avatar":""},{"name":"Christopher B. Duncan","avatar":""},{"name":"Katie A. Keane","avatar":""},{"name":"Dominic Renda","avatar":""},{"name":"Kenton Duty","avatar":""},{"name":"Michael William Arnold","avatar":""},{"name":"Sheetal Menon","avatar":""},{"name":"Arjun Mathur","avatar":""},{"name":"Arif Zakaria","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
