INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-hay-khong-yeu', 'Yêu Hay Không Yêu', 'Yes or No', 'https://phimimg.com/upload/vod/20231111-1/188e684f7df2c47c14fbd378d8affa34.jpg', 'https://phimimg.com/upload/vod/20231111-1/10290f4e660d6ca5492d1978e9e39db4.jpg', '<p>Yes or No là một bộ phim về đề tài đồng tính nữ của Thái Lan. Câu chuyện về Pai, một nữ sinh viên đại học nhưng lại có thái độ tiêu cực đối với những cô nàng tomboys. Và rồi cô phát hiện ra rằng người bạn cùng phòng mới của mình là Kim, là con gái nhưng lại thích ăn mặc như đàn ông và thích phụ nữ. Việc mất niềm tin ban đầu đã dần dần thay đổi thành một thứ tình cảm khác khi Kim bắt đầu theo đuổi Pai...</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sushar Manaying","avatar":""},{"name":"Suppanad Jittaleela","avatar":""},{"name":"Arisara Thongborisut","avatar":""},{"name":"Soranut Yupanun","avatar":""},{"name":"Nattharinphon Phrommin","avatar":""},{"name":"Maneerat Wongsjirasakdi","avatar":""},{"name":"Puttipong Promsaka Na Sakolnakorn","avatar":""},{"name":"Chanwut Promsaka Na Sakolnakorn","avatar":""},{"name":"Wasin Pokpong","avatar":""},{"name":"Jirawadee Issarangkul Na Ayuttaya","avatar":""},{"name":"Thanapat So","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
