INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-ranh-gioi', 'Vượt Qua Ranh Giới', 'Across The Line: The Exodus of Charlie Wright', 'https://phimimg.com/upload/vod/20231111-1/d9072517db1748da93ce89b1909fa883.jpg', 'https://phimimg.com/upload/vod/20231111-1/6bb6a00fd08850d511dd6880761139a8.jpg', '<p>Câu chuyện kể về cuộc chạy trốn của một nhà tài phiện từ Los Angeles và được phát hiện ẩn nấp ở Tijuana, anh ta cùng hàng tỷ đô của mình nhanh chóng trở thành mục tiêu tìm kiếm và săn lùng của một ông trùm ma túy Mexico khét tiếng, những tên cướp lão luyện Nga và cả những đặc vụ FBI, cuộc truy tìm trở nên vô cung gây cấn khi cả 3 thế lực đối đầu nhau dành một con mồi béo bở.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aidan Quinn","avatar":""},{"name":"Andy García","avatar":""},{"name":"Mario Van Peebles","avatar":""},{"name":"Danny Pino","avatar":""},{"name":"Claudia Ferri","avatar":""},{"name":"Luke Goss","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Elya Baskin","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"Melissa Baldridge","avatar":""},{"name":"Jordan Belfi","avatar":""},{"name":"Geoffrey Ross","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324475);
