INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-gian-bi-an', 'Không Gian Bí Ẩn', 'IMAX Hubble', 'https://phimimg.com/upload/vod/20231110-1/4b0bd5b5d694f5457030414239f674ef.jpg', 'https://phimimg.com/upload/vod/20231110-1/5c2451eeb2609abfb6dcd4146bcf3d52.jpg', '<p>Chuyến du hành xuyên Thái Dương Hệ mở ra trước mắt chúng ta 2.000 thiên hà và một lỗ đen khổng lồ. Dõi theo lời dẫn truyện của tài tử Leonardo DiCaprio, chúng ta còn được chứng kiến cận cảnh hoạt động của các phi hành gia trong nỗ lực không mệt mỏi nhằm sửa chữa kính viễn vọng không gian Hubble, một nhiệm vụ cực kỳ khó khăn và quan trọng trong lịch sử NASA.</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Leonardo DiCaprio","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324475);
