INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troll-hunter', 'Troll Hunter', 'Troll Hunter', 'https://phimimg.com/upload/vod/20231110-1/f2039a3ea3488d82ceddedc222011977.jpg', 'https://phimimg.com/upload/vod/20231110-1/8fd7dae3be967a9a60713acaeba073aa.jpg', '<p>Một nhóm sinh viên điều tra hàng loạt vụ giết gấu bí ẩn, nhưng biết được rằng còn nhiều điều nguy hiểm hơn đang diễn ra. Họ bắt đầu theo dõi một thợ săn bí ẩn, biết rằng anh ta thực sự là một thợ săn troll.</p>', 'Full', 1, 'single', 'completed', 24, 2010, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Otto Jespersen","avatar":""},{"name":"Glenn Erland Tosterud","avatar":""},{"name":"Johanna Mørck","avatar":""},{"name":"Tomas Alf Larsen","avatar":""},{"name":"Hans Morten Hansen","avatar":""},{"name":"Knut Nærum","avatar":""},{"name":"Robert Stoltenberg","avatar":""},{"name":"Urmila Berg-Domaas","avatar":""},{"name":"Eirik Bech","avatar":""},{"name":"Inge Erik Henjesand","avatar":""},{"name":"TomTom Jorgensen","avatar":""},{"name":"Benedicte Aubert Ringnes","avatar":""},{"name":"Magne Skjævesland","avatar":""},{"name":"Torunn Lødemel","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
