INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-nguoi-my', 'Quý Ông Người Mỹ', 'The American', 'https://phimimg.com/upload/vod/20231110-1/33ea7a5fbdcd8873eaa8d562b7736b33.jpg', 'https://phimimg.com/upload/vod/20231110-1/663e01bc1319ce98446af216ad5b0bd1.jpg', '<p>Phim xoay quanh câu chuyện về 1 tay sát thủ xuất sắc Jack (George Clooney đóng) có cuộc sống luôn luôn dịch chuyển và cô đơn. Anh phải sống ẩn dật tại ngoại ô nước Ý chuẩn bị cho một nhiệm vụ khác sau khi tình hình công việc ở Thuỵ Điển xấu đi. Jack tự hứa rằng sẽ &quot;rửa tay gác kiếm&quot; sau nhiệm vụ cuối cùng này. Nhưng nhiều chuyện bất ngờ xảy đến với Jack khi anh kết bạn với linh mục địa phương - Benedetto và đem lòng cảm mến cô gái xinh đẹp Clara.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"George Clooney","avatar":""},{"name":"Violante Placido","avatar":""},{"name":"Thekla Reuten","avatar":""},{"name":"Paolo Bonacelli","avatar":""},{"name":"Johan Leysen","avatar":""},{"name":"Irina Björklund","avatar":""},{"name":"Lars Hjelm","avatar":""},{"name":"Björn Granath","avatar":""},{"name":"Giorgio Gobbi","avatar":""},{"name":"Silvana Bosi","avatar":""},{"name":"Guido Palliggiano","avatar":""},{"name":"Samuli Vauramo","avatar":""},{"name":"Antonio Rampino","avatar":""},{"name":"Filippo Timi","avatar":""},{"name":"Ilaria Cramerotti","avatar":""},{"name":"Angelica Novak","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
