INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ay-la-chuyen-nho-2', 'Chuyện Ấy Là Chuyện Nhỏ 2', 'Sex and the City 2', 'https://phimimg.com/upload/vod/20231109-1/f8500f81641d15355b537383463af20b.jpg', 'https://phimimg.com/upload/vod/20231109-1/52b9f9b7e58619fd017606a04248a169.jpg', '<p>Carrie, Charlotte và Miranda hiện đều đã kết hôn, nhưng họ vẫn muốn vui đùa một chút dưới ánh mặt trời. Khi Samantha có cơ hội đến thăm một trong những điểm nghỉ dưỡng xa hoa nhất hành tinh và đề nghị đưa tất cả bọn họ đi cùng, họ phỏng đoán rằng một kỳ nghỉ dưỡng dành riêng cho phụ nữ có thể là lý do hoàn hảo để trốn tránh trách nhiệm và nhớ lại cuộc sống trước đây của họ như thế nào trước khi họ quyết định ổn định cuộc sống.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Jessica Parker","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Chris Noth","avatar":""},{"name":"David Eigenberg","avatar":""},{"name":"Evan Handler","avatar":""},{"name":"Liza Minnelli","avatar":""},{"name":"Willie Garson","avatar":""},{"name":"Mario Cantone","avatar":""},{"name":"Art Malik","avatar":""},{"name":"Raza Jaffrey","avatar":""},{"name":"Alexandra Fong","avatar":""},{"name":"Parker Fong","avatar":""},{"name":"Noah Mills","avatar":""},{"name":"Billy Stritch","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Jason Lew","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
