INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-ep-dau-tien', 'Sức Ép Đầu Tiên', 'Mardock Scramble: The First Compression', 'https://phimimg.com/upload/vod/20231110-1/565bae5e86980ce3155c09432e335178.jpg', 'https://phimimg.com/upload/vod/20231110-1/3328c76fce1a26838625ca350405e5e8.jpg', '<p>Mardock Scramble: The First Compression là phim đầu tiên trong bộ ba phim do studio anime GoHands thực hiện. Một cô gái điếm trẻ tên là Rune Balot đã mất mạng trong một vụ nổ, nhưng lại được Dr. Easter cứu sống. Hồi sinh trong thân thể một cyborg hiện đại, Balot đối đầu với những tên tội phạm tồi tệ nhất thành phố Mardock để trả thù.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Megumi Hayashibara","avatar":""},{"name":"Norito Yashima","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Tsutomu Isobe","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Masahiko Tanaka","avatar":""},{"name":"Mika Kanai","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Tomohiro Waki","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
