INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-thu', 'Vương Quốc Thú', 'Animals United', 'https://phimimg.com/upload/vod/20231109-1/277a405fea01ad27b237157187338c5f.jpg', 'https://phimimg.com/upload/vod/20231109-1/51121b4cff6a62ff081a55777b278aa0.jpg', '<p>Một nhóm động vật đang chờ lũ lụt hàng năm mà chúng dựa vào để kiếm thức ăn và nước uống phát hiện ra rằng con người, những kẻ đang phá hủy môi trường sống của chúng đã xây dựng một con đập cho một khu nghỉ dưỡng. Các loài động vật nỗ lực cứu vùng đồng bằng và gửi thông điệp tới con người không can thiệp vào thiên nhiên.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2010, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Christoph Maria Herbst","avatar":""},{"name":"Ralf Schmitz","avatar":""},{"name":"Thomas Fritsch","avatar":""},{"name":"Bastian Pastewka","avatar":""},{"name":"Oliver Kalkofe","avatar":""},{"name":"Nana Spier","avatar":""},{"name":"Constantin von Jascheroff","avatar":""},{"name":"Jessica Owen","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
