INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-do-ke-thu-xua', 'Đụng Độ Kẻ Thù Xưa', 'You Again', 'https://phimimg.com/upload/vod/20231109-1/003b645162350537f055d11ddfd23e59.jpg', 'https://phimimg.com/upload/vod/20231109-1/6af1f5d2f1c190cc6e6259cd71547a45.jpg', '<p>Marni phát hiện ra rằng vị hôn thê của anh trai mình lại chính là Joana người đã từng trêu ghẹo cô suốt thời trung học và không hề hiền lành như vẻ bên ngoài. Vì thế, Marni quyết tâm lột mặt nạ của cô nàng yêu nữ này. Trớ trêu thay, mẹ của Joana lại cũng có xích mích ngay từ nhỏ với mẹ của Marni. Những tình huống dở khóc dở cười nào sẽ chờ đợi khán giả khi cuộc đối đầu của Joana và Marni cùng hai bà mẹ diễn ra...</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Bell","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Betty White","avatar":""},{"name":"James Wolk","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Sean Wing","avatar":""},{"name":"Kyle Bornheimer","avatar":""},{"name":"William Brent","avatar":""},{"name":"Christine Lakin","avatar":""},{"name":"Meagan Holder","avatar":""},{"name":"Patrick Duffy","avatar":""},{"name":"Anna A. White","avatar":""},{"name":"Brytni Sarpy","avatar":""},{"name":"Gelsey Weis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324475);
