INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-do-ke-thu-xua', 'Đụng Độ Kẻ Thù Xưa', 'You Again', 'đụng độ kẻ thù xưa you again kristen bell jamie lee curtis sigourney weaver odette annable victor garber betty white james wolk kristin chenoweth sean wing kyle bornheimer william brent christine lakin meagan holder patrick duffy anna a. white brytni sarpy gelsey weis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-phai-ac-quy', 'Gặp Phải Ác Quỷ', 'I Saw the Devil', 'https://phimimg.com/upload/vod/20231109-1/e71210f8c515ef3ce5781e6ba56a1980.jpg', 'https://phimimg.com/upload/vod/20231109-1/66afb938e8b09ab04a2d5dd59a684b3f.jpg', '<p>Jang Kyung Cheol là 1 kẻ tâm thần xem giết ngườ như 1 thú vui. Hắn đã thực hiện hàng loạt những vụ giết người theo 1 cách ma quỷ mà con người không thể tưởng tượng nổi và nạn nhân của hắn bao gồm cả phụ nữ lẫn trẻ em. Cảnh sát đã lần theo hắn trong suốt 1 thời gian dài những cũng không tóm được hắn.
 Một ngày, con gái của 1 cảnh sát trưởng về hưu đã trở thành con mồi của hắn và được tìm thấy đã chết trong tình trạng khủng khiếp. Hôn phu của cô, Kim Soo Hyun, một mật vụ hàng đầu, quyết định tự mình săn đuổi hắn. Anh đã thề với lòng sẽ trả thù đẫm máu kẻ giết người, cho dù điều đó có nghĩa là chính anh phải trở thành một con quỷ.</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Oh San-ha","avatar":""},{"name":"Kim Yoon-seo","avatar":""},{"name":"Nam Bo-ra","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Yoon Chae-yeong","avatar":""},{"name":"Choi Moo-sung","avatar":""},{"name":"Kim In-seo","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Mi-nam Jeong","avatar":""},{"name":"Jo Deok-jae","avatar":""},{"name":"Jang Jeong-won","avatar":""},{"name":"Park Seo-yeon","avatar":""},{"name":"Lee Seo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
