INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-bao-ve-cong-chua', 'Kế Hoạch Bảo Vệ Công Chúa', 'Princess Protection Program', 'https://phimimg.com/upload/vod/20231109-1/517787522a9472a470df388f9cdee72f.jpg', 'https://phimimg.com/upload/vod/20231109-1/1cef2509c7b90e413f931b42cf1e6e86.jpg', '<p>Khi quốc gia của cô bị xâm lược, một công chúa trẻ được đưa vào Chương trình Bảo vệ Công chúa. Cô được chuyển đến Louisiana, nơi cô ở với một đặc vụ bí mật và cô con gái tomboy của anh ta, đồng thời phải học cách cư xử như một thiếu niên bình thường.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Demi Lovato","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Tom Verica","avatar":""},{"name":"Molly Hagan","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Johnny Ray Rodríguez","avatar":""},{"name":"Robert Adamson","avatar":""},{"name":"Samantha Droke","avatar":""},{"name":"Sully Díaz","avatar":""},{"name":"Kevin G. Schmidt","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Brian Tester","avatar":""},{"name":"Magda Rodriguez","avatar":""},{"name":"Talia Rothenberg","avatar":""},{"name":"Ricardo Álvarez","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
