INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-2-ton-su-truyen-ky', 'Diệp Vấn 2: Tôn Sư Truyền Kỳ', 'Ip Man 2', 'https://phimimg.com/upload/vod/20231108-1/fcc5f9a947afd976cfd0ca152f105a5b.jpg', 'https://phimimg.com/upload/vod/20231108-1/782ffe409b293ebad1341060b2e8e86e.jpg', '<p>Diệp Vấn 2 tiếp nối kết thúc của phần 1, tập trung vào những sóng gió trong cuộc đời của Diệp Vấn tại Hong Kong. Diệp Vấn là bậc thầy của môn phái Vịnh Xuân và chính những năm tháng sống tại Hong Kong đã giúp ông sáng tạo nhiều thế võ đặc sắc riêng của mình. Ngoài ra, ông còn chính sư phụ của huyền thoại võ thuật Lý Tiểu Long. Với cốt truyện li kì hấp dẫn, cộng với đạo diễn và dàn diễn viên nổi tiếng, tài năng Chân Tử Đan và Hùng Đại còn có nhiều diễn viên tên tuổi khác như Hồng Kim Bảo, Huỳnh Hiểu Minh, Thích Tiểu Long...., Diệp Vấn 2 đã tạo ra cơn sốt khi công chiếu rộng rãi tại các rạp Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Lynn Hung","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Ngo Ka-nin","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Calvin Ka-Sing Cheng","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Darren Shahlavi","avatar":""},{"name":"Ashton Chen","avatar":""},{"name":"Li Chak","avatar":""},{"name":"Jiang Daiyan","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Lam Hak-Ming","avatar":""},{"name":"Charles Mayer","avatar":""},{"name":"Bria","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
