INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('camp-rock-2-the-final-jam', 'Camp Rock 2: The Final Jam', 'Camp Rock 2: The Final Jam', 'https://phimimg.com/upload/vod/20231108-1/011f747a02b8d94c152c9044769ec876.jpg', 'https://phimimg.com/upload/vod/20231108-1/8f556c3f55cf5e32ba4af02d96ac8716.jpg', '<p>Mitchie nóng lòng muốn quay lại Camp Rock và dành cả mùa hè để sáng tác nhạc mới cùng bạn bè và siêu sao Shane Grey. Nhưng trại mới bóng bẩy bên kia hồ, Trại Ngôi sao, đã gây ra một số cuộc cạnh tranh nghiêm trọng - có sự góp mặt của những người mới đến Luke và Dana. Trong một trận chiến giật gân của các ban nhạc, với tương lai của Camp Rock đang bị đe dọa, liệu quá trình sản xuất hào nhoáng và những trò hề đỉnh cao của Camp Star sẽ chiến thắng hay Camp Rockers sẽ chứng minh rằng âm nhạc, tinh thần đồng đội và tinh thần mới là điều thực sự quan trọng?</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Demi Lovato","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Roshon Fegan","avatar":""},{"name":"Joe Jonas","avatar":""},{"name":"Nick Jonas","avatar":""},{"name":"Kevin Jonas","avatar":""},{"name":"Meaghan Jette Martin","avatar":""},{"name":"Chloe Bridges","avatar":""},{"name":"Maria Canals-Barrera","avatar":""},{"name":"Daniel Fathers","avatar":""},{"name":"Daniel Kash","avatar":""},{"name":"Matthew Finley","avatar":""},{"name":"Anna Maria Perez de Tagle","avatar":""},{"name":"Jasmine Richards","avatar":""},{"name":"Jordan Francis","avatar":""},{"name":"Erin Pitt","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chương Trình Truyền Hình","slug":"chuong-tr