INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-guom-mau', 'Lưỡi Gươm Máu', 'Blades of Blood', 'https://phimimg.com/upload/vod/20231108-1/5e2bbcbee7928df93ee4eed5342c465c.jpg', 'https://phimimg.com/upload/vod/20231108-1/ab94877ad9ffe735e1119e7e8ae3d6b3.jpg', '<p>Bộ phim xoay quanh thời kỳ vương triều Joseon (1392-1910) trước bờ vực của cuộc xâm lăng của Nhật vào thế kỷ 16, đây là giai đoạn đất nước rơi vào hỗn loạn về chính trị và xã hội. Phim có nhiều pha hài hước với sự xuất hiện của ông vua Seonjo cáu kỉnh và khá nhạt nhẽo, cùng hai phe phái đối lập chỉ tập trung vào việc lấy lòng ông hơn là tìm cách giải quyết các vấn đề.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Seung-won","avatar":""},{"name":"Hwang Jung-min","avatar":""},{"name":"Baek Sung-hyun","avatar":""},{"name":"Han Ji-hye","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Shin Jung-geun","avatar":""},{"name":"Lee Dal-Hyeong","avatar":""},{"name":"Yum Dong-hun","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Yang Yeong-Jo","avatar":""},{"name":"Lee Young-suk","avatar":""},{"name":"Seo Seung-won","avatar":""},{"name":"Jeong Gyu-su","avatar":""},{"name":"Ji Il-ju","avatar":""},{"name":"Yun Yeong-keol","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
