INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-quy', 'Mộ Quỷ', 'The Shrine', 'https://phimimg.com/upload/vod/20231108-1/a71314f01dab1df726f97ca7eaefa0e2.jpg', 'https://phimimg.com/upload/vod/20231108-1/b0aaddf014f90706f88c82f9faa87561.jpg', '<p>Một nhóm các nhà báo trẻ điều tra một giáo phái để biết được quy trình hiến tế, nhưng cách đầy tham vọng của họ có thể dẫn họ trở thành nạn nhân tiếp theo của giáo phái...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Aaron Ashmore","avatar":""},{"name":"Cindy Sampson","avatar":""},{"name":"Meghan Heffern","avatar":""},{"name":"Ben Lewis","avatar":""},{"name":"Trevor Matthews","avatar":""},{"name":"Vieslav Krystyan","avatar":""},{"name":"Laura de Carteret","avatar":""},{"name":"Monica Hewes","avatar":""},{"name":"Connor Stanhope","avatar":""},{"name":"Stefen Hayes","avatar":""},{"name":"Julia Debowska","avatar":""},{"name":"David Tompa","avatar":""},{"name":"Alexander Krstich","avatar":""},{"name":"Neil Davison","avatar":""},{"name":"Wojtek Skrzeta","avatar":""},{"name":"Paulino Nunes","avatar":""},{"name":"Rod Pr","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324475);
