INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mo-quy', 'Mộ Quỷ', 'The Shrine', 'mộ quỷ the shrine aaron ashmore cindy sampson meghan heffern ben lewis trevor matthews vieslav krystyan laura de carteret monica hewes connor stanhope stefen hayes julia debowska david tompa alexander krstich neil davison wojtek skrzeta paulino nunes rod pr ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-choi-cong-bang', 'Luật Chơi Công Bằng', 'Fair Game', 'https://phimimg.com/upload/vod/20231108-1/f3a826c818ebad3c089fa136b57c7aec.jpg', 'https://phimimg.com/upload/vod/20231108-1/0a8417c3e30dedf55a42f6e2df0fec2f.jpg', '<p>Nội dung phim dựa trên cuốn hồi ký My Life as a Spy, My Betrayal by the White House của Valerie Plame. Valerie Plame là một đặc vụ C.I.A. bị tiết lộ thân phận sau khi chồng của cô là Joe Wilson - một cựu đại sứ ngoại giao Hoa Kỳ, tiến hành cuộc điều tra về chính quyền tổng thống Bush đã giả mạo các tài liệu, Joe cũng chứng minh rằng không hề có chương trình vũ khí hạt nhân nào tại Trung Đông và đã bắt đầu với một bài báo đăng trên New York Times, kết tội nước Mỹ không đủ bằng chứng để tấn công Iraq. Vì vậy, sự trừng phạt của Nhà Trắng giành cho hai vợ chồng, chính là nỗi sợ lớn nhất của một điệp vụ C.I.A. - đó là tiết lộ thân phận tuyệt mật của Valerie. Fair Game sẽ lột tả những bí mật đằng sau vụ bê bối chính trị này, và những sự kiện diễn ra sau đó.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Noah Emmerich","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"David Andrews","avatar":""},{"name":"Tim Griffin","avatar":""},{"name":"Liraz Charhi","avatar":""},{"name":"Khaled El Nabawy","avatar":""},{"name":"Sonya Davison","avatar":""},{"name":"Vanessa Chong","avatar":""},{"name":"Anand Tiwari","avatar":""},{"name":"Stephanie Chai","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Rebecca R","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
