INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-dau-khon-nguoi', 'Nỗi Đau Khôn Nguôi', 'Rabbit Hole', 'https://phimimg.com/upload/vod/20231108-1/dd4587597c592ce5acdc361ee8c2c3c3.jpg', 'https://phimimg.com/upload/vod/20231108-1/5cbf9fbe556be0d37ba8bf7b3af2beaa.jpg', '<p>Với thời lượng hơn 2 phút, đoạn trailer phần nào đã cho chúng ta thấy sự đau khổ, nỗi dằn vặt của cặp vợ chồng vừa mất đi đứa con yêu quý. Nhiều khán giả khi xem trailer đã bày tỏ sự đồng cảm với nỗi buồn sâu sắc của hai vợ chồng trong câu truyện này nhưng họ cho biết có một cảm giác của niềm hy vọng trong trailer và có lẽ nó sẽ xuyên suốt bộ phim. Rabbit Hole&quot; dựa trên một tác phẩm cùng tên của nhà soạn kịch nổi tiếng David Lindsay-Abaire, từng giành chiến thắng tại giải thưởng Pulitzer. Phim kể về nỗi dằn vặt của một cặp vợ chồng bị mất đi một người con trong một vụ tai nạn giao thông. Trong phim Nicole Kidman và Aaron Eckhart vào vai cặp vợ chồng đang phải chiến đấu với chính mình để giữ mối quan hệ sau ...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Stephen Mailer","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Roberta Wallach","avatar":""},{"name":"Patricia Kalember","avatar":""},{"name":"Ali Marsh","avatar":""},{"name":"Yetta Gottesman","avatar":""},{"name":"Colin Mitchell","avatar":""},{"name":"Deidre Goodwin","avatar":""},{"name":"Julie Lauren","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c4301