INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nhuan', 'Năm Nhuận', 'Leap Year', 'https://phimimg.com/upload/vod/20231108-1/abd64f7bbd70c4d439a5e343067a8043.jpg', 'https://phimimg.com/upload/vod/20231108-1/2aa07c98c6fc3c8ae4c102a1a34f14bb.jpg', '<p>Câu chuyện phim xoay quanh chuyến du lịch của Anna đến Dublin, Ireland để cầu hôn bạn trai Jeremy vào ngày 29/2, ngày của năm nhuận. Khi máy bay trên đường đến Dublin thì có một cơn bão to, phi công phải hạ cánh tại Cardiff. Anna nhận được sự giúp đỡ của một chủ quán trọ nhỏ - Declan. Cuối cuộc hành trình, Anna và Declan nhận ra tình yêu ngọt ngào dành cho nhau, nhưng đúng lúc ấy, vị hôn phu của cô xuất hiện…</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Noel O''Donovan","avatar":""},{"name":"Tony Rohr","avatar":""},{"name":"Pat Laffan","avatar":""},{"name":"Alan Devlin","avatar":""},{"name":"Ian McElhinney","avatar":""},{"name":"Dominique McElligott","avatar":""},{"name":"Mark O''Regan","avatar":""},{"name":"Maggie McCarthy","avatar":""},{"name":"Peter O''Meara","avatar":""},{"name":"Macdara Ó Fátharta","avatar":""},{"name":"Kaitlin Olson","avatar":""},{"name":"Liza Ross","avatar":""},{"name":"Marcia","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
