INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-tham-hoa-giua-hai-trai-dat', 'Liên Minh Công Lý: Thảm Họa Giữa Hai Trái Đất', 'Justice League: Crisis on Two Earths', 'https://phimimg.com/upload/vod/20231108-1/bb9d31b4e52ddcca5096e84efd7a9ab7.jpg', 'https://phimimg.com/upload/vod/20231108-1/46c38605c2fe593beb2217105a16902a.jpg', '<p>Những Siêu Nhân Công Lý là bộ phim hoạt hình nói về một thế giới tồn tại song song với trái đất, nơi mà con người cũng như mọi vật chất đều trái ngược so với Trái đất. Ở hành tinh này, mọi thứ bị cái ác thống trị và phải nhờ tới những siêu anh hùng ở Trái Đất giúp đỡ.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Baldwin","avatar":""},{"name":"James Woods","avatar":""},{"name":"Mark Harmon","avatar":""},{"name":"Gina Torres","avatar":""},{"name":"Vanessa Marshall","avatar":""},{"name":"Chris Noth","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Jonathan Adams","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Josh Keaton","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"James Patrick Stuart","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jim Meskimen","avatar":""},{"name":"Freddi Rogers","avatar":""},{"name":"Bruce Timm","avatar":""},{"name":"Cedric Yarbrough","avatar":""},{"name":"Kari","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324475)