INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-ba-tu-dong-cat-thoi-gian', 'Hoàng Tử Ba Tư: Dòng Cát Thời Gian', 'Prince of Persia: The Sands of Time', 'https://phimimg.com/upload/vod/20231108-1/0824f63eddaed9f376e91a7e2f31e8e4.jpg', 'https://phimimg.com/upload/vod/20231108-1/4765f3c0a2bcedd2464857b3251b36e0.jpg', '<p>Hoàng Tử Ba Tư: Dòng Cát Thời Gian là câu chuyện kể về Dastan, một &nbsp;chàng trai sống lang thang trên đường phố Ba Tư hồi thế kỷ 6. Nhà vua &nbsp;đã nhận anh làm con nuôi vì nhận thấy khí phách can trường từ Dastan. &nbsp;Khi tên thầy pháp ác độc Nizam (Ben Kingsley) lên kế hoạch chiếm đoạt &nbsp;Dòng Cát Thời Gian (Sands of Time), một món quà của thần linh có khả &nbsp;năng đảo ngược thời gian và thống trị thế giới, vị hoàng tử trẻ tuổi &nbsp;Dastan phải liên kết với công chúa xinh đẹp Tamina để cứu đất nước Ba &nbsp;Tư.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Steve Toussaint","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Richard Coyle","avatar":""},{"name":"Ronald Pickup","avatar":""},{"name":"Reece Ritchie","avatar":""},{"name":"Gísli Örn Garðarsson","avatar":""},{"name":"Claudio Pacifico","avatar":""},{"name":"Thomas DuPont","avatar":""},{"name":"Dave Pope","avatar":""},{"name":"Domonkos Párdányi","avatar":""},{"name":"Massimiliano Ubaldi","avatar":""},{"name":"Vladimir &a","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b