INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-tu-ba-tu-dong-cat-thoi-gian', 'Hoàng Tử Ba Tư: Dòng Cát Thời Gian', 'Prince of Persia: The Sands of Time', 'hoàng tử ba tư: dòng cát thời gian prince of persia: the sands of time jake gyllenhaal gemma arterton ben kingsley alfred molina steve toussaint toby kebbell richard coyle ronald pickup reece ritchie gísli örn garðarsson claudio pacifico thomas dupont dave pope domonkos párdányi massimiliano ubaldi vladimir &a ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-thi-co-nhi', 'Triệu Thị Cô Nhi', 'Sacrifice', 'https://phimimg.com/upload/vod/20231108-1/e6d01453e6825b3b3ad841d8ed8fb249.jpg', 'https://phimimg.com/upload/vod/20231108-1/ccd8048acc274b367d16be48e1b1e5b1.jpg', '<p>Năm 590 trước Công nguyên, vua Tấn Linh Công nghe lời sàm tấu của Đại tướng quân Đồ Ngạn Giả đã tru di gia tộc Thượng khanh Triệu Sóc. Sau này Tấn Linh Công kế vị, lại không ưa dùng trung thần Triệu Sóc, nghe theo sự chia rẽ của Đồ Ngạn Giả. Hơn 300 người nhà Triệu Sóc bị sát hại, chỉ có một đứa bé chưa được 6 tháng được Trình Anh cứu thoát. Để bảo vệ giọt máu nhà họ Triệu, 8 người trung nghĩa trải qua gian khổ phải hy sinh mạng sống, Trình Anh phải dùng con trai của mình để thay thế, bảo toàn mạng sống cho Triệu Vũ. Hai mươi năm sau, cô nhi này lớn lên, Trình Anh mới kể lại toàn bộ câu chuyện án oan năm xưa và Triệu Vũ quyết tâm báo thù rửa hận.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ge You","avatar":""},{"name":"Wang Xueqi","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Hai Qing","avatar":""},{"name":"Zhang Fengyi","avatar":""},{"name":"Arthur Chen","avatar":""},{"name":"Li Dongxue","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Bao Guoan","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Dong Wenjun","avatar":""},{"name":"Liu Yajin","avatar":""},{"name":"Zhao Wenhao","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâ