INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-cong-tram-xang-2', 'Tấn Công Trạm Xăng 2', 'Attack the Gas Station 2', 'https://phimimg.com/upload/vod/20231107-1/8c0fd964e5bc390db97f0406ca815702.jpg', 'https://phimimg.com/upload/vod/20231107-1/ace0e9fe7388b9764923c2101c5c145d.jpg', '<p>Đã 10 năm kể từ khi Mr. Trạm xăng của Park đã bị tấn công bởi các băng đảng mô tô. Để trả thù, Park thuê một bộ tứ gồm những cậu bé lém lỉnh: một tay đấm chết người, một cầu thủ bóng đá với cú đá cao sát thủ, một đô vật bụng phệ và một kẻ nghiện trò chơi điện tử thành thạo nghệ thuật lừa bịp. Nhưng những nhân viên này trở nên nguy hiểm hơn khi họ đòi trả lương quá hạn.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Hyun-woo","avatar":""},{"name":"Jo Han-sun","avatar":""},{"name":"Moon Won-ju","avatar":""},{"name":"Jeong Jae-hoon","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Kwon Yong-hoon","avatar":""},{"name":"Park Sang-myeon","avatar":""},{"name":"Lee Hyeon-ji","avatar":""},{"name":"Lee Do-young","avatar":""},{"name":"Tak Te-in","avatar":""},{"name":"Ryu Jae-min","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Na Hae-ri","avatar":""},{"name":"Lee Se-Mi","avatar":""},{"name":"Lee Myung-ho","avatar":""},{"name":"Kim Soo-ro","avatar":""},{"name":"Kim Seon-a","avatar":""},{"name":"So Jeong","avatar":""},{"name":"Lee Yu-mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324475);
