INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-an', 'Kết Án', 'Conviction', 'https://phimimg.com/upload/vod/20231114-1/fd51cf596ee7e36ef0d5cc01f6aefd05.jpg', 'https://phimimg.com/upload/vod/20231114-1/86fd1997b0f8c78796740160ad162afd.jpg', '<p>Khi Kenny, anh trai của Betty Anne Waters, bị bắt vì tội giết người và bị kết án chung thân vào năm 1983, Betty Anne, một người vợ ở Massachusetts và là mẹ của hai đứa con, đã cống hiến cuộc đời mình để lật ngược bản án giết người. Tin chắc rằng anh trai mình vô tội, Betty Anne đã vượt qua các trường trung học, đại học và cuối cùng là trường luật trong hành trình 18 năm giải thoát Kenny. Với sự giúp đỡ của người bạn thân nhất Abra Rice, Betty Anne tìm hiểu kỹ bằng chứng đáng ngờ do cảnh sát thị trấn nhỏ Nancy Taylor thu thập, tỉ mỉ lần lại các bước dẫn đến việc bắt giữ Kenny. Niềm tin vào anh trai - và hành trình tìm kiếm sự thật - thúc đẩy Betty Anne và nhóm của cô khám phá sự thật và sử dụng bằng chứng DNA với hy vọng minh oan cho Kenny.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Swank","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Peter Gallagher","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Loren Dean","avatar":""},{"name":"Conor Donovan","avatar":""},{"name":"Owen Campbell","avatar":""},{"name":"Tobias Campbell","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Karen Young","avatar":""},{"name":"Talia Balsam","avatar":""},{"name":"John Pyper-Ferguson","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Thomas D. Mahard","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
