INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-mot-truyen-cuoi', 'Như Một Truyện Cười', 'It''s Kind of a Funny Story', 'https://phimimg.com/upload/vod/20231103-1/b61089202179d825e5242384e52b1c98.jpg', 'https://phimimg.com/upload/vod/20231103-1/25033ffb416afc15741467792aff7b28.jpg', '<p>Dựa trên cuốn tiểu thuyết của Ned Vizzini, bộ phim nói về Craig Gilner, một thiếu niên đang trong cơn suy sụp, sau khi cố gắng kiềm chế để không nhảy cầu Brooklyn tự tử, cậu đã tới gặp bác sĩ tâm lý và đượckhuyên nên vào phòng điều trị tâm thần. Cậu đã ghi danh vào phòng điều trị dành cho người lớn, và tại đây, cậu bé đã gặp gỡ những người quái dị và một cô gái kỳ lạ. Cho tới khi ra viện, tuy bệnh tình của cậu chưa hoàn toàn khỏi hẳn nhưng cậu đã có thêm những niềm tin mới vào cuộc sống.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keir Gilchrist","avatar":""},{"name":"Emma Roberts","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Bernard White","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Dana DeVestern","avatar":""},{"name":"Karen Chilton","avatar":""},{"name":"Rosalyn Coleman","avatar":""},{"name":"Daniel London","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
