INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-den-do', 'Phố Đèn Đỏ', 'Monga', 'https://phimimg.com/upload/vod/20231103-1/a1413a2f9774e70615c55e913d2649f7.jpg', 'https://phimimg.com/upload/vod/20231103-1/7f6e6a8840611a963ba26f846fd69408.jpg', '<p>Câu chuyện lấy bối cảnh giữa thập niên 80. Muỗi, Monk, Rồng, Khỉ và A Bá là bạn học cùng trường phổ thông và cũng là thành viên của &quot;Băng đảng Hoàng tử&quot;. Năm cậu thanh niên rất ghét bị thúc ép và thích thú với lối sống băng đảng của họ. Họ dự định sẽ thu nạp nhóm đầu gấu nhất trên phố đèn đỏ.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Mark Chao","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Ma Ju-Lung","avatar":""},{"name":"Ko Chia-yen","avatar":""},{"name":"Rhydian Vaughan","avatar":""},{"name":"Doze Niu Cheng-Tse","avatar":""},{"name":"Cheng Yu-Chieh","avatar":""},{"name":"Bamboo Chen","avatar":""},{"name":"Tsai Chang-Hsien","avatar":""},{"name":"Chen Handian","avatar":""},{"name":"Shih-Sian Wang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
