INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-vuot-thoi-gian', 'Cô Gái Vượt Thời Gian', 'Time Traveller - The Girl Who Leapt Through Time 2010', 'https://phimimg.com/upload/vod/20231103-1/5ceef1c4f8b3840c245e0bb8ca1608b4.jpg', 'https://phimimg.com/upload/vod/20231103-1/a3811d40a5043eb267586bedd8054b52.jpg', '<p>Cô Gái Vượt Thời Gian - The Girl Who Leapt Through Time là bộ phim hoạt hình tâm lý hài Nhật 2006 của đạo diễn Mamoru Hosoda. Makoto Konno 17 tuổi, cô là 1 học sinh trung học. Cô có khả năng vượt thời gian và cô đã áp dụng điều kì diệu này để sửa lại kết quả học tập của mình. Bên cạnh đó, không ít những rắc rối đã xảy đến với cô. Cô dần nhận ra việc thay đổi quá khứ không hề đơn giản như vậy, và tương lai của cô và bạn bè mình phụ thuộc vào chính khả năng nguy hiểm này.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Riisa Naka","avatar":""},{"name":"Akiyoshi Nakao","avatar":""},{"name":"Narumi Yasuda","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Anna Ishibashi","avatar":""},{"name":"Shôta Chiyo","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Mayu Kitaki","avatar":""},{"name":"Yuya Matsushita","avatar":""},{"name":"Masanobu Katsumura","avatar":""},{"name":"Maya Okano","avatar":""},{"name":"Kanji Ishimaru","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324475);
