INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-bo-o-new-york', 'Khủng Bố Ở New York', 'Five Minarets in New York', 'https://phimimg.com/upload/vod/20231103-1/6a98c2c59f0e029888c58ea4aa282bdf.jpg', 'https://phimimg.com/upload/vod/20231103-1/ce2d87fdcb6e5d88d81ab996748c0c23.jpg', '<p>Phim Khủng Bố Ở New York là bộ phim tâm lý hành động xoay quanh hai đặc phái viên chống khủng bố Thổ Nhĩ Kỳ được gửi đến thành phố New York với sứ mạng và nhiệm vụ là phải tìm bằng được và mang về các nhà lãnh đạo Hồi giáo nguy hiểm, đặc biệt là tên cầm đầu là &quot;Dajjal&quot; được cho là lẩn trốn tại đó. Nhưng khi đến đây họ phát hiện ra mọi việc không đơn giản như vậy?</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gina Gershon","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Justine Cotsonas","avatar":""},{"name":"Mahsun Kırmızıgül","avatar":""},{"name":"Bob Ari","avatar":""},{"name":"Hisham Tawfiq","avatar":""},{"name":"Haluk Bilginer","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Scott William Winters","avatar":""},{"name":"Mustafa Sandal","avatar":""},{"name":"Engin Altan Düzyatan","avatar":""},{"name":"Sharrieff Pugh","avatar":""},{"name":"Laine Rettmer","avatar":""},{"name":"Rev. William Rueger","avatar":""},{"name":"Ryan Silverman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324475);
