INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-quyen-do-van', 'Thái Quyền Đo Ván', 'BKO: Bangkok Knockout', 'https://phimimg.com/upload/vod/20231112-1/8619173df2032a0afc9ae38090301cd6.jpg', 'https://phimimg.com/upload/vod/20231112-1/487ea6533529e99ea2871f7a77c76e08.jpg', '<p>Một nhóm võ sinh đang thưởng thức bữa tiệc đoàn tụ thì một quả bom phát nổ trong tòa nhà. Khi họ tỉnh dậy, một số người bạn của họ đã bị bắt cóc và họ sớm phát hiện ra một nhóm sát thủ đang truy đuổi họ. Cách duy nhất để tồn tại là chiến đấu để thoát ra.</p>', 'Full', 1, 'single', 'completed', 29, 2010, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chatchapol Kulsiriwuthichai","avatar":""},{"name":"Sarawoot Kumsorn","avatar":""},{"name":"Puchong Sartnok","avatar":""},{"name":"Supakson Chaimongkol","avatar":""},{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"Sumret Muengput","avatar":""},{"name":"Poonyapat Soonkunchanon","avatar":""},{"name":"Gitabak Agohjit","avatar":""},{"name":"Tanavit Wongsuwan","avatar":""},{"name":"Wirat Kemklad","avatar":""},{"name":"Sorapong Chatree","avatar":""},{"name":"Kiattisak Udomnak","avatar":""},{"name":"Krittiya Lard","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324475);
