INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-to-xac', 'Những Đứa Trẻ To Xác', 'New Kids Turbo', 'https://phimimg.com/upload/vod/20231103-1/e6d744fc21b250dd7cd51ff0e45aa513.jpg', 'https://phimimg.com/upload/vod/20231103-1/74a3314d3c10dcfb2e8b243544c4125f.jpg', '<p>Năm người bạn từ &#39;Maaskantje&#39; sắp bị sa thải vì khủng hoảng kinh tế. Họ quyết định rằng họ sẽ không trả tiền cho bất cứ điều gì nữa.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Tim Haars","avatar":""},{"name":"Huub Smit","avatar":""},{"name":"Wesley van Gaalen","avatar":""},{"name":"Flip van der Kuil","avatar":""},{"name":"Steffen Haars","avatar":""},{"name":"Theo Maassen","avatar":""},{"name":"Nicole van Nierop","avatar":""},{"name":"Reinout Oerlemans","avatar":""},{"name":"Hans Teeuwen","avatar":""},{"name":"Frank Lammers","avatar":""},{"name":"Lars Boekhorst","avatar":""},{"name":"Peter Aerts","avatar":""},{"name":"Annemieke Bakker","avatar":""},{"name":"Marco Maas","avatar":""},{"name":"Ruud Matthijssen","avatar":""},{"name":"Bart de Rijk","avatar":""},{"name":"Daan van","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
