INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-le-bong-toi', 'Bên Lề Bóng Tối', 'Edge of Darkness', 'https://phimimg.com/upload/vod/20231103-1/093a6c1ac1f47036d4cff278db98763f.jpg', 'https://phimimg.com/upload/vod/20231103-1/1d712b393e7c4ea460740b6503094793.jpg', '<p>Bên Lề Bóng Đêm: Phim có nhịp độ chậm, kịch tính cao nhưng không dồn dập. Hành động ít đối thoại nhiều, và sự hồi hộp căng thẳng tăng lên từ từ cho đến khi bùng nổ thành sự phẫn nộ và giải thoát vào cuối phim. Nếu ta hình dung những phim Thriller khác như cảm giác bạn bị hụt chân, bị tuột dốc, bị ai đó săn đuổi, tấn công, thì khi xem phim này cảm giác của bạn sẽ giống như bị bóp cổ, nhưng không bóp mạnh mà bàn tay đó cứ siết chậm, thật chậm, từ từ, bạn sẽ nghẹt thở một cách chậm chạp và đến một lúc nào đó thực sự kinh hoàng vì cận kề cái chết.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"David Aaron Baker","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Damian Young","avatar":""},{"name":"Caterina Scorsone","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Wayne Duvall","avatar":""},{"name":"Gbenga Akinnagbe","avatar":""},{"name":"Gabrielle Popa","avatar":""},{"name":"Paul Sparks","avatar":""},{"name":"Christy Scott Cashma","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b0