INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-doan-la-ma', 'Binh Đoàn La Mã', 'Centurion', 'https://phimimg.com/upload/vod/20231103-1/e2f736c08843993d5b9f8f4941476b33.jpg', 'https://phimimg.com/upload/vod/20231103-1/e178ff4a6a8fbab689c7f5b9f33161dc.jpg', '<p>Năm 117 trước công nguyên, lãnh thổ của đế chế La Mã đã trải dài từ Ai Cập đến Tây Ban Nha, còn về phía Đông thì đến tận Hắc Hải. Thế nhưng, ở phía bắc nước Anh, đội quân xâm lược tàn bạo, số 13, lại bị chùn bước khi phải đối mặt với cuộc tập kích từ một kẻ thù “khó xơi”: bộ tộc Pict, những kẻ mọi rợ đáng sợ. Quintus Dias là người duy nhất còn sống sót trong một cuộc càn quét của bọn Pict lên pháo đài nằm gần vùng biên giới. Sau khi được tướng quân Virilus thuộc quân đoàn số 9 huyền thoại cứu mạng, Quintus cùng họ đi về phía bắc để tẩy sạch tất cả bọn Pict khỏi bề mặt Trái Đất này cũng như giết kẻ cầm đầu bọn chúng, tên Gorlacon. Thế nhưng, khi quân đoàn bị phục kích tại một khu vực hoàn toàn lạ lẫm còn Virilus thì bị bắt, Quintus phải đấu tranh trong tuyệt vọng nhằm duy trì đội quân nhỏ nhoi còn sống lại trong lãnh địa của kẻ thù. Cố gắng chịu đựng địa hình khắc nghiệt và những cuộc tấn công như vũ bão của bọn Pict do tên Etain khát máu cầm đầu, cả đội quân như chạy đua với thời gian để có thể đến giải cứu cho tướng quân Virilus và trở về đất nước an toàn.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"JJ Feild","avatar":""},{"name":"Noel Clarke","avatar":""},{"name":"Dimitri Leonidas","avatar":""},{"name":"Riz Ahmed","avatar":""},{"name":"Paul Freeman","avatar":""},{"name":"Dave Legeno","avatar":""},{"name":"Axelle Carolyn","avatar":""},{"name":"Andreas Wisniewski","avatar":""},{"name":"Jake Maskall","avatar":""},{"name":"Eoin Macken","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324476);
