INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('binh-doan-la-ma', 'Binh Đoàn La Mã', 'Centurion', 'binh đoàn la mã centurion michael fassbender olga kurylenko david morrissey liam cunningham dominic west imogen poots ulrich thomsen jj feild noel clarke dimitri leonidas riz ahmed paul freeman dave legeno axelle carolyn andreas wisniewski jake maskall eoin macken ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-tro-choi', 'Vua Trò Chơi', 'Yu-Gi-Oh! Bonds Beyond Time', 'https://phimimg.com/upload/vod/20231103-1/9d8c923565f2a6deacedba005f8afe41.jpg', 'https://phimimg.com/upload/vod/20231103-1/c7ae3107c168a70c1dfb9cd8a2e7febd.jpg', '<p>Stardust Dragon, chủ bài của Yusei Fudo bị một kẻ mang mặt nạ đánh cắp. Thành phố Neo Domino bắt đầu sụp đỗ, còn tại một thời gian khác, Yuki Judai bị những con rồng hùng mạnh nhất tấn công. Còn sau cùng, ở thời của Yugi Mutou, bầu trời bị những chiếc bóng bao phủ, khu thương xá sụp đổ, kéo theo những người đứng dưới nó, bao gồm cả Pegasus và Sugoroku Mutou, ông của Yugi. Rốt cuộc chuyện gì đang xảy ra, kẻ đeo mặt nạ là ai, mục tiêu của hắn là gì? Số phận của Duel Monster, cũng như của cả thế giới đang nằm trong tay 3 anh hùng của chúng ta, một người có sức mạnh của Supreme King cũng như Yubel, một người có sức mạnh của Crismson Dragon, và một người mang trong mình Linh hồn Pharaoh vô danh với sức mạnh của Trò chơi ngàn năm.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Atsushi Tamura","avatar":""},{"name":"KENN","avatar":""},{"name":"Shunsuke Kazama","avatar":""},{"name":"Yuya Miyashita","avatar":""},{"name":"Ai Horanai","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Jirou Jay Takasugi","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Mika Ishibashi","avatar":""},{"name":"Shintaro Asanuma","avatar":""},{"name":"Takanori Hoshino","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Kazunari Kojima","avatar":""},{"name":"Yûki Nakao","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324476);
