INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-tro-choi', 'Vua Trò Chơi', 'Yu-Gi-Oh! Bonds Beyond Time', 'vua trò chơi yu-gi-oh! bonds beyond time atsushi tamura kenn shunsuke kazama yuya miyashita ai horanai hiromi tsuru jirou jay takasugi kappei yamaguchi mika ishibashi shintaro asanuma takanori hoshino yuka terasaki kazunari kojima yûki nakao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tinh-nhan-xanh', 'Lễ Tình Nhân Xanh', 'Blue Valentine', 'https://phimimg.com/upload/vod/20231103-1/23bb8487d2c2bb1adfa74b545175839a.jpg', 'https://phimimg.com/upload/vod/20231103-1/5161ef0c2819f9c168f120cdaf61f4c6.jpg', '<p>Dean Pereira và Cindy Heller Pereira là đôi vợ chồng trẻ. Cả hai đều có những bất hạnh trong cuộc sống và họ đã đến với nhau bằng những kinh nghiệm họ đã trải qua trong cuộc sống hôn nhân. Dean, bỏ học cấp 3, xuất thân trong một gia đình tan vỡ, nơi mà anh chưa hề có một người mẹ thật sự. Anh chưa bao giờ xem là mình đã kết hôn hay có gia đình, dù có một tình yêu sét đánh với Cindy. Anh không có tham vọng nghề nghiệp nào ngoài công việc hiện tại - vì việc uống cạn cốc bia lúc 8 giờ sáng không hề ảnh hưởng đến công việc đó - trong khi Cindy luôn tin rằng anh rất có tiềm năng trong cuộc sống. Cindy cũng xuất thân trong một gia đình không hạnh phúc, với cả cha lẫn mẹ đều không tạo được tấm gương đẹp nào về cuộc sống hôn nhân và gia đình. Hãy cùng xem chuyện gì sẽ xảy ra khi cả 2 phải đối mặt với sự đổ vỡ....</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"John Doman","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"Ben Shenkman","avatar":""},{"name":"Jen Jones","avatar":""},{"name":"Maryann Plunkett","avatar":""},{"name":"Faith Wladyka","avatar":""},{"name":"Marshall Johnson","avatar":""},{"name":"James Benatti","avatar":""},{"name":"Barbara Troy","avatar":""},{"name":"Carey Westbrook","avatar":""},{"name":"Eileen Rosen","avatar":""},{"name":"Enid Graham","avatar":""},{"name":"Ashley Gurnari","avatar":""},{"name":"Jack Parshutich","avatar":""},{"name":"Samii Ryan","avatar":""},{"name":"Mark","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324476);
