INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-nat', 'Đổ Nát', 'Wrecked', 'https://phimimg.com/upload/vod/20231103-1/dde6e5f3473a95532aa739062ca3a516.jpg', 'https://phimimg.com/upload/vod/20231103-1/3e411517c61132b4edbf5f4632bc42f5.jpg', '<p>Một người đàn ông tỉnh dậy trong một vụ tai nạn ô tô dưới chân một vách đá dựng đứng. Anh ta không thể nhớ mình là ai hoặc làm thế nào anh ta đến đó, nhưng một báo cáo qua đài phát thanh đã lấp đầy một số chỗ trống, vì nó mô tả một vụ cướp ngân hàng bạo lực và nêu tên một thủ phạm tình cờ ngồi chết ở ghế sau.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Caroline Dhavernas","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Adrian Holmes","avatar":""},{"name":"Adrian G. Griffiths","avatar":""},{"name":"Lloyd Adams","avatar":""},{"name":"Mark McConchie","avatar":""},{"name":"Jacob Blair","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324476);
