INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-dai-bac', 'Tạm Biệt Đài Bắc', 'Au Revoir Taipei', 'https://phimimg.com/upload/vod/20231111-1/4410b9f3d52ce1fd3334d248411d941f.jpg', 'https://phimimg.com/upload/vod/20231111-1/595dfe20ee6ef6583ff7eb0cb833cc56.jpg', '<p>Tạm Biệt Đài Bắc - Au Revoir Taipei (2010): Luôn thương nhớ người bạn gái cũ đang học tại Paris, Tiểu Khải vùi đầu học tiếng Pháp đồng thời thỏa thuận với một tên cướp để có được tấm vé đến thiên đường lãng mạn này. Anh chàng không hề biết rằng anh đã &quot;hút hồn&quot; của cô bán hàng Susie. Thế nhưng vào đêm trước khi khởi hành tới Paris, một loạt những hiểu lầm và trùng hợp đã đưa anh và Susie lại gần nhau.</p>', 'Full', 1, 'single', 'completed', 18, 2010, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Jack Yao","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Joseph Chang","avatar":""},{"name":"Lawrence Ko","avatar":""},{"name":"Frankie Kao","avatar":""},{"name":"Paul Chiang","avatar":""},{"name":"Peggy Tseng","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Vera Yen","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Linda Liu","avatar":""},{"name":"Shih-Ping Yang","avatar":""},{"name":"Bo-Syuan Wang","avatar":""},{"name":"Brian Wong","avatar":""},{"name":"Chin Lun Hsia","avatar":""},{"name":"Jonah Tseng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
