INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-biet-dai-bac', 'Tạm Biệt Đài Bắc', 'Au Revoir Taipei', 'tạm biệt đài bắc au revoir taipei jack yao amber kuo joseph chang lawrence ko frankie kao paul chiang peggy tseng tony yang vera yen jack kao linda liu shih-ping yang bo-syuan wang brian wong chin lun hsia jonah tseng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-tieu-hoang-dai', 'Mục Tiêu Hoang Dại', 'Wild Target', 'https://phimimg.com/upload/vod/20231103-1/dbe996f0aef2cb5cc08babef8f37dc5d.jpg', 'https://phimimg.com/upload/vod/20231103-1/e240286f4696196210746fb09fd49ffc.jpg', '<p>Victor Maynard là một sát thủ trung niên, sống đơn độc, sống để làm hài lòng người mẹ ghê gớm của mình, bất chấp danh tiếng vô song về hiệu quả giết người của chính mình. Thói quen nghề nghiệp của anh ta bị gián đoạn khi anh ta thấy mình bị thu hút bởi một trong những nạn nhân dự định của mình. Sau khi tha mạng cho cô, anh bất ngờ có được một người học việc trẻ tuổi. Tin rằng Victor là một thám tử tư, hai người bạn đồng hành mới của anh ta theo đuổi, trong khi anh ta cố gắng ngăn chặn sự chú ý giết người của khách hàng bất hạnh của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Eileen Atkins","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Geoff Bell","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Graham Seed","avatar":""},{"name":"James O''Donnell","avatar":""},{"name":"George Rainsford","avatar":""},{"name":"Alexis Rodney","avatar":""},{"name":"Gregor Fisher","avatar":""},{"name":"Duncan Duff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
