INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-hieu-vo-hinh', 'Ám Hiệu Vô Hình', 'An Invisible Sign', 'https://phimimg.com/upload/vod/20231102-1/27b4a4e771d2e9783b47126458b8b181.jpg', 'https://phimimg.com/upload/vod/20231102-1/f1ec6c0f9b236cdc3d0d80c3988ed296.jpg', '<p>Mona Grey là một cô gái 20 tuổi có cuộc sống khá cô độc, yên tĩnh. Khi cô còn nhỏ, sau lần bố cô đột ngột đột quỵ, kỳ lạ thay, cô từ bỏ mọi thú vui chuyển học hành chăm chỉ, mong có thể cứu sống cha cô bị bệnh. Khi trưởng thành, Mona đã dạy môn này và phải giúp các em học sinh của mình vượt qua những khủng hoảng của chính họ.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Alba","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Sônia Braga","avatar":""},{"name":"John Shea","avatar":""},{"name":"Sophie Nyweide","avatar":""},{"name":"Marylouise Burke","avatar":""},{"name":"Ashlie Atkinson","avatar":""},{"name":"Crystal Bock","avatar":""},{"name":"Mackenzie Milone","avatar":""},{"name":"Ian Colletti","avatar":""},{"name":"Jake Siciliano","avatar":""},{"name":"Stephanie DeBolt","avatar":""},{"name":"Joanna Adler","avatar":""},{"name":"Donovan Fowler","avatar":""},{"name":"Emerald-Ang","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
