INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-buoi-sang', 'Xin Chào Buổi Sáng', 'Morning Glory', 'https://phimimg.com/upload/vod/20231102-1/50c65c31fb2d73530f8dfc6f289520b2.jpg', 'https://phimimg.com/upload/vod/20231102-1/497e536d4cbd45da65f83333d4a5485d.jpg', '<p>Phim xoay quanh một cặp đôi phát thanh viên Becky Fuller và Mike Pomeroy có tính cách trái ngược nhau, cộng tác trong một chương trình vào chào buổi sáng đầy tính thử thách, và đang có nguy cơ bị đóng cửa. Với tính cách xung đột nhau, liệu họ có thể hợp tác để vực dậy được chương trình của họ hay không...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel McAdams","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"John Pankow","avatar":""},{"name":"Matt Malloy","avatar":""},{"name":"J. Elaine Marcos","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"David Fonteno","avatar":""},{"name":"Vanessa Aspillaga","avatar":""},{"name":"Patti D''Arbanville","avatar":""},{"name":"Jayne Houdyshell","avatar":""},{"name":"Jeff Hiller","avatar":""},{"name":"Linda Powell","avatar":""},{"name":"Mike Hydeck","avatar":""},{"name":"Jerome","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324476);
