INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('reu', 'Rêu', 'Moss', 'https://phimimg.com/upload/vod/20231110-1/1d4852292ff9c6ad2d1d2b868ab21a31.jpg', 'https://phimimg.com/upload/vod/20231110-1/22de7a80439933cd88efa0a09f5cee42.jpg', '<p>Một cậu bé thành phố đến thăm một ngôi làng hẻo lánh để tìm hiểu lý do đằng sau cái chết kỳ lạ của cha mình. Người dân địa phương đang theo dõi mọi hành động của anh ấy và háo hức muốn thấy anh ấy rời đi. Khi anh bắt đầu điều tra, những bí mật độc ác của ngôi làng bắt đầu được làm sáng tỏ.</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hae-il","avatar":""},{"name":"Jung Jae-young","avatar":""},{"name":"Yu Jun-sang","avatar":""},{"name":"Yu Seon","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"O Sun-tae","avatar":""},{"name":"Yun Areum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324476);
