INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oh-invisible-man', 'Oh! Invisible Man', 'Oh! Invisible Man', 'https://phimimg.com/upload/vod/20231109-1/e369c0c57797577ccf97f9023cbc912e.jpg', 'https://phimimg.com/upload/vod/20231109-1/a266cc977071490c5d0efc257dbce7fd.jpg', '<p>Một cậu bé học sinh trung học bỗng phát hiện ra khả năng có thể biến thành người tàng hình của mình. Điều này đã vô tình dẫn đến những tình huống éo le khi cậu bé lại sống trong một gia đình với rất đông phụ nữ...</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Emi Yanagimoto","avatar":""},{"name":"Yuri Murakami","avatar":""},{"name":"Enoku Shimegi","avatar":""},{"name":"Yû Kawana","avatar":""},{"name":"Maika Suzuki","avatar":""},{"name":"Akitoshi Ohtaki","avatar":""},{"name":"Shiko","avatar":""},{"name":"Ito Haruka","avatar":""},{"name":"Bob Suzuki","avatar":""},{"name":"Takashi Omoto","avatar":""},{"name":"Kouichi Ikai","avatar":""},{"name":"Takako Sato","avatar":""},{"name":"Yakan Nabe","avatar":""},{"name":"Yoshifumi Ikeda","avatar":""},{"name":"Meme","avatar":""},{"name":"Aya Mizusaki","avatar":""},{"name":"Mitsuko Hoshi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
