INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-me-chat-dong-que', 'Mạnh Mẽ Chất Đồng Quê', 'Country Strong', 'https://phimimg.com/upload/vod/20231101-1/d292b368dce4721e578a7c0a89c4aab9.jpg', 'https://phimimg.com/upload/vod/20231101-1/7d3b4dc3e5604e8679c3e7bb43db26ed.jpg', '<p>Ngay sau khi ca sĩ kiêm nhạc sĩ trẻ đang lên Beau Williams có quan hệ với ngôi sao đồng quê sa ngã, cảm xúc không ổn định Kelly Canter, cặp đôi bắt đầu chuyến lưu diễn hồi sinh sự nghiệp do chồng cô/người quản lý James chỉ đạo và có sự góp mặt của nữ hoàng sắc đẹp trở thành ca sĩ Chiles Stanton. Giữa các buổi hòa nhạc, những vướng mắc lãng mạn và những con quỷ già đe dọa sẽ làm hỏng tất cả.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gwyneth Paltrow","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Tim McGraw","avatar":""},{"name":"Leighton Meester","avatar":""},{"name":"Marshall Chapman","avatar":""},{"name":"Lari White","avatar":""},{"name":"Jeremy Childs","avatar":""},{"name":"James DeForest Parker","avatar":""},{"name":"Lisa Stewart","avatar":""},{"name":"Jackie Welch","avatar":""},{"name":"Cinda McCain","avatar":""},{"name":"Gabe Sipos","avatar":""},{"name":"Sandra Harris","avatar":""},{"name":"Megan Henderson","avatar":""},{"name":"Dan Beene","avatar":""},{"name":"Reegus Flenory","avatar":""},{"name":"Terri Mint","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324476);
