INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-com-hang-hai', 'Những Tay Cớm Hạng Hai', 'The Other Guys', 'https://phimimg.com/upload/vod/20231029-1/2b415282bbc692a67e8a6df0142ec152.jpg', 'https://phimimg.com/upload/vod/20231029-1/38bce977c0d64e283f8cd2012fd82775.jpg', '<p>Terry Hoitz và Allen Gamble là 2 thanh tra của sở cảnh sát New York nhưng hằng ngày chỉ ngồi bàn giấy với công việc nhập dữ liệu nhàm chán. Trái ngược với Allen Gamble hoàn toàn an phận và chấp nhận công việc tẻ nhạt, Terry Hoitz muốn bứt phá thoát khỏi tình cảnh hiện tại. &nbsp;Điều gì sẽ xảy ra khi Danson và Highsmith biến mất? Terry Hoitz sẽ làm gì để lôi kéo Allen Gamble rời bỏ bàn giấy để trở thành người hùng hành động?</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Lindsay Sloane","avatar":""},{"name":"Natalie Zea","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Damon Wayans Jr.","avatar":""},{"name":"Derek Jeter","avatar":""},{"name":"Larnell Stovall","avatar":""},{"name":"Jalil Jay Lynch","avatar":""},{"name":"Roy T. Anderson","avatar":""},{"name":"Andrew Secu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324476);
