INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paris-ruc-lua', 'Paris Rực Lửa', 'From Paris with Love', 'https://phimimg.com/upload/vod/20231030-1/5d50e5bd839b8f0c36366702dd12316c.jpg', 'https://phimimg.com/upload/vod/20231030-1/6faf844fdefdb78512b48313a8a7523b.jpg', '<p>James Reese có công việc tốt là trợ lý đại sứ tại Pháp, nhưng niềm đam mê thực sự của anh ấy là một công việc phụ—làm việc với một vai trò nhỏ trong CIA. Anh ấy rất muốn trở thành một đặc vụ chính thức và không thể tin vào vận may của mình khi nhận được nhiệm vụ với Charlie Wax. Charlie vui vẻ sớm khiến James khóc vì công việc bàn giấy của mình, nhưng khi anh biết rằng chính những kẻ mà họ đang cố truy bắt đang theo đuổi anh, James nhận ra rằng Charlie có thể là hy vọng sống sót duy nhất của anh.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"John Travolta","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Kasia Smutniak","avatar":""},{"name":"Richard Durden","avatar":""},{"name":"Bing Yin","avatar":""},{"name":"Amber Rose Revah","avatar":""},{"name":"Eric Godon","avatar":""},{"name":"François Bredon","avatar":""},{"name":"Chems Dahmani","avatar":""},{"name":"Sami Darr","avatar":""},{"name":"Julien Hagnery","avatar":""},{"name":"Mostéfa Stiti","avatar":""},{"name":"Rebecca Dayan","avatar":""},{"name":"Michaël Vander-Meiren","avatar":""},{"name":"Didier Constant","avatar":""},{"name":"Alexandra Boyd","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324476);
