INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('paris-ruc-lua', 'Paris Rực Lửa', 'From Paris with Love', 'paris rực lửa from paris with love john travolta jonathan rhys meyers kasia smutniak richard durden bing yin amber rose revah eric godon françois bredon chems dahmani sami darr julien hagnery mostéfa stiti rebecca dayan michaël vander-meiren didier constant alexandra boyd m ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho-3d', 'Vũ Điệu Đường Phố 3D', 'Step Up 3D', 'https://phimimg.com/upload/vod/20231029-1/3a65b5a1aa8b738a765f5e355c7853a0.jpg', 'https://phimimg.com/upload/vod/20231029-1/1fcd9ac51121c8694e80e67aa45d6728.jpg', '<p>Step Up 3D là phần tiếp theo bộ phim âm nhạc thể thao nổi tiếp Step Up. Nhưng lần này, cốt truyện được chia làm hai câu chuyện chính. Sau khi tốt nghiệp trung học, Moose cùng cô bạn Carmille chuyển đến New York để theo học đại học. Từng yêu thích nhảy Hip hop nhưng do bố mẹ ngăn cấm nên cả hai phải từ bỏ đam mê. Nhưng ngay trong ngày đầu tới trường, mọi chuyện đột nhiên thay đổi khi Moose tình cờ “khiêu chiến” với nhóm nhảy Samurai nổi tiếng. Đặc biệt hơn, cậu còn làm quen với Luke, người sở hữu một khu nhà kho dành riêng cho các vũ công vô gia cư, càng khiến đam mê của Moose trỗi dậy. Tại đây, họ ăn cùng nhau, tập cùng nhau và thi đấu cùng nhau. Câu chuyện thứ hai kể về mối quan hệ giữa Luke và Natalie, một khuôn mặt mới trong thế giới Hip hop đường phố tại New York. Đích đến của họ chính là cuộc thi World Jam lần thứ nhất. Ai sẽ là người chiến thắng trong cuộc thi này?</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rick Malambri","avatar":""},{"name":"Adam Sevani","avatar":""},{"name":"Joe Slaughter","avatar":""},{"name":"Sharni Vinson","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Keith Stallworth","avatar":""},{"name":"Kendra Andrews","avatar":""},{"name":"Stephen ''tWitch'' Boss","avatar":""},{"name":"Martín Lombard","avatar":""},{"name":"Facundo Lombard","avatar":""},{"name":"Oren Michaeli","avatar":""},{"name":"Daniel ''Cloud'' Campos","avatar":""},{"name":"Aja George","avatar":""},{"name":"Straphanio ''Shonn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324476);
