INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-ngoai-hanh-tinh', 'Ánh Sáng Ngoài Hành Tinh', 'Skyline', 'https://phimimg.com/upload/vod/20231029-1/2887c0b14d504f206048e33c6f6e8303.jpg', 'https://phimimg.com/upload/vod/20231029-1/96ade3d5378c28a9a4b7943738ea591b.jpg', '<p>Khi những ánh sáng kỳ lạ chiếu xuống thành phố Los Angeles, mọi người bị hút ra ngoài như những con thiêu thân đến ngọn lửa nơi một thế lực ngoài Trái đất đe dọa nuốt chửng toàn bộ dân số loài người khỏi bề mặt Trái đất. Giờ đây, nhóm người sống sót phải chiến đấu để giành lấy mạng sống khi thế giới xung quanh họ dần sáng tỏ.</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Balfour","avatar":""},{"name":"Scottie Thompson","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Donald Faison","avatar":""},{"name":"Brittany Daniel","avatar":""},{"name":"Crystal Reed","avatar":""},{"name":"Neil Hopkins","avatar":""},{"name":"J. Paul Boehmer","avatar":""},{"name":"Tanya Newbould","avatar":""},{"name":"Pam Levin","avatar":""},{"name":"Phet Mahathongdy","avatar":""},{"name":"Byron McIntyre","avatar":""},{"name":"Robin Gammell","avatar":""},{"name":"Jackie Marin","avatar":""},{"name":"Tony Black","avatar":""},{"name":"Eliza Till","avatar":""},{"name":"James Huang","avatar":""},{"name":"Erik R","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324476);
