INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-dung-lai', 'Không Thể Dừng Lại', 'Unstoppable', 'https://phimimg.com/upload/vod/20231030-1/5bdfee51321192a4c9be8dcab508c44e.jpg', 'https://phimimg.com/upload/vod/20231030-1/b8d7b98401af58cbfea5189c7f5f263f.jpg', '<p>Chỉ vì sơ xuất của nhân viên xe lửa mà chuyến tàu mang số hiệu 777 bỗng trở thành nỗi kinh hoàng cho người dân vùng Pensylvania. Con tàu không người lái, chứa đầy chất hóa học phóng xuyên qua các thị trấn với một tốc độ chóng mặt. Mọi biện pháp đưa ra nhằm ngăn chặn con quái vật 777 đều không thành công. Chuyến tàu giống như quả tên lửa hạng nặng đang nhắm thẳng vào khu đông dân cư. Hi vọng duy nhất để dừng con tàu được đặt lên đôi vai của Frank (Denzel Washington), một nhân viên sắp nghỉ hưu sớm sau hơn 28 năm làm việc tận tụy cùng anh chàng mới vào nghề Will (Chris Pine).</p>', 'Full', 1, 'single', 'completed', 12, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Jessy Schram","avatar":""},{"name":"Elizabeth Mathis","avatar":""},{"name":"Meagan Tandy","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Andy Umberger","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Dylan Bruce","avatar":""},{"name":"Jeff Hochendoner","avatar":""},{"name":"Ryan Ahern","avatar":""},{"name":"Chri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324476);
