INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arthur-3-dai-chien-hai-the-gioi', 'Arthur 3: Đại Chiến Hai Thế Giới', 'Arthur 3: The War of the Two Worlds', 'https://phimimg.com/upload/vod/20231030-1/540ff03b896aba5968e9db6d9fb7d1a1.jpg', 'https://phimimg.com/upload/vod/20231030-1/683fdbdba6defbf9a363da3525a90c2e.jpg', '<p>Maltazard, Evil M, hiện cao 7 feet và tiến hóa giữa loài người, gây ra nỗi kinh hoàng ở bất cứ nơi nào hắn đi qua. Mục tiêu của anh rất đơn giản: thành lập một đội quân tay sai khổng lồ và thống trị vũ trụ. Trong khi đó, Arthur vẫn là một Minimoy, và do đó anh ấy đang ở trong tình trạng không thể chống đỡ được. Với sự giúp đỡ của Selenia và Betameche, anh ta nảy ra một kế hoạch để lấy lại kích thước bình thường của mình: tất cả những gì họ phải làm là đột nhập vào nhà Arthur thông qua hệ thống đường ống, bắt một chuyến tàu điện từ phòng ngủ của anh ta đến phòng làm việc của ông nội và tìm một loại thuốc tiên. sẽ làm cho anh ta phát triển trở lại kích thước con người. Nghe có vẻ đơn giản nếu không có Darkos, con trai riêng của Maltazard, đang bám đuôi họ.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Mia Farrow","avatar":""},{"name":"Robert Stanton","avatar":""},{"name":"Penny Balfour","avatar":""},{"name":"David Gasman","avatar":""},{"name":"Antony Hickling","avatar":""},{"name":"Dashiell Eaves","avatar":""},{"name":"Joseph Rezwin","avatar":""},{"name":"Cooper Daniels","avatar":""},{"name":"Ron Crawford","avatar":""},{"name":"Stuart Rudin","avatar":""},{"name":"Steve Routman","avatar":""},{"name":"Peter Hudson","avatar":""},{"name":"Lou Reed","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Iggy Pop","avatar":""},{"name":"Mike Powers","avatar":""},{"name":"James A. Baf","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324476);
