INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-san-ban-3', 'Mùa Săn Bắn 3', 'Open Season 3', 'https://phimimg.com/upload/vod/20231030-1/1cfb1a51cfc38d040306ec542f44b739.jpg', 'https://phimimg.com/upload/vod/20231030-1/b8a3a88499426f66146689b6a55aa640.jpg', '<p>Boog, Elliot và những người bạn trong rừng của họ trở lại với một cuộc phiêu lưu hoàn toàn mới, lần này là ở Big Top Circus! Bộ phim hài bắt đầu khi những người bạn của Boog chọn nghĩa vụ gia đình của họ trong chuyến đi hàng năm của anh chàng, và Boog thất vọng quyết định thực hiện một chuyến đi của riêng mình, điều này dẫn anh ta đến ngay giữa vòng xiếc...theo nghĩa đen. Khi anh đổi chỗ với một anh chàng hoa râm có vẻ ngoài quỷ dị giống rạp xiếc và phải lòng một thành viên quyến rũ của đoàn kịch người Nga, anh sẽ nhận ra rằng có lẽ rốt cuộc bạn không cần phải lựa chọn giữa gia đình và tình bạn.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew J. Munn","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Maddie Taylor","avatar":""},{"name":"Karley Scott Collins","avatar":""},{"name":"Ciara Bravo","avatar":""},{"name":"Dana Snyder","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"Sean Mullen","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"André Sogliuzzo","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Harrison Fahn","avatar":""},{"name":"Melissa Sturm","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Georgia Engel","avatar":""},{"name":"Fred Stolle","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh",