INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi', 'Người Sói', 'The Wolfman', 'https://phimimg.com/upload/vod/20231026-1/6ab6416462c350d41b195903ce83aada.jpg', 'https://phimimg.com/upload/vod/20231026-1/85cc55c7446f1cf23171b8ec36175e78.jpg', '<p>Lawrence Talbot, một người đàn ông Mỹ trong chuyến viếng thăm London thời Victoria để đền bù với người cha ghẻ lạnh của mình, đã bị một người sói cắn và sau khi biến hình dưới ánh trăng, khiến anh ta thèm ăn thịt dã man.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benicio del Toro","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Art Malik","avatar":""},{"name":"Antony Sher","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Cristina Contes","avatar":""},{"name":"David Sterne","avatar":""},{"name":"Elizabeth Croft","avatar":""},{"name":"Simon Merrells","avatar":""},{"name":"Asa Butterfield","avatar":""},{"name":"Olga Fedori","avatar":""},{"name":"Lorraine Hilton","avatar":""},{"name":"John Owens","avatar":""},{"name":"Gemma Whel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324476);
