INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiet-khi-su-cuoi-cung', 'Tiết Khí Sư Cuối Cùng', 'The Last Airbender', 'https://phimimg.com/upload/vod/20231026-1/9b94dc785606a7cbc631ae6abd800dfd.jpg', 'https://phimimg.com/upload/vod/20231026-1/1bf6f05fed6cfe538a89c1b20953da05.jpg', '<p>Câu chuyện kể về cuộc phiêu lưu của Aang, một người kế thừa trẻ tuổi của một dòng dõi lâu đời các Thế thần, người phải gạt bỏ tuổi thơ của mình sang một bên và ngăn chặn Hỏa Quốc bắt các quốc gia Nước, Đất và Không khí làm nô lệ.</p>', 'Full', 1, 'single', 'completed', 21, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Ringer","avatar":""},{"name":"Dev Patel","avatar":""},{"name":"Nicola Peltz Beckham","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Seychelle Gabriel","avatar":""},{"name":"Katharine Houghton","avatar":""},{"name":"Francis Guinan","avatar":""},{"name":"Damon Gupton","avatar":""},{"name":"Summer Bishil","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Jessica Jade Andres","avatar":""},{"name":"John D''Alonzo","avatar":""},{"name":"Keong Sim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324476);
