INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tu-than-2', 'Cuộc Đua Tử Thần 2', 'Death Race 2', 'https://phimimg.com/upload/vod/20231026-1/496195aa8143a6abbf222baa959f78f4.jpg', 'https://phimimg.com/upload/vod/20231026-1/1461e741ce4ec73ff40d0a523868f244.jpg', '<p>Cuộc Đua Tử Thần 2 là phần tiếp nối sau bộ phim cùng tên đã thành công năm 2008. Bộ phim cho chúng ta thấy thế giới trong một tương lai gần với sự sụp đổ của nền kinh tế, bạo lực xã hội đầy rẫy. Để có thể kiểm soát được đám tội phạm này, một nhà tù cực lớn và riêng biệt đã được xây dựng nhằm mục đích đó.</p>', 'Full', 1, 'single', 'completed', 21, 2010, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Luke Goss","avatar":""},{"name":"Lauren Cohan","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Tanit Phoenix","avatar":""},{"name":"Robin Shou","avatar":""},{"name":"Joe Vaz","avatar":""},{"name":"Frederick Koehler","avatar":""},{"name":"Sean Higgs","avatar":""},{"name":"Patrick Lyster","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Hennie Bosman","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Danny Keogh","avatar":""},{"name":"Ryan Kruger","avatar":""},{"name":"Robyn LeAnn Scott","avatar":""},{"name":"Alex Lorre","avatar":""},{"name":"Stephen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324476);
