INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cia-tai-xuat', 'CIA Tái Xuất', 'RED', 'https://phimimg.com/upload/vod/20231026-1/18f1677aa2bd68b8a37653bdd9fc6e45.jpg', 'https://phimimg.com/upload/vod/20231026-1/c4e5ea5a731ba441e9e4ea5d8a65e802.jpg', '<p>Frank (Bruce Willis), Joe (Morgan Freeman), Marvin (John Malkovich) và Victoria (Helen Mirren) từng là những đặc vụ hàng đầu của Cục tình báo trung ương Hoa Kỳ. Nhưng trong quá trình hoạt động, họ nắm giữ một vài bí mật khiến cả bốn trở thành mục tiêu truy sát của CIA. Không còn cách nào khác, họ phải tập hợp nhau lại, sử dụng những kinh nghiệm, kỹ năng siêu hạng để chống lại kẻ thù và đột nhập vào trụ sở chính của CIA để điều tra rõ nguyên nhân. Đây cũng là con đường sống sót duy nhất mà họ phải lựa chọn.</p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Rebecca Pidgeon","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"James Remar","avatar":""},{"name":"Ernest Borgnine","avatar":""},{"name":"Heidi von Palleske","avatar":""},{"name":"Jefferson Brown","avatar":""},{"name":"Chris Owens","avatar":""},{"name":"Jaqueline Fleming","avatar":""},{"name":"Ra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f697