INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cui-bap', 'Anh Hùng Cùi Bắp', 'Kick-Ass', 'https://phimimg.com/upload/vod/20231025-1/98a01f64570dd849399776c01a000b56.jpg', 'https://phimimg.com/upload/vod/20231025-1/7f4f888d3e14da2959db8815eb19d392.jpg', '<p>Kick-Ass là một bộ phim hài hành động có chủ đề về siêu anh hùng dựa trên truyện tranh cùng tên của Mark Millar và John Romita. Nội dung của Kick-Ass xoay quanh Dave Lizewski, một học sinh trung học vì quá mê mệt truyện tranh nên đã quyết định trở thành một… siêu anh hùng, dù cậu chẳng có khả năng siêu nhiên nào. Trên con đường “trừ gian diệt ác”, Dave vô tình chạm trán Big Daddy, một kẻ vì mục đích “thực thi công lý” đã huấn luyện cô con gái mới 11 tuổi của mình - Hit Girl - trở thành một “cô gái hành động” để trừng trị một tên trùm buôn bán ma túy.</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Lyndsy Fonseca","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Deborah Twiss","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Omari Hardwick","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Garrett M. Brown","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Sophie Wu","avatar":""},{"name":"Stu ''Large''","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324476);
