INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-tap-su', 'Phù Thủy Tập Sự', 'The Sorcerer''s Apprentice', 'https://phimimg.com/upload/vod/20231024-1/691035f4699785d00250230ba3c57ef4.jpg', 'https://phimimg.com/upload/vod/20231024-1/2a3141e5dfa7935d0b76992265771bac.jpg', '<p>Balthazar Blake là một phù thủy bậc thầy ở Manhattan thời hiện đại đang cố gắng bảo vệ thành phố khỏi kẻ thù không đội trời chung của mình, Maxim Horvath. Balthazar không thể làm điều đó một mình, vì vậy anh ta tuyển dụng Dave Stutler, một anh chàng có vẻ bình thường nhưng bộc lộ tiềm năng tiềm ẩn, làm người bảo trợ bất đắc dĩ của mình. Thầy phù thủy cho người đồng phạm bất đắc dĩ của anh ta một khóa học cấp tốc về nghệ thuật và khoa học phép thuật, và cùng nhau, những điều khó tin này các đối tác làm việc để ngăn chặn thế lực bóng tối.</p>', 'Full', 1, 'single', 'completed', 11, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Omar Benson Miller","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Jake Cherry","avatar":""},{"name":"James A. Stephens","avatar":""},{"name":"Gregory Woo","avatar":""},{"name":"Wai Ching Ho","avatar":""},{"name":"Jason R. Moore","avatar":""},{"name":"Robert Capron","avatar":""},{"name":"Peyton List","avatar":""},{"name":"Sándor Técsy","avatar":""},{"name":"Marika Daciuk","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2cc