INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-hanh-dong', 'Biệt Đội Hành Động', 'The A-Team', 'https://phimimg.com/upload/vod/20231024-1/bbd8c66e788d5e2589553567418618eb.jpg', 'https://phimimg.com/upload/vod/20231024-1/e547ce9a90fb9ccd66ee37ec3b2f429f.jpg', '<p>Bộ phim kể về biệt đội đặc biệt gồm bốn người lính siêu hạng: thủ lĩnh Hannibal, trung úy Baracus, Quinton Jackson và viên phi công Murdock. Sau 8 năm sát cánh bên nhau với hơn 80 nhiệm vụ lớn nhỏ tại nhiều chiến trường trên thế giới, biệt đội bất ngờ bị CIA bắt giữ về những tội lỗi mà họ không hề phạm phải. Giờ đây, bốn người chỉ còn cách thoát thân để chứng minh sự trong sạch của mình và tìm ra kẻ thù đứng đằng sau âm mưu thâm độc này...</p>', 'Full', 1, 'single', 'completed', 13, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Quinton Jackson","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Gerald McRaney","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Omari Hardwick","avatar":""},{"name":"Maury Sterling","avatar":""},{"name":"Terry Chen","avatar":""},{"name":"C. Ernst Harth","avatar":""},{"name":"Neil Schell","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Alex Madison","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"Jacob Blair","avatar":""},{"name":"Rad Dal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự"