INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-ao-giac-ke-thua', 'Trò Chơi Ảo Giác: Kế Thừa', 'TRON: Legacy', 'https://phimimg.com/upload/vod/20231022-1/059059c94572a9239f6772ec94ea4eb0.jpg', 'https://phimimg.com/upload/vod/20231022-1/062a2ce016f9aa27ee34263eeafdc798.jpg', '<p>Bối cảnh xảy ra vào 20 năm sau khi Kevin Flynn - người sáng lập ra công ty trò chơi Encom - mất tích. Con trai của ông - Sam Flynn - nay đã trưởng thành và luôn băn khoăn về sự biến mất kỳ lạ của cha. Một tin nhắn đã lôi kéo Sam tới khu trò chơi đã bị bỏ hoang nhiều năm. Tại đây, anh phát hiện ra một lối đi bí mật xuống phòng làm việc kín của cha. Khi khởi động hệ thống máy tính, Sam tức thời bị dịch chuyển tới Mạng lưới - nơi cha anh đã bị mắc kẹt trong 20 năm qua. Sam dấn thân vào hành trình tìm lại cha trong một môi trường vũ trụ ảo và phải tham gia trò chơi đấu sĩ ác liệt.&nbsp; Cùng với sự trợ giúp trung thành của nhân vật Quorra, cuộc phiêu lưu nghẹt thở của 2 cha con nhà Flynn xuyên khắp thế giới ảo công nghệ đặc biệt cao đã bắt đầu với những nguy hiểm mà chính họ cũng không ngờ tới.</p>', 'Full', 1, 'single', 'completed', 14, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Bruce Boxleitner","avatar":""},{"name":"James Frain","avatar":""},{"name":"Beau Garrett","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Serinda Swan","avatar":""},{"name":"Yaya DaCosta","avatar":""},{"name":"Elizabeth Mathis","avatar":""},{"name":"Kis Yurij","avatar":""},{"name":"Conrad Coates","avatar":""},{"name":"Ron Selmour","avatar":""},{"name":"Dan Joffre","avatar":""},{"name":"Darren Dolynski","avatar":""},{"name":"Kofi Yiadom","avatar":""},{"name":"Steven Lisberger","avatar":""},{"name":"Donne","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324476);
