INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-narnia-hanh-trinh-tren-tau-dawn-treader', 'Biên Niên Sử Narnia: Hành Trình Trên Tàu Dawn Treader', 'The Chronicles of Narnia: The Voyage of the Dawn Treader', 'https://phimimg.com/upload/vod/20231022-1/ca202ae8f9ecba7684033fa58dca5e0e.jpg', 'https://phimimg.com/upload/vod/20231022-1/0342e9fbaa1b646f02764a50af7df025.jpg', '<p>Số phận của The Chronicles of Narnia phiên bản điện ảnh cũng long đong, ly kỳ không kém gì cuộc phiêu lưu tại vùng đất huyền bí Narnia của bốn anh em nhà Pevensie. Sau khi thực hiện hai phần đầu (The Lion, the Witch and the Wardrobe và Prince Caspian), hãng Walt Disney bỗng nhiên từ bỏ đứa con cưng của mình. Dự án chuyển thể bộ tiểu thuyết thần thoại nổi tiếng của nhà văn C.S Lewis được “chuyển giao” cho hãng 20th Century Fox. The Voyage of the Dawn Treader (Hành trình trên tàu Dawn Treader) là tập thứ 3 trong Biên niên sử Narnia được dựng thành phim và cũng là tập đầu tiên do hãng 20th Century Fox (đồng) sản xuất và phát hành. Số phận của series The Chronicles of Narnia cũng phụ thuộc rất nhiều vào doanh thu phòng vé của The Voyage of the Dawn Treader. Nếu ăn khách, ...</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Georgie Henley","avatar":""},{"name":"Skandar Keynes","avatar":""},{"name":"Ben Barnes","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Anna Popplewell","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Laura Brent","avatar":""},{"name":"Gary Sweet","avatar":""},{"name":"Terry Norris","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Bille Brown","avatar":""},{"name":"Colin Moody","avatar":""},{"name":"Shane Rangi","avatar":""},{"name":"Arthur Angel","avatar":""},{"name":"Arabella Morton","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324476);
