INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-giua-cac-vi-than', 'Cuộc Chiến Giữa Các Vị Thần', 'Clash of the Titans', 'https://phimimg.com/upload/vod/20231023-1/1dd96a418e9aea73024168de3493b677.jpg', 'https://phimimg.com/upload/vod/20231023-1/55f975ae009d9365a62e2c6ad11b1d6c.jpg', '<p>Phim là phiên bản làm lại từ một bộ phim thần thoại Hy Lạp cùng tên được thực hiện năm 1981. Chuyện xoay quanh người anh hùng Perseus, một người bị thần Hades (thần cai quản địa ngục và là một trong những người anh em của thần Zeus) hãm hại cả gia đình, trong đó có cả công chúa Andromeda, người anh yêu. Không còn gì để mất, Perseus tình nguyện gánh vác một nhiệm vụ nguy hiểm: đánh bại thần Hades trước khi hắn cướp được quyền lực từ thần Zeus và biến trái đất thành địa ngục.&nbsp; Dẫn đầu một nhóm chiến binh, Perseus dấn thân vào một hành trình nguy hiểm, đi sâu vào thế giới bị cấm để chiến đấu với quỷ dữ và những con thú đáng sợ. Perseus chỉ sống sót nếu anh vượt qua các chướng ngại vật ở phía trước, chấp nhận quyền lực của mình như giống như một vị thần và tạo nên số phận của chính mình.</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Alexa Davalos","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Polly Walker","avatar":""},{"name":"Ashraf Barhom","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Hans Matheson","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Alexander Siddig","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324476);
