INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kip-luyen-rong', 'Bí Kíp Luyện Rồng', 'How to Train Your Dragon', 'https://phimimg.com/upload/vod/20231019-1/c815b55f2c31e82b9a7557a095490a92.jpg', 'https://phimimg.com/upload/vod/20231019-1/8841cab97904f0f76bd3bf665fb317a8.jpg', '<p>Thiếu niên nhút nhát Hiccup phải chứng minh với bố và làng của mình rằng cậu vẫn có thể là chiến binh Viking – ngay cả khi cậu muốn kết bạn với rồng hơn là giết rồng.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jay Baruchel","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Ashley Jensen","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Philip McGrade","avatar":""},{"name":"Kieron Elliott","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324476);
