INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('percy-jackson-ke-cap-tia-chop', 'Percy Jackson: Kẻ Cắp Tia Chớp', 'Percy Jackson & the Olympians: The Lightning Thief', 'https://phimimg.com/upload/vod/20231019-1/12f63d956bb6f12c1074fcb0fae12aeb.jpg', 'https://phimimg.com/upload/vod/20231019-1/577089d02f4bd8ee8e321286771abee6.jpg', '<p>Percy Jackson luôn gặp phải những rắc rối ở trường trung học nhưng hóa ra đó chỉ là những chuyện đơn giản của tuổi dậy thì. Còn thử thách mà cậu sẽ gặp phải chính là việc Percy khám phá ra rằng cha đẻ mình là Poseidon, vị thần biển cả, và điều đó có nghĩa rằng Percy là một á thần. Cùng lúc đó, thần Dớt, vua của các vị thần, đã buộc tội Percy ăn cắp vũ khí tối thượng của ông - tia sét quyền năng. Và bây giờ, tính mạng của Percy rơi vào vòng xoáy nguy hiểm, và cậu phải chuẩn bị cho một cuộc phiêu lưu lớn, với những giông bão hiểm nguy đang chờ dịp trút xuống thế giới…</p>', 'Full', 1, 'single', 'completed', 17, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Melina Kanakaredes","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Charlie Gallant","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Mari","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324476);
