INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-trom-the-ky', 'Vụ Trộm Thế Kỷ', 'The Town', 'https://phimimg.com/upload/vod/20231021-1/67a0db51976f72df2448638ed260516f.jpg', 'https://phimimg.com/upload/vod/20231021-1/f9e73c0384dae77b039cbfdad3eae23b.jpg', '<p>Bộ phim được chuyển thể từ cuốn tiểu thuyết Chuck Hogan &quot;s Prince of Thieves . Ngoài ra bộ phim còn có sự góp mặt của dàn diễn viên gồm: Rebecca Hall, Jon Hamm, Jeremy Renner, Blake Lively, Titus Welliver, Pete Postlethwaite và Chris Cooper họ vào vai những người theo dõi một nhóm những tên cướp ngân hàng ở Boston và đặt ra mục tiêu cuối cùng bằng cách cướp lấy Fenway Park .</p>', 'Full', 1, 'single', 'completed', 16, 2010, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Slaine","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Owen Burke","avatar":""},{"name":"Titus Welliver","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Dennis McLaughlin","avatar":""},{"name":"Corena Chase","avatar":""},{"name":"Brian Scannell","avatar":""},{"name":"Kerri Dunbar","avatar":""},{"name":"Tony V.","avatar":""},{"name":"Isaac Bordoy","avatar":""},{"name":"Michael Yebba","avatar":""},{"name":"Daniel Woods","avatar":""},{"name":"Jimm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324476);
