INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sat-2', 'Người Sắt 2', 'Iron Man 2', 'https://phimimg.com/upload/vod/20231018-1/7ed100595fc14b75c63b540d27405bda.jpg', 'https://phimimg.com/upload/vod/20231018-1/7cfe6b549fe9f94928b8bdc0016ac82f.jpg', '<p>Tony Stark tự hé lộ thân phận Người sắt của mình cho công chúng và chìm trong hào quang danh vọng. Một kẻ lạ mặt xuất hiện tấn công anh trên đường đua Monte Carlo. Tony bị hiện tượng nhiễm trùng máu đe dọa mạng sống, còn tên sát thủ kia bắt tay với đối thủ của tập đoàn Stark hòng thôn tính Tony.&nbsp; Phần 2 của Người sắt là lần đầu tiên trợ thủ Warmachine xuất hiện. Phim cũng tiết lộ những bí mật về cha của Tony, Howard Stark, trước khi dẫn dắt câu chuyện sang nhân vật Captain America, đồng đội tương lai của Người sắt tại tổ chức SHIELD.</p>', 'Full', 1, 'single', 'completed', 15, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Garry Shandling","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Christiane Amanpour","avatar":""},{"name":"Philippe Bergeron","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324476);
