INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-toc-may', 'Người Đẹp Tóc Mây', 'Tangled', 'https://phimimg.com/upload/vod/20231018-1/d802a66625dd5d5ec58a9cfbc9699393.jpg', 'https://phimimg.com/upload/vod/20231018-1/86994e9c8fbe8a6b841e9b797e368111.jpg', '<p>Rapunzel - nàng công chúa có mái tóc dài thần kì bị nhốt suốt 18 năm trời trên ngọn tháp cao chót vót bởi một mụ phù thủy. Mọi chuyện trở nên kịch tính khi tên trộm tinh quái và quyến rũ nhất vương quốc - Flynn Rider - trong cuộc chạy trốn khỏi binh lính triều đình, tình cờ rơi vào ngọn tháp của Rapunzel. Từ đây cô công chúa thơ dại đã bắt đầu chuyến phiêu lưu trốn chạy khỏi ngọn tháp u tối để tìm lại cuộc sống đích thực của chính mình.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mandy Moore","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Donna Murphy","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Richard Kiel","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Paul F. Tompkins","avatar":""},{"name":"Delaney Rose Stein","avatar":""},{"name":"Nathan Greno","avatar":""},{"name":"Byron Howard","avatar":""},{"name":"Tim Mertens","avatar":""},{"name":"Michael Bell","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Susanne Blakeslee","avatar":""},{"name":"Roy Conli","avatar":""},{"name":"David Cow","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324476);
