INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hau', 'Người Hầu', 'The Servant', 'https://phimimg.com/upload/vod/20230926-1/1ff227b3a69f7322e94c9abc5e0b7aaf.jpg', 'https://phimimg.com/upload/vod/20230926-1/2a3a348c9b93daea72b34ce47ccc9a06.jpg', '<p>Bộ phim dựa trên câu chuyện nổi tiếng về nàng Chun-hyang, về đôi uyên ương trẻ thời Joseon, do hai diễn viên nổi tiếng Kim Joo-hyuk và Ryu Seung-beom thủ diễn vai chính. Trước đây, vốn đã có nhiều đạo diễn làm phim về câu chuyện truyền kỳ này của văn hóa, lịch sử Hàn Quốc. Song, đến tay đạo diễn Kim Dae-woo lần này,&nbsp;</p>', 'Full', 1, 'single', 'completed', 20, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Joo-hyuk","avatar":""},{"name":"Cho Yeo-jeong","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Ryu Hyun-kyung","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Gong Hyung-jin","avatar":""},{"name":"Lee Min-woong","avatar":""},{"name":"Sim San","avatar":""},{"name":"Jo Han-chul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324476);
