INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-o-rome', 'Căn Phòng Ở Rome', 'Room in Rome', 'https://phimimg.com/upload/vod/20230925-1/e1cffd27631628b38a7503f2194d8271.jpg', 'https://phimimg.com/upload/vod/20230925-1/58ad323ca578e3b691c61aed301a015c.jpg', '<p>Nội dung của Phim xoay quanh chuyện tình cảm của một người phụ nữ trẻ tuổi người Nga tên là Natasha với một người con gái bí ẩn người bản địa tên là Alba khi cô du dịch sang Rome. Hai người thường xuyên gặp nhau trong một căn phòng tại một khách sạn mà ban đầu nó chỉ như một tình bạn với chiều hướng phát triển khi cả 2 rất hợp nhau trong mọi thứ. Nhưng không chỉ dừng lại ở đó, họ cảm thấy muốn biết về nhau một cách sâu sắc hơn mặc dù Natasha sắp kết hôn.Mọi thứ lên đến đỉnh điểm khi cả 2 bắt đầu khám phá nhau cũng như khám phá chính mình, cả 2 cùng nhau suốt đêm và rồi những ngày sau đó họ tranh thủ cả những giờ giải lao trong ngày, mối quan hệ này hoàn toàn có thể làm thay đổi cuộc đời của cả 2 và liệu rằng nó sẽ kéo dài trong bao lâu.</p>', 'Full', 1, 'single', 'completed', 21, 2010, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Elena Anaya","avatar":""},{"name":"Natasha Yarovenko","avatar":""},{"name":"Enrico Lo Verso","avatar":""},{"name":"Najwa Nimri","avatar":""},{"name":"Ander Malles","avatar":""},{"name":"Laura Meizoso","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324476);
