INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-vo-danh', 'Sát Thủ Vô Danh', 'The Man from Nowhere', 'https://phimimg.com/upload/vod/20230921-1/7680e8fefc6dd7611277ab304feae080.jpg', 'https://phimimg.com/upload/vod/20230921-1/6ab3857da9ec62ee759db75398e81137.jpg', '<p><span style="font-family: ">Sau một bi kịch, sát thủ chuyên nghiệp Cha Tae Shik rửa tay gác kiếm, lui về ở ẩn. Người duy nhất trò chuyện với anh là cô bé hàng xóm So Mi. Tuy nhiên, mẹ của So Mi lại dính dáng đến 1 đường dây buôn ma túy, cô bé bị bắt cóc. Cha Tae Shik buộc phải lao vào nguy hiểm giải cứu So Mi. Nhưng liệu Cha Tae Shik có cứu được cô bé? Những nguy hiểm nào đang chờ đợi anh?</span></p>', 'Full', 1, 'single', 'completed', 19, 2010, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Won Bin","avatar":""},{"name":"Kim Sae-ron","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Thanayong Wongtrakul","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Kim Hyo-seo","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Song Young-chang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324476);
