INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-sach-cua-eli', 'Cuốn Sách Của Eli', 'The Book of Eli', 'https://phimimg.com/upload/vod/20230917-1/15924ee81379a690c1717cf093905809.jpg', 'https://phimimg.com/upload/vod/20230917-1/25baa4f2c7a0f397c8680f8378730573.jpg', '<p><span style="font-family: ">Bộ phim The Book of Eli (Cuốn Sách Của Eli) (2010) là câu chuyện về một người đàn ông đơn thương độc mã trong cuộc chiến của mình, đi khắp nước Mỹ để bảo vệ một quyển sách thần thánh cất giữ bí mật cứu cả loài người.</span></p>', 'Full', 1, 'single', 'completed', 27, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Jennifer Beals","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Tom Waits","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Evan Jones","avatar":""},{"name":"Joe Pingue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324476);
