INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuon-sach-cua-eli', 'Cuốn Sách Của Eli', 'The Book of Eli', 'cuốn sách của eli the book of eli denzel washington gary oldman mila kunis ray stevenson jennifer beals michael gambon tom waits frances de la tour evan jones joe pingue ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-tinh-noi-chien-tran', 'Thư Tình Nơi Chiến Trận', 'Dear John', 'https://phimimg.com/upload/vod/20230915-1/1bfd410832b4a2bf85bfd78fb7376190.jpg', 'https://phimimg.com/upload/vod/20230915-1/71d5dee3b71ecac3a398e42bd08e4aca.jpg', '<p><span style="font-family: ">Bộ phim nói về chuyện tình đầy nước mắt của John và Savannah. Sau khi rời khỏi quân đội về thăm nhà, John đã gặp Savannah, một cô sinh viên đại học tuyệt đẹp nhưng lại cực kỳ bảo thủ. Sau một lần lặn sâu xuống biển để tìm chiếc ví đầm cô vô ý đánh rơi, John và Savannah đã nhanh chóng trở thành bạn bè. Sau đó, họ dần nhận ra cả hai đã trở nên thân thiết đến mức không thể thiếu nhau. Cuối cùng, John và Savannah quyết định lập kế hoạch kết hôn. Tuy nhiên sau sự kiện 09.11, John phải trở lại quân ngũ và Savannah thường viết cho anh những lá thư bắt đầu bằng từ “Dear John” (John thân mến). Nhận được những bức thư của cô, John rất phấn khích và nghĩ đến 1 ngày nào đó có thể trở về nhà bên cạnh Savannah. Thế nhưng, thời gian và khoảng cách luôn luôn là thách thức đối với những lới hứa hẹn. Vào một ngày kia, John vẫn nhận được một lá thư bắt đầu bằng từ “Dear John”, thế nhưng kết thúc lại là từ “Good Bye”</span></p>', 'Full', 1, 'single', 'completed', 30, 2010, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Henry Thomas","avatar":""},{"name":"D.J. Cotrona","avatar":""},{"name":"Cullen Moss","avatar":""},{"name":"Gavin McCulley","avatar":""},{"name":"Jose Lucena Jr.","avatar":""},{"name":"Keith D. Robinson","avatar":""},{"name":"Scott Porter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324476);
