INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-nguyet-vi-thanh', 'Thập Nguyệt Vi Thành', 'Bodyguards and Assassins', 'https://phimimg.com/uploads/movies/20260710/thap-nguyet-vi-thanh-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/thap-nguyet-vi-thanh-poster.webp', '<p>Chuyện về Tôn Trung Sơn đến Hồng Kông quyên góp cho phong trào khởi nghĩa. Những người thương nhân nghĩa sĩ đảm nhận trách nhiệm tiếp đãi Tôn Trung Sơn biết được chính phủ Mãn Thanh đã phái người đến ám sát Tôn Trung Sơn. Nên đã bỏ một số tiền lớn để mời những người có võ nghệ, thân thủ cao cường để bảo vệ Tôn Trung Sơn. Và sau cùng đã thành công hộ tống Tôn Trung Sơn về đến Quảng Châu...</p>', 'Full', 1, 'single', 'completed', 50, 2009, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Wang Xueqi","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Edison Wang","avatar":""},{"name":"Leon Lai Ming","avatar":""},{"name":"Mengke Bateer","avatar":""},{"name":"Chris Lee Yuchun","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Zhou Yun","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Zhang Hanyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Guarda Costas e Assasinos","Bodyguards & Assassins","5 พยัคฆ์พิทักษ์ซุนยัดเซ็น","Bodyguards and Assassins","8인 최후의 결사단","Οι φύλακες της επανάστασης","Oi fylakes tis epanastasis","Testőrök és gyilkosok","Телохранители и убийцы","Suikastçılar Fedailere Karşı","Thập Nguyệt Vi Thành","Guardaespaldas y asesinos","Strażnicy i zabójcy","Sap yueh wai sing","十月围城","Dark October","十月圍城"]', 1784690324476);
