INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thap-nguyet-vi-thanh', 'Thập Nguyệt Vi Thành', 'Bodyguards and Assassins', 'thập nguyệt vi thành bodyguards and assassins wang xueqi tony leung ka-fai hu jun donnie yen nicholas tse ting-fung edison wang leon lai ming mengke bateer chris lee yuchun simon yam fan bingbing zhou yun eric tsang chi-wai jacky cheung hok-yau zhang hanyu guarda costas e assasinos bodyguards & assassins 5 พยัคฆ์พิทักษ์ซุนยัดเซ็น bodyguards and assassins 8인 최후의 결사단 οι φύλακες της επανάστασης oi fylakes tis epanastasis testőrök és gyilkosok телохранители и убийцы suikastçılar fedailere karşı thập nguyệt vi thành guardaespaldas y asesinos strażnicy i zabójcy sap yueh wai sing 十月围城 dark october 十月圍城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-the-gioi-phan-4', 'Giải Cứu Thế Giới (Phần 4)', 'Heroes (Season 4)', 'https://phimimg.com/upload/vod/20260702-1/74dc36b1287778acd70532bb5b2e5b20.jpg', 'https://phimimg.com/upload/vod/20260702-1/8af6a9c69e1da033b85e687205189820.jpg', '<p>Những con người bình thường bỗng chốc phát hiện ra mình sở hữu những siêu năng lực phi thường. Cuộc đời của họ bắt đầu đan xen và gắn kết với nhau khi một thảm họa tàn khốc sắp xảy ra cần phải được ngăn chặn.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 31, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Quinto","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Jack Coleman","avatar":""},{"name":"Adrian Pasdar","avatar":""},{"name":"Greg Grunberg","avatar":""},{"name":"Sendhil Ramamurthy","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"James Kyson","avatar":""},{"name":"Cristine Rose","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Série Heroes","Heroes (2006)","英雄","Héroes","Heroes"]', 1784690324476);
