INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-ac-quy', 'Lời Nguyền Ác Quỷ', 'Drag Me To Hell', 'https://phimimg.com/upload/vod/20260701-1/4034ef4a38301773c1aeb085f15d7c63.jpg', 'https://phimimg.com/upload/vod/20260701-1/86a67b56cf45cf0373a8d97aae98f131.jpg', '<p>Sau khi từ chối gia hạn khoản vay để một người phụ nữ giữ lại căn nhà của mình, cuộc sống vốn dĩ đang đầy hứa hẹn của nhân viên tín dụng Christine Brown bỗng chốc đảo lộn và lao dốc một cách đáng sợ. Christine tin chắc rằng mình đã bị một người phụ nữ gốc Do-gip-si nguyền rủa, nhưng bạn trai cô lại tỏ ra hoài nghi. Niềm hy vọng duy nhất của cô lúc này đặt vào một nhà ngoại cảm — người tuyên bố có thể giúp cô hóa giải lời nguyền và ngăn không cho linh hồn cô bị kéo thẳng xuống địa ngục.</p>', 'Full', 1, 'single', 'completed', 48, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alison Lohman","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Lorna Raver","avatar":""},{"name":"Dileep Rao","avatar":""},{"name":"David Paymer","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Reggie Lee","avatar":""},{"name":"Molly Cheek","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Kevin Foster","avatar":""},{"name":"Alexis Cruz","avatar":""},{"name":"Ruth Livier","avatar":""},{"name":"Shiloh Selassie","avatar":""},{"name":"Flor de Maria Chahua","avatar":""},{"name":"Christopher Young","avatar":""},{"name":"Ricardo Molina","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Arrastrame al Infierno","Drag Me to Hell - Fahr mich zur Hölle",