INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-nguyen-ac-quy', 'Lời Nguyền Ác Quỷ', 'Drag Me To Hell', 'lời nguyền ác quỷ drag me to hell alison lohman justin long lorna raver dileep rao david paymer adriana barraza chelcie ross reggie lee molly cheek bojana novaković kevin foster alexis cruz ruth livier shiloh selassie flor de maria chahua christopher young ricardo molina arrastrame al infierno drag me to hell - fahr mich zur hölle malédiction de l''enfer llévame al infierno затягни мене до пекла jusqu''en enfer drag me to hell', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-do-phan-1', 'Phong Độ (Phần 1)', 'Hung (Season 1)', 'https://phimimg.com/upload/vod/20260630-1/94a10c2da693dfc1fa98ed964b93d801.jpg', 'https://phimimg.com/upload/vod/20260630-1/1c55506866423034f8c60b0289682437.jpg', '<p>Những thời khắc tuyệt vọng đòi hỏi những biện pháp cực đoan, và hoàn cảnh của Ray Drecker lúc này quả thực không thể bi đát hơn. Từ một huyền thoại thể thao thời trung học, giờ đây ở tuổi trung niên, anh phải chật vật với đồng lương huấn luyện viên bóng rổ, vừa ly dị vợ, vừa phải gồng gánh nuôi con thì căn nhà vốn đã xập xệ lại bất ngờ bị hỏa hoạn. Để tìm kiếm một công việc tay trái nhằm trang trải cuộc sống, Ray quyết định khai thác &quot;vốn tự có&quot; trời ban của mình như một nỗ lực cuối cùng để thay đổi số phận.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 38, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Charlie Saxton","avatar":""},{"name":"Sianoa Smit-McPhee","avatar":""},{"name":"Rebecca Creskoff","avatar":""},{"name":"Gregg Henry","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Lennie James","avatar":""},{"name":"Stephen Amell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Na velikosti záleží","Hung (Superdotado)","Hung"]', 1784690324476);
