INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-do-phan-1', 'Phong Độ (Phần 1)', 'Hung (Season 1)', 'phong độ (phần 1) hung (season 1) thomas jane jane adams charlie saxton sianoa smit-mcphee rebecca creskoff gregg henry anne heche lennie james stephen amell na velikosti záleží hung (superdotado) hung', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-dua-tin-2', 'Những Người Đưa Tin 2', 'Messengers 2: The Scarecrow', 'https://phimimg.com/upload/vod/20260618-1/e38991cd422bc5e0a3f30a579afb9a75.jpg', 'https://phimimg.com/upload/vod/20260618-1/1d09fca9ff29e7bc0251e41bd72af6ba.jpg', '<p>John Rollins, một người đàn ông của gia đình và là một nông dân, đang rơi vào cảnh kiệt quệ vì áp lực tài chính: đàn quạ dữ cùng tình trạng thiếu nước tưới đang tàn phá ráo riết ruộng ngô của anh; ngân hàng thì sắp sửa tịch thu tài sản thế chấp; anh lại chẳng còn một đồng tín dụng nào để sửa máy bơm nước hay mua hạt giống; chưa kể cuộc hôn nhân của anh đang đứng trên bờ vực khủng hoảng khi cô vợ Mary lại dành quá nhiều sự quan tâm cho người bạn Tommy. Khi John tình cờ phát hiện ra một ngăn bí mật trong kho thóc, anh tìm thấy một con bù nhìn rơm vô cùng quái dị, và cậu con trai Michael đã bắt anh phải hứa là sẽ tiêu hủy nó. Tuy nhiên, người hàng xóm Jude Weatherby đến chơi, đưa cho người vốn kiêng rượu như John một lốc bia và thuyết phục anh đem con bù nhìn ra cắm ở ruộng ngô. Ngay lập tức, cuộc đời của John thay đổi một cách chóng mặt: đàn quạ lăn đùng ra chết; máy bơm hoạt động trở lại giúp đất đai được tưới tiêu; và gã quản lý ngân hàng chịu trách nhiệm tịch thu đất của anh gặp tai nạn qua đời. Thế nhưng, John dần cảm nhận được rằng mảnh đất của mình đã bị một thế lực tà ác chiếm giữ, và nó đang đe dọa trực tiếp đến gia đình yêu thương của anh.</p>', 'Full', 1, 'single', 'completed', 35, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Norman Reedus","avatar":""},{"name":"Heather Stephens","avatar":""},{"name":"Claire Holt","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Darcy Fowers","avatar":""},{"name":"Matthew McNulty","avatar":""},{"name":"Laurence Belcher","avatar":""},{"name":"Vladimir Yossifov","avatar":""},{"name":"Todd Jensen","avatar":""},{"name":"Michael McCoy","avatar":""},{"name":"Kalina Green","avatar":""},{"name":"Erbi Ago","avatar":""},{"name":"Atanas Srebrev","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Les Messagers 2:L''épouvantail","Kliatba domu slnecnic 2: Strasiak","Messengers 2","Os Mensageiros 2: O Espantalho","Los Mensajeros 2 El Espantapajaros","Prokletí domu slunečnic 2","Los mensajeros 2","Los Mensajeros 2","The Messengers 2","Messengers 2: The Scarecrow"]', 1784690324476);
