INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-nguoi-dua-tin-2', 'Những Người Đưa Tin 2', 'Messengers 2: The Scarecrow', 'những người đưa tin 2 messengers 2: the scarecrow norman reedus heather stephens claire holt richard riehle darcy fowers matthew mcnulty laurence belcher vladimir yossifov todd jensen michael mccoy kalina green erbi ago atanas srebrev les messagers 2:l''épouvantail kliatba domu slnecnic 2: strasiak messengers 2 os mensageiros 2: o espantalho los mensajeros 2 el espantapajaros prokletí domu slunečnic 2 los mensajeros 2 los mensajeros 2 the messengers 2 messengers 2: the scarecrow', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-muon-chet-phan-1', 'Chán Muốn Chết (Phần 1)', 'Bored To Death (Season 1)', 'https://phimimg.com/upload/vod/20260615-1/2b34c42df9f5e28de2be8983ac63a7f9.jpg', 'https://phimimg.com/upload/vod/20260615-1/c3ff8b11c5f91082c529747ab2cc0d7a.jpg', '<p>Jonathan Ames, một nhà văn trẻ ở Brooklyn, đang cảm thấy hoàn toàn mất phương hướng. Anh vừa trải qua một cuộc chia tay đau đớn mà một phần nguyên nhân là do chứng nghiện rượu của mình, bản thân lại bế tắc không thể viết nổi cuốn tiểu thuyết thứ hai, và suốt ngày chìm đắm trong các cuộc chè chén với tay biên tập viên tạp chí của mình. Thay vì đối mặt với hiện thực phũ phàng, Jonathan lại trốn tránh vào những ảo tưởng của bản thân — lén lút hành nghề thám tử tư — chỉ vì anh muốn trở thành một người hùng và một người đàn ông của hành động.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 24, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Schwartzman","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Ted Danson","avatar":""},{"name":"Heather Burns","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无聊至死","凡人烦事","Смертельна нудьга","Bored to Death"]', 1784690324476);
