INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chan-muon-chet-phan-1', 'Chán Muốn Chết (Phần 1)', 'Bored To Death (Season 1)', 'chán muốn chết (phần 1) bored to death (season 1) jason schwartzman zach galifianakis ted danson heather burns 无聊至死 凡人烦事 смертельна нудьга bored to death', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-that-hiep-ngu-nghia', 'Bao Thanh Thiên: Thất Hiệp Ngũ Nghĩa', 'Justice Bao: The Seven Heroes And Five Gallants', 'https://phimimg.com/upload/vod/20260612-1/814f8c000f1baf3611d66caa646f73d6.jpg', 'https://phimimg.com/upload/vod/20260612-1/79942cb29045b8c29a891eeacb81584f.jpg', '<p>Bộ phim lấy bối cảnh Tống Nhân Tông sắc phong Bao Chửng làm phủ doãn phủ Khai Phong chấp chưởng kinh kỳ. Tú tài thi rớt Công Tôn Sách có ân tri ngộ với Bao Chửng nên đã theo bên cạnh để giúp hoạch định lưu kế sách lược. Giang hồ nghĩa sĩ nam hiệp Triển Chiêu cũng cảm động trước vị quan thương dân như con của Bao Chửng nên đã đến trợ giúp. Ngoại trừ một văn một võ bên cạnh Bao Chửng, còn có bắc hiệp Âu Dương Xuân, tiểu hiệp Ngải Hổ, Đinh Thị Song Hiệp, hắc yêu hồ Trí Hóa và hãm không đảo Ngũ Thử đều là những anh hùng hào kiệt có tiếng trừ gian diệt ác trên giang hồ. Dưới sự hiệu triệu của Triển Chiêu đã lần lượt đến ra sức tương trợ, trong lúc Bao Chửng trừ gian diệt ác, những hành động hiệp nghĩa của “Thất hiệp- Ngũ nghĩa” cũng lưu truyền trong dân gian.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 47, 2009, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Hà Gia Kính","avatar":""},{"name":"Kim Siêu Quần","avatar":""},{"name":"Phạm Hồng Hiên","avatar":""},{"name":"Giang Hồng Ân","avatar":""},{"name":"Kim Minh","avatar":""},{"name":"Vương Sa Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["包青天之七侠五义"]', 1784690324476);
