INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-6', 'Chuyện Văn Phòng (Phần 6)', 'The Office (Season 6)', 'https://phimimg.com/upload/vod/20260604-1/b583a7a05074509d81d59d62540254a5.jpg', 'https://phimimg.com/upload/vod/20260604-1/358a313788d96fc5ce3d3d9676c86fd4.jpg', '<p>Trong Phần 6, phi hành đoàn phải đối mặt với những mối tình lãng mạn, hôn nhân, vai trò làm cha mẹ, quyền sở hữu công ty mới, việc Darryl lên làm quản lý cấp trung và một ông chủ mới cuồng nhiệt.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 31, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324476);
