INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-9', 'Thị Trấn Smallville (Phần 9)', 'Smallville (Season 9)', 'https://phimimg.com/upload/vod/20250604-1/2e6954fe65d1c9d9a144746e9479b8da.jpg', 'https://phimimg.com/upload/vod/20250604-1/0215938e93cf85fbad38e1c16b6e9481.jpg', '<p>Ở mùa trước, Tess Mercer đầy mưu mô đã len lỏi khắp thị trấn, phát hiện ra thân phận thật sự của Clark và mở ra một thế giới nguy hiểm mới. Về phần Clark, anh đã chạm trán với đối thủ đáng sợ nhất của mình: Doomsday. Khi không phải chiến đấu với con quái vật đó, Clark lại bận rộn với công việc tại tòa soạn Daily Planet. Khi hình ảnh chàng phóng viên trẻ tuổi tại Daily Planet dần hình thành, thì tình cảm của Clark dành cho Lois — định mệnh đời anh — cũng ngày một lớn dần. Trong mùa chín, Clark Kent buộc phải đứng lên đối mặt với thử thách khi Zod và các thuộc hạ của hắn âm mưu giành quyền kiểm soát Trái Đất.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 17, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324476);
