INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-luu-cung-anthony-bourdain-phan-5', 'Phiêu Lưu Cùng Anthony Bourdain (Phần 5)', 'Anthony Bourdain: No Reservations (Season 5)', 'https://phimimg.com/upload/vod/20260531-1/382fda398cd611dfbfcb37fde068c1f5.jpg', 'https://phimimg.com/upload/vod/20260531-1/59c4e6260bc20404d4a1ff3c8da248f8.jpg', '<p>Chương trình phim tài liệu với người dẫn dắt là cố đầu bếp nổi tiếng thế giới Anthony Bourdain, đưa khán giả đi qua nhiều vùng đất để khám phá về cuộc sống muôn màu thông qua nét đẹp ẩm thực</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 25, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Bourdain","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Anthony Bourdain: No Reservations"]', 1784690324476);
