INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-phan-trong-chiec-mat-na-thien-than-khoa-than', 'Số Phận Trong Chiếc Mặt Nạ Thiên Thần Khỏa Thân', 'Fate In A Mask The Naked Angel', 'https://phimimg.com/upload/vod/20260518-1/be6a548a3caba190b70fa04e49fb7b26.jpg', 'https://phimimg.com/upload/vod/20260518-1/5a67a8333c83d2e767a47936ed7d66bb.jpg', '<p>Kizuki nhận dạy vẽ tại một trường học miễn phí, và mục tiêu của anh là Yoichi, một học sinh kiêm bảo vệ. Một ngày nọ, Kizuki mời Yoichi và bạn cô, Tooru, đến nhà và yêu cầu họ làm người mẫu khỏa thân. Youichi bối rối trước mong muốn quay phim cô trong một cảnh fundoshi và thủ dâm của Kizuki, nhưng anh cho Yoichi xem mặt nạ phòng độc và bộ quân phục của mình, đồng thời kể cho anh nghe về cuộc sống của mình khi đeo mặt nạ. Yoichi, không hề ghê tởm màn bắn tinh của Kizuki, bắt đầu nghĩ rằng anh muốn sống thật với giới tính của mình...</p>', 'Full', 1, 'single', 'completed', 19, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kôji Makimura","avatar":""},{"name":"Rei Ogasawara","avatar":""},{"name":"Yasunari Kubota","avatar":""},{"name":"Kaguya","avatar":""},{"name":"Kyôsuke Sasaki","avatar":""},{"name":"Shigeru Asami","avatar":""},{"name":"Tsukishiro Momoha","avatar":""},{"name":"Junichi Sakasegawa","avatar":""},{"name":"Seiji Saegusa","avatar":""},{"name":"Yaota Kuso","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kamen no shukumei: Utukushiki ratenshi","モンスターは何処にいる","仮面の宿命 ～美しき裸天使～"]', 1784690324476);
