INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-rock-phan-4', '30 Rock (Phần 4)', '30 Rock (Season 4)', 'https://phimimg.com/upload/vod/20260501-1/5873ebb0e2061696cbd21313bb543398.jpg', 'https://phimimg.com/upload/vod/20260501-1/ddf93b6f4e49769f3c9300de0e95b4a6.jpg', '<p>Công ty mẹ thay đổi khiến toàn bộ môi trường làm việc bị xáo trộn. Jack phải thích nghi với cấp trên mới và những quy tắc mới. Liz cố gắng xây dựng một cuộc sống “bình thường” hơn, nhưng nhận ra bản thân không dễ thay đổi. Sự mâu thuẫn giữa công việc và đời sống cá nhân ngày càng rõ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 27, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Maulik Pancholy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 ROCK サーティー･ロック","サーティー･ロック","30 락","30락","30록","30 Rock"]', 1784690324476);
