INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1-trieu-won', '1 Triệu Won', 'A Million', 'https://phimimg.com/upload/vod/20260501-1/54fc3b5ba6db406d4bb2a4a2327ffdde.jpg', 'https://phimimg.com/upload/vod/20260501-1/8f50bddac5ec3c4558a96d50569a6052.jpg', '<p>Bộ phim A Million (1 Triệu Won / 10억 - 2009) là một bộ phim điện ảnh giật gân, tâm lý của Hàn Quốc, kể về 8 người tham gia một chương trình thực tế sống sót tại vùng hoang dã Úc để giành giải thưởng 1 triệu Won, nhưng thực chất là một trò chơi tử thần.</p>', 'Full', 1, 'single', 'completed', 24, 2009, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae-il","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Shin Min-a","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Jung Yu-mi","avatar":""},{"name":"Lee Chun-hee","avatar":""},{"name":"Go Eun-ah","avatar":""},{"name":"Kim Hak-seon","avatar":""},{"name":"Yu Na-mi","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Kim Joong-ki","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Lee Na-ra","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Baek Jae-ho","avatar":""},{"name":"Yeon Song-ha","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Миллион","A Million","10-eok","1,000,000,000","10억"]', 1784690324476);
