INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('1-trieu-won', '1 Triệu Won', 'A Million', '1 triệu won a million park hae-il park hee-soon shin min-a lee min-ki jung yu-mi lee chun-hee go eun-ah kim hak-seon yu na-mi jeong seok-yong shin dong-mi kim joong-ki choi moo-seong lee na-ra kim joon-bae baek jae-ho yeon song-ha миллион a million 10-eok 1,000,000,000 10억', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-dot', 'Đừng Đốt', 'Don''t Burn', 'https://phimimg.com/upload/vod/20250423-1/a1ac7531c310ee6a33be4da901242bac.jpg', 'https://phimimg.com/upload/vod/20250423-1/f2ccb5c541f27910150227cf3d44535c.jpg', '<p>Đừng Đốt là bộ phim chuyển thể từ quyển nhật ký của nữ liệt sĩ - bác sĩ Đặng Thùy Trâm, ghi lại những năm tháng chiến đấu gian khổ của cô trong kháng chiến chống Mỹ. Tên phim bắt nguồn từ câu nói xúc động của thông dịch viên Nguyễn Trung Hiếu, khi ông ngăn lính Mỹ đốt cuốn nhật ký giữa trận càn ở Đức Phổ. Thùy Trâm hiện lên là người bác sĩ trẻ yêu đời, luôn hết lòng với thương, bệnh binh. Những cảnh cô chăm sóc, vỗ về bệnh nhân và nỗi đau, sự bất lực khi chứng kiến họ ra đi thể hiện sự tận tụy sâu sắc, mang thông điệp về tình yêu và sự kiên cường của một nữ bác sĩ trong chiến tranh.</p>', 'Full', 1, 'single', 'completed', 27, 2009, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Minh Hương","avatar":""},{"name":"Tina Dương","avatar":""},{"name":"Patrick T. McGowan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324476);
