INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-am-gia-dinh', 'Mái Ấm Gia Đình', 'The Blind Side', 'https://phimimg.com/upload/vod/20260421-1/2a46fe15063edf6d3780bf9e78cd06e8.jpg', 'https://phimimg.com/upload/vod/20260421-1/0e2cd1265a4b3ce337b2f3284919ec25.jpg', '<p>Leigh Anne Touhy, chuyên viên trang trí nội thất và &nbsp;Sean là chủ nhân hệ thống tiệm fast food &nbsp;trong tiểu bang. Họ sống trong khu McMansion sang trọng của khu phố Steel Magnolia, Memphis. Mike, hay còn được gọi là Big Mike vì vẻ ngoài kệch cỡm, to lớn, 19 tuổi, là cậu bé lang thang không cha mẹ. Buổi chiều Thanksgiving năm ấy, Leigh bắt gặp Mike đang co ro ngoài trời giá lạnh, Leigh đã đón cậu về nhà ăn bữa cơm Thanksgiving cùng với gia đình. Jake Touhy, con trai Leigh, 10 tuổi rất lanh lợi và lẻo mép. Collins, con gái teenager không tỏ vẻ con nhà giầu mà rất thân mật tạo cho Big Mike sự tự nhiên. Họ là một gia đình tốt bụng.Biết rõ Mike là người vô gia cư, Leigh và Sean tìm hiểu về gia cảnh của anh. Mẹ Mike có đến 14 ...</p>', 'Full', 1, 'single', 'completed', 24, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Tim McGraw","avatar":""},{"name":"Quinton Aaron","avatar":""},{"name":"Jae Head","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Catherine Dyer","avatar":""},{"name":"Andy Stahl","avatar":""},{"name":"Tom Nowicki","avatar":""},{"name":"Libby Whittemore","avatar":""},{"name":"Brian Hollan","avatar":""},{"name":"Melody Weintraub","avatar":""},{"name":"Sharon Conley","avatar":""},{"name":"Omar J. Dorsey","avatar":""},{"name":"Paul Amadi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["攻其不备","守护有心人","L''Éveil d''un champion","Сляпата страна","The Blind Side (Un sueño posible)","弱点","Um Sonho Possível","Zona e verbër","الجانب الخفي","Нябачны бок","Невидима зона","The blind side: Un somni possible","Priča o prvaku","Zrození šampiona","Elämä pelissä","The Blind Side : L''éveil d''un champion","Μια Σχέση Στοργής","הזדמנות שנייה","A szív bajnokai","しあわせの隠れ場所","블라인드 사이드","Neredzamā puse","Nematoma pusė","Wielki Mike","Povestea unui campion","Невидимая сторона","Mrtav ugao","Splnený sen","Zgodba o prvaku","Un sueño posible","เดอะ ไบลด์ไซด์ แม่ผู้นี้มีแต่รักแท้","Kör Nokta","Невидима сторона","Góc Khuất","Blind Side Die grosse Chance","The Blind Side - Die große Chance","The Blind Side"]', 1784690324476);
