INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('24-gio-chong-khung-bo-phan-7', '24 Giờ Chống Khủng Bố (Phần 7)', '24 (Season 7)', '24 giờ chống khủng bố (phần 7) 24 (season 7) kiefer sutherland mary lynn rajskub kim raver yvonne strahovski tate donovan william devane 24小时 24小时反恐部队 24 stunden 24 heures chrono بیست و چهار 24 ore トゥエンティフォー 24 horas przez 24 godziny 24 hodín 24 години двадцять чотири години twenty four 24: live another day 24', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-phep-thuat', 'Gia Đình Phép Thuật', 'Magical Family​', 'https://phimimg.com/upload/vod/20250425-1/f88be0c5f22b2f38e79239ac20edb54f.jpg', 'https://phimimg.com/upload/vod/20250425-1/5e059e0ec1298fa1f89e20d266c476e2.jpg', '<p>Gia đình phép thuật kể về chuyện 5 thành viên trong gia đình là ông Ma Baram, với con trai Ma Pungun, con dâu An Chini cùng 2 người cháu: Ma Yeye và Ma Suri xuống thế giới loài người để học tình cảm của con người để báo cáo về giúp ích cho phái Nguyên Lão ở thế giới phép thuật hiện đang hỗn loạn. Ban đầu, Yeye không muốn sống chung với con người nhưng sau đó cô lại yêu mến họ. Sau đó, Mây (em trai ruột ông Baram) và Bắp Cải (con trai của ngài Nghị trưởng phái Nguyên Lão) cũng xuống thế giới loài người. Họ được học rất nhiều tình cảm tốt đẹp của con người nhờ nhà của Tấn Trung – một hàng xóm hiền lành và tốt bụng. Biết được điều đó, phái Ma Nữ ở thế giới phép thuật cử Hoa Hồng Đen và Na Charu xuống để phá hoại gia đình ông Baram. Nhưng rồi Hoa Hồng Đen cũng bị tình cảm của con người ảnh hưởng, nên đã phản bội phái Ma Nữ và dẫn đến phải chịu tội, sau này cô trở thành người của phái Nguyên Lão. Phái Ma Nữ tiếp tục lần lượt cử thêm nhà phép thuật &quot;sinh đôi&quot;, hai nhà phép thuật Ma Nữ – Ma Nam và nhà phép thuật đột biến Gen để thực hiện mục đích ban đầu của mình. Tuy hai bên luôn đối đầu nhau, nhưng họ cũng hợp tác với nhau trong nhiều việc. Ở những tập cuối của phim, gia đình ông Baram bị con người nghi ngờ về thân phận nhà phép thuật của mình. Phái Nguyên Lão sử dụng phép thuật được nhờ dây chuyền phép thuật, còn phái Ma Nữ sử dụng phép thuật được nhờ nhẫn phép thuật. Phái Nguyên Lão đều cần phải đọc thần chú khi muốn sử dụng phép thuật, trong khi đó, nhẫn phép thuật của phái Ma Nữ thì không cần. Tia phép thuật xuất hiện với hình dạng &quot;tia sáng màu&quot;, có tác dụng dùng để biến hóa, liên lạc, tấn công, v.v... nhưng con người bình thường không thể thấy được những tia sáng này.</p>', 'Hoàn Tất (340/340)', 340, 'series', 'completed', 53, 2009, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hòa Hiệp","avatar":""},{"name":"Vu Dình Toàn","avatar":""},{"name":"Ly Thanh Thao","avatar":""},{"name":"Kim Hiền","avatar":""},{"name":"Băng Di","avatar":""},{"name":"Kim Xuân","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Ninh Dương Lan Ngọc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Magic Family","Vườn ảo thuật","Gia Đình Phép Thuật"]', 1784690324476);
