INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-gio-va-mai-mai', 'Bây Giờ Và Mãi Mãi', 'Now & Later', 'https://phimimg.com/upload/vod/20260328-1/2daee36c9ff80592ec215dae1489e437.jpg', 'https://phimimg.com/upload/vod/20260328-1/c3180abfc4906ee343823e082cf1035a.jpg', '<p>Tình dục, chính trị, văn hóa được hòa quyện trong suốt bộ phim Now &amp; Later (2009). Chuyện phim kể về Angela, một phụ nữ Mỹ La Tinh nhập cư bất hợp pháp vào Mỹ, tình cờ gặp Bill một nhân viên ngân hàng bị giáng chức, lang thang gần như vô gia cư được bạn của Angela giúp đỡ và giới thiệu. Rồi hai người lấy nhau, thỏa mãn nhau bằng những thú vui trần tục…</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keller Wortham","avatar":""},{"name":"Shari Solanis","avatar":""},{"name":"Luis Fernandez-Gil","avatar":""},{"name":"Adrian Quiñonez","avatar":""},{"name":"Marcellina Walker","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Now and Later","Now & Later"]', 1784690324476);
