INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-gio-va-mai-mai', 'Bây Giờ Và Mãi Mãi', 'Now & Later', 'bây giờ và mãi mãi now & later keller wortham shari solanis luis fernandez-gil adrian quiñonez marcellina walker now and later now & later', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-dai-tai-phan-2', 'Thám Tử Đại Tài (Phần 2)', 'The Mentalist (Season 2)', 'https://phimimg.com/upload/vod/20260118-1/63ffc889955c74572aace36e9f2ee9f7.jpg', 'https://phimimg.com/upload/vod/20260118-1/3cf65135b9b8094337a6b1a5fa757000.jpg', '<p>Chuyện phim xoay quanh cuộc hành trình tìm kiếm hung thủ đã sát hại vợ và con gái mình của Patrick Jane. Trước khi thảm kịch xảy đến với gia đình mình, Jane có một sự nghiệp thành công. Nhờ khả năng thôi miên, nắm bắt tâm lý và nhất là khả năng quan sát kỳ tài, anh đã trở nên nổi tiếng bằng việc giả làm một nhà tâm linh. Để khẳng định tài năng của mình, Jane đã xuất hiện trên truyền hình và tuyên bố mình đã giúp cảnh sát phác họa tiểu sử của tên giết người hàng loạt Red John. Tức giận vì bị xem thường, Red John đã giết vợ và con gái Jane để trả thù. Ngay sau thảm kịch, Jane bỏ nghề, trở thành là một cố vấn viên độc lập của phòng điều tra tội phạm bang California (CBI) với hy vọng tìm ra kẻ thủ ác.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 23, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Simon Baker","avatar":""},{"name":"Robin Tunney","avatar":""},{"name":"Tim Kang","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Joe Adler","avatar":""},{"name":"Josie Loren","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El mentalista","Менталистът","O Mentalista","超感神探","超感警探","Mentalist","The Mentalist","心计","A mentalista","THE MENTALIST メンタリスト","メンタリスト","멘탈리스트","Mentalistas","Менталист","De Mentalist","Mentalista","În mintea criminalului","Tam Ly Vien"]', 1784690324476);
