INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-4', 'Quá Nhanh Quá Nguy Hiểm 4', 'Fast & Furious', 'https://phimimg.com/upload/vod/20260225-1/c70cb97dcb9ff7b77e6fcc41e4b48ee1.jpg', 'https://phimimg.com/upload/vod/20260225-1/e670a7fb37cde2c81e952ebc5a088291.jpg', '<p>Đến Dominica để lẩn trốn lệnh truy nã, Dominic Toretto cố gắng tận hưởng một cuộc sống lãng mạn bên cô bạn gái xinh đẹp, cá tính Letty. Sau khi thực hiện một vụ cướp xe chở nhiên liệu, anh rời xa Letty để tránh sự truy lùng của cảnh sát quốc tế và cũng vì muốn bảo vệ cho người con gái anh yêu. Tuy nhiên, không lâu sau, Dom nhận được tin dữ về cái chết bi thảm, đầy bí ẩn của Letty. Anh tức tốc quay về Los Angeles, tự mình đi điều tra nguyên nhân và tìm cách trả thù cho người yêu.</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vin Diesel","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Jack Conley","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Liza Lapira","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Tego Calderon","avatar":""},{"name":"Don Omar","avatar":""},{"name":"Mirtha Michelle","avatar":""},{"name":"Greg Cipes","avatar":""},{"name":"Ron Yuan","avatar":""},{"name":"Alejandro Patiño","avatar":""},{"name":"Joe Hursley","avatar":""},{"name":"Cesar Garci","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rapido y Furioso 4","A todo gas: 4","Wild Speed: Max","분노의 질주 4","Hurjapäät 4","분노의 질주 4-더 오리지널","Fast & Furious - Solo parti originali","Fast & Furious - Neues Modell, Originalteile","Hızlı ve Öfkeli 4","速度与激情4：赛车风云","Rýchli a zbesilí","เร็ว...แรงทะลุนรก 4: ยกทีมซิ่ง แรงทะลุไมล์","A Todo Gas 4 Fast and Furious Aun mas rapido","玩命關頭4","The Fast and the Furious 4 - Neues Modell Originalteile","Brzi i Žestoki Povratak","F&F4 - Fast & Furious","Fast and Furious 4","Fast and Furious","Rapido Y Furioso 4","Fast & Furious 4","The Fast and the Furious 4","The Fast and the Furious 4 - Fast & Furious","ワイルド・スピード マックス","The Fast and the Furious IV: Fast & Furious","Fast & Furious: The Original","Quá Nhanh Quá Nguy Hiểm 4","狂野時速4","Rychle a zběsile 4","Rychle a zběsile 4: Rychlí a zběsilí","Forsaj 4","ワイルド・スピード MAX：2009","Fast & Furious 4 - Neues Modell. Originalteile.","Fast and Furious - Neues Modell. Originalteile.","Fast and Furious 4 - Neues Modell. Originalteile.","Fast & Furious"]', 1784690324476);
