INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('transformers-bai-binh-phuc-han', 'Transformers: Bại Binh Phục Hận', 'Transformers: Revenge of the Fallen', 'https://phimimg.com/upload/vod/20260225-1/2c16cc950a5d9a59e07ad6b959cd12cb.jpg', 'https://phimimg.com/upload/vod/20260225-1/a987e75df3b41c599a06966c9c29326a.jpg', '<p>Đã hai năm kể từ khi Sam Witwicky (Shia LaBeouf) và đội quân Autobot giải cứu loài người khỏi bọn xâm lăng Decepticon. Giờ đây Sam lại đang tất bật chuẩn bị cho mục tiêu lớn nhất trong đời: học đại học xa nhà. &nbsp;Xa nhà cũng là điều mà phe Autobot hiểu rõ hơn hết. Hy vọng tái tạo lại hành tinh quê hương Cybertron đã tan cùng Khối Lập Phương, các Autobot đành ngụ cư tại trái đất, liên minh cùng quân đội NEST rà soát và tiêu diệt những tàn dư còn sót lại của bọn Decepticon ở trái đất. Đáng buồn thay, mong muốn được sống hòa bình bên cạnh con người của các Autobot lại không được chấp nhận.</p>', 'Full', 1, 'single', 'completed', 23, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Ramón Rodríguez","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Julie White","avatar":""},{"name":"Isabel Lucas","avatar":""},{"name":"John Benjamin Hickey","avatar":""},{"name":"Matthew Marsden","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"