INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-2009', 'Tái Sinh', 'The Unborn', 'https://phimimg.com/upload/vod/20260128-1/a6edd6f6708d8eeb2d455ffb286351c3.jpg', 'https://phimimg.com/upload/vod/20260128-1/e8c242e9736e4b8af2e56341e5365835.jpg', '<p>Sau một sự cố kỳ lạ khi đi trông trẻ, Casey bắt đầu bị ám ảnh bởi những cơn ác mộng và các hiện tượng không thể giải thích liên quan đến một cậu bé ma quái. Dần dần, cô phát hiện mình đang bị một thế lực siêu nhiên gắn với người anh song sinh đã chết đeo bám, đồng thời những bí mật đen tối trong gia đình cũng dần bị hé lộ. Khi nguy hiểm ngày càng cận kề và mọi việc có liên quan đến người mẹ đã mất, Casey buộc phải nhờ đến sự giúp đỡ của giáo sĩ Sendak để giải mã lời nguyền và ngăn bi kịch tiếp diễn.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Odette Annable","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"James Remar","avatar":""},{"name":"Ethan Cutkosky","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Jane Alexander","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Atticus Shaffer","avatar":""},{"name":"C. S. Lee","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Michael Sassone","avatar":""},{"name":"Rachel Brosnahan","avatar":""},{"name":"Craig J. Harris","avatar":""},{"name":"Kymberly Mellen","avatar":""},{"name":"Brian Boland","avatar":""},{"name":"Rosly","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["La profecia del no nacido","奪命怪嬰","The Unborn"]', 1784