INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-vui-tinh', 'Những Người Vui Tính', 'Funny People', 'https://phimimg.com/upload/vod/20260122-1/2a1f3dd0f61a26fa5e676bce17c260dc.jpg', 'https://phimimg.com/upload/vod/20260122-1/554719a6c8ae6b9ce241282108cc6dd0.jpg', '<p>George Simmons là một diễn viên hài đã nghỉ hưu ở tuổi trung niên trở thành ngôi sao điện ảnh . Bất chấp sự giàu có của mình , anh ấy bị vỡ mộng và chán nản vì hầu hết các tác phẩm điện ảnh gần đây của anh ấy đều thấp và ít được đón nhận. Được chẩn đoán mắc bệnh bạch cầu dòng tủy cấp tính , anh ta được cung cấp một phương pháp điều trị thử nghiệm chỉ có tỷ lệ thành công 8%. Tin rằng mình sắp chết, anh trở về cội nguồn của mình là hài kịch độc lập.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"RZA","avatar":""},{"name":"Aziz Ansari","avatar":""},{"name":"Maude Apatow","avatar":""},{"name":"Iris Apatow","avatar":""},{"name":"Torsten Voges","avatar":""},{"name":"Allan Wasserman","avatar":""},{"name":"Rod Man","avatar":""},{"name":"Wayne Federman","avatar":""},{"name":"Mike O''Connell","avatar":""},{"name":"James Taylor","avatar":""},{"name":"Nicole Parker","avatar":""},{"name":"Nydia Mc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Siempre hay tiempo para reír","命运好好笑","爆笑绝唱","Zabawni ludzie","Komedianci","Funny People"]', 1784690324476);
