INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-quyen-luc', 'Trò Chơi Quyền Lực (Cuộc Chiến Cân Não)', 'State of Play', 'https://phimimg.com/upload/vod/20260116-1/16b013b7c5faea14147780207c6cc249.jpg', 'https://phimimg.com/upload/vod/20260116-1/91333cad4d38798c8b475d0d2c6a3e20.jpg', '<p>Stephen Collins (Ben Affleck) là một nghị sỹ đầy triển vọng khi leo lên các nấc thang quyền lực một cách nhanh chóng. Khi cuộc chạy đua đến vị trí Tổng thống càng đến gần, các nhà dự đoán đã tuyên đoán rằng Collins đã trở thành ứng cử viên của đảng này cho vị trí tổng thống. Tuy nhiên, việc Collins trở thành Tổng thống trở nên khó khăn hơn khi trợ lý của anh bị sát hạt, và một vài thông tin không có lợi cho Collins bị hé lộ. Cal McAffrey (Russell Crowe), người một thời là bạn thân của Collins, hiện đang là nhà báo nổi tiếng nhất tại thủ đô, lại là người được giao nhiệm vụ điều tra Collins. Cùng với đồng nghiệp là Della (Rachel McAdams), họ bắt đầu vụ điều tra xác định tên sát nhân. Và đó là điểm bắt đầu của ...</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Russell Crowe","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Michael Berresse","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Josh Mostel","avatar":""},{"name":"Michael Weston","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Sarah Lord","avatar":""},{"name":"Tuck Milligan","avatar":""},{"name":"Steve Park","avatar":""},{"name":"Bren","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Intrigas do Estado","Велика гра","State of Play - Der Stand der Dinge","وضعیت بازی","State of Play"]', 1784690324476);
