INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fresh-precure-movie-the-kingdom-of-toys-has-lots-of-secrets', 'Fresh Precure! Movie: The Kingdom of Toys has Lots of Secrets!?', '映画 フレッシュプリキュア！おもちゃの国は秘密がいっぱい！？', 'https://phimimg.com/upload/vod/20251230-1/44a5fb1b65126af2571a15be598ec0f3.jpg', 'https://phimimg.com/upload/vod/20251230-1/6955fd2904bb7b6154776b112860f576.jpg', '<p>Trong một bữa tiệc ngủ, Love tình cờ gặp được chú thỏ nhồi bông Usapyon cũ của cô. Một món đồ chơi bị bỏ rơi đang tìm cách trả thù đã chiếm lấy Vương Quốc Đồ Chơi và hắn ta bắt đầu đánh cắp đồ chơi từ khắp nơi. Nhiệm vụ của Pretty Cure là ngăn chặn hắn và bảo vệ cảm xúc của trẻ em ở khắp mọi nơi!</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanae Oki","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Akiko Nakagawa","avatar":""},{"name":"Yuka Komatsu","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Taiki Matsuno","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Kozo Shioya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Pretty Cure Movie 6 The Kingdom of Toys has Lots of Secrets!","映画 フレッシュプリキュア！おもちゃの国は秘密がいっぱい！？"]', 1784690324476);
