INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('avatar', 'Avatar', 'Avatar', 'https://phimimg.com/upload/vod/20251224-1/5ea13f0250ec1b118783644f6e78b242.jpg', 'https://phimimg.com/upload/vod/20251224-1/a14e53706b8086d753874f16c0d232d3.jpg', '<p>Bộ phim là câu chuyện về người anh hùng “bất đắc dĩ” Jake Sully – một cựu sĩ quan thủy quân lục chiến bị liệt nửa thân. Người anh em sinh đôi của anh được chọn để tham gia vào chương trình cấy gien với người ngoài hành tinh Na’vi nhằm tạo ra một giống loài mới có thể hít thở không khí tại hành tinh Pandora. Giống người mới này được gọi là Avatar. Sau khi anh của Jake bị giết, Jake được chọn để thay thế anh mình và đã trở thành một Avatar, Jake có nhiệm vụ đi tìm hiểu và nghiên cứu hành tinh Pandora. Những thông tin mà anh thu thập được rất có giá trị cho chiến dịch xâm chiếm hành tinh xanh thứ hai này của loài người.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"CCH Pounder","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Dileep Rao","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Sean Anthony Moran","avatar":""},{"name":"Jason Whyte","avatar":""},{"name":"Scott Lawrence","avatar":""},{"name":"Kelly Kilgour","avatar":""},{"name":"James Patrick","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","s