INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cho-nguoi-o-lai', 'Cuộc Chiến Cho Người Ở Lại', 'Taking Chance', 'https://phimimg.com/upload/vod/20251216-1/cd422bd7f3f6dcd62adc575f5d5d48c1.jpg', 'https://phimimg.com/upload/vod/20251216-1/93a2b7068e8689042200d31fa1a22ad2.jpg', '<p>Cả bộ phim tạo nên một bức tranh chủ yếu là gam màu trầm nhưng sự ấm áp như một ngọn lửa lan tỏa âm thầm sưởi ấm lòng người giữa đêm đông giá lạnh, là tia nắng bé nhỏ cuối đông báo hiệu một khởi đầu tươi sáng và tốt đep hơn, là một khoảnh khắc lặng yên giữa đời thường khi mà tất cả mọi khác biệt dường như hòa làm một tạo nên một tổng thể chung nhất – tình yêu thương đồng loại và sức mạnh hàn gắn vết thương của tập thể.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Tom Aldredge","avatar":""},{"name":"Nicholas Art","avatar":""},{"name":"Blanche Baker","avatar":""},{"name":"Guy Boyd","avatar":""},{"name":"Gordon Clapp","avatar":""},{"name":"Emily Wickersham","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Enver Gjokaj","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Noah Fleiss","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"John Bedford Lloyd","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["O Retorno de Um Herói","Sotilaan viimeinen matka","带你回家","A Última Escolta","A lélek útja","Cuộc Chiến Cho Người Ở Lại","Eve dönüş","護送錢斯","El regreso de un soldado","Забирая Чэнса","Ultimul drum al lui Chance","Podróż powrotna","戦場のおくりびと","Taking chance - Il ritorno di un eroe","Iroes polemou","L''Honneur d''un Marine","En soldats sista resa","Correr Riscos","Regresando a casa","Taking Chance"]', 1784690324476);
