INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-cho-nguoi-o-lai', 'Cuộc Chiến Cho Người Ở Lại', 'Taking Chance', 'cuộc chiến cho người ở lại taking chance kevin bacon tom aldredge nicholas art blanche baker guy boyd gordon clapp emily wickersham mike colter enver gjokaj ann dowd john magaro noah fleiss liza colón-zayas john bedford lloyd o retorno de um herói sotilaan viimeinen matka 带你回家 a última escolta a lélek útja cuộc chiến cho người ở lại eve dönüş 護送錢斯 el regreso de un soldado забирая чэнса ultimul drum al lui chance podróż powrotna 戦場のおくりびと taking chance - il ritorno di un eroe iroes polemou l''honneur d''un marine en soldats sista resa correr riscos regresando a casa taking chance', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-ngoc-nghech-sei-sung-saw-liu', 'Tử Thần Ngốc Nghếch (Sei sung saw liu)', 'Split Second Murders', 'https://phimimg.com/upload/vod/20251214-1/debb9316318bb28e8fc9b2a26383b0e6.jpg', 'https://phimimg.com/upload/vod/20251214-1/78f0f8fb1824f382d7015a72f05f08f0.jpg', '<p>Họa sĩ hoạt hình Lục Tử đam mê công việc nên bỏ bê bạn gái. Trên đường đi phỏng vấn, anh gặp nhiều chuyện rắc rối, và sau đó kể cho biên tập viên nghe câu chuyện sáng tác về chị gái làm môi giới bảo hiểm, người phát hiện ra em rể ngoại tình nhưng cố giấu, dẫn đến mâu thuẫn gia đình.Câu chuyện không được đón nhận. Sau đó, Lục Tử tình cờ gặp gỡ cô gái Phương Mỹ Phương và chứng kiến chuyện tình cảm phức tạp của bạn bè.Khi ông chủ yêu cầu anh sáng tác nội dung tàn bạo hơn, Lục Tử phải đưa ra quyết định khó khăn.</p>', 'Full', 1, 'single', 'completed', 25, 2009, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lâm Gia Đống","avatar":""},{"name":"Lục Vịnh Quân","avatar":""},{"name":"Phương Hạo Văn","avatar":""},{"name":"Lâm Triêu Vinh","avatar":""},{"name":"Châu Tú Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["死神傻了","Sei sung saw liu"]', 1784690324476);
