INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-than-ngoc-nghech-sei-sung-saw-liu', 'Tử Thần Ngốc Nghếch (Sei sung saw liu)', 'Split Second Murders', 'tử thần ngốc nghếch (sei sung saw liu) split second murders lâm gia đống lục vịnh quân phương hạo văn lâm triêu vinh châu tú na 死神傻了 sei sung saw liu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-nhan-that-su', 'Quan Nhân Thất Sự', 'Seven 2 One', 'https://phimimg.com/upload/vod/20251129-1/fd407c53f479e7a05846e0bb28f6c267.jpg', 'https://phimimg.com/upload/vod/20251129-1/c78dc4ea1942c3381d2479a6d4b83a21.jpg', '<p>Trong đêm, một tên cướp bịt mặt đã xông vào cửa hàng tiện lợi để cướp. Một nam thanh niên và tên cướp đã xô xát với nhau. Một chiếc xe cảnh sát nhanh chóng có mặt tại hiện trường gây án. Dung Dung đã rời bỏ người bạn gái đồng giới và bắt đầu hẹn hò với chàng trai trẻ tuổi, khôi ngô William. Nhưng William không hề biết rằng anh chỉ là chỗ dựa để Dung Dung thoát khỏi người yêu cũ để qua lại với người bạn gái mới; Bách Hào nghiện cờ bạc khiến bạn gái A Linh rất đau khổ. William đã thúc giục người đang cần tiền để đánh bạc Bách Hào dấn thân vào nguy hiểm. Cùng lúc đó, A Linh tích góp tiền cho bạn trai, nhưng lại dần rơi vào bẫy của Rio háo sắc.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Giang Nhược Lâm","avatar":""},{"name":"Trần Vĩ Đình","avatar":""},{"name":"Châu Bách Hà","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Trịnh Dung","avatar":""},{"name":"Triệu Thạc Chi","avatar":""},{"name":"Từ Chính Hhy","avatar":""},{"name":"Hà Thương Khiêm","avatar":""},{"name":"Triệu Tuấn Thừa","avatar":""},{"name":"Tiểu Phì","avatar":""},{"name":"Cung Gia Hân","avatar":""},{"name":"Tiêm Chí Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["關人7事"]', 1784690324476);
