INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-nhan-that-su', 'Quan Nhân Thất Sự', 'Seven 2 One', 'quan nhân thất sự seven 2 one giang nhược lâm trần vĩ đình châu bách hà châu tú na trịnh dung triệu thạc chi từ chính hhy hà thương khiêm triệu tuấn thừa tiểu phì cung gia hân tiêm chí văn 關人7事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-tu-da-tinh', 'Ái Tử Đa Tình', 'Short Of Love', 'https://phimimg.com/upload/vod/20251129-1/fcf845a68ff8b960c489f65b7df90e91.jpg', 'https://phimimg.com/upload/vod/20251129-1/e8ce551fcb143a8e98516a8d259c31cb.jpg', '<p>Lam Tử Kiệt (Vương Tổ Lam đóng) tuy có chiều cao khiêm tốn nhưng lại giàu có và sống xa hoa. Thư ký của anh (Quan Ân Na đóng) phạm sai lầm làm mất cổ phiếu công ty, nhưng nhờ đó anh lại may mắn tránh được cuộc khủng hoảng tài chính và tài sản không bị giảm đi nhiều. Trong một lần lén lút &quot;ăn vụng&quot; trên du thuyền, để bù đắp cho vị hôn thê Châu Châu (Châu Tú Na đóng), anh đặt mua một chiếc vòng cổ kim cương đắt tiền, nhưng lại vô tình làm mất và rơi vào tình cảnh vô cùng bối rối. Thấy dáng vẻ túng quẫn của Tử Kiệt, Châu Châu lầm tưởng anh đã phá sản nên quyết định chia tay. Trong giai đoạn khủng hoảng, Tử Kiệt vô cùng đau khổ. Anh tình cờ gặp được cô gái nhân hậu tên Angel (Angelababy/Dương Dĩnh đóng), và mỗi lần thất vọng, anh đều nhận được sự an ủi dịu dàng cùng lời khuyên chân thành từ cô. Sau đó, anh lần lượt quen biết hai chị em: giáo viên ballet Christy (Hoàng Uyển Linh đóng) và vũ nữ Christine (Hoàng Uyển Linh đóng), nữ mát-xa khiếm thị Gia Gia (Giả Hiểu Thần đóng), và đại ca giang hồ Đao Ba San (Từ Tử San đóng). Một loạt các mối tình lãng mạn này đã khuấy động dòng chảy tình yêu trong anh...</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Quan Ân Na","avatar":""},{"name":"Hoàng Uyển Linh","avatar":""},{"name":"Từ Tử San","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Angelababy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["矮仔多情"]', 1784690324476);
