INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-tu-da-tinh', 'Ái Tử Đa Tình', 'Short Of Love', 'ái tử đa tình short of love quan ân na hoàng uyển linh từ tử san châu tú na angelababy 矮仔多情', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thay-ma', 'Vùng Đất Thây Ma', 'Zombieland', 'https://phimimg.com/upload/vod/20251122-1/8ada74f675a197774a6ec7335f75b6ae.jpg', 'https://phimimg.com/upload/vod/20251122-1/45a5ff9d947c28c5811c53742edfe5a8.jpg', '<p>Zombieland là bộ phim ma - kinh dị nhưng mang yếu tố hài hước xoay quanh hai người đàn ông tìm cách xoay sở để sống sót trong một thế giới đầy thây ma. Đó là Columbus, một người đàn ông yếu đuối và Tallahassee, một anh hùng diệt thay ma, người có quyết tâm giết đến cái thây ma cuối cùng trên trái đất. Rồi một ngày họ nhận ra họ không phải là những người duy nhất sống sót, họ sẽ phải cùng nhau xác định cách nào thì ít đau đớn hơn: đoàn kết với nhau hay nạp mạng cho đám thây ma kia?</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Derek Graf","avatar":""},{"name":"Elle Alexander","avatar":""},{"name":"Melanie Booth","avatar":""},{"name":"Chris Burns","avatar":""},{"name":"Blaise Corrigan","avatar":""},{"name":"Sydnie Dawson","avatar":""},{"name":"Justin Price","avatar":""},{"name":"Christina Klein","avatar":""},{"name":"Amir Kovacs","avatar":""},{"name":"Shaun Lynch","avatar":""},{"name":"Lynn McArthur","avatar":""},{"name":"Michel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Земя на зомбита","Добро пожаловать в Зомбилэнд","Зомбiленд","Zumbilândia","Bienvenue à Zombieland","Bem-vindo a Zombieland","ゾンビランド","ゾンビランド：2009","喪屍樂園","丧尸乐园","僵尸领地","僵尸之地","Zombieland"]', 1784690324476);
