INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-doi-tra-phan-2', 'Trò Chơi Dối Trá (Phần 2)', 'Liar Game (Season 2)', 'https://phimimg.com/upload/vod/20251104-1/ed9bcd5479ae5cea20db78ce84a54823.jpg', 'https://phimimg.com/upload/vod/20251104-1/28910d7106ed9ccb705e3f2c445c92f2.jpg', '<p>Câu chuyện mở đầu với Kanzaki Nao (Toda Erika), cô sinh viên tốt bụng và trung thực đến ngây thơ, vô tình bị kéo vào “Trò chơi dối trá” – nơi người chơi lừa nhau để giành số tiền khổng lồ. Nao tìm đến sự giúp đỡ của thiên tài lừa đảo Akiyama Shinichi (Matsuda Shota). Từ đó, cả hai bước vào chuỗi đấu trí nghẹt thở.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Shota Matsuda","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Michiko Kichise","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Kosuke Suzuki","avatar":""},{"name":"Ikkei Watanabe","avatar":""},{"name":"Megumi","avatar":""},{"name":"Yoshiyuki Morishita","avatar":""},{"name":"Hairi Katagiri","avatar":""},{"name":"Shihou Harumi","avatar":""},{"name":"Yoshiyoshi Arakawa","avatar":""},{"name":"Jutta Yuki","avatar":""},{"name":"Hidekazu Mashima","avatar":""},{"name":"Nobuo Kyô","avatar":""},{"name":"Shugo Oshinari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["欺诈游戏","说谎者的游戏","Raiaa Geemu","Raiā Gēmu","ライアーゲーム","LIAR GAME","라이어게임","Ігри Брехунів"]', 1784690324476);
