INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh', 'Định Mệnh', 'Inglourious Basterds', 'https://phimimg.com/upload/vod/20251028-1/013c8b687affbd7794a5a039d29393eb.jpg', 'https://phimimg.com/upload/vod/20251028-1/5c6e749cef45b12d01de0a7b0b670e57.jpg', '<p>Vào năm đầu tiên khi Đức Quốc Xã chiếm đóng nước Pháp, Shosanna Dreyfus đã chứng kiến cảnh gia đình mình bị hành quyết trong tay quân đội Đức. Shosanna đã khó khăn lắm mới trốn thoát được và đi đến Paris, thay đổi danh tính, trở thành bà chủ và là người điều hành của một rạp chiếu bóng. Tại một nơi khác ở Châu Âu, trung úy Aldo Raine đã thành lập một nhóm binh lính Mỹ gốc Do Thái tiến hành các cuộc đột kích trả đũa Đức Quốc Xã . Đội quân của Raine kết hợp cùng một nữ diễn viên Đức kiêm điệp viên nằm vùng Bridget von Hammersmark để thi hành điệp vụ lật đổ những thủ lĩnh của Third Reich. Số phận đã đưa họ gặp nhau tại rạp chiếu bóng nơi Shosanna đang làm chủ những kế hoạch cùng với kế hoạch phục thù riêng của cô bắt đầu được tiến hành…</p>', 'Full', 1, 'single', 'completed', 24, 2009, 'Vietsub', 'FHD', 'Đức', 1, '[{"name":"Brad Pitt","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Eli Roth","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Gedeon Burkhard","avatar":""},{"name":"Jacky Ido","avatar":""},{"name":"B.J. Novak","avatar":""},{"name":"Omar Doom","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Sylvester Groth","avatar":""},{"name":"Martin Wuttke","avatar":""},{"name":"Mike Myers","avatar":""},{"name":"Julie Dreyfu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Malditos Bastardos","Bastardos Inglórios","Kunniattomat paskiaiset","Бесславные ублюдки","Bękarty wojny","Becstelen Brigantyk","Bastardos sin gloria","Sacanas Sem Lei","Maleïts Malparits","پست فطرت های لعنتی","Άδωξοι Μπάσταρδη","besslavnyye ublyudki","Безславнi виродки","바스터즈: 거친 녀석들","Inglourious Bastards","Inglorious Basterds","惡棍特工","イングロリアス・バスターズ","Serefsiz Alçaqlar","Бясслаўныя вырадкі","Гадни копилета","Le commando des bâtards","Bastardos Sin Gloria","Hanebný pancharti","Vääritud tõprad","Inglourious Basterds","Bastardi senza gloria","Nemilosrdni gadovi","Negarbingi šunsnukiai","Soysuzlar Çetesi","Ticalosi fara glorie","Neslavne barabe","Nehanební Bastardi","바스터즈-거친 녀석들","The Inglorious Bastards","ยุทธการเดือดเชือดนาซี","Những Kẻ Khốn Kiếp","希魔撞正殺人狂","Once Upon A Time In Nazi-Occupied France","Անփառունակ սրիկաները","Бясслаўныя выблядкі","أوغاد مجهولون"]', 1784690324476);
