INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dinh-menh', 'Định Mệnh', 'Inglourious Basterds', 'định mệnh inglourious basterds brad pitt mélanie laurent christoph waltz eli roth michael fassbender diane kruger daniel brühl til schweiger gedeon burkhard jacky ido b.j. novak omar doom august diehl denis ménochet sylvester groth martin wuttke mike myers julie dreyfu malditos bastardos bastardos inglórios kunniattomat paskiaiset бесславные ублюдки bękarty wojny becstelen brigantyk bastardos sin gloria sacanas sem lei maleïts malparits پست فطرت های لعنتی άδωξοι μπάσταρδη besslavnyye ublyudki безславнi виродки 바스터즈: 거친 녀석들 inglourious bastards inglorious basterds 惡棍特工 イングロリアス・バスターズ serefsiz alçaqlar бясслаўныя вырадкі гадни копилета le commando des bâtards bastardos sin gloria hanebný pancharti vääritud tõprad inglourious basterds bastardi senza gloria nemilosrdni gadovi negarbingi šunsnukiai soysuzlar çetesi ticalosi fara glorie neslavne barabe nehanební bastardi 바스터즈-거친 녀석들 the inglorious bastards ยุทธการเดือดเชือดนาซี những kẻ khốn kiếp 希魔撞正殺人狂 once upon a time in nazi-occupied france անփառունակ սրիկաները бясслаўныя выблядкі أوغاد مجهولون', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-3', 'Upin & Ipin (Phần 3)', 'Upin & Ipin (Season 3)', 'https://phimimg.com/upload/vod/20251022-1/58ddd8f6715870edccb673e749ce9070.jpg', 'https://phimimg.com/upload/vod/20251022-1/1c70d501a0b457261c1378e0b72aa486.jpg', '<p>“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p>Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p><br/></p><p><br/></p>', 'Hoàn Tất (3/3)', 3, 'hoathinh', 'completed', 21, 2009, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324476);
