INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-phu-quy', 'Con Đường Phú Quý', 'Born Rich', 'https://phimimg.com/upload/vod/20251008-1/11f7d2e514926a6a4c1a8169a5faf9cb.jpg', 'https://phimimg.com/upload/vod/20251008-1/bbe060d641ced50eaa43eac91faf6897.jpg', '<p>Trác Nhất Nguyên (Lữ Lương Vỹ đóng) hiểu lầm Sa Phú Lai (La Gia Lương đóng) là người em cùng cha khác mẹ với mình tức Trác Nhất Minh, cho nên ra sức dìu dắt Phú Lai trở thành nhân vật quan trọng trong giới ngân hàng. Trong bức màn tình thân, Nhất Nguyên không nhận ra dã tâm của Phú Lai, vô tình dẫn sói vào nhà...</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 11, 2009, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Anita Yuen Wing-Yee","avatar":""},{"name":"Kenix Kwok Ho-Ying","avatar":""},{"name":"Jaime Chik Mei-Chun","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Kenneth Ma Kwok-Ming","avatar":""},{"name":"Sharon Chan Man-Chi","avatar":""},{"name":"Nancy Sit Ka-Yin","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Natalie Tong","avatar":""},{"name":"Paul Chun Pui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Root of Evil","Born Rich","富貴門"]', 1784690324476);
