INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-hung-pha-an', 'Song Hùng Phá Án', 'Tokyo Dogs', 'https://phimimg.com/upload/vod/20251001-1/52c050d112df37a300845cb39cf60b4a.jpg', 'https://phimimg.com/upload/vod/20251001-1/83634a92c4bea63c2a54c4b0f0def6af.jpg', '<p>Kanade Takakura là một thám tử tinh anh của Sở Cảnh sát New York, nổi tiếng với khả năng phán đoán sắc bén nhưng tính cách lạnh lùng và cứng nhắc. Thuở nhỏ, Kanade từng mất cha trong một vụ giết người, và nỗi đau đó đã thôi thúc anh trở thành thám tử. Maruo Kudo là cựu thành viên băng mô tô, nay là thám tử đặc biệt thuộc sở cảnh sát Nhật Bản. Hai con người với tính cách trái ngược phải bắt tay hợp tác trong một vụ án mà những bí mật then chốt lại nằm trong tay một cô gái trẻ tên Yuki Matsunada.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Hiro Mizushima","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Nene Otsuka","avatar":""},{"name":"Ryo Katsuji","avatar":""},{"name":"Mikihisa Azuma","avatar":""},{"name":"Kotaro Shiga","avatar":""},{"name":"Rie Tomosaka","avatar":""},{"name":"Asami Usuda","avatar":""},{"name":"Hiroshi Yazaki","avatar":""},{"name":"Haruna Kawaguchi","avatar":""},{"name":"Takuya Yoshimura","avatar":""},{"name":"Yoshiko Tanaka","avatar":""},{"name":"Kensei Mikami","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["东京DOGS","東京DOGS"]', 1784690324476);
