INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-xich-bich-2', 'Đại Chiến Xích Bích 2', 'Red Cliff II', 'https://phimimg.com/upload/vod/20250915-1/9198b64700b4eb819a343b579fdf1b6a.jpg', 'https://phimimg.com/upload/vod/20250915-1/9d415337e3168a1862c589d96677e505.jpg', '<p>Kết thúc phần 1, quân Đông Ngô vui mừng trong không khí thắng trận, quyết định hạ trại bên bờ nam sông Trường Giang ở khu vực có những vách đá dựng đứng. Quân của Chu Du ít hơn nhiều, nhưng lại chiếm ưu thế về thủy chiến, Tào Tháo không thể qua sông nên đóng trại ở bờ bắc để huấn luyện quân. Ông dùng xích sắt nối thuyền lớn lại gọi là &quot;Liên Hoàn Chiến Thuyền&quot;. Trong khi quân lính chuẩn bị cho trận giao tranh sắp tới, Tào Tháo cao ngạo cho rằng thế trận liên hoàn chiến thuyền của mình là bất khả chiến bại, ung dung ngồi uống rượu làm thơ cùng chư tướng, lại còn tổ chức trò chơi đá cầu.Tào Tháo không hề biết rằng thời gian tồn tại của &quot;Liên Hoàn Chiến Thuyền&quot; chỉ còn tính bằng ngày.</p>', 'Full', 1, 'single', 'completed', 21, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Zhang Fengyi","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Lin Chi-Ling","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Hou Yong","avatar":""},{"name":"Song Jia","avatar":""},{"name":"You Yongzhi","avatar":""},{"name":"Baasanjav Mijid","avatar":""},{"name":"Zang Jinsheng","avatar":""},{"name":"Shan Zhang","avatar":""},{"name":"Wang Hui","avatar":""},{"name":"Xie Gang","avatar":""},{"name":"Shi Xiaohong","avatar":""},{"name":"Xu Fengnian","avatar":""},{"name":"Guo C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Red Cliff 2","Red Cliff II","La battaglia dei tre regni II","La battaglia dei tre regni 2°parte","Les 3 Royaumes : partie 2","A Batalha Dos Três Reinos II","A Batalha dos 3 Reinos II","赤壁2","Acantilado Rojo 2","Red Cliff: Part 2","レッドクリフ Part II -未来への最終決戦-","Red Cliff ภาค 2","赤壁：决战天下","적벽대전2","적벽대전 2부-최후의 결전","Chi bi: Jue zhan tian xia","Les Trois Royaumes, 2ème Partie","レッドクリフ Part II ―未来への最終決戦―：2009","レッドクリフ Part II ―未来への最終決戦―","赤壁：決戰天下","赤壁（下）","الجرف الأحمر (الجزء الثاني)"]', 1784690324476);
