INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-xich-bich-2', 'Đại Chiến Xích Bích 2', 'Red Cliff II', 'đại chiến xích bích 2 red cliff ii tony leung chiu-wai takeshi kaneshiro zhang fengyi chang chen zhao wei hu jun shido nakamura lin chi-ling tong dawei hou yong song jia you yongzhi baasanjav mijid zang jinsheng shan zhang wang hui xie gang shi xiaohong xu fengnian guo c red cliff 2 red cliff ii la battaglia dei tre regni ii la battaglia dei tre regni 2°parte les 3 royaumes : partie 2 a batalha dos três reinos ii a batalha dos 3 reinos ii 赤壁2 acantilado rojo 2 red cliff: part 2 レッドクリフ part ii -未来への最終決戦- red cliff ภาค 2 赤壁：决战天下 적벽대전2 적벽대전 2부-최후의 결전 chi bi: jue zhan tian xia les trois royaumes, 2ème partie レッドクリフ part ii ―未来への最終決戦―：2009 レッドクリフ part ii ―未来への最終決戦― 赤壁：決戰天下 赤壁（下） الجرف الأحمر (الجزء الثاني)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oss-117-lac-loi-o-rio', 'Oss 117: Lạc Lối Ở Rio', 'OSS 117: Lost in Rio', 'https://phimimg.com/upload/vod/20250830-1/ed74103f503b724358330eb4d91c0ce3.jpg', 'https://phimimg.com/upload/vod/20250830-1/2561b11e723748cc8b058cb642609ca9.jpg', '<p>12 năm sau khi sứ mệnh Cairo kết thúc, năm 1967 tại một khu nghỉ mát trượt tuyết ở Gstaad, Thụy Sĩ, OSS 117 đã hạ gục các băng đảng xã hội đen Trung Quốc , từng cái một. Một mật vụ Pháp của SDECE, phục vụ Pháp dưới thời Tướng De Gaulle và Thủ tướng Georges Pompidou, Hubert Bonisseur de La Bath nhận lệnh từ cấp trên của mình, Armand Lesignac, trong một nhiệm vụ ở Rio de Janeiro. Ở đó, Hubert phải mua vi phim từ một cựu quan chức Đức Quốc xã, trong đó có danh sách những người Pháp từng cộng tác với Đức Quốc xã trong Thế chiến thứ hai. Trong nhiệm vụ, Hubert đã tham gia với Mossad, tổ chức bí mật của Israel.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Jean Dujardin","avatar":""},{"name":"Louise Monot","avatar":""},{"name":"Alex Lutz","avatar":""},{"name":"Reem Kherici","avatar":""},{"name":"Rüdiger Vogler","avatar":""},{"name":"Pierre Bellemare","avatar":""},{"name":"Ken Samuels","avatar":""},{"name":"Serge Hazanavicius","avatar":""},{"name":"Laurent Capelluto","avatar":""},{"name":"Moon Dailly","avatar":""},{"name":"Jean-Marie Paris","avatar":""},{"name":"Jean-Louis Barcelona","avatar":""},{"name":"Jan Oliver Schroeder","avatar":""},{"name":"Guillaume Schiffman","avatar":""},{"name":"Vincent Haquin","avatar":""},{"name":"Adr","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["OSS 117 - Rio ne répond plus","OSS 117: Rio nem válaszol","OSS 117 - A riói küldetés","OSS 117 - Lost in Rio","OSS 117 - Rio Is Calling","OSS 117 Rio ne repond plus","OSS 117։ Rio ne répond plus","OSS 117 : Rio ne répond plus"]', 1784690324476);
