INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-tinh-yeu-tinh-yeu-toi', 'Thử Thách Tình Yêu (Tình Yêu Tới)', 'Love Happens', 'https://phimimg.com/upload/vod/20250828-1/c6bb52eadbe31cfc7b0249e14181c672.jpg', 'https://phimimg.com/upload/vod/20250828-1/28b53f2cb4b677cb5692032afa4ca4c6.jpg', '<p>Sau nỗi tuyệt vọng vì không cứu được vợ mình, người đàn ông vốn là bậc thầy của những lời khuyên, lại một lần nữa chạm tới giấc mơ hạnh phúc cùng cô chủ tiệm hoa kì lạ.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Deirdre Blades","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Sasha Alexander","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Clyde Kusatsu","avatar":""},{"name":"Anne Marie DeLuise","avatar":""},{"name":"Tyler McClendon","avatar":""},{"name":"Panou","avatar":""},{"name":"Michael Kopsa","avatar":""},{"name":"Michelle Harrison","avatar":""},{"name":"Darla Fa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qualcosa di speciale","O Amor Acontece","Derült égből szerelem","Quand arrive l''amour","愛上妳，愛上我","Nuevamente Amor","Coup de foudre à Seattle","Love Happens","러브 해픈스","러브 해펀스"]', 1784690324476);
