INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-thach-tinh-yeu-tinh-yeu-toi', 'Thử Thách Tình Yêu (Tình Yêu Tới)', 'Love Happens', 'thử thách tình yêu (tình yêu tới) love happens aaron eckhart jennifer aniston dan fogler judy greer martin sheen deirdre blades john carroll lynch sasha alexander frances conroy joe anderson clyde kusatsu anne marie deluise tyler mcclendon panou michael kopsa michelle harrison darla fa qualcosa di speciale o amor acontece derült égből szerelem quand arrive l''amour 愛上妳，愛上我 nuevamente amor coup de foudre à seattle love happens 러브 해픈스 러브 해펀스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-4-nguon-goc-nguoi-soi', 'X-Men 4: Nguồn Gốc Người Sói', 'X-Men Origins: Wolverine', 'https://phimimg.com/upload/vod/20250817-1/b3f35d48041bfba9cc28ae7cb2eedca0.jpg', 'https://phimimg.com/upload/vod/20250817-1/d785cd546c2c095ee60a847849f5b902.jpg', '<p>Tuổi thơ của James “Logan” Hewlett trở thành nỗi ám ảnh khi Logan chính tay giết chết cha ruột của mình, sau khi ông giết cha nuôi của anh. Logan và người anh Victor Creed đã cùng chạy trốn khắp nơi khi chỉ là những đứa trẻ, rồi sau đó cùng nhau khoác áo lính lao mình vào những cuộc chiến cho quân đội, và cuối cùng được William Stryker nhận về phục vụ cho đội quân người đột biến đặc biệt của hắn. Sau một trận càn quét ở Châu Phi, Logan giã từ đội quân này và lui về sống ẩn dật cùng bạn gái Silver Fox. Sau 6 năm bình yên, Stryker tìm đến và buộc Logan phải trở về tham gia dự án Weapon X mới của mình. Creed ra tay hạ sát Fox để buộc Logan khuất phục, gây nên mối hận thù giữa hai anh em Logan và Creed. &nbsp;Cùng lúc với việc sở hữu bộ xương từ chất Adamantium, Logan cũng dần mất đi ký ức và bắt đầu một cuộc sống mới. Weapon X đã biến Logan trở thành Wolverine, và người anh Creed cũng mang tên mới là Sabretooth.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Lynn Collins","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Dominic Monaghan","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"will.i.am","avatar":""},{"name":"Tim Pocock","avatar":""},{"name":"Julia Blake","avatar":""},{"name":"Max Cullen","avatar":""},{"name":"Troye Sivan","avatar":""},{"name":"Michael-James Olsen","avatar":""},{"name":"Peter O''Brien","avatar":""},{"name":"Aaron Jeffery","avatar":""},{"name":"Ali","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Люди икс Начало Росомаха","X-Men orígenes: Wolverine","엑스맨 탄생: 울버린","Люди-Х: Росомаха","Люди Ікс. Початок: Росомаха","X-Men 4: Orígenes Lobezno","金刚狼1：X战警起源","X-Men Les Origines : Wolverine","X-Men Başlangıç: Wolverine","变种特攻：狼人外传","X战警前传：金刚狼","X-Men Origins: Wolverine"]', 1784690324476);
