INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-vang-trang-non', 'Chạng Vạng: Trăng Non', 'The Twilight Saga: New Moon', 'https://phimimg.com/upload/vod/20250812-1/22806d9e27a052cc167508c92e70166b.jpg', 'https://phimimg.com/upload/vod/20250812-1/45151a05dbc88c73f7c7b0da4d64b7b0.jpg', '<p>Trong The Twilight Saga: New Moon, chương thứ hai trong series thành công ngoài mong đợi và là hội chứng văn hóa toàn cầu của Stephenie Meyer, mối tình lãng mạn giữa người và ma cà rồng được nâng lên một tầm cao mới khi Bella Swan (Kristen Stewart) thử thách định mệnh của mình chỉ để chớp lấy một khoảnh khắc ngắn ngủi được nhìn thấy người yêu Edward Cullen (Robert Pattinson). Khi cô tiến thẳng đến tận cùng bí mật của thế giới siêu nhiên mà cô hằng mong ước sẽ được trở thành một phần của nó, cô khám phá ra hai bí mật cổ đại có khả năng đe dọa cuộc sống của mình lớn nhất từ trước đến nay. Ngay sau sinh nhật lần thứ 18 của Bella, Edward quyết định rời bỏ cô để bảo vệ cô khỏi nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Taylor Lautner","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Rachelle Lefevre","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Nikki Reed","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Gil Birmingham","avatar":""},{"name":"Anna","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85