INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-bo-quoc-te', 'Khủng Bố Quốc Tế', 'The International', 'https://phimimg.com/upload/vod/20250804-1/c2e912f40ac72baf22221ab89412752f.jpg', 'https://phimimg.com/upload/vod/20250804-1/6124fb95a1d824ec371540bf57e3f637.jpg', '<p>Bộ phim là câu chuyện của nhân viên Interpol Louis Salinger và luật sư cố vấn của Manhattan Eleanor Whitman. Cả hai đang cố gắng lập lại công lý bằng cách vạch trần một trong số những ngân hàng có quyền lực nhất thế giới. Khám phá được các hoạt động phi pháp của ngân hàng này, bao gồm rửa tiền, buôn bán vũ khí và góp phần làm mất ổn định chính quyền, Salinger và Whitman bị cuốn vào cuộc điều tra xuyên các thành phố từ Berlin đến Milan, New York và Istanbul.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Patrick Baladi","avatar":""},{"name":"Jay Villiers","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Michel Voletti","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Remy Auberjonois","avatar":""},{"name":"Tibor Feldman","avatar":""},{"name":"Steven Randazzo","avatar":""},{"name":"Nilaja Sun","avatar":""},{"name":"Ty Jones","avatar":""},{"name":"Ian Burfield","avatar":""},{"name":"Peter Jorda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Internacional","Trama Internacional","黑暗金控","L''Enquête - The International","The International: Dinero en la Sombra","Agente Internacional","The International"]', 1784690324476);
