INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-diet-cuu-roi', 'Kẻ Hủy Diệt: Cứu Rỗi', 'Terminator Salvation', 'https://phimimg.com/upload/vod/20250804-1/752049a13fab0f766ef7e9eef89598a2.jpg', 'https://phimimg.com/upload/vod/20250804-1/53ce4d6b5167ac198dbcf1c28e24d5d1.jpg', '<p>“Terminator Salvation” là bộ phim thứ tư của dòng phim hành động nổi tiếng “Terminator” được phát hành phần đầu vào năm 1984. Bối cảnh phim diễn ra trong thế giới giả tưởng của tương lai năm 2018, khi cuộc chiến của nhân loại với những cỗ máy hủy diệt do hệ thống máy tính thông minh siêu việt tên Skynet làm chủ. Sau khi âm mưu xóa sổ nhân loại trong hàng trăm vụ nổ hạt nhân, Skynet và binh đoàn hủy diệt của nó bắt đầu tiến hành chiến dịch truy quét và tàn sát những người sống sót.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Moon Bloodgood","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Common","avatar":""},{"name":"Zach McGowan","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Jane Alexander","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Ivan G''Vera","avatar":""},{"name":"Dorian Nkono","avatar":""},{"name":"Chris Browning","avatar":""},{"name":"Beth Bailey","avatar":""},{"name":"Victor J. Ho","avatar":""},{"name":"Buster Reeves","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2