INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-huy-diet-cuu-roi', 'Kẻ Hủy Diệt: Cứu Rỗi', 'Terminator Salvation', 'kẻ hủy diệt: cứu rỗi terminator salvation christian bale sam worthington moon bloodgood helena bonham carter anton yelchin common zach mcgowan bryce dallas howard jane alexander michael ironside ivan g''vera dorian nkono chris browning beth bailey victor j. ho buster reeves ja terminator 4 t4 terminátor - megváltás terminator iv: salvation terminator 4: salvation exterminador do futuro 4 terminator 4 - salvation terminator 4 : renaissance terminator la salvación терминатор: да придёт спаситель terminator 4: salvación terminator 4 (director''s cut) terminator salvation: the future begins terminator: la salvación terminator - la salvación t4: salvation терминатор да придёт спаситель εξολοθρευτής: η σωτηρία exterminador do futuro 4 - a salvação 터미네이터: 미래전쟁의 시작 terminator - salvation terminator - salvation  (directors cut) terminator 4 - terminator renaissance 터미네이터 4, 미래전쟁의 시작 terminator 4 - die erlösung terminator 4 - renaissance terminator 4 renaissance 终结者2018 เทอร์มิเนเตอร์ 4 : มหาสงครามจักรกลล้างโลก 未來戰士：未來救贖 terminator 4 - terminator salvation 终结者4 终结者4：救世军 终结者4：救世主 未来战士2018 kẻ huỷ diệt: cứu rỗi terminator salvation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-quai-thu-thien-ha-ultra', 'Đại Chiến Quái Thú: Thiên Hà Ultra', 'Mega Monster Battle: Ultra Galaxy Legends The Movie', 'https://phimimg.com/upload/vod/20250727-1/0145ba01ee14ae3c95f6265cbe298968.jpg', 'https://phimimg.com/upload/vod/20250727-1/e49db21b664463783475d4cae772b502.jpg', '<p>Khi một thế lực tà ác cổ đại mang tên Ultraman Belial hồi sinh và chiếm lấy sức mạnh của 100 con quái thú, cả thiên hà rơi vào nguy hiểm. Để ngăn chặn thảm họa, các Ultraman huyền thoại như Ultraman Zero, Ultraman Mebius và nhiều chiến binh ánh sáng khác phải hợp sức chống lại đội quân quái vật hùng mạnh. Với những trận chiến mãn nhãn, kỹ xảo ấn tượng và thông điệp về lòng dũng cảm, Đại Chiến Quái Thú là món quà dành cho người hâm mộ ở mọi thế hệ.</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shota Minami","avatar":""},{"name":"Susumu Kurobe","avatar":""},{"name":"Kohji Moritsugu","avatar":""},{"name":"Takeshi Tsuruno","avatar":""},{"name":"Shunji Igarashi","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Hiroyuki Miyasako","avatar":""},{"name":"Hiroyuki Konishi","avatar":""},{"name":"Saki Kamiryô","avatar":""},{"name":"Mitsutoshi Shundo","avatar":""},{"name":"Junichiro Koizumi","avatar":""},{"name":"Masaaki Yajima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大怪兽格斗：超银河传说 THE MOVIE","울트라맨 극장판: 우주 몬스터 대결전","극장판 울트라맨 우주 몬스터 대결전","Mega Monster Battle Ultra Galaxy Legends","大怪獣バトル ウルトラ銀河伝説 THE MOVIE"]', 1784690324476);
