INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-chang-quy-tu', 'Bốn Chàng Quý Tử', 'The Sons Of Sol Pharmacy House', 'https://phimimg.com/upload/vod/20250705-1/14febdc1fdca1b8edb22e444db643287.jpg', 'https://phimimg.com/upload/vod/20250705-1/10308b2cee3ef3d388f8b931d36dbefd.jpg', '<p>Song Jin Poong là con trai cả trong gia đình có bốn anh em và anh luôn chăm chỉ làm việc để kiếm tiền nuôi cả nhà. Anh cũng là người không thể quên được mối tình đầu của mình. Mẹ anh, bà Ok Hee, muốn anh kết hôn vì anh đã 38 tuổi. Bà Ok Hee tin rằng các con trai của mình đều là những người đàn ông lý tưởng, và bất kỳ người phụ nữ nào cưới được họ đều là may mắn. Tuy nhiên, hàng xóm lại không nghĩ vậy, bởi mỗi người con trai trong nhà đều có một vấn đề riêng biệt.</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Lee Pil-mo","avatar":""},{"name":"Han Sang-jin","avatar":""},{"name":"Ji Chang-wook","avatar":""},{"name":"Yoo Ha-na","avatar":""},{"name":"Park Sun-young","avatar":""},{"name":"Yu Seon","avatar":""},{"name":"Song Eun-Chae","avatar":""},{"name":"Baek Il-seob","avatar":""},{"name":"Yoon Mi-ra","avatar":""},{"name":"Byun Hee-bong","avatar":""},{"name":"Kim Yong-geon","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Choi Ji-na","avatar":""},{"name":"Pang Eun-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["My Too Perfect Sons","솔약국집 아들들"]', 1784690324477);
