INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-nao-shinjuku', 'Đại Náo Shinjuku', 'Shinjuku Incident', 'https://phimimg.com/upload/vod/20250607-1/0cb4db5a8b3d3e9c963ffb04d2e2c42a.jpg', 'https://phimimg.com/upload/vod/20250607-1/b61f74f49cecc38cf7d343d1bb2dc4da.jpg', '<p>Bộ phim lấy bối cảnh những năm đầu thập niên 1990, được dựng trên câu chuyện có thật về một người đàn ông Trung Quốc vì tìm bạn gái mất tích mà phải nhập cư bất hợp pháp vào đất Nhật Bản. Để kiếm sống, anh ta đã phải làm mọi nghề dù thấp hèn ở vùng Shinjuku. Nhưng khi phát hiện bạn gái của mình đã kết hôn với một tay anh chị của Yakuza, người đàn ông quyết định định cư tại Nhật bản và để có được quyền nhập cư hợp pháp, anh ta đã đồng ý làm việc cho băng nhóm xã hội đen Eguchi. Chẳng mấy chốc, anh ta đã làm quen với quyền lực, với chém giết và bị lôi kéo vào giới xã hội đen đến mức không thể nào quay đầu lại được nữa…</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Xu Jinglei","avatar":""},{"name":"Masaya Katō","avatar":""},{"name":"Toru Minegishi","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Kenya Sawada","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Kathy Tong Yee","avatar":""},{"name":"Teddy Lin","avatar":""},{"name":"Hiro Hayama","avatar":""},{"name":"Wong Wai-Fai","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Gladys Fung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Jackie Chan in Shinjuku Incident","Kanli hesaplasma","la Vendetta del Dragone","O ektelestis tis Yakuza","Xin Su Shi Jian","Shinjuku Incident: Guerre des gangs à Tokyo","Shinjuku Incident","Stadt der Gewalt","新宿事件","しんじゅくインシデント","حادثه شین جوکو","حادثه در شینجوکو","Инцидент в Шинджуку"]', 1784690324477);
