INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-hoang-tu-lai', 'Harry Potter và Hoàng Tử Lai', 'Harry Potter and the Half-Blood Prince', 'https://phimimg.com/upload/vod/20250602-1/706ab376e08478b0956f619ffad48a76.jpg', 'https://phimimg.com/upload/vod/20250602-1/6daf44b2ebbfdcd811af13d89589fada.jpg', '<p>Đây là năm thứ 6 của Harry Potter tại trường Hogwarts. Trong lúc những thế lực hắc ám của Voldemort gieo rắc nỗi kinh hoàng và sợ hãi ở khắp nơi, mọi chuyện càng lúc càng trở nên rõ ràng hơn đối với Harry, cậu sẽ sớm phải đối diện với định mệnh của mình. &nbsp;Draco Malfoy, kẻ thù không đội trời chung của Harry, có nhiều hành động khả nghi, luôn lén lút đi khắp trường. Vì thế, Harry cho rằng Draco là nội gián của Voldermort và quyết tâm tìm hiểu chính xác chuyện gì đang xảy ra...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Bonnie Wright","avatar":""},{"name":"Jessie Cave","avatar":""},{"name":"Evanna Lynch","avatar":""},{"name":"Freddie Stroma","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Julie Walter","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Harry Potter en de Halfbloed Prins","Harry Potter y el Príncipe Mestizo","Harry Potter och Halvblodsprinsen","Harry Potter e o Enigma do Príncipe","해리포터와 혼혈 왕자","해리포터와 혼혈왕자","해리 포터와 혼혈왕자","Гарри Поттер и Принц-полукровка","ハリー・ポッターと謎のプリンス","ハリーポッターと謎のプリンス","הרי פותר הנסיך חצוי הדם","Harry Potter ja segavereline prints","哈利·波特与混血王子","แฮร์รี่ พอตเตอร์กับเจ้าชายเลือดผสม","Harry Potter et le Prince de sang-mêlé","Հարրի Փոթերը և Խառնածին արքայազնը","Harry Potter Half Blood Prince","Harry Potter 6","Harry Potter 6 - Half-Blood Prince","Harry Potter 6 - The Half-Blood Prince","هاري بوتر والأمير الهجين","Harry Potter and the Half-Blood Prince"]', 1784690324477);
