INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-hoang-tu-lai', 'Harry Potter và Hoàng Tử Lai', 'Harry Potter and the Half-Blood Prince', 'harry potter và hoàng tử lai harry potter and the half-blood prince daniel radcliffe rupert grint emma watson jim broadbent michael gambon tom felton alan rickman bonnie wright jessie cave evanna lynch freddie stroma robbie coltrane helena bonham carter maggie smith timothy spall david thewlis julie walter harry potter en de halfbloed prins harry potter y el príncipe mestizo harry potter och halvblodsprinsen harry potter e o enigma do príncipe 해리포터와 혼혈 왕자 해리포터와 혼혈왕자 해리 포터와 혼혈왕자 гарри поттер и принц-полукровка ハリー・ポッターと謎のプリンス ハリーポッターと謎のプリンス הרי פותר הנסיך חצוי הדם harry potter ja segavereline prints 哈利·波特与混血王子 แฮร์รี่ พอตเตอร์กับเจ้าชายเลือดผสม harry potter et le prince de sang-mêlé հարրի փոթերը և խառնածին արքայազնը harry potter half blood prince harry potter 6 harry potter 6 - half-blood prince harry potter 6 - the half-blood prince هاري بوتر والأمير الهجين harry potter and the half-blood prince', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-thit-vien', 'Cơn Mưa Thịt Viên', 'Cloudy With A Chance Of Meatballs', 'https://phimimg.com/upload/vod/20250526-1/0a774d94723e70479c066e4c759a8ba1.jpg', 'https://phimimg.com/upload/vod/20250526-1/56c8b82c5cf5ae2c8f862e6d86d68c3e.jpg', '<p>Flint Lockwood, một nhà sáng chế trẻ vô cùng dễ thương, sống độc thân cùng chú khỉ lém lỉnh Steve. Anh đã quyết định không theo nghề bán cà mòi truyền thống mấy đời của gia đình Lockwood mà lại đâm đầu vào phòng thí nghiệm với những phát mình vô cùng “tai hại”.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Hader","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"James Caan","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Mr. T","avatar":""},{"name":"Bobb''e J. Thompson","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Al Roker","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Max Neuwirth","avatar":""},{"name":"Peter Siragusa","avatar":""},{"name":"Angela Shelton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Liz Cackowski","avatar":""},{"name":"Isabella A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Облачно, возможны осадки в виде фрикаделек!","食破天惊","美食风球","Oblacno, sem-tam fasirky","美食从天而降","하늘에서 음식이 내린다면","Cơn Mưa Thịt Viên","食破天驚","Skýjað með kjötbollum á köflum","くもりときどきミートボール","Köfte Yağmuru","Parçalı Bulutlu Köfte Yağabilir","Cloudy with a Chance of Meatballs"]', 1784690324477);
