INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-mua-thit-vien', 'Cơn Mưa Thịt Viên', 'Cloudy With A Chance Of Meatballs', 'cơn mưa thịt viên cloudy with a chance of meatballs bill hader anna faris james caan andy samberg bruce campbell mr. t bobb''e j. thompson benjamin bratt neil patrick harris al roker lauren graham will forte max neuwirth peter siragusa angela shelton neil flynn liz cackowski isabella a облачно, возможны осадки в виде фрикаделек! 食破天惊 美食风球 oblacno, sem-tam fasirky 美食从天而降 하늘에서 음식이 내린다면 cơn mưa thịt viên 食破天驚 skýjað með kjötbollum á köflum くもりときどきミートボール köfte yağmuru parçalı bulutlu köfte yağabilir cloudy with a chance of meatballs', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-lich-su-khai-pha-vu-tru', 'Doraemon: Nobita và Lịch Sử Khai Phá Vũ Trụ', 'Doraemon: The New Record of Nobita''s Spaceblazer', 'https://phimimg.com/upload/vod/20250521-1/b4e3ddb1029d099aeee005a124350d63.jpg', 'https://phimimg.com/upload/vod/20250521-1/1db0ad9842e56cf8c0c835fea9652e3d.jpg', '<p>Nhờ vào hiện tượng thần giao cách cảm mà Nobita và Doraemon quen được 2 người bạn:Roppu và Chamy-cư dân hành tinh Koyakoya dưới không gian nền nhà căn phòng của Nobita do sự rối loạn không gian. Qua các buổi trò chuyện nên Doraemon và Nobita biết được hành tinh Đen có ý định cướp đoạt hành tinh Koyakoya để lấy đi Viên Đá Li Tâm-1 vật báu của hành tinh-tính năng gần giống như chong chóng tre nên Doraemon và Nobita giúp hành tinh Koyakoya đuổi bọn hành tinh Đen. Vì sự khác biệt về lực hấp dẫn nên khi Doraemon và Nobita ở hành tinh Koyakoya đã trở thành siêu nhân. Trong các trận chiến đã không có sự tham gia của Shizuka, Jaian và Suneo(vì lần trước do sân bóng bị mấy anh lớp trên chiếm nên nhóm bạn đã lên hành tinh Koyakoya chơi tạm nhưng không may lại bị người hành tinh Đen tấn công, sợ và bỏ về) cho đến khi Giramin đặt thiết bị nổ hòng phá huỷ hành tinh này Chamy đã đến cầu cứu và trận chiến đã trở nên gay cấn hơn khi có sự tham gia của Dorami.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2009, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Karina","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Ayaka Wilson","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["新宇宙開拓史","新・のび太の宇宙開拓史","新・大雄的宇宙开拓史","Eiga Doraemon Shin Nobita No Uchu Kaitakushi","The New Record of Nobita''s Spaceblazer","新大雄的宇宙開拓史","도라에몽: 신 노비타의 우주개척사","哆啦A夢：新·大雄的宇宙開拓史","Doraemon the Movie: Adventures of Koya Koya Planet","โนบิตะนักบุกเบิกอวกาศ","電影哆啦A夢：新大雄的宇宙開拓史","Doraemon the Movie: The New Records of Nobita''s Spaceblazer","Doraemon.The.Movie：The.New.Record.Of.Nobita-Spaceblazer","극장판 도라에몽: 신 진구의 우주개척사","극장판 도라에몽: 진구의 신 우주개척사","도라에몽 극장판: 진구의 신 우주개척사","映画ドラえもん 新・のび太の宇宙開拓史"]', 1784690324477);
