INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-lich-su-khai-pha-vu-tru', 'Doraemon: Nobita và Lịch Sử Khai Phá Vũ Trụ', 'Doraemon: The New Record of Nobita''s Spaceblazer', 'doraemon: nobita và lịch sử khai phá vũ trụ doraemon: the new record of nobita''s spaceblazer wasabi mizuta megumi oohara yumi kakazu tomokazu seki karina subaru kimura ayaka wilson 新宇宙開拓史 新・のび太の宇宙開拓史 新・大雄的宇宙开拓史 eiga doraemon shin nobita no uchu kaitakushi the new record of nobita''s spaceblazer 新大雄的宇宙開拓史 도라에몽: 신 노비타의 우주개척사 哆啦a夢：新·大雄的宇宙開拓史 doraemon the movie: adventures of koya koya planet โนบิตะนักบุกเบิกอวกาศ 電影哆啦a夢：新大雄的宇宙開拓史 doraemon the movie: the new records of nobita''s spaceblazer doraemon.the.movie：the.new.record.of.nobita-spaceblazer 극장판 도라에몽: 신 진구의 우주개척사 극장판 도라에몽: 진구의 신 우주개척사 도라에몽 극장판: 진구의 신 우주개척사 映画ドラえもん 新・のび太の宇宙開拓史', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-4', 'Lưỡi Hái Tử Thần 4', 'The Final Destination (Final Destination 4)', 'https://phimimg.com/upload/vod/20250519-1/114c8de49486cb31296bc77ffc75d62a.jpg', 'https://phimimg.com/upload/vod/20250519-1/7486aae1f521fe5ae9f395733d6ac32c.jpg', '<p>Tai nạn sẽ xảy ra liên hoàn, những chiếc xe va chạm mạnh rồi bất ngờ lao lên khán đài giết chết nhiều người đang hào hứng theo dõi cuộc đua... Nick giật mình trước điềm báo mình đang cảm thấy và vội vàng thuyết phục bạn gái Lori của anh và một số người khác rời trường đua ngay tức khắc. Khi họ chỉ vừa kịp thoát khỏi trường đua vài giây thì tai nạn thảm khốc đúng như những gì Nick linh cảm được đã diễn ra ngay trước mắt anh. Nhưng không may cho Nick và các bạn, tất cả không hề kết thúc ở đây, mà chỉ mới là sự bắt đầu. Không ai thoát khỏi Thần Chết một khi đã có tên trong sổ tử. Để cứu lấy chính mình, họ phải tìm ra đâu là đường đi của Thần Chết trước khi phải đối diện với “trạm cuối” của mình...</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bobby Campo","avatar":""},{"name":"Shantel VanSanten","avatar":""},{"name":"Nick Zano","avatar":""},{"name":"Haley Webb","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Krista Allen","avatar":""},{"name":"Andrew Fiscella","avatar":""},{"name":"Justin Welborn","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"Lara Grice","avatar":""},{"name":"Jackson Walker","avatar":""},{"name":"Phil Austin","avatar":""},{"name":"William Aguillard","avatar":""},{"name":"Brendan Aguillard","avatar":""},{"name":"Juan Kincaid","avatar":""},{"name":"Monique Detraz","avatar":""},{"name":"Chris","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Final Destination: Death Trip","El Destino Final (Destino Final 4)","Oszukać Przeznaczenie 4","The Final Destination in 3-D","Destino Final 4","مقصد نهایی 4","Destination Finale 4","The Final Destination 3D","โกงตาย ทะลุตาย","La Destination Ultime","Lưỡi Hái Tử Thần 4","死神4來了","Final Destination 4","絕命終結站4","ファイナル・デッドサーキット 3D","Premonição 4","死神来了4","The Final Destination 4","The Final Destination"]', 1784690324477);
