INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sinh-tu-chien', 'Sinh Tử Chiến', 'The King of Fighters', 'sinh tử chiến the king of fighters sean faris maggie q ray park will yun lee david leitch françoise yip hiro kanagawa bernice jan liu monique ganderton doug abrahams candus churchill robin nielsen scott patey toshi haraguchi sam hargrave 拳皇 格斗之王 the king of fighters la pelicula the king of fighters', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phineas-va-ferb-phan-2', 'Phineas Và Ferb (Phần 2)', 'Phineas And Ferb (Season 2)', 'https://phimimg.com/upload/vod/20250504-1/34a4700e9e10db8b31cca09d5a7e5078.jpg', 'https://phimimg.com/upload/vod/20250504-1/818dd1b91b3ac7cb81c4074806d9d78d.jpg', '<p>Phineas và Ferb là những cậu bé thông minh và tháo vát. Cả hai cậu đã dành thời gian cả mùa hè để thực hiện những kế hoạch khó tin (dựng đường xe trượt quanh thành phố, làm bãi biển ở sân sau, trở thành ca sĩ…) với sự trợ giúp của cô bé Isabella và nhóm bạn của cô. Tuy nhiên Candace lại thường không đồng tình với những việc làm của hai đứa em và cô luôn tìm cách mách mẹ cho bằng được. Thế nhưng khi mẹ của ba chị em về đến nơi thì tất cả mọi dấu vết đều bị xóa sạch một cách ngẫu nhiên và chưa lần nào Candace thành công trong việc vạch tội hai cậu em cả.

Song song với Phineas và Ferb, phim còn có một mạch truyện khác kể về Perry. Perry là thú mỏ vịt được nuôi trong nhà của hai anh em nhưng thực ra cậu là một điệp viên bí mật (Agent P). Perry có nhiệm vụ chống lại những âm mưu điên rồ và ngớ ngẩn của nhà bác học – tiến sĩ Heinz Doofenshmirtz.</p>', 'Hoàn Tất (39/39)', 39, 'hoathinh', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Vincent Martella","avatar":""},{"name":"David Errigo Jr.","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Caroline Rhea","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Dan Povenmire","avatar":""},{"name":"Jeff ''Swampy'' Marsh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Финиъс и Фърб","Phineas e Ferb","Phineas und Ferb","Phineas og Ferb","Phinéas et Ferb","Phineas en Ferb","فارس وفادي","Phineas och Ferb","Phineas & Ferb","Phineas và Ferb","Phineas and Ferb"]', 1784690324477);
