INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phineas-va-ferb-phan-2', 'Phineas Và Ferb (Phần 2)', 'Phineas And Ferb (Season 2)', 'phineas và ferb (phần 2) phineas and ferb (season 2) vincent martella david errigo jr. ashley tisdale caroline rhea dee bradley baker alyson stoner dan povenmire jeff ''swampy'' marsh финиъс и фърб phineas e ferb phineas und ferb phineas og ferb phinéas et ferb phineas en ferb فارس وفادي phineas och ferb phineas & ferb phineas và ferb phineas and ferb', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-ngot-ngao', 'Khoảnh Khắc Ngọt Ngào', 'Hi My Sweetheart', 'https://phimimg.com/upload/vod/20250424-1/91ada0ad1bff8c1c68ea4bfd3748dcb5.jpg', 'https://phimimg.com/upload/vod/20250424-1/b98f8f83c103a8f03c44305205ce796e.jpg', '<p>Tiết Hải (La Chí Tường) là một công tử nhà giàu, sống dưới sự bảo bọc của hai người chị gái. Khao khát tự lập, anh quyết định sang Hàng Châu du học và lấy tên giả Lâm Đạt Lãng, giả vờ là một sinh viên nghèo để tránh bị chú ý. Tại đây, anh gặp Trần Bảo Châu (Dương Thừa Lâm), một cô gái cá tính và mạnh mẽ. Cô đã giúp đỡ anh khi bị bắt nạt, và từ đó, hai người bắt đầu một mối tình ngọt ngào. Tuy nhiên, biến cố xảy ra khi gia đình Bảo Châu phá sản, khiến cô phải trở về Đài Loan và mất liên lạc với Đạt Lãng. Hiểu lầm rằng mình bị bỏ rơi, <span style="text-wrap-mode: wrap;">Tiết Hải</span> trở nên lạnh lùng và quyết định trả thù. Anh mua lại đài phát thanh nơi <span style="text-wrap-mode: wrap;">Bảo Châu</span> làm việc và lên kế hoạch trả thù khiến cô đau khổ....</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 29, 2009, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"La Chí Tường","avatar":""},{"name":"Dương Thừa Lâm","avatar":""},{"name":"Lý Vi","avatar":""},{"name":"Ngô Á Hinh","avatar":""},{"name":"Phương Phương","avatar":""},{"name":"Hướng Ngữ Kiệt","avatar":""},{"name":"Vương Nguyệt","avatar":""},{"name":"Giang Kỳ Lâm","avatar":""},{"name":"Địch Bồi Huệ","avatar":""},{"name":"Thiệu Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["海派甜心"]', 1784690324477);
