INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-giac-quy', 'Tam Giác Quỷ', 'Triangle', 'https://phimimg.com/upload/vod/20250417-1/61b7407b73e4dc8ea6bfaef48226a846.jpg', 'https://phimimg.com/upload/vod/20250417-1/88a06ef1cb5e59d026460849f83f9aeb.jpg', '<p>Jess luôn có linh cảm rằng cô sẽ gặp một việc gì đó rất dữ dội khi cô cùng nhóm bạn du thuyền đến bến cảng địa phương. Và rồi một cơn bão ập đến khiến cho các bạn trẻ phải tấp vào một con tàu bỏ hoang. Không một ai, đồng hồ đã dừng lại, và họ không đơn độc. Có ai đó đang cố gắng săn họ, từng người một. Và họ phát hiện ra họ đang bị kẹt trong một vòng lặp kỳ lạ. Jess hoàn toàn bị mất phương hướng, không thể tìm thấy tung tích của kẻ giết người, cứ luôn bị rình rập. Jess cần tìm được chìa khóa để kết thúc, khi đó thì đã quá muộn.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Melissa George","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Emma Lung","avatar":""},{"name":"Rachael Carpani","avatar":""},{"name":"Michael Dorman","avatar":""},{"name":"Joshua McIvor","avatar":""},{"name":"Henry Nixon","avatar":""},{"name":"Jack Taylor","avatar":""},{"name":"Bryan Probets","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Треугольник","Triângulo do Medo","トライアングル","El Triángulo","Triangulo","트라이앵글","트라이앵글 타임루프","迷失三角洲","轮回三角","恐怖游轮","Bermuda háromszög","汪洋血迷宮","Triangle"]', 1784690324477);
