INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-3-khung-long-thuc-giac', 'Kỷ Băng Hà 3: Khủng Long Thức Giấc', 'Ice Age: Dawn of the Dinosaurs', 'https://phimimg.com/upload/vod/20250412-1/43da5b2427ecd5f70e112b703b319903.jpg', 'https://phimimg.com/upload/vod/20250412-1/a6a2d4005aeee61e2f817692f230e53e.jpg', '<p>Những nhân vật đến từ thế giới băng giá của loạt phim bom tấn Ice Age và Ice Age: The Meldown nay đã quay trở lại trong một cuộc phiêu lưu kỳ thú. Mang sứ mệnh giải cứu anh chàng Sid xui xẻo, những người anh hùng của chúng ta đã mạo hiểm dấn thân vào một thế giới bí ẩn nằm sâu dưới lòng đất, nơi trú ngụ của các loài khủng long và những quần thể thực vật và động vật hung dữ. Không chỉ vậy, cả đội còn chạm trán với Buck - một con chồn chột mắt, tính tình cổ quái, chuyên săn khủng long.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2009, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Chris Wedge","avatar":""},{"name":"Karen Disher","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Eunice Cho","avatar":""},{"name":"Harrison Fahn","avatar":""},{"name":"Maile Flanagan","avatar":""},{"name":"Jason Fricchione","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Kelly Keaton","avatar":""},{"name":"Joey King","avatar":""},{"name":"Lucas Leguizamo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ice Age 3","Epoka Lodowcowa: Era Dinozaurów","L''Âge de glace 3","Doba ledová 3","Ice Age 3 El Origen De Los Dinosaurios Dawn of the Dinosaurs","Ice Age 3: Dawn of the Dinosaurs","A Era do Gelo 3 - Amanhecer dos Dinossauros","L''Âge de glace 3: Le Temps des dinosaures","アイス・エイジ３　ティラノのおとしもの","A Idade do Gelo 3: Despertar dos Dinossauros","Ice Age 3: Dinosaurerne kommer","L''era glaciale 3 - L''alba dei dinosauri","العصر الجليدي: فجر الديناصورات","Istid 3: Dinosaurene kommer","გამყინვარების ხანა: დინოზავრების გარიჟრაჟი","Jääaeg 3 Dinosauruste džungel","Kỷ Băng Hà 3: Khủng Long Thức Giấc","冰川时代3","冰河世纪3：大威龙驾到","冰河世纪3","冰河时代3：恐龙的黎明","冰河世纪3：恐龙的黎明","Buz Dövrü 3: Dinozavrlar","아이스 에이지 3","Ледена епоха 3: Ерата на динозаврите","Ledeno doba 3 - Dinosauri dolaze","Ísöld: Risaeðlurnar vakna!","Ice Age: Dawn of the Dinosaurs"]', 1784690324477);
