INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-bang-ha-3-khung-long-thuc-giac', 'Kỷ Băng Hà 3: Khủng Long Thức Giấc', 'Ice Age: Dawn of the Dinosaurs', 'kỷ băng hà 3: khủng long thức giấc ice age: dawn of the dinosaurs ray romano john leguizamo denis leary queen latifah simon pegg seann william scott josh peck chris wedge karen disher kristen wiig eunice cho harrison fahn maile flanagan jason fricchione bill hader kelly keaton joey king lucas leguizamo ice age 3 epoka lodowcowa: era dinozaurów l''âge de glace 3 doba ledová 3 ice age 3 el origen de los dinosaurios dawn of the dinosaurs ice age 3: dawn of the dinosaurs a era do gelo 3 - amanhecer dos dinossauros l''âge de glace 3: le temps des dinosaures アイス・エイジ３　ティラノのおとしもの a idade do gelo 3: despertar dos dinossauros ice age 3: dinosaurerne kommer l''era glaciale 3 - l''alba dei dinosauri العصر الجليدي: فجر الديناصورات istid 3: dinosaurene kommer გამყინვარების ხანა: დინოზავრების გარიჟრაჟი jääaeg 3 dinosauruste džungel kỷ băng hà 3: khủng long thức giấc 冰川时代3 冰河世纪3：大威龙驾到 冰河世纪3 冰河时代3：恐龙的黎明 冰河世纪3：恐龙的黎明 buz dövrü 3: dinozavrlar 아이스 에이지 3 ледена епоха 3: ерата на динозаврите ledeno doba 3 - dinosauri dolaze ísöld: risaeðlurnar vakna! ice age: dawn of the dinosaurs', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-phap-su-phan-1', 'Hội Pháp Sư (Phần 1)', 'Fairy Tail (Season 1)', 'https://phimimg.com/upload/vod/20250406-1/bed295645f98472bc855cee2bdb8238f.jpg', 'https://phimimg.com/upload/vod/20250406-1/6529e5eb413c7eb31b19fbb5597e4ed0.jpg', '<p>Bộ Phim Hội Pháp Sư có nội dung chính về Lucy, cô gái trẻ 17 tuổi với mong ước trở thành một pháp sư đầy quyền năng. Trên đường phiêu lưu thực hiện ước mơ, Lucy tình cờ gặp được một bộ đôi quái gở - Natsu và Happy, đang trên đường tìm kiếm Hỏa Long Igneel - tại Thị trấn Hargeon. Ước mơ của Lucy là được tham gia vào Bang hội, nơi tập trung đầy pháp sư tài giỏi.</p>', 'Hoàn Tất (175/175)', 175, 'hoathinh', 'completed', 15, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Wataru Hatano","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Mai Nakahara","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Ryoko Ono","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Shinpachi Tsuji","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c8