INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vut-bay', 'Vút Bay', 'Up', 'https://phimimg.com/upload/vod/20250327-1/c2bcdc09dfb3a9d4c6d0346095da4f92.jpg', 'https://phimimg.com/upload/vod/20250327-1/fdb16a2634f370f8292393ff14b435b4.jpg', '<p>Ông già Carl quyết hoàn thành chuyến đi ấp ủ cả đời tới Thác thiên đường bằng ngôi nhà kết hàng nghìn quả bóng bay. Ngay khi vừa &quot;cất cánh&quot;, ông phát hiện ra người đồng hành bất đắc dĩ: Cậu bé hướng đạo sinh Russell lắm mồm. Kể từ đây, cuộc phiêu lưu kì thú của 2 ông cháu diễn ra với biết bao bất ngờ cùng nguy hiểm rình rập...</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ed Asner","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Jordan Nagai","avatar":""},{"name":"Bob Peterson","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Jerome Ranft","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"David Kaye","avatar":""},{"name":"Elie Docter","avatar":""},{"name":"Jeremy Leary","avatar":""},{"name":"Mickie McGowan","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Donald Fullilove","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Josh Cooley","avatar":""},{"name":"Pete Docter","avatar":""},{"name":"Mark Andrews","avatar":""},{"name":"Bob Bergen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Vzhuru do oblak","Baala","Aukstyn","Up - Una aventura de altura","Up, una aventura de altura","Do neba","Yukarı Bak","Oben","Up, Una aventura de altura Pixar","Là-haut","فوق","Vút Bay","Yuxarı Bax","飞屋环游记"