INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-coraline', 'Cô Bé Coraline', 'Coraline', 'https://phimimg.com/upload/vod/20250326-1/22b856d118dfa183dd1d99b12f27a132.jpg', 'https://phimimg.com/upload/vod/20250326-1/444379cb6646d97cb4db15bfe5bea277.jpg', '<p>Khi Coraline chuyển đến một ngôi nhà cũ, cô cảm thấy buồn chán và bị cha mẹ bỏ rơi. Cô tìm thấy một cánh cửa ẩn với một lối đi bằng gạch. Trong đêm, cô băng qua hành lang và tìm thấy một thế giới song song, nơi mọi người đều có nút thay vì mắt, với cha mẹ chăm sóc và tất cả ước mơ của cô đều trở thành sự thật. Khi Người Mẹ khác mời Coraline ở lại thế giới của mình mãi mãi, cô gái từ chối và thấy rằng thực tế thay thế nơi cô bị mắc kẹt chỉ là một thủ thuật để thu hút cô.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dakota Fanning","avatar":""},{"name":"Teri Hatcher","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Dawn French","avatar":""},{"name":"Keith David","avatar":""},{"name":"John Hodgman","avatar":""},{"name":"Robert Bailey Jr.","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Aankha Neal","avatar":""},{"name":"George Selick","avatar":""},{"name":"Hannah Kaiser","avatar":""},{"name":"Harry Selick","avatar":""},{"name":"Marina Budovsky","avatar":""},{"name":"Emerson Tenney","avatar":""},{"name":"Jerome Ranft","avatar":""},{"name":"Christopher Murrie","avatar":""},{"name":"Jeremy Ryd","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["第十四道門","Coraline Y La Puerta Secreta","Coraline 3D","Coraline en de Geheime Deur","Коралайн и тайната на огледалото","Koralina i Tajna Ogledala","Coraline e a Porta Secreta","Коралина в Стране Кошмаров","コララインとボタンの魔女 ３Ｄ","კორალაინი","コララインとボタンの魔女 3D","Los mundos de Coraline","Կորալինե","코렐라인","Кораліна","Coraline"]', 1784690324477);
