INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kamen-rider-hiep-si-rong-sieu-nhan-phi-long', 'Kamen Rider: Hiệp Sĩ Rồng (Siêu Nhân Phi Long)', 'Kamen Rider: Dragon Knight', 'https://phimimg.com/upload/vod/20250320-1/a25828779e4eb32f094129b73ca384d6.jpg', 'https://phimimg.com/upload/vod/20250320-1/3b7a2c03bab5f35028b1db916394c3c8.jpg', '<p>Kamen Rider: Dragon Knight là một bộ phim truyền hình siêu anh hùng khoa học viễn tưởng của Mỹ, từng được phát sóng trên kênh The CW trong khung chương trình CW4Kids, từ ngày 13 tháng 12 năm 2008 đến ngày 26 tháng 12 năm 2009. Đây là phiên bản chuyển thể từ loạt phim tokusatsu Nhật Bản Kamen Rider Ryuki, và là tác phẩm thứ hai trong thương hiệu Kamen Rider được làm lại dành cho khán giả Mỹ, sau Masked Rider của Saban ra mắt năm 1995. Bộ phim do Steve và Michael Wang phát triển cho truyền hình, được sản xuất bởi Jimmy Sprague thông qua công ty Adness Entertainment.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stephen Ford","avatar":""},{"name":"Matt Mullins","avatar":""},{"name":"Marisa Lauren","avatar":""},{"name":"Yvonne Arias","avatar":""},{"name":"William O''Leary","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kamen Rider: O Cavaleiro Dragão","Kamen Rider: el caballero dragón","カメンライダー ドラゴンナイト","カメンライダードラゴンナイト","仮面ライダードラゴンナイト","가면 라이더 드래곤 나이트","คาเมนไรเดอร์ดราก้อนไนท์","Kamen Rider: Los caballeros dragón","Kamen Rider: Dragon Knight"]', 1784690324477);
