INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kamen-rider-hiep-si-rong-sieu-nhan-phi-long', 'Kamen Rider: Hiệp Sĩ Rồng (Siêu Nhân Phi Long)', 'Kamen Rider: Dragon Knight', 'kamen rider: hiệp sĩ rồng (siêu nhân phi long) kamen rider: dragon knight stephen ford matt mullins marisa lauren yvonne arias william o''leary kamen rider: o cavaleiro dragão kamen rider: el caballero dragón カメンライダー ドラゴンナイト カメンライダードラゴンナイト 仮面ライダードラゴンナイト 가면 라이더 드래곤 나이트 คาเมนไรเดอร์ดราก้อนไนท์ kamen rider: los caballeros dragón kamen rider: dragon knight', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-sieu-nhan-do', '10 Siêu Nhân Đỏ', 'Forever Red', 'https://phimimg.com/upload/vod/20250320-1/d51d8772b6b9bd0dbe9f94ec22f0ec0c.jpg', 'https://phimimg.com/upload/vod/20250320-1/ba2f81732c6b36eeadb3e27b7d6be7e9.jpg', '<p>Bốn năm sau khi Đế chế Máy móc bị phá hủy , những thành viên sống sót của đế chế vẫn tìm cách phá hủy Trái đất (làm thế nào họ sống sót sau Đế chế Đế chế Hủy diệt vẫn chưa rõ ràng). Tezzla , Gerrok , Steelon và Automon (và nhiều Cog ) là tất cả những gì còn sót lại của Đế chế hùng mạnh và đáng tự hào một thời cũng như Tướng Venjix , đóng vai trò là thủ lĩnh. Họ biết rằng Mặt trăng của Trái đất là nơi an nghỉ của Serpentera , Zord do Chúa tể Zedd tạo ra và sử dụng với sức mạnh phá hủy một hành tinh. Kể từ khi &quot;cái chết&quot; của Zedd trong Đế chế Đếm ngược đến Hủy diệt , vị trí của Serpentera vẫn là một bí ẩn trong nhiều năm. Venjix tìm thấy nó và bắt đầu sử dụng những người lính Cog để đào nó lên, lắp lại lò phản ứng Neo Plutonium để cung cấp năng lượng cho nó.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Power Rangers: Zeo","Power Rangers: Turbo","Power Rangers: Tempestade Ninja","Power Rangers: Galáxia Perdida","Power Rangers: Dino Trovão","Power Rangers: Força do Tempo","Power Rangers: No Espaço","Power Rangers: SPD","Power Rangers: Força Animal","Po