INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-seondeok', 'Nữ Hoàng Seondeok', 'The Great Queen Seondeok', 'https://phimimg.com/upload/vod/20250316-1/6cf61a3fadac23e8a36efa7f5bc7923f.jpg', 'https://phimimg.com/upload/vod/20250316-1/c409fad45fafc0dc3b983a4a81262291.jpg', '<p>Khi còn nhỏ, Công chúa Deokman may mắn thoát chết trong một vụ mưu sát do Mi Sil chủ mưu. Năm 15 tuổi, biết được thân phận thực của mình, Deokman quyết định trở lại Shilla để gặp cha mẹ. Nhờ sự trợ lực của những người thân cận, Deokman đã tiêu diệt Mi Sil và trở thành Nữ hoàng đầu tiên trong lịch sử Hàn Quốc. Chính bà là người đã đặt nền móng cho sự thống nhất ba vương quốc Koguryeo, Baekje và Shilla.</p>', 'Hoàn Tất (62/62)', 62, 'series', 'completed', 24, 2009, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Yo-won","avatar":""},{"name":"Nam Ji-hyun","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Ko Hyun-jung","avatar":""},{"name":"Uhm Tae-woong","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Park Ye-jin","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Yoo Seung-ho","avatar":""},{"name":"Qri","avatar":""},{"name":"Park Eun-bin","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Kwak Jung-wook","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Kim Jeong-hyeon","avatar":""},{"name":"Park Jung-chul","avatar":""},{"name":"Uhm Hyo-seop","avatar":""},{"name":"Noh Young-hak","avatar":""},{"name":"Park S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee6