INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dich-2009', 'Đại Dịch', 'Carriers', 'https://phimimg.com/upload/vod/20250314-1/3c25a835f77afe2e0b8d60e49416db38.jpg', 'https://phimimg.com/upload/vod/20250314-1/f8b3d728081891fa078d0a85b5da0072.jpg', '<p>Một loại virus chết người lây lan khắp Trái đất và gây ra cái chết hàng loạt. Bốn chàng trai trẻ đang trên đường đến miền Tây nước Mỹ với niềm vui hiện rõ trên khuôn mặt. Mục đích của họ là trốn đến bờ biển xa xôi của Vịnh Mexico. Ở đó, họ có thể yên tâm chờ hết dịch mà vẫn sống sót. Biết đâu, kế hoạch đã hoàn toàn bị phá hỏng khi chiếc xe của họ bị hỏng trên một con đường vắng vẻ. Từ đây, một chuỗi các sự kiện xoay chuyển số phận của họ không ngừng như cuộc hành trình tăm tối đáng sợ đến các địa ngục của vùng đất phía Tây với đầy rẫy những xác sống ghê tởm và những kẻ đang đứng trên bờ vực của cái chết. Cuộc chạy trốn của họ nhanh chóng biến thành một cuộc chiến đẫm máu và đẫm nước mắt chống lại những đứa trẻ bị nhiễm bệnh, những bác sĩ giết người, những người sống sót mất trí, những con chó dại, và cuối cùng là chính họ. Chỉ hơn 4 ngày, nhóm đã phải đối mặt với những quyết định liên quan đến đạo đức và phẩm chất con người mà chưa ai từng trải qua. Sau đó, họ phát hiện ra rằng kẻ thù lớn nhất của họ không phải là con virus đáng sợ đó mà chính là bóng tối bên trong chính họ ...</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lou Taylor Pucci","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Ron McClary","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Josh Berry","avatar":""},{"name":"Tim Janis","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"LeAnne Lynch","avatar":""},{"name":"Dale O´Malley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Carriers - Flucht vor der tödlichen Seuche","病毒携带者","携带者","绝命带原者","Infectados","Portadores","Носії","末日病毒","Носители","Carriers"]', 1784690324477);
