INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-dich-2009', 'Đại Dịch', 'Carriers', 'đại dịch carriers lou taylor pucci chris pine piper perabo emily vancamp christopher meloni kiernan shipka ron mcclary mark moses josh berry tim janis dylan kenin leanne lynch dale o´malley carriers - flucht vor der tödlichen seuche 病毒携带者 携带者 绝命带原者 infectados portadores носії 末日病毒 носители carriers', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep-3', 'Tiên Kiếm Kỳ Hiệp 3', 'Chinese Paladin 3', 'https://phimimg.com/upload/vod/20250314-1/fe508fa5fc63778e2a6baee8a46ac8c2.jpg', 'https://phimimg.com/upload/vod/20250314-1/8f5347f0e9e7b16fea6d2394d6f73bdd.jpg', '<p>Phim Tiên Kiếm Kì Hiệp 3 bắt đầu vào 50 năm trước của Tiên Kiếm 1. Phim xoay quanh Thần Tướng Chấn Yêu tên là Phi Bồng trên thần giới. Vào 1000 năm trước, vì để ma tôn Trọng Lầu xâm phạm Tiên Giới cho nên Thần Giới phái binh tới bắt Phi Bồng, Phi Bồng bị rớt xuống nhân gian, biến thành Thục Sơn Trấn Yêu Kiếm, rồi trải qua nhiều kiếp luân hồi. Người quản lý Thần Thụ (cây thần) là Tịch Dao vốn yêu thầm Phi Bồng, sau khi Phi Bồng xuống nhân gian, nàng liền dùng quả của Thần Thụ chế thành nữ tử là Tuyết Kiến xuống nhân gian. Sau nhiều kiếp luân hồi, Phi Bồng &nbsp;trở thành Cảnh Thiên, một chàng trai làm chức quản lý đồ cổ ở Vĩnh An, thành Du Châu. Anh có tài nhận biết đồ cổ, rất mê tiền, tham vọng trở thành người giàu nhất thiên hạ hoặc là Thục Sơn kiếm tiên. Sau khi Cảnh Thiên tìm được Ma Kiếm thì quen biết Tuyết Kiến, từ đó cuộc sống của Cảnh Thiên cũng đổi thay.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 13, 2009, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Đường Yên","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Lưu Thi Thi","avatar":""},{"name":"Hồ Ca","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["仙剑三","仙剑奇侠传三","仙剑奇侠传三 2009","仙剑奇侠传3","Chinese Paladin 3","Chinese Paladin III","Sword and Fairy 3","Tiên kiếm kỳ hiệp truyện 3"]', 1784690324477);
