INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-tam-ke', 'Cung Tâm Kế', 'Beyond The Realm Of Conscience', 'https://phimimg.com/upload/vod/20250305-1/a6629816ca8ad3292d4f1e6a11a616a0.jpg', 'https://phimimg.com/upload/vod/20250305-1/1330981d6ae9d5028b71c866c5e8b23c.jpg', '<p>Hậu cung nhà Đường với bốn Thượng cung nắm toàn bộ quyền lực, ra sức tranh giành, dùng mọi thủ đoạn đê hèn để triệt hạ nhau. Tuy nhiên sự tham chiến bất ngờ của hai tân quý phi được sủng ái là Kim Linh đầy dã tâm và nàng Tam Hảo hiền lành đã khiến tình thế xoay chuyển ngoạn mục, khiến hậu cung không ngừng dậy sóng.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 12, 2009, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Xa Thi Mạn","avatar":""},{"name":"Dương Di","avatar":""},{"name":"Trần Hào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["刘三好","Beyond The Realm Of Conscience","宫心计","宮心計"]', 1784690324477);
