INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-dai-hoa-2012', 'Năm Đại Họa 2012', '2012', 'https://phimimg.com/upload/vod/20250219-1/34b0feb56420d68056f60fd0672b60d5.jpg', 'https://phimimg.com/upload/vod/20250219-1/a0f933e3b1139aab8735e146c6df18c9.jpg', '<p>Bộ phim là một viễn cảnh được dựng lên về tương lai của Trái Đất vào năm &quot;đại họa&quot; năm 2012. Thay vì đề cập đến các trận động đất hay các đợt thủy triều khổng lồ như trong phim 2012 thì bộ phim lại miêu tả 2012 là năm của kỷ băng hà, một kỷ nguyên mới mà băng hà sẽ thống trị Trái Đất. Siêu núi lửa Fuji phun trào mây mù dày đặc bao phủ khắp nơi trên Trái Đất, nhân loại phải đối mặt với một sự diệt chủng mới, không ánh nắng mặt trời, nhiệt độ ngày càng hạn thấp. Và một nhóm nhà khoa học đã chiến đấu để ngăn chặn kỷ nguyên băng hà mới...</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Liam James","avatar":""},{"name":"Morgan Lily","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Beatrice Rosen","avatar":""},{"name":"Alexandre Haussmann","avatar":""},{"name":"Philippe Haussmann","avatar":""},{"name":"Johann Urb","avatar":""},{"name":"John Billingsley","avatar":""},{"name":"Chin Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["2012 - Konec světa","2012 – Das Ende der Welt","2012 - Wir waren gewarnt","2012 - Fomos Avisados","Farewell Atlantis","2012 วันสิ้นโลก","2012"]', 1784690324477);
