INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-dai-hoa-2012', 'Năm Đại Họa 2012', '2012', 'năm đại họa 2012 2012 john cusack amanda peet chiwetel ejiofor thandiwe newton oliver platt tom mccarthy woody harrelson danny glover liam james morgan lily zlatko burić beatrice rosen alexandre haussmann philippe haussmann johann urb john billingsley chin han 2012 - konec světa 2012 – das ende der welt 2012 - wir waren gewarnt 2012 - fomos avisados farewell atlantis 2012 วันสิ้นโลก 2012', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-than-chet', 'Giải Cứu Thần Chết', 'Saving The Death', 'https://phimimg.com/upload/vod/20250216-1/cbd1b7d98773cc6349bd4625eac82790.jpg', 'https://phimimg.com/upload/vod/20250216-1/07fea4f6f1fb3f88b03a287774369d46.jpg', '<p>An là một cô nữ sinh mơ mộng, luôn ước ao có chàng Thần Chết đẹp trai đến rút hồn mình như cô gái cùng tên trong phim Nụ hôn thần chết. Một ngày kia, Thần Chết Teen bất ngờ xuất hiện nhưng có nằm mơ, cô nàng An cũng không tưởng tượng nổi chính mình sẽ là người “Giải cứu thần chết”! &nbsp;Hớn hở với cuộc gặp gỡ bất ngờ, An ngay lập tức vạch ra kế hoạch bắt Thần Chết giúp mình từ một cô gái vụng về trở thành ngôi sao ca nhạc. Cô nàng sung sướng nghĩ tới viễn cảnh sẽ chinh phục trái tim anh bạn trai chơi bóng rổ Quang Anh và trả thù những kẻ từng ức hiếp mình. Nhưng Thần Chết Teen càng tích cực trổ tài thì An càng lãnh hậu quả bi đát. “Đuổi thì thương mà vương thì tội”, cô nàng An “cùng đường” nảy ra âm mưu để ai cũng xấu như mình. Thần Chết Teen được lệnh phải làm tung tóe những bí mật bấy lâu nay đào sâu chôn chặt, những cuộc tình tay ba éo le, bóng tối đời tư của các thầy cô đáng kính…</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Minh Hằng","avatar":""},{"name":"Chí Thiện","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Phương Thanh","avatar":""},{"name":"Hong Nhung","avatar":""},{"name":"Đông Nhi","avatar":""},{"name":"Võ Ngọc Trai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Giải Cứu Thần Chết"]', 1784690324477);
