INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-ma-ca-rong-phan-1', 'Nhật Ký Ma Cà Rồng (Phần 1)', 'The Vampire Diaries (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/a7ece50c8cf4ca443a1fbcf9884d62b9.jpg', 'https://phimimg.com/upload/vod/20240808-1/e5ee32b4f41b93037ea560704985733c.jpg', '<p>Câu chuyện về hai anh em ma cà rồng bị ám ảnh bởi cùng một cô gái, người có ngoại hình rất giống với ma cà rồng xinh đẹp nhưng tàn nhẫn mà họ từng biết và yêu vào năm 1864.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Wesley","avatar":""},{"name":"Ian Somerhalder","avatar":""},{"name":"Kat Graham","avatar":""},{"name":"Candice King","avatar":""},{"name":"Zach Roerig","avatar":""},{"name":"Michael Malarkey","avatar":""},{"name":"Matthew Davis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324477);
