INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuyen-da-xoa-phan-2', 'Khuyển Dạ Xoa (Phần 2)', 'Inuyasha (Season 2)', 'https://phimimg.com/upload/vod/20250126-1/4f4cdc77e14c8a8e96ec0aaabd44aef5.jpg', 'https://phimimg.com/upload/vod/20250126-1/f82afa3cfa2258edcb9c91780104b15d.jpg', '<p>Inuyasha - Khuyển Dạ Xoa thuộc thể loại phiêu lưu hành động xen lẫn yếu tố lãng mạn, được chấp bút bởi Rumiko Takahashi. Câu chuyện bắt đầu khi một bán yêu Khuyển Dạ Xoa (Inu Yasha) tấn công một ngôi làng để cướp viên ngọc Tứ Hồn (Shikon no Tama), một bảo bối có thể dùng để làm tăng sức mạnh của anh. Tuy nhiên, Cát Cánh (Kikyo), một nữ pháp sư (miko) kịp thời ngăn anh lại và dùng mũi tên thanh tẩy của cô phong ấn Khuyển Dạ Xoa vào gốc cây cổ thụ thần thánh trong làng. Tuy nhiên vì bị thương quá nặng, biết mình không qua khỏi, Cát Cánh đã yêu cầu em gái mình là A Phụng (Kaede) thiêu xác của cô cùng với viên ngọc Tứ Hồn để cho nó không rơi vào tay kẻ xấu. Trong lúc đó, ở thế giới hiện tại 550 năm sau, Nhật Mộ Li (Higurashi Kagome) đang mừng lễ sinh nhật thứ mười lăm của mình....</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 14, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kappei Yamaguchi","avatar":""},{"name":"Satsuki Yukino","avatar":""},{"name":"Izumi Ōgami","avatar":""},{"name":"Houko Kuwashima","avatar":""},{"name":"Noriko Hidaka","avatar":""},{"name":"Takeshi Kusao","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca8