INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khuyen-da-xoa-phan-2', 'Khuyển Dạ Xoa (Phần 2)', 'Inuyasha (Season 2)', 'khuyển dạ xoa (phần 2) inuyasha (season 2) kappei yamaguchi satsuki yukino izumi ōgami houko kuwashima noriko hidaka takeshi kusao инуяша: една феодална приказка инуяша: феодална приказка 犬夜叉 sengoku otogizoshi inuyasha inuyasha kanketsu-hen 犬夜叉: 完结篇 inu-yasha 犬夜叉 -完結編- 이누야사 пёс-демон 犬夜叉全集 inuyasha: a feudal fairy tale inuyasha: the final act khuyển dạ xoa', '');
