INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-6', 'Bác Sĩ House (Phần 6)', 'House (Season 6)', 'https://phimimg.com/upload/vod/20250103-1/5fbbb016c9fec90120c051172021e6da.jpg', 'https://phimimg.com/upload/vod/20250103-1/5bbd10022fb1c120d81ad0fda434abc0.jpg', '<p>Khi mùa giải trước kết thúc, House buộc phải thừa nhận rằng anh đã không còn nắm bắt được thực tế và không thể hành nghề y được nữa. Không còn lựa chọn nào khác, anh ta tự mình vào bệnh viện tâm thần. Phần 6 sẽ khám phá con đường hồi phục dài và ngoằn ngoèo của House: Liệu anh ấy có thể tìm thấy phiên bản nào đó của sự tỉnh táo và bình thường không? Liệu anh có thể tránh xa nơi làm việc được cho là đã khiến anh bất ổn về tinh thần nhưng cũng là chỗ dựa ổn định duy nhất trong cuộc đời anh? Princeton-Plainsboro có thể tiếp tục Khoa Chẩn đoán nổi tiếng mà không có anh ấy không? Mối quan hệ của Cuddy với House sẽ thay đổi như thế nào khi mối tình tưởng tượng của họ đã bị lộ?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324477);
