INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-nhan-so-phan-2', 'Hữu Nhân Sổ (Phần 2)', 'Natsume''s Book Of Friends (Season 2)', 'https://phimimg.com/upload/vod/20231204-1/1355a21019f05eab91c49f2e051dccfe.jpg', 'https://phimimg.com/upload/vod/20231204-1/3a62c224bc5ee01801507b539b627ab9.jpg', '<p>Natsume Takashi, một cậu bé có thể nhìn thấy yêu quái, vào 1 ngày nọ, đã tìm thấy cuốn hữu nhân sổ trong số các di vật của bà mình. Hữu nhân sổ này là một cuốn sổ thu thập những cái tên bị đánh cắp mà người bà quá cố Reiko của cậu ta, đã giành được khi đánh bại và chiến thắng yêu quái. Kể từ đó, Natsume cùng với người bảo hộ tự xưng - chú mèo yêu quái Nyanko-sensei, đã bắt đầu những ngày trả lại tên cho yêu quái ...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Eiji Itoh","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Hisayoshi Suganuma","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Sanae Kobayashi","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Kazuma Horie","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Rina Sato","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
