INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dep-tung-centimet', 'Đẹp Từng Centimet', 'Beauty in Each Centimeter', 'https://phimimg.com/upload/vod/20241204-1/2a2e1e3e72a0216b3bc7283db755a3c0.jpg', 'https://phimimg.com/upload/vod/20241204-1/6dd9db20f34b19372a048aca81b062fe.jpg', '<p>Quang Hy là một chàng nhiếp ảnh gia nghiệp dư, anh luôn muốn mình trở thành người chuyên nghiệp bằng cách chụp ảnh khỏa thân của phụ nữ để thực tập.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Tăng Thanh Hà","avatar":""},{"name":"Lương Mạnh Hải","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Dep Tung Centimet","Beautiful in Every Centimeter","Đẹp Từng Centimet"]', 1784690324477);
