INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dep-tung-centimet', 'Đẹp Từng Centimet', 'Beauty in Each Centimeter', 'đẹp từng centimet beauty in each centimeter tăng thanh hà lương mạnh hải dep tung centimet beautiful in every centimeter đẹp từng centimet', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xung-danh-tai-nu-phan-4', 'Xứng Danh Tài Nữ (Phần 4)', 'Rosy Business (Season 4)', 'https://phimimg.com/upload/vod/20241106-1/9acdc1497c0d58d7eae3cabd1ed55abd.jpg', 'https://phimimg.com/upload/vod/20241106-1/690e1b2b1721973e4f26e06129272126.jpg', '<p>Hôn ước của Khang Bảo Kỳ và Tưởng Kiều (do Nhạc Hoa đóng) không thành do năm đó bất chợt xảy ra một trận thiên tai. Nhìn thấy cảnh dân đói lầm than, cha của Bảo Kỳ quyết định giấu Vua mở kho lương thực để cứu tế. Vì thế, cả gia đình nhà họ Khang đều bị xử trảm, duy chỉ có Bảo Kỳ sống sót. Từ đó, cô lưu lạc khắp nơi để tránh khỏi sự truy sát của triều đình.Sau nhiều năm lang bạt, Bảo Kỳ cuối cùng cũng gặp lại vị hôn phu của mình. Tưởng Kiều của ngày nào nay đã trở thành vua gạo. Tuy công việc thuận lợi nhưng chuyện nhà của Tưởng Kiều lại rối ren. Khi biết Bảo Kỳ còn sống, Tưởng Kiều ra sức che chở cho cô, tiếp tục mối duyên xưa. Không bao lâu sau, Bảo Kỳ trở thành tứ phu nhân của Tưởng gia.Từ khi bước chân vào Tưởng gia, Bảo Kỳ luôn bị đại phu nhân Ân Phụng Nghi (do Tạ Tuyết Tâm đóng) và nhị phu nhân Bành Kiều (do Thương Thiên Nga đóng) hãm hại, lại thêm Tam phu nhân Lưu Phương (do Huệ Anh Hồng đóng) nhút nhát luôn hùa theo hai người chị.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 10, 2009, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lê Diệu Tường","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Tiêu Chính Nam","avatar":""},{"name":"La Thiên Vũ","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Gaan kwok hiu hung","妻妾成群","红粉商人","巾幗梟雄"]', 1784690324477);
