INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-kaiji', 'Thần Bài Kaiji', 'Kaiji: The Ultimate Gambler', 'https://phimimg.com/upload/vod/20241114-1/930f6646c3b8b32bcb390df21466fd1f.jpg', 'https://phimimg.com/upload/vod/20241114-1/c2e02b4032dd1a36d72801cae5e80959.jpg', '<p>Sau khi tốt nghiệp THPT, Kaiji Ito (Fujiwara Tatsuya) chuyển tới Nhật Bản. Không thể nào tìm được việc làm, cộng với bất mãn xã hội, cậu lao vào đánh bạc, rượu chè và phá hoại. Sau 2 năm bê tha, 1 gã đòi nợ tên Endo (Amami Yuki) đến gặp cậu để thu tiền. Gã cho Kaiji 2 lựa chọn: một là dùng cả 10 năm làm việc quần quật để trả nợ, hoặc là tham gia vào trò bạc trên 1 con tàu trong chỉ 1 đêm để thanh toán hết nợ nần và thậm chí còn có thể kiếm được nhiều hơn nữa. Thực ra, gã Endo đó đã chơi trò nhập nhằng 2 mặt, gã điều khiển Kaiji nhưng lại hoàn toàn cho rằng cậu không thể có đường về sau chuyến đi đó. Và rồi Kaiji bước vào đêm định mệnh của mình...</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Taro Yamamoto","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Yûki Amami","avatar":""},{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Kei Satō","avatar":""},{"name":"Suzuki Matsuo","avatar":""},{"name":"Ryushin Tei","avatar":""},{"name":"Shogen","avatar":""},{"name":"Ryuji Sainei","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Кайджи: игра ва-банк","Kaiji: Jinsei gyakuten gêmu","Kaiji: Gambling Apocalypse","KAIJI JINSEI GYAKUTEN GAME","Kaiji: En Büyük Kumarbaz","赌博默示录1","赌博默示录：人生逆转游戏","开司：人生逆转游戏","カイジ 人生逆転ゲーム"]', 1784690324477);
