INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-bai-kaiji', 'Thần Bài Kaiji', 'Kaiji: The Ultimate Gambler', 'thần bài kaiji kaiji: the ultimate gambler tatsuya fujiwara kenichi matsuyama taro yamamoto teruyuki kagawa yûki amami yuriko yoshitaka ken mitsuishi kei satō suzuki matsuo ryushin tei shogen ryuji sainei кайджи: игра ва-банк kaiji: jinsei gyakuten gêmu kaiji: gambling apocalypse kaiji jinsei gyakuten game kaiji: en büyük kumarbaz 赌博默示录1 赌博默示录：人生逆转游戏 开司：人生逆转游戏 カイジ 人生逆転ゲーム', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me', 'Người Mẹ', 'Mother', 'https://phimimg.com/upload/vod/20241114-1/26394df6d565f9d82a7b94e66c807b8d.jpg', 'https://phimimg.com/upload/vod/20241114-1/6296b85485074b3a516ed877cbf16304.jpg', '<p>Phim kể về câu chuyện của một người mẹ có đứa con mắc bệnh ngại tiếp xúc với xã hội bị vu oan cho một tội ác khủng khiếp. Với tình yêu thương mãnh liệt và nghị lực kiên cường, mẹ của anh quyết tâm tìm cho ra tên thủ ác nhằm giải oan cho con mình. Phim gây ấn tượng sâu sắc bởi diễn xuất tuyệt vời của nữ diễn viên chính Kim Hye-ja trong vai nhân vật người mẹ.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-ja","avatar":""},{"name":"Won Bin","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Lee Young-suk","avatar":""},{"name":"Moon Hee-ra","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Kim Byeong-soon","avatar":""},{"name":"Yeo Moo-yeong","avatar":""},{"name":"Jung Young-ki","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Kim Jin-goo","avatar":""},{"name":"Min Kyung-jin","avatar":""},{"name":"Jo Kyung-sook","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Yun Yeong-","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["非常母亲","骨肉同谋","Madeo","Madre","Mother - A Busca Pela Verdade","Mère","Matka","Mother: uma força única","Mama","Mother","母亲","母なる証明","母なる証明：2009","Äiti","Motina","Ana","마더"]', 1