INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-me', 'Người Mẹ', 'Mother', 'người mẹ mother kim hye-ja won bin jin goo yoon je-moon jeon mi-seon song sae-byuk lee young-suk moon hee-ra chun woo-hee kim byeong-soon yeo moo-yeong jung young-ki go gyu-pil lee mi-do kim jin-goo min kyung-jin jo kyung-sook park myung-shin yun yeong- 非常母亲 骨肉同谋 madeo madre mother - a busca pela verdade mère matka mother: uma força única mama mother 母亲 母なる証明 母なる証明：2009 äiti motina ana 마더', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-giac-quan-cua-than-tinh-ai', 'Năm Giác Quan Của Thần Tình Ái', 'Five Senses of Eros', 'https://phimimg.com/upload/vod/20241101-1/f6f5cb47267e928aa66c7261211117e6.jpg', 'https://phimimg.com/upload/vod/20241101-1/383e0afb388fb65246c9583a4ac04833.jpg', '<p>Tình yêu có muôn hình vạn trạng, đủ mọi màu sắc và thể loại. Mỗi một câu chuyện tình yêu lại mang đến cho chúng ta những suy nghĩ khác nhau. Movie Five senses of Eros gồm 5 câu chuyện tình yêu khác nhau. 5 câu chuyện tình yêu này cũng giống như 5 giác quan của thần tình ái sẽ mang đến cho chúng ta thật nhiều những cảm xúc và suy nghĩ. Mỗi một câu chuyện có lối dẫn dắt khác nhau, hoàn cảnh khác nhau và kết thúc khác nhau. Nhưng tất cả đều cho thấy rằng tình yêu là 1 thứ kỳ diệu. Tạo hóa đã ban cho con người tình yêu cũng giống như một báu vật gắn kết con người lại với nhau...</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장혁","avatar":""},{"name":"Cha Hyun-jung","avatar":""},{"name":"김강우","avatar":""},{"name":"차수연","avatar":""},{"name":"배종옥","avatar":""},{"name":"김수로","avatar":""},{"name":"김규리","avatar":""},{"name":"엄정화","avatar":""},{"name":"황정민","avatar":""},{"name":"김효진","avatar":""},{"name":"김동욱","avatar":""},{"name":"이시영","avatar":""},{"name":"정의철","avatar":""},{"name":"신세경","avatar":""},{"name":"송중기","avatar":""},{"name":"클라라","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ogamdo","Five Senses Of Eros","오감도"]', 1784690324477);
