INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kampfer', 'Kampfer', 'Kampfer', 'https://phimimg.com/upload/vod/20241028-1/86f9737cc42d12cb34b7ca1c1337c759.jpg', 'https://phimimg.com/upload/vod/20241028-1/a9435ecbc7c1788c15d79c2ab0290e71.jpg', '<p>Senou Natsuru là một cậu học sinh trung học bình thường. Tuy nhiên, cậu lại được chọn để trở thành một Kämpfer – với mục tiêu duy là chiến đấu với những Kämpfer khác và có những khả năng sử dụng súng, kiếm và pháp thuật. Nhưng cũng có những quy đối với Kämpfer; Thứ nhất, không thể tự mình biến đổi thành Kämpfer và ngược lại. Thứ hai, Kämpfer phải là mang thân hình của một cô gái mới có thể sử dụng được sức mạnh của mình.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 14, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"井上麻里奈","avatar":""},{"name":"堀江由衣","avatar":""},{"name":"水樹奈々","avatar":""},{"name":"田村ゆかり","avatar":""},{"name":"中尾衣里","avatar":""},{"name":"皆川純子","avatar":""},{"name":"阿澄佳奈","avatar":""},{"name":"植田佳奈","avatar":""},{"name":"名塚佳織","avatar":""},{"name":"内海賢二","avatar":""},{"name":"山川琴美","avatar":""},{"name":"能登麻美子","avatar":""},{"name":"中島愛","avatar":""},{"name":"三上枝織","avatar":""},{"name":"川原慶久","avatar":""},{"name":"荒浪和沙","avatar":""},{"name":"後藤邑子","avatar":""},{"name":"Yuki Kobayashi","avatar":""},{"name":"野村道子","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["肯普法 fur die Liebe","肯普法 为了爱","Kampfer","けんぷファー 愛のために","けんぷファー","Кемпфер","Kenpufer"]', 1784690324477);
