INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-sao-bang', 'Vườn Sao Băng', 'Boys Over Flowers', 'https://phimimg.com/upload/vod/20241022-1/35bc88d24f0b93e20028f562681335e4.jpg', 'https://phimimg.com/upload/vod/20241022-1/1bab8452f023857087b642e8ed68090e.jpg', '<p>Jan Di là một cô gái bình thường, gia đình có tiệm giặt khô gần trường đại học danh tiếng dành cho con nhà Shin Hwa.Một ngày nọ Jan Di gặp được 4 chàng trai nổi tiếng &quot;quậy&quot; và đều là con nhà giàu có khi cô vào trường này giao đồ giặt ủi. Bốn chàng trai này được biết đến như là một nhóm F4, những ai lên tiếng chống đối bốn anh chàng này đều không được &quot;yên thân&quot;.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 13, 2009, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ku Hye Sun","avatar":""},{"name":"Lee Min Ho","avatar":""},{"name":"Hyun-joong Kim","avatar":""},{"name":"Kim Bum","avatar":""},{"name":"Min Young-won","avatar":""},{"name":"Jang Ja-yeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Garotos em vez de Flores","Casi el paraíso","Fiúk a virágok felett","בנים על פני פרחים","Kkotboda Namja","Kgotboda Namja","Boys Over Flowers","Los chicos son mejores que las flores","Цветочки после ягодок","花樣男子","Boys Before Flowers","꽃보다 남자"]', 1784690324477);
