INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-hanh-phuc-ban-viet-nam', 'Ngôi Nhà Hạnh Phúc (Bản Việt Nam)', 'Full House (Vietnam Version)', 'https://phimimg.com/upload/vod/20241010-1/720a28cc28510bf53e0f1ff92ca9c6ab.jpg', 'https://phimimg.com/upload/vod/20241010-1/0fc94dfd50a01ede0045380002e85584.jpg', '<p>Ngôi nhà hạnh phúc phiên bản Việt là bộ phim truyền hình được chờ đón nhất trong năm 2009. Sự thành công của phiên bản Hàn Quốc khiến khán giả Việt Nam tò mò quan tâm khi được tin bộ phim này sẽ có phiên bản Việt.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lương Mạnh Hải","avatar":""},{"name":"Minh Hằng","avatar":""},{"name":"Thủy Tiên","avatar":""},{"name":"Lam Trường","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Bỗng Dưng Muốn Khóc"]', 1784690324477);
