INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-khat-mau-phan-4', 'Thiên Thần Khát Máu (Phần 4)', 'Dexter (Season 4)', 'https://phimimg.com/upload/vod/20240229-1/5f3bff23ef074b13f992c8c7be935be2.jpg', 'https://phimimg.com/upload/vod/20240229-1/b6d57a002d517d4ed72839cefea006e2.jpg', '<p>Dexter với tư cách là một người cha và người chồng đấu tranh để tìm cách tồn tại trong nhiều năm tới. Anh ta tìm cách học hỏi từ Arthur Mitchell, một kẻ giết người hàng loạt và là người đàn ông của gia đình, kẻ đã giết người hơn ba mươi năm mà không bị phát hiện.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael C. Hall","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Geoff Pierson","avatar":""},{"name":"David Zayas","avatar":""},{"name":"James Remar","avatar":""},{"name":"Aimee Garcia","avatar":""},{"name":"Desmond Harrington","avatar":""},{"name":"C.S. Lee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
