INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-1', 'Gia Đình Hiện Đại (Phần 1)', 'Modern Family (Season 1)', 'https://phimimg.com/upload/vod/20241001-1/6b6135f998ff3b32b3cdffa371a07dd3.jpg', 'https://phimimg.com/upload/vod/20241001-1/5748f301034011eaa38bf97d71a5741e.jpg', '<p>Modern Family mang đến một cái nhìn mới mẻ và hài hước về ý nghĩa của việc nuôi dạy một gia đình trong thời đại bận rộn này. Các mối quan hệ đa văn hóa, nhận con nuôi và hôn nhân đồng giới chỉ là một số vấn đề thời sự mà ba lứa con vô cùng đa dạng của chương trình phải đối mặt. Bất kể quy mô hay hình dạng, gia đình luôn được đặt lên hàng đầu trong cái nhìn “hiện đại” vui nhộn này về cuộc sống, tình yêu và tiếng cười.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324477);
