INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-hien-dai-phan-1', 'Gia Đình Hiện Đại (Phần 1)', 'Modern Family (Season 1)', 'gia đình hiện đại (phần 1) modern family (season 1) ed o''neill sofía vergara julie bowen ty burrell jesse tyler ferguson eric stonestreet sarah hyland ariel winter nolan gould rico rodriguez familja moderne съвременно семейство modern family famille moderne famille moderne egy rém modern család משפחה מודרנית modernā amerikāņu ģimene família moderna американская семейка عائلة عصرية сучасна сім’я a modern farewell', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-iris', 'Mật Danh IRIS', 'Iris', 'https://phimimg.com/upload/vod/20240920-1/2f7b0448374261776986164e02ab0d35.jpg', 'https://phimimg.com/upload/vod/20240920-1/247b2a7ad7de9808f1721c512646231b.jpg', '<p>Hàn Quốc, quốc gia cuối cùng được phân chia trên thế giới, liên tục chịu sức ép về chính trị và quân sự với các quốc gia xung quanh đặc biệt là về chính trị và quân sự với các quốc gia xung quanh đặc biệt là về vấn đề hạt nhân của Bắc Triều Tiên. Để tránh chiến tranh Triều Tiên lần thứ hai, đặc vụ mật NSS tồn tại vì an ninh quốc gia trên bán đảo Hàn Quốc.

Đặc vụ NSS được huấn luyện trở thành những chuyên gia, họ dùng bất cứ cách nào để hoàn thành nhiệm vụ. Họ chính thức không tồn tại và không được thừa nhận hay được bảo vệ bởi chính phủ. Mặc dù họ được huấn luyện thành những sát thủ máu lạnh, có một điều cấm kị mà họ không thể né tránh được, đó là tình yêu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"김영철","avatar":""},{"name":"임수향","avatar":""},{"name":"이준","avatar":""},{"name":"윤소이","avatar":""},{"name":"백성현","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"장혁","avatar":""},{"name":"이다해","avatar":""},{"name":"오연수","avatar":""},{"name":"윤두준","avatar":""},{"name":"김승우","avatar":""},{"name":"이정길","avatar":""},{"name":"윤주상","avatar":""},{"name":"이보희","avatar":""},{"name":"김소현","avatar":""},{"name":"Hwang Sung-woong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ирис","IRIS- Organização Secreta Coreana","特务情人","IRIS","Iris ஐரிஸ்","IRIS-アイリス-","IRIS アイリス","아이리스 시즌1","Irys","IRIS นักฆ่า / ล่า / หัวใจเธอ","特務情人","아이리스"]', 1784690324477);
