INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-muon-tham-kin', 'Ham Muốn Thầm Kín', 'Torso', 'https://phimimg.com/upload/vod/20230922-1/5ff27eb749578bd2ae5908ccf26a3dc1.jpg', 'https://phimimg.com/upload/vod/20230922-1/5f249999b058587604dcc139a1ff49e3.jpg', '<p>Nhân viên văn phòng có vẻ &quot;bình thường&quot; Hiroko có một bí mật. Ở nhà, cô sống với một thân người giả - không có đầu, tay hay chân, chỉ có cơ thể và dương vật. Hiroko tắm bằng phần thân và cô ấy cũng làm tình bằng phần thân vào ban đêm. Cuộc sống bí mật của Hiroko bị gián đoạn khi cô em gái vui vẻ Mina bấm chuông cửa. Mina đang chạy trốn khỏi người bạn trai bạo hành của mình và muốn ở lại nhà của Hiroko</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Makiko Watanabe","avatar":""},{"name":"Sakura Ando","avatar":""},{"name":"Sora Aoi","avatar":""},{"name":"Arata Iura","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Miyako Yamaguchi","avatar":""},{"name":"Yuko Nakamura","avatar":""},{"name":"Nao Okabe","avatar":""},{"name":"Yūko Genkaku","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
