INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('coi-xay-thit-nguoi', 'Cối Xay Thịt Người', 'Meat Grinder', 'https://phimimg.com/upload/vod/20240910-1/5e32512859c0d32302614cd7e47daa36.jpg', 'https://phimimg.com/upload/vod/20240910-1/99ff848ee5c5e45e576d40d1567b1b7e.jpg', '<p>Meat Grinder (2009) là một bộ phim kinh dị độc đáo, mang đến cho khán giả cảm giác kỳ quái và đáng sợ thông qua các công thức nấu phở truyền thống của nhân vật chính - Bus, một người phụ nữ làm chủ quán phở. Bus đã trải qua cuộc sống căng thẳng và luôn phải làm việc chăm chỉ để nuôi gia đình, như một đầu bếp tài ba. Tuy nhiên, đôi khi cô bị ám ảnh bởi một giọng nói bí ẩn, buộc cô phải tuân thủ những yêu cầu kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 19, 2009, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mai Charoenpura","avatar":""},{"name":"Arucha Tosawat","avatar":""},{"name":"Wiradit Srimalai","avatar":""},{"name":"Atitaya Shindejanichakul","avatar":""},{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"สมชาย ศักดิกุล","avatar":""},{"name":"Chaiyot Tushsanasuwan","avatar":""},{"name":"Shiny Khunthong","avatar":""},{"name":"Somchat Prachathai","avatar":""},{"name":"Thanatorn Oudsahakul","avatar":""},{"name":"Jiratchaya Jirarajagit","avatar":""},{"name":"Kittiphit Tamrongweenijchai","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
