INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-cuoi', 'Trạm Cuối', 'The Last Station', 'https://phimimg.com/upload/vod/20231103-1/0593dc765642a83323f18e80f0453023.jpg', 'https://phimimg.com/upload/vod/20231103-1/e7ffd04a6239b4fd74b4caabeb773660.jpg', '<p>Một bộ phim lịch sử minh họa cuộc đấu tranh của tác giả người Nga Leo Tolstoy để cân bằng giữa danh tiếng và sự giàu có với cam kết của ông về một cuộc sống không có vật chất. Nữ bá tước Sofya, vợ và là nàng thơ của Leo Tolstoy, dùng mọi thủ đoạn dụ dỗ đệ tử trung thành của chồng mình, người mà bà tin là người chịu trách nhiệm cho việc Tolstoy ký di chúc mới để lại công việc và tài sản của mình cho người dân Nga.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Anne-Marie Duff","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"John Sessions","avatar":""},{"name":"Patrick Kennedy","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"David Masterson","avatar":""},{"name":"Tomas Spencer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324477);
