INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-thien-do-long-ky-ban-2009', 'Ỷ Thiên Đồ Long Ký (Bản 2009)', 'The Heaven Sword And Dragon Saber', 'https://phimimg.com/upload/vod/20240904-1/1458f009f803c106d9a944735963539e.jpg', 'https://phimimg.com/upload/vod/20240904-1/65533fca0dbf2de07c2031abbca2423d.jpg', '<p>Ỷ Thiên Đồ Long Ký (tiếng Trung: 倚天屠龍記) là bộ phim truyền hình dựa theo tiểu thuyết cùng tên của nhà văn Kim Dung. Đây là phần cuối cùng trong Xạ điêu tam bộ khúc do Trương Kỷ Trung sản xuất, hai phần trước là Anh hùng xạ điêu (2003) và Thần điêu đại hiệp (2006). Kịch bản của bộ phim chủ yếu dựa trên phiên bản thứ ba của bộ tiểu thuyết Ỷ Thiên Đồ Long ký. Phim được quay trong vòng 5 tháng, từ 18 tháng 10 năm 2008 đến 16 tháng 3 năm 2009, được quay tại nhiều danh thắng của Trung Quốc như núi Võ Đang, đảo Đào Hoa, hang Long Du và khu thắng cảnh Vũ Di Sơn. Phim được phát sóng lần đầu tiên trên Đài truyền hình Ôn Châu vào tháng 10 năm 2009.</p>', 'Hoàn Tất (44/44)', 40, 'series', 'completed', 13, 2009, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Cao Viên Viên","avatar":""},{"name":"Giả Tịnh Văn","avatar":""},{"name":"Tô Hữu Bằng","avatar":""},{"name":"Trần Tú Lệ","avatar":""},{"name":"Trương Quốc Lập","avatar":""},{"name":"Trương Thiết Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324477);
