INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('y-thien-do-long-ky-ban-2009', 'Ỷ Thiên Đồ Long Ký (Bản 2009)', 'The Heaven Sword And Dragon Saber', 'ỷ thiên đồ long ký (bản 2009) the heaven sword and dragon saber thích tiểu long cao viên viên giả tịnh văn tô hữu bằng trần tú lệ trương quốc lập trương thiết lâm ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-vuong-hoc-duong-2', 'Bá Vương Học Đường 2', 'Crows Zero II', 'https://phimimg.com/upload/vod/20231101-1/0e46f144034e12426273a65246291940.jpg', 'https://phimimg.com/upload/vod/20231101-1/2f6a0abeb33b3157a75456b116aca2cb.jpg', '<p>Phần tiếp theo của Crow Zero, bộ phim về bạo lực học đường được xây dựng từ manga cùng tên của Hiroshi Takahashi. Kết thúc phần trước, băng GPS của Genji Takiya đã chiến thắng băng của Tamao Serizawa sau một trân đánh dữ dôi, trở thành băng lớn nhất tại trường Suzuran, còn Genji được coi là thủ lĩnh của trường. Tuy nhiên, thử thách mới đã bắt đầu khi Genji, trong khi bảo vệ 1 cựu thành viên của Suzuran đã tấn công 1 thành viên của trường Housen - một trường học cũng nổi tiếng bạo lực với những thành viên bất hảo không kém. Điều này khiến cho hiệp định đình chiến giữa 2 trường từ trước bị phá vỡ, và các thành viên của Suzukan bị kéo vào cuộc chiến trả thù với Housen - sự trả thù bắt nguồn từ những trận chiến trong quá khứ ...</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Kenta Kiritani","avatar":""},{"name":"Meisa Kuroki","avatar":""},{"name":"Kyosuke Yabe","avatar":""},{"name":"Sousuke Takaoka","avatar":""},{"name":"Tsutomu Takahashi","avatar":""},{"name":"Kaname Endo","avatar":""},{"name":"Suzunosuke Tanaka","avatar":""},{"name":"Yusuke Kamiji","avatar":""},{"name":"Shunsuke Daitoh","avatar":""},{"name":"Yusuke Izaki","avatar":""},{"name":"Hisato Izaki","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Shinnosuke Abe","avatar":""},{"name":"Nobuaki Kaneko","avatar":""},{"name":"Haruma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
