INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-vuong-hoc-duong-2', 'Bá Vương Học Đường 2', 'Crows Zero II', 'bá vương học đường 2 crows zero ii shun oguri takayuki yamada kenta kiritani meisa kuroki kyosuke yabe sousuke takaoka tsutomu takahashi kaname endo suzunosuke tanaka yusuke kamiji shunsuke daitoh yusuke izaki hisato izaki motoki fukami shinnosuke abe nobuaki kaneko haruma ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-bao-hong-2', 'Điệp Vụ Báo Hồng 2', 'The Pink Panther 2', 'https://phimimg.com/upload/vod/20240902-1/684c7fd4b52efb5601fa815bcf5f4478.jpg', 'https://phimimg.com/upload/vod/20240902-1/40a1d000ae2c5570d231dbb0e2773bf4.jpg', '<p>Sau khi rất nhiều cổ vật trên thế giới đột nhiên bị lấy cắp, kể cả viên kim cương vô giá Pink Panther của nước Pháp – vốn đang được triển lãm tại bảo tàng, Tổng thanh tra Dreyfus buộc phải đưa Clouseau tham gia vào một nhóm các thám tử và chuyên viên quốc tế với nhiệm vụ là truy bắt băng nhóm buôn cổ vật quy mô thế giới “The Tornado” và thu hồi những cổ vật đã bị lấy cắp. “Đội quân trong mơ” này đã chu du từ Pháp sang Rome để truy vấn Alonso Avellaneda – một nhân vật có quan hệ mật thiết với “The Tornado”, nhưng vẫn không thể ngăn “The Tornado” ra tay lần nữa, trộm mất chiếc nhẫn của Giáo hoàng. Dư luận và cấp trên tất cả đều chỉ trích nhóm người này, và vì sự ngớ ngẩn đầy tai họa của ông, Thanh tra Clouseau đã bị buộc phải rời khỏi nhóm bởi những đồng đội của mình. Những tình huống cười ra nước mắt do nhóm thám tử này gây ra đã củng cố thêm dấu ấn riêng cho thương hiệu “The Pink Panther” cũng như kế thừa hoàn hảo mạch truyện độc đáo của dòng phim này.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Andy García","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Yuki Matsuzaki","avatar":""},{"name":"Aishwarya Rai Bachchan","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Lily Tomlin","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Johnny Hallyday","avatar":""},{"name":"Geoffrey Palmer","avatar":""},{"name":"Philip Goodwin","avatar":""},{"name":"Armel Bellec","avatar":""},{"name":"Lewis D. Wheeler","avatar":""},{"name":"Richard LaFrance","avatar":""},{"name":"Simon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
