INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vu-bao-hong-2', 'Điệp Vụ Báo Hồng 2', 'The Pink Panther 2', 'điệp vụ báo hồng 2 the pink panther 2 steve martin jean reno emily mortimer andy garcía alfred molina yuki matsuzaki aishwarya rai bachchan john cleese lily tomlin jeremy irons johnny hallyday geoffrey palmer philip goodwin armel bellec lewis d. wheeler richard lafrance simon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bo-tuyet-voi', 'Người Bố Tuyệt Vời', 'World''s Greatest Dad', 'https://phimimg.com/upload/vod/20231101-1/0ee70083b92841c77c48eee2a426bf35.jpg', 'https://phimimg.com/upload/vod/20231101-1/aa04d14898db64b71950450567f740be.jpg', '<p>Sau một tai nạn kinh hoàng, Lance phải chịu bi kịch tồi tệ nhất và là cơ hội lớn nhất trong đời anh. Anh ta đột nhiên phải đối mặt với khả năng nổi tiếng, tài sản và sự nổi tiếng, nếu anh ta chỉ có thể sống với kiến thức về cách anh ta đạt được điều đó.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Alexie Gilmore","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Evan Martin","avatar":""},{"name":"Geoff Pierson","avatar":""},{"name":"Henry Simmons","avatar":""},{"name":"Mitzi McCall","avatar":""},{"name":"Jermaine Williams","avatar":""},{"name":"Lorraine Nicholson","avatar":""},{"name":"Morgan Murphy","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Jill Talley","avatar":""},{"name":"Bruce Hornsby","avatar":""},{"name":"Krist Novoselic","avatar":""},{"name":"Bobcat Goldthwait","avatar":""},{"name":"Tony V.","avatar":""},{"name":"Nao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
