INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-bo-tuyet-voi', 'Người Bố Tuyệt Vời', 'World''s Greatest Dad', 'người bố tuyệt vời world''s greatest dad robin williams alexie gilmore daryl sabara evan martin geoff pierson henry simmons mitzi mccall jermaine williams lorraine nicholson morgan murphy toby huss tom kenny jill talley bruce hornsby krist novoselic bobcat goldthwait tony v. nao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-2', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 2)', 'Star Wars: The Clone Wars (Season 2)', 'https://phimimg.com/upload/vod/20240624-1/2c8010c9663bd96d7228f36f9b15663c.jpg', 'https://phimimg.com/upload/vod/20240624-1/11674752a24af45c616fe1c8186d26d2.jpg', '<p>Những trận chiến khốc liệt, những câu chuyện thú vị và hoạt hình ngoạn mục nâng cao mức độ đặt cược lên cao hơn bao giờ hết trong Star Wars: The Clone Wars. Cuộc đấu tranh của các anh hùng Jedi ngày càng phức tạp hơn khi các mối quan hệ bí mật và bị cấm đoán bị tiết lộ, mạng sống bị đe dọa và một giống ác quỷ mới bước vào cuộc chiến - những kẻ săn tiền thưởng tàn nhẫn. Từ Nhà sản xuất điều hành George Lucas và Lucasfilm Animation, Phần hai hứa hẹn những cuộc phiêu lưu ly kỳ mới, những nhân vật và sinh vật chưa từng thấy trước đây cũng như những câu chuyện chưa được kể về Chiến tranh giữa các vì sao.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 11, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324477);
