INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-la-so-1-phan-2', 'Gia Đình Là Số 1 (Phần 2)', 'High Kick (Season 2)', 'https://phimimg.com/upload/vod/20240829-1/e82c52723a69fe65ec3ba8cb43a932e8.jpg', 'https://phimimg.com/upload/vod/20240829-1/c925028c9c3d0e90c44c90891989e369.jpg', '<p>Gia đình là số một - Phần 2 là bộ phim tiếp nối câu chuyện của phần 1, kể về những mẩu chuyện nho nhỏ xảy ra trong cuộc sống sinh hoạt hàng ngày của một gia đình vui nhộn. Mỗi thành viên đều có một cá tính và cách sống khác nhau. Chính những mâu thuẫn này cùng lối làm phim sitcom điển hình đã khiến khán giả, nhất là thiếu niên say sưa theo dõi. &nbsp;Về mặt nội dung, bộ phim hoàn toàn không phải là sự tiếp nối của phần 1. Nội dung phim không liện quan đến phần 1. Tuy vậy, cốt truyện của bộ phim lại có motip khá giống và tương đồng với phần 1. Câu chuyện cũng xoay quanh những chuyện gia đình, mối quan hệ giữa cha mẹ và con cái, cách giải quyết những mâu thuẫn xung dột giữa họ tạo ra những tiếng cười tự nhiên.</p>', 'Hoàn Tất (126/126)', 126, 'series', 'completed', 30, 2009, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"이순재","avatar":""},{"name":"이광수","avatar":""},{"name":"서신애","avatar":""},{"name":"줄리엔 강","avatar":""},{"name":"김자옥","avatar":""},{"name":"황정음","avatar":""},{"name":"신세경","avatar":""},{"name":"정보석","avatar":""},{"name":"오현경","avatar":""},{"name":"박신혜","avatar":""},{"name":"이기광","avatar":""},{"name":"유인나","avatar":""},{"name":"최다니엘","avatar":""},{"name":"윤시윤","avatar":""},{"name":"진지희","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
