INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-son-hanh', 'Hổ Sơn Hành', 'Traveling Tiger Mountain', 'https://phimimg.com/upload/vod/20240829-1/4b52c655f9c16ab6e5bdffde88bca26c.jpg', 'https://phimimg.com/upload/vod/20240829-1/7d779bd4559f385d7d80da22c2251e76.jpg', '<p>Hổ Sơn Hành - Traveling Tiger Mountain xoay quanh bối cảnh những năm đầu Dân quốc, thời cục rối ren, những người anh hùng sẵn sàng đối mặt với vận mệnh đau khổ, sẵn sàng hy sinh để bảo vệ những người yếu th. Nhưng cũng có người vì lợi ích bản thân mà bán rẻ lương tâm, sẵn sàng bán đứng bạn bè và người thân.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 12, 2009, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Dương Cung Như","avatar":""},{"name":"Chu Mục Nhân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
