INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-13-truy-lung-to-chuc-ao-den', 'Thám Tử Lừng Danh Conan 13: Truy Lùng Tổ Chức Áo Đen', 'Detective Conan: The Raven Chaser', 'https://phimimg.com/upload/vod/20231019-1/35381cab8b601f8bb6b4007b6f0afaa3.jpg', 'https://phimimg.com/upload/vod/20231019-1/d07f700f1580f91116783b1378c91acf.jpg', '<p>Thám tử nhí Edogawa Conan lại một lần nữa đối mặt với Tổ chức Áo đen trong một cuộc thách đấu định mệnh.Câu truyện bắt đầu khi Tổ chức áo đen phát hiện ra tên thám tử học sinh Kudo Shinichi vẫn còn sống sót sau khi uống viên thuốc độc của bọn chúng, và giờ đang trú ngụ trong vỏ bọc của một học sinh cấp một.Tất cả những người có liên quan với Conan đều nằm trong vòng truy sát của Tổ chức Áo đen.Conan sẽ phải làm gì để bảo vệ những người quan trọng của cậu? Mời các bạn đón xem.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2009, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Yukitoshi Hori","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Hiroyuki Kinoshita","avatar":""},{"name":"Yasuo Muramatsu","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Kenichi Ogata","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]