INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-the-phan-1', 'Thất Thế (Phần 1)', 'Eastbound & Down (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/2f2e31ee65106b893d22bc01742b6b7f.jpg', 'https://phimimg.com/upload/vod/20240808-1/7141f40a837c76da7825ff51cd787f24.jpg', '<p>Nhiều năm sau khi quay lưng lại với quê hương, một cầu thủ bóng chày chuyên nghiệp đã kiệt sức và quay trở lại dạy thể dục tại trường trung học cơ sở cũ của mình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny McBride","avatar":""},{"name":"Steve Little","avatar":""},{"name":"Katy Mixon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
