INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-doi-conchord-phan-2', 'Phi Đội Conchord (Phần 2)', 'Flight Of The Conchords (Season 2)', 'https://phimimg.com/upload/vod/20240808-1/03b9a06e179de4de997e9d0893c0bcc1.jpg', 'https://phimimg.com/upload/vod/20240808-1/87919fd3be374dd5739383447a5c9658.jpg', '<p>Những thử thách và gian khổ của một ban nhạc dân gian kỹ thuật số gồm hai người đã chuyển từ New Zealand đến New York với hy vọng xây dựng sự nghiệp âm nhạc thành công. Cho đến nay, họ đã tìm được một người quản lý (người có &quot;công việc&quot; khác là tại Lãnh sự quán New Zealand), một người hâm mộ (một người đã kết hôn bị ám ảnh) và một người bạn (chủ một cửa hàng cầm đồ địa phương) -- nhưng không có gì nhiều.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bret McKenzie","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Rhys Darby","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
