INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tuy-tung-phan-6', 'Đoàn Tùy Tùng (Phần 6)', 'Entourage (Season 6)', 'https://phimimg.com/upload/vod/20240808-1/6ac9121442b07a5efa99ef5bf1dfa04d.jpg', 'https://phimimg.com/upload/vod/20240808-1/eb4445866b8d874ee0d002e1b8014a1f.jpg', '<p>Ngôi sao điện ảnh Vince Chase khám phá địa hình tẻ nhạt của Los Angeles cùng một nhóm bạn thân thiết và người đại diện đáng tin cậy của anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Connolly","avatar":""},{"name":"Adrian Grenier","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Rex Lee","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Scott Caan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
