INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-co-dong-dong-doi', 'Biệt Đội Cơ Động : Đồng Đội', 'Tactical Unit: Partners', 'https://phimimg.com/upload/vod/20231006-1/572a23141ae520591567d4e368406eb7.jpg', 'https://phimimg.com/upload/vod/20231006-1/09a5e4f3f1552334a18de2e422e3e426.jpg', '<p>Khi có tin đồn rằng trùm băng đảng Ấn Độ đã biến mất từ lâu có tên Black Molly sắp quay trở lại thế giới ngầm, các sĩ quan của Đơn vị Chiến thuật Sam và May đã sẵn sàng giải quyết những rắc rối tiếp theo. Cánh tay phải của Molly, Velu quyết định rời khỏi băng nhóm sau khi mãn hạn tù, nhưng đồng đội cũ của anh là Sonu cảm thấy bị phản bội và thề sẽ giết anh ta. Trong khi đó, Sonu bị đẩy vào con đường không thể quay lại khi được giao nhiệm vụ ám sát Chánh thanh tra Chan, cấp trên của Sam và May.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Maggie Shiu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Vincent Sze","avatar":""},{"name":"Peter Chan Bei-Dak","avatar":""},{"name":"Chui Tien-You","avatar":""},{"name":"Jason Chang","avatar":""},{"name":"Luk Man-Wai","avatar":""},{"name":"Roderick Lam Chung-Kei","avatar":""},{"name":"Wong Chi-On","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
