INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-dam-mau-phan-2', 'Giang Hồ Đẫm Máu (Phần 2)', 'Sons Of Anarchy (Season 2)', 'https://phimimg.com/upload/vod/20240731-1/748a68cf59a0a4dda90895f9f0cec859.jpg', 'https://phimimg.com/upload/vod/20240731-1/b5f34f89ce8529fb63959017d35cac5d.jpg', '<p>Sons of Anarchy là một bộ phim truyền hình tội phạm của Mỹ bởi đạo diễn Kurt Sutter được phát sóng vào năm 2008 và kết thúc vào năm 2014. Kể cuộc đời của một câu lạc bộ xe gắn máy sống ngoài vòng pháp luật hoạt động tại Charming , một thị trấn hư cấu ở Thung lũng Trung tâm California . Charlie Hunnam trong vai Charlie Jackson là &quot;Jax&quot; Teller.

Mỗi Season sẽ liên quan đến âm mưu song song đan xen và chồng lên nhau, tập trung vào cả đời sống cá nhân và gia đình của Jackson &quot;Jax&quot; Teller ( Charlie Hunnam ) và trên SAMCRO ( viết tắt bởi Sons of Anarchy Motorcycle Club, Redwood Original). SAMCRO có liên quan đến việc buôn súng ở miền tây Hoa Kỳ, và đối phó với các băng nhóm đối thủ, chính trị gia và chính quyền. Chính thức lúc đầu là phó chủ tịch và sau đó lên giữ chủ tịch sau này của SAMCRO, sau khi phát hiện những tội ác mà chủ tịch cũ đã giấu diếm anh. Jax đấu tranh để quản lý câu lạc bộ và giữ lại tâm huyết của người sáng lập chính là người cha quá cố John.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Katey Sagal","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Dayton Callie","avatar":""},{"name":"David Labrava","avatar":""},{"name":"Drea de Matteo","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Niko Nicotera","avatar":""},{"name":"Theo Rossi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
