INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-so-9', 'Chiến Binh Số 9', '9', 'https://phimimg.com/upload/vod/20231023-1/f3425e1013785bcfabff877fe1cd4bd8.jpg', 'https://phimimg.com/upload/vod/20231023-1/0b66292c558b43600c95e02bcf88970f.jpg', '<p>&quot;9&quot; lấy bối cảnh thế giới thời hậu tận thế, lúc mà con người đã bị chính các cỗ máy mình tạo ra tiêu diệt. Nhưng dường như theo thời gian, các cỗ máy đó cũng chết dần chết mòn vì cạn kiệt nguồn nhiên liệu. Thứ xúc tác duy nhất duy trì sự sống của chúng là nguồn năng lượng, hay còn được hiểu nôm na là linh hồn, đang trú ngụ trong các búp bê vải nhỏ bé. Những búp bê vải này được tạo ra bởi một nhà khoa học bí ẩn với hi vọng, một ngày nào đó, linh hồn của chúng sẽ cứu rỗi cả thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Martin Landau","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Alan Oppenheimer","avatar":""},{"name":"Tom Kane","avatar":""},{"name":"Helen Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
