INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-3', 'Gã Điên (Phần 3)', 'Mad Men (Season 3)', 'https://phimimg.com/upload/vod/20240606-1/bf2054394bbe43d1198a4815b47e697f.jpg', 'https://phimimg.com/upload/vod/20240606-1/4ecbf04faebdec06991ce142ce632c12.jpg', '<p>Phần ba diễn ra sáu tháng sau khi phần thứ hai kết thúc và kết thúc vào tháng 12 năm 1963. Nó ghi lại sự kết thúc của kỷ nguyên Camelot khi các nhân vật trải qua những thay đổi to lớn trong cuộc sống nghề nghiệp và cá nhân của họ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 10, 2009, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
