INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-lam-tu-truyen-ky-phan-2', 'Thiếu Lâm Tự Truyền Kỳ (Phần 2)', 'A Legend Of Shaolin Temple (Season 2)', 'https://phimimg.com/upload/vod/20240508-1/4ef8abf846c2bd7dd0bb60821e5241c2.jpg', 'https://phimimg.com/upload/vod/20240508-1/3ea94b7c7169804475ba76190fd3d511.jpg', '<p>Thời kỳ Nam Bắc triều, chiến loạn liên miên. Có một vị cao nhân ngộ đạo, tên Cơ Thần Quang, quyết tâm xa lánh hồng trần, quy y Phật môn. Cơ Thần Quang đã quỳ trong tuyết 3 ngày 3 đêm, Đạt Ma phương trượng vẫn nhất quyết không thâu nhận, chỉ bảo rằng, trừ phi trời đổ tuyết hồng. Cơ Thần Quang quyết tâm xuất gia đã chặt đứt cánh tay trái của mình, quả nhiên trời toại lòng, tuyết hồng đã rơi. Đạt Ma vì cảm kích lòng thành nên đã thâu nhận, đặt pháp danh là Tuệ Khả, 15 năm sau Tuệ Khả trở thành đại phương trượng Thiếu Lâm, Tuệ Khả phương trượng tĩnh tâm thanh tu, từ chối cả lời mời tiến cung thuyết pháp của Thái hậu. Lạc Dương Vương Cao Kỳ và Phương trượng là bạn cũ, khi cùng đánh cờ, Tuệ Khả đã nói, thế sự nhiễu nhương, đệ tử môn đồ muốn tịnh tâm thật khó. Lạc Dương Vương lại bảo, triều đình lại ra lệnh tiến cung mỹ nữ, đề ra hàng loạt quy định mới, luật thuế mới, cái giàu có, xa hoa ngày càng tập trung ở hậu cung, chiến loạn thì nhiều, trong thiên hạ ai có thể ngồi yên mà hưởng lạc?</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 22, 2009, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Bao Guoan","avatar":""},{"name":"Li Bingyuan","avatar":""},{"name":"Tiger Xu","avatar":""},{"name":"Sammo Hung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324477);
