INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-duc-tiec-tung-va-doi-tra', 'Tình Dục, Tiệc Tùng Và Dối Trá', 'Sex, Party And Lies', 'https://phimimg.com/upload/vod/20240228-1/ab695c657c833be3a3bac70a3b8852ba.jpg', 'https://phimimg.com/upload/vod/20240228-1/a5998624d2bd7bf7f22610416f49750f.jpg', '<p>Một nhóm thanh niên đang chuẩn bị cho mùa hè của cuộc đời họ sẽ như thế nào, bao gồm bí mật, dối trá, móc túi, tình dục, sự nhầm lẫn và đặc biệt là bữa tiệc đêm tuyệt vời. Hầu hết thanh thiếu niên không nhận thức được rằng một khi bạn bắt đầu hành trình khởi đầu này, bạn sẽ không thể quay đầu lại, và thường thì những lời nói dối sẽ ngày càng trở nên lớn hơn, và đôi khi tình yêu có nghĩa là tổn thương.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Mario Casas","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Yon González","avatar":""},{"name":"Hugo Silva","avatar":""},{"name":"Ana Polvorosa","avatar":""},{"name":"Alejo Sauras","avatar":""},{"name":"Maxi Iglesias","avatar":""},{"name":"Miriam Giovanelli","avatar":""},{"name":"Asier Etxeandia","avatar":""},{"name":"Esmeralda Moya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
