INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-kim-thuat-su-brotherhood', 'Giả Kim Thuật Sư: BROTHERHOOD', 'Hagane No Renkinjutsushi: Fullmetal Alchemist Fullmetal Alchemist (2009) FMA FMAB', 'https://phimimg.com/upload/vod/20240228-1/1450569f8399a0e74692ddbacf14904c.jpg', 'https://phimimg.com/upload/vod/20240228-1/5c0a592cf85e93bca2debeb805be3631.jpg', '<p>Vì người mẹ đã khuất, hai anh em đã thâm nhập vào môn“ luyện thân thể người ” và đánh mất tất cả. Edward Elric, anh trai của Nhà giả kim &nbsp;và Alphonse Elric, người em trai có linh hồn được cố định trong bộ áo giáp. Họ tìm kiếm Hòn đá phù thủy để khôi phục những gì đã mất.</p>', 'Hoàn Tất (64/64)', 64, 'hoathinh', 'completed', 17, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
