INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-cuoi-cung', 'Ma Cà Rồng Cuối Cùng', 'Blood: The Last Vampire', 'https://phimimg.com/upload/vod/20240228-1/c2081a054eb123df361d2490be0894ba.jpg', 'https://phimimg.com/upload/vod/20240228-1/7c6d0e2b8b9d1ca1aa87fabc99b00136.jpg', '<p>Bề ngoài, Saya là một thanh niên 16 tuổi xinh đẹp, nhưng vẻ ngoài trẻ trung đó lại ẩn chứa tâm hồn dằn vặt của một người lai 400 tuổi. Sinh ra với cha là người và mẹ là ma cà rồng, trong nhiều thế kỷ, cô là một kẻ cô độc bị ám ảnh bởi việc sử dụng các kỹ năng samurai của mình để loại bỏ thế giới ma cà rồng, đồng thời biết rằng bản thân cô chỉ có thể sống sót nhờ máu của những kẻ cô săn đuổi.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Allison Miller","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Koyuki","avatar":""},{"name":"JJ Feild","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
