INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-quay-roi', 'Những Kẻ Quấy Rối', 'De Dana Dan', 'https://phimimg.com/upload/vod/20240228-1/a28d251ddb79a83c7d5bec66c4fe29bc.jpg', 'https://phimimg.com/upload/vod/20240228-1/d2da7a86659bd0aeef5315b1842e8dfc.jpg', '<p>Hai người đàn ông kém may mắn cố gắng bắt cóc con chó của một nữ doanh nhân giàu có để đòi một khoản tiền chuộc khổng lồ từ cô ấy. Nhưng mọi thứ trở nên rắc rối khi con chó mất tích.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Sunil Shetty","avatar":""},{"name":"Paresh Rawal","avatar":""},{"name":"Sameera Reddy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324477);
