INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-ve-thoi-tien-su', 'Trôi Về Thời Tiền Sử', 'Land Of The Lost', 'https://phimimg.com/upload/vod/20240227-1/6bbc6890496b48e3f550a330156e394a.jpg', 'https://phimimg.com/upload/vod/20240227-1/140fbd0f29ec9f95e71bd3cfe6a7c6b2.jpg', '<p>Một vùng lộng lẫy không gian của nhà khoa học Rick Marshall, trợ lý của mình Holly và một người tồn tại sẽ vào một thế giới cư trú bởi những con khủng long và những sinh vật chậm chạp đau đớn được gọi là thiết bị trượt băng.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324477);
