INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-sang', 'Ngôi Sao Sáng', 'Bright Star', 'https://phimimg.com/upload/vod/20240227-1/37cbfef3215df9d10906b8e77916f4a9.jpg', 'https://phimimg.com/upload/vod/20240227-1/fd64b4898d9460f23f1cf8d0c72e2e8d.jpg', '<p>Đó là năm 1818 tại làng Hampstead ở ngoại ô London. Nhà thơ Charles Brown sống trong một nửa của một ngôi nhà, gia đình Dilkes khác. Thông qua mối liên hệ với các Dilkes, gia đình không cha Brawne biết ông Brown. Ông Brown và con gái lớn của Brawne, Fanny, không thích nhau. Cô ấy nghĩ anh kiêu ngạo và thô lỗ; Anh ấy cảm thấy rằng cô ấy là một sự tán tỉnh tự phụ, chỉ biết cách may (thừa nhận cũng như cô ấy tạo ra tất cả quần áo thời trang của riêng mình) và bày tỏ ý kiến về những môn học mà cô ấy không biết gì. Nhà thơ đang vật lộn không an toàn John Keats đến sống với bạn mình, ông Brown. Cô Brawne và ông Keats có một sự hấp dẫn lẫn nhau với nhau, nhưng mối quan hệ của họ chậm phát triển, một phần, vì ông Brown làm bất cứ điều gì có thể để giữ cho hai cách xa nhau. Những trở ngại khác đối mặt với cặp vợ chồng, bao gồm niềm đam mê áp đảo cuối cùng của họ đối với nhau trong tầm nhìn của họ về những gì người kia làm, sự nghiệp đang gặp khó khăn của ông Keats, nơi cung cấp cho anh ta ít trong cách an ninh tiền tệ (sẽ dẫn đến bà Brawne không cho Đồng ý cho họ kết hôn) và các vấn đề sức khỏe trước đó đã thực hiện cuộc đời của anh trai của ông Keats, Tom.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Abbie Cornish","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Thomas Sangster","avatar":""},{"name":"Paul Schneider","avatar":""},{"name":"Kerry Fox","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
