INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-sat-o-nam-kinh', 'Thảm Sát Ở Nam Kinh', 'City Of Life And Death', 'https://phimimg.com/upload/vod/20240227-1/50b50300c44a4435d235116964913377.jpg', 'https://phimimg.com/upload/vod/20240227-1/4de5db24b974ca58d7ea6944c4c085b7.jpg', '<p>Thảm Sát Ở Nam Kinh - City of Life and Death lấy bối cảnh năm 1937, cao trào của trận chiến giữa Trung Quốc và Nhật Bản. Quân đội Nhật Bản đã chiếm được thành phố Nam Kinh, lúc bấy giờ là thủ đô của Trung Quốc. Những gì xảy ra sau đó được lịch sử gọi là cuộc thảm sát Nam Kinh, bởi trong khoảng thời gian vài tuần mà hàng nghìn binh lính và nhân dân Trung Hoa bị thảm sát dưới tay Phát Xít Nhật. Phim tố cáo tội ác chiến tranh thông qua hình tượng các nhân vật hư cấu: một chiến binh Trung Hoa, một giáo viên, một chiến binh Nhật, một nhà truyền giáo người nước ngoài, và John Rabe, một thương nhân đã góp tay vào việc cứu hàng nghìn người dân Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Viên Viên","avatar":""},{"name":"Tần Lam","avatar":""},{"name":"Lưu Diệp","avatar":""},{"name":"Phạm Vỹ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
