INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tien-tri', 'Nhà Tiên Tri', 'A Prophet', 'https://phimimg.com/upload/vod/20240220-1/e033fe99f47e0f33c1a0586f6ce0d7a5.jpg', 'https://phimimg.com/upload/vod/20240220-1/29d73ff60f3c436ce08d314c14cbed51.jpg', '<p>Bị kết án sáu năm tù, Malik El Djebena cô đơn trên thế giới và không thể đọc cũng như viết. Khi đến nhà tù, anh ta có vẻ trẻ hơn và dễ gãy hơn những người khác bị giam ở đó. Ngay lập tức, anh ta rơi vào sự thống trị của một nhóm người Corsican, những người thực thi quyền cai trị của họ trong nhà tù. Khi các nhiệm vụ trôi qua, anh ấy trở nên cứng rắn hơn và chiếm được lòng tin của nhóm Corsican.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tahar Rahim","avatar":""},{"name":"Niels Arestrup","avatar":""},{"name":"Adel Bencherif","avatar":""},{"name":"Hichem Yacoubi","avatar":""},{"name":"Reda Kateb","avatar":""},{"name":"Jean-Philippe Ricci","avatar":""},{"name":"Gilles Cohen","avatar":""},{"name":"Antoine Basler","avatar":""},{"name":"Foued Nassah","avatar":""},{"name":"Jean-Emmanuel Pagni","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
