INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hoi-doi-doi', 'Cơ Hội Đổi Đời', 'Post Grad', 'https://phimimg.com/upload/vod/20240220-1/7b6f93cc2bfa8131b1daff07d116b786.jpg', 'https://phimimg.com/upload/vod/20240220-1/5fba6f82030d71b7286f319811e41422.jpg', '<p>Ryden Malby có một kế hoạch tổng thể. Tốt nghiệp đại học, kiếm một công việc tuyệt vời, đi chơi với người bạn thân nhất của cô ấy và tìm được chàng trai hoàn hảo. Nhưng kế hoạch của cô ấy vượt khỏi tầm kiểm soát một cách vui nhộn khi cô ấy buộc phải chuyển về nhà với gia đình lập dị của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexis Bledel","avatar":""},{"name":"Zach Gilford","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Carol Burnett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
