INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shikabane-hime-kuro', 'Shikabane Hime: Kuro', 'Corpse Princess 2', 'https://phimimg.com/upload/vod/20240215-1/15e27f1cdd66a61afc5a4a19d6f8e0b9.jpg', 'https://phimimg.com/upload/vod/20240215-1/2399dcab3a4fc9669a3ef0d5e74bf6df.jpg', '<p>Con người khi chết đi nhưng vẫn còn luyến tiếc sâu nặng với thế giới này thì sẽ trở thành một “xác sống”.<br/>Sau khi bị một nhóm xác sống bí ẩn ám sát, Hoshimura Makina cũng trở thành một xác sống. Cô tình nguyện tham gia Kougon-một tổ chức chống xác sống, sát cánh chiến đấu với Pháp sư đỡ đầu của mình là Tagami Keisei…</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
