INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-lon-phan-3', 'Vụ Nổ Lớn (Phần 3)', 'The Big Bang Theory (Season 3)', 'https://phimimg.com/upload/vod/20240215-1/17d478604ae524634ae8f090af4d4123.jpg', 'https://phimimg.com/upload/vod/20240215-1/d54417553ab8814d8e2af03b45838a3f.jpg', '<p>Không khí trong nhóm bắt đầu thay đổi khi mối quan hệ của Leonard và Penny lúc mặn nồng lúc lạnh nhạt và tình cảm giữa Howard và Bernadette chớm nở.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Galecki","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Kaley Cuoco","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Mayim Bialik","avatar":""},{"name":"Melissa Rauch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
