INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-vi-pham-toi-phan-5', 'Hành Vi Phạm Tội (Phần 5)', 'Criminal Minds (Season 5)', 'https://phimimg.com/upload/vod/20240215-1/2edc979373282d4864fc180e03d05e7c.jpg', 'https://phimimg.com/upload/vod/20240215-1/398412a4f0c54427b5b40c484389e9de.jpg', '<p>Là thành viên đội chống tội phạm, bạn xem xét qua hiện trường để tìm chứng cứ, thẩm vấn những nhân chứng và nghi can, và cẩn thận phân tích các chứng cứ để tìm ra thủ phạm. Các thành viên BAU (Đơn vị phân tích hành vi) phải tìm ra kẻ giết người hàng loạt đang gây án ở một thị trấn trước khi quá muộn. Tập trung vào tội phạm, không phải tội ác, tìm ra động cơ của kẻ thủ ác và đoán trước hành động tiếp theo của hắn!</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 16, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Gibson","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Shemar Moore","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324477);
