INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-thanh-trung-phan-3', 'Lệnh Thanh Trừng (Phần 3)', 'Burn Notice (Season 3)', 'https://phimimg.com/upload/vod/20240205-1/1e22166873c3ae63e8264dff849f07ec.jpg', 'https://phimimg.com/upload/vod/20240205-1/d1f942dfcb92e56d1b905aa9cf393180.jpg', '<p>Một điệp viên trước đây từng nằm trong danh sách đen sử dụng những kỹ năng và quá trình đào tạo độc đáo của mình để giúp đỡ mọi người trong những tình huống tuyệt vọng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Donovan","avatar":""},{"name":"Sharon Gless","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Coby Bell","avatar":""},{"name":"Gabrielle Anwar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
