INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('9', '9', '9', 'https://phimimg.com/upload/vod/20240220-1/4545bb0cd669fb1bc7f92b3a5fc9617e.jpg', 'https://phimimg.com/upload/vod/20240220-1/ba6c66e33bd57b3482bbe4c16ce714f9.jpg', '<p>9 lấy bối cảnh thế giới thời hậu tận thế, lúc mà con người đã bị chính các cỗ máy mình tạo ra tiêu diệt. Nhưng dường như theo thời gian, các cỗ máy đó cũng chết dần chết mòn vì cạn kiệt nguồn nhiên liệu. Thứ xúc tác duy nhất duy trì sự sống của chúng là nguồn năng lượng, hay còn được hiểu nôm na là linh hồn, đang trú ngụ trong các búp bê vải nhỏ bé. Những búp bê vải này được tạo ra bởi một nhà khoa học bí ẩn với hi vọng, một ngày nào đó, linh hồn của chúng sẽ cứu rỗi cả thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Crispin Glover","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
