INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-doan-thay-ma', 'Binh Đoàn Thây Ma', 'Dead Snow', 'https://phimimg.com/upload/vod/20240219-1/5edcbe6efe9a38eea12b252255e14ee1.jpg', 'https://phimimg.com/upload/vod/20240219-1/bff7616f71dd2194cee0e13b9d342ca8.jpg', '<p>Một nhóm bạn trẻ đi đến một vùng núi tuyết để cắm trại nhưng họ không biết rằng núi tuyết đó chính là nơi chôn cất hàng trăm binh sĩ Đức Quốc xã chết từ thời Thế chiến thứ hai. Giờ đây bọn chúng đã trở thành những thây ma xác sống và đang đi khắp nơi tìm người để giết.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Charlotte Frogner","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Vegar Hoel","avatar":""},{"name":"Lasse Valdal","avatar":""},{"name":"Evy Kasseth Røsten","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
