INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-hai-mat', 'Trò Chơi Hai Mặt', 'Duplicity', 'https://phimimg.com/upload/vod/20240219-1/e4f073fac8bd21e9364df6868d5f0336.jpg', 'https://phimimg.com/upload/vod/20240219-1/5fa6f6f4b98fed05814398b6d3f79a2f.jpg', '<p>Lấy bối cảnh Manhattan và New York, Trò chơi hai mặt do bộ đôi Julia Roberts và Clive Owen đảm nhận sẽ vào vai hai người yêu nhau nhưng đồng thời lại là điệp viên thuộc hai tổ chức đối đầu nhau, nhưng cuối cùng họ đã cùng nhau hợp tác để thực hiện một phi vụ hoàn hảo.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Tom Wilkinson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324477);
