INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tri-cua-loi-noi-doi', 'Giá Trị Của Lời Nói Dối', 'The Invention Of Lying', 'https://phimimg.com/upload/vod/20240219-1/2e8fd1da4db5648865be08bac0d0b78f.jpg', 'https://phimimg.com/upload/vod/20240219-1/e9e614aa8309315563708145d923402b.jpg', '<p>Đó là một thế giới nơi mọi người nói sự thật - và bất cứ điều gì họ đang nghĩ. Mark Bellison là một nhà biên kịch, sắp bị sa thải. Anh ấy ngắn và chunky với một mũi phẳng - một thiết lập di truyền có nghĩa là anh ấy sẽ không đến được căn cứ đầu tiên với Anna, người phụ nữ mà anh ấy yêu thích. Tại một ngân hàng, trên khoảng thời gian anh ta làm mờ một sợi, với kết quả bắt mắt. Sau đó, khi mẹ anh ta trên giường chết, sợ hãi về khoảng trống vĩnh cửu đang chờ đợi cô, Mark phát minh tưởng tượng. Nhân viên bệnh viện tình cờ nghe mô tả về thiên đàng, tin rằng mọi từ, và nói với người khác. Sớm Mark là một nhà tiên tri, kịch bản sáng tạo đầu tiên của anh ấy làm cho anh ấy giàu có, và về cơ bản anh ấy là một chàng trai tốt. Nhưng đó sẽ là đủ cho Anna</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
