INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-khuat', 'Bất Khuất', 'Invictus', 'https://phimimg.com/upload/vod/20240219-1/999c26674c92f71939ea9d30ca48ec93.jpg', 'https://phimimg.com/upload/vod/20240219-1/9b8f88b2a83be60c08ecfd589c2a0596.jpg', '<p>Sau bốn năm được chính quyền da trắng trả tự do, Nelson Mandela trở thành tổng thống đầu tiên của nước Cộng hòa Nam Phi. Với những chính sách sáng suốt của mình, ông đã giúp Nam Phi vượt qua giai đoạn khó khăn sau thời kỳ phân biệt chủng tộc Apartheid, lần đầu tiên giúp đội bóng bầu dục nước nhà vinh danh trên đấu trường quốc tế. Phim dựa trên câu chuyện có thật, nhận được hai đề cử Oscar 2010.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Tony Kgoroge","avatar":""},{"name":"Adjoa Andoh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
