INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-khuat', 'Bất Khuất', 'Invictus', 'bất khuất invictus matt damon morgan freeman tony kgoroge adjoa andoh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-ben-ho', 'Sát Nhân Bên Hồ', 'Eden Lake', 'https://phimimg.com/upload/vod/20240219-1/cb09afe62997109f46d445c3689a694f.jpg', 'https://phimimg.com/upload/vod/20240219-1/e4f52b0c3bb16e483a740ded61baa078.jpg', '<p>Cặp đôi Steve và cô nuôi dạy trẻ Jenny dự định sẽ có một kì nghỉ cuối tuần thật thú vị, yên tĩnh nơi hồ Eden, bao phủ xung quanh bởi một khu rừng cây rậm rạp. Trong lúc Steve đang sắp xếp mọi thứ để chuẩn bị cho việc cầu hôn Jenny thì những giờ nghỉ ngơi êm đềm của họ bỗng bị phá rối bởi một nhóm thiếu niên ngỗ ngược. Sau khi bọn trẻ khiêu khích họ bằng cách trộm những đồ dùng cá nhân và phá hỏng chiếc xe mà họ đang dùng, tình huống càng trở nên tệ hại hơn khi Steve vì cố gắng bảo vệ bạn gái của mình đã phải chịu đựng những cú đánh khủng khiếp từ đám thiếu niên kia. Jenny buộc phải một mình chạy trốn giữa màn đêm đang buông xuống dần với hy vọng đến được một thị trấn nào đó gần nhất để cầu cứu, tuy nhiên, cô không biết rằng những thứ đang chờ đợi mình ở phía trước còn đáng sợ hơn gấp nhiều lần...</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kelly Reilly","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Tara Ellis","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
