INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-hoa-nhac', 'Buổi Hòa Nhạc', 'The Concert', 'https://phimimg.com/upload/vod/20240228-1/01d7ba62b680a2fdf6ff0f4174290299.jpg', 'https://phimimg.com/upload/vod/20240228-1/535d643908bf6fa1e66c80a8cb3fb41a.jpg', '<p>Ba mươi năm trước, nhạc trưởng Andreï Filipov của Dàn nhạc Bolshoi đã bị sa thải vì thuê nhạc sĩ Do Thái. Bây giờ là một người gác cổng thấp kém, có cơ hội để tập hợp các nhạc sĩ cũ của mình đến và đóng vai trò là dàn nhạc Buolshoi chính thức ở Paris.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Mélanie Laurent","avatar":""},{"name":"Aleksei Guskov","avatar":""},{"name":"François Berléand","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
