INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trang', 'Mặt Trăng', 'Moon', 'https://phimimg.com/upload/vod/20240228-1/f428f53c45246bdb2a868e52d8c16bf7.jpg', 'https://phimimg.com/upload/vod/20240228-1/75580094856f73ff6073af482e2b8df9.jpg', '<p>Bối cảnh của phim đặt ở tương lai, khi cuộc khủng hoảng năng lượng ở Trái đất đã được giải quyết ổn thỏa bằng một loại đá trên Mặt trăng. Công ty Lunar thuê Sam Bell lên mặt trăng làm việc trong hợp đồng 3 năm, coi sóc việc khai thác loại đá này. Anh ở trong một trung tâm điều khiển hiện đại, với sự giúp đỡ của con Robot thông minh Gerty. Chỉ còn 2 tuần nữa là hợp đồng kết thúc và anh đang mong muốn trở về nhà. Anh muốn gặp lại vợ và cô con gái 2 tuổi xinh đẹp chưa một lần bồng bế.Nhưng Sam bắt đầu thấy những ảo giác và sức khỏe giảm sút rõ rệt. Anh gặp tai nạn khi đang khảo sát địa hình ngoài bề mặt. Sau đó, Sam thức giấc và thấy mình đã quay lại trung tâm. Gesty thông báo rằng anh đã mất một phần trí nhớ. Sam cảm thấy nghi ngờ khi Gerty không cho anh ra ngoài lần nữa. Anh tìm cách thoát ra, tìm đến hiện trường vụ tai nạn và thấy có một Sam Bell khác đang nằm trong xe. Sam ngạc nhiên tột cùng, quyết định đưa Sam kia về chữa trị và tìm hiểu những điều bí ẩn.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Dominique McElligott","avatar":""},{"name":"Rosie Shaw","avatar":""},{"name":"Adrienne Shaw","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Matt Berry","avatar":""},{"name":"Malcolm Stewart","avatar":""},{"name":"Robin Chalk","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
