INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bikini-girls-on-ice', 'Bikini Girls On Ice', 'Bikini Girls On Ice', 'https://phimimg.com/upload/vod/20240228-1/c15f07413694d402b11de0f1a689164c.jpg', 'https://phimimg.com/upload/vod/20240228-1/647ce17f5466e3be567e8cfc92467d79.jpg', '<p>Khi một đoàn xe buýt chở các cầu thủ bóng đá nữ của trường đại học bị mắc kẹt trên đường đến buổi gây quỹ rửa xe bikini, họ quyết định mở cửa hàng trước một trạm xăng bỏ hoang ở rìa thị trấn. Họ ít biết rằng nơi này là nơi rình rập của một thợ cơ khí điên cuồng giết người tên là Moe.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Suzi Lorraine","avatar":""},{"name":"Kerri Taylor","avatar":""},{"name":"Cindel Chartrand","avatar":""},{"name":"Danielle Doetsch","avatar":""},{"name":"William Jarand","avatar":""},{"name":"Christina Sciortino","avatar":""},{"name":"Caroline Faille","avatar":""},{"name":"Tarek Gader","avatar":""},{"name":"Ivan Peric","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
