INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cuoc-voi-quy', 'Đánh Cược Với Quỷ', 'The Imaginarium Of Doctor Parnassus', 'https://phimimg.com/upload/vod/20240205-1/78321471f712b163a57ad7c80064c5ec.jpg', 'https://phimimg.com/upload/vod/20240205-1/07030a932a4984cc0ed8ba0eb5e8a954.jpg', '<p>Thầy pháp Parnassus được thiên phú cho một quyền năng đáng sợ: ông có thể điều khiển trí tưởng tượng của người khác. Trong một lần giao kèo ma quái, ông đã bán linh hồn cho Nick (hiện thân của Quỷ Satan) để đổi lấy sự trường sinh. Nhiều năm sau, khi phải lòng một cô gái trẻ, ông lại đánh đổi sự bất tử để lấy tuổi thanh xuân. Nhưng điều kiện cho cuộc trao đổi này thật nghiệt ngã: Ai là kẻ đầu tiên mê hoặc được cả 5 linh hồn của loài người sẽ thắng. Và phần thưởng cho kẻ chiến thắng sẽ là linh hồn của Valentina (con gái của Parnassus) khi cô tròn 16 tuổi.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Richard Riddell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
