INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-doi-khang', 'Lực Lượng Đối Kháng', 'Defiance', 'https://phimimg.com/upload/vod/20240205-1/7bb7fac49250d068562f18660c88c490.jpg', 'https://phimimg.com/upload/vod/20240205-1/955ca310bee1e86f1f4d62a89a0fcd5f.jpg', '<p>Lấy bối cảnh là cuộc chiến tranh Thế giới thứ 2, phim xoay quanh 3 người đàn ông gốc Do Thái: Tuvia, Zus và Asael. Cả 3 người đã trốn khỏi trại tập trung khi hàng ngàn người Do Thái định cư ở phía Đông Âu có nguy cơ bị tàn sát hàng loạt. Tuvia, Zus và Asael lẩn trốn tại một khu rừng ở Belarus và tại đây, họ bắt đầu một cuộc chiến chống lại Đức quốc xã với sự giúp đỡ của những người lính Nga. Bên cạnh đó, họ cũng phải đối mặt với điều kiện thời tiết khắc nghiệt tại vùng Đông Âu lạnh giá.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Jamie Bell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
