INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-merantau', 'Chiến Binh Merantau', 'Merantau', 'https://phimimg.com/upload/vod/20240220-1/7de930c9e991e73a9a4415d5fc40f242.jpg', 'https://phimimg.com/upload/vod/20240220-1/c2bf4b1f18fdd2c8f8e62715f43d274d.jpg', '<p>Ở Minangkabau, Tây Sumatera, Yuda, một học viên điêu luyện của Silat Harimau đang trong giai đoạn chuẩn bị cuối cùng để bắt đầu Merantau của mình, một nghi thức cổ xưa đã tồn tại cả thế kỷ, được thực hiện bởi những người đàn ông trẻ tuổi của cộng đồng, những người sẽ chứng kiến anh rời bỏ những tiện nghi của mình. làng nông nghiệp bình dị và tạo dựng tên tuổi của mình tại thành phố Jakarta nhộn nhịp.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Iko Uwais","avatar":""},{"name":"Chika Jessica","avatar":""},{"name":"Christine Hakim","avatar":""},{"name":"Mads Koudal","avatar":""},{"name":"Yusuf Aulia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
