INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-mo-coi', 'Đứa Trẻ Mồ Côi', 'Orphan', 'https://phimimg.com/upload/vod/20240205-1/3f95ab20ad37a944d397506233f3f3ce.jpg', 'https://phimimg.com/upload/vod/20240205-1/4e604de716955e4100fdb0b6cf83eaaf.jpg', '<p>Việc đứa con thứ ba chết khi sinh non đã khiến Kate chịu nhiều đả kích tâm lý. Mong tìm lại cuộc sống bình thường, cô và chồng quyết định nhận Esther làm con nuôi. Tuy nhiên, từ lúc Esther về nhà, một chuỗi các sự kiện lạ xảy ra, khiến Kate tin rằng Esther có điều gì đó bất thường. Kate cố gắng thuyết phục John và những người khác tìm hiểu bộ mặt thật của Esther, nhưng chẳng ai chú ý, cho đến khi mọi việc quá muộn.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isabelle Fuhrman","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Aryana Engineer","avatar":""},{"name":"Peter Sarsgaard","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
