INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-cong-leningrad', 'Tấn Công Leningrad', 'Attack On Leningrad', 'https://phimimg.com/upload/vod/20240220-1/252a23d53bd6657d95f15e28f07ebc9e.jpg', 'https://phimimg.com/upload/vod/20240220-1/4aabcad9114203f383488a585c61f458.jpg', '<p>Mùa Đông năm 1941, mở đầu cho cuộc tấn công Liên Bang Soviet , Đức Quốc Xã bao vây Leningrad - Saint Petersburg ngày nay và cắt mọi đường cứu trợ lương thực của thành phố. Không quân tập kích liên tục suốt ngày đêm, Leningrad bị cô lập hoàn toàn với thế giới bên ngoài. Không ai biết chuyện gì đang xảy ra bên trong, cũng không ai có thể thoát được làn đạn của phát xít để trốn ra ngoài. Với khẩu phần lương thực tối thiểu 125gram bánh mì/người, cư dân Leningrad xoay sở đủ mọi cách ăn đủ mọi thứ để có thể sống sót. Một nữ phóng viên người Anh vô tình kẹt lại trong thành phố, cùng trải qua cơn đói với người dân tại đây. Cuộc bao vây của phát xít Đức kéo dài 872 ngày, khoảng 1.500.000 người đã chết tại Leningrad, vì bom đạn và vì đói lạnh. Sau đó Hồng quân Soviet đã tiến vào giải phóng Leningrad , bắt đầu cuộc phản công tiêu diệt phát xít Đức...</p>', 'Full', 1, 'single', 'completed', 19, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mira Sorvino","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Olga Sutulova","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324477);
