INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thay-ma-cu-ban-dup', 'Vùng Đất Thây Ma: Cú Bắn Đúp', 'Zombieland: Double Tap', 'https://phimimg.com/upload/vod/20240126-1/801765ec92b1325477885dd538a478fb.jpg', 'https://phimimg.com/upload/vod/20240126-1/eb18b2697b3ea392c360a26f7483c473.jpg', '<p>Lấy bối cảnh 10 năm kể từ ngày đại dịch thây ma làm sụp đổ nước Mỹ, bộ tứ tưởng chừng có thể biến Nhà Trắng thành chốn định cư lâu dài. Tiếc rằng đời đâu như mơ. Little Rock dám cả gan bỏ nhà theo trai lạ, ba thành viên còn lại phải tức tốc lên đường đi tìm. Họ không thể ngờ đám thây ma thuở nào nay đã tiến hóa vượt bậc, ngày càng lì đòn, hung tợn và thậm chí còn thông minh hơn trước.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Stone","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Abigail Breslin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
