INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-3-nguoi-soi-noi-day', 'Thế Giới Ngầm 3: Người Sói Nổi Dậy', 'Underworld: Rise Of The Lycans', 'https://phimimg.com/upload/vod/20240123-1/4ea595fdd20fdce1f67aaff43c0f00fc.jpg', 'https://phimimg.com/upload/vod/20240123-1/3de673c0e31c4baae9cbf1e91cf2432a.jpg', '<p>Câu chuyện tiền truyện dấu vết nguồn gốc của mối thù máu cũ giữa các ma cà rồng quý tộc và nô lệ trên mạng của chúng, Lycans. Trong thời kỳ đen tối, một Lycan trẻ có tên Lucian nổi lên như một nhà lãnh đạo hùng mạnh, những người sành điệu vươn lên chống lại Viktor, Vua ma cà rồng độc ác, người đã làm nô lệ cho họ. Lucian được tham gia bởi người yêu bí mật của mình, Sonja, trong trận chiến chống lại quân đội ma cà rồng và sự đấu tranh của anh ta cho tự do Lycan.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
