INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mary-and-max', 'Mary And Max', 'Mary And Max', 'https://phimimg.com/upload/vod/20240123-1/ffc2bdae072095a4f301ee93f8ca3454.jpg', 'https://phimimg.com/upload/vod/20240123-1/3b732a8c6a811d84fb920d9c32f8570e.jpg', '<p>Vào giữa những năm 1970, một cô gái Úc không có lợi nhất, không có lợi nhất của 8 chọn một cái tên trong một cuốn sách điện thoại Manhattan và viết cho anh ta; Cô bao gồm một thanh sô cô la. Cô ấy là Mary Dinkle, đứa con duy nhất của một người mẹ nghiện rượu và một người cha mất tập trung. Anh ấy là max Horowitz, một người đàn ông thừa cân với Asperger, sống một mình ở New York. Anh viết lại, với sô cô la. Do đó, bắt đầu một thư từ 20 năm, bị gián đoạn bởi một sự lưu trú trong một tị nạn và một vài sai lầm. Mary rơi vào tình yêu với một người hàng xóm, tiết kiệm tiền để có một vết bớt loại bỏ và liên quan đến mất mát. Max có một tình bạn với một người hàng xóm, cố gắng kiểm soát cân nặng của mình, và cuối cùng có được công việc mơ ước. Hai người sẽ gặp mặt đối mặt?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
