INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han-kiem-soat', 'Giới Hạn Kiểm Soát', 'The Limits Of Control', 'https://phimimg.com/upload/vod/20240122-1/f6e653cba87d7d59c1ba9b8fc03be4ee.jpg', 'https://phimimg.com/upload/vod/20240122-1/f7460493d4d4d9f2c8b148649026d0b4.jpg', '<p>Một kẻ lạ mặt bí ẩn hoạt động ngoài vòng pháp luật và giấu kín mục tiêu của mình, không tin tưởng bất cứ ai. Trong khi phong thái của anh ấy vừa tập trung vừa mơ mộng một cách nghịch lý, anh ấy bắt đầu một cuộc hành trình không chỉ đưa anh ấy đi khắp Tây Ban Nha mà còn thông qua ý thức của chính anh ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isaach De Bankolé","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"John Hurt","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
