INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-bau', 'Dính Bầu', 'Baby On Board', 'https://phimimg.com/upload/vod/20240111-1/41979d85cf28cc45965096e9c56a5e8b.jpg', 'https://phimimg.com/upload/vod/20240111-1/d24cb2e4d32a37ac0d889272e29d47a7.jpg', '<p>Câu chuyện về Angela, một nữ doanh nhân đầy tham vọng, có ý thức về hình ảnh làm việc cho ông chủ Mary đòi hỏi quá cao. Khi Angela mang thai ngoài ý muốn khi đang ở đỉnh cao sự nghiệp, cuộc sống của cô với người chồng luật sư đã ly hôn, Curtis, bị đảo lộn hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heather Graham","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"John Corbett","avatar":""},{"name":"Lara Flynn Boyle","avatar":""},{"name":"Katie Finneran","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
