INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-chet-choc', 'Bí Mật Chết Chóc', 'Pandorum', 'https://phimimg.com/upload/vod/20240111-1/bdf3a3142189b896ddac941439c06b5f.jpg', 'https://phimimg.com/upload/vod/20240111-1/0b9a12798c21e7733fd2e06bc9778af3.jpg', '<p>Pandorum là một cuốn phim kinh dị lấy bối cảnh trên một chiếc phi thuyền không gian. Hai thuyền viên bị mắc kẹt trên chiếc tàu và họ nhanh chóng khám phá ra rằng họ không phải là những nạn nhân sống sót sau cùng. Trong khoang hoàn toàn tối như mực, tiếng động duy nhất phát ra là những âm thanh ù ù của máy và tiếng kẽo kẹt của thiết bị động cơ. Hai thuyền viên không nhớ mình là ai cũng như mục đích của họ là gì. Đại Úy Payton và Binh nhì Bower phải bắt đầu cuộc hành trình truy tìm tung tích của mình và toàn bộ phi hành đoàn.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Cam Gigandet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
