INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-marine-2', 'The Marine 2', 'The Marine 2', 'https://phimimg.com/upload/vod/20240104-1/bf4bf1bdf4f65fd91ca901c23095f3bc.jpg', 'https://phimimg.com/upload/vod/20240104-1/946f174e4974d0e2131e6b7dd05b038e.jpg', '<p>Trong khi đi nghỉ, một lính bắn tỉa biển Mỹ đảm nhận những kẻ nổi loạn địa phương đã chiếm quyền kiểm soát khu nghỉ dưỡng của Đảo Khách sạn nơi ông và vợ, người hiện đang là một con tin bị chuộc, đã ở lại.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
