INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-noi', 'Nghe Nói', 'Hear Me', 'https://phimimg.com/upload/vod/20240103-1/b63d803443101327e432611ad59183aa.jpg', 'https://phimimg.com/upload/vod/20240103-1/f1a6bab17331ac4352b6c6539683634e.jpg', '<p>Dương Dương và chị gái, Tiểu Bình khi sinh ra đã bị điếc, họ sử dụng điệu bộ cơ thể để nói chuyện với nhau. Tiểu Bình tham gia đội bơi dành cho người khuyết tật, và ao ước một ngày nào đó có thể tham gia thế vận hội Olympic. Ngoài cô em gái Dương Dương, Tiểu Bình còn nhận được sự giúp đỡ hết mình của Điền Quách - một anh chàng giao hàng. Cùng với nhau họ đã vượt qua những rào cản, theo đuổi ước mơ của mình và tình cảm của họ ngày càng trở nên bền chặt.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Michelle Chen","avatar":""},{"name":"Yi Han Chen","avatar":""},{"name":"Lung-Yu Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
