INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cell-211', 'Cell 211', 'Cell 211', 'https://phimimg.com/upload/vod/20240103-1/4f32ab08ed6f44255c1d7cf225276f3c.jpg', 'https://phimimg.com/upload/vod/20240103-1/55d31e389655ad7f416c4dd40399f956.jpg', '<p>Câu chuyện về hai người đàn ông ở hai phe khác nhau trong một cuộc bạo loạn trong tù -- người tù cầm đầu cuộc nổi loạn và người bảo vệ trẻ bị mắc kẹt trong cuộc nổi loạn, người đóng giả làm tù nhân trong một nỗ lực tuyệt vọng để sống sót qua thử thách.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Luis Tosar","avatar":""},{"name":"Alberto Ammann","avatar":""},{"name":"Antonio Resines","avatar":""},{"name":"Carlos Bardem","avatar":""},{"name":"Félix Cubero","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
