INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-vinh-hang', 'Lời Nguyền Vĩnh Hằng', 'Dorian Gray', 'https://phimimg.com/upload/vod/20240108-1/bff4829043c5b53e1edfa6ed7a35fbcd.jpg', 'https://phimimg.com/upload/vod/20240108-1/72f0040de84ef61bf7b1fe0754da1dfd.jpg', '<p>Bị quyến rũ vào thế giới suy tàn của Lãnh chúa Henry Wotton, nhà quý tộc trẻ đẹp trai Dorian Gray bị ám ảnh bởi việc duy trì vẻ ngoài trẻ trung của mình, và đặt ra một bức chân dung đặc biệt có thể vượt qua gió thời gian trong khi anh ta vẫn trẻ mãi không già. Khi nỗi ám ảnh của Gray vượt quá tầm kiểm soát, những nỗ lực tuyệt vọng để bảo vệ bí mật của mình đã biến cuộc sống từng được đặc ân của anh thành một địa ngục trần gian.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Barnes","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Emilia Fox","avatar":""},{"name":"Ben Chaplin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
