INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-tinh-bat-dac-di', 'Cứu Tinh Bất Đắc Dĩ', 'New In Town', 'https://phimimg.com/upload/vod/20240108-1/507991579fb171033a4fcd7eac354bb7.jpg', 'https://phimimg.com/upload/vod/20240108-1/50a278e0e803581d2946abcf37a7fa7a.jpg', '<p>Lucy Hill là một giám đốc điều hành đầy tham vọng sống ở Miami. Cô ấy yêu những đôi giày của mình, cô ấy yêu những chiếc ô tô của mình và cô ấy thích leo lên những bậc thang của công ty. Khi được giao một nhiệm vụ tạm thời - ở một nơi xa xôi hẻo lánh - để tái cấu trúc một nhà máy sản xuất, cô ấy đã chớp lấy cơ hội vì biết rằng cơ hội thăng tiến lớn đang cận kề. Điều bắt đầu như một nhiệm vụ đơn giản trở thành một trải nghiệm thay đổi cuộc đời khi Lucy khám phá ra ý nghĩa lớn lao hơn trong cuộc đời mình và bất ngờ nhất là người đàn ông trong mộng của cô.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Harry Connick Jr.","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Mike O''Brien","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
