INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-cuoi-cung-cua-amelia', 'Chuyến Bay Cuối Cùng Của Amelia', 'Amelia', 'https://phimimg.com/upload/vod/20240108-1/6c1ea86902f55934462fa575dfe7e966.jpg', 'https://phimimg.com/upload/vod/20240108-1/78b76b32fcf66c8ee91f8c35658fc7bb.jpg', '<p>Nhìn lại cuộc đời của phi công huyền thoại người Mỹ Amelia Earhart, người đã biến mất khi bay qua Thái Bình Dương vào năm 1937 trong nỗ lực thực hiện chuyến bay vòng quanh thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Swank","avatar":""},{"name":"Richard Gere","avatar":""},{"name":"Aaron Abrams","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Cherry Jones","avatar":""},{"name":"Mia Wasikowska","avatar":""},{"name":"Dylan Roberts","avatar":""},{"name":"Scott Yaphe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
