INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-pham-toi', 'Cảnh Sát Phạm Tội', 'The Bad Lieutenant: Port Of Call - New Orleans', 'https://phimimg.com/upload/vod/20240108-1/cfdebfc3d27c6145a40e342c7682ae29.jpg', 'https://phimimg.com/upload/vod/20240108-1/1182305e86dbbefad5588456f72e1006.jpg', '<p>Bộ phim đưa chúng ta dõi theo việc Terrence McDonagh (Nicolas Cage) - một trung sĩ của New Orleans Police điều tra vụ giết người của một gia đình người Senagalese nhập cư, mặc dù anh thường xuyên vi phạm luật lệ như nghiện những thứ thuốc chữa bệnh và bắt đầu sử dụng ma túy, đánh bạc, anh vẫn dần được thăng chức trở lại sau khi đã nhận huy chương và được thăng cấp lên chức đại úy hải quân vì sự dũng cảm của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Russell M. Haeuser","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
