INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('michael-jackson-do-la-anh', 'Michael Jackson: Đó Là Anh', 'This Is It', 'https://phimimg.com/upload/vod/20240102-1/30c16f25fb2d4d22608ff91ffd37e725.jpg', 'https://phimimg.com/upload/vod/20240102-1/4bd8ce217bd6b85440386c0727c987eb.jpg', '<p>This Is It là một món quà của Michael gửi đến các fan. Người hâm mộ sẽ thấy được hình ảnh Michael mà chúng ta chưa từng thấy trước đây: một nghệ sĩ vĩ đại trong công việc. Bộ phim sống động, giàu xúc cảm, cảm động đến rơi nước mắt và cũng ẩn chứa đầy sức mạnh.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jackson","avatar":""},{"name":"Alex Al","avatar":""},{"name":"Alexandra Apjarova","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324477);
