INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-long-ho-tranh-dau', 'Phong Vân: Long Hổ Tranh Đấu', 'The Storm Warriors', 'null', 'https://phimimg.com/upload/vod/20231231-1/13ce1af07bcc4f772eb9bc7dec93f9fd.jpg', '<p>Wind and Cloud thấy mình chống lại một lãnh chúa Nhật tàn nhẫn có ý định xâm lược Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Sing Sing (昵称) / Fu Shing Kwok (本名)","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"kenny ho","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Tiffany Tang","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Suet Lam","avatar":""},{"name":"KENNY WONG","avatar":""},{"name":"Candy Liu","avatar":""},{"name":"ANSONLEUNG","avatar":""},{"name":"Hồng Thiên Chiếu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
