INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-vien-ngoc-rong-thoi-dai-tien-hoa', '7 Viên Ngọc Rồng: Thời Đại Tiến Hóa', 'Dragonball: Evolution', 'https://phimimg.com/upload/vod/20231231-1/44f89b434fd585f34b73883a153908cd.jpg', 'https://phimimg.com/upload/vod/20231231-1/3de78ea54bbec1eba98a5092cdd4ead7.jpg', '<p>Câu chuyện kể về một thanh niên nhút nhát tên Goku. Goku được ông nội Gohan nuôi dạy từ bé, đồng thời cũng truyền cho cậu những tuyệt học võ nghệ cả đời. Vào sinh nhật thứ 18 của Goku, ông nội cậu bị giết chết, và theo lời căn dặn của ông, cậu lên đường tìm kiếm sư phụ Roshi. Trên đường cậu gặp Bulma, và nhờ cô gái này giúp đỡ mà cuối cùng cậu cũng đến được nơi ở của Roshi. Không những không được tiếp đón mà cậu còn phải giao chiến sống chết với Roshi trước khi Quy tiên sinh biết cậu chính là cháu trai của Gohan. Roshi bắt đầu huấn luyện cho Goku để chuẩn bị cho cậu một nền tảng võ công vững chắc, nhằm đủ sức chống trả lại sự tàn ác của những kẻ muốn độc chiếm ngọc rồng. Goku dần biết rõ về bí mật của ngọc rồng, về sức mạnh của sự hội tụ bảy viên ngọc đang rải rác khắp nơi trên thế giới, và cũng ý thức được nếu cậu không nhanh tay giành lấy những viên ngọc thần kỳ, những thế lực xấu sẽ dùng chúng để hủy diệt tất cả.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Chatwin","avatar":""},{"name":"James Marsters","avatar":""},{"name":"Yun-Fat Chow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324477);
