INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-bien-2009', 'Vượt Biên', 'Crossing Over', 'https://phimimg.com/upload/vod/20240102-1/80113886362f535bf3db1db72367a429.jpg', 'https://phimimg.com/upload/vod/20240102-1/d1dce9b55b0c093554e9f7267c238403.jpg', '<p>Crossing Over là một dải đa nhân vật về người nhập cư quốc tịch khác nhau đấu tranh để đạt được trạng thái pháp lý tại Los Angeles. Bộ phim đề với biên giới, gian lận tài liệu, tị nạn và quá trình thẻ xanh, chỗ làm việc thực thi pháp luật, tịch, văn phòng chống khủng bố và cuộc đụng độ của các nền văn hóa. Viết bởi Wayne Kramer</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Cliff Curtis","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
