INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-dem', 'Chuyến Tàu Đêm', 'Night Train', 'https://phimimg.com/upload/vod/20240102-1/e1c9641ba54a4cb2cccaca98f74705f8.jpg', 'https://phimimg.com/upload/vod/20240102-1/fec92f48720cd5f0069319d36a658578.jpg', '<p>Hai hành khách và người lái tàu điện phát hiện một thanh niên trên tàu đang giữ một viên kim cương quý giá và họ đã hợp tác với nhau để cướp viên kim cương này. Sau khi giết người thanh niên, họ xô anh ta xuống dòng sông. Để tránh không bị phát hiện, họ làm trương phồng cơ thể anh ta và cho vào một xe tải nhỏ. Tuy nhiên, sau đó họ bắt đầu có những âm mưu riêng hòng chiếm đoạt viên kim cương cho mình...</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Glover","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"Steve Zahn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
