INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ganesh', 'Ganesh', 'Ganesh', 'https://phimimg.com/upload/vod/20231231-1/c923f2ecb8d3634d5bb95cb8bcbe41c4.jpg', 'https://phimimg.com/upload/vod/20231231-1/e85bfb6114d454a63b3184ab680e2c2f.jpg', '<p>Để giúp một người bạn, Ganesh giả vờ yêu một cô gái. Cô ấy ghét anh ta khi cô ấy phát hiện ra sự thật. Cuối cùng, anh ấy thực sự yêu cô ấy và phải thuyết phục cô ấy về tình cảm thực sự của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ram Pothineni","avatar":""},{"name":"Kajal Agarwal","avatar":""},{"name":"Poonam Kaur","avatar":""},{"name":"Brahmanandam","avatar":""},{"name":"Ananth","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
