INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ganesh', 'Ganesh', 'Ganesh', 'ganesh ganesh ram pothineni kajal agarwal poonam kaur brahmanandam ananth ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiet-4-kinh-hoang', 'Tiết 4 Kinh Hoàng', '4th Period Mystery', 'https://phimimg.com/upload/vod/20240124-1/118dd2215eba97c47ffdb788018a0e9b.jpg', 'https://phimimg.com/upload/vod/20240124-1/f271ba409b3c9cf8bb7924bb6b73b460.jpg', '<p>Khi tất cả các học sinh đang học thể dục vào tiết 4 thì Jung Hoon (Yoo Seung Ho) quay về lớp và phát hiện ra cậu bạn cùng lớp Tae Gyu (Jo Sang Keun) bị giết hại. Jung Hoon và Tae Gu đã từng có xích mích với nhau trước đó. Cùng lúc ấy, Da Jung (Kang So Ra) bước vào lớp thấy quần áo Jung Hoon dính đầy máu và đang đứng gần cái xác chết nhưng Da Jung không tin Jung Hoon đã giết chết Tae Gyu. Chỉ còn lại 40 phút trước khi đến tiết học tiếp theo, vì học sinh sẽ kéo về lớp và phát hiện ra cái xác chết nên Da Jung và Jung Hoon buộc phải tìm ra hung thủ thực sự trước khi tiết thể dục kết thúc. Nhờ vào óc suy luận của Da Jung, họ đã từ từ lần ra thân phận của kẻ giết người, nhưng khi sắp hết 40 phút Jung Hoon và Da Jung lại phát hiện ra một sự thật tàn bạo khác của vụ án…</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chi-yong Ahn","avatar":""},{"name":"In-sook Choi","avatar":""},{"name":"Jae-sang Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
