INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-lan-nua-2009', 'Yêu Lần Nữa', 'The Rebound', 'https://phimimg.com/upload/vod/20231230-1/4bac3ca6b1c27671c1e080ee31a08413.jpg', 'https://phimimg.com/upload/vod/20231230-1/885c27e3e99ffb81019ceb236dbb36de.jpg', '<p>Khi phát hiện ra sự không chung thủy của chồng, Sandy rời vùng ngoại ô và chuyển vào thành phố. Ở đó, cô kết bạn với Aram, một anh chàng có vợ chỉ cưới anh ta để cô ấy có thẻ xanh. Sandy thuê Aram làm bảo mẫu của mình, và không lâu sau Aram và Sandy phát hiện ra họ rất hợp nhau và bắt đầu hẹn hò. Nhưng mối quan hệ của họ có thật hay thực tế chỉ là sự phục hồi cho cả hai?</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Art Garfunkel","avatar":""},{"name":"Joanna Gleason","avatar":""},{"name":"Lynn Whitfield","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324477);
