INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-chien-ma-ca-rong', 'Tử Chiến Ma Cà Rồng', 'Daybreakers', 'https://phimimg.com/upload/vod/20231230-1/cde5caf16e502d8291dd51e1024e9235.jpg', 'https://phimimg.com/upload/vod/20231230-1/0d49716104a2087e9458e3201bb3b79c.jpg', '<p>Vào năm 2019, khi một bệnh dịch lạ đã biến hầu hết con người trên thế giới trở thành ma cà rồng. Đối mặt với nguy cơ thiếu nguồn máu từ con người – thức ăn của ma cà rồng - một nhóm ma cà rồng quyết định lập một “trang trại người” nhằm duy trì nguồn máu và đảm bảo sự sinh tồn của mình. Cùng lúc đó, một nhà nghiên cứu quyết tìm cách hồi phục ma cà rồng trở lại làm người.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Sam Neill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
