INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-vo-2009', 'Đổ Vỡ', 'Cracks', 'https://phimimg.com/upload/vod/20231230-1/21cd380845084d13611a6b2d19ea4d94.jpg', 'https://phimimg.com/upload/vod/20231230-1/6680a5cac7aea719bc5447a1f27a7455.jpg', '<p>Tại một trường nội trú Elite Girls, đội lặn giành giải thưởng được coi là nhóm các cô gái hàng đầu trong trường. Khi một cô gái mới đến từ Tây Ban Nha, Fiamma, đến trường và gia nhập đội, phần còn lại của đội hình đang ghen tị với mối quan hệ của cô với huấn luyện viên và buộc cô ra khỏi đội và ra khỏi trường bằng cách bắt nạt cô. Khi cô gái bị buộc phải tham gia nhóm, họ quyết định cho cô ấy vào vòng tròn xã hội của họ và bắt đầu say mê với cô ấy như huấn luyện viên của họ. Nhưng mọi thứ diễn ra khi huấn luyện viên cho phép niềm đam mê của cô dẫn đến cô quá xa.</p>', 'Full', 1, 'single', 'completed', 28, 2009, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
