INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-sau-anh-mat-2009', 'Bí Mật Sau Ánh Mắt', 'The Secret In Their Eyes', 'https://phimimg.com/upload/vod/20231219-1/0692035f01c3e1b62b5c9d9d6de9a08f.jpg', 'https://phimimg.com/upload/vod/20231219-1/e95854bf46748ca68cc48e36475423c5.jpg', '<p>Bộ phim The secret in their eyes (tựa gốc là El secreto de Sus Ojos) kể về một công tố viên đã nghỉ hưu nhưng vẫn bị ám ảnh bởi vụ án cưỡng hiếp và giết người kéo dài suốt 25 năm. The secret in their eyes là một trong những bất ngờ hiếm hoi tại lễ trao giải Viện hàn lâm Điện ảnh Mỹ năm 2009, khi tác phẩm này chiến thắng ngoài dự đoán hạng mục phim tiếng nước ngoài hay nhất và là lần thứ hai điện ảnh Argentina giành tượng vàng Oscar.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Ricardo Darín","avatar":""},{"name":"Soledad Villamil","avatar":""},{"name":"Pablo Rago","avatar":""},{"name":"Javier Godino","avatar":""},{"name":"Guillermo Francella","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
