INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-long-dai-duong', 'Dưới Lòng Đại Dương', 'Under The Sea 3D', 'https://phimimg.com/upload/vod/20231219-1/14a7edf25e82ce7db8fab8e80b288925.jpg', 'https://phimimg.com/upload/vod/20231219-1/39f6bc07fdd7e7100235651c0a6bc0af.jpg', '<p>Phim Dưới Lòng Đại Dương - Under the Sea 3D 2009: Đại dương ẩn chứa nhiều bí ẩn và vẻ đẹp không thể tả bằng lời, mời các bạn theo dõi những loài động vật sống ở dưới sâu trong lòng đại dương bao la.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324477);
