INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-kells', 'Bí Mật Của Kells', 'The Secret Of Kells', 'https://phimimg.com/upload/vod/20231219-1/b3689707afcf6ed2e1a17cd941bef569.jpg', 'https://phimimg.com/upload/vod/20231219-1/5b4cb69736b661e04948997de7b5e63a.jpg', '<p>The Secret of Kells, là câu chuyện về cậu bé 12 tuổi Brendan và cuộc phiêu lưu để hoàn thành The Book of Kells, mộtcuốn sách có thực của thế kỷ thứ 9, được người dân Ireland coi là quốc bảo. Trước khi làm Tu viện trưởng, bác của Brendan từng là một Illuminator - một họa sư tài ba. Bị nguy cơ xâm lăng của hải tặc Viking ám ảnh, ông dồn tâm sức để xây dựng một tòa thành bảo vệ người dân địa phương. Cậu bé Brendan lớn lên trong vòng tay quản thúc của ông bác và sống một cuộc đời bình lặng sau những bức tường thành. Nhưng một ngày kia, tất cả đã hoàn toàn thay đổi với sự xuất hiện của Họa sư Aidan cùng chú mèo Pangur Ban. Ông lão râu bạc đã khơi dậy nơi Brendan tình yêu dành cho nghệ thuật trang trí sách và thôi thúc cậu khám phá thế giới ngoài những bức tường thành.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan McGuire","avatar":""},{"name":"Christen Mooney","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Mick Lally","avatar":""},{"name":"Liam Hourican","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324477);
