INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mon', 'Đồng Môn', 'Rebellion', 'https://phimimg.com/upload/vod/20231219-1/e059bc625ef12909bccd93dd1c71f2de.jpg', 'https://phimimg.com/upload/vod/20231219-1/a54fa12abe6eccf8c35075adcd6191bb.jpg', '<p>Jimmy, 1 trong Ngũ đại đương gia của giới giang hồ tại Hồng Kông bị ám sát và gần chết. Ngũ Bảo (cảnh sát chìm được cài vào), cận vệ của Jimmy, được đưa lên nắm quyền tạm thời kéo theo sự bất phục của nhị gia Hắc Thủy. Thủ phạm và nguyên nhân chưa được làm rõ, sự nghi kị giữa các đại ca, sự bất phục của Hắc Thủy đã tạo nên 1 làn sóng ngầm càng ngày càng dữ dội trong giới giang hồ. Cảnh sát Hồng Kông cũng nhân cơ hội này đào sâu vào mối hiềm khích đó và chờ cơ hội ra tay. Cuộc nổi loạn trong đêm, đêm u tối đó đã làm thay đổi trật tự băng nhóm trong giang hồ. Bao xác người nằm xuống, máu tuôn như mưa...</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shawn Yue","avatar":""},{"name":"Giang Nhược Lâm","avatar":""},{"name":"Đỗ Vấn Trạch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324477);
