INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-binh-harry-brown', 'Cựu Binh Harry Brown', 'Harry Brown', 'https://phimimg.com/upload/vod/20231219-1/a6589bfc4c68c499b4a2ea00cc874fae.jpg', 'https://phimimg.com/upload/vod/20231219-1/7d49472627d398ff7fbc6ea4d089e697.jpg', '<p>Một cựu quân nhân lớn tuổi và góa vợ tìm cách trả thù cho kẻ giết người bạn thân nhất của mình bằng cách thực hiện hình thức công lý của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Caine","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Lee Oakes","avatar":""},{"name":"Liam Cunningham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324477);
