INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-co-don', 'Người Đàn Ông Cô Đơn', 'A Single Man', 'https://phimimg.com/upload/vod/20231219-1/81a9485d6412feb262463207336976a9.jpg', 'https://phimimg.com/upload/vod/20231219-1/9205bfa82b96560bb4596d917a4bf29a.jpg', '<p>Cuộc sống của George Falconer, một giáo sư đại học người Anh, đang quay cuồng với sự ra đi đột ngột của người bạn đời lâu năm. Sự kiện đau buồn này khiến George thử thách ý chí sống của chính mình khi anh tìm kiếm sự an ủi từ người bạn gái thân Charley, người đang phải vật lộn với những câu hỏi của chính mình về cuộc sống.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Jon Kortajarena","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
