INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-cua-john-lennon', 'Tuổi Trẻ Của John Lennon', 'Nowhere Boy', 'https://phimimg.com/upload/vod/20231219-1/5653ed41b13f8766c61b5da93ca5592e.jpg', 'https://phimimg.com/upload/vod/20231219-1/62453e418ed05fa3e2e6c375e08fcdb7.jpg', '<p>Câu chuyện về thời thơ ấu của John Lennon (Aaron Taylor-Johnson) từ năm 1944 đến 1960, mối quan hệ của anh với dì Mimi (Dame Kristin Scott Thomas) và mẹ của anh Julia (Anne-Marie Duff) - hai phụ nữ thống trị trong lần đầu tiên một phần của cuộc sống của mình; Cuộc gặp đầu tiên của ông với Sir Paul McCartney (Thomas Brodie-Sangster) và George Harrison (Sam Bell), tình bạn của họ, tình yêu của họ dành cho âm nhạc và sự ra đời của Beatles.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324477);
