INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuoi-tre-cua-john-lennon', 'Tuổi Trẻ Của John Lennon', 'Nowhere Boy', 'tuổi trẻ của john lennon nowhere boy  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-xanh-tran-chien-dau-tien', 'Chiến Binh Xanh: Trận Chiến Đầu Tiên', 'Green Lantern: First Flight', 'https://phimimg.com/upload/vod/20231219-1/0fd6ee81768b5a7dde993752a6b87042.jpg', 'https://phimimg.com/upload/vod/20231219-1/28e4a289fa2c8fef7c744c14c407cfe8.jpg', '<p>Trong vũ trụ mênh mông mang theo những điều huyền bí to lớn có một lực lượng tuy nhỏ nhưng rất hùng mạnh đã tồn tại qua hàng thế kỉ. Là những người bảo vệ hòa bình và công lý, họ được gọi là quân đoàn Green Lantern. Những chiến binh Green Lantern đã thề rằng phải giữ được trật tự và bình yên trong dải ngân hà này, nên mỗi người đeo một chiếc nhẫn chứa đựng siêu quyền năng. Nhưng khi Parallax, kẻ thù mới của họ, đe dọa sẽ phá hủy sự cân bằng quyền năng trong vũ trụ, định mệnh của họ và số phận của Trái đất nằm trong tay thành viên mới nhất của quân đoàn, con người đầu tiên được lựa chọn: Hal Jordan.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christopher Meloni","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Tricia Helfer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324477);
