INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rupauls-drag-race-cuoc-chien-giay-cao-got-phan-1', 'Rupaul''s Drag Race - Cuộc Chiến Giày Cao Gót (Phần 1)', 'RuPaul''s Drag Race (Season 1)', 'https://phimimg.com/upload/vod/20240116-1/0d9a0db498f51f5360f7f8366eedc9c7.jpg', 'https://phimimg.com/upload/vod/20240116-1/296465084347d86b4cbaa85ee1978337.jpg', '<p>Trong chương trình giành giải Emmy này do RuPaul làm người dẫn chương trình, các nữ hoàng tranh tài để giành 100.000 USD và danh hiệu Siêu sao Drag Mỹ Tiếp theo.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 8, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"RuPaul Charles","avatar":""},{"name":"Michelle Visage","avatar":""},{"name":"Ross Mathews","avatar":""},{"name":"Carson Kressley","avatar":""},{"name":"Santino Rice","avatar":""},{"name":"Merle Ginsberg","avatar":""},{"name":"Billy B","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324477);
