INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('haeundae', 'Haeundae', 'Haeundae', 'https://phimimg.com/upload/vod/20231215-1/29736bd5df13b113087883da2c12f7ad.jpg', 'https://phimimg.com/upload/vod/20231215-1/f4fd1f6aafe2f6520fd5af52259dccbd.jpg', '<p>Một ngư dân mang mặc cảm tội lỗi chăm sóc một người phụ nữ mà cha của họ vô tình bị giết. Một nhà khoa học đoàn tụ với vợ cũ và một cô con gái thậm chí không nhớ mặt. Và một nhân viên cứu hộ nghèo phải lòng một cô gái thành phố giàu có. Khi tất cả phát hiện ra một cơn sóng thần khổng lồ sẽ ập vào bãi biển, họ nhận ra rằng họ chỉ còn 10 phút để trốn thoát.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sol Kyung-Gu","avatar":""},{"name":"Ha Ji Won","avatar":""},{"name":"Joong-Hoon Park","avatar":""},{"name":"Unm Jung Hwa","avatar":""},{"name":"Min-ki Lee","avatar":""},{"name":"강예원","avatar":""},{"name":"Kang Yea-Won","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324477);
