INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-51', 'Hành Tinh 51', 'Planet 51', 'https://phimimg.com/upload/vod/20231215-1/d114a3ba350c36e40e034951bd8c24ec.jpg', 'https://phimimg.com/upload/vod/20231215-1/2ed5639ebd37938684a6437b722fa588.jpg', '<p>Khi phi hành gia Trái đất, Đại úy Chuck Baker đến Hành tinh 51 -- một thế giới gợi nhớ đến vùng ngoại ô của Mỹ vào khoảng năm 1950 -- anh ấy cố gắng tránh bị bắt, phục hồi tàu vũ trụ của mình và về nhà an toàn, tất cả đều nhờ sự giúp đỡ của một sinh vật xanh nhỏ bé đồng cảm.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Gary Oldman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324477);
