INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-quai-sieu-dang', 'Tứ Quái Siêu Đẳng', 'The Men Who Stare At Goats', 'https://phimimg.com/upload/vod/20231213-1/b8a6e56c2dd5658c492c14938c5edc64.jpg', 'https://phimimg.com/upload/vod/20231213-1/18880a64244a2ac63cc40c429882eb31.jpg', '<p>Một phóng viên ở Iraq có thể có câu chuyện để đời khi anh gặp Lyn Cassady, một anh chàng tự xưng là cựu thành viên của Quân đội Trái đất Mới của Quân đội Hoa Kỳ, một đơn vị sử dụng sức mạnh huyền bí trong các nhiệm vụ của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Robert Patrick","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324477);
