INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phobia-2', 'Phobia 2', 'Phobia 2', 'https://phimimg.com/upload/vod/20240111-1/f67c4c3cfdf5e6447bba3a0263ceee1f.jpg', 'https://phimimg.com/upload/vod/20240111-1/5ca0e95dc165dcc64ca21d310e2ba7ad.jpg', '<p>Phobia 2 bao gồm năm phân khúc phim ngắn chỉ đạo bởi năm trong số năm của các đạo diễn hay nhất của các bộ phim kinh dị Thái Lan. Một thiếu niên đã thực hiện một tội ác đi đến một nơi linh thiêng để thiền định và trốn mà mang lại cho anh ta sợ hãi và cảm giác tội lỗi về những gì anh ta đã làm (Megment Novice). Một chàng trai trẻ bị ám ảnh trong một bệnh viện bởi một ông già hôn mê, người không quá xa anh ta (phường phân khúc). Hai người đàn ông cùng với hai người quá giang trong một chiếc xe tải gặp rắc rối lớn sau khi mở lưng (phân khúc ba lô). Một đại lý xe hơi đã nhận ra những gì chủ sở hữu / hành khách ô tô trước đó đã được đưa vào (trục vớt phân khúc). Một nữ diễn viên chăm chỉ xấu có vai trò là một con ma được báo cáo đã chết sau khi cô được đưa đến bệnh viện.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
