INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-duong', 'Cha Dượng', 'The Stepfather', 'https://phimimg.com/upload/vod/20231213-1/c6c977730b51a2eeda595784792955c5.jpg', 'https://phimimg.com/upload/vod/20231213-1/883c54ad88116baa4f102be042b33adf.jpg', '<p>Michael Harding trở về nhà từ trường quân sự và thấy mẹ anh đang hạnh phúc yêu và chung sống với bạn trai mới của bà, David. Khi hai người quen nhau, Michael ngày càng nghi ngờ người đàn ông luôn ở bên giúp đỡ. Anh ấy thực sự là người đàn ông trong mơ của cô hay David có thể đang che giấu một mặt tối?</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan Walsh","avatar":""},{"name":"Sela Ward","avatar":""},{"name":"Penn Badgley","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Deirdre Lovejoy","avatar":""},{"name":"Marcuis Harris","avatar":""},{"name":"Sherry Stringfield","avatar":""},{"name":"Nancy Linehan Charles","avatar":""},{"name":"Blue Deckert","avatar":""},{"name":"Paige Turco","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324477);
