INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-su-hoai-nghi', 'Vượt Quá Sự Hoài Nghi', 'Beyond A Reasonable Doubt', 'https://phimimg.com/upload/vod/20231213-1/6666647f393dbc97a74bb2b1865c4ffa.jpg', 'https://phimimg.com/upload/vod/20231213-1/8ad63e67d4ee8aacc9c2b193706dc5ab.jpg', '<p>Những bí mật, những âm mưu thanh toán lẫn nhau của giới xã hội đen chắc chắn sẽ lôi cuốn khán giả trong suốt gần 90 phút của phim. Tiêu đề của phim cũng rất gây ấn tượng: Tại sao một người đàn ông lại dàn dựng cho anh ta một… án mạng? Đây cũng là phim mới nhất của nam diễn viên gạo cội Michael Douglas, người từng rất nổi tiếng với thể loại phim này vào những thập kỷ 80, 90. Phim còn có sự tham gia của 2 diễn viên trẻ tiềm năng của Hollywood: Jesse Metcalfe và Amber Tamblyn.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Jesse Metcalfe","avatar":""},{"name":"Amber Tamblyn","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Orlando Jones","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
