INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-sa-mac', 'Hoa Sa Mạc', 'Desert Flower', 'https://phimimg.com/upload/vod/20231212-1/2713ae39de44fcafd5530ac2ed3f8fbe.jpg', 'https://phimimg.com/upload/vod/20231212-1/cec8e321507e600ef408c972644954a8.jpg', '<p>Waris Dirie, sinh năm 1965 tại Somalia, chạy trốn lúc 13 tuổi khi được bán là người vợ thứ 4. Cô ấy là người giúp việc tại Đại sứ quán Somalian ở London, sau đó là McDonald, nơi cô ấy được phát hiện và trở thành người mẫu hàng đầu quốc tế. 1997, cô ấy lên tiếng chống lại sự cắt xén bộ phận sinh dục nữ.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324478);
