INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-doi-mau', 'Ngọn Đồi Máu', 'The Hills Run Red', 'https://phimimg.com/upload/vod/20240108-1/711608f80b6c7207b092e2fc1d6e578c.jpg', 'https://phimimg.com/upload/vod/20240108-1/6d8246d791e4f06e2971b6cf726d14ec.jpg', '<p>Một nhóm những người hâm mộ phim kinh dị trẻ tuổi đi tìm kiếm một bộ phim đã biến mất một cách bí ẩn nhiều năm trước nhưng thay vào đó lại phát hiện ra rằng kẻ giết người mất trí nhớ trong phim là có thật, và anh ấy rất vui mừng được gặp những người hâm mộ sẽ chết một cách khủng khiếp vì nghệ thuật của anh ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Monk","avatar":""},{"name":"Tad Hilgenbrink","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Janet Montgomery","avatar":""},{"name":"Alex Wyndham","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
