INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-khoan-nhuong', 'Không Khoan Nhượng', 'The Horde', 'https://phimimg.com/upload/vod/20240108-1/3f482bc642d795008820c13cd6cccfa5.jpg', 'https://phimimg.com/upload/vod/20240108-1/2dc3834ce44a1617865117f37a27ae3e.jpg', '<p>Một nhóm cảnh sát quanh co đột kích vào một tòa nhà đổ nát nằm ở vùng ngoại ô nghèo khó của Paris, quyết tâm trả thù một cách điên cuồng cho cái chết của một trong số họ, bị sát hại bởi băng đảng tội phạm tàn nhẫn ẩn náu trên mê cung tối tăm sẽ trở thành một cái bẫy chết người khi người sống , bất ngờ bị một bệnh dịch bí ẩn biến thành xác sống, bắt đầu nuốt chửng thế giới.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Claude Perron","avatar":""},{"name":"Jean-Pierre Martins","avatar":""},{"name":"Ériq Ebouaney","avatar":""},{"name":"Aurélien Recoing","avatar":""},{"name":"Doudou Masta","avatar":""},{"name":"Antoine Oppenheim","avatar":""},{"name":"Jo Prestia","avatar":""},{"name":"Yves Pignot","avatar":""},{"name":"Adam Pengsawang","avatar":""},{"name":"Alain Figlarz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324478);
