INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-cun-cung', 'Khách Sạn Cún Cưng', 'Hotel For Dogs', 'https://phimimg.com/upload/vod/20231211-1/bf480ef703c1afa4e055562b6bd6d923.jpg', 'https://phimimg.com/upload/vod/20231211-1/578b5e84a3155a4cc4656c62e2ae12b9.jpg', '<p>Được đưa vào một nhà nuôi dưỡng không cho phép nuôi thú cưng, Andi, 16 tuổi và em trai cô, Bruce, biến một khách sạn bỏ hoang thành nhà cho chú chó của họ. Chẳng mấy chốc, những chú chó đi lạc khác cũng đến, và khách sạn trở thành thiên đường cho mọi chú chó mồ côi trong thị trấn. Nhưng bọn trẻ phải suy nghĩ thật nhanh để không bị cảnh sát theo đuôi.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Roberts","avatar":""},{"name":"Jake T. Austin","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Kyla Pratt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324478);
