INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-hon-ma', '7 Hồn Ma', 'The Seven Ghosts', 'https://phimimg.com/upload/vod/20231219-1/b54b3f2e83a94cf8c272f7a66e3751c5.jpg', 'https://phimimg.com/upload/vod/20231219-1/756414e196573655aa940cbcc5e2b653.jpg', '<p>Bối cảnh câu chuyện diễn ra trong một thế giới gothic fantasy, kể về Teito Klein. Một nô lệ mồ côi, người đã trở thành học viên xuất sắc nhất của Học viện Quân đội.Tuy nhiên, một sự kiện bất ngờ đã làm cho cậu bị rượt đuổi bởi lực lượng của Đế quốc Barsburg. Để thoát bị kết án, nhà thờ đã che chở cho Teito dựa vào luật lệ dành cho nơi tôn nghiêm. Ở đây, cậu đã phát hiện ra nhiều bí ẩn xung quanh bản thân, nhà thờ và Đế quốc.Sự thật là cậu có liên quan với một vị vua đã bị hạ bệ và viên đá huyền bí của thượng đế, “con mắt của Mikhael” (Eye of Micheal), chính điều này khiến cậu trở thành mục tiêu của Đế quốc. May mắn thay, trên đường chạy trốn, cậu được các linh mục trong nhà thờ, 7 Hồn Ma – 7 Ghost huyền thoại che chở.Liệu Teito có thoát được khỏi nanh vuốt của Quân đội không?Bí ẩn thân phận của cậu là gì?Tham mưu trưởng Ayanami thật sự là ai….</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 8, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324478);
