INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-co-dau', 'Cuộc Chiến Cô Dâu', 'Bride Wars', 'https://phimimg.com/upload/vod/20231211-1/af0f0ebe640fdf43c3a28b7846a31fd1.jpg', 'https://phimimg.com/upload/vod/20231211-1/75a1515205845650329e38ce22c0f10e.jpg', '<p>Cuộc Chiến Cô Dâu - Bride Wars kể về Emma và Liv vốn là đôi bạn thân từ thưở nhỏ, và như bao cô gái khác, cả hai đều có những mơ ước rất lý tưởng dành cho ngày trọng đại trong đời của mình, và gạch đầu dòng đầu tiên cho chuỗi những điều phải làm vào ngày cưới đó là phải tổ chức tại thánh đường dành cho các cô dâu ở New York - khách sạn Plaza. Nay họ đã cùng 26 tuổi, đang cùng nhau hiện thực hóa ước mơ của mình, và tưởng chừng như sẽ là hai cô dâu hạnh phúc nhất, nếu như không họ không phải tranh giành nhau thánh đường trong cùng một ngày. Không ai chịu nhường nhịn ai, và họ bắt đầu cảm thấy khó chịu về người bạn của mình. Khác hẳn với những gì tốt đẹp đã dành cho nhau lúc trước, cả hai bắt đầu ra sức tìm mọi cách để nói xấu và phá hoại đám cưới của người kia. Họ xem nhau như kẻ thù, và giữa họ đã nổ ra trận chiến, một trận chiến thật sự dành cho các cô dâu.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Candice Bergen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
