INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cong-cuoi-cung-thoi-mao-trach-dong', 'Vũ Công Cuối Cùng Thời Mao Trạch Đông', 'Mao''s Last Dancer', 'https://phimimg.com/upload/vod/20231211-1/8e97dfd242ac84c6c92579ad23df24de.jpg', 'https://phimimg.com/upload/vod/20231211-1/be558a77d096865bd76b8da76902fc80.jpg', '<p>Năm 11 tuổi, Li được các đại biểu văn hóa của Bà Mao đưa ra khỏi một ngôi làng nghèo ở Trung Quốc và đưa đến Bắc Kinh để học múa ba lê. Năm 1979, trong một lần trao đổi văn hóa ở Texas, ông đã yêu một phụ nữ Mỹ. Hai năm sau, anh tìm cách đào tẩu và tiếp tục biểu diễn với tư cách là vũ công chính cho Houston Ballet và là nghệ sĩ chính của Australian Ballet.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chi Cao","avatar":""},{"name":"Chengwu Guo","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Amanda Schull","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Camilla Vergotis","avatar":""},{"name":"Madeleine Eastoe","avatar":""},{"name":"Steven Heathcote","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
