INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-gi-ngoai-su-that', 'Không Gì Ngoài Sự Thật', 'Nothing But The Truth', 'https://phimimg.com/upload/vod/20231211-1/b4a80beacab2804c2d183d93e3f4d773.jpg', 'https://phimimg.com/upload/vod/20231211-1/08c03b5bd3a899739125747176eb391d.jpg', '<p>Rachael - nữ nhà báo một lần vô tình đã biết được một bí mật chính trị. Cô đăng bài báo đó mà không biết mình sẽ bị rắc rối với CIA. Cô bảo vệ người cung cấp tin và bị tuyên phạt tù. Khi đang thụ án, chồng cô đã ngoại tình với một phụ nữ khác và cô có nguy cơ đánh mất gia đình mình khi mãn hạn tù.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Andela Bassett","avatar":""},{"name":"Alan Alda","avatar":""},{"name":"Vera Farmiga","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
