INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hachiko-chu-cho-trung-thanh', 'Hachiko Chú Chó Trung Thành', 'Hachi: A Dog''s Tale', 'https://phimimg.com/upload/vod/20231211-1/439174fbc847a7deb42141d36c10996e.jpg', 'https://phimimg.com/upload/vod/20231211-1/97de96da93dbc891d638c32f19f70a42.jpg', '<p>Đi lại bằng tàu hỏa, giáo sư âm nhạc Parker Wilson tìm thấy một con chó con Akita, có lồng không được chú ý trong quá trình vận chuyển, để lại chỗ ở của anh ta, và vì nhà ga không thể quan tâm đến nó và người bắt chó cảnh báo ngay cả những người dễ thương như vậy có thể không được thông qua trong Hai tuần cho phép, anh ta vui lòng mang nó về nhà. Sachassy, người vợ ghen tị của anh ta ban đầu khiến Parker thề rằng nó sẽ không ở lại, nhưng đến khi nó rõ ràng không ai sẽ yêu cầu anh ta và một ứng cử viên nhận con nuôi được tìm thấy, cô ấy đồng ý giữ con chó, người đã giành chiến thắng trước con gái Andy và vị hôn phu của mình Michael từ cái nhìn đầu tiên. Người bạn đại học Nhật Bản Ken truyền cảm hứng cho việc đặt tên cho Pup Hachi (KO) và rất ngạc nhiên khi Parker đã khắc phục thành công thách thức để có được nó để tìm nạp, mà Akitas thường không làm. Hachi thực hiện một thói quen chờ đợi bậc thầy doting không kém ở nhà ga mỗi tối, nhưng sau một cuộc khủng hoảng tim, Parker chết. Hachi từ chối chấp nhận điều này, được chuyển đến nhà của Michael khi Cate chuyển ra ngoài, chờ đợi một bậc thầy không bao giờ có thể về nhà một lần nữa, bây giờ bằng cách được thông cảm bởi dân tộc thông cảm. Câu chuyện được kể trong những đoạn hồi tưởng là phân công lớp học anh hùng của tôi của con trai tuổi teen của Michael, người cũng có một con chó con akita.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324478);
