INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-va-nguoi-doi-ke-thu-quoc-gia', 'Siêu Nhân Và Người Dơi: Kẻ Thù Quốc Gia', 'Superman - Batman: Public Enemies', 'https://phimimg.com/upload/vod/20231211-1/3b9c842ff217e276e1c3ef6afec7f8c0.jpg', 'https://phimimg.com/upload/vod/20231211-1/5656c7734256ebb61ef07da22642fcf9.jpg', '<p>Khi Lex Luthor được bầu làm Tổng thống Mỹ, ông đã cáo buộc Superman là kẻ thù, buộc Superman làm sao để phá vỡ sao băng Kryptonite chuẩn bị đâm vào trái đất. Superman sẽ hành động thế nào?.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Conroy","avatar":""},{"name":"Tim Daly","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"LeVar Burton","avatar":""},{"name":"Xander Berkeley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324478);
