INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-quy-2', 'Hang Quỷ 2', 'The Descent: Part 2', 'https://phimimg.com/upload/vod/20231211-1/760ab745e73d7acfb162a64c2a4d125c.jpg', 'https://phimimg.com/upload/vod/20231211-1/c684e1971455489674dcefa47ceeae96.jpg', '<p>Phần 2 tiếp nối đoạn kết của phần 1 và lấy bối cảnh hai ngày sau đó, Sarah may mắn thoát khỏi được hang động kinh hoàng nhưng cô hoàn toàn không nhớ được những gì đã xảy ra do quá hoảng loạn. Sarah được đưa đến bệnh viện để dưỡng thương, ngài cảnh sát trưởng Vaines tiếp nhận vụ việc và trong quá trình điều tra ông phát hiện một ít máu dính trên người của Sarah chính là máu của Juno.
 Để tìm thêm manh mối và truy tìm những người còn sống sót trong hang, Vaines quyết định cùng Sarah và ba chuyên gia hang động là Dan, Greg và Cath quay ngược lại hang động đó. Liệu lần này ngài cảnh sát trưởng có tìm thêm được manh mối gì, Sarah có hồi phục trí nhớ và lũ quái vật dưới hang đó là gì.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shauna Macdonald","avatar":""},{"name":"Natalie Mendoza","avatar":""},{"name":"Gavan O''Herlihy","avatar":""},{"name":"Josh Dallas","avatar":""},{"name":"Anna Skellern","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
