INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-phan-boi-2009', 'Kẻ Phản Bội', 'Traitor', 'https://phimimg.com/upload/vod/20240111-1/3b1d40c1cf6ea95f9b52777a1fd132c2.jpg', 'https://phimimg.com/upload/vod/20240111-1/7503af0ab89eaf2d551521185a6626f4.jpg', '<p>Khi đặc vụ FBI Roy Clayton mở ra cuộc điều tra về một âm mưu nguy hiểm ở tầm quốc tế, mọi đầu mối mà Clayton khám phá được đều dẫn đến cựu sĩ quan lực lượng đặc biệt Hoa Kỳ Samir Horn. Với một nhân thân bí ẩn cùng một mạng lưới các mối liên hệ với những tổ chức khủng bố, Horn nhanh chóng trở thành kẻ bị tình nghi số một. Việc Horn có liên quan đến cuộc vượt ngục ở Yemen, vụ nổ bom ở Nice và cuộc đột kích tại Luân Đôn khiến Clayton phải băn khoăn rằng liệu con mồi của mình có đang bất mãn với những sỹ quan điều hành quân đội trước đây của anh ta, hay là, mọi thứ đang dần trở nên rắc rối hơn. Bị ám ảnh với việc phải tìm ra bằng được chân tướng của sự việc, Clayton lao vào cuộc truy nã Horn xuyên suốt cả thế giới, khi mà, người cựu sĩ quan năm xưa đang từ từ chìm sâu vào thế giới của những âm mưu đen tối...</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Don Cheadle","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Archie Panjabi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
