INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-he-tay-ba', 'Quan Hệ Tay Ba', 'Dare', 'https://phimimg.com/upload/vod/20231211-1/0996f6025ad1ad311b5937287dc95c55.jpg', 'https://phimimg.com/upload/vod/20231211-1/68f4a40ef6cf7fba0971f0fdd6a03405.jpg', '<p>Một nữ diễn viên đầy tham vọng, người bạn thân không phù hợp của cô ấy và một kẻ cô độc vướng vào một mối quan hệ thân mật và phức tạp.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emmy Rossum","avatar":""},{"name":"Zach Gilford","avatar":""},{"name":"Ashley Springer","avatar":""},{"name":"Ana Gasteyer","avatar":""},{"name":"Rooney Mara","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
