INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-tan-the', 'Hậu Tận Thế', 'The Road', 'https://phimimg.com/upload/vod/20231211-1/729e9e0dd217c4411e2a2a6e1b2fdf70.jpg', 'https://phimimg.com/upload/vod/20231211-1/40f8e9243214c744c7e7eaea5bb6a243.jpg', '<p>Bối cảnh của phim được lấy vào thời điểm của thế giới Hậu Tận Thế, bắt đầu từ vài năm sau sự kiện cataclysmic, những trận động đất thường xuyên diễn ra luôn là mối hiểm họa chết người. Thế giới trở nên u tối và xám xịt khi ngày càng có nhiều thứ chết đi. Một người đàn ông và đứa con trai đầu lòng tuổi teen, người được sinh ra sau khi tận thế, đang trên con đường tìm kiếm sự sống, kế hoạch của họ để đi bộ đến bờ biển và hướng về phía nam, nơi người đàn ông hy vọng sẽ có một môi trường hiếu khách hơn để sống.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Viggo Mortensen","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Guy Pearce","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
