INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-bloom', 'Anh Em Nhà Bloom', 'The Brothers Bloom', 'https://phimimg.com/upload/vod/20231211-1/36bc0e83b20b07343cfd08207f4f5574.jpg', 'https://phimimg.com/upload/vod/20231211-1/937434056e4055a1394288f2b5039fe3.jpg', '<p>Trong thế giới của hai anh em Bloom, họ đã trở nên lão luyện với những mánh lừa đảo sau nhiều năm bôn ba. Và giờ họ quyết định thực hiện một phi vụ cuối cùng thật ngoạn mục: dẫn dắt một quí cô giàu có vào một kế hoạch tỉ mỉ để tất cả có thể chu du vòng quanh thế giới. Mong muốn được giải nghệ, Bloom nhận lời tham gia trong mưu đồ cuối cùng và cũng là lớn nhất. Anh khéo léo tiếp cận cuộc sống của Penelope, vốn là một phụ nữ độc thân thừa kế đang mang trong mình cảm giác chán chường. Khi một mối tình lãng mạn nảy nở giữa họ, Bloom phải miễn cưỡng khai thác sự ngây thơ của cô, trong khi cô nàng đã say cậu em Bloom như điếu đổ. Nhưng Bloom bắt đầu tự hỏi rằng liệu đây có phải là phi vụ lừa đảo nguy hiểm nhất của ông anh trai?</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel Weisz","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Mark Ruffalo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
