INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pandemic', 'Pandemic', 'Pandemic', 'https://phimimg.com/upload/vod/20231231-1/1ce5eb00efc7029cc1e77b416a92ed63.jpg', 'https://phimimg.com/upload/vod/20231231-1/1c6861a360ef8db85077584c0b1c415e.jpg', '<p>Tsuyoshi Matsuoka, một bác sĩ tại một bệnh viện Tokyo, đã chẩn đoán căn bệnh của bệnh nhân như một cái lạnh thông thường. Nhưng sau cái chết đột ngột của bệnh nhân, anh ta nhận ra rằng bệnh rất nghiêm trọng, có thể tạo ra một dân số tuyệt chủng, vì vậy anh ta vật lộn để tìm ra nguyên nhân gây bệnh với bác sĩ Eiko Kobayashi</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324478);
