INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-cong-truc-dien', 'Tấn Công Trực Diện', 'Direct Contact', 'https://phimimg.com/upload/vod/20231231-1/b8713b86a7b44e06d2da3d49860ed04d.jpg', 'https://phimimg.com/upload/vod/20231231-1/2e48791032f3d1e37347d1591b7ccbdd.jpg', '<p>Mike Riggins, một thành viên trong lực lượng đặc nhiệm của quân đội Mỹ hoạt động tại Đông Âu, đang bị giam tại nhà tù của Nga. Anh được đề nghị đổi tự do của mình nếu đồng ý cứu một người phụ nữ Mỹ, Ana Gale, người đang bị bắt cóc và giam giữ. Nhưng, chẳng bao lâu sau khi cứu được Ana, Mike phát hiện ra rằng câu chuyện bắt cóc chỉ là cái bẫy để đưa Ana được tự do cho các thế lực khác bắt. Từ đó, Mike bị nhiều phe truy đuổi: chính phủ, quân đội, và các tổ chức ngầm mà mục đích của chúng là giết Mike và bắt Ana. Không có ai đề dựa giẫm và kẻ thù thì gần kề, Mike buộc phải tìm hiểu sự thật về Ana và đưa cô về Đại sứ quán Mỹ một cách an toàn.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Gina May","avatar":""},{"name":"Michael Paré","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
