INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-choc-to-ong-bau', 'Cô Gái Chọc Tổ Ong Bầu', 'The Girl Who Kicked The Hornet''s Nest', 'https://phimimg.com/upload/vod/20231230-1/56e62aaec49525535975b7615b945fd0.jpg', 'https://phimimg.com/upload/vod/20231230-1/746c917ed43388984a4db7e594aedea3.jpg', '<p>Lisbeth hôn mê vì phát đạn vào đầu ở cuối phần trước. Bản án sát nhân vẫn treo lơ lửng trên đầu cô. Trong lúc đó, Mikael tìm mọi cách chứng minh sự trong sạch của Lisbeth. Không chỉ phải đối đầu với những thế lực trong bóng tối, nữ Hacker còn phải đối diện quá khứ u ám của mình. The Girl Who Kicked The Hornets Nest kết thúc chùm 3 phần phim Millennium về nữ Hacker Lisbeth Salander.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Michael Nyqvist","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Lena Endre","avatar":""},{"name":"Annika Hallin","avatar":""},{"name":"Jacob Ericksson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
