INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-sau-su-song', 'Phía Sau Sự Sống', 'After Life', 'https://phimimg.com/upload/vod/20231211-1/53034e516d540d771457ea6fa91732ec.jpg', 'https://phimimg.com/upload/vod/20231211-1/e345dee30f1a2dace8407584714ff9a5.jpg', '<p>Sau một tai nạn xe hơi khủng khiếp, Anna tỉnh dậy và thấy mình là nhân vật chính trong 1 buổi tang lễ địa phương do giám đốc chuẩn bị khâm liệm cơ thể của cô. Anna cảm nhận rõ mình chưa chết, nhưng thực tế đã không khẳng định điều đó. Cô dần rơi vào trạng thái chấp nhận cái chết của mình. Bộ phim chuyển đến người xem các khía cạnh không ngừng của mối đe dọa, After Life là một phim kinh dị tâm lý phong cách huyền bí với những câu hỏi khó giải đáp về ranh giới giữa sự sống và cái chết.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Justin Long","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
