INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-o-liban', 'Cuộc Chiến Ở Liban', 'Lebanon', 'https://phimimg.com/upload/vod/20231211-1/745d5c39dcccfcd964995f72cf221f84.jpg', 'https://phimimg.com/upload/vod/20231211-1/e1ccdafd045bad5c44660cd069ea05b3.jpg', '<p>Bộ phim gợi lại những ký ức kinh hoàng của đạo diễn Maoz khi ông còn là một người lính Israel chiến đấu ở Liban năm 1982. Trong phim, bốn người lính Israel giam mình trong chiếc xe tăng, không chứng kiến những cảnh tượng rùng rợn mà họ bỏ lại đằng sau: người phụ nữ phát điên phát cuồng vì đứa con bị sát hại oan nghiệt, người đàn ông đứng tuổi bị lòng hận thù thiêu đốt, sự đau đớn cùng cực của một con lừa bị sổ ruột...</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Yoav Donat","avatar":""},{"name":"Itay Tiran","avatar":""},{"name":"Oshri Cohen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324478);
