INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kurbaan', 'Kurbaan', 'Kurbaan', 'https://phimimg.com/upload/vod/20231210-1/601d22bada3be33d715e85ef8bf76a34.jpg', 'https://phimimg.com/upload/vod/20231210-1/2db970543e5da4f6fcc962c4f9e3612b.jpg', '<p>Avantika Ahuja sống tại Hoa Kỳ cô về Delhi thăm quê hương và cô gặp Ehsaan Khan, một giáo sư Đại học ở Mumbai. Tình yêu nở hoa giữa bầu trời đầy ước hẹn. Bất chấp mọi sự ngăn cản họ đến Mỹ kết hôn và mong muốn có một cuộc sống lâu dài và ổn định. Avantika giúp Ehsaan nhận được một công việc tại trường đại học nơi cô dạy và Ehsaan được bổ nhiệm làm giáo sư dạy Hồi giáo và thế giới hiện đại. Cuộc sống tưởng chừng như hạnh phúc mỹ mãn thì khi cô đang mang thai cô lại tình cờ biết được bí mật thật khủng khiếp về Ehsaan Khan điều đó có thể phá vỡ tình cảm giữa hai người... Hình ảnh chết chóc, bom đạn ám ảnh cô từng đêm dần dần cô lịm dần trong tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Vivek Oberoi","avatar":""},{"name":"Dia Mirza","avatar":""},{"name":"Om Puri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
