INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-nuoc-my', 'Giấc Mơ Nước Mỹ', 'Notorious', 'https://phimimg.com/upload/vod/20231209-1/b0e04a2053ed831928b4a24fb7cc350a.jpg', 'https://phimimg.com/upload/vod/20231209-1/9f6ad44e3d701eca499190e6f4d246df.jpg', '<p>Khét tiếng là câu chuyện của Christopher Wallace. Bằng tài năng bẩm sinh và sự quyết tâm tuyệt đối, Wallace biến mình từ một kẻ hối hả trên đường phố Brooklyn (từng bán crack cho phụ nữ mang thai) thành một trong những rapper vĩ đại nhất mọi thời đại: The Notorious B.I.G. Theo dõi sự nổi tiếng nhanh chóng của anh ấy và việc anh ấy không chịu khuất phục trước những kỳ vọng - định nghĩa lại khái niệm của chúng ta về Giấc mơ Mỹ.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamal Woolard","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Naturi Naughton","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Antonique Smith","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
