INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-cuoc-gia-mao', 'Căn Cước Giả Mạo', 'Double Identity', 'https://phimimg.com/upload/vod/20231208-1/23940224ce33dde13cdc0553136506a5.jpg', 'https://phimimg.com/upload/vod/20231208-1/73d4c847b7bd6af8889a6a997c2b43f8.jpg', '<p>Ở Chechnya, một bác sĩ người Mỹ đi đường vòng trong cuộc đời khi giúp một người phụ nữ bí ẩn thoát khỏi kẻ định tấn công cô.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Val Kilmer","avatar":""},{"name":"Izabella Miko","avatar":""},{"name":"Hristo Shopov","avatar":""},{"name":"Raicho Vasilev","avatar":""},{"name":"Didem Erol","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
