INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xam-nhap-kho-bau-dai-duong-2', 'Xâm Nhập Kho Báu Đại Dương 2', 'Into The Blue 2: The Reef', 'https://phimimg.com/upload/vod/20231208-1/392fac53be766ccf6a5f903981e6f663.jpg', 'https://phimimg.com/upload/vod/20231208-1/48d2c41702de51b7d38ce6ba8b330c28.jpg', '<p>Bộ phim là cuộc phiêu lưu trên biển của hai thợ lặn chuyên nghiệp Sebastion và Dani. Họ được thuê để lặn xuống vùng biển nguy hiểm để tìm kiếm kho báu bí ẩn của Columbus. Tiền công rất hời. Nhưng vì làm việc cho những người không rõ danh tính, họ đã bị đẩy vào tình thế nguy hiểm, thử thách khả năng lặn, cũng như tình yêu, sức mạnh và ý chí sống còn.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Carmack","avatar":""},{"name":"Laura Vandervoort","avatar":""},{"name":"Marsha Thomason","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
