INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-sang-gia', 'Người Thừa Kế Sáng Giá', 'Brilliant Legacy', 'https://phimimg.com/upload/vod/20231207-1/a1165de0d572561c5b7923241056da15.jpg', 'https://phimimg.com/upload/vod/20231207-1/59cdd3b07c4e4ee7297f14e1842f3419.jpg', '<p>Xoay quanh nhân vật Eun Sung (Han Hyo Joo), một cô gái tốt bụng. Sau khi bố qua đời, mẹ kế Baek Sung Hee (Kim Mi Sook đóng) chiếm đoạt toàn bộ tài sản, đẩy Eun Sung ra khỏi nhà buộc cô tự xoay sở kiếm sống và chăm sóc người em trai mắc bệnh tự kỷ. Trong khi đó, bà lại hết mực chiều chuộng con gái riêng là Seung Mi (Moon Chae Won đóng). Trong một lần tình cờ, Eun Sung đã giúp đỡ và cưu mang Jang Sook Ja, bà lão bị mất trí nhớ, đồng thời cũng là chủ tịch tập đoàn thực phẩm Jin Sung. Cảm động vì tấm lòng của Eun Sung, bà Sook Ja đã cho Eun Sung vào làm ở tập đoàn của mình. Không những vậy, bà còn chọn Eun Sung làm người thừa kế toàn bộ tài sản chính thức của bà để dạy dỗ con cháu, đặc biệt là Sun Woo Hwan (Lee Seung Gi đóng), cháu nội của bà, người chỉ biết ỷ lại và lười biếng. Mọi chuyện trở nên phức tạp hơn khi Eun Sung bắt đầu rơi vào mối tình tay ba giữa hai chàng trai: Sun Woo Hwan, người thừa kế tập đoàn và Park Jun Se (Bae Soo Bin), chủ của một dãy nhà hàng lớn, đồng thời cũng là người có hôn ước sắp đặt với em gái của Woo Hwan, Woo Jung (Han Ye Won). Không dừng lại ở đó, Woo Hwan cũng là người mà Seung Mi - em gái kế của Eun Sung yêu thầm bao lâu nay.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 9, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Hyo Joo","avatar":""},{"name":"Lee Seung Gi","avatar":""},{"name":"Bae Soo Bin","avatar":""},{"name":"Moon Chae Won","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
