INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-khu-b13-toi-hau-thu', 'Đặc Khu B13: Tối Hậu Thư', 'Banlieue 13: Ultimatum - District 13: Ultimatum', 'https://phimimg.com/upload/vod/20231210-1/9a256389ad838974f38f24d520b9fac6.jpg', 'https://phimimg.com/upload/vod/20231210-1/6339b683e258310e8b4256c0d92be5d5.jpg', '<p>Damien và Leito trở về từ Quận 13 trong một nhiệm vụ mang lại hòa bình cho khu vực đầy rắc rối, nơi mà đang nằm dưới sự quản lý của năm băng phái găng-tơ khác nhau. Damien và Leito phải nhanh tay hơn lực lượng bí mật của thành phố trước khi họ bắt đầu thực hiện những biện pháp mạnh mẽ, không ghê tay để giải quyết vấn đề của khu vực …</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Cyril Raffaelli","avatar":""},{"name":"David Belle","avatar":""},{"name":"Philippe Torreton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
