INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-giua-dao-hoang', 'Lạc Giữa Đảo Hoang', 'Castaway On The Moon', 'https://phimimg.com/upload/vod/20231208-1/fdc9bd39969a7f5391c87759adb81a1f.jpg', 'https://phimimg.com/upload/vod/20231208-1/e4952d1b1ab6c37665f36e0cea2d7fb3.jpg', '<p>Kim Seung Geun cố gắng tự sát bằng cách nhảy xuống sông Hàn, nhưng cuối cùng anh lại trôi dạt vào đảo Bamseon, một hòn đảo nhỏ không người ở. Mặc dù luôn luôn nỗ lực để thoát khỏi đảo hoang, nhưng Seung Geun đã bắt đầu nhận ra rằng mình có thể sống được ở đây. Seung Geum dần dần phù hợp với cuộc sống trên đảo hoang và gặp Kim Jung Yeon, một phụ nữ sống xa rời thực tế và bị cô lập. Jung Yeon đã sống trong căn phòng của mình 2 năm và chỉ kết nối với thế giới bên ngoài bằng internet. Hai con người bị cô lập ngay chính dòng đời tấp nập. Seung Geun cuối cùng bị đưa vào trại tâm thần và bị coi như một người không bình thường. Rồi hai con người ấy cũng gặp nhau ngoài đời thật, bằng con người thật, chỉ để trao nhau một câu chào...</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Min-heui Hong","avatar":""},{"name":"So-yeon Jang","avatar":""},{"name":"Jae-yeong Jeong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
