INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-2009', 'Thần Bài', 'Poker King', 'https://phimimg.com/upload/vod/20231221-1/22a8d147d48f042185deab9e3cd90a44.jpg', 'https://phimimg.com/upload/vod/20231221-1/11aa7bfdfaa75843bf5f800bd596e13b.jpg', '<p>Cổ Thiên Lạc sẽ đóng cặp với Lưu Thanh Vân. Cả 2 người vào đóng vai những chuyên gia chơi bài poker nổi tiếng và chiến đấu để tranh giành ngôi “thần bài”. Nhân vật của Cổ Thiên Lạc là một người lập dị nhưng lại có khả năng chơi bài tuyệt diệu.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ching Wan Lau","avatar":""},{"name":"Jo Kuk","avatar":""},{"name":"Sherwin Ming","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324478);
