INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-bien-xanh', 'Chuyện Tình Biển Xanh', 'Ondine', 'https://phimimg.com/upload/vod/20231208-1/edc5f3fb787b9c4edd733133b4cf7b22.jpg', 'https://phimimg.com/upload/vod/20231208-1/5b2c403889bbff806f2a20525118bb55.jpg', '<p>Một ngư dân Ireland phát hiện ra một người phụ nữ trong lưới đánh cá của anh ta và tin rằng cô ấy là nàng tiên cá.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Alicja Bachleda-Curuś","avatar":""},{"name":"Dervla Kirwan","avatar":""},{"name":"Alison Barry","avatar":""},{"name":"Marion O''Dwyer","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
