INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-me-2009', 'Tình Mẹ', 'Motherhood', 'https://phimimg.com/upload/vod/20231208-1/de8e23a732b175c90e1e898138d67f15.jpg', 'https://phimimg.com/upload/vod/20231208-1/2c8c98b4817dd40be4ae404a3c5a7a4f.jpg', '<p>Eliza Welch là một nhà văn viễn tưởng, sống và làm việc tại một căn hộ ở tầng hai trong một tòa nhà chung cư, ở giữa khu nhà cao cấp Greenwich Village. Motherhood diễn ra trong một ngày mà sự sợ hãi của Eliza bị đẩy đến giới hạn của cô. Bắt đầu từ lúc bình minh, danh sách công việc của cô: chuẩn bị bữa tiệc sinh nhật 6 tuổi của con gái, giải quyết những rắc rối của cậu con trai mới biết đi, giành giật một chỗ đậu xe và hàn gắn rạn nứt sau khi đăng lời thú nhận với người bạn tốt nhất của cô trên blog của mình. Nhưng trên tất cả cô quyết định tham gia vào một cuộc thi của một tạp chí về giáo dục con cái. Tất cả công việc cô phải làm là viết 500 từ trả lời câu hỏi: \</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Edwards","avatar":""},{"name":"Uma Thurman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
