INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leningrad', 'Leningrad', 'Leningrad', 'https://phimimg.com/upload/vod/20231208-1/f8405285473b03b2a922fa0cf05993df.jpg', 'https://phimimg.com/upload/vod/20231208-1/95aa7fa5f2690e12d3784bd98e51bc1d.jpg', '<p>Khi phát xít Đức xâm lược Liên Xô vào năm 1941, quân đội của họ đã nhanh chóng bao vây Leningrad. Các nhà báo nước ngoài đã được sơ tán nhưng một trong số họ, Kate Davies, được cho là đã chết và lỡ chuyến bay. Một mình trong thành phố, cô được Nina Tsvetnova, một sĩ quan cảnh sát trẻ tuổi và có lý tưởng giúp đỡ và họ sẽ cùng nhau chiến đấu vì sự sống còn của chính họ và sự sống còn của người dân ở Leningrad bị bao vây.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Byrne","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Alexander Beyer","avatar":""},{"name":"Christian Berkel","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
