INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-tiet-kieu-my', 'Trinh Tiết Kiểu Mỹ', 'American Virgin', 'https://phimimg.com/upload/vod/20231208-1/7014181b51731701913d8dd39d1c5531.jpg', 'https://phimimg.com/upload/vod/20231208-1/2c2a73f830a1aae01a2406cac6478687.jpg', '<p>Một nữ sinh đại học năm nhất nhận học bổng từ một nhóm kiêng khem ủng hộ tiết kiệm tình dục cho đến khi kết hôn phát hiện ra rằng những trò hề của cô ấy trong một đêm ăn chơi trác táng, khi cô ấy miễn cưỡng say xỉn lần đầu tiên trong đời, đã bị một nhà sản xuất video nhếch nhác ghi lại trên máy quay. Giờ đây, cô và những người bạn của mình phải đi khắp đất nước để khôi phục lại những thước phim buộc tội.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jenna Dewan","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Chase Ryan Jeffery","avatar":""},{"name":"Brianne Davis","avatar":""},{"name":"Elan Moss-Bachrach","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
