INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lap-di-2', 'Kẻ Lập Dị 2', 'Crank: High Voltage', 'https://phimimg.com/upload/vod/20231206-1/aa3b84a62aec328b382b7947870e3890.jpg', 'https://phimimg.com/upload/vod/20231206-1/237a090a7c4462a7244cc0bdb08b7f17.jpg', '<p>Crank: High Voltage bắt đầu bằng việc sát thủ chuyên nghiệp Chev Chelios bị một nhóm gangster Trung Quốc bắt cóc. Ba tháng sau Chelios mới tỉnh dậy và phát hiện ra quả tim của mình đã bị thay thế bởi một quả tim nhân tạo. Để tồn tại và nuôi được quả tim này Chelios phải thường xuyên nạp điện cao thế vào người. Mục đích của nhóm xã hội đen này là muốn sử dụng Chelios làm công cụ thực hiện những ý đồ đen tối do chúng thiết lập nên. Tuy nhiên, chúng vấp phải sự kháng cự tột cùng của ý chí con người, của bản năng tồn tại tự do trong cá thể Chelios...</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Clifton Collins Jr.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
