INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madea-goes-to-jail', 'Madea Goes to Jail', 'Madea Goes to Jail', 'https://phimimg.com/upload/vod/20231206-1/b5869cd717d3dab149baa727d57d4042.jpg', 'https://phimimg.com/upload/vod/20231206-1/a9bc99c59ca03fc1358b19f2b51d20bd.jpg', '<p>Sau một cuộc rượt đuổi bằng ô tô tốc độ cao, Madea phải ngồi sau song sắt vì tính khí nóng nảy của cô đã lấn át cô. Trong khi đó, Trợ lý luật sư quận Josh Hardaway giải quyết một vụ án quá riêng tư để xử lý: đó là một cô gái điếm trẻ và từng nghiện ma túy tên là Candace. Khi Candace kết thúc trong tù, Madea đã che chở cho cô gái trẻ.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler Perry","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Keshia Knight Pulliam","avatar":""},{"name":"David Mann","avatar":""},{"name":"Tamela Mann","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
