INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-dinh-menh', 'Chuyến Tàu Định Mệnh', 'The Taking of Pelham 123', 'https://phimimg.com/upload/vod/20231206-1/bbc489e2b96f1423afff767462de25d4.jpg', 'https://phimimg.com/upload/vod/20231206-1/b99b7c59a8dbce6cbb241fabeda199bb.jpg', '<p>Ngày làm việc đầu tiên của Garber ở vị trí mới mở ra bởi một rắc rối nghiêm trọng. Một nhóm vũ trang hạng nặng gồm bốn người, dẫn đầu là Ryder, đánh chiếm đoàn tàu sáu toa chạy tuyến Pelham và bắt giữ tất cả con tin trên tàu. Bọn bắt cóc ra giá 10 triệu USD, kèm theo yêu cầu số tiền chuộc này phải được chuyển đến tay chúng không thiếu một xu trong vòng 60 phút. Mỗi phút trễ nải, một con tin sẽ phải chết. Run rủi thay, Garber là người được Ryder chỉ định thương lượng cùng hắn. Cũng chính anh phải một mình đến giao tiền chuộc, mặc cho sự phản đối từ Trung tâm Điều hành Đường ray và Trung úy Camonetti đến từ Phòng Cảnh sát New York. Một cuộc đấu trí vô cùng căng thẳng đã diễn ra giữa tên cầm đầu Ryder tinh quái, tàn nhẫn và người đàn ông chính trực Walter Garber. Anh đã tận dụng hết những hiểu biết của mình về hệ thống tàu điện ngầm để tìm cách giải thoát con tin...</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Luis Guzmán","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
