INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-cuong-no', 'Cơn Cuồng Nộ', 'Damage', 'https://phimimg.com/upload/vod/20231205-1/fe625de8ab795ca7c54fb253b8655c54.jpg', 'https://phimimg.com/upload/vod/20231205-1/3802fd7f586f09cff9d84b0557d0d9f7.jpg', '<p>Một cựu tội phạm chiến đấu trong lồng để trả tiền cho ca phẫu thuật cứu con gái của nạn nhân. Trên đường đi, anh ấy tìm thấy tình cha con và tình bạn, ở những nơi khó có thể xảy ra nhất.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Austin","avatar":""},{"name":"Laura Vandervoort","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"William B. Davis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324478);
