INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-the-ky', 'Chiến Binh Thế Kỷ', 'Solomon Kane', 'https://phimimg.com/upload/vod/20231205-1/8887653aea294f566f544a36b1325205.jpg', 'https://phimimg.com/upload/vod/20231205-1/290ca3d501510afd7229e6af34a83ab2.jpg', '<p>Một người lính đánh thuê của Nữ hoàng Elizabeth I khi chiến đấu ở châu Phi, ông đã gặp một con quỷ dưới địa ngục và phát hiện ra ông đã bị ràng buộc đối với Thần chết! Để lấy lại cuộc sống đã mất, ông nhận ra rằng ông sẽ phải tìm sự tha thứ, hoặc kết thúc linh hồn của ông trong địa ngục để có thể trở về Anh và sống 1 cuộc sống yên bình như một người Thanh giáo cô độc...</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"James Purefoy","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Rachel Hurd-Wood","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324478);
