INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-chon-hoang-da', 'Lạc Vào Chốn Hoang Dã', 'Where The Wild Things Are', 'https://phimimg.com/upload/vod/20231204-1/5c197ac9d21e7156c6d9c60aa8ffd3cd.jpg', 'https://phimimg.com/upload/vod/20231204-1/40d2c34dc5a3cd950f81d351368b6c25.jpg', '<p>Bị mẹ phạt ở trong phòng vì tội quá nghịch ngợm, Max đã tưởng tượng mình trốn vào một khu rừng có nhiều quái thú sinh sống và được tôn lên làm vua. Sau khi kết thân với một quái thú tên là Carol, Max đã học được thế nào là ý nghĩa của tình yêu trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Records","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Forest Whitaker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324478);
