INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-uninvited', 'The Uninvited', 'The Uninvited', 'https://phimimg.com/upload/vod/20231203-1/fd8ee035cf8f50dd0a139136ccc456e2.jpg', 'https://phimimg.com/upload/vod/20231203-1/03e3f8372aa91fb802c501bbb0a3cd05.jpg', '<p>Anna trở về nhà sau thời gian ở trong một cơ sở tâm thần sau cái chết bi thảm của mẹ cô và phát hiện ra rằng y tá cũ của mẹ cô, Rachel, đã chuyển đến nhà của họ và đính hôn với cha cô. Ngay sau khi biết được tin sốc này, hồn ma của mẹ cô đã đến thăm Anna và cảnh báo cô rằng Rachel có ý định xấu xa.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Browning","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Maya Massar","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324478);
