INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-toi-suy-sup', 'Đời Tôi Suy Sụp', 'My Life in Ruins', 'https://phimimg.com/upload/vod/20231203-1/258a9de7ac7b8aa60e4a33888bc04fdc.jpg', 'https://phimimg.com/upload/vod/20231203-1/2bf3691596ec25753160d7d9d6b88aa3.jpg', '<p>Georgia là một hướng dẫn viên người Mỹ tại Hy Lạp, cô chịu trách nhiệm hướng dẫn cho một nhóm đủ loại du khách đi vòng quanh Hy Lạp. Nhóm du khách này khá là ngớ ngẩn khi họ tỏ ra thích mua áo thun hơn là tìm hiểu thêm về lịch sử và văn hóa của Hy Lạp. Trong một cuộc bất đồng giữa chủ nghĩa cá nhân và văn hóa, mọi việc dường như diễn ra chệch hướng. Cho đến một ngày, một du khách lớn tuổi tên Irv Gordon chỉ cho cô thấy cách để luôn vui vẻ và để quan tâm đến một người mà cô không bao giờ nghĩ rằng mình sẽ tìm thấy tình yêu với anh ta: anh chàng tài xế xe buýt người Hy Lạp của cô.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nia Vardalos","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Rachel Dratch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
