INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-dau-doi', 'Bài Học Đầu Đời', 'An Education', 'https://phimimg.com/upload/vod/20231203-1/60d41f24c64fa1c9060aac5c228e84ce.jpg', 'https://phimimg.com/upload/vod/20231203-1/91aad9d026896bdbbbb437892983b801.jpg', '<p>Lấy bối cảnh đầu những năm 1960 tại vùng ngoại ô thành phố Luân Đôn, bộ phim xoay quanh cô nàng Jenny Mellor 16 tuổi đang sống cùng với cha và mẹ. Tất cả những gì mà Jenny làm đều nhằm để ghi danh thành công vào trường đại học Oxford, như mong mỏi của cha cô về một cuộc sống tốt đẹp hơn cho con gái mình. Jenny tươi tắn, xinh đẹp, chăm chỉ, sở hữu trí thông minh và sự lanh lợi trời phú. Vấn đề duy nhất khiến cha cô phiền não đó là khả năng học tiếng Latin và cậu bạn trai Graham tốt tính nhưng lập dị mà cô đang hẹn hò. Cuộc sống của Jenny thay đổi kể từ ngày cô gặp David Goldman, một người đàn ông trang nhã, thanh lịch, già gấp đôi tuổi cô...</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Olivia Williams","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
