INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kiem-vo-danh', 'Thanh Kiếm Vô Danh', 'The Sword With No Name', 'https://phimimg.com/upload/vod/20231215-1/c42255512e43fe2928a0f8bcc123ee38.jpg', 'https://phimimg.com/upload/vod/20231215-1/f36125eda2ac87d1bfe689507dadd1a1.jpg', '<p>Thanh Kiếm Vô Danh - The Sword with No Name là một bộ phim Hàn Quốc 2009 dựa trên câu chuyện giả tưởng của Hoàng Hậu Myeongseong. Mu-myeong là một thợ săn tiền thưởng bằng cách bắt tội phạm ở triều đại Joseon. Cuộc sống của Mu-myeong sẽ chẳng có gì thay đổi cho đến một ngày anh ta gặp một phụ nữ quý tộc xinh đẹp Min Ja-young. Nhưng không may thay, Ja-young vào hoàng cung là để được kết hôn với Hoàng Đế Gojong. Thầm thương trộm nhớ nàng, Mu-myeong tham gia bảo vệ hoàng cung để được gần Ja-young, luôn trung thành khi nàng lên ngôi trở thành Hoàng Hậu Myeongseong. Không may thay, mọi đau khổ đều bắt đầu từ đây...</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seung-woo Cho","avatar":""},{"name":"Soo Ae","avatar":""},{"name":"Sophie Broustal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
