INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doghouse', 'Doghouse', 'Doghouse', 'https://phimimg.com/upload/vod/20231204-1/739b11cfd9f321132800b85bd8d1fd0e.jpg', 'https://phimimg.com/upload/vod/20231204-1/ffe3427729ddd9c6d5cec4c128f38568.jpg', '<p>Vince đang xử lý việc ly hôn của mình một cách tồi tệ. Anh chán nản. Đi đến từng mảnh. Nhưng những người bạn của anh ta không từ bỏ anh ta. Đấu tranh với những rắc rối của phụ nữ của riêng họ, họ kéo anh ta ra cho một ngày cuối tuần uống rượu trong cả nước. Đến làng Moodley nơi những người phụ nữ đông hơn những người đàn ông 3: 1, các chàng trai thấy mình kỳ nghỉ trong một ngôi làng tràn ngập bởi zombirds tâm thần, giết người với một cơn khát đối với thịt đực.</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
