INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noc-doc-tu-than', 'Nọc Độc Tử Thần', 'Silent Venom', 'null', 'https://phimimg.com/upload/vod/20231202-1/9fbfe14af6fd0a394d4fc4037d7522b8.jpg', '<p>Nọc Độc Tử Thần - Silent Venom kể về câu chuyện một chiếc tàu ngầm chuyển hướng đến một hòn đảo Nam Thái Bình Dương để đón các nhà khoa học làm việc trong một dự án tuyệt mật. Nhưng phi hành đoàn đã kinh hoàng phát hiện ra rằng các nhà khoa học đã mang những con rắn có nọc độc chết người lên tàu. Nguy hiểm hơn nữa, họđã đi lạc vào vùng biển của Triều Tiên trong một cuộc tập trận hải quân, hiện đang bị tấn công từ trên cao và không thể nổi trên mặt nước. Bây giờ họ phải sống sót đủ lâu để có thể nổi trên mặt nước và thoát khỏi con tàu.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Perry","avatar":""},{"name":"Krista Allen","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Anthony Tyler Quinn","avatar":""},{"name":"Robert Catrini","avatar":""},{"name":"David Andriole","avatar":""},{"name":"Sam Scarber","avatar":""},{"name":"Travis Joe Dixon","avatar":""},{"name":"Haran Jackson","avatar":""},{"name":"Oliver Rayon","avatar":""},{"name":"Bill J. Stevens","avatar":""},{"name":"Gerald Webb","avatar":""},{"name":"T. Ryan Mooney","avatar":""},{"name":"Sterling Hiroshi Greene","avatar":""},{"name":"Kimo Keoke","avatar":""},{"name":"Ted","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324478);
