INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-vao-nha-thuong-dien', 'Cuộc Đua Vào Nhà Thương Điên', 'Asylum Seekers', 'https://phimimg.com/upload/vod/20231202-1/5f01337546f4eee693a95f0c7d619aeb.jpg', 'https://phimimg.com/upload/vod/20231202-1/8ae7bf00dfd6f78a615f8ec757a85b4a.jpg', '<p>Cuộc Đua Vào Nhà Thương Điên - Asylum Seekers: Sáu người với những sang chấn về vấn đề tâm lý riêng tìm đến một bệnh viện tâm thần để điều trị. Nhưng họ không được báo trước rằng bệnh viện chỉ còn chỗ cho một người điên nhất nhất, và cuộc chạy đua bắt đầu, với những hình thức thi đấu không tưởng. Họ dần dần hé lộ thêm về con người mình, rồi họ trở nên thân thiết, nhưng đó liệu đã phải là kết thúc?</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pepper Binkley","avatar":""},{"name":"Stella Maeve","avatar":""},{"name":"Bill Dawes","avatar":""},{"name":"Judith Hawking","avatar":""},{"name":"Daniel Irizarry","avatar":""},{"name":"Camille O''Sullivan","avatar":""},{"name":"Lee Wilkof","avatar":""},{"name":"Liza Binkley","avatar":""},{"name":"Shana Dowdeswell","avatar":""},{"name":"Karin Duseva","avatar":""},{"name":"Mercedes Herrero","avatar":""},{"name":"Remy Auberjonois","avatar":""},{"name":"John Auer","avatar":""},{"name":"Edward James Hyland","avatar":""},{"name":"Ken Jennings","avatar":""},{"name":"Suneet Kochar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
