INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tren-gac-xep', 'Quái Vật Trên Gác Xếp', 'Aliens in the Attic', 'https://phimimg.com/upload/vod/20231201-1/ac4444ed78fec39ff28e6cd816467ed6.jpg', 'https://phimimg.com/upload/vod/20231201-1/f5f252fb3d9b880e807779ccbcd89a45.jpg', '<p>Cuộc Chiến Vui Nhộn Giữa Những Đứa Trẻ Và Người Ngoài Hành Tinh - Aliens In The Attic kể về những nỗ lực của gia đình Pearson nhằm ngăn chặn âm mưu xâm chiếm Trái Đất của một nhóm người ngoài hành tinh sống tại Maine. Câu chuyện bắt đầu khi một ngôi sao băng bất ngờ đâm vào Trái Đất mang theo đó là sự xuất hiện của bốn người ngoài hành tinh kỳ lạ. Liệu gia đình Pearson sẽ làm gì để chống chọi lại với những người ngoài hành tinh đáng sợ này đây? Hãy theo dõi bộ phim để cùng chúng tôi tìm ra lời giải đáp nhé.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"J.K. Simmons","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Robert Hoffman","avatar":""},{"name":"Doris Roberts","avatar":""},{"name":"Tim Meadows","avatar":""},{"name":"Ashley Boettcher","avatar":""},{"name":"Megan Parker","avatar":""},{"name":"Henri Young","avatar":""},{"name":"Regan Young","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Melise","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Maggie VandenBerghe","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Dou","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":