INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-binh-mai-2-no-le-tinh-yeu', 'Kim Bình Mai 2: Nô Lệ Tình Yêu', 'The Forbidden Legend: Sex & Chopsticks 2', 'https://phimimg.com/upload/vod/20231201-1/e9a40c630aa29fd20d42b75c19b0b076.jpg', 'https://phimimg.com/upload/vod/20231201-1/b8ba9af83b8aa299a978666eebc6232b.jpg', '<p>Kim Bình Mai 2 chính là tiếp nối câu chuyện còn đang dang dở ở phần đầu tiên, nếu như ở phần 1 chúng ta được chứng kiến Tây Môn Khánh cướp Phan Kim Liên bằng cách giết hại chồng của ả là Võ Đại Lang thì ở phần kế tiếp, sẽ là câu chuyện trả thù của người em trai của Võ Lang là Võ Tòng, ngoài ra còn những câu chuyện đan xen quanh bản năng “thích tìm cái mới” đến kinh tởm của Khánh, y bắt cá 2 tay mà thậm chí còn có sở thích quan hệ với 2 người cùng một lúc. Y không từ thủ đoạn để dan díu với vợ của bạn, sau đó là tiếp tục hại chết người bạn của mình nhằm độc chiếm người mình thích.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Oscar Lam Wai-Kin","avatar":""},{"name":"Serina Hayakawa","avatar":""},{"name":"Kaera Uehara","avatar":""},{"name":"Winnie Leung","avatar":""},{"name":"Hikaru Wakana","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Tam Kon-Chung","avatar":""},{"name":"Samuel Leung Cheuk-Moon","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
