INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-trang', 'Cái Chết Trắng', 'Whiteout', 'https://phimimg.com/upload/vod/20231130-1/98f5cf541db4b66b89f85be31efba480.jpg', 'https://phimimg.com/upload/vod/20231130-1/64217003b62239d9e71d283010ea1505.jpg', '<p>Whiteout kể về hành trình điều tra một vụ án mạng bí ẩn của nữ đại úy Carrie Stetko tại vùng đất Nam cực băng giá. Từ bỏ kỳ nghỉ của mình và tới mảnh đất quanh năm tuyết phủ này chỉ ba ngày trước khi mùa đông ở nơi này bắt đầu, Carrie đã phải đối mặt với những nguy hiểm mà cô không ngờ tới. Sau khi dần dần mở khóa những manh mối, cô đại úy xinh đẹp đã khám phá ra những bí mật được chôn vùi dưới lớp băng vĩnh cửu, những bí mật mà cô có thể phải trả bằng chính máu của mình. Để tồn tại, Carrie chỉ có hai lựa chọn, giết hoặc bị giết. Cô cần phải tìm cho ra kẻ sát nhân giấu mặt trước khi bị vùi lấp bởi thiên nhiên tàn khốc. Ở vùng đất Nam cực trắng xóa, người truy tìm và kẻ bị truy tìm sẽ chỉ nhìn thấy nhau khi cách nhau trong gang tấc...</p>', 'Full', 1, 'single', 'completed', 7, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Gabriel Macht","avatar":""},{"name":"Tom Skerritt","avatar":""},{"name":"Columbus Short","avatar":""},{"name":"Shawn Doyle","avatar":""},{"name":"Alex O''Loughlin","avatar":""},{"name":"Joel S. Keller","avatar":""},{"name":"Jesse Todd","avatar":""},{"name":"Arthur Holden","avatar":""},{"name":"Erin Hickock","avatar":""},{"name":"Bashar Rahal","avatar":""},{"name":"Julian Cain","avatar":""},{"name":"Dennis Keiffer","avatar":""},{"name":"Andrei Runtso","avatar":""},{"name":"Roman Varshavsky","avatar":""},{"name":"Steve Lucescu","avatar":""},{"name":"Paula Jean","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172