INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ghet-ngay-le-tinh-nhan', 'Tôi Ghét Ngày Lễ Tình Nhân', 'I Hate Valentine''s Day', 'https://phimimg.com/upload/vod/20231130-1/dbce224387125b1bc3a39bc68ba3cf1a.jpg', 'https://phimimg.com/upload/vod/20231130-1/86ac16565dfc96800091f60e93a8ac6a.jpg', '<p style="text-align: left;">Một câu chuyện tình yêu lấy bối cảnh ở Manhattan, nơi một người bán hoa tuân thủ nghiêm ngặt giới hạn năm buổi hẹn hò với bất kỳ người đàn ông nào nhận thấy mình muốn nhiều hơn với chủ nhà hàng mới trong thị trấn.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nia Vardalos","avatar":""},{"name":"John Corbett","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Stephen Guarino","avatar":""},{"name":"Amir Arison","avatar":""},{"name":"Gary Wilmes","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Rachel Dratch","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"Ben Schwartz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
