INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nang-luc', 'Siêu Năng Lực', 'Push', 'https://phimimg.com/upload/vod/20231130-1/8e24d7f8492f11b50277adec7a9397f2.jpg', 'https://phimimg.com/upload/vod/20231130-1/0349c14c11f7ede382e925df22ce4869.jpg', '<p>Sau cái chết của cha, một sát thủ xuất sắc của đơn vị Division thuộc chính phủ Mỹ, Nick Gant đã chạy trốn đến Hong Kong và sống âm thầm tại đây nhằm thoát khỏi sự truy lùng của Division. Nhằm muốn tạo nên một đội quân gồm những con người có khả năng đặc biệt, Division không ngại làm trái với luật ứng dụng hoá học lên cơ thể người, gây ra nhiều cái chết mờ ám. &nbsp;Nick, Cassie Holmes và những người có siêu năng lực khác đã cùng hợp lực để chống lại Division, truy tìm cô gái bí ẩn Kira Hudson và một vali chứa đựng những manh mối có thể vạch trần tội ác của Division. Sức mạnh hợp nhất của họ đã lần lượt đánh bại những sát thủ Division phái đến, để phát hiện ra vũ khí tối thượng cuối cùng của đơn vị này – một loại thuốc mới có sức mạnh khủng khiếp tên là R16, có thể gây ra xung động giữa những người mang năng lực siêu phàm.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Camilla Belle","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Joel Gretsch","avatar":""},{"name":"Nate Mooney","avatar":""},{"name":"Li Xiaolu","avatar":""},{"name":"Maggie Siff","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Scott Michael Campbell","avatar":""},{"name":"Colin Ford","avatar":""},{"name":"Robert Tsonos","avatar":""},{"name":"Brandon Rhea","avatar":""},{"name":"Neil Jackson","avatar":""},{"name":"Leung Kai Cheung","avatar":""},{"name":"Hsin Na","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
