INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-su-john', 'Tiểu Sử John', 'John Rabe', 'https://phimimg.com/upload/vod/20231211-1/9cd17c64b36aaf7e2b5fc01202f73508.jpg', 'https://phimimg.com/upload/vod/20231211-1/b50bddc703ddfa5877f2c5243a177eb8.jpg', '<p>Nam Kinh, Trung Quốc, 1937. Quân Nhật tấn công đúng vào buổi tối mà vị thương gia người Đức John Rabe tổ chức bữa tiệc chia tay sau 30 năm ở Trung Quốc. Do vậy, Rabe đã cho vợ về châu Âu, còn mình thì ở lại thành phố bị chiếm đóng. Cùng với một nhóm người nước ngoài, Rabe đã lập ra một khu bảo vệ cho hàng trăm nghìn người, trong khi bên ngoài, quân Nhật đang tàn sát thường dân vô cùng tàn bạo. Tuy nhiên tình hình nhanh chóng trở nên tồi tệ và Rabe phải chiến đấu để bảo vệ sinh mạng của 200.000 người. Trái tim nhân hậu và nghĩa cử của John Rabe được nhân dân Trung Quốc ghi nhớ và biết ơn, nhưng chính ông lại bị đất nước mình bỏ rơi và ngay cả quân đội Đồng minh cũng nghi ngờ. Bởi vì ông đích thực là một Đảng viên Quốc xã, và ông đã dùng chính cái danh đó để thực hiện lòng trắc ẩn của mình...</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ulrich Tukur","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Steve Buscemi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324478);
