INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-hop-bi-an', 'Chiếc Hộp Bí Ẩn', 'The Box', 'https://phimimg.com/upload/vod/20231129-1/5bdbe542208d72f81f610c7551dfbba3.jpg', 'https://phimimg.com/upload/vod/20231129-1/15ac051d3948a697f58a63af4ce55652.jpg', '<p>Norma và Arthur Lewis, một cặp vợ chồng cùng đứa con nhỏ sống vùng ngoại ô, nhận được một chiếc hộp gỗ nhỏ như một món quà mang lại sự may mắn lẫn những hậu quả khó lường. Một người lạ bí ẩn, đến nói với họ rằng cứ mỗi lần ấn cái nút trên hộp sẽ mang lại cho họ số tiền một triệu đôla.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Holmes Osborne","avatar":""},{"name":"Sam Oz Stone","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Lisa K. Wyatt","avatar":""},{"name":"Mark S. Cartier","avatar":""},{"name":"Kevin Robertson","avatar":""},{"name":"Michele Durrett","avatar":""},{"name":"Ian Kahn","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Ryan Woodle","avatar":""},{"name":"Basil Hoffman","avatar":""},{"name":"Robert Harvey","avatar":""},{"name":"Gen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324478);
