INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-2009', 'Thứ 6 Ngày 13', 'Friday the 13th', 'https://phimimg.com/upload/vod/20230912-1/52223136cb4a8c155dab8e9ad0271e93.jpg', 'https://phimimg.com/upload/vod/20230912-1/bcbce329befe241634d3560e2e062a57.jpg', '<p><span style="font-family: ">Kể về một nhóm thanh niên trẻ bị mất tích khi đang cắm trại trong khu rừng gần hồ Camp Crystal sau khi tò mò tìm kiếm nơi ở của tên sát nhân giết người hàng loạt theo đồn đại. 6 tuần sau, vào đúng thứ 6 ngày 13, Trent mời bạn bè đến ngôi nhà của mình ở cạnh hồ Crystal để vui chơi cuối tuần. Mọi chuyện kỳ lạ bắt đầu xảy ra khi 1 thành viên trong nhóm là Whitney đã bị mất tích kèm theo sự xuất hiện của Clay – anh trai Whitney. Tất cả không ngờ rằng Jason Vorhees – một tên sát nhân khát máu mang mặt nạ sẽ biến thứ 6 ngày 13 của nhóm bạn trẻ trở thành một ngày tàn sát kinh hoàng.</span></p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jared Padalecki","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Amanda Righetti","avatar":""},{"name":"Travis Van Winkle","avatar":""},{"name":"Aaron Yoo","avatar":""},{"name":"Arlen Escarpeta","avatar":""},{"name":"Julianna Guill","avatar":""},{"name":"Jonathan Sadowski","avatar":""},{"name":"Ben Feldman","avatar":""},{"name":"Ryan Hansen","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324478);
