INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-hung-ba-thien-ha-2009', 'Phong Vân: Hùng Bá Thiên Hạ', 'The Storm Warriors', 'https://phimimg.com/upload/vod/20231010-1/6bc6c57aadb2e09f35db8682fad1e12f.jpg', 'https://phimimg.com/upload/vod/20231010-1/9c214a3e9154c0a300ad3070e848a35d.jpg', '<p>Nối tiếp phần đầu tiên của bộ phim, “Phong Vân 2 – The Storm Warriors” ra đời, trở thành một thành công nữa của bộ đôi đạo diễn Danny Pang và Oxide Pang. Phim xoay quanh cuộc chiến của bộ đôi chính nghĩa Bộ Kinh Vân và Nhiếp Phong với thế lực tà ác hung bạo, đứng đầu là tên giáo chủ sừng sỏ Tuyệt Vô Thần.&nbsp; “Phong Vân 2 – The Storm Warriors” lấy bối cảnh giới võ lâm Trung Hoa sau những biến cố ở phần phim thứ nhất. Lúc này, một thế lực không rõ lai lịch xuất hiện, tự nhận mình là bang phái Vô Thần Cung, gây sự với nhiều bang phái nổi danh khác. Đứng đầu Vô Thần Cung này là tên giáo chủ Tuyệt Vô Thần – một tên có lai lịch bí ẩn chẳng kém mấy bang phái của hắn. Ngay từ khi xuất hiện, Tuyệt Vô Thần cùng Vô Thần Cung đã thể hiện dã tâm xân chiếm Trung Hoa, xưng bá võ lâm thiên hạ. Đã nhiều bang phái, nhiều con người kì tài ra tay cố gắng trừ khử hắn nhưng đều thất bại ê chề. Tuyết Vô Thần không phải là một tên dễ đối phó.</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Kenny Ho","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Byron Pang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324478);
