INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-noi-mat-tham-2009', 'Đại Nội Mật Thám', 'On His Majesty''s Secret Service', 'https://phimimg.com/upload/vod/20231111-1/417faa5ede5857961933f483cd00a457.jpg', 'https://phimimg.com/upload/vod/20231111-1/b4687142c2dfb39cab2ef072ccc22b97.jpg', '<p>Cổ Thiên Lạc đóng vai 009, hoặc được dịch theo nghĩa đen từ cách phát âm theo âm thanh của nó, double-O Dog. Anh ấy là một trong 12 Vệ sĩ Hoàng gia đặc biệt của một Hoàng đế đơn giản (Liu Yiwei), người đã đặt tên cho 12 cận vệ này theo Cung hoàng đạo Trung Quốc, do đó 9 được dịch thành Chó. Không giống như các đồng nghiệp của mình, Dog là một nhà khoa học và dựa khá nhiều vào bộ não và các thiết bị thần kỳ của mình để bảo vệ Bệ hạ khỏi những sát thủ ninja độc ác.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Barbie Hsu","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Yang Jiang","avatar":""},{"name":"Liu Yiwei","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Shi Zhenlong","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Kingdom Yuen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324478);
