INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-noi-mat-tham-2009', 'Đại Nội Mật Thám', 'On His Majesty''s Secret Service', 'đại nội mật thám on his majesty''s secret service louis koo barbie hsu louis fan siu-wong sandra ng kwan-yue yang jiang liu yiwei song jia tong dawei lam tze-chung shi zhenlong law kar-ying leung kar-yan kingdom yuen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-ii', 'Phong Vân II', 'The Storm Warriors II', 'https://phimimg.com/upload/vod/20231129-1/3876f098a5fc9b4943e0fae104649ef5.jpg', 'https://phimimg.com/upload/vod/20231129-1/58249281b06a80e501474a7b5604bdea.jpg', '<p>Nối tiếp phần đầu tiên của bộ phim, “Phong Vân 2 – The Storm Warriors” ra đời, trở thành một thành công nữa của bộ đôi đạo diễn Danny Pang và Oxide Pang. Phim xoay quanh cuộc chiến của bộ đôi chính nghĩa Bộ Kinh Vân và Nhiếp Phong với thế lực tà ác hung bạo, đứng đầu là tên giáo chủ sừng sỏ Tuyệt Vô Thần. &nbsp;“Phong Vân 2 – The Storm Warriors” lấy bối cảnh giới võ lâm Trung Hoa sau những biến cố ở phần phim thứ nhất. Lúc này, một thế lực không rõ lai lịch xuất hiện, tự nhận mình là bang phái Vô Thần Cung, gây sự với nhiều bang phái nổi danh khác. Đứng đầu Vô Thần Cung này là tên giáo chủ Tuyệt Vô Thần – một tên có lai lịch bí ẩn chẳng kém mấy bang phái của hắn. Ngay từ khi xuất hiện, Tuyệt Vô Thần cùng Vô Thần Cung đã thể hiện dã tâm xân chiếm Trung Hoa, xưng bá võ lâm thiên hạ. Đã nhiều bang phái, nhiều con người kì tài ra tay cố gắng trừ khử hắn nhưng đều thất bại ê chề. Tuyết Vô Thần không phải là một tên dễ đối phó.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Kenny Ho","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Byron Pang","avatar":""},{"name":"Tang Yan","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324478);
