INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-anh-em-2009', 'Tình Anh Em', 'Brothers', 'https://phimimg.com/upload/vod/20231020-1/c3860891ce4d7c884b947ab30a0e601b.jpg', 'https://phimimg.com/upload/vod/20231020-1/d13354d04d199250c3fb2a2d9d22d755.jpg', '<p>Khi chiếc trực thăng của anh ta gặp sự cố trong chuyến làm nhiệm vụ lần thứ tư ở Afghanistan, Marine Sam Cahill được cho là đã chết. Trở về nhà, anh trai Tommy bước vào để trông nom vợ của Sam, Grace và hai đứa con. Sự trở lại nhà bất ngờ của Sam gây ra tình trạng hỗn loạn trong nước.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"Mare Winningham","avatar":""},{"name":"Taylor Geare","avatar":""},{"name":"Patrick John Flueger","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"Omid Abtahi","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Arron Shiver","avatar":""},{"name":"Ray Prewitt","avatar":""},{"name":"Jenny Wade","avatar":""},{"name":"Jason","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324478);
