INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-the-mang-2009', 'Kẻ Thế Mạng', 'Surrogates', 'https://phimimg.com/upload/vod/20231128-1/4cda1b80d4d41c53eb9397af3f42d133.jpg', 'https://phimimg.com/upload/vod/20231128-1/f9d9fe7b8f8a939bca087cd9fa720e11.jpg', '<p>Trong một tương lai không xa nữa, con người sống rất cô lập và chỉ liên lạc với nhau thông qua những con rô bốt. Một tổ chức tội phạm đã đứng lên chống phá và giết người. Trong khi những con rô bốt bị phá hủy thì một viên cảnh sát đã đứng ra ngăn chặn và trừng trị những tên sát thủ nàySau một cuộc đo sức nảy lửa rô bốt của chàng cảnh sát đã bị hỏng nặng, tuy nhiên nó cũng giúp anh thoát khỏi sự cô lập và làm sáng tỏ một âm mưu đen tối.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Helena Mattsson","avatar":""},{"name":"Boris Kodjoe","avatar":""},{"name":"Ian Novick","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Jack Noseworthy","avatar":""},{"name":"Danny F. Smith","avatar":""},{"name":"Jeffrey De Serrano","avatar":""},{"name":"Michael Cudlitz","avatar":""},{"name":"Trevor Donovan","avatar":""},{"name":"Jennifer Alden","avatar":""},{"name":"Michael Philip","avatar":""},{"name":"James","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
