INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dua-thu-den-thien-duong', 'Người Đưa Thư Đến Thiên Đường', 'Heaven''s Postman', 'https://phimimg.com/upload/vod/20231129-1/542d0ad21cb72a49b9e81a05eb0e0be7.jpg', 'https://phimimg.com/upload/vod/20231129-1/992df71d14dd0df5ac36f9e3a2eab265.jpg', '<p>Jae Jun chuyển những lá thư lên thiên đàng từ những người không thể vượt qua nỗi mất mát người thân. Một ngày nọ, Ha-na, người viết thư cho người bạn trai quá cố của mình, phát hiện ra danh tính bí mật của Jae-jun. Anh ấy mời cô ấy một công việc bán thời gian để hỗ trợ anh ấy, và họ bắt đầu cuộc hành trình kéo dài 14 ngày.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Jae-joong","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Shin Goo","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Yook Mi-ra","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Lee Du-il","avatar":""},{"name":"Jang Jung-hee","avatar":""},{"name":"Jung Jae-jin","avatar":""},{"name":"Baek So-Mi","avatar":""},{"name":"Kim Yoo-yeon","avatar":""},{"name":"Kim Jae-rok","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Yoon Seok-Hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
