INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-dang-nguyen-rua', 'Đội Bóng Đáng Nguyền Rủa', 'The Damned United', 'https://phimimg.com/upload/vod/20231129-1/4d7a4cc5d0a7632d7932236ff791f6fe.jpg', 'https://phimimg.com/upload/vod/20231129-1/e4dd4ec563dc1c615a4b1eb3c19e51a2.jpg', '<p>Bộ phim xoay quanh câu lạc bộ bóng đá đỉnh cao của Anh – Leeds United. Brian Clough không thích lối đá bẩn của những cầu thủ, và họ đã xích mích. Bộ phim còn là cái nhìn thoáng qua về sự nghiệp của ông, giúp giải thích thái độ thù địch của ông với người quản lý cũ Don Revie và lí do tại sao ông lại để tuột mất Peter Taylor vào tay Brighton &amp; Hove Albion...</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Michael Sheen","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Maurice Roëves","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Henry Goodman","avatar":""},{"name":"Mark Bazeley","avatar":""},{"name":"Giles Alderson","avatar":""},{"name":"Martin Compston","avatar":""},{"name":"David Roper","avatar":""},{"name":"Jimmy Reddington","avatar":""},{"name":"Peter McDonald","avatar":""},{"name":"Oliver Stokes","avatar":""},{"name":"Ryan Day","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Elizabeth Carling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324478);
