INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-cau-hon', 'Lời Cầu Hôn', 'The Proposal', 'https://phimimg.com/upload/vod/20231129-1/0889de596602a9533529dcbbdf6f90bf.jpg', 'https://phimimg.com/upload/vod/20231129-1/b7adc9772c92b550c4f089860cff393d.jpg', '<p>Đối mặt với nguy cơ bị trục xuất về Canada, Margaret – một nữ tổng biên tập sách đầy quyền lực đã nhanh trí cứu nguy cho mình bằng cách tuyên bố rằng cô sẽ đính hôn với trợ lý của mình là Andrew, người đã bị cô hành hạ tới bến sau nhiều năm làm việc.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Craig T. Nelson","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Betty White","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Oscar Nunez","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Michael Nouri","avatar":""},{"name":"Gregg Edelman","avatar":""},{"name":"Michael Mosley","avatar":""},{"name":"Dale Place","avatar":""},{"name":"Alicia Hunt","avatar":""},{"name":"Alexis Garcia","avatar":""},{"name":"Kortney Adams","avatar":""},{"name":"Chris Whitney","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
