INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-san-ca-heo', 'Nạn Săn Cá Heo', 'The Cove', 'https://phimimg.com/upload/vod/20231129-1/10f1c5fc90c362eef1d3b6b82a377a08.jpg', 'https://phimimg.com/upload/vod/20231129-1/a3445df25b0b534f7ed94449d4b6ebd8.jpg', '<p>The Cove kể câu chuyện có thật đáng kinh ngạc về cách một nhóm ưu tú gồm các cá nhân, nhà sản xuất phim và thợ lặn tự do bắt tay vào một nhiệm vụ bí mật là thâm nhập vào vịnh nhỏ ẩn giấu ở Nhật Bản, soi sáng một bí mật đen tối và chết chóc. Những khám phá gây sốc chỉ là phần nổi của tảng băng chìm.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Chisholm","avatar":""},{"name":"Mandy-Rae Cruikshank","avatar":""},{"name":"Charles Hambleton","avatar":""},{"name":"Simon Hutchins","avatar":""},{"name":"Kirk Krack","avatar":""},{"name":"Isabel Lucas","avatar":""},{"name":"Richard O''Barry","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Roger Payne","avatar":""},{"name":"John Potter","avatar":""},{"name":"Louie Psihoyos","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324478);
