INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-la-rac-roi', 'Đời Là Rắc Rối', 'It''s Complicated', 'https://phimimg.com/upload/vod/20231125-1/a7b027d5a031c4222cb76563af40c7f0.jpg', 'https://phimimg.com/upload/vod/20231125-1/6cdcbe334b0f990a8ecf54bf4cead098.jpg', '<p>Jane - mẹ của 3 đứa con đã trưởng thành và sở hữu nhà hàng làm ăn rất phát đạt là Santa Barbara. Sau cả thập kỷ li dị với Jake, là một luật sư thành đạt đã tái hôn với Agness - 1 cô gái trẻ hơn anh rất nhiều, họ tình cờ gặp lại nhau trong buổi tốt nghiệp của con họ. Rượu tràn đầy, những lời trò chuyện, và hai người đã lao vào một cuộc yêu đương ngoài dự tính trong trạng thái say xỉn. Mọi việc trở nên phức tạp khi một bữa ăn thuần túy lại trở thành 1 câu chuyện tình. Bỗng nhiên, Jane trở thành “người thứ ba”...</p>', 'Full', 1, 'single', 'completed', 8, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Steve Martin","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Mary Kay Place","avatar":""},{"name":"Rita Wilson","avatar":""},{"name":"Ali Wentworth","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Caitlin FitzGerald","avatar":""},{"name":"Emjay Anthony","avatar":""},{"name":"Nora Dunn","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Robert Curtis Brown","avatar":""},{"name":"James Patrick Stuart","avatar":""},{"name":"Peter MacKen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
