INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-dao-chich', 'Siêu Đạo Chích', 'Goemon', 'https://phimimg.com/upload/vod/20231125-1/4ed8e14039ef659c8db5941d2848af61.jpg', 'https://phimimg.com/upload/vod/20231125-1/8f41bf06268c3311c065af3bf31ef0c8.jpg', '<p>Goemon Ishikawa là một Shinobi đích thực, một võ sỹ đứng lên từ tang thương, được rèn luyện trong khắc khổ bởi một vị danh sư có một không hai. Trong một lần cướp của người giàu chia cho người nghèo, anh đã lấy phải chiếc hộp chứa đựng điều bí mật tày trời. Từ đấy binh đao sẽ dấy lên. Máu sẽ nhuộm đỏ những con đường, nhuộm đỏ chiến trường. Liệu Goemon sẽ làm gì trước viễn cảnh đen tối của cuộc chiến tranh giành quyền lực kinh hoàng ấy...?</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yosuke Eguchi","avatar":""},{"name":"Ryoko Hirosue","avatar":""},{"name":"Takao Osawa","avatar":""},{"name":"Jun Kaname","avatar":""},{"name":"Mikijiro Hira","avatar":""},{"name":"Masatō Ibu","avatar":""},{"name":"Tetsuji Tamayama","avatar":""},{"name":"Ryo","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Eriko Sato","avatar":""},{"name":"Mayumi Sada","avatar":""},{"name":"Takeru Satoh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324478);
