INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhoc-nicolas', 'Nhóc Nicolas', 'Le Petit Nicolas', 'https://phimimg.com/upload/vod/20231125-1/5e69f0ea51001f0bb4e536c555b6bba6.jpg', 'https://phimimg.com/upload/vod/20231125-1/8bf9a6dcd2d6aea2febefa216e920df7.jpg', '<p>Nicolas có một sự tồn tại hạnh phúc, cha mẹ yêu thương anh ấy, một nhóm bạn tuyệt vời mà anh ấy rất vui vẻ, và tất cả những gì anh ấy muốn là không có gì thay đổi. Tuy nhiên, một ngày nọ, anh tình cờ nghe được một cuộc trò chuyện khiến anh tin rằng cuộc đời mình có thể thay đổi mãi mãi, mẹ anh đang mang thai! Anh ấy hoảng sợ và hình dung ra điều tồi tệ nhất.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Maxime Godart","avatar":""},{"name":"Valérie Lemercier","avatar":""},{"name":"Kad Merad","avatar":""},{"name":"Sandrine Kiberlain","avatar":""},{"name":"François-Xavier Demaison","avatar":""},{"name":"Michel Duchaussoy","avatar":""},{"name":"Daniel Prévost","avatar":""},{"name":"Michel Galabru","avatar":""},{"name":"Anémone","avatar":""},{"name":"Louise Bourgoin","avatar":""},{"name":"Gérard Jugnot","avatar":""},{"name":"Vincent Claude","avatar":""},{"name":"Charles Vaillant","avatar":""},{"name":"Victor Carles","avatar":""},{"name":"Benjamin Averty","avatar":""},{"name":"Franço","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
