INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-bien-binh', 'Công Chúa Biến Binh', 'Wonder Woman', 'https://phimimg.com/upload/vod/20231125-1/ef16e976e7b17dad904fe3bcd8e423f1.jpg', 'https://phimimg.com/upload/vod/20231125-1/0def17e1f496d449c88e9e01fb426a90.jpg', '<p>Trên hòn đảo Themyscira huyền bí, chủng tộc chiến binh Amazons kiêu hãnh và hung dữ đã nuôi nấng một cô con gái có vẻ đẹp, sự duyên dáng và sức mạnh vô biên: Công nương Diana. Khi một phi công chiến đấu của Quân đội, Steve Trevor, hạ cánh xuống hòn đảo, Diana nổi loạn và cứng đầu bất chấp luật pháp của người Amazon bằng cách đi cùng Trevor trở lại nền văn minh.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keri Russell","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Skye Arens","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Julianne Grossman","avatar":""},{"name":"Vicki Lewis","avatar":""},{"name":"David McCallum","avatar":""},{"name":"Jason Charles Miller","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Andrea Romano","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Bruce","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug"