INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-ai-tinh', 'Tôi Là Ái Tình', 'I Am Love', 'https://phimimg.com/upload/vod/20231125-1/112da3b0f6a9afe2745caa64de1e0e58.jpg', 'https://phimimg.com/upload/vod/20231125-1/59670efdae70fb2307017f66a7b89235.jpg', '<p>I am Love - Io sono l’amore (Tôi Là Ái Tình), một bộ phim của đạo diễn người Ý Luca Guadagnino và diễn viên chính Tilda Swinton. Một câu chuyện về tình yêu bị ngăn cấm, sự phản bội và lòng khát khao tự do, một bộ phim hấp dẫn, khiêu khích, và đầy đau đớn. Emma Recchi (Tilda Swinton), một phụ nữ tóc vàng xinh đẹp di cư từ Liên Xô cũ tới Milan. Ở đó, cô trở thành một người vợ nhu mì, một người mẹ của ba đứa con trong gia tộc Recchi giàu có. Cuộc sống của cô sẽ mãi yên ả với việc lên kế hoạch cho các bữa tiệc và lấy đồ giặt khô nếu như cô không bị một tay đầu bếp trẻ người Italy là bạn của cậu con lớn Edo tên là Antonio Biscaglia (Edoardo Gabbriellini) hớp mất hồn vía...</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Tilda Swinton","avatar":""},{"name":"Flavio Parenti","avatar":""},{"name":"Edoardo Gabbriellini","avatar":""},{"name":"Alba Rohrwacher","avatar":""},{"name":"Gabriele Ferzetti","avatar":""},{"name":"Marisa Berenson","avatar":""},{"name":"Pippo Delbono","avatar":""},{"name":"Diane Fleri","avatar":""},{"name":"Mattia Zaccaro","avatar":""},{"name":"Maria Paiato","avatar":""},{"name":"Waris Ahluwalia","avatar":""},{"name":"Honor Swinton Byrne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
