INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-xanh', 'Phấn Xanh', 'Powder Blue', 'https://phimimg.com/upload/vod/20231125-1/30ecb020165a71ec42496b343f67ca9b.jpg', 'https://phimimg.com/upload/vod/20231125-1/193d9c5e78132e7a54ccc08526ed8dd3.jpg', '<p>Trên những con đường nghiệt ngã của LA, số phận của bốn con người khao khát được kết nối và cứu chuộc sắp va chạm với nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Biel","avatar":""},{"name":"Eddie Redmayne","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Patrick Swayze","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"Sanaa Lathan","avatar":""},{"name":"Ravi Patel","avatar":""},{"name":"Mandy June Turpin","avatar":""},{"name":"Diana Prince","avatar":""},{"name":"Chandler Canterbury","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Billy Wirth","avatar":""},{"name":"Don Swayze","avatar":""},{"name":"Ben Hernandez Bray","avatar":""},{"name":"Joe Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
