INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-quan-sip-2009', 'Siêu Nhân Quần Sịp', 'Yatterman', 'https://phimimg.com/upload/vod/20231206-1/ea0e19c3b477b0734b4af9097ccc4fe2.jpg', 'https://phimimg.com/upload/vod/20231206-1/4944e1709cfe08ced881c5e6c87e93e9.jpg', '<p>Câu chuyện bắt đầu từ một truyền thuyết về viên đá đầu lâu Dokuro nổi danh thiên hạ bởi kho báu ẩn đằng sau nó. Thế nhưng khi đến trái đất, viên đá ấy đã vỡ vụn thành nhiều mảnh và lưu lạc trong nhân gian. Ôm mộng tiền tài và quyền lực, bộ ba phản diện Dorombo lên đường tìm kiếm viên đá thần kỳ Dokuro. Tuy nhiên, tham vọng của ma nữ sexy Doronjo cùng 2 tên hầu cận xấu xí của nàng không dễ gì để có thể thành hiện thực. Trên đường tìm kiếm đá thần, chúng gặp phải sự chống lại của phe chính diện là những siêu nhân Yatterman, lại cũng là một bộ ba khác nữa.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Shô Sakurai","avatar":""},{"name":"Sadao Abe","avatar":""},{"name":"Kyôko Fukada","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324478);
