INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('youth-in-revolt', 'Youth in Revolt', 'Youth in Revolt', 'https://phimimg.com/upload/vod/20231124-1/364337f56b3d4c15f748a0937fdde23d.jpg', 'https://phimimg.com/upload/vod/20231124-1/cc98ec2cd26539f1b76f75f8f6335c73.jpg', '<p>Là một người hâm mộ Albert Camus và Jean-Luc Godard, cậu thiếu niên Nick Twisp chắc chắn không hài lòng khi mẹ cậu và bạn trai của bà chuyển cả gia đình đến một công viên xe moóc. Khi một người hàng xóm xinh đẹp tên Sheeni chơi các đĩa hát của những nghệ sĩ croon người Pháp, Nick thất vọng và thiếu kinh nghiệm đã có cảm tình ngay từ cái nhìn đầu tiên. Biết rằng cô ấy đang hẹn hò với ai đó, Nick bắt đầu một nhiệm vụ vui nhộn để tìm đường vào trái tim của Sheeni -- và lên giường.</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Cera","avatar":""},{"name":"Portia Doubleday","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Adhir Kalyan","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Erik Knudsen","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"Jade Fusco","avatar":""},{"name":"Lise Lacasse","avatar":""},{"name":"Mary Kay Place","avatar":""},{"name":"Jonathan B. Wright","avatar":""},{"name":"Michae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
