INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spread', 'Spread', 'Spread', 'https://phimimg.com/upload/vod/20231124-1/c809306cb39c98a23715e4f96b915f3b.jpg', 'https://phimimg.com/upload/vod/20231124-1/fa11736e6e8315da74ffcf96e156a611.jpg', '<p>Ở Los Angeles, Nikki là người vô gia cư, ít xe hơi và đóng cửa vào ngày 30, nhưng anh ta trông đẹp, đẹp trai và lão luyện trong bao tải, di chuyển từ một người phụ nữ giàu có 35 hoặc 40 sang người khác, một món đồ chơi con trai. Gig mới nhất của anh ấy, với Samantha, một luật sư có ngôi nhà nhìn ra l.a., thật ngọt ngào, mặc dù không rõ cô ấy sẽ chịu đựng anh ấy bao lâu. Rồi Nikki gặp Heather, một cô hầu bàn. Là người chơi đang được chơi, hoặc đây có thể là tình yêu? Nikki sẽ khám phá những gì?</p>', 'Full', 1, 'single', 'completed', 10, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashton Kutcher","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Sonia Rockwell","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Shane Brolly","avatar":""},{"name":"Eric Balfour","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Derek Carter","avatar":""},{"name":"Jordan Black","avatar":""},{"name":"Dani Levine","avatar":""},{"name":"Peter Marc Jacobson","avatar":""},{"name":"Lindsey Broad","avatar":""},{"name":"Amy Motta","avatar":""},{"name":"Lau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
