INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-shippden-nguoi-ke-thua-hoa-chi', 'Naruto Shippūden: Người Kế Thừa Hỏa Chí', 'Naruto Shippuden the Movie: The Will of Fire', 'https://phimimg.com/upload/vod/20231121-1/3c9f311655c6d450cb6ba8b27e9182f3.jpg', 'https://phimimg.com/upload/vod/20231121-1/5bd7117c9a9afa38da778422766f6dec.jpg', '<p>Nói về nguy cơ nổ ra Đại chiến Ninja lần thứ 4 khi các ninja có huyết kế giới hạn ở các làng sương mù, làng đá, làng mây và làng cát bỗng nhiên bắt đầu biến mất. Các quốc gia nghi ngờ làng lá - làng duy nhất không bị ảnh hưởng - đã gây ra tai nạn trên và tung tin đồn về việc Konoha đang có kế hoạch tạo phản. Đồng thời họ điều động quân đội đến biên giới Hỏa Quốc chuẩn bị phát động tấn công. Những người đứng đầu Hỏa Quốc phải chứng minh sự trong sạch của Konoha - tìm ra nguyên nhân vụ việc, nếu không họ sẽ phải xóa xổ cả làng để giữ hòa bình thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Ryoka Yuzuki","avatar":""},{"name":"Kohsuke Toriumi","avatar":""},{"name":"Yōichi Masukawa","avatar":""},{"name":"Shinji Kawada","avatar":""},{"name":"Nana Mizuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324478);
