INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('naruto-shippden-nguoi-ke-thua-hoa-chi', 'Naruto Shippūden: Người Kế Thừa Hỏa Chí', 'Naruto Shippuden the Movie: The Will of Fire', 'naruto shippūden: người kế thừa hỏa chí naruto shippuden the movie: the will of fire junko takeuchi chie nakamura kazuhiko inoue romi park satoshi hino showtaro morikubo kentaro ito ryoka yuzuki kohsuke toriumi yōichi masukawa shinji kawada nana mizuki ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-cap-do-doi-dau', 'Bốn Cấp Độ Đối Đầu', 'The Fourth Kind', 'https://phimimg.com/upload/vod/20231121-1/eb66a50d67d9fa7c8d2e162967c1e107.jpg', 'https://phimimg.com/upload/vod/20231121-1/32f242ce4d788800b7f5369d8a2d7801.jpg', '<p>Là một phim kinh dị khiêu khích đặt bối cảnh tại Nome, Alaska thời nay, là nơi bí ẩn kể từ thập niên 1960 - một lượng dân số thiếu cân xứng được thông báo là mất tích hàng năm. Mặc dù có rất nhiều nhân viên FBI đến điều tra khu vực, sự thật vẫn chưa bao giờ được khám phá. Tại một khu vực hẻo lánh, Tiến sỹ tâm lý học Abigail Tyler bắt đầu những buổi thu hình với những bệnh nhân bị chấn thương và vô tình khám phá ra một vài những chứng cứ đáng lo ngại nhất về vụ bắt cóc của người ngoài hành tinh chưa từng được ghi vào tài liệu...</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Eric Loren","avatar":""},{"name":"Mia McKenna-Bruce","avatar":""},{"name":"Raphaël Coleman","avatar":""},{"name":"Daphne Alexander","avatar":""},{"name":"Alisha Seaton","avatar":""},{"name":"Tyne Rafaeli","avatar":""},{"name":"Pavel Stefanov","avatar":""},{"name":"Kiera McMaster","avatar":""},{"name":"Sara Houghton","avatar":""},{"name":"Julian Vergov","avatar":""},{"name":"Ioan Lov","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
