INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bon-cap-do-doi-dau', 'Bốn Cấp Độ Đối Đầu', 'The Fourth Kind', 'bốn cấp độ đối đầu the fourth kind milla jovovich will patton hakeem kae-kazim corey johnson enzo cilenti elias koteas eric loren mia mckenna-bruce raphaël coleman daphne alexander alisha seaton tyne rafaeli pavel stefanov kiera mcmaster sara houghton julian vergov ioan lov ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-thuyet-khung-bo', 'Học Thuyết Khủng Bố', 'Echelon Conspiracy', 'https://phimimg.com/upload/vod/20231120-1/a2c5abc00fb6389c4324f05c65eb6542.jpg', 'https://phimimg.com/upload/vod/20231120-1/3225ecb85317735922d7d7e48ac96d3b.jpg', '<p>Trong chuyến công tác tại Thái Lan, Max Peterson, một kỹ sư tin học tình cờ nhân được một thùng đồ. Trong đó là một điện thoại công nghệ mới hiện đại và có khả năng &quot;tư duy&quot; khi luôn đưa ra những sự thật của “tương lai&quot;. Với cái phone trời cho, Max đã vào sòng bài lớn nhất nước Nga và toàn thắng. Thậm chí anh còn thắng được giải thưởng lớn nhất trị giá 3 triệu USD. Tuy nhiên, mọi hành động của anh đều bị FBI và thế lực sau lưng chú ý. Max hoàn toàn không biết mình chỉ là 1 nạn nhân kiếm tiền của người đứng sau hê thống thông minh. Hệ thống này đã lợi dụng sự bảo mật lỏng lẽo của cổng thông tin Hoa Kỳ. Khi mà mọi thông tin và hoạt động của con người đều được đưa vào máy tính một cách bí mật. Bằng sự quản lý của computer, họ dần mất đi quyền tự chủ và tự do của chính mình...</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shane West","avatar":""},{"name":"Edward Burns","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Steven Elder","avatar":""},{"name":"Sandra De Sousa","avatar":""},{"name":"Greg Donaldson","avatar":""},{"name":"Gosha Kutsenko","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Amara Zaragoza","avatar":""},{"name":"Sergey Gubanov","avatar":""},{"name":"Ilan Goodman","avatar":""},{"name":"Todd Jensen","avatar":""},{"name":"Andrea Enright","avatar":""},{"name":"Trevor White","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Danko Jordanov","avatar":""},{"name":"Veliza","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
