INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lung-tren-khong', 'Lơ Lửng Trên Không', 'Up in the Air', 'https://phimimg.com/upload/vod/20231120-1/2d9ffe9c6931750e3f8edea307192547.jpg', 'https://phimimg.com/upload/vod/20231120-1/d227ca94235dcc813140edc545df9f83.jpg', '<p>Cuộc đời nhẹ tênhRyan Bingham, bên cạnh công việc chính của mình mà ta sẽ nhắc đến sau, kiếm sống bằng nghề thuyết trình về triết lý sống của mình. Triết lý sống giúp anh tồn tại và thành công. Triết lý sống biệt lập. Sống ngăn nắp, chỉn chu, mọi thứ đều vào những khuôn khổ một cách chính xác, không ràng buộc với bất kỳ mối quan hệ xã hội nào. Bởi như anh nói: “Nói không ngoa, những mối quan hệ của bạn chính là những thứ nặng nề nhất trong đời bạn”.Không gia đình - chị và em gái của Ryan từ lâu không còn xem anh như một thành viên trong gia đình. Không tình yêu - anh có một bạn tình, Alex Goran, người phụ nữ “hoàn hảo” với Ryan. Họ gặp nhau trong những chuyến công tác, ngồi ăn uống trong những quầy bar, nhà hàng sang ...</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Amy Morton","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Tamala Jones","avatar":""},{"name":"Adhir Kalyan","avatar":""},{"name":"Keri Maletto","avatar":""},{"name":"Steve Eastin","avatar":""},{"name":"Adrienne Lamping","avatar":""},{"name":"​Christopher Lowell","avatar":""},{"name":"Erin McGra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
