INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-laventure', 'À l''aventure', 'À l''aventure', 'https://phimimg.com/upload/vod/20231120-1/2bdcb2a9f3f8c5f824beb5939807335c.jpg', 'https://phimimg.com/upload/vod/20231120-1/cd3117aef18945052ced6480c893e348.jpg', '<p>Chán nản với lối sống hiện tại và đặc biệt hơn là không được thỏa mãn về mặt tình dục với bạn trai Fred, Sandrine quyết định tìm một con đường mới trong cuộc sống. Bị hấp dẫn bởi người bạn Sophie, người đã kể cho cô nghe về những trải nghiệm tình dục của mình, qua nhiều cuộc gặp gỡ khác nhau, cô sẽ tìm thấy những niềm vui mới và trải nghiệm mới, dù là về thể chất hay tinh thần.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Carole Brana","avatar":""},{"name":"Lise Bellynck","avatar":""},{"name":"Jocelyn Quivrin","avatar":""},{"name":"Arnaud Binard","avatar":""},{"name":"Nadia Chibani","avatar":""},{"name":"Etienne Chicot","avatar":""},{"name":"Estelle Galarme","avatar":""},{"name":"Frederic Aspisi","avatar":""},{"name":"Michèle Larue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
