INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-nghia-tu-ban-mot-cau-chuyen-tinh', 'Chủ Nghĩa Tư Bản : Một Câu Chuyện Tình', 'Capitalism: A Love Story', 'https://phimimg.com/upload/vod/20231123-1/a5077d90ac9ba0d9f466be55866714d9.jpg', 'https://phimimg.com/upload/vod/20231123-1/fca1b574c97c75d4f3418b81da13ffee.jpg', '<p>Capitalism: A Love Story là một trải nghiệm tuyệt vời để thể nghiệm về cái bóng hào nhoáng của tư bản Mỹ. Tất cả những gì về giấc mơ Mỹ, Thiên đường Mỹ ẩn sau vẻ mặt hoành tráng phú cường của nước Mỹ, những gì người ta không bao giờ thấy qua truyền thông và báo đài hiện lồ lộ trước mắt.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Moore","avatar":""},{"name":"Elijah Cummings","avatar":""},{"name":"Marcy Kaptur","avatar":""},{"name":"Bernie Sanders","avatar":""},{"name":"Elizabeth Warren","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Baron Hill","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Peter Zalewski","avatar":""},{"name":"Bill Clinton","avatar":""},{"name":"Paul Ryan","avatar":""},{"name":"Joe Biden","avatar":""},{"name":"Michael Bloomberg","avatar":""},{"name":"Ruth Bader Ginsburg","avatar":""},{"name":"Martin Luther King Jr.","avatar":""},{"name":"Barack Obama","avatar":""},{"name":"Nancy","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324478);
