INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock-holmes', 'Thám Tử Sherlock Holmes', 'Sherlock Holmes', 'https://phimimg.com/upload/vod/20231123-1/d735b80de6d8a5445aff1c9e33c02571.jpg', 'https://phimimg.com/upload/vod/20231123-1/6db684ed962afa8bab6eb0d530cdac3c.jpg', '<p>Sau khi hàng loạt án mạng tàn bạo và sặc mùi cuồng tín xảy ra, Sherlock Holmes và người trợ tá đắc lực - bác sĩ John Watson - ra tay kịp thời cứu mạng nạn nhân tiếp theo và vạch mặt kẻ thủ ác: Blackwood. Tuy nhiên, đối với kẻ khát máu này, cái chết không hề làm hắn run sợ, mà ngược lại, bản án tử hình Sherlock Holmes &quot;tuyên&quot; cho hắn còn thúc đẩy hắn nhanh chóng hoàn thiện mưu đồ hắc ám của mình. Càng truy đuổi theo những đầu mối, ngài thám tử và vị bác sĩ tài ba càng dấn sâu vào một thế giới được thao túng bởi thế lực hắc ám và đầy rẫy những công cụ khoa học đáng sợ...</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Robert Maillet","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"William Houston","avatar":""},{"name":"Hans Matheson","avatar":""},{"name":"James Fox","avatar":""},{"name":"William Hope","avatar":""},{"name":"Clive Russell","avatar":""},{"name":"Oran Gurel","avatar":""},{"name":"David Garrick","avatar":""},{"name":"Ky Discala","avatar":""},{"name":"Andrew Brooke","avatar":""},{"name":"Tom Watt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình 