INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-tournament', 'The Tournament', 'The Tournament', 'https://phimimg.com/upload/vod/20231123-1/e137b74cbe262810dc151c5112fe7435.jpg', 'https://phimimg.com/upload/vod/20231123-1/332e49550ff328d027d30138e0d86c00.jpg', '<p>Cứ mười hoặc bảy năm một lần tại một thị trấn không ngờ tới, Giải đấu lại diễn ra. Một trận chiến hoàng gia giữa 30 sát thủ nguy hiểm nhất thế giới. Người đàn ông cuối cùng đứng nhận giải thưởng tiền mặt trị giá 10.000.000 đô la và danh hiệu số 1 thế giới, bản thân giải thưởng này đã mang mức giá một viên đạn huyền thoại triệu đô la.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ving Rhames","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Ian Somerhalder","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Sébastien Foucan","avatar":""},{"name":"Craig Conway","avatar":""},{"name":"John Lynch","avatar":""},{"name":"Nick Rowntree","avatar":""},{"name":"Rachel Grant","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Camilla Power","avatar":""},{"name":"Tamika Cameran","avatar":""},{"name":"Bashar Rahal","avatar":""},{"name":"J.J. Perry","avatar":""},{"name":"Velimir Vel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
