INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-tournament', 'The Tournament', 'The Tournament', 'the tournament the tournament ving rhames robert carlyle ian somerhalder kelly hu liam cunningham sébastien foucan craig conway john lynch nick rowntree rachel grant andy nyman iddo goldberg scott adkins camilla power tamika cameran bashar rahal j.j. perry velimir vel ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wonderful-world', 'Wonderful World', 'Wonderful World', 'https://phimimg.com/upload/vod/20231123-1/c4e5cb6ba96d310ef06fb3d68c3e12aa.jpg', 'https://phimimg.com/upload/vod/20231123-1/d59f7466296b2fc4f79a3039951f9807.jpg', '<p>Ben Singer là một ca sĩ nhạc dân ca thiếu nhi thất bại, một người soát lỗi sự nghiệp, một người cha không mấy xuất sắc vào cuối tuần và có lẽ là người đàn ông tiêu cực nhất còn sống. Lúng túng trong mọi khía cạnh của cuộc sống, niềm an ủi duy nhất của Ben đến từ những trận đấu cờ thường xuyên và những cuộc tranh luận thân thiện về lý thuyết trò chơi với người bạn cùng phòng người Senegal, Ibou. Khi Ibou đột ngột đổ bệnh, thế giới quan bi quan của Ben dường như đã được khẳng định một cách rõ ràng. Phải mất một chuyến thăm kéo dài từ chị gái của Ibou, Khadi, Ben mới nhận ra rằng sự hoài nghi có thể chỉ là vấn đề về quan điểm.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Broderick","avatar":""},{"name":"Sanaa Lathan","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Ally Walker","avatar":""},{"name":"Mia Ford","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
