INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('wonderful-world', 'Wonderful World', 'Wonderful World', 'wonderful world wonderful world matthew broderick sanaa lathan michael kenneth williams philip baker hall jesse tyler ferguson jodelle ferland ally walker mia ford ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-xa-thu', 'Siêu xạ thủ', 'The Sniper', 'https://phimimg.com/upload/vod/20231123-1/21dc4ccec87e81002d04bbae16a0a5df.jpg', 'https://phimimg.com/upload/vod/20231123-1/a8b2ce50e9034f4da5994c67eea66b0e.jpg', '<p>Hartman và Lincoln là hai xạ thủ cao siêu trong hàng ngũ cảnh sát. Một vụ cướp ngân hàng diễn ra và Hartman, Lincohn được điều đến để trấn áp tên tội phạm đang uy hiếp con tin. Lincoln nổ súng, vô tình giết chết con tin. Sau việc đó, anh phải ngồi tù bốn năm. Vợ anh vì quá đau buồn đã tự vẫn. Trong thời gian đó, Hartman gặp OJ - một cảnh sát trẻ có tiềm năng trở thành xạ thủ siêu đẳng. Chính vì vậy, Hartman đã quyết định kết nạp OJ vào nhóm xạ thủ của mình. Tuy nhiên, OJ cũng là một anh chàng cảnh sát cứng đầu. Trong một vụ án bắt cóc con tin, OJ đã sử dụng chiêu thức khá nguy hiểm - tương tự như phát bắn trước kia của Lincoln để bắn hạ hung thủ. Sau bốn năm, Lincoln ra tù và quyết tâm trả thù Hartman vì những uẩn khuất chưa được sáng tỏ trong vụ cướp nhà băng năm xưa. Và Lincoln đã làm mọi thứ thực hiện mục đích, kể cả cấu kết với bọn tội phạm và chống lại cảnh sát. Một cuộc chiến đẫm máu đã diễn ra giữa 3 tay súng cừ khôi: Lincoln, Hartman và OJ. Liệu ai sẽ là người chiến thắng? Và ai sẽ siêu xạ thủ...</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Richie Jen","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Mango Wong","avatar":""},{"name":"Bowie Lam","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Lam Chi-Tai","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Calvin Poon Yuen-Leung","avatar":""},{"name":"Cheung Chi-Sing","avatar":""},{"name":"Gregory Lam Kwai-Ban","avatar":""},{"name":"Stephen Tung Wai","avatar":""},{"name":"Charmaine Fong","avatar":""},{"name":"Chan Wai-Ling","avatar":""},{"name":"Lawrence Ah Mon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
