INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-xa-thu', 'Siêu xạ thủ', 'The Sniper', 'siêu xạ thủ the sniper richie jen edison chen huang xiaoming mango wong bowie lam michelle ye wilfred lau jack kao lam chi-tai patrick tang calvin poon yuen-leung cheung chi-sing gregory lam kwai-ban stephen tung wai charmaine fong chan wai-ling lawrence ah mon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-tho-2009', 'Khó Thở', 'Breathless', 'https://phimimg.com/upload/vod/20231123-1/c796c13d46e384399bc595bcaf31000f.jpg', 'https://phimimg.com/upload/vod/20231123-1/cc45e22f9248713f891ba6342930043a.jpg', '<p>Khó Thở là bộ phim vinh danh nền điên ảnh Hàn Quốc tại các liên hoan phim thế giới năm 2008. Bộ phim kể về cậu bé Sang Hoon lớn lên trong bạo lực, để trả thù người cha đã hủy hoại gia đình, Sang hoon trở thành tên du côn chuyên đi đòi nợ thuê. Cho đến một ngày anh gặp được cô học sinh bướng bỉnh Yeon Hee cũng có hoàn cảnh gia đình tương tự. Hai con người khốn khổ, tìm thấy ở nhau sự đồng cảm, niềm an ủi, và những niềm hạnh phúc nho nhoi. Thoát khỏi tăm tối, Sang Hoon và Yeon Hee dần được mọi người xung quanh đón nhận và tìm thấy giá trị đích thực của cuộc sống và tương lai.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yang Ik-june","avatar":""},{"name":"Kim Kkob-bi","avatar":""},{"name":"Lee Hwan","avatar":""},{"name":"Park Jeong-soon","avatar":""},{"name":"Lee Seung-yeon","avatar":""},{"name":"Kim Hee-Soo","avatar":""},{"name":"Choi Yong-min","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Ji Seon-ae","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Yun Seung-hun","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Kim Wang-geun","avatar":""},{"name":"Lee Eung-jae","avatar":""},{"name":"Kim Sang-won","avatar":""},{"name":"Oh Ji-hye","avatar":""},{"name":"Woo Jung-kook","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
