INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-xac-ac-quy', 'Thân Xác Ác Quỷ', 'Jennifer''s Body', 'https://phimimg.com/upload/vod/20231123-1/102b2f4502a3bf207b660194a1d8058a.jpg', 'https://phimimg.com/upload/vod/20231123-1/87099324d4325ce67fed58f716ea0d36.jpg', '<p>Sức nóng Jennifer phim kể về Nerdy, Ltd. mọt sách Needy Lesnicki, và kiêu ngạo, tự cao tự cổ vũ Jennifer tra là những người bạn tốt nhất, mặc dù họ chia sẻ rất ít điểm chung. Họ chia sẻ thậm chí ít điểm chung khi Jennifer bí ẩn đạt một cảm giác ngon miệng cho máu của con người sau khi một đám cháy thảm khốc tại một quán bar địa phương. Như các bạn học nam của Needy đang dần giết chết trong các cuộc tấn công khủng khiếp, các cô gái trẻ phải tìm ra sự thật đằng sau chuyển đổi của bạn mình và tìm thấy một cách để ngăn chặn các cuộc tàn sát khát máu trước khi nó đạt đến bạn trai của cô Chip.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Megan Fox","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Cynthia Stevenson","avatar":""},{"name":"Sal Cortez","avatar":""},{"name":"Ryan Levine","avatar":""},{"name":"Juan Riedinger","avatar":""},{"name":"Colin Askey","avatar":""},{"name":"Juno Rinaldi","avatar":""},{"name":"Josh Emerson","avatar":""},{"name":"Nicole Leduc","avatar":""},{"name":"Aman Johal","avatar":""},{"name":"Dan Joffre","avatar":""},{"name":"Candus","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]',