INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-eric', 'Đi Tìm Eric', 'Looking for Eric', 'https://phimimg.com/upload/vod/20231123-1/6920c780edf5eb04ee488282148f801d.jpg', 'https://phimimg.com/upload/vod/20231123-1/aa0fbe9ec40ddceafbd80b2c540b1cff.jpg', '<p>Looking for Eric là một bộ phim hài hước nói về tầm ảnh hưởng của những ngôi sao sân cỏ đối với những fan hâm mộ. Nhân vật chính của phim là một anh chàng tên Eric Bishop, một người đưa thư cuồng bóng đá tới mức “bỏ mặc” vợ con. Sau khi tự tử bất thành, anh ta bị ám ảnh rằng thần tượng Eric Cantona giúp đỡ anh, đưa cho anh những lời khuyên trong cuộc sống...</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Éric Cantona","avatar":""},{"name":"Steve Evets","avatar":""},{"name":"Stephanie Bishop","avatar":""},{"name":"John Henshaw","avatar":""},{"name":"Gerard Kearns","avatar":""},{"name":"Stefan Gumbs","avatar":""},{"name":"Lucy-Jo Hudson","avatar":""},{"name":"Justin Moorhouse","avatar":""},{"name":"Matthew McNulty","avatar":""},{"name":"Smug Roberts","avatar":""},{"name":"Mick Ferry","avatar":""},{"name":"Maxton Beesley","avatar":""},{"name":"Steve Marsh","avatar":""},{"name":"Ryan Pope","avatar":""},{"name":"Cleveland Campbell","avatar":""},{"name":"Laura Ainsworth","avatar":""},{"name":"Julie Brown","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
