INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('18-tuoi-van-con-zin', '18 Tuổi Vẫn Còn Zin', '18 Year Old Virgin', 'https://phimimg.com/upload/vod/20231123-1/3bed9e6a706ba2a8d626a7d009106087.jpg', 'https://phimimg.com/upload/vod/20231123-1/441d46082b6235193f336c543e4cad8b.jpg', '<p>Bộ phim xoay quanh cuộc sống của Kate Powers, học sinh cuối cấp. Dù cô có vẻ bề ngoài hấp dẫn nhưng vẫn chưa có bạn trai. Ghen tị với những cô gái khác trong trường, Katie tuyên bố sẽ &quot;vượt qua giới hạn&quot; trước ngày tốt nghiệp. Do đó, Katie chuẩn bị một lịch trình nghiêm túc với nhiều chàng trai khác nhau và cố gắng đưa họ lên giường để hoàn thành mục tiêu của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olivia May","avatar":""},{"name":"Lauren Walsh","avatar":""},{"name":"Todd Leigh","avatar":""},{"name":"Dustin Harnish","avatar":""},{"name":"Karmen Morales","avatar":""},{"name":"Dan Sykes","avatar":""},{"name":"J. Michael Trautmann","avatar":""},{"name":"Robbie Henke","avatar":""},{"name":"Seth Cassell","avatar":""},{"name":"Dustin Fitzsimons","avatar":""},{"name":"Danielle Gatto","avatar":""},{"name":"Conor Moriarty","avatar":""},{"name":"Brad Ulrich","avatar":""},{"name":"Kim Argetsinger","avatar":""},{"name":"Crystal Baker","avatar":""},{"name":"Elli Foxx","avatar":""},{"name":"Erica Rhodes","avatar":""},{"name":"Bla","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
