INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hannah-montana-the-movie', 'Hannah Montana: The Movie', 'Hannah Montana: The Movie', 'https://phimimg.com/upload/vod/20231123-1/e0b82264e4c9b45fbe74a951ab1c3752.jpg', 'https://phimimg.com/upload/vod/20231123-1/bd0aafbd4512ec290b2fd79aa2959de2.jpg', '<p>Khi Miley Stewart (hay còn gọi là ngôi sao nhạc pop Hannah Montana) bị cuốn vào lối sống của những ngôi sao siêu sao, bố cô quyết định đã đến lúc phải thay đổi hoàn toàn khung cảnh. Nhưng nibles ngọt ngào! Miley phải đánh đổi tất cả sự hào nhoáng và quyến rũ của Hollywood để lấy một chiếc quần jean xanh cũ kỹ trong trang trại của gia đình ở Tennessee, và đặt câu hỏi liệu cô có thể vừa là Miley Stewart vừa là Hannah Montana hay không.</p>', 'Full', 1, 'single', 'completed', 22, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miley Cyrus","avatar":""},{"name":"Billy Ray Cyrus","avatar":""},{"name":"Emily Osment","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Jason Earles","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Melora Hardin","avatar":""},{"name":"Mitchel Musso","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Taylor Swift","avatar":""},{"name":"Vanessa Williams","avatar":""},{"name":"Peter Gunn","avatar":""},{"name":"Jared Carter","avatar":""},{"name":"Barry Bostwick","avatar":""},{"name":"Beau Billingslea","avatar":""},{"name":"Katrina Smith","avatar":""},{"name":"Emily Grace Reav","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình C