INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-nu-sinh', 'Hội Nữ Sinh', 'The Telling', 'null', 'https://phimimg.com/upload/vod/20231120-1/a499ef77c96314a4e2d6b033076ffb60.jpg', '<p>Ba cô gái muốn tham gia Hội Nữ Sinh nổi tiếng là quái đản và kì dị trong trường đại học. Nhiệm vụ của họ là phải kể câu chuyện kinh dị khiến cho những người nghe thấy câu chuyện này trong hội nữ sinh bị ám ảnh và thực hiện vụ giết người như trong câu chuyện họ kể.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bridget Marquardt","avatar":""},{"name":"Holly Madison","avatar":""},{"name":"Najarra Townsend","avatar":""},{"name":"Angela Nicholas","avatar":""},{"name":"Jean Louise O''Sullivan","avatar":""},{"name":"Ashley Noel","avatar":""},{"name":"Nicole Zeoli","avatar":""},{"name":"Christine Nguyen","avatar":""},{"name":"Ed Gale","avatar":""},{"name":"Diane Salinger","avatar":""},{"name":"John D''Aquino","avatar":""},{"name":"Rebekah Kochan","avatar":""},{"name":"Christina Rosenberg","avatar":""},{"name":"Wesley Stiller","avatar":""},{"name":"Alyssa Price","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
