INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pomegranates-and-myrrh', 'Pomegranates and Myrrh', 'Pomegranates and Myrrh', 'null', 'https://phimimg.com/upload/vod/20231120-1/0be3f98dc62ac2377d2e03271b5a6aa4.jpg', '<p>Ở Ramallah, Kamar phóng khoáng chật vật sau khi chồng cô bị tống giam và xung đột với quy tắc đạo đức nghiêm ngặt nơi quê nhà. Rồi cô tìm lại được đam mê khiêu vũ.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Yasmine Al Massri","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Ali Suliman","avatar":""},{"name":"Walid Abdul Salam","avatar":""},{"name":"Ahmad Abu Sal''oum","avatar":""},{"name":"Yosef Abu Wardeh","avatar":""},{"name":"Valentina Abu-''Aksa","avatar":""},{"name":"Manal Awad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
