INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('white-night', 'White Night', 'White Night', 'https://phimimg.com/upload/vod/20231116-1/89b8780be815161ab5d5ecb2d48faaee.jpg', 'https://phimimg.com/upload/vod/20231116-1/d4e2472c0e13f95661598191d0cea7a2.jpg', '<p>Một người cầm đồ được tìm thấy bị sát hại ở một thị trấn xa xôi. Cảnh sát nghi ngờ rằng ông đã bị sát hại bởi một người quen, vì ngay cả điều tra viên giàu kinh nghiệm nhất trong vụ án cũng có thể xác định không có dấu hiệu kháng thuốc. Ba người bị nghi ngờ nhưng tất cả bọn họ đều có thành phố hoàn hảo và cuộc điều tra đến bế tắc. Một năm sau, một trong số họ được tìm thấy đã chết và vụ án giết người ban đầu thậm chí còn bí ẩn hơn. Gần mười lăm năm trôi qua và thanh tra chính, hiện đang tiếp cận nghỉ hưu, phản ánh về trường hợp duy nhất anh ta không thể giải quyết trong một nghề nghiệp thành công khác. Bị ám ảnh bởi một cảm giác trách nhiệm và cảm giác tội lỗi mà anh ta gây ra đau khổ bằng cách để vụ án giết người chưa được giải quyết, anh ta quyết định điều tra lại. Tìm kiếm dai dẳng của anh mang lại sự chú ý đến trường hợp bị lãng quên từ lâu và tiết lộ một mối quan hệ ẩn giấu giữa con trai của nạn nhân và con gái của người phụ nữ khu phố. Khi tình yêu của họ phát triển, nhiều tội lỗi xảy ra. Khi tội lỗi của họ phát triển, Chase của Thanh tra đến gần họ hơn.</p>', 'Full', 1, 'single', 'completed', 11, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Han Suk-kyu","avatar":""},{"name":"Go Soo","avatar":""},{"name":"Lee Min-jung","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Cha Hwa-yeon","avatar":""},{"name":"Jin Jung","avatar":""},{"name":"Im Ji-gyu","avatar":""},{"name":"Bang Joong-Hyun","avatar":""},{"name":"Son Ji-na","avatar":""},{"name":"Joo Ah-reum","avatar":""},{"name":"Ye Soo-jung","avatar":""},{"name":"Han Ye-won","avatar":""},{"name":"Kim Ji-hyeon","avatar":""},{"name":"Jo Kyung-sook","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Seo Dong-soo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
