INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-nhai', 'Hàng Nhái', 'Extract', 'https://phimimg.com/upload/vod/20231120-1/3da3dbf14c8bdbc178a8ce16b8e17191.jpg', 'https://phimimg.com/upload/vod/20231120-1/1068ae7689b7d4e401d6b172b3ddcb31.jpg', '<p>Chủ sở hữu của một nhà máy sản xuất chiết xuất hương liệu, Joel Reynold dường như có tất cả, nhưng thực sự thì không. Điều còn thiếu là sự quan tâm tình dục từ vợ anh ấy, Suzie. Joel nảy ra một kế hoạch phức tạp để khiến Suzie lừa dối anh ta, từ đó dọn đường cho Joel ngoại tình với Cindy, một nhân viên. Nhưng điều mà Joel không biết là Cindy là một kẻ lừa đảo có thái độ xã hội đen, và một tai nạn kinh hoàng tại nơi làm việc đã mở đường cho cô ấy hủy hoại Joel mãi mãi.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Javier Gutiérrez","avatar":""},{"name":"Lidia Porto","avatar":""},{"name":"Gene Simmons","avatar":""},{"name":"Matt Schulze","avatar":""},{"name":"Lamberto Gutierrez","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Hal Sparks","avatar":""},{"name":"Ni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
