INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-chuot-lang', 'Biệt Đội Chuột Lang', 'G-Force', 'https://phimimg.com/upload/vod/20231119-1/16fd56356da2dcd87fc4b84e56aa9c43.jpg', 'https://phimimg.com/upload/vod/20231119-1/805c53e97a402e261b176e88f8978d8b.jpg', '<p>Một chuyến phiêu lưu hài hước xoay quanh câu chuyện về một nhóm nhân viên tình báo đặc biệt của chính phủ: Biệt đội chuột lang . Được trang bị những thiết bị tối tân, những chú chuột lang được huấn luyện chuyên nghiệp đang nắm giữ vận mệnh của cả thế giới. Nhóm G-Force gồm có chú chuột lang Darwin (Sam Rockwell lồng tiếng), người chỉ huy tài ba; chuột lang Blaster (Tracy Morgan lồng tiếng), chuyên gia về vũ khí; chuột lang Juarez (Penelope Cruz lồng tiếng ) –bậc thầy về võ thuật cùng vẻ ngoài đầy quyến rũ; cộng thêm trinh sát ruồi Mooch (Edwin Louis) và chuyên gia máy tính, chuột chũi mũi sao Speckles (Nicolas Cage lồng tiếng).</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Kelli Garner","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Jared Lavette","avatar":""},{"name":"Micah Lavette","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Loudon Wainwright III","avatar":""},{"name":"Tyler Patrick Jones","avatar":""},{"name":"Piper M","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
