INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuc-9', 'Khu Vực 9', 'District 9', 'https://phimimg.com/upload/vod/20231118-1/ce5173f68031a49bbd3732b42f49bb64.jpg', 'https://phimimg.com/upload/vod/20231118-1/ba9a4c8bb01abf1a96f82a56d6b3f8b1.jpg', '<p>Hai mươi năm trước, người ngoài hành tinh bắt liên lạc lần đầu tiên với Trái đất. Con người chờ đợi các cuộc tấn công dữ dội, hoặc những bước tiến công nghệ vĩ đại. Nhưng trái với những gì con người mong đợi, người ngoài hành tinh là những sinh vật tị nạn, là những sinh vật sống sót duy nhất trên hành tinh của họ. Các sinh vật này dựng một phi thuyền căn cứ ở Khu 9 thuộc Nam Phi. Khi đấy, cả thế giới đang còn tranh cãi phải làm gì với người ngoài hành tinh.30 năm sau, lòng kiên nhẫn của con người đi đến giới hạn. Mọi vấn đề liên quan đến người ngoài hành tinh được giao cho MNU, một công ty tư nhân không mấy liên quan đến các vấn đề về người ngoài hành tinh, nhưng họ sẽ nhận được khoảng tiền khổng lồ ...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sharlto Copley","avatar":""},{"name":"Jason Cope","avatar":""},{"name":"Nathalie Boltt","avatar":""},{"name":"Sylvaine Strike","avatar":""},{"name":"Elizabeth Mkandawie","avatar":""},{"name":"John Sumner","avatar":""},{"name":"William Allen Young","avatar":""},{"name":"Nick Blake","avatar":""},{"name":"Greg Melvill-Smith","avatar":""},{"name":"Robert Hobbs","avatar":""},{"name":"Vanessa Haywood","avatar":""},{"name":"Morena Busa Sesatsa","avatar":""},{"name":"Themba Nkosi","avatar":""},{"name":"Mzwandile Nqoba","avatar":""},{"name":"Barry Strydom","avatar":""},{"name":"Jed Broph","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324478);
