INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-boc-thep', 'Xe Bọc Thép', 'Armored', 'https://phimimg.com/upload/vod/20231116-1/7919ad35b0ce5ecd4a23abe1ec6966e3.jpg', 'https://phimimg.com/upload/vod/20231116-1/5a390d34cc38cd4dc86f26d9541db0f1.jpg', '<p>Một nhóm sĩ quan tại một công ty an ninh vận tải bọc thép mạo hiểm mạng sống của họ khi họ bắt tay vào vụ cướp cuối cùng chống lại chính công ty của họ. Được trang bị một kế hoạch có vẻ như không thể tin được, những người đàn ông lên kế hoạch kiếm bộn tiền mà không gây hại gì. Nhưng khi một nhân chứng bất ngờ can thiệp, kế hoạch nhanh chóng bị phá vỡ và tất cả các vụ cá cược đều bị hủy bỏ.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Columbus Short","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Skeet Ulrich","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Andre Kinney","avatar":""},{"name":"Andrew Fiscella","avatar":""},{"name":"Nick Jameson","avatar":""},{"name":"Glenn Taranto","avatar":""},{"name":"Lorna Raver","avatar":""},{"name":"Garry Guerrier","avatar":""},{"name":"Robert Harvey","avatar":""},{"name":"Shawn Devorse","avatar":""},{"name":"Mike Cochrane","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784