INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xe-boc-thep', 'Xe Bọc Thép', 'Armored', 'xe bọc thép armored columbus short matt dillon jean reno laurence fishburne amaury nolasco skeet ulrich fred ward milo ventimiglia andre kinney andrew fiscella nick jameson glenn taranto lorna raver garry guerrier robert harvey shawn devorse mike cochrane pa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-rainy-days', 'My Rainy Days', 'My Rainy Days', 'https://phimimg.com/upload/vod/20231116-1/5c6a050f97781f5cb90015975f963294.jpg', 'https://phimimg.com/upload/vod/20231116-1/c0a142ff3dae78abdd97385c9cbd1b0b.jpg', '<p>Học sinh trung học mười bảy tuổi Rio Ozawa luôn là trung tâm của sự chú ý do vẻ đẹp của cô. Tuy nhiên, Rio chưa bao giờ quan tâm đến bất cứ ai nhưng bản thân mình do quá khứ đau thương của cô. Bạn bè của cô chỉ tồn tại để cô có thể sử dụng chúng cho lợi ích của mình. Rio chỉ quan tâm đến tiền. Cô ấy có liên quan đến việc hẹn hò bù đắp của người Viking và tống tiền. Một ngày nọ, những bức ảnh của Rio được trộn lẫn tại cửa hàng với những người của người khác tên Ozawa. Sau đó, cô gặp giáo sư trường đại học 35 tuổi Kouki Ozawa, và lần đầu tiên yêu nhau. Rio cảm thấy bối rối bởi cảm xúc của cô. Cô ấy thay đổi từ một người tự tin, trưởng thành, đến một thứ giống như một nữ sinh điển hình với một lòng kinh hoàng. Cô ấy đi theo Kouki xung quanh, yêu cầu anh ta dạy kèm với cô ấy, và muốn hẹn hò với anh ấy. Mặc dù Kouki trở nên quan tâm đến Rio, có một lý do anh ta không theo đuổi mối quan hệ. Tuy nhiên, Rio rất khăng khăng và bắt đầu thay đổi cả thế giới của mình để tốt hơn để ở bên anh ta. Đột nhiên Kouki biến mất mà không nói lời tạm biệt, và Rio bị nghiền nát. Bạn bè của cô, với sự giúp đỡ của người thân của Kouki, thấy anh làm việc ở một trường khác. Rio sau đó phát hiện ra rằng anh ta đang chết vì ung thư não, đó là lý do tại sao anh ta muốn giữ khoảng cách của mình, để tránh phá vỡ trái tim mình. Cô ấy thuyết phục anh ta có được một hoạt động mạo hiểm, ngay cả khi điều đó có nghĩa là anh ta không thể nhớ cô, để họ có thể có nhiều thời gian hơn với nhau. Cuối cùng, anh ta sống sót sau phẫu thuật, và họ lại gặp nhau, mặc dù nó không rõ ràng nếu anh ta nhớ cô.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nozomi Sasaki","avatar":""},{"name":"Shosuke Tanihara","avatar":""},{"name":"Hikaru Yamamoto","avatar":""},{"name":"Mitsuki Oishi","avatar":""},{"name":"Araki Nanaki","avatar":""},{"name":"Saki Kagami","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Wakana Sakai","avatar":""},{"name":"Mitsuru Fukikoshi","avatar":""},{"name":"Mayumi Wakamura","avatar":""},{"name":"Kanji Tsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
