INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-minh-ra-noi-doi', 'Phát minh ra nói dối', 'The Invention of Lying', 'https://phimimg.com/upload/vod/20231117-1/5ff10d0616b5e16eb04a498ea6058f4f.jpg', 'https://phimimg.com/upload/vod/20231117-1/8c86c1b84866a08246f9dae81af45ee2.jpg', '<p>Trong một thế giới không ai nói dối, một kịch bản gia có được danh tiếng và tiền bạc, và có thể là cả cô gái trong mơ của mình, bằng cách nói những điều không đúng.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ricky Gervais","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Louis C.K.","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"Rob Lowe","avatar":""},{"name":"Tina Fey","avatar":""},{"name":"Donna Sorbello","avatar":""},{"name":"Stephanie March","avatar":""},{"name":"Ruben Santiago-Hudson","avatar":""},{"name":"John Hodgman","avatar":""},{"name":"Nate Corddry","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Christopher Gues","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
