INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-lung-diet', 'Cổ Máy Lùng Diệt', 'Screamers: The Hunting', 'https://phimimg.com/upload/vod/20231117-1/81a989366d2408ef185a6218545d11c4.jpg', 'https://phimimg.com/upload/vod/20231117-1/0ac877343d16e1015235bd3b19e581c7.jpg', '<p>Cổ Máy Lùng Diệt - Screamers: The Hunting là một bộ phim khoa học viễn tưởng đầy kinh hoàng năm 1995 của đạo diễn Cristian Duguay. Mười ba năm trước, dân số trên hành tinh Sirius 6B đã hoàn toàn bị xóa sổ. Khi một tín hiệu nguy cấp từ Sirus 6B đến Trái Đất, một nhóm nhân viên cứu hộ được ra lệnh tìm hiểu xem bằng cách nào một thuộc địa của con người đã mất từ lâu có thể tránh và sống sót khỏi tay bọn robot. Và mọi chuyện dường như chỉ mới bắt đầu...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gina Holden","avatar":""},{"name":"Jana Pallaske","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Christopher Redman","avatar":""},{"name":"Tim Rozon","avatar":""},{"name":"Dave Lapommeray","avatar":""},{"name":"Jody Richardson","avatar":""},{"name":"Stephen Amell","avatar":""},{"name":"Lynley Hall","avatar":""},{"name":"Holly Uloth","avatar":""},{"name":"Darryl Hopkins","avatar":""},{"name":"Stephen Dunn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324478);
