INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-scooby-doo-bong-ma-trong-nha-hoang', 'Chú Chó Scooby Doo: Bóng Ma Trong Nhà Hoang', 'Scooby-Doo! The Mystery Begins', 'https://phimimg.com/upload/vod/20231115-1/53bd7f96429b82a6c6b006b7df21c03a.jpg', 'https://phimimg.com/upload/vod/20231115-1/92f504a7d708a16032c64fc75fc33b93.jpg', '<p>Câu chuyện xoanh quanh nguồn gốc Ngôi trường Bí mật Mystery. Trước khi trở thành những người bạn, những thành viên của Mystery, sống trong những vòng tròn xã giao riêng biệt. Duy nhất khi Fred, Daphne, Velma và Shaggy, cùng với chú chó Scooby Doo của Shaggy tìm thấy chủ nhân của việc phá hoại một cách ngu xuẩn trường học của họ và phát hiện ra sự thật về Coolsville lai vãng.</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Palatas","avatar":""},{"name":"Hayley Kiyoko","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Kate Melton","avatar":""},{"name":"Benita Ha","avatar":""},{"name":"Shawn Macdonald","avatar":""},{"name":"C. Ernst Harth","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Kurt Evans","avatar":""},{"name":"Kira Clavell","avatar":""},{"name":"Lorena Gale","avatar":""},{"name":"Christopher Attadia","avatar":""},{"name":"Jordana Largy","avatar":""},{"name":"Leah James","avatar":""},{"name":"David Hurtubise","avatar":""},{"name":"Dee Jay Jackson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324478);
