INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-cho-scooby-doo-bong-ma-trong-nha-hoang', 'Chú Chó Scooby Doo: Bóng Ma Trong Nhà Hoang', 'Scooby-Doo! The Mystery Begins', 'chú chó scooby doo: bóng ma trong nhà hoang scooby-doo! the mystery begins nick palatas hayley kiyoko frank welker robbie amell kate melton benita ha shawn macdonald c. ernst harth garry chalk kurt evans kira clavell lorena gale christopher attadia jordana largy leah james david hurtubise dee jay jackson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cheri', 'Chuyện Tình Cheri', 'Chéri', 'https://phimimg.com/upload/vod/20231115-1/f86cf6104b45826aa64da8b4dbc49c75.jpg', 'https://phimimg.com/upload/vod/20231115-1/2d1ff31689b89fe1d88a18d14d1591a8.jpg', '<p>Một bộ phim hài kịch tính xa hoa lấy bối cảnh ở Pháp vào cuối thế kỷ 19, trong thời kỳ Belle Epoque, thời kỳ dư thừa văn hóa và xã hội trong tầng lớp thượng lưu châu Âu chỉ kết thúc khi Chiến tranh thế giới thứ nhất nổ ra.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Pfeiffer","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Iben Hjejle","avatar":""},{"name":"Frances Tomelty","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Hubert Tellegen","avatar":""},{"name":"Joe Sheridan","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Alain Churin","avatar":""},{"name":"Bette Bourne","avatar":""},{"name":"Nichola McAuliffe","avatar":""},{"name":"András Hámori","avatar":""},{"name":"Gaye Brown","avatar":""},{"name":"Natasha Cashman","avatar":""},{"name":"Rollo Weeks","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
