INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-len', 'Vươn Lên', 'Precious', 'https://phimimg.com/upload/vod/20231114-1/57e112ede5c03868f71e2804f8b926a0.jpg', 'https://phimimg.com/upload/vod/20231114-1/e2850cf2b74c35e29ec79fe482765fe6.jpg', '<p>Là một bộ phim độc lập gây được tiếng vang lớn tại Liên hoan phim Sundance 2009, Precious (Vươn lên) được chuyển thể từ cuốn tiểu thuyết Push của Sapphire. Phim là câu chuyện kể về Precious - một cô gái da đen bị chính cha đẻ của mình lạm dụng tình dục và mang thai đứa con thứ hai của ông ta. Cô còn bị mẹ đẻ của mình ngược đãi, bị mọi người xa lánh vì ngoại hình quá khổ và học vấn thấp kém. Cuộc sống đầy tăm tối và nghiệt ngã, nhưng Precious chưa bao giờ thôi hy vọng vào một tương lai tươi sáng. Chính nghị lực tuyệt vời đã giúp cô gái trẻ vượt qua mọi khó khăn của cuộc sống...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabourey Sidibe","avatar":""},{"name":"Mo''Nique","avatar":""},{"name":"Paula Patton","avatar":""},{"name":"Mariah Carey","avatar":""},{"name":"Lenny Kravitz","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"Stephanie Andujar","avatar":""},{"name":"Chyna Layne","avatar":""},{"name":"Amina Robinson","avatar":""},{"name":"Xosha Roquemore","avatar":""},{"name":"Angelic Zambrana","avatar":""},{"name":"Aunt Dot","avatar":""},{"name":"Nealla Gordon","avatar":""},{"name":"Grace Hightower","avatar":""},{"name":"Barret Helms","avatar":""},{"name":"Kimberly Russell","avatar":""},{"name":"Bill S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
