INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-thu-cua-mot-tin-do-shopping', 'Tự Thú Của Một Tín Đồ Shopping', 'Confessions of a Shopaholic', 'https://phimimg.com/upload/vod/20231114-1/c685f2279f6cb6a9675e84f7a0eecdd1.jpg', 'https://phimimg.com/upload/vod/20231114-1/2b699268967d835af55603383a309b13.jpg', '<p>Đấu tranh với nỗi ám ảnh suy nhược của cô ấy với việc mua sắm và sự sụp đổ bất ngờ của nguồn thu nhập của cô ấy, Rebecca Bloomwood (Isla Fisher) đã vô tình đáp ứng một công việc viết cho một tạp chí tài chính sau khi trộn thư-gửi thư say rượu. Trớ trêu thay về sự thận trọng của người tiêu dùng mà cô đã không tuân theo, so sánh sáng tạo của Rebecca và những phép ẩn dụ khác nhau về kinh tế cấp sự hoan nghênh tới hạn, thành công của công chúng, và sự ngưỡng mộ của ông chủ hỗ trợ của cô Luke Brandon (Hugh Dancy). Nhưng khi cô ấy rút lại gần mục tiêu viết cuối cùng của mình là viết tạp chí thời trang nổi tiếng Alette, cô ấy đặt câu hỏi về tham vọng thực sự của mình và phải xác định xem sự khắc phục tình trạng &quot;shopaholic&quot; của cô ấy sẽ mang lại hạnh phúc thực sự của cô ấy</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isla Fisher","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Krysten Ritter","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"John Goodman","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Lynn Redgrave","avatar":""},{"name":"Robert Stanton","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Nick Cornish","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"Clea Lewis","avatar":""},{"name":"Stephen Guarino","avatar":""},{"name":"Tuomas Hiltunen","avatar":""},{"name":"Yos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
