INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-tuoi-teen', 'Tình Tuổi Teen', 'Adventureland', 'https://phimimg.com/upload/vod/20231114-1/f50fd6727fdbe9211f7c2e2a11d982ce.jpg', 'https://phimimg.com/upload/vod/20231114-1/4d27c91abedc92e08a8b97e67606acd8.jpg', '<p>Vào mùa hè năm 1987, James Brennan (Jesse Eisenberg), một sinh viên vừa tốt nghiệp đang háo hức chuẩn bị cho chuyến đi du lịch đến Châu Âu. Nhưng khi bố mẹ James (Wendie Malick và Jack Gilpin) thông báo rằng họ sẽ không tài trợ cho chuyến đi đó, James đã không còn sự lựa chọn nào khác ngoài việc nhận một công việc đáng chán tại công viên giải trí địa phương. Cố gắng quên đi giấc mơ về những món bia Đức, các bảo tàng nổi tiếng thế giới cũng như những cô gái Pháp mỹ miều - kỳ nghỉ hè của James bây giờ là công viên giải trí với bọn trẻ la hét đùa giỡn. Nhưng may mắn thay, kỳ hè tệ hại nhất này lại dường như trở thành một chuyến phiêu lưu thú vị khi James phải lòng cô đồng nghiệp quyến rũ Em (Kristen Stewart).</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Jack Gilpin","avatar":""},{"name":"Josh Pais","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"Mary Birdsong","avatar":""},{"name":"Matt Bush","avatar":""},{"name":"Paige Howard","avatar":""},{"name":"Dan Bittner","avatar":""},{"name":"Barret Hackney","avatar":""},{"name":"Michael Zegen","avatar":""},{"name":"Kimisha Renee Davis","avatar":""},{"name":"Van","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324478);
