INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-tot', 'Những Người Tốt', 'The Good Guy', 'https://phimimg.com/upload/vod/20231113-1/88d9b0519b1cd8a6718fe43fbc7a2197.jpg', 'https://phimimg.com/upload/vod/20231113-1/28dcfee1865de0c0ad6524aa964f2e5d.jpg', '<p>Cô gái trẻ đầy tham vọng Manhattanite và nhà bảo tồn đô thị Beth muốn có tất cả: một công việc tốt, những người bạn tốt và một chàng trai tốt để cùng chia sẻ thành phố. Tất nhiên cái cuối cùng đó thường là cái khó nhất trong tất cả. Beth phải lòng Tommy, một chàng trai hấp dẫn, trẻ trung ở Phố Wall. Nhưng ngay khi mọi thứ dường như đang đi vào quỹ đạo, thì những rắc rối lại nảy sinh khi người đồng nghiệp đẹp trai và nhạy cảm của Tommy là Daniel. Beth sớm biết rằng trò chơi tình ái ở thành phố lớn rất giống với Phố Wall - rủi ro cao, phần thưởng cao và mỗi người đều có một góc độ.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexis Bledel","avatar":""},{"name":"Scott Porter","avatar":""},{"name":"Bryan Greenberg","avatar":""},{"name":"Aaron Yoo","avatar":""},{"name":"Anna Chlumsky","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"Andrew McCarthy","avatar":""},{"name":"Kate Nauta","avatar":""},{"name":"Trini Alvarado","avatar":""},{"name":"Christine Evangelista","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
