INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-qua-dien-thoai', 'Chuyện Tình Qua Điện Thoại', 'Easier with Practice', 'https://phimimg.com/upload/vod/20231113-1/d816e576b6801444c519458820c699c0.jpg', 'https://phimimg.com/upload/vod/20231113-1/ebadb54a7012571e3f3aaebe6aa9939e.jpg', '<p>Chuyện Tình Qua Điện Thoại - Easier With Practice kể về mối quan hệ kỳ lạ của Davy Mitchell. Một buổi tối trong chuyến đi quảng bá cho cuốn tiểu thuyết chưa được công bố, Davy nhận được một cuộc điện thoại ngẫu nhiên từ một người phụ nữ bí ẩn tên Nicole. Họ bắt đầu một mối quan hệ hài hước và thân mật khiến Davy rất hạnh phúc. Tuy nhiên, cuối cùng, Davy phải đối mặt với không chỉ sự thật về mối quan hệ của họ mà còn về chính mình.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Geraghty","avatar":""},{"name":"Kel O''Neill","avatar":""},{"name":"Marguerite Moreau","avatar":""},{"name":"Jeanette Brox","avatar":""},{"name":"Jenna Gavigan","avatar":""},{"name":"Katie Aselton","avatar":""},{"name":"Eugene Byrd","avatar":""},{"name":"Lance Capaldi","avatar":""},{"name":"Lucas CorVatta","avatar":""},{"name":"Jamie Haqqani","avatar":""},{"name":"Allison Hensel","avatar":""},{"name":"Tracey Horsley","avatar":""},{"name":"Danielle Lozeau","avatar":""},{"name":"Emelie O''Hara","avatar":""},{"name":"Lauren Petzke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
