INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-hoi-ma-quy', 'Lễ Hội Ma Quỷ', 'Stan Helsing', 'https://phimimg.com/upload/vod/20231112-1/c5b1c7b45d805f6fc7339310f7fe095e.jpg', 'https://phimimg.com/upload/vod/20231112-1/6db90db1ffc31f6f2d47aef6e40e4213.jpg', '<p>Đó là đêm Halloween và nhân viên cửa hàng video Stan Helsing vừa gặp khó khăn với một yêu cầu vào phút cuối để cung cấp một số video. Với người bạn thân nhất của mình, cuộc hẹn của người bạn thân nhất và cô bạn gái cũ nóng bỏng đang hút thuốc đang chờ dự tiệc, Stan thuyết phục họ thực hiện một chuyến đi phụ đến Stormy Night Estates để thả thính. Nhưng cả nhóm bị nhốt bên trong và Stan phát hiện ra mình thực ra là Stan Van Helsing, hậu duệ của</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Steve Howey","avatar":""},{"name":"Diora Baird","avatar":""},{"name":"Leslie Nielsen","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Tara Wilson","avatar":""},{"name":"Ben Cotton","avatar":""},{"name":"Ildiko Ferenczi","avatar":""},{"name":"Desi Lydic","avatar":""},{"name":"Elysia Rotaru","avatar":""},{"name":"Zorianna Kit","avatar":""},{"name":"Denise Poole","avatar":""},{"name":"Kathryn Kirkpatrick","avatar":""},{"name":"Twan Holliday","avatar":""},{"name":"Alain Chanoine","avatar":""},{"name":"Charles Zuckermann","avatar":""},{"name":"Lara Babalola","avatar":""},{"name":"Jeff Gulka","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324478);
