INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-nguy-hiem', 'Trò Chơi Nguy Hiểm', 'Gamer', 'https://phimimg.com/upload/vod/20231111-1/c0cb20bd8ff4dab118d4498839f3f6f3.jpg', 'https://phimimg.com/upload/vod/20231111-1/cfe40c9188812c7b7e1d5161e959a9f9.jpg', '<p>Công nghệ kiểm soát tâm trí đã gây bão trong xã hội, một trò chơi trực tuyến nhiều người chơi có tên &quot;Slayers&quot; cho phép người chơi điều khiển tù nhân con người trên quy mô lớn. Simon điều khiển Kable, nhà vô địch trực tuyến của trò chơi. Thử thách cuối cùng của Kable là giành lại danh tính và sự độc lập của mình bằng cách đánh bại kẻ chủ mưu của trò chơi.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Amber Valletta","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Alison Lohman","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Ramsey Moore","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Johnny Whitworth","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"James Roday Rodriguez","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Aaron Yoo","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Zoë Bell","avatar":""},{"name":"Ashley Rickards","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324478);
