INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-trinh-tham-xinh-dep', 'Nữ Trinh Thám Xinh Đẹp', 'My Girlfriend Is an Agent', 'https://phimimg.com/upload/vod/20231111-1/23a075eaa5dd9fba41a8d1c57a8ffb57.jpg', 'https://phimimg.com/upload/vod/20231111-1/356e720da0350c470b769c420e5f45ff.jpg', '<p>Cải trang là một nhân viên du lịch, Suji thật sự lại là một điệp viên với sáu năm kinh nghiệm, người không thể để lộ thân phận của mình cho bạn trai Jae Joon biết. Sau những lần nói dối, Jae Joon quyết định nói lời chia tay, rời xa Suji và để cô một mình với nỗi buồn. Ba năm sau, trong một lần cải trang thành một nhân viên lau dọn, cô tình cờ gặp lại Jae Joon. Anh trở thành một kế toán viên quốc tế. Sự tình cờ này đưa Suji trở về với những kỷ niệm của tình yêu. Jae Joon đã mệt mỏi về những lời nói dối của bạn gái mình. Trong một cuộc điện thoại, anh nói với Suji rằng anh sẽ rời Hàn Quốc để đến Nga học.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ha-neul","avatar":""},{"name":"Kang Ji-hwan","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Jeong Woo-hyuk","avatar":""},{"name":"Kim Jung-pal","avatar":""},{"name":"Son Ho-seung","avatar":""},{"name":"Lee Kyung-Hoon","avatar":""},{"name":"Lee Joon-won","avatar":""},{"name":"Yoon Byung-hee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324478);
