INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('afro-samurai-resurrection', 'Afro Samurai: Resurrection', 'Afro Samurai: Resurrection', 'https://phimimg.com/upload/vod/20231111-1/d7042110b72f0743f29ca7076dbfb37a.jpg', 'https://phimimg.com/upload/vod/20231111-1/63451b4eb7dfdd5e546804e5d74fe46b.jpg', '<p>Afro Samurai trả thù cho cha mình và tìm thấy cuộc sống bình yên. Nhưng bậc thầy huyền thoại bị ép quay trở lại trò chơi bởi một người phụ nữ xinh đẹp và chết chóc trong quá khứ của anh ta. Những tia lửa bạo lực rơi dọc theo con đường đẫm máu của Afro giờ đã vượt khỏi tầm kiểm soát - và không nơi nào ngọn lửa hận thù dữ dội hơn trong mắt Sio.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"S. Scott Bullock","avatar":""},{"name":"Greg Eagles","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Dave Wittenberg","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Liam O''Brien","avatar":""},{"name":"Zachary Gordon","avatar":""},{"name":"Phil LaMarr","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"RZA","avatar":""},{"name":"Ariel Winter","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324478);
