INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-thanh', 'Phong Thanh', 'The Message', 'https://phimimg.com/upload/vod/20231110-1/b37f65168ce39a71cc2b2167bf2b3583.jpg', 'https://phimimg.com/upload/vod/20231110-1/a8473546300b8b479a928a41e21f078b.jpg', '<p>Bối cảnh của phim được lấy vào năm 1942 tại Nam Kinh, thời điểm mà lãnh thổ Trung Quốc đang bị quân đội Nhật Bản chiếm đóng và kiểm soát. Sau một loạt vụ ám sát nhằm vào quan chức chính phủ bù nhìn của Nhật Bản, một viên tướng Nhật tên là Takeda (Huỳnh Hiểu Minh) đã tung tin tức giả hòng dụ bắt một nhóm những kẻ bị tình nghi là nội gián về ngôi biệt thự Cầu Trang để tra hỏi. Bắt đầu từ đó, 2 bên khởi động trò chơi “mèo vờn chuột” đầy căng thẳng khi mà một điệp viên cộng sản Trung Quốc có mật danh “Lão Quỷ” đang cố gắng đưa tin tình báo ra ngoài để bảo vệ tổ chức của mình…</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Xun","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"Alec Su","avatar":""},{"name":"Ying Da","avatar":""},{"name":"Shi Zhaoqi","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Zhu Xu","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Ai Dai","avatar":""},{"name":"Zhang Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
