INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cap-gap-ong-gia', 'Kẻ Cắp Gặp Ông Già', 'Thick as Thieves', 'https://phimimg.com/upload/vod/20231110-1/b88f0cc1ceb4ca01d730b141ac6e349b.jpg', 'https://phimimg.com/upload/vod/20231110-1/cee3ea13131688f29f47b7cd6c2fc1b7.jpg', '<p>Keith Ripley (Morgan Freeman), một tên trộm chuyên nghiệp, là vị khách quen thuộc của các bảo tàng lớn trên thế giới, đang đi tìm cộng sự cùng mình thực hiện một phi vụ đặc biệt để trả nợ cho ông trùm mafia Nga.Sau nhiều năm, Ripley đã tìm được kẻ đồng hành, đó là tên cướp kim cương nổi tiếng ở Miami, Gabriel (Antonio Banderas), cả hai cùng nhận nhiệm vụ cướp hai quả trứng bảo vật được chế tác từ năm 1916, thuộc về công chúa Czarina Alexandra.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Michael Hayden","avatar":""},{"name":"Marcel Iureș","avatar":""},{"name":"Gary Werntz","avatar":""},{"name":"Gerrit Vooren","avatar":""},{"name":"Joshua Rubin","avatar":""},{"name":"Ivan Petrushinov","avatar":""},{"name":"Victor Boichev","avatar":""},{"name":"Nickolay Hadjiminev","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Marianne Stanicheva","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324478);
