INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-tra-thu', 'Đặc Vụ Trả Thù', 'Black Dynamite', 'https://phimimg.com/upload/vod/20231109-1/635796e861f5513eee75dd35348fb055.jpg', 'https://phimimg.com/upload/vod/20231109-1/83651f1a5c5af17a5d8fbe4129ec87cc.jpg', '<p>Black Dynamite, một đặc vụ CIA nguyện cống hiến hết mình để làm trong sạch khu phố sau khi anh trai mình bị giết bởi một tổ chức mờ ám. OLeary đồng nghiệp cũ của Black Dynamite cố gắng thuyết phục anh trở lại CIA bởi vì họ không muốn anh cố trả thù...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Arsenio Hall","avatar":""},{"name":"Tommy Davidson","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Richard Edson","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Buddy Lewis","avatar":""},{"name":"Irwin Keyes","avatar":""},{"name":"Miguel A. Núñez Jr.","avatar":""},{"name":"Nicole Ari Parker","avatar":""},{"name":"Salli Richardson-Whitfield","avatar":""},{"name":"John Salley","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Nicole Sullivan","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Ced","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324478);
