INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-2009', 'Người Bảo Vệ', 'The Keeper', 'https://phimimg.com/upload/vod/20231110-1/fd04a3135a4835d5a8aa1a1a068f2519.jpg', 'https://phimimg.com/upload/vod/20231110-1/24c231e16dc08a28d4189b879eb71987.jpg', '<p>Người Bảo Vệ - The Keeper: Roland Sallinger là một viên cảnh sát mẫn cán và tài ba của sở cảnh sát Los Angeles. Vì bị một đồng nghiệp móc nối với tội phạm gài bẫy, Roland bị thương nặng và bị cắt chức trong sự ấm ức. Nhận được một hợp đồng bảo vệ thân nhân từ một đồng nghiệp cũ, nay là một doanh nhân thành đạt Roland bay tới San Antonio, Texas để bảo vệ con gái ông ta khỏi tay bọn bắt cóc ...</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Liezl Carstens","avatar":""},{"name":"Arron Shiver","avatar":""},{"name":"Johnnie Hector","avatar":""},{"name":"Steph DuVall","avatar":""},{"name":"Luce Rains","avatar":""},{"name":"Kevin Wiggins","avatar":""},{"name":"Trine Christensen","avatar":""},{"name":"Tomas Sanchez","avatar":""},{"name":"Rio Alexander","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Charlie B. Brown","avatar":""},{"name":"Seri DeYoung","avatar":""},{"name":"David Manzanares","avatar":""},{"name":"Angela Serrano","avatar":""},{"name":"Patrick Mulderrig","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324478);
