INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-quai-woochi', 'Tiểu Quái Woochi', 'Woochi', 'https://phimimg.com/upload/vod/20231109-1/d5c8640bcdc6fa7c5990b9cc0a8229d7.jpg', 'https://phimimg.com/upload/vod/20231109-1/6cd22bd09bd40447863268a5429b2d96.jpg', '<p>Bộ phim xoay quanh cuộc đấu tranh của một pháp sư với các yêu tinh, đặc biệt miêu tả hình ảnh hiệp khách chuyên đi trừng trị bọn quan tham vô lại. 500 năm trước, Jeon Woo Chi bị hãm hại, phải chịu oan ức và bị nhốt trong một bức tranh. Tới 500 năm sau vào thời hiện đại, Jeon Woo Chi mới được thả ra và lại tiếp tục câu chuyện đấu tranh với lũ yêu tinh thời hiện đại.</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gang Dong-won","avatar":""},{"name":"Kim Yoon-seok","avatar":""},{"name":"Lim Soo-jung","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Sun Woo-sun","avatar":""},{"name":"Gong Jeong-hwan","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Kim Hyo-jin","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Yeon-su Seo","avatar":""},{"name":"Park Min-gyu","avatar":""},{"name":"Ji-hyeok Min","avatar":""},{"name":"Yeong-jin Sin","avatar":""},{"name":"Jong-gu Yun","avatar":""},{"name":"Hy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324479);
