INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-quai-woochi', 'Tiểu Quái Woochi', 'Woochi', 'tiểu quái woochi woochi gang dong-won kim yoon-seok lim soo-jung yoo hae-jin song young-chang ju jin-mo kim sang-ho sun woo-sun gong jeong-hwan baek yoon-sik yum jung-ah kim hyo-jin kwon tae-won yeon-su seo park min-gyu ji-hyeok min yeong-jin sin jong-gu yun hy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-cung-ung-thu', 'Sống Cùng Ung Thư', 'My Sister''s Keeper', 'https://phimimg.com/upload/vod/20231109-1/28a794ddb2754f19e20b808bf876296f.jpg', 'https://phimimg.com/upload/vod/20231109-1/ca2934aeb0273ba1a36943c8c6ff3548.jpg', '<p>Cuộc sống của Sara và Brian Fitzgerald với cậu con trai nhỏ và con gái hai tuổi, Kate, đã bị đảo lộn hoàn toàn khi họ biết được Kate mắc bệnh máu trắng. Hy vọng duy nhất của đôi vợ chồng này là sinh một đứa con khác với mục đích lấy tủy và máu để cứu sống Kate. Và với mục đích đó, Anna - cô con gái út của họ chào đời. Anna được thụ tinh trong ống nghiệm với kỹ thuật gien để máu từ dây rốn của cô bé có thể dùng để cấy vào người cô chị Kate. Sau này, tủy của Anna có thể được sử dụng để điều trị bệnh cho Kate. Nói chính xác là mạng sống của Kate được duy trì với máu và tủy của Anna. Suốt cuộc đời của hai chị em đều phải trải qua nhiều cuộc phẫu thuật và những ngày bất tận trong bệnh viện. Nhưng đến khi Anna 11 tuổi, cô bé từ chối việc hiến một quả thận của mình cho Kate và nhờ luật sư kiện cha mẹ mình. Vụ kiện của Anna có thể xé tan gia đình cô bé và đặt tính mạng của Kate vào tay số phận. Nhưng bằng những hình ảnh trở ngược lại quá khứ, My Sister&#39;s Keeper dần hé mở những bí mật sâu kín và đầy cảm động đằng sau hành động của bé Anna dũng cảm.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Sofia Vassilieva","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Emily Deschanel","avatar":""},{"name":"Heather Wahlquist","avatar":""},{"name":"Evan Ellingson","avatar":""},{"name":"Frank Cassavetes","avatar":""},{"name":"Nicole Marie Lenz","avatar":""},{"name":"Chris Kinkade","avatar":""},{"name":"Rick Salomon","avatar":""},{"name":"Frank Peluso","avatar":""},{"name":"Rico Simonini","avatar":""},{"name":"Keith Kraft","avatar":""},{"name":"Eliza","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
