INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-thuyen-am-nhac', 'Chiếc Thuyền Âm Nhạc', 'The Boat That Rocked', 'https://phimimg.com/upload/vod/20231108-1/fce1d828a16da94404f10797292ef4aa.jpg', 'https://phimimg.com/upload/vod/20231108-1/b0f966dc0f7ae28a683dfd086e46c112.jpg', '<p>The Boat That Rocked là một bộ phim hài tổng hợp, kể về câu chuyện tình lãng mạn giữa những người trẻ tuổi của thập niên 60 và nhạc pop. Phim kể về một ban nhạc DJ làm say đắm nước Anh, chơi thứ âm nhạc xác định một thế hệ và đứng lên chống lại một chính phủ muốn kiểm soát văn hóa đại chúng thông qua British Broadcasting Corporation. Dựa trên các sự kiện ở Anh vào những năm 60 khi chính phủ Lao động của Harold Wilson, muốn kiểm soát các đài phát thanh cướp biển, đủ để thấy việc thông qua Đạo luật Vi phạm Phát thanh Hàng hải vào ngày 15 tháng 8 năm 1967. Còn được gọi là &quot;Đài phát thanh cướp biển “.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Tom Sturridge","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"January Jones","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Katherine Parkinson","avatar":""},{"name":"Katie Lyons","avatar":""},{"name":"Tom Wisdom","avatar":""},{"name":"Will Adamsdale","avatar":""},{"name":"Tom Broo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
