INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-cuoi-ngot-ngao', 'Đám Cưới Ngọt Ngào', 'Wedding Fever In Campobello', 'https://phimimg.com/upload/vod/20231116-1/22d49972aeb9e4ac94033716e4499c42.jpg', 'https://phimimg.com/upload/vod/20231116-1/8268896c211406cb532484c5de6dabf6.jpg', '<p>Jan và Sara về gia đình xin tổ chức một đám cưới bình dị nhưng cha cô không đồng ý. Ông muốn tổ chức đám cưới ở miền Nam nước Ý. Vậy là cả gia đình cùng đến Campobello chuẩn bị. Biết bao nhiêu vấn đề xảy ra do sự xung đột văn hóa của 2 gia đình. Liệu cưới Sara có phải là điều đúng đắn không?</p>', 'Full', 1, 'single', 'completed', 21, 2009, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Lino Banfi","avatar":""},{"name":"Christian Ulmen","avatar":""},{"name":"Mina Tander","avatar":""},{"name":"Maren Kroymann","avatar":""},{"name":"Gundi Ellert","avatar":""},{"name":"Peter Prager","avatar":""},{"name":"Paolo De Vita","avatar":""},{"name":"Ludovica Modugno","avatar":""},{"name":"Martin Horn","avatar":""},{"name":"Jürgen Rißmann","avatar":""},{"name":"Marleen Lohse","avatar":""},{"name":"Leonardo Nigro","avatar":""},{"name":"Sergio Rubini","avatar":""},{"name":"Massimo Sarchielli","avatar":""},{"name":"Enzo Salomone","avatar":""},{"name":"Danilo De Summa","avatar":""},{"name":"Pierluigi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
