INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-39', 'Hồ Sơ 39', 'Case 39', 'https://phimimg.com/upload/vod/20231108-1/9366e535b3bb68a7f196c9e17b6346c2.jpg', 'https://phimimg.com/upload/vod/20231108-1/d57687518a71c87496eb0e97302af5ce.jpg', '<p>Một nhân viên công tác xã hội ngây thơ mang một đứa trẻ 10 tuổi về nhà để giải cứu cô bé khỏi cảnh bị bố mẹ ngược đãi, song nhận ra đứa bé không đơn giản như vẻ bề ngoài.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Adrian Lester","avatar":""},{"name":"Kerry O''Malley","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Cynthia Stevenson","avatar":""},{"name":"Alexander Conti","avatar":""},{"name":"Philip Cabrita","avatar":""},{"name":"Vanesa Tomasino","avatar":""},{"name":"Mary Black","avatar":""},{"name":"Domenico D''Ambrosio","avatar":""},{"name":"Benita Ha","avatar":""},{"name":"J. Winston Carrol","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
