INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-thinh-phong-van', 'Thiết Thính Phong Vân', 'Overheard', 'https://phimimg.com/upload/vod/20231108-1/4834058d14f6331cfe2acb569e9752c5.jpg', 'https://phimimg.com/upload/vod/20231108-1/33a2225b1271009fee498f22f2218873.jpg', '<p>Thiết Thính Phong Vân kể về một nhóm cảnh sát tình báo hình sự (C.I.B) cải trang thành các paparazi để đi dò la tin tức. Một lần, trong quá trình tác nghiệp, vài người trong số họ tình cờ nghe trộm được thông tin cổ phiếu nội bộ và hàng loạt câu chuyện phức tạp liên quan đến lòng tham bản năng của con người bắt đầu nảy sinh từ đó.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Ka Wah Lam","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Sharon Luk","avatar":""},{"name":"William Chan Wai-Ting","avatar":""},{"name":"Stephen Au Kam-Tong","avatar":""},{"name":"Queenie Chu","avatar":""},{"name":"Henry Fong","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Geoffrey Wong Chi-Hung","avatar":""},{"name":"Ben Yuen Foo-Wa","avatar":""},{"name":"Mat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
