INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-cuong-si', 'Những Kẻ Cuồng Si', 'Fanboys', 'https://phimimg.com/upload/vod/20231108-1/6242bc9709e22fc9dd3680b8e82552f4.jpg', 'https://phimimg.com/upload/vod/20231108-1/36e63bf75b994c4f70f1d41377ba8ddf.jpg', '<p>Năm 1999, những người hâm mộ Chiến tranh giữa các vì sao thực hiện một chuyến đi xuyên quốc gia đến Trang trại Skywalker của George Lucas để người bạn sắp chết của họ có thể xem buổi chiếu The Phantom Menace trước khi phát hành.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Huntington","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"David Denman","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Isaac Kappy","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Charlie B. Brown","avatar":""},{"name":"Tarek Bishara","avatar":""},{"name":"Stephen Pina","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Allie Grant","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Pell James","avatar":""},{"name":"Will","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
