INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chi-diem', 'Người Chỉ Điểm', 'The Informant!', 'https://phimimg.com/upload/vod/20231107-1/383de8671103c900b40e981cca879226.jpg', 'https://phimimg.com/upload/vod/20231107-1/b08add671a1f7e0cbcb705a300982b8b.jpg', '<p>Một ngôi sao đang lên tại gã khổng lồ công nghiệp nông nghiệp Archer Daniels Midland (ADM), Mark Whitacre đột nhiên trở thành người tố giác. Ngay cả khi vạch trần âm mưu ấn định giá xuyên quốc gia của công ty mình với FBI, Whitacre hình dung mình được ca ngợi như một anh hùng của người bình thường và được thăng chức.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Lucas McHugh Carroll","avatar":""},{"name":"Eddie Jemison","avatar":""},{"name":"Rusty Schwimmer","avatar":""},{"name":"Craig Ricci Shaynak","avatar":""},{"name":"Tom Papa","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Thomas F. Wilson","avatar":""},{"name":"Scott Bakula","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Allan Havey","avatar":""},{"name":"Howie Johnson","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Nick Craig","avatar":""},{"name":"Cody Puckett","avatar":""},{"name":"Andre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324479);
