INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nguoi-deu-on', 'Mọi Người Đều Ổn', 'Everybody''s Fine', 'https://phimimg.com/upload/vod/20231103-1/3d0cec3ca292be95a17509f3246f8ef2.jpg', 'https://phimimg.com/upload/vod/20231103-1/3c6fd9b4067f345d1d92e4602e88497f.jpg', '<p>Tám tháng sau cái chết của vợ, Frank Goode mong được đoàn tụ với bốn đứa con trưởng thành của mình. Khi tất cả họ hủy bỏ chuyến thăm vào phút cuối, Frank, trái với lời khuyên của bác sĩ, bắt đầu một chuyến đi để kết nối lại với con cái của mình. Khi lần lượt đến thăm từng người, Frank nhận thấy rằng cuộc sống của các con anh không hoàn toàn đẹp như tranh vẽ như chúng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Damian Young","avatar":""},{"name":"James Frain","avatar":""},{"name":"Katherine Moennig","avatar":""},{"name":"Brendan Sexton III","avatar":""},{"name":"James Murtaugh","avatar":""},{"name":"Austin Lysy","avatar":""},{"name":"Chandler Frantz","avatar":""},{"name":"Lily Mo Sheen","avatar":""},{"name":"Seamus Davey-Fitzpatrick","avatar":""},{"name":"Lucian Maisel","avatar":""},{"name":"Jason Harri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
