INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-hot-girl', 'Yêu Nhầm Hot Girl', 'I Love You, Beth Cooper', 'https://phimimg.com/upload/vod/20231103-1/e12bdd48a8c37ffc35e5e618316f4c41.jpg', 'https://phimimg.com/upload/vod/20231103-1/b691ebf80a24cdc991ed8232c0bff863.jpg', '<p>Một anh chàng mọt sách tuyên bố yêu cô gái nổi tiếng nhất trường - Beth Cooper - ngay trong bài diễn văn tốt nghiệp trung học. Hơn cả sự kinh ngạc, Beth tới trước cửa nhà anh chàng vào đêm đó và quyết định dành cho cậu bạn một đêm tuyệt nhất trong đời. Mọi chuyện bắt đầu rối tung từ đây!!!</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Hayden Panettiere","avatar":""},{"name":"Paul Rust","avatar":""},{"name":"Jack Carpenter","avatar":""},{"name":"Lauren London","avatar":""},{"name":"Lauren Storm","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Jared Keeso","avatar":""},{"name":"Brendan Penny","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Josh Emerson","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Cynthia Stevenson","avatar":""},{"name":"Pat Finn","avatar":""},{"name":"Andrea Savage","avatar":""},{"name":"Violet Columbus","avatar":""},{"name":"Anna Mae Routledge","avatar":""},{"name":"Anja Savcic","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
