INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-3', 'Lời Nguyền 3', 'The Grudge 3', 'https://phimimg.com/upload/vod/20231103-1/b0099db00bcfd51e7fdb768417a270bd.jpg', 'https://phimimg.com/upload/vod/20231103-1/b9ad0e82db23f857ecd0fd606e91a2ed.jpg', '<p>Tiếp theo của phần 1 và phần 2 của bộ phim kinh dị nổi tiếng của Nhật, kể về một người phụ nữ trẻ Nhật Bản có khả năng nắm giữ chìa khóa để có thể ngăn chặn linh hồn địa ngục không thể siêu thoát của Kayako .</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johanna Braddy","avatar":""},{"name":"Emi Ikehata","avatar":""},{"name":"Jadie-Rose Hobson","avatar":""},{"name":"Gil McKinney","avatar":""},{"name":"Beau Mirchoff","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Marina Sirtis","avatar":""},{"name":"Matthew Knight","avatar":""},{"name":"Aiko Horiuchi","avatar":""},{"name":"Shimba Tsuchiya","avatar":""},{"name":"Michael McCoy","avatar":""},{"name":"Takatsuna Mukai","avatar":""},{"name":"Laura Giosh","avatar":""},{"name":"Mihaela Nankova","avatar":""},{"name":"Takako Fuji","avatar":""},{"name":"Ohga Tanaka","avatar":""},{"name":"Takashi Mats","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
