INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-ac-quy', 'Thiên Thần & Ác Quỷ', 'Angels & Demons', 'https://phimimg.com/upload/vod/20231103-1/c77b8f112b3208ea6c2554b79c31e8f2.jpg', 'https://phimimg.com/upload/vod/20231103-1/a9323ee2de3b40f72dcb9efcfba4a090.jpg', '<p>Được chuyển thể từ tác phẩm cùng tên của Dan Brown, phim là phần tiếp theo của &quot;The Da Vinci Code&quot;, phát hành năm 2006 tuy câu truyện trong phim được diễn ra trước thời điểm xác định của &quot;The Da Vinci Code&quot;.Sau cái chết bí hiểm của nhà vật lý người Italia là Leonardo Vetra, giáo sư biểu tượng học Robert Langdon đến từ Harvard đã lên đường đến Vatican và gặp gỡ Vittoria Vetra – con gái của ông và cũng là một nhà khoa học xinh đẹp của tổ chức CERN để giải mã những ký hiệu để lại trên ngực nạn nhân.Những manh mối đã dẫn dắt họ tìm kiếm khắp nơi trong Tòa thánh, để dần phát hiện ra những dấu tích về một tổ chức ngầm khét tiếng trong quá khứ là nhóm “Người ngộ đạo”, cũng như những hiểm họa sắp diễn ra mà tổ chức này muốn ...</p>', 'Full', 1, 'single', 'completed', 20, 2009, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Ayelet Zurer","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"Nikolaj Lie Kaas","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Thure Lindhardt","avatar":""},{"name":"David Pasquesi","avatar":""},{"name":"Cosimo Fusco","avatar":""},{"name":"Victor Alfieri","avatar":""},{"name":"Franklin Amobi","avatar":""},{"name":"Curt Lowens","avatar":""},{"name":"Bob Yerkes","avatar":""},{"name":"Marc Fiorini","avatar":""},{"name":"Carmen Argenziano","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324479);
