INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-va-kho-bau-that-lac', 'Tinker Bell và Kho Báu Thất Lạc', 'Tinker Bell and the Lost Treasure', 'https://phimimg.com/upload/vod/20231103-1/cdccffcc1f99f419d012ec8c8bafb523.jpg', 'https://phimimg.com/upload/vod/20231103-1/4e973da1111ca75888fa3d32bc072372.jpg', '<p>Tinker Bell là một nàng tiên nhỏ bé có nhiệm vụ mang lại sự giao mùa: Đổi màu lá, mang tia nắng tới làm tan tuyết, đánh thức loài vật từ giấc ngủ đông hoặc tưới tia nước mát cho mầm xanh vươn lên. Cảm thấy công việc của mình không quan trọng bằng những nàng tiên khác, Tinker Bell cố gắng thay đổi bản thân nhưng điều đó chỉ mang lại các thảm họa.Với sự khích lệ từ những người bạn Rosetta, Silvermist, Fawn và Iridessa, Tink hiểu rằng bí quyết hóa giải các khó khăn trong cuộc sống nằm ngay trong những khả năng sẵn có độc đáo của mình. Và cô cũng đồng thời hiểu ra chân lý: Khi ta thành thật với bản thân, có thể những điều kỳ diệu sẽ đến.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2009, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mae Whitman","avatar":""},{"name":"Jesse McCartney","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Angela Bartys","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Eliza Pollack Zebert","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Allison Roth","avatar":""},{"name":"Thom Adcox-H","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324479);
