INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-coco', 'Cuộc Đời Coco', 'Coco avant Chanel', 'https://phimimg.com/upload/vod/20231103-1/1c6ecb3fabef147bce349577e09ea3b0.jpg', 'https://phimimg.com/upload/vod/20231103-1/4fe78a68016978da5b78f9aa5d251b74.jpg', '<p>Vài năm sau khi rời trại trẻ mồ côi, nơi mà cha cô không bao giờ quay lại đón cô, Gabrielle Chanel thấy mình đang làm việc trong một quán bar tỉnh lẻ. Cô ấy vừa là thợ may cho các nghệ sĩ biểu diễn vừa là ca sĩ, lấy biệt danh là Coco từ bài hát mà cô ấy hát hàng đêm cùng chị gái. Mối liên hệ với Nam tước Balsan giúp cô có cơ hội hòa nhập vào xã hội Pháp và cơ hội phát triển năng khiếu thiết kế của mình.</p>', 'Full', 1, 'single', 'completed', 19, 2009, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Audrey Tautou","avatar":""},{"name":"Benoît Poelvoorde","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Marie Gillain","avatar":""},{"name":"Emmanuelle Devos","avatar":""},{"name":"Régis Royer","avatar":""},{"name":"Étienne Bartholomeus","avatar":""},{"name":"Yan Duffas","avatar":""},{"name":"Fabien Béhar","avatar":""},{"name":"Roch Leibovici","avatar":""},{"name":"Jean-Yves Chatelais","avatar":""},{"name":"Pierre Diot","avatar":""},{"name":"Vincent Nemeth","avatar":""},{"name":"Bruno Abraham-Kremer","avatar":""},{"name":"Lisa Cohen","avatar":""},{"name":"Inès Bes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324479);
