INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-doi-coco', 'Cuộc Đời Coco', 'Coco avant Chanel', 'cuộc đời coco coco avant chanel audrey tautou benoît poelvoorde alessandro nivola marie gillain emmanuelle devos régis royer étienne bartholomeus yan duffas fabien béhar roch leibovici jean-yves chatelais pierre diot vincent nemeth bruno abraham-kremer lisa cohen inès bes ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-mong-chon-thien-duong', 'Vỡ Mộng Chốn Thiên Đường', 'Couples Retreat', 'https://phimimg.com/upload/vod/20231103-1/71ab97422d500e212b53c72c70164466.jpg', 'https://phimimg.com/upload/vod/20231103-1/4b42f27cfd75e28aeae6d5971122887e.jpg', '<p>Sau gần tám năm vui vẻ bên nhau, Jason và Cynthia bất ngờ gây sững sốt cho bạn bè khi tuyên bố sắp sửa ly dị. Và để cứu vãn cuộc hôn nhân này, hai người quyết định làm một chuyến du lịch xa hoa cuối cùng đến Eden Resort, một hòn đảo thiên đường nhiệt đới tại Nam Thái Bình Dương, nơi nổi tiếng với những liệu pháp mạnh mẽ chuyên giải quyết các vấn đề lứa đôi. Để có tiền trang trải chi phí cho chuyến du lịch này, cả hai cùng rủ nhóm bạn thân của mình tham gia với suy nghĩ “đôi bên cùng có lợi”: Trong khi hai người hòa giải, nhóm bạn của họ sẽ vui chơi trên bãi biển cát trắng trải đầy nắng vàng, thư giãn trong các phòng spa, chơi lưới sóng và tận hưởng. Tuy nhiên, mọi việc không chỉ đơn giản như vậy...</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Faizon Love","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Carlos Ponce","avatar":""},{"name":"Tasha Smith","avatar":""},{"name":"Kali Hawk","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Jonna Walsh","avatar":""},{"name":"Gattlin Griffith","avatar":""},{"name":"Colin Baiocchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
