INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-nghiem-tuc', 'Người Đàn Ông Nghiêm Túc', 'A Serious Man', 'https://phimimg.com/upload/vod/20231103-1/b9a91af68e3dc27b46fdc5e1952c335d.jpg', 'https://phimimg.com/upload/vod/20231103-1/38cdf049624f01e7e95058574508fd4f.jpg', '<p>Đang đứng trước một thảm cảnh: người anh bệnh nằm ăn vạ, người vợ tiêu tiền của mình nhưng lại ăn nằm với người khác, 2 đứa con hư hỏng luôn tìm cách ăn cắp tiền của mình để tiêu xài hoang phí, còn bản thân mình thì đang mơ tưởng đến cô hàng xóm,... bạn sẽ phải làm gì khi đứng trước một thảm cảnh như thế.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Stuhlbarg","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Fred Melamed","avatar":""},{"name":"Sari Lennick","avatar":""},{"name":"Aaron Wolff","avatar":""},{"name":"Jessica McManus","avatar":""},{"name":"Adam Arkin","avatar":""},{"name":"George Wyner","avatar":""},{"name":"Peter Breitmayer","avatar":""},{"name":"Brent Braunschweig","avatar":""},{"name":"David Kang","avatar":""},{"name":"Jon Kaminski Jr.","avatar":""},{"name":"Ari Hoptman","avatar":""},{"name":"Alan Mandell","avatar":""},{"name":"Amy Landecker","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Katherine Bor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
