INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-dan-ong-nghiem-tuc', 'Người Đàn Ông Nghiêm Túc', 'A Serious Man', 'người đàn ông nghiêm túc a serious man michael stuhlbarg richard kind fred melamed sari lennick aaron wolff jessica mcmanus adam arkin george wyner peter breitmayer brent braunschweig david kang jon kaminski jr. ari hoptman alan mandell amy landecker simon helberg katherine bor ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-ban-gai-cu', 'Hồn Ma Bạn Gái Cũ', 'Ghosts of Girlfriends Past', 'https://phimimg.com/upload/vod/20231103-1/a2aa922d855ddcb45b277595035ce935.jpg', 'https://phimimg.com/upload/vod/20231103-1/ac036d358b8fd73797c2d38aa078c11c.jpg', '<p>Phim Hồn Ma Bạn Gái Cũ (2009) kể về Connor Mead, anh chàng nhiếp ảnh hào hoa chỉ yêu thích tự do, vui đùa và các cô gái. Luôn sống vô trách nhiệm, Connor cùng lúc yêu nhiều cô gái khác nhau như cách để chứng tỏ bản thân mình. Em trai Conner, Paul Mead là tuýp người trái ngược với anh trai mình. Anh có tâm hồn lãng mạn và chuẩn bị kết hôn. Conner coi đó là quyết định sai lầm và thuyết phục Paul hủy bỏ đám cưới. Ngay khi tất cả gần như đổ vỡ dưới bàn tay của Connor, anh bất ngờ nhận được lời nhắn gửi từ hồn ma của người chú Wayne – một hình mẫu lý tưởng mà Connor luôn cố gắng noi theo. Lời nhắn khẩn cấp của chú Wayne được truyền đạt thông qua hồn ma của những người bạn gái đã từng bị Connor bỏ rơi trong quá khứ, để anh nhìn lại sự thật về những mối quan hệ thất bại trong đời, quá khứ xấu xa, hiện thực tàn nhẫn, và tương lai cô độc của mình. Liệu anh còn có cơ hội trở lại bản chất tốt bụng, chân thành và tìm kiếm được tình yêu thật sự của đời mình hay không?</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Breckin Meyer","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Anne Archer","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"Noureen DeWulf","avatar":""},{"name":"Rachel Boston","avatar":""},{"name":"Camille Guaty","avatar":""},{"name":"Amanda Walsh","avatar":""},{"name":"Emily Baldoni","avatar":""},{"name":"Catherine Haena Kim","avatar":""},{"name":"Noa Tishby","avatar":""},{"name":"Chris","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
