INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tay-thien-phu-chuyen-ve-ben-carson', 'Đôi Tay Thiên Phú: Chuyền Về Ben Carson', 'Gifted Hands: The Ben Carson Story', 'https://phimimg.com/upload/vod/20231103-1/de08440e50d0247b08c0dd913c9df1c5.jpg', 'https://phimimg.com/upload/vod/20231103-1/163bbe018c1095f6ee35bb555d81febc.jpg', '<p>Dựa trên câu chuyện có thật, bộ phim này xoay quanh cuộc đấu tranh của Ben Carson để vượt qua muôn vàn trở ngại nhằm nghiên cứu y học và cứu người ở bệnh viện Johns Hopkins.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"Aunjanue Ellis-Taylor","avatar":""},{"name":"Harron Atkins","avatar":""},{"name":"Ele Bardha","avatar":""},{"name":"Loren Bass","avatar":""},{"name":"Geoffrey Beauchamp","avatar":""},{"name":"Tajh Bellow","avatar":""},{"name":"Lesley Bevan","avatar":""},{"name":"Jesse Christian","avatar":""},{"name":"Ron Coden","avatar":""},{"name":"Wayne David Parker","avatar":""},{"name":"Angela Dawe","avatar":""},{"name":"Gregory Dockery","avatar":""},{"name":"Zac Douglass","avatar":""},{"name":"Ithamar Enriquez","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
