INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-den-nui-phu-thuy', 'Cuộc Đua Đến Núi Phù Thủy', 'Race to Witch Mountain', 'https://phimimg.com/upload/vod/20231103-1/04d9b665aac16791fa10bd362c6c0809.jpg', 'https://phimimg.com/upload/vod/20231103-1/65dcd94d7a8dfe0933042264477e1fdb.jpg', '<p>Jack Bruno là một tài xế taxi tại thành phố Las Vegas. Một ngày nọ anh được yêu cầu đón 2 đứa trẻ Sarah và Seth, nhưng anh không ngờ rằng đây không phải là 2 đứa trẻ bình thường mà là 2 đứa trẻ ngoài hành tinh với sức mạnh siêu nhiên đặc biệt, đang chạy trốn khỏi một tổ chức muốn sử dụng 2 đứa trẻ để thực hiện các kế hoạch ác độc. Chính từ đây anh dấn thân vào một cuộc phiêu lưu kỳ thú và cuộc rượt đuổi đầy gay cấn.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Alexander Ludwig","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"John Kassir","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"Tom Everett Scott","avatar":""},{"name":"Kim Richards","avatar":""},{"name":"Meredith Salenger","avatar":""},{"name":"Billy Brown","avatar":""},{"name":"Tom Woodruff Jr.","avatar":""},{"name":"Bob Clendenin","avatar":""},{"name":"Robert Torti","avatar":""},{"name":"Garry Marshall","avatar":""},{"name":"Ike Eisenman","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911