INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-dua-voi-lua', 'Cô Gái Đùa Với Lửa', 'The Girl Who Played with Fire', 'https://phimimg.com/upload/vod/20231103-1/750cca441f874497b25c487984d86bcd.jpg', 'https://phimimg.com/upload/vod/20231103-1/6441c0dc150a27fc2ed54b4cda1d027b.jpg', '<p>Salander bị buộc tội giết 3 người và để chứng minh được mình vô tội, cô phải nhờ đến sự giúp đỡ của người yêu Mikael Blomkvist (Michael Nyqvist) - một nhà báo cánh tả hoàn toàn tin tưởng ở cô. Sử dụng những phương pháp khác biệt, Mikael đã nói chuyện với những nghi phạm, còn Lisbeth hack mạng máy tính lấy những thông tin cần thiết. Từ đó hai người đã tìm được những mối liên hệ bí mật giữa nhiều điệp viên, quan chức chính phủ, và những tay buôn bán phụ nữ quốc tế.</p>', 'Full', 1, 'single', 'completed', 23, 2009, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Michael Nyqvist","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Lena Endre","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"Annika Hallin","avatar":""},{"name":"Per Oscarsson","avatar":""},{"name":"Sofia Ledarp","avatar":""},{"name":"Micke Spreitz","avatar":""},{"name":"Georgi Staykov","avatar":""},{"name":"Paolo Roberto","avatar":""},{"name":"Yasmine Garbi","avatar":""},{"name":"Tanja Lorentzon","avatar":""},{"name":"Jacob Ericksson","avatar":""},{"name":"Magnus Krepper","avatar":""},{"name":"Reuben Sallmander","avatar":""},{"name":"Jennie Silfverhjelm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","