INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-trom-bao-tang', 'Băng Trộm Bảo Tàng', 'The Maiden Heist', 'https://phimimg.com/upload/vod/20231102-1/90ad622d243874860087532759566cca.jpg', 'https://phimimg.com/upload/vod/20231102-1/4d83526bf010e5fb662d7b94f1dd9111.jpg', '<p>Một bộ phim hài xoay quanh ba nhân viên bảo vệ bảo tàng lập kế hoạch đánh cắp các tác phẩm nghệ thuật mà họ đã rất gắn bó trước khi chúng bị chuyển đến một bảo tàng khác.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Philip Dorn Hebert","avatar":""},{"name":"Todd Weeks","avatar":""},{"name":"Bhavesh Patel","avatar":""},{"name":"Stephen Stapinski","avatar":""},{"name":"Breckin Meyer","avatar":""},{"name":"Wynn Everett","avatar":""},{"name":"Joseph McKenna","avatar":""},{"name":"Jim Chiros","avatar":""},{"name":"Bates Wilder","avatar":""},{"name":"Anthony Cascio","avatar":""},{"name":"Naheem Garcia","avatar":""},{"name":"Bart A. Piscite","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324479);
