INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-10-the-gioi-suc-manh', 'Đảo Hải Tặc 10: Thế Giới Sức Mạnh', 'One Piece: Strong World', 'https://phimimg.com/upload/vod/20231110-1/25ded6b407b3b8beecc513b114dac729.jpg', 'https://phimimg.com/upload/vod/20231110-1/2f338bbd60b6d289df842947627a27dd.jpg', '<p>Câu chuyện bắt đầu từ một nhân vật, &quot;Golden Leo&quot; - Shiki. Shiki vốn là một hải tặc vĩ đại sánh ngang tầm với Roger - &quot;Vua hải tặc&quot;. Trong suốt cuộc đời, Shiki luôn thích làm những &quot;điều vĩ đại và đáng sợ&quot;. Shiki và Roger từng trải qua nhiều trận thư hùng làm chấn động biển khơi trước khi Roger tự nộp mình cho hải quân. Hay tin Roger bị bắt, Shiki nổi cơn lôi đình, vì cho rằng mạng sống của Roger chỉ mình hắn được quyền lấy. Trong cơn tức giận, Shiki đã một mình đến căn cứ hải quân, giết vô số quân lính với mục đích tìm Roger. Ở đây, Shiki đã gặp Garp - Ông của Luffy, phó đô đốc huyền thoại của hải quân và Sengokou - người sau này trở thành Đại đô đốc thống lĩnh toàn bộ lực lượng hải quân. Trận thư hùng của 3 người diễn ra long trời lở đất? Ai sẽ là người chiến thắng? Hậu quả của cuộc chiến kéo dài sau 20 năm sẽ như thế nào?</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Cho","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Yasuhiro Takato","avatar":""},{"name":"Wasabi Mizuta","avatar":""},{"name":"Mika Doi","avatar":""},{"name":"Hisako Kyoda","avatar":""},{"name":"Tomoko Naka","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Hiro","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324479);
