INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-khong-gian-khong-lui-buoc', 'Đặc Vụ Không Gian: Không Lùi Bước', 'Evangelion: 2.0 You Can (Not) Advance', 'https://phimimg.com/upload/vod/20231102-1/8dd09b8e94cbbcaef9642a6361612f78.jpg', 'https://phimimg.com/upload/vod/20231102-1/4457681bc2ba2251c72b450f5cce16a1.jpg', '<p>Sau các đợt tấn công không dứt của Angel, NERV quyết định tiếp nhận thêm hai phi công mới đến hỗ trợ cho chiến dịch là Asuka Langley Shikinami, một cô bé mạnh mẽ đầy cá tính, và Makinami Mari Illustrous, một nữ phi công bí ẩn từng lập chiến công tiêu diệt hài cốt tái sinh của Angel thứ ba, Shamshel. Cùng với sự hỗ trợ của Asuka, công cuộc chống chọi các Angel trở nên nhẹ nhàng hơn và Ikari Shinji cũng đã bắt đầu quen dần với cuộc sống và mở lòng với mọi người. Để rồi một biến cố kinh hoàng xảy đến...</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Miki Nagasawa","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Hiro Yuuki","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Tetsuya Iwanaga","avatar":""},{"name":"Junko Iwao","avatar":""},{"name":"Mugihito","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
