INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-khong-gian-khong-lui-buoc', 'Đặc Vụ Không Gian: Không Lùi Bước', 'Evangelion: 2.0 You Can (Not) Advance', 'đặc vụ không gian: không lùi bước evangelion: 2.0 you can (not) advance megumi ogata megumi hayashibara yuko miyamura maaya sakamoto kotono mitsuishi yuriko yamaguchi koichi yamadera fumihiko tachiki motomu kiyokawa miki nagasawa takehito koyasu hiro yuuki tomokazu seki tetsuya iwanaga junko iwao mugihito ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-noi-thien-duong', 'Truy Sát Nơi Thiên Đường', 'A Perfect Getaway', 'https://phimimg.com/upload/vod/20231101-1/bea133dc38d9ebb9cdef7064a5f3945e.jpg', 'https://phimimg.com/upload/vod/20231101-1/5aefefba7c9eb637f990699b311c2b57.jpg', '<p>Cliff và Cydney là một đôi tình nhân trẻ ưa mạo hiểm, quyết định tổ chức tuần trăng mật của họ bằng một chuyến đi tới một trong những bãi biển đẹp nhưng hẻo lánh nhất ở Hawaii. Chu du trong sự hoang sơ và ẩn dật, họ tin rằng mình đã tìm thấy thiên đường đích thực. Cho đến khi họ gặp một nhóm khách du lịch với vẻ hoảng sợ, nói bóng gió về một vụ án mạng rùng rợn của một cặp vợ chồng mới cưới xảy ra trên đảo, họ mới bắt đầu nhận ra họ nên quay trở về nhà. Không chắc chắn rằng nên ở lại hay quay về thì họ gặp một đôi tình nhân khác, Nick và Gina, rồi cả bốn người cùng tiếp tục lên đường và mọi thứ bắt đầu trở thành sai lầm khủng khiếp. Ai trong số họ cũng bắt đầu trông giống như mối hiểm hoạ ...</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Zahn","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Kiele Sanchez","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Anthony Ruivivar","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Wendy Braun","avatar":""},{"name":"Peter Navy Tuiasosopo","avatar":""},{"name":"Jim Cruz","avatar":""},{"name":"Isaac Santiago","avatar":""},{"name":"Matt Birman","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324479);
