INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-sat-noi-thien-duong', 'Truy Sát Nơi Thiên Đường', 'A Perfect Getaway', 'truy sát nơi thiên đường a perfect getaway steve zahn milla jovovich timothy olyphant kiele sanchez chris hemsworth marley shelton holt mccallany anthony ruivivar dale dickey wendy braun peter navy tuiasosopo jim cruz isaac santiago matt birman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-la-duoc-viec', 'Miễn Là Được Việc', 'Whatever Works', 'https://phimimg.com/upload/vod/20231101-1/5e72f05d21a48aadb89e4a3060cb1e5d.jpg', 'https://phimimg.com/upload/vod/20231101-1/0cc60b4ccd9e41f9bffa93c12bcdb000.jpg', '<p>Một ông già lập dị bất ngờ gặp một mĩ nhân và phải lòng cô. Nhưng cặp đôi này, gia đình của cô gái và những người bạn ở New York của ông sẽ hòa hợp với nhau bằng cách nào? Bên cạnh việc chú ý tới nội dung và tính nghệ thuật thì người ta còn chú ý tới từng bộ phim của Woody Allen để xem ai là nàng thơ mới nhất của ông. Với Whatever works thì người đó chắc hẳn là Evan Rachel Wood.</p>', 'Full', 1, 'single', 'completed', 15, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Larry David","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Ed Begley Jr.","avatar":""},{"name":"Carolyn McCormick","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Christopher Evan Welch","avatar":""},{"name":"Adam Brooks","avatar":""},{"name":"Lyle Kanouse","avatar":""},{"name":"Clifford Lee Dickson","avatar":""},{"name":"Yolonda Ross","avatar":""},{"name":"Samantha Bee","avatar":""},{"name":"Marcia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
