INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mien-la-duoc-viec', 'Miễn Là Được Việc', 'Whatever Works', 'miễn là được việc whatever works larry david evan rachel wood michael mckean conleth hill patricia clarkson ed begley jr. carolyn mccormick henry cavill john gallagher jr. christopher evan welch adam brooks lyle kanouse clifford lee dickson yolonda ross samantha bee marcia ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-gioi', 'Loạn Giới', 'Dogtooth', 'https://phimimg.com/upload/vod/20231101-1/572b456c224f4e0cde00a45df01f5db1.jpg', 'https://phimimg.com/upload/vod/20231101-1/40a4f11da85a44ab8af971b8c18725a8.jpg', '<p>Loạn Giới là một bộ phim khá thú vị của Hy Lạp, được các chuyên gia phê bình phim đánh giá khá cao, vì thế mà có thể hiểu tại sao trên IDMb, bộ phim này được người dùng cho đến 7.2/10 điểm. Bộ phim cũng đã đạt được một số giải thưởng tại các liên hoan điện ảnh khác nhau.Phim kể về 1 gia đình giàu có, nơi mà 3 người con được bao bọc trong &quot;nhung lụa&quot;, cho đến lúc trưởng thành họ vẫn chưa 1 lần được bước ra khỏi ngôi nhà có rào cao bao quanh. Mọi ngôn từ, hành động của họ đều được cha mẹ &quot;định nghĩa&quot; cho, điều đó dẫn đến nhiều lệch lạc trong giới tính - hành động - cuộc sống... Phim có nhiều cảnh khỏa thân và kinh dị nên bạn cần suy nghĩ trước khi xem, cảm ơn.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Greece', 0, '[{"name":"Christos Stergioglou","avatar":""},{"name":"Michele Valley","avatar":""},{"name":"Hristos Passalis","avatar":""},{"name":"Angeliki Papoulia","avatar":""},{"name":"Mary Tsoni","avatar":""},{"name":"Anna Kalaitzidou","avatar":""},{"name":"Steve Krikris","avatar":""},{"name":"Sissi Petropoulou","avatar":""},{"name":"Alexander Voulgaris","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
