INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-da-giet-me-toi', 'Tôi Đã Giết Mẹ Tôi', 'I Killed My Mother', 'https://phimimg.com/upload/vod/20231101-1/5931d22fc3ea8142b5d13c2278287bbb.jpg', 'https://phimimg.com/upload/vod/20231101-1/78936ad1afc67010477daf53bf029b9e.jpg', '<p>Hubert, một thanh niên 17 tuổi xấc xược, bối rối và bị giằng xé bởi mối quan hệ yêu-ghét với mẹ mình, mối quan hệ ngày càng tiêu tốn anh ta nhiều hơn mỗi ngày. Sau những thử thách đau khổ và những tình tiết bi thảm, Hubert sẽ tìm thấy mẹ của mình bên bờ sông Saint Lawrence, nơi anh lớn lên và cũng là nơi xảy ra một vụ giết người: vụ giết tuổi thơ.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Anne Dorval","avatar":""},{"name":"Xavier Dolan","avatar":""},{"name":"François Arnaud","avatar":""},{"name":"Suzanne Clément","avatar":""},{"name":"Patricia Tulasne","avatar":""},{"name":"Niels Schneider","avatar":""},{"name":"Monique Spaziani","avatar":""},{"name":"Pierre Chagnon","avatar":""},{"name":"Justin Caron","avatar":""},{"name":"Benoît Gouin","avatar":""},{"name":"Johanne-Marie Tremblay","avatar":""},{"name":"Hugolin Chevrette","avatar":""},{"name":"Francis Ducharme","avatar":""},{"name":"Pascale Audrey","avatar":""},{"name":"Émile Mailhiot","avatar":""},{"name":"Laur","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
