INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-cau-nguyen-cho-bobby', 'Lời Cầu Nguyện Cho Bobby', 'Prayers for Bobby', 'https://phimimg.com/upload/vod/20231101-1/ffe636fa59cefe9a04acf215eb41af62.jpg', 'https://phimimg.com/upload/vod/20231101-1/8fe986c7b8b0fca1877b5f464a04e838.jpg', '<p>Bobby Griffith là con trai cưng của mẹ anh, một cậu bé người Mỹ hoàn hảo lớn lên dưới ảnh hưởng tôn giáo sâu sắc ở Walnut Creek, California. Bobby cũng là người đồng tính. Vật lộn với mâu thuẫn không ai biết, càng ít được hiểu, Bobby cuối cùng cũng công khai với gia đình mình.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Kelley","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"Dan Butler","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Carly Schroeder","avatar":""},{"name":"Shannon Eagen","avatar":""},{"name":"Scott Bailey","avatar":""},{"name":"Rebecca Louise Miller","avatar":""},{"name":"Susan Ruttan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324479);
