INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trung-lap', 'Người Trung Lập', 'Middle Men', 'https://phimimg.com/upload/vod/20231101-1/09d3de773ae1dd23e204d3ca2babe715.jpg', 'https://phimimg.com/upload/vod/20231101-1/513b6652965747ae0e85af587292db46.jpg', '<p>Năm 1995, nhà kinh doanh “thẳng-và-hẹp” Jack Harris, một trong những người đi tiên phong về thương mại internet – người đã xây dựng nên công ty thanh toán trực tuyến đầu tiên kinh doanh độc quyền ngành giải trí dành cho người lớn, thấy mình bị rơi vào giữa một cơn lốc đầy những ngôi sao, những gã tội phạm, găng tơ Nga, các đại lí liên bang, và khủng bố quốc tế.Bị kẹt giữa một ngôi sao khiêu dâm và FBI, Harris học được rằng dù có trở thành một doanh nhân giàu có nhất trong thế hệ của mình cũng chưa chắc đã đủ để giúp anh ta tránh khỏi những rắc rối. Anh đã đấu tranh với đạo đức của mình và cố gắng để không bị chết đuối trong một biển những người ấy.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Wilson","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Gabriel Macht","avatar":""},{"name":"James Caan","avatar":""},{"name":"Jacinda Barrett","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Laura Ramsey","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"John Ashton","avatar":""},{"name":"Jason Antoon","avatar":""},{"name":"Martin Kove","avatar":""},{"name":"Shannon Whirry","avatar":""},{"name":"Suzanne Kent","avatar":""},{"name":"Laur","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324479);
