INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-tham-tu', 'Kung Fu Thám Tử', 'Kung Fu Joe', 'null', 'https://phimimg.com/upload/vod/20231101-1/8696d0fc183bf39d8a987a679440a9bb.jpg', '<p>Khi một nhà khoa học điên cố gắng chiếm thế giới với một đội quân bị gù, nhóm người bịt mặt và nhóm cướp biển thời thơ ấu thì cần một người ngăn cản đội quân này lại. Và người đó là Thám Tử Kung Fu.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zak VanWinkle","avatar":""},{"name":"Wilson Large","avatar":""},{"name":"Victoria Maurette","avatar":""},{"name":"Jeremy Parrish","avatar":""}]', '[]', '[]', 1784690324479);
