INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-cua-nu-hoang-victoria', 'Tuổi trẻ của nữ hoàng Victoria', 'The Young Victoria', 'https://phimimg.com/upload/vod/20231101-1/e5402c2c8c9bee2b17dbed02c577c789.jpg', 'https://phimimg.com/upload/vod/20231101-1/3a6214b9fd036dc925f2f28096ca4a97.jpg', '<p>Là người thừa kế hợp pháp duy nhất của Vua William nước Anh, cô gái tuổi teen Victoria bị cuốn vào những âm mưu chính trị của chính gia đình mình. Mẹ của Victoria muốn cô ký lệnh nhiếp chính, trong khi người chú người Bỉ của cô âm mưu dàn xếp cuộc hôn nhân giữa quốc vương tương lai và Hoàng tử Albert, người sẽ trở thành tình yêu của đời cô.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Jeanette Hain","avatar":""},{"name":"Michiel Huisman","avatar":""},{"name":"Rachael Stirling","avatar":""},{"name":"Julian Glover","avatar":""},{"name":"Michael Maloney","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Mo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
