INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-vong-sinh-tu', '12 Vòng Sinh Tử', '12 Rounds', 'https://phimimg.com/upload/vod/20231101-1/62098b51a7a0ec1e1ff7cc4c65e5b953.jpg', 'https://phimimg.com/upload/vod/20231101-1/3f7e004536bdb2e02184d4b4fe787d86.jpg', '<p>Thám tử Danny Fisher phát hiện ra bạn gái của mình đã bị người yêu cũ, người đã gắn liền với quá khứ của anh bắt cóc, và Fisher sẽ phải hoàn thành thành công 12 thử thách để đảm bảo an toàn cho cô.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cena","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Ashley Scott","avatar":""},{"name":"Brian J. White","avatar":""},{"name":"Taylor Cole","avatar":""},{"name":"Gonzalo Menendez","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Kyle Clements","avatar":""},{"name":"Peter Navy Tuiasosopo","avatar":""},{"name":"Travis Davis","avatar":""},{"name":"Brian Stanton","avatar":""},{"name":"Rosalind Rubin","avatar":""},{"name":"Kim Collins","avatar":""},{"name":"Lara Grice","avatar":""},{"name":"Douglas M. Griffin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324479);
