INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('i-give-my-first-love-to-you', 'I Give My First Love to You', 'I Give My First Love to You', 'https://phimimg.com/upload/vod/20231031-1/2269ce6e7c9a82c5edeaa2b4c56b0525.jpg', 'https://phimimg.com/upload/vod/20231031-1/94a84afeccb029286eab03905f046cc3.jpg', '<p>Takuma biết rằng cuộc sống của mình ngắn hơn những người khác và anh ấy cảm thấy rằng ngày tàn của mình đang đến gần. Anh chọn cách xa người con gái mình yêu để cô ấy dễ dàng bước tiếp. Điều anh không biết là anh đang đánh giá thấp cô.</p>', 'Full', 1, 'single', 'completed', 19, 2009, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mao Inoue","avatar":""},{"name":"Masaki Okada","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Yôko Moriguchi","avatar":""},{"name":"Yoshihiko Hosoda","avatar":""},{"name":"Natsuki Harada","avatar":""},{"name":"Toru Nakamura","avatar":""},{"name":"Yuki Terada","avatar":""},{"name":"Masataka Kubota","avatar":""},{"name":"Keiko Horiuchi","avatar":""},{"name":"Gaku Yamamoto","avatar":""},{"name":"Kaito Kobayashi","avatar":""},{"name":"Sea Kumada","avatar":""},{"name":"Ryunosuke Suzuki","avatar":""},{"name":"Toshi Takeuchi","avatar":""},{"name":"Mari Okamoto","avatar":""},{"name":"Kotaro Shig","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
