INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('i-give-my-first-love-to-you', 'I Give My First Love to You', 'I Give My First Love to You', 'i give my first love to you i give my first love to you mao inoue masaki okada tetta sugimoto yôko moriguchi yoshihiko hosoda natsuki harada toru nakamura yuki terada masataka kubota keiko horiuchi gaku yamamoto kaito kobayashi sea kumada ryunosuke suzuki toshi takeuchi mari okamoto kotaro shig ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-suu-tam', 'Kẻ Sưu Tầm', 'The Collector', 'https://phimimg.com/upload/vod/20231030-1/1809d83f1be2a00c16e9e77a8c360749.jpg', 'https://phimimg.com/upload/vod/20231030-1/ccbf162c024500f277e97fa07b6c5d22.jpg', '<p>Nội dung của phim xoay quanh một người đàn ông tên là Arkin (Josh Stewart), người đang có công việc sửa chữa cửa sổ và cửa ra vào của gia đình nhà Chase (Michael Reilly Burke), những người mới chuyển đến một căn nhà biệt lập tại Detroit, ở giữa nơi không có nhiều người ở. Trong khoảng thời gian này, vợ của anh đang nợ một số tiền khá lớn của những tay cho vay lãi cực kỳ nguy hiểm, anh đang rất cần tiền nhưng khoản thanh toán mà anh nhận được sau đó thực tế là không đủ để trả các khoản nợ của vợ anh. Để có tiền trả nợ cho vợ, Arkin đã liều lĩnh tìm đường đột nhập vào trộm đá qúy trong két sắt của gia đình nhà Chase. Ngờ đâu rằng cả căn nhà là một mê cung chết chóc chỉ có đường vào mà không có đường ra. Khi anh ta đến nhà, anh ta nhận ra rằng một tên tội phạm bị cách ly vốn đã bị giam cầm trong ngôi nhà từ lâu với những cái bẫy được đặt ở khắp mọi nơi. Arkin tìm cách thoát khỏi căn nhà chết người và làm mọi thứ để có thể tự cứu mạng mình.</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Stewart","avatar":""},{"name":"Juan Fernández","avatar":""},{"name":"Michael Reilly Burke","avatar":""},{"name":"Madeline Zima","avatar":""},{"name":"Andrea Roth","avatar":""},{"name":"Karley Scott Collins","avatar":""},{"name":"Robert Wisdom","avatar":""},{"name":"Daniella Alonso","avatar":""},{"name":"Haley Pullos","avatar":""},{"name":"Diane Ayala Goldner","avatar":""},{"name":"Alex Feldman","avatar":""},{"name":"Krystal Mayo","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"Michael Showers","avatar":""},{"name":"Bill Stinchcomb","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
