INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhi-astro', 'Siêu Nhí Astro', 'Astro Boy', 'https://phimimg.com/upload/vod/20231029-1/092f131b28b3bd3d5488300cae5cd8bc.jpg', 'https://phimimg.com/upload/vod/20231029-1/c7a2553152705671fdea5f27de474648.jpg', '<p>Lấy bối cảnh ở Thành phố Metro tương lai, Astro Boy (Atom) là một robot trẻ tuổi với sức mạnh đáng kinh ngạc được tạo ra bởi một nhà khoa học lỗi lạc dưới hình ảnh đứa con trai mà ông đã mất. Không thể đáp ứng mong đợi của người tạo ra mình, Astro dấn thân vào cuộc hành trình tìm kiếm sự chấp nhận, trải qua sự phản bội và thế giới ngầm của các đấu sĩ robot, trước khi quay lại cứu Metro City và hòa giải với người cha đã từ chối anh.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2009, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Madeline Carroll","avatar":""},{"name":"Freddie Highmore","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Sterling Beaumon","avatar":""},{"name":"Nathan Lane","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Newell Alexander","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Pilar Flynn","avatar":""},{"name":"Dee B","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":