INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhi-astro', 'Siêu Nhí Astro', 'Astro Boy', 'siêu nhí astro astro boy nicolas cage madeline carroll freddie highmore kristen bell donald sutherland bill nighy eugene levy sterling beaumon nathan lane samuel l. jackson charlize theron david alan grier alan tudyk newell alexander elle fanning pilar flynn dee b ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-co-hinh-xam-rong', 'Cô Gái Có Hình Xăm Rồng', 'The Girl with the Dragon Tattoo', 'https://phimimg.com/upload/vod/20231029-1/ecbb752aadfba2465c63cc50c744d494.jpg', 'https://phimimg.com/upload/vod/20231029-1/43751cf6e83f7cdcbda7de7562f63645.jpg', '<p>Lisbeth Salander là một cô gái trẻ bị coi là có vấn đề về mặt tâm thần, được nuôi dạy trong một bệnh viện dành cho thiếu nhi. Vẻ bề ngoài cứng rắn gai góc, cách cư xử, giao tiếp như đi ngược lại những nguyên tắc xã hội, nhưng Salander có một trí thông minh tuyệt vời, trí nhớ đáng ngạc nhiên, cộng với sự liều lĩnh và quyết đoán đến không ngờ. Mikael Blomkvist, một nhà báo lão luyện nhưng uy tín đang suy giảm do một bài báo anh viết về vụ bê bối tài chính của Tập đoàn Wennerstrom bị cho là “không có căn cứ”. Blomkvist được Henrik Vanger, người đứng đầu một dòng họ giàu có và danh giá, thuê để tìm hiểu sự thật đằng sau vụ mất tích từ hơn 40 năm trước của cô cháu gái Harriet.</p>', 'Full', 1, 'single', 'completed', 21, 2009, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Michael Nyqvist","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Lena Endre","avatar":""},{"name":"Sven-Bertil Taube","avatar":""},{"name":"Peter Haber","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"Marika Lagercrantz","avatar":""},{"name":"Ingvar Hirdwall","avatar":""},{"name":"Björn Granath","avatar":""},{"name":"Ewa Fröling","avatar":""},{"name":"Michalis Koutsogiannakis","avatar":""},{"name":"Annika Hallin","avatar":""},{"name":"Sofia Ledarp","avatar":""},{"name":"Tomas Köhler","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Stefan Sauk","avatar":""},{"name":"Gö","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324479);
