INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-than-o-haeundae', 'Sóng Thần Ở Haeundae', 'Tidal Wave', 'https://phimimg.com/upload/vod/20231029-1/e3d27ef7d10470e02ef65da871b90c57.jpg', 'https://phimimg.com/upload/vod/20231029-1/981071a3d2289e1b598cbf62900bf15a.jpg', '<p>Trên bãi biển Haeundae, một ngư dân mang mặc cảm tội lỗi chăm sóc một người phụ nữ có cha vô tình bị giết. Một nhà khoa học đoàn tụ với vợ cũ và cô con gái thậm chí còn không nhớ mặt ông. Và một nhân viên cứu hộ nghèo phải lòng một cô gái thành phố giàu có. Khi tất cả họ phát hiện ra một cơn sóng thần khổng lồ sẽ ập vào bãi biển, họ nhận ra mình chỉ có 10 phút để trốn thoát.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sol Kyung-gu","avatar":""},{"name":"Ha Ji-won","avatar":""},{"name":"Park Joong-hoon","avatar":""},{"name":"Uhm Jung-hwa","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Ye-won Kang","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Byoung-Sook Sung","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Cheon Bo-geun","avatar":""},{"name":"Lee Briggs","avatar":""},{"name":"Ho-min Yeo","avatar":""},{"name":"Lee Si-on","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Do Yong-gu","avatar":""},{"name":"Lee Dae-ho","avatar":""},{"name":"Ji Dae-han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
