INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-loi-vuon-dia-dang', 'Tội Lỗi Vườn Địa Đàng', 'Antichrist', 'https://phimimg.com/upload/vod/20231026-1/99800d23679fde939fd53b04a70ffbde.jpg', 'https://phimimg.com/upload/vod/20231026-1/9a5582252b85ee3f05087a2748098c7d.jpg', '<p>Tội Lỗi Vườn Địa Đàng kể về câu chuyện của một cặp vợ chồng, sau cái chết của con mình, họ quyết định vào trong rừng sống một cuộc sống bình thường và tránh xa thế giới nhộn nhịp bên ngoài. Và người chồng càng ngày càng có nhiều cảm hứng, đồng thời người vợ cũng trở nên cuồng dâm vô độ. Những lần trần trụi đến khó tin và những lần quan hệ như những con thú ngày càng nhiều…</p>', 'Full', 1, 'single', 'completed', 22, 2009, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Willem Dafoe","avatar":""},{"name":"Charlotte Gainsbourg","avatar":""},{"name":"Storm Acheche Sahlstrøm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
