INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-hai-dau-yeu', 'Hình Hài Dấu Yêu', 'The Lovely Bones', 'https://phimimg.com/upload/vod/20231026-1/79159bffb843e4e92682e682e50b0bb3.jpg', 'https://phimimg.com/upload/vod/20231026-1/a35aaeb5be553d0fe2860af7be226c5b.jpg', '<p>Sau khi bị sát hại dã man, Susie Salmon, 14 tuổi, từ trên trời quan sát gia đình đang đau buồn của mình -- và kẻ giết cô. Khi quan sát cuộc sống hàng ngày của họ, cô phải cân bằng giữa khao khát trả thù với mong muốn gia đình được hàn gắn.</p>', 'Full', 1, 'single', 'completed', 16, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Rose McIver","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Carolyn Dando","avatar":""},{"name":"Christian Ashdale","avatar":""},{"name":"Reece Ritchie","avatar":""},{"name":"Nikki SooHoo","avatar":""},{"name":"Jake Abel","avatar":""},{"name":"AJ Michalka","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Stink Fisher","avatar":""},{"name":"Evelyn Lennon","avatar":""},{"name":"Andrew James Allen","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
