INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lap-di-dien-cao-the', 'Kẻ Lập Dị: Điện Cao Thế', 'Crank: High Voltage', 'https://phimimg.com/upload/vod/20231026-1/076423ee3df3fc4bd44966da40f6ca9f.jpg', 'https://phimimg.com/upload/vod/20231026-1/0d09da97c8aa8628b1261a82f67e40ea.jpg', '<p>Crank 2 High Voltage bắt đầu bằng việc sát thủ chuyên nghiệp Chev Chelios bị một nhóm gangster Trung Quốc bắt cóc.Ba tháng sau Chelios mới tỉnh dậy và phát hiện ra quả tim của mình đã bị thay thế bởi một quả tim nhân tạo. Để tồn tại và nuôi được quả tim này Chelios phải thường xuyên nạp điện cao thế vào người. Mục đích của nhóm xã hội đen này là muốn sử dụng Chelios làm công cụ thực hiện những ý đồ đen tối do chúng thiết lập nên. Tuy nhiên, chúng vấp phải sự kháng cự tột cùng của ý chí con người, của bản năng tồn tại tự do trong cá thể Chelios.</p>', 'Full', 1, 'single', 'completed', 12, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"David Carradine","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Jose Pablo Cantillo","avatar":""},{"name":"Efren Ramirez","avatar":""},{"name":"Julanne Chidi Hill","avatar":""},{"name":"Reno Wilson","avatar":""},{"name":"Keone Young","avatar":""},{"name":"Art Hsu","avatar":""},{"name":"J. J. Soria","avatar":""},{"name":"Corey Haim","avatar":""},{"name":"Geri Horner","avatar":""},{"name":"William Brent","avatar":""},{"name":"Jamie Harris","avatar":""},{"name":"John de","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b3