INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-tuoi-17', 'Trở Lại Tuổi 17', '17 Again', 'https://phimimg.com/upload/vod/20231026-1/4cf4b56e016c621c7e2a36b01f1285c9.jpg', 'https://phimimg.com/upload/vod/20231026-1/4bf05dd08b7dc5520ebd5f1b71b1aaa0.jpg', '<p>17 Again (Trở Lại Tuổi 17) là bộ phim hài hước kể về Mike O Donnell, chàng trai nổi tiếng nhất trường. Nhưng cậu quyết định từ bỏ học bổng để bắt đầu cuộc sống mới với cô bạn gái Scarlet. Hai mươi năm sau, Mike &quot;người lớn&quot; cảm thấy cuộc sống không tốt đẹp như những gì anh hằng mong đợi. Anh nhớ lại thời quá khứ vang dội của mình và ước gì mọi thứ cũng được vẻ vang như thời anh 17. Rồi một ngày nọ anh thức giấc và thấy mình biến thành cậu bé Mike 17 tuổi... Điều gì sẽ xảy ra với Mike 17 tuổi? Anh có thích nghi được với cuộc sống hiện tại? Mike có quay lại được với chính mình?</p>', 'Full', 1, 'single', 'completed', 14, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Michelle Trachtenberg","avatar":""},{"name":"Sterling Knight","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"Tyler Steelman","avatar":""},{"name":"Allison Miller","avatar":""},{"name":"Adam Gregory","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Mario Cassem","avatar":""},{"name":"Kat Graham","avatar":""},{"name":"Tiya Sircar","avatar":""},{"name":"Melissa Ordway","avatar":""},{"name":"Melora Hardin","avatar":""},{"name":"Brian Doyle-Murray","avatar":""},{"name":"Josie Lor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
