INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-chang-ngoc', '3 Chàng Ngốc', '3 Idiots', 'https://phimimg.com/upload/vod/20231026-1/c649daafa7ac8dafb1a372ff360f44f4.jpg', 'https://phimimg.com/upload/vod/20231026-1/91053836cd5df14d0675f98eecd03d17.jpg', '<p>Phim xoay quanh câu chuyện ăn học của 3 anh chàng sinh viên, phim bắt đầu từ hồi tưởng của Farhan về quãng thời gian học tại Học Viện Cơ Khí Hoàng Gia cùng hai người bạn Rancho và Raju. Bất chấp mỗi người có một hoàn cảnh riêng họ đã trở thành những người bạn vô cùng thân thiết và trong khi cả trường đi theo phương pháp học tập máy móc của thầy hiệu trưởng Viru Sahastrabuddhe thì Rancho lại đi theo hướng học tập sáng tạo gây không ít mâu thuẫn với thầy nhưng thật trớ trêu Rancho lại đem lòng yêu Pia con gái thầy Viru. Thực sự Three Idiots là bộ phim vô cùng đáng xem dành cho các bạn học sinh, sinh viên đang ngồi trên ghế nhà trường. Three Idiots cũng là bức tranh tái hiện quá trình ăn ở học tập của sinh viên nói chung. Tất cả những yếu tố: áp lực học hành, lựa chọn nghề nghiệp, phương pháp học đại học đều được phản ánh rõ nét. bên cạnh đó là tình yêu trong sáng, lãng mạn và đẹp đẽ giữa Rancho và Pia. Three Idiots là tuyệt tác khó có thể bỏ qua.</p>', 'Full', 1, 'single', 'completed', 20, 2009, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"R. Madhavan","avatar":""},{"name":"Sharman Joshi","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Boman Irani","avatar":""},{"name":"Omi Vaidya","avatar":""},{"name":"Rahul Kumar","avatar":""},{"name":"Mona Singh","avatar":""},{"name":"Javed Jaffrey","avatar":""},{"name":"Olivier Lafont","avatar":""},{"name":"Parikshat Sahni","avatar":""},{"name":"Farida Dadi","avatar":""},{"name":"Amardeep Jha","avatar":""},{"name":"Mukund Bhatt","avatar":""},{"name":"Ali Fazal","avatar":""},{"name":"Arun Bali","avatar":""},{"name":"Supriya Shukla","avatar":""},{"name":"Dushyant Wagh","avatar":""},{"name":"Ak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
