INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-yeu', 'Chờ Yêu', 'He''s Just Not That Into You', 'https://phimimg.com/upload/vod/20231024-1/2e9856ec12b78875c2e6aef73c15a2ee.jpg', 'https://phimimg.com/upload/vod/20231024-1/b211ff76d76554747a3c93ea7657fa82.jpg', '<p>Cuộc sống của các cư dân Baltimore giao thoa khi họ đối mặt với sự phức tạp và cạm bẫy của các mối quan hệ hiện đại với tư cách là bạn bè lẫn người yêu.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ginnifer Goodwin","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Kevin Connolly","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"Sasha Alexander","avatar":""},{"name":"Wilson Cruz","avatar":""},{"name":"Hedy Burress","avatar":""},{"name":"Leonardo Nam","avatar":""},{"name":"Busy Philipps","avatar":""},{"name":"Brooke Bloom","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
