INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soc-sieu-quay-2', 'Sóc Siêu Quậy 2', 'Alvin and the Chipmunks: The Squeakquel', 'https://phimimg.com/upload/vod/20231024-1/305b1225891de689a2b2ca52513e70cc.jpg', 'https://phimimg.com/upload/vod/20231024-1/bacd00c81a8e8f8bc614092b88199a03.jpg', '<p>Alvin and the Chipmunks 2 là một bộ phim hoạt hình hài hành động Mỹ 2009 của đạo diễn Betty Thomas. Phim được viết bởi Jon Vitti, Jonathan Aibel và Glenn Berger, được phát hành bởi Twentieth Century Fox và được sản xuất bởi Fox 2000 Pictures, Regency Enterprises và Bagdasarian Company.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zachary Levi","avatar":""},{"name":"David Cross","avatar":""},{"name":"Jason Lee","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Jesse McCartney","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"Anjelah Johnson-Reyes","avatar":""},{"name":"Kathryn Joosten","avatar":""},{"name":"Kevin G. Schmidt","avatar":""},{"name":"Chris Warren","avatar":""},{"name":"Bridgit Mendler","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324479);
