INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('soc-sieu-quay-2', 'Sóc Siêu Quậy 2', 'Alvin and the Chipmunks: The Squeakquel', 'sóc siêu quậy 2 alvin and the chipmunks: the squeakquel zachary levi david cross jason lee justin long matthew gray gubler jesse mccartney amy poehler anna faris christina applegate wendie malick anjelah johnson-reyes kathryn joosten kevin g. schmidt chris warren bridgit mendler aimee carrero a ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-ac-chien-nguoi-ngoai-hanh-tinh', 'Quái Vật Ác Chiến Người Ngoài Hành Tinh', 'Monsters vs Aliens', 'https://phimimg.com/upload/vod/20231023-1/718f2df5ccfc804d8c5166646b73eb6e.jpg', 'https://phimimg.com/upload/vod/20231023-1/434a656f72968679b8a03f6867e04239.jpg', '<p>Trong phim Quái Vật Ác Chiến Người Hành Tinh, một tai nạn bất ngờ đã xảy ra ngay trong lễ cưới của Susan Murphy. Một thiên thạch rơi xuống Trái đất đã va vào cô khiến cho cơ thể Susan bỗng phát triển thành một người khổng lồ cao tới 15m. Quân đội ngay lập tức bắt giữ Susan và giam lỏng cô tại một trung tâm nghiên cứu bí mật của chính phủ. Tại đây, Susan được đổi tên thành Ginormica và gia nhập vào nhóm Quái vật đang được nghiên cứu. Cùng lúc đó, rô-bốt bí ẩn do Gallaxhar - kẻ mắc chứng hoang tưởng điều động đáp xuống Trái đất. Con rô-bốt này mang âm mưu thôn tính thế giới và đã ra tay bắn phá khắp nơi. Trong sự liều lĩnh tuyệt vọng, ngài Tổng thống (Stephen Colbert) chỉ còn cách thuyết phục nhóm Quái vật gia nhập quân đội để chống lại kẻ xâm lược ngoài hành tinh, cứu thế giới khỏi thảm họa diệt vong. Liệu mọi chuyện sẽ diễn ra thế nào, nhóm Quái vật có gia nhập quân đội và chống lại con rô-bốt kia không?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Stephen Colbert","avatar":""},{"name":"Julie White","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Sean Bishop","avatar":""},{"name":"Rich Dietl","avatar":""},{"name":"Rob Letterman","avatar":""},{"name":"Tom McGrath","avatar":""},{"name":"Chris Miller","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324479);
