INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-sat-thu', 'Ninja Sát Thủ', 'Ninja Assassin', 'https://phimimg.com/upload/vod/20231023-1/037b00a362c1439e557669c095f6627c.jpg', 'https://phimimg.com/upload/vod/20231023-1/5f48c194c75c10df80945a339c42f321.jpg', '<p>Bộ phim tập trung vào nhân vật Raizo (Rain), một trong những ninja sát thủ nguy hiểm nhất trên thế giới. Raiza thuở nhỏ là một đứa trẻ đường phố, được tổ chức Ozunu Clan, một tổ chức bí mật mà sự tồn tại của nó dường như vẫn là huyền thoại, nhận về nuôi và huấn luyện để trở thành sát thủ chuyên nghiệp. Nhưng Raizo bị ám ảnh bởi cách đối xử tàn nhẫn của tổ chức đối với bạn mình, Raizo quyết định trốn chạy và biến mất khỏi tổ chức. Raizo chờ đợi, và chuẩn bị thời cơ để trả thù.Tại Berlin, điệp vụ Mika Coretti chộp được manh mối về đường dây chuyển tiền giữa các sát thủ chuyên ám sát chính trị gia và một tổ chức sát thủ bí ẩn từ Viễn Đông. Thừa lệnh của cấp trên, Mika xâm nhập vào hệ thống tối ...</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Rain","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Rick Yune","avatar":""},{"name":"Yuki Iwamoto","avatar":""},{"name":"Sho Kosugi","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Linh-Dan Pham","avatar":""},{"name":"Lee Joon","avatar":""},{"name":"Jonathan Chan-Pensley","avatar":""},{"name":"Ill-Young Kim","avatar":""},{"name":"Fang Yu","avatar":""},{"name":"Adriana Altaras","avatar":""},{"name":"Kylie Liya Page","avatar":""},{"name":"Sungwoong Yoon","avatar":""},{"name":"Eleonore Weisgerber","avatar":""},{"name":"Wladimir Tarasj","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
