INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-vien-bao-tang-tran-chien-hoang-gia', 'Đêm Ở Viện Bảo Tàng: Trận Chiến Hoàng Gia', 'Night at the Museum: Battle of the Smithsonian', 'https://phimimg.com/upload/vod/20231023-1/6d960eb3b55d629537945f24f69f0f18.jpg', 'https://phimimg.com/upload/vod/20231023-1/b09a7886a5a0b1bd4518de02e94fcbda.jpg', '<p>Lại một lần nữa bảo tàng lịch sử tự nhiên đóng cửa để trùng tu, các hiện vật và mẫu tượng tại đây được chuyển đến kho dự trữ liên bang. Larry Daley không còn làm việc gác bảo tàng ban đêm nữa, nhưng khi biết tin các bạn cũ – tượng Cựu tổng thống Roosevelt và chàng cao bồi Jedediah đang gặp nạn tại nơi ở mới, Larry mạo hiểm thâm nhập vào kho dự trữ liên bang để giúp các bạn. Vẫn là đêm kinh hoàng với Larry khi các hiện vật tiếp tục nổi loạn. Câu chuyện giả tưởng về các hiện vật sống lại đã thu hút sự chú ý của hàng triệu người trên thế giới. Night At The Museum 2 Battle Of The Smithsonian hấp dẫn ở cốt truyện lạ, hài hước pha chút hành động mạo hiểm.</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Christopher Guest","avatar":""},{"name":"Alain Chabat","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"Jake Cherry","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Mizuo Peck","avatar":""},{"name":"Kerry van der Griend","avatar":""},{"name":"Matthew Harrison","avatar":""},{"name":"Rick","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324479);
