INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-o-vien-bao-tang-tran-chien-hoang-gia', 'Đêm Ở Viện Bảo Tàng: Trận Chiến Hoàng Gia', 'Night at the Museum: Battle of the Smithsonian', 'đêm ở viện bảo tàng: trận chiến hoàng gia night at the museum: battle of the smithsonian ben stiller amy adams owen wilson hank azaria robin williams christopher guest alain chabat steve coogan ricky gervais bill hader jon bernthal patrick gallagher jake cherry rami malek mizuo peck kerry van der griend matthew harrison rick ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-ret-nguoi', 'Con Rết Người', 'The Human Centipede (First Sequence)', 'https://phimimg.com/upload/vod/20231022-1/4484b120ca9d5e66cd2da5321df3dfb2.jpg', 'https://phimimg.com/upload/vod/20231022-1/2780437f6e4f887283637c2da52fc5ff.jpg', '<p>Trong một lần dừng chân ở Đức giữa chuyến đi vô tư xuyên châu Âu, hai cô gái người Mỹ thấy mình cô đơn vào ban đêm khi xe của họ bị hỏng trong rừng. Đang tìm kiếm sự giúp đỡ tại một biệt thự gần đó, họ bị cuốn vào nanh vuốt của một bác sĩ phẫu thuật loạn trí đã nghỉ hưu, người giải thích tầm nhìn khoa học điên rồ của mình cho những người bị giam giữ &quot;thật kinh hoàng&quot;. Họ trở thành đối tượng trong giấc mơ bệnh tật suốt đời của anh ta: trở thành người đầu tiên kết nối con người, người này đến người khác, và khi làm như vậy sẽ làm sống lại “con rết con người”.</p>', 'Full', 1, 'single', 'completed', 21, 2009, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Dieter Laser","avatar":""},{"name":"Ashley C. Williams","avatar":""},{"name":"Ashlynn Yennie","avatar":""},{"name":"Akihiro Kitamura","avatar":""},{"name":"Andreas Leupold","avatar":""},{"name":"Peter Blankenstein","avatar":""},{"name":"Rosemary Annabella","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324479);
