INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-du-hanh-giua-cac-vi-sao', 'Star Trek: Du Hành Giữa Các Vì Sao', 'Star Trek', 'https://phimimg.com/upload/vod/20231020-1/c36df7edd5e310ad54047bbd8b18ac5f.jpg', 'https://phimimg.com/upload/vod/20231020-1/22ec0025d32acccd228a81621bc677e1.jpg', '<p>Bộ phim xoay quanh một nhóm phi hành gia trên tàu vũ trụ U.S.S. Enterprise. Trong chuyến phiêu lưu đầy mạo hiểm, họ phải tìm cách ngăn chặn Thuyền trưởng Nero, thuộc tộc người Romulan, kẻ đang có âm mưu tàn sát toàn nhân loại.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"John Cho","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Rachel Nichols","avatar":""},{"name":"Faran Tahir","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Tony Elias","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324479);
