INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-bao-thu', 'Người Hùng Báo Thù', 'Watchmen', 'https://phimimg.com/upload/vod/20231020-1/0878a1c80f1a08980c5ec61e066d94ea.jpg', 'https://phimimg.com/upload/vod/20231020-1/cdac5432f3cad77693c2bd6d6a2ee629.jpg', '<p>Được chuyển thể từ bộ truyện tranh cùng tên nổi tiếng của Alan Moore (DC Comics), bối cảnh của phim Watchmen diễn ra vào năm 1985 giả định, thời điểm mà các siêu anh hùng tồn tại, Richard Nixon vẫn còn là tổng thống, và cuộc chiến tranh lạnh căng thẳng giữa Mỹ và Liên bang Xô Viết đang ở đỉnh cao.&nbsp; Ủy viên ban trật tự Rorschach đang điều tra vụ ám sát Comedian và khám phá ra một loạt những vụ sát hại những siêu anh hùng khác. Rorschach phát hiện ra một âm mưu diện rộng liên quan đến quá khứ của những đồng nghiệp của mình khiến toàn bộ lịch sử thay đổi.</p>', 'Full', 1, 'single', 'completed', 13, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Malin Åkerman","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Laura Mennell","avatar":""},{"name":"Matt Frewer","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Rob LaBelle","avatar":""},{"name":"Gary Houston","avatar":""},{"name":"James M. Connor","avatar":""},{"name":"Mary Ann Burger","avatar":""},{"name":"John Shaw","avatar":""},{"name":"Robert Wisden","avatar":""},{"name":"Jerry W","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324479);
