INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-va-chang-ech', 'Công Chúa và Chàng Ếch', 'The Princess and the Frog', 'https://phimimg.com/upload/vod/20231018-1/ff0a95eef0cc6d7a5f49841eedd37604.jpg', 'https://phimimg.com/upload/vod/20231018-1/9ea5d69aa2f13521497a19355ca6da4f.jpg', '<p>Tiana là một cô gái chăm chỉ, tự lập, và quyến rũ. Cô không có thời gian dành cho sự mơ mộng lãng mạn, mà thay vào đó là một niềm đam mê nấu nướng và cô mong muốn sẽ trở thành một người quản lý nhà hàng thành đạt, kế thừa từ người cha mình. Nhưng dù cho có cần cù và siêng năng đến mấy thì những trở ngại vẫn khiến cho mong ước đó của Tiana còn khá xa vời.</p>', 'Full', 1, 'single', 'completed', 21, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anika Noni Rose","avatar":""},{"name":"Bruno Campos","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Michael-Leon Wooley","avatar":""},{"name":"Keith David","avatar":""},{"name":"Jennifer Cody","avatar":""},{"name":"Peter Bartlett","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Oprah Winfrey","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"Don Hall","avatar":""},{"name":"Paul Briggs","avatar":""},{"name":"Jerry Kernion","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Elizabeth Da","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324479);
