INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-chua-va-chang-ech', 'Công Chúa và Chàng Ếch', 'The Princess and the Frog', 'công chúa và chàng ếch the princess and the frog anika noni rose bruno campos jim cummings michael-leon wooley keith david jennifer cody peter bartlett jenifer lewis oprah winfrey john goodman terrence howard ritchie montgomery don hall paul briggs jerry kernion corey burton elizabeth da ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than-bo-mac-cho-chet', 'Ngã Rẽ Tử Thần: Bỏ Mặc Cho Chết', 'Wrong Turn 3: Left for Dead', 'https://phimimg.com/upload/vod/20231018-1/128a4573870307bf29a7ed2a26c3bdb2.jpg', 'https://phimimg.com/upload/vod/20231018-1/3f8167e44fe1b93a55d10a0071028790.jpg', '<p>Ở một nhà tù tại tiểu bang Virginia, ba người cảnh sát là Nate, Walter và Preslow được lệnh phải chuyển một vài tù nhân đến nhà tù khác, bọn tù nhân đó đều là những tên tội phạm nguy hiểm nên phải kiểm tra bọn chúng chặt chẽ. Tối hôm đó, khi đi ngang qua khu rừng miền Tây Virginia, chiếc xe tù của họ đang chạy thì bị Three Finger lấy xe đuổi theo, hắn dùng dây kẽm gai làm nổ lốp xe tù khiến nó bị lật. Một lát sau khi hắn chạy mất, bọn tù nhân cùng những cảnh sát chui ra khỏi xe, bọn tù nhân cướp hết súng rồi đe dọa lại cảnh sát. Cả bọn phải đi bộ vào rừng, trên đường đi họ gặp một cô gái tên Alex nói là có một tên sát nhân đột biến đã giết sạch bạn cô. Những người tù nhân lẫn cảnh sát sẽ phải làm gì để đối phó với tên Three Finger và Three Toes, con hắn, liệu họ có thoát ra khỏi khu rừng kinh hoàng này không.</p>', 'Full', 1, 'single', 'completed', 18, 2009, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Tom Frederic","avatar":""},{"name":"Janet Montgomery","avatar":""},{"name":"Louise Cliffe","avatar":""},{"name":"Jack Gordon","avatar":""},{"name":"Emma Clifford","avatar":""},{"name":"Todd Jensen","avatar":""},{"name":"Gil Kolirin","avatar":""},{"name":"Charles Venn","avatar":""},{"name":"Jake Curran","avatar":""},{"name":"Tamer Hassan","avatar":""},{"name":"Christian Contreras","avatar":""},{"name":"Tom McKay","avatar":""},{"name":"Mike Straub","avatar":""},{"name":"Borislav Iliev","avatar":""},{"name":"Bill Moody","avatar":""},{"name":"Mac McDonald","avatar":""},{"name":"Charley Speed","avatar":""},{"name":"Borislav Pe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
