INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ly-bao-thu', 'Công Lý Báo Thù', 'Law Abiding Citizen', 'https://phimimg.com/upload/vod/20231019-1/7cbc4236a6c9d5721580ad2231a156fe.jpg', 'https://phimimg.com/upload/vod/20231019-1/2439f04d316cc0398cffe8709be2689e.jpg', '<p>Khi một vụ đột nhập và cướp tài sản ở một ngôi nhà diễn biến theo hướng tồi tệ, kẻ sống sót duy nhất sẽ chỉ dừng lại khi việc trả thù cho những người mà anh yêu quý hoàn tất. Clyde Shelton (Gerard Butler) thuộc tuýp người đàn ông đứng đắn của gia đình. Anh có vợ và con gái bị giết hại một cách dã man trong một vụ đột nhập nhà trái phép. Khi những tên sát thủ bị bắt, Nick Rice (Jamie Foxx) – công tố viên nổi tiếng của Philadelphia – được phân công thẩm định vụ án. Nick đã xử một trong những nghi phạm một bản án khá nhẹ để đổi lấy việc lấy lời khai chống lại đồng bọn của hắn.10 năm sau, người ta tìm thấy xác của một gã thoát tội giết người. Clyde Shelton bình thản nhận tội là đã giết hắn. Sau đó, anh cảnh báo ...</p>', 'Full', 1, 'single', 'completed', 17, 2009, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Michael Irby","avatar":""},{"name":"Gregory Itzin","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Emerald-Angel Young","avatar":""},{"name":"Brooke Stacy Mills","avatar":""},{"name":"Christian Stolte","avatar":""},{"name":"Annie Corley","avatar":""},{"name":"Richard Portnow","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Roger Bart","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
