INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-ngu-lam', 'Ba Chàng Ngự Lâm', 'The Hangover', 'https://phimimg.com/upload/vod/20231018-1/08c5c5bafed308122d3cae23a04f951f.jpg', 'https://phimimg.com/upload/vod/20231018-1/997b34242f50b44178f56383a8611928.jpg', '<p>The Hangover là bộ phim hài hước xoay quanh cuộc phiêu lưu của ba anh chàng độc thân. Doug Billings sắp kết hôn, ba chàng bạn thân Phil Wenneck, Stu Price, và cậu em rể Alan Garner quyết phải cùng Doug trải qua một buổi tiệc độc thân nhớ đời, theo đúng cách của các chàng trai Mỹ vẫn làm. Nhưng mọi việc bất ngờ trở nên tồi tệ sau một đêm quậy tưng bừng, anh bạn Doug đã mất tích, trong phòng tắm có một con hổ, chàng nha sĩ Stu mất một chiếc răng, còn trong tủ áo thì đột nhiên xuất hiện thêm một đứa bé. Không thể liên lạc được với Doug, cũng như không nhớ nổi chuyện gì đã xảy ra vào tối hôm trước, cả ba bắt đầu lần tìm từ những manh mối còn sót lại trong phòng. Nguy cơ chú rể mất tích trong lễ cưới và hôn lễ phải hủy bỏ càng khiến cả ba càng lo lắng. Trên đường truy tìm tông tích Doug, bao chuyện bi hài tréo ngoe đã diễn ra với bộ ba....</p>', 'Full', 1, 'single', 'completed', 20, 2009, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Sasha Barrese","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Jernard Burks","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Cleo King","avatar":""},{"name":"Bryan Callen","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Ian Anthony Dale","avatar":""},{"name":"Michael Li","avatar":""},{"name":"Sond","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
