INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lai-tao', 'Người Lai Tạo', 'Splice', 'https://phimimg.com/upload/vod/20231018-1/0f81daae4b65d67a8e4daa3204baa853.jpg', 'https://phimimg.com/upload/vod/20231018-1/f7036f680e771726f738fb17b277e558.jpg', '<p>Elsa và Clive, hai nhà khoa học trẻ nổi loạn, bất chấp ranh giới pháp lý và đạo đức và tiến hành một thí nghiệm nguy hiểm: ghép DNA của con người và động vật để tạo ra một sinh vật mới. Được đặt tên là &quot;Dren&quot;, sinh vật này nhanh chóng phát triển từ một bé gái sơ sinh dị dạng thành một con người-tinh tinh có cánh xinh đẹp nhưng nguy hiểm, người đã tạo nên mối liên kết với cả hai người tạo ra mình - chỉ để mối liên kết đó trở nên nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 25, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Sarah Polley","avatar":""},{"name":"Delphine Chanéac","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"Abigail Chu","avatar":""},{"name":"Stephanie Baird","avatar":""},{"name":"Brandon McGibbon","avatar":""},{"name":"Amanda Brugel","avatar":""},{"name":"Simona Măicănescu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
