INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-6', 'Lưỡi Cưa 6', 'Saw VI', 'https://phimimg.com/upload/vod/20231018-1/c4fd2d60b058cc21249e3c9b5e788e2e.jpg', 'https://phimimg.com/upload/vod/20231018-1/52fe93786e06d9566ca92da875dd453d.jpg', '<p>Saw 6 là câu chuyện nối tiếp sau Saw 5. Thanh tra Peter Strahm đã bị thiếu úy Mark Hoffman giết chết trong khi anh truy tìm tung tích của Jigsaw và những tên đồng lõa.&nbsp; Sự việc trở nên tồi tệ khi mà mọi nghi ngờ đều đổ dồn vào vào thanh tra quá cố Peter Strahm do một nhân viên FBI đã nhầm rằng anh chính là Jigsaw “thật sự”.&nbsp; Điều đó khiến cuộc truy tìm những kẻ giúp đỡ Jigsaw sẽ trở nên khó khăn, nguy hiểm hơn rất nhiều, nhất là lúc ấy, thiếu úy “dởm” Hoffman vẫn nhởn nhơ ngoài vòng pháp luật và tiếp tục gây ra những tội ác theo đúng những phong cách mà Jigsaw/John Kramer vẫn làm... Trò chơi trở về nơi bắt đầu.</p>', 'Full', 1, 'single', 'completed', 23, 2009, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Tobin Bell","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Mark Rolston","avatar":""},{"name":"Betsy Russell","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Peter Outerbridge","avatar":""},{"name":"Athena Karkanis","avatar":""},{"name":"Samantha Lemole","avatar":""},{"name":"Tanedra Howard","avatar":""},{"name":"Marty Moreau","avatar":""},{"name":"Shawn Ahmed","avatar":""},{"name":"Janelle Hutchison","avatar":""},{"name":"Gerry Mendicino","avatar":""},{"name":"Caroline Cave","avatar":""},{"name":"George Newbern","avatar":""},{"name":"Shauna MacDonald","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
