INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-rong', 'Bẫy Rồng', 'Clash', 'https://phimimg.com/upload/vod/20231011-1/3523d7047bfb8ea78cc0527ad340963a.jpg', 'https://phimimg.com/upload/vod/20231011-1/000e9a01ff6ccb8cdf2158c39ba2e7c3.jpg', '<p>Câu chuyện trong Bẫy rồng được mở đầu đầy ẩn dụ về những mối quan hệ lắt léo trong giới giang hồ, ở đó kẻ đặt bẫy người khác có khi cũng chính là con mồi, và ngược lại.Câu chuyện bắt đầu khi một băng nhóm giang hồ do Trinh, biệt danh Phượng Hoàng (Ngô Thanh Vân) nhận nhiệm vụ giành giật một chiếc máy tính xách tay có khả năng xâm nhập và điều khiển vệ tinh Vinasat 1, đang nằm trong tay một băng mafia người Pháp – những tên này tới Sài Gòn với mục đích rao bán chiếc máy tính xách tay trên với số tiền khổng lồ.Để thực hiện phi vụ, Trinh chiêu mộ một số tay giang hồ cộm cán – trong đó có Quân, biệt danh Hổ (Johnny Trí Nguyễn) và mua vũ khí từ các băng đảng khác. Những cuộc xung đột nảy lửa diễn ra ngay từ đầu bởi ...</p>', 'Full', 1, 'single', 'completed', 22, 2009, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Johnny Nguyen","avatar":""},{"name":"Veronica Ngo","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Lâm Minh Thắng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
