INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('14-ngay-phep', '14 Ngày Phép', '14 Days', 'null', 'https://phimimg.com/upload/vod/20231011-1/d8d5d0aa33ebafa218f7fe9ecd6da751.jpg', '<p>kể về Dũng, một kỹ sư công nghệ thông tin trở về nước sau 31 năm sống ở Mỹ để tìm hiểu quê hương trong 14 ngày nghỉ phép. Tại đây, trong những cuộc ăn chơi cùng Lâm ở vũ trường, anh ta gặp và yêu Thảo, nữ tiếp viên quán bar 25 tuổi.</p>', 'Full', 1, 'single', 'completed', 22, 2009, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trịnh Hội","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Bình Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
