INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-ma-ca-rong-cuoi-cung', 'Máu: Ma Cà Rồng Cuối Cùng', 'Blood: The Last Vampire', 'https://phimimg.com/upload/vod/20231010-1/446883c1389058159b08d10674911c47.jpg', 'https://phimimg.com/upload/vod/20231010-1/28a1a65e2c0a62aaf048bf5e7932b8e4.jpg', '<p>Bề ngoài, Saya là một cô gái 16 tuổi xinh đẹp nhưng vẻ ngoài trẻ trung đó lại ẩn giấu tâm hồn dày vò của một “người lai” 400 tuổi. Sinh ra với cha là con người và mẹ là ma cà rồng, trong nhiều thế kỷ, cô là người cô độc bị ám ảnh bởi việc sử dụng các kỹ năng samurai của mình để loại bỏ thế giới ma cà rồng, trong khi biết rằng bản thân cô chỉ có thể sống sót nhờ máu như những người cô săn lùng.</p>', 'Full', 1, 'single', 'completed', 20, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Allison Miller","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Koyuki","avatar":""},{"name":"JJ Feild","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Larry Lamb","avatar":""},{"name":"Andrew Pleavin","avatar":""},{"name":"Michael Byrne","avatar":""},{"name":"Colin Salmon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324479);
