INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-2009', 'Câu Chuyện Tình Yêu', 'Basic Love', 'https://phimimg.com/upload/vod/20231006-1/e4bb90f6f19de34a1672d61de7bf1996.jpg', 'https://phimimg.com/upload/vod/20231006-1/6a867a268f202e794ad617e3f5cc9053.jpg', '<p>Elanne Kwong và Janice Mann đóng vai chính với Rex Ho trong vai 3 người bạn thân nhất dần nảy sinh tình cảm với nhau, Ling lúc đầu hy vọng được đóng vai Cupid cùng Rex và Janice. Mọi chuyện trở nên phức tạp khi chẩn đoán ung thư của Ling được bạn bè cô biết và cô bắt đầu nhận ra rằng Rex có tình cảm với cô.</p>', 'Full', 1, 'single', 'completed', 20, 2009, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ellane Kong","avatar":""},{"name":"Rex Ho","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Cheng Pei-pei","avatar":""},{"name":"Pakho Chau","avatar":""},{"name":"Elanne Kwong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324479);
