INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-bo-gap-me-phan-5', 'Khi Bố Gặp Mẹ (Phần 5)', 'How I Met Your Mother (Season 5)', 'https://phimimg.com/upload/vod/20231001-1/c99b38f049dabdf756793b371dd0e8b7.jpg', 'https://phimimg.com/upload/vod/20231001-1/6fb6edf3096a4ef5a9288d87a5aaafb3.jpg', '<p>Tiếng cười quay trở lại mùa 5 “Khi Bố Gặp Mẹ”. Mọi chuyện bắt đầu khi người bạn thân nhất của Ted, Marshall, tiết lộ rằng anh ta sẽ cầu hôn người bạn gái lâu năm của mình, và bây giờ là vợ, Lily, một giáo viên mẫu giáo. Vào lúc đó, Ted nhận ra rằng tốt hơn hết anh nên đi tiếp nếu anh quá hy vọng tìm được tình yêu đích thực. Bộ truyện được kể lại thông qua những đoạn hồi tưởng từ tương lai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 23, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Cristin Milioti","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
