INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dap-hoan-hao', 'Cú Đáp Hoàn Hảo', 'Take Off', 'https://phimimg.com/upload/vod/20230930-1/37a3b04e2833d70db1d09df7fbdfd06c.jpg', 'https://phimimg.com/upload/vod/20230930-1/f25e558160dcc04d3b533cb2e91048e6.jpg', '<p>Năm thiếu niên bất đắc dĩ bị buộc phải trở thành những thành viên 
đội tuyển &quot;đại diện quốc gia&quot; để đi thi đấu môn Trượt tuyết nhảy xa. 
Cũng từ đây, họ đã bắt đầu phải trải qua một cuộc hành trình huấn luyện 
hết sức gian khổ với đầy mồ hôi và nước mắt nhưng cũng không kém phần 
vui nhộn với những tình huống vô cùng hài hước.</p>', 'Full', 1, 'single', 'completed', 24, 2009, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Kim Ji-seok","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Choi Jae-hwan","avatar":""},{"name":"Lee Jae-eung","avatar":""},{"name":"Lee Eun-sung","avatar":""},{"name":"Hyun Jyu-ni","avatar":""},{"name":"Lee Hye-sook","avatar":""},{"name":"Lee Han-wi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324479);
