INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('500-ngay-yeu', '(500) Ngày Yêu', '(500) Days of Summer', 'https://phimimg.com/upload/vod/20230917-1/241ce3b73f15bd85acfd1b1268f24489.jpg', 'https://phimimg.com/upload/vod/20230917-1/108673cba68a369dab87eb24bd06eb2b.jpg', '<p>Tom, người viết thiệp chúc mừng và là người lãng mạn vô vọng, hoàn toàn mất cảnh giác khi bạn gái anh, Summer, bất ngờ bỏ rơi anh. Anh ấy suy ngẫm về 500 ngày bên nhau của họ để cố gắng tìm hiểu xem mối tình của họ đã trở nên tồi tệ ở đâu, và khi làm như vậy, Tom đã tìm lại được niềm đam mê thực sự của mình trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 25, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Patricia Belcher","avatar":""},{"name":"Rachel Boston","avatar":""},{"name":"Minka Kelly","avatar":""},{"name":"Charles Walker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324479);
