INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-yeu-thuong', 'Giáng Sinh Yêu Thương', 'A Christmas Carol', 'https://phimimg.com/upload/vod/20230915-1/0c40701dfa3b7f15da6c8112ef6a6c29.jpg', 'https://phimimg.com/upload/vod/20230915-1/1da71d5245a95be6865a9a94ce206cdf.jpg', '<p><span style="font-family: &quot;Times New Roman&quot;; font-size: medium; text-wrap: wrap;">Giáng Sinh Yêu Thương dựa trên tác phẩm văn học kinh điển cùng tên của đại văn hào Charles Dicken kể về lão già keo kiệt Miser Ebenezer Scrooge bị đánh thức trong Lễ Giáng Sinh bởi một hồn ma. Trong phim hay này, hồn ma đã cho lão thấy cuộc sống của lão khốn khổ chừng nào và một tương lai kinh khủng đang chờ lão. Lão nhận ra rằng cuộc sống của lão đã trở nên đắng cay và ích kỷ từng ngày, và lão phải lựa chọn.</span></p>', 'Full', 1, 'hoathinh', 'completed', 30, 2009, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Steve Valentine","avatar":""},{"name":"Sage Ryan","avatar":""},{"name":"Amber Gainey Meade","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324479);
