INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-phu-bong-ro', 'Công Phu Bóng Rổ', 'Kung Fu Dunk', 'https://phimimg.com/uploads/movies/20260713/cong-phu-bong-ro-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/cong-phu-bong-ro-poster.webp', '<p>Cậu bé mồ côi Thế Kiệt (Châu Kiệt Luân) có kĩ năng ném bóng thần sầu. Kĩ năng này được chú Lập vô tình phát hiện ra, chú Lập lấy danh nghĩa tìm người thân lừa Thế Kệt tham gia vào đội bóng rổ để kiếm chác. Sau khi tham gia vào đội bóng rổ Thế Kiệt đem lòng yêu Ly Ly (Trác Thái Nghiên), còn Ly Ly đang yêu thầm Tiêu Phong. Liệu Thế Kiệt có thể giành chiến thắng? Thế Kệt có tìm được người nhà không? Con đường tình cảm của Thế Kiệt liệu có suôn sẻ không?</p>', 'Full', 1, 'single', 'completed', 55, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Jay Chou","avatar":""},{"name":"Charlene Choi Chuek-Yin","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Baron Chen","avatar":""},{"name":"Bryan Leung Kar-Yan","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Liu Geng-Hong","avatar":""},{"name":"Lee Li-Chun","avatar":""},{"name":"Shaun Tam Chun-Yin","avatar":""},{"name":"Huang Bo","avatar":""},{"name":"Yan Ni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Slam Dunk","Gong fu guan lan","Shaolin Basket","功夫灌籃","Guan lan","功夫灌篮"]', 1784690324479);
