INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cau-chuyen-lo-lem-khac', 'Một Câu Chuyện Lọ Lem Khác', 'Another Cinderella Story', 'https://phimimg.com/uploads/movies/20260713/mot-cau-chuyen-lo-lem-khac-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/mot-cau-chuyen-lo-lem-khac-poster.webp', '<p>Một chàng trai từng khiêu vũ với cô gái trong mơ tại một buổi dạ hội hóa trang giờ đây chỉ có duy nhất một manh mối về danh tính của cô: chiếc máy nghe nhạc Zune mà cô vô tình để lại khi vội vã chạy về nhà cho kịp giờ giới nghiêm. Đứng trước cơ hội ngàn năm có một, anh quyết định lên đường tìm kiếm người đẹp giấu mặt của mình.</p>', 'Full', 1, 'single', 'completed', 61, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Selena Gomez","avatar":""},{"name":"Drew Seeley","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Katharine Isabelle","avatar":""},{"name":"Emily Perkins","avatar":""},{"name":"Jessica Parker Kennedy","avatar":""},{"name":"Marcus T. Paulk","avatar":""},{"name":"Nicole LaPlaca","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"Lorena Gale","avatar":""},{"name":"Alex Zahara","avatar":""},{"name":"Colin Foo","avatar":""},{"name":"Garwin Sanford","avatar":""},{"name":"Jagoda Janik","avatar":""},{"name":"Laura Carswell","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["A Cinderella Story Two","Comme Cendrillon 2","Une autre histoire de Cendrillon","История Золушки 2