INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-kim-lien-di-ban', 'Phan Kim Liên dị bản', 'Sex Of Golden Plums', 'null', 'https://phimimg.com/upload/vod/20260604-1/c2154f11d07fd46a6bd79a3f4f802d40.jpg', '<p>Phim gồm 2 đĩa với sub Việt chuẩn. Nội dung phim kể về một thương gia giàu có đời nhà Bắc Tống. Khi chết trẻ, ông được quỷ vô thường lôi đến điện Diêm La gặp Diêm Vương hỏi tội. Diêm Vương đưa ra những bản cáo trạng về tội lỗi của hắn, nào là cướp vợ nhà lành, mua bán trinh tiết, gian dâm với phụ nữ, người hầu, gái già, gái trẻ dù trong gia trang hắn đầy vợ và thê thiếp… đặc biệt là vụ hắn giết chồng của Kim Liên. Hắn một mực chối tội và ở tận cùng sự khinh bỉ tên đê tiện, Diêm Vương tiết lộ một bí mật động trời mà hắn không ngờ đến…</p>', 'Full', 1, 'single', 'completed', 98, 2008, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Eddie Koo Koon Chung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Sex Of Golden Plums Part 2","金瓶梅禁传 下卷"]', 1784690324479);
