INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-8', 'Thị Trấn Smallville (Phần 8)', 'Smallville (Season 8)', 'https://phimimg.com/upload/vod/20250604-1/b5d6e67fc3f6b851e199f9d5b87eeeab.jpg', 'https://phimimg.com/upload/vod/20250604-1/50a567f5bb00aa50c627832aa4c5cd80.jpg', '<p>Ở mùa trước, Clark Kent và Lex Luthor đã chính thức trở thành kẻ thù không đội trời chung. Clark cũng khám phá ra thêm nhiều điều về hành tinh quê hương của mình, về cha mẹ ruột, về tương lai của bản thân và lý do vì sao cậu được gửi đến Trái Đất. Trong mùa tám, Clark Kent giờ đây là phóng viên tại tòa soạn Daily Planet và làm việc chung văn phòng với Lois Lane. Đồng thời, Metropolis cũng xuất hiện một anh hùng mới — người mà mọi người gọi bằng cái tên Red-Blue Blur (Bóng mờ Đỏ-Xanh).</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 14, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324479);
