INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-du-phan-6', 'Danh Dự (Phần 6)', 'One Tree Hill (Season 6)', 'https://phimimg.com/upload/vod/20260527-1/b8474dffacfd3fdb3bf308941adf2d88.jpg', 'https://phimimg.com/upload/vod/20260527-1/89d3370e5f2550b07921a45c12f4b251.jpg', '<p>Tại thị trấn Tree Hill thuộc bang Bắc Carolina, hai người anh em cùng cha khác mẹ chẳng có điểm gì chung ngoài một họ Scott. Lucas – một chàng trai sống nội tâm, thuộc tầng lớp lao động nghèo – là một thiên tài bóng rổ đường phố, nhưng tài năng của cậu chỉ được công nhận bởi nhóm bạn thân tại sân bóng bên bờ sông. Ngược lại, Nathan – chàng công tử nhà giàu, nổi tiếng và ngậm thìa vàng từ nhỏ – lại say sưa trong sự sùng bái của cả thị trấn với tư cách là ngôi sao sáng giá của đội bóng rổ trung học. Cả hai chàng trai đều là con của cựu cầu thủ bóng rổ đại học Dan Scott. Sự lựa chọn ruồng bỏ Lucas cùng người mẹ Karen từ nhiều năm trước của ông ta sẽ trở thành nỗi ám ảnh dai dẳng suốt cuộc đời, ngay cả trong cuộc sống hiện tại bên người vợ Deb và cậu con trai Nathan.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Lafferty","avatar":""},{"name":"Bethany Joy Lenz","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Robert Buckley","avatar":""},{"name":"Shantel VanSanten","avatar":""},{"name":"Jackson Brundage","avatar":""},{"name":"Lee Norris","avatar":""},{"name":"Lisa Goldstein Kirsch","avatar":""},{"name":"Stephen Colletti","avatar":""},{"name":"Tyler Hilton","avatar":""},{"name":"Paul Johansson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name"