INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-rock-phan-3', '30 Rock (Phần 3)', '30 Rock (Season 3)', 'https://phimimg.com/upload/vod/20260501-1/a5c094231905bb0d37f1ab5d11d0dfc4.jpg', 'https://phimimg.com/upload/vod/20260501-1/a6bceea7262d662b0752a2d5a85928ed.jpg', '<p>Jack theo đuổi tham vọng lớn hơn trong tập đoàn, đôi khi phải hy sinh nguyên tắc cá nhân. Liz thì ngày càng nhận ra cuộc sống của mình mất cân bằng hoàn toàn. Các nhân vật phụ như Tracy và Jenna không chỉ gây hài mà còn bộc lộ sự bất ổn phía sau danh tiếng.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 16, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Maulik Pancholy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 ROCK サーティー･ロック","サーティー･ロック","30 락","30락","30록","30 Rock"]', 1784690324479);
