INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-se', 'Chim Sẻ', 'The Sparrow', 'https://phimimg.com/upload/vod/20251012-1/e20bcd840ae3c0ee8673a2741dc2eded.jpg', 'https://phimimg.com/upload/vod/20251012-1/d658460ccb9101240ab5bba4011c2e86.jpg', '<p>Kei là thủ lĩnh giàu kinh nghiệm của một nhóm móc túi - còn được gọi là &quot;Chim sẻ&quot; trong tiếng lóng của HK. Anh thích lối sống vô tư chụp ảnh. Một ngày nọ, người đẹp bảnh bao Chun-Lei bất ngờ xuất hiện trong ống ngắm của Kei. Kei bị mê hoặc. Nhưng đằng sau vẻ ngoài hấp dẫn của Chun-Lei là một quá khứ bí ẩn và sứ mệnh giải phóng bản thân.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Kelly Lin Hsi-Lei","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Law Wing-Cheong","avatar":""},{"name":"Kenneth Cheung Moon-Yuen","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Henry Lo","avatar":""},{"name":"Jonathan Lee Yat-Sing","avatar":""},{"name":"Jackson Ha Chak-Shun","avatar":""},{"name":"Jeff Cheung Ka-Kit","avatar":""},{"name":"Hung Wai-Leung","avatar":""},{"name":"Chiang Lo","avatar":""},{"name":"Tong Pau-Chung","avatar":""},{"name":"Chris Chung","avatar":""},{"name":"Tang Tai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Man Jeuk","The Sparrow","スリ","Kieszonkowcy","スリ：2008","Sparrow","Sərçə","文雀"]', 1784690324479);
