INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chim-se', 'Chim Sẻ', 'The Sparrow', 'chim sẻ the sparrow simon yam kelly lin hsi-lei gordon lam ka-tung lo hoi-pang law wing-cheong kenneth cheung moon-yuen lam suet henry lo jonathan lee yat-sing jackson ha chak-shun jeff cheung ka-kit hung wai-leung chiang lo tong pau-chung chris chung tang tai man jeuk the sparrow スリ kieszonkowcy スリ：2008 sparrow sərçə 文雀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-can-giau-mat', 'Nghi Can Giấu Mặt', 'Suspect X', 'https://phimimg.com/upload/vod/20260418-1/685b2b9771f0dec1639e0a80f422b9e1.jpg', 'https://phimimg.com/upload/vod/20260418-1/835d65e823f7baa9ec14a16674c63a2a.jpg', '<p>Kể về cuộc đối đầu giữa nhà vật lý học thiên tài Yukawa và người bạn cũ, cũng là một nhà toán học thiên tài Ishigam. Tetsuya Ishigami, một nhà toán học thiên tài nhưng không gặp thời nên phải bằng lòng với cuộc sống của một giáo viên Toán cấp III sống độc thân không có bạn bè với một căn hộ bừa bộn. Xem phim này bạn sẽ thấy cuộc sống buồn bã của Ishigami thay đổi khi anh có hàng xóm mới – mẹ con nhà Yasuko Hanaoka. Trong một lần bị chồng cũ đến phá phách vòi tiền, mẹ con Hanaoka lỡ tay giết chết gã chồng vũ phu và đành phải nhờ vào trí tuệ của Ishigami để tìm ra một lối thoát. Không hổ danh là một nhà toán học thiên tài, Ishigami quả thực đã bằng cách nào đó dàn xếp để mẹ con Hanaoka có được chứng cớ ngoại phạm, một bài toán mà cảnh sát không thể giải nổi. Tất nhiên, Yukawa phải nhảy vào cuộc. Liệu cuộc đối đầu giữa tư duy trừu tượng của nhà toán học và tư duy thực nghiệm của nhà vật lý này ai sẽ chiến thắng?</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaharu Fukuyama","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Ikkei Watanabe","avatar":""},{"name":"Miki Maya","avatar":""},{"name":"Shinichi Tsutsumi","avatar":""},{"name":"Yasuko Matsuyuki","avatar":""},{"name":"Keishi Nagatsuka","avatar":""},{"name":"Hiroshi Shinagawa","avatar":""},{"name":"Dankan","avatar":""},{"name":"Miho Kanazawa","avatar":""},{"name":"Toru Masuoka","avatar":""},{"name":"Yasufumi Hayashi","avatar":""},{"name":"Ethan Amis","avatar":""},{"name":"Miyako Takayama","avatar":""},{"name":"Ryu Morioka","avatar":""},{"name":"Ito Tak","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yôgisha Ekkusu no kenshin","嫌疑人X的献身","神探伽俐略","容疑者X的献身","Yôgisha X no Kenshin","Suspect X","Devotion of Suspect","Yogisha Ekkusu no kenshin","嫌疑犯X的献身","ガリレオ 容疑者Xの献身","容疑者Xの献身：2008","神探伽俐略：嫌疑犯X的獻身","容疑者ｘの献身","容疑者Xの献身"]', 1784690324479);
