INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-dua-voi-zohan', 'Đừng Đùa Với Zohan', 'You Don''t Mess With The Zohan', 'https://phimimg.com/upload/vod/20260411-1/ef8360b7897b516732efe9b33237010a.jpg', 'https://phimimg.com/upload/vod/20260411-1/fea52a4403dad0070db1a20a483e4cca.jpg', '<p>Đừng Đùa Với Zohan (Đặc Vụ Cắt Tóc) là câu chuyện kể về việc quá chán nản với cuộc nội chiến dai dẳng ở quê hương, anh chàng đặc vụ Zohan quyết định bỏ trốn sang New York để thực hiện ước mơ của mình: trở thành một thợ hớt tóc. Trên quê hương mới, những sự cố dồn dập xảy đến khiến Zohan phải vận dụng những kỹ năng đặc vụ của mình để tồn tại, gây ra những tình huống cười chảy ra nước mắt.</p>', 'Full', 1, 'single', 'completed', 17, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Lainie Kazan","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Mariah Carey","avatar":""},{"name":"Yamit Sol","avatar":""},{"name":"Adria Tennor","avatar":""},{"name":"Daoud Heidami","avatar":""},{"name":"Dave Matthews","avatar":""},{"name":"Charlotte Rae","avatar":""},{"name":"Michael Buffer","avatar":""},{"name":"Ido Mosseri","avatar":""},{"name":"Sayed Badreya","avatar":""},{"name":"Robert Smigel","avatar":""},{"name":"Ido M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Не шутите с Зоханом","Dajte si pozor na Z