INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-dua-voi-zohan', 'Đừng Đùa Với Zohan', 'You Don''t Mess With The Zohan', 'đừng đùa với zohan you don''t mess with the zohan adam sandler emmanuelle chriqui john turturro nick swardson lainie kazan rob schneider kevin nealon mariah carey yamit sol adria tennor daoud heidami dave matthews charlotte rae michael buffer ido mosseri sayed badreya robert smigel ido m не шутите с зоханом dajte si pozor na zohana zohan - o agente bom de corte you don''t mess with the zohan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-biet-khoi-hanh', 'Tiễn Biệt (Khởi Hành)', 'Departures', 'https://phimimg.com/upload/vod/20260321-1/b9587baeb0795eba078ba2d1e1e584e4.jpg', 'https://phimimg.com/upload/vod/20260321-1/e24e66bdc759a9e48f010e4d3f37f41b.jpg', '<p>Daigo, một nghệ sĩ cello, bị sa thải khỏi dàn nhạc và cùng vợ chuyển về thị trấn nhỏ quê hương nơi chi phí sinh hoạt rẻ hơn. Tưởng rằng mình đang xin việc tại một công ty du lịch, anh phát hiện ra mình đang được phỏng vấn cho một công việc liên quan đến việc tiễn đưa người đã khuất mang tính chất lâu dài hơn – làm trợ lý cho người lo việc mai táng.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masahiro Motoki","avatar":""},{"name":"Hirosue Ryoko","avatar":""},{"name":"Tsutomu Yamazaki","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Toru Minegishi","avatar":""},{"name":"Tatsuo Yamada","avatar":""},{"name":"Yukiko Tachibana","avatar":""},{"name":"Yukari Tachibana","avatar":""},{"name":"Genjitsu Shu","avatar":""},{"name":"Taro Ishida","avatar":""},{"name":"Yukimi Koyanagi","avatar":""},{"name":"Hiroyuki Kishi","avatar":""},{"name":"Sanae Miyata","avatar":""},{"name":"Ryosuke Otani","avatar":""},{"name":"Mitsuyo Hoshino","avatar":""},{"name":"Tarō","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["送行者，礼仪师之奏","おくりびと","굿'' 바이","굿'' 바이: Good & Bye","A Partida","Departures","入殓师","Départs","Người Tiễn Đưa","Відбуття","送行者：禮儀師的樂章","Avsked","Despedidas","Odlasci","Ушедшие","''Plecări''","Pożegnani