INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madagascar-2-tau-thoat-den-chau-phi', 'Madagascar 2: Tẩu Thoát Đến Châu Phi', 'Madagascar: Escape 2 Africa', 'https://phimimg.com/upload/vod/20250316-1/2829cd35014299954fa72a7a75fe6b93.jpg', 'https://phimimg.com/upload/vod/20250316-1/58f7a00e178aed0215f25a8bf8c313c4.jpg', '<p>Thoát khỏi Madagascar, bộ tứ kỳ khôi lại mắc kẹt ở châu Phi với một rừng rắc rối: bị trục suất, thất tình, gặp kỳ phùng địch thủ và suýt làm mồi cho núi lửa...</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ben Stiller","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"David Schwimmer","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Bernie Mac","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"will.i.am","avatar":""},{"name":"Elisa Gabrielli","avatar":""},{"name":"Tom McGrath","avatar":""},{"name":"Chris Miller","avatar":""},{"name":"Christopher Knights","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"Qu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Madagascar 2","Madagascar - Escape 2 Africa","Madagascar 2 - La Grande Évasion","Madagaszkár 2","Madagascar 2 - La grande évasion","马达加斯加2","荒失失奇兵2：逃往非洲","Madagascar 2 - Escape 2 Africa","Madagaskar 2: Bijeg u Afriku","馬達加斯加2","Madagaskar 2: Útěk do afriky","Madagaskar 2","Madagaskar 2 - Útěk do afriky","Madagáscar 2","Mad