INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('madagascar-2-tau-thoat-den-chau-phi', 'Madagascar 2: Tẩu Thoát Đến Châu Phi', 'Madagascar: Escape 2 Africa', 'madagascar 2: tẩu thoát đến châu phi madagascar: escape 2 africa ben stiller chris rock david schwimmer jada pinkett smith sacha baron cohen cedric the entertainer andy richter bernie mac alec baldwin sherri shepherd will.i.am elisa gabrielli tom mcgrath chris miller christopher knights conrad vernon qu madagascar 2 madagascar - escape 2 africa madagascar 2 - la grande évasion madagaszkár 2 madagascar 2 - la grande évasion 马达加斯加2 荒失失奇兵2：逃往非洲 madagascar 2 - escape 2 africa madagaskar 2: bijeg u afriku 馬達加斯加2 madagaskar 2: útěk do afriky madagaskar 2 madagaskar 2 - útěk do afriky madagáscar 2 madagascar 2 : retour au bercail madagaskar 2 põgenemine aafrikasse мадагаскар 2 madagascar 2: escape para africa madagascar 2 - via dall''isola madagascar: the crate escape madagascar ii: escape 2 africa (2008) 荒失失奇兵 2 - 逃往非洲 madagascar 2: tẩu thoát đến châu phi マダガスカル2 madagascar: escape 2 africa', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-phan-4', 'Mất Tích (Phần 4)', 'Lost (Season 4)', 'https://phimimg.com/upload/vod/20260201-1/5b4446e8a10794ab099fb5fedaefbb34.jpg', 'https://phimimg.com/upload/vod/20260201-1/952814b639b0d46a24b05495db6b7761.jpg', '<p>Phim là câu chuyện về những con người sống sót trên chuyến bay Oceanic Airlines Flight 815 từ Sydney đến Los Angeles. Máy bay của họ rơi xuống một hòn đảo kỳ bí đâu đó ở Nam Thái Bình Dương với những hiện tượng không thể giải thích được. Xuyên suốt bộ phim là quá trình tìm kiếm đường trở về của những người sống sót, thông qua đó khám phá điều bí ẩn của hòn đảo và The Others - Một nhóm người đã ở trên đảo từ trước.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matthew Fox","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Terry O''Quinn","avatar":""},{"name":"Josh Holloway","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Nestor Carbonell","avatar":""},{"name":"Henry Ian Cusick","avatar":""},{"name":"Yunjin Kim","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Emilie de Ravin","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Zuleikha Robinson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["迷失 (2004)","گمشدگان","گمشده","ロスト","ＬＯ