INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-tich-phan-4', 'Mất Tích (Phần 4)', 'Lost (Season 4)', 'mất tích (phần 4) lost (season 4) matthew fox evangeline lilly terry o''quinn josh holloway michael emerson jorge garcia naveen andrews jeff fahey nestor carbonell henry ian cusick yunjin kim daniel dae kim emilie de ravin ken leung zuleikha robinson 迷失 (2004) گمشدگان گمشده ロスト ｌｏｓｔ　シーズン１ lost: zagubieni lost: naufragiaţii изгубљени izgubljeni kayıp lost', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-do-2-binh-doan-dia-nguc', 'Quỷ Đỏ 2: Binh Đoàn Địa Ngục', 'Hellboy II: The Golden Army', 'https://phimimg.com/upload/vod/20260129-1/2c8959cd850445425f00448b559c2631.jpg', 'https://phimimg.com/upload/vod/20260129-1/f12941603645565c6cf49fb9a6f50feb.jpg', '<p>Sau khi hiệp ước đình chiến từ xa xưa giữa loài người và vương quốc vô hình của sự huyền bí bị phá vỡ, một cuộc chiến dưới thế giới địa ngục có nguy cơ xảy ra. Một tên độc tài tàn ác đã thách thức cả thế giới loài người và thế giới âm ti, coi thường dòng máu huyết thống của hắn và làm sống dậy một đội quân không thể ngăn chặn được gồm những con quái vật khổng lồ. &nbsp;Trong phần 2 này, Hellboy sẽ phải đương đầu với những con quái vật hung tợn giữa thành phố và cùng khám phá những bí mật kinh hoàng về thế giới địa ngục. Sát cánh bên anh sẽ là cô gái Đuốc sống Liz Sherman...</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ron Perlman","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"John Alexander","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Luke Goss","avatar":""},{"name":"Anna Walton","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"John Hurt","avatar":""},{"name":"James Dodd","avatar":""},{"name":"Brian Steele","avatar":""},{"name":"Andrew Hefler","avatar":""},{"name":"Iván Kamarás","avatar":""},{"name":"Mike Kelly","avatar":""},{"name":"Jeremy Zimmermann","avatar":""},{"name":"Santiago Segura","avatar":""},{"name":"Roy Dotrice","avatar":""},{"name":"Aidan Cook","avatar":""},{"name":"Jeann","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be