INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-be-nguoi-ca-ponyo', 'Cô Bé Người Cá Ponyo', 'Ponyo', 'cô bé người cá ponyo ponyo yuria kozuki hiroki doi george tokoro tomoko yamaguchi yuki amami kazushige nagashima akiko yano shin''ichi hatori tokie hidari rumi hiiragi tomoko naraoka kazuko yoshiyuki eimi hiraoka nozomi ōhashi akiko takeguchi eiko kanazawa akihi ponyo on the cliff gake no ue no ponyo ponyo on the cliff by the sea ponyo y el secreto de la sirenita 悬崖上的金鱼公主 ponyo på klippen ved havet 벼랑 위의 포뇨 рыбка поньо на утесе поньо на кручі 悬崖上的金鱼姬 ponyo paa klippen ved havet 崖上的波兒 ponyo sur la falaise 厓上的波兒 ponjo z útesu nad mořem рыбка поньо на утёсе 崖上的波妞 崖上的波儿 ponyo: uma amizade que veio do mar 崖の上のポニョ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-phat-tac', 'Vùng Đất Quỷ Dữ: Phát Tác', 'Resident Evil: Degeneration', 'https://phimimg.com/upload/vod/20260119-1/f4e48003ed6fc884f71fbef631cec48e.jpg', 'https://phimimg.com/upload/vod/20260119-1/7a04ae8751b3fc7d3e31aed211ff01ec.jpg', '<p>Câu chuyện mở đầu vào mùa thu năm 2005 tại một phi trường tấp nập ở Hoa Kỳ. Tức là 7 năm sau vụ thả bom hạt nhân tại thành phố Raccoon. Một tổ chức khủng bố đã lén lút phát tán T-virus ra toàn bộ khu vực sân bay. &nbsp;Ngay lập tức, những thây ma bắt đầu hoành hành và cơn ác mộng tưởng chừng đã trôi vào dĩ vãng nay lại bùng nổ. Nguy cơ về một đại nạn toàn cầu là khó tránh khỏi. &nbsp;Leon S. Kennedy và Claire Redfield hợp tác cùng một đội đặc nhiệm để giải quyết tình hình trước khi T-virus bay ra ngoài không trung. Thời gian để thi hành nhiệm vụ khó khăn này chỉ vỏn vẹn gói gọn trong 4 giờ đồng hồ. Nếu thất bại, họ sẽ bị chính phủ cuốn văng cùng một đợt bom thiêu hủy khẩn cấp.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Paul Mercier","avatar":""},{"name":"Alyson Court","avatar":""},{"name":"Laura Bailey","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Crispin Freeman","avatar":""},{"name":"Michael Sorich","avatar":""},{"name":"Salli Saffioti","avatar":""},{"name":"Michelle Ruff","avatar":""},{"name":"Mary Elizabeth McGlynn","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Michael McConnohie","avatar":""},{"name":"Kirk Thornton","avatar":""},{"name":"Cindy Robinson","avatar":""},{"name":"Dave Wittenberg","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Kyle Hebert","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Biohazard: Degeneration","Resident Evil Degeneración","레지던트 이블 디제너레이션","生化危机1：恶化","바이오 하자드 디제네레이션","Resident Evil 1: Degeneration","Resident Evil (Animated) 1 Degeneration","バイオハザード：ディジェネレーション"]', 1784690324479);
