INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-quy-du-phat-tac', 'Vùng Đất Quỷ Dữ: Phát Tác', 'Resident Evil: Degeneration', 'vùng đất quỷ dữ: phát tác resident evil: degeneration paul mercier alyson court laura bailey roger craig smith crispin freeman michael sorich salli saffioti michelle ruff mary elizabeth mcglynn steve blum michael mcconnohie kirk thornton cindy robinson dave wittenberg kari wahlgren kyle hebert biohazard: degeneration resident evil degeneración 레지던트 이블 디제너레이션 生化危机1：恶化 바이오 하자드 디제네레이션 resident evil 1: degeneration resident evil (animated) 1 degeneration バイオハザード：ディジェネレーション', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-sung-lam-guong', 'Bẻ Sừng Làm Gương', 'Role Models', 'https://phimimg.com/upload/vod/20260115-1/d5fa30a9d23aaa8031748803a4a5cea9.jpg', 'https://phimimg.com/upload/vod/20260115-1/b47bbe41feafd806c8ec605a048fa11b.jpg', '<p>Danny và Wheeler, hai anh chàng bán hàng cho một hãng nước tăng lực, vô tình tông xe vào bức tượng của một ngôi trường. Tòa án cho họ lựa chọn: hoặc trải qua 30 ngày tù, hoặc tham gia chương trình giáo dục và tư vấn cho trẻ em. Chỉ sau một ngày ở cùng lũ trẻ, họ nhanh chóng nhận ra công việc này đầy thử thách hơn cả việc vào tù. Trong quá trình gắn bó, cả hai học được trách nhiệm, tình bạn và cách trưởng thành, còn lũ trẻ cũng nhận được sự quan tâm và hướng dẫn từ những người “hình mẫu” bất đắc dĩ.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Seann William Scott","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Bobb''e J. Thompson","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Kerri Kenney","avatar":""},{"name":"A.D. Miles","avatar":""},{"name":"Joe Lo Truglio","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Nicole Randall Johnson","avatar":""},{"name":"Allie Stamler","avatar":""},{"name":"Carly Craig","avatar":""},{"name":"Jessica Morris","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Roolimallit","Faça o Que Eu Digo, Não Faça o Que Eu Faço","老大哥计划","Un par nada ejemplar","Un Par Nada Ejemplar","사람 만들기","Mali duzi chłopcy","Role Models"]', 1784690324479);
