INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thac-loan-tren-bien', 'Thác Loạn Trên Biển', 'Donkey Punch', 'https://phimimg.com/upload/vod/20260109-1/9a4e764eb8568172b54d9f39babab15a.jpg', 'https://phimimg.com/upload/vod/20260109-1/3b509c15442d07144d75a66e5a42f1b1.jpg', '<p>Ba cô gái nóng bỏng, bốn chàng trai và một chiếc du thuyền siêu sang cùng nhau trải qua một đêm thác loạn với ma túy và tình dục. Tuy nhiên, một hành động trụy lạc đã đi quá xa, biến chuyến đi chơi của giới trẻ thành một cuối tuần hỗn loạn đẫm máu.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Nichola Burley","avatar":""},{"name":"Sian Breckin","avatar":""},{"name":"Jaime Winstone","avatar":""},{"name":"Robert Boulter","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Julian Morris","avatar":""},{"name":"Jay Taylor","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Coups Mortels","Coups mortels","Donkey Punch"]', 1784690324479);
