INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-diep', 'Kiếm Điệp', 'Butterfly Lovers', 'https://phimimg.com/upload/vod/20260109-1/385919a6b24d87dca0ea11358f5bdb38.jpg', 'https://phimimg.com/upload/vod/20260109-1/ada835dd08278a0803e7cb72c5564b5f.jpg', '<p>Zhu Yanzhi, cải trang thành đàn ông, tìm cách học võ thuật với một gia tộc tinh anh. Khi bắt đầu quá trình huấn luyện khắc nghiệt, Zhu nhận thấy mình mâu thuẫn với người huấn luyện kiêm cấp trên của mình, Liang.</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Charlene Choi Chuek-Yin","avatar":""},{"name":"Wu Chun","avatar":""},{"name":"Hu Ge","avatar":""},{"name":"Harlem Yu","avatar":""},{"name":"Xiong Xinxin","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Liu Kai","avatar":""},{"name":"Meng Fei","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Bonnie Xian","avatar":""},{"name":"Vincent Zheng","avatar":""},{"name":"Xue Jiangtao","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Hsu Yang","avatar":""},{"name":"Mang Fei","avatar":""},{"name":"Shaun Tam Chun-Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Sword Butterfly - Schwert des Schicksals","The Assassin''s Blade","武侠梁祝","剑蝶"]', 1784690324479);
