INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-soi-sa-mac', 'Chiến Dịch Sói Sa Mạc', 'The Hurt Locker', 'https://phimimg.com/upload/vod/20251214-1/4fac4328061544ae6c2c12f66fdf66ec.jpg', 'https://phimimg.com/upload/vod/20251214-1/f212648dc470ca66f7e1f7b058c96284.jpg', '<p>Bộ phim là câu chuyện về một trong những ngành nghề nguy hiểm nhất trên thế giới : tháo dỡ bom tại các điểm nóng của cuộc chiến tranh. Khi một trung sĩ tên James nhận nhiệm vụ trưởng nhóm tháo dỡ bom do một vài xung đột của các thành viên trong nhóm, anh đã làm hai cấp dưới của mình vô cùng ngạc nhiên. Sanbord và Eldridge đã vô cùng bất ngờ khi bị đẩy vào một trò chơi chết người trong cuộc chiến ở đô thị. James luôn tỏ ra lãnh đạm trước việc này. Và khi cả hai quyết định khống chế cấp trên của mình cũng là lúc bạo động biến thành phố trở nên hỗn loạn. Thân phận thật sự của James bị tiết lộ đã khiến cuộc đời hai chàng trai biến đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 21, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeremy Renner","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"David Morse","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Christian Camargo","avatar":""},{"name":"Christopher Sayegh","avatar":""},{"name":"David Gueriera","avatar":""},{"name":"Nabil Koni","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Sam Redford","avatar":""},{"name":"Erin Gann","avatar":""},{"name":"Malcolm Barrett","avatar":""},{"name":"Kristoffer Ryan Winters","avatar":""},{"name":"J.J.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Tödliches Kommando","Vivir al límite","Atrapados en Irak","Démineurs","Guerra ao Terror","ハート・ロッカー：2008","Toedliches Kommando The Hurt Locker","Echipa de foc","The Hurt Locker"]', 1784690324479);
