INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-ky-an-phan-2', 'Giang Hồ Kỳ Án (Phần 2)', 'The Gentle Crackdown (Season 2)', 'https://phimimg.com/upload/vod/20251124-1/4d2aca829a7bb828826ad567f38a4bd6.jpg', 'https://phimimg.com/upload/vod/20251124-1/3285861d47a0299d4f20160b9af5a7ae.jpg', '<p>Trần Tế Muội (Trịnh Hy Di) từ nhỏ mất cha, tính tình thẳng thắn, quyết chí giúp đỡ dân lành, nên được người dân ở huyện lương tài yêu mến. Đáng tiếc, cô làm việc lại hấp tấp vội vàng và quá nhiệt tình, nên đã hiểu lầm quan nông mới lên chức - Tạ Hoàng Thượng (Mã Tuấn Vĩ) là kẻ xấu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Niki Chow Lai-Kei","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Michelle Yim","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Halina Tam Siu-Wan","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Cindy Au","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"Mandy Lam Suk Man","avatar":""},{"name":"Ng Wai-San","avatar":""},{"name":"Candy Chiu Ching-Yee","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Sunny Tai Yiu-Ming","avatar":""},{"name":"Isa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Sau Choi Yu Jeuk Bing","秀才遇著兵"]', 1784690324479);
