INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ao-2008', 'Thế Giới Ảo', 'Pages of Treasures', 'https://phimimg.com/upload/vod/20251124-1/8161c6749fe01a2d52207a24cfb61e40.jpg', 'https://phimimg.com/upload/vod/20251124-1/9d60b56c34fa7b56849b02440ef538d0.jpg', '<p>Phương Học Văn luôn tin tưởng rằng “tri thức là sức mạnh”. Vì vậy, ông luôn cố gắng để đứa con lớn Phương Tâm Minh và đứa con thứ Phương Tâm Chánh được học hành tới nơi tới chốn. Nhưng Tâm Minh sau khi tốt nghiệp phổ thông không tiếp học nữa mà ra ngoài làm việc. Còn Chánh lại rất ham học và thông minh. Minh ra nước ngoài làm việc mong kiếm được nhiều tiền để Chánh được tiếp tục theo học ngành khoa học máy tính tại Mỹ. Vì công việc, hai anh em cùng trở về Hồng Kông và cùng làm trong một trung tâm thương mại. Chánh là kỹ sư an ninh mạng cấp cao còn Minh là nhân viên bảo an cấp thấp. Ông Phương lo lắng tình cảm anh em sẽ rạn nứt vì khoảng cách công việc khác nhau khá xa. Ông Văn mở kinh doanh một tiệm sách cũ nhằm chuẩn bị tương lai sau này cho Minh…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Paul Chun Pui","avatar":""},{"name":"Eric Suen Yiu-Wai","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Sonija Kwok Sin-Nae","avatar":""},{"name":"Sharon Chan Man-Chi","avatar":""},{"name":"Shirley Yeung Sze-Kei","avatar":""},{"name":"Vivien Yeo","avatar":""},{"name":"Jason Keng-Kwin Chan","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Fred Cheng Chun-Hung","avatar":""},{"name":"Wong Man-Biu","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Jason Chan Chi-San","avatar":""},{"name":"Chow Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Pages of Treasures","新网中人","新網中人","Click入黃金屋"]', 1784690324479);
