INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-nghi-thien-ha', 'Mẫu Nghi Thiên Hạ', 'The Queens', 'https://phimimg.com/upload/vod/20251110-1/84894e6d8fb449096f8cc1f45fcdbcdc.jpg', 'https://phimimg.com/upload/vod/20251110-1/26b367ff8feb78bc095fac6766714038.jpg', '<p>Phim kể về cuộc đời Vương Chính Quân - người phụ nữ bình thường nhưng nhờ trí tuệ, bản lĩnh và đức hạnh đã trở thành Hoàng hậu nhà Hán, rồi tiếp tục giữ ngôi vị Thái hậu qua nhiều triều đại. Bộ phim khắc họa hành trình đầy gian truân của bà trong chốn hậu cung hiểm ác, khi phải đối mặt với những âm mưu tranh quyền đoạt vị, tình thân và tình yêu. Tác phẩm vừa mang màu sắc lịch sử, vừa ca ngợi phẩm hạnh, sự kiên cường và tầm ảnh hưởng của một trong những nữ nhân quyền lực bậc nhất Trung Hoa.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 9, 2008, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Lệ Á","avatar":""},{"name":"Quách Trân Nghê","avatar":""},{"name":"Viên Lập","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["THE QUEENS","母仪天下"]', 1784690324479);
