INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ba-la-seora', 'Quý Bà (La Señora)', 'Lady', 'https://phimimg.com/upload/vod/20251104-1/682ca5e04f2dbdb7adda0052f5c4fbd2.jpg', 'https://phimimg.com/upload/vod/20251104-1/4864370a77e297ee6512b5f545bb359d.jpg', '<p>Vào những năm 1920, Victoria và Ángel yêu nhau tại một thị trấn nhỏ ở miền bắc Tây Ban Nha. Họ đến từ hai tầng lớp xã hội khác nhau, cô là con gái của một doanh nhân giàu có còn anh xuất thân từ một gia đình nghèo. Tình yêu của họ bị chia cách bởi các chuẩn mực xã hội và hoàn cảnh của thời đại đó. Nhiều năm sau, họ gặp lại nhau, Victoria là một nữ doanh nhân quyền lực còn Ángel giờ đây là một linh mục.</p>', 'Hoàn Tất (64/64)', 64, 'series', 'completed', 15, 2008, 'Thuyết Minh', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Ana Wagener","avatar":""},{"name":"Pepo Oliva","avatar":""},{"name":"Raúl Prieto","avatar":""},{"name":"Raúl Peña","avatar":""},{"name":"Manuela Vellés","avatar":""},{"name":"Nadia de Santiago","avatar":""},{"name":"Lucía Jiménez","avatar":""},{"name":"Adriana Ugarte","avatar":""},{"name":"Pedro Miguel Martínez","avatar":""},{"name":"Berta Ojea","avatar":""},{"name":"Carmen Conesa","avatar":""},{"name":"Rodolfo Sancho","avatar":""},{"name":"Álex González","avatar":""},{"name":"Roberto Enríquez","avatar":""},{"name":"Juan Meseguer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Señora"]', 1784690324480);
