INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-thieu-lam', 'Cô Gái Thiếu Lâm', 'Shaolin Girl', 'https://phimimg.com/upload/vod/20251028-1/fd9d8cf7782330019df9761e021aad94.jpg', 'https://phimimg.com/upload/vod/20251028-1/c2c09eecc9bb9e6985f795b1969a7dfc.jpg', '<p>Sau quá trình huấn luyện khắc nghiệt tại một trường võ thuật Thiếu Lâm, Lin trở về nhà. Cô mong muốn truyền bá nghệ thuật Kung Fu. Trong khi đó, một kẻ xấu tìm đến Lin để lấy đi sức mạnh của cô.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Ko Shibasaki","avatar":""},{"name":"Toru Nakamura","avatar":""},{"name":"Zhang Yuqi","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Lam Tze-Chung","avatar":""},{"name":"Takashi Okamura","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Mami Yamasaki","avatar":""},{"name":"Asagi Kudô","avatar":""},{"name":"Kana Harada","avatar":""},{"name":"Elly Otoguro","avatar":""},{"name":"Mayu Gamou","avatar":""},{"name":"Yûko Chino","avatar":""},{"name":"Aina Nishiaki","avatar":""},{"name":"Miyuu Sawai","avatar":""},{"name":"Asuka Ishii","avatar":""},{"name":"Asami Katsura","avatar":""},{"name":"Ayasa Hanagata","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kung Fu Girls","Shaolin Girl: Shaolin Soccer 2","Shôrin shôjo","少林少女"]', 1784690324480);
