INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-thieu-lam', 'Cô Gái Thiếu Lâm', 'Shaolin Girl', 'cô gái thiếu lâm shaolin girl ko shibasaki toru nakamura zhang yuqi tenky tin kai-man lam tze-chung takashi okamura yosuke eguchi mami yamasaki asagi kudô kana harada elly otoguro mayu gamou yûko chino aina nishiaki miyuu sawai asuka ishii asami katsura ayasa hanagata kung fu girls shaolin girl: shaolin soccer 2 shôrin shôjo 少林少女', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-kiem', 'Hồn Kiếm', 'The Spirit Of The Sword', 'https://phimimg.com/upload/vod/20251024-1/748e303816258e1d3dfdeaf8c5e54f24.jpg', 'https://phimimg.com/upload/vod/20251024-1/1c1a04297284073e250c6156e4a5c837.jpg', '<p>&quot;Hồn Kiếm&quot; (The Spirit Of The Sword) là một bộ phim võ thuật ấn tượng của điện ảnh Hong Kong, đưa khán giả vào một hành trình đầy kịch tính và sóng gió qua thế giới võ lâm Trung Nguyên. Được đạo diễn bởi Đàm Hữu Nghiệp và Trần Vịnh Ca, bộ phim đã để lại dấu ấn sâu đậm trong lòng khán giả yêu thích thể loại võ thuật. Câu chuyện của &quot;Hồn Kiếm&quot; xoay quanh chàng võ sĩ Nhật Bản mặc áo trắng, tay cầm bảo kiếm &quot;Trường Quang&quot;, người dũng cảm và đầy nhiệt huyết. Chàng đến Trung Nguyên với một mục tiêu cao cả: tìm kiếm bảy thanh kiếm huyền thoại, vốn được ví như bảo vật đỉnh cao của võ lâm, để hoàn thành di nguyện của sư phụ. Tuy nhiên, trên con đường gian nan ấy, chàng phải đối mặt với hàng loạt thách thức từ những cao thủ võ lâm và cả những âm mưu nguy hiểm từ ngụy quân tử Vương Điên và Mộc Lang Thần Quân. Trải qua những cuộc giao đấu đầy cam go, chàng gặp phải Phương Bảo Ngọc - người em cùng mẹ khác cha của mình. Tình thù giữa hai người dần nảy lửa, nhưng liệu đó có phải là số phận và âm mưu của kẻ xấu hay không? Bên cạnh đó, tình cảm giữa chàng và Châu Nhi, con gái của Vương Điên, cũng không ngừng thăng trầm trong những thử thách đầy nguy hiểm. Bên cạnh câu chuyện chính xoay quanh hành trình tìm kiếm bảo vật, &quot;Hồn Kiếm&quot; còn là một bức tranh đầy màu sắc về những mối quan hệ phức tạp giữa các nhân vật. Bạch Diễm Chúc, mẹ ruột của Đại Tạng và Bảo Ngọc, chứng kiến hai con mình trở thành kẻ thù, khiến trái tim bà đau đớn. Trên bề mặt, Tử Y Hầu - đệ nhất cao thủ võ lâm - dường như chỉ tập trung vào việc truy tìm Bạch Diễm Chúc, nhưng bên trong, anh nuôi hi vọng rằng Bảo Ngọc sẽ lật ngược số phận, biết sự thật và trả thù cho cha mình. Cuộc chiến giữa các phe phái võ lâm tất cả tập trung vào cổ thành La Á - nơi lưu giữ kho báu và bảo kiếm vang danh qua thế kỷ. Và khi mọi điều định đến đỉnh điểm, sự trỗi dậy của tình yêu và lòng trung thành cuối cùng cũng phá vỡ mọi âm mưu xấu xa, đưa mọi cuộc đấu đến hồi kết. &quot;Hồn Kiếm&quot; không chỉ là một bộ phim hành động võ thuật hấp dẫn mà còn là một tác phẩm nghệ thuật với những tình tiết lôi cuốn, những màn giao đấu mãn nhãn và những mảnh ghép tinh tế về tình cảm con người. Với sự tham gia của dàn diễn viên tài năng như Tạ Đình Phong, Chung Hân Đồng, Kiều Chấn Vũ, Y Năng Tĩnh, Đàm Diệu Văn, Dương Nhị, Triệu Hồng Phi, Châu Lợi, bộ phim đã tạo nên một cung bậc cảm xúc đa dạng và đong đầy cảm hứng cho người xem. Nếu bạn là một tín đồ của phim võ thuật cổ trang, không thể bỏ lỡ &quot;Hồn Kiếm&quot; - một tác phẩm điện ảnh đỉnh cao về võ nghệ và tình cảm, đem đến cho khán giả những giây phút giải trí đích thực. Hãy cùng Motchilltv khám phá bí ẩn của bảo kiếm và theo dõi cuộc hành trình đầy phiêu lưu của chàng võ sĩ Nhật Bản trong &quot;Hồn Kiếm&quot;!</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Patrick Tam Yiu-Man","avatar":""},{"name":"Zhao Hongfei","avatar":""},{"name":"Annie Shizuka Inoh","avatar":""},{"name":"Gillian Chung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The.New.Spirit.of.the.Sword","The Spirit Of The Sword"]', 1784690324480);
