INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-co-phieu', 'Nữ Hoàng Cổ Phiếu', 'The Money-Maker Recipe', 'https://phimimg.com/upload/vod/20251023-1/cdabd408f6c01a44718864a564169118.jpg', 'https://phimimg.com/upload/vod/20251023-1/ac3c9eb931f401716f4623e92c89484d.jpg', '<p>Dù là một môi giới cổ phiếu dày dạn kinh nghiệm, nhưng Hoàng Tử Thông (do Tạ Thiên Hoa đóng) lại không được lòng khách hàng vì quá nguyên tắc, cứng nhắc. Trong khi đó, một công ty mới với trang thiết bị hiện đại vừa khai trương, được quản lý bởi bậc thầy cổ phiếu Đinh Triệu Cảnh (do Lâm Gia Hoa đóng). Khách hàng lần lượt rời bỏ Thông để sang đầu tư cho công ty Cảnh.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 14, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kiki Sheung","avatar":""},{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Dominic Lam Ka-Wah","avatar":""},{"name":"Joyce Tang Lai-Ming","avatar":""},{"name":"Angela Tong Ying-Ying","avatar":""},{"name":"Toby Leung Ching-Kei","avatar":""},{"name":"Ellesmere Choi","avatar":""},{"name":"Leanne Li","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Suet Nei","avatar":""},{"name":"Rain Lau Yuk-Chui","avatar":""},{"name":"Alice Fung So-Bor","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Ng Wai-San","avatar":""},{"name":"Saman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Money-Maker Recipe","師奶股神"]', 1784690324480);
