INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-quy-huyen-thoai', 'Của Quý Huyền Thoại', 'A Tale of Legendary Libido', 'https://phimimg.com/upload/vod/20251024-1/559a0fd9acc97d456f4d60246efb5ba2.jpg', 'https://phimimg.com/upload/vod/20251024-1/d550fb301a3c777f2cd4a59b4fcb2364.jpg', '<p><span style="text-wrap-mode: wrap;">Những người phụ nữ trong làng của Byun chế nhạo việc anh ta thiếu ham muốn tình dục, nhưng Byun có tiếng cười cuối cùng khi một nhà sư lưu động truyền cho anh ta sức mạnh nam giới tối thượng.</span></p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bong Tae-gyu","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Youn Yuh-jung","avatar":""},{"name":"Jeon Su-gyeong","avatar":""},{"name":"Kwon Byung-gil","avatar":""},{"name":"Lee Jung-sub","avatar":""},{"name":"Seo Yeong","avatar":""},{"name":"Go Seo-hee","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Kim Ki-hyeon","avatar":""},{"name":"Park Young-seo","avatar":""},{"name":"Kwak Jin-mu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Legendary Libido","Của Quý Huyền Thoại","A Tale of Legendary Libido","가루지기"]', 1784690324480);
