INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ac-quai', 'Thiện, Ác, Quái', 'The Good, the Bad, the Weird', 'https://phimimg.com/upload/vod/20251023-1/68f94022c0c6124f1ce4a72c1ae43303.jpg', 'https://phimimg.com/upload/vod/20251023-1/082577c618a9324656acaef089be89d1.jpg', '<p>Vượt qua mọi kỷ lục trong nước về kinh phí sản xuất, “The Good, The Bad, The Weird” là phim có kinh phí sản xuất lớn nhất trong lịch sử điện ảnh Hàn Quốc (17 triệu USD ). “The Good, The Bad, The Weird” tái hiện lại Mãn Châu những năm 30 của thế kỷ trước, khi thế giới đang trong cảnh hỗn loạn. Lúc đó ở châu Á, Triều Tiên rơi vào bàn tay của phát xít Nhật. Nhiều người dân Triều Tiên đã tới vùng thảo nguyên hoang dã Manchuria, giáp ranh giữa Mông Cổ và Trung Quốc để lánh nạn. Và để tồn tại trong môi trường đầy khó khăn, một số người trở thành những tên cướp trên lưng ngựa để kiếm sống tại vùng đất hoang sơ cằn cỗi này. Bộ phim xoay quanh 3 nhân vật: The Good – Thiện (Jung Woo Sung), The Bad – Ác (Lee Byung Hun) và The Weird – Quái ...</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Ryu Seung-su","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Lee Chung-ah","avatar":""},{"name":"Kim Kwang-il","avatar":""},{"name":"Don Lee","avatar":""},{"name":"Son Jin-hwan","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Jo Kyung-hoon","avatar":""},{"name":"Lee Hang-soo","avatar":""},{"name":"Kang Hyun-joong","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Yoo Chang-sook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Joheunnom nabbeunnom isanghannom","The Good, the Bad. the Weird","Le Bon, la brute et le cinglé","El bueno, el malo y el raro","좋은 놈, 나쁜 놈, 이상한 놈","The Good, The Bad, The Weird","Os Invencíveis","Os Invisíveis","The Good the Bad the Weird","Hyvä, paha ja outo","グッド・バッド・ウィアード：2008","놈놈놈","Joeun nom, napun nom, esanghan nom"]', 1784690324480);
