INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-ac-quai', 'Thiện, Ác, Quái', 'The Good, the Bad, the Weird', 'thiện, ác, quái the good, the bad, the weird song kang-ho lee byung-hun jung woo-sung yoon je-moon ryu seung-su song young-chang son byung-ho oh dal-su lee chung-ah kim kwang-il don lee son jin-hwan park jin-woo jo kyung-hoon lee hang-soo kang hyun-joong lee sung-min yoo chang-sook joheunnom nabbeunnom isanghannom the good, the bad. the weird le bon, la brute et le cinglé el bueno, el malo y el raro 좋은 놈, 나쁜 놈, 이상한 놈 the good, the bad, the weird os invencíveis os invisíveis the good the bad the weird hyvä, paha ja outo グッド・バッド・ウィアード：2008 놈놈놈 joeun nom, napun nom, esanghan nom', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-2', 'Upin & Ipin (Phần 2)', 'Upin & Ipin (Season 2)', 'https://phimimg.com/upload/vod/20251022-1/5635b58d87b65913813b5238649f59f0.jpg', 'https://phimimg.com/upload/vod/20251022-1/2544ee07f31b9c23ddc655f1bc01e4b8.jpg', '<p>“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p>Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p><br/></p><p><br/></p>', 'Hoàn Tất (3/3)', 3, 'hoathinh', 'completed', 20, 2008, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324480);
