INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-sao-bang-hoi-ket-2008', 'Vườn Sao Băng: Hồi Kết', 'Hana Yori Dango: Final', 'https://phimimg.com/upload/vod/20250713-1/28aec14a663010c7932ec21438897509.jpg', 'https://phimimg.com/upload/vod/20250713-1/6dabb69e8e99fb9b1c70986bdfdb216f.jpg', '<p>Bộ phim dựa theo manga nổi tiếng cùng tên kể về chuyện tình cảm và tình bạn giữa một cô gái bình dân và bốn anh chàng F4 đẹp trai, con nhà quyền quý giàu có bậc nhất Nhật Bản. Sau bao nhiêu khó khăn, Tsukasa và Tsukushi cuối cùng sắp kết hôn. Tsukushi được mẹ chồng trao cho một món bảo vật gia truyền, nhưng bất ngờ đã bị một tên trộm cuỗm mất. Tsukushi, Tsukasa và ba thành viên còn lại của F4 tái hợp để truy tìm vật báu. Họ đã có một chuyến phiêu lưu vòng quanh thế giới, liệu 2 người có thể tìm lại món đồ đã mất và kết hôn hay không?</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mao Inoue","avatar":""},{"name":"Jun Matsumoto","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Shota Matsuda","avatar":""},{"name":"Tsuyoshi Abe","avatar":""},{"name":"Mariko Kaga","avatar":""},{"name":"Nanako Matsushima","avatar":""},{"name":"Natsuki Kato","avatar":""},{"name":"Akira","avatar":""},{"name":"Aki Nishihara","avatar":""},{"name":"Aki Fukada","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hana yori dango final","Hanadan final","Boys Before Flowers Final","Hana yori dango fainaru","Boys Over Flowers: The Movie","花样男子 Final","Boys Over Flowers Final","Hana yori Dango: Final","Boys Over Flowers: Final","花より男子 ファイナル","花样男子F","花より男子F"]', 1784690324480);
