INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-thach-luong-duyen', 'Kim Thạch Lương Duyên', 'A Journey Called Life', 'https://phimimg.com/upload/vod/20251008-1/15b4cf87f5ee4aa8d90d68d75057904c.jpg', 'https://phimimg.com/upload/vod/20251008-1/71941878a44c9501fc9fb6976b039167.jpg', '<p>Nội dung phim xoay quanh cuộc đời và số phận của Thi Gia Gia do Chung Gia Hân thủ vai. Thi Gia Gia vốn là một cô gái đanh đá. Vì mất mẹ sớm nên cô sống cuộc sống buông thả theo đám giang hồ. Một dịp tình cờ cô gặp gỡ và quen biết Nhật An – anh thanh niên hiền lành làm nghề đục đá cho xưởng đá Kim Thạch Ký. Tình yêu chân thành của An là động lực cho Gia Gia làm lại cuộc đời…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Steven Ma Chun-Wai","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Raymond Cho Wing-Lim","avatar":""},{"name":"Fala Chen","avatar":""},{"name":"Elaine Yiu","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Angelina Lo","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Samantha Chuk Man-Kwan","avatar":""},{"name":"Lee Tin-Cheung","avatar":""},{"name":"Hoffman Cheng","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Johnny Ngan Kwok-Leung","avatar":""},{"name":"Ti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Journey Called Life","金石良緣"]', 1784690324480);
