INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-xich-bich', 'Đại Chiến Xích Bích', 'Red Cliff', 'https://phimimg.com/upload/vod/20250915-1/dae5eb3054667d8fb97f02929a961ad7.jpg', 'https://phimimg.com/upload/vod/20250915-1/1db4a53389e8109eec243a2e20ea3ab3.jpg', '<p>Đối mặt với hạm đội thủy quân 80 vạn của Tào Tháo, Tôn Quyền cùng các triều thần nghe theo lời tiến cử của Chu Du, tạo thành liên minh Ngô - Thục kháng Tào. Trần giao tranh giữa hai thế lực hùng mạnh bắt đầu bằng trận chiến đánh dấu chiến thuật Bát Quái trận của kỳ tài Chu Du.</p>', 'Full', 1, 'single', 'completed', 22, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Jia","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Zhang Fengyi","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Lin Chi-Ling","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"You Yongzhi","avatar":""},{"name":"Hou Yong","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Baasanjav Mijid","avatar":""},{"name":"Zang Jinsheng","avatar":""},{"name":"Shan Zhang","avatar":""},{"name":"Wang Qingxiang","avatar":""},{"name":"Wang Hui","avatar":""},{"name":"Xie Gang","avatar":""},{"name":"Shi Xiaohong","avatar":""},{"name":"Xu","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["La Battaglia Dei Tre R