INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-xich-bich', 'Đại Chiến Xích Bích', 'Red Cliff', 'đại chiến xích bích red cliff song jia hu jun zhang fengyi tony leung chiu-wai takeshi kaneshiro chang chen zhao wei lin chi-ling shido nakamura you yongzhi hou yong tong dawei baasanjav mijid zang jinsheng shan zhang wang qingxiang wang hui xie gang shi xiaohong xu la battaglia dei tre regni la battaglia dei tre regni - parte seconda la battaglia dei tre regni - parte prima les trois royaumes, 1re partie 赤壁1 red cliff: part 1 red cliff 1 o porfyros lofos レッドクリフ parti red cliff ภาค 1 les 3 royaumes - partie 1 chi bi 적벽대전 1부-거대한 전쟁의 시작 적벽대전:거대한 전쟁의 시작 les trois royaumes, 1ère partie 赤壁 red cliff part i acantilado rojo (versión internacional) レッドクリフ part i：2008 red cliff i 赤壁（上） レッドクリフ partⅰ a batalha dos 3 reinos الجرف الأحمر (الجزء الأول)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-chuck-phan-2', 'Điệp Viên Chuck (Phần 2)', 'Chuck (Season 2)', 'https://phimimg.com/upload/vod/20250907-1/981442ac21864768de9d300b0d065aa3.jpg', 'https://phimimg.com/upload/vod/20250907-1/519f3a5f12730fa899dbcaafd6dbdc02.jpg', '<p>Chuck là bộ phim nói về một anh chàng tẻ nhạt bình thường không có gì nổi bật tên Chuck nhưng sau đó anh vô tình trở thành một điệp viên khi nhận được một mail kì lạ từ người bạn học cũ của anh tên Bryce. Bryce hiện đang làm việc cho CIA nên mail mà anh gửi cho Chuck có chứa nhiều bí mật trong đó nên vô tình khiến Chuck dính vào những vụ việc vô cùng rắc rối. Vì biết được 1 số bí mật nên CIA buộc phải bảo vệ anh đồng thời cho anh tham gia vào 1 số phi vụ vô cùng nguy hiểm.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Levi","avatar":""},{"name":"Yvonne Strahovski","avatar":""},{"name":"Joshua Gomez","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"Scott Krinsky","avatar":""},{"name":"Sarah Lancaster","avatar":""},{"name":"Mark Christopher Lawrence","avatar":""},{"name":"Ryan McPartlin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Чък","Praktoras... Sto Tsak","Πράκτορας... Στο Τσακ","チャック","CHUCK / チャック","Чак","宅男特務","Chuck"]', 1784690324480);
