INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-chuck-phan-2', 'Điệp Viên Chuck (Phần 2)', 'Chuck (Season 2)', 'điệp viên chuck (phần 2) chuck (season 2) zachary levi yvonne strahovski joshua gomez adam baldwin vik sahay scott krinsky sarah lancaster mark christopher lawrence ryan mcpartlin чък praktoras... sto tsak πράκτορας... στο τσακ チャック chuck / チャック чак 宅男特務 chuck', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-so-tu-than-l-thay-doi-the-gioi', 'Cuốn Sổ Tử Thần: L - Thay Đổi Thế Giới', 'Death Note: L Change The WorLd', 'https://phimimg.com/upload/vod/20250903-1/a0577af1a0780d5e83d2356d91d4dba0.jpg', 'https://phimimg.com/upload/vod/20250903-1/7cc643003a1a6651c73aa6c649c634f4.jpg', '<p>Bộ phim xoay quanh 23 ngày sống cuối cùng của L. L giải quyết vụ một nhóm khủng bố có ý định tiêu diệt loài người bằng loại vi-rút với tốc độc lây lan gấp 10 lần Ebola. Chúng bắt 1 cậu bé sống sót trong cuộc thử nghiệm của chúng tại ngôi làng nhỏ ở Thái Lan và một cậu học sinh trung học năm đầu dưới trướng của L tên Maki Nikaido. &nbsp;L sẽ đối mặt với vụ án như thế nào khi bên cạnh không còn những người mà anh tin cậy? Nội dung độc lập với manga Death Note, nhân vật L được khắc họa rõ nét hơn, sinh động hơn và đáng yêu hơn...</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenichi Matsuyama","avatar":""},{"name":"Narushi Fukuda","avatar":""},{"name":"Mayuko Fukuda","avatar":""},{"name":"Shingo Tsurumi","avatar":""},{"name":"Youki Kudoh","avatar":""},{"name":"Sei Hiraizumi","avatar":""},{"name":"Bokuzo Masana","avatar":""},{"name":"Yuta Kanai","avatar":""},{"name":"Megumi Sato","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Kiyotaka Nanbara","avatar":""},{"name":"Masanobu Takashima","avatar":""},{"name":"Shunji Fujimura","avatar":""},{"name":"Kazuki Namioka","avatar":""},{"name":"Hao Ganhane","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Asaka Se","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["死亡笔记3 L之终章","死亡笔记 : 改变世界","死亡笔记3","死亡笔记 III","DEATH NOTE: L – change the WorLd","DEATH NOTE 3: L – change the WorLd","DEATH NOTE: L, change the WorLd","DEATH NOTE 3","L: change the WorLd","Death Note III L Change the World","데스노트: L 새로운 시작","死亡笔记：L改变世界","L、最期の23日間。","L之終章 最後的23天","L change the WorLd"]', 1784690324480);
