INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuon-so-tu-than-l-thay-doi-the-gioi', 'Cuốn Sổ Tử Thần: L - Thay Đổi Thế Giới', 'Death Note: L Change The WorLd', 'cuốn sổ tử thần: l - thay đổi thế giới death note: l change the world kenichi matsuyama narushi fukuda mayuko fukuda shingo tsurumi youki kudoh sei hiraizumi bokuzo masana yuta kanai megumi sato renji ishibashi kiyotaka nanbara masanobu takashima shunji fujimura kazuki namioka hao ganhane erika toda asaka se 死亡笔记3 l之终章 死亡笔记 : 改变世界 死亡笔记3 死亡笔记 iii death note: l – change the world death note 3: l – change the world death note: l, change the world death note 3 l: change the world death note iii l change the world 데스노트: l 새로운 시작 死亡笔记：l改变世界 l、最期の23日間。 l之終章 最後的23天 l change the world', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-tinh-than', 'Sức Mạnh Tình Thân', 'Moonlight Resonance', 'https://phimimg.com/upload/vod/20231207-1/2eccc9d071faa03d47cf19a4a237749e.jpg', 'https://phimimg.com/upload/vod/20231207-1/83d51582a344760c40fee6635cebc0db.jpg', '<p>Sức Mạnh Tình Thân,&nbsp;Moonlight Resonance&nbsp;xoay quay gia đình tiệm bánh nổi tiếng Gia hảo nguyệt viên. Chung Tiếu Hà (do Lý Tư Kỳ đóng) và chồng là Cam Thái Tổ (do Hạ Vũ đóng) đã cùng nhau gầy dựng nên tiệm bánh từ hai bàn tay trắng. Họ có chung với nhau năm người con, các con lần lượt được đặt theo tên “Gia Hảo Nguyệt Viên Khánh Trung Thu”: Cam Vĩnh Gia (do Trần Hào đóng), Cam Vĩnh Hảo (do Lâm Phong đóng), Cam Vĩnh Viên (do Lê Nặc Ý đóng), Cam Vịnh Khánh (do Trần Pháp Lai đóng), Cam Vĩnh Trung (do Ôn Gia Hành đóng) và một người con gái nuôi là Tôn Hạo Nguyệt (do Dương Di đóng).&nbsp;</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2008, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324480);
