INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-chuot', 'Hiệp Sĩ Chuột', 'The Tale Of Despereaux', 'https://phimimg.com/upload/vod/20250827-1/c6c0fb69641f85c75d3ea4446e5f574c.jpg', 'https://phimimg.com/upload/vod/20250827-1/5f0fa77d5fe883e23413718411b4f46d.jpg', '<p>Chú chuột Despereaux Tilling bé nhỏ sinh ra với đôi mắt mở to, đôi tai vểnh cùng lòng nhiệt huyết và dũng cảm. Chú rất ham khám phá cuộc sống và luôn mong muốn được trải nghiệm những cuộc phiêu lưu thú vị. Tuy nhiên, ở vương quốc Dor, nơi Despereaux đang sống, người ta rất căm ghét loài chuột và tìm mọi cách đuổi chúng. Nguyên nhân là hoàng hậu vì nhìn thấy một chú chuột rơi vào bát súp đã chết ngất khiến vương quốc phủ một màu tang tóc. Một ngày kia, Despereaux liều lĩnh lẻn vào lâu đài hoàng gia đọc sách. Nơi đây, chú kết bạn với cô công chúa Pea, người luôn khao khát trốn khỏi lâu đài và cuộc sống tĩnh lặng bao trùm kể từ khi mẹ qua đời. Hành động của Despereaux đã khiến những con chuột khác tức giận và muốn đưa chú đi lưu đày. May mắn, chú đã được một kẻ lưu đày khác, chuột cống Ruscuro, giải cứu. Ngờ đâu Ruscuro chính là kẻ đã vô tình gây ra cái chết của hoàng hậu. Ruscuro sau khi nghe lời khuyên của Despereaux đã đến xin lỗi công chúa nhưng không được cô chấp nhận. Kể từ đó, Ruscuro quyết trả thù công chúa với sự giúp sức của Miggerey Sow, một cô hầu luôn mơ được làm công chúa. Khi Pea bị bắt cóc mang tới cho lũ chuột cống, Despereaux chợt nhận ra rằng, với sự quả cảm như một hiệp sĩ, chỉ có chú mới có thể cứu được công chúa của lòng mình.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Matthew Broderick","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Tracey Ullman","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Charles Shaughnessy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["双鼠记","Le Conte de Despereaux","大耳仔走天涯","浪漫的老鼠","סיפורו של דספרו","Despereaux - De Dappere Muis","Despereaux, de dappere muis","浪漫鼠德佩罗","Lugu hiirest nimega Despereaux","Priča o mišu zvanom Despero","El Valiente Despereaux","Пригоди Десперо","Ævintýri Despereaux","The Tale of Despereaux"]', 1784690324480);
