INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-vang', 'Chạng Vạng', 'Twilight', 'https://phimimg.com/upload/vod/20250812-1/9641c2dc6b6a2a873650ef26508f06d4.jpg', 'https://phimimg.com/upload/vod/20250812-1/62825b06546c4e356f77f1e284756ab0.jpg', '<p>Nội dung Twilight xoay quanh câu chuyện tình giữa một cô gái trẻ và một chàng trai ma cà rồng. Isabella Swan, 17 tuổi, thường gọi là Bella, từ Phoenix chuyển đến thị trấn nhỏ Forks, Washington sinh sống cùng cha Charlie Swan. Sự có mặt của cô ở đây đã làm các học sinh nam điêu đứng.Trong số các chàng trai xếp hàng theo đuổi mình, Bella đặc biệt để ý đến một chàng trai đầy vẻ bí ẩn và ma quái - Edward Cullen.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Nikki Reed","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Taylor Lautner","avatar":""},{"name":"Gil Birmingham","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Rachelle Lefevre","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Justin","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["暮光之城1","Crepusculo 1","La saga Crepúsculo: Crepúsculo","Twilight sága 1: Stmívání","The Twilight Saga 1: Twilight","The Twilight Saga - Biss zum Morgengrauen","Twilight 1 - Twilight - Biss zum Morgengrauen","Crepúsculo","The Twilight Saga","The Twilight Saga: Twilight","The Twilight Saga 1","Twilight 1","Alacatoranlıq","Մթնշաղ","吸血新世纪","گرگ و میش","Twilight"]', 1784690324480);
