INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-dot-sau-khi-doc', 'Hãy Đốt Sau Khi Đọc', 'Burn After Reading', 'https://phimimg.com/upload/vod/20250808-1/a6c749367ce7665257af6de8d74f867c.jpg', 'https://phimimg.com/upload/vod/20250808-1/f3b00d20ce7d9e947e3d0db05d804c4f.jpg', '<p>Bộ phim kể về điệp viên CIA Osbourne Cox (John Malkovich), người luôn tự hào với thành tích lẫy lừng bỗng dưng bị đuổi việc một cách sỗ sàng. Ông quyết định trả thù bằng cách viết hồi ký tiết lộ những chuyện bẩn thỉu ở hậu trường, về những tháng ngày đáng quên của mình trong quân ngũ với niềm tin cuốn sách sẽ gây tiếng vang lớn và lưu nó trong một chiếc đĩa dữ liệu. Trong khi đó, bà vợ Katie Cox (Tilda Swinton) luôn phải đối mặt với cuộc sống hôn nhân căng thẳng cùng ông chồng say mê với kế hoạch viết hồi ký, lại có quan hệ ngopài luồng với một viên cảnh sát liên bang bị ám ảnh vì phụ nữ Harry Pfarrer (George Clooney).</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"David Rasche","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Michael Countryman","avatar":""},{"name":"Kevin Sussman","avatar":""},{"name":"J.R. Horne","avatar":""},{"name":"Hamilton Clancy","avatar":""},{"name":"Armand Schultz","avatar":""},{"name":"Pun Bandhu","avatar":""},{"name":"Karla Mosle","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["После прочтения cжечь","Прочитати і спалити","Põletada peale lugemist","Spaliti nakon čitanja","Burn After Reading - Wer verbrennt sich hier die Finger?","Kafto aporrito","Kauto aporrito","Lire et détruire","Burn After Reading"]', 1784690324480);
