INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-dot-sau-khi-doc', 'Hãy Đốt Sau Khi Đọc', 'Burn After Reading', 'hãy đốt sau khi đọc burn after reading george clooney frances mcdormand brad pitt john malkovich tilda swinton richard jenkins elizabeth marvel david rasche j.k. simmons olek krupa michael countryman kevin sussman j.r. horne hamilton clancy armand schultz pun bandhu karla mosle после прочтения cжечь прочитати і спалити põletada peale lugemist spaliti nakon čitanja burn after reading - wer verbrennt sich hier die finger? kafto aporrito kauto aporrito lire et détruire burn after reading', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-loveru', 'To Love-Ru', 'To LOVE-Ru Trouble', 'https://phimimg.com/upload/vod/20250802-1/f03379680a971fc1ecac957cd90e1579.jpg', 'https://phimimg.com/upload/vod/20250802-1/66755a3c93662e7f48eaff459b5b64c6.jpg', '<p>Là một bộ anime hài hước lãng mạn kết hợp khoa học viễn tưởng. Nội dung chính xoay quanh cuộc sống của Yūki Rito, một nam sinh trung học bình thường, nhút nhát và không thể tỏ tình với cô gái mình thích là Sairenji Haruna.Một ngày nọ, khi đang ở trong bồn tắm, một cô gái ngoài hành tinh xinh đẹp tên là Lala Satalin Deviluke bất ngờ xuất hiện. Lala là công chúa của hành tinh Deviluke, và cô đang chạy trốn khỏi những người cầu hôn mà cha cô đã chọn.Một sự hiểu lầm xảy ra khi Rito vô tình chạm vào ngực của Lala. Theo phong tục của hành tinh cô, hành động này có nghĩa là họ đã đính hôn. Lala quyết định ở lại Trái Đất và sống cùng Rito, khiến cuộc sống của anh hoàn toàn đảo lộn.Bộ phim tập trung vào những rắc rối &quot;ecchi&quot; (tình huống gợi cảm) và hài hước khi Rito phải đối mặt với các tình huống khó xử liên quan đến Lala và những cô gái khác. Các nhân vật từ khắp vũ trụ liên tục xuất hiện, gây ra những tình huống dở khóc dở cười và khiến Rito phải &quot;vật lộn&quot; giữa tình cảm dành cho Haruna và trách nhiệm với Lala.</p><p><br/></p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 19, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akeno Watanabe","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Misato Fukuen","avatar":""},{"name":"Sayuri Yahagi","avatar":""},{"name":"Kanae Itou","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Ryoka Yuzuki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["出包王女","To Love-Ru","To LOVEるーとらぶるー","To LOVEるーとらぶるーダークネス","To LOVEるーとらぶるーダークネス 2nd","もっとTo LOVEるーとらぶるー","Motto To LOVE-Ru","투 러브-루 트러블","투 러브 트러블","To LOVE 트러블","Любовь и прочие неприятности","ทูเลิฟรู","ทูเลิฟรู ดาร์กเนส","To Love-Ru Trouble Darkness","Motto To Love Ru","To LOVE Ru Darkness","To LOVEる -とらぶる-"]', 1784690324480);
