INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('to-loveru', 'To Love-Ru', 'To LOVE-Ru Trouble', 'to love-ru to love-ru trouble akeno watanabe haruka tomatsu misato fukuen sayuri yahagi kanae itou aki toyosaki kaori nazuka ayako kawasumi ryoka yuzuki 出包王女 to love-ru to loveるーとらぶるー to loveるーとらぶるーダークネス to loveるーとらぶるーダークネス 2nd もっとto loveるーとらぶるー motto to love-ru 투 러브-루 트러블 투 러브 트러블 to love 트러블 любовь и прочие неприятности ทูเลิฟรู ทูเลิฟรู ดาร์กเนส to love-ru trouble darkness motto to love ru to love ru darkness to loveる -とらぶる-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-gium-co-chu-2008', 'Yêu Giùm Cô Chủ', 'Ngao Asoke', 'https://phimimg.com/upload/vod/20250712-1/f26e5921e60aed4cfc49a293f0936c56.jpg', 'https://phimimg.com/upload/vod/20250712-1/a7fb97f41daf54d169313e590dacd868.jpg', '<p>Monthai Mahataweit, một chàng trai trẻ 18 tuổi, điển trai và xuất chúng về mọi mặt, từ học vấn đến danh tiếng gia đình. Anh là con trai duy nhất của quan lớn Jao Khun Mahat và Khun Ying (Phu nhân) Tap Tim. Anh đang yêu Viyada Hiranwat, một cô gái xinh đẹp trẻ tuổi, được Khun Ying Tap Tim chấp thuận vì cô có địa vị và thân thế tương xứng. Bà cũng mong muốn hai người đính hôn trước khi Monthai đi du học nước ngoài.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 10, 2008, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Nawat Kulrattanarak","avatar":""},{"name":"Kanya Leenutapong","avatar":""},{"name":"Panward Hemmanee","avatar":""},{"name":"Karnjana Chindawath","avatar":""},{"name":"Oak Smith Arayaskul","avatar":""},{"name":"Kalaya Jirachaisakdecha","avatar":""},{"name":"Apinun Prasertwattanakul","avatar":""},{"name":"Pijittra Siriwetchapan","avatar":""},{"name":"Boriboon Junreurng","avatar":""},{"name":"Rungruang Anantaya","avatar":""},{"name":"Wiwat Phasomsab","avatar":""},{"name":"Paweena Charivsakul","avatar":""},{"name":"Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无忧花之影","Ngao Asoke","เงาอโศก","Shadow of the Sorrowless Flower"]', 1784690324480);
