INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ghep-tinh-yeu', 'Mảnh Ghép Tình Yêu', 'Definitely, Maybe', 'https://phimimg.com/upload/vod/20250618-1/b19cdbd87d69a1a29e1702bcc5762e05.jpg', 'https://phimimg.com/upload/vod/20250618-1/bb7f6aae795ec6b99c62fd1eb92a0770.jpg', '<p>Con đã được sinh ra thế nào? Bố đã gặp và yêu mẹ ra sao?... Đó có lẽ là những câu hỏi mà rất nhiều cô bé luôn thắc mắc với cha mẹ chúng. Definitely, Maybe cũng kể một câu chuyện giữa cha và con gái như thế, câu chuyện tình yêu giữa cha và mẹ trước khi có con, giống như một bài học lịch sử về tình yêu đầu đời với đầy đủ sự phức tạp mà trẻ thơ có lẽ sẽ không bao giờ hiểu được.</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Liane Balaban","avatar":""},{"name":"Annie Parisse","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"An Nguyen","avatar":""},{"name":"Adam Brooks","avatar":""},{"name":"Emily Wickersham","avatar":""},{"name":"Daniel Eric Gold","avatar":""},{"name":"Adam Ferrara","avatar":""},{"name":"Matthew Mason","avatar":""},{"name":"Ric","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["确定的可能","情迷三颗心","绝对，也许","Definitivamente Talvez","Koja je ona prava?","Kindlasti... võib-olla","Ehdottomasti ehkä","Sigoura, isos...","Noteikti, varbūt","Be abejo, turbūt","Definitivamente, tal vez","Helt sikkert, kanskje","Desigur... poate ca...","Да, возможно","Дефинитивно, можда","Katera je prava","Manh ghep tinh yeu","Urcite, mozná","Так, можливо","Так, ні, не знаю","Definitely, Maybe"]', 1784690324480);
