INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('manh-ghep-tinh-yeu', 'Mảnh Ghép Tình Yêu', 'Definitely, Maybe', 'mảnh ghép tình yêu definitely, maybe ryan reynolds abigail breslin elizabeth banks isla fisher rachel weisz kevin kline derek luke liane balaban annie parisse nestor serrano kevin corrigan an nguyen adam brooks emily wickersham daniel eric gold adam ferrara matthew mason ric 确定的可能 情迷三颗心 绝对，也许 definitivamente talvez koja je ona prava? kindlasti... võib-olla ehdottomasti ehkä sigoura, isos... noteikti, varbūt be abejo, turbūt definitivamente, tal vez helt sikkert, kanskje desigur... poate ca... да, возможно дефинитивно, можда katera je prava manh ghep tinh yeu urcite, mozná так, можливо так, ні, не знаю definitely, maybe', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-toi-la-gang-to', 'Cha Tôi Là Găng Tơ', 'Run Papa Run', 'https://phimimg.com/upload/vod/20250616-1/f10bf214dd1bcbf6e6ff41acb8b3f814.jpg', 'https://phimimg.com/upload/vod/20250616-1/3c1c167b171375c7e6d768c4096a2cc5.jpg', '<p>Khi có con với cô vợ luật sư Mỹ Bảo, đại ca Thiên Ân (Cổ Thiên Lạc) quyết &quot;đập đi xây lại&quot; cuộc sống. Xưa nay anh chỉ làm người tốt, chồng tốt, đại ca tốt nửa vời, liệu có thể làm người bố hoàn hảo?</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lưu Nhược Anh","avatar":""},{"name":"Miêu Khả Tú","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["一個好爸爸","一个好爸爸","Run Papa Run","我们这一家"]', 1784690324480);
