INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cha-toi-la-gang-to', 'Cha Tôi Là Găng Tơ', 'Run Papa Run', 'cha tôi là găng tơ run papa run cổ thiên lạc lưu nhược anh miêu khả tú 一個好爸爸 一个好爸爸 run papa run 我们这一家', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-8-tuoi', 'Cô Dâu 8 Tuổi', 'Little Bride', 'https://phimimg.com/upload/vod/20250525-1/797bf51bb676e91c9a52fb9f23df1dee.jpg', 'https://phimimg.com/upload/vod/20250525-1/f0420837f38be947634e4f4962bd562a.jpg', '<p>Câu chuyện xoay quanh Anandi, một bé gái mới 8 tuổi nhưng đã bị ép gả vào gia đình nhà chồng theo phong tục địa phương. Cô kết hôn với Jagdish, một cậu bé bằng tuổi. Từ đây, Anandi phải đối mặt với cuộc sống hôn nhân khi tuổi còn quá nhỏ: làm dâu, chịu đựng áp lực gia đình, xã hội, và những tổn thương từ sự bất công. Theo thời gian, Anandi trưởng thành và dần trở thành một người phụ nữ mạnh mẽ, kiên cường, đấu tranh cho công lý và quyền của phụ nữ, đặc biệt là trẻ em gái trong xã hội Ấn Độ. Song song với đó, phim cũng miêu tả sự thay đổi trong mối quan hệ giữa Anandi và Jagdish – từ tình bạn ngây thơ, đến tình cảm phức tạp khi họ trưởng thành và có những lựa chọn khác nhau trong cuộc đời.</p>', 'Hoàn Tất (1138/1138)', 1138, 'series', 'completed', 43, 2008, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Pratyusha Banerjee","avatar":""},{"name":"Avika Gor","avatar":""},{"name":"Shashank Vyas","avatar":""},{"name":"Avinash Mukherjee","avatar":""},{"name":"Anjum Farooki","avatar":""},{"name":"Mahima Makwana","avatar":""},{"name":"Sidharth Shukla","avatar":""},{"name":"Sriti Jha","avatar":""},{"name":"Roshni Walia","avatar":""},{"name":"Mahhi Vij","avatar":""},{"name":"Dishank Arora","avatar":""},{"name":"Ruslaan Mumtaz","avatar":""},{"name":"Yukti Kapoor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '["Anandhi","बालिका वधू","The Child Bride","Balika Vadhu"]', 1784690324480);
