INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-an-phan-2', 'Chạy Án (Phần 2)', 'Chay An (Season 2)', 'https://phimimg.com/upload/vod/20250604-1/2f769bf85f18a81a33cf95bce18fe5d5.jpg', 'https://phimimg.com/upload/vod/20250604-1/b1d10d5127107259dce4b987463111d9.gif', '<p><span style="text-wrap-mode: wrap;">Lấy cảm hứng từ vụ án Mai Văn Dâu, Chạy án tập trung vào cuộc đời của Cao Thanh Lâm (Việt Anh), con trai của Thứ trưởng Cao Đức Cẩm, học Thạc sĩ Tin học ở Mỹ và sau đó trở về nắm giữ vị trí Trưởng phòng thương mại điện tử ở ngân hàng Phú Tài do ông Trương Ngọc Trác đứng đầu. Tuy ông Cẩm là một cán bộ mẫu mực, đứng đắn, nhưng lại nhu nhược, để cho vợ là Dung thao túng gia đình, dựa vào danh nghĩa của chồng để làm ăn quan hệ với những doanh nghiệp trong tỉnh, và để Lâm được nuông chiều quá mức. Sau khi trở về, không những Lâm không thay đổi mà còn cấu bè kết phái với các phần tử bất hảo, chơi bời và dây vào xã hội đen khiến gia đình điêu đứng và gây ra những nguy hại về sau...</span></p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 20, 2008, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Việt Anh","avatar":""},{"name":"Phan Hòa","avatar":""},{"name":"Lê Dũng Nhi","avatar":""},{"name":"NSƯT Hương Dung","avatar":""},{"name":"Nguyễn Văn Báu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
