INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chun-buoc', 'Không Chùn Bước', 'Never Back Down', 'https://phimimg.com/upload/vod/20250526-1/e4db3ea0679adcf1cd85e7ea57374b4b.jpg', 'https://phimimg.com/upload/vod/20250526-1/ae2a63303438b6949891d7c5c403a864.jpg', '<p>Jake Tyler là một ngôi sao bóng đá rất được hâm mộ ở trường, nhưng mọi thứ đã thay đổi khi anh chuyển đến một trường trung học khác vì nơi đây, những người hùng thực sự lại là những anh chàng võ tổng hợp. Liệu Jake có thể tìm được chỗ đứng cho mình hay không khi anh không hề biết đấu võ và hơn nữa là bị cả đội võ tổng hợp ganh ghét vì anh đã cưa đổ cô nàng hoa khôi của trường?</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sean Faris","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Leslie Hope","avatar":""},{"name":"Wyatt Smith","avatar":""},{"name":"Neil Brown Jr.","avatar":""},{"name":"Lauren Leech","avatar":""},{"name":"Tilky Jones","avatar":""},{"name":"Steven Crowley","avatar":""},{"name":"Tom Nowicki","avatar":""},{"name":"Chele André","avatar":""},{"name":"Affion Crockett","avatar":""},{"name":"Chris Lindsay","avatar":""},{"name":"David Zelon","avatar":""},{"name":"Jonathan Eusebio","avatar":""},{"name":"Jocelyn Binde","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Never back down – Mai arrendersi","Never Back Down","Rompiendo las reglas","绝不退缩","Quebrando Regras","Chacun son combat","Ära iial tagane","Ne jamais reculer","Anypohoriti dynami","Nema predaje","Até ao Último Combate","Rendirse Jamás","Rendirse Jamas","Anypoxoriti dynami","The.Fighters.(2008)","Nikdy to nevzdávaj","The Fighters - Never Back Down"]', 1784690324480);
