INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-chun-buoc', 'Không Chùn Bước', 'Never Back Down', 'không chùn bước never back down sean faris amber heard cam gigandet djimon hounsou evan peters leslie hope wyatt smith neil brown jr. lauren leech tilky jones steven crowley tom nowicki chele andré affion crockett chris lindsay david zelon jonathan eusebio jocelyn binde never back down – mai arrendersi never back down rompiendo las reglas 绝不退缩 quebrando regras chacun son combat ära iial tagane ne jamais reculer anypohoriti dynami nema predaje até ao último combate rendirse jamás rendirse jamas anypoxoriti dynami the.fighters.(2008) nikdy to nevzdávaj the fighters - never back down', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nguoi-khong-lo-xanh', 'Doraemon: Nobita và Người Khổng Lồ Xanh', 'Doraemon: Nobita and the Green Giant Legend', 'https://phimimg.com/upload/vod/20250521-1/6cac6d5c6085b0cd232d738aba3fec20.jpg', 'https://phimimg.com/upload/vod/20250521-1/63494f95ba57911f3f6a8e8d6ed66c06.jpg', '<p>Phim Nobita Và Truyền Thuyết Thần Rừng mở đầu với cuộc đối thoại bí ẩn về sự biến đổi của thảm thực vật và môi trường trên Trái Đất: tình trạng tan băng, khai thác cạn kiệt đất đai, nước biển dâng cao, tình trạng đô thị hóa…, một lời nói đầy giận dữ: “Cơn phẫn nộ của diệp lục.” Nôbita nhặt được một cây con và giúp nó hoạt động được như động vật. Cậu đặt tên cho nó là Kibo. Kibo rất ham học, thích xem tivi – đặc biệt là những chuyên mục tin tức và giáo dục. Doraemon và nhóm bạn Nobita chơi đùa rất vui vẻ với Kibo. Nhưng một ngày nọ, họ thấy một vùng rừng biến mất và bị hút lên hành tinh của thực vật – nơi mà thực vật có một cuộc sống như của con người trên Trái Đất. Và cuộc hành trình của nhóm Doraemon bắt đầu từ đây…</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2008, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Takuya Yoshikoshi","avatar":""},{"name":"Maki Horikita","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Shihoko Hagino","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Eiga Doraemon Nobita to Midori no Kyojinden","Nobita and the Green Giant Legend","哆啦A夢：大雄與綠之巨人傳","도라에몽: 노비타와 녹색의 거인전","映画ドラえもん のび太と绿の巨人伝","도라에몽 극장판: 진구와 초록거인전","도라에몽: 진구와 초록거인전","映画ドラえもん のび太と緑の巨人伝"]', 1784690324480);
