INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-nguoi-khong-lo-xanh', 'Doraemon: Nobita và Người Khổng Lồ Xanh', 'Doraemon: Nobita and the Green Giant Legend', 'doraemon: nobita và người khổng lồ xanh doraemon: nobita and the green giant legend wasabi mizuta megumi oohara yumi kakazu tomokazu seki subaru kimura takuya yoshikoshi maki horikita chiaki fujimoto shihoko hagino eiga doraemon nobita to midori no kyojinden nobita and the green giant legend 哆啦a夢：大雄與綠之巨人傳 도라에몽: 노비타와 녹색의 거인전 映画ドラえもん のび太と绿の巨人伝 도라에몽 극장판: 진구와 초록거인전 도라에몽: 진구와 초록거인전 映画ドラえもん のび太と緑の巨人伝', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-anh-hung-xa-dieu-2008', 'Tân Anh Hùng Xạ Điêu', 'The Legend Of The Condor Heroes', 'https://phimimg.com/upload/vod/20250513-1/d239a690a06235bccc6ed7c9fe047ce0.jpg', 'https://phimimg.com/upload/vod/20230911-1/b4e6cdbd5c35baccec1c83cbde059283.jpg', '<p>Trong Tân Anh Hùng Xạ Điêu - The Legend Of The Condor Heroes, Lâm Y Thần vào vai Hoàng Dung, con gái đảo chủ đảo đào hoa Hoàng Dược Sư. Đóng cặp với Lâm Y Thần vẫn là Hồ Ca với vai Quách Tĩnh. Anh chàng vốn tư chất bình thường, là đồ đệ của Giang Nam thất quái. Tuy là người không thông minh nhưng Quách Tĩnh lại mang trong mình những phẩm chất của một nam nhi anh hùng: chính trực, chính nghĩa, dũng cảm. Chính vì thế đã khiến Hoàng Dung để ý. Sau bao khó khăn, cuối cùng Quách Tĩnh và Hoàng Dung cũng đến được bên nhau, hành tẩu giang hồ cùng nhau xây dựng gia đình.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 13, 2008, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Ca","avatar":""},{"name":"Lâm Y Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
