INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-gau-truc', 'Kung Fu Gấu Trúc', 'Kung Fu Panda', 'https://phimimg.com/upload/vod/20250412-1/28d0e5d858d0da867df3c72e693babd1.jpg', 'https://phimimg.com/upload/vod/20250412-1/f43d7d176441889842bf4d6b32dd767a.jpg', '<p>Khi kẻ xấu hùng mạnh phá hoại sự bình yên ở thung lũng của cậu, chú gấu trúc lười nhác đón nhận thử thách để đi theo định mệnh của mình – trở thành một võ hiệp.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jack Black","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"David Cross","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"James Hong","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Kyle Gass","avatar":""},{"name":"JR Reed","avatar":""},{"name":"Laura Kightlinger","avatar":""},{"name":"Tanya Haden","avatar":""},{"name":"Stephen Kearin","avatar":""},{"name":"Mark","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["쿵푸 팬더","Кунг-Фу Панда","კუნგ-ფუ პანდა","Kung Fu Panda : 2008","Κουνγκ Φου Πάντα 1","カンフー・パンダ","Công Phu Gấu Trúc","功夫熊猫","กังฟูแพนด้า จอมยุทธพลิกล็อค ช็อคยุทธภพ","Քունգ Ֆու Պանդա","Kung Fu Panda"]', 1784690324480);
