INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kung-fu-gau-truc', 'Kung Fu Gấu Trúc', 'Kung Fu Panda', 'kung fu gấu trúc kung fu panda jack black angelina jolie dustin hoffman ian mcshane jackie chan lucy liu seth rogen david cross randall duk kim james hong dan fogler michael clarke duncan wayne knight kyle gass jr reed laura kightlinger tanya haden stephen kearin mark thành long 쿵푸 팬더 кунг-фу панда კუნგ-ფუ პანდა kung fu panda : 2008 κουνγκ φου πάντα 1 カンフー・パンダ công phu gấu trúc 功夫熊猫 กังฟูแพนด้า จอมยุทธพลิกล็อค ช็อคยุทธภพ քունգ ֆու պանդա kung fu panda', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chinh-tri-gia-dong-tinh', 'Chính Trị Gia Đồng Tính', 'Milk', 'https://phimimg.com/upload/vod/20250324-1/d96831df3f066da97399b9f89e7256f1.jpg', 'https://phimimg.com/upload/vod/20250324-1/17fa23d7ebfcad2530f83f93f959cef7.jpg', '<p>Harvey Milk là một người đồng tính có quan điểm chính trị tích cực. Ông đã dấn thân vào con đường chông gai này với hi vọng sẽ thay đổi cái nhìn của xã hội về những người đồng tính. Sau hai chiến dịch tranh cử không thành công, năm 1977, ông đã giành được một ghế tại Ủy ban Giám sát San Francisco. Chiến thắng này cũng đánh dấu việc lần đầu tiên một người đồng tính có mặt trong Quốc hội Mỹ.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"James Franco","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Joseph Cross","avatar":""},{"name":"Stephen Spinella","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Lucas Grabeel","avatar":""},{"name":"Jeff Koons","avatar":""},{"name":"Brent Corrigan","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Elias McConnell","avatar":""},{"name":"Ashlee Temple","avatar":""},{"name":"Brandon B","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Milk","Milk - A Voz da Igualdade","Obywatel Milk","自由大道","밀크","Гарві Мілк","Milk: un hombre, una revolución, una esperanza"]', 1784690324480);
