INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-rung-xanh', 'Siêu Nhân Rừng Xanh', 'Power Rangers Jungle Fury', 'https://phimimg.com/upload/vod/20250320-1/5c5e00b45bdefdf4280b370217548819.jpg', 'https://phimimg.com/upload/vod/20250320-1/797af6d026dc5146fb5abec5e707a8bb.jpg', '<p>Siêu Nhân Rừng Xanh – Power Rangers Jungle Fury kể về 3 người trẻ tuổi đã được chọn để có thể bảo vệ và cứu Trái Đất khỏi một tên Dai Shi ác độc.Khi tên độc ác đó đã thoát khỏi sự giam cầm và hắn đã nhập vào thi thể người bạn đồng môn cũ của bọn họ.Cà 3 người họ đều được huấn luyện bởi các vị võ sư Kung Fu bậc nhất xuất thân từ những linh thú để bảo vệ cả thế giới.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Power Rangers Super Megaforce Finale: Legendary Battle","Power Rangers Super Megaforce: The Legendary Battle"]', 1784690324480);
