INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhan-rung-xanh', 'Siêu Nhân Rừng Xanh', 'Power Rangers Jungle Fury', 'siêu nhân rừng xanh power rangers jungle fury  power rangers super megaforce finale: legendary battle power rangers super megaforce: the legendary battle', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robot-biet-yeu', 'Robot Biết Yêu', 'WALL·E (WALL-E)', 'https://phimimg.com/upload/vod/20250319-1/c3b95a5547c174b188f9c48934df23de.jpg', 'https://phimimg.com/upload/vod/20250319-1/9d87007e2c39e06113ebaca633024a94.jpg', '<p>Trong tương lai, trái đất bị bao phủ bởi rác thải, loài người buộc phải rời khỏi trái đất và thay thế vào đó là hàng triệu con rô-bốt nhỏ bé với nhiệm vụ thu dọn rác thải cho đến khi trái đất có thể ở được. &nbsp;Nhưng chương trình đó thất bại chỉ trừ một chú robot nhỏ bé vẫn chăm chỉ làm công việc của mình, đó chính là WALL-E – robot duy nhất bị bỏ lại trên trái đất bắt đầu có một lỗi nhỏ trong hệ thống: phát triển tính cách của con người. WALL-E lãng mạn mơ ước rằng một ngày cậu sẽ kết giao được với ai đó, và cuộc đời này hẳn còn nhiều điều thú vị hơn công việc buồn tẻ mà cậu làm hàng ngày. &nbsp;Thế rồi EVE xuất hiện. EVE là cô người máy thăm dò có kiểu dáng đẹp, nhanh nhẹn, có thể bay và được trang bị súng laser. EVE thuộc hạm đội người máy được Phi trưởng của tàu Axiom cử xuống trái đất để làm nhiệm vụ kiểm tra bí mật. Theo đuổi EVE, WALL-E không thể ngờ rằng cậu sẽ vượt qua dải ngân hà và bước vào một chuyến phiêu lưu kỳ thú vượt xa sự tưởng tượng của chính mình.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2008, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Burtt","avatar":""},{"name":"Elissa Knight","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Kathy Najimy","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Lori Alan","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"John Cygan","avatar":""},{"name":"Pete Docter","avatar":""},{"name":"Paul Eiding","avatar":""},{"name":"Donald Fullilove","avatar":""},{"name":"Teresa Ganzel","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Sherry Lynn","avatar":""},{"name":"Mickie McGowan","avatar":""},{"name":"Laraine Newman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["WALL-E","월-E","ВАЛЛ-И","VALL-I","ვოლ·ი","Wall.E","WALL-E: RÔ-BỐT BIẾT IU","Người Máy Wall-E","WALL·E, batalló de neteja","VOL•İ","WALL·E"]', 1784690324480);
