INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('robot-biet-yeu', 'Robot Biết Yêu', 'WALL·E (WALL-E)', 'robot biết yêu wall·e (wall-e) ben burtt elissa knight jeff garlin fred willard john ratzenberger kathy najimy sigourney weaver lori alan bob bergen john cygan pete docter paul eiding donald fullilove teresa ganzel jess harnell sherry lynn mickie mcgowan laraine newman wall-e 월-e валл-и vall-i ვოლ·ი wall.e wall-e: rô-bốt biết iu người máy wall-e wall·e, batalló de neteja vol•i̇ wall·e', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-hoa-khong-co-hoa-hong', 'Cửa Hàng Hoa Không Có Hoa Hồng', 'Flower Shop Without Rose', 'https://phimimg.com/upload/vod/20250307-1/77f145355d9905dc84e3110849b470de.jpg', 'https://phimimg.com/upload/vod/20250307-1/aed324903598cd28f785f1a95c313937.jpg', '<p>Shiomi Eiji là một người bán hoa, đồng thời là ông bố đơn thân đang nuôi dạy cô con gái nhỏ Shizuku. Một ngày nọ, anh bắt gặp một người phụ nữ mù đang trú mưa dưới mái hiên tiệm hoa của mình và mời cô vào trong. Tưởng chừng chỉ là một cuộc gặp gỡ tình cờ, nhưng câu chuyện của họ dần hé lộ những bí mật ẩn giấu, khi tình yêu chớm nở lại bị cuốn vào một mạng lưới dối trá và động cơ đen tối. Mỗi nhân vật đều mang trong mình những nỗi đau thầm kín, và chẳng điều gì thực sự như vẻ bề ngoài.</p>', 'Full', 11, 'series', 'completed', 12, 2008, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shingo Katori","avatar":""},{"name":"Yuko Takeuchi","avatar":""},{"name":"Yumiko Shaku","avatar":""},{"name":"Shota Matsuda","avatar":""},{"name":"Yuika Motokariya","avatar":""},{"name":"Isao Bitō","avatar":""},{"name":"Susumu Terajima","avatar":""},{"name":"Junko Ikeuchi","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Yuuki Yagi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bara no nai Hanaya","沒有薔薇的花店","Flower Shop Without a Rose","The Flower Shop Without Roses","Flower Shop Without Roses","薔薇のない花屋"]', 1784690324480);
