INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-dinh-ky-2008', 'Lộc Đỉnh Ký', 'Royal Tramp', 'https://phimimg.com/upload/vod/20250303-1/676b63e4e25e38d02660ada2eff6b16c.jpg', 'https://phimimg.com/upload/vod/20250303-1/c67627bacdbd02baf0b39255ab3fbeb7.jpg', '<p>Lộc Đỉnh ký là bộ phim truyền hình Trung Quốc do Trương Kỷ Trung và Hoa Nghị huynh đệ sản xuất, chuyển thể từ tiểu thuyết cùng tên của nhà văn Kim Dung. Bộ phim gồm 50 tập, được phát sóng trên Đài truyền hình Giang Tô vào năm 2008, sau đó được phát sóng trên Đài truyền hình TVB của Hồng Kông và nhiều nước khác.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 13, 2008, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Hồ Khả","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Lý Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["鹿鼎记 2008","鹿鼎记","신 녹정기","녹정기"]', 1784690324480);
