INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-gia', 'Độc Giả', 'The Reader', 'https://phimimg.com/upload/vod/20250219-1/e2af114b672b33ec06b7945f99783ee5.jpg', 'https://phimimg.com/upload/vod/20250219-1/f6d98c5827ae569e0ebbbb2fe1995bd0.jpg', '<p>Một luật sư trung niên nhìn lại mối tình ngắn ngủi khi còn là thiếu niên với một phụ nữ lớn tuổi. Người đó cuối cùng bị xét xử vì tội ác chiến tranh của Đức Quốc xã 8 năm sau đó.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Kate Winslet","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"David Kross","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Jeanette Hain","avatar":""},{"name":"Hannah Herzsprung","avatar":""},{"name":"Karoline Herfurth","avatar":""},{"name":"Volker Bruch","avatar":""},{"name":"Alexandra Maria Lara","avatar":""},{"name":"Fabian Busch","avatar":""},{"name":"Vijessna Ferkic","avatar":""},{"name":"Susanne Lothar","avatar":""},{"name":"Matthias Habich","avatar":""},{"name":"Burghart Klaußner","avatar":""},{"name":"Sylvester Groth","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["A felolvasó","The Reader (El lector)","生死朗读","Σφραγισμένα Χείλη","Bralec","Predcítac","Skaitovas","Žena kojoj sam ćitao","Čitač","Una pasión secreta","Lektor","Okuyucu","더 리더: 책 읽어주는 남자","Читач","Der Vorleser","O Leitor","The Reader","El lector","Người Đọc Sách"]', 1784690324480);
