INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-khong-phong-bi', 'Thành Phố Không Phòng Bị', 'Open City', 'https://phimimg.com/upload/vod/20250211-1/3d3bcbeb6673da287e7d40f75773c24f.jpg', 'https://phimimg.com/upload/vod/20250211-1/828d7bb22fde3394a17255ae43c7439c.jpg', '<p>Jo Dae-yeong là một cảnh sát đang điều tra một băng nhóm móc túi có liên quan đến Yakuza. Một ngày nọ, anh cứu Baek Jang-mi khỏi nguy hiểm, chỉ để phát hiện ra rằng cô là trùm của băng nhóm mà anh đang truy lùng.</p>', 'Full', 1, 'single', 'completed', 22, 2008, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Kim Myung-min","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Yun Yeong-keol","avatar":""},{"name":"Lee Eun-mi","avatar":""},{"name":"Park Gil-su","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Oh Yeon-ah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Open City - Jäger und Gejagte","Mubangbi-dosi","무방비도시","Open City","Open City - Mubangbi-dosi","무방비 도시"]', 1784690324480);
