INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-pho-khong-phong-bi', 'Thành Phố Không Phòng Bị', 'Open City', 'thành phố không phòng bị open city son ye-jin kim myung-min kim hae-sook kim joon-bae park sung-woong yun yeong-keol lee eun-mi park gil-su yeom hye-ran kim won-jin oh yeon-ah open city - jäger und gejagte mubangbi-dosi 무방비도시 open city open city - mubangbi-dosi 무방비 도시', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vu-an-bi-an', 'Những Vụ Án Bí Ẩn', 'Detective Cheng Xu', 'https://phimimg.com/upload/vod/20250204-1/5fb732504a539f69ca24c6a9fadb54a3.jpg', 'https://phimimg.com/upload/vod/20250204-1/abe4542eebc09f54c54f4128045a186c.jpg', '<p>Những Vụ Án Bí Ẩn kể về việc thành cổ Long Thành trong 1 đêm liên tiếp xảy ra mấy vụ án mạng ly kỳ. Quần ma lộng hành ở Long Thành đã thức tỉnh 1 thám tử trầm lặng khá lâu, anh chính là Thành Huất, đệ nhất thám tử Long Thành. Hỗn loạn ở Long Thành lần này đã làm cho lời thề không ra tay của Thành Huất bị phá vỡ, khiến anh phải tái xuất giang hồ. Sống hay chết, thắng hay bại, mọi bí mật đều dần được bật mí qua những manh mối mà Thành Huất tìm thấy. Những vụ án bí ẩn sẽ được lật tẩy thế nào, mời các bạn cùng đón xem.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 11, 2008, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Vinh Quang","avatar":""},{"name":"Vương Lực Khả","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
