INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-co-dieu-toan-luu-ba-on-phan-9', 'Thần Cơ Diệu Toán Lưu Bá Ôn (Phần 9)', 'The Amazing Strategist Liu Bowen (Season 9)', 'thần cơ diệu toán lưu bá ôn (phần 9) the amazing strategist liu bowen (season 9) huỳnh thiếu kỳ dương hoài dân hoắc chính kỳ trần á lan giải bá ân dương tuấn ngạn tống đạt dân trần văn sơn vương vũ tiệp 神机妙算刘伯温 shen ji miao suan liu bo wen 神機妙算劉伯溫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-5', 'Bác Sĩ House (Phần 5)', 'House (Season 5)', 'https://phimimg.com/upload/vod/20250103-1/36bb16947e62e8eef760c4596a58ae4b.jpg', 'https://phimimg.com/upload/vod/20250103-1/a4bb9825166e5272b9d5cf149f1ea69c.jpg', '<p>Trong phần cuối của Phần 4, sau một vụ tai nạn xe buýt lớn khiến House không còn nhớ gì về vụ tai nạn, anh và nhóm đã ghép các mảnh ký ức của mình lại với nhau và phát hiện ra bạn gái của Wilson là Amber đang ở trên xe buýt với anh và bị thương nặng. Wilson phải đối mặt với sự thật kinh hoàng rằng House có liên quan đến cái chết của Amber. Khi Phần 5 mở đầu, khi tình bạn của anh với Wilson tan vỡ, House phải xác định xem liệu anh có phải chịu trách nhiệm về cái chết của Amber hay không và Wilson phải quyết định xem liệu House có phải là thế lực hủy diệt cuộc đời anh hay không trong khi Cuddy cố gắng thúc đẩy sự hòa giải giữa hai người họ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324480);
