INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-house-phan-5', 'Bác Sĩ House (Phần 5)', 'House (Season 5)', 'bác sĩ house (phần 5) house (season 5) hugh laurie robert sean leonard omar epps jesse spencer odette annable peter jacobson charlyne yi doctor house 豪斯医生 house - medical division دکتر هاوس ドクター・ハウス 닥터 하우스 доктор гаус house m.d. house', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-dong-vuon-dia-dang-2008', 'Phía Đông Vườn Địa Đàng', 'East Of Eden', 'https://phimimg.com/upload/vod/20241229-1/bdd6b9142c51170ea31495690ab4321b.jpg', 'https://phimimg.com/upload/vod/20241229-1/af058dc523b789b54a1548b4c6dcf32d.jpg', '<p>Lee Ki Chul - một thợ mỏ lãnh đạo các cuộc vận động đòi quyền lợi của công nhân, đã bị hại chết trong một sự cố sập hầm. Dong Chul là người duy nhất chứng kiến toàn bộ âm mưu đó và thề rằng sẽ trả thù kẻ đã gây ra cái chết của cha.

Nhưng không ai ngoại trừ một y tá, biết rằng người em trai của Dong Chul, Dong Wook, khi mới lọt lòng đã bị cô y tá đó tráo đổi với con trai của Shin Tae Hwan, Myung Hun. Dong Wook lớn lên với ước mơ trở thành một công tố viên để đòi lại công bằng cho gia đình và trả thù Shin Tae Hwan. Myung Hun cũng được nuôi dạy trong gia đình họ Shin nhưng luôn đau khổ vì người cha độc ác của mình.

Nhiều năm sau, Dong Chul trở thành cánh tay phải của chủ tịch Gook, ông vua của giới sòng bạc, phụ trách quản lý sòng bạc Slot machine và thực hiện kế hoạch trả thù Shin Tae Hwan. Dong Wook là một công tố viên đầy năng lực trong tổ điều tra đặc biệt Seoul. Đồng thời, Yoo Mi Ae, người y tá năm xưa cũng đã quay trở về để trả thù Shin Tae Hwan và tiết lộ bí năm xưa...</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 10, 2008, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Seung-heon","avatar":""},{"name":"Yeon Jeong-hun","avatar":""},{"name":"Park Hae-jin","avatar":""},{"name":"Lee Da-hae","avatar":""},{"name":"Han Ji-hye","avatar":""},{"name":"Lee Yeon-hee","avatar":""},{"name":"Jo Min-ki","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Yoo Dong-geun","avatar":""},{"name":"Shin Dong-woo","avatar":""},{"name":"Ian Kim Beom","avatar":""},{"name":"Park Gun-tae","avatar":""},{"name":"Nam Ji-hyun","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Jeong So-yeong","avatar":""},{"name":"Dennis Oh","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Hwang Jung-eum","avatar":""},{"name":"Jeon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["에덴의 동쪽","애덴의 동쪽","伊甸之東","East of Eden"]', 1784690324480);
