INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-than-chet', 'Nụ Hôn Thần Chết', 'The Kiss Of Death', 'https://phimimg.com/upload/vod/20241117-1/73282b87040a1fc176306050844c13f5.jpg', 'https://phimimg.com/upload/vod/20241117-1/3f4cb81033b2b7e5ed9a0a6f8c7d05c6.jpg', '<p>Hài hước, lãng mạn và pha chút kinh dị, &quot;Nụ Hôn Thần Chết&quot; được xem là một hiện tượng của phim Việt năm 2008. Thần chết Du &quot;mới vào nghề&quot; trong lần &quot;làm việc&quot; đầu tiên đã phải lòng cô gái xinh đẹp mà anh phải &quot;bắt hồn&quot;. Nhưng nếu không hoàn thành sứ mệnh, chính anh sẽ phải hứng chịu lời nguyền khủng khiếp từ cha mình. Liệu tình cảm hồn nhiên, chân thành giữa hai người có thể vượt qua những rào cản định kiến của hai cõi âm - dương?</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thanh Hằng","avatar":""},{"name":"Johnny Nguyen","avatar":""},{"name":"Hoài Linh","avatar":""},{"name":"Phương Thanh","avatar":""},{"name":"Hương Giang","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Tommy Quân Trần","avatar":""},{"name":"Vinh Thuy","avatar":""},{"name":"Thủy Tiên","avatar":""},{"name":"Vũ Ngọc Đãng","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Trinh Hoan Nguyen","avatar":""},{"name":"Doan Minh Tuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Nụ hôn thần chết"]', 1784690324480);
