INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-cua-saddam', 'Ngôi Nhà Của Saddam', 'House of Saddam', 'https://phimimg.com/upload/vod/20241102-1/1eb63529b6fda75c6b9e48897e05c03c.jpg', 'https://phimimg.com/upload/vod/20241102-1/7a5bc544f10fdf559ff601d212e838ff.jpg', '<p>Thế giới riêng tư của Saddam Hussein và những người thân cận nhất của ông được khắc họa trong bộ phim truyền hình bốn phần hấp dẫn này, kể về sự trỗi dậy và sụp đổ của một trong những nhân vật chính trị quan trọng nhất trong lịch sử gần đây.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 10, 2008, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Christine Stephen-Daly","avatar":""},{"name":"Shohreh Aghdashloo","avatar":""},{"name":"Makram J. Khoury","avatar":""},{"name":"Igal Naor","avatar":""},{"name":"Daniel Lundh","avatar":""},{"name":"Uri Gavriel","avatar":""},{"name":"Agni Scott","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Amber Rose Revah","avatar":""},{"name":"Saïd Amadis","avatar":""},{"name":"Philip Arditti","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Akbar Kurtha","avatar":""},{"name":"Mounir Margoum","avatar":""},{"name":"Shivani Ghai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["הבית של סדאם","Дом Саддама","Between Two Rivers","House of Saddam"]', 1784690324480);
