INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-cua-saddam', 'Ngôi Nhà Của Saddam', 'House of Saddam', 'ngôi nhà của saddam house of saddam christine stephen-daly shohreh aghdashloo makram j. khoury igal naor daniel lundh uri gavriel agni scott saïd taghmaoui amber rose revah saïd amadis philip arditti amr waked akbar kurtha mounir margoum shivani ghai הבית של סדאם дом саддама between two rivers house of saddam', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-iljimae', 'Huyền Thoại Iljimae', 'Iljimae', 'https://phimimg.com/upload/vod/20241030-1/8d33d6fc230f74149bc640343206190d.jpg', 'https://phimimg.com/upload/vod/20241030-1/db998c1504b22467abccc55c41fc75a9.jpg', '<p>Lee Geom (이겸) là con trai của nhà quý tộc Lee Won Ho (이원호). Lee Won Ho là em trai và cũng là tâm phúc của vua Joseon lúc bấy giờ và là một thành viên của tổ chức Thiên Hữu hội. Thuở nhỏ, Lee Geom có một cuộc sống hạnh phúc cùng cha mẹ và chị gái trong một căn nhà trồng đầy hoa mai. Thế nhưng, cuộc sống ấy kéo dài không bao lâu thì tai họa ập tới. Trong một lần nhà vua gặp gỡ một vị tiên tri mù, ông ta đã nói cho vua nghe về một mặt trời khác, sau này người có mặt trời ấy sẽ được người dân yêu mến, và người mang mặt trời ấy đang ở trong nhà Lee Won Ho. Sợ hãi về điều này, nhà vua ra lệnh cho người vu khống Won Ho tội mưu phản rồi sai người bí mật giết. Trước khi bị giết, ông đã đem Geom cất giấu vào một chiếc tủ và dặn dò cậu nhất định phải sống. Vì ở trong tủ nên cậu chứng kiến toàn bộ cảnh cha bị giết, sau này lại phải tự tay ném đá vào người mẹ ruột mình để chứng minh bản thân không phải con trai Lee Won Ho. Vì vậy cậu đã lập một lời thề, nhất định sau này lớn lên sẽ trả thù cho cha, tuy nhiên sau một trận ốm nặng, cậu đã quên hết mọi chuyện. 13 năm sau, lúc này Geom đang lưu lạc trong dân gian với cái tên Yong (용) và được nhận nuôi bởi Swe Dol (쇠돌), một tên trộm tài ba nay đã rửa tay gác kiếm. Trong một lần suýt chết, cậu đã dần dần nhớ lại quá khứ năm xưa, bắt đầu đi tìm mẹ và chị gái đang lưu lạc. Tuy nhiên, chị gái Geom, Yeon (연) vì không chịu phục tùng một tên lính xấu xa đã nhỡ tay đánh chết hắn, vì vậy cô bị xử treo cổ. Cái chết của chị gái khiến Geom đau đớn tột cùng và tìm cách trả thù cũng như truy tìm sự thật năm xưa. Với manh mối duy nhất là biểu tượng trên thanh kiếm đã giết chết cha mình, cứ đêm đến cậu lại cải trang đi ăn trộm ở những nhà quý tộc là hội viên Thiên Hữu hội để tìm ra chủ nhân thanh kiếm ấy. Bởi vì mỗi khi ăn trộm xong cậu đều để lại ở chỗ trộm một tờ giấy có vẽ cành hoa mai đỏ, thế nên cậu được người đời đặt tên là Iljimae (일지매 - Nhất Chi Mai). Thường thường sau khi trộm, Geom thường đem những của cải ấy chia cho người nghèo, vì vậy cậu được dân chúng yêu mến và trở thành một huyền thoại. Dần dần về sau, những bí mật trong quá khứ năm xưa dần sáng tỏ, và kể từ đó người ta đồn rằng Iljimae đã chết.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2008, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이준기","avatar":""},{"name":"한효주","avatar":""},{"name":"박시후","avatar":""},{"name":"이영아","avatar":""},{"name":"김성령","avatar":""},{"name":"안길강","avatar":""},{"name":"김창완","avatar":""},{"name":"이원종","avatar":""},{"name":"여진구","avatar":""},{"name":"김유정","avatar":""},{"name":"이다윗","avatar":""},{"name":"정다빈","avatar":""},{"name":"이일화","avatar":""},{"name":"Noh Young-hak","avatar":""},{"name":"Yeon Jun-seok","avatar":""},{"name":"이문식","avatar":""},{"name":"손태영","avatar":""},{"name":"김무열","avatar":""},{"name":"Lee Won-jae","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["一枝梅","Iljimae","Il Ji-Mae: The Phantom Thief","Huyền thoại Iljimae","일지매"]', 1784690324480);
