INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-iljimae', 'Huyền Thoại Iljimae', 'Iljimae', 'huyền thoại iljimae iljimae 이준기 한효주 박시후 이영아 김성령 안길강 김창완 이원종 여진구 김유정 이다윗 정다빈 이일화 noh young-hak yeon jun-seok 이문식 손태영 김무열 lee won-jae 一枝梅 iljimae il ji-mae: the phantom thief huyền thoại iljimae 일지매', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-2', 'Bằng Chứng Thép (Phần 2)', 'Forensic Heroes (Season 2)', 'https://phimimg.com/upload/vod/20241029-1/d2891408c4664a5ca458376e1f68f44c.jpg', 'https://phimimg.com/upload/vod/20241029-1/584e1191210e54a9eb6b045106fd4d14.jpg', '<p>Chuyên gia tháo mìn Dương Dật Thăng (Trịnh Gia Dĩnh) từ Anh trở về Hồng Kông thăm người thân, tình cờ vướng vào vụ án cài mìn. Thái độ làm việc bình tĩnh chuyên nghiệp của Thăng rất được bác sĩ xét nghiệm cao cấp Cao Nhan Bác (Âu Dương Chấn Hoa) xem trọng và khen ngợi. Sau cùng Thăng quyết định gia nhập tổ Pháp Chứng, và nhanh chóng trở thành người nổi tiếng của tổ. Tình bạn bị gián đoạn hơn 15 năm của Thăng và nhân viên pháp y Cổ Trạch Thâm (Lâm Văn Long) cũng được nối lại. Vợ sắp cưới của Thâm chẳng may mất mạng trong 1 vụ án; bạn gái của Bác trong tổ Trọng án Lương Tiểu Nhu (Mông Gia Tuệ) cũng gặp tai nạn, mất khả năng cầm súng, công việc bắt buộc phải chuyển giao cho Mã Quắc Anh (Xa Thi Mạn) phòng điều tra vật phẩm có độc. Quắc Anh xử lý các vụ án rất tỉnh táo và thông minh hơn người, nên đã thu hút sự chú ý của Thăng và Thâm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 15, 2008, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Xa Thi Mạn","avatar":""},{"name":"Lâm Văn Long","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Trịnh Gia Dĩnh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["法证先锋2","Forensic Heroes 2","法證先鋒II"]', 1784690324480);
