INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-muon-khoc', 'Bỗng Dưng Muốn Khóc', 'Suddenly Want to Cry', 'https://phimimg.com/upload/vod/20241010-1/5cb6e6ac95f134013533d967f36dc049.jpg', 'https://phimimg.com/upload/vod/20241010-1/f88b2dd1d3cef41b6e846447a061eb47.jpg', '<p>Bộ phim kể về mối tình thật hài hước, lãng mạn và cảm động của hai con người tưởng như hoàn toàn khác biệt nhau về tất cả mọi thứ: Bảo Nam và Diễm Trúc. Bảo Nam, 21 tuổi, đẹp trai, tính tình vui vẻ, hài hước, luôn là nhân vật trung tâm của đám bạn nhà giàu, suốt ngày chỉ biết rong chơi, đốt tiền vào những cuộc vui vô bổ. Bảo Nam sẵn sàng làm mọi thứ để làm vui lòng cô bạn gái của mình, một cô gái cực kỳ quyến rũ và luôn biết cách tiêu tiền một cách nhiều nhất và nhanh nhất.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2008, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Tăng Thanh Hà","avatar":""},{"name":"Lương Mạnh Hải","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Thanh Thủy","avatar":""},{"name":"Văn Tùng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Bỗng Dưng Muốn Khóc"]', 1784690324480);
