INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-trom-cap-chuc-ke-xau-ngu-ngon', 'Bộ ba trộm cắp: Chúc kẻ xấu ngủ ngon', 'Trailer Park Boys: Say Goodnight to the Bad Guys', 'https://phimimg.com/upload/vod/20231103-1/de1c51c7226a7d81960b72c6e67cad06.jpg', 'https://phimimg.com/upload/vod/20231103-1/5afdb0562e1e78702f4ae6706879b5bc.jpg', '<p>Một năm sau khi mùa 7 kết thúc, các chàng trai đang có một cuộc sống yên ấm. Nhưng kẻ thù xưa một lần nữa lại làm xáo trộn mọi thứ.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Paul Tremblay","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"Mike Smith","avatar":""},{"name":"John Dunsworth","avatar":""},{"name":"Patrick Roach","avatar":""},{"name":"Lucy Decoutere","avatar":""},{"name":"Sarah Dunsworth","avatar":""},{"name":"Barrie Dunn","avatar":""},{"name":"Jeanna Harrison","avatar":""},{"name":"Shelley Thompson","avatar":""},{"name":"Tyrone Parsons","avatar":""},{"name":"Jonathan Torrens","avatar":""},{"name":"Bernard Robichaud","avatar":""},{"name":"Richard Collins","avatar":""},{"name":"Jacob Rolfe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324480);
