INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-ba-trom-cap-chuc-ke-xau-ngu-ngon', 'Bộ ba trộm cắp: Chúc kẻ xấu ngủ ngon', 'Trailer Park Boys: Say Goodnight to the Bad Guys', 'bộ ba trộm cắp: chúc kẻ xấu ngủ ngon trailer park boys: say goodnight to the bad guys john paul tremblay robb wells mike smith john dunsworth patrick roach lucy decoutere sarah dunsworth barrie dunn jeanna harrison shelley thompson tyrone parsons jonathan torrens bernard robichaud richard collins jacob rolfe ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-rung', 'Mèo Rừng', 'The Missing Lynx', 'https://phimimg.com/upload/vod/20231102-1/375f4eda0cf297ebedd1e68d8a804d36.jpg', 'https://phimimg.com/upload/vod/20231102-1/a059d70498348b2a95264e9e865f83e7.jpg', '<p>Bộ phim Mèo Rừng kể về những con thú hoang dã bị bắt với mục đích điên rồ của một tên tiến sĩ có khả năng nói chuyện được với mọi con vật. Những con thú này với trí thông minh của mình đã chiến đấu anh dũng chống lại bọn săn thú và kết cục tốt đẹp dành cho những con vật dũng cảm. Nhân vật chính trong bộ phim là một chú mèo rừng và loài mèo của cậu ta đang đứng trước nguy cơ tiệt chủng, nhưng may mắn trong lúc bị bắt vào vườn thú thì cậu đã gặp được cô mèo rừng và đã nảy sinh tình yêu...</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2008, 'Thuyết Minh', 'HD', 'Tây Ban Nha', 0, '[{"name":"David Robles","avatar":""},{"name":"Beatriz Berciano","avatar":""},{"name":"Cecilia Santiago","avatar":""},{"name":"Abraham Aguilar","avatar":""},{"name":"Roberto Cuenca Martínez","avatar":""},{"name":"Stephen Hughes","avatar":""},{"name":"Carlos del Pino","avatar":""},{"name":"Pepa Castro","avatar":""},{"name":"David García","avatar":""},{"name":"Pilar Coronado","avatar":""},{"name":"Conchi López","avatar":""},{"name":"Héctor Garay","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
