INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-cuoc-chien-vo-tinh-phan-1', 'Chiến Tranh Giữa Các Vì Sao: Cuộc Chiến Vô Tính (Phần 1)', 'Star Wars: The Clone Wars (Season 1)', 'https://phimimg.com/upload/vod/20240624-1/ac2c95fe84c4991e65b0d4474dbf778f.jpg', 'https://phimimg.com/upload/vod/20240624-1/fecfe9aa612927aa6e5fc0f0d753c69d.jpg', '<p>Nhà sản xuất điều hành George Lucas và Lucasfilm Animation giới thiệu loạt phim mang tính đột phá này lấy bối cảnh giữa Tập I và Ill của câu chuyện Chiến tranh giữa các vì sao. Các anh hùng Jedi Yoda, Anakin, Obi-Wan và người mới Ahsoka chiến đấu chống lại phe ly khai độc ác do Bá tước Dooku, sát thủ Asajj Ventress và tướng cơ khí Grievous lãnh đạo. Mỗi tập phim là một cuộc phiêu lưu đầy hành động giới thiệu các nhân vật mới và khám phá các hành tinh mới khi Jedi và những người lính nhân bản dũng cảm của họ bảo vệ thiên hà Star Wars.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Eckstein","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Tom Kane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324480);
