INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ly-tieu-long-2008', 'Huyền Thoại Lý Tiểu Long', 'The Legend Of Bruce Lee', 'https://phimimg.com/upload/vod/20240829-1/a2dcb0cde49398b44e56e15954372dba.jpg', 'https://phimimg.com/upload/vod/20240829-1/15c79df0dfc6b4c7b18683141d59d89d.jpg', '<p>Huyền thoại Lý Tiểu Long hay Legend of Bruce Lee là bộ phim truyền hình võ thuật Trung Quốc năm 2008 dựa trên câu chuyện về cuộc đời có thật của Lý Tiểu Long. Bộ phim 50 tập này đã được sản xuất và phát sóng bởi CCTV và bắt đầu phát sóng vào ngày 12 tháng 10 năm 2008. Phim có sự tham gia của diễn viên Hồng Kông Trần Quốc Khôn trong vai Lý Tiểu Long và nữ diễn viên người Mỹ Michelle Lang trong vai vợ của Lý Tiểu Long, Linda Lee Cadwell. Giai đoạn sản xuất kéo dài chín tháng, với việc quay phim diễn ra tại Trung Quốc, Hồng Kông, Ma Cao, Hoa Kỳ, Ý và Thái Lan, với ngân sách là 50 triệu nhân dân tệ (7,3 triệu đô la Mỹ).</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 12, 2008, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Quốc Khôn","avatar":""},{"name":"Hạp Khắc","avatar":""},{"name":"Vu Thừa Huệ","avatar":""},{"name":"Vương Lạc Dũng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
