INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-ly-tieu-long-2008', 'Huyền Thoại Lý Tiểu Long', 'The Legend Of Bruce Lee', 'huyền thoại lý tiểu long the legend of bruce lee trần quốc khôn hạp khắc vu thừa huệ vương lạc dũng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoai-ngoc-truyen-ky', 'Hoài Ngọc Truyền Kỳ', 'The Legendary Of Matsu', 'https://phimimg.com/upload/vod/20240827-1/f1e7075e1bcb386656fe7ca5af7cc8fc.jpg', 'https://phimimg.com/upload/vod/20240827-1/19e51c6ff5c2a3cca2ededfbbc43d182.jpg', '<p>Trần Hoài Ngọc là con gái thứ 3 của Quận vương Trần Long Hồ. Cá tính ngang bướng nghịch ngợm, nhưng cũng là một cô gái tốt bụng giàu lòng nhân ái, hiếu thuận với cha mẹ và chung thủy với tình yêu.Cuộc gặp gỡ định mệnh giữa Hoài ngọc và Hàn Văn thái tử đã làm thay đổi vận mệnh của cả hai.Vì muốn phá giải trận pháp Thuỷ Long do Thái tử Hàn Vũ giăng bày, cả hai đã&nbsp; rơi vào nguy hiểm, giữa ranh giới sống chết, tấm chân tình của Hoài Ngọc đã làm Hàn Văn cho cảm động. Trong khi Hàn Vũ cũng đem lòng yêu và muốn cưới Hoài Ngọc làm vương phi.Hoài Ngọc đối&nbsp; với tình cảm của Hàn Văn và Hàn Vũ phải giải quyết ra sao? Đối phó Thủy Long bằng cách nào? Hoài Ngọc hạ phàm phải trải qua kiếp nạn ra sao?</p>', 'Hoàn Tất (313/313)', 313, 'series', 'completed', 11, 2008, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Mishelle Wang","avatar":""},{"name":"Hua Ye","avatar":""},{"name":"Viola Fong","avatar":""},{"name":"Margaret Wang","avatar":""},{"name":"Wang Chung-Huang","avatar":""},{"name":"曾莞婷","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324480);
