INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-12-tan-cung-cua-su-so-hai', 'Thám Tử Lừng Danh Conan 12: Tận Cùng Của Sự Sợ Hãi', 'Detective Conan: Full Score of Fear', 'https://phimimg.com/upload/vod/20231019-1/a5b4244c2c5a358dfd2c66d93c467074.jpg', 'https://phimimg.com/upload/vod/20231019-1/a0de04dbc4e29928a2e0eb879092eead.jpg', '<p>Conan và mọi người được mời đến tham gia buổi biểu diễn đầu tiên của nhà hát Doumoto. Sự hấp dẫn lớn nhất của buổi hòa tấu là cây đàn nổi tiếng thế giới Violon Xtract và khả năng đặc biệt của người ca sĩ có khả năng nghe hoàn hảo. Nhưng ngay sau đó, một vụ giết người hàng loạt xảy ra với nhiều cách thức. Tất cả nạn nhân đều là sinh viên của Học viên âm nhạc Doumoto và do 1 nhạc công piano nổi tiếng dạy. Conan sẽ làm thế nào để tìm ra hung thủ thực sự?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2008, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Nobuo Tanaka","avatar":""},{"name":"Kohsuke Meguro","avatar":""},{"name":"Houko Kuwashima","avatar":""},{"name":"Yuko Mizutani","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[