INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tuy-tung-phan-5', 'Đoàn Tùy Tùng (Phần 5)', 'Entourage (Season 5)', 'https://phimimg.com/upload/vod/20240808-1/2b7a685b9b4b2ef2f18b807413bf9e20.jpg', 'https://phimimg.com/upload/vod/20240808-1/47d7adb9b7d2655cae9870eba9dc825a.jpg', '<p>Ngôi sao điện ảnh Vince Chase khám phá địa hình tẻ nhạt của Los Angeles cùng một nhóm bạn thân thiết và người đại diện đáng tin cậy của anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Connolly","avatar":""},{"name":"Adrian Grenier","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Rex Lee","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Scott Caan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
