INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doan-tuy-tung-phan-5', 'Đoàn Tùy Tùng (Phần 5)', 'Entourage (Season 5)', 'đoàn tùy tùng (phần 5) entourage (season 5) kevin connolly adrian grenier kevin dillon jerry ferrara jeremy piven perrey reeves rex lee debi mazar emmanuelle chriqui rhys coiro scott caan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-nhi-lien-hoa', 'Thập Nhị Liên Hoa', '12 Lotus', 'https://phimimg.com/upload/vod/20240805-1/7a219fa86904c23ebb5d9d3cbf6e9d90.jpg', 'https://phimimg.com/upload/vod/20240805-1/d32f188d816303b360f9e6a79ca958d9.jpg', '<p>Khi còn nhỏ, Lian Hua mơ ước trở thành nghệ sĩ biểu diễn trong các buổi biểu diễn Getai của Singapore, các buổi hòa nhạc được tổ chức vào cùng tháng hàng năm và trình diễn những bài hát giàu cảm xúc về tình yêu, sự sống và cái chết. Tuy nhiên, cha của Lian đã ngăn cản cô theo đuổi ước mơ của mình, và mặc dù Lian không bao giờ đánh mất tình yêu với âm nhạc nhưng tham vọng của cô lại gắn liền với bi kịch khi cô lớn lên. Là một phụ nữ trưởng thành, Lian cuối cùng dường như đã sẵn sàng để ghi dấu ấn với tư cách là một nghệ sĩ biểu diễn khi hợp tác với giọng ca hào nhoáng Astroboy và chàng trai quyến rũ Ah Long. Ah Long yêu Lian, nhưng mối tình lãng mạn của họ đột ngột kết thúc và Lian bị một nhóm côn đồ muốn đòi nợ từ cha cô hành hung. Mười năm sau, Lian trung niên nghĩ rằng cô có thể có một cơ hội thành công khác khi tìm được tình yêu mới, nhưng số phận đã đưa cô đến bờ vực điên loạn và một lần nữa nỗi thất vọng lại chờ đợi cô.</p>', 'Full', 1, 'single', 'completed', 21, 2008, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Mindee Ong","avatar":""},{"name":"Liu Ling Ling","avatar":""},{"name":"Qi Yuwu","avatar":""},{"name":"Huang Yiliang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
