INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-an-phan-6', 'Lãnh Án (Phần 6)', 'Cold Case (Season 6)', 'https://phimimg.com/upload/vod/20240609-1/c8fafe68c783a94384a5eb8d50f1cf4c.jpg', 'https://phimimg.com/upload/vod/20240609-1/43367e8b6ea4269a7410c1acd4385a78.jpg', '<p>Nữ thám tử duy nhất của đội điều tra án mạng Philadelphia tìm thấy tiếng gọi của cô khi cô được giao những vụ án chưa bao giờ được giải quyết. Thám tử Lilly Rush kết hợp bản năng tự nhiên của mình với công nghệ cập nhật hiện nay để mang lại công lý cho tất cả các nạn nhân mà cô có thể.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kathryn Morris","avatar":""},{"name":"Danny Pino","avatar":""},{"name":"Jeremy Ratchford","avatar":""},{"name":"Thom Barry","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"John Finn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
