INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-toi', 'Tăm Tối', 'Blindness', 'https://phimimg.com/upload/vod/20240628-1/20ed7f3283c65212565715660620ace2.jpg', 'https://phimimg.com/upload/vod/20240628-1/82ed54135ff5768b4fcaf57372b12553.jpg', '<p>Ở một thành phố nọ, người dân đang sống một cuộc sống yên bình, bỗng chốc mọi thứ kì lạ ập đến, điều kinh khủng nhất là một căn bệnh quái ác chực chờ cướp đi &quot;ánh sáng&quot; của từng người dân của thành phố. Mọi người tỉnh dậy và họ không còn nhìn thấy được nữa. Các bác sĩ dần bó tay với căn bệnh kì quái và chính họ cũng là nạn nhân của nó nhưng có một số người quyết tâm tìm ra lời giải cho căn bệnh bí hiểm này và họ đã làm thế nào, hãy cùng xem Blindness.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"伊勢谷友介","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Don McKellar","avatar":""},{"name":"Maury Chaykin","avatar":""},{"name":"Mitchell Nye","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Jason Bermingham","avatar":""},{"name":"Eduardo Semerjian","avatar":""},{"name":"Ciça Meirelles","avatar":""},{"name":"Antonio Fragoso","avatar":""},{"name":"Lilian Blanc","avatar":""},{"name":"Douglas Silva","avatar":""},{"name":"Daniel Zettel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id