INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('merlin-phan-1', 'Merlin (Phần 1)', 'Merlin (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/0e3bc5c436eb214124a2bec9a5048c88.jpg', 'https://phimimg.com/upload/vod/20231219-1/86367e1d3c934951b3c81ef64422d40b.jpg', '<p>Không lâu sau khi đến Camelot, nơi ma thuật bị khép vào tội chết, chàng pháp sư Merlin trẻ tuổi nhận ra nhiệm vụ của mình là bảo vệ Arthur - vị vua tương lai.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Morgan","avatar":""},{"name":"Bradley James","avatar":""},{"name":"Katie McGrath","avatar":""},{"name":"Angel Coulby","avatar":""},{"name":"Richard Wilson","avatar":""},{"name":"Anthony Head","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Nathaniel Parker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
