INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-2', 'Gã Điên (Phần 2)', 'Mad Men (Season 2)', 'https://phimimg.com/upload/vod/20240606-1/bb3a3a7273a5c4d01a26ae5a0e79ff96.jpg', 'https://phimimg.com/upload/vod/20240606-1/b8dd443da4487ba00a2c38070726fefc.jpg', '<p>Phần hai diễn ra từ tháng 2 đến tháng 10 năm 1962, lên đến đỉnh điểm với Cuộc khủng hoảng tên lửa Cuba. người quen chưa biết của Don Draper đã gửi thư qua thư cho người quen bí mật này.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
