INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chong-bat-dac-di', 'Người Chồng Bất Đắc Dĩ', 'The Accidental Husband', 'https://phimimg.com/upload/vod/20240606-1/75a17678e3fbd45442c8eee99cdbb8d7.jpg', 'https://phimimg.com/upload/vod/20240606-1/50bf38a6b7a26c3a133619471f47744a.jpg', '<p>Một phát thanh viên, chuyên tư vấn chuyện tình cảm cho bạn nghe đài (Uma Thurman đóng), cô đã khuyên một phụ nữ từ bỏ bạn trai, vốn là một lính cứu hỏa New York, và sau này, người đàn ông đó đã ra sức trả thù cô. Cô đã quyết định lên xe hoa với người mình yêu, nhưng khi đến phòng đăng ký kết hôn, cô sửng sốt khi phát hiện ra rằng hoá ra mình đã có chồng. Sự thật trớ trêu này đã đẩy cô đến tình thế tiến thoái lưỡng nan, lưỡng lự giữa hai dòng nước. Sau khi biết được sự thật không mấy dễ chịu kia, cô nàng tội nghiệp đã quyết định tìm hiểu về anh chồng từ trên trời rơi xuống để rồi phát hiện ra những điều tưởng vậy mà không phải vậy, và kịch tính hơn, cô đã phải lòng… người đàn ông xa lạ ấy. Chính điều đó đã khiến cô lâm vào tình cảnh tiến thoái lưỡng nan, không biết phải chọn ai giữa hai người đàn ông mà cô đều yêu.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Brooke Adams","avatar":""},{"name":"Keir Dullea","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Lindsay Sloane","avatar":""},{"name":"Ajay Naidu","avatar":""},{"name":"Sarita Choudhury","avatar":""},{"name":"Jeffrey Tedmori","avatar":""},{"name":"Nick Sandow","avatar":""},{"name":"Michael Mosley","avatar":""},{"name":"Lindsey Kraft","avatar":""},{"name":"Yolande Bavan","avatar":""},{"name":"Adesola","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324480);
