INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-phan-4', 'Vượt Ngục (Phần 4)', 'Prison Break (Season 4)', 'https://phimimg.com/upload/vod/20240409-1/70c7dd5f71d2296ffcba45e492661ee1.jpg', 'https://phimimg.com/upload/vod/20240409-1/c08a5b84aff57aeee62d0a07c9b409e7.jpg', '<p>Phần 4 tập trung vào một nhóm nghiên cứu được tuyển dụng bởi đặc vụ An ninh nội địa mang tên Don Self nhằm có được Scylla. Mặc dù ban đầu, nhóm nghiên cứu tin rằng nó nằm trong Sổ đen của Hội Đồng Hành nhưng rồi nhóm được tung ra để thu thập thông tin về một loại pin tiên tiến có khả năng tái tái tạo năng lượng. Trong nửa đầu của phần 4, nhóm nghiên cứu tìm cách lấy thẻ truy cập vào Scylla, và đột nhập vào trụ sở Hội Đồng Hành để ăn cắp nó. Sara được phát hiện vẫn còn sống, Bellick mới là người bị chết. Đặc vụ Don Self bị phát hiện là gián điệp hai mang và đang có kế hoạch bán Scylla cho người trả giá cao nhất</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Wade Williams","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Marshall Allman","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Jodi Lyn O''keefe","avatar":""},{"name":"Paul Scheuring Diễn Viên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324480);
