INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-trai-moi-cua-me-toi', 'Bạn Trai Mới Của Mẹ Tôi', 'My Mom''s New Boyfriend', 'bạn trai mới của mẹ tôi my mom''s new boyfriend meg ryan antonio banderas selma blair colin hanks trevor morgan john valdetero eli danker tom adams keith david enrico colantoni ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-khung-bo', 'Đội Chống Khủng Bố', 'Secrets Of State', 'https://phimimg.com/upload/vod/20240228-1/afcd31005b4bd7c4f25f414a721c5d04.jpg', 'https://phimimg.com/upload/vod/20240228-1/f546623da89294739ae766c12551674f.jpg', '<p>Ở Pháp, các nhóm khủng bố và các cơ quan tình báo đang chiến đấu trong một cuộc chiến không khoan nhượng hàng ngày, nhân danh những hệ tư tưởng đối lập hoàn toàn. Tuy nhiên, các điệp viên khủng bố và bí mật đều có cuộc sống gần như giống nhau. Bị buộc tội phải giữ bí mật, những bậc thầy thao túng này cũng tuân theo những phương pháp tương tự. Alex và Al Barad là hai trong số họ. Người trước là người đứng đầu đơn vị chống khủng bố D.G.S.E.s (Direction Générale de la Sécurité Extérieure, đơn vị chống khủng bố trong tiếng Pháp tương đương với CIA hoặc MI6) trong khi đơn vị sau thống trị một mạng lưới khủng bố và cả hai đều chiến đấu bằng cách sử dụng loại vũ khí tàn nhẫn nhất: con người chúng sinh.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gérard Lanvin","avatar":""},{"name":"Vahina Giocante","avatar":""},{"name":"Nicolas Duvauchelle","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Rachida Brakni","avatar":""},{"name":"Mehdi Nebbou","avatar":""},{"name":"Aurélien Wiik","avatar":""},{"name":"Nicolas Marié","avatar":""},{"name":"Katia Lewkowicz","avatar":""},{"name":"Kamel Belghazi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324480);
