INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elegy', 'Elegy', 'Elegy', 'https://phimimg.com/upload/vod/20240228-1/c973cbd48f6ed35f7be61dbaae8c1299.jpg', 'https://phimimg.com/upload/vod/20240228-1/c83af11c17d9f3263834200fce749294.jpg', '<p>Nhà phê bình văn hóa David Kepesh nhận thấy cuộc sống của mình - mà ông cho rằng là một trạng thái của nam giới được giải phóng - bị Consuela Castillo, một học sinh lịch sự, ném vào tình trạng hỗn loạn bi thảm, người đã đánh thức cảm giác chiếm hữu tình dục ở giáo viên của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Penélope Cruz","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Sonja Bennett","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Shaker Paleja","avatar":""},{"name":"Charlie Rose","avatar":""},{"name":"Kris Pope","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
