INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bad-biology', 'Bad Biology', 'Bad Biology', 'https://phimimg.com/upload/vod/20240228-1/4d2ed4c7923c948920296923da3eecaf.jpg', 'https://phimimg.com/upload/vod/20240228-1/fd69d48a439f7234a9fa3c2ee95bc72f.jpg', '<p>Bị thúc đẩy bởi sự dư thừa sinh học, một thanh niên và một phụ nữ tìm kiếm sự thỏa mãn tình dục mà không biết đến sự tồn tại của nhau. Thật không may, cuối cùng họ gặp nhau, và mối liên kết giữa hai con người rất khác thường này kết thúc bằng một trải nghiệm tình dục bùng nổ và cuối cùng là đỉnh cao, dẫn đến một câu chuyện tình yêu khủng khiếp thực sự thần thánh....</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlee Danielson","avatar":""},{"name":"Anthony Sneed","avatar":""},{"name":"Ginger Starr","avatar":""},{"name":"John A. Thorburn","avatar":""},{"name":"Tom Kohut","avatar":""},{"name":"James Shell","avatar":""},{"name":"Vivian Sanchez","avatar":""},{"name":"Jessie Jayne Clancy","avatar":""},{"name":"Eléonore Hendricks","avatar":""},{"name":"Jude Angelini","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324480);
