INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-thu-tu', 'Một Ngày Thứ Tư', 'A Wednesday', 'https://phimimg.com/upload/vod/20240228-1/4cdbaa36b671e2bd5c5e00b51acfb7fe.jpg', 'https://phimimg.com/upload/vod/20240228-1/fd6d76b86cc3c3067f8a85412e71d68e.jpg', '<p>Ủy viên thành phố Munbai nhận được một cuộc điện thoại của kẻ lạ mặt đặt bom trong thành phố yêu cầu phải thả 4 tên tội phạm khủng bố. Đây là vụ án đặt bom lạ lùng chưa được ghi chép trong sổ sách của công an Ấn Độ...</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Anupam Kher","avatar":""},{"name":"Naseeruddin Shah","avatar":""},{"name":"Jimmy Shergill","avatar":""},{"name":"Deepal Shaw","avatar":""},{"name":"Aamir Bashir","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
