INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-duoi-day-bien', 'Bí Mật Dưới Đáy Biển', 'Fool''s Gold', 'https://phimimg.com/upload/vod/20240220-1/b66d856cea95f64282de6c7b42fe4195.jpg', 'https://phimimg.com/upload/vod/20240220-1/6072547eefe1a758785214b3b298f422.jpg', '<p>Ben Finn Finnegan (McConaughey) là một anh chàng chuyên đi săn lùng kho báu. Ben coi việc tìm ra Queens Dowry - bộ sưu tập huyền thoại gồm 40 chiếc rương chứa đầy báu vật bị thất lạc dưới đáy biển sâu năm 1715 là sứ mạng cuộc đời. Nhưng chính niềm đam mê này đã khiến Ben xao lãng gia đình và vợ anh, Tess (Hudson) xinh đẹp đã quyết định ly hôn. Tràn đầy tin tưởng bắt đầu cuộc sống mới, Tess xin được việc trên chiếc du thuyền sang trọng của nhà tỷ phú ưa ngao du Nigel Honeycutt (Donald Sutherland). Cùng lúc đó, với vẻ điển trai đầy mê hoặc của mình, Ben đã thuyết phục được ngài tỷ phú cùng cô con gái yêu Gemma (Alexis Dziena) về khả năng sở hữu kho báu Tây Ban Nha vô giá. Không còn cách nào khác, Tess buộc phải bắt tay với người chồng cũ để tìm ra kho báu bí ẩn nhất hành tinh và chống lại sự săn đuổi gắt gao của người thầy cũ Moe Fitch (Ray Winstone) và một tên găng-tơ tham lam (Kevin Hart)...</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Alexis Dziena","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Malcolm-Jamal Warner","avatar":""},{"name":"Brian Hooks","avatar":""},{"name":"David Roberts","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
