INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('marley-va-toi', 'Marley Và Tôi', 'Marley & Me', 'marley và tôi marley & me jennifer aniston owen wilson eric dane ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-quyen-ru-cua-nguoi-vo', 'Sự Quyến Rũ Của Người Vợ', 'Temptation Of Wife', 'https://phimimg.com/upload/vod/20240215-1/3025e340571a5ef73a1042f72d4f94dc.jpg', 'https://phimimg.com/upload/vod/20240215-1/e2c91148f49bd3615a22f6b4ccb83609.jpg', '<p>Xoay quanh cuộc sống đau khổ của nữ chính Goo Eun Jae (Jang Seo Hee đóng), người tốt nghiệp ngành trang điểm và luôn mơ ước trở thành chuyên gia làm đẹp. Cô phải tạm gác lại giấc mơ du học Pháp sau khi có thai với bạn trai Jung Gyo Bin (Byun Woo Min đóng) và kết hôn với anh này. Cuộc sống hôn nhân của Eun Jae sớm trở thành địa ngục khi cô bị sẩy thai và chịu cảnh mẹ chồng hắt hủi. Cùng lúc Eun Jae mang thai lần hai, một người bạn cũ của cô là Shin Ae Ri (Kim Seo Hyung đóng) trở về từ Pháp sau 5 năm xa xứ. Ae Ri là trẻ mồ từ hồi 7 tuổi, từng được bố mẹ Eun Jae cưu mang trong suốt 20 năm và cũng từng là bạn gái của anh trai Eun Jae, Goo Kang Jae (Choi Joon Yong đóng). Gyo Bin công khai ngoại tình với Ae Ri trước mặt Eun Jae, sau đó quyết định bỏ vợ đến với người tình. Đôi tình nhân còn lập mưu đẩy Eun Jae xuống biển để giết cả cô và cái thai trong bụng, với mục đích đoạt được tài sản trong di chúc của cha Gyo Bin, một doanh nhân giàu có. Sau vụ tai nạn, Eun Jae còn sống nhưng mất đi đứa con. Nhiều tháng sau, cô trở lại với khát vọng trả thù. Cô sống dưới tên của một cô gái khác, Min So Hee (Chae Young In đóng), người tự tử cùng ngày cô bị hại.</p>', 'Hoàn Tất (129/129)', 129, 'series', 'completed', 14, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Seo Hee","avatar":""},{"name":"Byun Woo Min","avatar":""},{"name":"Lee Jae Hwang","avatar":""},{"name":"Kim Seo Hyung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324480);
