INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-bi-2008', 'Họa Bì', 'Painted Skin', 'https://phimimg.com/upload/vod/20240220-1/4a611dd7bfa3fda7452622c7acbbbb26.jpg', 'https://phimimg.com/upload/vod/20240220-1/5177dbdc4540a6132e9aaef0090ab248.jpg', '<p>Vào thời Tần Hán, đại tướng Vương Sinh (Trần Khôn) thống lĩnh đội quân của mình chiến đấu với đám cướp sa mạc ở Tây Vực. Trong cuộc chiến này, tình cờ Vương Sinh cứu sống được một người con gái nhan sắc tuyệt trần tên là Tiểu Vi (Châu Tấn) và đưa cô về nhà cưu mang. Thực chất, Tiểu Vi là một nữ hồ ly độc ác, ngày ngày phải ăn tim người do Tắc Kè tinh (Thích Ngọc Võ) mang tới để có thể duy trì được phép thuật của mình. Nữ hồ ly Tiểu Vi đem lòng yêu Vương Sinh và muốn chiếm đoạt chàng cho riêng mình, nên đã dùng nhiều thủ đoạn hãm hại Bối Dung (Triệu Vy) – vợ của Vương Sinh, để chia rẻ tình cảm của hai người. Để bảo vệ chồng và hạnh phúc gia đình, Bối Dung đã chấp nhận lao vào cuộc chiến không cân sức giữa người và quỷ, với sự trợ giúp của một kiếm khách võ nghệ cao cường (Chung Tử Đơn) và một nữ pháp sư “tập sự” (Tôn Lệ)…</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Chen Kun","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Sun Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
