INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('web-tu-than', 'Web Tử Thần', 'Untraceable', 'https://phimimg.com/upload/vod/20240219-1/4276e951ee5743f3f51ea17ddfb0c863.jpg', 'https://phimimg.com/upload/vod/20240219-1/06f82e11a88dc406bcc1e04afbc98b65.jpg', '<p>Một tên giết người liên hoàn đã ghi hình trực tiếp và đăng tải trên trang web những cảnh gây án của mình. Thế rồi, khi càng có nhiều người đăng nhập vào trang web trên để xem thì nạn nhân sẽ bị tra tấn một cách tàn nhẫn và chết càng nhanh hơn. Vì vậy, nữ nhân viên mật vụ Jennifer Marsh cùng nhóm điều tra của cô lao vào truy tìm tên hung thủ, thế nhưng, họ lại bị vướng vào trò chơi “mèo vờn chuột” với một tên giết người cực kì khôn ngoan và xảo quyệt khi hắn ta không để lại một chút dấu vết nào...</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diane Lane","avatar":""},{"name":"Colin Hanks","avatar":""},{"name":"Joseph Cross","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324480);
