INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rut-sung-la-ban', 'Rút Súng Là Bắn', 'RocknRolla', 'https://phimimg.com/upload/vod/20240219-1/6d800d3a6f9c57c1893db139ba6781c3.jpg', 'https://phimimg.com/upload/vod/20240219-1/50bd4dc1b2f07efcab7f0a92813b9a65.jpg', '<p>Khi một băng cướp người Nga dàn dựng một âm mưu bất lương trong giao dịch bất động sản làm phát sinh hàng triệu đồng bảng Anh, những thành viên khác nhau của thế giới ngầm tội phạm ở Anh lao vào cuộc săn đuổi nhằm kiếm chác lợi nhuận từ nguồn của cải béo bở này. Trong số những nhân vật mờ ám tham gia cuộc săn đuổi đó có sự tham gia của Mr One-Two - một tên cướp đường phố láu lỉnh, nữ kế toán viên thông minh và xinh đẹp Stella và ngôi sao nhạc rock nghiện ma túy Johnny Quid… mỗi người đều cố gắng giành lấy bằng được phần của mình…</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Idris Elba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
