INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinker-bell-co-tien-giup-ich', 'Tinker Bell - Cô Tiên Giúp Ích', 'Tinker Bell', 'https://phimimg.com/upload/vod/20240219-1/4d0467aefba3e1315036de9a74d72533.jpg', 'https://phimimg.com/upload/vod/20240219-1/c7f9447618719bfe53ba6cd36a367f1f.jpg', '<p>Tinker Bell được sinh ra từ nụ cười đầu tiên của đứa trẻ sơ sinh và được ngọn gió mang tới Pixie Hollow (một hòn đảo ở Never Land). Tại đây cô gặp những nàng tiên nhỏ khác và biết rằng năng lực của mình là để phục vụ việc hàn gắn mọi thứ – một thiên thần sửa chữa mọi thứ. Các tiên thợ khác đã giúp nhân viên mới học việc và Tinker Bell đã học được nghề, cô có thể ...</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristin Chenoweth","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Mae Whitman","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
