INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-bien-gioi-moi', 'Liên Minh Công Lý: Biên Giới Mới', 'Justice League: The New Frontier', 'https://phimimg.com/upload/vod/20240205-1/c43e037861f62983e7cf4206c00bfc01.jpg', 'https://phimimg.com/upload/vod/20240205-1/800b9a3675cf4e3cf71692b6e23e0e3d.jpg', '<p>Loài người đang bị đe dọa bởi một sinh vật mạnh mẽ và chỉ có sức mạnh tổng hợp của Superman, Batman, Wonder Woman, Green Lantern, Martian Manhunter và The Flash mới có thể ngăn chặn nó. Nhưng liệu họ có thể vượt qua sự khác biệt của mình để ngăn chặn kẻ thù này bằng cách sử dụng sức mạnh tổng hợp của Liên minh Công lý mới thành lập của họ không?</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Boreanaz","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Brooke Shields","avatar":""},{"name":"Jeremy Sisto","avatar":""},{"name":"Kyle MacLachlan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324480);
