INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghajini', 'Ghajini', 'Ghajini', 'https://phimimg.com/upload/vod/20240205-1/11fd96ec9b8a5beaf12814bf53b8f538.jpg', 'https://phimimg.com/upload/vod/20240205-1/85e5886dd22f2868a3bc02923e702b50.jpg', '<p>Một chàng trai là chủ tịch của 1 tập đoàn máy tính lớn đem lòng yêu 1 cô gái đã tung tin đồn là cô gái đó là bạn gái của anh, cho dù 2 người chưa từng gặp mặt. Và rồi 2 người bắt đầu yêu nhau nhưng cô gái đã bị 1 tên trùm buôn người trả thù vì đã chỉ mặt tố cáo ông ta. Kết quả cô bị giết chết còn chàng trai thì bị đánh đến nỗi bị bệnh mất trí nhớ sau mỗi 15 phút, những gì trước đó sẽ quên hết. Chàng trai làm sao có thể trả thù được với trí nhớ sao mỗi 15 phút sẽ bị reset lại. Làm sao anh ta có thể sống được trong tình trạng như thế...</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Asin Thottumkal","avatar":""},{"name":"Jiah Khan","avatar":""},{"name":"Pradeep Ram Singh Rawat","avatar":""},{"name":"Riyaz Khan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
