INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mesrine-killer-instinct', 'Mesrine: Killer Instinct', 'Mesrine: Killer Instinct', 'https://phimimg.com/upload/vod/20240207-1/1aa82e209cbf47eea3688c605d390672.jpg', 'https://phimimg.com/upload/vod/20240207-1/950f95addc4582a61997efdbde345924.jpg', '<p>Phần một của bộ phim hình sự hai phần dựa trên câu chuyện có thật, với sự góp mặt của Vincent Cassel trong vai một trong những tên tội phạm khét tiếng nhất nước Pháp Từ cuối tháng 10/2008, công chúng Pháp đổ xô đến các rạp chiếu phim để biết tường tận về cuộc đời một tên cướp đã được mệnh danh là “Kẻ thù số 1 của công chúng ”, hoặc “Kẻ vượt ngục siêu nhất thế giới”. Đó chính là Jacques René Mesrine, tên cướp khét tiếng đã gây ra hàng loạt những vụ cướp nhà băng và vượt ngục gây náo loạn Pháp, Canada và Tây Ban Nha trong những năm 1960 và 1970. Theo hồ sơ của cảnh sát Pháp, Jacques René Mesrine sinh ngày 28.12.1936 trong một gia đình thuộc tầng lớp trung lưu vùng Clichy (Pháp). Khi còn nhỏ, Mesrine được gia đình cho đi học ...</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Vincent Cassel","avatar":""},{"name":"Cécile de France","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Gilles Lellouche","avatar":""},{"name":"Roy Dupuis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
