INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-su-that', 'Mặt Trái Sự Thật', 'Surveillance', 'https://phimimg.com/upload/vod/20240228-1/71d58a8f7fb0f506685094d4a0ebd8c6.jpg', 'https://phimimg.com/upload/vod/20240228-1/785601457a2d395cf689e6390b14a889.jpg', '<p>Một đặc vụ FBI theo dõi kẻ giết người hàng loạt với sự giúp đỡ của ba nạn nhân tương lai của hắn - tất cả đều có những câu chuyện cực kỳ khác nhau để kể.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Ormond","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Pell James","avatar":""},{"name":"Ryan Simpkins","avatar":""},{"name":"Cheri Oteri","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"French Stewart","avatar":""},{"name":"Kent Harper","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Gill Gayle","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
