INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-han-thu', 'Lửa Hận Thù', 'Max Payne', 'https://phimimg.com/upload/vod/20240205-1/101c42467588d069fa41bcb705933f87.jpg', 'https://phimimg.com/upload/vod/20240205-1/4c40026ea062966b72d8fb91153973cd.jpg', '<p>Với Max Payne, một viên cảnh sát tài năng nhưng có tính cách nổi loạn, thì cuộc sống hiện tại của anh chẳng khác gì địa ngục. Vợ và đứa con mới sinh của Max bị những kẻ giấu mặt sát hại dã man. Chìm trong đau khổ tột cùng, trong tâm trí của Max chỉ có một suy nghĩ duy nhất: Trả thù. Được tăng thêm những sức mạnh siêu nhiên và kì bí, Max không ngần ngại dấn thân vào thế giới ngầm, nơi có thủ phạm sát hại gia đình anh và những kẻ thù vô cùng nguy hiểm, nằm ngoài thế giới tự nhiên. Không gì có thể cản bước Max ngoại trừ một sự phản bội mà anh không thể ngờ tới...</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Beau Bridges","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324480);
