INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-do-vat', 'Võ Sĩ Đô Vật', 'The Wrestler', 'https://phimimg.com/upload/vod/20240207-1/aab6e04998bad0bc45773b87211d4dbf.jpg', 'https://phimimg.com/upload/vod/20240207-1/009ed7a38cd2cabf965f7cca1d425fad.jpg', '<p>Bộ phim tâm lý - hành động về chuyện tình giữa chàng võ sỹ và một vũ nữ thoát ý đã nhận giải Sư Tử Vàng cho Phim hay nhất tại LHP Quốc tế Venice 2008. Một cảnh lãng mạn trong The Wrestler. Randy The Ram Robinson (Mickey Rourke) là một võ sỹ chuyên nghiệp. Sau khi bị đột quỵ tại một trận thi đấu nhỏ, The Ram được bác sỹ thông báo rằng anh sẽ chết nếu tiếp tục thi đấu trở lại.Trong nỗ lực bắt đầu cuộc sống mới, Robinson xin việc làm tại một quán ăn và làm quen với Cassidy (Marisa Tomei), một vũ nữ thoát y đứng tuổi. Tình yêu nảy nở giữa hai người và Robinson đã mơ về hạnh phúc tương lai bên cạnh người yêu cũng như nối lại mối quan hệ với cô con gái lâu ngày không gặp Stephanie (Evan Rachel Wood).</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mickey Rourke","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Todd Barry","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
