INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thi-an-do', 'Sử Thi Ấn Độ', 'Jodhaa Akbar', 'https://phimimg.com/upload/vod/20240207-1/12b268c0a35546d940fff2eef0b2bc7f.jpg', 'https://phimimg.com/upload/vod/20240207-1/a3b2fceb8ad856e05d17bce9d8979432.jpg', '<p>Một câu chuyện tình yêu ở thế kỷ XVI về cuộc hôn nhân liên minh đã nảy sinh tình yêu đích thực giữa hoàng đế Mughal và công chúa Rajput.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Hrithik Roshan","avatar":""},{"name":"Aishwarya Rai Bachchan","avatar":""},{"name":"Sonu Sood","avatar":""},{"name":"Kulbhushan Kharbanda","avatar":""},{"name":"Suhasini Mulay","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324480);
