INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-dai-bang', 'Mắt Đại Bàng', 'Eagle Eye', 'https://phimimg.com/upload/vod/20240207-1/9fbbdf952da85e56cf1280f5f1d8beb6.jpg', 'https://phimimg.com/upload/vod/20240207-1/23eea8ecc41d4e2b24a4926245d0a77a.jpg', '<p>Jerry và Rachel là hai người xa lạ gặp nhau bởi một cuộc điện thoại bí ẩn từ một người phụ nữ mà họ chưa từng gặp mặt. Đe dọa tính mạng và gia đình của họ, cô đẩy Jerry và Rachel vào hàng loạt tình huống ngày càng nguy hiểm, sử dụng công nghệ của cuộc sống hàng ngày để theo dõi và kiểm soát mọi hành động của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Rosario Dawson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
