INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mo-coi-1', 'Sát Thủ Mồ Côi 1', 'Largo Winch', 'https://phimimg.com/upload/vod/20240128-1/8416206cd164ca356ffe8a3be8d1a710.jpg', 'https://phimimg.com/upload/vod/20240128-1/fce458aadf282a1adaa89971fc14feae.jpg', '<p>Sau cái chết của cha nuôi mình, Largo Winch thay cha làm giám đốc của Tập đoàn W. Mọi người đều bất ngờ khi anh quyết định bán công ty để thực hiện khát vọng tham gia vào các hoạt động từ thiện. Tuy nhiên, trước khi hợp đồng hoàn tất, anh bị cáo buộc tội ác chống lại nhân loại của một nhân chứng bí ẩn. Để chứng minh cho sự vô tội của mình, Largo phải hồi tưởng cuộc sống quá khứ của mình, trong trái tim của rừng rậm Myanmar...</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tomer Sisley","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Predrag Manojlovic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324480);
