INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-cuoc-thuong-dang', 'Quyền Cước Thượng Đẳng', 'Chocolate', 'https://phimimg.com/upload/vod/20240205-1/becc808d3eb20cc14a3198414eb3f7aa.jpg', 'https://phimimg.com/upload/vod/20240205-1/7377a8128cd84a79df320aac71d8c506.jpg', '<p>Bộ phim nói về một cô bé mắc chứng bệnh tự kỉ tên là Zen, cô bé là kết quả tình yêu của Mashashi - một thương gia người Nhật và Anna - người tình của một tên trùm có thế lực tại Thái Lan. Zen có khả năng học võ từ những người xung quanh, và điểm yếu của Zen là sợ... ruồi. Anna bị mắc chứng bệnh ung thư, không có tiền đóng viện phí vì thế Zen và Moom - anh trai nuôi phải đi đòi tiền nợ, với khả năng võ của mình, Zen đã đánh cho chúng một trận tơi bời và đòi được tiền. Không bao lâu thì tên trùm tìm ra được chỗ ở của hai mẹ con Anna, hắn đã quay về trả thù lại món nợ xưa kia mà Anna đã gây ra cho hắn với tuyên bố Sẽ trả cả vốn lẫn lời. Zen sẽ phải làm gì để bảo vệ cha mẹ của mình trước thế lực đen tối?</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"JeeJa Yanin","avatar":""},{"name":"Hiroshi Abe","avatar":""},{"name":"Pongpat Wachirabunjong","avatar":""},{"name":"Taphon Phopwandee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324480);
