INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-ma', 'Thị Trấn Ma', 'Ghost Town', 'https://phimimg.com/upload/vod/20240128-1/af3dbcdf3b7ad96cf4c430863ed3dbf5.jpg', 'https://phimimg.com/upload/vod/20240128-1/09c6c89892d8571b2d9c75634c2fc343.jpg', '<p>Bertram Pincus là một người đàn ông có kỹ năng nhân dân để lại nhiều điều mong muốn. Khi Pincus chết bất ngờ, nhưng được hồi sinh một cách kỳ diệu sau bảy phút, anh thức dậy để phát hiện ra rằng bây giờ anh ta có khả năng gây phiền nhiễu để nhìn thấy ma.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324480);
