INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-giao-huong-tokyo', 'Bảng Giao Hưởng Tokyo', 'Tokyo Sonata', 'https://phimimg.com/upload/vod/20240126-1/38799f727e3d0f92ee5b484ffb3ac420.jpg', 'https://phimimg.com/upload/vod/20240126-1/c410af9bca7ad517020e3bf084ea3928.jpg', '<p>Tokyo Sonata kể về cuộc sống của một gia đình lao động bình thường ở Tokyo, gia đình Sasaki, bao gồm chồng (Sasaki Ryuhei), vợ (Megumi) và hai đứa con trai Takashi và Kenji. Ryuhei có một công việc văn phòng tốt đẹp, nhưng bỗng một ngày kia bị đuổi việc vì đã có các công nhân người Hoa chịu làm việc với giá rẻ hơn. Khi đang đi tìm việc làm, Ryuhei gặp lại người bạn cũ Kurosu, cũng vừa mất việc...</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Teruyuki Kagawa","avatar":""},{"name":"Kyôko Koizumi","avatar":""},{"name":"Yû Koyanagi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
