INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-chuon-chuon', 'Siêu Nhân Chuồn Chuồn', 'Superhero Movie', 'https://phimimg.com/upload/vod/20240123-1/5fb5cb746142c8c41e64aee10f9234c6.jpg', 'https://phimimg.com/upload/vod/20240123-1/fbd1e14ff397417295fc3bcd4da1f99c.jpg', '<p>Đội ngũ đằng sau Scary Movie đảm nhận thể loại truyện tranh trong câu chuyện này về Rick Riker, một thiếu niên mọt sách được thấm nhuần siêu năng lực bởi một con chuồn chuồn phóng xạ. Và bởi vì mọi anh hùng đều cần kẻ thù, hãy nhập Lou Landers, hay còn gọi là Đồng hồ cát ngốc nghếch phản diện.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drake Bell","avatar":""},{"name":"Sara Paxton","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Leslie Nielsen","avatar":""},{"name":"Kevin Hart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324481);
