INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-dung-khach-vao-nha', 'Mời Đúng Khách Vào Nhà', 'Let The Right One In', 'https://phimimg.com/upload/vod/20240123-1/1ace23cb2575e3c648c25cc6f5c4c7f7.jpg', 'https://phimimg.com/upload/vod/20240123-1/da9325a7b9dc262e5be68e1e51771a45.jpg', '<p>Let the Right One In (Hãy Để Đúng Người Vào) ngụ ý đến một “tập quán” của ma cà rồng, chỉ có thể vào nhà người khác khi được chủ nhân cho phép. Phim mang đầy đủ tính chất của một phim ma cà rồng kinh điển. Những con ma cà rồng bốc cháy dưới ánh sáng mặt trời, không thể ăn được gì khác ngoài máu, không thể vào nhà khi chưa được mời, cắn cổ và vặn đầu người khác một cách dễ dàng… Nhưng không hề gây cho người xem ảo tưởng về sức mạnh của ma cà rồng, mà ngược lại, tạo cảm giác rất thật, rất thuyết phục về sự tồn tại của chúng. Phim được xếp loại R vì có những cảnh bạo lực và đầy máu me, nhưng không hoàn toàn là một phim kinh dị, mà còn là một bộ phim nhân văn sâu sắc, mang đến những ấn tượng khó quên.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Kåre Hedebrant","avatar":""},{"name":"Lina Leandersson","avatar":""},{"name":"Per Ragnar","avatar":""},{"name":"Henrik Dahl","avatar":""},{"name":"Karin Bergquist","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
