INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-sach-ma-thuat', 'Trang Sách Ma Thuật', 'Inkheart', 'https://phimimg.com/upload/vod/20240124-1/0f9879f8e59ea7a83475e7ba9830525b.jpg', 'https://phimimg.com/upload/vod/20240124-1/ff52d714b77ec43990f8f1f31d205a9f.jpg', '<p>Từ sau khi mẹ mất tích lúc cô bé còn nhỏ, Meggie luôn rong ruổi theo bố đi từ nơi này đến nơi khác để tìm một bản sao của quyển sách Inkheart. Mãi đến khi chạm trán nhân vật bí ẩn tên Dustfinger, Meggie mới biết bố mình có khả năng đưa những nhân vật từ sách ra ngoài đời thực. Và quyển Inkheart chính là chìa khóa để đưa mẹ cô bé trở về.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Eliza Bennett","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Helen Mirren","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
