INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-nuoc-uc', 'Chuyện Tình Nước Úc', 'Australia', 'https://phimimg.com/upload/vod/20240123-1/d84f3c6600de177f65d41b452ccf98c1.jpg', 'https://phimimg.com/upload/vod/20240123-1/38628cf654142c90f1f579fa653943eb.jpg', '<p>Một nữ quý tộc dòng dõi Anh được thừa kế một trang trại gia súc khổng lồ ở miền Bắc tên là Sarah Ashley, bị lạc mất gia đình khi những tiếng bom đầu tiên rền vang trên nước Úc. Được người chăn bò trong lâu đài của gia đình giúp đỡ vượt qua cơn hoạn nạn, cô đã cùng anh trốn chạy dưới làn mưa bom của phát xít Nhật. Từ chỗ không ưa nổi anh chàng thô lỗ này, Sarah dần dần đã rơi vào lưới tình…</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Shea Adams","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
