INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tro-lai', 'Người Hùng Trở Lại', 'JCVD', 'https://phimimg.com/upload/vod/20240123-1/6ed5fd070de5dc76e89452b76715065a.jpg', 'https://phimimg.com/upload/vod/20240123-1/6d09c896ab6dde52ba196e61e3d29776.jpg', '<p>Giữa các vấn đề về thuế và cuộc chiến pháp lý với vợ để giành quyền nuôi con gái, đây là khoảng thời gian khó khăn đối với ngôi sao phim hành động, người nhận thấy rằng ngay cả Steven Seagal cũng đã giành được một vai diễn từ anh ấy! Phiên bản hư cấu này của Jean-Claude Van Damme trở về đất nước nơi anh sinh ra để tìm kiếm hòa bình và yên tĩnh mà anh không còn có thể tận hưởng ở Hoa Kỳ, nhưng lại vô tình tham gia vào một vụ cướp ngân hàng với các con tin.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"François Damiens","avatar":""},{"name":"Zinedine Soualem","avatar":""},{"name":"Karim Belkhadra","avatar":""},{"name":"Jean-François Wolff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
