INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-valse-cua-ky-uc', 'Điệu Valse Của Ký Ức', 'Waltz With Bashir', 'https://phimimg.com/upload/vod/20240121-1/b260778a4cbaf12b7363fda481a52b38.jpg', 'https://phimimg.com/upload/vod/20240121-1/bdbf0a08b807bef00fc259d7486c802a.jpg', '<p>Một đạo diễn phim Israel đã phỏng vấn những cựu chiến binh đồng nghiệp của cuộc xâm lược Lebanon năm 1982 để xây dựng lại những kỷ niệm của chính mình về thời hạn dịch vụ của mình trong cuộc xung đột đó.</p>', 'Full', 1, 'hoathinh', 'completed', 30, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324481);
