INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chuong-tu-than', 'Hồi Chuông Tử Thần', 'Death Bell', 'https://phimimg.com/upload/vod/20240121-1/3762eec6586161cea6afd5412f621760.jpg', 'https://phimimg.com/upload/vod/20240121-1/6666d3cf090756653c98e72d1a02d015.jpg', '<p>20 học sinh giỏi nhất của trường Trung học Chang-ahn thường tập trung lại với nhau vào ngày thứ bảy. Những học sinh này ngồi trong lớp học, háo hức tham dự bài giảng do Chang-wook và ba cộng sự tổ chức. Giữa lúc bài học đang diễn ra, thì bỗng nhiên từ loa phóng thanh phát ra âm nhạc và TV tự động bật lên. Các học sinh càng sửng sốt hơn khi họ thấy Hye-yeong trên TV và cô đang bị dìm trong một bể đầy nước. Sau đó một giọng nói phát ra và hỏi những học sinh này một câu hỏi, câu trả lời đúng sẽ cứu mạng của Hye-yeong, còn nếu trả lời sai thì cô sẽ chết. 20 học sinh chỉ có một thời gian ngắn để nghĩ ra câu trả lời và không có lối thoát nào để họ có thể ra khỏi trường Chang-ahn. Và ngày càng nhiều học sinh lần lượt bị biến mất khi các câu hỏi lần lượt được đưa ra. Một bài kiểm tra giữa kỳ đẫm máu cứ thế diễn ra.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"In-sook Choi","avatar":""},{"name":"Da-Geon","avatar":""},{"name":"Sung Jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
