INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-new-york', 'Chuyện Tình New York', 'New York, I Love You', 'https://phimimg.com/upload/vod/20240104-1/968508eeab8b87a923a293498cadd866.jpg', 'https://phimimg.com/upload/vod/20240104-1/d4e1f2ddc0063e323796de6009aa9e6c.jpg', '<p>New York, I Love You đi sâu vào cuộc sống thân mật của người dân New York khi họ vật lộn, vui thích và tìm kiếm tình yêu. Hành trình từ Quận Kim cương ở trung tâm Manhattan, qua Khu phố Tàu và Upper East Side, hướng tới Ngôi làng, đến Tribeca và Brooklyn khi những người yêu nhau ở mọi lứa tuổi cố gắng tìm kiếm sự lãng mạn ở Big Apple.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Andy García","avatar":""},{"name":"Rachel Bilson","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Irrfan Khan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
