INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-bong-dem', 'Kỵ Sĩ Bóng Đêm', 'The Dark Knight', 'https://phimimg.com/upload/vod/20240104-1/b2748e456090a1c43b246c014b60fa1a.jpg', 'https://phimimg.com/upload/vod/20240104-1/2cae46be24f514793c9e873f6de0fc32.jpg', '<p>Người dơi bước vào giai đoạn cam go nhất trong cuộc chiến chống lại cái ác khi tên tội phạm bậc thầy The Joker xuất hiện. Các tay trùm thuê The Joker giết người dơi để trả thù cho chỗ tài sản phi pháp bị anh lật tẩy. Tiếp tay cho The Joker là toàn bộ tội phạm ở thành phố Gotham, những kẻ đang bị bộ ba Người dơi – Trung úy Gordon – Luật sư Harvey Dent thu hẹp đất sống. Hàng loạt vụ tấn công xảy ra khiến Người dơi lúng túng. Các quan chức bị sát hại, người dân không dám ra đường buổi tối vì sợ bị giết, mọi lối ra vào thành phố Gotham bị phong tỏa. Tất cả đều do một tay The Joker sắp đặt. Luật sư Dent và cô bạn lâu năm của Người dơi là Rachel Dawes bị lôi đến hai nhà kho chứa bom hẹn giờ. Quỷ kế của The Joker khiến Người dơi không kịp đến cứu bạn, luật sư Dent may mắn thoát chết nhưng bị cháy nửa mặt. The Joker giúp Dent thoát khỏi bệnh viện, đồng thời xúi giục y trút hết hận thù lên người dơi, cảnh sát và các ông trùm. Điên cuồng vì mất nàng Dawes, luật sư Dent trở thành kẻ Lưỡng diện xấu xa, trong số các nạn nhân của y suýt nữa có cả người dơi và toàn bộ gia đình trung úy Gordon. Không muốn dân chúng Gotham mất tinh thần khi biết sự thật về người đứng đầu thành phố, Người dơi quyết định đứng ra nhận tội thay Dent...</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Heath Ledger","avatar":""},{"name":"Aaron Eckhart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
