INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nhan-benjamin', 'Dị Nhân Benjamin', 'The Curious Case Of Benjamin Button', 'https://phimimg.com/upload/vod/20240104-1/dd4fd79f4306284241cfc727c2ba96d6.jpg', 'https://phimimg.com/upload/vod/20240104-1/0f37b351f720d3d6f0323c0a1a4f5364.jpg', '<p>Vào ngày mà cơn bão Katrina đánh vào New Orleans, Daisy Williams (Nee Fuller) đang ở trong một bệnh viện New Orleans. Ở bên cô là con gái trưởng thành của cô, Caroline. Daisy yêu cầu Caroline đọc to, cuốn nhật ký của người bạn suốt đời của Daisy, Nút Benjamin. Nhật ký của Benjamin kể lại toàn bộ cuộc sống phi thường của mình, khía cạnh bất thường chính của việc anh ta lùi về phía sau, được chẩn đoán mắc một số bệnh lão hóa khi sinh và do đó có rất ít cơ hội sống sót, nhưng người sống sót và trở nên trẻ hơn với thời gian. Bị bỏ rơi bởi cha đẻ của mình, Nút Thomas, sau khi bà mẹ ruột của Benjamin đã chết trong sinh con, Benjamin được Queenie nuôi dưỡng, một người phụ nữ da đen và người chăm sóc tại một người cao niên về nhà. Bà của Daisy là một cư dân tại nhà đó, nơi cô gặp Benjamin lần đầu tiên. Mặc dù tách biệt trong những năm qua, Daisy và Benjamin vẫn tiếp xúc trong suốt cuộc đời của họ, kết nối lại trong bốn mươi tuổi khi ở tuổi, cuối cùng họ cũng khớp. Một số tiết lộ trong nhật ký của Benjamin rất khó đọc, đặc biệt là khi nó liên quan đến thời điểm kết nối lại giữa Benjamin và Daisy, khi Daisy già đi và Benjamin phát triển trẻ hơn trong những năm tuổi thơ.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
