INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiem-nguy-o-bangkok', 'Hiểm Nguy Ở Bangkok', 'Bangkok Dangerous', 'https://phimimg.com/upload/vod/20240104-1/7a2d0e2a5de8d3697ce1ec8ad6b6f54a.jpg', 'https://phimimg.com/upload/vod/20240104-1/f9f3612ec5c5ef3af3c3a1a136260a0b.jpg', '<p>Cuộc đời của một sát thủ giấu tên đã có một chuyển biến bất ngờ khi anh hành trình đến Thái Lan để hoàn thành một hợp đồng ám sát. Joe (Nicolas Cage), một kẻ giết người tàn nhẫn, hắn đến Bangkok để thi hành bốn bản hợp đồng cho tên tội phạm khét tiếng tên là Surat, hắn thuê Kong (Shahkrit Yamnarm), một tên rác rưởi trên phố và chuyên móc túi, để chạy việc vặt cho hắn với mục đích che đậy dấu vết của hắn bằng cách giết hắn khi nhiệm vụ gần hoàn thành.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Shahkrit Yamnarm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
