INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-cuoi-cung', 'Sứ Mệnh Cuối Cùng', 'Righteous Kill', 'https://phimimg.com/upload/vod/20240104-1/34bdcd30d81b2f95b589a4c9ab603d49.jpg', 'https://phimimg.com/upload/vod/20240104-1/fbc762ce15347a59536e77d6c373c8c5.jpg', '<p>Sứ mệnh cuối cùng kể câu chuyện về hai cảnh sát điều tra lừng danh David Fish và Thomas Cowan của Sở cảnh sát New York. Sau 30 năm cống hiến cho ngành trong một môi trường làm việc đầy áp lực và đoạt nhiều huy chương, hai người đang chuẩn bị cho ngày về hưu thanh thản, nhưng đúng vào ngày cuối cùng họ trút bỏ chiếc áo cảnh sát thì cả hai được cử đi điều tra một vụ án mạng mà nạn nhân là một tên gangster khét tiếng, liên quan đến một vụ án mà họ đã từng điều tra cách đó vài năm.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Carla Gugino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
