INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jumper-nhung-ke-thong-tri', 'Jumper: Những Kẻ Thống Trị', 'Jumper', 'null', 'https://phimimg.com/upload/vod/20240108-1/1e251ea82342e6f7995fcaa5a25991b1.jpg', '<p>Một chàng trai mới phát hiện ra mình có năng lực dịch chuyển tức thời theo ý muốn, nhưng chuyến vi vu của anh khiến anh lọt vào tầm ngắm của một kẻ địch rất mạnh.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Rachel Bilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
