INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trung-phat-vung-chien-su', 'Kẻ Trừng Phạt: Vùng Chiến Sự', 'Punisher: War Zone', 'https://phimimg.com/upload/vod/20240108-1/fa800b160c8e4efe30122e411f717bcb.jpg', 'https://phimimg.com/upload/vod/20240108-1/d3eb1145305288f54c4f2d76de47fb50.jpg', '<p>Lâu đài Frank, người đàn ông quân đội cũ có gia đình bị giết bởi tội phạm, người đã trở thành một Vigilante được gọi là kẻ trừng phạt, diễn ra theo cả một gia đình mob và khiến tất cả mọi người ngoại trừ Enforcer Billy Russoti. Anh ta theo dõi Russoti xuống và đuổi theo anh ta vào một chiếc VAT được sử dụng để nghiền chai. Frank bật máy nghiền hy vọng nó sẽ chăm sóc anh ta nhưng nó không. Anh ta sống sót nhưng vẫn duy trì những chấn thương rất nặng mà ngay cả khi phẫu thuật thẩm mỹ, mặt anh ta trông giống như một trò chơi ghép hình. Vì vậy, ông quyết định áp dụng tên ghép hình. Frank người đã giết một trong những người của Russoti, những người không biết đến anh ta là một người được nuôi dưỡng bí mật, quyết định đóng gói nó vào. Nhưng khi anh ta học Russoti không chết và đang tìm kiếm số tiền mà anh ta giao phó cho Fed và sẽ đi tìm nó nhà có nghĩa là gia đình anh đang gặp nguy hiểm. Vì vậy, Frank cố gắng cứu họ. Nhưng Russoti muốn trả thù Frank để anh ta thoát ra rằng anh trai mình quá điên rồ đến nỗi anh ta cam kết với một tị nạn, để đối phó với anh ta. Và cũng là một Fed một người bạn của người đàn ông Frank đã giết chết anh ta quá.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
