INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hang-xom-kinh-di', 'Người Hàng Xóm Kinh Dị', 'Lakeview Terrace', 'https://phimimg.com/upload/vod/20231231-1/e202f975dca2cb688361587a6805ddae.jpg', 'https://phimimg.com/upload/vod/20231231-1/6a53b0a60edacf06a8286fd6d9384844.jpg', '<p>“Lakeview Terrace” là địa danh một thắng cảnh của Los Angeles có một cái hồ rộng, xung quanh có khu đất thơ mộng, cây cối, và nhiều công viên cho người đến cắm trại hoặc cư ngụ trong những căn lều hoặc nhà lưu động do xe kéo. Nơi đó thuộc quận Trinity County của CA, địa phương Lewiston của LA. Đây cũng là địa phương mà năm 1991, người tài xế tắc xi da đen tên Rodney King bị bốn cảnh sát LAPD đánh gần chết vì chạy quá tốc độ, trong lúc có từ bốn đến sáu LAPD khác đứng nhìn. Tất cả quang cảnh được thu hình từ xa, gởi ra thế giới. Tòa án xử. Các cảnh sát viên được tha bổng. Đó là lý do chính khiến người da đen nổi loạn, đốt phá Los Angeles năm 1992</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Ron Glass","avatar":""},{"name":"Justin Chambers","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
