INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-su-tinh-yeu', 'Quân Sư Tình Yêu', 'The Love Guru', 'https://phimimg.com/upload/vod/20231231-1/af3b437a5b0b617f2d1606070a837400.jpg', 'https://phimimg.com/upload/vod/20231231-1/c71a15280cdd32731725b4e278778288.jpg', '<p>Sinh ra ở Mỹ và lớn lên trong một đạo tràng của Ấn Độ, Pitka trở về quê hương của mình để tìm kiếm vận may với tư cách là một nhà tâm linh và chuyên gia tự lực. Các kỹ năng của anh ấy được thử thách khi anh ấy phải đưa cuộc hôn nhân của một vận động viên khúc côn cầu tan vỡ trở lại đúng thời điểm để người đàn ông này giúp đội của anh ấy giành được Cúp Stanley.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Meagan Good","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324481);
