INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-diet-vong', 'Ngày Diệt Vong', 'Doomsday', 'null', 'https://phimimg.com/upload/vod/20231231-1/6a0d4386417ebbcba6a4cba7624be744.jpg', '<p>Khi dịch bệnh virus bùng phát ở Anh, chính phủ đã cách ly những người nhiễm bệnh trong một thành phố có tường bao kín, nhưng căn bệnh này lại xuất hiện 30 năm sau đó.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rhona Mitra","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Adrian Lester","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
