INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-spirit', 'Người Hùng Spirit', 'The Spirit', 'https://phimimg.com/upload/vod/20231231-1/764a6be1e388e22533a8199316fa346b.jpg', 'https://phimimg.com/upload/vod/20231231-1/6cee08402130fdf48e83eaeac648e4de.jpg', '<p>The Spirit là câu chuyện về Denny Colt, một viên cảnh sát được cho là đã bị giết chết, nhưng rồi anh lại tái sinh một cách bí ẩn đằng sau lớp mặt nạ của một người chuyên săn lùng những tên tội phạm với biệt danh Hồn Ma. Với mong muốn bảo vệ sự yên bình cho Central City, Spirit quyết tâm sẽ tóm bằng được những tên ác ôn ra khỏi bóng tối, và nhất là tên đầu sỏ của bọn chúng, một kẻ ngông cuồng mắc chứng bệnh hoang tưởng tự đại mang biệt danh Octopus. Tuy nhiên, nhiệm vụ của Spirit thật không dễ dàng chút nào khi xung quanh anh luôn cũng có nhiều người đẹp tìm cách quyến rũ Spirit, nhưng đồng thời cũng có thể ra tay giết hại anh bất kì lúc nào. Mặc dù vậy, vẫn có một người yêu không bao giờ phản bội anh, và với nàng, anh mãi luôn là chính mình. Đó chính là Central City, quê hương cổ xưa kiêu hãnh mà anh đã được sinh ra những hai lần...</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Macht","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Scarlett Johansson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
