INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-sat-than-binh', 'Thiên Sát Thần Binh', 'The Divine Weapon', 'https://phimimg.com/upload/vod/20240102-1/d213e0c4694f4a85b0d04486faa4b914.jpg', 'https://phimimg.com/upload/vod/20240102-1/ce3a0c4b14920f5d5cced64fec01d123.jpg', '<p>Dưới triều đại của vua Sejong vào thế kỷ 15, triều đại Joseon là hiện thân của nhà nước hoàn hảo. Đối với nhà Minh Trung Quốc, cường quốc đầy tham vọng, Joseon là một trở ngại cho việc mở rộng lãnh thổ. Để bảo vệ bản thân khỏi chiến tranh, Vua Sejong đã phát triển một vũ khí bí mật để bảo vệ lãnh thổ của họ và lấy lại đất đai cũng như quyền lực tối cao của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Jae-young","avatar":""},{"name":"Han Da-gam","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Shin Jung-geun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
