INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-song-con', 'Mật Mã Sống Còn', 'Babylon A.D.', 'https://phimimg.com/upload/vod/20240128-1/c281e6cc686f06c8968813fba1fe2fe5.jpg', 'https://phimimg.com/upload/vod/20240128-1/ad98d447a6c149c2d61b24d1d467b92a.jpg', '<p>Thế giới trong một tương lai không xa. Mọi hành động của con người đều bị các vệ tinh theo dõi, giám sát. Phần lớn diện tích trái đất là một vùng chiến sự. Phần còn lại là những sân ga tồi tàn, những thành phố chật ních và những vùng đất hoang bị ngắt quãng bởi các khu vực nhiễm phóng xạ.Toorop, một lính đánh thuê, được giao nhiệm vụ áp tải một chuyến hàng đặc biệt - một cô gái trẻ - từ Đông Âu tới New York. Cùng với Xơ Rebeka, người giám hộ của cô gái trẻ, cả ba phải vượt qua một hành trình dài 6.000 dặm với những trở ngại mà Toorop không bao giờ có thể tưởng tượng ra. Khi Toorop biết được anh là người bảo vệ niềm hy vọng duy nhất của tương lai loài người cũng là lúc anh phải lựa chọn: làm một việc có ý nghĩa ...</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Mélanie Thierry","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Charlotte Rampling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
