INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-xa-em', 'Không Thể Xa Em', 'Made Of Honor', 'https://phimimg.com/upload/vod/20240102-1/1a702ed668c0fe71f205a6ee07054318.jpg', 'https://phimimg.com/upload/vod/20240102-1/45f1eb4627a9f19e25bebe7df1846273.jpg', '<p>Tom là một chàng trai tuấn tú được nhiều cô gái theo đuổi nhưng anh không bao giờ dừng lại với ai quá lâu. Tuy vậy Tom và Hanah lại là đôi bạn thân 10 năm và chưa từng xảy ra mối quan hệ vượt quá tình bạn. Cho đến một lần khi Hanah đi công tác xa, Tom mới cảm nhận được cuộc sống của anh không thể thiếu Hanah, vì vậy anh đợi cô trở về sẽ ngỏ lời cầu hôn. Nào ngờ khi Hanah trở về bên cạnh cô đã có một người đàn ông khác...</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Kevin McKidd","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
