INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-the-xa-em', 'Không Thể Xa Em', 'Made Of Honor', 'không thể xa em made of honor patrick dempsey michelle monaghan kevin mckidd ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fading-of-the-cries', 'Fading Of The Cries', 'Fading Of The Cries', 'https://phimimg.com/upload/vod/20240102-1/2a00c37c2a04d5af20cd9136db252989.jpg', 'https://phimimg.com/upload/vod/20240102-1/9104b2da0637b782c98cd4f182c05a65.jpg', '<p>Jacob, một chàng trai trẻ được trang bị một thanh kiếm chết người, đã cứu Sarah, một cô gái tuổi teen, khỏi Mathias, một ác quỷ độc ác đã bắt đầu tấn công một thị trấn nhỏ trên đất nông nghiệp trong khi tìm kiếm chiếc vòng cổ cổ từng thuộc về chú của Sarah. Jacob lên đường đưa Sarah về nhà an toàn, băng qua những con phố, cánh đồng, nhà thờ và đường hầm dưới lòng đất, trong khi bị lũ sinh vật ma quỷ truy đuổi. Trên đường đi, cả hai đều phải đối mặt với những con quỷ trong chính họ - Sarah bắt đầu hiểu rằng lòng căm thù của cô đối với mẹ và em gái có thể là vô cớ và Jacob phát hiện ra những bí mật trong quá khứ của mình, nhận ra cách duy nhất để thực sự đánh bại lũ quỷ là trở về quê hương. chính nơi gia đình anh bị sát hại.</p>', 'Full', 1, 'single', 'completed', 6, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jordan Matthews","avatar":""},{"name":"Thomas Ian Nicholas","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Mackenzie Rosman","avatar":""},{"name":"Elaine Hendrix","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
