INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-chien', 'Huyết Chiến', 'Fatal Move - Triad Wars', 'https://phimimg.com/upload/vod/20240102-1/db1b9695f8e4c3cd47355096c6e0ff22.jpg', 'https://phimimg.com/upload/vod/20240102-1/eb2917abccbda63433ddad9717a63f11.jpg', '<p>Đại ca hội Tam Hoàng, Lung, là con mồi của lực lượng phòng chống tội phạm. Nhưng gã còn là cái gai trong mắt các thuộc hạ luôn nuôi ý định lật đổ. Bên cạnh Lung là hai người thân thiết. Liệu những người anh em, kẻ nào mới là thù?</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung Kam-Bo","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Niu Tien","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
