INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-sam-hoi', 'Hành Trình Sám Hối', 'Seven Pounds', 'https://phimimg.com/upload/vod/20240102-1/7c367cc9354899bcfad6f34c25494832.jpg', 'https://phimimg.com/upload/vod/20240102-1/b4f36a148516e842d6d7502c9b0ede60.jpg', '<p>Bị đè nặng bởi một bí mật đen tối, đặc vụ Ben Thomas của Sở Thuế Vụ cố gắng giúp cải thiện cuộc sống của bảy người lạ đang cần có một cơ hội thứ hai.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Elpidia Carrillo","avatar":""},{"name":"Robinne Lee","avatar":""},{"name":"Joe Nunez","avatar":""},{"name":"Bill Smitrovich","avatar":""},{"name":"Tim Kelleher","avatar":""},{"name":"Gina Hecht","avatar":""},{"name":"Andy Milder","avatar":""},{"name":"Judyann Elder","avatar":""},{"name":"Sarah Jane Morris","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
