INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sita-sings-the-blues', 'Sita Sings The Blues', 'Sita Sings The Blues', 'https://phimimg.com/upload/vod/20231231-1/a1ff20388f4a665868926c87ed7b4b7c.jpg', 'https://phimimg.com/upload/vod/20231231-1/5a81f61345181cc9debb2938a95e1eda.jpg', '<p>Sử dụng giọng hát jazz thập niên 1920 của Annette Hanshaw, câu chuyện sử thi Ấn Độ về hoàng tử bị lưu đày Ramayana và cô dâu Sita của ông được phản chiếu bằng cuộc sống cá nhân đương đại của một người phụ nữ bị hắt hủi và cuộc thảo luận nhẹ nhàng nhưng đầy hiểu biết về bối cảnh lịch sử của bộ ba con rối bóng Ấn Độ.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reena Shah","avatar":""},{"name":"Debargo Sanyal","avatar":""},{"name":"Annette Hanshaw","avatar":""},{"name":"Aseem Chhabra","avatar":""},{"name":"Bhavana Nagulapally","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
