INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhien-hoang-da-trung-quoc', 'Thiên Nhiên Hoang Dã Trung Quốc', 'Wild China', 'https://phimimg.com/upload/vod/20240109-1/39c45737b530876e0e4e2613c3e130ff.jpg', 'https://phimimg.com/upload/vod/20240109-1/0d9b3b16d429c3a0f80ee856c4b201e3.jpg', '<p>Wild China là cái nhìn chuyên sâu ở một trong những quốc gia có nền văn hóa lâu đời nhất trên thế giới. Trung Quốc là một đất nước rộng lớn với hằng hà sa số cảnh quan đa dạng đáng kinh ngạc. Thông qua loạt phim gồm 6 tập, khán giả sẽ được thưởng thức cả một kho báu thiên nhiên và động vật hoang dã, nơi cất dấu bí mật tại những vùng đất hoang sơ nhất của Trung Quốc, cụ thể tìm hiểu: các vương quốc cổ đại Hán, các thảo nguyên Mông Cổ, con đường tơ lụa và các cao nguyên Tây Tạng...</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bernard Hill","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324481);
