INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-truyen-ky', 'Sát Thủ Truyền Kỳ', 'Legendary Assassin', 'https://phimimg.com/upload/vod/20231230-1/e34b61d28729e6b0752c65d285cc98b6.jpg', 'https://phimimg.com/upload/vod/20231230-1/5f3e5d8ad617c4a31376af76fb6863a6.jpg', '<p>Một sát thủ vừa mới hoàn thành vụ giết người mới nhất của mình bị mắc kẹt trên một hòn đảo, khi anh ta vô tình kết bạn với một nữ cảnh sát. Khi màn đêm buông xuống, sự thật bất thành văn được tôn trọng bởi cả hai phía của luật pháp bị phá vỡ. Sau khi hài cốt của một thi thể thuộc về một trùm ma túy và thủ lĩnh tổ chức tội phạm được tìm thấy, sự hỗn loạn xảy ra và bọn tội phạm tàn phá những con phố từng yên bình trong một cuộc chạy đua với thời gian để tìm ra kẻ giết người bí ẩn đang thả rông và khát máu.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Jing","avatar":""},{"name":"Celina Jade","avatar":""},{"name":"Kara Hui","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324481);
