INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-lua-doi', 'Sự Lừa Dối', 'Deception', 'https://phimimg.com/upload/vod/20231230-1/a6964362c9f267e1186649ad623caa78.jpg', 'https://phimimg.com/upload/vod/20231230-1/3e141f4742fea2e204a042cbe3dd32c7.jpg', '<p>Là một kiểm toán viên của công ty làm việc ở một số văn phòng khác nhau, Jonathan McQuarry lang thang không nơi nương tựa giữa những tay môi giới quyền lực ở New York. Cuộc gặp gỡ tình cờ với luật sư lôi cuốn Wyatt Bose dẫn đến việc Jonathan được giới thiệu về The List, một câu lạc bộ tình dục ngầm. Jonathan bắt đầu ngoại tình với một người phụ nữ chỉ được biết đến với cái tên S, người đã giới thiệu Jonathan với một thế giới phản bội và giết người.</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Andrew Ginsburg","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
