INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-dang-yeu', 'Kẻ Thù Đáng Yêu', 'My Dear Enemy', 'https://phimimg.com/upload/vod/20231230-1/f96fc137f1ca3039c1c7586bd41b6579.jpg', 'https://phimimg.com/upload/vod/20231230-1/736397aac9a2395f9222cf61bc2096af.jpg', '<p>Nghỉ ngơi, độc thân và ở tuổi ba mươi, hee-soo là khốn khổ. Tuyệt vọng, cô ấy bắt đầu tìm bạn trai cũ, Byoung-woon, người nợ 3,500 đô la của cô ấy. Khá bất tiện, hóa ra rằng Byoung-woon cũng không có tiền, nhưng anh ấy vui vẻ tuyên bố rằng anh ấy có thể lấy tiền từ một loạt các bạn gái. Nghi ngờ, Hee-Soo quyết định trail Byoung-woon khi anh ta làm cho những viên đạn của Lady Chums khác nhau, chỉ trong trường hợp anh ta cố gắng lừa dối cô. Do đó, cặp đôi bắt đầu vào một hành trình kỳ lạ, hoài cổ cùng nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
