INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phe-tich', 'Phế Tích', 'The Ruins', 'https://phimimg.com/upload/vod/20231219-1/74efc142e7c8622ee81a1824536948e3.jpg', 'https://phimimg.com/upload/vod/20231219-1/bb8ceed83e1445dbd27ef700729353b9.jpg', '<p>Một nhóm bạn trẻ quyết định du lịch khám phá ngôi đền cổ tại Mexico, nơi được bao phủ quanh nó bằng các loại dây leo hiền lành. Sự cố xảy ra khi họ bất chợt đối đấu với một nhóm người dân địa phương và một thành viên trong đoàn đã bị giết. Con đường thoát thân duy nhất là ở trên đỉnh của ngôi đền. Điện thoại đã bị mất, thức ăn và nước uống cũng gần cạn. Họ sẽ làm sao để thoát thân, và có chuyện kì lạ gì ở ngôi đền khi những dây leo hiền lành trở thành sát thủ thầm lặng...</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shawn Ashmore","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Jonathan Tucker","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
