INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-co-nang-nghien-sex', 'Nhật Ký Cô Nàng Nghiện Sex', 'Diary Of A Nymphomaniac', 'https://phimimg.com/upload/vod/20231227-1/b815e909b80e641f61ee4881498b0186.jpg', 'https://phimimg.com/upload/vod/20231227-1/f72100558e99cf46ca664b3839672219.jpg', '<p>Phim kể về cô nàng tri thức mắc chứng nghiện sex Valére. Sau khi người bà có cùng sở thích tình dục khuyên cô hãy viết một cuốn nhật kí, Valére đã ghi lại những mối tình lăng nhăng của mình kể từ lần ân ái đầu tiên năm cô 15 tuổi. Ít lâu sau Valére yêu doanh nhân đẹp trai và thành đạt Jaime khi công việc chính của cô gặp trở ngại. Không may thay, khả năng chăn gối của Jaime không đủ để thỏa mãn Valére. Trước những cơn ghen điên cuồng của chồng, Valére bỏ nhà đi và gia nhập vào hàng ngũ gái làm tiền cao cấp. Từ đây, cô nhận ra nhiều điều về sex cũng như chính bản thân mình... Diary of a Sex Addict được làm lại từ một bộ phim cùng tên sản xuất năm 2001 đã nhận được rất nhiều ý kiến đánh giá của báo giới lúc đó. Phiên bản năm 2008 này của đạo diễn Christian Molina với sự góp mặt của nữ diễn viên Belén Fabra sẽ mang đến nhiều điều mới lạ về thế giới vốn đã rất phức tạp của phụ nữ.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Belén Fabra","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Llum Barrera","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Ángela Molina","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
