INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-troi-chiec-ruong-chan-ly', 'Cổng Trời: Chiếc Rương Chân Lý', 'Stargate: The Ark Of Truth', 'https://phimimg.com/upload/vod/20231219-1/efe6dab9bfcbac258a7759fbdab0f67b.jpg', 'https://phimimg.com/upload/vod/20231219-1/e0e75b26f9b45b5ef79c9ba852d63fbe.jpg', '<p>Stargate: The Ark Of Truth là một bộ phim khoa học viễn tưởng với phần mở đầu là bối cảnh diễn ra trong quá khứ, nơi người xem được gặp nhóm người La Mã và Hy Lạp cổ đại tranh luận về việc dùng phương kế “Ark of Truth” đối phó với Ori. Ark, được hiểu nôm na là phần quan trọng của kỹ thuật, khi được phóng xạ sẽ làm đảo ngược quá trình tẩy não Ori. Là những người không can thiệp vào chuyện nội bộ quốc gia, họ quyết định chống lại việc sử dụng vũ khí này. Và nó được coi là “biến mất” theo thời gian. Sau đó, bộ phim như được “tua” nhanh về hiện tại, nơi khán giả được gặp gỡ nhóm SG-1 của Daniel Jackson, Vala Mal Doran, Cameron Mitchell, và Samantha Carter. Họ đang tìm kiếm một vật gì đó rất giống với Ark. Nhưng trước khi họ tìm được cách mở vũ khí này, họ bị Ori tấn công.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Browder","avatar":""},{"name":"Amanda Tapping","avatar":""},{"name":"Christopher Judge","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
