INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-sparta', 'Chiến Binh Sparta', 'Meet The Spartans', 'https://phimimg.com/upload/vod/20231219-1/894aae0c4aeaf81cf4f50a477e35729a.jpg', 'https://phimimg.com/upload/vod/20231219-1/91d3e6c513c023adf9cc2e2e2ab19713.jpg', '<p>Trong phiên bản nhại phim chính kịch huyền thoại 300 này, Hoàng đế Leonidas và các chiến binh Sparta ca hát khi họ lao vào chiến đấu với quân Ba Tư.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Maguire","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"Ken Davitian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324481);
