INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-rac-roi', 'Phi Vụ Rắc Rối', 'Meet Dave', 'https://phimimg.com/upload/vod/20231215-1/0875036d481f36c8255d40a6ace60406.jpg', 'https://phimimg.com/upload/vod/20231215-1/31aaba5dca8914edbc18a6f9d2a77015.jpg', '<p>Một tàu vũ trụ có hình dạng như một vùng đất của con người đối mặt với Đảo Liberty. Phi hành đoàn của nó (chúng sinh nhỏ, thông minh và unemotion) đang tìm kiếm một quả cầu được gửi từ hành tinh của nó để chiết xuất muối của đại dương, điều này sẽ hủy hoại trái đất. Quả cầu đang sở hữu Josh, con trai lớp năm của một người mẹ duy nhất có xe tấn công tàu vũ trụ ngoài hành tinh cứu thương và làm tê liệt nguồn điện của nó. Phi hành đoàn có 48 giờ để phục hồi quả cầu, ném nó vào Đại Tây Dương và rời khỏi Trái đất. Trong suốt hai ngày, phi hành đoàn của tàu trải nghiệm sự hỗn loạn và cảm xúc ở New York. Làm người khổng lồ của Trái đất - Josh và mẹ của anh ấy - có gì để dạy những người ngoài hành tinh bũng cảm này không? Trong khi đó, Mutiny đang diễn ra và cảnh sát đang đóng cửa.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
