INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-ta-tay-doc', 'Đông Tà Tây Độc', 'Ashes Of Time', 'https://phimimg.com/upload/vod/20231212-1/bdd411f4de9260fe117d2ecd87e05038.jpg', 'https://phimimg.com/upload/vod/20231212-1/55ea02cf2098a082c1a23f09b6cf7420.jpg', '<p>Âu Dương Phong sau khi rời khỏi núi Bạch Đà, đã dừng chân tại một sa mạc, dựng quán và trở thành một người trung gian chuyên giải quyết mọi vấn đề rắc rối của người khác. Những khách hàng lần lượt đến tìm tửu quán của Âu Dương Phong không chỉ để đưa ra những yêu cầu đặc biệt hay nghỉ ngơi đơn thuần, mà còn để kể về những chuyện tình của họ... Bộ phim là bốn câu chuyện nhỏ của bốn nhân vật chính đan xen lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Lâm Thanh Hà","avatar":""},{"name":"Trương Khả Di","avatar":""},{"name":"Trương Quốc Vinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
