INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-trieu-tu-long-2008', 'Huyền Thoại Triệu Tử Long', 'Three Kingdoms: Resurrection Of The Dragon', 'https://phimimg.com/upload/vod/20231211-1/a1f9612c3761fabfb9e634a3b17163b3.jpg', 'https://phimimg.com/upload/vod/20231211-1/a5302f59b7351e87c8cd026946460b64.jpg', '<p>Phim chủ yếu kể về cuộc đời Triệu Tử Long (Triệu Vân) sau khi Lưu Bị ,Trương Phi, Quan Công qua đời. Bối cảnh của phim là cuộc chiến cuối cùng giữa Thục và Ngụy. Triệu Tử Long chỉ đạo con của Trương Phi và Quan Công chinh phạt chiến trường. Ngoài ra, phim còn thông qua hồi ức 60 năm trước của Triệu Tử Long để tái hiện lại những trận đánh hoành tráng và nổi tiếng của thời tam quốc.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Sammo Hung Kam-Bo","avatar":""},{"name":"Maggie Q","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
