INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harold-kumar-thoat-khoi-nguc-guantanamo', 'Harold & Kumar Thoát Khỏi Ngục Guantanamo', 'Harold & Kumar Escape From Guantanamo Bay', 'https://phimimg.com/upload/vod/20231211-1/ec2e67dba4cdda50a362f16f908ab6d0.jpg', 'https://phimimg.com/upload/vod/20231211-1/b6d5d574bdd1ff83ca7faa8a08fde3d4.jpg', '<p>Harold &amp; Kumar là cặp bài trùng. Họ luôn gặp rắc rối nhưng họ luôn bên nhau. Trong 1 chuyến đi đến Amsterdam (Hà Lan),do hút thuốc lào và có ngoại hình châu Á nên...trong thời buổi...họ được xem là khủng bố và bị bắt về Vịnh. Guantanomo,nơi giam giữ những kẻ bị xem là khủng bố. Nhưng cho dù là nơi nào đi nữa thì cũng có thể kìm chân được 2 anh chàng lắm rắc rối này.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cho","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Neil Patrick Harris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
