INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-chuong-chopper-plus-no-ro-giua-mua-dong-cay-hoa-anh-dao-huyen-dieu', 'Vua Hải Tặc: Chương Chopper Plus - Nở Rộ Giữa Mùa đông, Cây Hoa Anh đào Huyền Diệu', 'One Piece Movie 9: Episode Of Chopper Plus - Fuyu Ni Saku, Kiseki No Sakura', 'https://phimimg.com/upload/vod/20231208-1/035c78eeba6466bd0d6a8769ab9f3ccd.jpg', 'https://phimimg.com/upload/vod/20231208-1/2c4c18be1a30e9135659c029fb8da6a3.jpg', '<p>Phim kể về chuyến hành trình của băng Mũ Rơm tới hòn đảo Drum. Tại đây họ gặp được Chopper và chiêu mộ cậu ta làm thành viên mới cho băng hải tặc. Chopper có khả năng biến hình nhờ trái ác quỷ Hito Hito no Mi. Cậu ta cũng là một bác sĩ với khả năng y thuật tuyệt vời. Vì lẽ đó đã trở thành thành viên thứ 6 của băng Hải Tặc Mũ Rơm. Tại đây cả nhóm cũng phải chiến đấu với Mushul, một kẻ có âm mưu thôn tính cả hòn đảo Drum. Quê hương của thành viên mới Chopper và của những người dân vô tội trên đảo.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
