INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-son-my-nhan', 'Giang Sơn Mỹ Nhân', 'An Empress And The Warriors', 'https://phimimg.com/upload/vod/20231210-1/16f7a1b812cd2c0921524705cb568e29.jpg', 'https://phimimg.com/upload/vod/20231210-1/e5dbdfd11ae792d10b33a31eaca6dc47.jpg', '<p>Giang Sơn Mỹ Nhân - An Empress and the Warriors: Phim lấy bối cảnh thời chiến loạn lạc, một cô công công chúa bị gian thần hãm hại phải lưu lạc trong nhân gian. Cô công chúa này may mắn được một nam nhân cứu sống và cưu mang. Khi biết được thân phận thật và sứ mệnh phục quốc của cô. Người nam nhân này đã phụ giúp cô giết chết kẻ thù giành lại giang sơn. Nhưng khi công chúa có được tất cả những gì bị chiếm mất, cô lại thấy ngai vàng không phải là nơi dành cho cô. Liệu cô sẽ lựa chọn lựa tình yêu hay trách nhiệm và vương quyền..</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chung Tử Đơn","avatar":""},{"name":"Lê Minh","avatar":""},{"name":"Trần Tuệ Lâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324481);
