INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('high-school-musical-3-le-tot-nghiep', 'High School Musical 3: Lễ Tốt Nghiệp', 'High School Musical 3: Senior Year', 'https://phimimg.com/upload/vod/20231209-1/02d16f1d3444737620acd18a7e91ec15.jpg', 'https://phimimg.com/upload/vod/20231209-1/7e9ae666bf7a7bb441546b3240f3ff73.jpg', '<p>Khi người cao niên ở trường trung học, Troy và Gabriella đấu tranh với ý tưởng được tách ra khỏi nhau như những cách tiếp cận đại học. Cùng với phần còn lại của Wildcats, họ đứng đầu một vở nhạc kịch mùa xuân để giải quyết kinh nghiệm, hy vọng và sợ hãi về tương lai của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
