INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-la', 'Phép Lạ', 'Miracle At St. Anna', 'https://phimimg.com/upload/vod/20231209-1/cd1bf82f04691192002bb66a0b581254.jpg', 'https://phimimg.com/upload/vod/20231209-1/d19a88f93d8d67bcfbd22d0d57be6ea3.jpg', '<p>Phép Lạ - Miracle at St. Anna: Chuyển thể từ quyển tiểu thuyết cùng tên của James McBride dựa trên những sự kiện lịch sử có thật, Miracle at St. Anna kể lại câu chuyện của 4 người lính Mỹ da đen thuộc đơn vị Buffalo Soldier đóng quân tại Tuscany (Ý) trong suốt Thế chiến II. Những người lính này đã trải nghiệm cảm giác chiến thắng lẫn những bi kịch do chiến tranh mang lại khi chính họ bị mắc kẹt trong vùng chiến tuyến của kẻ thù và bị chia cắt với đơn vị của mình khi một thành viên liều lĩnh mạng sống của anh để cứu lấy sinh mạng của một cậu bé trai người Ý . Bị Tổ Quốc chối bỏ, những người lính đó đã tìm cho mình niềm an ủi ở thị trấn Tuscan xinh đẹp ở St.Anna ..</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Derek Luke","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Laz Alonso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
