INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tat-ca-vi-co-ay', 'Tất Cả Vì Cô Ấy', 'Anything For Her', 'https://phimimg.com/upload/vod/20231208-1/58ed28dc5eea65df1b57cba6c04f1295.jpg', 'https://phimimg.com/upload/vod/20231208-1/1cc826a9f85ca4f23ca9d84b346916d4.jpg', '<p>Lisa và Julien đã kết hôn và có một cuộc sống hạnh phúc bình yên với cậu con trai Oscar. Nhưng cuộc sống của họ thay đổi hoàn toàn vào một buổi sáng, khi cảnh sát đến bắt Lisa với tội danh giết người. Cô bị kết án 20 năm tù. Tin chắc về sự vô tội của vợ mình, Julien quyết định hành động. Anh ấy sẽ sẵn sàng đi bao xa vì cô ấy?</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Vincent Lindon","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Lancelot Roch","avatar":""},{"name":"Olivier Marchal","avatar":""},{"name":"Hammou Graïa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
