INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-truy-lac', 'Ngôi Sao Trụy Lạc', 'Flashbacks Of A Fool', 'https://phimimg.com/upload/vod/20231210-1/a8f63992aad6f47ba750228180e40fd8.jpg', 'https://phimimg.com/upload/vod/20231210-1/6a63729faa25218cfd5e2f75940e7fe2.jpg', '<p>Một ngôi sao Hollywood già nua, Joe Scott, sống một cuộc sống theo chủ nghĩa khoái lạc tự ái, được trợ lý riêng của ông, Ophelia quan sát. Cái chết của người bạn thân thời thơ ấu của anh, Boots, đưa nhân vật chính của chúng ta và bộ phim vào một đoạn hồi tưởng kéo dài về một thị trấn ven biển ở Anh những năm 1970.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Harry Eden","avatar":""},{"name":"Miriam Karlin","avatar":""},{"name":"Jodhi May","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Keeley Hawes","avatar":""},{"name":"Sid Mitchell","avatar":""},{"name":"Alfie Allen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
