INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-hai-sat-thu', 'Câu Chuyện Hai Sát Thủ', 'In Bruges', 'https://phimimg.com/upload/vod/20231208-1/5e7bfb027ca34719dc42b3c057e5c38d.jpg', 'https://phimimg.com/upload/vod/20231208-1/e038b1ae7a9fc530dbfb613edbce58a3.jpg', '<p>Thành phố cổ xưa Bruges tại Bỉ là nơi thích hợp cho những du khách từ khắp nơi trên thế giới đến để tham quan phong cảnh tuyệt đẹp và nghỉ dưỡng. Vì vậy, với 2 tay sát thủ Ray và Ken thì đó chính là nơi ẩn mình lý tưởng kể từ khi cặp bài trùng này thất bại trong nhiệm vụ khó khăn mà ông trùm người Luân Đôn Harry giao cho họ. Trong thời gian chờ đợi cú điện thoại của ông trùm để nhận nhiệm vụ mới, Ray và Ken đành cùng nhau từ từ hưởng thụ cuộc sống yên bình tại đây như những người khách du lịch bình thường khác.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Ciarán Hinds","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324481);
