INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-la-mat', 'Những Kẻ Lạ Mặt', 'The Strangers', 'https://phimimg.com/upload/vod/20231208-1/900b895555aab603e4ce7e08cca7ba81.jpg', 'https://phimimg.com/upload/vod/20231208-1/c01cc7753ece72435e58cb58602c8495.jpg', '<p>After returning from a wedding reception, a couple staying in an isolated vacation house receive a knock on the door in the mid-hours of the night. What ensues is a violent invasion by three strangers, their faces hidden behind masks. The couple find themselves in a violent struggle, in which they go beyond what either of them thought capable in order to survive.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liv Tyler","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Gemma Ward","avatar":""},{"name":"Kip Weeks","avatar":""},{"name":"Laura Margolis","avatar":""},{"name":"Glenn Howerton","avatar":""},{"name":"Alex Fisher","avatar":""},{"name":"Peter Clayton-Luce","avatar":""},{"name":"Nick Barghini","avatar":""},{"name":"Shawn McClellan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324481);
