INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-tam-sat-thu', 'Đệ Tam Sát Thủ', 'Pineapple Express', 'https://phimimg.com/upload/vod/20231219-1/c2806aa565a481347144703980ba3169.jpg', 'https://phimimg.com/upload/vod/20231219-1/1c13c454121802d5588719e0d1abab4a.jpg', '<p>Gã lười nhác Dale Denton chỉ có một lí do duy nhất để tìm đến Saul Silver, một gã lười khác chẳng kém cạnh mình là để tìm cách mua một loại ma túy mới và cực hiếm trên thị trường có tên gọi là Pineapple Express. Thế nhưng, sau khi gặp Saul, Dale vô tình trở thành nhân chứng duy nhất của một vụ giết người được gây ra bởi một nữ cảnh sát và một tay trùm buôn thuốc phiện nguy hiểm nhất của thành phố. Trong cơn hoảng loạn, Dale không còn cách nào khác là quay trở lại và cầu cứu Saul giúp mình vì Pineapple Express là loại ma túy quá hiếm và từ dấu vết của chúng mà bọn sát thủ sẽ tìm ra họ. Trên đường trốn chạy, Dale và Saul mới phát hiện ra rằng họ không chỉ bị ảo giác của loại ma túy kia hành hạ, mà tệ hơn nữa là bọn sát thủ đang truy tìm họ ráo riết nhằm thủ tiêu cả hai càng sớm càng tốt</p>', 'Full', 1, 'single', 'completed', 6, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"James Franco","avatar":""},{"name":"Gary Cole","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324481);
