INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-choi-ve-vuon', 'Tay Chơi Về Vườn', 'Revanche', 'https://phimimg.com/upload/vod/20231208-1/1020eadeebdbe2cdfeaa46882990ba68.jpg', 'https://phimimg.com/upload/vod/20231208-1/d5d0b24ff4d75e9c0dd352d12900d893.jpg', '<p>Một tay chơi khét tiếng mệt mỏi với thời cuộc, chỉ mong sao về vườn với một gái bán hoa hoàn lương đến từ Ucraina, ả Tamara. Nhưng để được vậy, hắn phải làm vụ cướp nhà băng lần cuối để xóa nợ và có đủ tiền bay về miền Nam. Khốn nạn thay Tamara lại vô ý bắn vào tay cảnh sát tình cờ có mặt khi đang trên đường trốn chạy. Alex bỏ trốn đến trang trại của ông nội của hắn và đen sao Robert, tay cảnh sát bị bắn, lại là hàng xóm của ông mình. Ý nghĩ trả thù bắt đầu phát sinh...</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Johannes Krisch","avatar":""},{"name":"Irina Potapenko","avatar":""},{"name":"Andreas Lust","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324481);
