INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-duoi-long-dat', 'Thành Phố Dưới Lòng Đất', 'City of Ember', 'https://phimimg.com/upload/vod/20231204-1/e410eb8cfdc7a8ac02cbee24f7f49874.jpg', 'https://phimimg.com/upload/vod/20231204-1/d79893379084ec0c1369b7df41dbd7d2.jpg', '<p>City Of Ember là bộ phim xoay quanh một thành phố dưới lòng đất tên là Ember. Qua nhiều thế hệ, cư dân thành phố Ember tồn tại và phát triển trong một thế giới kỳ thú của ánh đèn điện lấp lánh dưới lòng đất. Được xây dựng như một nơi trú ẩn cho loài người và được cấp năng lượng bởi một máy phát điện khổng lồ. Nhưng một điều rất đáng tiếc là thành phố này chỉ tồn tại được trong 200 năm. Lúc này, Ember đã trở nên tăm tối do máy phát đã ngưng hoạt động. Chạy đua với thời gian, Doon Harrow và Lina khéo léo vận động những chính trị gia tham nhũng và các nhân vật khó chịu với hy vọng thực hiện được mục tiêu: mang ánh sáng trở lại cho Thành phố Ember...</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Bill Murray","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
