INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-informers', 'The Informers', 'The Informers', 'https://phimimg.com/upload/vod/20231201-1/a467156ceeddea1fbd91c5c3285e9b1c.jpg', 'https://phimimg.com/upload/vod/20231201-1/e39cc99eeac4676ce28f4d49112ce568.jpg', '<p>Một tuyển tập các truyện ngắn giao nhau lấy bối cảnh ở Los Angeles đầu những năm 1980, mô tả một tuần trong cuộc sống của nhiều nhân vật xa lánh xã hội, chủ yếu là những người khá giả, những người làm tê liệt cảm giác trống rỗng của họ bằng tình dục tùy tiện, bạo lực và ma túy.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Kim Basinger","avatar":""},{"name":"Jon Foster","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Chris Isaak","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Lou Taylor Pucci","avatar":""},{"name":"Mel Raido","avatar":""},{"name":"Brad Renfro","avatar":""},{"name":"Theo Rossi","avatar":""},{"name":"Cameron Goodman","avatar":""},{"name":"Aaron Himelstein","avatar":""},{"name":"Jessica Stroup","avatar":""},{"name":"Peter Scanavino","avatar":""},{"name":"Ange","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
