INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-doat', 'Cưỡng Đoạt', 'Taken', 'https://phimimg.com/upload/vod/20231201-1/e8b7f5a2472dfb52502a7fff48826cf6.jpg', 'https://phimimg.com/upload/vod/20231201-1/f76a74b5723c4256fa026cf3412f1a52.jpg', '<p>Bryan là điệp viên đã nghĩ hưu muốn dùng thời gian đó để bù đắp cho Kim- con gái cưng của ông vì thời gian còn làm việc ông đã không có thời gian dành cho vợ con đến nỗi vợ chồng ông phải li dị để vợ ông tìm một bến đỗ mới. Khi con gái muốn đi Paris chơi cùng với cô bạn thân, ông đã có linh tính chẳng lành. Thật vậy, hai cô gái đã bị bắt cóc khi vừa xuống máy bay. Phim Taken là cuộc giải cứu con gái trong vòng 96 tiếng, bằng những kỹ năng của một cựu điệp viên, ông có làm được điều đó không?</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Holly Valance","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Olivier Rabourdin","avatar":""},{"name":"Gérard Watkins","avatar":""},{"name":"Marc Amyot","avatar":""},{"name":"Arben Bajraktaraj","avatar":""},{"name":"Radivoje Bukvić","avatar":""},{"name":"Mathieu Busson","avatar":""},{"name":"Michel Flash","avatar":""},{"name":"Nicolas Gi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
