INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-2008', 'Trốn Chạy', 'Exit Speed', 'https://phimimg.com/upload/vod/20231201-1/4d2eee431d714f6903116b7f6a4eab09.jpg', 'https://phimimg.com/upload/vod/20231201-1/8f9081b8335ccfa56a230c50154cbd4c.jpg', '<p>Vào đêm Giáng sinh, mười người lạ mặt lên xe buýt đi qua Texas. Ở nơi hoang dã xa xôi này họ va chạm với một nhóm nghiện ma túy di chuyển bằng xe đạp. Bị buộc phải rời khỏi đường và bị nhóm giang hồ kia nhốt trong hẻm của một bãi phế liệu bị bỏ rơi. Họ buộc phải sử dụng vũ khí và sự dũng cảm để bảo vệ chống lại băng nhóm đi xe đạp kia. Để sống sót họ phải tiếp tục tấn công.</p>', 'Full', 1, 'single', 'completed', 8, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Desmond Harrington","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"Julie Mond","avatar":""},{"name":"Alice Greczyn","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Gregory Jbara","avatar":""},{"name":"David Rees Snell","avatar":""},{"name":"Kelli Dawn Hancock","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
