INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-beethoven-6-ngoi-sao-moi', 'Chú Chó Beethoven 6: Ngôi Sao Mới', 'Beethoven''s Big Break', 'https://phimimg.com/upload/vod/20231211-1/729b464a389bca314c086c55f886923d.jpg', 'https://phimimg.com/upload/vod/20231211-1/1eb2b8ee55bbe786ddd5fa3ba34e4687.jpg', '<p>Cuộc sống của chú chó hoang Beethoven và bầy cún con chẳng dễ dàng. Nhưng khi một chú chó ngôi sao điện ảnh bị bắt cóc, Beethoven được chọn làm diễn viên thế chỗ.</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Silverman","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Jennifer Finnigan","avatar":""},{"name":"Eddie Griffin","avatar":""},{"name":"Rhea Perlman","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Oscar Nuñez","avatar":""},{"name":"Joey Fatone","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
