INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-delphi', 'Hiệu Ứng Delphi', 'Delphi Effect', 'https://phimimg.com/upload/vod/20231210-1/383a7fca2cc07bd4dd7d80ccd0b6f276.jpg', 'https://phimimg.com/upload/vod/20231210-1/c40ac9b2d4d2796d8ff4b0cfaf25e972.jpg', '<p>Hiệu Ứng Delphi - Delphi Effect kể về cựu điệp viên Jacob Keane bị thu hút trở lại thế giới ngầm của hoạt động gián điệp quốc tế khi đối tác cũ của anh là Marta xuất hiện trở lại sau mười bảy năm. Tuy nhiên, cô đã bị mất trí nhớ trên đường chạy trốn khỏi một cặp sát thủ tâm thần chết người.</p>', 'Full', 1, 'single', 'completed', 9, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fraser Brown","avatar":""},{"name":"Robert Gant","avatar":""},{"name":"Shannen Doherty","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
