INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hieu-ung-delphi', 'Hiệu Ứng Delphi', 'Delphi Effect', 'hiệu ứng delphi delphi effect fraser brown robert gant shannen doherty ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nang-sat-thu-ke-thu-so-mot-cua-cong-chung', 'Bản Năng Sát Thủ: Kẻ Thù Số Một Của Công Chúng', 'Mesrine: Public Enemy #1', 'https://phimimg.com/upload/vod/20231130-1/7c04bdff33121cd93e2293ee276b5122.jpg', 'https://phimimg.com/upload/vod/20231130-1/41bfa6d6aae9a082206fe98160906d14.jpg', '<p>Tháng 3/1973, Mesrine bị bắt giữ nhưng đã thoát khỏi phòng xử án sau khi bắt thẩm phán làm con tin. Đây là thời điểm Mesrine bắt đầu nổi tiếng khắp nước Pháp. Báo chí gọi Mesrine là &quot;kẻ thù số 1 của công chúng&quot;. Tháng 9/1973, Mesrine rơi vào tay của thanh tra cảnh sát Robert Broussard, người tổ chức chiến dịch tiêu diệt hắn ta ở Porte de Clignancourt vào 6 năm sau đó. Sau khoảng thời gian 5 năm ngồi tù tại Santé - một pháo đài kiên cố bao quanh bởi những đại lộ và con đường thanh lịch đằng sau Montparnasse - vào tháng 5/1978, không rõ do nguyên nhân nào mà Mesrine đã đào thoát thành công khỏi nhà tù. Sau gần hai thập kỷ với nhiều vụ cướp, bắt cóc và giết người của Masrine, vào tháng 10.1979, Tổng thống Pháp Giscard d’Estaining đã phải tuyên bố: “Chúng ta thực sự phải kết thúc Masrine”. Ngày 2.11.1979, Masrine đã bị các thành viên Đội cảnh sát đặc biệt của thanh tra Robert Broussard hạ gục trên xe ô tô với 20 phát đạn...</p>', 'Full', 1, 'single', 'completed', 7, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Vincent Cassel","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Mathieu Amalric","avatar":""},{"name":"Gérard Lanvin","avatar":""},{"name":"Samuel Le Bihan","avatar":""},{"name":"Olivier Gourmet","avatar":""},{"name":"Georges Wilson","avatar":""},{"name":"Michel Duchaussoy","avatar":""},{"name":"Anne Consigny","avatar":""},{"name":"Laure Marsac","avatar":""},{"name":"Alain Fromager","avatar":""},{"name":"Alain Doutey","avatar":""},{"name":"Arsène Mosca","avatar":""},{"name":"Christophe Vandevelde","avatar":""},{"name":"Luc Thuillier","avatar":""},{"name":"Serge Bia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
