INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('igor', 'Igor', 'Igor', 'https://phimimg.com/upload/vod/20231129-1/fd16ad5e8a460def8405dcba3998c76a.jpg', 'https://phimimg.com/upload/vod/20231129-1/bd9bb60fce03824427be0ae8e42a5578.jpg', '<p>Trợ lý của một nhà khoa học xấu xa lưng gù sáo rỗng khao khát trở thành một nhà khoa học, khiến phần còn lại của cộng đồng khoa học xấu xa không hài lòng.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2008, 'Thuyết Minh', 'HD', 'Pháp', 0, '[{"name":"John Cusack","avatar":""},{"name":"Myleene Klass","avatar":""},{"name":"Robin Walsh","avatar":""},{"name":"Matt McKenna","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Sean Hayes","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Jay Leno","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"James Lipton","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Arsenio Hall","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Zoë Bright","avatar":""},{"name":"Sophia Eraklis","avatar":""},{"name":"A. Cheron Hall","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
