INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-dem-2008', 'Kẻ Săn Đêm', 'Prom Night', 'https://phimimg.com/upload/vod/20231108-1/8a0e214e5731f0a7a15d242c0d7677d7.jpg', 'https://phimimg.com/upload/vod/20231108-1/08353c115ac840fd032f478108f858d8.jpg', '<p>Vào đêm dạ hội, một nữ sinh cuối cấp vẫn bị ám ảnh bởi cơn ác mộng trong quá khứ cố gắng trốn khỏi kẻ sát nhân định hủy hoại bữa tiệc của cô và bạn bè.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brittany Snow","avatar":""},{"name":"Scott Porter","avatar":""},{"name":"Jessica Stroup","avatar":""},{"name":"Dana Davis","avatar":""},{"name":"Collins Pennie","avatar":""},{"name":"Kelly Blatz","avatar":""},{"name":"Johnathon Schaech","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Shawn Driscoll","avatar":""},{"name":"Brianne Davis","avatar":""},{"name":"Valeri Ross","avatar":""},{"name":"Jessalyn Gilsig","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Mary Mara","avatar":""},{"name":"Allison Kyler","avatar":""},{"name":"Craig Suss","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
