INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-ngoai-tuoi-30-2008', 'Ông Ngoại Tuổi 30', 'Scandal Makers', 'https://phimimg.com/upload/vod/20231120-1/312fe03c352bf85b1d32f319ba3beed0.jpg', 'https://phimimg.com/upload/vod/20231120-1/b196610dcedc4af70f8e1fff5955b0e7.jpg', '<p>Cuộc sống của anh chàng Nam Hyeon Soo độc thân 36 tuổi bỗng nhiên đảo lộn, khi phát hiện mình có một cô con gái 22 tuổi và cô ấy có đứa con trai 6 tuổi. Ngoài ra, Nam Hyeon Soo là người nổi tiếng, nhiều fan, nên anh rất sợ sự việc rùm beng, sự nghiệp tiêu tan. Anh đành chấp nhận con gái và cháu ngoại của mình ở cùng nhà. Từ đây, các rắc rối nhỏ liên tục phát sinh giữa ba người khi ở chung một mái nhà và chính cuộc gặp gỡ này đã thay đổi con người của Nam Hyeon Soo...</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Tae-hyun","avatar":""},{"name":"Park Bo-young","avatar":""},{"name":"Wang Seok-hyeon","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Im Ji-gyu","avatar":""},{"name":"Lim Seung-dae","avatar":""},{"name":"Jung Won-joong","avatar":""},{"name":"Kim Ki-bang","avatar":""},{"name":"Park Young-seo","avatar":""},{"name":"Kim Hye Jin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324481);
