INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-ngoai-tuoi-30-2008', 'Ông Ngoại Tuổi 30', 'Scandal Makers', 'ông ngoại tuổi 30 scandal makers cha tae-hyun park bo-young wang seok-hyeon hwang woo-seul-hye im ji-gyu lim seung-dae jung won-joong kim ki-bang park young-seo kim hye jin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tu-than-2008', 'Cuộc Đua Tử Thần', 'Death Race', 'https://phimimg.com/upload/vod/20231026-1/1dc0258c7684d2d09ca1194ec4302f49.jpg', 'https://phimimg.com/upload/vod/20231026-1/6c07102613206898334e4dd33ff9e2c5.jpg', '<p>Death Race” tái hiện lại bộ phim nổi tiếng &quot;Death Race 2000&quot; của năm 1975 theo phong cách và kỹ xảo hoàn toàn mới. Diễn viên chính do nam tài tử Jason Statham thủ vai, nổi tiếng với seri phim ăn khách như The Transporter, Crank, The Bank Job, War... Người viết kịch bản, đồng đạo diễn của bộ phim mới này, ông Paul W.S. Anderson (người Anh) chuyên thể loại phim khoa học viễn tưởng. Bộ phim sẽ được công chiếu vào tháng 8/2008, hứa hẹn những trận chiến nảy lửa giữa các “anh tài” hùng mạnh không kém “đội quân xe” trong phim Transformer 2 ra mắt năm 2009.Điểm hấp dẫn trong bộ phim hành động viễn tưởng “Death race” với dàn “diễn viên” tham gia đều là các “ngôi sao” nổi tiếng như Ford Mustang GT 2006, Dodge Ram 2004, Porsche 911, Chrysler 300C, BMW 735i 1989, ...</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Natalie Martinez","avatar":""},{"name":"Max Ryan","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Frederick Koehler","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Justin Mader","avatar":""},{"name":"Robert LaSardo","avatar":""},{"name":"Robin Shou","avatar":""},{"name":"Benz Antoine","avatar":""},{"name":"Danny Blanco Hall","avatar":""},{"name":"Christian Paul","avatar":""},{"name":"Janaya Stephens","avatar":""},{"name":"John Fallon","avatar":""},{"name":"Bruc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324481);
