INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-dua-tu-than-2008', 'Cuộc Đua Tử Thần', 'Death Race', 'cuộc đua tử thần death race jason statham joan allen ian mcshane tyrese gibson natalie martinez max ryan jason clarke frederick koehler jacob vargas justin mader robert lasardo robin shou benz antoine danny blanco hall christian paul janaya stephens john fallon bruc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-troi', 'Cổng Trời', 'Stargate: Continuum', 'https://phimimg.com/upload/vod/20231129-1/afdb52f8a33f3e3de9313b47480c63d9.jpg', 'https://phimimg.com/upload/vod/20231129-1/67144177319dde8959953fe28bf86e17.jpg', '<p>Trong phim Cổng Trời, một đơn vị quân đôi ưu tú (SG-1) phải chạy trốn về trái đất trong khi hai thành viên trong số họ đột nhiên biến mất mà ko giải thích được. Nhưng họ trở về thế giới qua &quot;cổng trời&quot; - một cổ máy cổ xưa cho phép họ đi đến hàng trăm hành tinh - chưa bao giờ được khám phá và tiểu sử riêng của họ đã bị xóa bỏ. Trong phim online này, giờ đây họ phải thuyết phục chính quyền và quân đội là thời biểu đã bị thay đổi bởi một thế lực ngoài hành tinh (Ba&#39;al) để xâm chiếm trái đất và thời gian không đứng về phía họ. Liệu phim hay này sẽ diễn biến thế nào mời các bạn cùng theo dõi bộ phim Cổng Trời.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ben Browder","avatar":""},{"name":"Amanda Tapping","avatar":""},{"name":"Christopher Judge","avatar":""},{"name":"Michael Shanks","avatar":""},{"name":"Claudia Black","avatar":""},{"name":"Beau Bridges","avatar":""},{"name":"Richard Dean Anderson","avatar":""},{"name":"Cliff Simon","avatar":""},{"name":"Don S. Davis","avatar":""},{"name":"William Devane","avatar":""},{"name":"Steve Bacic","avatar":""},{"name":"Gary Jones","avatar":""},{"name":"Peter Williams","avatar":""},{"name":"Jacqueline Samuda","avatar":""},{"name":"Jay Williams","avatar":""},{"name":"Corey Turner","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324481);
