INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-gian-chet-su-sup-do', 'Không Gian Chết: Sự Sụp Đổ', 'Dead Space: Downfall', 'https://phimimg.com/upload/vod/20231129-1/87a7945aabdaaec41266766333aa5c61.jpg', 'https://phimimg.com/upload/vod/20231129-1/60d93aab6a85cc8f825cb2c26ea00098.jpg', '<p>Trong một nhiệm vụ khai thác không gian sâu đến một hành tinh xa xôi, một di tích tôn giáo cổ đại - được cho là bằng chứng về sự tồn tại của Chúa - được khai quật và mang lên tàu. Khi cổ vật xấu xa giải phóng một chủng tộc ngoài hành tinh đã ngủ yên từ lâu, cái nhìn thoáng qua về Thiên đường của nó sẽ biến con tàu thành Địa ngục sống. Phần tiền truyện của các sự kiện trong trò chơi điện tử năm 2008 Dead Space.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Boxleitner","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Phil Morris","avatar":""},{"name":"Bob Neill","avatar":""},{"name":"Jim Piddock","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Lia Sargent","avatar":""},{"name":"Hal Sparks","avatar":""},{"name":"Keith Szarabajka","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"David Zyler","avatar":""},{"name":"Kirk Baily","avatar":""},{"name":"Shelly","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý"