INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-doi-xanh-tuoi', 'Cây Đời Xanh Tươi', 'Still Walking', 'https://phimimg.com/upload/vod/20231128-1/0670201dfaec1b04fa2b4c1b4e2d943c.jpg', 'https://phimimg.com/upload/vod/20231128-1/36995d9aefeb225f7985d8685fde6c0f.jpg', '<p>Ryota (Abe Hiroshi thủ vai) là người con trai 40 tuổi trong gia đình Yokoyama. Gần đây anh lấy một phụ nữ góa chồng với đứa con trai mười tuổi từ cuộc hôn nhân trước. Cả ba người cùng đến thăm bố của Ryota. Bây giờ trong nhà chỉ còn bố mẹ của Ryota ở trong căn nhà cũ, nơi đã từng là một trạm y tế khang trang. Vẫn còn dấu tích của trạm y tế năm xưa nơi những lọ thuốc, nhưng bác sĩ - bố Ryota - đã về hưu. Tuy bên ngoài không có vẻ gì khác, nhưng mọi thứ đều đã già đi theo thời gian. Gia đình họp lại để tưởng nhớ người con trai cả, Junpei, qua đời vì một tai nạn khủng khiếp mười lăm năm trước. Ryouta chưa bao giờ đạt được kỳ vọng của gia đình như anh của mình - nối nghiệp trạm y tế của cha. Và vì vậy giữa anh và cha anh ...</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Abe","avatar":""},{"name":"Kirin Kiki","avatar":""},{"name":"Yui Natsukawa","avatar":""},{"name":"Yoshio Harada","avatar":""},{"name":"YOU","avatar":""},{"name":"Kazuya Takahashi","avatar":""},{"name":"Hotaru Nomoto","avatar":""},{"name":"Ryôga Hayashi","avatar":""},{"name":"Shohei Tanaka","avatar":""},{"name":"Susumu Terajima","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
