INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-do', 'Mỹ Nhân Đồ', 'Portrait of a Beauty', 'https://phimimg.com/upload/vod/20231129-1/2003b1e0bfa7fed03a3618eea6233514.jpg', 'https://phimimg.com/upload/vod/20231129-1/e775cfa1f803682b41caba7e3487ad87.jpg', '<p>Ở thời Joseon, một họa sĩ tài giỏi nhưng buộc phải che giấu giới tính của mình rơi vào lưới tình với một chàng trai trẻ, khiến thầy của nàng ghen tị.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Gyu-ri","avatar":""},{"name":"Kim Young-ho","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Choo Ja-hyun","avatar":""},{"name":"Bo Ri","avatar":""},{"name":"Lee Eun-mi","avatar":""},{"name":"Shin Yu-ju","avatar":""},{"name":"Joo Young-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
