INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phobia', 'Phobia', 'Phobia', 'https://phimimg.com/upload/vod/20231129-1/b0ee96c44dbab82fb9180c91272c7dbf.jpg', 'https://phimimg.com/upload/vod/20231129-1/4cfa7f1e67067e3267f512941cb7d034.jpg', '<p>4bia là một tuyển tập kinh dị. Phân khúc đầu tiên, &quot;Hạnh phúc&quot; là về một cô gái cô đơn tương ứng với một người lạ trên tay nhắn tin văn bản điện thoại và sớm phát hiện ra một điều gì đó kỳ lạ về người lạ mới này rằng cô bị thu hút. &quot;Tit for Tat&quot; Spun một câu chuyện về ma thuật đen và báo thù cho một đứa trẻ học đã bị bắt nạt bởi một băng đảng trường học. &quot;Ở giữa&quot; - một nhóm bạn đã đối mặt với một trong những chuyến đi cắm trại tồi tệ nhất của họ sau tai nạn chèo thuyền nước. Phân khúc cuối cùng &quot;FRight&quot; cuối cùng mang đến nỗi kinh hoàng với những tầm cao mới với một bộ phim kinh dị tâm lý liên quan đến một tiếp viên bay solo trong một cabin với xác chết.</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chermarn Boonyasak","avatar":""},{"name":"Maneerat Kam-Uan","avatar":""},{"name":"Apinya Sakuljaroensuk","avatar":""},{"name":"Chatpong Nattapong","avatar":""},{"name":"Pongsatorn Jongwilas","avatar":""},{"name":"Attharut Kongrasri","avatar":""},{"name":"Kantapat Permpoonpatcharasuk","avatar":""},{"name":"Witawat Singlampong","avatar":""},{"name":"Nottapon Boonprakob","avatar":""},{"name":"Paween Purijitpanya","avatar":""},{"name":"Paramej Noiam","avatar":""},{"name":"Nada Lesongan","avatar":""},{"name":"Chon Wach","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
