INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-di-nhan', 'Biên Niên Sử Dị Nhân', 'Mutant Chronicles', 'https://phimimg.com/upload/vod/20231125-1/df39b1ee1ed9e485009f687bdf4e7f86.jpg', 'https://phimimg.com/upload/vod/20231125-1/aa2f7c625e6879eb5e5f98aad41491fb.jpg', '<p>Đó là năm 2707. Tài nguyên thiên nhiên của Trái đất gần như đã cạn kiệt bởi loài người. Các trận chiến diễn ra ác liệt trong phần còn lại giữa các Tập đoàn cạnh tranh. Trong một trận chiến như vậy, phong ấn bị phá vỡ và đánh thức một cỗ máy cổ xưa và chết chóc đã từng bị đánh bại hàng ngàn năm trước. Mệnh lệnh chờ đợi sự trở lại của nó bây giờ phải lãnh đạo một nhóm nhỏ binh lính để tiêu diệt nó một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Devon Aoki","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Benno Fürmann","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Anna Walton","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"Steve Toussaint","avatar":""},{"name":"Luis Echegaray","avatar":""},{"name":"Shauna Macdonald","avatar":""},{"name":"Roger Ashton-Griffiths","avatar":""},{"name":"Christopher Adamson","avatar":""},{"name":"Jacqueline Chan","avatar":""},{"name":"Nicholas Ball","avatar":""},{"name":"Georgina Berriman","avatar":""},{"name":"Geor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324481);
