INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tinh-bao', 'Nữ Tình Báo', 'Female Agents', 'https://phimimg.com/upload/vod/20231125-1/83f77c5c83c20654a57b0bd94c069a48.jpg', 'https://phimimg.com/upload/vod/20231125-1/837c54d37560b57ea5f59bedafdbfa50.jpg', '<p>Tháng 5 năm 1944, một nhóm nữ quân nhân Pháp và các chiến binh kháng chiến được gia nhập vào nhóm đặc công Điều hành Hoạt động Đặc biệt của Anh dưới sự chỉ huy của Louise Desfontaines và anh trai cô Pierre. Nhiệm vụ của họ là giải cứu một nhà địa chất của quân đội Anh bị bắt do thám các bãi biển ở Normandy.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sophie Marceau","avatar":""},{"name":"Julie Depardieu","avatar":""},{"name":"Marie Gillain","avatar":""},{"name":"Déborah François","avatar":""},{"name":"Moritz Bleibtreu","avatar":""},{"name":"Julien Boisselier","avatar":""},{"name":"Maya Sansa","avatar":""},{"name":"Vincent Rottiers","avatar":""},{"name":"Volker Bruch","avatar":""},{"name":"David Capelle","avatar":""},{"name":"Natasha Cashman","avatar":""},{"name":"Jan Oliver Schroeder","avatar":""},{"name":"David Van Severen","avatar":""},{"name":"Robin Renucci","avatar":""},{"name":"Xavier Beauvois","avatar":""},{"name":"Col","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324481);
