INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-tinh-bao', 'Nữ Tình Báo', 'Female Agents', 'nữ tình báo female agents sophie marceau julie depardieu marie gillain déborah françois moritz bleibtreu julien boisselier maya sansa vincent rottiers volker bruch david capelle natasha cashman jan oliver schroeder david van severen robin renucci xavier beauvois col ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-san-rong', 'Hiệp Sĩ Săn Rồng', 'Dragon Hunters', 'https://phimimg.com/upload/vod/20231125-1/ddb9df7d930e6157ff7e5f06b2d510dc.jpg', 'https://phimimg.com/upload/vod/20231125-1/beb8af83aaae01159acdb0a13b8b3f40.jpg', '<p>Zoe muốn giúp ông bác lãnh chúa tống khứ một con rồng khủng khiếp ra khỏi lãnh thổ. Cô bé hăm hở tìm kiếm những người hùng giúp mình trong cuộc chiến đấu. Và khi đụng đầu Gwizdo (Patrick Timsit) và Lian-Chu (Vincent Lindon), hai chiến binh săn rồng, cô bé quyết định tin tưởng cùng họ lập thành một nhóm kỳ khôi. Ranh mãnh láu lỉnh, Gwizdo biết đọc biết viết và tính toán trên hai mươi đầu ngón tay và chân, một khả năng siêu phàm không phải ai cũng biết. Còn có năng khiếu đặc biệt về tài phỉnh phờ và bịp bợm, nói không biết mệt, anh chàng nhỏ con sẵn sàng đặt ra những câu chuyện tệ hại nhất cho tới những trò lừa thông minh nhất. Nhưng cô bé Zoe lại có thể biến anh chàng thành một người hoàn toàn khác....</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Vincent Lindon","avatar":""},{"name":"Patrick Timsit","avatar":""},{"name":"Philippe Nahon","avatar":""},{"name":"Amanda Lear","avatar":""},{"name":"Marie Drion","avatar":""},{"name":"Jérémy Prévost","avatar":""},{"name":"Jean-Marc Lentretien","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Elias Eliot","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Nick Jameson","avatar":""},{"name":"Mary Mouser","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Dave Wittenberg","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
