INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-mariposa-va-nhung-nguoi-ban-tien-buom', 'Barbie: Mariposa và Những Người Bạn Tiên Bướm', 'Barbie: Mariposa and Her Butterfly Fairy Friends', 'https://phimimg.com/upload/vod/20231123-1/6b6699f8949b188f2d4f2dd55e642903.jpg', 'https://phimimg.com/upload/vod/20231123-1/8745c819308cbae17f360416ce9f9fbf.jpg', '<p>Khi nữ hoàng tiên cánh bướm ở xứ sở phép thuật Flutterfield bị trúng độc, hoàng tử đã nhờ Mariposa giúp đỡ để cứu lấy thành phố của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chiara Zanni","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Erin Mathews","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Alessandro Juliani","avatar":""},{"name":"Cathy Weseluck","avatar":""},{"name":"Alistair Abell","avatar":""},{"name":"Kelly Sheridan","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Terry Klassen","avatar":""},{"name":"Jane Barr","avatar":""},{"name":"David Kaye","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324481);
