INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-ca-3-cau-chuyen-bat-dau', 'Nàng Tiên Cá 3: Câu Chuyện Bắt Đầu', 'The Little Mermaid: Ariel''s Beginning', 'https://phimimg.com/upload/vod/20231123-1/210dada07267b3459efc41c976cef2b1.jpg', 'https://phimimg.com/upload/vod/20231123-1/e86e04fb9de8d4b57d2865f9fb99aea1.jpg', '<p>Nàng Tiên Cá 3: Câu Chuyện Bắt Đầu là phần tiếp theo của loạt phim Nàng Tiên Cá vốn rất nổi tiếng với các em nhỏ trên toàn thế giới. Lần này, Disney lại 1 lần nữa dẫn dắt người xem trở về quá khứ, về lại quãng thời gian trước khi Ariel gặp được hoàng tử. Tại đây, người xem sẽ được tận mắt thấy vua Tripton cùng hoàng hậu Athena – mẹ của Ariel, cái chết của Athena và những gì xảy ra tiếp theo đằng sau sự kiện đó.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodi Benson","avatar":""},{"name":"Samuel E. Wright","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Jennifer Hale","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Parker Goris","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Lorelei Hill Butters","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324481);
