INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-thien-duong', 'Đêm Thiên Đường', 'Nights In Rodanthe', 'https://phimimg.com/upload/vod/20231123-1/9aad16e11d121690b34277a791eb7556.jpg', 'https://phimimg.com/upload/vod/20231123-1/6421d873d18abfe7dcf017134565686e.jpg', '<p>Adrienne bị chồng phản bội, còn bác sĩ Paul đang muốn tìm sự tha thứ của người nhà một bệnh nhân đã mất. Họ gặp nhau vào một ngày cuối tuần tại thị trấn nhỏ ở vùng biển Rodanthe khi cơn bão tràn qua và đánh thức những cảm xúc tưởng chừng ngủ quên mãi mãi. Đêm thiên đường sẽ đọng lại gì trong phần đời còn lại của họ?</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Diane Lane","avatar":""},{"name":"Richard Gere","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Becky Ann Baker","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Linda Molloy","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Charlie Tahan","avatar":""},{"name":"Carolyn McCormick","avatar":""},{"name":"Ted Manson","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Terri Denise Johnson","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"Marisela Ramirez","avatar":""},{"name":"Kimberl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
