INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nu-ben-ho', 'Yêu Nữ Bên Hồ', 'Siren X', 'https://phimimg.com/upload/vod/20231120-1/2015580ce7735d4576ef1b45da57b122.jpg', 'https://phimimg.com/upload/vod/20231120-1/4afbd225d9e9aeb952fda858a3c82e9d.jpg', '<p>Câu chuyện phim Yêu Nữ Bên Hồ bắt đầu xảy ra trong 1 buổi quay phim &quot;Người lớn&quot; ngoài trời. Trong quá trình quay phim kinh dị, mấy anh chàng thấy 1 việc rất lạ. Họ bắt gặp 1 cô gái rất đẹp và quyến rũ làm mấy anh chết mê mệt. Và cô ấy muốn được thỏa mãn &quot;vấn đề tình dục&quot; của mình. Nhưng cuối cùng tất cả đều có 1 bi kịch thảm thương.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuma Asami","avatar":""},{"name":"Yuria Hidaka","avatar":""},{"name":"Takashi Naha","avatar":""},{"name":"Eiji Nakamura","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324481);
