INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mamma-mia-giai-dieu-hanh-phuc', 'Mamma Mia! Giai Điệu Hạnh Phúc', 'Mamma Mia!', 'https://phimimg.com/upload/vod/20231120-1/88e4e671f5d2c5055f646d949cd4abb9.jpg', 'https://phimimg.com/upload/vod/20231120-1/3ba3bf6749aecd7e672a44a62dfa3821.jpg', '<p>Đặt trên một hòn đảo Hy Lạp đầy màu sắc, cốt truyện đóng vai trò là nền tảng cho sự giàu có của các bài hát ABBA. Một phụ nữ trẻ sắp kết hôn rằng bất kỳ một trong ba người đàn ông có thể là cha cô. Cô ấy mời cả ba vào đám cưới mà không nói với mẹ, Donna Sheridan (Meryl Streep), người đã từng là ca sĩ chính của Donna và máy nổ. Trong khi đó, Donna đã mời các ca sĩ dự phòng của mình, Rosie Mulligan (Dame Julie Walters) và Tanya Wilkinson (Christine Baranski).</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Niall Buggy","avatar":""},{"name":"Chris Jarvis","avatar":""},{"name":"Ashley Lilley","avatar":""},{"name":"Rachel McDowall","avatar":""},{"name":"Philip Michael","avatar":""},{"name":"Juan Pablo Di Pace","avatar":""},{"name":"Enzo Squillino Jr.","avatar":""},{"name":"Ricardo Mo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
