INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-thit-nguoi', 'Chuyến Tàu Thịt Người', 'The Midnight Meat Train', 'https://phimimg.com/upload/vod/20231120-1/e30f836e7d16bebb88b4eedca1d076de.jpg', 'https://phimimg.com/upload/vod/20231120-1/f0d4e6a1cc89988e20a73da9539870b1.jpg', '<p>Nỗi ám ảnh theo đuổi chủ đề đen tối của một nhiếp ảnh gia đã dẫn anh ta vào con đường của một kẻ giết người hàng loạt chuyên rình rập những người đi làm vào đêm khuya, cuối cùng tàn sát họ theo những cách ghê rợn nhất.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley Cooper","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Brooke Shields","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Roger Bart","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Barbara Eve Harris","avatar":""},{"name":"Stephanie Mace","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Quinton Jackson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324481);
