INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('largo-winch', 'Largo Winch', 'Largo Winch', 'https://phimimg.com/upload/vod/20231116-1/11f7cbefc23ec92bcf0e89a97e8803fb.jpg', 'https://phimimg.com/upload/vod/20231116-1/32cb6e473a6848ca7f5698f552e28f9c.jpg', '<p>Sau khi một tỷ phú quyền lực bị sát hại, người con nuôi bí mật của ông phải chạy đua để chứng minh tính hợp pháp của mình, tìm ra những kẻ giết cha mình và ngăn chặn chúng chiếm lấy đế chế tài chính của ông.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Tomer Sisley","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Mélanie Thierry","avatar":""},{"name":"Miki Manojlović","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Gilbert Melki","avatar":""},{"name":"Anne Consigny","avatar":""},{"name":"Steven Waddington","avatar":""},{"name":"Radivoje Bukvić","avatar":""},{"name":"Nicolas Vaude","avatar":""},{"name":"Benjamin Siksou","avatar":""},{"name":"David Gasman","avatar":""},{"name":"Bojana Panic","avatar":""},{"name":"Gérard Watkins","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Wolfgang Pissor","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
