INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ride-away', 'Ride Away', 'Ride Away', 'https://phimimg.com/upload/vod/20231116-1/84127cda6520f14a69eb5e6bc82866ce.jpg', 'https://phimimg.com/upload/vod/20231116-1/5da733ceea0bfebaa3410c19847d1374.jpg', '<p>Hà Jung, một sinh viên đại học năm thứ nhất, quan tâm đến một cậu bé tên Su Wook, người làm việc tại một hiệu sách cũ gần trường của cô. Để thấy Su Wook, Hà Jung đến thăm cửa hàng để mua và bán sách; Theo thời gian, lối sống của cô trở nên tập trung vào Su Wook. Cô ấy biết rằng anh ấy cưỡi trên chiếc xe đạp của anh ấy, và điều này khiến cô ấy học cách cưỡi một người. Họ bắt đầu bày tỏ tình cảm của họ với nhau, nhưng không ai trong số họ nhận thức được những bí mật đau đớn của nhau từ quá khứ.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Hyo-joo","avatar":""},{"name":"Lee Young-hoon","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Song Gwang-won","avatar":""},{"name":"Jeon Il-beom","avatar":""},{"name":"Lee Eun","avatar":""},{"name":"Kwon Geum-san","avatar":""},{"name":"Lee Jung-gook","avatar":""},{"name":"Yang In","avatar":""},{"name":"Yoon Hyun-yong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
