INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sinh-duoi-da', 'Ký Sinh Dưới Da', 'Splinter', 'https://phimimg.com/upload/vod/20231116-1/4502cf390a2fd3ed9e95ecb3d962c860.jpg', 'https://phimimg.com/upload/vod/20231116-1/c33239372860aff288fc4365eade85c1.jpg', '<p>Khi kế hoạch cho một chuyến du ngoạn tự nhiên của họ gặp trục trặc, Polly và bạn trai Seth quyết định thuê một nhà nghỉ. Trên đường đi, họ bị cướp ô tô và bị bắt cóc bởi những kẻ lừa đảo cho thuê thấp Dennis và Lacey, những kẻ đưa nạn nhân và chiếc SUV của họ đến một trạm xăng gần đó. Trên đường đi, họ gặp phải một bầy ký sinh trùng ngày càng đáng sợ, và nếu bất kỳ ai trong số họ muốn sống sót, họ sẽ phải vượt qua những sinh vật chết người này.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jill Wagner","avatar":""},{"name":"Charles Baker","avatar":""},{"name":"Rachel Kerbs","avatar":""},{"name":"Paulo Costanzo","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Laurel Whitsett","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
