INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-sinh-duoi-da', 'Ký Sinh Dưới Da', 'Splinter', 'ký sinh dưới da splinter jill wagner charles baker rachel kerbs paulo costanzo shea whigham laurel whitsett ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-chi-em-2', 'Tình Chị Em 2', 'The Sisterhood of the Traveling Pants 2', 'https://phimimg.com/upload/vod/20231119-1/dcc13a41e3250726d0326fa8a951dfe4.jpg', 'https://phimimg.com/upload/vod/20231119-1/90d5e2a8d284a4faafd63ef2c695ff49.jpg', '<p>Carmen Lowell đang làm việc trên hậu trường của một vở kịch tại Yale. Khi nữ diễn viên chính, bạn của cô Julia, mời cô đến Vermont với cô để chơi một vở diễn với một diễn viên chuyên nghiệp, cô quyết định ở lại với bạn bè và mẹ mang thai của mình. Tuy nhiên, cô ấy đã thay đổi suy nghĩ của mình sau khi cô ấy thấy rằng những người bạn của mình sẽ rời đi vào mùa hè: Lena Kaligaris sẽ đi du lịch đến một khóa học vẽ, Bridget Vreeland, những người trong một cuộc khủng hoảng hiện sinh, nhớ mẹ cô ấy, sẽ đi du lịch đến một nhà khảo cổ học ở Thổ Nhĩ Kỳ và Tibby Tomko-Rollins đang làm việc trong một người cho thuê và vẫn chỉnh sửa phim tài liệu của cô. Carmen phát triển sự phải lòng nam diễn viên chính Ian, người thuyết phục cô tham gia vào buổi thử giọng, và sau đó cô được đạo diễn Bill Kerr mời để thực hiện vai trò nữ chính. Sau đó, cô tìm thấy sự thật về tình bạn của Julia. Lena tan vỡ phát hiện ra rằng Kostas vừa kết hôn, và cô ấy hẹn hò với người mẫu của lớp học vẽ. Bridget tìm thấy những lá thư gửi cho cô ấy từ bà ngoại mà cha cô đã giấu, và quyết định đến thăm cô, khám phá thông tin về mẹ cô. Tibby làm tình với bạn trai Brian McBrian và sợ một thai kỳ có thể xảy ra. Cuối cùng, bạn gái phát hiện ra rằng tình bạn của họ là có thật và số tiền đến nhiều hơn chỉ là một cặp Jeans.Carmen Lowell đang làm việc ở hậu trường của một vở kịch tại Yale. Khi nữ diễn viên chính, bạn của cô Julia, mời cô đến Vermont với cô để chơi một vở diễn với một diễn viên chuyên nghiệp, cô quyết định ở lại với bạn bè và mẹ mang thai của mình. Tuy nhiên, cô ấy đã thay đổi suy nghĩ của mình sau khi cô ấy thấy rằng những người bạn của mình sẽ rời đi vào mùa hè: Lena Kaligaris sẽ đi du lịch đến một khóa học vẽ, Bridget Vreeland, những người trong một cuộc khủng hoảng hiện sinh, nhớ mẹ cô ấy, sẽ đi du lịch đến một nhà khảo cổ học ở Thổ Nhĩ Kỳ và Tibby Tomko-Rollins đang làm việc trong một người cho thuê và vẫn chỉnh sửa phim tài liệu của cô. Carmen phát triển sự phải lòng nam diễn viên chính Ian, người thuyết phục cô tham gia vào buổi thử giọng, và sau đó cô được đạo diễn Bill Kerr mời để thực hiện vai trò nữ chính. Sau đó, cô tìm thấy sự thật về tình bạn của Julia. Lena tan vỡ phát hiện ra rằng Kostas vừa kết hôn, và cô ấy hẹn hò với người mẫu của lớp học vẽ. Bridget tìm thấy những lá thư gửi cho cô ấy từ bà ngoại mà cha cô đã giấu, và quyết định đến thăm cô, khám phá thông tin về mẹ cô. Tibby làm tình với bạn trai Brian McBrian và sợ một thai kỳ có thể xảy ra. Cuối cùng, các bạn gái phát hiện ra rằng tình bạn của họ là có thật và số tiền nhiều hơn là chỉ là một chiếc quần jean.</p>', 'Full', 1, 'single', 'completed', 20, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amber Tamblyn","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Rachel Nichols","avatar":""},{"name":"Tom Wisdom","avatar":""},{"name":"Rachel Ticotin","avatar":""},{"name":"Leonardo Nam","avatar":""},{"name":"Michael Rady","avatar":""},{"name":"Shohreh Aghdashloo","avatar":""},{"name":"Blythe Danner","avatar":""},{"name":"Jesse Williams","avatar":""},{"name":"Lucy Hale","avatar":""},{"name":"Maria Konstadarou","avatar":""},{"name":"Ernie Lively","avatar":""},{"name":"Stevie Ray Dallimore","avatar":""},{"name":"Aliso","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"