INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('space-chimps', 'Space Chimps', 'Space Chimps', 'https://phimimg.com/upload/vod/20231119-1/fa5b37dfb0a807f8df6e509bf54cbcb0.jpg', 'https://phimimg.com/upload/vod/20231119-1/86e08fafe1b7e55d13f5cfb62adc2268.jpg', '<p>Ba con tinh tinh được gửi vào vũ trụ để khám phá khả năng tồn tại sự sống ngoài hành tinh khi một vụ tai nạn tàu con thoi không người lái hạ cánh xuống một hành tinh chưa được khám phá.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy Samberg","avatar":""},{"name":"Cheryl Hines","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Zack Shada","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Omid Abtahi","avatar":""},{"name":"Patrick Breen","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Wally Wingert","avatar":""},{"name":"Jessica Gee-George","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Jason Harris","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324481);
