INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wendy-va-lucy', 'Wendy và Lucy', 'Wendy and Lucy', 'https://phimimg.com/upload/vod/20231119-1/0b62cd82d9719bd1458fb447d4a5cc73.jpg', 'https://phimimg.com/upload/vod/20231119-1/dff9803fa8385f633198e0a0e26e3fba.jpg', '<p>Wendy, một người trôi dạt gần như không một xu dính túi, đang đến Alaska để tìm việc làm, và người bạn đồng hành duy nhất của cô là chú chó Lucy. Gần như suýt mất tất cả, Wendy gặp một va chạm lớn hơn trên đường khi chiếc ô tô cũ của cô bị hỏng và cô bị bắt vì tội ăn trộm thức ăn cho chó. Khi cô ấy đăng ký bảo lãnh và quay lại để lấy Lucy, cô ấy phát hiện ra rằng con chó đã biến mất, khiến cô ấy phải điên cuồng tìm kiếm con vật cưng của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Williams","avatar":""},{"name":"Wally Dalton","avatar":""},{"name":"Will Oldham","avatar":""},{"name":"John Robinson","avatar":""},{"name":"David Koppell","avatar":""},{"name":"Max Clement","avatar":""},{"name":"Sid Shanley","avatar":""},{"name":"Dave Hubner","avatar":""},{"name":"Michelle Worthey","avatar":""},{"name":"Roger D. Faires","avatar":""},{"name":"Boggs Johnson","avatar":""},{"name":"Tanya Smith","avatar":""},{"name":"Michael Brophy","avatar":""},{"name":"John Breen","avatar":""},{"name":"Deneb Catalan","avatar":""},{"name":"Skeeter Greene","avatar":""},{"name":"Marilyn Faith Hick","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
