INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-o-barcelona', 'Chuyện Tình ở Barcelona', 'Vicky Cristina Barcelona', 'https://phimimg.com/upload/vod/20231118-1/66b2b56cef1e2590b6a3968be1b76c74.jpg', 'https://phimimg.com/upload/vod/20231118-1/dcb41a94057f9ac2c00a872a2295dfb9.jpg', '<p>Phim Chuyện Tình Ở Barcelona xoay quanh hai cô gái trẻ người Mỹ vốn là bạn thân của nhau là Vicky và Cristina cùng thực hiện chuyến đi nghỉ hè tại Barcelona. Tại thành phố xinh đẹp này, cả hai tình cờ gặp gỡ, và cùng bị quyến rũ bởi anh chàng họa sĩ tài hoa José Antonio. Xem phim này bạn sẽ thấy trong lúc tình cảm của bọn họ đang tiến triển tốt đẹp thì cô vợ cũ xinh đẹp nhưng nóng nảy của José xuất hiện khiến cho chuyện tình cảm giữa các nhân vật lại càng trở nên nhập nhằng hơn... Phim Chuyện Tình Ở Barcelona là câu chuyện đầy tinh tế về những ẩn ức, tâm lý và khát vọng bùng cháy trong tình yêu của những người phụ nữ, qua đó để lại những dư vị vừa nồng nàn, ngọt ngào lại có chút gì đó đắng cay, thấm thía. Kính mời các ...</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Christopher Evan Welch","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Julio Perillán","avatar":""},{"name":"Juan Queseda","avatar":""},{"name":"Ricard Salom","avatar":""},{"name":"Maurice Sonnenberg","avatar":""},{"name":"Manel Barceló","avatar":""},{"name":"Josep Maria Domènech","avatar":""},{"name":"Emilio de Benito","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
