INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-yeu-thuong', 'Tìm Lại Yêu Thương', 'The Secret Life of Bees', 'https://phimimg.com/upload/vod/20231117-1/b6f63fcfa04de27c45fee6815ab51421.jpg', 'https://phimimg.com/upload/vod/20231117-1/6a7afe9788ba44b8ee2bc736b74969ee.jpg', '<p>Lấy bối cảnh ở Nam Carolina năm 1964, đây là câu chuyện về Lily Owens, một cô bé 14 tuổi bị ám ảnh bởi ký ức về người mẹ quá cố của mình. Để thoát khỏi cuộc sống cô đơn và mối quan hệ rắc rối với cha mình, Lily chạy trốn cùng Rosaleen, người chăm sóc và người bạn duy nhất của cô, đến một thị trấn ở Nam Carolina, nơi nắm giữ bí mật về quá khứ của mẹ cô.</p>', 'Full', 1, 'single', 'completed', 20, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dakota Fanning","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"Alicia Keys","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Hilarie Burton","avatar":""},{"name":"Tristan Mack Wilds","avatar":""},{"name":"Nate Parker","avatar":""},{"name":"Shondrella Avery","avatar":""},{"name":"Renee Clark","avatar":""},{"name":"Sharon Conley","avatar":""},{"name":"Nicky Buggs","avatar":""},{"name":"Jasmine Burke","avatar":""},{"name":"Emma Sage Bowman","avatar":""},{"name":"Addy Miller","avatar":""},{"name":"Emily Alyn","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
