INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-binh-mai', 'Kim Bình Mai', 'The Forbidden Legend: Sex & Chopsticks', 'https://phimimg.com/upload/vod/20231117-1/8fe352c18b1d7b3a3d703b2c8e20ede5.jpg', 'https://phimimg.com/upload/vod/20231117-1/a8b49d18f3fa3df201ade6915973dc9c.jpg', '<p>Phim nói về Tây Môn Khánh được cha là Tây Môn Quỳ truyền cho những bài học và bí quyết chinh phục phụ nữ. Phần 1 xoay quanh mối quan hệ của Tây Môn Khánh cùng 2 người vợ đầu tiên là Nguyệt Nhi (ni cô hoàn tục) và Kim Liên (vợ Võ Đại Lang)</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Oscar Lam Wai-Kin","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Hikaru Wakana","avatar":""},{"name":"Kaera Uehara","avatar":""},{"name":"Serina Hayakawa","avatar":""},{"name":"Minami Matsuzaka","avatar":""},{"name":"Winnie Leung","avatar":""},{"name":"Samuel Leung Cheuk-Moon","avatar":""},{"name":"Tam Kon-Chung","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
