INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-tinh-yeu', 'Ranh Giới Tình Yêu', 'The Edge of Love', 'https://phimimg.com/upload/vod/20231117-1/822db60cba2b5f95533d97b6fd27ee84.jpg', 'https://phimimg.com/upload/vod/20231117-1/ba89ce4a4b53a64a5c80281585020d26.jpg', '<p>Khi nhà thơ xứ Wales Dylan Thomas và người vợ tán tỉnh Caitlin của anh ta đến London đang bị chiến tranh tàn phá, điều cuối cùng họ mong đợi là tình cờ gặp Vera, người yêu thời thơ ấu của Dylan. Bất chấp niềm vui được gặp lại Dylan sau nhiều năm, Vera bị một sĩ quan bảnh bao, William Killick, cuốn đi và thấy mình bị giằng xé giữa sự tôn thờ công khai của người bạn trai mới tìm thấy và sự quyến rũ quỷ quyệt của người xứ Wales kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Matthew Rhys","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Lisa Stansfield","avatar":""},{"name":"Richard Dillane","avatar":""},{"name":"Anne Lambton","avatar":""},{"name":"Alastair Mackenzie","avatar":""},{"name":"Camilla Rutherford","avatar":""},{"name":"Richard Clifford","avatar":""},{"name":"Paul Brooke","avatar":""},{"name":"Simon Kassianides","avatar":""},{"name":"Jonny Phillips","avatar":""},{"name":"Paul Brooke","avatar":""},{"name":"Ben Batt","avatar":""},{"name":"Anthony O''D","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
