INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bo-cap-2-chien-binh-troi-day', 'Vua Bọ Cạp 2: Chiến Binh Trỗi Dậy', 'The Scorpion King 2: Rise of a Warrior', 'https://phimimg.com/upload/vod/20231115-1/c979f66a0770d0127c7db75e6ac0450c.jpg', 'https://phimimg.com/upload/vod/20231115-1/e904d275b7a0599a7522d957611a2dcb.jpg', '<p>Sau khi chứng kiến tận mắt cái chết của cha dưới tay của tên khát máu Sargon, chàng trai trẻ Mathayus quyết tâm luyện tập tại thung lũng Bò Cạp hòng trả thù cho cha mình. Sau đó, anh phải dấn thân vào một thế giới khác đầy nguy hiểm để có được thanh gươm có thể giết được Sargon. Liệu Mathayus có thể trả thù được cho cha?</p>', 'Full', 1, 'single', 'completed', 20, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Copon","avatar":""},{"name":"Randy Couture","avatar":""},{"name":"Karen David","avatar":""},{"name":"Simon Quarterman","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"Andreas Wisniewski","avatar":""},{"name":"Natalie Becker","avatar":""},{"name":"Jeremy Crutchley","avatar":""},{"name":"Shane Manie","avatar":""},{"name":"Chase Agulhas","avatar":""},{"name":"Pierre Marais","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Az Abrahams","avatar":""},{"name":"Vaneshran Arumugam","avatar":""},{"name":"Mike Thompson","avatar":""},{"name":"Wayne Shields","avatar":""},{"name":"Diane Wilso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 178469