INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-than-chet-tan-phai-vao-bong-dem-goi-ten-em', 'Sứ Mệnh Thần Chết: Tàn Phai Vào Bóng Đêm, Gọi Tên Em', 'Bleach the Movie: Fade to Black', 'https://phimimg.com/upload/vod/20231115-1/884f165f382996c3c099ec9ad087c1a2.jpg', 'https://phimimg.com/upload/vod/20231115-1/d91d73baca71d9a8de8f09e65a9129e5.jpg', '<p>Hai con người đến từ một nơi xa xăm có khả năng xóa đi kí ức. Một loại Hollow hiếm xuất hiện. Một sản phẩm của Kurotsuchi bị lạm dụng. Ký ức của tất cả Thần Chết bị đảo lộn. Soul Society rơi vào tình trạng hỗn độn. Ẩn sau đó là một bi kịch của quá khứ. Duy chỉ hai con người không bị ảnh hưởng. Họ phải làm thế nào để giải quyết mọi thứ?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masakazu Morita","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Mitsuaki Madono","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Taro Yamaguchi","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Rintaro Nishi","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Hisayo Mochizuki","avatar":""},{"name":"Nobuyuki Hiyama","avatar":""},{"name":"Kaya Mat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
