INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-menh-than-chet-tan-phai-vao-bong-dem-goi-ten-em', 'Sứ Mệnh Thần Chết: Tàn Phai Vào Bóng Đêm, Gọi Tên Em', 'Bleach the Movie: Fade to Black', 'sứ mệnh thần chết: tàn phai vào bóng đêm, gọi tên em bleach the movie: fade to black masakazu morita fumiko orikasa kentaro ito aya hirano hiroshi kamiya mitsuaki madono jun fukuyama taro yamaguchi takako honda katsuyuki konishi rintaro nishi tetsu inada fumiko orikasa rie kugimiya hisayo mochizuki nobuyuki hiyama kaya mat ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chi-noi-vang', 'Người Chỉ Nói Vâng', 'Yes Man', 'https://phimimg.com/upload/vod/20231114-1/b35432ac92550818eb793713e9a57805.jpg', 'https://phimimg.com/upload/vod/20231114-1/f3708e75b5605599224a24784d31a13b.jpg', '<p>Carl Allen đang sống theo một lối mòn. Anh không bao giờ từ chối các hồ sơ cho vay tại ngân hàng nơi anh đang làm việc. Tuy nhiên, anh lại sẵn sàng từ chối mọi lời mời từ bạn bè để ở nhà nằm dài trên chiếc ghế trường kỷ xem TV. Anh trở thành người đàn ông luôn luôn nói Không. Cuộc đời Carl có một bước ngoặt bất ngờ khi anh miễn cưỡng tham dự một cuộc hội thảo, do một vị quân sư &quot;đồng ý tuốt&quot; dẫn dắt. Ông khuyến khích mọi người nên nói &quot;đồng ý&quot; nhiều hơn để thay đổi cuộc sống. Ban đầu, Carl thử đồng ý với mọi thứ bằng một tâm trạng hoài nghi. Nhưng dần dần, anh ta hiểu cần đầu tư cho cuộc đời mình nhiều hơn. Thái độ của Carl bắt đầu thay đổi sau khi rời khỏi cuộc hội thảo. Tuy nhiên, anh chỉ bắt đầu coi trọng các cơ hội mà cuộc sống mang đến khi gặp Allison. Cô là một người phụ nữ quyến rũ, tình cờ gặp Carl khi anh đang đổ xăng. Cô đề nghị cho anh đi nhờ một đoạn và tất nhiên anh nói &quot;đồng ý&quot;.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Danny Masterson","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Sasha Alexander","avatar":""},{"name":"Molly Sims","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Rocky Carroll","avatar":""},{"name":"John Cothran","avatar":""},{"name":"Spencer Garrett","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Kai Lennox","avatar":""},{"name":"Cecelia An","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
