INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-khach-tu-than', 'Hành Khách Tử Thần', 'Passengers', 'https://phimimg.com/upload/vod/20231113-1/96e89f8282bb0df9e2429ed0021ffe9c.jpg', 'https://phimimg.com/upload/vod/20231113-1/6bd77c374f4565c39ea79d5fb8cab6a3.jpg', '<p>Sau một vụ tai nạn máy bay, nhà trị liệu trẻ tuổi Claire được người cố vấn của cô giao nhiệm vụ tư vấn cho năm người sống sót trên chuyến bay. Khi họ chia sẻ những hồi ức về vụ việc - mà một số người nói bao gồm một vụ nổ mà hãng hàng không tuyên bố chưa bao giờ xảy ra - Claire bị Eric, người bí mật nhất trong số các hành khách, hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"David Morse","avatar":""},{"name":"William B. Davis","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Don Thompson","avatar":""},{"name":"Andrew Wheeler","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Elzanne Fourie","avatar":""},{"name":"Stacy Grant","avatar":""},{"name":"Conner Dwelly","avatar":""},{"name":"Claire Smithies","avatar":""},{"name":"Karen Elizabeth Austin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
