INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('i-cant-think-straight', 'I Can''t Think Straight', 'I Can''t Think Straight', 'https://phimimg.com/upload/vod/20231112-1/0ea3e9da453a7758eed4fc51eadbfdb4.jpg', 'https://phimimg.com/upload/vod/20231112-1/67e4b219ec8e9cefad8e17cebc0ee058.jpg', '<p>Một bộ phim lãng mạn năm 2008 được chuyển thể từ cùng một cuốn tiểu thuyết về một Jordanian có trụ sở tại London, Tala, người đang chuẩn bị cho một đám cưới phức tạp. Một bước ngoặt của các sự kiện khiến cô ngoại tình và sau đó yêu một người phụ nữ khác, Leyla, một người Ấn Độ Anh.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lisa Ray","avatar":""},{"name":"Sheetal Sheth","avatar":""},{"name":"Antonia Frering","avatar":""},{"name":"Dalip Tahil","avatar":""},{"name":"Nina Wadia","avatar":""},{"name":"Siddiqua Akhtar","avatar":""},{"name":"Amber Rose Revah","avatar":""},{"name":"Ernest Ignatius","avatar":""},{"name":"Anya Lahiri","avatar":""},{"name":"Kimberly Jaraj","avatar":""},{"name":"Sam Vincenti","avatar":""},{"name":"Rez Kempton","avatar":""},{"name":"Darwin Shaw","avatar":""},{"name":"George Tardios","avatar":""},{"name":"Ishwar Maharaj","avatar":""},{"name":"Gabrielle Amies","avatar":""},{"name":"Jessica Allsop","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
