INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-cung-hot-boy', 'Hẹn Hò Cùng Hot Boy', 'Picture This', 'https://phimimg.com/upload/vod/20231113-1/46a10b07559f2d5f30c3bb1607e3c709.jpg', 'https://phimimg.com/upload/vod/20231113-1/dc0794e854ed1c3c9507108d4d87a2fa.jpg', '<p>Ashley Tisdale trong vai cô bé vai chính Mandy-một cô gái bình thường trong trường trung học Nottingham. Nhưng không hiểu sao Mandy lại có một cuộc hẹn với chàng trai hot nhất trường Drew Patterson. Và nhiều rắc rối đã nảy sinh từ đó. Để đến được cuộc hẹn Mandy phải nhờ sự giúp đỡ từ những người bạn thân. Họ cùng nhau tìm cách vượt qua sự cấm cản của bố Mandy và cô người tình cũ. Cuối cùng, Mandy đã nhận ra sự nổi tiếng đến và đi như một cơn gió nhưng những người bạn thân vẫn sẽ mãi ở bên ta.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Tisdale","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Shenae Grimes-Beech","avatar":""},{"name":"Lauren Collins","avatar":""},{"name":"Cindy Busby","avatar":""},{"name":"Marie-Marguerite Sabongui","avatar":""},{"name":"Angela Galuppo","avatar":""},{"name":"Maxim Roy","avatar":""},{"name":"Vanessa Matsui","avatar":""},{"name":"Natalie Vansier","avatar":""},{"name":"Dani Kind","avatar":""},{"name":"Annie Murphy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324481);
