INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cong-tuoc', 'Nữ Công Tước', 'The Duchess', 'https://phimimg.com/upload/vod/20231113-1/a26558daaaf07c1973f452d4b602aa50.jpg', 'https://phimimg.com/upload/vod/20231113-1/61c458fa64eba6d0509e15218c7b8b4f.jpg', '<p>Một biên niên sử về cuộc đời của quý tộc thế kỷ 18 Georgiana, Nữ công tước xứ Devonshire, người bị nguyền rủa vì cuộc sống cá nhân và chính trị xa hoa của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Aidan McArdle","avatar":""},{"name":"John Shrapnel","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Patrick Godfrey","avatar":""},{"name":"Michael Medwin","avatar":""},{"name":"Justin Edwards","avatar":""},{"name":"Richard McCabe","avatar":""},{"name":"Calvin A. Dean","avatar":""},{"name":"Hannah Stokely","avatar":""},{"name":"Andrew Armou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
