INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-quen-tinh-cu', 'Lãng quên tình cũ', 'Forgetting Sarah Marshall', 'https://phimimg.com/upload/vod/20231113-1/f60e5154d969ab40b800abd3ae6578f9.jpg', 'https://phimimg.com/upload/vod/20231113-1/041cf04cc53c7a158d28e3f3e634abda.jpg', '<p>Sau khi chia tay Sarah, cô bạn gái là ngôi sao truyền hình, Peter muốn quên cô nhưng không thể vì cô cũng đang đi nghỉ tại cùng một khu nghỉ mát ở Hawaii.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Segel","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Liz Cackowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Maria Christina Thayer","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"William Baldwin","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Da''Vone McDonald","avatar":""},{"name":"Steve Landesberg","avatar":""},{"name":"Kalani Robb","avatar":""},{"name":"Murray Mille","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
