INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-quen-tinh-cu', 'Lãng quên tình cũ', 'Forgetting Sarah Marshall', 'lãng quên tình cũ forgetting sarah marshall jason segel kristen bell mila kunis russell brand bill hader jonah hill liz cackowski jack mcbrayer maria christina thayer paul rudd jason bateman william baldwin kristen wiig da''vone mcdonald steve landesberg kalani robb murray mille ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xe-chet-choc', 'Chuyến Xe Chết Chóc', 'Truck', 'https://phimimg.com/upload/vod/20231121-1/37c5835943b4e91ed439aa6263b78eb8.jpg', 'https://phimimg.com/upload/vod/20231121-1/db996e6558c3cce69fc9996c292ba272.jpg', '<p>Nội dung của phim xoay quanh anh chàng tài xế xe tải hạng nặng bình thường tên là Chul min (Hae-jin Yoo), công việc hàng ngày của anh là lái xe vận chuyển các chuyến hàng chất lỏng, rượu bia, rau củ quả và các nhu yếu phẩm xuôi ngược quanh khu vực lân cận. Đây là công việc không mang lại nguồn thu nhập lớn tại Hàn, chỉ gọi là ở mức đủ sống, vì thế khi cô con gái của anh được chẩn đoán bị dị tật tim, anh đã phải lăn lộn vay tiền từ bạn bè để chi trả cho ca phẫu thuật. Để rồi, thời gian sau anh không thể cáng đáng nổi số lãi mẹ đẻ lãi con và anh thử vận may của mình ở trò đỏ đen cờ bạc.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Yoo Hae-jin","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Jang Jun-nyeong","avatar":""},{"name":"Lee Chae-young","avatar":""},{"name":"Ji Soo-won","avatar":""},{"name":"Kim Jung-hak","avatar":""},{"name":"Park Jeong-hak","avatar":""},{"name":"Lee Won-jae","avatar":""},{"name":"Choi Jong-ryul","avatar":""},{"name":"Jeong Gi-seop","avatar":""},{"name":"Kim Bo-ra","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324481);
