INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-che-2', 'Anh Hùng Che 2', 'Che: Part Two', 'https://phimimg.com/upload/vod/20231111-1/04ff5099d439610efe36e342cd950116.jpg', 'https://phimimg.com/upload/vod/20231111-1/33c020c5aa62cf8bfebc3c0a54bda682.jpg', '<p>Sau Cách mạng Cuba, Che đang ở đỉnh cao danh vọng và quyền lực. Sau đó, anh ta biến mất, tái xuất hiện ẩn danh ở Bolivia, nơi anh ta tổ chức một nhóm nhỏ gồm các đồng chí Cuba và những tân binh người Bolivia để bắt đầu cuộc Cách mạng Mỹ Latinh vĩ đại. Qua câu chuyện này, chúng ta hiểu rằng Che vẫn là một biểu tượng của chủ nghĩa lý tưởng và chủ nghĩa anh hùng sống mãi trong trái tim của mọi người trên khắp thế giới.</p>', 'Full', 1, 'single', 'completed', 17, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benicio del Toro","avatar":""},{"name":"Carlos Bardem","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Pablo Durán","avatar":""},{"name":"Eduard Fernández","avatar":""},{"name":"Marc-André Grondin","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Kahlil Méndez","avatar":""},{"name":"Cristian Mercado","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Gastón Pauls","avatar":""},{"name":"Antonio Peredo","avatar":""},{"name":"Jorge Perugorría","avatar":""},{"name":"Lou Diamond Phillips","avatar":""},{"name":"Frank","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324481);
