INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-duoi', 'Kẻ Săn Đuổi', 'The Chaser', 'https://phimimg.com/upload/vod/20231111-1/1a515e13e87292c3535579e861571d58.jpg', 'https://phimimg.com/upload/vod/20231111-1/ed86adfc8e512d8f9f0c82fbd53db888.jpg', '<p>Jung-ho, từng là cảnh sát nhưng nay đã trở thành một tay ma cô dẫn gái, nổi điên vì hàng loạt gái gọi dưới tay gã biến mất. Gã tin rằng các cô gái đã lừa tiền hắn mà bỏ đi. Nhưng sự thật là một tên sát nhân hàng loạt nhắm vào các cô gái gọi, trong đó có Min-ji, người Jung-ho quan tâm nhất...</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Yoon-seok","avatar":""},{"name":"Ha Jung-woo","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Jo Deok-jae","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"Lee Jae-hui","avatar":""},{"name":"Koo Bon-woong","avatar":""},{"name":"Yoo Ji-yeon","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Song Yo-sep","avatar":""},{"name":"Jong-goo Lee","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Jeong Jae-hoon","avatar":""},{"name":"Park","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324481);
