INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ong-kinh', 'Ma Ống Kính', 'Shutter', 'https://phimimg.com/upload/vod/20231111-1/966479841562710e7c2e17409b8861a5.jpg', 'https://phimimg.com/upload/vod/20231111-1/3caebdfcaa21dce079dc7e02b8a2cdc2.jpg', '<p>Sau vụ tai nạn xe hơi thảm khốc, một cặp vợ chồng trẻ mới cưới trở nên ám ảnh với những hình ảnh ma quái, kỳ lạ xuất hiện trong những bức ảnh họ chụp.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joshua Jackson","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Megumi Okina","avatar":""},{"name":"David Denman","avatar":""},{"name":"Eri Otoguro","avatar":""},{"name":"John Hensley","avatar":""},{"name":"Maya Hazen","avatar":""},{"name":"James Kyson","avatar":""},{"name":"Yoshiko Miyazaki","avatar":""},{"name":"Kei Yamamoto","avatar":""},{"name":"Daisy Betts","avatar":""},{"name":"Adrienne Pickering","avatar":""},{"name":"Pascal Morineau","avatar":""},{"name":"Masaki Ota","avatar":""},{"name":"Heideru Tatsuo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324481);
