INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-tay-ba', 'Tình Tay Ba', 'Two Lovers', 'https://phimimg.com/upload/vod/20231111-1/9b84a70ec44cca793bfc7b364e45fed7.jpg', 'https://phimimg.com/upload/vod/20231111-1/b18df5680617c5416feec3eb1850ed83.jpg', '<p>Là một câu chuyện tình lãng mạn diễn ra tại Thành phố New York, kể về Leonard, một người đàn ông quyến rũ nhưng đượm buồn vừa mới chuyển về sống với bố mẹ sau một mối tình tan vỡ. Bố mẹ Leonard cố gắng mai mối anh với Sandra, một cô gái ngọt ngào và xinh xắn và là con gái của một gia đình thân thiết. Bữa ăn gia đình trịnh trọng đã được chuẩn bị để hai người gặp gỡ nhau và Leonard đã đồng ý bắt đầu mối quan hệ nghiêm túc theo sự sắp xếp của bố mẹ. Nhưng một đêm nọ, Leonard nhìn ra ngoài cửa sổ phòng ngủ và nhìn thấy một người phụ nữ đẹp mê hồn mà Leonard chưa từng thấy trước đây - Michelle vừa mới chuyển tới và đang sống trong căn hộ do một người đàn ông mà cô đang cặp kè trả tiền cho. Cuộc tình tay ba bắt đầu...</p>', 'Full', 1, 'single', 'completed', 26, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Moni Moshonov","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Bob Ari","avatar":""},{"name":"David Ross","avatar":""},{"name":"Anne Joyce","avatar":""},{"name":"Elliot Villar","avatar":""},{"name":"Craig Walker","avatar":""},{"name":"Carmen M. Herlihy","avatar":""},{"name":"Don Hewitt Jr.","avatar":""},{"name":"Christian Albrizo","avatar":""},{"name":"Julie Budd","avatar":""},{"name":"Iain J. Bopp","avatar":""},{"name":"Samantha Ivers","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
