INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gran-torino', 'Gran Torino', 'Gran Torino', 'https://phimimg.com/upload/vod/20231110-1/1ad054dd956283a17ad102dbc5f3ede4.jpg', 'https://phimimg.com/upload/vod/20231110-1/ac1d00677724b78c557d6ec343defe9e.jpg', '<p>Tiêu đề bộ phim Gran Torino được lấy từ tên chiếc xe Ford 1972 cũ kỹ của ông già Walt Kowalski, một lính Mỹ từng tham gia cuộc chiến tại Triều Tiên. Phim kể về việc Walt Kowalski cố gắng cải tạo người hàng xóm của mình, cậu bé Thao Lor một thiếu niên H&quot;mong đang cố gắng đánh cắp chiếc xe cổ của ông.</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Christopher Carley","avatar":""},{"name":"Bee Vang","avatar":""},{"name":"Ahney Her","avatar":""},{"name":"Brian Haley","avatar":""},{"name":"Geraldine Hughes","avatar":""},{"name":"Dreama Walker","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"William Hill","avatar":""},{"name":"Brooke Chia Thao","avatar":""},{"name":"Chee Thao","avatar":""},{"name":"Choua Kue","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Xia Soua Chang","avatar":""},{"name":"Doua Moua","avatar":""},{"name":"Sarah Neubauer","avatar":""},{"name":"Lee Mon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
