INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hipsters', 'Hipsters', 'Hipsters', 'https://phimimg.com/upload/vod/20231119-1/438a47f2d9406012030fdbc5bb771891.jpg', 'https://phimimg.com/upload/vod/20231119-1/7f149791507bd964bacc94b8a1a07727.jpg', '<p>Trong khi Chiến tranh Lạnh nóng lên trên sân khấu thế giới, tuổi trẻ nổi tiếng năm 1955 Moscow, một cuộc chiến văn hóa chống lại sự phù hợp ảm đạm của Liên Xô, tặng quần áo chợ đen rực rỡ, áp dụng các biệt danh của Mỹ và mặc khải trong nhạc jazz bị cấm. Các tàu điện tử cộng sản 20 tuổi tẩm thẳng tìm thấy những &#39;hipsters&#39; hipster này gây sốc cho đến khi anh ta rơi vào câu thần chú của một người, cụ thể là Polly và tham gia cuộc cách mạng mới. Chẳng mấy chốc, anh ta là một con công, cavorting trong thời trang hào nhoáng mới nhất, thể thao một pompadour to lớn và khóc lóc trên saxophone.</p>', 'Full', 1, 'single', 'completed', 21, 2008, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Anton Shagin","avatar":""},{"name":"Oksana Akinshina","avatar":""},{"name":"Maksim Matveev","avatar":""},{"name":"Igor Voynarovskiy","avatar":""},{"name":"Ekaterina Vilkova","avatar":""},{"name":"Konstantin Balakirev","avatar":""},{"name":"Oleg Yankovskiy","avatar":""},{"name":"Alexandr Stefantsov","avatar":""},{"name":"Georgiy Sivokhin","avatar":""},{"name":"Olga Filimonova","avatar":""},{"name":"Yanina Buiko","avatar":""},{"name":"Irina Rozanova","avatar":""},{"name":"Sergey Garmash","avatar":""},{"name":"Oleksiy Horbunov","avatar":""},{"name":"Darya Hram","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
