INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hipsters', 'Hipsters', 'Hipsters', 'hipsters hipsters anton shagin oksana akinshina maksim matveev igor voynarovskiy ekaterina vilkova konstantin balakirev oleg yankovskiy alexandr stefantsov georgiy sivokhin olga filimonova yanina buiko irina rozanova sergey garmash oleksiy horbunov darya hram ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-valkyrie', 'Điệp Vụ Valkyrie', 'Valkyrie', 'https://phimimg.com/upload/vod/20231109-1/4188ff140f7ec17ba35470291a760d55.jpg', 'https://phimimg.com/upload/vod/20231109-1/4d208053e54efe0316513761f0184efa.jpg', '<p>Trong Chiến tranh thế giới thứ 2, Adolf Hitler(1889-1945), kẻ đứng đầu Chủ nghĩa Phát xít, đã rất nhiều lần bị ám sát nhưng tất cả đều không thành, và vụ ám sát do đại tá Claus Schenk Graf von Stauffenberg thực hiện ngày 24 tháng 7 năm 1944 là vụ ám sát nổi tiếng nhất lúc bấy giờ. Hitler đã thoát chết do... quá may mắn. Kết quả là đại tá Stauffenberg bị xử bắn cùng hàng ngàn người có liên quan nhưng ông đã kịp lưu tên trong sử sách như là 1 người anh hùng, 1 biểu tượng lớn cho phong trào phản chiến, chống Hitler.</p>', 'Full', 1, 'single', 'completed', 29, 2008, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Carice van Houten","avatar":""},{"name":"Kenneth Cranham","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"David Bamber","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Christian Berkel","avatar":""},{"name":"Jamie Parker","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Danny We","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324481);
