INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-va-khuyen-luoi', 'Rắn Và Khuyên Lưỡi', 'Snakes and Earrings', 'https://phimimg.com/upload/vod/20231109-1/004b5718875a61addf4eda02fc9eab7a.jpg', 'https://phimimg.com/upload/vod/20231109-1/d445f9b15a8be74966d0945abc9ddefe.jpg', '<p>Khi ở một mình trong hộp đêm, Lui thẳng thắn gặp Ama, đứa trẻ punk nhạy cảm nhưng rắc rối. Bị mê hoặc bởi chiếc lưỡi chẻ của anh ta, cô bị ám ảnh bởi việc chỉnh sửa cơ thể và sớm muốn được điều trị tương tự. Sau khi Shiba, người bạn có hình xăm dày đặc của Ama, đâm vào lưỡi cô ấy, Lui thấy mình bị cả hai người đàn ông cuốn hút một cách khó cưỡng – và trong danh sách những ham muốn ngày càng tăng của mình, giờ đây cô ấy đã thêm một hình xăm.</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Kengo Kora","avatar":""},{"name":"Arata Iura","avatar":""},{"name":"Yû Abiru","avatar":""},{"name":"Sonim","avatar":""},{"name":"Yuko Imai","avatar":""},{"name":"Shūto Ayabe","avatar":""},{"name":"Hidekazu Ichinose","avatar":""},{"name":"Masafumi Senô","avatar":""},{"name":"Ennosuke Ichikawa","avatar":""},{"name":"Rakkyo Ide","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Toshiaki Karasawa","avatar":""},{"name":"Tatsuya Fujiwara","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324481);
