INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-thu-thu-loi-nguyen-chiec-coc-thanh', 'Hội Thủ Thư: Lời Nguyền Chiếc Cốc Thánh', 'The Librarian: The Curse of the Judas Chalice', 'https://phimimg.com/upload/vod/20231109-1/9a5953b3989926c4bdde4d345aa6027b.jpg', 'https://phimimg.com/upload/vod/20231109-1/6833eb53eca59b7979640cab6d0eeacb.jpg', '<p>Khi đang thực hiện một nhiệm vụ nguy hiểm chết người khôi phục chiếc ly Judas Chalice lịch sử, Flynn được Simone cứu và yêu nàng, một phụ nữ Pháp đang nắm giữ một bí mật kinh khủng. Nhưng khi bị một giáo sư đáng kính lừa gạt và một băng đảng tàn bạo phục kích, Flynn nhận ra rằng bí mật của Simone, nhiệm vụ thật sự của mình và khám phá kinh ngạc đều nằm trong một hầm mộ đang tan rữa ở New Orleans có thể đang kìm giữ Hoàng tử Vlad Dracul mà cả thế giới khiếp sợ bao thế kỷ nay.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Wyle","avatar":""},{"name":"Stana Katic","avatar":""},{"name":"Jane Curtin","avatar":""},{"name":"Bob Newhart","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Dikran Tulaine","avatar":""},{"name":"Jason Douglas","avatar":""},{"name":"Beth Burvant","avatar":""},{"name":"Aimée Spring Fortier","avatar":""},{"name":"Earl Maddox","avatar":""},{"name":"Joe Knezevich","avatar":""},{"name":"David Born","avatar":""},{"name":"Joe Ross","avatar":""},{"name":"John Curran","avatar":""},{"name":"Connor Hill","avatar":""},{"name":"Todd Voltz","avatar":""},{"name":"Werner Richmond","avatar":""},{"name":"Armando Leduc","avatar":""},{"name":"Sea","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324481);
