INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-thu-thu-loi-nguyen-chiec-coc-thanh', 'Hội Thủ Thư: Lời Nguyền Chiếc Cốc Thánh', 'The Librarian: The Curse of the Judas Chalice', 'hội thủ thư: lời nguyền chiếc cốc thánh the librarian: the curse of the judas chalice noah wyle stana katic jane curtin bob newhart bruce davison dikran tulaine jason douglas beth burvant aimée spring fortier earl maddox joe knezevich david born joe ross john curran connor hill todd voltz werner richmond armando leduc sea ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-phu-khu-o-chuot', 'Triệu Phú Khu Ổ Chuột', 'Slumdog Millionaire', 'https://phimimg.com/upload/vod/20231109-1/b513e7fd34e66f11da8a492228c5c07c.jpg', 'https://phimimg.com/upload/vod/20231109-1/604e5c3026fa1d148e1f616cc40af509.jpg', '<p>Phim lấy bối cảnh cuộc thi “Ai Là Triệu Phú” phiên bản Ấn Độ Jamal Malik, một thanh niên bất hạnh không nhà cửa, không cha mẹ đăng kí tham dự chương trình với lý do thật đặc biệt nhưng đã xuất sắc vượt qua câu hỏi 10 triệu Rupee đúng lúc đó thời lượng của chương trình hết. Jamal bị cảnh sát bắt vì nghi ngờ anh gian lận trong cuộc thi cuối cùng họ đã phải thả Jamal để anh tiếp tục cuộc thi khi biết lý do giúp Jamal có thể trả lời tất cả câu hỏi ở nhiều lĩnh vực mà người dẫn chương trình đưa ra. Lý do đó là gì? Jamal có chiến thắng ở phần còn lại của chương trình? Slumdog Millionaire là bức tranh về cuộc sống của hàng chục triệu người thuộc tầng lớp dưới của xã hội Ấn Độ những người đang hàng ngày giành giật miếng cơm manh áo để tồn tại trong hoàn cảnh vô cùng khắc nghiệt nhưng dường như khao khát vươn lên không bao giờ tắt trong họ. Slumdog Millionaire đã giành tới 8 giải Oscar và hàng chục danh hiệu danh giá khác.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dev Patel","avatar":""},{"name":"Saurabh Shukla","avatar":""},{"name":"Anil Kapoor","avatar":""},{"name":"Raj Zutshi","avatar":""},{"name":"Jeneva Talwar","avatar":""},{"name":"Freida Pinto","avatar":""},{"name":"Irrfan Khan","avatar":""},{"name":"Azharuddin Mohammed Ismail","avatar":""},{"name":"Ayush Mahesh Khedekar","avatar":""},{"name":"Jira Banjara","avatar":""},{"name":"Sheikh Wali","avatar":""},{"name":"Mahesh Manjrekar","avatar":""},{"name":"Sanchita Choudhary","avatar":""},{"name":"Himanshu Tyagi","avatar":""},{"name":"Sharib Hashmi","avatar":""},{"name":"Virendra Chatt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
