INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ke-luc-nua-dem', 'Chuyện Kể Lúc Nửa Đêm', 'Bedtime Stories', 'https://phimimg.com/upload/vod/20231109-1/39c33e80b643d6d85a1cbaf023c0721f.jpg', 'https://phimimg.com/upload/vod/20231109-1/13c9967151e77e71c2d6dcdbb331f63b.jpg', '<p>Skeeter Bronson là một anh chàng kém may mắn, luôn kể chuyện trước khi đi ngủ cho cháu gái và cháu trai của mình. Nhưng cuộc sống của anh bị đảo lộn khi những câu chuyện kỳ ảo mà anh bịa ra để giải trí một cách khó hiểu lại trở thành hiện thực. Liệu Skeeter đang hoang mang có thể kiểm soát được những tưởng tượng ngang ngược của mình khi những nhân vật và tình huống kỳ quặc trong tâm trí anh ta đã biến thành những con người và sự kiện thực tế?</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Lucy Lawless","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Aisha Tyler","avatar":""},{"name":"Kathryn Joosten","avatar":""},{"name":"Jonathan Morgan Heit","avatar":""},{"name":"Laura Ann Kesling","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Tim H","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324481);
