INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-dia-cau', 'Thảm Họa Địa Cầu', 'The Happening', 'https://phimimg.com/upload/vod/20231109-1/12c9329f3ec705cb761ee3ac65889e8b.jpg', 'https://phimimg.com/upload/vod/20231109-1/e76759a4a80fa6674dc855a44e83c9c1.jpg', '<p>Câu chuyện của The Happening bắt đầu trong công viên Central Park, vào một buổi sáng đẹp trời, nhưng tất cả lại trở thành ác mộng khi một vài người, sau đó là tất cả mọi người bỗng nhiên dừng lại, tê cứng và tự kết liễu cuộc đời mình bằng những cách rất dã man. Báo, đài, tivi đều ầm ĩ với hiện tượng kỳ lạ này, phải chăng đó là cuộc tấn công của một bọn khủng bố? Hay có điều gì đó không ổn?</p>', 'Full', 1, 'single', 'completed', 28, 2008, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Ashlyn Sanchez","avatar":""},{"name":"Betty Buckley","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Robert Bailey Jr.","avatar":""},{"name":"Frank Collison","avatar":""},{"name":"Jeremy Strong","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Victoria Clark","avatar":""},{"name":"M. Night Shyamalan","avatar":""},{"name":"Alison Folland","avatar":""},{"name":"Kristen Connolly","avatar":""},{"name":"Cornell Womack","avatar":""},{"name":"Curtis McCla","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324481);
