INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-truy-duoi-tan-khoc', 'Cuộc Truy Đuổi Tàn Khốc', '10,000 BC', 'https://phimimg.com/upload/vod/20231103-1/11e5598479c8a6e709b41cb0589a82d7.jpg', 'https://phimimg.com/upload/vod/20231103-1/1c36eb125b0c3fbd76743d64edef0d27.jpg', '<p>10,000 B.C &nbsp;kể về hành trình đầy gian nan của chàng trai D&quot;Leh. Ở nơi ngọn núi cao nhất, có một bộ lạc sinh sống. Trong bộ lạc đó có anh chàng thợ săn D&quot;Leh. Từ mặc cảm của một cậu bé mồ côi có người cha hèn nhát, D”Leh đã lớn lên và trở thành một thợ săn tài năng. Anh được bộ lạc giao cho cây thương trắng quyền năng và được lựa chọn người phụ nữ cho mình. Anh đã chọn nàng Evolet xinh đẹp. Nhưng một toán giặc cướp đi vị hôn thê Evolet, D&quot;Leh dấn thân vào hành trình giải cứu. Họ chạm trán với các sinh vật săn mồi và những tộc người xa lạ trên đường đi, trước khi đặt chân tới nơi sẽ thay đổi số phận toàn nhân loại... từ đây, cuộc phiêu lưu của họ bắt đầu...</p>', 'Full', 1, 'single', 'completed', 21, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Strait","avatar":""},{"name":"Camilla Belle","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Nathanael Baring","avatar":""},{"name":"Mo Zinal","avatar":""},{"name":"Affif Ben Badra","avatar":""},{"name":"Mona Hammond","avatar":""},{"name":"Marco Khan","avatar":""},{"name":"Reece Ritchie","avatar":""},{"name":"Joel Fry","avatar":""},{"name":"Joel Virgel","avatar":""},{"name":"Omar Sharif","avatar":""},{"name":"Kristian Beazley","avatar":""},{"name":"Junior Oliphant","avatar":""},{"name":"Louise Tu''u","avatar":""},{"name":"Jacob Renton","avatar":""},{"name":"Grayson Hunt Urwin","avatar":""},{"name":"Fa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324481);
