INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-le-giang-sinh', 'Bốn Lễ Giáng Sinh', 'Four Christmases', 'https://phimimg.com/upload/vod/20231103-1/db77f2c589cd370f1622422eaf33ad45.jpg', 'https://phimimg.com/upload/vod/20231103-1/bb337415da3fff797d3aa1b539f4182a.jpg', '<p>Brad và Kate đã tạo ra một thứ gì đó nghệ thuật để trốn tránh gia đình của họ trong những ngày lễ, nhưng năm nay kế hoạch hoàn hảo của họ sắp phá sản - thời điểm quan trọng. Bị mắc kẹt tại sân bay thành phố sau khi tất cả các chuyến bay khởi hành đều bị hủy bỏ, cặp đôi cảm thấy xấu hổ khi thấy mưu mẹo của họ bị một phóng viên truyền hình quá khích vạch trần. Giờ đây, Brad và Kate chỉ còn lại ít sự lựa chọn quý giá ngoài việc nuốt chửng niềm kiêu hãnh của mình và chịu đựng các vòng đấu.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Sissy Spacek","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Tim McGraw","avatar":""},{"name":"Katy Mixon","avatar":""},{"name":"Jeanette Miller","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Jack Donner","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Steve Wiebe","avatar":""},{"name":"Zak Bog","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
