INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('front-of-the-class', 'Front of the Class', 'Front of the Class', 'https://phimimg.com/upload/vod/20231113-1/434b7b2cd34494a01573256804227294.jpg', 'https://phimimg.com/upload/vod/20231113-1/d86bdfef9850cb067de6f3945dc72e2e.jpg', '<p>Sau khi bị thách thức bởi hội chứng Tourette từ một độ tuổi rất trẻ, Brad Cohen bất chấp tất cả các tỷ lệ cược để trở thành một giáo viên có năng khiếu. Khi Cohen phát triển lên, anh ta phải đối mặt với bạn bè và các bạn cùng lớp, những người không nhận ra rằng đôi khi anh ta không thể kiểm soát sự bùng nổ của mình và một người cha dường như không muốn chấp nhận tình trạng của con trai mình.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Wolk","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Dominic Scott Kay","avatar":""},{"name":"Sarah Drew","avatar":""},{"name":"Kathleen York","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Patricia Heaton","avatar":""},{"name":"Johnny Pacar","avatar":""},{"name":"Charles Henry Wyson","avatar":""},{"name":"Charlie Finn","avatar":""},{"name":"Dianne Butler","avatar":""},{"name":"Helen Ingebritsen","avatar":""},{"name":"Laura Whyte","avatar":""},{"name":"Mike Pniewski","avatar":""},{"name":"Michael H. Cole","avatar":""},{"name":"Breanna Brooks","avatar":""},{"name":"Chase Mc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324481);
