INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('front-of-the-class', 'Front of the Class', 'Front of the Class', 'front of the class front of the class james wolk treat williams dominic scott kay sarah drew kathleen york joe chrest patricia heaton johnny pacar charles henry wyson charlie finn dianne butler helen ingebritsen laura whyte mike pniewski michael h. cole breanna brooks chase mc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-nim', 'Thế Giới Của Nim', 'Nim''s Island', 'https://phimimg.com/upload/vod/20231103-1/0c633e79cf9c437aa2f704baa3440e58.jpg', 'https://phimimg.com/upload/vod/20231103-1/48d574c64089ebb7df63d837ccc538d8.jpg', '<p>Nim sống trên một hòn đảo, bất cứ điều gì cũng có thể xảy ra ở thế giới của cô bé. Đây là nơi mọi điều trong tưởng tượng trở thành sự thật. Vây quanh Nim là những người bạn thú kỳ lạ và các huyền thoại trong sách vở. Khi hòn đảo của cô bé bị tấn công, Nim đi tìm nhà phiêu lưu nổi danh nhất thế giới, cũng là người hùng trong truyện mà cô ngưỡng mộ: Alex Rover. Tuy nhiên, một điều Nim không biết đó là tác giả loạt sách nổi tiếng về Rover, thực ra là Alexandra Rover, một người nhút nhát ẩn mình trong căn hộ riêng. Khi Alexandra quyết định lao mình vào cuộc phiêu lưu thực cùng với Nim, họ học được lòng can đảm ở chính nhân vật Alex Rover, khơi dậy sức mạnh trong mỗi người để cùng bảo vệ hòn đảo của Nim.</p>', 'Full', 1, 'single', 'completed', 23, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Abigail Breslin","avatar":""},{"name":"Jodie Foster","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Michael Carman","avatar":""},{"name":"Maddison Joyce","avatar":""},{"name":"Christopher James Baker","avatar":""},{"name":"Rhonda Doyle","avatar":""},{"name":"Bryan Probets","avatar":""},{"name":"Jay Laga''aia","avatar":""},{"name":"Mark Brady","avatar":""},{"name":"Anthony Simcoe","avatar":""},{"name":"Peter Callan","avatar":""},{"name":"Russell Butler","avatar":""},{"name":"Colin Gibson","avatar":""},{"name":"Andrew Nason","avatar":""},{"name":"Dorothy Thorsen","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324482);
