INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-minh-tinh-va-chang-lang-tu', 'Nữ Minh Tinh và Chàng Lãng Tử', 'Beverly Hills Chihuahua', 'https://phimimg.com/upload/vod/20231103-1/252faf0309c5e24c433b1f18afcdd645.jpg', 'https://phimimg.com/upload/vod/20231103-1/b9843b4f8fa5ed3783e0434c98e2679e.jpg', '<p>Một chú chó chihuahua được nuông chiều ở Beverly Hills tên là Chloe, trong khi đi nghỉ ở Mexico với cháu gái của chủ sở hữu là Viv, Rachel, bị lạc và phải nhờ bạn bè giúp cô trở về nhà trước khi cô bị bắt bởi một kẻ lừa đảo muốn đòi tiền chuộc.</p>', 'Full', 1, 'single', 'completed', 11, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Andy García","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Paul Rodríguez","avatar":""},{"name":"Plácido Domingo","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Eddie ''Piolin'' Sotelo","avatar":""},{"name":"Carlos Juvera","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Manolo Cardona","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Cheech","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324482);
