INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-tren-chien-hao', 'Người Tình Trên Chiến Hào', 'Passchendaele', 'https://phimimg.com/upload/vod/20231101-1/cf8708b8fbb1c77295f9307fee1ffe75.jpg', 'https://phimimg.com/upload/vod/20231101-1/1af3244c3d6df70cad22e6e8e90f1f13.jpg', '<p>Trung sĩ Michael Dunne chiến đấu trong Tiểu đoàn 10, hay còn gọi là &quot;Chiến đấu thứ mười&quot; với Sư đoàn 1 Canada và tham gia tất cả các trận đánh lớn của Canada trong cuộc chiến, đồng thời lập kỷ lục về số lượng giải thưởng dũng cảm cá nhân cao nhất cho một trận chiến</p>', 'Full', 1, 'single', 'completed', 19, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Paul Gross","avatar":""},{"name":"Caroline Dhavernas","avatar":""},{"name":"Joe Dinicol","avatar":""},{"name":"Meredith Bailey","avatar":""},{"name":"Adam J. Harrington","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"James Kot","avatar":""},{"name":"Jesse Frechette","avatar":""},{"name":"Robert Nogier","avatar":""},{"name":"David LeReaney","avatar":""},{"name":"Jayson Therrien","avatar":""},{"name":"Michael Greyeyes","avatar":""},{"name":"Landon Liboiron","avatar":""},{"name":"Hugh Probyn","avatar":""},{"name":"Jim Mezon","avatar":""},{"name":"Brian Dooley","avatar":""},{"name":"Patricia Be","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324482);
