INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-ghe', 'Anh Em Ghẻ', 'Step Brothers', 'https://phimimg.com/upload/vod/20231030-1/613c887a9a46a91597eeae62e66d3aa6.jpg', 'https://phimimg.com/upload/vod/20231030-1/36c3d9e881ae6f6639fabe03df681f19.jpg', '<p>Brennan Huff là anh chàng 39 tuổi với công việc làm thêm không ổn định và đang sống chung cùng với mẹ mình là Nancy. Còn Dale Doback cũng là một anh chàng tương tự nhưng lớn hơn Brenna 1 tuổi và sống cùng cha mình là Robert.Khi Nancy và Robert gặp gỡ, yêu nhau và dọn về sống cùng nhau thì đột ngột Brennan và Dale trở thành anh em ghẻ của nhau.Mặc dù thời gian đầu sống cùng nhau dưới một mái nhà, Brennan và Dale luôn có những mâu thuẫn với nhau, ghét nhau, nhưng rồi, cả hai chợt nhận ra rằng dường như giữa họ có những điểm tương đồng với nhau, đều là những kẻ lớn xác nhưng đầu óc thì như những đứa trẻ và nhất là lười biếng như nhau.Thế rồi, cả hai buộc phải hợp tác với nhau khi mà cha mẹ của họ muốn họ phải dọn ra ở riêng…</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Andrea Savage","avatar":""},{"name":"Lurie Poston","avatar":""},{"name":"Elizabeth Yozamp","avatar":""},{"name":"Logan Manus","avatar":""},{"name":"Travis T. Flory","avatar":""},{"name":"Lili Rose McKay","avatar":""},{"name":"Shira Piven","avatar":""},{"name":"Seth Morris","avatar":""},{"name":"Wayne Federman","avatar":""},{"name":"Maria Quiban","avatar":""},{"name":"Danielle Schne","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324482);
