INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-trai-dat-ngung-quay', 'Ngày Trái Đất Ngừng Quay', 'The Day the Earth Stood Still', 'https://phimimg.com/upload/vod/20231029-1/4861bd81056559998d7116a98cf23adc.jpg', 'https://phimimg.com/upload/vod/20231029-1/051a6df7d3adf1e9e8dc30ff78d37466.jpg', '<p>Bộ phim bắt đầu từ việc tiến sĩ Helen Benson được triệu tập đến một cơ sở quân sự với một số nhà khoa học khác khi một tàu vũ trụ ngoài hành tinh của các loại đến ở thành phố New York. Trên tàu là một giống người ngoài hành tinh và một con robot khổng lồ với kích thước lớn cũng như có khả năng chiến đấu rất khủng khiếp. Những người ngoài hành tinh tự xưng là Klaatu và cho biết anh ta đến để cứu trái đất. &nbsp;Tuy nhiên các phương pháp thẩm tra sau đó lại khiến Klaatu và những người đứng sau anh ta quyết định rằng loài người sẽ phải bị xóa sổ để Trái đất có thể tồn tại.</p>', 'Full', 1, 'single', 'completed', 17, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Jaden Smith","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"James Hong","avatar":""},{"name":"Jake McLaughlin","avatar":""},{"name":"John Rothman","avatar":""},{"name":"Sunita Prasad","avatar":""},{"name":"Juan Riedinger","avatar":""},{"name":"Sam Gilroy","avatar":""},{"name":"Tanya Champoux","avatar":""},{"name":"Rukiya Bernard","avatar":""},{"name":"Mous","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324482);
