INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-kung-fu', 'Vua Kung Fu', 'The Forbidden Kingdom', 'https://phimimg.com/upload/vod/20231029-1/4be5630132d93cc074add930875ad0e7.jpg', 'https://phimimg.com/upload/vod/20231029-1/e058199a665ec37b8f46eb1cf1e7e048.jpg', '<p>Jason anh chàng người Mỹ ham mê võ thuật Trung Hoa tới cực điểm trái ngược với suy nghĩ của mọi người Jason lại thường xuyên bị bạn bè bắt nạt nhưng mọi chuyện đã thay đổi khi Jason tới tiệm cho thuê phim kiêm cầm đồ của ông lão người Tàu tên Hop. Cậu ngỡ ngàng khi ngó thấy một cây gậy sắt màu vàng nằm trong căn phòng lâu nay vẫn kín cửa. Ông lão đã trao cho cậu cây gậy và sau 500 năm cậu chính là người được chọn để giải cứu Tôn Ngộ Không. The Forbidden Kingdom được coi là phim bom tấn của Châu Á vào thời điểm nó ra đời. The Forbidden Kingdom quy tụ dàn sao hùng hậu với Lý Liên Kiệt, Thành Long, Lưu Diệc Phi khán giả chắc chắn sẽ mãn nhãn khi xem phim.</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Jet Li","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Morgan Benoit","avatar":""},{"name":"Jack Posobiec","avatar":""},{"name":"Thomas McDonell","avatar":""},{"name":"Juana Collignon","avatar":""},{"name":"Zhi Ma Gui","avatar":""},{"name":"Shen Shou He","avatar":""},{"name":"Bin Jiang","avatar":""},{"name":"Shaohua Yang","avatar":""},{"name":"Yu Yuan Zeng","avatar":""},{"name":"David William No","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"