INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-vong-tinh-yeu', 'Khát Vọng Tình Yêu', 'Revolutionary Road', 'https://phimimg.com/upload/vod/20231029-1/eebba29097c7192cc4f2d30dce8f41f7.jpg', 'https://phimimg.com/upload/vod/20231029-1/a6f2abe70710dde35a42d501766f2928.jpg', '<p>Một cặp vợ chồng trẻ sống ở vùng ngoại ô Connecticut vào giữa những năm 1950 phải vật lộn để giải quyết các vấn đề cá nhân của họ trong khi cố gắng nuôi dạy hai đứa con của họ. Dựa trên một cuốn tiểu thuyết của Richard Yates.</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Richard Easton","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Max Baker","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Christopher Fitzgerald","avatar":""},{"name":"Jonathan Roumie","avatar":""},{"name":"Neal Bledsoe","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Samantha Soul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324482);
