INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-shippden-nhiem-vu-bi-mat', 'Naruto Shippūden: Nhiệm Vụ Bí Mật', 'Naruto Shippuden the Movie: Bonds', 'https://phimimg.com/upload/vod/20231029-1/37c87ed777b6042ad82b75ae710b41a7.jpg', 'https://phimimg.com/upload/vod/20231029-1/00ff394008981b7236861379283953fc.jpg', '<p>Phim kể về những thành viên bí ẩn của ninja từ Land of the Sky thực hiện một cuộc tấn công bất ngờ vào Konoha . Điều này là bởi vì Konoha đã gần như tiêu diệt đất của Sky trong Chiến tranh thế giới thứ hai Shinobi. Nhóm bắt đầu tấn công Konoha, gây ra tình trạng lộn xộn khối, với Sora-nin bay sử dụng một thiết bị Cơ Winged và bắn phá làng. Một cậu bé đã đi một chặng đường rất dài để thông báo cho Konoha rằng ngôi làng của mình đã bị tấn công, và rằng ông đang tìm kiếm sensei của mình, những người hiện đang ở Konoha, để ông có thể quay lại với anh ta để chữa lành những người bị thương tại ngôi làng của mình.Một nhóm ba người, gồm Naruto , Sakura và Hinata , đã được gửi đi cùng các cậu bé, Amaru , và Shinno , sensei của mình, để giúp làng của Amaru.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Noriaki Sugiyama","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Motoko Kumai","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Koichi Tochika","avatar":""},{"name":"Keiko Nemoto","avatar":""},{"name":"Junichi Endo","avatar":""},{"name":"Kouji Fujiyoshi","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Kujira","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324482);
