INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('naruto-shippden-nhiem-vu-bi-mat', 'Naruto Shippūden: Nhiệm Vụ Bí Mật', 'Naruto Shippuden the Movie: Bonds', 'naruto shippūden: nhiệm vụ bí mật naruto shippuden the movie: bonds junko takeuchi noriaki sugiyama chie nakamura unsho ishizuka motoko kumai kazuhiko inoue rikiya koyama showtaro morikubo nana mizuki satoshi hino kentaro ito koichi tochika keiko nemoto junichi endo kouji fujiyoshi kazuyuki okitsu kujira ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho-2-tren-nhung-con-duong', 'Vũ Điệu Đường Phố 2: Trên Những Con Đường', 'Step Up 2: The Streets', 'https://phimimg.com/upload/vod/20231029-1/4edeb71e5059df6ce38d4507367d6554.jpg', 'https://phimimg.com/upload/vod/20231029-1/04b4889136973ce368aa09a16fa4b812.jpg', '<p>Andie là một cô gái đam mê những điệu nhảy đầy cảm xúc và ngẫu hứng của đường phố. Sau khi mẹ qua đời, Andie sống cùng gia đình người bạn gái thân nhất của mẹ. Cô bạn buộc phải nhập học trường nghệ thuật Maryland nếu không muốn bị chuyển tới Texas. Tại đây, Andie gặp gỡ Chase Collins - anh chàng hotboy của trường Maryland và cũng là một vũ công xuất sắc. Họ mạnh dạn lập nên một nhóm nhảy, quy tụ những thành viên đặc biệt nhất trong trường. Từ những sinh viên hết sức bình thường trong môi trường nghệ thuật chuyên nghiệp, họ đã gắn kết với nhau và sẵn sàng cho cuộc thi nhảy đường phố khu vực Baltimore đang đến rất gần...</p>', 'Full', 1, 'single', 'completed', 17, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Briana Evigan","avatar":""},{"name":"Robert Hoffman","avatar":""},{"name":"Will Kemp","avatar":""},{"name":"Cassie Ventura","avatar":""},{"name":"Adam Sevani","avatar":""},{"name":"Danielle Polanco","avatar":""},{"name":"Telisha Shaw","avatar":""},{"name":"Black Thomas","avatar":""},{"name":"Mari Koda","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Hi-Hat","avatar":""},{"name":"Kate Lacey","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Delia Goncalvez","avatar":""},{"name":"Alison Faulk","avatar":""},{"name":"Sonja Sohn","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324486);
