INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-dieu-duong-pho-2-tren-nhung-con-duong', 'Vũ Điệu Đường Phố 2: Trên Những Con Đường', 'Step Up 2: The Streets', 'vũ điệu đường phố 2: trên những con đường step up 2: the streets briana evigan robert hoffman will kemp cassie ventura adam sevani danielle polanco telisha shaw black thomas mari koda harry shum jr. hi-hat kate lacey channing tatum delia goncalvez alison faulk sonja sohn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-tinh-ai', 'Con Đường Tình Ái', 'Sex Drive', 'https://phimimg.com/upload/vod/20231030-1/66f434acc0dae7dc4b237b375df581c2.jpg', 'https://phimimg.com/upload/vod/20231030-1/e4ff8ddd5654c1985812ecb47ea08294.jpg', '<p>Chàng trai 18 tuổi Ian Lafferty quyết định thực hiện chuyến du hành kéo dài 500 dặm từ Chicago đến Knoxville cùng cậu bạn thân Lance của mình chỉ để “đánh mất” sự trinh trắng của mình với một người đẹp tóc vàng bốc lửa mang biệt danh Ms. Tasty mà Ian làm quen được trên mạng. Vấn đề rắc rối của Ian là cậu phải đánh cắp chiếc xe hơi đắt tiền của ông anh trai kiêu ngạo Rex để làm phương tiện di chuyển vì người đẹp không thể chờ đợi cậu quá lâu. Tuy nhiên, Ian không thể ngờ rằng chuyến đi mà cậu sắp trải nghiệm lại là một chuyến hành trình đầy những sự rủi ro vui nhộn trong sự truy đuổi ráo riết của Rex cùng cuộc sống tự do phóng túng trên đường đi sẽ dạy cho Ian nhiều kinh nghiệm sống hơn cả những ...</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Zuckerman","avatar":""},{"name":"Amanda Crew","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Alice Greczyn","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Mark L. Young","avatar":""},{"name":"Cole Petersen","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Michael Cudlitz","avatar":""},{"name":"Allison Weissman","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Kim Ostrenko","avatar":""},{"name":"Brett Rice","avatar":""},{"name":"David Koechner","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324486);
