INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-9-no-vao-mua-dong-hoa-sakura-dieu-ky', 'Đảo Hải Tặc 9: Nở Vào Mùa Đông, Hoa Sakura Diệu Kỳ', 'One Piece: Episode of Chopper Plus: Bloom in the Winter, Miracle Cherry Blossom', 'https://phimimg.com/upload/vod/20231030-1/446788c177d6418c1f7ca707b980e971.jpg', 'https://phimimg.com/upload/vod/20231030-1/b0eec9d94eaffb4c59e18dae5cc1b154.jpg', '<p>Tập phim kể lại câu chuyện gia nhập băng Mũ Rơm của Tony Chopper dưới sự lãnh đạo của Luffy. Luffy lãnh đạo nhóm hải tặc Mũ Rơm qua East Blue và rồi tiến đến Grand Line. Cậu theo dấu chân của vị vua hải tặc quá cố, Gol D. Roger, chu du từ đảo này sang đảo khác để đến với kho báu vĩ đại One Piece. Mỗi thành viên trong nhóm đều có 1 quá khứ rất đặc biệt và đáng buồn. Ngoài khả năng đặc biệt trong công việc của mình, bất cứ thành viên nào cũng có khả năng chiến đấu rất tốt.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2008, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Bin Shimada","avatar":""},{"name":"Yusuke Numata","avatar":""},{"name":"Kenji Nomura","avatar":""},{"name":"Kenichi Ono","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Shigeru Ushiyama","avatar":""},{"name":"Monta Mino","avatar":""},{"name":"Mahito Ohba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu