INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-san-ban-2', 'Mùa Săn Bắn 2', 'Open Season 2', 'https://phimimg.com/upload/vod/20231030-1/08254f94b72adc6400a07a8476c31de7.jpg', 'https://phimimg.com/upload/vod/20231030-1/b04a84aa23cd719eabf4b9853c1e9771.jpg', '<p>Sau khi yêu Giselle, con đường đến với bàn thờ của Elliot phải đi một đoạn đường vòng khi ông Weenie bị bắt cóc bởi một nhóm thú cưng được nuông chiều quyết tâm trả lại cho chủ nhân của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joel McHale","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Georgia Engel","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Maddie Taylor","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"Fred Stoller","avatar":""},{"name":"Sean Mullen","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Olivia Hack","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Michelle Murdocca","avatar":""},{"name":"Jacquie Barnbrook","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324486);
