INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-cai-bang', 'Siêu Nhân Cái Bang', 'Hancock', 'https://phimimg.com/upload/vod/20231026-1/ca68684bc6db41baf93b1caf67e2510c.jpg', 'https://phimimg.com/upload/vod/20231026-1/c0e6c8dc5d42b5363afc13105cab2340.jpg', '<p>Bộ phim là câu chuyện hài hước về Siêu anh hùng lười biếng Hancock. Vì những tật xấu cố hữu của mình mà Hancock bị mọi người ghét bỏ. Và để lấy lại hình ảnh của một Siêu anh hùng được yêu mến, Hancock đã có một kế hoạch...</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Jae Head","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"David Mattey","avatar":""},{"name":"Maetrix Fitten","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Johnny Galecki","avatar":""},{"name":"Hayley Marie Norman","avatar":""},{"name":"Dorothy Cecchi","avatar":""},{"name":"Peter Berg","avatar":""},{"name":"Darrell Foster","avatar":""},{"name":"Brandon Ford Green","avatar":""},{"name":"Daeg Faerch","avatar":""},{"name":"Ryan Radis","avatar":""},{"name":"Eddie J. Fernand","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324486);
