INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhan-cai-bang', 'Siêu Nhân Cái Bang', 'Hancock', 'siêu nhân cái bang hancock will smith charlize theron jason bateman jae head eddie marsan david mattey maetrix fitten thomas lennon johnny galecki hayley marie norman dorothy cecchi peter berg darrell foster brandon ford green daeg faerch ryan radis eddie j. fernand ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('voi-va-nhung-nguoi-ban', 'Voi và Những Người Bạn', 'Horton Hears a Who!', 'https://phimimg.com/upload/vod/20231026-1/ad2784de9b495ef13edfaee0a6aa9cec.jpg', 'https://phimimg.com/upload/vod/20231026-1/09bf52574f7b103e55157ce54762dbf0.jpg', '<p>Chú voi Horton tình cờ nghe thấy tiếng kêu cứu vọng ra từ một hạt bụi. Thật khó tin nhưng hạt bụi ấy là hành tinh của những người Who nhỏ bé. Họ đang gặp nguy hiểm và cầu Horton bảo vệ thành phố Who-ville của mình. Dù bị muông thú trong khu rừng Nool hết lời chế nhạo, chú vẫn quyết tâm nhận lời và bảo vệ những người bạn của mình tới cùng vì “con người là con người, dù họ nhỏ bé tới đâu”.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Carol Burnett","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Charles Osgood","avatar":""},{"name":"Josh Flitter","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Jesse McCartney","avatar":""},{"name":"Shelby Adamowsky","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Caitlin Rose Anderson","avatar":""},{"name":"Emily Anders","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7