INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('voi-va-nhung-nguoi-ban', 'Voi và Những Người Bạn', 'Horton Hears a Who!', 'voi và những người bạn horton hears a who! jim carrey steve carell carol burnett will arnett seth rogen dan fogler isla fisher jonah hill amy poehler jaime pressly charles osgood josh flitter niecy nash jesse mccartney shelby adamowsky jack angel caitlin rose anderson emily anders ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-than-bi', 'Khu Rừng Thần Bí', 'The Spiderwick Chronicles', 'https://phimimg.com/upload/vod/20231026-1/2e4dfc439d85673dfe00e3ba179083e1.jpg', 'https://phimimg.com/upload/vod/20231026-1/30e63801737494ed28201c99279b2159.jpg', '<p>Câu chuyện xoay quanh 3 đứa trẻ nhà Grace và mẹ chúng khi chuyển đến căn nhà trước đây thuộc về cụ cố Spiderwick. Do đám trẻ không thích thú gì với lần di dời này, chúng bắt đầu tự thích nghi với hoàn cảnh theo cách riêng của mình. Riêng Jared đã nhận thấy những điều kỳ lạ đang diễn ra quanh ngôi nhà và tiến hành tìm hiểu. Mặc kệ lời cảnh báo từ con gia tinh Thimbletack, một sinh vật thú vị sống trong những bức tường của ngôi nhà, cậu bé phát hiện ra một cuốn sách lạ có vẻ nguy hiểm do cụ cố Arthur viết có tựa đề Hướng dẫn Tìm hiểu Thế giới Quanh bạn của Arthur Spiderwick...</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Bolger","avatar":""},{"name":"Jordy Benattar","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Andrew McCarthy","avatar":""},{"name":"Lise Durocher-Viens","avatar":""},{"name":"Freddie Highmore","avatar":""},{"name":"Joan Plowright","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Tod Fennell","avatar":""},{"name":"Mariah Inger","avatar":""},{"name":"Jeremy Lavalley","avatar":""},{"name":"Kyle Switzer","avatar":""},{"name":"Tyler Patrick Jones","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324486);
