INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-rung-than-bi', 'Khu Rừng Thần Bí', 'The Spiderwick Chronicles', 'khu rừng thần bí the spiderwick chronicles sarah bolger jordy benattar mary-louise parker nick nolte andrew mccarthy lise durocher-viens freddie highmore joan plowright david strathairn seth rogen martin short tod fennell mariah inger jeremy lavalley kyle switzer tyler patrick jones ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-vao-long-dat', 'Cuộc Phiêu Lưu Vào Lòng Đất', 'Journey to the Center of the Earth', 'https://phimimg.com/upload/vod/20231026-1/16dc3a1157d4b496c739bea333ec68bd.jpg', 'https://phimimg.com/upload/vod/20231026-1/7e2ea4c490d6bdbd2605dc2edcc2c1e7.jpg', '<p>Phim Journey To The Center Of The Earth (Lạc Vào Tiền Sử) kể về chuyến phiêu lưu của một nhà khoa học, người đã bị thế giới chế nhạo vì những lí thuyết “điên rồ” của mình. Ông đã tiến hành một chuyến phiêu lưu đến Iceland, cùng với đứa cháu tên là Sean. Trong cuộc du hành này, họ đã tình cờ phát hiện ra một lối đi vào lòng đất. Các nhà thám hiểm quyết định tiếp tục cuộc phiêu lưu trong lòng đất để tìm hiểu chuyện gì đã xảy ra với người anh trai đã mất tích và người cháu của vị giáo sư. Và họ đã phát hiện ra một thế giới ngầm, một thế giới kì bí và đầy nguy hiểm trong lòng đất, với toàn những sinh vật khổng lồ nguy hiểm...</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Anita Briem","avatar":""},{"name":"Seth Meyers","avatar":""},{"name":"Jean Michel Paré","avatar":""},{"name":"Jane Wheeler","avatar":""},{"name":"Frank Fontaine","avatar":""},{"name":"Giancarlo Caltabiano","avatar":""},{"name":"Kaniehtiio Horn","avatar":""},{"name":"Garth Gilker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3