INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phieu-luu-vao-long-dat', 'Cuộc Phiêu Lưu Vào Lòng Đất', 'Journey to the Center of the Earth', 'cuộc phiêu lưu vào lòng đất journey to the center of the earth brendan fraser josh hutcherson anita briem seth meyers jean michel paré jane wheeler frank fontaine giancarlo caltabiano kaniehtiio horn garth gilker ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-diet-vong', 'Thảm Họa Diệt Vong', 'Cloverfield', 'https://phimimg.com/upload/vod/20231025-1/c088387b31e98fbd554319ba15016b0c.jpg', 'https://phimimg.com/upload/vod/20231025-1/8e43193a33f17408e27ce1f2d674eca1.jpg', '<p>Rob vừa được đề cử lên làm phó giám đốc cho công ty Slusho và anh buộc phải sang Nhật làm việc. Jason, anh trai của Rob cùng người bạn gái Lily tổ chức một bữa tiệc bất ngờ tại căn hộ của Rob ở Manhattan. Bất thình lình, một trận động đất xảy ra, đèn đóm chập chờn, mọi người trong bữa tiệc ngơ ngác ùa lên sân thượng. Xa xa, họ nhìn thấy những tòa nhà của thành phố New York đang bị pháo kích cháy nổ rực sáng bầu trời. Mọi người hoảng loạn chạy ra đường và họ nghe được những tiếng gầm kỳ quái, rồi từ trên không trung một vật thể to lớn rớt xuống mặt đường, đó chính là đầu của tượng Nữ Thần Tự do. Cư dân trong thành phố bây giờ bắt đầu chạy tán loạn. Cái gì đang tấn công thành phố này? Các bạn muốn biết ...</p>', 'Full', 1, 'single', 'completed', 23, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lizzy Caplan","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Michael Stahl-David","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Anjul Nigam","avatar":""},{"name":"Margot Farley","avatar":""},{"name":"Theo Rossi","avatar":""},{"name":"Brian Klugman","avatar":""},{"name":"Kelvin Yu","avatar":""},{"name":"Liza Lapira","avatar":""},{"name":"Lili Mirojnick","avatar":""},{"name":"Ben Feldman","avatar":""},{"name":"Elena Caruso","avatar":""},{"name":"Vakisha Coleman","avatar":""},{"name":"Will Greenberg","avatar":""},{"name":"Rob Kerko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2cc