INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-thong-tri', 'Những Kẻ Thống Trị', 'Jumper', 'https://phimimg.com/upload/vod/20231025-1/2a33527677bed8f96d998141019fa8e1.jpg', 'https://phimimg.com/upload/vod/20231025-1/852436267c3f5f9d7ae501b5b0678c40.jpg', '<p>David Rice phát hiện ra mình có khả năng di chuyển tức thời từ nơi này sang nơi khác chỉ trong nháy mắt. Từ đó anh phát hiện ra mình là một trong số những người hiếm hoi có được khả năng kỳ lạ này. Và cũng vì chính khả năng đó, anh bị kéo vào một cuộc chiến giữa những người dịch chuyển tức thời cũng như những người khác đã thề sẽ triệt tiêu tất cả những người có khả năng kỳ lạ đó.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Rachel Bilson","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Max Thieriot","avatar":""},{"name":"Jesse James","avatar":""},{"name":"Tom Hulce","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Teddy Dunn","avatar":""},{"name":"Barbara Garrick","avatar":""},{"name":"Michael Winther","avatar":""},{"name":"Massimiliano Pazzaglia","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Nath","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324486);
