INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-2008', 'Truy Sát', 'Wanted', 'https://phimimg.com/upload/vod/20231024-1/907081c2b2e1f1f266d3fcbc747f5a9d.jpg', 'https://phimimg.com/upload/vod/20231024-1/e0ab3409d184130d9b168ad235735079.jpg', '<p>Câu chuyện xoay quanh anh chàng Wesley Gibson, một thanh niên trẻ tuổi nhưng lại sống một cách chán chường vì những điều bất mãn trong công việc và tình yêu. Đến công sở, anh phải chịu những lời chì chiết của sếp trước mặt đồng nghiệp. Khi trở về nhà, anh lại chứng kiến cảnh cô người yêu của mình bị lắm kẻ dòm ngó, trong đó có cả người bạn thân nhất của anh. Cuộc sống như thế đã đẩy Wesley đến tình cảnh của một kẻ thất bại, anh nhấm nháp cái chết trong lòng qua mỗi phút giây. Rất may cho Wesley, những ngày đau khổ ấy mau chóng chấm dứt, và cuộc sống của anh rẽ sang một hướng hoàn toàn mới... vì một cô gái - nữ sát thủ Fox, từ đó Wesley biết được câu chuyện về người cha mà lâu nay anh không hề biết mặt.</p>', 'Full', 1, 'single', 'completed', 17, 2008, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Common","avatar":""},{"name":"Kristen Hager","avatar":""},{"name":"Marc Warren","avatar":""},{"name":"David O''Hara","avatar":""},{"name":"Dato Bakhtadze","avatar":""},{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Lorna Scott","avatar":""},{"name":"Sophiya Haque","avatar":""},{"name":"Brian Caspe","avatar":""},{"name":"Mark O''Neal","avatar":""},{"name":"Bridget","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324486);
