INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-sat-2008', 'Truy Sát', 'Wanted', 'truy sát wanted james mcavoy angelina jolie morgan freeman terence stamp thomas kretschmann common kristen hager marc warren david o''hara dato bakhtadze konstantin khabenskiy chris pratt lorna scott sophiya haque brian caspe mark o''neal bridget ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sam-nhiet-doi', 'Sấm Nhiệt Đới', 'Tropic Thunder', 'https://phimimg.com/upload/vod/20231024-1/df6ca2b30a56ff21b8cff4efa26bf848.jpg', 'https://phimimg.com/upload/vod/20231024-1/abf23facd8ee1ee6eaab9691bf85612d.jpg', '<p>“Sấm nhiệt đới – Tropic Thunder” là một bBPhim xoay quanh câu chuyện về đoàn làm phim đã lỗi thời trong nỗ lực tìm lại hào quang đã mất của mình.&nbsp; Một tay súng kì cựu trong cuộc chiến tranh Việt Nam – trung sĩ John “bốn lá” đề ra ý tưởng làm ra bộ phim với đề tài chiến tranh Việt Nam. Ông thu thập những diễn viên nổi tiếng một thời nhưng hiện tại đã bị hào quang rời bỏ để lập thành một đoàn làm phim đặt biệt. Dự án chậm tiến độ và gặp nguy cơ bị bỏ rơi bởi nhà sản xuất.&nbsp; Theo lời khuyên của “Bốn lá”, Damien thả các diễn viên vào giữa rừng với máy quay ẩn và các vụ nổ hiệu ứng đặc biệt để dựng phim “theo phong cách du kích”, tăng độ chân thực và kịch tính cho phim. Các diễn viên được trang bị những khẩu súng giả cùng với một bản đồ và danh sách cảnh quay sẽ dẫn đến một chiếc trực thăng đang chờ ở cuối tuyến. Không ngờ rằng nơi đoàn phim bị bỏ lại là khu vực “Tam giác vàng” của băng đảng buôn bán heroin.</p>', 'Full', 1, 'single', 'completed', 20, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Tom Cruise","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Brandon Soo Hoo","avatar":""},{"name":"Reggie Lee","avatar":""},{"name":"Trieu Tran","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Tyra Banks","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Jennifer Lo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324486);
