INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sam-nhiet-doi', 'Sấm Nhiệt Đới', 'Tropic Thunder', 'sấm nhiệt đới tropic thunder ben stiller jack black robert downey jr. tom cruise nick nolte jay baruchel brandon t. jackson steve coogan matthew mcconaughey danny mcbride bill hader brandon soo hoo reggie lee trieu tran tobey maguire tyra banks jon voight jennifer lo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-dinh-muc-khuay-khoa', 'Điệp Viên 007: Định Mức Khuây Khỏa', 'Quantum of Solace', 'https://phimimg.com/upload/vod/20231024-1/e39e3e904bd5a57e26da25a7ba25e4f2.jpg', 'https://phimimg.com/upload/vod/20231024-1/6daf66e372280442e34be3aeac0c7308.jpg', '<p>Bắt đầu từ cái chết của Vesper, người con gái anh yêu, Bond cùng ‘M’ thẩm vấn Mr. White để tìm ra tung tích của tổ chức bí mật đã gây sức ép lên Vesper. Một sự tình cờ đã đưa Bond đến Haiti để gặp Camille, người phụ nữ xinh đẹp có mối hận thù với Dominic Greene, tay thương gia độc ác đội lốt nhà hảo tâm và tổ chức Quantum của hắn ta. Một nhiệm vụ sau đó đã đưa Bond tới Úc, Italia, và Nam Mỹ, và tại đây anh phát hiện ra Greene có âm mưu thống trị một trong những tài nguyên thiên nhiên quan trọng nhất của thế giới. Gạt bỏ tất cả sự phản bội, chết chóc, và lừa dối đã trải qua, Bond liên minh với những người bạn cũ để tìm ra sự thật. 007 một lần nữa quyết định qua mặt CIA, và ngay cả “sếp” ‘M’ để ngăn chặn Greene cùng tổ chức của hắn.</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Mathieu Amalric","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Giancarlo Giannini","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Anatole Taubman","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Tim Pigott-Smith","avatar":""},{"name":"Joaquín Cosío","avatar":""},{"name":"Fernando Guillén Cuervo","avatar":""},{"name":"Jesús Ochoa","avatar":""},{"name":"Lucrezi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324486);
