INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ay-la-chuyen-nho', 'Chuyện Ấy Là Chuyện Nhỏ', 'Sex and the City', 'https://phimimg.com/upload/vod/20231024-1/8d0faa2428b2b41fab9a3f0b262cc4af.jpg', 'https://phimimg.com/upload/vod/20231024-1/32250867154f0ae9884429e3ac285846.jpg', '<p>Một nhà văn ở New York chuyên viết về tình dục và tình yêu cuối cùng đã kết hôn với Mr. Big của cô ấy. Nhưng ba người bạn gái thân nhất của cô ấy phải an ủi cô ấy sau khi một trong số họ vô tình làm Mr. Big phụ tình cô.</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Jessica Parker","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Chris Noth","avatar":""},{"name":"Candice Bergen","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"David Eigenberg","avatar":""},{"name":"Evan Handler","avatar":""},{"name":"Jason Lewis","avatar":""},{"name":"Mario Cantone","avatar":""},{"name":"Lynn Cohen","avatar":""},{"name":"Willie Garson","avatar":""},{"name":"Joanna Gleason","avatar":""},{"name":"Joseph Pupo","avatar":""},{"name":"Alexandra Fong","avatar":""},{"name":"Parker Fong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324486);
