INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-phim-heo-nghiep-du', 'Hãng Phim Heo Nghiệp Dư', 'Zack and Miri Make a Porno', 'https://phimimg.com/upload/vod/20231023-1/15517bdcdd31be9939ab4073113ce7a7.jpg', 'https://phimimg.com/upload/vod/20231023-1/6c7c624ee224224b9921e87cc46ccf8d.jpg', '<p>Những người bạn trung thành suốt đời Zack và Miri tìm cách giải quyết các vấn đề về dòng tiền của họ bằng cách làm một bộ phim người lớn cùng nhau. Tuy nhiên, khi máy quay quay, bộ đôi bắt đầu cảm thấy rằng họ có thể dành nhiều tình cảm cho nhau hơn những gì họ nghĩ trước đây.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Banks","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Gerry Bednob","avatar":""},{"name":"Edward Janda","avatar":""},{"name":"Nicholas Lombardi","avatar":""},{"name":"Chris Milan","avatar":""},{"name":"Jennifer Schwalbach Smith","avatar":""},{"name":"Kenny Hotz","avatar":""},{"name":"Brandon Routh","avatar":""},{"name":"Anne Wade","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Jeff Anderson","avatar":""},{"name":"Jim Norton","avatar":""},{"name":"Jean-Pierre Nutini","avatar":""},{"name":"Alice Eisner","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324486);
