INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hang-phim-heo-nghiep-du', 'Hãng Phim Heo Nghiệp Dư', 'Zack and Miri Make a Porno', 'hãng phim heo nghiệp dư zack and miri make a porno elizabeth banks seth rogen craig robinson gerry bednob edward janda nicholas lombardi chris milan jennifer schwalbach smith kenny hotz brandon routh anne wade justin long tom savini jeff anderson jim norton jean-pierre nutini alice eisner ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sat', 'Người Sắt', 'Iron Man', 'https://phimimg.com/upload/vod/20231023-1/95bcaaa3bbc20702755fc91569f0de3c.jpg', 'https://phimimg.com/upload/vod/20231023-1/3d81f21c3c591a90d625f038d44a53de.jpg', '<p>Tony Stark vừa là chủ tập đoàn công nghệ, vừa là một tay chơi kỳ dị. Trong chuyến thị sát Afghanistan, ông bị nhóm khủng bố bắt cóc. Chúng đòi Tony chế tạo thứ vũ khí hủy diệt để tấn công nước Mỹ.&nbsp; Nhận ra sự thật phũ phàng rằng, những vũ khí do mình chế tạo đang quay ngược lại tấn công chính mình, Tony bắt tay chế tạo bộ giáp công nghệ cao. Tẩu thoát khỏi nơi giam cầm, Tony trở thành đại diện công lý dưới biệt danh Người sắt. Trong khi đó, người đồng sự trong tập đoàn Stark âm mưu lật đổ Tony.&nbsp; Bộ phim mở ra câu chuyện trong tương lai về nhóm siêu anh hùng Avenger khi tổ chức bí mật SHIELD bắt đầu lộ diện.</p>', 'Full', 1, 'single', 'completed', 15, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Bill Smitrovich","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Faran Tahir","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Peter Billingsley","avatar":""},{"name":"Sayed Badreya","avatar":""},{"name":"Tim Guinee","avatar":""},{"name":"Will Lyman","avatar":""},{"name":"Tom Morello","avatar":""},{"name":"Marco Khan","avatar":""},{"name":"Daston Kal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"P