INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-rambo-4', 'Chiến Binh Rambo 4', 'Rambo IV', 'https://phimimg.com/upload/vod/20231022-1/cbd60a7c644c95d2b9fe4b59924c5bca.jpg', 'https://phimimg.com/upload/vod/20231022-1/94d3aff121c951863bca4e73a7546062.jpg', '<p>Trong Rambo IV, John Rambo quy ẩn về miền Bắc Thái Lan, sống một cuộc sống bình dị giữa núi rừng; cho đến khi một nhóm người thuộc tỗ chức đấu tranh vì quyền của con người tìm đến anh và nhờ Rambo dẫn đường đến Burma để cung cấp thuốc men. Nhưng khi những người làm việc từ thiện này bị bắt bởi quân đội của Burma thì Rambo quyết định một mình tấn công vào sào huyệt của chúng để cứu họ ...</p>', 'Full', 1, 'single', 'completed', 19, 2008, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Julie Benz","avatar":""},{"name":"Matthew Marsden","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Reynaldo Gallegos","avatar":""},{"name":"Tim Kang","avatar":""},{"name":"Jake La Botz","avatar":""},{"name":"Maung Maung Khin","avatar":""},{"name":"Paul Schulze","avatar":""},{"name":"Cameron Pearson","avatar":""},{"name":"Thomas Peterson","avatar":""},{"name":"Tony Skarberg","avatar":""},{"name":"James With","avatar":""},{"name":"Kasikorn Niyompattana","avatar":""},{"name":"Shaliew ''Lek'' Bamrun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324486);
