INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-narnia-hoang-tu-caspian', 'Biên Niên Sử Narnia: Hoàng Tử Caspian', 'The Chronicles of Narnia: Prince Caspian', 'https://phimimg.com/upload/vod/20231022-1/27d38cc94bab74141e8cf7e2eae26e2f.jpg', 'https://phimimg.com/upload/vod/20231022-1/7503ef538da51f7202b3be9ff010bfc5.jpg', '<p>Sau khi rời khỏi vùng đất thần tiên Narnia, 1 năm đã trôi qua bỗng 1 ngày nọ, lũ trẻ nhà Pevensie lại được triệu tập trở lại vùng đất thần tiên một cách đầy bất ngờ. Trở lại vùng đất quen thuộc nhưng nay đã thay đổi rất nhiều, lũ trẻ không ngờ rắng 1 năm của thế giới thực là 1300 năm của Narnia và người triệu tập chúng không phải Ngài Sư tử Aslan xưa mà là 1 chàng hoàng tử tuấn tú, hoàng tử của xứ sở Narnia huyền bí. 4 anh em nhà Pevensie lần nữa lại cùng chung sức với chàng hoàng tử nọ để chiến đấu chống lại cái ác đe dọa xứ sở thần tiên Narnia khi Nữ hoàng băng giá quay trở lại cùng 1 đạo quân hung tàn...</p>', 'Full', 1, 'single', 'completed', 24, 2008, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Georgie Henley","avatar":""},{"name":"Skandar Keynes","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Anna Popplewell","avatar":""},{"name":"Ben Barnes","avatar":""},{"name":"Sergio Castellitto","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Warwick Davis","avatar":""},{"name":"Vincent Grass","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"Cornell John","avatar":""},{"name":"Damián Alcázar","avatar":""},{"name":"Alicia Borrachero","avatar":""},{"name":"Simón Andreu","avatar":""},{"name":"Predrag Bjelac","avatar":""},{"name":"David Bowl","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58