INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bien-nien-su-narnia-hoang-tu-caspian', 'Biên Niên Sử Narnia: Hoàng Tử Caspian', 'The Chronicles of Narnia: Prince Caspian', 'biên niên sử narnia: hoàng tử caspian the chronicles of narnia: prince caspian georgie henley skandar keynes william moseley anna popplewell ben barnes sergio castellitto peter dinklage warwick davis vincent grass pierfrancesco favino cornell john damián alcázar alicia borrachero simón andreu predrag bjelac david bowl ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-3', 'Người Vận Chuyển 3', 'Transporter 3', 'https://phimimg.com/upload/vod/20231023-1/466691e7381ac8824025747d86124644.jpg', 'https://phimimg.com/upload/vod/20231023-1/63ad279b8dbf8214e800a0b2f2ff5df4.jpg', '<p>Trong Transporter 3, Frank Martin chịu nhiều sức ép trong việc hộ tống Valentina, cô con gái bị bắt cóc của Leonid Vasilev, người đứng đầu Cơ Quan Bảo Vệ Môi Trường của Ukraine, suốt chặng đường dài từ Marseilles đến Stuttgart và Budapest, trước khi dừng lại ở Odessa, Biển Đen.&nbsp; Suốt quãng đường đi, dù nhận được sự giúp đỡ của Thanh tra Tarconi, Frank liên tục phải đấu tranh với những người đã ép buộc anh phải nhận lấy công việc này, những tay chân của Vasilev được gửi đến để ngăn cản anh cùng sự bất hợp tác của Valentina. Bất chấp thái độ hoài nghi của Valentina, Frank và cô gái cuối cùng cũng đã chịu kết hợp cùng nhau trong lúc cả hai đang cố gắng thoát khỏi những tình huống đe dọa tính mạng của chính mình liên tiếp ập đến.</p>', 'Full', 1, 'single', 'completed', 18, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Natalya Rudakova","avatar":""},{"name":"François Berléand","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Jeroen Krabbé","avatar":""},{"name":"Alex Kobold","avatar":""},{"name":"David Atrakchi","avatar":""},{"name":"Yann Sundberg","avatar":""},{"name":"Ériq Ebouaney","avatar":""},{"name":"David Kammenos","avatar":""},{"name":"Silvio Simac","avatar":""},{"name":"Oscar Relier","avatar":""},{"name":"Timo Dierkes","avatar":""},{"name":"Igor Koumpan","avatar":""},{"name":"Paul Barrett","avatar":""},{"name":"Elef Zack","avatar":""},{"name":"Katia Tchenko","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324486);
