INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tia-chop', 'Tia Chớp', 'Bolt', 'https://phimimg.com/upload/vod/20231022-1/e7fffc74b7840a82e63fa987dcb0a36c.jpg', 'https://phimimg.com/upload/vod/20231022-1/94d510b9eca18f6eab13977c6ce5ba03.jpg', '<p>Đối với Bolt - chú chó siêu phàm, thì ngày nào cũng tràn đầy những cuộc phiêu lưu, nguy hiểm và bất ngờ. Thế nhưng tất cả những điều đó chỉ xảy ra đằng sau ống kính máy quay.&nbsp; Cho đến một ngày, siêu sao truyền hình tình cờ bị vận chuyển từ sân khấu Hollywood tới thành phố New York, nơi cậu bắt đầu cuộc phiêu lưu lớn nhất - một cuộc hành trình xuyên đất nước trong cuộc đời thực để trở về với người chủ - bạn diễn của mình là Penny.</p>', 'Full', 1, 'hoathinh', 'completed', 28, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Susie Essman","avatar":""},{"name":"Miley Cyrus","avatar":""},{"name":"Mark Walton","avatar":""},{"name":"Greg Germann","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Lino DiSalvo","avatar":""},{"name":"Todd Cummings","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"James Lipton","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Anne Lockhart","avatar":""},{"name":"J.P. Manoux","avatar":""},{"name":"Dan Fogelman","avatar":""},{"name":"Randy Savage","avatar":""},{"name":"Ronn","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324486);
