INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-the-ky', 'Vụ Cướp Thế Kỷ', 'The Bank Job', 'https://phimimg.com/upload/vod/20231023-1/5d52a863b610bf300bd7d795eeab578b.jpg', 'https://phimimg.com/upload/vod/20231023-1/3f5c4c6b2733c924da03ddb31d288076.jpg', '<p>Terry làm nghề buôn bán ô tô nhỏ đang cố gắng từ bỏ quá khứ tội lỗi để bắt đầu một gia đình hạnh phúc. Mặc dù chưa bao giờ phạm một tội nào quá lớn nhưng Terry vẫn chưa hẳn đã hoàn lương. Trong khi đó, Martine, hàng xóm cũ của Terry đã đề nghị anh ta tham gia vào một vụ cướp ngân hàng. Nhận thấy đây là một phi vụ cực kỳ nguy hiểm nhưng Terry biết nó cũng có thể mang tới cơ hội đổi đời. Kế hoạch được vạch ra và băng trộm đã tìm thấy những két bạc chứa đầy tiền vàng trong ngân hàng Lloyds ở Marylebone, Luân Đôn. Nhưng họ không hề biết rằng những ngăn kéo an toàn đó còn chứa cả các bí mật khủng khiếp liên quan tới các tên tội phạm thế giới ngầm, các nhân vật cốt cán trong chính phủ và thậm chí cả Hoàng gia. Liệu Terry và đồng phạm có phải là những tên cướp nhà băng tai tiếng nhất hay thực sự chỉ là những kẻ vô tội trong một tội ác kinh hoàng?</p>', 'Full', 1, 'single', 'completed', 19, 2008, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Stephen Campbell Moore","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"James Faulkner","avatar":""},{"name":"Andrew Brooke","avatar":""},{"name":"Michael Jibson","avatar":""},{"name":"Georgia Taylor","avatar":""},{"name":"Richard Lintern","avatar":""},{"name":"Peter Bowles","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Alki David","avatar":""},{"name":"Hattie Morahan","avatar":""},{"name":"Julian Lewis Jones","avatar":""},{"name":"Rupert Frazer","avatar":""},{"name":"Keeley Hawes","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324486);
