INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-cuop-the-ky', 'Vụ Cướp Thế Kỷ', 'The Bank Job', 'vụ cướp thế kỷ the bank job jason statham saffron burrows stephen campbell moore daniel mays james faulkner andrew brooke michael jibson georgia taylor richard lintern peter bowles alistair petrie alki david hattie morahan julian lewis jones rupert frazer keeley hawes ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-hoai-nghi', 'Sự Hoài Nghi', 'Changeling', 'https://phimimg.com/upload/vod/20231023-1/35539c16b222b2db94323b140734c28b.jpg', 'https://phimimg.com/upload/vod/20231023-1/193836ed2c708786db8fa0370ecc4244.jpg', '<p>Phim có bối cảnh năm 1928, được dựa trên câu chuyện có thật tại Los Angeles, Angelina Jolie vào vai Christine một nhân viên giám sát tại tổng đài điện thoại địa phương.Một ngày nọ, cậu con trai của cô đột ngột bị bắt cóc, đau khổ và tuyệt vọng Christine đã cầu cứu nhiều nơi và mong có phép màu nào đó sẽ xảy ra .&nbsp; Nhưng khi cậu bé mà sở cảnh sát mang trả cho cô, thì linh tính của người mẹ trong người Christine mách bảo với cô rằng đứa bé ấy không phải là đứa con mà cô hết mực yêu thương. .Và cuộc hành trình đi tìm lại đứa con yêu dấu của mình đã đẩy cô vào nhiều tình thế tồi tệ khi không một ai tin những gì cô nói...</p>', 'Full', 1, 'single', 'completed', 13, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Jason Butler Harner","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Geoff Pierson","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Frank Wood","avatar":""},{"name":"Peter Gerety","avatar":""},{"name":"Reed Birney","avatar":""},{"name":"Gattlin Griffith","avatar":""},{"name":"Michelle Gunn","avatar":""},{"name":"Jan Devereaux","avatar":""},{"name":"Erica Grant","avatar":""},{"name":"Antonia Bennet","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324486);
