INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-hoai-nghi', 'Sự Hoài Nghi', 'Changeling', 'sự hoài nghi changeling angelina jolie john malkovich jeffrey donovan michael kelly colm feore jason butler harner amy ryan geoff pierson denis o''hare frank wood peter gerety reed birney gattlin griffith michelle gunn jan devereaux erica grant antonia bennet ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-ky-la-cua-benjamin', 'Cuộc Đời Kỳ Lạ Của Benjamin', 'The Curious Case of Benjamin Button', 'https://phimimg.com/upload/vod/20231020-1/1666b28e24d15e27da8bf25930b99dad.jpg', 'https://phimimg.com/upload/vod/20231020-1/1669f6471728d0cf1cc612337b5b1957.jpg', '<p>Phim kể về Benjamin Button (Brad Pitt), một người sinh ra đã không được bình thường như những đứa trẻ khác khi dáng vẻ bề ngoài của anh là một ông già 80 tuổi. Bị bỏ rơi tại trước cửa viện dưỡng lão bởi người cha Thomas Button, Benjamin trải qua những tháng ngày đầu đời cơ cực và đau đớn tại đây, trước khi anh dần dần trẻ lại từng ngày. Anh yêu một nữ diễn viên ballet tên Daisy (Cate Blanchett), và vấn đề bắt đầu rắc rối khi anh thì cứ trẻ ra, còn cô thì ngày một già đi. Hình ảnh một đôi tình nhân đang yêu nhau say đắm bỗng chốc trở thành một đứa trẻ bi bô và một người già nhăn nheo gầy yếu đã gợi nhiều cảm xúc thương yêu, khiến ta phải ngẫm nghĩ nhiều hơn về tình yêu và những giá trị vượt khỏi quy luật thời gian của cuộc đời mình. Người xem sẽ cùng dõi theo cuộc phiêu lưu của Benjamin trong quá trình tìm hiểu cuộc sống, chiến tranh, cảm nhận tình yêu và đối mặt với những nỗi buồn chia ly...</p>', 'Full', 1, 'single', 'completed', 14, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Julia Ormond","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Phyllis Somerville","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Faune Chambers","avatar":""},{"name":"Donna DuPlantier","avatar":""},{"name":"Jacob Tolano","avatar":""},{"name":"Earl Maddox","avatar":""},{"name":"Ed Metzger","avatar":""},{"name":"Danny Vinson","avatar":""},{"name":"David Jensen","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324486);
