INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-doi-ky-la-cua-benjamin', 'Cuộc Đời Kỳ Lạ Của Benjamin', 'The Curious Case of Benjamin Button', 'cuộc đời kỳ lạ của benjamin the curious case of benjamin button brad pitt cate blanchett taraji p. henson julia ormond jason flemyng mahershala ali jared harris elias koteas phyllis somerville tilda swinton faune chambers donna duplantier jacob tolano earl maddox ed metzger danny vinson david jensen j ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-khong-lo-xanh-phi-thuong', 'Người Khổng Lồ Xanh Phi Thường', 'The Incredible Hulk', 'https://phimimg.com/upload/vod/20231020-1/f8f30edce05a0ef3495f9d6b65dbd0e1.jpg', 'https://phimimg.com/upload/vod/20231020-1/d032a0422019279076885d8b41c2cd2e.jpg', '<p>Sau nhiều năm bị biến thành kẻ nửa người nửa quái vật The Hulk, nhà khoa học Bruce Banner vẫn phải lần trốn trong rừng rậm Nam Mỹ, tìm cách chữa trị cho chính bản thân mình. Cùng lúc đó anh vẫn bị sự truy lùng của quân đội Mỹ, dẫn dắt bởi tướng Ross và tên Emil Blonsky, kẻ muốn sử dụng sức mạnh của The Hulk. Chính tên này sau đó đã tự lặp lại tai nạn của Bruce Banner, với hy vọng biến mình thành siêu nhân. Nhưng Emil phát hiện ra rằng hắn bị biến thành một con quái vật - the Abomination- và không bao giờ trở lại thành dạng người như Bruce được nữa. Đổ lỗi cho Bruce vì sự đột biến của mình, hắn truy sát anh để trả thù.</p>', 'Full', 1, 'single', 'completed', 12, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edward Norton","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Christina Cabot","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Lou Ferrigno","avatar":""},{"name":"Paul Soles","avatar":""},{"name":"Débora Nascimento","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Chris Owens","avatar":""},{"name":"Al Vrkljan","avatar":""},{"name":"Adrian Hein","avatar":""},{"name":"John MacDonald","avatar":""},{"name":"Shaun McComb","avatar":""},{"name":"Simon Wong","avatar":""},{"name":"Pedro Sa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành 