INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-be-mang-pyjama-soc', 'Chú Bé Mang Pyjama Sọc', 'The Boy in the Striped Pyjamas', 'https://phimimg.com/upload/vod/20231020-1/4f4e8d3b95aa373b0cd3302a8b979f63.jpg', 'https://phimimg.com/upload/vod/20231020-1/fc072698f3d185e2d0d67052136513af.jpg', '<p>Tác phẩm kể lại câu chuyện kinh hoàng của một trại giam tù binh của Đức Quốc xã qua góc nhìn của cậu bé 8 tuổi - Bruno (Asa Butterfield), là con trai của chỉ huy Đức Quốc xã ở trại và Shmuel - một cậu bé tù nhân người Do Thái. Bộ phim đã nhận nhiều chỉ trích của các nhà giáo dục vì những chi tiết không xác thực so với thực tế, và về những tình huống ghi nhận sự cảm thông với gia đình Đức Quốc xã - trung tâm của câu chuyện mà bỏ qua những nạn nhân người Do Thái đáng thương phải chịu sự đày đọa và cái chết thương tâm.</p>', 'Full', 1, 'single', 'completed', 24, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Asa Butterfield","avatar":""},{"name":"Jack Scanlon","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"David Hayman","avatar":""},{"name":"Sheila Hancock","avatar":""},{"name":"Cara Horgan","avatar":""},{"name":"Richard Johnson","avatar":""},{"name":"Amber Beattie","avatar":""},{"name":"Zac Mattoon O''Brien","avatar":""},{"name":"Charlie Baker","avatar":""},{"name":"Jim Norton","avatar":""},{"name":"Domonkos Németh","avatar":""},{"name":"Henry Kingsmill","avatar":""},{"name":"Zsuzsa Holl","avatar":""},{"name":"Lászl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 