INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-ky-si-bong-dem', 'Người Dơi: Kỵ Sĩ Bóng Đêm', 'The Dark Knight', 'https://phimimg.com/upload/vod/20231018-1/ed5564edd98ab92763a06ce477ef4b5d.jpg', 'https://phimimg.com/upload/vod/20231018-1/a41308af925ad176a3e88b90e4c5d6e8.jpg', '<p>Người Dơi bước vào giai đoạn cam go nhất trong cuộc chiến chống lại cái ác khi tên tội phạm bậc thầy The Joker xuất hiện. Các tay trùm thuê The Joker giết Người Dơi để trả thù cho chỗ tài sản phi pháp bị anh lật tẩy. Tiếp tay cho The Joker là toàn bộ tội phạm ở thành phố Gotham, những kẻ đang bị bộ ba Người Dơi - Trung úy Gordon - Luật sư Harvey Dent thu hẹp đất sống. Hàng loạt vụ tấn công xảy ra khiến Người Dơi lúng túng. Các quan chức bị sát hại, người dân không dám ra đường buổi tối vì sợ bị giết, mọi lối ra vào thành phố Gotham bị phong tỏa. Tất cả đều do một tay The Joker sắp đặt.</p>', 'Full', 1, 'single', 'completed', 16, 2008, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Heath Ledger","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Maggie Gyllenhaal","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Nestor Carbonell","avatar":""},{"name":"Monique Gabriela Curnen","avatar":""},{"name":"Ron Dean","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Keith Szarabajka","avatar":""},{"name":"Joshua Harto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac