INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-lam-nguoi-xau-phan-1', 'Tập làm người xấu (Phần 1)', 'Breaking Bad (Season 1)', 'https://phimimg.com/upload/vod/20231006-1/5dbbc14cf454238c216dcf3f72426a6c.jpg', 'https://phimimg.com/upload/vod/20231006-1/ccc6cb4b5bef00d2289a95397465893b.jpg', '<p>Một giáo viên dạy hóa ở trường trung học mắc bệnh ung thư bắt tay với một cựu học sinh để bảo vệ tương lai của gia đình bằng cách sản xuất và bán ma túy đá.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 24, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bryan Cranston","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Anna Gunn","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Betsy Brandt","avatar":""},{"name":"RJ Mitte","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Steven Michael Quezada","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Giancarlo Esposito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324486);
