INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-1', 'Diệp Vấn 1', 'Ip Man', 'https://phimimg.com/upload/vod/20231004-1/97ac5e937523a4ed84270bb5ab73958c.jpg', 'https://phimimg.com/upload/vod/20231004-1/834a7a0473c47f287bf8e848b6750095.jpg', '<p>Vào năm 1937, chiến tranh bùng nổ, và quân Nhật nhanh chóng chiếm đóng Phật Sơn. Diệp gia bị niêm phong, Diệp Vấn cũng vợ con phải chuyển đến một căn nhà lụp xụp; anh phải đi xúc than để kiếm miếng ăn cho gia đình. Tên tướng Nhật là Miura bị ám ảnh bởi võ thuật, và dùng lương thực để thưởng cho những trận đấu võ giữa người dân và quân lính của hắn. Vài người bạn của Diệp Vấn không kiềm chế được và xin tham gia. Lam võ khùng vốn có lòng tự tôn dân tộc rất cao, không hề sợ hãi lao lên thách thức Miura nhưng đã phải trả giá bằng tính mạng của mình. Ngày hôm sau, chứng kiến thêm cái chết của Lưu sư phụ, Diệp Vấn nổi cơn thịnh nộ và hạ gục 10 tên lính nhật trong một lượt đấu.</p>', 'Full', 1, 'single', 'completed', 25, 2008, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Lynn Hung","avatar":""},{"name":"Hiroyuki Ikeuchi","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Fan Siu-wong","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Wong Yau-Nam","avatar":""},{"name":"Dennis To Yue-Hong","avatar":""},{"name":"Calvin Cheng Ka-Sing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324486);
