INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-bo-gap-me-phan-4', 'Khi Bố Gặp Mẹ (Phần 4)', 'How I Met Your Mother (Season 4)', 'https://phimimg.com/upload/vod/20231001-1/9f673477846ef6579f7022729dacfa20.jpg', 'https://phimimg.com/upload/vod/20231001-1/46583217582c698808294c64cef9fc6a.jpg', '<p>Tiếp tục với mùa 4 “Khi Bố Gặp Mẹ” đầy hài hước. Mọi chuyện bắt đầu khi người bạn thân nhất của Ted, Marshall, tiết lộ rằng anh ta sẽ cầu hôn người bạn gái lâu năm của mình, và bây giờ là vợ, Lily, một giáo viên mẫu giáo.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Cristin Milioti","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324486);
