INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('indiana-jones-va-vuong-quoc-so-nguoi', 'Indiana Jones và Vương Quốc Sọ Người', 'Indiana Jones and the Kingdom of the Crystal Skull', 'https://phimimg.com/upload/vod/20230925-1/efaa442e9a45246b349300dd79881d5e.jpg', 'https://phimimg.com/upload/vod/20230925-1/263f65107fde1514f7f4b6653652f2c3.jpg', '<p>Lấy bối cảnh năm 1957, 19 năm sau khi Indiana Jones và cuộc viễn chinh cuối cùng ra mắt, phim kể về cuộc chuyến phiêu lưu mới nhất của nhà thám hiểm dũng cảm. Lần này, ông phải tìm ra Crystal Skull (sọ pha lê), một đồ vật bí hiểm có nguồn gốc từ ngoài hành tinh chứa đựng sức mạnh khủng khiếp.</p>', 'Full', 1, 'single', 'completed', 19, 2008, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Karen Allen","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Igor Jijikine","avatar":""},{"name":"Dimitri Diatchenko","avatar":""},{"name":"Ilia Volok","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324486);
