INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-luu-tinh-duc', 'Phiêu Lưu Tình Dục', 'À l’aventure', 'https://phimimg.com/upload/vod/20230922-1/42e3690a393d5c4e354996ceb3940b3a.jpg', 'https://phimimg.com/upload/vod/20230922-1/6fa7e7d3d2263c198017300b0bf9512a.jpg', '<p>Chán nản với lối sống hiện tại và đặc biệt hơn là không được thỏa mãn về mặt tình dục với bạn trai Fred, Sandrine quyết định tìm một con đường mới trong cuộc sống. Bị hấp dẫn bởi người bạn Sophie, người đã kể cho cô nghe về những trải nghiệm tình dục của mình, qua nhiều cuộc gặp gỡ khác nhau, cô sẽ tìm thấy những niềm vui mới và trải nghiệm mới, dù là về thể chất hay tinh thần.</p>', 'Full', 1, 'single', 'completed', 19, 2008, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Carole Brana","avatar":""},{"name":"Lise Bellynck","avatar":""},{"name":"Jocelyn Quivrin","avatar":""},{"name":"Arnaud Binard","avatar":""},{"name":"Nadia Chibani","avatar":""},{"name":"Etienne Chicot","avatar":""},{"name":"Estelle Galarme","avatar":""},{"name":"Frederic Aspisi","avatar":""},{"name":"Michèle Larue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324486);
