INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-ret-gio-lanh-chet-choc', 'Gió Rét (Gió Lạnh Chết Chóc)', 'Wind Chill', 'https://phimimg.com/upload/vod/20260701-1/c514a280d7634ca561859c73218ac299.jpg', 'https://phimimg.com/upload/vod/20260701-1/b98fe73639574d68ddce9584f80e3fa3.jpg', '<p>Trên đường lái xe về nhà dịp nghỉ lễ, hai sinh viên đại học bị hỏng xe giữa một con đường vắng vẻ, nơi linh hồn của những người đã chết tại đó quay lại ám ảnh họ.</p>', 'Full', 1, 'single', 'completed', 63, 2007, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"Ashton Holmes","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"Ian A. Wallace","avatar":""},{"name":"Donny Lucas","avatar":""},{"name":"Chelan Simmons","avatar":""},{"name":"Darren Moore","avatar":""},{"name":"Linden Banks","avatar":""},{"name":"Caz Odin Darko","avatar":""},{"name":"Heath Horejda","avatar":""},{"name":"Ian Thompson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Estrada Maldita","Mrozny wiatr","Eglovismenoi","Egklovismenoi","Egklobismenoi","Escalofrío","Lamentos en el viento","Wind Chill - Der eisige Tod","デス・ロード　染血","Wind Chill"]', 1784690324486);
