INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-dua-tin-nhung-loi-canh-bao', 'Những Người Đưa Tin (Những Lời Cảnh Báo)', 'The Messengers', 'https://phimimg.com/upload/vod/20260618-1/3353dcc23551c657dfc87d5f4d0600e6.jpg', 'https://phimimg.com/upload/vod/20260618-1/1416c9f27351dd21896d11956471bba2.jpg', '<p>Khi gia đình Solomon quyết định từ bỏ cuộc sống xô bồ, náo nhiệt nơi thành thị để đổi lấy sự yên bình tại một trang trại ở Bắc Dakota, họ không thể ngờ rằng một cơn ác mộng kinh hoàng đang chờ đón phía trước. Ngay sau khi chuyển đến, cô con gái tuổi teen Jess và cậu em trai nhỏ liên tục nhìn thấy những bóng ma đáng sợ, đồng thời phải hứng chịu các cuộc tấn công dữ dội từ một thế lực siêu nhiên bí ẩn. Jess buộc phải tìm cách cảnh báo cho gia đình vốn đang hoài nghi của mình trước khi quá muộn để giải cứu họ.</p>', 'Full', 1, 'single', 'completed', 38, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"Penelope Ann Miller","avatar":""},{"name":"John Corbett","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"William B. Davis","avatar":""},{"name":"Evan Turner","avatar":""},{"name":"Theodore Turner","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Michael Daingerfield","avatar":""},{"name":"Tatiana Maslany","avatar":""},{"name":"Shirley McQueen","avatar":""},{"name":"Anna Hagan","avatar":""},{"name":"Blaine Hart","avatar":""},{"name":"Graham B","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-