INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-he-cua-coo', 'Ngày Hè Của Coo', 'Summer Days With Coo', 'https://phimimg.com/upload/vod/20260616-1/f7f348f50155b81d126f56628b150b43.jpg', 'https://phimimg.com/upload/vod/20260616-1/097b02026d869fc71065815439b9db9c.jpg', '<p>Một chú Kappa nhỏ bé, đơn độc đã sống sót một cách kỳ diệu qua hơn 200 năm để đến với nước Nhật hiện đại, nơi cậu được cậu bé Koichi tìm thấy. Được gia đình Koichi bí mật nhận nuôi và đặt tên là Coo, chú Kappa cùng người bạn con người mới của mình bắt đầu hành trình tìm kiếm những vùng đất hoang sơ, chưa có dấu chân người, với hy vọng mong manh sẽ tìm lại được những đồng loại còn sống sót của mình.a</p>', 'Full', 1, 'hoathinh', 'completed', 32, 2007, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazato Tomizawa","avatar":""},{"name":"Takahiro Yokokawa","avatar":""},{"name":"Naoki Tanaka","avatar":""},{"name":"Tamaki Matsumoto","avatar":""},{"name":"Ken''ichi Nagira","avatar":""},{"name":"Nanako Hirata","avatar":""},{"name":"Kyousuke Ikeda","avatar":""},{"name":"Kazuki Matsuoka","avatar":""},{"name":"Souta Murakami","avatar":""},{"name":"Saki Yoshihara","avatar":""},{"name":"Kereo Yoshita","avatar":""},{"name":"Naomi Nishida","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["跟河童小酷的暑假时光","החופש הגדול עם קו","Kappa no Kū to Natsuyasumi","Grandes vacances avec Coo le kappa","Летние дни с Каппой","Ein Sommer mit Coo","El vera