INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cua-siam', 'Tình yêu của Siam', 'Love of Siam', 'https://phimimg.com/upload/vod/20260607-1/bd57d2bb2e3d96a23fd09800819a481d.jpg', 'https://phimimg.com/upload/vod/20260607-1/e92c1a43d2347a3204faa689f41df582.jpg', '<p>Hai cậu bé là bạn thân sống cuộc sống gia đình yên bình ở Bangkok. Cuộc sống của họ bị xáo trộn khi chị gái của một cậu bé mất tích trong chuyến đi rừng. Gia đình tan vỡ chuyển đi, chia cắt hai cậu bé. Nhiều năm sau, giờ đã ở tuổi thiếu niên, hai cậu bé gặp lại nhau. Một trong số họ hiện là trưởng nhóm của một nhóm nhạc nam đầy tham vọng có trợ lý quản lý rất giống với người chị gái đã mất. Hai cậu bé phải đối mặt với gia đình, cuộc sống xã hội và tình cảm của họ dành cho nhau.</p>', 'Full', 1, 'single', 'completed', 32, 2007, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Witwisit Hiranyawongkul","avatar":""},{"name":"Mario Maurer","avatar":""},{"name":"Chermarn Boonyasak","avatar":""},{"name":"Sinjai Plengpanich","avatar":""},{"name":"Songsit Roongnophakunsri","avatar":""},{"name":"Pimpan Buranapim","avatar":""},{"name":"Narinchot Wachirathonniyomkul","avatar":""},{"name":"Jirayu La-ongmanee","avatar":""},{"name":"Kanya Rattanapetch","avatar":""},{"name":"Chanidapa Pongsilpipat","avatar":""},{"name":"Pongnarin Ulice","avatar":""},{"name":"Jarunee Boonsake","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Rak haeng Siam","The Love of Siam","暹罗之恋","Love of Siam","รักแห่งสยาม"]', 1784690324486);
