INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-4', 'Chuyện Văn Phòng (Phần 4)', 'The Office (Season 4)', 'https://phimimg.com/upload/vod/20260604-1/46ede0239caea2517ee47f44d177d2a7.jpg', 'https://phimimg.com/upload/vod/20260604-1/42098e63bbfb343a3ff17b71497dad52.jpg', '<p>Phần bốn đánh dấu sự ra đi của Karen Filippelli với tư cách là một nhân vật bình thường, mặc dù cô ấy xuất hiện vài giây trong tập đầu tiên, Fun Run và trong tập thứ sáu, Branch Wars, với tư cách là giám đốc khu vực của chi nhánh Utica. Các mối quan hệ một lần nữa nổi lên như chủ đề chính của mùa giải, với sự nổi lên của Jim Halpert và Pam Beesley, còn của Michael Scott và Jan Levinson, cũng như sự suy giảm của Dwight Schrute và Angela Martin. Công nghệ là một chủ đề phổ biến khác khi các nhân viên văn phòng phải vật lộn với các sáng kiến do Ryan Howard đưa ra nhằm hiện đại hóa công ty.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 27, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324486);
