INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-7', 'Thị Trấn Smallville (Phần 7)', 'Smallville (Season 7)', 'https://phimimg.com/upload/vod/20250604-1/fbb8c9319736a944435dc48de187fef0.jpg', 'https://phimimg.com/upload/vod/20250604-1/1bc137099ce8435ef2f3957bcbfe59f2.jpg', '<p>Khi Kara, em họ của Clark xuất hiện, Clark khuyên cô nên giữ kín thân phận và học cách kiểm soát sức mạnh của mình. Nhưng Kara lại có ý định khác và nhanh chóng trở thành mục tiêu cho tham vọng quyền lực của Lex Luthor. Đồng thời, giờ đây có hai Clark Kent: một người là chàng trai trẻ sống tại thị trấn nhỏ ở Kansas, đang dần bước đi trên con đường định mệnh của mình; người còn lại là Bizarro — kẻ mang cùng DNA với Clark nhưng lại không chia sẻ những giá trị đạo đức của anh. Lane có bước tiến lớn trong sự nghiệp, còn Chloe Sullivan nhận ra rằng việc cân bằng giữa sức mạnh từ thiên thạch và cuộc sống cá nhân không hề dễ dàng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324486);
