INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-am-sau-cuoc-yeu', 'Dư Âm Sau Cuộc Yêu', 'After Sex', 'https://phimimg.com/upload/vod/20260525-1/043cc75c0a4da3a6969d1dc9e337dfce.jpg', 'https://phimimg.com/upload/vod/20260525-1/366d677472f062021dac68e0a5a8d89f.jpg', '<p>Tình dục được sử dụng làm phông nền để mổ xẻ những góc khuất về sự thân mật và tổn thương của con người. Bộ phim đi sâu vào những khía cạnh phức tạp của các mối quan hệ thời hiện đại thông qua câu chuyện của tám cặp đôi hoàn toàn riêng biệt. Bằng những đoạn hội thoại chân thực cùng các tình huống trớ trêu đầy nhạy cảm, tác phẩm dẫn dắt người xem đi từ chương đầu khởi nguồn cho đến những dư chấn hậu tan vỡ của một cuộc tình, đồng thời xem xét từng giai đoạn chuyển biến ở giữa – nơi ta có thể nhìn thấy những khoảnh khắc hài hước đan xen trong bi kịch, những nỗi đau thắt lòng và cả sự hoang mang tột cùng của tình yêu.</p>', 'Full', 1, 'single', 'completed', 29, 2007, 'Vietsub', '', 'Âu Mỹ', 0, '[{"name":"Marc Blucas","avatar":""},{"name":"Jose Pablo Cantillo","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"James DeBello","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Natalie Elizabeth Marston","avatar":""},{"name":"Jeanette O''Connor","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Tanc Sade","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Timm Sharp","avatar":""},{"name":"Charity She","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37