INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-cua-nhung-giac-mo-cua-chung-ta', 'Giai điệu Của Những Giấc Mơ Của Chúng Ta', 'The Tune Of Our Dreams', 'https://phimimg.com/upload/vod/20260513-1/2e42ac84fe093f63198754e936f2e9ac.jpg', 'https://phimimg.com/upload/vod/20260513-1/70851f29de0116ab0fc883d638daa1b1.jpg', '<p>Yasu chơi guitar trên phố mỗi đêm. Một chàng trai trẻ xa lạ, Dare, đứng trước mặt anh. Yasu ngay lập tức cảm thấy hơi say mê Dare, người luôn thẳng thắn bày tỏ quan điểm của mình, và đưa anh về căn hộ của mình, nơi anh không còn nơi nào để trở về. Căn phòng lúc này đang có sự hiện diện của hai người bạn của Yasu là Otto và Bohra, một cặp đôi hài hước, và Sekken, người làm việc bán thời gian với Yasu và có ước mơ trở thành một nhân viên toàn thời gian. Dare cảm thấy thoải mái trong bầu không khí này. Yasu bảo anh ở lại bao lâu tùy thích. Và chẳng mấy chốc, tình cảm của cô dành cho anh ngày càng sâu đậm.</p>', 'Full', 1, 'single', 'completed', 23, 2007, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomohiro Okada","avatar":""},{"name":"松浦祐也","avatar":""},{"name":"Takami Kazumasa","avatar":""},{"name":"横須賀正一","avatar":""},{"name":"中村公彦","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Otoko-tachi no yume neiro","男たちの夢音色"]', 1784690324486);
