INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-o-nga-tu-duong', 'Tình Yêu ở Ngã Tư đường', 'Love In The Crossroads', 'https://phimimg.com/upload/vod/20260513-1/8b8a89e74219098c254cba7913d76128.jpg', 'https://phimimg.com/upload/vod/20260513-1/34035b505ee3c75d8736484f1b8ee39a.jpg', '<p>Shingo mơ ước trở thành nhiếp ảnh gia tin tức và hiện đang làm quay phim AV. Anh sống một cuộc đời phần lớn theo đuổi ước mơ của riêng mình, và bị Mio, người đang sống cùng anh, bỏ rơi. Sau đó, Shingo thấy một thông báo tuyển dụng nhiếp ảnh gia với mức lương khủng, liền đến phỏng vấn và ngay lập tức được nhận. Nhiệm vụ là quay một đoạn video riêng tư về Nakajima...</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shinji Yamaguchi","avatar":""},{"name":"樹かず","avatar":""},{"name":"横須賀正一","avatar":""},{"name":"野村貴浩","avatar":""},{"name":"本多菊次朗","avatar":""},{"name":"Itsuka Harusaki","avatar":""},{"name":"Mari Hoshizawa","avatar":""},{"name":"Kôji Makimura","avatar":""},{"name":"池島ゆたか","avatar":""},{"name":"ムーミン","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sôai no kurosurôdo","奏愛のクロスロード"]', 1784690324486);
