INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ship-hang-cho-dai-ca', 'Ship Hàng Cho Đại Ca', 'Teng-Nong', 'https://phimimg.com/upload/vod/20260513-1/3885980aeb95dc54e4227a53f5558d0d.jpg', 'https://phimimg.com/upload/vod/20260513-1/5965187d471b0d54478adfe38a2c9792.jpg', '<p>Đang thực hiện một nhiệm vụ giao hàng đơn giản cho tay trùm băng đảng, hai anh bạn hậu đậu lại quyết định đi đường tắt và vô tình lọt vào tầm ngắm của cảnh sát — cùng một sát thủ máu lạnh. Từ một công việc tưởng chừng dễ dàng, cả hai bỗng chốc rơi vào cuộc truy đuổi nghẹt thở, nơi họ vừa phải tìm cách cắt đuôi lực lượng chức năng, vừa phải trốn thoát khỏi lưỡi hái tử thần của kẻ ám sát chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 24, 2007, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Choosak Iamsuk","avatar":""},{"name":"Jirada Yohara","avatar":""},{"name":"Phairoj Jaising","avatar":""},{"name":"Andy Kempimok","avatar":""},{"name":"Isara Isarangkul Na Ayutthaya","avatar":""},{"name":"Ittiphon Suriyarungchot","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Somchai Kemklad","avatar":""},{"name":"Thatsarot Phuangrot","avatar":""},{"name":"Thawon Yimpenyowng","avatar":""},{"name":"Kittisak Chusri","avatar":""},{"name":"Sudarat Butrprom","avatar":""},{"name":"Pun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Teng Nong Khon Maha Hia","Teng Nong","เท่งโหน่งคนมาหาเฮีย","เท่ง โหน่ง คนมาหาเฮีย"]', 1784690324486);
