INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-mot-dem-dinh-bau', 'Tình Một Đêm (Dính Bầu)', 'Knocked Up', 'https://phimimg.com/upload/vod/20260509-1/f688efaf9aa76093eac7358d24b9b101.jpg', 'https://phimimg.com/upload/vod/20260509-1/c126fa8afcd3c31d90f943df8f277562.jpg', '<p>Cuộc đời êm đẹp của phóng viên mảng giải trí Alison Scott (Katherine Heigl đóng) bỗng đảo lộn khi cô gặp và qua đêm với anh chàng Ben Stone (Seth Rogen đóng). Ben là một kẻ phất phơ, hoàn toàn khác với cô về lối sống, lý tưởng, hoài bão. Đối mặt với việc phải một mình vượt cạn mà lại không nỡ bỏ thai, Alison đã quay lại tìm cha đứa bé. Chàng Ben cũng phải tự quyết định: ra đi hoặc ở lại với mẹ con họ. Sự nghi ngại giữa hai người ngày càng lớn, khi mỗi ngày trôi qua, họ càng thấy đối phương và mẫu người trong mộng của mình khác nhau một trời một vực. Họ đã trải qua 9 tháng vò đầu bứt tai tìm đáp án cho câu hỏi: điều gì làm nên một cuộc sống chung suốt đời hạnh phúc? Sau The 40-Year-Old-Virgin, Judd Apatow lại gây bất ngờ ...</p>', 'Full', 1, 'single', 'completed', 24, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"Katherine Heigl","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Lo Mutuc","avatar":""},{"name":"Iris Apatow","avatar":""},{"name":"Maude Apatow","avatar":""},{"name":"Joanna Kerns","avatar":""},{"name":"Harold Ramis","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Tim Bagley","avatar":""},{"name":"Loudon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ligeramente embarazada","Lío embarazoso","Knocked Up 1","Ligeiramente grávidos","意外之孕","好孕臨門","Ligeramente Embarazada","Немножко беременна","Beim ersten Mal - Knocked Up","사고친 후에","Smelt på tjukka","Beim ersten Mal","無ケーカクの命中男／ノックトアップ","無ケーカクの命中男 ノックトアップ","Трошки вагітна","En cloque, mode d''emploi","Knocked Up"]', 1784690324486);
