INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-mot-dem-dinh-bau', 'Tình Một Đêm (Dính Bầu)', 'Knocked Up', 'tình một đêm (dính bầu) knocked up seth rogen katherine heigl paul rudd leslie mann jason segel jay baruchel jonah hill martin starr lo mutuc iris apatow maude apatow joanna kerns harold ramis alan tudyk kristen wiig bill hader ken jeong craig robinson tim bagley loudon ligeramente embarazada lío embarazoso knocked up 1 ligeiramente grávidos 意外之孕 好孕臨門 ligeramente embarazada немножко беременна beim ersten mal - knocked up 사고친 후에 smelt på tjukka beim ersten mal 無ケーカクの命中男／ノックトアップ 無ケーカクの命中男 ノックトアップ трошки вагітна en cloque, mode d''emploi knocked up', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-toi-phan-4', 'Giải Cứu Tôi (Phần 4)', 'Rescue Me (Season 4)', 'https://phimimg.com/upload/vod/20260428-1/0c95ae89f6c52cbd0484f63273616650.jpg', 'https://phimimg.com/upload/vod/20260428-1/5237cf8816cc09a4fd6fa36e4520fae1.jpg', '<p>Hậu quả của sự kiện 11/9 đã để lại những vết sẹo tâm lý sâu sắc cho những người lính cứu hỏa thuộc Sở Cứu hỏa Thành phố New York (FDNY), và không ai phải chịu đựng nhiều hơn Tommy Gavin. Vừa ly thân với vợ và ba đứa con, Tommy chênh vênh giữa nỗi đau và sự giận dữ khi cố gắng rũ bỏ những cơn ác mộng đeo bám về những đồng đội đã hy sinh, đặc biệt là người anh họ quá cố Jimmy Keefe. Làm việc bên cạnh những người đồng đội kỳ cựu như Trung úy &quot;Lou&quot; Shea, Franco Rivera, Sean Garrity và lính mới Mike Lombardi, Tommy phải chiến đấu với cơn nghiện rượu và ma túy để nỗ lực giữ vững bản sắc quan trọng nhất của mình: một người lính cứu hỏa thực thụ của New York.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 23, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Denis Leary","avatar":""},{"name":"Adam Ferrara","avatar":""},{"name":"Andrea Roth","avatar":""},{"name":"John Scurti","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"Michael Lombardi","avatar":""},{"name":"Steven Pasquale","avatar":""},{"name":"Larenz Tate","avatar":""},{"name":"Callie Thorne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["火线救援","Rescue Me - Salvami","レスキュー・ミー ニューヨークのえいゆうたち","レスキュー・ミー ～ NYの英雄たち","Rescue Me: FDNY","Rescue Me"]', 1784690324486);
