INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-rock-phan-2', '30 Rock (Phần 2)', '30 Rock (Season 2)', 'https://phimimg.com/upload/vod/20260501-1/2ecbb1708c891ace57a73f364408187d.jpg', 'https://phimimg.com/upload/vod/20260501-1/4373c9fe490f37f9e531a3b973c78219.jpg', '<p>Show bắt đầu thành công hơn, nhưng áp lực tăng lên. Liz cố tìm sự ổn định trong tình cảm nhưng liên tục thất bại. Trong khi đó, Jack phải đối mặt với gia đình quyền lực của mình, cho thấy lý do anh ám ảnh với thành công. Mối quan hệ giữa Liz và Jack dần chuyển từ xung đột sang hỗ trợ lẫn nhau.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 20, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Maulik Pancholy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 ROCK サーティー･ロック","サーティー･ロック","30 락","30락","30록","30 Rock"]', 1784690324486);
