INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-dai-su-phu', 'Tam Đại Sư Phụ', 'Master KIMs', 'https://phimimg.com/upload/vod/20260420-1/d19174fa1ee07038dd040ad90b7d8d6a.jpg', 'https://phimimg.com/upload/vod/20260420-1/f2c23eaacc8288d27d922277abb2c325.jpg', '<p>Hai sư phụ Kim ghét nhau chẳng qua là vì họ cùng yêu con gái của ông chủ tiệm mì: nàng Liên Thục giỏi giang và xinh đẹp. Nhưng giữa lúc cuộc chiến giữa Kim quán trưởng 1 và Kim quán trưởng 2 đang diễn ra gây cấn thì bỗng xuất hiện Kim quán trưởng 3. Người này là một cao thủ Kungfu, vừa đẹp trai hào hoa lại vừa đàn hay hát giỏi. Ông chủ tiệm mì vô cùng khó xử vì con gái thì chỉ có một mà lại có đến ba Kim quán trưởng. Cuối cùng ông quyết định mở một cuộc thi để kén rể...</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Hyun-jun","avatar":""},{"name":"Choi Sung-kook","avatar":""},{"name":"Kwon Oh-joong","avatar":""},{"name":"Oh Seung-hyun","avatar":""},{"name":"Noh Joo-hyun","avatar":""},{"name":"Jeong Jun-ha","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Kim Byung-man","avatar":""},{"name":"Cho Won-hee","avatar":""},{"name":"Moon Won-ju","avatar":""},{"name":"Baek Bong-ki","avatar":""},{"name":"Tak Jae-hoon","avatar":""},{"name":"Kwon Oh-Min","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Kim-gwanjang dae Kim-gwanjang dae Kim-gwanjang","Three Kims","김관장 대 김관장 대 김관장"]', 1784690324486);
