INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-con-mot-chu-tinh-chi-tinh-yeu-cuu-duoc-tinh-yeu', 'Chỉ Còn Một Chữ Tình (Chỉ Tình Yêu Cứu Được Tình Yêu)', 'Reign Over Me', 'https://phimimg.com/upload/vod/20260414-1/983123771ea013e12de5a61e8fac6889.jpg', 'https://phimimg.com/upload/vod/20260414-1/2685b4fb7745e7de700e32df0e13aed7.jpg', '<p>Cuộc gặp tình cờ với Alan Johnson (Don Cheadle), người bạn thời sinh viên đã xáo trộn cuộc sống Charlie, buộc anh phải đối diện với thực tại để có thể tìm ra cách trở lại cuộc sống bình thường. Chính Alan, đang từ một người con chu đáo, người chồng thủy chung, người cha mẫu mực, bỗng có những hành trạng thất thường, đi sớm về khuya, sa vào những phiền toái các kiểu, vì Charlie. Alan không thể đành tâm nhìn bạn chỉ nhăm nhăm trốn chạy, giấu mình trong ngôi nhà lạnh ngắt như hang ổ của con thú bị trọng thương, chỉ với game và máy nghe nhạc…</p>', 'Full', 1, 'single', 'completed', 24, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Robert Klein","avatar":""},{"name":"Melinda Dillon","avatar":""},{"name":"Mike Binder","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Rae Allen","avatar":""},{"name":"Paula Newsome","avatar":""},{"name":"John de Lancie","avatar":""},{"name":"Paul Butler","avatar":""},{"name":"Camille LaChe Smith","avatar":""},{"name":"Imani Hakim","avatar":""},{"name":"Denise Dowse","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["La Esperanza Vive en Mi","À coeur ouvert","Reign Over Me"]', 1784690324486);
