INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chi-con-mot-chu-tinh-chi-tinh-yeu-cuu-duoc-tinh-yeu', 'Chỉ Còn Một Chữ Tình (Chỉ Tình Yêu Cứu Được Tình Yêu)', 'Reign Over Me', 'chỉ còn một chữ tình (chỉ tình yêu cứu được tình yêu) reign over me adam sandler don cheadle jada pinkett smith liv tyler saffron burrows donald sutherland robert klein melinda dillon mike binder jonathan banks rae allen paula newsome john de lancie paul butler camille lache smith imani hakim denise dowse la esperanza vive en mi à coeur ouvert reign over me', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('24-gio-chong-khung-bo-phan-6', '24 Giờ Chống Khủng Bố (Phần 6)', '24 (Season 6)', 'https://phimimg.com/upload/vod/20260407-1/37b5bb0573f48b3261efcae0ef8abcb0.jpg', 'https://phimimg.com/upload/vod/20260407-1/d802ae70a40a03a7624e8989a03e6dc9.jpg', '<p>Đặc vụ Bauer làm việc cho tổ chức Counter Terrorist Unit (tạm dịch là Đơn vị chống khủng bố) &nbsp;tại Los Angeles. Bauer là một đặc vụ đầy kinh nghiệm và thành thạo &nbsp;trong cách tiếp cận cũng như tra khảo những đối tượng khủng bố nguy &nbsp;hiểm, nhưng đôi khi những cách này cũng rất tàn bạo. Hầu hết trong suốt &nbsp;cả loạt phim, yếu tố cốt truyện chính diễn ra giống như một bộ phim về &nbsp;chính trị. Còn cốt truyện điển hình trong phim là Bauer luôn phải chạy &nbsp;đua với thời gian trong nỗ lực ngăn chặn nhiều âm mưu khủng bố khác nhau &nbsp;bao gồm: âm mưu ám sát tổng thống, vũ khí hủy diệt hàng loạt, khủng bố &nbsp;bằng vũ khí sinh học, tấn công mạng Internet,... cũng như những âm mưu &nbsp;đối phó với chính phủ và tham nhũng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"Kim Raver","avatar":""},{"name":"Yvonne Strahovski","avatar":""},{"name":"Tate Donovan","avatar":""},{"name":"William Devane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["24小时","24小时