INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-duoi-thap-co-2', 'Cuộc Chiến Dưới Tháp Cổ 2', 'Aliens vs Predator: Requiem', 'https://phimimg.com/upload/vod/20260320-1/dede3df07859e3f4aa3cfb11559dba27.jpg', 'https://phimimg.com/upload/vod/20260320-1/07e71b5099edf315eea0bc287c74fe91.jpg', '<p>Aliens Vs. Predator Requiem là phần tiếp theo của loạt phim khoa học viễn tưởng pha chút kinh dị, kỳ quái ăn khách Aliens Vs. Predator. Lần này, một chiến binh Predator đã bị lây nhiễm tế bào Alien, phi thuyền buộc phải hạ cách khẩn cấp, đó là một thị trấn nhỏ ở vùng Colorado... và thế là: &quot;Mùa giáng sinh này trái đất sẽ không còn yên bình nữa...&quot;</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Paetkau","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Steven Pasquale","avatar":""},{"name":"Reiko Aylesworth","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Johnny Lewis","avatar":""},{"name":"Ariel Gade","avatar":""},{"name":"Kristen Hager","avatar":""},{"name":"Robert Joy","avatar":""},{"name":"Ian Whyte","avatar":""},{"name":"Tom Woodruff Jr.","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Meshach Peters","avatar":""},{"name":"Matt Ward","avatar":""},{"name":"David Hornsby","avatar":""},{"name":"Chris William Martin","avatar":""},{"name":"James Chutter","avatar":""},{"name":"Ph","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02