INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('transformers-robot-dai-chien', 'Transformers: Robot Đại Chiến', 'Transformers', 'https://phimimg.com/upload/vod/20260225-1/f2ce63e34341b14512fd7f0f208544b2.jpg', 'https://phimimg.com/upload/vod/20260225-1/a7fc6cb106b43aef09115a882e7b5099.jpg', '<p>Cách đây chừng 4 triệu năm, trên hành tinh Cybertron xa xôi tồn tại một nền văn minh của robot. nhưng rồi nền văn minh ấy bị tàn phá bởi cuộc chiến kéo dài nhiều thế kỷ giữa hai chủng người máy: autobot (phe thiện) và deception (phe ác). Chúng đánh nhau để tranh giành allspark (thực thể lập phương) – thứ có khả năng mang tới quyền lực tối thượng cho kẻ sở hữu nó. Và rồi Trái Đất vô tình bị cuốn vào cuộc chiến khốc liệt này với những vũ khí mang tính hủy diệt khủng khiếp mà hai chủng tộc đó có khả năng biến hình đa dạng từ những chiếc xe tự hành cho đến những chiếc máy bay, những cỗ máy chiến đấu hủy diệt hàng loạt...</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Mark Ryan","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Michael O''Neill","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Julie White","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Zack Ward","avatar":""},{"name":"Luis Echagar","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Τρανσφόρμερς","ทรานส์ฟอร์เมอร์ส 1 : มหาวิบัติจักรกลสังหารถล่มจักรวาล","變形金剛1","变形金刚1","變形金剛","トランスフォーマー：2007","Robot Đại Chiến","變形金剛 1","Transformers 1","अंतरिक्ष का युद्ध","Transformers"]', 1784690324486);
