INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('transformers-robot-dai-chien', 'Transformers: Robot Đại Chiến', 'Transformers', 'transformers: robot đại chiến transformers shia labeouf megan fox mark ryan peter cullen hugo weaving josh duhamel tyrese gibson charlie adler rachael taylor anthony anderson jon voight john turturro michael o''neill kevin dunn julie white amaury nolasco zack ward luis echagar τρανσφόρμερς ทรานส์ฟอร์เมอร์ส 1 : มหาวิบัติจักรกลสังหารถล่มจักรวาล 變形金剛1 变形金刚1 變形金剛 トランスフォーマー：2007 robot đại chiến 變形金剛 1 transformers 1 अंतरिक्ष का युद्ध transformers', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-cot-phan-3', 'Hài Cốt (Phần 3)', 'Bones (Season 3)', 'https://phimimg.com/upload/vod/20260222-1/127d3e41fc4469ec89fe8f43613f27f9.jpg', 'https://phimimg.com/upload/vod/20260222-1/00ad9f973718c03122f716be00ecac5d.jpg', '<p>Tiến sĩ Temperance Brennan và các đồng nghiệp tại Phòng thí nghiệm Pháp y Medico-Legal thuộc Viện Jeffersonian hỗ trợ Đặc vụ Seeley Booth điều tra các vụ án giết người, đặc biệt là khi các thi thể đã bị phân hủy, thiêu rụi hoặc hủy hoại nghiêm trọng đến mức các phương pháp nhận dạng thông thường không còn tác dụng.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 16, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emily Deschanel","avatar":""},{"name":"David Boreanaz","avatar":""},{"name":"John Boyd","avatar":""},{"name":"Michaela Conlin","avatar":""},{"name":"Tamara Taylor","avatar":""},{"name":"T.J. Thyne","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huesos","Bones: Sempre em Medicina","寻骨线索","עצמות","استخوان‌ها","Bones"]', 1784690324486);
