INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-cot-phan-3', 'Hài Cốt (Phần 3)', 'Bones (Season 3)', 'hài cốt (phần 3) bones (season 3) emily deschanel david boreanaz john boyd michaela conlin tamara taylor t.j. thyne huesos bones: sempre em medicina 寻骨线索 עצמות استخوان‌ها bones', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kham-pha-the-gioi-tengen-toppa-gurren-lagann', 'Khám Phá Thế Giới (Tengen Toppa Gurren Lagann)', 'Gurren Lagann', 'https://phimimg.com/upload/vod/20260124-1/147c1f85ee30f7f01c55af4bbb7dedca.jpg', 'https://phimimg.com/upload/vod/20260124-1/8a8459cfa6c4c3043027c08a6e995a75.jpg', '<p>Trong tương lai xa, con người xây dựng nhà cửa và nuôi thú vật dưới hang ngầm lòng đất. Kết quả, Họ sống trong sợ hãi của những trận động đất và sụp hầm, và đã vài trăm năm trôi qua, Jeeha là một trong những ngôi làng đó.Một ngày kia, một cậu bé tên Simon đột nhiên tìm thấy một mũi khoan nhỏ, sáng bóng trong khi đào mở rộng đất cho làng. Cùng lúc đó, Kamina, một anh chàng tin tưởng rằng phía trên ngôi làng là một miền đất khác, lập nên một băng để phá xuyên qua mái vòm để có thể rời khỏi hang ngầm. Đột nhiên một trận động đất xuất hiện và mái vòm sụp xuống theo sau là một cỗ máy khổng lồ đã phá vỡ mái vòm.Kamina bây giờ chắc chắn là có một thế giới khác phía trên họ. Rất bất cẩn, anh ta bắt đầu chiến đấu với con robot. Thời điểm đó, một người khác xuất hiện từ miền đất phía trên. Một cô gái mang tên Yoko,. Với khẩu súng trường trên tay, cô đã tấn công con robot. Tuy nhiên những gì cô có thể làm là đốn ngã nó. Sau đó Simon cho Kamina và Yoko xem vật mà cậu ta đã tìm thấy. Đó là một...</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 10, 2007, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Kiyoyuki Yanada","avatar":""},{"name":"Nobuyuki Hiyama","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Yukari Fukui","avatar":""},{"name":"Michiko Neya","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Takashi Kondo","avatar":""},{"name":"Takaya Kamikawa","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Kisho Taniyama","avatar":""},{"name":"Kana Ueda","avatar":""},{"name":"Kana Asumi","avatar":""},{"name":"Daiki Nakamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天元突破：红莲螺岩","טנגן טופה גורן לאגן","TTGL","Tengen Toppa Gurren Lagann","천원돌파 그렌라간","Гуррен Лаганн","Heaven-Piercing Gurren Lagann","Heavenly Breakthrough Gurren Lagann","天元突破グレンラガン"]', 1784690324486);
