INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-dong-tinh-2007', 'Hôn Nhân Đồng Tính (Đám Cưới Bất Đắc Dĩ)', 'I Now Pronounce You Chuck & Larry', 'https://phimimg.com/upload/vod/20260116-1/0ebf928c9a814ab0435ea4c522254b44.jpg', 'https://phimimg.com/upload/vod/20260116-1/14fb4603c68fd3bdf83c077b8eb51bba.jpg', '<p>Chuck và Larry là bạn và là lính cứu hỏa ở New York. Họ rất thân thiết và sẽ làm bất cứ điều gì vì nhau, vì vậy, khi có vấn đề với việc sắp xếp lương hưu của Larry mà có thể giải quyết bằng cách tham gia vào quan hệ đối tác dân sự, Chuck đồng ý đóng giả làm &quot;chồng&quot; của anh ấy để giải quyết vấn đề quản trị. Đáng buồn thay, một vụ lừa đảo nổi tiếng ở một tiểu bang khác có nghĩa là &quot;cặp đôi&quot; đang bị điều tra viên ám ảnh Clint Fritzer giám sát và phải đóng hết vai trò của họ. Sự vui nhộn tự nhiên xảy ra nhưng mọi người cũng có thể học được một bài học không?</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Nicholas Turturro","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Rachel Dratch","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Richard Chamberlain","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Becky O''Donohue","avatar":""},{"name":"Shelby Adamowsky","avatar":""},{"name":"Jessie O''Donohue","avatar":""},{"name":"Chandra West","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Os declaro marido y marido","當我們「假」在一起","迫上断背山","Yo los Declaro Marido y Larry","Chuck & Larry - Wie Feuer und Flamme","Eu os Declaro Marido e… Larry","Declaro-vos Marido e... Marido","I Now Pronounce You Chuck and Larry","同性婚礼","I Now Pronounce You Chuck & Larry"]', 1784690324486);
