INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-nhan-dong-tinh-2007', 'Hôn Nhân Đồng Tính (Đám Cưới Bất Đắc Dĩ)', 'I Now Pronounce You Chuck & Larry', 'hôn nhân đồng tính (đám cưới bất đắc dĩ) i now pronounce you chuck & larry adam sandler kevin james jessica biel dan aykroyd ving rhames steve buscemi nicholas turturro allen covert rachel dratch nick swardson richard chamberlain jamie chung becky o''donohue shelby adamowsky jessie o''donohue chandra west os declaro marido y marido 當我們「假」在一起 迫上断背山 yo los declaro marido y larry chuck & larry - wie feuer und flamme eu os declaro marido e… larry declaro-vos marido e... marido i now pronounce you chuck and larry 同性婚礼 i now pronounce you chuck & larry', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-cua-mr-bean', 'Kỳ Nghỉ Của Mr. Bean', 'Mr. Bean''s Holiday', 'https://phimimg.com/upload/vod/20260116-1/31ffd4c556780ee3497e5327cec9ca33.jpg', 'https://phimimg.com/upload/vod/20260116-1/2aeda901cab0376f36c8aad49a2a7fb0.jpg', '<p>&quot;Nhờ vào “tài lẻ”, Mr.Bean may mắn trúng giải Nhất trong một cuộc quay xổ số từ thiện ở nhà thờ. Giải thưởng bao gồm một chiếc máy ảnh kỹ thuật số hiện đại, một chuyến du lịch một tuần đến các bãi biển vùng Riveira xinh đẹp ở phía Nam nước Pháp - nơi tổ chức Liên hoan phim quốc tế thường niên Cannes và 200 euro tiền tiêu vặt.Thật thú vị là chuyến du lịch được tổ chức vào đúng thời điểm vùng Riveira đang bận rộn chuẩn bị cho Liên hoan phim Cannes.Mr.Bean lên đường với tất cả sự háo hức và hãnh diện. Trên đường đi, chỉ vì cái tính vụng về đặc trưng của mình, Mr.Bean đã làm Emil - một đạo diễn người Nga cũng đang trên đường đến Cannes với con trai Stepan - bị nhỡ tàu.Mr.Bean bất đắc dĩ vừa phải ...</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rowan Atkinson","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Maxim Baldry","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Emma de Caunes","avatar":""},{"name":"Steve Pemberton","avatar":""},{"name":"Jean Rochefort","avatar":""},{"name":"Michel Winogradoff","avatar":""},{"name":"Adrien Rodrigue","avatar":""},{"name":"Bams Betga-Tchouni","avatar":""},{"name":"Julie Fournier","avatar":""},{"name":"Julie Ferrier","avatar":""},{"name":"Lily Atkinson","avatar":""},{"name":"Preston Nyman","avatar":""},{"name":"Sharlit Deyzac","avatar":""},{"name":"Francois Touch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mr Bean''s Holiday","Las Vacaciones de Mr. Bean","Prázdniny Mr. Beana","Les vacances de Mr. Bean","憨豆先生的假期","Kỳ Nghỉ Của Mr. Bean","憨豆先生的黄金周","Mr Bean: 2 - Las vacaciones de Mr. Bean","Mr. Bean macht Ferien","Mr.ビーン カンヌで大迷惑?!","미스터 빈의 홀리데이","Mr. Bean''s Holiday"]', 1784690324486);
