INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-3-toi-hau-thu-cua-bourne', 'Siêu Điệp Viên 3: Tối Hậu Thư Của Bourne', 'The Bourne Ultimatum', 'https://phimimg.com/upload/vod/20260116-1/b70ba65c9a61046df27781d35bb56825.jpg', 'https://phimimg.com/upload/vod/20260116-1/28be37c17d24c488905f6b95345bc5e2.jpg', '<p>Sau cái chết của Marie, Jason gần như trở nên điên loạn với hàng đống đạn dược và những vũ khí giết người hiện đại. Anh chỉ có một mục tiêu duy nhất là quay trở lại nơi bắt đầu và tìm hiểu về thân phận của mình. Jason phải truy ra quá khứ của mình để tìm ra một tương lai mới cho bản thân. Anh phải đi từ Moscow, Paris, Madrid và London sang Tangier và New York tiếp tục sứ mệnh của mình để tìm ra Jason Bourne &quot;thật&quot;. Anh phải cố thoát khỏi sự truy đuổi của cảnh sát và điệp viên của Interpol trong suốt chuyến hành trình gian khổ đó.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Tom Gallop","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Joey Ansah","avatar":""},{"name":"Colin Stinton","avatar":""},{"name":"Dan Fredenburgh","avatar":""},{"name":"Lucy Liemann","avatar":""},{"name":"Bryan Reents","avatar":""},{"name":"Arkie Reece","avatar":""},{"name":"John Roberson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d