INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-dien-am-nhac-2', 'Hội Diễn Âm Nhạc 2', 'High School Musical 2', 'https://phimimg.com/upload/vod/20251116-1/178ad6d631c89ae767d1f6d705d5d4b2.jpg', 'https://phimimg.com/upload/vod/20251116-1/cdb886c1e26bf15a0c4199946e277039.jpg', '<p>Troy được cung cấp một công việc tại Câu lạc bộ đồng quê của Ryan &amp; Sharpay và kết thúc việc hạ cánh cho Gabriella, Chad, Taylor, Kelsi, Jason, Martha và Zeke. Sau đó, ông được giới thiệu với cha mẹ của Sharpay và nhận ra rằng Sharpay có thể hạ cánh cho anh ta nhiều cơ hội và thậm chí là một học bổng bóng rổ. Trong khi đó, trong khi Troy bắt đầu đi chơi với dân gian giàu, Chad lo lắng rằng Troy sẽ quên bạn bè. Gabriella cảm thấy như thể cô đang mất Troy để Sharpay. Cuối cùng, Troy sẽ phải học cách nghĩ về học bổng của mình mà không mất bạn bè</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Lucas Grabeel","avatar":""},{"name":"Corbin Bleu","avatar":""},{"name":"Olesya Rulin","avatar":""},{"name":"Chris Warren","avatar":""},{"name":"Monique Coleman","avatar":""},{"name":"Ryne Sanborn","avatar":""},{"name":"Kaycee Stroh","avatar":""},{"name":"Mark L. Taylor","avatar":""},{"name":"Robert Curtis Brown","avatar":""},{"name":"Jessica Tuck","avatar":""},{"name":"Bart Johnson","avatar":""},{"name":"Alyson Reed","avatar":""},{"name":"Tanya Chisholm","avatar":""},{"name":"Miley Cyrus","avatar":""},{"name":"Kel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492