INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-phau-thuat-cua-grey-phan-4', 'Ca Phẫu Thuật Của Grey (Phần 4)', 'Grey''s Anatomy (Season 4)', 'ca phẫu thuật của grey (phần 4) grey''s anatomy (season 4) ellen pompeo chandra wilson james pickens jr. kevin mckidd caterina scorsone camilla luddington kim raver jason george chris carmack anthony hill adelaide kane alexis floyd niko terho harry shum jr. trevor jackson anatomia e greit a anatomia de grey l''anatomie de grey 实习医生 grey''s anatomy die jungen ärzte grey''s anatomy die jungen aerzte grey''s anatomy - die jungen ärzte a coeur ouvert 그레이 아나토미 анатомія пристрасті greys anatomy grey''s anatomy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-doi-tra-phan-1', 'Trò Chơi Dối Trá (Phần 1)', 'Liar Game (Season 1)', 'https://phimimg.com/upload/vod/20251104-1/5a0f4c467412f95897a89376ec89dabb.jpg', 'https://phimimg.com/upload/vod/20251104-1/5888a1b6b0d3cec3134ca287c1cd8fb7.jpg', '<p>Câu chuyện mở đầu với Kanzaki Nao (Toda Erika), cô sinh viên tốt bụng và trung thực đến ngây thơ, vô tình bị kéo vào “Trò chơi dối trá” – nơi người chơi lừa nhau để giành số tiền khổng lồ. Nao tìm đến sự giúp đỡ của thiên tài lừa đảo Akiyama Shinichi (Matsuda Shota). Từ đó, cả hai bước vào chuỗi đấu trí nghẹt thở.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2007, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Shota Matsuda","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Michiko Kichise","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Kosuke Suzuki","avatar":""},{"name":"Ikkei Watanabe","avatar":""},{"name":"Megumi","avatar":""},{"name":"Yoshiyuki Morishita","avatar":""},{"name":"Hairi Katagiri","avatar":""},{"name":"Shihou Harumi","avatar":""},{"name":"Yoshiyoshi Arakawa","avatar":""},{"name":"Jutta Yuki","avatar":""},{"name":"Hidekazu Mashima","avatar":""},{"name":"Nobuo Kyô","avatar":""},{"name":"Shugo Oshinari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["欺诈游戏","说谎者的游戏","Raiaa Geemu","Raiā Gēmu","ライアーゲーム","LIAR GAME","라이어게임","Ігри Брехунів"]', 1784690324486);
