INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-ngay-dia-nguc', '7 Ngày Địa Ngục', 'Seven Days', 'https://phimimg.com/upload/vod/20251023-1/4570ec10d0f39c4869007c0522e4f42a.jpg', 'https://phimimg.com/upload/vod/20251023-1/ececcfe108f668c676a4e06676aeb078.jpg', '<p>Nội dung phim xoay quanh câu chuyện về một bà mẹ cô độc mà đứa con duy nhất của cô cũng bị một kẻ lạ mặt bắt cóc. Nhưng Ji-yon cũng là một nữ luật sư tài năng, quyến rũ và đầy tham vọng; vì thế khi kẻ bắt cóc yêu cầu cô phải bào chữa cho một bị cáo bị kết án giết người đổi lại cô sẽ cứu được con gái mình thì cô đã từ chối và chống trả đến cùng.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yunjin Kim","avatar":""},{"name":"Kim Mi-sook","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Jang Hang-seon","avatar":""},{"name":"Oh Kwang-rok","avatar":""},{"name":"Ok Ji-young","avatar":""},{"name":"Jeong Dong-hwan","avatar":""},{"name":"Seo Dong-soo","avatar":""},{"name":"Lee Jeong-heon","avatar":""},{"name":"Jin Yong-uk","avatar":""},{"name":"Kim Min-su","avatar":""},{"name":"Bae Geon-sik","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["七日綁票令","7天","Se-beun De-i-jeu","七天","SevenDays","세븐데이즈","Seven Days","세븐 데이즈"]', 1784690324486);
