INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('7-ngay-dia-nguc', '7 Ngày Địa Ngục', 'Seven Days', '7 ngày địa ngục seven days yunjin kim kim mi-sook park hee-soon choi moo-seong jang hang-seon oh kwang-rok ok ji-young jeong dong-hwan seo dong-soo lee jeong-heon jin yong-uk kim min-su bae geon-sik 七日綁票令 7天 se-beun de-i-jeu 七天 sevendays 세븐데이즈 seven days 세븐 데이즈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-15', 'Upin & Ipin (Phần 15)', 'Upin & Ipin (Season 15)', 'https://phimimg.com/upload/vod/20251022-1/65e09d63895745fd4137f060e8037437.jpg', 'https://phimimg.com/upload/vod/20251022-1/5571fac8e2f5da06936d7e0ac222269b.jpg', '<p>“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p>Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p><br/></p><p><br/></p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 21, 2007, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324486);
