INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuat-nhap-khau', 'Xuất Nhập Khẩu', 'Import/Export', 'https://phimimg.com/upload/vod/20251015-1/ad83e79b49991f1b0e80130cb37eade2.jpg', 'https://phimimg.com/upload/vod/20251015-1/15e268f0c10b48451fe60a2ca8d65c63.jpg', '<p>Một y tá từ Ukraine tìm kiếm một cuộc sống tốt đẹp hơn ở phương Tây, trong khi một nhân viên bảo vệ thất nghiệp từ Áo hướng về phía Đông vì lý do tương tự. Cả hai đều đang tìm kiếm việc làm, một khởi đầu mới, một sự tồn tại, đấu tranh để tin vào bản thân, để tìm thấy ý nghĩa trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 29, 2007, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Ekateryna Rak","avatar":""},{"name":"Paul Hofmann","avatar":""},{"name":"Michael Thomas","avatar":""},{"name":"Susanne Lothar","avatar":""},{"name":"Natalija Baranova","avatar":""},{"name":"Natalja Epureanu","avatar":""},{"name":"Maria Hofstätter","avatar":""},{"name":"Georg Friedrich","avatar":""},{"name":"Erich Finsches","avatar":""},{"name":"Johannes Nussbaum","avatar":""},{"name":"Lidiya Oleksandrivna Savka","avatar":""},{"name":"Dmytro Andriyovich Gachkov","avatar":""},{"name":"Miloslava Kubkova","avatar":""},{"name":"Katka Ackerm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Import/Export","Ипорт-Экспорт","Импорт/Экспорт","进出口","寂寞边界","Import Export","Імпорт Експорт"]', 1784690324486);
