INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('-van-mo-chi', 'Văn Mộ Chí', 'Epitaph', 'https://phimimg.com/upload/vod/20251009-1/94f55937a4dca048952ef04e4b311493.jpg', 'https://phimimg.com/upload/vod/20251009-1/600f4662d7519514c41e0310725b4e16.jpg', '<p>Bác sĩ Park Jung-nam tìm thấy một album ảnh có từ thời còn là thực tập sinh tại Bệnh viện Ansaeng. Điều này kích hoạt ký ức của cuộc đời anh. Năm 1942, khi còn là một bác sĩ y khoa trẻ tuổi, cuộc hôn nhân sắp đặt của Jung-nam kết thúc khi vợ sắp cưới của anh, người mà anh chưa bao giờ gặp, đã tự tử. Sau đó, anh được chỉ định theo dõi nhà xác vào đêm khuya. Ở đó, anh ta yêu một xác chết và được tiết lộ là thi thể của vị hôn thê quá cố của anh ta. Chẳng mấy chốc, những sự kiện bí ẩn khác diễn ra trong bệnh viện, liên quan đến một cô gái trẻ bị ma ám và một kẻ giết người hàng loạt nhắm vào lính Nhật.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin Goo","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Kim Bo-kyung","avatar":""},{"name":"Lee Dong-kyu","avatar":""},{"name":"Park Ji-a","avatar":""},{"name":"Ko Joo-yeon","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Jeong Ji-an","avatar":""},{"name":"Choi Jae-hwan","avatar":""},{"name":"Jeon Moo-song","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Kim Joo-hyun","avatar":""},{"name":"Uhm Ji-won","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["奇談","Gidam","冥婚淒谈","奇谈","기담","گورنبشته","Epitaph"]', 1784690324487);
