INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-but-anh-yeu-em', 'Tái Bút: Anh Yêu Em', 'P.S. I Love You', 'https://phimimg.com/upload/vod/20251008-1/6ef5d0d2787f28f90da7dac5f7a70a4f.jpg', 'https://phimimg.com/upload/vod/20251008-1/c14c6a0a1fd42a42ee24aad854a12672.jpg', '<p><span style="text-wrap-mode: wrap;">Holly Kennedy thật đẹp, thông minh và kết hôn với tình yêu của đời mình - một người irishman say mê, hài hước, hài hước và bốc đồng tên là Gerry. Vì vậy, khi cuộc sống của Gerry bị bệnh tật, nó sẽ mất cuộc sống từ Holly. Người duy nhất có thể giúp cô là người không còn ở đó. Không ai biết Holly tốt hơn Gerry. Vì vậy, đó là một điều tốt, anh ấy đã lên kế hoạch trước. Trước khi chết, Gerry đã viết một loạt các lá thư sẽ hướng dẫn cô, không chỉ thông qua nỗi đau của cô, mà còn khám phá lại chính mình. Tin nhắn đầu tiên đến sinh nhật lần thứ 30 của Holly dưới dạng một chiếc bánh, và cho cú sốc hoàn toàn của cô, một đoạn băng ghi âm từ Gerry, người tiến hành bảo cô ra ngoài và &quot;kỷ niệm bản thân&quot;. Trong những tuần và nhiều tháng sau đó, nhiều chữ cái từ Gerry được giao theo những cách đáng ngạc nhiên, mỗi chữ cái gửi cho cô ấy vào một cuộc phiêu lưu mới và mỗi lần ký theo cách tương tự; P.S. Tôi mến bạn. Mẹ và những người bạn tốt nhất của Holly bắt đầu lo lắng rằng những lá thư của Gerry đang giữ cho Holly gắn liền với quá khứ, nhưng thực tế, mỗi lá thư đang đẩy cô ấy đi xa hơn vào một tương lai mới. Với những lời của Gerry là hướng dẫn của cô, Holly bắt đầu cuộc hành trình khám phá lại trong một câu chuyện về hôn nhân, tình bạn và cách một tình yêu mạnh mẽ có thể biến sự vĩ đại của cái chết thành một khởi đầu mới cho cuộc sống.</span></p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Hilary Swank","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Harry Connick Jr.","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"James Marsters","avatar":""},{"name":"Nellie McKay","avatar":""},{"name":"Anne Kent","avatar":""},{"name":"Brian McGrath","avatar":""},{"name":"Dean Winters","avatar":""},{"name":"Sherie Rene Scott","avatar":""},{"name":"Susan Blackwell","avatar":""},{"name":"Michael Countryman","avatar":""},{"name":"Roger Rathburn","avatar":""},{"name":"Rita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Posdata, te amo","P.S. Eu te amo","P.S. Ma armastan sind","P.S. Te iubesc","P.S. kocham cie","P.S. rakastan sinua","Posdata: Te quiero","P.S.我愛你","P.S. Je t''aime","Posdata, Te quiero","P.S. Я люблю тебя","P.S. I Love You - Non è mai troppo tardi per dirlo","P.S. I Love You","P.D. T''estimo"]', 1784690324487);
