INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-but-anh-yeu-em', 'Tái Bút: Anh Yêu Em', 'P.S. I Love You', 'tái bút: anh yêu em p.s. i love you hilary swank gerard butler lisa kudrow harry connick jr. gina gershon jeffrey dean morgan kathy bates james marsters nellie mckay anne kent brian mcgrath dean winters sherie rene scott susan blackwell michael countryman roger rathburn rita posdata, te amo p.s. eu te amo p.s. ma armastan sind p.s. te iubesc p.s. kocham cie p.s. rakastan sinua posdata: te quiero p.s.我愛你 p.s. je t''aime posdata, te quiero p.s. я люблю тебя p.s. i love you - non è mai troppo tardi per dirlo p.s. i love you p.d. t''estimo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-3', 'Người Nhện 3', 'Spider-Man 3', 'https://phimimg.com/upload/vod/20250828-1/2b65f5542958b51e8ebe6a753c0037cb.jpg', 'https://phimimg.com/upload/vod/20250828-1/db24338194c1b2ec0ec3a77f20429d88.jpg', '<p>Spider Man 3 là phần tiếp theo của series phim Spider Man. Lần này, tưởng như Peter Parker đã tìm được bình yên trong cuộc sống bên cạnh người anh yêu. Nhưng cậu bạn cũ Harry Osborn khám phá ra bí mật về bộ giáp Green Goblin do người cha quá cố để lại. &nbsp;Cũng đúng lúc này, bỗng có một thứ vật chất biến bộ đồ của Spider-Man thành màu đen và khiến tính khí của Peter Parker đột ngột thay đổi, trở nên cao ngạo hơn bao giờ hết. Rồi thứ vật chất đen bí ẩn kia còn biến Eddie Brock trở thành Venom (Người Nhện Đen) – có những khả năng y hệt như Spider Man. Giờ đây Spider Man phải tìm cách thoát khỏi thứ vật chất gớm ghiếc kia và chuẩn bị cho một cuộc chiến lớn với ba kẻ thù đầy nguy hiểm kia… Tình yêu, tình bạn và những giằng xé nội tâm sẽ giúp được gì khi Người Nhện không còn khoác trên mình bộ đồ màu đỏ quen thuộc?</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"James Franco","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Rosemary Harris","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Theresa Russell","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Perla Haney-Jardine","avatar":""},{"name":"Wi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Spider-Man 3: The IMAX Experience","Σπάιντερμαν 3","Людина-павук 3. Ворог у відбитті","스파이더맨3","Pókember 3","スパイダーマン3","Hämähäkkimies 3","ობობა-კაცი 3","სპაიდერმენი 3","Người Nhện 3","មនុស្សពីងពាង វគ្គ៣","Örümcek Adam 3","Spider Man III","蜘蛛侠3 (托比·马奎尔)","ပင့်ကူလူသား ၃","Hörümçək-Adam 3","الرجل العنكبوت ٣","Spider-Man 3"]', 1784690324487);
