INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-2007', 'Trở Lại', 'Return', 'https://phimimg.com/upload/vod/20250913-1/3add2fd51dc66d48b5fc7a4bfa588021.jpg', 'https://phimimg.com/upload/vod/20250913-1/2955faba316dc1870a7ec89565af1d7b.jpg', '<p>Năm mười tuổi, Sang-woo phải trải qua một ca phẫu thuật đau đớn và vì sang chấn, cậu đã giết một đứa trẻ khác. Sau đó, cậu được điều trị bằng thôi miên và cùng gia đình biến mất. Hai mươi lăm năm sau, khi đã trở thành một bác sĩ thành đạt, Sang-woo tình cờ gặp lại người bạn cũ – và từ đó, mọi thứ bắt đầu thay đổi.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Myung-min","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Kim Yu-mi","avatar":""},{"name":"Yu Jun-sang","avatar":""},{"name":"Jung You-seok","avatar":""},{"name":"Kim Roi-ha","avatar":""},{"name":"Kwak Min-seok","avatar":""},{"name":"Baek Seung-hwan","avatar":""},{"name":"Kim Byung-chul","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Seo Young-hwa","avatar":""},{"name":"Kim Kwang-shik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ri-teon","Wide Awake","Return","리턴"]', 1784690324487);
