INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoc-loi-chuoc-toi', 'Chuộc Lỗi (Chuộc Tội)', 'Atonement', 'https://phimimg.com/upload/vod/20250814-1/63da53852836827342cdbb263819207d.jpg', 'https://phimimg.com/upload/vod/20250814-1/301ebf21803bd74de9132fc3955f7f97.jpg', '<p>Lời kết tội của Briony cũng chính là phán quyết cuối cùng thay đổi hoàn toàn cuộc đời Robbie. Từ một thanh niên tri thức, anh bỗng nhiên bị chôn chân trong chốn lao tù và hiến dâng tuổi trẻ nơi chiến trường khốc liệt. Mối tình của anh và Cecilia mãi mãi kết thúc ở lời hứa “Anh sẽ trở về” và nụ hôn tạm biệt trước lúc đi xa.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Saoirse Ronan","avatar":""},{"name":"Romola Garai","avatar":""},{"name":"Vanessa Redgrave","avatar":""},{"name":"Brenda Blethyn","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Alfie Allen","avatar":""},{"name":"Jérémie Renier","avatar":""},{"name":"Anthony Minghella","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Peter Wight","avatar":""},{"name":"Gina McKee","avatar":""},{"name":"Tilly Vosburgh","avatar":""},{"name":"John","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Искупление","Espiazione","Reviens-moi","Desejo e Reparação","愛．誘．罪","Expiación: Más Allá de la Pasión","تاوان","Expiación","Atonement - Abbitte","어톤먼트","Försoning","愛誘罪","Expiation","Chuộc Tội","救赎","Atonement"]', 1784690324487)