INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-long-cua-cha', 'Nỗi Lòng Của Cha (Tình Phụ Tử)', 'Fathers and Sons', 'https://phimimg.com/upload/vod/20250727-1/9f4a895a07892ec6351b88602b6d66b0.jpg', 'https://phimimg.com/upload/vod/20250727-1/655d085399a9839fde51aaafc52cfb34.jpg', '<p>&quot;Chuyên gia giá cả&quot; Mẫn Thiên Tứ là một giám đốc thị trường có tiếng trong thành phố, anh được mệnh danh là &quot;Mẫn đại nhân&quot;. Một ngày nọ, con trai 8 tuổi đột nhiên được gửi lại cho anh, khiến anh không biết xoay sở ra sao, may mắn được người bạn khắc khẩu Kim Mỹ Toàn nghĩ cách giúp đỡ. Mặt khác, con trai giúp cho Thiên Tứ và cha nuôi Cao Chí Thiêm hàn gắn lại tình cảm. Chí Thiêm luôn chiều theo ý con trai Cao Thanh khiến bản thân chịu nhiều tủi ấm ức. Cao Thanh thì chỉ lo chăm sóc con gái mình, người cha gương mẫu ấy lại trở thành người con và người chồng thất bại, may được Thiên Tứ và người bạn tri kỷ La Tứ Hỷ động viên giúp đỡ. Thiên Tứ và Cao Thanh hai người cha không thành công này lại vô tình phát hiện ra bí mật bị cha họ che giấu suốt nhiều năm...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 11, 2007, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bobby Au-Yeung Tsan-Wah","avatar":""},{"name":"Yoyo Mung Ka-Wai","avatar":""},{"name":"Ha Yue","avatar":""},{"name":"Wong Hei","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Halina Tam Siu-Wan","avatar":""},{"name":"Evergreen Mak Cheung-Ching","avatar":""},{"name":"Chris Lai","avatar":""},{"name":"Jacky Wong Shu-Hei","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Anne Heung Hoi-Lam","avatar":""},{"name":"Vivian Tsang","avatar":""},{"name":"Chan On-ying","avatar":""},{"name":"Mary Hon Ma-Lee","avatar":""},{"name":"Chow Chung","avatar":""},{"name":"Alice Fu","avatar":""}]',