INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-thuong-hang-cua-zack-cody-phan-3', 'Cuộc Sống Thượng Hạng Của Zack & Cody (Phần 3)', 'The Suite Life Of Zack & Cody (Season 3)', 'https://phimimg.com/upload/vod/20250710-1/7c18e223924112d80edfb3269b832f2f.jpg', 'https://phimimg.com/upload/vod/20250710-1/c708600a88c6cc8e5f8cf0ad138f3709.jpg', '<p>Gặp gỡ Zack và Cody, cặp song sinh giống hệt nhau 11 tuổi và là cư dân mới nhất của khách sạn sang trọng Tipton ở Boston. Sống trong một căn hộ cùng mẹ là Carey, hai cậu bé xem Tipton như sân chơi riêng của mình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 20, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan Sprouse","avatar":""},{"name":"Cole Sprouse","avatar":""},{"name":"Ashley Tisdale","avatar":""},{"name":"Brenda Song","avatar":""},{"name":"Kim Rhodes","avatar":""},{"name":"Phill Lewis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Suite Life of Zack & Cody"]', 1784690324487);
