INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-toc-do', 'Ma Tốc Độ', 'Ghost Rider', 'https://phimimg.com/upload/vod/20250707-1/ac6576feb3b333856d39258edcc8ad86.jpg', 'https://phimimg.com/upload/vod/20250707-1/208533e413278b313d46d34f4ac06414.jpg', '<p>Jonny là một tay lái mô tô siêu hạng chuyên biểu diễn những pha mạo hiểm trên đường phố. Khi cha mắc bệnh ung thư, anh đành phải ký một bản khế ước với tử thần để cứu mạng cha. Khi màn đêm buông xuống, anh trở thành ma tốc độ với chiếc đầu lâu rực lửa và chiếc mô tô phân khối lớn đi săn tìm văn tự ghi tên các linh hồn nộp cho ác quỷ. Nhưng rồi Jonny bị ác quỷ phản bội, cha anh vẫn chết mà người yêu thì rời xa anh, anh trở thành người đứng giữa cuộc chiến của hai cha con quỷ Mephistopheles.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Peter Fonda","avatar":""},{"name":"Matt Long","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Raquel Alessi","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Tony Ghosthawk","avatar":""},{"name":"Hugh Sexton","avatar":""},{"name":"Marcus Jones","avatar":""},{"name":"Lawrence Cameron Steele","avatar":""},{"name":"Eddie Baroo","avatar":""},{"name":"Jessica Napier","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Daniel Frederiksen","avatar":""},{"name":"Mathew","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ghost Rider - Aaveajaja","Ghost Rider (Extended Cut)","Ghost Rider El Motorista Fantasma","Ghost Rider 1","El Vengador Fantasma 1","گوست رایدر","灵魂战车","महाकाल: आग लगा देगा","幽灵车神","恶灵战警","恶灵骑士","幽灵骑士","鬼面骑士","الشبح الدراج","Ghost Rider"]', 1784690324487);
