INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-toc-do', 'Ma Tốc Độ', 'Ghost Rider', 'ma tốc độ ghost rider nicolas cage eva mendes sam elliott wes bentley peter fonda matt long brett cullen raquel alessi donal logue tony ghosthawk hugh sexton marcus jones lawrence cameron steele eddie baroo jessica napier rebel wilson daniel frederiksen mathew ghost rider - aaveajaja ghost rider (extended cut) ghost rider el motorista fantasma ghost rider 1 el vengador fantasma 1 گوست رایدر 灵魂战车 महाकाल: आग लगा देगा 幽灵车神 恶灵战警 恶灵骑士 幽灵骑士 鬼面骑士 الشبح الدراج ghost rider', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-menh-lenh-phuong-hoang', 'Harry Potter và Mệnh Lệnh Phượng Hoàng', 'Harry Potter and the Order of the Phoenix', 'https://phimimg.com/upload/vod/20250602-1/48fa44ed4ca3fed2adf799240069b7ef.jpg', 'https://phimimg.com/upload/vod/20250602-1/8d433ae93f9c5ba3086c1742b65f63b1.jpg', '<p>Harry tức giận vì bị bỏ rơi ở nhà Dursley trong dịp hè, cậu ngờ rằng Chúa tể hắc ám Voldemort đang tập hợp lực lượng, và vì cậu có nguy cơ bị tấn công, những người Harry luôn coi là bạn đang cố che giấu tung tích cậu. Cuối cùng, sau khi được giải cứu, Harry khám phá ra rằng giáo sư Dumbledore đang tập hợp lại Hội Phượng Hoàng – một đoàn quân bí mật đã được thành lập từ những năm trước nhằm chống lại Chúa tể Voldemort. &nbsp;Tuy nhiên, Bộ Pháp thuật không ủng hộ Hội Phượng Hoàng, những lời bịa đặt nhanh chóng được đăng tải trên Nhật báo Tiên tri – một tờ báo của giới phù thủy, Harry lo ngại rằng rất có khả năng cậu sẽ phải gánh vác trách nhiệm chống lại cái ác một mình.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Evanna Lynch","avatar":""},{"name":"Katie Leung","avatar":""},{"name":"Warwick Davis","avatar":""},{"name":"Fion","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Harry Potter och Fenixorden","Harry Potter E L''ordine della Fenice","Harry Potter og Føniksordenen","Harry Potter i Zakon Feniksa","Harry Potter e a Ordem da Fênix","해리포터와 불사조 기사단","Гарри Поттер и Орден Феникса","ハリーポッターと不死鳥の騎士団","Harijs Poters un Fēniksa Ordenis","הרי פותר ומסדר עוף החול","Harry Potter y la Orden del Fénix","Harry Potter ja Fööniksi Ordu","哈利·波特与凤凰社","Harry Potter và Hội Phượng Hoàng","แฮร์รี่ พอตเตอร์กับภาคีนกฟีนิกซ์","هاري بوتر وجماعة العنقاء","Harry Potter et l''Ordre du Phénix","Հարրի Փոթերը և Փյունիկի միաբանությունը","Harri Potter və Simurq Ordeni","Harry Potter i Red Feniksa","Harry Potter i l''orde del Fènix","Harry Potter og Fønixordenen","Hari Poter kaj la Ordeno de la Fenikso","Harry Potter eta Fenixaren Ordena","Harry Potter e a Orde do Fénix","Haris Poteris ir Fenikso Brolija","Harry Potter és a Főnix Rendje","Harry Potter en de Orde van de Feniks","Harry Potter va Feniks Jamiyati","Harry Potter dhe Urdhri i Feniksit","Harry Potter și Ordinul Phoenix","Harry Potter in Feniksov Red","Harry Potter a Fénixov Rád","Harry Potter ja Feeniksin Kilta","Harry Potter ve Zümrüdüanka Yoldaşlığı","Harry Potter a Fénixův Řád","Harry Potter og Fönixreglan","Haris Puoteris ė Feniksa Bruolėjė","Гары Потэр і Ордэн Фенікса","Ο Χάρι Πότερ και το Τάγμα του Φοίνικα","Гарри Поттер жана Феникс ордени","Хари Потър и Орденът на феникса","Харри Поттер ба Галт шувууны бүлгэм","Хари Потер и Редот на фениксот","Хари Потер и Ред феникса","Гаррі Поттер та Орден Фенікса","Гарри Поттер тата Феникс орденӗ","Хәрри Поттер және Самұрық Ордені","ہیری پوٹر اور ققنس کا گروہ","هری پاتر و محفل ققنوس","ہیری پوٹر اینڈ دی آرڈر اف فینیکس","ہیری پوٹر تہٕ پھینِک سٕنٛز جماعت","हैरी पॉटर और मायापंछी का समूह","हॅरी पॉटर अँड द ऑर्डर ऑफ द फिनिक्स","ਹੈਰੀ ਪੌਟਰ ਐਂਡ ਦ ਔਰਡਰ ਔਫ਼ ਦ ਫ਼ੀਨਿਕਸ","ஆரி பாட்டர் அண்டு த ஆர்டர் ஆப் த பீனிக்சு","ഹാരി പോട്ടർ ആന്