INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-menh-lenh-phuong-hoang', 'Harry Potter và Mệnh Lệnh Phượng Hoàng', 'Harry Potter and the Order of the Phoenix', 'harry potter và mệnh lệnh phượng hoàng harry potter and the order of the phoenix daniel radcliffe rupert grint emma watson imelda staunton helena bonham carter robbie coltrane gary oldman ralph fiennes michael gambon alan rickman richard griffiths brendan gleeson jason isaacs evanna lynch katie leung warwick davis fion harry potter och fenixorden harry potter e l''ordine della fenice harry potter og føniksordenen harry potter i zakon feniksa harry potter e a ordem da fênix 해리포터와 불사조 기사단 гарри поттер и орден феникса ハリーポッターと不死鳥の騎士団 harijs poters un fēniksa ordenis הרי פותר ומסדר עוף החול harry potter y la orden del fénix harry potter ja fööniksi ordu 哈利·波特与凤凰社 harry potter và hội phượng hoàng แฮร์รี่ พอตเตอร์กับภาคีนกฟีนิกซ์ هاري بوتر وجماعة العنقاء harry potter et l''ordre du phénix հարրի փոթերը և փյունիկի միաբանությունը harri potter və simurq ordeni harry potter i red feniksa harry potter i l''orde del fènix harry potter og fønixordenen hari poter kaj la ordeno de la fenikso harry potter eta fenixaren ordena harry potter e a orde do fénix haris poteris ir fenikso brolija harry potter és a főnix rendje harry potter en de orde van de feniks harry potter va feniks jamiyati harry potter dhe urdhri i feniksit harry potter și ordinul phoenix harry potter in feniksov red harry potter a fénixov rád harry potter ja feeniksin kilta harry potter ve zümrüdüanka yoldaşlığı harry potter a fénixův řád harry potter og fönixreglan haris puoteris ė feniksa bruolėjė гары потэр і ордэн фенікса ο χάρι πότερ και το τάγμα του φοίνικα гарри поттер жана феникс ордени хари потър и орденът на феникса харри поттер ба галт шувууны бүлгэм хари потер и редот на фениксот хари потер и ред феникса гаррі поттер та орден фенікса гарри поттер тата феникс орденӗ хәрри поттер және самұрық ордені ہیری پوٹر اور ققنس کا گروہ هری پاتر و محفل ققنوس ہیری پوٹر اینڈ دی آرڈر اف فینیکس ہیری پوٹر تہٕ پھینِک سٕنٛز جماعت हैरी पॉटर और मायापंछी का समूह हॅरी पॉटर अँड द ऑर्डर ऑफ द फिनिक्स ਹੈਰੀ ਪੌਟਰ ਐਂਡ ਦ ਔਰਡਰ ਔਫ਼ ਦ ਫ਼ੀਨਿਕਸ ஆரி பாட்டர் அண்டு த ஆர்டர் ஆப் த பீனிக்சு ഹാരി പോട്ടർ ആന്റ് ദ ഓർഡർ ഓഫ് ദ ഫീനിക്സ് ჰარი პოტერი დო ფენიქსიშ ორდენი ჰარი პოტერი და ფენიქსის ორდენი harry potter 5 harry potter 5 - order of the phoenix harry potter 5 - the order of the phoenix harry potter and the order of the phoenix', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-giang-sinh-kinh-hoang-2007', 'Đêm Giáng Sinh Kinh Hoàng', 'P2', 'https://phimimg.com/upload/vod/20250522-1/a8b4f3c55d3762d72cca6cd75eeb9103.jpg', 'https://phimimg.com/upload/vod/20250522-1/e38c60126fb88b93edfd4c846d9576c2.jpg', '<p>Phim kể về Angela Bridges, một nữ doanh nhân bị mắc kẹt trong tầng hầm bãi đỗ xe vào đêm Giáng sinh, nơi cô phải đối mặt với một nhân viên bảo vệ có tâm lý bất ổn. Bộ phim mang đến không khí căng thẳng và kịch tính với yếu tố sinh tồn đặc trưng của dòng phim kinh dị.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rachel Nichols","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Simon Reynolds","avatar":""},{"name":"Philip Akin","avatar":""},{"name":"Miranda Edwards","avatar":""},{"name":"Paul Sun-Hyung Lee","avatar":""},{"name":"Grace Lynn Kung","avatar":""},{"name":"Philip Williams","avatar":""},{"name":"Arnold Pinnock","avatar":""},{"name":"Bathsheba Garnett","avatar":""},{"name":"Franck Khalfoun","avatar":""},{"name":"Stephanie Moore","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["P2 - A rettegés új szintje","2ème Sous-Sol","El nivel del pánico","-2 Il Livello del Terrore","Parking 2","Piso 2 El Nivel del Panico","پارکینگ شمار ۲","P2 - Sem Saída","P2: Ново ниво на страх","Парковка","P2"]', 1784690324487);
