INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-chuyen-phieu-luu-vao-xu-quy', 'Doraemon : Nobita và Chuyến Phiêu Lưu Vào Xứ Quỷ', 'Doraemon: Nobita''s New Great Adventure Into the Underworld - The Seven Magic Users', 'https://phimimg.com/upload/vod/20250521-1/3f80260092c3edd84606b32490e9a449.jpg', 'https://phimimg.com/upload/vod/20250521-1/5f99888b63adc7d3ceef621861b1ef69.jpg', '<p>Câu chuyện được bắt đầu với giấc mơ về một thế giới phù thủy của Nôbita. Tuy được Đêkhi giải thích rõ ràng nhưng Nôbita vẫn không nguôi mơ mộng về một thế giới phép thuật. Cùng với đó là sự xuất hiện của hai pho tượng đá Nôbita và Đôrêmon một cách bí ẩn...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2007, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Shihoko Hagino","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Sachi Matsumoto","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Saki Aibu","avatar":""},{"name":"Tamaki Matsumoto","avatar":""},{"name":"Jun''ichi Kômoto","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Masami Hisamoto","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["新魔界大冒險",