INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-den-bon-mat', 'Ngọn Đèn Bốn Mặt', 'The Four-Faced Lamp', 'https://phimimg.com/upload/vod/20250406-1/bb6b21aa98336af5c719de3ecefa1389.jpg', 'https://phimimg.com/upload/vod/20250406-1/238f94eb7b1965c8a1742878c3013aff.jpg', '<p>&quot;Ngọn Đèn Bốn Mặt&quot; dựa trên truyện ngắn &quot;Người Giữ Cồn&quot; của Nguyễn Thế Hùng, từng đoạt giải nhất cuộc thi &quot;Truyện ngắn ĐBSCL 2005&quot;. Bộ phim do Đài Phát thanh Truyền hình TP Cần Thơ hợp tác với Hãng phim Giải Phóng sản xuất nhân kỷ niệm 60 năm ngày thương binh liệt sĩ (27/7/1947 – 27/7/2007).</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hữu Thành","avatar":""},{"name":"Ngọc Thảo","avatar":""},{"name":"Mai Mai","avatar":""},{"name":"Tăng Bảo Quyên","avatar":""},{"name":"Trí Cường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324487);
