INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-tham-hiem', 'Siêu Nhân Thám Hiểm', 'Power Rangers Operation Overdrive', 'https://phimimg.com/upload/vod/20250401-1/126f97566d0b03d682377755d6613eba.jpg', 'https://phimimg.com/upload/vod/20250401-1/c9b551e85a473abb8ab96bce1ba36811.jpg', '<p>Năm cá nhân dũng cảm, tài giỏi và gan dạ—Mack Hartford, Will Aston, Dax Lo, Ronny Robinson và Rose Ortiz—được tỷ phú thám hiểm Andrew Hartford (cha của Mack) lựa chọn và cải tiến bằng công nghệ di truyền để trở thành Power Rangers Overdrive. Họ được giao một nhiệm vụ quan trọng: du hành khắp thế giới để tìm kiếm năm viên ngọc ma thuật từng thuộc về vương miện Corona Aurora trước khi rơi vào tay hai anh em phản diện Flurious và Moltor. Trên hành trình này, nhóm Ranger không chỉ phải đối đầu với Flurious và Moltor mà còn chạm trán với hai thế lực tà ác khác là Kamdor và Fearcats. May mắn thay, họ nhận được sự giúp đỡ từ một người ngoài hành tinh tên Tyzonn, người đã gia nhập đội để cùng chiến đấu chống lại kẻ thù hùng mạnh.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324487);
