INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-chuot-dau-bep', 'Chú Chuột Đầu Bếp', 'Ratatouille', 'https://phimimg.com/upload/vod/20250327-1/cb97b67955cfeee5225f6f769d06f849.jpg', 'https://phimimg.com/upload/vod/20250327-1/7ae7d5e55b886dede42f753c4f628db7.jpg', '<p>Remy là một chú chuột có lòng yêu thích ẩm thực và mong muốn được đến Paris để thực hiện ước mơ trở thành đầu bếp nổi tiếng. Tuy bị gia đình ngăn cản nhưng cuối cùng Remy cũng đặt chân được đến kinh đô ánh sáng và bắt đầu cuộc phiêu lưu của mình. &nbsp;Tại đây, Remy quen Linguini - cậu con trai của thần tượng đồng thời là bếp trưởng nổi tiếng của nhà hàng Gusteau. Remy và Linguini trở thành cặp bài trùng trong việc chế biến các món ăn mới lạ, đồng thời chứng mình quan niệm của Gusteau: &quot;Ai cũng có thể nấu ăn ngon&quot;.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2007, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patton Oswalt","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Lou Romano","avatar":""},{"name":"Brian Dennehy","avatar":""},{"name":"Peter Sohn","avatar":""},{"name":"Peter O''Toole","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Janeane Garofalo","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Julius Callahan","avatar":""},{"name":"James Remar","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Teddy Newton","avatar":""},{"name":"Tony Fucile","avatar":""},{"name":"Jake Steinfeld","avatar":""},{"name":"Brad Bird","avatar":""},{"name":"Stéphane Roux","avatar":""},{"name":"Jack Bir","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["美食总动员","O ratatouis","Juhu-hu","Remî no oishî resutoran","Remy''s Delicious Restaurant","La troskinys","Mućkalica","Ratatouille - Dobrú chut!","Chú Chuột Đầu Bếp","Delicious Ratatouille 3D","Ratatui","라따뚜이","Rottatouille","خلطة بيطة بالصلصة","Ratatouille 3D","五星级大鼠","موش سرآشپز","Ratatouille [COLOR yellow]مدبلج[/COLOR]","Ratatatira","Juhu hu","Råttatouille","L’ecsó","Ratatouille"]', 1784690324487);
