INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-chuot-dau-bep', 'Chú Chuột Đầu Bếp', 'Ratatouille', 'chú chuột đầu bếp ratatouille patton oswalt ian holm lou romano brian dennehy peter sohn peter o''toole brad garrett janeane garofalo will arnett julius callahan james remar john ratzenberger teddy newton tony fucile jake steinfeld brad bird stéphane roux jack bir 美食总动员 o ratatouis juhu-hu remî no oishî resutoran remy''s delicious restaurant la troskinys mućkalica ratatouille - dobrú chut! chú chuột đầu bếp delicious ratatouille 3d ratatui 라따뚜이 rottatouille خلطة بيطة بالصلصة ratatouille 3d 五星级大鼠 موش سرآشپز ratatouille [color yellow]مدبلج[/color] ratatatira juhu hu råttatouille l’ecsó ratatouille', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-bat-thanh', 'Âm Mưu Bất Thành', 'The Slicing of the Demon', 'https://phimimg.com/upload/vod/20250324-1/c67c7e3828dcef1bd7d42b5839ba322e.jpg', 'https://phimimg.com/upload/vod/20250324-1/9711f634732f853f46ef298837f3d77e.jpg', '<p>Phim lấy bối cảnh Trung Quốc thời nhà Minh, Đồ Tứ Hải là một đao phủ kết nghĩa anh em cùng Thủy như Trần. Hai người lạc vào một nơi gọi là Trấn Thiên Long, một nơi cảnh vật thanh bình nhưng nơi đây ẩn chứa một bí mật vô cùng to lớn. Nơi đây có đại sư Thiên Mạng và Thiện Dao là con gái của ông. Thiện Dao và Như Trần nảy sinh tình cảm với nhau và họ trở thành phu phụ. Trấn Xương Long từ một vùng đất yên bình, nay bổng chốc xảy ra rất nhiều án mạng, không một ai biết thủ phạm là những người nào, thật đáng sợ với những bí mật ẩn chứa tại vùng đất vốn bình yên trước đó.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 21, 2007, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Bernice Jan Liu","avatar":""},{"name":"Angela Tong Ying-Ying","avatar":""},{"name":"Elliot Ngok Wah","avatar":""},{"name":"Charmaine Li","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Sherming Yiu Lok-yee","avatar":""},{"name":"Henry Lo Chun-Shun","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Ellesmere Choi","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"Steve Lee Ka-Ting","avatar":""},{"name":"Thomas Sin Ho-Y","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["凶城计","The Slicing Of The Demon","凶城計中計"]', 1784690324487);
