INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-muu-bat-thanh', 'Âm Mưu Bất Thành', 'The Slicing of the Demon', 'âm mưu bất thành the slicing of the demon michael tse tin-wah sunny chan kam-hung bernice jan liu angela tong ying-ying elliot ngok wah charmaine li benz hui siu-hung sherming yiu lok-yee henry lo chun-shun samuel kwok fung ellesmere choi savio tsang steve lee ka-ting thomas sin ho-y 凶城计 the slicing of the demon 凶城計中計', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-o-bac-kinh', 'Lạc Lối Ở Bắc Kinh', 'Lost In Beijing', 'https://phimimg.com/upload/vod/20250305-1/529fade490d9f070115e2b9266787989.jpg', 'https://phimimg.com/upload/vod/20250305-1/9a91b6167a44b87cda6c6aec8c5888b8.jpg', '<p>Tại Bắc Kinh có đôi vợ chồng trẻ: Kiên (Đồng Đại Vy) và Táo (Phạm Băng Băng). Chồng làm nghề lau kiếng cho các căn hộ cao ốc, vợ làm massage. Táo chơi thân với một cô bé trong tiệm tên Tiểu Mai. Vì chống lại một người khách sàm sỡ, Tiểu Mai bị đuổi, Táo đi uống rượu cùng Tiểu Mai rồi về tiệm nằm ngủ hớ hênh bị ông chủ (Lương Gia Huy) cưỡng bức. Thoạt tiên cô chống đỡ nhưng sau đó lại cam chịu. Trong khi đó, Kiên đang lau kiếng ở bên ngoài trông thấy đã xông vào gây hấn. Sau đó Táo có mang, Kiên nghĩ đứa bé trong bụng vợ là của ông chủ. Còn ông chủ do vợ không sinh con được nên cảm thấy đứa bé như của trời ban cho mình. Rắc rối càng lớn khi hai người đàn ông đều muốn mình là cha của đứa bé, còn hai người phụ nữ đều cảm thấy khó xử. Cảnh sát vào cuộc, giám định ADN cho biết đứa bé là con của đôi vợ chồng Kiên-Táo. Ông chủ hụt hẫng nhưng vẫn không tin. Kết phim, Táo bế con ra đi, cô không cần ai, kể cả anh chồng Kiên ích kỷ lẫn ông chủ giàu có.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Băng Băng","avatar":""},{"name":"Lương Gia Huy","avatar":""},{"name":"Đồng Đại Vĩ","avatar":""},{"name":"Tằng Mỹ Huệ Tư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ping Guo","Lost in Beijing","蘋果","蘋果 (2007)","苹果"]', 1784690324487);
