INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lac-loi-o-bac-kinh', 'Lạc Lối Ở Bắc Kinh', 'Lost In Beijing', 'lạc lối ở bắc kinh lost in beijing phạm băng băng lương gia huy đồng đại vĩ tằng mỹ huệ tư ping guo lost in beijing 蘋果 蘋果 (2007) 苹果', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-cua-nuoc-mat', 'Người Mẹ Của Nước Mắt', 'Mother Of Tears', 'https://phimimg.com/upload/vod/20250226-1/61e547ef702e58a90ff0ba67a7e2a97a.jpg', 'https://phimimg.com/upload/vod/20250226-1/98b2d0606495c57e39b990785d7a61de.jpg', '<p>Một chiếc bình cổ được tìm thấy trong một nghĩa trang bên ngoài Rome. Khi được mở ra, nó kích hoạt hàng loạt sự kiện bạo lực: trộm cướp, hiếp dâm và giết người gia tăng đột biến, trong khi nhiều phụ nữ trẻ với vẻ ngoài bí ẩn và tà ác từ khắp nơi trên thế giới đổ về thành phố. Tất cả những điều này đều bắt nguồn từ sự trở lại của Mater Lacrimarum—phù thủy cuối cùng trong ba phù thủy hùng mạnh đã gieo rắc nỗi kinh hoàng và chết chóc suốt nhiều thế kỷ. Giữa một đội quân điên loạn và quỷ dữ, Sarah Mandy—một sinh viên nghệ thuật với những năng lực siêu nhiên bí ẩn—là người duy nhất có thể ngăn chặn Mẹ của Nước Mắt hủy diệt Rome.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Asia Argento","avatar":""},{"name":"Cristian Solimeno","avatar":""},{"name":"Adam James","avatar":""},{"name":"Moran Atias","avatar":""},{"name":"Valéria Cavalli","avatar":""},{"name":"Philippe Leroy","avatar":""},{"name":"Daria Nicolodi","avatar":""},{"name":"Coralina Cataldi-Tassoni","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Robert Madison","avatar":""},{"name":"Jun Ichikawa","avatar":""},{"name":"Silvia Rubino","avatar":""},{"name":"Barbara Mautino","avatar":""},{"name":"Paolo Stella","avatar":""},{"name":"Simonetta Solder","avatar":""},{"name":"Stefano Fregni","avatar":""},{"name":"Gi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La madre del mal","O Retorno da Maldição - AMãe das Lágrimas","Mother of Tears: The Third Mother","Мать слез","Matka łez","눈물의 마녀","Mother of Tears","サスペリア・テルザ 最後の魔女","La terza madre"]', 1784690324487);
