INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung', 'Mê Cung', 'Bhool Bhulaiyaa', 'https://phimimg.com/upload/vod/20250216-1/8b729f2bc2e947260a8481d32f6ed7aa.jpg', 'https://phimimg.com/upload/vod/20250216-1/5ce9f922df5c3763fbf1eadfcd1372b6.jpg', '<p>NRI Siddharth Chaturvedi và vợ anh, Avni, trở về cung điện tổ tiên của gia đình Siddharth ở Varanasi, mặc kệ những cảnh báo về lời nguyền và các hiện tượng siêu nhiên. Chẳng bao lâu sau, những sự kiện khó giải thích bắt đầu xảy ra, buộc Siddharth phải tìm đến nhà tâm lý học lập dị Aditya Shrivastav để giúp giải quyết bí ẩn.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Vidya Balan","avatar":""},{"name":"Shiney Ahuja","avatar":""},{"name":"Paresh Rawal","avatar":""},{"name":"Ameesha Patel","avatar":""},{"name":"Manoj Joshi","avatar":""},{"name":"Rajpal Yadav","avatar":""},{"name":"Govardhan Asrani","avatar":""},{"name":"Rasika Joshi","avatar":""},{"name":"Vikram Gokhale","avatar":""},{"name":"Vineeth Radhakrishnan","avatar":""},{"name":"Kaveri Jha","avatar":""},{"name":"Tarina Patel","avatar":""},{"name":"Farida Dadi","avatar":""},{"name":"Jimit Trivedi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Labyrinth","भूल भुलैया"]', 1784690324487);
