INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-ca-phe-hoang-tu', 'Tiệm Cà Phê Hoàng Tử', 'Coffee Prince', 'https://phimimg.com/upload/vod/20250216-1/cfd009020ff86927ed4a7821cfef1f85.jpg', 'https://phimimg.com/upload/vod/20250216-1/465eceae7275d71a527593ef0ba7011f.jpg', '<p>Câu chuyện cổ tích thời hiện đại hài hước nhưng không kém phần lãng mạn, xoay quanh hai nhân vật là Go Eun Chae-một cô gái ngỗ nghịch giỏi võ có bề ngoài giống hệt con trai và có thể làm tất cả mọi việc để lo cho gia đình, trong khi Choi Han Kyun-là con cưng trong một gia đình giàu sang, có một tiệm cà phê riêng và không bao giờ tin vào một tình yêu đích thực…</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 21, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Gong Yoo","avatar":""},{"name":"Yoon Eun-hye","avatar":""},{"name":"Lee Sun-kyun","avatar":""},{"name":"Chae Jung-an","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Kim Jae-wook","avatar":""},{"name":"Lee Eon","avatar":""},{"name":"Kim Yeong-ok","avatar":""},{"name":"Choi Il-hwa","avatar":""},{"name":"Kim Ja-ok","avatar":""},{"name":"Park Won-sook","avatar":""},{"name":"Yoon Ji-yoo","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Ban Hye-ra","avatar":""},{"name":"Lee Ji Wan","avatar":""},{"name":"Nam Myung-ryeol","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Príncipe do Café","咖啡王子一号店","Keo-pi Peu-rin-seu 1-ho-jeom","Kapi Peurinseu","Coffee Prince 1 Hojeom","Kapi Peurinseu 1hojeom","커피 프린스 1호점","커피프린스1호점","The 1st Shop of Coffee Prince","Coffee Prince","커피프린스 1호점"]', 1784690324487);
