INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-co-dieu-toan-luu-ba-on-phan-8', 'Thần Cơ Diệu Toán Lưu Bá Ôn (Phần 8)', 'The Amazing Strategist Liu Bowen (Season 8)', 'thần cơ diệu toán lưu bá ôn (phần 8) the amazing strategist liu bowen (season 8) huỳnh thiếu kỳ dương hoài dân hoắc chính kỳ trần á lan giải bá ân dương tuấn ngạn tống đạt dân trần văn sơn vương vũ tiệp 神机妙算刘伯温 shen ji miao suan liu bo wen 神機妙算劉伯溫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-co-dieu-toan-luu-ba-on-phan-7', 'Thần Cơ Diệu Toán Lưu Bá Ôn (Phần 7)', 'The Amazing Strategist Liu Bowen (Season 7)', 'https://phimimg.com/upload/vod/20250202-1/9bdc8248f1ecc499eee05b89a1303df7.jpg', 'https://phimimg.com/upload/vod/20250202-1/1bca028a1d639daba311baa39edc44be.jpg', '<p><span style="text-wrap-mode: wrap;">Lưu Bá Ôn là nhân vật có thật trong lịch sử, Lưu Cơ sinh năm 1311, mất năm 1375 tự Bá Ôn. Ông là người cuối đời Nguyên đầu đời minh ở huyện Thanh Điền, tỉnh Chiết Giang. Vốn thông minh cơ trí hơn người lại tinh thông kinh sử, am hiểu kỳ môn độn giáp và cũng không hề kém cỏi võ công, Lưu Bá Ôn góp công không nhỏ trong công cuộc bình phục Trung Nguyên, thống nhất thiên hạ của Minh Thái Tổ. Triều Minh, Lưu Bá Ôn được xem là khai quốc công thần, là cánh tay đắc lực của Hoàng đế Chu Nguyên Chương. Nhưng cũng chính vì sự hơn người ấy, Lưu đã gặp không ít khó khăn do sự tị hiềm của kẻ xấu. Sau khi đánh bại Trần Hữu Lượng, Trương Sĩ Thành, vị Đại Minh Khai Quốc Hoàng đế Chu Nguyên Chương chính thức lên ngôi. Trong ngày đầu lập quốc, Hoàng đế thống lĩnh văn võ bá quan làm lễ tế trời. Bầu trời đột nhiên xuất hiện hiện tượng kỳ lạ “Thiên cẩu thực nhật”. Hoàng đế hoảng sợ, triều thần hoang mang cho rằng yêu ma tác quái. Chỉ duy Lưu Bá Ôn có đủ sự tinh tường, am hiểu để nhận ra đó là hiện tượng nhật thực. Sau khi được Lưu Bá Ôn giải thích cặn kẽ, Hoàng đế phẫn nộ với đám triều thần nông cạn kiến thức nhưng lại thích khoe khoang, a dua. Sự kiện này ngay lập tức đẩy Lưu Bá Ôn và Thừa tướng Hồ Duy Dung vào thế đối nghịch nhau. Lợi dụng tình yêu của Chu Hoàng Đế dành cho Nam Phong – công chúa triều Nguyên, và tình yêu của A Tú – thanh mai trúc mã của Lưu Bá Ôn – dành cho Lưu Bá Ôn, Hồ Thừa Tướng âm thầm gây nên sóng gió trong cung đình Đại Minh. Cũng từ đó, triều Minh chao đảo trong làn sóng đấu tranh do bọn gian thần gây nên … Thuộc thể loại phim kiếm hiệp, hài, bộ phim “Lưu Bá Ôn” không chỉ đem đến tiếng cười cho khán gỉa mà còn giúp khán giả hiểu thêm về một nhân vật có thật trong lịch sử Trung Hoa.</span></p>', 'Hoàn Tất (208/208)', 208, 'series', 'completed', 26, 2007, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Huỳnh Thiếu Kỳ","avatar":""},{"name":"Dương Hoài Dân","avatar":""},{"name":"Hoắc Chính Kỳ","avatar":""},{"name":"Trần Á Lan","avatar":""},{"name":"Giải Bá Ân","avatar":""},{"name":"Dương Tuấn Ngạn","avatar":""},{"name":"Tống Đạt Dân","avatar":""},{"name":"Trần Văn Sơn","avatar":""},{"name":"Vương Vũ Tiệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["神机妙算刘伯温","Shen Ji Miao Suan Liu Bo Wen","神機妙算劉伯溫"]', 1784690324487);
