INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-tu-mon', 'Song Tử Môn', 'Twins Mission', 'https://phimimg.com/upload/vod/20250112-1/11bf578f673877a1f5a4d4c03a9ce87f.jpg', 'https://phimimg.com/upload/vod/20250112-1/19f2c596dfad64c53faa4346b0256898.jpg', '<p>Song Tử Môn là bộ phim hành động xoay quanh tên trộm trứ danh từ lâu đã biến mất nhưng bỗng dưng lại xuất hiện để thực hiện một vụ cướp táo bạo trên tàu. Lilian có đứa em bị bệnh nan y, vào lúc cô tuyệt vọng nhất thì có người tặng cô một món bảo vật có khả năng chữa bệnh, đó chính là món đồ bị đánh cắp...</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Charlene Choi Cheuk-Yin","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Sammo Hung Kam-Bo","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Jess Zhang","avatar":""},{"name":"Steven Cheung Chi-Hang","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Cody Liang","avatar":""},{"name":"Andy Liang","avatar":""},{"name":"Mona","avatar":""},{"name":"Lisa","avatar":""},{"name":"Long Ze","avatar":""},{"name":"Long Fei","avatar":""},{"name":"Albert Leung","avatar":""},{"name":"Herbert Leung","avatar":""},{"name":"Gao Shan","avatar":""},{"name":"Bobby Yip Kin-Sang","avatar":""},{"name":"Chen Hao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Двойная миссия","Twins Mission","คู่พายุ ฟัดทะลุฟ้า","雙子神偸"]', 1784690324487);
