INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lee-san-trieu-dai-chosun', 'Lee San Triều Đại Chosun', 'Lee San Wind Of The Palace', 'https://phimimg.com/upload/vod/20241108-1/b0e05edf159b28893309bc889ebe025c.jpg', 'https://phimimg.com/upload/vod/20241108-1/2972d48448f350c686cc8b83539da732.jpg', '<p>Câu chuyện kể về vị vua thứ 22 của triều đại Joseon vào thế kỷ 18 của Triều Tiên. Ông là một vị vua khôn ngoan, tiếp thu nhiều cái mới và luôn đấu tranh vì giá trị của nền dân chủ. Phim tập hợp những câu chuyện về những chiến thắng huy hoàng, những thành tựu lịch sử cũng như những tiếc nuối của vị vua lẫy lừng này như dẹp tan quân phiến loạn, xây dựng pháo đài Hwvaieong - một thành tựu kiến trúc nổi bật cho đến ngày nay, sự chuyển mình từ nền kinh tế gia đình thành kinh tế thương mại... Đặc biệt, tình yêu giữa vua Lee San và nàng Song Yeung giỏi vẽ được khắc họa rất ấn tượng. Ngay từ tập 1, cuộc gặp gỡ định mệnh giữa Lee San khi còn là một cậu bé 11 tuổi và cô bé mới vào cung học nghề Song Yeung đã là mối nhân duyên cho một cuộc tình dài 30 năm đầy nghịch cảnh nhưng rất lãng mạn giữa một vị hoàng đế và một thường dân.</p>', 'Hoàn Tất (77/77)', 77, 'series', 'completed', 12, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Seo-jin","avatar":""},{"name":"Han Ji-min","avatar":""},{"name":"Lee Soon-jae","avatar":""},{"name":"Kyeon Mi-ri","avatar":""},{"name":"Sung Hyun-ah","avatar":""},{"name":"Kim Yeo-jin","avatar":""},{"name":"Park Eun-hye","avatar":""},{"name":"Lee Jong-soo","avatar":""},{"name":"Han Sang-jin","avatar":""},{"name":"Lee Da-wit","avatar":""},{"name":"Lee Jae-yong","avatar":""},{"name":"Park Ji-bin","avatar":""},{"name":"Jo Yeon-woo","avatar":""},{"name":"Cha Woong-ki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["李祘","යහපත් මහරජ","Lee San: The Wind of the Palace","ลีซาน จอมบัลลังก์พลิกแผ่นดิน","Wind of the Palace","Yi San","이산"]', 1784690324487);
