INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-sach-vo', 'Theo Sách Vở', 'Going by the Book', 'https://phimimg.com/upload/vod/20241106-1/16208e858f872f797a6f583eeb125cf2.jpg', 'https://phimimg.com/upload/vod/20241106-1/1f241a72f3592f18acc5ab2400d3895e.jpg', '<p>Giám đốc Văn phòng Cảnh sát Thành phố Sampo, Seung-u, tổ chức mô phỏng một vụ cướp ngân hàng, nhưng một cảnh sát trong sách quá bị cuốn vào trò nhập vai khiến mô phỏng không diễn ra theo cách anh ta dự đoán.</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Jae-young","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Shin Goo","avatar":""},{"name":"Lee Yong-i","avatar":""},{"name":"Kim Kyu-chul","avatar":""},{"name":"Lee Young-eun","avatar":""},{"name":"Im Ji-eun","avatar":""},{"name":"Uhm Soo-jung","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Min Ji-hwan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Bareuge Salja","Going by the Book","Ограбление","바르게 살자"]', 1784690324487);
