INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-son-phi-ho', 'Tuyết Sơn Phi Hồ', 'Fox Volant Of The Snowy', 'https://phimimg.com/upload/vod/20241104-1/dd48ecb48de3860a75daf545ffe44f7c.jpg', 'https://phimimg.com/upload/vod/20241104-1/585d75d0badcd803dba2f7acfee9b4b3.jpg', '<p>Tuyết sơn phi hồ xoay quanh bốn gia tộc họ Miêu, Hồ, Phạm và Điền. Ba nhà Miêu – Phạm - Điền hãm hại nhà họ Hồ. Trước khi chết, Hồ Nhất Đao kịp giao đứa con trai duy nhất của dòng họ là Hồ Phỉ cho Bình An Tứ nuôi dưỡng. Trưởng thành, Hồ Phỉ tìm cách trả thù cho cha mẹ và trong chuyến bôn tẩu giang hồ, anh đã gặp được sự giúp đỡ của rất nhiều nguời, đồng thời anh cũng bị xoáy vào vòng đấu tranh quyền lực của triều đình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 31, 2007, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhiếp Viễn","avatar":""},{"name":"Chu Ân","avatar":""},{"name":"Chung Hân Đồng","avatar":""},{"name":"An Dĩ Hiên","avatar":""},{"name":"Phương Trung Tín","avatar":""},{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Đàm Diệu Văn","avatar":""},{"name":"Lữ Nhất","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Fox Volant of the Snowy Mountain","雪山飛狐"]', 1784690324487);
