INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-quoc-gia', 'Mật Mã Quốc Gia', 'Fay Grim', 'https://phimimg.com/upload/vod/20241031-1/b32a0ab233cd045d68d4b5dc19cc3e8a.jpg', 'https://phimimg.com/upload/vod/20241031-1/c816f22ebe3887f7489010d6621b8572.jpg', '<p>Nhiều năm sau khi người chồng khét tiếng của cô, Henry Fool, bỏ trốn sau khi giết một người hàng xóm, Fay Grim (Parker Posey) nhận được chuyến thăm từ đặc vụ CIA Fulbright (Jeff Goldblum), người nói với cô rằng Henry đã chết, nhưng một số nhật ký của anh đã bị xóa. được khai quật ở Pháp. Cô bắt đầu một cuộc phiêu lưu vòng quanh thế giới và sớm dẫn đến việc phát hiện ra rằng anh ấy còn sống, và những cuốn nhật ký của anh ấy còn nhiều hơn những gì chúng thể hiện.</p><p>Fay Grim là một bộ phim kinh dị gián điệp năm 2006 do Hal Hartley viết kịch bản và đạo diễn. Bộ phim là phần tiếp theo của bộ phim Henry Fool năm 1997 của Hartley.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Parker Posey","avatar":""},{"name":"Liam Aiken","avatar":""},{"name":"James Urbaniak","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"D.J. Mendel","avatar":""},{"name":"Megan Gay","avatar":""},{"name":"Jasmin Tabatabai","avatar":""},{"name":"Chuck Montgomery","avatar":""},{"name":"John Keogh","avatar":""},{"name":"Claudia Michelsen","avatar":""},{"name":"Leo Fitzpatrick","avatar":""},{"name":"Sibel Kekilli","avatar":""},{"name":"Thomas Jay Ryan","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Miho Nikaido","avatar":""},{"name":"Elina Löwensohn","avatar":""},{"name":"Jef Bayonn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fej Grim","Fay Grim"]', 1784690324487);
