INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-vu-em', 'Nhật Ký Vú Em', 'The Nanny Diaries', 'https://phimimg.com/upload/vod/20241021-1/6854ac1670e012bd67526c8a2dfbb046.jpg', 'https://phimimg.com/upload/vod/20241021-1/0ad67ee71c876489828ca69e8f915fb0.jpg', '<p>Nhật Ký Vú Em - The Nanny Diaries xoay quanh Annie - cô gái xinh đẹp vừa tốt nghiệp đại học. Một tình huống bất ngờ đã đẩy Annie trở thành người trông trẻ. Thế nhưng công việc tưởng như nhẹ nhàng này thật sự không hề đơn giản khi cô phải đối phó với sự điên rồ của chủ nhà, một mối tình chớm nở và cậu nhóc khó bảo mà cô nhận chăm sóc.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Alicia Keys","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Donna Murphy","avatar":""},{"name":"Nicholas Art","avatar":""},{"name":"Judith Roberts","avatar":""},{"name":"Julie White","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"John Henry Cox","avatar":""},{"name":"Lewis Payton","avatar":""},{"name":"Jr.","avatar":""},{"name":"Sonnie Brown","avatar":""},{"name":"Georgina Chapman","avatar":""},{"name":"Jodi Michelle Pynn","avatar":""},{"name":"Mike Rad","avatar":""},{"name":"Joanna Heimbold","avatar":""},{"name":"Marla Suc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Die Tagebücher einer Nanny","El diario de la niñera","Una niñera en apuros","Le Journal d''une nanny","Lastenhoitajan päiväkirja","私がクマにキレた理由","Νταντά Υψηλής Κοινωνίας","O Diário de Uma Babá","De