INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-trinh-nu', 'Thế Giới Của Trinh Nữ', 'Virgin Territory', 'https://phimimg.com/upload/vod/20241016-1/7b3cd47785309bb438c886aa94e45b1a.jpg', 'https://phimimg.com/upload/vod/20241016-1/70d04bf82a63ae8ac1dfb5e68b319607.jpg', '<p>Trong thời kỳ Cái chết đen ở Tuscany, cũng như trong Decameron, mười thanh niên Florentines chạy trốn khỏi bệnh dịch. Nhưng thay vì kể chuyện, họ có những cuộc phiêu lưu đầy ham muốn, những cuộc trao đổi tục tĩu, lãng mạn, đấu kiếm, những nữ tu ngang ngược, những tên cướp biển Saracen và một con bò gợi cảm.</p>', 'Full', 1, 'single', 'completed', 31, 2007, 'Vietsub', 'FHD', 'Luxembourg', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Mischa Barton","avatar":""},{"name":"Kate Groombridge","avatar":""},{"name":"Rosalind Halstead","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Matthew Rhys","avatar":""},{"name":"Ryan Cartwright","avatar":""},{"name":"Christopher Egan","avatar":""},{"name":"Anna Galiena","avatar":""},{"name":"Silvia Colloca","avatar":""},{"name":"Jay Villiers","avatar":""},{"name":"Simone Spinazzè","avatar":""},{"name":"Craig Parkinson","avatar":""},{"name":"Chiara Gensini","avatar":""},{"name":"Katy Louise Saunders","avatar":""},{"name":"Elisabet","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Medieval Pie : Territoires Vierges","Szűzlányok ajándéka","Aprendiz de caballero","Território Virgem","Angeloi & parthenes","Andjeli i djevice","Decameron Pie","Dekameron","Anjos e Virgens","Територiя незайманостi","Angels and Virgins","Decameron: Angels & Virgins","Virgin Territory"]', 1784690324487);
