INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-ben-thuong-hai-2007', 'Tân Bến Thượng Hải', 'Shanghai Bund', 'https://phimimg.com/upload/vod/20241007-1/9bfc85757be495f55dbddb5a502d0afa.jpg', 'https://phimimg.com/upload/vod/20241007-1/280c01d0054f0abfe0b5baf95b387946.jpg', '<p>Tân Bến Thượng Hải xoay quanh cuộc tranh giành quyền lực của các băng nhóm ở Thượng Hải vào những năm 1930. Trong thời gian đó, Thượng Hải bị chia năm xẻ bảy, những nước đại cường quốc như Anh, Pháp, Mỹ, Nhật... chiếm đóng từng khu vực gọi là &quot;tô giới&quot;. Nhân vật chính là Hứa Văn Cường (Huỳnh Hiểu Minh thủ vai) đem lòng yêu Phùng Trình Trình (Tôn Lệ thủ vai) là con gái của ông trùm Phùng Kính Nghiêu. Sau nhiều biến cố cũng như mâu thuẫn đỉnh điểm diễn ra buộc Hứa Văn Cường phải rời Thượng Hải về HongKong sinh sống. Nhưng Phùng Kính Nghiêu vẫn không buông tha “ đuổi cùng giết tận” diệt môn cả gia đình Hứa Văn Cường. Căm phẫn đau thương đến tột cùng, Hứa Văn Cường quyết định trở về Thượng Hải trả thù…</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 15, 2007, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Huỳnh Hải Ba","avatar":""},{"name":"Lý Tuyết Kiện","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["新上海滩"]', 1784690324487);
