INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lucky-luke-di-ve-mien-vien-tay', 'Lucky Luke: Đi Về Miền Viễn Tây', 'Go West: A Lucky Luke Adventure', 'https://phimimg.com/upload/vod/20240928-1/2d605a203d26a9f0c2b10020f915706b.jpg', 'https://phimimg.com/upload/vod/20240928-1/a4094aa7d69c47201e7f183d5e9fdd02.jpg', '<p>Bộ phim&nbsp;là câu chuyền về chuyến phiêu lưu của chàng Lucky Luke, huyền thoại sống của miền Tây hoang dã. Lần này, Anh em nhà Dalton chạy trốn sự săn đuổi của Lucky Luke đến tận New York. Tại đây, không chịu ngoan ngoãn ẩn mình, anh em tội phạm này tìm cách lừa đảo một nhóm người nhập cư bất hợp pháp đáng thương bỏ tiền ra mua mảnh đất của nhà tài phiệt Crook. Sự vụ vỡ lở, chúng đổ tội cho Lucky Luke bằng một lá thư nặc danh hòng trốn tội. Liệu Crook sẽ tin lời bọn gian xảo hay tìm đến chàng cao bồi nổi tiếng để nhờ cậy?&quot;</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2007, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Lambert Wilson","avatar":""},{"name":"Clovis Cornillac","avatar":""},{"name":"François Morel","avatar":""},{"name":"Bernard Alane","avatar":""},{"name":"Edgar Givry","avatar":""},{"name":"Titoff","avatar":""},{"name":"Jean Piat","avatar":""},{"name":"Eric Métayer","avatar":""},{"name":"Dee Dee Bridgewater","avatar":""},{"name":"Adrien Antoine","avatar":""},{"name":"Marie Vincent","avatar":""},{"name":"Dorothée Pousséo","avatar":""},{"name":"François Siener","avatar":""},{"name":"Michael Lonsdale","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Lucky Luke Go West","Lucky Luke - Mod Vest!","Lucky Luke - Lähde Länteen!","Red Kit: Batıya Hücum","Tous à l''ouest, une aventure de Lucky Luke","Tous à l''ouest","Lucky Luke - Auf in den Westen","Lucky Luke - Go West","Λούκυ Λουκ: Τρελές περιπέτειες στην Άγρια Δύση","Lucky Luke: Treles peripeteies stin Agria Dysi","Lucky Luke – Auf in den Wilden Westen","Tous à l''ouest : Une aventure de Lucky Luke"]', 1784690324487);
