INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shrek-3', 'Shrek 3', 'Shrek The Third', 'https://phimimg.com/upload/vod/20240713-1/22a45d5c2e3f1ff19d1c2a6960ec7bdd.jpg', 'https://phimimg.com/upload/vod/20240713-1/b774ea0c97c5250219b75bc4ae0a1bcd.jpg', '<p>Cuộc sống nơi đầm lầy dường như chưa bao giờ đẹp đến thế với Shrek và Fiona, cho đến khi vua Harold đột nhiên đổ bệnh và chàng chằn tinh phải đi tìm người nối dõi.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Cameron Diaz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324487);
