INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-xa', 'Thiện Xạ', 'Shooter', 'https://phimimg.com/upload/vod/20231019-1/ab68ea219a24c46ec10798f955c5e6dd.jpg', 'https://phimimg.com/upload/vod/20231019-1/fcd824e9b25dcd7de229554534491590.jpg', '<p>Xạ thủ bắn tỉa cừ khôi nhất quân đội Mỹ được mời ngăn chặn âm mưu ám sát tổng thống. Khi biết đó chỉ là một cái bẫy, anh phải đơn thương độc mã chống lại những chính trị gia biến chất để minh oan cho mình.Bob Lee Swagger (Mark Wahlberg) là một lính bắn tỉa thuộc lực lượng lính thủy đánh bộ Mỹ. Với tài bắn tỉa trăm phát trăm trúng ở khoảng cách xa, anh nổi danh trong tất cả binh chủng với biệt danh “Bob cừ khôi”. Sau khi mất người bạn thân, cũng là đồng đội, trong một chiến dịch ở Ethiopia, Bob quay trở về bang Wyoming và xin rời ngũ. Quá đau buồn trước cái chết của bạn, anh dựng một ngôi nhà nhỏ trên núi và lên đó sống cùng một con chó săn. Anh chỉ liên hệ với thế giới bên ngoài thông qua mạng Internet.36 tháng đã trôi ...</p>', 'Full', 1, 'single', 'completed', 21, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Jonathan Walker","avatar":""},{"name":"Louis Ferreira","avatar":""},{"name":"Tate Donovan","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Alan C. Peterson","avatar":""},{"name":"Ned Beatty","avatar":""},{"name":"Lane Garrison","avatar":""},{"name":"Zak Santiago","avatar":""},{"name":"Michael-Ann Connor","avatar":""},{"name":"Roberto Lombardi","avatar":""},{"name":"Jonathan Euse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324487);
