INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-mua-vui', 'Dịch Vụ Mua Vui', 'Pleasure Factory', 'https://phimimg.com/upload/vod/20240910-1/b52726ad885e25130f8b6d059dfff679.jpg', 'https://phimimg.com/upload/vod/20240910-1/ec0fb9188966db7d4c238a3680421647.jpg', '<p>Một loạt các câu chuyện liên quan đến người tìm kiếm niềm vui và các nhà cung cấp dịch vụ giải trí trong một đêm ở Geylang, quận ánh sáng đỏ của Singapore. Có ba câu chuyện khác biệt, thống nhất chỉ bởi sự hiện diện của nhân vật từ tất cả các câu chuyện trong một quán ăn trên phố</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"楊貴媚","avatar":""},{"name":"Ananda Everingham","avatar":""},{"name":"Loo Zihan","avatar":""},{"name":"Katashi Chen","avatar":""},{"name":"Xuer","avatar":""},{"name":"Isabella Chen","avatar":""},{"name":"Jeszlene Zhou","avatar":""},{"name":"Ian Francis Low","avatar":""},{"name":"Vincent Tee","avatar":""},{"name":"Godfrey Yeo","avatar":""},{"name":"Theresa Chua","avatar":""},{"name":"Fish Chaar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324487);
