INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-khuyen', 'Siêu Khuyển', 'Underdog', 'https://phimimg.com/upload/vod/20231103-1/c48d3620978b29ead6dd12db05c0282f.jpg', 'https://phimimg.com/upload/vod/20231103-1/8d2c5119fe520e32979657abee79e457.jpg', '<p>Chú chó săn thỏ Shoeshine bị bạn bè trong lực lượng cảnh khuyển chế nhạo vì sự hậu đậu của mình. Vô tình, Shoeshine bị tiến sỹ Simon bắt đi làm thí nghiệm. Tai nạn khi đang tiến hành thử nghiệm đã khiến Shoeshine trở thành siêu khuyển Underdog. Siêu khuyển không chỉ có khả năng... nói chuyện với con người mà còn sở hữu sức mạnh siêu nhiên.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Lee","avatar":""},{"name":"Jim Belushi","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Taylor Momsen","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Alex Neuberger","avatar":""},{"name":"Larry Vigus","avatar":""},{"name":"Bates Wilder","avatar":""},{"name":"Frank Ridley","avatar":""},{"name":"Alexander ''Alex'' Garde","avatar":""},{"name":"Diana Shneider","avatar":""},{"name":"Samantha Bee","avatar":""},{"name":"John Franchi","avatar":""},{"name":"Ezra B","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]'