INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-shippuden', 'Naruto Shippuden', 'Naruto Shippuden', 'https://phimimg.com/upload/vod/20240902-1/906557a923eec92f176a1be6add31ac6.jpg', 'https://phimimg.com/upload/vod/20240902-1/7eed050b63a25cdde46ac7d4ca1383b7.jpg', '<p>Naruto Shippuden hay còn được gọi với cái tên quen thuộc Naruto phần 2 là phần tiếp theo của bộ phim hoạt hình nổi tiếng Naruto, lấy bối cảnh hai năm rưỡi sau khi Naruto rời làng Lá. Naruto Shippuden tiếp tục theo chân chàng ninja trẻ tuổi Naruto Uzumaki trong cuộc hành trình luyện tập cực khổ để trở thành ninja giỏi nhất. Trong khi đó, Akatsuki, một tổ chức bí ẩn tập hợp những ninja phản diện tài giỏi bậc nhất, đang từng bước thực hiện kế hoạch lớn của chúng, đe dọa sự an toàn của thế giới ninja. Naruto sẽ làm gì để bảo vệ làng Lá và những người mà cậu yêu quý?</p>', 'Hoàn Tất (500/500)', 500, 'hoathinh', 'completed', 15, 2007, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"竹内順子","avatar":""},{"name":"杉山紀彰","avatar":""},{"name":"中村千絵","avatar":""},{"name":"井上和彦","avatar":""},{"name":"森久保祥太郎","avatar":""},{"name":"日野聡","avatar":""},{"name":"石田彰","avatar":""},{"name":"石川英郎","avatar":""},{"name":"遠近孝一","avatar":""},{"name":"Keiko Nemoto","avatar":""},{"name":"くじら","avatar":""},{"name":"勝生真沙子","avatar":""},{"name":"江原正士","avatar":""},{"name":"飛田展男","avatar":""},{"name":"神奈延年","avatar":""},{"name":"朴璐美","avatar":""},{"name":"川田紳司","avatar":""},{"name":"Tomoyuki Dan","avatar":""},{"name":"小山力也","avatar":""},{"name":"水樹奈々","avatar":""},{"name":"大塚芳忠","avatar":""},{"name":"伊藤健太郎","avatar":""},{"name":"増川洋一","avatar":""},{"name":"田村ゆかり","avatar":""},{"name":"柚木涼香","avatar":""},{"name":"鳥海浩輔","avatar":""},{"name":"玄田哲章","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc2