INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('naruto-shippuden', 'Naruto Shippuden', 'Naruto Shippuden', 'naruto shippuden naruto shippuden 竹内順子 杉山紀彰 中村千絵 井上和彦 森久保祥太郎 日野聡 石田彰 石川英郎 遠近孝一 keiko nemoto くじら 勝生真沙子 江原正士 飛田展男 神奈延年 朴璐美 川田紳司 tomoyuki dan 小山力也 水樹奈々 大塚芳忠 伊藤健太郎 増川洋一 田村ゆかり 柚木涼香 鳥海浩輔 玄田哲章 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-11-kho-bau-duoi-day-dai-duong', 'Thám Tử Lừng Danh Conan 11: Kho Báu Dưới Đáy Đại Dương', 'Detective Conan: Jolly Roger in the Deep Azure', 'https://phimimg.com/upload/vod/20231019-1/b5149f1b0b92544294e9312a068ee2d6.jpg', 'https://phimimg.com/upload/vod/20231019-1/9ee7f33edae7816cc5823a3d67ac1e10.jpg', '<p>Thanh tra Satou và Takagi trong một lần bắt truy bắt tội phạm và làm chúng bị thuơng, một trong số chúng trong cơn hôn mê đã nhắc đến đảo Koumi.Thật tình cờ, đó cũng là nơi mà Kogoro Mouri, Ran, Sonoko, cùng đội thám tử nhí nghỉ mát. Koumijima (Đảo Koumi) là một hòn đảo đẹp nằm trên biển Thái Bình Dương. Nơi đây có một truyền thuyết nói rằng có một ngôi nhà cổ nằm dưới đáy biển được gọi là &quot;Biệt thự dưới đáy biển&quot; cùng với 2 nữ cướp biển, &quot;Anne Bonney&quot; và &quot;Mary Read&quot;, họ đã để lại số kho báu từ khỏang 300 năm trước.Ở nơi đó Conan đã gặp phải bọn săn lùng kho báu. Một trong những gã đó khi đang tìm kiếm &quot;Biệt thự dưới đáy biển&quot; thì bị cá mập tấn công rồi chết. Sau đó họ phát hiện rằng máu của cá đã được trét ...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2007, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Nobutoshi Canna","avatar":""},{"name":"Kenyu Horiuchi","avatar":""},{"name":"Takanobu Hozumi","avatar":""},{"name":"Atsuko Yuya","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
