INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-minh', 'Một Mình', 'Alone', 'https://phimimg.com/upload/vod/20240726-1/a8a37ec72b3e0612d40dcefd7d2f95d7.jpg', 'https://phimimg.com/upload/vod/20240726-1/e03467bf2fb163ab1b95d94895b289e6.jpg', '<p>Bộ phim xoay quanh Pim, người sống sót duy nhất sau cuộc phẫu thuật tách cặp song sinh dính liền. Khi trở về Thái Lan để thăm mẹ ốm, Pim bị ám ảnh bởi hồn ma của chị mình, Ploy, người đã chết trong cuộc phẫu thuật. Những sự kiện kỳ lạ xảy ra khiến Pim và bạn trai Wee phải đối mặt với quá khứ đen tối và sự thật đáng sợ.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Marsha Vadhanapanich","avatar":""},{"name":"Witaya Wasukraipaisarn","avatar":""},{"name":"Ratchanoo Bunchootwong","avatar":""},{"name":"Hatairat Egereff","avatar":""},{"name":"Rutairat Egereff","avatar":""},{"name":"Namo Tongkumnerd","avatar":""},{"name":"Chutikan Vimuktananda","avatar":""},{"name":"Chayakan Vimuktananda","avatar":""},{"name":"Nimit Luksameepong","avatar":""},{"name":"Yupawan Unnataravarangkool","avatar":""},{"name":"Michel Pardo","avatar":""},{"name":"Taechit Mingmongkol","avatar":""},{"name":"Po","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
