INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-huy-diet', 'Lệnh Hủy Diệt', 'Planet Terror', 'https://phimimg.com/upload/vod/20231029-1/0b681db99463d71e856a39fa2b79360b.jpg', 'https://phimimg.com/upload/vod/20231029-1/e0e4db627ff8889f9bd840e5f32f9ad0.jpg', '<p>“Planet Terror” kể về một nhóm người “không ai giống ai” gồm tên tội phạm Wray ( Freddy Rodriguez), vũ công thoát y Cherry ( Rose McGowan), bác sĩ đồng tính Dakota Block ( Marley Shelton)… nhưng phải “chung tay” (và cả chân!) để trốn khỏi vùng Texas đầy rẫy những cái xác di động. Nguyên nhân là một loại vũ khí sinh học của chính phủ vô tình bị giải phóng ra ngoài không khí đã khiến những người dân thường bị biến đổi thành những zombie đi ăn thịt đồng loại. Những người còn sống sót vừa phải chiến đấu với xác sống vừa phải chống lại lực lượng quân đội vốn đã bị nhiễm bệnh nhưng nhờ hít một loại khí giải độc mà vẫn còn tồn tại.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rose McGowan","avatar":""},{"name":"Freddy Rodríguez","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Rebel Rodriguez","avatar":""},{"name":"Julio Oscar Mechoso","avatar":""},{"name":"Fergie","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Carlos Gallardo","avatar":""},{"name":"Tommy Nix","avatar":""},{"name":"Michael Parks","avatar":""},{"name":"Quentin Tarantino","avatar":""},{"name":"Elect","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8