INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khoc-liet', 'Cuộc Chiến Khốc Liệt', 'War', 'https://phimimg.com/upload/vod/20231026-1/76643b31e5a125e360c9fe57954c1133.jpg', 'https://phimimg.com/upload/vod/20231026-1/4c9ba8ac309d8d553786921b29d46c56.jpg', '<p>Sau bộ phim “The One” đã lâu lắm rồi chúng ta mới thấy hai ngôi sao phim hành động là Lý Liên Kiệt (Jet Li) và Jason Statham - người nổi tiếng với series phim “The Transporter”; đóng cặp với nhau. Trở lại với bộ phim “War”, ở lần tái ngộ này Jason Statham trong vai một điệp viên FBI phải truy tìm một tên sát thủ với biệt danh là “Rouge” do Lý Liên Kiệt đóng. Đây là kẻ đã sát hại đồng nghiệp của anh và Jason Statham quyết bắt “Rouge” phải trả giá cho những hành động của mình…</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jet Li","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"John Lone","avatar":""},{"name":"Devon Aoki","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"Ryo Ishibashi","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Andrea Roth","avatar":""},{"name":"Kenneth Choi","avatar":""},{"name":"Mathew St. Patrick","avatar":""},{"name":"Nadine Velazquez","avatar":""},{"name":"Terry Chen","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Steph Song","avatar":""},{"name":"Kennedy Montano","avatar":""},{"name":"Kane Kosugi","avatar":""},{"name":"Eric Keenleyside","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
