INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-khoc-liet', 'Cuộc Chiến Khốc Liệt', 'War', 'cuộc chiến khốc liệt war jet li jason statham john lone devon aoki luis guzmán saul rubinek ryo ishibashi sung kang andrea roth kenneth choi mathew st. patrick nadine velazquez terry chen mark cheng ho-nam steph song kennedy montano kane kosugi eric keenleyside lý liên kiệt ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-cua-shana-ban-dien-anh', 'Đôi Mắt Của Shana: Bản Điện Ảnh', 'Shakugan no Shana: The Movie', 'https://phimimg.com/upload/vod/20231023-1/03ae0527c664feb44e17a9ce6cf075ec.jpg', 'https://phimimg.com/upload/vod/20231023-1/ea3e9130f9c68fa08becfea8aeb06a89.jpg', '<p>Sakai Yuji - 1 cậu học sinh cao trung bình thường không có gì nổi bật. Cuộc sống của cậu vẫn êm đềm trôi qua như bao người khác. Và đó cũng chính là mong muốn duy nhất trong cuộc đời cậu. Thế nhưng mong muốn giản đơn ấy không thể thành hiện thực. Vào 1 ngày, trên đường đi học về thì bất chợt, cậu bị vướng vào 1 cuộc chiến kinh hoàng với những con quái vật chuyên hút sinh lực của loài người. Tưởng như cuộc đời chấm dứt, bỗng nhiên 1 cô gái với mái đỏ và đôi mắt rực lửa xuất hiện và giải cứu. Chưa kịp vui mừng, mà ngờ đâu, sự thật vẫn là sự thật. Cậu được biết rằng &quot;mình đã chết&quot;. Giờ đây chỉ là 1 thực thể trống rỗng, sẽ bị lãng quên dần theo thời gian. Liệu kết cuộc của Yuji sẽ ra sao khi sợi dây định mệnh đã gắn kết hai số phận, hai con người ở hai thế giới riêng biệt lại với nhau.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Mitsuo Iwata","avatar":""},{"name":"Tomo Sakurai","avatar":""},{"name":"Kimiko Koyama","avatar":""},{"name":"Hirofumi Nojima","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Masashi Ebara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
