INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-mat-cua-shana-ban-dien-anh', 'Đôi Mắt Của Shana: Bản Điện Ảnh', 'Shakugan no Shana: The Movie', 'đôi mắt của shana: bản điện ảnh shakugan no shana: the movie satoshi hino ayako kawasumi junichi suwabe mitsuo iwata tomo sakurai kimiko koyama hirofumi nojima rie kugimiya hitomi nabatame masashi ebara ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soc-sieu-quay', 'Sóc Siêu Quậy', 'Alvin and the Chipmunks', 'https://phimimg.com/upload/vod/20231023-1/581ae4ae3e62a767f4aaeefd44c43378.jpg', 'https://phimimg.com/upload/vod/20231023-1/3901d24cec1d57ada25461cc8f49528f.jpg', '<p>Ở một khu rừng toàn thông, có ba con sóc biết nói: Alvin, Simon và Theodore; không những thế, chúng còn hát rất hay. Một hôm, cây thông của chúng bị chặt mang vào thành phố, ba con sóc bắt đầu cuộc sống mới nơi đô thị với nhịp sống nhanh. Trong thành phố đó, có một chàng nhạc sĩ tên Dave. Anh rất yêu âm nhạc, nhưng những tác phẩm của anh không làm hài lòng ông chủ khó tính. Anh bị đuổi việc. Ba con sóc con sống ở trong nhà Dave, gây cho anh bao rắc rối phiền toái, nhưng cũng có bao niềm vui. Những chú sóc nhỏ hát bài hát của Dave, chúng trở nên nổi tiếng. Mọi chuyện rắc rối bắt đầu xảy ra...</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Lee","avatar":""},{"name":"David Cross","avatar":""},{"name":"Cameron Richardson","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Jesse McCartney","avatar":""},{"name":"Veronica Alicino","avatar":""},{"name":"Allison Karman","avatar":""},{"name":"Tiara Parker","avatar":""},{"name":"Kira Verrastro","avatar":""},{"name":"Beth Riesgraf","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Don Tiffany","avatar":""},{"name":"Frank Maharajh","avatar":""},{"name":"Kevin Symons","avatar":""},{"name":"Jayden Lund","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324487);
