INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('soc-sieu-quay', 'Sóc Siêu Quậy', 'Alvin and the Chipmunks', 'sóc siêu quậy alvin and the chipmunks jason lee david cross cameron richardson jane lynch justin long matthew gray gubler jesse mccartney veronica alicino allison karman tiara parker kira verrastro beth riesgraf adriane lenox don tiffany frank maharajh kevin symons jayden lund ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-shippden-cai-chet-tien-doan', 'Naruto Shippūden: Cái Chết Tiên Đoán', 'Naruto Shippuden the Movie', 'https://phimimg.com/upload/vod/20231019-1/ff9089c5f8f5f1306c71dbcfc7ffd368.jpg', 'https://phimimg.com/upload/vod/20231019-1/18eaaafc351e6c8da8a2d53c759257d3.jpg', '<p>Những con quỷ đã từng gần như phá hủy thế giới, được hồi sinh bởi một ai đó. Để ngăn chặn thế giới bị hủy diệt, con quỷ phải bị phong ấn và người duy nhất có thể làm điều đó là cô gái đền thờ Shion từ đất nước của quỷ, người có hai sức mạnh; Một người đang phong ấn quỷ và người kia dự đoán về cái chết của con người. Lần này, nhiệm vụ của Naruto là bảo vệ Shion, nhưng cô dự đoán cái chết của Naruto. Cách duy nhất để thoát khỏi nó, là tránh xa Shion, thứ sẽ khiến cô không được bảo vệ, sau đó là con quỷ, mục tiêu duy nhất là giết Shion sẽ làm như vậy, nghĩa là ngày tận thế. Naruto quyết định thách thức &quot;dự đoán về cái chết&quot; này.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Yōichi Masukawa","avatar":""},{"name":"Koichi Tochika","avatar":""},{"name":"Ayumi Fujimura","avatar":""},{"name":"Yoshinori Fujita","avatar":""},{"name":"Daisuke Kishio","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Masako Katsuki","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Hidetoshi Nak","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324487);
