INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-cau-vong', 'Mắt Cầu Vồng', 'Rainbow Eyes', 'https://phimimg.com/upload/vod/20240624-1/05c0522b51b4fd7bdeea41b0a4695b79.jpg', 'https://phimimg.com/upload/vod/20240624-1/d429e7c7adb527463bd1e553020f2bc4.jpg', '<p>Kyeong Joon và Eun Joo điều tra một vụ giết người ghê rợn mà nạn nhân là một doanh nhân giàu có, bị đâm hơn 20 nhát, máu loang lổ khắp nơi. Kẻ giết người đã cẩn thận không để lại bất kỳ bằng chứng buộc tội nào, nhưng một sợi tóc đã được tìm thấy. Cảnh sát có thể xác định rằng kẻ giết người là nam và có nhóm máu AB.</p><p>Không lâu sau đó tiếp tục xảy ra vụ giết người thứ hai. Các nạn nhân dường như không liên quan đến nhau, nhưng phương thức giết người lại giống hệt nhau. Khi cảnh sát nghiên cứu sâu hơn về thân thế của các nạn nhân, họ phát hiện ra rằng hai nạn nhân đều thuộc cùng một căn cứ quân sự từ nhiều năm trước. Một tháng trước khi xuất ngũ, họ được chuyển tới một căn cứ khác cùng với một người thứ ba tên Jay Bae. Cảnh sát tin rằng Jay Bae có thể là nạn nhân tiếp theo hoặc kẻ giết người. Cuộc điều tra của họ mới chỉ bắt đầu.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김강우","avatar":""},{"name":"김규리","avatar":""},{"name":"이수경","avatar":""},{"name":"박원상","avatar":""},{"name":"Jeon Chang-geol","avatar":""},{"name":"최덕문","avatar":""},{"name":"김성령","avatar":""},{"name":"김유정","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324487);
