INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-phan-1', 'Gã Điên (Phần 1)', 'Mad Men (Season 1)', 'https://phimimg.com/upload/vod/20240606-1/9b8fdf00dfefa4f659c20fa5e05ec5ee.jpg', 'https://phimimg.com/upload/vod/20240606-1/bd105e44ca18df9d83fcab3c29536a93.jpg', '<p>Phần một diễn ra từ tháng 3 đến tháng 11 năm 1960. Phim giới thiệu công ty quảng cáo hư cấu Sterling Cooper. Mùa giải bắt đầu với cô thư ký mới, Peggy Olson, bắt đầu ngày đầu tiên làm việc tại công ty. Khi mùa giải mở ra, câu chuyện cốt truyện bí ẩn của người đàn ông quảng cáo bí ẩn Don Draper được tiết lộ cũng như sự tự tin và thành công ngày càng tăng của Peggy Olson.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 19, 2007, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"January Jones","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Aaron Staton","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Kevin Rahm","avatar":""},{"name":"Christopher Stanley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
