INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-phan-3', 'Vượt Ngục (Phần 3)', 'Prison Break (Season 3)', 'https://phimimg.com/upload/vod/20240409-1/78608a8d24e29ca60a5f05afdd3c14e2.jpg', 'https://phimimg.com/upload/vod/20240409-1/0c7efad82138ba674ac2b4b8c76ff01f.jpg', '<p>Burrows nhanh chóng bắt liên lạc với Gretchen Morgan (thành viên Hội Đồng Hành). Gretchen chính là người đã bắt cóc LJ - con trai Burrows và cả Sara Tancredi - người con gái mà Michael yêu thương. Burrows được biết Hội Đồng Hành muốn giải thoát Scofield Whistler ra khỏi Sona. Trong season 3 này, Michael và Whistler sẽ xây dựng một kế hoạch để trốn thoát khỏi nhà tù mới. Michael tiếp tục rơi vào tình trạng khẩn trương cực độ trong khi Lincoln bận đối phó với một gián điệp của Hội Đồng Hành cũng chính là Gretchen Morgan. Sucre tìm được một công việc tại nhà tù để hỗ trợ Michael trong kế hoạch trốn thoát.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Wade Williams","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Marshall Allman","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Jodi Lyn O''keefe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324487);
