INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hotaru-tia-sang-trong-doi-phan-1', 'Hotaru: Tia Sáng Trong Đời (Phần 1)', 'Hotaru No Hikari: It''s Only A Little Light In My Life (Season 1)', 'https://phimimg.com/upload/vod/20240302-1/1c3d301374596b467dd1e41ff22534e7.jpg', 'https://phimimg.com/upload/vod/20240302-1/0f5ad969692ef5b736f866639911395a.jpg', '<p>Khi không làm công việc yêu thích, Hotaru chỉ muốn thư giãn ở nhà – cho đến khi con trai chủ nhà xuất hiện và đó không ai khác chính là vị sếp kỹ tính của cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayase Haruka","avatar":""},{"name":"Fujiki Naohito","avatar":""},{"name":"Kuninaka Ryoko","avatar":""},{"name":"Kato Kazuki","avatar":""},{"name":"Takeda Shinji","avatar":""},{"name":"Itaya Yuka","avatar":""},{"name":"Yasuda Ken","avatar":""},{"name":"Asami Reina","avatar":""},{"name":"Watabe Gota","avatar":""},{"name":"Shibue Joji","avatar":""},{"name":"Matsumoto Marika","avatar":""},{"name":"Matsushita Sara","avatar":""},{"name":"Maruyama Tomomi","avatar":""},{"name":"Matsunaga Hiroshi","avatar":""},{"name":"Mukai Osamu","avatar":""},{"name":"Kimura Tae","avatar":""},{"name":"Usuda","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
