INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hotaru-tia-sang-trong-doi-phan-1', 'Hotaru: Tia Sáng Trong Đời (Phần 1)', 'Hotaru No Hikari: It''s Only A Little Light In My Life (Season 1)', 'hotaru: tia sáng trong đời (phần 1) hotaru no hikari: it''s only a little light in my life (season 1) ayase haruka fujiki naohito kuninaka ryoko kato kazuki takeda shinji itaya yuka yasuda ken asami reina watabe gota shibue joji matsumoto marika matsushita sara maruyama tomomi matsunaga hiroshi mukai osamu kimura tae usuda ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('claymore', 'Claymore', 'Claymore', 'https://phimimg.com/upload/vod/20240302-1/2e83abd75a94e0b1d612f49fdee5fd67.jpg', 'https://phimimg.com/upload/vod/20240302-1/69f6a89a4cc8f1b3a9b661f0b53ef583.jpg', '<p>Yoma! Quái vật ăn phủ tạng con người. Chúng sống dưới lốt nạn nhân trà trộn vào thế giới loài người. Không ai hay cũng ko ai biết duy chỉ có Claymore - Những thiếu nữ mang trong mình máu thịt của loài quái vật sở hữu đôi mắt làm thành danh tiếng của họ. Phù Thủy Mắt Bạc! Những thiếu nữ mất đi hạnh phúc, mất đi tương lai và liệu Clare - Teresa có bảo vệ họ trước loài Awakened Beings hay với cái tên là loài Thức Tỉnh ...&nbsp;</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 17, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
