INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-khuat-cua-mat-trang', 'Vùng Khuất Của Mặt Trăng', 'In The Shadow Of The Moon', 'https://phimimg.com/upload/vod/20240227-1/625864f421c95e2ac718430f832a0c10.jpg', 'https://phimimg.com/upload/vod/20240227-1/f0ec57eccac1bcdc0c40eb7a41eb459d.jpg', '<p>Giữa năm 1968 và 1972, có 9 tàu vũ trụ của Mỹ đã du hành tới Mặt Trăng. Những phi hành gia trên tàu là những người duy nhất từng tới một thế giới khác. 11 phi hành gia từng tham gia chương trình Apollo, nay đã cao tuổi, mỗi người thuật lại chuyện xưa, về việc mình làm với những nỗi sợ, âu lo, can đảm và cả những mặc cảm. Cùng nhau họ nói lên ý nghĩ của mình về công tác, về vũ trụ, về trái đất, về những ước vọng... trên hết là ý thức về cố gắng và thành tựu của con người nói chung</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Carlson","avatar":""},{"name":"Buzz Aldrin","avatar":""},{"name":"Michael Collins","avatar":""},{"name":"Alan Bean","avatar":""},{"name":"Eugene Cernan","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324487);
