INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-long-co-quy', 'Trong Lòng Có Quỷ', 'The Matrimony', 'https://phimimg.com/upload/vod/20240227-1/af6e78bbaea44c9ae38c2beeb9133c68.jpg', 'https://phimimg.com/upload/vod/20240227-1/bd8921af669e166ba75c6c86a2942b59.jpg', '<p>Vào những năm 30 tại Thượng Hải, Thẩm Quân Sơ yêu sâu đậm cô bạn gái Từ Mạn Lệ, nhưng vì tính cách hướng nội nên không thể mở lời cầu hôn. Mạn Lệ vô cùng chán nản, bèn sáng tác một vở kịch truyền thanh. Trong vở kịch, nhiếp ảnh gia Quân Sơ mua một chiếc nhẫn và hẹn gặp Mạn Lệ, nhưng không may cô đã bị xe đụng chết khi đang trên đường đi gặp anh, Quân Sơ chìm đắm trong hối hận và nhớ nhung. Sau đó, Tam Tam, người rất yêu Quân Sơ, đã nhìn thấy Mạn Lệ cứ quanh quẩn xung quanh họ không chịu đi. Mạn Lệ đã dạy Tam Tam cách làm cho Quân Sơ vui… Vở kịch kết thúc, Quân Sơ hiểu được tâm ý của Mạn Lệ và đã viết một lá thư cầu hôn cô…</p>', 'Full', 1, 'single', 'completed', 19, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leon.Lai Ming","avatar":""},{"name":"Ren''e Liu","avatar":""},{"name":"Fan Bing Bing","avatar":""},{"name":"Xu Song Zi","avatar":""},{"name":"Zheng Yu Zhi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324487);
