INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-charlie-wilson', 'Cuộc Chiến Của Charlie Wilson', 'Charlie Wilson''s War', 'https://phimimg.com/upload/vod/20240227-1/ae2ad5731360e6c719f931226c283686.jpg', 'https://phimimg.com/upload/vod/20240227-1/f18f071baeb90a8dc28ac2335c757d64.jpg', '<p>Một bộ phim truyền hình dựa trên những giao dịch bí mật của Quốc hội Texas Charlie Wilson ở Afghanistan, nơi anh ta nỗ lực hỗ trợ phiến quân trong cuộc chiến với Liên Xô có một số hiệu ứng không lường trước và lâu dài.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324487);
