INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-hoan-hao-2007', 'Người Lạ Hoàn Hảo', 'Perfect Stranger', 'https://phimimg.com/upload/vod/20240227-1/8c8e44b3ba6c78812d5183a695b10040.jpg', 'https://phimimg.com/upload/vod/20240227-1/4e55839dea29c2fc94e92ff82843c77f.jpg', '<p>Một nhà báo bí mật chỉ ra doanh nhân Harrison Hill là kẻ giết bạn thân của cô. Đóng giả là một trong những kẻ hấp dẫn của anh ấy, cô ấy bước vào một trò chơi mèo vờn chuột trực tuyến.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Halle Berry","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Michael Tolan","avatar":""},{"name":"Richard Portnow","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
