INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-mau-hong', 'Cuộc Sống Màu Hồng', 'La Vie En Rose', 'https://phimimg.com/upload/vod/20240227-1/566f8f31653ae8d341bae70837986dbc.jpg', 'https://phimimg.com/upload/vod/20240227-1/0cc399b48515c21ee582e7b7d6922658.jpg', '<p>Một cái nhìn không theo thời gian về cuộc sống của Sparrow nhỏ, Édith Piaf (1915-1963). Mẹ cô là một ca sĩ có cồn, cha cô một người biểu diễn xiếc, bà ngoại của cô là một bà điên. Trong thời thơ ấu, cô sống với mỗi người trong số họ. Lúc 20 tuổi, cô là một ca sĩ trên đường phố được phát hiện bởi một chủ sở hữu câu lạc bộ đã bị sát hại, được huấn luyện bởi một nhạc sĩ mang cô đến phòng hòa nhạc, và sau đó nhanh chóng nổi tiếng. Những người bạn đồng hành là rượu và đau lòng. Những bi kịch của tình yêu của cô với Marcel Cerdan và cái chết của đứa con duy nhất của cô Belie lời nói của một trong những bài hát đặc trưng của cô, Non, Je Ne Recrette Rien. Bản chất qua lại và cốt truyện cho thấy các mô hình của bộ nhớ và hiệp hội.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324487);
