INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dua-dieu', 'Người Đua Diều', 'The Kite Runner', 'https://phimimg.com/upload/vod/20240220-1/49bfd280dba14c767239b30afe3978f4.jpg', 'https://phimimg.com/upload/vod/20240220-1/844d1733349a24a289987d7413f52345.jpg', '<p>Bộ phim kể về ba quảng thời gian quan trọng trong cuộc đời của nhân vật Amir, từ lúc cậu là cậu bé mê thả diều tại thành phố Kabul, Afghanistan cho đến khi trở thành một nhà văn nổi tiếng sinh sống tại San Francisco, Mỹ.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Khalid Abdalla","avatar":""},{"name":"Ahmad Khan Mahmoodzada","avatar":""},{"name":"Atossa Leoni","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
