INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-kiem', 'Cường Kiếm', 'Devil''s Disciple', 'https://phimimg.com/upload/vod/20240215-1/7a4c4565209676b79866d6cf243fdce9.jpg', 'https://phimimg.com/upload/vod/20240215-1/4d408f1a1726fe2738849bbd75cb140b.jpg', '<p>Phim kể về tiểu tử giang hồ Thành Phong và kẻ lạnh lùng kiêu ngạo Kinh Lỗi. Cả hai lần lượt được chọn vào Thánh Kiếm môn. Tà phái Huyết Ảnh giáo mới được khôi phục lại, giáo chủ mới là nữ ma đầu Mạc Vấn dẩn theo để tử đột kích Thánh Kiếm môn. Thành Phong bị trọng thương, và may mắn được bạn thân là Thủy Linh cứu sống. Chưởng môn Thánh Kiếm môn hứa gả con gái là Bắc Đường Tử Long cho Phong. Thật không may, trước ngày thành hôn, thân phận chị em song sinh của giáo chủ Mạc Vấn bị vạch trần...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 23, 2007, 'Lồng Tiếng', 'SD', 'Trung Quốc', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Trần Mẫn Chi","avatar":""},{"name":"Liêu Bích Nhi","avatar":""},{"name":"Dương Tư Kỳ","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324487);
