INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-quay-dam-mau', 'Góc Quay Đẫm Máu', 'Rec', 'https://phimimg.com/upload/vod/20240220-1/a21fbd64058ecd2ced488193d4e7da86.jpg', 'https://phimimg.com/upload/vod/20240220-1/0279b15c0284333c08ad963ba77ee0b2.jpg', '<p>Phim được bắt đầu bằng việc hai phóng viên theo chân một lính cứu hỏa để làm phóng sự về công việc gác đêm. Nhưng rồi họ bị kẹt lại tại một khu chung cư mà ở đó, người dân bị nhiễm căn bệnh dại luôn thèm khát máu tươi. Khu chung cư nhanh chóng trở thành mồ chôn sống của hai phóng viên nọ. Khán giả được theo dõi câu chuyện của họ thông qua những hình ảnh trong một chiếc camera cầm tay...</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Manuela Velasco","avatar":""},{"name":"Ferran Terraza","avatar":""},{"name":"Jorge-Yamam Serrano","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
