INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-den-xu-so-than-tien', 'Đường Đến Xứ Sở Thần Tiên', 'Bridge To Terabithia', 'https://phimimg.com/upload/vod/20240219-1/d56257d331b8cb1e31ccbd6ba7bd20bb.jpg', 'https://phimimg.com/upload/vod/20240219-1/a8e0c98518dfa0ed43fb05028bbaae76.jpg', '<p>Jesse Aaron có mơ ước trở thành một vận động viên điền kinh giỏi nhất trong lớp và có mâu thuẫn với Leslie Burke - nữ sinh vừa chuyển là một đối thủ đáng gờm trong môn điền kinh. Bất ngờ, họ phát hiện ra một vùng đất mới, một vùng đất của thần linh, một miền thiên đường tuyệt đẹp. Họ đặt cho nó cái tên là Terabithia và cùng nhau làm Vua và Hoàng Hậu của vùng đất này... Ở Terabithia, họ kết bạn và tình bạn của keo sơn, thuần khiết như chính vùng đất huyền thoại này.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hutcherson","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Zooey Deschanel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324487);
