INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-diet-vong-2007', 'Tín Hiệu Diệt Vong', 'The Signal', 'https://phimimg.com/upload/vod/20240207-1/15571f46eb849213acd258c789fde74e.jpg', 'https://phimimg.com/upload/vod/20240207-1/8b23f7175e7a52738d1fc7d9896e2cb5.jpg', '<p>Một bộ phim kinh dị được kể thành ba phần, từ ba góc nhìn, trong đó một đường truyền bí ẩn biến con người thành kẻ giết người xâm chiếm mọi điện thoại di động, radio và tivi.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anessa Ramsey","avatar":""},{"name":"Justin Welborn","avatar":""},{"name":"AJ Bowen","avatar":""},{"name":"Scott Poythress","avatar":""},{"name":"Sahr Ngaujah","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
