INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hannibal-troi-day', 'Hannibal Trỗi Dậy', 'Hannibal Rising', 'https://phimimg.com/upload/vod/20240207-1/3f4c1fa9ef814a9a0d0a327bdcbe8167.jpg', 'https://phimimg.com/upload/vod/20240207-1/b3d995fd5b7bce7ad7a829120599ea60.jpg', '<p>Mischa và Hannibal, em trai và em gái, không thể tách rời; Đó là tình yêu của họ dành cho nhau mà liên kết trái phiếu của họ. Đồng hành của họ là ràng buộc mãi mãi, cho đến khi, với gia đình của họ, trong khi trốn khỏi cỗ máy chiến tranh Nazi, một tập hợp hoàn cảnh xoắn, tốc độ của một cuộc tấn công luẩn quẩn nhất trong tương lai của một bài giảng tiếng Hannibal cho sự báo thù của người đụ vào sự giết chóc tàn bạo của bé chị gái. Nhiều năm sau, chúng tôi tìm thấy Hannibal, thiếu niên, thành lập ở Paris và sống với dì Lady Murasaki Shikibu và học tại trường y ở đây anh ấy tìm thấy sở trường của mình. Vẫn đang tìm kiếm những kẻ giết người của em gái mình, vẫn cay đắng và vẫn hy vọng thỏa mãn mong muốn về quả báo của mình. Cơ hội này đến, và chẳng mấy chốc chúng ta sẽ học được rằng với một pound thịt bị mất một pound thịt phải được hoàn trả. Đây là câu chuyện kinh hoàng của công lý và danh dự, những cơn đau đang phát triển của một chàng trai trẻ sẽ có tội với việc trả tiền với nhiều hơn là xác thịt và xương. Đây là câu chuyện về và tăng của Hannibal trẻ, cầu nguyện bạn không gặp anh ta, vì thịt bạn sẽ đến với anh ta. Nếm cơn thịnh nộ của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324487);
