INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-chan-toi-ac', 'Ngăn Chặn Tội Ác', 'The Air I Breathe', 'https://phimimg.com/upload/vod/20240207-1/e4590025074f6d3c74a1c4c473ffea39.jpg', 'https://phimimg.com/upload/vod/20240207-1/2acdb885344fce8ec39ba83b992e2c5d.jpg', '<p>Một vị thương gia đặt cược cuộc sống của mình dựa vào những con ngựa đua, một tay găng tơ có thể nhìn thấy được tương lai, một ngôi sao ca nhạc trở thành con mồi của một tay trùm tội phạm và một vị bác sĩ chạy đua với thời gian để cứu lấy tình yêu của cuộc đời mình. Những câu chuyện được lồng ghép khéo léo trong bộ phim tượng trưng cho những cảm xúc cơ bản của con người trong cuộc sống bao gồm vui sướng, giận dữ, yêu thương và ghét bỏ...</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Andy Garcia","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324487);
