INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-dan-ong', 'Thành Phố Đàn Ông', 'City Of Men', 'https://phimimg.com/upload/vod/20240207-1/ffb1f02eaaca93251c55a7117e623339.jpg', 'https://phimimg.com/upload/vod/20240207-1/d99b6e0e1acea50390841d9145eb0f5d.jpg', '<p>Những người bạn thân nhất Acerola và Laranjinha, sắp bước sang tuổi 18, khám phá ra những điều về quá khứ của người cha đã mất tích của họ, điều sẽ làm tan vỡ tình bạn vững chắc của họ, giữa cuộc chiến giữa các băng đảng ma túy đối thủ từ các khu ổ chuột của Rio.</p>', 'Full', 1, 'single', 'completed', 35, 2007, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Douglas Silva","avatar":""},{"name":"Darlan Cunha","avatar":""},{"name":"Jonathan Haagensen","avatar":""},{"name":"Rodrigo dos Santos","avatar":""},{"name":"Fábio Lago","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
