INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-bau-2007', 'Dính Bầu', 'Juno', 'https://phimimg.com/upload/vod/20240205-1/eba5ac4f835676e5d0c52cb718cc2868.jpg', 'https://phimimg.com/upload/vod/20240205-1/2d1b67a0e88009923f6a39bdadaa37d4.jpg', '<p>Một câu chuyện kể trong bốn mùa, bắt đầu vào mùa thu khi Juno, một thiếu niên trường trung học 16 tuổi ở Minnesota, phát hiện ra cô đang mang thai sau một sự kiện trên ghế với người bạn thân nhất của mình, Bleeker. Trong phòng chờ của một phòng khám phá thai, Juno kỳ quặc và sắc sảo, Juno sẽ quyết định sinh con và đặt đứa trẻ bằng một cặp vợ chồng nuôi. Cô tìm thấy một trong những người trên Pennysaver, liên lạc với họ, nói với cha và mẹ kế của cô, và mang đi học. Các phụ huynh được chọn, yupscale cao cấp (một trong số họ mát mẻ và thoải mái, sự tỉ mỉ và tăng nhẹ), gặp Juno, ký giấy, và năm mở ra. Kế hoạch của Juno sẽ làm việc, cô ấy có thể ứng biến, và về Bleeker thì sao?</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324487);
