INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-long-hanh', 'Ác Quỷ Lộng Hành', 'Beowulf', 'https://phimimg.com/upload/vod/20240205-1/4426a7c5dac4f9d4ef548ed253cb9284.jpg', 'https://phimimg.com/upload/vod/20240205-1/bda025901d92be987300df2da0b5159b.jpg', '<p>Beowulf là một bộ phim hành động, phiêu lưu chuyển thể từ một bài thơ Anh cổ về chàng dũng sĩ huyền thoại Beowulf, người có nhiệm vụ cao cả là giết chết tên khổng lồ hung bạo Grendel. Mẹ của Grendel tìm cách cám dỗ Beowulf với mục đích soán ngôi dũng sĩ đoạt quyền trị vì vương quốc...</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Winstone","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Angelina Jolie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324487);
