INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-goi-cam', 'Đặc Vụ Gợi Cảm', 'Zero Uman R: Keishichou 0-ka No Onna Yokubou No Daishou', 'https://phimimg.com/upload/vod/20240228-1/b4506a99fd5571c2981c66660099a7ef.jpg', 'https://phimimg.com/upload/vod/20240228-1/2d8c47abfac8bf0149799c9cb555b1b3.jpg', '<p>Một nữ điệp viên bí ẩn được tuyển dụng để thâm nhập vào thế giới ngầm Nhật Bản và thu thập bằng chứng cho một chi nhánh bí mật của Sở Cảnh sát Tokyo.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sasa Handa","avatar":""},{"name":"Hiromitsu Kiba","avatar":""},{"name":"Atsuko Miura","avatar":""},{"name":"Masaki Miura","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324487);
