INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('i-think-i-love-my-wife', 'I Think I Love My Wife', 'I Think I Love My Wife', 'https://phimimg.com/upload/vod/20240205-1/a72b36f937d52b65e84f61905a8ca515.jpg', 'https://phimimg.com/upload/vod/20240205-1/9caedc45d60ee55bd4f524b1889e609f.jpg', '<p>Richard Cooper là một người đàn ông đã có gia đình và là cha của hai đứa trẻ, người chỉ cảm thấy nhàm chán với cuộc sống hôn nhân. Không nhận được bất kỳ quan hệ tình dục nào từ vợ, anh ta tìm đến những người phụ nữ ngẫu nhiên trên phố, đến mức anh ta ăn trưa muộn để nhìn họ. Khi người yêu cũ Nikki Tru đến văn phòng của anh ấy để lấy thư giới thiệu, cô ấy bị ám ảnh bởi Cooper và họ bắt đầu một mối quan hệ phức tạp.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Rock","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Gina Torres","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Edward Herrmann","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324487);
