INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bang-dang-2007', 'Cuộc Chiến Băng Đảng', 'Smokin'' Aces', 'https://phimimg.com/upload/vod/20240219-1/5352689691d3c86767ceed49151dc71e.jpg', 'https://phimimg.com/upload/vod/20240219-1/ec4da430a57f36c90b58c90aa16b23a2.jpg', '<p>Sau tất cả những tội ác của tay trùm Primo Sparazza gây ra, cảnh sát chỉ trông chờ tìm thấy một bằng chứng thuyết phục để tống cổ tên khốn vào nhà đá. Nhưng mọi tội ác đều được gột rửa không một chút dấu vết. Buddy “Aces” Israel, kẻ được mệnh danh là Thần Bài vời các màn biểu diễn điệu nghệ tại các sòng bạc vùng Lake Jahoe, Neveda, từng là tay thân tín nhất của Sparazza. Những ngày gần đây, tên Buddy ngày càng trở nên chướng mắt. Trong những cuộc điện thoại, cảnh sát được biết Sparazza sẵn sàng trả một triệu đô cho tên côn đồ nào muốn phanh thây tên khốn Buddie. Chỉ đợi có thế, cảnh sát lập tức nhập cuộc với chương trình “Bảo Vệ Nhân Chứng” của FBI…</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Joseph Ruskin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
