INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cargo-200', 'Cargo 200', 'Груз 200', 'https://phimimg.com/upload/vod/20240128-1/2b23dea946c02b7883038a94fd6516dc.jpg', 'https://phimimg.com/upload/vod/20240128-1/a5778e4c289511dc2749b268276648dc.jpg', '<p>Khi trở về Leningrad sau chuyến thăm anh trai, xe của Giáo sư Artyom bị hỏng và ông tìm sự trợ giúp tại một trang trại biệt lập do Alexey, vợ ông, một lao động Việt Nam và một người lạ lang thang quanh trang trại ở. Khi chiếc xe của anh ấy được sửa chữa xong, Artyom rời đi trong tình trạng say xỉn, còn các học sinh Valera và Angelika đến. Sau khi Valera say xỉn, kẻ lạ mặt bắt cóc Angelika.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Agniya Kuznetsova","avatar":""},{"name":"Aleksey Poluyan","avatar":""},{"name":"Leonid Gromov","avatar":""},{"name":"Aleksey Serebryakov","avatar":""},{"name":"Leonid Bichevin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
