INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boy-a', 'Boy A', 'Boy A', 'https://phimimg.com/upload/vod/20240128-1/66813cc57f58a0c7f2e7773f155befe2.jpg', 'https://phimimg.com/upload/vod/20240128-1/ae62dd2336dc1b204179e9e3fad239a3.jpg', '<p>Nội dung phim kể về một thanh niên sau khi ra tù được đưa vào nhân thân mới, dưới sự giám sát của người giám hộ. Được giúp đỡ bởi người giám sát, người mà anh ta xem như cha, anh ta tìm được công việc và bạn bè. Anh đã sống tốt, trở thành tấm gương cho mọi người xung quanh, nhưng lỗi lầm thời niên thiếu vẫn ám ảnh, rồi đột ngột quay lại thật trớ trêu đúng lúc anh biến thành người hùng của thị trấn.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Katie Lyons","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Shaun Evans","avatar":""},{"name":"Siobhan Finneran","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
