INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-tu-hinh', 'Án Tử Hình', 'Death Sentence', 'https://phimimg.com/upload/vod/20240128-1/dbab8fb03639907e5582371461092e59.jpg', 'https://phimimg.com/upload/vod/20240128-1/824138db12b23f1833a0e5f5d0937dfd.jpg', '<p>Nick Hume - một doanh nhân điềm đạm có một cuộc sống được cho là hoàn hảo bên người vợ xinh đẹp Helen và cậu con trai ngoan ngoãn Lucas. Vô tình trở thành nhân chứng của một vụ án của nhóm tội phạm dính líu tới các quan chức cao cấp của chính phủ, Nick đặt cả gia đình vào thế bị đe dọa tính mạng. Con đường duy nhất của Nick là phải sẵn sàng bảo vệ những người thân bằng bạo lực, thậm chí phải trả giá bằng máu...</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Kelly Preston","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
