INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-tiec-tinh-yeu', 'Dạ Tiệc Tình Yêu', 'Feast Of Love', 'https://phimimg.com/upload/vod/20240128-1/2824dda1b59b2d46bb94045ab829fe44.jpg', 'https://phimimg.com/upload/vod/20240128-1/df92496e0addf3be829dbaa84204bca9.jpg', '<p>Dạ Tiệc Tình Yêu - Feast of Love là một bộ phim truyền hình Mỹ 2007 của đạo diễn Robert Benton. Một nhóm người sống ở ngoại ô Oregon bị thay đổi quan điểm sống khi một cô gái xinh đẹp Chloe (Alexa Davalos) chuyển đến. Ở chính nơi đây hàng loạt những rắc rối về tình yêu, tình dục. Họ xen lẫn vào nhau thành một câu chuyện mà trong đó không có ai trốn thoát được sự cám dỗ, mê hoặc, hạnh phúc và đau thương của tình yêu. Liệu sự xuất hiện của Chloe sẽ cảnh tỉnh tất cả?</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Alexa Davalos","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
