INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('evangelion-10-you-are-not-alone', 'Evangelion: 1.0 You Are (Not) Alone', 'Evangelion Shin Gekijouban: Jo, Rebuild Of Evangelion: 1.0 You Are (Not) Alone, Evangelion: 1.01 You Are (Not) Alone, Evangelion: 1.11 You Are (Not) Alone', 'https://phimimg.com/upload/vod/20240126-1/248b434792dedea3735cf7441a2593f2.jpg', 'https://phimimg.com/upload/vod/20240126-1/84d468e7127e881eb4e078ebff7feee0.jpg', '<p>Sau lần va chạm thứ hai, tất cả những gì còn lại của Nhật Bản là Tokyo-3, một thành phố đang bị tấn công bởi những sinh vật khổng lồ tìm cách diệt trừ loài người, được gọi là Angels. Sau hơn tám năm không gặp cha mình, Shinji Ikari nhận được một cuộc điện thoại, trong đó anh được yêu cầu khẩn cấp đến Trụ sở NERV, một tổ chức chuyên giải quyết việc tiêu diệt các Thiên thần thông qua việc sử dụng các mech khổng lồ gọi là Evas. Mục tiêu của Shinji là lái chiếc Eva Unit 01 trong khi hợp tác với phi công Eva Unit 00, Ayanami Rei.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324487);
