INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-chet-choc', 'Khu Rừng Chết Chóc', 'Forest Of Death', 'null', 'https://phimimg.com/upload/vod/20240126-1/e41cf86b12070735510d3f86b2f99a35.jpg', '<p>Trong một khu rừng bí ẩn ở Thái Lan, nhiều thanh niên tự tử biến mất và các đội cứu hộ dù có la bàn cũng không thể tìm ra lối thoát. Cô phóng viên đầy tham vọng May đang làm báo chí giật gân khám phá những cái chết trong rừng. Bạn trai của cô và nhà thực vật học Shun Shu-hoi đang phát triển một phương tiện giao tiếp với thực vật. Trong khi đó, thám tử C. C. Ha đang điều tra vụ cưỡng hiếp và cái chết của một phụ nữ và nghi phạm chính là Patrick Wong.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Fanny Shu","avatar":""},{"name":"Hsu Chi","avatar":""},{"name":"Shu Kei","avatar":""},{"name":"Caihua Li","avatar":""},{"name":"Chow","avatar":""},{"name":"Lawrence","avatar":""},{"name":"Lau Siu Ming","avatar":""},{"name":"Ruan Min An","avatar":""},{"name":"Suet Lam","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324487);
