INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sword-of-the-stranger', 'Sword Of The Stranger', 'Sword Of The Stranger', 'https://phimimg.com/upload/vod/20240123-1/802d8c6c2cf97f4f243b61d0e5b70e36.jpg', 'https://phimimg.com/upload/vod/20240123-1/5f2f5707da52c14cedd9d648b7a5602c.jpg', '<p>Một cậu bé và con chó của anh ta thấy mục tiêu của Ming: một triều đại nước ngoài sẽ dừng lại ở không có gì. Một ngày nọ, một chiến binh yên tĩnh và long trọng vượt qua con đường của họ, và trở nên kết nối không thể cưỡng lại với hai người. Một thỏa thuận bị tấn công và chiến binh đồng ý đưa cậu bé đến một ngôi chùa ở xa, Phật giáo, nơi một tu sĩ tốt bụng đang chờ đợi để chăm sóc anh ta và con chó. Thật không may, Ming đã gửi Elite của họ, và họ sẽ kiểm tra sức mạnh, lòng can đảm và chất lượng mỗi bước của con đường.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324487);
