INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-khung-dien', 'Thám Tử Khùng Điên', 'Mad Detective', 'https://phimimg.com/upload/vod/20240122-1/f6c2ed2627b94debfabff7c8083565b9.jpg', 'https://phimimg.com/upload/vod/20240122-1/fd27e1673e102891bdd56773e0b73d9f.jpg', '<p>Bun, một cựu thanh tra cảnh sát bị tâm thần phân liệt đã nghỉ hưu để giúp một thám tử tân binh giải quyết một vụ án giết người phức tạp liên quan đến một đồng nghiệp mất tích và một cảnh sát bị nghi ngờ mắc chứng rối loạn đa nhân cách.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Andy On","avatar":""},{"name":"Gordon Lam","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Lee Kwok-Lun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
