INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-chevalier', 'Khách Sạn Chevalier', 'Hotel Chevalier', 'https://phimimg.com/upload/vod/20240122-1/23b536c45a8aa517bba1a6d5b74f1192.jpg', 'https://phimimg.com/upload/vod/20240122-1/1771c538c359ba621f723869d7b4a3ce.jpg', '<p>Trong phòng khách sạn ở Paris, Jack Whitman nằm trên giường. Điện thoại của anh đổ chuông; đó là một người phụ nữ đang trên đường đến gặp anh ấy, thật bất ngờ. Cô ấy đến và những rắc rối trong mối quan hệ của họ xuất hiện từng chút một. Họ sẽ làm tình chứ? Mối quan hệ của họ đã kết thúc chưa? (Phần tiền truyện của The Darjeeling Limited, 2007.)</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Schwartzman","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Waris Ahluwalia","avatar":""},{"name":"Michel Castejon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
