INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('closure', 'Closure', 'Closure', 'https://phimimg.com/upload/vod/20240121-1/aeb2d86d629e8b2ea1c0a8dda6c5179b.jpg', 'https://phimimg.com/upload/vod/20240121-1/4acd00f8beeed881e0af40d3ef0f03a6.jpg', '<p>Có sự ăn ý ngay lập tức giữa Alice (Gillian Anderson), một nữ doanh nhân và Adam (Danny Dyer), một người đàn ông thuộc tầng lớp lao động trẻ tuổi, người lắp đặt hệ thống an ninh trong căn hộ của cô ở London. Cô đưa anh đến một bữa tiệc ở quê, và cuối cùng họ đã làm tình. Nhưng màn đêm trở nên kinh hoàng khi họ chạm trán với ba tên côn đồ đang tấn công Adam và *** Alice. Vụ việc biến họ thành những người ẩn dật đáng sợ cho đến khi Alice phát hiện ra thủ lĩnh của những kẻ tấn công họ (Anthony Calf) – và hai nạn nhân lên kế hoạch trả thù tàn bạo.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Dyer","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Adam Rayner","avatar":""},{"name":"Antony Byrne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
