INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-do', 'Ranh Giới Đỏ', 'Redline', 'https://phimimg.com/upload/vod/20240121-1/16cb41e55802fc933366016cf8d340d9.jpg', 'https://phimimg.com/upload/vod/20240121-1/273ad447037c34be0cf22c05161d0f64.jpg', '<p>Một người đam mê ô tô trẻ tuổi tuyệt đẹp - và là người đứng đầu ban nhạc không tên nổi tiếng nhất ở bờ biển phía Tây - thấy mình bị cuốn vào các cuộc thi đua xe kéo bất hợp pháp được tổ chức bởi những người cuồng xe kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathan Phillips","avatar":""},{"name":"Nadia Bjorlin","avatar":""},{"name":"Eddie Griffin","avatar":""},{"name":"Tim Matheson","avatar":""},{"name":"Jesse Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324487);
