INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-lan-va-canh-buom', 'Chuông Lặn Và Cánh Bướm', 'The Diving Bell And The Butterfly', 'https://phimimg.com/upload/vod/20240111-1/c5ac4c7294292844724885204eef2123.jpg', 'https://phimimg.com/upload/vod/20240111-1/5cca3f472593fabd4b0fb4061c95af42.jpg', '<p>Phim Chuông Lặn Và Cánh Bướm là câu chuyện có thật của Jean-Dominique Bauby, bạn bè thường gọi là Jean-Do, chủ bút hào hoa phong nhã của tờ nguyệt san thời trang Elle nổi tiếng thế giới. Và rồi, một ngày nọ, ông bị đột quỵ, chỉ trừ mắt trái vẫn còn cử động. Tuy toàn thân bất động nhưng trong đầu óc của Jean-Do vẫn còn minh mẫn, tỉnh táo. Cuộc đời của Jean-Do tưởng chừng như phải kết thúc tại đây với cái chết nhưng thế giới xung quanh, bạn bè đã giúp ông vượt qua những tháng ngày khó khăn... Bộ phim là tiếng nói khát vọng sống của con người trong mọi hoàn cảnh, là sự sẻ chia gắn bó của con người với con người dù họ ở bất cứ hoàn cảnh nào.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Mathieu Amalric","avatar":""},{"name":"Emmanuelle Seigner","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Anne Consigny","avatar":""},{"name":"Patrick Chesnais","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
