INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuong-lan-va-canh-buom', 'Chuông Lặn Và Cánh Bướm', 'The Diving Bell And The Butterfly', 'chuông lặn và cánh bướm the diving bell and the butterfly mathieu amalric emmanuelle seigner marie-josée croze anne consigny patrick chesnais ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-tang-toc', 'Khu Rừng Tang Tóc', 'The Mourning Forest', 'https://phimimg.com/upload/vod/20240111-1/e4cc43966f2834237f826f2893cb684c.jpg', 'https://phimimg.com/upload/vod/20240111-1/320adbb0aca81d2a66b4d058f9f2cd23.jpg', '<p>Phim kể câu chuyện về một y tá (do Machiko Ono thủ vai), người đang vô cùng đau buồn và tuyệt vọng vì sự ra đi đột ngột của đứa con mà cô rất yêu thương. Cô đan làm việc tại một viện an dưỡng và một trong những bệnh nhân của cô là một người đàn ông lớn tuổi (Shigeki Uda). Ông ta mắc phải căn bệnh sa sút trí tuệ, vì một lí do nào đó mà ông đang tìm kiếm trong rừng địa phương để có cái gì đó kết nối với người vợ đã chết mà anh không thể giải thích. Cô đưa ông đến một nơi nhưng hai người bị mắc kẹt trong một khu rừng, nơi họ bắt tay vào một cuộc hành trình kéo dài hai ngày. Shigeki sống trong một nhà nhỏ về hưu. Anh cảm thấy thoải mái và vui vẻ ở đây với các cư dân khác và nhân viên bệnh viện nhẹ nhàng và chu đáo. Machiko, một trong những nhân viên của viện dưỡng lão chú ý đặc biệt đến anh ta. Tuy nhiên, cô bị ám ảnh bởi sự mất mát của đứa con. Sau khi chào mừng sinh nhật của Shigeki, Machiko quyết định đưa anh ta lái xe ở nông thôn. Đi dọc theo các tuyến đường đẹp, chiếc xe bị buộc vào một cái mương và ở đây họ bắt tay vào cuộc hành trình khám phá cùng nhau. Khi Shigeki quyết tâm đi vào rừng, Machiko không còn cách nào khác hơn là đi theo. Sau hai ngày miệt mài đi qua rừng cây dày đặc cuối cùng họ cũng đến ngôi mộ của vợ ông Shigeki. Đó là nơi yên bình mà Machiko phát hiện ra rằng Shigeki đã viết thư cho người vợ yêu quý của mình trong 33 năm. Đã đến lúc anh ta viết thư cuối cùng. Machito tận tụy ở đó để giúp anh ta kết thúc sự thương tiếc, và làm như vậy sẽ tìm thấy sự bình an trong lòng cô.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Machiko Ono","avatar":""},{"name":"Shigeki Uda","avatar":""},{"name":"Makiko Watanabe","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
