INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-den-tam-linh', 'Đường Đến Tâm Linh', 'The Darjeeling Limited', 'https://phimimg.com/upload/vod/20240104-1/9e0be8ff5f20cf49264d32c9458025b6.jpg', 'https://phimimg.com/upload/vod/20240104-1/3da9738052daee1a04d8b2f8ea319710.jpg', '<p>Đường đến Tâm Linh - The Darjeeling Limited là một bộ phim hài năm 2007 của đạo diễn Wes Anderson. Những người thân bị ly gián Francis (Owen Wilson), Peter (Adrien Brody) và Jack (Jason Schwartzman) được tái hợp và tham gia một chuyến xe lửa trên khắp Ấn Độ. Họ đã không nói chuyện với nhau trong hơn một năm kể từ khi cha qua đời. Francis đang hồi phục sau một tai nạn xe gắn máy, Peter không thể đối mặt với thời kỳ mang thai của vợ mình và Jack không thể kết thúc với người yêu cũ. Mục đích của cuộc tái ngộ này là gì? Điều gì còn gắn kết giữa họ?</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Jason Schwartzman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
