INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('not-nhac-tinh-yeu', 'Nốt Nhạc Tình Yêu', 'Music And Lyrics', 'https://phimimg.com/upload/vod/20240104-1/bfbe6a321b9f829179bfa5da13548377.jpg', 'https://phimimg.com/upload/vod/20240104-1/8ee3f39c9fcd61d162fa53d28f9801e5.jpg', '<p>Là một ca sĩ đã qua thời hoàng kim, Alex mừng rỡ khi có cơ hội đánh bóng lại tên tuổi khi được đề nghị viết một ca khúc để thu âm với một nữ ca sĩ nổi tiếng khác. Điều khó khăn là trước nay Alex không hề biết tí gì về việc viết lời hay nhạc cả. Để làm việc, Alex chấp nhận hợp tác với Sophie, một phụ nữ nổi tiếng là khó khăn trong việc làm chung. &nbsp;Dần dà, tình cảm đã nảy sinh giữa hai người như một điều tất yếu.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Toni Trucks","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Haley Bennett","avatar":""},{"name":"Brooke Tansley","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Zak Orth","avatar":""},{"name":"Scott Porter","avatar":""},{"name":"Nick Bacon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324487);
