INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-su-tu-noi-gian', 'Khi Sư Tử Nổi Giận', 'Lions For Lambs', 'https://phimimg.com/upload/vod/20240104-1/7057564972e7cb5c65bebde44dd18a2c.jpg', 'https://phimimg.com/upload/vod/20240104-1/ce48293c953414fd60a241c9b4a6975b.jpg', '<p>Bộ phim kể về câu chuyện của ba nhân vật: một giáo sư theo chủ nghĩa duy tâm đang nỗ lực truyền cảm hứng cho một sinh viên được hưởng nhiều đặc ân; một cựu sinh viên bị thương trong cuộc chiến tại Afghanistan và một nghị sỹ quốc hội có mối liên hệ mật thiết với người phóng viên dày dạn kinh nghiệm đã tiết lộ rất nhiều về con người thật của mình… Tom Cruise, Meryl Streep và Robert Redford cùng đảm nhiệm những vai diễn chính trong bộ phim này.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Robert Redford","avatar":""},{"name":"Tom Cruise","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Andrew Garfield","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
