INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hitman-x47-ke-san-nguoi', 'Hitman X47: Kẻ Săn Người', 'Hitman', 'https://phimimg.com/upload/vod/20240103-1/21d4bf041504aca0b37a52719164181f.jpg', 'https://phimimg.com/upload/vod/20240103-1/bf42de7d6f5d995c3c9d2fb3aff9dd52.jpg', '<p>Hitman mô tả về các hoạt động ám sát của sát thủ mang biệt danh 47 - kẻ “được huấn luyện trở thành một sát thủ chuyên nghiệp đánh thuê, với vũ khí mạnh nhất là thần kinh thép và niềm tin - lòng tự hào tuyệt đối vào nghiệp ám sát của bản thân. Cái tên 47 bắt nguồn từ hai chữ số cuối cùng trên dãy mã vạch được xăm vào sau gáy của anh”. Kẻ đi săn mang tên 47 trở thành đối tượng bị săn đuổi trên khắp Đông Âu bởi cả Interpol lẫn quân đội Nga sau khi bị phát hiện dính líu vào một cuộc binh biến chính trị. 47 giờ đây phải tìm cách chạy trốn, đồng thời tìm hiểu kẻ giật dây đạo diễn toàn bộ sự việc, và lý do chúng làm điều đó. Nhưng mối nguy lớn nhất đối với tính mạng của 47 không phải là các hành động của anh, mà là một cô gái xinh đẹp...</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothy Olyphant","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Olga Kurylenko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
