INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-boi-ban', 'Nàng Bồi Bàn', 'Waitress', 'https://phimimg.com/upload/vod/20240108-1/70c301f2172a06d05f4838caba30ca53.jpg', 'https://phimimg.com/upload/vod/20240108-1/f2b88b079378d2959101f01b964dd773.jpg', '<p>Cô hầu bàn Jenna (Keri Russell) được khách hàng tại Quán ăn Joe’s biết đến như một đầu bếp nướng bánh “xinh nhất” ở thị trấn nhỏ này. Từ bao lâu nay, cuộc sống của Jenna chỉ quanh quẩn ở bếp ăn, với công việc hầu bàn tẻ nhạt, chưa kể một ông chồng độc đoán, vô trách nhiệm. Với hy vọng thắng giải thưởng 25.000$ tại cuộc thi nướng bánh, Jenna tin mình có thể đổi đời. Nhưng ngay lúc đó, Jenna ngỡ ngàng khi biết mình đã có thai và những dự tính tương lai xem như rối bời hết cả. Những băn khoăn và lo lắng của một bà mẹ trẻ khiến Jenna hoàn toàn lung lạc. Có nên giữ lại đứa trẻ khi cô và chồng mình đã không còn tình cảm gì với nhau? Tạo hoá khéo trêu ngươi, cùng lúc ấy, chàng bác sĩ trẻ điển trai Pomatter (Nathan Fillion) vừa chuyển đến thị trấn lại chính là…bác sĩ hộ sinh cho Jenna. Nhưng ngay từ phút đầu gặp mặt, cả hai đều cảm thấy trái tim đập loạn nhịp vì nhau; và trong sâu thẳm những ước mơ thầm kín nhất, Jenna biết mình vẫn còn biết yêu thương, và hy vọng.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keri Russell","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Andy Griffith","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324487);
