INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-voi-thu-thach-4', 'Đương Đầu Với Thử Thách 4', 'Live Free Or Die Hard', 'https://phimimg.com/upload/vod/20240108-1/ffbe2cc23b385a642eab89d78f6b9d1e.jpg', 'https://phimimg.com/upload/vod/20240108-1/407b90ccfed2b89ea9385d43601edf05.jpg', '<p>Một nhóm tin tặc âm mưu đưa nước Mỹ trở lại thời tiền sử bằng cách đánh sập tất cả mạng máy tính vào ngày quốc khánh. Mọi thứ trong kế hoạch hành động của chúng sẽ hoàn hảo nếu không có sự can thiệp của John McClane.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Timothy Olyphant","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
