INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-suong-mu-2007', 'Quái Vật Sương Mù', 'The Mist', 'https://phimimg.com/upload/vod/20240108-1/70e5e59847cae7b3f452d2ef1750ba80.jpg', 'https://phimimg.com/upload/vod/20240108-1/679c39301905086289aedf80cf91ac44.jpg', '<p>Sau khi cơn bão tàn khốc càn quét một thị trấn nhỏ, người dân ở đó nhận ra một màn sương tà ác đang bao phủ quê nhà của họ và giết chết bất cứ ai còn ở bên ngoài.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Laurie Holden","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Jeffrey DeMunn","avatar":""},{"name":"Frances Sternhagen","avatar":""},{"name":"Nathan Gamble","avatar":""},{"name":"Alexa Davalos","avatar":""},{"name":"Chris Owen","avatar":""},{"name":"Sam Witwer","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324487);
