INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wedded-worried-wearied', 'Wedded, Worried, Wearied', 'Wedded, Worried, Wearied', 'https://phimimg.com/upload/vod/20240108-1/6dfda1883859e14de53fdfe53df67d40.jpg', 'https://phimimg.com/upload/vod/20240108-1/4619512ce1c5848415ba042aad1e8a3d.jpg', '<p>Jed và Angie để con ở nhà rồi đi nghỉ tuần trăng mật đã trì hoãn từ lâu. Thế nhưng những bà mẹ hay cãi cọ của họ lại quyết định trở thành bảo mẫu cho đứa trẻ, dẫn đến bao hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Judy Ann Santos","avatar":""},{"name":"Ryan Agoncillo","avatar":""},{"name":"Gina Pareño","avatar":""},{"name":"Gloria Diaz","avatar":""},{"name":"Derek Ramsay","avatar":""},{"name":"Ariel Ureta","avatar":""},{"name":"Dominic Ochoa","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Tuesday Vargas","avatar":""},{"name":"Gerard Pizzaras","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324487);
