INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-elizabeth-de-nhat-thoi-dai-hoang-kim', 'Nữ Hoàng Elizabeth Đệ Nhất: Thời Đại Hoàng Kim', 'Elizabeth: The Golden Age', 'https://phimimg.com/upload/vod/20231231-1/1b391f066b085a605b68a3fa5e483ffb.jpg', 'https://phimimg.com/upload/vod/20231231-1/522941b7f4742eb2ac521406086870e6.jpg', '<p>Tiếp theo bộ phim Elizabeth (1998) kể về quá trình lên ngôi của nữ hoàng Anh Elizabeth I, bộ phim Elizabeth: The Golden Age (Nữ hoàng Elizabeth: Thời đại hoàng kim 2007) được xem là phần 2, với ê kíp thực hiện chính đã tham gia từ phần 1. Trong phần 2, khán giả sẽ được quay về với bối cảnh châu Âu vào thời kỳ cuối thế kỷ 16, khi diễn biến chính trị, xã hội và chiến tranh ngày một phức tạp và đỉnh điểm là cuộc chiến tranh giữa 2 đế quốc Anh và Tây Ban Nha. Đã có một cuộc viễn chinh của một người phụ nữ nhằm chế ngự tình yêu, sự đe dọa của kẻ thù và lòng tôn kính của thần dân ở vương quốc bà trị vì. Đó chính là Nữ hoàng của vương quốc Anh - Elizabeth đệ nhất, người được mệnh danh là Woman Warrior Queen - Nữ Hoàng Chiến Binh. Một Nữ hoàng Elizabeth trưởng thành chịu đựng nhiều cuộc khủng hoảng vào cuối triều đại của bà bao gồm các mưu đồ của tòa án, một âm mưu ám sát, Armada (Hạm đội) Tây Ban Nha và những thất vọng về cuộc tình lãng mạn...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Laurence Fox","avatar":""},{"name":"Tom Hollander","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324487);
