INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-hoang-elizabeth-de-nhat-thoi-dai-hoang-kim', 'Nữ Hoàng Elizabeth Đệ Nhất: Thời Đại Hoàng Kim', 'Elizabeth: The Golden Age', 'nữ hoàng elizabeth đệ nhất: thời đại hoàng kim elizabeth: the golden age cate blanchett clive owen geoffrey rush laurence fox tom hollander ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dau-2-ke-dung-cuoi-cung', 'Quyết Đấu 2: Kẻ Đứng Cuối Cùng', 'Undisputed II: Last Man Standing', 'https://phimimg.com/upload/vod/20240102-1/ea26d06ea2118832370d2d1b50fb34ba.jpg', 'https://phimimg.com/upload/vod/20240102-1/566d40209cf04b57440506256daa6d92.jpg', '<p>Nhà vô địch quyền anh Chambers bị bắt giam trong một nhà tù ở Nga và anh bị bắt buộc phải tham gia các trận đấm bốc đầy bạo lực. Không một luật lệ nào ràng buộc giữa các trận đấu, thắng thua được quyết định bằng sự sống và cái chết, với những khả năng và kinh nghiệm quyền anh của mình, Chambers phải đối mặt với những tên võ sĩ to lớn và bạo lực...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Ben Cross","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324487);
